INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(1, '1 Chronicles', 13, 1, 1, ' آدم ، شيت ، أنوش '),
(2, '1 Chronicles', 13, 1, 2, ' قينان ، مهللئيل ، يارد '),
(3, '1 Chronicles', 13, 1, 3, ' أخنوخ ، متوشالح ، لامك '),
(4, '1 Chronicles', 13, 1, 4, ' نوح ، سام ، حام ، يافث '),
(5, '1 Chronicles', 13, 1, 5, ' بنو يافث : جومر وماجوج وماداي وياوان وتوبال وماشك وتيراس '),
(6, '1 Chronicles', 13, 1, 6, ' وبنو جومر : أشكناز وريفاث وتوجرمة '),
(7, '1 Chronicles', 13, 1, 7, ' وبنو ياوان : أليشة وترشيشة وكتيم ودودانيم '),
(8, '1 Chronicles', 13, 1, 8, ' بنو حام : كوش ومصرايم وفوط وكنعان '),
(9, '1 Chronicles', 13, 1, 9, ' وبنو كوش : سبا وحويلة وسبتا ورعما وسبتكا . وبنو رعما : شبا وددان '),
(10, '1 Chronicles', 13, 1, 10, ' وكوش ولد نمرود الذي ابتدأ يكون جبارا في الأرض '),
(11, '1 Chronicles', 13, 1, 11, ' ومصرايم ولد : لوديم وعناميم ولهابيم ونفتوحيم '),
(12, '1 Chronicles', 13, 1, 12, ' وفتروسيم وكسلوحيم ، الذين خرج منهم فلشتيم وكفتوريم '),
(13, '1 Chronicles', 13, 1, 13, ' وكنعان ولد : صيدون بكره ، وحثا '),
(14, '1 Chronicles', 13, 1, 14, ' واليبوسي والأموري والجرجاشي '),
(15, '1 Chronicles', 13, 1, 15, ' والحوي والعرقي والسيني '),
(16, '1 Chronicles', 13, 1, 16, ' والأروادي والصماري والحماثي '),
(17, '1 Chronicles', 13, 1, 17, ' بنو سام : عيلام وأشور وأرفكشاد ولود وأرام وعوص وحول وجاثر وماشك '),
(18, '1 Chronicles', 13, 1, 18, ' وأرفكشاد ولد شالح ، وشالح ولد عابر '),
(19, '1 Chronicles', 13, 1, 19, ' ولعابر ولد ابنان اسم الواحد فالج ، لأن في أيامه قسمت الأرض . واسم أخيه يقطان '),
(20, '1 Chronicles', 13, 1, 20, ' ويقطان ولد : ألموداد وشالف وحضرموت ويارح '),
(21, '1 Chronicles', 13, 1, 21, ' وهدورام وأوزال ودقلة '),
(22, '1 Chronicles', 13, 1, 22, ' وعيبال وأبيمايل وشبا '),
(23, '1 Chronicles', 13, 1, 23, ' وأوفير وحويلة ويوباب . كل هؤلاء بنو يقطان '),
(24, '1 Chronicles', 13, 1, 24, ' سام ، أرفكشاد ، شالح '),
(25, '1 Chronicles', 13, 1, 25, ' عابر ، فالج ، رعو '),
(26, '1 Chronicles', 13, 1, 26, ' سروج ، ناحور ، تارح '),
(27, '1 Chronicles', 13, 1, 27, ' أبرام ، وهو إبراهيم '),
(28, '1 Chronicles', 13, 1, 28, ' ابنا إبراهيم : إسحاق وإسماعيل '),
(29, '1 Chronicles', 13, 1, 29, ' هذه مواليدهم . بكر إسماعيل : نبايوت ، وقيدار وأدبئيل ومبسام '),
(30, '1 Chronicles', 13, 1, 30, ' ومشماع ودومة ومسا وحدد وتيماء '),
(31, '1 Chronicles', 13, 1, 31, ' ويطور ونافيش وقدمة . هؤلاء هم بنو إسماعيل '),
(32, '1 Chronicles', 13, 1, 32, ' وأما بنو قطورة سرية إبراهيم ، فإنها ولدت : زمران ويقشان ومدان ومديان ويشباق وشوحا . وابنا يقشان : شبا وددان '),
(33, '1 Chronicles', 13, 1, 33, ' وبنو مديان : عيفة وعفر وحنوك وأبيداع وألدعة . فكل هؤلاء بنو قطورة '),
(34, '1 Chronicles', 13, 1, 34, ' وولد إبراهيم إسحاق . وابنا إسحاق : عيسو وإسرائيل '),
(35, '1 Chronicles', 13, 1, 35, ' بنو عيسو : أليفاز ورعوئيل ويعوش ويعلام وقورح '),
(36, '1 Chronicles', 13, 1, 36, ' بنو أليفاز : تيمان وأومار وصفي وجعثام وقناز وتمناع وعماليق '),
(37, '1 Chronicles', 13, 1, 37, ' بنو رعوئيل : نحث وزارح وشمة ومزة '),
(38, '1 Chronicles', 13, 1, 38, ' وبنو سعير : لوطان وشوبال وصبعون وعنى وديشون وإيصر وديشان '),
(39, '1 Chronicles', 13, 1, 39, ' وابنا لوطان : حوري وهومام . وأخت لوطان : تمناع '),
(40, '1 Chronicles', 13, 1, 40, ' بنو شوبال : عليان ومناحة وعيبال وشفي وأونام . وابنا صبعون : أية وعنى . 41ابن عنى : ديشون ، وبنو ديشون : حمران وأشبان ويثران وكران '),
(41, '1 Chronicles', 13, 1, 42, ' بنو إيصر : بلهان وزعوان ويعقان . وابنا ديشان : عوص وأران '),
(42, '1 Chronicles', 13, 1, 43, ' هؤلاء هم الملوك الذين ملكوا في أرض أدوم قبلما ملك ملك لبني إسرائيل : بالع بن بعور . واسم مدينته دنهابة '),
(43, '1 Chronicles', 13, 1, 44, ' ومات بالع فملك مكانه يوباب بن زارح من بصرة '),
(44, '1 Chronicles', 13, 1, 45, ' ومات يوباب فملك مكانه حوشام من أرض التيماني '),
(45, '1 Chronicles', 13, 1, 46, ' ومات حوشام فملك مكانه هدد بن بدد الذي كسر مديان في بلاد موآب ، واسم مدينته عويت '),
(46, '1 Chronicles', 13, 1, 47, ' ومات هدد فملك مكانه سملة من مسريقة '),
(47, '1 Chronicles', 13, 1, 48, ' ومات سملة فملك مكانه شاول من رحوبوت النهر '),
(48, '1 Chronicles', 13, 1, 49, ' ومات شاول فملك مكانه بعل حانان بن عكبور '),
(49, '1 Chronicles', 13, 1, 50, ' ومات بعل حانان فملك مكانه هدد ، واسم مدينته فاعي ، واسم امرأته مهيطبئيل بنت مطرد بنت ماء ذهب '),
(50, '1 Chronicles', 13, 1, 51, ' ومات هدد . فكانت أمراء أدوم : أمير تمناع ، أمير علوة ، أمير يتيت '),
(51, '1 Chronicles', 13, 1, 52, ' أمير أهوليبامة ، أمير أيلة ، أمير فينون '),
(52, '1 Chronicles', 13, 1, 53, ' أمير قناز ، أمير تيمان ، أمير مبصار '),
(53, '1 Chronicles', 13, 1, 54, ' أمير مجديئيل ، أمير عيرام . هؤلاء أمراء أدوم '),
(54, '1 Chronicles', 13, 2, 1, ' هؤلاء بنو إسرائيل : رأوبين ، شمعون ، لاوي ويهوذا ، يساكر وزبولون '),
(55, '1 Chronicles', 13, 2, 2, ' دان ، يوسف وبنيامين ، نفتالي ، جاد وأشير '),
(56, '1 Chronicles', 13, 2, 3, ' بنو يهوذا : عير وأونان وشيلة . ولد الثلاثة من بنت شوع الكنعانية . وكان عير بكر يهوذا شريرا في عيني الرب فأماته '),
(57, '1 Chronicles', 13, 2, 4, ' وثامار كنته ولدت له فارص وزارح . كل بني يهوذا خمسة '),
(58, '1 Chronicles', 13, 2, 5, ' ابنا فارص : حصرون وحامول '),
(59, '1 Chronicles', 13, 2, 6, ' وبنو زارح : زمري وأيثان وهيمان وكلكول ودارع . الجميع خمسة '),
(60, '1 Chronicles', 13, 2, 7, ' وابن كرمي : عخار مكدر إسرائيل الذي خان في الحرام '),
(61, '1 Chronicles', 13, 2, 8, ' وابن أيثان : عزريا '),
(62, '1 Chronicles', 13, 2, 9, ' وبنو حصرون الذين ولدوا له : يرحمئيل ورام وكلوباي '),
(63, '1 Chronicles', 13, 2, 10, ' ورام ولد عميناداب ، وعميناداب ولد نحشون رئيس بني يهوذا '),
(64, '1 Chronicles', 13, 2, 11, ' ونحشون ولد سلمو ، وسلمو ولد بوعز '),
(65, '1 Chronicles', 13, 2, 12, ' وبوعز ولد عوبيد ، وعوبيد ولد يسى '),
(66, '1 Chronicles', 13, 2, 13, ' ويسى ولد : بكره أليآب ، وأبيناداب الثاني ، وشمعى الثالث '),
(67, '1 Chronicles', 13, 2, 14, ' ونثنئيل الرابع ، ورداي الخامس '),
(68, '1 Chronicles', 13, 2, 15, ' وأوصم السادس ، وداود السابع '),
(69, '1 Chronicles', 13, 2, 16, ' وأختاهم صروية وأبيجايل . وبنو صروية : أبشاي ويوآب وعسائيل ، ثلاثة '),
(70, '1 Chronicles', 13, 2, 17, ' وأبيجايل ولدت عماسا ، وأبو عماسا يثر الإسماعيلي '),
(71, '1 Chronicles', 13, 2, 18, ' وكالب بن حصرون ولد من عزوبة امرأته ومن يريعوث . وهؤلاء بنوها : ياشر وشوباب وأردون '),
(72, '1 Chronicles', 13, 2, 19, ' وماتت عزوبة فاتخذ كالب لنفسه أفرات ، فولدت له حور '),
(73, '1 Chronicles', 13, 2, 20, ' وحور ولد أوري ، وأوري ولد بصلئيل '),
(74, '1 Chronicles', 13, 2, 21, ' وبعد دخل حصرون على بنت ماكير أبي جلعاد واتخذها ، وهو ابن ستين سنة ، فولدت له سجوب '),
(75, '1 Chronicles', 13, 2, 22, ' وسجوب ولد يائير ، وكان له ثلاث وعشرون مدينة في أرض جلعاد '),
(76, '1 Chronicles', 13, 2, 23, ' وأخذ جشور وأرام حووث يائير منهم مع قناة وقراها ، ستين مدينة . كل هؤلاء بنو ماكير أبي جلعاد '),
(77, '1 Chronicles', 13, 2, 24, ' وبعد وفاة حصرون في كالب أفراتة ، ولدت له أبياه امرأة حصرون أشحور أبا تقوع '),
(78, '1 Chronicles', 13, 2, 25, ' وكان بنو يرحمئيل بكر حصرون : البكر رام ، ثم بونة وأورن وأوصم وأخيا '),
(79, '1 Chronicles', 13, 2, 26, ' وكانت امرأة أخرى ليرحمئيل اسمها عطارة . هي أم أونام '),
(80, '1 Chronicles', 13, 2, 27, ' وكان بنو رام بكر يرحمئيل : معص ويمين وعاقر '),
(81, '1 Chronicles', 13, 2, 28, ' وكان ابنا أونام : شماي وياداع . وابنا شماي : ناداب وأبيشور '),
(82, '1 Chronicles', 13, 2, 29, ' واسم امرأة أبيشور أبيحايل ، وولدت له أحبان وموليد '),
(83, '1 Chronicles', 13, 2, 30, ' وابنا ناداب : سلد وأفايم . ومات سلد بلا بنين '),
(84, '1 Chronicles', 13, 2, 31, ' وابن أفايم يشعي ، وابن يشعي شيشان ، وابن شيشان أحلاي '),
(85, '1 Chronicles', 13, 2, 32, ' وابنا ياداع أخي شماي : يثر ويوناثان . ومات يثر بلا بنين '),
(86, '1 Chronicles', 13, 8, 30, ' وابنه البكر عبدون ، ثم صور وقيس وبعل وناداب '),
(87, '1 Chronicles', 13, 8, 31, ' وجدور وأخيو وزاكر '),
(88, '1 Chronicles', 13, 8, 32, ' ومقلوث ولد شماة . وهم أيضا مع إخوتهم سكنوا في أورشليم مقابل إخوتهم '),
(89, '1 Chronicles', 13, 8, 33, ' ونير ولد قيس ، وقيس ولد شاول ، وشاول ولد يهوناثان وملكيشوع وأبيناداب وإشبعل '),
(90, '1 Chronicles', 13, 8, 34, ' وابن يهوناثان : مريببعل ، ومريببعل ولد ميخا '),
(91, '1 Chronicles', 13, 8, 35, ' وبنو ميخا : فيثون ومالك وتاريع وآحاز '),
(92, '1 Chronicles', 13, 8, 36, ' وآحاز ولد يهوعدة ، ويهوعدة ولد علمث وعزموت وزمري . وزمري ولد موصا '),
(93, '1 Chronicles', 13, 8, 37, ' وموصا ولد بنعة ، ورافة ابنه ، وألعاسة ابنه ، وآصيل ابنه '),
(94, '1 Chronicles', 13, 8, 38, ' ولآصيل ستة بنين وهذه أسماؤهم : عزريقام وبكرو وإسماعيل وشعريا وعوبديا وحانان . كل هؤلاء بنو آصيل '),
(95, '1 Chronicles', 13, 8, 39, ' وبنو عاشق أخيه : أولام بكره ، ويعوش الثاني ، وأليفلط الثالث '),
(96, '1 Chronicles', 13, 8, 40, ' وكان بنو أولام رجالا جبابرة بأس يغرقون في القسي ، كثيري البنين وبني البنين مئة وخمسين . كل هؤلاء من بني بنيامين '),
(97, '1 Chronicles', 13, 9, 1, ' وانتسب كل إسرائيل ، وها هم مكتوبون في سفر ملوك إسرائيل . وسبي يهوذا إلى بابل لأجل خيانتهم '),
(98, '1 Chronicles', 13, 9, 2, ' والسكان الأولون في ملكهم ومدنهم هم إسرائيل الكهنة واللاويون والنثينيم '),
(99, '1 Chronicles', 13, 9, 3, ' وسكن في أورشليم من بني يهوذا ، وبني بنيامين ، وبني أفرايم ومنسى '),
(100, '1 Chronicles', 13, 9, 4, ' عوثاي بن عميهود بن عمري بن إمري بنباني ، من بني فارص بن يهوذا '),
(101, '1 Chronicles', 13, 9, 5, ' ومن الشيلونيين : عسايا البكر وبنوه '),
(102, '1 Chronicles', 13, 9, 6, ' ومن بني زارح : يعوئيل وإخوتهم ست مئة وتسعون '),
(103, '1 Chronicles', 13, 9, 7, ' ومن بني بنيامين : سلو بن مشلام بن هودويا بن هسنوأة '),
(104, '1 Chronicles', 13, 9, 8, ' ويبنيا بن يروحام ، وأيلة بن عزي بن مكري ، ومشلام بن شفطيا بن رعوئيل بن يبنيا '),
(105, '1 Chronicles', 13, 9, 9, ' وإخوتهم حسب مواليدهم تسع مئة وستة وخمسون . كل هؤلاء الرجال رؤوس آباء لبيوت آبائهم '),
(106, '1 Chronicles', 13, 9, 10, ' ومن الكهنة : يدعيا ويهوياريب وياكين '),
(107, '1 Chronicles', 13, 9, 11, ' وعزريا بن حلقيا بن مشلام بن صادوق بن مرايوث بن أخيطوب رئيس بيت الله '),
(108, '1 Chronicles', 13, 9, 12, ' وعدايا بن يروحام بن فشحور بن ملكيا ، ومعساي بن عديئيل بن يحزيرة بن مشلام بن مشليميت بن إمير '),
(109, '1 Chronicles', 13, 9, 13, ' وإخوتهم رؤوس بيوت آبائهم ألف وسبع مئة وستون جبابرة بأس لعمل خدمة بيت الله '),
(110, '1 Chronicles', 13, 9, 14, ' ومن اللاويين : شمعيا بن حشوب بن عزريقام بن حشبيا من بني مراري '),
(111, '1 Chronicles', 13, 9, 15, ' وبقبقر وحرش وجلال ومتنيا بن ميخا بن زكري بن آساف '),
(112, '1 Chronicles', 13, 9, 16, ' وعوبديا بن شمعيا بن جلال بن يدوثون ، وبرخيا بن آسا بن ألقانة الساكن في قرى النطوفاتيين '),
(113, '1 Chronicles', 13, 9, 17, ' والبوابون : شلوم وعقوب وطلمون وأخيمان وإخوتهم . شلوم الرأس '),
(114, '1 Chronicles', 13, 9, 18, ' وحتى الآن هم في باب الملك إلى الشرق . هم البوابون لفرق بني لاوي '),
(115, '1 Chronicles', 13, 9, 19, ' وشلوم بن قوري بن أبيأساف بن قورح وإخوته لبيوت آبائه . القورحيون على عمل الخدمة حراس أبواب الخيمة ، وآباؤهم على محلة الرب حراس المدخل '),
(116, '1 Chronicles', 13, 9, 20, ' وفينحاس بن ألعازار كان رئيسا عليهم سابقا ، والرب معه '),
(117, '1 Chronicles', 13, 9, 21, ' وزكريا بن مشلميا كان بواب باب خيمة الاجتماع '),
(118, '1 Chronicles', 13, 9, 22, ' جميع هؤلاء المنتخبين بوابين للأبواب مئتان واثنا عشر ، وقد انتسبوا حسب قراهم . أقامهم داود وصموئيل الرائي على وظائفهم '),
(119, '1 Chronicles', 13, 9, 23, ' وكانوا هم وبنوهم على أبواب بيت الرب بيت الخيمة للحراسة '),
(120, '1 Chronicles', 13, 9, 24, ' في الجهات الأربع كان البوابون ، في الشرق والغرب والشمال والجنوب '),
(121, '1 Chronicles', 13, 9, 25, ' وكان إخوتهم في قراهم للمجيء معهم في السبعة الأيام ، حينا بعد حين '),
(122, '1 Chronicles', 13, 9, 26, ' لأنه بالوظيفة رؤساء البوابين هؤلاء الأربعة هم لاويون وكانوا على المخادع وعلى خزائن بيت الله '),
(123, '1 Chronicles', 13, 9, 27, ' ونزلوا حول بيت الله لأن عليهم الحراسة ، وعليهم الفتح كل صباح '),
(124, '1 Chronicles', 13, 9, 28, ' وبعضهم على آنية الخدمة ، لأنهم كانوا يدخلونها بعدد ، ويخرجونها بعدد '),
(125, '1 Chronicles', 13, 9, 29, ' وبعضهم اؤتمنوا على الآنية وعلى كل أمتعة القدس وعلى الدقيق والخمر واللبان والأطياب '),
(126, '1 Chronicles', 13, 9, 30, ' والبعض من بني الكهنة كانوا يركبون دهون الأطياب '),
(127, '1 Chronicles', 13, 9, 31, ' ومتثيا واحد من اللاويين ، وهو بكر شلوم القورحي ، بالوظيفة على عمل المطبوخات '),
(128, '1 Chronicles', 13, 9, 32, ' والبعض من بني القهاتيين من إخوتهم على خبز الوجوه ليهيئوه في كل سبت '),
(129, '1 Chronicles', 13, 9, 33, ' فهؤلاء هم المغنون رؤوس آباء اللاويين في المخادع ، وهم معفون ، لأنه نهارا وليلا عليهم العمل '),
(130, '1 Chronicles', 13, 9, 34, ' هؤلاء رؤوس آباء اللاويين . حسب مواليدهم رؤوس . هؤلاء سكنوا في أورشليم '),
(131, '1 Chronicles', 13, 9, 35, ' وفي جبعون سكن أبو جبعون يعوئيل ، واسم امرأته معكة '),
(132, '1 Chronicles', 13, 9, 36, ' وابنه البكر عبدون ثم صور وقيس وبعل ونير وناداب '),
(133, '1 Chronicles', 13, 9, 37, ' وجدور وأخيو وزكريا ومقلوث '),
(134, '1 Chronicles', 13, 9, 38, ' ومقلوث ولد شمآم . وهم أيضا سكنوا مقابل إخوتهم في أورشليم مع إخوتهم '),
(135, '1 Chronicles', 13, 9, 39, ' ونير ولد قيس ، وقيس ولد شاول ، وشاول ولد : يهوناثان : وملكيشوع وأبيناداب وإشبعل '),
(136, '1 Chronicles', 13, 9, 40, ' وابن يهوناثان مريببعل ، ومريببعل ولد ميخا '),
(137, '1 Chronicles', 13, 9, 41, ' وبنو ميخا : فيثون ومالك وتحريع وآحاز '),
(138, '1 Chronicles', 13, 9, 42, ' وآحاز ولد يعرة ، ويعرة ولد علمث وعزموت وزمري . وزمري ولد موصا '),
(139, '1 Chronicles', 13, 9, 43, ' وموصا ولد ينعا ، ورفايا ابنه ، وألعسة ابنه ، وآصيل ابنه '),
(140, '1 Chronicles', 13, 9, 44, ' وكان لآصيل ستة بنين وهذه أسماؤهم : عزريقام وبكرو ثم إسماعيل وشعريا وعوبديا وحانان . هؤلاء بنو آصيل '),
(141, '1 Chronicles', 13, 10, 1, ' وحارب الفلسطينيون إسرائيل ، فهرب رجال إسرائيل من أمام الفلسطينيين وسقطوا قتلى في جبل جلبوع '),
(142, '1 Chronicles', 13, 10, 2, ' وشد الفلسطينيون وراء شاول ووراء بنيه ، وضرب الفلسطينيون يوناثان وأبيناداب وملكيشوع أبناء شاول '),
(143, '1 Chronicles', 13, 10, 3, ' واشتدت الحرب على شاول ، فأصابته رماة القسي ، فانجرح من الرماة '),
(144, '1 Chronicles', 13, 10, 4, ' فقال شاول لحامل سلاحه : استل سيفك واطعني به لئلا يأتي هؤلاء الغلف ويقبحوني . فلم يشأ حامل سلاحه لأنه خاف جدا . فأخذ شاول السيف وسقط عليه '),
(145, '1 Chronicles', 13, 10, 5, ' فلما رأى حامل سلاحه أنه قد مات شاول ، سقط هو أيضا على السيف ومات '),
(146, '1 Chronicles', 13, 10, 6, ' فمات شاول وبنوه الثلاثة وكل بيته ، ماتوا معا '),
(147, '1 Chronicles', 13, 10, 7, ' ولما رأى جميع رجال إسرائيل الذين في الوادي أنهم قد هربوا ، وأن شاول وبنيه قد ماتوا ، تركوا مدنهم وهربوا ، فأتى الفلسطينيون وسكنوا بها '),
(148, '1 Chronicles', 13, 10, 8, ' وفي الغد لما جاء الفلسطينيون ليعروا القتلى ، وجدوا شاول وبنيه ساقطين في جبل جلبوع '),
(149, '1 Chronicles', 13, 10, 9, ' فعروه وأخذوا رأسه وسلاحه ، وأرسلوا إلى أرض الفلسطينيين في كل ناحية لأجل تبشير أصنامهم والشعب '),
(150, '1 Chronicles', 13, 10, 10, ' ووضعوا سلاحه في بيت آلهتهم ، وسمروا رأسه في بيت داجون '),
(151, '1 Chronicles', 13, 10, 11, ' ولما سمع كل يابيش جلعاد بكل ما فعل الفلسطينيون بشاول '),
(152, '1 Chronicles', 13, 10, 12, ' قام كل ذي بأس وأخذوا جثة شاول وجثث بنيه وجاءوا بها إلى يابيش ، ودفنوا عظامهم تحت البطمة في يابيش ، وصاموا سبعة أيام '),
(153, '1 Chronicles', 13, 10, 13, ' فمات شاول بخيانته التي بها خان الرب من أجل كلام الرب الذي لم يحفظه . وأيضا لأجل طلبه إلى الجان للسؤال '),
(154, '1 Chronicles', 13, 10, 14, ' ولم يسأل من الرب ، فأماته وحول المملكة إلى داود بن يسى '),
(155, '1 Chronicles', 13, 11, 1, ' واجتمع كل رجال إسرائيل إلى داود في حبرون قائلين : هوذا عظمك ولحمك نحن '),
(156, '1 Chronicles', 13, 11, 2, ' ومنذ أمس وما قبله حين كان شاول ملكا كنت أنت تخرج وتدخل إسرائيل ، وقد قال لك الرب إلهك : أنت ترعى شعبي إسرائيل وأنت تكون رئيسا لشعبي إسرائيل '),
(157, '1 Chronicles', 13, 11, 3, ' وجاء جميع شيوخ إسرائيل إلى الملك إلى حبرون ، فقطع داود معهم عهدا في حبرون أمام الرب ، ومسحوا داود ملكا على إسرائيل حسب كلام الرب عن يد صموئيل '),
(158, '1 Chronicles', 13, 11, 4, ' وذهب داود وكل إسرائيل إلى أورشليم ، أي يبوس . وهناك اليبوسيون سكان الأرض '),
(159, '1 Chronicles', 13, 2, 33, ' وابنا يوناثان : فالت وزازا . هؤلاء هم بنو يرحمئيل '),
(160, '1 Chronicles', 13, 2, 34, ' ولم يكن لشيشان بنون بل بنات . وكان لشيشان عبد مصري اسمه يرحع '),
(161, '1 Chronicles', 13, 2, 35, ' فأعطى شيشان ابنته ليرحع عبده امرأة ، فولدت له عتاي '),
(162, '1 Chronicles', 13, 2, 36, ' وعتاي ولد ناثان ، وناثان ولد زاباد '),
(163, '1 Chronicles', 13, 2, 37, ' وزاباد ولد أفلال ، وأفلال ولد عوبيد '),
(164, '1 Chronicles', 13, 2, 38, ' وعوبيد ولد ياهو ، وياهو ولد عزريا '),
(165, '1 Chronicles', 13, 2, 39, ' وعزريا ولد حالص ، وحالص ولد إلعاسة '),
(166, '1 Chronicles', 13, 2, 40, ' وإلعاسة ولد سسماي ، وسسماي ولد شلوم '),
(167, '1 Chronicles', 13, 2, 41, ' وشلوم ولد يقمية ، ويقمية ولد أليشمع '),
(168, '1 Chronicles', 13, 2, 42, ' وبنو كالب أخي يرحمئيل : ميشاع بكره . هو أبو زيف . وبنو مريشة أبي حبرون '),
(169, '1 Chronicles', 13, 2, 43, ' وبنو حبرون : قورح وتفوح وراقم وشامع '),
(170, '1 Chronicles', 13, 2, 44, ' وشامع ولد راقم أبا يرقعام . وراقم ولد شماي '),
(171, '1 Chronicles', 13, 2, 45, ' وابن شماي معون ، ومعون أبو بيت صور '),
(172, '1 Chronicles', 13, 2, 46, ' وعيفة سرية كالب ولدت : حاران وموصا وجازيز . وحاران ولد جازيز '),
(173, '1 Chronicles', 13, 2, 47, ' وبنو يهداي : رجم ويوثام وجيشان وفلط وعيفة وشاعف '),
(174, '1 Chronicles', 13, 2, 48, ' وأما معكة سرية كالب فولدت : شبر وترحنة '),
(175, '1 Chronicles', 13, 2, 49, ' وولدت شاعف أبا مدمنة ، وشوا أبا مكبينا وأبا جبعا . وبنت كالب عكسة '),
(176, '1 Chronicles', 13, 2, 50, ' هؤلاء هم بنو كالب بن حور بكر أفراتة : شوبال أبو قرية يعاريم '),
(177, '1 Chronicles', 13, 2, 51, ' وسلما أبو بيت لحم ، وحاريف أبو بيت جادير '),
(178, '1 Chronicles', 13, 2, 52, ' وكان لشوبال أبي قرية يعاريم بنون : هرواه وحصي همنوحوت '),
(179, '1 Chronicles', 13, 2, 53, ' وعشائر قرية يعاريم : اليثري والفوتي والشماتي والمشراعي . من هؤلاء خرج الصرعي والأشتأولي '),
(180, '1 Chronicles', 13, 2, 54, ' بنو سلما : بيت لحم والنطوفاتي وعطروت بيت يوآب وحصي المنوحي الصرعي '),
(181, '1 Chronicles', 13, 2, 55, ' وعشائر الكتبة سكان يعبيص : ترعاتيم وشمعاتيم وسوكاتيم . هم القينيون الخارجون من حمة أبي بيت ركاب '),
(182, '1 Chronicles', 13, 3, 1, ' وهؤلاء هم بنو داود الذين ولدوا له في حبرون : البكر أمنون من أخينوعم اليزرعيلية . الثاني دانيئيل من أبيجايل الكرملية '),
(183, '1 Chronicles', 13, 3, 2, ' الثالث أبشالوم ابن معكة بنت تلماي ملك جشور . الرابع أدونيا ابن حجيث '),
(184, '1 Chronicles', 13, 3, 3, ' الخامس شفطيا من أبيطال . السادس يثرعام من عجلة امرأته '),
(185, '1 Chronicles', 13, 3, 4, ' ولد له ستة في حبرون . وملك هناك سبع سنين وستة أشهر ، ثم ملك ثلاثا وثلاثين سنة في أورشليم '),
(186, '1 Chronicles', 13, 3, 5, ' وهؤلاء ولدوا له في أورشليم : شمعى وشوباب وناثان وسليمان . أربعة من بثشوع بنت عميئيل '),
(187, '1 Chronicles', 13, 3, 6, ' ويبحار وأليشامع وأليفالط '),
(188, '1 Chronicles', 13, 3, 7, ' ونوجه ونافج ويافيع '),
(189, '1 Chronicles', 13, 3, 8, ' وأليشمع وألياداع وأليفلط . تسعة '),
(190, '1 Chronicles', 13, 3, 9, ' الكل بنو داود ما عدا بني السراري . وثامار هي أختهم '),
(191, '1 Chronicles', 13, 3, 10, ' وابن سليمان رحبعام ، وابنه أبيا ، وابنه آسا ، وابنه يهوشافاط '),
(192, '1 Chronicles', 13, 3, 11, ' وابنه يورام ، وابنه أخزيا ، وابنه يوآش '),
(193, '1 Chronicles', 13, 3, 12, ' وابنه أمصيا ، وابنه عزريا ، وابنه يوثام '),
(194, '1 Chronicles', 13, 3, 13, ' وابنه آحاز ، وابنه حزقيا ، وابنه منسى '),
(195, '1 Chronicles', 13, 3, 14, ' وابنه آمون ، وابنه يوشيا '),
(196, '1 Chronicles', 13, 3, 15, ' وبنو يوشيا : البكر يوحانان ، الثاني يهوياقيم ، الثالث صدقيا ، الرابع شلوم '),
(197, '1 Chronicles', 13, 3, 16, ' وابنا يهوياقيم : يكنيا ابنه وصدقيا ابنه '),
(198, '1 Chronicles', 13, 3, 17, ' وابنا يكنيا : أسير وشألتيئيل ابنه '),
(199, '1 Chronicles', 13, 3, 18, ' وملكيرام وفدايا وشنأصر ويقميا وهوشاماع وندبيا '),
(200, '1 Chronicles', 13, 3, 19, ' وابنا فدايا : زربابل وشمعي . وبنو زربابل : مشلام وحننيا وشلومية أختهم '),
(201, '1 Chronicles', 13, 3, 20, ' وحشوبة وأوهل وبرخيا وحسديا ويوشب حسد . خمسة '),
(202, '1 Chronicles', 13, 3, 21, ' وبنو حننيا : فلطيا ويشعيا ، وبنو رفايا ، وبنو أرنان ، وبنو عوبديا ، وبنو شكنيا '),
(203, '1 Chronicles', 13, 3, 22, ' وبنو شكنيا : شمعيا ، وبنو شمعيا : حطوش ويجآل وباريح ونعريا وشافاط.ستة '),
(204, '1 Chronicles', 13, 3, 23, ' وبنو نعريا : اليوعيني وحزقيا وعزريقام . ثلاثة '),
(205, '1 Chronicles', 13, 3, 24, ' وبنو اليوعيني : هوداياهو وألياشيب وفلايا وعقوب ويوحانان ودلايا وعناني . سبعة '),
(206, '1 Chronicles', 13, 4, 1, ' بنو يهوذا : فارص وحصرون وكرمي وحور وشوبال '),
(207, '1 Chronicles', 13, 4, 2, ' ورآيا بن شوبال ولد يحث ، ويحث ولد أخوماي ولاهد . هذه عشائر الصرعيين '),
(208, '1 Chronicles', 13, 4, 3, ' وهؤلاء لأبي عيطم : يزرعيل ويشما ويدباش ، واسم أختهم هصللفوني '),
(209, '1 Chronicles', 13, 4, 4, ' وفنوئيل أبو جدور ، وعازر أبو حوشة . هؤلاء بنو حور بكر أفراتة أبي بيت لحم '),
(210, '1 Chronicles', 13, 4, 5, ' وكان لأشحور أبي تقوع امرأتان : حلاة ونعرة '),
(211, '1 Chronicles', 13, 4, 6, ' وولدت له نعرة : أخزام وحافر والتيماني والأخشتاري . هؤلاء بنو نعرة '),
(212, '1 Chronicles', 13, 4, 7, ' وبنو حلاة : صرث وصوحر وأثنان '),
(213, '1 Chronicles', 13, 4, 8, ' وقوص ولد : عانوب وهصوبيبة وعشائر أخرحيل بن هارم '),
(214, '1 Chronicles', 13, 4, 9, ' وكان يعبيص أشرف من إخوته . وسمته أمه يعبيص قائلة : لأني ولدته بحزن '),
(215, '1 Chronicles', 13, 4, 10, ' ودعا يعبيص إله إسرائيل قائلا : ليتك تباركني ، وتوسع تخومي ، وتكون يدك معي ، وتحفظني من الشر حتى لا يتعبني . فآتاه الله بما سأل '),
(216, '1 Chronicles', 13, 4, 11, ' وكلوب أخو شوحة ولد محير . هو أبو أشتون '),
(217, '1 Chronicles', 13, 4, 12, ' وأشتون ولد بيت رافا وفاسح وتحنة أبا مدينة ناحاش . هؤلاء أهل ريكة '),
(218, '1 Chronicles', 13, 4, 13, ' وابنا قناز : عثنيئيل وسرايا ، وابن عثنيئيل : حثاث '),
(219, '1 Chronicles', 13, 4, 14, ' ومعونوثاي ولد عفرة ، وسرايا ولد يوآب أبا وادي الصناع ، لأنهم كانوا صناعا '),
(220, '1 Chronicles', 13, 4, 15, ' وبنو كالب بن يفنة : عيرو وأيلة وناعم . وابن أيلة : قناز '),
(221, '1 Chronicles', 13, 4, 16, ' وبنو يهللئيل : زيف وزيفة وتيريا وأسرئيل '),
(222, '1 Chronicles', 13, 4, 17, ' وبنو عزرة : يثر ومرد وعافر ويالون . وحبلت بمريم وشماي ويشبح أبي أشتموع '),
(223, '1 Chronicles', 13, 4, 18, ' وامرأته اليهودية ولدت يارد أبا جدور ، وحابر أبا سوكو ، ويقوثيئيل أبا زانوح . وهؤلاء بنو بثية بنت فرعون التي أخذها مرد '),
(224, '1 Chronicles', 13, 4, 19, ' وبنو امرأته اليهودية أخت نحم : أبي قعيلة الجرمي وأشتموع المعكي '),
(225, '1 Chronicles', 13, 4, 20, ' وبنو شيمون : أمنون ورنة بن حانان ، وتيلون . وابنا يشعي : زوحيت وبنزوحيت '),
(226, '1 Chronicles', 13, 4, 21, ' بنو شيلة بن يهوذا : عير أبو ليكة ، ولعدة أبو مريشة ، وعشائر بيت عاملي البز من بيت أشبيع '),
(227, '1 Chronicles', 13, 4, 22, ' ويوقيم ، وأهل كزيبا ، ويوآش وساراف ، الذين هم أصحاب موآب ويشوبي لحم . وهذه الأمور قديمة '),
(228, '1 Chronicles', 13, 4, 23, ' هؤلاء هم الخزافون وسكان نتاعيم وجديرة . أقاموا هناك مع الملك لشغله '),
(229, '1 Chronicles', 13, 4, 24, ' بنو شمعون : نموئيل ويامين ويريب وزارح وشاول '),
(230, '1 Chronicles', 13, 4, 25, ' وابنه شلوم وابنه مبسام وابنه مشماع '),
(231, '1 Chronicles', 13, 4, 26, ' وبنو مشماع : حموئيل ابنه ، زكور ابنه ، شمعي ابنه '),
(232, '1 Chronicles', 13, 4, 27, ' وكان لشمعي ستة عشر ابنا وست بنات . وأما إخوته فلم يكن لهم بنون كثيرون ، وكل عشائرهم لم يكثروا مثل بني يهوذا '),
(233, '1 Chronicles', 13, 4, 28, ' وأقاموا في بئر سبع ومولادة وحصر شوعال '),
(234, '1 Chronicles', 13, 4, 29, ' وفي بلهة وعاصم وتولاد '),
(235, '1 Chronicles', 13, 4, 30, ' وفي بتوئيل وحرمة وصقلغ '),
(236, '1 Chronicles', 13, 4, 31, ' وفي بيت مركبوت وحصر سوسيم وبيت برئي وشعرايم . هذه مدنهم إلى حينما ملك داود '),
(237, '1 Chronicles', 13, 4, 32, ' وقراهم : عيطم وعين ورمون وتوكن وعاشان ، خمس مدن '),
(238, '1 Chronicles', 13, 4, 33, ' وجميع قراهم التي حول هذه المدن إلى بعل . هذه مساكنهم وأنسابهم '),
(239, '1 Chronicles', 13, 4, 34, ' ومشوباب ويمليك ويوشا بن أمصيا '),
(240, '1 Chronicles', 13, 4, 35, ' ويوئيل وياهو بن يوشبيا بن سرايا بن عسيئيل '),
(241, '1 Chronicles', 13, 4, 36, ' وأليوعيناي ويعقوبا ويشوحايا وعسايا وعديئيل ويسيميئيل وبنايا '),
(242, '1 Chronicles', 13, 4, 37, ' وزيزا بن شفعي بن ألون بن يدايا بن شمري بن شمعيا '),
(243, '1 Chronicles', 13, 4, 38, ' هؤلاء الواردون بأسمائهم رؤساء في عشائرهم وبيوت آبائهم امتدوا كثيرا '),
(244, '1 Chronicles', 13, 4, 39, ' وساروا إلى مدخل جدور إلى شرقي الوادي ليفتشوا على مرعى لماشيتهم '),
(245, '1 Chronicles', 13, 4, 40, ' فوجدوا مرعى خصبا وجيدا ، وكانت الأرض واسعة الأطراف مستريحة ومطمئنة ، لأن آل حام سكنوا هناك في القديم '),
(246, '1 Chronicles', 13, 4, 41, ' وجاء هؤلاء المكتوبة أسماؤهم في أيام حزقيا ملك يهوذا . وضربوا خيمهم والمعونيين الذين وجدوا هناك وحرموهم إلى هذا اليوم ، وسكنوا مكانهم لأن هناك مرعى لماشيتهم '),
(247, '1 Chronicles', 13, 4, 42, ' ومنهم ، من بني شمعون ، ذهب إلى جبل سعير خمس مئة رجل ، وقدامهم : فلطيا ونعريا ورفايا وعزيئيل بنو يشعي '),
(248, '1 Chronicles', 13, 4, 43, ' وضربوا بقية المنفلتين من عماليق ، وسكنوا هناك إلى هذا اليوم '),
(249, '1 Chronicles', 13, 5, 1, ' وبنو رأوبين بكر إسرائيل . لأنه هو البكر ، ولأجل تدنيسه فراش أبيه ، أعطيت بكوريته لبني يوسف بن إسرائيل ، فلم ينسب بكرا '),
(250, '1 Chronicles', 13, 5, 2, ' لأن يهوذا اعتز على إخوته ومنه الرئيس ، وأما البكورية فليوسف '),
(251, '1 Chronicles', 13, 5, 3, ' بنو رأوبين بكر إسرائيل : حنوك وفلو وحصرون وكرمي '),
(252, '1 Chronicles', 13, 5, 4, ' بنو يوئيل : ابنه شمعيا ، وابنه جوج ، وابنه شمعي '),
(253, '1 Chronicles', 13, 5, 5, ' وابنه ميخا ، وابنه رآيا ، وابنه بعل '),
(254, '1 Chronicles', 13, 5, 6, ' وابنه بئيرة الذي سباه تلغث فلناسر ملك أشور . هو رئيس الرأوبينيين '),
(255, '1 Chronicles', 13, 5, 7, ' وإخوته حسب عشائرهم في الانتساب حسب مواليدهم : الرئيس يعيئيل وزكريا '),
(256, '1 Chronicles', 13, 5, 8, ' وبالع بن عزاز بن شامع بن يوئيل الذي سكن في عروعير حتى إلى نبو وبعل معون '),
(257, '1 Chronicles', 13, 5, 9, ' وسكن شرقا إلى مدخل البرية من نهر الفرات ، لأن ماشيتهم كثرت في أرض جلعاد '),
(258, '1 Chronicles', 13, 5, 10, ' وفي أيام شاول عملوا حربا مع الهاجريين فسقطوا بأيديهم ، وسكنوا في خيامهم في جميع جهات شرق جلعاد '),
(259, '1 Chronicles', 13, 5, 11, ' وبنو جاد سكنوا مقابلهم في أرض باشان حتى إلى سلخة '),
(260, '1 Chronicles', 13, 5, 12, ' يوئيل الرأس ، وشافاط ثانيه ، ويعناي وشافاط في باشان '),
(261, '1 Chronicles', 13, 5, 13, ' وإخوتهم حسب بيوت آبائهم : ميخائيل ومشلام وشبع ويوراي ويعكان وزيع وعابر . سبعة '),
(262, '1 Chronicles', 13, 5, 14, ' هؤلاء بنو أبيحايل بن حوري بن ياروح بن جلعاد بن ميخائيل بن يشيشاي بن يحدو بن بوز '),
(263, '1 Chronicles', 13, 5, 15, ' وأخي بن عبدئيل بن جوني رئيس بيت آبائهم '),
(264, '1 Chronicles', 13, 5, 16, ' وسكنوا في جلعاد في باشان وقراها ، وفي جميع مسارح شارون عند مخارجها '),
(265, '1 Chronicles', 13, 5, 17, ' جميعهم انتسبوا في أيام يوثام ملك يهوذا ، وفي أيام يربعام ملك إسرائيل '),
(266, '1 Chronicles', 13, 5, 18, ' بنو رأوبين والجاديون ونصف سبط منسى من بني البأس ، رجال يحملون الترس والسيف ويشدون القوس ومتعلمون القتال ، أربعة وأربعون ألفا وسبع مئة وستون من الخارجين في الجيش '),
(267, '1 Chronicles', 13, 5, 19, ' وعملوا حربا مع الهاجريين ويطور ونافيش ونوداب '),
(268, '1 Chronicles', 13, 5, 20, ' فانتصروا عليهم . فدفع ليدهم الهاجريون وكل من معهم لأنهم صرخوا إلى الله في القتال ، فاستجاب لهم لأنهم اتكلوا عليه '),
(269, '1 Chronicles', 13, 5, 21, ' ونهبوا ماشيتهم : جمالهم خمسين ألفا ، وغنما مئتين وخمسين ألفا ، وحميرا ألفين . وسبوا أناسا مئة ألف '),
(270, '1 Chronicles', 13, 5, 22, ' لأنه سقط قتلى كثيرون ، لأن القتال إنما كان من الله . وسكنوا مكانهم إلى السبي '),
(271, '1 Chronicles', 13, 5, 23, ' وبنو نصف سبط منسى سكنوا في الأرض وامتدوا من باشان إلى بعل حرمون وسنير وجبل حرمون '),
(272, '1 Chronicles', 13, 5, 24, ' وهؤلاء رؤوس بيوت آبائهم : عافر ويشعي وأليئيل وعزريئيل ويرميا وهودويا ويحديئيل ،  ، رجال جبابرة بأس وذوو اسم ورؤوس لبيوت آبائهم '),
(273, '1 Chronicles', 13, 5, 25, ' وخانوا إله آبائهم وزنوا وراء آلهة شعوب الأرض الذين طردهم الرب من أمامهم '),
(274, '1 Chronicles', 13, 5, 26, ' فنبه إله إسرائيل روح فول ملك أشور وروح تلغث فلناسر ملك أشور ، فسباهم ، الرأوبينيين والجاديين ونصف سبط منسى ، وأتى بهم إلى حلح وخابور وهارا ونهر جوزان إلى هذا اليوم '),
(275, '1 Chronicles', 13, 6, 1, ' بنو لاوي : جرشون وقهات ومراري '),
(276, '1 Chronicles', 13, 6, 2, ' وبنو قهات : عمرام ويصهار وحبرون وعزيئيل '),
(277, '1 Chronicles', 13, 6, 3, ' وبنو عمرام : هارون وموسى ومريم . وبنو هارون : ناداب وأبيهو وأليعازار وإيثامار '),
(278, '1 Chronicles', 13, 6, 4, ' ألعازار ولد فينحاس ، وفينحاس ولد أبيشوع '),
(279, '1 Chronicles', 13, 6, 5, ' وأبيشوع ولد بقي ، وبقي ولد عزي '),
(280, '1 Chronicles', 13, 6, 6, ' وعزي ولد زرحيا ، وزرحيا ولد مرايوث '),
(281, '1 Chronicles', 13, 6, 7, ' ومرايوث ولد أمريا ، وأمريا ولد أخيطوب '),
(282, '1 Chronicles', 13, 6, 8, ' وأخيطوب ولد صادوق ، وصادوق ولد أخيمعص '),
(283, '1 Chronicles', 13, 6, 9, ' وأخيمعص ولد عزريا ، وعزريا ولد يوحانان '),
(284, '1 Chronicles', 13, 6, 10, ' ويوحانان ولد عزريا ، وهو الذي كهن في البيت الذي بناه سليمان في أورشليم '),
(285, '1 Chronicles', 13, 6, 11, ' وعزريا ولد أمريا ، وأمريا ولد أخيطوب '),
(286, '1 Chronicles', 13, 6, 12, ' وأخيطوب ولد صادوق ، وصادوق ولد شلوم '),
(287, '1 Chronicles', 13, 6, 13, ' وشلوم ولد حلقيا ، وحلقيا ولد عزريا '),
(288, '1 Chronicles', 13, 6, 14, ' وعزريا ولد سرايا ، وسرايا ولد يهوصاداق '),
(289, '1 Chronicles', 13, 6, 15, ' ويهوصاداق سار في سبي الرب يهوذا ، وأورشليم بيد نبوخذناصر '),
(290, '1 Chronicles', 13, 6, 16, ' بنو لاوي : جرشوم وقهات ومراري '),
(291, '1 Chronicles', 13, 6, 17, ' وهذان اسما ابني جرشوم : لبني وشمعي '),
(292, '1 Chronicles', 13, 6, 18, ' وبنو قهات : عمرام ويصهار وحبرون وعزيئيل '),
(293, '1 Chronicles', 13, 6, 19, ' وابنا مراري : محلي وموشي . فهذه عشائر اللاويين حسب آبائهم '),
(294, '1 Chronicles', 13, 6, 20, ' لجرشوم : لبني ابنه ، ويحث ابنه ، وزمة ابنه '),
(295, '1 Chronicles', 13, 6, 21, ' ويوآخ ابنه ، وعدو ابنه ، وزارح ابنه ، ويأثراي ابنه '),
(296, '1 Chronicles', 13, 6, 22, ' بنو قهات : عميناداب ابنه ، وقورح ابنه ، وأسير ابنه '),
(297, '1 Chronicles', 13, 6, 23, ' وألقانة ابنه ، وأبيأساف ابنه ، وأسير ابنه '),
(298, '1 Chronicles', 13, 6, 24, ' وتحث ابنه ، وأوريئيل ابنه ، وعزيا ابنه ، وشاول ابنه '),
(299, '1 Chronicles', 13, 11, 5, ' وقال سكان يبوس لداود : لا تدخل إلى هنا . فأخذ داود حصن صهيون ، هي مدينة داود '),
(300, '1 Chronicles', 13, 11, 6, ' وقال داود : إن الذي يضرب اليبوسيين أولا يكون رأسا وقائدا . فصعد أولا يوآب ابن صروية ، فصار رأسا '),
(301, '1 Chronicles', 13, 11, 7, ' وأقام داود في الحصن ، لذلك دعوه مدينة داود '),
(302, '1 Chronicles', 13, 11, 8, ' وبنى المدينة حواليها من القلعة إلى ما حولها . ويوآب جدد سائر المدينة '),
(303, '1 Chronicles', 13, 11, 9, ' وكان داود يتزايد متعظما ورب الجنود معه '),
(304, '1 Chronicles', 13, 11, 10, ' وهؤلاء رؤساء الأبطال الذين لداود ، الذين تشددوا معه في ملكه مع كل إسرائيل لتمليكه حسب كلام الرب من جهة إسرائيل '),
(305, '1 Chronicles', 13, 11, 11, ' وهذا هو عدد الأبطال الذين لداود : يشبعام بن حكموني رئيس الثوالث . هو هز رمحه على ثلاث مئة قتلهم دفعة واحدة '),
(306, '1 Chronicles', 13, 11, 12, ' وبعده ألعازار بن دودو الأخوخي . هو من الأبطال الثلاثة '),
(307, '1 Chronicles', 13, 11, 13, ' هو كان مع داود في فس دميم وقد اجتمع هناك الفلسطينيون للحرب . وكانت قطعة الحقل مملوءة شعيرا ، فهرب الشعب من أمام الفلسطينيين '),
(308, '1 Chronicles', 13, 11, 14, ' ووقفوا في وسط القطعة وأنقذوها ، وضربوا الفلسطينيين . وخلص الرب خلاصا عظيما '),
(309, '1 Chronicles', 13, 11, 15, ' ونزل ثلاثة من الثلاثين رئيسا إلى الصخر إلى داود ، إلى مغارة عدلام ، وجيش الفلسطينيين نازل في وادي الرفائيين '),
(310, '1 Chronicles', 13, 11, 16, ' وكان داود حينئذ في الحصن ، وحفظة الفلسطينيين حينئذ في بيت لحم '),
(311, '1 Chronicles', 13, 11, 17, ' فتأوه داود وقال : من يسقيني ماء من بئر بيت لحم التي عند الباب '),
(312, '1 Chronicles', 13, 11, 18, ' فشق الثلاثة محلة الفلسطينيين واستقوا ماء من بئر بيت لحم التي عند الباب ، وحملوه وأتوا به إلى داود ، فلم يشأ داود أن يشربه بل سكبه للرب '),
(313, '1 Chronicles', 13, 11, 19, ' وقال : حاشا لي من قبل إلهي أن أفعل ذلك أأشرب دم هؤلاء الرجال بأنفسهم ؟ لأنهم إنما أتوا به بأنفسهم . ولم يشأ أن يشربه . هذا ما فعله الأبطال الثلاثة '),
(314, '1 Chronicles', 13, 11, 20, ' وأبشاي أخو يوآب كان رئيس ثلاثة . وهو قد هز رمحه على ثلاث مئة فقتلهم ، فكان له اسم بين الثلاثة '),
(315, '1 Chronicles', 13, 11, 21, ' من الثلاثة أكرم على الاثنين وكان لهما رئيسا ، إلا أنه لم يصل إلى الثلاثة الأول '),
(316, '1 Chronicles', 13, 11, 22, ' بنايا بن يهوياداع ابن ذي بأس كثير الأفعال من قبصيئيل . هو الذي ضرب أسدي موآب ، وهو الذي نزل وضرب أسدا في وسط جب يوم الثلج '),
(317, '1 Chronicles', 13, 11, 23, ' وهو ضرب الرجل المصري الذي قامته خمس أذرع ، وفي يد المصري رمح كنول النساجين . فنزل إليه بعصا وخطف الرمح من يد المصري وقتله برمحه '),
(318, '1 Chronicles', 13, 11, 24, ' هذا ما فعله بنايا بن يهوياداع ، فكان له اسم بين الثلاثة الأبطال '),
(319, '1 Chronicles', 13, 11, 25, ' هوذا أكرم على الثلاثين إلا أنه لم يصل إلى الثلاثة . فجعله داود من أصحاب سره '),
(320, '1 Chronicles', 13, 11, 26, ' وأبطال الجيش هم : عسائيل أخو يوآب ، وألحانان بن دودو من بيت لحم '),
(321, '1 Chronicles', 13, 11, 27, ' شموت الهروري ، حالص الفلوني '),
(322, '1 Chronicles', 13, 11, 28, ' عيرا بن عقيش التقوعي ، أبيعزر العناثوثي '),
(323, '1 Chronicles', 13, 11, 29, ' سبكاي الحوشاتي ، عيلاي الأخوخي '),
(324, '1 Chronicles', 13, 11, 30, ' مهراي النطوفاتي ، خالد بن بعنة النطوفاتي '),
(325, '1 Chronicles', 13, 11, 31, ' إتاي بن ريباي من جبعة بني بنيامين ، بنايا الفرعتوني '),
(326, '1 Chronicles', 13, 11, 32, ' حوراي من أودية جاعش ، أبيئيل العرباتي '),
(327, '1 Chronicles', 13, 11, 33, ' عزموت البحرومي ، إليحبا الشعلبوني '),
(328, '1 Chronicles', 13, 11, 34, ' بنو هاشم الجزوني ، يوناثان بن شاجاي الهراري '),
(329, '1 Chronicles', 13, 11, 35, ' أخيآم بن ساكار الهراري ، أليفال بن أور '),
(330, '1 Chronicles', 13, 11, 36, ' حافر المكيراتي ، وأخيا الفلوني '),
(331, '1 Chronicles', 13, 11, 37, ' حصرو الكرملي ، نعراي بن أزباي '),
(332, '1 Chronicles', 13, 11, 38, ' يوئيل أخو ناثان ، مبحار بن هجري '),
(333, '1 Chronicles', 13, 11, 39, ' صالق العموني ، نحراي البئيروتي ، حامل سلاح يوآب ابن صروية '),
(334, '1 Chronicles', 13, 11, 40, ' عيرا اليثري ، جارب اليثري '),
(335, '1 Chronicles', 13, 11, 41, ' أوريا الحثي ، زاباد بن أحلاي '),
(336, '1 Chronicles', 13, 11, 42, ' عدينا بن شيزا الرأوبيني ، رأس الرأوبينيين ومعه ثلاثون '),
(337, '1 Chronicles', 13, 11, 43, ' حانان ابن معكة ، يوشافاط المثني '),
(338, '1 Chronicles', 13, 11, 44, ' عزيا العشتروتي ، شاماع ويعوئيل ابنا حوثام العروعيري '),
(339, '1 Chronicles', 13, 11, 45, ' يديعئيل بن شمري ، ويوحا أخوه التيصي '),
(340, '1 Chronicles', 13, 11, 46, ' إيليئيل من محويم ، ويريباي ويوشويا ابنا ألنعم ، ويثمة الموآبي '),
(341, '1 Chronicles', 13, 11, 47, ' إيليئيل وعوبيد ويعسيئيل من مصوبايا '),
(342, '1 Chronicles', 13, 12, 1, ' وهؤلاء هم الذين جاءوا إلى داود إلى صقلغ ، وهو بعد محجوز عن وجه شاول بن قيس ، وهم من الأبطال مساعدون في الحرب '),
(343, '1 Chronicles', 13, 12, 2, ' نازعون في القسي ، يرمون الحجارة والسهام من القسي باليمين واليسار ، من إخوة شاول من بنيامين '),
(344, '1 Chronicles', 13, 12, 3, ' الرأس أخيعزر ثم يوآش ابنا شماعة الجبعي ، ويزوئيل وفالط ابنا عزموت ، وبراخة وياهو العناثوثي '),
(345, '1 Chronicles', 13, 12, 4, ' ويشمعيا الجبعوني البطل بين الثلاثين وعلى الثلاثين ، ويرميا ويحزيئيل ويوحانان ويوزاباد الجديري '),
(346, '1 Chronicles', 13, 12, 5, ' وإلعوزاي ويريموث وبعليا وشمريا وشفطيا الحروفي '),
(347, '1 Chronicles', 13, 12, 6, ' وألقانة ويشيا وعزريئيل ويوعزر ويشبعام القورحيون '),
(348, '1 Chronicles', 13, 12, 7, ' ويوعيلة وزبديا ابنا يروحام من جدور '),
(349, '1 Chronicles', 13, 12, 8, ' ومن الجاديين انفصل إلى داود إلى الحصن في البرية جبابرة البأس رجال جيش للحرب ، صافو أتراس ورماح ، وجوههم كوجوه الأسود ، وهم كالظبي على الجبال في السرعة '),
(350, '1 Chronicles', 13, 12, 9, ' عازر الرأس ، وعوبديا الثاني ، وأليآب الثالث '),
(351, '1 Chronicles', 13, 12, 10, ' ومشمنة الرابع ، ويرميا الخامس '),
(352, '1 Chronicles', 13, 12, 11, ' وعتاي السادس ، وإيليئيل السابع '),
(353, '1 Chronicles', 13, 12, 12, ' ويوحانان الثامن ، وألزاباد التاسع '),
(354, '1 Chronicles', 13, 12, 13, ' ويرميا العاشر ، ومخبناي الحادي عشر '),
(355, '1 Chronicles', 13, 12, 14, ' هؤلاء من بني جاد رؤوس الجيش . صغيرهم لمئة ، والكبير لألف '),
(356, '1 Chronicles', 13, 12, 15, ' هؤلاء هم الذين عبروا الأردن في الشهر الأول وهو ممتلئ إلى جميع شطوطه وهزموا كل أهل الأودية شرقا وغربا '),
(357, '1 Chronicles', 13, 12, 16, ' وجاء قوم من بني بنيامين ويهوذا إلى الحصن إلى داود '),
(358, '1 Chronicles', 13, 12, 17, ' فخرج داود لاستقبالهم وأجاب وقال لهم : إن كنتم قد جئتم بسلام إلي لتساعدوني ، يكون لي معكم قلب واحد . وإن كان لكي تدفعوني لعدوي ولا ظلم في يدي ، فلينظر إله آبائنا وينصف '),
(359, '1 Chronicles', 13, 12, 18, ' فحل الروح على عماساي رأس الثوالث فقال : لك نحن يا داود ، ومعك نحن يا ابن يسى . سلام ، سلام لك ، وسلام لمساعديك . لأن إلهك معينك . فقبلهم داود وجعلهم رؤوس الجيوش '),
(360, '1 Chronicles', 13, 12, 19, ' وسقط إلى داود بعض من منسى حين جاء مع الفلسطينيين ضد شاول للقتال ولم يساعدوهم ، لأن أقطاب الفلسطينيين أرسلوه بمشورة قائلين : إنما برؤوسنا يسقط إلى سيده شاول '),
(361, '1 Chronicles', 13, 12, 20, ' حين انطلق إلى صقلغ سقط إليه من منسى عدناح ويوزاباد ويديعئيل وميخائيل ويوزاباد وأليهو وصلتاي رؤوس ألوف منسى '),
(362, '1 Chronicles', 13, 12, 21, ' وهم ساعدوا داود على الغزاة لأنهم جميعا جبابرة بأس ، وكانوا رؤساء في الجيش '),
(363, '1 Chronicles', 13, 12, 22, ' لأنه وقتئذ أتى أناس إلى داود يوما فيوما لمساعدته ، حتى صاروا جيشا عظيما كجيش الله '),
(364, '1 Chronicles', 13, 12, 23, ' وهذا عدد رؤوس المتجردين للقتال الذين جاءوا إلى داود إلى حبرون ، ليحولوا مملكة شاول إليه حسب قول الرب '),
(365, '1 Chronicles', 13, 12, 24, ' بنو يهوذا حاملو الأتراس والرماح ستة آلاف وثمان مئة متجرد للقتال '),
(366, '1 Chronicles', 13, 12, 25, ' من بني شمعون جبابرة بأس في الحرب سبعة آلاف ومئة '),
(367, '1 Chronicles', 13, 12, 26, ' من بني لاوي أربعة آلاف وست مئة '),
(368, '1 Chronicles', 13, 18, 2, ' وضرب موآب ، فصار الموآبيون عبيدا لداود يقدمون هدايا '),
(369, '1 Chronicles', 13, 18, 3, ' وضرب داود هدر عزر ملك صوبة في حماة حين ذهب ليقيم سلطته عند نهر الفرات '),
(370, '1 Chronicles', 13, 18, 4, ' وأخذ داود منه ألف مركبة وسبعة آلاف فارس وعشرين ألف راجل ، وعرقب داود كل خيل المركبات وأبقى منها مئة مركبة '),
(371, '1 Chronicles', 13, 18, 5, ' فجاء أرام دمشق لنجدة هدر عزر ملك صوبة ، فضرب داود من أرام اثنين وعشرين ألف رجل '),
(372, '1 Chronicles', 13, 18, 6, ' وجعل داود محافظين في أرام دمشق ، وصار الأراميون لداود عبيدا يقدمون هدايا . وكان الرب يخلص داود حيثما توجه '),
(373, '1 Chronicles', 13, 18, 7, ' وأخذ داود أتراس الذهب التي كانت على عبيد هدر عزر وأتى بها إلى أورشليم '),
(374, '1 Chronicles', 13, 18, 8, ' ومن طبحة وخون مدينتي هدر عزر أخذ داود نحاسا كثيرا جدا صنع منه سليمان بحر النحاس والأعمدة وآنية النحاس '),
(375, '1 Chronicles', 13, 18, 9, ' وسمع توعو ملك حماة أن داود قد ضرب كل جيش هدر عزر ملك صوبة '),
(376, '1 Chronicles', 13, 18, 10, ' فأرسل هدورام ابنه إلى الملك داود ليسأل عن سلامته ويباركه ، لأنه حارب هدر عزر وضربه . لأن هدر عزر كانت له حروب مع توعو . وبيده جميع آنية الذهب والفضة والنحاس '),
(377, '1 Chronicles', 13, 18, 11, ' هذه أيضا قدسها الملك داود للرب مع الفضة والذهب الذي أخذه من كل الأمم : من أدوم ومن موآب ومن بني عمون ومن الفلسطينيين ومن عماليق '),
(378, '1 Chronicles', 13, 18, 12, ' وأبشاي ابن صروية ضرب من أدوم في وادي الملح ثمانية عشر ألفا '),
(379, '1 Chronicles', 13, 18, 13, ' وجعل في أدوم محافظين ، فصار جميع الأدوميين عبيدا لداود . وكان الرب يخلص داود حيثما توجه '),
(380, '1 Chronicles', 13, 18, 14, ' وملك داود على جميع إسرائيل ، وكان يجري قضاء وعدلا لكل شعبه '),
(381, '1 Chronicles', 13, 18, 15, ' وكان يوآب ابن صروية على الجيش ، ويهوشافاط بن أخيلود مسجلا '),
(382, '1 Chronicles', 13, 18, 16, ' وصادوق بن أخيطوب وأبيمالك بن أبياثار كاهنين ، وشوشا كاتبا '),
(383, '1 Chronicles', 13, 18, 17, ' وبنايا بن يهوياداع على الجلادين والسعاة ، وبنو داود الأولين بين يدي الملك '),
(384, '1 Chronicles', 13, 19, 1, ' وكان بعد ذلك أن ناحاش ملك بني عمون مات ، فملك ابنه عوضا عنه '),
(385, '1 Chronicles', 13, 19, 2, ' فقال داود : أصنع معروفا مع حانون بن ناحاش ، لأن أباه صنع معي معروفا . فأرسل داود رسلا ليعزيه بأبيه . فجاء عبيد داود إلى أرض بني عمون إلى حانون ليعزوه '),
(386, '1 Chronicles', 13, 19, 3, ' فقال رؤساء بني عمون لحانون : هل يكرم داود أباك في عينيك حتى أرسل إليك معزين ؟ أليس إنما لأجل الفحص والقلب وتجسس الأرض جاء عبيده إليك '),
(387, '1 Chronicles', 13, 19, 4, ' فأخذ حانون عبيد داود وحلق لحاهم وقص ثيابهم من الوسط عند السوءة ثم أطلقهم '),
(388, '1 Chronicles', 13, 19, 5, ' فذهب أناس وأخبروا داود عن الرجال . فأرسل للقائهم ، لأن الرجال كانوا خجلين جدا . وقال الملك : أقيموا في أريحا حتى تنبت لحاكم ثم ارجعوا '),
(389, '1 Chronicles', 13, 19, 6, ' ولما رأى بنو عمون أنهم قد أنتنوا عند داود ، أرسل حانون وبنو عمون ألف وزنة من الفضة لكي يستأجروا لأنفسهم من أرام النهرين ومن أرام معكة ومن صوبة مركبات وفرسانا '),
(390, '1 Chronicles', 13, 19, 7, ' فاستأجروا لأنفسهم اثنين وثلاثين ألف مركبة ، وملك معكة وشعبه . فجاءوا ونزلوا مقابل ميدبا . واجتمع بنو عمون من مدنهم وأتوا للحرب '),
(391, '1 Chronicles', 13, 19, 8, ' ولما سمع داود أرسل يوآب وكل جيش الجبابرة '),
(392, '1 Chronicles', 13, 19, 9, ' فخرج بنو عمون واصطفوا للحرب عند باب المدينة ، والملوك الذين جاءوا كانوا وحدهم في الحقل '),
(393, '1 Chronicles', 13, 19, 10, ' ولما رأى يوآب أن مقدمة الحرب كانت نحوه من قدام ومن وراء ، اختار من جميع منتخبي إسرائيل ، وصفهم للقاء أرام '),
(394, '1 Chronicles', 13, 19, 11, ' وسلم بقية الشعب ليد أبشاي أخيه ، فاصطفوا للقاء بني عمون '),
(395, '1 Chronicles', 13, 19, 12, ' وقال : إن قوي أرام علي تكون لي نجدة ، وإن قوي بنو عمون عليك أنجدتك '),
(396, '1 Chronicles', 13, 19, 13, ' تجلد ، ولنتشدد لأجل شعبنا ولأجل مدن إلهنا ، وما يحسن في عيني الرب يفعل '),
(397, '1 Chronicles', 13, 19, 14, ' وتقدم يوآب والشعب الذين معه نحو أرام للمحاربة ، فهربوا من أمامه '),
(398, '1 Chronicles', 13, 19, 15, ' ولما رأى بنو عمون أنه قد هرب أرام ، هربوا هم أيضا من أمام أبشاي أخيه ودخلوا إلى المدينة . وجاء يوآب إلى أورشليم '),
(399, '1 Chronicles', 13, 19, 16, ' ولما رأى أرام أنهم قد انكسروا أمام إسرائيل أرسلوا رسلا ، وأبرزوا أرام الذين في عبر النهر ، وأمامهم شوبك رئيس جيش هدر عزر '),
(400, '1 Chronicles', 13, 19, 17, ' ولما أخبر داود جمع كل إسرائيل وعبر الأردن وجاء إليهم واصطف ضدهم . اصطف داود للقاء أرام في الحرب فحاربوه '),
(401, '1 Chronicles', 13, 19, 18, ' وهرب أرام من أمام إسرائيل ، وقتل داود من أرام سبعة آلاف مركبة وأربعين ألف راجل ، وقتل شوبك رئيس الجيش '),
(402, '1 Chronicles', 13, 19, 19, ' ولما رأى عبيد هدر عزر أنهم قد انكسروا أمام إسرائيل صالحوا داود وخدموه . ولم يشأ أرام أن ينجدوا بني عمون بعد '),
(403, '1 Chronicles', 13, 20, 1, ' وكان عند تمام السنة في وقت خروج الملوك ، اقتاد يوآب قوة الجيش وأخرب أرض بني عمون وأتى وحاصر ربة . وكان داود مقيما في أورشليم . فضرب يوآب ربة وهدمها '),
(404, '1 Chronicles', 13, 20, 2, ' وأخذ داود تاج ملكهم عن رأسه ، فوجد وزنه وزنة من الذهب ، وفيه حجر كريم . فكان على رأس داود . وأخرج غنيمة المدينة وكانت كثيرة جدا '),
(405, '1 Chronicles', 13, 20, 3, ' وأخرج الشعب الذين بها ونشرهم بمناشير ونوارج حديد وفؤوس . وهكذا صنع داود لكل مدن بني عمون . ثم رجع داود وكل الشعب إلى أورشليم '),
(406, '1 Chronicles', 13, 20, 4, ' ثم بعد ذلك قامت حرب في جازر مع الفلسطينيين . حينئذ سبكاي الحوشي قتل سفاي من أولاد رافا فذلوا '),
(407, '1 Chronicles', 13, 20, 5, ' وكانت أيضا حرب مع الفلسطينيين ، فقتل ألحانان بن ياعور لحمي أخا جليات الجتي . وكانت قناة رمحه كنول النساجين '),
(408, '1 Chronicles', 13, 20, 6, ' ثم كانت أيضا حرب في جت ، وكان رجل طويل القامة أعنش ، أصابعه أربع وعشرون ، وهو أيضا ولد لرافا '),
(409, '1 Chronicles', 13, 20, 7, ' ولما عير إسرائيل ضربه يهوناثان بن شمعا أخي داود '),
(410, '1 Chronicles', 13, 20, 8, ' هؤلاء ولدوا لرافا في جت وسقطوا بيد داود وبيد عبيده '),
(411, '1 Chronicles', 13, 21, 1, ' ووقف الشيطان ضد إسرائيل ، وأغوى داود ليحصي إسرائيل '),
(412, '1 Chronicles', 13, 21, 2, ' فقال داود ليوآب ولرؤساء الشعب : اذهبوا عدوا إسرائيل من بئر سبع إلى دان ، وأتوا إلي فأعلم عددهم '),
(413, '1 Chronicles', 13, 21, 3, ' فقال يوآب : ليزد الرب على شعبه أمثالهم مئة ضعف . أليسوا جميعا يا سيدي الملك عبيدا لسيدي ؟ لماذا يطلب هذا سيدي ؟ لماذا يكون سبب إثم لإسرائيل '),
(414, '1 Chronicles', 13, 21, 4, ' فاشتد كلام الملك على يوآب . فخرج يوآب وطاف في كل إسرائيل ثم جاء إلى أورشليم '),
(415, '1 Chronicles', 13, 21, 5, ' فدفع يوآب جملة عدد الشعب إلى داود ، فكان كل إسرائيل ألف ألف ومئة ألف رجل مستلي السيف ، ويهوذا أربع مئة وسبعين ألف رجل مستلي السيف '),
(416, '1 Chronicles', 13, 21, 6, ' وأما لاوي وبنيامين فلم يعدهم معهم لأن كلام الملك كان مكروها لدى يوآب '),
(417, '1 Chronicles', 13, 21, 7, ' وقبح في عيني الله هذا الأمر فضرب إسرائيل '),
(418, '1 Chronicles', 13, 21, 8, ' فقال داود لله : لقد أخطأت جدا حيث عملت هذا الأمر . والآن أزل إثم عبدك لأني سفهت جدا '),
(419, '1 Chronicles', 13, 21, 9, ' فكلم الرب جاد رائي داود وقال '),
(420, '1 Chronicles', 13, 21, 10, ' اذهب وكلم داود قائلا : هكذا قال الرب : ثلاثة أنا عارض عليك فاختر لنفسك واحدا منها فأفعله بك '),
(421, '1 Chronicles', 13, 21, 11, ' فجاء جاد إلى داود وقال له : هكذا قال الرب : اقبل لنفسك '),
(422, '1 Chronicles', 13, 21, 12, ' إما ثلاث سنين جوع ، أو ثلاثة أشهر هلاك أمام مضايقيك وسيف أعدائك يدركك ، أو ثلاثة أيام يكون فيها سيف الرب ووبأ في الأرض ، وملاك الرب يعثو في كل تخوم إسرائيل فانظر الآن ماذا أرد جوابا لمرسلي '),
(423, '1 Chronicles', 13, 21, 13, ' فقال داود لجاد : قد ضاق بي الأمر جدا . دعني أسقط في يد الرب لأن مراحمه كثيرة ، ولا أسقط في يد إنسان '),
(424, '1 Chronicles', 13, 21, 14, ' فجعل الرب وبأ في إسرائيل ، فسقط من إسرائيل سبعون ألف رجل '),
(425, '1 Chronicles', 13, 21, 15, ' وأرسل الله ملاكا على أورشليم لإهلاكها ، وفيما هو يهلك رأى الرب فندم على الشر ، وقال للملاك المهلك : كفى الآن ، رد يدك . وكان ملاك الرب واقفا عند بيدر أرنان اليبوسي '),
(426, '1 Chronicles', 13, 21, 16, ' ورفع داود عينيه فرأى ملاك الرب واقفا بين الأرض والسماء ، وسيفه مسلول بيده وممدود على أورشليم . فسقط داود والشيوخ على وجوههم مكتسين بالمسوح '),
(427, '1 Chronicles', 13, 21, 17, ' وقال داود لله : ألست أنا هو الذي أمر بإحصاء الشعب ؟ وأنا هو الذي أخطأ وأساء ، وأما هؤلاء الخراف فماذا عملوا ؟ فأيها الرب إلهي ، لتكن يدك علي وعلى بيت أبي لا على شعبك لضربهم '),
(428, '1 Chronicles', 13, 21, 18, ' فكلم ملاك الرب جاد أن يقول لداود أن يصعد داود ليقيم مذبحا للرب في بيدر أرنان اليبوسي '),
(429, '1 Chronicles', 13, 21, 19, ' فصعد داود حسب كلام جاد الذي تكلم به باسم الرب '),
(430, '1 Chronicles', 13, 21, 20, ' فالتفت أرنان فرأى الملاك . وبنوه الأربعة معه اختبأوا ، وكان أرنان يدرس حنطة '),
(431, '1 Chronicles', 13, 21, 21, ' وجاء داود إلى أرنان . وتطلع أرنان فرأى داود ، وخرج من البيدر وسجد لداود على وجهه إلى الأرض '),
(432, '1 Chronicles', 13, 21, 22, ' فقال داود لأرنان : أعطني مكان البيدر فأبني فيه مذبحا للرب . بفضة كاملة أعطني إياه ، فتكف الضربة عن الشعب '),
(433, '1 Chronicles', 13, 21, 23, ' فقال أرنان لداود : خذه لنفسك ، وليفعل سيدي الملك ما يحسن في عينيه . انظر . قد أعطيت البقر للمحرقة ، والنوارج للوقود ، والحنطة للتقدمة . الجميع أعطيت '),
(434, '1 Chronicles', 13, 21, 24, ' فقال الملك داود لأرنان : لا بل شراء أشتريه بفضة كاملة ، لأني لا آخذ ما لك للرب فأصعد محرقة مجانية '),
(435, '1 Chronicles', 13, 21, 25, ' ودفع داود لأرنان عن المكان ذهبا وزنه ست مئة شاقل '),
(436, '1 Chronicles', 13, 21, 26, ' وبنى داود هناك مذبحا للرب ، وأصعد محرقات وذبائح سلامة ، ودعا الرب فأجابه بنار من السماء على مذبح المحرقة '),
(437, '1 Chronicles', 13, 21, 27, ' وأمر الرب الملاك فرد سيفه إلى غمده '),
(438, '1 Chronicles', 13, 21, 28, ' في ذلك الوقت لما رأى داود أن الرب قد أجابه في بيدر أرنان اليبوسي ذبح هناك '),
(439, '1 Chronicles', 13, 21, 29, ' ومسكن الرب الذي عمله موسى في البرية ومذبح المحرقة كانا في ذلك الوقت في المرتفعة في جبعون '),
(440, '1 Chronicles', 13, 21, 30, ' ولم يستطع داود أن يذهب إلى أمامه ليسأل الله ، لأنه خاف من جهة سيف ملاك الرب '),
(441, '1 Chronicles', 13, 22, 1, ' فقال داود : هذا هو بيت الرب الإله ، وهذا هو مذبح المحرقة لإسرائيل '),
(442, '1 Chronicles', 13, 6, 25, ' وابنا ألقانة : عماساي وأخيموت '),
(443, '1 Chronicles', 13, 6, 26, ' وألقانة . بنو ألقانة : صوفاي ابنه ، ونحث ابنه '),
(444, '1 Chronicles', 13, 6, 27, ' وأليآب ابنه ، ويروحام ابنه ، وألقانة ابنه '),
(445, '1 Chronicles', 13, 6, 28, ' وابنا صموئيل : البكر وشني ثم أبيا '),
(446, '1 Chronicles', 13, 6, 29, ' بنو مراري : محلي ، ولبني ابنه ، وشمعي ابنه ، وعزة ابنه '),
(447, '1 Chronicles', 13, 6, 30, ' وشمعى ابنه ، وحجيا ابنه ، وعسايا ابنه '),
(448, '1 Chronicles', 13, 6, 31, ' وهؤلاء هم الذين أقامهم داود على يد الغناء في بيت الرب بعدما استقر التابوت '),
(449, '1 Chronicles', 13, 6, 32, ' وكانوا يخدمون أمام مسكن خيمة الاجتماع بالغناء إلى أن بنى سليمان بيت الرب في أورشليم ، فقاموا على خدمتهم حسب ترتيبهم '),
(450, '1 Chronicles', 13, 6, 33, ' وهؤلاء هم القائمون مع بنيهم . من بني القهاتيين : هيمان المغني ابن يوئيل بن صموئيل '),
(451, '1 Chronicles', 13, 6, 34, ' بن ألقانة بن يروحام بن إيليئيل بن توح '),
(452, '1 Chronicles', 13, 6, 35, ' بن صوف بن ألقانة بن محث بن عماساي '),
(453, '1 Chronicles', 13, 6, 36, ' بن ألقانة بن يوئيل بن عزريا بن صفنيا '),
(454, '1 Chronicles', 13, 6, 37, ' بن تحث بن أسير بن أبياساف بن قورح '),
(455, '1 Chronicles', 13, 6, 38, ' بن يصهار بن قهات بن لاوي بن إسرائيل '),
(456, '1 Chronicles', 13, 6, 39, ' وأخوه آساف الواقف عن يمينه . آساف بن برخيا بن شمعي '),
(457, '1 Chronicles', 13, 6, 40, ' بن ميخائيل بن بعسيا بن ملكيا '),
(458, '1 Chronicles', 13, 6, 41, ' بن أثناي بن زارح بن عدايا '),
(459, '1 Chronicles', 13, 6, 42, ' بن أيثان بن زمة بن شمعي '),
(460, '1 Chronicles', 13, 6, 43, ' بن يحث بن جرشوم بن لاوي '),
(461, '1 Chronicles', 13, 6, 44, ' وبنو مراري إخوتهم عن اليسار . أيثان بن قيشي بن عبدي بن ملوخ '),
(462, '1 Chronicles', 13, 6, 45, ' بن حشبيا بن أمصيا بن حلقيا '),
(463, '1 Chronicles', 13, 6, 46, ' بن أمصي بن باني بن شامر '),
(464, '1 Chronicles', 13, 6, 47, ' بن محلي بن موشي بن مراري بن لاوي '),
(465, '1 Chronicles', 13, 6, 48, ' وإخوتهم اللاويون مقامون لكل خدمة مسكن بيت الله '),
(466, '1 Chronicles', 13, 6, 49, ' وأما هارون وبنوه فكانوا يوقدون على مذبح المحرقة وعلى مذبح البخور مع كل عمل قدس الأقداس ، وللتكفير عن إسرائيل حسب كل ما أمر به موسى عبد الله '),
(467, '1 Chronicles', 13, 6, 50, ' وهؤلاء بنو هارون : ألعازار ابنه ، وفينحاس ابنه ، وأبيشوع ابنه '),
(468, '1 Chronicles', 13, 6, 51, ' وبقي ابنه ، وعزي ابنه ، وزرحيا ابنه '),
(469, '1 Chronicles', 13, 6, 52, ' ومرايوث ابنه ، وأمريا ابنه ، وأخيطوب ابنه '),
(470, '1 Chronicles', 13, 6, 53, ' وصادوق ابنه ، وأخيمعص ابنه '),
(471, '1 Chronicles', 13, 6, 54, ' وهذه مساكنهم مع ضياعهم وتخومهم : لبني هارون ، لعشيرة القهاتيين لأنه لهم كانت القرعة '),
(472, '1 Chronicles', 13, 6, 55, ' وأعطوهم حبرون في أرض يهوذا ومسارحها حواليها '),
(473, '1 Chronicles', 13, 6, 56, ' وأما حقل المدينة وديارها فأعطوها لكالب بن يفنة '),
(474, '1 Chronicles', 13, 6, 57, ' وأعطوا لبني هارون مدن الملجإ حبرون ولبنة ومسارحها ، ويتير وأشتموع ومسارحها '),
(475, '1 Chronicles', 13, 6, 58, ' وحيلين ومسارحها ، ودبير ومسارحها '),
(476, '1 Chronicles', 13, 6, 59, ' وعاشان ومسارحها ، وبيتشمس ومسارحها '),
(477, '1 Chronicles', 13, 6, 60, ' ومن سبط بنيامين جبع ومسارحها ، وعلمث ومسارحها ، وعناثوث ومسارحها . جميع مدنهم ثلاث عشرة مدينة حسب عشائرهم '),
(478, '1 Chronicles', 13, 6, 61, ' ولبني قهات الباقين من عشيرة السبط من نصف السبط ، نصف منسى ، بالقرعة عشر مدن '),
(479, '1 Chronicles', 13, 6, 62, ' ولبني جرشوم حسب عشائرهم . من سبط يساكر ومن سبط أشير ومن سبط نفتالي ومن سبط منسى في باشان ثلاث عشرة مدينة '),
(480, '1 Chronicles', 13, 6, 63, ' لبني مراري حسب عشائرهم من سبط رأوبين ومن سبط جاد ومن سبط زبولون بالقرعة اثنتا عشرة مدينة '),
(481, '1 Chronicles', 13, 6, 64, ' فأعطى بنو إسرائيل اللاويين المدن ومسارحها '),
(482, '1 Chronicles', 13, 6, 65, ' وأعطوا بالقرعة من سبط يهوذا ومن سبط بني شمعون ومن سبط بني بنيامين هذه المدن التي سموها بأسماء '),
(483, '1 Chronicles', 13, 6, 66, ' وبعض عشائر بني قهات كانت مدن تخمهم من سبط أفرايم '),
(484, '1 Chronicles', 13, 6, 67, ' وأعطوهم مدن الملجإ : شكيم ومسارحها في جبل أفرايم ، وجازر ومسارحها '),
(485, '1 Chronicles', 13, 6, 68, ' ويقمعام ومسارحها ، وبيت حورون ومسارحها '),
(486, '1 Chronicles', 13, 6, 69, ' وأيلون ومسارحها ، وجت رمون ومسارحها '),
(487, '1 Chronicles', 13, 6, 70, ' ومن نصف سبط منسى : عانير ومسارحها ، وبلعام ومسارحها ، لعشيرة بني قهات الباقين '),
(488, '1 Chronicles', 13, 6, 71, ' لبني جرشوم من نصف سبط منسى : جولان في باشان ومسارحها ، وعشتاروت ومسارحها '),
(489, '1 Chronicles', 13, 6, 72, ' ومن سبط يساكر : قادش ومسارحها ، ودبرة ومسارحها ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(490, '1 Chronicles', 13, 6, 73, ' وراموت ومسارحها ، وعانيم ومسارحها '),
(491, '1 Chronicles', 13, 6, 74, ' ومن سبط أشير : مشآل ومسارحها ، وعبدون ومسارحها '),
(492, '1 Chronicles', 13, 6, 75, ' وحقوق ومسارحها ، ورحوب ومسارحها '),
(493, '1 Chronicles', 13, 6, 76, ' ومن سبط نفتالي : قادش في الجليل ومسارحها ، وحمون ومسارحها ، وقريتايم ومسارحها '),
(494, '1 Chronicles', 13, 6, 77, ' لبني مراري الباقين من سبط زبولون : رمونو ومسارحها ، وتابور ومسارحها '),
(495, '1 Chronicles', 13, 6, 78, ' وفي عبر أردن أريحا شرقي الأردن ، من سبط رأوبين : باصر في البرية ومسارحها ، ويهصة ومسارحها '),
(496, '1 Chronicles', 13, 6, 79, ' وقديموت ومسارحها ، وميفعة ومسارحها '),
(497, '1 Chronicles', 13, 6, 80, ' ومن سبط جاد : راموت في جلعاد ومسارحها ، ومحنايم ومسارحها '),
(498, '1 Chronicles', 13, 6, 81, ' وحشبون ومسارحها ، ويعزير ومسارحها '),
(499, '1 Chronicles', 13, 7, 1, ' وبنو يساكر : تولاع وفوة وياشوب وشمرون . أربعة '),
(500, '1 Chronicles', 13, 7, 2, ' وبنو تولاع : عزي ورفايا ويريئيل ويحماي ويبسام وشموئيل رؤوس بيت أبيهم تولاع جبابرة بأس حسب مواليدهم . كان عددهم في أيام داود اثنين وعشرين ألفا وست مئة '),
(501, '1 Chronicles', 13, 7, 3, ' وابن عزي يزرحيا . وبنو يزرحيا : ميخائيل وعوبديا ويوئيل ويشيا . خمسة ، كلهم رؤوس '),
(502, '1 Chronicles', 13, 7, 4, ' ومعهم حسب مواليدهم وبيوت آبائهم جيوش أجناد الحرب ستة وثلاثون ألفا ، لأنهم كثروا النساء والبنين '),
(503, '1 Chronicles', 13, 7, 5, ' وإخوتهم حسب كل عشائر يساكر جبابرة بأس ، سبعة وثمانون ألفا مجمل انتسابهم '),
(504, '1 Chronicles', 13, 7, 6, ' لبنيامين : بالع وباكر ويديعئيل . ثلاثة '),
(505, '1 Chronicles', 13, 7, 7, ' وبنو بالع : أصبون وعزي وعزيئيل ويريموث وعيري . خمسة . رؤوس بيوت آباء جبابرة بأس ، وقد انتسبوا اثنين وعشرين ألفا وأربعة وثلاثين '),
(506, '1 Chronicles', 13, 7, 8, ' وبنو باكر : زميرة ويوعاش وأليعزر وأليوعيناي وعمري ويريموث وأبيا وعناثوث وعلامث . كل هؤلاء بنو باكر '),
(507, '1 Chronicles', 13, 7, 9, ' وانتسابهم حسب مواليدهم رؤوس بيوت آبائهم جبابرة بأس عشرون ألفا ومئتان '),
(508, '1 Chronicles', 13, 7, 10, ' وابن يديعئيل بلهان ، وبنو بلهان : يعيش وبنيامين وأهود وكنعنة وزيتان وترشيش وأخيشاحر '),
(509, '1 Chronicles', 13, 7, 11, ' كل هؤلاء بنو يديعئيل حسب رؤوس الآباء جبابرة البأس سبعة عشر ألفا ومئتان من الخارجين في الجيش للحرب '),
(510, '1 Chronicles', 13, 7, 12, ' وشفيم وحفيم ابنا عير ، وحوشيم بن أحير '),
(511, '1 Chronicles', 13, 7, 13, ' بنو نفتالي : يحصيئيل وجوني ويصر وشلوم ، بنو بلهة '),
(512, '1 Chronicles', 13, 7, 14, ' بنو منسى : إشريئيل ، الذي ولدته سريته الأرامية . ولدت ماكير أبا جلعاد '),
(513, '1 Chronicles', 13, 7, 15, ' وماكير اتخذ امرأة أخت حفيم وشفيم واسمها معكة . واسم ابنه الثاني صلفحاد . وكان لصلفحاد بنات '),
(514, '1 Chronicles', 13, 7, 16, ' وولدت معكة امرأة ماكير ابنا ودعت اسمه فرش ، واسم أخيه شارش ، وابناه : أولام وراقم '),
(515, '1 Chronicles', 13, 7, 17, ' وابن أولام : بدان . هؤلاء بنو جلعاد بن ماكير بن منسى '),
(516, '1 Chronicles', 13, 7, 18, ' وأخته همولكة ولدت إيشهود وأبيعزر ومحلة '),
(517, '1 Chronicles', 13, 7, 19, ' وكان بنو شميداع : أخيان وشكيم ولقحي وأنيعام '),
(518, '1 Chronicles', 13, 7, 20, ' وبنو أفرايم : شوتالح وبرد ابنه ، وتحث ابنه ، وألعادا ابنه ، وتحث ابنه '),
(519, '1 Chronicles', 13, 7, 21, ' وزاباد ابنه ، وشوتالح ابنه وعزر وألعاد ، وقتلهم رجال جت المولودون في الأرض لأنهم نزلوا ليسوقوا ماشيتهم '),
(520, '1 Chronicles', 13, 7, 22, ' وناح أفرايم أبوهم أياما كثيرة وأتى إخوته ليعزوه '),
(521, '1 Chronicles', 13, 7, 23, ' ودخل على امرأته فحبلت وولدت ابنا ، فدعا اسمه بريعة ، لأن بلية كانت في بيته '),
(522, '1 Chronicles', 13, 7, 24, ' وبنته شيرة . وقد بنت بيت حورون السفلى والعليا وأزين شيرة '),
(523, '1 Chronicles', 13, 7, 25, ' ورفح ابنه ، ورشف ، وتلح ابنه ، وتاحن ابنه '),
(524, '1 Chronicles', 13, 7, 26, ' ولعدان ابنه ، وعميهود ابنه ، وأليشمع ابنه '),
(525, '1 Chronicles', 13, 7, 27, ' ونون ابنه ، ويهوشوع ابنه '),
(526, '1 Chronicles', 13, 7, 28, ' وأملاكهم ومساكنهم : بيت إيل وقراها ، وشرقا نعران ، وغربا جازر وقراها ، وشكيم وقراها ، إلى غزة وقراها '),
(527, '1 Chronicles', 13, 7, 29, ' ولجهة بني منسى بيت شان وقراها ، وتعنك وقراها ، ومجدو وقراها ، ودور وقراها . في هذه سكن بنو يوسف بن إسرائيل '),
(528, '1 Chronicles', 13, 7, 30, ' بنو أشير : يمنة ويشوة ويشوي وبريعة وسارح أختهم '),
(529, '1 Chronicles', 13, 7, 31, ' وابنا بريعة : حابر وملكيئيل . هو أبو برزاوث '),
(530, '1 Chronicles', 13, 7, 32, ' وحابر ولد يفليط وشومير وحوثام وشوعا أختهم '),
(531, '1 Chronicles', 13, 7, 33, ' وبنو يفليط : فاسك وبمهال وعشوة . هؤلاء بنو يفليط '),
(532, '1 Chronicles', 13, 7, 34, ' وبنو شامر : آخي ورهجة ويحبة وأرام '),
(533, '1 Chronicles', 13, 7, 35, ' وبنو هيلام أخيه : صوفح ويمناع وشالش وعامال '),
(534, '1 Chronicles', 13, 7, 36, ' وبنو صوفح : سوح وحرنفر وشوعال وبيري ويمرة '),
(535, '1 Chronicles', 13, 7, 37, ' وباصر وهود وشما وشلشة ويثران وبئيرا '),
(536, '1 Chronicles', 13, 7, 38, ' وبنو يثر : يفنة وفسفة وأرا '),
(537, '1 Chronicles', 13, 7, 39, ' وبنو علا : آرح وحنيئيل ورصيا '),
(538, '1 Chronicles', 13, 7, 40, ' كل هؤلاء بنو أشير رؤوس بيوت آباء منتخبون جبابرة بأس ، رؤوس الرؤساء وانتسابهم في الجيش في الحرب ، عددهم من الرجال ستة وعشرون ألفا '),
(539, '1 Chronicles', 13, 8, 1, ' وبنيامين ولد : بالع بكره ، وأشبيل الثاني ، وأخرخ الثالث '),
(540, '1 Chronicles', 13, 8, 2, ' ونوحة الرابع ، ورافا الخامس '),
(541, '1 Chronicles', 13, 8, 3, ' وكان بنو بالع : أدار وجيرا وأبيهود '),
(542, '1 Chronicles', 13, 8, 4, ' وأبيشوع ونعمان وأخوخ '),
(543, '1 Chronicles', 13, 8, 5, ' وحيرا وشفوفان وحورام '),
(544, '1 Chronicles', 13, 8, 6, ' وهؤلاء بنو آحود . هؤلاء رؤوس آباء سكان جبع ، ونقلوهم إلى مناحة '),
(545, '1 Chronicles', 13, 8, 7, ' أي : نعمان وأخيا . وجيرا هو نقلهم ، وولد : عزا وأخيحود '),
(546, '1 Chronicles', 13, 8, 8, ' وشحرايم ولد في بلاد موآب بعد إطلاقه امرأتيه حوشيم وبعرا '),
(547, '1 Chronicles', 13, 8, 9, ' وولد من خودش امرأته : يوباب وظبيا وميشا وملكام '),
(548, '1 Chronicles', 13, 8, 10, ' ويعوص وشبيا ومرمة . هؤلاء بنو رؤوس آباء '),
(549, '1 Chronicles', 13, 8, 11, ' ومن حوشيم ولد : أبيطوب وألفعل '),
(550, '1 Chronicles', 13, 8, 12, ' وبنو ألفعل : عابر ومشعام وشامر ، وهو بنى أونو ولود وقراها '),
(551, '1 Chronicles', 13, 8, 13, ' وبريعة وشمع . هما رأسا آباء لسكان أيلون ، وهما طردا سكان جت '),
(552, '1 Chronicles', 13, 8, 14, ' وأخيو وشاشق ويريموت '),
(553, '1 Chronicles', 13, 8, 15, ' وزبديا وعراد وعادر '),
(554, '1 Chronicles', 13, 8, 16, ' وميخائيل ويشفة ويوخا ، أبناء بريعة '),
(555, '1 Chronicles', 13, 8, 17, ' وزبديا ومشلام وحزقي وحابر '),
(556, '1 Chronicles', 13, 8, 18, ' ويشمراي ويزلياه ويوباب ، أبناء ألفعل '),
(557, '1 Chronicles', 13, 8, 19, ' وياقيم وزكري وزبدي '),
(558, '1 Chronicles', 13, 8, 20, ' وأليعيناي وصلتاي وإيليئيل '),
(559, '1 Chronicles', 13, 8, 21, ' وعدايا وبرايا وشمرة ، أبناء شمعي '),
(560, '1 Chronicles', 13, 8, 22, ' ويشفان وعابر وإيليئيل '),
(561, '1 Chronicles', 13, 8, 23, ' وعبدون وزكري وحانان '),
(562, '1 Chronicles', 13, 8, 24, ' وحننيا وعيلام وعنثوثيا '),
(563, '1 Chronicles', 13, 8, 25, ' ويفديا وفنوئيل ، أبناء شاشق '),
(564, '1 Chronicles', 13, 8, 26, ' وشمشراي وشحريا وعثليا '),
(565, '1 Chronicles', 13, 8, 27, ' ويعرشيا وإيليا وزكري ، أبناء يروحام '),
(566, '1 Chronicles', 13, 8, 28, ' هؤلاء رؤوس آباء . حسب مواليدهم رؤوس . هؤلاء سكنوا في أورشليم '),
(567, '1 Chronicles', 13, 8, 29, ' وفي جبعون سكن أبو جبعون ، واسم امرأته معكة '),
(568, '1 Chronicles', 13, 12, 27, ' ويهوياداع رئيس الهرونيين ومعه ثلاثة آلاف وسبع مئة '),
(569, '1 Chronicles', 13, 12, 28, ' وصادوق غلام جبار بأس وبيت أبيه اثنان وعشرون قائدا '),
(570, '1 Chronicles', 13, 12, 29, ' ومن بني بنيامين إخوة شاول ثلاثة آلاف ، وإلى هنا كان أكثرهم يحرسون حراسة بيت شاول '),
(571, '1 Chronicles', 13, 12, 30, ' ومن بني أفرايم عشرون ألفا وثمان مئة ، جبابرة بأس وذوو اسم في بيوت آبائهم '),
(572, '1 Chronicles', 13, 12, 31, ' ومن نصف سبط منسى ثمانية عشر ألفا قد تعينوا بأسمائهم لكي يأتوا ويملكوا داود '),
(573, '1 Chronicles', 13, 12, 32, ' ومن بني يساكر الخبيرين بالأوقات لمعرفة ما يعمل إسرائيل ، رؤوسهم مئتان ، وكل إخوتهم تحت أمرهم '),
(574, '1 Chronicles', 13, 12, 33, ' من زبولون الخارجون للقتال المصطفون للحرب بجميع أدوات الحرب خمسون ألفا ، وللاصطفاف من دون خلاف '),
(575, '1 Chronicles', 13, 12, 34, ' ومن نفتالي ألف رئيس ومعهم سبعة وثلاثون ألفا بالأتراس والرماح '),
(576, '1 Chronicles', 13, 12, 35, ' ومن الدانيين مصطفون للحرب ثمانية وعشرون ألفا وست مئة '),
(577, '1 Chronicles', 13, 12, 36, ' ومن أشير الخارجون للجيش لأجل الاصطفاف للحرب أربعون ألفا '),
(578, '1 Chronicles', 13, 12, 37, ' ومن عبر الأردن : من الرأوبينيين والجاديين ونصف سبط منسى ، بجميع أدوات جيش الحرب مئة وعشرون ألفا '),
(579, '1 Chronicles', 13, 12, 38, ' كل هؤلاء رجال حرب يصطفون صفوفا ، أتوا بقلب تام إلى حبرون ليملكوا داود على كل إسرائيل . وكذلك كل بقية إسرائيل بقلب واحد لتمليك داود '),
(580, '1 Chronicles', 13, 12, 39, ' وكانوا هناك مع داود ثلاثة أيام يأكلون ويشربون لأن إخوتهم أعدوا لهم '),
(581, '1 Chronicles', 13, 12, 40, ' وكذلك القريبون منهم حتى يساكر وزبولون ونفتالي ، كانوا يأتون بخبز على الحمير والجمال والبغال والبقر ، وبطعام من دقيق وتين وزبيب وخمر وزيت ، وبقر وغنم بكثرة ، لأنه كان فرح في إسرائيل '),
(582, '1 Chronicles', 13, 13, 1, ' وشاور داود قواد الألوف والمئات وكل رئيس '),
(583, '1 Chronicles', 13, 13, 2, ' وقال داود لكل جماعة إسرائيل : إن حسن عندكم وكان ذلك من الرب إلهنا ، فلنرسل إلى كل جهة ، إلى إخوتنا الباقين في كل أراضي إسرائيل ومعهم الكهنة واللاويون في مدن مسارحهم ليجتمعوا إلينا '),
(584, '1 Chronicles', 13, 13, 3, ' فنرجع تابوت إلهنا إلينا لأننا لم نسأل به في أيام شاول '),
(585, '1 Chronicles', 13, 13, 4, ' فقال كل الجماعة بأن يفعلوا ذلك ، لأن الأمر حسن في أعين جميع الشعب '),
(586, '1 Chronicles', 13, 13, 5, ' وجمع داود كل إسرائيل من شيحور مصر إلى مدخل حماة ليأتوا بتابوت الله من قرية يعاريم '),
(587, '1 Chronicles', 13, 13, 6, ' وصعد داود وكل إسرائيل إلى بعلة ، إلى قرية يعاريم التي ليهوذا ، ليصعدوا من هناك تابوت الله الرب الجالس على الكروبيم الذي دعي بالاسم '),
(588, '1 Chronicles', 13, 13, 7, ' وأركبوا تابوت الله على عجلة جديدة من بيت أبيناداب ، وكان عزا وأخيو يسوقان العجلة '),
(589, '1 Chronicles', 13, 13, 8, ' وداود وكل إسرائيل يلعبون أمام الله بكل عز وبأغاني وعيدان ورباب ودفوف وصنوج وأبواق '),
(590, '1 Chronicles', 13, 13, 9, ' ولما انتهوا إلى بيدر كيدون ، مد عزا يده ليمسك التابوت ، لأن الثيران انشمصت '),
(591, '1 Chronicles', 13, 13, 10, ' فحمي غضب الرب على عزا وضربه من أجل أنه مد يده إلى التابوت ، فمات هناك أمام الله '),
(592, '1 Chronicles', 13, 13, 11, ' فاغتاظ داود لأن الرب اقتحم عزا اقتحاما ، وسمى ذلك الموضع فارص عزا إلى هذا اليوم '),
(593, '1 Chronicles', 13, 13, 12, ' وخاف داود الله في ذلك اليوم قائلا : كيف آتي بتابوت الله إلي '),
(594, '1 Chronicles', 13, 13, 13, ' ولم ينقل داود التابوت إليه إلى مدينة داود ، بل مال به إلى بيت عوبيد أدوم الجتي '),
(595, '1 Chronicles', 13, 13, 14, ' وبقي تابوت الله عند بيت عوبيد أدوم في بيته ثلاثة أشهر . وبارك الرب بيت عوبيد أدوم وكل ما له '),
(596, '1 Chronicles', 13, 14, 1, ' وأرسل حيرام ملك صور رسلا إلى داود وخشب أرز وبنائين ونجارين ، ليبنوا له بيتا '),
(597, '1 Chronicles', 13, 14, 2, ' وعلم داود أن الرب قد أثبته ملكا على إسرائيل ، لأن مملكته ارتفعت متصاعدة من أجل شعبه إسرائيل '),
(598, '1 Chronicles', 13, 14, 3, ' وأخذ داود نساء أيضا في أورشليم ، وولد أيضا داود بنين وبنات '),
(599, '1 Chronicles', 13, 14, 4, ' وهذه أسماء الأولاد الذين كانوا له في أورشليم : شموع وشوباب وناثان وسليمان '),
(600, '1 Chronicles', 13, 14, 5, ' ويبحار وأليشوع وألفالط '),
(601, '1 Chronicles', 13, 14, 6, ' ونوجه ونافج ويافيع '),
(602, '1 Chronicles', 13, 14, 7, ' وأليشمع وبعلياداع وأليفلط '),
(603, '1 Chronicles', 13, 14, 8, ' وسمع الفلسطينيون أن داود قد مسح ملكا على كل إسرائيل ، فصعد كل الفلسطينيين ليفتشوا على داود . ولما سمع داود خرج لاستقبالهم '),
(604, '1 Chronicles', 13, 14, 9, ' فجاء الفلسطينيون وانتشروا في وادي الرفائيين '),
(605, '1 Chronicles', 13, 14, 10, ' فسأل داود من الله قائلا : أأصعد على الفلسطينيين فتدفعهم ليدي ؟  . فقال له الرب : اصعد فأدفعهم ليدك '),
(606, '1 Chronicles', 13, 14, 11, ' فصعدوا إلى بعل فراصيم وضربهم داود هناك . وقال داود : قد اقتحم الله أعدائي بيدي كاقتحام المياه . لذلك دعوا اسم ذلك الموضع بعل فراصيم '),
(607, '1 Chronicles', 13, 14, 12, ' وتركوا هناك آلهتهم ، فأمر داود فأحرقت بالنار '),
(608, '1 Chronicles', 13, 14, 13, ' ثم عاد الفلسطينيون أيضا وانتشروا في الوادي '),
(609, '1 Chronicles', 13, 14, 14, ' فسأل أيضا داود من الله ، فقال له الله : لا تصعد وراءهم ، تحول عنهم وهلم عليهم مقابل أشجار البكا '),
(610, '1 Chronicles', 13, 14, 15, ' وعندما تسمع صوت خطوات في رؤوس أشجار البكا فاخرج حينئذ للحرب ، لأن الله يخرج أمامك لضرب محلة الفلسطينيين '),
(611, '1 Chronicles', 13, 14, 16, ' ففعل داود كما أمره الله ، وضربوا محلة الفلسطينيين من جبعون إلى جازر '),
(612, '1 Chronicles', 13, 14, 17, ' وخرج اسم داود إلى جميع الأراضي ، وجعل الرب هيبته على جميع الأمم '),
(613, '1 Chronicles', 13, 15, 1, ' وعمل داود لنفسه بيوتا في مدينة داود ، وأعد مكانا لتابوت الله ونصب له خيمة '),
(614, '1 Chronicles', 13, 15, 2, ' حينئذ قال داود : ليس لأحد أن يحمل تابوت الله إلا للاويين ، لأن الرب إنما اختارهم لحمل تابوت الله ولخدمته إلى الأبد '),
(615, '1 Chronicles', 13, 15, 3, ' وجمع داود كل إسرائيل إلى أورشليم لأجل إصعاد تابوت الرب إلى مكانه الذي أعده له '),
(616, '1 Chronicles', 13, 15, 4, ' فجمع داود بني هارون واللاويين '),
(617, '1 Chronicles', 13, 15, 5, ' من بني قهات : أوريئيل الرئيس ، وإخوته مئة وعشرين '),
(618, '1 Chronicles', 13, 15, 6, ' من بني مراري : عسايا الرئيس ، وإخوته مئتين وعشرين '),
(619, '1 Chronicles', 13, 15, 7, ' من بني جرشوم : يوئيل الرئيس ، وإخوته مئة وثلاثين '),
(620, '1 Chronicles', 13, 15, 8, ' من بني أليصافان : شمعيا الرئيس ، وإخوته مئتين '),
(621, '1 Chronicles', 13, 15, 9, ' من بني حبرون : إيليئيل الرئيس ، وإخوته ثمانين '),
(622, '1 Chronicles', 13, 15, 10, ' من بني عزيئيل : عميناداب ، الرئيس ، وإخوته مئة واثني عشر '),
(623, '1 Chronicles', 13, 15, 11, ' ودعا داود صادوق وأبياثار الكاهنين واللاويين : أوريئيل وعسايا ويوئيل وشمعيا وإيليئيل وعميناداب '),
(624, '1 Chronicles', 13, 15, 12, ' وقال لهم : أنتم رؤوس آباء اللاويين ، فتقدسوا أنتم وإخوتكم وأصعدوا تابوت الرب إله إسرائيل إلى حيث أعددت له '),
(625, '1 Chronicles', 13, 15, 13, ' لأنه إذ لم تكونوا في المرة الأولى ، اقتحمنا الرب إلهنا ، لأننا لم نسأله حسب المرسوم '),
(626, '1 Chronicles', 13, 15, 14, ' فتقدس الكهنة واللاويون ليصعدوا تابوت الرب إله إسرائيل '),
(627, '1 Chronicles', 13, 15, 15, ' وحمل بنو اللاويين تابوت الله ، كما أمر موسى حسب كلام الرب بالعصي على أكتافهم '),
(628, '1 Chronicles', 13, 15, 16, ' وأمر داود رؤساء اللاويين أن يوقفوا إخوتهم المغنين بآلات غناء ، بعيدان ورباب وصنوج ، مسمعين برفع الصوت بفرح '),
(629, '1 Chronicles', 13, 15, 17, ' فأوقف اللاويون هيمان بن يوئيل ، ومن إخوته آساف بن برخيا ، ومن بني مراري إخوتهم إيثان بن قوشيا '),
(630, '1 Chronicles', 13, 15, 18, ' ومعهم إخوتهم الثواني : زكريا وبين ويعزئيل وشميراموث ويحيئيل وعني وأليآب وبنايا ومعسيا ومتثيا وأليفليا ومقنيا وعوبيد أدوم ويعيئيل البوابين '),
(631, '1 Chronicles', 13, 15, 19, ' والمغنون : هيمان وآساف وإيثان بصنوج نحاس للتسميع '),
(632, '1 Chronicles', 13, 15, 20, ' وزكريا وعزيئيل وشميراموث ويحيئيل وعني وألياب ومعسيا وبنايا بالرباب على الجواب '),
(633, '1 Chronicles', 13, 15, 21, ' ومتثيا وأليفليا ومقنيا وعوبيد أدوم ويعيئيل وعززيا بالعيدان على القرار للإمامة '),
(634, '1 Chronicles', 13, 15, 22, ' وكننيا رئيس اللاويين على الحمل مرشدا في الحمل لأنه كان خبيرا '),
(635, '1 Chronicles', 13, 15, 23, ' وبرخيا وألقانة بوابان للتابوت '),
(636, '1 Chronicles', 13, 15, 24, ' وشبنيا ويوشافاط ونثنئيل وعماساي وزكريا وبنايا وأليعزر الكهنة ينفخون بالأبواق أمام تابوت الله ، وعوبيد أدوم ويحيى بوابان للتابوت '),
(637, '1 Chronicles', 13, 15, 25, ' وكان داود وشيوخ إسرائيل ورؤساء الألوف هم الذين ذهبوا لإصعاد تابوت عهد الرب ، من بيت عوبيد أدوم بفرح '),
(638, '1 Chronicles', 13, 22, 2, ' وأمر داود بجمع الأجنبيين الذين في أرض إسرائيل ، وأقام نحاتين لنحت حجارة مربعة لبناء بيت الله '),
(639, '1 Chronicles', 13, 22, 3, ' وهيأ داود حديدا كثيرا للمسامير لمصاريع الأبواب وللوصل ، ونحاسا كثيرا بلا وزن '),
(640, '1 Chronicles', 13, 22, 4, ' وخشب أرز لم يكن له عدد لأن الصيدونيين والصوريين أتوا بخشب أرز كثير إلى داود '),
(641, '1 Chronicles', 13, 22, 5, ' وقال داود : إن سليمان ابني صغير وغض ، والبيت الذي يبنى للرب يكون عظيما جدا في الاسم والمجد في جميع الأراضي ، فأنا أهيئ له . فهيأ داود كثيرا قبل وفاته '),
(642, '1 Chronicles', 13, 22, 6, ' ودعا سليمان ابنه وأوصاه أن يبني بيتا للرب إله إسرائيل '),
(643, '1 Chronicles', 13, 22, 7, ' وقال داود لسليمان : يا ابني ، قد كان في قلبي أن أبني بيتا لاسم الرب إلهي '),
(644, '1 Chronicles', 13, 22, 8, ' فكان إلي كلام الرب قائلا : قد سفكت دما كثيرا وعملت حروبا عظيمة ، فلا تبني بيتا لاسمي لأنك سفكت دماء كثيرة على الأرض أمامي '),
(645, '1 Chronicles', 13, 22, 9, ' هوذا يولد لك ابن يكون صاحب راحة ، وأريحه من جميع أعدائه حواليه ، لأن اسمه يكون سليمان . فأجعل سلاما وسكينة في إسرائيل في أيامه '),
(646, '1 Chronicles', 13, 22, 10, ' هو يبني بيتا لاسمي ، وهو يكون لي ابنا ، وأنا له أبا وأثبت كرسي ملكه على إسرائيل إلى الأبد '),
(647, '1 Chronicles', 13, 22, 11, ' الآن يا ابني ، ليكن الرب معك فتفلح وتبني بيت الرب إلهك ، كما تكلم عنك '),
(648, '1 Chronicles', 13, 22, 12, ' إنما يعطيك الرب فطنة وفهما ويوصيك بإسرائيل لحفظ شريعة الرب إلهك '),
(649, '1 Chronicles', 13, 22, 13, ' حينئذ تفلح إذا تحفظت لعمل الفرائض والأحكام التي أمر بها الرب موسى لأجل إسرائيل . تشدد وتشجع لا تخف ولا ترتعب '),
(650, '1 Chronicles', 13, 22, 14, ' هأنذا في مذلتي هيأت لبيت الرب ذهبا مئة ألف وزنة ، وفضة ألف ألف وزنة ، ونحاسا وحديدا بلا وزن لأنه كثير . وقد هيأت خشبا وحجارة فتزيد عليها '),
(651, '1 Chronicles', 13, 22, 15, ' وعندك كثيرون من عاملي الشغل : نحاتين وبنائين ونجارين وكل حكيم في كل عمل '),
(652, '1 Chronicles', 13, 22, 16, ' الذهب والفضة والنحاس والحديد ليس لها عدد . قم واعمل ، وليكن الرب معك '),
(653, '1 Chronicles', 13, 22, 17, ' وأمر داود جميع رؤساء إسرائيل أن يساعدوا سليمان ابنه '),
(654, '1 Chronicles', 13, 22, 18, ' أليس الرب إلهكم معكم ، وقد أراحكم من كل ناحية ، لأنه دفع ليدي سكان الأرض فخضعت الأرض أمام الرب وأمام شعبه '),
(655, '1 Chronicles', 13, 22, 19, ' فالآن اجعلوا قلوبكم وأنفسكم لطلب الرب إلهكم ، وقوموا وابنوا مقدس الرب الإله ، ليؤتى بتابوت عهد الرب وبآنية قدس الله إلى البيت الذي يبنى لاسم الرب '),
(656, '1 Chronicles', 13, 23, 1, ' ولما شاخ داود وشبع أياما ملك سليمان ابنه على إسرائيل '),
(657, '1 Chronicles', 13, 23, 2, ' وجمع كل رؤساء إسرائيل والكهنة واللاويين '),
(658, '1 Chronicles', 13, 23, 3, ' فعد اللاويون من ابن ثلاثين سنة فما فوق ، فكان عددهم حسب رؤوسهم من الرجال ثمانية وثلاثين ألفا '),
(659, '1 Chronicles', 13, 23, 4, ' من هؤلاء للمناظرة على عمل بيت الرب أربعة وعشرون ألفا . وستة آلاف عرفاء وقضاة '),
(660, '1 Chronicles', 13, 23, 5, ' وأربعة آلاف بوابون ، وأربعة آلاف مسبحون للرب بالآلات التي عملت للتسبيح '),
(661, '1 Chronicles', 13, 23, 6, ' وقسمهم داود فرقا لبني لاوي : لجرشون وقهات ومراري '),
(662, '1 Chronicles', 13, 23, 7, ' من الجرشونيين : لعدان وشمعي '),
(663, '1 Chronicles', 13, 23, 8, ' بنو لعدان : الرأس يحيئيل ثم زيثام ويوئيل ، ثلاثة '),
(664, '1 Chronicles', 13, 23, 9, ' بنو شمعي : شلوميث وحزيئيل وهاران ، ثلاثة . هؤلاء رؤوس آباء للعدان '),
(665, '1 Chronicles', 13, 23, 10, ' وبنو شمعي : يحث وزينا ويعوش وبريعة . هؤلاء بنو شمعي ، أربعة '),
(666, '1 Chronicles', 13, 23, 11, ' وكان يحث الرأس وزيزة الثاني . أما يعوش وبريعة فلم يكثرا الأولاد ، فكانوا في الإحصاء لبيت أب واحد '),
(667, '1 Chronicles', 13, 23, 12, ' بنو قهات : عمرام ويصهار وحبرون وعزيئيل ، أربعة '),
(668, '1 Chronicles', 13, 23, 13, ' ابنا عمرام : هارون وموسى ، وأفرز هارون لتقديسه قدس أقداس هو وبنوه إلى الأبد ، ليوقد أمام الرب ويخدمه ويبارك باسمه إلى الأبد '),
(669, '1 Chronicles', 13, 23, 14, ' وأما موسى رجل الله فدعي بنوه مع سبط لاوي '),
(670, '1 Chronicles', 13, 23, 15, ' ابنا موسى : جرشوم وأليعزر '),
(671, '1 Chronicles', 13, 23, 16, ' بنو جرشوم : شبوئيل الرأس '),
(672, '1 Chronicles', 13, 23, 17, ' وكان ابن أليعزر : رحبيا الرأس ، ولم يكن لأليعزر بنون آخرون . وأما بنو رحبيا فكانوا كثيرين جدا '),
(673, '1 Chronicles', 13, 23, 18, ' بنو يصهار : شلوميث الرأس '),
(674, '1 Chronicles', 13, 23, 19, ' بنو حبرون : يريا الرأس ، وأمريا الثاني ، ويحزيئيل الثالث ، ويقمعام الرابع '),
(675, '1 Chronicles', 13, 23, 20, ' ابنا عزيئيل : ميخا الرأس ، ويشيا الثاني '),
(676, '1 Chronicles', 13, 23, 21, ' ابنا مراري : محلي وموشي . ابنا محلي : ألعازار وقيس '),
(677, '1 Chronicles', 13, 23, 22, ' ومات ألعازار ولم يكن له بنون بل بنات ، فأخذهن بنو قيس إخوتهن '),
(678, '1 Chronicles', 13, 23, 23, ' بنو موشي : محلي وعادر ويريموث ، ثلاثة '),
(679, '1 Chronicles', 13, 23, 24, ' هؤلاء بنو لاوي حسب بيوت آبائهم رؤوس الآباء ، حسب إحصائهم في عدد الأسماء ، حسب رؤوسهم عاملو العمل لخدمة بيت الرب ، من ابن عشرين سنة فما فوق '),
(680, '1 Chronicles', 13, 23, 25, ' لأن داود قال : قد أراح الرب إله إسرائيل شعبه فسكن في أورشليم إلى الأبد '),
(681, '1 Chronicles', 13, 23, 26, ' وليس للاويين بعد أن يحملوا المسكن وكل آنيته لخدمته '),
(682, '1 Chronicles', 13, 23, 27, ' لأنه حسب كلام داود الأخير عد بنو لاوي من ابن عشرين سنة فما فوق '),
(683, '1 Chronicles', 13, 23, 28, ' لأنهم كانوا يقفون بين يدي بني هارون على خدمة بيت الرب في الدور والمخادع ، وعلى تطهير كل قدس وعمل خدمة بيت الله '),
(684, '1 Chronicles', 13, 23, 29, ' وعلى خبز الوجوه ودقيق التقدمة ورقاق الفطير وما يعمل على الصاج والمربوكات وعلى كل كيل وقياس '),
(685, '1 Chronicles', 13, 23, 30, ' ولأجل الوقوف كل صباح لحمد الرب وتسبيحه وكذلك في المساء '),
(686, '1 Chronicles', 13, 23, 31, ' ولكل إصعاد محرقات للرب في السبوت والأهلة والمواسم بالعدد حسب المرسوم عليهم دائما أمام الرب '),
(687, '1 Chronicles', 13, 23, 32, ' وليحرسوا حراسة خيمة الاجتماع ، وحراسة القدس ، وحراسة بني هارون إخوتهم في خدمة بيت الرب '),
(688, '1 Chronicles', 13, 24, 1, ' وهذه فرق بني هارون : بنو هارون : ناداب وأبيهو ، ألعازار وإيثامار '),
(689, '1 Chronicles', 13, 24, 2, ' ومات ناداب وأبيهو قبل أبيهما ولم يكن لهما بنون ، فكهن ألعازار وإيثامار '),
(690, '1 Chronicles', 13, 24, 3, ' وقسمهم داود وصادوق من بني ألعازار ، وأخيمالك من بني إيثامار ، حسب وكالتهم في خدمتهم '),
(691, '1 Chronicles', 13, 24, 4, ' ووجد لبني ألعازار رؤوس رجال أكثر من بني إيثامار ، فانقسموا لبني ألعازار رؤوسا لبيت آبائهم ستة عشر ، ولبني إيثامار لبيت آبائهم ثمانية '),
(692, '1 Chronicles', 13, 24, 5, ' وانقسموا بالقرعة ، هؤلاء مع هؤلاء ، لأن رؤساء القدس ورؤساء بيت الله كانوا من بني ألعازار ومن بني إيثامار '),
(693, '1 Chronicles', 13, 24, 6, ' وكتبهم شمعيا بن نثنئيل الكاتب من اللاويين أمام الملك والرؤساء وصادوق الكاهن وأخيمالك بن أبياثار ورؤوس الآباء للكهنة واللاويين . فأخذ بيت أب واحد لألعازار ، وأخذ واحد لإيثامار '),
(694, '1 Chronicles', 13, 24, 7, ' فخرجت القرعة الأولى ليهوياريب . الثانية ليدعيا '),
(695, '1 Chronicles', 13, 24, 8, ' الثالثة لحاريم . الرابعة لسعوريم '),
(696, '1 Chronicles', 13, 24, 9, ' الخامسة لملكيا . السادسة لميامين '),
(697, '1 Chronicles', 13, 24, 10, ' السابعة لهقوص . الثامنة لأبيا '),
(698, '1 Chronicles', 13, 24, 11, ' التاسعة ليشوع . العاشرة لشكنيا '),
(699, '1 Chronicles', 13, 24, 12, ' الحادية عشرة لألياشيب . الثانية عشرة لياقيم '),
(700, '1 Chronicles', 13, 24, 13, ' الثالثة عشرة لحفة . الرابعة عشرة ليشبآب '),
(701, '1 Chronicles', 13, 24, 14, ' الخامسة عشرة لبلجة . السادسة عشرة لإيمير '),
(702, '1 Chronicles', 13, 24, 15, ' السابعة عشرة لحيزير . الثامنة عشرة لهفصيص '),
(703, '1 Chronicles', 13, 24, 16, ' التاسعة عشرة لفقحيا . العشرون ليحزقيئيل '),
(704, '1 Chronicles', 13, 24, 17, ' الحادية والعشرون لياكين . الثانية والعشرون لجامول '),
(705, '1 Chronicles', 13, 24, 18, ' الثالثة والعشرون لدلايا . الرابعة والعشرون لمعزيا '),
(706, '1 Chronicles', 13, 24, 19, ' فهذه وكالتهم وخدمتهم للدخول إلى بيت الرب حسب حكمهم عن يد هارون أبيهم ، كما أمره الرب إله إسرائيل '),
(707, '1 Chronicles', 13, 24, 20, ' وأما بنو لاوي الباقون : فمن بني عمرام : شوبائيل ، ومن بني شوبائيل : يحديا '),
(708, '1 Chronicles', 13, 27, 1, ' وبنو إسرائيل حسب عددهم من رؤوس الآباء ورؤساء الألوف والمئات وعرفاؤهم الذين يخدمون الملك في كل أمور ، الفرق الداخلين والخارجين شهرا فشهرا لكل شهور السنة ، كل فرقة كانت أربعة وعشرين ألفا '),
(709, '1 Chronicles', 13, 27, 2, ' على الفرقة الأولى للشهر الأول يشبعام بن زبديئيل ، وفي فرقته أربعة وعشرون ألفا '),
(710, '1 Chronicles', 13, 27, 3, ' من بني فارص كان رأس جميع رؤساء الجيوش للشهر الأول '),
(711, '1 Chronicles', 13, 27, 4, ' وعلى فرقة الشهر الثاني دوداي الأخوخي ، ومن فرقته مقلوث الرئيس . وفي فرقته أربعة وعشرون ألفا '),
(712, '1 Chronicles', 13, 27, 5, ' رئيس الجيش الثالث للشهر الثالث بنايا بن يهوياداع الكاهن الرأس ، وفي فرقته أربعة وعشرون ألفا '),
(713, '1 Chronicles', 13, 27, 6, ' هو بنايا جبار الثلاثين ، وعلى الثلاثين ومن فرقته عميزاباد ابنه '),
(714, '1 Chronicles', 13, 27, 7, ' الرابع للشهر الرابع عسائيل أخو يوآب وزبديا ابنه بعده ، وفي فرقته أربعة وعشرون ألفا '),
(715, '1 Chronicles', 13, 27, 8, ' الخامس للشهر الخامس الرئيس شمحوث اليزراحي ، وفي فرقته أربعة وعشرون ألفا '),
(716, '1 Chronicles', 13, 27, 9, ' السادس للشهر السادس عيرا بن عقيش التقوعي ، وفي فرقته أربعة وعشرون ألفا '),
(717, '1 Chronicles', 13, 27, 10, ' السابع للشهر السابع حالص الفلوني من بني أفرايم ، وفي فرقته أربعة وعشرون ألفا '),
(718, '1 Chronicles', 13, 27, 11, ' الثامن للشهر الثامن سبكاي الحوشاتي من الزارحيين ، وفي فرقته أربعة وعشرون ألفا '),
(719, '1 Chronicles', 13, 27, 12, ' التاسع للشهر التاسع أبيعزر العناثوثي من بنيامين ، وفي فرقته أربعة وعشرون ألفا '),
(720, '1 Chronicles', 13, 27, 13, ' العاشر للشهر العاشر مهراي النطوفاتي من الزارحيين ، وفي فرقته أربعة وعشرون ألفا '),
(721, '1 Chronicles', 13, 27, 14, ' الحادي عشر للشهر الحادي عشر بنايا الفرعتوني من بني أفرايم ، وفي فرقته أربعة وعشرون ألفا '),
(722, '1 Chronicles', 13, 27, 15, ' الثاني عشر للشهر الثاني عشر خلداي النطوفاتي من عثنئيل ، وفي فرقته أربعة وعشرون ألفا '),
(723, '1 Chronicles', 13, 27, 16, ' وعلى أسباط إسرائيل : للرأوبينيين الرئيس : أليعزر بن زكري . للشمعونيين : شفطيا بن معكة '),
(724, '1 Chronicles', 13, 27, 17, ' للاويين : حشبيا بن قموئيل . لهارون : صادوق '),
(725, '1 Chronicles', 13, 27, 18, ' ليهوذا : أليهو من إخوة داود . ليساكر : عمري بن ميخائيل '),
(726, '1 Chronicles', 13, 27, 19, ' لزبولون : يشمعيا بن عوبديا . لنفتالي : يريموث بن عزرئيل '),
(727, '1 Chronicles', 13, 27, 20, ' لبني أفرايم : هوشع بن عززيا . لنصف سبط منسى : يوئيل بن فدايا '),
(728, '1 Chronicles', 13, 27, 21, ' لنصف سبط منسى في جلعاد : يدو بن زكريا . لبنيامين : يعسيئيل بن أبنير '),
(729, '1 Chronicles', 13, 27, 22, ' لدان : عزرئيل بن يروحام . هؤلاء رؤساء أسباط إسرائيل '),
(730, '1 Chronicles', 13, 27, 23, ' ولم يأخذ داود عددهم من ابن عشرين سنة فما دون ، لأن الرب قال إنه يكثر إسرائيل كنجوم السماء '),
(731, '1 Chronicles', 13, 27, 24, ' يوآب ابن صروية ابتدأ يحصي ولم يكمل لأنه كان من جرى ذلك سخط على إسرائيل ، ولم يدون العدد في سفر أخبار الأيام للملك داود '),
(732, '1 Chronicles', 13, 27, 25, ' وعلى خزائن الملك عزموت بن عديئيل . وعلى الخزائن في الحقل في المدن والقرى والحصون يهوناثان بن عزيا '),
(733, '1 Chronicles', 13, 27, 26, ' وعلى الفعلة في الحقل لشغل الأرض عزري بن كلوب '),
(734, '1 Chronicles', 13, 27, 27, ' وعلى الكروم شمعي الرامي . وعلى ما في الكروم من خزائن الخمر زبدي الشفمي '),
(735, '1 Chronicles', 13, 27, 28, ' وعلى الزيتون والجميز اللذين في السهل بعل حانان الجديري . وعلى خزائن الزيت يوعاش '),
(736, '1 Chronicles', 13, 27, 29, ' وعلى البقر السائم في شارون شطراي الشاروني . وعلى البقر الذي في الأودية شافاط بن عدلاي '),
(737, '1 Chronicles', 13, 27, 30, ' وعلى الجمال أوبيل الإسماعيلي . وعلى الحمير يحديا الميرونوثي '),
(738, '1 Chronicles', 13, 27, 31, ' وعلى الغنم يازيز الهاجري . كل هؤلاء رؤساء الأملاك التي للملك داود '),
(739, '1 Chronicles', 13, 27, 32, ' ويهوناثان عم داود كان مشيرا ورجلا مختبرا وفقيها . ويحيئيل بن حكموني كان مع بني الملك '),
(740, '1 Chronicles', 13, 27, 33, ' وكان أخيتوفل مشيرا للملك ، وحوشاي الأركي صاحب الملك '),
(741, '1 Chronicles', 13, 27, 34, ' وبعد أخيتوفل يهوياداع بن بنايا وأبياثار . وكان رئيس جيش الملك يوآب '),
(742, '1 Chronicles', 13, 28, 1, ' وجمع داود كل رؤساء إسرائيل ، رؤساء الأسباط ورؤساء الفرق الخادمين الملك ، ورؤساء الألوف ورؤساء المئات ، ورؤساء كل الأموال والأملاك التي للملك ولبنيه ، مع الخصيان والأبطال وكل جبابرة البأس ، إلى أورشليم '),
(743, '1 Chronicles', 13, 28, 2, ' ووقف داود الملك على رجليه وقال : اسمعوني يا إخوتي وشعبي . كان في قلبي أن أبني بيت قرار لتابوت عهد الرب ولموطئ قدمي إلهنا ، وقد هيأت للبناء '),
(744, '1 Chronicles', 13, 28, 3, ' ولكن الله قال لي : لا تبني بيتا لاسمي لأنك أنت رجل حروب وقد سفكت دما '),
(745, '1 Chronicles', 13, 28, 4, ' وقد اختارني الرب إله إسرائيل من كل بيت أبي لأكون ملكا على إسرائيل إلى الأبد ، لأنه إنما اختار يهوذا رئيسا ، ومن بيت يهوذا بيت أبي ، ومن بني أبي سر بي ليملكني على كل إسرائيل '),
(746, '1 Chronicles', 13, 28, 5, ' ومن كل بني ، لأن الرب أعطاني بنين كثيرين ، إنما اختار سليمان ابني ليجلس على كرسي مملكة الرب على إسرائيل '),
(747, '1 Chronicles', 13, 28, 6, ' وقال لي : إن سليمان ابنك هو يبني بيتي ودياري ، لأني اخترته لي ابنا ، وأنا أكون له أبا '),
(748, '1 Chronicles', 13, 28, 7, ' وأثبت مملكته إلى الأبد إذا تشدد للعمل حسب وصاياي وأحكامي كهذا اليوم '),
(749, '1 Chronicles', 13, 28, 8, ' والآن في أعين كل إسرائيل محفل الرب ، وفي سماع إلهنا ، احفظوا واطلبوا جميع وصايا الرب إلهكم لكي ترثوا الأرض الجيدة وتورثوها لأولادكم بعدكم إلى الأبد '),
(750, '1 Chronicles', 13, 28, 9, ' وأنت يا سليمان ابني ، اعرف إله أبيك واعبده بقلب كامل ونفس راغبة ، لأن الرب يفحص جميع القلوب ، ويفهم كل تصورات الأفكار . فإذا طلبته يوجد منك ، وإذا تركته يرفضك إلى الأبد '),
(751, '1 Chronicles', 13, 28, 10, ' انظر الآن لأن الرب قد اختارك لتبني بيتا للمقدس ، فتشدد واعمل '),
(752, '1 Chronicles', 13, 28, 11, ' وأعطى داود سليمان ابنه مثال الرواق وبيوته وخزائنه وعلاليه ومخادعه الداخلية وبيت الغطاء '),
(753, '1 Chronicles', 13, 28, 12, ' ومثال كل ما كان عنده بالروح لديار بيت الرب ولجميع المخادع حواليه ، ولخزائن بيت الله وخزائن الأقداس '),
(754, '1 Chronicles', 13, 28, 13, ' ولفرق الكهنة واللاويين ، ولكل عمل خدمة بيت الرب ، ولكل آنية خدمة بيت الرب '),
(755, '1 Chronicles', 13, 28, 14, ' فمن الذهب بالوزن لما هو من ذهب ، لكل آنية خدمة فخدمة ، ولجميع آنية الفضة فضة بالوزن ، لكل آنية خدمة فخدمة '),
(756, '1 Chronicles', 13, 28, 15, ' وبالوزن لمنائر الذهب وسرجها من ذهب بالوزن لكل منارة فمنارة وسرجها ، ولمنائر الفضة بالوزن لكل منارة وسرجها حسب خدمة منارة فمنارة '),
(757, '1 Chronicles', 13, 28, 16, ' وذهبا بالوزن لموائد خبز الوجوه لكل مائدة فمائدة ، وفضة لموائد الفضة '),
(758, '1 Chronicles', 13, 28, 17, ' وذهبا خالصا للمناشل والمناضح والكؤوس . ولأقداح الذهب بالوزن لقدح فقدح ، ولأقداح الفضة بالوزن لقدح فقدح '),
(759, '1 Chronicles', 13, 28, 18, ' ولمذبح البخور ذهبا مصفى بالوزن ، وذهبا لمثال مركبة الكروبيم الباسطة أجنحتها المظللة تابوت عهد الرب '),
(760, '1 Chronicles', 13, 28, 19, ' قد أفهمني الرب كل ذلك بالكتابة بيده علي ، أي كل أشغال المثال '),
(761, '1 Chronicles', 13, 28, 20, ' وقال داود لسليمان ابنه : تشدد وتشجع واعمل . لا تخف ولا ترتعب ، لأن الرب الإله إلهي معك . لا يخذلك ولا يتركك حتى تكمل كل عمل خدمة بيت الرب '),
(762, '1 Chronicles', 13, 28, 21, ' وهوذا فرق الكهنة واللاويين لكل خدمة ، بيت الله . ومعك في كل عمل كل نبيه بحكمة لكل خدمة ، والرؤساء وكل الشعب تحت كل أوامرك '),
(763, '1 Chronicles', 13, 29, 1, ' وقال داود الملك لكل المجمع : إن سليمان ابني الذي وحده اختاره الله ، إنما هو صغير وغض ، والعمل عظيم لأن الهيكل ليس لإنسان بل للرب الإله '),
(764, '1 Chronicles', 13, 29, 2, ' وأنا بكل قوتي هيأت لبيت إلهي : الذهب لما هو من ذهب ، والفضة لما هو من فضة ، والنحاس لما هو من نحاس ، والحديد لما هو من حديد ، والخشب لما هو من خشب ، وحجارة الجزع ، وحجارة للترصيع ، وحجارة كحلاء ورقماء ، وكل حجارة كريمة ، وحجارة الرخام بكثرة '),
(765, '1 Chronicles', 13, 29, 3, ' وأيضا لأني قد سررت ببيت إلهي ، لي خاصة من ذهب وفضة قد دفعتها لبيت إلهي فوق جميع ما هيأته لبيت القدس '),
(766, '1 Chronicles', 13, 29, 4, ' ثلاثة آلاف وزنة ذهب من ذهب أوفير ، وسبعة آلاف وزنة فضة مصفاة ، لأجل تغشية حيطان البيوت '),
(767, '1 Chronicles', 13, 29, 5, ' الذهب للذهب ، والفضة للفضة ولكل عمل بيد أرباب الصنائع . فمن ينتدب اليوم لملء يده للرب '),
(768, '1 Chronicles', 13, 29, 6, ' فانتدب رؤساء الآباء ، ورؤساء أسباط إسرائيل ، ورؤساء الألوف والمئات ، ورؤساء أشغال الملك '),
(769, '1 Chronicles', 13, 29, 7, ' وأعطوا لخدمة بيت الله خمسة آلاف وزنة وعشرة آلاف درهم من الذهب ، وعشرة آلاف وزنة من الفضة ، وثمانية عشر ألف وزنة من النحاس ، ومئة ألف وزنة من الحديد '),
(770, '1 Chronicles', 13, 29, 8, ' ومن وجد عنده حجارة أعطاها لخزينة بيت الرب عن يد يحيئيل الجرشوني '),
(771, '1 Chronicles', 13, 29, 9, ' وفرح الشعب بانتدابهم ، لأنهم بقلب كامل انتدبوا للرب . وداود الملك أيضا فرح فرحا عظيما '),
(772, '1 Chronicles', 13, 29, 10, ' وبارك داود الرب أمام كل الجماعة ، وقال داود : مبارك أنت أيها الرب إله إسرائيل أبينا من الأزل وإلى الأبد '),
(773, '1 Chronicles', 13, 29, 11, ' لك يارب العظمة والجبروت والجلال والبهاء والمجد ، لأن لك كل ما في السماء والأرض . لك يارب الملك ، وقد ارتفعت رأسا على الجميع '),
(774, '1 Chronicles', 13, 29, 12, ' والغنى والكرامة من لدنك ، وأنت تتسلط على الجميع ، وبيدك القوة والجبروت ، وبيدك تعظيم وتشديد الجميع '),
(775, '1 Chronicles', 13, 29, 13, ' والآن ، يا إلهنا نحمدك ونسبح اسمك الجليل '),
(776, '1 Chronicles', 13, 29, 14, ' ولكن من أنا ، ومن هو شعبي حتى نستطيع أن ننتدب هكذا ؟ لأن منك الجميع ومن يدك أعطيناك '),
(777, '1 Chronicles', 13, 29, 15, ' لأننا نحن غرباء أمامك ، ونزلاء مثل كل آبائنا . أيامنا كالظل على الأرض وليس رجاء '),
(778, '1 Chronicles', 13, 29, 16, ' أيها الرب إلهنا ، كل هذه الثروة التي هيأناها لنبني لك بيتا لاسم قدسك ، إنما هي من يدك ، ولك الكل '),
(779, '1 Chronicles', 13, 29, 17, ' وقد علمت يا إلهي أنك أنت تمتحن القلوب وتسر بالاستقامة . أنا باستقامة قلبي انتدبت بكل هذه ، والآن شعبك الموجود هنا رأيته بفرح ينتدب لك '),
(780, '1 Chronicles', 13, 29, 18, ' يارب إله إبراهيم وإسحاق وإسرائيل آبائنا ، احفظ هذه إلى الأبد في تصور أفكار قلوب شعبك ، وأعد قلوبهم نحوك '),
(781, '1 Chronicles', 13, 29, 19, ' وأما سليمان ابني فأعطه قلبا كاملا ليحفظ وصاياك ، شهاداتك وفرائضك ، وليعمل الجميع ، وليبني الهيكل الذي هيأت له '),
(782, '1 Chronicles', 13, 29, 20, ' ثم قال داود لكل الجماعة : باركوا الرب إلهكم فبارك كل الجماعة الرب إله آبائهم ، وخروا وسجدوا للرب وللملك '),
(783, '1 Chronicles', 13, 15, 26, ' ولما أعان الله اللاويين حاملي تابوت عهد الرب ، ذبحوا سبعة عجول وسبعة كباش '),
(784, '1 Chronicles', 13, 15, 27, ' وكان داود لابسا جبة من كتان ، وجميع اللاويين حاملين التابوت ، والمغنون وكننيا رئيس الحمل مع المغنين . وكان على داود أفود من كتان '),
(785, '1 Chronicles', 13, 15, 28, ' فكان جميع إسرائيل يصعدون تابوت عهد الرب بهتاف ، وبصوت الأصوار والأبواق والصنوج ، يصوتون بالرباب والعيدان '),
(786, '1 Chronicles', 13, 15, 29, ' ولما دخل تابوت عهد الرب مدينة داود ، أشرفت ميكال بنت شاول من الكوة فرأت الملك داود يرقص ويلعب ، فاحتقرته في قلبها '),
(787, '1 Chronicles', 13, 16, 1, ' وأدخلوا تابوت الله وأثبتوه في وسط الخيمة التي نصبها له داود ، وقربوا محرقات وذبائح سلامة أمام الله '),
(788, '1 Chronicles', 13, 16, 2, ' ولما انتهى داود من إصعاد المحرقات وذبائح السلامة بارك الشعب باسم الرب '),
(789, '1 Chronicles', 13, 16, 3, ' وقسم على كل آل إسرائيل من الرجال والنساء ، على كل إنسان ، رغيف خبز وكأس خمر وقرص زبيب '),
(790, '1 Chronicles', 13, 16, 4, ' وجعل أمام تابوت الرب من اللاويين خداما ، ولأجل التذكير والشكر وتسبيح الرب إله إسرائيل '),
(791, '1 Chronicles', 13, 16, 5, ' آساف الرأس ، وزكريا ثانيه ، ويعيئيل وشميراموث ويحيئيل ومتثيا وأليآب وبنايا وعوبيد أدوم ويعيئيل بآلات رباب وعيدان . وكان آساف يصوت بالصنوج '),
(792, '1 Chronicles', 13, 16, 6, ' وبنايا ويحزيئيل الكاهنان بالأبواق دائما أمام تابوت عهد الله '),
(793, '1 Chronicles', 13, 16, 7, ' حينئذ في ذلك اليوم أولا جعل داود يحمد الرب بيد آساف وإخوته '),
(794, '1 Chronicles', 13, 16, 8, ' احمدوا الرب . ادعوا باسمه . أخبروا في الشعوب بأعماله '),
(795, '1 Chronicles', 13, 16, 9, ' غنوا له . ترنموا له . تحادثوا بكل عجائبه '),
(796, '1 Chronicles', 13, 16, 10, ' افتخروا باسم قدسه . تفرح قلوب الذين يلتمسون الرب '),
(797, '1 Chronicles', 13, 16, 11, ' اطلبوا الرب وعزه . التمسوا وجهه دائما '),
(798, '1 Chronicles', 13, 16, 12, ' اذكروا عجائبه التي صنع . آياته وأحكام فمه '),
(799, '1 Chronicles', 13, 16, 13, ' يا ذرية إسرائيل عبده ، وبني يعقوب مختاريه '),
(800, '1 Chronicles', 13, 16, 14, ' هو الرب إلهنا . في كل الأرض أحكامه '),
(801, '1 Chronicles', 13, 16, 15, ' اذكروا إلى الأبد عهده ، الكلمة التي أوصى بها إلى ألف جيل '),
(802, '1 Chronicles', 13, 16, 16, ' الذي قطعه مع إبراهيم . وقسمه لإسحاق '),
(803, '1 Chronicles', 13, 16, 17, ' وقد أقامه ليعقوب فريضة ، ولإسرائيل عهدا أبديا '),
(804, '1 Chronicles', 13, 16, 18, ' قائلا : لك أعطي أرض كنعان حبل ميراثكم '),
(805, '1 Chronicles', 13, 16, 19, ' حين كنتم عددا قليلا ، قليلين جدا وغرباء فيها '),
(806, '1 Chronicles', 13, 16, 20, ' وذهبوا من أمة إلى أمة ومن مملكة إلى شعب آخر '),
(807, '1 Chronicles', 13, 16, 21, ' لم يدع أحدا يظلمهم بل وبخ من أجلهم ملوكا '),
(808, '1 Chronicles', 13, 16, 22, ' لا تمسوا مسحائي ولا تؤذوا أنبيائي '),
(809, '1 Chronicles', 13, 16, 23, ' غنوا للرب يا كل الأرض . بشروا من يوم إلى يوم بخلاصه '),
(810, '1 Chronicles', 13, 16, 24, ' حدثوا في الأمم بمجده وفي كل الشعوب بعجائبه '),
(811, '1 Chronicles', 13, 16, 25, ' لأن الرب عظيم ومفتخر جدا . وهو مرهوب فوق جميع الآلهة '),
(812, '1 Chronicles', 13, 16, 26, ' لأن كل آلهة الأمم أصنام ، وأما الرب فقد صنع السماوات '),
(813, '1 Chronicles', 13, 16, 27, ' الجلال والبهاء أمامه . العزة والبهجة في مكانه '),
(814, '1 Chronicles', 13, 16, 28, ' هبوا الرب يا عشائر الشعوب ، هبوا الرب مجدا وعزة '),
(815, '1 Chronicles', 13, 16, 29, ' هبوا الرب مجد اسمه . احملوا هدايا وتعالوا إلى أمامه . اسجدوا للرب في زينة مقدسة '),
(816, '1 Chronicles', 13, 16, 30, ' ارتعدوا أمامه يا جميع الأرض . تثبتت المسكونة أيضا ، لا تتزعزع '),
(817, '1 Chronicles', 13, 16, 31, ' لتفرح السماوات وتبتهج الأرض ويقولوا في الأمم : الرب قد ملك '),
(818, '1 Chronicles', 13, 16, 32, ' ليعج البحر وملؤه ، ولتبتهج البرية وكل ما فيها '),
(819, '1 Chronicles', 13, 16, 33, ' حينئذ تترنم أشجار الوعر أمام الرب لأنه جاء ليدين الأرض '),
(820, '1 Chronicles', 13, 16, 34, ' احمدوا الرب لأنه صالح ، لأن إلى الأبد رحمته '),
(821, '1 Chronicles', 13, 16, 35, ' وقولوا : خلصنا يا إله خلاصنا ، واجمعنا وأنقذنا من الأمم لنحمد اسم قدسك ، ونتفاخر بتسبيحتك '),
(822, '1 Chronicles', 13, 16, 36, ' مبارك الرب إله إسرائيل من الأزل وإلى الأبد . فقال كل الشعب : آمين ، وسبحوا الرب '),
(823, '1 Chronicles', 13, 16, 37, ' وترك هناك أمام تابوت عهد الرب آساف وإخوته ، ليخدموا أمام التابوت دائما خدمة كل يوم بيومها '),
(824, '1 Chronicles', 13, 16, 38, ' وعوبيد أدوم وإخوتهم ثمانية وستين ، وعوبيد أدوم بن يديثون وحوسة بوابين '),
(825, '1 Chronicles', 13, 16, 39, ' وصادوق الكاهن وإخوته الكهنة أمام مسكن الرب في المرتفعة التي في جبعون '),
(826, '1 Chronicles', 13, 16, 40, ' ليصعدوا محرقات للرب على مذبح المحرقة دائما صباحا ومساء ، وحسب كل ما هو مكتوب في شريعة الرب التي أمر بها إسرائيل '),
(827, '1 Chronicles', 13, 16, 41, ' ومعهم هيمان ويدوثون وباقي المنتخبين الذين ذكرت أسماؤهم ليحمدوا الرب ، لأن إلى الأبد رحمته '),
(828, '1 Chronicles', 13, 16, 42, ' ومعهم هيمان ويدوثون بأبواق وصنوج للمصوتين ، وآلات غناء لله ، وبنو يدوثون بوابون '),
(829, '1 Chronicles', 13, 16, 43, ' ثم انطلق كل الشعب كل واحد إلى بيته ، ورجع داود ليبارك بيته '),
(830, '1 Chronicles', 13, 17, 1, ' وكان لما سكن داود في بيته ، قال داود لناثان النبي : هأنذا ساكن في بيت من أرز ، وتابوت عهد الرب تحت شقق '),
(831, '1 Chronicles', 13, 17, 2, ' فقال ناثان لداود : افعل كل ما في قلبك لأن الله معك '),
(832, '1 Chronicles', 13, 17, 3, ' وفي تلك الليلة كان كلام الله إلى ناثان قائلا '),
(833, '1 Chronicles', 13, 17, 4, ' اذهب وقل لداود عبدي : هكذا قال الرب : أنت لا تبني لي بيتا للسكنى '),
(834, '1 Chronicles', 13, 17, 5, ' لأني لم أسكن في بيت منذ يوم أصعدت إسرائيل إلى هذا اليوم ، بل سرت من خيمة إلى خيمة ، ومن مسكن إلى مسكن '),
(835, '1 Chronicles', 13, 17, 6, ' في كل ما سرت مع جميع إسرائيل ، هل تكلمت بكلمة مع أحد قضاة إسرائيل الذين أمرتهم أن يرعوا شعبي إسرائيل قائلا : لماذا لم تبنوا لي بيتا من أرز '),
(836, '1 Chronicles', 13, 17, 7, ' والآن فهكذا تقول لعبدي داود : هكذا قال رب الجنود : أنا أخذتك من المربض ، من وراء الغنم لتكون رئيسا على شعبي إسرائيل '),
(837, '1 Chronicles', 13, 17, 8, ' وكنت معك حيثما توجهت ، وقرضت جميع أعدائك من أمامك ، وعملت لك اسما كاسم العظماء الذين في الأرض '),
(838, '1 Chronicles', 13, 17, 9, ' وعينت مكانا لشعبي إسرائيل وغرسته فسكن في مكانه ، ولا يضطرب بعد ، ولا يعود بنو الإثم يبلونه كما في الأول '),
(839, '1 Chronicles', 13, 17, 10, ' ومنذ الأيام التي فيها أقمت قضاة على شعبي إسرائيل . وأذللت جميع أعدائك . وأخبرك أن الرب يبني لك بيتا '),
(840, '1 Chronicles', 13, 17, 11, ' ويكون متى كملت أيامك لتذهب مع آبائك ، أني أقيم بعدك نسلك الذي يكون من بنيك وأثبت مملكته '),
(841, '1 Chronicles', 13, 17, 12, ' هو يبني لي بيتا وأنا أثبت كرسيه إلى الأبد '),
(842, '1 Chronicles', 13, 17, 13, ' أنا أكون له أبا وهو يكون لي ابنا ، ولا أنزع رحمتي عنه كما نزعتها عن الذي كان قبلك '),
(843, '1 Chronicles', 13, 17, 14, ' وأقيمه في بيتي وملكوتي إلى الأبد ، ويكون كرسيه ثابتا إلى الأبد '),
(844, '1 Chronicles', 13, 17, 15, ' فحسب جميع هذا الكلام وحسب كل هذه الرؤيا كذلك كلم ناثان داود '),
(845, '1 Chronicles', 13, 17, 16, ' فدخل الملك داود وجلس أمام الرب وقال : من أنا أيها الرب الإله ، وماذا بيتي حتى أوصلتني إلى هنا '),
(846, '1 Chronicles', 13, 17, 17, ' وقل هذا في عينيك يا الله ، فتكلمت عن بيت عبدك إلى زمان طويل ، ونظرت إلي من العلاء كعادة الإنسان أيها الرب الإله '),
(847, '1 Chronicles', 13, 17, 18, ' فماذا يزيد داود بعد لك لأجل إكرام عبدك وأنت قد عرفت عبدك '),
(848, '1 Chronicles', 13, 17, 19, ' يارب ، من أجل عبدك وحسب قلبك قد فعلت كل هذه العظائم ، لتظهر جميع العظائم '),
(849, '1 Chronicles', 13, 17, 20, ' يارب ، ليس مثلك ولا إله غيرك حسب كل ما سمعناه بآذاننا '),
(850, '1 Chronicles', 13, 17, 21, ' وأية أمة على الأرض مثل شعبك إسرائيل الذي سار الله ليفتديه لنفسه شعبا ، لتجعل لك اسم عظائم ومخاوف بطردك أمما من أمام شعبك الذي افتديته من مصر '),
(851, '1 Chronicles', 13, 17, 22, ' وقد جعلت شعبك إسرائيل لنفسك شعبا إلى الأبد ، وأنت أيها الرب صرت لهم إلها '),
(852, '1 Chronicles', 13, 17, 23, ' والآن أيها الرب ، ليثبت إلى الأبد الكلام الذي تكلمت به عن عبدك وعن بيته وافعل كما نطقت '),
(853, '1 Chronicles', 13, 17, 24, ' وليثبت ويتعظم اسمك إلى الأبد ، فيقال : رب الجنود إله إسرائيل . هو الله لإسرائيل وليثبت بيت داود عبدك أمامك '),
(854, '1 Chronicles', 13, 17, 25, ' لأنك يا إلهي قد أعلنت لعبدك أنك تبني له بيتا ، لذلك وجد عبدك أن يصلي أمامك '),
(855, '1 Chronicles', 13, 17, 26, ' والآن أيها الرب ، أنت هو الله ، وقد وعدت عبدك بهذا الخير '),
(856, '1 Chronicles', 13, 17, 27, ' والآن قد ارتضيت بأن تبارك بيت عبدك ليكون إلى الأبد أمامك ، لأنك أنت يارب قد باركت وهو مبارك إلى الأبد '),
(857, '1 Chronicles', 13, 18, 1, ' وبعد ذلك ضرب داود الفلسطينيين وذللهم ، وأخذ جت وقراها من يد الفلسطينيين '),
(858, '1 Chronicles', 13, 24, 21, ' وأما رحبيا ، فمن بني رحبيا : الرأس يشيا '),
(859, '1 Chronicles', 13, 24, 22, ' ومن اليصهاريين : شلوموث ، ومن بني شلوموث : يحث '),
(860, '1 Chronicles', 13, 24, 23, ' ومن بني حبرون : يريا ، وأمريا الثاني ، ويحزيئيل الثالث ، ويقمعام الرابع '),
(861, '1 Chronicles', 13, 24, 24, ' من بني عزيئيل : ميخا . من بني ميخا : شامور '),
(862, '1 Chronicles', 13, 24, 25, ' أخو ميخا : يشيا . ومن بني يشيا : زكريا '),
(863, '1 Chronicles', 13, 24, 26, ' ابنا مراري : محلي وموشي . ابن يعزيا : بنو '),
(864, '1 Chronicles', 13, 24, 27, ' من بني مراري ليعزيا : بنو وشوهم وزكور وعبري '),
(865, '1 Chronicles', 13, 24, 28, ' من محلي : ألعازار ولم يكن له بنون '),
(866, '1 Chronicles', 13, 24, 29, ' وأما قيس ، فابن قيس يرحمئيل '),
(867, '1 Chronicles', 13, 24, 30, ' وبنو موشي : محلي وعادر ويريموث . هؤلاء بنو اللاويين حسب بيوت آبائهم '),
(868, '1 Chronicles', 13, 24, 31, ' وألقوا هم أيضا قرعا مقابل إخوتهم بني هارون أمام داود الملك وصادوق وأخيمالك ورؤوس آباء الكهنة واللاويين . الآباء الرؤوس كما إخوتهم الأصاغر '),
(869, '1 Chronicles', 13, 25, 1, ' وأفرز داود ورؤساء الجيش للخدمة بني آساف وهيمان ويدوثون المتنبئين بالعيدان والرباب والصنوج . وكان عددهم من رجال العمل حسب خدمتهم '),
(870, '1 Chronicles', 13, 25, 2, ' من بني آساف : زكور ويوسف ونثنيا وأشرئيلة . بنو آساف تحت يد آساف المتنبئ بين يدي الملك '),
(871, '1 Chronicles', 13, 25, 3, ' من يدوثون ، بنو يدوثون : جدليا وصري ويشعيا وحشبيا ومتثيا ، ستة . تحت يد أبيهم يدوثون المتنبئ بالعود لأجل الحمد والتسبيح للرب '),
(872, '1 Chronicles', 13, 25, 4, ' من هيمان : بقيا ومتنيا وعزيئيل وشبوئيل ويريموث وحننيا وحناني وإيليآثة وجدلتي وروممتي عزر ويشبقاشة وملوثي وهوثير ومحزيوث '),
(873, '1 Chronicles', 13, 25, 5, ' جميع هؤلاء بنو هيمان رائي الملك بكلام الله لرفع القرن . ورزق الرب هيمان أربعة عشر ابنا وثلاث بنات '),
(874, '1 Chronicles', 13, 25, 6, ' كل هؤلاء تحت يد أبيهم لأجل غناء بيت الرب بالصنوج والرباب والعيدان لخدمة بيت الله ، تحت يد الملك وآساف ويدوثون وهيمان '),
(875, '1 Chronicles', 13, 25, 7, ' وكان عددهم مع إخوتهم المتعلمين الغناء للرب ، كل الخبيرين مئتين وثمانية وثمانين '),
(876, '1 Chronicles', 13, 25, 8, ' وألقوا قرع الحراسة الصغير كما الكبير ، المعلم مع التلميذ '),
(877, '1 Chronicles', 13, 25, 9, ' فخرجت القرعة الأولى التي هي لآساف ليوسف . الثانية لجدليا ، هو وإخوته وبنوه اثنا عشر '),
(878, '1 Chronicles', 13, 25, 10, ' الثالثة لزكور ، بنوه وإخوته اثنا عشر '),
(879, '1 Chronicles', 13, 25, 11, ' الرابعة ليصري ، بنوه وإخوته اثنا عشر '),
(880, '1 Chronicles', 13, 25, 12, ' الخامسة لنثنيا ، بنوه وإخوته اثنا عشر '),
(881, '1 Chronicles', 13, 25, 13, ' السادسة لبقيا ، بنوه وإخوته اثنا عشر '),
(882, '1 Chronicles', 13, 25, 14, ' السابعة ليشرئيلة ، بنوه وإخوته اثنا عشر '),
(883, '1 Chronicles', 13, 25, 15, ' الثامنة ليشعيا ، بنوه وإخوته اثنا عشر '),
(884, '1 Chronicles', 13, 25, 16, ' التاسعة لمتنيا ، بنوه وإخوته اثنا عشر '),
(885, '1 Chronicles', 13, 25, 17, ' العاشرة لشمعي ، بنوه وإخوته اثنا عشر '),
(886, '1 Chronicles', 13, 25, 18, ' الحادية عشرة لعزرئيل ، بنوه وإخوته اثنا عشر '),
(887, '1 Chronicles', 13, 25, 19, ' والثانية عشرة لحشبيا ، بنوه وإخوته اثنا عشر '),
(888, '1 Chronicles', 13, 25, 20, ' الثالثة عشرة لشوبائيل ، بنوه وإخوته اثنا عشر '),
(889, '1 Chronicles', 13, 25, 21, ' الرابعة عشرة لمتثيا ، بنوه وإخوته اثنا عشر '),
(890, '1 Chronicles', 13, 25, 22, ' الخامسة عشرة ليريموث ، بنوه وإخوته اثنا عشر '),
(891, '1 Chronicles', 13, 25, 23, ' السادسة عشرة لحننيا ، بنوه وإخوته اثنا عشر '),
(892, '1 Chronicles', 13, 25, 24, ' السابعة عشرة ليشبقاشة ، بنوه وإخوته اثنا عشر '),
(893, '1 Chronicles', 13, 25, 25, ' الثامنة عشرة لحناني ، بنوه وإخوته اثنا عشر '),
(894, '1 Chronicles', 13, 25, 26, ' التاسعة عشرة لملوثي ، بنوه وإخوته اثنا عشر '),
(895, '1 Chronicles', 13, 25, 27, ' العشرون لإيليآثة ، بنوه وإخوته اثنا عشر '),
(896, '1 Chronicles', 13, 25, 28, ' الحادية والعشرون لهوثير ، بنوه وإخوته اثنا عشر '),
(897, '1 Chronicles', 13, 25, 29, ' الثانية والعشرون لجدلتي ، بنوه وإخوته اثنا عشر '),
(898, '1 Chronicles', 13, 25, 30, ' الثالثة والعشرون لمحزيوث ، بنوه وإخوته اثنا عشر '),
(899, '1 Chronicles', 13, 25, 31, ' الرابعة والعشرون لروممتي عزر ، بنوه وإخوته اثنا عشر '),
(900, '1 Chronicles', 13, 26, 1, ' وأما أقسام البوابين فمن القورحيين : مشلميا بن قوري من بني آساف '),
(901, '1 Chronicles', 13, 26, 2, ' وكان لمشلميا بنون : زكريا البكر ، ويديعئيل الثاني ، وزبديا الثالث ، ويثنئيل الرابع '),
(902, '1 Chronicles', 13, 26, 3, ' وعيلام الخامس ، ويهوحانان السادس ، وأليهو عيناي السابع '),
(903, '1 Chronicles', 13, 26, 4, ' وكان لعوبيد أدوم بنون : شمعيا البكر ، ويهوزاباد الثاني ، ويوآخ الثالث ، وساكار الرابع ، ونثنئيل الخامس '),
(904, '1 Chronicles', 13, 26, 5, ' وعميئيل السادس ، ويساكر السابع ، وفعلتاي الثامن . لأن الله باركه '),
(905, '1 Chronicles', 13, 26, 6, ' ولشمعيا ابنه ولد بنون تسلطوا في بيت آبائهم لأنهم جبابرة بأس '),
(906, '1 Chronicles', 13, 26, 7, ' بنو شمعيا : عثني ورفائيل وعوبيد وألزاباد ، إخوته أصحاب بأس : أليهو وسمكيا '),
(907, '1 Chronicles', 13, 26, 8, ' كل هؤلاء من بني عوبيد أدوم هم وبنوهم وإخوتهم أصحاب بأس بقوة في الخدمة ، اثنان وستون لعوبيد أدوم '),
(908, '1 Chronicles', 13, 26, 9, ' وكان لمشلميا بنون وإخوة أصحاب بأس ثمانية عشر '),
(909, '1 Chronicles', 13, 26, 10, ' وكان لحوسة من بني مراري بنون : شمري الرأس ، مع أنه لم يكن بكرا جعله أبوه رأسا '),
(910, '1 Chronicles', 13, 26, 11, ' حلقيا الثاني ، وطبليا الثالث ، وزكريا الرابع . كل بني حوسة وإخوته ثلاثة عشر '),
(911, '1 Chronicles', 13, 26, 12, ' لفرق البوابين هؤلاء حسب رؤوس الجبابرة حراسة كما لإخوتهم للخدمة في بيت الرب '),
(912, '1 Chronicles', 13, 26, 13, ' وألقوا قرعا الصغير كالكبير حسب بيوت آبائهم لكل باب '),
(913, '1 Chronicles', 13, 26, 14, ' فأصابت القرعة من جهة الشرق شلميا . ولزكريا ابنه المشير بفطنة ألقوا قرعا ، فخرجت القرعة له إلى الشمال '),
(914, '1 Chronicles', 13, 26, 15, ' لعوبيد أدوم إلى الجنوب ولبنيه المخازن '),
(915, '1 Chronicles', 13, 26, 16, ' لشفيم وحوسة إلى الغرب مع باب شلكة في مصعد الدرج محرس مقابل محرس '),
(916, '1 Chronicles', 13, 26, 17, ' من جهة الشرق كان اللاويون ستة . من جهة الشمال أربعة لليوم . من جهة الجنوب أربعة لليوم . ومن جهة المخازن اثنين اثنين '),
(917, '1 Chronicles', 13, 26, 18, ' من جهة الرواق إلى الغرب أربعة في المصعد واثنين في الرواق '),
(918, '1 Chronicles', 13, 26, 19, ' هذه أقسام البوابين من بني القورحيين ومن بني مراري '),
(919, '1 Chronicles', 13, 26, 20, ' وأما اللاويون فأخيا على خزائن بيت الله وعلى خزائن الأقداس '),
(920, '1 Chronicles', 13, 26, 21, ' وأما بنو لعدان ، فبنو لعدان الجرشوني رؤوس بيت الآباء للعدان ، الجرشوني يحيئيلي '),
(921, '1 Chronicles', 13, 26, 22, ' بنو يحيئيلي : زيثام ويوئيل أخوه على خزائن بيت الرب '),
(922, '1 Chronicles', 13, 26, 23, ' من العمراميين واليصهاريين والحبرونيين والعزيئيليين '),
(923, '1 Chronicles', 13, 26, 24, ' كان شبوئيل بن جرشوم بن موسى وكان رئيسا على الخزائن '),
(924, '1 Chronicles', 13, 26, 25, ' وإخوته من أليعزر : رحبيا ابنه ، ويشعيا ابنه ، ويورام ابنه ، وزكري ابنه ، وشلوميث ابنه '),
(925, '1 Chronicles', 13, 26, 26, ' شلوميث هذا وإخوته كانوا على جميع خزائن الأقداس التي قدسها داود الملك ورؤوس الآباء ورؤساء الألوف والمئات ورؤساء الجيش '),
(926, '1 Chronicles', 13, 26, 27, ' من الحروب ومن الغنائم قدسوا لتشديد بيت الرب '),
(927, '1 Chronicles', 13, 26, 28, ' وكل ما قدسه صموئيل الرائي وشاول بن قيس وأبنير بن نير ويوآب ابن صروية ، كل مقدس كان تحت يد شلوميث وإخوته '),
(928, '1 Chronicles', 13, 26, 29, ' ومن اليصهاريين : كننيا وبنوه للعمل الخارجي على إسرائيل عرفاء وقضاة '),
(929, '1 Chronicles', 13, 26, 30, ' من الحبرونيين : حشبيا وإخوته ذوو بأس ألف وسبع مئة موكلين على إسرائيل في عبر الأردن غربا في كل عمل الرب وفي خدمة الملك '),
(930, '1 Chronicles', 13, 26, 31, ' من الحبرونيين : يريا رأس الحبرونيين حسب مواليد آبائه . في السنة الرابعة لملك داود طلبوا فوجد فيهم جبابرة بأس في يعزير جلعاد '),
(931, '1 Chronicles', 13, 26, 32, ' وإخوته ذوو بأس ألفان وسبع مئة رؤوس آباء . ووكلهم داود الملك على الرأوبينيين والجاديين ونصف سبط منسى في كل أمور الله وأمور الملك '),
(932, '1 Chronicles', 13, 29, 21, ' وذبحوا للرب ذبائح وأصعدوا محرقات للرب في غد ذلك اليوم : ألف ثور وألف كبش وألف خروف مع سكائبها ، وذبائح كثيرة لكل إسرائيل '),
(933, '1 Chronicles', 13, 29, 22, ' وأكلوا وشربوا أمام الرب في ذلك اليوم بفرح عظيم . وملكوا ثانية سليمان بن داود ، ومسحوه للرب رئيسا ، وصادوق كاهنا '),
(934, '1 Chronicles', 13, 29, 23, ' وجلس سليمان على كرسي الرب ملكا مكان داود أبيه ، ونجح وأطاعه كل إسرائيل '),
(935, '1 Chronicles', 13, 29, 24, ' وجميع الرؤساء والأبطال وجميع أولاد الملك داود أيضا خضعوا لسليمان الملك '),
(936, '1 Chronicles', 13, 29, 25, ' وعظم الرب سليمان جدا في أعين جميع إسرائيل ، وجعل عليه جلالا ملكيا لم يكن على ملك قبله في إسرائيل '),
(937, '1 Chronicles', 13, 29, 26, ' وداود بن يسى ملك على كل إسرائيل '),
(938, '1 Chronicles', 13, 29, 27, ' والزمان الذي ملك فيه على إسرائيل أربعون سنة . ملك سبع سنين في حبرون ، وملك ثلاثا وثلاثين سنة في أورشليم '),
(939, '1 Chronicles', 13, 29, 28, ' ومات بشيبة صالحة وقد شبع أياما وغنى وكرامة . وملك سليمان ابنه مكانه '),
(940, '1 Chronicles', 13, 29, 29, ' وأمور داود الملك الأولى والأخيرة ، هي مكتوبة في سفر أخبار صموئيل الرائي ، وأخبار ناثان النبي ، وأخبار جاد الرائي '),
(941, '1 Chronicles', 13, 29, 30, ' مع كل ملكه وجبروته والأوقات التي عبرت عليه ، وعلى إسرائيل وعلى كل ممالك الأروض '),
(942, '1 Corinthians', 46, 1, 1, ' بولس ، المدعو رسولا ليسوع المسيح بمشيئة الله ، وسوستانيس الأخ ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(943, '1 Corinthians', 46, 1, 2, ' إلى كنيسة الله التي في كورنثوس ، المقدسين في المسيح يسوع ، المدعوين قديسين مع جميع الذين يدعون باسم ربنا يسوع المسيح في كل مكان ، لهم ولنا '),
(944, '1 Corinthians', 46, 1, 3, ' نعمة لكم وسلام من الله أبينا والرب يسوع المسيح '),
(945, '1 Corinthians', 46, 1, 4, ' أشكر إلهي في كل حين من جهتكم على نعمة الله المعطاة لكم في يسوع المسيح '),
(946, '1 Corinthians', 46, 1, 5, ' أنكم في كل شيء استغنيتم فيه في كل كلمة وكل علم '),
(947, '1 Corinthians', 46, 1, 6, ' كما ثبتت فيكم شهادة المسيح '),
(948, '1 Corinthians', 46, 1, 7, ' حتى إنكم لستم ناقصين في موهبة ما ، وأنتم متوقعون استعلان ربنا يسوع المسيح '),
(949, '1 Corinthians', 46, 1, 8, ' الذي سيثبتكم أيضا إلى النهاية بلا لوم في يوم ربنا يسوع المسيح '),
(950, '1 Corinthians', 46, 1, 9, ' أمين هو الله الذي به دعيتم إلى شركة ابنه يسوع المسيح ربنا '),
(951, '1 Corinthians', 46, 1, 10, ' ولكنني أطلب إليكم أيها الإخوة ، باسم ربنا يسوع المسيح ، أن تقولوا جميعكم قولا واحدا ، ولا يكون بينكم انشقاقات ، بل كونوا كاملين في فكر واحد ورأي واحد '),
(952, '1 Corinthians', 46, 1, 11, ' لأني أخبرت عنكم يا إخوتي من أهل خلوي أن بينكم خصومات '),
(953, '1 Corinthians', 46, 1, 12, ' فأنا أعني هذا : أن كل واحد منكم يقول : أنا لبولس ، وأنا لأبلوس ، وأنا لصفا ، وأنا للمسيح '),
(954, '1 Corinthians', 46, 1, 13, ' هل انقسم المسيح ؟ ألعل بولس صلب لأجلكم ، أم باسم بولس اعتمدتم '),
(955, '1 Corinthians', 46, 1, 14, ' أشكر الله أني لم أعمد أحدا منكم إلا كريسبس وغايس '),
(956, '1 Corinthians', 46, 1, 15, ' حتى لا يقول أحد إني عمدت باسمي '),
(957, '1 Corinthians', 46, 1, 16, ' وعمدت أيضا بيت استفانوس . عدا ذلك لست أعلم هل عمدت أحدا آخر '),
(958, '1 Corinthians', 46, 1, 17, ' لأن المسيح لم يرسلني لأعمد بل لأبشر ، لا بحكمة كلام لئلا يتعطل صليب المسيح '),
(959, '1 Corinthians', 46, 1, 18, ' فإن كلمة الصليب عند الهالكين جهالة ، وأما عندنا نحن المخلصين فهي قوة الله '),
(960, '1 Corinthians', 46, 1, 19, ' لأنه مكتوب : سأبيد حكمة الحكماء ، وأرفض فهم الفهماء '),
(961, '1 Corinthians', 46, 1, 20, ' أين الحكيم ؟ أين الكاتب ؟ أين مباحث هذا الدهر ؟ ألم يجهل الله حكمة هذا العالم '),
(962, '1 Corinthians', 46, 1, 21, ' لأنه إذ كان العالم في حكمة الله لم يعرف الله بالحكمة ، استحسن الله أن يخلص المؤمنين بجهالة الكرازة '),
(963, '1 Corinthians', 46, 1, 22, ' لأن اليهود يسألون آية ، واليونانيين يطلبون حكمة '),
(964, '1 Corinthians', 46, 1, 23, ' ولكننا نحن نكرز بالمسيح مصلوبا : لليهود عثرة ، ولليونانيين جهالة '),
(965, '1 Corinthians', 46, 1, 24, ' وأما للمدعوين : يهودا ويونانيين ، فبالمسيح قوة الله وحكمة الله '),
(966, '1 Corinthians', 46, 1, 25, ' لأن جهالة الله أحكم من الناس وضعف الله أقوى من الناس '),
(967, '1 Corinthians', 46, 1, 26, ' فانظروا دعوتكم أيها الإخوة ، أن ليس كثيرون حكماء حسب الجسد ، ليس كثيرون أقوياء ، ليس كثيرون شرفاء '),
(968, '1 Corinthians', 46, 1, 27, ' بل اختار الله جهال العالم ليخزي الحكماء . واختار الله ضعفاء العالم ليخزي الأقوياء '),
(969, '1 Corinthians', 46, 1, 28, ' واختار الله أدنياء العالم والمزدرى وغير الموجود ليبطل الموجود '),
(970, '1 Corinthians', 46, 1, 29, ' لكي لا يفتخر كل ذي جسد أمامه '),
(971, '1 Corinthians', 46, 1, 30, ' ومنه أنتم بالمسيح يسوع ، الذي صار لنا حكمة من الله وبرا وقداسة وفداء '),
(972, '1 Corinthians', 46, 1, 31, ' حتى كما هو مكتوب : من افتخر فليفتخر بالرب '),
(973, '1 Corinthians', 46, 2, 1, ' وأنا لما أتيت إليكم أيها الإخوة ، أتيت ليس بسمو الكلام أو الحكمة مناديا لكم بشهادة الله '),
(974, '1 Corinthians', 46, 2, 2, ' لأني لم أعزم أن أعرف شيئا بينكم إلا يسوع المسيح وإياه مصلوبا '),
(975, '1 Corinthians', 46, 2, 3, ' وأنا كنت عندكم في ضعف ، وخوف ، ورعدة كثيرة '),
(976, '1 Corinthians', 46, 2, 4, ' وكلامي وكرازتي لم يكونا بكلام الحكمة الإنسانية المقنع ، بل ببرهان الروح والقوة '),
(977, '1 Corinthians', 46, 2, 5, ' لكي لا يكون إيمانكم بحكمة الناس بل بقوة الله '),
(978, '1 Corinthians', 46, 2, 6, ' لكننا نتكلم بحكمة بين الكاملين ، ولكن بحكمة ليست من هذا الدهر ، ولا من عظماء هذا الدهر ، الذين يبطلون '),
(979, '1 Corinthians', 46, 2, 7, ' بل نتكلم بحكمة الله في سر : الحكمة المكتومة ، التي سبق الله فعينها قبل الدهور لمجدنا '),
(980, '1 Corinthians', 46, 2, 8, ' التي لم يعلمها أحد من عظماء هذا الدهر ، لأن لو عرفوا لما صلبوا رب المجد '),
(981, '1 Corinthians', 46, 2, 9, ' بل كما هو مكتوب : ما لم تر عين ، ولم تسمع أذن ، ولم يخطر على بال إنسان : ما أعده الله للذين يحبونه '),
(982, '1 Corinthians', 46, 2, 10, ' فأعلنه الله لنا نحن بروحه . لأن الروح يفحص كل شيء حتى أعماق الله '),
(983, '1 Corinthians', 46, 2, 11, ' لأن من من الناس يعرف أمور الإنسان إلا روح الإنسان الذي فيه ؟ هكذا أيضا أمور الله لا يعرفها أحد إلا روح الله '),
(984, '1 Corinthians', 46, 2, 12, ' ونحن لم نأخذ روح العالم ، بل الروح الذي من الله ، لنعرف الأشياء الموهوبة لنا من الله '),
(985, '1 Corinthians', 46, 2, 13, ' التي نتكلم بها أيضا ، لا بأقوال تعلمها حكمة إنسانية ، بل بما يعلمه الروح القدس ، قارنين الروحيات بالروحيات '),
(986, '1 Corinthians', 46, 2, 14, ' ولكن الإنسان الطبيعي لا يقبل ما لروح الله لأنه عنده جهالة ، ولا يقدر أن يعرفه لأنه إنما يحكم فيه روحيا '),
(987, '1 Corinthians', 46, 2, 15, ' وأما الروحي فيحكم في كل شيء ، وهو لايحكم فيه من أحد '),
(988, '1 Corinthians', 46, 2, 16, ' لأنه من عرف فكر الرب فيعلمه ؟ وأما نحن فلنا فكر المسيح '),
(989, '1 Corinthians', 46, 3, 1, ' وأنا أيها الإخوة لم أستطع أن أكلمكم كروحيين ، بل كجسديين كأطفال في المسيح '),
(990, '1 Corinthians', 46, 3, 2, ' سقيتكم لبنا لا طعاما ، لأنكم لم تكونوا بعد تستطيعون ، بل الآن أيضا لا تستطيعون '),
(991, '1 Corinthians', 46, 3, 3, ' لأنكم بعد جسديون . فإنه إذ فيكم حسد وخصام وانشقاق ، ألستم جسديين وتسلكون بحسب البشر '),
(992, '1 Corinthians', 46, 3, 4, ' لأنه متى قال واحد : أنا لبولس وآخر : أنا لأبلوس أفلستم جسديين '),
(993, '1 Corinthians', 46, 3, 5, ' فمن هو بولس ؟ ومن هو أبلوس ؟ بل خادمان آمنتم بواسطتهما ، وكما أعطى الرب لكل واحد '),
(994, '1 Corinthians', 46, 3, 6, ' أنا غرست وأبلوس سقى ، لكن الله كان ينمي '),
(995, '1 Corinthians', 46, 3, 7, ' إذا ليس الغارس شيئا ولا الساقي ، بل الله الذي ينمي '),
(996, '1 Corinthians', 46, 3, 8, ' والغارس والساقي هما واحد ، ولكن كل واحد سيأخذ أجرته بحسب تعبه '),
(997, '1 Corinthians', 46, 3, 9, ' فإننا نحن عاملان مع الله ، وأنتم فلاحة الله ، بناء الله '),
(998, '1 Corinthians', 46, 3, 10, ' حسب نعمة الله المعطاة لي كبناء حكيم قد وضعت أساسا ، وآخر يبني عليه . ولكن فلينظر كل واحد كيف يبني عليه '),
(999, '1 Corinthians', 46, 3, 11, ' فإنه لا يستطيع أحد أن يضع أساسا آخر غير الذي وضع ، الذي هو يسوع المسيح '),
(1000, '1 Corinthians', 46, 3, 12, ' ولكن إن كان أحد يبني على هذا الأساس : ذهبا ، فضة ، حجارة كريمة ، خشبا ، عشبا ، قشا '),
(1001, '1 Corinthians', 46, 3, 13, ' فعمل كل واحد سيصير ظاهرا لأن اليوم سيبينه . لأنه بنار يستعلن ، وستمتحن النار عمل كل واحد ما هو '),
(1002, '1 Corinthians', 46, 3, 14, ' إن بقي عمل أحد قد بناه عليه فسيأخذ أجرة '),
(1003, '1 Corinthians', 46, 3, 15, ' إن احترق عمل أحد فسيخسر ، وأما هو فسيخلص ، ولكن كما بنار '),
(1004, '1 Corinthians', 46, 3, 16, ' أما تعلمون أنكم هيكل الله ، وروح الله يسكن فيكم '),
(1005, '1 Corinthians', 46, 3, 17, ' إن كان أحد يفسد هيكل الله فسيفسده الله ، لأن هيكل الله مقدس الذي أنتم هو '),
(1006, '1 Corinthians', 46, 3, 18, ' لا يخدعن أحد نفسه . إن كان أحد يظن أنه حكيم بينكم في هذا الدهر ، فليصر جاهلا لكي يصير حكيما '),
(1007, '1 Corinthians', 46, 3, 19, ' لأن حكمة هذا العالم هي جهالة عند الله ، لأنه مكتوب : الآخذ الحكماء بمكرهم '),
(1008, '1 Corinthians', 46, 3, 20, ' وأيضا : الرب يعلم أفكار الحكماء أنها باطلة '),
(1009, '1 Corinthians', 46, 3, 21, ' إذا لا يفتخرن أحد بالناس فإن كل شيء لكم '),
(1010, '1 Corinthians', 46, 3, 22, ' أبولس ، أم أبلوس ، أم صفا ، أم العالم ، أم الحياة ، أم الموت ، أم الأشياء الحاضرة ، أم المستقبلة . كل شيء لكم '),
(1011, '1 Corinthians', 46, 3, 23, ' وأما أنتم فللمسيح ، والمسيح لله '),
(1012, '1 Corinthians', 46, 4, 1, ' هكذا فليحسبنا الإنسان كخدام المسيح ، ووكلاء سرائر الله '),
(1013, '1 Corinthians', 46, 4, 2, ' ثم يسأل في الوكلاء لكي يوجد الإنسان أمينا '),
(1014, '1 Corinthians', 46, 4, 3, ' وأما أنا فأقل شيء عندي أن يحكم في منكم ، أو من يوم بشر . بل لست أحكم في نفسي أيضا '),
(1015, '1 Corinthians', 46, 4, 4, ' فإني لست أشعر بشيء في ذاتي . لكنني لست بذلك مبررا . ولكن الذي يحكم في هو الرب '),
(1016, '1 Corinthians', 46, 4, 5, ' إذا لا تحكموا في شيء قبل الوقت ، حتى يأتي الرب الذي سينير خفايا الظلام ويظهر آراء القلوب . وحينئذ يكون المدح لكل واحد من الله '),
(1017, '1 Corinthians', 46, 4, 6, ' فهذا أيها الإخوة حولته تشبيها إلى نفسي وإلى أبلوس من أجلكم ، لكي تتعلموا فينا : أن لا تفتكروا فوق ما هو مكتوب ، كي لا ينتفخ أحد لأجل الواحد على الآخر '),
(1018, '1 Corinthians', 46, 4, 7, ' لأنه من يميزك ؟ وأي شيء لك لم تأخذه ؟ وإن كنت قد أخذت ، فلماذا تفتخر كأنك لم تأخذ '),
(1019, '1 Corinthians', 46, 4, 8, ' إنكم قد شبعتم قد استغنيتم ملكتم بدوننا وليتكم ملكتم لنملك نحن أيضا معكم '),
(1020, '1 Corinthians', 46, 4, 9, ' فإني أرى أن الله أبرزنا نحن الرسل آخرين ، كأننا محكوم علينا بالموت . لأننا صرنا منظرا للعالم ، للملائكة والناس '),
(1021, '1 Corinthians', 46, 4, 10, ' نحن جهال من أجل المسيح ، وأما أنتم فحكماء في المسيح نحن ضعفاء ، وأما أنتم فأقوياء أنتم مكرمون ، وأما نحن فبلا كرامة '),
(1022, '1 Corinthians', 46, 4, 11, ' إلى هذه الساعة نجوع ونعطش ونعرى ونلكم وليس لنا إقامة '),
(1023, '1 Corinthians', 46, 4, 12, ' ونتعب عاملين بأيدينا . نشتم فنبارك . نضطهد فنحتمل '),
(1024, '1 Corinthians', 46, 4, 13, ' يفترى علينا فنعظ . صرنا كأقذار العالم ووسخ كل شيء إلى الآن '),
(1025, '1 Corinthians', 46, 4, 14, ' ليس لكي أخجلكم أكتب بهذا ، بل كأولادي الأحباء أنذركم '),
(1026, '1 Corinthians', 46, 4, 15, ' لأنه وإن كان لكم ربوات من المرشدين في المسيح ، لكن ليس آباء كثيرون . لأني أنا ولدتكم في المسيح يسوع بالإنجيل '),
(1027, '1 Corinthians', 46, 4, 16, ' فأطلب إليكم أن تكونوا متمثلين بي '),
(1028, '1 Corinthians', 46, 4, 17, ' لذلك أرسلت إليكم تيموثاوس ، الذي هو ابني الحبيب والأمين في الرب ، الذي يذكركم بطرقي في المسيح كما أعلم في كل مكان ، في كل كنيسة '),
(1029, '1 Corinthians', 46, 4, 18, ' فانتفخ قوم كأني لست آتيا إليكم '),
(1030, '1 Corinthians', 46, 4, 19, ' ولكني سآتي إليكم سريعا إن شاء الرب ، فسأعرف ليس كلام الذين انتفخوا بل قوتهم '),
(1031, '1 Corinthians', 46, 4, 20, ' لأن ملكوت الله ليس بكلام ، بل بقوة '),
(1032, '1 Corinthians', 46, 4, 21, ' ماذا تريدون ؟ أبعصا آتي إليكم أم بالمحبة وروح الوداعة '),
(1033, '1 Corinthians', 46, 5, 1, ' يسمع مطلقا أن بينكم زنى وزنى هكذا لا يسمى بين الأمم ، حتى أن تكون للإنسان امرأة أبيه '),
(1034, '1 Corinthians', 46, 5, 2, ' أفأنتم منتفخون ، وبالحري لم تنوحوا حتى يرفع من وسطكم الذي فعل هذا الفعل '),
(1035, '1 Corinthians', 46, 5, 3, ' فإني أنا كأني غائب بالجسد ، ولكن حاضر بالروح ، قد حكمت كأني حاضر في الذي فعل هذا ، هكذا '),
(1036, '1 Corinthians', 46, 5, 4, ' باسم ربنا يسوع المسيح - إذ أنتم وروحي مجتمعون مع قوة ربنا يسوع المسيح '),
(1037, '1 Corinthians', 46, 5, 5, ' أن يسلم مثل هذا للشيطان لهلاك الجسد ، لكي تخلص الروح في يوم الرب يسوع '),
(1038, '1 Corinthians', 46, 5, 6, ' ليس افتخاركم حسنا . ألستم تعلمون أن خميرة صغيرة تخمر العجين كله '),
(1039, '1 Corinthians', 46, 5, 7, ' إذا نقوا منكم الخميرة العتيقة ، لكي تكونوا عجينا جديدا كما أنتم فطير . لأن فصحنا أيضا المسيح قد ذبح لأجلنا '),
(1040, '1 Corinthians', 46, 5, 8, ' إذا لنعيد ، ليس بخميرة عتيقة ، ولا بخميرة الشر والخبث ، بل بفطير الإخلاص والحق '),
(1041, '1 Corinthians', 46, 5, 9, ' كتبت إليكم في الرسالة أن لا تخالطوا الزناة '),
(1042, '1 Corinthians', 46, 5, 10, ' وليس مطلقا زناة هذا العالم ، أو الطماعين ، أو الخاطفين ، أو عبدة الأوثان ، وإلا فيلزمكم أن تخرجوا من العالم '),
(1043, '1 Corinthians', 46, 5, 11, ' وأما الآن فكتبت إليكم : إن كان أحد مدعو أخا زانيا أو طماعا أو عابد وثن أو شتاما أو سكيرا أو خاطفا ، أن لا تخالطوا ولا تؤاكلوا مثل هذا '),
(1044, '1 Corinthians', 46, 5, 12, ' لأنه ماذا لي أن أدين الذين من خارج ؟ ألستم أنتم تدينون الذين من داخل '),
(1045, '1 Corinthians', 46, 5, 13, ' أما الذين من خارج فالله يدينهم . فاعزلوا الخبيث من بينكم '),
(1046, '1 Corinthians', 46, 6, 1, ' أيتجاسر منكم أحد له دعوى على آخر أن يحاكم عند الظالمين ، وليس عند القديسين '),
(1047, '1 Corinthians', 46, 6, 2, ' ألستم تعلمون أن القديسين سيدينون العالم ؟ فإن كان العالم يدان بكم ، أفأنتم غير مستأهلين للمحاكم الصغرى '),
(1048, '1 Corinthians', 46, 6, 3, ' ألستم تعلمون أننا سندين ملائكة ؟ فبالأولى أمور هذه الحياة '),
(1049, '1 Corinthians', 46, 6, 4, ' فإن كان لكم محاكم في أمور هذه الحياة ، فأجلسوا المحتقرين في الكنيسة قضاة '),
(1050, '1 Corinthians', 46, 6, 5, ' لتخجيلكم أقول . أهكذا ليس بينكم حكيم ، ولا واحد يقدر أن يقضي بين إخوته '),
(1051, '1 Corinthians', 46, 6, 6, ' لكن الأخ يحاكم الأخ ، وذلك عند غير المؤمنين '),
(1052, '1 Corinthians', 46, 6, 7, ' فالآن فيكم عيب مطلقا ، لأن عندكم محاكمات بعضكم مع بعض . لماذا لا تظلمون بالحري ؟ لماذا لا تسلبون بالحري '),
(1053, '1 Corinthians', 46, 6, 8, ' لكن أنتم تظلمون وتسلبون ، وذلك للإخوة '),
(1054, '1 Corinthians', 46, 6, 9, ' أم لستم تعلمون أن الظالمين لا يرثون ملكوت الله ؟ لا تضلوا : لا زناة ولا عبدة أوثان ولا فاسقون ولا مأبونون ولا مضاجعو ذكور '),
(1055, '1 Corinthians', 46, 6, 10, ' ولا سارقون ولا طماعون ولا سكيرون ولا شتامون ولا خاطفون يرثون ملكوت الله '),
(1056, '1 Corinthians', 46, 6, 11, ' وهكذا كان أناس منكم . لكن اغتسلتم ، بل تقدستم ، بل تبررتم باسم الرب يسوع وبروح إلهنا '),
(1057, '1 Corinthians', 46, 6, 12, ' كل الأشياء تحل لي ، لكن ليس كل الأشياء توافق . كل الأشياء تحل لي ، لكن لا يتسلط علي شيء '),
(1058, '1 Corinthians', 46, 6, 13, ' الأطعمة للجوف والجوف للأطعمة ، والله سيبيد هذا وتلك . ولكن الجسد ليس للزنا بل للرب ، والرب للجسد '),
(1059, '1 Corinthians', 46, 6, 14, ' والله قد أقام الرب ، وسيقيمنا نحن أيضا بقوته '),
(1060, '1 Corinthians', 46, 6, 15, ' ألستم تعلمون أن أجسادكم هي أعضاء المسيح ؟ أفآخذ أعضاء المسيح وأجعلها أعضاء زانية ؟ حاشا '),
(1061, '1 Corinthians', 46, 6, 16, ' أم لستم تعلمون أن من التصق بزانية هو جسد واحد ؟ لأنه يقول : يكون الاثنان جسدا واحدا '),
(1062, '1 Corinthians', 46, 6, 17, ' وأما من التصق بالرب فهو روح واحد '),
(1063, '1 Corinthians', 46, 6, 18, ' اهربوا من الزنا . كل خطية يفعلها الإنسان هي خارجة عن الجسد ، لكن الذي يزني يخطئ إلى جسده '),
(1064, '1 Corinthians', 46, 6, 19, ' أم لستم تعلمون أن جسدكم هو هيكل للروح القدس الذي فيكم ، الذي لكم من الله ، وأنكم لستم لأنفسكم '),
(1065, '1 Corinthians', 46, 6, 20, ' لأنكم قد اشتريتم بثمن . فمجدوا الله في أجسادكم وفي أرواحكم التي هي لله '),
(1066, '1 Corinthians', 46, 7, 1, ' وأما من جهة الأمور التي كتبتم لي عنها : فحسن للرجل أن لا يمس امرأة '),
(1067, '1 Corinthians', 46, 7, 2, ' ولكن لسبب الزنا ، ليكن لكل واحد امرأته ، وليكن لكل واحدة رجلها '),
(1068, '1 Corinthians', 46, 7, 3, ' ليوف الرجل المرأة حقها الواجب ، وكذلك المرأة أيضا الرجل '),
(1069, '1 Corinthians', 46, 7, 4, ' ليس للمرأة تسلط على جسدها ، بل للرجل . وكذلك الرجل أيضا ليس له تسلط على جسده ، بل للمرأة '),
(1070, '1 Corinthians', 46, 7, 5, ' لا يسلب أحدكم الآخر ، إلا أن يكون على موافقة ، إلى حين ، لكي تتفرغوا للصوم والصلاة ، ثم تجتمعوا أيضا معا لكي لا يجربكم الشيطان لسبب عدم نزاهتكم '),
(1071, '1 Corinthians', 46, 7, 6, ' ولكن أقول هذا على سبيل الإذن لا على سبيل الأمر '),
(1072, '1 Corinthians', 46, 7, 7, ' لأني أريد أن يكون جميع الناس كما أنا . لكن كل واحد له موهبته الخاصة من الله . الواحد هكذا والآخر هكذا '),
(1073, '1 Corinthians', 46, 7, 8, ' ولكن أقول لغير المتزوجين وللأرامل ، إنه حسن لهم إذا لبثوا كما أنا '),
(1074, '1 Corinthians', 46, 7, 9, ' ولكن إن لم يضبطوا أنفسهم ، فليتزوجوا . لأن التزوج أصلح من التحرق '),
(1075, '1 Corinthians', 46, 7, 10, ' وأما المتزوجون ، فأوصيهم ، لا أنا بل الرب : أن لا تفارق المرأة رجلها '),
(1076, '1 Corinthians', 46, 7, 11, ' وإن فارقته ، فلتلبث غير متزوجة ، أو لتصالح رجلها . ولا يترك الرجل امرأته '),
(1077, '1 Corinthians', 46, 7, 12, ' وأما الباقون ، فأقول لهم أنا ، لا الرب : إن كان أخ له امرأة غير مؤمنة ، وهي ترتضي أن تسكن معه ، فلا يتركها '),
(1078, '1 Corinthians', 46, 7, 13, ' والمرأة التي لها رجل غير مؤمن ، وهو يرتضي أن يسكن معها ، فلا تتركه '),
(1079, '1 Corinthians', 46, 7, 14, ' لأن الرجل غير المؤمن مقدس في المرأة ، والمرأة غير المؤمنة مقدسة في الرجل . وإلا فأولادكم نجسون ، وأما الآن فهم مقدسون '),
(1080, '1 Corinthians', 46, 7, 15, ' ولكن إن فارق غير المؤمن ، فليفارق . ليس الأخ أو الأخت مستعبدا في مثل هذه الأحوال ، ولكن الله قد دعانا في السلام '),
(1081, '1 Corinthians', 46, 7, 16, ' لأنه كيف تعلمين أيتها المرأة ، هل تخلصين الرجل ؟ أو كيف تعلم أيها الرجل ، هل تخلص المرأة '),
(1082, '1 Corinthians', 46, 7, 17, ' غير أنه كما قسم الله لكل واحد ، كما دعا الرب كل واحد ، هكذا ليسلك . وهكذا أنا آمر في جميع الكنائس '),
(1083, '1 Corinthians', 46, 7, 18, ' دعي أحد وهو مختون ، فلا يصر أغلف . دعي أحد في الغرلة ، فلا يختتن '),
(1084, '1 Corinthians', 46, 7, 19, ' ليس الختان شيئا ، وليست الغرلة شيئا ، بل حفظ وصايا الله '),
(1085, '1 Corinthians', 46, 7, 20, ' الدعوة التي دعي فيها كل واحد فليلبث فيها '),
(1086, '1 Corinthians', 46, 7, 21, ' دعيت وأنت عبد فلا يهمك ، بل وإن استطعت أن تصير حرا فاستعملها بالحري '),
(1087, '1 Corinthians', 46, 7, 22, ' لأن من دعي في الرب وهو عبد ، فهو عتيق الرب . كذلك أيضا الحر المدعو هو عبد للمسيح '),
(1088, '1 Corinthians', 46, 7, 23, ' قد اشتريتم بثمن ، فلا تصيروا عبيدا للناس '),
(1089, '1 Corinthians', 46, 7, 24, ' ما دعي كل واحد فيه أيها الإخوة فليلبث في ذلك مع الله '),
(1090, '1 Corinthians', 46, 7, 25, ' وأما العذارى ، فليس عندي أمر من الرب فيهن ، ولكنني أعطي رأيا كمن رحمه الرب أن يكون أمينا '),
(1091, '1 Corinthians', 46, 7, 26, ' فأظن أن هذا حسن لسبب الضيق الحاضر ، أنه حسن للإنسان أن يكون هكذا '),
(1092, '1 Corinthians', 46, 7, 27, ' أنت مرتبط بامرأة ، فلا تطلب الانفصال . أنت منفصل عن امرأة ، فلا تطلب امرأة '),
(1093, '1 Corinthians', 46, 7, 28, ' لكنك وإن تزوجت لم تخطئ . وإن تزوجت العذراء لم تخطئ . ولكن مثل هؤلاء يكون لهم ضيق في الجسد . وأما أنا فإني أشفق عليكم '),
(1094, '1 Corinthians', 46, 7, 29, ' فأقول هذا أيها الإخوة : الوقت منذ الآن مقصر ، لكي يكون الذين لهم نساء كأن ليس لهم '),
(1095, '1 Corinthians', 46, 7, 30, ' والذين يبكون كأنهم لا يبكون ، والذين يفرحون كأنهم لا يفرحون ، والذين يشترون كأنهم لا يملكون '),
(1096, '1 Corinthians', 46, 7, 31, ' والذين يستعملون هذا العالم كأنهم لا يستعملونه . لأن هيئة هذا العالم تزول '),
(1097, '1 Corinthians', 46, 7, 32, ' فأريد أن تكونوا بلا هم . غير المتزوج يهتم في ما للرب كيف يرضي الرب '),
(1098, '1 Corinthians', 46, 7, 33, ' وأما المتزوج فيهتم في ما للعالم كيف يرضي امرأته '),
(1099, '1 Corinthians', 46, 7, 34, ' إن بين الزوجة والعذراء فرقا : غير المتزوجة تهتم في ما للرب لتكون مقدسة جسدا وروحا . وأما المتزوجة فتهتم في ما للعالم كيف ترضي رجلها '),
(1100, '1 Corinthians', 46, 7, 35, ' هذا أقوله لخيركم ، ليس لكي ألقي عليكم وهقا ، بل لأجل اللياقة والمثابرة للرب من دون ارتباك '),
(1101, '1 Corinthians', 46, 7, 36, ' ولكن إن كان أحد يظن أنه يعمل بدون لياقة نحو عذرائه إذا تجاوزت الوقت ، وهكذا لزم أن يصير ، فليفعل ما يريد . إنه لا يخطئ . فليتزوجا '),
(1102, '1 Corinthians', 46, 7, 37, ' وأما من أقام راسخا في قلبه ، وليس له اضطرار ، بل له سلطان على إرادته ، وقد عزم على هذا في قلبه أن يحفظ عذراءه ، فحسنا يفعل '),
(1103, '1 Corinthians', 46, 7, 38, ' إذا ، من زوج فحسنا يفعل ، ومن لا يزوج يفعل أحسن '),
(1104, '1 Corinthians', 46, 7, 39, ' المرأة مرتبطة بالناموس ما دام رجلها حيا . ولكن إن مات رجلها ، فهي حرة لكي تتزوج بمن تريد ، في الرب فقط '),
(1105, '1 Corinthians', 46, 7, 40, ' ولكنها أكثر غبطة إن لبثت هكذا ، بحسب رأيي . وأظن أني أنا أيضا عندي روح الله '),
(1106, '1 Corinthians', 46, 8, 1, ' وأما من جهة ما ذبح للأوثان : فنعلم أن لجميعنا علما . العلم ينفخ ، ولكن المحبة تبني '),
(1107, '1 Corinthians', 46, 8, 2, ' فإن كان أحد يظن أنه يعرف شيئا ، فإنه لم يعرف شيئا بعد كما يجب أن يعرف '),
(1108, '1 Corinthians', 46, 8, 3, ' ولكن إن كان أحد يحب الله ، فهذا معروف عنده '),
(1109, '1 Corinthians', 46, 8, 4, ' فمن جهة أكل ما ذبح للأوثان : نعلم أن ليس وثن في العالم ، وأن ليس إله آخر إلا واحدا '),
(1110, '1 Corinthians', 46, 8, 5, ' لأنه وإن وجد ما يسمى آلهة ، سواء كان في السماء أو على الأرض ، كما يوجد آلهة كثيرون وأرباب كثيرون '),
(1111, '1 Corinthians', 46, 8, 6, ' لكن لنا إله واحد : الآب الذي منه جميع الأشياء ، ونحن له . ورب واحد : يسوع المسيح ، الذي به جميع الأشياء ، ونحن به '),
(1112, '1 Corinthians', 46, 8, 7, ' ولكن ليس العلم في الجميع . بل أناس بالضمير نحو الوثن إلى الآن يأكلون كأنه مما ذبح لوثن ، فضميرهم إذ هو ضعيف يتنجس '),
(1113, '1 Corinthians', 46, 8, 8, ' ولكن الطعام لا يقدمنا إلى الله ، لأننا إن أكلنا لا نزيد وإن لم نأكل لا ننقص '),
(1114, '1 Corinthians', 46, 8, 9, ' ولكن انظروا لئلا يصير سلطانكم هذا معثرة للضعفاء '),
(1115, '1 Corinthians', 46, 8, 10, ' لأنه إن رآك أحد يا من له علم ، متكئا في هيكل وثن ، أفلا يتقوى ضميره ، إذ هو ضعيف ، حتى يأكل ما ذبح للأوثان '),
(1116, '1 Corinthians', 46, 8, 11, ' فيهلك بسبب علمك الأخ الضعيف الذي مات المسيح من أجله '),
(1117, '1 Corinthians', 46, 8, 12, ' وهكذا إذ تخطئون إلى الإخوة وتجرحون ضميرهم الضعيف ، تخطئون إلى المسيح '),
(1118, '1 Corinthians', 46, 8, 13, ' لذلك إن كان طعام يعثر أخي فلن آكل لحما إلى الأبد ، لئلا أعثر أخي '),
(1119, '1 Corinthians', 46, 9, 1, ' ألست أنا رسولا ؟ ألست أنا حرا ؟ أما رأيت يسوع المسيح ربنا ؟ ألستم أنتم عملي في الرب '),
(1120, '1 Corinthians', 46, 9, 2, ' إن كنت لست رسولا إلى آخرين ، فإنما أنا إليكم رسول لأنكم أنتم ختم رسالتي في الرب '),
(1121, '1 Corinthians', 46, 9, 3, ' هذا هو احتجاجي عند الذين يفحصونني '),
(1122, '1 Corinthians', 46, 9, 4, ' ألعلنا ليس لنا سلطان أن نأكل ونشرب '),
(1123, '1 Corinthians', 46, 9, 5, ' ألعلنا ليس لنا سلطان أن نجول بأخت زوجة كباقي الرسل وإخوة الرب وصفا '),
(1124, '1 Corinthians', 46, 9, 6, ' أم أنا وبرنابا وحدنا ليس لنا سلطان أن لا نشتغل '),
(1125, '1 Corinthians', 46, 9, 7, ' من تجند قط بنفقة نفسه ؟ ومن يغرس كرما ومن ثمره لا يأكل ؟ أو من يرعى رعية ومن لبن الرعية لا يأكل '),
(1126, '1 Corinthians', 46, 9, 8, ' ألعلي أتكلم بهذا كإنسان ؟ أم ليس الناموس أيضا يقول هذا '),
(1127, '1 Corinthians', 46, 9, 9, ' فإنه مكتوب في ناموس موسى : لا تكم ثورا دارسا . ألعل الله تهمه الثيران '),
(1128, '1 Corinthians', 46, 9, 10, ' أم يقول مطلقا من أجلنا ؟ إنه من أجلنا مكتوب . لأنه ينبغي للحراث أن يحرث على رجاء ، وللدارس على الرجاء أن يكون شريكا في رجائه '),
(1129, '1 Corinthians', 46, 9, 11, ' إن كنا نحن قد زرعنا لكم الروحيات ، أفعظيم إن حصدنا منكم الجسديات '),
(1130, '1 Corinthians', 46, 9, 12, ' إن كان آخرون شركاء في السلطان عليكم ، أفلسنا نحن بالأولى ؟ لكننا لم نستعمل هذا السلطان ، بل نتحمل كل شيء لئلا نجعل عائقا لإنجيل المسيح '),
(1131, '1 Corinthians', 46, 9, 13, ' ألستم تعلمون أن الذين يعملون في الأشياء المقدسة ، من الهيكل يأكلون ؟ الذين يلازمون المذبح يشاركون المذبح '),
(1132, '1 Corinthians', 46, 9, 14, ' هكذا أيضا أمر الرب : أن الذين ينادون بالإنجيل ، من الإنجيل يعيشون '),
(1133, '1 Corinthians', 46, 9, 15, ' أما أنا فلم أستعمل شيئا من هذا ، ولا كتبت هذا لكي يصير في هكذا . لأنه خير لي أن أموت من أن يعطل أحد فخري '),
(1134, '1 Corinthians', 46, 9, 16, ' لأنه إن كنت أبشر فليس لي فخر ، إذ الضرورة موضوعة علي ، فويل لي إن كنت لا أبشر '),
(1135, '1 Corinthians', 46, 9, 17, ' فإنه إن كنت أفعل هذا طوعا فلي أجر ، ولكن إن كان كرها فقد استؤمنت على وكالة '),
(1136, '1 Corinthians', 46, 9, 18, ' فما هو أجري ؟ إذ وأنا أبشر أجعل إنجيل المسيح بلا نفقة ، حتى لم أستعمل سلطاني في الإنجيل '),
(1137, '1 Corinthians', 46, 9, 19, ' فإني إذ كنت حرا من الجميع ، استعبدت نفسي للجميع لأربح الأكثرين '),
(1138, '1 Corinthians', 46, 9, 20, ' فصرت لليهود كيهودي لأربح اليهود . وللذين تحت الناموس كأني تحت الناموس لأربح الذين تحت الناموس '),
(1139, '1 Corinthians', 46, 9, 21, ' وللذين بلا ناموس كأني بلا ناموس - مع أني لست بلا ناموس لله ، بل تحت ناموس للمسيح - لأربح الذين بلا ناموس '),
(1140, '1 Corinthians', 46, 9, 22, ' صرت للضعفاء كضعيف لأربح الضعفاء . صرت للكل كل شيء ، لأخلص على كل حال قوما '),
(1141, '1 Corinthians', 46, 9, 23, ' وهذا أنا أفعله لأجل الإنجيل ، لأكون شريكا فيه '),
(1142, '1 Corinthians', 46, 9, 24, ' ألستم تعلمون أن الذين يركضون في الميدان جميعهم يركضون ، ولكن واحدا يأخذ الجعالة ؟ هكذا اركضوا لكي تنالوا '),
(1143, '1 Corinthians', 46, 9, 25, ' وكل من يجاهد يضبط نفسه في كل شيء . أما أولئك فلكي يأخذوا إكليلا يفنى ، وأما نحن فإكليلا لا يفنى '),
(1144, '1 Corinthians', 46, 9, 26, ' إذا ، أنا أركض هكذا كأنه ليس عن غير يقين . هكذا أضارب كأني لا أضرب الهواء '),
(1145, '1 Corinthians', 46, 9, 27, ' بل أقمع جسدي وأستعبده ، حتى بعد ما كرزت للآخرين لا أصير أنا نفسي مرفوضا '),
(1146, '1 Corinthians', 46, 10, 1, ' فإني لست أريد أيها الإخوة أن تجهلوا أن آباءنا جميعهم كانوا تحت السحابة ، وجميعهم اجتازوا في البحر '),
(1147, '1 Corinthians', 46, 10, 2, ' وجميعهم اعتمدوا لموسى في السحابة وفي البحر '),
(1148, '1 Corinthians', 46, 10, 3, ' وجميعهم أكلوا طعاما واحدا روحيا '),
(1149, '1 Corinthians', 46, 10, 4, ' وجميعهم شربوا شرابا واحدا روحيا ، لأنهم كانوا يشربون من صخرة روحية تابعتهم ، والصخرة كانت المسيح '),
(1150, '1 Corinthians', 46, 10, 5, ' لكن بأكثرهم لم يسر الله ، لأنهم طرحوا في القفر '),
(1151, '1 Corinthians', 46, 10, 6, ' وهذه الأمور حدثت مثالا لنا ، حتى لا نكون نحن مشتهين شرورا كما اشتهى أولئك '),
(1152, '1 Corinthians', 46, 10, 7, ' فلا تكونوا عبدة أوثان كما كان أناس منهم ، كما هو مكتوب : جلس الشعب للأكل والشرب ، ثم قاموا للعب '),
(1153, '1 Corinthians', 46, 10, 8, ' ولا نزن كما زنى أناس منهم ، فسقط في يوم واحد ثلاثة وعشرون ألفا '),
(1154, '1 Corinthians', 46, 10, 9, ' ولا نجرب المسيح كما جرب أيضا أناس منهم ، فأهلكتهم الحيات '),
(1155, '1 Corinthians', 46, 10, 10, ' ولا تتذمروا كما تذمر أيضا أناس منهم ، فأهلكهم المهلك '),
(1156, '1 Corinthians', 46, 10, 11, ' فهذه الأمور جميعها أصابتهم مثالا ، وكتبت لإنذارنا نحن الذين انتهت إلينا أواخر الدهور '),
(1157, '1 Corinthians', 46, 10, 12, ' إذا من يظن أنه قائم ، فلينظر أن لا يسقط '),
(1158, '1 Corinthians', 46, 10, 13, ' لم تصبكم تجربة إلا بشرية . ولكن الله أمين ، الذي لا يدعكم تجربون فوق ما تستطيعون ، بل سيجعل مع التجربة أيضا المنفذ ، لتستطيعوا أن تحتملوا '),
(1159, '1 Corinthians', 46, 10, 14, ' لذلك يا أحبائي اهربوا من عبادة الأوثان '),
(1160, '1 Corinthians', 46, 10, 15, ' أقول كما للحكماء : احكموا أنتم في ما أقول '),
(1161, '1 Corinthians', 46, 10, 16, ' كأس البركة التي نباركها ، أليست هي شركة دم المسيح ؟ الخبز الذي نكسره ، أليس هو شركة جسد المسيح '),
(1162, '1 Corinthians', 46, 10, 17, ' فإننا نحن الكثيرين خبز واحد ، جسد واحد ، لأننا جميعنا نشترك في الخبز الواحد '),
(1163, '1 Corinthians', 46, 10, 18, ' انظروا إسرائيل حسب الجسد . أليس الذين يأكلون الذبائح هم شركاء المذبح '),
(1164, '1 Corinthians', 46, 10, 19, ' فماذا أقول ؟ أإن الوثن شيء ، أو إن ما ذبح للوثن شيء '),
(1165, '1 Corinthians', 46, 10, 20, ' بل إن ما يذبحه الأمم فإنما يذبحونه للشياطين ، لا لله . فلست أريد أن تكونوا أنتم شركاء الشياطين '),
(1166, '1 Corinthians', 46, 10, 21, ' لا تقدرون أن تشربوا كأس الرب وكأس شياطين . لا تقدرون أن تشتركوا في مائدة الرب وفي مائدة شياطين '),
(1167, '1 Corinthians', 46, 10, 22, ' أم نغير الرب ؟ ألعلنا أقوى منه '),
(1168, '1 Corinthians', 46, 10, 23, ' كل الأشياء تحل لي ، لكن ليس كل الأشياء توافق . كل الأشياء تحل لي ، ولكن ليس كل الأشياء تبني '),
(1169, '1 Corinthians', 46, 10, 24, ' لا يطلب أحد ما هو لنفسه ، بل كل واحد ما هو للآخر '),
(1170, '1 Corinthians', 46, 10, 25, ' كل ما يباع في الملحمة كلوه غير فاحصين عن شيء ، من أجل الضمير '),
(1171, '1 Corinthians', 46, 10, 26, ' لأن للرب الأرض وملأها '),
(1172, '1 Corinthians', 46, 10, 27, ' وإن كان أحد من غير المؤمنين يدعوكم ، وتريدون أن تذهبوا ، فكل ما يقدم لكم كلوا منه غير فاحصين ، من أجل الضمير '),
(1173, '1 Corinthians', 46, 10, 28, ' ولكن إن قال لكم أحد : هذا مذبوح لوثن فلا تأكلوا من أجل ذاك الذي أعلمكم ، والضمير . لأن للرب الأرض وملأها '),
(1174, '1 Corinthians', 46, 10, 29, ' أقول الضمير ، ليس ضميرك أنت ، بل ضمير الآخر . لأنه لماذا يحكم في حريتي من ضمير آخر '),
(1175, '1 Corinthians', 46, 10, 30, ' فإن كنت أنا أتناول بشكر ، فلماذا يفترى علي لأجل ما أشكر عليه '),
(1176, '1 Corinthians', 46, 10, 31, ' فإذا كنتم تأكلون أو تشربون أو تفعلون شيئا ، فافعلوا كل شيء لمجد الله '),
(1177, '1 Corinthians', 46, 10, 32, ' كونوا بلا عثرة لليهود ولليونانيين ولكنيسة الله '),
(1178, '1 Corinthians', 46, 10, 33, ' كما أنا أيضا أرضي الجميع في كل شيء ، غير طالب ما يوافق نفسي ، بل الكثيرين ، لكي يخلصوا '),
(1179, '1 Corinthians', 46, 11, 1, ' كونوا متمثلين بي كما أنا أيضا بالمسيح '),
(1180, '1 Corinthians', 46, 11, 2, ' فأمدحكم أيها الإخوة على أنكم تذكرونني في كل شيء ، وتحفظون التعاليم كما سلمتها إليكم '),
(1181, '1 Corinthians', 46, 11, 3, ' ولكن أريد أن تعلموا أن رأس كل رجل هو المسيح ، وأما رأس المرأة فهو الرجل ، ورأس المسيح هو الله '),
(1182, '1 Corinthians', 46, 11, 4, ' كل رجل يصلي أو يتنبأ وله على رأسه شيء ، يشين رأسه '),
(1183, '1 Corinthians', 46, 11, 5, ' وأما كل امرأة تصلي أو تتنبأ ورأسها غير مغطى ، فتشين رأسها ، لأنها والمحلوقة شيء واحد بعينه '),
(1184, '1 Corinthians', 46, 11, 6, ' إذ المرأة ، إن كانت لا تتغطى ، فليقص شعرها . وإن كان قبيحا بالمرأة أن تقص أو تحلق ، فلتتغط '),
(1185, '1 Corinthians', 46, 11, 7, ' فإن الرجل لا ينبغي أن يغطي رأسه لكونه صورة الله ومجده . وأما المرأة فهي مجد الرجل '),
(1186, '1 Corinthians', 46, 11, 8, ' لأن الرجل ليس من المرأة ، بل المرأة من الرجل '),
(1187, '1 Corinthians', 46, 11, 9, ' ولأن الرجل لم يخلق من أجل المرأة ، بل المرأة من أجل الرجل '),
(1188, '1 Corinthians', 46, 11, 10, ' لهذا ينبغي للمرأة أن يكون لها سلطان على رأسها ، من أجل الملائكة '),
(1189, '1 Corinthians', 46, 11, 11, ' غير أن الرجل ليس من دون المرأة ، ولا المرأة من دون الرجل في الرب '),
(1190, '1 Corinthians', 46, 11, 12, ' لأنه كما أن المرأة هي من الرجل ، هكذا الرجل أيضا هو بالمرأة . ولكن جميع الأشياء هي من الله '),
(1191, '1 Corinthians', 46, 11, 13, ' احكموا في أنفسكم : هل يليق بالمرأة أن تصلي إلى الله وهي غير مغطاة '),
(1192, '1 Corinthians', 46, 11, 14, ' أم ليست الطبيعة نفسها تعلمكم أن الرجل إن كان يرخي شعره فهو عيب له '),
(1193, '1 Corinthians', 46, 11, 15, ' وأما المرأة إن كانت ترخي شعرها فهو مجد لها ، لأن الشعر قد أعطي لها عوض برقع '),
(1194, '1 Corinthians', 46, 11, 16, ' ولكن إن كان أحد يظهر أنه يحب الخصام ، فليس لنا نحن عادة مثل هذه ، ولا لكنائس الله '),
(1195, '1 Corinthians', 46, 11, 17, ' ولكنني إذ أوصي بهذا ، لست أمدح كونكم تجتمعون ليس للأفضل ، بل للأردإ '),
(1196, '1 Corinthians', 46, 11, 18, ' لأني أولا حين تجتمعون في الكنيسة ، أسمع أن بينكم انشقاقات ، وأصدق بعض التصديق '),
(1197, '1 Corinthians', 46, 11, 19, ' لأنه لا بد أن يكون بينكم بدع أيضا ، ليكون المزكون ظاهرين بينكم '),
(1198, '1 Corinthians', 46, 11, 20, ' فحين تجتمعون معا ليس هو لأكل عشاء الرب '),
(1199, '1 Corinthians', 46, 11, 21, ' لأن كل واحد يسبق فيأخذ عشاء نفسه في الأكل ، فالواحد يجوع والآخر يسكر '),
(1200, '1 Corinthians', 46, 11, 22, ' أفليس لكم بيوت لتأكلوا فيها وتشربوا ؟ أم تستهينون بكنيسة الله وتخجلون الذين ليس لهم ؟ ماذا أقول لكم ؟ أأمدحكم على هذا ؟ لست أمدحكم '),
(1201, '1 Corinthians', 46, 11, 23, ' لأنني تسلمت من الرب ما سلمتكم أيضا : إن الرب يسوع في الليلة التي أسلم فيها ، أخذ خبزا '),
(1202, '1 Corinthians', 46, 11, 24, ' وشكر فكسر ، وقال : خذوا كلوا هذا هو جسدي المكسور لأجلكم . اصنعوا هذا لذكري '),
(1203, '1 Corinthians', 46, 11, 25, ' كذلك الكأس أيضا بعدما تعشوا ، قائلا : هذه الكأس هي العهد الجديد بدمي . اصنعوا هذا كلما شربتم لذكري '),
(1204, '1 Corinthians', 46, 11, 26, ' فإنكم كلما أكلتم هذا الخبز وشربتم هذه الكأس ، تخبرون بموت الرب إلى أن يجيء '),
(1205, '1 Corinthians', 46, 11, 27, ' إذا أي من أكل هذا الخبز ، أو شرب كأس الرب ، بدون استحقاق ، يكون مجرما في جسد الرب ودمه '),
(1206, '1 Corinthians', 46, 11, 28, ' ولكن ليمتحن الإنسان نفسه ، وهكذا يأكل من الخبز ويشرب من الكأس '),
(1207, '1 Corinthians', 46, 11, 29, ' لأن الذي يأكل ويشرب بدون استحقاق يأكل ويشرب دينونة لنفسه ، غير مميز جسد الرب '),
(1208, '1 Corinthians', 46, 11, 30, ' من أجل هذا فيكم كثيرون ضعفاء ومرضى ، وكثيرون يرقدون '),
(1209, '1 Corinthians', 46, 11, 31, ' لأننا لو كنا حكمنا على أنفسنا لما حكم علينا '),
(1210, '1 Corinthians', 46, 11, 32, ' ولكن إذ قد حكم علينا ، نؤدب من الرب لكي لا ندان مع العالم '),
(1211, '1 Corinthians', 46, 11, 33, ' إذا يا إخوتي ، حين تجتمعون للأكل ، انتظروا بعضكم بعضا '),
(1212, '1 Corinthians', 46, 11, 34, ' إن كان أحد يجوع فليأكل في البيت ، كي لا تجتمعوا للدينونة . وأما الأمور الباقية فعندما أجيء أرتبها '),
(1213, '1 Corinthians', 46, 12, 1, ' وأما من جهة المواهب الروحية أيها الإخوة ، فلست أريد أن تجهلوا '),
(1214, '1 Corinthians', 46, 12, 2, ' أنتم تعلمون أنكم كنتم أمما منقادين إلى الأوثان البكم ، كما كنتم تساقون '),
(1215, '1 Corinthians', 46, 12, 3, ' لذلك أعرفكم أن ليس أحد وهو يتكلم بروح الله يقول : يسوع أناثيما . وليس أحد يقدر أن يقول : يسوع رب إلا بالروح القدس '),
(1216, '1 Corinthians', 46, 12, 4, ' فأنواع مواهب موجودة ، ولكن الروح واحد '),
(1217, '1 Corinthians', 46, 12, 5, ' وأنواع خدم موجودة ، ولكن الرب واحد '),
(1218, '1 Corinthians', 46, 12, 6, ' وأنواع أعمال موجودة ، ولكن الله واحد ، الذي يعمل الكل في الكل '),
(1219, '1 Corinthians', 46, 12, 7, ' ولكنه لكل واحد يعطى إظهار الروح للمنفعة '),
(1220, '1 Corinthians', 46, 12, 8, ' فإنه لواحد يعطى بالروح كلام حكمة ، ولآخر كلام علم بحسب الروح الواحد '),
(1221, '1 Corinthians', 46, 12, 9, ' ولآخر إيمان بالروح الواحد ، ولآخر مواهب شفاء بالروح الواحد '),
(1222, '1 Corinthians', 46, 12, 10, ' ولآخر عمل قوات ، ولآخر نبوة ، ولآخر تمييز الأرواح ، ولآخر أنواع ألسنة ، ولآخر ترجمة ألسنة '),
(1223, '1 Corinthians', 46, 12, 11, ' ولكن هذه كلها يعملها الروح الواحد بعينه ، قاسما لكل واحد بمفرده ، كما يشاء '),
(1224, '1 Corinthians', 46, 12, 12, ' لأنه كما أن الجسد هو واحد وله أعضاء كثيرة ، وكل أعضاء الجسد الواحد إذا كانت كثيرة هي جسد واحد ، كذلك المسيح أيضا '),
(1225, '1 Corinthians', 46, 12, 13, ' لأننا جميعنا بروح واحد أيضا اعتمدنا إلى جسد واحد ، يهودا كنا أم يونانيين ، عبيدا أم أحرارا ، وجميعنا سقينا روحا واحدا '),
(1226, '1 Corinthians', 46, 12, 14, ' فإن الجسد أيضا ليس عضوا واحدا بل أعضاء كثيرة '),
(1227, '1 Corinthians', 46, 12, 15, ' إن قالت الرجل : لأني لست يدا ، لست من الجسد . أفلم تكن لذلك من الجسد '),
(1228, '1 Corinthians', 46, 12, 16, ' وإن قالت الأذن : لأني لست عينا ، لست من الجسد . أفلم تكن لذلك من الجسد '),
(1229, '1 Corinthians', 46, 12, 17, ' لو كان كل الجسد عينا ، فأين السمع ؟ لو كان الكل سمعا ، فأين الشم '),
(1230, '1 Corinthians', 46, 12, 18, ' وأما الآن فقد وضع الله الأعضاء ، كل واحد منها في الجسد ، كما أراد '),
(1231, '1 Corinthians', 46, 12, 19, ' ولكن لو كان جميعها عضوا واحدا ، أين الجسد '),
(1232, '1 Corinthians', 46, 12, 20, ' فالآن أعضاء كثيرة ، ولكن جسد واحد '),
(1233, '1 Corinthians', 46, 12, 21, ' لا تقدر العين أن تقول لليد : لا حاجة لي إليك . أو الرأس أيضا للرجلين : لا حاجة لي إليكما '),
(1234, '1 Corinthians', 46, 12, 22, ' بل بالأولى أعضاء الجسد التي تظهر أضعف هي ضرورية '),
(1235, '1 Corinthians', 46, 12, 23, ' وأعضاء الجسد التي نحسب أنها بلا كرامة نعطيها كرامة أفضل . والأعضاء القبيحة فينا لها جمال أفضل '),
(1236, '1 Corinthians', 46, 12, 24, ' وأما الجميلة فينا فليس لها احتياج . لكن الله مزج الجسد ، معطيا الناقص كرامة أفضل '),
(1237, '1 Corinthians', 46, 12, 25, ' لكي لا يكون انشقاق في الجسد ، بل تهتم الأعضاء اهتماما واحدا بعضها لبعض '),
(1238, '1 Corinthians', 46, 12, 26, ' فإن كان عضو واحد يتألم ، فجميع الأعضاء تتألم معه . وإن كان عضو واحد يكرم ، فجميع الأعضاء تفرح معه '),
(1239, '1 Corinthians', 46, 12, 27, ' وأما أنتم فجسد المسيح ، وأعضاؤه أفرادا '),
(1240, '1 Corinthians', 46, 12, 28, ' فوضع الله أناسا في الكنيسة : أولا رسلا ، ثانيا أنبياء ، ثالثا معلمين ، ثم قوات ، وبعد ذلك مواهب شفاء ، أعوانا ، تدابير ، وأنواع ألسنة '),
(1241, '1 Corinthians', 46, 12, 29, ' ألعل الجميع رسل ؟ ألعل الجميع أنبياء ؟ ألعل الجميع معلمون ؟ ألعل الجميع أصحاب قوات '),
(1242, '1 Corinthians', 46, 12, 30, ' ألعل للجميع مواهب شفاء ؟ ألعل الجميع يتكلمون بألسنة ؟ ألعل الجميع يترجمون '),
(1243, '1 Corinthians', 46, 12, 31, ' ولكن جدوا للمواهب الحسنى . وأيضا أريكم طريقا أفضل '),
(1244, '1 Corinthians', 46, 13, 1, ' إن كنت أتكلم بألسنة الناس والملائكة ولكن ليس لي محبة ، فقد صرت نحاسا يطن أو صنجا يرن '),
(1245, '1 Corinthians', 46, 13, 2, ' وإن كانت لي نبوة ، وأعلم جميع الأسرار وكل علم ، وإن كان لي كل الإيمان حتى أنقل الجبال ، ولكن ليس لي محبة ، فلست شيئا '),
(1246, '1 Corinthians', 46, 13, 3, ' وإن أطعمت كل أموالي ، وإن سلمت جسدي حتى أحترق ، ولكن ليس لي محبة ، فلا أنتفع شيئا '),
(1247, '1 Corinthians', 46, 13, 4, ' المحبة تتأنى وترفق . المحبة لا تحسد . المحبة لا تتفاخر ، ولا تنتفخ '),
(1248, '1 Corinthians', 46, 13, 5, ' ولا تقبح ، ولا تطلب ما لنفسها ، ولا تحتد ، ولا تظن السؤ '),
(1249, '1 Corinthians', 46, 13, 6, ' ولا تفرح بالإثم بل تفرح بالحق '),
(1250, '1 Corinthians', 46, 13, 7, ' وتحتمل كل شيء ، وتصدق كل شيء ، وترجو كل شيء ، وتصبر على كل شيء '),
(1251, '1 Corinthians', 46, 13, 8, ' المحبة لا تسقط أبدا . وأما النبوات فستبطل ، والألسنة فستنتهي ، والعلم فسيبطل '),
(1252, '1 Corinthians', 46, 13, 9, ' لأننا نعلم بعض العلم ونتنبأ بعض التنبؤ '),
(1253, '1 Corinthians', 46, 13, 10, ' ولكن متى جاء الكامل فحينئذ يبطل ما هو بعض '),
(1254, '1 Corinthians', 46, 13, 11, ' لما كنت طفلا كطفل كنت أتكلم ، وكطفل كنت أفطن ، وكطفل كنت أفتكر . ولكن لما صرت رجلا أبطلت ما للطفل '),
(1255, '1 Corinthians', 46, 13, 12, ' فإننا ننظر الآن في مرآة ، في لغز ، لكن حينئذ وجها لوجه . الآن أعرف بعض المعرفة ، لكن حينئذ سأعرف كما عرفت '),
(1256, '1 Corinthians', 46, 13, 13, ' أما الآن فيثبت : الإيمان والرجاء والمحبة ، هذه الثلاثة ولكن أعظمهن المحبة '),
(1257, '1 Corinthians', 46, 14, 1, ' اتبعوا المحبة ، ولكن جدوا للمواهب الروحية ، وبالأولى أن تتنبأوا '),
(1258, '1 Corinthians', 46, 14, 2, ' لأن من يتكلم بلسان لا يكلم الناس بل الله ، لأن ليس أحد يسمع ، ولكنه بالروح يتكلم بأسرار '),
(1259, '1 Corinthians', 46, 14, 3, ' وأما من يتنبأ ، فيكلم الناس ببنيان ووعظ وتسلية '),
(1260, '1 Corinthians', 46, 14, 4, ' من يتكلم بلسان يبني نفسه ، وأما من يتنبأ فيبني الكنيسة '),
(1261, '1 Corinthians', 46, 14, 5, ' إني أريد أن جميعكم تتكلمون بألسنة ، ولكن بالأولى أن تتنبأوا . لأن من يتنبأ أعظم ممن يتكلم بألسنة ، إلا إذا ترجم ، حتى تنال الكنيسة بنيانا '),
(1262, '1 Corinthians', 46, 14, 6, ' فالآن أيها الإخوة ، إن جئت إليكم متكلما بألسنة ، فماذا أنفعكم ، إن لم أكلمكم إما بإعلان ، أو بعلم ، أو بنبوة ، أو بتعليم '),
(1263, '1 Corinthians', 46, 14, 7, ' الأشياء العادمة النفوس التي تعطي صوتا : مزمار أو قيثارة ، مع ذلك إن لم تعط فرقا للنغمات ، فكيف يعرف ما زمر أو ما عزف به '),
(1264, '1 Corinthians', 46, 14, 8, ' فإنه إن أعطى البوق أيضا صوتا غير واضح ، فمن يتهيأ للقتال '),
(1265, '1 Corinthians', 46, 14, 9, ' هكذا أنتم أيضا إن لم تعطوا باللسان كلاما يفهم ، فكيف يعرف ما تكلم به ؟ فإنكم تكونون تتكلمون في الهواء '),
(1266, '1 Corinthians', 46, 14, 10, ' ربما تكون أنواع لغات هذا عددها في العالم ، وليس شيء منها بلا معنى '),
(1267, '1 Corinthians', 46, 14, 11, ' فإن كنت لا أعرف قوة اللغة أكون عند المتكلم أعجميا ، والمتكلم أعجميا عندي '),
(1268, '1 Corinthians', 46, 14, 12, ' هكذا أنتم أيضا ، إذ إنكم غيورون للمواهب الروحية ، اطلبوا لأجل بنيان الكنيسة أن تزدادوا '),
(1269, '1 Corinthians', 46, 14, 13, ' لذلك من يتكلم بلسان فليصل لكي يترجم '),
(1270, '1 Corinthians', 46, 14, 14, ' لأنه إن كنت أصلي بلسان ، فروحي تصلي ، وأما ذهني فهو بلا ثمر '),
(1271, '1 Corinthians', 46, 14, 15, ' فما هو إذا ؟ أصلي بالروح ، وأصلي بالذهن أيضا . أرتل بالروح ، وأرتل بالذهن أيضا '),
(1272, '1 Corinthians', 46, 14, 16, ' وإلا فإن باركت بالروح ، فالذي يشغل مكان العامي ، كيف يقول آمين عند شكرك ؟ لأنه لا يعرف ماذا تقول '),
(1273, '1 Corinthians', 46, 14, 17, ' فإنك أنت تشكر حسنا ، ولكن الآخر لا يبنى '),
(1274, '1 Corinthians', 46, 14, 18, ' أشكر إلهي أني أتكلم بألسنة أكثر من جميعكم '),
(1275, '1 Corinthians', 46, 14, 19, ' ولكن ، في كنيسة ، أريد أن أتكلم خمس كلمات بذهني لكي أعلم آخرين أيضا ، أكثر من عشرة آلاف كلمة بلسان '),
(1276, '1 Corinthians', 46, 14, 20, ' أيها الإخوة ، لا تكونوا أولادا في أذهانكم ، بل كونوا أولادا في الشر ، وأما في الأذهان فكونوا كاملين '),
(1277, '1 Corinthians', 46, 14, 21, ' مكتوب في الناموس : إني بذوي ألسنة أخرى وبشفاه أخرى سأكلم هذا الشعب ، ولا هكذا يسمعون لي ، يقول الرب '),
(1278, '1 Corinthians', 46, 14, 22, ' إذا الألسنة آية ، لا للمؤمنين ، بل لغير المؤمنين . أما النبوة فليست لغير المؤمنين ، بل للمؤمنين '),
(1279, '1 Corinthians', 46, 14, 23, ' فإن اجتمعت الكنيسة كلها في مكان واحد ، وكان الجميع يتكلمون بألسنة ، فدخل عاميون أو غير مؤمنين ، أفلا يقولون إنكم تهذون '),
(1280, '1 Corinthians', 46, 14, 24, ' ولكن إن كان الجميع يتنبأون ، فدخل أحد غير مؤمن أو عامي ، فإنه يوبخ من الجميع . يحكم عليه من الجميع '),
(1281, '1 Corinthians', 46, 14, 25, ' وهكذا تصير خفايا قلبه ظاهرة . وهكذا يخر على وجهه ويسجد لله ، مناديا : أن الله بالحقيقة فيكم '),
(1282, '1 Corinthians', 46, 14, 26, ' فما هو إذا أيها الإخوة ؟ متى اجتمعتم فكل واحد منكم له مزمور ، له تعليم ، له لسان ، له إعلان ، له ترجمة . فليكن كل شيء للبنيان '),
(1283, '1 Corinthians', 46, 14, 27, ' إن كان أحد يتكلم بلسان ، فاثنين اثنين ، أو على الأكثر ثلاثة ثلاثة ، وبترتيب ، وليترجم واحد '),
(1284, '1 Corinthians', 46, 14, 28, ' ولكن إن لم يكن مترجم فليصمت في الكنيسة ، وليكلم نفسه والله '),
(1285, '1 Corinthians', 46, 14, 29, ' أما الأنبياء فليتكلم اثنان أو ثلاثة ، وليحكم الآخرون '),
(1286, '1 Corinthians', 46, 14, 30, ' ولكن إن أعلن لآخر جالس فليسكت الأول '),
(1287, '1 Corinthians', 46, 14, 31, ' لأنكم تقدرون جميعكم أن تتنبأوا واحدا واحدا ، ليتعلم الجميع ويتعزى الجميع '),
(1288, '1 Corinthians', 46, 14, 32, ' وأرواح الأنبياء خاضعة للأنبياء '),
(1289, '1 Corinthians', 46, 14, 33, ' لأن الله ليس إله تشويش بل إله سلام ، كما في جميع كنائس القديسين '),
(1290, '1 Corinthians', 46, 14, 34, ' لتصمت نساؤكم في الكنائس ، لأنه ليس مأذونا لهن أن يتكلمن ، بل يخضعن كما يقول الناموس أيضا '),
(1291, '1 Corinthians', 46, 14, 35, ' ولكن إن كن يردن أن يتعلمن شيئا ، فليسألن رجالهن في البيت ، لأنه قبيح بالنساء أن تتكلم في كنيسة '),
(1292, '1 Corinthians', 46, 14, 36, ' أم منكم خرجت كلمة الله ؟ أم إليكم وحدكم انتهت '),
(1293, '1 Corinthians', 46, 14, 37, ' إن كان أحد يحسب نفسه نبيا أو روحيا ، فليعلم ما أكتبه إليكم أنه وصايا الرب '),
(1294, '1 Corinthians', 46, 14, 38, ' ولكن إن يجهل أحد ، فليجهل '),
(1295, '1 Corinthians', 46, 14, 39, ' إذا أيها الإخوة جدوا للتنبؤ ، ولا تمنعوا التكلم بألسنة '),
(1296, '1 Corinthians', 46, 14, 40, ' وليكن كل شيء بلياقة وبحسب ترتيب '),
(1297, '1 Corinthians', 46, 15, 1, ' وأعرفكم أيها الإخوة بالإنجيل الذي بشرتكم به ، وقبلتموه ، وتقومون فيه '),
(1298, '1 Corinthians', 46, 15, 2, ' وبه أيضا تخلصون ، إن كنتم تذكرون أي كلام بشرتكم به . إلا إذا كنتم قد آمنتم عبثا '),
(1299, '1 Corinthians', 46, 15, 3, ' فإنني سلمت إليكم في الأول ما قبلته أنا أيضا : أن المسيح مات من أجل خطايانا حسب الكتب '),
(1300, '1 Corinthians', 46, 15, 4, ' وأنه دفن ، وأنه قام في اليوم الثالث حسب الكتب '),
(1301, '1 Corinthians', 46, 15, 5, ' وأنه ظهر لصفا ثم للاثني عشر '),
(1302, '1 Corinthians', 46, 15, 6, ' وبعد ذلك ظهر دفعة واحدة لأكثر من خمسمئة أخ ، أكثرهم باق إلى الآن . ولكن بعضهم قد رقدوا '),
(1303, '1 Corinthians', 46, 15, 7, ' وبعد ذلك ظهر ليعقوب ، ثم للرسل أجمعين '),
(1304, '1 Corinthians', 46, 15, 8, ' وآخر الكل - كأنه للسقط - ظهر لي أنا '),
(1305, '1 Corinthians', 46, 15, 9, ' لأني أصغر الرسل ، أنا الذي لست أهلا لأن أدعى رسولا ، لأني اضطهدت كنيسة الله '),
(1306, '1 Corinthians', 46, 15, 10, ' ولكن بنعمة الله أنا ما أنا ، ونعمته المعطاة لي لم تكن باطلة ، بل أنا تعبت أكثر منهم جميعهم . ولكن لا أنا ، بل نعمة الله التي معي '),
(1307, '1 Corinthians', 46, 15, 11, ' فسواء أنا أم أولئك ، هكذا نكرز وهكذا آمنتم '),
(1308, '1 Corinthians', 46, 15, 12, ' ولكن إن كان المسيح يكرز به أنه قام من الأموات ، فكيف يقول قوم بينكم إن ليس قيامة أموات '),
(1309, '1 Corinthians', 46, 15, 13, ' فإن لم تكن قيامة أموات فلا يكون المسيح قد قام '),
(1310, '1 Corinthians', 46, 15, 14, ' وإن لم يكن المسيح قد قام ، فباطلة كرازتنا وباطل أيضا إيمانكم '),
(1311, '1 Corinthians', 46, 15, 15, ' ونوجد نحن أيضا شهود زور لله ، لأننا شهدنا من جهة الله أنه أقام المسيح وهو لم يقمه ، إن كان الموتى لا يقومون '),
(1312, '1 Corinthians', 46, 15, 16, ' لأنه إن كان الموتى لا يقومون ، فلا يكون المسيح قد قام '),
(1313, '1 Corinthians', 46, 15, 17, ' وإن لم يكن المسيح قد قام ، فباطل إيمانكم . أنتم بعد في خطاياكم '),
(1314, '1 Corinthians', 46, 15, 18, ' إذا الذين رقدوا في المسيح أيضا هلكوا '),
(1315, '1 Corinthians', 46, 15, 19, ' إن كان لنا في هذه الحياة فقط رجاء في المسيح ، فإننا أشقى جميع الناس '),
(1316, '1 Corinthians', 46, 15, 20, ' ولكن الآن قد قام المسيح من الأموات وصار باكورة الراقدين '),
(1317, '1 Corinthians', 46, 15, 21, ' فإنه إذ الموت بإنسان ، بإنسان أيضا قيامة الأموات '),
(1318, '1 Corinthians', 46, 15, 22, ' لأنه كما في آدم يموت الجميع ، هكذا في المسيح سيحيا الجميع '),
(1319, '1 Corinthians', 46, 15, 23, ' ولكن كل واحد في رتبته : المسيح باكورة ، ثم الذين للمسيح في مجيئه '),
(1320, '1 Corinthians', 46, 15, 24, ' وبعد ذلك النهاية ، متى سلم الملك لله الآب ، متى أبطل كل رياسة وكل سلطان وكل قوة '),
(1321, '1 Corinthians', 46, 15, 25, ' لأنه يجب أن يملك حتى يضع جميع الأعداء تحت قدميه '),
(1322, '1 Corinthians', 46, 15, 26, ' آخر عدو يبطل هو الموت '),
(1323, '1 Corinthians', 46, 15, 27, ' لأنه أخضع كل شيء تحت قدميه . ولكن حينما يقول : إن كل شيء قد أخضع فواضح أنه غير الذي أخضع له الكل '),
(1324, '1 Corinthians', 46, 15, 28, ' ومتى أخضع له الكل ، فحينئذ الابن نفسه أيضا سيخضع للذي أخضع له الكل ، كي يكون الله الكل في الكل '),
(1325, '1 Corinthians', 46, 15, 29, ' وإلا فماذا يصنع الذين يعتمدون من أجل الأموات ؟ إن كان الأموات لا يقومون البتة ، فلماذا يعتمدون من أجل الأموات '),
(1326, '1 Corinthians', 46, 15, 30, ' ولماذا نخاطر نحن كل ساعة '),
(1327, '1 Corinthians', 46, 15, 31, ' إني بافتخاركم الذي لي في يسوع المسيح ربنا ، أموت كل يوم '),
(1328, '1 Corinthians', 46, 15, 32, ' إن كنت كإنسان قد حاربت وحوشا في أفسس ، فما المنفعة لي ؟ إن كان الأموات لا يقومون ، فلنأكل ونشرب لأننا غدا نموت '),
(1329, '1 Corinthians', 46, 15, 33, ' لا تضلوا : فإن المعاشرات الردية تفسد الأخلاق الجيدة '),
(1330, '1 Corinthians', 46, 15, 34, ' اصحوا للبر ولا تخطئوا ، لأن قوما ليست لهم معرفة بالله . أقول ذلك لتخجيلكم '),
(1331, '1 Corinthians', 46, 15, 35, ' لكن يقول قائل : كيف يقام الأموات ؟ وبأي جسم يأتون '),
(1332, '1 Corinthians', 46, 15, 36, ' يا غبي الذي تزرعه لا يحيا إن لم يمت '),
(1333, '1 Corinthians', 46, 15, 37, ' والذي تزرعه ، لست تزرع الجسم الذي سوف يصير ، بل حبة مجردة ، ربما من حنطة أو أحد البواقي '),
(1334, '1 Corinthians', 46, 15, 38, ' ولكن الله يعطيها جسما كما أراد . ولكل واحد من البزور جسمه '),
(1335, '1 Corinthians', 46, 15, 39, ' ليس كل جسد جسدا واحدا ، بل للناس جسد واحد ، وللبهائم جسد آخر ، وللسمك آخر ، وللطير آخر '),
(1336, '1 Corinthians', 46, 15, 40, ' وأجسام سماوية ، وأجسام أرضية . لكن مجد السماويات شيء ، ومجد الأرضيات آخر '),
(1337, '1 Corinthians', 46, 15, 41, ' مجد الشمس شيء ، ومجد القمر آخر ، ومجد النجوم آخر . لأن نجما يمتاز عن نجم في المجد '),
(1338, '1 Corinthians', 46, 15, 42, ' هكذا أيضا قيامة الأموات : يزرع في فساد ويقام في عدم فساد '),
(1339, '1 Corinthians', 46, 15, 43, ' يزرع في هوان ويقام في مجد . يزرع في ضعف ويقام في قوة '),
(1340, '1 Corinthians', 46, 15, 44, ' يزرع جسما حيوانيا ويقام جسما روحانيا . يوجد جسم حيواني ويوجد جسم روحاني '),
(1341, '1 Corinthians', 46, 15, 45, ' هكذا مكتوب أيضا : صار آدم ، الإنسان الأول ، نفسا حية ، وآدم الأخير روحا محييا '),
(1342, '1 Corinthians', 46, 15, 46, ' لكن ليس الروحاني أولا بل الحيواني ، وبعد ذلك الروحاني '),
(1343, '1 Corinthians', 46, 15, 47, ' الإنسان الأول من الأرض ترابي . الإنسان الثاني ، الرب ، من السماء '),
(1344, '1 Corinthians', 46, 15, 48, ' كما هو الترابي هكذا الترابيون أيضا ، وكما هو السماوي هكذا السماويون أيضا '),
(1345, '1 Corinthians', 46, 15, 49, ' وكما لبسنا صورة الترابي ، سنلبس أيضا صورة السماوي '),
(1346, '1 Corinthians', 46, 15, 50, ' فأقول هذا أيها الإخوة : إن لحما ودما لا يقدران أن يرثا ملكوت الله ، ولا يرث الفساد عدم الفساد '),
(1347, '1 Corinthians', 46, 15, 51, ' هوذا سر أقوله لكم : لا نرقد كلنا ، ولكننا كلنا نتغير '),
(1348, '1 Corinthians', 46, 15, 52, ' في لحظة في طرفة عين ، عند البوق الأخير . فإنه سيبوق ، فيقام الأموات عديمي فساد ، ونحن نتغير '),
(1349, '1 Corinthians', 46, 15, 53, ' لأن هذا الفاسد لابد أن يلبس عدم فساد ، وهذا المائت يلبس عدم موت '),
(1350, '1 Corinthians', 46, 15, 54, ' ومتى لبس هذا الفاسد عدم فساد ، ولبس هذا المائت عدم موت ، فحينئذ تصير الكلمة المكتوبة : ابتلع الموت إلى غلبة '),
(1351, '1 Corinthians', 46, 15, 55, ' أين شوكتك يا موت ؟ أين غلبتك يا هاوية '),
(1352, '1 Corinthians', 46, 15, 56, ' أما شوكة الموت فهي الخطية ، وقوة الخطية هي الناموس '),
(1353, '1 Corinthians', 46, 15, 57, ' ولكن شكرا لله الذي يعطينا الغلبة بربنا يسوع المسيح '),
(1354, '1 Corinthians', 46, 15, 58, ' إذا يا إخوتي الأحباء ، كونوا راسخين ، غير متزعزعين ، مكثرين في عمل الرب كل حين ، عالمين أن تعبكم ليس باطلا في الرب '),
(1355, '1 Corinthians', 46, 16, 1, ' وأما من جهة الجمع لأجل القديسين ، فكما أوصيت كنائس غلاطية هكذا افعلوا أنتم أيضا '),
(1356, '1 Corinthians', 46, 16, 2, ' في كل أول أسبوع ، ليضع كل واحد منكم عنده ، خازنا ما تيسر ، حتى إذا جئت لا يكون جمع حينئذ '),
(1357, '1 Corinthians', 46, 16, 3, ' ومتى حضرت ، فالذين تستحسنونهم أرسلهم برسائل ليحملوا إحسانكم إلى أورشليم '),
(1358, '1 Corinthians', 46, 16, 4, ' وإن كان يستحق أن أذهب أنا أيضا ، فسيذهبون معي '),
(1359, '1 Corinthians', 46, 16, 5, ' وسأجيء إليكم متى اجتزت بمكدونية ، لأني أجتاز بمكدونية '),
(1360, '1 Corinthians', 46, 16, 6, ' وربما أمكث عندكم أو أشتي أيضا لكي تشيعوني إلى حيثما أذهب '),
(1361, '1 Corinthians', 46, 16, 7, ' لأني لست أريد الآن أن أراكم في العبور ، لأني أرجو أن أمكث عندكم زمانا إن أذن الرب '),
(1362, '1 Corinthians', 46, 16, 8, ' ولكنني أمكث في أفسس إلى يوم الخمسين '),
(1363, '1 Corinthians', 46, 16, 9, ' لأنه قد انفتح لي باب عظيم فعال ، ويوجد معاندون كثيرون '),
(1364, '1 Corinthians', 46, 16, 10, ' ثم إن أتى تيموثاوس ، فانظروا أن يكون عندكم بلا خوف . لأنه يعمل عمل الرب كما أنا أيضا '),
(1365, '1 Corinthians', 46, 16, 11, ' فلا يحتقره أحد ، بل شيعوه بسلام ليأتي إلي ، لأني أنتظره مع الإخوة '),
(1366, '1 Corinthians', 46, 16, 12, ' وأما من جهة أبلوس الأخ ، فطلبت إليه كثيرا أن يأتي إليكم مع الإخوة ، ولم تكن له إرادة البتة أن يأتي الآن . ولكنه سيأتي متى توفق الوقت '),
(1367, '1 Corinthians', 46, 16, 13, ' اسهروا . اثبتوا في الإيمان . كونوا رجالا . تقووا '),
(1368, '1 Corinthians', 46, 16, 14, ' لتصر كل أموركم في محبة '),
(1369, '1 Corinthians', 46, 16, 15, ' وأطلب إليكم أيها الإخوة : أنتم تعرفون بيت استفاناس أنهم باكورة أخائية ، وقد رتبوا أنفسهم لخدمة القديسين '),
(1370, '1 Corinthians', 46, 16, 16, ' كي تخضعوا أنتم أيضا لمثل هؤلاء ، وكل من يعمل معهم ويتعب '),
(1371, '1 Corinthians', 46, 16, 17, ' ثم إني أفرح بمجيء استفاناس وفرتوناتوس وأخائيكوس ، لأن نقصانكم ، هؤلاء قد جبروه '),
(1372, '1 Corinthians', 46, 16, 18, ' إذ أراحوا روحي وروحكم . فاعرفوا مثل هؤلاء '),
(1373, '1 Corinthians', 46, 16, 19, ' تسلم عليكم كنائس أسيا . يسلم عليكم في الرب كثيرا أكيلا وبريسكلا مع الكنيسة التي في بيتهما '),
(1374, '1 Corinthians', 46, 16, 20, ' يسلم عليكم الإخوة أجمعون . سلموا بعضكم على بعض بقبلة مقدسة '),
(1375, '1 Corinthians', 46, 16, 21, ' السلام بيدي أنا بولس '),
(1376, '1 Corinthians', 46, 16, 22, ' إن كان أحد لا يحب الرب يسوع المسيح فليكن أناثيما ماران أثا '),
(1377, '1 Corinthians', 46, 16, 23, ' نعمة الرب يسوع المسيح معكم . '),
(1378, '1 Corinthians', 46, 16, 24, ' محبتي مع جميعكم في المسيح يسوع . آمين '),
(1379, '1 John', 62, 1, 1, ' الذي كان من البدء ، الذي سمعناه ، الذي رأيناه بعيوننا ، الذي شاهدناه ، ولمسته أيدينا ، من جهة كلمة الحياة '),
(1380, '1 John', 62, 1, 2, ' فإن الحياة أظهرت ، وقد رأينا ونشهد ونخبركم بالحياة الأبدية التي كانت عند الآب وأظهرت لنا '),
(1381, '1 John', 62, 1, 3, ' الذي رأيناه وسمعناه نخبركم به ، لكي يكون لكم أيضا شركة معنا . وأما شركتنا نحن فهي مع الآب ومع ابنه يسوع المسيح '),
(1382, '1 John', 62, 1, 4, ' ونكتب إليكم هذا لكي يكون فرحكم كاملا '),
(1383, '1 John', 62, 1, 5, ' وهذا هو الخبر الذي سمعناه منه ونخبركم به : إن الله نور وليس فيه ظلمة البتة '),
(1384, '1 John', 62, 1, 6, ' إن قلنا : إن لنا شركة معه وسلكنا في الظلمة ، نكذب ولسنا نعمل الحق '),
(1385, '1 John', 62, 1, 7, ' ولكن إن سلكنا في النور كما هو في النور ، فلنا شركة بعضنا مع بعض ، ودم يسوع المسيح ابنه يطهرنا من كل خطية '),
(1386, '1 John', 62, 1, 8, ' إن قلنا : إنه ليس لنا خطية ، نضل أنفسنا وليس الحق فينا '),
(1387, '1 John', 62, 1, 9, ' إن اعترفنا بخطايانا فهو أمين وعادل ، حتى يغفر لنا خطايانا ويطهرنا من كل إثم '),
(1388, '1 John', 62, 1, 10, ' إن قلنا : إننا لم نخطئ نجعله كاذبا ، وكلمته ليست فينا ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(1389, '1 John', 62, 2, 1, ' يا أولادي ، أكتب إليكم هذا لكي لا تخطئوا . وإن أخطأ أحد فلنا شفيع عند الآب ، يسوع المسيح البار '),
(1390, '1 John', 62, 2, 2, ' وهو كفارة لخطايانا . ليس لخطايانا فقط ، بل لخطايا كل العالم أيضا '),
(1391, '1 John', 62, 2, 3, ' وبهذا نعرف أننا قد عرفناه : إن حفظنا وصاياه '),
(1392, '1 John', 62, 2, 4, ' من قال : قد عرفته وهو لا يحفظ وصاياه ، فهو كاذب وليس الحق فيه '),
(1393, '1 John', 62, 2, 5, ' وأما من حفظ كلمته ، فحقا في هذا قد تكملت محبة الله . بهذا نعرف أننا فيه '),
(1394, '1 John', 62, 2, 6, ' من قال : إنه ثابت فيه ينبغي أنه كما سلك ذاك هكذا يسلك هو أيضا '),
(1395, '1 John', 62, 2, 7, ' أيها الإخوة ، لست أكتب إليكم وصية جديدة ، بل وصية قديمة كانت عندكم من البدء . الوصية القديمة هي الكلمة التي سمعتموها من البدء '),
(1396, '1 John', 62, 2, 8, ' أيضا وصية جديدة أكتب إليكم ، ما هو حق فيه وفيكم : أن الظلمة قد مضت ، والنور الحقيقي الآن يضيء '),
(1397, '1 John', 62, 2, 9, ' من قال : إنه في النور وهو يبغض أخاه ، فهو إلى الآن في الظلمة '),
(1398, '1 John', 62, 2, 10, ' من يحب أخاه يثبت في النور وليس فيه عثرة '),
(1399, '1 John', 62, 2, 11, ' وأما من يبغض أخاه فهو في الظلمة ، وفي الظلمة يسلك ، ولا يعلم أين يمضي ، لأن الظلمة أعمت عينيه '),
(1400, '1 John', 62, 2, 12, ' أكتب إليكم أيها الأولاد ، لأنه قد غفرت لكم الخطايا من أجل اسمه '),
(1401, '1 John', 62, 2, 13, ' أكتب إليكم أيها الآباء ، لأنكم قد عرفتم الذي من البدء . أكتب إليكم أيها الأحداث ، لأنكم قد غلبتم الشرير . أكتب إليكم أيها الأولاد ، لأنكم قد عرفتم الآب '),
(1402, '1 John', 62, 2, 14, ' كتبت إليكم أيها الآباء ، لأنكم قد عرفتم الذي من البدء . كتبت إليكم أيها الأحداث ، لأنكم أقوياء ، وكلمة الله ثابتة فيكم ، وقد غلبتم الشرير '),
(1403, '1 John', 62, 2, 15, ' لا تحبوا العالم ولا الأشياء التي في العالم . إن أحب أحد العالم فليست فيه محبة الآب '),
(1404, '1 John', 62, 2, 16, ' لأن كل ما في العالم : شهوة الجسد ، وشهوة العيون ، وتعظم المعيشة ، ليس من الآب بل من العالم '),
(1405, '1 John', 62, 2, 17, ' والعالم يمضي وشهوته ، وأما الذي يصنع مشيئة الله فيثبت إلى الأبد '),
(1406, '1 John', 62, 2, 18, ' أيها الأولاد هي الساعة الأخيرة . وكما سمعتم أن ضد المسيح يأتي ، قد صار الآن أضداد للمسيح كثيرون . من هنا نعلم أنها الساعة الأخيرة '),
(1407, '1 John', 62, 2, 19, ' منا خرجوا ، لكنهم لم يكونوا منا ، لأنهم لو كانوا منا لبقوا معنا . لكن ليظهروا أنهم ليسوا جميعهم منا '),
(1408, '1 John', 62, 2, 20, ' وأما أنتم فلكم مسحة من القدوس وتعلمون كل شيء '),
(1409, '1 John', 62, 2, 21, ' لم أكتب إليكم لأنكم لستم تعلمون الحق ، بل لأنكم تعلمونه ، وأن كل كذب ليس من الحق '),
(1410, '1 John', 62, 2, 22, ' من هو الكذاب ، إلا الذي ينكر أن يسوع هو المسيح ؟ هذا هو ضد المسيح ، الذي ينكر الآب والابن '),
(1411, '1 John', 62, 2, 23, ' كل من ينكر الابن ليس له الآب أيضا ، ومن يعترف بالابن فله الآب أيضا '),
(1412, '1 John', 62, 2, 24, ' أما أنتم فما سمعتموه من البدء فليثبت إذا فيكم . إن ثبت فيكم ما سمعتموه من البدء ، فأنتم أيضا تثبتون في الابن وفي الآب '),
(1413, '1 John', 62, 2, 25, ' وهذا هو الوعد الذي وعدنا هو به : الحياة الأبدية '),
(1414, '1 John', 62, 2, 26, ' كتبت إليكم هذا عن الذين يضلونكم '),
(1415, '1 John', 62, 2, 27, ' وأما أنتم فالمسحة التي أخذتموها منه ثابتة فيكم ، ولا حاجة بكم إلى أن يعلمكم أحد ، بل كما تعلمكم هذه المسحة عينها عن كل شيء ، وهي حق وليست كذبا . كما علمتكم تثبتون فيه '),
(1416, '1 John', 62, 2, 28, ' والآن أيها الأولاد ، اثبتوا فيه ، حتى إذا أظهر يكون لنا ثقة ، ولا نخجل منه في مجيئه '),
(1417, '1 John', 62, 2, 29, ' إن علمتم أنه بار هو ، فاعلموا أن كل من يصنع البر مولود منه '),
(1418, '1 John', 62, 3, 1, ' انظروا أية محبة أعطانا الآب حتى ندعى أولاد الله من أجل هذا لا يعرفنا العالم ، لأنه لا يعرفه '),
(1419, '1 John', 62, 3, 2, ' أيها الأحباء ، الآن نحن أولاد الله ، ولم يظهر بعد ماذا سنكون . ولكن نعلم أنه إذا أظهر نكون مثله ، لأننا سنراه كما هو '),
(1420, '1 John', 62, 3, 3, ' وكل من عنده هذا الرجاء به ، يطهر نفسه كما هو طاهر '),
(1421, '1 John', 62, 3, 4, ' كل من يفعل الخطية يفعل التعدي أيضا . والخطية هي التعدي '),
(1422, '1 John', 62, 3, 5, ' وتعلمون أن ذاك أظهر لكي يرفع خطايانا ، وليس فيه خطية '),
(1423, '1 John', 62, 3, 6, ' كل من يثبت فيه لا يخطئ . كل من يخطئ لم يبصره ولا عرفه '),
(1424, '1 John', 62, 3, 7, ' أيها الأولاد ، لا يضلكم أحد : من يفعل البر فهو بار ، كما أن ذاك بار '),
(1425, '1 John', 62, 3, 8, ' من يفعل الخطية فهو من إبليس ، لأن إبليس من البدء يخطئ . لأجل هذا أظهر ابن الله لكي ينقض أعمال إبليس '),
(1426, '1 John', 62, 3, 9, ' كل من هو مولود من الله لا يفعل خطية ، لأن زرعه يثبت فيه ، ولا يستطيع أن يخطئ لأنه مولود من الله '),
(1427, '1 John', 62, 3, 10, ' بهذا أولاد الله ظاهرون وأولاد إبليس : كل من لا يفعل البر فليس من الله ، وكذا من لا يحب أخاه '),
(1428, '1 John', 62, 3, 11, ' لأن هذا هو الخبر الذي سمعتموه من البدء : أن يحب بعضنا بعضا '),
(1429, '1 John', 62, 3, 12, ' ليس كما كان قايين من الشرير وذبح أخاه . ولماذا ذبحه ؟ لأن أعماله كانت شريرة ، وأعمال أخيه بارة '),
(1430, '1 John', 62, 3, 13, ' لا تتعجبوا يا إخوتي إن كان العالم يبغضكم '),
(1431, '1 John', 62, 3, 14, ' نحن نعلم أننا قد انتقلنا من الموت إلى الحياة ، لأننا نحب الإخوة . من لا يحب أخاه يبق في الموت '),
(1432, '1 John', 62, 3, 15, ' كل من يبغض أخاه فهو قاتل نفس ، وأنتم تعلمون أن كل قاتل نفس ليس له حياة أبدية ثابتة فيه '),
(1433, '1 John', 62, 3, 16, ' بهذا قد عرفنا المحبة : أن ذاك وضع نفسه لأجلنا ، فنحن ينبغي لنا أن نضع نفوسنا لأجل الإخوة '),
(1434, '1 John', 62, 3, 17, ' وأما من كان له معيشة العالم ، ونظر أخاه محتاجا ، وأغلق أحشاءه عنه ، فكيف تثبت محبة الله فيه '),
(1435, '1 John', 62, 3, 18, ' يا أولادي ، لا نحب بالكلام ولا باللسان ، بل بالعمل والحق '),
(1436, '1 John', 62, 3, 19, ' وبهذا نعرف أننا من الحق ونسكن قلوبنا قدامه '),
(1437, '1 John', 62, 3, 20, ' لأنه إن لامتنا قلوبنا فالله أعظم من قلوبنا ، ويعلم كل شيء '),
(1438, '1 John', 62, 3, 21, ' أيها الأحباء ، إن لم تلمنا قلوبنا ، فلنا ثقة من نحو الله '),
(1439, '1 John', 62, 3, 22, ' ومهما سألنا ننال منه ، لأننا نحفظ وصاياه ، ونعمل الأعمال المرضية أمامه '),
(1440, '1 John', 62, 3, 23, ' وهذه هي وصيته : أن نؤمن باسم ابنه يسوع المسيح ، ونحب بعضنا بعضا كما أعطانا وصية '),
(1441, '1 John', 62, 3, 24, ' ومن يحفظ وصاياه يثبت فيه وهو فيه . وبهذا نعرف أنه يثبت فينا : من الروح الذي أعطانا '),
(1442, '1 John', 62, 4, 1, ' أيها الأحباء ، لا تصدقوا كل روح ، بل امتحنوا الأرواح : هل هي من الله ؟ لأن أنبياء كذبة كثيرين قد خرجوا إلى العالم '),
(1443, '1 John', 62, 4, 2, ' بهذا تعرفون روح الله : كل روح يعترف بيسوع المسيح أنه قد جاء في الجسد فهو من الله '),
(1444, '1 John', 62, 4, 3, ' وكل روح لا يعترف بيسوع المسيح أنه قد جاء في الجسد ، فليس من الله . وهذا هو روح ضد المسيح الذي سمعتم أنه يأتي ، والآن هو في العالم '),
(1445, '1 John', 62, 4, 4, ' أنتم من الله أيها الأولاد ، وقد غلبتموهم لأن الذي فيكم أعظم من الذي في العالم '),
(1446, '1 John', 62, 4, 5, ' هم من العالم . من أجل ذلك يتكلمون من العالم ، والعالم يسمع لهم '),
(1447, '1 John', 62, 4, 6, ' نحن من الله . فمن يعرف الله يسمع لنا ، ومن ليس من الله لا يسمع لنا . من هذا نعرف روح الحق وروح الضلال '),
(1448, '1 John', 62, 4, 7, ' أيها الأحباء ، لنحب بعضنا بعضا ، لأن المحبة هي من الله ، وكل من يحب فقد ولد من الله ويعرف الله '),
(1449, '1 John', 62, 4, 8, ' ومن لا يحب لم يعرف الله ، لأن الله محبة '),
(1450, '1 John', 62, 4, 9, ' بهذا أظهرت محبة الله فينا : أن الله قد أرسل ابنه الوحيد إلى العالم لكي نحيا به '),
(1451, '1 John', 62, 4, 10, ' في هذا هي المحبة : ليس أننا نحن أحببنا الله ، بل أنه هو أحبنا ، وأرسل ابنه كفارة لخطايانا '),
(1452, '1 John', 62, 4, 11, ' أيها الأحباء ، إن كان الله قد أحبنا هكذا ، ينبغي لنا أيضا أن يحب بعضنا بعضا '),
(1453, '1 John', 62, 4, 12, ' الله لم ينظره أحد قط . إن أحب بعضنا بعضا ، فالله يثبت فينا ، ومحبته قد تكملت فينا '),
(1454, '1 John', 62, 4, 13, ' بهذا نعرف أننا نثبت فيه وهو فينا : أنه قد أعطانا من روحه '),
(1455, '1 John', 62, 4, 14, ' ونحن قد نظرنا ونشهد أن الآب قد أرسل الابن مخلصا للعالم '),
(1456, '1 John', 62, 4, 15, ' من اعترف أن يسوع هو ابن الله ، فالله يثبت فيه وهو في الله '),
(1457, '1 John', 62, 4, 16, ' ونحن قد عرفنا وصدقنا المحبة التي لله فينا . الله محبة ، ومن يثبت في المحبة ، يثبت في الله والله فيه '),
(1458, '1 John', 62, 4, 17, ' بهذا تكملت المحبة فينا : أن يكون لنا ثقة في يوم الدين ، لأنه كما هو في هذا العالم ، هكذا نحن أيضا '),
(1459, '1 John', 62, 4, 18, ' لا خوف في المحبة ، بل المحبة الكاملة تطرح الخوف إلى خارج لأن الخوف له عذاب . وأما من خاف فلم يتكمل في المحبة '),
(1460, '1 John', 62, 4, 19, ' نحن نحبه لأنه هو أحبنا أولا '),
(1461, '1 John', 62, 4, 20, ' إن قال أحد : إني أحب الله وأبغض أخاه ، فهو كاذب . لأن من لا يحب أخاه الذي أبصره ، كيف يقدر أن يحب الله الذي لم يبصره '),
(1462, '1 John', 62, 4, 21, ' ولنا هذه الوصية منه : أن من يحب الله يحب أخاه أيضا '),
(1463, '1 John', 62, 5, 1, ' كل من يؤمن أن يسوع هو المسيح فقد ولد من الله . وكل من يحب الوالد يحب المولود منه أيضا '),
(1464, '1 John', 62, 5, 2, ' بهذا نعرف أننا نحب أولاد الله : إذا أحببنا الله وحفظنا وصاياه '),
(1465, '1 John', 62, 5, 3, ' فإن هذه هي محبة الله : أن نحفظ وصاياه . ووصاياه ليست ثقيلة '),
(1466, '1 John', 62, 5, 4, ' لأن كل من ولد من الله يغلب العالم . وهذه هي الغلبة التي تغلب العالم : إيماننا '),
(1467, '1 John', 62, 5, 5, ' من هو الذي يغلب العالم ، إلا الذي يؤمن أن يسوع هو ابن الله '),
(1468, '1 John', 62, 5, 6, ' هذا هو الذي أتى بماء ودم : يسوع المسيح . لا بالماء فقط ، بل بالماء والدم . والروح هو الذي يشهد ، لأن الروح هو الحق '),
(1469, '1 John', 62, 5, 7, ' فإن الذين يشهدون في السماء هم ثلاثة : الآب ، والكلمة ، والروح القدس . وهؤلاء الثلاثة هم واحد '),
(1470, '1 John', 62, 5, 8, ' والذين يشهدون في الأرض هم ثلاثة : الروح ، والماء ، والدم . والثلاثة هم في الواحد '),
(1471, '1 John', 62, 5, 9, ' إن كنا نقبل شهادة الناس ، فشهادة الله أعظم ، لأن هذه هي شهادة الله التي قد شهد بها عن ابنه '),
(1472, '1 John', 62, 5, 10, ' من يؤمن بابن الله فعنده الشهادة في نفسه . من لا يصدق الله ، فقد جعله كاذبا ، لأنه لم يؤمن بالشهادة التي قد شهد بها الله عن ابنه '),
(1473, '1 John', 62, 5, 11, ' وهذه هي الشهادة : أن الله أعطانا حياة أبدية ، وهذه الحياة هي في ابنه '),
(1474, '1 John', 62, 5, 12, ' من له الابن فله الحياة ، ومن ليس له ابن الله فليست له الحياة '),
(1475, '1 John', 62, 5, 13, ' كتبت هذا إليكم ، أنتم المؤمنين باسم ابن الله ، لكي تعلموا أن لكم حياة أبدية ، ولكي تؤمنوا باسم ابن الله '),
(1476, '1 John', 62, 5, 14, ' وهذه هي الثقة التي لنا عنده : أنه إن طلبنا شيئا حسب مشيئته يسمع لنا '),
(1477, '1 John', 62, 5, 15, ' وإن كنا نعلم أنه مهما طلبنا يسمع لنا ، نعلم أن لنا الطلبات التي طلبناها منه '),
(1478, '1 John', 62, 5, 16, ' إن رأى أحد أخاه يخطئ خطية ليست للموت ، يطلب ، فيعطيه حياة للذين يخطئون ليس للموت . توجد خطية للموت . ليس لأجل هذه أقول أن يطلب '),
(1479, '1 John', 62, 5, 17, ' كل إثم هو خطية ، وتوجد خطية ليست للموت '),
(1480, '1 John', 62, 5, 18, ' نعلم أن كل من ولد من الله لا يخطئ ، بل المولود من الله يحفظ نفسه ، والشرير لا يمسه '),
(1481, '1 John', 62, 5, 19, ' نعلم أننا نحن من الله ، والعالم كله قد وضع في الشرير '),
(1482, '1 John', 62, 5, 20, ' ونعلم أن ابن الله قد جاء وأعطانا بصيرة لنعرف الحق . ونحن في الحق في ابنه يسوع المسيح . هذا هو الإله الحق والحياة الأبدية '),
(1483, '1 John', 62, 5, 21, ' أيها الأولاد احفظوا أنفسكم من الأصنام . آمين '),
(1484, '1 Kings', 11, 4, 19, ' جابر بن أوري في أرض جلعاد ، أرض سيحون ملك الأموريين وعوج ملك باشان . ووكيل واحد الذي في الأرض '),
(1485, '1 Kings', 11, 4, 20, ' وكان يهوذا وإسرائيل كثيرين كالرمل الذي على البحر في الكثرة . يأكلون ويشربون ويفرحون '),
(1486, '1 Kings', 11, 4, 21, ' وكان سليمان متسلطا على جميع الممالك من النهر إلى أرض فلسطين ، وإلى تخوم مصر . كانوا يقدمون الهدايا ويخدمون سليمان كل أيام حياته '),
(1487, '1 Kings', 11, 4, 22, ' وكان طعام سليمان لليوم الواحد : ثلاثين كر سميذ ، وستين كر دقيق '),
(1488, '1 Kings', 11, 4, 23, ' وعشرة ثيران مسمنة ، وعشرين ثورا من المراعي ، ومئة خروف ، ما عدا الأيائل والظباء واليحامير والإوز المسمن '),
(1489, '1 Kings', 11, 4, 24, ' لأنه كان متسلطا على كل ما عبر النهر من تفسح إلى غزة ، على كل ملوك عبر النهر ، وكان له صلح من جميع جوانبه حواليه '),
(1490, '1 Kings', 11, 4, 25, ' وسكن يهوذا وإسرائيل آمنين ، كل واحد تحت كرمته وتحت تينته ، من دان إلى بئر سبع ، كل أيام سليمان '),
(1491, '1 Kings', 11, 4, 26, ' وكان لسليمان أربعون ألف مذود لخيل مركباته ، واثنا عشر ألف فارس '),
(1492, '1 Kings', 11, 4, 27, ' وهؤلاء الوكلاء كانوا يمتارون للملك سليمان ولكل من تقدم إلى مائدة الملك سليمان ، كل واحد في شهره . لم يكونوا يحتاجون إلى شيء '),
(1493, '1 Kings', 11, 4, 28, ' وكانوا يأتون بشعير وتبن للخيل والجياد إلى الموضع الذي يكون فيه ، كل واحد حسب قضائه '),
(1494, '1 Kings', 11, 4, 29, ' وأعطى الله سليمان حكمة وفهما كثيرا جدا ، ورحبة قلب كالرمل الذي على شاطئ البحر '),
(1495, '1 Kings', 11, 4, 30, ' وفاقت حكمة سليمان حكمة جميع بني المشرق وكل حكمة مصر '),
(1496, '1 Kings', 11, 4, 31, ' وكان أحكم من جميع الناس ، من إيثان الأزراحي وهيمان وكلكول ودردع بني ماحول . وكان صيته في جميع الأمم حواليه '),
(1497, '1 Kings', 11, 4, 32, ' وتكلم بثلاثة آلاف مثل ، وكانت نشائده ألفا وخمسا '),
(1498, '1 Kings', 11, 4, 33, ' وتكلم عن الأشجار ، من الأرز الذي في لبنان إلى الزوفا النابت في الحائط . وتكلم عن البهائم وعن الطير وعن الدبيب وعن السمك '),
(1499, '1 Kings', 11, 4, 34, ' وكانوا يأتون من جميع الشعوب ليسمعوا حكمة سليمان ، من جميع ملوك الأرض الذين سمعوا بحكمته '),
(1500, '1 Kings', 11, 5, 1, ' وأرسل حيرام ملك صور عبيده إلى سليمان ، لأنه سمع أنهم مسحوه ملكا مكان أبيه ، لأن حيرام كان محبا لداود كل الأيام '),
(1501, '1 Kings', 11, 5, 2, ' فأرسل سليمان إلى حيرام يقول '),
(1502, '1 Kings', 11, 5, 3, ' أنت تعلم داود أبي أنه لم يستطع أن يبني بيتا لاسم الرب إلهه ، بسبب الحروب التي أحاطت به ، حتى جعلهم الرب تحت بطن قدميه '),
(1503, '1 Kings', 11, 5, 4, ' والآن فقد أراحني الرب إلهي من كل الجهات فلا يوجد خصم ولا حادثة شر '),
(1504, '1 Kings', 11, 5, 5, ' وهأنذا قائل على بناء بيت لاسم الرب إلهي كما كلم الرب داود أبي قائلا : إن ابنك الذي أجعله مكانك على كرسيك هو يبني البيت لاسمي '),
(1505, '1 Kings', 11, 5, 6, ' والآن فأمر أن يقطعوا لي أرزا من لبنان ، ويكون عبيدي مع عبيدك ، وأجرة عبيدك أعطيك إياها حسب كل ما تقول ، لأنك تعلم أنه ليس بيننا أحد يعرف قطع الخشب مثل الصيدونيين '),
(1506, '1 Kings', 11, 5, 7, ' فلما سمع حيرام كلام سليمان ، فرح جدا وقال : مبارك اليوم الرب الذي أعطى داود ابنا حكيما على هذا الشعب الكثير '),
(1507, '1 Kings', 11, 5, 8, ' وأرسل حيرام إلى سليمان قائلا : قد سمعت ما أرسلت به إلي . أنا أفعل كل مسرتك في خشب الأرز وخشب السرو '),
(1508, '1 Kings', 11, 5, 9, ' عبيدي ينزلون ذلك من لبنان إلى البحر ، وأنا أجعله أرماثا في البحر إلى الموضع الذي تعرفني عنه وأنفضه هناك ، وأنت تحمله ، وأنت تعمل مرضاتي بإعطائك طعاما لبيتي '),
(1509, '1 Kings', 11, 5, 10, ' فكان حيرام يعطي سليمان خشب أرز وخشب سرو حسب كل مسرته '),
(1510, '1 Kings', 11, 5, 11, ' وأعطى سليمان حيرام عشرين ألف كر حنطة طعاما لبيته ، وعشرين كر زيت رض . هكذا كان سليمان يعطي حيرام سنة فسنة '),
(1511, '1 Kings', 11, 5, 12, ' والرب أعطى سليمان حكمة كما كلمه . وكان صلح بين حيرام وسليمان ، وقطعا كلاهما عهدا '),
(1512, '1 Kings', 11, 5, 13, ' وسخر الملك سليمان من جميع إسرائيل ، وكانت السخر ثلاثين ألف رجل '),
(1513, '1 Kings', 11, 5, 14, ' فأرسلهم إلى لبنان عشرة آلاف في الشهر بالنوبة . يكونون شهرا في لبنان وشهرين في بيوتهم . وكان أدونيرام على التسخير '),
(1514, '1 Kings', 11, 5, 15, ' وكان لسليمان سبعون ألفا يحملون أحمالا ، وثمانون ألفا يقطعون في الجبل '),
(1515, '1 Kings', 11, 5, 16, ' ما عدا رؤساء الوكلاء لسليمان الذين على العمل ثلاثة آلاف وثلاث مئة ، المتسلطين على الشعب العاملين العمل '),
(1516, '1 Kings', 11, 5, 17, ' وأمر الملك أن يقلعوا حجارة كبيرة ، حجارة كريمة لتأسيس البيت ، حجارة مربعة '),
(1517, '1 Kings', 11, 5, 18, ' فنحتها بناؤو سليمان ، وبناؤو حيرام والجبليون ، وهيأوا الأخشاب والحجارة لبناء البيت '),
(1518, '1 Kings', 11, 6, 1, ' وكان في سنة الأربع مئة والثمانين لخروج بني إسرائيل من أرض مصر ، في السنة الرابعة لملك سليمان على إسرائيل ، في شهر زيو وهو الشهر الثاني ، أنه بنى البيت للرب '),
(1519, '1 Kings', 11, 6, 2, ' والبيت الذي بناه الملك سليمان للرب طوله ستون ذراعا ، وعرضه عشرون ذراعا ، وسمكه ثلاثون ذراعا '),
(1520, '1 Kings', 11, 6, 3, ' والرواق قدام هيكل البيت طوله عشرون ذراعا حسب عرض البيت ، وعرضه عشر أذرع قدام البيت '),
(1521, '1 Kings', 11, 6, 4, ' وعمل للبيت كوى مسقوفة مشبكة '),
(1522, '1 Kings', 11, 6, 5, ' وبنى مع حائط البيت طباقا حواليه مع حيطان البيت حول الهيكل والمحراب ، وعمل غرفات في مستديرها '),
(1523, '1 Kings', 11, 6, 6, ' فالطبقة السفلى عرضها خمس أذرع ، والوسطى عرضها ست أذرع ، والثالثة عرضها سبع أذرع ، لأنه جعل للبيت حواليه من خارج أخصاما لئلا تتمكن الجوائز في حيطان البيت '),
(1524, '1 Kings', 11, 6, 7, ' والبيت في بنائه بني بحجارة صحيحة مقتلعة ، ولم يسمع في البيت عند بنائه منحت ولا معول ولا أداة من حديد '),
(1525, '1 Kings', 11, 6, 8, ' وكان باب الغرفة الوسطى في جانب البيت الأيمن ، وكانوا يصعدون بدرج معطف إلى الوسطى ، ومن الوسطى إلى الثالثة '),
(1526, '1 Kings', 11, 6, 9, ' فبنى البيت وأكمله ، وسقف البيت بألواح وجوائز من الأرز '),
(1527, '1 Kings', 11, 6, 10, ' وبنى الغرفات على البيت كله سمكها خمس أذرع ، وتمكنت في البيت بخشب أرز '),
(1528, '1 Kings', 11, 6, 11, ' وكان كلام الرب إلى سليمان قائلا '),
(1529, '1 Kings', 11, 6, 12, ' هذا البيت الذي أنت بانيه ، إن سلكت في فرائضي وعملت أحكامي وحفظت كل وصاياي للسلوك بها ، فإني أقيم معك كلامي الذي تكلمت به إلى داود أبيك '),
(1530, '1 Kings', 11, 6, 13, ' وأسكن في وسط بني إسرائيل ، ولا أترك شعبي إسرائيل '),
(1531, '1 Kings', 11, 6, 14, ' فبنى سليمان البيت وأكمله '),
(1532, '1 Kings', 11, 6, 15, ' وبنى حيطان البيت من داخل بأضلاع أرز من أرض البيت إلى حيطان السقف ، وغشاه من داخل بخشب ، وفرش أرض البيت بأخشاب سرو '),
(1533, '1 Kings', 11, 6, 16, ' وبنى عشرين ذراعا من مؤخر البيت بأضلاع أرز من الأرض إلى الحيطان . وبنى داخله لأجل المحراب ، أي قدس الأقداس '),
(1534, '1 Kings', 11, 6, 17, ' وأربعون ذراعا كانت البيت ، أي الهيكل الذي أمامه '),
(1535, '1 Kings', 11, 6, 18, ' وأرز البيت من داخل كان منقورا على شكل قثاء وبراعم زهور . الجميع أرز . لم يكن يرى حجر '),
(1536, '1 Kings', 11, 6, 19, ' وهيأ محرابا في وسط البيت من داخل ليضع هناك تابوت عهد الرب '),
(1537, '1 Kings', 11, 6, 20, ' ولأجل المحراب عشرون ذراعا طولا وعشرون ذراعا عرضا وعشرون ذراعا سمكا . وغشاه بذهب خالص ، وغشى المذبح بأرز '),
(1538, '1 Kings', 11, 6, 21, ' وغشى سليمان البيت من داخل بذهب خالص . وسد بسلاسل ذهب قدام المحراب . وغشاه بذهب '),
(1539, '1 Kings', 11, 6, 22, ' وجميع البيت غشاه بذهب إلى تمام كل البيت ، وكل المذبح الذي للمحراب غشاه بذهب '),
(1540, '1 Kings', 11, 6, 23, ' وعمل في المحراب كروبين من خشب الزيتون ، علو الواحد عشر أذرع '),
(1541, '1 Kings', 11, 6, 24, ' وخمس أذرع جناح الكروب الواحد ، وخمس أذرع جناح الكروب الآخر . عشر أذرع من طرف جناحه إلى طرف جناحه '),
(1542, '1 Kings', 11, 6, 25, ' وعشر أذرع الكروب الآخر . قياس واحد ، وشكل واحد للكروبين '),
(1543, '1 Kings', 11, 6, 26, ' علو الكروب الواحد عشر أذرع وكذا الكروب الآخر '),
(1544, '1 Kings', 11, 6, 27, ' وجعل الكروبين في وسط البيت الداخلي ، وبسطوا أجنحة الكروبين فمس جناح الواحد الحائط وجناح الكروب الآخر مس الحائط الآخر . وكانت أجنحتهما في وسط البيت يمس أحدهما الآخر '),
(1545, '1 Kings', 11, 6, 28, ' وغشى الكروبين بذهب '),
(1546, '1 Kings', 11, 6, 29, ' وجميع حيطان البيت في مستديرها رسمها نقشا بنقر كروبيم ونخيل وبراعم زهور من داخل ومن خارج '),
(1547, '1 Kings', 11, 6, 30, ' وغشى أرض البيت بذهب من داخل ومن خارج '),
(1548, '1 Kings', 11, 6, 31, ' وعمل لباب المحراب مصراعين من خشب الزيتون . الساكف والقائمتان مخمسة '),
(1549, '1 Kings', 11, 6, 32, ' والمصراعان من خشب الزيتون . ورسم عليهما نقش كروبيم ونخيل وبراعم زهور ، وغشاهما بذهب ، ورصع الكروبيم والنخيل بذهب '),
(1550, '1 Kings', 11, 6, 33, ' وكذلك عمل لمدخل الهيكل قوائم من خشب الزيتون مربعة '),
(1551, '1 Kings', 11, 6, 34, ' ومصراعين من خشب السرو . المصراع الواحد دفتان تنطويان ، والمصراع الآخر دفتان تنطويان '),
(1552, '1 Kings', 11, 6, 35, ' ونحت كروبيم ونخيلا وبراعم زهور ، وغشاها بذهب مطرق على المنقوش '),
(1553, '1 Kings', 11, 6, 36, ' وبنى الدار الداخلية ثلاثة صفوف منحوتة ، وصفا من جوائز الأرز '),
(1554, '1 Kings', 11, 6, 37, ' في السنة الرابعة أسس بيت الرب في شهر زيو '),
(1555, '1 Kings', 11, 1, 1, ' وشاخ الملك داود . تقدم في الأيام . وكانوا يدثرونه بالثياب فلم يدفأ '),
(1556, '1 Kings', 11, 1, 2, ' فقال له عبيده : ليفتشوا لسيدنا الملك على فتاة عذراء ، فلتقف أمام الملك ولتكن له حاضنة ولتضطجع في حضنك فيدفأ سيدنا الملك '),
(1557, '1 Kings', 11, 1, 3, ' ففتشوا على فتاة جميلة في جميع تخوم إسرائيل ، فوجدوا أبيشج الشونمية ، فجاءوا بها إلى الملك '),
(1558, '1 Kings', 11, 1, 4, ' وكانت الفتاة جميلة جدا ، فكانت حاضنة الملك . وكانت تخدمه ، ولكن الملك لم يعرفها '),
(1559, '1 Kings', 11, 1, 5, ' ثم إن أدونيا ابن حجيث ترفع قائلا : أنا أملك . وعد لنفسه عجلات وفرسانا وخمسين رجلا يجرون أمامه '),
(1560, '1 Kings', 11, 1, 6, ' ولم يغضبه أبوه قط قائلا : لماذا فعلت هكذا ؟  . وهو أيضا جميل الصورة جدا ، وقد ولدته أمه بعد أبشالوم '),
(1561, '1 Kings', 11, 1, 7, ' وكان كلامه مع يوآب ابن صروية ، ومع أبياثار الكاهن ، فأعانا أدونيا '),
(1562, '1 Kings', 11, 1, 8, ' وأما صادوق الكاهن وبناياهو بن يهوياداع وناثان النبي وشمعي وريعي والجبابرة الذين لداود فلم يكونوا مع أدونيا '),
(1563, '1 Kings', 11, 1, 9, ' فذبح أدونيا غنما وبقرا ومعلوفات عند حجر الزاحفة الذي بجانب عين روجل ، ودعا جميع إخوته بني الملك وجميع رجال يهوذا عبيد الملك '),
(1564, '1 Kings', 11, 1, 10, ' وأما ناثان النبي وبناياهو والجبابرة وسليمان أخوه فلم يدعهم '),
(1565, '1 Kings', 11, 1, 11, ' فكلم ناثان بثشبع أم سليمان قائلا : أما سمعت أن أدونيا ابن حجيث قد ملك ، وسيدنا داود لا يعلم '),
(1566, '1 Kings', 11, 1, 12, ' فالآن تعالي أشير عليك مشورة فتنجي نفسك ونفس ابنك سليمان '),
(1567, '1 Kings', 11, 1, 13, ' اذهبي وادخلي إلى الملك داود وقولي له : أما حلفت أنت يا سيدي الملك لأمتك قائلا : إن سليمان ابنك يملك بعدي ، وهو يجلس على كرسيي ؟ فلماذا ملك أدونيا '),
(1568, '1 Kings', 11, 1, 14, ' وفيما أنت متكلمة هناك مع الملك ، أدخل أنا وراءك وأكمل كلامك '),
(1569, '1 Kings', 11, 1, 15, ' فدخلت بثشبع إلى الملك إلى المخدع . وكان الملك قد شاخ جدا وكانت أبيشج الشونمية تخدم الملك '),
(1570, '1 Kings', 11, 1, 16, ' فخرت بثشبع وسجدت للملك ، فقال الملك : ما لك '),
(1571, '1 Kings', 11, 1, 17, ' فقالت له أنت يا سيدي حلفت بالرب إلهك لأمتك قائلا : إن سليمان ابنك يملك بعدي وهو يجلس على كرسيي '),
(1572, '1 Kings', 11, 1, 18, ' والآن هوذا أدونيا قد ملك . والآن أنت ياسيدي الملك لا تعلم ذلك '),
(1573, '1 Kings', 11, 1, 19, ' وقد ذبح ثيرانا ومعلوفات وغنما بكثرة ، ودعا جميع بني الملك ، وأبياثار الكاهن ويوآب رئيس الجيش ، ولم يدع سليمان عبدك '),
(1574, '1 Kings', 11, 1, 20, ' وأنت يا سيدي الملك أعين جميع إسرائيل نحوك لكي تخبرهم من يجلس على كرسي سيدي الملك بعده '),
(1575, '1 Kings', 11, 1, 21, ' فيكون إذا اضطجع سيدي الملك مع آبائه أني أنا وابني سليمان نحسب مذنبين '),
(1576, '1 Kings', 11, 1, 22, ' وبينما هي متكلمة مع الملك ، إذا ناثان النبي داخل '),
(1577, '1 Kings', 11, 1, 23, ' فأخبروا الملك قائلين : هوذا ناثان النبي . فدخل إلى أمام الملك وسجد للملك على وجهه إلى الأرض '),
(1578, '1 Kings', 11, 1, 24, ' وقال ناثان : يا سيدي الملك ، أأنت قلت : إن أدونيا يملك بعدي وهو يجلس على كرسيي '),
(1579, '1 Kings', 11, 1, 25, ' لأنه نزل اليوم وذبح ثيرانا ومعلوفات وغنما بكثرة ، ودعا جميع بني الملك ورؤساء الجيش وأبياثار الكاهن ، وها هم يأكلون ويشربون أمامه ويقولون : ليحي الملك أدونيا '),
(1580, '1 Kings', 11, 1, 26, ' وأما أنا عبدك وصادوق الكاهن وبناياهو بن يهوياداع وسليمان عبدك فلم يدعنا '),
(1581, '1 Kings', 11, 1, 27, ' هل من قبل سيدي الملك كان هذا الأمر ، ولم تعلم عبدك من يجلس على كرسي سيدي الملك بعده '),
(1582, '1 Kings', 11, 1, 28, ' فأجاب الملك داود وقال : ادع لي بثشبع . فدخلت إلى أمام الملك ووقفت بين يدي الملك '),
(1583, '1 Kings', 11, 1, 29, ' فحلف الملك وقال : حي هو الرب الذي فدى نفسي من كل ضيقة '),
(1584, '1 Kings', 11, 1, 30, ' إنه كما حلفت لك بالرب إله إسرائيل قائلا : إن سليمان ابنك يملك بعدي ، وهو يجلس على كرسيي عوضا عني ، كذلك أفعل هذا اليوم '),
(1585, '1 Kings', 11, 1, 31, ' فخرت بثشبع على وجهها إلى الأرض وسجدت للملك وقالت : ليحي سيدي الملك داود إلى الأبد '),
(1586, '1 Kings', 11, 1, 32, ' وقال الملك داود : ادع لي صادوق الكاهن وناثان النبي وبناياهو بن يهوياداع . فدخلوا إلى أمام الملك '),
(1587, '1 Kings', 11, 1, 33, ' فقال الملك لهم : خذوا معكم عبيد سيدكم ، وأركبوا سليمان ابني على البغلة التي لي ، وانزلوا به إلى جيحون '),
(1588, '1 Kings', 11, 1, 34, ' وليمسحه هناك صادوق الكاهن وناثان النبي ملكا على إسرائيل ، واضربوا بالبوق وقولوا : ليحي الملك سليمان '),
(1589, '1 Kings', 11, 1, 35, ' وتصعدون وراءه ، فيأتي ويجلس على كرسيي وهو يملك عوضا عني ، وإياه قد أوصيت أن يكون رئيسا على إسرائيل ويهوذا '),
(1590, '1 Kings', 11, 1, 36, ' فأجاب بناياهو بن يهوياداع الملك وقال : آمين . هكذا يقول الرب إله سيدي الملك '),
(1591, '1 Kings', 11, 1, 37, ' كما كان الرب مع سيدي الملك كذلك ليكن مع سليمان ، ويجعل كرسيه أعظم من كرسي سيدي الملك داود '),
(1592, '1 Kings', 11, 1, 38, ' فنزل صادوق الكاهن وناثان النبي وبناياهو بن يهوياداع والجلادون والسعاة ، وأركبوا سليمان على بغلة الملك داود ، وذهبوا به إلى جيحون '),
(1593, '1 Kings', 11, 1, 39, ' فأخذ صادوق الكاهن قرن الدهن من الخيمة ومسح سليمان . وضربوا بالبوق ، وقال جميع الشعب : ليحي الملك سليمان '),
(1594, '1 Kings', 11, 1, 40, ' وصعد جميع الشعب وراءه . وكان الشعب يضربون بالناي ويفرحون فرحا عظيما حتى انشقت الأرض من أصواتهم '),
(1595, '1 Kings', 11, 1, 41, ' فسمع أدونيا وجميع المدعوين الذين عنده بعدما انتهوا من الأكل . وسمع يوآب صوت البوق فقال : لماذا صوت القرية مضطرب '),
(1596, '1 Kings', 11, 1, 42, ' وفيما هو يتكلم إذا بيوناثان بن أبياثار الكاهن قد جاء ، فقال أدونيا : تعال ، لأنك ذو بأس وتبشر بالخير '),
(1597, '1 Kings', 11, 1, 43, ' فأجاب يوناثان وقال لأدونيا : بل سيدنا الملك داود قد ملك سليمان '),
(1598, '1 Kings', 11, 1, 44, ' وأرسل الملك معه صادوق الكاهن وناثان النبي وبناياهو بن يهوياداع والجلادين والسعاة ، وقد أركبوه على بغلة الملك '),
(1599, '1 Kings', 11, 1, 45, ' ومسحه صادوق الكاهن وناثان النبي ملكا في جيحون ، وصعدوا من هناك فرحين حتى اضطربت القرية . هذا هو الصوت الذي سمعتموه '),
(1600, '1 Kings', 11, 1, 46, ' وأيضا قد جلس سليمان على كرسي المملكة '),
(1601, '1 Kings', 11, 1, 47, ' وأيضا جاء عبيد الملك ليباركوا سيدنا الملك داود قائلين : يجعل إلهك اسم سليمان أحسن من اسمك ، وكرسيه أعظم من كرسيك . فسجد الملك على سريره '),
(1602, '1 Kings', 11, 1, 48, ' وأيضا هكذا قال الملك : مبارك الرب إله إسرائيل الذي أعطاني اليوم من يجلس على كرسيي وعيناي تبصران '),
(1603, '1 Kings', 11, 1, 49, ' فارتعد وقام جميع مدعوي أدونيا ، وذهبوا كل واحد في طريقه '),
(1604, '1 Kings', 11, 1, 50, ' وخاف أدونيا من قبل سليمان ، وقام وانطلق وتمسك بقرون المذبح '),
(1605, '1 Kings', 11, 1, 51, ' فأخبر سليمان وقيل له : هوذا أدونيا خائف من الملك سليمان ، وهوذا قد تمسك بقرون المذبح قائلا : ليحلف لي اليوم الملك سليمان إنه لا يقتل عبده بالسيف '),
(1606, '1 Kings', 11, 1, 52, ' فقال سليمان : إن كان ذا فضيلة لا يسقط من شعره إلى الأرض ، ولكن إن وجد به شر فإنه يموت '),
(1607, '1 Kings', 11, 1, 53, ' فأرسل الملك سليمان فأنزلوه عن المذبح ، فأتى وسجد للملك سليمان . فقال له سليمان : اذهب إلى بيتك '),
(1608, '1 Kings', 11, 2, 1, ' ولما قربت أيام وفاة داود أوصى سليمان ابنه قائلا '),
(1609, '1 Kings', 11, 2, 2, ' أنا ذاهب في طريق الأرض كلها ، فتشدد وكن رجلا '),
(1610, '1 Kings', 11, 2, 3, ' احفظ شعائر الرب إلهك ، إذ تسير في طرقه ، وتحفظ فرائضه ، وصاياه وأحكامه وشهاداته ، كما هو مكتوب في شريعة موسى ، لكي تفلح في كل ما تفعل وحيثما توجهت '),
(1611, '1 Kings', 11, 2, 4, ' لكي يقيم الرب كلامه الذي تكلم به عني قائلا : إذا حفظ بنوك طريقهم وسلكوا أمامي بالأمانة من كل قلوبهم وكل أنفسهم ، قال لا يعدم لك رجل عن كرسي إسرائيل '),
(1612, '1 Kings', 11, 2, 5, ' وأنت أيضا تعلم ما فعل بي يوآب ابن صروية ، ما فعل لرئيسي جيوش إسرائيل : ابنير بن نير وعماسا بن يثر ، إذ قتلهما وسفك دم الحرب في الصلح ، وجعل دم الحرب في منطقته التي على حقويه وفي نعليه اللتين برجليه '),
(1613, '1 Kings', 11, 2, 6, ' فافعل حسب حكمتك ولا تدع شيبته تنحدر بسلام إلى الهاوية '),
(1614, '1 Kings', 11, 2, 7, ' وافعل معروفا لبني برزلاي الجلعادي فيكونوا بين الآكلين على مائدتك ، لأنهم هكذا تقدموا إلي عند هربي من وجه أبشالوم أخيك '),
(1615, '1 Kings', 11, 2, 8, ' وهوذا معك شمعي بن جيرا البنياميني من بحوريم ، وهو لعنني لعنة شديدة يوم انطلقت إلى محنايم ، وقد نزل للقائي إلى الأردن ، فحلفت له بالرب قائلا : إني لا أميتك بالسيف '),
(1616, '1 Kings', 11, 2, 9, ' والآن فلا تبرره لأنك أنت رجل حكيم ، فاعلم ما تفعل به وأحدر شيبته بالدم إلى الهاوية '),
(1617, '1 Kings', 11, 2, 10, ' واضطجع داود مع آبائه ، ودفن في مدينة داود '),
(1618, '1 Kings', 11, 2, 11, ' وكان الزمان الذي ملك فيه داود على إسرائيل أربعين سنة . في حبرون ملك سبع سنين ، وفي أورشليم ملك ثلاثا وثلاثين سنة '),
(1619, '1 Kings', 11, 2, 12, ' وجلس سليمان على كرسي داود أبيه ، وتثبت ملكه جدا '),
(1620, '1 Kings', 11, 2, 13, ' ثم جاء أدونيا ابن حجيث إلى بثشبع أم سليمان . فقالت : أللسلام جئت ؟ . فقال : للسلام '),
(1621, '1 Kings', 11, 2, 14, ' ثم قال : لي معك كلمة . فقالت : تكلم '),
(1622, '1 Kings', 11, 2, 15, ' فقال : أنت تعلمين أن الملك كان لي ، وقد جعل جميع إسرائيل وجوههم نحوي لأملك ، فدار الملك وصار لأخي لأنه من قبل الرب صار له '),
(1623, '1 Kings', 11, 2, 16, ' والآن أسألك سؤالا واحدا فلا ترديني فيه . فقالت له : تكلم '),
(1624, '1 Kings', 11, 2, 17, ' فقال : قولي لسليمان الملك ، لأنه لا يردك ، أن يعطيني أبيشج الشونمية امرأة '),
(1625, '1 Kings', 11, 2, 18, ' فقالت بثشبع : حسنا . أنا أتكلم عنك إلى الملك '),
(1626, '1 Kings', 11, 2, 19, ' فدخلت بثشبع إلى الملك سليمان لتكلمه عن أدونيا . فقام الملك للقائها وسجد لها وجلس على كرسيه ، ووضع كرسيا لأم الملك فجلست عن يمينه '),
(1627, '1 Kings', 11, 2, 20, ' وقالت : إنما أسألك سؤالا واحدا صغيرا . لا تردني . فقال لها الملك : اسألي يا أمي ، لأني لا أردك '),
(1628, '1 Kings', 11, 2, 21, ' فقالت : لتعط أبيشج الشونمية لأدونيا أخيك امرأة '),
(1629, '1 Kings', 11, 2, 22, ' فأجاب الملك سليمان وقال لأمه : ولماذا أنت تسألين أبيشج الشونمية لأدونيا ؟ فاسألي له الملك لأنه أخي الأكبر مني له ولأبياثار الكاهن وليوآب ابن صروية '),
(1630, '1 Kings', 11, 2, 23, ' وحلف سليمان الملك بالرب قائلا : هكذا يفعل لي الله وهكذا يزيد ، إنه قد تكلم أدونيا بهذا الكلام ضد نفسه '),
(1631, '1 Kings', 11, 2, 24, ' والآن حي هو الرب الذي ثبتني وأجلسني على كرسي داود أبي ، والذي صنع لي بيتا كما تكلم ، إنه اليوم يقتل أدونيا '),
(1632, '1 Kings', 11, 2, 25, ' فأرسل الملك سليمان بيد بناياهو بن يهوياداع ، فبطش به فمات '),
(1633, '1 Kings', 11, 2, 26, ' وقال الملك لأبياثار الكاهن : اذهب إلى عناثوث إلى حقولك ، لأنك مستوجب الموت ، ولست أقتلك في هذا اليوم ، لأنك حملت تابوت سيدي الرب أمام داود أبي ، ولأنك تذللت بكل ما تذلل به أبي '),
(1634, '1 Kings', 11, 2, 27, ' وطرد سليمان أبياثار عن أن يكون كاهنا للرب ، لإتمام كلام الرب الذي تكلم به على بيت عالي في شيلوه '),
(1635, '1 Kings', 11, 2, 28, ' فأتى الخبر إلى يوآب ، لأن يوآب مال وراء أدونيا ولم يمل وراء أبشالوم ، فهرب يوآب إلى خيمة الرب وتمسك بقرون المذبح '),
(1636, '1 Kings', 11, 2, 29, ' فأخبر الملك سليمان بأن يوآب قد هرب إلى خيمة الرب وها هو بجانب المذبح . فأرسل سليمان بناياهو بن يهوياداع قائلا : اذهب ابطش به '),
(1637, '1 Kings', 11, 2, 30, ' فدخل بناياهو إلى خيمة الرب وقال له : هكذا يقول الملك : اخرج . فقال : كلا ، ولكنني هنا أموت . فرد بناياهو الجواب على الملك قائلا : هكذا تكلم يوآب وهكذا جاوبني '),
(1638, '1 Kings', 11, 2, 31, ' فقال له الملك : افعل كما تكلم ، وابطش به وادفنه ، وأزل عني وعن بيت أبي الدم الزكي الذي سفكه يوآب '),
(1639, '1 Kings', 11, 2, 32, ' فيرد الرب دمه على رأسه ، لأنه بطش برجلين بريئين وخير منه وقتلهما بالسيف ، وأبي داود لا يعلم ، وهما أبنير بن نير رئيس جيش إسرائيل ، وعماسا بن يثر رئيس جيش يهوذا '),
(1640, '1 Kings', 11, 2, 33, ' فيرتد دمهما على رأس يوآب ورأس نسله إلى الأبد ، ويكون لداود ونسله وبيته وكرسيه سلام إلى الأبد من عند الرب '),
(1641, '1 Kings', 11, 2, 34, ' فصعد بناياهو بن يهوياداع وبطش به وقتله ، فدفن في بيته في البرية '),
(1642, '1 Kings', 11, 2, 35, ' وجعل الملك بناياهو بن يهوياداع مكانه على الجيش ، وجعل الملك صادوق الكاهن مكان أبياثار '),
(1643, '1 Kings', 11, 2, 36, ' ثم أرسل الملك ودعا شمعي وقال له : ابن لنفسك بيتا في أورشليم ، وأقم هناك ولا تخرج من هناك إلى هنا أو هنالك '),
(1644, '1 Kings', 11, 2, 37, ' فيوم تخرج وتعبر وادي قدرون ، اعلمن بأنك موتا تموت ، ويكون دمك على رأسك '),
(1645, '1 Kings', 11, 2, 38, ' فقال شمعي للملك : حسن الأمر . كما تكلم سيدي الملك كذلك يصنع عبدك . فأقام شمعي في أورشليم أياما كثيرة '),
(1646, '1 Kings', 11, 2, 39, ' وفي نهاية ثلاث سنين هرب عبدان لشمعي إلى أخيش بن معكة ملك جت ، فأخبروا شمعي قائلين : هوذا عبداك في جت '),
(1647, '1 Kings', 11, 2, 40, ' فقام شمعي وشد على حماره وذهب إلى جت إلى أخيش ليفتش على عبديه ، فانطلق شمعي وأتى بعبديه من جت '),
(1648, '1 Kings', 11, 2, 41, ' فأخبر سليمان بأن شمعي قد انطلق من أورشليم إلى جت ورجع '),
(1649, '1 Kings', 11, 2, 42, ' فأرسل الملك ودعا شمعي وقال له : أما استحلفتك بالرب وأشهدت عليك قائلا : إنك يوم تخرج وتذهب إلى هنا وهنالك ، اعلمن بأنك موتا تموت ؟ فقلت لي : حسن الأمر . قد سمعت '),
(1650, '1 Kings', 11, 2, 43, ' فلماذا لم تحفظ يمين الرب والوصية التي أوصيتك بها '),
(1651, '1 Kings', 11, 2, 44, ' ثم قال الملك لشمعي : أنت عرفت كل الشر الذي علمه قلبك الذي فعلته لداود أبي ، فليرد الرب شرك على رأسك '),
(1652, '1 Kings', 11, 2, 45, ' والملك سليمان يبارك ، وكرسي داود يكون ثابتا أمام الرب إلى الأبد '),
(1653, '1 Kings', 11, 2, 46, ' وأمر الملك بناياهو بن يهوياداع ، فخرج وبطش به فمات . وتثبت الملك بيد سليمان '),
(1654, '1 Kings', 11, 3, 1, ' وصاهر سليمان فرعون ملك مصر ، وأخذ بنت فرعون وأتى بها إلى مدينة داود إلى أن أكمل بناء بيته وبيت الرب وسور أورشليم حواليها '),
(1655, '1 Kings', 11, 3, 2, ' إلا أن الشعب كانوا يذبحون في المرتفعات ، لأنه لم يبن بيت لاسم الرب إلى تلك الأيام '),
(1656, '1 Kings', 11, 3, 3, ' وأحب سليمان الرب سائرا في فرائض داود أبيه ، إلا أنه كان يذبح ويوقد في المرتفعات '),
(1657, '1 Kings', 11, 3, 4, ' وذهب الملك إلى جبعون ليذبح هناك ، لأنها هي المرتفعة العظمى ، وأصعد سليمان ألف محرقة على ذلك المذبح '),
(1658, '1 Kings', 11, 3, 5, ' في جبعون تراءى الرب لسليمان في حلم ليلا ، وقال الله : اسأل ماذا أعطيك '),
(1659, '1 Kings', 11, 3, 6, ' فقال سليمان : إنك قد فعلت مع عبدك داود أبي رحمة عظيمة حسبما سار أمامك بأمانة وبر واستقامة قلب معك ، فحفظت له هذه الرحمة العظيمة وأعطيته ابنا يجلس على كرسيه كهذا اليوم '),
(1660, '1 Kings', 11, 3, 7, ' والآن أيها الرب إلهي ، أنت ملكت عبدك مكان داود أبي ، وأنا فتى صغير لا أعلم الخروج والدخول '),
(1661, '1 Kings', 11, 3, 8, ' وعبدك في وسط شعبك الذي اخترته ، شعب كثير لا يحصى ولا يعد من الكثرة '),
(1662, '1 Kings', 11, 3, 9, ' فأعط عبدك قلبا فهيما لأحكم على شعبك وأميز بين الخير والشر ، لأنه من يقدر أن يحكم على شعبك العظيم هذا '),
(1663, '1 Kings', 11, 3, 10, ' فحسن الكلام في عيني الرب ، لأن سليمان سأل هذا الأمر '),
(1664, '1 Kings', 11, 3, 11, ' فقال له الله : من أجل أنك قد سألت هذا الأمر ، ولم تسأل لنفسك أياما كثيرة ولا سألت لنفسك غنى ، ولا سألت أنفس أعدائك ، بل سألت لنفسك تمييزا لتفهم الحكم '),
(1665, '1 Kings', 11, 3, 12, ' هوذا قد فعلت حسب كلامك . هوذا أعطيتك قلبا حكيما ومميزا حتى إنه لم يكن مثلك قبلك ولا يقوم بعدك نظيرك '),
(1666, '1 Kings', 11, 3, 13, ' وقد أعطيتك أيضا ما لم تسأله ، غنى وكرامة حتى إنه لا يكون رجل مثلك في الملوك كل أيامك '),
(1667, '1 Kings', 11, 3, 14, ' فإن سلكت في طريقي وحفظت فرائضي ووصاياي ، كما سلك داود أبوك ، فإني أطيل أيامك '),
(1668, '1 Kings', 11, 3, 15, ' فاستيقظ سليمان وإذا هو حلم . وجاء إلى أورشليم ووقف أمام تابوت عهد الرب وأصعد محرقات وقرب ذبائح سلامة ، وعمل وليمة لكل عبيده '),
(1669, '1 Kings', 11, 3, 16, ' حينئذ أتت امرأتان زانيتان إلى الملك ووقفتا بين يديه '),
(1670, '1 Kings', 11, 3, 17, ' فقالت المرأة الواحدة : استمع يا سيدي . إني أنا وهذه المرأة ساكنتان في بيت واحد ، وقد ولدت معها في البيت '),
(1671, '1 Kings', 11, 3, 18, ' وفي اليوم الثالث بعد ولادتي ولدت هذه المرأة أيضا ، وكنا معا ، ولم يكن معنا غريب في البيت غيرنا نحن كلتينا في البيت '),
(1672, '1 Kings', 11, 3, 19, ' فمات ابن هذه في الليل ، لأنها اضطجعت عليه '),
(1673, '1 Kings', 11, 3, 20, ' فقامت في وسط الليل وأخذت ابني من جانبي وأمتك نائمة ، وأضجعته في حضنها ، وأضجعت ابنها الميت في حضني '),
(1674, '1 Kings', 11, 3, 21, ' فلما قمت صباحا لأرضع ابني ، إذا هو ميت . ولما تأملت فيه في الصباح ، إذا هو ليس ابني الذي ولدته '),
(1675, '1 Kings', 11, 3, 22, ' وكانت المرأة الأخرى تقول : كلا ، بل ابني الحي وابنك الميت . وهذه تقول : لا ، بل ابنك الميت وابني الحي . وتكلمتا أمام الملك '),
(1676, '1 Kings', 11, 3, 23, ' فقال الملك : هذه تقول : هذا ابني الحي وابنك الميت ، وتلك تقول : لا ، بل ابنك الميت وابني الحي '),
(1677, '1 Kings', 11, 3, 24, ' فقال الملك : ايتوني بسيف . فأتوا بسيف بين يدي الملك '),
(1678, '1 Kings', 11, 3, 25, ' فقال الملك : اشطروا الولد الحي اثنين ، وأعطوا نصفا للواحدة ونصفا للأخرى '),
(1679, '1 Kings', 11, 3, 26, ' فتكلمت المرأة التي ابنها الحي إلى الملك ، لأن أحشاءها اضطرمت على ابنها ، وقالت : استمع يا سيدي . أعطوها الولد الحي ولا تميتوه . وأما تلك فقالت : لا يكون لي ولا لك . اشطروه '),
(1680, '1 Kings', 11, 3, 27, ' فأجاب الملك وقال : أعطوها الولد الحي ولا تميتوه فإنها أمه '),
(1681, '1 Kings', 11, 3, 28, ' ولما سمع جميع إسرائيل بالحكم الذي حكم به الملك خافوا الملك ، لأنهم رأوا حكمة الله فيه لإجراء الحكم '),
(1682, '1 Kings', 11, 4, 1, ' وكان الملك سليمان ملكا على جميع إسرائيل '),
(1683, '1 Kings', 11, 4, 2, ' وهؤلاء هم الرؤساء الذين له : عزرياهو بن صادوق الكاهن '),
(1684, '1 Kings', 11, 4, 3, ' وأليحورف وأخيا ابنا شيشا كاتبان . ويهوشافاط بن أخيلود المسجل '),
(1685, '1 Kings', 11, 4, 4, ' وبناياهو بن يهوياداع على الجيش ، وصادوق وأبياثار كاهنان '),
(1686, '1 Kings', 11, 4, 5, ' وعزرياهو بن ناثان على الوكلاء ، وزابود بن ناثان كاهن وصاحب الملك '),
(1687, '1 Kings', 11, 4, 6, ' وأخيشار على البيت ، وأدونيرام بن عبدا على التسخير '),
(1688, '1 Kings', 11, 4, 7, ' وكان لسليمان اثنا عشر وكيلا على جميع إسرائيل يمتارون للملك وبيته . كان على الواحد أن يمتار شهرا في السنة '),
(1689, '1 Kings', 11, 4, 8, ' وهذه أسماؤهم : ابن حور في جبل أفرايم '),
(1690, '1 Kings', 11, 4, 9, ' ابن دقر في ماقص وشعلبيم وبيت شمس وأيلون بيت حانان '),
(1691, '1 Kings', 11, 4, 10, ' ابن حسد في أربوت . كانت له سوكوه وكل أرض حافر '),
(1692, '1 Kings', 11, 4, 11, ' ابن أبيناداب في كل مرتفعات دور . كانت طافة بنت سليمان له امرأة '),
(1693, '1 Kings', 11, 4, 12, ' بعنا بن أخيلود في تعنك ومجدو وكل بيت شان التي بجانب صرتان تحت يزرعيل ، من بيت شان إلى آبل محولة ، إلى معبر يقمعام '),
(1694, '1 Kings', 11, 4, 13, ' ابن جابر في راموت جلعاد . له حووث يائير ابن منسى التي في جلعاد ، وله كورة أرجوب التي في باشان . ستون مدينة عظيمة بأسوار وعوارض من نحاس '),
(1695, '1 Kings', 11, 4, 14, ' أخيناداب بن عدو في محنايم '),
(1696, '1 Kings', 11, 4, 15, ' أخيمعص في نفتالي ، وهو أيضا أخذ باسمة بنت سليمان امرأة '),
(1697, '1 Kings', 11, 4, 16, ' بعنا بن حوشاي في أشير وبعلوت '),
(1698, '1 Kings', 11, 4, 17, ' يهوشافاط بن فاروح في يساكر '),
(1699, '1 Kings', 11, 4, 18, ' شمعي بن أيلا في بنيامين '),
(1700, '1 Kings', 11, 10, 5, ' وطعام مائدته ، ومجلس عبيده ، وموقف خدامه وملابسهم ، وسقاته ، ومحرقاته التي كان يصعدها في بيت الرب ، لم يبق فيها روح بعد '),
(1701, '1 Kings', 11, 10, 6, ' فقالت للملك : صحيحا كان الخبر الذي سمعته في أرضي عن أمورك وعن حكمتك '),
(1702, '1 Kings', 11, 10, 7, ' ولم أصدق الأخبار حتى جئت وأبصرت عيناي ، فهوذا النصف لم أخبر به . زدت حكمة وصلاحا على الخبر الذي سمعته '),
(1703, '1 Kings', 11, 10, 8, ' طوبى لرجالك ، وطوبى لعبيدك هؤلاء الواقفين أمامك دائما السامعين حكمتك '),
(1704, '1 Kings', 11, 10, 9, ' ليكن مباركا الرب إلهك الذي سر بك وجعلك على كرسي إسرائيل . لأن الرب أحب إسرائيل إلى الأبد جعلك ملكا ، لتجري حكما وبرا '),
(1705, '1 Kings', 11, 10, 10, ' وأعطت الملك مئة وعشرين وزنة ذهب وأطيابا كثيرة جدا وحجارة كريمة . لم يأت بعد مثل ذلك الطيب في الكثرة ، الذي أعطته ملكة سبا للملك سليمان '),
(1706, '1 Kings', 11, 10, 11, ' وكذا سفن حيرام التي حملت ذهبا من أوفير ، أتت من أوفير بخشب الصندل كثيرا جدا وبحجارة كريمة '),
(1707, '1 Kings', 11, 10, 12, ' فعمل سليمان خشب الصندل درابزينا لبيت الرب وبيت الملك ، وأعوادا وربابا للمغنين . لم يأت ولم ير مثل خشب الصندل ذلك إلى هذا اليوم '),
(1708, '1 Kings', 11, 10, 13, ' وأعطى الملك سليمان لملكة سبا كل مشتهاها الذي طلبت ، عدا ما أعطاها إياه حسب كرم الملك سليمان . فانصرفت وذهبت إلى أرضها هي وعبيدها '),
(1709, '1 Kings', 11, 10, 14, ' وكان وزن الذهب الذي أتى سليمان في سنة واحدة ست مئة وستا وستين وزنة ذهب '),
(1710, '1 Kings', 11, 10, 15, ' ما عدا الذي من عند التجار وتجارة التجار وجميع ملوك العرب وولاة الأرض '),
(1711, '1 Kings', 11, 10, 16, ' وعمل الملك سليمان مئتي ترس من ذهب مطرق ، خص الترس الواحد ست مئة شاقل من الذهب '),
(1712, '1 Kings', 11, 10, 17, ' وثلاث مئة مجن من ذهب مطرق . خص المجن ثلاثة أمناء من الذهب . وجعلها سليمان في بيت وعر لبنان '),
(1713, '1 Kings', 11, 10, 18, ' وعمل الملك كرسيا عظيما من عاج وغشاه بذهب إبريز '),
(1714, '1 Kings', 11, 10, 19, ' وللكرسي ست درجات . وللكرسي رأس مستدير من ورائه ، ويدان من هنا ومن هناك على مكان الجلوس ، وأسدان واقفان بجانب اليدين '),
(1715, '1 Kings', 11, 10, 20, ' واثنا عشر أسدا واقفة هناك على الدرجات الست من هنا ومن هناك . لم يعمل مثله في جميع الممالك '),
(1716, '1 Kings', 11, 10, 21, ' وجميع آنية شرب الملك سليمان من ذهب ، وجميع آنية بيت وعر لبنان من ذهب خالص ، لا فضة ، هي لم تحسب شيئا في أيام سليمان '),
(1717, '1 Kings', 11, 10, 22, ' لأنه كان للملك في البحر سفن ترشيش مع سفن حيرام . فكانت سفن ترشيش تأتي مرة في كل ثلاث سنوات . أتت سفن ترشيش حاملة ذهبا وفضة وعاجا وقرودا وطواويس '),
(1718, '1 Kings', 11, 10, 23, ' فتعاظم الملك سليمان على كل ملوك الأرض في الغنى والحكمة '),
(1719, '1 Kings', 11, 10, 24, ' وكانت كل الأرض ملتمسة وجه سليمان لتسمع حكمته التي جعلها الله في قلبه '),
(1720, '1 Kings', 11, 10, 25, ' وكانوا يأتون كل واحد بهديته ، بآنية فضة وآنية ذهب وحلل وسلاح وأطياب وخيل وبغال سنة فسنة '),
(1721, '1 Kings', 11, 10, 26, ' وجمع سليمان مراكب وفرسانا ، فكان له ألف وأربع مئة مركبة ، واثنا عشر ألف فارس ، فأقامهم في مدن المراكب ومع الملك في أورشليم '),
(1722, '1 Kings', 11, 10, 27, ' وجعل الملك الفضة في أورشليم مثل الحجارة ، وجعل الأرز مثل الجميز الذي في السهل في الكثرة '),
(1723, '1 Kings', 11, 10, 28, ' وكان مخرج الخيل التي لسليمان من مصر . وجماعة تجار الملك أخذوا جليبة بثمن '),
(1724, '1 Kings', 11, 10, 29, ' وكانت المركبة تصعد وتخرج من مصر بست مئة شاقل من الفضة ، والفرس بمئة وخمسين . وهكذا لجميع ملوك الحثيين وملوك أرام كانوا يخرجون عن يدهم '),
(1725, '1 Kings', 11, 11, 1, ' وأحب الملك سليمان نساء غريبة كثيرة مع بنت فرعون : موآبيات وعمونيات وأدوميات وصيدونيات وحثيات '),
(1726, '1 Kings', 11, 11, 2, ' من الأمم الذين قال عنهم الرب لبني إسرائيل : لا تدخلون إليهم وهم لا يدخلون إليكم ، لأنهم يميلون قلوبكم وراء آلهتهم . فالتصق سليمان بهؤلاء بالمحبة '),
(1727, '1 Kings', 11, 11, 3, ' وكانت له سبع مئة من النساء السيدات ، وثلاث مئة من السراري ، فأمالت نساؤه قلبه '),
(1728, '1 Kings', 11, 11, 4, ' وكان في زمان شيخوخة سليمان أن نساءه أملن قلبه وراء آلهة أخرى ، ولم يكن قلبه كاملا مع الرب إلهه كقلب داود أبيه '),
(1729, '1 Kings', 11, 11, 5, ' فذهب سليمان وراء عشتورث إلهة الصيدونيين ، وملكوم رجس العمونيين '),
(1730, '1 Kings', 11, 11, 6, ' وعمل سليمان الشر في عيني الرب ، ولم يتبع الرب تماما كداود أبيه '),
(1731, '1 Kings', 11, 11, 7, ' حينئذ بنى سليمان مرتفعة لكموش رجس الموآبيين على الجبل الذي تجاه أورشليم ، ولمولك رجس بني عمون '),
(1732, '1 Kings', 11, 11, 8, ' وهكذا فعل لجميع نسائه الغريبات اللواتي كن يوقدن ويذبحن لآلهتهن '),
(1733, '1 Kings', 11, 11, 9, ' فغضب الرب على سليمان لأن قلبه مال عن الرب إله إسرائيل الذي تراءى له مرتين '),
(1734, '1 Kings', 11, 11, 10, ' وأوصاه في هذا الأمر أن لا يتبع آلهة أخرى ، فلم يحفظ ما أوصى به الرب '),
(1735, '1 Kings', 11, 11, 11, ' فقال الرب لسليمان : من أجل أن ذلك عندك ، ولم تحفظ عهدي وفرائضي التي أوصيتك بها ، فإني أمزق المملكة عنك تمزيقا وأعطيها لعبدك '),
(1736, '1 Kings', 11, 11, 12, ' إلا إني لا أفعل ذلك في أيامك ، من أجل داود أبيك ، بل من يد ابنك أمزقها '),
(1737, '1 Kings', 11, 11, 13, ' على أني لا أمزق منك المملكة كلها ، بل أعطي سبطا واحدا لابنك ، لأجل داود عبدي ، ولأجل أورشليم التي اخترتها '),
(1738, '1 Kings', 11, 11, 14, ' وأقام الرب خصما لسليمان : هدد الأدومي ، كان من نسل الملك في أدوم '),
(1739, '1 Kings', 11, 11, 15, ' وحدث لما كان داود في أدوم ، عند صعود يوآب رئيس الجيش لدفن القتلى ، وضرب كل ذكر في أدوم '),
(1740, '1 Kings', 11, 11, 16, ' لأن يوآب وكل إسرائيل أقاموا هناك ستة أشهر حتى أفنوا كل ذكر في أدوم '),
(1741, '1 Kings', 11, 11, 17, ' أن هدد هرب هو ورجال أدوميون من عبيد أبيه معه ليأتوا مصر . وكان هدد غلاما صغيرا '),
(1742, '1 Kings', 11, 11, 18, ' وقاموا من مديان وأتوا إلى فاران ، وأخذوا معهم رجالا من فاران وأتوا إلى مصر ، إلى فرعون ملك مصر ، فأعطاه بيتا وعين له طعاما وأعطاه أرضا '),
(1743, '1 Kings', 11, 11, 19, ' فوجد هدد نعمة في عيني فرعون جدا ، وزوجه أخت امرأته ، أخت تحفنيس الملكة '),
(1744, '1 Kings', 11, 11, 20, ' فولدت له أخت تحفنيس جنوبث ابنه ، وفطمته تحفنيس في وسط بيت فرعون . وكان جنوبث في بيت فرعون بين بني فرعون '),
(1745, '1 Kings', 11, 11, 21, ' فسمع هدد في مصر بأن داود قد اضطجع مع آبائه ، وبأن يوآب رئيس الجيش قد مات . فقال هدد لفرعون : أطلقني إلى أرضي '),
(1746, '1 Kings', 11, 11, 22, ' فقال له فرعون : ماذا أعوزك عندي حتى إنك تطلب الذهاب إلى أرضك ؟  . فقال : لا شيء ، وإنما أطلقني '),
(1747, '1 Kings', 11, 11, 23, ' وأقام الله له خصما آخر : رزون بن أليداع ، الذي هرب من عند سيده هدد عزر ملك صوبة '),
(1748, '1 Kings', 11, 11, 24, ' فجمع إليه رجالا فصار رئيس غزاة عند قتل داود إياهم ، فانطلقوا إلى دمشق وأقاموا بها وملكوا في دمشق '),
(1749, '1 Kings', 11, 11, 25, ' وكان خصما لإسرائيل كل أيام سليمان ، مع شر هدد . فكره إسرائيل ، وملك على أرام '),
(1750, '1 Kings', 11, 11, 26, ' ويربعام بن ناباط ، أفرايمي من صردة ، عبد لسليمان . واسم أمه صروعة ، وهي امرأة أرملة ، رفع يده على الملك '),
(1751, '1 Kings', 11, 11, 27, ' وهذا هو سبب رفعه يده على الملك : أن سليمان بنى القلعة وسد شقوق مدينة داود أبيه '),
(1752, '1 Kings', 11, 11, 28, ' وكان الرجل يربعام جبار بأس ، فلما رأى سليمان الغلام أنه عامل شغلا ، أقامه على كل أعمال بيت يوسف '),
(1753, '1 Kings', 11, 11, 29, ' وكان في ذلك الزمان لما خرج يربعام من أورشليم ، أنه لاقاه أخيا الشيلوني النبي في الطريق وهو لابس رداء جديدا ، وهما وحدهما في الحقل '),
(1754, '1 Kings', 11, 11, 30, ' فقبض أخيا على الرداء الجديد الذي عليه ومزقه اثنتي عشرة قطعة '),
(1755, '1 Kings', 11, 11, 31, ' وقال ليربعام : خذ لنفسك عشر قطع ، لأنه هكذا قال الرب إله إسرائيل : هأنذا أمزق المملكة من يد سليمان وأعطيك عشرة أسباط '),
(1756, '1 Kings', 11, 11, 32, ' ويكون له سبط واحد من أجل عبدي داود ومن أجل أورشليم المدينة التي اخترتها من كل أسباط إسرائيل '),
(1757, '1 Kings', 11, 11, 33, ' لأنهم تركوني وسجدوا لعشتورث إلهة الصيدونيين ، ولكموش إله الموآبيين ، ولملكوم إله بني عمون ، ولم يسلكوا في طرقي ليعملوا المستقيم في عيني وفرائضي وأحكامي كداود أبيه '),
(1758, '1 Kings', 11, 11, 34, ' ولا آخذ كل المملكة من يده ، بل أصيره رئيسا كل أيام حياته لأجل داود عبدي الذي اخترته الذي حفظ وصاياي وفرائضي '),
(1759, '1 Kings', 11, 11, 35, ' وآخذ المملكة من يد ابنه وأعطيك إياها ، أي الأسباط العشرة '),
(1760, '1 Kings', 11, 11, 36, ' وأعطي ابنه سبطا واحدا ، ليكون سراج لداود عبدي كل الأيام أمامي في أورشليم المدينة التي اخترتها لنفسي لأضع اسمي فيها '),
(1761, '1 Kings', 11, 11, 37, ' وآخذك فتملك حسب كل ما تشتهي نفسك ، وتكون ملكا على إسرائيل '),
(1762, '1 Kings', 11, 11, 38, ' فإذا سمعت لكل ما أوصيك به ، وسلكت في طرقي ، وفعلت ما هو مستقيم في عيني ، وحفظت فرائضي ووصاياي كما فعل داود عبدي ، أكون معك وأبني لك بيتا آمنا كما بنيت لداود ، وأعطيك إسرائيل '),
(1763, '1 Kings', 11, 11, 39, ' وأذل نسل داود من أجل هذا ، ولكن لا كل الأيام '),
(1764, '1 Kings', 11, 11, 40, ' وطلب سليمان قتل يربعام ، فقام يربعام وهرب إلى مصر إلى شيشق ملك مصر . وكان في مصر إلى وفاة سليمان '),
(1765, '1 Kings', 11, 11, 41, ' وبقية أمور سليمان وكل ما صنع وحكمته ، أما هي مكتوبة في سفر أمور سليمان '),
(1766, '1 Kings', 11, 11, 42, ' وكانت الأيام التي ملك فيها سليمان في أورشليم على كل إسرائيل أربعين سنة '),
(1767, '1 Kings', 11, 11, 43, ' ثم اضطجع سليمان مع آبائه ودفن في مدينة داود أبيه ، وملك رحبعام ابنه عوضا عنه '),
(1768, '1 Kings', 11, 12, 1, ' وذهب رحبعام إلى شكيم ، لأنه جاء إلى شكيم جميع إسرائيل ليملكوه '),
(1769, '1 Kings', 11, 12, 2, ' ولما سمع يربعام بن نباط وهو بعد في مصر ، لأنه هرب من وجه سليمان الملك ، وأقام يربعام في مصر '),
(1770, '1 Kings', 11, 12, 3, ' وأرسلوا فدعوه . أتى يربعام وكل جماعة إسرائيل وكلموا رحبعام قائلين '),
(1771, '1 Kings', 11, 12, 4, ' إن أباك قسى نيرنا ، وأما أنت فخفف الآن من عبودية أبيك القاسية ، ومن نيره الثقيل الذي جعله علينا ، فنخدمك '),
(1772, '1 Kings', 11, 12, 5, ' فقال لهم : اذهبوا إلى ثلاثة أيام أيضا ثم ارجعوا إلي . فذهب الشعب '),
(1773, '1 Kings', 11, 12, 6, ' فاستشار الملك رحبعام الشيوخ الذين كانوا يقفون أمام سليمان أبيه وهو حي ، قائلا : كيف تشيرون أن أرد جوابا إلى هذا الشعب '),
(1774, '1 Kings', 11, 12, 7, ' فكلموه قائلين : إن صرت اليوم عبدا لهذا الشعب وخدمتهم وأجبتهم وكلمتهم كلاما حسنا ، يكونون لك عبيدا كل الأيام '),
(1775, '1 Kings', 11, 6, 38, ' وفي السنة الحادية عشرة في شهر بول ، وهو الشهر الثامن ، أكمل البيت في جميع أموره وأحكامه . فبناه في سبع سنين '),
(1776, '1 Kings', 11, 7, 1, ' وأما بيته فبناه سليمان في ثلاث عشرة سنة وأكمل كل بيته '),
(1777, '1 Kings', 11, 7, 2, ' وبنى بيت وعر لبنان ، طوله مئة ذراع وعرضه خمسون ذراعا وسمكه ثلاثون ذراعا ، على أربعة صفوف من أعمدة أرز وجوائز أرز على الأعمدة '),
(1778, '1 Kings', 11, 7, 3, ' وسقف بأرز من فوق على الغرفات الخمس والأربعين التي على الأعمدة . كل صف خمس عشرة '),
(1779, '1 Kings', 11, 7, 4, ' والسقوف ثلاث طباق ، وكوة مقابل كوة ثلاث مرات '),
(1780, '1 Kings', 11, 7, 5, ' وجميع الأبواب والقوائم مربعة مسقوفة ، ووجه كوة مقابل كوة ثلاث مرات '),
(1781, '1 Kings', 11, 7, 6, ' وعمل رواق الأعمدة طوله خمسون ذراعا وعرضه ثلاثون ذراعا . ورواقا آخر قدامها وأعمدة وأسكفة قدامها '),
(1782, '1 Kings', 11, 7, 7, ' وعمل رواق الكرسي حيث يقضي ، أي رواق القضاء ، وغشي بأرز من أرض إلى سقف '),
(1783, '1 Kings', 11, 7, 8, ' وبيته الذي كان يسكنه في دار أخرى داخل الرواق ، كان كهذا العمل . وعمل بيتا لابنة فرعون التي أخذها سليمان ، كهذا الرواق '),
(1784, '1 Kings', 11, 7, 9, ' كل هذه من حجارة كريمة كقياس الحجارة المنحوتة منشورة بمنشار من داخل ومن خارج ، من الأساس إلى الإفريز ، ومن خارج إلى الدار الكبيرة '),
(1785, '1 Kings', 11, 7, 10, ' وكان مؤسسا على حجارة كريمة ، حجارة عظيمة ، حجارة عشر أذرع ، وحجارة ثمان أذرع '),
(1786, '1 Kings', 11, 7, 11, ' ومن فوق حجارة كريمة كقياس المنحوتة ، وأرز '),
(1787, '1 Kings', 11, 7, 12, ' وللدار الكبيرة في مستديرها ثلاثة صفوف منحوتة ، وصف من جوائز الأرز . كذلك دار بيت الرب الداخلية ورواق البيت '),
(1788, '1 Kings', 11, 7, 13, ' وأرسل الملك سليمان وأخذ حيرام من صور '),
(1789, '1 Kings', 11, 7, 14, ' وهو ابن امرأة أرملة من سبط نفتالي ، وأبوه رجل صوري نحاس ، وكان ممتلئا حكمة وفهما ومعرفة لعمل كل عمل في النحاس . فأتى إلى الملك سليمان وعمل كل عمله '),
(1790, '1 Kings', 11, 7, 15, ' وصور العمودين من نحاس ، طول العمود الواحد ثمانية عشر ذراعا . وخيط اثنتا عشرة ذراعا يحيط بالعمود الآخر '),
(1791, '1 Kings', 11, 7, 16, ' وعمل تاجين ليضعهما على رأسي العمودين من نحاس مسبوك . طول التاج الواحد خمس أذرع ، وطول التاج الآخر خمس أذرع '),
(1792, '1 Kings', 11, 7, 17, ' وشباكا عملا مشبكا وضفائر كعمل السلاسل للتاجين اللذين على رأسي العمودين ، سبعا للتاج الواحد ، وسبعا للتاج الآخر '),
(1793, '1 Kings', 11, 7, 18, ' وعمل للعمودين صفين من الرمان في مستديرهما على الشبكة الواحدة لتغطية التاج الذي على رأس العمود ، وهكذا عمل للتاج الآخر '),
(1794, '1 Kings', 11, 7, 19, ' والتاجان اللذان على رأسي العمودين من صيغة السوسن كما في الرواق هما أربع أذرع '),
(1795, '1 Kings', 11, 7, 20, ' وكذلك التاجان اللذان على العمودين من عند البطن الذي من جهة الشبكة صاعدا . والرمانات مئتان على صفوف مستديرة على التاج الثاني '),
(1796, '1 Kings', 11, 7, 21, ' وأوقف العمودين في رواق الهيكل . فأوقف العمود الأيمن ودعا اسمه ياكين . ثم أوقف العمود الأيسر ودعا اسمه بوعز '),
(1797, '1 Kings', 11, 7, 22, ' وعلى رأس العمودين صيغة السوسن . فكمل عمل العمودين '),
(1798, '1 Kings', 11, 7, 23, ' وعمل البحر مسبوكا . عشر أذرع من شفته إلى شفته ، وكان مدورا مستديرا . ارتفاعه خمس أذرع ، وخيط ثلاثون ذراعا يحيط به بدائره '),
(1799, '1 Kings', 11, 7, 24, ' وتحت شفته قثاء مستديرا تحيط به . عشر للذراع . محيطة بالبحر بمستديره صفين . القثاء قد سبكت بسبكه '),
(1800, '1 Kings', 11, 7, 25, ' وكان قائما على اثني عشر ثورا : ثلاثة متوجهة إلى الشمال ، وثلاثة متوجهة إلى الغرب ، وثلاثة متوجهة إلى الجنوب ، وثلاثة متوجهة إلى الشرق . والبحر عليها من فوق ، وجميع أعجازها إلى داخل '),
(1801, '1 Kings', 11, 7, 26, ' وغلظه شبر ، وشفته كعمل شفة كأس بزهر سوسن . يسع ألفي بث '),
(1802, '1 Kings', 11, 7, 27, ' وعمل القواعد العشر من نحاس ، طول القاعدة الواحدة أربع أذرع ، وعرضها أربع أذرع ، وارتفاعها ثلاث أذرع '),
(1803, '1 Kings', 11, 7, 28, ' وهذا عمل القواعد : لها أتراس ، والأتراس بين الحواجب ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(1804, '1 Kings', 11, 7, 29, ' وعلى الأتراس التي بين الحواجب أسود وثيران وكروبيم ، وكذلك على الحواجب من فوق . ومن تحت الأسود والثيران قلائد زهور عمل مدلى '),
(1805, '1 Kings', 11, 7, 30, ' ولكل قاعدة أربع بكر من نحاس وقطاب من نحاس ، ولقوائمها الأربع أكتاف ، والأكتاف مسبوكة تحت المرحضة بجانب كل قلادة '),
(1806, '1 Kings', 11, 7, 31, ' وفمها داخل الإكليل ومن فوق ذراع . وفمها مدور كعمل قاعدة ذراع ونصف ذراع . وأيضا على فمها نقش . وأتراسها مربعة لا مدورة '),
(1807, '1 Kings', 11, 7, 32, ' والبكر الأربع تحت الأتراس ، وخطاطيف البكر في القاعدة ، وارتفاع البكرة الواحدة ذراع ونصف ذراع '),
(1808, '1 Kings', 11, 7, 33, ' وعمل البكر كعمل بكرة مركبة . خطاطيفها وأطرها وأصابعها وقبوبها كلها مسبوكة '),
(1809, '1 Kings', 11, 7, 34, ' وأربع أكتاف على أربع زوايا القاعدة الواحدة ، وأكتاف القاعدة منها '),
(1810, '1 Kings', 11, 7, 35, ' وأعلى القاعدة مقبب مستدير على ارتفاع نصف ذراع من أعلى القاعدة . أياديها وأتراسها منها '),
(1811, '1 Kings', 11, 7, 36, ' ونقش على ألواح أياديها ، وعلى أتراسها كروبيم وأسودا ونخيلا كسعة كل واحدة ، وقلائد زهور مستديرة '),
(1812, '1 Kings', 11, 7, 37, ' هكذا عمل القواعد العشر . لجميعها سبك واحد وقياس واحد وشكل واحد '),
(1813, '1 Kings', 11, 7, 38, ' وعمل عشر مراحض من نحاس تسع كل مرحضة أربعين بثا . المرحضة الواحدة أربع أذرع . مرحضة واحدة على القاعدة الواحدة للعشر القواعد '),
(1814, '1 Kings', 11, 7, 39, ' وجعل القواعد خمسا على جانب البيت الأيمن ، وخمسا على جانب البيت الأيسر ، وجعل البحر على جانب البيت الأيمن إلى الشرق من جهة الجنوب '),
(1815, '1 Kings', 11, 7, 40, ' وعمل حيرام المراحض والرفوش والمناضح . وانتهى حيرام من جميع العمل الذي عمله للملك سليمان لبيت الرب '),
(1816, '1 Kings', 11, 7, 41, ' العمودين وكرتي التاجين اللذين على رأسي العمودين ، والشبكتين لتغطية كرتي التاجين اللذين على رأسي العمودين '),
(1817, '1 Kings', 11, 7, 42, ' وأربع مئة الرمانة التي للشبكتين ، صفا رمان للشبكة الواحدة لأجل تغطية كرتي التاجين اللذين على العمودين '),
(1818, '1 Kings', 11, 7, 43, ' والقواعد العشر والمراحض العشر على القواعد '),
(1819, '1 Kings', 11, 7, 44, ' والبحر الواحد والاثني عشر ثورا تحت البحر '),
(1820, '1 Kings', 11, 7, 45, ' والقدور والرفوش والمناضح . وجميع هذه الآنية التي عملها حيرام للملك سليمان لبيت الرب هي من نحاس مصقول '),
(1821, '1 Kings', 11, 7, 46, ' في غور الأردن سبكها الملك ، في أرض الخزف بين سكوت وصرتان '),
(1822, '1 Kings', 11, 7, 47, ' وترك سليمان وزن جميع الآنية لأنها كثيرة جدا جدا . لم يتحقق وزن النحاس '),
(1823, '1 Kings', 11, 7, 48, ' وعمل سليمان جميع آنية بيت الرب : المذبح من ذهب ، والمائدة التي عليها خبز الوجوه من ذهب '),
(1824, '1 Kings', 11, 7, 49, ' والمنائر خمسا عن اليمين وخمسا عن اليسار أمام المحراب من ذهب خالص ، والأزهار والسرج والملاقط من ذهب '),
(1825, '1 Kings', 11, 7, 50, ' والطسوس والمقاص والمناضح والصحون والمجامر من ذهب خالص ، والوصل لمصاريع البيت الداخلي ، أي لقدس الأقداس ، ولأبواب البيت ، أي الهيكل من ذهب '),
(1826, '1 Kings', 11, 7, 51, ' وأكمل جميع العمل الذي عمله الملك سليمان لبيت الرب . وأدخل سليمان أقداس داود أبيه : الفضة والذهب والآنية ، وجعلها في خزائن بيت الرب '),
(1827, '1 Kings', 11, 8, 1, ' حينئذ جمع سليمان شيوخ إسرائيل وكل رؤوس الأسباط ، رؤساء الآباء من بني إسرائيل إلى الملك سليمان في أورشليم ، لإصعاد تابوت عهد الرب من مدينة داود ، هي صهيون '),
(1828, '1 Kings', 11, 8, 2, ' فاجتمع إلى الملك سليمان جميع رجال إسرائيل في العيد في شهر أيثانيم ، هو الشهر السابع '),
(1829, '1 Kings', 11, 8, 3, ' وجاء جميع شيوخ إسرائيل ، وحمل الكهنة التابوت '),
(1830, '1 Kings', 11, 8, 4, ' وأصعدوا تابوت الرب وخيمة الاجتماع مع جميع آنية القدس التي في الخيمة ، فأصعدها الكهنة واللاويون '),
(1831, '1 Kings', 11, 8, 5, ' والملك سليمان وكل جماعة إسرائيل المجتمعين إليه معه أمام التابوت ، كانوا يذبحون من الغنم والبقر ما لا يحصى ولا يعد من الكثرة '),
(1832, '1 Kings', 11, 8, 6, ' وأدخل الكهنة تابوت عهد الرب إلى مكانه في محراب البيت في قدس الأقداس ، إلى تحت جناحي الكروبين '),
(1833, '1 Kings', 11, 8, 7, ' لأن الكروبين بسطا أجنحتهما على موضع التابوت ، وظلل الكروبان التابوت وعصيه من فوق '),
(1834, '1 Kings', 11, 8, 8, ' وجذبوا العصي فتراءت رؤوس العصي من القدس أمام المحراب ولم تر خارجا ، وهي هناك إلى هذا اليوم '),
(1835, '1 Kings', 11, 8, 9, ' لم يكن في التابوت إلا لوحا الحجر اللذان وضعهما موسى هناك في حوريب حين عاهد الرب بني إسرائيل عند خروجهم من أرض مصر '),
(1836, '1 Kings', 11, 8, 10, ' وكان لما خرج الكهنة من القدس أن السحاب ملأ بيت الرب '),
(1837, '1 Kings', 11, 8, 11, ' ولم يستطع الكهنة أن يقفوا للخدمة بسبب السحاب ، لأن مجد الرب ملأ بيت الرب '),
(1838, '1 Kings', 11, 8, 12, ' حينئذ تكلم سليمان : قال الرب إنه يسكن في الضباب '),
(1839, '1 Kings', 11, 8, 13, ' إني قد بنيت لك بيت سكنى ، مكانا لسكناك إلى الأبد '),
(1840, '1 Kings', 11, 8, 14, ' وحول الملك وجهه وبارك كل جمهور إسرائيل ، وكل جمهور إسرائيل واقف '),
(1841, '1 Kings', 11, 8, 15, ' وقال : مبارك الرب إله إسرائيل الذي تكلم بفمه إلى داود أبي وأكمل بيده قائلا '),
(1842, '1 Kings', 11, 8, 16, ' منذ يوم أخرجت شعبي إسرائيل من مصر لم أختر مدينة من جميع أسباط إسرائيل لبناء بيت ليكون اسمي هناك ، بل إنما اخترت داود ليكون على شعبي إسرائيل '),
(1843, '1 Kings', 11, 8, 17, ' وكان في قلب داود أبي أن يبني بيتا لاسم الرب إله إسرائيل '),
(1844, '1 Kings', 11, 8, 18, ' فقال الرب لداود أبي : من أجل أنه كان في قلبك أن تبني بيتا لاسمي ، قد أحسنت بكونه في قلبك '),
(1845, '1 Kings', 11, 8, 19, ' إلا إنك أنت لا تبني البيت ، بل ابنك الخارج من صلبك هو يبني البيت لاسمي '),
(1846, '1 Kings', 11, 8, 20, ' وأقام الرب كلامه الذي تكلم به ، وقد قمت أنا مكان داود أبي وجلست على كرسي إسرائيل كما تكلم الرب ، وبنيت البيت لاسم الرب إله إسرائيل '),
(1847, '1 Kings', 11, 8, 21, ' وجعلت هناك مكانا للتابوت الذي فيه عهد الرب الذي قطعه مع آبائنا عند إخراجه إياهم من أرض مصر '),
(1848, '1 Kings', 11, 8, 22, ' ووقف سليمان أمام مذبح الرب تجاه كل جماعة إسرائيل ، وبسط يديه إلى السماء '),
(1849, '1 Kings', 11, 8, 23, ' وقال : أيها الرب إله إسرائيل ، ليس إله مثلك في السماء من فوق ، ولا على الأرض من أسفل ، حافظ العهد والرحمة لعبيدك السائرين أمامك بكل قلوبهم '),
(1850, '1 Kings', 11, 8, 24, ' الذي قد حفظت لعبدك داود أبي ما كلمته به ، فتكلمت بفمك وأكملت بيدك كهذا اليوم '),
(1851, '1 Kings', 11, 8, 25, ' والآن أيها الرب إله إسرائيل احفظ لعبدك داود أبي ما كلمته به قائلا : لا يعدم لك أمامي رجل يجلس على كرسي إسرائيل ، إن كان بنوك إنما يحفظون طرقهم حتى يسيروا أمامي كما سرت أنت أمامي '),
(1852, '1 Kings', 11, 8, 26, ' والآن يا إله إسرائيل فليتحقق كلامك الذي كلمت به عبدك داود أبي '),
(1853, '1 Kings', 11, 8, 27, ' لأنه هل يسكن الله حقا على الأرض ؟ هوذا السماوات وسماء السماوات لا تسعك ، فكم بالأقل هذا البيت الذي بنيت '),
(1854, '1 Kings', 11, 8, 28, ' فالتفت إلى صلاة عبدك وإلى تضرعه أيها الرب إلهي ، واسمع الصراخ والصلاة التي يصليها عبدك أمامك اليوم '),
(1855, '1 Kings', 11, 8, 29, ' لتكون عيناك مفتوحتين على هذا البيت ليلا ونهارا ، على الموضع الذي قلت : إن اسمي يكون فيه ، لتسمع الصلاة التي يصليها عبدك في هذا الموضع '),
(1856, '1 Kings', 11, 8, 30, ' واسمع تضرع عبدك وشعبك إسرائيل الذين يصلون في هذا الموضع ، واسمع أنت في موضع سكناك في السماء ، وإذا سمعت فاغفر '),
(1857, '1 Kings', 11, 8, 31, ' إذا أخطأ أحد إلى صاحبه ووضع عليه حلفا ليحلفه ، وجاء الحلف أمام مذبحك في هذا البيت '),
(1858, '1 Kings', 11, 8, 32, ' فاسمع أنت في السماء واعمل واقض بين عبيدك ، إذ تحكم على المذنب فتجعل طريقه على رأسه ، وتبرر البار إذ تعطيه حسب بره '),
(1859, '1 Kings', 11, 8, 33, ' إذا انكسر شعبك إسرائيل أمام العدو لأنهم أخطأوا إليك ، ثم رجعوا إليك واعترفوا باسمك وصلوا وتضرعوا إليك نحو هذا البيت '),
(1860, '1 Kings', 11, 8, 34, ' فاسمع أنت من السماء واغفر خطية شعبك إسرائيل ، وأرجعهم إلى الأرض التي أعطيتها لآبائهم '),
(1861, '1 Kings', 11, 8, 35, ' إذا أغلقت السماء ولم يكن مطر ، لأنهم أخطأوا إليك ، ثم صلوا في هذا الموضع واعترفوا باسمك ، ورجعوا عن خطيتهم لأنك ضايقتهم '),
(1862, '1 Kings', 11, 8, 36, ' فاسمع أنت من السماء واغفر خطية عبيدك وشعبك إسرائيل ، فتعلمهم الطريق الصالح الذي يسلكون فيه ، وأعط مطرا على أرضك التي أعطيتها لشعبك ميراثا '),
(1863, '1 Kings', 11, 8, 37, ' إذا صار في الأرض جوع ، إذا صار وبأ ، إذا صار لفح أو يرقان أو جراد جردم ، أو إذا حاصره عدوه في أرض مدنه ، في كل ضربة وكل مرض '),
(1864, '1 Kings', 11, 8, 38, ' فكل صلاة وكل تضرع تكون من أي إنسان كان من كل شعبك إسرائيل ، الذين يعرفون كل واحد ضربة قلبه ، فيبسط يديه نحو هذا البيت '),
(1865, '1 Kings', 11, 8, 39, ' فاسمع أنت من السماء مكان سكناك واغفر ، واعمل وأعط كل إنسان حسب كل طرقه كما تعرف قلبه . لأنك أنت وحدك قد عرفت قلوب كل بني البشر '),
(1866, '1 Kings', 11, 8, 40, ' لكي يخافوك كل الأيام التي يحيون فيها على وجه الأرض التي أعطيت لآبائنا '),
(1867, '1 Kings', 11, 8, 41, ' وكذلك الأجنبي الذي ليس من شعبك إسرائيل هو ، وجاء من أرض بعيدة من أجل اسمك '),
(1868, '1 Kings', 11, 8, 42, ' لأنهم يسمعون باسمك العظيم وبيدك القوية وذراعك الممدودة ، فمتى جاء وصلى في هذا البيت '),
(1869, '1 Kings', 11, 8, 43, ' فاسمع أنت من السماء مكان سكناك ، وافعل حسب كل ما يدعو به إليك الأجنبي ، لكي يعلم كل شعوب الأرض اسمك ، فيخافوك كشعبك إسرائيل ، ولكي يعلموا أنه قد دعي اسمك على هذا البيت الذي بنيت '),
(1870, '1 Kings', 11, 8, 44, ' إذا خرج شعبك لمحاربة عدوه في الطريق الذي ترسلهم فيه ، وصلوا إلى الرب نحو المدينة التي اخترتها والبيت الذي بنيته لاسمك '),
(1871, '1 Kings', 11, 8, 45, ' فاسمع من السماء صلاتهم وتضرعهم واقض قضاءهم '),
(1872, '1 Kings', 11, 8, 46, ' إذا أخطأوا إليك ، لأنه ليس إنسان لا يخطئ ، وغضبت عليهم ودفعتهم أمام العدو وسباهم ، سابوهم إلى أرض العدو ، بعيدة أو قريبة '),
(1873, '1 Kings', 11, 8, 47, ' فإذا ردوا إلى قلوبهم في الأرض التي يسبون إليها ورجعوا وتضرعوا إليك في أرض سبيهم قائلين : قد أخطأنا وعوجنا وأذنبنا '),
(1874, '1 Kings', 11, 8, 48, ' ورجعوا إليك من كل قلوبهم ومن كل أنفسهم في أرض أعدائهم الذين سبوهم ، وصلوا إليك نحو أرضهم التي أعطيت لآبائهم ، نحو المدينة التي اخترت والبيت الذي بنيت لاسمك '),
(1875, '1 Kings', 11, 8, 49, ' فاسمع في السماء مكان سكناك صلاتهم وتضرعهم واقض قضاءهم '),
(1876, '1 Kings', 11, 8, 50, ' واغفر لشعبك ما أخطأوا به إليك ، وجميع ذنوبهم التي أذنبوا بها إليك ، وأعطهم رحمة أمام الذين سبوهم فيرحموهم '),
(1877, '1 Kings', 11, 8, 51, ' لأنهم شعبك وميراثك الذين أخرجت من مصر ، من وسط كور الحديد '),
(1878, '1 Kings', 11, 8, 52, ' لتكون عيناك مفتوحتين نحو تضرع عبدك وتضرع شعبك إسرائيل ، فتصغي إليهم في كل ما يدعونك '),
(1879, '1 Kings', 11, 8, 53, ' لأنك أنت أفرزتهم لك ميراثا من جميع شعوب الأرض ، كما تكلمت عن يد موسى عبدك عند إخراجك آباءنا من مصر يا سيدي الرب '),
(1880, '1 Kings', 11, 8, 54, ' وكان لما انتهى سليمان من الصلاة إلى الرب بكل هذه الصلاة والتضرع ، أنه نهض من أمام مذبح الرب ، من الجثو على ركبتيه ، ويداه مبسوطتان نحو السماء '),
(1881, '1 Kings', 11, 8, 55, ' ووقف وبارك كل جماعة إسرائيل بصوت عال قائلا '),
(1882, '1 Kings', 11, 8, 56, ' مبارك الرب الذي أعطى راحة لشعبه إسرائيل حسب كل ما تكلم به ، ولم تسقط كلمة واحدة من كل كلامه الصالح الذي تكلم به عن يد موسى عبده '),
(1883, '1 Kings', 11, 8, 57, ' ليكن الرب إلهنا معنا كما كان مع آبائنا فلا يتركنا ولا يرفضنا '),
(1884, '1 Kings', 11, 8, 58, ' ليميل بقلوبنا إليه لكي نسير في جميع طرقه ونحفظ وصاياه وفرائضه وأحكامه التي أوصى بها آباءنا '),
(1885, '1 Kings', 11, 8, 59, ' وليكن كلامي هذا الذي تضرعت به أمام الرب قريبا من الرب إلهنا نهارا وليلا ، ليقضي قضاء عبده وقضاء شعبه إسرائيل ، أمر كل يوم في يومه '),
(1886, '1 Kings', 11, 8, 60, ' ليعلم كل شعوب الأرض أن الرب هو الله وليس آخر '),
(1887, '1 Kings', 11, 8, 61, ' فليكن قلبكم كاملا لدى الرب إلهنا إذ تسيرون في فرائضه وتحفظون وصاياه كهذا اليوم '),
(1888, '1 Kings', 11, 8, 62, ' ثم إن الملك وجميع إسرائيل معه ذبحوا ذبائح أمام الرب '),
(1889, '1 Kings', 11, 8, 63, ' وذبح سليمان ذبائح السلامة التي ذبحها للرب : من البقر اثنين وعشرين ألفا ، ومن الغنم مئة ألف وعشرين ألفا ، فدشن الملك وجميع بني إسرائيل بيت الرب '),
(1890, '1 Kings', 11, 8, 64, ' في ذلك اليوم قدس الملك وسط الدار التي أمام بيت الرب ، لأنه قرب هناك المحرقات والتقدمات وشحم ذبائح السلامة ، لأن مذبح النحاس الذي أمام الرب كان صغيرا عن أن يسع المحرقات والتقدمات وشحم ذبائح السلامة '),
(1891, '1 Kings', 11, 8, 65, ' وعيد سليمان العيد في ذلك الوقت وجميع إسرائيل معه ، جمهور كبير من مدخل حماة إلى وادي مصر ، أمام الرب إلهنا سبعة أيام وسبعة أيام ، أربعة عشر يوما '),
(1892, '1 Kings', 11, 8, 66, ' وفي اليوم الثامن صرف الشعب ، فباركوا الملك وذهبوا إلى خيمهم فرحين وطيبي القلوب ، لأجل كل الخير الذي عمل الرب لداود عبده ولإسرائيل شعبه '),
(1893, '1 Kings', 11, 9, 1, ' وكان لما أكمل سليمان بناء بيت الرب وبيت الملك وكل مرغوب سليمان الذي سر أن يعمل '),
(1894, '1 Kings', 11, 9, 2, ' أن الرب تراءى لسليمان ثانية كما تراءى له في جبعون '),
(1895, '1 Kings', 11, 9, 3, ' وقال له الرب : قد سمعت صلاتك وتضرعك الذي تضرعت به أمامي . قدست هذا البيت الذي بنيته لأجل وضع اسمي فيه إلى الأبد ، وتكون عيناي وقلبي هناك كل الأيام '),
(1896, '1 Kings', 11, 9, 4, ' وأنت إن سلكت أمامي كما سلك داود أبوك بسلامة قلب واستقامة ، وعملت حسب كل ما أوصيتك وحفظت فرائضي وأحكامي '),
(1897, '1 Kings', 11, 9, 5, ' فإني أقيم كرسي ملكك على إسرائيل إلى الأبد كما كلمت داود أباك قائلا : لا يعدم لك رجل عن كرسي إسرائيل '),
(1898, '1 Kings', 11, 9, 6, ' إن كنتم تنقلبون أنتم أو أبناؤكم من ورائي ، ولا تحفظون وصاياي ، فرائضي التي جعلتها أمامكم ، بل تذهبون وتعبدون آلهة أخرى وتسجدون لها '),
(1899, '1 Kings', 11, 9, 7, ' فإني أقطع إسرائيل عن وجه الأرض التي أعطيتهم إياها ، والبيت الذي قدسته لاسمي أنفيه من أمامي ، ويكون إسرائيل مثلا وهزأة في جميع الشعوب '),
(1900, '1 Kings', 11, 9, 8, ' وهذا البيت يكون عبرة . كل من يمر عليه يتعجب ويصفر ، ويقولون : لماذا عمل الرب هكذا لهذه الأرض ولهذا البيت '),
(1901, '1 Kings', 11, 9, 9, ' فيقولون : من أجل أنهم تركوا الرب إلههم الذي أخرج آباءهم من أرض مصر ، وتمسكوا بآلهة أخرى وسجدوا لها وعبدوها ، لذلك جلب الرب عليهم كل هذا الشر '),
(1902, '1 Kings', 11, 9, 10, ' وبعد نهاية عشرين سنة بعدما بنى سليمان البيتين ، بيت الرب وبيت الملك '),
(1903, '1 Kings', 11, 9, 11, ' وكان حيرام ملك صور قد ساعف سليمان بخشب أرز وخشب سرو وذهب ، حسب كل مسرته . أعطى حينئذ الملك سليمان حيرام عشرين مدينة في أرض الجليل '),
(1904, '1 Kings', 11, 9, 12, ' فخرج حيرام من صور ليرى المدن التي أعطاه إياها سليمان ، فلم تحسن في عينيه '),
(1905, '1 Kings', 11, 9, 13, ' فقال : ما هذه المدن التي أعطيتني يا أخي ؟  . ودعاها أرض كابول إلى هذا اليوم '),
(1906, '1 Kings', 11, 9, 14, ' وأرسل حيرام للملك مئة وعشرين وزنة ذهب '),
(1907, '1 Kings', 11, 9, 15, ' وهذا هو سبب التسخير الذي جعله الملك سليمان لبناء بيت الرب وبيته والقلعة وسور أورشليم وحاصور ومجدو وجازر '),
(1908, '1 Kings', 11, 9, 16, ' صعد فرعون ملك مصر وأخذ جازر وأحرقها بالنار ، وقتل الكنعانيين الساكنين في المدينة ، وأعطاها مهرا لابنته امرأة سليمان '),
(1909, '1 Kings', 11, 9, 17, ' وبنى سليمان جازر وبيت حورون السفلى '),
(1910, '1 Kings', 11, 9, 18, ' وبعلة وتدمر في البرية في الأرض '),
(1911, '1 Kings', 11, 9, 19, ' وجميع مدن المخازن التي كانت لسليمان ، ومدن المركبات ومدن الفرسان ، ومرغوب سليمان الذي رغب أن يبنيه في أورشليم وفي لبنان وفي كل أرض سلطنته '),
(1912, '1 Kings', 11, 9, 20, ' جميع الشعب الباقين من الأموريين والحثيين والفرزيين والحويين واليبوسيين الذين ليسوا من بني إسرائيل '),
(1913, '1 Kings', 11, 9, 21, ' أبناؤهم الذين بقوا بعدهم في الأرض ، الذين لم يقدر بنو إسرائيل أن يحرموهم ، جعل عليهم سليمان تسخير عبيد إلى هذا اليوم '),
(1914, '1 Kings', 11, 9, 22, ' وأما بنو إسرائيل فلم يجعل سليمان منهم عبيدا لأنهم رجال القتال وخدامه وأمراؤه وثوالثه ورؤساء مركباته وفرسانه '),
(1915, '1 Kings', 11, 9, 23, ' هؤلاء رؤساء الموكلين على أعمال سليمان خمس مئة وخمسون ، الذين كانوا يتسلطون على الشعب العاملين العمل '),
(1916, '1 Kings', 11, 9, 24, ' ولكن بنت فرعون صعدت من مدينة داود إلى بيتها الذي بناه لها ، حينئذ بنى القلعة '),
(1917, '1 Kings', 11, 9, 25, ' وكان سليمان يصعد ثلاث مرات في السنة محرقات وذبائح سلامة على المذبح الذي بناه للرب ، وكان يوقد على الذي أمام الرب . وأكمل البيت '),
(1918, '1 Kings', 11, 9, 26, ' وعمل الملك سليمان سفنا في عصيون جابر التي بجانب أيلة على شاطئ بحر سوف في أرض أدوم '),
(1919, '1 Kings', 11, 9, 27, ' فأرسل حيرام في السفن عبيده النواتي العارفين بالبحر مع عبيد سليمان '),
(1920, '1 Kings', 11, 9, 28, ' فأتوا إلى أوفير ، وأخذوا من هناك ذهبا أربع مئة وزنة وعشرين وزنة ، وأتوا بها إلى الملك سليمان '),
(1921, '1 Kings', 11, 10, 1, ' وسمعت ملكة سبا بخبر سليمان لمجد الرب ، فأتت لتمتحنه بمسائل '),
(1922, '1 Kings', 11, 10, 2, ' فأتت إلى أورشليم بموكب عظيم جدا ، بجمال حاملة أطيابا وذهبا كثيرا جدا وحجارة كريمة . وأتت إلى سليمان وكلمته بكل ما كان بقلبها '),
(1923, '1 Kings', 11, 10, 3, ' فأخبرها سليمان بكل كلامها . لم يكن أمر مخفيا عن الملك لم يخبرها به '),
(1924, '1 Kings', 11, 10, 4, ' فلما رأت ملكة سبا كل حكمة سليمان ، والبيت الذي بناه '),
(1925, '1 Kings', 11, 12, 8, ' فترك مشورة الشيوخ التي أشاروا بها عليه واستشار الأحداث الذين نشأوا معه ووقفوا أمامه '),
(1926, '1 Kings', 11, 12, 9, ' وقال لهم : بماذا تشيرون أنتم فنرد جوابا على هذا الشعب الذين كلموني قائلين : خفف من النير الذي جعله علينا أبوك '),
(1927, '1 Kings', 11, 12, 10, ' فكلمه الأحداث الذين نشأوا معه قائلين : هكذا تقول لهذا الشعب الذين كلموك قائلين : إن أباك ثقل نيرنا وأما أنت فخفف من نيرنا ، هكذا تقول لهم : إن خنصري أغلظ من متني أبي '),
(1928, '1 Kings', 11, 12, 11, ' والآن أبي حملكم نيرا ثقيلا وأنا أزيد على نيركم . أبي أدبكم بالسياط وأنا أؤدبكم بالعقارب '),
(1929, '1 Kings', 11, 12, 12, ' فجاء يربعام وجميع الشعب إلى رحبعام في اليوم الثالث كما تكلم الملك قائلا : ارجعوا إلي في اليوم الثالث '),
(1930, '1 Kings', 11, 12, 13, ' فأجاب الملك الشعب بقساوة ، وترك مشورة الشيوخ التي أشاروا بها عليه '),
(1931, '1 Kings', 11, 12, 14, ' وكلمهم حسب مشورة الأحداث قائلا : أبي ثقل نيركم وأنا أزيد على نيركم . أبي أدبكم بالسياط وأنا أؤدبكم بالعقارب '),
(1932, '1 Kings', 11, 12, 15, ' ولم يسمع الملك للشعب ، لأن السبب كان من قبل الرب ليقيم كلامه الذي تكلم به الرب عن يد أخيا الشيلوني إلى يربعام بن نباط '),
(1933, '1 Kings', 11, 12, 16, ' فلما رأى كل إسرائيل أن الملك لم يسمع لهم ، رد الشعب جوابا على الملك قائلين : أي قسم لنا في داود ؟ ولا نصيب لنا في ابن يسى إلى خيامك يا إسرائيل . الآن انظر إلى بيتك يا داود . وذهب إسرائيل إلى خيامهم '),
(1934, '1 Kings', 11, 12, 17, ' وأما بنو إسرائيل الساكنون في مدن يهوذا فملك عليهم رحبعام '),
(1935, '1 Kings', 11, 12, 18, ' ثم أرسل الملك رحبعام أدورام الذي على التسخير فرجمه جميع إسرائيل بالحجارة فمات . فبادر الملك رحبعام وصعد إلى المركبة ليهرب إلى أورشليم '),
(1936, '1 Kings', 11, 12, 19, ' فعصى إسرائيل على بيت داود إلى هذا اليوم '),
(1937, '1 Kings', 11, 12, 20, ' ولما سمع جميع إسرائيل بأن يربعام قد رجع ، أرسلوا فدعوه إلى الجماعة ، وملكوه على جميع إسرائيل . لم يتبع بيت داود إلا سبط يهوذا وحده '),
(1938, '1 Kings', 11, 12, 21, ' ولما جاء رحبعام إلى أورشليم جمع كل بيت يهوذا وسبط بنيامين ، مئة وثمانين ألف مختار محارب ، ليحاربوا بيت إسرائيل ويردوا المملكة لرحبعام بن سليمان '),
(1939, '1 Kings', 11, 12, 22, ' وكان كلام الله إلى شمعيا رجل الله قائلا '),
(1940, '1 Kings', 11, 12, 23, ' كلم رحبعام بن سليمان ملك يهوذا وكل بيت يهوذا وبنيامين وبقية الشعب قائلا '),
(1941, '1 Kings', 11, 12, 24, ' هكذا قال الرب : لا تصعدوا ولا تحاربوا إخوتكم بني إسرائيل . ارجعوا كل واحد إلى بيته ، لأن من عندي هذا الأمر . فسمعوا لكلام الرب ورجعوا لينطلقوا حسب قول الرب '),
(1942, '1 Kings', 11, 12, 25, ' وبنى يربعام شكيم في جبل أفرايم وسكن بها . ثم خرج من هناك وبنى فنوئيل '),
(1943, '1 Kings', 11, 12, 26, ' وقال يربعام في قلبه : الآن ترجع المملكة إلى بيت داود '),
(1944, '1 Kings', 11, 12, 27, ' إن صعد هذا الشعب ليقربوا ذبائح في بيت الرب في أورشليم ، يرجع قلب هذا الشعب إلى سيدهم ، إلى رحبعام ملك يهوذا ويقتلوني ، ويرجعوا إلى رحبعام ملك يهوذا '),
(1945, '1 Kings', 11, 12, 28, ' فاستشار الملك وعمل عجلي ذهب ، وقال لهم : كثير عليكم أن تصعدوا إلى أورشليم . هوذا آلهتك يا إسرائيل الذين أصعدوك من أرض مصر '),
(1946, '1 Kings', 11, 12, 29, ' ووضع واحدا في بيت إيل ، وجعل الآخر في دان '),
(1947, '1 Kings', 11, 12, 30, ' وكان هذا الأمر خطية . وكان الشعب يذهبون إلى أمام أحدهما حتى إلى دان '),
(1948, '1 Kings', 11, 12, 31, ' وبنى بيت المرتفعات ، وصير كهنة من أطراف الشعب لم يكونوا من بني لاوي '),
(1949, '1 Kings', 11, 12, 32, ' وعمل يربعام عيدا في الشهر الثامن في اليوم الخامس عشر من الشهر ، كالعيد الذي في يهوذا ، وأصعد على المذبح . هكذا فعل في بيت إيل بذبحه للعجلين اللذين عملهما . وأوقف في بيت إيل كهنة المرتفعات التي عملها '),
(1950, '1 Kings', 11, 12, 33, ' وأصعد على المذبح الذي عمل في بيت إيل في اليوم الخامس عشر من الشهر الثامن ، في الشهر الذي ابتدعه من قلبه ، فعمل عيدا لبني إسرائيل ، وصعد على المذبح ليوقد '),
(1951, '1 Kings', 11, 13, 1, ' وإذا برجل الله قد أتى من يهوذا بكلام الرب إلى بيت إيل ، ويربعام واقف لدى المذبح لكي يوقد '),
(1952, '1 Kings', 11, 13, 2, ' فنادى نحو المذبح بكلام الرب وقال : يا مذبح ، يا مذبح ، هكذا قال الرب : هوذا سيولد لبيت داود ابن اسمه يوشيا ، ويذبح عليك كهنة المرتفعات الذين يوقدون عليك ، وتحرق عليك عظام الناس '),
(1953, '1 Kings', 11, 13, 3, ' وأعطى في ذلك اليوم علامة قائلا : هذه هي العلامة التي تكلم بها الرب : هوذا المذبح ينشق ويذرى الرماد الذي عليه '),
(1954, '1 Kings', 11, 13, 4, ' فلما سمع الملك كلام رجل الله الذي نادى نحو المذبح في بيت إيل ، مد يربعام يده عن المذبح قائلا : أمسكوه . فيبست يده التي مدها نحوه ولم يستطع أن يردها إليه '),
(1955, '1 Kings', 11, 13, 5, ' وانشق المذبح وذري الرماد من على المذبح حسب العلامة التي أعطاها رجل الله بكلام الرب '),
(1956, '1 Kings', 11, 13, 6, ' فأجاب الملك وقال لرجل الله : تضرع إلى وجه الرب إلهك وصل من أجلي فترجع يدي إلي . فتضرع رجل الله إلى وجه الرب فرجعت يد الملك إليه وكانت كما في الأول '),
(1957, '1 Kings', 11, 13, 7, ' ثم قال الملك لرجل الله : ادخل معي إلى البيت وتقوت فأعطيك أجرة '),
(1958, '1 Kings', 11, 13, 8, ' فقال رجل الله للملك : لو أعطيتني نصف بيتك لا أدخل معك ولا آكل خبزا ولا أشرب ماء في هذا الموضع '),
(1959, '1 Kings', 11, 13, 9, ' لأني هكذا أوصيت بكلام الرب قائلا : لا تأكل خبزا ولا تشرب ماء ولا ترجع في الطريق الذي ذهبت فيه '),
(1960, '1 Kings', 11, 13, 10, ' فذهب في طريق آخر ، ولم يرجع في الطريق الذي جاء فيه إلى بيت إيل '),
(1961, '1 Kings', 11, 13, 11, ' وكان نبي شيخ ساكنا في بيت إيل ، فأتى بنوه وقصوا عليه كل العمل الذي عمله رجل الله ذلك اليوم في بيت إيل ، وقصوا على أبيهم الكلام الذي تكلم به إلى الملك '),
(1962, '1 Kings', 11, 13, 12, ' فقال لهم أبوهم : من أي طريق ذهب ؟  . وكان بنوه قد رأوا الطريق الذي سار فيه رجل الله الذي جاء من يهوذا '),
(1963, '1 Kings', 11, 13, 13, ' فقال لبنيه : شدوا لي على الحمار . فشدوا له على الحمار فركب عليه '),
(1964, '1 Kings', 11, 13, 14, ' وسار وراء رجل الله ، فوجده جالسا تحت البلوطة ، فقال له : أأنت رجل الله الذي جاء من يهوذا ؟  . فقال : أنا هو '),
(1965, '1 Kings', 11, 13, 15, ' فقال له : سر معي إلى البيت وكل خبزا '),
(1966, '1 Kings', 11, 13, 16, ' فقال : لا أقدر أن أرجع معك ولا أدخل معك ولا آكل خبزا ولا أشرب معك ماء في هذا الموضع '),
(1967, '1 Kings', 11, 13, 17, ' لأنه قيل لي بكلام الرب : لا تأكل خبزا ولا تشرب هناك ماء . ولا ترجع سائرا في الطريق الذي ذهبت فيه '),
(1968, '1 Kings', 11, 13, 18, ' فقال له : أنا أيضا نبي مثلك ، وقد كلمني ملاك بكلام الرب قائلا : ارجع به معك إلى بيتك فيأكل خبزا ويشرب ماء . كذب عليه '),
(1969, '1 Kings', 11, 13, 19, ' فرجع معه وأكل خبزا في بيته وشرب ماء '),
(1970, '1 Kings', 11, 13, 20, ' وبينما هما جالسان على المائدة كان كلام الرب إلى النبي الذي أرجعه '),
(1971, '1 Kings', 11, 13, 21, ' فصاح إلى رجل الله الذي جاء من يهوذا قائلا : هكذا قال الرب : من أجل أنك خالفت قول الرب ولم تحفظ الوصية التي أوصاك بها الرب إلهك '),
(1972, '1 Kings', 11, 13, 22, ' فرجعت وأكلت خبزا وشربت ماء في الموضع الذي قال لك : لا تأكل فيه خبزا ولا تشرب ماء ، لا تدخل جثتك قبر آبائك '),
(1973, '1 Kings', 11, 13, 23, ' ثم بعدما أكل خبزا وبعد أن شرب ، شد له على الحمار ، أي للنبي الذي أرجعه '),
(1974, '1 Kings', 11, 13, 24, ' وانطلق . فصادفه أسد في الطريق وقتله . وكانت جثته مطروحة في الطريق والحمار واقف بجانبها والأسد واقف بجانب الجثة '),
(1975, '1 Kings', 11, 13, 25, ' وإذا بقوم يعبرون فرأوا الجثة ، مطروحة في الطريق والأسد واقف بجانب الجثة . فأتوا وأخبروا في المدينة التي كان النبي الشيخ ساكنا بها '),
(1976, '1 Kings', 11, 13, 26, ' ولما سمع النبي الذي أرجعه عن الطريق قال : هو رجل الله الذي خالف قول الرب ، فدفعه الرب للأسد فافترسه وقتله حسب كلام الرب الذي كلمه به '),
(1977, '1 Kings', 11, 13, 27, ' وكلم بنيه قائلا : شدوا لي على الحمار . فشدوا '),
(1978, '1 Kings', 11, 13, 28, ' فذهب ووجد جثته مطروحة في الطريق ، والحمار والأسد واقفين بجانب الجثة ، ولم يأكل الأسد الجثة ولا افترس الحمار '),
(1979, '1 Kings', 11, 13, 29, ' فرفع النبي جثة رجل الله ووضعها على الحمار ورجع بها ، ودخل النبي الشيخ المدينة ليندبه ويدفنه '),
(1980, '1 Kings', 11, 13, 30, ' فوضع جثته في قبره وناحوا عليه قائلين : آه يا أخي '),
(1981, '1 Kings', 11, 13, 31, ' وبعد دفنه إياه كلم بنيه قائلا : عند وفاتي ادفنوني في القبر الذي دفن فيه رجل الله . بجانب عظامه ضعوا عظامي '),
(1982, '1 Kings', 11, 13, 32, ' لأنه تماما سيتم الكلام الذي نادى به بكلام الرب نحو المذبح الذي في بيت إيل ، ونحو جميع بيوت المرتفعات التي في مدن السامرة '),
(1983, '1 Kings', 11, 13, 33, ' بعد هذا الأمر لم يرجع يربعام عن طريقه الردية ، بل عاد فعمل من أطراف الشعب كهنة مرتفعات . من شاء ملأ يده فصار من كهنة المرتفعات '),
(1984, '1 Kings', 11, 13, 34, ' وكان من هذا الأمر خطية لبيت يربعام ، وكان لإبادته وخرابه عن وجه الأرض '),
(1985, '1 Kings', 11, 14, 1, ' في ذلك الزمان مرض أبيا بن يربعام '),
(1986, '1 Kings', 11, 14, 2, ' فقال يربعام لامرأته : قومي غيري شكلك حتى لا يعلموا أنك امرأة يربعام واذهبي إلى شيلوه . هوذا هناك أخيا النبي الذي قال عني : إني أملك على هذا الشعب '),
(1987, '1 Kings', 11, 14, 3, ' وخذي بيدك عشرة أرغفة وكعكا وجرة عسل ، وسيري إليه وهو يخبرك ماذا يكون للغلام '),
(1988, '1 Kings', 11, 14, 4, ' ففعلت امرأة يربعام هكذا ، وقامت وذهبت إلى شيلوه ودخلت بيت أخيا . وكان أخيا لا يقدر أن يبصر لأنه قد قامت عيناه بسبب شيخوخته '),
(1989, '1 Kings', 11, 14, 5, ' وقال الرب لأخيا : هوذا امرأة يربعام آتية لتسأل منك شيئا من جهة ابنها لأنه مريض . فقل لها : كذا وكذا ، فإنها عند دخولها تتنكر '),
(1990, '1 Kings', 11, 14, 6, ' فلما سمع أخيا حس رجليها وهي داخلة في الباب قال : ادخلي يا امرأة يربعام . لماذا تتنكرين وأنا مرسل إليك بقول قاس '),
(1991, '1 Kings', 11, 14, 7, ' اذهبي قولي ليربعام : هكذا قال الرب إله إسرائيل : من أجل أني قد رفعتك من وسط الشعب وجعلتك رئيسا على شعبي إسرائيل '),
(1992, '1 Kings', 11, 14, 8, ' وشققت المملكة من بيت داود وأعطيتك إياها ، ولم تكن كعبدي داود الذي حفظ وصاياي والذي سار ورائي بكل قلبه ليفعل ما هو مستقيم فقط في عيني '),
(1993, '1 Kings', 11, 14, 9, ' وقد ساء عملك أكثر من جميع الذين كانوا قبلك ، فسرت وعملت لنفسك آلهة أخرى ومسبوكات لتغيظني ، وقد طرحتني وراء ظهرك '),
(1994, '1 Kings', 11, 14, 10, ' لذلك هأنذا جالب شرا على بيت يربعام ، وأقطع ليربعام كل بائل بحائط محجوزا ومطلقا في إسرائيل ، وأنزع آخر بيت يربعام كما ينزع البعر حتى يفنى '),
(1995, '1 Kings', 11, 14, 11, ' من مات ليربعام في المدينة تأكله الكلاب ، ومن مات في الحقل تأكله طيور السماء ، لأن الرب تكلم '),
(1996, '1 Kings', 11, 14, 12, ' وأنت فقومي وانطلقي إلى بيتك ، وعند دخول رجليك المدينة يموت الولد '),
(1997, '1 Kings', 11, 14, 13, ' ويندبه جميع إسرائيل ويدفنونه ، لأن هذا وحده من يربعام يدخل القبر ، لأنه وجد فيه أمر صالح نحو الرب إله إسرائيل في بيت يربعام '),
(1998, '1 Kings', 11, 14, 14, ' ويقيم الرب لنفسه ملكا على إسرائيل يقرض بيت يربعام هذا اليوم . وماذا ؟ الآن أيضا '),
(1999, '1 Kings', 11, 14, 15, ' ويضرب الرب إسرائيل كاهتزاز القصب في الماء ، ويستأصل إسرائيل عن هذه الأرض الصالحة التي أعطاها لآبائهم ، ويبددهم إلى عبر النهر لأنهم عملوا سواريهم وأغاظوا الرب '),
(2000, '1 Kings', 11, 14, 16, ' ويدفع إسرائيل من أجل خطايا يربعام الذي أخطأ وجعل إسرائيل يخطئ '),
(2001, '1 Kings', 11, 14, 17, ' فقامت امرأة يربعام وذهبت وجاءت إلى ترصة ، ولما وصلت إلى عتبة الباب مات الغلام '),
(2002, '1 Kings', 11, 14, 18, ' فدفنه وندبه جميع إسرائيل حسب كلام الرب الذي تكلم به عن يد عبده أخيا النبي '),
(2003, '1 Kings', 11, 14, 19, ' وأما بقية أمور يربعام ، كيف حارب وكيف ملك ، فإنها مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(2004, '1 Kings', 11, 14, 20, ' والزمان الذي ملك فيه يربعام هو اثنتان وعشرون سنة ، ثم اضطجع مع آبائه ، وملك ناداب ابنه عوضا عنه '),
(2005, '1 Kings', 11, 14, 21, ' وأما رحبعام بن سليمان فملك في يهوذا . وكان رحبعام ابن إحدى وأربعين سنة حين ملك ، وملك سبع عشرة سنة في أورشليم ، المدينة التي اختارها الرب لوضع اسمه فيها من جميع أسباط إسرائيل ، واسم أمه نعمة العمونية '),
(2006, '1 Kings', 11, 14, 22, ' وعمل يهوذا الشر في عيني الرب وأغاروه أكثر من جميع ما عمل آباؤهم بخطاياهم التي أخطأوا بها '),
(2007, '1 Kings', 11, 14, 23, ' وبنوا هم أيضا لأنفسهم مرتفعات وأنصابا وسواري على كل تل مرتفع وتحت كل شجرة خضراء '),
(2008, '1 Kings', 11, 14, 24, ' وكان أيضا مأبونون في الأرض ، فعلوا حسب كل أرجاس الأمم الذين طردهم الرب من أمام بني إسرائيل '),
(2009, '1 Kings', 11, 14, 25, ' وفي السنة الخامسة للملك رحبعام ، صعد شيشق ملك مصر إلى أورشليم '),
(2010, '1 Kings', 11, 14, 26, ' وأخذ خزائن بيت الرب وخزائن بيت الملك ، وأخذ كل شيء . وأخذ جميع أتراس الذهب التي عملها سليمان '),
(2011, '1 Kings', 11, 14, 27, ' فعمل الملك رحبعام عوضا عنها أتراس نحاس وسلمها ليد رؤساء السعاة الحافظين باب بيت الملك '),
(2012, '1 Kings', 11, 14, 28, ' وكان إذا دخل الملك بيت الرب يحملها السعاة ، ثم يرجعونها إلى غرفة السعاة '),
(2013, '1 Kings', 11, 14, 29, ' وبقية أمور رحبعام وكل ما فعل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(2014, '1 Kings', 11, 14, 30, ' وكانت حرب بين رحبعام ويربعام كل الأيام '),
(2015, '1 Kings', 11, 14, 31, ' ثم اضطجع رحبعام مع آبائه ، ودفن مع آبائه في مدينة داود . واسم أمه نعمة العمونية . وملك أبيام ابنه عوضا عنه '),
(2016, '1 Kings', 11, 15, 1, ' وفي السنة الثامنة عشرة للملك يربعام بن نباط ، ملك أبيام على يهوذا '),
(2017, '1 Kings', 11, 15, 2, ' ملك ثلاث سنين في أورشليم ، واسم أمه معكة ابنة أبشالوم '),
(2018, '1 Kings', 11, 15, 3, ' وسار في جميع خطايا أبيه التي عملها قبله ، ولم يكن قلبه كاملا مع الرب إلهه كقلب داود أبيه '),
(2019, '1 Kings', 11, 15, 4, ' ولكن لأجل داود أعطاه الرب إلهه سراجا في أورشليم ، إذ أقام ابنه بعده وثبت أورشليم '),
(2020, '1 Kings', 11, 15, 5, ' لأن داود عمل ما هو مستقيم في عيني الرب ولم يحد عن شيء مما أوصاه به كل أيام حياته ، إلا في قضية أوريا الحثي '),
(2021, '1 Kings', 11, 15, 6, ' وكانت حرب بين رحبعام ويربعام كل أيام حياته '),
(2022, '1 Kings', 11, 15, 7, ' وبقية أمور أبيام وكل ما عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا ؟ وكانت حرب بين أبيام ويربعام '),
(2023, '1 Kings', 11, 15, 8, ' ثم اضطجع أبيام مع آبائه ، فدفنوه في مدينة داود ، وملك آسا ابنه عوضا عنه '),
(2024, '1 Kings', 11, 15, 9, ' وفي السنة العشرين ليربعام ملك إسرائيل ، ملك آسا على يهوذا '),
(2025, '1 Kings', 11, 15, 10, ' ملك إحدى وأربعين سنة في أورشليم ، واسم أمه معكة ابنة أبشالوم '),
(2026, '1 Kings', 11, 15, 11, ' وعمل آسا ما هو مستقيم في عيني الرب كداود أبيه '),
(2027, '1 Kings', 11, 15, 12, ' وأزال المأبونين من الأرض ، ونزع جميع الأصنام التي عملها آباؤه '),
(2028, '1 Kings', 11, 15, 13, ' حتى إن معكة أمه خلعها من أن تكون ملكة ، لأنها عملت تمثالا لسارية ، وقطع آسا تمثالها وأحرقه في وادي قدرون '),
(2029, '1 Kings', 11, 15, 14, ' وأما المرتفعات فلم تنزع ، إلا إن قلب آسا كان كاملا مع الرب كل أيامه '),
(2030, '1 Kings', 11, 15, 15, ' وأدخل أقداس أبيه وأقداسه إلى بيت الرب من الفضة والذهب والآنية '),
(2031, '1 Kings', 11, 15, 16, ' وكانت حرب بين آسا وبعشا ملك إسرائيل كل أيامهما '),
(2032, '1 Kings', 11, 15, 17, ' وصعد بعشا ملك إسرائيل على يهوذا وبنى الرامة لكي لا يدع أحدا يخرج أو يدخل إلى آسا ملك يهوذا '),
(2033, '1 Kings', 11, 15, 18, ' وأخذ آسا جميع الفضة والذهب الباقية في خزائن بيت الرب وخزائن بيت الملك ودفعها ليد عبيده ، وأرسلهم الملك آسا إلى بنهدد بن طبريمون بن حزيون ملك أرام الساكن في دمشق قائلا '),
(2034, '1 Kings', 11, 15, 19, ' إن بيني وبينك وبين أبي وأبيك عهدا . هوذا قد أرسلت لك هدية من فضة وذهب ، فتعال انقض عهدك مع بعشا ملك إسرائيل فيصعد عني '),
(2035, '1 Kings', 11, 15, 20, ' فسمع بنهدد للملك آسا وأرسل رؤساء الجيوش التي له على مدن إسرائيل ، وضرب عيون ودان وآبل بيت معكة وكل كنروت مع كل أرض نفتالي '),
(2036, '1 Kings', 11, 15, 21, ' ولما سمع بعشا كف عن بناء الرامة وأقام في ترصة '),
(2037, '1 Kings', 11, 15, 22, ' فاستدعى الملك آسا كل يهوذا . لم يكن بريء . فحملوا كل حجارة الرامة وأخشابها التي بناها بعشا ، وبنى بها الملك آسا جبع بنيامين والمصفاة '),
(2038, '1 Kings', 11, 15, 23, ' وبقية كل أمور آسا وكل جبروته وكل ما فعل والمدن التي بناها ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا ؟ غير أنه في زمان شيخوخته مرض في رجليه '),
(2039, '1 Kings', 11, 15, 24, ' ثم اضطجع آسا مع آبائه ، ودفن مع آبائه في مدينة داود أبيه ، وملك يهوشافاط ابنه عوضا عنه '),
(2040, '1 Kings', 11, 15, 25, ' وملك ناداب بن يربعام على إسرائيل في السنة الثانية لآسا ملك يهوذا ، فملك على إسرائيل سنتين '),
(2041, '1 Kings', 11, 15, 26, ' وعمل الشر في عيني الرب ، وسار في طريق أبيه وفي خطيته التي جعل بها إسرائيل يخطئ '),
(2042, '1 Kings', 11, 15, 27, ' وفتن عليه بعشا بن أخيا من بيت يساكر ، وضربه بعشا في جبثون التي للفلسطينيين . وكان ناداب وكل إسرائيل محاصرين جبثون '),
(2043, '1 Kings', 11, 15, 28, ' وأماته بعشا في السنة الثالثة لآسا ملك يهوذا وملك عوضا عنه '),
(2044, '1 Kings', 11, 15, 29, ' ولما ملك ضرب كل بيت يربعام . لم يبق نسمة ليربعام حتى أفناهم ، حسب كلام الرب الذي تكلم به عن يد عبده أخيا الشيلوني '),
(2045, '1 Kings', 11, 15, 30, ' لأجل خطايا يربعام التي أخطأها والتي جعل بها إسرائيل يخطئ بإغاظته التي أغاظ بها الرب إله إسرائيل '),
(2046, '1 Kings', 11, 15, 31, ' وبقية أمور ناداب وكل ما عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(2047, '1 Kings', 11, 15, 32, ' وكانت حرب بين آسا وبعشا ملك إسرائيل كل أيامهما '),
(2048, '1 Kings', 11, 16, 33, ' وعمل أخآب سواري ، وزاد أخآب في العمل لإغاظة الرب إله إسرائيل أكثر من جميع ملوك إسرائيل الذين كانوا قبله '),
(2049, '1 Kings', 11, 16, 34, ' في أيامه بنى حيئيل البيتئيلي أريحا . بأبيرام بكره وضع أساسها ، وبسجوب صغيره نصب أبوابها ، حسب كلام الرب الذي تكلم به عن يد يشوع بن نون '),
(2050, '1 Kings', 11, 17, 1, ' وقال إيليا التشبي من مستوطني جلعاد لأخآب : حي هو الرب إله إسرائيل الذي وقفت أمامه ، إنه لا يكون طل ولا مطر في هذه السنين إلا عند قولي '),
(2051, '1 Kings', 11, 17, 2, ' وكان كلام الرب له قائلا '),
(2052, '1 Kings', 11, 17, 3, ' انطلق من هنا واتجه نحو المشرق ، واختبئ عند نهر كريث الذي هو مقابل الأردن '),
(2053, '1 Kings', 11, 17, 4, ' فتشرب من النهر . وقد أمرت الغربان أن تعولك هناك '),
(2054, '1 Kings', 11, 17, 5, ' فانطلق وعمل حسب كلام الرب ، وذهب فأقام عند نهر كريث الذي هو مقابل الأردن '),
(2055, '1 Kings', 11, 17, 6, ' وكانت الغربان تأتي إليه بخبز ولحم صباحا ، وبخبز ولحم مساء ، وكان يشرب من النهر '),
(2056, '1 Kings', 11, 17, 7, ' وكان بعد مدة من الزمان أن النهر يبس ، لأنه لم يكن مطر في الأرض '),
(2057, '1 Kings', 11, 17, 8, ' وكان له كلام الرب قائلا '),
(2058, '1 Kings', 11, 17, 9, ' قم اذهب إلى صرفة التي لصيدون وأقم هناك . هوذا قد أمرت هناك امرأة أرملة أن تعولك '),
(2059, '1 Kings', 11, 17, 10, ' فقام وذهب إلى صرفة . وجاء إلى باب المدينة ، وإذا بامرأة أرملة هناك تقش عيدانا ، فناداها وقال : هاتي لي قليل ماء في إناء فأشرب '),
(2060, '1 Kings', 11, 17, 11, ' وفيما هي ذاهبة لتأتي به ، ناداها وقال : هاتي لي كسرة خبز في يدك '),
(2061, '1 Kings', 11, 17, 12, ' فقالت : حي هو الرب إلهك ، إنه ليست عندي كعكة ، ولكن ملء كف من الدقيق في الكوار ، وقليل من الزيت في الكوز ، وهأنذا أقش عودين لآتي وأعمله لي ولابني لنأكله ثم نموت '),
(2062, '1 Kings', 11, 17, 13, ' فقال لها إيليا : لا تخافي . ادخلي واعملي كقولك ، ولكن اعملي لي منها كعكة صغيرة أولا واخرجي بها إلي ، ثم اعملي لك ولابنك أخيرا '),
(2063, '1 Kings', 11, 17, 14, ' لأنه هكذا قال الرب إله إسرائيل : إن كوار الدقيق لا يفرغ ، وكوز الزيت لا ينقص ، إلى اليوم الذي فيه يعطي الرب مطرا على وجه الأرض '),
(2064, '1 Kings', 11, 17, 15, ' فذهبت وفعلت حسب قول إيليا ، وأكلت هي وهو وبيتها أياما '),
(2065, '1 Kings', 11, 17, 16, ' كوار الدقيق لم يفرغ ، وكوز الزيت لم ينقص ، حسب قول الرب الذي تكلم به عن يد إيليا '),
(2066, '1 Kings', 11, 17, 17, ' وبعد هذه الأمور مرض ابن المرأة صاحبة البيت واشتد مرضه جدا حتى لم تبق فيه نسمة '),
(2067, '1 Kings', 11, 17, 18, ' فقالت لإيليا : ما لي ولك يا رجل الله هل جئت إلي لتذكير إثمي وإماتة ابني '),
(2068, '1 Kings', 11, 17, 19, ' فقال لها : أعطيني ابنك . وأخذه من حضنها وصعد به إلى العلية التي كان مقيما بها ، وأضجعه على سريره '),
(2069, '1 Kings', 11, 17, 20, ' وصرخ إلى الرب وقال : أيها الرب إلهي ، أأيضا إلى الأرملة التي أنا نازل عندها قد أسأت بإماتتك ابنها '),
(2070, '1 Kings', 11, 17, 21, ' فتمدد على الولد ثلاث مرات ، وصرخ إلى الرب وقال : يارب إلهي ، لترجع نفس هذا الولد إلى جوفه '),
(2071, '1 Kings', 11, 17, 22, ' فسمع الرب لصوت إيليا ، فرجعت نفس الولد إلى جوفه فعاش '),
(2072, '1 Kings', 11, 17, 23, ' فأخذ إيليا الولد ونزل به من العلية إلى البيت ودفعه لأمه ، وقال إيليا : انظري ، ابنك حي '),
(2073, '1 Kings', 11, 17, 24, ' فقالت المرأة لإيليا : هذا الوقت علمت أنك رجل الله ، وأن كلام الرب في فمك حق '),
(2074, '1 Kings', 11, 18, 1, ' وبعد أيام كثيرة كان كلام الرب إلى إيليا في السنة الثالثة قائلا : اذهب وتراء لأخآب فأعطي مطرا على وجه الأرض '),
(2075, '1 Kings', 11, 18, 2, ' فذهب إيليا ليتراءى لأخآب . وكان الجوع شديدا في السامرة '),
(2076, '1 Kings', 11, 18, 3, ' فدعا أخآب عوبديا الذي على البيت ، وكان عوبديا يخشى الرب جدا '),
(2077, '1 Kings', 11, 18, 4, ' وكان حينما قطعت إيزابل أنبياء الرب أن عوبديا أخذ مئة نبي وخبأهم خمسين رجلا في مغارة وعالهم بخبز وماء '),
(2078, '1 Kings', 11, 18, 5, ' وقال أخآب لعوبديا : اذهب في الأرض إلى جميع عيون الماء وإلى جميع الأودية ، لعلنا نجد عشبا فنحيي الخيل والبغال ولا نعدم البهائم كلها '),
(2079, '1 Kings', 11, 18, 6, ' فقسما بينهما الأرض ليعبرا بها . فذهب أخآب في طريق واحد وحده ، وذهب عوبديا في طريق آخر وحده '),
(2080, '1 Kings', 11, 18, 7, ' وفيما كان عوبديا في الطريق ، إذا بإيليا قد لقيه فعرفه ، وخر على وجهه وقال : أأنت هو سيدي إيليا '),
(2081, '1 Kings', 11, 18, 8, ' فقال له : أنا هو . اذهب وقل لسيدك : هوذا إيليا '),
(2082, '1 Kings', 11, 18, 9, ' فقال : ما هي خطيتي حتى إنك تدفع عبدك ليد أخآب ليميتني '),
(2083, '1 Kings', 11, 18, 10, ' حي هو الرب إلهك ، إنه لا توجد أمة ولا مملكة لم يرسل سيدي إليها ليفتش عليك ، وكانوا يقولون : إنه لا يوجد . وكان يستحلف المملكة والأمة أنهم لم يجدوك '),
(2084, '1 Kings', 11, 18, 11, ' والآن أنت تقول : اذهب قل لسيدك : هوذا إيليا '),
(2085, '1 Kings', 11, 18, 12, ' ويكون إذا انطلقت من عندك ، أن روح الرب يحملك إلى حيث لا أعلم . فإذا أتيت وأخبرت أخآب ولم يجدك فإنه يقتلني ، وأنا عبدك أخشى الرب منذ صباي '),
(2086, '1 Kings', 11, 18, 13, ' ألم يخبر سيدي بما فعلت حين قتلت إيزابل أنبياء الرب ، إذ خبأت من أنبياء الرب مئة رجل ، خمسين خمسين رجلا في مغارة وعلتهم بخبز وماء '),
(2087, '1 Kings', 11, 18, 14, ' وأنت الآن تقول : اذهب قل لسيدك : هوذا إيليا ، فيقتلني '),
(2088, '1 Kings', 11, 18, 15, ' فقال إيليا : حي هو رب الجنود الذي أنا واقف أمامه ، إني اليوم أتراءى له '),
(2089, '1 Kings', 11, 18, 16, ' فذهب عوبديا للقاء أخآب وأخبره ، فسار أخآب للقاء إيليا '),
(2090, '1 Kings', 11, 18, 17, ' ولما رأى أخآب إيليا قال له أخآب : أأنت هو مكدر إسرائيل '),
(2091, '1 Kings', 11, 18, 18, ' فقال : لم أكدر إسرائيل ، بل أنت وبيت أبيك بترككم وصايا الرب وبسيرك وراء البعليم '),
(2092, '1 Kings', 11, 18, 19, ' فالآن أرسل واجمع إلي كل إسرائيل إلى جبل الكرمل ، وأنبياء البعل أربع المئة والخمسين ، وأنبياء السواري أربع المئة ، الذين يأكلون على مائدة إيزابل '),
(2093, '1 Kings', 11, 18, 20, ' فأرسل أخآب إلى جميع بني إسرائيل ، وجمع الأنبياء إلى جبل الكرمل '),
(2094, '1 Kings', 11, 18, 21, ' فتقدم إيليا إلى جميع الشعب وقال : حتى متى تعرجون بين الفرقتين ؟ إن كان الرب هو الله فاتبعوه ، وإن كان البعل فاتبعوه . فلم يجبه الشعب بكلمة '),
(2095, '1 Kings', 11, 18, 22, ' ثم قال إيليا للشعب : أنا بقيت نبيا للرب وحدي ، وأنبياء البعل أربع مئة وخمسون رجلا '),
(2096, '1 Kings', 11, 18, 23, ' فليعطونا ثورين ، فيختاروا لأنفسهم ثورا واحدا ويقطعوه ويضعوه على الحطب ، ولكن لا يضعوا نارا . وأنا أقرب الثور الآخر وأجعله على الحطب ، ولكن لا أضع نارا '),
(2097, '1 Kings', 11, 18, 24, ' ثم تدعون باسم آلهتكم وأنا أدعو باسم الرب . والإله الذي يجيب بنار فهو الله . فأجاب جميع الشعب وقالوا : الكلام حسن '),
(2098, '1 Kings', 11, 18, 25, ' فقال إيليا لأنبياء البعل : اختاروا لأنفسكم ثورا واحدا وقربوا أولا ، لأنكم أنتم الأكثر ، وادعوا باسم آلهتكم ، ولكن لا تضعوا نارا '),
(2099, '1 Kings', 11, 18, 26, ' فأخذوا الثور الذي أعطي لهم وقربوه ، ودعوا باسم البعل من الصباح إلى الظهر قائلين : يا بعل أجبنا . فلم يكن صوت ولا مجيب . وكانوا يرقصون حول المذبح الذي عمل '),
(2100, '1 Kings', 11, 18, 27, ' وعند الظهر سخر بهم إيليا وقال : ادعوا بصوت عال لأنه إله لعله مستغرق أو في خلوة أو في سفر أو لعله نائم فيتنبه '),
(2101, '1 Kings', 11, 18, 28, ' فصرخوا بصوت عال ، وتقطعوا حسب عادتهم بالسيوف والرماح حتى سال منهم الدم '),
(2102, '1 Kings', 11, 18, 29, ' ولما جاز الظهر ، وتنبأوا إلى حين إصعاد التقدمة ، ولم يكن صوت ولا مجيب ولا مصغ '),
(2103, '1 Kings', 11, 18, 30, ' قال إيليا لجميع الشعب : تقدموا إلي . فتقدم جميع الشعب إليه . فرمم مذبح الرب المنهدم '),
(2104, '1 Kings', 11, 18, 31, ' ثم أخذ إيليا اثني عشر حجرا ، بعدد أسباط بني يعقوب ، الذي كان كلام الرب إليه قائلا : إسرائيل يكون اسمك '),
(2105, '1 Kings', 11, 18, 32, ' وبنى الحجارة مذبحا باسم الرب ، وعمل قناة حول المذبح تسع كيلتين من البزر '),
(2106, '1 Kings', 11, 18, 33, ' ثم رتب الحطب وقطع الثور ووضعه على الحطب ، وقال : املأوا أربع جرات ماء وصبوا على المحرقة وعلى الحطب '),
(2107, '1 Kings', 11, 18, 34, ' ثم قال : ثنوا فثنوا . وقال : ثلثوا فثلثوا '),
(2108, '1 Kings', 11, 18, 35, ' فجرى الماء حول المذبح وامتلأت القناة أيضا ماء '),
(2109, '1 Kings', 11, 18, 36, ' وكان عند إصعاد التقدمة أن إيليا النبي تقدم وقال : أيها الرب إله إبراهيم وإسحاق وإسرائيل ، ليعلم اليوم أنك أنت الله في إسرائيل ، وأني أنا عبدك ، وبأمرك قد فعلت كل هذه الأمور '),
(2110, '1 Kings', 11, 18, 37, ' استجبني يارب ، استجبني ، ليعلم هذا الشعب أنك أنت الرب الإله ، وأنك أنت حولت قلوبهم رجوعا '),
(2111, '1 Kings', 11, 18, 38, ' فسقطت نار الرب وأكلت المحرقة والحطب والحجارة والتراب ، ولحست المياه التي في القناة '),
(2112, '1 Kings', 11, 18, 39, ' فلما رأى جميع الشعب ذلك سقطوا على وجوههم وقالوا : الرب هو الله الرب هو الله '),
(2113, '1 Kings', 11, 18, 40, ' فقال لهم إيليا : أمسكوا أنبياء البعل ولا يفلت منهم رجل . فأمسكوهم ، فنزل بهم إيليا إلى نهر قيشون وذبحهم هناك '),
(2114, '1 Kings', 11, 18, 41, ' وقال إيليا لأخآب : اصعد كل واشرب ، لأنه حس دوي مطر '),
(2115, '1 Kings', 11, 18, 42, ' فصعد أخآب ليأكل ويشرب ، وأما إيليا فصعد إلى رأس الكرمل وخر إلى الأرض ، وجعل وجهه بين ركبتيه '),
(2116, '1 Kings', 11, 18, 43, ' وقال لغلامه : اصعد تطلع نحو البحر . فصعد وتطلع وقال : ليس شيء . فقال : ارجع سبع مرات '),
(2117, '1 Kings', 11, 18, 44, ' وفي المرة السابعة قال : هوذا غيمة صغيرة قدر كف إنسان صاعدة من البحر . فقال : اصعد قل لأخآب : اشدد وانزل لئلا يمنعك المطر '),
(2118, '1 Kings', 11, 18, 45, ' وكان من هنا إلى هنا أن السماء اسودت من الغيم والريح ، وكان مطر عظيم . فركب أخآب ومضى إلى يزرعيل '),
(2119, '1 Kings', 11, 18, 46, ' وكانت يد الرب على إيليا ، فشد حقويه وركض أمام أخآب حتى تجيء إلى يزرعيل '),
(2120, '1 Kings', 11, 19, 1, ' وأخبر أخآب إيزابل بكل ما عمل إيليا ، وكيف أنه قتل جميع الأنبياء بالسيف '),
(2121, '1 Kings', 11, 19, 2, ' فأرسلت إيزابل رسولا إلى إيليا تقول : هكذا تفعل الآلهة وهكذا تزيد ، إن لم أجعل نفسك كنفس واحد منهم في نحو هذا الوقت غدا '),
(2122, '1 Kings', 11, 19, 3, ' فلما رأى ذلك قام ومضى لأجل نفسه ، وأتى إلى بئر سبع التي ليهوذا وترك غلامه هناك '),
(2123, '1 Kings', 11, 19, 4, ' ثم سار في البرية مسيرة يوم ، حتى أتى وجلس تحت رتمة وطلب الموت لنفسه ، وقال : قد كفى الآن يارب . خذ نفسي لأنني لست خيرا من آبائي '),
(2124, '1 Kings', 11, 19, 5, ' واضطجع ونام تحت الرتمة . وإذا بملاك قد مسه وقال : قم وكل '),
(2125, '1 Kings', 11, 19, 6, ' فتطلع وإذا كعكة رضف وكوز ماء عند رأسه ، فأكل وشرب ثم رجع فاضطجع '),
(2126, '1 Kings', 11, 19, 7, ' ثم عاد ملاك الرب ثانية فمسه وقال : قم وكل ، لأن المسافة كثيرة عليك '),
(2127, '1 Kings', 11, 19, 8, ' فقام وأكل وشرب ، وسار بقوة تلك الأكلة أربعين نهارا وأربعين ليلة إلى جبل الله حوريب '),
(2128, '1 Kings', 11, 19, 9, ' ودخل هناك المغارة وبات فيها . وكان كلام الرب إليه يقول : ما لك ههنا يا إيليا '),
(2129, '1 Kings', 11, 19, 10, ' فقال : قد غرت غيرة للرب إله الجنود ، لأن بني إسرائيل قد تركوا عهدك ، ونقضوا مذابحك ، وقتلوا أنبياءك بالسيف ، فبقيت أنا وحدي ، وهم يطلبون نفسي ليأخذوها '),
(2130, '1 Kings', 11, 19, 11, ' فقال : اخرج وقف على الجبل أمام الرب . وإذا بالرب عابر وريح عظيمة وشديدة قد شقت الجبال وكسرت الصخور أمام الرب ، ولم يكن الرب في الريح . وبعد الريح زلزلة ، ولم يكن الرب في الزلزلة '),
(2131, '1 Kings', 11, 19, 12, ' وبعد الزلزلة نار ، ولم يكن الرب في النار . وبعد النار صوت منخفض خفيف '),
(2132, '1 Kings', 11, 19, 13, ' فلما سمع إيليا لف وجهه بردائه وخرج ووقف في باب المغارة ، وإذا بصوت إليه يقول : ما لك ههنا يا إيليا '),
(2133, '1 Kings', 11, 19, 14, ' فقال : غرت غيرة للرب إله الجنود ، لأن بني إسرائيل قد تركوا عهدك ، ونقضوا مذابحك ، وقتلوا أنبياءك بالسيف ، فبقيت أنا وحدي ، وهم يطلبون نفسي ليأخذوها '),
(2134, '1 Kings', 11, 19, 15, ' فقال له الرب : اذهب راجعا في طريقك إلى برية دمشق ، وادخل وامسح حزائيل ملكا على أرام '),
(2135, '1 Kings', 11, 19, 16, ' وامسح ياهو بن نمشي ملكا على إسرائيل ، وامسح أليشع بن شافاط من آبل محولة نبيا عوضا عنك '),
(2136, '1 Kings', 11, 19, 17, ' فالذي ينجو من سيف حزائيل يقتله ياهو ، والذي ينجو من سيف ياهو يقتله أليشع '),
(2137, '1 Kings', 11, 19, 18, ' وقد أبقيت في إسرائيل سبعة آلاف ، كل الركب التي لم تجث للبعل وكل فم لم يقبله '),
(2138, '1 Kings', 11, 19, 19, ' فذهب من هناك ووجد أليشع بن شافاط يحرث ، واثنا عشر فدان بقر قدامه ، وهو مع الثاني عشر . فمر إيليا به وطرح رداءه عليه '),
(2139, '1 Kings', 11, 19, 20, ' فترك البقر وركض وراء إيليا وقال : دعني أقبل أبي وأمي وأسير وراءك . فقال له : اذهب راجعا ، لأني ماذا فعلت لك '),
(2140, '1 Kings', 11, 19, 21, ' فرجع من ورائه وأخذ فدان بقر وذبحهما ، وسلق اللحم بأدوات البقر وأعطى الشعب فأكلوا . ثم قام ومضى وراء إيليا وكان يخدمه '),
(2141, '1 Kings', 11, 20, 1, ' وجمع بنهدد ملك أرام كل جيشه ، واثنين وثلاثين ملكا معه ، وخيلا ومركبات وصعد وحاصر السامرة وحاربها '),
(2142, '1 Kings', 11, 20, 2, ' وأرسل رسلا إلى أخآب ملك إسرائيل إلى المدينة وقال له : هكذا يقول بنهدد '),
(2143, '1 Kings', 11, 20, 3, ' لي فضتك وذهبك ، ولي نساؤك وبنوك الحسان '),
(2144, '1 Kings', 11, 20, 4, ' فأجاب ملك إسرائيل وقال : حسب قولك يا سيدي الملك ، أنا وجميع ما لي لك '),
(2145, '1 Kings', 11, 20, 5, ' فرجع الرسل وقالوا : هكذا تكلم بنهدد قائلا : إني قد أرسلت إليك قائلا : إن فضتك وذهبك ونساءك وبنيك تعطيني إياهم '),
(2146, '1 Kings', 11, 20, 6, ' فإني في نحو هذا الوقت غدا أرسل عبيدي إليك فيفتشون بيتك وبيوت عبيدك ، وكل ما هو شهي في عينيك يضعونه في أيديهم ويأخذونه '),
(2147, '1 Kings', 11, 20, 7, ' فدعا ملك إسرائيل جميع شيوخ الأرض ، وقال : اعلموا وانظروا أن هذا يطلب الشر ، لأنه أرسل إلي بطلب نسائي وبني وفضتي وذهبي ولم أمنعها عنه '),
(2148, '1 Kings', 11, 20, 8, ' فقال له كل الشيوخ وكل الشعب : لا تسمع له ولا تقبل '),
(2149, '1 Kings', 11, 20, 9, ' فقال لرسل بنهدد : قولوا لسيدي الملك : إن كل ما أرسلت فيه إلى عبدك أولا أفعله . وأما هذا الأمر فلا أستطيع أن أفعله . فرجع الرسل وردوا عليه الجواب '),
(2150, '1 Kings', 11, 20, 10, ' فأرسل إليه بنهدد وقال : هكذا تفعل بي الآلهة وهكذا تزيدني ، إن كان تراب السامرة يكفي قبضات لكل الشعب الذي يتبعني '),
(2151, '1 Kings', 11, 20, 11, ' فأجاب ملك إسرائيل وقال : قولوا : لا يفتخرن من يشد كمن يحل '),
(2152, '1 Kings', 11, 20, 12, ' فلما سمع هذا الكلام وهو يشرب مع الملوك في الخيام قال لعبيده : اصطفوا . فاصطفوا على المدينة '),
(2153, '1 Kings', 11, 20, 13, ' وإذا بنبي تقدم إلى أخآب ملك إسرائيل وقال : هكذا قال الرب : هل رأيت كل هذا الجمهور العظيم ؟ هأنذا أدفعه ليدك اليوم ، فتعلم أني أنا الرب '),
(2154, '1 Kings', 11, 20, 14, ' فقال أخآب : بمن ؟  . فقال : هكذا قال الرب : بغلمان رؤساء المقاطعات . فقال : من يبتدئ بالحرب فقال : أنت '),
(2155, '1 Kings', 11, 20, 15, ' فعد غلمان رؤساء المقاطعات فبلغوا مئتين واثنين وثلاثين . وعد بعدهم كل الشعب ، كل بني إسرائيل ، سبعة آلاف '),
(2156, '1 Kings', 11, 20, 16, ' وخرجوا عند الظهر وبنهدد يشرب ويسكر في الخيام هو والملوك الاثنان والثلاثون الذين ساعدوه '),
(2157, '1 Kings', 11, 20, 17, ' فخرج غلمان رؤساء المقاطعات أولا . وأرسل بنهدد فأخبروه قائلين : قد خرج رجال من السامرة '),
(2158, '1 Kings', 11, 20, 18, ' فقال : إن كانوا قد خرجوا للسلام فأمسكوهم أحياء ، وإن كانوا قد خرجوا للقتال فأمسكوهم أحياء '),
(2159, '1 Kings', 11, 20, 19, ' فخرج غلمان رؤساء المقاطعات ، هؤلاء من المدينة هم ، والجيش الذي وراءهم '),
(2160, '1 Kings', 11, 20, 20, ' وضرب كل رجل رجله ، فهرب الأراميون ، وطاردهم إسرائيل ، ونجا بنهدد ملك أرام على فرس مع الفرسان '),
(2161, '1 Kings', 11, 20, 21, ' وخرج ملك إسرائيل فضرب الخيل والمركبات ، وضرب أرام ضربة عظيمة '),
(2162, '1 Kings', 11, 20, 22, ' فتقدم النبي إلى ملك إسرائيل وقال له : اذهب تشدد ، واعلم وانظر ما تفعل ، لأنه عند تمام السنة يصعد عليك ملك أرام '),
(2163, '1 Kings', 11, 20, 23, ' وأما عبيد ملك أرام فقالوا له : إن آلهتهم آلهة جبال ، لذلك قووا علينا . ولكن إذا حاربناهم في السهل فإننا نقوى عليهم '),
(2164, '1 Kings', 11, 20, 24, ' وافعل هذا الأمر : اعزل الملوك ، كل واحد من مكانه ، وضع قوادا مكانهم '),
(2165, '1 Kings', 11, 20, 25, ' وأحص لنفسك جيشا كالجيش الذي سقط منك ، فرسا بفرس ، ومركبة بمركبة ، فنحاربهم في السهل ونقوى عليهم . فسمع لقولهم وفعل كذلك '),
(2166, '1 Kings', 11, 20, 26, ' وعند تمام السنة عد بنهدد الأراميين ، وصعد إلى أفيق ليحارب إسرائيل '),
(2167, '1 Kings', 11, 20, 27, ' وأحصي بنو إسرائيل وتزودوا وساروا للقائهم . فنزل بنو إسرائيل مقابلهم نظير قطيعين صغيرين من المعزى ، وأما الأراميون فملأوا الأرض '),
(2168, '1 Kings', 11, 20, 28, ' فتقدم رجل الله وكلم ملك إسرائيل وقال : هكذا قال الرب : من أجل أن الأراميين قالوا : إن الرب إنما هو إله جبال وليس هو إله أودية ، أدفع كل هذا الجمهور العظيم ليدك ، فتعلمون أني أنا الرب '),
(2169, '1 Kings', 11, 20, 29, ' فنزل هؤلاء مقابل أولئك سبعة أيام . وفي اليوم السابع اشتبكت الحرب ، فضرب بنو إسرائيل من الأراميين مئة ألف راجل في يوم واحد '),
(2170, '1 Kings', 11, 20, 30, ' وهرب الباقون إلى أفيق ، إلى المدينة ، وسقط السور على السبعة والعشرين ألف رجل الباقين . وهرب بنهدد ودخل المدينة ، من مخدع إلى مخدع '),
(2171, '1 Kings', 11, 20, 31, ' فقال له عبيده : إننا قد سمعنا أن ملوك بيت إسرائيل هم ملوك حليمون ، فلنضع مسوحا على أحقائنا وحبالا على رؤوسنا ونخرج إلى ملك إسرائيل لعله يحيي نفسك '),
(2172, '1 Kings', 11, 20, 32, ' فشدوا مسوحا على أحقائهم وحبالا على رؤوسهم وأتوا إلى ملك إسرائيل وقالوا : يقول عبدك بنهدد : لتحي نفسي . فقال : أهو حي بعد هو أخي '),
(2173, '1 Kings', 11, 20, 33, ' فتفاءل الرجال وأسرعوا ولجوا هل هو منه . وقالوا : أخوك بنهدد . فقال : ادخلوا خذوه . فخرج إليه بنهدد فأصعده إلى المركبة '),
(2174, '1 Kings', 11, 20, 34, ' وقال له : إني أرد المدن التي أخذها أبي من أبيك ، وتجعل لنفسك أسواقا في دمشق كما جعل أبي في السامرة . فقال : وأنا أطلقك بهذا العهد . فقطع له عهدا وأطلقه '),
(2175, '1 Kings', 11, 20, 35, ' وإن رجلا من بني الأنبياء قال لصاحبه : عن أمر الرب اضربني . فأبى الرجل أن يضربه '),
(2176, '1 Kings', 11, 20, 36, ' فقال له : من أجل أنك لم تسمع لقول الرب ، فحينما تذهب من عندي يقتلك أسد . ولما ذهب من عنده لقيه أسد وقتله '),
(2177, '1 Kings', 11, 20, 37, ' ثم صادف رجلا آخر فقال : اضربني . فضربه الرجل ضربة فجرحه '),
(2178, '1 Kings', 11, 20, 38, ' فذهب النبي وانتظر الملك على الطريق ، وتنكر بعصابة على عينيه '),
(2179, '1 Kings', 11, 20, 39, ' ولما عبر الملك نادى الملك وقال : خرج عبدك إلى وسط القتال ، وإذا برجل مال وأتى إلي برجل وقال : احفظ هذا الرجل ، وإن فقد تكون نفسك بدل نفسه ، أو تدفع وزنة من الفضة '),
(2180, '1 Kings', 11, 20, 40, ' وفيما عبدك مشتغل هنا وهناك إذا هو مفقود . فقال له ملك إسرائيل : هكذا حكمك . أنت قضيت '),
(2181, '1 Kings', 11, 20, 41, ' فبادر ورفع العصابة عن عينيه ، فعرفه ملك إسرائيل أنه من الأنبياء '),
(2182, '1 Kings', 11, 20, 42, ' فقال له : هكذا قال الرب : لأنك أفلت من يدك رجلا قد حرمته ، تكون نفسك بدل نفسه ، وشعبك بدل شعبه '),
(2183, '1 Kings', 11, 20, 43, ' فمضى ملك إسرائيل إلى بيته مكتئبا مغموما وجاء إلى السامرة '),
(2184, '1 Kings', 11, 21, 1, ' وحدث بعد هذه الأمور أنه كان لنابوت اليزرعيلي كرم في يزرعيل بجانب قصر أخآب ملك السامرة '),
(2185, '1 Kings', 11, 21, 2, ' فكلم أخآب نابوت قائلا : أعطني كرمك فيكون لي بستان بقول ، لأنه قريب بجانب بيتي ، فأعطيك عوضه كرما أحسن منه . أو إذا حسن في عينيك أعطيتك ثمنه فضة '),
(2186, '1 Kings', 11, 21, 3, ' فقال نابوت لأخآب : حاشا لي من قبل الرب أن أعطيك ميراث آبائي '),
(2187, '1 Kings', 11, 21, 4, ' فدخل أخآب بيته مكتئبا مغموما من أجل الكلام الذي كلمه به نابوت اليزرعيلي قائلا : لا أعطيك ميراث آبائي . واضطجع على سريره وحول وجهه ولم يأكل خبزا '),
(2188, '1 Kings', 11, 21, 5, ' فدخلت إليه إيزابل امرأته وقالت له : لماذا روحك مكتئبة ولا تأكل خبزا '),
(2189, '1 Kings', 11, 21, 6, ' فقال لها : لأني كلمت نابوت اليزرعيلي وقلت له : أعطني كرمك بفضة ، وإذا شئت أعطيتك كرما عوضه ، فقال : لا أعطيك كرمي ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(2190, '1 Kings', 11, 21, 7, ' فقالت له إيزابل : أأنت الآن تحكم على إسرائيل ؟ قم كل خبزا وليطب قلبك . أنا أعطيك كرم نابوت اليزرعيلي '),
(2191, '1 Kings', 11, 21, 8, ' ثم كتبت رسائل باسم أخآب ، وختمتها بخاتمه ، وأرسلت الرسائل إلى الشيوخ والأشراف الذين في مدينته الساكنين مع نابوت '),
(2192, '1 Kings', 11, 21, 9, ' وكتبت في الرسائل تقول : نادوا بصوم ؟ وأجلسوا نابوت في رأس الشعب '),
(2193, '1 Kings', 11, 21, 10, ' وأجلسوا رجلين من بني بليعال تجاهه ليشهدا قائلين : قد جدفت على الله وعلى الملك . ثم أخرجوه وارجموه فيموت '),
(2194, '1 Kings', 11, 21, 11, ' ففعل رجال مدينته ، الشيوخ والأشراف الساكنون في مدينته ، كما أرسلت إليهم إيزابل ، كما هو مكتوب في الرسائل التي أرسلتها إليهم '),
(2195, '1 Kings', 11, 21, 12, ' فنادوا بصوم وأجلسوا نابوت في رأس الشعب '),
(2196, '1 Kings', 11, 21, 13, ' وأتى رجلان من بني بليعال وجلسا تجاهه ، وشهد رجلا بليعال على نابوت أمام الشعب قائلين : قد جدف نابوت على الله وعلى الملك . فأخرجوه خارج المدينة ورجموه بحجارة فمات '),
(2197, '1 Kings', 11, 21, 14, ' وأرسلوا إلى إيزابل يقولون : قد رجم نابوت ومات '),
(2198, '1 Kings', 11, 21, 15, ' ولما سمعت إيزابل أن نابوت قد رجم ومات ، قالت إيزابل لأخآب : قم رث كرم نابوت اليزرعيلي الذي أبى أن يعطيك إياه بفضة ، لأن نابوت ليس حيا بل هو ميت '),
(2199, '1 Kings', 11, 21, 16, ' ولما سمع أخآب أن نابوت قد مات ، قام أخآب لينزل إلى كرم نابوت اليزرعيلي ليرثه '),
(2200, '1 Kings', 11, 21, 17, ' فكان كلام الرب إلى إيليا التشبي قائلا '),
(2201, '1 Kings', 11, 21, 18, ' قم انزل للقاء أخآب ملك إسرائيل الذي في السامرة . هوذا هو في كرم نابوت الذي نزل إليه ليرثه '),
(2202, '1 Kings', 11, 21, 19, ' وكلمه قائلا : هكذا قال الرب : هل قتلت وورثت أيضا ؟ ثم كلمه قائلا : هكذا قال الرب : في المكان الذي لحست فيه الكلاب دم نابوت تلحس الكلاب دمك أنت أيضا '),
(2203, '1 Kings', 11, 21, 20, ' فقال أخآب لإيليا : هل وجدتني يا عدوي ؟  . فقال : قد وجدتك لأنك قد بعت نفسك لعمل الشر في عيني الرب '),
(2204, '1 Kings', 11, 21, 21, ' هأنذا أجلب عليك شرا ، وأبيد نسلك ، وأقطع لأخآب كل بائل بحائط ومحجوز ومطلق في إسرائيل '),
(2205, '1 Kings', 11, 21, 22, ' وأجعل بيتك كبيت يربعام بن نباط ، وكبيت بعشا بن أخيا ، لأجل الإغاظة التي أغظتني ، ولجعلك إسرائيل يخطئ '),
(2206, '1 Kings', 11, 21, 23, ' وتكلم الرب عن إيزابل أيضا قائلا : إن الكلاب تأكل إيزابل عند مترسة يزرعيل '),
(2207, '1 Kings', 11, 21, 24, ' من مات لأخآب في المدينة تأكله الكلاب ، ومن مات في الحقل تأكله طيور السماء '),
(2208, '1 Kings', 11, 21, 25, ' ولم يكن كأخآب الذي باع نفسه لعمل الشر في عيني الرب ، الذي أغوته إيزابل امرأته '),
(2209, '1 Kings', 11, 21, 26, ' ورجس جدا بذهابه وراء الأصنام ، حسب كل ما فعل الأموريون الذين طردهم الرب من أمام بني إسرائيل '),
(2210, '1 Kings', 11, 21, 27, ' ولما سمع أخآب هذا الكلام ، شق ثيابه وجعل مسحا على جسده ، وصام واضطجع بالمسح ومشى بسكوت '),
(2211, '1 Kings', 11, 21, 28, ' فكان كلام الرب إلى إيليا التشبي قائلا '),
(2212, '1 Kings', 11, 21, 29, ' هل رأيت كيف اتضع أخآب أمامي ؟ فمن أجل أنه قد اتضع أمامي لا أجلب الشر في أيامه ، بل في أيام ابنه أجلب الشر على بيته '),
(2213, '1 Kings', 11, 22, 1, ' وأقاموا ثلاث سنين بدون حرب بين أرام وإسرائيل '),
(2214, '1 Kings', 11, 22, 2, ' وفي السنة الثالثة نزل يهوشافاط ملك يهوذا إلى ملك إسرائيل '),
(2215, '1 Kings', 11, 22, 3, ' فقال ملك إسرائيل لعبيده : أتعلمون أن راموت جلعاد لنا ونحن ساكتون عن أخذها من يد ملك أرام '),
(2216, '1 Kings', 11, 22, 4, ' وقال ليهوشافاط : أتذهب معي للحرب إلى راموت جلعاد ؟ فقال يهوشافاط لملك إسرائيل : مثلي مثلك . شعبي كشعبك ، وخيلي كخيلك '),
(2217, '1 Kings', 11, 22, 5, ' ثم قال يهوشافاط لملك إسرائيل : اسأل اليوم عن كلام الرب '),
(2218, '1 Kings', 11, 22, 6, ' فجمع ملك إسرائيل الأنبياء ، نحو أربع مئة رجل وقال لهم : أأذهب إلى راموت جلعاد للقتال أم أمتنع ؟  . فقالوا : اصعد فيدفعها السيد ليد الملك '),
(2219, '1 Kings', 11, 22, 7, ' فقال يهوشافاط : أما يوجد هنا بعد نبي للرب فنسأل منه '),
(2220, '1 Kings', 11, 22, 8, ' فقال ملك إسرائيل ليهوشافاط : إنه يوجد بعد رجل واحد لسؤال الرب به ، ولكني أبغضه لأنه لا يتنبأ علي خيرا بل شرا ، وهو ميخا بن يملة . فقال يهوشافاط : لا يقل الملك هكذا '),
(2221, '1 Kings', 11, 22, 9, ' فدعا ملك إسرائيل خصيا وقال : أسرع إلي بميخا بن يملة '),
(2222, '1 Kings', 11, 22, 10, ' وكان ملك إسرائيل ويهوشافاط ملك يهوذا جالسين كل واحد على كرسيه ، لابسين ثيابهما في ساحة عند مدخل باب السامرة ، وجميع الأنبياء يتنبأون أمامهما '),
(2223, '1 Kings', 11, 22, 11, ' وعمل صدقيا بن كنعنة لنفسه قرني حديد وقال : هكذا قال الرب : بهذه تنطح الأراميين حتى يفنوا '),
(2224, '1 Kings', 11, 22, 12, ' وتنبأ جميع الأنبياء هكذا قائلين : اصعد إلى راموت جلعاد وأفلح ، فيدفعها الرب ليد الملك '),
(2225, '1 Kings', 11, 22, 13, ' وأما الرسول الذي ذهب ليدعو ميخا فكلمه قائلا : هوذا كلام جميع الأنبياء بفم واحد خير للملك ، فليكن كلامك مثل كلام واحد منهم ، وتكلم بخير '),
(2226, '1 Kings', 11, 22, 14, ' فقال ميخا : حي هو الرب ، إن ما يقوله لي الرب به أتكلم '),
(2227, '1 Kings', 11, 22, 15, ' ولما أتى إلى الملك قال له الملك : يا ميخا ، أنصعد إلى راموت جلعاد للقتال ، أم نمتنع ؟  . فقال له : اصعد وأفلح فيدفعها الرب ليد الملك '),
(2228, '1 Kings', 11, 22, 16, ' فقال له الملك : كم مرة استحلفتك أن لا تقول لي إلا الحق باسم الرب '),
(2229, '1 Kings', 11, 22, 17, ' فقال : رأيت كل إسرائيل مشتتين على الجبال كخراف لا راعي لها . فقال الرب : ليس لهؤلاء أصحاب ، فليرجعوا كل واحد إلى بيته بسلام '),
(2230, '1 Kings', 11, 22, 18, ' فقال ملك إسرائيل ليهوشافاط : أما قلت لك : إنه لا يتنبأ علي خيرا بل شرا '),
(2231, '1 Kings', 11, 22, 19, ' وقال : فاسمع إذا كلام الرب : قد رأيت الرب جالسا على كرسيه ، وكل جند السماء وقوف لديه عن يمينه وعن يساره '),
(2232, '1 Kings', 11, 22, 20, ' فقال الرب : من يغوي أخآب فيصعد ويسقط في راموت جلعاد ؟ فقال هذا هكذا ، وقال ذاك هكذا '),
(2233, '1 Kings', 11, 22, 21, ' ثم خرج الروح ووقف أمام الرب وقال : أنا أغويه . وقال له الرب : بماذا '),
(2234, '1 Kings', 11, 22, 22, ' فقال : أخرج وأكون روح كذب في أفواه جميع أنبيائه . فقال : إنك تغويه وتقتدر ، فاخرج وافعل هكذا '),
(2235, '1 Kings', 11, 22, 23, ' والآن هوذا قد جعل الرب روح كذب في أفواه جميع أنبيائك هؤلاء ، والرب تكلم عليك بشر '),
(2236, '1 Kings', 11, 22, 24, ' فتقدم صدقيا بن كنعنة وضرب ميخا على الفك وقال : من أين عبر روح الرب مني ليكلمك '),
(2237, '1 Kings', 11, 22, 25, ' فقال ميخا : إنك سترى في ذلك اليوم الذي تدخل فيه من مخدع إلى مخدع لتختبئ '),
(2238, '1 Kings', 11, 22, 26, ' فقال ملك إسرائيل : خذ ميخا ورده إلى آمون رئيس المدينة ، وإلى يوآش ابن الملك '),
(2239, '1 Kings', 11, 22, 27, ' وقل هكذا قال الملك : ضعوا هذا في السجن ، وأطعموه خبز الضيق وماء الضيق حتى آتي بسلام '),
(2240, '1 Kings', 11, 22, 28, ' فقال ميخا : إن رجعت بسلام فلم يتكلم الرب بي . وقال : اسمعوا أيها الشعب أجمعون '),
(2241, '1 Kings', 11, 22, 29, ' فصعد ملك إسرائيل ويهوشافاط ملك يهوذا إلى راموت جلعاد '),
(2242, '1 Kings', 11, 22, 30, ' فقال ملك إسرائيل ليهوشافاط : إني أتنكر وأدخل الحرب ، وأما أنت فالبس ثيابك . فتنكر ملك إسرائيل ودخل الحرب '),
(2243, '1 Kings', 11, 22, 31, ' وأمر ملك أرام رؤساء المركبات التي له ، الاثنين والثلاثين ، وقال : لا تحاربوا صغيرا ولا كبيرا إلا ملك إسرائيل وحده '),
(2244, '1 Kings', 11, 22, 32, ' فلما رأى رؤساء المركبات يهوشافاط ، قالوا : إنه ملك إسرائيل . فمالوا عليه ليقاتلوه ، فصرخ يهوشافاط '),
(2245, '1 Kings', 11, 22, 33, ' فلما رأى رؤساء المركبات أنه ليس ملك إسرائيل رجعوا عنه '),
(2246, '1 Kings', 11, 22, 34, ' وإن رجلا نزع في قوسه غير متعمد وضرب ملك إسرائيل بين أوصال الدرع . فقال لمدير مركبته : رد يدك وأخرجني من الجيش لأني قد جرحت '),
(2247, '1 Kings', 11, 22, 35, ' واشتد القتال في ذلك اليوم ، وأوقف الملك في مركبته مقابل أرام ، ومات عند المساء ، وجرى دم الجرح إلى حضن المركبة '),
(2248, '1 Kings', 11, 22, 36, ' وعبرت الرنة في الجند عند غروب الشمس قائلا : كل رجل إلى مدينته ، وكل رجل إلى أرضه '),
(2249, '1 Kings', 11, 22, 37, ' فمات الملك وأدخل السامرة فدفنوا الملك في السامرة '),
(2250, '1 Kings', 11, 22, 38, ' وغسلت المركبة في بركة السامرة فلحست الكلاب دمه ، وغسلوا سلاحه . حسب كلام الرب الذي تكلم به '),
(2251, '1 Kings', 11, 22, 39, ' وبقية أمور أخآب وكل ما فعل ، وبيت العاج الذي بناه ، وكل المدن التي بناها ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(2252, '1 Kings', 11, 22, 40, ' فاضطجع أخآب مع آبائه ، وملك أخزيا ابنه عوضا عنه '),
(2253, '1 Kings', 11, 22, 41, ' وملك يهوشافاط بن آسا على يهوذا في السنة الرابعة لأخآب ملك إسرائيل '),
(2254, '1 Kings', 11, 22, 42, ' وكان يهوشافاط ابن خمس وثلاثين سنة حين ملك ، وملك خمسا وعشرين سنة في أورشليم ، واسم أمه عزوبة بنت شلحي '),
(2255, '1 Kings', 11, 22, 43, ' وسار في كل طريق آسا أبيه . لم يحد عنها ، إذ عمل المستقيم في عيني الرب . إلا أن المرتفعات لم تنتزع ، بل كان الشعب لا يزال يذبح ويوقد على المرتفعات '),
(2256, '1 Kings', 11, 22, 44, ' وصالح يهوشافاط ملك إسرائيل '),
(2257, '1 Kings', 11, 22, 45, ' وبقية أمور يهوشافاط وجبروته الذي أظهره ، وكيف حارب ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(2258, '1 Kings', 11, 22, 46, ' وبقية المأبونين الذين بقوا في أيام آسا أبيه أبادهم من الأرض '),
(2259, '1 Kings', 11, 22, 47, ' ولم يكن في أدوم ملك . ملك وكيل '),
(2260, '1 Kings', 11, 22, 48, ' وعمل يهوشافاط سفن ترشيش لكي تذهب إلى أوفير لأجل الذهب ، فلم تذهب ، لأن السفن تكسرت في عصيون جابر '),
(2261, '1 Kings', 11, 22, 49, ' حينئذ قال أخزيا بن أخآب ليهوشافاط : ليذهب عبيدي مع عبيدك في السفن . فلم يشأ يهوشافاط '),
(2262, '1 Kings', 11, 22, 50, ' واضطجع يهوشافاط مع آبائه ، ودفن مع آبائه في مدينة داود أبيه ، فملك يهورام ابنه عوضا عنه '),
(2263, '1 Kings', 11, 22, 51, ' أخزيا بن أخآب ملك على إسرائيل في السامرة في السنة السابعة عشرة ليهوشافاط ملك يهوذا . ملك على إسرائيل سنتين '),
(2264, '1 Kings', 11, 22, 52, ' وعمل الشر في عيني الرب ، وسار في طريق أبيه وطريق أمه ، وطريق يربعام بن نباط الذي جعل إسرائيل يخطئ '),
(2265, '1 Kings', 11, 22, 53, ' وعبد البعل وسجد له وأغاظ الرب إله إسرائيل ، حسب كل ما فعل أبوه '),
(2266, '1 Maccabees', 72, 1, 1, 'ان الاسكندر بن فيلبس المكدوني بعد خروجه من ارض كتيم وايقاعه بداريوس ملك فارس وماداي ملك مكانه وهو اول من ملك على اليونان'),
(2267, '1 Maccabees', 72, 1, 2, 'ثم اثار حروبا كثيرة وفتح حصونا متعددة وقتل ملوك الارض'),
(2268, '1 Maccabees', 72, 1, 3, 'و اجتاز الى اقاصي الارض وسلب غنائم جمهور من الامم فسكتت الارض بين يديه فترفع في قلبه وتشامخ'),
(2269, '1 Maccabees', 72, 1, 4, 'و حشد جيشا قويا جدا'),
(2270, '1 Maccabees', 72, 1, 5, 'و استولى على البلاد والامم والسلاطين فكانوا يحملون اليه الجزية'),
(2271, '1 Maccabees', 72, 1, 6, 'و بعد ذلك انطرح على فراشه واحس من نفسه بالموت'),
(2272, '1 Maccabees', 72, 1, 7, 'فدعا عبيده الكبراء الذين نشاوا معه منذ الصباء فقسم مملكته بينهم في حياته'),
(2273, '1 Maccabees', 72, 1, 8, 'و كان ملك الاسكندر اثنتي عشرة سنة ومات'),
(2274, '1 Maccabees', 72, 1, 9, 'فتملك عبيده كل واحد في مكانه'),
(2275, '1 Maccabees', 72, 1, 10, 'و لبس كل منهم التاج بعد وفاته وكذلك بنوهم من بعدهم سنين كثيرة فكثرت الشرور في الارض'),
(2276, '1 Maccabees', 72, 1, 11, 'و خرجت منهم جرثومة اثيمة هي انطيوكس الشهير ابن انطيوكس الملك وكان رهينة في رومية وملك في السنة المئة والسابعة والثلاثين من دولة اليونان'),
(2277, '1 Maccabees', 72, 1, 12, 'و في تلك الايام خرج من اسرائيل ابناء منافقون فاغروا كثيرين قائلين هلم نعقد عهدا مع الامم حولنا فانا منذ انفصلنا عنهم لحقتنا شرور كثيرة'),
(2278, '1 Maccabees', 72, 1, 13, 'فحسن الكلام في عيونهم'),
(2279, '1 Maccabees', 72, 1, 14, 'و بادر نفر من الشعب وذهبوا الى الملك فاطلق لهم ان يصنعوا بحسب احكام الامم'),
(2280, '1 Maccabees', 72, 1, 15, 'فابتنوا مدرسة في اورشليم على حسب سنن الامم'),
(2281, '1 Maccabees', 72, 1, 16, 'و عملوا لهم غلفا وارتدوا عن العهد المقدس ومازجوا الامم وباعوا انفسهم لصنيع الشر'),
(2282, '1 Maccabees', 72, 1, 17, 'و لما استتب الملك لانطيوكس ازمع على امتلاك مصر ليكون مالكا على كلتا المملكتين'),
(2283, '1 Maccabees', 72, 1, 18, 'فدخل مصر بجيش كثيف وعجلات وفيلة وفرسان واسطول عظيم'),
(2284, '1 Maccabees', 72, 1, 19, 'و اثار الحرب على بطلماوس ملك مصر فارتاع بطلماوس من وجهه وهرب وسقط قتلى كثيرون'),
(2285, '1 Maccabees', 72, 1, 20, 'فاستحوذوا على المدن الحصينة بارض مصر وسلبوا غنائم ارض مصر'),
(2286, '1 Maccabees', 72, 1, 21, 'و رجع انطيوكس بعدما اوقع بمصر وذلك في السنة المئة والثالثة والاربعين ونهض نحو اسرائيل'),
(2287, '1 Maccabees', 72, 1, 22, 'فصعد الى اورشليم بجيش كثيف'),
(2288, '1 Maccabees', 72, 1, 23, 'و دخل المقدس بتجبر واخذ مذبح الذهب ومنارة النور مع جميع ادواتها ومائدة التنضيد والمساكب والجامات ومجامر الذهبو الحجاب والاكاليل والحلية الذهبية التي كانت على وجه الهيكل وحطمها جميعا'),
(2289, '1 Maccabees', 72, 1, 24, 'و اخذ الفضة والذهب والانية النفيسة واخذ ما وجد من الكنوز المكنونة اخذ الجميع وانصرف الى ارضه'),
(2290, '1 Maccabees', 72, 1, 25, 'و اكثر من القتل وتكلم بتجبر عظيم'),
(2291, '1 Maccabees', 72, 1, 26, 'فكانت مناحة عظيمة في اسرائيل في كل ارضهم'),
(2292, '1 Maccabees', 72, 1, 27, 'و انتحب الرؤساء والشيوخ وخارت العذارى والفتيان وتغير جمال النساء'),
(2293, '1 Maccabees', 72, 1, 28, 'و كل عروس اتخذ مرثاة والجالسة في الحجلة عقدت مناحة'),
(2294, '1 Maccabees', 72, 1, 29, 'فارتجت الارض على سكانها وجميع ال يعقوب لبسوا الخزي'),
(2295, '1 Maccabees', 72, 1, 30, 'و بعد سنتين من الايام ارسل الملك رئيس الجزية الى مدن يهوذا فوفد على اورشليم في جيش كثيف'),
(2296, '1 Maccabees', 72, 1, 31, 'و خاطبهم خطاب سلام مكرا فوثقوا به'),
(2297, '1 Maccabees', 72, 1, 32, 'ثم هجم على المدينة فجاة وضربها ضربة عظيمة واهلك شعبا كثيرا من اسرائيل'),
(2298, '1 Maccabees', 72, 1, 33, 'و سلب غنائم المدينة واحرقها بالنار وهدم بيوتها واسوارها من حولها'),
(2299, '1 Maccabees', 72, 1, 34, 'و سبوا النساء والاولاد واستولوا على المواشي'),
(2300, '1 Maccabees', 72, 1, 35, 'و بنوا على مدينة داود سورا عظيما متينا وبروجا حصينة فصارت قلعة لهم'),
(2301, '1 Maccabees', 72, 1, 36, 'و جعلوا هناك امة اثيمة رجالا منافقين فتحصنوا فيها ووضعوا فيها السلاح والطعام وجمعوا غنائم اورشليم'),
(2302, '1 Maccabees', 72, 1, 37, 'و وضعوها هناك فصاروا لهم شركا مهلكا'),
(2303, '1 Maccabees', 72, 1, 38, 'و كان ذلك مكمنا للمقدس وشيطانا خبيثا لاسرائيل على الدوام'),
(2304, '1 Maccabees', 72, 1, 39, 'فسفكوا الدم الزكي حول المقدس ونجسوا المقدس'),
(2305, '1 Maccabees', 72, 1, 40, 'فهرب اهل اورشليم بسببهم فامست مسكن غرباء وصارت غريبة للمولودين فيها وابناؤها هجروها'),
(2306, '1 Maccabees', 72, 1, 41, 'و رد مقدسها خرابا كالقفر وحولت اعيادها مناحة وسبوتها عارا وعزها اضمحلالا'),
(2307, '1 Maccabees', 72, 1, 42, 'و على قدر مجدها اكثر هوانها ورفعتها الت الى مناحة'),
(2308, '1 Maccabees', 72, 1, 43, 'و كتب الملك انطيوكس الى مملكته كلها بان يكونوا جميعهم شعبا واحدا ويتركوا كل واحد سننه'),
(2309, '1 Maccabees', 72, 1, 44, 'فاذعنت الامم باسرها لكلام الملك'),
(2310, '1 Maccabees', 72, 1, 45, 'و كثيرون من اسرائيل ارتضوا دينه وذبحوا للاصنام ودنسوا السبت'),
(2311, '1 Maccabees', 72, 1, 46, 'و انفذ الملك كتبا على ايدي رسل الى اورشليم ومدن يهوذا ان يتبعوا سنن الاجانب في الارض'),
(2312, '1 Maccabees', 72, 1, 47, 'و يمتنعوا عن المحرقات والذبيحة والسكيب في المقدس'),
(2313, '1 Maccabees', 72, 1, 48, 'و يدنسوا السبوت والاعياد'),
(2314, '1 Maccabees', 72, 1, 49, 'و ينجسوا المقادس والقديسين'),
(2315, '1 Maccabees', 72, 1, 50, 'و يبتنوا مذابح وهياكل ومعابد للاصنام ويذبحوا الخنازير والحيوانات النجسة'),
(2316, '1 Maccabees', 72, 1, 51, 'و يتركوا بنيهم قلفا ويقذروا نفوسهم بكل نجاسة ورجس حتى ينسوا الشريعة ويغيروا جميع الاحكام'),
(2317, '1 Maccabees', 72, 1, 52, 'و من لا يعمل بمقتضى كلام الملك يقتل'),
(2318, '1 Maccabees', 72, 1, 53, 'و كتب بمثل هذا الكلام كله الى مملكته باسرها واقام رقباء على جميع الشعب'),
(2319, '1 Maccabees', 72, 1, 54, 'و امر مدائن يهوذا بان يذبحوا في كل مدينة'),
(2320, '1 Maccabees', 72, 1, 55, 'فانضم اليهم كثيرون من الشعب كل من نبذ الشريعة فصنعوا الشر في الارض'),
(2321, '1 Maccabees', 72, 1, 56, 'و الجاوا اسرائيل الى المختبات في كل موضع فروا اليه'),
(2322, '1 Maccabees', 72, 1, 57, 'و في اليوم الخامس عشر من كسلو في السنة المئة والخامسة والاربعين بنوا رجاسة الخراب على المذبح وبنوا مذابح في مدن يهوذا من كل ناحية'),
(2323, '1 Maccabees', 72, 1, 58, 'و كانوا يقترون على ابواب البيوت وفي الساحات'),
(2324, '1 Maccabees', 72, 1, 59, 'و ما وجدوه من اسفار الشريعة مزقوه واحرقوه بالنار'),
(2325, '1 Maccabees', 72, 1, 60, 'و كل من وجد عنده سفر من العهد او اتبع الشريعة فانه مقتول بامر الملك'),
(2326, '1 Maccabees', 72, 1, 61, 'هكذا كانوا يفعلون بسطوتهم في اسرائيل بالذين يصادفونهم في المدن شهرا فشهرا'),
(2327, '1 Maccabees', 72, 1, 62, 'و في اليوم الخامس والعشرين من الشهر ذبحوا على مذبح الاصنام الذي فوق المذبح'),
(2328, '1 Maccabees', 72, 1, 63, 'و النساء اللواتي ختن اولادهن قتلوهن بمقتضى الامر'),
(2329, '1 Maccabees', 72, 1, 64, 'و علقوا الاطفال في اعناقهن ونهبوا بيوتهن وقتلوا الذين ختنوهم'),
(2330, '1 Maccabees', 72, 1, 65, 'و ان كثيرين في اسرائيل عزموا وصمموا في انفسهم على ان لا ياكلوا نجسا واختاروا الموت لئلا يتنجسوا بالاطعمة'),
(2331, '1 Maccabees', 72, 1, 66, 'و لا يدنسوا العهد المقدس فماتوا'),
(2332, '1 Maccabees', 72, 1, 67, 'و كان على اسرائيل غضب شديد جدا'),
(2333, '1 Maccabees', 72, 2, 1, 'في تلك الايام خرج من اورشليم متتيا بن يوحنا بن سمعان كاهن من بني يوياريب وسكن في مودين'),
(2334, '1 Maccabees', 72, 2, 2, 'و كان له خمسة بنين يوحنا الملقب بكديس'),
(2335, '1 Maccabees', 72, 2, 3, 'و سمعان المسمى بطسي'),
(2336, '1 Maccabees', 72, 2, 4, 'و يهوذا الملقب بالمكابي'),
(2337, '1 Maccabees', 72, 2, 5, 'و العازار الملقب باواران ويوناتان الملقب بافوس'),
(2338, '1 Maccabees', 72, 2, 6, 'و لما راى ما يصنع من المنكرات في يهوذا واورشليم'),
(2339, '1 Maccabees', 72, 2, 7, 'قال ويل لي لم ولدت فانظر حطم شعبي وحطم المدينة المقدسة وامكث ههنا اراها مسلمة الى ايدي الاعداء'),
(2340, '1 Maccabees', 72, 2, 8, 'و ارى المقدس في ايدي الاجانب وهيكلها كرجل ذليل'),
(2341, '1 Maccabees', 72, 2, 9, 'و قد اخذت انية مجدها في السبي وقتل اطفالها في الساحات وفتيانها بسيف العدو'),
(2342, '1 Maccabees', 72, 2, 10, 'اية امة لم ترث ملكها ولم تسلب غنائمها'),
(2343, '1 Maccabees', 72, 2, 11, 'جميع حلاها قد نزعت والتي كانت حرة صارت امة'),
(2344, '1 Maccabees', 72, 2, 12, 'ها ان اقداسنا وبهاءنا ومجدنا قد دمرت ودنستها الامم'),
(2345, '1 Maccabees', 72, 2, 13, 'فلم حياتنا بعد'),
(2346, '1 Maccabees', 72, 2, 14, 'و مزق متتيا وبنوه ثيابهم وتحزموا بالمسوح وناحوا مناحة شديدة'),
(2347, '1 Maccabees', 72, 2, 15, 'و ان الذين ارسلهم الملك ليجبروا الناس على الارتداد قدموا الى مدينة مودين ليذبحوا'),
(2348, '1 Maccabees', 72, 2, 16, 'فاقبل عليهم كثيرين من اسرائيل واجتمع متتيا وبنوه'),
(2349, '1 Maccabees', 72, 2, 17, 'فاجاب رسل الملك وكلموا متتيا قائلين انت رئيس في هذه المدينة شريف عظيم معزز بالبنين والاخوة'),
(2350, '1 Maccabees', 72, 2, 18, 'فالان ابدا انت وتقدم لامضاء امر الملك كما فعلت الامم كلها ورجال يهوذا ومن بقي في اورشليم فتكون انت واهل بيتك من اصدقاء الملك وتكرم انت وبنوك بالذهب والفضة والهدايا الكثيرة'),
(2351, '1 Maccabees', 72, 2, 19, 'فاجاب متتيا بصوت عظيم وقال انه وان طاعت للملك كل الامم التي في دار ملكه وارتد كل احد عن دين ابائه ورضي باوامره'),
(2352, '1 Maccabees', 72, 2, 20, 'فانا وبني واخوتي نسلك في عهد ابائنا'),
(2353, '1 Maccabees', 72, 2, 21, 'فحاشا لنا ان نترك الشريعة والاحكام'),
(2354, '1 Maccabees', 72, 2, 22, 'انا لن نسمع لكلام الملك فنحيد عن ديننا يمنة او يسرة'),
(2355, '1 Maccabees', 72, 2, 23, 'و لما فرغ من هذا الكلام اقبل رجل يهودي على عيون الجميع ليذبح على المذبح الذي في مودين على مقتضى امر الملك'),
(2356, '1 Maccabees', 72, 2, 24, 'فلما راى متتيا ذلك غار وارتعش حقواه واستشاط غضبا وفاقا للشريعة فوثب عليه وقتله على المذبح'),
(2357, '1 Maccabees', 72, 2, 25, 'و في ذلك الوقت قتل ايضا رجل الملك الذي كان يجبر على الذبح وهدم المذبح'),
(2358, '1 Maccabees', 72, 2, 26, 'و غار للشريعة كما فعل فنحاس بزمري بن سالو'),
(2359, '1 Maccabees', 72, 2, 27, 'و صاح متتيا في المدينة بصوت عظيم قائلا كل من غار للشريعة وحافظ على العهد فليخرج ورائي'),
(2360, '1 Maccabees', 72, 2, 28, 'و هرب هو وبنوه الى الجبال وتركوا كل ما لهم في المدينة'),
(2361, '1 Maccabees', 72, 2, 29, 'حينئذ نزل كثيرون الى البرية ممن يبتغون العدل والحكم'),
(2362, '1 Maccabees', 72, 2, 30, 'ليسكنوا هناك هم وبنوهم ونساؤهم ومواشيهم لان الشرور كثرت عليهم'),
(2363, '1 Maccabees', 72, 2, 31, 'فاخبر رجال الملك والجند الذين كانوا في اورشليم في مدينة داود بان رجالا من الناقضين لامر الملك قد نزلوا واختباوا في البرية فجرى كثيرون في اعقابهم'),
(2364, '1 Maccabees', 72, 2, 32, 'فادركوهم وجيشوا حولهم وناصبوهم القتال في يوم السبت'),
(2365, '1 Maccabees', 72, 2, 33, 'و قالوا لهم حسبكم ما فعلتم فاخرجوا وافعلوا كما امر الملك فتحيوا'),
(2366, '1 Maccabees', 72, 2, 34, 'فقالوا لا نخرج ولا نفعل كما امر الملك لئلا ندنس يوم السبت'),
(2367, '1 Maccabees', 72, 2, 35, 'فاثاروا عليهم القتال'),
(2368, '1 Maccabees', 72, 2, 36, 'فلم يردوا عليهم ولا رموهم بحجر ولا سدوا مختباتهم'),
(2369, '1 Maccabees', 72, 2, 37, 'قائلين لنمت جميعا في استقامتنا والسماء والارض شاهدتان لنا بانكم تهلكوننا ظلما'),
(2370, '1 Maccabees', 72, 2, 38, 'فهجموا عليهم وقاتلوهم في السبت فهلكوا هم ونساؤهم وبنوهم ومواشيهم وكانوا الف نفس من الناس'),
(2371, '1 Maccabees', 72, 2, 39, 'و اخبر متتيا واصحابه فناحوا عليهم نوحا شديدا'),
(2372, '1 Maccabees', 72, 2, 40, 'و قال بعضهم لبعض ان فعلنا كلنا كما فعل اخوتنا ولم نقاتل الامم عن نفوسنا واحكامنا لم يلبثوا ان يبيدونا عن الارض'),
(2373, '1 Maccabees', 72, 2, 41, 'و اتمروا في ذلك اليوم قائلين كل رجل اتانا مقاتلا يوم السبت نقاتله ولا نموت جميعا كما مات اخوتنا في المختبات'),
(2374, '1 Maccabees', 72, 2, 42, 'حينئذ اجتمعت اليهم جماعة الحسيديين ذوي الباس في اسرائيل وكل من انتدب للشريعة'),
(2375, '1 Maccabees', 72, 2, 43, 'و انضم اليهم جميع الذين فروا من الشر فازدادوا بهم تعزيزا'),
(2376, '1 Maccabees', 72, 2, 44, 'و الفوا جيشا واوقعوا بالخطاة في غضبهم وبرجال النفاق في حنقهم وفر الباقون الى الامم طالبين النجاة'),
(2377, '1 Maccabees', 72, 2, 45, 'ثم جال متتيا واصحابه وهدموا المذابح'),
(2378, '1 Maccabees', 72, 2, 46, 'و ختنوا كل من وجدوه في تخوم اسرائيل من الاولاد الغلف وتشددوا'),
(2379, '1 Maccabees', 72, 2, 47, 'و تتبعوا ذوي التجبر ونجحوا في عمل ايديهم'),
(2380, '1 Maccabees', 72, 2, 48, 'و انقذوا الشريعة من ايدي الامم وايدي الملوك ولم يجعلوا للخاطئ قرنا'),
(2381, '1 Maccabees', 72, 2, 49, 'و قاربت ايام متتيا ان يموت فقال لبنيه لقد اشتد التجبر والعقاب وزمان الانقلاب ووغر الحنق'),
(2382, '1 Maccabees', 72, 2, 50, 'فالان ايها البنون غاروا للشريعة وابذلوا نفوسكم دون عهد ابائنا'),
(2383, '1 Maccabees', 72, 2, 51, 'اذكروا اعمال ابائنا التي صنعوها في اجيالهم فتنالوا مجدا عظيما واسما مخلدا'),
(2384, '1 Maccabees', 72, 2, 52, 'الم يكن ابرهيم في التجربة وجد مؤمنا فحسب له ذلك برا'),
(2385, '1 Maccabees', 72, 2, 53, 'و يوسف في اوان ضيقه حفظ الوصية فصار سيدا على مصر'),
(2386, '1 Maccabees', 72, 2, 54, 'و فنحاس ابونا غار غيرة فاخذ عهد كهنوت ابدي'),
(2387, '1 Maccabees', 72, 2, 55, 'و يشوع اذ اتم ما امر به صار قاضيا في اسرائيل'),
(2388, '1 Maccabees', 72, 2, 56, 'و كالب بشهادته في الجماعة نال ميراثا في الارض'),
(2389, '1 Maccabees', 72, 2, 57, 'و داود برحمته ورث عرش الملك الى ابد الاباد'),
(2390, '1 Maccabees', 72, 2, 58, 'و ايليا بغيرته للشريعة رفع الى السماء'),
(2391, '1 Maccabees', 72, 2, 59, 'و حننيا وعزريا وميشائيل بايمانهم خلصوا من اللهيب'),
(2392, '1 Maccabees', 72, 2, 60, 'و دانيال باستقامته انقذ من افواه الاسود'),
(2393, '1 Maccabees', 72, 2, 61, 'و هكذا اعتبروا في جيل فجيل ان جميع المتوكلين عليه لا يزلون'),
(2394, '1 Maccabees', 72, 2, 62, 'و لا تخشوا من كلام الرجل الخاطئ لان مجده ياول الى قذر ودود'),
(2395, '1 Maccabees', 72, 2, 63, 'اليوم يرتفع وغدا لا وجود له لانه يعود الى ترابه وتضمحل افكاره'),
(2396, '1 Maccabees', 72, 2, 64, 'فانتم ايها البنون تشددوا وكونوا رجالا في الشريعة فانكم بها ستمجدون'),
(2397, '1 Maccabees', 72, 2, 65, 'و هوذا سمعان اخوكم اني اعلم انه رجل مشورة فاسمعوا منه كل الايام وليكن لكم ابا'),
(2398, '1 Maccabees', 72, 2, 66, 'و يهوذا المكابي الشديد الباس منذ صباه هو يكون لكم رئيس الجيش ويتولى قتال الشعوب'),
(2399, '1 Maccabees', 72, 2, 67, 'و اجمعوا اليكم جميع العاملين بالشريعة وانتقموا لشعبكم انتقاما'),
(2400, '1 Maccabees', 72, 2, 68, 'كافئوا الامم مكافاة وواظبوا على وصايا الشريعة'),
(2401, '1 Maccabees', 72, 2, 69, 'ثم باركهم وانضم الى ابائه'),
(2402, '1 Maccabees', 72, 2, 70, 'و كانت وفاته في السنة المئة والسادسة والاربعين فدفنه بنوه في قبور ابائهم بمودين وبكى عليه جميع اسرائيل بكاء شديدا'),
(2403, '1 Maccabees', 72, 3, 1, 'فقام مكانه يهوذا ابنه المسمى بالمكابي'),
(2404, '1 Maccabees', 72, 3, 2, 'و كان كل اخوته وجميع الذين انضموا الى ابيه انصارا له يحاربون حرب اسرائيل بفرح'),
(2405, '1 Maccabees', 72, 3, 3, 'فزاد شعبه بسطة في العز ولبس لامته كجبار وتقلد سلاحه للقتال وباشر الحروب وبسيفه حمى الجيش'),
(2406, '1 Maccabees', 72, 3, 4, 'و كان كالاسد في حركاته وكالشبل الزائر على الفريسة'),
(2407, '1 Maccabees', 72, 3, 5, 'فتعقب اهل النفاق مستقصيا اثارهم واحرق الذين يفتنون شعبه بالنار'),
(2408, '1 Maccabees', 72, 3, 6, 'فنكص المنافقون خوفا منه واضطرب جميع فاعلي الاثم ونجح الخلاص على يده'),
(2409, '1 Maccabees', 72, 3, 7, 'و احنق ملوكا كثيرين وفرح يعقوب باعماله فصار ذكره مباركا مدى الدهر'),
(2410, '1 Maccabees', 72, 3, 8, 'و جال في مدن يهوذا واهلك الكفرة منها وصرف الغضب عن اسرائيل'),
(2411, '1 Maccabees', 72, 3, 9, 'فاشتهر الى اقاصي الارض وجمع المشرفين على الهلاك'),
(2412, '1 Maccabees', 72, 3, 10, 'و حشد ابلونيوس الامم وجاء بجيش عظيم من السامرة ليحارب اسرائيل'),
(2413, '1 Maccabees', 72, 3, 11, 'فلما علم يهوذا خرج للقائه فاوقع به وقتله وسقط قتلى كثيرون وانهزم الباقون'),
(2414, '1 Maccabees', 72, 3, 12, 'فسلب غنائمهم واخذ يهوذا سيف ابلونيوس فكان يقاتل به كل الايام'),
(2415, '1 Maccabees', 72, 3, 13, 'و سمع سارون قائد جيش سورية ان يهوذا قد عصب عصابة وجماعة من المؤمنين يسيرون معه الى القتال'),
(2416, '1 Maccabees', 72, 3, 14, 'فقال اقيم لنفسي اسما واتمجد في المملكة واقاتل يهوذا والذين معه من المستهينين بامر الملك'),
(2417, '1 Maccabees', 72, 3, 15, 'ثم تجهز للخروج وخرج معه جيش قوي من الكفرة يظاهرونه وينتقمون من بني اسرائيل'),
(2418, '1 Maccabees', 72, 3, 16, 'فدنوا الى عقبة بيت حورون فخرج يهوذا للقائهم في نفر يسير'),
(2419, '1 Maccabees', 72, 3, 17, 'فلما راوا الجيش مقبلا الى لقائهم قالوا ليهوذا كيف نطيق قتال مثل هذا الجمع القوي ونحن نفر يسير وقد استرخينا اليوم من الصوم'),
(2420, '1 Maccabees', 72, 3, 18, 'فقال يهوذا ما اسهل ان يدفع الكثيرون الى ايدي القليلين وسواء عند اله السماء ان يخلص بالكثيرين وبالقليلين'),
(2421, '1 Maccabees', 72, 3, 19, 'فانه ليس الظفر في الحرب بكثرة الجنود وانما القوة من السماء'),
(2422, '1 Maccabees', 72, 3, 20, 'اولئك ياتوننا بجمع من ذوي الشتائم والنفاق ليبيدونا نحن ونساءنا واولادنا ويسلبونا'),
(2423, '1 Maccabees', 72, 3, 21, 'و اما نحن فنحارب عن نفوسنا وسنننا'),
(2424, '1 Maccabees', 72, 3, 22, 'و هو يكسرهم امام وجوهنا فلا تخافوهم'),
(2425, '1 Maccabees', 72, 3, 23, 'و لما فرغ من كلامه هجم عليهم بغتة فانكسر سارون وجيشه امامه'),
(2426, '1 Maccabees', 72, 3, 24, 'فتتبعه في عقبة بيت حورون الى السهل فسقط منهم ثماني مئة رجل وانهزم الباقون الى ارض فلسطين'),
(2427, '1 Maccabees', 72, 3, 25, 'فوقع خوف يهوذا واخوته ورعبهم على الامم الذين حولهم'),
(2428, '1 Maccabees', 72, 3, 26, 'و بلغ ذكره الى الملك وتحدثت الامم كلها بوقائع يهوذا'),
(2429, '1 Maccabees', 72, 3, 27, 'فلما سمع انطيوكس الملك بهذا الكلام استشاط غضبا وارسل وجمع كل جيوش مملكته عسكرا شديدا جدا'),
(2430, '1 Maccabees', 72, 3, 28, 'و فتح خزانته ودفع الى جيوشه وظائف سنة وامرهم بان يكونوا متاهبين لكل شيء'),
(2431, '1 Maccabees', 72, 3, 29, 'ثم راى ان الفضة قد نفدت من الخزائن وقد قل جباة ضرائب البلاد لسبب الفتنة والضربة التي احدثها في الارض لينسخ السنن التي كانت لها منذ ايام القدم'),
(2432, '1 Maccabees', 72, 3, 30, 'و خشي انه لا يملك ما يقوم بنفقاته وعطاياه التي طال ما كان يجود بها جودا واسعا فاق به الملوك الذين كانوا من قبله'),
(2433, '1 Maccabees', 72, 3, 31, 'فتحير في نفسه حيرة شديدة وازمع ان يذهب الى بلاد فارس وياخذ جزية البلاد ويجبي مالا جزيلا'),
(2434, '1 Maccabees', 72, 3, 32, 'فاستخلف ليسياس على امور الملك من نهر الفرات الى حدود مصر وهو رجل شريف من النسل الملكي'),
(2435, '1 Maccabees', 72, 3, 33, 'و ان يتولى تربية انطيوكوس ابنه الى ان يعود'),
(2436, '1 Maccabees', 72, 3, 34, 'و فوض اليه شطر الجيش والفيلة وامره بكل ما كان في نفسه وبامر سكان اليهودية واورشليم'),
(2437, '1 Maccabees', 72, 3, 35, 'ان يوجه اليهم جيشا يكسر ويستاصل شوكة اسرائيل وبقية اورشليم ويمحو ذكرهم من المكان'),
(2438, '1 Maccabees', 72, 3, 36, 'و ينزل في جميع تخومهم ابناء الاجانب ويقسم الارض بينهم'),
(2439, '1 Maccabees', 72, 3, 37, 'و اخذ الملك الشطر الباقي من الجيش وسار من انطاكية عاصمة ملكه في السنة المئة والسابعة والاربعين وعبر نهر الفرات وجال في الاقاليم العليا'),
(2440, '1 Maccabees', 72, 3, 38, 'فاختار ليسياس بطلماوس بن دوريمانس ونكانور وجرجياس رجالا ذوي باس من اصحاب الملك'),
(2441, '1 Maccabees', 72, 3, 39, 'و وجه منهم اربعين الف راجل وسبعة الاف فارس لياتوا ارض يهوذا ويدمروها على حسب امر الملك'),
(2442, '1 Maccabees', 72, 3, 40, 'فساروا بالجيش كله حتى بلغوا الى قرب عماوس ونزلوا هناك في ارض السهل'),
(2443, '1 Maccabees', 72, 3, 41, 'و سمع بخبرهم تجار البلاد فاخذوا من الفضة والذهب شيئا كثيرا وعبيدهم وجاءوا المحلة حتى يشتروا بني اسرائيل عبيدا لهمو انضمت اليهم جيوش سورية وارض الغرباء'),
(2444, '1 Maccabees', 72, 3, 42, 'و راى يهوذا واخوته تفاقم الشر وان الجيوش حالة في تخومهم وبلغهم كلام الملك انه امر باهلاك الشعب واستئصاله'),
(2445, '1 Maccabees', 72, 3, 43, 'فقال كل واحد لصاحبه هلم ننهض شعبنا من مذلته ونقاتل عن شعبنا واقداسنا'),
(2446, '1 Maccabees', 72, 3, 44, 'فاحتشدت الجماعة لتتاهب للقتال وتصلي وتسال الرافة والمراحم'),
(2447, '1 Maccabees', 72, 3, 45, 'و كانت اورشليم مهجورة كالقفر لا يدخلها ولا يخرج منها احد من بنيها وكان المقدس مدوسا وابناء الاجانب في القلعة التيكانت مسكنا للامم وقد زال الطرب عن يعقوب وبطل المزمار والكنارة'),
(2448, '1 Maccabees', 72, 3, 46, 'فاجتمعوا وساروا الى المصفاة قبالة اورشليم لان المصفاة كانت من قبل هي موضع الصلاة لاسرائيل'),
(2449, '1 Maccabees', 72, 3, 47, 'و صاموا في ذلك اليوم وتحزموا بالمسوح وحثوا الرماد على رؤوسهم ومزقوا ثيابهم'),
(2450, '1 Maccabees', 72, 3, 48, 'و نشروا كتاب الشريعة الذي كانت الامم تبحث فيه عن مثال لاصنامها'),
(2451, '1 Maccabees', 72, 3, 49, 'و اتوا بثياب الكهنوت وبالبواكير والعشور ثم دعوا النذراء الذين قد استوفوا ايامهم'),
(2452, '1 Maccabees', 72, 3, 50, 'و رفعوا اصواتهم الى السماء قائلين ما نصنع بهؤلاء والى اين ننطلق بهم'),
(2453, '1 Maccabees', 72, 3, 51, 'فان اقداسك قد ديست ودنست وكهنتك في النحيب والمذلة'),
(2454, '1 Maccabees', 72, 3, 52, 'و ها ان الامم قد اجتمعوا علينا ليبيدونا وانت عليم بما ياتمرون علينا'),
(2455, '1 Maccabees', 72, 3, 53, 'فكيف نستطيع الثبات امامهم ان لم تكن انت في نصرتنا'),
(2456, '1 Maccabees', 72, 3, 54, 'ثم نفخوا في الابواق وصرخوا بصوت عظيم'),
(2457, '1 Maccabees', 72, 3, 55, 'و بعد ذلك رتب يهوذا قواد الشعب رؤساء الالف والمئة والخمسين والعشرة'),
(2458, '1 Maccabees', 72, 3, 56, 'و امر من اخذ في بناء بيت او خطب امراة او غرس كرما او كان خائفا بان يرجع الى بيته بحسب الشريعة'),
(2459, '1 Maccabees', 72, 3, 57, 'ثم سار الجيش ونزلوا بجنوب عماوس'),
(2460, '1 Maccabees', 72, 3, 58, 'فقال يهوذا تنطقوا وكونوا ذوي باس وتاهبوا للغد لمقاتلة هذه الامم المجتمعة علينا لتبيدنا نحن واقداسنا'),
(2461, '1 Maccabees', 72, 3, 59, 'فانه خير لنا ان نموت في القتال ولا نعاين الشر في قومنا واقداسنا'),
(2462, '1 Maccabees', 72, 3, 60, 'و كما تكون مشيئته في السماء فليصنع بنا'),
(2463, '1 Maccabees', 72, 4, 1, 'و اخذ جرجياس خمسة الاف راجل والف فارس منتخبين وسار الجيش ليلا'),
(2464, '1 Maccabees', 72, 4, 2, 'ليهجموا على محلة اليهود ويوقعوا بهم بغتة وكان اهل القلعة ادلاء لهم'),
(2465, '1 Maccabees', 72, 4, 3, 'فسمع يهوذا فسار هو ورجال الباس ليضرب جيش الملك الذي في عماوس'),
(2466, '1 Maccabees', 72, 4, 4, 'و كان لا يزال متفرقا في خارج المحلة'),
(2467, '1 Maccabees', 72, 4, 5, 'فلما انتهى جرجياس الى محلة يهوذا ليلا لم يجد احدا فطلبهم في الجبال لانه قال انهم هربوا منا'),
(2468, '1 Maccabees', 72, 4, 6, 'فلما كان النهار ظهر يهوذا في السهل ومعه ثلاثة الاف رجل الا انهم لم يكن معهم من الجنن والسيوف ما يوافق مرادهم'),
(2469, '1 Maccabees', 72, 4, 7, 'و راوا ان جيش الامم قوي وعليه الدروع والخيل من حوله وهم مدربون على الحرب'),
(2470, '1 Maccabees', 72, 4, 8, 'فقال يهوذا لمن معه من الرجال لا تخافوا كثرتهم ولا تخشوا بطشهم'),
(2471, '1 Maccabees', 72, 4, 9, 'اذكروا كيف نجا اباؤنا في بحر القلزم حين تتبعهم فرعون بجيشه'),
(2472, '1 Maccabees', 72, 4, 10, 'فالان لنصرخن الى السماء لعله يرحمنا ويتذكر عهد ابائنا ويكسر هذا الجيش امامنا اليوم'),
(2473, '1 Maccabees', 72, 4, 11, 'فتعلم كل الامم ان لاسرائيل فاديا ومخلصا'),
(2474, '1 Maccabees', 72, 4, 12, 'و رفع الاجانب ابصارهم فراوهم مقبلين عليهم'),
(2475, '1 Maccabees', 72, 4, 13, 'فخرجوا من المحلة للقتال ونفخ اصحاب يهوذا في البوق'),
(2476, '1 Maccabees', 72, 4, 14, 'و اقتتلوا فانكسرت الامم وانهزمت الى السهل'),
(2477, '1 Maccabees', 72, 4, 15, 'و سقط جميع ساقتهم بالسيف فتعقبوهم الى جازر وسهول ادوم واشدود ويمنيا وكان الساقطون منهم ثلاثة الاف رجل'),
(2478, '1 Maccabees', 72, 4, 16, 'ثم رجع يهوذا وجيشه عن تعقبهم'),
(2479, '1 Maccabees', 72, 4, 17, 'و قال للشعب لا تطمعوا في الغنائم لان الحرب لا تزال قائمة علينا'),
(2480, '1 Maccabees', 72, 4, 18, 'فان جرجياس وجيشه بالقرب منا في الجبل فاثبتوا الان امام اعدائنا وقاتلوهم وبعد ذلك تاخذون الغنائم بامان'),
(2481, '1 Maccabees', 72, 4, 19, 'و لم يفرغ يهوذا من هذا الكلام حتى ظهرت فرقة تتشوف من الجبل'),
(2482, '1 Maccabees', 72, 4, 20, 'فرات انهم قد انكسروا وان المحلة قد احرقت كما دلهم على ذلك الدخان المتصاعد'),
(2483, '1 Maccabees', 72, 4, 21, 'فلما عاينوا ذلك خافوا جدا واذ راوا جيش يهوذا في السهل مستعدا للقتال'),
(2484, '1 Maccabees', 72, 4, 22, 'فروا جميعا الى ارض الاجانب'),
(2485, '1 Maccabees', 72, 4, 23, 'فرجع يهوذا الى غنائم المحلة فاخذوا ذهبا كثيرا وفضة وسمنجونيا وارجوانا بحريا واموالا جزيلة'),
(2486, '1 Maccabees', 72, 4, 24, 'و عادوا وهم يسبحون الرب ويباركونه الى السماء لانه صالح لان الى الابد رحمته'),
(2487, '1 Maccabees', 72, 4, 25, 'و كان في ذلك اليوم خلاص عظيم في اسرائيل'),
(2488, '1 Maccabees', 72, 4, 26, 'و وفد كل من نجا من الاجانب على ليسياس واخبروه بجميع ما وقع'),
(2489, '1 Maccabees', 72, 4, 27, 'فلما سمع ذلك بهت وانكسر عزمه اذ لم ينفذ في اسرائيل ما كان يريده ولم يتم ما امر به الملك'),
(2490, '1 Maccabees', 72, 4, 28, 'فلما كانت السنة القابلة جمع ليسياس ستة الاف راجل منتخبين وخمسة الاف فارس لمحاربتهم'),
(2491, '1 Maccabees', 72, 4, 29, 'فاتوا الى ادوم ثم نزلوا ببيت صور فلاقاهم يهوذا في عشرة الاف رجل'),
(2492, '1 Maccabees', 72, 4, 30, 'فراى جيشا قويا فصلى وقال مبارك انت يا مخلص اسرائيل الذي حطم بطش الجبار على يد عبده داود واسلم محلة الاجانب الى يد يوناتان بن شاول وحامل سلاحه'),
(2493, '1 Maccabees', 72, 4, 31, 'فالق هذا الجيش في ايدي شعبك اسرائيل وليخزوا مع جنودهم وفرسانهم'),
(2494, '1 Maccabees', 72, 4, 32, 'احلل عليهم الرعدة واذب تجبر قوتهم وليضطربوا وينسحقوا'),
(2495, '1 Maccabees', 72, 4, 33, 'اسقطهم بسيف محبيك وليسبحك بالاناشيد جميع الذين يعرفون اسمك'),
(2496, '1 Maccabees', 72, 4, 34, 'ثم التحم القتال فسقط من جيش ليسياس خمسة الاف رجل وصرعوا امامهم'),
(2497, '1 Maccabees', 72, 4, 35, 'فلما راى ليسياس انكسار جيشه وبسالة جيش يهوذا وانهم مستعدون بشجاعتهم اما للحياة واما للموت ذهب الى انطاكية وجمع جيشا من الغرباء ولما كثر جيشه الاول هم بالرجوع الى اليهودية'),
(2498, '1 Maccabees', 72, 4, 36, 'و ان يهوذا واخوته قالوا ها ان اعداءنا قد انسحقوا فلنصعد الان لتطهير المقادس وتدشينها'),
(2499, '1 Maccabees', 72, 4, 37, 'فاجتمع كل الجيش وصعدوا الى جبل صهيون'),
(2500, '1 Maccabees', 72, 4, 38, 'فراوا المقدس خاليا والمذبح منجسا والابواب محرقة وقد طلع النبات في الديار كما يطلع في غابة او جبل من الجبال والغرفات مهدومة'),
(2501, '1 Maccabees', 72, 4, 39, 'فمزقوا ثيابهم وناحوا نوحا عظيما وحثوا على رؤوسهم رمادا'),
(2502, '1 Maccabees', 72, 4, 40, 'و سقطوا بوجوههم على الارض ونفخوا في ابواق الاشارة وصرخوا الى السماء'),
(2503, '1 Maccabees', 72, 4, 41, 'حينئذ رتب يهوذا رجالا يصادمون اهل القلعة ريثما يطهر المقادس'),
(2504, '1 Maccabees', 72, 4, 42, 'و اختار كهنة لا عيب فيهم من ذوي الحرص على الشريعة'),
(2505, '1 Maccabees', 72, 4, 43, 'فطهروا المقادس ورفعوا الحجارة المدنسة الى موضع نجس'),
(2506, '1 Maccabees', 72, 4, 44, 'ثم ائتمروا في مذبح المحرقة المدنس ماذا يصنعون به'),
(2507, '1 Maccabees', 72, 4, 45, 'فخطرت لهم مشورة صالحة ان يهدموه لئلا يكون لهم عارا لتدنيس الامم اياه فهدموا المذبح'),
(2508, '1 Maccabees', 72, 4, 46, 'و وضعوا الحجارة في جبل البيت في موضع لائق الى ان ياتي نبي ويجيب عنها'),
(2509, '1 Maccabees', 72, 4, 47, 'ثم اخذوا حجارة غير منحوتة وفاقا للشريعة وبنوا المذبح الجديد على رسم الاول'),
(2510, '1 Maccabees', 72, 4, 48, 'و بنوا المقادس وداخل البيت وقدسوا الديار'),
(2511, '1 Maccabees', 72, 4, 49, 'و صنعوا انية مقدسة جديدة وحملوا المنارة ومذبح البخور والمائدة الى الهيكل'),
(2512, '1 Maccabees', 72, 4, 50, 'و بخروا على المذبح واوقدوا السرج التي على المنارة فكانت تضيء في الهيكل'),
(2513, '1 Maccabees', 72, 4, 51, 'و جعلوا الخبز على المائدة ونشروا السجوف واتموا جميع الاعمال التي عملوها'),
(2514, '1 Maccabees', 72, 4, 52, 'و بكروا في اليوم الخامس عشر من الشهر التاسع وهو كسلو في السنة المئة والثامنة والاربعين'),
(2515, '1 Maccabees', 72, 4, 53, 'و قدموا ذبيحة بحسب الشريعة على مذبح المحرقة الجديد الذي صنعوه'),
(2516, '1 Maccabees', 72, 4, 54, 'و في مثل الوقت واليوم الذي فيه دنسته الامم في ذلك اليوم دشن بالاناشيد والعيدان والكنارات والصنوج'),
(2517, '1 Maccabees', 72, 4, 55, 'فخر جميع الشعب على وجوههم وسجدوا للذي انجحهم وباركوه الى السماء'),
(2518, '1 Maccabees', 72, 4, 56, 'و اتموا تدشين المذبح في ثمانية ايام وقدموا المحرقات بفرح وذبحوا ذبيحة السلامة والحمد'),
(2519, '1 Maccabees', 72, 4, 57, 'و زينوا وجه الهيكل باكاليل من الذهب وتروس ودشنوا الابواب والغرفات وجعلوا لها مصاريع'),
(2520, '1 Maccabees', 72, 4, 58, 'فكان عند الشعب سرور عظيم جدا وازيل تعيير الامم'),
(2521, '1 Maccabees', 72, 4, 59, 'و رسم يهوذا واخوته وجماعة اسرائيل كلها ان يعيد لتدشين المذبح في وقته سنة فسنة مدة ثمانية ايام من اليوم الخامس والعشرين من شهر كسلو بسرور وابتهاج'),
(2522, '1 Maccabees', 72, 4, 60, 'و في ذلك الزمان بنوا على جبل صهيون من حوله اسوارا عالية وبروجا حصينة لئلا تجيء الامم وتطاه كما فعلت من قبل'),
(2523, '1 Maccabees', 72, 4, 61, 'و اقام ثم جيشا يحرسونه وحصنوا بيت صور صيانة له حتى يكون للشعب معقلا تلقاء ادوم'),
(2524, '1 Maccabees', 72, 5, 1, 'و لما سمعت الامم التي من حولهم ان قد بني المذبح ودشن المقدس كما كانا من قبل استشاطوا غضبا'),
(2525, '1 Maccabees', 72, 5, 2, 'و اتمروا ان يبيدوا من بينهم من نسل يعقوب وطفقوا يقتلون ويهلكون من الشعب'),
(2526, '1 Maccabees', 72, 5, 3, 'و كان يهوذا يحارب بني عيسو في ادوم عند اقربتين لانهم كانوا يضيقون على اسرائيل فضربهم ضربة عظيمة ودفعهم وسلب غنائمهم'),
(2527, '1 Maccabees', 72, 5, 4, 'و تذكر شر بني بيان الذين كانوا شركا ومعثرة للشعب يكمنون لهم على الطرق'),
(2528, '1 Maccabees', 72, 5, 5, 'فالجاهم الى البروج وحاصرهم وابسلهم واحرق بروجهم وكل من كان فيها بالنار'),
(2529, '1 Maccabees', 72, 5, 6, 'ثم عبر الى بني عمون فصادف عسكرا قويا وشعبا كثيرا تحت قيادة تيموتاوس'),
(2530, '1 Maccabees', 72, 5, 7, 'فواقعهم في حروب كثيرة فانكسروا امامه فاوقع بهم'),
(2531, '1 Maccabees', 72, 5, 8, 'و فتح يعزير وتوابعها ثم عاد الى اليهودية'),
(2532, '1 Maccabees', 72, 5, 9, 'و ان الامم الذين في جلعاد اجتمعوا على من كان من اسرائيل في تخومهم ليبيدوهم ففروا الى حصن دياتما'),
(2533, '1 Maccabees', 72, 5, 10, 'و ارسلوا كتابا الى يهوذا واخوته قائلين ان الامم الذين حولنا قد اجتمعوا علينا يريدون ابادتنا'),
(2534, '1 Maccabees', 72, 5, 11, 'و في عزمهم ان ياتوا ويستفتحوا الحصن الذي التجانا اليه وجيشهم تحت قيادة تيموتاوس'),
(2535, '1 Maccabees', 72, 5, 12, 'فالان هلم واستنقذنا من ايديهم فقد سقط منا عدد كثير'),
(2536, '1 Maccabees', 72, 5, 13, 'و جميع اخوتنا الذين في ارض طوب قد قتلوا وسبيت نساؤهم واولادهم وسلبت امتعتهم وهلك هناك نحو الف رجل'),
(2537, '1 Maccabees', 72, 5, 14, 'فبينما هم يقراون الكتاب اذا برسل اخرين قد وفدوا من الجليل وثيابهم ممزقة واخبروا بمثل ذلك'),
(2538, '1 Maccabees', 72, 5, 15, 'قائلين قد اجتمعوا علينا من بطلمايس وصور وصيدا وكل جليل الامم ليبيدونا'),
(2539, '1 Maccabees', 72, 5, 16, 'فلما سمع يهوذا والشعب هذا الكلام عقدوا مجمعا عظيما وتشاوروا فيما يصنعون باخوتهم الذين في الضيق تحت الحصار'),
(2540, '1 Maccabees', 72, 5, 17, 'فقال يهوذا لسمعان اخيه اختر لك رجالا وانطلق واستنقذ اخوتك الذين في الجليل وانا ويوناتان اخي ننطلق الى ارض جلعاد'),
(2541, '1 Maccabees', 72, 5, 18, 'و استخلف يوسف بن زكريا وعزريا قائدي الشعب مع بقية الجيش في اليهودية للمحافظة'),
(2542, '1 Maccabees', 72, 5, 19, 'و اوصاهما قائلا توليا امر هذا الشعب ولا تقيما على الامم حربا حتى نعود'),
(2543, '1 Maccabees', 72, 5, 20, 'فانقسمت الرجال ثلاثة الاف مع سمعان ينطلقون الى الجليل وثمانية الاف مع يهوذا الى ارض جلعاد'),
(2544, '1 Maccabees', 72, 5, 21, 'و انطلق سمعان الى الجليل وناصب الامم حروبا كثيرة فانكسرت الامم من وجهه فتتبعهم الى باب بطلمايس'),
(2545, '1 Maccabees', 72, 5, 22, 'فسقط من الامم ثلاثة الاف رجل وسلب غنائمهم'),
(2546, '1 Maccabees', 72, 5, 23, 'و اخذ الذين في الجليل وعربات مع النساء والاولاد وكل ما كان لهم وجاء بهم الى اليهودية بسرور عظيم'),
(2547, '1 Maccabees', 72, 5, 24, 'و اما يهوذا المكابي ويوناتان اخوه فعبرا الاردن وسارا مسيرة ثلاثة ايام في البرية'),
(2548, '1 Maccabees', 72, 5, 25, 'فصادفا النباطيين فتلقوهما بسلام وقصوا عليهما كل ما اصاب اخوتهما في ارض جلعاد'),
(2549, '1 Maccabees', 72, 5, 26, 'و ان كثيرين منهم قد حصروا في بصرة وباصر وعليم وكسفور ومكيد وقرنائيم وكلها مدن حصينة عظيمة'),
(2550, '1 Maccabees', 72, 5, 27, 'و انهم ايضا محصورون في سائر مدن ارض جلعاد والقوم مستعدون لمحاصرتهم غدا في الحصون والقبض عليهم وابادتهم جميعا في يوم واحد'),
(2551, '1 Maccabees', 72, 5, 28, 'فعدل يهوذا جيشه بغتة وتوجه جهة البرية الى باصر فاستحوذ على المدينة وقتل كل ذكر بحد السيف وسلب جميع غنائمهم واحرق المدينة بالنار'),
(2552, '1 Maccabees', 72, 5, 29, 'ثم قام من هناك ليلا وسار الى الحصن'),
(2553, '1 Maccabees', 72, 5, 30, 'و لما كان الصبح رفعوا ابصارهم فاذا بقوم كثيرين لا عدد لهم حاملين سلالم ومجانيق لفتح الحصن وهم محاصرون لهم'),
(2554, '1 Maccabees', 72, 5, 31, 'و راى يهوذا ان الحرب قد التحمت وقد علت جلبة المدينة الى السماء بالابواق والصراخ العظيم'),
(2555, '1 Maccabees', 72, 5, 32, 'فقال لرجال الجيش قاتلوا اليوم عن اخوتكم'),
(2556, '1 Maccabees', 72, 5, 33, 'و خرج في ثلاث فرق من ورائهم ونفخوا في الابواق وصرخوا في الصلاة'),
(2557, '1 Maccabees', 72, 5, 34, 'و علم جيش تيموتاوس انه المكابي فهربوا من وجهه فضربهم ضربة عظيمة فسقط منهم في ذلك اليوم ثمانية الاف رجل'),
(2558, '1 Maccabees', 72, 5, 35, 'ثم انصرف الى المصفاة وحاربها فافتتحها وقتل كل ذكر بها وسلب غنائمها واحرقها بالنار'),
(2559, '1 Maccabees', 72, 5, 36, 'و مضى من هناك فافتتح كسفور ومكيد وباصر وسائر مدن ارض جلعاد'),
(2560, '1 Maccabees', 72, 5, 37, 'و بعد هذه الامور جمع تيموتاوس جيشا اخر ونزل قبالة رافون في عبر الوادي'),
(2561, '1 Maccabees', 72, 5, 38, 'فارسل يهوذا رجالا يكشفون امر الجيش فاخبروه قائلين ان جميع الامم التي حولنا قد انضمت اليهم وهم جيش عظيم جدا'),
(2562, '1 Maccabees', 72, 5, 39, 'و قد استاجروا العرب يظاهرونهم ونزلوا في عبر الوادي وفي عزمهم ان ياتوك للقتال فخرج يهوذا لملاقاتهم'),
(2563, '1 Maccabees', 72, 5, 40, 'و قال تيموتاوس لرؤساء جيشه اذا بلغ يهوذا وجيشه الى وادي الماء فان عبر الينا اولا فلا نطيق الثبات امامه بل يتغلب علينا تغلبا'),
(2564, '1 Maccabees', 72, 5, 41, 'و ان تخوف وحل في عبر النهر جزنا اليه وتغلبنا عليه'),
(2565, '1 Maccabees', 72, 5, 42, 'فلما بلغ يهوذا الى وادي الماء اقام كتبة الشعب على الوادي وامرهم قائلا لا تدعوا احدا يحل ههنا بل لينطلقوا بجملتهم الى الحرب'),
(2566, '1 Maccabees', 72, 5, 43, 'و عبر اليهم وهو في المقدمة وكل الشعب وراءه فانكسرت امامه جميع الامم والقوا سلاحهم وفروا الى المعبد الذي في قرنائيم'),
(2567, '1 Maccabees', 72, 5, 44, 'فاستولى اليهود على المدينة واحرقوا المعبد مع كل من كان فيه بالنار وانكسر اهل قرنائيم ولم يطيقوا الثبات امام يهوذا'),
(2568, '1 Maccabees', 72, 5, 45, 'و جمع يهوذا كل من كان من اسرائيل في ارض جلعاد صغيرهم وكبيرهم ونساءهم واولادهم مع امتعتهم جيشا عظيما جدا لينصرف بهم الى ارض يهوذا'),
(2569, '1 Maccabees', 72, 5, 46, 'فبلغوا الى عفرون وهي مدينة عظيمة على المدخل حصينة جدا فلم يكن لهم ان يحيدوا عنها يمنة ولا يسرة الا ان يجوزوا فيوسطها'),
(2570, '1 Maccabees', 72, 5, 47, 'فاغلق اهل المدينة على انفسهم وردموا الابواب بالحجارة فارسا اليهم يهوذا بكلام السلم'),
(2571, '1 Maccabees', 72, 5, 48, 'قائلا انا نجوز في ارضك لنذهب الى ارضنا ولا يضركم احد انما نمر باقدامنا فابوا ان يفتحوا له'),
(2572, '1 Maccabees', 72, 5, 49, 'فامر يهوذا ان ينادى في المحلة بان يهجم كل واحد من المكان الذي هو فيه'),
(2573, '1 Maccabees', 72, 5, 50, 'فهجم رجال الباس وحاربوا المدينة كل ذلك اليوم وليلته كلها فاسلمت المدينة الى يديه'),
(2574, '1 Maccabees', 72, 5, 51, 'فاهلك كل ذكر بحد السيف ودمرها وسلب غنائمها واجتاز في المدينة من فوق القتلى'),
(2575, '1 Maccabees', 72, 5, 52, 'ثم عبروا الاردن الى السهل العظيم قبالة بيت شان'),
(2576, '1 Maccabees', 72, 5, 53, 'و كان يهوذا يجمع المتخلفين ويشجع الشعب طول الطريق حتى وصلوا الى ارض يهوذا'),
(2577, '1 Maccabees', 72, 5, 54, 'فصعدوا جبل صهيون بسرور وابتهاج وقدموا المحرقات لاجل انه لم يسقط احد منهم حتى رجعوا بسلام'),
(2578, '1 Maccabees', 72, 5, 55, 'و في الايام التي كان فيها يهوذا ويوناتان في جلعاد وسمعان اخوه في الجليل قبالة بطلمايس'),
(2579, '1 Maccabees', 72, 5, 56, 'سمع يوسف بن زكريا وعزريا رئيسا الجيش بما ابدوا من الحماسة والقتال'),
(2580, '1 Maccabees', 72, 5, 57, 'فقالا لنقم لنا نحن ايضا اسما ولننطلق لمحاربة الامم التي حولنا'),
(2581, '1 Maccabees', 72, 5, 58, 'ثم امرا الجيش الذي معهما فزحفوا على يمنيا'),
(2582, '1 Maccabees', 72, 5, 59, 'فخرج جرجياس ورجاله من المدينة الى ملاقاتهم للقتال'),
(2583, '1 Maccabees', 72, 5, 60, 'فانكسر يوسف وعزريا فتتبعوهما الى حدود اليهودية وسقط في ذلك اليوم من شعب اسرائيل الفا رجل وكانت في شعب اسرائيل حطمة عظيمة'),
(2584, '1 Maccabees', 72, 5, 61, 'ذلك لانهما لم يسمعا ليهوذا واخوته ظنا منهما بانهما يبديان حماسة'),
(2585, '1 Maccabees', 72, 5, 62, 'الا انهما لم يكونا من نسب اولئك الرجال الذين اوتوا خلاص اسرائيل على ايديهم'),
(2586, '1 Maccabees', 72, 5, 63, 'و عظم الرجل يهوذا واخوته جدا في عيون كل اسرائيل وجميع الامم التي سار اليها ذكرهم'),
(2587, '1 Maccabees', 72, 5, 64, 'و كانوا يجتمعون اليهم باصوات التهنئة'),
(2588, '1 Maccabees', 72, 5, 65, 'و خرج يهوذا واخوته وحاربوا بني عيسو في ارض الجنوب وضرب حبرون وتوابعها وهدم سورها واحرق البروج التيحولها'),
(2589, '1 Maccabees', 72, 5, 66, 'و سار قاصدا ارض الاجانب وجال في ارض السامرة'),
(2590, '1 Maccabees', 72, 5, 67, 'و في ذلك الحين سقط كهنة في الحرب وكانوا يريدون ان يبدوا حماسة فخرجوا الى الحرب عن غير تدبر'),
(2591, '1 Maccabees', 72, 5, 68, 'ثم توجه يهوذا الى اشدود في ارض الاجانب فهدم مذابحهم واحرق منحوتات الهتهم بالنار وسلب غنائم المدن وعاد الى ارض يهوذا'),
(2592, '1 Maccabees', 72, 6, 1, 'و فيما كان انطيوكس الملك يجول في الاقاليم العليا سمع بذكر المايس وهي مدينة بفارس مشهورة باموالها من الفضة والذهب'),
(2593, '1 Maccabees', 72, 6, 2, 'و ان بها هيكلا فيه كثير من الاموال وفيه سجوف الذهب والدروع والاسلحة التي تركها ثم الاسكندر بن فيلبس الملك المكدوني الذي كان اول ملك في اليونان'),
(2594, '1 Maccabees', 72, 6, 3, 'فاتى وحاول ان ياخذ المدينة وينهبها فلم يستطع لان الامر كان قد عرف عند اهل المدينة'),
(2595, '1 Maccabees', 72, 6, 4, 'فثاروا اليه وقاتلوه فهرب ومضى من هناك بغم شديد راجعا الى بابل'),
(2596, '1 Maccabees', 72, 6, 5, 'و جاءه في فارس مخبر بان الجيوش التي وجهت الى ارض يهوذا قد انكسرت'),
(2597, '1 Maccabees', 72, 6, 6, 'و ان ليسياس قد انهزم من وجههم وكان قد خرج عليهم في جيش في غاية القوة فتعززوا بالسلاح والذخائر والغنائم الكثيرة التي اخذوها ممن دمروهم من الجيوش'),
(2598, '1 Maccabees', 72, 6, 7, 'و هدموا الرجاسة التي كان قد بناها على المذبح في اورشليم وحوطوا المقدس بالاسوار الرفيعة كما كان من قبل وحصنوا بيت صور مدينتهم'),
(2599, '1 Maccabees', 72, 6, 8, 'فلما سمع الملك هذا الكلام بهت واضطرب جدا وانطرح على الفراش وقد اوقعه الغم في السقم لان الامر وقع على خلاف مشتهاه'),
(2600, '1 Maccabees', 72, 6, 9, 'فلبث هناك اياما كثيرة لانه تجدد فيه غم شديد وايقن بالموت'),
(2601, '1 Maccabees', 72, 6, 10, 'فدعا جميع اصحابه وقال لهم لقد شرد النوم عن عيني وسقط قلبي من الكرب'),
(2602, '1 Maccabees', 72, 6, 11, 'فقلت في نفسي الى اي بلاء صرت وما اعظم اللجة التي انا فيها بعد ان كنت مسرورا ومحبوبا في سلطاني'),
(2603, '1 Maccabees', 72, 6, 12, 'اني لاتذكر المساوئ التي صنعتها في اورشليم وكيف اخذت كل انية الذهب والفضة التي كانت فيها وارسلت لابادة سكان يهوذا بغير سبب'),
(2604, '1 Maccabees', 72, 6, 13, 'فانا اعلم باني لاجل ذلك اصابتني هذه البلايا وها انا اهلك بكمد شديد في ارض غريبة'),
(2605, '1 Maccabees', 72, 6, 14, 'ثم دعا فيلبس احد اصحابه واقامه على جميع مملكته'),
(2606, '1 Maccabees', 72, 6, 15, 'و دفع اليه تاجه وحلته وخاتمه واوصاه بتدبير انطيوكس ابنه وترشيحه للملك'),
(2607, '1 Maccabees', 72, 6, 16, 'و مات هناك انطيوكس الملك في السنة المئة والتاسعة والاربعين'),
(2608, '1 Maccabees', 72, 6, 17, 'و علم ليسياس ان الملك قد توفي وملك موضعه انطيوكس ابنه الذي رباه هو في حداثته وسماه باسم اوباطور'),
(2609, '1 Maccabees', 72, 6, 18, 'و كان اهل القلعة يصدون اسرائيل عن دخول المقادس ويحاولون الاضرار بهم من كل جانب وتوطيد الامم بينهم'),
(2610, '1 Maccabees', 72, 6, 19, 'فعزم يهوذا على الايقاع بهم وحشد جميع الشعب لمحاصرتهم'),
(2611, '1 Maccabees', 72, 6, 20, 'فاجتمعوا معا وحاصروهم سنة مئة وخمسين ونصب عليهم القذافات والمجانيق'),
(2612, '1 Maccabees', 72, 6, 21, 'فخرج بعض منهم من الحصار فانضم اليهم نفر منافقون من اسرائيل'),
(2613, '1 Maccabees', 72, 6, 22, 'و انطلقوا الى الملك وقالوا الى متى لا تجري القضاء ولا تنتقم لاخوتنا'),
(2614, '1 Maccabees', 72, 6, 23, 'انا ارتضينا بخدمة ابيك والعمل باوامره واتباع رسومه'),
(2615, '1 Maccabees', 72, 6, 24, 'و لذلك ابناء شعبنا يحاصرون القلعة بغضا لنا وكل من صادفوه منا قتلوه ونهبوا املاكنا'),
(2616, '1 Maccabees', 72, 6, 25, 'و لم يكتفوا بمد ايديهم علينا ولكنهم تجاوزا الى جميع تخومنا'),
(2617, '1 Maccabees', 72, 6, 26, 'و ها انهم قد زحفوا الى قلعة اورشليم ليستحوذوا عليها وعلى المقدس وحصنوا بيت صور'),
(2618, '1 Maccabees', 72, 6, 27, 'فالان ان لم تسرع وتبادرهم فسيصنعون شرا من ذلك فلا تقدر ان تكفهم'),
(2619, '1 Maccabees', 72, 6, 28, 'فلما سمع الملك غضب وجمع جميع اصحابه وقواد جيشه ورؤساء الفرسان'),
(2620, '1 Maccabees', 72, 6, 29, 'و جاءته من ممالك اخرى ومن جزائر البحار جنود مستاجرة'),
(2621, '1 Maccabees', 72, 6, 30, 'و كان عدد جيوشه مئة الف راجل وعشرين الف فارس واثنين وثلاثين فيلا مضراة على الحرب'),
(2622, '1 Maccabees', 72, 6, 31, 'فزحفوا مجتازين في ادوم ونزلوا عند بيت صور وحاربوا اياما كثيرة وصنعوا المجانيق فخرجوا واحرقوها بالنار وقاتلوا بباس'),
(2623, '1 Maccabees', 72, 6, 32, 'فسار يهوذا عن القلعة ونزل ببيت زكريا تجاه محلة الملك'),
(2624, '1 Maccabees', 72, 6, 33, 'فبكر الملك ووجه بباس جيشه الى طريق بيت زكريا فتاهبت الجيوش للقتال ونفخوا في الابواق'),
(2625, '1 Maccabees', 72, 6, 34, 'و اروا الفيلة عصير العنب والتوت حتى يهيجوها للقتال'),
(2626, '1 Maccabees', 72, 6, 35, 'ثم وزعوها على الفرق فجعلوا عند كل فيل الف رجل لابسين الدروع المسرودة وعلى رؤوسهم خوذ النحاس واقاموا لكل فيل خمسمئة فارس منتخبين'),
(2627, '1 Maccabees', 72, 6, 36, 'فكان اولئك حيثما وجد الفيل سبقوا اليه وحيثما ذهب ذهبوا معه لا يفارقونه'),
(2628, '1 Maccabees', 72, 6, 37, 'و كان على كل فيل برج حصين من الخشب يحميه مطوق بالمجانيق وعلى البرج اثنان وثلاثون رجلا من ذوي الباس يقاتلون منه والهندي يدير الفيل'),
(2629, '1 Maccabees', 72, 6, 38, 'و جعلوا سائر الفرسان من هنا وهناك على جانبي الجيش يحثونه ويكتنفونه في الشعاب'),
(2630, '1 Maccabees', 72, 6, 39, 'فلما لمعت الشمس على تروس الذهب والنحاس لمعت بها الجبال وتاججت كسرج من نار'),
(2631, '1 Maccabees', 72, 6, 40, 'و انتشر جيش الملك قسم على الجبال العالية وقسم في البطاح ومشوا بتحفظ وانتظام'),
(2632, '1 Maccabees', 72, 6, 41, 'فارتعد كل من سمع جلبتهم ودرجان جمهورهم وقعقعة سلاحهم فان الجيش كان عظيما وقويا جدا'),
(2633, '1 Maccabees', 72, 6, 42, 'فتقدم يهوذا وجيشه للمبارزة فسقط من جيش الملك ست مئة رجل'),
(2634, '1 Maccabees', 72, 6, 43, 'و راى العازار بن سواران واحدا من الفيلة عليه الدرع الملكية يفوق جميع الفيلة فظن ان عليه الملك'),
(2635, '1 Maccabees', 72, 6, 44, 'فبذل نفسه ليخلص شعبه ويقيم لنفسه اسما مخلدا'),
(2636, '1 Maccabees', 72, 6, 45, 'و عدا اليه مقتحما في وسط الفرقة يقتل يمنة ويسرة فتفرقوا عنه من هنا ومن هناك'),
(2637, '1 Maccabees', 72, 6, 46, 'و دخل بين قوائم الفيل حتى صار تحته وقتله فسقط عليه الى الارض فمات مكانه'),
(2638, '1 Maccabees', 72, 6, 47, 'و ان اليهود لما راوا سطوة الملك وبطش الجيوش ارتدوا عنهم'),
(2639, '1 Maccabees', 72, 6, 48, 'فصعد الملك بجيشه نحو اورشليم لملاقاتهم وزحف الى اليهودية وجبل صهيون'),
(2640, '1 Maccabees', 72, 6, 49, 'و عقد صلحا مع اهل بيت صور فخرجوا من المدينة لنفاد الطعام من عندهم مدة حصرهم فيها اذ كان سبت للارض'),
(2641, '1 Maccabees', 72, 6, 50, 'فاستولى الملك على بيت صور واقام هناك حرسا يحافظون عليها'),
(2642, '1 Maccabees', 72, 6, 51, 'و نزل عند المقدس اياما كثيرة ونصب هناك القذافات والمجانيق والات لرشق النار والحجارة وادوات لرمي السهام ومقاليع'),
(2643, '1 Maccabees', 72, 6, 52, 'و صنع اليهود مجانيق قبالة مجانيقهم وحاربوا اياما كثيرة');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(2644, '1 Maccabees', 72, 6, 53, 'و لم يكن في اوعيتهم طعام لانها كانت السنة السابعة وكان الذين لجاوا الى اليهودية من الامم قد اكلوا ما فضل من الذخيرة'),
(2645, '1 Maccabees', 72, 6, 54, 'فلم يبق في المقادس الا نفر يسير لان الجوع غلب عليهم فتفرقوا كل واحد الى موضعه'),
(2646, '1 Maccabees', 72, 6, 55, 'و بلغ ليسياس ان فيلبس الذي اقامه انطيوكس في حياته ليرشح انطيوكس ابنه للملك'),
(2647, '1 Maccabees', 72, 6, 56, 'قد رجع من فارس وماداي ومعه جيوش الملك التي سارت في صحبته وانه يحاول ان يتولى الامور'),
(2648, '1 Maccabees', 72, 6, 57, 'فبادر وسعى الى الملك والقواد والجيش وقال لهم انا لنضعف يوما بعد يوم وقد قل طعامنا والمكان الذي نحاصره حصين وامور المملكة تستحثنا'),
(2649, '1 Maccabees', 72, 6, 58, 'و الان فلنعاقد هؤلاء الناس ولنبرم صلحا معهم ومع جميع امتهم'),
(2650, '1 Maccabees', 72, 6, 59, 'و لنقرر لهم ان يسلكوا في سننهم كما كانوا من قبل فانهم لاجل سننهم التي نقضناها غضبوا وفعلوا كل ذلك'),
(2651, '1 Maccabees', 72, 6, 60, 'فحسن الكلام في عيون الملك والرؤساء فارسل اليهم في المصالحة فاجابوا'),
(2652, '1 Maccabees', 72, 6, 61, 'فحلف لهم الملك والرؤساء وعلى ذلك خرجوا من الحصن'),
(2653, '1 Maccabees', 72, 6, 62, 'فدخل الملك الى جبل صهيون وراى الموضع حصينا فنقض الحلف الذي حلفه وامر بهدم السور الذي حوله'),
(2654, '1 Maccabees', 72, 6, 63, 'ثم انصرف مسرعا ورجع الى انطاكية فوجد فيلبس قد استولى على المدينة فقاتله واخذ المدينة عنوة'),
(2655, '1 Maccabees', 72, 7, 1, 'و في السنة المئة والحادية والخمسين خرج ديمتريوس بن سلوقس من رومية وصعد في نفر يسير الى مدينة بالساحل وملك هناك'),
(2656, '1 Maccabees', 72, 7, 2, 'و لما دخل دار ملك ابائه قبضت الجيوش على انطيوكس وليسياس لتاتيه بهما'),
(2657, '1 Maccabees', 72, 7, 3, 'فلما علم بذلك قال لا تروني اوجههما'),
(2658, '1 Maccabees', 72, 7, 4, 'فقتلتهما الجيوش وجلس ديمتريوس على عرش ملكه'),
(2659, '1 Maccabees', 72, 7, 5, 'فاتاه جميع رجال النفاق والكفر من اسرائيل وفي مقدمتهم الكيمس وهو يطمع ان يصير كاهنا اعظم'),
(2660, '1 Maccabees', 72, 7, 6, 'و وشوا على الشعب عند الملك قائلين ان يهوذا واخوته قد اهلكوا اصحابك وطردونا عن ارضنا'),
(2661, '1 Maccabees', 72, 7, 7, 'فالان ارسل رجلا تثق به يذهب ويفحص عن جميع ما انزله بنا وببلاد الملك من الدمار ويعاقبهم مع جميع اعوانهم'),
(2662, '1 Maccabees', 72, 7, 8, 'فاختار الملك بكيديس احد اصحاب الملك امير عبر النهر وكان عظيما في المملكة وامينا للملك وارسله'),
(2663, '1 Maccabees', 72, 7, 9, 'هو والكيمس الكافر وقد قلده الكهنوت وامره ان ينتقم من بني اسرائيل'),
(2664, '1 Maccabees', 72, 7, 10, 'فسارا وقدما ارض يهوذا في جيش كثيف وانفذا رسلا الى يهوذا واخوته يخاطبونهم بالسلام مكرا'),
(2665, '1 Maccabees', 72, 7, 11, 'فلم يلتفتوا الى كلامهما لانهم راوهما قادمين في جيش كثيف'),
(2666, '1 Maccabees', 72, 7, 12, 'و اجتمعت الى الكيمس وبكيديس جماعة الكتبة يسالون حقوقا'),
(2667, '1 Maccabees', 72, 7, 13, 'و وافى الحسيديون وهم المقدمون في بني اسرائيل يسالونهما السلم'),
(2668, '1 Maccabees', 72, 7, 14, 'لانهم قالوا ان مع جيوشه كاهنا من نسل هرون فلا يظلمنا'),
(2669, '1 Maccabees', 72, 7, 15, 'فخاطبهم خطاب سلام وحلف لهم قائلا انا لا نريد بكم ولا باصحابكم سوءا'),
(2670, '1 Maccabees', 72, 7, 16, 'فصدقوه فقبض على ستين رجلا منهم وقتلهم في يوم واحد كما هو مكتوب'),
(2671, '1 Maccabees', 72, 7, 17, 'جعلوا لحوم اصفيائك وسفكوا دماءهم حول اورشليم ولم يكن لهم من دافن'),
(2672, '1 Maccabees', 72, 7, 18, 'فوقع خوفهم ورعبهم على جميع الشعب لانهم قالوا ليس فيهم شيء من الحق والعدل اذ نكثوا العهد والحلف الذي حلفوه'),
(2673, '1 Maccabees', 72, 7, 19, 'و ارتحل بكيديس عن اورشليم ونزل ببيت زيت وارسل وقبض على كثيرين من الذين كانوا قد خذلوه وعلى بعض من الشعب وذبحهم علىالجب العظيم'),
(2674, '1 Maccabees', 72, 7, 20, 'ثم سلم البلاد الى الكيمس وابقى معه جيشا يؤازره وانصرف بكيديس الى الملك'),
(2675, '1 Maccabees', 72, 7, 21, 'و كان الكيمس يجهد في تولى الكهنوت الاعظم'),
(2676, '1 Maccabees', 72, 7, 22, 'و اجتمع اليه جميع المفسدين في الشعب واستولوا على ارض يهوذا وضربوا اسرائيل ضربة عظيمة'),
(2677, '1 Maccabees', 72, 7, 23, 'و راى يهوذا جميع الشر الذي صنعه الكيمس ومن معه في بني اسرائيل وكان فوق ما صنعت الامم'),
(2678, '1 Maccabees', 72, 7, 24, 'فخرج الى جميع حدود اليهودية مما حولها وانزل نقمته بالقوم الذين خذلوه فكفوا عن مهاجمة البلاد'),
(2679, '1 Maccabees', 72, 7, 25, 'فلما راى الكيمس ان قد تقوى يهوذا ومن معه وعلم انه لا يستطيع الثبات امامهم رجع الى الملك ووشى عليهم بجرائم'),
(2680, '1 Maccabees', 72, 7, 26, 'فارسل الملك نكانور احد رؤسائه المشهورين وكان عدوا مبغضا لاسرائيل وامره بابادة الشعب'),
(2681, '1 Maccabees', 72, 7, 27, 'فوفد نكانور على اورشليم في جيش كثير وارسل الى يهوذا واخوته يخاطبهم بالسلام مكرا'),
(2682, '1 Maccabees', 72, 7, 28, 'قائلا لا يكن قتال بيني وبينكم فانني قادم في نفر قليل لاواجهكم بسلام'),
(2683, '1 Maccabees', 72, 7, 29, 'و جاء الى يهوذا وحيا بعضهما بعضا تحية السلم وكان الاعداء مستعدين لاختطاف يهوذا'),
(2684, '1 Maccabees', 72, 7, 30, 'و علم يهوذا ان مواجهته كانت مكرا فاجفل منه وابي ان يعود الى مواجهته'),
(2685, '1 Maccabees', 72, 7, 31, 'فلما راى نكانور ان مشورته قد كشفت خرج لملاقاة يهوذا بالقتال عند كفر سلامة'),
(2686, '1 Maccabees', 72, 7, 32, 'فسقط من جيش نكانور نحو خمسة الاف رجل وفر الباقون الى مدينة داود'),
(2687, '1 Maccabees', 72, 7, 33, 'و بعد هذه الامور صعد نكانور الى جبل صهيون فخرج بعض الكهنة من المقادس وبعض شيوخ الشعب يحيونه تحية السلم ويرونه المحرقات المقربة عن الملك'),
(2688, '1 Maccabees', 72, 7, 34, 'فاستهزا بهم وسخر منهم وتقذرهم وكلمهم بتجبر'),
(2689, '1 Maccabees', 72, 7, 35, 'و اقسم بغضب قائلا ان لم يسلم يهوذا وجيشه الى يدي اليوم فسيكون متى عدت بسلام اني احرق هذا البيت وخرج بحنق شديد'),
(2690, '1 Maccabees', 72, 7, 36, 'فدخل الكهنة ووقفوا امام المذبح والهيكل وبكوا وقالوا'),
(2691, '1 Maccabees', 72, 7, 37, 'انك يا رب قد اخترت هذا البيت ليدعى فيه باسمك ويكون بيت صلاة وتضرع لشعبك'),
(2692, '1 Maccabees', 72, 7, 38, 'فانزل النقمة بهذا الرجل وجيشه وليسقطوا بالسيف واذكر تجاديفهم ولا تبق عليهم'),
(2693, '1 Maccabees', 72, 7, 39, 'ثم خرج نكانور من اورشليم ونزل ببيت حورون فانحاز اليه جيش سورية'),
(2694, '1 Maccabees', 72, 7, 40, 'و نزل يهوذا باداسة في ثلاثة الاف رجل وصلى يهوذا وقال'),
(2695, '1 Maccabees', 72, 7, 41, 'انه لما جدف الذين كانوا مع ملك اشور خرج ملاكك يا رب وضرب مئة الف وخمسة وثمانين الفا منهم'),
(2696, '1 Maccabees', 72, 7, 42, 'هكذا فاحطم هذا الجيش امامنا اليوم فيعلم الباقون انهم تكلموا على اقداسك سوءا واقض عليه بحسب خبثه'),
(2697, '1 Maccabees', 72, 7, 43, 'ثم الحم الجيشان القتال في اليوم الثالث عشر من شهر اذار فانكسر جيش نكانور وكان هو اول من سقط في القتال'),
(2698, '1 Maccabees', 72, 7, 44, 'فلما راى جيش نكانور انه قد سقط القوا اسلحتهم وهربوا'),
(2699, '1 Maccabees', 72, 7, 45, 'فتعقبوهم مسيرة يوم من اداسة الى مدخل جازر ونفخوا وراءهم في ابواق الاشارة'),
(2700, '1 Maccabees', 72, 7, 46, 'فخرج الناس من جميع قرى اليهودية من كل جانب وصدموهم فارتدوا الى جهة الذين يتعقبونهم فسقطوا جميعهم بالسيف ولم يبق منهم احد'),
(2701, '1 Maccabees', 72, 7, 47, 'فاخذوا الغنائم والاسلاب وقطعوا راس نكانور ويمينه التي مدها بتجبر واتوا بهما وعلقوهما قبالة اورشليم'),
(2702, '1 Maccabees', 72, 7, 48, 'ففرح الشعب جدا وقضوا ذلك النهار بمسرة عظيمة'),
(2703, '1 Maccabees', 72, 7, 49, 'و رسموا ان يعيد ذلك اليوم الثالث عشر من اذار كل سنة'),
(2704, '1 Maccabees', 72, 7, 50, 'و هدات ارض يهوذا اياما يسيرة'),
(2705, '1 Maccabees', 72, 8, 1, 'و سمع يهوذا باسم الرومانيين انهم ذوو اقتدار عظيم ويعزون كل من ضوى اليهم وكل من جاءهم اثروه بمودتهم ولهم شوكة شديدة'),
(2706, '1 Maccabees', 72, 8, 2, 'و قصت عليه وقائعهم وما ابدوا من الحماسة في قتال الغاليين وانهم اخضعوهم وضربوا عليهم الجزية'),
(2707, '1 Maccabees', 72, 8, 3, 'و ما فعلوا في بلاد اسبانية واستيلاؤهم على معادن الفضة والذهب التي هناك وانهم اخضعوا كل مكان بمشورتهم وطول اناتهم'),
(2708, '1 Maccabees', 72, 8, 4, 'و ان كان ذلك المكان عنهم بمسافة بعيدة وكسروا الذين اغاروا عليهم من الملوك من اقاصي الارض وضربوهم ضربة عظيمة وانسائر الملوك يحملون اليهم الجزية كل سنة'),
(2709, '1 Maccabees', 72, 8, 5, 'و قد قهروا فيلبس وفرساوس ملك كتيم في الحرب وكل من قاتلهم واخضعوهم'),
(2710, '1 Maccabees', 72, 8, 6, 'و كسروا انطيوكس الكبير ملك اسية الذي زحف لقتالهم ومعه مئة وعشرون فيلا وفرسان وعجلات وجيش كثير جدا'),
(2711, '1 Maccabees', 72, 8, 7, 'و قبضوا عليه حيا وضربوا عليه وعلى الذين يملكون بعده جزية عظيمة ورهائن ووضائع معلومة'),
(2712, '1 Maccabees', 72, 8, 8, 'و ان يتركوا بلاد الهند وماداي ولود وخيار بلادهم واخذوها منه واعطوها لاومينيس الملك'),
(2713, '1 Maccabees', 72, 8, 9, 'و لما هم اليونان ان يسيروا لمقاتلتهم بلغهم ذلك'),
(2714, '1 Maccabees', 72, 8, 10, 'فارسلوا اليهم قائدا واحدا وحاربوهم فسقط منهم قتلى كثيرون وسبوا نساءهم واولادهم ونهبوهم واستولوا على ارضهم وهدموا حصونهم واستعبدوهم الى هذا اليوم'),
(2715, '1 Maccabees', 72, 8, 11, 'و دمروا سائر الممالك والجزائر التي قاومتهم واستعبدوا سكانها'),
(2716, '1 Maccabees', 72, 8, 12, 'و انهم حفظوا المودة لاوليائهم والذين اعتمدوا عليهم وتسلطوا على الممالك قريبها وبعيدها وكل من سمع باسمهم خافهم'),
(2717, '1 Maccabees', 72, 8, 13, 'و من ارادوا مؤازرته وتمليكه ملكوه ومن ارادوا خلعه خلعوه فعلا شانهم جدا'),
(2718, '1 Maccabees', 72, 8, 14, 'و مع ذلك كله لم يلبس احد منهم التاج ولا تردى الارجوان مباهاة به'),
(2719, '1 Maccabees', 72, 8, 15, 'و انما وضعوا لهم شورى ياتمر فيها كل يوم ثلاث مئة وعشرون رجلا لاصلاح شؤونهم'),
(2720, '1 Maccabees', 72, 8, 16, 'و هم يفوضون سلطانهم وسياسة ارضهم بجملتها كل سنة الى رجل واحد وجميعهم يطيعون هذا الواحد وليس فيهم حسد ولا منافسة'),
(2721, '1 Maccabees', 72, 8, 17, 'فاختار يهوذا اوبولمس بن يوحنا بن اكوس وياسون بن العازار وارسلهما الى رومية ليعقدا معهم عهد الموالاة والمناصرة'),
(2722, '1 Maccabees', 72, 8, 18, 'و يرفعا عنهم النير لانهم راوا ان دولة اليونان قد استعبدت اسرائيل استعبادا'),
(2723, '1 Maccabees', 72, 8, 19, 'فانطلقا الى رومية في سفر بعيد جدا ودخلا الشورى وتكلما وقالا'),
(2724, '1 Maccabees', 72, 8, 20, 'انا مرسلان اليكم من قبل يهوذا المكابي واخوته وجمهور اليهود لنعقد معكم عهد المناصرة والمسالمة وان تثبتونا في جملة مناصريكم واوليائكم'),
(2725, '1 Maccabees', 72, 8, 21, 'فحسن الكلام لديهم'),
(2726, '1 Maccabees', 72, 8, 22, 'و هذه نسخة الكتاب الذي دونوه على الواح من نحاس وارسلوه الى اورشليم حتى يكون عندهم تذكار للمسالمة والمناصرة'),
(2727, '1 Maccabees', 72, 8, 23, 'الفلاح للرومانيين ولامة اليهود في البحر والبر الى الابد وليبعد عنهم السيف والعدو'),
(2728, '1 Maccabees', 72, 8, 24, 'اذا قامت حرب في رومية اولا او عند اي كان من مناصريهم في جميع سلطانهم'),
(2729, '1 Maccabees', 72, 8, 25, 'فامة اليهود تناصر بكل عزمها كما تقتضيه الحال'),
(2730, '1 Maccabees', 72, 8, 26, 'و ليس على الرومانيين ان يؤدوا الى المحاربين معهم او يجهروا لهم طعاما ولا اسلحة ولا فضة ولا سفنا كذلك حسن عند الرومانيين لكن يحافظون على اوامر الرومانيين بغير ان ياخذوا شيئا'),
(2731, '1 Maccabees', 72, 8, 27, 'و كذلك امة اليهود اذا حدثت لها حرب اولا فالرومانيون ينتدبون للمناصرة كما تقتضيه الحال'),
(2732, '1 Maccabees', 72, 8, 28, 'و ليس على اليهود ان يؤدوا الى المناصرين طعاما ولا اسلحة ولا فضة ولاسفنا كذلك حسن عند الرومانيين لكن يحافظون على اوامر اليهود دون غش'),
(2733, '1 Maccabees', 72, 8, 29, 'على هذا الكلام عاهد الرومانيون شعب اليهود'),
(2734, '1 Maccabees', 72, 8, 30, 'و اذا شاء هؤلاء او اولئك ان يزيدوا على هذا الكلام او يسقطوا منه فيفعلون برضى الفريقين وكل ما زادوا او اسقطوا يكون مقررا'),
(2735, '1 Maccabees', 72, 8, 31, 'اما الشرور التي انزلها بهم الملك ديمتريوس فقد كتبنا اليه قائلين لم ثقلت النير على اوليائنا ومناصرينا اليهود'),
(2736, '1 Maccabees', 72, 8, 32, 'فان عادوا يتظلمون منك فسنجري لهم الحكم ونقاتلك بحرا وبرا'),
(2737, '1 Maccabees', 72, 9, 1, 'و لما سمع ديمتريوس بان نكانور وجيوشه قد سقطوا في الحرب عاد ثانية فارسل الى ارض يهوذا بكيديس والكيمس ومعهما الجناح الايمن'),
(2738, '1 Maccabees', 72, 9, 2, 'فانطلقا في طريق الجلجال ونزلا عند مشالوت باربيل فاستولى عليها واهلكا نفوسا كثيرة'),
(2739, '1 Maccabees', 72, 9, 3, 'و في الشهر الاول من السنة المئة والثانية والخمسين نزلا على اورشليم'),
(2740, '1 Maccabees', 72, 9, 4, 'ثم زحفا وانطلقا الى بئروت في عشرين الف راجل والفي فارس'),
(2741, '1 Maccabees', 72, 9, 5, 'و كان يهوذا قد نزل بلاشع ومعه ثلاثة الاف رجل منتخبين'),
(2742, '1 Maccabees', 72, 9, 6, 'فلما راوا كثرة عدد الجيوش خافوا خوفا شديدا فجعل كثيرون ينسابون من المحلة ولم يبق منهم الا ثماني مئة رجل'),
(2743, '1 Maccabees', 72, 9, 7, 'فلما راى يهوذا ان جيشه قد انساب والحرب تضايقه انكسر قلبه لانه لم يبق له وقت لردهم واسترخت عزائمه'),
(2744, '1 Maccabees', 72, 9, 8, 'فقال لمن بقي معه لنقم ونهجم على مناصبينا عسى ان نقدر على مدافعتهم'),
(2745, '1 Maccabees', 72, 9, 9, 'فصرفوه عن عزمه قائلين انه ليس في طاقاتنا اليوم الا ان ننجو بنفوسنا ثم نرجع مع اخواتنا ونقاتلهم فانا عدد قليل'),
(2746, '1 Maccabees', 72, 9, 10, 'فقال يهوذا حاش لي ان افعل مثل ذلك واهرب منهم وان كان قد دنا اجلنا فلنموتن بشجاعة عن اخواتنا ولا نبقين على مجدنا وصمة'),
(2747, '1 Maccabees', 72, 9, 11, 'و برز جيش العدو من المحلة ووقفوا بازائهم وانقسمت الفرسان قسمين وكان الرماة بالمقاليع والقسي يتقدمون الجيش كلها من ذوي الباس'),
(2748, '1 Maccabees', 72, 9, 12, 'و كان بكيديس في الجناح الايمن فازدلفت الفرقة من الجانبين وهتفوا بالابواق'),
(2749, '1 Maccabees', 72, 9, 13, 'و نفخ رجال يهوذا ايضا في الابواق فارتجت الارض من جلبة العسكرين والتحم القتال من الصبح الى المساء'),
(2750, '1 Maccabees', 72, 9, 14, 'و راى يهوذا ان بكيديس وقوة الجيش في الجناح الايمن فقصدهم ومعه كل ذي قلب ثابت'),
(2751, '1 Maccabees', 72, 9, 15, 'فكسروا الجناح الايمن وتعقبوا اثرهم الى جبل اشدود'),
(2752, '1 Maccabees', 72, 9, 16, 'فلما راى رجال الجناح الايسر انكسار الجناح الايمن انقلبوا على اثار يهوذا ومن معه'),
(2753, '1 Maccabees', 72, 9, 17, 'فاشتد القتال وسقط قتلى كثيرون من الفريقين'),
(2754, '1 Maccabees', 72, 9, 18, 'و سقط يهوذا وهرب الباقون'),
(2755, '1 Maccabees', 72, 9, 19, 'فحمل يوناتان وسمعان يهوذا اخاهما ودفناه في قبر ابائه في مودين'),
(2756, '1 Maccabees', 72, 9, 20, 'فبكاه شعب اسرائيل بكاء عظيما ولطموا عليه وناحوا اياما وقالوا'),
(2757, '1 Maccabees', 72, 9, 21, 'كيف سقط البطل مخلص اسرائيل'),
(2758, '1 Maccabees', 72, 9, 22, 'و بقية اخبار يهوذا وحروبه وما ابداه من الحماسة وجبروته لم تكتب في هذا الموضع لانها كثيرة جدا'),
(2759, '1 Maccabees', 72, 9, 23, 'و كان بعد وفاة يهوذا ان المنافقين برزوا في جميع تخوم اسرائيل وظهر كل فاعلي الاثم'),
(2760, '1 Maccabees', 72, 9, 24, 'و في تلك الايام حدثت مجاعة عظيمة جدا فتخاذلت البلاد اليهم'),
(2761, '1 Maccabees', 72, 9, 25, 'فاختار بكيديس الكفرة منهم واقامهم رؤساء على البلاد'),
(2762, '1 Maccabees', 72, 9, 26, 'فكانوا يتطلبون اصحاب يهوذا ويتفقدونهم وياتون بهم الى بكيديس فينتقم منهم ويستهزئ بهم'),
(2763, '1 Maccabees', 72, 9, 27, 'فحل باسرائيل ضيق عظيم لم يحدث مثله منذ لم يظهر فيهم نبي'),
(2764, '1 Maccabees', 72, 9, 28, 'فاجتمع جميع اصحاب يهوذا وقالوا ليوناتان'),
(2765, '1 Maccabees', 72, 9, 29, 'انه منذ وفاة يهوذا اخيك لم يقم له كفؤ يخرج على العدو وعلى بكيديس والمبغضين لامتنا'),
(2766, '1 Maccabees', 72, 9, 30, 'فنحن نختارك اليوم رئيسا لنا وقائدا مكانه تحارب حربنا'),
(2767, '1 Maccabees', 72, 9, 31, 'فقبل يوناتان القيادة في ذلك الوقت وقام في موضع يهوذا اخيه'),
(2768, '1 Maccabees', 72, 9, 32, 'فلما علم بكيديس طلب قتله'),
(2769, '1 Maccabees', 72, 9, 33, 'و بلغ ذلك يوناتان وسمعان اخاه وجميع من معه فهربوا الى برية تقوع ونزلوا على ماء جب اسفار'),
(2770, '1 Maccabees', 72, 9, 34, 'فعلم بكيديس فزحف بجميع جيشه الى عبر الاردن يوم سبت'),
(2771, '1 Maccabees', 72, 9, 35, 'و ارسل يوناتان يوحنا اخاه بجماعة تحت قيادته يسال النباطيين اولياءه ان يعيروهم عدتهم الوافرة'),
(2772, '1 Maccabees', 72, 9, 36, 'فخرج بنو يمري من ميدابا وقبضوا على يوحنا وكل ما معه وذهبوا بالجميع'),
(2773, '1 Maccabees', 72, 9, 37, 'و بعد هذه الامور اخبر يوناتان وسمعان اخوه ان بني يمري يقيمون عرسا عظيما ويزفون العروس من ميدابا باحتفال عظيم وهيابنة بعض عظماء كنعان'),
(2774, '1 Maccabees', 72, 9, 38, 'فذكروا يوحنا اخاهم وصعدوا واختباوا وراء الجبل'),
(2775, '1 Maccabees', 72, 9, 39, 'ثم رفعوا ابصارهم ونظروا فاذا بجلبة وجهاز كثير والعروس واصحابه واخوته خارجون للقائهم بالدفوف والات الطرب واسلحة كثيرة'),
(2776, '1 Maccabees', 72, 9, 40, 'فثار عليهم رجال يوناتان من المكمن وضربوهم فسقط قتلى كثيرون وهرب الباقون الى الجبل فاخذوا كل اسلابهم'),
(2777, '1 Maccabees', 72, 9, 41, 'و تحول العرس الى مناحة وصوت الات طربهم الى نحيب'),
(2778, '1 Maccabees', 72, 9, 42, 'و لما انتقموا لدم اخيهم رجعوا الى غيضة الاردن'),
(2779, '1 Maccabees', 72, 9, 43, 'فسمع بكيديس فوفد الى شطوط الاردن يوم سبت في جيش عظيم'),
(2780, '1 Maccabees', 72, 9, 44, 'فقال يوناتان لمن معه لننهض الان ونقاتل عن نفوسنا فليس الامر اليوم كما كان امس فما قبل'),
(2781, '1 Maccabees', 72, 9, 45, 'ها ان الحرب امامنا وخلفنا وماء الاردن والغياض والغاب من هنا ومن هناك فليس لنا مناص'),
(2782, '1 Maccabees', 72, 9, 46, 'و الان فاصرخوا الى السماء فتنقذوا من ايدي اعدائكم ثم التحم القتال'),
(2783, '1 Maccabees', 72, 9, 47, 'و مد يوناتان يده ليضرب بكيديس فانصاع عنه الى الوراء'),
(2784, '1 Maccabees', 72, 9, 48, 'فرمى يوناتان ومن معه بانفسهم في الاردن وعاموا الى العبر فلم يعبروا الاردن اليهم'),
(2785, '1 Maccabees', 72, 9, 49, 'و سقط من رجال بكيديس في ذلك اليوم الف رجل فعاد الى اورشليم'),
(2786, '1 Maccabees', 72, 9, 50, 'ثم بنى مدائن حصينة في اليهودية وحصن اريحا وعماوس وبيت حورون وبيت ايل وتمنة وفرعتون وتفون باسوار عالية وابواب ومزاليج'),
(2787, '1 Maccabees', 72, 9, 51, 'و جعل فيها حرسا يراغمون اسرائيل'),
(2788, '1 Maccabees', 72, 9, 52, 'و حصن مدينة صور وجازر والقلعة وجعل فيها جيوشا وميرة'),
(2789, '1 Maccabees', 72, 9, 53, 'و اخذ ابناء قواد البلاد رهائن وجعلهم في القلعة باورشليم في الحبس'),
(2790, '1 Maccabees', 72, 9, 54, 'و في السنة الثالثة والخمسين في الشهر الثاني امر الكيمس ان يهدم حائط دار المقدس الداخلية فهدم اعمال الانبياء وشرع في التدمير'),
(2791, '1 Maccabees', 72, 9, 55, 'في ذلك الزمان ضرب الكيمس فكف عن صنيعه واعتقل لسانه وفلج ولم يعد يستطيع ان ينطق بكلمة ولا ان يوصي لبنيه'),
(2792, '1 Maccabees', 72, 9, 56, 'و مات الكيمس في ذلك الزمان في عذاب شديد'),
(2793, '1 Maccabees', 72, 9, 57, 'فلما راى بكيديس ان الكيمس قد مات رجع الى الملك وهدات ارض يهوذا سنتين'),
(2794, '1 Maccabees', 72, 9, 58, 'و بعد ائتمر المنافقون كلهم وقالوا ها ان يوناتان والذين معه في منازلهم هادئون مطمئنون فهلموا الان نحمل عليهم بكيديس فيقبض عليهم اجمعين في ليلة واحدة'),
(2795, '1 Maccabees', 72, 9, 59, 'و انطلقوا واشاروا عليه بذلك'),
(2796, '1 Maccabees', 72, 9, 60, 'فقام وسار في جيش عظيم وبعث سرا يكتب الى جميع نصرائه في اليهودية ان يقبضوا على يوناتان والذين معه فلم يجدوا الى ذلك سبيلا لان مشورتهم انكشفت لهم'),
(2797, '1 Maccabees', 72, 9, 61, 'ثم قبضوا على خمسين رجلا من البلاد وهم ارباب الفتنة وقتلوهم'),
(2798, '1 Maccabees', 72, 9, 62, 'و انصرف يوناتان وسمعان ومن معهما الى بيت حجلة في البرية وبنى مهدومها وحصنها'),
(2799, '1 Maccabees', 72, 9, 63, 'و لما علم بكيديس حشد جميع جمهوره وراسل حلفاءه في اليهودية'),
(2800, '1 Maccabees', 72, 9, 64, 'و زحف ونزل على بيت حجلة وحاربها اياما كثيرة ونصب المجانيق'),
(2801, '1 Maccabees', 72, 9, 65, 'و ان يوناتان ترك سمعان اخاه في المدينة وخرج في عدد من الجند وانتشر في البلاد'),
(2802, '1 Maccabees', 72, 9, 66, 'و ضرب ادورين واخوته وبني فاسرون في خيامهم وطفق يوقع بالعدو ويزداد قوة'),
(2803, '1 Maccabees', 72, 9, 67, 'و خرج سمعان ومن معه من المدينة واحرقوا المجانيق'),
(2804, '1 Maccabees', 72, 9, 68, 'و قاتلوا بكيديس فانكسر وضايقوه جدا واذ ذهبت مشورته وخروجه في الباطل'),
(2805, '1 Maccabees', 72, 9, 69, 'استشاط غضبا على الرجال المنافقين الذين اشاروا عليه بالخروج من البلاد وقتل كثيرين منهم وازمع الانصراف الى ارضه'),
(2806, '1 Maccabees', 72, 9, 70, 'و علم يوناتان فانفذ اليه رسلا في عقد المصالحة ورد الاسرى'),
(2807, '1 Maccabees', 72, 9, 71, 'فاجاب وفعل بحسب كلامه وحلف له انه لن يطلبه بسوء كل ايام حياته'),
(2808, '1 Maccabees', 72, 9, 72, 'و رد اليه الاسرى الذين اسرهم من قبل في ارض يهوذا ثم عاد الى ارضه ولم يعد يسير الى تخومهم'),
(2809, '1 Maccabees', 72, 9, 73, 'فزال السيف من اسرائيل وسكن يوناتان في مكماش واخذ يوناتان يحاكم الشعب واستاصل المنافقين من اسرائيل'),
(2810, '1 Maccabees', 72, 10, 1, 'و في السنة المئة والستين صعد الاسكندر الشهير ابن انطيوكس وفتح بطلمايس فقبلوه فملك هناك'),
(2811, '1 Maccabees', 72, 10, 2, 'فسمع ديمتريوس الملك فجمع جيوشا كثيرة جدا وخرج لملاقاته في الحرب'),
(2812, '1 Maccabees', 72, 10, 3, 'و انفذ ديمتريوس الى يوناتان كتبا في معنى السلم متقربا اليه بالاطراء'),
(2813, '1 Maccabees', 72, 10, 4, 'لانه قال لنسبق الى مسالمته قبل ان يسالم الاسكندر علينا'),
(2814, '1 Maccabees', 72, 10, 5, 'فانه سيذكر كل ما انزلنا به وباخوته وامته من المساوئ'),
(2815, '1 Maccabees', 72, 10, 6, 'و اذن له ان يجمع جيوشا ويتجهز بالاسلحة ويكون مناصرا له وامر له برد الرهائن الذين في القلعة'),
(2816, '1 Maccabees', 72, 10, 7, 'فجاء يوناتان الى اورشليم وتلا الكتب على مسامع الشعب كله واهل القلعة'),
(2817, '1 Maccabees', 72, 10, 8, 'فلما سمع ان الملك اذن له في جمع الجيوش جزعوا جزعا شديدا'),
(2818, '1 Maccabees', 72, 10, 9, 'و رد اهل القلعة الرهائن الى يوناتان فردهم الى ذوي قرابتهم'),
(2819, '1 Maccabees', 72, 10, 10, 'و اقام يوناتان باورشليم وطفق يبني ويجدد المدينة'),
(2820, '1 Maccabees', 72, 10, 11, 'و امر صناع العمل ان يبنوا الاسوار حول جبل صهيون بحجارة منحوتة للتحصين ففعلوا'),
(2821, '1 Maccabees', 72, 10, 12, 'فهرب الغرباء الذين في الحصون التي بناها بكيديس'),
(2822, '1 Maccabees', 72, 10, 13, 'و ترك كل واحد مكانه وذهب الى ارضه'),
(2823, '1 Maccabees', 72, 10, 14, 'غير انه بقي في بيت صور قوم من المرتدين عن الشريعة والرسوم فانها كانت ملجا لهم'),
(2824, '1 Maccabees', 72, 10, 15, 'و سمع الاسكندر الملك بالمواعيد التي عرضها ديمتريوس على يوناتان وحدث بما صنع هو واخوته من الحروب واعمال الباس وما كابدوه من النصب'),
(2825, '1 Maccabees', 72, 10, 16, 'فقال انا لا نجد من رجل يماثله فلنتخذه لنا وليا ومناصرا'),
(2826, '1 Maccabees', 72, 10, 17, 'و كتب كتبا وبعث اليه بها في هذا المعنى قائلا'),
(2827, '1 Maccabees', 72, 10, 18, 'من الملك الاسكندر الى اخيه يوناتان سلام'),
(2828, '1 Maccabees', 72, 10, 19, 'لقد بلغنا عنك انك رجل شديد الجبروت وخليق بان تكون لنا وليا'),
(2829, '1 Maccabees', 72, 10, 20, 'فنحن نقيمك اليوم كاهنا اعظم في امتك وتسمى ولي الملك وتهتم بما لنا وتبقى في مودتنا وارسل اليه ارجوانا وتاجا من ذهب'),
(2830, '1 Maccabees', 72, 10, 21, 'فلبس يوناتان الحلة المقدسة في الشهر السابع من السنة المئة والستين في عيد المظال وجمع الجيوش وتجهز باسلحة كثيرة'),
(2831, '1 Maccabees', 72, 10, 22, 'و ذكر ذلك لديمتريوس فشق عليه وقال'),
(2832, '1 Maccabees', 72, 10, 23, 'كيف تركنا الاسكندر يسبقنا الى مصافاة اليهود والتعزز بهم'),
(2833, '1 Maccabees', 72, 10, 24, 'فاكتب انا ايضا اليهم بكلام ملاطفة وتعظيم واعدهم بعطايا ليكونوا من مناصري'),
(2834, '1 Maccabees', 72, 10, 25, 'و كاتبهم بقوله من الملك ديمتريوس الى امة اليهود سلام'),
(2835, '1 Maccabees', 72, 10, 26, 'لقد بلغنا انكم محافظون على عهودكم لنا ثابتون في مودتنا ولم تتقربوا الى اعدائنا فسرنا ذلك'),
(2836, '1 Maccabees', 72, 10, 27, 'فاثبتوا في المحافظة على وفائكم لنا فنحسن ثوابكم على ما تفعلون في حقنا'),
(2837, '1 Maccabees', 72, 10, 28, 'و نحط عنكم كثيرا مما لنا عليكم ونصلكم بالعطايا'),
(2838, '1 Maccabees', 72, 10, 29, 'و الان فاني اعفيكم واحط عن جميع اليهود كل جزية ومكس الملح والاكاليل وثلث الزرع'),
(2839, '1 Maccabees', 72, 10, 30, 'و نصف اتاء الشجر الذي يحق لي اخذه اعفيكم من هذه الاشياء من اليوم فصاعد في ارض يهوذا وفي المدن الثلاث الملحقة بها من ارض السامرة والجليل من هذا اليوم على طول الزمان'),
(2840, '1 Maccabees', 72, 10, 31, 'و لتكن اورشليم مقدسة وحرة هي وتخومها واحط عنها العشور والضرائب'),
(2841, '1 Maccabees', 72, 10, 32, 'و اتخلى عن القلعة التي باورشليم واعطيها للكاهن الاعظم يقيم فيها من يختاره من الرجال لحراستها'),
(2842, '1 Maccabees', 72, 10, 33, 'و جميع النفوس التي سبيت من اليهود من ارض يهوذا في مملكتي باسرها اطلقها حرة بلا ثمن وليكن الجميع معفين من اتاوة المواشي'),
(2843, '1 Maccabees', 72, 10, 34, 'و لتكن الاعياد كلها والسبوت ورؤوس الشهور والايام المخصصة والايام الثلاثة التي قبل العيد والايام الثلاثة التي بعد العيد ايام ابراء وعفو لجميع اليهود الذين في مملكتي'),
(2844, '1 Maccabees', 72, 10, 35, 'فلا يكون لاحد ان يرافع احدا منهم او يثقل عليه في اي امر كان'),
(2845, '1 Maccabees', 72, 10, 36, 'و ليكتتب من اليهود في جيوش الملك الى ثلاثين الف رجل تعطى لهم وظائف كما يحق لسائر جنود الملك'),
(2846, '1 Maccabees', 72, 10, 37, 'فيجعل منهم في حصون الملك العظيمة ويفوض الى البعض منهم النظر في مهام المملكة التي تقتضي الامانة ورؤساؤهم ومدبروهم يكونون من جملتهم ويسلكون بحسب سننهم كما امر الملك لارض يهوذا'),
(2847, '1 Maccabees', 72, 10, 38, 'و اما المدن الثلاث الملحقة باليهودية من بلاد السامرة فلتبق ملحقة باليهودية فتكون معها خاضعة لواحد ولا تطيع سلطانا اخر الا سلطان الكاهن الاعظم'),
(2848, '1 Maccabees', 72, 10, 39, 'و قد وهبت بطلمايس وما يتبعها للمقدس الذي باورشليم لاجل نفقة الاقداس'),
(2849, '1 Maccabees', 72, 10, 40, 'و زدت عليها خمسة عشر الف مثقال فضة كل سنة من دخل الملك من الاماكن التي تختص به'),
(2850, '1 Maccabees', 72, 10, 41, 'و كل ما بقي مما لم يدفعه وكلاء المال عن السنين السالفة يؤدونه من الان لاعمال البيت'),
(2851, '1 Maccabees', 72, 10, 42, 'و ما عدا ذلك فخمسة الاف مثقال الفضة التي كانت تؤخذ من دخل المقدس في كل سنة تترك رزقا للكهنة القائمين بالخدمة'),
(2852, '1 Maccabees', 72, 10, 43, 'و اي من لاذ بالمقدس في اورشليم في جميع حدوده وللملك عليه مال او اي حق كان فليعف وليبق له كل ما ملك في مملكتي'),
(2853, '1 Maccabees', 72, 10, 44, 'و نفقة البناء واعمال الترميم في المقادس تعطى من حساب الملك'),
(2854, '1 Maccabees', 72, 10, 45, 'و بناء اسوار اورشليم وتحصينها على محيطها وبناء الاسوار في سائر اليهودية تعطى نفقته من حساب الملك'),
(2855, '1 Maccabees', 72, 10, 46, 'فلما سمع يوناتان والشعب هذا الكلام لم يثقوا به ولا قبلوه لانهم تذكروا ما انزله ديمتريوس باسرائيل من الشر العظيم والضغط الشديد'),
(2856, '1 Maccabees', 72, 10, 47, 'فاثروا الاسكندر لانه بداهم بكلام السلام وبقوا على مناصرته كل الايام'),
(2857, '1 Maccabees', 72, 10, 48, 'و جمع الاسكندر الملك جيوشا عظيمة نزل تجاه ديمتريوس'),
(2858, '1 Maccabees', 72, 10, 49, 'فانتشب القتال بين الملكين فانهزم جيش ديمتريوس فتعقبه الاسكندر وهجم عليهم'),
(2859, '1 Maccabees', 72, 10, 50, 'و اشتد القتال جدا الى ان غابت الشمس وسقط ديمتريوس في ذلك اليوم'),
(2860, '1 Maccabees', 72, 10, 51, 'ثم بعث الاسكندر رسلا الى بطلماوس ملك مصر بهذا الكلام قائلا'),
(2861, '1 Maccabees', 72, 10, 52, 'اذ قد رجعت الى ارض مملكتي وجلست على عرش ابائي واستتب لي السلطان وكسرت ديمتريوس واستوليت على بلادنا'),
(2862, '1 Maccabees', 72, 10, 53, 'اذ الحمت عليه القتال فانكسر امامنا هو وجيشه وجلست على عرش ملكه'),
(2863, '1 Maccabees', 72, 10, 54, 'فهلم الان نوال بعضنا بعضا وهب لي ابنتك زوجة فاصاهرك واهدي اليك هدايا تليق بك'),
(2864, '1 Maccabees', 72, 10, 55, 'فاجاب بطلماوس الملك قائلا ما اسعد اليوم الذي رجعت فيه الى ارض ابائك وجلست على عرش ملكهم'),
(2865, '1 Maccabees', 72, 10, 56, 'و اني صانع ما كتبت الى به فهلم الى بطلمايس فنتواجه واصاهرك كما قلت'),
(2866, '1 Maccabees', 72, 10, 57, 'و خرج بطلماوس من مصر هو وكلوبطرة ابنته ودخلا بطلمايس في السنة المئة والثانية والستين'),
(2867, '1 Maccabees', 72, 10, 58, 'فلاقاه الاسكندر الملك فاعطاه كلوبطرة ابنته واقام عرسها في بطلمايس على عادة الملوك باحتفال عظيم'),
(2868, '1 Maccabees', 72, 10, 59, 'و كتب الاسكندر الملك الى يوناتان ان يقدم لملاقاته'),
(2869, '1 Maccabees', 72, 10, 60, 'فانطلق الى بطلمايس في موكب مجيد ولقى الملكين واهدى لهما ولاصحابهما فضة وذهبا وهدايا كثيرة فنال حظوة لديهما'),
(2870, '1 Maccabees', 72, 10, 61, 'و اجتمع عليه رجال مفسدون من اسرائيل رجال منافقون ووشوا به فلم يصغ الملك اليهم'),
(2871, '1 Maccabees', 72, 10, 62, 'و امر الملك ان ينزعوا ثياب يوناتان ويلبسوه ارجوانا ففعلوا واجلسه الملك بجانبه'),
(2872, '1 Maccabees', 72, 10, 63, 'و قال لعظمائه اخرجوا معه الى وسط المدينة ونادوا ان لا يتعرض له احد في امر من الامور ولا يسوءه بشيء من المكروه'),
(2873, '1 Maccabees', 72, 10, 64, 'فلما راى الذين وشوا به ما هو فيه من المجد وكيف نودي له والبس الارجون هربوا جميعهم'),
(2874, '1 Maccabees', 72, 10, 65, 'و اعزه الملك وجعله من اصدقائه الخواص واقامه قائدا وشريكا في الملك'),
(2875, '1 Maccabees', 72, 10, 66, 'فعاد يوناتان الى اورشليم سالما مسرورا'),
(2876, '1 Maccabees', 72, 10, 67, 'و في السنة المئة والخامسة والستين جاء ديمتريوس بن ديمتريوس الى ارض ابائه'),
(2877, '1 Maccabees', 72, 10, 68, 'فسمع بذلك الاسكندر الملك فاغتم جدا ورجع الى انطاكية'),
(2878, '1 Maccabees', 72, 10, 69, 'و فوض ديمتريوس قيادة الجيش الى ابلونيوس والى بقاع سورية فحشد جيشا عظيما ونزل بيمنيا وراسل يوناتان الكاهن الاعظم قائلا'),
(2879, '1 Maccabees', 72, 10, 70, 'انه ليس لنا من مقاوم الا انت وبسببك قد اصبحت عرضة للسخرية والتعيير فعلام انت تناهضنا في الجبال'),
(2880, '1 Maccabees', 72, 10, 71, 'فالان ان كنت واثقا بجيوشك فانزل الينا في السهل فنتبارز هناك فان معي قوة الامصار'),
(2881, '1 Maccabees', 72, 10, 72, 'سل واعلم من انا ومن الذين يؤازرونني فانه يقال انكم لا تستطيعون الثبات امامنا لان ابائك قد انكسروا في ارضهم مرتين'),
(2882, '1 Maccabees', 72, 10, 73, 'فلست تطيق الثبات امام الفرسان وجيش في كثرة جيشي في سهل لا حجر فيه ولا حصاة ولا ملجا تهربون اليه'),
(2883, '1 Maccabees', 72, 10, 74, 'فلما سمع يوناتان كلام ابلونيوس اضطرب غيظا واختار عشرة الاف رجل وخرج من اورشليم ولحق به سمعان اخوه لمظاهرته'),
(2884, '1 Maccabees', 72, 10, 75, 'و نزل تجاه يافا فاغلقوا في وجهه ابواب المدينة لان حرس ابلونيوس كان فيها فحاصرها'),
(2885, '1 Maccabees', 72, 10, 76, 'فخاف الذين في المدينة وفتحوا له فاستولى يوناتان على يافا'),
(2886, '1 Maccabees', 72, 10, 77, 'و سمع ابلونيوس فتقدم في ثلاثة الاف فارس وجيش كثير'),
(2887, '1 Maccabees', 72, 10, 78, 'و سار نحو اشدود كانه عابر سبيل ثم عطف بغتة الى السهل اذ كان معه كثيرون من الفرسان الذين يعتمد عليهم فتعقبه يوناتان الى اشدود والتحم القتال بين الفريقين'),
(2888, '1 Maccabees', 72, 10, 79, 'و كان ابلونيوس قد خلف الف فارس وراءهم في خفية'),
(2889, '1 Maccabees', 72, 10, 80, 'الا ان يوناتان كان عالما ان وراءه كمينا ولم يلبثوا ان احدقوا بجيشه يرمون الشعب بالسهام من الصبح الى المساء'),
(2890, '1 Maccabees', 72, 10, 81, 'اما الشعب فبقي في مواقفه كما امر يوناتان حتى اعيت خيل اولئك'),
(2891, '1 Maccabees', 72, 10, 82, 'حينئذ برز سمعان بجيشه والحم القتال على الفرقة لان الخيل كانت قد وهنت فكسرهم فهربوا'),
(2892, '1 Maccabees', 72, 10, 83, 'و تبددت الخيل في السهل وفروا الى اشدود ودخلوا بيت داجون معبد صنمهم لينجوا بنفوسهم'),
(2893, '1 Maccabees', 72, 10, 84, 'فاحرق يوناتان اشدود والمدن التي حولها وسلب غنائمهم واحرق هيكل داجون والذين انهزموا اليه بالنار'),
(2894, '1 Maccabees', 72, 10, 85, 'و كان الذين قتلوا بالسيف مع الذين احرقوا ثمانية الاف رجل'),
(2895, '1 Maccabees', 72, 10, 86, 'ثم سار يوناتان من هناك ونزل تجاه اشقلون فخرج اهل المدينة للقائه باجلال عظيم'),
(2896, '1 Maccabees', 72, 10, 87, 'و رجع يوناتان بمن معه الى اورشليم ومعهم غنائم كثيرة'),
(2897, '1 Maccabees', 72, 10, 88, 'و لمل سمع الاسكندر الملك بهذه الحوادث زاد يوناتان مجدا'),
(2898, '1 Maccabees', 72, 10, 89, 'و بعث اليه بعروة من ذهب كما كان يعطى لانسباء الملوك ووهب له عقرون وتخومها ملكا'),
(2899, '1 Maccabees', 72, 11, 1, 'و جمع ملك مصر جيوشا كثيرة كالرمل الذي على ساحل البحر وسفنا عديدة وحاول الاستيلاء على مملكة الاسكندر بالمكر والحاقها بمملكته'),
(2900, '1 Maccabees', 72, 11, 2, 'فقدم سورية متظاهرا بالسلم ففتح له اهل المدن ولاقوه اذ كان الاسكندر الملك قد امر بلقائه لانه صهره'),
(2901, '1 Maccabees', 72, 11, 3, 'و كان بطلماوس عند دخوله المدن يبقي في كل مدينة حرسا من الجند'),
(2902, '1 Maccabees', 72, 11, 4, 'و لما وصل الى اشدود اروه هيكل داجون المحرق واشدود وضواحيها المهدومة والجثث المطروحة والذين كان يوناتان قد احرقهم في الحرب وكانوا قد جعلوا رجامهم على طريقه'),
(2903, '1 Maccabees', 72, 11, 5, 'و حدثوا الملك بما فعل يوناتان يريدون تجرمه فسكت الملك'),
(2904, '1 Maccabees', 72, 11, 6, 'و لاقى يوناتان الملك في يافا باجلال وسلم بعضهما على بعض وناما هناك'),
(2905, '1 Maccabees', 72, 11, 7, 'ثم شيع يوناتان الملك الى النهر الذي يقال له الوتارس ورجع الى اورشليم'),
(2906, '1 Maccabees', 72, 11, 8, 'فاستحوذ الملك بطلماوس على مدن الساحل الى سلوكية الساحلية وكان مضمرا للاسكندر السوء'),
(2907, '1 Maccabees', 72, 11, 9, 'ثم انفذ رسلا الى ديمتريوس الملك قائلا هلم فنعقد عقدا بيني وبينك واهب لك بنتي التي عند الاسكندر وتملك ملك ابيك'),
(2908, '1 Maccabees', 72, 11, 10, 'فاني قد ندمت على عطائي ابنتي له لانه رام قتلي'),
(2909, '1 Maccabees', 72, 11, 11, 'و تجنى عليه طمعا في ملكه'),
(2910, '1 Maccabees', 72, 11, 12, 'ثم استرد ابنته واعطاها لديمتريوس وتغير على الاسكندر وظهرت عداوتهما'),
(2911, '1 Maccabees', 72, 11, 13, 'ثم ان بطلماوس دخل انطاكية ووضع على راسه تاجين تاج اسية وتاج مصر'),
(2912, '1 Maccabees', 72, 11, 14, 'و كان الاسكندر الملك اذ ذاك في كيليكية لان اهل تلك البلاد كانوا قد تمردوا'),
(2913, '1 Maccabees', 72, 11, 15, 'فلما سمع الاسكندر قدم لمقاتلته فاخرج بطلماوس جيشه ولاقاه بعسكر شديد فكسره'),
(2914, '1 Maccabees', 72, 11, 16, 'فهرب الاسكندر الى ديار العرب مستجيرا بهم وعظم امر بطلماوس الملك'),
(2915, '1 Maccabees', 72, 11, 17, 'فقطع زبديئيل العربي راس الاسكندر وبعث به الى بطلماوس'),
(2916, '1 Maccabees', 72, 11, 18, 'و في اليوم الثالث مات بطلماوس الملك فاهلك رجال الجند الحراس الذين في الحصون'),
(2917, '1 Maccabees', 72, 11, 19, 'و ملك ديمتريوس في السنة المئة والسابعة والستين'),
(2918, '1 Maccabees', 72, 11, 20, 'في تلك الايام جمع يوناتان رجال اليهودية لفتح القلعة التي باورشليم ونصب عليها مجانيق كثيرة'),
(2919, '1 Maccabees', 72, 11, 21, 'فانطلق قوم من مبغضي امتهم من الرجال المنافقين الى الملك واخبروه بان يوناتان يحاصر القلعة'),
(2920, '1 Maccabees', 72, 11, 22, 'فلما سمع استشاط غضبا وسار من ساعته قاصدا بطلمايس وكتب الى يوناتان ان يكف عن محاصرة القلعة وان يبادر الى ملاقاته في بطلمايس للمواجهة'),
(2921, '1 Maccabees', 72, 11, 23, 'فلما بلغ ذلك يوناتان امر بان يستمروا على الحصار واختار بعضا من شيوخ اسرائيل والكهنة وخاطر بنفسه'),
(2922, '1 Maccabees', 72, 11, 24, 'و اخذ من الفضة والذهب والحلل وسائر الهدايا شيئا كثيرا وانطلق الى الملك في بطلمايس فنال حظوة لديه'),
(2923, '1 Maccabees', 72, 11, 25, 'و وشى به قوم من الامة من اهل النفاق'),
(2924, '1 Maccabees', 72, 11, 26, 'الا ان الملك عامله كما كان اسلافه يعاملونه وعظمه لدى اصحابه جميعا'),
(2925, '1 Maccabees', 72, 11, 27, 'و اقره في الكهنوت الاعظم وفي كل ما كان له من الاختصاصات وجعله من اول اصدقائه'),
(2926, '1 Maccabees', 72, 11, 28, 'و سال يوناتان الملك ان يعفي اليهودية والمدن الثلاث وارض السامرة من كل جزية ووعده بثلاث مئة قنطار'),
(2927, '1 Maccabees', 72, 11, 29, 'فارتضى الملك وكتب ليوناتان كتبا في ذلك كله وهذه صورتها'),
(2928, '1 Maccabees', 72, 11, 30, 'من ديمتريوس الملك الى يوناتان اخيه وامة اليهود سلام'),
(2929, '1 Maccabees', 72, 11, 31, 'نسخة الكتاب الذي كتبناه في حقكم الى لسطانيس قريبنا كتبنا بها اليكم لتقفوا على مضمونها'),
(2930, '1 Maccabees', 72, 11, 32, 'من ديمتريوس الملك الى لسطانيس ابيه سلام'),
(2931, '1 Maccabees', 72, 11, 33, 'لقد راينا ان نحسن الى امة اليهود اوليائنا المحافظين على ما يحق لنا وفاء بما سبق من برهم لنا'),
(2932, '1 Maccabees', 72, 11, 34, 'فجعلنا لهم تخوم اليهودية والمدن الثلاث وهي افيرمة ولدة والرامتائيم التي الحقت باليهودية من ارض السامرة وجميع توابعها فتكون لجميع الذين يذبحون في اورشليم بدل الضرائب الملكية التي كان الملك يستخرجها منهم قبلا في كل سنة من اتاء الارض وثمر الاشجار'),
(2933, '1 Maccabees', 72, 11, 35, 'و سائر ما يحق لنا من العشور والوضائع ووهاد الملح والاكاليل'),
(2934, '1 Maccabees', 72, 11, 36, 'هذا كله قد انعمنا عليهم به تبرعا ومن الان لا يلغى شيء من هذا الانعام ما طال الزمان'),
(2935, '1 Maccabees', 72, 11, 37, 'فالان اكتبوا نسخة من هذا الرسم ولتسلم الى يوناتان ولتوضع في الجبل المقدس في موضع مشهود'),
(2936, '1 Maccabees', 72, 11, 38, 'و راى ديمتريوس الملك ان الارض قد اطمانت لديه لا ينازعه منازع فسرح جميع جيوشه كل واحد الى موضعه ما خلا الجنود الغرباء الذين جاء بهم من جزائر الامم فمقته جيوش ابائه كلهم'),
(2937, '1 Maccabees', 72, 11, 39, 'و كان تريفون من احزاب الاسكندر قبلا فلما راى ان الجيوش جميعها تتذمر على ديمتريوس انطلق الى ايملكوئيل العربي وكان يربي انطيوكس بن الاسكندر'),
(2938, '1 Maccabees', 72, 11, 40, 'فالح عليه ان يسلمه اليه لكي يملك مكان ابيه واخبره بما فعل ديمتريوس وبما له في الجيوش من العداوة ومكث هناك اياما كثيرة'),
(2939, '1 Maccabees', 72, 11, 41, 'و ارسل يوناتان الى ديمتريوس الملك ان يخرج الجنود الذين في القلعة من اورشليم والذين في الحصون لانهم كانوا يحاربون اسرائيل'),
(2940, '1 Maccabees', 72, 11, 42, 'فارسل ديمتريوس الى يوناتان قائلا سافعل ذلك لك ولامتك بل ساعظمك انت وامتك تعظيما متى وافقتني فرصة'),
(2941, '1 Maccabees', 72, 11, 43, 'و الان فانك تحسن الصنيع اذا ارسلت الى رجالا يكونون في نجدتي فاني قد خذلتني جيوشي كلها'),
(2942, '1 Maccabees', 72, 11, 44, 'فوجه يوناتان ثلاث الاف رجل اشداء الباس الى انطاكية فوافوا الملك ففرح الملك بقدومهم'),
(2943, '1 Maccabees', 72, 11, 45, 'و اجتمع اهل المدينة في وسط المدينة وكانوا مئة وعشرين الف رجل يحاولون قتل الملك'),
(2944, '1 Maccabees', 72, 11, 46, 'فهرب الملك الى داره فاستولى اهل المدينة على طرق المدينة وشرعوا في القتال'),
(2945, '1 Maccabees', 72, 11, 47, 'فدعا الملك اليهود لنجدته فاجتمعوا اليه كلهم ثم تفرقوا بجملتهم في المدينة فقتلوا فى المدينة في ذلك اليوم مئة الف رجل'),
(2946, '1 Maccabees', 72, 11, 48, 'و احرقوا المدينة واخذوا غنائم كثيرة في ذلك اليوم وخلصوا الملك'),
(2947, '1 Maccabees', 72, 11, 49, 'فلما راى اهل المدينة ان اليهود قد استولوا على المدينة يفعلون ما شاءوا انخلعت قلوبهم وصرخوا الى الملك متضرعين وقالوا'),
(2948, '1 Maccabees', 72, 11, 50, 'عاقدنا وليكف اليهود عن الايقاع بنا وبالمدينة'),
(2949, '1 Maccabees', 72, 11, 51, 'فالقوا السلاح وعقدوا المصالحة فعظم امر اليهود عند الملك وعند جميع اهل مملكته ثم رجعوا الى اورشليم بغنائم كثيرة'),
(2950, '1 Maccabees', 72, 11, 52, 'و جلس ديمتريوس الملك على عرش ملكه وهدات الارض امامه'),
(2951, '1 Maccabees', 72, 11, 53, 'فاخلف في جميع ما وعد وتغير على يوناتان وكافاه بخلاف ما صنع اليه من المعروف وضيق عليه جدا'),
(2952, '1 Maccabees', 72, 11, 54, 'و بعد ذلك رجع تريفون ومعه انطيوكس وهو غلام صغير فملك انطيوكس ولبس التاج'),
(2953, '1 Maccabees', 72, 11, 55, 'فاجتمع اليه جميع الجيوش التي سرحها ديمتريوس وقاتلوا ديمتريوس ففر منهم منهزما'),
(2954, '1 Maccabees', 72, 11, 56, 'فاستولى تريفون على الفيلة ثم فتح انطاكية'),
(2955, '1 Maccabees', 72, 11, 57, 'و كتب انطيوكس الصغير الى يوناتان قائلا اني اقرك في الكهنوت الاعظم واقيمك على المدن الاربع واتخذك من اصدقاءالملك'),
(2956, '1 Maccabees', 72, 11, 58, 'و ارسل اليه انية من الذهب لخدمته واباح له ان يشرب في الذهب ويلبس الارجوان بعروة الذهب'),
(2957, '1 Maccabees', 72, 11, 59, 'و اقام سمعان اخاه قائدا من عقبة صور الى حدود مصر'),
(2958, '1 Maccabees', 72, 11, 60, 'و خرج يوناتان وطاف في عبر النهر وفي المدن فاجتمعت لمظاهرته جميع جيوش سورية وقدم اشقلون فلاقاه اهل المدينة باحتفال'),
(2959, '1 Maccabees', 72, 11, 61, 'و انصرف من هناك الى غزة فاغلق اهل غزة الابواب في وجهه فحاصرها واحرق ضواحيها بالنار ونهبها'),
(2960, '1 Maccabees', 72, 11, 62, 'فسال اهل غزة يوناتان الامان فعاقدهم واخذ ابناء رؤسائهم رهائن وارسلهم الى اورشليم ثم جال في البلاد الى دمشق'),
(2961, '1 Maccabees', 72, 11, 63, 'و سمع يوناتان ان قواد ديمتريوس قد بلغوا الى قادش الجليل في جيش كثيف يريدون ان يعزلوه عن الولاية'),
(2962, '1 Maccabees', 72, 11, 64, 'فزحف لملاقاتهم وخلف سمعان اخاه في البلاد'),
(2963, '1 Maccabees', 72, 11, 65, 'فحاصر سمعان بيت صور وحاربها اياما كثيرة واحاط بها'),
(2964, '1 Maccabees', 72, 11, 66, 'فسالوه المعاقدة فعاقدهم واخرجهم من هناك وفتح المدينة واقام فيها حرسا'),
(2965, '1 Maccabees', 72, 11, 67, 'و اما يوناتان وجيشه فنزلوا على ماء جناسر وقبل الفجر زحفوا الى سهل حاصور'),
(2966, '1 Maccabees', 72, 11, 68, 'فاذا بجيش الاجانب يلاقيهم في السهل وقد اقاموا عليهم كمينا في الجبال فبينما هم يتقدمون تجاههم'),
(2967, '1 Maccabees', 72, 11, 69, 'ثار الكمين من مواضعهم والحموا القتال'),
(2968, '1 Maccabees', 72, 11, 70, 'ففر رجال يوناتان جميعا ولم يبق منهم احد الا متتيا ابن ابشالوم ويهوذا بن حلفي قائدا الجيوش'),
(2969, '1 Maccabees', 72, 11, 71, 'فمزق يوناتان ثيابه وحثا التراب على راسه وصلى'),
(2970, '1 Maccabees', 72, 11, 72, 'ثم عاد اليهم يقاتلهم فانهزموا وهربوا'),
(2971, '1 Maccabees', 72, 11, 73, 'و لما راى ذلك الذين هربوا من رجاله رجعوا وتعقبوا العدو معه الى قادش الى معسكرهم ونزلوا هناك'),
(2972, '1 Maccabees', 72, 11, 74, 'فسقط من الاجانب في ذلك اليوم ثلاثة الف رجل ورجع يوناتان الى اورشليم'),
(2973, '1 Maccabees', 72, 12, 1, 'و راى يوناتان ان له فرصة ملائمة فاختار رجالا وسيرهم الى رومية ليقروا الموالاة بينهم ويجددوها'),
(2974, '1 Maccabees', 72, 12, 2, 'و ارسل معهم الى اسبرطة واماكن اخرى كتبا في هذا المعنى'),
(2975, '1 Maccabees', 72, 12, 3, 'فانطلقوا الى رومية ودخلوا الشورى وقالوا انا مرسلون من قبل يوناتان الكاهن الاعظم وامة اليهود لنجدد ما بينكم وبينهم من الموالاة والمناصرة كما كان من قبل'),
(2976, '1 Maccabees', 72, 12, 4, 'فاعطوهم كتبا للعمال في الاقاليم حتى يبلغوهم ارض يهوذا بسلام'),
(2977, '1 Maccabees', 72, 12, 5, 'و هذه نسخة الكتب التي كتبها يوناتان الى اهل اسبرطة'),
(2978, '1 Maccabees', 72, 12, 6, 'من يوناتان الكاهن الاعظم وشيوخ الامة ومن الكهنة وسائر شعب اليهود الى اهل اسبرطة اخوتهم سلام'),
(2979, '1 Maccabees', 72, 12, 7, 'ان اريوس المالك فيكم كان قديما قد انفذ كتبا الى اونيا الكاهن الاعظم يشهد انكم اخوتنا على ما هو في نسختها'),
(2980, '1 Maccabees', 72, 12, 8, 'فتلقى اونيا الرسول باكرام واخذ الكتب المصرح فيها بالمناصرة والموالاة'),
(2981, '1 Maccabees', 72, 12, 9, 'فنحن وان لم تكن بنا حاجة الى ذلك بما لنا من التعزية في الاسفار المقدسة التي في ايدينا'),
(2982, '1 Maccabees', 72, 12, 10, 'قد اثرنا مراسلتكم لنجدد الاخاء والموالاة لئلا نعد من الاجانب عندكم اذ قد مضى على مكاتبتكم لنا زمان مديد'),
(2983, '1 Maccabees', 72, 12, 11, 'و انا في كل حين في الاعياد وسائر الايام المفروضة لا نزال نذكركم في الذبائح التي نقدمها وفي الصلوات كما ينبغي ويليقان يذكر الاخوة'),
(2984, '1 Maccabees', 72, 12, 12, 'و يسرنا ما انتم عليه من الاعتزاز'),
(2985, '1 Maccabees', 72, 12, 13, 'اما نحن فقد احاطت بنا مضايق كثيرة وحروب عديدة وقاتلنا الملوك الذين من حولنا'),
(2986, '1 Maccabees', 72, 12, 14, 'لكنا كرهنا ان نثقل عليكم وعلى سائر مناصرينا واوليائنا في تلك الحروب'),
(2987, '1 Maccabees', 72, 12, 15, 'فان لنا من السماء مددا يمدنا وقد تخلصنا من اعدائنا واذللناهم'),
(2988, '1 Maccabees', 72, 12, 16, 'و الان فقد اخترنا نومانيوس بن انطيوكس وانتيباتير بن ياسون وارسلناهما الى الرومانيين لنجدد ما كان بيننا قبلا من الموالاة والمناصرة'),
(2989, '1 Maccabees', 72, 12, 17, 'و امرناهما بان يقدما اليكم ويقرئاكم السلام ويسلما اليكم الكتب من قبلنا في تجديد اخائنا'),
(2990, '1 Maccabees', 72, 12, 18, 'و لكم جميل الصنع ان اجبتمونا الى ذلك'),
(2991, '1 Maccabees', 72, 12, 19, 'و هذه نسخة الكتب التي ارسلها الى اونيا'),
(2992, '1 Maccabees', 72, 12, 20, 'من اريوس ملك الاسبرطيين الى اونيا الكاهن الاعظم سلام'),
(2993, '1 Maccabees', 72, 12, 21, 'و بعد فقد وجد في بعض الكتب ان الاسبرطيين واليهود اخوة من نسل ابراهيم'),
(2994, '1 Maccabees', 72, 12, 22, 'و اذ قد علمنا ذلك فلكم جميل الصنع ان راسلتمونا فيما انتم عليه من السلام'),
(2995, '1 Maccabees', 72, 12, 23, 'و الان فان جوابنا اليكم ان مواشيكم واملاككم هي لنا وان ما لنا هو لكم هذا ما اوصينا بان تبلغوه'),
(2996, '1 Maccabees', 72, 12, 24, 'و بلغ يوناتان ان قواد ديمتريوس قد عادوا لمحاربته بجيش يزيد على جيشه الاول'),
(2997, '1 Maccabees', 72, 12, 25, 'فخرج من اورشليم ووافاهم في ارض حماة ولم يمهلهم ان يطاوا ارضه'),
(2998, '1 Maccabees', 72, 12, 26, 'ثم ارسل جواسيس الى محلتهم فرجعوا واخبروه انهم مزمعون ان يهجموا عليهم في الليل'),
(2999, '1 Maccabees', 72, 12, 27, 'فلما غربت الشمس امر يوناتان الذين معه بان يسهروا تحت السلاح الليل كله استعدادا للقتال وفرق الحرس حول المحلة'),
(3000, '1 Maccabees', 72, 12, 28, 'و سمع العدو بان يوناتان والذين معه متاهبون للقتال فداخل قلوبهم الرعب والرعدة فاضرموا النيران في محلتهم وهربوا'),
(3001, '1 Maccabees', 72, 12, 29, 'الا ان يوناتان والذين معه لم يعلموا بما كان الا عند الصبح لانهم كانوا يرون ضوء النيران'),
(3002, '1 Maccabees', 72, 12, 30, 'فتعقبهم يوناتان فلم يدركهم لانهم كانوا قد قطعوا نهر الوطارس'),
(3003, '1 Maccabees', 72, 12, 31, 'فارتد يوناتان الى العرب المسمين بالزبديين وضربهم وسلب غنائمهم'),
(3004, '1 Maccabees', 72, 12, 32, 'ثم ارتحل واتى دمشق وجال في البلاد كلها'),
(3005, '1 Maccabees', 72, 12, 33, 'و اما سمعان فخرج وبلغ الى اشقلون والحصون التي بالقرب منها ثم ارتد الى يافا واستحوذ عليها'),
(3006, '1 Maccabees', 72, 12, 34, 'لانه سمع انهم يريدون ان يسلموا الحصن الى احزاب ديمتريوس واقام هناك حرسا يحافظون على المدينة'),
(3007, '1 Maccabees', 72, 12, 35, 'ثم رجع يوناتان وجمع شيوخ الشعب واتمر معهم ان يبني حصونا في اليهودية'),
(3008, '1 Maccabees', 72, 12, 36, 'و يرفع اسوار اورشليم ويشيد حائطا عاليا بين القلعة والمدينة ليفصلها عن المدينة وتبقى على حدتها حتى لا يشتروا ويبيعوا'),
(3009, '1 Maccabees', 72, 12, 37, 'فاتفقوا على ان يبنوا المدينة وتقدم اليهم ان يبنوا سور الوادي شرقا ورمموا السور المسمى كافيناطا'),
(3010, '1 Maccabees', 72, 12, 38, 'و ابتنى سمعان حاديد في السهل وحصنها بالابواب والمزاليج'),
(3011, '1 Maccabees', 72, 12, 39, 'و حاول تريفون ان يملك على اسية ويلبس التاج ويلقي يده على انطيوكس الملك'),
(3012, '1 Maccabees', 72, 12, 40, 'لكنه خشي من يوناتان ان يمنعه ويحاربه فطلب سبيلا لان يقبض على يوناتان ويهلكه فسار واتى الى بيت شان'),
(3013, '1 Maccabees', 72, 12, 41, 'فخرج يوناتان لملتقاه في اربعين الف رجل منتخبين للقتال واتى الى بيت شان'),
(3014, '1 Maccabees', 72, 12, 42, 'فلما راى تريقون ان يوناتان قد اقبل في جيش كثيف لم يجسر ان يمد يده اليه'),
(3015, '1 Maccabees', 72, 12, 43, 'فتلقاه باكرام واوصى به جميع اصحابه واهدى اليه هدايا وامر جيوشه بان يطيعوه طاعتهم لنفسه'),
(3016, '1 Maccabees', 72, 12, 44, 'و قال ليوناتان لم ثقلت على هؤلاء الشعب كلهم وليس بيننا حرب'),
(3017, '1 Maccabees', 72, 12, 45, 'اطلقهم الى بيوتهم وانتخب لك نفرا قليلا يكونون معك وهلم معي الى بطلمايس فاسلمها اليك هي وسائر الحصون ومن بقي من الجيوش وجميع المقلدين على الامور ثم انصرف راجعا فاني لهذا جئت'),
(3018, '1 Maccabees', 72, 12, 46, 'فصدقه وفعل كما قال واطلق الجيوش فانصرفوا الى ارض يهوذا'),
(3019, '1 Maccabees', 72, 12, 47, 'و استبقى لنفسه ثلاثة الاف رجل ترك الفين منهم في الجليل وصحبه الف'),
(3020, '1 Maccabees', 72, 12, 48, 'فلما دخل يوناتان بطلمايس اغلق اهل بطلمايس الابواب وقبضوا عليه وقتلوا جميع الذين دخلوا معه بالسيف'),
(3021, '1 Maccabees', 72, 12, 49, 'و ارسل تريفون جيشا وفرسانا الى الجليل والصحراء الواسعة لاهلاك جميع رجال يوناتان'),
(3022, '1 Maccabees', 72, 12, 50, 'لكنهم لما علموا ان يوناتان والذين معه قد قبض عليهم وهلكوا شجعوا انفسهم وتقدموا وهم متضامون متاهبون للقتال'),
(3023, '1 Maccabees', 72, 12, 51, 'و اذ راى طالبوهم انهم مستبسلون رجعوا عنهم'),
(3024, '1 Maccabees', 72, 12, 52, 'فوفدوا جميعهم بالسلام الى ارض يهوذا وناحوا على يوناتان والذين معه واشتد خوفهم وكانت عند جميع اسرائيل مناحة عظيمة'),
(3025, '1 Maccabees', 72, 12, 53, 'و طلب كل الامم الذين حولهم ان يدمروهم لانهم قالوا'),
(3026, '1 Maccabees', 72, 12, 54, 'انهم لا رئيس لهم ولا ناصر فلنقاتلهم ولنمح ذكرهم من البشر'),
(3027, '1 Maccabees', 72, 13, 1, 'و بلغ سمعان ان تريفون قد جمع جيشا عظيما ليغير على ارض يهوذا ويدمرها'),
(3028, '1 Maccabees', 72, 13, 2, 'و راى ان شعبه قد داخله الرعب والرعدة فصعد الى اورشليم وجمع الشعب'),
(3029, '1 Maccabees', 72, 13, 3, 'و شجعهم وقال لهم قد علمتم ما فعلت انا واخوتي واهل بيت ابي من اجل السنن والاقداس وما لقينا من الحروب والشدائد'),
(3030, '1 Maccabees', 72, 13, 4, 'و قد كان في ذلك هلاك اخوتي جميعا لاجل اسرائيل وبقيت انا وحدي'),
(3031, '1 Maccabees', 72, 13, 5, 'و الان فحاش لي ان اضن بنفسي في كل موقع ضيق فاني لست خيرا من اخوتي'),
(3032, '1 Maccabees', 72, 13, 6, 'بل انتقم لامتي وللاقداس ولنسائنا واولادنا لان الامم باسرها قد اجتمعت لتدميرنا بغضا'),
(3033, '1 Maccabees', 72, 13, 7, 'فلما سمع الشعب هذا الكلام ثارت نفوسهم'),
(3034, '1 Maccabees', 72, 13, 8, 'و اجابوا بصوت عظيم قائلين انت قائد لنا مكان يهوذا ويوناتان اخيك'),
(3035, '1 Maccabees', 72, 13, 9, 'فحارب حربنا ومهما قلت لنا فانا نفعله'),
(3036, '1 Maccabees', 72, 13, 10, 'فحشد جميع رجال القتال وجد في اتمام اسوار اورشليم وحصنها مما حولها'),
(3037, '1 Maccabees', 72, 13, 11, 'ثم وجه يوناتان بن ابشالوم الى يافا في عدد واف من الجيش فطرد الذين كانوا فيها واقام هناك'),
(3038, '1 Maccabees', 72, 13, 12, 'و زحف تريفون من بطلمايس في جيش عظيم قاصدا ارض يهوذا ومعه يوناتان تحت الحفظ'),
(3039, '1 Maccabees', 72, 13, 13, 'و كان سمعان حالا بحاديد قبالة السهل'),
(3040, '1 Maccabees', 72, 13, 14, 'و علم تريفون ان سمعان قد قام في موضع يوناتان اخيه وانه مزمع ان يلحم الحرب معه فانفذ اليه رسلا'),
(3041, '1 Maccabees', 72, 13, 15, 'يقول انا انما قبضنا على يوناتان اخيك لمال كان عليه للملك فيما باشره من الامور'),
(3042, '1 Maccabees', 72, 13, 16, 'فالان ارسل مئة قنطار فضة وابنيه رهينة لئلا يغدر بنا اذا اطلقناه وحينئذ نطلقه'),
(3043, '1 Maccabees', 72, 13, 17, 'و علم سمعان انهم انما يكلمونه بمكر الا انه ارسل المال والولدين مخافة ان يجلب على نفسه عداوة عظيمة من قبل الشعب ويقولوا'),
(3044, '1 Maccabees', 72, 13, 18, 'لسبب انه لم يرسل اليه المال والولدين هلك'),
(3045, '1 Maccabees', 72, 13, 19, 'فوجه الولدين ومئة القنطار الا ان تريفون اخلف ولم يطلق يوناتان'),
(3046, '1 Maccabees', 72, 13, 20, 'و جاء تريفون بعد ذلك ليغير على البلاد ويدمرها ودار في الطريق الى ادورا وكان سمعان وجيشه يقاومونه حيثما تقدم'),
(3047, '1 Maccabees', 72, 13, 21, 'و انفذ الذين في القلعة رسلا الى تريفون يلحون عليه ان ياتيهم في طريق البرية وينفذ اليهم ميرة'),
(3048, '1 Maccabees', 72, 13, 22, 'فجهز تريفون جميع فرسانه للمسير في ذلك الليل لكن اذ تكاثر الثلج جدا منعهم الثلج من المسير فارتحل واتى الى ارض جلعاد'),
(3049, '1 Maccabees', 72, 13, 23, 'و لما ان قارب بسكاما قتل يوناتان ودفنوه هناك'),
(3050, '1 Maccabees', 72, 13, 24, 'ثم رجع تريفون وانصرف الى ارضه'),
(3051, '1 Maccabees', 72, 13, 25, 'فارسل سمعان واخذ عظام يوناتان اخيه ودفنها في مودين مدينة ابائه'),
(3052, '1 Maccabees', 72, 13, 26, 'و ناح عليه كل اسرائيل نوحا عظيما وندبوه اياما كثيرة'),
(3053, '1 Maccabees', 72, 13, 27, 'و شيد سمعان على قبر ابيه واخوته بناء عاليا منظورا بحجارة نحتت من وراء ومن امام'),
(3054, '1 Maccabees', 72, 13, 28, 'و نصب على القبور سبعة اهرام واحدا بازاء واحد لابيه وامه واخوته الاربعة'),
(3055, '1 Maccabees', 72, 13, 29, 'و زينها بفنون ونقوش وجعل حولها اعمدة عظيمة مرسوما على الاعمدة اسلحة تخليدا لذكرهم وبجانب الاسلحة سفن منقوشة وكانت منظورة لجميع ركاب البحر'),
(3056, '1 Maccabees', 72, 13, 30, 'هذا هو القبر الذي صنعه بمودين باقيا الى هذا اليوم'),
(3057, '1 Maccabees', 72, 13, 31, 'و سلك تريفون بالغدر مع انطيوكس الملك الصغير وقتله'),
(3058, '1 Maccabees', 72, 13, 32, 'و ملك مكانه ولبس تاج اسية وضرب الارض ضربة عظيمة'),
(3059, '1 Maccabees', 72, 13, 33, 'و بنى سمعان حصون اليهودية وعززها بالبروج الرفيعة والاسوار العظيمة والابواب والمزاليج وادخر ميرة في الحصون'),
(3060, '1 Maccabees', 72, 13, 34, 'و انتخب سمعان رجالا وارسل الى ديمتريوس الملك ان يعفي البلاد لان كل ما فعله تريفون انما كان اختلاسا'),
(3061, '1 Maccabees', 72, 13, 35, 'فبعث اليه ديمتريوس الملك بهذا الكلام واجابه وكتب اليه كتابا هذه صورته'),
(3062, '1 Maccabees', 72, 13, 36, 'من ديمتريوس الملك الى سمعان الكاهن الاعظم وصديق الملوك والى الشيوخ وشعب اليهود سلام'),
(3063, '1 Maccabees', 72, 13, 37, 'قد وصل الينا اكليل الذهب والسعفة التي بعثت بها الينا وفي عزمنا ان نعقد معكم سلما وثيقا ونكاتب ارباب الامور ان يعفوكم مما عليكم'),
(3064, '1 Maccabees', 72, 13, 38, 'و كل ما رسمنا لكم يبقى مرسوما والحصون التي بنيتموها تكون لكم'),
(3065, '1 Maccabees', 72, 13, 39, 'و لكن ما فرط من هفوة وخطا الى هذا اليوم نتجاوز عنه والاكليل الذي لنا عليكم وكل وضيعة اخرى على اورشليم نعفيكم منها'),
(3066, '1 Maccabees', 72, 13, 40, 'و ان كان فيكم اهل للاكتتاب في جندنا فليكتتبوا ولكن فيما بيننا سلم'),
(3067, '1 Maccabees', 72, 13, 41, 'و في السنة المئة والسبعين خلع نير الامم عن اسرائيل'),
(3068, '1 Maccabees', 72, 13, 42, 'و بدا شعب اسرائيل يكتب في توقيع الصكوك والعقود في السنة الاولى لسمعان الكاهن الاعظم قائد اليهود ورئيسهم'),
(3069, '1 Maccabees', 72, 13, 43, 'في تلك الايام نزل سمعان على غزة وحاصرها بجيوشه وصنع دبابات وادناها من المدينة وضرب احد البروج واستولى عليه'),
(3070, '1 Maccabees', 72, 13, 44, 'و هجم الذين في الدبابة على المدينة فوقع اضطراب عظيم في المدينة'),
(3071, '1 Maccabees', 72, 13, 45, 'و صعد الذين في المدينة مع النساء الى السور ممزقة ثيابهم وصرخوا بصوت عظيم الى سمعان يسالونه الامان'),
(3072, '1 Maccabees', 72, 13, 46, 'و قالوا لا تعاملنا بحسب مساوئنا بل بحسب رافتك'),
(3073, '1 Maccabees', 72, 13, 47, 'فرق لهم سمعان وكف عن قتالهم واخرجهم من المدينة وطهر البيوت التي كانت فيها اصنام ثم دخلها بالتسبيح والشكر'),
(3074, '1 Maccabees', 72, 13, 48, 'و ازل منها كل رجاسة واسكن هناك رجالا من المتمسكين بالشريعة وحصنها وبنى له فيها منزلا'),
(3075, '1 Maccabees', 72, 13, 49, 'و اما الذين في قلعة اورشليم فاذ كانوا قد منعوا من الخروج ودخول البلد ومن البيع والشراء اشتدت مجاعتهم ومات كثير منهم'),
(3076, '1 Maccabees', 72, 13, 50, 'فصرخوا الى سمعان يسالون الامان فامنهم واخرجهم من هناك وطهر القلعة من النجاسات'),
(3077, '1 Maccabees', 72, 13, 51, 'و دخلها في اليوم الثالث والعشرين من الشهر الثاني في السنة المئة والحادية والسبعين بالحمد والسعف والكنارات والصنوج والعيدان والتسابيح والاناشيد لانحطام العدو الشديد من اسرائيل');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(3078, '1 Maccabees', 72, 13, 52, 'و رسم ان يعيد ذلك اليوم بسرور كل سنة'),
(3079, '1 Maccabees', 72, 13, 53, 'ثم حصن جبل الهيكل الذي بجانب القلعة وسكن هناك هو والذين معه'),
(3080, '1 Maccabees', 72, 13, 54, 'و راى سمعان ان يوحنا ابنه رجل باس فجعله قائدا على جميع الجيوش واقام بجازر'),
(3081, '1 Maccabees', 72, 14, 1, 'و في السنة المئة والثانية والسبعين جمع ديمتريوس الملك جيوشه وسار الى ماداي يستمد نجدة لمحاربة تريفون'),
(3082, '1 Maccabees', 72, 14, 2, 'و بلغ ارساكيس ملك فارس وماداي ان ديمتريوس قد دخل تخومه فارسل بعض رؤسائه ليقبض عليه حيا'),
(3083, '1 Maccabees', 72, 14, 3, 'فذهب وضرب جيش ديمتريوس وقبض عليه واتى به ارساكيس فجعله في السجن'),
(3084, '1 Maccabees', 72, 14, 4, 'فهدات ارض يهوذا كل ايام سمعان وجعل همه مصلحة امته فكانوا مبتهجين بسلطانه ومجده كل الايام'),
(3085, '1 Maccabees', 72, 14, 5, 'و فضلا عن ذلك المجد كله جعل يافا مرسى وفتح مجازا لجزائر البحر'),
(3086, '1 Maccabees', 72, 14, 6, 'و وسع تخوم امته واستحوذ على البلاد'),
(3087, '1 Maccabees', 72, 14, 7, 'و جمع اسرى كثيرين وامتلك جازر وبيت صور والقلعة واخرج منها النجاسات ولم يكن من يقاومه'),
(3088, '1 Maccabees', 72, 14, 8, 'و كانوا يفلحون ارضهم بسلام والارض تعطي اتاءها واشجار الحقول اثمارها'),
(3089, '1 Maccabees', 72, 14, 9, 'و كان الشيوخ يجلسون في الساحات يتفاوضون جميعا في مصالح الامة والشبان متسربلين بالبهاء وعليهم حلل الحرب'),
(3090, '1 Maccabees', 72, 14, 10, 'و كان سمعان يمير المدن بالطعام ويهيئ فيها اسباب التحصين حتى صار ذكر مجده الى اقاصي الارض'),
(3091, '1 Maccabees', 72, 14, 11, 'و قرر السلم في ارضه فلبث اسرائيل في فرح عظيم'),
(3092, '1 Maccabees', 72, 14, 12, 'و جلس كل واحد تحت كرمته وتينته ولم يكن من يذعرهم'),
(3093, '1 Maccabees', 72, 14, 13, 'و لم يبق في الارض من يحاربهم وقد انكسرت الملوك في تلك الايام'),
(3094, '1 Maccabees', 72, 14, 14, 'و قوى كل من كان ضعيفا في شعبه وغار على الشريعة واستاصل كل اثيم وشرير'),
(3095, '1 Maccabees', 72, 14, 15, 'و عظم الاقداس واكثر من الانية المقدسة'),
(3096, '1 Maccabees', 72, 14, 16, 'و بلغ خبر وفاة يوناتان الى رومية واسبرطة فاسفوا اسفا شديدا'),
(3097, '1 Maccabees', 72, 14, 17, 'و اذ بلغهم ان سمعان اخاه قد تقلد الكهنوت الاعظم مكانه وصارت البلاد وما بها من المدن تحت سلطانه'),
(3098, '1 Maccabees', 72, 14, 18, 'كتبوا اليه على الواح من نحاس يجددون معه ما كانوا قد قرروه مع يهوذا ويوناتان اخويه من الموالاة والمناصرة'),
(3099, '1 Maccabees', 72, 14, 19, 'فقرئت الالواح بمشهد الجماعة في اورشليم وهذه صورة الكتب التي انفذها الاسبرطيون'),
(3100, '1 Maccabees', 72, 14, 20, 'من رؤساء الاسبرطيين ومن المدينة الى سمعان الكاهن الاعظم والى الشيوخ والكهنة وسائر شعب اليهود اخوتنا سلام'),
(3101, '1 Maccabees', 72, 14, 21, 'لقد اخبرنا الرسل الذين انفذتموهم الى شعبنا بما انتم فيه من العزة والكرامة فسررنا بوفدهم'),
(3102, '1 Maccabees', 72, 14, 22, 'و دونا ما قالوه في دواوين الشعب هكذا قد قدم علينا نومانيوس بن انطيوكس وانتيباتير ابن ياسون رسولا اليهود ليجددا مابيننا من الموالاة'),
(3103, '1 Maccabees', 72, 14, 23, 'فحسن لدى الشعب ان يلتقي الرجلين باكرام ويثبت صورة كلامهما في سجلات الشعب المخصصة لتكون تذكارا عند شعب الاسبرطيين وقد كتبنا بنسختها الى سمعان الكاهن الاعظم'),
(3104, '1 Maccabees', 72, 14, 24, 'و بعد ذلك ارسل سمعان نومانيوس الى رومية ومعه ترس عظيم من الذهب وزنه الف منا ليقرر المناصرة بينه وبينهم'),
(3105, '1 Maccabees', 72, 14, 25, 'فلما سمع الشعب ذلك الكلام قالوا بماذا نكافئ سمعان وبنيه'),
(3106, '1 Maccabees', 72, 14, 26, 'على ثباته هو واخوته وبيت ابيه ودفعه عن اسرائيل اعداءه وتمتيعه له بالحرية وكتب في الواح من نحاس جعلوها على انصابفي جبل صهيون'),
(3107, '1 Maccabees', 72, 14, 27, 'ما صورته في اليوم العاشر من شهر ايلول في السنة المئة والثانية والسبعين وهي السنة الثالثة لسمعان الكاهن الاعظم في سرمال'),
(3108, '1 Maccabees', 72, 14, 28, 'في مجمع عظيم من الكهنة والشعب ورؤساء الامة وشيوخ البلاد ثبت عندنا ان قد وقعت حروب كثيرة في البلاد'),
(3109, '1 Maccabees', 72, 14, 29, 'و ان سمعان بن متتيا من بني ياريب واخوته قد القوا بانفسهم في المخاطر وناهضوا اعداء امتهم صيانة لاقداسهم والشريعة واولوا امتهم مجدا كبيرا'),
(3110, '1 Maccabees', 72, 14, 30, 'و ان يوناتان جمع شمل امته وتقلد فيهم الكهنوت الاعظم ثم انضم الى قومه'),
(3111, '1 Maccabees', 72, 14, 31, 'فهم اعداؤهم بالغارة على ارضهم ليدمروا بلادهم ويلقوا ايديهم على اقداسهم'),
(3112, '1 Maccabees', 72, 14, 32, 'حينئذ نهض سمعان وقاتل عن امته وانفق كثيرا من امواله وسلح رجال الباس من امته واجرى عليهم الارزاق'),
(3113, '1 Maccabees', 72, 14, 33, 'و حصن مدن اليهودية وبيت صور التي عند حدود اليهودية حيث كانت اسلحة الاعداء من قبل وجعل هناك حرسا من رجال اليهود'),
(3114, '1 Maccabees', 72, 14, 34, 'و حصن يافا التي على البحر وجازر التي عند حدود اشدود حيث كان الاعداء مقيمين من قبل واسكن هناك يهودا وجعل فيهما كل ما ياول الى اعزاز شانهما'),
(3115, '1 Maccabees', 72, 14, 35, 'فلما راى الشعب ما فعل سمعان والمجد الذي شرع في انشائه لامته اقاموه قائدا لهم وكاهنا اعظم لما صنعه من ذلك كله ولاجل عدله والوفاء الذي حفظه لامته والتماسه اعزاز شعبه بجميع الوجوه'),
(3116, '1 Maccabees', 72, 14, 36, 'و في ايامه تم النجح على يديه باجلاء الامم عن البلاد وطرد الذين في مدينة داود باورشليم وكانوا قد بنوا لانفسهم قلعة يخرجون منها وينجسون ما حول الاقداس ويفسدون الطهارة افسادا عظيما'),
(3117, '1 Maccabees', 72, 14, 37, 'و اسكن فيها رجالا من اليهود وحصنها لصيانة البلاد والمدينة ورفع اسوار اورشليم'),
(3118, '1 Maccabees', 72, 14, 38, 'و اقره الملك ديمتريوس في الكهنوت الاعظم'),
(3119, '1 Maccabees', 72, 14, 39, 'و جعله من اصدقائه وعظمه جدا'),
(3120, '1 Maccabees', 72, 14, 40, 'اذ بلغه ان الرومانيين يسمون اليهود اولياء لهم ومناصرين واخوة وقد تلقوا رسل سمعان باكرام'),
(3121, '1 Maccabees', 72, 14, 41, 'و ان اليهود وكهنتهم قد حسن لديهم ان يكون سمعان رئيسا وكاهنا اعظم مدى الدهر الى ان يقوم نبي امين'),
(3122, '1 Maccabees', 72, 14, 42, 'و يكون قائدا لهم ويهتم بالاقداس ويقيم منهم اناسا على الاعمال والبلاد والاسلحة والحصون'),
(3123, '1 Maccabees', 72, 14, 43, 'و يتولى امر الاقداس وان يطيعه الجميع وتكتب باسمه جميع الصكوك في البلاد ويلبس الارجوان والذهب'),
(3124, '1 Maccabees', 72, 14, 44, 'و لا يحل لاحد من الشعب والكهنة ان ينقض شيئا من ذلك او يخالف شيئا مما يامر به او يجمع مجمعا بدونه في البلاد او يلبس الارجوان وعروة الذهب'),
(3125, '1 Maccabees', 72, 14, 45, 'و من فعل خلاف ذلك ونقض شيئا منه فهو مجرم'),
(3126, '1 Maccabees', 72, 14, 46, 'و قد رضي الشعب كله بان يقلد سمعان جميع ما ذكر'),
(3127, '1 Maccabees', 72, 14, 47, 'و قبل سمعان ورضي ان يكون كاهنا اعظم وقائدا ورئيسا لامة اليهود وللكهنة وحاكما على الجميع'),
(3128, '1 Maccabees', 72, 14, 48, 'و رسموا بان تدون هذه الكتابة في الواح من نحاس توضع في رواق الاقداس في موضع مشهود'),
(3129, '1 Maccabees', 72, 14, 49, 'و توضع صورها في الخزانة حتى تبقى لسمعان وبنيه'),
(3130, '1 Maccabees', 72, 15, 1, 'و انفذ انطيوكس بن ديمتريوس الملك كتبا من جزائر البحر الى سمعان الكاهن رئيس امة اليهود والى الشعب اجمع'),
(3131, '1 Maccabees', 72, 15, 2, 'و هذه فحواها من انطيوكس الملك الى سمعان الكاهن الاعظم رئيس الامة والى شعب اليهود سلام'),
(3132, '1 Maccabees', 72, 15, 3, 'انه اذ كان قوم من ذوي الفساد قد تسلطوا على مملكة ابائنا كان من همي الان ان استخلص المملكة حتى اعيدها الى ما كانت عليه منقبل وقد حشدت جيوشا كثيرة وجهزت اسطولا للحرب'),
(3133, '1 Maccabees', 72, 15, 4, 'و انا عازم ان اتقدم على البلاد لانتقم من الذين افسدوا في بلادنا وخربوا مدنا كثيرة في المملكة'),
(3134, '1 Maccabees', 72, 15, 5, 'فالان اقرر لك كل حطيطة حطها عنك الملوك من قبلي وكل ما اعفوك منه من التقادم'),
(3135, '1 Maccabees', 72, 15, 6, 'و قد ابحت لك ان تضرب في بلادك سكة خاصة'),
(3136, '1 Maccabees', 72, 15, 7, 'و ان تكون اورشليم والاقداس حرة وكل ما جهزته من الاسلحة وبنيته من الحصون التي في يدك فليبق لك'),
(3137, '1 Maccabees', 72, 15, 8, 'و كل ضريبة ملكية كانت فيما سلف او تكون فيما ياتي تفعى منها من الان على طول الزمان'),
(3138, '1 Maccabees', 72, 15, 9, 'و اذا فزنا بمملكتنا اعززناك انت وامتك والهيكل اعزازا عظيما حتى يتلالا مجدكم في الارض كلها'),
(3139, '1 Maccabees', 72, 15, 10, 'و في السنة المئة والرابعة والسبعين خرج انطيوكس الى ارض ابائه فاجتمع اليه جميع الجيوش حتى لم يبق مع تريفون الا نفر يسير'),
(3140, '1 Maccabees', 72, 15, 11, 'فتعقبه انطيوكس الملك فانطلق هاربا الى دورا التي على البحر'),
(3141, '1 Maccabees', 72, 15, 12, 'اذ ايقن ان قد تراكم عليه الشر وخذلته الجيوش'),
(3142, '1 Maccabees', 72, 15, 13, 'فنزل انطيوكس على دورا ومعه مئة وعشرون الفا من رجال الحرب وثمانية الاف فارس'),
(3143, '1 Maccabees', 72, 15, 14, 'و احاط بالمدينة وتقدم الاسطول من البحر فضايق المدينة برا وبحرا ولم يدع احدا يدخل او يخرج'),
(3144, '1 Maccabees', 72, 15, 15, 'و قدم نومانيوس والذين معه من رومية كتبا الى الملوك والبلاد كتب فيها هكذا'),
(3145, '1 Maccabees', 72, 15, 16, 'من لوكيوس وزير الرومانيين الى بطلماوس الملك سلام'),
(3146, '1 Maccabees', 72, 15, 17, 'لقد اتانا رسل اليهود اوليائنا ومناصرينا يجددون قديم الموالاة والمناصرة مرسلين من قبل سمعان الكاهن وشعب اليهود'),
(3147, '1 Maccabees', 72, 15, 18, 'و معهم ترس من ذهب وزنه الف منا'),
(3148, '1 Maccabees', 72, 15, 19, 'فلذلك راينا ان نكتب الى الملوك والبلاد ان لا يطلبوهم بسوء ولا يقيموا عليهم حربا ولا على شيء من مدنهم وبلادهم ولا يناصروا من يحاربهم'),
(3149, '1 Maccabees', 72, 15, 20, 'و حسن لدينا ان نقبل منهم الترس'),
(3150, '1 Maccabees', 72, 15, 21, 'فان فر اليكم من بلادهم بعض من رجال الفساد فاسلموهم الى سمعان الكاهن الاعظم لينتقم منهم على مقتضى شريعتهم'),
(3151, '1 Maccabees', 72, 15, 22, 'و كتب مثل ذلك الى ديمتريوس الملك واتالس وارياراطيس وارساكيس'),
(3152, '1 Maccabees', 72, 15, 23, 'و الى جميع البلاد الى لمساكس واسبرطة وديلس ومندس وسيكيون وكارية وسامس وبمفيلية وليكية واليكرنسس ورودس وفسيليس وكوس وسيدن وارادس وجرتينة وكنيدس وقبرس والقيروان'),
(3153, '1 Maccabees', 72, 15, 24, 'و كتبوا بنسخة تلك الكتب الى سمعان الكاهن الاعظم'),
(3154, '1 Maccabees', 72, 15, 25, 'و عاد انطيوكس الملك فحاصر دورا ولم يزل يضايقها وينصب عليها المجانيق واحاط بالتريفون لئلا يدخل ويخرج'),
(3155, '1 Maccabees', 72, 15, 26, 'فارسل اليه سمعان الفي رجل منتخبين نصرة له وفضة وذهبا وانية كثيرة'),
(3156, '1 Maccabees', 72, 15, 27, 'فابى انطيوكس ان يقبلها ونقض كل ما كان عاهده به من قبل وتغير عليه'),
(3157, '1 Maccabees', 72, 15, 28, 'و ارسل اليه اتينوبيوس احد اصحابه ليفاوضه قائلا انكم مستولون على يافا وجازر والقلعة التي باورشليم وهي من مدن مملكتي'),
(3158, '1 Maccabees', 72, 15, 29, 'و قد خربتم تخومها وضربتم الارض ضربة عظيمة وتسلطتم على اماكن كثيرة في مملكتي'),
(3159, '1 Maccabees', 72, 15, 30, 'فالان اسلموا المدن التي استحوذتم عليها وادوا خراج الاماكن التي تسلطتم عليها في خارج تخوم اليهودية'),
(3160, '1 Maccabees', 72, 15, 31, 'و الا فادوا عنها خمس مئة قنطار فضة وعن الاتلاف الذي اتلفتموه وعن خراج المدن خمس مئة قنطار اخرى والا وفدنا عليكم مقاتلين'),
(3161, '1 Maccabees', 72, 15, 32, 'فجاء اتينوبيوس صاحب الملك الى اورشليم وشاهد مجد سمعان وخزانة انيته الفضية والذهبية واثاثا وافرا فبهت واخبرهبكلام الملك'),
(3162, '1 Maccabees', 72, 15, 33, 'فاجاب سمعان وقال له انا لم ناخذ ارضا لغريب ولم نستول على شيء لاجنبي ولكنه ميراث ابائنا الذي كان اعداؤنا قد استولوا عليه ظلما حينا من الدهر'),
(3163, '1 Maccabees', 72, 15, 34, 'فلما اصبنا الفرصة استرددنا ميراث ابائنا'),
(3164, '1 Maccabees', 72, 15, 35, 'فاما يافا وجازر اللتان تطالب بهما فانهما كانتا تجلبان على الشعب في بلادنا نكبات شديدة غير انا نؤدي عنهما مئة قنطار فلم يجبه اتينوبيوس بكلمة'),
(3165, '1 Maccabees', 72, 15, 36, 'و رجع الى الملك مغضبا واخبره بهذا الكلام وبمجد سمعان وكل ما شاهده فغضب الملك غضبا شديدا'),
(3166, '1 Maccabees', 72, 15, 37, 'و ركب تريفون في سفينة وفر الى ارطوسياس'),
(3167, '1 Maccabees', 72, 15, 38, 'ففوض الملك قيادة الساحل الى كندباوس وجعل تحت يده جنودا من الرجالة وفرسانا'),
(3168, '1 Maccabees', 72, 15, 39, 'و امره ان يزحف على اليهودية واوعز اليه ان يبني قدرون ويحصن الابواب ويقاتل الشعب ثم ان الملك تعقب تريفون'),
(3169, '1 Maccabees', 72, 15, 40, 'فبلغ كندباوس الى يمنيا وجعل يرغم الشعب ويغير على اليهودية ويسبي في الشعب ويقتل وبني قدرون'),
(3170, '1 Maccabees', 72, 15, 41, 'و جعل فيها فرسانا وجنودا ليخرجوا وينتشروا في طرق اليهودية كما رسم له الملك'),
(3171, '1 Maccabees', 72, 16, 1, 'فصعد يوحنا من جازر واخبر سمعان اباه بما صنع كندباوس'),
(3172, '1 Maccabees', 72, 16, 2, 'فدعا سمعان ابنيه الاكبرين يهوذا ويوحنا وقال لهما انا لم نزل انا واخوتي وبيت ابي نحارب حروب اسرائيل منذ صغرنا الى هذا اليوم وقد انجح على ايدينا خلاص اسرائيل مرارا كثيرة'),
(3173, '1 Maccabees', 72, 16, 3, 'و الان فاني قد شخت وانتما برحمة الله قد بلغتما اشدكما فقوما مقامي ومقام اخي واخرجا وقاتلا عن امتكما وليؤازركما النصر من السماء'),
(3174, '1 Maccabees', 72, 16, 4, 'و انتخب من البلاد عشرين الفا من رجال الحرب والفرسان فزحفوا على كندباوس وباتوا بمودين'),
(3175, '1 Maccabees', 72, 16, 5, 'ثم قاموا في الغد وانطلقوا الى السهل فاذا تلقائهم جيش عظيم من الرجالة والفرسان وكان بين الفريقين واد'),
(3176, '1 Maccabees', 72, 16, 6, 'فنزل يوحنا بازائهم هو وشعبه واذ راى الشعب خائفا من عبور الوادي عبر هو اولا فلما راه الرجال عبروه وراءه'),
(3177, '1 Maccabees', 72, 16, 7, 'ففرق الشعب وجعل الفرسان في وسط الرجالة وكانت فرسان العدو كثيرة جدا'),
(3178, '1 Maccabees', 72, 16, 8, 'ثم نفخوا في الابواق المقدسة فانكسر كندباوس وجيشه وسقط منهم قتلى كثيرين وفر الباقون الى الحصن'),
(3179, '1 Maccabees', 72, 16, 9, 'حينئذ جرح يهوذا اخو يوحنا وتعقبهم يوحنا حتى بلغ كندباوس الى قدرون التي بناها'),
(3180, '1 Maccabees', 72, 16, 10, 'ففروا الى البروج التي بارض اشدود فاحرقها بالنار فسقط منهم الفا رجل ثم رجع الى ارض يهوذا بسلام'),
(3181, '1 Maccabees', 72, 16, 11, 'و كان بطلماوس بن ابوبس قد اقيم قائدا في بقعة اريحا وكان عنده من الفضة والذهب شيء كثير'),
(3182, '1 Maccabees', 72, 16, 12, 'و كان صهر الكاهن الاعظم'),
(3183, '1 Maccabees', 72, 16, 13, 'فتشامخ في قلبه وطلب ان يستولي على البلاد وقد نوى الغدر بسمعان وبنيه حتى يهلكهم'),
(3184, '1 Maccabees', 72, 16, 14, 'و كان سمعان يجول في مدن البلاد ينظر في مهماتها فنزل الى اريحا هو ومتتيا ويهوذا ابناه في السنة المئة والسابعة والسبعين في شهر شباط'),
(3185, '1 Maccabees', 72, 16, 15, 'فانزلهم ابن ابوبس بحصين كان قد بناه يقال له دوق وهو يضمر لهم الغدر وصنع لهم مادبة عظيمة واخفى هناك رجالا'),
(3186, '1 Maccabees', 72, 16, 16, 'فلما سكر سمعان وبنوه قام بطلماوس ومن معه واخذوا سلاحهم ووثبوا على سمعان في المادبة وقتلوه هو وابنيه وبعضا من غلمانه'),
(3187, '1 Maccabees', 72, 16, 17, 'و خان خيانة فظيعة وكافا الخير بالشر'),
(3188, '1 Maccabees', 72, 16, 18, 'ثم كتب بطلماوس بذلك وارسل الى الملك ان يوجه اليه جيشا لنصرته فيسلم اليه البلاد والمدن'),
(3189, '1 Maccabees', 72, 16, 19, 'و وجه قوما الى جازر لاهلاك يوحنا وانفذ كتبا الى رؤساء الالوف ان ياتوه حتى يعطيهم فضة وذهبا وهدايا'),
(3190, '1 Maccabees', 72, 16, 20, 'و ارسل اخرين ليستولوا على اورشليم وجبل الهيكل'),
(3191, '1 Maccabees', 72, 16, 21, 'فسبق واحد واخبر يوحنا في جازر بهلاك ابيه واخويه وان بطلماوس قد بعث من يقتله'),
(3192, '1 Maccabees', 72, 16, 22, 'فلما سمع ذلك بهت جدا وقبض على الرجال الذين اتوا ليقتلوه وقتلهم لعلمه انهم يريدون اهلاكه'),
(3193, '1 Maccabees', 72, 16, 23, 'و بقية اخبار يوحنا وحروبه وما ابداه من الحماسة وبناؤه الاسوار التي بناها واعماله'),
(3194, '1 Maccabees', 72, 16, 24, 'مكتوبة في كتاب ايام كهنوته الاعظم منذ تقلد الكهنوت الاعظم بعد ابيه'),
(3195, '1 Peter', 60, 1, 1, ' بطرس ، رسول يسوع المسيح ، إلى المتغربين من شتات بنتس وغلاطية وكبدوكية وأسيا وبيثينية ، المختارين '),
(3196, '1 Peter', 60, 1, 2, ' بمقتضى علم الله الآب السابق ، في تقديس الروح للطاعة ، ورش دم يسوع المسيح : لتكثر لكم النعمة والسلام '),
(3197, '1 Peter', 60, 1, 3, ' مبارك الله أبو ربنا يسوع المسيح ، الذي حسب رحمته الكثيرة ولدنا ثانية لرجاء حي ، بقيامة يسوع المسيح من الأموات '),
(3198, '1 Peter', 60, 1, 4, ' لميراث لا يفنى ولا يتدنس ولا يضمحل ، محفوظ في السماوات لأجلكم '),
(3199, '1 Peter', 60, 1, 5, ' أنتم الذين بقوة الله محروسون ، بإيمان ، لخلاص مستعد أن يعلن في الزمان الأخير '),
(3200, '1 Peter', 60, 1, 6, ' الذي به تبتهجون ، مع أنكم الآن - إن كان يجب - تحزنون يسيرا بتجارب متنوعة '),
(3201, '1 Peter', 60, 1, 7, ' لكي تكون تزكية إيمانكم ، وهي أثمن من الذهب الفاني ، مع أنه يمتحن بالنار ، توجد للمدح والكرامة والمجد عند استعلان يسوع المسيح '),
(3202, '1 Peter', 60, 1, 8, ' الذي وإن لم تروه تحبونه . ذلك وإن كنتم لا ترونه الآن لكن تؤمنون به ، فتبتهجون بفرح لا ينطق به ومجيد '),
(3203, '1 Peter', 60, 1, 9, ' نائلين غاية إيمانكم خلاص النفوس '),
(3204, '1 Peter', 60, 1, 10, ' الخلاص الذي فتش وبحث عنه أنبياء ، الذين تنبأوا عن النعمة التي لأجلكم '),
(3205, '1 Peter', 60, 1, 11, ' باحثين أي وقت أو ما الوقت الذي كان يدل عليه روح المسيح الذي فيهم ، إذ سبق فشهد بالآلام التي للمسيح ، والأمجاد التي بعدها '),
(3206, '1 Peter', 60, 1, 12, ' الذين أعلن لهم أنهم ليس لأنفسهم ، بل لنا كانوا يخدمون بهذه الأمور التي أخبرتم بها أنتم الآن ، بواسطة الذين بشروكم في الروح القدس المرسل من السماء . التي تشتهي الملائكة أن تطلع عليها '),
(3207, '1 Peter', 60, 1, 13, ' لذلك منطقوا أحقاء ذهنكم صاحين ، فألقوا رجاءكم بالتمام على النعمة التي يؤتى بها إليكم عند استعلان يسوع المسيح '),
(3208, '1 Peter', 60, 1, 14, ' كأولاد الطاعة ، لا تشاكلوا شهواتكم السابقة في جهالتكم '),
(3209, '1 Peter', 60, 1, 15, ' بل نظير القدوس الذي دعاكم ، كونوا أنتم أيضا قديسين في كل سيرة '),
(3210, '1 Peter', 60, 1, 16, ' لأنه مكتوب : كونوا قديسين لأني أنا قدوس '),
(3211, '1 Peter', 60, 1, 17, ' وإن كنتم تدعون أبا الذي يحكم بغير محاباة حسب عمل كل واحد ، فسيروا زمان غربتكم بخوف '),
(3212, '1 Peter', 60, 1, 18, ' عالمين أنكم افتديتم لا بأشياء تفنى ، بفضة أو ذهب ، من سيرتكم الباطلة التي تقلدتموها من الآباء '),
(3213, '1 Peter', 60, 1, 19, ' بل بدم كريم ، كما من حمل بلا عيب ولا دنس ، دم المسيح '),
(3214, '1 Peter', 60, 1, 20, ' معروفا سابقا قبل تأسيس العالم ، ولكن قد أظهر في الأزمنة الأخيرة من أجلكم '),
(3215, '1 Peter', 60, 1, 21, ' أنتم الذين به تؤمنون بالله الذي أقامه من الأموات وأعطاه مجدا ، حتى إن إيمانكم ورجاءكم هما في الله '),
(3216, '1 Peter', 60, 1, 22, ' طهروا نفوسكم في طاعة الحق بالروح للمحبة الأخوية العديمة الرياء ، فأحبوا بعضكم بعضا من قلب طاهر بشدة '),
(3217, '1 Peter', 60, 1, 23, ' مولودين ثانية ، لا من زرع يفنى ، بل مما لا يفنى ، بكلمة الله الحية الباقية إلى الأبد '),
(3218, '1 Peter', 60, 1, 24, ' لأن : كل جسد كعشب ، وكل مجد إنسان كزهر عشب . العشب يبس وزهره سقط '),
(3219, '1 Peter', 60, 1, 25, ' وأما كلمة الرب فتثبت إلى الأبد . وهذه هي الكلمة التي بشرتم بها '),
(3220, '1 Peter', 60, 2, 1, ' فاطرحوا كل خبث وكل مكر والرياء والحسد وكل مذمة '),
(3221, '1 Peter', 60, 2, 2, ' وكأطفال مولودين الآن ، اشتهوا اللبن العقلي العديم الغش لكي تنموا به '),
(3222, '1 Peter', 60, 2, 3, ' إن كنتم قد ذقتم أن الرب صالح . الحجر الحي والشعب المختار '),
(3223, '1 Peter', 60, 2, 4, ' الذي إذ تأتون إليه ، حجرا حيا مرفوضا من الناس ، ولكن مختار من الله كريم '),
(3224, '1 Peter', 60, 2, 5, ' كونوا أنتم أيضا مبنيين - كحجارة حية - بيتا روحيا ، كهنوتا مقدسا ، لتقديم ذبائح روحية مقبولة عند الله بيسوع المسيح '),
(3225, '1 Peter', 60, 2, 6, ' لذلك يتضمن أيضا في الكتاب : هنذا أضع في صهيون حجر زاوية مختارا كريما ، والذي يؤمن به لن يخزى '),
(3226, '1 Peter', 60, 2, 7, ' فلكم أنتم الذين تؤمنون الكرامة ، وأما للذين لا يطيعون : فالحجر الذي رفضه البناؤون ، هو قد صار رأس الزاوية '),
(3227, '1 Peter', 60, 2, 8, ' وحجر صدمة وصخرة عثرة . الذين يعثرون غير طائعين للكلمة ، الأمر الذي جعلوا له '),
(3228, '1 Peter', 60, 2, 9, ' وأما أنتم فجنس مختار ، وكهنوت ملوكي ، أمة مقدسة ، شعب اقتناء ، لكي تخبروا بفضائل الذي دعاكم من الظلمة إلى نوره العجيب '),
(3229, '1 Peter', 60, 2, 10, ' الذين قبلا لم تكونوا شعبا ، وأما الآن فأنتم شعب الله . الذين كنتم غير مرحومين ، وأما الآن فمرحومون '),
(3230, '1 Peter', 60, 2, 11, ' أيها الأحباء ، أطلب إليكم كغرباء ونزلاء ، أن تمتنعوا عن الشهوات الجسدية التي تحارب النفس '),
(3231, '1 Peter', 60, 2, 12, ' وأن تكون سيرتكم بين الأمم حسنة ، لكي يكونوا ، في ما يفترون عليكم كفاعلي شر ، يمجدون الله في يوم الافتقاد ، من أجل أعمالكم الحسنة التي يلاحظونها '),
(3232, '1 Peter', 60, 2, 13, ' فاخضعوا لكل ترتيب بشري من أجل الرب . إن كان للملك فكمن هو فوق الكل '),
(3233, '1 Peter', 60, 2, 14, ' أو للولاة فكمرسلين منه للانتقام من فاعلي الشر ، وللمدح لفاعلي الخير '),
(3234, '1 Peter', 60, 2, 15, ' لأن هكذا هي مشيئة الله : أن تفعلوا الخير فتسكتوا جهالة الناس الأغبياء '),
(3235, '1 Peter', 60, 2, 16, ' كأحرار ، وليس كالذين الحرية عندهم سترة للشر ، بل كعبيد الله '),
(3236, '1 Peter', 60, 2, 17, ' أكرموا الجميع . أحبوا الإخوة . خافوا الله . أكرموا الملك '),
(3237, '1 Peter', 60, 2, 18, ' أيها الخدام ، كونوا خاضعين بكل هيبة للسادة ، ليس للصالحين المترفقين فقط ، بل للعنفاء أيضا '),
(3238, '1 Peter', 60, 2, 19, ' لأن هذا فضل ، إن كان أحد من أجل ضمير نحو الله ، يحتمل أحزانا متألما بالظلم '),
(3239, '1 Peter', 60, 2, 20, ' لأنه أي مجد هو إن كنتم تلطمون مخطئين فتصبرون ؟ بل إن كنتم تتألمون عاملين الخير فتصبرون ، فهذا فضل عند الله '),
(3240, '1 Peter', 60, 2, 21, ' لأنكم لهذا دعيتم . فإن المسيح أيضا تألم لأجلنا ، تاركا لنا مثالا لكي تتبعوا خطواته '),
(3241, '1 Peter', 60, 2, 22, ' الذي لم يفعل خطية ، ولا وجد في فمه مكر '),
(3242, '1 Peter', 60, 2, 23, ' الذي إذ شتم لم يكن يشتم عوضا ، وإذ تألم لم يكن يهدد بل كان يسلم لمن يقضي بعدل '),
(3243, '1 Peter', 60, 2, 24, ' الذي حمل هو نفسه خطايانا في جسده على الخشبة ، لكي نموت عن الخطايا فنحيا للبر . الذي بجلدته شفيتم '),
(3244, '1 Peter', 60, 2, 25, ' لأنكم كنتم كخراف ضالة ، لكنكم رجعتم الآن إلى راعي نفوسكم وأسقفها '),
(3245, '1 Peter', 60, 3, 1, ' كذلكن أيتها النساء ، كن خاضعات لرجالكن ، حتى وإن كان البعض لا يطيعون الكلمة ، يربحون بسيرة النساء بدون كلمة '),
(3246, '1 Peter', 60, 3, 2, ' ملاحظين سيرتكن الطاهرة بخوف '),
(3247, '1 Peter', 60, 3, 3, ' ولا تكن زينتكن الزينة الخارجية ، من ضفر الشعر والتحلي بالذهب ولبس الثياب '),
(3248, '1 Peter', 60, 3, 4, ' بل إنسان القلب الخفي في العديمة الفساد ، زينة الروح الوديع الهادئ ، الذي هو قدام الله كثير الثمن '),
(3249, '1 Peter', 60, 3, 5, ' فإنه هكذا كانت قديما النساء القديسات أيضا المتوكلات على الله ، يزين أنفسهن خاضعات لرجالهن '),
(3250, '1 Peter', 60, 3, 6, ' كما كانت سارة تطيع إبراهيم داعية إياه سيدها . التي صرتن أولادها ، صانعات خيرا ، وغير خائفات خوفا البتة '),
(3251, '1 Peter', 60, 3, 7, ' كذلكم أيها الرجال ، كونوا ساكنين بحسب الفطنة مع الإناء النسائي كالأضعف ، معطين إياهن كرامة ، كالوارثات أيضا معكم نعمة الحياة ، لكي لا تعاق صلواتكم '),
(3252, '1 Peter', 60, 3, 8, ' والنهاية ، كونوا جميعا متحدي الرأي بحس واحد ، ذوي محبة أخوية ، مشفقين ، لطفاء '),
(3253, '1 Peter', 60, 3, 9, ' غير مجازين عن شر بشر أو عن شتيمة بشتيمة ، بل بالعكس مباركين ، عالمين أنكم لهذا دعيتم لكي ترثوا بركة '),
(3254, '1 Peter', 60, 3, 10, ' لأن : من أراد أن يحب الحياة ويرى أياما صالحة ، فليكفف لسانه عن الشر وشفتيه أن تتكلما بالمكر '),
(3255, '1 Peter', 60, 3, 11, ' ليعرض عن الشر ويصنع الخير ، ليطلب السلام ويجد في أثره '),
(3256, '1 Peter', 60, 3, 12, ' لأن عيني الرب على الأبرار ، وأذنيه إلى طلبتهم ، ولكن وجه الرب ضد فاعلي الشر '),
(3257, '1 Peter', 60, 3, 13, ' فمن يؤذيكم إن كنتم متمثلين بالخير '),
(3258, '1 Peter', 60, 3, 14, ' ولكن وإن تألمتم من أجل البر ، فطوباكم . وأما خوفهم فلا تخافوه ولا تضطربوا '),
(3259, '1 Peter', 60, 3, 15, ' بل قدسوا الرب الإله في قلوبكم ، مستعدين دائما لمجاوبة كل من يسألكم عن سبب الرجاء الذي فيكم ، بوداعة وخوف '),
(3260, '1 Peter', 60, 3, 16, ' ولكم ضمير صالح ، لكي يكون الذين يشتمون سيرتكم الصالحة في المسيح ، يخزون في ما يفترون عليكم كفاعلي شر '),
(3261, '1 Peter', 60, 3, 17, ' لأن تألمكم إن شاءت مشيئة الله ، وأنتم صانعون خيرا ، أفضل منه وأنتم صانعون شرا '),
(3262, '1 Peter', 60, 3, 18, ' فإن المسيح أيضا تألم مرة واحدة من أجل الخطايا ، البار من أجل الأثمة ، لكي يقربنا إلى الله ، مماتا في الجسد ولكن محيى في الروح '),
(3263, '1 Peter', 60, 3, 19, ' الذي فيه أيضا ذهب فكرز للأرواح التي في السجن '),
(3264, '1 Peter', 60, 3, 20, ' إذ عصت قديما ، حين كانت أناة الله تنتظر مرة في أيام نوح ، إذ كان الفلك يبنى ، الذي فيه خلص قليلون ، أي ثماني أنفس بالماء '),
(3265, '1 Peter', 60, 3, 21, ' الذي مثاله يخلصنا نحن الآن ، أي المعمودية . لا إزالة وسخ الجسد ، بل سؤال ضمير صالح عن الله ، بقيامة يسوع المسيح '),
(3266, '1 Peter', 60, 3, 22, ' الذي هو في يمين الله ، إذ قد مضى إلى السماء ، وملائكة وسلاطين وقوات مخضعة له '),
(3267, '1 Peter', 60, 4, 1, ' فإذ قد تألم المسيح لأجلنا بالجسد ، تسلحوا أنتم أيضا بهذه النية . فإن من تألم في الجسد ، كف عن الخطية '),
(3268, '1 Peter', 60, 4, 2, ' لكي لا يعيش أيضا الزمان الباقي في الجسد ، لشهوات الناس ، بل لإرادة الله '),
(3269, '1 Peter', 60, 4, 3, ' لأن زمان الحياة الذي مضى يكفينا لنكون قد عملنا إرادة الأمم ، سالكين في الدعارة والشهوات ، وإدمان الخمر ، والبطر ، والمنادمات ، وعبادة الأوثان المحرمة '),
(3270, '1 Peter', 60, 4, 4, ' الأمر الذي فيه يستغربون أنكم لستم تركضون معهم إلى فيض هذه الخلاعة عينها ، مجدفين '),
(3271, '1 Peter', 60, 4, 5, ' الذين سوف يعطون حسابا للذي هو على استعداد أن يدين الأحياء والأموات '),
(3272, '1 Peter', 60, 4, 6, ' فإنه لأجل هذا بشر الموتى أيضا ، لكي يدانوا حسب الناس بالجسد ، ولكن ليحيوا حسب الله بالروح '),
(3273, '1 Peter', 60, 4, 7, ' وإنما نهاية كل شيء قد اقتربت ، فتعقلوا واصحوا للصلوات '),
(3274, '1 Peter', 60, 4, 8, ' ولكن قبل كل شيء ، لتكن محبتكم بعضكم لبعض شديدة ، لأن المحبة تستر كثرة من الخطايا '),
(3275, '1 Peter', 60, 4, 9, ' كونوا مضيفين بعضكم بعضا بلا دمدمة '),
(3276, '1 Peter', 60, 4, 10, ' ليكن كل واحد بحسب ما أخذ موهبة ، يخدم بها بعضكم بعضا ، كوكلاء صالحين على نعمة الله المتنوعة '),
(3277, '1 Peter', 60, 4, 11, ' إن كان يتكلم أحد فكأقوال الله . وإن كان يخدم أحد فكأنه من قوة يمنحها الله ، لكي يتمجد الله في كل شيء بيسوع المسيح ، الذي له المجد والسلطان إلى أبد الآبدين . آمين '),
(3278, '1 Peter', 60, 4, 12, ' أيها الأحباء ، لا تستغربوا البلوى المحرقة التي بينكم حادثة ، لأجل امتحانكم ، كأنه أصابكم أمر غريب '),
(3279, '1 Peter', 60, 4, 13, ' بل كما اشتركتم في آلام المسيح ، افرحوا لكي تفرحوا في استعلان مجده أيضا مبتهجين '),
(3280, '1 Peter', 60, 4, 14, ' إن عيرتم باسم المسيح ، فطوبى لكم ، لأن روح المجد والله يحل عليكم . أما من جهتهم فيجدف عليه ، وأما من جهتكم فيمجد '),
(3281, '1 Peter', 60, 4, 15, ' فلا يتألم أحدكم كقاتل ، أو سارق ، أو فاعل شر ، أو متداخل في أمور غيره '),
(3282, '1 Peter', 60, 4, 16, ' ولكن إن كان كمسيحي ، فلا يخجل ، بل يمجد الله من هذا القبيل '),
(3283, '1 Peter', 60, 4, 17, ' لأنه الوقت لابتداء القضاء من بيت الله . فإن كان أولا منا ، فما هي نهاية الذين لا يطيعون إنجيل الله '),
(3284, '1 Peter', 60, 4, 18, ' وإن كان البار بالجهد يخلص ، فالفاجر والخاطئ أين يظهران '),
(3285, '1 Peter', 60, 4, 19, ' فإذا ، الذين يتألمون بحسب مشيئة الله ، فليستودعوا أنفسهم - كما لخالق أمين - في عمل الخير '),
(3286, '1 Peter', 60, 5, 1, ' أطلب إلى الشيوخ الذين بينكم ، أنا الشيخ رفيقهم ، والشاهد لآلام المسيح ، وشريك المجد العتيد أن يعلن '),
(3287, '1 Peter', 60, 5, 2, ' ارعوا رعية الله التي بينكم نظارا ، لا عن اضطرار بل بالاختيار ، ولا لربح قبيح بل بنشاط '),
(3288, '1 Peter', 60, 5, 3, ' ولا كمن يسود على الأنصبة ، بل صائرين أمثلة للرعية '),
(3289, '1 Peter', 60, 5, 4, ' ومتى ظهر رئيس الرعاة تنالون إكليل المجد الذي لا يبلى '),
(3290, '1 Peter', 60, 5, 5, ' كذلك أيها الأحداث ، اخضعوا للشيوخ ، وكونوا جميعا خاضعين بعضكم لبعض ، وتسربلوا بالتواضع ، لأن : الله يقاوم المستكبرين ، وأما المتواضعون فيعطيهم نعمة '),
(3291, '1 Peter', 60, 5, 6, ' فتواضعوا تحت يد الله القوية لكي يرفعكم في حينه '),
(3292, '1 Peter', 60, 5, 7, ' ملقين كل همكم عليه ، لأنه هو يعتني بكم '),
(3293, '1 Peter', 60, 5, 8, ' اصحوا واسهروا . لأن إبليس خصمكم كأسد زائر ، يجول ملتمسا من يبتلعه هو '),
(3294, '1 Peter', 60, 5, 9, ' فقاوموه ، راسخين في الإيمان ، عالمين أن نفس هذه الآلام تجرى على إخوتكم الذين في العالم '),
(3295, '1 Peter', 60, 5, 10, ' وإله كل نعمة الذي دعانا إلى مجده الأبدي في المسيح يسوع ، بعدما تألمتم يسيرا ، هو يكملكم ، ويثبتكم ، ويقويكم ، ويمكنكم '),
(3296, '1 Peter', 60, 5, 11, ' له المجد والسلطان إلى أبد الآبدين . آمين '),
(3297, '1 Peter', 60, 5, 12, ' بيد سلوانس الأخ الأمين ، - كما أظن - كتبت إليكم بكلمات قليلة واعظا وشاهدا ، أن هذه هي نعمة الله الحقيقية التي فيها تقومون '),
(3298, '1 Peter', 60, 5, 13, ' تسلم عليكم التي في بابل المختارة معكم ، ومرقس ابني '),
(3299, '1 Peter', 60, 5, 14, ' سلموا بعضكم على بعض بقبلة المحبة . سلام لكم جميعكم الذين في المسيح يسوع . آمين '),
(3300, '1 Samuel', 9, 1, 11, ' ونذرت نذرا وقالت : يارب الجنود ، إن نظرت نظرا إلى مذلة أمتك ، وذكرتني ولم تنس أمتك بل أعطيت أمتك زرع بشر ، فإني أعطيه للرب كل أيام حياته ، ولا يعلو رأسه موسى '),
(3301, '1 Samuel', 9, 1, 12, ' وكان إذ أكثرت الصلاة أمام الرب وعالي يلاحظ فاها '),
(3302, '1 Samuel', 9, 1, 13, ' فإن حنة كانت تتكلم في قلبها ، وشفتاها فقط تتحركان ، وصوتها لم يسمع ، أن عالي ظنها سكرى '),
(3303, '1 Samuel', 9, 1, 14, ' فقال لها عالي : حتى متى تسكرين ؟ انزعي خمرك عنك '),
(3304, '1 Samuel', 9, 1, 15, ' فأجابت حنة وقالت : لا يا سيدي . إني امرأة حزينة الروح ولم أشرب خمرا ولا مسكرا ، بل أسكب نفسي أمام الرب '),
(3305, '1 Samuel', 9, 1, 16, ' لا تحسب أمتك ابنة بليعال ، لأني من كثرة كربتي وغيظي قد تكلمت إلى الآن '),
(3306, '1 Samuel', 9, 1, 17, ' فأجاب عالي وقال : اذهبي بسلام ، وإله إسرائيل يعطيك سؤلك الذي سألته من لدنه '),
(3307, '1 Samuel', 9, 1, 18, ' فقالت : لتجد جاريتك نعمة في عينيك . ثم مضت المرأة في طريقها وأكلت ، ولم يكن وجهها بعد مغيرا '),
(3308, '1 Samuel', 9, 1, 19, ' وبكروا في الصباح وسجدوا أمام الرب ، ورجعوا وجاءوا إلى بيتهم في الرامة . وعرف ألقانة امرأته حنة ، والرب ذكرها '),
(3309, '1 Samuel', 9, 1, 20, ' وكان في مدار السنة أن حنة حبلت وولدت ابنا ودعت اسمه صموئيل ، قائلة : لأني من الرب سألته '),
(3310, '1 Samuel', 9, 1, 21, ' وصعد الرجل ألقانة وجميع بيته ليذبح للرب الذبيحة السنوية ، ونذره '),
(3311, '1 Samuel', 9, 1, 22, ' ولكن حنة لم تصعد لأنها قالت لرجلها : متى فطم الصبي آتي به ليتراءى أمام الرب ويقيم هناك إلى الأبد '),
(3312, '1 Samuel', 9, 1, 23, ' فقال لها ألقانة رجلها : اعملي ما يحسن في عينيك . امكثي حتى تفطميه . إنما الرب يقيم كلامه . فمكثت المرأة وأرضعت ابنها حتى فطمته '),
(3313, '1 Samuel', 9, 1, 24, ' ثم حين فطمته أصعدته معها بثلاثة ثيران وإيفة دقيق وزق خمر ، وأتت به إلى الرب في شيلوه والصبي صغير '),
(3314, '1 Samuel', 9, 1, 25, ' فذبحوا الثور وجاءوا بالصبي إلى عالي '),
(3315, '1 Samuel', 9, 1, 26, ' وقالت : أسألك يا سيدي . حية هي نفسك يا سيدي ، أنا المرأة التي وقفت لديك هنا تصلي إلى الرب '),
(3316, '1 Samuel', 9, 1, 27, ' لأجل هذا الصبي صليت فأعطاني الرب سؤلي الذي سألته من لدنه '),
(3317, '1 Samuel', 9, 1, 28, ' وأنا أيضا قد أعرته للرب . جميع أيام حياته هو عارية للرب . وسجد هناك للرب '),
(3318, '1 Samuel', 9, 2, 1, ' فصلت حنة وقالت : فرح قلبي بالرب . ارتفع قرني بالرب . اتسع فمي على أعدائي ، لأني قد ابتهجت بخلاصك '),
(3319, '1 Samuel', 9, 2, 2, ' ليس قدوس مثل الرب ، لأنه ليس غيرك ، وليس صخرة مثل إلهنا '),
(3320, '1 Samuel', 9, 2, 3, ' لا تكثروا الكلام العالي المستعلي ، ولتبرح وقاحة من أفواهكم . لأن الرب إله عليم ، وبه توزن الأعمال '),
(3321, '1 Samuel', 9, 2, 4, ' قسي الجبابرة انحطمت ، والضعفاء تمنطقوا بالبأس '),
(3322, '1 Samuel', 9, 2, 5, ' الشباعى آجروا أنفسهم بالخبز ، والجياع كفوا . حتى أن العاقر ولدت سبعة ، وكثيرة البنين ذبلت '),
(3323, '1 Samuel', 9, 2, 6, ' الرب يميت ويحيي . يهبط إلى الهاوية ويصعد '),
(3324, '1 Samuel', 9, 2, 7, ' الرب يفقر ويغني . يضع ويرفع '),
(3325, '1 Samuel', 9, 2, 8, ' يقيم المسكين من التراب . يرفع الفقير من المزبلة للجلوس مع الشرفاء ويملكهم كرسي المجد . لأن للرب أعمدة الأرض ، وقد وضع عليها المسكونة '),
(3326, '1 Samuel', 9, 2, 9, ' أرجل أتقيائه يحرس ، والأشرار في الظلام يصمتون . لأنه ليس بالقوة يغلب إنسان '),
(3327, '1 Samuel', 9, 2, 10, ' مخاصمو الرب ينكسرون . من السماء يرعد عليهم . الرب يدين أقاصي الأرض ، ويعطي عزا لملكه ، ويرفع قرن مسيحه '),
(3328, '1 Samuel', 9, 2, 11, ' وذهب ألقانة إلى الرامة إلى بيته ، وكان الصبي يخدم الرب أمام عالي الكاهن '),
(3329, '1 Samuel', 9, 2, 12, ' وكان بنو عالي ، بني بليعال ، لم يعرفوا الرب '),
(3330, '1 Samuel', 9, 2, 13, ' ولا حق الكهنة من الشعب . كلما ذبح رجل ذبيحة يجيء غلام الكاهن عند طبخ اللحم ، ومنشال ذو ثلاثة أسنان بيده '),
(3331, '1 Samuel', 9, 2, 14, ' فيضرب في المرحضة أو المرجل أو المقلى أو القدر . كل ما يصعد به المنشل يأخذه الكاهن لنفسه . هكذا كانوا يفعلون بجميع إسرائيل الآتين إلى هناك في شيلوه '),
(3332, '1 Samuel', 9, 2, 15, ' كذلك قبل ما يحرقون الشحم يأتي غلام الكاهن ويقول للرجل الذابح : أعط لحما ليشوى للكاهن ، فإنه لا يأخذ منك لحما مطبوخا بل نيئا '),
(3333, '1 Samuel', 9, 2, 16, ' فيقول له الرجل : ليحرقوا أولا الشحم ، ثم خذ ما تشتهيه نفسك . فيقول له : لا ، بل الآن تعطي وإلا فآخذ غصبا '),
(3334, '1 Samuel', 9, 2, 17, ' فكانت خطية الغلمان عظيمة جدا أمام الرب ، لأن الناس استهانوا بتقدمة الرب '),
(3335, '1 Samuel', 9, 2, 18, ' وكان صموئيل يخدم أمام الرب وهو صبي متمنطق بأفود من كتان '),
(3336, '1 Samuel', 9, 2, 19, ' وعملت له أمه جبة صغيرة وأصعدتها له من سنة إلى سنة عند صعودها مع رجلها لذبح الذبيحة السنوية '),
(3337, '1 Samuel', 9, 2, 20, ' وبارك عالي ألقانة وامرأته وقال : يجعل لك الرب نسلا من هذه المرأة بدل العارية التي أعارت للرب . وذهبا إلى مكانهما '),
(3338, '1 Samuel', 9, 2, 21, ' ولما افتقد الرب حنة حبلت وولدت ثلاثة بنين وبنتين . وكبر الصبي صموئيل عند الرب '),
(3339, '1 Samuel', 9, 2, 22, ' وشاخ عالي جدا ، وسمع بكل ما عمله بنوه بجميع إسرائيل وبأنهم كانوا يضاجعون النساء المجتمعات في باب خيمة الاجتماع '),
(3340, '1 Samuel', 9, 2, 23, ' فقال لهم : لماذا تعملون مثل هذه الأمور ؟ لأني أسمع بأموركم الخبيثة من جميع هذا الشعب '),
(3341, '1 Samuel', 9, 2, 24, ' لا يا بني ، لأنه ليس حسنا الخبر الذي أسمع . تجعلون شعب الرب يتعدون '),
(3342, '1 Samuel', 9, 2, 25, ' إذا أخطأ إنسان إلى إنسان يدينه الله . فإن أخطأ إنسان إلى الرب فمن يصلي من أجله ؟  . ولم يسمعوا لصوت أبيهم لأن الرب شاء أن يميتهم '),
(3343, '1 Samuel', 9, 2, 26, ' وأما الصبي صموئيل فتزايد نموا وصلاحا لدى الرب والناس أيضا '),
(3344, '1 Samuel', 9, 2, 27, ' وجاء رجل الله إلى عالي وقال له : هكذا يقول الرب : هل تجليت لبيت أبيك وهم في مصر في بيت فرعون '),
(3345, '1 Samuel', 9, 2, 28, ' وانتخبته من جميع أسباط إسرائيل لي كاهنا ليصعد على مذبحي ويوقد بخورا ويلبس أفودا أمامي ، ودفعت لبيت أبيك جميع وقائد بني إسرائيل '),
(3346, '1 Samuel', 9, 2, 29, ' فلماذا تدوسون ذبيحتي وتقدمتي التي أمرت بها في المسكن ، وتكرم بنيك علي لكي تسمنوا أنفسكم بأوائل كل تقدمات إسرائيل شعبي '),
(3347, '1 Samuel', 9, 2, 30, ' لذلك يقول الرب إله إسرائيل : إني قلت إن بيتك وبيت أبيك يسيرون أمامي إلى الأبد . والآن يقول الرب : حاشا لي فإني أكرم الذين يكرمونني ، والذين يحتقرونني يصغرون '),
(3348, '1 Samuel', 9, 2, 31, ' هوذا تأتي أيام أقطع فيها ذراعك وذراع بيت أبيك حتى لا يكون شيخ في بيتك '),
(3349, '1 Samuel', 9, 2, 32, ' وترى ضيق المسكن في كل ما يحسن به إلى إسرائيل ، ولا يكون شيخ في بيتك كل الأيام '),
(3350, '1 Samuel', 9, 2, 33, ' ورجل لك لا أقطعه من أمام مذبحي يكون لإكلال عينيك وتذويب نفسك . وجميع ذرية بيتك يموتون شبانا '),
(3351, '1 Samuel', 9, 2, 34, ' وهذه لك علامة تأتي على ابنيك حفني وفينحاس : في يوم واحد يموتان كلاهما '),
(3352, '1 Samuel', 9, 2, 35, ' وأقيم لنفسي كاهنا أمينا يعمل حسب ما بقلبي ونفسي ، وأبني له بيتا أمينا فيسير أمام مسيحي كل الأيام '),
(3353, '1 Samuel', 9, 2, 36, ' ويكون أن كل من يبقى في بيتك يأتي ليسجد له لأجل قطعة فضة ورغيف خبز ، ويقول : ضمني إلى إحدى وظائف الكهنوت لآكل كسرة خبز '),
(3354, '1 Samuel', 9, 3, 1, ' وكان الصبي صموئيل يخدم الرب أمام عالي . وكانت كلمة الرب عزيزة في تلك الأيام . لم تكن رؤيا كثيرا '),
(3355, '1 Samuel', 9, 3, 2, ' وكان في ذلك الزمان إذ كان عالي مضطجعا في مكانه وعيناه ابتدأتا تضعفان ، لم يقدر أن يبصر '),
(3356, '1 Samuel', 9, 3, 3, ' وقبل أن ينطفئ سراج الله ، وصموئيل مضطجع في هيكل الرب الذي فيه تابوت الله '),
(3357, '1 Samuel', 9, 3, 4, ' أن الرب دعا صموئيل ، فقال : هأنذا '),
(3358, '1 Samuel', 9, 3, 5, ' وركض إلى عالي وقال : هأنذا لأنك دعوتني . فقال : لم أدع . ارجع اضطجع . فذهب واضطجع '),
(3359, '1 Samuel', 9, 3, 6, ' ثم عاد الرب ودعا أيضا صموئيل . فقام صموئيل وذهب إلى عالي وقال : هأنذا لأنك دعوتني . فقال : لم أدع يا ابني . ارجع اضطجع '),
(3360, '1 Samuel', 9, 3, 7, ' ولم يعرف صموئيل الرب بعد ، ولا أعلن له كلام الرب بعد '),
(3361, '1 Samuel', 9, 3, 8, ' وعاد الرب فدعا صموئيل ثالثة . فقام وذهب إلى عالي وقال : هأنذا لأنك دعوتني . ففهم عالي أن الرب يدعو الصبي '),
(3362, '1 Samuel', 9, 3, 9, ' فقال عالي لصموئيل : اذهب اضطجع ، ويكون إذا دعاك تقول : تكلم يارب ، لأن عبدك سامع . فذهب صموئيل واضطجع في مكانه '),
(3363, '1 Samuel', 9, 3, 10, ' فجاء الرب ووقف ودعا كالمرات الأول : صموئيل ، صموئيل . فقال صموئيل : تكلم لأن عبدك سامع '),
(3364, '1 Samuel', 9, 3, 11, ' فقال الرب لصموئيل : هوذا أنا فاعل أمرا في إسرائيل كل من سمع به تطن أذناه '),
(3365, '1 Samuel', 9, 3, 12, ' في ذلك اليوم أقيم على عالي كل ما تكلمت به على بيته . أبتدئ وأكمل '),
(3366, '1 Samuel', 9, 3, 13, ' وقد أخبرته بأني أقضي على بيته إلى الأبد ، من أجل الشر الذي يعلم أن بنيه قد أوجبوا به اللعنة على أنفسهم ، ولم يردعهم '),
(3367, '1 Samuel', 9, 3, 14, ' ولذلك أقسمت لبيت عالي أنه لا يكفر عن شر بيت عالي بذبيحة أو بتقدمة إلى الأبد '),
(3368, '1 Samuel', 9, 3, 15, ' واضطجع صموئيل إلى الصباح ، وفتح أبواب بيت الرب . وخاف صموئيل أن يخبر عالي بالرؤيا '),
(3369, '1 Samuel', 9, 3, 16, ' فدعا عالي صموئيل وقال : يا صموئيل ابني . فقال : هأنذا '),
(3370, '1 Samuel', 9, 3, 17, ' فقال : ما الكلام الذي كلمك به ؟ لا تخف عني . هكذا يعمل لك الله وهكذا يزيد إن أخفيت عني كلمة من كل الكلام الذي كلمك به '),
(3371, '1 Samuel', 9, 3, 18, ' فأخبره صموئيل بجميع الكلام ولم يخف عنه . فقال : هو الرب . ما يحسن في عينيه يعمل '),
(3372, '1 Samuel', 9, 3, 19, ' وكبر صموئيل وكان الرب معه ، ولم يدع شيئا من جميع كلامه يسقط إلى الأرض '),
(3373, '1 Samuel', 9, 3, 20, ' وعرف جميع إسرائيل من دان إلى بئر سبع أنه قد اؤتمن صموئيل نبيا للرب '),
(3374, '1 Samuel', 9, 1, 1, ' كان رجل من رامتايم صوفيم من جبل أفرايم اسمه ألقانة بن يروحام بن أليهو بن توحو بن صوف . هو أفرايمي '),
(3375, '1 Samuel', 9, 1, 2, ' وله امرأتان ، اسم الواحدة حنة ، واسم الأخرى فننة . وكان لفننة أولاد ، وأما حنة فلم يكن لها أولاد '),
(3376, '1 Samuel', 9, 1, 3, ' وكان هذا الرجل يصعد من مدينته من سنة إلى سنة ليسجد ويذبح لرب الجنود في شيلوه . وكان هناك ابنا عالي : حفني وفينحاس ، كاهنا الرب '),
(3377, '1 Samuel', 9, 1, 4, ' ولما كان الوقت وذبح ألقانة ، أعطى فننة امرأته وجميع بنيها وبناتها أنصبة '),
(3378, '1 Samuel', 9, 1, 5, ' وأما حنة فأعطاها نصيب اثنين ، لأنه كان يحب حنة . ولكن الرب كان قد أغلق رحمها '),
(3379, '1 Samuel', 9, 1, 6, ' وكانت ضرتها تغيظها أيضا غيظا لأجل المراغمة ، لأن الرب أغلق رحمها '),
(3380, '1 Samuel', 9, 1, 7, ' وهكذا صار سنة بعد سنة ، كلما صعدت إلى بيت الرب ، هكذا كانت تغيظها . فبكت ولم تأكل '),
(3381, '1 Samuel', 9, 1, 8, ' فقال لها ألقانة رجلها : يا حنة ، لماذا تبكين ؟ ولماذا لا تأكلين ؟ ولماذا يكتئب قلبك ؟ أما أنا خير لك من عشرة بنين '),
(3382, '1 Samuel', 9, 1, 9, ' فقامت حنة بعدما أكلوا في شيلوه وبعدما شربوا ، وعالي الكاهن جالس على الكرسي عند قائمة هيكل الرب '),
(3383, '1 Samuel', 9, 1, 10, ' وهي مرة النفس . فصلت إلى الرب ، وبكت بكاء '),
(3384, '1 Samuel', 9, 8, 3, ' ولم يسلك ابناه في طريقه ، بل مالا وراء المكسب ، وأخذا رشوة وعوجا القضاء '),
(3385, '1 Samuel', 9, 8, 4, ' فاجتمع كل شيوخ إسرائيل وجاءوا إلى صموئيل إلى الرامة '),
(3386, '1 Samuel', 9, 8, 5, ' وقالوا له : هوذا أنت قد شخت ، وابناك لم يسيرا في طريقك . فالآن اجعل لنا ملكا يقضي لنا كسائر الشعوب '),
(3387, '1 Samuel', 9, 8, 6, ' فساء الأمر في عيني صموئيل إذ قالوا : أعطنا ملكا يقضي لنا . وصلى صموئيل إلى الرب '),
(3388, '1 Samuel', 9, 8, 7, ' فقال الرب لصموئيل : اسمع لصوت الشعب في كل ما يقولون لك ، لأنهم لم يرفضوك أنت بل إياي رفضوا حتى لا أملك عليهم '),
(3389, '1 Samuel', 9, 8, 8, ' حسب كل أعمالهم التي عملوا من يوم أصعدتهم من مصر إلى هذا اليوم وتركوني وعبدوا آلهة أخرى ، هكذا هم عاملون بك أيضا '),
(3390, '1 Samuel', 9, 8, 9, ' فالآن اسمع لصوتهم . ولكن أشهدن عليهم وأخبرهم بقضاء الملك الذي يملك عليهم '),
(3391, '1 Samuel', 9, 8, 10, ' فكلم صموئيل الشعب الذين طلبوا منه ملكا بجميع كلام الرب '),
(3392, '1 Samuel', 9, 8, 11, ' وقال : هذا يكون قضاء الملك الذي يملك عليكم : يأخذ بنيكم ويجعلهم لنفسه ، لمراكبه وفرسانه ، فيركضون أمام مراكبه '),
(3393, '1 Samuel', 9, 8, 12, ' ويجعل لنفسه رؤساء ألوف ورؤساء خماسين ، فيحرثون حراثته ويحصدون حصاده ، ويعملون عدة حربه وأدوات مراكبه '),
(3394, '1 Samuel', 9, 8, 13, ' ويأخذ بناتكم عطارات وطباخات وخبازات '),
(3395, '1 Samuel', 9, 8, 14, ' ويأخذ حقولكم وكرومكم وزيتونكم ، أجودها ويعطيها لعبيده '),
(3396, '1 Samuel', 9, 8, 15, ' ويعشر زروعكم وكرومكم ، ويعطي لخصيانه وعبيده '),
(3397, '1 Samuel', 9, 8, 16, ' ويأخذ عبيدكم وجواريكم وشبانكم الحسان وحميركم ويستعملهم لشغله '),
(3398, '1 Samuel', 9, 8, 17, ' ويعشر غنمكم وأنتم تكونون له عبيدا '),
(3399, '1 Samuel', 9, 8, 18, ' فتصرخون في ذلك اليوم من وجه ملككم الذي اخترتموه لأنفسكم ، فلا يستجيب لكم الرب في ذلك اليوم '),
(3400, '1 Samuel', 9, 8, 19, ' فأبى الشعب أن يسمعوا لصوت صموئيل ، وقالوا : لا بل يكون علينا ملك '),
(3401, '1 Samuel', 9, 8, 20, ' فنكون نحن أيضا مثل سائر الشعوب ، ويقضي لنا ملكنا ويخرج أمامنا ويحارب حروبنا '),
(3402, '1 Samuel', 9, 8, 21, ' فسمع صموئيل كل كلام الشعب وتكلم به في أذني الرب '),
(3403, '1 Samuel', 9, 8, 22, ' فقال الرب لصموئيل : اسمع لصوتهم وملك عليهم ملكا . فقال صموئيل لرجال إسرائيل : اذهبوا كل واحد إلى مدينته '),
(3404, '1 Samuel', 9, 9, 1, ' وكان رجل من بنيامين اسمه قيس بن أبيئيل بن صرور بن بكورة بن أفيح ، ابن رجل بنياميني جبار بأس '),
(3405, '1 Samuel', 9, 9, 2, ' وكان له ابن اسمه شاول ، شاب وحسن ، ولم يكن رجل في بني إسرائيل أحسن منه . من كتفه فما فوق كان أطول من كل الشعب '),
(3406, '1 Samuel', 9, 9, 3, ' فضلت أتن قيس أبي شاول . فقال قيس لشاول ابنه : خذ معك واحدا من الغلمان وقم اذهب فتش على الأتن '),
(3407, '1 Samuel', 9, 9, 4, ' فعبر في جبل أفرايم ، ثم عبر في أرض شليشة فلم يجدها . ثم عبرا في أرض شعليم فلم توجد . ثم عبرا في أرض بنيامين فلم يجداها '),
(3408, '1 Samuel', 9, 9, 5, ' ولما دخلا أرض صوف قال شاول لغلامه الذي معه : تعال نرجع لئلا يترك أبي الأتن ويهتم بنا '),
(3409, '1 Samuel', 9, 9, 6, ' فقال له : هوذا رجل الله في هذه المدينة ، والرجل مكرم ، كل ما يقوله يصير . لنذهب الآن إلى هناك لعله يخبرنا عن طريقنا التي نسلك فيها '),
(3410, '1 Samuel', 9, 9, 7, ' فقال شاول للغلام : هوذا نذهب ، فماذا نقدم للرجل ؟ لأن الخبز قد نفد من أوعيتنا وليس من هدية نقدمها لرجل الله . ماذا معنا '),
(3411, '1 Samuel', 9, 9, 8, ' فعاد الغلام وأجاب شاول وقال : هوذا يوجد بيدي ربع شاقل فضة فأعطيه لرجل الله فيخبرنا عن طريقنا '),
(3412, '1 Samuel', 9, 9, 9, ' سابقا في إسرائيل هكذا كان يقول الرجل عند ذهابه ليسأل الله : هلم نذهب إلى الرائي . لأن النبي اليوم كان يدعى سابقا الرائي '),
(3413, '1 Samuel', 9, 9, 10, ' فقال شاول لغلامه : كلامك حسن . هلم نذهب . فذهبا إلى المدينة التي فيها رجل الله '),
(3414, '1 Samuel', 9, 9, 11, ' وفيما هما صاعدان في مطلع المدينة صادفا فتيات خارجات لاستقاء الماء . فقالا لهن : أهنا الرائي '),
(3415, '1 Samuel', 9, 9, 12, ' فأجبنهما وقلن : نعم . هوذا هو أمامكما . أسرعا الآن ، لأنه جاء اليوم إلى المدينة لأنه اليوم ذبيحة للشعب على المرتفعة '),
(3416, '1 Samuel', 9, 9, 13, ' عند دخولكما المدينة للوقت تجدانه قبل صعوده إلى المرتفعة ليأكل ، لأن الشعب لا يأكل حتى يأتي لأنه يبارك الذبيحة . بعد ذلك يأكل المدعوون . فالآن اصعدا لأنكما في مثل اليوم تجدانه '),
(3417, '1 Samuel', 9, 9, 14, ' فصعدا إلى المدينة . وفيما هما آتيان في وسط المدينة إذا بصموئيل خارج للقائهما ليصعد إلى المرتفعة '),
(3418, '1 Samuel', 9, 9, 15, ' والرب كشف أذن صموئيل قبل مجيء شاول بيوم قائلا '),
(3419, '1 Samuel', 9, 9, 16, ' غدا في مثل الآن أرسل إليك رجلا من أرض بنيامين ، فامسحه رئيسا لشعبي إسرائيل ، فيخلص شعبي من يد الفلسطينيين ، لأني نظرت إلى شعبي لأن صراخهم قد جاء إلي '),
(3420, '1 Samuel', 9, 9, 17, ' فلما رأى صموئيل شاول أجابه الرب : هوذا الرجل الذي كلمتك عنه . هذا يضبط شعبي '),
(3421, '1 Samuel', 9, 9, 18, ' فتقدم شاول إلى صموئيل في وسط الباب وقال : أطلب إليك : أخبرني أين بيت الرائي '),
(3422, '1 Samuel', 9, 9, 19, ' فأجاب صموئيل شاول وقال : أنا الرائي . اصعدا أمامي إلى المرتفعة فتأكلا معي اليوم ، ثم أطلقك صباحا وأخبرك بكل ما في قلبك '),
(3423, '1 Samuel', 9, 9, 20, ' وأما الأتن الضالة لك منذ ثلاثة أيام فلا تضع قلبك عليها لأنها قد وجدت . ولمن كل شهي إسرائيل ؟ أليس لك ولكل بيت أبيك '),
(3424, '1 Samuel', 9, 9, 21, ' فأجاب شاول وقال : أما أنا بنياميني من أصغر أسباط إسرائيل ، وعشيرتي أصغر كل عشائر أسباط بنيامين ؟ فلماذا تكلمني بمثل هذا الكلام '),
(3425, '1 Samuel', 9, 9, 22, ' فأخذ صموئيل شاول وغلامه وأدخلهما إلى المنسك وأعطاهما مكانا في رأس المدعوين ، وهم نحو ثلاثين رجلا '),
(3426, '1 Samuel', 9, 9, 23, ' وقال صموئيل للطباخ : هات النصيب الذي أعطيتك إياه ، الذي قلت لك عنه : ضعه عندك '),
(3427, '1 Samuel', 9, 9, 24, ' فرفع الطباخ الساق مع ما عليها وجعلها أمام شاول . فقال : هوذا ما أبقي . ضعه أمامك وكل . لأنه إلى هذا الميعاد محفوظ لك من حين قلت : دعوت الشعب . فأكل شاول مع صموئيل في ذلك اليوم '),
(3428, '1 Samuel', 9, 9, 25, ' ولما نزلوا من المرتفعة إلى المدينة تكلم مع شاول على السطح '),
(3429, '1 Samuel', 9, 9, 26, ' وبكروا . وكان عند طلوع الفجر أن صموئيل دعا شاول عن السطح قائلا : قم فأصرفك . فقام شاول وخرجا كلاهما ، هو وصموئيل إلى خارج '),
(3430, '1 Samuel', 9, 9, 27, ' وفيما هما نازلان بطرف المدينة قال صموئيل لشاول : قل للغلام أن يعبر قدامنا . فعبر . وأما أنت فقف الآن فأسمعك كلام الله '),
(3431, '1 Samuel', 9, 10, 1, ' فأخذ صموئيل قنينة الدهن وصب على رأسه وقبله وقال : أليس لأن الرب قد مسحك على ميراثه رئيسا '),
(3432, '1 Samuel', 9, 10, 2, ' في ذهابك اليوم من عندي تصادف رجلين عند قبر راحيل ، في تخم بنيامين في صلصح ، فيقولان لك : قد وجدت الأتن ، التي ذهبت تفتش عليها ، وهوذا أبوك قد ترك أمر الأتن واهتم بكما قائلا : ماذا أصنع لابني '),
(3433, '1 Samuel', 9, 10, 3, ' وتعدو من هناك ذاهبا حتى تأتي إلى بلوطة تابور ، فيصادفك هناك ثلاثة رجال صاعدون إلى الله إلى بيت إيل ، واحد حامل ثلاثة جداء ، وواحد حامل ثلاثة أرغفة خبز ، وواحد حامل زق خمر '),
(3434, '1 Samuel', 9, 10, 4, ' فيسلمون عليك ويعطونك رغيفي خبز ، فتأخذ من يدهم '),
(3435, '1 Samuel', 9, 10, 5, ' بعد ذلك تأتي إلى جبعة الله حيث أنصاب الفلسطينيين . ويكون عند مجيئك إلى هناك إلى المدينة أنك تصادف زمرة من الأنبياء نازلين من المرتفعة وأمامهم رباب ودف وناي وعود وهم يتنبأون '),
(3436, '1 Samuel', 9, 10, 6, ' فيحل عليك روح الرب فتتنبأ معهم وتتحول إلى رجل آخر '),
(3437, '1 Samuel', 9, 10, 7, ' وإذا أتت هذه الآيات عليك ، فافعل ما وجدته يدك ، لأن الله معك '),
(3438, '1 Samuel', 9, 10, 8, ' وتنزل قدامي إلى الجلجال ، وهوذا أنا أنزل إليك لأصعد محرقات وأذبح ذبائح سلامة . سبعة أيام تلبث حتى آتي إليك وأعلمك ماذا تفعل '),
(3439, '1 Samuel', 9, 10, 9, ' وكان عندما أدار كتفه لكي يذهب من عند صموئيل أن الله أعطاه قلبا آخر ، وأتت جميع هذه الآيات في ذلك اليوم '),
(3440, '1 Samuel', 9, 10, 10, ' ولما جاءوا إلى هناك إلى جبعة ، إذا بزمرة من الأنبياء لقيته ، فحل عليه روح الله فتنبأ في وسطهم '),
(3441, '1 Samuel', 9, 10, 11, ' ولما رآه جميع الذين عرفوه منذ أمس وما قبله أنه يتنبأ مع الأنبياء ، قال الشعب ، الواحد لصاحبه : ماذا صار لابن قيس ؟ أشاول أيضا بين الأنبياء '),
(3442, '1 Samuel', 9, 10, 12, ' فأجاب رجل من هناك وقال : ومن هو أبوهم ؟  . ولذلك ذهب مثلا : أشاول أيضا بين الأنبياء '),
(3443, '1 Samuel', 9, 10, 13, ' ولما انتهى من التنبي جاء إلى المرتفعة '),
(3444, '1 Samuel', 9, 10, 14, ' فقال عم شاول له ولغلامه : إلى أين ذهبتما ؟  . فقال : لكي نفتش على الأتن . ولما رأينا أنها لم توجد جئنا إلى صموئيل '),
(3445, '1 Samuel', 9, 10, 15, ' فقال عم شاول : أخبرني ماذا قال لكما صموئيل '),
(3446, '1 Samuel', 9, 10, 16, ' فقال شاول لعمه : أخبرنا بأن الأتن قد وجدت . ولكنه لم يخبره بأمر المملكة الذي تكلم به صموئيل '),
(3447, '1 Samuel', 9, 10, 17, ' واستدعى صموئيل الشعب إلى الرب إلى المصفاة '),
(3448, '1 Samuel', 9, 10, 18, ' وقال لبني إسرائيل : هكذا يقول الرب إله إسرائيل : إني أصعدت إسرائيل من مصر وأنقذتكم من يد المصريين ومن يد جميع الممالك التي ضايقتكم '),
(3449, '1 Samuel', 9, 10, 19, ' وأنتم قد رفضتم اليوم إلهكم الذي هو مخلصكم من جميع الذين يسيئون إليكم ويضايقونكم ، وقلتم له : بل تجعل علينا ملكا . فالآن امثلوا أمام الرب حسب أسباطكم وألوفكم '),
(3450, '1 Samuel', 9, 10, 20, ' فقدم صموئيل جميع أسباط إسرائيل ، فأخذ سبط بنيامين '),
(3451, '1 Samuel', 9, 10, 21, ' ثم قدم سبط بنيامين حسب عشائره ، فأخذت عشيرة مطري ، وأخذ شاول بن قيس . ففتشوا عليه فلم يوجد '),
(3452, '1 Samuel', 9, 10, 22, ' فسألوا أيضا من الرب : هل يأتي الرجل أيضا إلى هنا ؟  . فقال الرب : هوذا قد اختبأ بين الأمتعة '),
(3453, '1 Samuel', 9, 10, 23, ' فركضوا وأخذوه من هناك ، فوقف بين الشعب ، فكان أطول من كل الشعب من كتفه فما فوق '),
(3454, '1 Samuel', 9, 10, 24, ' فقال صموئيل لجميع الشعب : أرأيتم الذي اختاره الرب ، أنه ليس مثله في جميع الشعب ؟  . فهتف كل الشعب وقالوا : ليحي الملك '),
(3455, '1 Samuel', 9, 10, 25, ' فكلم صموئيل الشعب بقضاء المملكة ، وكتبه في السفر ووضعه أمام الرب . ثم أطلق صموئيل جميع الشعب كل واحد إلى بيته '),
(3456, '1 Samuel', 9, 10, 26, ' وشاول أيضا ذهب إلى بيته إلى جبعة ، وذهب معه الجماعة التي مس الله قلبها '),
(3457, '1 Samuel', 9, 10, 27, ' وأما بنو بليعال فقالوا : كيف يخلصنا هذا ؟  . فاحتقروه ولم يقدموا له هدية . فكان كأصم '),
(3458, '1 Samuel', 9, 11, 1, ' وصعد ناحاش العموني ونزل على يابيش جلعاد . فقال جميع أهل يابيش لناحاش : اقطع لنا عهدا فنستعبد لك '),
(3459, '1 Samuel', 9, 3, 21, ' وعاد الرب يتراءى في شيلوه ، لأن الرب استعلن لصموئيل في شيلوه بكلمة الرب '),
(3460, '1 Samuel', 9, 4, 1, ' وكان كلام صموئيل إلى جميع إسرائيل . وخرج إسرائيل للقاء الفلسطينيين للحرب ، ونزلوا عند حجر المعونة ، وأما الفلسطينيون فنزلوا في أفيق '),
(3461, '1 Samuel', 9, 4, 2, ' واصطف الفلسطينيون للقاء إسرائيل ، واشتبكت الحرب فانكسر إسرائيل أمام الفلسطينيين ، وضربوا من الصف في الحقل نحو أربعة آلاف رجل '),
(3462, '1 Samuel', 9, 4, 3, ' فجاء الشعب إلى المحلة . وقال شيوخ إسرائيل : لماذا كسرنا اليوم الرب أمام الفلسطينيين ؟ لنأخذ لأنفسنا من شيلوه تابوت عهد الرب فيدخل في وسطنا ويخلصنا من يد أعدائنا '),
(3463, '1 Samuel', 9, 4, 4, ' فأرسل الشعب إلى شيلوه وحملوا من هناك تابوت عهد رب الجنود الجالس على الكروبيم . وكان هناك ابنا عالي حفني وفينحاس مع تابوت عهد الله '),
(3464, '1 Samuel', 9, 4, 5, ' وكان عند دخول تابوت عهد الرب إلى المحلة أن جميع إسرائيل هتفوا هتافا عظيما حتى ارتجت الأرض '),
(3465, '1 Samuel', 9, 4, 6, ' فسمع الفلسطينيون صوت الهتاف فقالوا : ما هو صوت هذا الهتاف العظيم في محلة العبرانيين ؟  . وعلموا أن تابوت الرب جاء إلى المحلة '),
(3466, '1 Samuel', 9, 4, 7, ' فخاف الفلسطينيون لأنهم قالوا : قد جاء الله إلى المحلة . وقالوا : ويل لنا لأنه لم يكن مثل هذا منذ أمس ولا ما قبله '),
(3467, '1 Samuel', 9, 4, 8, ' ويل لنا من ينقذنا من يد هؤلاء الآلهة القادرين ؟ هؤلاء هم الآلهة الذين ضربوا مصر بجميع الضربات في البرية '),
(3468, '1 Samuel', 9, 4, 9, ' تشددوا وكونوا رجالا أيها الفلسطينيون لئلا تستعبدوا للعبرانيين كما استعبدوا هم لكم . فكونوا رجالا وحاربوا '),
(3469, '1 Samuel', 9, 4, 10, ' فحارب الفلسطينيون ، وانكسر إسرائيل وهربوا كل واحد إلى خيمته . وكانت الضربة عظيمة جدا ، وسقط من إسرائيل ثلاثون ألف راجل '),
(3470, '1 Samuel', 9, 4, 11, ' وأخذ تابوت الله ، ومات ابنا عالي حفني وفينحاس '),
(3471, '1 Samuel', 9, 4, 12, ' فركض رجل من بنيامين من الصف ، وجاء إلى شيلوه في ذلك اليوم ، وثيابه ممزقة وتراب على رأسه '),
(3472, '1 Samuel', 9, 4, 13, ' ولما جاء ، فإذا عالي جالس على كرسي بجانب الطريق يراقب ، لأن قلبه كان مضطربا لأجل تابوت الله . ولما جاء الرجل ليخبر في المدينة ، صرخت المدينة كلها '),
(3473, '1 Samuel', 9, 4, 14, ' فسمع عالي صوت الصراخ فقال : ما هو صوت الضجيج هذا ؟  . فأسرع الرجل وأخبر عالي '),
(3474, '1 Samuel', 9, 4, 15, ' وكان عالي ابن ثمان وتسعين سنة ، وقامت عيناه ولم يقدر أن يبصر '),
(3475, '1 Samuel', 9, 4, 16, ' فقال الرجل لعالي : أنا جئت من الصف ، وأنا هربت اليوم من الصف . فقال : كيف كان الأمر يا ابني '),
(3476, '1 Samuel', 9, 4, 17, ' فأجاب المخبر وقال : هرب إسرائيل أمام الفلسطينيين وكانت أيضا كسرة عظيمة في الشعب ، ومات أيضا ابناك حفني وفينحاس ، وأخذ تابوت الله '),
(3477, '1 Samuel', 9, 4, 18, ' وكان لما ذكر تابوت الله ، أنه سقط عن الكرسي إلى الوراء إلى جانب الباب ، فانكسرت رقبته ومات ، لأنه كان رجلا شيخا وثقيلا . وقد قضى لإسرائيل أربعين سنة '),
(3478, '1 Samuel', 9, 4, 19, ' وكنته امرأة فينحاس كانت حبلى تكاد تلد . فلما سمعت خبر أخذ تابوت الله وموت حميها ورجلها ، ركعت وولدت ، لأن مخاضها انقلب عليها '),
(3479, '1 Samuel', 9, 4, 20, ' وعند احتضارها قالت لها الواقفات عندها : لا تخافي لأنك قد ولدت ابنا . فلم تجب ولم يبال قلبها '),
(3480, '1 Samuel', 9, 4, 21, ' فدعت الصبي إيخابود ، قائلة : قد زال المجد من إسرائيل . لأن تابوت الله قد أخذ ولأجل حميها ورجلها '),
(3481, '1 Samuel', 9, 4, 22, ' فقالت : زال المجد من إسرائيل لأن تابوت الله قد أخذ '),
(3482, '1 Samuel', 9, 5, 1, ' فأخذ الفلسطينيون تابوت الله وأتوا به من حجر المعونة إلى أشدود '),
(3483, '1 Samuel', 9, 5, 2, ' وأخذ الفلسطينيون تابوت الله وأدخلوه إلى بيت داجون ، وأقاموه بقرب داجون '),
(3484, '1 Samuel', 9, 5, 3, ' وبكر الأشدوديون في الغد وإذا بداجون ساقط على وجهه إلى الأرض أمام تابوت الرب ، فأخذوا داجون وأقاموه في مكانه '),
(3485, '1 Samuel', 9, 5, 4, ' وبكروا صباحا في الغد وإذا بداجون ساقط على وجهه على الأرض أمام تابوت الرب ، ورأس داجون ويداه مقطوعة على العتبة . بقي بدن السمكة فقط '),
(3486, '1 Samuel', 9, 5, 5, ' لذلك لا يدوس كهنة داجون وجميع الداخلين إلى بيت داجون على عتبة داجون في أشدود إلى هذا اليوم ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(3487, '1 Samuel', 9, 5, 6, ' فثقلت يد الرب على الأشدوديين ، وأخربهم وضربهم بالبواسير في أشدود وتخومها '),
(3488, '1 Samuel', 9, 5, 7, ' ولما رأى أهل أشدود الأمر كذلك قالوا : لا يمكث تابوت إله إسرائيل عندنا لأن يده قد قست علينا وعلى داجون إلهنا '),
(3489, '1 Samuel', 9, 5, 8, ' فأرسلوا وجمعوا جميع أقطاب الفلسطينيين إليهم وقالوا : ماذا نصنع بتابوت إله إسرائيل ؟  . فقالوا : لينقل تابوت إله إسرائيل إلى جت . فنقلوا تابوت إله إسرائيل '),
(3490, '1 Samuel', 9, 5, 9, ' وكان بعدما نقلوه أن يد الرب كانت على المدينة باضطراب عظيم جدا ، وضرب أهل المدينة من الصغير إلى الكبير ، ونفرت لهم البواسير '),
(3491, '1 Samuel', 9, 5, 10, ' فأرسلوا تابوت الله إلى عقرون . وكان لما دخل تابوت الله إلى عقرون أنه صرخ العقرونيون قائلين : قد نقلوا إلينا تابوت إله إسرائيل لكي يميتونا نحن وشعبنا '),
(3492, '1 Samuel', 9, 5, 11, ' وأرسلوا وجمعوا كل أقطاب الفلسطينيين وقالوا : أرسلوا تابوت إله إسرائيل فيرجع إلى مكانه ولا يميتنا نحن وشعبنا . لأن اضطراب الموت كان في كل المدينة . يد الله كانت ثقيلة جدا هناك '),
(3493, '1 Samuel', 9, 5, 12, ' والناس الذين لم يموتوا ضربوا بالبواسير ، فصعد صراخ المدينة إلى السماء '),
(3494, '1 Samuel', 9, 6, 1, ' وكان تابوت الله في بلاد الفلسطينيين سبعة أشهر '),
(3495, '1 Samuel', 9, 6, 2, ' فدعا الفلسطينيون الكهنة والعرافين قائلين : ماذا نعمل بتابوت الرب ؟ أخبرونا بماذا نرسله إلى مكانه '),
(3496, '1 Samuel', 9, 6, 3, ' فقالوا : إذا أرسلتم تابوت إله إسرائيل ، فلا ترسلوه فارغا ، بل ردوا له قربان إثم . حينئذ تشفون ويعلم عندكم لماذا لا ترتفع يده عنكم '),
(3497, '1 Samuel', 9, 6, 4, ' فقالوا : وما هو قربان الإثم الذي نرده له ؟  . فقالوا : حسب عدد أقطاب الفلسطينيين : خمسة بواسير من ذهب ، وخمسة فيران من ذهب . لأن الضربة واحدة عليكم جميعا وعلى أقطابكم '),
(3498, '1 Samuel', 9, 6, 5, ' واصنعوا تماثيل بواسيركم وتماثيل فيرانكم التي تفسد الأرض ، وأعطوا إله إسرائيل مجدا لعله يخفف يده عنكم وعن آلهتكم وعن أرضكم '),
(3499, '1 Samuel', 9, 6, 6, ' ولماذا تغلظون قلوبكم كما أغلظ المصريون وفرعون قلوبهم ؟ أليس على ما فعل بهم أطلقوهم فذهبوا '),
(3500, '1 Samuel', 9, 6, 7, ' فالآن خذوا واعملوا عجلة واحدة جديدة وبقرتين مرضعتين لم يعلهما نير ، واربطوا البقرتين إلى العجلة ، وأرجعوا ولديهما عنهما إلى البيت '),
(3501, '1 Samuel', 9, 6, 8, ' وخذوا تابوت الرب واجعلوه على العجلة ، وضعوا أمتعة الذهب التي تردونها له قربان إثم في صندوق بجانبه وأطلقوه فيذهب '),
(3502, '1 Samuel', 9, 6, 9, ' وانظروا ، فإن صعد في طريق تخمه إلى بيتشمس فإنه هو الذي فعل بنا هذا الشر العظيم . وإلا فنعلم أن يده لم تضربنا . كان ذلك علينا عرضا '),
(3503, '1 Samuel', 9, 6, 10, ' ففعل الرجال كذلك ، وأخذوا بقرتين مرضعتين وربطوهما إلى العجلة ، وحبسوا ولديهما في البيت '),
(3504, '1 Samuel', 9, 6, 11, ' ووضعوا تابوت الرب على العجلة مع الصندوق وفيران الذهب وتماثيل بواسيرهم '),
(3505, '1 Samuel', 9, 6, 12, ' فاستقامت البقرتان في الطريق إلى طريق بيتشمس ، وكانتا تسيران في سكة واحدة وتجأران ، ولم تميلا يمينا ولا شمالا ، وأقطاب الفلسطينيين يسيرون وراءهما إلى تخم بيتشمس '),
(3506, '1 Samuel', 9, 6, 13, ' وكان أهل بيتشمس يحصدون حصاد الحنطة في الوادي ، فرفعوا أعينهم ورأوا التابوت ، وفرحوا برؤيته '),
(3507, '1 Samuel', 9, 6, 14, ' فأتت العجلة إلى حقل يهوشع البيتشمسي ووقفت هناك . وهناك حجر كبير . فشققوا خشب العجلة وأصعدوا البقرتين محرقة للرب '),
(3508, '1 Samuel', 9, 6, 15, ' فأنزل اللاويون تابوت الرب والصندوق الذي معه الذي فيه أمتعة الذهب ووضعوهما على الحجر الكبير . وأصعد أهل بيتشمس محرقات وذبحوا ذبائح في ذلك اليوم للرب '),
(3509, '1 Samuel', 9, 6, 16, ' فرأى أقطاب الفلسطينيين الخمسة ورجعوا إلى عقرون في ذلك اليوم '),
(3510, '1 Samuel', 9, 6, 17, ' وهذه هي بواسير الذهب التي ردها الفلسطينيون قربان إثم للرب : واحد لأشدود ، وواحد لغزة ، وواحد لأشقلون ، وواحد لجت ، وواحد لعقرون '),
(3511, '1 Samuel', 9, 6, 18, ' وفيران الذهب بعدد جميع مدن الفلسطينيين ، للخمسة الأقطاب ، من المدينة المحصنة إلى قرية الصحراء . وشاهد هو الحجر الكبير الذي وضعوا عليه تابوت الرب . هو إلى هذا اليوم في حقل يهوشع البيتشمسي '),
(3512, '1 Samuel', 9, 6, 19, ' وضرب أهل بيتشمس لأنهم نظروا إلى تابوت الرب . وضرب من الشعب خمسين ألف رجل وسبعين رجلا . فناح الشعب لأن الرب ضرب الشعب ضربة عظيمة '),
(3513, '1 Samuel', 9, 6, 20, ' وقال أهل بيتشمس : من يقدر أن يقف أمام الرب الإله القدوس هذا ؟ وإلى من يصعد عنا '),
(3514, '1 Samuel', 9, 6, 21, ' وأرسلوا رسلا إلى سكان قرية يعاريم قائلين : قد رد الفلسطينيون تابوت الرب ، فانزلوا وأصعدوه إليكم '),
(3515, '1 Samuel', 9, 7, 1, ' فجاء أهل قرية يعاريم وأصعدوا تابوت الرب وأدخلوه إلى بيت أبيناداب في الأكمة ، وقدسوا ألعازار ابنه لأجل حراسة تابوت الرب '),
(3516, '1 Samuel', 9, 7, 2, ' وكان من يوم جلوس التابوت في قرية يعاريم أن المدة طالت وكانت عشرين سنة . وناح كل بيت إسرائيل وراء الرب '),
(3517, '1 Samuel', 9, 7, 3, ' وكلم صموئيل كل بيت إسرائيل قائلا : إن كنتم بكل قلوبكم راجعين إلى الرب ، فانزعوا الآلهة الغريبة والعشتاروث من وسطكم ، وأعدوا قلوبكم للرب واعبدوه وحده ، فينقذكم من يد الفلسطينيين '),
(3518, '1 Samuel', 9, 7, 4, ' فنزع بنو إسرائيل البعليم والعشتاروث وعبدوا الرب وحده '),
(3519, '1 Samuel', 9, 7, 5, ' فقال صموئيل : اجمعوا كل إسرائيل إلى المصفاة فأصلي لأجلكم إلى الرب '),
(3520, '1 Samuel', 9, 7, 6, ' فاجتمعوا إلى المصفاة واستقوا ماء وسكبوه أمام الرب ، وصاموا في ذلك اليوم وقالوا هناك : قد أخطأنا إلى الرب . وقضى صموئيل لبني إسرائيل في المصفاة '),
(3521, '1 Samuel', 9, 7, 7, ' وسمع الفلسطينيون أن بني إسرائيل قد اجتمعوا في المصفاة ، فصعد أقطاب الفلسطينيين إلى إسرائيل . فلما سمع بنو إسرائيل خافوا من الفلسطينيين '),
(3522, '1 Samuel', 9, 7, 8, ' وقال بنو إسرائيل لصموئيل : لا تكف عن الصراخ من أجلنا إلى الرب إلهنا فيخلصنا من يد الفلسطينيين '),
(3523, '1 Samuel', 9, 7, 9, ' فأخذ صموئيل حملا رضيعا وأصعده محرقة بتمامه للرب ، وصرخ صموئيل إلى الرب من أجل إسرائيل ، فاستجاب له الرب '),
(3524, '1 Samuel', 9, 7, 10, ' وبينما كان صموئيل يصعد المحرقة ، تقدم الفلسطينيون لمحاربة إسرائيل ، فأرعد الرب بصوت عظيم في ذلك اليوم على الفلسطينيين وأزعجهم ، فانكسروا أمام إسرائيل '),
(3525, '1 Samuel', 9, 7, 11, ' وخرج رجال إسرائيل من المصفاة وتبعوا الفلسطينيين وضربوهم إلى ما تحت بيت كار '),
(3526, '1 Samuel', 9, 7, 12, ' فأخذ صموئيل حجرا ونصبه بين المصفاة والسن ، ودعا اسمه حجر المعونة ، وقال : إلى هنا أعاننا الرب '),
(3527, '1 Samuel', 9, 7, 13, ' فذل الفلسطينيون ولم يعودوا بعد للدخول في تخم إسرائيل . وكانت يد الرب على الفلسطينيين كل أيام صموئيل '),
(3528, '1 Samuel', 9, 7, 14, ' والمدن التي أخذها الفلسطينيون من إسرائيل رجعت إلى إسرائيل من عقرون إلى جت . واستخلص إسرائيل تخومها من يد الفلسطينيين . وكان صلح بين إسرائيل والأموريين '),
(3529, '1 Samuel', 9, 7, 15, ' وقضى صموئيل لإسرائيل كل أيام حياته '),
(3530, '1 Samuel', 9, 7, 16, ' وكان يذهب من سنة إلى سنة ويدور في بيت إيل والجلجال والمصفاة ، ويقضي لإسرائيل في جميع هذه المواضع '),
(3531, '1 Samuel', 9, 7, 17, ' وكان رجوعه إلى الرامة لأن بيته هناك . وهناك قضى لإسرائيل ، وبنى هناك مذبحا للرب '),
(3532, '1 Samuel', 9, 8, 1, ' وكان لما شاخ صموئيل أنه جعل بنيه قضاة لإسرائيل '),
(3533, '1 Samuel', 9, 8, 2, ' وكان اسم ابنه البكر يوئيل ، واسم ثانيه أبيا . كانا قاضيين في بئر سبع '),
(3534, '1 Samuel', 9, 11, 2, ' فقال لهم ناحاش العموني : بهذا أقطع لكم . بتقوير كل عين يمنى لكم وجعل ذلك عارا على جميع إسرائيل '),
(3535, '1 Samuel', 9, 11, 3, ' فقال له شيوخ يابيش : اتركنا سبعة أيام فنرسل رسلا إلى جميع تخوم إسرائيل . فإن لم يوجد من يخلصنا نخرج إليك '),
(3536, '1 Samuel', 9, 11, 4, ' فجاء الرسل إلى جبعة شاول وتكلموا بهذا الكلام في آذان الشعب ، فرفع كل الشعب أصواتهم وبكوا '),
(3537, '1 Samuel', 9, 11, 5, ' وإذا بشاول آت وراء البقر من الحقل ، فقال شاول : ما بال الشعب يبكون ؟  . فقصوا عليه كلام أهل يابيش '),
(3538, '1 Samuel', 9, 11, 6, ' فحل روح الله على شاول عندما سمع هذا الكلام وحمي غضبه جدا '),
(3539, '1 Samuel', 9, 11, 7, ' فأخذ فدان بقر وقطعه ، وأرسل إلى كل تخوم إسرائيل بيد الرسل قائلا : من لا يخرج وراء شاول ووراء صموئيل ، فهكذا يفعل ببقره . فوقع رعب الرب على الشعب ، فخرجوا كرجل واحد '),
(3540, '1 Samuel', 9, 11, 8, ' وعدهم في بازق ، فكان بنو إسرائيل ثلاث مئة ألف ، ورجال يهوذا ثلاثين ألفا '),
(3541, '1 Samuel', 9, 11, 9, ' وقالوا للرسل الذين جاءوا : هكذا تقولون لأهل يابيش جلعاد : غدا عندما تحمى الشمس يكون لكم خلاص . فأتى الرسل وأخبروا أهل يابيش ففرحوا '),
(3542, '1 Samuel', 9, 11, 10, ' وقال أهل يابيش : غدا نخرج إليكم فتفعلون بنا حسب كل ما يحسن في أعينكم '),
(3543, '1 Samuel', 9, 11, 11, ' وكان في الغد أن شاول جعل الشعب ثلاث فرق ، ودخلوا في وسط المحلة عند سحر الصبح وضربوا العمونيين حتى حمي النهار . والذين بقوا تشتتوا حتى لم يبق منهم اثنان معا '),
(3544, '1 Samuel', 9, 11, 12, ' وقال الشعب لصموئيل : من هم الذين يقولون : هل شاول يملك علينا ؟ ايتوا بالرجال فنقتلهم '),
(3545, '1 Samuel', 9, 11, 13, ' فقال شاول : لا يقتل أحد في هذا اليوم ، لأنه في هذا اليوم صنع الرب خلاصا في إسرائيل '),
(3546, '1 Samuel', 9, 11, 14, ' وقال صموئيل للشعب : هلموا نذهب إلى الجلجال ونجدد هناك المملكة '),
(3547, '1 Samuel', 9, 11, 15, ' فذهب كل الشعب إلى الجلجال وملكوا هناك شاول أمام الرب في الجلجال ، وذبحوا هناك ذبائح سلامة أمام الرب . وفرح هناك شاول وجميع رجال إسرائيل جدا '),
(3548, '1 Samuel', 9, 12, 1, ' وقال صموئيل لكل إسرائيل : هأنذا قد سمعت لصوتكم في كل ما قلتم لي وملكت عليكم ملكا '),
(3549, '1 Samuel', 9, 12, 2, ' والآن هوذا الملك يمشي أمامكم . وأما أنا فقد شخت وشبت ، وهوذا أبنائي معكم . وأنا قد سرت أمامكم منذ صباي إلى هذا اليوم '),
(3550, '1 Samuel', 9, 12, 3, ' هأنذا فاشهدوا علي قدام الرب وقدام مسيحه : ثور من أخذت ؟ وحمار من أخذت ؟ ومن ظلمت ؟ ومن سحقت ؟ ومن يد من أخذت فدية لأغضي عيني عنه ، فأرد لكم '),
(3551, '1 Samuel', 9, 12, 4, ' فقالوا : لم تظلمنا ولا سحقتنا ولا أخذت من يد أحد شيئا '),
(3552, '1 Samuel', 9, 12, 5, ' فقال لهم : شاهد الرب عليكم وشاهد مسيحه اليوم هذا ، أنكم لم تجدوا بيدي شيئا . فقالوا : شاهد '),
(3553, '1 Samuel', 9, 12, 6, ' وقال صموئيل للشعب : الرب الذي أقام موسى وهارون ، وأصعد آباءكم من أرض مصر '),
(3554, '1 Samuel', 9, 12, 7, ' فالآن امثلوا فأحاكمكم أمام الرب بجميع حقوق الرب التي صنعها معكم ومع آبائكم '),
(3555, '1 Samuel', 9, 12, 8, ' لما جاء يعقوب إلى مصر وصرخ آباؤكم إلى الرب ، أرسل الرب موسى وهارون فأخرجا آباءكم من مصر وأسكناهم في هذا المكان '),
(3556, '1 Samuel', 9, 12, 9, ' فلما نسوا الرب إلههم ، باعهم ليد سيسرا رئيس جيش حاصور ، وليد الفلسطينيين ، وليد ملك موآب فحاربوهم '),
(3557, '1 Samuel', 9, 12, 10, ' فصرخوا إلى الرب وقالوا : أخطأنا لأننا تركنا الرب وعبدنا البعليم والعشتاروث . فالآن أنقذنا من يد أعدائنا فنعبدك '),
(3558, '1 Samuel', 9, 12, 11, ' فأرسل الرب يربعل وبدان ويفتاح وصموئيل ، وأنقذكم من يد أعدائكم الذين حولكم فسكنتم آمنين '),
(3559, '1 Samuel', 9, 12, 12, ' ولما رأيتم ناحاش ملك بني عمون آتيا عليكم ، قلتم لي : لا بل يملك علينا ملك . والرب إلهكم ملككم '),
(3560, '1 Samuel', 9, 12, 13, ' فالآن هوذا الملك الذي اخترتموه ، الذي طلبتموه ، وهوذا قد جعل الرب عليكم ملكا '),
(3561, '1 Samuel', 9, 12, 14, ' إن اتقيتم الرب وعبدتموه وسمعتم صوته ولم تعصوا قول الرب ، وكنتم أنتم والملك أيضا الذي يملك عليكم وراء الرب إلهكم '),
(3562, '1 Samuel', 9, 12, 15, ' وإن لم تسمعوا صوت الرب بل عصيتم قول الرب ، تكن يد الرب عليكم كما على آبائكم '),
(3563, '1 Samuel', 9, 12, 16, ' فالآن امثلوا أيضا وانظروا هذا الأمر العظيم الذي يفعله الرب أمام أعينكم '),
(3564, '1 Samuel', 9, 12, 17, ' أما هو حصاد الحنطة اليوم ؟ فإني أدعو الرب فيعطي رعودا ومطرا فتعلمون وترون أنه عظيم شركم الذي عملتموه في عيني الرب بطلبكم لأنفسكم ملكا '),
(3565, '1 Samuel', 9, 12, 18, ' فدعا صموئيل الرب فأعطى رعودا ومطرا في ذلك اليوم . وخاف جميع الشعب الرب وصموئيل جدا '),
(3566, '1 Samuel', 9, 12, 19, ' وقال جميع الشعب لصموئيل : صل عن عبيدك إلى الرب إلهك حتى لا نموت ، لأننا قد أضفنا إلى جميع خطايانا شرا بطلبنا لأنفسنا ملكا '),
(3567, '1 Samuel', 9, 12, 20, ' فقال صموئيل للشعب : لا تخافوا . إنكم قد فعلتم كل هذا الشر ، ولكن لا تحيدوا عن الرب ، بل اعبدوا الرب بكل قلوبكم '),
(3568, '1 Samuel', 9, 12, 21, ' ولا تحيدوا . لأن ذلك وراء الأباطيل التي لا تفيد ولا تنقذ ، لأنها باطلة '),
(3569, '1 Samuel', 9, 12, 22, ' لأنه لا يترك الرب شعبه من أجل اسمه العظيم . لأنه قد شاء الرب أن يجعلكم له شعبا '),
(3570, '1 Samuel', 9, 12, 23, ' وأما أنا فحاشا لي أن أخطئ إلى الرب فأكف عن الصلاة من أجلكم ، بل أعلمكم الطريق الصالح المستقيم '),
(3571, '1 Samuel', 9, 12, 24, ' إنما اتقوا الرب واعبدوه بالأمانة من كل قلوبكم ، بل انظروا فعله الذي عظمه معكم '),
(3572, '1 Samuel', 9, 12, 25, ' وإن فعلتم شرا فإنكم تهلكون أنتم وملككم جميعا '),
(3573, '1 Samuel', 9, 13, 1, ' كان شاول ابن سنة في ملكه ، وملك سنتين على إسرائيل '),
(3574, '1 Samuel', 9, 13, 2, ' واختار شاول لنفسه ثلاثة آلاف من إسرائيل ، فكان ألفان مع شاول في مخماس وفي جبل بيت إيل ، وألف كان مع يوناثان في جبعة بنيامين . وأما بقية الشعب فأرسلهم كل واحد إلى خيمته '),
(3575, '1 Samuel', 9, 13, 3, ' وضرب يوناثان نصب الفلسطينيين الذي في جبع ، فسمع الفلسطينيون . وضرب شاول بالبوق في جميع الأرض قائلا : ليسمع العبرانيون '),
(3576, '1 Samuel', 9, 13, 4, ' فسمع جميع إسرائيل قولا : قد ضرب شاول نصب الفلسطينيين ، وأيضا قد أنتن إسرائيل لدى الفلسطينيين . فاجتمع الشعب وراء شاول إلى الجلجال '),
(3577, '1 Samuel', 9, 13, 5, ' وتجمع الفلسطينيون لمحاربة إسرائيل ، ثلاثون ألف مركبة ، وستة آلاف فارس ، وشعب كالرمل الذي على شاطئ البحر في الكثرة . وصعدوا ونزلوا في مخماس شرقي بيت آون '),
(3578, '1 Samuel', 9, 13, 6, ' ولما رأى رجال إسرائيل أنهم في ضنك ، لأن الشعب تضايق ، اختبأ الشعب في المغاير والغياض والصخور والصروح والآبار '),
(3579, '1 Samuel', 9, 13, 7, ' وبعض العبرانيين عبروا الأردن إلى أرض جاد وجلعاد . وكان شاول بعد في الجلجال وكل الشعب ارتعد وراءه '),
(3580, '1 Samuel', 9, 13, 8, ' فمكث سبعة أيام حسب ميعاد صموئيل ، ولم يأت صموئيل إلى الجلجال ، والشعب تفرق عنه '),
(3581, '1 Samuel', 9, 13, 9, ' فقال شاول : قدموا إلي المحرقة وذبائح السلامة . فأصعد المحرقة '),
(3582, '1 Samuel', 9, 13, 10, ' وكان لما انتهى من إصعاد المحرقة إذا صموئيل مقبل ، فخرج شاول للقائه ليباركه '),
(3583, '1 Samuel', 9, 13, 11, ' فقال صموئيل : ماذا فعلت ؟  . فقال شاول : لأني رأيت أن الشعب قد تفرق عني ، وأنت لم تأت في أيام الميعاد ، والفلسطينيون متجمعون في مخماس '),
(3584, '1 Samuel', 9, 13, 12, ' فقلت : الآن ينزل الفلسطينيون إلي إلى الجلجال ولم أتضرع إلى وجه الرب ، فتجلدت وأصعدت المحرقة '),
(3585, '1 Samuel', 9, 13, 13, ' فقال صموئيل لشاول : قد انحمقت لم تحفظ وصية الرب إلهك التي أمرك بها ، لأنه الآن كان الرب قد ثبت مملكتك على إسرائيل إلى الأبد '),
(3586, '1 Samuel', 9, 13, 14, ' وأما الآن فمملكتك لا تقوم . قد انتخب الرب لنفسه رجلا حسب قلبه ، وأمره الرب أن يترأس على شعبه . لأنك لم تحفظ ما أمرك به الرب '),
(3587, '1 Samuel', 9, 13, 15, ' وقام صموئيل وصعد من الجلجال إلى جبعة بنيامين . وعد شاول الشعب الموجود معه نحو ست مئة رجل '),
(3588, '1 Samuel', 9, 13, 16, ' وكان شاول ويوناثان ابنه والشعب الموجود معهما مقيمين في جبع بنيامين ، والفلسطينيون نزلوا في مخماس '),
(3589, '1 Samuel', 9, 13, 17, ' فخرج المخربون من محلة الفلسطينيين في ثلاث فرق . الفرقة الواحدة توجهت في طريق عفرة إلى أرض شوعال '),
(3590, '1 Samuel', 9, 13, 18, ' والفرقة الأخرى توجهت في طريق بيت حورون ، والفرقة الأخرى توجهت في طريق التخم المشرف على وادي صبوعيم نحو البرية '),
(3591, '1 Samuel', 9, 13, 19, ' ولم يوجد صانع في كل أرض إسرائيل ، لأن الفلسطينيين قالوا : لئلا يعمل العبرانيون سيفا أو رمحا '),
(3592, '1 Samuel', 9, 13, 20, ' بل كان ينزل كل إسرائيل إلى الفلسطينيين لكي يحدد كل واحد سكته ومنجله وفأسه ومعوله '),
(3593, '1 Samuel', 9, 13, 21, ' عندما كلت حدود السكك والمناجل والمثلثات الأسنان والفؤوس ولترويس المناسيس '),
(3594, '1 Samuel', 9, 13, 22, ' وكان في يوم الحرب أنه لم يوجد سيف ولا رمح بيد جميع الشعب الذي مع شاول ومع يوناثان . على أنه وجد مع شاول ويوناثان ابنه '),
(3595, '1 Samuel', 9, 13, 23, ' وخرج حفظة الفلسطينيين إلى معبر مخماس '),
(3596, '1 Samuel', 9, 14, 1, ' وفي ذات يوم قال يوناثان بن شاول للغلام حامل سلاحه : تعال نعبر إلى حفظة الفلسطينيين الذين في ذلك العبر . ولم يخبر أباه '),
(3597, '1 Samuel', 9, 14, 2, ' وكان شاول مقيما في طرف جبعة تحت الرمانة التي في مغرون ، والشعب الذي معه نحو ست مئة رجل '),
(3598, '1 Samuel', 9, 14, 3, ' وأخيا بن أخيطوب ، أخي إيخابود بن فينحاس بن عالي ، كاهن الرب في شيلوه كان لابسا أفودا . ولم يعلم الشعب أن يوناثان قد ذهب '),
(3599, '1 Samuel', 9, 14, 4, ' وبين المعابر التي التمس يوناثان أن يعبرها إلى حفظة الفلسطينيين سن صخرة من هذه الجهة وسن صخرة من تلك الجهة ، واسم الواحدة بوصيص واسم الأخرى سنه '),
(3600, '1 Samuel', 9, 14, 5, ' والسن الواحد عمود إلى الشمال مقابل مخماس ، والآخر إلى الجنوب مقابل جبع '),
(3601, '1 Samuel', 9, 14, 6, ' فقال يوناثان للغلام حامل سلاحه : تعال نعبر إلى صف هؤلاء الغلف ، لعل الله يعمل معنا ، لأنه ليس للرب مانع عن أن يخلص بالكثير أو بالقليل '),
(3602, '1 Samuel', 9, 14, 7, ' فقال له حامل سلاحه : اعمل كل ما بقلبك . تقدم . هأنذا معك حسب قلبك '),
(3603, '1 Samuel', 9, 14, 8, ' فقال يوناثان : هوذا نحن نعبر إلى القوم ونظهر أنفسنا لهم '),
(3604, '1 Samuel', 9, 14, 9, ' فإن قالوا لنا هكذا : دوموا حتى نصل إليكم . نقف في مكاننا ولا نصعد إليهم '),
(3605, '1 Samuel', 9, 14, 10, ' ولكن إن قالوا هكذا : اصعدوا إلينا . نصعد ، لأن الرب قد دفعهم ليدنا ، وهذه هي العلامة لنا '),
(3606, '1 Samuel', 9, 14, 11, ' فأظهرا أنفسهما لصف الفلسطينيين . فقال الفلسطينيون : هوذا العبرانيون خارجون من الثقوب التي اختبأوا فيها '),
(3607, '1 Samuel', 9, 14, 12, ' فأجاب رجال الصف يوناثان وحامل سلاحه وقالوا : اصعدا إلينا فنعلمكما شيئا . فقال يوناثان لحامل سلاحه : اصعد ورائي لأن الرب قد دفعهم ليد إسرائيل '),
(3608, '1 Samuel', 9, 14, 13, ' فصعد يوناثان على يديه ورجليه وحامل سلاحه وراءه . فسقطوا أمام يوناثان ، وكان حامل سلاحه يقتل وراءه '),
(3609, '1 Samuel', 9, 16, 2, ' فقال صموئيل : كيف أذهب ؟ إن سمع شاول يقتلني . فقال الرب : خذ بيدك عجلة من البقر وقل : قد جئت لأذبح للرب '),
(3610, '1 Samuel', 9, 16, 3, ' وادع يسى إلى الذبيحة ، وأنا أعلمك ماذا تصنع . وامسح لي الذي أقول لك عنه '),
(3611, '1 Samuel', 9, 16, 4, ' ففعل صموئيل كما تكلم الرب وجاء إلى بيت لحم . فارتعد شيوخ المدينة عند استقباله وقالوا : أسلام مجيئك '),
(3612, '1 Samuel', 9, 16, 5, ' فقال : سلام . قد جئت لأذبح للرب . تقدسوا وتعالوا معي إلى الذبيحة . وقدس يسى وبنيه ودعاهم إلى الذبيحة '),
(3613, '1 Samuel', 9, 16, 6, ' وكان لما جاءوا أنه رأى أليآب ، فقال : إن أمام الرب مسيحه '),
(3614, '1 Samuel', 9, 16, 7, ' فقال الرب لصموئيل : لا تنظر إلى منظره وطول قامته لأني قد رفضته . لأنه ليس كما ينظر الإنسان . لأن الإنسان ينظر إلى العينين ، وأما الرب فإنه ينظر إلى القلب '),
(3615, '1 Samuel', 9, 16, 8, ' فدعا يسى أبيناداب وعبره أمام صموئيل ، فقال : وهذا أيضا لم يختره الرب '),
(3616, '1 Samuel', 9, 16, 9, ' وعبر يسى شمة ، فقال : وهذا أيضا لم يختره الرب '),
(3617, '1 Samuel', 9, 16, 10, ' وعبر يسى بنيه السبعة أمام صموئيل ، فقال صموئيل ليسى : الرب لم يختر هؤلاء '),
(3618, '1 Samuel', 9, 16, 11, ' وقال صموئيل ليسى : هل كملوا الغلمان ؟  . فقال : بقي بعد الصغير وهوذا يرعى الغنم . فقال صموئيل ليسى : أرسل وأت به ، لأننا لا نجلس حتى يأتي إلى ههنا '),
(3619, '1 Samuel', 9, 16, 12, ' فأرسل وأتى به . وكان أشقر مع حلاوة العينين وحسن المنظر . فقال الرب : قم امسحه ، لأن هذا هو '),
(3620, '1 Samuel', 9, 16, 13, ' فأخذ صموئيل قرن الدهن ومسحه في وسط إخوته . وحل روح الرب على داود من ذلك اليوم فصاعدا . ثم قام صموئيل وذهب إلى الرامة '),
(3621, '1 Samuel', 9, 16, 14, ' وذهب روح الرب من عند شاول ، وبغته روح رديء من قبل الرب '),
(3622, '1 Samuel', 9, 16, 15, ' فقال عبيد شاول له : هوذا روح رديء من قبل الله يبغتك '),
(3623, '1 Samuel', 9, 16, 16, ' فليأمر سيدنا عبيده قدامه أن يفتشوا على رجل يحسن الضرب بالعود . ويكون إذا كان عليك الروح الرديء من قبل الله ، أنه يضرب بيده فتطيب '),
(3624, '1 Samuel', 9, 16, 17, ' فقال شاول لعبيده : انظروا لي رجلا يحسن الضرب وأتوا به إلي '),
(3625, '1 Samuel', 9, 16, 18, ' فأجاب واحد من الغلمان وقال : هوذا قد رأيت ابنا ليسى البيتلحمي يحسن الضرب ، وهو جبار بأس ورجل حرب ، وفصيح ورجل جميل ، والرب معه '),
(3626, '1 Samuel', 9, 16, 19, ' فأرسل شاول رسلا إلى يسى يقول : أرسل إلي داود ابنك الذي مع الغنم '),
(3627, '1 Samuel', 9, 16, 20, ' فأخذ يسى حمارا حاملا خبزا وزق خمر وجدي معزى ، وأرسلها بيد داود ابنه إلى شاول '),
(3628, '1 Samuel', 9, 16, 21, ' فجاء داود إلى شاول ووقف أمامه ، فأحبه جدا وكان له حامل سلاح '),
(3629, '1 Samuel', 9, 16, 22, ' فأرسل شاول إلى يسى يقول : ليقف داود أمامي لأنه وجد نعمة في عيني '),
(3630, '1 Samuel', 9, 16, 23, ' وكان عندما جاء الروح من قبل الله على شاول أن داود أخذ العود وضرب بيده ، فكان يرتاح شاول ويطيب ويذهب عنه الروح الرديء '),
(3631, '1 Samuel', 9, 17, 1, ' وجمع الفلسطينيون جيوشهم للحرب ، فاجتمعوا في سوكوه التي ليهوذا ، ونزلوا بين سوكوه وعزيقة في أفس دميم '),
(3632, '1 Samuel', 9, 17, 2, ' واجتمع شاول ورجال إسرائيل ونزلوا في وادي البطم ، واصطفوا للحرب للقاء الفلسطينيين '),
(3633, '1 Samuel', 9, 17, 3, ' وكان الفلسطينيون وقوفا على جبل من هنا ، وإسرائيل وقوفا على جبل من هناك ، والوادي بينهم '),
(3634, '1 Samuel', 9, 17, 4, ' فخرج رجل مبارز من جيوش الفلسطينيين اسمه جليات ، من جت ، طوله ست أذرع وشبر '),
(3635, '1 Samuel', 9, 17, 5, ' وعلى رأسه خوذة من نحاس ، وكان لابسا درعا حرشفيا ، ووزن الدرع خمسة آلاف شاقل نحاس '),
(3636, '1 Samuel', 9, 17, 6, ' وجرموقا نحاس على رجليه ، ومزراق نحاس بين كتفيه '),
(3637, '1 Samuel', 9, 17, 7, ' وقناة رمحه كنول النساجين ، وسنان رمحه ست مئة شاقل حديد ، وحامل الترس كان يمشي قدامه '),
(3638, '1 Samuel', 9, 17, 8, ' فوقف ونادى صفوف إسرائيل وقال لهم : لماذا تخرجون لتصطفوا للحرب ؟ أما أنا الفلسطيني ، وأنتم عبيد لشاول ؟ اختاروا لأنفسكم رجلا ولينزل إلي '),
(3639, '1 Samuel', 9, 17, 9, ' فإن قدر أن يحاربني ويقتلني نصير لكم عبيدا ، وإن قدرت أنا عليه وقتلته تصيرون أنتم لنا عبيدا وتخدموننا '),
(3640, '1 Samuel', 9, 17, 10, ' وقال الفلسطيني : أنا عيرت صفوف إسرائيل هذا اليوم . أعطوني رجلا فنتحارب معا '),
(3641, '1 Samuel', 9, 17, 11, ' ولما سمع شاول وجميع إسرائيل كلام الفلسطيني هذا ارتاعوا وخافوا جدا '),
(3642, '1 Samuel', 9, 17, 12, ' وداود هو ابن ذلك الرجل الأفراتي من بيت لحم يهوذا الذي اسمه يسى وله ثمانية بنين . وكان الرجل في أيام شاول قد شاخ وكبر بين الناس '),
(3643, '1 Samuel', 9, 17, 13, ' وذهب بنو يسى الثلاثة الكبار وتبعوا شاول إلى الحرب . وأسماء بنيه الثلاثة الذين ذهبوا إلى الحرب : أليآب البكر ، وأبيناداب ثانيه ، وشمة ثالثهما '),
(3644, '1 Samuel', 9, 17, 14, ' وداود هو الصغير . والثلاثة الكبار ذهبوا وراء شاول '),
(3645, '1 Samuel', 9, 17, 15, ' وأما داود فكان يذهب ويرجع من عند شاول ليرعى غنم أبيه في بيت لحم '),
(3646, '1 Samuel', 9, 17, 16, ' وكان الفلسطيني يتقدم ويقف صباحا ومساء أربعين يوما '),
(3647, '1 Samuel', 9, 17, 17, ' فقال يسى لداود ابنه : خذ لإخوتك إيفة من هذا الفريك ، وهذه العشر الخبزات واركض إلى المحلة إلى إخوتك '),
(3648, '1 Samuel', 9, 17, 18, ' وهذه العشر القطعات من الجبن قدمها لرئيس الألف ، وافتقد سلامة إخوتك وخذ منهم عربونا '),
(3649, '1 Samuel', 9, 17, 19, ' وكان شاول وهم وجميع رجال إسرائيل في وادي البطم يحاربون الفلسطينيين '),
(3650, '1 Samuel', 9, 17, 20, ' فبكر داود صباحا وترك الغنم مع حارس ، وحمل وذهب كما أمره يسى ، وأتى إلى المتراس ، والجيش خارج إلى الاصطفاف وهتفوا للحرب '),
(3651, '1 Samuel', 9, 17, 21, ' واصطف إسرائيل والفلسطينيون صفا مقابل صف '),
(3652, '1 Samuel', 9, 17, 22, ' فترك داود الأمتعة التي معه بيد حافظ الأمتعة ، وركض إلى الصف وأتى وسأل عن سلامة إخوته '),
(3653, '1 Samuel', 9, 17, 23, ' وفيما هو يكلمهم إذا برجل مبارز اسمه جليات الفلسطيني من جت ، صاعد من صفوف الفلسطينيين وتكلم بمثل هذا الكلام ، فسمع داود '),
(3654, '1 Samuel', 9, 17, 24, ' وجميع رجال إسرائيل لما رأوا الرجل هربوا منه وخافوا جدا '),
(3655, '1 Samuel', 9, 17, 25, ' فقال رجال إسرائيل : أرأيتم هذا الرجل الصاعد ؟ ليعير إسرائيل هو صاعد فيكون أن الرجل الذي يقتله يغنيه الملك غنى جزيلا ، ويعطيه بنته ، ويجعل بيت أبيه حرا في إسرائيل '),
(3656, '1 Samuel', 9, 17, 26, ' فكلم داود الرجال الواقفين معه قائلا : ماذا يفعل للرجل الذي يقتل ذلك الفلسطيني ، ويزيل العار عن إسرائيل ؟ لأنه من هو هذا الفلسطيني الأغلف حتى يعير صفوف الله الحي '),
(3657, '1 Samuel', 9, 17, 27, ' فكلمه الشعب بمثل هذا الكلام قائلين : كذا يفعل للرجل الذي يقتله '),
(3658, '1 Samuel', 9, 17, 28, ' وسمع أخوه الأكبر أليآب كلامه مع الرجال ، فحمي غضب أليآب على داود وقال : لماذا نزلت ؟ وعلى من تركت تلك الغنيمات القليلة في البرية ؟ أنا علمت كبرياءك وشر قلبك ، لأنك إنما نزلت لكي ترى الحرب '),
(3659, '1 Samuel', 9, 17, 29, ' فقال داود : ماذا عملت الآن ؟ أما هو كلام '),
(3660, '1 Samuel', 9, 17, 30, ' وتحول من عنده نحو آخر ، وتكلم بمثل هذا الكلام ، فرد له الشعب جوابا كالجواب الأول '),
(3661, '1 Samuel', 9, 17, 31, ' وسمع الكلام الذي تكلم به داود وأخبروا به أمام شاول ، فاستحضره '),
(3662, '1 Samuel', 9, 17, 32, ' فقال داود لشاول : لا يسقط قلب أحد بسببه . عبدك يذهب ويحارب هذا الفلسطيني '),
(3663, '1 Samuel', 9, 17, 33, ' فقال شاول لداود : لا تستطيع أن تذهب إلى هذا الفلسطيني لتحاربه لأنك غلام وهو رجل حرب منذ صباه '),
(3664, '1 Samuel', 9, 17, 34, ' فقال داود لشاول : كان عبدك يرعى لأبيه غنما ، فجاء أسد مع دب وأخذ شاة من القطيع '),
(3665, '1 Samuel', 9, 17, 35, ' فخرجت وراءه وقتلته وأنقذتها من فيه ، ولما قام علي أمسكته من ذقنه وضربته فقتلته '),
(3666, '1 Samuel', 9, 17, 36, ' قتل عبدك الأسد والدب جميعا . وهذا الفلسطيني الأغلف يكون كواحد منهما ، لأنه قد عير صفوف الله الحي '),
(3667, '1 Samuel', 9, 17, 37, ' وقال داود : الرب الذي أنقذني من يد الأسد ومن يد الدب هو ينقذني من يد هذا الفلسطيني . فقال شاول لداود : اذهب وليكن الرب معك '),
(3668, '1 Samuel', 9, 17, 38, ' وألبس شاول داود ثيابه ، وجعل خوذة من نحاس على رأسه ، وألبسه درعا '),
(3669, '1 Samuel', 9, 17, 39, ' فتقلد داود بسيفه فوق ثيابه وعزم أن يمشي ، لأنه لم يكن قد جرب . فقال داود لشاول : لا أقدر أن أمشي بهذه ، لأني لم أجربها . ونزعها داود عنه '),
(3670, '1 Samuel', 9, 17, 40, ' وأخذ عصاه بيده ، وانتخب له خمسة حجارة ملس من الوادي وجعلها في كنف الرعاة الذي له ، أي في الجراب ، ومقلاعه بيده وتقدم نحو الفلسطيني '),
(3671, '1 Samuel', 9, 17, 41, ' وذهب الفلسطيني ذاهبا واقترب إلى داود والرجل حامل الترس أمامه '),
(3672, '1 Samuel', 9, 17, 42, ' ولما نظر الفلسطيني ورأى داود استحقره ، لأنه كان غلاما وأشقر جميل المنظر '),
(3673, '1 Samuel', 9, 17, 43, ' فقال الفلسطيني لداود : ألعلي أنا كلب حتى أنك تأتي إلي بعصي ؟  . ولعن الفلسطيني داود بآلهته '),
(3674, '1 Samuel', 9, 17, 44, ' وقال الفلسطيني لداود : تعال إلي فأعطي لحمك لطيور السماء ووحوش البرية '),
(3675, '1 Samuel', 9, 17, 45, ' فقال داود للفلسطيني : أنت تأتي إلي بسيف وبرمح وبترس ، وأنا آتي إليك باسم رب الجنود إله صفوف إسرائيل الذين عيرتهم '),
(3676, '1 Samuel', 9, 17, 46, ' هذا اليوم يحبسك الرب في يدي ، فأقتلك وأقطع رأسك . وأعطي جثث جيش الفلسطينيين هذا اليوم لطيور السماء وحيوانات الأرض ، فتعلم كل الأرض أنه يوجد إله لإسرائيل '),
(3677, '1 Samuel', 9, 17, 47, ' وتعلم هذه الجماعة كلها أنه ليس بسيف ولا برمح يخلص الرب ، لأن الحرب للرب وهو يدفعكم ليدنا '),
(3678, '1 Samuel', 9, 17, 48, ' وكان لما قام الفلسطيني وذهب وتقدم للقاء داود أن داود أسرع وركض نحو الصف للقاء الفلسطيني '),
(3679, '1 Samuel', 9, 17, 49, ' ومد داود يده إلى الكنف وأخذ منه حجرا ورماه بالمقلاع ، وضرب الفلسطيني في جبهته ، فارتز الحجر في جبهته ، وسقط على وجهه إلى الأرض '),
(3680, '1 Samuel', 9, 17, 50, ' فتمكن داود من الفلسطيني بالمقلاع والحجر ، وضرب الفلسطيني وقتله . ولم يكن سيف بيد داود '),
(3681, '1 Samuel', 9, 17, 51, ' فركض داود ووقف على الفلسطيني وأخذ سيفه واخترطه من غمده وقتله وقطع به رأسه . فلما رأى الفلسطينيون أن جبارهم قد مات هربوا '),
(3682, '1 Samuel', 9, 17, 52, ' فقام رجال إسرائيل ويهوذا وهتفوا ولحقوا الفلسطينيين حتى مجيئك إلى الوادي ، وحتى أبواب عقرون . فسقطت قتلى الفلسطينيين في طريق شعرايم إلى جت وإلى عقرون '),
(3683, '1 Samuel', 9, 17, 53, ' ثم رجع بنو إسرائيل من الاحتماء وراء الفلسطينيين ونهبوا محلتهم '),
(3684, '1 Samuel', 9, 14, 14, ' وكانت الضربة الأولى التي ضربها يوناثان وحامل سلاحه نحو عشرين رجلا في نحو نصف تلم فدان أرض '),
(3685, '1 Samuel', 9, 14, 15, ' وكان ارتعاد في المحلة ، في الحقل ، وفي جميع الشعب . الصف والمخربون ارتعدوا هم أيضا ، ورجفت الأرض فكان ارتعاد عظيم '),
(3686, '1 Samuel', 9, 14, 16, ' فنظر المراقبون لشاول في جبعة بنيامين ، وإذا بالجمهور قد ذاب وذهبوا متبددين '),
(3687, '1 Samuel', 9, 14, 17, ' فقال شاول للشعب الذي معه : عدوا الآن وانظروا من ذهب من عندنا . فعدوا ، وهوذا يوناثان وحامل سلاحه ليسا موجودين '),
(3688, '1 Samuel', 9, 14, 18, ' فقال شاول لأخيا : قدم تابوت الله . لأن تابوت الله كان في ذلك اليوم مع بني إسرائيل '),
(3689, '1 Samuel', 9, 14, 19, ' وفيما كان شاول يتكلم بعد مع الكاهن ، تزايد الضجيج الذي في محلة الفلسطينيين وكثر . فقال شاول للكاهن : كف يدك '),
(3690, '1 Samuel', 9, 14, 20, ' وصاح شاول وجميع الشعب الذي معه وجاءوا إلى الحرب ، وإذا بسيف كل واحد على صاحبه . اضطراب عظيم جدا '),
(3691, '1 Samuel', 9, 14, 21, ' والعبرانيون الذين كانوا مع الفلسطينيين منذ أمس وما قبله ، الذين صعدوا معهم إلى المحلة من حواليهم ، صاروا هم أيضا مع إسرائيل الذين مع شاول ويوناثان '),
(3692, '1 Samuel', 9, 14, 22, ' وسمع جميع رجال إسرائيل الذين اختبأوا في جبل أفرايم أن الفلسطينيين هربوا ، فشدوا هم أيضا وراءهم في الحرب '),
(3693, '1 Samuel', 9, 14, 23, ' فخلص الرب إسرائيل في ذلك اليوم . وعبرت الحرب إلى بيت آون '),
(3694, '1 Samuel', 9, 14, 24, ' وضنك رجال إسرائيل في ذلك اليوم ، لأن شاول حلف الشعب قائلا : ملعون الرجل الذي يأكل خبزا إلى المساء حتى أنتقم من أعدائي . فلم يذق جميع الشعب خبزا '),
(3695, '1 Samuel', 9, 14, 25, ' وجاء كل الشعب إلى الوعر وكان عسل على وجه الحقل '),
(3696, '1 Samuel', 9, 14, 26, ' ولما دخل الشعب الوعر إذا بالعسل يقطر ولم يمد أحد يده إلى فيه ، لأن الشعب خاف من القسم '),
(3697, '1 Samuel', 9, 14, 27, ' وأما يوناثان فلم يسمع عندما استحلف أبوه الشعب ، فمد طرف النشابة التي بيده وغمسه في قطر العسل ورد يده إلى فيه فاستنارت عيناه '),
(3698, '1 Samuel', 9, 14, 28, ' فأجاب واحد من الشعب وقال : قد حلف أبوك الشعب حلفا قائلا : ملعون الرجل الذي يأكل خبزا اليوم . فأعيا الشعب '),
(3699, '1 Samuel', 9, 14, 29, ' فقال يوناثان : قد كدر أبي الأرض . انظروا كيف استنارت عيناي لأني ذقت قليلا من هذا العسل '),
(3700, '1 Samuel', 9, 14, 30, ' فكم بالحري لو أكل اليوم الشعب من غنيمة أعدائهم التي وجدوا ؟ أما كانت الآن ضربة أعظم على الفلسطينيين '),
(3701, '1 Samuel', 9, 14, 31, ' فضربوا في ذلك اليوم الفلسطينيين من مخماس إلى أيلون . وأعيا الشعب جدا '),
(3702, '1 Samuel', 9, 14, 32, ' وثار الشعب على الغنيمة ، فأخذوا غنما وبقرا وعجولا ، وذبحوا على الأرض وأكل الشعب على الدم '),
(3703, '1 Samuel', 9, 14, 33, ' فأخبروا شاول قائلين : هوذا الشعب يخطئ إلى الرب بأكله على الدم . فقال : قد غدرتم . دحرجوا إلي الآن حجرا كبيرا '),
(3704, '1 Samuel', 9, 14, 34, ' وقال شاول : تفرقوا بين الشعب وقولوا لهم أن يقدموا إلي كل واحد ثوره وكل واحد شاته ، واذبحوا ههنا وكلوا ولا تخطئوا إلى الرب بأكلكم مع الدم . فقدم جميع الشعب كل واحد ثوره بيده في تلك الليلة وذبحوا هناك '),
(3705, '1 Samuel', 9, 14, 35, ' وبنى شاول مذبحا للرب . الذي شرع ببنيانه مذبحا للرب '),
(3706, '1 Samuel', 9, 14, 36, ' وقال شاول : لننزل وراء الفلسطينيين ليلا وننهبهم إلى ضوء الصباح ولا نبق منهم أحدا . فقالوا : افعل كل ما يحسن في عينيك . وقال الكاهن : لنتقدم هنا إلى الله '),
(3707, '1 Samuel', 9, 14, 37, ' فسأل شاول الله : أأنحدر وراء الفلسطينيين ؟ أتدفعهم ليد إسرائيل ؟  . فلم يجبه في ذلك اليوم '),
(3708, '1 Samuel', 9, 14, 38, ' فقال شاول : تقدموا إلى هنا يا جميع وجوه الشعب ، واعلموا وانظروا بماذا كانت هذه الخطية اليوم '),
(3709, '1 Samuel', 9, 14, 39, ' لأنه حي هو الرب مخلص إسرائيل ، ولو كانت في يوناثان ابني فإنه يموت موتا . ولم يكن من يجيبه من كل الشعب '),
(3710, '1 Samuel', 9, 14, 40, ' فقال لجميع إسرائيل : أنتم تكونون في جانب وأنا ويوناثان ابني في جانب . فقال الشعب لشاول : اصنع ما يحسن في عينيك '),
(3711, '1 Samuel', 9, 14, 41, ' وقال شاول للرب إله إسرائيل : هب صدقا . فأخذ يوناثان وشاول ، أما الشعب فخرجوا '),
(3712, '1 Samuel', 9, 14, 42, ' فقال شاول : ألقوا بيني وبين يوناثان ابني . فأخذ يوناثان '),
(3713, '1 Samuel', 9, 14, 43, ' فقال شاول ليوناثان : أخبرني ماذا فعلت . فأخبره يوناثان وقال : ذقت ذوقا بطرف النشابة التي بيدي قليل عسل . فهأنذا أموت '),
(3714, '1 Samuel', 9, 14, 44, ' فقال شاول : هكذا يفعل الله وهكذا يزيد إنك موتا تموت يا يوناثان '),
(3715, '1 Samuel', 9, 14, 45, ' فقال الشعب لشاول : أيموت يوناثان الذي صنع هذا الخلاص العظيم في إسرائيل ؟ حاشا حي هو الرب ، لا تسقط شعرة من رأسه إلى الأرض لأنه مع الله عمل هذا اليوم . فافتدى الشعب يوناثان فلم يمت '),
(3716, '1 Samuel', 9, 14, 46, ' فصعد شاول من وراء الفلسطينيين ، وذهب الفلسطينيون إلى مكانهم '),
(3717, '1 Samuel', 9, 14, 47, ' وأخذ شاول الملك على إسرائيل ، وحارب جميع أعدائه حواليه : موآب وبني عمون وأدوم وملوك صوبة والفلسطينيين . وحيثما توجه غلب '),
(3718, '1 Samuel', 9, 14, 48, ' وفعل ببأس وضرب عماليق ، وأنقذ إسرائيل من يد ناهبيه '),
(3719, '1 Samuel', 9, 14, 49, ' وكان بنو شاول : يوناثان ويشوي وملكيشوع ، واسما ابنتيه : اسم البكر ميرب واسم الصغيرة ميكال '),
(3720, '1 Samuel', 9, 14, 50, ' واسم امرأة شاول أخينوعم بنت أخيمعص ، واسم رئيس جيشه أبينير بن نير عم شاول '),
(3721, '1 Samuel', 9, 14, 51, ' وقيس أبو شاول ونير أبو أبنير ابنا أبيئيل '),
(3722, '1 Samuel', 9, 14, 52, ' وكانت حرب شديدة على الفلسطينيين كل أيام شاول . وإذا رأى شاول رجلا جبارا أو ذا بأس ضمه إلى نفسه '),
(3723, '1 Samuel', 9, 15, 1, ' وقال صموئيل لشاول : إياي أرسل الرب لمسحك ملكا على شعبه إسرائيل . والآن فاسمع صوت كلام الرب '),
(3724, '1 Samuel', 9, 15, 2, ' هكذا يقول رب الجنود : إني قد افتقدت ما عمل عماليق بإسرائيل حين وقف له في الطريق عند صعوده من مصر '),
(3725, '1 Samuel', 9, 15, 3, ' فالآن اذهب واضرب عماليق ، وحرموا كل ما له ولا تعف عنهم بل اقتل رجلا وامرأة ، طفلا ورضيعا ، بقرا وغنما ، جملا وحمارا '),
(3726, '1 Samuel', 9, 15, 4, ' فاستحضر شاول الشعب وعده في طلايم ، مئتي ألف راجل ، وعشرة آلاف رجل من يهوذا. '),
(3727, '1 Samuel', 9, 15, 5, ' ثم جاء شاول إلى مدينة عماليق وكمن في الوادي '),
(3728, '1 Samuel', 9, 15, 6, ' وقال شاول للقينيين : اذهبوا حيدوا انزلوا من وسط العمالقة لئلا أهلككم معهم ، وأنتم قد فعلتم معروفا مع جميع بني إسرائيل عند صعودهم من مصر . فحاد القيني من وسط عماليق '),
(3729, '1 Samuel', 9, 15, 7, ' وضرب شاول عماليق من حويلة حتى مجيئك إلى شور التي مقابل مصر '),
(3730, '1 Samuel', 9, 15, 8, ' وأمسك أجاج ملك عماليق حيا ، وحرم جميع الشعب بحد السيف '),
(3731, '1 Samuel', 9, 15, 9, ' وعفا شاول والشعب عن أجاج وعن خيار الغنم والبقر والثنيان والخراف ، وعن كل الجيد ، ولم يرضوا أن يحرموها . وكل الأملاك المحتقرة والمهزولة حرموها '),
(3732, '1 Samuel', 9, 15, 10, ' وكان كلام الرب إلى صموئيل قائلا '),
(3733, '1 Samuel', 9, 15, 11, ' ندمت على أني قد جعلت شاول ملكا ، لأنه رجع من ورائي ولم يقم كلامي . فاغتاظ صموئيل وصرخ إلى الرب الليل كله '),
(3734, '1 Samuel', 9, 15, 12, ' فبكر صموئيل للقاء شاول صباحا . فأخبر صموئيل وقيل له : قد جاء شاول إلى الكرمل ، وهوذا قد نصب لنفسه نصبا ودار وعبر ونزل إلى الجلجال '),
(3735, '1 Samuel', 9, 15, 13, ' ولما جاء صموئيل إلى شاول قال له شاول : مبارك أنت للرب . قد أقمت كلام الرب '),
(3736, '1 Samuel', 9, 15, 14, ' فقال صموئيل : وما هو صوت الغنم هذا في أذني ، وصوت البقر الذي أنا سامع '),
(3737, '1 Samuel', 9, 15, 15, ' فقال شاول : من العمالقة ، قد أتوا بها ، لأن الشعب قد عفا عن خيار الغنم والبقر لأجل الذبح للرب إلهك . وأما الباقي فقد حرمناه '),
(3738, '1 Samuel', 9, 15, 16, ' فقال صموئيل لشاول : كف فأخبرك بما تكلم به الرب إلي هذه الليلة . فقال له : تكلم '),
(3739, '1 Samuel', 9, 15, 17, ' فقال صموئيل : أليس إذ كنت صغيرا في عينيك صرت رأس أسباط إسرائيل ومسحك الرب ملكا على إسرائيل '),
(3740, '1 Samuel', 9, 15, 18, ' وأرسلك الرب في طريق وقال : اذهب وحرم الخطاة عماليق وحاربهم حتى يفنوا '),
(3741, '1 Samuel', 9, 15, 19, ' فلماذا لم تسمع لصوت الرب ، بل ثرت على الغنيمة وعملت الشر في عيني الرب '),
(3742, '1 Samuel', 9, 15, 20, ' فقال شاول لصموئيل : إني قد سمعت لصوت الرب وذهبت في الطريق التي أرسلني فيها الرب وأتيت بأجاج ملك عماليق وحرمت عماليق '),
(3743, '1 Samuel', 9, 15, 21, ' فأخذ الشعب من الغنيمة غنما وبقرا ، أوائل الحرام لأجل الذبح للرب إلهك في الجلجال '),
(3744, '1 Samuel', 9, 15, 22, ' فقال صموئيل : هل مسرة الرب بالمحرقات والذبائح كما باستماع صوت الرب ؟ هوذا الاستماع أفضل من الذبيحة ، والإصغاء أفضل من شحم الكباش '),
(3745, '1 Samuel', 9, 15, 23, ' لأن التمرد كخطية العرافة ، والعناد كالوثن والترافيم . لأنك رفضت كلام الرب رفضك من الملك '),
(3746, '1 Samuel', 9, 15, 24, ' فقال شاول لصموئيل : أخطأت لأني تعديت قول الرب وكلامك ، لأني خفت من الشعب وسمعت لصوتهم '),
(3747, '1 Samuel', 9, 15, 25, ' والآن فاغفر خطيتي وارجع معي فأسجد للرب '),
(3748, '1 Samuel', 9, 15, 26, ' فقال صموئيل لشاول : لا أرجع معك لأنك رفضت كلام الرب ، فرفضك الرب من أن تكون ملكا على إسرائيل '),
(3749, '1 Samuel', 9, 15, 27, ' ودار صموئيل ليمضي ، فأمسك بذيل جبته فانمزق '),
(3750, '1 Samuel', 9, 15, 28, ' فقال له صموئيل : يمزق الرب مملكة إسرائيل عنك اليوم ويعطيها لصاحبك الذي هو خير منك '),
(3751, '1 Samuel', 9, 15, 29, ' وأيضا نصيح إسرائيل لا يكذب ولا يندم ، لأنه ليس إنسانا ليندم '),
(3752, '1 Samuel', 9, 15, 30, ' فقال : قد أخطأت . والآن فأكرمني أمام شيوخ شعبي وأمام إسرائيل ، وارجع معي فأسجد للرب إلهك '),
(3753, '1 Samuel', 9, 15, 31, ' فرجع صموئيل وراء شاول ، وسجد شاول للرب '),
(3754, '1 Samuel', 9, 15, 32, ' وقال صموئيل : قدموا إلي أجاج ملك عماليق . فذهب إليه أجاج فرحا . وقال أجاج : حقا قد زالت مرارة الموت '),
(3755, '1 Samuel', 9, 15, 33, ' فقال صموئيل : كما أثكل سيفك النساء ، كذلك تثكل أمك بين النساء . فقطع صموئيل أجاج أمام الرب في الجلجال '),
(3756, '1 Samuel', 9, 15, 34, ' وذهب صموئيل إلى الرامة ، وأما شاول فصعد إلى بيته في جبعة شاول '),
(3757, '1 Samuel', 9, 15, 35, ' ولم يعد صموئيل لرؤية شاول إلى يوم موته ، لأن صموئيل ناح على شاول . والرب ندم لأنه ملك شاول على إسرائيل '),
(3758, '1 Samuel', 9, 16, 1, ' فقال الرب لصموئيل : حتى متى تنوح على شاول ، وأنا قد رفضته عن أن يملك على إسرائيل ؟ املأ قرنك دهنا وتعال أرسلك إلى يسى البيتلحمي ، لأني قد رأيت لي في بنيه ملكا '),
(3759, '1 Samuel', 9, 17, 54, ' وأخذ داود رأس الفلسطيني وأتى به إلى أورشليم ، ووضع أدواته في خيمته '),
(3760, '1 Samuel', 9, 17, 55, ' ولما رأى شاول داود خارجا للقاء الفلسطيني قال لأبنير رئيس الجيش : ابن من هذا الغلام يا أبنير ؟  . فقال أبنير : وحياتك أيها الملك لست أعلم '),
(3761, '1 Samuel', 9, 17, 56, ' فقال الملك : اسأل ابن من هذا الغلام '),
(3762, '1 Samuel', 9, 17, 57, ' ولما رجع داود من قتل الفلسطيني أخذه أبنير وأحضره أمام شاول ورأس الفلسطيني بيده '),
(3763, '1 Samuel', 9, 17, 58, ' فقال له شاول : ابن من أنت يا غلام ؟  . فقال داود : ابن عبدك يسى البيتلحمي '),
(3764, '1 Samuel', 9, 18, 1, ' وكان لما فرغ من الكلام مع شاول أن نفس يوناثان تعلقت بنفس داود ، وأحبه يوناثان كنفسه '),
(3765, '1 Samuel', 9, 18, 2, ' فأخذه شاول في ذلك اليوم ولم يدعه يرجع إلى بيت أبيه '),
(3766, '1 Samuel', 9, 18, 3, ' وقطع يوناثان وداود عهدا لأنه أحبه كنفسه '),
(3767, '1 Samuel', 9, 18, 4, ' وخلع يوناثان الجبة التي عليه وأعطاها لداود مع ثيابه وسيفه وقوسه ومنطقته '),
(3768, '1 Samuel', 9, 18, 5, ' وكان داود يخرج إلى حيثما أرسله شاول . كان يفلح . فجعله شاول على رجال الحرب . وحسن في أعين جميع الشعب وفي أعين عبيد شاول أيضا '),
(3769, '1 Samuel', 9, 18, 6, ' وكان عند مجيئهم حين رجع داود من قتل الفلسطيني ، أن النساء خرجت من جميع مدن إسرائيل بالغناء والرقص للقاء شاول الملك بدفوف وبفرح وبمثلثات '),
(3770, '1 Samuel', 9, 18, 7, ' فأجابت النساء اللاعبات وقلن : ضرب شاول ألوفه وداود ربواته '),
(3771, '1 Samuel', 9, 18, 8, ' فاحتمى شاول جدا وساء هذا الكلام في عينيه ، وقال : أعطين داود ربوات وأما أنا فأعطينني الألوف وبعد فقط تبقى له المملكة '),
(3772, '1 Samuel', 9, 18, 9, ' فكان شاول يعاين داود من ذلك اليوم فصاعدا '),
(3773, '1 Samuel', 9, 18, 10, ' وكان في الغد أن الروح الرديء من قبل الله اقتحم شاول وجن في وسط البيت . وكان داود يضرب بيده كما في يوم فيوم ، وكان الرمح بيد شاول '),
(3774, '1 Samuel', 9, 18, 11, ' فأشرع شاول الرمح وقال : أضرب داود حتى إلى الحائط . فتحول داود من أمامه مرتين '),
(3775, '1 Samuel', 9, 18, 12, ' وكان شاول يخاف داود لأن الرب كان معه ، وقد فارق شاول '),
(3776, '1 Samuel', 9, 18, 13, ' فأبعده شاول عنه وجعله له رئيس ألف ، فكان يخرج ويدخل أمام الشعب '),
(3777, '1 Samuel', 9, 18, 14, ' وكان داود مفلحا في جميع طرقه والرب معه '),
(3778, '1 Samuel', 9, 18, 15, ' فلما رأى شاول أنه مفلح جدا فزع منه '),
(3779, '1 Samuel', 9, 18, 16, ' وكان جميع إسرائيل ويهوذا يحبون داود لأنه كان يخرج ويدخل أمامهم '),
(3780, '1 Samuel', 9, 18, 17, ' وقال شاول لداود : هوذا ابنتي الكبيرة ميرب أعطيك إياها امرأة . إنما كن لي ذا بأس وحارب حروب الرب . فإن شاول قال : لا تكن يدي عليه ، بل لتكن عليه يد الفلسطينيين '),
(3781, '1 Samuel', 9, 18, 18, ' فقال داود لشاول : من أنا ، وما هي حياتي وعشيرة أبي في إسرائيل حتى أكون صهر الملك '),
(3782, '1 Samuel', 9, 18, 19, ' وكان في وقت إعطاء ميرب ابنة شاول لداود أنها أعطيت لعدريئيل المحولي امرأة '),
(3783, '1 Samuel', 9, 18, 20, ' وميكال ابنة شاول أحبت داود ، فأخبروا شاول ، فحسن الأمر في عينيه '),
(3784, '1 Samuel', 9, 18, 21, ' وقال شاول : أعطيه إياها فتكون له شركا وتكون يد الفلسطينيين عليه . وقال شاول لداود ثانية : تصاهرني اليوم '),
(3785, '1 Samuel', 9, 18, 22, ' وأمر شاول عبيده : تكلموا مع داود سرا قائلين : هوذا قد سر بك الملك ، وجميع عبيده قد أحبوك . فالآن صاهر الملك '),
(3786, '1 Samuel', 9, 18, 23, ' فتكلم عبيد شاول في أذني داود بهذا الكلام . فقال داود : هل هو مستخف في أعينكم مصاهرة الملك وأنا رجل مسكين وحقير '),
(3787, '1 Samuel', 9, 18, 24, ' فأخبر شاول عبيده قائلين : بمثل هذا الكلام تكلم داود '),
(3788, '1 Samuel', 9, 18, 25, ' فقال شاول : هكذا تقولون لداود : ليست مسرة الملك بالمهر ، بل بمئة غلفة من الفلسطينيين للانتقام من أعداء الملك . وكان شاول يتفكر أن يوقع داود بيد الفلسطينيين '),
(3789, '1 Samuel', 9, 18, 26, ' فأخبر عبيده داود بهذا الكلام ، فحسن الكلام في عيني داود أن يصاهر الملك . ولم تكمل الأيام '),
(3790, '1 Samuel', 9, 18, 27, ' حتى قام داود وذهب هو ورجاله وقتل من الفلسطينيين مئتي رجل ، وأتى داود بغلفهم فأكملوها للملك لمصاهرة الملك . فأعطاه شاول ميكال ابنته امرأة '),
(3791, '1 Samuel', 9, 18, 28, ' فرأى شاول وعلم أن الرب مع داود . وميكال ابنة شاول كانت تحبه '),
(3792, '1 Samuel', 9, 18, 29, ' وعاد شاول يخاف داود بعد ، وصار شاول عدوا لداود كل الأيام '),
(3793, '1 Samuel', 9, 18, 30, ' وخرج أقطاب الفلسطينيين . ومن حين خروجهم كان داود يفلح أكثر من جميع عبيد شاول ، فتوقر اسمه جدا '),
(3794, '1 Samuel', 9, 19, 1, ' وكلم شاول يوناثان ابنه وجميع عبيده أن يقتلوا داود '),
(3795, '1 Samuel', 9, 19, 2, ' وأما يوناثان بن شاول فسر بداود جدا . فأخبر يوناثان داود قائلا : شاول أبي ملتمس قتلك ، والآن فاحتفظ على نفسك إلى الصباح ، وأقم في خفية واختبئ '),
(3796, '1 Samuel', 9, 19, 3, ' وأنا أخرج وأقف بجانب أبي في الحقل الذي أنت فيه ، وأكلم أبي عنك ، وأرى ماذا يصير وأخبرك '),
(3797, '1 Samuel', 9, 19, 4, ' وتكلم يوناثان عن داود حسنا مع شاول أبيه وقال له : لا يخطئ الملك إلى عبده داود ، لأنه لم يخطئ إليك ، ولأن أعماله حسنة لك جدا '),
(3798, '1 Samuel', 9, 19, 5, ' فإنه وضع نفسه بيده وقتل الفلسطيني فصنع الرب خلاصا عظيما لجميع إسرائيل . أنت رأيت وفرحت . فلماذا تخطئ إلى دم بريء بقتل داود بلا سبب '),
(3799, '1 Samuel', 9, 19, 6, ' فسمع شاول لصوت يوناثان ، وحلف شاول : حي هو الرب لا يقتل '),
(3800, '1 Samuel', 9, 19, 7, ' فدعا يوناثان داود وأخبره يوناثان بجميع هذا الكلام . ثم جاء يوناثان بداود إلى شاول فكان أمامه كأمس وما قبله '),
(3801, '1 Samuel', 9, 19, 8, ' وعادت الحرب تحدث ، فخرج داود وحارب الفلسطينيين وضربهم ضربة عظيمة فهربوا من أمامه '),
(3802, '1 Samuel', 9, 19, 9, ' وكان الروح الرديء من قبل الرب على شاول وهو جالس في بيته ورمحه بيده ، وكان داود يضرب باليد '),
(3803, '1 Samuel', 9, 19, 10, ' فالتمس شاول أن يطعن داود بالرمح حتى إلى الحائط ، ففر من أمام شاول فضرب الرمح إلى الحائط ، فهرب داود ونجا تلك الليلة '),
(3804, '1 Samuel', 9, 19, 11, ' فأرسل شاول رسلا إلى بيت داود ليراقبوه ويقتلوه في الصباح . فأخبرت داود ميكال امرأته قائلة : إن كنت لا تنجو بنفسك هذه الليلة فإنك تقتل غدا '),
(3805, '1 Samuel', 9, 19, 12, ' فأنزلت ميكال داود من الكوة ، فذهب هاربا ونجا '),
(3806, '1 Samuel', 9, 19, 13, ' فأخذت ميكال الترافيم ووضعته في الفراش ، ووضعت لبدة المعزى تحت رأسه وغطته بثوب '),
(3807, '1 Samuel', 9, 19, 14, ' وأرسل شاول رسلا لأخذ داود ، فقالت : هو مريض '),
(3808, '1 Samuel', 9, 19, 15, ' ثم أرسل شاول الرسل ليروا داود قائلا : اصعدوا به إلي على الفراش لكي أقتله '),
(3809, '1 Samuel', 9, 19, 16, ' فجاء الرسل وإذا في الفراش الترافيم ولبدة المعزى تحت رأسه '),
(3810, '1 Samuel', 9, 19, 17, ' فقال شاول لميكال : لماذا خدعتني ، فأطلقت عدوي حتى نجا ؟  . فقالت ميكال لشاول : هو قال لي : أطلقيني ، لماذا أقتلك '),
(3811, '1 Samuel', 9, 19, 18, ' فهرب داود ونجا وجاء إلى صموئيل في الرامة وأخبره بكل ما عمل به شاول . وذهب هو وصموئيل وأقاما في نايوت '),
(3812, '1 Samuel', 9, 19, 19, ' فأخبر شاول وقيل له : هوذا داود في نايوت في الرامة '),
(3813, '1 Samuel', 9, 19, 20, ' فأرسل شاول رسلا لأخذ داود . ولما رأوا جماعة الأنبياء يتنبأون ، وصموئيل واقفا رئيسا عليهم ، كان روح الله على رسل شاول فتنبأوا هم أيضا '),
(3814, '1 Samuel', 9, 19, 21, ' وأخبروا شاول ، فأرسل رسلا آخرين ، فتنبأوا هم أيضا . ثم عاد شاول فأرسل رسلا ثالثة ، فتنبأوا هم أيضا '),
(3815, '1 Samuel', 9, 19, 22, ' فذهب هو أيضا إلى الرامة وجاء إلى البئر العظيمة التي عند سيخو وسأل وقال : أين صموئيل وداود ؟  . فقيل : ها هما في نايوت في الرامة '),
(3816, '1 Samuel', 9, 19, 23, ' فذهب إلى هناك إلى نايوت في الرامة ، فكان عليه أيضا روح الله ، فكان يذهب ويتنبأ حتى جاء إلى نايوت في الرامة '),
(3817, '1 Samuel', 9, 19, 24, ' فخلع هو أيضا ثيابه وتنبأ هو أيضا أمام صموئيل ، وانطرح عريانا ذلك النهار كله وكل الليل . لذلك يقولون : أشاول أيضا بين الأنبياء '),
(3818, '1 Samuel', 9, 20, 1, ' فهرب داود من نايوت في الرامة ، وجاء وقال قدام يوناثان : ماذا عملت ؟ وما هو إثمي ؟ وما هي خطيتي أمام أبيك حتى يطلب نفسي '),
(3819, '1 Samuel', 9, 20, 2, ' فقال له : حاشا . لا تموت هوذا أبي لا يعمل أمرا كبيرا ولا أمرا صغيرا إلا ويخبرني به . ولماذا يخفي عني أبي هذا الأمر ؟ ليس كذا '),
(3820, '1 Samuel', 9, 20, 3, ' فحلف أيضا داود وقال : إن أباك قد علم أني قد وجدت نعمة في عينيك ، فقال : لا يعلم يوناثان هذا لئلا يغتم . ولكن حي هو الرب ، وحية هي نفسك ، إنه كخطوة بيني وبين الموت '),
(3821, '1 Samuel', 9, 20, 4, ' فقال يوناثان لداود : مهما تقل نفسك أفعله لك '),
(3822, '1 Samuel', 9, 20, 5, ' فقال داود ليوناثان : هوذا الشهر غدا حينما أجلس مع الملك للأكل . ولكن أرسلني فأختبئ في الحقل إلى مساء اليوم الثالث '),
(3823, '1 Samuel', 9, 20, 6, ' وإذا افتقدني أبوك ، فقل : قد طلب داود مني طلبة أن يركض إلى بيت لحم مدينته ، لأن هناك ذبيحة سنوية لكل العشيرة '),
(3824, '1 Samuel', 9, 20, 7, ' فإن قال هكذا : حسنا . كان سلام لعبدك . ولكن إن اغتاظ غيظا ، فاعلم أنه قد أعد الشر عنده '),
(3825, '1 Samuel', 9, 20, 8, ' فتعمل معروفا مع عبدك ، لأنك بعهد الرب أدخلت عبدك معك . وإن كان في إثم فاقتلني أنت ، ولماذا تأتي بي إلى أبيك '),
(3826, '1 Samuel', 9, 20, 9, ' فقال يوناثان : حاشا لك لأنه لو علمت أن الشر قد أعد عند أبي ليأتي عليك ، أفما كنت أخبرك به '),
(3827, '1 Samuel', 9, 20, 10, ' فقال داود ليوناثان : من يخبرني إن جاوبك أبوك شيئا قاسيا '),
(3828, '1 Samuel', 9, 20, 11, ' فقال يوناثان لداود : تعال نخرج إلى الحقل . فخرجا كلاهما إلى الحقل '),
(3829, '1 Samuel', 9, 20, 12, ' وقال يوناثان لداود : يارب إله إسرائيل ، متى اختبرت أبي مثل الآن غدا أو بعد غد ، فإن كان خير لداود ولم أرسل حينئذ فأخبره '),
(3830, '1 Samuel', 9, 20, 13, ' فهكذا يفعل الرب ليوناثان وهكذا يزيد . وإن استحسن أبي الشر نحوك ، فإني أخبرك وأطلقك فتذهب بسلام . وليكن الرب معك كما كان مع أبي '),
(3831, '1 Samuel', 9, 20, 14, ' ولا وأنا حي بعد تصنع معي إحسان الرب حتى لا أموت '),
(3832, '1 Samuel', 9, 20, 15, ' بل لا تقطع معروفك عن بيتي إلى الأبد ، ولا حين يقطع الرب أعداء داود جميعا عن وجه الأرض '),
(3833, '1 Samuel', 9, 20, 16, ' فعاهد يوناثان بيت داود وقال : ليطلب الرب من يد أعداء داود '),
(3834, '1 Samuel', 9, 29, 5, ' أليس هذا هو داود الذي غنين له بالرقص قائلات : ضرب شاول ألوفه وداود ربواته '),
(3835, '1 Samuel', 9, 29, 6, ' فدعا أخيش داود وقال له : حي هو الرب ، إنك أنت مستقيم ، وخروجك ودخولك معي في الجيش صالح في عيني لأني لم أجد فيك شرا من يوم جئت إلي إلى اليوم . وأما في أعين الأقطاب فلست بصالح '),
(3836, '1 Samuel', 9, 29, 7, ' فالآن ارجع واذهب بسلام ، ولا تفعل سوءا في أعين أقطاب الفلسطينيين '),
(3837, '1 Samuel', 9, 29, 8, ' فقال داود لأخيش : فماذا عملت ؟ وماذا وجدت في عبدك من يوم صرت أمامك إلى اليوم حتى لا آتي وأحارب أعداء سيدي الملك '),
(3838, '1 Samuel', 9, 29, 9, ' فأجاب أخيش وقال لداود : علمت أنك صالح في عيني كملاك الله . إلا إن رؤساء الفلسطينيين قالوا : لا يصعد معنا إلى الحرب '),
(3839, '1 Samuel', 9, 29, 10, ' والآن فبكر صباحا مع عبيد سيدك الذين جاءوا معك . وإذا بكرتم صباحا وأضاء لكم فاذهبوا '),
(3840, '1 Samuel', 9, 29, 11, ' فبكر داود هو ورجاله لكي يذهبوا صباحا ويرجعوا إلى أرض الفلسطينيين . وأما الفلسطينيون فصعدوا إلى يزرعيل '),
(3841, '1 Samuel', 9, 30, 1, ' ولما جاء داود ورجاله إلى صقلغ في اليوم الثالث ، كان العمالقة قد غزوا الجنوب وصقلغ ، وضربوا صقلغ وأحرقوها بالنار '),
(3842, '1 Samuel', 9, 30, 2, ' وسبوا النساء اللواتي فيها . لم يقتلوا أحدا لا صغيرا ولا كبيرا ، بل ساقوهم ومضوا في طريقهم '),
(3843, '1 Samuel', 9, 30, 3, ' فدخل داود ورجاله المدينة وإذا هي محرقة بالنار ، ونساؤهم وبنوهم وبناتهم قد سبوا '),
(3844, '1 Samuel', 9, 30, 4, ' فرفع داود والشعب الذين معه أصواتهم وبكوا حتى لم تبق لهم قوة للبكاء '),
(3845, '1 Samuel', 9, 30, 5, ' وسبيت امرأتا داود : أخينوعم اليزرعيلية وأبيجايل امرأة نابال الكرملي '),
(3846, '1 Samuel', 9, 30, 6, ' فتضايق داود جدا لأن الشعب قالوا برجمه ، لأن أنفس جميع الشعب كانت مرة كل واحد على بنيه وبناته . وأما داود فتشدد بالرب إلهه '),
(3847, '1 Samuel', 9, 30, 7, ' ثم قال داود لأبياثار الكاهن ابن أخيمالك : قدم إلي الأفود . فقدم أبياثار الأفود إلى داود '),
(3848, '1 Samuel', 9, 30, 8, ' فسأل داود من الرب قائلا : إذا لحقت هؤلاء الغزاة فهل أدركهم ؟  . فقال له : الحقهم فإنك تدرك وتنقذ '),
(3849, '1 Samuel', 9, 30, 9, ' فذهب داود هو والست مئة الرجل الذين معه وجاءوا إلى وادي البسور ، والمتخلفون وقفوا '),
(3850, '1 Samuel', 9, 30, 10, ' وأما داود فلحق هو وأربع مئة رجل ، ووقف مئتا رجل لأنهم أعيوا عن أن يعبروا وادي البسور '),
(3851, '1 Samuel', 9, 30, 11, ' فصادفوا رجلا مصريا في الحقل فأخذوه إلى داود ، وأعطوه خبزا فأكل وسقوه ماء '),
(3852, '1 Samuel', 9, 30, 12, ' وأعطوه قرصا من التين وعنقودين من الزبيب ، فأكل ورجعت روحه إليه ، لأنه لم يأكل خبزا ولا شرب ماء في ثلاثة أيام وثلاث ليال '),
(3853, '1 Samuel', 9, 30, 13, ' فقال له داود : لمن أنت ؟ ومن أين أنت ؟  . فقال : أنا غلام مصري عبد لرجل عماليقي ، وقد تركني سيدي لأني مرضت منذ ثلاثة أيام '),
(3854, '1 Samuel', 9, 30, 14, ' فإننا قد غزونا على جنوبي الكريتيين ، وعلى ما ليهوذا وعلى جنوبي كالب وأحرقنا صقلغ بالنار '),
(3855, '1 Samuel', 9, 30, 15, ' فقال له داود : هل تنزل بي إلى هؤلاء الغزاة ؟  . فقال : احلف لي بالله أنك لا تقتلني ولا تسلمني ليد سيدي ، فأنزل بك إلى هؤلاء الغزاة '),
(3856, '1 Samuel', 9, 30, 16, ' فنزل به وإذا بهم منتشرون على وجه كل الأرض ، يأكلون ويشربون ويرقصون بسبب جميع الغنيمة العظيمة التي أخذوا من أرض الفلسطينيين ومن أرض يهوذا '),
(3857, '1 Samuel', 9, 30, 17, ' فضربهم داود من العتمة إلى مساء غدهم ، ولم ينج منهم رجل إلا أربع مئة غلام الذين ركبوا جمالا وهربوا '),
(3858, '1 Samuel', 9, 30, 18, ' واستخلص داود كل ما أخذه عماليق ، وأنقذ داود امرأتيه '),
(3859, '1 Samuel', 9, 30, 19, ' ولم يفقد لهم شيء لا صغير ولا كبير ، ولا بنون ولا بنات ولا غنيمة ، ولا شيء من جميع ما أخذوا لهم ، بل رد داود الجميع '),
(3860, '1 Samuel', 9, 30, 20, ' وأخذ داود الغنم والبقر . ساقوها أمام تلك الماشية وقالوا : هذه غنيمة داود '),
(3861, '1 Samuel', 9, 30, 21, ' وجاء داود إلى مئتي الرجل الذين أعيوا عن الذهاب وراء داود ، فأرجعوهم في وادي البسور ، فخرجوا للقاء داود ولقاء الشعب الذين معه . فتقدم داود إلى القوم وسأل عن سلامتهم '),
(3862, '1 Samuel', 9, 30, 22, ' فأجاب كل رجل شرير ولئيم من الرجال الذين ساروا مع داود وقالوا : لأجل أنهم لم يذهبوا معنا لا نعطيهم من الغنيمة التي استخلصناها ، بل لكل رجل امرأته وبنيه ، فليقتادوهم وينطلقوا '),
(3863, '1 Samuel', 9, 30, 23, ' فقال داود : لا تفعلوا هكذا يا إخوتي ، لأن الرب قد أعطانا وحفظنا ودفع ليدنا الغزاة الذين جاءوا علينا '),
(3864, '1 Samuel', 9, 30, 24, ' ومن يسمع لكم في هذا الأمر ؟ لأنه كنصيب النازل إلى الحرب نصيب الذي يقيم عند الأمتعة ، فإنهم يقتسمون بالسوية '),
(3865, '1 Samuel', 9, 30, 25, ' وكان من ذلك اليوم فصاعدا أنه جعلها فريضة وقضاء لإسرائيل إلى هذا اليوم '),
(3866, '1 Samuel', 9, 30, 26, ' ولما جاء داود إلى صقلغ أرسل من الغنيمة إلى شيوخ يهوذا ، إلى أصحابه قائلا : هذه لكم بركة من غنيمة أعداء الرب '),
(3867, '1 Samuel', 9, 30, 27, ' إلى الذين في بيت إيل والذين في راموت الجنوب والذين في يتير '),
(3868, '1 Samuel', 9, 30, 28, ' وإلى الذين في عروعير والذين في سفموث والذين في أشتموع '),
(3869, '1 Samuel', 9, 30, 29, ' وإلى الذين في راخال والذين في مدن اليرحمئيليين والذين في مدن القينيين '),
(3870, '1 Samuel', 9, 30, 30, ' وإلى الذين في حرمة والذين في كور عاشان والذين في عتاك '),
(3871, '1 Samuel', 9, 30, 31, ' وإلى الذين في حبرون ، وإلى جميع الأماكن التي تردد فيها داود ورجاله '),
(3872, '1 Samuel', 9, 31, 1, ' وحارب الفلسطينيون إسرائيل ، فهرب رجال إسرائيل من أمام الفلسطينيين وسقطوا قتلى في جبل جلبوع '),
(3873, '1 Samuel', 9, 31, 2, ' فشد الفلسطينيون وراء شاول وبنيه ، وضرب الفلسطينيون يوناثان وأبيناداب وملكيشوع أبناء شاول '),
(3874, '1 Samuel', 9, 31, 3, ' واشتدت الحرب على شاول فأصابه الرماة رجال القسي ، فانجرح جدا من الرماة ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(3875, '1 Samuel', 9, 31, 4, ' فقال شاول لحامل سلاحه : استل سيفك واطعني به لئلا يأتي هؤلاء الغلف ويطعنوني ويقبحوني . فلم يشأ حامل سلاحه لأنه خاف جدا . فأخذ شاول السيف وسقط عليه '),
(3876, '1 Samuel', 9, 31, 5, ' ولما رأى حامل سلاحه أنه قد مات شاول ، سقط هو أيضا على سيفه ومات معه '),
(3877, '1 Samuel', 9, 31, 6, ' فمات شاول وبنوه الثلاثة وحامل سلاحه وجميع رجاله في ذلك اليوم معا '),
(3878, '1 Samuel', 9, 31, 7, ' ولما رأى رجال إسرائيل الذين في عبر الوادي والذين في عبر الأردن أن رجال إسرائيل قد هربوا ، وأن شاول وبنيه قد ماتوا ، تركوا المدن وهربوا . فأتى الفلسطينيون وسكنوا بها '),
(3879, '1 Samuel', 9, 31, 8, ' وفي الغد لما جاء الفلسطينيون ليعروا القتلى ، وجدوا شاول وبنيه الثلاثة ساقطين في جبل جلبوع '),
(3880, '1 Samuel', 9, 31, 9, ' فقطعوا رأسه ونزعوا سلاحه ، وأرسلوا إلى أرض الفلسطينيين في كل جهة لأجل التبشير في بيت أصنامهم وفي الشعب '),
(3881, '1 Samuel', 9, 31, 10, ' ووضعوا سلاحه في بيت عشتاروث ، وسمروا جسده على سور بيت شان '),
(3882, '1 Samuel', 9, 31, 11, ' ولما سمع سكان يابيش جلعاد بما فعل الفلسطينيون بشاول '),
(3883, '1 Samuel', 9, 31, 12, ' قام كل ذي بأس وساروا الليل كله ، وأخذوا جسد شاول وأجساد بنيه عن سور بيت شان ، وجاءوا بها إلى يابيش وأحرقوها هناك '),
(3884, '1 Samuel', 9, 31, 13, ' وأخذوا عظامهم ودفنوها تحت الأثلة في يابيش ، وصاموا سبعة أيام '),
(3885, '1 Samuel', 9, 20, 17, ' ثم عاد يوناثان واستحلف داود بمحبته له ، لأنه أحبه محبة نفسه '),
(3886, '1 Samuel', 9, 20, 18, ' وقال له يوناثان : غدا الشهر ، فتفتقد لأن موضعك يكون خاليا '),
(3887, '1 Samuel', 9, 20, 19, ' وفي اليوم الثالث تنزل سريعا وتأتي إلى الموضع الذي اختبأت فيه يوم العمل ، وتجلس بجانب حجر الافتراق '),
(3888, '1 Samuel', 9, 20, 20, ' وأنا أرمي ثلاثة سهام إلى جانبه كأني أرمي غرضا '),
(3889, '1 Samuel', 9, 20, 21, ' وحينئذ أرسل الغلام قائلا : اذهب التقط السهام . فإن قلت للغلام : هوذا السهام دونك فجائيا ، خذها . فتعال ، لأن لك سلاما . لا يوجد شيء ، حي هو الرب '),
(3890, '1 Samuel', 9, 20, 22, ' ولكن إن قلت هكذا للغلام : هوذا السهام دونك فصاعدا . فاذهب ، لأن الرب قد أطلقك '),
(3891, '1 Samuel', 9, 20, 23, ' وأما الكلام الذي تكلمنا به أنا وأنت ، فهوذا الرب بيني وبينك إلى الأبد '),
(3892, '1 Samuel', 9, 20, 24, ' فاختبأ داود في الحقل . وكان الشهر ، فجلس الملك على الطعام ليأكل '),
(3893, '1 Samuel', 9, 20, 25, ' فجلس الملك في موضعه حسب كل مرة على مجلس عند الحائط . وقام يوناثان وجلس أبنير إلى جانب شاول ، وخلا موضع داود '),
(3894, '1 Samuel', 9, 20, 26, ' ولم يقل شاول شيئا في ذلك اليوم ، لأنه قال : لعله عارض . غير طاهر هو . إنه ليس طاهرا '),
(3895, '1 Samuel', 9, 20, 27, ' وكان في الغد الثاني من الشهر أن موضع داود خلا ، فقال شاول ليوناثان ابنه : لماذا لم يأت ابن يسى إلى الطعام لا أمس ولا اليوم '),
(3896, '1 Samuel', 9, 20, 28, ' فأجاب يوناثان شاول : إن داود طلب مني أن يذهب إلى بيت لحم '),
(3897, '1 Samuel', 9, 20, 29, ' وقال : أطلقني لأن عندنا ذبيحة عشيرة في المدينة ، وقد أوصاني أخي بذلك . والآن إن وجدت نعمة في عينيك فدعني أفلت وأرى إخوتي . لذلك لم يأت إلى مائدة الملك '),
(3898, '1 Samuel', 9, 20, 30, ' فحمي غضب شاول على يوناثان وقال له : يا ابن المتعوجة المتمردة ، أما علمت أنك قد اخترت ابن يسى لخزيك وخزي عورة أمك '),
(3899, '1 Samuel', 9, 20, 31, ' لأنه ما دام ابن يسى حيا على الأرض لا تثبت أنت ولا مملكتك . والآن أرسل وأت به إلي لأنه ابن الموت هو '),
(3900, '1 Samuel', 9, 20, 32, ' فأجاب يوناثان شاول أباه وقال له : لماذا يقتل ؟ ماذا عمل '),
(3901, '1 Samuel', 9, 20, 33, ' فصابى شاول الرمح نحوه ليطعنه ، فعلم يوناثان أن أباه قد عزم على قتل داود '),
(3902, '1 Samuel', 9, 20, 34, ' فقام يوناثان عن المائدة بحمو غضب ولم يأكل خبزا في اليوم الثاني من الشهر ، لأنه اغتم على داود ، لأن أباه قد أخزاه '),
(3903, '1 Samuel', 9, 20, 35, ' وكان في الصباح أن يوناثان خرج إلى الحقل إلى ميعاد داود ، وغلام صغير معه '),
(3904, '1 Samuel', 9, 20, 36, ' وقال لغلامه : اركض التقط السهام التي أنا راميها . وبينما الغلام راكض رمى السهم حتى جاوزه '),
(3905, '1 Samuel', 9, 20, 37, ' ولما جاء الغلام إلى موضع السهم الذي رماه يوناثان ، نادى يوناثان وراء الغلام وقال : أليس السهم دونك فصاعدا '),
(3906, '1 Samuel', 9, 20, 38, ' ونادى يوناثان وراء الغلام قائلا : اعجل . أسرع . لا تقف . فالتقط غلام يوناثان السهم وجاء إلى سيده '),
(3907, '1 Samuel', 9, 20, 39, ' والغلام لم يكن يعلم شيئا ، وأما يوناثان وداود فكانا يعلمان الأمر '),
(3908, '1 Samuel', 9, 20, 40, ' فأعطى يوناثان سلاحه للغلام الذي له وقال له : اذهب . ادخل به إلى المدينة '),
(3909, '1 Samuel', 9, 20, 41, ' الغلام ذهب وداود قام من جانب الجنوب وسقط على وجهه إلى الأرض وسجد ثلاث مرات . وقبل كل منهما صاحبه ، وبكى كل منهما مع صاحبه حتى زاد داود '),
(3910, '1 Samuel', 9, 20, 42, ' فقال يوناثان لداود : اذهب بسلام لأننا كلينا قد حلفنا باسم الرب قائلين : الرب يكون بيني وبينك وبين نسلي ونسلك إلى الأبد . فقام وذهب ، وأما يوناثان فجاء إلى المدينة '),
(3911, '1 Samuel', 9, 21, 1, ' فجاء داود إلى نوب إلى أخيمالك الكاهن ، فاضطرب أخيمالك عند لقاء داود وقال له : لماذا أنت وحدك وليس معك أحد '),
(3912, '1 Samuel', 9, 21, 2, ' فقال داود لأخيمالك الكاهن : إن الملك أمرني بشيء وقال لي : لا يعلم أحد شيئا من الأمر الذي أرسلتك فيه وأمرتك به ، وأما الغلمان فقد عينت لهم الموضع الفلاني والفلاني '),
(3913, '1 Samuel', 9, 21, 3, ' والآن فماذا يوجد تحت يدك ؟ أعط خمس خبزات في يدي أو الموجود '),
(3914, '1 Samuel', 9, 21, 4, ' فأجاب الكاهن داود وقال : لا يوجد خبز محلل تحت يدي ، ولكن يوجد خبز مقدس إذا كان الغلمان قد حفظوا أنفسهم لا سيما من النساء '),
(3915, '1 Samuel', 9, 21, 5, ' فأجاب داود الكاهن وقال له : إن النساء قد منعت عنا منذ أمس وما قبله عند خروجي ، وأمتعة الغلمان مقدسة . وهو على نوع محلل ، واليوم أيضا يتقدس بالآنية '),
(3916, '1 Samuel', 9, 21, 6, ' فأعطاه الكاهن المقدس ، لأنه لم يكن هناك خبز إلا خبز الوجوه المرفوع من أمام الرب لكي يوضع خبز سخن في يوم أخذه '),
(3917, '1 Samuel', 9, 21, 7, ' وكان هناك رجل من عبيد شاول في ذلك اليوم محصورا أمام الرب ، اسمه دواغ الأدومي رئيس رعاة شاول '),
(3918, '1 Samuel', 9, 21, 8, ' وقال داود لأخيمالك : أفما يوجد هنا تحت يدك رمح أو سيف ، لأني لم آخذ بيدي سيفي ولا سلاحي لأن أمر الملك كان معجلا '),
(3919, '1 Samuel', 9, 21, 9, ' فقال الكاهن : إن سيف جليات الفلسطيني الذي قتلته في وادي البطم ، ها هو ملفوف في ثوب خلف الأفود ، فإن شئت أن تأخذه فخذه ، لأنه ليس آخر سواه هنا . فقال داود : لا يوجد مثله ، أعطني إياه '),
(3920, '1 Samuel', 9, 21, 10, ' وقام داود وهرب في ذلك اليوم من أمام شاول وجاء إلى أخيش ملك جت '),
(3921, '1 Samuel', 9, 21, 11, ' فقال عبيد أخيش له : أليس هذا داود ملك الأرض ؟ أليس لهذا كن يغنين في الرقص قائلات : ضرب شاول ألوفه وداود ربواته '),
(3922, '1 Samuel', 9, 21, 12, ' فوضع داود هذا الكلام في قلبه وخاف جدا من أخيش ملك جت '),
(3923, '1 Samuel', 9, 21, 13, ' فغير عقله في أعينهم ، وتظاهر بالجنون بين أيديهم ، وأخذ يخربش على مصاريع الباب ويسيل ريقه على لحيته '),
(3924, '1 Samuel', 9, 21, 14, ' فقال أخيش لعبيده : هوذا ترون الرجل مجنونا ، فلماذا تأتون به إلي '),
(3925, '1 Samuel', 9, 21, 15, ' ألعلي محتاج إلى مجانين حتى أتيتم بهذا ليتجنن علي ؟ أهذا يدخل بيتي '),
(3926, '1 Samuel', 9, 22, 1, ' فذهب داود من هناك ونجا إلى مغارة عدلام . فلما سمع إخوته وجميع بيت أبيه نزلوا إليه إلى هناك '),
(3927, '1 Samuel', 9, 22, 2, ' واجتمع إليه كل رجل متضايق ، وكل من كان عليه دين ، وكل رجل مر النفس ، فكان عليهم رئيسا . وكان معه نحو أربع مئة رجل '),
(3928, '1 Samuel', 9, 22, 3, ' وذهب داود من هناك إلى مصفاة موآب ، وقال لملك موآب : ليخرج أبي وأمي إليكم حتى أعلم ماذا يصنع لي الله '),
(3929, '1 Samuel', 9, 22, 4, ' فودعهما عند ملك موآب ، فأقاما عنده كل أيام إقامة داود في الحصن '),
(3930, '1 Samuel', 9, 22, 5, ' فقال جاد النبي لداود : لا تقم في الحصن . اذهب وادخل أرض يهوذا . فذهب داود وجاء إلى وعر حارث '),
(3931, '1 Samuel', 9, 22, 6, ' وسمع شاول أنه قد اشتهر داود والرجال الذين معه . وكان شاول مقيما في جبعة تحت الأثلة في الرامة ورمحه بيده ، وجميع عبيده وقوفا لديه '),
(3932, '1 Samuel', 9, 22, 7, ' فقال شاول لعبيده الواقفين لديه : اسمعوا يا بنيامينيون : هل يعطيكم جميعكم ابن يسى حقولا وكروما ؟ وهل يجعلكم جميعكم رؤساء ألوف ورؤساء مئات '),
(3933, '1 Samuel', 9, 22, 8, ' حتى فتنتم كلكم علي ، وليس من يخبرني بعهد ابني مع ابن يسى ، وليس منكم من يحزن علي أو يخبرني بأن ابني قد أقام عبدي علي كمينا كهذا اليوم '),
(3934, '1 Samuel', 9, 22, 9, ' فأجاب دواغ الأدومي الذي كان موكلا على عبيد شاول وقال : قد رأيت ابن يسى آتيا إلى نوب إلى أخيمالك بن أخيطوب '),
(3935, '1 Samuel', 9, 22, 10, ' فسأل له من الرب وأعطاه زادا . وسيف جليات الفلسطيني أعطاه إياه '),
(3936, '1 Samuel', 9, 22, 11, ' فأرسل الملك واستدعى أخيمالك بن أخيطوب الكاهن وجميع بيت أبيه الكهنة الذين في نوب ، فجاءوا كلهم إلى الملك '),
(3937, '1 Samuel', 9, 22, 12, ' فقال شاول : اسمع يا ابن أخيطوب . فقال : هأنذا يا سيدي '),
(3938, '1 Samuel', 9, 22, 13, ' فقال له شاول : لماذا فتنتم علي أنت وابن يسى بإعطائك إياه خبزا وسيفا ، وسألت له من الله ليقوم علي كامنا كهذا اليوم '),
(3939, '1 Samuel', 9, 22, 14, ' فأجاب أخيمالك الملك وقال : ومن من جميع عبيدك مثل داود ، أمين وصهر الملك وصاحب سرك ومكرم في بيتك '),
(3940, '1 Samuel', 9, 22, 15, ' فهل اليوم ابتدأت أسأل له من الله ؟ حاشا لي لا ينسب الملك شيئا لعبده ولا لجميع بيت أبي ، لأن عبدك لم يعلم شيئا من كل هذا صغيرا أو كبيرا '),
(3941, '1 Samuel', 9, 22, 16, ' فقال الملك : موتا تموت يا أخيمالك ، أنت وكل بيت أبيك '),
(3942, '1 Samuel', 9, 22, 17, ' وقال الملك للسعاة الواقفين لديه : دوروا واقتلوا كهنة الرب ، لأن يدهم أيضا مع داود ، ولأنهم علموا أنه هارب ولم يخبروني . فلم يرض عبيد الملك أن يمدوا أيديهم ليقعوا بكهنة الرب '),
(3943, '1 Samuel', 9, 22, 18, ' فقال الملك لدواغ : در أنت وقع بالكهنة . فدار دواغ الأدومي ووقع هو بالكهنة ، وقتل في ذلك اليوم خمسة وثمانين رجلا لابسي أفود كتان '),
(3944, '1 Samuel', 9, 22, 19, ' وضرب نوب مدينة الكهنة بحد السيف . الرجال والنساء والأطفال والرضعان والثيران والحمير والغنم بحد السيف '),
(3945, '1 Samuel', 9, 22, 20, ' فنجا ولد واحد لأخيمالك بن أخيطوب اسمه أبياثار وهرب إلى داود '),
(3946, '1 Samuel', 9, 22, 21, ' وأخبر أبياثار داود بأن شاول قد قتل كهنة الرب '),
(3947, '1 Samuel', 9, 22, 22, ' فقال داود لأبياثار : علمت في ذلك اليوم الذي فيه كان دواغ الأدومي هناك ، أنه يخبر شاول . أنا سببت لجميع أنفس بيت أبيك '),
(3948, '1 Samuel', 9, 22, 23, ' أقم معي . لا تخف ، لأن الذي يطلب نفسي يطلب نفسك ، ولكنك عندي محفوظ '),
(3949, '1 Samuel', 9, 23, 1, ' فأخبروا داود قائلين : هوذا الفلسطينيون يحاربون قعيلة وينهبون البيادر '),
(3950, '1 Samuel', 9, 23, 2, ' فسأل داود من الرب قائلا : أأذهب وأضرب هؤلاء الفلسطينيين ؟  . فقال الرب لداود : اذهب واضرب الفلسطينيين وخلص قعيلة '),
(3951, '1 Samuel', 9, 23, 3, ' فقال رجال داود له : ها نحن ههنا في يهوذا خائفون ، فكم بالحري إذا ذهبنا إلى قعيلة ضد صفوف الفلسطينيين '),
(3952, '1 Samuel', 9, 23, 4, ' فعاد أيضا داود وسأل من الرب ، فأجابه الرب وقال : قم انزل إلى قعيلة ، فإني أدفع الفلسطينيين ليدك '),
(3953, '1 Samuel', 9, 23, 5, ' فذهب داود ورجاله إلى قعيلة ، وحارب الفلسطينيين وساق مواشيهم ، وضربهم ضربة عظيمة ، وخلص داود سكان قعيلة '),
(3954, '1 Samuel', 9, 23, 6, ' وكان لما هرب أبياثار بن أخيمالك إلى داود إلى قعيلة نزل وبيده أفود '),
(3955, '1 Samuel', 9, 23, 7, ' فأخبر شاول بأن داود قد جاء إلى قعيلة ، فقال شاول : قد نبذه الله إلى يدي ، لأنه قد أغلق عليه بالدخول إلى مدينة لها أبواب وعوارض '),
(3956, '1 Samuel', 9, 23, 8, ' ودعا شاول جميع الشعب للحرب للنزول إلى قعيلة لمحاصرة داود ورجاله '),
(3957, '1 Samuel', 9, 23, 9, ' فلما عرف داود أن شاول منشئ عليه الشر ، قال لأبياثار الكاهن قدم الأفود '),
(3958, '1 Samuel', 9, 23, 10, ' ثم قال داود : يارب إله إسرائيل ، إن عبدك قد سمع بأن شاول يحاول أن يأتي إلى قعيلة لكي يخرب المدينة بسببي '),
(3959, '1 Samuel', 9, 23, 11, ' فهل يسلمني أهل قعيلة ليده ؟ هل ينزل شاول كما سمع عبدك ؟ يارب إله إسرائيل ، أخبر عبدك . فقال الرب : ينزل '),
(3960, '1 Samuel', 9, 23, 12, ' فقال داود : هل يسلمني أهل قعيلة مع رجالي ليد شاول ؟  . فقال الرب : يسلمون '),
(3961, '1 Samuel', 9, 23, 13, ' فقام داود ورجاله ، نحو ست مئة رجل ، وخرجوا من قعيلة وذهبوا حيثما ذهبوا . فأخبر شاول بأن داود قد أفلت من قعيلة ، فعدل عن الخروج '),
(3962, '1 Samuel', 9, 23, 14, ' وأقام داود في البرية في الحصون ومكث في الجبل في برية زيف . وكان شاول يطلبه كل الأيام ، ولكن لم يدفعه الله ليده '),
(3963, '1 Samuel', 9, 23, 15, ' فرأى داود أن شاول قد خرج يطلب نفسه . وكان داود في برية زيف في الغاب '),
(3964, '1 Samuel', 9, 23, 16, ' فقام يوناثان بن شاول وذهب إلى داود إلى الغاب وشدد يده بالله '),
(3965, '1 Samuel', 9, 23, 17, ' وقال له : لا تخف لأن يد شاول أبي لا تجدك ، وأنت تملك على إسرائيل ، وأنا أكون لك ثانيا . وشاول أبي أيضا يعلم ذلك '),
(3966, '1 Samuel', 9, 23, 18, ' فقطعا كلاهما عهدا أمام الرب . وأقام داود في الغاب ، وأما يوناثان فمضى إلى بيته '),
(3967, '1 Samuel', 9, 23, 19, ' فصعد الزيفيون إلى شاول إلى جبعة قائلين : أليس داود مختبئا عندنا في حصون في الغاب ، في تل حخيلة التي إلى يمين القفر '),
(3968, '1 Samuel', 9, 23, 20, ' فالآن حسب كل شهوة نفسك أيها الملك في النزول انزل ، وعلينا أن نسلمه ليد الملك '),
(3969, '1 Samuel', 9, 23, 21, ' فقال شاول : مباركون أنتم من الرب لأنكم قد أشفقتم علي '),
(3970, '1 Samuel', 9, 23, 22, ' فاذهبوا أكدوا أيضا ، واعلموا وانظروا مكانه حيث تكون رجله ومن رآه هناك ، لأنه قيل لي : إنه مكرا يمكر '),
(3971, '1 Samuel', 9, 23, 23, ' فانظروا واعلموا جميع المختبآت التي يختبئ فيها ، ثم ارجعوا إلي على تأكيد ، فأسير معكم . ويكون إذا وجد في الأرض ، أني أفتش عليه بجميع ألوف يهوذا '),
(3972, '1 Samuel', 9, 23, 24, ' فقاموا وذهبوا إلى زيف قدام شاول . وكان داود ورجاله في برية معون ، في السهل عن يمين القفر '),
(3973, '1 Samuel', 9, 23, 25, ' وذهب شاول ورجاله للتفتيش . فأخبروا داود ، فنزل إلى الصخر وأقام في برية معون . فلما سمع شاول تبع داود إلى برية معون '),
(3974, '1 Samuel', 9, 23, 26, ' فذهب شاول عن جانب الجبل من هنا ، وداود ورجاله عن جانب الجبل من هناك . وكان داود يفر في الذهاب من أمام شاول ، وكان شاول ورجاله يحاوطون داود ورجاله لكي يأخذوهم '),
(3975, '1 Samuel', 9, 23, 27, ' فجاء رسول إلى شاول يقول : أسرع واذهب لأن الفلسطينيين قد اقتحموا الأرض '),
(3976, '1 Samuel', 9, 23, 28, ' فرجع شاول عن اتباع داود ، وذهب للقاء الفلسطينيين . لذلك دعي ذلك الموضع صخرة الزلقات '),
(3977, '1 Samuel', 9, 23, 29, ' وصعد داود من هناك وأقام في حصون عين جدي '),
(3978, '1 Samuel', 9, 24, 1, ' ولما رجع شاول من وراء الفلسطينيين أخبروه قائلين : هوذا داود في برية عين جدي '),
(3979, '1 Samuel', 9, 24, 2, ' فأخذ شاول ثلاثة آلاف رجل منتخبين من جميع إسرائيل وذهب يطلب داود ورجاله على صخور الوعول '),
(3980, '1 Samuel', 9, 24, 3, ' وجاء إلى صير الغنم التي في الطريق . وكان هناك كهف فدخل شاول لكي يغطي رجليه ، وداود ورجاله كانوا جلوسا في مغابن الكهف '),
(3981, '1 Samuel', 9, 24, 4, ' فقال رجال داود له : هوذا اليوم الذي قال لك عنه الرب : هأنذا أدفع عدوك ليدك فتفعل به ما يحسن في عينيك . فقام داود وقطع طرف جبة شاول سرا '),
(3982, '1 Samuel', 9, 24, 5, ' وكان بعد ذلك أن قلب داود ضربه على قطعه طرف جبة شاول '),
(3983, '1 Samuel', 9, 24, 6, ' فقال لرجاله : حاشا لي من قبل الرب أن أعمل هذا الأمر بسيدي ، بمسيح الرب ، فأمد يدي إليه لأنه مسيح الرب هو '),
(3984, '1 Samuel', 9, 24, 7, ' فوبخ داود رجاله بالكلام ، ولم يدعهم يقومون على شاول . وأما شاول فقام من الكهف وذهب في طريقه '),
(3985, '1 Samuel', 9, 24, 8, ' ثم قام داود بعد ذلك وخرج من الكهف ونادى وراء شاول قائلا : يا سيدي الملك . ولما التفت شاول إلى ورائه ، خر داود على وجهه إلى الأرض وسجد '),
(3986, '1 Samuel', 9, 24, 9, ' وقال داود لشاول : لماذا تسمع كلام الناس القائلين : هوذا داود يطلب أذيتك '),
(3987, '1 Samuel', 9, 24, 10, ' هوذا قد رأت عيناك اليوم هذا كيف دفعك الرب اليوم ليدي في الكهف ، وقيل لي أن أقتلك ، ولكنني أشفقت عليك وقلت : لا أمد يدي إلى سيدي ، لأنه مسيح الرب هو '),
(3988, '1 Samuel', 9, 24, 11, ' فانظر يا أبي ، انظر أيضا طرف جبتك بيدي . فمن قطعي طرف جبتك وعدم قتلي إياك اعلم وانظر أنه ليس في يدي شر ولا جرم ، ولم أخطئ إليك ، وأنت تصيد نفسي لتأخذها '),
(3989, '1 Samuel', 9, 24, 12, ' يقضي الرب بيني وبينك وينتقم لي الرب منك ، ولكن يدي لا تكون عليك '),
(3990, '1 Samuel', 9, 24, 13, ' كما يقول مثل القدماء : من الأشرار يخرج شر . ولكن يدي لا تكون عليك '),
(3991, '1 Samuel', 9, 24, 14, ' وراء من خرج ملك إسرائيل ؟ وراء من أنت مطارد ؟ وراء كلب ميت وراء برغوث واحد '),
(3992, '1 Samuel', 9, 24, 15, ' فيكون الرب الديان ويقضي بيني وبينك ، ويرى ويحاكم محاكمتي ، وينقذني من يدك '),
(3993, '1 Samuel', 9, 24, 16, ' فلما فرغ داود من التكلم بهذا الكلام إلى شاول ، قال شاول : أهذا صوتك يا ابني داود ؟  . ورفع شاول صوته وبكى '),
(3994, '1 Samuel', 9, 24, 17, ' ثم قال لداود : أنت أبر مني ، لأنك جازيتني خيرا وأنا جازيتك شرا '),
(3995, '1 Samuel', 9, 24, 18, ' وقد أظهرت اليوم أنك عملت بي خيرا ، لأن الرب قد دفعني بيدك ولم تقتلني '),
(3996, '1 Samuel', 9, 24, 19, ' فإذا وجد رجل عدوه ، فهل يطلقه في طريق خير ؟ فالرب يجازيك خيرا عما فعلته لي اليوم هذا '),
(3997, '1 Samuel', 9, 24, 20, ' والآن فإني علمت أنك تكون ملكا وتثبت بيدك مملكة إسرائيل '),
(3998, '1 Samuel', 9, 24, 21, ' فاحلف لي الآن بالرب إنك لا تقطع نسلي من بعدي ، ولا تبيد اسمي من بيت أبي '),
(3999, '1 Samuel', 9, 24, 22, ' فحلف داود لشاول . ثم ذهب شاول إلى بيته ، وأما داود ورجاله فصعدوا إلى الحصن '),
(4000, '1 Samuel', 9, 25, 1, ' ومات صموئيل ، فاجتمع جميع إسرائيل وندبوه ودفنوه في بيته في الرامة . وقام داود ونزل إلى برية فاران '),
(4001, '1 Samuel', 9, 25, 2, ' وكان رجل في معون ، وأملاكه في الكرمل ، وكان الرجل عظيما جدا وله ثلاثة آلاف من الغنم وألف من المعز ، وكان يجز غنمه في الكرمل '),
(4002, '1 Samuel', 9, 25, 3, ' واسم الرجل نابال واسم امرأته أبيجايل . وكانت المرأة جيدة الفهم وجميلة الصورة ، وأما الرجل فكان قاسيا ورديء الأعمال ، وهو كالبي '),
(4003, '1 Samuel', 9, 25, 4, ' فسمع داود في البرية أن نابال يجز غنمه '),
(4004, '1 Samuel', 9, 25, 5, ' فأرسل داود عشرة غلمان ، وقال داود للغلمان : اصعدوا إلى الكرمل وادخلوا إلى نابال واسألوا باسمي عن سلامته '),
(4005, '1 Samuel', 9, 25, 6, ' وقولوا هكذا : حييت وأنت سالم ، وبيتك سالم ، وكل مالك سالم '),
(4006, '1 Samuel', 9, 25, 7, ' والآن قد سمعت أن عندك جزازين . حين كان رعاتك معنا ، لم نؤذهم ولم يفقد لهم شيء كل الأيام التي كانوا فيها في الكرمل '),
(4007, '1 Samuel', 9, 25, 8, ' اسأل غلمانك فيخبروك . فليجد الغلمان نعمة في عينيك لأننا قد جئنا في يوم طيب ، فأعط ما وجدته يدك لعبيدك ولابنك داود '),
(4008, '1 Samuel', 9, 25, 9, ' فجاء الغلمان وكلموا نابال حسب كل هذا الكلام باسم داود وكفوا '),
(4009, '1 Samuel', 9, 25, 10, ' فأجاب نابال عبيد داود وقال : من هو داود ؟ ومن هو ابن يسى ؟ قد كثر اليوم العبيد الذين يقحصون كل واحد من أمام سيده '),
(4010, '1 Samuel', 9, 25, 11, ' أآخذ خبزي ومائي وذبيحي الذي ذبحت لجازي وأعطيه لقوم لا أعلم من أين هم '),
(4011, '1 Samuel', 9, 25, 12, ' فتحول غلمان داود إلى طريقهم ورجعوا وجاءوا وأخبروه حسب كل هذا الكلام '),
(4012, '1 Samuel', 9, 25, 13, ' فقال داود لرجاله : ليتقلد كل واحد منكم سيفه . فتقلد كل واحد سيفه ، وتقلد داود أيضا سيفه . وصعد وراء داود نحو أربع مئة رجل ، ومكث مئتان مع الأمتعة '),
(4013, '1 Samuel', 9, 25, 14, ' فأخبر أبيجايل امرأة نابال غلام من الغلمان قائلا : هوذا داود أرسل رسلا من البرية ليباركوا سيدنا فثار عليهم '),
(4014, '1 Samuel', 9, 25, 15, ' والرجال محسنون إلينا جدا ، فلم نؤذ ولا فقد منا شيء كل أيام ترددنا معهم ونحن في الحقل '),
(4015, '1 Samuel', 9, 25, 16, ' كانوا سورا لنا ليلا ونهارا كل الأيام التي كنا فيها معهم نرعى الغنم '),
(4016, '1 Samuel', 9, 25, 17, ' والآن اعلمي وانظري ماذا تعملين ، لأن الشر قد أعد على سيدنا وعلى بيته ، وهو ابن لئيم لا يمكن الكلام معه '),
(4017, '1 Samuel', 9, 25, 18, ' فبادرت أبيجايل وأخذت مئتي رغيف خبز ، وزقي خمر ، وخمسة خرفان مهيأة ، وخمس كيلات من الفريك ، ومئتي عنقود من الزبيب ، ومئتي قرص من التين ، ووضعتها على الحمير '),
(4018, '1 Samuel', 9, 25, 19, ' وقالت لغلمانها : اعبروا قدامي . هأنذا جائية وراءكم . ولم تخبر رجلها نابال '),
(4019, '1 Samuel', 9, 25, 20, ' وفيما هي راكبة على الحمار ونازلة في سترة الجبل ، إذا بداود ورجاله منحدرون لاستقبالها ، فصادفتهم '),
(4020, '1 Samuel', 9, 25, 21, ' وقال داود : إنما باطلا حفظت كل ما لهذا في البرية ، فلم يفقد من كل ما له شيء ، فكافأني شرا بدل خير '),
(4021, '1 Samuel', 9, 25, 22, ' هكذا يصنع الله لأعداء داود وهكذا يزيد ، إن أبقيت من كل ما له إلى ضوء الصباح بائلا بحائط '),
(4022, '1 Samuel', 9, 25, 23, ' ولما رأت أبيجايل داود أسرعت ونزلت عن الحمار ، وسقطت أمام داود على وجهها وسجدت إلى الأرض '),
(4023, '1 Samuel', 9, 25, 24, ' وسقطت على رجليه وقالت : علي أنا يا سيدي هذا الذنب ، ودع أمتك تتكلم في أذنيك واسمع كلام أمتك '),
(4024, '1 Samuel', 9, 25, 25, ' لا يضعن سيدي قلبه على الرجل اللئيم هذا ، على نابال ، لأن كاسمه هكذا هو . نابال اسمه والحماقة عنده . وأنا أمتك لم أر غلمان سيدي الذين أرسلتهم '),
(4025, '1 Samuel', 9, 25, 26, ' والآن يا سيدي ، حي هو الرب ، وحية هي نفسك ، إن الرب قد منعك عن إتيان الدماء وانتقام يدك لنفسك . والآن فليكن كنابال أعداؤك والذين يطلبون الشر لسيدي '),
(4026, '1 Samuel', 9, 25, 27, ' والآن هذه البركة التي أتت بها جاريتك إلى سيدي فلتعط للغلمان السائرين وراء سيدي '),
(4027, '1 Samuel', 9, 25, 28, ' واصفح عن ذنب أمتك لأن الرب يصنع لسيدي بيتا أمينا ، لأن سيدي يحارب حروب الرب ، ولم يوجد فيك شر كل أيامك '),
(4028, '1 Samuel', 9, 25, 29, ' وقد قام رجل ليطاردك ويطلب نفسك ، ولكن نفس سيدي لتكن محزومة في حزمة الحياة مع الرب إلهك . وأما نفس أعدائك فليرم بها كما من وسط كفة المقلاع '),
(4029, '1 Samuel', 9, 25, 30, ' ويكون عندما يصنع الرب لسيدي حسب كل ما تكلم به من الخير من أجلك ، ويقيمك رئيسا على إسرائيل '),
(4030, '1 Samuel', 9, 25, 31, ' أنه لا تكون لك هذه مصدمة ومعثرة قلب لسيدي ، أنك قد سفكت دما عفوا ، أو أن سيدي قد انتقم لنفسه . وإذا أحسن الرب إلى سيدي فاذكر أمتك '),
(4031, '1 Samuel', 9, 25, 32, ' فقال داود لأبيجايل : مبارك الرب إله إسرائيل الذي أرسلك هذا اليوم لاستقبالي '),
(4032, '1 Samuel', 9, 25, 33, ' ومبارك عقلك ، ومباركة أنت ، لأنك منعتني اليوم من إتيان الدماء وانتقام يدي لنفسي '),
(4033, '1 Samuel', 9, 25, 34, ' ولكن حي هو الرب إله إسرائيل الذي منعني عن أذيتك ، إنك لو لم تبادري وتأتي لاستقبالي ، لما أبقي لنابال إلى ضوء الصباح بائل بحائط '),
(4034, '1 Samuel', 9, 25, 35, ' فأخذ داود من يدها ما أتت به إليه وقال لها : اصعدي بسلام إلى بيتك . انظري . قد سمعت لصوتك ورفعت وجهك '),
(4035, '1 Samuel', 9, 25, 36, ' فجاءت أبيجايل إلى نابال وإذا وليمة عنده في بيته كوليمة ملك . وكان نابال قد طاب قلبه وكان سكران جدا ، فلم تخبره بشيء صغير أو كبير إلى ضوء الصباح '),
(4036, '1 Samuel', 9, 25, 37, ' وفي الصباح عند خروج الخمر من نابال أخبرته امرأته بهذا الكلام ، فمات قلبه داخله وصار كحجر '),
(4037, '1 Samuel', 9, 25, 38, ' وبعد نحو عشرة أيام ضرب الرب نابال فمات '),
(4038, '1 Samuel', 9, 25, 39, ' فلما سمع داود أن نابال قد مات قال : مبارك الرب الذي انتقم نقمة تعييري من يد نابال ، وأمسك عبده عن الشر ، ورد الرب شر نابال على رأسه . وأرسل داود وتكلم مع أبيجايل ليتخذها له امرأة '),
(4039, '1 Samuel', 9, 25, 40, ' فجاء عبيد داود إلى أبيجايل إلى الكرمل وكلموها قائلين : إن داود قد أرسلنا إليك لكي نتخذك له امرأة '),
(4040, '1 Samuel', 9, 25, 41, ' فقامت وسجدت على وجهها إلى الأرض وقالت : هوذا أمتك جارية لغسل أرجل عبيد سيدي '),
(4041, '1 Samuel', 9, 25, 42, ' ثم بادرت وقامت أبيجايل وركبت الحمار مع خمس فتيات لها ذاهبات وراءها ، وسارت وراء رسل داود وصارت له امرأة '),
(4042, '1 Samuel', 9, 25, 43, ' ثم أخذ داود أخينوعم من يزرعيل فكانتا له كلتاهما امرأتين '),
(4043, '1 Samuel', 9, 25, 44, ' فأعطى شاول ميكال ابنته امرأة داود لفلطي بن لايش الذي من جليم '),
(4044, '1 Samuel', 9, 26, 1, ' ثم جاء الزيفيون إلى شاول إلى جبعة قائلين : أليس داود مختفيا في تل حخيلة الذي مقابل القفر '),
(4045, '1 Samuel', 9, 26, 2, ' فقام شاول ونزل إلى برية زيف ومعه ثلاثة آلاف رجل منتخبي إسرائيل لكي يفتش على داود في برية زيف '),
(4046, '1 Samuel', 9, 26, 3, ' ونزل شاول في تل حخيلة الذي مقابل القفر على الطريق . وكان داود مقيما في البرية . فلما رأى أن شاول قد جاء وراءه إلى البرية '),
(4047, '1 Samuel', 9, 26, 4, ' أرسل داود جواسيس وعلم باليقين أن شاول قد جاء '),
(4048, '1 Samuel', 9, 26, 5, ' فقام داود وجاء إلى المكان الذي نزل فيه شاول ، ونظر داود المكان الذي اضطجع فيه شاول وأبنير بن نير رئيس جيشه . وكان شاول مضطجعا عند المتراس والشعب نزول حواليه '),
(4049, '1 Samuel', 9, 26, 6, ' فأجاب داود وكلم أخيمالك الحثي وأبيشاي ابن صروية أخا يوآب قائلا : من ينزل معي إلى شاول إلى المحلة ؟  . فقال أبيشاي : أنا أنزل معك '),
(4050, '1 Samuel', 9, 26, 7, ' فجاء داود وأبيشاي إلى الشعب ليلا وإذا بشاول مضطجع نائم عند المتراس ، ورمحه مركوز في الأرض عند رأسه ، وأبنير والشعب مضطجعون حواليه '),
(4051, '1 Samuel', 9, 26, 8, ' فقال أبيشاي لداود : قد حبس الله اليوم عدوك في يدك . فدعني الآن أضربه بالرمح إلى الأرض دفعة واحدة ولا أثني عليه '),
(4052, '1 Samuel', 9, 26, 9, ' فقال داود لأبيشاي : لا تهلكه ، فمن الذي يمد يده إلى مسيح الرب ويتبرأ '),
(4053, '1 Samuel', 9, 26, 10, ' وقال داود : حي هو الرب ، إن الرب سوف يضربه ، أو يأتي يومه فيموت ، أو ينزل إلى الحرب ويهلك '),
(4054, '1 Samuel', 9, 26, 11, ' حاشا لي من قبل الرب أن أمد يدي إلى مسيح الرب والآن فخذ الرمح الذي عند رأسه وكوز الماء وهلم '),
(4055, '1 Samuel', 9, 26, 12, ' فأخذ داود الرمح وكوز الماء من عند رأس شاول وذهبا ، ولم ير ولا علم ولا انتبه أحد لأنهم جميعا كانوا نياما ، لأن سبات الرب وقع عليهم '),
(4056, '1 Samuel', 9, 26, 13, ' وعبر داود إلى العبر ووقف على رأس الجبل عن بعد ، والمسافة بينهم كبيرة '),
(4057, '1 Samuel', 9, 26, 14, ' ونادى داود الشعب وأبنير بن نير قائلا : أما تجيب يا أبنير ؟  . فأجاب أبنير وقال : من أنت الذي ينادي الملك '),
(4058, '1 Samuel', 9, 26, 15, ' فقال داود لأبنير : أما أنت رجل ؟ ومن مثلك في إسرائيل ؟ فلماذا لم تحرس سيدك الملك ؟ لأنه قد جاء واحد من الشعب لكي يهلك الملك سيدك '),
(4059, '1 Samuel', 9, 26, 16, ' ليس حسنا هذا الأمر الذي عملت . حي هو الرب ، إنكم أبناء الموت أنتم ، لأنكم لم تحافظوا على سيدكم ، على مسيح الرب . فانظر الآن أين هو رمح الملك وكوز الماء الذي كان عند رأسه '),
(4060, '1 Samuel', 9, 26, 17, ' وعرف شاول صوت داود فقال : أهذا هو صوتك يا ابني داود ؟  . فقال داود : إنه صوتي يا سيدي الملك '),
(4061, '1 Samuel', 9, 26, 18, ' ثم قال : لماذا سيدي يسعى وراء عبده ؟ لأني ماذا عملت وأي شر بيدي '),
(4062, '1 Samuel', 9, 26, 19, ' والآن فليسمع سيدي الملك كلام عبده : فإن كان الرب قد أهاجك ضدي فليشتم تقدمة . وإن كان بنو الناس فليكونوا ملعونين أمام الرب ، لأنهم قد طردوني اليوم من الانضمام إلى نصيب الرب قائلين : اذهب اعبد آلهة أخرى '),
(4063, '1 Samuel', 9, 26, 20, ' والآن لا يسقط دمي إلى الأرض أمام وجه الرب ، لأن ملك إسرائيل قد خرج ليفتش على برغوث واحد كما يتبع الحجل في الجبال '),
(4064, '1 Samuel', 9, 26, 21, ' فقال شاول : قد أخطأت . ارجع يا ابني داود ، لأني لا أسيء إليك بعد من أجل أن نفسي كانت كريمة في عينيك اليوم . هوذا قد حمقت وضللت كثيرا جدا '),
(4065, '1 Samuel', 9, 26, 22, ' فأجاب داود وقال : هوذا رمح الملك ، فليعبر واحد من الغلمان ويأخذه '),
(4066, '1 Samuel', 9, 26, 23, ' والرب يرد على كل واحد بره وأمانته ، لأنه قد دفعك الرب اليوم ليدي ولم أشأ أن أمد يدي إلى مسيح الرب '),
(4067, '1 Samuel', 9, 26, 24, ' وهوذا كما كانت نفسك عظيمة اليوم في عيني ، كذلك لتعظم نفسي في عيني الرب فينقذني من كل ضيق '),
(4068, '1 Samuel', 9, 26, 25, ' فقال شاول لداود : مبارك أنت يا ابني داود ، فإنك تفعل وتقدر . ثم ذهب داود في طريقه ورجع شاول إلى مكانه '),
(4069, '1 Samuel', 9, 27, 1, ' وقال داود في قلبه : إني سأهلك يوما بيد شاول ، فلا شيء خير لي من أن أفلت إلى أرض الفلسطينيين ، فييأس شاول مني فلا يفتش علي بعد في جميع تخوم إسرائيل ، فأنجو من يده '),
(4070, '1 Samuel', 9, 27, 2, ' فقام داود وعبر هو والست مئة الرجل الذين معه إلى أخيش بن معوك ملك جت '),
(4071, '1 Samuel', 9, 27, 3, ' وأقام داود عند أخيش في جت هو ورجاله ، كل واحد وبيته ، داود وامرأتاه أخينوعم اليزرعيلية وأبيجايل امرأة نابال الكرملية '),
(4072, '1 Samuel', 9, 27, 4, ' فأخبر شاول أن داود قد هرب إلى جت فلم يعد أيضا يفتش عليه '),
(4073, '1 Samuel', 9, 27, 5, ' فقال داود لأخيش : إن كنت قد وجدت نعمة في عينيك ، فليعطوني مكانا في إحدى قرى الحقل فأسكن هناك . ولماذا يسكن عبدك في مدينة المملكة معك '),
(4074, '1 Samuel', 9, 27, 6, ' فأعطاه أخيش في ذلك اليوم صقلغ . لذلك صارت صقلغ لملوك يهوذا إلى هذا اليوم '),
(4075, '1 Samuel', 9, 27, 7, ' وكان عدد الأيام التي سكن فيها داود في بلاد الفلسطينيين سنة وأربعة أشهر '),
(4076, '1 Samuel', 9, 27, 8, ' وصعد داود ورجاله وغزوا الجشوريين والجرزيين والعمالقة ، لأن هؤلاء من قديم سكان الأرض من عند شور إلى أرض مصر '),
(4077, '1 Samuel', 9, 27, 9, ' وضرب داود الأرض ، ولم يستبق رجلا ولا امرأة ، وأخذ غنما وبقرا وحميرا وجمالا وثيابا ورجع وجاء إلى أخيش '),
(4078, '1 Samuel', 9, 27, 10, ' فقال أخيش : إذا لم تغزوا اليوم . فقال داود : بلى . على جنوبي يهوذا ، وجنوبي اليرحمئيليين ، وجنوبي القينيين '),
(4079, '1 Samuel', 9, 27, 11, ' فلم يستبق داود رجلا ولا امرأة حتى يأتي إلى جت ، إذ قال : لئلا يخبروا عنا قائلين : هكذا فعل داود . وهكذا عادته كل أيام إقامته في بلاد الفلسطينيين '),
(4080, '1 Samuel', 9, 27, 12, ' فصدق أخيش داود قائلا : قد صار مكروها لدى شعبه إسرائيل ، فيكون لي عبدا إلى الأبد '),
(4081, '1 Samuel', 9, 28, 1, ' وكان في تلك الأيام أن الفلسطينيين جمعوا جيوشهم لكي يحاربوا إسرائيل . فقال أخيش لداود : اعلم يقينا أنك ستخرج معي في الجيش أنت ورجالك '),
(4082, '1 Samuel', 9, 28, 2, ' فقال داود لأخيش : لذلك أنت ستعلم ما يفعل عبدك . فقال أخيش لداود : لذلك أجعلك حارسا لرأسي كل الأيام '),
(4083, '1 Samuel', 9, 28, 3, ' ومات صموئيل وندبه كل إسرائيل ودفنوه في الرامة في مدينته . وكان شاول قد نفى أصحاب الجان والتوابع من الأرض '),
(4084, '1 Samuel', 9, 28, 4, ' فاجتمع الفلسطينيون وجاءوا ونزلوا في شونم ، وجمع شاول جميع إسرائيل ونزل في جلبوع '),
(4085, '1 Samuel', 9, 28, 5, ' ولما رأى شاول جيش الفلسطينيين خاف واضطرب قلبه جدا '),
(4086, '1 Samuel', 9, 28, 6, ' فسأل شاول من الرب ، فلم يجبه الرب لا بالأحلام ولا بالأوريم ولا بالأنبياء '),
(4087, '1 Samuel', 9, 28, 7, ' فقال شاول لعبيده : فتشوا لي على امرأة صاحبة جان ، فأذهب إليها وأسألها . فقال له عبيده : هوذا امرأة صاحبة جان في عين دور '),
(4088, '1 Samuel', 9, 28, 8, ' فتنكر شاول ولبس ثيابا أخرى ، وذهب هو ورجلان معه وجاءوا إلى المرأة ليلا . وقال : اعرفي لي بالجان وأصعدي لي من أقول لك '),
(4089, '1 Samuel', 9, 28, 9, ' فقالت له المرأة : هوذا أنت تعلم ما فعل شاول ، كيف قطع أصحاب الجان والتوابع من الأرض . فلماذا تضع شركا لنفسي لتميتها '),
(4090, '1 Samuel', 9, 28, 10, ' فحلف لها شاول بالرب قائلا : حي هو الرب ، إنه لا يلحقك إثم في هذا الأمر '),
(4091, '1 Samuel', 9, 28, 11, ' فقالت المرأة : من أصعد لك ؟  . فقال : أصعدي لي صموئيل '),
(4092, '1 Samuel', 9, 28, 12, ' فلما رأت المرأة صموئيل صرخت بصوت عظيم ، وكلمت المرأة شاول قائلة : لماذا خدعتني وأنت شاول '),
(4093, '1 Samuel', 9, 28, 13, ' فقال لها الملك : لا تخافي . فماذا رأيت ؟  . فقالت المرأة لشاول : رأيت آلهة يصعدون من الأرض '),
(4094, '1 Samuel', 9, 28, 14, ' فقال لها : ما هي صورته ؟  . فقالت : رجل شيخ صاعد وهو مغطى بجبة . فعلم شاول أنه صموئيل ، فخر على وجهه إلى الأرض وسجد '),
(4095, '1 Samuel', 9, 28, 15, ' فقال صموئيل لشاول : لماذا أقلقتني بإصعادك إياي ؟  . فقال شاول : قد ضاق بي الأمر جدا . الفلسطينيون يحاربونني ، والرب فارقني ولم يعد يجيبني لا بالأنبياء ولا بالأحلام . فدعوتك لكي تعلمني ماذا أصنع '),
(4096, '1 Samuel', 9, 28, 16, ' فقال صموئيل : ولماذا تسألني والرب قد فارقك وصار عدوك '),
(4097, '1 Samuel', 9, 28, 17, ' وقد فعل الرب لنفسه كما تكلم عن يدي ، وقد شق الرب المملكة من يدك وأعطاها لقريبك داود '),
(4098, '1 Samuel', 9, 28, 18, ' لأنك لم تسمع لصوت الرب ولم تفعل حمو غضبه في عماليق ، لذلك قد فعل الرب بك هذا الأمر اليوم '),
(4099, '1 Samuel', 9, 28, 19, ' ويدفع الرب إسرائيل أيضا معك ليد الفلسطينيين . وغدا أنت وبنوك تكونون معي ، ويدفع الرب جيش إسرائيل أيضا ليد الفلسطينيين '),
(4100, '1 Samuel', 9, 28, 20, ' فأسرع شاول وسقط على طوله إلى الأرض وخاف جدا من كلام صموئيل ، وأيضا لم تكن فيه قوة ، لأنه لم يأكل طعاما النهار كله والليل '),
(4101, '1 Samuel', 9, 28, 21, ' ثم جاءت المرأة إلى شاول ورأت أنه مرتاع جدا ، فقالت له : هوذا قد سمعت جاريتك لصوتك فوضعت نفسي في كفي وسمعت لكلامك الذي كلمتني به '),
(4102, '1 Samuel', 9, 28, 22, ' والآن اسمع أنت أيضا لصوت جاريتك فأضع قدامك كسرة خبز وكل ، فتكون فيك قوة إذ تسير في الطريق '),
(4103, '1 Samuel', 9, 28, 23, ' فأبى وقال : لا آكل . فألح عليه عبداه والمرأة أيضا ، فسمع لصوتهم وقام عن الأرض وجلس على السرير '),
(4104, '1 Samuel', 9, 28, 24, ' وكان للمرأة عجل مسمن في البيت ، فأسرعت وذبحته وأخذت دقيقا وعجنته وخبزت فطيرا '),
(4105, '1 Samuel', 9, 28, 25, ' ثم قدمته أمام شاول وأمام عبديه فأكلوا . وقاموا وذهبوا في تلك الليلة '),
(4106, '1 Samuel', 9, 29, 1, ' وجمع الفلسطينيون جميع جيوشهم إلى أفيق . وكان الإسرائيليون نازلين على العين التي في يزرعيل '),
(4107, '1 Samuel', 9, 29, 2, ' وعبر أقطاب الفلسطينيين مئات وألوفا ، وعبر داود ورجاله في الساقة مع أخيش '),
(4108, '1 Samuel', 9, 29, 3, ' فقال رؤساء الفلسطينيين : ما هؤلاء العبرانيون ؟  . فقال أخيش لرؤساء الفلسطينيين : أليس هذا داود عبد شاول ملك إسرائيل الذي كان معي هذه الأيام أو هذه السنين ، ولم أجد فيه شيئا من يوم نزوله إلى هذا اليوم '),
(4109, '1 Samuel', 9, 29, 4, ' وسخط عليه رؤساء الفلسطينيين ، وقال له رؤساء الفلسطينيين : أرجع الرجل فيرجع إلى موضعه الذي عينت له ، ولا ينزل معنا إلى الحرب ، ولا يكون لنا عدوا في الحرب . فبماذا يرضي هذا سيده ؟ أليس برؤوس أولئك الرجال '),
(4110, '1 Thessalonians', 52, 1, 1, ' بولس وسلوانس وتيموثاوس ، إلى كنيسة التسالونيكيين ، في الله الآب والرب يسوع المسيح : نعمة لكم وسلام من الله أبينا والرب يسوع المسيح '),
(4111, '1 Thessalonians', 52, 1, 2, ' نشكر الله كل حين من جهة جميعكم ، ذاكرين إياكم في صلواتنا '),
(4112, '1 Thessalonians', 52, 1, 3, ' متذكرين بلا انقطاع عمل إيمانكم ، وتعب محبتكم ، وصبر رجائكم ، ربنا يسوع المسيح ، أمام الله وأبينا '),
(4113, '1 Thessalonians', 52, 1, 4, ' عالمين أيها الإخوة المحبوبون من الله اختياركم '),
(4114, '1 Thessalonians', 52, 1, 5, ' أن إنجيلنا لم يصر لكم بالكلام فقط ، بل بالقوة أيضا ، وبالروح القدس ، وبيقين شديد ، كما تعرفون أي رجال كنا بينكم من أجلكم '),
(4115, '1 Thessalonians', 52, 1, 6, ' وأنتم صرتم متمثلين بنا وبالرب ، إذ قبلتم الكلمة في ضيق كثير ، بفرح الروح القدس '),
(4116, '1 Thessalonians', 52, 1, 7, ' حتى صرتم قدوة لجميع الذين يؤمنون في مكدونية وفي أخائية '),
(4117, '1 Thessalonians', 52, 1, 8, ' لأنه من قبلكم قد أذيعت كلمة الرب ، ليس في مكدونية وأخائية فقط ، بل في كل مكان أيضا قد ذاع إيمانكم بالله ، حتى ليس لنا حاجة أن نتكلم شيئا '),
(4118, '1 Thessalonians', 52, 1, 9, ' لأنهم هم يخبرون عنا ، أي دخول كان لنا إليكم ، وكيف رجعتم إلى الله من الأوثان ، لتعبدوا الله الحي الحقيقي '),
(4119, '1 Thessalonians', 52, 1, 10, ' وتنتظروا ابنه من السماء ، الذي أقامه من الأموات ، يسوع ، الذي ينقذنا من الغضب الآتي '),
(4120, '1 Thessalonians', 52, 2, 1, ' لأنكم أنتم أيها الإخوة تعلمون دخولنا إليكم أنه لم يكن باطلا '),
(4121, '1 Thessalonians', 52, 2, 2, ' بل بعد ما تألمنا قبلا وبغي علينا كما تعلمون ، في فيلبي ، جاهرنا في إلهنا أن نكلمكم بإنجيل الله ، في جهاد كثير '),
(4122, '1 Thessalonians', 52, 2, 3, ' لأن وعظنا ليس عن ضلال ، ولا عن دنس ، ولا بمكر '),
(4123, '1 Thessalonians', 52, 2, 4, ' بل كما استحسنا من الله أن نؤتمن على الإنجيل ، هكذا نتكلم ، لا كأننا نرضي الناس بل الله الذي يختبر قلوبنا '),
(4124, '1 Thessalonians', 52, 2, 5, ' فإننا لم نكن قط في كلام تملق كما تعلمون ، ولا في علة طمع . الله شاهد '),
(4125, '1 Thessalonians', 52, 2, 6, ' ولا طلبنا مجدا من الناس ، لا منكم ولا من غيركم مع أننا قادرون أن نكون في وقار كرسل المسيح '),
(4126, '1 Thessalonians', 52, 2, 7, ' بل كنا مترفقين في وسطكم كما تربي المرضعة أولادها '),
(4127, '1 Thessalonians', 52, 2, 8, ' هكذا إذ كنا حانين إليكم ، كنا نرضى أن نعطيكم ، لا إنجيل الله فقط بل أنفسنا أيضا ، لأنكم صرتم محبوبين إلينا '),
(4128, '1 Thessalonians', 52, 2, 9, ' فإنكم تذكرون أيها الإخوة تعبنا وكدنا ، إذ كنا نكرز لكم بإنجيل الله ، ونحن عاملون ليلا ونهارا كي لا نثقل على أحد منكم '),
(4129, '1 Thessalonians', 52, 2, 10, ' أنتم شهود ، والله ، كيف بطهارة وببر وبلا لوم كنا بينكم أنتم المؤمنين '),
(4130, '1 Thessalonians', 52, 2, 11, ' كما تعلمون كيف كنا نعظ كل واحد منكم كالأب لأولاده ، ونشجعكم '),
(4131, '1 Thessalonians', 52, 2, 12, ' ونشهدكم لكي تسلكوا كما يحق لله الذي دعاكم إلى ملكوته ومجده '),
(4132, '1 Thessalonians', 52, 2, 13, ' من أجل ذلك نحن أيضا نشكر الله بلا انقطاع ، لأنكم إذ تسلمتم منا كلمة خبر من الله ، قبلتموها لا ككلمة أناس ، بل كما هي بالحقيقة ككلمة الله ، التي تعمل أيضا فيكم أنتم المؤمنين '),
(4133, '1 Thessalonians', 52, 2, 14, ' فإنكم أيها الإخوة صرتم متمثلين بكنائس الله التي هي في اليهودية في المسيح يسوع ، لأنكم تألمتم أنتم أيضا من أهل عشيرتكم تلك الآلام عينها ، كما هم أيضا من اليهود '),
(4134, '1 Thessalonians', 52, 2, 15, ' الذين قتلوا الرب يسوع وأنبياءهم ، واضطهدونا نحن . وهم غير مرضين لله وأضداد لجميع الناس '),
(4135, '1 Thessalonians', 52, 2, 16, ' يمنعوننا عن أن نكلم الأمم لكي يخلصوا ، حتى يتمموا خطاياهم كل حين . ولكن قد أدركهم الغضب إلى النهاية '),
(4136, '1 Thessalonians', 52, 2, 17, ' وأما نحن أيها الإخوة ، فإذ قد فقدناكم زمان ساعة - بالوجه لا بالقلب - اجتهدنا أكثر ، باشتهاء كثير ، أن نرى وجوهكم '),
(4137, '1 Thessalonians', 52, 2, 18, ' لذلك أردنا أن نأتي إليكم - أنا بولس - مرة ومرتين . وإنما عاقنا الشيطان '),
(4138, '1 Thessalonians', 52, 2, 19, ' لأن من هو رجاؤنا وفرحنا وإكليل افتخارنا ؟ أم لستم أنتم أيضا أمام ربنا يسوع المسيح في مجيئه '),
(4139, '1 Thessalonians', 52, 2, 20, ' لأنكم أنتم مجدنا وفرحنا '),
(4140, '1 Thessalonians', 52, 3, 1, ' لذلك إذ لم نحتمل أيضا استحسنا أن نترك في أثينا وحدنا '),
(4141, '1 Thessalonians', 52, 3, 2, ' فأرسلنا تيموثاوس أخانا ، وخادم الله ، والعامل معنا في إنجيل المسيح ، حتى يثبتكم ويعظكم لأجل إيمانكم '),
(4142, '1 Thessalonians', 52, 3, 3, ' كي لا يتزعزع أحد في هذه الضيقات . فإنكم أنتم تعلمون أننا موضوعون لهذا '),
(4143, '1 Thessalonians', 52, 3, 4, ' لأننا لما كنا عندكم ، سبقنا فقلنا لكم : إننا عتيدون أن نتضايق ، كما حصل أيضا ، وأنتم تعلمون '),
(4144, '1 Thessalonians', 52, 3, 5, ' من أجل هذا إذ لم أحتمل أيضا ، أرسلت لكي أعرف إيمانكم ، لعل المجرب يكون قد جربكم ، فيصير تعبنا باطلا '),
(4145, '1 Thessalonians', 52, 3, 6, ' وأما الآن فإذ جاء إلينا تيموثاوس من عندكم ، وبشرنا بإيمانكم ومحبتكم ، وبأن عندكم ذكرا لنا حسنا كل حين ، وأنتم مشتاقون أن ترونا ، كما نحن أيضا أن نراكم '),
(4146, '1 Thessalonians', 52, 3, 7, ' فمن أجل هذا تعزينا أيها الإخوة من جهتكم في ضيقتنا وضرورتنا ، بإيمانكم '),
(4147, '1 Thessalonians', 52, 3, 8, ' لأننا الآن نعيش إن ثبتم أنتم في الرب '),
(4148, '1 Thessalonians', 52, 3, 9, ' لأنه أي شكر نستطيع أن نعوض إلى الله من جهتكم عن كل الفرح الذي نفرح به من أجلكم قدام إلهنا '),
(4149, '1 Thessalonians', 52, 3, 10, ' طالبين ليلا ونهارا أوفر طلب ، أن نرى وجوهكم ، ونكمل نقائص إيمانكم '),
(4150, '1 Thessalonians', 52, 3, 11, ' والله نفسه أبونا وربنا يسوع المسيح يهدي طريقنا إليكم '),
(4151, '1 Thessalonians', 52, 3, 12, ' والرب ينميكم ويزيدكم في المحبة بعضكم لبعض وللجميع كما نحن أيضا لكم '),
(4152, '1 Thessalonians', 52, 3, 13, ' لكي يثبت قلوبكم بلا لوم في القداسة ، أمام الله أبينا في مجيء ربنا يسوع المسيح مع جميع قديسيه '),
(4153, '1 Thessalonians', 52, 4, 1, ' فمن ثم أيها الإخوة نسألكم ونطلب إليكم في الرب يسوع ، أنكم كما تسلمتم منا كيف يجب أن تسلكوا وترضوا الله ، تزدادون أكثر '),
(4154, '1 Thessalonians', 52, 4, 2, ' لأنكم تعلمون أية وصايا أعطيناكم بالرب يسوع '),
(4155, '1 Thessalonians', 52, 4, 3, ' لأن هذه هي إرادة الله : قداستكم . أن تمتنعوا عن الزنا '),
(4156, '1 Thessalonians', 52, 4, 4, ' أن يعرف كل واحد منكم أن يقتني إناءه بقداسة وكرامة '),
(4157, '1 Thessalonians', 52, 4, 5, ' لا في هوى شهوة كالأمم الذين لا يعرفون الله '),
(4158, '1 Thessalonians', 52, 4, 6, ' أن لا يتطاول أحد ويطمع على أخيه في هذا الأمر ، لأن الرب منتقم لهذه كلها كما قلنا لكم قبلا وشهدنا '),
(4159, '1 Thessalonians', 52, 4, 7, ' لأن الله لم يدعنا للنجاسة بل في القداسة '),
(4160, '1 Thessalonians', 52, 4, 8, ' إذا من يرذل لا يرذل إنسانا ، بل الله الذي أعطانا أيضا روحه القدوس '),
(4161, '1 Thessalonians', 52, 4, 9, ' وأما المحبة الأخوية فلا حاجة لكم أن أكتب إليكم عنها ، لأنكم أنفسكم متعلمون من الله أن يحب بعضكم بعضا '),
(4162, '1 Thessalonians', 52, 4, 10, ' فإنكم تفعلون ذلك أيضا لجميع الإخوة الذين في مكدونية كلها . وإنما أطلب إليكم أيها الإخوة أن تزدادوا أكثر '),
(4163, '1 Thessalonians', 52, 4, 11, ' وأن تحرصوا على أن تكونوا هادئين ، وتمارسوا أموركم الخاصة ، وتشتغلوا بأيديكم أنتم كما أوصيناكم '),
(4164, '1 Thessalonians', 52, 4, 12, ' لكي تسلكوا بلياقة عند الذين هم من خارج ، ولا تكون لكم حاجة إلى أحد '),
(4165, '1 Thessalonians', 52, 4, 13, ' ثم لا أريد أن تجهلوا أيها الإخوة من جهة الراقدين ، لكي لا تحزنوا كالباقين الذين لا رجاء لهم '),
(4166, '1 Thessalonians', 52, 4, 14, ' لأنه إن كنا نؤمن أن يسوع مات وقام ، فكذلك الراقدون بيسوع ، سيحضرهم الله أيضا معه '),
(4167, '1 Thessalonians', 52, 4, 15, ' فإننا نقول لكم هذا بكلمة الرب : إننا نحن الأحياء الباقين إلى مجيء الرب ، لا نسبق الراقدين '),
(4168, '1 Thessalonians', 52, 4, 16, ' لأن الرب نفسه بهتاف ، بصوت رئيس ملائكة وبوق الله ، سوف ينزل من السماء والأموات في المسيح سيقومون أولا '),
(4169, '1 Thessalonians', 52, 4, 17, ' ثم نحن الأحياء الباقين سنخطف جميعا معهم في السحب لملاقاة الرب في الهواء ، وهكذا نكون كل حين مع الرب '),
(4170, '1 Thessalonians', 52, 4, 18, ' لذلك عزوا بعضكم بعضا بهذا الكلام '),
(4171, '1 Thessalonians', 52, 5, 1, ' وأما الأزمنة والأوقات فلا حاجة لكم أيها الإخوة أن أكتب إليكم عنها '),
(4172, '1 Thessalonians', 52, 5, 2, ' لأنكم أنتم تعلمون بالتحقيق أن يوم الرب كلص في الليل هكذا يجيء '),
(4173, '1 Thessalonians', 52, 5, 3, ' لأنه حينما يقولون : سلام وأمان ، حينئذ يفاجئهم هلاك بغتة ، كالمخاض للحبلى ، فلا ينجون '),
(4174, '1 Thessalonians', 52, 5, 4, ' وأما أنتم أيها الإخوة فلستم في ظلمة حتى يدرككم ذلك اليوم كلص '),
(4175, '1 Thessalonians', 52, 5, 5, ' جميعكم أبناء نور وأبناء نهار . لسنا من ليل ولا ظلمة '),
(4176, '1 Thessalonians', 52, 5, 6, ' فلا ننم إذا كالباقين ، بل لنسهر ونصح '),
(4177, '1 Thessalonians', 52, 5, 7, ' لأن الذين ينامون فبالليل ينامون ، والذين يسكرون فبالليل يسكرون '),
(4178, '1 Thessalonians', 52, 5, 8, ' وأما نحن الذين من نهار ، فلنصح لابسين درع الإيمان والمحبة ، وخوذة هي رجاء الخلاص '),
(4179, '1 Thessalonians', 52, 5, 9, ' لأن الله لم يجعلنا للغضب ، بل لاقتناء الخلاص بربنا يسوع المسيح '),
(4180, '1 Thessalonians', 52, 5, 10, ' الذي مات لأجلنا ، حتى إذا سهرنا أو نمنا نحيا جميعا معه '),
(4181, '1 Thessalonians', 52, 5, 11, ' لذلك عزوا بعضكم بعضا وابنوا أحدكم الآخر ، كما تفعلون أيضا '),
(4182, '1 Thessalonians', 52, 5, 12, ' ثم نسألكم أيها الإخوة أن تعرفوا الذين يتعبون بينكم ويدبرونكم في الرب وينذرونكم '),
(4183, '1 Thessalonians', 52, 5, 13, ' وأن تعتبروهم كثيرا جدا في المحبة من أجل عملهم . سالموا بعضكم بعضا '),
(4184, '1 Thessalonians', 52, 5, 14, ' ونطلب إليكم أيها الإخوة : أنذروا الذين بلا ترتيب . شجعوا صغار النفوس . أسندوا الضعفاء . تأنوا على الجميع '),
(4185, '1 Thessalonians', 52, 5, 15, ' انظروا أن لا يجازي أحد أحدا عن شر بشر ، بل كل حين اتبعوا الخير بعضكم لبعض وللجميع '),
(4186, '1 Thessalonians', 52, 5, 16, ' افرحوا كل حين '),
(4187, '1 Thessalonians', 52, 5, 17, ' صلوا بلا انقطاع '),
(4188, '1 Thessalonians', 52, 5, 18, ' اشكروا في كل شيء ، لأن هذه هي مشيئة الله في المسيح يسوع من جهتكم '),
(4189, '1 Thessalonians', 52, 5, 19, ' لا تطفئوا الروح '),
(4190, '1 Thessalonians', 52, 5, 20, ' لا تحتقروا النبوات '),
(4191, '1 Thessalonians', 52, 5, 21, ' امتحنوا كل شيء . تمسكوا بالحسن '),
(4192, '1 Thessalonians', 52, 5, 22, ' امتنعوا عن كل شبه شر '),
(4193, '1 Thessalonians', 52, 5, 23, ' وإله السلام نفسه يقدسكم بالتمام . ولتحفظ روحكم ونفسكم وجسدكم كاملة بلا لوم عند مجيء ربنا يسوع المسيح '),
(4194, '1 Thessalonians', 52, 5, 24, ' أمين هو الذي يدعوكم الذي سيفعل أيضا '),
(4195, '1 Thessalonians', 52, 5, 25, ' أيها الإخوة صلوا لأجلنا '),
(4196, '1 Thessalonians', 52, 5, 26, ' سلموا على الإخوة جميعا بقبلة مقدسة '),
(4197, '1 Thessalonians', 52, 5, 27, ' أناشدكم بالرب أن تقرأ هذه الرسالة على جميع الإخوة القديسين '),
(4198, '1 Thessalonians', 52, 5, 28, ' نعمة ربنا يسوع المسيح معكم . آمين '),
(4199, '1 Timothy', 54, 1, 1, ' بولس ، رسول يسوع المسيح ، بحسب أمر الله مخلصنا ، وربنا يسوع المسيح ، رجائنا '),
(4200, '1 Timothy', 54, 1, 2, ' إلى تيموثاوس ، الابن الصريح في الإيمان : نعمة ورحمة وسلام من الله أبينا والمسيح يسوع ربنا '),
(4201, '1 Timothy', 54, 1, 3, ' كما طلبت إليك أن تمكث في أفسس ، إذ كنت أنا ذاهبا إلى مكدونية ، لكي توصي قوما أن لا يعلموا تعليما آخر '),
(4202, '1 Timothy', 54, 1, 4, ' ولا يصغوا إلى خرافات وأنساب لا حد لها ، تسبب مباحثات دون بنيان الله الذي في الإيمان '),
(4203, '1 Timothy', 54, 1, 5, ' وأما غاية الوصية فهي المحبة من قلب طاهر ، وضمير صالح ، وإيمان بلا رياء '),
(4204, '1 Timothy', 54, 1, 6, ' الأمور التي إذ زاغ قوم عنها ، انحرفوا إلى كلام باطل '),
(4205, '1 Timothy', 54, 1, 7, ' يريدون أن يكونوا معلمي الناموس ، وهم لا يفهمون ما يقولون ، ولا ما يقررونه '),
(4206, '1 Timothy', 54, 1, 8, ' ولكننا نعلم أن الناموس صالح ، إن كان أحد يستعمله ناموسيا '),
(4207, '1 Timothy', 54, 1, 9, ' عالما هذا : أن الناموس لم يوضع للبار ، بل للأثمة والمتمردين ، للفجار والخطاة ، للدنسين والمستبيحين ، لقاتلي الآباء وقاتلي الأمهات ، لقاتلي الناس '),
(4208, '1 Timothy', 54, 1, 10, ' للزناة ، لمضاجعي الذكور ، لسارقي الناس ، للكذابين ، للحانثين ، وإن كان شيء آخر يقاوم التعليم الصحيح '),
(4209, '1 Timothy', 54, 1, 11, ' حسب إنجيل مجد الله المبارك الذي اؤتمنت أنا عليه '),
(4210, '1 Timothy', 54, 1, 12, ' وأنا أشكر المسيح يسوع ربنا الذي قواني ، أنه حسبني أمينا ، إذ جعلني للخدمة '),
(4211, '1 Timothy', 54, 1, 13, ' أنا الذي كنت قبلا مجدفا ومضطهدا ومفتريا . ولكنني رحمت ، لأني فعلت بجهل في عدم إيمان '),
(4212, '1 Timothy', 54, 1, 14, ' وتفاضلت نعمة ربنا جدا مع الإيمان والمحبة التي في المسيح يسوع '),
(4213, '1 Timothy', 54, 1, 15, ' صادقة هي الكلمة ومستحقة كل قبول : أن المسيح يسوع جاء إلى العالم ليخلص الخطاة الذين أولهم أنا '),
(4214, '1 Timothy', 54, 1, 16, ' لكنني لهذا رحمت : ليظهر يسوع المسيح في أنا أولا كل أناة ، مثالا للعتيدين أن يؤمنوا به للحياة الأبدية '),
(4215, '1 Timothy', 54, 1, 17, ' وملك الدهور الذي لا يفنى ولا يرى ، الإله الحكيم وحده ، له الكرامة والمجد إلى دهر الدهور . آمين '),
(4216, '1 Timothy', 54, 1, 18, ' هذه الوصية أيها الابن تيموثاوس أستودعك إياها حسب النبوات التي سبقت عليك ، لكي تحارب فيها المحاربة الحسنة '),
(4217, '1 Timothy', 54, 1, 19, ' ولك إيمان وضمير صالح ، الذي إذ رفضه قوم ، انكسرت بهم السفينة من جهة الإيمان أيضا '),
(4218, '1 Timothy', 54, 1, 20, ' الذين منهم هيمينايس والإسكندر ، اللذان أسلمتهما للشيطان لكي يؤدبا حتى لا يجدفا '),
(4219, '1 Timothy', 54, 2, 1, ' فأطلب أول كل شيء ، أن تقام طلبات وصلوات وابتهالات وتشكرات لأجل جميع الناس '),
(4220, '1 Timothy', 54, 2, 2, ' لأجل الملوك وجميع الذين هم في منصب ، لكي نقضي حياة مطمئنة هادئة في كل تقوى ووقار '),
(4221, '1 Timothy', 54, 2, 3, ' لأن هذا حسن ومقبول لدى مخلصنا الله '),
(4222, '1 Timothy', 54, 2, 4, ' الذي يريد أن جميع الناس يخلصون ، وإلى معرفة الحق يقبلون '),
(4223, '1 Timothy', 54, 2, 5, ' لأنه يوجد إله واحد ووسيط واحد بين الله والناس : الإنسان يسوع المسيح '),
(4224, '1 Timothy', 54, 2, 6, ' الذي بذل نفسه فدية لأجل الجميع ، الشهادة في أوقاتها الخاصة '),
(4225, '1 Timothy', 54, 2, 7, ' التي جعلت أنا لها كارزا ورسولا . الحق أقول في المسيح ولا أكذب ، معلما للأمم في الإيمان والحق '),
(4226, '1 Timothy', 54, 2, 8, ' فأريد أن يصلي الرجال في كل مكان ، رافعين أيادي طاهرة ، بدون غضب ولا جدال '),
(4227, '1 Timothy', 54, 2, 9, ' وكذلك أن النساء يزين ذواتهن بلباس الحشمة ، مع ورع وتعقل ، لا بضفائر أو ذهب أو لآلئ أو ملابس كثيرة الثمن '),
(4228, '1 Timothy', 54, 2, 10, ' بل كما يليق بنساء متعاهدات بتقوى الله بأعمال صالحة '),
(4229, '1 Timothy', 54, 2, 11, ' لتتعلم المرأة بسكوت في كل خضوع '),
(4230, '1 Timothy', 54, 2, 12, ' ولكن لست آذن للمرأة أن تعلم ولا تتسلط على الرجل ، بل تكون في سكوت '),
(4231, '1 Timothy', 54, 2, 13, ' لأن آدم جبل أولا ثم حواء '),
(4232, '1 Timothy', 54, 2, 14, ' وآدم لم يغو ، لكن المرأة أغويت فحصلت في التعدي '),
(4233, '1 Timothy', 54, 2, 15, ' ولكنها ستخلص بولادة الأولاد ، إن ثبتن في الإيمان والمحبة والقداسة مع التعقل '),
(4234, '1 Timothy', 54, 3, 1, ' صادقة هي الكلمة : إن ابتغى أحد الأسقفية ، فيشتهي عملا صالحا '),
(4235, '1 Timothy', 54, 3, 2, ' فيجب أن يكون الأسقف بلا لوم ، بعل امرأة واحدة ، صاحيا ، عاقلا ، محتشما ، مضيفا للغرباء ، صالحا للتعليم '),
(4236, '1 Timothy', 54, 3, 3, ' غير مدمن الخمر ، ولا ضراب ، ولا طامع بالربح القبيح ، بل حليما ، غير مخاصم ، ولا محب للمال '),
(4237, '1 Timothy', 54, 3, 4, ' يدبر بيته حسنا ، له أولاد في الخضوع بكل وقار '),
(4238, '1 Timothy', 54, 3, 5, ' وإنما إن كان أحد لا يعرف أن يدبر بيته ، فكيف يعتني بكنيسة الله '),
(4239, '1 Timothy', 54, 3, 6, ' غير حديث الإيمان لئلا يتصلف فيسقط في دينونة إبليس '),
(4240, '1 Timothy', 54, 3, 7, ' ويجب أيضا أن تكون له شهادة حسنة من الذين هم من خارج ، لئلا يسقط في تعيير وفخ إبليس '),
(4241, '1 Timothy', 54, 3, 8, ' كذلك يجب أن يكون الشمامسة ذوي وقار ، لا ذوي لسانين ، غير مولعين بالخمر الكثير ، ولا طامعين بالربح القبيح '),
(4242, '1 Timothy', 54, 3, 9, ' ولهم سر الإيمان بضمير طاهر '),
(4243, '1 Timothy', 54, 3, 10, ' وإنما هؤلاء أيضا ليختبروا أولا ، ثم يتشمسوا إن كانوا بلا لوم '),
(4244, '1 Timothy', 54, 3, 11, ' كذلك يجب أن تكون النساء ذوات وقار ، غير ثالبات ، صاحيات ، أمينات في كل شيء '),
(4245, '1 Timothy', 54, 3, 12, ' ليكن الشمامسة كل بعل امرأة واحدة ، مدبرين أولادهم وبيوتهم حسنا '),
(4246, '1 Timothy', 54, 3, 13, ' لأن الذين تشمسوا حسنا ، يقتنون لأنفسهم درجة حسنة وثقة كثيرة في الإيمان الذي بالمسيح يسوع '),
(4247, '1 Timothy', 54, 3, 14, ' هذا أكتبه إليك راجيا أن آتي إليك عن قريب '),
(4248, '1 Timothy', 54, 3, 15, ' ولكن إن كنت أبطئ ، فلكي تعلم كيف يجب أن تتصرف في بيت الله ، الذي هو كنيسة الله الحي ، عمود الحق وقاعدته '),
(4249, '1 Timothy', 54, 3, 16, ' وبالإجماع عظيم هو سر التقوى : الله ظهر في الجسد ، تبرر في الروح ، تراءى لملائكة ، كرز به بين الأمم ، أومن به في العالم ، رفع في المجد '),
(4250, '1 Timothy', 54, 4, 1, ' ولكن الروح يقول صريحا : إنه في الأزمنة الأخيرة يرتد قوم عن الإيمان ، تابعين أرواحا مضلة وتعاليم شياطين '),
(4251, '1 Timothy', 54, 4, 2, ' في رياء أقوال كاذبة ، موسومة ضمائرهم '),
(4252, '1 Timothy', 54, 4, 3, ' مانعين عن الزواج ، وآمرين أن يمتنع عن أطعمة قد خلقها الله لتتناول بالشكر من المؤمنين وعارفي الحق '),
(4253, '1 Timothy', 54, 4, 4, ' لأن كل خليقة الله جيدة ، ولا يرفض شيء إذا أخذ مع الشكر '),
(4254, '1 Timothy', 54, 4, 5, ' لأنه يقدس بكلمة الله والصلاة '),
(4255, '1 Timothy', 54, 4, 6, ' إن فكرت الإخوة بهذا ، تكون خادما صالحا ليسوع المسيح ، متربيا بكلام الإيمان والتعليم الحسن الذي تتبعته '),
(4256, '1 Timothy', 54, 4, 7, ' وأما الخرافات الدنسة العجائزية فارفضها ، وروض نفسك للتقوى '),
(4257, '1 Timothy', 54, 4, 8, ' لأن الرياضة الجسدية نافعة لقليل ، ولكن التقوى نافعة لكل شيء ، إذ لها موعد الحياة الحاضرة والعتيدة '),
(4258, '1 Timothy', 54, 4, 9, ' صادقة هي الكلمة ومستحقة كل قبول '),
(4259, '1 Timothy', 54, 4, 10, ' لأننا لهذا نتعب ونعير ، لأننا قد ألقينا رجاءنا على الله الحي ، الذي هو مخلص جميع الناس ، ولاسيما المؤمنين '),
(4260, '1 Timothy', 54, 4, 11, ' أوص بهذا وعلم '),
(4261, '1 Timothy', 54, 4, 12, ' لا يستهن أحد بحداثتك ، بل كن قدوة للمؤمنين في الكلام ، في التصرف ، في المحبة ، في الروح ، في الإيمان ، في الطهارة '),
(4262, '1 Timothy', 54, 4, 13, ' إلى أن أجيء اعكف على القراءة والوعظ والتعليم '),
(4263, '1 Timothy', 54, 4, 14, ' لا تهمل الموهبة التي فيك ، المعطاة لك بالنبوة مع وضع أيدي المشيخة '),
(4264, '1 Timothy', 54, 4, 15, ' اهتم بهذا . كن فيه ، لكي يكون تقدمك ظاهرا في كل شيء '),
(4265, '1 Timothy', 54, 4, 16, ' لاحظ نفسك والتعليم وداوم على ذلك ، لأنك إذا فعلت هذا ، تخلص نفسك والذين يسمعونك أيضا '),
(4266, '1 Timothy', 54, 5, 1, ' لا تزجر شيخا بل عظه كأب ، والأحداث كإخوة '),
(4267, '1 Timothy', 54, 5, 2, ' والعجائز كأمهات ، والحدثات كأخوات ، بكل طهارة '),
(4268, '1 Timothy', 54, 5, 3, ' أكرم الأرامل اللواتي هن بالحقيقة أرامل '),
(4269, '1 Timothy', 54, 5, 4, ' ولكن إن كانت أرملة لها أولاد أو حفدة ، فليتعلموا أولا أن يوقروا أهل بيتهم ويوفوا والديهم المكافأة ، لأن هذا صالح ومقبول أمام الله '),
(4270, '1 Timothy', 54, 5, 5, ' ولكن التي هي بالحقيقة أرملة ووحيدة ، فقد ألقت رجاءها على الله ، وهي تواظب الطلبات والصلوات ليلا ونهارا '),
(4271, '1 Timothy', 54, 5, 6, ' وأما المتنعمة فقد ماتت وهي حية '),
(4272, '1 Timothy', 54, 5, 7, ' فأوص بهذا لكي يكن بلا لوم '),
(4273, '1 Timothy', 54, 5, 8, ' وإن كان أحد لا يعتني بخاصته ، ولاسيما أهل بيته ، فقد أنكر الإيمان ، وهو شر من غير المؤمن '),
(4274, '1 Timothy', 54, 5, 9, ' لتكتتب أرملة ، إن لم يكن عمرها أقل من ستين سنة ، امرأة رجل واحد '),
(4275, '1 Timothy', 54, 5, 10, ' مشهودا لها في أعمال صالحة ، إن تكن قد ربت الأولاد ، أضافت الغرباء ، غسلت أرجل القديسين ، ساعدت المتضايقين ، اتبعت كل عمل صالح '),
(4276, '1 Timothy', 54, 5, 11, ' أما الأرامل الحدثات فارفضهن ، لأنهن متى بطرن على المسيح ، يردن أن يتزوجن '),
(4277, '1 Timothy', 54, 5, 12, ' ولهن دينونة لأنهن رفضن الإيمان الأول '),
(4278, '1 Timothy', 54, 5, 13, ' ومع ذلك أيضا يتعلمن أن يكن بطالات ، يطفن في البيوت . ولسن بطالات فقط بل مهذارات أيضا ، وفضوليات ، يتكلمن بما لا يجب '),
(4279, '1 Timothy', 54, 5, 14, ' فأريد أن الحدثات يتزوجن ويلدن الأولاد ويدبرن البيوت ، ولا يعطين علة للمقاوم من أجل الشتم '),
(4280, '1 Timothy', 54, 5, 15, ' فإن بعضهن قد انحرفن وراء الشيطان ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(4281, '1 Timothy', 54, 5, 16, ' إن كان لمؤمن أو مؤمنة أرامل ، فليساعدهن ولا يثقل على الكنيسة ، لكي تساعد هي اللواتي هن بالحقيقة أرامل '),
(4282, '1 Timothy', 54, 5, 17, ' أما الشيوخ المدبرون حسنا فليحسبوا أهلا لكرامة مضاعفة ، ولاسيما الذين يتعبون في الكلمة والتعليم '),
(4283, '1 Timothy', 54, 5, 18, ' لأن الكتاب يقول : لا تكم ثورا دارسا ، والفاعل مستحق أجرته '),
(4284, '1 Timothy', 54, 5, 19, ' لا تقبل شكاية على شيخ إلا على شاهدين أو ثلاثة شهود '),
(4285, '1 Timothy', 54, 5, 20, ' الذين يخطئون وبخهم أمام الجميع ، لكي يكون عند الباقين خوف '),
(4286, '1 Timothy', 54, 5, 21, ' أناشدك أمام الله والرب يسوع المسيح والملائكة المختارين ، أن تحفظ هذا بدون غرض ، ولا تعمل شيئا بمحاباة '),
(4287, '1 Timothy', 54, 5, 22, ' لا تضع يدا على أحد بالعجلة ، ولا تشترك في خطايا الآخرين . احفظ نفسك طاهرا '),
(4288, '1 Timothy', 54, 5, 23, ' لا تكن في ما بعد شراب ماء ، بل استعمل خمرا قليلا من أجل معدتك وأسقامك الكثيرة '),
(4289, '1 Timothy', 54, 5, 24, ' خطايا بعض الناس واضحة تتقدم إلى القضاء ، وأما البعض فتتبعهم '),
(4290, '1 Timothy', 54, 5, 25, ' كذلك أيضا الأعمال الصالحة واضحة ، والتي هي خلاف ذلك لا يمكن أن تخفى '),
(4291, '1 Timothy', 54, 6, 1, ' جميع الذين هم عبيد تحت نير فليحسبوا سادتهم مستحقين كل إكرام ، لئلا يفترى على اسم الله وتعليمه '),
(4292, '1 Timothy', 54, 6, 2, ' والذين لهم سادة مؤمنون ، لا يستهينوا بهم لأنهم إخوة ، بل ليخدموهم أكثر ، لأن الذين يتشاركون في الفائدة ، هم مؤمنون ومحبوبون . علم وعظ بهذا '),
(4293, '1 Timothy', 54, 6, 3, ' إن كان أحد يعلم تعليما آخر ، ولا يوافق كلمات ربنا يسوع المسيح الصحيحة ، والتعليم الذي هو حسب التقوى '),
(4294, '1 Timothy', 54, 6, 4, ' فقد تصلف ، وهو لا يفهم شيئا ، بل هو متعلل بمباحثات ومماحكات الكلام ، التي منها يحصل الحسد والخصام والافتراء والظنون الردية '),
(4295, '1 Timothy', 54, 6, 5, ' ومنازعات أناس فاسدي الذهن وعادمي الحق ، يظنون أن التقوى تجارة . تجنب مثل هؤلاء '),
(4296, '1 Timothy', 54, 6, 6, ' وأما التقوى مع القناعة فهي تجارة عظيمة '),
(4297, '1 Timothy', 54, 6, 7, ' لأننا لم ندخل العالم بشيء ، وواضح أننا لا نقدر أن نخرج منه بشيء '),
(4298, '1 Timothy', 54, 6, 8, ' فإن كان لنا قوت وكسوة ، فلنكتف بهما '),
(4299, '1 Timothy', 54, 6, 9, ' وأما الذين يريدون أن يكونوا أغنياء ، فيسقطون في تجربة وفخ وشهوات كثيرة غبية ومضرة ، تغرق الناس في العطب والهلاك '),
(4300, '1 Timothy', 54, 6, 10, ' لأن محبة المال أصل لكل الشرور ، الذي إذ ابتغاه قوم ضلوا عن الإيمان ، وطعنوا أنفسهم بأوجاع كثيرة '),
(4301, '1 Timothy', 54, 6, 11, ' وأما أنت يا إنسان الله فاهرب من هذا ، واتبع البر والتقوى والإيمان والمحبة والصبر والوداعة '),
(4302, '1 Timothy', 54, 6, 12, ' جاهد جهاد الإيمان الحسن ، وأمسك بالحياة الأبدية التي إليها دعيت أيضا ، واعترفت الاعتراف الحسن أمام شهود كثيرين '),
(4303, '1 Timothy', 54, 6, 13, ' أوصيك أمام الله الذي يحيي الكل ، والمسيح يسوع الذي شهد لدى بيلاطس البنطي بالاعتراف الحسن '),
(4304, '1 Timothy', 54, 6, 14, ' أن تحفظ الوصية بلا دنس ولا لوم إلى ظهور ربنا يسوع المسيح '),
(4305, '1 Timothy', 54, 6, 15, ' الذي سيبينه في أوقاته المبارك العزيز الوحيد : ملك الملوك ورب الأرباب '),
(4306, '1 Timothy', 54, 6, 16, ' الذي وحده له عدم الموت ، ساكنا في نور لا يدنى منه ، الذي لم يره أحد من الناس ولا يقدر أن يراه ، الذي له الكرامة والقدرة الأبدية . آمين '),
(4307, '1 Timothy', 54, 6, 17, ' أوص الأغنياء في الدهر الحاضر أن لا يستكبروا ، ولا يلقوا رجاءهم على غير يقينية الغنى ، بل على الله الحي الذي يمنحنا كل شيء بغنى للتمتع '),
(4308, '1 Timothy', 54, 6, 18, ' وأن يصنعوا صلاحا ، وأن يكونوا أغنياء في أعمال صالحة ، وأن يكونوا أسخياء في العطاء ، كرماء في التوزيع '),
(4309, '1 Timothy', 54, 6, 19, ' مدخرين لأنفسهم أساسا حسنا للمستقبل ، لكي يمسكوا بالحياة الأبدية '),
(4310, '1 Timothy', 54, 6, 20, ' يا تيموثاوس ، احفظ الوديعة ، معرضا عن الكلام الباطل الدنس ، ومخالفات العلم الكاذب الاسم '),
(4311, '1 Timothy', 54, 6, 21, ' الذي إذ تظاهر به قوم زاغوا من جهة الإيمان '),
(4312, '1 Timothy', 54, 6, 22, ' النعمة معك . آمين '),
(4313, '2 Chronicles', 14, 4, 14, ' وعمل القواعد وعمل المراحض على القواعد '),
(4314, '2 Chronicles', 14, 4, 15, ' والبحر الواحد والاثني عشر ثورا تحته '),
(4315, '2 Chronicles', 14, 4, 16, ' والقدور والرفوش والمناشل وكل آنيتها ، عملها للملك سليمان حورام أبي لبيت الرب من نحاس مجلي '),
(4316, '2 Chronicles', 14, 4, 17, ' في غور الأردن سبكها الملك في أرض الخزف بين سكوت وصردة '),
(4317, '2 Chronicles', 14, 4, 18, ' وعمل سليمان كل هذه الآنية كثيرة جدا لأنه لم يتحقق وزن النحاس '),
(4318, '2 Chronicles', 14, 4, 19, ' وعمل سليمان كل الآنية التي لبيت الله ، ومذبح الذهب والموائد وعليها خبز الوجوه '),
(4319, '2 Chronicles', 14, 4, 20, ' والمنائر وسرجها لتتقد حسب المرسوم أمام المحراب من ذهب خالص '),
(4320, '2 Chronicles', 14, 4, 21, ' والأزهار والسرج والملاقط من ذهب . وهو ذهب كامل '),
(4321, '2 Chronicles', 14, 4, 22, ' والمقاص والمناضح والصحون والمجامر من ذهب خالص ، وباب البيت ومصاريعه الداخلية لقدس الأقداس ومصاريع بيت الهيكل من ذهب '),
(4322, '2 Chronicles', 14, 5, 1, ' وكمل جميع العمل الذي عمله سليمان لبيت الرب ، وأدخل سليمان أقداس داود أبيه . والفضة والذهب وجميع الآنية جعلها في خزائن بيت الله '),
(4323, '2 Chronicles', 14, 5, 2, ' حينئذ جمع سليمان شيوخ إسرائيل وكل رؤوس الأسباط ، رؤساء الآباء لبني إسرائيل ، إلى أورشليم لإصعاد تابوت عهد الرب من مدينة داود ، هي صهيون '),
(4324, '2 Chronicles', 14, 5, 3, ' فاجتمع إلى الملك جميع رجال إسرائيل في العيد الذي في الشهر السابع '),
(4325, '2 Chronicles', 14, 5, 4, ' وجاء جميع شيوخ إسرائيل . وحمل اللاويون التابوت '),
(4326, '2 Chronicles', 14, 5, 5, ' وأصعدوا التابوت وخيمة الاجتماع مع جميع آنية القدس التي في الخيمة ، أصعدها الكهنة واللاويون '),
(4327, '2 Chronicles', 14, 5, 6, ' والملك سليمان وكل جماعة إسرائيل المجتمعين إليه أمام التابوت كانوا يذبحون غنما وبقرا ما لا يحصى ولا يعد من الكثرة '),
(4328, '2 Chronicles', 14, 5, 7, ' وأدخل الكهنة تابوت عهد الرب إلى مكانه في محراب البيت في قدس الأقداس إلى تحت جناحي الكروبين '),
(4329, '2 Chronicles', 14, 5, 8, ' وكان الكروبان باسطين أجنحتهما على موضع التابوت . وظلل الكروبان التابوت وعصيه من فوق '),
(4330, '2 Chronicles', 14, 5, 9, ' وجذبوا العصي فتراءت رؤوس العصي من التابوت أمام المحراب ولم تر خارجا ، وهي هناك إلى هذا اليوم '),
(4331, '2 Chronicles', 14, 5, 10, ' لم يكن في التابوت إلا اللوحان اللذان وضعهما موسى في حوريب حين عاهد الرب بني إسرائيل عند خروجهم من مصر '),
(4332, '2 Chronicles', 14, 5, 11, ' وكان لما خرج الكهنة من القدس ، لأن جميع الكهنة الموجودين تقدسوا ، لم تلاحظ الفرق '),
(4333, '2 Chronicles', 14, 5, 12, ' واللاويون المغنون أجمعون : آساف وهيمان ويدوثون وبنوهم وإخوتهم ، لابسين كتانا ، بالصنوج والرباب والعيدان واقفين شرقي المذبح ، ومعهم من الكهنة مئة وعشرون ينفخون في الأبواق '),
(4334, '2 Chronicles', 14, 5, 13, ' وكان لما صوت المبوقون والمغنون كواحد ، صوتا واحدا ، لتسبيح الرب وحمده ، ورفعوا صوتا بالأبواق والصنوج وآلات الغناء والتسبيح للرب : لأنه صالح لأن إلى الأبد رحمته . أن البيت ، بيت الرب ، امتلأ سحابا '),
(4335, '2 Chronicles', 14, 5, 14, ' ولم يستطع الكهنة أن يقفوا للخدمة بسبب السحاب ، لأن مجد الرب ملأ بيت الله '),
(4336, '2 Chronicles', 14, 6, 1, ' حينئذ قال سليمان : قال الرب إنه يسكن في الضباب '),
(4337, '2 Chronicles', 14, 6, 2, ' وأنا بنيت لك بيت سكنى مكانا لسكناك إلى الأبد '),
(4338, '2 Chronicles', 14, 6, 3, ' وحول الملك وجهه وبارك كل جمهور إسرائيل ، وكل جمهور إسرائيل واقف '),
(4339, '2 Chronicles', 14, 6, 4, ' وقال : مبارك الرب إله إسرائيل الذي كلم بفمه داود أبي وأكمل بيديه قائلا '),
(4340, '2 Chronicles', 14, 6, 5, ' منذ يوم أخرجت شعبي من أرض مصر لم أختر مدينة من جميع أسباط إسرائيل لبناء بيت ليكون اسمي هناك ، ولا اخترت رجلا يكون رئيسا لشعبي إسرائيل '),
(4341, '2 Chronicles', 14, 6, 6, ' بل اخترت أورشليم ليكون اسمي فيها ، واخترت داود ليكون على شعبي إسرائيل '),
(4342, '2 Chronicles', 14, 6, 7, ' وكان في قلب داود أبي أن يبني بيتا لاسم الرب إله إسرائيل '),
(4343, '2 Chronicles', 14, 6, 8, ' فقال الرب لداود أبي : من أجل أنه كان في قلبك أن تبني بيتا لاسمي ، قد أحسنت بكون ذلك في قلبك '),
(4344, '2 Chronicles', 14, 6, 9, ' إلا أنك أنت لا تبني البيت ، بل ابنك الخارج من صلبك هو يبني البيت لاسمي '),
(4345, '2 Chronicles', 14, 6, 10, ' وأقام الرب كلامه الذي تكلم به ، وقد قمت أنا مكان داود أبي ، وجلست على كرسي إسرائيل كما تكلم الرب ، وبنيت البيت لاسم الرب إله إسرائيل '),
(4346, '2 Chronicles', 14, 6, 11, ' ووضعت هناك التابوت الذي فيه عهد الرب الذي قطعه مع بني إسرائيل '),
(4347, '2 Chronicles', 14, 6, 12, ' ووقف أمام مذبح الرب تجاه كل جماعة إسرائيل وبسط يديه '),
(4348, '2 Chronicles', 14, 6, 13, ' لأن سليمان صنع منبرا من نحاس وجعله في وسط الدار ، طوله خمس أذرع وعرضه خمس أذرع وارتفاعه ثلاث أذرع ، ووقف عليه ، ثم جثا على ركبتيه تجاه كل جماعة إسرائيل وبسط يديه نحو السماء '),
(4349, '2 Chronicles', 14, 6, 14, ' وقال : أيها الرب إله إسرائيل ، لا إله مثلك في السماء والأرض ، حافظ العهد والرحمة لعبيدك السائرين أمامك بكل قلوبهم '),
(4350, '2 Chronicles', 14, 6, 15, ' الذي قد حفظت لعبدك داود أبي ما كلمته به ، فتكلمت بفمك وأكملت بيدك كهذا اليوم '),
(4351, '2 Chronicles', 14, 6, 16, ' والآن أيها الرب إله إسرائيل ، احفظ لعبدك داود أبي ما كلمته به قائلا : لا يعدم لك أمامي رجل يجلس على كرسي إسرائيل ، إن يكن بنوك طرقهم يحفظون حتى يسيروا في شريعتي كما سرت أنت أمامي '),
(4352, '2 Chronicles', 14, 6, 17, ' والآن أيها الرب إله إسرائيل ، فليتحقق كلامك الذي كلمت به عبدك داود '),
(4353, '2 Chronicles', 14, 6, 18, ' لأنه هل يسكن الله حقا مع الإنسان على الأرض ؟ هوذا السماوات وسماء السماوات لا تسعك ، فكم بالأقل هذا البيت الذي بنيت '),
(4354, '2 Chronicles', 14, 6, 19, ' فالتفت إلى صلاة عبدك وإلى تضرعه أيها الرب إلهي ، واسمع الصراخ والصلاة التي يصليها عبدك أمامك '),
(4355, '2 Chronicles', 14, 6, 20, ' لتكون عيناك مفتوحتين على هذا البيت نهارا وليلا على الموضع الذي قلت إنك تضع اسمك فيه ، لتسمع الصلاة التي يصليها عبدك في هذا الموضع '),
(4356, '2 Chronicles', 14, 6, 21, ' واسمع تضرعات عبدك وشعبك إسرائيل الذين يصلون في هذا الموضع ، واسمع أنت من موضع سكناك من السماء ، وإذا سمعت فاغفر '),
(4357, '2 Chronicles', 14, 6, 22, ' إن أخطأ أحد إلى صاحبه ووضع عليه حلف ليحلفه ، وجاء الحلف أمام مذبحك في هذا البيت '),
(4358, '2 Chronicles', 14, 6, 23, ' فاسمع أنت من السماء واعمل ، واقض بين عبيدك إذ تعاقب المذنب فتجعل طريقه على رأسه ، وتبرر البار إذ تعطيه حسب بره '),
(4359, '2 Chronicles', 14, 6, 24, ' وإن انكسر شعبك إسرائيل أمام العدو لكونهم أخطأوا إليك ، ثم رجعوا واعترفوا باسمك وصلوا وتضرعوا أمامك نحو هذا البيت '),
(4360, '2 Chronicles', 14, 6, 25, ' فاسمع أنت من السماء واغفر خطية شعبك إسرائيل ، وأرجعهم إلى الأرض التي أعطيتها لهم ولآبائهم '),
(4361, '2 Chronicles', 14, 6, 26, ' إذا أغلقت السماء ولم يكن مطر لكونهم أخطأوا إليك ، ثم صلوا في هذا المكان واعترفوا باسمك ورجعوا عن خطيتهم لأنك ضايقتهم '),
(4362, '2 Chronicles', 14, 6, 27, ' فاسمع أنت من السماء واغفر خطية عبيدك وشعبك إسرائيل ، فتعلمهم الطريق الصالح الذي يسلكون فيه ، وأعط مطرا على أرضك التي أعطيتها لشعبك ميراثا '),
(4363, '2 Chronicles', 14, 6, 28, ' إذا صار في الأرض جوع ، إذا صار وبأ أو لفح أو يرقان أو جراد أو جردم ، أو إذا حاصرهم أعداؤهم في أرض مدنهم ، في كل ضربة وكل مرض '),
(4364, '2 Chronicles', 14, 6, 29, ' فكل صلاة وكل تضرع تكون من أي إنسان كان ، أو من كل شعبك إسرائيل الذين يعرفون كل واحد ضربته ووجعه ، فيبسط يديه نحو هذا البيت '),
(4365, '2 Chronicles', 14, 6, 30, ' فاسمع أنت من السماء مكان سكناك ، واغفر وأعط كل إنسان حسب كل طرقه كما تعرف قلبه . لأنك أنت وحدك تعرف قلوب بني البشر '),
(4366, '2 Chronicles', 14, 6, 31, ' لكي يخافوك ويسيروا في طرقك كل الأيام التي يحيون فيها على وجه الأرض التي أعطيت لآبائنا '),
(4367, '2 Chronicles', 14, 6, 32, ' وكذلك الأجنبي الذي ليس هو من شعبك إسرائيل ، وقد جاء من أرض بعيدة من أجل اسمك العظيم ويدك القوية وذراعك الممدودة ، فمتى جاءوا وصلوا في هذا البيت '),
(4368, '2 Chronicles', 14, 6, 33, ' فاسمع أنت من السماء مكان سكناك وافعل حسب كل ما يدعوك به الأجنبي ، لكي يعلم كل شعوب الأرض اسمك فيخافوك كشعبك إسرائيل ، ولكي يعلموا أن اسمك قد دعي على هذا البيت الذي بنيت '),
(4369, '2 Chronicles', 14, 6, 34, ' إذا خرج شعبك لمحاربة أعدائه في الطريق الذي ترسلهم فيه وصلوا إليك نحو هذه المدينة التي اخترتها ، والبيت الذي بنيت لاسمك '),
(4370, '2 Chronicles', 14, 6, 35, ' فاسمع من السماء صلاتهم وتضرعهم واقض قضاءهم '),
(4371, '2 Chronicles', 14, 6, 36, ' إذا أخطأوا إليك ، لأنه ليس إنسان لا يخطئ ، وغضبت عليهم ودفعتهم أمام العدو ، وسباهم ، سابوهم إلى أرض بعيدة أو قريبة '),
(4372, '2 Chronicles', 14, 6, 37, ' فإذا ردوا إلى قلوبهم في الأرض التي يسبون إليها ، ورجعوا وتضرعوا إليك في أرض سبيهم قائلين : قد أخطأنا وعوجنا وأذنبنا '),
(4373, '2 Chronicles', 14, 6, 38, ' ورجعوا إليك من كل قلوبهم ومن كل أنفسهم في أرض سبيهم التي سبوهم إليها ، وصلوا نحو أرضهم التي أعطيتها لآبائهم ، والمدينة التي اخترت ، والبيت الذي بنيت لاسمك '),
(4374, '2 Chronicles', 14, 6, 39, ' فاسمع من السماء من مكان سكناك صلاتهم وتضرعاتهم ، واقض قضاءهم ، واغفر لشعبك ما أخطأوا به إليك '),
(4375, '2 Chronicles', 14, 6, 40, ' الآن يا إلهي ، لتكن عيناك مفتوحتين ، وأذناك مصغيتين لصلاة هذا المكان '),
(4376, '2 Chronicles', 14, 6, 41, ' والآن قم أيها الرب الإله إلى راحتك أنت وتابوت عزك . كهنتك أيها الرب الإله يلبسون الخلاص ، وأتقياؤك يبتهجون بالخير '),
(4377, '2 Chronicles', 14, 6, 42, ' أيها الرب الإله ، لا ترد وجه مسيحك . اذكر مراحم داود عبدك '),
(4378, '2 Chronicles', 14, 7, 1, ' ولما انتهى سليمان من الصلاة ، نزلت النار من السماء وأكلت المحرقة والذبائح ، وملأ مجد الرب البيت '),
(4379, '2 Chronicles', 14, 7, 2, ' ولم يستطع الكهنة أن يدخلوا بيت الرب لأن مجد الرب ملأ بيت الرب '),
(4380, '2 Chronicles', 14, 7, 3, ' وكان جميع بني إسرائيل ينظرون عند نزول النار ومجد الرب على البيت ، وخروا على وجوههم إلى الأرض على البلاط المجزع ، وسجدوا وحمدوا الرب لأنه صالح وإلى الأبد رحمته '),
(4381, '2 Chronicles', 14, 7, 4, ' ثم إن الملك وكل الشعب ذبحوا ذبائح أمام الرب '),
(4382, '2 Chronicles', 14, 7, 5, ' وذبح الملك سليمان ذبائح من البقر اثنين وعشرين ألفا ، ومن الغنم مئة وعشرين ألفا ، ودشن الملك وكل الشعب بيت الله '),
(4383, '2 Chronicles', 14, 7, 6, ' وكان الكهنة واقفين على محارسهم ، واللاويون بآلات غناء الرب التي عملها داود الملك لأجل حمد الرب لأن إلى الأبد رحمته حين سبح داود بها ، والكهنة ينفخون في الأبواق مقابلهم ، وكل إسرائيل واقف '),
(4384, '2 Chronicles', 14, 7, 7, ' وقدس سليمان وسط الدار التي أمام بيت الرب ، لأنه قرب هناك المحرقات وشحم ذبائح السلامة ، لأن مذبح النحاس الذي عمله سليمان لم يكف لأن يسع المحرقات والتقدمات والشحم '),
(4385, '2 Chronicles', 14, 7, 8, ' وعيد سليمان العيد في ذلك الوقت سبعة أيام ، وكل إسرائيل معه وجمهور عظيم جدا من مدخل حماة إلى وادي مصر '),
(4386, '2 Chronicles', 14, 7, 9, ' وعملوا في اليوم الثامن اعتكافا لأنهم عملوا تدشين المذبح سبعة أيام ، والعيد سبعة أيام '),
(4387, '2 Chronicles', 14, 7, 10, ' وفي اليوم الثالث والعشرين من الشهر السابع صرف الشعب إلى خيامهم فرحين وطيبي القلوب ، لأجل الخير الذي عمله الرب لداود ولسليمان ولإسرائيل شعبه '),
(4388, '2 Chronicles', 14, 14, 7, ' وقال ليهوذا : لنبن هذه المدن ونحوطها بأسوار وأبراج وأبواب وعوارض ما دامت الأرض أمامنا ، لأننا قد طلبنا الرب إلهنا . طلبناه فأراحنا من كل جهة . فبنوا ونجحوا '),
(4389, '2 Chronicles', 14, 14, 8, ' وكان لآسا جيش يحملون أتراسا ورماحا من يهوذا ، ثلاث مئة ألف ، ومن بنيامين من الذين يحملون الأتراس ويشدون القسي مئتان وثمانون ألفا . كل هؤلاء جبابرة بأس '),
(4390, '2 Chronicles', 14, 14, 9, ' فخرج إليهم زارح الكوشي بجيش ألف ألف ، وبمركبات ثلاث مئة ، وأتى إلى مريشة '),
(4391, '2 Chronicles', 14, 14, 10, ' وخرج آسا للقائه واصطفوا للقتال في وادي صفاتة عند مريشة '),
(4392, '2 Chronicles', 14, 14, 11, ' ودعا آسا الرب إلهه وقال : أيها الرب ، ليس فرقا عندك أن تساعد الكثيرين ومن ليس لهم قوة . فساعدنا أيها الرب إلهنا ، لأننا عليك اتكلنا وباسمك قدمنا على هذا الجيش . أيها الرب أنت إلهنا . لا يقو عليك إنسان '),
(4393, '2 Chronicles', 14, 14, 12, ' فضرب الرب الكوشيين أمام آسا وأمام يهوذا ، فهرب الكوشيون '),
(4394, '2 Chronicles', 14, 14, 13, ' وطردهم آسا والشعب الذي معه إلى جرار ، وسقط من الكوشيين حتى لم يكن لهم حي ، لأنهم انكسروا أمام الرب وأمام جيشه . فحملوا غنيمة كثيرة جدا '),
(4395, '2 Chronicles', 14, 14, 14, ' وضربوا جميع المدن التي حول جرار ، لأن رعب الرب كان عليهم ، ونهبوا كل المدن لأنه كان فيها نهب كثير '),
(4396, '2 Chronicles', 14, 14, 15, ' وضربوا أيضا خيام الماشية وساقوا غنما كثيرا وجمالا ، ثم رجعوا إلى أورشليم '),
(4397, '2 Chronicles', 14, 15, 1, ' وكان روح الله على عزريا بن عوديد '),
(4398, '2 Chronicles', 14, 15, 2, ' فخرج للقاء آسا وقال له : اسمعوا لي يا آسا وجميع يهوذا وبنيامين . الرب معكم ما كنتم معه ، وإن طلبتموه يوجد لكم ، وإن تركتموه يترككم '),
(4399, '2 Chronicles', 14, 15, 3, ' ولإسرائيل أيام كثيرة بلا إله حق وبلا كاهن معلم وبلا شريعة '),
(4400, '2 Chronicles', 14, 15, 4, ' ولكن لما رجعوا عندما تضايقوا إلى الرب إله إسرائيل وطلبوه وجد لهم '),
(4401, '2 Chronicles', 14, 15, 5, ' وفي تلك الأزمان لم يكن أمان للخارج ولا للداخل ، لأن اضطرابات كثيرة كانت على كل سكان الأراضي '),
(4402, '2 Chronicles', 14, 15, 6, ' فأفنيت أمة بأمة ومدينة بمدينة ، لأن الله أزعجهم بكل ضيق '),
(4403, '2 Chronicles', 14, 15, 7, ' فتشددوا أنتم ولا ترتخ أيديكم لأن لعملكم أجرا '),
(4404, '2 Chronicles', 14, 15, 8, ' فلما سمع آسا هذا الكلام ونبوة عوديد النبي ، تشدد ونزع الرجاسات من كل أرض يهوذا وبنيامين ومن المدن التي أخذها من جبل أفرايم ، وجدد مذبح الرب الذي أمام رواق الرب '),
(4405, '2 Chronicles', 14, 15, 9, ' وجمع كل يهوذا وبنيامين والغرباء معهم من أفرايم ومنسى ومن شمعون ، لأنهم سقطوا إليه من إسرائيل بكثرة حين رأوا أن الرب إلهه معه '),
(4406, '2 Chronicles', 14, 15, 10, ' فاجتمعوا في أورشليم في الشهر الثالث ، في السنة الخامسة عشرة لملك آسا '),
(4407, '2 Chronicles', 14, 15, 11, ' وذبحوا للرب في ذلك اليوم من الغنيمة التي جلبوا سبع مئة من البقر ، وسبعة آلاف من الضأن '),
(4408, '2 Chronicles', 14, 15, 12, ' ودخلوا في عهد أن يطلبوا الرب إله آبائهم بكل قلوبهم وكل أنفسهم '),
(4409, '2 Chronicles', 14, 15, 13, ' حتى إن كل من لا يطلب الرب إله إسرائيل يقتل من الصغير إلى الكبير ، من الرجال والنساء '),
(4410, '2 Chronicles', 14, 15, 14, ' وحلفوا للرب بصوت عظيم وهتاف وبأبواق وقرون '),
(4411, '2 Chronicles', 14, 15, 15, ' وفرح كل يهوذا من أجل الحلف ، لأنهم حلفوا بكل قلوبهم ، وطلبوه بكل رضاهم فوجد لهم ، وأراحهم الرب من كل جهة '),
(4412, '2 Chronicles', 14, 15, 16, ' حتى إن معكة أم آسا الملك خلعها من أن تكون ملكة لأنها عملت لسارية تمثالا ، وقطع آسا تمثالها ودقه وأحرقه في وادي قدرون '),
(4413, '2 Chronicles', 14, 15, 17, ' وأما المرتفعات فلم تنزع من إسرائيل . إلا أن قلب آسا كان كاملا كل أيامه '),
(4414, '2 Chronicles', 14, 15, 18, ' وأدخل أقداس أبيه وأقداسه إلى بيت الله من الفضة والذهب والآنية '),
(4415, '2 Chronicles', 14, 15, 19, ' ولم تكن حرب إلى السنة الخامسة والثلاثين لملك آسا '),
(4416, '2 Chronicles', 14, 16, 1, ' في السنة السادسة والثلاثين لملك آسا صعد بعشا ملك إسرائيل على يهوذا ، وبنى الرامة لكيلا يدع أحدا يخرج أو يدخل إلى آسا ملك يهوذا '),
(4417, '2 Chronicles', 14, 16, 2, ' وأخرج آسا فضة وذهبا من خزائن بيت الرب وبيت الملك ، وأرسل إلى بنهدد ملك أرام الساكن في دمشق قائلا '),
(4418, '2 Chronicles', 14, 16, 3, ' إن بيني وبينك ، وبين أبي وأبيك عهدا . هوذا قد أرسلت لك فضة وذهبا ، فتعال انقض عهدك مع بعشا ملك إسرائيل فيصعد عني '),
(4419, '2 Chronicles', 14, 16, 4, ' فسمع بنهدد للملك آسا ، وأرسل رؤساء الجيوش التي له على مدن إسرائيل ، فضربوا عيون ودان وآبل المياه وجميع مخازن مدن نفتالي '),
(4420, '2 Chronicles', 14, 16, 5, ' فلما سمع بعشا كف عن بناء الرامة وترك عمله '),
(4421, '2 Chronicles', 14, 16, 6, ' فأخذ آسا الملك كل يهوذا ، فحملوا حجارة الرامة وأخشابها التي بنى بها بعشا ، وبنى بها جبع والمصفاة '),
(4422, '2 Chronicles', 14, 16, 7, ' وفي ذلك الزمان جاء حناني الرائي إلى آسا ملك يهوذا وقال له : من أجل أنك استندت على ملك أرام ولم تستند على الرب إلهك ، لذلك قد نجا جيش ملك أرام من يدك '),
(4423, '2 Chronicles', 14, 16, 8, ' ألم يكن الكوشيون واللوبيون جيشا كثيرا بمركبات وفرسان كثيرة جدا ؟ فمن أجل أنك استندت على الرب دفعهم ليدك '),
(4424, '2 Chronicles', 14, 16, 9, ' لأن عيني الرب تجولان في كل الأرض ليتشدد مع الذين قلوبهم كاملة نحوه ، فقد حمقت في هذا حتى إنه من الآن تكون عليك حروب '),
(4425, '2 Chronicles', 14, 16, 10, ' فغضب آسا على الرائي ووضعه في السجن ، لأنه اغتاظ منه من أجل هذا ، وضايق آسا بعضا من الشعب في ذلك الوقت '),
(4426, '2 Chronicles', 14, 16, 11, ' وأمور آسا الأولى والأخيرة ، ها هي مكتوبة في سفر الملوك ليهوذا وإسرائيل '),
(4427, '2 Chronicles', 14, 16, 12, ' ومرض آسا في السنة التاسعة والثلاثين من ملكه في رجليه حتى اشتد مرضه ، وفي مرضه أيضا لم يطلب الرب بل الأطباء '),
(4428, '2 Chronicles', 14, 16, 13, ' ثم اضطجع آسا مع آبائه ومات في السنة الحادية والأربعين لملكه '),
(4429, '2 Chronicles', 14, 16, 14, ' فدفنوه في قبوره التي حفرها لنفسه في مدينة داود ، وأضجعوه في سرير كان مملوا أطيابا وأصنافا عطرة حسب صناعة العطارة . وأحرقوا له حريقة عظيمة جدا '),
(4430, '2 Chronicles', 14, 17, 1, ' وملك يهوشافاط ابنه عوضا عنه وتشدد على إسرائيل '),
(4431, '2 Chronicles', 14, 17, 2, ' وجعل جيشا في جميع مدن يهوذا الحصينة ، وجعل وكلاء في أرض يهوذا وفي مدن أفرايم التي أخذها آسا أبوه '),
(4432, '2 Chronicles', 14, 17, 3, ' وكان الرب مع يهوشافاط لأنه سار في طرق داود أبيه الأولى ، ولم يطلب البعليم '),
(4433, '2 Chronicles', 14, 17, 4, ' ولكنه طلب إله أبيه وسار في وصاياه لا حسب أعمال إسرائيل '),
(4434, '2 Chronicles', 14, 17, 5, ' فثبت الرب المملكة في يده ، وقدم كل يهوذا هدايا ليهوشافاط . وكان له غنى وكرامة بكثرة '),
(4435, '2 Chronicles', 14, 17, 6, ' وتقوى قلبه في طرق الرب ، ونزع أيضا المرتفعات والسواري من يهوذا '),
(4436, '2 Chronicles', 14, 17, 7, ' وفي السنة الثالثة لملكه أرسل إلى رؤسائه ، إلى بنحائل وعوبديا وزكريا ونثنئيل وميخايا أن يعلموا في مدن يهوذا '),
(4437, '2 Chronicles', 14, 17, 8, ' ومعهم اللاويون شمعيا ونثنيا وزبديا وعسائيل وشميراموث ويهوناثان وأدونيا وطوبيا وطوب أدونيا اللاويون ، ومعهم أليشمع ويهورام الكاهنان '),
(4438, '2 Chronicles', 14, 17, 9, ' فعلموا في يهوذا ومعهم سفر شريعة الرب ، وجالوا في جميع مدن يهوذا وعلموا الشعب '),
(4439, '2 Chronicles', 14, 17, 10, ' وكانت هيبة الرب على جميع ممالك الأراضي التي حول يهوذا فلم يحاربوا يهوشافاط '),
(4440, '2 Chronicles', 14, 17, 11, ' وبعض الفلسطينيين أتوا يهوشافاط بهدايا وحمل فضة ، والعربان أيضا أتوه بغنم : من الكباش سبعة آلاف وسبع مئة ، ومن التيوس سبعة آلاف وسبع مئة '),
(4441, '2 Chronicles', 14, 17, 12, ' وكان يهوشافاط يتعظم جدا ، وبنى في يهوذا حصونا ومدن مخازن '),
(4442, '2 Chronicles', 14, 17, 13, ' وكان له شغل كثير في مدن يهوذا ، ورجال حرب جبابرة بأس في أورشليم '),
(4443, '2 Chronicles', 14, 17, 14, ' وهذا عددهم حسب بيوت آبائهم من يهوذا رؤساء ألوف : عدنة الرئيس ومعه جبابرة بأس ثلاث مئة ألف '),
(4444, '2 Chronicles', 14, 17, 15, ' وبجانبه يهوناثان الرئيس ومعه مئتان وثمانون ألفا '),
(4445, '2 Chronicles', 14, 17, 16, ' وبجانبه عمسيا بن زكري المنتدب للرب ومعه مئتا ألف جبار بأس '),
(4446, '2 Chronicles', 14, 17, 17, ' ومن بنيامين ألياداع جبار بأس ومعه من المتسلحين بالقسي والأتراس مئتا ألف '),
(4447, '2 Chronicles', 14, 17, 18, ' وبجانبه يهوزاباد ومعه مئة وثمانون ألفا متجردون للحرب '),
(4448, '2 Chronicles', 14, 17, 19, ' هؤلاء خدام الملك ، فضلا عن الذين جعلهم الملك في المدن الحصينة في كل يهوذا '),
(4449, '2 Chronicles', 14, 18, 1, ' وكان ليهوشافاط غنى وكرامة بكثرة . وصاهر أخآب '),
(4450, '2 Chronicles', 14, 18, 2, ' ونزل بعد سنين إلى أخآب إلى السامرة ، فذبح أخآب غنما وبقرا بكثرة له وللشعب الذي معه ، وأغواه أن يصعد إلى راموت جلعاد '),
(4451, '2 Chronicles', 14, 18, 3, ' وقال أخآب ملك إسرائيل ليهوشافاط ملك يهوذا : أتذهب معي إلى راموت جلعاد ؟  . وقال له : مثلي مثلك وشعبي كشعبك ومعك في القتال '),
(4452, '2 Chronicles', 14, 18, 4, ' ثم قال يهوشافاط لملك إسرائيل : اسأل اليوم عن كلام الرب '),
(4453, '2 Chronicles', 14, 18, 5, ' فجمع ملك إسرائيل الأنبياء ، أربع مئة رجل ، وقال لهم : أنذهب إلى راموت جلعاد للقتال أم أمتنع ؟  . فقالوا : اصعد فيدفعها الله ليد الملك '),
(4454, '2 Chronicles', 14, 18, 6, ' فقال يهوشافاط : أليس هنا أيضا نبي للرب فنسأل منه '),
(4455, '2 Chronicles', 14, 18, 7, ' فقال ملك إسرائيل ليهوشافاط : بعد رجل واحد لسؤال الرب به ، ولكنني أبغضه لأنه لا يتنبأ علي خيرا بل شرا كل أيامه ، وهو ميخا بن يملة . فقال يهوشافاط : لا يقل الملك هكذا '),
(4456, '2 Chronicles', 14, 18, 8, ' فدعا ملك إسرائيل خصيا وقال : أسرع بميخا بن يملة '),
(4457, '2 Chronicles', 14, 18, 9, ' وكان ملك إسرائيل ويهوشافاط ملك يهوذا جالسين كل واحد على كرسيه ، لابسين ثيابهما وجالسين في ساحة عند مدخل باب السامرة ، وجميع الأنبياء يتنبأون أمامهما '),
(4458, '2 Chronicles', 14, 18, 10, ' وعمل صدقيا بن كنعنة لنفسه قرون حديد وقال : هكذا قال الرب : بهذه تنطح الأراميين حتى يفنوا '),
(4459, '2 Chronicles', 14, 18, 11, ' وتنبأ جميع الأنبياء هكذا قائلين : اصعد إلى راموت جلعاد وأفلح ، فيدفعها الرب ليد الملك '),
(4460, '2 Chronicles', 14, 18, 12, ' وأما الرسول الذي ذهب ليدعو ميخا فكلمه قائلا : هوذا كلام جميع الأنبياء بفم واحد خير للملك . فليكن كلامك كواحد منهم وتكلم بخير '),
(4461, '2 Chronicles', 14, 18, 13, ' فقال ميخا : حي هو الرب ، إن ما يقوله إلهي فبه أتكلم '),
(4462, '2 Chronicles', 14, 18, 14, ' ولما جاء إلى الملك قال له الملك : يا ميخا ، أنذهب إلى راموت جلعاد للقتال أم أمتنع ؟  . فقال : اصعدوا وأفلحوا فيدفعوا ليدكم '),
(4463, '2 Chronicles', 14, 1, 1, ' وتشدد سليمان بن داود على مملكته ، وكان الرب إلهه معه وعظمه جدا '),
(4464, '2 Chronicles', 14, 1, 2, ' وكلم سليمان جميع إسرائيل ، رؤساء الألوف والمئات والقضاة وكل رئيس في كل إسرائيل رؤوس الآباء '),
(4465, '2 Chronicles', 14, 1, 3, ' فذهب سليمان وكل الجماعة معه إلى المرتفعة التي في جبعون ، لأنه هناك كانت خيمة الاجتماع ، خيمة الله التي عملها موسى عبد الرب في البرية '),
(4466, '2 Chronicles', 14, 1, 4, ' وأما تابوت الله فأصعده داود من قرية يعاريم عندما هيأ له داود ، لأنه نصب له خيمة في أورشليم '),
(4467, '2 Chronicles', 14, 1, 5, ' ومذبح النحاس الذي عمله بصلئيل بن أوري بن حور ، وضعه أمام مسكن الرب ، وطلب إليه سليمان والجماعة '),
(4468, '2 Chronicles', 14, 1, 6, ' وأصعد سليمان هناك على مذبح النحاس أمام الرب الذي كان في خيمة الاجتماع ، أصعد عليه ألف محرقة '),
(4469, '2 Chronicles', 14, 1, 7, ' في تلك الليلة تراءى الله لسليمان وقال له : اسأل ماذا أعطيك '),
(4470, '2 Chronicles', 14, 1, 8, ' فقال سليمان لله : إنك قد فعلت مع داود أبي رحمة عظيمة وملكتني مكانه '),
(4471, '2 Chronicles', 14, 1, 9, ' فالآن أيها الرب الإله ، ليثبت كلامك مع داود أبي ، لأنك قد ملكتني على شعب كثير كتراب الأرض '),
(4472, '2 Chronicles', 14, 1, 10, ' فأعطني الآن حكمة ومعرفة لأخرج أمام هذا الشعب وأدخل ، لأنه من يقدر أن يحكم على شعبك هذا العظيم '),
(4473, '2 Chronicles', 14, 1, 11, ' فقال الله لسليمان : من أجل أن هذا كان في قلبك ، ولم تسأل غنى ولا أموالا ولا كرامة ولا أنفس مبغضيك ، ولا سألت أياما كثيرة ، بل إنما سألت لنفسك حكمة ومعرفة تحكم بهما على شعبي الذي ملكتك عليه '),
(4474, '2 Chronicles', 14, 1, 12, ' قد أعطيتك حكمة ومعرفة ، وأعطيك غنى وأموالا وكرامة لم يكن مثلها للملوك الذين قبلك ، ولا يكون مثلها لمن بعدك '),
(4475, '2 Chronicles', 14, 1, 13, ' فجاء سليمان من المرتفعة التي في جبعون إلى أورشليم من أمام خيمة الاجتماع وملك على إسرائيل '),
(4476, '2 Chronicles', 14, 1, 14, ' وجمع سليمان مركبات وفرسانا ، فكان له ألف وأربع مئة مركبة واثنا عشر ألف فارس ، فجعلها في مدن المركبات ومع الملك في أورشليم '),
(4477, '2 Chronicles', 14, 1, 15, ' وجعل الملك الفضة والذهب في أورشليم مثل الحجارة ، وجعل الأرز كالجميز الذي في السهل في الكثرة '),
(4478, '2 Chronicles', 14, 1, 16, ' وكان مخرج الخيل التي لسليمان من مصر . وجماعة تجار الملك أخذوا جليبة بثمن '),
(4479, '2 Chronicles', 14, 1, 17, ' فأصعدوا وأخرجوا من مصر المركبة بست مئة شاقل من الفضة ، والفرس بمئة وخمسين ، وهكذا لجميع ملوك الحثيين وملوك أرام كانوا يخرجون عن يدهم '),
(4480, '2 Chronicles', 14, 2, 1, ' وأمر سليمان ببناء بيت لاسم الرب ، وبيت لملكه '),
(4481, '2 Chronicles', 14, 2, 2, ' وأحصى سليمان سبعين ألف رجل حمال ، وثمانين ألف رجل نحات في الجبل ، ووكلاء عليهم ثلاثة آلاف وست مئة '),
(4482, '2 Chronicles', 14, 2, 3, ' وأرسل سليمان إلى حورام ملك صور قائلا : كما فعلت مع داود أبي إذ أرسلت له أرزا ليبني له بيتا يسكن فيه '),
(4483, '2 Chronicles', 14, 2, 4, ' فهأنذا أبني بيتا لاسم الرب إلهي لأقدسه له ، لأوقد أمامه بخورا عطرا ، ولخبز الوجوه الدائم ، وللمحرقات صباحا ومساء ، وللسبوت والأهلة ومواسم الرب إلهنا . هذا على إسرائيل إلى الأبد '),
(4484, '2 Chronicles', 14, 2, 5, ' والبيت الذي أنا بانيه عظيم لأن إلهنا أعظم من جميع الآلهة '),
(4485, '2 Chronicles', 14, 2, 6, ' ومن يستطيع أن يبني له بيتا ، لأن السماوات وسماء السماوات لا تسعه ومن أنا حتى أبني له بيتا إلا للإيقاد أمامه '),
(4486, '2 Chronicles', 14, 2, 7, ' فالآن أرسل لي رجلا حكيما في صناعة الذهب والفضة والنحاس والحديد والأرجوان والقرمز والأسمانجوني ، ماهرا في النقش ، مع الحكماء الذين عندي في يهوذا وفي أورشليم الذين أعدهم داود أبي '),
(4487, '2 Chronicles', 14, 2, 8, ' وأرسل لي خشب أرز وسرو وصندل من لبنان ، لأني أعلم أن عبيدك ماهرون في قطع خشب لبنان . وهوذا عبيدي مع عبيدك '),
(4488, '2 Chronicles', 14, 2, 9, ' وليعدوا لي خشبا بكثرة لأن البيت الذي أبنيه عظيم وعجيب '),
(4489, '2 Chronicles', 14, 2, 10, ' وهأنذا أعطي للقطاعين القاطعين الخشب عشرين ألف كر من الحنطة طعاما لعبيدك ، وعشرين ألف كر شعير ، وعشرين ألف بث خمر ، وعشرين ألف بث زيت '),
(4490, '2 Chronicles', 14, 2, 11, ' فقال حورام ملك صور بكتابة أرسلها إلى سليمان : لأن الرب قد أحب شعبه جعلك عليهم ملكا '),
(4491, '2 Chronicles', 14, 2, 12, ' وقال حورام : مبارك الرب إله إسرائيل الذي صنع السماء والأرض ، الذي أعطى داود الملك ابنا حكيما صاحب معرفة وفهم ، الذي يبني بيتا للرب وبيتا لملكه '),
(4492, '2 Chronicles', 14, 2, 13, ' والآن أرسلت رجلا حكيما صاحب فهم حورام أبي '),
(4493, '2 Chronicles', 14, 2, 14, ' ابن امرأة من بنات دان ، وأبوه رجل صوري ماهر في صناعة الذهب والفضة والنحاس والحديد والحجارة والخشب والأرجوان والأسمانجوني والكتان والقرمز ، ونقش كل نوع من النقش ، واختراع كل اختراع يلقى عليه ، مع حكمائك وحكماء سيدي داود أبيك '),
(4494, '2 Chronicles', 14, 2, 15, ' والآن الحنطة والشعير والزيت والخمر التي ذكرها سيدي فليرسلها لعبيده '),
(4495, '2 Chronicles', 14, 2, 16, ' ونحن نقطع خشبا من لبنان حسب كل احتياجك ، ونأتي به إليك أرماثا على البحر إلى يافا ، وأنت تصعده إلى أورشليم '),
(4496, '2 Chronicles', 14, 2, 17, ' وعد سليمان جميع الرجال الأجنبيين الذين في أرض إسرائيل ، بعد العد الذي عدهم إياه داود أبوه ، فوجدوا مئة وثلاثة وخمسين ألفا وست مئة '),
(4497, '2 Chronicles', 14, 2, 18, ' فجعل منهم سبعين ألف حمال ، وثمانين ألف قطاع على الجبل ، وثلاثة آلاف وست مئة وكلاء لتشغيل الشعب '),
(4498, '2 Chronicles', 14, 3, 1, ' وشرع سليمان في بناء بيت الرب في أورشليم ، في جبل المريا حيث تراءى لداود أبيه ، حيث هيأ داود مكانا في بيدر أرنان اليبوسي '),
(4499, '2 Chronicles', 14, 3, 2, ' وشرع في البناء في ثاني الشهر الثاني ، في السنة الرابعة لملكه '),
(4500, '2 Chronicles', 14, 3, 3, ' وهذه أسسها سليمان لبناء بيت الله : الطول بالذراع على القياس الأول ستون ذراعا ، والعرض عشرون ذراعا '),
(4501, '2 Chronicles', 14, 3, 4, ' والرواق الذي قدام الطول حسب عرض البيت عشرون ذراعا ، وارتفاعه مئة وعشرون ، وغشاه من داخل بذهب خالص '),
(4502, '2 Chronicles', 14, 3, 5, ' والبيت العظيم غشاه بخشب سرو ، غشاه بذهب خالص ، وجعل عليه نخيلا وسلاسل '),
(4503, '2 Chronicles', 14, 3, 6, ' ورصع البيت بحجارة كريمة للجمال . والذهب ذهب فروايم '),
(4504, '2 Chronicles', 14, 3, 7, ' وغشى البيت : أخشابه وأعتابه وحيطانه ومصاريعه بذهب ، ونقش كروبيم على الحيطان '),
(4505, '2 Chronicles', 14, 3, 8, ' وعمل بيت قدس الأقداس ، طوله حسب عرض البيت عشرون ذراعا ، وعرضه عشرون ذراعا ، وغشاه بذهب جيد ست مئة وزنة '),
(4506, '2 Chronicles', 14, 3, 9, ' وكان وزن المسامير خمسين شاقلا من ذهب ، وغشى العلالي بذهب '),
(4507, '2 Chronicles', 14, 3, 10, ' وعمل في بيت قدس الأقداس كروبين صناعة الصياغة ، وغشاهما بذهب '),
(4508, '2 Chronicles', 14, 3, 11, ' وأجنحة الكروبين طولها عشرون ذراعا ، الجناح الواحد خمس أذرع يمس حائط البيت ، والجناح الآخر خمس أذرع يمس جناح الكروب الآخر '),
(4509, '2 Chronicles', 14, 3, 12, ' وجناح الكروب الآخر خمس أذرع يمس حائط البيت ، والجناح الآخر خمس أذرع يتصل بجناح الكروب الآخر '),
(4510, '2 Chronicles', 14, 3, 13, ' وأجنحة هذين الكروبين منبسطة عشرون ذراعا ، وهما واقفان على أرجلهما ووجههما إلى داخل '),
(4511, '2 Chronicles', 14, 3, 14, ' وعمل الحجاب من أسمانجوني وأرجوان وقرمز وكتان ، وجعل عليه كروبيم '),
(4512, '2 Chronicles', 14, 3, 15, ' وعمل أمام البيت عمودين ، طولهما خمس وثلاثون ذراعا ، والتاجان اللذان على رأسيهما خمس أذرع '),
(4513, '2 Chronicles', 14, 3, 16, ' وعمل سلاسل كما في المحراب وجعلها على رأسي العمودين ، وعمل مئة رمانة وجعلها في السلاسل '),
(4514, '2 Chronicles', 14, 3, 17, ' وأوقف العمودين أمام الهيكل ، واحدا عن اليمين وواحدا عن اليسار ، ودعا اسم الأيمن ياكين واسم الأيسر بوعز '),
(4515, '2 Chronicles', 14, 4, 1, ' وعمل مذبح نحاس طوله عشرون ذراعا ، وعرضه عشرون ذراعا ، وارتفاعه عشر أذرع '),
(4516, '2 Chronicles', 14, 4, 2, ' وعمل البحر مسبوكا عشر أذرع من شفته إلى شفته ، وكان مدورا مستديرا وارتفاعه خمس أذرع ، وخيط ثلاثون ذراعا يحيط بدائره '),
(4517, '2 Chronicles', 14, 4, 3, ' وشبه قثاء تحته مستديرا يحيط به على استدارته ، للذراع عشر تحيط بالبحر مستديرة ، والقثاء صفان قد سبكت بسبكه '),
(4518, '2 Chronicles', 14, 4, 4, ' كان قائما على اثني عشر ثورا ، ثلاثة متجهة إلى الشمال ، وثلاثة متجهة إلى الغرب ، وثلاثة متجهة إلى الجنوب ، وثلاثة متجهة إلى الشرق ، والبحر عليها من فوق ، وجميع أعجازها إلى داخل '),
(4519, '2 Chronicles', 14, 4, 5, ' وغلظه شبر ، وشفته كعمل شفة كأس بزهر سوسن . يأخذ ويسع ثلاثة آلاف بث '),
(4520, '2 Chronicles', 14, 4, 6, ' وعمل عشر مراحض ، وجعل خمسا عن اليمين وخمسا عن اليسار ، للاغتسال فيها . كانوا يغسلون فيها ما يقربونه محرقة ، والبحر لكي يغتسل فيه الكهنة '),
(4521, '2 Chronicles', 14, 4, 7, ' وعمل منائر ذهب عشرا كرسمها ، وجعلها في الهيكل ، خمسا عن اليمين وخمسا عن اليسار '),
(4522, '2 Chronicles', 14, 4, 8, ' وعمل عشر موائد ووضعها في الهيكل ، خمسا عن اليمين وخمسا عن اليسار . وعمل مئة منضحة من ذهب '),
(4523, '2 Chronicles', 14, 4, 9, ' وعمل دار الكهنة والدار العظيمة ومصاريع الدار ، وغشى مصاريعها بنحاس '),
(4524, '2 Chronicles', 14, 4, 10, ' وجعل البحر إلى الجانب الأيمن إلى الشرق من جهة الجنوب '),
(4525, '2 Chronicles', 14, 4, 11, ' وعمل حورام القدور والرفوش والمناضح . وانتهى حورام من عمل العمل الذي صنعه للملك سليمان في بيت الله '),
(4526, '2 Chronicles', 14, 4, 12, ' العمودين وكرتي التاجين على رأسي العمودين ، والشبكتين لتغطية كرتي التاجين اللذين على رأسي العمودين '),
(4527, '2 Chronicles', 14, 4, 13, ' والرمانات الأربع مئة للشبكتين ، صفي رمان للشبكة الواحدة لتغطية كرتي التاجين اللذين على العمودين '),
(4528, '2 Chronicles', 14, 7, 11, ' وأكمل سليمان بيت الرب وبيت الملك . وكل ما خطر ببال سليمان أن يعمله في بيت الرب وفي بيته نجح فيه '),
(4529, '2 Chronicles', 14, 7, 12, ' وتراءى الرب لسليمان ليلا وقال له : قد سمعت صلاتك ، واخترت هذا المكان لي بيت ذبيحة '),
(4530, '2 Chronicles', 14, 7, 13, ' إن أغلقت السماء ولم يكن مطر ، وإن أمرت الجراد أن يأكل الأرض ، وإن أرسلت وبأ على شعبي '),
(4531, '2 Chronicles', 14, 7, 14, ' فإذا تواضع شعبي الذين دعي اسمي عليهم وصلوا وطلبوا وجهي ، ورجعوا عن طرقهم الردية فإنني أسمع من السماء وأغفر خطيتهم وأبرئ أرضهم '),
(4532, '2 Chronicles', 14, 7, 15, ' الآن عيناي تكونان مفتوحتين ، وأذناي مصغيتين إلى صلاة هذا المكان '),
(4533, '2 Chronicles', 14, 7, 16, ' والآن قد اخترت وقدست هذا البيت ليكون اسمي فيه إلى الأبد ، وتكون عيناي وقلبي هناك كل الأيام '),
(4534, '2 Chronicles', 14, 7, 17, ' وأنت إن سلكت أمامي كما سلك داود أبوك ، وعملت حسب كل ما أمرتك به ، وحفظت فرائضي وأحكامي '),
(4535, '2 Chronicles', 14, 7, 18, ' فإني أثبت كرسي ملكك كما عاهدت داود أباك قائلا : لا يعدم لك رجل يتسلط على إسرائيل '),
(4536, '2 Chronicles', 14, 7, 19, ' ولكن إن انقلبتم وتركتم فرائضي ووصاياي التي جعلتها أمامكم ، وذهبتم وعبدتم آلهة أخرى وسجدتم لها '),
(4537, '2 Chronicles', 14, 7, 20, ' فإني أقلعهم من أرضي التي أعطيتهم إياها ، وهذا البيت الذي قدسته لاسمي أطرحه من أمامي وأجعله مثلا وهزأة في جميع الشعوب '),
(4538, '2 Chronicles', 14, 7, 21, ' وهذا البيت الذي كان مرتفعا ، كل من يمر به يتعجب ويقول : لماذا عمل الرب هكذا لهذه الأرض ولهذا البيت '),
(4539, '2 Chronicles', 14, 7, 22, ' فيقولون : من أجل أنهم تركوا الرب إله آبائهم الذي أخرجهم من أرض مصر ، وتمسكوا بآلهة أخرى وسجدوا لها وعبدوها ، لذلك جلب عليهم كل هذا الشر '),
(4540, '2 Chronicles', 14, 8, 1, ' وبعد نهاية عشرين سنة ، بعد أن بنى سليمان بيت الرب وبيته '),
(4541, '2 Chronicles', 14, 8, 2, ' بنى سليمان المدن التي أعطاها حورام لسليمان ، وأسكن فيها بني إسرائيل '),
(4542, '2 Chronicles', 14, 8, 3, ' وذهب سليمان إلى حماة صوبة وقوي عليها '),
(4543, '2 Chronicles', 14, 8, 4, ' وبنى تدمر في البرية وجميع مدن المخازن التي بناها في حماة '),
(4544, '2 Chronicles', 14, 8, 5, ' وبنى بيت حورون العليا وبيت حورون السفلى ، مدنا حصينة بأسوار وأبواب وعوارض '),
(4545, '2 Chronicles', 14, 8, 6, ' وبعلة وكل مدن المخازن التي كانت لسليمان ، وجميع مدن المركبات ومدن الفرسان ، وكل مرغوب سليمان الذي رغب أن يبنيه في أورشليم وفي لبنان وفي كل أرض سلطانه '),
(4546, '2 Chronicles', 14, 8, 7, ' أما جميع الشعب الباقي من الحثيين والأموريين والفرزيين والحويين واليبوسيين الذين ليسوا من إسرائيل '),
(4547, '2 Chronicles', 14, 8, 8, ' من بينهم ، الذين بقوا بعدهم في الأرض ، الذين لم يفنهم بنو إسرائيل ، فجعل سليمان عليهم سخرة إلى هذا اليوم '),
(4548, '2 Chronicles', 14, 8, 9, ' وأما بنو إسرائيل فلم يجعل سليمان منهم عبيدا لشغله ، لأنهم رجال القتال ورؤساء قواده ورؤساء مركباته وفرسانه '),
(4549, '2 Chronicles', 14, 8, 10, ' وهؤلاء رؤساء الموكلين الذين للملك سليمان ، مئتان وخمسون المتسلطون على الشعب '),
(4550, '2 Chronicles', 14, 8, 11, ' وأما بنت فرعون فأصعدها سليمان من مدينة داود إلى البيت الذي بناه لها ، لأنه قال : لا تسكن امرأة لي في بيت داود ملك إسرائيل ، لأن الأماكن التي دخل إليها تابوت الرب إنما هي مقدسة '),
(4551, '2 Chronicles', 14, 8, 12, ' حينئذ أصعد سليمان محرقات للرب على مذبح الرب الذي بناه قدام الرواق '),
(4552, '2 Chronicles', 14, 8, 13, ' أمر كل يوم بيومه من المحرقات حسب وصية موسى في السبوت والأهلة والمواسم ، ثلاث مرات في السنة ، في عيد الفطير وعيد الأسابيع وعيد المظال '),
(4553, '2 Chronicles', 14, 8, 14, ' وأوقف حسب قضاء داود أبيه فرق الكهنة على خدمتهم واللاويين على حراساتهم ، للتسبيح والخدمة أمام الكهنة ، عمل كل يوم بيومه ، والبوابين حسب فرقهم على كل باب . لأنه هكذا هي وصية داود رجل الله '),
(4554, '2 Chronicles', 14, 8, 15, ' ولم يحيدوا عن وصية الملك على الكهنة واللاويين في كل أمر وفي الخزائن '),
(4555, '2 Chronicles', 14, 8, 16, ' فتهيأ كل عمل سليمان إلى يوم تأسيس بيت الرب وإلى نهايته . فكمل بيت الرب '),
(4556, '2 Chronicles', 14, 8, 17, ' حينئذ ذهب سليمان إلى عصيون جابر ، وإلى أيلة على شاطئ البحر في أرض أدوم '),
(4557, '2 Chronicles', 14, 8, 18, ' وأرسل له حورام بيد عبيده سفنا وعبيدا يعرفون البحر ، فأتوا مع عبيد سليمان إلى أوفير ، وأخذوا من هناك أربع مئة وخمسين وزنة ذهب وأتوا بها إلى الملك سليمان '),
(4558, '2 Chronicles', 14, 9, 1, ' وسمعت ملكة سباء بخبر سليمان ، فأتت لتمتحن سليمان بمسائل إلى أورشليم ، بموكب عظيم جدا ، وجمال حاملة أطيابا وذهبا بكثرة وحجارة كريمة ، فأتت إلى سليمان وكلمته عن كل ما في قلبها '),
(4559, '2 Chronicles', 14, 9, 2, ' فأخبرها سليمان بكل كلامها . ولم يخف عن سليمان أمر إلا وأخبرها به '),
(4560, '2 Chronicles', 14, 9, 3, ' فلما رأت ملكة سبا حكمة سليمان والبيت الذي بناه '),
(4561, '2 Chronicles', 14, 9, 4, ' وطعام مائدته ، ومجلس عبيده ، وموقف خدامه وملابسهم ، وسقاته وملابسهم ، ومحرقاته التي كان يصعدها في بيت الرب ، لم تبق فيها روح بعد '),
(4562, '2 Chronicles', 14, 9, 5, ' فقالت للملك : صحيح الخبر الذي سمعته في أرضي عن أمورك وعن حكمتك '),
(4563, '2 Chronicles', 14, 9, 6, ' ولم أصدق كلامهم حتى جئت وأبصرت عيناي ، فهوذا لم أخبر بنصف كثرة حكمتك . زدت على الخبر الذي سمعته '),
(4564, '2 Chronicles', 14, 9, 7, ' فطوبى لرجالك وطوبى لعبيدك هؤلاء الواقفين أمامك دائما والسامعين حكمتك '),
(4565, '2 Chronicles', 14, 9, 8, ' ليكن مباركا الرب إلهك الذي سر بك ، وجعلك على كرسيه ملكا للرب إلهك . لأن إلهك أحب إسرائيل ليثبته إلى الأبد ، قد جعلك عليهم ملكا ، لتجري حكما وعدلا '),
(4566, '2 Chronicles', 14, 9, 9, ' وأهدت للملك مئة وعشرين وزنة ذهب وأطيابا كثيرة جدا وحجارة كريمة ، ولم يكن مثل ذلك الطيب الذي أهدته ملكة سبا للملك سليمان '),
(4567, '2 Chronicles', 14, 9, 10, ' وكذا عبيد حورام وعبيد سليمان الذين جلبوا ذهبا من أوفير أتوا بخشب الصندل وحجارة كريمة '),
(4568, '2 Chronicles', 14, 9, 11, ' وعمل الملك خشب الصندل درجا لبيت الرب وبيت الملك ، وأعوادا وربابا ، ولم ير مثلها قبل في أرض يهوذا '),
(4569, '2 Chronicles', 14, 9, 12, ' وأعطى الملك سليمان ملكة سبا كل مشتهاها الذي طلبت ، فضلا عما أتت به إلى الملك . فانصرفت وذهبت إلى أرضها هي وعبيدها '),
(4570, '2 Chronicles', 14, 9, 13, ' وكان وزن الذهب الذي جاء سليمان في سنة واحدة ، ست مئة وستا وستين وزنة ذهب '),
(4571, '2 Chronicles', 14, 9, 14, ' فضلا عن الذي جاء به التجار والمستبضعون . وكل ملوك العرب وولاة الأرض كانوا يأتون بذهب وفضة إلى سليمان '),
(4572, '2 Chronicles', 14, 9, 15, ' وعمل الملك سليمان مئتي ترس من ذهب مطرق ، خص الترس الواحد ست مئة شاقل من الذهب المطرق '),
(4573, '2 Chronicles', 14, 9, 16, ' وثلاث مئة مجن من ذهب مطرق ، خص المجن الواحد ثلاث مئة شاقل من الذهب . وجعلها الملك في بيت وعر لبنان '),
(4574, '2 Chronicles', 14, 9, 17, ' وعمل الملك كرسيا عظيما من عاج وغشاه بذهب خالص '),
(4575, '2 Chronicles', 14, 9, 18, ' وللكرسي ست درجات . وللكرسي موطئ من ذهب كلها متصلة ، ويدان من هنا ومن هناك على مكان الجلوس ، وأسدان واقفان بجانب اليدين '),
(4576, '2 Chronicles', 14, 9, 19, ' واثنا عشر أسدا واقفة هناك على الدرجات الست من هنا ومن هناك . لم يعمل مثله في جميع الممالك '),
(4577, '2 Chronicles', 14, 9, 20, ' وجميع آنية شرب الملك سليمان من ذهب ، وجميع آنية بيت وعر لبنان من ذهب خالص . لم تحسب الفضة شيئا في أيام سليمان '),
(4578, '2 Chronicles', 14, 9, 21, ' لأن سفن الملك كانت تسير إلى ترشيش مع عبيد حورام ، وكانت سفن ترشيش تأتي مرة في كل ثلاث سنين حاملة ذهبا وفضة وعاجا وقرودا وطواويس '),
(4579, '2 Chronicles', 14, 9, 22, ' فتعظم الملك سليمان على كل ملوك الأرض في الغنى والحكمة '),
(4580, '2 Chronicles', 14, 9, 23, ' وكان جميع ملوك الأرض يلتمسون وجه سليمان ليسمعوا حكمته التي جعلها الله في قلبه '),
(4581, '2 Chronicles', 14, 9, 24, ' وكانوا يأتون كل واحد بهديته ، بآنية فضة وآنية ذهب وحلل وسلاح وأطياب وخيل وبغال ، سنة فسنة '),
(4582, '2 Chronicles', 14, 9, 25, ' وكان لسليمان أربعة آلاف مذود خيل ومركبات ، واثنا عشر ألف فارس ، فجعلها في مدن المركبات ومع الملك في أورشليم '),
(4583, '2 Chronicles', 14, 9, 26, ' وكان متسلطا على جميع الملوك من النهر إلى أرض الفلسطينيين وإلى تخوم مصر '),
(4584, '2 Chronicles', 14, 9, 27, ' وجعل الملك الفضة في أورشليم مثل الحجارة ، وجعل الأرز مثل الجميز الذي في السهل في الكثرة '),
(4585, '2 Chronicles', 14, 9, 28, ' وكان مخرج خيل سليمان من مصر ومن جميع الأراضي '),
(4586, '2 Chronicles', 14, 9, 29, ' وبقية أمور سليمان الأولى والأخيرة ، أما هي مكتوبة في أخبار ناثان النبي ، وفي نبوة أخيا الشيلوني ، وفي رؤى يعدو الرائي على يربعام بن نباط '),
(4587, '2 Chronicles', 14, 9, 30, ' وملك سليمان في أورشليم على كل إسرائيل أربعين سنة '),
(4588, '2 Chronicles', 14, 9, 31, ' ثم اضطجع سليمان مع آبائه فدفنوه في مدينة داود أبيه . وملك رحبعام ابنه عوضا عنه '),
(4589, '2 Chronicles', 14, 10, 1, ' وذهب رحبعام إلى شكيم ، لأنه جاء إلى شكيم كل إسرائيل ليملكوه '),
(4590, '2 Chronicles', 14, 10, 2, ' ولما سمع يربعام بن نباط ، وهو في مصر حيث هرب من وجه سليمان الملك ، رجع يربعام من مصر '),
(4591, '2 Chronicles', 14, 10, 3, ' فأرسلوا ودعوه ، فأتى يربعام وكل إسرائيل وكلموا رحبعام قائلين '),
(4592, '2 Chronicles', 14, 10, 4, ' إن أباك قسى نيرنا ، فالآن خفف من عبودية أبيك القاسية ومن نيره الثقيل الذي جعله علينا فنخدمك '),
(4593, '2 Chronicles', 14, 10, 5, ' فقال لهم : ارجعوا إلي بعد ثلاثة أيام . فذهب الشعب '),
(4594, '2 Chronicles', 14, 10, 6, ' فاستشار الملك رحبعام الشيوخ الذين كانوا يقفون أمام سليمان أبيه وهو حي قائلا : كيف تشيرون أن أرد جوابا على هذا الشعب '),
(4595, '2 Chronicles', 14, 10, 7, ' فكلموه قائلين : إن كنت صالحا نحو هذا الشعب وأرضيتهم وكلمتهم كلاما حسنا ، يكونون لك عبيدا كل الأيام '),
(4596, '2 Chronicles', 14, 10, 8, ' فترك مشورة الشيوخ التي أشاروا بها عليه ، واستشار الأحداث الذين نشأوا معه ووقفوا أمامه '),
(4597, '2 Chronicles', 14, 10, 9, ' وقال لهم : بماذا تشيرون أنتم فنرد جوابا على هذا الشعب الذين كلموني قائلين : خفف من النير الذي جعله علينا أبوك '),
(4598, '2 Chronicles', 14, 10, 10, ' فكلمه الأحداث الذين نشأوا معه قائلين : هكذا تقول للشعب الذين كلموك قائلين : إن أباك ثقل نيرنا وأما أنت فخفف عنا ، هكذا تقول لهم : إن خنصري أغلظ من متني أبي '),
(4599, '2 Chronicles', 14, 10, 11, ' والآن أبي حملكم نيرا ثقيلا وأنا أزيد على نيركم . أبي أدبكم بالسياط وأما أنا فبالعقارب '),
(4600, '2 Chronicles', 14, 10, 12, ' فجاء يربعام وجميع الشعب إلى رحبعام في اليوم الثالث كما تكلم الملك قائلا : ارجعوا إلي في اليوم الثالث '),
(4601, '2 Chronicles', 14, 10, 13, ' فأجابهم الملك بقساوة ، وترك الملك رحبعام مشورة الشيوخ '),
(4602, '2 Chronicles', 14, 10, 14, ' وكلمهم حسب مشورة الأحداث قائلا : أبي ثقل نيركم وأنا أزيد عليه . أبي أدبكم بالسياط وأما أنا فبالعقارب '),
(4603, '2 Chronicles', 14, 21, 8, ' في أيامه عصى أدوم من تحت يد يهوذا وملكوا على أنفسهم ملكا '),
(4604, '2 Chronicles', 14, 21, 9, ' وعبر يهورام مع رؤسائه وجميع المركبات معه ، وقام ليلا وضرب أدوم المحيط به ورؤساء المركبات '),
(4605, '2 Chronicles', 14, 21, 10, ' فعصى أدوم من تحت يد يهوذا إلى هذا اليوم . حينئذ عصت لبنة في ذلك الوقت من تحت يده لأنه ترك الرب إله آبائه '),
(4606, '2 Chronicles', 14, 21, 11, ' وهو أيضا عمل مرتفعات في جبال يهوذا ، وجعل سكان أورشليم يزنون ، وطوح يهوذا '),
(4607, '2 Chronicles', 14, 21, 12, ' وأتت إليه كتابة من إيليا النبي تقول : هكذا قال الرب إله داود أبيك : من أجل أنك لم تسلك في طرق يهوشافاط أبيك وطرق آسا ملك يهوذا '),
(4608, '2 Chronicles', 14, 21, 13, ' بل سلكت في طرق ملوك إسرائيل ، وجعلت يهوذا وسكان أورشليم يزنون كزنا بيت أخآب ، وقتلت أيضا إخوتك من بيت أبيك الذين هم أفضل منك '),
(4609, '2 Chronicles', 14, 21, 14, ' هوذا يضرب الرب شعبك وبنيك ونساءك وكل مالك ضربة عظيمة '),
(4610, '2 Chronicles', 14, 21, 15, ' وإياك بأمراض كثيرة بداء أمعائك حتى تخرج أمعاؤك بسبب المرض يوما فيوما '),
(4611, '2 Chronicles', 14, 21, 16, ' وأهاج الرب على يهورام روح الفلسطينيين والعرب الذين بجانب الكوشيين '),
(4612, '2 Chronicles', 14, 21, 17, ' فصعدوا إلى يهوذا وافتتحوها ، وسبوا كل الأموال الموجودة في بيت الملك مع بنيه ونسائه أيضا ، ولم يبق له ابن إلا يهوآحاز أصغر بنيه '),
(4613, '2 Chronicles', 14, 21, 18, ' وبعد هذا كله ضربه الرب في أمعائه بمرض ليس له شفاء '),
(4614, '2 Chronicles', 14, 21, 19, ' وكان من يوم إلى يوم وحسب ذهاب المدة عند نهاية سنتين ، أن أمعاءه خرجت بسبب مرضه ، فمات بأمراض ردية ، ولم يعمل له شعبه حريقة كحريقة آبائه '),
(4615, '2 Chronicles', 14, 21, 20, ' كان ابن اثنتين وثلاثين سنة حين ملك ، وملك ثماني سنين في أورشليم ، وذهب غير مأسوف عليه ، ودفنوه في مدينة داود ، ولكن ليس في قبور الملوك '),
(4616, '2 Chronicles', 14, 22, 1, ' وملك سكان أورشليم أخزيا ابنه الأصغر عوضا عنه ، لأن جميع الأولين قتلهم الغزاة الذين جاءوا مع العرب إلى المحلة . فملك أخزيا بن يهورام ملك يهوذا '),
(4617, '2 Chronicles', 14, 22, 2, ' كان أخزيا ابن اثنتين وأربعين سنة حين ملك ، وملك سنة واحدة في أورشليم ، واسم أمه عثليا بنت عمري '),
(4618, '2 Chronicles', 14, 22, 3, ' وهو أيضا سلك في طرق بيت أخآب لأن أمه كانت تشير عليه بفعل الشر '),
(4619, '2 Chronicles', 14, 22, 4, ' فعمل الشر في عيني الرب مثل بيت أخآب ، لأنهم كانوا له مشيرين بعد وفاة أبيه لإبادته '),
(4620, '2 Chronicles', 14, 22, 5, ' فسلك بمشورتهم وذهب مع يهورام بن أخآب ملك إسرائيل لمحاربة حزائيل ملك أرام في راموت جلعاد . وضرب الأراميون يورام '),
(4621, '2 Chronicles', 14, 22, 6, ' فرجع ليبرأ في يزرعيل بسبب الضربات التي ضربوه إياها في الرامة عند محاربته حزائيل ملك أرام . ونزل عزريا بن يهورام ملك يهوذا لعيادة يهورام بن أخآب في يزرعيل لأنه كان مريضا '),
(4622, '2 Chronicles', 14, 22, 7, ' فمن قبل الله كان هلاك أخزيا بمجيئه إلى يورام . فإنه حين جاء خرج مع يهورام إلى ياهو بن نمشي الذي مسحه الرب لقطع بيت أخآب '),
(4623, '2 Chronicles', 14, 22, 8, ' وإذ كان ياهو يقضي على بيت أخآب ، وجد رؤساء يهوذا وبني إخوة أخزيا الذين كانوا يخدمون أخزيا فقتلهم '),
(4624, '2 Chronicles', 14, 22, 9, ' وطلب أخزيا فأمسكوه وهو مختبئ في السامرة ، وأتوا به إلى ياهو وقتلوه ودفنوه ، لأنهم قالوا : إنه ابن يهوشافاط الذي طلب الرب بكل قلبه . فلم يكن لبيت أخزيا من يقوى على المملكة '),
(4625, '2 Chronicles', 14, 22, 10, ' ولما رأت عثليا أم أخزيا أن ابنها قد مات ، قامت وأبادت جميع النسل الملكي من بيت يهوذا '),
(4626, '2 Chronicles', 14, 22, 11, ' أما يهوشبعة بنت الملك فأخذت يوآش بن أخزيا وسرقته من وسط بني الملك الذين قتلوا ، وجعلته هو ومرضعته في مخدع السرير ، وخبأته يهوشبعة بنت الملك يهورام امرأة يهوياداع الكاهن ، لأنها كانت أخت أخزيا ، من وجه عثليا فلم تقتله '),
(4627, '2 Chronicles', 14, 22, 12, ' وكان معهم في بيت الله مختبئا ست سنين ، وعثليا مالكة على الأرض '),
(4628, '2 Chronicles', 14, 23, 1, ' وفي السنة السابعة تشدد يهوياداع وأخذ معه في العهد رؤساء المئات : عزريا بن يروحام ، وإسماعيل بن يهوحانان ، وعزريا بن عوبيد ، ومعسيا بن عدايا ، وأليشافاط بن زكري '),
(4629, '2 Chronicles', 14, 23, 2, ' وجالوا في يهوذا وجمعوا اللاويين من جميع مدن يهوذا ورؤوس آباء إسرائيل وجاءوا إلى أورشليم '),
(4630, '2 Chronicles', 14, 23, 3, ' وقطع كل المجمع عهدا في بيت الله مع الملك . وقال لهم : هوذا ابن الملك يملك كما تكلم الرب عن بني داود '),
(4631, '2 Chronicles', 14, 23, 4, ' هذا هو الأمر الذي تعملونه : الثلث منكم الذين يدخلون في السبت من الكهنة واللاويين يكونون بوابين للأبواب '),
(4632, '2 Chronicles', 14, 23, 5, ' والثلث في بيت الملك ، والثلث في باب الأساس ، وجميع الشعب في ديار بيت الرب '),
(4633, '2 Chronicles', 14, 23, 6, ' ولا يدخل بيت الرب إلا الكهنة والذين يخدمون من اللاويين ، فهم يدخلون لأنهم مقدسون ، وكل الشعب يحرسون حراسة الرب '),
(4634, '2 Chronicles', 14, 23, 7, ' ويحيط اللاويون بالملك مستديرين ، كل واحد سلاحه بيده . والذي يدخل البيت يقتل . وكونوا مع الملك في دخوله وفي خروجه '),
(4635, '2 Chronicles', 14, 23, 8, ' فعمل اللاويون وكل يهوذا حسب كل ما أمر به يهوياداع الكاهن . وأخذوا كل واحد رجاله الداخلين في السبت ، مع الخارجين في السبت ، لأن يهوياداع الكاهن لم يصرف الفرق '),
(4636, '2 Chronicles', 14, 23, 9, ' وأعطى يهوياداع الكاهن رؤساء المئات الحراب والمجان والأتراس التي للملك داود التي في بيت الله '),
(4637, '2 Chronicles', 14, 23, 10, ' وأوقف جميع الشعب ، وكل واحد سلاحه بيده من جانب البيت الأيمن إلى جانب البيت الأيسر حول المذبح والبيت ، حول الملك مستديرين '),
(4638, '2 Chronicles', 14, 23, 11, ' ثم أخرجوا ابن الملك ووضعوا عليه التاج وأعطوه الشهادة ، وملكوه . ومسحه يهوياداع وبنوه وقالوا : ليحي الملك '),
(4639, '2 Chronicles', 14, 23, 12, ' ولما سمعت عثليا صوت الشعب يركضون ويمدحون الملك ، دخلت إلى الشعب في بيت الرب '),
(4640, '2 Chronicles', 14, 23, 13, ' ونظرت وإذا الملك واقف على منبره في المدخل ، والرؤساء والأبواق عند الملك ، وكل شعب الأرض يفرحون وينفخون بالأبواق ، والمغنون بآلات الغناء ، والمعلمون التسبيح . فشقت عثليا ثيابها وقالت : خيانة ، خيانة '),
(4641, '2 Chronicles', 14, 23, 14, ' فأخرج يهوياداع الكاهن رؤساء المئات الموكلين على الجيش وقال لهم : أخرجوها إلى خارج الصفوف ، والذي يتبعها يقتل بالسيف . لأن الكاهن قال : لا تقتلوها في بيت الرب '),
(4642, '2 Chronicles', 14, 23, 15, ' فألقوا عليها الأيادي . ولما أتت إلى مدخل باب الخيل إلى بيت الملك قتلوها هناك '),
(4643, '2 Chronicles', 14, 23, 16, ' فقطع يهوياداع عهدا بينه وبين كل الشعب وبين الملك أن يكونوا شعبا للرب '),
(4644, '2 Chronicles', 14, 23, 17, ' ودخل جميع الشعب إلى بيت البعل وهدموه وكسروا مذابحه وتماثيله ، وقتلوا متان كاهن البعل أمام المذبح '),
(4645, '2 Chronicles', 14, 23, 18, ' وجعل يهوياداع مناظرين على بيت الرب عن يد الكهنة اللاويين الذين قسمهم داود على بيت الرب ، لأجل إصعاد محرقات الرب ، كما هو مكتوب في شريعة موسى ، بالفرح والغناء حسب أمر داود '),
(4646, '2 Chronicles', 14, 23, 19, ' وأوقف البوابين على أبواب بيت الرب لئلا يدخل نجس في أمر ما '),
(4647, '2 Chronicles', 14, 23, 20, ' وأخذ رؤساء المئات والعظماء والمتسلطين على الشعب وكل شعب الأرض ، وأنزل الملك من بيت الرب ، ودخلوا من وسط الباب الأعلى إلى بيت الملك ، وأجلسوا الملك على كرسي المملكة '),
(4648, '2 Chronicles', 14, 23, 21, ' ففرح كل شعب الأرض واستراحت المدينة ، وقتلوا عثليا بالسيف '),
(4649, '2 Chronicles', 14, 24, 1, ' كان يوآش ابن سبع سنين حين ملك ، وملك أربعين سنة في أورشليم ، واسم أمه ظبية من بئر سبع '),
(4650, '2 Chronicles', 14, 24, 2, ' وعمل يوآش المستقيم في عيني الرب كل أيام يهوياداع الكاهن '),
(4651, '2 Chronicles', 14, 24, 3, ' واتخذ يهوياداع له امرأتين فولد بنين وبنات '),
(4652, '2 Chronicles', 14, 24, 4, ' وحدث بعد ذلك أنه كان في قلب يوآش أن يجدد بيت الرب '),
(4653, '2 Chronicles', 14, 24, 5, ' فجمع الكهنة واللاويين وقال لهم : اخرجوا إلى مدن يهوذا واجمعوا من جميع إسرائيل فضة لأجل ترميم بيت إلهكم من سنة إلى سنة ، وبادروا أنتم إلى هذا الأمر . فلم يبادر اللاويون '),
(4654, '2 Chronicles', 14, 24, 6, ' فدعا الملك يهوياداع الرأس وقال له : لماذا لم تطلب من اللاويين أن يأتوا من يهوذا وأورشليم بجزية موسى عبد الرب وجماعة إسرائيل لخيمة الشهادة '),
(4655, '2 Chronicles', 14, 24, 7, ' لأن بني عثليا الخبيثة قد هدموا بيت الله ، وصيروا كل أقداس بيت الرب للبعليم ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(4656, '2 Chronicles', 14, 24, 8, ' وأمر الملك فعملوا صندوقا وجعلوه في باب بيت الرب خارجا '),
(4657, '2 Chronicles', 14, 24, 9, ' ونادوا في يهوذا وأورشليم بأن يأتوا إلى الرب بجزية موسى عبد الرب المفروضة على إسرائيل في البرية '),
(4658, '2 Chronicles', 14, 24, 10, ' ففرح كل الرؤساء وكل الشعب وأدخلوا وألقوا في الصندوق حتى امتلأ '),
(4659, '2 Chronicles', 14, 24, 11, ' وحينما كان يؤتى بالصندوق إلى وكالة الملك بيد اللاويين ، عندما يرون أن الفضة قد كثرت ، كان يأتي كاتب الملك ووكيل الكاهن الرأس ويفرغان الصندوق ، ثم يحملانه ويردانه إلى مكانه . هكذا كانوا يفعلون يوما فيوما ، حتى جمعوا فضة بكثرة '),
(4660, '2 Chronicles', 14, 24, 12, ' ودفعها الملك ويهوياداع لعاملي شغل خدمة بيت الرب ، وكانوا يستأجرون نحاتين ونجارين لتجديد بيت الرب ، وللعاملين في الحديد والنحاس أيضا لترميم بيت الرب '),
(4661, '2 Chronicles', 14, 24, 13, ' فعمل عاملو الشغل ونجح العمل بأيديهم ، وأقاموا بيت الله على رسمه وثبتوه '),
(4662, '2 Chronicles', 14, 24, 14, ' ولما أكملوا أتوا إلى ما بين يدي الملك ويهوياداع ببقية الفضة وعملوها آنية لبيت الرب ، آنية خدمة وإصعاد وصحونا وآنية ذهب وفضة . وكانوا يصعدون محرقات في بيت الرب دائما كل أيام يهوياداع '),
(4663, '2 Chronicles', 14, 24, 15, ' وشاخ يهوياداع وشبع من الأيام ومات . كان ابن مئة وثلاثين سنة عند وفاته '),
(4664, '2 Chronicles', 14, 24, 16, ' فدفنوه في مدينة داود مع الملوك لأنه عمل خيرا في إسرائيل ومع الله وبيته '),
(4665, '2 Chronicles', 14, 24, 17, ' وبعد موت يهوياداع جاء رؤساء يهوذا وسجدوا للملك . حينئذ سمع الملك لهم '),
(4666, '2 Chronicles', 14, 24, 18, ' وتركوا بيت الرب إله آبائهم وعبدوا السواري والأصنام ، فكان غضب على يهوذا وأورشليم لأجل إثمهم هذا '),
(4667, '2 Chronicles', 14, 24, 19, ' وأرسل إليهم أنبياء لإرجاعهم إلى الرب ، وأشهدوا عليهم فلم يصغوا '),
(4668, '2 Chronicles', 14, 24, 20, ' ولبس روح الله زكريا بن يهوياداع الكاهن فوقف فوق الشعب وقال لهم : هكذا يقول الله : لماذا تتعدون وصايا الرب فلا تفلحون ؟ لأنكم تركتم الرب قد ترككم '),
(4669, '2 Chronicles', 14, 24, 21, ' ففتنوا عليه ورجموه بحجارة بأمر الملك في دار بيت الرب '),
(4670, '2 Chronicles', 14, 24, 22, ' ولم يذكر يوآش الملك المعروف الذي عمله يهوياداع أبوه معه ، بل قتل ابنه . وعند موته قال : الرب ينظر ويطالب '),
(4671, '2 Chronicles', 14, 24, 23, ' وفي مدار السنة صعد عليه جيش أرام وأتوا إلى يهوذا وأورشليم وأهلكوا كل رؤساء الشعب من الشعب ، وجميع غنيمتهم أرسلوها إلى ملك دمشق '),
(4672, '2 Chronicles', 14, 24, 24, ' لأن جيش أرام جاء بشرذمة قليلة ، ودفع الرب ليدهم جيشا كثيرا جدا لأنهم تركوا الرب إله آبائهم . فأجروا قضاء على يوآش '),
(4673, '2 Chronicles', 14, 24, 25, ' وعند ذهابهم عنه ، لأنهم تركوه بأمراض كثيرة ، فتن عليه عبيده من أجل دماء بني يهوياداع الكاهن ، وقتلوه على سريره فمات . فدفنوه في مدينة داود ، ولم يدفنوه في قبور الملوك '),
(4674, '2 Chronicles', 14, 24, 26, ' وهذان هما الفاتنان عليه : زاباد بن شمعة العمونية ، ويهوزاباد بن شمريت الموآبية '),
(4675, '2 Chronicles', 14, 24, 27, ' وأما بنوه وكثرة ما حمل عليه ومرمة بيت الله ، ها هي مكتوبة في مدرس سفر الملوك . وملك أمصيا ابنه عوضا عنه '),
(4676, '2 Chronicles', 14, 25, 1, ' ملك أمصيا وهو ابن خمس وعشرين سنة ، وملك تسعا وعشرين سنة في أورشليم ، واسم أمه يهوعدان من أورشليم '),
(4677, '2 Chronicles', 14, 25, 2, ' وعمل المستقيم في عيني الرب ، ولكن ليس بقلب كامل '),
(4678, '2 Chronicles', 14, 25, 3, ' ولما تثبتت المملكة عليه قتل عبيده الذين قتلوا الملك أباه '),
(4679, '2 Chronicles', 14, 25, 4, ' وأما بنوهم فلم يقتلهم ، بل كما هو مكتوب في الشريعة في سفر موسى ، حيث أمر الرب قائلا : لا تموت الآباء لأجل البنين ، ولا البنون يموتون لأجل الآباء ، بل كل واحد يموت لأجل خطيته '),
(4680, '2 Chronicles', 14, 25, 5, ' وجمع أمصيا يهوذا وأقامهم حسب بيوت الآباء رؤساء ألوف ورؤساء مئات في كل يهوذا وبنيامين ، وأحصاهم من ابن عشرين سنة فما فوق ، فوجدهم ثلاث مئة ألف مختار خارج للحرب حامل رمح وترس '),
(4681, '2 Chronicles', 14, 25, 6, ' واستأجر من إسرائيل مئة ألف جبار بأس بمئة وزنة من الفضة '),
(4682, '2 Chronicles', 14, 25, 7, ' وجاء إليه رجل الله قائلا : أيها الملك ، لا يأتي معك جيش إسرائيل ، لأن الرب ليس مع إسرائيل ، مع كل بني أفرايم '),
(4683, '2 Chronicles', 14, 25, 8, ' وإن ذهبت أنت فاعمل وتشدد للقتال ، لأن الله يسقطك أمام العدو ، لأن عند الله قوة للمساعدة وللإسقاط '),
(4684, '2 Chronicles', 14, 25, 9, ' فقال أمصيا لرجل الله : فماذا يعمل لأجل المئة الوزنة التي أعطيتها لغزاة إسرائيل ؟  . فقال رجل الله : إن الرب قادر أن يعطيك أكثر من هذه '),
(4685, '2 Chronicles', 14, 25, 10, ' فأفرز أمصيا الغزاة الذين جاءوا إليه من أفرايم لكي ينطلقوا إلى مكانهم ، فحمي غضبهم جدا على يهوذا ورجعوا إلى مكانهم بحمو الغضب '),
(4686, '2 Chronicles', 14, 25, 11, ' وأما أمصيا فتشدد واقتاد شعبه وذهب إلى وادي الملح ، وضرب من بني ساعير عشرة آلاف '),
(4687, '2 Chronicles', 14, 25, 12, ' وعشرة آلاف أحياء سباهم بنو يهوذا وأتوا بهم إلى رأس سالع وطرحوهم عن رأس سالع فتكسروا أجمعون '),
(4688, '2 Chronicles', 14, 25, 13, ' وأما الرجال الغزاة الذين أرجعهم أمصيا عن الذهاب معه إلى القتال ، فاقتحموا مدن يهوذا من السامرة إلى بيت حورون ، وضربوا منهم ثلاثة آلاف ونهبوا نهبا كثيرا '),
(4689, '2 Chronicles', 14, 25, 14, ' ثم بعد مجيء أمصيا من ضرب الأدوميين أتى بآلهة بني ساعير وأقامهم له آلهة ، وسجد أمامهم وأوقد لهم '),
(4690, '2 Chronicles', 14, 25, 15, ' فحمي غضب الرب على أمصيا وأرسل إليه نبيا فقال له : لماذا طلبت آلهة الشعب الذين لم ينقذوا شعبهم من يدك '),
(4691, '2 Chronicles', 14, 25, 16, ' وفيما هو يكلمه قال له : هل جعلوك مشيرا للملك ؟ كف لماذا يقتلونك ؟  . فكف النبي وقال : قد علمت أن الله قد قضى بهلاكك لأنك عملت هذا ولم تسمع لمشورتي '),
(4692, '2 Chronicles', 14, 25, 17, ' فاستشار أمصيا ملك يهوذا ، وأرسل إلى يوآش بن يهوآحاز بن ياهو ملك إسرائيل قائلا : هلم نتراء مواجهة '),
(4693, '2 Chronicles', 14, 25, 18, ' فأرسل يوآش ملك إسرائيل إلى أمصيا ملك يهوذا قائلا : العوسج الذي في لبنان أرسل إلى الأرز الذي في لبنان يقول : أعط ابنتك لابني امرأة . فعبر حيوان بري كان في لبنان وداس العوسج '),
(4694, '2 Chronicles', 14, 25, 19, ' تقول : هأنذا قد ضربت أدوم ، فرفعك قلبك للتمجد فالآن أقم في بيتك . لماذا تهجم على الشر فتسقط أنت ويهوذا معك '),
(4695, '2 Chronicles', 14, 25, 20, ' فلم يسمع أمصيا لأنه كان من قبل الله أن يسلمهم ، لأنهم طلبوا آلهة أدوم '),
(4696, '2 Chronicles', 14, 25, 21, ' وصعد يوآش ملك إسرائيل فتراءيا مواجهة ، هو وأمصيا ملك يهوذا ، في بيت شمس التي ليهوذا '),
(4697, '2 Chronicles', 14, 25, 22, ' فانهزم يهوذا أمام إسرائيل وهربوا كل واحد إلى خيمته '),
(4698, '2 Chronicles', 14, 25, 23, ' وأما أمصيا ملك يهوذا ابن يوآش بن يهوآحاز فأمسكه يوآش ملك إسرائيل في بيت شمس وجاء به إلى أورشليم ، وهدم سور أورشليم من باب أفرايم إلى باب الزاوية ، أربع مئة ذراع '),
(4699, '2 Chronicles', 14, 25, 24, ' وأخذ كل الذهب والفضة وكل الآنية الموجودة في بيت الله مع عوبيد أدوم وخزائن بيت الملك والرهناء ورجع إلى السامرة '),
(4700, '2 Chronicles', 14, 25, 25, ' وعاش أمصيا بن يوآش ملك يهوذا بعد موت يوآش بن يهوآحاز ملك إسرائيل خمس عشرة سنة '),
(4701, '2 Chronicles', 14, 25, 26, ' وبقية أمور أمصيا الأولى والأخيرة ، أما هي مكتوبة في سفر ملوك يهوذا وإسرائيل '),
(4702, '2 Chronicles', 14, 25, 27, ' ومن حين حاد أمصيا من وراء الرب فتنوا عليه في أورشليم ، فهرب إلى لخيش ، فأرسلوا وراءه إلى لخيش وقتلوه هناك '),
(4703, '2 Chronicles', 14, 25, 28, ' وحملوه على الخيل ودفنوه مع آبائه في مدينة يهوذا '),
(4704, '2 Chronicles', 14, 26, 1, ' وأخذ كل شعب يهوذا عزيا وهو ابن ست عشرة سنة وملكوه عوضا عن أبيه أمصيا '),
(4705, '2 Chronicles', 14, 26, 2, ' هو بنى أيلة وردها ليهوذا بعد اضطجاع الملك مع آبائه '),
(4706, '2 Chronicles', 14, 26, 3, ' كان عزيا ابن ست عشرة سنة حين ملك ، وملك اثنتين وخمسين سنة في أورشليم ، واسم أمه يكليا من أورشليم '),
(4707, '2 Chronicles', 14, 26, 4, ' وعمل المستقيم في عيني الرب حسب كل ما عمل أمصيا أبوه '),
(4708, '2 Chronicles', 14, 26, 5, ' وكان يطلب الله في أيام زكريا الفاهم بمناظر الله . وفي أيام طلبه الرب أنجحه الله '),
(4709, '2 Chronicles', 14, 26, 6, ' وخرج وحارب الفلسطينيين وهدم سور جت وسور يبنة وسور أشدود ، وبنى مدنا في أرض أشدود والفلسطينيين '),
(4710, '2 Chronicles', 14, 26, 7, ' وساعده الله على الفلسطينيين وعلى العرب الساكنين في جور بعل والمعونيين '),
(4711, '2 Chronicles', 14, 26, 8, ' وأعطى العمونيون عزيا هدايا ، وامتد اسمه إلى مدخل مصر لأنه تشدد جدا '),
(4712, '2 Chronicles', 14, 26, 9, ' وبنى عزيا أبراجا في أورشليم عند باب الزاوية وعند باب الوادي وعند الزاوية وحصنها '),
(4713, '2 Chronicles', 14, 26, 10, ' وبنى أبراجا في البرية ، وحفر آبارا كثيرة لأنه كان له ماشية كثيرة في الساحل والسهل ، وفلاحون وكرامون في الجبال وفي الكرمل ، لأنه كان يحب الفلاحة '),
(4714, '2 Chronicles', 14, 26, 11, ' وكان لعزيا جيش من المقاتلين يخرجون للحرب أحزابا حسب عدد إحصائهم عن يد يعيئيل الكاتب ومعسيا العريف تحت يد حننيا ، واحد من رؤساء الملك '),
(4715, '2 Chronicles', 14, 26, 12, ' كل عدد رؤوس الآباء من جبابرة البأس ألفان وست مئة '),
(4716, '2 Chronicles', 14, 26, 13, ' وتحت يدهم جيش جنود ثلاث مئة ألف وسبعة آلاف وخمس مئة من المقاتلين بقوة شديدة لمساعدة الملك على العدو '),
(4717, '2 Chronicles', 14, 26, 14, ' وهيأ لهم عزيا ، لكل الجيش ، أتراسا ورماحا وخوذا ودروعا وقسيا وحجارة مقاليع '),
(4718, '2 Chronicles', 14, 26, 15, ' وعمل في أورشليم منجنيقات اختراع مخترعين لتكون على الأبراج وعلى الزوايا ، لترمى بها السهام والحجارة العظيمة . وامتد اسمه إلى بعيد إذ عجبت مساعدته حتى تشدد '),
(4719, '2 Chronicles', 14, 26, 16, ' ولما تشدد ارتفع قلبه إلى الهلاك وخان الرب إلهه ، ودخل هيكل الرب ليوقد على مذبح البخور '),
(4720, '2 Chronicles', 14, 26, 17, ' ودخل وراءه عزريا الكاهن ومعه ثمانون من كهنة الرب بني البأس '),
(4721, '2 Chronicles', 14, 26, 18, ' وقاوموا عزيا الملك وقالوا له : ليس لك يا عزيا أن توقد للرب ، بل للكهنة بني هارون المقدسين للإيقاد . اخرج من المقدس لأنك خنت وليس لك من كرامة من عند الرب الإله '),
(4722, '2 Chronicles', 14, 26, 19, ' فحنق عزيا . وكان في يده مجمرة للإيقاد . وعند حنقه على الكهنة خرج برص في جبهته أمام الكهنة في بيت الرب بجانب مذبح البخور '),
(4723, '2 Chronicles', 14, 26, 20, ' فالتفت نحوه عزرياهو الكاهن الرأس وكل الكهنة ، وإذا هو أبرص في جبهته ، فطردوه من هناك حتى إنه هو نفسه بادر إلى الخروج لأن الرب ضربه '),
(4724, '2 Chronicles', 14, 26, 21, ' وكان عزيا الملك أبرص إلى يوم وفاته ، وأقام في بيت المرض أبرص لأنه قطع من بيت الرب ، وكان يوثام ابنه على بيت الملك يحكم على شعب الأرض '),
(4725, '2 Chronicles', 14, 26, 22, ' وبقية أمور عزيا الأولى والأخيرة كتبها إشعياء بن آموص النبي '),
(4726, '2 Chronicles', 14, 26, 23, ' ثم اضطجع عزيا مع آبائه ودفنوه مع آبائه في حقل المقبرة التي للملوك ، لأنهم قالوا إنه أبرص . وملك يوثام ابنه عوضا عنه '),
(4727, '2 Chronicles', 14, 27, 1, ' كان يوثام ابن خمس وعشرين سنة حين ملك ، وملك ست عشرة سنة في أورشليم ، واسم أمه يروشة بنت صادوق '),
(4728, '2 Chronicles', 14, 27, 2, ' وعمل المستقيم في عيني الرب حسب كل ما عمل عزيا أبوه ، إلا أنه لم يدخل هيكل الرب . وكان الشعب يفسدون بعد '),
(4729, '2 Chronicles', 14, 27, 3, ' هو بنى الباب الأعلى لبيت الرب ، وبنى كثيرا على سور الأكمة '),
(4730, '2 Chronicles', 14, 27, 4, ' وبنى مدنا في جبل يهوذا ، وبنى في الغابات قلعا وأبراجا '),
(4731, '2 Chronicles', 14, 27, 5, ' وهو حارب ملك بني عمون وقوي عليهم ، فأعطاه بنو عمون في تلك السنة مئة وزنة من الفضة ، وعشرة آلاف كر قمح ، وعشرة آلاف من الشعير . هذا ما أداه له بنو عمون ، وكذلك في السنة الثانية والثالثة '),
(4732, '2 Chronicles', 14, 27, 6, ' وتشدد يوثام لأنه هيأ طرقه أمام الرب إلهه '),
(4733, '2 Chronicles', 14, 27, 7, ' وبقية أمور يوثام وكل حروبه وطرقه ، ها هي مكتوبة في سفر ملوك إسرائيل ويهوذا '),
(4734, '2 Chronicles', 14, 27, 8, ' كان ابن خمس وعشرين سنة حين ملك ، وملك ست عشرة سنة في أورشليم '),
(4735, '2 Chronicles', 14, 27, 9, ' ثم اضطجع يوثام مع آبائه فدفنوه في مدينة داود ، وملك آحاز ابنه عوضا عنه '),
(4736, '2 Chronicles', 14, 28, 1, ' كان آحاز ابن عشرين سنة حين ملك ، وملك ست عشرة سنة في أورشليم ، ولم يفعل المستقيم في عيني الرب كداود أبيه '),
(4737, '2 Chronicles', 14, 28, 2, ' بل سار في طرق ملوك إسرائيل ، وعمل أيضا تماثيل مسبوكة للبعليم '),
(4738, '2 Chronicles', 14, 28, 3, ' وهو أوقد في وادي ابن هنوم وأحرق بنيه بالنار حسب رجاسات الأمم الذين طردهم الرب من أمام بني إسرائيل '),
(4739, '2 Chronicles', 14, 28, 4, ' وذبح وأوقد على المرتفعات وعلى التلال وتحت كل شجرة خضراء '),
(4740, '2 Chronicles', 14, 28, 5, ' فدفعه الرب إلهه ليد ملك أرام ، فضربوه وسبوا منه سبيا عظيما وأتوا بهم إلى دمشق . ودفع أيضا ليد ملك إسرائيل فضربه ضربة عظيمة '),
(4741, '2 Chronicles', 14, 28, 6, ' وقتل فقح بن رمليا في يهوذا مئة وعشرين ألفا في يوم واحد ، الجميع بنو بأس ، لأنهم تركوا الرب إله آبائهم '),
(4742, '2 Chronicles', 14, 28, 7, ' وقتل زكري جبار أفرايم معسيا ابن الملك ، وعزريقام رئيس البيت ، وألقانة ثاني الملك '),
(4743, '2 Chronicles', 14, 28, 8, ' وسبى بنو إسرائيل من إخوتهم مئتي ألف من النساء والبنين والبنات ، ونهبوا أيضا منهم غنيمة وافرة وأتوا بالغنيمة إلى السامرة '),
(4744, '2 Chronicles', 14, 28, 9, ' وكان هناك نبي للرب اسمه عوديد ، فخرج للقاء الجيش الآتي إلى السامرة وقال لهم : هوذا من أجل غضب الرب إله آبائكم على يهوذا قد دفعهم ليدكم وقد قتلتموهم بغضب بلغ السماء '),
(4745, '2 Chronicles', 14, 28, 10, ' والآن أنتم عازمون على إخضاع بني يهوذا وأورشليم عبيدا وإماء لكم . أما عندكم أنتم آثام للرب إلهكم '),
(4746, '2 Chronicles', 14, 28, 11, ' والآن اسمعوا لي وردوا السبي الذي سبيتموه من إخوتكم لأن حمو غضب الرب عليكم '),
(4747, '2 Chronicles', 14, 28, 12, ' ثم قام رجال من رؤوس بني أفرايم : عزريا بن يهوحانان ، وبرخيا بن مشليموت ، ويحزقيا بن شلوم ، وعماسا بن حدلاي على المقبلين من الجيش '),
(4748, '2 Chronicles', 14, 28, 13, ' وقالوا لهم : لا تدخلون بالسبي إلى هنا لأن علينا إثما للرب ، وأنتم عازمون أن تزيدوا على خطايانا وعلى إثمنا ، لأن لنا إثما كثيرا ، وعلى إسرائيل حمو غضب '),
(4749, '2 Chronicles', 14, 28, 14, ' فترك المتجردون السبي والنهب أمام الرؤساء وكل الجماعة '),
(4750, '2 Chronicles', 14, 28, 15, ' وقام الرجال المعينة أسماؤهم وأخذوا المسبيين وألبسوا كل عراتهم من الغنيمة ، وكسوهم وحذوهم وأطعموهم وأسقوهم ودهنوهم ، وحملوا على حمير جميع المعيين منهم ، وأتوا بهم إلى أريحا ، مدينة النخل ، إلى إخوتهم . ثم رجعوا إلى السامرة '),
(4751, '2 Chronicles', 14, 28, 16, ' في ذلك الوقت أرسل الملك آحاز إلى ملوك أشور لكي يساعدوه '),
(4752, '2 Chronicles', 14, 28, 17, ' فإن الأدوميين أتوا أيضا وضربوا يهوذا وسبوا سبيا '),
(4753, '2 Chronicles', 14, 10, 15, ' ولم يسمع الملك للشعب ، لأن السبب كان من قبل الله ، لكي يقيم الرب كلامه الذي تكلم به عن يد أخيا الشيلوني إلى يربعام بن نباط '),
(4754, '2 Chronicles', 14, 10, 16, ' فلما رأى كل إسرائيل أن الملك لم يسمع لهم ، جاوب الشعب الملك قائلين : أي قسم لنا في داود ؟ ولا نصيب لنا في ابن يسى كل واحد إلى خيمته يا إسرائيل . الآن انظر إلى بيتك يا داود . وذهب كل إسرائيل إلى خيامهم '),
(4755, '2 Chronicles', 14, 10, 17, ' وأما بنو إسرائيل الساكنون في مدن يهوذا فملك عليهم رحبعام '),
(4756, '2 Chronicles', 14, 10, 18, ' ثم أرسل الملك رحبعام هدورام الذي على التسخير ، فرجمه بنو إسرائيل بالحجارة فمات . فبادر الملك رحبعام وصعد إلى المركبة ليهرب إلى أورشليم '),
(4757, '2 Chronicles', 14, 10, 19, ' فعصى إسرائيل بيت داود إلى هذا اليوم '),
(4758, '2 Chronicles', 14, 11, 1, ' ولما جاء رحبعام إلى أورشليم ، جمع من بيت يهوذا وبنيامين مئة وثمانين ألف مختار محارب ليحارب إسرائيل ، ليرد الملك إلى رحبعام '),
(4759, '2 Chronicles', 14, 11, 2, ' وكان كلام الرب إلى شمعيا رجل الله قائلا '),
(4760, '2 Chronicles', 14, 11, 3, ' كلم رحبعام بن سليمان ملك يهوذا وكل إسرائيل في يهوذا وبنيامين قائلا '),
(4761, '2 Chronicles', 14, 11, 4, ' هكذا قال الرب : لا تصعدوا ولا تحاربوا إخوتكم . ارجعوا كل واحد إلى بيته ، لأنه من قبلي صار هذا الأمر . فسمعوا لكلام الرب ورجعوا عن الذهاب ضد يربعام '),
(4762, '2 Chronicles', 14, 11, 5, ' وأقام رحبعام في أورشليم وبنى مدنا للحصار في يهوذا '),
(4763, '2 Chronicles', 14, 11, 6, ' فبنى بيت لحم وعيطام وتقوع '),
(4764, '2 Chronicles', 14, 11, 7, ' وبيت صور وسوكو وعدلام '),
(4765, '2 Chronicles', 14, 11, 8, ' وجت ومريشة وزيف '),
(4766, '2 Chronicles', 14, 11, 9, ' وأدورايم ولخيش وعزيقة '),
(4767, '2 Chronicles', 14, 11, 10, ' وصرعة وأيلون وحبرون ، التي في يهوذا وبنيامين ، مدنا حصينة '),
(4768, '2 Chronicles', 14, 11, 11, ' وشدد الحصون وجعل فيها قوادا وخزائن مأكل وزيت وخمر '),
(4769, '2 Chronicles', 14, 11, 12, ' وأتراسا في كل مدينة ورماحا ، وشددها كثيرا جدا ، وكان له يهوذا وبنيامين '),
(4770, '2 Chronicles', 14, 11, 13, ' والكهنة واللاويون الذين في كل إسرائيل مثلوا بين يديه من جميع تخومهم '),
(4771, '2 Chronicles', 14, 11, 14, ' لأن اللاويين تركوا مسارحهم وأملاكهم وانطلقوا إلى يهوذا وأورشليم ، لأن يربعام وبنيه رفضوهم من أن يكهنوا للرب '),
(4772, '2 Chronicles', 14, 11, 15, ' وأقام لنفسه كهنة للمرتفعات وللتيوس وللعجول التي عمل '),
(4773, '2 Chronicles', 14, 11, 16, ' وبعدهم جاء إلى أورشليم من جميع أسباط إسرائيل ، الذين وجهوا قلوبهم إلى طلب الرب إله إسرائيل ، ليذبحوا للرب إله آبائهم '),
(4774, '2 Chronicles', 14, 11, 17, ' وشددوا مملكة يهوذا وقووا رحبعام بن سليمان ثلاث سنين ، لأنهم ساروا في طريق داود وسليمان ثلاث سنين '),
(4775, '2 Chronicles', 14, 11, 18, ' واتخذ رحبعام لنفسه امرأة : محلة بنت يريموث بن داود ، وأبيحايل بنت أليآب بن يسى '),
(4776, '2 Chronicles', 14, 11, 19, ' فولدت له بنين : يعوش وشمريا وزاهم '),
(4777, '2 Chronicles', 14, 11, 20, ' ثم بعدها أخذ معكة بنت أبشالوم ، فولدت له : أبيا وعتاي وزيزا وشلوميث '),
(4778, '2 Chronicles', 14, 11, 21, ' وأحب رحبعام معكة بنت أبشالوم أكثر من جميع نسائه وسراريه ، لأنه اتخذ ثماني عشرة امرأة وستين سرية ، وولد ثمانية وعشرين ابنا وستين ابنة '),
(4779, '2 Chronicles', 14, 11, 22, ' وأقام رحبعام أبيا ابن معكة رأسا وقائدا بين إخوته لكي يملكه '),
(4780, '2 Chronicles', 14, 11, 23, ' وكان فهيما ، وفرق من كل بنيه في جميع أراضي يهوذا وبنيامين في كل المدن الحصينة وأعطاهم زادا بكثرة . وطلب نساء كثيرة '),
(4781, '2 Chronicles', 14, 12, 1, ' ولما تثبتت مملكة رحبعام وتشددت ، ترك شريعة الرب هو وكل إسرائيل معه '),
(4782, '2 Chronicles', 14, 12, 2, ' وفي السنة الخامسة للملك رحبعام صعد شيشق ملك مصر على أورشليم ، لأنهم خانوا الرب '),
(4783, '2 Chronicles', 14, 12, 3, ' بألف ومئتي مركبة وستين ألف فارس ، ولم يكن عدد للشعب الذين جاءوا معه من مصر : لوبيين وسكيين وكوشيين '),
(4784, '2 Chronicles', 14, 12, 4, ' وأخذ المدن الحصينة التي ليهوذا وأتى إلى أورشليم '),
(4785, '2 Chronicles', 14, 12, 5, ' فجاء شمعيا النبي إلى رحبعام ورؤساء يهوذا الذين اجتمعوا في أورشليم من وجه شيشق ، وقال لهم : هكذا قال الرب : أنتم تركتموني وأنا أيضا تركتكم ليد شيشق '),
(4786, '2 Chronicles', 14, 12, 6, ' فتذلل رؤساء إسرائيل والملك وقالوا : بار هو الرب '),
(4787, '2 Chronicles', 14, 12, 7, ' فلما رأى الرب أنهم تذللوا ، كان كلام الرب إلى شمعيا قائلا : قد تذللوا فلا أهلكهم بل أعطيهم قليلا من النجاة ، ولا ينصب غضبي على أورشليم بيد شيشق '),
(4788, '2 Chronicles', 14, 12, 8, ' لكنهم يكونون له عبيدا ويعلمون خدمتي وخدمة ممالك الأراضي '),
(4789, '2 Chronicles', 14, 12, 9, ' فصعد شيشق ملك مصر على أورشليم وأخذ خزائن بيت الرب وخزائن بيت الملك ، أخذ الجميع ، وأخذ أتراس الذهب التي عملها سليمان '),
(4790, '2 Chronicles', 14, 12, 10, ' فعمل الملك رحبعام عوضا عنها أتراس نحاس وسلمها إلى أيدي رؤساء السعاة الحافظين باب بيت الملك '),
(4791, '2 Chronicles', 14, 12, 11, ' وكان إذا دخل الملك بيت الرب يأتي السعاة ويحملونها ، ثم يرجعونها إلى غرفة السعاة '),
(4792, '2 Chronicles', 14, 12, 12, ' ولما تذلل ارتد عنه غضب الرب فلم يهلكه تماما . وكذلك كان في يهوذا أمور حسنة '),
(4793, '2 Chronicles', 14, 12, 13, ' فتشدد الملك رحبعام في أورشليم وملك ، لأن رحبعام كان ابن إحدى وأربعين سنة حين ملك ، وملك سبع عشرة سنة في أورشليم ، المدينة التي اختارها الرب ليضع اسمه فيها دون جميع أسباط إسرائيل ، واسم أمه نعمة العمونية '),
(4794, '2 Chronicles', 14, 12, 14, ' وعمل الشر لأنه لم يهيئ قلبه لطلب الرب '),
(4795, '2 Chronicles', 14, 12, 15, ' وأمور رحبعام الأولى والأخيرة ، أماهي مكتوبة في أخبار شمعيا النبي وعدو الرائي عن الانتساب ؟ وكانت حروب بين رحبعام ويربعام كل الأيام '),
(4796, '2 Chronicles', 14, 12, 16, ' ثم اضطجع رحبعام مع آبائه ودفن في مدينة داود ، وملك أبيا ابنه عوضا عنه '),
(4797, '2 Chronicles', 14, 13, 1, ' في السنة الثامنة عشرة للملك يربعام ، ملك أبيا على يهوذا '),
(4798, '2 Chronicles', 14, 13, 2, ' ملك ثلاث سنين في أورشليم ، واسم أمه ميخايا بنت أوريئيل من جبعة . وكانت حرب بين أبيا ويربعام '),
(4799, '2 Chronicles', 14, 13, 3, ' وابتدأ أبيا في الحرب بجيش من جبابرة القتال ، أربع مئة ألف رجل مختار ، ويربعام اصطف لمحاربته بثمان مئة ألف رجل مختار ، جبابرة بأس '),
(4800, '2 Chronicles', 14, 13, 4, ' وقام أبيا على جبل صمارايم الذي في جبل أفرايم وقال : اسمعوني يا يربعام وكل إسرائيل '),
(4801, '2 Chronicles', 14, 13, 5, ' أما لكم أن تعرفوا أن الرب إله إسرائيل أعطى الملك على إسرائيل لداود إلى الأبد ولبنيه بعهد ملح '),
(4802, '2 Chronicles', 14, 13, 6, ' فقام يربعام بن نباط عبد سليمان بن داود وعصى سيده '),
(4803, '2 Chronicles', 14, 13, 7, ' فاجتمع إليه رجال بطالون بنو بليعال وتشددوا على رحبعام بن سليمان ، وكان رحبعام فتى رقيق القلب فلم يثبت أمامهم '),
(4804, '2 Chronicles', 14, 13, 8, ' والآن أنتم تقولون إنكم تثبتون أمام مملكة الرب بيد بني داود ، وأنتم جمهور كثير ومعكم عجول ذهب قد عملها يربعام لكم آلهة '),
(4805, '2 Chronicles', 14, 13, 9, ' أما طردتم كهنة الرب بني هارون واللاويين ، وعملتم لأنفسكم كهنة كشعوب الأراضي ، كل من أتى ليملأ يده بثور ابن بقر وسبعة كباش ، صار كاهنا للذين ليسوا آلهة '),
(4806, '2 Chronicles', 14, 13, 10, ' وأما نحن فالرب هو إلهنا ، ولم نتركه . والكهنة الخادمون الرب هم بنو هارون واللاويون في العمل '),
(4807, '2 Chronicles', 14, 13, 11, ' ويوقدون للرب محرقات كل صباح ومساء . وبخور أطياب وخبز الوجوه على المائدة الطاهرة ، ومنارة الذهب وسرجها للإيقاد كل مساء ، لأننا نحن حارسون حراسة الرب إلهنا . وأما أنتم فقد تركتموه '),
(4808, '2 Chronicles', 14, 13, 12, ' وهوذا معنا الله رئيسا ، وكهنته وأبواق الهتاف للهتاف عليكم . فيا بني إسرائيل ، لا تحاربوا الرب إله آبائكم لأنكم لا تفلحون '),
(4809, '2 Chronicles', 14, 13, 13, ' ولكن يربعام جعل الكمين يدور ليأتي من خلفهم . فكانوا أمام يهوذا والكمين خلفهم '),
(4810, '2 Chronicles', 14, 13, 14, ' فالتفت يهوذا وإذا الحرب عليهم من قدام ومن خلف . فصرخوا إلى الرب ، وبوق الكهنة بالأبواق '),
(4811, '2 Chronicles', 14, 13, 15, ' وهتف رجال يهوذا . ولما هتف رجال يهوذا ضرب الله يربعام وكل إسرائيل أمام أبيا ويهوذا '),
(4812, '2 Chronicles', 14, 13, 16, ' فانهزم بنو إسرائيل من أمام يهوذا ودفعهم الله ليدهم '),
(4813, '2 Chronicles', 14, 13, 17, ' وضربهم أبيا وقومه ضربة عظيمة ، فسقط قتلى من إسرائيل خمس مئة ألف رجل مختار '),
(4814, '2 Chronicles', 14, 13, 18, ' فذل بنو إسرائيل في ذلك الوقت وتشجع بنو يهوذا لأنهم اتكلوا على الرب إله آبائهم '),
(4815, '2 Chronicles', 14, 13, 19, ' وطارد أبيا يربعام وأخذ منه مدنا : بيت إيل وقراها ، ويشانة وقراها ، وعفرون وقراها '),
(4816, '2 Chronicles', 14, 13, 20, ' ولم يقو يربعام بعد في أيام أبيا ، فضربه الرب ومات '),
(4817, '2 Chronicles', 14, 13, 21, ' وتشدد أبيا واتخذ لنفسه أربع عشرة امرأة ، وولد اثنين وعشرين ابنا وست عشرة بنتا '),
(4818, '2 Chronicles', 14, 13, 22, ' وبقية أمور أبيا وطرقه وأقواله مكتوبة في مدرس النبي عدو '),
(4819, '2 Chronicles', 14, 14, 1, ' ثم اضطجع أبيا مع آبائه فدفنوه في مدينة داود ، وملك آسا ابنه عوضا عنه . في أيامه استراحت الأرض عشر سنين '),
(4820, '2 Chronicles', 14, 14, 2, ' وعمل آسا ما هو صالح ومستقيم في عيني الرب إلهه '),
(4821, '2 Chronicles', 14, 14, 3, ' ونزع المذابح الغريبة والمرتفعات ، وكسر التماثيل وقطع السواري '),
(4822, '2 Chronicles', 14, 14, 4, ' وقال ليهوذا أن يطلبوا الرب إله آبائهم وأن يعملوا حسب الشريعة والوصية '),
(4823, '2 Chronicles', 14, 14, 5, ' ونزع من كل مدن يهوذا المرتفعات وتماثيل الشمس ، واستراحت المملكة أمامه '),
(4824, '2 Chronicles', 14, 14, 6, ' وبنى مدنا حصينة في يهوذا لأن الأرض استراحت ولم تكن عليه حرب في تلك السنين ، لأن الرب أراحه '),
(4825, '2 Chronicles', 14, 18, 15, ' فقال له الملك : كم مرة أستحلفك أن لا تقول لي إلا الحق باسم الرب '),
(4826, '2 Chronicles', 14, 18, 16, ' فقال : رأيت كل إسرائيل مشتتين على الجبال كخراف لا راعي لها . فقال الرب : ليس لهؤلاء أصحاب ، فليرجعوا كل واحد إلى بيته بسلام '),
(4827, '2 Chronicles', 14, 18, 17, ' فقال ملك إسرائيل ليهوشافاط : أما قلت لك : إنه لا يتنبأ علي خيرا بل شرا '),
(4828, '2 Chronicles', 14, 18, 18, ' وقال : فاسمع إذا كلام الرب . قد رأيت الرب جالسا على كرسيه ، وكل جند السماء وقوف عن يمينه وعن يساره '),
(4829, '2 Chronicles', 14, 18, 19, ' فقال الرب : من يغوي أخآب ملك إسرائيل فيصعد ويسقط في راموت جلعاد ؟ فقال هذا هكذا ، وقال ذاك هكذا '),
(4830, '2 Chronicles', 14, 18, 20, ' ثم خرج الروح ووقف أمام الرب وقال : أنا أغويه . فقال له الرب : بماذا '),
(4831, '2 Chronicles', 14, 18, 21, ' فقال : أخرج وأكون لروح كذب في أفواه جميع أنبيائه . فقال : إنك تغويه وتقتدر . فاخرج وافعل هكذا '),
(4832, '2 Chronicles', 14, 18, 22, ' والآن هوذا قد جعل الرب روح كذب في أفواه أنبيائك هؤلاء ، والرب تكلم عليك بشر '),
(4833, '2 Chronicles', 14, 18, 23, ' فتقدم صدقيا بن كنعنة وضرب ميخا على الفك وقال : من أي طريق عبر روح الرب مني ليكلمك '),
(4834, '2 Chronicles', 14, 18, 24, ' فقال ميخا : إنك سترى في ذلك اليوم الذي تدخل فيه من مخدع إلى مخدع لتختبئ '),
(4835, '2 Chronicles', 14, 18, 25, ' فقال ملك إسرائيل : خذوا ميخا وردوه إلى أمون رئيس المدينة وإلى يوآش ابن الملك '),
(4836, '2 Chronicles', 14, 18, 26, ' وقولوا هكذا يقول الملك : ضعوا هذا في السجن ، وأطعموه خبز الضيق وماء الضيق حتى أرجع بسلام '),
(4837, '2 Chronicles', 14, 18, 27, ' فقال ميخا : إن رجعت رجوعا بسلام ، فلم يتكلم الرب بي . وقال : اسمعوا أيها الشعوب أجمعون '),
(4838, '2 Chronicles', 14, 18, 28, ' فصعد ملك إسرائيل ويهوشافاط ملك يهوذا إلى راموت جلعاد '),
(4839, '2 Chronicles', 14, 18, 29, ' وقال ملك إسرائيل ليهوشافاط : إني أتنكر وأدخل الحرب ، وأما أنت فالبس ثيابك . فتنكر ملك إسرائيل ودخلا الحرب '),
(4840, '2 Chronicles', 14, 18, 30, ' وأمر ملك أرام رؤساء المركبات التي له قائلا : لا تحاربوا صغيرا ولا كبيرا إلا ملك إسرائيل وحده '),
(4841, '2 Chronicles', 14, 18, 31, ' فلما رأى رؤساء المركبات يهوشافاط قالوا : إنه ملك إسرائيل ، فحاوطوه للقتال ، فصرخ يهوشافاط ، وساعده الرب وحولهم الله عنه '),
(4842, '2 Chronicles', 14, 18, 32, ' فلما رأى رؤساء المركبات أنه ليس ملك إسرائيل رجعوا عنه '),
(4843, '2 Chronicles', 14, 18, 33, ' وإن رجلا نزع في قوسه غير متعمد وضرب ملك إسرائيل بين أوصال الدرع ، فقال لمدير المركبة : رد يدك وأخرجني من الجيش لأني قد جرحت '),
(4844, '2 Chronicles', 14, 18, 34, ' واشتد القتال في ذلك اليوم ، وأوقف ملك إسرائيل في المركبة مقابل أرام إلى المساء ، ومات عند غروب الشمس '),
(4845, '2 Chronicles', 14, 19, 1, ' ورجع يهوشافاط ملك يهوذا إلى بيته بسلام إلى أورشليم '),
(4846, '2 Chronicles', 14, 19, 2, ' وخرج للقائه ياهو بن حناني الرائي ، وقال للملك يهوشافاط : أتساعد الشرير وتحب مبغضي الرب ؟ فلذلك الغضب عليك من قبل الرب '),
(4847, '2 Chronicles', 14, 19, 3, ' غير أنه وجد فيك أمور صالحة لأنك نزعت السواري من الأرض وهيأت قلبك لطلب الله '),
(4848, '2 Chronicles', 14, 19, 4, ' وأقام يهوشافاط في أورشليم ، ثم رجع وخرج أيضا بين الشعب من بئر سبع إلى جبل أفرايم وردهم إلى الرب إله آبائهم '),
(4849, '2 Chronicles', 14, 19, 5, ' وأقام قضاة في الأرض في كل مدن يهوذا المحصنة في كل مدينة فمدينة '),
(4850, '2 Chronicles', 14, 19, 6, ' وقال للقضاة : انظروا ما أنتم فاعلون ، لأنكم لا تقضون للإنسان بل للرب ، وهو معكم في أمر القضاء '),
(4851, '2 Chronicles', 14, 19, 7, ' والآن لتكن هيبة الرب عليكم . احذروا وافعلوا . لأنه ليس عند الرب إلهنا ظلم ولا محاباة ولا ارتشاء '),
(4852, '2 Chronicles', 14, 19, 8, ' وكذا في أورشليم أقام يهوشافاط من اللاويين والكهنة ومن رؤوس آباء إسرائيل لقضاء الرب والدعاوي . ورجعوا إلى أورشليم '),
(4853, '2 Chronicles', 14, 19, 9, ' وأمرهم قائلا : هكذا تفعلون بتقوى الرب بأمانة وقلب كامل '),
(4854, '2 Chronicles', 14, 19, 10, ' وفي كل دعوى تأتي إليكم من إخوتكم الساكنين في مدنهم ، بين دم ودم ، بين شريعة ووصية من جهة فرائض أو أحكام ، حذروهم فلا يأثموا إلى الرب فيكون غضب عليكم وعلى إخوتكم . هكذا افعلوا فلا تأثموا '),
(4855, '2 Chronicles', 14, 19, 11, ' وهوذا أمريا الكاهن الرأس عليكم في كل أمور الرب ، وزبديا بن يشمعئيل الرئيس على بيت يهوذا في كل أمور الملك ، والعرفاء اللاويون أمامكم . تشددوا وافعلوا ، وليكن الرب مع الصالح '),
(4856, '2 Chronicles', 14, 20, 1, ' ثم بعد ذلك أتى بنو موآب وبنو عمون ومعهم العمونيون على يهوشافاط للمحاربة '),
(4857, '2 Chronicles', 14, 20, 2, ' فجاء أناس وأخبروا يهوشافاط قائلين : قد جاء عليك جمهور كثير من عبر البحر من أرام ، وها هم في حصون تامار . هي عين جدي '),
(4858, '2 Chronicles', 14, 20, 3, ' فخاف يهوشافاط وجعل وجهه ليطلب الرب ، ونادى بصوم في كل يهوذا '),
(4859, '2 Chronicles', 14, 20, 4, ' واجتمع يهوذا ليسألوا الرب . جاءوا أيضا من كل مدن يهوذا ليسألوا الرب '),
(4860, '2 Chronicles', 14, 20, 5, ' فوقف يهوشافاط في جماعة يهوذا وأورشليم في بيت الرب أمام الدار الجديدة '),
(4861, '2 Chronicles', 14, 20, 6, ' وقال : يارب إله آبائنا ، أما أنت هو الله في السماء ، وأنت المتسلط على جميع ممالك الأمم ، وبيدك قوة وجبروت وليس من يقف معك '),
(4862, '2 Chronicles', 14, 20, 7, ' ألست أنت إلهنا الذي طردت سكان هذه الأرض من أمام شعبك إسرائيل وأعطيتها لنسل إبراهيم خليلك إلى الأبد '),
(4863, '2 Chronicles', 14, 20, 8, ' فسكنوا فيها وبنوا لك فيها مقدسا لاسمك قائلين '),
(4864, '2 Chronicles', 14, 20, 9, ' إذا جاء علينا شر ، سيف قضاء أو وبأ أو جوع ، ووقفنا أمام هذا البيت وأمامك ، لأن اسمك في هذا البيت ، وصرخنا إليك من ضيقنا فإنك تسمع وتخلص '),
(4865, '2 Chronicles', 14, 20, 10, ' والآن هوذا بنو عمون وموآب وجبل ساعير ، الذين لم تدع إسرائيل يدخلون إليهم حين جاءوا من أرض مصر ، بل مالوا عنهم ولم يهلكوهم '),
(4866, '2 Chronicles', 14, 20, 11, ' فهوذا هم يكافئوننا بمجيئهم لطردنا من ملكك الذي ملكتنا إياه '),
(4867, '2 Chronicles', 14, 20, 12, ' يا إلهنا أما تقضي عليهم لأنه ليس فينا قوة أمام هذا الجمهور الكثير الآتي علينا ، ونحن لا نعلم ماذا نعمل ولكن نحوك أعيننا '),
(4868, '2 Chronicles', 14, 20, 13, ' وكان كل يهوذا واقفين أمام الرب مع أطفالهم ونسائهم وبنيهم '),
(4869, '2 Chronicles', 14, 20, 14, ' وإن يحزئيل بن زكريا بن بنايا بن يعيئيل بن متنيا اللاوي من بني آساف ، كان عليه روح الرب في وسط الجماعة '),
(4870, '2 Chronicles', 14, 20, 15, ' فقال : اصغوا يا جميع يهوذا وسكان أورشليم ، وأيها الملك يهوشافاط . هكذا قال الرب لكم : لا تخافوا ولا ترتاعوا بسبب هذا الجمهور الكثير ، لأن الحرب ليست لكم بل لله '),
(4871, '2 Chronicles', 14, 20, 16, ' غدا انزلوا عليهم . هوذا هم صاعدون في عقبة صيص فتجدوهم في أقصى الوادي أمام برية يروئيل '),
(4872, '2 Chronicles', 14, 20, 17, ' ليس عليكم أن تحاربوا في هذه . قفوا اثبتوا وانظروا خلاص الرب معكم يا يهوذا وأورشليم . لا تخافوا ولا ترتاعوا . غدا اخرجوا للقائهم والرب معكم '),
(4873, '2 Chronicles', 14, 20, 18, ' فخر يهوشافاط لوجهه على الأرض ، وكل يهوذا وسكان أورشليم سقطوا أمام الرب سجودا للرب '),
(4874, '2 Chronicles', 14, 20, 19, ' فقام اللاويون من بني القهاتيين ومن بني القورحيين ليسبحوا الرب إله إسرائيل بصوت عظيم جدا '),
(4875, '2 Chronicles', 14, 20, 20, ' وبكروا صباحا وخرجوا إلى برية تقوع . وعند خروجهم وقف يهوشافاط وقال : اسمعوا يا يهوذا وسكان أورشليم ، آمنوا بالرب إلهكم فتأمنوا . آمنوا بأنبيائه فتفلحوا '),
(4876, '2 Chronicles', 14, 20, 21, ' ولما استشار الشعب أقام مغنين للرب ومسبحين في زينة مقدسة عند خروجهم أمام المتجردين وقائلين : احمدوا الرب لأن إلى الأبد رحمته '),
(4877, '2 Chronicles', 14, 20, 22, ' ولما ابتدأوا في الغناء والتسبيح جعل الرب أكمنة على بني عمون وموآب وجبل ساعير الآتين على يهوذا ، فانكسروا '),
(4878, '2 Chronicles', 14, 20, 23, ' وقام بنو عمون وموآب على سكان جبل ساعير ليحرموهم ويهلكوهم . ولما فرغوا من سكان ساعير ساعد بعضهم على إهلاك بعض '),
(4879, '2 Chronicles', 14, 20, 24, ' ولما جاء يهوذا إلى المرقب في البرية تطلعوا نحو الجمهور وإذا هم جثث ساقطة على الأرض ولم ينفلت أحد '),
(4880, '2 Chronicles', 14, 20, 25, ' فأتى يهوشافاط وشعبه لنهب أموالهم ، فوجدوا بينهم أموالا وجثثا وأمتعة ثمينة بكثرة ، فأخذوها لأنفسهم حتى لم يقدروا أن يحملوها . وكانوا ثلاثة أيام ينهبون الغنيمة لأنها كانت كثيرة '),
(4881, '2 Chronicles', 14, 20, 26, ' وفي اليوم الرابع اجتمعوا في وادي بركة ، لأنهم هناك باركوا الرب ، لذلك دعوا اسم ذلك المكان وادي بركة إلى اليوم '),
(4882, '2 Chronicles', 14, 20, 27, ' ثم ارتد كل رجال يهوذا وأورشليم ويهوشافاط برأسهم ليرجعوا إلى أورشليم بفرح ، لأن الرب فرحهم على أعدائهم '),
(4883, '2 Chronicles', 14, 20, 28, ' ودخلوا أورشليم بالرباب والعيدان والأبواق إلى بيت الرب '),
(4884, '2 Chronicles', 14, 20, 29, ' وكانت هيبة الله على كل ممالك الأراضي حين سمعوا أن الرب حارب أعداء إسرائيل '),
(4885, '2 Chronicles', 14, 20, 30, ' واستراحت مملكة يهوشافاط ، وأراحه إلهه من كل جهة '),
(4886, '2 Chronicles', 14, 20, 31, ' وملك يهوشافاط على يهوذا . كان ابن خمس وثلاثين سنة حين ملك ، وملك خمسا وعشرين سنة في أورشليم ، واسم أمه عزوبة بنت شلحي '),
(4887, '2 Chronicles', 14, 20, 32, ' وسار في طريق أبيه آسا ولم يحد عنها إذ عمل المستقيم في عيني الرب '),
(4888, '2 Chronicles', 14, 20, 33, ' إلا أن المرتفعات لم تنتزع ، بل كان الشعب لم يعدوا بعد قلوبهم لإله آبائهم '),
(4889, '2 Chronicles', 14, 20, 34, ' وبقية أمور يهوشافاط الأولى والأخيرة ، ها هي مكتوبة في أخبار ياهو بن حناني المذكور في سفر ملوك إسرائيل '),
(4890, '2 Chronicles', 14, 20, 35, ' ثم بعد ذلك اتحد يهوشافاط ملك يهوذا مع أخزيا ملك إسرائيل الذي أساء في عمله '),
(4891, '2 Chronicles', 14, 20, 36, ' فاتحد معه في عمل سفن تسير إلى ترشيش ، فعملا السفن في عصيون جابر '),
(4892, '2 Chronicles', 14, 20, 37, ' وتنبأ أليعزر بن دوداواهو من مريشة على يهوشافاط قائلا : لأنك اتحدت مع أخزيا ، قد اقتحم الرب أعمالك . فتكسرت السفن ولم تستطع السير إلى ترشيش '),
(4893, '2 Chronicles', 14, 21, 1, ' واضطجع يهوشافاط مع آبائه فدفن مع آبائه في مدينة داود ، وملك يهورام ابنه عوضا عنه '),
(4894, '2 Chronicles', 14, 21, 2, ' وكان له إخوة ، بنو يهوشافاط : عزريا ويحيئيل وزكريا وعزرياهو وميخائيل وشفطيا . كل هؤلاء بنو يهوشافاط ملك إسرائيل '),
(4895, '2 Chronicles', 14, 21, 3, ' وأعطاهم أبوهم عطايا كثيرة من فضة وذهب وتحف مع مدن حصينة في يهوذا . وأما المملكة فأعطاها ليهورام لأنه البكر '),
(4896, '2 Chronicles', 14, 21, 4, ' فقام يهورام على مملكة أبيه وتشدد وقتل جميع إخوته بالسيف ، وأيضا بعضا من رؤساء إسرائيل '),
(4897, '2 Chronicles', 14, 21, 5, ' كان يهورام ابن اثنتين وثلاثين سنة حين ملك ، وملك ثماني سنين في أورشليم '),
(4898, '2 Chronicles', 14, 21, 6, ' وسار في طريق ملوك إسرائيل كما فعل بيت أخآب ، لأن بنت أخآب كانت له امرأة . وعمل الشر في عيني الرب '),
(4899, '2 Chronicles', 14, 21, 7, ' ولم يشإ الرب أن يبيد بيت داود لأجل العهد الذي قطعه مع داود ، ولأنه قال إنه يعطيه وبنيه سراجا كل الأيام '),
(4900, '2 Chronicles', 14, 31, 2, ' وأقام حزقيا فرق الكهنة واللاويين حسب أقسامهم ، كل واحد حسب خدمته ، الكهنة واللاويين للمحرقات وذبائح السلامة ، للخدمة والحمد والتسبيح في أبواب محلات الرب '),
(4901, '2 Chronicles', 14, 31, 3, ' وأعطى الملك حصة من ماله للمحرقات ، محرقات الصباح والمساء ، والمحرقات للسبوت والأشهر والمواسم ، كما هو مكتوب في شريعة الرب '),
(4902, '2 Chronicles', 14, 31, 4, ' وقال للشعب سكان أورشليم أن يعطوا حصة الكهنة واللاويين ، لكي يتمسكوا بشريعة الرب '),
(4903, '2 Chronicles', 14, 31, 5, ' ولما شاع الأمر كثر بنو إسرائيل من أوائل الحنطة والمسطار والزيت والعسل ، ومن كل غلة الحقل وأتوا بعشر الجميع بكثرة '),
(4904, '2 Chronicles', 14, 31, 6, ' وبنو إسرائيل ويهوذا الساكنون في مدن يهوذا أتوا هم أيضا بعشر البقر والضأن ، وعشر الأقداس المقدسة للرب إلههم ، وجعلوها صبرا صبرا '),
(4905, '2 Chronicles', 14, 31, 7, ' في الشهر الثالث ابتدأوا بتأسيس الصبر ، وفي الشهر السابع أكملوا '),
(4906, '2 Chronicles', 14, 31, 8, ' وجاء حزقيا والرؤساء ورأوا الصبر ، فباركوا الرب وشعبه إسرائيل '),
(4907, '2 Chronicles', 14, 31, 9, ' وسأل حزقيا الكهنة واللاويين عن الصبر '),
(4908, '2 Chronicles', 14, 31, 10, ' فكلمه عزريا الكاهن الرأس لبيت صادوق وقال : منذ ابتدأ بجلب التقدمة إلى بيت الرب ، أكلنا وشبعنا وفضل عنا بكثرة ، لأن الرب بارك شعبه ، والذي فضل هو هذه الكثرة '),
(4909, '2 Chronicles', 14, 31, 11, ' وأمر حزقيا بإعداد مخادع في بيت الرب ، فأعدوا '),
(4910, '2 Chronicles', 14, 31, 12, ' وأتوا بالتقدمة والعشر والأقداس بأمانة . وكان رئيسا عليهم كوننيا اللاوي ، وشمعي أخوه الثاني '),
(4911, '2 Chronicles', 14, 31, 13, ' ويحيئيل وعززيا ونحث وعسائيل ويريموث ويوزاباد وإيليئيل ويسمخيا ومحث وبنايا وكلاء تحت يد كوننيا وشمعي أخيه ، حسب تعيين حزقيا الملك وعزريا رئيس بيت الله '),
(4912, '2 Chronicles', 14, 31, 14, ' وقوري بن يمنة اللاوي البواب نحو الشرق كان على المتبرع به لله لإعطاء تقدمة الرب وأقداس الأقداس '),
(4913, '2 Chronicles', 14, 31, 15, ' وتحت يده : عدن ومنيامين ويشوع وشمعيا وأمريا وشكنيا في مدن الكهنة بأمانة ، ليعطوا لإخوتهم حسب الفرق الكبير كالصغير '),
(4914, '2 Chronicles', 14, 31, 16, ' فضلا عن انتساب ذكورهم من ابن ثلاث سنين فما فوق من كل داخل بيت الرب ، أمر كل يوم بيومه حسب خدمتهم في حراساتهم حسب أقسامهم '),
(4915, '2 Chronicles', 14, 31, 17, ' وانتساب الكهنة حسب بيوت آبائهم ، واللاويين من ابن عشرين سنة فما فوق حسب حراساتهم وأقسامهم '),
(4916, '2 Chronicles', 14, 31, 18, ' وانتساب جميع أطفالهم ونسائهم وبنيهم وبناتهم في كل الجماعة ، لأنهم بأمانتهم تقدسوا تقدسا '),
(4917, '2 Chronicles', 14, 31, 19, ' ومن بني هارون الكهنة في حقول مسارح مدنهم في كل مدينة فمدينة ، الرجال المعينة أسماؤهم لإعطاء حصص لكل ذكر من الكهنة ولكل من انتسب من اللاويين '),
(4918, '2 Chronicles', 14, 31, 20, ' هكذا عمل حزقيا في كل يهوذا ، وعمل ما هو صالح ومستقيم وحق أمام الرب إلهه '),
(4919, '2 Chronicles', 14, 31, 21, ' وكل عمل ابتدأ به في خدمة بيت الله وفي الشريعة والوصية ليطلب إلهه ، إنما عمله بكل قلبه وأفلح '),
(4920, '2 Chronicles', 14, 32, 1, ' وبعد هذه الأمور وهذه الأمانة ، أتى سنحاريب ملك أشور ودخل يهوذا ونزل على المدن الحصينة وطمع بإخضاعها لنفسه '),
(4921, '2 Chronicles', 14, 32, 2, ' ولما رأى حزقيا أن سنحاريب قد أتى ووجهه على محاربة أورشليم '),
(4922, '2 Chronicles', 14, 32, 3, ' تشاور هو ورؤساؤه وجبابرته على طم مياه العيون التي هي خارج المدينة فساعدوه '),
(4923, '2 Chronicles', 14, 32, 4, ' فتجمع شعب كثير وطموا جميع الينابيع والنهر الجاري في وسط الأرض ، قائلين : لماذا يأتي ملوك أشور ويجدون مياها غزيرة '),
(4924, '2 Chronicles', 14, 32, 5, ' وتشدد وبنى كل السور المنهدم وأعلاه إلى الأبراج ، وسورا آخر خارجا ، وحصن القلعة ، مدينة داود ، وعمل سلاحا بكثرة وأتراسا '),
(4925, '2 Chronicles', 14, 32, 6, ' وجعل رؤساء قتال على الشعب ، وجمعهم إليه إلى ساحة باب المدينة ، وطيب قلوبهم قائلا '),
(4926, '2 Chronicles', 14, 32, 7, ' تشددوا وتشجعوا . لا تخافوا ولا ترتاعوا من ملك أشور ومن كل الجمهور الذي معه ، لأن معنا أكثر مما معه '),
(4927, '2 Chronicles', 14, 32, 8, ' معه ذراع بشر ، ومعنا الرب إلهنا ليساعدنا ويحارب حروبنا . فاستند الشعب على كلام حزقيا ملك يهوذا '),
(4928, '2 Chronicles', 14, 32, 9, ' بعد هذا أرسل سنحاريب ملك أشور عبيده إلى أورشليم ، وهو على لخيش وكل سلطنته معه ، إلى حزقيا ملك يهوذا وإلى كل يهوذا الذين في أورشليم يقولون '),
(4929, '2 Chronicles', 14, 32, 10, ' هكذا يقول سنحاريب ملك أشور : على ماذا تتكلون وتقيمون في الحصار في أورشليم '),
(4930, '2 Chronicles', 14, 32, 11, ' أليس حزقيا يغويكم ليدفعكم للموت بالجوع والعطش ، قائلا : الرب إلهنا ينقذنا من يد ملك أشور '),
(4931, '2 Chronicles', 14, 32, 12, ' أليس حزقيا هو الذي أزال مرتفعاته ومذابحه ، وكلم يهوذا وأورشليم قائلا : أمام مذبح واحد تسجدون ، وعليه توقدون '),
(4932, '2 Chronicles', 14, 32, 13, ' أما تعلمون ما فعلته أنا وآبائي بجميع شعوب الأراضي ؟ فهل قدرت آلهة أمم الأراضي أن تنقذ أرضها من يدي '),
(4933, '2 Chronicles', 14, 32, 14, ' من من جميع آلهة هؤلاء الأمم الذين حرمهم آبائي ، استطاع أن ينقذ شعبه من يدي حتى يستطيع إلهكم أن ينقذكم من يدي '),
(4934, '2 Chronicles', 14, 32, 15, ' والآن لا يخدعنكم حزقيا ، ولا يغوينكم هكذا ولا تصدقوه ، لأنه لم يقدر إله أمة أو مملكة أن ينقذ شعبه من يدي ويد آبائي ، فكم بالحري إلهكم لا ينقذكم من يدي '),
(4935, '2 Chronicles', 14, 32, 16, ' وتكلم عبيده أكثر ضد الرب الإله وضد حزقيا عبده '),
(4936, '2 Chronicles', 14, 32, 17, ' وكتب رسائل لتعيير الرب إله إسرائيل وللتكلم ضده قائلا : كما أن آلهة أمم الأراضي لم تنقذ شعوبها من يدي ، كذلك لا ينقذ إله حزقيا شعبه من يدي '),
(4937, '2 Chronicles', 14, 32, 18, ' وصرخوا بصوت عظيم باليهودي إلى شعب أورشليم الذين على السور لتخويفهم وترويعهم لكي يأخذوا المدينة '),
(4938, '2 Chronicles', 14, 32, 19, ' وتكلموا على إله أورشليم كما على آلهة شعوب الأرض صنعة أيدي الناس '),
(4939, '2 Chronicles', 14, 32, 20, ' فصلى حزقيا الملك وإشعياء بن آموص النبي لذلك وصرخا إلى السماء '),
(4940, '2 Chronicles', 14, 32, 21, ' فأرسل الرب ملاكا فأباد كل جبار بأس ورئيس وقائد في محلة ملك أشور . فرجع بخزي الوجه إلى أرضه . ولما دخل بيت إلهه قتله هناك بالسيف الذين خرجوا من أحشائه '),
(4941, '2 Chronicles', 14, 32, 22, ' وخلص الرب حزقيا وسكان أورشليم من سنحاريب ملك أشور ومن يد الجميع ، وحماهم من كل ناحية '),
(4942, '2 Chronicles', 14, 32, 23, ' وكان كثيرون يأتون بتقدمات الرب إلى أورشليم ، وتحف لحزقيا ملك يهوذا ، واعتبر في أعين جميع الأمم بعد ذلك '),
(4943, '2 Chronicles', 14, 32, 24, ' في تلك الأيام مرض حزقيا إلى حد الموت وصلى إلى الرب فكلمه وأعطاه علامة '),
(4944, '2 Chronicles', 14, 32, 25, ' ولكن لم يرد حزقيا حسبما أنعم عليه لأن قلبه ارتفع ، فكان غضب عليه وعلى يهوذا وأورشليم '),
(4945, '2 Chronicles', 14, 32, 26, ' ثم تواضع حزقيا بسبب ارتفاع قلبه هو وسكان أورشليم ، فلم يأت عليهم غضب الرب في أيام حزقيا '),
(4946, '2 Chronicles', 14, 32, 27, ' وكان لحزقيا غنى وكرامة كثيرة جدا ، وعمل لنفسه خزائن للفضة والذهب والحجارة الكريمة والأطياب والأتراس وكل آنية ثمينة '),
(4947, '2 Chronicles', 14, 32, 28, ' ومخازن لغلة الحنطة والمسطار والزيت ، وأواري لكل أنواع البهائم ، وللقطعان أواري '),
(4948, '2 Chronicles', 14, 32, 29, ' وعمل لنفسه أبراجا ومواشي غنم وبقر بكثرة ، لأن الله أعطاه أموالا كثيرة جدا '),
(4949, '2 Chronicles', 14, 32, 30, ' وحزقيا هذا سد مخرج مياه جيحون الأعلى ، وأجراها تحت الأرض ، إلى الجهة الغربية من مدينة داود . وأفلح حزقيا في كل عمله '),
(4950, '2 Chronicles', 14, 32, 31, ' وهكذا في أمر تراجم رؤساء بابل الذين أرسلوا إليه ليسألوا عن الأعجوبة التي كانت في الأرض ، تركه الله ليجربه ليعلم كل ما في قلبه '),
(4951, '2 Chronicles', 14, 32, 32, ' وبقية أمور حزقيا ومراحمه ، ها هي مكتوبة في رؤيا إشعياء بن آموص النبي ، في سفر ملوك يهوذا وإسرائيل '),
(4952, '2 Chronicles', 14, 32, 33, ' ثم اضطجع حزقيا مع آبائه فدفنوه في عقبة قبور بني داود ، وعمل له إكراما عند موته كل يهوذا وسكان أورشليم . وملك منسى ابنه عوضا عنه '),
(4953, '2 Chronicles', 14, 33, 1, ' كان منسى ابن اثنتي عشرة سنة حين ملك ، وملك خمسا وخمسين سنة في أورشليم '),
(4954, '2 Chronicles', 14, 33, 2, ' وعمل الشر في عيني الرب حسب رجاسات الأمم الذين طردهم الرب من أمام بني إسرائيل '),
(4955, '2 Chronicles', 14, 33, 3, ' وعاد فبنى المرتفعات التي هدمها حزقيا أبوه ، وأقام مذابح للبعليم ، وعمل سواري وسجد لكل جند السماء وعبدها '),
(4956, '2 Chronicles', 14, 33, 4, ' وبنى مذابح في بيت الرب الذي قال عنه الرب : في أورشليم يكون اسمي إلى الأبد '),
(4957, '2 Chronicles', 14, 33, 5, ' وبنى مذابح لكل جند السماء في داري بيت الرب '),
(4958, '2 Chronicles', 14, 33, 6, ' وعبر بنيه في النار في وادي ابن هنوم ، وعاف وتفاءل وسحر ، واستخدم جانا وتابعة ، وأكثر عمل الشر في عيني الرب لإغاظته '),
(4959, '2 Chronicles', 14, 33, 7, ' ووضع تمثال الشكل الذي عمله في بيت الله الذي قال الله عنه لداود ولسليمان ابنه : في هذا البيت وفي أورشليم التي اخترت من جميع أسباط إسرائيل أضع اسمي إلى الأبد '),
(4960, '2 Chronicles', 14, 33, 8, ' ولا أعود أزحزح رجل إسرائيل عن الأرض التي عينت لآبائهم ، وذلك إذا حفظوا وعملوا كل ما أوصيتهم به ، كل الشريعة والفرائض والأحكام عن يد موسى '),
(4961, '2 Chronicles', 14, 33, 9, ' ولكن منسى أضل يهوذا وسكان أورشليم ليعملوا أشر من الأمم الذين طردهم الرب من أمام بني إسرائيل '),
(4962, '2 Chronicles', 14, 33, 10, ' وكلم الرب منسى وشعبه فلم يصغوا '),
(4963, '2 Chronicles', 14, 33, 11, ' فجلب الرب عليهم رؤساء الجند الذين لملك أشور ، فأخذوا منسى بخزامة وقيدوه بسلاسل نحاس وذهبوا به إلى بابل '),
(4964, '2 Chronicles', 14, 33, 12, ' ولما تضايق طلب وجه الرب إلهه ، وتواضع جدا أمام إله آبائه '),
(4965, '2 Chronicles', 14, 33, 13, ' وصلى إليه فاستجاب له وسمع تضرعه ، ورده إلى أورشليم إلى مملكته . فعلم منسى أن الرب هو الله '),
(4966, '2 Chronicles', 14, 33, 14, ' وبعد ذلك بنى سورا خارج مدينة داود غربا إلى جيحون في الوادي ، وإلى مدخل باب السمك ، وحوط الأكمة بسور وعلاه جدا . ووضع رؤساء جيوش في جميع المدن الحصينة في يهوذا '),
(4967, '2 Chronicles', 14, 33, 15, ' وأزال الآلهة الغريبة والأشباه من بيت الرب ، وجميع المذابح التي بناها في جبل بيت الرب وفي أورشليم ، وطرحها خارج المدينة '),
(4968, '2 Chronicles', 14, 33, 16, ' ورمم مذبح الرب وذبح عليه ذبائح سلامة وشكر ، وأمر يهوذا أن يعبدوا الرب إله إسرائيل '),
(4969, '2 Chronicles', 14, 33, 17, ' إلا أن الشعب كانوا بعد يذبحون على المرتفعات ، إنما للرب إلههم '),
(4970, '2 Chronicles', 14, 33, 18, ' وبقية أمور منسى وصلاته إلى إلهه ، وكلام الرائين الذين كلموه باسم الرب إله إسرائيل ، ها هي في أخبار ملوك إسرائيل '),
(4971, '2 Chronicles', 14, 33, 19, ' وصلاته والاستجابة له ، وكل خطاياه وخيانته والأماكن التي بنى فيها مرتفعات وأقام سواري وتماثيل قبل تواضعه ، ها هي مكتوبة في أخبار الرائين '),
(4972, '2 Chronicles', 14, 33, 20, ' ثم اضطجع منسى مع آبائه فدفنوه في بيته ، وملك آمون ابنه عوضا عنه '),
(4973, '2 Chronicles', 14, 33, 21, ' كان آمون ابن اثنتين وعشرين سنة حين ملك ، وملك سنتين في أورشليم '),
(4974, '2 Chronicles', 14, 33, 22, ' وعمل الشر في عيني الرب كما عمل منسى أبوه ، وذبح آمون لجميع التماثيل التي عمل منسى أبوه وعبدها '),
(4975, '2 Chronicles', 14, 28, 18, ' واقتحم الفلسطينيون مدن السواحل وجنوبي يهوذا ، وأخذوا بيت شمس وأيلون وجديروت وسوكو وقراها ، وتمنة وقراها ، وحمزو وقراها ، وسكنوا هناك '),
(4976, '2 Chronicles', 14, 28, 19, ' لأن الرب ذلل يهوذا بسبب آحاز ملك إسرائيل ، لأنه أجمح يهوذا وخان الرب خيانة '),
(4977, '2 Chronicles', 14, 28, 20, ' فجاء عليه تلغث فلناسر ملك أشور وضايقه ولم يشدده '),
(4978, '2 Chronicles', 14, 28, 21, ' لأن آحاز أخذ قسما من بيت الرب ومن بيت الملك ومن الرؤساء وأعطاه لملك أشور ولكنه لم يساعده '),
(4979, '2 Chronicles', 14, 28, 22, ' وفي ضيقه زاد خيانة بالرب الملك آحاز هذا '),
(4980, '2 Chronicles', 14, 28, 23, ' وذبح لآلهة دمشق الذين ضاربوه وقال : لأن آلهة ملوك أرام تساعدهم أنا أذبح لهم فيساعدونني . وأما هم فكانوا سبب سقوط له ولكل إسرائيل '),
(4981, '2 Chronicles', 14, 28, 24, ' وجمع آحاز آنية بيت الله وقطع آنية بيت الله وأغلق أبواب بيت الرب ، وعمل لنفسه مذابح في كل زاوية في أورشليم '),
(4982, '2 Chronicles', 14, 28, 25, ' وفي كل مدينة فمدينة من يهوذا عمل مرتفعات للإيقاد لآلهة أخرى ، وأسخط الرب إله آبائه '),
(4983, '2 Chronicles', 14, 28, 26, ' وبقية أموره وكل طرقه الأولى والأخيرة ، ها هي مكتوبة في سفر ملوك يهوذا وإسرائيل '),
(4984, '2 Chronicles', 14, 28, 27, ' ثم اضطجع آحاز مع آبائه فدفنوه في المدينة في أورشليم ، لأنهم لم يأتوا به إلى قبور ملوك إسرائيل . وملك حزقيا ابنه عوضا عنه '),
(4985, '2 Chronicles', 14, 29, 1, ' ملك حزقيا وهو ابن خمس وعشرين سنة ، وملك تسعا وعشرين سنة في أورشليم ، واسم أمه أبية بنت زكريا '),
(4986, '2 Chronicles', 14, 29, 2, ' وعمل المستقيم في عيني الرب حسب كل ما عمل داود أبوه '),
(4987, '2 Chronicles', 14, 29, 3, ' هو في السنة الأولى من ملكه في الشهر الأول فتح أبواب بيت الرب ورممها '),
(4988, '2 Chronicles', 14, 29, 4, ' وأدخل الكهنة واللاويين وجمعهم إلى الساحة الشرقية '),
(4989, '2 Chronicles', 14, 29, 5, ' وقال لهم : اسمعوا لي أيها اللاويون ، تقدسوا الآن وقدسوا بيت الرب إله آبائكم ، وأخرجوا النجاسة من القدس '),
(4990, '2 Chronicles', 14, 29, 6, ' لأن آباءنا خانوا وعملوا الشر في عيني الرب إلهنا وتركوه ، وحولوا وجوههم عن مسكن الرب وأعطوا قفا '),
(4991, '2 Chronicles', 14, 29, 7, ' وأغلقوا أيضا أبواب الرواق وأطفأوا السرج ولم يوقدوا بخورا ولم يصعدوا محرقة في القدس لإله إسرائيل '),
(4992, '2 Chronicles', 14, 29, 8, ' فكان غضب الرب على يهوذا وأورشليم ، وأسلمهم للقلق والدهش والصفير كما أنتم راؤون بأعينكم '),
(4993, '2 Chronicles', 14, 29, 9, ' وهوذا قد سقط آباؤنا بالسيف ، وبنونا وبناتنا ونساؤنا في السبي لأجل هذا '),
(4994, '2 Chronicles', 14, 29, 10, ' فالآن في قلبي أن أقطع عهدا مع الرب إله إسرائيل فيرد عنا حمو غضبه '),
(4995, '2 Chronicles', 14, 29, 11, ' يا بني ، لا تضلوا الآن لأن الرب اختاركم لكي تقفوا أمامه وتخدموه وتكونوا خادمين وموقدين له '),
(4996, '2 Chronicles', 14, 29, 12, ' فقام اللاويون : محث بن عماساي ويوئيل بن عزريا من بني القهاتيين ، ومن بني مراري : قيس بن عبدي وعزريا بن يهللئيل ، ومن الجرشونيين : يوآخ بن زمة وعيدن بن يوآخ '),
(4997, '2 Chronicles', 14, 29, 13, ' ومن بني أليصافان : شمري ويعيئيل ، ومن بني آساف : زكريا ومتنيا '),
(4998, '2 Chronicles', 14, 29, 14, ' ومن بني هيمان : يحيئيل وشمعي ، ومن بني يدوثون : شمعيا وعزيئيل '),
(4999, '2 Chronicles', 14, 29, 15, ' وجمعوا إخوتهم وتقدسوا وأتوا حسب أمر الملك بكلام الرب ليطهروا بيت الرب '),
(5000, '2 Chronicles', 14, 29, 16, ' ودخل الكهنة إلى داخل بيت الرب ليطهروه ، وأخرجوا كل النجاسة التي وجدوها في هيكل الرب إلى دار بيت الرب ، وتناولها اللاويون ليخرجوها إلى الخارج إلى وادي قدرون '),
(5001, '2 Chronicles', 14, 29, 17, ' وشرعوا في التقديس في أول الشهر الأول . وفي اليوم الثامن من الشهر انتهوا إلى رواق الرب وقدسوا بيت الرب في ثمانية أيام ، وفي اليوم السادس عشر من الشهر الأول انتهوا '),
(5002, '2 Chronicles', 14, 29, 18, ' ودخلوا إلى داخل ، إلى حزقيا الملك وقالوا : قد طهرنا كل بيت الرب ومذبح المحرقة وكل آنيته ومائدة خبز الوجوه وكل آنيتها '),
(5003, '2 Chronicles', 14, 29, 19, ' وجميع الآنية التي طرحها الملك آحاز في ملكه بخيانته ، قد هيأناها وقدسناها ، وها هي أمام مذبح الرب '),
(5004, '2 Chronicles', 14, 29, 20, ' وبكر حزقيا الملك وجمع رؤساء المدينة وصعد إلى بيت الرب '),
(5005, '2 Chronicles', 14, 29, 21, ' فأتوا بسبعة ثيران وسبعة كباش وسبعة خرفان وسبعة تيوس معزى ذبيحة خطية عن المملكة وعن المقدس وعن يهوذا . وقال لبني هارون الكهنة أن يصعدوها على مذبح الرب '),
(5006, '2 Chronicles', 14, 29, 22, ' فذبحوا الثيران ، وتناول الكهنة الدم ورشوه على المذبح ، ثم ذبحوا الكباش ورشوا الدم على المذبح ، ثم ذبحوا الخرفان ورشوا الدم على المذبح '),
(5007, '2 Chronicles', 14, 29, 23, ' ثم تقدموا بتيوس ذبيحة الخطية أمام الملك والجماعة ، ووضعوا أيديهم عليها '),
(5008, '2 Chronicles', 14, 29, 24, ' وذبحها الكهنة وكفروا بدمها على المذبح تكفيرا عن جميع إسرائيل ، لأن الملك قال إن المحرقة وذبيحة الخطية هما عن كل إسرائيل '),
(5009, '2 Chronicles', 14, 29, 25, ' وأوقف اللاويين في بيت الرب بصنوج ورباب وعيدان حسب أمر داود وجاد رائي الملك وناثان النبي ، لأن من قبل الرب الوصية عن يد أنبيائه '),
(5010, '2 Chronicles', 14, 29, 26, ' فوقف اللاويون بآلات داود ، والكهنة بالأبواق '),
(5011, '2 Chronicles', 14, 29, 27, ' وأمر حزقيا بإصعاد المحرقة على المذبح . وعند ابتداء المحرقة ابتدأ نشيد الرب والأبواق بواسطة آلات داود ملك إسرائيل '),
(5012, '2 Chronicles', 14, 29, 28, ' وكان كل الجماعة يسجدون والمغنون يغنون والمبوقون يبوقون . الجميع ، إلى أن انتهت المحرقة '),
(5013, '2 Chronicles', 14, 29, 29, ' وعند انتهاء المحرقة خر الملك وكل الموجودين معه وسجدوا '),
(5014, '2 Chronicles', 14, 29, 30, ' وقال حزقيا الملك والرؤساء للاويين أن يسبحوا الرب بكلام داود وآساف الرائي ، فسبحوا بابتهاج وخروا وسجدوا '),
(5015, '2 Chronicles', 14, 29, 31, ' ثم أجاب حزقيا وقال : الآن ملأتم أيديكم للرب . تقدموا وأتوا بذبائح وقرابين شكر لبيت الرب . فأتت الجماعة بذبائح وقرابين شكر ، وكل سموح القلب أتى بمحرقات '),
(5016, '2 Chronicles', 14, 29, 32, ' وكان عدد المحرقات التي أتى بها الجماعة سبعين ثورا ومئة كبش ومئتي خروف . كل هذه محرقة للرب '),
(5017, '2 Chronicles', 14, 29, 33, ' والأقداس ست مئة من البقر وثلاثة آلاف من الضأن '),
(5018, '2 Chronicles', 14, 29, 34, ' إلا إن الكهنة كانوا قليلين فلم يقدروا أن يسلخوا كل المحرقات ، فساعدهم إخوتهم اللاويون حتى كمل العمل وحتى تقدس الكهنة . لأن اللاويين كانوا أكثر استقامة قلب من الكهنة في التقدس '),
(5019, '2 Chronicles', 14, 29, 35, ' وأيضا كانت المحرقات كثيرة بشحم ذبائح السلامة وسكائب المحرقات . فاستقامت خدمة بيت الرب '),
(5020, '2 Chronicles', 14, 29, 36, ' وفرح حزقيا وكل الشعب من أجل أن الله أعد الشعب ، لأن الأمر كان بغتة '),
(5021, '2 Chronicles', 14, 30, 1, ' وأرسل حزقيا إلى جميع إسرائيل ويهوذا ، وكتب أيضا رسائل إلى أفرايم ومنسى أن يأتوا إلى بيت الرب في أورشليم ليعملوا فصحا للرب إله إسرائيل '),
(5022, '2 Chronicles', 14, 30, 2, ' فتشاور الملك ورؤساؤه وكل الجماعة في أورشليم أن يعملوا الفصح في الشهر الثاني '),
(5023, '2 Chronicles', 14, 30, 3, ' لأنهم لم يقدروا أن يعملوه في ذلك الوقت ، لأن الكهنة لم يتقدسوا بالكفاية ، والشعب لم يجتمعوا إلى أورشليم '),
(5024, '2 Chronicles', 14, 30, 4, ' فحسن الأمر في عيني الملك وعيون كل الجماعة '),
(5025, '2 Chronicles', 14, 30, 5, ' فاعتمدوا على إطلاق النداء في جميع إسرائيل ، من بئر سبع إلى دان ، أن يأتوا لعمل الفصح للرب إله إسرائيل في أورشليم ، لأنهم لم يعملوه كما هو مكتوب منذ زمان كثير '),
(5026, '2 Chronicles', 14, 30, 6, ' فذهب السعاة بالرسائل من يد الملك ورؤسائه في جميع إسرائيل ويهوذا ، وحسب وصية الملك كانوا يقولون : يا بني إسرائيل ، ارجعوا إلى الرب إله إبراهيم وإسحاق وإسرائيل ، فيرجع إلى الناجين الباقين لكم من يد ملوك أشور '),
(5027, '2 Chronicles', 14, 30, 7, ' ولا تكونوا كآبائكم وكإخوتكم الذين خانوا الرب إله آبائهم ، فجعلهم دهشة كما أنتم ترون '),
(5028, '2 Chronicles', 14, 30, 8, ' الآن لا تصلبوا رقابكم كآبائكم ، بل اخضعوا للرب وادخلوا مقدسه الذي قدسه إلى الأبد ، واعبدوا الرب إلهكم فيرتد عنكم حمو غضبه ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(5029, '2 Chronicles', 14, 30, 9, ' لأنه برجوعكم إلى الرب يجد إخوتكم وبنوكم رحمة أمام الذين يسبونهم ، فيرجعون إلى هذه الأرض ، لأن الرب إلهكم حنان ورحيم ، ولا يحول وجهه عنكم إذا رجعتم إليه '),
(5030, '2 Chronicles', 14, 30, 10, ' فكان السعاة يعبرون من مدينة إلى مدينة في أرض أفرايم ومنسى حتى زبولون ، فكانوا يضحكون عليهم ويهزأون بهم '),
(5031, '2 Chronicles', 14, 30, 11, ' إلا إن قوما من أشير ومنسى وزبولون تواضعوا وأتوا إلى أورشليم '),
(5032, '2 Chronicles', 14, 30, 12, ' وكانت يد الله في يهوذا أيضا ، فأعطاهم قلبا واحدا ليعملوا بأمر الملك والرؤساء ، حسب قول الرب '),
(5033, '2 Chronicles', 14, 30, 13, ' فاجتمع إلى أورشليم شعب كثير لعمل عيد الفطير في الشهر الثاني ، جماعة كثيرة جدا '),
(5034, '2 Chronicles', 14, 30, 14, ' وقاموا وأزالوا المذابح التي في أورشليم ، وأزالوا كل مذابح التبخير وطرحوها إلى وادي قدرون '),
(5035, '2 Chronicles', 14, 30, 15, ' وذبحوا الفصح في الرابع عشر من الشهر الثاني . والكهنة واللاويون خجلوا وتقدسوا وأدخلوا المحرقات إلى بيت الرب '),
(5036, '2 Chronicles', 14, 30, 16, ' وأقاموا على مقامهم حسب حكمهم كناموس موسى رجل الله . كان الكهنة يرشون الدم من يد اللاويين '),
(5037, '2 Chronicles', 14, 30, 17, ' لأنه كان كثيرون في الجماعة لم يتقدسوا ، فكان اللاويون على ذبح الفصح عن كل من ليس بطاهر لتقديسهم للرب '),
(5038, '2 Chronicles', 14, 30, 18, ' لأن كثيرين من الشعب ، كثيرين من أفرايم ومنسى ويساكر وزبولون لم يتطهروا ، بل أكلوا الفصح ليس كما هو مكتوب . إلا إن حزقيا صلى عنهم قائلا : الرب الصالح يكفر عن '),
(5039, '2 Chronicles', 14, 30, 19, ' كل من هيأ قلبه لطلب الله الرب إله آبائه ، وليس كطهارة القدس '),
(5040, '2 Chronicles', 14, 30, 20, ' فسمع الرب لحزقيا وشفى الشعب '),
(5041, '2 Chronicles', 14, 30, 21, ' وعمل بنو إسرائيل الموجودون في أورشليم عيد الفطير سبعة أيام بفرح عظيم ، وكان اللاويون والكهنة يسبحون الرب يوما فيوما بآلات حمد للرب '),
(5042, '2 Chronicles', 14, 30, 22, ' وطيب حزقيا قلوب جميع اللاويين الفطنين فطنة صالحة للرب ، وأكلوا الموسم سبعة أيام ، يذبحون ذبائح سلامة ويحمدون الرب إله آبائهم '),
(5043, '2 Chronicles', 14, 30, 23, ' وتشاور كل الجماعة أن يعملوا سبعة أيام أخرى ، فعملوا سبعة أيام بفرح '),
(5044, '2 Chronicles', 14, 30, 24, ' لأن حزقيا ملك يهوذا قدم للجماعة ألف ثور وسبعة آلاف من الضأن ، والرؤساء قدموا للجماعة ألف ثور وعشرة آلاف من الضأن ، وتقدس كثيرون من الكهنة '),
(5045, '2 Chronicles', 14, 30, 25, ' وفرح كل جماعة يهوذا ، والكهنة واللاويون ، وكل الجماعة الآتين من إسرائيل ، والغرباء الآتون من أرض إسرائيل والساكنون في يهوذا '),
(5046, '2 Chronicles', 14, 30, 26, ' وكان فرح عظيم في أورشليم ، لأنه من أيام سليمان بن داود ملك إسرائيل لم يكن كهذا في أورشليم '),
(5047, '2 Chronicles', 14, 30, 27, ' وقام الكهنة اللاويون وباركوا الشعب ، فسمع صوتهم ودخلت صلاتهم إلى مسكن قدسه إلى السماء '),
(5048, '2 Chronicles', 14, 31, 1, ' ولما كمل هذا خرج كل إسرائيل الحاضرين إلى مدن يهوذا ، وكسروا الأنصاب وقطعوا السواري ، وهدموا المرتفعات والمذابح من كل يهوذا وبنيامين ومن أفرايم ومنسى حتى أفنوها ، ثم رجع كل إسرائيل كل واحد إلى ملكه ، إلى مدنهم '),
(5049, '2 Chronicles', 14, 36, 13, ' وتمرد أيضا على الملك نبوخذناصر الذي حلفه بالله ، وصلب عنقه وقوى قلبه عن الرجوع إلى الرب إله إسرائيل '),
(5050, '2 Chronicles', 14, 36, 14, ' حتى إن جميع رؤساء الكهنة والشعب أكثروا الخيانة حسب كل رجاسات الأمم ، ونجسوا بيت الرب الذي قدسه في أورشليم '),
(5051, '2 Chronicles', 14, 36, 15, ' فأرسل الرب إله آبائهم إليهم عن يد رسله مبكرا ومرسلا لأنه شفق على شعبه وعلى مسكنه '),
(5052, '2 Chronicles', 14, 36, 16, ' فكانوا يهزأون برسل الله ، ورذلوا كلامه وتهاونوا بأنبيائه حتى ثار غضب الرب على شعبه حتى لم يكن شفاء '),
(5053, '2 Chronicles', 14, 36, 17, ' فأصعد عليهم ملك الكلدانيين فقتل مختاريهم بالسيف في بيت مقدسهم . ولم يشفق على فتى أو عذراء ، ولا على شيخ أو أشيب ، بل دفع الجميع ليده '),
(5054, '2 Chronicles', 14, 36, 18, ' وجميع آنية بيت الله الكبيرة والصغيرة ، وخزائن بيت الرب وخزائن الملك ورؤسائه أتى بها جميعا إلى بابل '),
(5055, '2 Chronicles', 14, 36, 19, ' وأحرقوا بيت الله ، وهدموا سور أورشليم وأحرقوا جميع قصورها بالنار ، وأهلكوا جميع آنيتها الثمينة '),
(5056, '2 Chronicles', 14, 36, 20, ' وسبى الذين بقوا من السيف إلى بابل ، فكانوا له ولبنيه عبيدا إلى أن ملكت مملكة فارس '),
(5057, '2 Chronicles', 14, 36, 21, ' لإكمال كلام الرب بفم إرميا ، حتى استوفت الأرض سبوتها ، لأنها سبتت في كل أيام خرابها لإكمال سبعين سنة '),
(5058, '2 Chronicles', 14, 36, 22, ' وفي السنة الأولى لكورش ملك فارس لأجل تكميل كلام الرب بفم إرميا ، نبه الرب روح كورش ملك فارس ، فأطلق نداء في كل مملكته وكذا بالكتابة قائلا '),
(5059, '2 Chronicles', 14, 36, 23, ' هكذا قال كورش ملك فارس : إن الرب إله السماء قد أعطاني جميع ممالك الأرض ، وهو أوصاني أن أبني له بيتا في أورشليم التي في يهوذا . من منكم من جميع شعبه ، الرب إلهه معه وليصعد '),
(5060, '2 Chronicles', 14, 33, 23, ' ولم يتواضع أمام الرب كما تواضع منسى أبوه ، بل ازداد آمون إثما '),
(5061, '2 Chronicles', 14, 33, 24, ' وفتن عليه عبيده وقتلوه في بيته '),
(5062, '2 Chronicles', 14, 33, 25, ' وقتل شعب الأرض جميع الفاتنين على الملك آمون ، وملك شعب الأرض يوشيا ابنه عوضا عنه '),
(5063, '2 Chronicles', 14, 34, 1, ' كان يوشيا ابن ثماني سنين حين ملك ، وملك إحدى وثلاثين سنة في أورشليم '),
(5064, '2 Chronicles', 14, 34, 2, ' وعمل المستقيم في عيني الرب ، وسار في طرق داود أبيه ، ولم يحد يمينا ولا شمالا '),
(5065, '2 Chronicles', 14, 34, 3, ' وفي السنة الثامنة من ملكه إذ كان بعد فتى ، ابتدأ يطلب إله داود أبيه . وفي السنة الثانية عشرة ابتدأ يطهر يهوذا وأورشليم من المرتفعات والسواري والتماثيل والمسبوكات '),
(5066, '2 Chronicles', 14, 34, 4, ' وهدموا أمامه مذابح البعليم ، وتماثيل الشمس التي عليها من فوق قطعها ، وكسر السواري والتماثيل والمسبوكات ودقها ورشها على قبور الذين ذبحوا لها '),
(5067, '2 Chronicles', 14, 34, 5, ' وأحرق عظام الكهنة على مذابحهم وطهر يهوذا وأورشليم '),
(5068, '2 Chronicles', 14, 34, 6, ' وفي مدن منسى وأفرايم وشمعون حتى ونفتالي مع خرائبها حولها '),
(5069, '2 Chronicles', 14, 34, 7, ' هدم المذابح والسواري ودق التماثيل ناعما ، وقطع جميع تماثيل الشمس في كل أرض إسرائيل ، ثم رجع إلى أورشليم '),
(5070, '2 Chronicles', 14, 34, 8, ' وفي السنة الثامنة عشرة من ملكه بعد أن طهر الأرض والبيت ، أرسل شافان بن أصليا ومعسيا رئيس المدينة ويوآخ بن يوآحاز المسجل لأجل ترميم بيت الرب إلهه '),
(5071, '2 Chronicles', 14, 34, 9, ' فجاءوا إلى حلقيا الكاهن العظيم ، وأعطوه الفضة المدخلة إلى بيت الله التي جمعها اللاويون حارسو الباب من منسى وأفرايم ومن كل بقية إسرائيل ومن كل يهوذا وبنيامين ، ثم رجعوا إلى أورشليم '),
(5072, '2 Chronicles', 14, 34, 10, ' ودفعوها لأيدي عاملي الشغل الموكلين في بيت الرب ، فدفعوها لعاملي الشغل الذين كانوا يعملون في بيت الرب لأجل إصلاح البيت وترميمه '),
(5073, '2 Chronicles', 14, 34, 11, ' وأعطوها للنجارين والبنائين ليشتروا حجارة منحوتة وأخشابا للوصل ولأجل تسقيف البيوت التي أخربها ملوك يهوذا '),
(5074, '2 Chronicles', 14, 34, 12, ' وكان الرجال يعملون العمل بأمانة ، وعليهم وكلاء يحث وعوبديا اللاويان من بني مراري ، وزكريا ومشلام من بني القهاتيين لأجل المناظرة ، ومن اللاويين كل ماهر بآلات الغناء '),
(5075, '2 Chronicles', 14, 34, 13, ' وكانوا على الحمال ووكلاء على كل عامل شغل في خدمة فخدمة . وكان من اللاويين كتاب وعرفاء وبوابون '),
(5076, '2 Chronicles', 14, 34, 14, ' وعند إخراجهم الفضة المدخلة إلى بيت الرب ، وجد حلقيا الكاهن سفر شريعة الرب بيد موسى '),
(5077, '2 Chronicles', 14, 34, 15, ' فأجاب حلقيا وقال لشافان الكاتب : قد وجدت سفر الشريعة في بيت الرب . وسلم حلقيا السفر إلى شافان '),
(5078, '2 Chronicles', 14, 34, 16, ' فجاء شافان بالسفر إلى الملك ورد إلى الملك جوابا قائلا : كل ما أسلم ليد عبيدك هم يفعلونه '),
(5079, '2 Chronicles', 14, 34, 17, ' وقد أفرغوا الفضة الموجودة في بيت الرب ودفعوها ليد الوكلاء ويد عاملي الشغل '),
(5080, '2 Chronicles', 14, 34, 18, ' وأخبر شافان الكاتب الملك قائلا : قد أعطاني حلقيا الكاهن سفرا . وقرأ فيه شافان أمام الملك '),
(5081, '2 Chronicles', 14, 34, 19, ' فلما سمع الملك كلام الشريعة مزق ثيابه '),
(5082, '2 Chronicles', 14, 34, 20, ' وأمر الملك حلقيا وأخيقام بن شافان وعبدون بن ميخا وشافان الكاتب وعسايا عبد الملك قائلا '),
(5083, '2 Chronicles', 14, 34, 21, ' اذهبوا اسألوا الرب من أجلي ومن أجل من بقي من إسرائيل ويهوذا عن كلام السفر الذي وجد ، لأنه عظيم غضب الرب الذي انسكب علينا من أجل أن آباءنا لم يحفظوا كلام الرب ليعملوا حسب كل ما هو مكتوب في هذا السفر '),
(5084, '2 Chronicles', 14, 34, 22, ' فذهب حلقيا والذين أمرهم الملك إلى خلدة النبية امرأة شلوم بن توقهة بن حسرة حارس الثياب ، وهي ساكنة في أورشليم في القسم الثاني ، وكلموها هكذا '),
(5085, '2 Chronicles', 14, 34, 23, ' فقالت لهم : هكذا قال الرب إله إسرائيل : قولوا للرجل الذي أرسلكم إلي '),
(5086, '2 Chronicles', 14, 34, 24, ' هكذا قال الرب : هأنذا جالب شرا على هذا الموضع وعلى سكانه ، جميع اللعنات المكتوبة في السفر الذي قراءه أمام ملك يهوذا '),
(5087, '2 Chronicles', 14, 34, 25, ' من أجل أنهم تركوني وأوقدوا لآلهة أخرى لكي يغيظوني بكل أعمال أيديهم ، وينسكب غضبي على هذا الموضع ولا ينطفئ '),
(5088, '2 Chronicles', 14, 34, 26, ' وأما ملك يهوذا الذي أرسلكم لتسألوا من الرب ، فهكذا تقولون له : هكذا قال الرب إله إسرائيل من جهة الكلام الذي سمعت '),
(5089, '2 Chronicles', 14, 34, 27, ' من أجل أنه قد رق قلبك ، وتواضعت أمام الله حين سمعت كلامه على هذا الموضع وعلى سكانه ، وتواضعت أمامي ومزقت ثيابك وبكيت أمامي يقول الرب ، قد سمعت أنا أيضا '),
(5090, '2 Chronicles', 14, 34, 28, ' هأنذا أضمك إلى آبائك فتضم إلى قبرك بسلام ، وكل الشر الذي أجلبه على هذا الموضع وعلى سكانه لا ترى عيناك . فردوا على الملك الجواب '),
(5091, '2 Chronicles', 14, 34, 29, ' وأرسل الملك وجمع كل شيوخ يهوذا وأورشليم '),
(5092, '2 Chronicles', 14, 34, 30, ' وصعد الملك إلى بيت الرب مع كل رجال يهوذا وسكان أورشليم والكهنة واللاويين وكل الشعب من الكبير إلى الصغير ، وقرأ في آذانهم كل كلام سفر العهد الذي وجد في بيت الرب '),
(5093, '2 Chronicles', 14, 34, 31, ' ووقف الملك على منبره وقطع عهدا أمام الرب للذهاب وراء الرب ولحفظ وصاياه وشهاداته وفرائضه بكل قلبه وكل نفسه ، ليعمل كلام العهد المكتوب في هذا السفر '),
(5094, '2 Chronicles', 14, 34, 32, ' وأوقف كل الموجودين في أورشليم وبنيامين ، فعمل سكان أورشليم حسب عهد الله إله آبائهم '),
(5095, '2 Chronicles', 14, 34, 33, ' وأزال يوشيا جميع الرجاسات من كل الأراضي التي لبني إسرائيل ، وجعل جميع الموجودين في أورشليم يعبدون الرب إلههم . كل أيامه لم يحيدوا من وراء الرب إله آبائهم '),
(5096, '2 Chronicles', 14, 35, 1, ' وعمل يوشيا في أورشليم فصحا للرب ، وذبحوا الفصح في الرابع عشر من الشهر الأول '),
(5097, '2 Chronicles', 14, 35, 2, ' وأقام الكهنة على حراساتهم وشددهم لخدمة بيت الرب '),
(5098, '2 Chronicles', 14, 35, 3, ' وقال للاويين الذين كانوا يعلمون كل إسرائيل ، الذين كانوا مقدسين للرب : اجعلوا تابوت القدس في البيت الذي بناه سليمان بن داود ملك إسرائيل . ليس لكم أن تحملوا على الأكتاف . الآن اخدموا الرب إلهكم وشعبه إسرائيل '),
(5099, '2 Chronicles', 14, 35, 4, ' وأعدوا بيوت آبائكم حسب فرقكم ، حسب كتابة داود ملك إسرائيل ، وحسب كتابة سليمان ابنه '),
(5100, '2 Chronicles', 14, 35, 5, ' وقفوا في القدس حسب أقسام بيوت آباء إخوتكم بني الشعب وفرق بيوت آباء اللاويين '),
(5101, '2 Chronicles', 14, 35, 6, ' واذبحوا الفصح وتقدسوا وأعدوا إخوتكم ليعملوا حسب كلام الرب عن يد موسى '),
(5102, '2 Chronicles', 14, 35, 7, ' وأعطى يوشيا لبني الشعب غنما : حملانا وجداء ، جميع ذلك للفصح لكل الموجودين إلى عدد ثلاثين ألفا وثلاثة آلاف من البقر . هذه من مال الملك '),
(5103, '2 Chronicles', 14, 35, 8, ' ورؤساؤه قدموا تبرعا للشعب والكهنة واللاويين حلقيا وزكريا ويحيئيل رؤساء بيت الله . أعطوا الكهنة للفصح ألفين وست مئة ، ومن البقر ثلاث مئة '),
(5104, '2 Chronicles', 14, 35, 9, ' وكوننيا وشمعيا ونثنئيل أخواه وحشبيا ويعيئيل ويوزاباد رؤساء اللاويين قدموا للاويين للفصح خمسة آلاف ، ومن البقر خمس مئة '),
(5105, '2 Chronicles', 14, 35, 10, ' فتهيأت الخدمة ، وقام الكهنة في مقامهم واللاويون في فرقهم حسب أمر الملك '),
(5106, '2 Chronicles', 14, 35, 11, ' وذبحوا الفصح . ورش الكهنة من أيديهم ، وأما اللاويون فكانوا يسلخون '),
(5107, '2 Chronicles', 14, 35, 12, ' ورفعوا المحرقة ليعطوا حسب أقسام بيوت الآباء لبني الشعب ، ليقربوا للرب كما هو مكتوب في سفر موسى . وهكذا بالبقر '),
(5108, '2 Chronicles', 14, 35, 13, ' وشووا الفصح بالنار كالمرسوم . وأما الأقداس فطبخوها في القدور والمراجل والصحاف ، وبادروا بها إلى جميع بني الشعب '),
(5109, '2 Chronicles', 14, 35, 14, ' وبعد أعدوا لأنفسهم وللكهنة ، لأن الكهنة بني هارون كانوا على إصعاد المحرقة والشحم إلى الليل . فأعد اللاويون لأنفسهم وللكهنة بني هارون '),
(5110, '2 Chronicles', 14, 35, 15, ' والمغنون بنو آساف كانوا في مقامهم حسب أمر داود وآساف وهيمان ويدوثون رائي الملك . والبوابون على باب فباب لم يكن لهم أن يحيدوا عن خدمتهم ، لأن إخوتهم اللاويين أعدوا لهم '),
(5111, '2 Chronicles', 14, 35, 16, ' فتهيأ كل خدمة الرب في ذلك اليوم لعمل الفصح وإصعاد المحرقات على مذبح الرب ، حسب أمر الملك يوشيا '),
(5112, '2 Chronicles', 14, 35, 17, ' وعمل بنو إسرائيل الموجودون الفصح في ذلك الوقت ، وعيد الفطير سبعة أيام '),
(5113, '2 Chronicles', 14, 35, 18, ' ولم يعمل فصح مثله في إسرائيل من أيام صموئيل النبي . وكل ملوك إسرائيل لم يعملوا كالفصح الذي عمله يوشيا والكهنة واللاويون وكل يهوذا وإسرائيل الموجودين وسكان أورشليم '),
(5114, '2 Chronicles', 14, 35, 19, ' في السنة الثامنة عشرة لملك يوشيا عمل هذا الفصح '),
(5115, '2 Chronicles', 14, 35, 20, ' بعد كل هذا حين هيأ يوشيا البيت ، صعد نخو ملك مصر إلى كركميش ليحارب عند الفرات . فخرج يوشيا للقائه '),
(5116, '2 Chronicles', 14, 35, 21, ' فأرسل إليه رسلا يقول : ما لي ولك ياملك يهوذا لست عليك أنت اليوم ، ولكن على بيت حربي ، والله أمر بإسراعي . فكف عن الله الذي معي فلا يهلكك '),
(5117, '2 Chronicles', 14, 35, 22, ' ولم يحول يوشيا وجهه عنه بل تنكر لمقاتلته ، ولم يسمع لكلام نخو من فم الله ، بل جاء ليحارب في بقعة مجدو '),
(5118, '2 Chronicles', 14, 35, 23, ' وأصاب الرماة الملك يوشيا ، فقال الملك لعبيده : انقلوني لأني جرحت جدا '),
(5119, '2 Chronicles', 14, 35, 24, ' فنقله عبيده من المركبة وأركبوه على المركبة الثانية التي له ، وساروا به إلى أورشليم فمات ودفن في قبور آبائه . وكان كل يهوذا وأورشليم ينوحون على يوشيا '),
(5120, '2 Chronicles', 14, 35, 25, ' ورثى إرميا يوشيا . وكان جميع المغنين والمغنيات يندبون يوشيا في مراثيهم إلى اليوم ، وجعلوها فريضة على إسرائيل ، وها هي مكتوبة في المراثي '),
(5121, '2 Chronicles', 14, 35, 26, ' وبقية أمور يوشيا ومراحمه حسبما هو مكتوب في ناموس الرب '),
(5122, '2 Chronicles', 14, 35, 27, ' وأموره الأولى والأخيرة ، ها هي مكتوبة في سفر ملوك إسرائيل ويهوذا '),
(5123, '2 Chronicles', 14, 36, 1, ' وأخذ شعب الأرض يهوآحاز بن يوشيا وملكوه عوضا عن أبيه في أورشليم '),
(5124, '2 Chronicles', 14, 36, 2, ' كان يوآحاز ابن ثلاث وعشرين سنة حين ملك ، وملك ثلاثة أشهر في أورشليم '),
(5125, '2 Chronicles', 14, 36, 3, ' وعزله ملك مصر في أورشليم وغرم الأرض بمئة وزنة من الفضة ، وبوزنة من الذهب '),
(5126, '2 Chronicles', 14, 36, 4, ' وملك ملك مصر ألياقيم أخاه على يهوذا وأورشليم ، وغير اسمه إلى يهوياقيم . وأما يوآحاز أخوه فأخذه نخو وأتى به إلى مصر '),
(5127, '2 Chronicles', 14, 36, 5, ' كان يهوياقيم ابن خمس وعشرين سنة حين ملك ، وملك إحدى عشرة سنة في أورشليم ، وعمل الشر في عيني الرب إلهه '),
(5128, '2 Chronicles', 14, 36, 6, ' عليه صعد نبوخذناصر ملك بابل وقيده بسلاسل نحاس ليذهب به إلى بابل '),
(5129, '2 Chronicles', 14, 36, 7, ' وأتى نبوخذناصر ببعض آنية بيت الرب إلى بابل وجعلها في هيكله في بابل '),
(5130, '2 Chronicles', 14, 36, 8, ' وبقية أمور يهوياقيم ورجاساته التي عمل وما وجد فيه ، ها هي مكتوبة في سفر ملوك إسرائيل ويهوذا . وملك يهوياكين ابنه عوضا عنه '),
(5131, '2 Chronicles', 14, 36, 9, ' كان يهوياكين ابن ثماني سنين حين ملك ، وملك ثلاثة أشهر وعشرة أيام في أورشليم . وعمل الشر في عيني الرب '),
(5132, '2 Chronicles', 14, 36, 10, ' وعند رجوع السنة أرسل الملك نبوخذناصر فأتى به إلى بابل مع آنية بيت الرب الثمينة ، وملك صدقيا أخاه على يهوذا وأورشليم '),
(5133, '2 Chronicles', 14, 36, 11, ' كان صدقيا ابن إحدى وعشرين سنة حين ملك ، وملك إحدى عشرة سنة في أورشليم '),
(5134, '2 Chronicles', 14, 36, 12, ' وعمل الشر في عيني الرب إلهه ، ولم يتواضع أمام إرميا النبي من فم الرب '),
(5135, '2 Corinthians', 47, 1, 1, ' بولس ، رسول يسوع المسيح بمشيئة الله ، وتيموثاوس الأخ ، إلى كنيسة الله التي في كورنثوس ، مع القديسين أجمعين الذين في جميع أخائية '),
(5136, '2 Corinthians', 47, 1, 2, ' نعمة لكم وسلام من الله أبينا والرب يسوع المسيح '),
(5137, '2 Corinthians', 47, 1, 3, ' مبارك الله أبو ربنا يسوع المسيح ، أبو الرأفة وإله كل تعزية '),
(5138, '2 Corinthians', 47, 1, 4, ' الذي يعزينا في كل ضيقتنا ، حتى نستطيع أن نعزي الذين هم في كل ضيقة بالتعزية التي نتعزى نحن بها من الله '),
(5139, '2 Corinthians', 47, 1, 5, ' لأنه كما تكثر آلام المسيح فينا ، كذلك بالمسيح تكثر تعزيتنا أيضا '),
(5140, '2 Corinthians', 47, 1, 6, ' فإن كنا نتضايق فلأجل تعزيتكم وخلاصكم ، العامل في احتمال نفس الآلام التي نتألم بها نحن أيضا . أو نتعزى فلأجل تعزيتكم وخلاصكم '),
(5141, '2 Corinthians', 47, 1, 7, ' فرجاؤنا من أجلكم ثابت . عالمين أنكم كما أنتم شركاء في الآلام ، كذلك في التعزية أيضا '),
(5142, '2 Corinthians', 47, 1, 8, ' فإننا لا نريد أن تجهلوا أيها الإخوة من جهة ضيقتنا التي أصابتنا في أسيا ، أننا تثقلنا جدا فوق الطاقة ، حتى أيسنا من الحياة أيضا '),
(5143, '2 Corinthians', 47, 1, 9, ' لكن كان لنا في أنفسنا حكم الموت ، لكي لا نكون متكلين على أنفسنا بل على الله الذي يقيم الأموات '),
(5144, '2 Corinthians', 47, 1, 10, ' الذي نجانا من موت مثل هذا ، وهو ينجي . الذي لنا رجاء فيه أنه سينجي أيضا فيما بعد '),
(5145, '2 Corinthians', 47, 1, 11, ' وأنتم أيضا مساعدون بالصلاة لأجلنا ، لكي يؤدى شكر لأجلنا من أشخاص كثيرين ، على ما وهب لنا بواسطة كثيرين '),
(5146, '2 Corinthians', 47, 1, 12, ' لأن فخرنا هو هذا : شهادة ضميرنا أننا في بساطة وإخلاص الله ، لا في حكمة جسدية بل في نعمة الله ، تصرفنا في العالم ، ولاسيما من نحوكم '),
(5147, '2 Corinthians', 47, 1, 13, ' فإننا لا نكتب إليكم بشيء آخر سوى ما تقرأون أو تعرفون . وأنا أرجو أنكم ستعرفون إلى النهاية أيضا '),
(5148, '2 Corinthians', 47, 1, 14, ' كما عرفتمونا أيضا بعض المعرفة أننا فخركم ، كما أنكم أيضا فخرنا في يوم الرب يسوع '),
(5149, '2 Corinthians', 47, 1, 15, ' وبهذه الثقة كنت أشاء أن آتي إليكم أولا ، لتكون لكم نعمة ثانية '),
(5150, '2 Corinthians', 47, 1, 16, ' وأن أمر بكم إلى مكدونية ، وآتي أيضا من مكدونية إليكم ، وأشيع منكم إلى اليهودية '),
(5151, '2 Corinthians', 47, 1, 17, ' فإذ أنا عازم على هذا ، ألعلي استعملت الخفة ؟ أم أعزم على ما أعزم بحسب الجسد ، كي يكون عندي نعم نعم ولا لا '),
(5152, '2 Corinthians', 47, 1, 18, ' لكن أمين هو الله إن كلامنا لكم لم يكن نعم ولا '),
(5153, '2 Corinthians', 47, 1, 19, ' لأن ابن الله يسوع المسيح ، الذي كرز به بينكم بواسطتنا ، أنا وسلوانس وتيموثاوس ، لم يكن نعم ولا ، بل قد كان فيه نعم '),
(5154, '2 Corinthians', 47, 1, 20, ' لأن مهما كانت مواعيد الله فهو فيه النعم وفيه الآمين ، لمجد الله ، بواسطتنا '),
(5155, '2 Corinthians', 47, 1, 21, ' ولكن الذي يثبتنا معكم في المسيح ، وقد مسحنا ، هو الله '),
(5156, '2 Corinthians', 47, 1, 22, ' الذي ختمنا أيضا ، وأعطى عربون الروح في قلوبنا '),
(5157, '2 Corinthians', 47, 1, 23, ' ولكني أستشهد الله على نفسي ، أني إشفاقا عليكم لم آت إلى كورنثوس '),
(5158, '2 Corinthians', 47, 1, 24, ' ليس أننا نسود على إيمانكم ، بل نحن موازرون لسروركم . لأنكم بالإيمان تثبتون '),
(5159, '2 Corinthians', 47, 2, 1, ' ولكني جزمت بهذا في نفسي أن لا آتي إليكم أيضا في حزن '),
(5160, '2 Corinthians', 47, 2, 2, ' لأنه إن كنت أحزنكم أنا ، فمن هو الذي يفرحني إلا الذي أحزنته '),
(5161, '2 Corinthians', 47, 2, 3, ' وكتبت لكم هذا عينه حتى إذا جئت لا يكون لي حزن من الذين كان يجب أن أفرح بهم ، واثقا بجميعكم أن فرحي هو فرح جميعكم '),
(5162, '2 Corinthians', 47, 2, 4, ' لأني من حزن كثير وكآبة قلب كتبت إليكم بدموع كثيرة ، لا لكي تحزنوا ، بل لكي تعرفوا المحبة التي عندي ، ولاسيما من نحوكم '),
(5163, '2 Corinthians', 47, 2, 5, ' ولكن إن كان أحد قد أحزن ، فإنه لم يحزني ، بل أحزن جميعكم بعض الحزن لكي لا أثقل '),
(5164, '2 Corinthians', 47, 2, 6, ' مثل هذا يكفيه هذا القصاص الذي من الأكثرين '),
(5165, '2 Corinthians', 47, 2, 7, ' حتى تكونوا - بالعكس - تسامحونه بالحري وتعزونه ، لئلا يبتلع مثل هذا من الحزن المفرط '),
(5166, '2 Corinthians', 47, 2, 8, ' لذلك أطلب أن تمكنوا له المحبة '),
(5167, '2 Corinthians', 47, 2, 9, ' لأني لهذا كتبت لكي أعرف تزكيتكم ، هل أنتم طائعون في كل شيء '),
(5168, '2 Corinthians', 47, 2, 10, ' والذي تسامحونه بشيء فأنا أيضا . لأني أنا ما سامحت به - إن كنت قد سامحت بشيء - فمن أجلكم بحضرة المسيح '),
(5169, '2 Corinthians', 47, 2, 11, ' لئلا يطمع فينا الشيطان ، لأننا لا نجهل أفكاره '),
(5170, '2 Corinthians', 47, 2, 12, ' ولكن لما جئت إلى ترواس ، لأجل إنجيل المسيح ، وانفتح لي باب في الرب '),
(5171, '2 Corinthians', 47, 2, 13, ' لم تكن لي راحة في روحي ، لأني لم أجد تيطس أخي . لكن ودعتهم فخرجت إلى مكدونية '),
(5172, '2 Corinthians', 47, 2, 14, ' ولكن شكرا لله الذي يقودنا في موكب نصرته في المسيح كل حين ، ويظهر بنا رائحة معرفته في كل مكان '),
(5173, '2 Corinthians', 47, 2, 15, ' لأننا رائحة المسيح الذكية لله ، في الذين يخلصون وفي الذين يهلكون '),
(5174, '2 Corinthians', 47, 2, 16, ' لهؤلاء رائحة موت لموت ، ولأولئك رائحة حياة لحياة . ومن هو كفوء لهذه الأمور '),
(5175, '2 Corinthians', 47, 2, 17, ' لأننا لسنا كالكثيرين غاشين كلمة الله ، لكن كما من إخلاص ، بل كما من الله نتكلم أمام الله في المسيح '),
(5176, '2 Corinthians', 47, 3, 1, ' أفنبتدئ نمدح أنفسنا ؟ أم لعلنا نحتاج كقوم رسائل توصية إليكم ، أو رسائل توصية منكم '),
(5177, '2 Corinthians', 47, 3, 2, ' أنتم رسالتنا ، مكتوبة في قلوبنا ، معروفة ومقروءة من جميع الناس '),
(5178, '2 Corinthians', 47, 3, 3, ' ظاهرين أنكم رسالة المسيح ، مخدومة منا ، مكتوبة لا بحبر بل بروح الله الحي ، لا في ألواح حجرية بل في ألواح قلب لحمية '),
(5179, '2 Corinthians', 47, 3, 4, ' ولكن لنا ثقة مثل هذه بالمسيح لدى الله '),
(5180, '2 Corinthians', 47, 3, 5, ' ليس أننا كفاة من أنفسنا أن نفتكر شيئا كأنه من أنفسنا ، بل كفايتنا من الله '),
(5181, '2 Corinthians', 47, 3, 6, ' الذي جعلنا كفاة لأن نكون خدام عهد جديد . لا الحرف بل الروح . لأن الحرف يقتل ولكن الروح يحيي '),
(5182, '2 Corinthians', 47, 3, 7, ' ثم إن كانت خدمة الموت ، المنقوشة بأحرف في حجارة ، قد حصلت في مجد ، حتى لم يقدر بنو إسرائيل أن ينظروا إلى وجه موسى لسبب مجد وجهه الزائل '),
(5183, '2 Corinthians', 47, 3, 8, ' فكيف لا تكون بالأولى خدمة الروح في مجد '),
(5184, '2 Corinthians', 47, 3, 9, ' لأنه إن كانت خدمة الدينونة مجدا ، فبالأولى كثيرا تزيد خدمة البر في مجد '),
(5185, '2 Corinthians', 47, 3, 10, ' فإن الممجد أيضا لم يمجد من هذا القبيل لسبب المجد الفائق '),
(5186, '2 Corinthians', 47, 3, 11, ' لأنه إن كان الزائل في مجد ، فبالأولى كثيرا يكون الدائم في مجد '),
(5187, '2 Corinthians', 47, 3, 12, ' فإذ لنا رجاء مثل هذا نستعمل مجاهرة كثيرة '),
(5188, '2 Corinthians', 47, 3, 13, ' وليس كما كان موسى يضع برقعا على وجهه لكي لا ينظر بنو إسرائيل إلى نهاية الزائل '),
(5189, '2 Corinthians', 47, 3, 14, ' بل أغلظت أذهانهم ، لأنه حتى اليوم ذلك البرقع نفسه عند قراءة العهد العتيق باق غير منكشف ، الذي يبطل في المسيح '),
(5190, '2 Corinthians', 47, 3, 15, ' لكن حتى اليوم ، حين يقرأ موسى ، البرقع موضوع على قلبهم '),
(5191, '2 Corinthians', 47, 3, 16, ' ولكن عندما يرجع إلى الرب يرفع البرقع '),
(5192, '2 Corinthians', 47, 3, 17, ' وأما الرب فهو الروح ، وحيث روح الرب هناك حرية '),
(5193, '2 Corinthians', 47, 3, 18, ' ونحن جميعا ناظرين مجد الرب بوجه مكشوف ، كما في مرآة ، نتغير إلى تلك الصورة عينها ، من مجد إلى مجد ، كما من الرب الروح '),
(5194, '2 Corinthians', 47, 4, 1, ' من أجل ذلك ، إذ لنا هذه الخدمة - كما رحمنا - لا نفشل '),
(5195, '2 Corinthians', 47, 4, 2, ' بل قد رفضنا خفايا الخزي ، غير سالكين في مكر ، ولا غاشين كلمة الله ، بل بإظهار الحق ، مادحين أنفسنا لدى ضمير كل إنسان قدام الله '),
(5196, '2 Corinthians', 47, 4, 3, ' ولكن إن كان إنجيلنا مكتوما ، فإنما هو مكتوم في الهالكين '),
(5197, '2 Corinthians', 47, 4, 4, ' الذين فيهم إله هذا الدهر قد أعمى أذهان غير المؤمنين ، لئلا تضيء لهم إنارة إنجيل مجد المسيح ، الذي هو صورة الله '),
(5198, '2 Corinthians', 47, 4, 5, ' فإننا لسنا نكرز بأنفسنا ، بل بالمسيح يسوع ربا ، ولكن بأنفسنا عبيدا لكم من أجل يسوع '),
(5199, '2 Corinthians', 47, 4, 6, ' لأن الله الذي قال : أن يشرق نور من ظلمة ، هو الذي أشرق في قلوبنا ، لإنارة معرفة مجد الله في وجه يسوع المسيح '),
(5200, '2 Corinthians', 47, 4, 7, ' ولكن لنا هذا الكنز في أوان خزفية ، ليكون فضل القوة لله لا منا '),
(5201, '2 Corinthians', 47, 4, 8, ' مكتئبين في كل شيء ، لكن غير متضايقين . متحيرين ، لكن غير يائسين '),
(5202, '2 Corinthians', 47, 4, 9, ' مضطهدين ، لكن غير متروكين . مطروحين ، لكن غير هالكين '),
(5203, '2 Corinthians', 47, 4, 10, ' حاملين في الجسد كل حين إماتة الرب يسوع ، لكي تظهر حياة يسوع أيضا في جسدنا '),
(5204, '2 Corinthians', 47, 4, 11, ' لأننا نحن الأحياء نسلم دائما للموت من أجل يسوع ، لكي تظهر حياة يسوع أيضا في جسدنا المائت '),
(5205, '2 Corinthians', 47, 4, 12, ' إذا الموت يعمل فينا ، ولكن الحياة فيكم '),
(5206, '2 Corinthians', 47, 4, 13, ' فإذ لنا روح الإيمان عينه ، حسب المكتوب : آمنت لذلك تكلمت ، نحن أيضا نؤمن ولذلك نتكلم أيضا '),
(5207, '2 Corinthians', 47, 4, 14, ' عالمين أن الذي أقام الرب يسوع سيقيمنا نحن أيضا بيسوع ، ويحضرنا معكم '),
(5208, '2 Corinthians', 47, 4, 15, ' لأن جميع الأشياء هي من أجلكم ، لكي تكون النعمة وهي قد كثرت بالأكثرين ، تزيد الشكر لمجد الله '),
(5209, '2 Corinthians', 47, 4, 16, ' لذلك لا نفشل ، بل وإن كان إنساننا الخارج يفنى ، فالداخل يتجدد يوما فيوما '),
(5210, '2 Corinthians', 47, 4, 17, ' لأن خفة ضيقتنا الوقتية تنشئ لنا أكثر فأكثر ثقل مجد أبديا '),
(5211, '2 Corinthians', 47, 4, 18, ' ونحن غير ناظرين إلى الأشياء التي ترى ، بل إلى التي لا ترى . لأن التي ترى وقتية ، وأما التي لا ترى فأبدية '),
(5212, '2 Corinthians', 47, 5, 1, ' لأننا نعلم أنه إن نقض بيت خيمتنا الأرضي ، فلنا في السماوات بناء من الله ، بيت غير مصنوع بيد ، أبدي '),
(5213, '2 Corinthians', 47, 5, 2, ' فإننا في هذه أيضا نئن مشتاقين إلى أن نلبس فوقها مسكننا الذي من السماء '),
(5214, '2 Corinthians', 47, 5, 3, ' وإن كنا لابسين لا نوجد عراة '),
(5215, '2 Corinthians', 47, 5, 4, ' فإننا نحن الذين في الخيمة نئن مثقلين ، إذ لسنا نريد أن نخلعها بل أن نلبس فوقها ، لكي يبتلع المائت من الحياة '),
(5216, '2 Corinthians', 47, 5, 5, ' ولكن الذي صنعنا لهذا عينه هو الله ، الذي أعطانا أيضا عربون الروح '),
(5217, '2 Corinthians', 47, 5, 6, ' فإذا نحن واثقون كل حين وعالمون أننا ونحن مستوطنون في الجسد ، فنحن متغربون عن الرب '),
(5218, '2 Corinthians', 47, 5, 7, ' لأننا بالإيمان نسلك لا بالعيان '),
(5219, '2 Corinthians', 47, 5, 8, ' فنثق ونسر بالأولى أن نتغرب عن الجسد ونستوطن عند الرب '),
(5220, '2 Corinthians', 47, 5, 9, ' لذلك نحترص أيضا - مستوطنين كنا أو متغربين - أن نكون مرضيين عنده '),
(5221, '2 Corinthians', 47, 5, 10, ' لأنه لابد أننا جميعا نظهر أمام كرسي المسيح ، لينال كل واحد ما كان بالجسد بحسب ما صنع ، خيرا كان أم شرا '),
(5222, '2 Corinthians', 47, 5, 11, ' فإذ نحن عالمون مخافة الرب نقنع الناس . وأما الله فقد صرنا ظاهرين له ، وأرجو أننا قد صرنا ظاهرين في ضمائركم أيضا '),
(5223, '2 Corinthians', 47, 5, 12, ' لأننا لسنا نمدح أنفسنا أيضا لديكم ، بل نعطيكم فرصة للافتخار من جهتنا ، ليكون لكم جواب على الذين يفتخرون بالوجه لا بالقلب '),
(5224, '2 Corinthians', 47, 5, 13, ' لأننا إن صرنا مختلين فلله ، أو كنا عاقلين فلكم '),
(5225, '2 Corinthians', 47, 5, 14, ' لأن محبة المسيح تحصرنا . إذ نحن نحسب هذا : أنه إن كان واحد قد مات لأجل الجميع ، فالجميع إذا ماتوا '),
(5226, '2 Corinthians', 47, 5, 15, ' وهو مات لأجل الجميع كي يعيش الأحياء فيما بعد لا لأنفسهم ، بل للذي مات لأجلهم وقام '),
(5227, '2 Corinthians', 47, 5, 16, ' إذا نحن من الآن لا نعرف أحدا حسب الجسد . وإن كنا قد عرفنا المسيح حسب الجسد ، لكن الآن لا نعرفه بعد '),
(5228, '2 Corinthians', 47, 5, 17, ' إذا إن كان أحد في المسيح فهو خليقة جديدة : الأشياء العتيقة قد مضت ، هوذا الكل قد صار جديدا '),
(5229, '2 Corinthians', 47, 5, 18, ' ولكن الكل من الله ، الذي صالحنا لنفسه بيسوع المسيح ، وأعطانا خدمة المصالحة '),
(5230, '2 Corinthians', 47, 5, 19, ' أي إن الله كان في المسيح مصالحا العالم لنفسه ، غير حاسب لهم خطاياهم ، وواضعا فينا كلمة المصالحة '),
(5231, '2 Corinthians', 47, 5, 20, ' إذا نسعى كسفراء عن المسيح ، كأن الله يعظ بنا . نطلب عن المسيح : تصالحوا مع الله '),
(5232, '2 Corinthians', 47, 5, 21, ' لأنه جعل الذي لم يعرف خطية ، خطية لأجلنا ، لنصير نحن بر الله فيه '),
(5233, '2 Corinthians', 47, 6, 1, ' فإذ نحن عاملون معه نطلب أن لا تقبلوا نعمة الله باطلا '),
(5234, '2 Corinthians', 47, 6, 2, ' لأنه يقول : في وقت مقبول سمعتك ، وفي يوم خلاص أعنتك . هوذا الآن وقت مقبول . هوذا الآن يوم خلاص '),
(5235, '2 Corinthians', 47, 6, 3, ' ولسنا نجعل عثرة في شيء لئلا تلام الخدمة '),
(5236, '2 Corinthians', 47, 6, 4, ' بل في كل شيء نظهر أنفسنا كخدام الله : في صبر كثير ، في شدائد ، في ضرورات ، في ضيقات '),
(5237, '2 Corinthians', 47, 6, 5, ' في ضربات ، في سجون ، في اضطرابات ، في أتعاب ، في أسهار ، في أصوام '),
(5238, '2 Corinthians', 47, 6, 6, ' في طهارة ، في علم ، في أناة ، في لطف ، في الروح القدس ، في محبة بلا رياء '),
(5239, '2 Corinthians', 47, 6, 7, ' في كلام الحق ، في قوة الله بسلاح البر لليمين ولليسار '),
(5240, '2 Corinthians', 47, 6, 8, ' بمجد وهوان ، بصيت رديء وصيت حسن . كمضلين ونحن صادقون '),
(5241, '2 Corinthians', 47, 6, 9, ' كمجهولين ونحن معروفون ، كمائتين وها نحن نحيا ، كمؤدبين ونحن غير مقتولين '),
(5242, '2 Corinthians', 47, 6, 10, ' كحزانى ونحن دائما فرحون ، كفقراء ونحن نغني كثيرين ، كأن لا شيء لنا ونحن نملك كل شيء '),
(5243, '2 Corinthians', 47, 6, 11, ' فمنا مفتوح إليكم أيها الكورنثيون . قلبنا متسع '),
(5244, '2 Corinthians', 47, 6, 12, ' لستم متضيقين فينا بل متضيقين في أحشائكم '),
(5245, '2 Corinthians', 47, 6, 13, ' فجزاء لذلك أقول كما لأولادي : كونوا أنتم أيضا متسعين '),
(5246, '2 Corinthians', 47, 6, 14, ' لا تكونوا تحت نير مع غير المؤمنين ، لأنه أية خلطة للبر والإثم ؟ وأية شركة للنور مع الظلمة '),
(5247, '2 Corinthians', 47, 6, 15, ' وأي اتفاق للمسيح مع بليعال ؟ وأي نصيب للمؤمن مع غير المؤمن '),
(5248, '2 Corinthians', 47, 6, 16, ' وأية موافقة لهيكل الله مع الأوثان ؟ فإنكم أنتم هيكل الله الحي ، كما قال الله : إني سأسكن فيهم وأسير بينهم ، وأكون لهم إلها ، وهم يكونون لي شعبا '),
(5249, '2 Corinthians', 47, 6, 17, ' لذلك اخرجوا من وسطهم واعتزلوا ، يقول الرب . ولا تمسوا نجسا فأقبلكم '),
(5250, '2 Corinthians', 47, 6, 18, ' وأكون لكم أبا ، وأنتم تكونون لي بنين وبنات ، يقول الرب ، القادر على كل شيء '),
(5251, '2 Corinthians', 47, 7, 1, ' فإذ لنا هذه المواعيد أيها الأحباء لنطهر ذواتنا من كل دنس الجسد والروح ، مكملين القداسة في خوف الله '),
(5252, '2 Corinthians', 47, 7, 2, ' اقبلونا . لم نظلم أحدا . لم نفسد أحدا . لم نطمع في أحد '),
(5253, '2 Corinthians', 47, 7, 3, ' لا أقول هذا لأجل دينونة ، لأني قد قلت سابقا إنكم في قلوبنا ، لنموت معكم ونعيش معكم '),
(5254, '2 Corinthians', 47, 7, 4, ' لي ثقة كثيرة بكم . لي افتخار كثير من جهتكم . قد امتلأت تعزية وازددت فرحا جدا في جميع ضيقاتنا '),
(5255, '2 Corinthians', 47, 7, 5, ' لأننا لما أتينا إلى مكدونية لم يكن لجسدنا شيء من الراحة بل كنا مكتئبين في كل شيء : من خارج خصومات ، من داخل مخاوف '),
(5256, '2 Corinthians', 47, 7, 6, ' لكن الله الذي يعزي المتضعين عزانا بمجيء تيطس '),
(5257, '2 Corinthians', 47, 7, 7, ' وليس بمجيئه فقط بل أيضا بالتعزية التي تعزى بها بسببكم ، وهو يخبرنا بشوقكم ونوحكم وغيرتكم لأجلي ، حتى إني فرحت أكثر '),
(5258, '2 Corinthians', 47, 7, 8, ' لأني وإن كنت قد أحزنتكم بالرسالة لست أندم ، مع أني ندمت . فإني أرى أن تلك الرسالة أحزنتكم ولو إلى ساعة '),
(5259, '2 Corinthians', 47, 7, 9, ' الآن أنا أفرح ، لا لأنكم حزنتم ، بل لأنكم حزنتم للتوبة . لأنكم حزنتم بحسب مشيئة الله لكي لا تتخسروا منا في شيء '),
(5260, '2 Corinthians', 47, 7, 10, ' لأن الحزن الذي بحسب مشيئة الله ينشئ توبة لخلاص بلا ندامة ، وأما حزن العالم فينشئ موتا '),
(5261, '2 Corinthians', 47, 7, 11, ' فإنه هوذا حزنكم هذا عينه بحسب مشيئة الله ، كم أنشأ فيكم : من الاجتهاد ، بل من الاحتجاج ، بل من الغيظ ، بل من الخوف ، بل من الشوق ، بل من الغيرة ، بل من الانتقام . في كل شيء أظهرتم أنفسكم أنكم أبرياء في هذا الأمر '),
(5262, '2 Corinthians', 47, 7, 12, ' إذا وإن كنت قد كتبت إليكم ، فليس لأجل المذنب ولا لأجل المذنب إليه ، بل لكي يظهر لكم أمام الله اجتهادنا لأجلكم '),
(5263, '2 Corinthians', 47, 7, 13, ' من أجل هذا قد تعزينا بتعزيتكم . ولكن فرحنا أكثر جدا بسبب فرح تيطس ، لأن روحه قد استراحت بكم جميعا '),
(5264, '2 Corinthians', 47, 7, 14, ' فإني إن كنت افتخرت شيئا لديه من جهتكم لم أخجل ، بل كما كلمناكم بكل شيء بالصدق ، كذلك افتخارنا أيضا لدى تيطس صار صادقا '),
(5265, '2 Corinthians', 47, 7, 15, ' وأحشاؤه هي نحوكم بالزيادة ، متذكرا طاعة جميعكم ، كيف قبلتموه بخوف ورعدة '),
(5266, '2 Corinthians', 47, 7, 16, ' أنا أفرح إذا أني أثق بكم في كل شيء '),
(5267, '2 Corinthians', 47, 8, 1, ' ثم نعرفكم أيها الإخوة نعمة الله المعطاة في كنائس مكدونية '),
(5268, '2 Corinthians', 47, 8, 2, ' أنه في اختبار ضيقة شديدة فاض وفور فرحهم وفقرهم العميق لغنى سخائهم '),
(5269, '2 Corinthians', 47, 8, 3, ' لأنهم أعطوا حسب الطاقة ، أنا أشهد ، وفوق الطاقة ، من تلقاء أنفسهم '),
(5270, '2 Corinthians', 47, 8, 4, ' ملتمسين منا ، بطلبة كثيرة ، أن نقبل النعمة وشركة الخدمة التي للقديسين '),
(5271, '2 Corinthians', 47, 8, 5, ' وليس كما رجونا ، بل أعطوا أنفسهم أولا للرب ، ولنا ، بمشيئة الله '),
(5272, '2 Corinthians', 47, 8, 6, ' حتى إننا طلبنا من تيطس أنه كما سبق فابتدأ ، كذلك يتمم لكم هذه النعمة أيضا '),
(5273, '2 Corinthians', 47, 8, 7, ' لكن كما تزدادون في كل شيء : في الإيمان والكلام والعلم وكل اجتهاد ومحبتكم لنا ، ليتكم تزدادون في هذه النعمة أيضا '),
(5274, '2 Corinthians', 47, 8, 8, ' لست أقول على سبيل الأمر ، بل باجتهاد آخرين ، مختبرا إخلاص محبتكم أيضا '),
(5275, '2 Corinthians', 47, 8, 9, ' فإنكم تعرفون نعمة ربنا يسوع المسيح ، أنه من أجلكم افتقر وهو غني ، لكي تستغنوا أنتم بفقره '),
(5276, '2 Corinthians', 47, 8, 10, ' أعطي رأيا في هذا أيضا ، لأن هذا ينفعكم أنتم الذين سبقتم فابتدأتم منذ العام الماضي ، ليس أن تفعلوا فقط بل أن تريدوا أيضا '),
(5277, '2 Corinthians', 47, 8, 11, ' ولكن الآن تمموا العمل أيضا ، حتى إنه كما أن النشاط للإرادة ، كذلك يكون التتميم أيضا حسب ما لكم '),
(5278, '2 Corinthians', 47, 8, 12, ' لأنه إن كان النشاط موجودا فهو مقبول على حسب ما للإنسان ، لا على حسب ما ليس له '),
(5279, '2 Corinthians', 47, 8, 13, ' فإنه ليس لكي يكون للآخرين راحة ولكم ضيق '),
(5280, '2 Corinthians', 47, 8, 14, ' بل بحسب المساواة . لكي تكون في هذا الوقت فضالتكم لإعوازهم ، كي تصير فضالتهم لإعوازكم ، حتى تحصل المساواة '),
(5281, '2 Corinthians', 47, 8, 15, ' كما هو مكتوب : الذي جمع كثيرا لم يفضل ، والذي جمع قليلا لم ينقص '),
(5282, '2 Corinthians', 47, 8, 16, ' ولكن شكرا لله الذي جعل هذا الاجتهاد عينه لأجلكم في قلب تيطس '),
(5283, '2 Corinthians', 47, 8, 17, ' لأنه قبل الطلبة . وإذ كان أكثر اجتهادا ، مضى إليكم من تلقاء نفسه '),
(5284, '2 Corinthians', 47, 8, 18, ' وأرسلنا معه الأخ الذي مدحه في الإنجيل في جميع الكنائس '),
(5285, '2 Corinthians', 47, 8, 19, ' وليس ذلك فقط ، بل هو منتخب أيضا من الكنائس رفيقا لنا في السفر ، مع هذه النعمة المخدومة منا لمجد ذات الرب الواحد ، ولنشاطكم '),
(5286, '2 Corinthians', 47, 8, 20, ' متجنبين هذا أن يلومنا أحد في جسامة هذه المخدومة منا '),
(5287, '2 Corinthians', 47, 8, 21, ' معتنين بأمور حسنة ، ليس قدام الرب فقط ، بل قدام الناس أيضا '),
(5288, '2 Corinthians', 47, 8, 22, ' وأرسلنا معهما أخانا ، الذي اختبرنا مرارا في أمور كثيرة أنه مجتهد ، ولكنه الآن أشد اجتهادا كثيرا بالثقة الكثيرة بكم '),
(5289, '2 Corinthians', 47, 8, 23, ' أما من جهة تيطس فهو شريك لي وعامل معي لأجلكم . وأما أخوانا فهما رسولا الكنائس ، ومجد المسيح '),
(5290, '2 Corinthians', 47, 8, 24, ' فبينوا لهم ، وقدام الكنائس ، بينة محبتكم ، وافتخارنا من جهتكم '),
(5291, '2 Corinthians', 47, 9, 1, ' فإنه من جهة الخدمة للقديسين ، هو فضول مني أن أكتب إليكم '),
(5292, '2 Corinthians', 47, 9, 2, ' لأني أعلم نشاطكم الذي أفتخر به من جهتكم لدى المكدونيين ، أن أخائية مستعدة منذ العام الماضي . وغيرتكم قد حرضت الأكثرين '),
(5293, '2 Corinthians', 47, 9, 3, ' ولكن أرسلت الإخوة لئلا يتعطل افتخارنا من جهتكم من هذا القبيل ، كي تكونوا مستعدين كما قلت '),
(5294, '2 Corinthians', 47, 9, 4, ' حتى إذا جاء معي مكدونيون ووجدوكم غير مستعدين لا نخجل نحن - حتى لا أقول أنتم - في جسارة الافتخار هذه '),
(5295, '2 Corinthians', 47, 9, 5, ' فرأيت لازما أن أطلب إلى الإخوة أن يسبقوا إليكم ، ويهيئوا قبلا بركتكم التي سبق التخبير بها ، لتكون هي معدة هكذا كأنها بركة ، لا كأنها بخل '),
(5296, '2 Corinthians', 47, 9, 6, ' هذا وإن من يزرع بالشح فبالشح أيضا يحصد ، ومن يزرع بالبركات فبالبركات أيضا يحصد '),
(5297, '2 Corinthians', 47, 9, 7, ' كل واحد كما ينوي بقلبه ، ليس عن حزن أو اضطرار . لأن المعطي المسرور يحبه الله '),
(5298, '2 Corinthians', 47, 9, 8, ' والله قادر أن يزيدكم كل نعمة ، لكي تكونوا ولكم كل اكتفاء كل حين في كل شيء ، تزدادون في كل عمل صالح '),
(5299, '2 Corinthians', 47, 9, 9, ' كما هو مكتوب : فرق . أعطى المساكين . بره يبقى إلى الأبد '),
(5300, '2 Corinthians', 47, 9, 10, ' والذي يقدم بذارا للزارع وخبزا للأكل ، سيقدم ويكثر بذاركم وينمي غلات بركم '),
(5301, '2 Corinthians', 47, 9, 11, ' مستغنين في كل شيء لكل سخاء ينشئ بنا شكرا لله '),
(5302, '2 Corinthians', 47, 9, 12, ' لأن افتعال هذه الخدمة ليس يسد إعواز القديسين فقط ، بل يزيد بشكر كثير لله '),
(5303, '2 Corinthians', 47, 9, 13, ' إذ هم باختبار هذه الخدمة ، يمجدون الله على طاعة اعترافكم لإنجيل المسيح ، وسخاء التوزيع لهم وللجميع '),
(5304, '2 Corinthians', 47, 9, 14, ' وبدعائهم لأجلكم ، مشتاقين إليكم من أجل نعمة الله الفائقة لديكم '),
(5305, '2 Corinthians', 47, 9, 15, ' فشكرا لله على عطيته التي لا يعبر عنها '),
(5306, '2 Corinthians', 47, 10, 1, ' ثم أطلب إليكم بوداعة المسيح وحلمه ، أنا نفسي بولس الذي في الحضرة ذليل بينكم ، وأما في الغيبة فمتجاسر عليكم '),
(5307, '2 Corinthians', 47, 10, 2, ' ولكن أطلب أن لا أتجاسر وأنا حاضر بالثقة التي بها أرى أني سأجترئ على قوم يحسبوننا كأننا نسلك حسب الجسد '),
(5308, '2 Corinthians', 47, 10, 3, ' لأننا وإن كنا نسلك في الجسد ، لسنا حسب الجسد نحارب '),
(5309, '2 Corinthians', 47, 10, 4, ' إذ أسلحة محاربتنا ليست جسدية ، بل قادرة بالله على هدم حصون '),
(5310, '2 Corinthians', 47, 10, 5, ' هادمين ظنونا وكل علو يرتفع ضد معرفة الله ، ومستأسرين كل فكر إلى طاعة المسيح '),
(5311, '2 Corinthians', 47, 10, 6, ' ومستعدين لأن ننتقم على كل عصيان ، متى كملت طاعتكم '),
(5312, '2 Corinthians', 47, 10, 7, ' أتنظرون إلى ما هو حسب الحضرة ؟ إن وثق أحد بنفسه أنه للمسيح ، فليحسب هذا أيضا من نفسه : أنه كما هو للمسيح ، كذلك نحن أيضا للمسيح '),
(5313, '2 Corinthians', 47, 10, 8, ' فإني وإن افتخرت شيئا أكثر بسلطاننا الذي أعطانا إياه الرب لبنيانكم لا لهدمكم ، لا أخجل '),
(5314, '2 Corinthians', 47, 10, 9, ' لئلا أظهر كأني أخيفكم بالرسائل '),
(5315, '2 Corinthians', 47, 10, 10, ' لأنه يقول : الرسائل ثقيلة وقوية ، وأما حضور الجسد فضعيف ، والكلام حقير '),
(5316, '2 Corinthians', 47, 10, 11, ' مثل هذا فليحسب هذا : أننا كما نحن في الكلام بالرسائل ونحن غائبون ، هكذا نكون أيضا بالفعل ونحن حاضرون '),
(5317, '2 Corinthians', 47, 10, 12, ' لأننا لا نجترئ أن نعد أنفسنا بين قوم من الذين يمدحون أنفسهم ، ولا أن نقابل أنفسنا بهم . بل هم إذ يقيسون أنفسهم على أنفسهم ، ويقابلون أنفسهم بأنفسهم ، لا يفهمون '),
(5318, '2 Corinthians', 47, 10, 13, ' ولكن نحن لا نفتخر إلى ما لا يقاس ، بل حسب قياس القانون الذي قسمه لنا الله ، قياسا للبلوغ إليكم أيضا '),
(5319, '2 Corinthians', 47, 10, 14, ' لأننا لا نمدد أنفسنا كأننا لسنا نبلغ إليكم . إذ قد وصلنا إليكم أيضا في إنجيل المسيح '),
(5320, '2 Corinthians', 47, 10, 15, ' غير مفتخرين إلى ما لا يقاس في أتعاب آخرين ، بل راجين - إذا نما إيمانكم - أن نتعظم بينكم حسب قانوننا بزيادة '),
(5321, '2 Corinthians', 47, 10, 16, ' لنبشر إلى ما وراءكم . لا لنفتخر بالأمور المعدة في قانون غيرنا '),
(5322, '2 Corinthians', 47, 10, 17, ' وأما : من افتخر فليفتخر بالرب '),
(5323, '2 Corinthians', 47, 10, 18, ' لأنه ليس من مدح نفسه هو المزكى ، بل من يمدحه الرب '),
(5324, '2 Corinthians', 47, 11, 1, ' ليتكم تحتملون غباوتي قليلا بل أنتم محتملي '),
(5325, '2 Corinthians', 47, 11, 2, ' فإني أغار عليكم غيرة الله ، لأني خطبتكم لرجل واحد ، لأقدم عذراء عفيفة للمسيح '),
(5326, '2 Corinthians', 47, 11, 3, ' ولكنني أخاف أنه كما خدعت الحية حواء بمكرها ، هكذا تفسد أذهانكم عن البساطة التي في المسيح '),
(5327, '2 Corinthians', 47, 11, 4, ' فإنه إن كان الآتي يكرز بيسوع آخر لم نكرز به ، أو كنتم تأخذون روحا آخر لم تأخذوه ، أو إنجيلا آخر لم تقبلوه ، فحسنا كنتم تحتملون '),
(5328, '2 Corinthians', 47, 11, 5, ' لأني أحسب أني لم أنقص شيئا عن فائقي الرسل '),
(5329, '2 Corinthians', 47, 11, 6, ' وإن كنت عاميا في الكلام ، فلست في العلم ، بل نحن في كل شيء ظاهرون لكم بين الجميع '),
(5330, '2 Corinthians', 47, 11, 7, ' أم أخطأت خطية إذ أذللت نفسي كي ترتفعوا أنتم ، لأني بشرتكم مجانا بإنجيل الله '),
(5331, '2 Corinthians', 47, 11, 8, ' سلبت كنائس أخرى آخذا أجرة لأجل خدمتكم ، وإذ كنت حاضرا عندكم واحتجت ، لم أثقل على أحد '),
(5332, '2 Corinthians', 47, 11, 9, ' لأن احتياجي سده الإخوة الذين أتوا من مكدونية . وفي كل شيء حفظت نفسي غير ثقيل عليكم ، وسأحفظها '),
(5333, '2 Corinthians', 47, 11, 10, ' حق المسيح في . إن هذا الافتخار لا يسد عني في أقاليم أخائية '),
(5334, '2 Corinthians', 47, 11, 11, ' لماذا ؟ ألأني لا أحبكم ؟ الله يعلم '),
(5335, '2 Corinthians', 47, 11, 12, ' ولكن ما أفعله سأفعله لأقطع فرصة الذين يريدون فرصة كي يوجدوا كما نحن أيضا في ما يفتخرون به '),
(5336, '2 Corinthians', 47, 11, 13, ' لأن مثل هؤلاء هم رسل كذبة ، فعلة ماكرون ، مغيرون شكلهم إلى شبه رسل المسيح '),
(5337, '2 Corinthians', 47, 11, 14, ' ولا عجب . لأن الشيطان نفسه يغير شكله إلى شبه ملاك نور '),
(5338, '2 Corinthians', 47, 11, 15, ' فليس عظيما إن كان خدامه أيضا يغيرون شكلهم كخدام للبر . الذين نهايتهم تكون حسب أعمالهم '),
(5339, '2 Corinthians', 47, 11, 16, ' أقول أيضا : لا يظن أحد أني غبي . وإلا فاقبلوني ولو كغبي ، لأفتخر أنا أيضا قليلا '),
(5340, '2 Corinthians', 47, 11, 17, ' الذي أتكلم به لست أتكلم به بحسب الرب ، بل كأنه في غباوة ، في جسارة الافتخار هذه '),
(5341, '2 Corinthians', 47, 11, 18, ' بما أن كثيرين يفتخرون حسب الجسد ، أفتخر أنا أيضا '),
(5342, '2 Corinthians', 47, 11, 19, ' فإنكم بسرور تحتملون الأغبياء ، إذ أنتم عقلاء '),
(5343, '2 Corinthians', 47, 11, 20, ' لأنكم تحتملون : إن كان أحد يستعبدكم إن كان أحد يأكلكم إن كان أحد يأخذكم إن كان أحد يرتفع إن كان أحد يضربكم على وجوهكم '),
(5344, '2 Corinthians', 47, 11, 21, ' على سبيل الهوان أقول : كيف أننا كنا ضعفاء ولكن الذي يجترئ فيه أحد ، أقول في غباوة : أنا أيضا أجترئ فيه '),
(5345, '2 Corinthians', 47, 11, 22, ' أهم عبرانيون ؟ فأنا أيضا . أهم إسرائيليون ؟ فأنا أيضا . أهم نسل إبراهيم ؟ فأنا أيضا '),
(5346, '2 Corinthians', 47, 11, 23, ' أهم خدام المسيح ؟ أقول كمختل العقل ، فأنا أفضل : في الأتعاب أكثر ، في الضربات أوفر ، في السجون أكثر ، في الميتات مرارا كثيرة '),
(5347, '2 Corinthians', 47, 11, 24, ' من اليهود خمس مرات قبلت أربعين جلدة إلا واحدة '),
(5348, '2 Corinthians', 47, 11, 25, ' ثلاث مرات ضربت بالعصي ، مرة رجمت ، ثلاث مرات انكسرت بي السفينة ، ليلا ونهارا قضيت في العمق '),
(5349, '2 Corinthians', 47, 11, 26, ' بأسفار مرارا كثيرة ، بأخطار سيول ، بأخطار لصوص ، بأخطار من جنسي ، بأخطار من الأمم ، بأخطار في المدينة ، بأخطار في البرية ، بأخطار في البحر ، بأخطار من إخوة كذبة '),
(5350, '2 Corinthians', 47, 11, 27, ' في تعب وكد ، في أسهار مرارا كثيرة ، في جوع وعطش ، في أصوام مرارا كثيرة ، في برد وعري '),
(5351, '2 Corinthians', 47, 11, 28, ' عدا ما هو دون ذلك : التراكم علي كل يوم ، الاهتمام بجميع الكنائس '),
(5352, '2 Corinthians', 47, 11, 29, ' من يضعف وأنا لا أضعف ؟ من يعثر وأنا لا ألتهب '),
(5353, '2 Corinthians', 47, 11, 30, ' إن كان يجب الافتخار ، فسأفتخر بأمور ضعفي '),
(5354, '2 Corinthians', 47, 11, 31, ' الله أبو ربنا يسوع المسيح ، الذي هو مبارك إلى الأبد ، يعلم أني لست أكذب '),
(5355, '2 Corinthians', 47, 11, 32, ' في دمشق ، والي الحارث الملك كان يحرس مدينة الدمشقيين ، يريد أن يمسكني '),
(5356, '2 Corinthians', 47, 11, 33, ' فتدليت من طاقة في زنبيل من السور ، ونجوت من يديه '),
(5357, '2 Corinthians', 47, 12, 1, ' إنه لا يوافقني أن أفتخر . فإني آتي إلى مناظر الرب وإعلاناته '),
(5358, '2 Corinthians', 47, 12, 2, ' أعرف إنسانا في المسيح قبل أربع عشرة سنة . أفي الجسد ؟ لست أعلم ، أم خارج الجسد ؟ لست أعلم . الله يعلم . اختطف هذا إلى السماء الثالثة '),
(5359, '2 Corinthians', 47, 12, 3, ' وأعرف هذا الإنسان : أفي الجسد أم خارج الجسد ؟ لست أعلم . الله يعلم '),
(5360, '2 Corinthians', 47, 12, 4, ' أنه اختطف إلى الفردوس ، وسمع كلمات لا ينطق بها ، ولا يسوغ لإنسان أن يتكلم بها '),
(5361, '2 Corinthians', 47, 12, 5, ' من جهة هذا أفتخر . ولكن من جهة نفسي لا أفتخر إلا بضعفاتي '),
(5362, '2 Corinthians', 47, 12, 6, ' فإني إن أردت أن أفتخر لا أكون غبيا ، لأني أقول الحق . ولكني أتحاشى لئلا يظن أحد من جهتي فوق ما يراني أو يسمع مني '),
(5363, '2 Corinthians', 47, 12, 7, ' ولئلا أرتفع بفرط الإعلانات ، أعطيت شوكة في الجسد ، ملاك الشيطان ليلطمني ، لئلا أرتفع '),
(5364, '2 Corinthians', 47, 12, 8, ' من جهة هذا تضرعت إلى الرب ثلاث مرات أن يفارقني '),
(5365, '2 Corinthians', 47, 12, 9, ' فقال لي : تكفيك نعمتي ، لأن قوتي في الضعف تكمل . فبكل سرور أفتخر بالحري في ضعفاتي ، لكي تحل علي قوة المسيح '),
(5366, '2 Corinthians', 47, 12, 10, ' لذلك أسر بالضعفات والشتائم والضرورات والاضطهادات والضيقات لأجل المسيح . لأني حينما أنا ضعيف فحينئذ أنا قوي '),
(5367, '2 Corinthians', 47, 12, 11, ' قد صرت غبيا وأنا أفتخر . أنتم ألزمتموني لأنه كان ينبغي أن أمدح منكم ، إذ لم أنقص شيئا عن فائقي الرسل ، وإن كنت لست شيئا '),
(5368, '2 Corinthians', 47, 12, 12, ' إن علامات الرسول صنعت بينكم في كل صبر ، بآيات وعجائب وقوات '),
(5369, '2 Corinthians', 47, 12, 13, ' لأنه ما هو الذي نقصتم عن سائر الكنائس ، إلا أني أنا لم أثقل عليكم ؟ سامحوني بهذا الظلم '),
(5370, '2 Corinthians', 47, 12, 14, ' هوذا المرة الثالثة أنا مستعد أن آتي إليكم ولا أثقل عليكم . لأني لست أطلب ما هو لكم بل إياكم . لأنه لا ينبغي أن الأولاد يذخرون للوالدين ، بل الوالدون للأولاد '),
(5371, '2 Corinthians', 47, 12, 15, ' وأما أنا فبكل سرور أنفق وأنفق لأجل أنفسكم ، وإن كنت كلما أحبكم أكثر أحب أقل '),
(5372, '2 Corinthians', 47, 12, 16, ' فليكن . أنا لم أثقل عليكم ، لكن إذ كنت محتالا أخذتكم بمكر '),
(5373, '2 Corinthians', 47, 12, 17, ' هل طمعت فيكم بأحد من الذين أرسلتهم إليكم '),
(5374, '2 Corinthians', 47, 12, 18, ' طلبت إلى تيطس وأرسلت معه الأخ . هل طمع فيكم تيطس ؟ أما سلكنا بذات الروح الواحد ؟ أما بذات الخطوات الواحدة '),
(5375, '2 Corinthians', 47, 12, 19, ' أتظنون أيضا أننا نحتج لكم ؟ أمام الله في المسيح نتكلم . ولكن الكل أيها الأحباء لأجل بنيانكم '),
(5376, '2 Corinthians', 47, 12, 20, ' لأني أخاف إذا جئت أن لا أجدكم كما أريد ، وأوجد منكم كما لا تريدون . أن توجد خصومات ومحاسدات وسخطات وتحزبات ومذمات ونميمات وتكبرات وتشويشات '),
(5377, '2 Corinthians', 47, 12, 21, ' أن يذلني إلهي عندكم ، إذا جئت أيضا وأنوح على كثيرين من الذين أخطأوا من قبل ولم يتوبوا عن النجاسة والزنا والعهارة التي فعلوها '),
(5378, '2 Corinthians', 47, 13, 1, ' هذه المرة الثالثة آتي إليكم . على فم شاهدين وثلاثة تقوم كل كلمة '),
(5379, '2 Corinthians', 47, 13, 2, ' قد سبقت فقلت ، وأسبق فأقول كما وأنا حاضر المرة الثانية ، وأنا غائب الآن ، أكتب للذين أخطأوا من قبل ، ولجميع الباقين : أني إذا جئت أيضا لا أشفق '),
(5380, '2 Corinthians', 47, 13, 3, ' إذ أنتم تطلبون برهان المسيح المتكلم في ، الذي ليس ضعيفا لكم بل قوي فيكم '),
(5381, '2 Corinthians', 47, 13, 4, ' لأنه وإن كان قد صلب من ضعف ، لكنه حي بقوة الله . فنحن أيضا ضعفاء فيه ، لكننا سنحيا معه بقوة الله من جهتكم '),
(5382, '2 Corinthians', 47, 13, 5, ' جربوا أنفسكم ، هل أنتم في الإيمان ؟ امتحنوا أنفسكم . أم لستم تعرفون أنفسكم ، أن يسوع المسيح هو فيكم ، إن لم تكونوا مرفوضين '),
(5383, '2 Corinthians', 47, 13, 6, ' لكنني أرجو أنكم ستعرفون أننا نحن لسنا مرفوضين '),
(5384, '2 Corinthians', 47, 13, 7, ' وأصلي إلى الله أنكم لا تعملون شيئا رديا ، ليس لكي نظهر نحن مزكين ، بل لكي تصنعوا أنتم حسنا ، ونكون نحن كأننا مرفوضون '),
(5385, '2 Corinthians', 47, 13, 8, ' لأننا لا نستطيع شيئا ضد الحق ، بل لأجل الحق '),
(5386, '2 Corinthians', 47, 13, 9, ' لأننا نفرح حينما نكون نحن ضعفاء وأنتم تكونون أقوياء . وهذا أيضا نطلبه كما لكم '),
(5387, '2 Corinthians', 47, 13, 10, ' لذلك أكتب بهذا وأنا غائب ، لكي لا أستعمل جزما وأنا حاضر ، حسب السلطان الذي أعطاني إياه الرب للبنيان لا للهدم '),
(5388, '2 Corinthians', 47, 13, 11, ' أخيرا أيها الإخوة افرحوا . اكملوا . تعزوا . اهتموا اهتماما واحدا . عيشوا بالسلام ، وإله المحبة والسلام سيكون معكم '),
(5389, '2 Corinthians', 47, 13, 12, ' سلموا بعضكم على بعض بقبلة مقدسة '),
(5390, '2 Corinthians', 47, 13, 13, ' يسلم عليكم جميع القديسين '),
(5391, '2 Corinthians', 47, 13, 14, ' نعمة ربنا يسوع المسيح ، ومحبة الله ، وشركة الروح القدس مع جميعكم . آمين '),
(5392, '2 John', 63, 1, 1, ' الشيخ ، إلى كيرية المختارة ، وإلى أولادها الذين أنا أحبهم بالحق ، ولست أنا فقط ، بل أيضا جميع الذين قد عرفوا الحق '),
(5393, '2 John', 63, 1, 2, ' من أجل الحق الذي يثبت فينا وسيكون معنا إلى الأبد '),
(5394, '2 John', 63, 1, 3, ' تكون معكم نعمة ورحمة وسلام من الله الآب ومن الرب يسوع المسيح ، ابن الآب بالحق والمحبة '),
(5395, '2 John', 63, 1, 4, ' فرحت جدا لأني وجدت من أولادك بعضا سالكين في الحق ، كما أخذنا وصية من الآب '),
(5396, '2 John', 63, 1, 5, ' والآن أطلب منك يا كيرية ، لا كأني أكتب إليك وصية جديدة ، بل التي كانت عندنا من البدء : أن يحب بعضنا بعضا '),
(5397, '2 John', 63, 1, 6, ' وهذه هي المحبة : أن نسلك بحسب وصاياه . هذه هي الوصية ، كما سمعتم من البدء أن تسلكوا فيها '),
(5398, '2 John', 63, 1, 7, ' لأنه قد دخل إلى العالم مضلون كثيرون ، لا يعترفون بيسوع المسيح آتيا في الجسد . هذا هو المضل ، والضد للمسيح '),
(5399, '2 John', 63, 1, 8, ' انظروا إلى أنفسكم لئلا نضيع ما عملناه ، بل ننال أجرا تاما '),
(5400, '2 John', 63, 1, 9, ' كل من تعدى ولم يثبت في تعليم المسيح فليس له الله . ومن يثبت في تعليم المسيح فهذا له الآب والابن جميعا '),
(5401, '2 John', 63, 1, 10, ' إن كان أحد يأتيكم ، ولا يجيء بهذا التعليم ، فلا تقبلوه في البيت ، ولا تقولوا له سلام '),
(5402, '2 John', 63, 1, 11, ' لأن من يسلم عليه يشترك في أعماله الشريرة '),
(5403, '2 John', 63, 1, 12, ' إذ كان لي كثير لأكتب إليكم ، لم أرد أن يكون بورق وحبر ، لأني أرجو أن آتي إليكم وأتكلم فما لفم ، لكي يكون فرحنا كاملا '),
(5404, '2 John', 63, 1, 13, ' يسلم عليك أولاد أختك المختارة . آمين '),
(5405, '2 Kings', 12, 1, 1, ' وعصى موآب على إسرائيل بعد وفاة أخآب '),
(5406, '2 Kings', 12, 1, 2, ' وسقط أخزيا من الكوة التي في عليته التي في السامرة فمرض ، وأرسل رسلا وقال لهم : اذهبوا اسألوا بعل زبوب إله عقرون إن كنت أبرأ من هذا المرض '),
(5407, '2 Kings', 12, 1, 3, ' فقال ملاك الرب لإيليا التشبي : قم اصعد للقاء رسل ملك السامرة وقل لهم : أليس لأنه لا يوجد في إسرائيل إله ، تذهبون لتسألوا بعل زبوب إله عقرون '),
(5408, '2 Kings', 12, 1, 4, ' فلذلك هكذا قال الرب : إن السرير الذي صعدت عليه لا تنزل عنه بل موتا تموت . فانطلق إيليا '),
(5409, '2 Kings', 12, 1, 5, ' ورجع الرسل إليه ، فقال لهم : لماذا رجعتم '),
(5410, '2 Kings', 12, 1, 6, ' فقالوا له : صعد رجل للقائنا وقال لنا : اذهبوا راجعين إلى الملك الذي أرسلكم وقولوا له : هكذا قال الرب : أليس لأنه لا يوجد في إسرائيل إله أرسلت لتسأل بعل زبوب إله عقرون ؟ لذلك السرير الذي صعدت عليه ، لا تنزل عنه بل موتا تموت '),
(5411, '2 Kings', 12, 1, 7, ' فقال لهم : ما هي هيئة الرجل الذي صعد للقائكم وكلمكم بهذا الكلام '),
(5412, '2 Kings', 12, 1, 8, ' فقالوا له : إنه رجل أشعر متنطق بمنطقة من جلد على حقويه . فقال : هو إيليا التشبي '),
(5413, '2 Kings', 12, 1, 9, ' فأرسل إليه رئيس خمسين مع الخمسين الذين له ، فصعد إليه وإذا هو جالس على رأس الجبل . فقال له : يا رجل الله ، الملك يقول : انزل '),
(5414, '2 Kings', 12, 1, 10, ' فأجاب إيليا وقال لرئيس الخمسين : إن كنت أنا رجل الله ، فلتنزل نار من السماء وتأكلك أنت والخمسين الذين لك . فنزلت نار من السماء وأكلته هو والخمسين الذين له '),
(5415, '2 Kings', 12, 1, 11, ' ثم عاد وأرسل إليه رئيس خمسين آخر والخمسين الذين له . فأجاب وقال له : يا رجل الله ، هكذا يقول الملك : أسرع وانزل '),
(5416, '2 Kings', 12, 1, 12, ' فأجاب إيليا وقال لهم : إن كنت أنا رجل الله ، فلتنزل نار من السماء وتأكلك أنت والخمسين الذين لك . فنزلت نار الله من السماء وأكلته هو والخمسين الذين له '),
(5417, '2 Kings', 12, 1, 13, ' ثم عاد فأرسل رئيس خمسين ثالثا والخمسين الذين له . فصعد رئيس الخمسين الثالث وجاء وجثا على ركبتيه أمام إيليا ، وتضرع إليه وقال له : يا رجل الله ، لتكرم نفسي وأنفس عبيدك هؤلاء الخمسين في عينيك '),
(5418, '2 Kings', 12, 1, 14, ' هوذا قد نزلت نار من السماء وأكلت رئيسي الخمسينين الأولين وخمسينيهما ، والآن فلتكرم نفسي في عينيك '),
(5419, '2 Kings', 12, 1, 15, ' فقال ملاك الرب لإيليا : انزل معه . لا تخف منه . فقام ونزل معه إلى الملك '),
(5420, '2 Kings', 12, 1, 16, ' وقال له : هكذا قال الرب : من أجل أنك أرسلت رسلا لتسأل بعل زبوب إله عقرون ، أليس لأنه لا يوجد في إسرائيل إله لتسأل عن كلامه لذلك السرير الذي صعدت عليه لا تنزل عنه بل موتا تموت '),
(5421, '2 Kings', 12, 1, 17, ' فمات حسب كلام الرب الذي تكلم به إيليا . وملك يهورام عوضا عنه في السنة الثانية ليهورام بن يهوشافاط ملك يهوذا ، لأنه لم يكن له ابن '),
(5422, '2 Kings', 12, 1, 18, ' وبقية أمور أخزيا التي عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5423, '2 Kings', 12, 2, 1, ' وكان عند إصعاد الرب إيليا في العاصفة إلى السماء ، أن إيليا وأليشع ذهبا من الجلجال ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(5424, '2 Kings', 12, 2, 2, ' فقال إيليا لأليشع : امكث هنا لأن الرب قد أرسلني إلى بيت إيل . فقال أليشع : حي هو الرب ، وحية هي نفسك ، إني لا أتركك . ونزلا إلى بيت إيل '),
(5425, '2 Kings', 12, 2, 3, ' فخرج بنو الأنبياء الذين في بيت إيل إلى أليشع وقالوا له : أتعلم أنه اليوم يأخذ الرب سيدك من على رأسك ؟  . فقال : نعم ، إني أعلم فاصمتوا '),
(5426, '2 Kings', 12, 2, 4, ' ثم قال له إيليا : يا أليشع ، امكث هنا لأن الرب قد أرسلني إلى أريحا . فقال : حي هو الرب ، وحية هي نفسك ، إني لا أتركك . وأتيا إلى أريحا '),
(5427, '2 Kings', 12, 2, 5, ' فتقدم بنو الأنبياء الذين في أريحا إلى أليشع وقالوا له : أتعلم أنه اليوم يأخذ الرب سيدك من على رأسك ؟  . فقال : نعم ، إني أعلم فاصمتوا '),
(5428, '2 Kings', 12, 2, 6, ' ثم قال له إيليا : أمكث هنا لأن الرب قد أرسلني إلى الأردن . فقال : حي هو الرب ، وحية هي نفسك ، إني لا أتركك . وانطلقا كلاهما '),
(5429, '2 Kings', 12, 2, 7, ' فذهب خمسون رجلا من بني الأنبياء ووقفوا قبالتهما من بعيد . ووقف كلاهما بجانب الأردن '),
(5430, '2 Kings', 12, 2, 8, ' وأخذ إيليا رداءه ولفه وضرب الماء ، فانفلق إلى هنا وهناك ، فعبرا كلاهما في اليبس '),
(5431, '2 Kings', 12, 2, 9, ' ولما عبرا قال إيليا لأليشع : اطلب : ماذا أفعل لك قبل أن أوخذ منك ؟  . فقال أليشع : ليكن نصيب اثنين من روحك علي '),
(5432, '2 Kings', 12, 2, 10, ' فقال : صعبت السؤال . فإن رأيتني أوخذ منك يكون لك كذلك ، وإلا فلا يكون '),
(5433, '2 Kings', 12, 2, 11, ' وفيما هما يسيران ويتكلمان إذا مركبة من نار وخيل من نار ففصلت بينهما ، فصعد إيليا في العاصفة إلى السماء '),
(5434, '2 Kings', 12, 2, 12, ' وكان أليشع يرى وهو يصرخ : يا أبي ، يا أبي ، مركبة إسرائيل وفرسانها . ولم يره بعد ، فأمسك ثيابه ومزقها قطعتين '),
(5435, '2 Kings', 12, 2, 13, ' ورفع رداء إيليا الذي سقط عنه ، ورجع ووقف على شاطئ الأردن '),
(5436, '2 Kings', 12, 2, 14, ' فأخذ رداء إيليا الذي سقط عنه وضرب الماء وقال : أين هو الرب إله إيليا ؟  . ثم ضرب الماء أيضا فانفلق إلى هنا وهناك ، فعبر أليشع '),
(5437, '2 Kings', 12, 2, 15, ' ولما رآه بنو الأنبياء الذين في أريحا قبالته قالوا : قد استقرت روح إيليا على أليشع . فجاءوا للقائه وسجدوا له إلى الأرض '),
(5438, '2 Kings', 12, 2, 16, ' وقالوا له : هوذا مع عبيدك خمسون رجلا ذوو بأس ، فدعهم يذهبون ويفتشون على سيدك ، لئلا يكون قد حمله روح الرب وطرحه على أحد الجبال ، أو في أحد الأودية . فقال : لاترسلوا '),
(5439, '2 Kings', 12, 2, 17, ' فألحوا عليه حتى خجل وقال : أرسلوا . فأرسلوا خمسين رجلا ، ففتشوا ثلاثة أيام ولم يجدوه '),
(5440, '2 Kings', 12, 2, 18, ' ولما رجعوا إليه وهو ماكث في أريحا قال لهم : أما قلت لكم لا تذهبوا '),
(5441, '2 Kings', 12, 2, 19, ' وقال رجال المدينة لأليشع : هوذا موقع المدينة حسن كما يرى سيدي ، وأما المياه فردية والأرض مجدبة '),
(5442, '2 Kings', 12, 2, 20, ' فقال : ائتوني بصحن جديد ، وضعوا فيه ملحا . فأتوه به '),
(5443, '2 Kings', 12, 2, 21, ' فخرج إلى نبع الماء وطرح فيه الملح وقال : هكذا قال الرب : قد أبرأت هذه المياه . لا يكون فيها أيضا موت ولا جدب '),
(5444, '2 Kings', 12, 2, 22, ' فبرئت المياه إلى هذا اليوم ، حسب قول أليشع الذي نطق به '),
(5445, '2 Kings', 12, 2, 23, ' ثم صعد من هناك إلى بيت إيل . وفيما هو صاعد في الطريق إذا بصبيان صغار خرجوا من المدينة وسخروا منه وقالوا له : اصعد يا أقرع اصعد يا أقرع '),
(5446, '2 Kings', 12, 2, 24, ' فالتفت إلى ورائه ونظر إليهم ولعنهم باسم الرب ، فخرجت دبتان من الوعر وافترستا منهم اثنين وأربعين ولدا '),
(5447, '2 Kings', 12, 2, 25, ' وذهب من هناك إلى جبل الكرمل ، ومن هناك رجع إلى السامرة '),
(5448, '2 Kings', 12, 3, 1, ' وملك يهورام بن أخآب على إسرائيل في السامرة ، في السنة الثامنة عشرة ليهوشافاط ملك يهوذا . ملك اثنتي عشرة سنة '),
(5449, '2 Kings', 12, 3, 2, ' وعمل الشر في عيني الرب ، ولكن ليس كأبيه وأمه ، فإنه أزال تمثال البعل الذي عمله أبوه '),
(5450, '2 Kings', 12, 3, 3, ' إلا أنه لصق بخطايا يربعام بن نباط الذي جعل إسرائيل يخطئ . لم يحد عنها '),
(5451, '2 Kings', 12, 3, 4, ' وكان ميشع ملك موآب صاحب مواش ، فأدى لملك إسرائيل مئة ألف خروف ومئة ألف كبش بصوفها '),
(5452, '2 Kings', 12, 3, 5, ' وعند موت أخآب عصى ملك موآب على ملك إسرائيل '),
(5453, '2 Kings', 12, 3, 6, ' وخرج الملك يهورام في ذلك اليوم من السامرة وعد كل إسرائيل '),
(5454, '2 Kings', 12, 3, 7, ' وذهب وأرسل إلى يهوشافاط ملك يهوذا يقول : قد عصى علي ملك موآب . فهل تذهب معي إلى موآب للحرب ؟  . فقال : أصعد . مثلي مثلك . شعبي كشعبك وخيلي كخيلك '),
(5455, '2 Kings', 12, 3, 8, ' فقال : من أي طريق نصعد ؟  . فقال : من طريق برية أدوم '),
(5456, '2 Kings', 12, 3, 9, ' فذهب ملك إسرائيل وملك يهوذا وملك أدوم وداروا مسيرة سبعة أيام . ولم يكن ماء للجيش والبهائم التي تبعتهم '),
(5457, '2 Kings', 12, 3, 10, ' فقال ملك إسرائيل : آه ، على أن الرب قد دعا هؤلاء الثلاثة الملوك ليدفعهم إلى يد موآب '),
(5458, '2 Kings', 12, 3, 11, ' فقال يهوشافاط : أليس هنا نبي للرب فنسأل الرب به ؟ فأجاب واحد من عبيد ملك إسرائيل وقال : هنا أليشع بن شافاط الذي كان يصب ماء على يدي إيليا '),
(5459, '2 Kings', 12, 3, 12, ' فقال يهوشافاط : عنده كلام الرب . فنزل إليه ملك إسرائيل ويهوشافاط وملك أدوم '),
(5460, '2 Kings', 12, 3, 13, ' فقال أليشع لملك إسرائيل : ما لي ولك اذهب إلى أنبياء أبيك وإلى أنبياء أمك . فقال له ملك إسرائيل : كلا . لأن الرب قد دعا هؤلاء الثلاثة الملوك ليدفعهم إلى يد موآب '),
(5461, '2 Kings', 12, 3, 14, ' فقال أليشع : حي هو رب الجنود الذي أنا واقف أمامه ، إنه لولا أني رافع وجه يهوشافاط ملك يهوذا ، لما كنت أنظر إليك ولا أراك '),
(5462, '2 Kings', 12, 3, 15, ' والآن فأتوني بعواد . ولما ضرب العواد بالعود كانت عليه يد الرب '),
(5463, '2 Kings', 12, 3, 16, ' فقال : هكذا قال الرب : اجعلوا هذا الوادي جبابا جبابا '),
(5464, '2 Kings', 12, 3, 17, ' لأنه هكذا قال الرب : لا ترون ريحا ولا ترون مطرا وهذا الوادي يمتلئ ماء ، فتشربون أنتم وماشيتكم وبهائمكم '),
(5465, '2 Kings', 12, 3, 18, ' وذلك يسير في عيني الرب ، فيدفع موآب إلى أيديكم '),
(5466, '2 Kings', 12, 3, 19, ' فتضربون كل مدينة محصنة ، وكل مدينة مختارة ، وتقطعون كل شجرة طيبة ، وتطمون جميع عيون الماء ، وتفسدون كل حقلة جيدة بالحجارة '),
(5467, '2 Kings', 12, 3, 20, ' وفي الصباح عند إصعاد التقدمة إذا مياه آتية عن طريق أدوم ، فامتلأت الأرض ماء '),
(5468, '2 Kings', 12, 3, 21, ' ولما سمع كل الموآبيين أن الملوك قد صعدوا لمحاربتهم جمعوا كل متقلدي السلاح فما فوق ، ووقفوا على التخم '),
(5469, '2 Kings', 12, 3, 22, ' وبكروا صباحا والشمس أشرقت على المياه ، ورأى الموآبيون مقابلهم المياه حمراء كالدم '),
(5470, '2 Kings', 12, 3, 23, ' فقالوا : هذا دم قد تحارب الملوك وضرب بعضهم بعضا ، والآن فإلى النهب يا موآب '),
(5471, '2 Kings', 12, 3, 24, ' وأتوا إلى محلة إسرائيل ، فقام إسرائيل وضربوا الموآبيين فهربوا من أمامهم ، فدخلوها وهم يضربون الموآبيين '),
(5472, '2 Kings', 12, 3, 25, ' وهدموا المدن ، وكان كل واحد يلقي حجره في كل حقلة جيدة حتى ملأوها ، وطموا جميع عيون الماء وقطعوا كل شجرة طيبة . ولكنهم أبقوا في قير حارسة حجارتها . واستدار أصحاب المقاليع وضربوها '),
(5473, '2 Kings', 12, 3, 26, ' فلما رأى ملك موآب أن الحرب قد اشتدت عليه أخذ معه سبع مئة رجل مستلي السيوف لكي يشقوا إلى ملك أدوم ، فلم يقدروا '),
(5474, '2 Kings', 12, 3, 27, ' فأخذ ابنه البكر الذي كان ملك عوضا عنه ، وأصعده محرقة على السور . فكان غيظ عظيم على إسرائيل . فانصرفوا عنه ورجعوا إلى أرضهم '),
(5475, '2 Kings', 12, 4, 1, ' وصرخت إلى أليشع امرأة من نساء بني الأنبياء قائلة : إن عبدك زوجي قد مات ، وأنت تعلم أن عبدك كان يخاف الرب . فأتى المرابي ليأخذ ولدي له عبدين '),
(5476, '2 Kings', 12, 4, 2, ' فقال لها أليشع : ماذا أصنع لك ؟ أخبريني ماذا لك في البيت ؟  . فقالت : ليس لجاريتك شيء في البيت إلا دهنة زيت '),
(5477, '2 Kings', 12, 9, 1, ' ودعا أليشع النبي واحدا من بني الأنبياء وقال له : شد حقويك وخذ قنينة الدهن هذه بيدك ، واذهب إلى راموت جلعاد '),
(5478, '2 Kings', 12, 9, 2, ' وإذا وصلت إلى هناك فانظر هناك ياهو بن يهوشافاط بن نمشي ، وادخل وأقمه من وسط إخوته ، وادخل به إلى مخدع داخل مخدع '),
(5479, '2 Kings', 12, 9, 3, ' ثم خذ قنينة الدهن وصب على رأسه وقل : هكذا قال الرب : قد مسحتك ملكا على إسرائيل . ثم افتح الباب واهرب ولا تنتظر '),
(5480, '2 Kings', 12, 9, 4, ' فانطلق الغلام ، أي الغلام النبي إلى راموت جلعاد '),
(5481, '2 Kings', 12, 9, 5, ' ودخل وإذا قواد الجيش جلوس . فقال : لي كلام معك يا قائد . فقال ياهو : مع من منا كلنا ؟  . فقال : معك أيها القائد '),
(5482, '2 Kings', 12, 9, 6, ' فقام ودخل البيت ، فصب الدهن على رأسه وقال له : هكذا قال الرب إله إسرائيل : قد مسحتك ملكا على شعب الرب إسرائيل '),
(5483, '2 Kings', 12, 9, 7, ' فتضرب بيت أخآب سيدك . وأنتقم لدماء عبيدي الأنبياء ، ودماء جميع عبيد الرب من يد إيزابل '),
(5484, '2 Kings', 12, 9, 8, ' فيبيد كل بيت أخآب ، وأستأصل لأخآب كل بائل بحائط ومحجوز ومطلق في إسرائيل '),
(5485, '2 Kings', 12, 9, 9, ' وأجعل بيت أخآب كبيت يربعام بن نباط ، وكبيت بعشا بن أخيا '),
(5486, '2 Kings', 12, 9, 10, ' وتأكل الكلاب إيزابل في حقل يزرعيل وليس من يدفنها . ثم فتح الباب وهرب '),
(5487, '2 Kings', 12, 9, 11, ' وأما ياهو فخرج إلى عبيد سيده ، فقيل له : أسلام ؟ لماذا جاء هذا المجنون إليك ؟  . فقال لهم : أنتم تعرفون الرجل وكلامه '),
(5488, '2 Kings', 12, 9, 12, ' فقالوا : كذب . فأخبرنا . فقال : بكذا وكذا كلمني قائلا : هكذا قال الرب : قد مسحتك ملكا على إسرائيل '),
(5489, '2 Kings', 12, 9, 13, ' فبادر كل واحد وأخذ ثوبه ووضعه تحته على الدرج نفسه ، وضربوا بالبوق وقالوا : قد ملك ياهو '),
(5490, '2 Kings', 12, 9, 14, ' وعصى ياهو بن يهوشافاط بن نمشي على يورام . وكان يورام يحافظ على راموت جلعاد هو وكل إسرائيل من حزائيل ملك أرام '),
(5491, '2 Kings', 12, 9, 15, ' ورجع يهورام الملك لكي يبرأ في يزرعيل من الجروح التي ضربه بها الأراميون حين قاتل حزائيل ملك أرام . فقال ياهو : إن كان في أنفسكم ، لا يخرج منهزم من المدينة لكي ينطلق فيخبر في يزرعيل '),
(5492, '2 Kings', 12, 9, 16, ' وركب ياهو وذهب إلى يزرعيل ، لأن يورام كان مضطجعا هناك . ونزل أخزيا ملك يهوذا ليرى يورام '),
(5493, '2 Kings', 12, 9, 17, ' وكان الرقيب واقفا على البرج في يزرعيل ، فرأى جماعة ياهو عند إقباله ، فقال : إني أرى جماعة . فقال يهورام : خذ فارسا وأرسله للقائهم ، فيقول : أسلام '),
(5494, '2 Kings', 12, 9, 18, ' فذهب راكب الفرس للقائه وقال : هكذا يقول الملك : أسلام ؟  . فقال ياهو : ما لك وللسلام ؟ در إلى ورائي . فأخبر الرقيب قائلا : قد وصل الرسول إليهم ولم يرجع '),
(5495, '2 Kings', 12, 9, 19, ' فأرسل راكب فرس ثانيا ، فلما وصل إليهم قال : هكذا يقول الملك : أسلام ؟  . فقال ياهو : ما لك وللسلام ؟ در إلى ورائي '),
(5496, '2 Kings', 12, 9, 20, ' فأخبر الرقيب قائلا : قد وصل إليهم ولم يرجع . والسوق كسوق ياهو بن نمشي ، لأنه يسوق بجنون '),
(5497, '2 Kings', 12, 9, 21, ' فقال يهورام : اشدد . فشدت مركبته ، وخرج يهورام ملك إسرائيل وأخزيا ملك يهوذا ، كل واحد في مركبته ، خرجا للقاء ياهو . فصادفاه عند حقلة نابوت اليزرعيلي '),
(5498, '2 Kings', 12, 9, 22, ' فلما رأى يهورام ياهو قال : أسلام يا ياهو ؟  . فقال : أي سلام ما دام زنى إيزابل أمك وسحرها الكثير '),
(5499, '2 Kings', 12, 9, 23, ' فرد يهورام يديه وهرب ، وقال لأخزيا : خيانة يا أخزيا '),
(5500, '2 Kings', 12, 9, 24, ' فقبض ياهو بيده على القوس وضرب يهورام بين ذراعيه ، فخرج السهم من قلبه فسقط في مركبته '),
(5501, '2 Kings', 12, 9, 25, ' وقال لبدقر ثالثه : ارفعه وألقه في حصة حقل نابوت اليزرعيلي . واذكر كيف إذ ركبت أنا وإياك معا وراء أخآب أبيه ، جعل الرب عليه هذا الحمل '),
(5502, '2 Kings', 12, 9, 26, ' ألم أر أمسا دم نابوت ودماء بنيه ، يقول الرب ، فأجازيك في هذه الحقلة ، يقول الرب . فالآن ارفعه وألقه في الحقلة حسب قول الرب '),
(5503, '2 Kings', 12, 9, 27, ' ولما رأى ذلك أخزيا ملك يهوذا هرب في طريق بيت البستان ، فطارده ياهو وقال : اضربوه . فضربوه أيضا في المركبة في عقبة جور التي عند يبلعام . فهرب إلى مجدو ومات هناك '),
(5504, '2 Kings', 12, 9, 28, ' فأركبه عبيده إلى أورشليم ودفنوه في قبره مع آبائه في مدينة داود '),
(5505, '2 Kings', 12, 9, 29, ' في السنة الحادية عشرة ليورام بن أخآب ، ملك أخزيا على يهوذا '),
(5506, '2 Kings', 12, 9, 30, ' فجاء ياهو إلى يزرعيل . ولما سمعت إيزابل كحلت بالأثمد عينيها ، وزينت رأسها وتطلعت من كوة '),
(5507, '2 Kings', 12, 9, 31, ' وعند دخول ياهو الباب قالت : أسلام لزمري قاتل سيده '),
(5508, '2 Kings', 12, 9, 32, ' فرفع وجهه نحو الكوة وقال : من معي ؟ من ؟  . فأشرف عليه اثنان أو ثلاثة من الخصيان '),
(5509, '2 Kings', 12, 9, 33, ' فقال : اطرحوها . فطرحوها ، فسال من دمها على الحائط وعلى الخيل فداسها '),
(5510, '2 Kings', 12, 9, 34, ' ودخل وأكل وشرب ثم قال : افتقدوا هذه الملعونة وادفنوها ، لأنها بنت ملك '),
(5511, '2 Kings', 12, 9, 35, ' ولما مضوا ليدفنوها ، لم يجدوا منها إلا الجمجمة والرجلين وكفي اليدين '),
(5512, '2 Kings', 12, 9, 36, ' فرجعوا وأخبروه ، فقال : إنه كلام الرب الذي تكلم به عن يد عبده إيليا التشبي قائلا : في حقل يزرعيل تأكل الكلاب لحم إيزابل '),
(5513, '2 Kings', 12, 9, 37, ' وتكون جثة إيزابل كدمنة على وجه الحقل في قسم يزرعيل حتى لا يقولوا : هذه إيزابل '),
(5514, '2 Kings', 12, 10, 1, ' وكان لأخآب سبعون ابنا في السامرة . فكتب ياهو رسائل وأرسلها إلى السامرة ، إلى رؤساء يزرعيل الشيوخ وإلى مربي أخآب ، قائلا '),
(5515, '2 Kings', 12, 10, 2, ' فالآن عند وصول هذه الرسالة إليكم ، إذ عندكم بنو سيدكم ، وعندكم مركبات وخيل ومدينة محصنة وسلاح '),
(5516, '2 Kings', 12, 10, 3, ' انظروا الأفضل والأصلح من بني سيدكم واجعلوه على كرسي أبيه ، وحاربوا عن بيت سيدكم '),
(5517, '2 Kings', 12, 10, 4, ' فخافوا جدا جدا وقالوا : هوذا ملكان لم يقفا أمامه ، فكيف نقف نحن '),
(5518, '2 Kings', 12, 10, 5, ' فأرسل الذي على البيت والذي على المدينة والشيوخ والمربون إلى ياهو قائلين : عبيدك نحن ، وكل ما قلت لنا نفعله . لا نملك أحدا . ما يحسن في عينيك فافعله '),
(5519, '2 Kings', 12, 10, 6, ' فكتب إليهم رسالة ثانية قائلا : إن كنتم لي وسمعتم لقولي ، فخذوا رؤوس الرجال بني سيدكم ، وتعالوا إلي في نحو هذا الوقت غدا إلى يزرعيل . وبنو الملك سبعون رجلا كانوا مع عظماء المدينة الذين ربوهم '),
(5520, '2 Kings', 12, 10, 7, ' فلما وصلت الرسالة إليهم أخذوا بني الملك وقتلوا سبعين رجلا ووضعوا رؤوسهم في سلال وأرسلوها إليه إلى يزرعيل '),
(5521, '2 Kings', 12, 10, 8, ' فجاء الرسول وأخبره قائلا : قد أتوا برؤوس بني الملك . فقال : اجعلوها كومتين في مدخل الباب إلى الصباح '),
(5522, '2 Kings', 12, 10, 9, ' وفي الصباح خرج ووقف وقال لجميع الشعب : أنتم أبرياء . هأنذا قد عصيت على سيدي وقتلته ، ولكن من قتل كل هؤلاء '),
(5523, '2 Kings', 12, 10, 10, ' فاعلموا الآن أنه لا يسقط من كلام الرب إلى الأرض الذي تكلم به الرب على بيت أخآب ، وقد فعل الرب ما تكلم به عن يد عبده إيليا '),
(5524, '2 Kings', 12, 10, 11, ' وقتل ياهو كل الذين بقوا لبيت أخآب في يزرعيل وكل عظمائه ومعارفه وكهنته ، حتى لم يبق له شاردا '),
(5525, '2 Kings', 12, 10, 12, ' ثم قام وجاء سائرا إلى السامرة . وإذ كان عند بيت عقد الرعاة في الطريق '),
(5526, '2 Kings', 12, 10, 13, ' صادف ياهو إخوة أخزيا ملك يهوذا ، فقال : من أنتم ؟  . فقالوا : نحن إخوة أخزيا ، ونحن نازلون لنسلم على بني الملك وبني الملكة '),
(5527, '2 Kings', 12, 10, 14, ' فقال : أمسكوهم أحياء . فأمسكوهم أحياء وقتلوهم عند بئر بيت عقد ، اثنين وأربعين رجلا ولم يبق منهم أحدا '),
(5528, '2 Kings', 12, 10, 15, ' ثم انطلق من هناك فصادف يهوناداب بن ركاب يلاقيه ، فباركه وقال له : هل قلبك مستقيم نظير قلبي مع قلبك ؟  . فقال يهوناداب : نعم ونعم . هات يدك . فأعطاه يده ، فأصعده إليه إلى المركبة '),
(5529, '2 Kings', 12, 10, 16, ' وقال : هلم معي وانظر غيرتي للرب . وأركبه معه في مركبته '),
(5530, '2 Kings', 12, 10, 17, ' وجاء إلى السامرة ، وقتل جميع الذين بقوا لأخآب في السامرة حتى أفناه ، حسب كلام الرب الذي كلم به إيليا '),
(5531, '2 Kings', 12, 10, 18, ' ثم جمع ياهو كل الشعب وقال لهم : إن أخآب قد عبد البعل قليلا ، وأما ياهو فإنه يعبده كثيرا '),
(5532, '2 Kings', 12, 10, 19, ' والآن فادعوا إلي جميع أنبياء البعل وكل عابديه وكل كهنته . لا يفقد أحد ، لأن لي ذبيحة عظيمة للبعل . كل من فقد لا يعيش . وقد فعل ياهو بمكر لكي يفني عبدة البعل '),
(5533, '2 Kings', 12, 10, 20, ' وقال ياهو : قدسوا اعتكافا للبعل . فنادوا به '),
(5534, '2 Kings', 12, 10, 21, ' وأرسل ياهو في كل إسرائيل ، فأتى جميع عبدة البعل ولم يبق أحد إلا أتى ، ودخلوا بيت البعل ، فامتلأ بيت البعل من جانب إلى جانب '),
(5535, '2 Kings', 12, 10, 22, ' فقال للذي على الملابس : أخرج ملابس لكل عبدة البعل . فأخرج لهم ملابس '),
(5536, '2 Kings', 12, 10, 23, ' ودخل ياهو ويهوناداب بن ركاب إلى بيت البعل . فقال لعبدة البعل : فتشوا وانظروا لئلا يكون معكم ههنا أحد من عبيد الرب ، ولكن عبدة البعل وحدهم '),
(5537, '2 Kings', 12, 10, 24, ' ودخلوا ليقربوا ذبائح ومحرقات . وأما ياهو فأقام خارجا ثمانين رجلا وقال : الرجل الذي ينجو من الرجال الذين أتيت بهم إلى أيديكم تكون أنفسكم بدل نفسه '),
(5538, '2 Kings', 12, 10, 25, ' ولما انتهوا من تقريب المحرقة قال ياهو للسعاة والثوالث : ادخلوا اضربوهم . لا يخرج أحد . فضربوهم بحد السيف ، وطرحهم السعاة والثوالث . وساروا إلى مدينة بيت البعل '),
(5539, '2 Kings', 12, 10, 26, ' وأخرجوا تماثيل بيت البعل وأحرقوها '),
(5540, '2 Kings', 12, 10, 27, ' وكسروا تمثال البعل ، وهدموا بيت البعل ، وجعلوه مزبلة إلى هذا اليوم '),
(5541, '2 Kings', 12, 10, 28, ' واستأصل ياهو البعل من إسرائيل '),
(5542, '2 Kings', 12, 10, 29, ' ولكن خطايا يربعام بن نباط الذي جعل إسرائيل يخطئ لم يحد ياهو عنها ، أي عجول الذهب التي في بيت إيل والتي في دان '),
(5543, '2 Kings', 12, 10, 30, ' وقال الرب لياهو : من أجل أنك قد أحسنت بعمل ما هو مستقيم في عيني ، وحسب كل ما بقلبي فعلت ببيت أخآب ، فأبناؤك إلى الجيل الرابع يجلسون على كرسي إسرائيل '),
(5544, '2 Kings', 12, 10, 31, ' ولكن ياهو لم يتحفظ للسلوك في شريعة الرب إله إسرائيل من كل قلبه . لم يحد عن خطايا يربعام الذي جعل إسرائيل يخطئ '),
(5545, '2 Kings', 12, 10, 32, ' في تلك الأيام ابتدأ الرب يقص إسرائيل ، فضربهم حزائيل في جميع تخوم إسرائيل '),
(5546, '2 Kings', 12, 10, 33, ' من الأردن لجهة مشرق الشمس ، جميع أرض جلعاد الجاديين والرأوبينيين والمنسيين ، من عروعير التي على وادي أرنون وجلعاد وباشان '),
(5547, '2 Kings', 12, 10, 34, ' وبقية أمور ياهو وكل ما عمل وكل جبروته ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5548, '2 Kings', 12, 10, 35, ' واضطجع ياهو مع آبائه فدفنوه في السامرة ، وملك يهوأحاز ابنه عوضا عنه '),
(5549, '2 Kings', 12, 10, 36, ' وكانت الأيام التي ملك فيها ياهو على إسرائيل في السامرة ثمانيا وعشرين سنة '),
(5550, '2 Kings', 12, 11, 1, ' فلما رأت عثليا أم أخزيا ، أن ابنها قد مات ، قامت فأبادت جميع النسل الملكي '),
(5551, '2 Kings', 12, 6, 8, ' وأما ملك أرام فكان يحارب إسرائيل ، وتآمر مع عبيده قائلا : في المكان الفلاني تكون محلتي '),
(5552, '2 Kings', 12, 6, 9, ' فأرسل رجل الله إلى ملك إسرائيل يقول : احذر من أن تعبر بهذا الموضع ، لأن الأراميين حالون هناك '),
(5553, '2 Kings', 12, 6, 10, ' فأرسل ملك إسرائيل إلى الموضع الذي قال له عنه رجل الله وحذره منه وتحفظ هناك ، لا مرة ولا مرتين '),
(5554, '2 Kings', 12, 6, 11, ' فاضطرب قلب ملك أرام من هذا الأمر ، ودعا عبيده وقال لهم : أما تخبرونني من منا هو لملك إسرائيل '),
(5555, '2 Kings', 12, 6, 12, ' فقال واحد من عبيده : ليس هكذا يا سيدي الملك . ولكن أليشع النبي الذي في إسرائيل ، يخبر ملك إسرائيل بالأمور التي تتكلم بها في مخدع مضطجعك '),
(5556, '2 Kings', 12, 6, 13, ' فقال : اذهبوا وانظروا أين هو ، فأرسل وآخذه . فأخبر وقيل له : هوذا هو في دوثان '),
(5557, '2 Kings', 12, 6, 14, ' فأرسل إلى هناك خيلا ومركبات وجيشا ثقيلا ، وجاءوا ليلا وأحاطوا بالمدينة '),
(5558, '2 Kings', 12, 6, 15, ' فبكر خادم رجل الله وقام وخرج ، وإذا جيش محيط بالمدينة وخيل ومركبات . فقال غلامه له : آه يا سيدي كيف نعمل '),
(5559, '2 Kings', 12, 6, 16, ' فقال : لا تخف ، لأن الذين معنا أكثر من الذين معهم '),
(5560, '2 Kings', 12, 6, 17, ' وصلى أليشع وقال : يارب ، افتح عينيه فيبصر . ففتح الرب عيني الغلام فأبصر ، وإذا الجبل مملوء خيلا ومركبات نار حول أليشع '),
(5561, '2 Kings', 12, 6, 18, ' ولما نزلوا إليه صلى أليشع إلى الرب وقال : اضرب هؤلاء الأمم بالعمى . فضربهم بالعمى كقول أليشع '),
(5562, '2 Kings', 12, 6, 19, ' فقال لهم أليشع : ليست هذه هي الطريق ، ولا هذه هي المدينة . اتبعوني فأسير بكم إلى الرجل الذي تفتشون عليه . فسار بهم إلى السامرة '),
(5563, '2 Kings', 12, 6, 20, ' فلما دخلوا السامرة قال أليشع : يارب ، افتح أعين هؤلاء فيبصروا . ففتح الرب أعينهم فأبصروا وإذا هم في وسط السامرة '),
(5564, '2 Kings', 12, 6, 21, ' فقال ملك إسرائيل لأليشع لما رآهم : هل أضرب ؟ هل أضرب يا أبي '),
(5565, '2 Kings', 12, 6, 22, ' فقال : لا تضرب . تضرب الذين سبيتهم بسيفك وبقوسك . ضع خبزا وماء أمامهم فيأكلوا ويشربوا ، ثم ينطلقوا إلى سيدهم '),
(5566, '2 Kings', 12, 6, 23, ' فأولم لهم وليمة عظيمة فأكلوا وشربوا ، ثم أطلقهم فانطلقوا إلى سيدهم . ولم تعد أيضا جيوش أرام تدخل إلى أرض إسرائيل '),
(5567, '2 Kings', 12, 6, 24, ' وكان بعد ذلك أن بنهدد ملك أرام جمع كل جيشه وصعد فحاصر السامرة '),
(5568, '2 Kings', 12, 6, 25, ' وكان جوع شديد في السامرة . وهم حاصروها حتى صار رأس الحمار بثمانين من الفضة ، وربع القاب من زبل الحمام بخمس من الفضة '),
(5569, '2 Kings', 12, 6, 26, ' وبينما كان ملك إسرائيل جائزا على السور صرخت امرأة إليه تقول : خلص يا سيدي الملك '),
(5570, '2 Kings', 12, 6, 27, ' فقال : لا يخلصك الرب . من أين أخلصك ؟ أمن البيدر أو من المعصرة '),
(5571, '2 Kings', 12, 6, 28, ' ثم قال لها الملك : ما لك ؟  . فقالت : إن هذه المرأة قد قالت لي : هاتي ابنك فنأكله اليوم ثم ، نأكل ابني غدا '),
(5572, '2 Kings', 12, 6, 29, ' فسلقنا ابني وأكلناه . ثم قلت لها في اليوم الآخر : هاتي ابنك فنأكله فخبأت ابنها '),
(5573, '2 Kings', 12, 6, 30, ' فلما سمع الملك كلام المرأة مزق ثيابه وهو مجتاز على السور ، فنظر الشعب وإذا مسح من داخل على جسده '),
(5574, '2 Kings', 12, 6, 31, ' فقال : هكذا يصنع لي الله وهكذا يزيد ، إن قام رأس أليشع بن شافاط عليه اليوم '),
(5575, '2 Kings', 12, 6, 32, ' وكان أليشع جالسا في بيته والشيوخ جلوسا عنده . فأرسل رجلا من أمامه . وقبلما أتى الرسول إليه قال للشيوخ : هل رأيتم أن ابن القاتل هذا قد أرسل لكي يقطع رأسي ؟ انظروا إذا جاء الرسول فأغلقوا الباب واحصروه عند الباب . أليس صوت قدمي سيده وراءه '),
(5576, '2 Kings', 12, 6, 33, ' وبينما هو يكلمهم إذا بالرسول نازل إليه . فقال : هوذا هذا الشر هو من قبل الرب . ماذا أنتظر من الرب بعد '),
(5577, '2 Kings', 12, 7, 1, ' وقال أليشع : اسمعوا كلام الرب . هكذا قال الرب : في مثل هذا الوقت غدا تكون كيلة الدقيق بشاقل ، وكيلتا الشعير بشاقل في باب السامرة '),
(5578, '2 Kings', 12, 7, 2, ' وإن جنديا للملك كان يستند على يده أجاب رجل الله وقال : هوذا الرب يصنع كوى في السماء هل يكون هذا الأمر ؟  . فقال : إنك ترى بعينيك ، ولكن لا تأكل منه '),
(5579, '2 Kings', 12, 7, 3, ' وكان أربعة رجال برص عند مدخل الباب ، فقال أحدهم لصاحبه : لماذا نحن جالسون هنا حتى نموت '),
(5580, '2 Kings', 12, 7, 4, ' إذا قلنا : ندخل المدينة ، فالجوع في المدينة فنموت فيها . وإذا جلسنا هنا نموت . فالآن هلم نسقط إلى محلة الأراميين ، فإن استحيونا حيينا ، وإن قتلونا متنا '),
(5581, '2 Kings', 12, 7, 5, ' فقاموا في العشاء ليذهبوا إلى محلة الأراميين . فجاءوا إلى آخر محلة الأراميين فلم يكن هناك أحد '),
(5582, '2 Kings', 12, 7, 6, ' فإن الرب أسمع جيش الأراميين صوت مركبات وصوت خيل ، صوت جيش عظيم . فقالوا الواحد لأخيه : هوذا ملك إسرائيل قد استأجر ضدنا ملوك الحثيين وملوك المصريين ليأتوا علينا '),
(5583, '2 Kings', 12, 7, 7, ' فقاموا وهربوا في العشاء وتركوا خيامهم وخيلهم وحميرهم ، المحلة كما هي ، وهربوا لأجل نجاة أنفسهم '),
(5584, '2 Kings', 12, 7, 8, ' وجاء هؤلاء البرص إلى آخر المحلة ودخلوا خيمة واحدة ، فأكلوا وشربوا وحملوا منها فضة وذهبا وثيابا ومضوا وطمروها . ثم رجعوا ودخلوا خيمة أخرى وحملوا منها ومضوا وطمروا '),
(5585, '2 Kings', 12, 7, 9, ' ثم قال بعضهم لبعض : لسنا عاملين حسنا . هذا اليوم هو يوم بشارة ونحن ساكتون ، فإن انتظرنا إلى ضوء الصباح يصادفنا شر . فهلم الآن ندخل ونخبر بيت الملك '),
(5586, '2 Kings', 12, 7, 10, ' فجاءوا ودعوا بواب المدينة وأخبروه قائلين : إننا دخلنا محلة الأراميين فلم يكن هناك أحد ولا صوت إنسان ، ولكن خيل مربوطة وحمير مربوطة وخيام كما هي '),
(5587, '2 Kings', 12, 7, 11, ' فدعا البوابين فأخبروا بيت الملك داخلا '),
(5588, '2 Kings', 12, 7, 12, ' فقام الملك ليلا وقال لعبيده : لأخبرنكم ما فعل لنا الأراميون . علموا أننا جياع فخرجوا من المحلة ليختبئوا في حقل قائلين : إذا خرجوا من المدينة قبضنا عليهم أحياء ودخلنا المدينة '),
(5589, '2 Kings', 12, 7, 13, ' فأجاب واحد من عبيده وقال : فليأخذوا خمسة من الخيل الباقية التي بقيت فيها . هي نظير كل جمهور إسرائيل الذين بقوا بها ، أو هي نظير كل جمهور إسرائيل الذين فنوا . فنرسل ونرى '),
(5590, '2 Kings', 12, 7, 14, ' فأخذوا مركبتي خيل . وأرسل الملك وراء جيش الأراميين قائلا : اذهبوا وانظروا '),
(5591, '2 Kings', 12, 7, 15, ' فانطلقوا وراءهم إلى الأردن ، وإذا كل الطريق ملآن ثيابا وآنية قد طرحها الأراميون من عجلتهم . فرجع الرسل وأخبروا الملك '),
(5592, '2 Kings', 12, 7, 16, ' فخرج الشعب ونهبوا محلة الأراميين . فكانت كيلة الدقيق بشاقل ، وكيلتا الشعير بشاقل حسب كلام الرب '),
(5593, '2 Kings', 12, 7, 17, ' وأقام الملك على الباب الجندي الذي كان يستند على يده ، فداسه الشعب في الباب ، فمات كما قال رجل الله الذي تكلم عند نزول الملك إليه '),
(5594, '2 Kings', 12, 7, 18, ' فإنه لما تكلم رجل الله إلى الملك قائلا : كيلتا شعير بشاقل وكيلة دقيق بشاقل تكون في مثل هذا الوقت غدا في باب السامرة '),
(5595, '2 Kings', 12, 7, 19, ' وأجاب الجندي رجل الله وقال : هوذا الرب يصنع كوى في السماء هل يكون مثل هذا الأمر ؟  . قال : إنك ترى بعينيك ولكنك لا تأكل منه '),
(5596, '2 Kings', 12, 7, 20, ' فكان له كذلك . داسه الشعب في الباب فمات '),
(5597, '2 Kings', 12, 8, 1, ' وكلم أليشع المرأة التي أحيا ابنها قائلا : قومي وانطلقي أنت وبيتك وتغربي حيثما تتغربي ، لأن الرب قد دعا بجوع فيأتي أيضا على الأرض سبع سنين '),
(5598, '2 Kings', 12, 8, 2, ' فقامت المرأة وفعلت حسب كلام رجل الله ، وانطلقت هي وبيتها وتغربت في أرض الفلسطينيين سبع سنين '),
(5599, '2 Kings', 12, 8, 3, ' وفي نهاية السنين السبع رجعت المرأة من أرض الفلسطينيين ، وخرجت لتصرخ إلى الملك لأجل بيتها وحقلها '),
(5600, '2 Kings', 12, 8, 4, ' وكلم الملك جيحزي غلام رجل الله قائلا : قص علي جميع العظائم التي فعلها أليشع '),
(5601, '2 Kings', 12, 8, 5, ' وفيما هو يقص على الملك كيف أنه أحيا الميت ، إذا بالمرأة التي أحيا ابنها تصرخ إلى الملك لأجل بيتها ولأجل حقلها . فقال جيحزي : يا سيدي الملك ، هذه هي المرأة وهذا هو ابنها الذي أحياه أليشع '),
(5602, '2 Kings', 12, 8, 6, ' فسأل الملك المرأة فقصت عليه ذلك ، فأعطاها الملك خصيا قائلا : أرجع كل ما لها وجميع غلات الحقل من حين تركت الأرض إلى الآن '),
(5603, '2 Kings', 12, 8, 7, ' وجاء أليشع إلى دمشق . وكان بنهدد ملك أرام مريضا ، فأخبر وقيل له : قد جاء رجل الله إلى هنا '),
(5604, '2 Kings', 12, 8, 8, ' فقال الملك لحزائيل : خذ بيدك هدية واذهب لاستقبال رجل الله ، واسأل الرب به قائلا : هل أشفى من مرضي هذا '),
(5605, '2 Kings', 12, 8, 9, ' فذهب حزائيل لاستقباله وأخذ هدية بيده ، ومن كل خيرات دمشق حمل أربعين جملا ، وجاء ووقف أمامه وقال : إن ابنك بنهدد ملك أرام قد أرسلني إليك قائلا : هل أشفى من مرضي هذا '),
(5606, '2 Kings', 12, 8, 10, ' فقال له أليشع : اذهب وقل له : شفاء تشفى . وقد أراني الرب أنه يموت موتا '),
(5607, '2 Kings', 12, 8, 11, ' فجعل نظره عليه وثبته حتى خجل ، فبكى رجل الله '),
(5608, '2 Kings', 12, 8, 12, ' فقال حزائيل : لماذا يبكي سيدي ؟  . فقال : لأني علمت ما ستفعله ببني إسرائيل من الشر ، فإنك تطلق النار في حصونهم ، وتقتل شبانهم بالسيف ، وتحطم أطفالهم ، وتشق حواملهم '),
(5609, '2 Kings', 12, 8, 13, ' فقال حزائيل : ومن هو عبدك الكلب حتى يفعل هذا الأمر العظيم ؟  . فقال أليشع : قد أراني الرب إياك ملكا على أرام '),
(5610, '2 Kings', 12, 8, 14, ' فانطلق من عند أليشع ودخل إلى سيده فقال له : ماذا قال لك أليشع ؟  . فقال : قال لي إنك تحيا '),
(5611, '2 Kings', 12, 8, 15, ' وفي الغد أخذ اللبدة وغمسها بالماء ، ونشرها على وجهه ومات ، وملك حزائيل عوضا عنه '),
(5612, '2 Kings', 12, 8, 16, ' وفي السنة الخامسة ليورام بن أخآب ملك إسرائيل ويهوشافاط ملك يهوذا ، ملك يهورام بن يهوشافاط ملك يهوذا '),
(5613, '2 Kings', 12, 8, 17, ' كان ابن اثنتين وثلاثين سنة حين ملك ، وملك ثماني سنين في أورشليم '),
(5614, '2 Kings', 12, 8, 18, ' وسار في طريق ملوك إسرائيل كما فعل بيت أخآب ، لأن بنت أخآب كانت له امرأة ، وعمل الشر في عيني الرب '),
(5615, '2 Kings', 12, 8, 19, ' ولم يشإ الرب أن يبيد يهوذا من أجل داود عبده ، كما قال إنه يعطيه سراجا ولبنيه كل الأيام '),
(5616, '2 Kings', 12, 8, 20, ' في أيامه عصى أدوم من تحت يد يهوذا وملكوا على أنفسهم ملكا '),
(5617, '2 Kings', 12, 8, 21, ' وعبر يورام إلى صعير وجميع المركبات معه ، وقام ليلا وضرب أدوم المحيط به ورؤساء المركبات . وهرب الشعب إلى خيامهم '),
(5618, '2 Kings', 12, 8, 22, ' وعصى أدوم من تحت يد يهوذا إلى هذا اليوم . حينئذ عصت لبنة في ذلك الوقت '),
(5619, '2 Kings', 12, 8, 23, ' وبقية أمور يورام وكل ما صنع ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5620, '2 Kings', 12, 8, 24, ' واضطجع يورام مع آبائه ، ودفن مع آبائه في مدينة داود ، وملك أخزيا ابنه عوضا عنه '),
(5621, '2 Kings', 12, 8, 25, ' في السنة الثانية عشرة ليورام بن أخآب ملك إسرائيل ، ملك أخزيا بن يهورام ملك يهوذا '),
(5622, '2 Kings', 12, 8, 26, ' وكان أخزيا ابن اثنتين وعشرين سنة حين ملك ، وملك سنة واحدة في أورشليم ، واسم أمه عثليا بنت عمري ملك إسرائيل '),
(5623, '2 Kings', 12, 8, 27, ' وسار في طريق بيت أخآب ، وعمل الشر في عيني الرب كبيت أخآب ، لأنه كان صهر بيت أخآب '),
(5624, '2 Kings', 12, 8, 28, ' وانطلق مع يورام بن أخآب لمقاتلة حزائيل ملك أرام في راموت جلعاد ، فضرب الأراميون يورام '),
(5625, '2 Kings', 12, 8, 29, ' فرجع يورام الملك ليبرأ في يزرعيل من الجروح التي جرحه بها الأراميون في راموت عند مقاتلته حزائيل ملك أرام . ونزل أخزيا بن يهورام ملك يهوذا ليرى يورام بن أخآب في يزرعيل لأنه كان مريضا '),
(5626, '2 Kings', 12, 11, 2, ' فأخذت يهوشبع بنت الملك يورام ، أخت أخزيا ، يوآش بن أخزيا وسرقته من وسط بني الملك الذين قتلوا ، هو ومرضعته من مخدع السرير ، وخبأوه من وجه عثليا فلم يقتل '),
(5627, '2 Kings', 12, 11, 3, ' وكان معها في بيت الرب مختبئا ست سنين . وعثليا مالكة على الأرض '),
(5628, '2 Kings', 12, 11, 4, ' وفي السنة السابعة أرسل يهوياداع فأخذ رؤساء مئات الجلادين والسعاة ، وأدخلهم إليه ، إلى بيت الرب ، وقطع معهم عهدا واستحلفهم في بيت الرب وأراهم ابن الملك '),
(5629, '2 Kings', 12, 11, 5, ' وأمرهم قائلا : هذا ما تفعلونه : الثلث منكم الذين يدخلون في السبت يحرسون حراسة بيت الملك '),
(5630, '2 Kings', 12, 11, 6, ' والثلث على باب سور ، والثلث على الباب وراء السعاة . فتحرسون حراسة البيت للصد '),
(5631, '2 Kings', 12, 11, 7, ' والفرقتان منكم ، جميع الخارجين في السبت ، يحرسون حراسة بيت الرب حول الملك '),
(5632, '2 Kings', 12, 11, 8, ' وتحيطون بالملك حواليه ، كل واحد سلاحه بيده . ومن دخل الصفوف يقتل . وكونوا مع الملك في خروجه ودخوله '),
(5633, '2 Kings', 12, 11, 9, ' ففعل رؤساء المئات حسب كل ما أمر به يهوياداع الكاهن ، وأخذوا كل واحد رجاله الداخلين في السبت مع الخارجين في السبت ، وجاءوا إلى يهوياداع الكاهن '),
(5634, '2 Kings', 12, 11, 10, ' فأعطى الكاهن لرؤساء المئات الحراب والأتراس التي للملك داود التي في بيت الرب '),
(5635, '2 Kings', 12, 11, 11, ' ووقف السعاة كل واحد سلاحه بيده من جانب البيت الأيمن إلى جانب البيت الأيسر حول المذبح والبيت ، حول الملك مستديرين '),
(5636, '2 Kings', 12, 11, 12, ' وأخرج ابن الملك ووضع عليه التاج وأعطاه الشهادة ، فملكوه ومسحوه وصفقوا وقالوا : ليحي الملك '),
(5637, '2 Kings', 12, 11, 13, ' ولما سمعت عثليا صوت السعاة والشعب ، دخلت إلى الشعب إلى بيت الرب '),
(5638, '2 Kings', 12, 11, 14, ' ونظرت وإذا الملك واقف على المنبر حسب العادة ، والرؤساء ونافخو الأبواق بجانب الملك ، وكل شعب الأرض يفرحون ويضربون بالأبواق . فشقت عثليا ثيابها وصرخت : خيانة ، خيانة '),
(5639, '2 Kings', 12, 11, 15, ' فأمر يهوياداع الكاهن رؤساء المئات ، قواد الجيش وقال لهم : أخرجوها إلى خارج الصفوف ، والذي يتبعها اقتلوه بالسيف . لأن الكاهن قال : لا تقتل في بيت الرب '),
(5640, '2 Kings', 12, 11, 16, ' فألقوا عليها الأيادي ، ومضت في طريق مدخل الخيل إلى بيت الملك ، وقتلت هناك '),
(5641, '2 Kings', 12, 11, 17, ' وقطع يهوياداع عهدا بين الرب وبين الملك والشعب ليكونوا شعبا للرب ، وبين الملك والشعب '),
(5642, '2 Kings', 12, 11, 18, ' ودخل جميع شعب الأرض إلى بيت البعل وهدموا مذابحه وكسروا تماثيله تماما ، وقتلوا متان كاهن البعل أمام المذابح . وجعل الكاهن نظارا على بيت الرب '),
(5643, '2 Kings', 12, 11, 19, ' وأخذ رؤساء المئات والجلادين والسعاة وكل شعب الأرض ، فأنزلوا الملك من بيت الرب وأتوا في طريق باب السعاة إلى بيت الملك ، فجلس على كرسي الملوك '),
(5644, '2 Kings', 12, 11, 20, ' وفرح جميع شعب الأرض ، واستراحت المدينة . وقتلوا عثليا بالسيف عند بيت الملك '),
(5645, '2 Kings', 12, 11, 21, ' كان يهوآش ابن سبع سنين حين ملك '),
(5646, '2 Kings', 12, 12, 1, ' في السنة السابعة لياهو ، ملك يهوآش . ملك أربعين سنة في أورشليم ، واسم أمه ظبية من بئر سبع '),
(5647, '2 Kings', 12, 12, 2, ' وعمل يهوآش ما هو مستقيم في عيني الرب كل أيامه التي فيها علمه يهوياداع الكاهن '),
(5648, '2 Kings', 12, 12, 3, ' إلا أن المرتفعات لم تنتزع ، بل كان الشعب لا يزالون يذبحون ويوقدون على المرتفعات '),
(5649, '2 Kings', 12, 12, 4, ' وقال يهوآش للكهنة : جميع فضة الأقداس التي أدخلت إلى بيت الرب ، الفضة الرائجة ، فضة كل واحد حسب النفوس المقومة ، كل فضة يخطر ببال إنسان أن يدخلها إلى بيت الرب '),
(5650, '2 Kings', 12, 12, 5, ' ليأخذها الكهنة لأنفسهم كل واحد من عند صاحبه ، وهم يرممون ما تهدم من البيت ، كل ما وجد فيه متهدما '),
(5651, '2 Kings', 12, 12, 6, ' وفي السنة الثالثة والعشرين للملك يهوآش لم تكن الكهنة رمموا ما تهدم من البيت '),
(5652, '2 Kings', 12, 12, 7, ' فدعا الملك يهوآش يهوياداع الكاهن والكهنة وقال لهم : لماذا لم ترمموا ما تهدم من البيت ؟ فالآن لا تأخذوا فضة من عند أصحابكم ، بل اجعلوها لما تهدم من البيت '),
(5653, '2 Kings', 12, 12, 8, ' فوافق الكهنة على أن لا يأخذوا فضة من الشعب ، ولا يرمموا ما تهدم من البيت '),
(5654, '2 Kings', 12, 12, 9, ' فأخذ يهوياداع الكاهن صندوقا وثقب ثقبا في غطائه ، وجعله بجانب المذبح عن اليمين عند دخول الإنسان إلى بيت الرب . والكهنة حارسو الباب جعلوا فيه كل الفضة المدخلة إلى بيت الرب '),
(5655, '2 Kings', 12, 12, 10, ' وكان لما رأوا الفضة قد كثرت في الصندوق ، أنه صعد كاتب الملك والكاهن العظيم وصروا وحسبوا الفضة الموجودة في بيت الرب '),
(5656, '2 Kings', 12, 12, 11, ' ودفعوا الفضة المحسوبة إلى أيدي عاملي الشغل الموكلين على بيت الرب ، وأنفقوها للنجارين والبنائين العاملين في بيت الرب '),
(5657, '2 Kings', 12, 12, 12, ' ولبنائي الحيطان ونحاتي الحجارة ، ولشراء الأخشاب والحجارة المنحوتة لترميم ما تهدم من بيت الرب ، ولكل ما ينفق على البيت لترميمه '),
(5658, '2 Kings', 12, 12, 13, ' إلا أنه لم يعمل لبيت الرب طسوس فضة ولا مقصات ولا مناضح ولا أبواق ، كل آنية الذهب وآنية الفضة ، من الفضة الداخلة إلى بيت الرب '),
(5659, '2 Kings', 12, 12, 14, ' بل كانوا يدفعونها لعاملي الشغل ، فكانوا يرممون بها بيت الرب '),
(5660, '2 Kings', 12, 12, 15, ' ولم يحاسبوا الرجال الذين سلموهم الفضة بأيديهم لكي يعطوها لعاملي الشغل ، لأنهم كانوا يعملون بأمانة '),
(5661, '2 Kings', 12, 12, 16, ' وأما فضة ذبيحة الإثم وفضة ذبيحة الخطية فلم تدخل إلى بيت الرب ، بل كانت للكهنة '),
(5662, '2 Kings', 12, 12, 17, ' حينئذ صعد حزائيل ملك أرام وحارب جت وأخذها ، ثم حول حزائيل وجهه ليصعد إلى أورشليم '),
(5663, '2 Kings', 12, 12, 18, ' فأخذ يهوآش ملك يهوذا جميع الأقداس التي قدسها يهوشافاط ويهورام وأخزيا آباؤه ملوك يهوذا ، وأقداسه وكل الذهب الموجود في خزائن بيت الرب وبيت الملك ، وأرسلها إلى حزائيل ملك أرام فصعد عن أورشليم '),
(5664, '2 Kings', 12, 12, 19, ' وبقية أمور يوآش وكل ما عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5665, '2 Kings', 12, 12, 20, ' وقام عبيده وفتنوا فتنة وقتلوا يوآش في بيت القلعة حيث ينزل إلى سلى '),
(5666, '2 Kings', 12, 12, 21, ' لأن يوزاكار بن شمعة ويهوزاباد بن شومير عبديه ضرباه فمات ، فدفنوه مع آبائه في مدينة داود ، وملك أمصيا ابنه عوضا عنه '),
(5667, '2 Kings', 12, 13, 1, ' في السنة الثالثة والعشرين ليوآش بن أخزيا ملك يهوذا ، ملك يهوأحاز بن ياهو على إسرائيل في السامرة سبع عشرة سنة '),
(5668, '2 Kings', 12, 13, 2, ' وعمل الشر في عيني الرب ، وسار وراء خطايا يربعام بن نباط الذي جعل إسرائيل يخطئ . لم يحد عنها '),
(5669, '2 Kings', 12, 13, 3, ' فحمي غضب الرب على إسرائيل ، فدفعهم ليد حزائيل ملك أرام ، وليد بنهدد بن حزائيل كل الأيام '),
(5670, '2 Kings', 12, 13, 4, ' وتضرع يهوأحاز إلى وجه الرب ، فسمع له الرب لأنه رأى ضيق إسرائيل ، لأن ملك أرام ضايقهم '),
(5671, '2 Kings', 12, 13, 5, ' وأعطى الرب إسرائيل مخلصا ، فخرجوا من تحت يد الأراميين . وأقام بنو إسرائيل في خيامهم كأمس وما قبله '),
(5672, '2 Kings', 12, 13, 6, ' ولكنهم لم يحيدوا عن خطايا بيت يربعام الذي جعل إسرائيل يخطئ ، بل ساروا بها . ووقفت السارية أيضا في السامرة '),
(5673, '2 Kings', 12, 13, 7, ' لأنه لم يبق ليهوأحاز شعبا إلا خمسين فارسا وعشر مركبات وعشرة آلاف راجل ، لأن ملك أرام أفناهم ووضعهم كالتراب للدوس '),
(5674, '2 Kings', 12, 13, 8, ' وبقية أمور يهوأحاز وكل ما عمل وجبروته ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5675, '2 Kings', 12, 13, 9, ' ثم اضطجع يهوأحاز مع آبائه ، فدفنوه في السامرة ، وملك يوآش ابنه عوضا عنه '),
(5676, '2 Kings', 12, 13, 10, ' في السنة السابعة والثلاثين ليوآش ملك يهوذا ، ملك يهوآش بن يهوأحاز على إسرائيل في السامرة ست عشرة سنة '),
(5677, '2 Kings', 12, 13, 11, ' وعمل الشر في عيني الرب ، ولم يحد عن جميع خطايا يربعام بن نباط الذي جعل إسرائيل يخطئ ، بل سار بها '),
(5678, '2 Kings', 12, 13, 12, ' وبقية أمور يوآش وكل ما عمل وجبروته وكيف حارب أمصيا ملك يهوذا ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5679, '2 Kings', 12, 13, 13, ' ثم اضطجع يوآش مع آبائه ، وجلس يربعام على كرسيه . ودفن يوآش في السامرة مع ملوك إسرائيل '),
(5680, '2 Kings', 12, 13, 14, ' ومرض أليشع مرضه الذي مات به ، فنزل إليه يوآش ملك إسرائيل ، وبكى على وجهه وقال : يا أبي ، يا أبي ، يا مركبة إسرائيل وفرسانها '),
(5681, '2 Kings', 12, 13, 15, ' فقال له أليشع : خذ قوسا وسهاما . فأخذ لنفسه قوسا وسهاما '),
(5682, '2 Kings', 12, 13, 16, ' ثم قال لملك إسرائيل : ركب يدك على القوس . فركب يده ، ثم وضع أليشع يده على يدي الملك '),
(5683, '2 Kings', 12, 13, 17, ' وقال : افتح الكوة لجهة الشرق . ففتحها . فقال أليشع : ارم . فرمى . فقال : سهم خلاص للرب وسهم خلاص من أرام ، فإنك تضرب أرام في أفيق إلى الفناء '),
(5684, '2 Kings', 12, 13, 18, ' ثم قال : خذ السهام . فأخذها . ثم قال لملك إسرائيل : اضرب على الأرض . فضرب ثلاث مرات ووقف '),
(5685, '2 Kings', 12, 13, 19, ' فغضب عليه رجل الله وقال : لو ضربت خمس أو ست مرات ، حينئذ ضربت أرام إلى الفناء . وأما الآن فإنك إنما تضرب أرام ثلاث مرات '),
(5686, '2 Kings', 12, 13, 20, ' ومات أليشع فدفنوه . وكان غزاة موآب تدخل على الأرض عند دخول السنة '),
(5687, '2 Kings', 12, 13, 21, ' وفيما كانوا يدفنون رجلا إذا بهم قد رأوا الغزاة ، فطرحوا الرجل في قبر أليشع ، فلما نزل الرجل ومس عظام أليشع عاش وقام على رجليه '),
(5688, '2 Kings', 12, 13, 22, ' وأما حزائيل ملك أرام فضايق إسرائيل كل أيام يهوأحاز '),
(5689, '2 Kings', 12, 13, 23, ' فحن الرب عليهم ورحمهم والتفت إليهم لأجل عهده مع إبراهيم وإسحاق ويعقوب ، ولم يشأ أن يستأصلهم ، ولم يطرحهم عن وجهه حتى الآن '),
(5690, '2 Kings', 12, 13, 24, ' ثم مات حزائيل ملك أرام ، وملك بنهدد ابنه عوضا عنه '),
(5691, '2 Kings', 12, 13, 25, ' فعاد يهوآش بن يهوأحاز وأخذ المدن من يد بنهدد بن حزائيل التي أخذها من يد يهوأحاز أبيه بالحرب . ضربه يوآش ثلاث مرات واسترد مدن إسرائيل '),
(5692, '2 Kings', 12, 14, 1, ' في السنة الثانية ليوآش بن يوأحاز ملك إسرائيل ، ملك أمصيا بن يوآش ملك يهوذا '),
(5693, '2 Kings', 12, 14, 2, ' كان ابن خمس وعشرين سنة حين ملك ، وملك تسعا وعشرين سنة في أورشليم ، واسم أمه يهوعدان من أورشليم '),
(5694, '2 Kings', 12, 14, 3, ' وعمل ما هو مستقيم في عيني الرب ، ولكن ليس كداود أبيه ، عمل حسب كل ما عمل يوآش أبوه '),
(5695, '2 Kings', 12, 14, 4, ' إلا أن المرتفعات لم تنتزع ، بل كان الشعب لا يزالون يذبحون ويوقدون على المرتفعات '),
(5696, '2 Kings', 12, 14, 5, ' ولما تثبتت المملكة بيده ، قتل عبيده الذين قتلوا الملك أباه '),
(5697, '2 Kings', 12, 14, 6, ' ولكنه لم يقتل أبناء القاتلين ، حسب ما هو مكتوب في سفر شريعة موسى ، حيث أمر الرب قائلا : لا يقتل الآباء من أجل البنين ، والبنون لا يقتلون من أجل الآباء . إنما كل إنسان يقتل بخطيته '),
(5698, '2 Kings', 12, 14, 7, ' هو قتل من أدوم في وادي الملح عشرة آلاف ، وأخذ سالع بالحرب ، ودعا اسمها يقتئيل إلى هذا اليوم '),
(5699, '2 Kings', 12, 14, 8, ' حينئذ أرسل أمصيا رسلا إلى يهوآش بن يهوأحاز بن ياهو ملك إسرائيل قائلا : هلم نتراء مواجهة '),
(5700, '2 Kings', 12, 14, 9, ' فأرسل يهوآش ملك إسرائيل إلى أمصيا ملك يهوذا قائلا : العوسج الذي في لبنان أرسل إلى الأرز الذي في لبنان يقول : أعط ابنتك لابني امرأة . فعبر حيوان بري كان في لبنان وداس العوسج '),
(5701, '2 Kings', 12, 14, 10, ' إنك قد ضربت أدوم فرفعك قلبك . تمجد وأقم في بيتك . ولماذا تهجم على الشر فتسقط أنت ويهوذا معك '),
(5702, '2 Kings', 12, 14, 11, ' فلم يسمع أمصيا ، فصعد يهوآش ملك إسرائيل وتراءيا مواجهة ، هو وأمصيا ملك يهوذا في بيت شمس التي ليهوذا '),
(5703, '2 Kings', 12, 14, 12, ' فانهزم يهوذا أمام إسرائيل وهربوا كل واحد إلى خيمته '),
(5704, '2 Kings', 12, 14, 13, ' وأما أمصيا ملك يهوذا ابن يهوآش بن أخزيا فأمسكه يهوآش ملك إسرائيل في بيت شمس ، وجاء إلى أورشليم وهدم سور أورشليم من باب أفرايم إلى باب الزاوية ، أربع مئة ذراع '),
(5705, '2 Kings', 12, 14, 14, ' وأخذ كل الذهب والفضة وجميع الآنية الموجودة في بيت الرب وفي خزائن بيت الملك والرهناء ، ورجع إلى السامرة '),
(5706, '2 Kings', 12, 14, 15, ' وبقية أمور يهوآش التي عمل وجبروته وكيف حارب أمصيا ملك يهوذا ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5707, '2 Kings', 12, 14, 16, ' ثم اضطجع يهوآش مع آبائه ، ودفن في السامرة مع ملوك إسرائيل ، وملك يربعام ابنه عوضا عنه '),
(5708, '2 Kings', 12, 14, 17, ' وعاش أمصيا بن يوآش ملك يهوذا بعد وفاة يهوآش بن يهوأحاز ملك إسرائيل خمس عشرة سنة '),
(5709, '2 Kings', 12, 14, 18, ' وبقية أمور أمصيا ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5710, '2 Kings', 12, 14, 19, ' وفتنوا عليه فتنة في أورشليم ، فهرب إلى لخيش ، فأرسلوا وراءه إلى لخيش وقتلوه هناك '),
(5711, '2 Kings', 12, 14, 20, ' وحملوه على الخيل فدفن في أورشليم مع آبائه في مدينة داود '),
(5712, '2 Kings', 12, 14, 21, ' وأخذ كل شعب يهوذا عزريا ، وهو ابن ست عشرة سنة ، وملكوه عوضا عن أبيه أمصيا '),
(5713, '2 Kings', 12, 14, 22, ' هو بنى أيلة واستردها ليهوذا بعد اضطجاع الملك مع آبائه '),
(5714, '2 Kings', 12, 14, 23, ' في السنة الخامسة عشرة لأمصيا بن يوآش ملك يهوذا ، ملك يربعام بن يوآش ملك إسرائيل في السامرة إحدى وأربعين سنة '),
(5715, '2 Kings', 12, 14, 24, ' وعمل الشر في عيني الرب . لم يحد عن شيء من خطايا يربعام بن نباط الذي جعل إسرائيل يخطئ '),
(5716, '2 Kings', 12, 14, 25, ' هو رد تخم إسرائيل من مدخل حماة إلى بحر العربة ، حسب كلام الرب إله إسرائيل الذي تكلم به عن يد عبده يونان بن أمتاي النبي الذي من جت حافر '),
(5717, '2 Kings', 12, 14, 26, ' لأن الرب رأى ضيق إسرائيل مرا جدا ، لأنه لم يكن محجوز ولا مطلق وليس معين لإسرائيل '),
(5718, '2 Kings', 12, 14, 27, ' ولم يتكلم الرب بمحو اسم إسرائيل من تحت السماء ، فخلصهم بيد يربعام ابن يوآش '),
(5719, '2 Kings', 12, 14, 28, ' وبقية أمور يربعام وكل ما عمل وجبروته ، كيف حارب وكيف استرجع إلى إسرائيل دمشق وحماة التي ليهوذا ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5720, '2 Kings', 12, 14, 29, ' ثم اضطجع يربعام مع آبائه ، مع ملوك إسرائيل ، وملك زكريا ابنه عوضا عنه '),
(5721, '2 Kings', 12, 15, 1, ' في السنة السابعة والعشرين ليربعام ملك إسرائيل ، ملك عزريا بن أمصيا ملك يهوذا '),
(5722, '2 Kings', 12, 15, 2, ' كان ابن ست عشرة سنة حين ملك ، وملك اثنتين وخمسين سنة في أورشليم ، واسم أمه يكليا من أورشليم '),
(5723, '2 Kings', 12, 15, 3, ' وعمل ما هو مستقيم في عيني الرب حسب كل ما عمل أمصيا أبوه '),
(5724, '2 Kings', 12, 15, 4, ' ولكن المرتفعات لم تنتزع ، بل كان الشعب لا يزالون يذبحون ويوقدون على المرتفعات '),
(5725, '2 Kings', 12, 15, 5, ' وضرب الرب الملك فكان أبرص إلى يوم وفاته ، وأقام في بيت المرض ، وكان يوثام ابن الملك على البيت يحكم على شعب الأرض '),
(5726, '2 Kings', 12, 15, 6, ' وبقية أمور عزريا وكل ما عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5727, '2 Kings', 12, 15, 7, ' ثم اضطجع عزريا مع آبائه ، فدفنوه مع آبائه في مدينة داود ، وملك يوثام ابنه عوضا عنه '),
(5728, '2 Kings', 12, 15, 8, ' في السنة الثامنة والثلاثين لعزريا ملك يهوذا ، ملك زكريا بن يربعام على إسرائيل في السامرة ستة أشهر '),
(5729, '2 Kings', 12, 15, 9, ' وعمل الشر في عيني الرب كما عمل آباؤه . لم يحد عن خطايا يربعام بن نباط الذي جعل إسرائيل يخطئ '),
(5730, '2 Kings', 12, 15, 10, ' ففتن عليه شلوم بن يابيش ، وضربه أمام الشعب فقتله ، وملك عوضا عنه '),
(5731, '2 Kings', 12, 15, 11, ' وبقية أمور زكريا هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل . '),
(5732, '2 Kings', 12, 15, 12, ' ذلك كلام الرب الذي كلم به ياهو قائلا : بنو الجيل الرابع يجلسون لك على كرسي إسرائيل . وهكذا كان. '),
(5733, '2 Kings', 12, 15, 13, ' شلوم بن يابيش ملك في السنة التاسعة والثلاثين لعزيا ملك يهوذا ، وملك شهر أيام في السامرة '),
(5734, '2 Kings', 12, 15, 14, ' وصعد منحيم بن جادي من ترصة وجاء إلى السامرة ، وضرب شلوم بن يابيش في السامرة فقتله ، وملك عوضا عنه '),
(5735, '2 Kings', 12, 15, 15, ' وبقية أمور شلوم وفتنته التي فتنها هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5736, '2 Kings', 12, 15, 16, ' حينئذ ضرب منحيم تفصح وكل ما بها وتخومها من ترصة ، لأنهم لم يفتحوا له . ضربها وشق جميع حواملها '),
(5737, '2 Kings', 12, 15, 17, ' في السنة التاسعة والثلاثين لعزريا ملك يهوذا ، ملك منحيم بن جادي على إسرائيل في السامرة عشر سنين '),
(5738, '2 Kings', 12, 15, 18, ' وعمل الشر في عيني الرب . لم يحد عن خطايا يربعام بن نباط الذي جعل إسرائيل يخطئ كل أيامه '),
(5739, '2 Kings', 12, 15, 19, ' فجاء فول ملك أشور على الأرض ، فأعطى منحيم لفول ألف وزنة من الفضة لتكون يداه معه ليثبت المملكة في يده '),
(5740, '2 Kings', 12, 15, 20, ' ووضع منحيم الفضة على إسرائيل على جميع جبابرة البأس ليدفع لملك أشور خمسين شاقل فضة على كل رجل ، فرجع ملك أشور ولم يقم هناك في الأرض '),
(5741, '2 Kings', 12, 15, 21, ' وبقية أمور منحيم وكل ما عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5742, '2 Kings', 12, 15, 22, ' ثم اضطجع منحيم مع آبائه ، وملك فقحيا ابنه عوضا عنه '),
(5743, '2 Kings', 12, 15, 23, ' في السنة الخمسين لعزريا ملك يهوذا ، ملك فقحيا بن منحيم على إسرائيل في السامرة سنتين '),
(5744, '2 Kings', 12, 15, 24, ' وعمل الشر في عيني الرب . لم يحد عن خطايا يربعام بن نباط الذي جعل إسرائيل يخطئ '),
(5745, '2 Kings', 12, 15, 25, ' ففتن عليه فقح بن رمليا ثالثه ، وضربه في السامرة في قصر بيت الملك مع أرجوب ومع أرية ومعه خمسون رجلا من بني الجلعاديين . قتله وملك عوضا عنه '),
(5746, '2 Kings', 12, 15, 26, ' وبقية أمور فقحيا وكل ما عمل ، ها هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5747, '2 Kings', 12, 15, 27, ' في السنة الثانية والخمسين لعزريا ملك يهوذا ، ملك فقح بن رمليا على إسرائيل في السامرة عشرين سنة '),
(5748, '2 Kings', 12, 15, 28, ' وعمل الشر في عيني الرب . لم يحد عن خطايا يربعام بن نباط الذي جعل إسرائيل يخطئ '),
(5749, '2 Kings', 12, 15, 29, ' في أيام فقح ملك إسرائيل ، جاء تغلث فلاسر ملك أشور وأخذ عيون وآبل بيت معكة ويانوح وقادش وحاصور وجلعاد والجليل وكل أرض نفتالي ، وسباهم إلى أشور '),
(5750, '2 Kings', 12, 15, 30, ' وفتن هوشع بن أيلة على فقح بن رمليا ، وضربه فقتله ، وملك عوضا عنه في السنة العشرين ليوثام بن عزيا '),
(5751, '2 Kings', 12, 15, 31, ' وبقية أمور فقح وكل ما عمل ، هي مكتوبة في سفر أخبار الأيام لملوك إسرائيل '),
(5752, '2 Kings', 12, 15, 32, ' في السنة الثانية لفقح بن رمليا ملك إسرائيل ، ملك يوثام بن عزيا ملك يهوذا '),
(5753, '2 Kings', 12, 15, 33, ' كان ابن خمس وعشرين سنة حين ملك ، وملك ست عشرة سنة في أورشليم ، واسم أمه يروشا ابنة صادوق '),
(5754, '2 Kings', 12, 15, 34, ' وعمل ما هو مستقيم في عيني الرب . عمل حسب كل ما عمل عزيا أبوه '),
(5755, '2 Kings', 12, 15, 35, ' إلا أن المرتفعات لم تنتزع ، بل كان الشعب لا يزالون يذبحون ويوقدون على المرتفعات . هو بنى الباب الأعلى لبيت الرب '),
(5756, '2 Kings', 12, 15, 36, ' وبقية أمور يوثام وكل ما عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5757, '2 Kings', 12, 15, 37, ' في تلك الأيام ابتدأ الرب يرسل على يهوذا رصين ملك أرام وفقح بن رمليا '),
(5758, '2 Kings', 12, 15, 38, ' واضطجع يوثام مع آبائه ودفن مع آبائه في مدينة داود أبيه ، وملك آحاز ابنه عوضا عنه '),
(5759, '2 Kings', 12, 16, 1, ' في السنة السابعة عشرة لفقح بن رمليا ، ملك آحاز بن يوثام ملك يهوذا '),
(5760, '2 Kings', 12, 16, 2, ' كان آحاز ابن عشرين سنة حين ملك ، وملك ست عشرة سنة في أورشليم . ولم يعمل المستقيم في عيني الرب إلهه كداود أبيه '),
(5761, '2 Kings', 12, 16, 3, ' بل سار في طريق ملوك إسرائيل ، حتى إنه عبر ابنه في النار حسب أرجاس الأمم الذين طردهم الرب من أمام بني إسرائيل '),
(5762, '2 Kings', 12, 16, 4, ' وذبح وأوقد على المرتفعات وعلى التلال وتحت كل شجرة خضراء '),
(5763, '2 Kings', 12, 16, 5, ' حينئذ صعد رصين ملك أرام وفقح بن رمليا ملك إسرائيل إلى أورشليم للمحاربة ، فحاصروا آحاز ولم يقدروا أن يغلبوه '),
(5764, '2 Kings', 12, 16, 6, ' في ذلك الوقت أرجع رصين ملك أرام أيلة للأراميين ، وطرد اليهود من أيلة . وجاء الأراميون إلى أيلة وأقاموا هناك إلى هذا اليوم '),
(5765, '2 Kings', 12, 16, 7, ' وأرسل آحاز رسلا إلى تغلث فلاسر ملك أشور قائلا : أنا عبدك وابنك . اصعد وخلصني من يد ملك أرام ومن يد ملك إسرائيل القائمين علي '),
(5766, '2 Kings', 12, 16, 8, ' فأخذ آحاز الفضة والذهب الموجودة في بيت الرب وفي خزائن بيت الملك وأرسلها إلى ملك أشور هدية '),
(5767, '2 Kings', 12, 16, 9, ' فسمع له ملك أشور ، وصعد ملك أشور إلى دمشق وأخذها وسباها إلى قير ، وقتل رصين '),
(5768, '2 Kings', 12, 16, 10, ' وسار الملك آحاز للقاء تغلث فلاسر ملك أشور ، إلى دمشق . ورأى المذبح الذي في دمشق . وأرسل الملك آحاز إلى أوريا الكاهن شبه المذبح وشكله حسب كل صناعته '),
(5769, '2 Kings', 12, 16, 11, ' فبنى أوريا الكاهن مذبحا . حسب كل ما أرسل الملك آحاز من دمشق كذلك عمل أوريا الكاهن ، ريثما جاء الملك آحاز من دمشق '),
(5770, '2 Kings', 12, 16, 12, ' فلما قدم الملك من دمشق رأى الملك المذبح ، فتقدم الملك إلى المذبح وأصعد عليه '),
(5771, '2 Kings', 12, 16, 13, ' وأوقد محرقته وتقدمته وسكب سكيبه ، ورش دم ذبيحة السلامة التي له على المذبح '),
(5772, '2 Kings', 12, 16, 14, ' ومذبح النحاس الذي أمام الرب قدمه من أمام البيت من بين المذبح وبيت الرب ، وجعله على جانب المذبح الشمالي '),
(5773, '2 Kings', 12, 16, 15, ' وأمر الملك آحاز أوريا الكاهن قائلا : على المذبح العظيم أوقد محرقة الصباح وتقدمة المساء ، ومحرقة الملك وتقدمته ، مع محرقة كل شعب الأرض وتقدمتهم وسكائبهم ، ورش عليه كل دم محرقة وكل دم ذبيحة . ومذبح النحاس يكون لي للسؤال '),
(5774, '2 Kings', 12, 16, 16, ' فعمل أوريا الكاهن حسب كل ما أمر به الملك آحاز '),
(5775, '2 Kings', 12, 16, 17, ' وقطع الملك آحاز أتراس القواعد ورفع عنها المرحضة ، وأنزل البحر عن ثيران النحاس التي تحته وجعله على رصيف من حجارة '),
(5776, '2 Kings', 12, 24, 4, ' وكذلك لأجل الدم البريء الذي سفكه ، لأنه ملأ أورشليم دما بريئا ، ولم يشإ الرب أن يغفر '),
(5777, '2 Kings', 12, 24, 5, ' وبقية أمور يهوياقيم وكل ما عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5778, '2 Kings', 12, 24, 6, ' ثم اضطجع يهوياقيم مع آبائه ، وملك يهوياكين ابنه عوضا عنه '),
(5779, '2 Kings', 12, 24, 7, ' ولم يعد أيضا ملك مصر يخرج من أرضه ، لأن ملك بابل أخذ من نهر مصر إلى نهر الفرات كل ما كان لملك مصر '),
(5780, '2 Kings', 12, 24, 8, ' كان يهوياكين ابن ثماني عشرة سنة حين ملك ، وملك ثلاثة أشهر في أورشليم ، واسم أمه نحوشتا بنت ألناثان من أورشليم '),
(5781, '2 Kings', 12, 24, 9, ' وعمل الشر في عيني الرب حسب كل ما عمل أبوه '),
(5782, '2 Kings', 12, 24, 10, ' في ذلك الزمان صعد عبيد نبوخذناصر ملك بابل إلى أورشليم ، فدخلت المدينة تحت الحصار '),
(5783, '2 Kings', 12, 24, 11, ' وجاء نبوخذناصر ملك بابل على المدينة ، وكان عبيده يحاصرونها '),
(5784, '2 Kings', 12, 24, 12, ' فخرج يهوياكين ملك يهوذا إلى ملك بابل ، هو وأمه وعبيده ورؤساؤه وخصيانه ، وأخذه ملك بابل في السنة الثامنة من ملكه '),
(5785, '2 Kings', 12, 24, 13, ' وأخرج من هناك جميع خزائن بيت الرب ، وخزائن بيت الملك ، وكسر كل آنية الذهب التي عملها سليمان ملك إسرائيل في هيكل الرب ، كما تكلم الرب '),
(5786, '2 Kings', 12, 24, 14, ' وسبى كل أورشليم وكل الرؤساء وجميع جبابرة البأس ، عشرة آلاف مسبي ، وجميع الصناع والأقيان . لم يبق أحد إلا مساكين شعب الأرض '),
(5787, '2 Kings', 12, 24, 15, ' وسبى يهوياكين إلى بابل . وأم الملك ونساء الملك وخصيانه وأقوياء الأرض ، سباهم من أورشليم إلى بابل '),
(5788, '2 Kings', 12, 24, 16, ' وجميع أصحاب البأس ، سبعة آلاف ، والصناع والأقيان ألف ، وجميع الأبطال أهل الحرب ، سباهم ملك بابل إلى بابل '),
(5789, '2 Kings', 12, 24, 17, ' وملك ملك بابل متنيا عمه عوضا عنه ، وغير اسمه إلى صدقيا '),
(5790, '2 Kings', 12, 24, 18, ' كان صدقيا ابن إحدى وعشرين سنة حين ملك ، وملك إحدى عشرة سنة في أورشليم ، واسم أمه حميطل بنت إرميا من لبنة '),
(5791, '2 Kings', 12, 24, 19, ' وعمل الشر في عيني الرب حسب كل ما عمل يهوياقيم '),
(5792, '2 Kings', 12, 24, 20, ' لأنه لأجل غضب الرب على أورشليم وعلى يهوذا حتى طرحهم من أمام وجهه ، كان أن صدقيا تمرد على ملك بابل '),
(5793, '2 Kings', 12, 25, 1, ' وفي السنة التاسعة لملكه ، في الشهر العاشر في عاشر الشهر ، جاء نبوخذناصر ملك بابل هو وكل جيشه على أورشليم ونزل عليها ، وبنوا عليها أبراجا حولها '),
(5794, '2 Kings', 12, 25, 2, ' ودخلت المدينة تحت الحصار إلى السنة الحادية عشرة للملك صدقيا '),
(5795, '2 Kings', 12, 25, 3, ' في تاسع الشهر اشتد الجوع في المدينة ، ولم يكن خبز لشعب الأرض '),
(5796, '2 Kings', 12, 25, 4, ' فثغرت المدينة ، وهرب جميع رجال القتال ليلا من طريق الباب بين السورين اللذين نحو جنة الملك . وكان الكلدانيون حول المدينة مستديرين . فذهبوا في طريق البرية '),
(5797, '2 Kings', 12, 25, 5, ' فتبعت جيوش الكلدانيين الملك فأدركوه في برية أريحا ، وتفرقت جميع جيوشه عنه '),
(5798, '2 Kings', 12, 25, 6, ' فأخذوا الملك وأصعدوه إلى ملك بابل ، إلى ربلة ، وكلموه بالقضاء عليه '),
(5799, '2 Kings', 12, 25, 7, ' وقتلوا بني صدقيا أمام عينيه ، وقلعوا عيني صدقيا وقيدوه بسلسلتين من نحاس ، وجاءوا به إلى بابل '),
(5800, '2 Kings', 12, 25, 8, ' وفي الشهر الخامس ، في سابع الشهر ، وهي السنة التاسعة عشرة للملك نبوخذناصر ملك بابل ، جاء نبوزرادان رئيس الشرط عبد ملك بابل إلى أورشليم '),
(5801, '2 Kings', 12, 25, 9, ' وأحرق بيت الرب وبيت الملك ، وكل بيوت أورشليم ، وكل بيوت العظماء أحرقها بالنار ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(5802, '2 Kings', 12, 25, 10, ' وجميع أسوار أورشليم مستديرا هدمها كل جيوش الكلدانيين الذين مع رئيس الشرط '),
(5803, '2 Kings', 12, 25, 11, ' وبقية الشعب الذين بقوا في المدينة ، والهاربون الذين هربوا إلى ملك بابل ، وبقية الجمهور سباهم نبوزرادان رئيس الشرط '),
(5804, '2 Kings', 12, 25, 12, ' ولكن رئيس الشرط أبقى من مساكين الأرض كرامين وفلاحين '),
(5805, '2 Kings', 12, 25, 13, ' وأعمدة النحاس التي في بيت الرب والقواعد وبحر النحاس الذي في بيت الرب كسرها الكلدانيون ، وحملوا نحاسها إلى بابل '),
(5806, '2 Kings', 12, 25, 14, ' والقدور والرفوش والمقاص والصحون وجميع آنية النحاس التي كانوا يخدمون بها ، أخذوها '),
(5807, '2 Kings', 12, 25, 15, ' والمجامر والمناضح . ما كان من ذهب فالذهب ، وما كان من فضة فالفضة ، أخذها رئيس الشرط '),
(5808, '2 Kings', 12, 25, 16, ' والعمودان والبحر الواحد والقواعد التي عملها سليمان لبيت الرب ، لم يكن وزن لنحاس كل هذه الأدوات '),
(5809, '2 Kings', 12, 25, 17, ' ثماني عشرة ذراعا ارتفاع العمود الواحد ، وعليه تاج من نحاس ، وارتفاع التاج ثلاث أذرع ، والشبكة والرمانات التي على التاج مستديرة جميعها من نحاس . وكان للعمود الثاني مثل هذه على الشبكة '),
(5810, '2 Kings', 12, 25, 18, ' وأخذ رئيس الشرط سرايا الكاهن الرئيس ، وصفنيا الكاهن الثاني ، وحارسي الباب الثلاثة '),
(5811, '2 Kings', 12, 25, 19, ' ومن المدينة أخذ خصيا واحدا كان وكيلا على رجال الحرب ، وخمسة رجال من الذين ينظرون وجه الملك الذين وجدوا في المدينة ، وكاتب رئيس الجند الذي كان يجمع شعب الأرض ، وستين رجلا من شعب الأرض الموجودين في المدينة '),
(5812, '2 Kings', 12, 25, 20, ' وأخذهم نبوزرادان رئيس الشرط وسار بهم إلى ملك بابل إلى ربلة '),
(5813, '2 Kings', 12, 25, 21, ' فضربهم ملك بابل وقتلهم في ربلة في أرض حماة . فسبي يهوذا من أرضه '),
(5814, '2 Kings', 12, 25, 22, ' وأما الشعب الذي بقي في أرض يهوذا ، الذين أبقاهم نبوخذناصر ملك بابل ، فوكل عليهم جدليا بن أخيقام بن شافان '),
(5815, '2 Kings', 12, 25, 23, ' ولما سمع جميع رؤساء الجيوش هم ورجالهم أن ملك بابل قد وكل جدليا أتوا إلى جدليا إلى المصفاة ، وهم إسماعيل بن نثنيا ، ويوحنان بن قاريح ، وسرايا بن تنحومث النطوفاتي ، ويازنيا ابن المعكي ، هم ورجالهم '),
(5816, '2 Kings', 12, 25, 24, ' وحلف جدليا لهم ولرجالهم ، وقال لهم : لا تخافوا من عبيد الكلدانيين . اسكنوا الأرض وتعبدوا لملك بابل فيكون لكم خير '),
(5817, '2 Kings', 12, 25, 25, ' وفي الشهر السابع جاء إسماعيل بن نثنيا بن أليشمع من النسل الملكي ، وعشرة رجال معه وضربوا جدليا فمات ، وأيضا اليهود والكلدانيين الذين معه في المصفاة '),
(5818, '2 Kings', 12, 25, 26, ' فقام جميع الشعب من الصغير إلى الكبير ورؤساء الجيوش وجاءوا إلى مصر ، لأنهم خافوا من الكلدانيين '),
(5819, '2 Kings', 12, 25, 27, ' وفي السنة السابعة والثلاثين لسبي يهوياكين ملك يهوذا ، في الشهر الثاني عشر في السابع والعشرين من الشهر ، رفع أويل مرودخ ملك بابل ، في سنة تملكه ، رأس يهوياكين ملك يهوذا من السجن '),
(5820, '2 Kings', 12, 25, 28, ' وكلمه بخير ، وجعل كرسيه فوق كراسي الملوك الذين معه في بابل '),
(5821, '2 Kings', 12, 25, 29, ' وغير ثياب سجنه . وكان يأكل دائما الخبز أمامه كل أيام حياته '),
(5822, '2 Kings', 12, 25, 30, ' ووظيفته وظيفة دائمة تعطى له من عند الملك ، أمر كل يوم بيومه كل أيام حياته '),
(5823, '2 Kings', 12, 16, 18, ' ورواق السبت الذي بنوه في البيت ، ومدخل الملك من خارج ، غيره في بيت الرب من أجل ملك أشور '),
(5824, '2 Kings', 12, 16, 19, ' وبقية أمور آحاز التي عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5825, '2 Kings', 12, 16, 20, ' ثم اضطجع آحاز مع آبائه ، ودفن مع آبائه في مدينة داود ، وملك حزقيا ابنه عوضا عنه '),
(5826, '2 Kings', 12, 17, 1, ' في السنة الثانية عشرة لآحاز ملك يهوذا ، ملك هوشع بن أيلة في السامرة على إسرائيل تسع سنين '),
(5827, '2 Kings', 12, 17, 2, ' وعمل الشر في عيني الرب ، ولكن ليس كملوك إسرائيل الذين كانوا قبله '),
(5828, '2 Kings', 12, 17, 3, ' وصعد عليه شلمنأسر ملك أشور ، فصار له هوشع عبدا ودفع له جزية '),
(5829, '2 Kings', 12, 17, 4, ' ووجد ملك أشور في هوشع خيانة ، لأنه أرسل رسلا إلى سوا ملك مصر ، ولم يؤد جزية إلى ملك أشور حسب كل سنة ، فقبض عليه ملك أشور وأوثقه في السجن '),
(5830, '2 Kings', 12, 17, 5, ' وصعد ملك أشور على كل الأرض ، وصعد إلى السامرة وحاصرها ثلاث سنين '),
(5831, '2 Kings', 12, 17, 6, ' في السنة التاسعة لهوشع أخذ ملك أشور السامرة ، وسبى إسرائيل إلى أشور وأسكنهم في حلح وخابور نهر جوزان وفي مدن مادي '),
(5832, '2 Kings', 12, 17, 7, ' وكان أن بني إسرائيل أخطأوا إلى الرب إلههم الذي أصعدهم من أرض مصر من تحت يد فرعون ملك مصر ، واتقوا آلهة أخرى '),
(5833, '2 Kings', 12, 17, 8, ' وسلكوا حسب فرائض الأمم الذين طردهم الرب من أمام بني إسرائيل وملوك إسرائيل الذين أقاموهم '),
(5834, '2 Kings', 12, 17, 9, ' وعمل بنو إسرائيل سرا ضد الرب إلههم أمورا ليست بمستقيمة ، وبنوا لأنفسهم مرتفعات في جميع مدنهم ، من برج النواطير إلى المدينة المحصنة '),
(5835, '2 Kings', 12, 17, 10, ' وأقاموا لأنفسهم أنصابا وسواري على كل تل عال وتحت كل شجرة خضراء '),
(5836, '2 Kings', 12, 17, 11, ' وأوقدوا هناك على جميع المرتفعات مثل الأمم الذين ساقهم الرب من أمامهم ، وعملوا أمورا قبيحة لإغاظة الرب '),
(5837, '2 Kings', 12, 17, 12, ' وعبدوا الأصنام التي قال الرب لهم عنها : لا تعملوا هذا الأمر '),
(5838, '2 Kings', 12, 17, 13, ' وأشهد الرب على إسرائيل وعلى يهوذا عن يد جميع الأنبياء وكل راء قائلا : ارجعوا عن طرقكم الرديئة واحفظوا وصاياي ، فرائضي ، حسب كل الشريعة التي أوصيت بها آباءكم ، والتي أرسلتها إليكم عن يد عبيدي الأنبياء '),
(5839, '2 Kings', 12, 17, 14, ' فلم يسمعوا بل صلبوا أقفيتهم كأقفية آبائهم الذين لم يؤمنوا بالرب إلههم '),
(5840, '2 Kings', 12, 17, 15, ' ورفضوا فرائضه وعهده الذي قطعه مع آبائهم وشهاداته التي شهد بها عليهم ، وساروا وراء الباطل ، وصاروا باطلا وراء الأمم الذين حولهم ، الذين أمرهم الرب أن لا يعملوا مثلهم '),
(5841, '2 Kings', 12, 17, 16, ' وتركوا جميع وصايا الرب إلههم وعملوا لأنفسهم مسبوكات عجلين ، وعملوا سواري ، وسجدوا لجميع جند السماء ، وعبدوا البعل '),
(5842, '2 Kings', 12, 17, 17, ' وعبروا بنيهم وبناتهم في النار ، وعرفوا عرافة وتفاءلوا ، وباعوا أنفسهم لعمل الشر في عيني الرب لإغاظته '),
(5843, '2 Kings', 12, 17, 18, ' فغضب الرب جدا على إسرائيل ونحاهم من أمامه ، ولم يبق إلا سبط يهوذا وحده '),
(5844, '2 Kings', 12, 17, 19, ' ويهوذا أيضا لم يحفظوا وصايا الرب إلههم ، بل سلكوا في فرائض إسرائيل التي عملوها '),
(5845, '2 Kings', 12, 17, 20, ' فرذل الرب كل نسل إسرائيل ، وأذلهم ودفعهم ليد ناهبين حتى طرحهم من أمامه '),
(5846, '2 Kings', 12, 17, 21, ' لأنه شق إسرائيل عن بيت داود ، فملكوا يربعام بن نباط ، فأبعد يربعام إسرائيل من وراء الرب وجعلهم يخطئون خطية عظيمة '),
(5847, '2 Kings', 12, 17, 22, ' وسلك بنو إسرائيل في جميع خطايا يربعام التي عمل . لم يحيدوا عنها '),
(5848, '2 Kings', 12, 17, 23, ' حتى نحى الرب إسرائيل من أمامه كما تكلم عن يد جميع عبيده الأنبياء ، فسبي إسرائيل من أرضه إلى أشور إلى هذا اليوم '),
(5849, '2 Kings', 12, 17, 24, ' وأتى ملك أشور بقوم من بابل وكوث وعوا وحماة وسفروايم ، وأسكنهم في مدن السامرة عوضا عن بني إسرائيل ، فامتلكوا السامرة وسكنوا في مدنها '),
(5850, '2 Kings', 12, 17, 25, ' وكان في ابتداء سكنهم هناك أنهم لم يتقوا الرب ، فأرسل الرب عليهم السباع فكانت تقتل منهم '),
(5851, '2 Kings', 12, 17, 26, ' فكلموا ملك أشور قائلين : إن الأمم الذين سبيتهم وأسكنتهم في مدن السامرة ، لا يعرفون قضاء إله الأرض ، فأرسل عليهم السباع فهي تقتلهم لأنهم لا يعرفون قضاء إله الأرض '),
(5852, '2 Kings', 12, 17, 27, ' فأمر ملك أشور قائلا : ابعثوا إلى هناك واحدا من الكهنة الذين سبيتموهم من هناك فيذهب ويسكن هناك ، ويعلمهم قضاء إله الأرض '),
(5853, '2 Kings', 12, 17, 28, ' فأتى واحد من الكهنة الذين سبوهم من السامرة ، وسكن في بيت إيل وعلمهم كيف يتقون الرب '),
(5854, '2 Kings', 12, 17, 29, ' فكانت كل أمة تعمل آلهتها ووضعوها في بيوت المرتفعات التي عملها السامريون ، كل أمة في مدنها التي سكنت فيها '),
(5855, '2 Kings', 12, 17, 30, ' فعمل أهل بابل سكوث بنوث ، وأهل كوث عملوا نرجل ، وأهل حماة عملوا أشيما '),
(5856, '2 Kings', 12, 17, 31, ' والعويون عملوا نبحز وترتاق ، والسفروايميون كانوا يحرقون بنيهم بالنار لأدرملك وعنملك إلهي سفروايم '),
(5857, '2 Kings', 12, 17, 32, ' فكانوا يتقون الرب ، ويعملون لأنفسهم من أطرافهم كهنة مرتفعات ، كانوا يقربون لأجلهم في بيوت المرتفعات '),
(5858, '2 Kings', 12, 17, 33, ' كانوا يتقون الرب ويعبدون آلهتهم كعادة الأمم الذين سبوهم من بينهم '),
(5859, '2 Kings', 12, 17, 34, ' إلى هذا اليوم يعملون كعاداتهم الأول . لا يتقون الرب ولا يعملون حسب فرائضهم وعوائدهم ولا حسب الشريعة والوصية التي أمر بها الرب بني يعقوب ، الذي جعل اسمه إسرائيل '),
(5860, '2 Kings', 12, 17, 35, ' وقطع الرب معهم عهدا وأمرهم قائلا : لا تتقوا آلهة أخرى ، ولا تسجدوا لها ولا تعبدوها ولا تذبحوا لها '),
(5861, '2 Kings', 12, 17, 36, ' بل إنما اتقوا الرب الذي أصعدكم من أرض مصر بقوة عظيمة وذراع ممدودة ، وله اسجدوا ، وله اذبحوا '),
(5862, '2 Kings', 12, 17, 37, ' واحفظوا الفرائض والأحكام والشريعة والوصية التي كتبها لكم لتعملوا بها كل الأيام ، ولا تتقوا آلهة أخرى '),
(5863, '2 Kings', 12, 17, 38, ' ولا تنسوا العهد الذي قطعته معكم ، ولا تتقوا آلهة أخرى '),
(5864, '2 Kings', 12, 17, 39, ' بل إنما اتقوا الرب إلهكم وهو ينقذكم من أيدي جميع أعدائكم '),
(5865, '2 Kings', 12, 17, 40, ' فلم يسمعوا بل عملوا حسب عادتهم الأولى '),
(5866, '2 Kings', 12, 17, 41, ' فكان هؤلاء الأمم يتقون الرب ، ويعبدون تماثيلهم ، وأيضا بنوهم وبنو بنيهم . فكما عمل آباؤهم هكذا هم عاملون إلى هذا اليوم '),
(5867, '2 Kings', 12, 18, 1, ' وفي السنة الثالثة لهوشع بن أيلة ملك إسرائيل ، ملك حزقيا بن آحاز ملك يهوذا '),
(5868, '2 Kings', 12, 18, 2, ' كان ابن خمس وعشرين سنة حين ملك ، وملك تسعا وعشرين سنة في أورشليم ، واسم أمه أبي ابنة زكريا '),
(5869, '2 Kings', 12, 18, 3, ' وعمل المستقيم في عيني الرب حسب كل ما عمل داود أبوه '),
(5870, '2 Kings', 12, 18, 4, ' هو أزال المرتفعات ، وكسر التماثيل ، وقطع السواري ، وسحق حية النحاس التي عملها موسى ، لأن بني إسرائيل كانوا إلى تلك الأيام يوقدون لها ، ودعوها نحشتان '),
(5871, '2 Kings', 12, 18, 5, ' على الرب إله إسرائيل اتكل ، وبعده لم يكن مثله في جميع ملوك يهوذا ولا في الذين كانوا قبله '),
(5872, '2 Kings', 12, 18, 6, ' والتصق بالرب ولم يحد عنه ، بل حفظ وصاياه التي أمر بها الرب موسى '),
(5873, '2 Kings', 12, 18, 7, ' وكان الرب معه ، وحيثما كان يخرج كان ينجح . وعصى على ملك أشور ولم يتعبد له '),
(5874, '2 Kings', 12, 18, 8, ' هو ضرب الفلسطينيين إلى غزة وتخومها ، من برج النواطير إلى المدينة المحصنة '),
(5875, '2 Kings', 12, 18, 9, ' وفي السنة الرابعة للملك حزقيا ، وهي السنة السابعة لهوشع بن أيلة ملك إسرائيل ، صعد شلمنأسر ملك أشور على السامرة وحاصرها '),
(5876, '2 Kings', 12, 18, 10, ' وأخذوها في نهاية ثلاث سنين . ففي السنة السادسة لحزقيا ، وهي السنة التاسعة لهوشع ملك إسرائيل ، أخذت السامرة '),
(5877, '2 Kings', 12, 18, 11, ' وسبى ملك أشور إسرائيل إلى أشور ، ووضعهم في حلح وخابور نهر جوزان وفي مدن مادي '),
(5878, '2 Kings', 12, 18, 12, ' لأنهم لم يسمعوا لصوت الرب إلههم ، بل تجاوزوا عهده وكل ما أمر به موسى عبد الرب ، فلم يسمعوا ولم يعملوا '),
(5879, '2 Kings', 12, 18, 13, ' وفي السنة الرابعة عشرة للملك حزقيا ، صعد سنحاريب ملك أشور على جميع مدن يهوذا الحصينة وأخذها '),
(5880, '2 Kings', 12, 18, 14, ' وأرسل حزقيا ملك يهوذا إلى ملك أشور إلى لخيش يقول : قد أخطأت . ارجع عني ، ومهما جعلت علي حملته . فوضع ملك أشور على حزقيا ملك يهوذا ثلاث مئة وزنة من الفضة وثلاثين وزنة من الذهب '),
(5881, '2 Kings', 12, 18, 15, ' فدفع حزقيا جميع الفضة الموجودة في بيت الرب وفي خزائن بيت الملك '),
(5882, '2 Kings', 12, 18, 16, ' في ذلك الزمان قشر حزقيا الذهب عن أبواب هيكل الرب والدعائم التي كان قد غشاها حزقيا ملك يهوذا ، ودفعه لملك أشور '),
(5883, '2 Kings', 12, 18, 17, ' وأرسل ملك أشور ترتان وربساريس وربشاقى من لخيش إلى الملك حزقيا بجيش عظيم إلى أورشليم ، فصعدوا وأتوا إلى أورشليم . ولما صعدوا جاءوا ووقفوا عند قناة البركة العليا التي في طريق حقل القصار '),
(5884, '2 Kings', 12, 18, 18, ' ودعوا الملك ، فخرج إليهم ألياقيم بن حلقيا الذي على البيت وشبنة الكاتب ويواخ بن آساف المسجل '),
(5885, '2 Kings', 12, 18, 19, ' فقال لهم ربشاقى : قولوا لحزقيا : هكذا يقول الملك العظيم ملك أشور : ما الاتكال الذي اتكلت '),
(5886, '2 Kings', 12, 18, 20, ' قلت إنما كلام الشفتين هو مشورة وبأس للحرب . والآن على من اتكلت حتى عصيت علي '),
(5887, '2 Kings', 12, 18, 21, ' فالآن هوذا قد اتكلت على عكاز هذه القصبة المرضوضة ، على مصر ، التي إذا توكأ أحد عليها ، دخلت في كفه وثقبتها هكذا هو فرعون ملك مصر لجميع المتكلين عليه '),
(5888, '2 Kings', 12, 18, 22, ' وإذا قلتم لي : على الرب إلهنا اتكلنا ، أفليس هو الذي أزال حزقيا مرتفعاته ومذابحه ، وقال ليهوذا ولأورشليم : أمام هذا المذبح تسجدون في أورشليم '),
(5889, '2 Kings', 12, 18, 23, ' والآن راهن سيدي ملك أشور ، فأعطيك ألفي فرس إن كنت تقدر أن تجعل عليها راكبين '),
(5890, '2 Kings', 12, 18, 24, ' فكيف ترد وجه وال واحد من عبيد سيدي الصغار ، وتتكل على مصر لأجل مركبات وفرسان '),
(5891, '2 Kings', 12, 18, 25, ' والآن هل بدون الرب صعدت على هذا الموضع لأخربه ؟ الرب قال لي : اصعد على هذه الأرض واخربها '),
(5892, '2 Kings', 12, 18, 26, ' فقال ألياقيم بن حلقيا وشبنة ويواخ لربشاقى : كلم عبيدك بالأرامي لأننا نفهمه ، ولا تكلمنا باليهودي في مسامع الشعب الذين على السور '),
(5893, '2 Kings', 12, 18, 27, ' فقال لهم ربشاقى : هل إلى سيدك وإليك أرسلني سيدي لكي أتكلم بهذا الكلام ؟ أليس إلى الرجال الجالسين على السور ليأكلوا عذرتهم ويشربوا بولهم معكم '),
(5894, '2 Kings', 12, 18, 28, ' ثم وقف ربشاقى ونادى بصوت عظيم باليهودي وتكلم قائلا : اسمعوا كلام الملك العظيم ملك أشور '),
(5895, '2 Kings', 12, 18, 29, ' هكذا يقول الملك : لا يخدعكم حزقيا ، لأنه لا يقدر أن ينقذكم من يده '),
(5896, '2 Kings', 12, 18, 30, ' ولا يجعلكم حزقيا تتكلون على الرب قائلا : إنقاذا ينقذنا الرب ولا تدفع هذه المدينة إلى يد ملك أشور '),
(5897, '2 Kings', 12, 18, 31, ' لا تسمعوا لحزقيا . لأنه هكذا يقول ملك أشور : اعقدوا معي صلحا ، واخرجوا إلي ، وكلوا كل واحد من جفنته وكل واحد من تينته ، واشربوا كل واحد ماء بئره '),
(5898, '2 Kings', 12, 18, 32, ' حتى آتي وآخذكم إلى أرض كأرضكم ، أرض حنطة وخمر ، أرض خبز وكروم ، أرض زيتون وعسل واحيوا ولا تموتوا . ولا تسمعوا لحزقيا لأنه يغركم قائلا : الرب ينقذنا '),
(5899, '2 Kings', 12, 18, 33, ' هل أنقذ آلهة الأمم كل واحد أرضه من يد ملك أشور '),
(5900, '2 Kings', 12, 18, 34, ' أين آلهة حماة وأرفاد ؟ أين آلهة سفروايم وهينع وعوا ؟ هل أنقذوا السامرة من يدي '),
(5901, '2 Kings', 12, 18, 35, ' من من كل آلهة الأراضي أنقذ أرضهم من يدي ، حتى ينقذ الرب أورشليم من يدي '),
(5902, '2 Kings', 12, 18, 36, ' فسكت الشعب ولم يجيبوه بكلمة ، لأن أمر الملك كان قائلا : لا تجيبوه '),
(5903, '2 Kings', 12, 18, 37, ' فجاء ألياقيم بن حلقيا الذي على البيت ، وشبنة الكاتب ، ويواخ بن آساف المسجل ، إلى حزقيا وثيابهم ممزقة ، فأخبروه بكلام ربشاقى '),
(5904, '2 Kings', 12, 19, 1, ' فلما سمع الملك حزقيا ذلك ، مزق ثيابه وتغطى بمسح ودخل بيت الرب '),
(5905, '2 Kings', 12, 19, 2, ' وأرسل ألياقيم الذي على البيت وشبنة الكاتب وشيوخ الكهنة متغطين بمسح إلى إشعيا النبي ابن آموص '),
(5906, '2 Kings', 12, 19, 3, ' فقالوا له : هكذا يقول حزقيا : هذا اليوم يوم شدة وتأديب وإهانة ، لأن الأجنة قد دنت إلى المولد ولا قوة للولادة '),
(5907, '2 Kings', 12, 19, 4, ' لعل الرب إلهك يسمع جميع كلام ربشاقى الذي أرسله ملك أشور سيده ليعير الإله الحي ، فيوبخ على الكلام الذي سمعه الرب إلهك . فارفع صلاة من أجل البقية الموجودة '),
(5908, '2 Kings', 12, 19, 5, ' فجاء عبيد الملك حزقيا إلى إشعيا '),
(5909, '2 Kings', 12, 19, 6, ' فقال لهم إشعيا : هكذا تقولون لسيدكم : هكذا قال الرب : لا تخف بسبب الكلام الذي سمعته ، الذي جدف علي به غلمان ملك أشور '),
(5910, '2 Kings', 12, 19, 7, ' هأنذا أجعل فيه روحا فيسمع خبرا ويرجع إلى أرضه ، وأسقطه بالسيف في أرضه '),
(5911, '2 Kings', 12, 19, 8, ' فرجع ربشاقى ووجد ملك أشور يحارب لبنة ، لأنه سمع أنه ارتحل عن لخيش '),
(5912, '2 Kings', 12, 19, 9, ' وسمع عن ترهاقة ملك كوش قولا : قد خرج ليحاربك . فعاد وأرسل رسلا إلى حزقيا قائلا '),
(5913, '2 Kings', 12, 19, 10, ' هكذا تكلمون حزقيا ملك يهوذا قائلين : لا يخدعك إلهك الذي أنت متكل عليه قائلا : لا تدفع أورشليم إلى يد ملك أشور '),
(5914, '2 Kings', 12, 19, 11, ' إنك قد سمعت ما فعل ملوك أشور بجميع الأراضي لإهلاكها ، وهل تنجو أنت '),
(5915, '2 Kings', 12, 19, 12, ' هل أنقذت آلهة الأمم هؤلاء الذين أهلكهم آبائي ، جوزان وحاران ورصف وبني عدن الذين في تلاسار '),
(5916, '2 Kings', 12, 19, 13, ' أين ملك حماة وملك أرفاد وملك مدينة سفروايم وهينع وعوا '),
(5917, '2 Kings', 12, 19, 14, ' فأخذ حزقيا الرسائل من أيدي الرسل وقرأها ، ثم صعد إلى بيت الرب ، ونشرها حزقيا أمام الرب '),
(5918, '2 Kings', 12, 19, 15, ' وصلى حزقيا أمام الرب وقال : أيها الرب إله إسرائيل ، الجالس فوق الكروبيم ، أنت هو الإله وحدك لكل ممالك الأرض . أنت صنعت السماء والأرض '),
(5919, '2 Kings', 12, 19, 16, ' أمل يارب أذنك واسمع . افتح يارب عينيك وانظر ، واسمع كلام سنحاريب الذي أرسله ليعير الله الحي '),
(5920, '2 Kings', 12, 19, 17, ' حقا يارب إن ملوك أشور قد خربوا الأمم وأراضيهم '),
(5921, '2 Kings', 12, 19, 18, ' ودفعوا آلهتهم إلى النار . ولأنهم ليسوا آلهة ، بل صنعة أيدي الناس : خشب وحجر ، فأبادوهم '),
(5922, '2 Kings', 12, 19, 19, ' والآن أيها الرب إلهنا ، خلصنا من يده ، فتعلم ممالك الأرض كلها أنك أنت الرب الإله وحدك '),
(5923, '2 Kings', 12, 19, 20, ' فأرسل إشعيا بن آموص إلى حزقيا قائلا : هكذا قال الرب إله إسرائيل الذي صليت إليه من جهة سنحاريب ملك أشور : قد سمعت '),
(5924, '2 Kings', 12, 19, 21, ' هذا هو الكلام الذي تكلم به الرب عليه : احتقرتك واستهزأت بك العذراء ابنة صهيون ، ونحوك أنغضت ابنة أورشليم رأسها '),
(5925, '2 Kings', 12, 19, 22, ' من عيرت وجدفت ؟ وعلى من عليت صوتا ؟ وقد رفعت إلى العلاء عينيك على قدوس إسرائيل '),
(5926, '2 Kings', 12, 19, 23, ' على يد رسلك عيرت السيد ، وقلت : بكثرة مركباتي قد صعدت إلى علو الجبال ، إلى عقاب لبنان وأقطع أرزه الطويل وأفضل سروه ، وأدخل أقصى علوه ، وعر كرمله '),
(5927, '2 Kings', 12, 19, 24, ' أنا قد حفرت وشربت مياها غريبة ، وأنشف بأسفل قدمي جميع خلجان مصر '),
(5928, '2 Kings', 12, 19, 25, ' ألم تسمع ؟ منذ البعيد صنعته ، منذ الأيام القديمة صورته . الآن أتيت به . فتكون لتخريب مدن محصنة حتى تصير روابي خربة '),
(5929, '2 Kings', 12, 19, 26, ' فسكانها قصار الأيدي قد ارتاعوا وخجلوا ، صاروا كعشب الحقل وكالنبات الأخضر ، كحشيش السطوح وكملفوح قبل نموه '),
(5930, '2 Kings', 12, 19, 27, ' ولكني عالم بجلوسك وخروجك ودخولك وهيجانك علي '),
(5931, '2 Kings', 12, 19, 28, ' لأن هيجانك علي وعجرفتك قد صعدا إلى أذني ، أضع خزامتي في أنفك ولجامي في شفتيك ، وأردك في الطريق الذي جئت فيه '),
(5932, '2 Kings', 12, 19, 29, ' وهذه لك علامة : تأكلون هذه السنة زريعا ، وفي السنة الثانية خلفة . وأما السنة الثالثة ففيها تزرعون وتحصدون وتغرسون كروما وتأكلون أثمارها '),
(5933, '2 Kings', 12, 19, 30, ' ويعود الناجون من بيت يهوذا ، الباقون ، يتأصلون إلى أسفل ويصنعون ثمرا إلى ما فوق '),
(5934, '2 Kings', 12, 19, 31, ' لأنه من أورشليم تخرج البقية ، والناجون من جبل صهيون . غيرة رب الجنود تصنع هذا '),
(5935, '2 Kings', 12, 19, 32, ' لذلك هكذا قال الرب عن ملك أشور : لا يدخل هذه المدينة ، ولا يرمي هناك سهما ، ولا يتقدم عليها بترس ، ولا يقيم عليها مترسة '),
(5936, '2 Kings', 12, 19, 33, ' في الطريق الذي جاء فيه يرجع ، وإلى هذه المدينة لا يدخل ، يقول الرب '),
(5937, '2 Kings', 12, 19, 34, ' وأحامي عن هذه المدينة لأخلصها من أجل نفسي ومن أجل داود عبدي '),
(5938, '2 Kings', 12, 19, 35, ' وكان في تلك الليلة أن ملاك الرب خرج وضرب من جيش أشور مئة ألف وخمسة وثمانين ألفا . ولما بكروا صباحا إذا هم جميعا جثث ميتة '),
(5939, '2 Kings', 12, 19, 36, ' فانصرف سنحاريب ملك أشور وذهب راجعا وأقام في نينوى '),
(5940, '2 Kings', 12, 19, 37, ' وفيما هو ساجد في بيت نسروخ إلهه ، ضربه أدرملك وشرآصر ابناه بالسيف ، ونجوا إلى أرض أراراط . وملك آسرحدون ابنه عوضا عنه '),
(5941, '2 Kings', 12, 20, 1, ' في تلك الأيام مرض حزقيا للموت ، فجاء إليه إشعيا بن آموص النبي وقال له : هكذا قال الرب : أوص بيتك لأنك تموت ولا تعيش '),
(5942, '2 Kings', 12, 20, 2, ' فوجه وجهه إلى الحائط وصلى إلى الرب قائلا '),
(5943, '2 Kings', 12, 20, 3, ' آه يارب ، اذكر كيف سرت أمامك بالأمانة وبقلب سليم ، وفعلت الحسن في عينيك . وبكى حزقيا بكاء عظيما '),
(5944, '2 Kings', 12, 20, 4, ' ولم يخرج إشعيا إلى المدينة الوسطى حتى كان كلام الرب إليه قائلا '),
(5945, '2 Kings', 12, 20, 5, ' ارجع وقل لحزقيا رئيس شعبي : هكذا قال الرب إله داود أبيك : قد سمعت صلاتك . قد رأيت دموعك . هأنذا أشفيك . في اليوم الثالث تصعد إلى بيت الرب '),
(5946, '2 Kings', 12, 20, 6, ' وأزيد على أيامك خمس عشرة سنة ، وأنقذك من يد ملك أشور مع هذه المدينة ، وأحامي عن هذه المدينة من أجل نفسي ، ومن أجل داود عبدي '),
(5947, '2 Kings', 12, 20, 7, ' فقال إشعيا : خذوا قرص تين . فأخذوها ووضعوها على الدبل فبرئ '),
(5948, '2 Kings', 12, 20, 8, ' وقال حزقيا لإشعيا : ما العلامة أن الرب يشفيني ، فأصعد في اليوم الثالث إلى بيت الرب '),
(5949, '2 Kings', 12, 20, 9, ' فقال إشعيا : هذه لك علامة من قبل الرب على أن الرب يفعل الأمر الذي تكلم به : هل يسير الظل عشر درجات أو يرجع عشر درجات '),
(5950, '2 Kings', 12, 20, 10, ' فقال حزقيا : إنه يسير على الظل أن يمتد عشر درجات . لا بل يرجع الظل إلى الوراء عشر درجات '),
(5951, '2 Kings', 12, 20, 11, ' فدعا إشعيا النبي الرب ، فأرجع الظل بالدرجات التي نزل بها بدرجات آحاز عشر درجات إلى الوراء '),
(5952, '2 Kings', 12, 20, 12, ' في ذلك الزمان أرسل برودخ بلادان بن بلادان ملك بابل رسائل وهدية إلى حزقيا ، لأنه سمع أن حزقيا قد مرض '),
(5953, '2 Kings', 12, 20, 13, ' فسمع لهم حزقيا وأراهم كل بيت ذخائره ، والفضة والذهب والأطياب والزيت الطيب ، وكل بيت أسلحته وكل ما وجد في خزائنه . لم يكن شيء لم يرهم إياه حزقيا في بيته وفي كل سلطنته '),
(5954, '2 Kings', 12, 20, 14, ' فجاء إشعيا النبي إلى الملك حزقيا وقال له : ماذا قال هؤلاء الرجال ؟ ومن أين جاءوا إليك ؟  . فقال حزقيا : جاءوا من أرض بعيدة ، من بابل '),
(5955, '2 Kings', 12, 20, 15, ' فقال : ماذا رأوا في بيتك ؟  . فقال حزقيا : رأوا كل ما في بيتي . ليس في خزائني شيء لم أرهم إياه '),
(5956, '2 Kings', 12, 20, 16, ' فقال إشعيا لحزقيا : اسمع قول الرب '),
(5957, '2 Kings', 12, 20, 17, ' هوذا تأتي أيام يحمل فيها كل ما في بيتك ، وما ذخره آباؤك إلى هذا اليوم إلى بابل . لا يترك شيء ، يقول الرب '),
(5958, '2 Kings', 12, 20, 18, ' ويؤخذ من بنيك الذين يخرجون منك ، الذين تلدهم ، فيكونون خصيانا في قصر ملك بابل '),
(5959, '2 Kings', 12, 20, 19, ' فقال حزقيا لإشعيا : جيد هو قول الرب الذي تكلمت به . ثم قال : فكيف لا ، إن يكن سلام وأمان في أيامي '),
(5960, '2 Kings', 12, 20, 20, ' وبقية أمور حزقيا وكل جبروته ، وكيف عمل البركة والقناة وأدخل الماء إلى المدينة ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5961, '2 Kings', 12, 20, 21, ' ثم اضطجع حزقيا مع آبائه ، وملك منسى ابنه عوضا عنه '),
(5962, '2 Kings', 12, 21, 1, ' كان منسى ابن اثنتي عشرة سنة حين ملك ، وملك خمسا وخمسين سنة في أورشليم ، واسم أمه حفصيبة '),
(5963, '2 Kings', 12, 21, 2, ' وعمل الشر في عيني الرب ، حسب رجاسات الأمم الذين طردهم الرب من أمام بني إسرائيل '),
(5964, '2 Kings', 12, 21, 3, ' وعاد فبنى المرتفعات التي أبادها حزقيا أبوه ، وأقام مذابح للبعل ، وعمل سارية كما عمل أخآب ملك إسرائيل ، وسجد لكل جند السماء وعبدها '),
(5965, '2 Kings', 12, 21, 4, ' وبنى مذابح في بيت الرب الذي قال الرب عنه : في أورشليم أضع اسمي '),
(5966, '2 Kings', 12, 21, 5, ' وبنى مذابح لكل جند السماء في داري بيت الرب '),
(5967, '2 Kings', 12, 21, 6, ' وعبر ابنه في النار ، وعاف وتفاءل واستخدم جانا وتوابع ، وأكثر عمل الشر في عيني الرب لإغاظته '),
(5968, '2 Kings', 12, 21, 7, ' ووضع تمثال السارية التي عمل ، في البيت الذي قال الرب عنه لداود وسليمان ابنه : في هذا البيت وفي أورشليم ، التي اخترت من جميع أسباط إسرائيل ، أضع اسمي إلى الأبد '),
(5969, '2 Kings', 12, 21, 8, ' ولا أعود أزحزح رجل إسرائيل من الأرض التي أعطيت لآبائهم ، وذلك إذا حفظوا وعملوا حسب كل ما أوصيتهم به ، وكل الشريعة التي أمرهم بها عبدي موسى '),
(5970, '2 Kings', 12, 21, 9, ' فلم يسمعوا ، بل أضلهم منسى ليعملوا ما هو أقبح من الأمم الذين طردهم الرب من أمام بني إسرائيل '),
(5971, '2 Kings', 12, 21, 10, ' وتكلم الرب عن يد عبيده الأنبياء قائلا '),
(5972, '2 Kings', 12, 21, 11, ' من أجل أن منسى ملك يهوذا قد عمل هذه الأرجاس ، وأساء أكثر من جميع الذي عمله الأموريون الذين قبله ، وجعل أيضا يهوذا يخطئ بأصنامه '),
(5973, '2 Kings', 12, 21, 12, ' لذلك هكذا قال الرب إله إسرائيل : هأنذا جالب شرا على أورشليم ويهوذا حتى أن كل من يسمع به تطن أذناه '),
(5974, '2 Kings', 12, 21, 13, ' وأمد على أورشليم خيط السامرة ومطمار بيت أخآب ، وأمسح أورشليم كما يمسح واحد الصحن . يمسحه ويقلبه على وجهه '),
(5975, '2 Kings', 12, 21, 14, ' وأرفض بقية ميراثي ، وأدفعهم إلى أيدي أعدائهم ، فيكونون غنيمة ونهبا لجميع أعدائهم '),
(5976, '2 Kings', 12, 21, 15, ' لأنهم عملوا الشر في عيني ، وصاروا يغيظونني من اليوم الذي فيه خرج آباؤهم من مصر إلى هذا اليوم '),
(5977, '2 Kings', 12, 21, 16, ' وسفك أيضا منسى دما بريا كثيرا جدا حتى ملأ أورشليم من الجانب إلى الجانب ، فضلا عن خطيته التي بها جعل يهوذا يخطئ بعمل الشر في عيني الرب '),
(5978, '2 Kings', 12, 21, 17, ' وبقية أمور منسى وكل ما عمل ، وخطيته التي أخطأ بها ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5979, '2 Kings', 12, 21, 18, ' ثم اضطجع منسى مع آبائه ، ودفن في بستان بيته في بستان عزا ، وملك آمون ابنه عوضا عنه '),
(5980, '2 Kings', 12, 21, 19, ' كان آمون ابن اثنتين وعشرين سنة حين ملك ، وملك سنتين في أورشليم ، واسم أمه مشلمة بنت حاروص من يطبة '),
(5981, '2 Kings', 12, 21, 20, ' وعمل الشر في عيني الرب كما عمل منسى أبوه '),
(5982, '2 Kings', 12, 21, 21, ' وسلك في كل الطريق الذي سلك فيه أبوه ، وعبد الأصنام التي عبدها أبوه وسجد لها '),
(5983, '2 Kings', 12, 21, 22, ' وترك الرب إله آبائه ولم يسلك في طريق الرب '),
(5984, '2 Kings', 12, 21, 23, ' وفتن عبيد آمون عليه ، فقتلوا الملك في بيته '),
(5985, '2 Kings', 12, 21, 24, ' فضرب كل شعب الأرض جميع الفاتنين على الملك آمون ، وملك شعب الأرض يوشيا ابنه عوضا عنه '),
(5986, '2 Kings', 12, 21, 25, ' وبقية أمور آمون التي عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(5987, '2 Kings', 12, 21, 26, ' ودفن في قبره في بستان عزا ، وملك يوشيا ابنه عوضا عنه '),
(5988, '2 Kings', 12, 22, 1, ' كان يوشيا ابن ثمان سنين حين ملك ، وملك إحدى وثلاثين سنة في أورشليم ، واسم أمه يديدة بنت عداية من بصقة '),
(5989, '2 Kings', 12, 22, 2, ' وعمل المستقيم في عيني الرب ، وسار في جميع طريق داود أبيه ، ولم يحد يمينا ولا شمالا '),
(5990, '2 Kings', 12, 22, 3, ' وفي السنة الثامنة عشرة للملك يوشيا ، أرسل الملك شافان بن أصليا بن مشلام الكاتب إلى بيت الرب قائلا '),
(5991, '2 Kings', 12, 22, 4, ' اصعد إلى حلقيا الكاهن العظيم ، فيحسب الفضة المدخلة إلى بيت الرب التي جمعها حارسو الباب من الشعب '),
(5992, '2 Kings', 12, 22, 5, ' فيدفعوها ليد عاملي الشغل الموكلين ببيت الرب ، ويدفعوها إلى عاملي الشغل الذي في بيت الرب لترميم ثلم البيت '),
(5993, '2 Kings', 12, 22, 6, ' للنجارين والبنائين والنحاتين ، ولشراء أخشاب وحجارة منحوتة لأجل ترميم البيت '),
(5994, '2 Kings', 12, 22, 7, ' إلا أنهم لم يحاسبوا بالفضة المدفوعة لأيديهم ، لأنهم إنما عملوا بأمانة '),
(5995, '2 Kings', 12, 22, 8, ' فقال حلقيا الكاهن العظيم لشافان الكاتب : قد وجدت سفر الشريعة في بيت الرب . وسلم حلقيا السفر لشافان فقرأه '),
(5996, '2 Kings', 12, 22, 9, ' وجاء شافان الكاتب إلى الملك ، ورد على الملك جوابا وقال : قد أفرغ عبيدك الفضة الموجودة في البيت ودفعوها إلى يد عاملي الشغل وكلاء بيت الرب '),
(5997, '2 Kings', 12, 22, 10, ' وأخبر شافان الكاتب الملك قائلا : قد أعطاني حلقيا الكاهن سفرا . وقرأه شافان أمام الملك '),
(5998, '2 Kings', 12, 22, 11, ' فلما سمع الملك كلام سفر الشريعة مزق ثيابه '),
(5999, '2 Kings', 12, 22, 12, ' وأمر الملك حلقيا الكاهن ، وأخيقام بن شافان ، وعكبور بن ميخا ، وشافان الكاتب ، وعسايا عبد الملك قائلا '),
(6000, '2 Kings', 12, 22, 13, ' اذهبوا اسألوا الرب لأجلي ولأجل الشعب ولأجل كل يهوذا من جهة كلام هذا السفر الذي وجد ، لأنه عظيم هو غضب الرب الذي اشتعل علينا ، من أجل أن آباءنا لم يسمعوا لكلام هذا السفر ليعملوا حسب كل ما هو مكتوب علينا '),
(6001, '2 Kings', 12, 22, 14, ' فذهب حلقيا الكاهن وأخيقام وعكبور وشافان وعسايا إلى خلدة النبية ، امرأة شلوم بن تقوة بن حرحس حارس الثياب . وهي ساكنة في أورشليم في القسم الثاني وكلموها '),
(6002, '2 Kings', 12, 22, 15, ' فقالت لهم : هكذا قال الرب إله إسرائيل : قولوا للرجل الذي أرسلكم إلي '),
(6003, '2 Kings', 12, 22, 16, ' هكذا قال الرب : هأنذا جالب شرا على هذا الموضع وعلى سكانه ، كل كلام السفر الذي قرأه ملك يهوذا '),
(6004, '2 Kings', 12, 22, 17, ' من أجل أنهم تركوني وأوقدوا لآلهة أخرى لكي يغيظوني بكل عمل أيديهم ، فيشتعل غضبي على هذا الموضع ولا ينطفئ '),
(6005, '2 Kings', 12, 22, 18, ' وأما ملك يهوذا الذي أرسلكم لتسألوا الرب ، فهكذا تقولون له : هكذا قال الرب إله إسرائيل من جهة الكلام الذي سمعت '),
(6006, '2 Kings', 12, 22, 19, ' من أجل أنه قد رق قلبك ، وتواضعت أمام الرب حين سمعت ما تكلمت به على هذا الموضع وعلى سكانه أنهم يصيرون دهشا ولعنة ، ومزقت ثيابك وبكيت أمامي . قد سمعت أنا أيضا ، يقول الرب '),
(6007, '2 Kings', 12, 22, 20, ' لذلك هأنذا أضمك إلى آبائك ، فتضم إلى قبرك بسلام ، ولا ترى عيناك كل الشر الذي أنا جالبه على هذا الموضع . فردوا على الملك جوابا '),
(6008, '2 Kings', 12, 23, 1, ' وأرسل الملك ، فجمعوا إليه كل شيوخ يهوذا وأورشليم '),
(6009, '2 Kings', 12, 23, 2, ' وصعد الملك إلى بيت الرب وجميع رجال يهوذا وكل سكان أورشليم معه ، والكهنة والأنبياء وكل الشعب من الصغير إلى الكبير ، وقرأ في آذانهم كل كلام سفر الشريعة الذي وجد في بيت الرب '),
(6010, '2 Kings', 12, 23, 3, ' ووقف الملك على المنبر وقطع عهدا أمام الرب للذهاب وراء الرب ، ولحفظ وصاياه وشهاداته وفرائضه بكل القلب وكل النفس ، لإقامة كلام هذا العهد المكتوب في هذا السفر . ووقف جميع الشعب عند العهد '),
(6011, '2 Kings', 12, 23, 4, ' وأمر الملك حلقيا الكاهن العظيم ، وكهنة الفرقة الثانية ، وحراس الباب أن يخرجوا من هيكل الرب جميع الآنية المصنوعة للبعل وللسارية ولكل أجناد السماء ، وأحرقها خارج أورشليم في حقول قدرون ، وحمل رمادها إلى بيت إيل '),
(6012, '2 Kings', 12, 23, 5, ' ولاشى كهنة الأصنام الذين جعلهم ملوك يهوذا ليوقدوا على المرتفعات في مدن يهوذا وما يحيط بأورشليم ، والذين يوقدون : للبعل ، للشمس والقمر والمنازل ولكل أجناد السماء '),
(6013, '2 Kings', 12, 23, 6, ' وأخرج السارية من بيت الرب خارج أورشليم إلى وادي قدرون وأحرقها في وادي قدرون ، ودقها إلى أن صارت غبارا ، وذرى الغبار على قبور عامة الشعب '),
(6014, '2 Kings', 12, 23, 7, ' وهدم بيوت المأبونين التي عند بيت الرب ، حيث كانت النساء ينسجن بيوتا للسارية '),
(6015, '2 Kings', 12, 23, 8, ' وجاء بجميع الكهنة من مدن يهوذا ، ونجس المرتفعات حيث كان الكهنة يوقدون ، من جبع إلى بئر سبع ، وهدم مرتفعات الأبواب التي عند مدخل باب يشوع رئيس المدينة التي عن اليسار في باب المدينة '),
(6016, '2 Kings', 12, 23, 9, ' إلا أن كهنة المرتفعات لم يصعدوا إلى مذبح الرب في أورشليم بل أكلوا فطيرا بين إخوتهم '),
(6017, '2 Kings', 12, 23, 10, ' ونجس توفة التي في وادي بني هنوم لكي لا يعبر أحد ابنه أو ابنته في النار لمولك '),
(6018, '2 Kings', 12, 23, 11, ' وأباد الخيل التي أعطاها ملوك يهوذا للشمس عند مدخل بيت الرب عند مخدع نثنملك الخصي الذي في الأروقة ، ومركبات الشمس أحرقها بالنار '),
(6019, '2 Kings', 12, 23, 12, ' والمذابح التي على سطح علية آحاز التي عملها ملوك يهوذا ، والمذابح التي عملها منسى في داري بيت الرب ، هدمها الملك ، وركض من هناك وذرى غبارها في وادي قدرون '),
(6020, '2 Kings', 12, 23, 13, ' والمرتفعات التي قبالة أورشليم ، التي عن يمين جبل الهلاك ، التي بناها سليمان ملك إسرائيل لعشتورث رجاسة الصيدونيين ، ولكموش رجاسة الموآبيين ، ولملكوم كراهة بني عمون ، نجسها الملك '),
(6021, '2 Kings', 12, 23, 14, ' وكسر التماثيل وقطع السواري وملأ مكانها من عظام الناس '),
(6022, '2 Kings', 12, 23, 15, ' وكذلك المذبح الذي في بيت إيل في المرتفعة التي عملها يربعام بن نباط الذي جعل إسرائيل يخطئ ، فذانك المذبح والمرتفعة هدمهما وأحرق المرتفعة وسحقها حتى صارت غبارا ، وأحرق السارية '),
(6023, '2 Kings', 12, 23, 16, ' والتفت يوشيا فرأى القبور التي هناك في الجبل ، فأرسل وأخذ العظام من القبور وأحرقها على المذبح ونجسه ، حسب كلام الرب الذي نادى به رجل الله الذي نادى بهذا الكلام '),
(6024, '2 Kings', 12, 23, 17, ' وقال : ما هذه الصوة التي أرى ؟  . فقال له رجال المدينة : هي قبر رجل الله الذي جاء من يهوذا ، ونادى بهذه الأمور التي عملت على مذبح بيت إيل '),
(6025, '2 Kings', 12, 23, 18, ' فقال : دعوه . لا يحركن أحد عظامه . فتركوا عظامه وعظام النبي الذي جاء من السامرة '),
(6026, '2 Kings', 12, 23, 19, ' وكذا جميع بيوت المرتفعات التي في مدن السامرة التي عملها ملوك إسرائيل للإغاظة ، أزالها يوشيا ، وعمل بها حسب جميع الأعمال التي عملها في بيت إيل '),
(6027, '2 Kings', 12, 23, 20, ' وذبح جميع كهنة المرتفعات التي هناك على المذابح ، وأحرق عظام الناس عليها ، ثم رجع إلى أورشليم '),
(6028, '2 Kings', 12, 23, 21, ' وأمر الملك جميع الشعب قائلا : اعملوا فصحا للرب إلهكم ، كما هو مكتوب في سفر العهد هذا '),
(6029, '2 Kings', 12, 23, 22, ' إنه لم يعمل مثل هذا الفصح منذ أيام القضاة الذين حكموا على إسرائيل ، ولا في كل أيام ملوك إسرائيل وملوك يهوذا '),
(6030, '2 Kings', 12, 23, 23, ' ولكن في السنة الثامنة عشرة للملك يوشيا ، عمل هذا الفصح للرب في أورشليم '),
(6031, '2 Kings', 12, 23, 24, ' وكذلك السحرة والعرافون والترافيم والأصنام وجميع الرجاسات التي رئيت في أرض يهوذا وفي أورشليم ، أبادها يوشيا ليقيم كلام الشريعة المكتوب في السفر الذي وجده حلقيا الكاهن في بيت الرب '),
(6032, '2 Kings', 12, 23, 25, ' ولم يكن قبله ملك مثله قد رجع إلى الرب بكل قلبه وكل نفسه وكل قوته حسب كل شريعة موسى ، وبعده لم يقم مثله '),
(6033, '2 Kings', 12, 23, 26, ' ولكن الرب لم يرجع عن حمو غضبه العظيم ، لأن غضبه حمي على يهوذا من أجل جميع الإغاظات التي أغاظه إياها منسى '),
(6034, '2 Kings', 12, 23, 27, ' فقال الرب : إني أنزع يهوذا أيضا من أمامي كما نزعت إسرائيل ، وأرفض هذه المدينة التي اخترتها : أورشليم ، والبيت الذي قلت يكون اسمي فيه '),
(6035, '2 Kings', 12, 23, 28, ' وبقية أمور يوشيا وكل ما عمل ، أما هي مكتوبة في سفر أخبار الأيام لملوك يهوذا '),
(6036, '2 Kings', 12, 23, 29, ' في أيامه صعد فرعون نخو ملك مصر على ملك أشور إلى نهر الفرات . فصعد الملك يوشيا للقائه ، فقتله في مجدو حين رآه '),
(6037, '2 Kings', 12, 23, 30, ' وأركبه عبيده ميتا من مجدو ، وجاءوا به إلى أورشليم ودفنوه في قبره . فأخذ شعب الأرض يهوآحاز بن يوشيا ومسحوه وملكوه عوضا عن أبيه '),
(6038, '2 Kings', 12, 23, 31, ' كان يهوآحاز ابن ثلاث وعشرين سنة حين ملك ، وملك ثلاثة أشهر في أورشليم ، واسم أمه حموطل بنت إرميا من لبنة '),
(6039, '2 Kings', 12, 23, 32, ' فعمل الشر في عيني الرب حسب كل ما عمله آباؤه '),
(6040, '2 Kings', 12, 23, 33, ' وأسره فرعون نخو في ربلة في أرض حماة لئلا يملك في أورشليم ، وغرم الأرض بمئة وزنة من الفضة ووزنة من الذهب '),
(6041, '2 Kings', 12, 23, 34, ' وملك فرعون نخو ألياقيم بن يوشيا عوضا عن يوشيا أبيه ، وغير اسمه إلى يهوياقيم ، وأخذ يهوآحاز وجاء إلى مصر فمات هناك '),
(6042, '2 Kings', 12, 23, 35, ' ودفع يهوياقيم الفضة والذهب لفرعون ، إلا أنه قوم الأرض لدفع الفضة بأمر فرعون . كل واحد حسب تقويمه . فطالب شعب الأرض بالفضة والذهب ليدفع لفرعون نخو '),
(6043, '2 Kings', 12, 23, 36, ' كان يهوياقيم ابن خمس وعشرين سنة حين ملك ، وملك إحدى عشرة سنة في أورشليم ، واسم أمه زبيدة بنت فداية من رومة '),
(6044, '2 Kings', 12, 23, 37, ' وعمل الشر في عيني الرب حسب كل ما عمل آباؤه '),
(6045, '2 Kings', 12, 24, 1, ' في أيامه صعد نبوخذناصر ملك بابل ، فكان له يهوياقيم عبدا ثلاث سنين . ثم عاد فتمرد عليه '),
(6046, '2 Kings', 12, 24, 2, ' فأرسل الرب عليه غزاة الكلدانيين ، وغزاة الأراميين ، وغزاة الموآبيين ، وغزاة بني عمون وأرسلهم على يهوذا ليبيدها حسب كلام الرب الذي تكلم به عن يد عبيده الأنبياء '),
(6047, '2 Kings', 12, 24, 3, ' إن ذلك كان حسب كلام الرب على يهوذا لينزعهم من أمامه لأجل خطايا منسى حسب كل ما عمل '),
(6048, '2 Maccabees', 73, 1, 1, 'الى الاخوة اليهود الذين في مصر سلام اليكم من الاخوة اليهود الذين في اورشليم وبلاد اليهودية اطيب السلام'),
(6049, '2 Maccabees', 73, 1, 2, 'ليبارككم الله ويذكر عهده مع ابراهيم واسحق ويعقوب عبيده الامناء'),
(6050, '2 Maccabees', 73, 1, 3, 'و ليؤتكم جميعا قلبا لان تعبدوه وتصنعوا مشيئته بصدر مشروح ونفس راضية'),
(6051, '2 Maccabees', 73, 1, 4, 'و يفتح قلوبكم لشريعته ووصاياه ويجعلكم في سلام'),
(6052, '2 Maccabees', 73, 1, 5, 'و ليستجب لصلواتكم ويتب عليكم ولا يخذلكم في اوان السوء'),
(6053, '2 Maccabees', 73, 1, 6, 'و نحن ههنا نصلي من اجلكم'),
(6054, '2 Maccabees', 73, 1, 7, 'كنا نحن اليهود قد كتبنا اليكم في عهد ديمتريوس في السنة المئة والتاسعة والستين حين الضيق والشدة التي نزلت بنا في تلك السنين بعد انصراف ياسون والذين معه من الارض المقدسة والمملكة'),
(6055, '2 Maccabees', 73, 1, 8, 'فانهم احرقوا الباب وسفكوا الدم الزكي فابتهلنا الى الرب فاستجاب لنا وقربنا الذبيحة والسميذ واوقدنا السرج وقدمنا الخبز'),
(6056, '2 Maccabees', 73, 1, 9, 'فالان عليكم ان تعيدوا ايام المظال التي في شهر كسلو'),
(6057, '2 Maccabees', 73, 1, 10, 'في السنة المئة والثامنة والثمانين من سكان اورشليم واليهودية والشيوخ ويهوذا الى ارسطوبولس مؤدب بطلماوس الملك الذي من ذرية الكهنة المسحاء والى اليهود الذين في مصر سلام وعافية'),
(6058, '2 Maccabees', 73, 1, 11, 'نشكر الله الشكر الجزيل على انه خلصنا من اخطار جسيمة عند مناصبتنا للملك'),
(6059, '2 Maccabees', 73, 1, 12, 'و دحر الذين يقاتلوننا في المدينة المقدسة'),
(6060, '2 Maccabees', 73, 1, 13, 'فانه اذ كان الملك في فارس يقود جيشا لا يثبت امامه احد نكبوا في هيكل النناية بحيلة احتالها عليهم كهنة النناية'),
(6061, '2 Maccabees', 73, 1, 14, 'و ذلك انه جاء انطيوكس ومن معه من اصحابه الى هناك متظاهرا بانه يريد ان يقارنها وفي نفسه ان ياخذ الاموال على سبيل الصداق'),
(6062, '2 Maccabees', 73, 1, 15, 'فابرز كهنة النناية الاموال ودخل هو مع نفر يسير الى داخل المعبد ثم اغلقوا الهيكل'),
(6063, '2 Maccabees', 73, 1, 16, 'فلما دخل انطيوكس فتحوا بابا خفيا كان في ارض الهيكل وقذفوا حجارة رجموا بها القائد ثم قطعوهم قطعا وحزوا رؤوسهم والقوها الى الذين كانوا في الخارج'),
(6064, '2 Maccabees', 73, 1, 17, 'ففي كل شيء تبارك الهنا الذي اسلم الكفرة'),
(6065, '2 Maccabees', 73, 1, 18, 'وبعد فإذ كنا مزمعين ان نعيد عيد تطهير الهيكل في اليوم الخامس والعشرين من شهر كسلو راينا من الواجب ان نعلن اليكم انتعيدوا انتم ايضا عيد المظال والنار التي ظهرت حين بنى نحميا الهيكل والمذبح وقدم الذبيحة'),
(6066, '2 Maccabees', 73, 1, 19, 'فانه حين اجلي اباؤنا الى فارس اخذ بعض اتقياء الكهنة من نار المذبح سرا وخباوها في جوف بئر لا ماء فيها وحافظوا عليها بحيث بقي الموضع مجهولا عند الجميع'),
(6067, '2 Maccabees', 73, 1, 20, 'و بعد انقضاء سنين كثيرة حين شاء الله ارسل ملك فارس نحميا الى هنا فبعث اعقاب الكهنة الذين خباوا النار لالتماسها الا انهم كما حدثونا لم يجدوا نارا بل ماء خاثرا'),
(6068, '2 Maccabees', 73, 1, 21, 'فامرهم ان يغرفوا وياتوا به ولما احضرت الذبائح امر نحميا الكهنة ان ينضحوا بهذا الماء الخشب والموضوع عليه'),
(6069, '2 Maccabees', 73, 1, 22, 'فصنعوا كذلك ولما برزت الشمس وقد كانت محجوبة بالغيم اتقدت نار عظيمة حتى تعجب الجميع'),
(6070, '2 Maccabees', 73, 1, 23, 'و عند احراق الذبيحة كان الكهنة كلهم يصلون وكان يوناتان يبدا والباقون يجيبونه'),
(6071, '2 Maccabees', 73, 1, 24, 'و هذا ما صلى به نحميا ايها الرب الرب الاله خالق الكل المرهوب القوي العادل الرحيم يا من هو وحده الملك والبار'),
(6072, '2 Maccabees', 73, 1, 25, 'يا من هو وحده المتفضل العادل القدير الازلي مخلص اسرائيل من كل شر الذي اصطفى اباءنا وقدسهم'),
(6073, '2 Maccabees', 73, 1, 26, 'تقبل الذبيحة من اجل جميع شعبك اسرائيل وصن ميراثك وقدسه'),
(6074, '2 Maccabees', 73, 1, 27, 'و اجمع شتاتنا واعتق المستعبدين عند الامم وانظر الى الممتهنين والممقوتين ولتعلم الامم انك انت الهنا'),
(6075, '2 Maccabees', 73, 1, 28, 'و عاقب الظالمين والقاذفين بتجبر'),
(6076, '2 Maccabees', 73, 1, 29, 'و اغرس شعبك في مكانك المقدس كما قال موسى'),
(6077, '2 Maccabees', 73, 1, 30, 'و كان الكهنة يرنمون بالاناشيد'),
(6078, '2 Maccabees', 73, 1, 31, 'و لما احرقت الذبيحة امر نحميا بان يريقوا ما بقي من الماء على الحجارة الكبيرة'),
(6079, '2 Maccabees', 73, 1, 32, 'فلما صنعوا ذلك اتقد اللهيب فاطفاه النور المنبعث من المذبح'),
(6080, '2 Maccabees', 73, 1, 33, 'فشاع ذلك واخبر ملك فارس ان الموضع الذي خبا فيه الكهنة النار حين جلائهم قد ظهر فيه ماء وبه طهر الذين مع نحميا الذبيحة'),
(6081, '2 Maccabees', 73, 1, 34, 'فسيجه الملك وصيره مقدسا بعد الفحص عن الامر'),
(6082, '2 Maccabees', 73, 1, 35, 'و انعطف الملك اليهم واخذ عطايا كثيرة ووهبها لهم'),
(6083, '2 Maccabees', 73, 1, 36, 'و سماه الذين مع نحميا نفطار اي تطهيرا ويعرف عند كثيرين بنفطاي'),
(6084, '2 Maccabees', 73, 2, 1, 'قد جاء في السجلات ان ارميا النبي امر اهل الجلاء ان ياخذوا النار كما ذكر وكما امر النبي اهل الجلاء'),
(6085, '2 Maccabees', 73, 2, 2, 'اذ اوصاهم ان لا ينسوا وصايا الرب ولا تغوى قلوبهم اذا راوا تماثيل الذهب والفضة وما عليها من الزينة'),
(6086, '2 Maccabees', 73, 2, 3, 'و حرضهم بمثل هذا الكلام على ان لا يزيلوا الشريعة من قلوبهم'),
(6087, '2 Maccabees', 73, 2, 4, 'و جاء في هذه الكتابة ان النبي بمقتضى وحي سار اليه امر ان يذهب معه بالمسكن والتابوت حتى يصل الى الجبل الذي صعد اليه موسى وراى ميراث الله'),
(6088, '2 Maccabees', 73, 2, 5, 'و لما وصل ارميا وجد كهفا فادخل اليه المسكن والتابوت ومذبح البخور ثم سد الباب'),
(6089, '2 Maccabees', 73, 2, 6, 'فاقبل بعض من كانوا معه ليسموا الطريق فلم يستطيعوا ان يجدوه'),
(6090, '2 Maccabees', 73, 2, 7, 'فلما اعلم بذلك ارميا لامهم وقال ان هذا الموضع سيبقى مجهولا الى ان يجمع الله شمل الشعب ويرحمهم'),
(6091, '2 Maccabees', 73, 2, 8, 'و حينئذ يبرز الرب هذه الاشياء ويبدو مجد الرب والغمام كما ظهر في ايام موسى وحين سال سليمان ان يقدس الموضع تقديسا بهيا'),
(6092, '2 Maccabees', 73, 2, 9, 'اذ اشتهر وابدى حكمته بتقديم الذبيحة لتدشين الهيكل وتتميمه'),
(6093, '2 Maccabees', 73, 2, 10, 'فكما دعا موسى الرب فنزلت النار من السماء وافنت الذبيحة كذلك دعا سليمان فنزلت النار من السماء وافنت المحرقات'),
(6094, '2 Maccabees', 73, 2, 11, 'و قال موسى انما افنيت ذبيحة الخطيئة لانها لم تؤكل'),
(6095, '2 Maccabees', 73, 2, 12, 'و كذلك عيد سليمان للتدشين ثمانية الايام'),
(6096, '2 Maccabees', 73, 2, 13, 'و قد شرح ذلك في السجلات والتذاكر التي لنحميا وكيف انشا مكتبة جمع فيها اخبار الملوك والانبياء وكتابات داود ورسائل الملوك في التقادم'),
(6097, '2 Maccabees', 73, 2, 14, 'و كذلك جمع يهوذا كل ما فقد منا في الحرب التي حدثت لنا وهو عندنا'),
(6098, '2 Maccabees', 73, 2, 15, 'فان كانت لكم حاجة بذلك فارسلوا من ياخذه اليكم'),
(6099, '2 Maccabees', 73, 2, 16, 'و اذ قد ازمعنا ان نعيد عيد التطهير كتبنا اليكم وانكم لتحسنون الصنع اذا عيدتم هذه الايام'),
(6100, '2 Maccabees', 73, 2, 17, 'و الله الذي خلص جميع شعبه ورد على الجميع الميراث والملك والكهنوت والمقدس'),
(6101, '2 Maccabees', 73, 2, 18, 'كما وعد في الشريعة نرجو منه ان يرحمنا قريبا ويجمعنا مما تحت السماء الى الموضع المقدس'),
(6102, '2 Maccabees', 73, 2, 19, 'فانه قد انقذنا من شرور عظيمة وطهر الموضع'),
(6103, '2 Maccabees', 73, 2, 20, 'ان الحوادث التي وقعت ليهوذا المكابي واخوته وتطهير الهيكل العظيم وتدشين المذبح'),
(6104, '2 Maccabees', 73, 2, 21, 'و الحروب التي وقعت مع انطيوكس الشهير وابنه اوباطور'),
(6105, '2 Maccabees', 73, 2, 22, 'و الايات التي ظهرت من السماء في حقل الذين تحمسوا لدين اليهود حتى انهم مع قلتهم تسلطوا على البلاد بجملتها وطردوا جماهير الاعاجم'),
(6106, '2 Maccabees', 73, 2, 23, 'و استردوا الهيكل الذي اشتهر ذكره في المسكونة باسرها وحرروا المدينة واحيوا الشرائع التي كادت تضمحل لان الرب عطف عليهم بكثرة مراحمه'),
(6107, '2 Maccabees', 73, 2, 24, 'تلك الامور التي شرحها ياسون القيرواني في خمسة كتب قد اقبلنا نحن على اختصارها في درج واحد'),
(6108, '2 Maccabees', 73, 2, 25, 'و لما راينا تكاثر الحوادث والصعوبة التي تعترض من اراد الخوض في اخبار التاريخ لكثرة المواد'),
(6109, '2 Maccabees', 73, 2, 26, 'كان من همنا ان نجعل فيما كتبناه فكاهة للمطالع وسهولة للحافظ وفائدة للجميع'),
(6110, '2 Maccabees', 73, 2, 27, 'فلم يكن تكلفنا لهذا الاختصار امرا سهلا وانما تم بالعرق والسهر'),
(6111, '2 Maccabees', 73, 2, 28, 'كما ان الذي يعد مادبة ويبتغي بها منفعة الناس لا يكون الامر عليه سهلا غير انا لاجل مرضاة الكثيرين سنتحمل هذا النصب عن طيبة نفس'),
(6112, '2 Maccabees', 73, 2, 29, 'تاركين التدقيق في تفاصيل الحوادث لاصحاب التاريخ وملتزمين في الاختصار استقراء اهم الوقائع'),
(6113, '2 Maccabees', 73, 2, 30, 'فانه كما ينبغي لمن يهندس بيتا جديدا ان يهتم بجميع اجزاء البنيان ولمن يباشر الوسم والتصوير ان يتطلب اسباب الزينة هكذا ما نحن فيه على ما ارى'),
(6114, '2 Maccabees', 73, 2, 31, 'فان التبحر والكلام على كل امر والبحث عن جزء فجزء من شان مصنف التاريخ'),
(6115, '2 Maccabees', 73, 2, 32, 'و اما الملخص فمرخص له ان يسوق الحديث باختصار مع اهمال التدقيق في المباحث'),
(6116, '2 Maccabees', 73, 2, 33, 'و ههنا نشرع في ايراد الحوادث مقتصرين من التمهيد على ما ذكرناه اذ ليس من الاصابة الاطناب فيما قبل التاريخ والايجاز في التاريخ'),
(6117, '2 Maccabees', 73, 3, 1, 'حين كانت المدينة المقدسة عامرة امنة والشرائع محفوظة غاية الحفظ لما كان عليه اونيا الكاهن الاعظم من الورع والبغض للشر'),
(6118, '2 Maccabees', 73, 3, 2, 'كان الملوك انفسهم يعظمون المقدس ويكرمون الهيكل بافخر التقادم'),
(6119, '2 Maccabees', 73, 3, 3, 'حتى ان سلوقس ملك اسية كان يؤدي من دخله الخاص جميع النفقات المختصة بتقديم الذبائح'),
(6120, '2 Maccabees', 73, 3, 4, 'و ان رجلا اسمه سمعان من سبط بنيامين كان مقلدا الوكالة على الهيكل وقعت مخاصمة بينه وبين الكاهن الاعظم لاجل ظلم جناه علىالمدينة'),
(6121, '2 Maccabees', 73, 3, 5, 'و اذ لم يمكنه التغلب على اونيا انطلق الى ابلونيوس بن ترساوس وكان اذ ذاك قائدا في بقاع سورية وفينيقية'),
(6122, '2 Maccabees', 73, 3, 6, 'و اخبره ان الخزانة التي في اورشليم مشحونة من الاموال بما لا يستطاع وصفه حتى ان الدخل لا يحصى لكثرته وان ذلك ليس بمختص بنفقة الذبائح فيتهيا للملك ادخال ذلك كله في حوزته'),
(6123, '2 Maccabees', 73, 3, 7, 'ففاوض ابلونيوس الملك واعلمه بالاموال التي وصفت له فاختار هليودورس قيم المصالح وارسله وامره بجلب الاموال المذكورة'),
(6124, '2 Maccabees', 73, 3, 8, 'فتوجه هليودورس لساعته قاصدا في الظاهر التطوف في مدن بقاع سورية وفينيقية وكان في الواقع يقصد انفاذ مرام الملك'),
(6125, '2 Maccabees', 73, 3, 9, 'فلما جاء اورشليم احسن الكاهن الاعظم ملتقاه فحدثه بما كوشفوا به وصرح له بسبب قدومه وساله هل الامر في الحقيقة كماذكر له'),
(6126, '2 Maccabees', 73, 3, 10, 'فذكر له الكاهن الاعظم ان المال هو ودائع للارامل واليتامى'),
(6127, '2 Maccabees', 73, 3, 11, 'و ان قسما منه لهركانس بن طوبيا احد عظماء الاشراف ثم ان الامر ليس على ما وشى به سمعان المنافق وانما المال كله اربعون قنطار فضة ومئتا قنطار ذهب'),
(6128, '2 Maccabees', 73, 3, 12, 'فلا يجوز بوجه من الوجوه هضم الذين ائتمنوا قداسة الموضع ومهابة وحرمة الهيكل المكرم في المسكونة كلها'),
(6129, '2 Maccabees', 73, 3, 13, 'لكن هليودورس بناء على امر الملك اصر على حمل الاموال الى خزانة الملك'),
(6130, '2 Maccabees', 73, 3, 14, 'و عين يوما دخل فيه للفحص عن ذلك فكان في جميع المدينة ارتعاش شديد'),
(6131, '2 Maccabees', 73, 3, 15, 'و انطرح الكهنة امام المذبح بحللهم الكهنوتية يبتهلون نحو السماء الى الذي سن في الودائع ان تصان لمستودعها'),
(6132, '2 Maccabees', 73, 3, 16, 'و كان من راى وجه الكاهن الاعظم يتفطر فؤاده لان منظره وامتقاع لونه كانا ينبئان بما في نفسه من الارتعاش'),
(6133, '2 Maccabees', 73, 3, 17, 'اذ كان الرجل قد اشتمل عليه الرعب والقشعريرة فكانا يدلان الرائين على ما في قلبه من الكابة'),
(6134, '2 Maccabees', 73, 3, 18, 'و كان الناس يتبادرون من البيوت افواجا ليصلوا صلاة عامة لسبب الهوان المشرف على الموضع'),
(6135, '2 Maccabees', 73, 3, 19, 'و كانت النساء يزدحمن في الشوارع وهن متحزمات بالمسوح تحت ثديهن والعذارى ربات الخدور يتجارين بعضهن الى الابواب وبعضهن الى الاسوار واخريات يتطلعن من الكوى'),
(6136, '2 Maccabees', 73, 3, 20, 'و كلهن باسطات ايديهن الى السماء يتضرعن بالابتهال'),
(6137, '2 Maccabees', 73, 3, 21, 'فكان انكسار الجمهور وانتظار الكاهن الاعظم وهو في ارتعاش شديد مما يصدع القلب رحمة'),
(6138, '2 Maccabees', 73, 3, 22, 'و كانوا يتضرعون الى الاله القدير ان يحفظ الودائع موفوره لمستودعيها'),
(6139, '2 Maccabees', 73, 3, 23, 'اما هليودورس فكان اخذا في اتمام ما قضى به وقد حضر هناك مع شرطه في الخزانة'),
(6140, '2 Maccabees', 73, 3, 24, 'فصنع رب ابائنا وسلطان كل قدرة اية عظيمة حتى ان جميع الذين اجتراوا على الدخول صرعتهم قدرة الله واخذهم الانحلال والرعب'),
(6141, '2 Maccabees', 73, 3, 25, 'و ذلك انه ظهر لهم فرس عليه راكب مخيف وجهازه فاخر فوثب وضرب هليودورس بحوافر يديه وكانت عدة الراكب كانها من ذهب'),
(6142, '2 Maccabees', 73, 3, 26, 'و تراءى ايضا لهليودورس فتيان عجيبا القوة بديعا البهاء حسنا اللباس فوقفا على جانبيه يجلدانه جلدا متواصلا حتى اثخناه بالضرب'),
(6143, '2 Maccabees', 73, 3, 27, 'فسقط لساعته على الارض وغشيه ظلام كثيف فرفعوه وجعلوه على محمل'),
(6144, '2 Maccabees', 73, 3, 28, 'فاذا به بعد ان دخل الخزانة المذكورة في موكب حافل وجند كثير قد اصبح محمولا لا مغيث له وقد تجلت لهم قدرة الله علانية'),
(6145, '2 Maccabees', 73, 3, 29, 'فكان مطروحا بالقوة الالهية ابكم منقطع الرجاء من الخلاص'),
(6146, '2 Maccabees', 73, 3, 30, 'و اليهود يباركون الرب الذي مجد مقدسه وقد امتلا الهيكل ابتهاجا وتهللا اذ تجلى فيه الرب القدير بعدما كان قبيل ذلك مملوء اخوفا واضطرابا'),
(6147, '2 Maccabees', 73, 3, 31, 'فبادر بعض من اصحاب هليودورس وسالوا اونيا ان يبتهل الى العلي ويمن عليه بالحياة اذ كان قد اصبح على اخر رمق'),
(6148, '2 Maccabees', 73, 3, 32, 'فخالج قلب الكاهن الاعظم ان الملك ربما اتهم اليهود بمكيدة كادوها لهليودورس فقدم الذبيحة من اجل خلاص الرجل'),
(6149, '2 Maccabees', 73, 3, 33, 'و بينما الكاهن الاعظم يقدم الكفارة اذ عاد ذانك الفتيان فظهر لهليودورس بلباسهما الاول ووقفا وقالا عليك بجزيل الشكر لاونيا الكاهن الاعظم فان الرب قد من عليك بالحياة من اجله'),
(6150, '2 Maccabees', 73, 3, 34, 'و انت ايها المجلود فاخبر الجميع بقدرة الله العظيمة قالا ذلك وغابا عن النظر'),
(6151, '2 Maccabees', 73, 3, 35, 'فقدم هليودورس ذبيحة للرب وصلى اليه صلوات عظيمة على انه من عليه بالحياة وشكر اونيا ورجع بجيشه الى الملك'),
(6152, '2 Maccabees', 73, 3, 36, 'و كان يعترف امام الجميع بما عاينه من اعمال الله العظيم'),
(6153, '2 Maccabees', 73, 3, 37, 'و سال الملك هليودورس من ترى يكون اهلا لان نعود فنرسله الى اورشليم فقال'),
(6154, '2 Maccabees', 73, 3, 38, 'ان كان لك عدو او صاحب دسيسة في المملكة فارسله الى هناك فيرجع اليك مجلودا ان نجا فان في ذلك الموضع قدرة الهية لا محالة'),
(6155, '2 Maccabees', 73, 3, 39, 'لان الذي مسكنه في السماء هو يراقب الموضع ويدافع عنه فيضرب الذين يقصدون بالشر ويهلكهم'),
(6156, '2 Maccabees', 73, 3, 40, 'هذا ما كان من امر هليودورس وحماية الخزانة'),
(6157, '2 Maccabees', 73, 4, 1, 'و كان سمعان المذكور الذي وشى في امر الاموال والوطن يقذف اونيا كانه هو اغرى هليودورس بذلك وجلب عليه ذلك الشر'),
(6158, '2 Maccabees', 73, 4, 2, 'و بلغ من وقاحته انه وصف المحسن الى المدينة والقائم بمصلحة اهل وطنه والغيور على الشريعة بانه صاحب دسيسة'),
(6159, '2 Maccabees', 73, 4, 3, 'فاشتدت العداوة حتى ان احد خواص سمعان شرع في القتل'),
(6160, '2 Maccabees', 73, 4, 4, 'فلما تبين اونيا ما في ذلك الخصام من الخطر مع حماقة ابلونيوس قائد بقاع سورية وفينيقية الذي كان يمد سمعان في خبثه قصد الملك'),
(6161, '2 Maccabees', 73, 4, 5, 'لا واشيا باهل وطنه ولكن ابتغاء لمصالح تعم الشعب برمته'),
(6162, '2 Maccabees', 73, 4, 6, 'لانه راى انه بغير عناية الملك لا يمكن ان تكون الاحوال في سلام ولا ان يقلع سمعان عن رعونته'),
(6163, '2 Maccabees', 73, 4, 7, 'و كان انه بعد وفاة سلوقس واستيلاء انطيوكس الملقب بالشهير على الملك طمع ياسون اخو اونيا في الكهنوت الاعظم'),
(6164, '2 Maccabees', 73, 4, 8, 'فوفد على الملك ووعده بثلاث مئة وستين قنطار فضة وبثمانين قنطارا من دخل اخر'),
(6165, '2 Maccabees', 73, 4, 9, 'و ما عدا ذلك ضمن له مئة وخمسين قنطارا غيرها ان رخص له بسلطة الملك في اقامة مدرسة للتروض وموضع للغلمان وان يكتتب اهل اورشليم في رعوية انطاكية'),
(6166, '2 Maccabees', 73, 4, 10, 'فاجابه الملك الى ذلك فتقلد الرئاسة وما لبث ان صرف شعبه الى عادات الامم'),
(6167, '2 Maccabees', 73, 4, 11, 'و الغى الاختصاصات التي انعم بها الملوك على اليهود على يد يوحنا ابي اوبولمس الذي قلد السفارة الى الرومانيين في عقد الموالاة والمناصرة وابطل رسوم الشريعة وادخل سننا تخالف الشريعة'),
(6168, '2 Maccabees', 73, 4, 12, 'و بادر فاقام مدرسة للتروض تحت القلعة وساق نخبة الغلمان فجعلهم تحت القبعة'),
(6169, '2 Maccabees', 73, 4, 13, 'فتمكن الميل الى عادات اليونان والتخلق باخلاق الاجانب بشدة فجور ياسون الذي هو كافر لا كاهن اعظم'),
(6170, '2 Maccabees', 73, 4, 14, 'حتى ان الكهنة لم يعودوا يحرصون على خدمة المذبح واستهانوا بالهيكل واهملوا الذبائح لينالوا حظا في جوائز الملعب المحرمة بعد المباراة في رمي المطاث'),
(6171, '2 Maccabees', 73, 4, 15, 'و كانوا يستخفون بماثر ابائهم ويتنافسون بمفاخر اليونان'),
(6172, '2 Maccabees', 73, 4, 16, 'فلذلك احاقت بهم رزيئة شديدة فان الذين اولعوا برسومهم وحرصوا على التشبه بهم هم صاروا اعداء لهم ومنتقمين'),
(6173, '2 Maccabees', 73, 4, 17, 'لان النفاق في الشريعة الالهية لا يذهب سدى كما يشهد بذلك ما سيجيء'),
(6174, '2 Maccabees', 73, 4, 18, 'و لما جرت في صور المصارعة التي تجري كل سنة خامسة والملك حاضر'),
(6175, '2 Maccabees', 73, 4, 19, 'انفذ ياسون الخبيث رسلا من اورشليم انطاكيي الرعوية ومعهم ثلاث مئة درهم فضة لذبيحة هركليس لكن هؤلاء طلبوا ان لا تنفق على الذبيحة لان ذلك كان غير لائق بل تنفق في شيء اخر'),
(6176, '2 Maccabees', 73, 4, 20, 'فكان هذا المال في قصد مرسله لذبيحة هركليس لكنه بسعي الذين حملوه انفق في بناء سفن ثلاثية'),
(6177, '2 Maccabees', 73, 4, 21, 'و ارسل ابولنيوس بن منستاوس الى مصر لمبايعة بطلماوس فيلوماتور الملك فعلم انطيوكس انه قد نحي عن تدبير الامور فوجه اهتمامه الى تحصين نفسه ورجع الى يافا ثم سار الى اورشليم'),
(6178, '2 Maccabees', 73, 4, 22, 'فاستقبله ياسون واهل المدينة استقبالا جليلا ودخل بين المشاعل والهتاف ثم انصرف من هناك بالجيش الى فينيقية'),
(6179, '2 Maccabees', 73, 4, 23, 'و بعد مدة ثلاث سنين وجه ياسون منلاوس اخا سمعان المذكور ليحمل اموالا للملك ويفاوضه في امور مهمة'),
(6180, '2 Maccabees', 73, 4, 24, 'فتزلف الى الملك واطرا عظمة سلطانه واحال الكهنوت الاعظم الى نفسه بان زاد ثلاث مئة قنطار فضة على ما اعطى ياسون'),
(6181, '2 Maccabees', 73, 4, 25, 'ثم رجع ومعه اوامر الملك ولم يكن على شيء مما يليق بالكهنوت الاعظم وانما كانت له اخلاق غاشم عنيف واحقاد وحش ضار');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(6182, '2 Maccabees', 73, 4, 26, 'و هكذا فان ياسون الذي ختل اخاه ختله اخر فطرد وفر الى ارض بني عمون'),
(6183, '2 Maccabees', 73, 4, 27, 'و استولى منلاوس على الرئاسة الا انه لم يوف شيئا من الاموال التي كان وعد بها الملك'),
(6184, '2 Maccabees', 73, 4, 28, 'فكان سستراتس رئيس القلعة يطالبه لانه كان مولي امر الجباية ولهذا السبب استدعيا كلاهما الى الملك'),
(6185, '2 Maccabees', 73, 4, 29, 'فاستخلف منلاوس ليسيماكس اخاه على الكهنوت الاعظم واستخلف سستراتس كراتيس والي القبرسيين'),
(6186, '2 Maccabees', 73, 4, 30, 'و حدث بعد ذلك ان اهل طرسوس وملو تمردوا لانهم جعلوا هبة لانطيوكيس سرية الملك'),
(6187, '2 Maccabees', 73, 4, 31, 'فبادر الملك لاطفاء الفتنة واستخلف مكانه اندرونكس احد ذوي المناصب'),
(6188, '2 Maccabees', 73, 4, 32, 'فراى منلاوس انه قد اصاب فرصة فسرق من الهيكل انية من الذهب اهدى بعضها الى اندرونكس وباع بعضها في صور والمدن التيبجوارها'),
(6189, '2 Maccabees', 73, 4, 33, 'و لما تيقن اونيا ذلك حجه به وكان قد انصرف الى حمى بدفنة بالقرب من انطاكية'),
(6190, '2 Maccabees', 73, 4, 34, 'فخلا منلاوس باندرونكس واغراه ان يقبض على اونيا فصار الى اونيا وخدعه بمكره وعاقده بقسم حتى حمله على الخروج من الحمى وان كان غير واثق به ثم اغتاله من ساعته ولم يرع للعدل حرمة'),
(6191, '2 Maccabees', 73, 4, 35, 'فوقع ذلك موقع المقت عند اليهود بل عند كثير من سائر الامم وشق عليهم قتل الرجل بغيا'),
(6192, '2 Maccabees', 73, 4, 36, 'فلما رجع الملك من نواحي قيلقية رفع اليه يهود المدينة مع ساءته هذه الجناية من اليونانيين مقتل اونيا عدوانا'),
(6193, '2 Maccabees', 73, 4, 37, 'فتاسف انطيوكس ورق رحمة وبكى على حكمة ذلك المفقود وكثرة ادبه'),
(6194, '2 Maccabees', 73, 4, 38, 'و اضطرم غضبا ولساعته نزع الارجوان عن اندرونكس ومزق حلله واطافه في المدينة كلها ثم اباد ذلك القاتل في الموضع الذي فتك فيه باونيا فانزل به الرب العقوبة التي استحقها'),
(6195, '2 Maccabees', 73, 4, 39, 'و كان ليسيماكس في المدينة قد سلب باغراء منلاوس كثيرا من مال الاقداس فذاع الخبر في الخارج بان قد اخذ كثير من الذهب فاجتمع الجمهور على ليسيماكس'),
(6196, '2 Maccabees', 73, 4, 40, 'فلما راى ليسيماكس هيجان الجموع وشدة غضبهم سلح ثلاثة الاف رجل واعمل ايدي الظلم تحت قيادة رجل عات قد تناهى في السن والحماقة جميعا'),
(6197, '2 Maccabees', 73, 4, 41, 'فلما راوا ما عزم عليه ليسيماكس تناول بعضهم حجارة وبعضهم هراوى وبعضهم رمادا حثوه من كل جانب على اصحاب ليسيماكس'),
(6198, '2 Maccabees', 73, 4, 42, 'فجرحوا كثيرين منهم وصرعوا بعضا وهزموهم باجمعهم وقتلوا سالب الاقداس عند الخزانة'),
(6199, '2 Maccabees', 73, 4, 43, 'و اقيم الحكم في هذه الامور على منلاوس'),
(6200, '2 Maccabees', 73, 4, 44, 'فلما قدم الملك الى صور ارسلت المشيخة ثلاثة رجال فرفعوا عليه الدعوى'),
(6201, '2 Maccabees', 73, 4, 45, 'و اذ راى منلاوس انه مغلوب وعد بطلماوس بن دوريمانس بمال جزيل ليستميل الملك'),
(6202, '2 Maccabees', 73, 4, 46, 'فدخل بطلماوس على الملك وهو في بعض الاروقة يتنسم الهواء وصرفه عن رايه'),
(6203, '2 Maccabees', 73, 4, 47, 'فحكم لمنلاوس الذي هو علة الشر كله بالبراءة مما شكى به وقضى بالموت على اولئك المساكين الذين لو رفعوا دعواهم الى الاسكوتيين لحكم لهم بالبراءة'),
(6204, '2 Maccabees', 73, 4, 48, 'و لم يلبث اولئك المحاجون عن المدينة والشعب والاقداس ان حل بهم العقاب الجائر'),
(6205, '2 Maccabees', 73, 4, 49, 'فشق هذا التعدى حتى على الصوريين وبذلوا نفقات دفنهم بسخاء'),
(6206, '2 Maccabees', 73, 4, 50, 'و استقر منلاوس في الرئاسة بشره ذوي الاحكام وكان لا يزداد الا خبثا ولم يزل لاهل وطنه كمينا مهلكا'),
(6207, '2 Maccabees', 73, 5, 1, 'في ذلك الزمان تجهز انطيوكس لغزو مصر ثانية'),
(6208, '2 Maccabees', 73, 5, 2, 'فحدث انه ظهر في المدينة كلها مدة اربعين يوما فرسان تعدو في الجو وعليهم ملابس ذهبية وفي ايديهم رماح وهم مكتبون كتائب'),
(6209, '2 Maccabees', 73, 5, 3, 'و قنابل من الخيل مصطفة وهجوم وكر بين الفريقين وتقليب تروس وحراب كثيرة واستلال سيوف ورشق نبال ولمعان حلي ذهبية ودروع من كل صنف'),
(6210, '2 Maccabees', 73, 5, 4, 'فكان الجميع يسالون ان يكون مال هذه الاية خيرا'),
(6211, '2 Maccabees', 73, 5, 5, 'و ارجف قوم ان انطيوكس قد مات فاتخذ ياسون جيشا ليس باقل من الف نفس وهجم على المدينة بغتة حتى اذا دفع الذين على الاسوار واوشك ان ياخذ المدينة هرب منلاوس الى القلعة'),
(6212, '2 Maccabees', 73, 5, 6, 'فطفق ياسون يذبح اهل وطنه بغير رحمة ولم يفطن ان الظفر بالاخوان هو عين الخذلان حتى كان نصرته هذه انما كانت على اعداء لا على بني امته'),
(6213, '2 Maccabees', 73, 5, 7, 'لكنه لم يحز الرئاسة وانما احاق به اخيرا خزي كيده فهرب ثانية الى ارض بني عمون'),
(6214, '2 Maccabees', 73, 5, 8, 'و كانت خاتمة امره منقلبا سيئا لان ارتاس زعيم العرب طرده فجعل يفر من مدينة الى مدينة والجميع ينبذونه ويبغضونه بغضة من ارتد عن الشريعة ويمقتونه مقت من هو قتال لاهل وطنه حتى دحر الى مصر'),
(6215, '2 Maccabees', 73, 5, 9, 'فكان ان الذي غرب كثيرين هلك في الغربة في ارض لكديمون اذ لجا الى هناك بوسيلة القرابة'),
(6216, '2 Maccabees', 73, 5, 10, 'و الذي طرح كثيرين بغير قبر اصبح لم يبك عليه ولم يدفن ولم يكن له قبر في وطنه'),
(6217, '2 Maccabees', 73, 5, 11, 'فلما بلغت الملك هذه الحوادث اتهم اليهود بالانتقاض عليه فزحف من مصر وقد تنمر في قلبه واخذ المدينة عنوة'),
(6218, '2 Maccabees', 73, 5, 12, 'و امر الجنود ان يقتلوا كل من صادفوه دون رحمة ويذبحوا المختبئين في البيوت'),
(6219, '2 Maccabees', 73, 5, 13, 'فطفقوا يهلكون الشبان والشيوخ ويبيدون الرجال والنساء والاولاد ويذبحون العذارى والاطفال'),
(6220, '2 Maccabees', 73, 5, 14, 'فهلك ثمانون الف نفس في ثلاثة ايام منهم اربعون الفا في المعركة وبيع منهم عدد ليس باقل من القتلى'),
(6221, '2 Maccabees', 73, 5, 15, 'و لم يكتف بذلك بل اجترا ودخل الهيكل الذي هو اقدس موضع في الارض كلها وكان دليله منلاوس الخائن للشريعة والوطن'),
(6222, '2 Maccabees', 73, 5, 16, 'و اخذ الانية المقدسة بيديه الدنستين مع ما اهدته ملوك الاجانب لزينة الموضع وبهائه وكرامته وقبض عليها بيديه النجستين ومضى'),
(6223, '2 Maccabees', 73, 5, 17, 'فتشامخ انطيوكس في نفسه ولم يفطن الى ان الله غضب حينا لاجل خطايا سكان المدينة وانه لذلك اهمل الموضع'),
(6224, '2 Maccabees', 73, 5, 18, 'و لولا انهم انهمكوا بخطايا كثيرة لجلد حال دخوله وردع عن جسارته كما وقع لهليودورس الذي بعثه سلوقس الملك لافتقاد الخزانة'),
(6225, '2 Maccabees', 73, 5, 19, 'و لكن الرب لم يتخذ الامة لاجل الموضع بل الموضع لاجل الامة'),
(6226, '2 Maccabees', 73, 5, 20, 'و لذلك بعدما اشترك الموضع في مصائب الامة عاد فاشترك في نعم الرب وبعدما خذله القدير في غضبه ادرك كل مجد عند توبته تعالى'),
(6227, '2 Maccabees', 73, 5, 21, 'و حمل انطيوكس من الهيكل الفا وثماني مئة قنطار وبادر الرجوع الى انطاكية وقد خيلت اليه كبرياؤه وتشامخ نفسه انه يقطع البر بالسفن والبحر بالقدم'),
(6228, '2 Maccabees', 73, 5, 22, 'و ترك عمالا يراغمون الامة منهم فيلبس في اورشليم وهو فريجي الاصل وكان اشرس اخلاقا من الذي نصبه'),
(6229, '2 Maccabees', 73, 5, 23, 'و اندرونكس في جرزيم وايضا منلاوس الذي كان اشد جورا على الرعية من كليهما'),
(6230, '2 Maccabees', 73, 5, 24, 'ثم حمله ما كان عليه من المقت لرعايا اليهود على ان ارسل ابلونيوس الرئيس البغيض في اثنين وعشرين الف جندي وامره ان يذبح كل بالغ منهم ويبيع النساء والصبيان'),
(6231, '2 Maccabees', 73, 5, 25, 'فلما وفد الى اورشليم اظهر السلام وتربص الى يوم السبت المقدس حتى اذا دخل اليهود في عطلتهم امر اصحابه بان يتسلحوا'),
(6232, '2 Maccabees', 73, 5, 26, 'و ذبح جميع الخارجين للتفرج ثم اقتحم المدينة بالسلاح واهلك خلقا كثيرا'),
(6233, '2 Maccabees', 73, 5, 27, 'و ان يهوذا المكابي كان قد انصرف الى البرية وهو عاشر عشرة فلبث مع اصحابه في الجبال يعيشون عيشة الوحوش وياكلون العشب لئلا يشتركوا في النجاسة'),
(6234, '2 Maccabees', 73, 6, 1, 'و بعد ذلك بيسير ارسل الملك شيخا اثينيا ليضطر اليهود ان يرتدوا عن شريعة ابائهم ولا يتبعوا شريعة الله'),
(6235, '2 Maccabees', 73, 6, 2, 'و ليدنس هيكل اورشليم ويجعله على اسم زوس الاولمبي ويجعل هيكل جرزيم على اسم زوس مؤوي الغرباء لان اهل الموضع كانوا غرباء'),
(6236, '2 Maccabees', 73, 6, 3, 'فاشتد انفجار الشر وعظم على الجماهير'),
(6237, '2 Maccabees', 73, 6, 4, 'و امتلا الهيكل عمرا وقصوفا واخذ الامم يفسقون بالمابونين ويضاجعون النساء في الدور المقدسة ويدخلون اليها ما لا يحل'),
(6238, '2 Maccabees', 73, 6, 5, 'و كان المذبح مغطى بالمحارم التي نهت الشريعة عنها'),
(6239, '2 Maccabees', 73, 6, 6, 'و لم يكن لاحد ان يعيد السبت ولا يحفظ اعياد الاباء ولا يعترف بانه يهودي اصلا'),
(6240, '2 Maccabees', 73, 6, 7, 'و كانوا كل شهر يوم مولد الملك يساقون قسرا للتضحية وفي عيد ديونيسيوس يضطرون الى الطواف اجلالا له وعليهم اكاليل من اللبلاب'),
(6241, '2 Maccabees', 73, 6, 8, 'و صدر امر الى المدن اليونانية المجاورة باغراء البطالمة ان يلزموا اليهود بمثل ذلك وبالتضحية'),
(6242, '2 Maccabees', 73, 6, 9, 'و ان من ابى ان يتخذ السنن اليونانية يقتل فذاقوا بذلك امر البلاء'),
(6243, '2 Maccabees', 73, 6, 10, 'فان امراتين سعي بهما انهما ختنتا اولادهما فعلقوا اطفالهما على اثديهما وطافوا بهما في المدينة علانية ثم القوهما عن السور'),
(6244, '2 Maccabees', 73, 6, 11, 'و لجا قوم الى مغاور كانت بالقرب منهم لاقامة السبت سرا فوشي بهم الى فيلبس فاحرقهم بالنار وهم لا يجترئون ان يدافعواعن انفسهم اجلالا لهذا اليوم العظيم'),
(6245, '2 Maccabees', 73, 6, 12, 'و اني لارجو من مطالعي هذا الكتاب ان لا يستوحشوا من هذه الضربات وان يحسبوا هذه النقم ليست للهلاك بل لتاديب امتنا'),
(6246, '2 Maccabees', 73, 6, 13, 'فانه اذا لم يهمل الكفرة زمنا طويلا بل عجل عليهم بالعقاب فذلك دليل على رحمة عظيمة'),
(6247, '2 Maccabees', 73, 6, 14, 'لان الرب لا يمهل عقابنا بالاناة الى ان يستوفى كيل الاثام كما يفعل مع سائر الامم'),
(6248, '2 Maccabees', 73, 6, 15, 'فقد قضى فينا بذلك لئلا تبلغ اثامنا غايتها وينتقم منا اخيرا'),
(6249, '2 Maccabees', 73, 6, 16, 'فهو لا يزيل عنا رحمته ابدا واذا ادب شعبه بالشدائد فلا يخذله'),
(6250, '2 Maccabees', 73, 6, 17, 'نقول هذا على سبيل التذكرة ونرجع الى تتمة الحديث بكلام موجز'),
(6251, '2 Maccabees', 73, 6, 18, 'كان رجل يقال له العازار من متقدمي الكتبة طاعن في السن رائع المنظر في الغاية فاكرهوه بفتح فيه على اكل لحم الخنزير'),
(6252, '2 Maccabees', 73, 6, 19, 'فاختار ان يموت مجيدا على ان يحيا ذميما وانقاد الى العذاب طائعا'),
(6253, '2 Maccabees', 73, 6, 20, 'و قذف لحم الخنزير من فيه ثم تقدم كما يليق بمن يتمنع بشجاعة عما لا يحل ذوقه رغبة في الحياة'),
(6254, '2 Maccabees', 73, 6, 21, 'فخلا به الموكلون بامر الضحايا الكفرية لما كان بينهم وبينه من قديم المعرفة وجعلوا يحثونه ان ياتي بما يحل له تناوله من اللحم مهيأ بيده ويتظاهر بانه ياكل من لحم الضحايا التي امر بها الملك'),
(6255, '2 Maccabees', 73, 6, 22, 'لينجو من الموت اذا فعل ذلك وينال منهم الجميل لاجل مودته القديمة لهم'),
(6256, '2 Maccabees', 73, 6, 23, 'لكنه عول على الراي النزيه الجدير بسنه وكرامة شيخوخته وما بلغ اليه من جلالة المشيب وبكمال سيرته الحسنة منذ حداثته بلب الشريعة المقدسة الالهية واجاب بغير توقف وقال بل اسبق الى الجحيم'),
(6257, '2 Maccabees', 73, 6, 24, 'لانه لا يليق بسننا الرئاء لئلا يظن كثير من الشبان ان العازار وهو ابن تسعين سنة قد انحاز الى مذهب الاجانب'),
(6258, '2 Maccabees', 73, 6, 25, 'و يضلوا بسببي لاجل رئائي وحبي لحياة قصيرة فانية فاجلب على شيخوختي الرجس والفضيحة'),
(6259, '2 Maccabees', 73, 6, 26, 'فاني ولو نجوت الان من نكال البشر لا افر من يدي القدير لا في الحياة ولا بعد الممات'),
(6260, '2 Maccabees', 73, 6, 27, 'و لكن اذا فارقت الحياة ببسالة فقد وفيت بحق شيخوختي'),
(6261, '2 Maccabees', 73, 6, 28, 'و ابقيت للشبان قدوة شهامة ليتلقوا المنية ببسالة وشهامة في سبيل الشريعة الجليلة المقدسة ولما قال هذا انطلق من ساعته الى عذاب التوتير والضرب'),
(6262, '2 Maccabees', 73, 6, 29, 'فتحول اولئك الذين ابدوا له الرافة قبيل ذلك الى القسوة لحسبانهم ان كلامه كان عن كبر'),
(6263, '2 Maccabees', 73, 6, 30, 'و لما اشرف على الموت من الضرب تنهد وقال يعلم الرب وهو ذو العلم المقدس اني وانا قادر على التخلص من الموت اكابد في جسدي عذاب الضرب الاليم واما في نفسي فاني احتمل ذلك مسرورا لاجل مخافته'),
(6264, '2 Maccabees', 73, 6, 31, 'و هكذا قضى هذا الرجل تاركا موته قدوة شهامة وتذكار فضيلة لامته باسرها فضلا عن الشبان بخصوصهم'),
(6265, '2 Maccabees', 73, 7, 1, 'و قبض على سبعة اخوة مع امهم فاخذ الملك يكرههم عل تناول لحوم الخنزير المحرمة ويعذبهم بالمقارع والسياط'),
(6266, '2 Maccabees', 73, 7, 2, 'فانتدب احدهم للكلام وقال ماذا تبتغي وعم تستنطقنا انا لنختار ان نموت ولا نخالف شريعة ابائنا'),
(6267, '2 Maccabees', 73, 7, 3, 'فحنق الملك وامر باحماء الطواجن والقدور ولما احميت'),
(6268, '2 Maccabees', 73, 7, 4, 'امر لساعته بان يقطع لسان الذي انتدب للكلام ويسلخ جلد راسه وتجدع اطرافه على عيون اخوته وامه'),
(6269, '2 Maccabees', 73, 7, 5, 'و لما عاد جذمة امر بان يؤخذ الى النار وفيه رمق من الحياة ويقلى وفيما كان البخار منتشرا من الطاجن كانوا هم وامهم يحض بعضهم بعضا ان يقدموا على الموت بشجاعة'),
(6270, '2 Maccabees', 73, 7, 6, 'قائلين ان الرب الاله ناظر وهو يتمجد بنا كما صرح موسى في نشيده الشاهد في الوجوه اذ قال ويستمجد بعبيده'),
(6271, '2 Maccabees', 73, 7, 7, 'و لما قضى الاول على هذه الحال ساقوا الثاني الى الهوان ونزعوا جلد راسه مع شعره ثم سالوه هل ياكل قبل ان يعاقب في جسده عضوا عضوا'),
(6272, '2 Maccabees', 73, 7, 8, 'فاجاب بلغة ابائه وقال لا فاذاقوه بقية العذاب كالاول'),
(6273, '2 Maccabees', 73, 7, 9, 'و فيما كان على اخر رمق قال انك ايها الفاجر تسلبنا الحياة الدنيا ولكن ملك العالمين اذا متنا في سبيل شريعته فسيقيمنا لحياة ابدية'),
(6274, '2 Maccabees', 73, 7, 10, 'و بعده شرعوا يستهينون بالثالث وامروه فدلع لسانه وبسط يديه بقلب جليد'),
(6275, '2 Maccabees', 73, 7, 11, 'و قال اني من الرب السماء اوتيت هذه الاعضاء ولاجل شريعته ابذلها واياه ارجو ان استردها من بعد'),
(6276, '2 Maccabees', 73, 7, 12, 'فبهت الملك والذين معه من بسالة قلب ذلك الغلام الذي لم يبال بالعذاب شيئا'),
(6277, '2 Maccabees', 73, 7, 13, 'و لما قضى عذبوا الرابع ونكلوا به بمثل ذلك'),
(6278, '2 Maccabees', 73, 7, 14, 'و لما اشرف على الموت قال حبذا ما يتوقعه الذي يقتل بايدي الناس من رجاء اقامة الله له اما انت فلا تكون لك قيامة للحياة'),
(6279, '2 Maccabees', 73, 7, 15, 'ثم ساقوا الخامس وعذبوه فالتفت الى الملك وقال'),
(6280, '2 Maccabees', 73, 7, 16, 'انك بما لك من السلطان على البشر مع كونك فانيا تفعل ما تشاء ولكن لا تظن ان الله قد خذل ذريتنا'),
(6281, '2 Maccabees', 73, 7, 17, 'اصبر قليلا فترى باسه الشديد كيف يعذبك انت ونسلك'),
(6282, '2 Maccabees', 73, 7, 18, 'و بعده ساقوا السادس فلما قارب ان يموت قال لا تغتر بالباطل فانا نحن جلبنا على انفسنا هذا العذاب لانا خطانا الى الهنا ولذلك وقع لنا ما يقضي بالعجب'),
(6283, '2 Maccabees', 73, 7, 19, 'و اما انت لا تحسب انك تترك سدى بعد تعرضك لمناصبة الله'),
(6284, '2 Maccabees', 73, 7, 20, 'و كانت امهم اجدر الكل بالعجب والذكر الحميد فانها عاينت بنيها السبعة يهلكون في مدة يوم واحد وصبرت على ذلك بنفس طيبة ثقة بالرب'),
(6285, '2 Maccabees', 73, 7, 21, 'و كانت تحرض كلا منهم بلغة ابائها وهي ممتلئة من الحكمة السامية وقد القت على كلامها الانثوي بسالة رجلية'),
(6286, '2 Maccabees', 73, 7, 22, 'قائلة لهم اني لست اعلم كيف نشاتم في احشائي ولا انا منحتكم الروح والحياة ولا احكمت تركيب اعضائكم'),
(6287, '2 Maccabees', 73, 7, 23, 'على ان خالق العالم الذي جبل تكوين الانسان وابدع لكل شيء تكوينه سيعيد اليكم برحمته الروح والحياة لانكم الان تبذلون انفسكم في سبيل شريعته'),
(6288, '2 Maccabees', 73, 7, 24, 'و ان انطيوكس اذ تخيل انه يستخف به وخشي صوت معير يعيره اخذ يحرض بالكلام اصغرهم الباقي بل اكد له بالايمان انه يغنيه ويسعده اذا ترك شريعة ابائه ويتخذه خليلا له ويقلده المناصب'),
(6289, '2 Maccabees', 73, 7, 25, 'و لمل لم يصخ الغلام لذلك البتة دعا الملك امه وحثها ان تشير على الغلام بما يبلغ الي خلاصه'),
(6290, '2 Maccabees', 73, 7, 26, 'و الح عليها حتى وعدت بانها تشير على ابنها'),
(6291, '2 Maccabees', 73, 7, 27, 'ثم انحنت اليه واستهزات بالملك العنيف وقالت بلغة ابائها يا بني ارحمني انا التي حملتك في جوفها تسعة اشهر وارضعتك ثلاث سنين وعالتك وبلغتك الى هذه السن وربتك'),
(6292, '2 Maccabees', 73, 7, 28, 'انظر يا ولدي الى السماء والارض واذا رايت كل ما فيهما فاعلم ان الله صنع الجميع من العدم وكذلك وجد جنس البشر'),
(6293, '2 Maccabees', 73, 7, 29, 'فلا تخف من هذا الجلاد لكن كن مستاهلا لاخوتك واقبل الموت لاتلقاك مع اخوتك بالرحمة'),
(6294, '2 Maccabees', 73, 7, 30, 'و فيما هي تتكلم قال الغلام ماذا انتم منتظرون اني لا اطيع امر الملك وانما اطيع امر الشريعة التي القيت الى ابائنا على يد موسى'),
(6295, '2 Maccabees', 73, 7, 31, 'و انت ايها المخترع كل شر على العبرانيين انك لن تنجو من يدي الله'),
(6296, '2 Maccabees', 73, 7, 32, 'فنحن انما نعاقب على خطايانا'),
(6297, '2 Maccabees', 73, 7, 33, 'و ربنا الحي وان سخط علينا حينا يسيرا لتوبيخنا وتاديبنا سيتوب على عبيده من بعد'),
(6298, '2 Maccabees', 73, 7, 34, 'و اما انت ايها المنافق يا اخبث كل بشر فلا تتشامخ باطلا وتتنمر بامالك الكاذبة وانت رافع يدك على عبيده'),
(6299, '2 Maccabees', 73, 7, 35, 'لانك لم تنج من دينونة الله القدير الرقيب'),
(6300, '2 Maccabees', 73, 7, 36, 'و لقد صبر اخوتنا على الم ساعة ثم فازوا بحياة ابدية وهم في عهد الله واما انت فسيحل بك بقضاء الله العقاب الذي تستوجبه بكبريائك'),
(6301, '2 Maccabees', 73, 7, 37, 'و انا كاخوتي ابذل جسدي ونفسي في سبيل شريعة ابائنا وابتهل الى الله ان لا يبطئ في توبته على امتنا وان يجعلك بالمحن والضربات تعترف بانه هو الاله وحده'),
(6302, '2 Maccabees', 73, 7, 38, 'و ان ينتهي في وفي اخوتي غضب القدير الذي حل على امتنا عدلا'),
(6303, '2 Maccabees', 73, 7, 39, 'فحنق الملك ولم يحتمل ذلك الاستهزاء فزاده نكالا على اخوته'),
(6304, '2 Maccabees', 73, 7, 40, 'و هكذا قضى هذا الغلام طاهرا وقد وكل الى الرب كل امره'),
(6305, '2 Maccabees', 73, 7, 41, 'و في اخر الامر هلكت الام على اثر بنيها'),
(6306, '2 Maccabees', 73, 7, 42, 'و بما اوردناه عن الضحايا والتعذيبات المبرحة كفاية'),
(6307, '2 Maccabees', 73, 8, 1, 'و كان يهوذا المكابي ومن معه يتسللون الى القرى ويندبون ذوي قرابتهم ويستضمون الذين ثبتوا على دين اليهود حتى جمعوا ستة الاف'),
(6308, '2 Maccabees', 73, 8, 2, 'و كانوا يبتهلون الى الرب ان ينظر الى شعبه الذي اصبح يدوسه كل احد ويعطف على الهيكل الذي دنسه اهل النفاق'),
(6309, '2 Maccabees', 73, 8, 3, 'و يرحم المدينة المتهدمة التي اشرفت على الامحاء ويصغي الى صوت الدماء الصارخة اليه'),
(6310, '2 Maccabees', 73, 8, 4, 'و يذكر اهلاك الاطفال الابرئاء ظلما والتجاديف على اسمه ويجهر ببغضته للشر'),
(6311, '2 Maccabees', 73, 8, 5, 'و لما اصبح المكابي في جيش لم تعد الامم تثبت امامه اذ كان سخط الرب قد استحال الى رحمة'),
(6312, '2 Maccabees', 73, 8, 6, 'فجعل يفاجئ المدن والقرى ويحرقها حتى اذا استولى على مواضع توافقه تغلب على الاعداء في مواقع جمة'),
(6313, '2 Maccabees', 73, 8, 7, 'و كان اكثر غاراته ليلا فذاع خبر شجاعته في كل مكان'),
(6314, '2 Maccabees', 73, 8, 8, 'فلما راى فيلبس ان الرجل اخذ في التقدم شيئا فشيئا وقد اوتي الفوز في اكثر اموره كتب الى بطلماوس قائد بقاع سورية فينيقية يساله المناجدة لصيانة مصالح الملك'),
(6315, '2 Maccabees', 73, 8, 9, 'فاختار لساعته نكانور بن بتركلس من خواص اصدقاء الملك وجعل تحت يده لفيفا من الامم يبلغ عشرين الفا ليستاصل ذرية اليهود عن اخرهم وضم اليه جرجياس وهو من القواد المحنكين في امر الحرب'),
(6316, '2 Maccabees', 73, 8, 10, 'فرسم نكانور ان يؤخذ من مبيع سبي اليهود الفا القنطار التي كانت للرومانيين على الملك'),
(6317, '2 Maccabees', 73, 8, 11, 'و ارسل في الحال الى مدن الساحل يدعو الى مشتري رقاب اليهود مسعرا كل تسعين رقبة بقنطار ولم يخطر له ما سيحل به من نقمة القدير'),
(6318, '2 Maccabees', 73, 8, 12, 'فاتصل بيهوذا خبر مقدم نكانور فاخبر الذين معه بمجيء الجيش'),
(6319, '2 Maccabees', 73, 8, 13, 'فبدا الذين خافوا ولم يثقوا بعدل الله ينسابون كل واحد من مكانه'),
(6320, '2 Maccabees', 73, 8, 14, 'و باع اخرون كل ما كان باقيا لهم وكانوا يبتهلون الى الرب ان ينقذهم من نكانور الكافر الذي باعهم قبل الملتقى'),
(6321, '2 Maccabees', 73, 8, 15, 'و ذلك ان لم يكن من اجلهم فمن اجل عهده مع ابائهم وحرمة اسمه العظيم الذي هم مسمون به'),
(6322, '2 Maccabees', 73, 8, 16, 'فحشد المكابي اصحابه وهم ستة الاف وحرضهم ان لا يرتاعوا من الاعداء ولا يخافوا من كثرة الامم المجتمعة عليهم بغيا وان يقاتلوا بباس'),
(6323, '2 Maccabees', 73, 8, 17, 'جاعلين نصب عيونهم الاهانة التي الحقوها بالموضع المقدس عدوانا وما انزلوه بالمدينة من القهر والعار مع نقض سنن الاباء'),
(6324, '2 Maccabees', 73, 8, 18, 'و قال ان هؤلاء انما يتوكلون على سلاحهم وجسارتهم واما نحن فنتوكل على الله القدير الذي يستطيع في لمحة ان يبيد الثائرين علينا بل العالم باسره'),
(6325, '2 Maccabees', 73, 8, 19, 'ثم ذكر لهم النجدات التي امد بها اباؤهم وما كان من ابادة المئة والخمسة والثمانين الفا على عهد سنحاريب'),
(6326, '2 Maccabees', 73, 8, 20, 'و الواقعة التي كانت لهم في بابل مع الغلاطيين كيف برزوا للقتال وهم ثمانية الاف رجل ومعهم اربعة الاف من المكدونيين وكيف حين وهل المكدونيين اهلك اولئك الثمانية الالاف مئة وعشرين الفا بالنجدة التي اوتها من السماء وعادوا بخير جزيل'),
(6327, '2 Maccabees', 73, 8, 21, 'و بعدما شددهم بهذا الكلام حتى اضحوا مستعدين للموت في سبيل الشريعة والوطن قسمهم اربع فرق'),
(6328, '2 Maccabees', 73, 8, 22, 'و اقام كل واحد من اخوته سمعان ويوسف ويوناتان قائدا على فرقة وجعل تحت يده الفا وخمس مئة'),
(6329, '2 Maccabees', 73, 8, 23, 'ثم امر العازار ان يتلو عليهم الكتاب المقدس وجعل لهم كلمة السر نصرة الله ثم اتخذ قيادة الكتيبة الاولى وحمل على نكانور'),
(6330, '2 Maccabees', 73, 8, 24, 'فايدهم القدير فقتلوا من الاعداء ما يزيد على تسعة الاف وتركوا اكثر جيش نكانور مجرحين مجدعي الاعضاء والجاوا الجميع الى الهزيمة'),
(6331, '2 Maccabees', 73, 8, 25, 'و غنموا اموال الذين جاءوا لشرائهم ثم تعقبوهم مسافة غير قصيرة'),
(6332, '2 Maccabees', 73, 8, 26, 'الى ان حضرت الساعة فامسكوا وعادوا وقد ادركوا السبت ولذلك لم يطيلوا تعقبهم'),
(6333, '2 Maccabees', 73, 8, 27, 'و جمعوا اسلحة الاعداء واخذوا اسلابهم ثم حفظوا السبت وهم يباركون الرب كثيرا ويعترفون له اذ انقذهم ليعيدوا ذلك اليوم ومن عليهم باستئناف رحمته'),
(6334, '2 Maccabees', 73, 8, 28, 'و لما انقضى السبت وزعوا على الضعفاء والارامل واليتامى نصيبهم من الغنائم واقتسموا الباقي بينهم وبين اولادهم'),
(6335, '2 Maccabees', 73, 8, 29, 'و بعدما فرغوا من ذلك اقاموا صلاة عامة سائلين الرب الرحيم ان يعود فيتوب على عبيده'),
(6336, '2 Maccabees', 73, 8, 30, 'و قتلوا ما يزيد على عشرين الفا من جيوش تيموتاوس وبكيديس واستولوا على حصون مشيدة واقتسموا كثيرا من الاسلاب جعلوها سهاما متساوية لهم وللضعفاء واليتامى والارامل والشيوخ'),
(6337, '2 Maccabees', 73, 8, 31, 'و لما جمعوا اسلحة العدو رتبوا كل شيء في موضعه اللائق به وحملوا ما بقي من الغنائم الى اورشليم'),
(6338, '2 Maccabees', 73, 8, 32, 'و قتلوا رئيس جيش تيموتاوس وكان رجلا شديد النفاق الحق باليهود اضرارا كثيرة'),
(6339, '2 Maccabees', 73, 8, 33, 'و بينا هم يحتفلون بالظفر في وطنهم احرقوا كلستانيس وقوما معه في بيت كانوا قد فروا اليه وكانوا قد احرقوا الابواب المقدسة فنالهم الجزاء الذي استوجبوه بكفرهم'),
(6340, '2 Maccabees', 73, 8, 34, 'و اما نكانور الشديد الفجور الذي كان قد استصحب معه الف تاجر لمشتري اليهود'),
(6341, '2 Maccabees', 73, 8, 35, 'فلما راى الذين كان يحتقرهم قد اذلوه بامداد الرب خلع ما عليه من الثياب الفاخرة وانساب في كبد البلاد منفردا كالابق حتى لحق بانطاكية وهو متفجع غاية التفجع لانقراض جيشه'),
(6342, '2 Maccabees', 73, 8, 36, 'و بعدما كان قد وعد الرومانيين بان يفيهم الخراج من سبي اورشليم عاد يذيع ان اليهود لهم الله نصير وانهم لذلك لا يغلبون اذ هم متبعون ما رسم لهم من الشرائع'),
(6343, '2 Maccabees', 73, 9, 1, 'و اتفق في ذلك الزمان ان انطيوكس كان منصرفا عن بلاد فارس بالخزي'),
(6344, '2 Maccabees', 73, 9, 2, 'و كان قد زحف على مدينة اسمها برسابوليس وشرع يسلب الهياكل ويعسف المدينة فثار الجموع الى السلاح ودفعوه فانهزم انطيوكس منقلبا بالعار'),
(6345, '2 Maccabees', 73, 9, 3, 'و لما كان عند احمتا بلغه ما وقع لنكانور واصحاب تيموتاوس'),
(6346, '2 Maccabees', 73, 9, 4, 'فاستشاط غضبا وازمع ان يحيل على اليهود ما الحقه به الذين هزموه من الشر فامر سائق عجلته بان يجد في السير بغير انقطاع وقد حلبه القضاء من السماء فانه قال في تجبره لآتين اورشليم ولأجعلنها مدفنا لليهود'),
(6347, '2 Maccabees', 73, 9, 5, 'لكن الرب اله اسرائيل البصير بكل شيء ضربه ضربة معضلة غير منظورة فانه لم يفرغ من كلامه ذاك حتى اخذه داء في احشائه لا دواء له ومغص اليم في جوفه'),
(6348, '2 Maccabees', 73, 9, 6, 'و كان ذلك عين العدل في حقه لانه عذب احشاء كثيرين بالالام المتنوعة الغريبة لكنه لم يكن ليكف عن عتيه'),
(6349, '2 Maccabees', 73, 9, 7, 'و انما بقي صدره ممتلئا من الكبرياء ينفث نار الحنق على اليهود ويحث على الاسراع في السير حتى انه من شدة الجري سقط من عجلته فترضضت بتلك السقطة الهائلة جميع اعضاء جسمه'),
(6350, '2 Maccabees', 73, 9, 8, 'فاصبح بعدما خيل له بزهوه الذي لم يبلغ اليه انسان انه يحكم على امواج البحر ويجعل قمم الجبال في كفة الميزان مصروعا على الارض محمولا في محفة شهادة للجميع بقدرة الله الجليلة'),
(6351, '2 Maccabees', 73, 9, 9, 'حتى كانت الديدان تنبع من جسد ذلك المنافق ولحمه يتساقط وهو حي بالالام والاوجاع وصار الجيش كله يتكره نتن رائحته'),
(6352, '2 Maccabees', 73, 9, 10, 'حتى انه بعدما كان قبيل ذلك يزين له انه يمس كواكب السماء لم يكن احد يطيق حمله لشدة رائحته التي لا تحتمل'),
(6353, '2 Maccabees', 73, 9, 11, 'فلما راى نفسه في تلك الحال من تمزق جسمه اخذ ينزل عن كبريائه المفرطة ويتعقل الحق اذ كانت الاوجاع تزداد فيه على الساعات بالضربة الالهية'),
(6354, '2 Maccabees', 73, 9, 12, 'حتى انه هو نفسه امسى لا يطيق نتنه فقال حق على الانسان ان يخضع لله وان لا يحمله الكبر وهو فان على ان يحسب نفسه معادلا لله'),
(6355, '2 Maccabees', 73, 9, 13, 'و كان ذلك الفاجر يتضرع الى الرب لكن الرب لم يكن ليرحمه من بعد ونذر'),
(6356, '2 Maccabees', 73, 9, 14, 'ان المدينة المقدسة التي كان يقصدها حثيثا ليمحو اثارها ويجعلها مدفنا سيجعلها حرة'),
(6357, '2 Maccabees', 73, 9, 15, 'و ان اليهود الذين كان قد قضى عليهم بان لا يدفنوا بل يلقوا مع اطفالهم ماكلا للطيور والوحوش سيسويهم جميعا بالاثينيين'),
(6358, '2 Maccabees', 73, 9, 16, 'و ان الهيكل المقدس الذي كان قد انتهبه سيزينه بافخر التحف ويرد الانية المقدسة اضعافا ويؤدي النفقات المفروضة للذبائح من دخله الخاص'),
(6359, '2 Maccabees', 73, 9, 17, 'بل انه هو نفسه يتهود ويطوف كل معمور في الارض ينادي بقدرة الله'),
(6360, '2 Maccabees', 73, 9, 18, 'و اذ لم تسكن الامه لان قضاء الله العادل كان قد حل عليه قنط من نفسه وكتب الى اليهود رسالة في معنى التوسل وهذه صورتها'),
(6361, '2 Maccabees', 73, 9, 19, 'من انطيوكس الملك القائد الى رعايا اليهود الافاضل السلام الكثير والعافية والغبطة'),
(6362, '2 Maccabees', 73, 9, 20, 'اذا كنتم في سلامة وكان اولادكم وكل شيء لكم على ما تحبون فاني اشكر الله شكرا جزيلا اما انا فرجائي منوط بالسماء'),
(6363, '2 Maccabees', 73, 9, 21, 'و بعد فاني منذ اعتللت لم ازل اذكركم بالمودة ناويا لكم الكرامة والخير فاني في ايابي من نواحي فارس اصابني داء شديد فرايت من الواجب ان اصرف العناية الى مصلحة الجميع'),
(6364, '2 Maccabees', 73, 9, 22, 'ليس لاني قانط من نفسي فان لي رجاء وثيقا ان اتخلص من علتي'),
(6365, '2 Maccabees', 73, 9, 23, 'ثم اني تذكرت ان ابي حين سار بجيشه الى الاقاليم العليا عين الولي لعهده'),
(6366, '2 Maccabees', 73, 9, 24, 'و انا اخاف ان يقع امر غير منتظر او يذيع خبر مشؤوم فيضطرب مقلدوا الامور في البلاد عند بلوغه اليهم'),
(6367, '2 Maccabees', 73, 9, 25, 'و قد تبين لي ان من حولنا من ذوي السلطان ومجاوري المملكة يترصدون الفرص ويتوقعون حادثا يحدث فلذلك عينت للملك ابني انطيوكسالذي سلمته غير مرة الى كثيرين منكم واوصيتهم به عند مسيري الى الاقاليم العليا وقد كتبت اليه في هذا المعنى'),
(6368, '2 Maccabees', 73, 9, 26, 'فانشدكم وارغب اليكم ان تذكروا ما اوليتكم من النعم العامة والخاصة وان يبقى كل منكم على ما كان له من الولاء لي ولابني'),
(6369, '2 Maccabees', 73, 9, 27, 'و لي الثقة بانه سياتم بقصدي فيعاملكم بالرفق والمرؤة'),
(6370, '2 Maccabees', 73, 9, 28, 'ثم قضى هذا السفاك الدماء المجدف بعد الام مبرحة كما كان يفعل بالناس ومات ميتة شقاء على الجبال في ارض غربة'),
(6371, '2 Maccabees', 73, 9, 29, 'فنقل جثته فيلبس رضيعه ثم انصرف الى مصر الى بطلماوس فيلوماتور خوفا من ابن انطيوكس'),
(6372, '2 Maccabees', 73, 10, 1, 'اما المكابي والذين معه فبامداد الرب استردوا الهيكل والمدينة'),
(6373, '2 Maccabees', 73, 10, 2, 'و هدموا المذابح التي كان الاجانب قد بنوها في الساحة وخربوا المعابد'),
(6374, '2 Maccabees', 73, 10, 3, 'و طهروا الهيكل وصنعوا مذبحا اخر واقتدحوا حجارة اقتبسوا منها نارا وقدموا ذبيحة بعد فترة سنتين وهياوا البخور والسرج وخبز التقدمة'),
(6375, '2 Maccabees', 73, 10, 4, 'و بعدما اتموا ذلك ابتهلوا الى الرب وقد خروا بصدورهم ان لا يصابوا بمثل تلك الشرور لكن اذا خطئوا يؤدبهم هو برفق ولا يسلمهم الى امم كافرة وحشية'),
(6376, '2 Maccabees', 73, 10, 5, 'و اتفق انه في مثل اليوم الذي فيه نجست الغرباء الهيكل في ذلك اليوم عينه ثم تطهير الهيكل وهو اليوم الخامس والعشرون من ذلك الشهر الذي هو شهر كسلو'),
(6377, '2 Maccabees', 73, 10, 6, 'فعيدوا ثمانية ايام بفرح كما في عيد المظال وهم يذكرون كيف قضوا عيد المظال قبيل ذلك في الجبال والمغاور مثل وحوش البرية'),
(6378, '2 Maccabees', 73, 10, 7, 'و لذلك سبحوا لمن يسر تطهير هيكله وفي ايديهم غصون ذات اوراق وافنان خضر وسعف'),
(6379, '2 Maccabees', 73, 10, 8, 'و رسموا رسما عاما على جميع امة اليهود ان يعيدوا هذه الايام في كل سنة'),
(6380, '2 Maccabees', 73, 10, 9, 'هكذا كانت وفاة انطيوكس الملقب بالشهير'),
(6381, '2 Maccabees', 73, 10, 10, 'و لنشرع الان في خبر ابن ذاك المنافق ونذكر ما كان من رزايا الحروب بالايجاز'),
(6382, '2 Maccabees', 73, 10, 11, 'انه لما استولى هذا على الملك فوض تدبير الامور الى ليسياس قائد القواد في بقاع سورية وفينيقية'),
(6383, '2 Maccabees', 73, 10, 12, 'و ذلك ان بطلماوس المسمى بمكرون عزم على ان ينصف اليهود مما كانوا فيه من الظلم واجتهد في معاملتهم بالسلم'),
(6384, '2 Maccabees', 73, 10, 13, 'فلذلك سعى به اصحابه الى اوباطور وكثر كلام الناس فيه بانه خائن لانه تخلى عن قبرس التي كان فيلوماطور قد استعمله عليها وانحاز الى انطيوكس الشهير واذ ذهبت عنه كرامة السلطان بلغ منه الكمد فقتل نفسه بسم'),
(6385, '2 Maccabees', 73, 10, 14, 'فولى جرجياس قيادة البلاد وشرع يجيش من الاجانب وناصب اليهود حربا متواصلة'),
(6386, '2 Maccabees', 73, 10, 15, 'و كذلك الادوميون الذين كانت لهم حصون ملائمة كانوا يرغمون اليهود ويقبلون المهاجرين من اورشليم ويتجهزون للحرب'),
(6387, '2 Maccabees', 73, 10, 16, 'فابتهل الذين مع المكابي وتضرعوا الى الله ان يكون لهم نصيرا ثم هجموا على حصون الادوميين'),
(6388, '2 Maccabees', 73, 10, 17, 'و اندفعوا عليها بشدة وامتلكوا مواضع منها وصدموا جميع الذين كانوا يقاتلون على السور وكل من اقتحمهم قتلوه فاهلكوا منهم عشرين الفا'),
(6389, '2 Maccabees', 73, 10, 18, 'و فر تسعة الاف منهم الى برجين حصينين جدا مجهزين بكل اسباب الدفاع'),
(6390, '2 Maccabees', 73, 10, 19, 'فخلف المكابي سمعان ويوسف وزكا وعددا من اصحابه كافيا لمحاصرتهما وانصرف الى مواضع اخرى كانت اشد اقتضاء له'),
(6391, '2 Maccabees', 73, 10, 20, 'غير ان الذين كانوا مع سمعان استغواهم حب المال فارتشوا من بعض الذين في البرجين وخلوا سبيلهم بعد ان اخذوا منهم سبعين الف درهم'),
(6392, '2 Maccabees', 73, 10, 21, 'فلما اخبر المكابي بما وقع جمع رؤساء الشعب وشكا ما فعلوا من بيع اخوتهم بالمال اذ اطلقوا اعدائهم عليهم'),
(6393, '2 Maccabees', 73, 10, 22, 'ثم قتل اولئك الخونة ومن فوره استولى على البرجين'),
(6394, '2 Maccabees', 73, 10, 23, 'و قرنت اسلحته بكل فوز على يده فاهلك في البرجين ما يزيد على عشرين الفا'),
(6395, '2 Maccabees', 73, 10, 24, 'ثم ان تيموتاوس الذي كان اليهود قد قهروه من قبل حشد جيشا عظيما من الغرباء وجمع من فرسان اسية عددا غير قليل ونزل على اليهودية نزول مستفتح قهرا'),
(6396, '2 Maccabees', 73, 10, 25, 'فعندما اقترب توجه اصحاب المكابي الى الابتهال الى الله وقد حثوا التراب على رؤوسهم وحزموا احقاءهم بالمسوح'),
(6397, '2 Maccabees', 73, 10, 26, 'و خروا عند رجل المذبح وابتهلوا اليه ان يكون راحما لهم ومعاديا لاعدائهم ومضايقا لمضايقيهم كما ورد في الشريعة'),
(6398, '2 Maccabees', 73, 10, 27, 'و لما فرغوا من الدعاء اخذوا السلاح وتقدموا حتى صاروا عن المدينة بمسافة بعيدة ولما قاربوا العدو وقفوا'),
(6399, '2 Maccabees', 73, 10, 28, 'و عند طلوع الشمس تلاحم الفريقان وهؤلاء متوكلون على الرب كفيلا بالفوز والنصر مع بسالتهم واولئك متخذون البأس قائدهم في الحروب'),
(6400, '2 Maccabees', 73, 10, 29, 'فلما اشتد القتال تراءى للاعداء من السماء خمسة رجال رائعي المنظر على خيل لها لجم من ذهب فجعل اثنان منهم يقدمان اليهود'),
(6401, '2 Maccabees', 73, 10, 30, 'و هما قد اكتنفا المكابي يحفزانه باسلحتهما ويقيانه الجراح وهم يرمون بالسهام والصواعق حتى عميت ابصارهم وجعلوا يخبطون ويتصرعون'),
(6402, '2 Maccabees', 73, 10, 31, 'فقتل عشرون الفا وخمس مئة ومن الفرسان ست مئة'),
(6403, '2 Maccabees', 73, 10, 32, 'و انهزم تيموتاوس الى الحصن المسمى بجازر وهو حصن منيع وكان تحت امرة كيراوس'),
(6404, '2 Maccabees', 73, 10, 33, 'فاستبشر اصحاب المكابي وحاصروا المعقل اربعة ايام'),
(6405, '2 Maccabees', 73, 10, 34, 'و ان الذين في داخله لثقتهم بمناعة المكان تمادوا في التجديف وافحشوا في الكلام'),
(6406, '2 Maccabees', 73, 10, 35, 'فلما كان صباح اليوم الخامس هجم عشرون فتى من اصحاب المكابي على السور وهم متقدون غيظا من التجاديف وطفقوا يذبحون ببسالة وتنمر كل من عرض امامهم'),
(6407, '2 Maccabees', 73, 10, 36, 'و عطف اخرون فتسلقوا الى الذين في الداخل واضرموا البرجين واحرقوا اولئك المجدفين احياء في النيران المتقدة'),
(6408, '2 Maccabees', 73, 10, 37, 'و كسر اخرون الابواب وادخلوا بقية الجيش فاستحوذوا على المدينة وكان تيموتاوس مستخفيا في جب فذبحوه هو وكيراوس اخاه وابلوفانيس'),
(6409, '2 Maccabees', 73, 10, 38, 'و بعد ذلك باركوا الرب بالنشيد والاعتراف على احسانه العظيم الى اسرائيل وتاييده لهم بالنصر'),
(6410, '2 Maccabees', 73, 11, 1, 'و بعد ذلك بزمان يسير اذ كانت هذه الحوادث قد شقت جدا ليسياس وكيل الملك وذي قرابته والمقلد تدبير الامور'),
(6411, '2 Maccabees', 73, 11, 2, 'جمع نحو ثمانين الفا والفرسان كلهم وزحف على اليهود زاعما انه يجعل المدينة مسكنا لليونانيين'),
(6412, '2 Maccabees', 73, 11, 3, 'و يجعل الهيكل موضعا للكسب كسائر معابد الامم ويعرض الكهنوت الاعظم للبيع سنة فسنة'),
(6413, '2 Maccabees', 73, 11, 4, 'غير متفكر في قدرة الله لكن متوكلا برعونة قلبه على ربوات الرجالة والوف الفرسان وفيلته الثمانين'),
(6414, '2 Maccabees', 73, 11, 5, 'فدخل اليهودية وبلغ الى بيت صور وهي موضع منيع على نحو خمس غلوات من اورشليم وضايقها'),
(6415, '2 Maccabees', 73, 11, 6, 'فلما علم اصحاب المكابي انه يحاصر الحصون ابتهلوا الى الرب مع الجموع بالنحيب والدموع ان يرسل ملاكه الصالح لخلاص اسرائيل'),
(6416, '2 Maccabees', 73, 11, 7, 'ثم اخذ المكابي سلاحه اولا وحرض الاخرين على الاقتحام معه لنجدة اخوتهم'),
(6417, '2 Maccabees', 73, 11, 8, 'فاندفعوا متحمسين بقلب واحد وفيما هم بعد عند اورشليم تراءى فارس عليه لباس ابيض يتقدمهم وهو يخطر بسلاح من ذهب'),
(6418, '2 Maccabees', 73, 11, 9, 'فطفقوا باجمعهم يباركون الله الرحيم وتشجعوا في قلوبهم حتى كانوا مستعدين ان يبطشوا باضرى الوحوش فضلا عن الناس ويخترقوا الاسوار الحديدية'),
(6419, '2 Maccabees', 73, 11, 10, 'و اخذوا يتقدمون بانتظام وقد اتتهم السماء نصرة والرب رحمة'),
(6420, '2 Maccabees', 73, 11, 11, 'و حملوا على الاعداء حملة الاسود وصرعوا منهم احد عشر الفا ومن الفرسان الفا وست مئة'),
(6421, '2 Maccabees', 73, 11, 12, 'و الجاوا سائرهم الى الفرار وكان اكثر الذين نجوا بانفسهم جرحى عراة وانهزم ليسياس اقبح هزيمة'),
(6422, '2 Maccabees', 73, 11, 13, 'و اذ كان الرجل صاحب دهاء اخذ يفكر فيما اصابه من الخسران وفطن ان العبرانيين قوم لا يقهرون لان الله القدير مناصر لهم فراسلهم'),
(6423, '2 Maccabees', 73, 11, 14, 'و وعد بانه يسلم بكل ما هو حق ويستميل الملك الى موالاتهم'),
(6424, '2 Maccabees', 73, 11, 15, 'فرضي المكابي بكل ما سال ليسياس ابتغاء لما هو انفع وكل ما طلب المكابي من ليسياس بالكتابة ان يقضى لليهود قضاه الملك'),
(6425, '2 Maccabees', 73, 11, 16, 'و هذا نص الرسائل التي كتب بها ليسياس الى اليهود من ليسياس الى شعب اليهود سلام'),
(6426, '2 Maccabees', 73, 11, 17, 'قد سلم الينا يوحنا وابشالوم الموجهان من قبلكم كتاب جوابكم وسالا قضاء فحواه'),
(6427, '2 Maccabees', 73, 11, 18, 'فشرحت للملك ما ينبغي انهاؤه اليه فامضى منه ما تحتمله الحال'),
(6428, '2 Maccabees', 73, 11, 19, 'و ان بقيتم على الاخلاص فيما بيننا من الامور فاني اتوخى ان اكون لكم فيما ياتي سببا للخير'),
(6429, '2 Maccabees', 73, 11, 20, 'و اما تفصيل الامور فقد اوصيناهما مع من نحن مرسلون من قبلنا ان يفاوضوكم فيه'),
(6430, '2 Maccabees', 73, 11, 21, 'و السلام في السنة المئة والثامنة والاربعين في الرابع والعشرين من شهر ديوس كورنتي'),
(6431, '2 Maccabees', 73, 11, 22, 'و هذه صورة رسالة الملك من الملك انطيوكس الى اخينا ليسياس سلام'),
(6432, '2 Maccabees', 73, 11, 23, 'انا منذ انتقل والدنا الى الالهة لم يزل همنا ان يكون اهل مملكتنا بغير بلبال منقطعين الى شؤونهم'),
(6433, '2 Maccabees', 73, 11, 24, 'و اذ قد بلغنا ان اليهود غير راضين بما امرهم والدنا من التحول الى سنن اليونان لكنهم متمسكون بمذهبهم ولذلك يسالون انتباح لهم سننهم'),
(6434, '2 Maccabees', 73, 11, 25, 'و نحن نريد لهذا الشعب ان يكون كغيره خاليا عن البلبال فانا نحكم بان يرد لهم الهيكل وان يساسوا بمقتضى عادات ابائهم'),
(6435, '2 Maccabees', 73, 11, 26, 'فاذا ارسلت اليهم وعاقدتهم ليطمئنوا اذا علموا راينا فيهم ويقبلوا على مصالحهم بارتياح فنعما تفعل'),
(6436, '2 Maccabees', 73, 11, 27, 'و هذه رسالة الملك الى الامة من الملك انطيوكس الى مشيخة اليهود وسائر اليهود سلام'),
(6437, '2 Maccabees', 73, 11, 28, 'ان كنتم في خير فهذا ما نحب ونحن ايضا في عافية'),
(6438, '2 Maccabees', 73, 11, 29, 'قد اطلعنا منلاوس انكم تودون ان تنزلوا فتقيموا مع قومكم'),
(6439, '2 Maccabees', 73, 11, 30, 'فالذين يرتحلون الى اليوم الثلاثين من شهر كسنتكس يكونون في امان'),
(6440, '2 Maccabees', 73, 11, 31, 'و قد ابحنا لليهود اطعمتهم وشرائعهم كما كانوا عليه من قبل وكل من هفا منهم فيما سلف فلا اعنات عليه'),
(6441, '2 Maccabees', 73, 11, 32, 'و انا مرسل اليكم منلاوس ليشافهكم'),
(6442, '2 Maccabees', 73, 11, 33, 'و السلام في السنة المئة والثامنة والاربعين في الخامس عشر من شهر كسنتكس'),
(6443, '2 Maccabees', 73, 11, 34, 'و ارسل الرومانيون اليهم رسالة هذه صورتها من كونتس مميوس وتيطس منليوس رسولي الرومانيين الى شعب اليهود سلام'),
(6444, '2 Maccabees', 73, 11, 35, 'ما رخص لكم فيه ليسياس نسيب الملك نحن موافقون عليه'),
(6445, '2 Maccabees', 73, 11, 36, 'و ما استحسن ان يرفع الى الملك تشاوروا فيه وبادروا بارسال واحد لنقضي ما يوافقكم فانا متوجهان الى انطاكية'),
(6446, '2 Maccabees', 73, 11, 37, 'فعجلوا في ارسال من ترسلون لنكون على بصيرة مما تبتغون'),
(6447, '2 Maccabees', 73, 11, 38, 'و السلام في السنة المئة والثامنة والاربعين في الخامس عشر من شهر كسنتكس'),
(6448, '2 Maccabees', 73, 12, 1, 'و بعد ابرام هذه المواثيق انصرف ليسياس الى الملك واقبل اليهود على حرث اراضيهم'),
(6449, '2 Maccabees', 73, 12, 2, 'الا ان القواد الذين في البلاد وهم تيموتاوس وابلونيوس بن جنايوس وايرونيمس وديمفون وكذلك نكانور حاكم قبرس لميدعوا لهم راحة ولا سكينة'),
(6450, '2 Maccabees', 73, 12, 3, 'و اتى اهل يافا اغتيالا فظيعا وذلك انهم دعوا اليهود المساكنين لهم ان يركبوا هم ونساؤهم واولادهم قوارب كانوا اعدوها لهم كان لا عداوة بينهم'),
(6451, '2 Maccabees', 73, 12, 4, 'و اذ كان ذلك باجماع اهل المدينة كلهم رضي به اليهود وهم واثقون منهم بالاخلاص وغير متهمين لهم بسوء فلما امعنوا في البحر اغرقوهم وكان عددهم يبلغ المئتين'),
(6452, '2 Maccabees', 73, 12, 5, 'فلما بلغ يهوذا ما وقع على بني امته من الغدر الوحشي نادى فيمن معه من الرجال ودعا الله الديان العادل'),
(6453, '2 Maccabees', 73, 12, 6, 'و سار على الذين اهلكوا اخوته واضرم النار في المرفا ليلا واحرق القوارب وقتل الذين فروا الى هناك'),
(6454, '2 Maccabees', 73, 12, 7, 'و لما كانت المدينة مغلقة انصرف في نية الرجوع ومحو دولة اليافيين من اصلها'),
(6455, '2 Maccabees', 73, 12, 8, 'لكن لما علم ان اهل يمنيا ناوون ان يصنعوا بمساكنيهم من اليهود مثل ذلك'),
(6456, '2 Maccabees', 73, 12, 9, 'نزل على اهل يمنيا ليلا واحرق المرفا مع الاسطول حتى رؤى ضوء النار من اورشليم على بعد مئتين واربعين غلوة'),
(6457, '2 Maccabees', 73, 12, 10, 'ثم ساروا من هناك تسع غلوات زاحفين على تيموتاوس فتصدى لهم قوم من العرب يبلغون خمسة الاف ومعهم خمس مئة فارس'),
(6458, '2 Maccabees', 73, 12, 11, 'فاقتتلوا قتالا شديدا وكان الفوز لاصحاب يهوذا بنصرة الله فانكسر عرب البادية وسالوا يهوذا ان يعاقدهم على ان يؤدوا اليهم مواشي ويمدوهم بمنافع اخرى'),
(6459, '2 Maccabees', 73, 12, 12, 'و لم يشك يهوذا انه يحصل منهم على جدوى طائلة فرضي بمصالحتهم فعاقدهم فانصرفوا الى اخبيتهم'),
(6460, '2 Maccabees', 73, 12, 13, 'ثم اغار على مدينة حصينة ممنعة بالجسور والاسوار يسكتها لفيف من الامم اسمها كسفيس'),
(6461, '2 Maccabees', 73, 12, 14, 'و اذ كان الذين فيها واثقين بمناعة الاسوار ووفرة الميرة اخذوا الامر بالتهاون وطفقوا يشتمون اصحاب يهوذا ويجدفون وينطقون بما لا يحل'),
(6462, '2 Maccabees', 73, 12, 15, 'فدعا اصحاب يهوذا رب العالمين العظيم الذي اسقط اريحا على عهد يشوع بغير كباش ولا مجانيق ثم وثبوا على السور كالاسود'),
(6463, '2 Maccabees', 73, 12, 16, 'و فتحوا المدينة بمشيئة الله وقتلوا من الخلق ما لا يحصى حتى ان البحيرة التي هناك وعرضها غلوتان امتلات وطفحت بالدماء'),
(6464, '2 Maccabees', 73, 12, 17, 'ثم ساروا من هناك مسيرة سبع مئة وخمسين غلوة حتى انتهوا الى الكرك الى اليهود الذين يعرفون بالطوبيين'),
(6465, '2 Maccabees', 73, 12, 18, 'فلم يظفروا بتيموتاوس في تلك المواضع لانه كان قد انصرف عنها دون ان يصنع شيئا لكنه ترك في بعض المواضع محرسا منيعا'),
(6466, '2 Maccabees', 73, 12, 19, 'فخرج دوسيتاوس وسوسيباتير من قواد المكابي واهلكا من الجند الذي تركه تيموتاوس في الحصن ما ينيف على عشرة الاف'),
(6467, '2 Maccabees', 73, 12, 20, 'و قسم المكابي جيشه فرقا واقامهما على الفرق وحمل على تيموتاوس وكان معه مئة وعشرون الف راجل والفان وخمس مئة فارس'),
(6468, '2 Maccabees', 73, 12, 21, 'فلما بلغ تيموتاوس مقدم يهوذا وجه النساء والاولاد وسائر الثقل الى مكان يسمى قرنيم وكان موضعا منيعا يصعب فتحه والاقدام عليه لانه محاط بالمضايق'),
(6469, '2 Maccabees', 73, 12, 22, 'و لما بدت اول فرقة من جيش يهوذا داخل الاعداء الرعب والرعدة اذ تراءى لهم من يرى كل شيء فبادروا المفر من كل وجه حتى انبعضهم كان يؤذي بعضا واصاب بعضهم بعضا بحد السيوف'),
(6470, '2 Maccabees', 73, 12, 23, 'و شد يهوذا في اثارهم يثخن في اولئك الكفرة حتى اهلك منهم ثلاثين الف رجل'),
(6471, '2 Maccabees', 73, 12, 24, 'و وقع تيموتاوس في ايدي اصحاب دوسيتاوس وسوسيباتير فطفق يتضرع اليهم بكل وسيلة ان يطلقواه حيا بحجة ان عنده كثيرين من ابائهم واخوتهم اذا هلك يخذلون'),
(6472, '2 Maccabees', 73, 12, 25, 'و اكد لهم العهد بضمانات كثيرة انه يطلقهم سالمين فخلوا سبيله لاجل خلاص اخوتهم'),
(6473, '2 Maccabees', 73, 12, 26, 'ثم اغار يهوذا على قرنيم وهيكل اترجتيس وقتل خمسة وعشرون الف نفس'),
(6474, '2 Maccabees', 73, 12, 27, 'و بعد انكسار اولئك وهلكتهم زحف يهوذا على عفرون احدى المدن الحصينة وكان يسكنها ليسياس وامم شتى وكان على اسوارها شبان من ذوي الباس يقاتلون بشدة ومعهم كثير من المجانيق والسهام'),
(6475, '2 Maccabees', 73, 12, 28, 'فدعا اصحاب يهوذا القدير الذي يحطم باس العدو بشدة فاخذوا المدينة وصرعوا من الذين في داخلها خمسة وعشرين الفا'),
(6476, '2 Maccabees', 73, 12, 29, 'ثم ارتحلوا من هناك وهجموا على مدينة بيت شان وهي على ست مئة غلوة من اورشليم'),
(6477, '2 Maccabees', 73, 12, 30, 'الا ان اليهود المقيمين هناك شهدوا بان اهل بيت شان مصافون لهم وانهم عاملوهم بالاحسان في ازمنة الضيق'),
(6478, '2 Maccabees', 73, 12, 31, 'فشكروهم على صنيعهم واوصوهم ان لا يزالوا معهم على المصافاة ثم جاءوا اورشليم لقرب عيد الاسابيع'),
(6479, '2 Maccabees', 73, 12, 32, 'و بعد العيد المعروف بعيد الخمسين اغاروا على جرجياس قائد ارض ادوم'),
(6480, '2 Maccabees', 73, 12, 33, 'فبرز اليهم في ثلاثة الاف راجل واربع مئة فارس'),
(6481, '2 Maccabees', 73, 12, 34, 'و اقتتل الفريقان فسقط من اليهود نفر قليل'),
(6482, '2 Maccabees', 73, 12, 35, 'و كان فيهم فارس ذو باس يقال له دوسيتاوس من رجال بكينور فادرك جرجياس وقبض على ثوبه واجتذبه بقوة يريد ان ياسر ذلك المنافق حيا فعدا عليه فارس من التراكيين وقطع كتفيه وفر جرجياس الى مريشة'),
(6483, '2 Maccabees', 73, 12, 36, 'و تمادى القتال على اصحاب اسدرين حتى كلوا فدعا يهوذا الرب لياخذ بنصرتهم ويقاتل في مقدمتهم'),
(6484, '2 Maccabees', 73, 12, 37, 'و جعل يهتف بالاناشيد بلسان ابائه ثم صرخ وحمل على اصحاب جرجياس بغتة وكسرهم'),
(6485, '2 Maccabees', 73, 12, 38, 'ثم جمع يهوذا جيشه وسار به الى مدينة عدلام ولما كان اليوم السابع تطهروا بحسب العادة وقضوا السبت هناك'),
(6486, '2 Maccabees', 73, 12, 39, 'و في الغد جاء يهوذا ومن معه على ما تقتضيه السنة ليحملوا جثث القتلى ويدفنوهم مع ذوي قرابتهم في مقابر ابائهم'),
(6487, '2 Maccabees', 73, 12, 40, 'فوجدوا تحت ثياب كل واحد من القتلى انواطا من اصنام يمنيا مما تحرمه الشريعة على اليهود فتبين للجميع ان ذلك كان سبب قتلهم'),
(6488, '2 Maccabees', 73, 12, 41, 'فسبحوا كلهم الرب الديان العادل الذي يكشف الخفايا'),
(6489, '2 Maccabees', 73, 12, 42, 'ثم انثنوا يصلون ويبتهلون ان تمحى تلك الخطيئة المجترمة كل المحو وكان يهوذا النبيل يعظ القوم ان ينزهوا انفسهم عن الخطيئة اذ راوا بعيونهم ما اصاب الذي سقطوا لاجل الخطيئة'),
(6490, '2 Maccabees', 73, 12, 43, 'ثم جمع من كل واحد تقدمة فبلغ المجموع الفي درهم من الفضة فارسلها الى اورشليم ليقدم بها ذبيحة عن الخطيئة وكان ذلك من احسن الصنيع واتقاه لاعتقاده قيامة الموتى'),
(6491, '2 Maccabees', 73, 12, 44, 'لانه لو لم يكن مترجيا قيامة الذين سقطوا لكانت صلاته من اجل الموتى باطلا وعبثا'),
(6492, '2 Maccabees', 73, 12, 45, 'و لاعتباره ان الذين رقدوا بالتقوى قد ادخر لهم ثواب جميل'),
(6493, '2 Maccabees', 73, 12, 46, 'و هو راي مقدس تقوي ولهذا قدم الكفارة عن الموتى ليحلوا من الخطيئة'),
(6494, '2 Maccabees', 73, 13, 1, 'في السنة المئة والتاسعة والاربعين بلغ اصحاب يهوذا ان انطيوكس اوباطور قادم على اليهودية بجيش كثيف'),
(6495, '2 Maccabees', 73, 13, 2, 'و معه ليسياس الوكيل وقيم المصالح ومعهما جيش من اليونان مؤلف من مئة وعشرة الاف راجل وخمسة الاف وثلاث مئة فارس واثنين وعشرين فيلا وثلاث مئة عجلة ذات مناجل'),
(6496, '2 Maccabees', 73, 13, 3, 'فانضم اليهم منلاوس وجعل يحرض انطيوكس بكل نوع من المؤالسة غير مبال بخلاص الوطن بل كان همه ان يرد الى الرئاسة'),
(6497, '2 Maccabees', 73, 13, 4, 'و لكن ملك الملوك هيج سخط انطيوكس على ذلك الكافر فان ليسياس اشربه ان الرجل كان هو السبب في تلك النوازل باسرها فامر بان يذهب به الى بيرية ليقتل على عادة البلاد'),
(6498, '2 Maccabees', 73, 13, 5, 'و هناك برج علوه خمسون ذراعا مملوء رمادا وفيه الة مستديرة تهوي براكبها من جميع جهاتها الى الرماد'),
(6499, '2 Maccabees', 73, 13, 6, 'ففي ذلك الموضع اهلك ذلك المختاس للهيكل الذي كان سببا لشرور شتى مدفوعا اليه بايدي الجميع'),
(6500, '2 Maccabees', 73, 13, 7, 'و بهذه المنية هلك منلاوس المنافق ولم يحصل على تربة يوارى فيها'),
(6501, '2 Maccabees', 73, 13, 8, 'و كان ذلك بكل عدل فانه اذ كان قد اجترم جرائم كثيرة على المذبح الذي ناره ورماده مطهران ذاق منيته في الرماد'),
(6502, '2 Maccabees', 73, 13, 9, 'و اما الملك فما زال متقدما بعتوه وقساوته متوعدا اليهود بامر من البلايا التي انزلها بهم ابوه'),
(6503, '2 Maccabees', 73, 13, 10, 'فلما علم يهوذا بذلك امر الشعب بالابتهال الى الرب نهارا وليلا ان ينصرهم في ذلك اليوم كما كان يفعل من قبل'),
(6504, '2 Maccabees', 73, 13, 11, 'اذ قد اشرفوا على اضمحلال الشريعة والوطن والهيكل المقدس وان لا يدع الامم المجدفة تذل شعبه الذي لم يفرج عنه الا من امديسير'),
(6505, '2 Maccabees', 73, 13, 12, 'ففعلوا كلهم وتضرعوا الى الرب الرحيم بابكاء والصوم والسجود مدة ثلاثة ايام بلا انقطاع ثم حرضهم يهوذا وامرهم بالاجتماع'),
(6506, '2 Maccabees', 73, 13, 13, 'و خلا بالشيوخ وابرم معهم مشورة ان يخرجوا ويقضوا الامر بتاييد الرب قبل ان يدخل جيش الملك اليهودية ويستحوذ على المدينة'),
(6507, '2 Maccabees', 73, 13, 14, 'ففوض الامر الى خالق الكائنات وحض اصحابه ان يقاتلوا ببسالة ويبذلوا انفسهم دون الشريعة والهيكل والمدينة والوطن والدولة ونصب محلته عند مودين'),
(6508, '2 Maccabees', 73, 13, 15, 'و جعل لهم كلمة السر النصر بالله ثم اختار قوما من نخب الشبان وهجم ليلا على مخيم الملك في المحلة وقتل اربعة الاف رجل واهلك اول الفيلة مع القوم الذين كانوا في برجه'),
(6509, '2 Maccabees', 73, 13, 16, 'و ملاوا المحلة رعبا واضطرابا وانقلبوا فائزين بوقاية الرب التي كانت تكتنفه'),
(6510, '2 Maccabees', 73, 13, 17, 'و تمت له هذه النصرة عند طلوع الفجر'),
(6511, '2 Maccabees', 73, 13, 18, 'فلما ذاق الملك ما عند اليهود من البطش عمد الى اخذ المعاقل بالحيلة'),
(6512, '2 Maccabees', 73, 13, 19, 'فحاصر بيت صور وهي محرس منيع ليهود فانكسر وارتد منكوسا خاسرا'),
(6513, '2 Maccabees', 73, 13, 20, 'و كان يهوذا يمد الذين فيها بما يحتاجون اليه'),
(6514, '2 Maccabees', 73, 13, 21, 'و ان رجلا من جيش اليهود اسمه رودكس كاشف العدو باسرارهم فطلبوه وقبضوا عليه وسجنوه'),
(6515, '2 Maccabees', 73, 13, 22, 'فعاد الملك وخاطب اهل بيت صور وعرض عليهم الصلح فعاقدوه وانصرف'),
(6516, '2 Maccabees', 73, 13, 23, 'و بعد ان قاتل يهوذا وانكسر بلغه ان فيلبس الذي كان قد ترك في انطاكية لتدبير الامور قد تمرد عليه فوقع في حيرة وتوسل الى اليهود ودان لهم وحالفهم على اعطاء حقوقهم كلها وسالمهم وقدم ذبيحة واكرم الهيكل واحسن الى الموضع'),
(6517, '2 Maccabees', 73, 13, 24, 'و صافى المكابي ونصبه قائدا وحاكما على البلاد من بطلمايس الى حدود الجرانيين'),
(6518, '2 Maccabees', 73, 13, 25, 'ثم جاء الى بطلمايس وكان اهل المدينة قد شق عليهم ذلك العهد وانكروا عليه فسخ عهودهم'),
(6519, '2 Maccabees', 73, 13, 26, 'فانطلق ليسياس الى الديوان واورد ما استطاع من الحجج فاقنعهم وسكنهم وميلهم الى الرفق ثم عاد الى انطاكية وهكذا انقضى مقدم الملك ورجوعه'),
(6520, '2 Maccabees', 73, 14, 1, 'و بعد مدة ثلاث سنين بلغ اصحاب يهوذا ان ديمتريوس بن سلوقس قد ركب البحر من ميناء طرابلس بجيش كثيف واسطول'),
(6521, '2 Maccabees', 73, 14, 2, 'و استولى على البلاد بعد ما قتل انطيوكس وليسياس وكيله'),
(6522, '2 Maccabees', 73, 14, 3, 'و ان الكيمس الذي كان قد قلد الكهنوت الاعظم ثم انقاد الى النجاسة ايام الاختلاط ايقن ان لا خلاص له البتة ولا سبيل الى ارتقاء المذبح المقدس'),
(6523, '2 Maccabees', 73, 14, 4, 'فاتى ديمتريوس الملك في السنة المئة والحادية والخمسين واهدى اليه اكليلا من ذهب وسعفة واغصانا من زيتون مما يختص بالهيكل وبقي في ذلك اليوم ساكتا'),
(6524, '2 Maccabees', 73, 14, 5, 'ثم اصاب فرصة توافق رعونة مقاصده فان ديمتريوس دعاه الى ديوانه وساله عن احوال اليهود وما في نياتهم'),
(6525, '2 Maccabees', 73, 14, 6, 'فقال ان الحسيديين من اليهود الذين عليهم يهوذا المكابي لا يزالون في الحروب والفتن ولا يدعون للملكة راحة'),
(6526, '2 Maccabees', 73, 14, 7, 'و هاءنذا قد سلبت كرامة ابائي اعني الكهنوت الاعظم فقدمت الى هنا'),
(6527, '2 Maccabees', 73, 14, 8, 'اولا لاوفي خدمتي فيما ياول الى مصلحة الملك وثانيا للسعي في مصلحة قومي لان سفه اولئك الناس قد انزل بامتنا البلاء الشديد'),
(6528, '2 Maccabees', 73, 14, 9, 'فاذ قد اطلعت ايها الملك على تفصيل ذلك فالتفت الى بلادنا وامتنا المبغي عليها بما فيك من الرفق والاحسان الى الجميع'),
(6529, '2 Maccabees', 73, 14, 10, 'فانه ما دام يهوذا باقيا فمن المحال ان تكون الاحوال في دعة'),
(6530, '2 Maccabees', 73, 14, 11, 'و لما اتم مقاله جعل سائر اصدقاء ديمتريوس وهم اعداء ليهوذا ويوغرونه عليه'),
(6531, '2 Maccabees', 73, 14, 12, 'فاستحضر من ساعته نكانور مدبر الفيلة واقامه قائدا على اليهودية وارسله'),
(6532, '2 Maccabees', 73, 14, 13, 'و امره ان يقتل يهوذا ويبدد اصحابه ويقيم الكيمس كاهنا اعظم للهيكل الشهير'),
(6533, '2 Maccabees', 73, 14, 14, 'فاخذ الامم الذين في اليهودية يفرون عن يهوذا وينضمون افواجا الى نكانور وهم يعدون نكبات اليهود ورزاياهم حظا لهم'),
(6534, '2 Maccabees', 73, 14, 15, 'و لما بلغ اليهود قدوم نكانور وانضمام الامم اليه حثوا التراب على رؤوسهم وابتهلوا الى الذي اقام شعبه ليبقى مدى الدهر مدافعا عن ميراثه بايات بينة'),
(6535, '2 Maccabees', 73, 14, 16, 'ثم امرهم القائد فبادروا المسير من هناك والتقوهم عند قرية دساو'),
(6536, '2 Maccabees', 73, 14, 17, 'و كان سمعان اخو يهوذا قد نازل نكانور فجاءته نجدة على حين بغتة فادركه بعض الفشل'),
(6537, '2 Maccabees', 73, 14, 18, 'و لكن لما سمع نكانور بما ابداه اصحاب يهوذا من الباس والبسالة في مدافعاتهم عن الوطن اشفق من ان يفصل الامر بالسلاح'),
(6538, '2 Maccabees', 73, 14, 19, 'فارسل بوسيدونيوس وتاودوتس ومتتيا لعرض الصلح وامضائه'),
(6539, '2 Maccabees', 73, 14, 20, 'فبحثوا في الامر طويلا وعرض القائد ذلك على الجمهور فاجمعوا كلهم على راي واحد وقبلوا العهد'),
(6540, '2 Maccabees', 73, 14, 21, 'و عينوا يوما يواجهونهم فيه سرا فاقبل نكانور وجيء بالكراسي من الجانبين'),
(6541, '2 Maccabees', 73, 14, 22, 'و اقام يهوذا رجالا متسلحين متاهبين في المواضع الموافقة مخافة ان يدهمهم الاعداء بشر ثم تفاوضوا وعقدوا الاتفاق'),
(6542, '2 Maccabees', 73, 14, 23, 'و اقام نكانور باورشليم لا ياتي منكرا واطلق الجيوش التي اجتمعت اليه افواجا'),
(6543, '2 Maccabees', 73, 14, 24, 'و كان كثير التردد الى يهوذا وصبا اليه بقلبه'),
(6544, '2 Maccabees', 73, 14, 25, 'و حثه على الزواج والاستيلاد فتزوج ولبث في راحة وطيب عيش'),
(6545, '2 Maccabees', 73, 14, 26, 'و لما راى الكيمس ما هما فيه من التصافي والتعاهد عاد فاتى الى ديمتريوس وقال ان نكانور يرى في الامور راي الفساد وانه قد عين في موضعه يهوذا الكامن للملكة كاهنا اعظم'),
(6546, '2 Maccabees', 73, 14, 27, 'فاستشاط الملك غضبا ووغر صدره بسعاية ذلك الفاجر فكتب الى نكانور يقول انه ساخط من ذلك العهد ويامره بان يبادر الى ارسال المكابي مقيدا الى انطاكية'),
(6547, '2 Maccabees', 73, 14, 28, 'فلما وقف نكانور على ذلك ادركته الحيرة وصعب عليه ان ينقض عهده ولم ير من الرجل ظلما'),
(6548, '2 Maccabees', 73, 14, 29, 'و لكن اذ لم يجد سبيلا الى مقاومة الملك تربص فرصة ليمضي الامر بالمكيدة'),
(6549, '2 Maccabees', 73, 14, 30, 'و راى المكابي ان نكانور قد تغير عليه ولم يعد يتلقاه ببشاشته المالوفة ففطن ان هذا التغير ليس عن خير فجمع عددا من اصحابه وتغيب عن نكانور'),
(6550, '2 Maccabees', 73, 14, 31, 'فلما راى نكانور ان الرجل قد سبقه بحزمه ودهائه انطلق الى الهيكل العظيم المقدس وكان الكهنة يقدمون الذبائح على عادتهم فامرهم ان يسلموا اليه الرجل'),
(6551, '2 Maccabees', 73, 14, 32, 'فاقسموا وقالوا انهم لا يعلمون اين الذي يطلبه فمد يمينه على الهيكل'),
(6552, '2 Maccabees', 73, 14, 33, 'و اقسم قائلا لئن لم تسلموا الي يهوذا موثقا لاهدمن بيت الله هذا الى الارض ولاقلعن المذبح واشيدن هنا هيكلا شهيرا لديونيسيوس'),
(6553, '2 Maccabees', 73, 14, 34, 'قال هذا وانصرف فرفع الكهنة ايديهم الى السماء ودعوا من هو نصير امتنا على الدوام قائلين'),
(6554, '2 Maccabees', 73, 14, 35, 'يا من هو رب الجميع الغني عن كل شيء لقد حسن لديك ان يكون هيكل سكناك فيما بيننا'),
(6555, '2 Maccabees', 73, 14, 36, 'فالان ايها الرب يا قدوس كل قداسة صن هذا البيت الذي قد طهر عن قليل واحفظه طاهرا الى الابد');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(6556, '2 Maccabees', 73, 14, 37, 'و كان في اورشليم شيخ اسمه رازيس وهو رجل محب لوطنه محمود السمعة يسمى بابي اليهود لما كان عنده من الغيرة عليهم فوشي به الى نكانور'),
(6557, '2 Maccabees', 73, 14, 38, 'و كان فيما سلف من ايام الاختلاط مخلص التمسك بدين اليهود ولم يزل يبذل جسمه ونفسه في سبيل الدين'),
(6558, '2 Maccabees', 73, 14, 39, 'و اراد نكانور ان يبدي ما كان عنده من الحنق على اليهود فارسل اكثر من خمس مئة جندي ليقبضوا عليه'),
(6559, '2 Maccabees', 73, 14, 40, 'لاعتقاده انه ان امسكه فقد انزل بهم مصيبة عظيمة'),
(6560, '2 Maccabees', 73, 14, 41, 'فلما راى الجنود قد اوشكوا ان يستولوا على البرج ويفتحوا باب الدار وقد اطلقوا النار لاحراق الابواب واصبح محاطا من كل جانب وجا نفسه بالسيف'),
(6561, '2 Maccabees', 73, 14, 42, 'و اختار ان يموت بكرامة ولا يصير في ايدي المجرمين ويشتم بما لا يليق باصله الكريم'),
(6562, '2 Maccabees', 73, 14, 43, 'و لكنه لعجلته اخطا المقتل واذ كانت الجنود قد هجمت الى داخل الابواب رقي الى السور بقلب جليد والقى بنفسه من فوق الجنود'),
(6563, '2 Maccabees', 73, 14, 44, 'فانفرجوا لحينهم فسقط في وسط الفرجة'),
(6564, '2 Maccabees', 73, 14, 45, 'و اذ كان به رمق وقد اشتعلت فيه الحمية قام ودمه يتفجر كالينبوع وجراحه بالغة واخترق الجنود عدوا'),
(6565, '2 Maccabees', 73, 14, 46, 'و استولى قائما على صخرة عالية وقد نزف دمه ثم اخرج امعاءه وحملها بيديه وطرحها على الجند ودعا رب الحياة والروح ان يردهما عليه ثم فاضت نفسه'),
(6566, '2 Maccabees', 73, 15, 1, 'و بلغ نكانور ان اصحاب يهوذا في نواحي السامرة فعزم على مفاجاته يوم السبت دون تعرض لخطر الحرب'),
(6567, '2 Maccabees', 73, 15, 2, 'فقال له اليهود الذين شايعوه اضطرارا لا تاخذ القوم بهذه القسوة والخشونة بل ارع حرمة يوم قد اكرمه وقدسه الرقيب على كل شيء'),
(6568, '2 Maccabees', 73, 15, 3, 'فسال ذلك الفاجر وهل في السماء قدير امر بحفظ يوم السبت'),
(6569, '2 Maccabees', 73, 15, 4, 'فقالوا ان في السماء الرب الحي القدير وهو الذي اوصى بحفظ اليوم السابع'),
(6570, '2 Maccabees', 73, 15, 5, 'فقال الرجل وانا ايضا قدير في الارض فامر باخذ السلاح وامضاء اوامر الملك ولكنه لم يتمكن من قضاء ماربه الخبيث'),
(6571, '2 Maccabees', 73, 15, 6, 'و كان نكانور بما عنده من الزهو والصلف مضمرا ان ينصب تذكارا يشير به الى جميع غلباته على اصحاب يهوذا'),
(6572, '2 Maccabees', 73, 15, 7, 'و اما المكابي فلم يزل يثق كل الثقة بان الرب سيؤتيه النصر'),
(6573, '2 Maccabees', 73, 15, 8, 'فحرض اصحابه ان لا يجزعوا من غارة الامم بل يذكروا النجدات التي طال ما امدوا بها من السماء وينتظروا الظفر والنصرة التي سيؤتونها من عند القدير'),
(6574, '2 Maccabees', 73, 15, 9, 'ثم كلمهم عن الشريعة والانبياء وذكر لهم الوقائع التي باشروها حتى اذكى حماستهم'),
(6575, '2 Maccabees', 73, 15, 10, 'و بعدما ثبت عزائمهم شرح لهم كيف نقضت الامم عهودها وحنثت بايمانها'),
(6576, '2 Maccabees', 73, 15, 11, 'و سلح كلا منهم بتعزية كلامه الصالح اكثر مما سلحهم بالتروس والرماح ثم قص عليهم رؤيا يقينية تجلت له في الحلم فشرح بها صدورهم اجمعين'),
(6577, '2 Maccabees', 73, 15, 12, 'و هذه هي الرؤيا قال رايت اونيا الكاهن الاعظم رجل الخير والصلاح المهيب المنظر الحليم الاخلاق صاحب الاقوال الرائعة المواظب منذ صبائه على جميع ضروب الفضائل باسطا يديه ومصليا لاجل جماعة اليهود باسرها'),
(6578, '2 Maccabees', 73, 15, 13, 'ثم تراءى لي رجل كريم الشيبة اغر البهاء عليه جلالة عجيبة سامية'),
(6579, '2 Maccabees', 73, 15, 14, 'فاجاب اونيا وقال هذا محب الاخوة المكثر من الصلوات لاجل الشعب والمدينة المقدسة ارميا نبي الله'),
(6580, '2 Maccabees', 73, 15, 15, 'ثم ان ارميا مد يمينه وناول يهوذا سيفا من ذهب وقال'),
(6581, '2 Maccabees', 73, 15, 16, 'خذ هذا السيف المقدس هبة من عند الله به تحطم الاعداء'),
(6582, '2 Maccabees', 73, 15, 17, 'فطابت قلوبهم باقوال يهوذا الصالحة التي حركت بقوتها حماستهم واثارت نفوس الشبان وعقدوا عزمهم على ان لا يعسكروا بل يهجموا بشجاعة ويحاربوا بكل بسالة حتى يفصلوا الامر اذ كانت المدينة والاقداس والهيكل في خطر'),
(6583, '2 Maccabees', 73, 15, 18, 'و كان اضطرابهم على النساء والاولاد والاخوة وذوي القرابات ايسر وقعا من خوفهم على الهيكل المقدس الذي كان هو الخوف الاعظم والاول'),
(6584, '2 Maccabees', 73, 15, 19, 'و كان الباقون في المدينة في اضطراب شديد من قبل القتال الذي كانوا يتوقعونه في الفضاء'),
(6585, '2 Maccabees', 73, 15, 20, 'و بينا كان الجميع ينتظرون ما ياول اليه الامر وقد ازدلف العدو واصطف الجيش واقيمت الفيلة في مواضعها وترتبت الفرسان على الجناحين'),
(6586, '2 Maccabees', 73, 15, 21, 'تفرس المكابي في كثرة الجيوش وتوفر الاسلحة المختلفة وضراوة الفيلة فرفع يديه الى السماء ودعا الرب الرقيب صانع المعجزات لعلمه ان ليس الظفر بالسلاح ولكنه بقضائه يؤتي الظفر من يستحقه'),
(6587, '2 Maccabees', 73, 15, 22, 'و صلى قائلا انك يا رب قد ارسلت ملاكك في عهد حزقيا ملك يهوذا فقتل من جند سنحاريب مئة وخمسة وثمانين الفا'),
(6588, '2 Maccabees', 73, 15, 23, 'و الان يا ملك السماوات ارسل ملاكا صالحا امامنا يوقع الرعب والرعدة وبعظمة ذراعك'),
(6589, '2 Maccabees', 73, 15, 24, 'ليتروع الذين وافوا على شعبك المقدس مجدفين وكان يهوذا يصلي هكذا'),
(6590, '2 Maccabees', 73, 15, 25, 'و اصحاب نكانور يتقدمون بالابواق والاغاني'),
(6591, '2 Maccabees', 73, 15, 26, 'فواقعهم اصحاب يهوذا بالدعاء والصلوات'),
(6592, '2 Maccabees', 73, 15, 27, 'و فيما هم يقاتلون بالايدي كانوا يصلون الى الله في قلوبهم فصرعوا خمسة وثلاثين الفا وهم في غاية التهلل بمحضر الله ونصرته'),
(6593, '2 Maccabees', 73, 15, 28, 'و لما فرغوا من الجهاد ورجعوا مبتهجين وجدوا نكانور بسلاحه وقد خر قتيلا'),
(6594, '2 Maccabees', 73, 15, 29, 'حينئذ ارتفع الهتاف والزجل وسبحوا الملك العظيم بلسان ابائهم'),
(6595, '2 Maccabees', 73, 15, 30, 'ثم ان يهوذا الذي لم يزل في مقدمة اهل وطنه باذلا دونهم جسده ونفسه وراعيا لبني امته المودة التي اثرهم بها منذ حداثته امر بقطع راس نكانور ويده مع كتفه وحملهما الى اورشليم'),
(6596, '2 Maccabees', 73, 15, 31, 'و لما بلغ الى هناك دعا بني امته والكهنة وقام امام المذبح واستحضر الذين في القلعة'),
(6597, '2 Maccabees', 73, 15, 32, 'و اراهم راس نكانور الفاحش ويد ذلك الفاجر التي مدها متجبرا على بيت القدير المقدس'),
(6598, '2 Maccabees', 73, 15, 33, 'ثم قطع لسان نكانور المنافق وامر بان يقطع قطعا ويطرح الى الطيور وتعلق يد ذلك الاحمق تجاه الهيكل'),
(6599, '2 Maccabees', 73, 15, 34, 'و كان الجميع يباركون الى السماء الرب الحاضر لنصرتهم قائلين تبارك الذي حفظ موضعه من كل دنس'),
(6600, '2 Maccabees', 73, 15, 35, 'و ربط راس نكانور على القلعة ليكون دليلا بينا جليا على نصرة الله'),
(6601, '2 Maccabees', 73, 15, 36, 'ثم رسم الجميع بتوقيع عام ان لا يترك ذلك اليوم بدون احتفال'),
(6602, '2 Maccabees', 73, 15, 37, 'بل يكون عيدا وهو اليوم الثالث عشر من الشهر الثاني عشر الذي يقال له اذار بلسان ارام قبل يوم مردكاي بيوم واحد'),
(6603, '2 Maccabees', 73, 15, 38, 'هذا ما تم من امر نكانور ومنذ تلك الايام عادت المدينة في حوزة العبرانيين وههنا انا ايضا اجعل ختام الكلام'),
(6604, '2 Maccabees', 73, 15, 39, 'فان كنت قد احسنت التاليف واصبت الغرض فذلك ما كنت اتمنى وان كان قد لحقني الوهن والتقصير فاني قد بذلت وسعي'),
(6605, '2 Maccabees', 73, 15, 40, 'ثم كما ان اشرب الخمر وحدها او شرب الماء وحده مضر وانما تطيب الخمر ممزوجة بالماء وتعقب لذة وطربا كذلك تنميق الكلام على هذا الاسلوب يطرب مسامع مطالعي التاليف. انتهى.'),
(6606, '2 Peter', 61, 1, 1, ' سمعان بطرس عبد يسوع المسيح ورسوله ، إلى الذين نالوا معنا إيمانا ثمينا مساويا لنا ، ببر إلهنا والمخلص يسوع المسيح '),
(6607, '2 Peter', 61, 1, 2, ' لتكثر لكم النعمة والسلام بمعرفة الله ويسوع ربنا '),
(6608, '2 Peter', 61, 1, 3, ' كما أن قدرته الإلهية قد وهبت لنا كل ما هو للحياة والتقوى ، بمعرفة الذي دعانا بالمجد والفضيلة '),
(6609, '2 Peter', 61, 1, 4, ' اللذين بهما قد وهب لنا المواعيد العظمى والثمينة ، لكي تصيروا بها شركاء الطبيعة الإلهية ، هاربين من الفساد الذي في العالم بالشهوة '),
(6610, '2 Peter', 61, 1, 5, ' ولهذا عينه - وأنتم باذلون كل اجتهاد - قدموا في إيمانكم فضيلة ، وفي الفضيلة معرفة '),
(6611, '2 Peter', 61, 1, 6, ' وفي المعرفة تعففا ، وفي التعفف صبرا ، وفي الصبر تقوى '),
(6612, '2 Peter', 61, 1, 7, ' وفي التقوى مودة أخوية ، وفي المودة الأخوية محبة '),
(6613, '2 Peter', 61, 1, 8, ' لأن هذه إذا كانت فيكم وكثرت ، تصيركم لا متكاسلين ولا غير مثمرين لمعرفة ربنا يسوع المسيح '),
(6614, '2 Peter', 61, 1, 9, ' لأن الذي ليس عنده هذه ، هو أعمى قصير البصر ، قد نسي تطهير خطاياه السالفة '),
(6615, '2 Peter', 61, 1, 10, ' لذلك بالأكثر اجتهدوا أيها الإخوة أن تجعلوا دعوتكم واختياركم ثابتين . لأنكم إذا فعلتم ذلك ، لن تزلوا أبدا '),
(6616, '2 Peter', 61, 1, 11, ' لأنه هكذا يقدم لكم بسعة دخول إلى ملكوت ربنا ومخلصنا يسوع المسيح الأبدي '),
(6617, '2 Peter', 61, 1, 12, ' لذلك لا أهمل أن أذكركم دائما بهذه الأمور ، وإن كنتم عالمين ومثبتين في الحق الحاضر '),
(6618, '2 Peter', 61, 1, 13, ' ولكني أحسبه حقا - ما دمت في هذا المسكن - أن أنهضكم بالتذكرة '),
(6619, '2 Peter', 61, 1, 14, ' عالما أن خلع مسكني قريب ، كما أعلن لي ربنا يسوع المسيح أيضا '),
(6620, '2 Peter', 61, 1, 15, ' فأجتهد أيضا أن تكونوا بعد خروجي ، تتذكرون كل حين بهذه الأمور '),
(6621, '2 Peter', 61, 1, 16, ' لأننا لم نتبع خرافات مصنعة ، إذ عرفناكم بقوة ربنا يسوع المسيح ومجيئه ، بل قد كنا معاينين عظمته '),
(6622, '2 Peter', 61, 1, 17, ' لأنه أخذ من الله الآب كرامة ومجدا ، إذ أقبل عليه صوت كهذا من المجد الأسنى : هذا هو ابني الحبيب الذي أنا سررت به '),
(6623, '2 Peter', 61, 1, 18, ' ونحن سمعنا هذا الصوت مقبلا من السماء ، إذ كنا معه في الجبل المقدس '),
(6624, '2 Peter', 61, 1, 19, ' وعندنا الكلمة النبوية ، وهي أثبت ، التي تفعلون حسنا إن انتبهتم إليها ، كما إلى سراج منير في موضع مظلم ، إلى أن ينفجر النهار ، ويطلع كوكب الصبح في قلوبكم '),
(6625, '2 Peter', 61, 1, 20, ' عالمين هذا أولا : أن كل نبوة الكتاب ليست من تفسير خاص '),
(6626, '2 Peter', 61, 1, 21, ' لأنه لم تأت نبوة قط بمشيئة إنسان ، بل تكلم أناس الله القديسون مسوقين من الروح القدس '),
(6627, '2 Peter', 61, 2, 1, ' ولكن ، كان أيضا في الشعب أنبياء كذبة ، كما سيكون فيكم أيضا معلمون كذبة ، الذين يدسون بدع هلاك . وإذ هم ينكرون الرب الذي اشتراهم ، يجلبون على أنفسهم هلاكا سريعا '),
(6628, '2 Peter', 61, 2, 2, ' وسيتبع كثيرون تهلكاتهم . الذين بسببهم يجدف على طريق الحق '),
(6629, '2 Peter', 61, 2, 3, ' وهم في الطمع يتجرون بكم بأقوال مصنعة ، الذين دينونتهم منذ القديم لا تتوانى ، وهلاكهم لا ينعس '),
(6630, '2 Peter', 61, 2, 4, ' لأنه إن كان الله لم يشفق على ملائكة قد أخطأوا ، بل في سلاسل الظلام طرحهم في جهنم ، وسلمهم محروسين للقضاء '),
(6631, '2 Peter', 61, 2, 5, ' ولم يشفق على العالم القديم ، بل إنما حفظ نوحا ثامنا كارزا للبر ، إذ جلب طوفانا على عالم الفجار '),
(6632, '2 Peter', 61, 2, 6, ' وإذ رمد مدينتي سدوم وعمورة ، حكم عليهما بالانقلاب ، واضعا عبرة للعتيدين أن يفجروا '),
(6633, '2 Peter', 61, 2, 7, ' وأنقذ لوطا البار ، مغلوبا من سيرة الأردياء في الدعارة '),
(6634, '2 Peter', 61, 2, 8, ' إذ كان البار ، بالنظر والسمع وهو ساكن بينهم ، يعذب يوما فيوما نفسه البارة بالأفعال الأثيمة '),
(6635, '2 Peter', 61, 2, 9, ' يعلم الرب أن ينقذ الأتقياء من التجربة ، ويحفظ الأثمة إلى يوم الدين معاقبين '),
(6636, '2 Peter', 61, 2, 10, ' ولاسيما الذين يذهبون وراء الجسد في شهوة النجاسة ، ويستهينون بالسيادة . جسورون ، معجبون بأنفسهم ، لا يرتعبون أن يفتروا على ذوي الأمجاد '),
(6637, '2 Peter', 61, 2, 11, ' حيث ملائكة - وهم أعظم قوة وقدرة - لا يقدمون عليهم لدى الرب حكم افتراء '),
(6638, '2 Peter', 61, 2, 12, ' أما هؤلاء فكحيوانات غير ناطقة ، طبيعية ، مولودة للصيد والهلاك ، يفترون على ما يجهلون ، فسيهلكون في فسادهم '),
(6639, '2 Peter', 61, 2, 13, ' آخذين أجرة الإثم . الذين يحسبون تنعم يوم لذة . أدناس وعيوب ، يتنعمون في غرورهم صانعين ولائم معكم '),
(6640, '2 Peter', 61, 2, 14, ' لهم عيون مملوة فسقا ، لا تكف عن الخطية ، خادعون النفوس غير الثابتة . لهم قلب متدرب في الطمع . أولاد اللعنة '),
(6641, '2 Peter', 61, 2, 15, ' قد تركوا الطريق المستقيم ، فضلوا ، تابعين طريق بلعام بن بصور الذي أحب أجرة الإثم '),
(6642, '2 Peter', 61, 2, 16, ' ولكنه حصل على توبيخ تعديه ، إذ منع حماقة النبي حمار أعجم ناطقا بصوت إنسان '),
(6643, '2 Peter', 61, 2, 17, ' هؤلاء هم آبار بلا ماء ، غيوم يسوقها النوء . الذين قد حفظ لهم قتام الظلام إلى الأبد '),
(6644, '2 Peter', 61, 2, 18, ' لأنهم إذ ينطقون بعظائم البطل ، يخدعون بشهوات الجسد في الدعارة ، من هرب قليلا من الذين يسيرون في الضلال '),
(6645, '2 Peter', 61, 2, 19, ' واعدين إياهم بالحرية ، وهم أنفسهم عبيد الفساد . لأن ما انغلب منه أحد ، فهو له مستعبد أيضا '),
(6646, '2 Peter', 61, 2, 20, ' لأنه إذا كانوا ، بعدما هربوا من نجاسات العالم ، بمعرفة الرب والمخلص يسوع المسيح ، يرتبكون أيضا فيها ، فينغلبون ، فقد صارت لهم الأواخر أشر من الأوائل '),
(6647, '2 Peter', 61, 2, 21, ' لأنه كان خيرا لهم لو لم يعرفوا طريق البر ، من أنهم بعدما عرفوا ، يرتدون عن الوصية المقدسة المسلمة لهم '),
(6648, '2 Peter', 61, 2, 22, ' قد أصابهم ما في المثل الصادق : كلب قد عاد إلى قيئه ، وخنزيرة مغتسلة إلى مراغة الحمأة '),
(6649, '2 Peter', 61, 3, 1, ' هذه أكتبها الآن إليكم رسالة ثانية أيها الأحباء ، فيهما أنهض بالتذكرة ذهنكم النقي '),
(6650, '2 Peter', 61, 3, 2, ' لتذكروا الأقوال التي قالها سابقا الأنبياء القديسون ، ووصيتنا نحن الرسل ، وصية الرب والمخلص '),
(6651, '2 Peter', 61, 3, 3, ' عالمين هذا أولا : أنه سيأتي في آخر الأيام قوم مستهزئون ، سالكين بحسب شهوات أنفسهم '),
(6652, '2 Peter', 61, 3, 4, ' وقائلين : أين هو موعد مجيئه ؟ لأنه من حين رقد الآباء كل شيء باق هكذا من بدء الخليقة '),
(6653, '2 Peter', 61, 3, 5, ' لأن هذا يخفى عليهم بإرادتهم : أن السماوات كانت منذ القديم ، والأرض بكلمة الله قائمة من الماء وبالماء '),
(6654, '2 Peter', 61, 3, 6, ' اللواتي بهن العالم الكائن حينئذ فاض عليه الماء فهلك '),
(6655, '2 Peter', 61, 3, 7, ' وأما السماوات والأرض الكائنة الآن ، فهي مخزونة بتلك الكلمة عينها ، محفوظة للنار إلى يوم الدين وهلاك الناس الفجار '),
(6656, '2 Peter', 61, 3, 8, ' ولكن لا يخف عليكم هذا الشيء الواحد أيها الأحباء : أن يوما واحدا عند الرب كألف سنة ، وألف سنة كيوم واحد '),
(6657, '2 Peter', 61, 3, 9, ' لا يتباطأ الرب عن وعده كما يحسب قوم التباطؤ ، لكنه يتأنى علينا ، وهو لا يشاء أن يهلك أناس ، بل أن يقبل الجميع إلى التوبة '),
(6658, '2 Peter', 61, 3, 10, ' ولكن سيأتي كلص في الليل ، يوم الرب ، الذي فيه تزول السماوات بضجيج ، وتنحل العناصر محترقة ، وتحترق الأرض والمصنوعات التي فيها '),
(6659, '2 Peter', 61, 3, 11, ' فبما أن هذه كلها تنحل ، أي أناس يجب أن تكونوا أنتم في سيرة مقدسة وتقوى '),
(6660, '2 Peter', 61, 3, 12, ' منتظرين وطالبين سرعة مجيء يوم الرب ، الذي به تنحل السماوات ملتهبة ، والعناصر محترقة تذوب '),
(6661, '2 Peter', 61, 3, 13, ' ولكننا بحسب وعده ننتظر سماوات جديدة ، وأرضا جديدة ، يسكن فيها البر '),
(6662, '2 Peter', 61, 3, 14, ' لذلك أيها الأحباء ، إذ أنتم منتظرون هذه ، اجتهدوا لتوجدوا عنده بلا دنس ولا عيب ، في سلام '),
(6663, '2 Peter', 61, 3, 15, ' واحسبوا أناة ربنا خلاصا ، كما كتب إليكم أخونا الحبيب بولس أيضا بحسب الحكمة المعطاة له '),
(6664, '2 Peter', 61, 3, 16, ' كما في الرسائل كلها أيضا ، متكلما فيها عن هذه الأمور ، التي فيها أشياء عسرة الفهم ، يحرفها غير العلماء وغير الثابتين ، كباقي الكتب أيضا ، لهلاك أنفسهم '),
(6665, '2 Peter', 61, 3, 17, ' فأنتم أيها الأحباء ، إذ قد سبقتم فعرفتم ، احترسوا من أن تنقادوا بضلال الأردياء ، فتسقطوا من ثباتكم '),
(6666, '2 Peter', 61, 3, 18, ' ولكن انموا في النعمة وفي معرفة ربنا ومخلصنا يسوع المسيح . له المجد الآن وإلى يوم الدهر . آمين '),
(6667, '2 Samuel', 10, 1, 1, ' وكان بعد موت شاول ورجوع داود من مضاربة العمالقة ، أن داود أقام في صقلغ يومين '),
(6668, '2 Samuel', 10, 1, 2, ' وفي اليوم الثالث إذا برجل أتى من المحلة من عند شاول وثيابه ممزقة وعلى رأسه تراب . فلما جاء إلى داود خر إلى الأرض وسجد '),
(6669, '2 Samuel', 10, 1, 3, ' فقال له داود : من أين أتيت ؟  . فقال له : من محلة إسرائيل نجوت '),
(6670, '2 Samuel', 10, 1, 4, ' فقال له داود : كيف كان الأمر ؟ أخبرني . فقال : إن الشعب قد هرب من القتال ، وسقط أيضا كثيرون من الشعب وماتوا ، ومات شاول ويوناثان ابنه أيضا '),
(6671, '2 Samuel', 10, 1, 5, ' فقال داود للغلام الذي أخبره : كيف عرفت أنه قد مات شاول ويوناثان ابنه '),
(6672, '2 Samuel', 10, 1, 6, ' فقال الغلام الذي أخبره : اتفق أني كنت في جبل جلبوع وإذا شاول يتوكأ على رمحه ، وإذا بالمركبات والفرسان يشدون وراءه '),
(6673, '2 Samuel', 10, 1, 7, ' فالتفت إلى ورائه فرآني ودعاني فقلت : هأنذا '),
(6674, '2 Samuel', 10, 1, 8, ' فقال لي : من أنت ؟ فقلت له : عماليقي أنا '),
(6675, '2 Samuel', 10, 1, 9, ' فقال لي : قف علي واقتلني لأنه قد اعتراني الدوار ، لأن كل نفسي بعد في '),
(6676, '2 Samuel', 10, 1, 10, ' فوقفت عليه وقتلته لأني علمت أنه لا يعيش بعد سقوطه ، وأخذت الإكليل الذي على رأسه والسوار الذي على ذراعه وأتيت بهما إلى سيدي ههنا '),
(6677, '2 Samuel', 10, 1, 11, ' فأمسك داود ثيابه ومزقها ، وكذا جميع الرجال الذين معه '),
(6678, '2 Samuel', 10, 1, 12, ' وندبوا وبكوا وصاموا إلى المساء على شاول وعلى يوناثان ابنه ، وعلى شعب الرب وعلى بيت إسرائيل لأنهم سقطوا بالسيف '),
(6679, '2 Samuel', 10, 1, 13, ' ثم قال داود للغلام الذي أخبره : من أين أنت ؟  . فقال : أنا ابن رجل غريب ، عماليقي '),
(6680, '2 Samuel', 10, 1, 14, ' فقال له داود : كيف لم تخف أن تمد يدك لتهلك مسيح الرب '),
(6681, '2 Samuel', 10, 1, 15, ' ثم دعا داود واحدا من الغلمان وقال : تقدم . أوقع به . فضربه فمات '),
(6682, '2 Samuel', 10, 1, 16, ' فقال له داود : دمك على رأسك لأن فمك شهد عليك قائلا : أنا قتلت مسيح الرب '),
(6683, '2 Samuel', 10, 1, 17, ' ورثا داود بهذه المرثاة شاول ويوناثان ابنه '),
(6684, '2 Samuel', 10, 1, 18, ' وقال أن يتعلم بنو يهوذا نشيد القوس . هوذا ذلك مكتوب في سفر ياشر '),
(6685, '2 Samuel', 10, 1, 19, ' الظبي يا إسرائيل مقتول على شوامخك . كيف سقط الجبابرة '),
(6686, '2 Samuel', 10, 1, 20, ' لا تخبروا في جت . لا تبشروا في أسواق أشقلون ، لئلا تفرح بنات الفلسطينيين ، لئلا تشمت بنات الغلف '),
(6687, '2 Samuel', 10, 1, 21, ' ياجبال جلبوع لا يكن طل ولا مطر عليكن ، ولا حقول تقدمات ، لأنه هناك طرح مجن الجبابرة ، مجن شاول بلا مسح بالدهن '),
(6688, '2 Samuel', 10, 1, 22, ' من دم القتلى ، من شحم الجبابرة لم ترجع قوس يوناثان إلى الوراء ، وسيف شاول لم يرجع خائبا '),
(6689, '2 Samuel', 10, 1, 23, ' شاول ويوناثان المحبوبان والحلوان في حياتهما لم يفترقا في موتهما . أخف من النسور وأشد من الأسود '),
(6690, '2 Samuel', 10, 1, 24, ' يا بنات إسرائيل ، ابكين شاول الذي ألبسكن قرمزا بالتنعم ، وجعل حلي الذهب على ملابسكن '),
(6691, '2 Samuel', 10, 4, 2, ' وكان لابن شاول رجلان رئيسا غزاة ، اسم الواحد بعنة واسم الآخر ركاب ، ابنا رمون البئيروتي من بني بنيامين ، لأن بئيروت حسبت لبنيامين '),
(6692, '2 Samuel', 10, 4, 3, ' وهرب البئيروتيون إلى جتايم وتغربوا هناك إلى هذا اليوم '),
(6693, '2 Samuel', 10, 4, 4, ' وكان ليوناثان بن شاول ابن مضروب الرجلين ، كان ابن خمس سنين عند مجيء خبر شاول ويوناثان من يزرعيل ، فحملته مربيته وهربت . ولما كانت مسرعة لتهرب وقع وصار أعرج . واسمه مفيبوشث '),
(6694, '2 Samuel', 10, 4, 5, ' وسار ابنا رمون البئيروتي ، ركاب وبعنة ، ودخلا عند حر النهار إلى بيت إيشبوشث وهو نائم نومة الظهيرة '),
(6695, '2 Samuel', 10, 4, 6, ' فدخلا إلى وسط البيت ليأخذا حنطة ، وضرباه في بطنه . ثم أفلت ركاب وبعنة أخوه '),
(6696, '2 Samuel', 10, 4, 7, ' فعند دخولهما البيت كان هو مضطجعا على سريره في مخدع نومه ، فضرباه وقتلاه وقطعا رأسه ، وأخذا رأسه وسارا في طريق العربة الليل كله '),
(6697, '2 Samuel', 10, 4, 8, ' وأتيا برأس إيشبوشث إلى داود إلى حبرون ، وقالا للملك : هوذا رأس إيشبوشث بن شاول عدوك الذي كان يطلب نفسك . وقد أعطى الرب لسيدي الملك انتقاما في هذا اليوم من شاول ومن نسله '),
(6698, '2 Samuel', 10, 4, 9, ' فأجاب داود ركاب وبعنة أخاه ، ابني رمون البئيروتي ، وقال لهما : حي هو الرب الذي فدى نفسي من كل ضيق '),
(6699, '2 Samuel', 10, 4, 10, ' إن الذي أخبرني قائلا : هوذا قد مات شاول ، وكان في عيني نفسه كمبشر ، قبضت عليه وقتلته في صقلغ . ذلك أعطيته بشارة '),
(6700, '2 Samuel', 10, 4, 11, ' فكم بالحري إذا كان رجلان باغيان يقتلان رجلا صديقا في بيته ، على سريره ؟ فالآن أما أطلب دمه من أيديكما ، وأنزعكما من الأرض '),
(6701, '2 Samuel', 10, 4, 12, ' وأمر داود الغلمان فقتلوهما ، وقطعوا أيديهما وأرجلهما ، وعلقوهما على البركة في حبرون . وأما رأس إيشبوشث فأخذوه ودفنوه في قبر أبنير في حبرون '),
(6702, '2 Samuel', 10, 5, 1, ' وجاء جميع أسباط إسرائيل إلى داود ، إلى حبرون ، وتكلموا قائلين : هوذا عظمك ولحمك نحن '),
(6703, '2 Samuel', 10, 5, 2, ' ومنذ أمس وما قبله ، حين كان شاول ملكا علينا ، قد كنت أنت تخرج وتدخل إسرائيل . وقد قال لك الرب : أنت ترعى شعبي إسرائيل ، وأنت تكون رئيسا على إسرائيل '),
(6704, '2 Samuel', 10, 5, 3, ' وجاء جميع شيوخ إسرائيل إلى الملك ، إلى حبرون ، فقطع الملك داود معهم عهدا في حبرون أمام الرب . ومسحوا داود ملكا على إسرائيل '),
(6705, '2 Samuel', 10, 5, 4, ' كان داود ابن ثلاثين سنة حين ملك ، وملك أربعين سنة '),
(6706, '2 Samuel', 10, 5, 5, ' في حبرون ملك على يهوذا سبع سنين وستة أشهر . وفي أورشليم ملك ثلاثا وثلاثين سنة على جميع إسرائيل ويهوذا '),
(6707, '2 Samuel', 10, 5, 6, ' وذهب الملك ورجاله إلى أورشليم ، إلى اليبوسيين سكان الأرض . فكلموا داود قائلين : لا تدخل إلى هنا ، ما لم تنزع العميان والعرج . أي لا يدخل داود إلى هنا '),
(6708, '2 Samuel', 10, 5, 7, ' وأخذ داود حصن صهيون ، هي مدينة داود '),
(6709, '2 Samuel', 10, 5, 8, ' وقال داود في ذلك اليوم : إن الذي يضرب اليبوسيين ويبلغ إلى القناة والعرج والعمي المبغضين من نفس داود . لذلك يقولون : لا يدخل البيت أعمى أو أعرج '),
(6710, '2 Samuel', 10, 5, 9, ' وأقام داود في الحصن وسماه مدينة داود . وبنى داود مستديرا من القلعة فداخلا '),
(6711, '2 Samuel', 10, 5, 10, ' وكان داود يتزايد متعظما ، والرب إله الجنود معه '),
(6712, '2 Samuel', 10, 5, 11, ' وأرسل حيرام ملك صور رسلا إلى داود ، وخشب أرز ونجارين وبنائين فبنوا لداود بيتا '),
(6713, '2 Samuel', 10, 5, 12, ' وعلم داود أن الرب قد أثبته ملكا على إسرائيل ، وأنه قد رفع ملكه من أجل شعبه إسرائيل '),
(6714, '2 Samuel', 10, 5, 13, ' وأخذ داود أيضا سراري ونساء من أورشليم بعد مجيئه من حبرون ، فولد أيضا لداود بنون وبنات '),
(6715, '2 Samuel', 10, 5, 14, ' وهذه أسماء الذين ولدوا له في أورشليم : شموع وشوباب وناثان وسليمان '),
(6716, '2 Samuel', 10, 5, 15, ' ويبحار وأليشوع ونافج ويافيع '),
(6717, '2 Samuel', 10, 5, 16, ' وأليشمع وأليداع وأليفلط '),
(6718, '2 Samuel', 10, 5, 17, ' وسمع الفلسطينيون أنهم قد مسحوا داود ملكا على إسرائيل ، فصعد جميع الفلسطينيين ليفتشوا على داود . ولما سمع داود نزل إلى الحصن '),
(6719, '2 Samuel', 10, 5, 18, ' وجاء الفلسطينيون وانتشروا في وادي الرفائيين '),
(6720, '2 Samuel', 10, 5, 19, ' وسأل داود من الرب قائلا : أأصعد إلى الفلسطينيين ؟ أتدفعهم ليدي ؟  . فقال الرب لداود : اصعد ، لأني دفعا أدفع الفلسطينيين ليدك '),
(6721, '2 Samuel', 10, 5, 20, ' فجاء داود إلى بعل فراصيم وضربهم داود هناك ، وقال : قد اقتحم الرب أعدائي أمامي كاقتحام المياه . لذلك دعى اسم ذلك الموضع بعل فراصيم '),
(6722, '2 Samuel', 10, 5, 21, ' وتركوا هناك أصنامهم فنزعها داود ورجاله '),
(6723, '2 Samuel', 10, 5, 22, ' ثم عاد الفلسطينيون فصعدوا أيضا وانتشروا في وادي الرفائيين '),
(6724, '2 Samuel', 10, 5, 23, ' فسأل داود من الرب ، فقال : لا تصعد ، بل در من ورائهم ، وهلم عليهم مقابل أشجار البكا '),
(6725, '2 Samuel', 10, 5, 24, ' وعندما تسمع صوت خطوات في رؤوس أشجار البكا ، حينئذ احترص ، لأنه إذ ذاك يخرج الرب أمامك لضرب محلة الفلسطينيين '),
(6726, '2 Samuel', 10, 5, 25, ' ففعل داود كذلك كما أمره الرب ، وضرب الفلسطينيين من جبع إلى مدخل جازر '),
(6727, '2 Samuel', 10, 6, 1, ' وجمع داود أيضا جميع المنتخبين في إسرائيل ، ثلاثين ألفا '),
(6728, '2 Samuel', 10, 6, 2, ' وقام داود وذهب هو وجميع الشعب الذي معه من بعلة يهوذا ، ليصعدوا من هناك تابوت الله ، الذي يدعى عليه بالاسم ، اسم رب الجنود ، الجالس على الكروبيم '),
(6729, '2 Samuel', 10, 6, 3, ' فأركبوا تابوت الله على عجلة جديدة ، وحملوه من بيت أبيناداب الذي في الأكمة . وكان عزة وأخيو ، ابنا أبيناداب يسوقان العجلة الجديدة '),
(6730, '2 Samuel', 10, 6, 4, ' فأخذوها من بيت أبيناداب الذي في الأكمة مع تابوت الله . وكان أخيو يسير أمام التابوت '),
(6731, '2 Samuel', 10, 6, 5, ' وداود وكل بيت إسرائيل يلعبون أمام الرب بكل أنواع الآلات من خشب السرو ، بالعيدان وبالرباب وبالدفوف وبالجنوك وبالصنوج '),
(6732, '2 Samuel', 10, 6, 6, ' ولما انتهوا إلى بيدر ناخون مد عزة يده إلى تابوت الله وأمسكه ، لأن الثيران انشمصت '),
(6733, '2 Samuel', 10, 6, 7, ' فحمي غضب الرب على عزة ، وضربه الله هناك لأجل غفله ، فمات هناك لدى تابوت الله '),
(6734, '2 Samuel', 10, 6, 8, ' فاغتاظ داود لأن الرب اقتحم عزة اقتحاما ، وسمى ذلك الموضع فارص عزة إلى هذا اليوم '),
(6735, '2 Samuel', 10, 6, 9, ' وخاف داود من الرب في ذلك اليوم وقال : كيف يأتي إلي تابوت الرب '),
(6736, '2 Samuel', 10, 6, 10, ' ولم يشأ داود أن ينقل تابوت الرب إليه ، إلى مدينة داود ، فمال به داود إلى بيت عوبيد أدوم الجتي '),
(6737, '2 Samuel', 10, 6, 11, ' وبقي تابوت الرب في بيت عوبيد أدوم الجتي ثلاثة أشهر . وبارك الرب عوبيد أدوم وكل بيته '),
(6738, '2 Samuel', 10, 6, 12, ' فأخبر الملك داود وقيل له : قد بارك الرب بيت عوبيد أدوم وكل ما له بسبب تابوت الله . فذهب داود وأصعد تابوت الله من بيت عوبيد أدوم إلى مدينة داود بفرح '),
(6739, '2 Samuel', 10, 6, 13, ' وكان كلما خطا حاملوا تابوت الرب ست خطوات يذبح ثورا وعجلا معلوفا '),
(6740, '2 Samuel', 10, 6, 14, ' وكان داود يرقص بكل قوته أمام الرب . وكان داود متنطقا بأفود من كتان '),
(6741, '2 Samuel', 10, 6, 15, ' فأصعد داود وجميع بيت إسرائيل تابوت الرب بالهتاف وبصوت البوق '),
(6742, '2 Samuel', 10, 6, 16, ' ولما دخل تابوت الرب مدينة داود ، أشرفت ميكال بنت شاول من الكوة ورأت الملك داود يطفر ويرقص أمام الرب ، فاحتقرته في قلبها '),
(6743, '2 Samuel', 10, 6, 17, ' فأدخلوا تابوت الرب وأوقفوه في مكانه في وسط الخيمة التي نصبها له داود . وأصعد داود محرقات أمام الرب وذبائح سلامة '),
(6744, '2 Samuel', 10, 6, 18, ' ولما انتهى داود من إصعاد المحرقات وذبائح السلامة بارك الشعب باسم رب الجنود '),
(6745, '2 Samuel', 10, 6, 19, ' وقسم على جميع الشعب ، على كل جمهور إسرائيل رجالا ونساء ، على كل واحد رغيف خبز وكأس خمر وقرص زبيب . ثم ذهب كل الشعب كل واحد إلى بيته '),
(6746, '2 Samuel', 10, 6, 20, ' ورجع داود ليبارك بيته . فخرجت ميكال بنت شاول لاستقبال داود ، وقالت : ما كان أكرم ملك إسرائيل اليوم ، حيث تكشف اليوم في أعين إماء عبيده كما يتكشف أحد السفهاء '),
(6747, '2 Samuel', 10, 6, 21, ' فقال داود لميكال : إنما أمام الرب الذي اختارني دون أبيك ودون كل بيته ليقيمني رئيسا على شعب الرب إسرائيل ، فلعبت أمام الرب '),
(6748, '2 Samuel', 10, 6, 22, ' وإني أتصاغر دون ذلك وأكون وضيعا في عيني نفسي ، وأما عند الإماء التي ذكرت فأتمجد '),
(6749, '2 Samuel', 10, 6, 23, ' ولم يكن لميكال بنت شاول ولد إلى يوم موتها '),
(6750, '2 Samuel', 10, 7, 1, ' وكان لما سكن الملك في بيته ، وأراحه الرب من كل الجهات من جميع أعدائه '),
(6751, '2 Samuel', 10, 7, 2, ' أن الملك قال لناثان النبي : انظر . إني ساكن في بيت من أرز ، وتابوت الله ساكن داخل الشقق '),
(6752, '2 Samuel', 10, 7, 3, ' فقال ناثان للملك : اذهب افعل كل ما بقلبك ، لأن الرب معك '),
(6753, '2 Samuel', 10, 7, 4, ' وفي تلك الليلة كان كلام الرب إلى ناثان قائلا '),
(6754, '2 Samuel', 10, 7, 5, ' اذهب وقل لعبدي داود : هكذا قال الرب : أأنت تبني لي بيتا لسكناي '),
(6755, '2 Samuel', 10, 7, 6, ' لأني لم أسكن في بيت منذ يوم أصعدت بني إسرائيل من مصر إلى هذا اليوم ، بل كنت أسير في خيمة وفي مسكن '),
(6756, '2 Samuel', 10, 7, 7, ' في كل ما سرت مع جميع بني إسرائيل ، هل تكلمت بكلمة إلى أحد قضاة إسرائيل الذين أمرتهم أن يرعوا شعبي إسرائيل قائلا : لماذا لم تبنوا لي بيتا من الأرز '),
(6757, '2 Samuel', 10, 7, 8, ' والآن فهكذا تقول لعبدي داود : هكذا قال رب الجنود : أنا أخذتك من المربض من وراء الغنم لتكون رئيسا على شعبي إسرائيل '),
(6758, '2 Samuel', 10, 7, 9, ' وكنت معك حيثما توجهت ، وقرضت جميع أعدائك من أمامك ، وعملت لك اسما عظيما كاسم العظماء الذين في الأرض '),
(6759, '2 Samuel', 10, 7, 10, ' وعينت مكانا لشعبي إسرائيل وغرسته ، فسكن في مكانه ، ولا يضطرب بعد ، ولا يعود بنو الإثم يذللونه كما في الأول '),
(6760, '2 Samuel', 10, 7, 11, ' ومنذ يوم أقمت فيه قضاة على شعبي إسرائيل . وقد أرحتك من جميع أعدائك . والرب يخبرك أن الرب يصنع لك بيتا '),
(6761, '2 Samuel', 10, 7, 12, ' متى كملت أيامك واضطجعت مع آبائك ، أقيم بعدك نسلك الذي يخرج من أحشائك وأثبت مملكته '),
(6762, '2 Samuel', 10, 7, 13, ' هو يبني بيتا لاسمي ، وأنا أثبت كرسي مملكته إلى الأبد '),
(6763, '2 Samuel', 10, 7, 14, ' أنا أكون له أبا وهو يكون لي ابنا . إن تعوج أؤدبه بقضيب الناس وبضربات بني آدم '),
(6764, '2 Samuel', 10, 1, 25, ' كيف سقط الجبابرة في وسط الحرب يوناثان على شوامخك مقتول '),
(6765, '2 Samuel', 10, 1, 26, ' قد تضايقت عليك يا أخي يوناثان . كنت حلوا لي جدا . محبتك لي أعجب من محبة النساء '),
(6766, '2 Samuel', 10, 1, 27, ' كيف سقط الجبابرة وبادت آلات الحرب '),
(6767, '2 Samuel', 10, 2, 1, ' وكان بعد ذلك أن داود سأل الرب قائلا : أأصعد إلى إحدى مدائن يهوذا ؟  . فقال له الرب : اصعد . فقال داود : إلى أين أصعد ؟  . فقال : إلى حبرون '),
(6768, '2 Samuel', 10, 2, 2, ' فصعد داود إلى هناك هو وامرأتاه أخينوعم اليزرعيلية وأبيجايل امرأة نابال الكرملي '),
(6769, '2 Samuel', 10, 2, 3, ' وأصعد داود رجاله الذين معه ، كل واحد وبيته ، وسكنوا في مدن حبرون '),
(6770, '2 Samuel', 10, 2, 4, ' وأتى رجال يهوذا ومسحوا هناك داود ملكا على بيت يهوذا . وأخبروا داود قائلين : إن رجال يابيش جلعاد هم الذين دفنوا شاول '),
(6771, '2 Samuel', 10, 2, 5, ' فأرسل داود رسلا إلى أهل يابيش جلعاد يقول لهم : مباركون أنتم من الرب ، إذ قد فعلتم هذا المعروف بسيدكم شاول فدفنتموه '),
(6772, '2 Samuel', 10, 2, 6, ' والآن ليصنع الرب معكم إحسانا وحقا ، وأنا أيضا أفعل معكم هذا الخير لأنكم فعلتم هذا الأمر '),
(6773, '2 Samuel', 10, 2, 7, ' والآن فلتتشدد أيديكم وكونوا ذوي بأس ، لأنه قد مات سيدكم شاول ، وإياي مسح بيت يهوذا ملكا عليهم '),
(6774, '2 Samuel', 10, 2, 8, ' وأما أبنير بن نير ، رئيس جيش شاول ، فأخذ إيشبوشث بن شاول وعبر به إلى محنايم '),
(6775, '2 Samuel', 10, 2, 9, ' وجعله ملكا على جلعاد وعلى الأشوريين وعلى يزرعيل وعلى أفرايم وعلى بنيامين وعلى كل إسرائيل '),
(6776, '2 Samuel', 10, 2, 10, ' وكان إيشبوشث بن شاول ابن أربعين سنة حين ملك على إسرائيل ، وملك سنتين . وأما بيت يهوذا فإنما اتبعوا داود '),
(6777, '2 Samuel', 10, 2, 11, ' وكانت المدة التي ملك فيها داود في حبرون على بيت يهوذا سبع سنين وستة أشهر '),
(6778, '2 Samuel', 10, 2, 12, ' وخرج أبنير بن نير وعبيد إيشبوشث بن شاول من محنايم إلى جبعون '),
(6779, '2 Samuel', 10, 2, 13, ' وخرج يوآب ابن صروية وعبيد داود ، فالتقوا جميعا على بركة جبعون ، وجلسوا هؤلاء على البركة من هنا وهؤلاء على البركة من هناك '),
(6780, '2 Samuel', 10, 2, 14, ' فقال أبنير ليوآب : ليقم الغلمان ويتكافحوا أمامنا . فقال يوآب : ليقوموا '),
(6781, '2 Samuel', 10, 2, 15, ' فقاموا وعبروا بالعدد ، اثنا عشر لأجل بنيامين وإيشبوشث بن شاول ، واثنا عشر من عبيد داود '),
(6782, '2 Samuel', 10, 2, 16, ' وأمسك كل واحد برأس صاحبه وضرب سيفه في جنب صاحبه وسقطوا جميعا . فدعي ذلك الموضع حلقث هصوريم ، التي هي في جبعون '),
(6783, '2 Samuel', 10, 2, 17, ' وكان القتال شديدا جدا في ذلك اليوم ، وانكسر أبنير ورجال إسرائيل أمام عبيد داود '),
(6784, '2 Samuel', 10, 2, 18, ' وكان هناك بنو صروية الثلاثة : يوآب وأبيشاي وعسائيل . وكان عسائيل خفيف الرجلين كظبي البر '),
(6785, '2 Samuel', 10, 2, 19, ' فسعى عسائيل وراء أبنير ، ولم يمل في السير يمنة ولا يسرة من وراء أبنير '),
(6786, '2 Samuel', 10, 2, 20, ' فالتفت أبنير إلى ورائه وقال : أأنت عسائيل ؟  . فقال : أنا هو '),
(6787, '2 Samuel', 10, 2, 21, ' فقال له أبنير : مل إلى يمينك أو إلى يسارك واقبض على أحد الغلمان وخذ لنفسك سلبه . فلم يشأ عسائيل أن يميل من ورائه '),
(6788, '2 Samuel', 10, 2, 22, ' ثم عاد أبنير وقال لعسائيل : مل من ورائي . لماذا أضربك إلى الأرض ؟ فكيف أرفع وجهي لدى يوآب أخيك '),
(6789, '2 Samuel', 10, 2, 23, ' فأبى أن يميل ، فضربه أبنير بزج الرمح في بطنه ، فخرج الرمح من خلفه ، فسقط هناك ومات في مكانه . وكان كل من يأتي إلى الموضع الذي سقط فيه عسائيل ومات يقف '),
(6790, '2 Samuel', 10, 2, 24, ' وسعى يوآب وأبيشاي وراء أبنير ، وغابت الشمس عندما أتيا إلى تل أمة الذي تجاه جيح في طريق برية جبعون '),
(6791, '2 Samuel', 10, 2, 25, ' فاجتمع بنو بنيامين وراء أبنير وصاروا جماعة واحدة ، ووقفوا على رأس تل واحد '),
(6792, '2 Samuel', 10, 2, 26, ' فنادى أبنير يوآب وقال : هل إلى الأبد يأكل السيف ؟ ألم تعلم أنها تكون مرارة في الأخير ؟ فحتى متى لا تقول للشعب أن يرجعوا من وراء إخوتهم '),
(6793, '2 Samuel', 10, 2, 27, ' فقال يوآب : حي هو الله ، إنه لو لم تتكلم لكان الشعب في الصباح قد صعد كل واحد من وراء أخيه '),
(6794, '2 Samuel', 10, 2, 28, ' وضرب يوآب بالبوق فوقف جميع الشعب ولم يسعوا بعد وراء إسرائيل ولا عادوا إلى المحاربة '),
(6795, '2 Samuel', 10, 2, 29, ' فسار أبنير ورجاله في العربة ذلك الليل كله وعبروا الأردن ، وساروا في كل الشعب وجاءوا إلى محنايم '),
(6796, '2 Samuel', 10, 2, 30, ' ورجع يوآب من وراء أبنير وجمع كل الشعب . وفقد من عبيد داود تسعة عشر رجلا وعسائيل '),
(6797, '2 Samuel', 10, 2, 31, ' وضرب عبيد داود من بنيامين ومن رجال أبنير ، فمات ثلاث مئة وستون رجلا '),
(6798, '2 Samuel', 10, 2, 32, ' ورفعوا عسائيل ودفنوه في قبر أبيه الذي في بيت لحم . وسار يوآب ورجاله الليل كله وأصبحوا في حبرون '),
(6799, '2 Samuel', 10, 3, 1, ' وكانت الحرب طويلة بين بيت شاول وبيت داود ، وكان داود يذهب يتقوى ، وبيت شاول يذهب يضعف '),
(6800, '2 Samuel', 10, 3, 2, ' وولد لداود بنون في حبرون . وكان بكره أمنون من أخينوعم اليزرعيلية '),
(6801, '2 Samuel', 10, 3, 3, ' وثانيه كيلآب من أبيجايل امرأة نابال الكرملي ، والثالث أبشالوم ابن معكة بنت تلماي ملك جشور '),
(6802, '2 Samuel', 10, 3, 4, ' والرابع أدونيا ابن حجيث ، والخامس شفطيا ابن أبيطال '),
(6803, '2 Samuel', 10, 3, 5, ' والسادس يثرعام من عجلة امرأة داود . هؤلاء ولدوا لداود في حبرون '),
(6804, '2 Samuel', 10, 3, 6, ' وكان في وقوع الحرب بين بيت شاول وبيت داود ، أن أبنير تشدد لأجل بيت شاول '),
(6805, '2 Samuel', 10, 3, 7, ' وكانت لشاول سرية اسمها رصفة بنت أية . فقال إيشبوشث لأبنير : لماذا دخلت إلى سرية أبي '),
(6806, '2 Samuel', 10, 3, 8, ' فاغتاظ أبنير جدا من كلام إيشبوشث وقال : ألعلي رأس كلب ليهوذا ؟ اليوم أصنع معروفا مع بيت شاول أبيك ، مع إخوته ومع أصحابه ، ولم أسلمك ليد داود ، وتطالبني اليوم بإثم المرأة '),
(6807, '2 Samuel', 10, 3, 9, ' هكذا يصنع الله بأبنير وهكذا يزيده ، إنه كما حلف الرب لداود كذلك أصنع له '),
(6808, '2 Samuel', 10, 3, 10, ' لنقل المملكة من بيت شاول ، وإقامة كرسي داود على إسرائيل وعلى يهوذا من دان إلى بئر سبع '),
(6809, '2 Samuel', 10, 3, 11, ' ولم يقدر بعد أن يجاوب أبنير بكلمة لأجل خوفه منه '),
(6810, '2 Samuel', 10, 3, 12, ' فأرسل أبنير من فوره رسلا إلى داود قائلا : لمن هي الأرض ؟ يقولون : اقطع عهدك معي ، وهوذا يدي معك لرد جميع إسرائيل إليك '),
(6811, '2 Samuel', 10, 3, 13, ' فقال : حسنا . أنا أقطع معك عهدا ، إلا إني أطلب منك أمرا واحدا ، وهو أن لا ترى وجهي ما لم تأت أولا بميكال بنت شاول حين تأتي لترى وجهي '),
(6812, '2 Samuel', 10, 3, 14, ' وأرسل داود رسلا إلى إيشبوشث بن شاول يقول : أعطني امرأتي ميكال التي خطبتها لنفسي بمئة غلفة من الفلسطينيين '),
(6813, '2 Samuel', 10, 3, 15, ' فأرسل إيشبوشث وأخذها من عند رجلها ، من فلطيئيل بن لايش '),
(6814, '2 Samuel', 10, 3, 16, ' وكان رجلها يسير معها ويبكي وراءها إلى بحوريم . فقال له أبنير : اذهب . ارجع . فرجع '),
(6815, '2 Samuel', 10, 3, 17, ' وكان كلام أبنير إلى شيوخ إسرائيل قائلا : قد كنتم منذ أمس وما قبله تطلبون داود ليكون ملكا عليكم '),
(6816, '2 Samuel', 10, 3, 18, ' فالآن افعلوا ، لأن الرب كلم داود قائلا : إني بيد داود عبدي أخلص شعبي إسرائيل من يد الفلسطينيين ومن أيدي جميع أعدائهم '),
(6817, '2 Samuel', 10, 3, 19, ' وتكلم أبنير أيضا في مسامع بنيامين ، وذهب أبنير ليتكلم في سماع داود أيضا في حبرون ، بكل ما حسن في أعين إسرائيل وفي أعين جميع بيت بنيامين '),
(6818, '2 Samuel', 10, 3, 20, ' فجاء أبنير إلى داود إلى حبرون ومعه عشرون رجلا . فصنع داود لأبنير وللرجال الذين معه وليمة '),
(6819, '2 Samuel', 10, 3, 21, ' وقال أبنير لداود : أقوم وأذهب وأجمع إلى سيدي الملك جميع إسرائيل ، فيقطعون معك عهدا ، وتملك حسب كل ما تشتهي نفسك . فأرسل داود أبنير فذهب بسلام '),
(6820, '2 Samuel', 10, 3, 22, ' وإذا بعبيد داود ويوآب قد جاءوا من الغزو وأتوا بغنيمة كثيرة معهم ، ولم يكن أبنير مع داود في حبرون ، لأنه كان قد أرسله فذهب بسلام '),
(6821, '2 Samuel', 10, 3, 23, ' وجاء يوآب وكل الجيش الذي معه . فأخبروا يوآب قائلين : قد جاء أبنير بن نير إلى الملك فأرسله ، فذهب بسلام '),
(6822, '2 Samuel', 10, 3, 24, ' فدخل يوآب إلى الملك وقال : ماذا فعلت ؟ هوذا قد جاء أبنير إليك . لماذا أرسلته فذهب '),
(6823, '2 Samuel', 10, 3, 25, ' أنت تعلم أبنير بن نير أنه إنما جاء ليملقك ، وليعلم خروجك ودخولك وليعلم كل ما تصنع '),
(6824, '2 Samuel', 10, 3, 26, ' ثم خرج يوآب من عند داود وأرسل رسلا وراء أبنير ، فردوه من بئر السيرة وداود لا يعلم '),
(6825, '2 Samuel', 10, 3, 27, ' ولما رجع أبنير إلى حبرون ، مال به يوآب إلى وسط الباب ليكلمه سرا ، وضربه هناك في بطنه فمات بدم عسائيل أخيه '),
(6826, '2 Samuel', 10, 3, 28, ' فسمع داود بعد ذلك فقال : إني بريء أنا ومملكتي لدى الرب إلى الأبد من دم أبنير بن نير '),
(6827, '2 Samuel', 10, 3, 29, ' فليحل على رأس يوآب وعلى كل بيت أبيه ، ولا ينقطع من بيت يوآب ذو سيل وأبرص وعاكز على العكازة وساقط بالسيف ومحتاج الخبز '),
(6828, '2 Samuel', 10, 3, 30, ' فقتل يوآب وأبيشاي أخوه أبنير ، لأنه قتل عسائيل أخاهما في جبعون في الحرب '),
(6829, '2 Samuel', 10, 3, 31, ' فقال داود ليوآب ولجميع الشعب الذي معه : مزقوا ثيابكم وتنطقوا بالمسوح والطموا أمام أبنير . وكان داود الملك يمشي وراء النعش '),
(6830, '2 Samuel', 10, 3, 32, ' ودفنوا أبنير في حبرون . ورفع الملك صوته وبكى على قبر أبنير ، وبكى جميع الشعب '),
(6831, '2 Samuel', 10, 3, 33, ' ورثا الملك أبنير وقال : هل كموت أحمق يموت أبنير '),
(6832, '2 Samuel', 10, 3, 34, ' يداك لم تكونا مربوطتين ، ورجلاك لم توضعا في سلاسل نحاس . كالسقوط أمام بني الإثم سقطت . وعاد جميع الشعب يبكون عليه '),
(6833, '2 Samuel', 10, 3, 35, ' وجاء جميع الشعب ليطعموا داود خبزا ، وكان بعد نهار . فحلف داود قائلا : هكذا يفعل لي الله وهكذا يزيد ، إن كنت أذوق خبزا أو شيئا آخر قبل غروب الشمس '),
(6834, '2 Samuel', 10, 3, 36, ' فعرف جميع الشعب وحسن في أعينهم ، كما أن كل ما صنع الملك كان حسنا في أعين جميع الشعب '),
(6835, '2 Samuel', 10, 3, 37, ' وعلم كل الشعب وجميع إسرائيل في ذلك اليوم أنه لم يكن من الملك قتل أبنير بن نير '),
(6836, '2 Samuel', 10, 3, 38, ' وقال الملك لعبيده : ألا تعلمون أن رئيسا وعظيما سقط اليوم في إسرائيل '),
(6837, '2 Samuel', 10, 3, 39, ' وأنا اليوم ضعيف وممسوح ملكا ، وهؤلاء الرجال بنو صروية أقوى مني . يجازي الرب فاعل الشر كشره '),
(6838, '2 Samuel', 10, 4, 1, ' ولما سمع ابن شاول أن أبنير قد مات في حبرون ، ارتخت يداه ، وارتاع جميع إسرائيل '),
(6839, '2 Samuel', 10, 7, 15, ' ولكن رحمتي لا تنزع منه كما نزعتها من شاول الذي أزلته من أمامك '),
(6840, '2 Samuel', 10, 7, 16, ' ويأمن بيتك ومملكتك إلى الأبد أمامك . كرسيك يكون ثابتا إلى الأبد '),
(6841, '2 Samuel', 10, 7, 17, ' فحسب جميع هذا الكلام وحسب كل هذه الرؤيا كذلك كلم ناثان داود '),
(6842, '2 Samuel', 10, 7, 18, ' فدخل الملك داود وجلس أمام الرب وقال : من أنا يا سيدي الرب ؟ وما هو بيتي حتى أوصلتني إلى ههنا '),
(6843, '2 Samuel', 10, 7, 19, ' وقل هذا أيضا في عينيك يا سيدي الرب ، فتكلمت أيضا من جهة بيت عبدك إلى زمان طويل ، وهذه عادة الإنسان يا سيدي الرب '),
(6844, '2 Samuel', 10, 7, 20, ' وبماذا يعود داود يكلمك وأنت قد عرفت عبدك يا سيدي الرب '),
(6845, '2 Samuel', 10, 7, 21, ' فمن أجل كلمتك وحسب قلبك فعلت هذه العظائم كلها لتعرف عبدك '),
(6846, '2 Samuel', 10, 7, 22, ' لذلك قد عظمت أيها الرب الإله ، لأنه ليس مثلك وليس إله غيرك حسب كل ما سمعناه بآذاننا '),
(6847, '2 Samuel', 10, 7, 23, ' وأية أمة على الأرض مثل شعبك إسرائيل الذي سار الله ليفتديه لنفسه شعبا ، ويجعل له اسما ، ويعمل لكم العظائم والتخاويف لأرضك أمام شعبك الذي افتديته لنفسك من مصر ، من الشعوب وآلهتهم '),
(6848, '2 Samuel', 10, 7, 24, ' وثبت لنفسك شعبك إسرائيل ، شعبا لنفسك إلى الأبد ، وأنت يارب صرت لهم إلها '),
(6849, '2 Samuel', 10, 7, 25, ' والآن أيها الرب الإله أقم إلى الأبد الكلام الذي تكلمت به عن عبدك وعن بيته ، وافعل كما نطقت '),
(6850, '2 Samuel', 10, 7, 26, ' وليتعظم اسمك إلى الأبد ، فيقال : رب الجنود إله على إسرائيل . وليكن بيت عبدك داود ثابتا أمامك '),
(6851, '2 Samuel', 10, 7, 27, ' لأنك أنت يارب الجنود إله إسرائيل قد أعلنت لعبدك قائلا : إني أبني لك بيتا ، لذلك وجد عبدك في قلبه أن يصلي لك هذه الصلاة '),
(6852, '2 Samuel', 10, 7, 28, ' والآن يا سيدي الرب أنت هو الله وكلامك هو حق ، وقد كلمت عبدك بهذا الخير '),
(6853, '2 Samuel', 10, 7, 29, ' فالآن ارتض وبارك بيت عبدك ليكون إلى الأبد أمامك ، لأنك أنت يا سيدي الرب قد تكلمت . فليبارك بيت عبدك ببركتك إلى الأبد '),
(6854, '2 Samuel', 10, 8, 1, ' وبعد ذلك ضرب داود الفلسطينيين وذللهم ، وأخذ داود زمام القصبة من يد الفلسطينيين '),
(6855, '2 Samuel', 10, 8, 2, ' وضرب الموآبيين وقاسهم بالحبل . أضجعهم على الأرض ، فقاس بحبلين للقتل وبحبل للاستحياء . وصار الموآبيون عبيدا لداود يقدمون هدايا '),
(6856, '2 Samuel', 10, 8, 3, ' وضرب داود هدد عزر بن رحوب ملك صوبة حين ذهب ليرد سلطته عند نهر الفرات '),
(6857, '2 Samuel', 10, 8, 4, ' فأخذ داود منه ألفا وسبع مئة فارس وعشرين ألف راجل . وعرقب داود جميع خيل المركبات وأبقى منها مئة مركبة '),
(6858, '2 Samuel', 10, 8, 5, ' فجاء أرام دمشق لنجدة هدد عزر ملك صوبة ، فضرب داود من أرام اثنين وعشرين ألف رجل '),
(6859, '2 Samuel', 10, 8, 6, ' وجعل داود محافظين في أرام دمشق ، وصار الأراميون لداود عبيدا يقدمون هدايا . وكان الرب يخلص داود حيثما توجه '),
(6860, '2 Samuel', 10, 8, 7, ' وأخذ داود أتراس الذهب التي كانت على عبيد هدد عزر وأتى بها إلى أورشليم '),
(6861, '2 Samuel', 10, 8, 8, ' ومن باطح ومن بيروثاي ، مدينتي هدد عزر ، أخذ الملك داود نحاسا كثيرا جدا '),
(6862, '2 Samuel', 10, 8, 9, ' وسمع توعي ملك حماة أن داود قد ضرب كل جيش هدد عزر '),
(6863, '2 Samuel', 10, 8, 10, ' فأرسل توعي يورام ابنه إلى الملك داود ليسأل عن سلامته ويباركه لأنه حارب هدد عزر وضربه ، لأن هدد عزر كانت له حروب مع توعي . وكان بيده آنية فضة وآنية ذهب وآنية نحاس '),
(6864, '2 Samuel', 10, 8, 11, ' وهذه أيضا قدسها الملك داود للرب مع الفضة والذهب الذي قدسه من جميع الشعوب الذين أخضعهم '),
(6865, '2 Samuel', 10, 8, 12, ' من أرام ، ومن موآب ، ومن بني عمون ، ومن الفلسطينيين ، ومن عماليق ، ومن غنيمة هدد عزر بن رحوب ملك صوبة '),
(6866, '2 Samuel', 10, 8, 13, ' ونصب داود تذكارا عند رجوعه من ضربه ثمانية عشر ألفا من أرام في وادي الملح '),
(6867, '2 Samuel', 10, 8, 14, ' وجعل في أدوم محافظين . وضع محافظين في أدوم كلها . وكان جميع الأدوميين عبيدا لداود . وكان الرب يخلص داود حيثما توجه '),
(6868, '2 Samuel', 10, 8, 15, ' وملك داود على جميع إسرائيل . وكان داود يجري قضاء وعدلا لكل شعبه '),
(6869, '2 Samuel', 10, 8, 16, ' وكان يوآب ابن صروية على الجيش ، ويهوشافاط بن أخيلود مسجلا '),
(6870, '2 Samuel', 10, 8, 17, ' وصادوق بن أخيطوب وأخيمالك بن أبياثار كاهنين ، وسرايا كاتبا '),
(6871, '2 Samuel', 10, 8, 18, ' وبناياهو بن يهوياداع على الجلادين والسعاة ، وبنو داود كانوا كهنة '),
(6872, '2 Samuel', 10, 9, 1, ' وقال داود : هل يوجد بعد أحد قد بقي من بيت شاول ، فأصنع معه معروفا من أجل يوناثان '),
(6873, '2 Samuel', 10, 9, 2, ' وكان لبيت شاول عبد اسمه صيبا ، فاستدعوه إلى داود ، وقال له الملك : أأنت صيبا ؟  . فقال : عبدك '),
(6874, '2 Samuel', 10, 9, 3, ' فقال الملك : ألا يوجد بعد أحد لبيت شاول فأصنع معه إحسان الله ؟  . فقال صيبا للملك : بعد ابن ليوناثان أعرج الرجلين '),
(6875, '2 Samuel', 10, 9, 4, ' فقال له الملك : أين هو ؟  . فقال صيبا للملك : هوذا هو في بيت ماكير بن عميئيل في لودبار '),
(6876, '2 Samuel', 10, 9, 5, ' فأرسل الملك داود وأخذه من بيت ماكير بن عميئيل من لودبار '),
(6877, '2 Samuel', 10, 9, 6, ' فجاء مفيبوشث بن يوناثان بن شاول إلى داود وخر على وجهه وسجد ، فقال داود : يا مفيبوشث . فقال : هأنذا عبدك '),
(6878, '2 Samuel', 10, 9, 7, ' فقال له داود : لا تخف . فإني لأعملن معك معروفا من أجل يوناثان أبيك ، وأرد لك كل حقول شاول أبيك ، وأنت تأكل خبزا على مائدتي دائما '),
(6879, '2 Samuel', 10, 9, 8, ' فسجد وقال : من هو عبدك حتى تلتفت إلى كلب ميت مثلي '),
(6880, '2 Samuel', 10, 9, 9, ' ودعا الملك صيبا غلام شاول وقال له : كل ما كان لشاول ولكل بيته قد دفعته لابن سيدك '),
(6881, '2 Samuel', 10, 9, 10, ' فتشتغل له في الأرض أنت وبنوك وعبيدك ، وتستغل ليكون لابن سيدك خبز ليأكل . ومفيبوشث ابن سيدك يأكل دائما خبزا على مائدتي . وكان لصيبا خمسة عشر ابنا وعشرون عبدا '),
(6882, '2 Samuel', 10, 9, 11, ' فقال صيبا للملك : حسب كل ما يأمر به سيدي الملك عبده كذلك يصنع عبدك . فيأكل مفيبوشث على مائدتي كواحد من بني الملك '),
(6883, '2 Samuel', 10, 9, 12, ' وكان لمفيبوشث ابن صغير اسمه ميخا . وكان جميع ساكني بيت صيبا عبيدا لمفيبوشث '),
(6884, '2 Samuel', 10, 9, 13, ' فسكن مفيبوشث في أورشليم ، لأنه كان يأكل دائما على مائدة الملك . وكان أعرج من رجليه كلتيهما '),
(6885, '2 Samuel', 10, 10, 1, ' وكان بعد ذلك أن ملك بني عمون مات ، وملك حانون ابنه عوضا عنه '),
(6886, '2 Samuel', 10, 10, 2, ' فقال داود : أصنع معروفا مع حانون بن ناحاش كما صنع أبوه معي معروفا . فأرسل داود بيد عبيده يعزيه عن أبيه . فجاء عبيد داود إلى أرض بني عمون '),
(6887, '2 Samuel', 10, 10, 3, ' فقال رؤساء بني عمون لحانون سيدهم : هل يكرم داود أباك في عينيك حتى أرسل إليك معزين ؟ أليس لأجل فحص المدينة وتجسسها وقلبها ، أرسل داود عبيده إليك '),
(6888, '2 Samuel', 10, 10, 4, ' فأخذ حانون عبيد داود وحلق أنصاف لحاهم ، وقص ثيابهم من الوسط إلى أستاههم ، ثم أطلقهم '),
(6889, '2 Samuel', 10, 10, 5, ' ولما أخبروا داود أرسل للقائهم ، لأن الرجال كانوا خجلين جدا . وقال الملك : أقيموا في أريحا حتى تنبت لحاكم ثم ارجعوا '),
(6890, '2 Samuel', 10, 10, 6, ' ولما رأى بنو عمون أنهم قد أنتنوا عند داود ، أرسل بنو عمون واستأجروا أرام بيت رحوب وأرام صوبا ، عشرين ألف راجل ، ومن ملك معكة ألف رجل ، ورجال طوب اثني عشر ألف رجل '),
(6891, '2 Samuel', 10, 10, 7, ' فلما سمع داود أرسل يوآب وكل جيش الجبابرة '),
(6892, '2 Samuel', 10, 10, 8, ' وخرج بنو عمون واصطفوا للحرب عند مدخل الباب ، وكان أرام صوبا ورحوب ورجال طوب ومعكة وحدهم في الحقل '),
(6893, '2 Samuel', 10, 10, 9, ' فلما رأى يوآب أن مقدمة الحرب كانت نحوه من قدام ومن وراء ، اختار من جميع منتخبي إسرائيل وصفهم للقاء أرام '),
(6894, '2 Samuel', 10, 10, 10, ' وسلم بقية الشعب ليد أخيه أبيشاي ، فصفهم للقاء بني عمون '),
(6895, '2 Samuel', 10, 10, 11, ' وقال : إن قوي أرام علي تكون لي منجدا ، وإن قوي عليك بنو عمون أذهب لنجدتك '),
(6896, '2 Samuel', 10, 10, 12, ' تجلد ولنتشدد من أجل شعبنا ومن أجل مدن إلهنا ، والرب يفعل ما يحسن في عينيه '),
(6897, '2 Samuel', 10, 10, 13, ' فتقدم يوآب والشعب الذين معه لمحاربة أرام فهربوا من أمامه '),
(6898, '2 Samuel', 10, 10, 14, ' ولما رأى بنو عمون أنه قد هرب أرام ، هربوا من أمام أبيشاي ودخلوا المدينة . فرجع يوآب عن بني عمون وأتى إلى أورشليم '),
(6899, '2 Samuel', 10, 10, 15, ' ولما رأى أرام أنهم قد انكسروا أمام إسرائيل ، اجتمعوا معا '),
(6900, '2 Samuel', 10, 10, 16, ' وأرسل هدر عزر فأبرز أرام الذي في عبر النهر ، فأتوا إلى حيلام وأمامهم شوبك رئيس جيش هدر عزر '),
(6901, '2 Samuel', 10, 10, 17, ' ولما أخبر داود ، جمع كل إسرائيل وعبر الأردن وجاء إلى حيلام ، فاصطف أرام للقاء داود وحاربوه '),
(6902, '2 Samuel', 10, 10, 18, ' وهرب أرام من أمام إسرائيل ، وقتل داود من أرام سبع مئة مركبة وأربعين ألف فارس ، وضرب شوبك رئيس جيشه فمات هناك '),
(6903, '2 Samuel', 10, 10, 19, ' ولما رأى جميع الملوك ، عبيد هدر عزر أنهم انكسروا أمام إسرائيل ، صالحوا إسرائيل واستعبدوا لهم ، وخاف أرام أن ينجدوا بني عمون بعد '),
(6904, '2 Samuel', 10, 11, 1, ' وكان عند تمام السنة ، في وقت خروج الملوك ، أن داود أرسل يوآب وعبيده معه وجميع إسرائيل ، فأخربوا بني عمون وحاصروا ربة . وأما داود فأقام في أورشليم '),
(6905, '2 Samuel', 10, 11, 2, ' وكان في وقت المساء أن داود قام عن سريره وتمشى على سطح بيت الملك ، فرأى من على السطح امرأة تستحم . وكانت المرأة جميلة المنظر جدا '),
(6906, '2 Samuel', 10, 11, 3, ' فأرسل داود وسأل عن المرأة ، فقال واحد : أليست هذه بثشبع بنت أليعام امرأة أوريا الحثي '),
(6907, '2 Samuel', 10, 11, 4, ' فأرسل داود رسلا وأخذها ، فدخلت إليه ، فاضطجع معها وهي مطهرة من طمثها . ثم رجعت إلى بيتها '),
(6908, '2 Samuel', 10, 11, 5, ' وحبلت المرأة ، فأرسلت وأخبرت داود وقالت : إني حبلى '),
(6909, '2 Samuel', 10, 11, 6, ' فأرسل داود إلى يوآب يقول : أرسل إلي أوريا الحثي . فأرسل يوآب أوريا إلى داود '),
(6910, '2 Samuel', 10, 11, 7, ' فأتى أوريا إليه ، فسأل داود عن سلامة يوآب وسلامة الشعب ونجاح الحرب '),
(6911, '2 Samuel', 10, 11, 8, ' وقال داود لأوريا : انزل إلى بيتك واغسل رجليك . فخرج أوريا من بيت الملك ، وخرجت وراءه حصة من عند الملك '),
(6912, '2 Samuel', 10, 11, 9, ' ونام أوريا على باب بيت الملك مع جميع عبيد سيده ، ولم ينزل إلى بيته '),
(6913, '2 Samuel', 10, 11, 10, ' فأخبروا داود قائلين : لم ينزل أوريا إلى بيته . فقال داود لأوريا : أما جئت من السفر ؟ فلماذا لم تنزل إلى بيتك '),
(6914, '2 Samuel', 10, 11, 11, ' فقال أوريا لداود : إن التابوت وإسرائيل ويهوذا ساكنون في الخيام ، وسيدي يوآب وعبيد سيدي نازلون على وجه الصحراء ، وأنا آتي إلى بيتي لآكل وأشرب وأضطجع مع امرأتي ؟ وحياتك وحياة نفسك ، لا أفعل هذا الأمر '),
(6915, '2 Samuel', 10, 11, 12, ' فقال داود لأوريا : أقم هنا اليوم أيضا ، وغدا أطلقك . فأقام أوريا في أورشليم ذلك اليوم وغده '),
(6916, '2 Samuel', 10, 11, 13, ' ودعاه داود فأكل أمامه وشرب وأسكره . وخرج عند المساء ليضطجع في مضجعه مع عبيد سيده ، وإلى بيته لم ينزل '),
(6917, '2 Samuel', 10, 11, 14, ' وفي الصباح كتب داود مكتوبا إلى يوآب وأرسله بيد أوريا '),
(6918, '2 Samuel', 10, 11, 15, ' وكتب في المكتوب يقول : اجعلوا أوريا في وجه الحرب الشديدة ، وارجعوا من ورائه فيضرب ويموت '),
(6919, '2 Samuel', 10, 11, 16, ' وكان في محاصرة يوآب المدينة أنه جعل أوريا في الموضع الذي علم أن رجال البأس فيه '),
(6920, '2 Samuel', 10, 11, 17, ' فخرج رجال المدينة وحاربوا يوآب ، فسقط بعض الشعب من عبيد داود ، ومات أوريا الحثي أيضا '),
(6921, '2 Samuel', 10, 11, 18, ' فأرسل يوآب وأخبر داود بجميع أمور الحرب '),
(6922, '2 Samuel', 10, 11, 19, ' وأوصى الرسول قائلا : عندما تفرغ من الكلام مع الملك عن جميع أمور الحرب '),
(6923, '2 Samuel', 10, 11, 20, ' فإن اشتعل غضب الملك ، وقال لك : لماذا دنوتم من المدينة للقتال ؟ أما علمتم أنهم يرمون من على السور '),
(6924, '2 Samuel', 10, 11, 21, ' من قتل أبيمالك بن يربوشث ؟ ألم ترمه امرأة بقطعة رحى من على السور فمات في تاباص ؟ لماذا دنوتم من السور ؟ فقل : قد مات عبدك أوريا الحثي أيضا '),
(6925, '2 Samuel', 10, 11, 22, ' فذهب الرسول ودخل وأخبر داود بكل ما أرسله فيه يوآب '),
(6926, '2 Samuel', 10, 11, 23, ' وقال الرسول لداود : قد تجبر علينا القوم وخرجوا إلينا إلى الحقل فكنا عليهم إلى مدخل الباب '),
(6927, '2 Samuel', 10, 11, 24, ' فرمى الرماة عبيدك من على السور ، فمات البعض من عبيد الملك ، ومات عبدك أوريا الحثي أيضا '),
(6928, '2 Samuel', 10, 11, 25, ' فقال داود للرسول : هكذا تقول ليوآب : لا يسؤ في عينيك هذا الأمر ، لأن السيف يأكل هذا وذاك . شدد قتالك على المدينة وأخربها . وشدده '),
(6929, '2 Samuel', 10, 11, 26, ' فلما سمعت امرأة أوريا أنه قد مات أوريا رجلها ، ندبت بعلها '),
(6930, '2 Samuel', 10, 11, 27, ' ولما مضت المناحة أرسل داود وضمها إلى بيته ، وصارت له امرأة وولدت له ابنا . وأما الأمر الذي فعله داود فقبح في عيني الرب '),
(6931, '2 Samuel', 10, 12, 1, ' فأرسل الرب ناثان إلى داود . فجاء إليه وقال له : كان رجلان في مدينة واحدة ، واحد منهما غني والآخر فقير '),
(6932, '2 Samuel', 10, 12, 2, ' وكان للغني غنم وبقر كثيرة جدا '),
(6933, '2 Samuel', 10, 12, 3, ' وأما الفقير فلم يكن له شيء إلا نعجة واحدة صغيرة قد اقتناها ورباها وكبرت معه ومع بنيه جميعا . تأكل من لقمته وتشرب من كأسه وتنام في حضنه ، وكانت له كابنة '),
(6934, '2 Samuel', 10, 12, 4, ' فجاء ضيف إلى الرجل الغني ، فعفا أن يأخذ من غنمه ومن بقره ليهيئ للضيف الذي جاء إليه ، فأخذ نعجة الرجل الفقير وهيأ للرجل الذي جاء إليه '),
(6935, '2 Samuel', 10, 12, 5, ' فحمي غضب داود على الرجل جدا ، وقال لناثان : حي هو الرب ، إنه يقتل الرجل الفاعل ذلك '),
(6936, '2 Samuel', 10, 12, 6, ' ويرد النعجة أربعة أضعاف لأنه فعل هذا الأمر ولأنه لم يشفق '),
(6937, '2 Samuel', 10, 12, 7, ' فقال ناثان لداود : أنت هو الرجل هكذا قال الرب إله إسرائيل : أنا مسحتك ملكا على إسرائيل وأنقذتك من يد شاول '),
(6938, '2 Samuel', 10, 12, 8, ' وأعطيتك بيت سيدك ونساء سيدك في حضنك ، وأعطيتك بيت إسرائيل ويهوذا . وإن كان ذلك قليلا ، كنت أزيد لك كذا وكذا '),
(6939, '2 Samuel', 10, 12, 9, ' لماذا احتقرت كلام الرب لتعمل الشر في عينيه ؟ قد قتلت أوريا الحثي بالسيف ، وأخذت امرأته لك امرأة ، وإياه قتلت بسيف بني عمون '),
(6940, '2 Samuel', 10, 12, 10, ' والآن لا يفارق السيف بيتك إلى الأبد ، لأنك احتقرتني وأخذت امرأة أوريا الحثي لتكون لك امرأة '),
(6941, '2 Samuel', 10, 12, 11, ' هكذا قال الرب : هأنذا أقيم عليك الشر من بيتك ، وآخذ نساءك أمام عينيك وأعطيهن لقريبك ، فيضطجع مع نسائك في عين هذه الشمس '),
(6942, '2 Samuel', 10, 12, 12, ' لأنك أنت فعلت بالسر وأنا أفعل هذا الأمر قدام جميع إسرائيل وقدام الشمس '),
(6943, '2 Samuel', 10, 12, 13, ' فقال داود لناثان : قد أخطأت إلى الرب . فقال ناثان لداود : الرب أيضا قد نقل عنك خطيتك . لا تموت '),
(6944, '2 Samuel', 10, 12, 14, ' غير أنه من أجل أنك قد جعلت بهذا الأمر أعداء الرب يشمتون ، فالابن المولود لك يموت '),
(6945, '2 Samuel', 10, 12, 15, ' وذهب ناثان إلى بيته . وضرب الرب الولد الذي ولدته امرأة أوريا لداود فثقل '),
(6946, '2 Samuel', 10, 12, 16, ' فسأل داود الله من أجل الصبي ، وصام داود صوما ، ودخل وبات مضطجعا على الأرض '),
(6947, '2 Samuel', 10, 12, 17, ' فقام شيوخ بيته عليه ليقيموه عن الأرض فلم يشأ ، ولم يأكل معهم خبزا '),
(6948, '2 Samuel', 10, 12, 18, ' وكان في اليوم السابع أن الولد مات ، فخاف عبيد داود أن يخبروه بأن الولد قد مات لأنهم قالوا : هوذا لما كان الولد حيا كلمناه فلم يسمع لصوتنا . فكيف نقول له : قد مات الولد ؟ يعمل أشر '),
(6949, '2 Samuel', 10, 12, 19, ' ورأى داود عبيده يتناجون ، ففطن داود أن الولد قد مات . فقال داود لعبيده : هل مات الولد ؟  . فقالوا : مات '),
(6950, '2 Samuel', 10, 12, 20, ' فقام داود عن الأرض واغتسل وادهن وبدل ثيابه ودخل بيت الرب وسجد ، ثم جاء إلى بيته وطلب فوضعوا له خبزا فأكل '),
(6951, '2 Samuel', 10, 12, 21, ' فقال له عبيده : ما هذا الأمر الذي فعلت ؟ لما كان الولد حيا صمت وبكيت ، ولما مات الولد قمت وأكلت خبزا '),
(6952, '2 Samuel', 10, 12, 22, ' فقال : لما كان الولد حيا صمت وبكيت لأني قلت : من يعلم ؟ ربما يرحمني الرب ويحيا الولد ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(6953, '2 Samuel', 10, 12, 23, ' والآن قد مات ، فلماذا أصوم ؟ هل أقدر أن أرده بعد ؟ أنا ذاهب إليه وأما هو فلا يرجع إلي '),
(6954, '2 Samuel', 10, 12, 24, ' وعزى داود بثشبع امرأته ، ودخل إليها واضطجع معها فولدت ابنا ، فدعا اسمه سليمان ، والرب أحبه '),
(6955, '2 Samuel', 10, 12, 25, ' وأرسل بيد ناثان النبي ودعا اسمه يديديا من أجل الرب '),
(6956, '2 Samuel', 10, 12, 26, ' وحارب يوآب ربة بني عمون وأخذ مدينة المملكة '),
(6957, '2 Samuel', 10, 12, 27, ' وأرسل يوآب رسلا إلى داود يقول : قد حاربت ربة وأخذت أيضا مدينة المياه '),
(6958, '2 Samuel', 10, 12, 28, ' فالآن اجمع بقية الشعب وانزل على المدينة وخذها لئلا آخذ أنا المدينة فيدعى باسمي عليها '),
(6959, '2 Samuel', 10, 12, 29, ' فجمع داود كل الشعب وذهب إلى ربة وحاربها وأخذها '),
(6960, '2 Samuel', 10, 12, 30, ' وأخذ تاج ملكهم عن رأسه ، ووزنه وزنة من الذهب مع حجر كريم ، وكان على رأس داود . وأخرج غنيمة المدينة كثيرة جدا '),
(6961, '2 Samuel', 10, 12, 31, ' وأخرج الشعب الذي فيها ووضعهم تحت مناشير ونوارج حديد وفؤوس حديد وأمرهم في أتون الآجر ، وهكذا صنع بجميع مدن بني عمون . ثم رجع داود وجميع الشعب إلى أورشليم '),
(6962, '2 Samuel', 10, 13, 1, ' وجرى بعد ذلك أنه كان لأبشالوم بن داود أخت جميلة اسمها ثامار ، فأحبها أمنون بن داود '),
(6963, '2 Samuel', 10, 13, 2, ' وأحصر أمنون للسقم من أجل ثامار أخته لأنها كانت عذراء ، وعسر في عيني أمنون أن يفعل لها شيئا '),
(6964, '2 Samuel', 10, 13, 3, ' وكان لأمنون صاحب اسمه يوناداب بن شمعى أخي داود . وكان يوناداب رجلا حكيما جدا '),
(6965, '2 Samuel', 10, 13, 4, ' فقال له : لماذا يا ابن الملك أنت ضعيف هكذا من صباح إلى صباح ؟ أما تخبرني ؟  . فقال له أمنون : إني أحب ثامار أخت أبشالوم أخي '),
(6966, '2 Samuel', 10, 13, 5, ' فقال يوناداب : اضطجع على سريرك وتمارض . وإذا جاء أبوك ليراك فقل له : دع ثامار أختي فتأتي وتطعمني خبزا ، وتعمل أمامي الطعام لأرى فآكل من يدها '),
(6967, '2 Samuel', 10, 13, 6, ' فاضطجع أمنون وتمارض ، فجاء الملك ليراه . فقال أمنون للملك : دع ثامار أختي فتأتي وتصنع أمامي كعكتين فآكل من يدها '),
(6968, '2 Samuel', 10, 13, 7, ' فأرسل داود إلى ثامار إلى البيت قائلا : اذهبي إلى بيت أمنون أخيك واعملي له طعاما '),
(6969, '2 Samuel', 10, 13, 8, ' فذهبت ثامار إلى بيت أمنون أخيها وهو مضطجع . وأخذت العجين وعجنت وعملت كعكا أمامه وخبزت الكعك '),
(6970, '2 Samuel', 10, 13, 9, ' وأخذت المقلاة وسكبت أمامه ، فأبى أن يأكل . وقال أمنون : أخرجوا كل إنسان عني . فخرج كل إنسان عنه '),
(6971, '2 Samuel', 10, 13, 10, ' ثم قال أمنون لثامار : ايتي بالطعام إلى المخدع فآكل من يدك . فأخذت ثامار الكعك الذي عملته وأتت به أمنون أخاها إلى المخدع '),
(6972, '2 Samuel', 10, 13, 11, ' وقدمت له ليأكل ، فأمسكها وقال لها : تعالي اضطجعي معي يا أختي '),
(6973, '2 Samuel', 10, 13, 12, ' فقالت له : لا يا أخي ، لا تذلني لأنه لا يفعل هكذا في إسرائيل . لا تعمل هذه القباحة '),
(6974, '2 Samuel', 10, 13, 13, ' أما أنا فأين أذهب بعاري ؟ وأما أنت فتكون كواحد من السفهاء في إسرائيل والآن كلم الملك لأنه لا يمنعني منك '),
(6975, '2 Samuel', 10, 13, 14, ' فلم يشأ أن يسمع لصوتها ، بل تمكن منها وقهرها واضطجع معها '),
(6976, '2 Samuel', 10, 13, 15, ' ثم أبغضها أمنون بغضة شديدة جدا ، حتى إن البغضة التي أبغضها إياها كانت أشد من المحبة التي أحبها إياها . وقال لها أمنون : قومي انطلقي '),
(6977, '2 Samuel', 10, 13, 16, ' فقالت له : لا سبب هذا الشر بطردك إياي هو أعظم من الآخر الذي عملته بي . فلم يشأ أن يسمع لها '),
(6978, '2 Samuel', 10, 13, 17, ' بل دعا غلامه الذي كان يخدمه وقال : اطرد هذه عني خارجا وأقفل الباب وراءها '),
(6979, '2 Samuel', 10, 13, 18, ' وكان عليها ثوب ملون ، لأن بنات الملك العذارى كن يلبسن جبات مثل هذه . فأخرجها خادمه إلى الخارج وأقفل الباب وراءها '),
(6980, '2 Samuel', 10, 13, 19, ' فجعلت ثامار رمادا على رأسها ، ومزقت الثوب الملون الذي عليها ، ووضعت يدها على رأسها وكانت تذهب صارخة '),
(6981, '2 Samuel', 10, 13, 20, ' فقال لها أبشالوم أخوها : هل كان أمنون أخوك معك ؟ فالآن يا أختي اسكتي . أخوك هو . لا تضعي قلبك على هذا الأمر . فأقامت ثامار مستوحشة في بيت أبشالوم أخيها '),
(6982, '2 Samuel', 10, 13, 21, ' ولما سمع الملك داود بجميع هذه الأمور اغتاظ جدا '),
(6983, '2 Samuel', 10, 13, 22, ' ولم يكلم أبشالوم أمنون بشر ولا بخير ، لأن أبشالوم أبغض أمنون من أجل أنه أذل ثامار أخته '),
(6984, '2 Samuel', 10, 13, 23, ' وكان بعد سنتين من الزمان ، أنه كان لأبشالوم جزازون في بعل حاصور التي عند أفرايم . فدعا أبشالوم جميع بني الملك '),
(6985, '2 Samuel', 10, 13, 24, ' وجاء أبشالوم إلى الملك وقال : هوذا لعبدك جزازون . فليذهب الملك وعبيده مع عبدك '),
(6986, '2 Samuel', 10, 13, 25, ' فقال الملك لأبشالوم : لا يا ابني . لا نذهب كلنا لئلا نثقل عليك . فألح عليه ، فلم يشأ أن يذهب بل باركه '),
(6987, '2 Samuel', 10, 13, 26, ' فقال أبشالوم : إذا دع أخي أمنون يذهب معنا . فقال الملك : لماذا يذهب معك '),
(6988, '2 Samuel', 10, 13, 27, ' فألح عليه أبشالوم ، فأرسل معه أمنون وجميع بني الملك '),
(6989, '2 Samuel', 10, 13, 28, ' فأوصى أبشالوم غلمانه قائلا : انظروا . متى طاب قلب أمنون بالخمر وقلت لكم : اضربوا أمنون ، فاقتلوه . لا تخافوا . أليس أني أنا أمرتكم ؟ فتشددوا وكونوا ذوي بأس '),
(6990, '2 Samuel', 10, 13, 29, ' ففعل غلمان أبشالوم بأمنون كما أمر أبشالوم . فقام جميع بني الملك وركبوا كل واحد على بغله وهربوا '),
(6991, '2 Samuel', 10, 13, 30, ' وفيما هم في الطريق وصل الخبر إلى داود وقيل له : قد قتل أبشالوم جميع بني الملك ، ولم يتبق منهم أحد '),
(6992, '2 Samuel', 10, 13, 31, ' فقام الملك ومزق ثيابه واضطجع على الأرض وجميع عبيده واقفون وثيابهم ممزقة '),
(6993, '2 Samuel', 10, 13, 32, ' فأجاب يوناداب بن شمعى أخي داود وقال : لا يظن سيدي أنهم قتلوا جميع الفتيان بني الملك . إنما أمنون وحده مات ، لأن ذلك قد وضع عند أبشالوم منذ يوم أذل ثامار أخته '),
(6994, '2 Samuel', 10, 13, 33, ' والآن لا يضعن سيدي الملك في قلبه شيئا قائلا : إن جميع بني الملك قد ماتوا . إنما أمنون وحده مات '),
(6995, '2 Samuel', 10, 13, 34, ' وهرب أبشالوم . ورفع الغلام الرقيب طرفه ونظر وإذا بشعب كثير يسيرون على الطريق وراءه بجانب الجبل '),
(6996, '2 Samuel', 10, 13, 35, ' فقال يوناداب للملك : هوذا بنو الملك قد جاءوا . كما قال عبدك كذلك صار '),
(6997, '2 Samuel', 10, 13, 36, ' ولما فرغ من الكلام إذا ببني الملك قد جاءوا ورفعوا أصواتهم وبكوا ، وكذلك بكى الملك وعبيده بكاء عظيما جدا '),
(6998, '2 Samuel', 10, 13, 37, ' فهرب أبشالوم وذهب إلى تلماي بن عميهود ملك جشور . وناح داود على ابنه الأيام كلها '),
(6999, '2 Samuel', 10, 13, 38, ' وهرب أبشالوم وذهب إلى جشور ، وكان هناك ثلاث سنين '),
(7000, '2 Samuel', 10, 13, 39, ' وكان داود يتوق إلى الخروج إلى أبشالوم ، لأنه تعزى عن أمنون حيث إنه مات '),
(7001, '2 Samuel', 10, 14, 1, ' وعلم يوآب ابن صروية أن قلب الملك على أبشالوم '),
(7002, '2 Samuel', 10, 14, 2, ' فأرسل يوآب إلى تقوع وأخذ من هناك امرأة حكيمة وقال لها : تظاهري بالحزن ، والبسي ثياب الحزن ، ولا تدهني بزيت ، بل كوني كامرأة لها أيام كثيرة وهي تنوح على ميت '),
(7003, '2 Samuel', 10, 14, 3, ' وادخلي إلى الملك وكلميه بهذا الكلام . وجعل يوآب الكلام في فمها '),
(7004, '2 Samuel', 10, 14, 4, ' وكلمت المرأة التقوعية الملك ، وخرت على وجهها إلى الأرض وسجدت وقالت : أعن أيها الملك '),
(7005, '2 Samuel', 10, 14, 5, ' فقال لها الملك : ما بالك ؟  . فقالت : إني امرأة أرملة . قد مات رجلي '),
(7006, '2 Samuel', 10, 14, 6, ' ولجاريتك ابنان ، فتخاصما في الحقل وليس من يفصل بينهما ، فضرب أحدهما الآخر وقتله '),
(7007, '2 Samuel', 10, 14, 7, ' وهوذا العشيرة كلها قد قامت على جاريتك وقالوا : سلمي ضارب أخيه لنقتله بنفس أخيه الذي قتله ، فنهلك الوارث أيضا . فيطفئون جمرتي التي بقيت ، ولا يتركون لرجلي اسما ولا بقية على وجه الأرض '),
(7008, '2 Samuel', 10, 14, 8, ' فقال الملك للمرأة : اذهبي إلى بيتك وأنا أوصي فيك '),
(7009, '2 Samuel', 10, 14, 9, ' فقالت المرأة التقوعية للملك : علي الإثم يا سيدي الملك وعلى بيت أبي ، والملك وكرسيه نقيان '),
(7010, '2 Samuel', 10, 14, 10, ' فقال الملك : إذا كلمك أحد فأتي به إلي فلا يعود يمسك بعد '),
(7011, '2 Samuel', 10, 14, 11, ' فقالت : اذكر أيها الملك الرب إلهك حتى لا يكثر ولي الدم القتل ، لئلا يهلكوا ابني . فقال : حي هو الرب ، إنه لا تسقط شعرة من شعر ابنك إلى الأرض '),
(7012, '2 Samuel', 10, 14, 12, ' فقالت المرأة : لتتكلم جاريتك كلمة إلى سيدي الملك . فقال : تكلمي '),
(7013, '2 Samuel', 10, 14, 13, ' فقالت المرأة : ولماذا افتكرت بمثل هذا الأمر على شعب الله ؟ ويتكلم الملك بهذا الكلام كمذنب بما أن الملك لا يرد منفيه '),
(7014, '2 Samuel', 10, 14, 14, ' لأنه لابد أن نموت ونكون كالماء المهراق على الأرض الذي لا يجمع أيضا . ولا ينزع الله نفسا بل يفكر أفكارا حتى لا يطرد عنه منفيه '),
(7015, '2 Samuel', 10, 14, 15, ' والآن حيث إني جئت لأكلم الملك سيدي بهذا الأمر ، لأن الشعب أخافني ، فقالت جاريتك : أكلم الملك لعل الملك يفعل كقول أمته '),
(7016, '2 Samuel', 10, 14, 16, ' لأن الملك يسمع لينقذ أمته من يد الرجل الذي يريد أن يهلكني أنا وابني معا من نصيب الله '),
(7017, '2 Samuel', 10, 14, 17, ' فقالت جاريتك : ليكن كلام سيدي الملك عزاء ، لأنه سيدي الملك إنما هو كملاك الله لفهم الخير والشر ، والرب إلهك يكون معك '),
(7018, '2 Samuel', 10, 14, 18, ' فأجاب الملك وقال للمرأة : لا تكتمي عني أمرا أسألك عنه . فقالت المرأة : ليتكلم سيدي الملك '),
(7019, '2 Samuel', 10, 14, 19, ' فقال الملك : هل يد يوآب معك في هذا كله ؟  . فأجابت المرأة وقالت : حية هي نفسك يا سيدي الملك ، لا يحاد يمينا أو يسارا عن كل ما تكلم به سيدي الملك ، لأن عبدك يوآب هو أوصاني ، وهو وضع في فم جاريتك كل هذا الكلام '),
(7020, '2 Samuel', 10, 14, 20, ' لأجل تحويل وجه الكلام فعل عبدك يوآب هذا الأمر ، وسيدي حكيم كحكمة ملاك الله ليعلم كل ما في الأرض '),
(7021, '2 Samuel', 10, 14, 21, ' فقال الملك ليوآب : هأنذا قد فعلت هذا الأمر ، فاذهب رد الفتى أبشالوم '),
(7022, '2 Samuel', 10, 14, 22, ' فسقط يوآب على وجهه إلى الأرض وسجد وبارك الملك ، وقال يوآب : اليوم علم عبدك أني قد وجدت نعمة في عينيك يا سيدي الملك ، إذ فعل الملك قول عبده '),
(7023, '2 Samuel', 10, 14, 23, ' ثم قام يوآب وذهب إلى جشور وأتى بأبشالوم إلى أورشليم '),
(7024, '2 Samuel', 10, 14, 24, ' فقال الملك : لينصرف إلى بيته ولا ير وجهي . فانصرف أبشالوم إلى بيته ولم ير وجه الملك '),
(7025, '2 Samuel', 10, 14, 25, ' ولم يكن في كل إسرائيل رجل جميل وممدوح جدا كأبشالوم ، من باطن قدمه حتى هامته لم يكن فيه عيب '),
(7026, '2 Samuel', 10, 14, 26, ' وعند حلقه رأسه ، إذ كان يحلقه في آخر كل سنة ، لأنه كان يثقل عليه فيحلقه ، كان يزن شعر رأسه مئتي شاقل بوزن الملك '),
(7027, '2 Samuel', 10, 14, 27, ' وولد لأبشالوم ثلاثة بنين وبنت واحدة اسمها ثامار ، وكانت امرأة جميلة المنظر '),
(7028, '2 Samuel', 10, 14, 28, ' وأقام أبشالوم في أورشليم سنتين ولم ير وجه الملك '),
(7029, '2 Samuel', 10, 14, 29, ' فأرسل أبشالوم إلى يوآب ليرسله إلى الملك ، فلم يشأ أن يأتي إليه . ثم أرسل أيضا ثانية ، فلم يشأ أن يأتي '),
(7030, '2 Samuel', 10, 14, 30, ' فقال لعبيده : انظروا . حقلة يوآب بجانبي ، وله هناك شعير . اذهبوا وأحرقوه بالنار . فأحرق عبيد أبشالوم الحقلة بالنار '),
(7031, '2 Samuel', 10, 14, 31, ' فقام يوآب وجاء إلى أبشالوم إلى البيت وقال له : لماذا أحرق عبيدك حقلتي بالنار '),
(7032, '2 Samuel', 10, 14, 32, ' فقال أبشالوم ليوآب : هأنذا قد أرسلت إليك قائلا : تعال إلى هنا فأرسلك إلى الملك تقول : لماذا جئت من جشور ؟ خير لي لو كنت باقيا هناك . فالآن إني أرى وجه الملك ، وإن وجد في إثم فليقتلني '),
(7033, '2 Samuel', 10, 14, 33, ' فجاء يوآب إلى الملك وأخبره . ودعا أبشالوم ، فأتى إلى الملك وسجد على وجهه إلى الأرض قدام الملك ، فقبل الملك أبشالوم '),
(7034, '2 Samuel', 10, 15, 1, ' وكان بعد ذلك أن أبشالوم اتخذ مركبة وخيلا وخمسين رجلا يجرون قدامه '),
(7035, '2 Samuel', 10, 15, 2, ' وكان أبشالوم يبكر ويقف بجانب طريق الباب ، وكل صاحب دعوى آت إلى الملك لأجل الحكم ، كان أبشالوم يدعوه إليه ويقول : من أية مدينة أنت ؟  . فيقول : من أحد أسباط إسرائيل عبدك '),
(7036, '2 Samuel', 10, 15, 3, ' فيقول أبشالوم له : انظر . أمورك صالحة ومستقيمة ، ولكن ليس من يسمع لك من قبل الملك '),
(7037, '2 Samuel', 10, 15, 4, ' ثم يقول أبشالوم : من يجعلني قاضيا في الأرض فيأتي إلي كل إنسان له خصومة ودعوى فأنصفه '),
(7038, '2 Samuel', 10, 15, 5, ' وكان إذا تقدم أحد ليسجد له ، يمد يده ويمسكه ويقبله '),
(7039, '2 Samuel', 10, 15, 6, ' وكان أبشالوم يفعل مثل هذا الأمر لجميع إسرائيل الذين كانوا يأتون لأجل الحكم إلى الملك ، فاسترق أبشالوم قلوب رجال إسرائيل '),
(7040, '2 Samuel', 10, 15, 7, ' وفي نهاية أربعين سنة قال أبشالوم للملك : دعني فأذهب وأوفي نذري الذي نذرته للرب في حبرون '),
(7041, '2 Samuel', 10, 15, 8, ' لأن عبدك نذر نذرا عند سكناي في جشور في أرام قائلا : إن أرجعني الرب إلى أورشليم فإني أعبد الرب '),
(7042, '2 Samuel', 10, 15, 9, ' فقال له الملك : اذهب بسلام . فقام وذهب إلى حبرون '),
(7043, '2 Samuel', 10, 15, 10, ' وأرسل أبشالوم جواسيس في جميع أسباط إسرائيل قائلا : إذا سمعتم صوت البوق ، فقولوا : قد ملك أبشالوم في حبرون '),
(7044, '2 Samuel', 10, 15, 11, ' وانطلق مع أبشالوم مئتا رجل من أورشليم قد دعوا وذهبوا ببساطة ، ولم يكونوا يعلمون شيئا '),
(7045, '2 Samuel', 10, 15, 12, ' وأرسل أبشالوم إلى أخيتوفل الجيلوني مشير داود من مدينته جيلوه إذ كان يذبح ذبائح . وكانت الفتنة شديدة وكان الشعب لا يزال يتزايد مع أبشالوم '),
(7046, '2 Samuel', 10, 15, 13, ' فأتى مخبر إلى داود قائلا : إن قلوب رجال إسرائيل صارت وراء أبشالوم '),
(7047, '2 Samuel', 10, 15, 14, ' فقال داود لجميع عبيده الذين معه في أورشليم : قوموا بنا نهرب ، لأنه ليس لنا نجاة من وجه أبشالوم . أسرعوا للذهاب لئلا يبادر ويدركنا وينزل بنا الشر ويضرب المدينة بحد السيف '),
(7048, '2 Samuel', 10, 15, 15, ' فقال عبيد الملك للملك : حسب كل ما يختاره سيدنا الملك نحن عبيده '),
(7049, '2 Samuel', 10, 15, 16, ' فخرج الملك وجميع بيته وراءه . وترك الملك عشر نساء سراري لحفظ البيت '),
(7050, '2 Samuel', 10, 15, 17, ' وخرج الملك وكل الشعب في أثره ووقفوا عند البيت الأبعد '),
(7051, '2 Samuel', 10, 15, 18, ' وجميع عبيده كانوا يعبرون بين يديه مع جميع الجلادين والسعاة وجميع الجتيين ، ست مئة رجل أتوا وراءه من جت ، وكانوا يعبرون بين يدي الملك '),
(7052, '2 Samuel', 10, 15, 19, ' فقال الملك لإتاي الجتي : لماذا تذهب أنت أيضا معنا ؟ ارجع وأقم مع الملك لأنك غريب ومنفي أيضا من وطنك '),
(7053, '2 Samuel', 10, 15, 20, ' أمسا جئت واليوم أتيهك بالذهاب معنا وأنا أنطلق إلى حيث أنطلق ؟ ارجع ورجع إخوتك . الرحمة والحق معك '),
(7054, '2 Samuel', 10, 15, 21, ' فأجاب إتاي الملك وقال : حي هو الرب وحي ، سيدي الملك ، إنه حيثما كان سيدي الملك ، إن كان للموت أو للحياة ، فهناك يكون عبدك أيضا '),
(7055, '2 Samuel', 10, 15, 22, ' فقال داود لإتاي : اذهب واعبر . فعبر إتاي الجتي وجميع رجاله وجميع الأطفال الذين معه '),
(7056, '2 Samuel', 10, 15, 23, ' وكانت جميع الأرض تبكي بصوت عظيم ، وجميع الشعب يعبرون . وعبر الملك في وادي قدرون ، وعبر جميع الشعب نحو طريق البرية '),
(7057, '2 Samuel', 10, 15, 24, ' وإذا بصادوق أيضا وجميع اللاويين معه يحملون تابوت عهد الله . فوضعوا تابوت الله ، وصعد أبياثار حتى انتهى جميع الشعب من العبور من المدينة '),
(7058, '2 Samuel', 10, 15, 25, ' فقال الملك لصادوق : أرجع تابوت الله إلى المدينة ، فإن وجدت نعمة في عيني الرب فإنه يرجعني ويريني إياه ومسكنه '),
(7059, '2 Samuel', 10, 15, 26, ' وإن قال هكذا : إني لم أسر بك . فهأنذا ، فليفعل بي حسبما يحسن في عينيه '),
(7060, '2 Samuel', 10, 15, 27, ' ثم قال الملك لصادوق الكاهن : أأنت راء ؟ فارجع إلى المدينة بسلام أنت وأخيمعص ابنك ويوناثان بن أبياثار . ابناكما كلاهما معكما '),
(7061, '2 Samuel', 10, 15, 28, ' انظروا . أني أتوانى في سهول البرية حتى تأتي كلمة منكم لتخبيري '),
(7062, '2 Samuel', 10, 15, 29, ' فأرجع صادوق وأبياثار تابوت الله إلى أورشليم وأقاما هناك '),
(7063, '2 Samuel', 10, 15, 30, ' وأما داود فصعد في مصعد جبل الزيتون . كان يصعد باكيا ورأسه مغطى ويمشي حافيا ، وجميع الشعب الذين معه غطوا كل واحد رأسه ، وكانوا يصعدون وهم يبكون '),
(7064, '2 Samuel', 10, 15, 31, ' وأخبر داود وقيل له : إن أخيتوفل بين الفاتنين مع أبشالوم . فقال داود : حمق يارب مشورة أخيتوفل '),
(7065, '2 Samuel', 10, 15, 32, ' ولما وصل داود إلى القمة حيث سجد لله ، إذا بحوشاي الأركي قد لقيه ممزق الثوب والتراب على رأسه '),
(7066, '2 Samuel', 10, 15, 33, ' فقال له داود : إذا عبرت معي تكون علي حملا '),
(7067, '2 Samuel', 10, 15, 34, ' ولكن إذا رجعت إلى المدينة وقلت لأبشالوم : أنا أكون عبدك أيها الملك . أنا عبد أبيك منذ زمان والآن أنا عبدك . فإنك تبطل لي مشورة أخيتوفل '),
(7068, '2 Samuel', 10, 15, 35, ' أليس معك هناك صادوق وأبياثار الكاهنان . فكل ما تسمعه من بيت الملك ، فأخبر به صادوق وأبياثار الكاهنين '),
(7069, '2 Samuel', 10, 15, 36, ' هوذا هناك معهما ابناهما أخيمعص لصادوق ويوناثان لأبياثار . فترسلون على أيديهما إلي كل كلمة تسمعونها '),
(7070, '2 Samuel', 10, 15, 37, ' فأتى حوشاي صاحب داود إلى المدينة ، وأبشالوم يدخل أورشليم '),
(7071, '2 Samuel', 10, 16, 1, ' ولما عبر داود قليلا عن القمة ، إذا بصيبا غلام مفيبوشث قد لقيه بحمارين مشدودين ، عليهما مئتا رغيف خبز ومئة عنقود زبيب ومئة قرص تين وزق خمر '),
(7072, '2 Samuel', 10, 16, 2, ' فقال الملك لصيبا : ما لك وهذه ؟  . فقال صيبا : الحماران لبيت الملك للركوب ، والخبز والتين للغلمان ليأكلوا ، والخمر ليشربه من أعيا في البرية '),
(7073, '2 Samuel', 10, 16, 3, ' فقال الملك : وأين ابن سيدك ؟  . فقال صيبا للملك : هوذا هو مقيم في أورشليم ، لأنه قال : اليوم يرد لي بيت إسرائيل مملكة أبي '),
(7074, '2 Samuel', 10, 16, 4, ' فقال الملك لصيبا : هوذا لك كل ما لمفيبوشث . فقال صيبا : سجدت ليتني أجد نعمة في عينيك يا سيدي الملك '),
(7075, '2 Samuel', 10, 16, 5, ' ولما جاء الملك داود إلى بحوريم إذا برجل خارج من هناك من عشيرة بيت شاول ، اسمه شمعي بن جيرا ، يسب وهو يخرج '),
(7076, '2 Samuel', 10, 16, 6, ' ويرشق بالحجارة داود وجميع عبيد الملك داود وجميع الشعب وجميع الجبابرة عن يمينه وعن يساره '),
(7077, '2 Samuel', 10, 16, 7, ' وهكذا كان شمعي يقول في سبه : اخرج اخرج يا رجل الدماء ورجل بليعال '),
(7078, '2 Samuel', 10, 16, 8, ' قد رد الرب عليك كل دماء بيت شاول الذي ملكت عوضا عنه ، وقد دفع الرب المملكة ليد أبشالوم ابنك ، وها أنت واقع بشرك لأنك رجل دماء '),
(7079, '2 Samuel', 10, 16, 9, ' فقال أبيشاي ابن صروية للملك : لماذا يسب هذا الكلب الميت سيدي الملك ؟ دعني أعبر فأقطع رأسه '),
(7080, '2 Samuel', 10, 16, 10, ' فقال الملك : ما لي ولكم يا بني صروية دعوه يسب لأن الرب قال له : سب داود . ومن يقول : لماذا تفعل هكذا '),
(7081, '2 Samuel', 10, 16, 11, ' وقال داود لأبيشاي ولجميع عبيده : هوذا ابني الذي خرج من أحشائي يطلب نفسي ، فكم بالحري الآن بنياميني ؟ دعوه يسب لأن الرب قال له '),
(7082, '2 Samuel', 10, 16, 12, ' لعل الرب ينظر إلى مذلتي ويكافئني الرب خيرا عوض مسبته بهذا اليوم '),
(7083, '2 Samuel', 10, 16, 13, ' وإذ كان داود ورجاله يسيرون في الطريق ، كان شمعي يسير في جانب الجبل مقابله ويسب وهو سائر ويرشق بالحجارة مقابله ويذري التراب '),
(7084, '2 Samuel', 10, 16, 14, ' وجاء الملك وكل الشعب الذين معه وقد أعيوا فاستراحوا هناك '),
(7085, '2 Samuel', 10, 16, 15, ' وأما أبشالوم وجميع الشعب رجال إسرائيل ، فأتوا إلى أورشليم وأخيتوفل معهم '),
(7086, '2 Samuel', 10, 16, 16, ' ولما جاء حوشاي الأركي صاحب داود إلى أبشالوم ، قال حوشاي لأبشالوم : ليحي الملك ليحي الملك '),
(7087, '2 Samuel', 10, 16, 17, ' فقال أبشالوم لحوشاي : أهذا معروفك مع صاحبك ؟ لماذا لم تذهب مع صاحبك '),
(7088, '2 Samuel', 10, 16, 18, ' فقال حوشاي لأبشالوم : كلا ، ولكن الذي اختاره الرب وهذا الشعب وكل رجال إسرائيل فله أكون ومعه أقيم '),
(7089, '2 Samuel', 10, 16, 19, ' وثانيا : من أخدم ؟ أليس بين يدي ابنه ؟ كما خدمت بين يدي أبيك كذلك أكون بين يديك '),
(7090, '2 Samuel', 10, 16, 20, ' وقال أبشالوم لأخيتوفل : أعطوا مشورة ، ماذا نفعل '),
(7091, '2 Samuel', 10, 16, 21, ' فقال أخيتوفل لأبشالوم : ادخل إلى سراري أبيك اللواتي تركهن لحفظ البيت ، فيسمع كل إسرائيل أنك قد صرت مكروها من أبيك ، فتتشدد أيدي جميع الذين معك '),
(7092, '2 Samuel', 10, 16, 22, ' فنصبوا لأبشالوم الخيمة على السطح ، ودخل أبشالوم إلى سراري أبيه أمام جميع إسرائيل '),
(7093, '2 Samuel', 10, 16, 23, ' وكانت مشورة أخيتوفل التي كان يشير بها في تلك الأيام كمن يسأل بكلام الله . هكذا كل مشورة أخيتوفل على داود وعلى أبشالوم جميعا '),
(7094, '2 Samuel', 10, 17, 1, ' وقال أخيتوفل لأبشالوم : دعني أنتخب اثني عشر ألف رجل وأقوم وأسعى وراء داود هذه الليلة '),
(7095, '2 Samuel', 10, 17, 2, ' فآتي عليه وهو متعب ومرتخي اليدين فأزعجه ، فيهرب كل الشعب الذي معه ، وأضرب الملك وحده '),
(7096, '2 Samuel', 10, 17, 3, ' وأرد جميع الشعب إليك . كرجوع الجميع هو الرجل الذي تطلبه ، فيكون كل الشعب في سلام '),
(7097, '2 Samuel', 10, 17, 4, ' فحسن الأمر في عيني أبشالوم وأعين جميع شيوخ إسرائيل '),
(7098, '2 Samuel', 10, 17, 5, ' فقال أبشالوم : ادع أيضا حوشاي الأركي فنسمع ما يقول هو أيضا '),
(7099, '2 Samuel', 10, 17, 6, ' فلما جاء حوشاي إلى أبشالوم ، كلمه أبشالوم قائلا : بمثل هذا الكلام تكلم أخيتوفل . أنعمل حسب كلامه أم لا ؟ تكلم أنت '),
(7100, '2 Samuel', 10, 17, 7, ' فقال حوشاي لأبشالوم : ليست حسنة المشورة التي أشار بها أخيتوفل هذه المرة '),
(7101, '2 Samuel', 10, 17, 8, ' ثم قال حوشاي : أنت تعلم أباك ورجاله أنهم جبابرة ، وأن أنفسهم مرة كدبة مثكل في الحقل . وأبوك رجل قتال ولا يبيت مع الشعب '),
(7102, '2 Samuel', 10, 17, 9, ' ها هو الآن مختبئ في إحدى الحفر أو أحد الأماكن . ويكون إذا سقط بعضهم في الابتداء أن السامع يسمع فيقول : قد صارت كسرة في الشعب الذي وراء أبشالوم '),
(7103, '2 Samuel', 10, 17, 10, ' أيضا ذو البأس الذي قلبه كقلب الأسد يذوب ذوبانا ، لأن جميع إسرائيل يعلمون أن أباك جبار ، والذين معه ذوو بأس '),
(7104, '2 Samuel', 10, 17, 11, ' لذلك أشير بأن يجتمع إليك كل إسرائيل من دان إلى بئر سبع ، كالرمل الذي على البحر في الكثرة ، وحضرتك سائر في الوسط '),
(7105, '2 Samuel', 10, 17, 12, ' ونأتي إليه إلى أحد الأماكن حيث هو ، وننزل عليه نزول الطل على الأرض ، ولا يبقى منه ولا من جميع الرجال الذين معه واحد '),
(7106, '2 Samuel', 10, 17, 13, ' وإذا انحاز إلى مدينة ، يحمل جميع إسرائيل إلى تلك المدينة حبالا ، فنجرها إلى الوادي حتى لا تبقى هناك ولا حصاة '),
(7107, '2 Samuel', 10, 17, 14, ' فقال أبشالوم وكل رجال إسرائيل : إن مشورة حوشاي الأركي أحسن من مشورة أخيتوفل . فإن الرب أمر بإبطال مشورة أخيتوفل الصالحة ، لكي ينزل الرب الشر بأبشالوم '),
(7108, '2 Samuel', 10, 17, 15, ' وقال حوشاي لصادوق وأبياثار الكاهنين : كذا وكذا أشار أخيتوفل على أبشالوم وعلى شيوخ إسرائيل ، وكذا وكذا أشرت أنا '),
(7109, '2 Samuel', 10, 17, 16, ' فالآن أرسلوا عاجلا وأخبروا داود قائلين : لا تبت هذه الليلة في سهول البرية ، بل اعبر لئلا يبتلع الملك وجميع الشعب الذي معه '),
(7110, '2 Samuel', 10, 17, 17, ' وكان يوناثان وأخيمعص واقفين عند عين روجل ، فانطلقت الجارية وأخبرتهما ، وهما ذهبا وأخبرا الملك داود ، لأنهما لم يقدرا أن يريا داخلين المدينة '),
(7111, '2 Samuel', 10, 17, 18, ' فرآهما غلام وأخبر أبشالوم . فذهبا كلاهما عاجلا ودخلا بيت رجل في بحوريم وله بئر في داره ، فنزلا إليها '),
(7112, '2 Samuel', 10, 17, 19, ' فأخذت المرأة وفرشت سجفا على فم البئر وسطحت عليه سميذا فلم يعلم الأمر '),
(7113, '2 Samuel', 10, 17, 20, ' فجاء عبيد أبشالوم إلى المرأة إلى البيت وقالوا : أين أخيمعص ويوناثان ؟  . فقالت لهم المرأة : قد عبرا قناة الماء . ولما فتشوا ولم يجدوهما رجعوا إلى أورشليم '),
(7114, '2 Samuel', 10, 17, 21, ' وبعد ذهابهم خرجا من البئر وذهبا وأخبرا الملك داود ، وقالا لداود : قوموا واعبروا سريعا الماء ، لأن هكذا أشار عليكم أخيتوفل '),
(7115, '2 Samuel', 10, 17, 22, ' فقام داود وجميع الشعب الذي معه وعبروا الأردن . وعند ضوء الصباح لم يبق أحد لم يعبر الأردن '),
(7116, '2 Samuel', 10, 17, 23, ' وأما أخيتوفل فلما رأى أن مشورته لم يعمل بها ، شد على الحمار وقام وانطلق إلى بيته إلى مدينته ، وأوصى لبيته ، وخنق نفسه ومات ودفن في قبر أبيه '),
(7117, '2 Samuel', 10, 17, 24, ' وجاء داود إلى محنايم . وعبر أبشالوم الأردن هو وجميع رجال إسرائيل معه '),
(7118, '2 Samuel', 10, 17, 25, ' وأقام أبشالوم عماسا بدل يوآب على الجيش . وكان عماسا ابن رجل اسمه يثرا الإسرائيلي الذي دخل إلى أبيجايل بنت ناحاش أخت صروية أم يوآب '),
(7119, '2 Samuel', 10, 17, 26, ' ونزل إسرائيل وأبشالوم في أرض جلعاد '),
(7120, '2 Samuel', 10, 17, 27, ' وكان لما جاء داود إلى محنايم أن شوبي بن ناحاش من ربة بني عمون ، وماكير بن عميئيل من لودبار ، وبرزلاي الجلعادي من روجليم '),
(7121, '2 Samuel', 10, 17, 28, ' قدموا فرشا وطسوسا وآنية خزف وحنطة وشعيرا ودقيقا وفريكا وفولا وعدسا وحمصا مشويا '),
(7122, '2 Samuel', 10, 17, 29, ' وعسلا وزبدة وضأنا وجبن بقر ، لداود وللشعب الذي معه ليأكلوا ، لأنهم قالوا : الشعب جوعان ومتعب وعطشان في البرية '),
(7123, '2 Samuel', 10, 18, 1, ' وأحصى داود الشعب الذي معه ، وجعل عليهم رؤساء ألوف ورؤساء مئات '),
(7124, '2 Samuel', 10, 18, 2, ' وأرسل داود الشعب ثلثا بيد يوآب ، وثلثا بيد أبيشاي ابن صروية أخي يوآب ، وثلثا بيد إتاي الجتي . وقال الملك للشعب : إني أنا أيضا أخرج معكم '),
(7125, '2 Samuel', 10, 18, 3, ' فقال الشعب : لا تخرج ، لأننا إذا هربنا لا يبالون بنا ، وإذا مات نصفنا لا يبالون بنا . والآن أنت كعشرة آلاف منا . والآن الأصلح أن تكون لنا نجدة من المدينة '),
(7126, '2 Samuel', 10, 18, 4, ' فقال لهم الملك : ما يحسن في أعينكم أفعله . فوقف الملك بجانب الباب وخرج جميع الشعب مئات وألوفا '),
(7127, '2 Samuel', 10, 18, 5, ' وأوصى الملك يوآب وأبيشاي وإتاي قائلا : ترفقوا لي بالفتى أبشالوم . وسمع جميع الشعب حين أوصى الملك جميع الرؤساء بأبشالوم '),
(7128, '2 Samuel', 10, 18, 6, ' وخرج الشعب إلى الحقل للقاء إسرائيل . وكان القتال في وعر أفرايم '),
(7129, '2 Samuel', 10, 18, 7, ' فانكسر هناك شعب إسرائيل أمام عبيد داود ، وكانت هناك مقتلة عظيمة في ذلك اليوم . قتل عشرون ألفا '),
(7130, '2 Samuel', 10, 18, 8, ' وكان القتال هناك منتشرا على وجه كل الأرض ، وزاد الذين أكلهم الوعر من الشعب على الذين أكلهم السيف في ذلك اليوم '),
(7131, '2 Samuel', 10, 18, 9, ' وصادف أبشالوم عبيد داود ، وكان أبشالوم راكبا على بغل ، فدخل البغل تحت أغصان البطمة العظيمة الملتفة ، فتعلق رأسه بالبطمة وعلق بين السماء والأرض ، والبغل الذي تحته مر '),
(7132, '2 Samuel', 10, 18, 10, ' فرآه رجل وأخبر يوآب وقال : إني قد رأيت أبشالوم معلقا بالبطمة '),
(7133, '2 Samuel', 10, 18, 11, ' فقال يوآب للرجل الذي أخبره : إنك قد رأيته ، فلماذا لم تضربه هناك إلى الأرض ؟ وعلي أن أعطيك عشرة من الفضة ومنطقة '),
(7134, '2 Samuel', 10, 18, 12, ' فقال الرجل ليوآب : فلو وزن في يدي ألف من الفضة لما كنت أمد يدي إلى ابن الملك ، لأن الملك أوصاك في آذاننا أنت وأبيشاي وإتاي قائلا : احترزوا أيا كان منكم على الفتى أبشالوم '),
(7135, '2 Samuel', 10, 18, 13, ' وإلا فكنت فعلت بنفسي زورا ، إذ لا يخفى عن الملك شيء ، وأنت كنت وقفت ضدي '),
(7136, '2 Samuel', 10, 18, 14, ' فقال يوآب : إني لا أصبر هكذا أمامك . فأخذ ثلاثة سهام بيده ونشبها في قلب أبشالوم ، وهو بعد حي في قلب البطمة '),
(7137, '2 Samuel', 10, 18, 15, ' وأحاط بها عشرة غلمان حاملو سلاح يوآب ، وضربوا أبشالوم وأماتوه '),
(7138, '2 Samuel', 10, 18, 16, ' وضرب يوآب بالبوق فرجع الشعب عن اتباع إسرائيل ، لأن يوآب منع الشعب '),
(7139, '2 Samuel', 10, 18, 17, ' وأخذوا أبشالوم وطرحوه في الوعر في الجب العظيم ، وأقاموا عليه رجمة عظيمة جدا من الحجارة . وهرب كل إسرائيل ، كل واحد إلى خيمته '),
(7140, '2 Samuel', 10, 18, 18, ' وكان أبشالوم قد أخذ وأقام لنفسه وهو حي النصب الذي في وادي الملك ، لأنه قال : ليس لي ابن لأجل تذكير اسمي . ودعا النصب باسمه ، وهو يدعى يد أبشالوم إلى هذا اليوم '),
(7141, '2 Samuel', 10, 18, 19, ' وقال أخيمعص بن صادوق : دعني أجر فأبشر الملك ، لأن الله قد انتقم له من أعدائه '),
(7142, '2 Samuel', 10, 18, 20, ' فقال له يوآب : ما أنت صاحب بشارة في هذا اليوم . في يوم آخر تبشر ، وهذا اليوم لا تبشر من أجل أن ابن الملك قد مات '),
(7143, '2 Samuel', 10, 18, 21, ' وقال يوآب لكوشي : اذهب وأخبر الملك بما رأيت . فسجد كوشي ليوآب وركض '),
(7144, '2 Samuel', 10, 18, 22, ' وعاد أيضا أخيمعص بن صادوق فقال ليوآب : مهما كان ، فدعني أجر أنا أيضا وراء كوشي . فقال يوآب : لماذا تجري أنت يا ابني ، وليس لك بشارة تجازى '),
(7145, '2 Samuel', 10, 18, 23, ' قال : مهما كان أجري . فقال له : اجر . فجرى أخيمعص في طريق الغور وسبق كوشي '),
(7146, '2 Samuel', 10, 18, 24, ' وكان داود جالسا بين البابين ، وطلع الرقيب إلى سطح الباب إلى السور ورفع عينيه ونظر وإذا برجل يجري وحده '),
(7147, '2 Samuel', 10, 18, 25, ' فنادى الرقيب وأخبر الملك . فقال الملك : إن كان وحده ففي فمه بشارة . وكان يسعى ويقرب '),
(7148, '2 Samuel', 10, 18, 26, ' ثم رأى الرقيب رجلا آخر يجري ، فنادى الرقيب البواب وقال : هوذا رجل يجري وحده . فقال الملك : وهذا أيضا مبشر '),
(7149, '2 Samuel', 10, 18, 27, ' وقال الرقيب : إني أرى جري الأول كجري أخيمعص بن صادوق . فقال الملك : هذا رجل صالح ويأتي ببشارة صالحة '),
(7150, '2 Samuel', 10, 18, 28, ' فنادى أخيمعص وقال للملك : السلام . وسجد للملك على وجهه إلى الأرض . وقال : مبارك الرب إلهك الذي دفع القوم الذين رفعوا أيديهم على سيدي الملك '),
(7151, '2 Samuel', 10, 18, 29, ' فقال الملك : أسلام للفتى أبشالوم ؟  . فقال أخيمعص : قد رأيت جمهورا عظيما عند إرسال يوآب عبد الملك وعبدك ، ولم أعلم ماذا '),
(7152, '2 Samuel', 10, 18, 30, ' فقال الملك : در وقف ههنا . فدار ووقف '),
(7153, '2 Samuel', 10, 18, 31, ' وإذا بكوشي قد أتى ، وقال كوشي : ليبشر سيدي الملك ، لأن الرب قد انتقم لك اليوم من جميع القائمين عليك '),
(7154, '2 Samuel', 10, 18, 32, ' فقال الملك لكوشي : أسلام للفتى أبشالوم ؟  . فقال كوشي : ليكن كالفتى أعداء سيدي الملك وجميع الذين قاموا عليك للشر '),
(7155, '2 Samuel', 10, 18, 33, ' فانزعج الملك وصعد إلى علية الباب وكان يبكي ويقول هكذا وهو يتمشى : يا ابني أبشالوم ، يا ابني ، يا ابني أبشالوم يا ليتني مت عوضا عنك يا أبشالوم ابني ، يا ابني '),
(7156, '2 Samuel', 10, 19, 1, ' فأخبر يوآب : هوذا الملك يبكي وينوح على أبشالوم '),
(7157, '2 Samuel', 10, 19, 2, ' فصارت الغلبة في ذلك اليوم مناحة عند جميع الشعب ، لأن الشعب سمعوا في ذلك اليوم من يقول إن الملك قد تأسف على ابنه '),
(7158, '2 Samuel', 10, 19, 3, ' وتسلل الشعب في ذلك اليوم للدخول إلى المدينة كما يتسلل القوم الخجلون عندما يهربون في القتال '),
(7159, '2 Samuel', 10, 19, 4, ' وستر الملك وجهه وصرخ الملك بصوت عظيم : يا ابني أبشالوم ، يا أبشالوم ابني ، يا ابني '),
(7160, '2 Samuel', 10, 19, 5, ' فدخل يوآب إلى الملك إلى البيت وقال : قد أخزيت اليوم وجوه جميع عبيدك ، منقذي نفسك اليوم وأنفس بنيك وبناتك وأنفس نسائك وأنفس سراريك '),
(7161, '2 Samuel', 10, 19, 6, ' بمحبتك لمبغضيك وبغضك لمحبيك ، لأنك أظهرت اليوم أنه ليس لك رؤساء ولا عبيد ، لأني علمت اليوم أنه لو كان أبشالوم حيا وكلنا اليوم موتى ، لحسن حينئذ الأمر في عينيك '),
(7162, '2 Samuel', 10, 19, 7, ' فالآن قم واخرج وطيب قلوب عبيدك ، لأني قد أقسمت بالرب إنه إن لم تخرج لا يبيت أحد معك هذه الليلة ، ويكون ذلك أشر عليك من كل شر أصابك منذ صباك إلى الآن '),
(7163, '2 Samuel', 10, 19, 8, ' فقام الملك وجلس في الباب . فأخبروا جميع الشعب قائلين : هوذا الملك جالس في الباب . فأتى جميع الشعب أمام الملك . وأما إسرائيل فهربوا كل واحد إلى خيمته '),
(7164, '2 Samuel', 10, 19, 9, ' وكان جميع الشعب في خصام في جميع أسباط إسرائيل قائلين : إن الملك قد أنقذنا من يد أعدائنا وهو نجانا من يد الفلسطينيين ، والآن قد هرب من الأرض لأجل أبشالوم '),
(7165, '2 Samuel', 10, 19, 10, ' وأبشالوم الذي مسحناه علينا قد مات في الحرب . فالآن لماذا أنتم ساكتون عن إرجاع الملك '),
(7166, '2 Samuel', 10, 19, 11, ' وأرسل الملك داود إلى صادوق وأبياثار الكاهنين قائلا : كلما شيوخ يهوذا قائلين : لماذا تكونون آخرين في إرجاع الملك إلى بيته ، وقد أتى كلام جميع إسرائيل إلى الملك في بيته '),
(7167, '2 Samuel', 10, 19, 12, ' أنتم إخوتي . أنتم عظمي ولحمي . فلماذا تكونون آخرين في إرجاع الملك '),
(7168, '2 Samuel', 10, 19, 13, ' وتقولان لعماسا : أما أنت عظمي ولحمي ؟ هكذا يفعل بي الله وهكذا يزيد ، إن كنت لا تصير رئيس جيش عندي كل الأيام بدل يوآب '),
(7169, '2 Samuel', 10, 19, 14, ' فاستمال بقلوب جميع رجال يهوذا كرجل واحد ، فأرسلوا إلى الملك قائلين : ارجع أنت وجميع عبيدك '),
(7170, '2 Samuel', 10, 19, 15, ' فرجع الملك وأتى إلى الأردن ، وأتى يهوذا إلى الجلجال سائرا لملاقاة الملك ليعبر الملك الأردن '),
(7171, '2 Samuel', 10, 19, 16, ' فبادر شمعي بن جيرا البنياميني الذي من بحوريم ونزل مع رجال يهوذا للقاء الملك داود '),
(7172, '2 Samuel', 10, 19, 17, ' ومعه ألف رجل من بنيامين ، وصيبا غلام بيت شاول وبنوه الخمسة عشر وعبيده العشرون معه ، فخاضوا الأردن أمام الملك '),
(7173, '2 Samuel', 10, 19, 18, ' وعبر القارب لتعبير بيت الملك ولعمل ما يحسن في عينيه . وسقط شمعي بن جيرا أمام الملك عندما عبر الأردن '),
(7174, '2 Samuel', 10, 19, 19, ' وقال للملك : لا يحسب لي سيدي إثما ، ولا تذكر ما افترى به عبدك يوم خروج سيدي الملك من أورشليم ، حتى يضع الملك ذلك في قلبه '),
(7175, '2 Samuel', 10, 19, 20, ' لأن عبدك يعلم أني قد أخطأت ، وهأنذا قد جئت اليوم أول كل بيت يوسف ، ونزلت للقاء سيدي الملك '),
(7176, '2 Samuel', 10, 19, 21, ' فأجاب أبيشاي ابن صروية وقال : ألا يقتل شمعي لأجل هذا ، لأنه سب مسيح الرب '),
(7177, '2 Samuel', 10, 19, 22, ' فقال داود : ما لي ولكم يا بني صروية حتى تكونوا لي اليوم مقاومين ؟ آليوم يقتل أحد في إسرائيل ؟ أفما علمت أني اليوم ملك على إسرائيل '),
(7178, '2 Samuel', 10, 19, 23, ' ثم قال الملك لشمعي : لا تموت . وحلف له الملك '),
(7179, '2 Samuel', 10, 19, 24, ' ونزل مفيبوشث ابن شاول للقاء الملك ، ولم يعتن برجليه ، ولا اعتنى بلحيته ، ولا غسل ثيابه ، من اليوم الذي ذهب فيه الملك إلى اليوم الذي أتى فيه بسلام '),
(7180, '2 Samuel', 10, 19, 25, ' فلما جاء إلى أورشليم للقاء الملك ، قال له الملك : لماذا لم تذهب معي يا مفيبوشث '),
(7181, '2 Samuel', 10, 19, 26, ' فقال : يا سيدي الملك إن عبدي قد خدعني ، لأن عبدك قال : أشد لنفسي الحمار فأركب عليه وأذهب مع الملك ، لأن عبدك أعرج '),
(7182, '2 Samuel', 10, 19, 27, ' ووشى بعبدك إلى سيدي الملك ، وسيدي الملك كملاك الله . فا فعل ما يحسن في عينيك '),
(7183, '2 Samuel', 10, 19, 28, ' لأن كل بيت أبي لم يكن إلا أناسا موتى لسيدي الملك ، وقد جعلت عبدك بين الآكلين على مائدتك . فأي حق لي بعد حتى أصرخ أيضا إلى الملك '),
(7184, '2 Samuel', 10, 19, 29, ' فقال له الملك : لماذا تتكلم بعد بأمورك ؟ قد قلت : إنك أنت وصيبا تقسمان الحقل '),
(7185, '2 Samuel', 10, 19, 30, ' فقال مفيبوشث للملك : فليأخذ الكل أيضا بعد أن جاء سيدي الملك بسلام إلى بيته '),
(7186, '2 Samuel', 10, 19, 31, ' ونزل برزلاي الجلعادي من روجليم وعبر الأردن مع الملك ليشيعه عند الأردن '),
(7187, '2 Samuel', 10, 19, 32, ' وكان برزلاي قد شاخ جدا . كان ابن ثمانين سنة . وهو عال الملك عند إقامته في محنايم لأنه كان رجلا عظيما جدا '),
(7188, '2 Samuel', 10, 19, 33, ' فقال الملك لبرزلاي : اعبر أنت معي وأنا أعولك معي في أورشليم '),
(7189, '2 Samuel', 10, 19, 34, ' فقال برزلاي للملك : كم أيام سني حياتي حتى أصعد مع الملك إلى أورشليم '),
(7190, '2 Samuel', 10, 19, 35, ' أنا اليوم ابن ثمانين سنة . هل أميز بين الطيب والرديء ؟ وهل يستطعم عبدك بما آكل وما أشرب ؟ وهل أسمع أيضا أصوات المغنين والمغنيات ؟ فلماذا يكون عبدك أيضا ثقلا على سيدي الملك '),
(7191, '2 Samuel', 10, 19, 36, ' يعبر عبدك قليلا الأردن مع الملك . ولماذا يكافئني الملك بهذه المكافأة '),
(7192, '2 Samuel', 10, 19, 37, ' دع عبدك يرجع فأموت في مدينتي عند قبر أبي وأمي . وهوذا عبدك كمهام يعبر مع سيدي الملك ، فافعل له ما يحسن في عينيك '),
(7193, '2 Samuel', 10, 19, 38, ' فأجاب الملك : إن كمهام يعبر معي فأفعل له ما يحسن في عينيك ، وكل ما تتمناه مني أفعله لك '),
(7194, '2 Samuel', 10, 19, 39, ' فعبر جميع الشعب الأردن ، والملك عبر . وقبل الملك برزلاي وباركه ، فرجع إلى مكانه '),
(7195, '2 Samuel', 10, 19, 40, ' وعبر الملك إلى الجلجال ، وعبر كمهام معه ، وكل شعب يهوذا عبروا الملك ، وكذلك نصف شعب إسرائيل '),
(7196, '2 Samuel', 10, 19, 41, ' وإذا بجميع رجال إسرائيل جاءون إلى الملك ، وقالوا للملك : لماذا سرقك إخوتنا رجال يهوذا وعبروا الأردن بالملك وبيته وكل رجال داود معه '),
(7197, '2 Samuel', 10, 19, 42, ' فأجاب كل رجال يهوذا رجال إسرائيل : لأن الملك قريب إلي ، ولماذا تغتاظ من هذا الأمر ؟ هل أكلنا شيئا من الملك أو وهبنا هبة '),
(7198, '2 Samuel', 10, 19, 43, ' فأجاب رجال إسرائيل رجال يهوذا وقالوا : لي عشرة أسهم في الملك ، وأنا أحق منك بداود ، فلماذا استخففت بي ولم يكن كلامي أولا في إرجاع ملكي ؟  . وكان كلام رجال يهوذا أقسى من كلام رجال إسرائيل '),
(7199, '2 Samuel', 10, 20, 1, ' واتفق هناك رجل لئيم اسمه شبع بن بكري رجل بنياميني ، فضرب بالبوق وقال : ليس لنا قسم في داود ولا لنا نصيب في ابن يسى . كل رجل إلى خيمته يا إسرائيل '),
(7200, '2 Samuel', 10, 20, 2, ' فصعد كل رجال إسرائيل من وراء داود إلى وراء شبع بن بكري . وأما رجال يهوذا فلازموا ملكهم من الأردن إلى أورشليم '),
(7201, '2 Samuel', 10, 20, 3, ' وجاء داود إلى بيته في أورشليم . وأخذ الملك النساء السراري العشر اللواتي تركهن لحفظ البيت ، وجعلهن تحت حجز ، وكان يعولهن ولكن لم يدخل إليهن ، بل كن محبوسات إلى يوم موتهن في عيشة العزوبة '),
(7202, '2 Samuel', 10, 20, 4, ' وقال الملك لعماسا : اجمع لي رجال يهوذا في ثلاثة أيام ، واحضر أنت هنا '),
(7203, '2 Samuel', 10, 20, 5, ' فذهب عماسا ليجمع يهوذا ، ولكنه تأخر عن الميقات الذي عينه '),
(7204, '2 Samuel', 10, 20, 6, ' فقال داود لأبيشاي : الآن يسيء إلينا شبع بن بكري أكثر من أبشالوم . فخذ أنت عبيد سيدك واتبعه لئلا يجد لنفسه مدنا حصينة وينفلت من أمام أعيننا '),
(7205, '2 Samuel', 10, 20, 7, ' فخرج وراءه رجال يوآب : الجلادون والسعاة وجميع الأبطال ، وخرجوا من أورشليم ليتبعوا شبع بن بكري '),
(7206, '2 Samuel', 10, 20, 8, ' ولما كانوا عند الصخرة العظيمة التي في جبعون ، جاء عماسا قدامهم . وكان يوآب متنطقا على ثوبه الذي كان لابسه ، وفوقه منطقة سيف في غمده مشدودة على حقويه ، فلما خرج اندلق السيف '),
(7207, '2 Samuel', 10, 20, 9, ' فقال يوآب لعماسا : أسالم أنت يا أخي ؟  . وأمسكت يد يوآب اليمنى بلحية عماسا ليقبله '),
(7208, '2 Samuel', 10, 20, 10, ' وأما عماسا فلم يحترز من السيف الذي بيد يوآب ، فضربه به في بطنه فدلق أمعاءه إلى الأرض ولم يثن عليه ، فمات . وأما يوآب وأبيشاي أخوه فتبعا شبع بن بكري '),
(7209, '2 Samuel', 10, 20, 11, ' ووقف عنده واحد من غلمان يوآب ، فقال : من سر بيوآب ، ومن هو لداود ، فوراء يوآب '),
(7210, '2 Samuel', 10, 20, 12, ' وكان عماسا يتمرغ في الدم في وسط السكة . ولما رأى الرجل أن كل الشعب يقفون ، نقل عماسا من السكة إلى الحقل وطرح عليه ثوبا ، لما رأى أن كل من يصل إليه يقف '),
(7211, '2 Samuel', 10, 20, 13, ' فلما نقل عن السكة عبر كل إنسان وراء يوآب لاتباع شبع بن بكري '),
(7212, '2 Samuel', 10, 20, 14, ' وعبر في جميع أسباط إسرائيل إلى آبل وبيت معكة وجميع البيريين ، فاجتمعوا وخرجوا أيضا وراءه '),
(7213, '2 Samuel', 10, 20, 15, ' وجاءوا وحاصروه في آبل بيت معكة ، وأقاموا مترسة حول المدينة فأقامت في الحصار ، وجميع الشعب الذين مع يوآب كانوا يخربون لأجل إسقاط السور '),
(7214, '2 Samuel', 10, 20, 16, ' فنادت امرأة حكيمة من المدينة : اسمعوا . اسمعوا . قولوا ليوآب تقدم إلى ههنا فأكلمك '),
(7215, '2 Samuel', 10, 20, 17, ' فتقدم إليها ، فقالت المرأة : أأنت يوآب ؟  . فقال : أنا هو . فقالت له : اسمع كلام أمتك . فقال : أنا سامع '),
(7216, '2 Samuel', 10, 20, 18, ' فتكلمت قائلة : كانوا يتكلمون أولا قائلين : سؤالا يسألون في آبل . وهكذا كانوا انتهوا '),
(7217, '2 Samuel', 10, 20, 19, ' أنا مسالمة أمينة في إسرائيل . أنت طالب أن تميت مدينة وأما في إسرائيل . لماذا تبلع نصيب الرب '),
(7218, '2 Samuel', 10, 20, 20, ' فأجاب يوآب وقال : حاشاي حاشاي أن أبلع وأن أهلك '),
(7219, '2 Samuel', 10, 20, 21, ' الأمر ليس كذلك . لأن رجلا من جبل أفرايم اسمه شبع بن بكري رفع يده على الملك داود . سلموه وحده فأنصرف عن المدينة . فقالت المرأة ليوآب : هوذا رأسه يلقى إليك عن السور '),
(7220, '2 Samuel', 10, 20, 22, ' فأتت المرأة إلى جميع الشعب بحكمتها فقطعوا رأس شبع بن بكري وألقوه إلى يوآب ، فضرب بالبوق فانصرفوا عن المدينة كل واحد إلى خيمته . وأما يوآب فرجع إلى أورشليم إلى الملك '),
(7221, '2 Samuel', 10, 20, 23, ' وكان يوآب على جميع جيش إسرائيل ، وبنايا بن يهوياداع على الجلادين والسعاة '),
(7222, '2 Samuel', 10, 20, 24, ' وأدورام على الجزية ، ويهوشافاط بن أخيلود مسجلا '),
(7223, '2 Samuel', 10, 20, 25, ' وشيوا كاتبا ، وصادوق وأبياثار كاهنين '),
(7224, '2 Samuel', 10, 20, 26, ' وعيرا اليائيري أيضا كان كاهنا لداود '),
(7225, '2 Samuel', 10, 21, 1, ' وكان جوع في أيام داود ثلاث سنين ، سنة بعد سنة ، فطلب داود وجه الرب . فقال الرب : هو لأجل شاول ولأجل بيت الدماء ، لأنه قتل الجبعونيين '),
(7226, '2 Samuel', 10, 21, 2, ' فدعا الملك الجبعونيين وقال لهم . والجبعونيون ليسوا من بني إسرائيل بل من بقايا الأموريين ، وقد حلف لهم بنو إسرائيل ، وطلب شاول أن يقتلهم لأجل غيرته على بني إسرائيل ويهوذا '),
(7227, '2 Samuel', 10, 21, 3, ' قال داود للجبعونيين : ماذا أفعل لكم ؟ وبماذا أكفر فتباركوا نصيب الرب '),
(7228, '2 Samuel', 10, 21, 4, ' فقال له الجبعونيون : ليس لنا فضة ولا ذهب عند شاول ولا عند بيته ، وليس لنا أن نميت أحدا في إسرائيل . فقال : مهما قلتم أفعله لكم '),
(7229, '2 Samuel', 10, 21, 5, ' فقالوا للملك : الرجل الذي أفنانا والذي تآمر علينا ليبيدنا لكي لا نقيم في كل تخوم إسرائيل '),
(7230, '2 Samuel', 10, 21, 6, ' فلنعط سبعة رجال من بنيه فنصلبهم للرب في جبعة شاول مختار الرب . فقال الملك : أنا أعطي '),
(7231, '2 Samuel', 10, 21, 7, ' وأشفق الملك على مفيبوشث بن يوناثان بن شاول من أجل يمين الرب التي بينهما ، بين داود ويوناثان بن شاول '),
(7232, '2 Samuel', 10, 21, 8, ' فأخذ الملك ابني رصفة ابنة أية اللذين ولدتهما لشاول : أرموني ومفيبوشث ، وبني ميكال ابنة شاول الخمسة الذين ولدتهم لعدرئيل بن برزلاي المحولي '),
(7233, '2 Samuel', 10, 21, 9, ' وسلمهم إلى يد الجبعونيين ، فصلبوهم على الجبل أمام الرب . فسقط السبعة معا وقتلوا في أيام الحصاد ، في أولها في ابتداء حصاد الشعير '),
(7234, '2 Samuel', 10, 21, 10, ' فأخذت رصفة ابنة أية مسحا وفرشته لنفسها على الصخر من ابتداء الحصاد حتى انصب الماء عليهم من السماء ، ولم تدع طيور السماء تنزل عليهم نهارا ، ولا حيوانات الحقل ليلا '),
(7235, '2 Samuel', 10, 21, 11, ' فأخبر داود بما فعلت رصفة ابنة أية سرية شاول '),
(7236, '2 Samuel', 10, 21, 12, ' فذهب داود وأخذ عظام شاول وعظام يوناثان ابنه من أهل يابيش جلعاد الذين سرقوها من شارع بيت شان ، حيث علقهما الفلسطينيون يوم ضرب الفلسطينيون شاول في جلبوع '),
(7237, '2 Samuel', 10, 21, 13, ' فأصعد من هناك عظام شاول وعظام يوناثان ابنه ، وجمعوا عظام المصلوبين '),
(7238, '2 Samuel', 10, 21, 14, ' ودفنوا عظام شاول ويوناثان ابنه في أرض بنيامين في صيلع ، في قبر قيس أبيه ، وعملوا كل ما أمر به الملك . وبعد ذلك استجاب الله من أجل الأرض '),
(7239, '2 Samuel', 10, 21, 15, ' وكانت أيضا حرب بين الفلسطينيين وإسرائيل ، فانحدر داود وعبيده معه وحاربوا الفلسطينيين ، فأعيا داود '),
(7240, '2 Samuel', 10, 21, 16, ' ويشبي بنوب الذي من أولاد رافا ، ووزن رمحه ثلاث مئة شاقل نحاس وقد تقلد جديدا ، افتكر أن يقتل داود '),
(7241, '2 Samuel', 10, 21, 17, ' فأنجده أبيشاي ابن صروية ، فضرب الفلسطيني وقتله . حينئذ حلف رجال داود له قائلين : لا تخرج أيضا معنا إلى الحرب ، ولا تطفئ سراج إسرائيل '),
(7242, '2 Samuel', 10, 21, 18, ' ثم بعد ذلك كانت أيضا حرب في جوب مع الفلسطينيين . حينئذ سبكاي الحوشي قتل ساف الذي هو من أولاد رافا '),
(7243, '2 Samuel', 10, 21, 19, ' ثم كانت أيضا حرب في جوب مع الفلسطينيين . فألحانان بن يعري أرجيم البيتلحمي قتل جليات الجتي ، وكانت قناة رمحه كنول النساجين '),
(7244, '2 Samuel', 10, 21, 20, ' وكانت أيضا حرب في جت ، وكان رجل طويل القامة أصابع كل من يديه ست ، وأصابع كل من رجليه ست ، عددها أربع وعشرون ، وهو أيضا ولد لرافا '),
(7245, '2 Samuel', 10, 21, 21, ' ولما عير إسرائيل ضربه يوناثان بن شمعى أخي داود '),
(7246, '2 Samuel', 10, 21, 22, ' هؤلاء الأربعة ولدوا لرافا في جت وسقطوا بيد داود وبيد عبيده '),
(7247, '2 Samuel', 10, 22, 1, ' وكلم داود الرب بكلام هذا النشيد في اليوم الذي أنقذه فيه الرب من أيدي كل أعدائه ومن يد شاول '),
(7248, '2 Samuel', 10, 22, 2, ' فقال : الرب صخرتي وحصني ومنقذي '),
(7249, '2 Samuel', 10, 22, 3, ' إله صخرتي به أحتمي . ترسي وقرن خلاصي . ملجإي ومناصي . مخلصي ، من الظلم تخلصني '),
(7250, '2 Samuel', 10, 22, 4, ' أدعو الرب الحميد فأتخلص من أعدائي '),
(7251, '2 Samuel', 10, 22, 5, ' لأن أمواج الموت اكتنفتني . سيول الهلاك أفزعتني '),
(7252, '2 Samuel', 10, 22, 6, ' حبال الهاوية أحاطت بي . شرك الموت أصابتني '),
(7253, '2 Samuel', 10, 22, 7, ' في ضيقي دعوت الرب ، وإلى إلهي صرخت ، فسمع من هيكله صوتي ، وصراخي دخل أذنيه '),
(7254, '2 Samuel', 10, 22, 8, ' فارتجت الأرض وارتعشت . أسس السماوات ارتعدت وارتجت ، لأنه غضب '),
(7255, '2 Samuel', 10, 22, 9, ' صعد دخان من أنفه ، ونار من فمه أكلت . جمر اشتعلت منه '),
(7256, '2 Samuel', 10, 22, 10, ' طأطأ السماوات ونزل ، وضباب تحت رجليه '),
(7257, '2 Samuel', 10, 22, 11, ' ركب على كروب ، وطار ورئي على أجنحة الريح '),
(7258, '2 Samuel', 10, 22, 12, ' جعل الظلمة حوله مظلات ، مياها حاشكة وظلام الغمام '),
(7259, '2 Samuel', 10, 22, 13, ' من الشعاع قدامه اشتعلت جمر نار '),
(7260, '2 Samuel', 10, 22, 14, ' أرعد الرب من السماوات ، والعلي أعطى صوته '),
(7261, '2 Samuel', 10, 22, 15, ' أرسل سهاما فشتتهم ، برقا فأزعجهم '),
(7262, '2 Samuel', 10, 22, 16, ' فظهرت أعماق البحر ، وانكشفت أسس المسكونة من زجر الرب ، من نسمة ريح أنفه '),
(7263, '2 Samuel', 10, 22, 17, ' أرسل من العلى فأخذني ، نشلني من مياه كثيرة '),
(7264, '2 Samuel', 10, 22, 18, ' أنقذني من عدوي القوي ، من مبغضي لأنهم أقوى مني '),
(7265, '2 Samuel', 10, 22, 19, ' أصابوني في يوم بليتي ، وكان الرب سندي '),
(7266, '2 Samuel', 10, 22, 20, ' أخرجني إلى الرحب . خلصني لأنه سر بي '),
(7267, '2 Samuel', 10, 22, 21, ' يكافئني الرب حسب بري . حسب طهارة يدي يرد علي '),
(7268, '2 Samuel', 10, 22, 22, ' لأني حفظت طرق الرب ، ولم أعص إلهي '),
(7269, '2 Samuel', 10, 22, 23, ' لأن جميع أحكامه أمامي ، وفرائضه لا أحيد عنها '),
(7270, '2 Samuel', 10, 22, 24, ' وأكون كاملا لديه ، وأتحفظ من إثمي '),
(7271, '2 Samuel', 10, 22, 25, ' فيرد الرب علي كبري ، وكطهارتي أمام عينيه '),
(7272, '2 Samuel', 10, 22, 26, ' مع الرحيم تكون رحيما . مع الرجل الكامل تكون كاملا '),
(7273, '2 Samuel', 10, 22, 27, ' مع الطاهر تكون طاهرا ، ومع الأعوج تكون ملتويا '),
(7274, '2 Samuel', 10, 22, 28, ' وتخلص الشعب البائس ، وعيناك على المترفعين فتضعهم '),
(7275, '2 Samuel', 10, 22, 29, ' لأنك أنت سراجي يارب ، والرب يضيء ظلمتي '),
(7276, '2 Samuel', 10, 22, 30, ' لأني بك اقتحمت جيشا . بإلهي تسورت أسوارا '),
(7277, '2 Samuel', 10, 22, 31, ' الله طريقه كامل ، وقول الرب نقي . ترس هو لجميع المحتمين به '),
(7278, '2 Samuel', 10, 22, 32, ' لأنه من هو إله غير الرب ؟ ومن هو صخرة غير إلهنا '),
(7279, '2 Samuel', 10, 22, 33, ' الإله الذي يعززني بالقوة ، ويصير طريقي كاملا '),
(7280, '2 Samuel', 10, 22, 34, ' الذي يجعل رجلي كالإيل ، وعلى مرتفعاتي يقيمني '),
(7281, '2 Samuel', 10, 22, 35, ' الذي يعلم يدي القتال ، فتحنى بذراعي قوس من نحاس '),
(7282, '2 Samuel', 10, 22, 36, ' وتجعل لي ترس خلاصك ، ولطفك يعظمني '),
(7283, '2 Samuel', 10, 22, 37, ' توسع خطواتي تحتي ، فلم تتقلقل كعباي '),
(7284, '2 Samuel', 10, 22, 38, ' ألحق أعدائي فأهلكهم ، ولا أرجع حتى أفنيهم '),
(7285, '2 Samuel', 10, 22, 39, ' أفنيهم وأسحقهم فلا يقومون ، بل يسقطون تحت رجلي '),
(7286, '2 Samuel', 10, 22, 40, ' تنطقني قوة للقتال ، وتصرع القائمين علي تحتي '),
(7287, '2 Samuel', 10, 22, 41, ' وتعطيني أقفية أعدائي ومبغضي فأفنيهم '),
(7288, '2 Samuel', 10, 22, 42, ' يتطلعون فليس مخلص ، إلى الرب فلا يستجيبهم '),
(7289, '2 Samuel', 10, 22, 43, ' فأسحقهم كغبار الأرض . مثل طين الأسواق أدقهم وأدوسهم '),
(7290, '2 Samuel', 10, 22, 44, ' وتنقذني من مخاصمات شعبي ، وتحفظني رأسا للأمم . شعب لم أعرفه يتعبد لي '),
(7291, '2 Samuel', 10, 22, 45, ' بنو الغرباء يتذللون لي . من سماع الأذن يسمعون لي '),
(7292, '2 Samuel', 10, 22, 46, ' بنو الغرباء يبلون ويزحفون من حصونهم '),
(7293, '2 Samuel', 10, 22, 47, ' حي هو الرب ، ومبارك صخرتي ، ومرتفع إله صخرة خلاصي '),
(7294, '2 Samuel', 10, 22, 48, ' الإله المنتقم لي ، والمخضع شعوبا تحتي '),
(7295, '2 Samuel', 10, 22, 49, ' والذي يخرجني من بين أعدائي ، ويرفعني فوق القائمين علي ، وينقذني من رجل الظلم '),
(7296, '2 Samuel', 10, 22, 50, ' لذلك أحمدك يارب في الأمم ، ولاسمك أرنم '),
(7297, '2 Samuel', 10, 22, 51, ' برج خلاص لملكه ، والصانع رحمة لمسيحه ، لداود ونسله إلى الأبد '),
(7298, '2 Samuel', 10, 23, 1, ' فهذه هي كلمات داود الأخيرة : وحي داود بن يسى ، ووحي الرجل القائم في العلا ، مسيح إله يعقوب ، ومرنم إسرائيل الحلو '),
(7299, '2 Samuel', 10, 23, 2, ' روح الرب تكلم بي وكلمته على لساني '),
(7300, '2 Samuel', 10, 23, 3, ' قال إله إسرائيل . إلي تكلم صخرة إسرائيل : إذا تسلط على الناس بار يتسلط بخوف الله '),
(7301, '2 Samuel', 10, 23, 4, ' وكنور الصباح إذا أشرقت الشمس . كعشب من الأرض في صباح صحو مضيء غب المطر '),
(7302, '2 Samuel', 10, 23, 5, ' أليس هكذا بيتي عند الله ؟ لأنه وضع لي عهدا أبديا متقنا في كل شيء ومحفوظا ، أفلا يثبت كل خلاصي وكل مسرتي '),
(7303, '2 Samuel', 10, 23, 6, ' ولكن بني بليعال جميعهم كشوك مطروح ، لأنهم لا يؤخذون بيد '),
(7304, '2 Samuel', 10, 23, 7, ' والرجل الذي يمسهم يتسلح بحديد وعصا رمح ، فيحترقون بالنار في مكانهم '),
(7305, '2 Samuel', 10, 23, 8, ' هذه أسماء الأبطال الذين لداود : يشيب بشبث التحكموني رئيس الثلاثة . هو هز رمحه على ثمان مئة قتلهم دفعة واحدة '),
(7306, '2 Samuel', 10, 23, 9, ' وبعده ألعازار بن دودو بن أخوخي ، أحد الثلاثة الأبطال الذين كانوا مع داود حينما عيروا الفلسطينيين الذين اجتمعوا هناك للحرب وصعد رجال إسرائيل '),
(7307, '2 Samuel', 10, 23, 10, ' أما هو فأقام وضرب الفلسطينيين حتى كلت يده ، ولصقت يده بالسيف ، وصنع الرب خلاصا عظيما في ذلك اليوم ، ورجع الشعب وراءه للنهب فقط '),
(7308, '2 Samuel', 10, 23, 11, ' وبعده شمة بن أجي الهراري . فاجتمع الفلسطينيون جيشا ، وكانت هناك قطعة حقل مملوءة عدسا ، فهرب الشعب من أمام الفلسطينيين '),
(7309, '2 Samuel', 10, 23, 12, ' فوقف في وسط القطعة وأنقذها ، وضرب الفلسطينيين ، فصنع الرب خلاصا عظيما '),
(7310, '2 Samuel', 10, 23, 13, ' ونزل الثلاثة من الثلاثين رئيسا وأتوا في الحصاد إلى داود إلى مغارة عدلام ، وجيش الفلسطينيين نازل في وادي الرفائيين '),
(7311, '2 Samuel', 10, 23, 14, ' وكان داود حينئذ في الحصن ، وحفظة الفلسطينيين حينئذ في بيت لحم '),
(7312, '2 Samuel', 10, 23, 15, ' فتأوه داود وقال : من يسقيني ماء من بئر بيت لحم التي عند الباب '),
(7313, '2 Samuel', 10, 23, 16, ' فشق الأبطال الثلاثة محلة الفلسطينيين واستقوا ماء من بئر بيت لحم التي عند الباب ، وحملوه وأتوا به إلى داود ، فلم يشأ أن يشربه ، بل سكبه للرب '),
(7314, '2 Samuel', 10, 23, 17, ' وقال : حاشا لي يارب أن أفعل ذلك هذا دم الرجال الذين خاطروا بأنفسهم . فلم يشأ أن يشربه . هذا ما فعله الثلاثة الأبطال '),
(7315, '2 Samuel', 10, 23, 18, ' وأبيشاي أخو يوآب ابن صروية هو رئيس ثلاثة . هذا هز رمحه على ثلاث مئة قتلهم ، فكان له اسم بين الثلاثة '),
(7316, '2 Samuel', 10, 23, 19, ' ألم يكرم على الثلاثة فكان لهم رئيسا ، إلا أنه لم يصل إلى الثلاثة الأول '),
(7317, '2 Samuel', 10, 23, 20, ' وبناياهو بن يهوياداع ، ابن ذي بأس ، كثير الأفعال ، من قبصئيل ، هو الذي ضرب أسدي موآب ، وهو الذي نزل وضرب أسدا في وسط جب يوم الثلج '),
(7318, '2 Samuel', 10, 23, 21, ' وهو ضرب رجلا مصريا ذا منظر ، وكان بيد المصري رمح ، فنزل إليه بعصا وخطف الرمح من يد المصري وقتله برمحه '),
(7319, '2 Samuel', 10, 23, 22, ' هذا ما فعله بناياهو بن يهوياداع ، فكان له اسم بين الثلاثة الأبطال '),
(7320, '2 Samuel', 10, 23, 23, ' وأكرم على الثلاثين ، إلا أنه لم يصل إلى الثلاثة . فجعله داود من أصحاب سره '),
(7321, '2 Samuel', 10, 23, 24, ' وعسائيل أخو يوآب كان من الثلاثين ، وألحانان بن دودو من بيت لحم '),
(7322, '2 Samuel', 10, 23, 25, ' وشمة الحرودي ، وأليقا الحرودي '),
(7323, '2 Samuel', 10, 23, 26, ' وحالص الفلطي ، وعيرا بن عقيش التقوعي '),
(7324, '2 Samuel', 10, 23, 27, ' وأبيعزر العناثوثي ، ومبوناي الحوشاتي '),
(7325, '2 Samuel', 10, 23, 28, ' وصلمون الأخوخي ، ومهراي النطوفاتي '),
(7326, '2 Samuel', 10, 23, 29, ' وخالب بن بعنة النطوفاتي ، وإتاي بن ريباي من جبعة بني بنيامين '),
(7327, '2 Samuel', 10, 23, 30, ' وبنايا الفرعتوني ، وهداي من أودية جاعش '),
(7328, '2 Samuel', 10, 23, 31, ' وأبو علبون العرباتي ، وعزموت البرحومي '),
(7329, '2 Samuel', 10, 23, 32, ' وأليحبا الشعلبوني ، ومن بني ياشن : يوناثان '),
(7330, '2 Samuel', 10, 23, 33, ' وشمة الهراري ، وأخيآم بن شارار الأراري '),
(7331, '2 Samuel', 10, 23, 34, ' وأليفلط بن أحسباي ابن المعكي ، وأليعام بن أخيتوفل الجيلوني '),
(7332, '2 Samuel', 10, 23, 35, ' وحصراي الكرملي ، وفعراي الأربي '),
(7333, '2 Samuel', 10, 23, 36, ' ويجآل بن ناثان من صوبة ، وباني الجادي '),
(7334, '2 Samuel', 10, 23, 37, ' وصالق العموني ، ونحراي البئيروتي ، حامل سلاح يوآب بن صروية '),
(7335, '2 Samuel', 10, 23, 38, ' وعيرا اليثري ، وجارب اليثري '),
(7336, '2 Samuel', 10, 23, 39, ' وأوريا الحثي . الجميع سبعة وثلاثون '),
(7337, '2 Samuel', 10, 24, 1, ' وعاد فحمي غضب الرب على إسرائيل ، فأهاج عليهم داود قائلا : امض وأحص إسرائيل ويهوذا '),
(7338, '2 Samuel', 10, 24, 2, ' فقال الملك ليوآب رئيس الجيش الذي عنده : طف في جميع أسباط إسرائيل من دان إلى بئر سبع وعدوا الشعب ، فأعلم عدد الشعب '),
(7339, '2 Samuel', 10, 24, 3, ' فقال يوآب للملك : ليزد الرب إلهك الشعب أمثالهم مئة ضعف ، وعينا سيدي الملك ناظرتان . ولكن لماذا يسر سيدي الملك بهذا الأمر '),
(7340, '2 Samuel', 10, 24, 4, ' فاشتد كلام الملك على يوآب وعلى رؤساء الجيش ، فخرج يوآب ورؤساء الجيش من عند الملك ليعدوا الشعب ، أي إسرائيل '),
(7341, '2 Samuel', 10, 24, 5, ' فعبروا الأردن ونزلوا في عروعير عن يمين المدينة التي في وسط وادي جاد وتجاه يعزير '),
(7342, '2 Samuel', 10, 24, 6, ' وأتوا إلى جلعاد وإلى أرض تحتيم إلى حدشي ، ثم أتوا إلى دان يعن ، واستداروا إلى صيدون '),
(7343, '2 Samuel', 10, 24, 7, ' ثم أتوا إلى حصن صور وجميع مدن الحويين والكنعانيين ، ثم خرجوا إلى جنوبي يهوذا ، إلى بئر سبع '),
(7344, '2 Samuel', 10, 24, 8, ' وطافوا كل الأرض ، وجاءوا في نهاية تسعة أشهر وعشرين يوما إلى أورشليم '),
(7345, '2 Samuel', 10, 24, 9, ' فدفع يوآب جملة عدد الشعب إلى الملك ، فكان إسرائيل ثمان مئة ألف رجل ذي بأس مستل السيف ، ورجال يهوذا خمس مئة ألف رجل '),
(7346, '2 Samuel', 10, 24, 10, ' وضرب داود قلبه بعدما عد الشعب . فقال داود للرب : لقد أخطأت جدا في ما فعلت ، والآن يارب ، أزل إثم عبدك لأني انحمقت جدا '),
(7347, '2 Samuel', 10, 24, 11, ' ولما قام داود صباحا ، كان كلام الرب إلى جاد النبي رائي داود قائلا '),
(7348, '2 Samuel', 10, 24, 12, ' اذهب وقل لداود : هكذا قال الرب : ثلاثة أنا عارض عليك ، فاختر لنفسك واحدا منها فأفعله بك '),
(7349, '2 Samuel', 10, 24, 13, ' فأتى جاد إلى داود وأخبره وقال له : أتأتي عليك سبع سني جوع في أرضك ، أم تهرب ثلاثة أشهر أمام أعدائك وهم يتبعونك ، أم يكون ثلاثة أيام وبأ في أرضك ؟ فالآن اعرف وانظر ماذا أرد جوابا على مرسلي '),
(7350, '2 Samuel', 10, 24, 14, ' فقال داود لجاد : قد ضاق بي الأمر جدا . فلنسقط في يد الرب ، لأن مراحمه كثيرة ولا أسقط في يد إنسان ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(7351, '2 Samuel', 10, 24, 15, ' فجعل الرب وبأ في إسرائيل من الصباح إلى الميعاد ، فمات من الشعب من دان إلى بئر سبع سبعون ألف رجل '),
(7352, '2 Samuel', 10, 24, 16, ' وبسط الملاك يده على أورشليم ليهلكها ، فندم الرب عن الشر ، وقال للملاك المهلك الشعب : كفى الآن رد يدك . وكان ملاك الرب عند بيدر أرونة اليبوسي '),
(7353, '2 Samuel', 10, 24, 17, ' فكلم داود الرب عندما رأى الملاك الضارب الشعب وقال : ها أنا أخطأت ، وأنا أذنبت ، وأما هؤلاء الخراف فماذا فعلوا ؟ فلتكن يدك علي وعلى بيت أبي '),
(7354, '2 Samuel', 10, 24, 18, ' فجاء جاد في ذلك اليوم إلى داود وقال له : اصعد وأقم للرب مذبحا في بيدر أرونة اليبوسي '),
(7355, '2 Samuel', 10, 24, 19, ' فصعد داود حسب كلام جاد كما أمر الرب '),
(7356, '2 Samuel', 10, 24, 20, ' فتطلع أرونة ورأى الملك وعبيده يقبلون إليه ، فخرج أرونة وسجد للملك على وجهه إلى الأرض '),
(7357, '2 Samuel', 10, 24, 21, ' وقال أرونة : لماذا جاء سيدي الملك إلى عبده ؟  . فقال داود : لأشتري منك البيدر لكي أبني مذبحا للرب فتكف الضربة عن الشعب '),
(7358, '2 Samuel', 10, 24, 22, ' فقال أرونة لداود : فليأخذه سيدي الملك ويصعد ما يحسن في عينيه . انظر . البقر للمحرقة ، والنوارج وأدوات البقر حطبا '),
(7359, '2 Samuel', 10, 24, 23, ' الكل دفعه أرونة المالك إلى الملك . وقال أرونة للملك : الرب إلهك يرضى عنك '),
(7360, '2 Samuel', 10, 24, 24, ' فقال الملك لأرونة : لا ، بل أشتري منك بثمن ، ولا أصعد للرب إلهي محرقات مجانية . فاشترى داود البيدر والبقر بخمسين شاقلا من الفضة '),
(7361, '2 Samuel', 10, 24, 25, ' وبنى داود هناك مذبحا للرب وأصعد محرقات وذبائح سلامة ، واستجاب الرب من أجل الأرض ، فكفت الضربة عن إسرائيل '),
(7362, '2 Thessalonians', 53, 1, 1, ' بولس وسلوانس وتيموثاوس ، إلى كنيسة التسالونيكيين ، في الله أبينا والرب يسوع المسيح '),
(7363, '2 Thessalonians', 53, 1, 2, ' نعمة لكم وسلام من الله أبينا والرب يسوع المسيح '),
(7364, '2 Thessalonians', 53, 1, 3, ' ينبغي لنا أن نشكر الله كل حين من جهتكم أيها الإخوة كما يحق ، لأن إيمانكم ينمو كثيرا ، ومحبة كل واحد منكم جميعا بعضكم لبعض تزداد '),
(7365, '2 Thessalonians', 53, 1, 4, ' حتى إننا نحن أنفسنا نفتخر بكم في كنائس الله ، من أجل صبركم وإيمانكم في جميع اضطهاداتكم والضيقات التي تحتملونها '),
(7366, '2 Thessalonians', 53, 1, 5, ' بينة على قضاء الله العادل ، أنكم تؤهلون لملكوت الله الذي لأجله تتألمون أيضا '),
(7367, '2 Thessalonians', 53, 1, 6, ' إذ هو عادل عند الله أن الذين يضايقونكم يجازيهم ضيقا '),
(7368, '2 Thessalonians', 53, 1, 7, ' وإياكم الذين تتضايقون راحة معنا ، عند استعلان الرب يسوع من السماء مع ملائكة قوته '),
(7369, '2 Thessalonians', 53, 1, 8, ' في نار لهيب ، معطيا نقمة للذين لا يعرفون الله ، والذين لا يطيعون إنجيل ربنا يسوع المسيح '),
(7370, '2 Thessalonians', 53, 1, 9, ' الذين سيعاقبون بهلاك أبدي من وجه الرب ومن مجد قوته '),
(7371, '2 Thessalonians', 53, 1, 10, ' متى جاء ليتمجد في قديسيه ويتعجب منه في جميع المؤمنين . لأن شهادتنا عندكم صدقت في ذلك اليوم '),
(7372, '2 Thessalonians', 53, 1, 11, ' الأمر الذي لأجله نصلي أيضا كل حين من جهتكم : أن يؤهلكم إلهنا للدعوة ، ويكمل كل مسرة الصلاح وعمل الإيمان بقوة '),
(7373, '2 Thessalonians', 53, 1, 12, ' لكي يتمجد اسم ربنا يسوع المسيح فيكم ، وأنتم فيه ، بنعمة إلهنا والرب يسوع المسيح '),
(7374, '2 Thessalonians', 53, 2, 1, ' ثم نسألكم أيها الإخوة من جهة مجيء ربنا يسوع المسيح واجتماعنا إليه '),
(7375, '2 Thessalonians', 53, 2, 2, ' أن لا تتزعزعوا سريعا عن ذهنكم ، ولا ترتاعوا ، لا بروح ولا بكلمة ولا برسالة كأنها منا : أي أن يوم المسيح قد حضر '),
(7376, '2 Thessalonians', 53, 2, 3, ' لا يخدعنكم أحد على طريقة ما ، لأنه لا يأتي إن لم يأت الارتداد أولا ، ويستعلن إنسان الخطية ، ابن الهلاك '),
(7377, '2 Thessalonians', 53, 2, 4, ' المقاوم والمرتفع على كل ما يدعى إلها أو معبودا ، حتى إنه يجلس في هيكل الله كإله ، مظهرا نفسه أنه إله '),
(7378, '2 Thessalonians', 53, 2, 5, ' أما تذكرون أني وأنا بعد عندكم ، كنت أقول لكم هذا '),
(7379, '2 Thessalonians', 53, 2, 6, ' والآن تعلمون ما يحجز حتى يستعلن في وقته '),
(7380, '2 Thessalonians', 53, 2, 7, ' لأن سر الإثم الآن يعمل فقط ، إلى أن يرفع من الوسط الذي يحجز الآن '),
(7381, '2 Thessalonians', 53, 2, 8, ' وحينئذ سيستعلن الأثيم ، الذي الرب يبيده بنفخة فمه ، ويبطله بظهور مجيئه '),
(7382, '2 Thessalonians', 53, 2, 9, ' الذي مجيئه بعمل الشيطان ، بكل قوة ، وبآيات وعجائب كاذبة '),
(7383, '2 Thessalonians', 53, 2, 10, ' وبكل خديعة الإثم ، في الهالكين ، لأنهم لم يقبلوا محبة الحق حتى يخلصوا '),
(7384, '2 Thessalonians', 53, 2, 11, ' ولأجل هذا سيرسل إليهم الله عمل الضلال ، حتى يصدقوا الكذب '),
(7385, '2 Thessalonians', 53, 2, 12, ' لكي يدان جميع الذين لم يصدقوا الحق ، بل سروا بالإثم '),
(7386, '2 Thessalonians', 53, 2, 13, ' وأما نحن فينبغي لنا أن نشكر الله كل حين لأجلكم أيها الإخوة المحبوبون من الرب ، أن الله اختاركم من البدء للخلاص ، بتقديس الروح وتصديق الحق '),
(7387, '2 Thessalonians', 53, 2, 14, ' الأمر الذي دعاكم إليه بإنجيلنا ، لاقتناء مجد ربنا يسوع المسيح '),
(7388, '2 Thessalonians', 53, 2, 15, ' فاثبتوا إذا أيها الإخوة وتمسكوا بالتعاليم التي تعلمتموها ، سواء كان بالكلام أم برسالتنا '),
(7389, '2 Thessalonians', 53, 2, 16, ' وربنا نفسه يسوع المسيح ، والله أبونا الذي أحبنا وأعطانا عزاء أبديا ورجاء صالحا بالنعمة '),
(7390, '2 Thessalonians', 53, 2, 17, ' يعزي قلوبكم ويثبتكم في كل كلام وعمل صالح '),
(7391, '2 Thessalonians', 53, 3, 1, ' أخيرا أيها الإخوة صلوا لأجلنا ، لكي تجري كلمة الرب وتتمجد ، كما عندكم أيضا '),
(7392, '2 Thessalonians', 53, 3, 2, ' ولكي ننقذ من الناس الأردياء الأشرار . لأن الإيمان ليس للجميع '),
(7393, '2 Thessalonians', 53, 3, 3, ' أمين هو الرب الذي سيثبتكم ويحفظكم من الشرير '),
(7394, '2 Thessalonians', 53, 3, 4, ' ونثق بالرب من جهتكم أنكم تفعلون ما نوصيكم به وستفعلون أيضا '),
(7395, '2 Thessalonians', 53, 3, 5, ' والرب يهدي قلوبكم إلى محبة الله ، وإلى صبر المسيح '),
(7396, '2 Thessalonians', 53, 3, 6, ' ثم نوصيكم أيها الإخوة ، باسم ربنا يسوع المسيح ، أن تتجنبوا كل أخ يسلك بلا ترتيب ، وليس حسب التعليم الذي أخذه منا '),
(7397, '2 Thessalonians', 53, 3, 7, ' إذ أنتم تعرفون كيف يجب أن يتمثل بنا ، لأننا لم نسلك بلا ترتيب بينكم '),
(7398, '2 Thessalonians', 53, 3, 8, ' ولا أكلنا خبزا مجانا من أحد ، بل كنا نشتغل بتعب وكد ليلا ونهارا ، لكي لا نثقل على أحد منكم '),
(7399, '2 Thessalonians', 53, 3, 9, ' ليس أن لا سلطان لنا ، بل لكي نعطيكم أنفسنا قدوة حتى تتمثلوا بنا '),
(7400, '2 Thessalonians', 53, 3, 10, ' فإننا أيضا حين كنا عندكم ، أوصيناكم بهذا : أنه إن كان أحد لا يريد أن يشتغل فلا يأكل أيضا '),
(7401, '2 Thessalonians', 53, 3, 11, ' لأننا نسمع أن قوما يسلكون بينكم بلا ترتيب ، لا يشتغلون شيئا بل هم فضوليون '),
(7402, '2 Thessalonians', 53, 3, 12, ' فمثل هؤلاء نوصيهم ونعظهم بربنا يسوع المسيح أن يشتغلوا بهدوء ، ويأكلوا خبز أنفسهم '),
(7403, '2 Thessalonians', 53, 3, 13, ' أما أنتم أيها الإخوة فلا تفشلوا في عمل الخير '),
(7404, '2 Thessalonians', 53, 3, 14, ' وإن كان أحد لا يطيع كلامنا بالرسالة ، فسموا هذا ولا تخالطوه لكي يخجل '),
(7405, '2 Thessalonians', 53, 3, 15, ' ولكن لا تحسبوه كعدو ، بل أنذروه كأخ '),
(7406, '2 Thessalonians', 53, 3, 16, ' ورب السلام نفسه يعطيكم السلام دائما من كل وجه . الرب مع جميعكم '),
(7407, '2 Thessalonians', 53, 3, 17, ' السلام بيدي أنا بولس ، الذي هو علامة في كل رسالة . هكذا أنا أكتب '),
(7408, '2 Thessalonians', 53, 3, 18, ' نعمة ربنا يسوع المسيح مع جميعكم . آمين '),
(7409, '2 Timothy', 55, 1, 1, ' بولس ، رسول يسوع المسيح بمشيئة الله ، لأجل وعد الحياة التي في يسوع المسيح '),
(7410, '2 Timothy', 55, 1, 2, ' إلى تيموثاوس الابن الحبيب : نعمة ورحمة وسلام من الله الآب والمسيح يسوع ربنا '),
(7411, '2 Timothy', 55, 1, 3, ' إني أشكر الله الذي أعبده من أجدادي بضمير طاهر ، كما أذكرك بلا انقطاع في طلباتي ليلا ونهارا '),
(7412, '2 Timothy', 55, 1, 4, ' مشتاقا أن أراك ، ذاكرا دموعك لكي أمتلئ فرحا '),
(7413, '2 Timothy', 55, 1, 5, ' إذ أتذكر الإيمان العديم الرياء الذي فيك ، الذي سكن أولا في جدتك لوئيس وأمك أفنيكي ، ولكني موقن أنه فيك أيضا '),
(7414, '2 Timothy', 55, 1, 6, ' فلهذا السبب أذكرك أن تضرم أيضا موهبة الله التي فيك بوضع يدي '),
(7415, '2 Timothy', 55, 1, 7, ' لأن الله لم يعطنا روح الفشل ، بل روح القوة والمحبة والنصح '),
(7416, '2 Timothy', 55, 1, 8, ' فلا تخجل بشهادة ربنا ، ولا بي أنا أسيره ، بل اشترك في احتمال المشقات لأجل الإنجيل بحسب قوة الله '),
(7417, '2 Timothy', 55, 1, 9, ' الذي خلصنا ودعانا دعوة مقدسة ، لا بمقتضى أعمالنا ، بل بمقتضى القصد والنعمة التي أعطيت لنا في المسيح يسوع قبل الأزمنة الأزلية '),
(7418, '2 Timothy', 55, 1, 10, ' وإنما أظهرت الآن بظهور مخلصنا يسوع المسيح ، الذي أبطل الموت وأنار الحياة والخلود بواسطة الإنجيل '),
(7419, '2 Timothy', 55, 1, 11, ' الذي جعلت أنا له كارزا ورسولا ومعلما للأمم '),
(7420, '2 Timothy', 55, 1, 12, ' لهذا السبب أحتمل هذه الأمور أيضا . لكنني لست أخجل ، لأنني عالم بمن آمنت ، وموقن أنه قادر أن يحفظ وديعتي إلى ذلك اليوم '),
(7421, '2 Timothy', 55, 1, 13, ' تمسك بصورة الكلام الصحيح الذي سمعته مني ، في الإيمان والمحبة التي في المسيح يسوع '),
(7422, '2 Timothy', 55, 1, 14, ' احفظ الوديعة الصالحة بالروح القدس الساكن فينا '),
(7423, '2 Timothy', 55, 1, 15, ' أنت تعلم هذا أن جميع الذين في أسيا ارتدوا عني ، الذين منهم فيجلس وهرموجانس '),
(7424, '2 Timothy', 55, 1, 16, ' ليعط الرب رحمة لبيت أنيسيفورس ، لأنه مرارا كثيرة أراحني ولم يخجل بسلسلتي '),
(7425, '2 Timothy', 55, 1, 17, ' بل لما كان في رومية ، طلبني بأوفر اجتهاد فوجدني '),
(7426, '2 Timothy', 55, 1, 18, ' ليعطه الرب أن يجد رحمة من الرب في ذلك اليوم . وكل ما كان يخدم في أفسس أنت تعرفه جيدا '),
(7427, '2 Timothy', 55, 2, 1, ' فتقو أنت يا ابني بالنعمة التي في المسيح يسوع '),
(7428, '2 Timothy', 55, 2, 2, ' وما سمعته مني بشهود كثيرين ، أودعه أناسا أمناء ، يكونون أكفاء أن يعلموا آخرين أيضا '),
(7429, '2 Timothy', 55, 2, 3, ' فاشترك أنت في احتمال المشقات كجندي صالح ليسوع المسيح '),
(7430, '2 Timothy', 55, 2, 4, ' ليس أحد وهو يتجند يرتبك بأعمال الحياة لكي يرضي من جنده '),
(7431, '2 Timothy', 55, 2, 5, ' وأيضا إن كان أحد يجاهد ، لا يكلل إن لم يجاهد قانونيا '),
(7432, '2 Timothy', 55, 2, 6, ' يجب أن الحراث الذي يتعب ، يشترك هو أولا في الأثمار '),
(7433, '2 Timothy', 55, 2, 7, ' افهم ما أقول . فليعطك الرب فهما في كل شيء '),
(7434, '2 Timothy', 55, 2, 8, ' اذكر يسوع المسيح المقام من الأموات ، من نسل داود بحسب إنجيلي '),
(7435, '2 Timothy', 55, 2, 9, ' الذي فيه أحتمل المشقات حتى القيود كمذنب . لكن كلمة الله لا تقيد '),
(7436, '2 Timothy', 55, 2, 10, ' لأجل ذلك أنا أصبر على كل شيء لأجل المختارين ، لكي يحصلوا هم أيضا على الخلاص الذي في المسيح يسوع ، مع مجد أبدي '),
(7437, '2 Timothy', 55, 2, 11, ' صادقة هي الكلمة : أنه إن كنا قد متنا معه فسنحيا أيضا معه '),
(7438, '2 Timothy', 55, 2, 12, ' إن كنا نصبر فسنملك أيضا معه . إن كنا ننكره فهو أيضا سينكرنا '),
(7439, '2 Timothy', 55, 2, 13, ' إن كنا غير أمناء فهو يبقى أمينا ، لن يقدر أن ينكر نفسه '),
(7440, '2 Timothy', 55, 2, 14, ' فكر بهذه الأمور ، مناشدا قدام الرب أن لا يتماحكوا بالكلام . الأمر غير النافع لشيء ، لهدم السامعين '),
(7441, '2 Timothy', 55, 2, 15, ' اجتهد أن تقيم نفسك لله مزكى ، عاملا لا يخزى ، مفصلا كلمة الحق بالاستقامة '),
(7442, '2 Timothy', 55, 2, 16, ' وأما الأقوال الباطلة الدنسة فاجتنبها ، لأنهم يتقدمون إلى أكثر فجور '),
(7443, '2 Timothy', 55, 2, 17, ' وكلمتهم ترعى كآكلة . الذين منهم هيمينايس وفيليتس '),
(7444, '2 Timothy', 55, 2, 18, ' اللذان زاغا عن الحق ، قائلين : إن القيامة قد صارت فيقلبان إيمان قوم '),
(7445, '2 Timothy', 55, 2, 19, ' ولكن أساس الله الراسخ قد ثبت ، إذ له هذا الختم : يعلم الرب الذين هم له . وليتجنب الإثم كل من يسمي اسم المسيح '),
(7446, '2 Timothy', 55, 2, 20, ' ولكن في بيت كبير ليس آنية من ذهب وفضة فقط ، بل من خشب وخزف أيضا ، وتلك للكرامة وهذه للهوان '),
(7447, '2 Timothy', 55, 2, 21, ' فإن طهر أحد نفسه من هذه ، يكون إناء للكرامة ، مقدسا ، نافعا للسيد ، مستعدا لكل عمل صالح '),
(7448, '2 Timothy', 55, 2, 22, ' أما الشهوات الشبابية فاهرب منها ، واتبع البر والإيمان والمحبة والسلام مع الذين يدعون الرب من قلب نقي '),
(7449, '2 Timothy', 55, 2, 23, ' والمباحثات الغبية والسخيفة اجتنبها ، عالما أنها تولد خصومات '),
(7450, '2 Timothy', 55, 2, 24, ' وعبد الرب لا يجب أن يخاصم ، بل يكون مترفقا بالجميع ، صالحا للتعليم ، صبورا على المشقات '),
(7451, '2 Timothy', 55, 2, 25, ' مؤدبا بالوداعة المقاومين ، عسى أن يعطيهم الله توبة لمعرفة الحق '),
(7452, '2 Timothy', 55, 2, 26, ' فيستفيقوا من فخ إبليس إذ قد اقتنصهم لإرادته '),
(7453, '2 Timothy', 55, 3, 1, ' ولكن اعلم هذا أنه في الأيام الأخيرة ستأتي أزمنة صعبة '),
(7454, '2 Timothy', 55, 3, 2, ' لأن الناس يكونون محبين لأنفسهم ، محبين للمال ، متعظمين ، مستكبرين ، مجدفين ، غير طائعين لوالديهم ، غير شاكرين ، دنسين '),
(7455, '2 Timothy', 55, 3, 3, ' بلا حنو ، بلا رضى ، ثالبين ، عديمي النزاهة ، شرسين ، غير محبين للصلاح '),
(7456, '2 Timothy', 55, 3, 4, ' خائنين ، مقتحمين ، متصلفين ، محبين للذات دون محبة لله '),
(7457, '2 Timothy', 55, 3, 5, ' لهم صورة التقوى ، ولكنهم منكرون قوتها . فأعرض عن هؤلاء '),
(7458, '2 Timothy', 55, 3, 6, ' فإنه من هؤلاء هم الذين يدخلون البيوت ، ويسبون نسيات محملات خطايا ، منساقات بشهوات مختلفة '),
(7459, '2 Timothy', 55, 3, 7, ' يتعلمن في كل حين ، ولا يستطعن أن يقبلن إلى معرفة الحق أبدا '),
(7460, '2 Timothy', 55, 3, 8, ' وكما قاوم ينيس ويمبريس موسى ، كذلك هؤلاء أيضا يقاومون الحق . أناس فاسدة أذهانهم ، ومن جهة الإيمان مرفوضون '),
(7461, '2 Timothy', 55, 3, 9, ' لكنهم لا يتقدمون أكثر ، لأن حمقهم سيكون واضحا للجميع ، كما كان حمق ذينك أيضا '),
(7462, '2 Timothy', 55, 3, 10, ' وأما أنت فقد تبعت تعليمي ، وسيرتي ، وقصدي ، وإيماني ، وأناتي ، ومحبتي ، وصبري '),
(7463, '2 Timothy', 55, 3, 11, ' واضطهاداتي ، وآلامي ، مثل ما أصابني في أنطاكية وإيقونية ولسترة . أية اضطهادات احتملت ومن الجميع أنقذني الرب '),
(7464, '2 Timothy', 55, 3, 12, ' وجميع الذين يريدون أن يعيشوا بالتقوى في المسيح يسوع يضطهدون '),
(7465, '2 Timothy', 55, 3, 13, ' ولكن الناس الأشرار المزورين سيتقدمون إلى أردأ ، مضلين ومضلين '),
(7466, '2 Timothy', 55, 3, 14, ' وأما أنت فاثبت على ما تعلمت وأيقنت ، عارفا ممن تعلمت '),
(7467, '2 Timothy', 55, 3, 15, ' وأنك منذ الطفولية تعرف الكتب المقدسة ، القادرة أن تحكمك للخلاص ، بالإيمان الذي في المسيح يسوع '),
(7468, '2 Timothy', 55, 3, 16, ' كل الكتاب هو موحى به من الله ، ونافع للتعليم والتوبيخ ، للتقويم والتأديب الذي في البر '),
(7469, '2 Timothy', 55, 3, 17, ' لكي يكون إنسان الله كاملا ، متأهبا لكل عمل صالح '),
(7470, '2 Timothy', 55, 4, 1, ' أنا أناشدك إذا أمام الله والرب يسوع المسيح ، العتيد أن يدين الأحياء والأموات ، عند ظهوره وملكوته '),
(7471, '2 Timothy', 55, 4, 2, ' اكرز بالكلمة . اعكف على ذلك في وقت مناسب وغير مناسب . وبخ ، انتهر ، عظ بكل أناة وتعليم '),
(7472, '2 Timothy', 55, 4, 3, ' لأنه سيكون وقت لا يحتملون فيه التعليم الصحيح ، بل حسب شهواتهم الخاصة يجمعون لهم معلمين مستحكة مسامعهم '),
(7473, '2 Timothy', 55, 4, 4, ' فيصرفون مسامعهم عن الحق ، وينحرفون إلى الخرافات '),
(7474, '2 Timothy', 55, 4, 5, ' وأما أنت فاصح في كل شيء . احتمل المشقات . اعمل عمل المبشر . تمم خدمتك '),
(7475, '2 Timothy', 55, 4, 6, ' فإني أنا الآن أسكب سكيبا ، ووقت انحلالي قد حضر '),
(7476, '2 Timothy', 55, 4, 7, ' قد جاهدت الجهاد الحسن ، أكملت السعي ، حفظت الإيمان '),
(7477, '2 Timothy', 55, 4, 8, ' وأخيرا قد وضع لي إكليل البر ، الذي يهبه لي في ذلك اليوم ، الرب الديان العادل ، وليس لي فقط ، بل لجميع الذين يحبون ظهوره أيضا '),
(7478, '2 Timothy', 55, 4, 9, ' بادر أن تجيء إلي سريعا '),
(7479, '2 Timothy', 55, 4, 10, ' لأن ديماس قد تركني إذ أحب العالم الحاضر وذهب إلى تسالونيكي ، وكريسكيس إلى غلاطية ، وتيطس إلى دلماطية '),
(7480, '2 Timothy', 55, 4, 11, ' لوقا وحده معي . خذ مرقس وأحضره معك لأنه نافع لي للخدمة '),
(7481, '2 Timothy', 55, 4, 12, ' أما تيخيكس فقد أرسلته إلى أفسس '),
(7482, '2 Timothy', 55, 4, 13, ' الرداء الذي تركته في ترواس عند كاربس ، أحضره متى جئت ، والكتب أيضا ولاسيما الرقوق '),
(7483, '2 Timothy', 55, 4, 14, ' إسكندر النحاس أظهر لي شرورا كثيرة . ليجازه الرب حسب أعماله '),
(7484, '2 Timothy', 55, 4, 15, ' فاحتفظ منه أنت أيضا ، لأنه قاوم أقوالنا جدا '),
(7485, '2 Timothy', 55, 4, 16, ' في احتجاجي الأول لم يحضر أحد معي ، بل الجميع تركوني . لا يحسب عليهم '),
(7486, '2 Timothy', 55, 4, 17, ' ولكن الرب وقف معي وقواني ، لكي تتم بي الكرازة ، ويسمع جميع الأمم ، فأنقذت من فم الأسد '),
(7487, '2 Timothy', 55, 4, 18, ' وسينقذني الرب من كل عمل رديء ويخلصني لملكوته السماوي . الذي له المجد إلى دهر الدهور . آمين '),
(7488, '2 Timothy', 55, 4, 19, ' سلم على فرسكا وأكيلا وبيت أنيسيفورس '),
(7489, '2 Timothy', 55, 4, 20, ' أراستس بقي في كورنثوس . وأما تروفيمس فتركته في ميليتس مريضا '),
(7490, '2 Timothy', 55, 4, 21, ' بادر أن تجيء قبل الشتاء . يسلم عليك أفبولس وبوديس ولينس وكلافدية والإخوة جميعا '),
(7491, '2 Timothy', 55, 4, 22, ' الرب يسوع المسيح مع روحك . النعمة معكم . آمين '),
(7492, '3 John', 64, 1, 1, ' الشيخ ، إلى غايس الحبيب الذي أنا أحبه بالحق '),
(7493, '3 John', 64, 1, 2, ' أيها الحبيب ، في كل شيء أروم أن تكون ناجحا وصحيحا ، كما أن نفسك ناجحة '),
(7494, '3 John', 64, 1, 3, ' لأني فرحت جدا إذ حضر إخوة وشهدوا بالحق الذي فيك ، كما أنك تسلك بالحق '),
(7495, '3 John', 64, 1, 4, ' ليس لي فرح أعظم من هذا : أن أسمع عن أولادي أنهم يسلكون بالحق '),
(7496, '3 John', 64, 1, 5, ' أيها الحبيب ، أنت تفعل بالأمانة كل ما تصنعه إلى الإخوة وإلى الغرباء '),
(7497, '3 John', 64, 1, 6, ' الذين شهدوا بمحبتك أمام الكنيسة . الذين تفعل حسنا إذا شيعتهم كما يحق لله '),
(7498, '3 John', 64, 1, 7, ' لأنهم من أجل اسمه خرجوا ، وهم لا يأخذون شيئا من الأمم '),
(7499, '3 John', 64, 1, 8, ' فنحن ينبغي لنا أن نقبل أمثال هؤلاء ، لكي نكون عاملين معهم بالحق '),
(7500, '3 John', 64, 1, 9, ' كتبت إلى الكنيسة ، ولكن ديوتريفس - الذي يحب أن يكون الأول بينهم - لا يقبلنا '),
(7501, '3 John', 64, 1, 10, ' من أجل ذلك ، إذا جئت فسأذكره بأعماله التي يعملها ، هاذرا علينا بأقوال خبيثة . وإذ هو غير مكتف بهذه ، لا يقبل الإخوة ، ويمنع أيضا الذين يريدون ، ويطردهم من الكنيسة '),
(7502, '3 John', 64, 1, 11, ' أيها الحبيب ، لا تتمثل بالشر بل بالخير ، لأن من يصنع الخير هو من الله ، ومن يصنع الشر ، فلم يبصر الله '),
(7503, '3 John', 64, 1, 12, ' ديمتريوس مشهود له من الجميع ومن الحق نفسه ، ونحن أيضا نشهد ، وأنتم تعلمون أن شهادتنا هي صادقة '),
(7504, '3 John', 64, 1, 13, ' وكان لي كثير لأكتبه ، لكنني لست أريد أن أكتب إليك بحبر وقلم '),
(7505, '3 John', 64, 1, 14, ' ولكنني أرجو أن أراك عن قريب فنتكلم فما لفم '),
(7506, '3 John', 64, 1, 15, ' سلام لك . يسلم عليك الأحباء . سلم على الأحباء بأسمائهم '),
(7507, 'Acts', 44, 10, 45, ' فاندهش المؤمنون الذين من أهل الختان ، كل من جاء مع بطرس ، لأن موهبة الروح القدس قد انسكبت على الأمم أيضا '),
(7508, 'Acts', 44, 10, 46, ' لأنهم كانوا يسمعونهم يتكلمون بألسنة ويعظمون الله . حينئذ أجاب بطرس '),
(7509, 'Acts', 44, 10, 47, ' أترى يستطيع أحد أن يمنع الماء حتى لا يعتمد هؤلاء الذين قبلوا الروح القدس كما نحن أيضا '),
(7510, 'Acts', 44, 10, 48, ' وأمر أن يعتمدوا باسم الرب . حينئذ سألوه أن يمكث أياما '),
(7511, 'Acts', 44, 11, 1, ' فسمع الرسل والإخوة الذين كانوا في اليهودية أن الأمم أيضا قبلوا كلمة الله '),
(7512, 'Acts', 44, 11, 2, ' ولما صعد بطرس إلى أورشليم ، خاصمه الذين من أهل الختان '),
(7513, 'Acts', 44, 11, 3, ' قائلين : إنك دخلت إلى رجال ذوي غلفة وأكلت معهم '),
(7514, 'Acts', 44, 11, 4, ' فابتدأ بطرس يشرح لهم بالتتابع قائلا '),
(7515, 'Acts', 44, 11, 5, ' أنا كنت في مدينة يافا أصلي ، فرأيت في غيبة رؤيا : إناء نازلا مثل ملاءة عظيمة مدلاة بأربعة أطراف من السماء ، فأتى إلي '),
(7516, 'Acts', 44, 11, 6, ' فتفرست فيه متأملا ، فرأيت دواب الأرض والوحوش والزحافات وطيور السماء '),
(7517, 'Acts', 44, 11, 7, ' وسمعت صوتا قائلا لي : قم يا بطرس ، اذبح وكل '),
(7518, 'Acts', 44, 11, 8, ' فقلت : كلا يا رب لأنه لم يدخل فمي قط دنس أو نجس '),
(7519, 'Acts', 44, 11, 9, ' فأجابني صوت ثانية من السماء : ما طهره الله لا تنجسه أنت '),
(7520, 'Acts', 44, 11, 10, ' وكان هذا على ثلاث مرات . ثم انتشل الجميع إلى السماء أيضا '),
(7521, 'Acts', 44, 11, 11, ' وإذا ثلاثة رجال قد وقفوا للوقت عند البيت الذي كنت فيه ، مرسلين إلي من قيصرية '),
(7522, 'Acts', 44, 11, 12, ' فقال لي الروح أن أذهب معهم غير مرتاب في شيء . وذهب معي أيضا هؤلاء الإخوة الستة . فدخلنا بيت الرجل '),
(7523, 'Acts', 44, 11, 13, ' فأخبرنا كيف رأى الملاك في بيته قائما وقائلا له : أرسل إلى يافا رجالا ، واستدع سمعان الملقب بطرس '),
(7524, 'Acts', 44, 11, 14, ' وهو يكلمك كلاما به تخلص أنت وكل بيتك '),
(7525, 'Acts', 44, 11, 15, ' فلما ابتدأت أتكلم ، حل الروح القدس عليهم كما علينا أيضا في البداءة '),
(7526, 'Acts', 44, 11, 16, ' فتذكرت كلام الرب كيف قال : إن يوحنا عمد بماء وأما أنتم فستعمدون بالروح القدس '),
(7527, 'Acts', 44, 11, 17, ' فإن كان الله قد أعطاهم الموهبة كما لنا أيضا بالسوية مؤمنين بالرب يسوع المسيح ، فمن أنا ؟ أقادر أن أمنع الله '),
(7528, 'Acts', 44, 11, 18, ' فلما سمعوا ذلك سكتوا ، وكانوا يمجدون الله قائلين : إذا أعطى الله الأمم أيضا التوبة للحياة '),
(7529, 'Acts', 44, 11, 19, ' أما الذين تشتتوا من جراء الضيق الذي حصل بسبب استفانوس فاجتازوا إلى فينيقية وقبرس وأنطاكية ، وهم لا يكلمون أحدا بالكلمة إلا اليهود فقط '),
(7530, 'Acts', 44, 11, 20, ' ولكن كان منهم قوم ، وهم رجال قبرسيون وقيروانيون ، الذين لما دخلوا أنطاكية كانوا يخاطبون اليونانيين مبشرين بالرب يسوع '),
(7531, 'Acts', 44, 11, 21, ' وكانت يد الرب معهم ، فآمن عدد كثير ورجعوا إلى الرب '),
(7532, 'Acts', 44, 11, 22, ' فسمع الخبر عنهم في آذان الكنيسة التي في أورشليم ، فأرسلوا برنابا لكي يجتاز إلى أنطاكية '),
(7533, 'Acts', 44, 11, 23, ' الذي لما أتى ورأى نعمة الله فرح ، ووعظ الجميع أن يثبتوا في الرب بعزم القلب '),
(7534, 'Acts', 44, 11, 24, ' لأنه كان رجلا صالحا وممتلئا من الروح القدس والإيمان . فانضم إلى الرب جمع غفير '),
(7535, 'Acts', 44, 11, 25, ' ثم خرج برنابا إلى طرسوس ليطلب شاول . ولما وجده جاء به إلى أنطاكية '),
(7536, 'Acts', 44, 11, 26, ' فحدث أنهما اجتمعا في الكنيسة سنة كاملة وعلما جمعا غفيرا . ودعي التلاميذ مسيحيين في أنطاكية أولا '),
(7537, 'Acts', 44, 11, 27, ' وفي تلك الأيام انحدر أنبياء من أورشليم إلى أنطاكية '),
(7538, 'Acts', 44, 11, 28, ' وقام واحد منهم اسمه أغابوس ، وأشار بالروح أن جوعا عظيما كان عتيدا أن يصير على جميع المسكونة ، الذي صار أيضا في أيام كلوديوس قيصر '),
(7539, 'Acts', 44, 11, 29, ' فحتم التلاميذ حسبما تيسر لكل منهم أن يرسل كل واحد شيئا ، خدمة إلى الإخوة الساكنين في اليهودية '),
(7540, 'Acts', 44, 11, 30, ' ففعلوا ذلك مرسلين إلى المشايخ بيد برنابا وشاول '),
(7541, 'Acts', 44, 12, 1, ' وفي ذلك الوقت مد هيرودس الملك يديه ليسيئ إلى أناس من الكنيسة '),
(7542, 'Acts', 44, 12, 2, ' فقتل يعقوب أخا يوحنا بالسيف '),
(7543, 'Acts', 44, 12, 3, ' وإذ رأى أن ذلك يرضي اليهود ، عاد فقبض على بطرس أيضا . وكانت أيام الفطير '),
(7544, 'Acts', 44, 12, 4, ' ولما أمسكه وضعه في السجن ، مسلما إياه إلى أربعة أرابع من العسكر ليحرسوه ، ناويا أن يقدمه بعد الفصح إلى الشعب '),
(7545, 'Acts', 44, 12, 5, ' فكان بطرس محروسا في السجن ، وأما الكنيسة فكانت تصير منها صلاة بلجاجة إلى الله من أجله '),
(7546, 'Acts', 44, 12, 6, ' ولما كان هيرودس مزمعا أن يقدمه ، كان بطرس في تلك الليلة نائما بين عسكريين مربوطا بسلسلتين ، وكان قدام الباب حراس يحرسون السجن '),
(7547, 'Acts', 44, 12, 7, ' وإذا ملاك الرب أقبل ، ونور أضاء في البيت ، فضرب جنب بطرس وأيقظه قائلا : قم عاجلا . فسقطت السلسلتان من يديه '),
(7548, 'Acts', 44, 12, 8, ' وقال له الملاك : تمنطق والبس نعليك . ففعل هكذا . فقال له : البس رداءك واتبعني '),
(7549, 'Acts', 44, 12, 9, ' فخرج يتبعه . وكان لا يعلم أن الذي جرى بواسطة الملاك هو حقيقي ، بل يظن أنه ينظر رؤيا '),
(7550, 'Acts', 44, 12, 10, ' فجازا المحرس الأول والثاني ، وأتيا إلى باب الحديد الذي يؤدي إلى المدينة ، فانفتح لهما من ذاته ، فخرجا وتقدما زقاقا واحدا ، وللوقت فارقه الملاك '),
(7551, 'Acts', 44, 12, 11, ' فقال بطرس ، وهو قد رجع إلى نفسه : الآن علمت يقينا أن الرب أرسل ملاكه وأنقذني من يد هيرودس ، ومن كل انتظار شعب اليهود '),
(7552, 'Acts', 44, 12, 12, ' ثم جاء وهو منتبه إلى بيت مريم أم يوحنا الملقب مرقس ، حيث كان كثيرون مجتمعين وهم يصلون '),
(7553, 'Acts', 44, 12, 13, ' فلما قرع بطرس باب الدهليز جاءت جارية اسمها رودا لتسمع '),
(7554, 'Acts', 44, 12, 14, ' فلما عرفت صوت بطرس لم تفتح الباب من الفرح ، بل ركضت إلى داخل وأخبرت أن بطرس واقف قدام الباب '),
(7555, 'Acts', 44, 12, 15, ' فقالوا لها : أنت تهذين . وأما هي فكانت تؤكد أن هكذا هو . فقالوا : إنه ملاكه '),
(7556, 'Acts', 44, 12, 16, ' وأما بطرس فلبث يقرع . فلما فتحوا ورأوه اندهشوا '),
(7557, 'Acts', 44, 12, 17, ' فأشار إليهم بيده ليسكتوا ، وحدثهم كيف أخرجه الرب من السجن . وقال : أخبروا يعقوب والإخوة بهذا . ثم خرج وذهب إلى موضع آخر '),
(7558, 'Acts', 44, 12, 18, ' فلما صار النهار حصل اضطراب ليس بقليل بين العسكر : ترى ماذا جرى لبطرس '),
(7559, 'Acts', 44, 12, 19, ' وأما هيرودس فلما طلبه ولم يجده فحص الحراس ، وأمر أن ينقادوا إلى القتل . ثم نزل من اليهودية إلى قيصرية وأقام هناك '),
(7560, 'Acts', 44, 12, 20, ' وكان هيرودس ساخطا على الصوريين والصيداويين ، فحضروا إليه بنفس واحدة واستعطفوا بلاستس الناظر على مضجع الملك ، ثم صاروا يلتمسون المصالحة لأن كورتهم تقتات من كورة الملك '),
(7561, 'Acts', 44, 12, 21, ' ففي يوم معين لبس هيرودس الحلة الملوكية ، وجلس على كرسي الملك وجعل يخاطبهم '),
(7562, 'Acts', 44, 12, 22, ' فصرخ الشعب : هذا صوت إله لا صوت إنسان '),
(7563, 'Acts', 44, 12, 23, ' ففي الحال ضربه ملاك الرب لأنه لم يعط المجد لله ، فصار يأكله الدود ومات '),
(7564, 'Acts', 44, 12, 24, ' وأما كلمة الله فكانت تنمو وتزيد '),
(7565, 'Acts', 44, 12, 25, ' ورجع برنابا وشاول من أورشليم بعد ما كملا الخدمة ، وأخذا معهما يوحنا الملقب مرقس '),
(7566, 'Acts', 44, 13, 1, ' وكان في أنطاكية في الكنيسة هناك أنبياء ومعلمون : برنابا ، وسمعان الذي يدعى نيجر ، ولوكيوس القيرواني ، ومناين الذي تربى مع هيرودس رئيس الربع ، وشاول '),
(7567, 'Acts', 44, 13, 2, ' وبينما هم يخدمون الرب ويصومون ، قال الروح القدس : أفرزوا لي برنابا وشاول للعمل الذي دعوتهما إليه '),
(7568, 'Acts', 44, 13, 3, ' فصاموا حينئذ وصلوا ووضعوا عليهما الأيادي ، ثم أطلقوهما '),
(7569, 'Acts', 44, 13, 4, ' فهذان إذ أرسلا من الروح القدس انحدرا إلى سلوكية ، ومن هناك سافرا في البحر إلى قبرس '),
(7570, 'Acts', 44, 13, 5, ' ولما صارا في سلاميس ناديا بكلمة الله في مجامع اليهود . وكان معهما يوحنا خادما '),
(7571, 'Acts', 44, 13, 6, ' ولما اجتازا الجزيرة إلى بافوس ، وجدا رجلا ساحرا نبيا كذابا يهوديا اسمه باريشوع '),
(7572, 'Acts', 44, 13, 7, ' كان مع الوالي سرجيوس بولس ، وهو رجل فهيم . فهذا دعا برنابا وشاول والتمس أن يسمع كلمة الله '),
(7573, 'Acts', 44, 13, 8, ' فقاومهما عليم الساحر ، لأن هكذا يترجم اسمه ، طالبا أن يفسد الوالي عن الإيمان '),
(7574, 'Acts', 44, 13, 9, ' وأما شاول ، الذي هو بولس أيضا ، فامتلأ من الروح القدس وشخص إليه '),
(7575, 'Acts', 44, 13, 10, ' وقال : أيها الممتلئ كل غش وكل خبث يا ابن إبليس يا عدو كل بر ألا تزال تفسد سبل الله المستقيمة '),
(7576, 'Acts', 44, 13, 11, ' فالآن هوذا يد الرب عليك ، فتكون أعمى لا تبصر الشمس إلى حين . ففي الحال سقط عليه ضباب وظلمة ، فجعل يدور ملتمسا من يقوده بيده '),
(7577, 'Acts', 44, 13, 12, ' فالوالي حينئذ لما رأى ما جرى ، آمن مندهشا من تعليم الرب '),
(7578, 'Acts', 44, 13, 13, ' ثم أقلع من بافوس بولس ومن معه وأتوا إلى برجة بمفيلية . وأما يوحنا ففارقهم ورجع إلى أورشليم '),
(7579, 'Acts', 44, 13, 14, ' وأما هم فجازوا من برجة وأتوا إلى أنطاكية بيسيدية ، ودخلوا المجمع يوم السبت وجلسوا '),
(7580, 'Acts', 44, 13, 15, ' وبعد قراءة الناموس والأنبياء ، أرسل إليهم رؤساء المجمع قائلين : أيها الرجال الإخوة ، إن كانت عندكم كلمة وعظ للشعب فقولوا '),
(7581, 'Acts', 44, 13, 16, ' فقام بولس وأشار بيده وقال : أيها الرجال الإسرائيليون والذين يتقون الله ، اسمعوا '),
(7582, 'Acts', 44, 13, 17, ' إله شعب إسرائيل هذا اختار آباءنا ، ورفع الشعب في الغربة في أرض مصر ، وبذراع مرتفعة أخرجهم منها '),
(7583, 'Acts', 44, 13, 18, ' ونحو مدة أربعين سنة ، احتمل عوائدهم في البرية '),
(7584, 'Acts', 44, 13, 19, ' ثم أهلك سبع أمم في أرض كنعان وقسم لهم أرضهم بالقرعة '),
(7585, 'Acts', 44, 13, 20, ' وبعد ذلك في نحو أربعمئة وخمسين سنة أعطاهم قضاة حتى صموئيل النبي '),
(7586, 'Acts', 44, 13, 21, ' ومن ثم طلبوا ملكا ، فأعطاهم الله شاول بن قيس ، رجلا من سبط بنيامين ، أربعين سنة '),
(7587, 'Acts', 44, 13, 22, ' ثم عزله وأقام لهم داود ملكا ، الذي شهد له أيضا ، إذ قال : وجدت داود بن يسى رجلا حسب قلبي ، الذي سيصنع كل مشيئتي '),
(7588, 'Acts', 44, 13, 23, ' من نسل هذا ، حسب الوعد ، أقام الله لإسرائيل مخلصا ، يسوع '),
(7589, 'Acts', 44, 13, 24, ' إذ سبق يوحنا فكرز قبل مجيئه بمعمودية التوبة لجميع شعب إسرائيل '),
(7590, 'Acts', 44, 13, 25, ' ولما صار يوحنا يكمل سعيه جعل يقول : من تظنون أني أنا ؟ لست أنا إياه ، لكن هوذا يأتي بعدي الذي لست مستحقا أن أحل حذاء قدميه '),
(7591, 'Acts', 44, 13, 26, ' أيها الرجال الإخوة بني جنس إبراهيم ، والذين بينكم يتقون الله ، إليكم أرسلت كلمة هذا الخلاص '),
(7592, 'Acts', 44, 13, 27, ' لأن الساكنين في أورشليم ورؤساءهم لم يعرفوا هذا . وأقوال الأنبياء التي تقرأ كل سبت تمموها ، إذ حكموا عليه '),
(7593, 'Acts', 44, 13, 28, ' ومع أنهم لم يجدوا علة واحدة للموت طلبوا من بيلاطس أن يقتل '),
(7594, 'Acts', 44, 13, 29, ' ولما تمموا كل ما كتب عنه ، أنزلوه عن الخشبة ووضعوه في قبر '),
(7595, 'Acts', 44, 13, 30, ' ولكن الله أقامه من الأموات '),
(7596, 'Acts', 44, 13, 31, ' وظهر أياما كثيرة للذين صعدوا معه من الجليل إلى أورشليم ، الذين هم شهوده عند الشعب '),
(7597, 'Acts', 44, 13, 32, ' ونحن نبشركم بالموعد الذي صار لآبائنا '),
(7598, 'Acts', 44, 13, 33, ' إن الله قد أكمل هذا لنا نحن أولادهم ، إذ أقام يسوع كما هو مكتوب أيضا في المزمور الثاني : أنت ابني ، أنا اليوم ولدتك '),
(7599, 'Acts', 44, 13, 34, ' إنه أقامه من الأموات ، غير عتيد أن يعود أيضا إلى فساد ، فهكذا قال : إني سأعطيكم مراحم داود الصادقة '),
(7600, 'Acts', 44, 13, 35, ' ولذلك قال أيضا في مزمور آخر : لن تدع قدوسك يرى فسادا '),
(7601, 'Acts', 44, 13, 36, ' لأن داود بعد ما خدم جيله بمشورة الله ، رقد وانضم إلى آبائه ، ورأى فسادا '),
(7602, 'Acts', 44, 13, 37, ' وأما الذي أقامه الله فلم ير فسادا '),
(7603, 'Acts', 44, 13, 38, ' فليكن معلوما عندكم أيها الرجال الإخوة ، أنه بهذا ينادى لكم بغفران الخطايا '),
(7604, 'Acts', 44, 13, 39, ' وبهذا يتبرر كل من يؤمن من كل ما لم تقدروا أن تتبرروا منه بناموس موسى '),
(7605, 'Acts', 44, 13, 40, ' فانظروا لئلا يأتي عليكم ما قيل في الأنبياء '),
(7606, 'Acts', 44, 13, 41, ' انظروا أيها المتهاونون ، وتعجبوا واهلكوا لأنني عملا أعمل في أيامكم . عملا لا تصدقون إن أخبركم أحد به '),
(7607, 'Acts', 44, 13, 42, ' وبعدما خرج اليهود من المجمع جعل الأمم يطلبون إليهما أن يكلماهم بهذا الكلام في السبت القادم '),
(7608, 'Acts', 44, 13, 43, ' ولما انفضت الجماعة ، تبع كثيرون من اليهود والدخلاء المتعبدين بولس وبرنابا ، اللذين كانا يكلمانهم ويقنعانهم أن يثبتوا في نعمة الله '),
(7609, 'Acts', 44, 13, 44, ' وفي السبت التالي اجتمعت كل المدينة تقريبا لتسمع كلمة الله '),
(7610, 'Acts', 44, 13, 45, ' فلما رأى اليهود الجموع امتلأوا غيرة ، وجعلوا يقاومون ما قاله بولس مناقضين ومجدفين '),
(7611, 'Acts', 44, 13, 46, ' فجاهر بولس وبرنابا وقالا : كان يجب أن تكلموا أنتم أولا بكلمة الله ، ولكن إذ دفعتموها عنكم ، وحكمتم أنكم غير مستحقين للحياة الأبدية ، هوذا نتوجه إلى الأمم '),
(7612, 'Acts', 44, 13, 47, ' لأن هكذا أوصانا الرب : قد أقمتك نورا للأمم ، لتكون أنت خلاصا إلى أقصى الأرض '),
(7613, 'Acts', 44, 13, 48, ' فلما سمع الأمم ذلك كانوا يفرحون ويمجدون كلمة الرب . وآمن جميع الذين كانوا معينين للحياة الأبدية '),
(7614, 'Acts', 44, 13, 49, ' وانتشرت كلمة الرب في كل الكورة '),
(7615, 'Acts', 44, 13, 50, ' ولكن اليهود حركوا النساء المتعبدات الشريفات ووجوه المدينة ، وأثاروا اضطهادا على بولس وبرنابا ، وأخرجوهما من تخومهم '),
(7616, 'Acts', 44, 13, 51, ' أما هما فنفضا غبار أرجلهما عليهم ، وأتيا إلى إيقونية '),
(7617, 'Acts', 44, 13, 52, ' وأما التلاميذ فكانوا يمتلئون من الفرح والروح القدس '),
(7618, 'Acts', 44, 14, 1, ' وحدث في إيقونية أنهما دخلا معا إلى مجمع اليهود وتكلما ، حتى آمن جمهور كثير من اليهود واليونانيين '),
(7619, 'Acts', 44, 14, 2, ' ولكن اليهود غير المؤمنين غروا وأفسدوا نفوس الأمم على الإخوة '),
(7620, 'Acts', 44, 14, 3, ' فأقاما زمانا طويلا يجاهران بالرب الذي كان يشهد لكلمة نعمته ، ويعطي أن تجرى آيات وعجائب على أيديهما '),
(7621, 'Acts', 44, 14, 4, ' فانشق جمهور المدينة ، فكان بعضهم مع اليهود ، وبعضهم مع الرسولين '),
(7622, 'Acts', 44, 14, 5, ' فلما حصل من الأمم واليهود مع رؤسائهم هجوم ليبغوا عليهما ويرجموهما '),
(7623, 'Acts', 44, 14, 6, ' شعرا به ، فهربا إلى مدينتي ليكأونية : لسترة ودربة ، وإلى الكورة المحيطة '),
(7624, 'Acts', 44, 14, 7, ' وكانا هناك يبشران . في لسترة ودربة '),
(7625, 'Acts', 44, 14, 8, ' وكان يجلس في لسترة رجل عاجز الرجلين مقعد من بطن أمه ، ولم يمش قط '),
(7626, 'Acts', 44, 14, 9, ' هذا كان يسمع بولس يتكلم ، فشخص إليه ، وإذ رأى أن له إيمانا ليشفى '),
(7627, 'Acts', 44, 14, 10, ' قال بصوت عظيم : قم على رجليك منتصبا . فوثب وصار يمشي '),
(7628, 'Acts', 44, 14, 11, ' فالجموع لما رأوا ما فعل بولس ، رفعوا صوتهم بلغة ليكأونية قائلين : إن الآلهة تشبهوا بالناس ونزلوا إلينا '),
(7629, 'Acts', 44, 14, 12, ' فكانوا يدعون برنابا زفس وبولس هرمس إذ كان هو المتقدم في الكلام '),
(7630, 'Acts', 44, 14, 13, ' فأتى كاهن زفس ، الذي كان قدام المدينة ، بثيران وأكاليل عند الأبواب مع الجموع ، وكان يريد أن يذبح '),
(7631, 'Acts', 44, 14, 14, ' فلما سمع الرسولان ، برنابا وبولس ، مزقا ثيابهما ، واندفعا إلى الجمع صارخين '),
(7632, 'Acts', 44, 14, 15, ' وقائلين : أيها الرجال ، لماذا تفعلون هذا ؟ نحن أيضا بشر تحت آلام مثلكم ، نبشركم أن ترجعوا من هذه الأباطيل إلى الإله الحي الذي خلق السماء والأرض والبحر وكل ما فيها '),
(7633, 'Acts', 44, 14, 16, ' الذي في الأجيال الماضية ترك جميع الأمم يسلكون في طرقهم '),
(7634, 'Acts', 44, 14, 17, ' مع أنه لم يترك نفسه بلا شاهد ، وهو يفعل خيرا : يعطينا من السماء أمطارا وأزمنة مثمرة ، ويملأ قلوبنا طعاما وسرورا '),
(7635, 'Acts', 44, 14, 18, ' وبقولهما هذا كفا الجموع بالجهد عن أن يذبحوا لهما '),
(7636, 'Acts', 44, 14, 19, ' ثم أتى يهود من أنطاكية وإيقونية وأقنعوا الجموع ، فرجموا بولس وجروه خارج المدينة ، ظانين أنه قد مات '),
(7637, 'Acts', 44, 14, 20, ' ولكن إذ أحاط به التلاميذ ، قام ودخل المدينة ، وفي الغد خرج مع برنابا إلى دربة '),
(7638, 'Acts', 44, 14, 21, ' فبشرا في تلك المدينة وتلمذا كثيرين ثم رجعا إلى لسترة وإيقونية وأنطاكية '),
(7639, 'Acts', 44, 14, 22, ' يشددان أنفس التلاميذ ويعظانهم أن يثبتوا في الإيمان ، وأنه بضيقات كثيرة ينبغي أن ندخل ملكوت الله '),
(7640, 'Acts', 44, 14, 23, ' وانتخبا لهم قسوسا في كل كنيسة ، ثم صليا بأصوام واستودعاهم للرب الذي كانوا قد آمنوا به '),
(7641, 'Acts', 44, 14, 24, ' ولما اجتازا في بيسيدية أتيا إلى بمفيلية '),
(7642, 'Acts', 44, 14, 25, ' وتكلما بالكلمة في برجة ، ثم نزلا إلى أتالية '),
(7643, 'Acts', 44, 1, 1, ' الكلام الأول أنشأته يا ثاوفيلس ، عن جميع ما ابتدأ يسوع يفعله ويعلم به '),
(7644, 'Acts', 44, 1, 2, ' إلى اليوم الذي ارتفع فيه ، بعد ما أوصى بالروح القدس الرسل الذين اختارهم '),
(7645, 'Acts', 44, 1, 3, ' الذين أراهم أيضا نفسه حيا ببراهين كثيرة ، بعد ما تألم ، وهو يظهر لهم أربعين يوما ، ويتكلم عن الأمور المختصة بملكوت الله '),
(7646, 'Acts', 44, 1, 4, ' وفيما هو مجتمع معهم أوصاهم أن لا يبرحوا من أورشليم ، بل ينتظروا موعد الآب الذي سمعتموه مني '),
(7647, 'Acts', 44, 1, 5, ' لأن يوحنا عمد بالماء ، وأما أنتم فستتعمدون بالروح القدس ، ليس بعد هذه الأيام بكثير '),
(7648, 'Acts', 44, 1, 6, ' أما هم المجتمعون فسألوه قائلين : يا رب ، هل في هذا الوقت ترد الملك إلى إسرائيل '),
(7649, 'Acts', 44, 1, 7, ' فقال لهم : ليس لكم أن تعرفوا الأزمنة والأوقات التي جعلها الآب في سلطانه '),
(7650, 'Acts', 44, 1, 8, ' لكنكم ستنالون قوة متى حل الروح القدس عليكم ، وتكونون لي شهودا في أورشليم وفي كل اليهودية والسامرة وإلى أقصى الأرض '),
(7651, 'Acts', 44, 1, 9, ' ولما قال هذا ارتفع وهم ينظرون . وأخذته سحابة عن أعينهم '),
(7652, 'Acts', 44, 1, 10, ' وفيما كانوا يشخصون إلى السماء وهو منطلق ، إذا رجلان قد وقفا بهم بلباس أبيض '),
(7653, 'Acts', 44, 1, 11, ' وقالا : أيها الرجال الجليليون ، ما بالكم واقفين تنظرون إلى السماء ؟ إن يسوع هذا الذي ارتفع عنكم إلى السماء سيأتي هكذا كما رأيتموه منطلقا إلى السماء '),
(7654, 'Acts', 44, 1, 12, ' حينئذ رجعوا إلى أورشليم من الجبل الذي يدعى جبل الزيتون ، الذي هو بالقرب من أورشليم على سفر سبت '),
(7655, 'Acts', 44, 1, 13, ' ولما دخلوا صعدوا إلى العلية التي كانوا يقيمون فيها : بطرس ويعقوب ويوحنا وأندراوس وفيلبس وتوما وبرثولماوس ومتى ويعقوب بن حلفى وسمعان الغيور ويهوذا أخو يعقوب '),
(7656, 'Acts', 44, 1, 14, ' هؤلاء كلهم كانوا يواظبون بنفس واحدة على الصلاة والطلبة ، مع النساء ، ومريم أم يسوع ، ومع إخوته '),
(7657, 'Acts', 44, 1, 15, ' وفي تلك الأيام قام بطرس في وسط التلاميذ ، وكان عدة أسماء معا نحو مئة وعشرين . فقال '),
(7658, 'Acts', 44, 1, 16, ' أيها الرجال الإخوة ، كان ينبغي أن يتم هذا المكتوب الذي سبق الروح القدس فقاله بفم داود ، عن يهوذا الذي صار دليلا للذين قبضوا على يسوع '),
(7659, 'Acts', 44, 1, 17, ' إذ كان معدودا بيننا وصار له نصيب في هذه الخدمة '),
(7660, 'Acts', 44, 1, 18, ' فإن هذا اقتنى حقلا من أجرة الظلم ، وإذ سقط على وجهه انشق من الوسط ، فانسكبت أحشاؤه كلها '),
(7661, 'Acts', 44, 1, 19, ' وصار ذلك معلوما عند جميع سكان أورشليم ، حتى دعي ذلك الحقل في لغتهم حقل دما أي : حقل دم '),
(7662, 'Acts', 44, 1, 20, ' لأنه مكتوب في سفر المزامير : لتصر داره خرابا ولا يكن فيها ساكن . وليأخذ وظيفته آخر '),
(7663, 'Acts', 44, 1, 21, ' فينبغي أن الرجال الذين اجتمعوا معنا كل الزمان الذي فيه دخل إلينا الرب يسوع وخرج '),
(7664, 'Acts', 44, 1, 22, ' منذ معمودية يوحنا إلى اليوم الذي ارتفع فيه عنا ، يصير واحد منهم شاهدا معنا بقيامته '),
(7665, 'Acts', 44, 1, 23, ' فأقاموا اثنين : يوسف الذي يدعى بارسابا الملقب يوستس ، ومتياس '),
(7666, 'Acts', 44, 1, 24, ' وصلوا قائلين : أيها الرب العارف قلوب الجميع ، عين أنت من هذين الاثنين أيا اخترته '),
(7667, 'Acts', 44, 1, 25, ' ليأخذ قرعة هذه الخدمة والرسالة التي تعداها يهوذا ليذهب إلى مكانه '),
(7668, 'Acts', 44, 1, 26, ' ثم ألقوا قرعتهم ، فوقعت القرعة على متياس ، فحسب مع الأحد عشر رسولا '),
(7669, 'Acts', 44, 2, 1, ' ولما حضر يوم الخمسين كان الجميع معا بنفس واحدة '),
(7670, 'Acts', 44, 2, 2, ' وصار بغتة من السماء صوت كما من هبوب ريح عاصفة وملأ كل البيت حيث كانوا جالسين '),
(7671, 'Acts', 44, 2, 3, ' وظهرت لهم ألسنة منقسمة كأنها من نار واستقرت على كل واحد منهم '),
(7672, 'Acts', 44, 2, 4, ' وامتلأ الجميع من الروح القدس ، وابتدأوا يتكلمون بألسنة أخرى كما أعطاهم الروح أن ينطقوا '),
(7673, 'Acts', 44, 2, 5, ' وكان يهود رجال أتقياء من كل أمة تحت السماء ساكنين في أورشليم '),
(7674, 'Acts', 44, 2, 6, ' فلما صار هذا الصوت ، اجتمع الجمهور وتحيروا ، لأن كل واحد كان يسمعهم يتكلمون بلغته '),
(7675, 'Acts', 44, 2, 7, ' فبهت الجميع وتعجبوا قائلين بعضهم لبعض : أترى ليس جميع هؤلاء المتكلمين جليليين '),
(7676, 'Acts', 44, 2, 8, ' فكيف نسمع نحن كل واحد منا لغته التي ولد فيها '),
(7677, 'Acts', 44, 2, 9, ' فرتيون وماديون وعيلاميون ، والساكنون ما بين النهرين ، واليهودية وكبدوكية وبنتس وأسيا '),
(7678, 'Acts', 44, 2, 10, ' وفريجية وبمفيلية ومصر ، ونواحي ليبية التي نحو القيروان ، والرومانيون المستوطنون يهود ودخلاء '),
(7679, 'Acts', 44, 2, 11, ' كريتيون وعرب ، نسمعهم يتكلمون بألسنتنا بعظائم الله '),
(7680, 'Acts', 44, 2, 12, ' فتحير الجميع وارتابوا قائلين بعضهم لبعض : ما عسى أن يكون هذا '),
(7681, 'Acts', 44, 2, 13, ' وكان آخرون يستهزئون قائلين : إنهم قد امتلأوا سلافة '),
(7682, 'Acts', 44, 2, 14, ' فوقف بطرس مع الأحد عشر ورفع صوته وقال لهم : أيها الرجال اليهود والساكنون في أورشليم أجمعون ، ليكن هذا معلوما عندكم وأصغوا إلى كلامي '),
(7683, 'Acts', 44, 2, 15, ' لأن هؤلاء ليسوا سكارى كما أنتم تظنون ، لأنها الساعة الثالثة من النهار '),
(7684, 'Acts', 44, 2, 16, ' بل هذا ما قيل بيوئيل النبي '),
(7685, 'Acts', 44, 2, 17, ' يقول الله : ويكون في الأيام الأخيرة أني أسكب من روحي على كل بشر ، فيتنبأ بنوكم وبناتكم ، ويرى شبابكم رؤى ويحلم شيوخكم أحلاما '),
(7686, 'Acts', 44, 2, 18, ' وعلى عبيدي أيضا وإمائي أسكب من روحي في تلك الأيام فيتنبأون '),
(7687, 'Acts', 44, 2, 19, ' وأعطي عجائب في السماء من فوق وآيات على الأرض من أسفل : دما ونارا وبخار دخان '),
(7688, 'Acts', 44, 2, 20, ' تتحول الشمس إلى ظلمة والقمر إلى دم ، قبل أن يجيء يوم الرب العظيم الشهير '),
(7689, 'Acts', 44, 2, 21, ' ويكون كل من يدعو باسم الرب يخلص '),
(7690, 'Acts', 44, 2, 22, ' أيها الرجال الإسرائيليون اسمعوا هذه الأقوال : يسوع الناصري رجل قد تبرهن لكم من قبل الله بقوات وعجائب وآيات صنعها الله بيده في وسطكم ، كما أنتم أيضا تعلمون '),
(7691, 'Acts', 44, 2, 23, ' هذا أخذتموه مسلما بمشورة الله المحتومة وعلمه السابق ، وبأيدي أثمة صلبتموه وقتلتموه '),
(7692, 'Acts', 44, 2, 24, ' الذي أقامه الله ناقضا أوجاع الموت ، إذ لم يكن ممكنا أن يمسك منه '),
(7693, 'Acts', 44, 2, 25, ' لأن داود يقول فيه : كنت أرى الرب أمامي في كل حين ، أنه عن يميني ، لكي لا أتزعزع '),
(7694, 'Acts', 44, 2, 26, ' لذلك سر قلبي وتهلل لساني . حتى جسدي أيضا سيسكن على رجاء '),
(7695, 'Acts', 44, 2, 27, ' لأنك لن تترك نفسي في الهاوية ولا تدع قدوسك يرى فسادا '),
(7696, 'Acts', 44, 2, 28, ' عرفتني سبل الحياة وستملأني سرورا مع وجهك '),
(7697, 'Acts', 44, 2, 29, ' أيها الرجال الإخوة ، يسوغ أن يقال لكم جهارا عن رئيس الآباء داود إنه مات ودفن ، وقبره عندنا حتى هذا اليوم '),
(7698, 'Acts', 44, 2, 30, ' فإذ كان نبيا ، وعلم أن الله حلف له بقسم أنه من ثمرة صلبه يقيم المسيح حسب الجسد ليجلس على كرسيه '),
(7699, 'Acts', 44, 2, 31, ' سبق فرأى وتكلم عن قيامة المسيح : أنه لم تترك نفسه في الهاوية ولا رأى جسده فسادا '),
(7700, 'Acts', 44, 2, 32, ' فيسوع هذا أقامه الله ، ونحن جميعا شهود لذلك '),
(7701, 'Acts', 44, 2, 33, ' وإذ ارتفع بيمين الله ، وأخذ موعد الروح القدس من الآب ، سكب هذا الذي أنتم الآن تبصرونه وتسمعونه '),
(7702, 'Acts', 44, 2, 34, ' لأن داود لم يصعد إلى السماوات . وهو نفسه يقول : قال الرب لربي : اجلس عن يميني '),
(7703, 'Acts', 44, 2, 35, ' حتى أضع أعداءك موطئا لقدميك '),
(7704, 'Acts', 44, 2, 36, ' فليعلم يقينا جميع بيت إسرائيل أن الله جعل يسوع هذا ، الذي صلبتموه أنتم ، ربا ومسيحا '),
(7705, 'Acts', 44, 2, 37, ' فلما سمعوا نخسوا في قلوبهم ، وقالوا لبطرس ولسائر الرسل : ماذا نصنع أيها الرجال الإخوة '),
(7706, 'Acts', 44, 2, 38, ' فقال لهم بطرس : توبوا وليعتمد كل واحد منكم على اسم يسوع المسيح لغفران الخطايا ، فتقبلوا عطية الروح القدس '),
(7707, 'Acts', 44, 2, 39, ' لأن الموعد هو لكم ولأولادكم ولكل الذين على بعد ، كل من يدعوه الرب إلهنا '),
(7708, 'Acts', 44, 2, 40, ' وبأقوال أخر كثيرة كان يشهد لهم ويعظهم قائلا : اخلصوا من هذا الجيل الملتوي '),
(7709, 'Acts', 44, 2, 41, ' فقبلوا كلامه بفرح ، واعتمدوا ، وانضم في ذلك اليوم نحو ثلاثة آلاف نفس '),
(7710, 'Acts', 44, 2, 42, ' وكانوا يواظبون على تعليم الرسل ، والشركة ، وكسر الخبز ، والصلوات '),
(7711, 'Acts', 44, 2, 43, ' وصار خوف في كل نفس . وكانت عجائب وآيات كثيرة تجرى على أيدي الرسل '),
(7712, 'Acts', 44, 2, 44, ' وجميع الذين آمنوا كانوا معا ، وكان عندهم كل شيء مشتركا '),
(7713, 'Acts', 44, 2, 45, ' والأملاك والمقتنيات كانوا يبيعونها ويقسمونها بين الجميع ، كما يكون لكل واحد احتياج '),
(7714, 'Acts', 44, 2, 46, ' وكانوا كل يوم يواظبون في الهيكل بنفس واحدة . وإذ هم يكسرون الخبز في البيوت ، كانوا يتناولون الطعام بابتهاج وبساطة قلب '),
(7715, 'Acts', 44, 2, 47, ' مسبحين الله ، ولهم نعمة لدى جميع الشعب . وكان الرب كل يوم يضم إلى الكنيسة الذين يخلصون '),
(7716, 'Acts', 44, 3, 1, ' وصعد بطرس ويوحنا معا إلى الهيكل في ساعة الصلاة التاسعة '),
(7717, 'Acts', 44, 3, 2, ' وكان رجل أعرج من بطن أمه يحمل ، كانوا يضعونه كل يوم عند باب الهيكل الذي يقال له الجميل ليسأل صدقة من الذين يدخلون الهيكل '),
(7718, 'Acts', 44, 3, 3, ' فهذا لما رأى بطرس ويوحنا مزمعين أن يدخلا الهيكل ، سأل ليأخذ صدقة '),
(7719, 'Acts', 44, 3, 4, ' فتفرس فيه بطرس مع يوحنا ، وقال : انظر إلينا '),
(7720, 'Acts', 44, 3, 5, ' فلاحظهما منتظرا أن يأخذ منهما شيئا '),
(7721, 'Acts', 44, 3, 6, ' فقال بطرس : ليس لي فضة ولا ذهب ، ولكن الذي لي فإياه أعطيك : باسم يسوع المسيح الناصري قم وامش '),
(7722, 'Acts', 44, 3, 7, ' وأمسكه بيده اليمنى وأقامه ، ففي الحال تشددت رجلاه وكعباه '),
(7723, 'Acts', 44, 3, 8, ' فوثب ووقف وصار يمشي ، ودخل معهما إلى الهيكل وهو يمشي ويطفر ويسبح الله '),
(7724, 'Acts', 44, 3, 9, ' وأبصره جميع الشعب وهو يمشي ويسبح الله '),
(7725, 'Acts', 44, 3, 10, ' وعرفوه أنه هو الذي كان يجلس لأجل الصدقة على باب الهيكل الجميل ، فامتلأوا دهشة وحيرة مما حدث له '),
(7726, 'Acts', 44, 3, 11, ' وبينما كان الرجل الأعرج الذي شفي متمسكا ببطرس ويوحنا ، تراكض إليهم جميع الشعب إلى الرواق الذي يقال له رواق سليمان وهم مندهشون '),
(7727, 'Acts', 44, 3, 12, ' فلما رأى بطرس ذلك أجاب الشعب : أيها الرجال الإسرائيليون ، ما بالكم تتعجبون من هذا ؟ ولماذا تشخصون إلينا ، كأننا بقوتنا أو تقوانا قد جعلنا هذا يمشي '),
(7728, 'Acts', 44, 3, 13, ' إن إله إبراهيم وإسحاق ويعقوب ، إله آبائنا ، مجد فتاه يسوع ، الذي أسلمتموه أنتم وأنكرتموه أمام وجه بيلاطس ، وهو حاكم بإطلاقه '),
(7729, 'Acts', 44, 3, 14, ' ولكن أنتم أنكرتم القدوس البار ، وطلبتم أن يوهب لكم رجل قاتل '),
(7730, 'Acts', 44, 3, 15, ' ورئيس الحياة قتلتموه ، الذي أقامه الله من الأموات ، ونحن شهود لذلك '),
(7731, 'Acts', 44, 3, 16, ' وبالإيمان باسمه ، شدد اسمه هذا الذي تنظرونه وتعرفونه ، والإيمان الذي بواسطته أعطاه هذه الصحة أمام جميعكم '),
(7732, 'Acts', 44, 3, 17, ' والآن أيها الإخوة ، أنا أعلم أنكم بجهالة عملتم ، كما رؤساؤكم أيضا '),
(7733, 'Acts', 44, 3, 18, ' وأما الله فما سبق وأنبأ به بأفواه جميع أنبيائه ، أن يتألم المسيح ، قد تممه هكذا '),
(7734, 'Acts', 44, 3, 19, ' فتوبوا وارجعوا لتمحى خطاياكم ، لكي تأتي أوقات الفرج من وجه الرب '),
(7735, 'Acts', 44, 3, 20, ' ويرسل يسوع المسيح المبشر به لكم قبل '),
(7736, 'Acts', 44, 3, 21, ' الذي ينبغي أن السماء تقبله ، إلى أزمنة رد كل شيء ، التي تكلم عنها الله بفم جميع أنبيائه القديسين منذ الدهر '),
(7737, 'Acts', 44, 3, 22, ' فإن موسى قال للآباء : إن نبيا مثلي سيقيم لكم الرب إلهكم من إخوتكم . له تسمعون في كل ما يكلمكم به '),
(7738, 'Acts', 44, 3, 23, ' ويكون أن كل نفس لا تسمع لذلك النبي تباد من الشعب '),
(7739, 'Acts', 44, 3, 24, ' وجميع الأنبياء أيضا من صموئيل فما بعده ، جميع الذين تكلموا ، سبقوا وأنبأوا بهذه الأيام '),
(7740, 'Acts', 44, 3, 25, ' أنتم أبناء الأنبياء ، والعهد الذي عاهد به الله آباءنا قائلا لإبراهيم : وبنسلك تتبارك جميع قبائل الأرض '),
(7741, 'Acts', 44, 3, 26, ' إليكم أولا ، إذ أقام الله فتاه يسوع ، أرسله يبارككم برد كل واحد منكم عن شروره '),
(7742, 'Acts', 44, 4, 1, ' وبينما هما يخاطبان الشعب ، أقبل عليهما الكهنة وقائد جند الهيكل والصدوقيون '),
(7743, 'Acts', 44, 4, 2, ' متضجرين من تعليمهما الشعب ، وندائهما في يسوع بالقيامة من الأموات '),
(7744, 'Acts', 44, 4, 3, ' فألقوا عليهما الأيادي ووضعوهما في حبس إلى الغد ، لأنه كان قد صار المساء '),
(7745, 'Acts', 44, 4, 4, ' وكثيرون من الذين سمعوا الكلمة آمنوا ، وصار عدد الرجال نحو خمسة آلاف '),
(7746, 'Acts', 44, 4, 5, ' وحدث في الغد أن رؤساءهم وشيوخهم وكتبتهم اجتمعوا إلى أورشليم '),
(7747, 'Acts', 44, 4, 6, ' مع حنان رئيس الكهنة وقيافا ويوحنا والإسكندر ، وجميع الذين كانوا من عشيرة رؤساء الكهنة '),
(7748, 'Acts', 44, 4, 7, ' ولما أقاموهما في الوسط ، جعلوا يسألونهما : بأية قوة وبأي اسم صنعتما أنتما هذا '),
(7749, 'Acts', 44, 4, 8, ' حينئذ امتلأ بطرس من الروح القدس وقال لهم : يا رؤساء الشعب وشيوخ إسرائيل '),
(7750, 'Acts', 44, 4, 9, ' إن كنا نفحص اليوم عن إحسان إلى إنسان سقيم ، بماذا شفي هذا '),
(7751, 'Acts', 44, 4, 10, ' فليكن معلوما عند جميعكم وجميع شعب إسرائيل ، أنه باسم يسوع المسيح الناصري ، الذي صلبتموه أنتم ، الذي أقامه الله من الأموات ، بذاك وقف هذا أمامكم صحيحا '),
(7752, 'Acts', 44, 4, 11, ' هذا هو : الحجر الذي احتقرتموه أيها البناؤون ، الذي صار رأس الزاوية '),
(7753, 'Acts', 44, 4, 12, ' وليس بأحد غيره الخلاص . لأن ليس اسم آخر تحت السماء ، قد أعطي بين الناس ، به ينبغي أن نخلص '),
(7754, 'Acts', 44, 4, 13, ' فلما رأوا مجاهرة بطرس ويوحنا ، ووجدوا أنهما إنسانان عديما العلم وعاميان ، تعجبوا . فعرفوهما أنهما كانا مع يسوع '),
(7755, 'Acts', 44, 4, 14, ' ولكن إذ نظروا الإنسان الذي شفي واقفا معهما ، لم يكن لهم شيء يناقضون به '),
(7756, 'Acts', 44, 4, 15, ' فأمروهما أن يخرجا إلى خارج المجمع ، وتآمروا فيما بينهم '),
(7757, 'Acts', 44, 4, 16, ' قائلين : ماذا نفعل بهذين الرجلين ؟ لأنه ظاهر لجميع سكان أورشليم أن آية معلومة قد جرت بأيديهما ، ولا نقدر أن ننكر '),
(7758, 'Acts', 44, 4, 17, ' ولكن لئلا تشيع أكثر في الشعب ، لنهددهما تهديدا أن لا يكلما أحدا من الناس فيما بعد بهذا الاسم '),
(7759, 'Acts', 44, 4, 18, ' فدعوهما وأوصوهما أن لا ينطقا البتة ، ولا يعلما باسم يسوع '),
(7760, 'Acts', 44, 4, 19, ' فأجابهم بطرس ويوحنا وقالا : إن كان حقا أمام الله أن نسمع لكم أكثر من الله ، فاحكموا '),
(7761, 'Acts', 44, 4, 20, ' لأننا نحن لا يمكننا أن لا نتكلم بما رأينا وسمعنا '),
(7762, 'Acts', 44, 4, 21, ' وبعدما هددوهما أيضا أطلقوهما ، إذ لم يجدوا البتة كيف يعاقبونهما بسبب الشعب ، لأن الجميع كانوا يمجدون الله على ما جرى '),
(7763, 'Acts', 44, 4, 22, ' لأن الإنسان الذي صارت فيه آية الشفاء هذه ، كان له أكثر من أربعين سنة '),
(7764, 'Acts', 44, 4, 23, ' ولما أطلقا أتيا إلى رفقائهما وأخبراهم بكل ما قاله لهما رؤساء الكهنة والشيوخ '),
(7765, 'Acts', 44, 4, 24, ' فلما سمعوا ، رفعوا بنفس واحدة صوتا إلى الله وقالوا : أيها السيد ، أنت هو الإله الصانع السماء والأرض والبحر وكل ما فيها '),
(7766, 'Acts', 44, 4, 25, ' القائل بفم داود فتاك : لماذا ارتجت الأمم وتفكر الشعوب بالباطل '),
(7767, 'Acts', 44, 4, 26, ' قامت ملوك الأرض ، واجتمع الرؤساء معا على الرب وعلى مسيحه '),
(7768, 'Acts', 44, 4, 27, ' لأنه بالحقيقة اجتمع على فتاك القدوس يسوع ، الذي مسحته ، هيرودس وبيلاطس البنطي مع أمم وشعوب إسرائيل '),
(7769, 'Acts', 44, 4, 28, ' ليفعلوا كل ما سبقت فعينت يدك ومشورتك أن يكون '),
(7770, 'Acts', 44, 4, 29, ' والآن يا رب ، انظر إلى تهديداتهم ، وامنح عبيدك أن يتكلموا بكلامك بكل مجاهرة '),
(7771, 'Acts', 44, 4, 30, ' بمد يدك للشفاء ، ولتجر آيات وعجائب باسم فتاك القدوس يسوع '),
(7772, 'Acts', 44, 4, 31, ' ولما صلوا تزعزع المكان الذي كانوا مجتمعين فيه ، وامتلأ الجميع من الروح القدس ، وكانوا يتكلمون بكلام الله بمجاهرة '),
(7773, 'Acts', 44, 4, 32, ' وكان لجمهور الذين آمنوا قلب واحد ونفس واحدة ، ولم يكن أحد يقول إن شيئا من أمواله له ، بل كان عندهم كل شيء مشتركا '),
(7774, 'Acts', 44, 4, 33, ' وبقوة عظيمة كان الرسل يؤدون الشهادة بقيامة الرب يسوع ، ونعمة عظيمة كانت على جميعهم '),
(7775, 'Acts', 44, 4, 34, ' إذ لم يكن فيهم أحد محتاجا ، لأن كل الذين كانوا أصحاب حقول أو بيوت كانوا يبيعونها ، ويأتون بأثمان المبيعات '),
(7776, 'Acts', 44, 4, 35, ' ويضعونها عند أرجل الرسل ، فكان يوزع على كل أحد كما يكون له احتياج '),
(7777, 'Acts', 44, 4, 36, ' ويوسف الذي دعي من الرسل برنابا ، الذي يترجم ابن الوعظ ، وهو لاوي قبرسي الجنس '),
(7778, 'Acts', 44, 4, 37, ' إذ كان له حقل باعه ، وأتى بالدراهم ووضعها عند أرجل الرسل '),
(7779, 'Acts', 44, 5, 1, ' ورجل اسمه حنانيا ، وامرأته سفيرة ، باع ملكا '),
(7780, 'Acts', 44, 5, 2, ' واختلس من الثمن ، وامرأته لها خبر ذلك ، وأتى بجزء ووضعه عند أرجل الرسل '),
(7781, 'Acts', 44, 5, 3, ' فقال بطرس : يا حنانيا ، لماذا ملأ الشيطان قلبك لتكذب على الروح القدس وتختلس من ثمن الحقل '),
(7782, 'Acts', 44, 5, 4, ' أليس وهو باق كان يبقى لك ؟ ولما بيع ، ألم يكن في سلطانك ؟ فما بالك وضعت في قلبك هذا الأمر ؟ أنت لم تكذب على الناس بل على الله '),
(7783, 'Acts', 44, 5, 5, ' فلما سمع حنانيا هذا الكلام وقع ومات . وصار خوف عظيم على جميع الذين سمعوا بذلك '),
(7784, 'Acts', 44, 5, 6, ' فنهض الأحداث ولفوه وحملوه خارجا ودفنوه '),
(7785, 'Acts', 44, 5, 7, ' ثم حدث بعد مدة نحو ثلاث ساعات ، أن امرأته دخلت ، وليس لها خبر ما جرى '),
(7786, 'Acts', 44, 5, 8, ' فأجابها بطرس : قولي لي : أبهذا المقدار بعتما الحقل ؟ فقالت : نعم ، بهذا المقدار '),
(7787, 'Acts', 44, 5, 9, ' فقال لها بطرس : ما بالكما اتفقتما على تجربة روح الرب ؟ هوذا أرجل الذين دفنوا رجلك على الباب ، وسيحملونك خارجا '),
(7788, 'Acts', 44, 5, 10, ' فوقعت في الحال عند رجليه وماتت . فدخل الشباب ووجدوها ميتة ، فحملوها خارجا ودفنوها بجانب رجلها '),
(7789, 'Acts', 44, 5, 11, ' فصار خوف عظيم على جميع الكنيسة وعلى جميع الذين سمعوا بذلك '),
(7790, 'Acts', 44, 5, 12, ' وجرت على أيدي الرسل آيات وعجائب كثيرة في الشعب . وكان الجميع بنفس واحدة في رواق سليمان '),
(7791, 'Acts', 44, 5, 13, ' وأما الآخرون فلم يكن أحد منهم يجسر أن يلتصق بهم ، لكن كان الشعب يعظمهم '),
(7792, 'Acts', 44, 5, 14, ' وكان مؤمنون ينضمون للرب أكثر ، جماهير من رجال ونساء '),
(7793, 'Acts', 44, 5, 15, ' حتى إنهم كانوا يحملون المرضى خارجا في الشوارع ويضعونهم على فرش وأسرة ، حتى إذا جاء بطرس يخيم ولو ظله على أحد منهم '),
(7794, 'Acts', 44, 5, 16, ' واجتمع جمهور المدن المحيطة إلى أورشليم حاملين مرضى ومعذبين من أرواح نجسة ، وكانوا يبرأون جميعهم '),
(7795, 'Acts', 44, 5, 17, ' فقام رئيس الكهنة وجميع الذين معه ، الذين هم شيعة الصدوقيين ، وامتلأوا غيرة '),
(7796, 'Acts', 44, 5, 18, ' فألقوا أيديهم على الرسل ووضعوهم في حبس العامة '),
(7797, 'Acts', 44, 5, 19, ' ولكن ملاك الرب في الليل فتح أبواب السجن وأخرجهم وقال '),
(7798, 'Acts', 44, 5, 20, ' اذهبوا قفوا وكلموا الشعب في الهيكل بجميع كلام هذه الحياة '),
(7799, 'Acts', 44, 5, 21, ' فلما سمعوا دخلوا الهيكل نحو الصبح وجعلوا يعلمون . ثم جاء رئيس الكهنة والذين معه ، ودعوا المجمع وكل مشيخة بني إسرائيل ، فأرسلوا إلى الحبس ليؤتى بهم '),
(7800, 'Acts', 44, 5, 22, ' ولكن الخدام لما جاءوا لم يجدوهم في السجن ، فرجعوا وأخبروا '),
(7801, 'Acts', 44, 5, 23, ' قائلين : إننا وجدنا الحبس مغلقا بكل حرص ، والحراس واقفين خارجا أمام الأبواب ، ولكن لما فتحنا لم نجد في الداخل أحدا '),
(7802, 'Acts', 44, 5, 24, ' فلما سمع الكاهن وقائد جند الهيكل ورؤساء الكهنة هذه الأقوال ، ارتابوا من جهتهم : ما عسى أن يصير هذا '),
(7803, 'Acts', 44, 5, 25, ' ثم جاء واحد وأخبرهم قائلا : هوذا الرجال الذين وضعتموهم في السجن هم في الهيكل واقفين يعلمون الشعب ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(7804, 'Acts', 44, 5, 26, ' حينئذ مضى قائد الجند مع الخدام ، فأحضرهم لا بعنف ، لأنهم كانوا يخافون الشعب لئلا يرجموا '),
(7805, 'Acts', 44, 5, 27, ' فلما أحضروهم أوقفوهم في المجمع . فسألهم رئيس الكهنة '),
(7806, 'Acts', 44, 5, 28, ' قائلا : أما أوصيناكم وصية أن لا تعلموا بهذا الاسم ؟ وها أنتم قد ملأتم أورشليم بتعليمكم ، وتريدون أن تجلبوا علينا دم هذا الإنسان '),
(7807, 'Acts', 44, 5, 29, ' فأجاب بطرس والرسل وقالوا : ينبغي أن يطاع الله أكثر من الناس '),
(7808, 'Acts', 44, 5, 30, ' إله آبائنا أقام يسوع الذي أنتم قتلتموه معلقين إياه على خشبة '),
(7809, 'Acts', 44, 5, 31, ' هذا رفعه الله بيمينه رئيسا ومخلصا ، ليعطي إسرائيل التوبة وغفران الخطايا '),
(7810, 'Acts', 44, 5, 32, ' ونحن شهود له بهذه الأمور ، والروح القدس أيضا ، الذي أعطاه الله للذين يطيعونه '),
(7811, 'Acts', 44, 5, 33, ' فلما سمعوا حنقوا ، وجعلوا يتشاورون أن يقتلوهم '),
(7812, 'Acts', 44, 5, 34, ' فقام في المجمع رجل فريسي اسمه غمالائيل ، معلم للناموس ، مكرم عند جميع الشعب ، وأمر أن يخرج الرسل قليلا '),
(7813, 'Acts', 44, 5, 35, ' ثم قال لهم : أيها الرجال الإسرائيليون ، احترزوا لأنفسكم من جهة هؤلاء الناس في ما أنتم مزمعون أن تفعلوا '),
(7814, 'Acts', 44, 5, 36, ' لأنه قبل هذه الأيام قام ثوداس قائلا عن نفسه إنه شيء ، الذي التصق به عدد من الرجال نحو أربعمئة ، الذي قتل ، وجميع الذين انقادوا إليه تبددوا وصاروا لا شيء '),
(7815, 'Acts', 44, 5, 37, ' بعد هذا قام يهوذا الجليلي في أيام الاكتتاب ، وأزاغ وراءه شعبا غفيرا . فذاك أيضا هلك ، وجميع الذين انقادوا إليه تشتتوا '),
(7816, 'Acts', 44, 5, 38, ' والآن أقول لكم : تنحوا عن هؤلاء الناس واتركوهم لأنه إن كان هذا الرأي أو هذا العمل من الناس فسوف ينتقض '),
(7817, 'Acts', 44, 5, 39, ' وإن كان من الله فلا تقدرون أن تنقضوه ، لئلا توجدوا محاربين لله أيضا '),
(7818, 'Acts', 44, 5, 40, ' فانقادوا إليه . ودعوا الرسل وجلدوهم ، وأوصوهم أن لا يتكلموا باسم يسوع ، ثم أطلقوهم '),
(7819, 'Acts', 44, 5, 41, ' وأما هم فذهبوا فرحين من أمام المجمع ، لأنهم حسبوا مستأهلين أن يهانوا من أجل اسمه '),
(7820, 'Acts', 44, 5, 42, ' وكانوا لا يزالون كل يوم في الهيكل وفي البيوت معلمين ومبشرين بيسوع المسيح '),
(7821, 'Acts', 44, 6, 1, ' وفي تلك الأيام إذ تكاثر التلاميذ ، حدث تذمر من اليونانيين على العبرانيين أن أراملهم كن يغفل عنهن في الخدمة اليومية '),
(7822, 'Acts', 44, 6, 2, ' فدعا الاثنا عشر جمهور التلاميذ وقالوا : لا يرضي أن نترك نحن كلمة الله ونخدم موائد '),
(7823, 'Acts', 44, 6, 3, ' فانتخبوا أيها الإخوة سبعة رجال منكم ، مشهودا لهم ومملوين من الروح القدس وحكمة ، فنقيمهم على هذه الحاجة '),
(7824, 'Acts', 44, 6, 4, ' وأما نحن فنواظب على الصلاة وخدمة الكلمة '),
(7825, 'Acts', 44, 6, 5, ' فحسن هذا القول أمام كل الجمهور ، فاختاروا استفانوس ، رجلا مملوا من الإيمان والروح القدس ، وفيلبس ، وبروخورس ، ونيكانور ، وتيمون ، وبرميناس ، ونيقولاوس دخيلا أنطاكيا '),
(7826, 'Acts', 44, 6, 6, ' الذين أقاموهم أمام الرسل ، فصلوا ووضعوا عليهم الأيادي '),
(7827, 'Acts', 44, 6, 7, ' وكانت كلمة الله تنمو ، وعدد التلاميذ يتكاثر جدا في أورشليم ، وجمهور كثير من الكهنة يطيعون الإيمان '),
(7828, 'Acts', 44, 6, 8, ' وأما استفانوس فإذ كان مملوا إيمانا وقوة ، كان يصنع عجائب وآيات عظيمة في الشعب '),
(7829, 'Acts', 44, 6, 9, ' فنهض قوم من المجمع الذي يقال له مجمع الليبرتينيين والقيروانيين والإسكندريين ، ومن الذين من كيليكيا وأسيا ، يحاورون استفانوس '),
(7830, 'Acts', 44, 6, 10, ' ولم يقدروا أن يقاوموا الحكمة والروح الذي كان يتكلم به '),
(7831, 'Acts', 44, 6, 11, ' حينئذ دسوا لرجال يقولون : إننا سمعناه يتكلم بكلام تجديف على موسى وعلى الله '),
(7832, 'Acts', 44, 6, 12, ' وهيجوا الشعب والشيوخ والكتبة ، فقاموا وخطفوه وأتوا به إلى المجمع '),
(7833, 'Acts', 44, 6, 13, ' وأقاموا شهودا كذبة يقولون : هذا الرجل لا يفتر عن أن يتكلم كلاما تجديفا ضد هذا الموضع المقدس والناموس '),
(7834, 'Acts', 44, 6, 14, ' لأننا سمعناه يقول : إن يسوع الناصري هذا سينقض هذا الموضع ، ويغير العوائد التي سلمنا إياها موسى '),
(7835, 'Acts', 44, 6, 15, ' فشخص إليه جميع الجالسين في المجمع ، ورأوا وجهه كأنه وجه ملاك '),
(7836, 'Acts', 44, 7, 1, ' فقال رئيس الكهنة : أترى هذه الأمور هكذا هي '),
(7837, 'Acts', 44, 7, 2, ' فقال : أيها الرجال الإخوة والآباء ، اسمعوا ظهر إله المجد لأبينا إبراهيم وهو في ما بين النهرين ، قبلما سكن في حاران '),
(7838, 'Acts', 44, 7, 3, ' وقال له : اخرج من أرضك ومن عشيرتك ، وهلم إلى الأرض التي أريك '),
(7839, 'Acts', 44, 7, 4, ' فخرج حينئذ من أرض الكلدانيين وسكن في حاران . ومن هناك نقله ، بعد ما مات أبوه ، إلى هذه الأرض التي أنتم الآن ساكنون فيها '),
(7840, 'Acts', 44, 7, 5, ' ولم يعطه فيها ميراثا ولا وطأة قدم ، ولكن وعد أن يعطيها ملكا له ولنسله من بعده ، ولم يكن له بعد ولد '),
(7841, 'Acts', 44, 7, 6, ' وتكلم الله هكذا : أن يكون نسله متغربا في أرض غريبة ، فيستعبدوه ويسيئوا إليه أربع مئة سنة '),
(7842, 'Acts', 44, 7, 7, ' والأمة التي يستعبدون لها سأدينها أنا ، يقول الله . وبعد ذلك يخرجون ويعبدونني في هذا المكان '),
(7843, 'Acts', 44, 7, 8, ' وأعطاه عهد الختان ، وهكذا ولد إسحاق وختنه في اليوم الثامن . وإسحاق ولد يعقوب ، ويعقوب ولد رؤساء الآباء الاثني عشر '),
(7844, 'Acts', 44, 7, 9, ' ورؤساء الآباء حسدوا يوسف وباعوه إلى مصر ، وكان الله معه '),
(7845, 'Acts', 44, 7, 10, ' وأنقذه من جميع ضيقاته ، وأعطاه نعمة وحكمة أمام فرعون ملك مصر ، فأقامه مدبرا على مصر وعلى كل بيته '),
(7846, 'Acts', 44, 7, 11, ' ثم أتى جوع على كل أرض مصر وكنعان ، وضيق عظيم ، فكان آباؤنا لا يجدون قوتا '),
(7847, 'Acts', 44, 7, 12, ' ولما سمع يعقوب أن في مصر قمحا ، أرسل آباءنا أول مرة '),
(7848, 'Acts', 44, 7, 13, ' وفي المرة الثانية استعرف يوسف إلى إخوته ، واستعلنت عشيرة يوسف لفرعون '),
(7849, 'Acts', 44, 7, 14, ' فأرسل يوسف واستدعى أباه يعقوب وجميع عشيرته ، خمسة وسبعين نفسا '),
(7850, 'Acts', 44, 7, 15, ' فنزل يعقوب إلى مصر ومات هو وآباؤنا '),
(7851, 'Acts', 44, 7, 16, ' ونقلوا إلى شكيم ووضعوا في القبر الذي اشتراه إبراهيم بثمن فضة من بني حمور أبي شكيم '),
(7852, 'Acts', 44, 7, 17, ' وكما كان يقرب وقت الموعد الذي أقسم الله عليه لإبراهيم ، كان ينمو الشعب ويكثر في مصر '),
(7853, 'Acts', 44, 7, 18, ' إلى أن قام ملك آخر لم يكن يعرف يوسف '),
(7854, 'Acts', 44, 7, 19, ' فاحتال هذا على جنسنا وأساء إلى آبائنا ، حتى جعلوا أطفالهم منبوذين لكي لا يعيشوا '),
(7855, 'Acts', 44, 7, 20, ' وفي ذلك الوقت ولد موسى وكان جميلا جدا ، فربي هذا ثلاثة أشهر في بيت أبيه '),
(7856, 'Acts', 44, 7, 21, ' ولما نبذ ، اتخذته ابنة فرعون وربته لنفسها ابنا '),
(7857, 'Acts', 44, 7, 22, ' فتهذب موسى بكل حكمة المصريين ، وكان مقتدرا في الأقوال والأعمال '),
(7858, 'Acts', 44, 7, 23, ' ولما كملت له مدة أربعين سنة ، خطر على باله أن يفتقد إخوته بني إسرائيل '),
(7859, 'Acts', 44, 7, 24, ' وإذ رأى واحدا مظلوما حامى عنه ، وأنصف المغلوب ، إذ قتل المصري '),
(7860, 'Acts', 44, 7, 25, ' فظن أن إخوته يفهمون أن الله على يده يعطيهم نجاة ، وأما هم فلم يفهموا '),
(7861, 'Acts', 44, 7, 26, ' وفي اليوم الثاني ظهر لهم وهم يتخاصمون ، فساقهم إلى السلامة قائلا : أيها الرجال ، أنتم إخوة . لماذا تظلمون بعضكم بعضا '),
(7862, 'Acts', 44, 7, 27, ' فالذي كان يظلم قريبه دفعه قائلا : من أقامك رئيسا وقاضيا علينا '),
(7863, 'Acts', 44, 7, 28, ' أتريد أن تقتلني كما قتلت أمس المصري '),
(7864, 'Acts', 44, 7, 29, ' فهرب موسى بسبب هذه الكلمة ، وصار غريبا في أرض مديان ، حيث ولد ابنين '),
(7865, 'Acts', 44, 7, 30, ' ولما كملت أربعون سنة ، ظهر له ملاك الرب في برية جبل سيناء في لهيب نار عليقة '),
(7866, 'Acts', 44, 7, 31, ' فلما رأى موسى ذلك تعجب من المنظر . وفيما هو يتقدم ليتطلع ، صار إليه صوت الرب '),
(7867, 'Acts', 44, 7, 32, ' أنا إله آبائك ، إله إبراهيم وإله إسحاق وإله يعقوب . فارتعد موسى ولم يجسر أن يتطلع '),
(7868, 'Acts', 44, 7, 33, ' فقال له الرب : اخلع نعل رجليك ، لأن الموضع الذي أنت واقف عليه أرض مقدسة '),
(7869, 'Acts', 44, 7, 34, ' إني لقد رأيت مشقة شعبي الذين في مصر ، وسمعت أنينهم ونزلت لأنقذهم . فهلم الآن أرسلك إلى مصر '),
(7870, 'Acts', 44, 7, 35, ' هذا موسى الذي أنكروه قائلين : من أقامك رئيسا وقاضيا ؟ هذا أرسله الله رئيسا وفاديا بيد الملاك الذي ظهر له في العليقة '),
(7871, 'Acts', 44, 7, 36, ' هذا أخرجهم صانعا عجائب وآيات في أرض مصر ، وفي البحر الأحمر ، وفي البرية أربعين سنة '),
(7872, 'Acts', 44, 7, 37, ' هذا هو موسى الذي قال لبني إسرائيل : نبيا مثلي سيقيم لكم الرب إلهكم من إخوتكم . له تسمعون '),
(7873, 'Acts', 44, 7, 38, ' هذا هو الذي كان في الكنيسة في البرية ، مع الملاك الذي كان يكلمه في جبل سيناء ، ومع آبائنا . الذي قبل أقوالا حية ليعطينا إياها '),
(7874, 'Acts', 44, 7, 39, ' الذي لم يشأ آباؤنا أن يكونوا طائعين له ، بل دفعوه ورجعوا بقلوبهم إلى مصر '),
(7875, 'Acts', 44, 7, 40, ' قائلين لهارون : اعمل لنا آلهة تتقدم أمامنا ، لأن هذا موسى الذي أخرجنا من أرض مصر لا نعلم ماذا أصابه '),
(7876, 'Acts', 44, 7, 41, ' فعملوا عجلا في تلك الأيام وأصعدوا ذبيحة للصنم ، وفرحوا بأعمال أيديهم '),
(7877, 'Acts', 44, 7, 42, ' فرجع الله وأسلمهم ليعبدوا جند السماء ، كما هو مكتوب في كتاب الأنبياء : هل قربتم لي ذبائح وقرابين أربعين سنة في البرية يا بيت إسرائيل '),
(7878, 'Acts', 44, 7, 43, ' بل حملتم خيمة مولوك ، ونجم إلهكم رمفان ، التماثيل التي صنعتموها لتسجدوا لها . فأنقلكم إلى ما وراء بابل '),
(7879, 'Acts', 44, 7, 44, ' وأما خيمة الشهادة فكانت مع آبائنا في البرية ، كما أمر الذي كلم موسى أن يعملها على المثال الذي كان قد رآه '),
(7880, 'Acts', 44, 7, 45, ' التي أدخلها أيضا آباؤنا إذ تخلفوا عليها مع يشوع في ملك الأمم الذين طردهم الله من وجه آبائنا ، إلى أيام داود '),
(7881, 'Acts', 44, 7, 46, ' الذي وجد نعمة أمام الله ، والتمس أن يجد مسكنا لإله يعقوب '),
(7882, 'Acts', 44, 7, 47, ' ولكن سليمان بنى له بيتا '),
(7883, 'Acts', 44, 7, 48, ' لكن العلي لا يسكن في هياكل مصنوعات الأيادي ، كما يقول النبي '),
(7884, 'Acts', 44, 7, 49, ' السماء كرسي لي ، والأرض موطئ لقدمي . أي بيت تبنون لي ؟ يقول الرب ، وأي هو مكان راحتي '),
(7885, 'Acts', 44, 7, 50, ' أليست يدي صنعت هذه الأشياء كلها '),
(7886, 'Acts', 44, 7, 51, ' يا قساة الرقاب ، وغير المختونين بالقلوب والآذان أنتم دائما تقاومون الروح القدس . كما كان آباؤكم كذلك أنتم '),
(7887, 'Acts', 44, 7, 52, ' أي الأنبياء لم يضطهده آباؤكم ؟ وقد قتلوا الذين سبقوا فأنبأوا بمجيء البار ، الذي أنتم الآن صرتم مسلميه وقاتليه '),
(7888, 'Acts', 44, 7, 53, ' الذين أخذتم الناموس بترتيب ملائكة ولم تحفظوه '),
(7889, 'Acts', 44, 7, 54, ' فلما سمعوا هذا حنقوا بقلوبهم وصروا بأسنانهم عليه '),
(7890, 'Acts', 44, 7, 55, ' وأما هو فشخص إلى السماء وهو ممتلئ من الروح القدس ، فرأى مجد الله ، ويسوع قائما عن يمين الله '),
(7891, 'Acts', 44, 7, 56, ' فقال : ها أنا أنظر السماوات مفتوحة ، وابن الإنسان قائما عن يمين الله '),
(7892, 'Acts', 44, 7, 57, ' فصاحوا بصوت عظيم وسدوا آذانهم ، وهجموا عليه بنفس واحدة '),
(7893, 'Acts', 44, 7, 58, ' وأخرجوه خارج المدينة ورجموه . والشهود خلعوا ثيابهم عند رجلي شاب يقال له شاول '),
(7894, 'Acts', 44, 7, 59, ' فكانوا يرجمون استفانوس وهو يدعو ويقول : أيها الرب يسوع اقبل روحي '),
(7895, 'Acts', 44, 7, 60, ' ثم جثا على ركبتيه وصرخ بصوت عظيم : يا رب ، لا تقم لهم هذه الخطية . وإذ قال هذا رقد '),
(7896, 'Acts', 44, 8, 1, ' وكان شاول راضيا بقتله . وحدث في ذلك اليوم اضطهاد عظيم على الكنيسة التي في أورشليم ، فتشتت الجميع في كور اليهودية والسامرة ، ما عدا الرسل '),
(7897, 'Acts', 44, 8, 2, ' وحمل رجال أتقياء استفانوس وعملوا عليه مناحة عظيمة '),
(7898, 'Acts', 44, 8, 3, ' وأما شاول فكان يسطو على الكنيسة ، وهو يدخل البيوت ويجر رجالا ونساء ويسلمهم إلى السجن '),
(7899, 'Acts', 44, 8, 4, ' فالذين تشتتوا جالوا مبشرين بالكلمة '),
(7900, 'Acts', 44, 8, 5, ' فانحدر فيلبس إلى مدينة من السامرة وكان يكرز لهم بالمسيح '),
(7901, 'Acts', 44, 8, 6, ' وكان الجموع يصغون بنفس واحدة إلى ما يقوله فيلبس عند استماعهم ونظرهم الآيات التي صنعها '),
(7902, 'Acts', 44, 8, 7, ' لأن كثيرين من الذين بهم أرواح نجسة كانت تخرج صارخة بصوت عظيم . وكثيرون من المفلوجين والعرج شفوا '),
(7903, 'Acts', 44, 8, 8, ' فكان فرح عظيم في تلك المدينة '),
(7904, 'Acts', 44, 8, 9, ' وكان قبلا في المدينة رجل اسمه سيمون ، يستعمل السحر ويدهش شعب السامرة ، قائلا إنه شيء عظيم '),
(7905, 'Acts', 44, 8, 10, ' وكان الجميع يتبعونه من الصغير إلى الكبير قائلين : هذا هو قوة الله العظيمة '),
(7906, 'Acts', 44, 8, 11, ' وكانوا يتبعونه لكونهم قد اندهشوا زمانا طويلا بسحره '),
(7907, 'Acts', 44, 8, 12, ' ولكن لما صدقوا فيلبس وهو يبشر بالأمور المختصة بملكوت الله وباسم يسوع المسيح ، اعتمدوا رجالا ونساء '),
(7908, 'Acts', 44, 8, 13, ' وسيمون أيضا نفسه آمن . ولما اعتمد كان يلازم فيلبس ، وإذ رأى آيات وقوات عظيمة تجرى اندهش '),
(7909, 'Acts', 44, 8, 14, ' ولما سمع الرسل الذين في أورشليم أن السامرة قد قبلت كلمة الله ، أرسلوا إليهم بطرس ويوحنا '),
(7910, 'Acts', 44, 8, 15, ' اللذين لما نزلا صليا لأجلهم لكي يقبلوا الروح القدس '),
(7911, 'Acts', 44, 8, 16, ' لأنه لم يكن قد حل بعد على أحد منهم ، غير أنهم كانوا معتمدين باسم الرب يسوع '),
(7912, 'Acts', 44, 8, 17, ' حينئذ وضعا الأيادي عليهم فقبلوا الروح القدس '),
(7913, 'Acts', 44, 8, 18, ' ولما رأى سيمون أنه بوضع أيدي الرسل يعطى الروح القدس قدم لهما دراهم '),
(7914, 'Acts', 44, 8, 19, ' قائلا : أعطياني أنا أيضا هذا السلطان ، حتى أي من وضعت عليه يدي يقبل الروح القدس '),
(7915, 'Acts', 44, 8, 20, ' فقال له بطرس : لتكن فضتك معك للهلاك ، لأنك ظننت أن تقتني موهبة الله بدراهم '),
(7916, 'Acts', 44, 8, 21, ' ليس لك نصيب ولا قرعة في هذا الأمر ، لأن قلبك ليس مستقيما أمام الله '),
(7917, 'Acts', 44, 8, 22, ' فتب من شرك هذا ، واطلب إلى الله عسى أن يغفر لك فكر قلبك '),
(7918, 'Acts', 44, 8, 23, ' لأني أراك في مرارة المر ورباط الظلم '),
(7919, 'Acts', 44, 8, 24, ' فأجاب سيمون وقال : اطلبا أنتما إلى الرب من أجلي لكي لا يأتي علي شيء مما ذكرتما '),
(7920, 'Acts', 44, 8, 25, ' ثم إنهما بعد ما شهدا وتكلما بكلمة الرب ، رجعا إلى أورشليم وبشرا قرى كثيرة للسامريين '),
(7921, 'Acts', 44, 8, 26, ' ثم إن ملاك الرب كلم فيلبس قائلا : قم واذهب نحو الجنوب ، على الطريق المنحدرة من أورشليم إلى غزة التي هي برية '),
(7922, 'Acts', 44, 8, 27, ' فقام وذهب . وإذا رجل حبشي خصي ، وزير لكنداكة ملكة الحبشة ، كان على جميع خزائنها . فهذا كان قد جاء إلى أورشليم ليسجد '),
(7923, 'Acts', 44, 8, 28, ' وكان راجعا وجالسا على مركبته وهو يقرأ النبي إشعياء '),
(7924, 'Acts', 44, 8, 29, ' فقال الروح لفيلبس : تقدم ورافق هذه المركبة '),
(7925, 'Acts', 44, 8, 30, ' فبادر إليه فيلبس ، وسمعه يقرأ النبي إشعياء ، فقال : ألعلك تفهم ما أنت تقرأ '),
(7926, 'Acts', 44, 8, 31, ' فقال : كيف يمكنني إن لم يرشدني أحد ؟  . وطلب إلى فيلبس أن يصعد ويجلس معه '),
(7927, 'Acts', 44, 8, 32, ' وأما فصل الكتاب الذي كان يقرأه فكان هذا : مثل شاة سيق إلى الذبح ، ومثل خروف صامت أمام الذي يجزه هكذا لم يفتح فاه '),
(7928, 'Acts', 44, 8, 33, ' في تواضعه انتزع قضاؤه ، وجيله من يخبر به ؟ لأن حياته تنتزع من الأرض '),
(7929, 'Acts', 44, 8, 34, ' فأجاب الخصي فيلبس وقال : أطلب إليك : عن من يقول النبي هذا ؟ عن نفسه أم عن واحد آخر '),
(7930, 'Acts', 44, 8, 35, ' ففتح فيلبس فاه وابتدأ من هذا الكتاب فبشره بيسوع '),
(7931, 'Acts', 44, 8, 36, ' وفيما هما سائران في الطريق أقبلا على ماء ، فقال الخصي : هوذا ماء . ماذا يمنع أن أعتمد '),
(7932, 'Acts', 44, 8, 37, ' فقال فيلبس : إن كنت تؤمن من كل قلبك يجوز . فأجاب وقال : أنا أومن أن يسوع المسيح هو ابن الله '),
(7933, 'Acts', 44, 8, 38, ' فأمر أن تقف المركبة ، فنزلا كلاهما إلى الماء ، فيلبس والخصي ، فعمده '),
(7934, 'Acts', 44, 8, 39, ' ولما صعدا من الماء ، خطف روح الرب فيلبس ، فلم يبصره الخصي أيضا ، وذهب في طريقه فرحا '),
(7935, 'Acts', 44, 8, 40, ' وأما فيلبس فوجد في أشدود . وبينما هو مجتاز ، كان يبشر جميع المدن حتى جاء إلى قيصرية '),
(7936, 'Acts', 44, 9, 1, ' أما شاول فكان لم يزل ينفث تهددا وقتلا على تلاميذ الرب ، فتقدم إلى رئيس الكهنة '),
(7937, 'Acts', 44, 9, 2, ' وطلب منه رسائل إلى دمشق ، إلى الجماعات ، حتى إذا وجد أناسا من الطريق ، رجالا أو نساء ، يسوقهم موثقين إلى أورشليم '),
(7938, 'Acts', 44, 9, 3, ' وفي ذهابه حدث أنه اقترب إلى دمشق فبغتة أبرق حوله نور من السماء '),
(7939, 'Acts', 44, 9, 4, ' فسقط على الأرض وسمع صوتا قائلا له : شاول ، شاول لماذا تضطهدني '),
(7940, 'Acts', 44, 9, 5, ' فقال : من أنت يا سيد ؟ فقال الرب : أنا يسوع الذي أنت تضطهده . صعب عليك أن ترفس مناخس '),
(7941, 'Acts', 44, 9, 6, ' فقال وهو مرتعد ومتحير : يا رب ، ماذا تريد أن أفعل ؟ فقال له الرب : قم وادخل المدينة فيقال لك ماذا ينبغي أن تفعل '),
(7942, 'Acts', 44, 9, 7, ' وأما الرجال المسافرون معه فوقفوا صامتين ، يسمعون الصوت ولا ينظرون أحدا '),
(7943, 'Acts', 44, 9, 8, ' فنهض شاول عن الأرض ، وكان وهو مفتوح العينين لا يبصر أحدا . فاقتادوه بيده وأدخلوه إلى دمشق '),
(7944, 'Acts', 44, 9, 9, ' وكان ثلاثة أيام لا يبصر ، فلم يأكل ولم يشرب '),
(7945, 'Acts', 44, 9, 10, ' وكان في دمشق تلميذ اسمه حنانيا ، فقال له الرب في رؤيا : يا حنانيا . فقال : هأنذا يا رب '),
(7946, 'Acts', 44, 9, 11, ' فقال له الرب : قم واذهب إلى الزقاق الذي يقال له المستقيم ، واطلب في بيت يهوذا رجلا طرسوسيا اسمه شاول . لأنه هوذا يصلي '),
(7947, 'Acts', 44, 9, 12, ' وقد رأى في رؤيا رجلا اسمه حنانيا داخلا وواضعا يده عليه لكي يبصر '),
(7948, 'Acts', 44, 9, 13, ' فأجاب حنانيا : يا رب ، قد سمعت من كثيرين عن هذا الرجل ، كم من الشرور فعل بقديسيك في أورشليم '),
(7949, 'Acts', 44, 9, 14, ' وههنا له سلطان من قبل رؤساء الكهنة أن يوثق جميع الذين يدعون باسمك '),
(7950, 'Acts', 44, 9, 15, ' فقال له الرب : اذهب لأن هذا لي إناء مختار ليحمل اسمي أمام أمم وملوك وبني إسرائيل '),
(7951, 'Acts', 44, 9, 16, ' لأني سأريه كم ينبغي أن يتألم من أجل اسمي '),
(7952, 'Acts', 44, 9, 17, ' فمضى حنانيا ودخل البيت ووضع عليه يديه وقال : أيها الأخ شاول ، قد أرسلني الرب يسوع الذي ظهر لك في الطريق الذي جئت فيه ، لكي تبصر وتمتلئ من الروح القدس '),
(7953, 'Acts', 44, 9, 18, ' فللوقت وقع من عينيه شيء كأنه قشور ، فأبصر في الحال ، وقام واعتمد '),
(7954, 'Acts', 44, 9, 19, ' وتناول طعاما فتقوى . وكان شاول مع التلاميذ الذين في دمشق أياما '),
(7955, 'Acts', 44, 9, 20, ' وللوقت جعل يكرز في المجامع بالمسيح : أن هذا هو ابن الله '),
(7956, 'Acts', 44, 9, 21, ' فبهت جميع الذين كانوا يسمعون وقالوا : أليس هذا هو الذي أهلك في أورشليم الذين يدعون بهذا الاسم ؟ وقد جاء إلى هنا لهذا ليسوقهم موثقين إلى رؤساء الكهنة '),
(7957, 'Acts', 44, 9, 22, ' وأما شاول فكان يزداد قوة ، ويحير اليهود الساكنين في دمشق محققا : أن هذا هو المسيح '),
(7958, 'Acts', 44, 9, 23, ' ولما تمت أيام كثيرة تشاور اليهود ليقتلوه '),
(7959, 'Acts', 44, 9, 24, ' فعلم شاول بمكيدتهم . وكانوا يراقبون الأبواب أيضا نهارا وليلا ليقتلوه '),
(7960, 'Acts', 44, 9, 25, ' فأخذه التلاميذ ليلا وأنزلوه من السور مدلين إياه في سل '),
(7961, 'Acts', 44, 9, 26, ' ولما جاء شاول إلى أورشليم حاول أن يلتصق بالتلاميذ ، وكان الجميع يخافونه غير مصدقين أنه تلميذ '),
(7962, 'Acts', 44, 9, 27, ' فأخذه برنابا وأحضره إلى الرسل ، وحدثهم كيف أبصر الرب في الطريق وأنه كلمه ، وكيف جاهر في دمشق باسم يسوع '),
(7963, 'Acts', 44, 9, 28, ' فكان معهم يدخل ويخرج في أورشليم ويجاهر باسم الرب يسوع '),
(7964, 'Acts', 44, 9, 29, ' وكان يخاطب ويباحث اليونانيين ، فحاولوا أن يقتلوه '),
(7965, 'Acts', 44, 9, 30, ' فلما علم الإخوة أحدروه إلى قيصرية وأرسلوه إلى طرسوس '),
(7966, 'Acts', 44, 9, 31, ' وأما الكنائس في جميع اليهودية والجليل والسامرة فكان لها سلام ، وكانت تبنى وتسير في خوف الرب ، وبتعزية الروح القدس كانت تتكاثر '),
(7967, 'Acts', 44, 9, 32, ' وحدث أن بطرس وهو يجتاز بالجميع ، نزل أيضا إلى القديسين الساكنين في لدة '),
(7968, 'Acts', 44, 9, 33, ' فوجد هناك إنسانا اسمه إينياس مضطجعا على سرير منذ ثماني سنين ، وكان مفلوجا '),
(7969, 'Acts', 44, 9, 34, ' فقال له بطرس : يا إينياس ، يشفيك يسوع المسيح . قم وافرش لنفسك . فقام للوقت '),
(7970, 'Acts', 44, 9, 35, ' ورآه جميع الساكنين في لدة وسارون ، الذين رجعوا إلى الرب '),
(7971, 'Acts', 44, 9, 36, ' وكان في يافا تلميذة اسمها طابيثا ، الذي ترجمته غزالة . هذه كانت ممتلئة أعمالا صالحة وإحسانات كانت تعملها '),
(7972, 'Acts', 44, 9, 37, ' وحدث في تلك الأيام أنها مرضت وماتت ، فغسلوها ووضعوها في علية '),
(7973, 'Acts', 44, 9, 38, ' وإذ كانت لدة قريبة من يافا ، وسمع التلاميذ أن بطرس فيها ، أرسلوا رجلين يطلبان إليه أن لا يتوانى عن أن يجتاز إليهم '),
(7974, 'Acts', 44, 9, 39, ' فقام بطرس وجاء معهما . فلما وصل صعدوا به إلى العلية ، فوقفت لديه جميع الأرامل يبكين ويرين أقمصة وثيابا مما كانت تعمل غزالة وهي معهن '),
(7975, 'Acts', 44, 9, 40, ' فأخرج بطرس الجميع خارجا ، وجثا على ركبتيه وصلى ، ثم التفت إلى الجسد وقال : يا طابيثا ، قومي ففتحت عينيها . ولما أبصرت بطرس جلست '),
(7976, 'Acts', 44, 9, 41, ' فناولها يده وأقامها . ثم نادى القديسين والأرامل وأحضرها حية '),
(7977, 'Acts', 44, 9, 42, ' فصار ذلك معلوما في يافا كلها ، فآمن كثيرون بالرب '),
(7978, 'Acts', 44, 9, 43, ' ومكث أياما كثيرة في يافا ، عند سمعان رجل دباغ '),
(7979, 'Acts', 44, 10, 1, ' وكان في قيصرية رجل اسمه كرنيليوس ، قائد مئة من الكتيبة التي تدعى الإيطالية '),
(7980, 'Acts', 44, 10, 2, ' وهو تقي وخائف الله مع جميع بيته ، يصنع حسنات كثيرة للشعب ، ويصلي إلى الله في كل حين '),
(7981, 'Acts', 44, 10, 3, ' فرأى ظاهرا في رؤيا نحو الساعة التاسعة من النهار ، ملاكا من الله داخلا إليه وقائلا له : يا كرنيليوس '),
(7982, 'Acts', 44, 10, 4, ' فلما شخص إليه ودخله الخوف ، قال : ماذا يا سيد ؟ فقال له : صلواتك وصدقاتك صعدت تذكارا أمام الله '),
(7983, 'Acts', 44, 10, 5, ' والآن أرسل إلى يافا رجالا واستدع سمعان الملقب بطرس '),
(7984, 'Acts', 44, 10, 6, ' إنه نازل عند سمعان رجل دباغ بيته عند البحر . هو يقول لك ماذا ينبغي أن تفعل '),
(7985, 'Acts', 44, 10, 7, ' فلما انطلق الملاك الذي كان يكلم كرنيليوس ، نادى اثنين من خدامه ، وعسكريا تقيا من الذين كانوا يلازمونه '),
(7986, 'Acts', 44, 10, 8, ' وأخبرهم بكل شيء وأرسلهم إلى يافا '),
(7987, 'Acts', 44, 10, 9, ' ثم في الغد فيما هم يسافرون ويقتربون إلى المدينة ، صعد بطرس على السطح ليصلي نحو الساعة السادسة '),
(7988, 'Acts', 44, 10, 10, ' فجاع كثيرا واشتهى أن يأكل . وبينما هم يهيئون له ، وقعت عليه غيبة '),
(7989, 'Acts', 44, 10, 11, ' فرأى السماء مفتوحة ، وإناء نازلا عليه مثل ملاءة عظيمة مربوطة بأربعة أطراف ومدلاة على الأرض '),
(7990, 'Acts', 44, 10, 12, ' وكان فيها كل دواب الأرض والوحوش والزحافات وطيور السماء '),
(7991, 'Acts', 44, 10, 13, ' وصار إليه صوت : قم يا بطرس ، اذبح وكل '),
(7992, 'Acts', 44, 10, 14, ' فقال بطرس : كلا يا رب لأني لم آكل قط شيئا دنسا أو نجسا '),
(7993, 'Acts', 44, 10, 15, ' فصار إليه أيضا صوت ثانية : ما طهره الله لا تدنسه أنت '),
(7994, 'Acts', 44, 10, 16, ' وكان هذا على ثلاث مرات ، ثم ارتفع الإناء أيضا إلى السماء '),
(7995, 'Acts', 44, 10, 17, ' وإذ كان بطرس يرتاب في نفسه : ماذا عسى أن تكون الرؤيا التي رآها ؟  ، إذا الرجال الذين أرسلوا من قبل كرنيليوس ، وكانوا قد سألوا عن بيت سمعان وقد وقفوا على الباب '),
(7996, 'Acts', 44, 10, 18, ' ونادوا يستخبرون : هل سمعان الملقب بطرس نازل هناك '),
(7997, 'Acts', 44, 10, 19, ' وبينما بطرس متفكر في الرؤيا ، قال له الروح : هوذا ثلاثة رجال يطلبونك '),
(7998, 'Acts', 44, 10, 20, ' لكن قم وانزل واذهب معهم غير مرتاب في شيء ، لأني أنا قد أرسلتهم '),
(7999, 'Acts', 44, 10, 21, ' فنزل بطرس إلى الرجال الذين أرسلوا إليه من قبل كرنيليوس ، وقال : ها أنا الذي تطلبونه . ما هو السبب الذي حضرتم لأجله '),
(8000, 'Acts', 44, 10, 22, ' فقالوا : إن كرنيليوس قائد مئة ، رجلا بارا وخائف الله ومشهودا له من كل أمة اليهود ، أوحي إليه بملاك مقدس أن يستدعيك إلى بيته ويسمع منك كلاما '),
(8001, 'Acts', 44, 10, 23, ' فدعاهم إلى داخل وأضافهم . ثم في الغد خرج بطرس معهم ، وأناس من الإخوة الذين من يافا رافقوه '),
(8002, 'Acts', 44, 10, 24, ' وفي الغد دخلوا قيصرية . وأما كرنيليوس فكان ينتظرهم ، وقد دعا أنسباءه وأصدقاءه الأقربين '),
(8003, 'Acts', 44, 10, 25, ' ولما دخل بطرس استقبله كرنيليوس وسجد واقعا على قدميه '),
(8004, 'Acts', 44, 10, 26, ' فأقامه بطرس قائلا : قم ، أنا أيضا إنسان '),
(8005, 'Acts', 44, 10, 27, ' ثم دخل وهو يتكلم معه ووجد كثيرين مجتمعين '),
(8006, 'Acts', 44, 10, 28, ' فقال لهم : أنتم تعلمون كيف هو محرم على رجل يهودي أن يلتصق بأحد أجنبي أو يأتي إليه . وأما أنا فقد أراني الله أن لا أقول عن إنسان ما إنه دنس أو نجس '),
(8007, 'Acts', 44, 10, 29, ' فلذلك جئت من دون مناقضة إذ استدعيتموني . فأستخبركم : لأي سبب استدعيتموني '),
(8008, 'Acts', 44, 10, 30, ' فقال كرنيليوس : منذ أربعة أيام إلى هذه الساعة كنت صائما . وفي الساعة التاسعة كنت أصلي في بيتي ، وإذا رجل قد وقف أمامي بلباس لامع '),
(8009, 'Acts', 44, 10, 31, ' وقال يا كرنيليوس ، سمعت صلاتك وذكرت صدقاتك أمام الله '),
(8010, 'Acts', 44, 10, 32, ' فأرسل إلى يافا واستدع سمعان الملقب بطرس . إنه نازل في بيت سمعان رجل دباغ عند البحر . فهو متى جاء يكلمك '),
(8011, 'Acts', 44, 10, 33, ' فأرسلت إليك حالا . وأنت فعلت حسنا إذ جئت . والآن نحن جميعا حاضرون أمام الله لنسمع جميع ما أمرك به الله '),
(8012, 'Acts', 44, 10, 34, ' ففتح بطرس فاه وقال : بالحق أنا أجد أن الله لا يقبل الوجوه '),
(8013, 'Acts', 44, 10, 35, ' بل في كل أمة ، الذي يتقيه ويصنع البر مقبول عنده '),
(8014, 'Acts', 44, 10, 36, ' الكلمة التي أرسلها إلى بني إسرائيل يبشر بالسلام بيسوع المسيح . هذا هو رب الكل '),
(8015, 'Acts', 44, 10, 37, ' أنتم تعلمون الأمر الذي صار في كل اليهودية مبتدئا من الجليل ، بعد المعمودية التي كرز بها يوحنا '),
(8016, 'Acts', 44, 10, 38, ' يسوع الذي من الناصرة كيف مسحه الله بالروح القدس والقوة ، الذي جال يصنع خيرا ويشفي جميع المتسلط عليهم إبليس ، لأن الله كان معه '),
(8017, 'Acts', 44, 10, 39, ' ونحن شهود بكل ما فعل في كورة اليهودية وفي أورشليم . الذي أيضا قتلوه معلقين إياه على خشبة '),
(8018, 'Acts', 44, 10, 40, ' هذا أقامه الله في اليوم الثالث ، وأعطى أن يصير ظاهرا '),
(8019, 'Acts', 44, 10, 41, ' ليس لجميع الشعب ، بل لشهود سبق الله فانتخبهم . لنا نحن الذين أكلنا وشربنا معه بعد قيامته من الأموات '),
(8020, 'Acts', 44, 10, 42, ' وأوصانا أن نكرز للشعب ، ونشهد بأن هذا هو المعين من الله ديانا للأحياء والأموات '),
(8021, 'Acts', 44, 10, 43, ' له يشهد جميع الأنبياء أن كل من يؤمن به ينال باسمه غفران الخطايا '),
(8022, 'Acts', 44, 10, 44, ' فبينما بطرس يتكلم بهذه الأمور حل الروح القدس على جميع الذين كانوا يسمعون الكلمة '),
(8023, 'Acts', 44, 14, 26, ' ومن هناك سافرا في البحر إلى أنطاكية ، حيث كانا قد أسلما إلى نعمة الله للعمل الذي أكملاه '),
(8024, 'Acts', 44, 14, 27, ' ولما حضرا وجمعا الكنيسة ، أخبرا بكل ما صنع الله معهما ، وأنه فتح للأمم باب الإيمان '),
(8025, 'Acts', 44, 14, 28, ' وأقاما هناك زمانا ليس بقليل مع التلاميذ '),
(8026, 'Acts', 44, 15, 1, ' وانحدر قوم من اليهودية ، وجعلوا يعلمون الإخوة أنه : إن لم تختتنوا حسب عادة موسى ، لا يمكنكم أن تخلصوا '),
(8027, 'Acts', 44, 15, 2, ' فلما حصل لبولس وبرنابا منازعة ومباحثة ليست بقليلة معهم ، رتبوا أن يصعد بولس وبرنابا وأناس آخرون منهم إلى الرسل والمشايخ إلى أورشليم من أجل هذه المسألة '),
(8028, 'Acts', 44, 15, 3, ' فهؤلاء بعد ما شيعتهم الكنيسة اجتازوا في فينيقية والسامرة يخبرونهم برجوع الأمم ، وكانوا يسببون سرورا عظيما لجميع الإخوة '),
(8029, 'Acts', 44, 15, 4, ' ولما حضروا إلى أورشليم قبلتهم الكنيسة والرسل والمشايخ ، فأخبروهم بكل ما صنع الله معهم '),
(8030, 'Acts', 44, 15, 5, ' ولكن قام أناس من الذين كانوا قد آمنوا من مذهب الفريسيين ، وقالوا : إنه ينبغي أن يختنوا ، ويوصوا بأن يحفظوا ناموس موسى '),
(8031, 'Acts', 44, 15, 6, ' فاجتمع الرسل والمشايخ لينظروا في هذا الأمر '),
(8032, 'Acts', 44, 15, 7, ' فبعد ما حصلت مباحثة كثيرة قام بطرس وقال لهم : أيها الرجال الإخوة ، أنتم تعلمون أنه منذ أيام قديمة اختار الله بيننا أنه بفمي يسمع الأمم كلمة الإنجيل ويؤمنون '),
(8033, 'Acts', 44, 15, 8, ' والله العارف القلوب ، شهد لهم معطيا لهم الروح القدس كما لنا أيضا '),
(8034, 'Acts', 44, 15, 9, ' ولم يميز بيننا وبينهم بشيء ، إذ طهر بالإيمان قلوبهم '),
(8035, 'Acts', 44, 15, 10, ' فالآن لماذا تجربون الله بوضع نير على عنق التلاميذ لم يستطع آباؤنا ولا نحن أن نحمله '),
(8036, 'Acts', 44, 15, 11, ' لكن بنعمة الرب يسوع المسيح نؤمن أن نخلص كما أولئك أيضا '),
(8037, 'Acts', 44, 15, 12, ' فسكت الجمهور كله . وكانوا يسمعون برنابا وبولس يحدثان بجميع ما صنع الله من الآيات والعجائب في الأمم بواسطتهم '),
(8038, 'Acts', 44, 15, 13, ' وبعدما سكتا أجاب يعقوب قائلا : أيها الرجال الإخوة ، اسمعوني '),
(8039, 'Acts', 44, 15, 14, ' سمعان قد أخبر كيف افتقد الله أولا الأمم ليأخذ منهم شعبا على اسمه '),
(8040, 'Acts', 44, 15, 15, ' وهذا توافقه أقوال الأنبياء ، كما هو مكتوب '),
(8041, 'Acts', 44, 15, 16, ' سأرجع بعد هذا وأبني أيضا خيمة داود الساقطة ، وأبني أيضا ردمها وأقيمها ثانية '),
(8042, 'Acts', 44, 15, 17, ' لكي يطلب الباقون من الناس الرب ، وجميع الأمم الذين دعي اسمي عليهم ، يقول الرب ، الصانع هذا كله '),
(8043, 'Acts', 44, 15, 18, ' معلومة عند الرب منذ الأزل جميع أعماله '),
(8044, 'Acts', 44, 15, 19, ' لذلك أنا أرى أن لا يثقل على الراجعين إلى الله من الأمم '),
(8045, 'Acts', 44, 15, 20, ' بل يرسل إليهم أن يمتنعوا عن نجاسات الأصنام ، والزنا ، والمخنوق ، والدم '),
(8046, 'Acts', 44, 15, 21, ' لأن موسى منذ أجيال قديمة ، له في كل مدينة من يكرز به ، إذ يقرأ في المجامع كل سبت '),
(8047, 'Acts', 44, 15, 22, ' حينئذ رأى الرسل والمشايخ مع كل الكنيسة أن يختاروا رجلين منهم ، فيرسلوهما إلى أنطاكية مع بولس وبرنابا : يهوذا الملقب برسابا ، وسيلا ، رجلين متقدمين في الإخوة '),
(8048, 'Acts', 44, 15, 23, ' وكتبوا بأيديهم هكذا : الرسل والمشايخ والإخوة يهدون سلاما إلى الإخوة الذين من الأمم في أنطاكية وسورية وكيليكية '),
(8049, 'Acts', 44, 15, 24, ' إذ قد سمعنا أن أناسا خارجين من عندنا أزعجوكم بأقوال ، مقلبين أنفسكم ، وقائلين أن تختتنوا وتحفظوا الناموس ، الذين نحن لم نأمرهم '),
(8050, 'Acts', 44, 15, 25, ' رأينا وقد صرنا بنفس واحدة أن نختار رجلين ونرسلهما إليكم مع حبيبينا برنابا وبولس '),
(8051, 'Acts', 44, 15, 26, ' رجلين قد بذلا نفسيهما لأجل اسم ربنا يسوع المسيح '),
(8052, 'Acts', 44, 15, 27, ' فقد أرسلنا يهوذا وسيلا ، وهما يخبرانكم بنفس الأمور شفاها '),
(8053, 'Acts', 44, 15, 28, ' لأنه قد رأى الروح القدس ونحن ، أن لا نضع عليكم ثقلا أكثر ، غير هذه الأشياء الواجبة '),
(8054, 'Acts', 44, 15, 29, ' أن تمتنعوا عما ذبح للأصنام ، وعن الدم ، والمخنوق ، والزنا ، التي إن حفظتم أنفسكم منها فنعما تفعلون . كونوا معافين '),
(8055, 'Acts', 44, 15, 30, ' فهؤلاء لما أطلقوا جاءوا إلى أنطاكية ، وجمعوا الجمهور ودفعوا الرسالة '),
(8056, 'Acts', 44, 15, 31, ' فلما قرأوها فرحوا لسبب التعزية '),
(8057, 'Acts', 44, 15, 32, ' ويهوذا وسيلا ، إذ كانا هما أيضا نبيين ، وعظا الإخوة بكلام كثير وشدداهم '),
(8058, 'Acts', 44, 15, 33, ' ثم بعد ما صرفا زمانا أطلقا بسلام من الإخوة إلى الرسل '),
(8059, 'Acts', 44, 15, 34, ' ولكن سيلا رأى أن يلبث هناك '),
(8060, 'Acts', 44, 15, 35, ' أما بولس وبرنابا فأقاما في أنطاكية يعلمان ويبشران مع آخرين كثيرين أيضا بكلمة الرب '),
(8061, 'Acts', 44, 15, 36, ' ثم بعد أيام قال بولس لبرنابا : لنرجع ونفتقد إخوتنا في كل مدينة نادينا فيها بكلمة الرب ، كيف هم '),
(8062, 'Acts', 44, 15, 37, ' فأشار برنابا أن يأخذا معهما أيضا يوحنا الذي يدعى مرقس '),
(8063, 'Acts', 44, 15, 38, ' وأما بولس فكان يستحسن أن الذي فارقهما من بمفيلية ولم يذهب معهما للعمل ، لا يأخذانه معهما '),
(8064, 'Acts', 44, 15, 39, ' فحصل بينهما مشاجرة حتى فارق أحدهما الآخر . وبرنابا أخذ مرقس وسافر في البحر إلى قبرس '),
(8065, 'Acts', 44, 15, 40, ' وأما بولس فاختار سيلا وخرج مستودعا من الإخوة إلى نعمة الله '),
(8066, 'Acts', 44, 15, 41, ' فاجتاز في سورية وكيليكية يشدد الكنائس '),
(8067, 'Acts', 44, 16, 1, ' ثم وصل إلى دربة ولسترة ، وإذا تلميذ كان هناك اسمه تيموثاوس ، ابن امرأة يهودية مؤمنة ولكن أباه يوناني '),
(8068, 'Acts', 44, 16, 2, ' وكان مشهودا له من الإخوة الذين في لسترة وإيقونية '),
(8069, 'Acts', 44, 16, 3, ' فأراد بولس أن يخرج هذا معه ، فأخذه وختنه من أجل اليهود الذين في تلك الأماكن ، لأن الجميع كانوا يعرفون أباه أنه يوناني '),
(8070, 'Acts', 44, 16, 4, ' وإذ كانوا يجتازون في المدن كانوا يسلمونهم القضايا التي حكم بها الرسل والمشايخ الذين في أورشليم ليحفظوها '),
(8071, 'Acts', 44, 16, 5, ' فكانت الكنائس تتشدد في الإيمان وتزداد في العدد كل يوم '),
(8072, 'Acts', 44, 16, 6, ' وبعد ما اجتازوا في فريجية وكورة غلاطية ، منعهم الروح القدس أن يتكلموا بالكلمة في أسيا '),
(8073, 'Acts', 44, 16, 7, ' فلما أتوا إلى ميسيا حاولوا أن يذهبوا إلى بثينية ، فلم يدعهم الروح '),
(8074, 'Acts', 44, 16, 8, ' فمروا على ميسيا وانحدروا إلى ترواس '),
(8075, 'Acts', 44, 16, 9, ' وظهرت لبولس رؤيا في الليل : رجل مكدوني قائم يطلب إليه ويقول : اعبر إلى مكدونية وأعنا '),
(8076, 'Acts', 44, 16, 10, ' فلما رأى الرؤيا للوقت طلبنا أن نخرج إلى مكدونية ، متحققين أن الرب قد دعانا لنبشرهم '),
(8077, 'Acts', 44, 16, 11, ' فأقلعنا من ترواس وتوجهنا بالاستقامة إلى ساموثراكي ، وفي الغد إلى نيابوليس '),
(8078, 'Acts', 44, 16, 12, ' ومن هناك إلى فيلبي ، التي هي أول مدينة من مقاطعة مكدونية ، وهي كولونية . فأقمنا في هذه المدينة أياما '),
(8079, 'Acts', 44, 16, 13, ' وفي يوم السبت خرجنا إلى خارج المدينة عند نهر ، حيث جرت العادة أن تكون صلاة ، فجلسنا وكنا نكلم النساء اللواتي اجتمعن '),
(8080, 'Acts', 44, 16, 14, ' فكانت تسمع امرأة اسمها ليدية ، بياعة أرجوان من مدينة ثياتيرا ، متعبدة لله ، ففتح الرب قلبها لتصغي إلى ما كان يقوله بولس '),
(8081, 'Acts', 44, 16, 15, ' فلما اعتمدت هي وأهل بيتها طلبت قائلة : إن كنتم قد حكمتم أني مؤمنة بالرب ، فادخلوا بيتي وامكثوا . فألزمتنا '),
(8082, 'Acts', 44, 16, 16, ' وحدث بينما كنا ذاهبين إلى الصلاة ، أن جارية بها روح عرافة استقبلتنا . وكانت تكسب مواليها مكسبا كثيرا بعرافتها '),
(8083, 'Acts', 44, 16, 17, ' هذه اتبعت بولس وإيانا وصرخت قائلة : هؤلاء الناس هم عبيد الله العلي ، الذين ينادون لكم بطريق الخلاص '),
(8084, 'Acts', 44, 16, 18, ' وكانت تفعل هذا أياما كثيرة . فضجر بولس والتفت إلى الروح وقال : أنا آمرك باسم يسوع المسيح أن تخرج منها . فخرج في تلك الساعة '),
(8085, 'Acts', 44, 16, 19, ' فلما رأى مواليها أنه قد خرج رجاء مكسبهم ، أمسكوا بولس وسيلا وجروهما إلى السوق إلى الحكام '),
(8086, 'Acts', 44, 16, 20, ' وإذ أتوا بهما إلى الولاة ، قالوا : هذان الرجلان يبلبلان مدينتنا ، وهما يهوديان '),
(8087, 'Acts', 44, 16, 21, ' ويناديان بعوائد لا يجوز لنا أن نقبلها ولا نعمل بها ، إذ نحن رومانيون '),
(8088, 'Acts', 44, 16, 22, ' فقام الجمع معا عليهما ، ومزق الولاة ثيابهما وأمروا أن يضربا بالعصي '),
(8089, 'Acts', 44, 16, 23, ' فوضعوا عليهما ضربات كثيرة وألقوهما في السجن ، وأوصوا حافظ السجن أن يحرسهما بضبط '),
(8090, 'Acts', 44, 16, 24, ' وهو إذ أخذ وصية مثل هذه ، ألقاهما في السجن الداخلي ، وضبط أرجلهما في المقطرة '),
(8091, 'Acts', 44, 16, 25, ' ونحو نصف الليل كان بولس وسيلا يصليان ويسبحان الله ، والمسجونون يسمعونهما '),
(8092, 'Acts', 44, 16, 26, ' فحدث بغتة زلزلة عظيمة حتى تزعزعت أساسات السجن ، فانفتحت في الحال الأبواب كلها ، وانفكت قيود الجميع '),
(8093, 'Acts', 44, 16, 27, ' ولما استيقظ حافظ السجن ، ورأى أبواب السجن مفتوحة ، استل سيفه وكان مزمعا أن يقتل نفسه ، ظانا أن المسجونين قد هربوا '),
(8094, 'Acts', 44, 16, 28, ' فنادى بولس بصوت عظيم قائلا : لا تفعل بنفسك شيئا رديا لأن جميعنا ههنا '),
(8095, 'Acts', 44, 16, 29, ' فطلب ضوءا واندفع إلى داخل ، وخر لبولس وسيلا وهو مرتعد '),
(8096, 'Acts', 44, 16, 30, ' ثم أخرجهما وقال : يا سيدي ، ماذا ينبغي أن أفعل لكي أخلص '),
(8097, 'Acts', 44, 16, 31, ' فقالا : آمن بالرب يسوع المسيح فتخلص أنت وأهل بيتك '),
(8098, 'Acts', 44, 16, 32, ' وكلماه وجميع من في بيته بكلمة الرب '),
(8099, 'Acts', 44, 16, 33, ' فأخذهما في تلك الساعة من الليل وغسلهما من الجراحات ، واعتمد في الحال هو والذين له أجمعون '),
(8100, 'Acts', 44, 16, 34, ' ولما أصعدهما إلى بيته قدم لهما مائدة ، وتهلل مع جميع بيته إذ كان قد آمن بالله '),
(8101, 'Acts', 44, 16, 35, ' ولما صار النهار أرسل الولاة الجلادين قائلين : أطلق ذينك الرجلين '),
(8102, 'Acts', 44, 16, 36, ' فأخبر حافظ السجن بولس بهذا الكلام أن الولاة قد أرسلوا أن تطلقا ، فاخرجا الآن واذهبا بسلام '),
(8103, 'Acts', 44, 16, 37, ' فقال لهم بولس : ضربونا جهرا غير مقضي علينا ، ونحن رجلان رومانيان ، وألقونا في السجن . أفالآن يطردوننا سرا ؟ كلا بل ليأتوا هم أنفسهم ويخرجونا '),
(8104, 'Acts', 44, 16, 38, ' فأخبر الجلادون الولاة بهذا الكلام ، فاختشوا لما سمعوا أنهما رومانيان '),
(8105, 'Acts', 44, 16, 39, ' فجاءوا وتضرعوا إليهما وأخرجوهما ، وسألوهما أن يخرجا من المدينة '),
(8106, 'Acts', 44, 16, 40, ' فخرجا من السجن ودخلا عند ليدية ، فأبصرا الإخوة وعزياهم ثم خرجا '),
(8107, 'Acts', 44, 17, 1, ' فاجتازا في أمفيبوليس وأبولونية ، وأتيا إلى تسالونيكي ، حيث كان مجمع اليهود '),
(8108, 'Acts', 44, 17, 2, ' فدخل بولس إليهم حسب عادته ، وكان يحاجهم ثلاثة سبوت من الكتب '),
(8109, 'Acts', 44, 17, 3, ' موضحا ومبينا أنه كان ينبغي أن المسيح يتألم ويقوم من الأموات ، وأن : هذا هو المسيح يسوع الذي أنا أنادي لكم به '),
(8110, 'Acts', 44, 17, 4, ' فاقتنع قوم منهم وانحازوا إلى بولس وسيلا ، ومن اليونانيين المتعبدين جمهور كثير ، ومن النساء المتقدمات عدد ليس بقليل '),
(8111, 'Acts', 44, 17, 5, ' فغار اليهود غير المؤمنين واتخذوا رجالا أشرارا من أهل السوق ، وتجمعوا وسجسوا المدينة ، وقاموا على بيت ياسون طالبين أن يحضروهما إلى الشعب '),
(8112, 'Acts', 44, 17, 6, ' ولما لم يجدوهما ، جروا ياسون وأناسا من الإخوة إلى حكام المدينة صارخين : إن هؤلاء الذين فتنوا المسكونة حضروا إلى ههنا أيضا '),
(8113, 'Acts', 44, 17, 7, ' وقد قبلهم ياسون . وهؤلاء كلهم يعملون ضد أحكام قيصر قائلين : إنه يوجد ملك آخر : يسوع '),
(8114, 'Acts', 44, 17, 8, ' فأزعجوا الجمع وحكام المدينة إذ سمعوا هذا '),
(8115, 'Acts', 44, 17, 9, ' فأخذوا كفالة من ياسون ومن الباقين ، ثم أطلقوهم '),
(8116, 'Acts', 44, 17, 10, ' وأما الإخوة فللوقت أرسلوا بولس وسيلا ليلا إلى بيرية . وهما لما وصلا مضيا إلى مجمع اليهود '),
(8117, 'Acts', 44, 17, 11, ' وكان هؤلاء أشرف من الذين في تسالونيكي ، فقبلوا الكلمة بكل نشاط فاحصين الكتب كل يوم : هل هذه الأمور هكذا '),
(8118, 'Acts', 44, 17, 12, ' فآمن منهم كثيرون ، ومن النساء اليونانيات الشريفات ، ومن الرجال عدد ليس بقليل '),
(8119, 'Acts', 44, 17, 13, ' فلما علم اليهود الذين من تسالونيكي أنه في بيرية أيضا نادى بولس بكلمة الله ، جاءوا يهيجون الجموع هناك أيضا '),
(8120, 'Acts', 44, 17, 14, ' فحينئذ أرسل الإخوة بولس للوقت ليذهب كما إلى البحر ، وأما سيلا وتيموثاوس فبقيا هناك '),
(8121, 'Acts', 44, 17, 15, ' والذين صاحبوا بولس جاءوا به إلى أثينا . ولما أخذوا وصية إلى سيلا وتيموثاوس أن يأتيا إليه بأسرع ما يمكن ، مضوا '),
(8122, 'Acts', 44, 17, 16, ' وبينما بولس ينتظرهما في أثينا احتدت روحه فيه ، إذ رأى المدينة مملؤة أصناما '),
(8123, 'Acts', 44, 17, 17, ' فكان يكلم في المجمع اليهود المتعبدين ، والذين يصادفونه في السوق كل يوم '),
(8124, 'Acts', 44, 17, 18, ' فقابله قوم من الفلاسفة الأبيكوريين والرواقيين ، وقال بعض : ترى ماذا يريد هذا المهذار أن يقول ؟ وبعض : إنه يظهر مناديا بآلهة غريبة . لأنه كان يبشرهم بيسوع والقيامة '),
(8125, 'Acts', 44, 17, 19, ' فأخذوه وذهبوا به إلى أريوس باغوس ، قائلين : هل يمكننا أن نعرف ما هو هذا التعليم الجديد الذي تتكلم به '),
(8126, 'Acts', 44, 17, 20, ' لأنك تأتي إلى مسامعنا بأمور غريبة ، فنريد أن نعلم ما عسى أن تكون هذه '),
(8127, 'Acts', 44, 17, 21, ' أما الأثينويون أجمعون والغرباء المستوطنون ، فلا يتفرغون لشيء آخر ، إلا لأن يتكلموا أو يسمعوا شيئا حديثا '),
(8128, 'Acts', 44, 17, 22, ' فوقف بولس في وسط أريوس باغوس وقال : أيها الرجال الأثينويون أراكم من كل وجه كأنكم متدينون كثيرا '),
(8129, 'Acts', 44, 17, 23, ' لأنني بينما كنت أجتاز وأنظر إلى معبوداتكم ، وجدت أيضا مذبحا مكتوبا عليه : لإله مجهول . فالذي تتقونه وأنتم تجهلونه ، هذا أنا أنادي لكم به '),
(8130, 'Acts', 44, 17, 24, ' الإله الذي خلق العالم وكل ما فيه ، هذا ، إذ هو رب السماء والأرض ، لا يسكن في هياكل مصنوعة بالأيادي '),
(8131, 'Acts', 44, 17, 25, ' ولا يخدم بأيادي الناس كأنه محتاج إلى شيء ، إذ هو يعطي الجميع حياة ونفسا وكل شيء '),
(8132, 'Acts', 44, 17, 26, ' وصنع من دم واحد كل أمة من الناس يسكنون على كل وجه الأرض ، وحتم بالأوقات المعينة وبحدود مسكنهم '),
(8133, 'Acts', 44, 17, 27, ' لكي يطلبوا الله لعلهم يتلمسونه فيجدوه ، مع أنه عن كل واحد منا ليس بعيدا '),
(8134, 'Acts', 44, 17, 28, ' لأننا به نحيا ونتحرك ونوجد ، كما قال بعض شعرائكم أيضا : لأننا أيضا ذريته '),
(8135, 'Acts', 44, 17, 29, ' فإذ نحن ذرية الله ، لا ينبغي أن نظن أن اللاهوت شبيه بذهب أو فضة أو حجر نقش صناعة واختراع إنسان '),
(8136, 'Acts', 44, 17, 30, ' فالله الآن يأمر جميع الناس في كل مكان أن يتوبوا ، متغاضيا عن أزمنة الجهل '),
(8137, 'Acts', 44, 17, 31, ' لأنه أقام يوما هو فيه مزمع أن يدين المسكونة بالعدل ، برجل قد عينه ، مقدما للجميع إيمانا إذ أقامه من الأموات '),
(8138, 'Acts', 44, 17, 32, ' ولما سمعوا بالقيامة من الأموات كان البعض يستهزئون ، والبعض يقولون : سنسمع منك عن هذا أيضا '),
(8139, 'Acts', 44, 17, 33, ' وهكذا خرج بولس من وسطهم '),
(8140, 'Acts', 44, 17, 34, ' ولكن أناسا التصقوا به وآمنوا ، منهم ديونيسيوس الأريوباغي ، وامرأة اسمها دامرس وآخرون معهما '),
(8141, 'Acts', 44, 18, 1, ' وبعد هذا مضى بولس من أثينا وجاء إلى كورنثوس '),
(8142, 'Acts', 44, 18, 2, ' فوجد يهوديا اسمه أكيلا ، بنطي الجنس ، كان قد جاء حديثا من إيطالية ، وبريسكلا امرأته ، لأن كلوديوس كان قد أمر أن يمضي جميع اليهود من رومية ، فجاء إليهما '),
(8143, 'Acts', 44, 18, 3, ' ولكونه من صناعتهما أقام عندهما وكان يعمل ، لأنهما كانا في صناعتهما خياميين '),
(8144, 'Acts', 44, 18, 4, ' وكان يحاج في المجمع كل سبت ويقنع يهودا ويونانيين '),
(8145, 'Acts', 44, 18, 5, ' ولما انحدر سيلا وتيموثاوس من مكدونية ، كان بولس منحصرا بالروح وهو يشهد لليهود بالمسيح يسوع '),
(8146, 'Acts', 44, 18, 6, ' وإذ كانوا يقاومون ويجدفون نفض ثيابه وقال لهم : دمكم على رؤوسكم أنا بريء . من الآن أذهب إلى الأمم '),
(8147, 'Acts', 44, 18, 7, ' فانتقل من هناك وجاء إلى بيت رجل اسمه يوستس ، كان متعبدا لله ، وكان بيته ملاصقا للمجمع '),
(8148, 'Acts', 44, 18, 8, ' وكريسبس رئيس المجمع آمن بالرب مع جميع بيته ، وكثيرون من الكورنثيين إذ سمعوا آمنوا واعتمدوا '),
(8149, 'Acts', 44, 18, 9, ' فقال الرب لبولس برؤيا في الليل : لا تخف ، بل تكلم ولا تسكت '),
(8150, 'Acts', 44, 18, 10, ' لأني أنا معك ، ولا يقع بك أحد ليؤذيك ، لأن لي شعبا كثيرا في هذه المدينة '),
(8151, 'Acts', 44, 18, 11, ' فأقام سنة وستة أشهر يعلم بينهم بكلمة الله '),
(8152, 'Acts', 44, 18, 12, ' ولما كان غاليون يتولى أخائية ، قام اليهود بنفس واحدة على بولس ، وأتوا به إلى كرسي الولاية '),
(8153, 'Acts', 44, 18, 13, ' قائلين : إن هذا يستميل الناس أن يعبدوا الله بخلاف الناموس '),
(8154, 'Acts', 44, 18, 14, ' وإذ كان بولس مزمعا أن يفتح فاه قال غاليون لليهود : لو كان ظلما أو خبثا رديا أيها اليهود ، لكنت بالحق قد احتملتكم '),
(8155, 'Acts', 44, 18, 15, ' ولكن إذا كان مسألة عن : كلمة ، وأسماء ، وناموسكم ، فتبصرون أنتم . لأني لست أشاء أن أكون قاضيا لهذه الأمور '),
(8156, 'Acts', 44, 18, 16, ' فطردهم من الكرسي '),
(8157, 'Acts', 44, 18, 17, ' فأخذ جميع اليونانيين سوستانيس رئيس المجمع ، وضربوه قدام الكرسي ، ولم يهم غاليون شيء من ذلك '),
(8158, 'Acts', 44, 18, 18, ' وأما بولس فلبث أيضا أياما كثيرة ، ثم ودع الإخوة وسافر في البحر إلى سورية ، ومعه بريسكلا وأكيلا ، بعدما حلق رأسه في كنخريا لأنه كان عليه نذر '),
(8159, 'Acts', 44, 18, 19, ' فأقبل إلى أفسس وتركهما هناك . وأما هو فدخل المجمع وحاج اليهود '),
(8160, 'Acts', 44, 18, 20, ' وإذ كانوا يطلبون أن يمكث عندهم زمانا أطول لم يجب '),
(8161, 'Acts', 44, 18, 21, ' بل ودعهم قائلا : ينبغي على كل حال أن أعمل العيد القادم في أورشليم . ولكن سأرجع إليكم أيضا إن شاء الله . فأقلع من أفسس '),
(8162, 'Acts', 44, 18, 22, ' ولما نزل في قيصرية صعد وسلم على الكنيسة ، ثم انحدر إلى أنطاكية '),
(8163, 'Acts', 44, 18, 23, ' وبعدما صرف زمانا خرج واجتاز بالتتابع في كورة غلاطية وفريجية يشدد جميع التلاميذ '),
(8164, 'Acts', 44, 18, 24, ' ثم أقبل إلى أفسس يهودي اسمه أبلوس ، إسكندري الجنس ، رجل فصيح مقتدر في الكتب '),
(8165, 'Acts', 44, 18, 25, ' كان هذا خبيرا في طريق الرب . وكان وهو حار بالروح يتكلم ويعلم بتدقيق ما يختص بالرب . عارفا معمودية يوحنا فقط '),
(8166, 'Acts', 44, 18, 26, ' وابتدأ هذا يجاهر في المجمع . فلما سمعه أكيلا وبريسكلا أخذاه إليهما ، وشرحا له طريق الرب بأكثر تدقيق '),
(8167, 'Acts', 44, 18, 27, ' وإذ كان يريد أن يجتاز إلى أخائية ، كتب الإخوة إلى التلاميذ يحضونهم أن يقبلوه . فلما جاء ساعد كثيرا بالنعمة الذين كانوا قد آمنوا '),
(8168, 'Acts', 44, 18, 28, ' لأنه كان باشتداد يفحم اليهود جهرا ، مبينا بالكتب أن يسوع هو المسيح '),
(8169, 'Acts', 44, 19, 1, ' فحدث فيما كان أبلوس في كورنثوس ، أن بولس بعد ما اجتاز في النواحي العالية جاء إلى أفسس . فإذ وجد تلاميذ '),
(8170, 'Acts', 44, 19, 2, ' قال لهم : هل قبلتم الروح القدس لما آمنتم ؟ قالوا له : ولا سمعنا أنه يوجد الروح القدس '),
(8171, 'Acts', 44, 19, 3, ' فقال لهم : فبماذا اعتمدتم ؟ فقالوا : بمعمودية يوحنا '),
(8172, 'Acts', 44, 19, 4, ' فقال بولس : إن يوحنا عمد بمعمودية التوبة ، قائلا للشعب أن يؤمنوا بالذي يأتي بعده ، أي بالمسيح يسوع '),
(8173, 'Acts', 44, 19, 5, ' فلما سمعوا اعتمدوا باسم الرب يسوع '),
(8174, 'Acts', 44, 19, 6, ' ولما وضع بولس يديه عليهم حل الروح القدس عليهم ، فطفقوا يتكلمون بلغات ويتنبأون '),
(8175, 'Acts', 44, 19, 7, ' وكان جميع الرجال نحو اثني عشر '),
(8176, 'Acts', 44, 19, 8, ' ثم دخل المجمع ، وكان يجاهر مدة ثلاثة أشهر محاجا ومقنعا في ما يختص بملكوت الله '),
(8177, 'Acts', 44, 19, 9, ' ولما كان قوم يتقسون ولا يقنعون ، شاتمين الطريق أمام الجمهور ، اعتزل عنهم وأفرز التلاميذ ، محاجا كل يوم في مدرسة إنسان اسمه تيرانس '),
(8178, 'Acts', 44, 19, 10, ' وكان ذلك مدة سنتين ، حتى سمع كلمة الرب يسوع جميع الساكنين في أسيا ، من يهود ويونانيين '),
(8179, 'Acts', 44, 19, 11, ' وكان الله يصنع على يدي بولس قوات غير المعتادة '),
(8180, 'Acts', 44, 19, 12, ' حتى كان يؤتى عن جسده بمناديل أو مآزر إلى المرضى ، فتزول عنهم الأمراض ، وتخرج الأرواح الشريرة منهم '),
(8181, 'Acts', 44, 19, 13, ' فشرع قوم من اليهود الطوافين المعزمين أن يسموا على الذين بهم الأرواح الشريرة باسم الرب يسوع ، قائلين : نقسم عليك بيسوع الذي يكرز به بولس '),
(8182, 'Acts', 44, 19, 14, ' وكان سبعة بنين لسكاوا ، رجل يهودي رئيس كهنة ، الذين فعلوا هذا '),
(8183, 'Acts', 44, 19, 15, ' فأجاب الروح الشرير وقال : أما يسوع فأنا أعرفه ، وبولس أنا أعلمه ، وأما أنتم فمن أنتم '),
(8184, 'Acts', 44, 19, 16, ' فوثب عليهم الإنسان الذي كان فيه الروح الشرير ، وغلبهم وقوي عليهم ، حتى هربوا من ذلك البيت عراة ومجرحين '),
(8185, 'Acts', 44, 19, 17, ' وصار هذا معلوما عند جميع اليهود واليونانيين الساكنين في أفسس . فوقع خوف على جميعهم ، وكان اسم الرب يسوع يتعظم '),
(8186, 'Acts', 44, 19, 18, ' وكان كثيرون من الذين آمنوا يأتون مقرين ومخبرين بأفعالهم '),
(8187, 'Acts', 44, 19, 19, ' وكان كثيرون من الذين يستعملون السحر يجمعون الكتب ويحرقونها أمام الجميع . وحسبوا أثمانها فوجدوها خمسين ألفا من الفضة '),
(8188, 'Acts', 44, 19, 20, ' هكذا كانت كلمة الرب تنمو وتقوى بشدة '),
(8189, 'Acts', 44, 19, 21, ' ولما كملت هذه الأمور ، وضع بولس في نفسه أنه بعدما يجتاز في مكدونية وأخائية يذهب إلى أورشليم ، قائلا : إني بعد ما أصير هناك ينبغي أن أرى رومية أيضا '),
(8190, 'Acts', 44, 19, 22, ' فأرسل إلى مكدونية اثنين من الذين كانوا يخدمونه : تيموثاوس وأرسطوس ، ولبث هو زمانا في أسيا '),
(8191, 'Acts', 44, 19, 23, ' وحدث في ذلك الوقت شغب ليس بقليل بسبب هذا الطريق '),
(8192, 'Acts', 44, 19, 24, ' لأن إنسانا اسمه ديمتريوس ، صائغ صانع هياكل فضة لأرطاميس ، كان يكسب الصناع مكسبا ليس بقليل '),
(8193, 'Acts', 44, 19, 25, ' فجمعهم والفعلة في مثل ذلك العمل وقال : أيها الرجال أنتم تعلمون أن سعتنا إنما هي من هذه الصناعة '),
(8194, 'Acts', 44, 19, 26, ' وأنتم تنظرون وتسمعون أنه ليس من أفسس فقط ، بل من جميع أسيا تقريبا ، استمال وأزاغ بولس هذا جمعا كثيرا قائلا : إن التي تصنع بالأيادي ليست آلهة '),
(8195, 'Acts', 44, 19, 27, ' فليس نصيبنا هذا وحده في خطر من أن يحصل في إهانة ، بل أيضا هيكل أرطاميس ، الإلهة العظيمة ، أن يحسب لا شيء ، وأن سوف تهدم عظمتها ، هي التي يعبدها جميع أسيا والمسكونة '),
(8196, 'Acts', 44, 19, 28, ' فلما سمعوا امتلأوا غضبا ، وطفقوا يصرخون قائلين : عظيمة هي أرطاميس الأفسسيين '),
(8197, 'Acts', 44, 19, 29, ' فامتلأت المدينة كلها اضطرابا ، واندفعوا بنفس واحدة إلى المشهد خاطفين معهم غايوس وأرسترخس المكدونيين ، رفيقي بولس في السفر '),
(8198, 'Acts', 44, 19, 30, ' ولما كان بولس يريد أن يدخل بين الشعب ، لم يدعه التلاميذ '),
(8199, 'Acts', 44, 19, 31, ' وأناس من وجوه أسيا ، كانوا أصدقاءه ، أرسلوا يطلبون إليه أن لا يسلم نفسه إلى المشهد '),
(8200, 'Acts', 44, 19, 32, ' وكان البعض يصرخون بشيء والبعض بشيء آخر ، لأن المحفل كان مضطربا ، وأكثرهم لا يدرون لأي شيء كانوا قد اجتمعوا '),
(8201, 'Acts', 44, 19, 33, ' فاجتذبوا إسكندر من الجمع ، وكان اليهود يدفعونه . فأشار إسكندر بيده يريد أن يحتج للشعب '),
(8202, 'Acts', 44, 19, 34, ' فلما عرفوا أنه يهودي ، صار صوت واحد من الجميع صارخين نحو مدة ساعتين : عظيمة هي أرطاميس الأفسسيين '),
(8203, 'Acts', 44, 19, 35, ' ثم سكن الكاتب الجمع وقال : أيها الرجال الأفسسيون ، من هو الإنسان الذي لا يعلم أن مدينة الأفسسيين متعبدة لأرطاميس الإلهة العظيمة والتمثال الذي هبط من زفس '),
(8204, 'Acts', 44, 19, 36, ' فإذ كانت هذه الأشياء لا تقاوم ، ينبغي أن تكونوا هادئين ولا تفعلوا شيئا اقتحاما '),
(8205, 'Acts', 44, 19, 37, ' لأنكم أتيتم بهذين الرجلين ، وهما ليسا سارقي هياكل ، ولا مجدفين على إلهتكم '),
(8206, 'Acts', 44, 19, 38, ' فإن كان ديمتريوس والصناع الذين معه لهم دعوى على أحد ، فإنه تقام أيام للقضاء ، ويوجد ولاة ، فليرافعوا بعضهم بعضا '),
(8207, 'Acts', 44, 19, 39, ' وإن كنتم تطلبون شيئا من جهة أمور أخر ، فإنه يقضى في محفل شرعي '),
(8208, 'Acts', 44, 19, 40, ' لأننا في خطر أن نحاكم من أجل فتنة هذا اليوم . وليس علة يمكننا من أجلها أن نقدم حسابا عن هذا التجمع '),
(8209, 'Acts', 44, 19, 41, ' ولما قال هذا صرف المحفل '),
(8210, 'Acts', 44, 20, 1, ' وبعدما انتهى الشغب ، دعا بولس التلاميذ وودعهم ، وخرج ليذهب إلى مكدونية '),
(8211, 'Acts', 44, 20, 2, ' ولما كان قد اجتاز في تلك النواحي ووعظهم بكلام كثير ، جاء إلى هلاس '),
(8212, 'Acts', 44, 20, 3, ' فصرف ثلاثة أشهر . ثم إذ حصلت مكيدة من اليهود عليه ، وهو مزمع أن يصعد إلى سورية ، صار رأي أن يرجع على طريق مكدونية '),
(8213, 'Acts', 44, 20, 4, ' فرافقه إلى أسيا سوباترس البيري ، ومن أهل تسالونيكي : أرسترخس وسكوندس وغايوس الدربي وتيموثاوس . ومن أهل أسيا : تيخيكس وتروفيمس '),
(8214, 'Acts', 44, 20, 5, ' هؤلاء سبقوا وانتظرونا في ترواس '),
(8215, 'Acts', 44, 20, 6, ' وأما نحن فسافرنا في البحر بعد أيام الفطير من فيلبي ، ووافيناهم في خمسة أيام إلى ترواس ، حيث صرفنا سبعة أيام '),
(8216, 'Acts', 44, 20, 7, ' وفي أول الأسبوع إذ كان التلاميذ مجتمعين ليكسروا خبزا ، خاطبهم بولس وهو مزمع أن يمضي في الغد ، وأطال الكلام إلى نصف الليل '),
(8217, 'Acts', 44, 20, 8, ' وكانت مصابيح كثيرة في العلية التي كانوا مجتمعين فيها '),
(8218, 'Acts', 44, 20, 9, ' وكان شاب اسمه أفتيخوس جالسا في الطاقة متثقلا بنوم عميق . وإذ كان بولس يخاطب خطابا طويلا ، غلب عليه النوم فسقط من الطبقة الثالثة إلى أسفل ، وحمل ميتا '),
(8219, 'Acts', 44, 20, 10, ' فنزل بولس ووقع عليه واعتنقه قائلا : لا تضطربوا لأن نفسه فيه '),
(8220, 'Acts', 44, 20, 11, ' ثم صعد وكسر خبزا وأكل وتكلم كثيرا إلى الفجر . وهكذا خرج '),
(8221, 'Acts', 44, 20, 12, ' وأتوا بالفتى حيا ، وتعزوا تعزية ليست بقليلة '),
(8222, 'Acts', 44, 20, 13, ' وأما نحن فسبقنا إلى السفينة وأقلعنا إلى أسوس ، مزمعين أن نأخذ بولس من هناك ، لأنه كان قد رتب هكذا مزمعا أن يمشي '),
(8223, 'Acts', 44, 20, 14, ' فلما وافانا إلى أسوس أخذناه وأتينا إلى ميتيليني '),
(8224, 'Acts', 44, 20, 15, ' ثم سافرنا من هناك في البحر وأقبلنا في الغد إلى مقابل خيوس . وفي اليوم الآخر وصلنا إلى ساموس ، وأقمنا في تروجيليون ، ثم في اليوم التالي جئنا إلى ميليتس '),
(8225, 'Acts', 44, 20, 16, ' لأن بولس عزم أن يتجاوز أفسس في البحر لئلا يعرض له أن يصرف وقتا في أسيا ، لأنه كان يسرع حتى إذا أمكنه يكون في أورشليم في يوم الخمسين '),
(8226, 'Acts', 44, 20, 17, ' ومن ميليتس أرسل إلى أفسس واستدعى قسوس الكنيسة '),
(8227, 'Acts', 44, 20, 18, ' فلما جاءوا إليه قال لهم : أنتم تعلمون من أول يوم دخلت أسيا ، كيف كنت معكم كل الزمان '),
(8228, 'Acts', 44, 20, 19, ' أخدم الرب بكل تواضع ودموع كثيرة ، وبتجارب أصابتني بمكايد اليهود '),
(8229, 'Acts', 44, 20, 20, ' كيف لم أؤخر شيئا من الفوائد إلا وأخبرتكم وعلمتكم به جهرا وفي كل بيت '),
(8230, 'Acts', 44, 20, 21, ' شاهدا لليهود واليونانيين بالتوبة إلى الله والإيمان الذي بربنا يسوع المسيح '),
(8231, 'Acts', 44, 20, 22, ' والآن ها أنا أذهب إلى أورشليم مقيدا بالروح ، لا أعلم ماذا يصادفني هناك '),
(8232, 'Acts', 44, 20, 23, ' غير أن الروح القدس يشهد في كل مدينة قائلا : إن وثقا وشدائد تنتظرني '),
(8233, 'Acts', 44, 20, 24, ' ولكنني لست أحتسب لشيء ، ولا نفسي ثمينة عندي ، حتى أتمم بفرح سعيي والخدمة التي أخذتها من الرب يسوع ، لأشهد ببشارة نعمة الله '),
(8234, 'Acts', 44, 20, 25, ' والآن ها أنا أعلم أنكم لا ترون وجهي أيضا ، أنتم جميعا الذين مررت بينكم كارزا بملكوت الله '),
(8235, 'Acts', 44, 20, 26, ' لذلك أشهدكم اليوم هذا أني بريء من دم الجميع '),
(8236, 'Acts', 44, 20, 27, ' لأني لم أؤخر أن أخبركم بكل مشورة الله '),
(8237, 'Acts', 44, 20, 28, ' احترزوا إذا لأنفسكم ولجميع الرعية التي أقامكم الروح القدس فيها أساقفة ، لترعوا كنيسة الله التي اقتناها بدمه '),
(8238, 'Acts', 44, 20, 29, ' لأني أعلم هذا : أنه بعد ذهابي سيدخل بينكم ذئاب خاطفة لا تشفق على الرعية '),
(8239, 'Acts', 44, 20, 30, ' ومنكم أنتم سيقوم رجال يتكلمون بأمور ملتوية ليجتذبوا التلاميذ وراءهم '),
(8240, 'Acts', 44, 20, 31, ' لذلك اسهروا ، متذكرين أني ثلاث سنين ليلا ونهارا ، لم أفتر عن أن أنذر بدموع كل واحد '),
(8241, 'Acts', 44, 20, 32, ' والآن أستودعكم يا إخوتي لله ولكلمة نعمته ، القادرة أن تبنيكم وتعطيكم ميراثا مع جميع المقدسين '),
(8242, 'Acts', 44, 20, 33, ' فضة أو ذهب أو لباس أحد لم أشته '),
(8243, 'Acts', 44, 20, 34, ' أنتم تعلمون أن حاجاتي وحاجات الذين معي خدمتها هاتان اليدان '),
(8244, 'Acts', 44, 20, 35, ' في كل شيء أريتكم أنه هكذا ينبغي أنكم تتعبون وتعضدون الضعفاء ، متذكرين كلمات الرب يسوع أنه قال : مغبوط هو العطاء أكثر من الأخذ '),
(8245, 'Acts', 44, 20, 36, ' ولما قال هذا جثا على ركبتيه مع جميعهم وصلى '),
(8246, 'Acts', 44, 20, 37, ' وكان بكاء عظيم من الجميع ، ووقعوا على عنق بولس يقبلونه '),
(8247, 'Acts', 44, 20, 38, ' متوجعين ، ولا سيما من الكلمة التي قالها : إنهم لن يروا وجهه أيضا . ثم شيعوه إلى السفينة '),
(8248, 'Acts', 44, 21, 1, ' ولما انفصلنا عنهم أقلعنا وجئنا متوجهين بالاستقامة إلى كوس ، وفي اليوم التالي إلى رودس ، ومن هناك إلى باترا '),
(8249, 'Acts', 44, 21, 2, ' فإذ وجدنا سفينة عابرة إلى فينيقية صعدنا إليها وأقلعنا ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(8250, 'Acts', 44, 21, 3, ' ثم اطلعنا على قبرس ، وتركناها يسرة وسافرنا إلى سورية ، وأقبلنا إلى صور ، لأن هناك كانت السفينة تضع وسقها '),
(8251, 'Acts', 44, 21, 4, ' وإذ وجدنا التلاميذ مكثنا هناك سبعة أيام . وكانوا يقولون لبولس بالروح أن لا يصعد إلى أورشليم '),
(8252, 'Acts', 44, 21, 5, ' ولكن لما استكملنا الأيام خرجنا ذاهبين ، وهم جميعا يشيعوننا ، مع النساء والأولاد إلى خارج المدينة . فجثونا على ركبنا على الشاطئ وصلينا '),
(8253, 'Acts', 44, 21, 6, ' ولما ودعنا بعضنا بعضا صعدنا إلى السفينة . وأما هم فرجعوا إلى خاصتهم '),
(8254, 'Acts', 44, 21, 7, ' ولما أكملنا السفر في البحر من صور ، أقبلنا إلى بتولمايس ، فسلمنا على الإخوة ومكثنا عندهم يوما واحدا '),
(8255, 'Acts', 44, 21, 8, ' ثم خرجنا في الغد نحن رفقاء بولس وجئنا إلى قيصرية ، فدخلنا بيت فيلبس المبشر ، إذ كان واحدا من السبعة وأقمنا عنده '),
(8256, 'Acts', 44, 21, 9, ' وكان لهذا أربع بنات عذارى كن يتنبأن '),
(8257, 'Acts', 44, 21, 10, ' وبينما نحن مقيمون أياما كثيرة ، انحدر من اليهودية نبي اسمه أغابوس '),
(8258, 'Acts', 44, 21, 11, ' فجاء إلينا ، وأخذ منطقة بولس ، وربط يدي نفسه ورجليه وقال : هذا يقوله الروح القدس : الرجل الذي له هذه المنطقة ، هكذا سيربطه اليهود في أورشليم ويسلمونه إلى أيدي الأمم '),
(8259, 'Acts', 44, 21, 12, ' فلما سمعنا هذا طلبنا إليه نحن والذين من المكان أن لا يصعد إلى أورشليم '),
(8260, 'Acts', 44, 21, 13, ' فأجاب بولس : ماذا تفعلون ؟ تبكون وتكسرون قلبي ، لأني مستعد ليس أن أربط فقط ، بل أن أموت أيضا في أورشليم لأجل اسم الرب يسوع '),
(8261, 'Acts', 44, 21, 14, ' ولما لم يقنع سكتنا قائلين : لتكن مشيئة الرب '),
(8262, 'Acts', 44, 21, 15, ' وبعد تلك الأيام تأهبنا وصعدنا إلى أورشليم '),
(8263, 'Acts', 44, 21, 16, ' وجاء أيضا معنا من قيصرية أناس من التلاميذ ذاهبين بنا إلى مناسون ، وهو رجل قبرسي ، تلميذ قديم ، لننزل عنده '),
(8264, 'Acts', 44, 21, 17, ' ولما وصلنا إلى أورشليم قبلنا الإخوة بفرح '),
(8265, 'Acts', 44, 21, 18, ' وفي الغد دخل بولس معنا إلى يعقوب ، وحضر جميع المشايخ '),
(8266, 'Acts', 44, 21, 19, ' فبعد ما سلم عليهم طفق يحدثهم شيئا فشيئا بكل ما فعله الله بين الأمم بواسطة خدمته '),
(8267, 'Acts', 44, 21, 20, ' فلما سمعوا كانوا يمجدون الرب . وقالوا له : أنت ترى أيها الأخ كم يوجد ربوة من اليهود الذين آمنوا ، وهم جميعا غيورون للناموس '),
(8268, 'Acts', 44, 21, 21, ' وقد أخبروا عنك أنك تعلم جميع اليهود الذين بين الأمم الارتداد عن موسى ، قائلا : أن لا يختنوا أولادهم ولا يسلكوا حسب العوائد '),
(8269, 'Acts', 44, 21, 22, ' فإذا ماذا يكون ؟ لا بد على كل حال أن يجتمع الجمهور ، لأنهم سيسمعون أنك قد جئت '),
(8270, 'Acts', 44, 21, 23, ' فافعل هذا الذي نقول لك : عندنا أربعة رجال عليهم نذر '),
(8271, 'Acts', 44, 21, 24, ' خذ هؤلاء وتطهر معهم وأنفق عليهم ليحلقوا رؤوسهم ، فيعلم الجميع أن ليس شيء مما أخبروا عنك ، بل تسلك أنت أيضا حافظا للناموس '),
(8272, 'Acts', 44, 21, 25, ' وأما من جهة الذين آمنوا من الأمم ، فأرسلنا نحن إليهم وحكمنا أن لا يحفظوا شيئا مثل ذلك ، سوى أن يحافظوا على أنفسهم مما ذبح للأصنام ، ومن الدم ، والمخنوق ، والزنا '),
(8273, 'Acts', 44, 21, 26, ' حينئذ أخذ بولس الرجال في الغد ، وتطهر معهم ودخل الهيكل ، مخبرا بكمال أيام التطهير ، إلى أن يقرب عن كل واحد منهم القربان '),
(8274, 'Acts', 44, 21, 27, ' ولما قاربت الأيام السبعة أن تتم ، رآه اليهود الذين من أسيا في الهيكل ، فأهاجوا كل الجمع وألقوا عليه الأيادي '),
(8275, 'Acts', 44, 21, 28, ' صارخين : يا أيها الرجال الإسرائيليون ، أعينوا هذا هو الرجل الذي يعلم الجميع في كل مكان ضدا للشعب والناموس وهذا الموضع ، حتى أدخل يونانيين أيضا إلى الهيكل ودنس هذا الموضع المقدس '),
(8276, 'Acts', 44, 21, 29, ' لأنهم كانوا قد رأوا معه في المدينة تروفيمس الأفسسي ، فكانوا يظنون أن بولس أدخله إلى الهيكل '),
(8277, 'Acts', 44, 21, 30, ' فهاجت المدينة كلها ، وتراكض الشعب وأمسكوا بولس وجروه خارج الهيكل . وللوقت أغلقت الأبواب '),
(8278, 'Acts', 44, 21, 31, ' وبينما هم يطلبون أن يقتلوه ، نما خبر إلى أمير الكتيبة أن أورشليم كلها قد اضطربت '),
(8279, 'Acts', 44, 21, 32, ' فللوقت أخذ عسكرا وقواد مئات وركض إليهم . فلما رأوا الأمير والعسكر كفوا عن ضرب بولس '),
(8280, 'Acts', 44, 21, 33, ' حينئذ اقترب الأمير وأمسكه ، وأمر أن يقيد بسلسلتين ، وطفق يستخبر : ترى من يكون ؟ وماذا فعل '),
(8281, 'Acts', 44, 21, 34, ' وكان البعض يصرخون بشيء والبعض بشيء آخر في الجمع . ولما لم يقدر أن يعلم اليقين لسبب الشغب ، أمر أن يذهب به إلى المعسكر '),
(8282, 'Acts', 44, 21, 35, ' ولما صار على الدرج اتفق أن العسكر حمله بسبب عنف الجمع '),
(8283, 'Acts', 44, 21, 36, ' لأن جمهور الشعب كانوا يتبعونه صارخين : خذه '),
(8284, 'Acts', 44, 21, 37, ' وإذ قارب بولس أن يدخل المعسكر قال للأمير : أيجوز لي أن أقول لك شيئا ؟ فقال : أتعرف اليونانية '),
(8285, 'Acts', 44, 21, 38, ' أفلست أنت المصري الذي صنع قبل هذه الأيام فتنة ، وأخرج إلى البرية أربعة الآلاف الرجل من القتلة '),
(8286, 'Acts', 44, 21, 39, ' فقال بولس : أنا رجل يهودي طرسوسي ، من أهل مدينة غير دنية من كيليكية . وألتمس منك أن تأذن لي أن أكلم الشعب '),
(8287, 'Acts', 44, 21, 40, ' فلما أذن له ، وقف بولس على الدرج وأشار بيده إلى الشعب ، فصار سكوت عظيم . فنادى باللغة العبرانية قائلا '),
(8288, 'Acts', 44, 22, 1, ' أيها الرجال الإخوة والآباء ، اسمعوا احتجاجي الآن لديكم '),
(8289, 'Acts', 44, 22, 2, ' فلما سمعوا أنه ينادي لهم باللغة العبرانية أعطوا سكوتا أحرى . فقال '),
(8290, 'Acts', 44, 22, 3, ' أنا رجل يهودي ولدت في طرسوس كيليكية ، ولكن ربيت في هذه المدينة مؤدبا عند رجلي غمالائيل على تحقيق الناموس الأبوي . وكنت غيورا لله كما أنتم جميعكم اليوم '),
(8291, 'Acts', 44, 22, 4, ' واضطهدت هذا الطريق حتى الموت ، مقيدا ومسلما إلى السجون رجالا ونساء '),
(8292, 'Acts', 44, 22, 5, ' كما يشهد لي أيضا رئيس الكهنة وجميع المشيخة ، الذين إذ أخذت أيضا منهم رسائل للإخوة إلى دمشق ، ذهبت لآتي بالذين هناك إلى أورشليم مقيدين لكي يعاقبوا '),
(8293, 'Acts', 44, 22, 6, ' فحدث لي وأنا ذاهب ومتقرب إلى دمشق أنه نحو نصف النهار ، بغتة أبرق حولي من السماء نور عظيم '),
(8294, 'Acts', 44, 22, 7, ' فسقطت على الأرض ، وسمعت صوتا قائلا لي : شاول شاول لماذا تضطهدني '),
(8295, 'Acts', 44, 22, 8, ' فأجبت : من أنت يا سيد ؟ فقال لي : أنا يسوع الناصري الذي أنت تضطهده '),
(8296, 'Acts', 44, 22, 9, ' والذين كانوا معي نظروا النور وارتعبوا ، ولكنهم لم يسمعوا صوت الذي كلمني '),
(8297, 'Acts', 44, 22, 10, ' فقلت : ماذا أفعل يا رب ؟ فقال لي الرب : قم واذهب إلى دمشق ، وهناك يقال لك عن جميع ما ترتب لك أن تفعل '),
(8298, 'Acts', 44, 22, 11, ' وإذ كنت لا أبصر من أجل بهاء ذلك النور ، اقتادني بيدي الذين كانوا معي ، فجئت إلى دمشق '),
(8299, 'Acts', 44, 22, 12, ' ثم إن حنانيا رجلا تقيا حسب الناموس ، ومشهودا له من جميع اليهود السكان '),
(8300, 'Acts', 44, 22, 13, ' أتى إلي ، ووقف وقال لي : أيها الأخ شاول ، أبصر ففي تلك الساعة نظرت إليه '),
(8301, 'Acts', 44, 22, 14, ' فقال : إله آبائنا انتخبك لتعلم مشيئته ، وتبصر البار ، وتسمع صوتا من فمه '),
(8302, 'Acts', 44, 22, 15, ' لأنك ستكون له شاهدا لجميع الناس بما رأيت وسمعت '),
(8303, 'Acts', 44, 22, 16, ' والآن لماذا تتوانى ؟ قم واعتمد واغسل خطاياك داعيا باسم الرب '),
(8304, 'Acts', 44, 22, 17, ' وحدث لي بعد ما رجعت إلى أورشليم وكنت أصلي في الهيكل ، أني حصلت في غيبة '),
(8305, 'Acts', 44, 22, 18, ' فرأيته قائلا لي : أسرع واخرج عاجلا من أورشليم ، لأنهم لا يقبلون شهادتك عني '),
(8306, 'Acts', 44, 22, 19, ' فقلت : يا رب ، هم يعلمون أني كنت أحبس وأضرب في كل مجمع الذين يؤمنون بك '),
(8307, 'Acts', 44, 22, 20, ' وحين سفك دم استفانوس شهيدك كنت أنا واقفا وراضيا بقتله ، وحافظا ثياب الذين قتلوه '),
(8308, 'Acts', 44, 22, 21, ' فقال لي : اذهب ، فإني سأرسلك إلى الأمم بعيدا '),
(8309, 'Acts', 44, 22, 22, ' فسمعوا له حتى هذه الكلمة ، ثم رفعوا أصواتهم قائلين : خذ مثل هذا من الأرض ، لأنه كان لا يجوز أن يعيش '),
(8310, 'Acts', 44, 22, 23, ' وإذ كانوا يصيحون ويطرحون ثيابهم ويرمون غبارا إلى الجو '),
(8311, 'Acts', 44, 22, 24, ' أمر الأمير أن يذهب به إلى المعسكر ، قائلا أن يفحص بضربات ، ليعلم لأي سبب كانوا يصرخون عليه هكذا '),
(8312, 'Acts', 44, 22, 25, ' فلما مدوه للسياط ، قال بولس لقائد المئة الواقف : أيجوز لكم أن تجلدوا إنسانا رومانيا غير مقضي عليه '),
(8313, 'Acts', 44, 22, 26, ' فإذ سمع قائد المئة ذهب إلى الأمير ، وأخبره قائلا : انظر ماذا أنت مزمع أن تفعل لأن هذا الرجل روماني '),
(8314, 'Acts', 44, 22, 27, ' فجاء الأمير وقال له : قل لي : أنت روماني ؟ فقال : نعم '),
(8315, 'Acts', 44, 22, 28, ' فأجاب الأمير : أما أنا فبمبلغ كبير اقتنيت هذه الرعوية . فقال بولس : أما أنا فقد ولدت فيها '),
(8316, 'Acts', 44, 22, 29, ' وللوقت تنحى عنه الذين كانوا مزمعين أن يفحصوه . واختشى الأمير لما علم أنه روماني ، ولأنه قد قيده . أمام رؤساء اليهود '),
(8317, 'Acts', 44, 22, 30, ' وفي الغد إذ كان يريد أن يعلم اليقين : لماذا يشتكي اليهود عليه ؟ حله من الرباط ، وأمر أن يحضر رؤساء الكهنة وكل مجمعهم . فأحدر بولس وأقامه لديهم '),
(8318, 'Acts', 44, 23, 1, ' فتفرس بولس في المجمع وقال : أيها الرجال الإخوة ، إني بكل ضمير صالح قد عشت لله إلى هذا اليوم '),
(8319, 'Acts', 44, 23, 2, ' فأمر حنانيا رئيس الكهنة ، الواقفين عنده أن يضربوه على فمه '),
(8320, 'Acts', 44, 23, 3, ' حينئذ قال له بولس : سيضربك الله أيها الحائط المبيض أفأنت جالس تحكم علي حسب الناموس ، وأنت تأمر بضربي مخالفا للناموس '),
(8321, 'Acts', 44, 23, 4, ' فقال الواقفون : أتشتم رئيس كهنة الله '),
(8322, 'Acts', 44, 23, 5, ' فقال بولس : لم أكن أعرف أيها الإخوة أنه رئيس كهنة ، لأنه مكتوب : رئيس شعبك لا تقل فيه سوءا '),
(8323, 'Acts', 44, 23, 6, ' ولما علم بولس أن قسما منهم صدوقيون والآخر فريسيون ، صرخ في المجمع : أيها الرجال الإخوة ، أنا فريسي ابن فريسي . على رجاء قيامة الأموات أنا أحاكم '),
(8324, 'Acts', 44, 23, 7, ' ولما قال هذا حدثت منازعة بين الفريسيين والصدوقيين ، وانشقت الجماعة '),
(8325, 'Acts', 44, 23, 8, ' لأن الصدوقيين يقولون إنه ليس قيامة ولا ملاك ولا روح ، وأما الفريسيون فيقرون بكل ذلك '),
(8326, 'Acts', 44, 23, 9, ' فحدث صياح عظيم ، ونهض كتبة قسم الفريسيين وطفقوا يخاصمون قائلين : لسنا نجد شيئا رديا في هذا الإنسان وإن كان روح أو ملاك قد كلمه فلا نحاربن الله '),
(8327, 'Acts', 44, 23, 10, ' ولما حدثت منازعة كثيرة اختشى الأمير أن يفسخوا بولس ، فأمر العسكر أن ينزلوا ويختطفوه من وسطهم ويأتوا به إلى المعسكر '),
(8328, 'Acts', 44, 23, 11, ' وفي الليلة التالية وقف به الرب وقال : ثق يا بولس لأنك كما شهدت بما لي في أورشليم ، هكذا ينبغي أن تشهد في رومية أيضا '),
(8329, 'Acts', 44, 23, 12, ' ولما صار النهار صنع بعض اليهود اتفاقا ، وحرموا أنفسهم قائلين : إنهم لا يأكلون ولا يشربون حتى يقتلوا بولس '),
(8330, 'Acts', 44, 23, 13, ' وكان الذين صنعوا هذا التحالف أكثر من أربعين '),
(8331, 'Acts', 44, 23, 14, ' فتقدموا إلى رؤساء الكهنة والشيوخ وقالوا : قد حرمنا أنفسنا حرما أن لا نذوق شيئا حتى نقتل بولس '),
(8332, 'Acts', 44, 23, 15, ' والآن أعلموا الأمير أنتم مع المجمع لكي ينزله إليكم غدا ، كأنكم مزمعون أن تفحصوا بأكثر تدقيق عما له . ونحن ، قبل أن يقترب ، مستعدون لقتله '),
(8333, 'Acts', 44, 23, 16, ' ولكن ابن أخت بولس سمع بالكمين ، فجاء ودخل المعسكر وأخبر بولس '),
(8334, 'Acts', 44, 23, 17, ' فاستدعى بولس واحدا من قواد المئات وقال : اذهب بهذا الشاب إلى الأمير ، لأن عنده شيئا يخبره به '),
(8335, 'Acts', 44, 23, 18, ' فأخذه وأحضره إلى الأمير وقال : استدعاني الأسير بولس ، وطلب أن أحضر هذا الشاب إليك ، وهو عنده شيء ليقوله لك '),
(8336, 'Acts', 44, 23, 19, ' فأخذ الأمير بيده وتنحى به منفردا ، واستخبره : ما هو الذي عندك لتخبرني به '),
(8337, 'Acts', 44, 23, 20, ' فقال : إن اليهود تعاهدوا أن يطلبوا منك أن تنزل بولس غدا إلى المجمع ، كأنهم مزمعون أن يستخبروا عنه بأكثر تدقيق '),
(8338, 'Acts', 44, 23, 21, ' فلا تنقد إليهم ، لأن أكثر من أربعين رجلا منهم كامنون له ، قد حرموا أنفسهم أن لا يأكلوا ولا يشربوا حتى يقتلوه . وهم الآن مستعدون منتظرون الوعد منك '),
(8339, 'Acts', 44, 23, 22, ' فأطلق الأمير الشاب موصيا إياه أن : لا تقل لأحد إنك أعلمتني بهذا '),
(8340, 'Acts', 44, 23, 23, ' ثم دعا اثنين من قواد المئات وقال : أعدا مئتي عسكري ليذهبوا إلى قيصرية ، وسبعين فارسا ومئتي رامح ، من الساعة الثالثة من الليل '),
(8341, 'Acts', 44, 23, 24, ' وأن يقدما دواب ليركبا بولس ويوصلاه سالما إلى فيلكس الوالي '),
(8342, 'Acts', 44, 23, 25, ' وكتب رسالة حاوية هذه الصورة '),
(8343, 'Acts', 44, 23, 26, ' كلوديوس ليسياس ، يهدي سلاما إلى العزيز فيلكس الوالي '),
(8344, 'Acts', 44, 23, 27, ' هذا الرجل لما أمسكه اليهود وكانوا مزمعين أن يقتلوه ، أقبلت مع العسكر وأنقذته ، إذ أخبرت أنه روماني '),
(8345, 'Acts', 44, 23, 28, ' وكنت أريد أن أعلم العلة التي لأجلها كانوا يشتكون عليه ، فأنزلته إلى مجمعهم '),
(8346, 'Acts', 44, 23, 29, ' فوجدته مشكوا عليه من جهة مسائل ناموسهم . ولكن شكوى تستحق الموت أو القيود لم تكن عليه '),
(8347, 'Acts', 44, 23, 30, ' ثم لما أعلمت بمكيدة عتيدة أن تصير على الرجل من اليهود ، أرسلته للوقت إليك ، آمرا المشتكين أيضا أن يقولوا لديك ما عليه . كن معافى '),
(8348, 'Acts', 44, 23, 31, ' فالعسكر أخذوا بولس كما أمروا ، وذهبوا به ليلا إلى أنتيباتريس '),
(8349, 'Acts', 44, 23, 32, ' وفي الغد تركوا الفرسان يذهبون معه ورجعوا إلى المعسكر '),
(8350, 'Acts', 44, 23, 33, ' وأولئك لما دخلوا قيصرية ودفعوا الرسالة إلى الوالي ، أحضروا بولس أيضا إليه '),
(8351, 'Acts', 44, 23, 34, ' فلما قرأ الوالي الرسالة ، وسأل من أية ولاية هو ، ووجد أنه من كيليكية '),
(8352, 'Acts', 44, 23, 35, ' قال : سأسمعك متى حضر المشتكون عليك أيضا . وأمر أن يحرس في قصر هيرودس '),
(8353, 'Acts', 44, 24, 1, ' وبعد خمسة أيام انحدر حنانيا رئيس الكهنة مع الشيوخ وخطيب اسمه ترتلس . فعرضوا للوالي ضد بولس '),
(8354, 'Acts', 44, 24, 2, ' فلما دعي ، ابتدأ ترتلس في الشكاية قائلا '),
(8355, 'Acts', 44, 24, 3, ' إننا حاصلون بواسطتك على سلام جزيل ، وقد صارت لهذه الأمة مصالح بتدبيرك . فنقبل ذلك أيها العزيز فيلكس بكل شكر في كل زمان وكل مكان '),
(8356, 'Acts', 44, 24, 4, ' ولكن لئلا أعوقك أكثر ، ألتمس أن تسمعنا بالاختصار بحلمك '),
(8357, 'Acts', 44, 24, 5, ' فإننا إذ وجدنا هذا الرجل مفسدا ومهيج فتنة بين جميع اليهود الذين في المسكونة ، ومقدام شيعة الناصريين '),
(8358, 'Acts', 44, 24, 6, ' وقد شرع أن ينجس الهيكل أيضا ، أمسكناه وأردنا أن نحكم عليه حسب ناموسنا '),
(8359, 'Acts', 44, 24, 7, ' فأقبل ليسياس الأمير بعنف شديد وأخذه من بين أيدينا '),
(8360, 'Acts', 44, 24, 8, ' وأمر المشتكين عليه أن يأتوا إليك . ومنه يمكنك إذا فحصت أن تعلم جميع هذه الأمور التي نشتكي بها عليه '),
(8361, 'Acts', 44, 24, 9, ' ثم وافقه اليهود أيضا قائلين : إن هذه الأمور هكذا '),
(8362, 'Acts', 44, 24, 10, ' فأجاب بولس ، إذ أومأ إليه الوالي أن يتكلم : إني إذ قد علمت أنك منذ سنين كثيرة قاض لهذه الأمة ، أحتج عما في أمري بأكثر سرور '),
(8363, 'Acts', 44, 24, 11, ' وأنت قادر أن تعرف أنه ليس لي أكثر من اثني عشر يوما منذ صعدت لأسجد في أورشليم '),
(8364, 'Acts', 44, 24, 12, ' ولم يجدوني في الهيكل أحاج أحدا أو أصنع تجمعا من الشعب ، ولا في المجامع ولا في المدينة '),
(8365, 'Acts', 44, 24, 13, ' ولا يستطيعون أن يثبتوا ما يشتكون به الآن علي '),
(8366, 'Acts', 44, 24, 14, ' ولكنني أقر لك بهذا : أنني حسب الطريق الذي يقولون له شيعة ، هكذا أعبد إله آبائي ، مؤمنا بكل ما هو مكتوب في الناموس والأنبياء '),
(8367, 'Acts', 44, 24, 15, ' ولي رجاء بالله في ما هم أيضا ينتظرونه : أنه سوف تكون قيامة للأموات ، الأبرار والأثمة '),
(8368, 'Acts', 44, 24, 16, ' لذلك أنا أيضا أدرب نفسي ليكون لي دائما ضمير بلا عثرة من نحو الله والناس '),
(8369, 'Acts', 44, 24, 17, ' وبعد سنين كثيرة جئت أصنع صدقات لأمتي وقرابين '),
(8370, 'Acts', 44, 24, 18, ' وفي ذلك وجدني متطهرا في الهيكل ، ليس مع جمع ولا مع شغب ، قوم هم يهود من أسيا '),
(8371, 'Acts', 44, 24, 19, ' كان ينبغي أن يحضروا لديك ويشتكوا ، إن كان لهم علي شيء '),
(8372, 'Acts', 44, 24, 20, ' أو ليقل هؤلاء أنفسهم ماذا وجدوا في من الذنب وأنا قائم أمام المجمع '),
(8373, 'Acts', 44, 24, 21, ' إلا من جهة هذا القول الواحد الذي صرخت به واقفا بينهم : أني من أجل قيامة الأموات أحاكم منكم اليوم '),
(8374, 'Acts', 44, 24, 22, ' فلما سمع هذا فيلكس أمهلهم ، إذ كان يعلم بأكثر تحقيق أمور هذا الطريق ، قائلا : متى انحدر ليسياس الأمير أفحص عن أموركم '),
(8375, 'Acts', 44, 24, 23, ' وأمر قائد المئة أن يحرس بولس ، وتكون له رخصة ، وأن لا يمنع أحدا من أصحابه أن يخدمه أو يأتي إليه '),
(8376, 'Acts', 44, 24, 24, ' ثم بعد أيام جاء فيلكس مع دروسلا امرأته ، وهي يهودية . فاستحضر بولس وسمع منه عن الإيمان بالمسيح '),
(8377, 'Acts', 44, 24, 25, ' وبينما كان يتكلم عن البر والتعفف والدينونة العتيدة أن تكون ، ارتعب فيلكس ، وأجاب : أما الآن فاذهب ، ومتى حصلت على وقت أستدعيك '),
(8378, 'Acts', 44, 24, 26, ' وكان أيضا يرجو أن يعطيه بولس دراهم ليطلقه ، ولذلك كان يستحضره مرارا أكثر ويتكلم معه '),
(8379, 'Acts', 44, 24, 27, ' ولكن لما كملت سنتان ، قبل فيلكس بوركيوس فستوس خليفة له . وإذ كان فيلكس يريد أن يودع اليهود منة ، ترك بولس مقيدا '),
(8380, 'Acts', 44, 25, 1, ' فلما قدم فستوس إلى الولاية صعد بعد ثلاثة أيام من قيصرية إلى أورشليم '),
(8381, 'Acts', 44, 25, 2, ' فعرض له رئيس الكهنة ووجوه اليهود ضد بولس ، والتمسوا منه '),
(8382, 'Acts', 44, 25, 3, ' طالبين عليه منة ، أن يستحضره إلى أورشليم ، وهم صانعون كمينا ليقتلوه في الطريق '),
(8383, 'Acts', 44, 25, 4, ' فأجاب فستوس أن يحرس بولس في قيصرية ، وأنه هو مزمع أن ينطلق عاجلا '),
(8384, 'Acts', 44, 25, 5, ' وقال : فلينزل معي الذين هم بينكم مقتدرون . وإن كان في هذا الرجل شيء فليشتكوا عليه '),
(8385, 'Acts', 44, 25, 6, ' وبعد ما صرف عندهم أكثر من عشرة أيام انحدر إلى قيصرية . وفي الغد جلس على كرسي الولاية وأمر أن يؤتى ببولس '),
(8386, 'Acts', 44, 25, 7, ' فلما حضر ، وقف حوله اليهود الذين كانوا قد انحدروا من أورشليم ، وقدموا على بولس دعاوي كثيرة وثقيلة لم يقدروا أن يبرهنوها '),
(8387, 'Acts', 44, 25, 8, ' إذ كان هو يحتج : أني ما أخطأت بشيء ، لا إلى ناموس اليهود ولا إلى الهيكل ولا إلى قيصر '),
(8388, 'Acts', 44, 25, 9, ' ولكن فستوس إذ كان يريد أن يودع اليهود منة ، أجاب بولس قائلا : أتشاء أن تصعد إلى أورشليم لتحاكم هناك لدي من جهة هذه الأمور '),
(8389, 'Acts', 44, 25, 10, ' فقال بولس : أنا واقف لدى كرسي ولاية قيصر حيث ينبغي أن أحاكم . أنا لم أظلم اليهود بشيء ، كما تعلم أنت أيضا جيدا '),
(8390, 'Acts', 44, 25, 11, ' لأني إن كنت آثما ، أو صنعت شيئا يستحق الموت ، فلست أستعفي من الموت . ولكن إن لم يكن شيء مما يشتكي علي به هؤلاء ، فليس أحد يستطيع أن يسلمني لهم . إلى قيصر أنا رافع دعواي '),
(8391, 'Acts', 44, 25, 12, ' حينئذ تكلم فستوس مع أرباب المشورة ، فأجاب : إلى قيصر رفعت دعواك . إلى قيصر تذهب '),
(8392, 'Acts', 44, 25, 13, ' وبعدما مضت أيام أقبل أغريباس الملك وبرنيكي إلى قيصرية ليسلما على فستوس '),
(8393, 'Acts', 44, 25, 14, ' ولما كانا يصرفان هناك أياما كثيرة ، عرض فستوس على الملك أمر بولس ، قائلا : يوجد رجل تركه فيلكس أسيرا '),
(8394, 'Acts', 44, 25, 15, ' وعرض لي عنه رؤساء الكهنة ومشايخ اليهود لما كنت في أورشليم طالبين حكما عليه '),
(8395, 'Acts', 44, 25, 16, ' فأجبتهم أن ليس للرومانيين عادة أن يسلموا أحدا للموت قبل أن يكون المشكو عليه مواجهة مع المشتكين ، فيحصل على فرصة للاحتجاج عن الشكوى '),
(8396, 'Acts', 44, 25, 17, ' فلما اجتمعوا إلى هنا جلست من دون إمهال في الغد على كرسي الولاية ، وأمرت أن يؤتى بالرجل '),
(8397, 'Acts', 44, 25, 18, ' فلما وقف المشتكون حوله ، لم يأتوا بعلة واحدة مما كنت أظن '),
(8398, 'Acts', 44, 25, 19, ' لكن كان لهم عليه مسائل من جهة ديانتهم ، وعن واحد اسمه يسوع قد مات ، وكان بولس يقول : إنه حي '),
(8399, 'Acts', 44, 25, 20, ' وإذ كنت مرتابا في المسألة عن هذا قلت : ألعله يشاء أن يذهب إلى أورشليم ، ويحاكم هناك من جهة هذه الأمور '),
(8400, 'Acts', 44, 25, 21, ' ولكن لما رفع بولس دعواه لكي يحفظ لفحص أوغسطس ، أمرت بحفظه إلى أن أرسله إلى قيصر '),
(8401, 'Acts', 44, 25, 22, ' فقال أغريباس لفستوس : كنت أريد أنا أيضا أن أسمع الرجل . فقال : غدا تسمعه '),
(8402, 'Acts', 44, 25, 23, ' ففي الغد لما جاء أغريباس وبرنيكي في احتفال عظيم ، ودخلا إلى دار الاستماع مع الأمراء ورجال المدينة المقدمين ، أمر فستوس فأتي ببولس '),
(8403, 'Acts', 44, 25, 24, ' فقال فستوس : أيها الملك أغريباس والرجال الحاضرون معنا أجمعون ، أنتم تنظرون هذا الذي توسل إلي من جهته كل جمهور اليهود في أورشليم وهنا ، صارخين أنه لا ينبغي أن يعيش بعد '),
(8404, 'Acts', 44, 25, 25, ' وأما أنا فلما وجدت أنه لم يفعل شيئا يستحق الموت ، وهو قد رفع دعواه إلى أوغسطس ، عزمت أن أرسله '),
(8405, 'Acts', 44, 25, 26, ' وليس لي شيء يقين من جهته لأكتب إلى السيد . لذلك أتيت به لديكم ، ولا سيما لديك أيها الملك أغريباس ، حتى إذا صار الفحص يكون لي شيء لأكتب '),
(8406, 'Acts', 44, 25, 27, ' لأني أرى حماقة أن أرسل أسيرا ولا أشير إلى الدعاوي التي عليه '),
(8407, 'Acts', 44, 26, 1, ' فقال أغريباس لبولس : مأذون لك أن تتكلم لأجل نفسك . حينئذ بسط بولس يده وجعل يحتج '),
(8408, 'Acts', 44, 26, 2, ' إني أحسب نفسي سعيدا أيها الملك أغريباس ، إذ أنا مزمع أن أحتج اليوم لديك عن كل ما يحاكمني به اليهود '),
(8409, 'Acts', 44, 26, 3, ' لا سيما وأنت عالم بجميع العوائد والمسائل التي بين اليهود . لذلك ألتمس منك أن تسمعني بطول الأناة '),
(8410, 'Acts', 44, 26, 4, ' فسيرتي منذ حداثتي التي من البداءة كانت بين أمتي في أورشليم يعرفها جميع اليهود '),
(8411, 'Acts', 44, 26, 5, ' عالمين بي من الأول ، إن أرادوا أن يشهدوا ، أني حسب مذهب عبادتنا الأضيق عشت فريسيا '),
(8412, 'Acts', 44, 26, 6, ' والآن أنا واقف أحاكم على رجاء الوعد الذي صار من الله لآبائنا '),
(8413, 'Acts', 44, 26, 7, ' الذي أسباطنا الاثنا عشر يرجون نواله ، عابدين بالجهد ليلا ونهارا . فمن أجل هذا الرجاء أنا أحاكم من اليهود أيها الملك أغريباس '),
(8414, 'Acts', 44, 26, 8, ' لماذا يعد عندكم أمرا لا يصدق إن أقام الله أمواتا '),
(8415, 'Acts', 44, 26, 9, ' فأنا ارتأيت في نفسي أنه ينبغي أن أصنع أمورا كثيرة مضادة لاسم يسوع الناصري '),
(8416, 'Acts', 44, 26, 10, ' وفعلت ذلك أيضا في أورشليم ، فحبست في سجون كثيرين من القديسين ، آخذا السلطان من قبل رؤساء الكهنة . ولما كانوا يقتلون ألقيت قرعة بذلك '),
(8417, 'Acts', 44, 26, 11, ' وفي كل المجامع كنت أعاقبهم مرارا كثيرة ، وأضطرهم إلى التجديف . وإذ أفرط حنقي عليهم كنت أطردهم إلى المدن التي في الخارج '),
(8418, 'Acts', 44, 26, 12, ' ولما كنت ذاهبا في ذلك إلى دمشق ، بسلطان ووصية من رؤساء الكهنة '),
(8419, 'Acts', 44, 26, 13, ' رأيت في نصف النهار في الطريق ، أيها الملك ، نورا من السماء أفضل من لمعان الشمس ، قد أبرق حولي وحول الذاهبين معي '),
(8420, 'Acts', 44, 26, 14, ' فلما سقطنا جميعنا على الأرض ، سمعت صوتا يكلمني ويقول باللغة العبرانية : شاول ، شاول لماذا تضطهدني ؟ صعب عليك أن ترفس مناخس '),
(8421, 'Acts', 44, 26, 15, ' فقلت أنا : من أنت يا سيد ؟ فقال : أنا يسوع الذي أنت تضطهده '),
(8422, 'Acts', 44, 26, 16, ' ولكن قم وقف على رجليك لأني لهذا ظهرت لك ، لأنتخبك خادما وشاهدا بما رأيت وبما سأظهر لك به '),
(8423, 'Acts', 44, 26, 17, ' منقذا إياك من الشعب ومن الأمم الذين أنا الآن أرسلك إليهم '),
(8424, 'Acts', 44, 26, 18, ' لتفتح عيونهم كي يرجعوا من ظلمات إلى نور ، ومن سلطان الشيطان إلى الله ، حتى ينالوا بالإيمان بي غفران الخطايا ونصيبا مع المقدسين '),
(8425, 'Acts', 44, 26, 19, ' من ثم أيها الملك أغريباس لم أكن معاندا للرؤيا السماوية '),
(8426, 'Acts', 44, 26, 20, ' بل أخبرت أولا الذين في دمشق ، وفي أورشليم حتى جميع كورة اليهودية ، ثم الأمم ، أن يتوبوا ويرجعوا إلى الله عاملين أعمالا تليق بالتوبة '),
(8427, 'Acts', 44, 26, 21, ' من أجل ذلك أمسكني اليهود في الهيكل وشرعوا في قتلي '),
(8428, 'Acts', 44, 26, 22, ' فإذ حصلت على معونة من الله ، بقيت إلى هذا اليوم ، شاهدا للصغير والكبير . وأنا لا أقول شيئا غير ما تكلم الأنبياء وموسى أنه عتيد أن يكون '),
(8429, 'Acts', 44, 26, 23, ' إن يؤلم المسيح ، يكن هو أول قيامة الأموات ، مزمعا أن ينادي بنور للشعب وللأمم '),
(8430, 'Acts', 44, 26, 24, ' وبينما هو يحتج بهذا ، قال فستوس بصوت عظيم : أنت تهذي يا بولس الكتب الكثيرة تحولك إلى الهذيان '),
(8431, 'Acts', 44, 26, 25, ' فقال : لست أهذي أيها العزيز فستوس ، بل أنطق بكلمات الصدق والصحو '),
(8432, 'Acts', 44, 26, 26, ' لأنه من جهة هذه الأمور ، عالم الملك الذي أكلمه جهارا ، إذ أنا لست أصدق أن يخفى عليه شيء من ذلك ، لأن هذا لم يفعل في زاوية '),
(8433, 'Acts', 44, 26, 27, ' أتؤمن أيها الملك أغريباس بالأنبياء ؟ أنا أعلم أنك تؤمن '),
(8434, 'Acts', 44, 26, 28, ' فقال أغريباس لبولس : بقليل تقنعني أن أصير مسيحيا '),
(8435, 'Acts', 44, 26, 29, ' فقال بولس : كنت أصلي إلى الله أنه بقليل وبكثير ، ليس أنت فقط ، بل أيضا جميع الذين يسمعونني اليوم ، يصيرون هكذا كما أنا ، ما خلا هذه القيود '),
(8436, 'Acts', 44, 26, 30, ' فلما قال هذا قام الملك والوالي وبرنيكي والجالسون معهم '),
(8437, 'Acts', 44, 26, 31, ' وانصرفوا وهم يكلمون بعضهم بعضا قائلين : إن هذا الإنسان ليس يفعل شيئا يستحق الموت أو القيود '),
(8438, 'Acts', 44, 26, 32, ' وقال أغريباس لفستوس : كان يمكن أن يطلق هذا الإنسان لو لم يكن قد رفع دعواه إلى قيصر '),
(8439, 'Acts', 44, 27, 1, ' فلما استقر الرأي أن نسافر في البحر إلى إيطاليا ، سلموا بولس وأسرى آخرين إلى قائد مئة من كتيبة أوغسطس اسمه يوليوس '),
(8440, 'Acts', 44, 27, 2, ' فصعدنا إلى سفينة أدراميتينية ، وأقلعنا مزمعين أن نسافر مارين بالمواضع التي في أسيا . وكان معنا أرسترخس ، رجل مكدوني من تسالونيكي '),
(8441, 'Acts', 44, 27, 3, ' وفي اليوم الآخر أقبلنا إلى صيداء ، فعامل يوليوس بولس بالرفق ، وأذن أن يذهب إلى أصدقائه ليحصل على عناية منهم '),
(8442, 'Acts', 44, 27, 4, ' ثم أقلعنا من هناك وسافرنا في البحر من تحت قبرس ، لأن الرياح كانت مضادة '),
(8443, 'Acts', 44, 27, 5, ' وبعد ما عبرنا البحر الذي بجانب كيليكية وبمفيلية ، نزلنا إلى ميرا ليكية '),
(8444, 'Acts', 44, 27, 6, ' فإذ وجد قائد المئة هناك سفينة إسكندرية مسافرة إلى إيطاليا أدخلنا فيها '),
(8445, 'Acts', 44, 27, 7, ' ولما كنا نسافر رويدا أياما كثيرة ، وبالجهد صرنا بقرب كنيدس ، ولم تمكنا الريح أكثر ، سافرنا من تحت كريت بقرب سلموني '),
(8446, 'Acts', 44, 27, 8, ' ولما تجاوزناها بالجهد جئنا إلى مكان يقال له المواني الحسنة التي بقربها مدينة لسائية '),
(8447, 'Acts', 44, 27, 9, ' ولما مضى زمان طويل ، وصار السفر في البحر خطرا ، إذ كان الصوم أيضا قد مضى ، جعل بولس ينذرهم '),
(8448, 'Acts', 44, 27, 10, ' قائلا : أيها الرجال ، أنا أرى أن هذا السفر عتيد أن يكون بضرر وخسارة كثيرة ، ليس للشحن والسفينة فقط ، بل لأنفسنا أيضا '),
(8449, 'Acts', 44, 27, 11, ' ولكن كان قائد المئة ينقاد إلى ربان السفينة وإلى صاحبها أكثر مما إلى قول بولس '),
(8450, 'Acts', 44, 27, 12, ' ولأن المينا لم يكن موقعها صالحا للمشتى ، استقر رأي أكثرهم أن يقلعوا من هناك أيضا ، عسى أن يمكنهم الإقبال إلى فينكس ليشتوا فيها . وهي مينا في كريت تنظر نحو الجنوب والشمال الغربيين '),
(8451, 'Acts', 44, 27, 13, ' فلما نسمت ريح جنوب ، ظنوا أنهم قد ملكوا مقصدهم ، فرفعوا المرساة وطفقوا يتجاوزون كريت على أكثر قرب '),
(8452, 'Acts', 44, 27, 14, ' ولكن بعد قليل هاجت عليها ريح زوبعية يقال لها أوروكليدون '),
(8453, 'Acts', 44, 27, 15, ' فلما خطفت السفينة ولم يمكنها أن تقابل الريح ، سلمنا ، فصرنا نحمل '),
(8454, 'Acts', 44, 27, 16, ' فجرينا تحت جزيرة يقال لها كلودي وبالجهد قدرنا أن نملك القارب '),
(8455, 'Acts', 44, 27, 17, ' ولما رفعوه طفقوا يستعملون معونات ، حازمين السفينة ، وإذ كانوا خائفين أن يقعوا في السيرتس ، أنزلوا القلوع ، وهكذا كانوا يحملون '),
(8456, 'Acts', 44, 27, 18, ' وإذ كنا في نوء عنيف ، جعلوا يفرغون في الغد '),
(8457, 'Acts', 44, 27, 19, ' وفي اليوم الثالث رمينا بأيدينا أثاث السفينة '),
(8458, 'Acts', 44, 27, 20, ' وإذ لم تكن الشمس ولا النجوم تظهر أياما كثيرة ، واشتد علينا نوء ليس بقليل ، انتزع أخيرا كل رجاء في نجاتنا '),
(8459, 'Acts', 44, 27, 21, ' فلما حصل صوم كثير ، حينئذ وقف بولس في وسطهم وقال : كان ينبغي أيها الرجال أن تذعنوا لي ، ولا تقلعوا من كريت ، فتسلموا من هذا الضرر والخسارة '),
(8460, 'Acts', 44, 27, 22, ' والآن أنذركم أن تسروا ، لأنه لا تكون خسارة نفس واحدة منكم ، إلا السفينة '),
(8461, 'Acts', 44, 27, 23, ' لأنه وقف بي هذه الليلة ملاك الإله الذي أنا له والذي أعبده '),
(8462, 'Acts', 44, 27, 24, ' قائلا : لا تخف يا بولس . ينبغي لك أن تقف أمام قيصر . وهوذا قد وهبك الله جميع المسافرين معك '),
(8463, 'Acts', 44, 27, 25, ' لذلك سروا أيها الرجال ، لأني أومن بالله أنه يكون هكذا كما قيل لي '),
(8464, 'Acts', 44, 27, 26, ' ولكن لا بد أن نقع على جزيرة '),
(8465, 'Acts', 44, 27, 27, ' فلما كانت الليلة الرابعة عشرة ، ونحن نحمل تائهين في بحر أدريا ، ظن النوتية ، نحو نصف الليل ، أنهم اقتربوا إلى بر '),
(8466, 'Acts', 44, 27, 28, ' فقاسوا ووجدوا عشرين قامة . ولما مضوا قليلا قاسوا أيضا فوجدوا خمس عشرة قامة '),
(8467, 'Acts', 44, 27, 29, ' وإذ كانوا يخافون أن يقعوا على مواضع صعبة ، رموا من المؤخر أربع مراس ، وكانوا يطلبون أن يصير النهار '),
(8468, 'Acts', 44, 27, 30, ' ولما كان النوتية يطلبون أن يهربوا من السفينة ، وأنزلوا القارب إلى البحر بعلة أنهم مزمعون أن يمدوا مراسي من المقدم '),
(8469, 'Acts', 44, 27, 31, ' قال بولس لقائد المئة والعسكر : إن لم يبق هؤلاء في السفينة فأنتم لا تقدرون أن تنجوا '),
(8470, 'Acts', 44, 27, 32, ' حينئذ قطع العسكر حبال القارب وتركوه يسقط '),
(8471, 'Acts', 44, 27, 33, ' وحتى قارب أن يصير النهار كان بولس يطلب إلى الجميع أن يتناولوا طعاما ، قائلا : هذا هو اليوم الرابع عشر ، وأنتم منتظرون لا تزالون صائمين ، ولم تأخذوا شيئا '),
(8472, 'Acts', 44, 27, 34, ' لذلك ألتمس منكم أن تتناولوا طعاما ، لأن هذا يكون مفيدا لنجاتكم ، لأنه لا تسقط شعرة من رأس واحد منكم '),
(8473, 'Acts', 44, 27, 35, ' ولما قال هذا أخذ خبزا وشكر الله أمام الجميع ، وكسر ، وابتدأ يأكل '),
(8474, 'Acts', 44, 27, 36, ' فصار الجميع مسرورين وأخذوا هم أيضا طعاما '),
(8475, 'Acts', 44, 27, 37, ' وكنا في السفينة جميع الأنفس مئتين وستة وسبعين '),
(8476, 'Acts', 44, 27, 38, ' ولما شبعوا من الطعام طفقوا يخففون السفينة طارحين الحنطة في البحر '),
(8477, 'Acts', 44, 27, 39, ' ولما صار النهار لم يكونوا يعرفون الأرض ، ولكنهم أبصروا خليجا له شاطئ ، فأجمعوا أن يدفعوا إليه السفينة إن أمكنهم '),
(8478, 'Acts', 44, 27, 40, ' فلما نزعوا المراسي تاركين إياها في البحر ، وحلوا ربط الدفة أيضا ، رفعوا قلعا للريح الهابة ، وأقبلوا إلى الشاطئ '),
(8479, 'Acts', 44, 27, 41, ' وإذ وقعوا على موضع بين بحرين ، شططوا السفينة ، فارتكز المقدم ولبث لا يتحرك . وأما المؤخر فكان ينحل من عنف الأمواج '),
(8480, 'Acts', 44, 27, 42, ' فكان رأي العسكر أن يقتلوا الأسرى لئلا يسبح أحد منهم فيهرب '),
(8481, 'Acts', 44, 27, 43, ' ولكن قائد المئة ، إذ كان يريد أن يخلص بولس ، منعهم من هذا الرأي ، وأمر أن القادرين على السباحة يرمون أنفسهم أولا فيخرجون إلى البر '),
(8482, 'Acts', 44, 27, 44, ' والباقين بعضهم على ألواح وبعضهم على قطع من السفينة . فهكذا حدث أن الجميع نجوا إلى البر '),
(8483, 'Acts', 44, 28, 1, ' ولما نجوا وجدوا أن الجزيرة تدعى مليطة '),
(8484, 'Acts', 44, 28, 2, ' فقدم أهلها البرابرة لنا إحسانا غير المعتاد ، لأنهم أوقدوا نارا وقبلوا جميعنا من أجل المطر الذي أصابنا ومن أجل البرد '),
(8485, 'Acts', 44, 28, 3, ' فجمع بولس كثيرا من القضبان ووضعها على النار ، فخرجت من الحرارة أفعى ونشبت في يده '),
(8486, 'Acts', 44, 28, 4, ' فلما رأى البرابرة الوحش معلقا بيده ، قال بعضهم لبعض : لا بد أن هذا الإنسان قاتل ، لم يدعه العدل يحيا ولو نجا من البحر '),
(8487, 'Acts', 44, 28, 5, ' فنفض هو الوحش إلى النار ولم يتضرر بشيء ردي '),
(8488, 'Acts', 44, 28, 6, ' وأما هم فكانوا ينتظرون أنه عتيد أن ينتفخ أو يسقط بغتة ميتا . فإذ انتظروا كثيرا ورأوا أنه لم يعرض له شيء مضر ، تغيروا وقالوا : هو إله '),
(8489, 'Acts', 44, 28, 7, ' وكان في ما حول ذلك الموضع ضياع لمقدم الجزيرة الذي اسمه بوبليوس . فهذا قبلنا وأضافنا بملاطفة ثلاثة أيام '),
(8490, 'Acts', 44, 28, 8, ' فحدث أن أبا بوبليوس كان مضطجعا معترى بحمى وسحج . فدخل إليه بولس وصلى ، ووضع يديه عليه فشفاه '),
(8491, 'Acts', 44, 28, 9, ' فلما صار هذا ، كان الباقون الذين بهم أمراض في الجزيرة يأتون ويشفون '),
(8492, 'Acts', 44, 28, 10, ' فأكرمنا هؤلاء إكرامات كثيرة . ولما أقلعنا زودونا ما يحتاج إليه '),
(8493, 'Acts', 44, 28, 11, ' وبعد ثلاثة أشهر أقلعنا في سفينة إسكندرية موسومة بعلامة الجوزاء ، كانت قد شتت في الجزيرة '),
(8494, 'Acts', 44, 28, 12, ' فنزلنا إلى سراكوسا ومكثنا ثلاثة أيام '),
(8495, 'Acts', 44, 28, 13, ' ثم من هناك درنا وأقبلنا إلى ريغيون . وبعد يوم واحد حدثت ريح جنوب ، فجئنا في اليوم الثاني إلى بوطيولي '),
(8496, 'Acts', 44, 28, 14, ' حيث وجدنا إخوة فطلبوا إلينا أن نمكث عندهم سبعة أيام . وهكذا أتينا إلى رومية '),
(8497, 'Acts', 44, 28, 15, ' ومن هناك لما سمع الإخوة بخبرنا ، خرجوا لاستقبالنا إلى فورن أبيوس والثلاثة الحوانيت . فلما رآهم بولس شكر الله وتشجع '),
(8498, 'Acts', 44, 28, 16, ' ولما أتينا إلى رومية سلم قائد المئة الأسرى إلى رئيس المعسكر ، وأما بولس فأذن له أن يقيم وحده مع العسكري الذي كان يحرسه '),
(8499, 'Acts', 44, 28, 17, ' وبعد ثلاثة أيام استدعى بولس الذين كانوا وجوه اليهود . فلما اجتمعوا قال لهم : أيها الرجال الإخوة ، مع أني لم أفعل شيئا ضد الشعب أو عوائد الآباء ، أسلمت مقيدا من أورشليم إلى أيدي الرومانيين '),
(8500, 'Acts', 44, 28, 18, ' الذين لما فحصوا كانوا يريدون أن يطلقوني ، لأنه لم تكن في علة واحدة للموت '),
(8501, 'Acts', 44, 28, 19, ' ولكن لما قاوم اليهود ، اضطررت أن أرفع دعواي إلى قيصر ، ليس كأن لي شيئا لأشتكي به على أمتي '),
(8502, 'Acts', 44, 28, 20, ' فلهذا السبب طلبتكم لأراكم وأكلمكم ، لأني من أجل رجاء إسرائيل موثق بهذه السلسلة '),
(8503, 'Acts', 44, 28, 21, ' فقالوا له : نحن لم نقبل كتابات فيك من اليهودية ، ولا أحد من الإخوة جاء فأخبرنا أو تكلم عنك بشيء ردي '),
(8504, 'Acts', 44, 28, 22, ' ولكننا نستحسن أن نسمع منك ماذا ترى ، لأنه معلوم عندنا من جهة هذا المذهب أنه يقاوم في كل مكان '),
(8505, 'Acts', 44, 28, 23, ' فعينوا له يوما ، فجاء إليه كثيرون إلى المنزل ، فطفق يشرح لهم شاهدا بملكوت الله ، ومقنعا إياهم من ناموس موسى والأنبياء بأمر يسوع ، من الصباح إلى المساء '),
(8506, 'Acts', 44, 28, 24, ' فاقتنع بعضهم بما قيل ، وبعضهم لم يؤمنوا '),
(8507, 'Acts', 44, 28, 25, ' فانصرفوا وهم غير متفقين بعضهم مع بعض ، لما قال بولس كلمة واحدة : إنه حسنا كلم الروح القدس آباءنا بإشعياء النبي '),
(8508, 'Acts', 44, 28, 26, ' قائلا : اذهب إلى هذا الشعب وقل : ستسمعون سمعا ولا تفهمون ، وستنظرون نظرا ولا تبصرون '),
(8509, 'Acts', 44, 28, 27, ' لأن قلب هذا الشعب قد غلظ ، وبآذانهم سمعوا ثقيلا ، وأعينهم أغمضوها . لئلا يبصروا بأعينهم ويسمعوا بآذانهم ويفهموا بقلوبهم ويرجعوا ، فأشفيهم '),
(8510, 'Acts', 44, 28, 28, ' فليكن معلوما عندكم أن خلاص الله قد أرسل إلى الأمم ، وهم سيسمعون '),
(8511, 'Acts', 44, 28, 29, ' ولما قال هذا مضى اليهود ولهم مباحثة كثيرة فيما بينهم '),
(8512, 'Acts', 44, 28, 30, ' وأقام بولس سنتين كاملتين في بيت استأجره لنفسه . وكان يقبل جميع الذين يدخلون إليه '),
(8513, 'Acts', 44, 28, 31, ' كارزا بملكوت الله ، ومعلما بأمر الرب يسوع المسيح بكل مجاهرة ، بلا مانع '),
(8514, 'Amos', 30, 1, 1, ' أقوال عاموس الذي كان بين الرعاة من تقوع التي رآها عن إسرائيل ، في أيام عزيا ملك يهوذا ، وفي أيام يربعام بن يوآش ملك إسرائيل ، قبل الزلزلة بسنتين '),
(8515, 'Amos', 30, 1, 2, ' فقال : إن الرب يزمجر من صهيون ، ويعطي صوته من أورشليم ، فتنوح مراعي الرعاة وييبس رأس الكرمل '),
(8516, 'Amos', 30, 1, 3, ' هكذا قال الرب : من أجل ذنوب دمشق الثلاثة والأربعة لا أرجع عنه ، لأنهم داسوا جلعاد بنوارج من حديد '),
(8517, 'Amos', 30, 1, 4, ' فأرسل نارا على بيت حزائيل فتأكل قصور بنهدد '),
(8518, 'Amos', 30, 1, 5, ' وأكسر مغلاق دمشق ، وأقطع الساكن من بقعة آون ، وماسك القضيب من بيت عدن ، ويسبى شعب أرام إلى قير ، قال الرب '),
(8519, 'Amos', 30, 1, 6, ' هكذا قال الرب : من أجل ذنوب غزة الثلاثة والأربعة لا أرجع عنه ، لأنهم سبوا سبيا كاملا لكى يسلموه إلى أدوم '),
(8520, 'Amos', 30, 1, 7, ' فأرسل نارا على سور غزة فتأكل قصورها '),
(8521, 'Amos', 30, 1, 8, ' وأقطع الساكن من أشدود ، وماسك القضيب من أشقلون ، وأرد يدي على عقرون ، فتهلك بقية الفلسطينيين ، قال السيد الرب '),
(8522, 'Amos', 30, 1, 9, ' هكذا قال الرب : من أجل ذنوب صور الثلاثة والأربعة لا أرجع عنه ، لأنهم سلموا سبيا كاملا إلى أدوم ، ولم يذكروا عهد الإخوة '),
(8523, 'Amos', 30, 1, 10, ' فأرسل نارا على سور صور فتأكل قصورها '),
(8524, 'Amos', 30, 1, 11, ' هكذا قال الرب : من أجل ذنوب أدوم الثلاثة والأربعة لا أرجع ، لأنه تبع بالسيف أخاه ، وأفسد مراحمه ، وغضبه إلى الدهر يفترس ، وسخطه يحفظه إلى الأبد '),
(8525, 'Amos', 30, 1, 12, ' فأرسل نارا على تيمان فتأكل قصور بصرة '),
(8526, 'Amos', 30, 1, 13, ' هكذا قال الرب : من أجل ذنوب بني عمون الثلاثة والأربعة لا أرجع عنه ، لأنهم شقوا حوامل جلعاد لكي يوسعوا تخومهم '),
(8527, 'Amos', 30, 1, 14, ' فأضرم نارا على سور ربة فتأكل قصورها . بجلبة في يوم القتال ، بنوء في يوم الزوبعة '),
(8528, 'Amos', 30, 1, 15, ' ويمضي ملكهم إلى السبي هو ورؤساؤه جميعا ، قال الرب '),
(8529, 'Amos', 30, 2, 1, ' هكذا قال الرب : من أجل ذنوب موآب الثلاثة والأربعة لا أرجع عنه ، لأنهم أحرقوا عظام ملك أدوم كلسا '),
(8530, 'Amos', 30, 2, 2, ' فأرسل نارا على موآب فتأكل قصور قريوت ، ويموت موآب بضجيج ، بجلبة ، بصوت البوق '),
(8531, 'Amos', 30, 2, 3, ' وأقطع القاضي من وسطها ، وأقتل جميع رؤسائها معه ، قال الرب '),
(8532, 'Amos', 30, 2, 4, ' هكذا قال الرب : من أجل ذنوب يهوذا الثلاثة والأربعة لا أرجع عنه ، لأنهم رفضوا ناموس الله ولم يحفظوا فرائضه ، وأضلتهم أكاذيبهم التي سار آباؤهم وراءها '),
(8533, 'Amos', 30, 2, 5, ' فأرسل نارا على يهوذا فتأكل قصور أورشليم '),
(8534, 'Amos', 30, 2, 6, ' هكذا قال الرب : من أجل ذنوب إسرائيل الثلاثة والأربعة لا أرجع عنه ، لأنهم باعوا البار بالفضة ، والبائس لأجل نعلين '),
(8535, 'Amos', 30, 2, 7, ' الذين يتهممون تراب الأرض على رؤوس المساكين ، ويصدون سبيل البائسين ، ويذهب رجل وأبوه إلى صبية واحدة حتى يدنسوا اسم قدسي '),
(8536, 'Amos', 30, 2, 8, ' ويتمددون على ثياب مرهونة بجانب كل مذبح ، ويشربون خمر المغرمين في بيت آلهتهم '),
(8537, 'Amos', 30, 2, 9, ' وأنا قد أبدت من أمامهم الأموري الذي قامته مثل قامة الأرز ، وهو قوي كالبلوط . أبدت ثمره من فوق ، وأصوله من تحت '),
(8538, 'Amos', 30, 2, 10, ' وأنا أصعدتكم من أرض مصر وسرت بكم في البرية أربعين سنة لترثوا أرض الأموري '),
(8539, 'Amos', 30, 2, 11, ' وأقمت من بنيكم أنبياء ، ومن فتيانكم نذيرين . أليس هكذا يا بني إسرائيل ، يقول الرب '),
(8540, 'Amos', 30, 2, 12, ' لكنكم سقيتم النذيرين خمرا ، وأوصيتم الأنبياء قائلين : لا تتنبأوا '),
(8541, 'Amos', 30, 2, 13, ' هأنذا أضغط ما تحتكم كما تضغط العجلة الملآنة حزما '),
(8542, 'Amos', 30, 2, 14, ' ويبيد المناص عن السريع ، والقوي لا يشدد قوته ، والبطل لا ينجي نفسه '),
(8543, 'Amos', 30, 2, 15, ' وماسك القوس لا يثبت ، وسريع الرجلين لا ينجو ، وراكب الخيل لا ينجي نفسه '),
(8544, 'Amos', 30, 2, 16, ' والقوي القلب بين الأبطال يهرب عريانا في ذلك اليوم ، يقول الرب '),
(8545, 'Amos', 30, 3, 1, ' اسمعوا هذا القول الذي تكلم به الرب عليكم يا بني إسرائيل ، على كل القبيلة التي أصعدتها من أرض مصر قائلا '),
(8546, 'Amos', 30, 3, 2, ' إياكم فقط عرفت من جميع قبائل الأرض ، لذلك أعاقبكم على جميع ذنوبكم '),
(8547, 'Amos', 30, 3, 3, ' هل يسير اثنان معا إن لم يتواعدا '),
(8548, 'Amos', 30, 3, 4, ' هل يزمجر الأسد في الوعر وليس له فريسة ؟ هل يعطي شبل الأسد زئيره من خدره إن لم يخطف '),
(8549, 'Amos', 30, 3, 5, ' هل يسقط عصفور في فخ الأرض وليس له شرك ؟ هل يرفع فخ عن الأرض وهو لم يمسك شيئا '),
(8550, 'Amos', 30, 3, 6, ' أم يضرب بالبوق في مدينة والشعب لا يرتعد ؟ هل تحدث بلية في مدينة والرب لم يصنعها '),
(8551, 'Amos', 30, 3, 7, ' إن السيد الرب لا يصنع أمرا إلا وهو يعلن سره لعبيده الأنبياء '),
(8552, 'Amos', 30, 3, 8, ' الأسد قد زمجر ، فمن لا يخاف ؟ السيد الرب قد تكلم ، فمن لا يتنبأ '),
(8553, 'Amos', 30, 3, 9, ' نادوا على القصور في أشدود ، وعلى القصور في أرض مصر ، وقولوا : اجتمعوا على جبال السامرة وانظروا شغبا عظيما في وسطها ومظالم في داخلها '),
(8554, 'Amos', 30, 3, 10, ' فإنهم لا يعرفون أن يصنعوا الاستقامة ، يقول الرب . أولئك الذين يخزنون الظلم والاغتصاب في قصورهم '),
(8555, 'Amos', 30, 3, 11, ' لذلك هكذا قال السيد الرب : ضيق حتى في كل ناحية من الأرض ، فينزل عنك عزك وتنهب قصورك '),
(8556, 'Amos', 30, 3, 12, ' هكذا قال الرب : كما ينزع الراعي من فم الأسد كراعين أو قطعة أذن ، هكذا ينتزع بنو إسرائيل الجالسون في السامرة في زاوية السرير وعلى دمقس الفراش '),
(8557, 'Amos', 30, 3, 13, ' اسمعوا واشهدوا على بيت يعقوب ، يقول السيد الرب إله الجنود '),
(8558, 'Amos', 30, 3, 14, ' إني يوم معاقبتي إسرائيل على ذنوبه أعاقب مذابح بيت إيل ، فتقطع قرون المذبح وتسقط إلى الأرض '),
(8559, 'Amos', 30, 3, 15, ' وأضرب بيت الشتاء مع بيت الصيف ، فتبيد بيوت العاج ، وتضمحل البيوت العظيمة ، يقول الرب '),
(8560, 'Amos', 30, 4, 1, ' اسمعي هذا القول يا بقرات باشان التي في جبل السامرة ، الظالمة المساكين ، الساحقة البائسين ، القائلة لسادتها : هات لنشرب '),
(8561, 'Amos', 30, 4, 2, ' قد أقسم السيد الرب بقدسه : هوذا أيام تأتي عليكن ، يأخذونكن بخزائم ، وذريتكن بشصوص السمك '),
(8562, 'Amos', 30, 4, 3, ' ومن الشقوق تخرجن كل واحدة على وجهها ، وتندفعن إلى الحصن ، يقول الرب '),
(8563, 'Amos', 30, 4, 4, ' هلم إلى بيت إيل ، وأذنبوا إلى الجلجال ، وأكثروا الذنوب ، وأحضروا كل صباح ذبائحكم ، وكل ثلاثة أيام عشوركم '),
(8564, 'Amos', 30, 4, 5, ' وأوقدوا من الخمير تقدمة شكر ، ونادوا بنوافل وسمعوا ، لأنكم هكذا أحببتم يا بني إسرائيل ، يقول السيد الرب '),
(8565, 'Amos', 30, 4, 6, ' وأنا أيضا أعطيتكم نظافة الأسنان في جميع مدنكم ، وعوز الخبز في جميع أماكنكم ، فلم ترجعوا إلي ، يقول الرب '),
(8566, 'Amos', 30, 4, 7, ' وأنا أيضا منعت عنكم المطر إذ بقي ثلاثة أشهر للحصاد ، وأمطرت على مدينة واحدة ، وعلى مدينة أخرى لم أمطر . أمطر على ضيعة واحدة ، والضيعة التي لم يمطر عليها جفت '),
(8567, 'Amos', 30, 4, 8, ' فجالت مدينتان أو ثلاث إلى مدينة واحدة لتشرب ماء ولم تشبع ، فلم ترجعوا إلي ، يقول الرب '),
(8568, 'Amos', 30, 4, 9, ' ضربتكم باللفح واليرقان . كثيرا ما أكل القمص جناتكم وكرومكم وتينكم وزيتونكم ، فلم ترجعوا إلي ، يقول الرب '),
(8569, 'Amos', 30, 4, 10, ' أرسلت بينكم وبأ على طريقة مصر . قتلت بالسيف فتيانكم مع سبي خيلكم ، وأصعدت نتن محالكم حتى إلى أنوفكم ، فلم ترجعوا إلي ، يقول الرب '),
(8570, 'Amos', 30, 4, 11, ' قلبت بعضكم كما قلب الله سدوم وعمورة ، فصرتم كشعلة منتشلة من الحريق ، فلم ترجعوا إلي ، يقول الرب '),
(8571, 'Amos', 30, 4, 12, ' لذلك هكذا أصنع بك يا إسرائيل . فمن أجل أني أصنع بك هذا ، فاستعد للقاء إلهك يا إسرائيل '),
(8572, 'Amos', 30, 4, 13, ' فإنه هوذا الذي صنع الجبال وخلق الريح وأخبر الإنسان ما هو فكره ، الذي يجعل الفجر ظلاما ، ويمشي على مشارف الأرض ، يهوه إله الجنود اسمه '),
(8573, 'Amos', 30, 5, 1, ' اسمعوا هذا القول الذي أنا أنادي به عليكم ، مرثاة يا بيت إسرائيل '),
(8574, 'Amos', 30, 5, 2, ' سقطت عذراء إسرائيل . لا تعود تقوم . انطرحت على أرضها ليس من يقيمها '),
(8575, 'Amos', 30, 5, 3, ' لأنه هكذا قال السيد الرب : المدينة الخارجة بألف ، يبقى لها مئة ، والخارجة بمئة يبقى لها عشرة من بيت إسرائيل '),
(8576, 'Amos', 30, 5, 4, ' لأنه هكذا قال الرب لبيت إسرائيل : اطلبوا فتحيوا '),
(8577, 'Amos', 30, 5, 5, ' ولا تطلبوا بيت إيل ، وإلى الجلجال لا تذهبوا ، وإلى بئر سبع لا تعبروا . لأن الجلجال تسبى سبيا ، وبيت إيل تصير عدما '),
(8578, 'Amos', 30, 5, 6, ' اطلبوا الرب فتحيوا لئلا يقتحم بيت يوسف كنار تحرق ، ولا يكون من يطفئها من بيت إيل '),
(8579, 'Amos', 30, 5, 7, ' يا أيها الذين يحولون الحق أفسنتينا ، ويلقون البر إلى الأرض '),
(8580, 'Amos', 30, 5, 8, ' الذي صنع الثريا والجبار ، ويحول ظل الموت صبحا ، ويظلم النهار كالليل . الذي يدعو مياه البحر ويصبها على وجه الأرض ، يهوه اسمه '),
(8581, 'Amos', 30, 5, 9, ' الذي يفلح الخرب على القوي ، فيأتي الخرب على الحصن '),
(8582, 'Amos', 30, 5, 10, ' إنهم في الباب يبغضون المنذر ، ويكرهون المتكلم بالصدق '),
(8583, 'Amos', 30, 5, 11, ' لذلك من أجل أنكم تدوسون المسكين ، وتأخذون منه هدية قمح ، بنيتم بيوتا من حجارة منحوتة ولا تسكنون فيها ، وغرستم كروما شهية ولا تشربون خمرها '),
(8584, 'Amos', 30, 5, 12, ' لأني علمت أن ذنوبكم كثيرة وخطاياكم وافرة أيها المضايقون البار ، الآخذون الرشوة ، الصادون البائسين في الباب '),
(8585, 'Amos', 30, 5, 13, ' لذلك يصمت العاقل في ذلك الزمان لأنه زمان رديء '),
(8586, 'Amos', 30, 5, 14, ' اطلبوا الخير لا الشر لكى تحيوا ، فعلى هذا يكون الرب إله الجنود معكم كما قلتم '),
(8587, 'Amos', 30, 5, 15, ' ابغضوا الشر ، وأحبوا الخير ، وثبتوا الحق في الباب ، لعل الرب إله الجنود يتراءف على بقية يوسف '),
(8588, 'Amos', 30, 5, 16, ' لذلك هكذا قال السيد الرب إله الجنود : في جميع الأسواق نحيب ، وفي جميع الأزقة يقولون : آه آه ويدعون الفلاح إلى النوح ، وجميع عارفي الرثاء للندب '),
(8589, 'Amos', 30, 5, 17, ' وفي جميع الكروم ندب ، لأني أعبر في وسطك ، قال الرب '),
(8590, 'Amos', 30, 5, 18, ' ويل للذين يشتهون يوم الرب لماذا لكم يوم الرب ؟ هو ظلام لا نور '),
(8591, 'Amos', 30, 5, 19, ' كما إذا هرب إنسان من أمام الأسد فصادفه الدب ، أو دخل البيت ووضع يده على الحائط فلدغته الحية '),
(8592, 'Amos', 30, 5, 20, ' أليس يوم الرب ظلاما لا نورا ، وقتاما ولا نور له '),
(8593, 'Amos', 30, 5, 21, ' بغضت ، كرهت أعيادكم ، ولست ألتذ باعتكافاتكم '),
(8594, 'Amos', 30, 5, 22, ' إني إذا قدمتم لي محرقاتكم وتقدماتكم لا أرتضي ، وذبائح السلامة من مسمناتكم لا ألتفت إليها '),
(8595, 'Amos', 30, 5, 23, ' أبعد عني ضجة أغانيك ، ونغمة ربابك لا أسمع '),
(8596, 'Amos', 30, 5, 24, ' وليجر الحق كالمياه ، والبر كنهر دائم '),
(8597, 'Amos', 30, 5, 25, ' هل قدمتم لي ذبائح وتقدمات في البرية أربعين سنة يا بيت إسرائيل '),
(8598, 'Amos', 30, 5, 26, ' بل حملتم خيمة ملكومكم ، وتمثال أصنامكم ، نجم إلهكم الذي صنعتم لنفوسكم '),
(8599, 'Amos', 30, 5, 27, ' فأسبيكم إلى ما وراء دمشق ، قال الرب إله الجنود اسمه '),
(8600, 'Amos', 30, 6, 1, ' ويل للمستريحين في صهيون ، والمطمئنين في جبل السامرة ، نقباء أول الأمم . يأتي إليهم بيت إسرائيل '),
(8601, 'Amos', 30, 6, 2, ' اعبروا إلى كلنة وانظروا ، واذهبوا من هناك إلى حماة العظيمة ، ثم انزلوا إلى جت الفلسطينيين . أهي أفضل من هذه الممالك ، أم تخمهم أوسع من تخمكم '),
(8602, 'Amos', 30, 6, 3, ' أنتم الذين تبعدون يوم البلية وتقربون مقعد الظلم '),
(8603, 'Amos', 30, 6, 4, ' المضطجعون على أسرة من العاج ، والمتمددون على فرشهم ، والآكلون خرافا من الغنم ، وعجولا من وسط الصيرة '),
(8604, 'Amos', 30, 6, 5, ' الهاذرون مع صوت الرباب ، المخترعون لأنفسهم آلات الغناء كداود '),
(8605, 'Amos', 30, 6, 6, ' الشاربون من كؤوس الخمر ، والذين يدهنون بأفضل الأدهان ولا يغتمون على انسحاق يوسف '),
(8606, 'Amos', 30, 6, 7, ' لذلك الآن يسبون في أول المسبيين ، ويزول صياح المتمددين '),
(8607, 'Amos', 30, 6, 8, ' قد أقسم السيد الرب بنفسه ، يقول الرب إله الجنود : إني أكره عظمة يعقوب وأبغض قصوره ، فأسلم المدينة وملأها '),
(8608, 'Amos', 30, 6, 9, ' فيكون إذا بقي عشرة رجال في بيت واحد أنهم يموتون '),
(8609, 'Amos', 30, 6, 10, ' وإذا حمل أحدا عمه ومحرقه ليخرج العظام من البيت ، وقال لمن هو في جوانب البيت : أعندك بعد ؟  . يقول : ليس بعد . فيقول : اسكت ، فإنه لا يذكر اسم الرب '),
(8610, 'Amos', 30, 6, 11, ' لأنه هوذا الرب يأمر فيضرب البيت الكبير ردما ، والبيت الصغير شقوقا '),
(8611, 'Amos', 30, 6, 12, ' هل تركض الخيل على الصخر ؟ أو يحرث عليه بالبقر ؟ حتى حولتم الحق سما ، وثمر البر أفسنتينا '),
(8612, 'Amos', 30, 6, 13, ' أنتم الفرحون بالبطل ، القائلون : أليس بقوتنا اتخذنا لأنفسنا قرونا '),
(8613, 'Amos', 30, 6, 14, ' لأني هأنذا أقيم عليكم يا بيت إسرائيل ، يقول الرب إله الجنود ، أمة فيضايقونكم من مدخل حماة إلى وادي العربة '),
(8614, 'Amos', 30, 7, 1, ' هكذا أراني السيد الرب وإذا هو يصنع جرادا في أول طلوع خلف العشب . وإذا خلف عشب بعد جزاز الملك '),
(8615, 'Amos', 30, 7, 2, ' وحدث لما فرغ من أكل عشب الأرض أني قلت : أيها السيد الرب ، اصفح كيف يقوم يعقوب ؟ فإنه صغير '),
(8616, 'Amos', 30, 7, 3, ' فندم الرب على هذا . لا يكون قال الرب '),
(8617, 'Amos', 30, 7, 4, ' هكذا أراني السيد الرب ، وإذا السيد الرب قد دعا للمحاكمة بالنار ، فأكلت الغمر العظيم وأكلت الحقل '),
(8618, 'Amos', 30, 7, 5, ' فقلت : أيها السيد الرب ، كف كيف يقوم يعقوب ؟ فإنه صغير '),
(8619, 'Amos', 30, 7, 6, ' فندم الرب على هذا . فهو أيضا لا يكون قال السيد الرب '),
(8620, 'Amos', 30, 7, 7, ' هكذا أراني وإذا الرب واقف على حائط قائم وفي يده زيج '),
(8621, 'Amos', 30, 7, 8, ' فقال لي الرب : ما أنت راء يا عاموس ؟  . فقلت : زيجا . فقال السيد : هأنذا واضع زيجا في وسط شعبي إسرائيل . لا أعود أصفح له بعد '),
(8622, 'Amos', 30, 7, 9, ' فتقفر مرتفعات إسحاق وتخرب مقادس إسرائيل ، وأقوم على بيت يربعام بالسيف '),
(8623, 'Amos', 30, 7, 10, ' فأرسل أمصيا كاهن بيت إيل إلى يربعام ملك إسرائيل قائلا : قد فتن عليك عاموس في وسط بيت إسرائيل . لا تقدر الأرض أن تطيق كل أقواله '),
(8624, 'Amos', 30, 7, 11, ' لأنه هكذا قال عاموس : يموت يربعام بالسيف ، ويسبى إسرائيل عن أرضه '),
(8625, 'Amos', 30, 7, 12, ' فقال أمصيا لعاموس : أيها الرائي ، اذهب اهرب إلى أرض يهوذا وكل هناك خبزا وهناك تنبأ '),
(8626, 'Amos', 30, 7, 13, ' وأما بيت إيل فلا تعد تتنبأ فيها بعد ، لأنها مقدس الملك وبيت الملك '),
(8627, 'Amos', 30, 7, 14, ' فأجاب عاموس وقال لأمصيا : لست أنا نبيا ولا أنا ابن نبي ، بل أنا راع وجاني جميز '),
(8628, 'Amos', 30, 7, 15, ' فأخذني الرب من وراء الضأن وقال لي الرب : اذهب تنبأ لشعبي إسرائيل '),
(8629, 'Amos', 30, 7, 16, ' فالآن اسمع قول الرب : أنت تقول : لا تتنبأ على إسرائيل ولا تتكلم على بيت إسحاق '),
(8630, 'Amos', 30, 7, 17, ' لذلك هكذا قال الرب : امرأتك تزني في المدينة ، وبنوك وبناتك يسقطون بالسيف ، وأرضك تقسم بالحبل ، وأنت تموت في أرض نجسة ، وإسرائيل يسبى سبيا عن أرضه '),
(8631, 'Amos', 30, 8, 1, ' هكذا أراني السيد الرب وإذا سلة للقطاف '),
(8632, 'Amos', 30, 8, 2, ' فقال : ماذا أنت راء يا عاموس ؟  . فقلت : سلة للقطاف . فقال لي الرب : قد أتت النهاية على شعبي إسرائيل . لا أعود أصفح له بعد '),
(8633, 'Amos', 30, 8, 3, ' فتصير أغاني القصر ولاول في ذلك اليوم ، يقول السيد الرب ، الجثث كثيرة يطرحونها في كل موضع بالسكوت '),
(8634, 'Amos', 30, 8, 4, ' اسمعوا هذا أيها المتهممون المساكين لكي تبيدوا بائسي الأرض '),
(8635, 'Amos', 30, 8, 5, ' قائلين : متى يمضي رأس الشهر لنبيع قمحا ، والسبت لنعرض حنطة ؟ لنصغر الإيفة ، ونكبر الشاقل ، ونعوج موازين الغش '),
(8636, 'Amos', 30, 8, 6, ' لنشتري الضعفاء بفضة ، والبائس بنعلين ، ونبيع نفاية القمح '),
(8637, 'Amos', 30, 8, 7, ' قد أقسم الرب بفخر يعقوب : إني لن أنسى إلى الأبد جميع أعمالهم '),
(8638, 'Amos', 30, 8, 8, ' أليس من أجل هذا ترتعد الأرض ، وينوح كل ساكن فيها ، وتطمو كلها كنهر ، وتفيض وتنضب كنيل مصر '),
(8639, 'Amos', 30, 8, 9, ' ويكون في ذلك اليوم ، يقول السيد الرب ، أني أغيب الشمس في الظهر ، وأقتم الأرض في يوم نور '),
(8640, 'Amos', 30, 8, 10, ' وأحول أعيادكم نوحا ، وجميع أغانيكم مراثي ، وأصعد على كل الأحقاء مسحا ، وعلى كل رأس قرعة ، وأجعلها كمناحة الوحيد وآخرها يوما مرا '),
(8641, 'Amos', 30, 8, 11, ' هوذا أيام تأتي ، يقول السيد الرب ، أرسل جوعا في الأرض ، لا جوعا للخبز ، ولا عطشا للماء ، بل لاستماع كلمات الرب '),
(8642, 'Amos', 30, 8, 12, ' فيجولون من بحر إلى بحر ، ومن الشمال إلى المشرق ، يتطوحون ليطلبوا كلمة الرب فلا يجدونها '),
(8643, 'Amos', 30, 8, 13, ' في ذلك اليوم تذبل بالعطش العذارى الجميلات والفتيان '),
(8644, 'Amos', 30, 8, 14, ' الذين يحلفون بذنب السامرة ، ويقولون : حي إلهك يا دان ، وحية طريقة بئر سبع . فيسقطون ولا يقومون بعد '),
(8645, 'Amos', 30, 9, 1, ' رأيت السيد قائما على المذبح ، فقال : اضرب تاج العمود حتى ترجف الأعتاب ، وكسرها على رؤوس جميعهم ، فأقتل آخرهم بالسيف . لا يهرب منهم هارب ولا يفلت منهم ناج '),
(8646, 'Amos', 30, 9, 2, ' إن نقبوا إلى الهاوية فمن هناك تأخذهم يدي ، وإن صعدوا إلى السماء فمن هناك أنزلهم '),
(8647, 'Amos', 30, 9, 3, ' وإن اختبأوا في رأس الكرمل فمن هناك أفتش وآخذهم ، وإن اختفوا من أمام عيني في قعر البحر فمن هناك آمر الحية فتلدغهم '),
(8648, 'Amos', 30, 9, 4, ' وإن مضوا في السبي أمام أعدائهم فمن هناك آمر السيف فيقتلهم ، وأجعل عيني عليهم للشر لا للخير '),
(8649, 'Amos', 30, 9, 5, ' والسيد رب الجنود الذي يمس الأرض فتذوب ، وينوح الساكنون فيها ، وتطمو كلها كنهر وتنضب كنيل مصر '),
(8650, 'Amos', 30, 9, 6, ' الذي بنى في السماء علاليه وأسس على الأرض قبته ، الذي يدعو مياه البحر ويصبها على وجه الأرض ، يهوه اسمه '),
(8651, 'Amos', 30, 9, 7, ' ألستم لي كبني الكوشيين يا بني إسرائيل ، يقول الرب ؟ ألم أصعد إسرائيل من أرض مصر ، والفلسطينيين من كفتور ، والأراميين من قير '),
(8652, 'Amos', 30, 9, 8, ' هوذا عينا السيد الرب على المملكة الخاطئة ، وأبيدها عن وجه الأرض . غير أني لا أبيد بيت يعقوب تماما ، يقول الرب '),
(8653, 'Amos', 30, 9, 9, ' لأنه هأنذا آمر فأغربل بيت إسرائيل بين جميع الأمم كما يغربل في الغربال ، وحبة لا تقع إلى الأرض '),
(8654, 'Amos', 30, 9, 10, ' بالسيف يموت كل خاطئي شعبي القائلين : لا يقترب الشر ، ولا يأتي بيننا '),
(8655, 'Amos', 30, 9, 11, ' في ذلك اليوم أقيم مظلة داود الساقطة ، وأحصن شقوقها ، وأقيم ردمها ، وأبنيها كأيام الدهر '),
(8656, 'Amos', 30, 9, 12, ' لكي يرثوا بقية أدوم وجميع الأمم الذين دعي اسمي عليهم ، يقول الرب ، الصانع هذا '),
(8657, 'Amos', 30, 9, 13, ' ها أيام تأتي ، يقول الرب ، يدرك الحارث الحاصد ، ودائس العنب باذر الزرع ، وتقطر الجبال عصيرا ، وتسيل جميع التلال '),
(8658, 'Amos', 30, 9, 14, ' وأرد سبي شعبي إسرائيل فيبنون مدنا خربة ويسكنون ، ويغرسون كروما ويشربون خمرها ، ويصنعون جنات ويأكلون أثمارها '),
(8659, 'Amos', 30, 9, 15, ' وأغرسهم في أرضهم ، ولن يقلعوا بعد من أرضهم التي أعطيتهم ، قال الرب إلهك '),
(8660, 'Baruch', 71, 1, 1, 'هذا كلام الكتاب الذي كتبه باروك بن نيريا بن معسيا بن صدقيا بن حسديا ابن حلقيا في بابل'),
(8661, 'Baruch', 71, 1, 2, 'في السنة الخامسة في السابع من الشهر حين اخذ الكلدانيون اورشليم واحرقوها بالنار'),
(8662, 'Baruch', 71, 1, 3, 'و تلا باروك كلام هذا الكتاب على مسمعي يكنيا بن يوياقيم ملك يهوذا وعلى مسامع جميع الشعب الذين جاءوا لاستماع الكتاب'),
(8663, 'Baruch', 71, 1, 4, 'و على مسامع المقتدرين وبني الملوك ومسامع الشيوخ ومسامع جميع الشعب من الصغار الى الكبار جميع الساكنين في بابل على نهر سود'),
(8664, 'Baruch', 71, 1, 5, 'فبكوا وصاموا وصلوا امام الرب'),
(8665, 'Baruch', 71, 1, 6, 'و جمعوا من الفضة قدر ما استطاعت يد كل واحد'),
(8666, 'Baruch', 71, 1, 7, 'و بعثوا الى اورشليم الى يوياقيم بن حلقيا بن شلوم الكاهن والى الكهنة والى جميع الشعب الذين معه في اورشليم'),
(8667, 'Baruch', 71, 1, 8, 'عندما اخذ انية بيت الرب المسلوبة من الهيكل ليردها الى ارض يهوذا في العاشر من سيوان وهي انية الفضة التي صنعها صدقيا ابن يوشيا ملك يهوذا'),
(8668, 'Baruch', 71, 1, 9, 'بعدما اجلى نبوكد نصر ملك بابل يكنيا والرؤساء والمحصنين والمقتدرين وشعب الارض من اورشليم وذهب بهم الى بابل'),
(8669, 'Baruch', 71, 1, 10, 'و قالوا انا قد ارسلنا اليكم فضة فابتاعوا بالفضة محرقات وذبائح للخطية ولبانا واصنعوا تقادم وقدموها علىمذبح الرب الهنا'),
(8670, 'Baruch', 71, 1, 11, 'و صلوا من اجل حياة نبوكد نصر ملك بابل وحياة بلشصر ابنه لكي تكون ايامهما كايام السماء على الارض'),
(8671, 'Baruch', 71, 1, 12, 'فيؤتينا الرب قوة وينير عيوننا ونحيا تحت ظل نبوكد نصر ملك بابل وظل بلشصر ابنه ونتعبد لهما اياما كثيرة ونحننائلون لديهما حظوة');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(8672, 'Baruch', 71, 1, 13, 'و صلوا من اجلنا الى الرب الهنا فانا قد خطئنا الى الرب الهنا ولم يرتد سخط الرب وغضبه عنا الى هذا اليوم'),
(8673, 'Baruch', 71, 1, 14, 'و اتلوا هذا الكتاب الذي ارسلناه اليكم لينادى به في بيت الرب في يوم العيد وفي ايام المحفل'),
(8674, 'Baruch', 71, 1, 15, 'و قولوا للرب الهنا العدل ولنا خزي الوجوه كما في هذا اليوم لرجال يهوذا وسكان اورشليم'),
(8675, 'Baruch', 71, 1, 16, 'و لملوكنا ورؤسائنا وكهنتنا وانبيائنا وابائنا'),
(8676, 'Baruch', 71, 1, 17, 'لانا خطئنا امام الرب وعصيناه'),
(8677, 'Baruch', 71, 1, 18, 'و لم نسمع لصوت الرب الهنا لنسلك في اوامر الرب التي جعلها امام وجوهنا'),
(8678, 'Baruch', 71, 1, 19, 'من يوم اخرج الرب اباءنا من ارض مصر الى هذا اليوم ما زلنا نعاصي الرب الهنا ونعرض عن استماع صوته'),
(8679, 'Baruch', 71, 1, 20, 'فلحق بنا الشر واللعنة اللذان امر الرب موسى عبده ان يوعد بهما يوم اخرج اباءنا من ارض مصر ليعطينا ارضا تدر لبنا وعسلا كما في هذا اليوم'),
(8680, 'Baruch', 71, 1, 21, 'فلم نسمع لصوت الرب الهنا ولا لجميع كلام الانبياء الذين ارسلهم الينا'),
(8681, 'Baruch', 71, 1, 22, 'و مضينا كل واحد على اصرار قلبه الشرير عابدين الهة اخر صانعين الشر امام عيني الرب الهنا'),
(8682, 'Baruch', 71, 2, 1, 'فاقام الرب كلامه الذي تكلم به علينا وعلى قضاتنا الذين يقضون في اسرائيل وعلى ملوكنا ورؤسائنا وعلى رجال اسرائيل ويهوذا'),
(8683, 'Baruch', 71, 2, 2, 'جالبا علينا شرا عظيما بحيث لم يحدث تحت السماء باسرها مثل ما احدثه في اورشليم على حسب ما كتب في شريعة موسى'),
(8684, 'Baruch', 71, 2, 3, 'حتى اكل بعضنا لحم ابنه والاخر لحم بنته'),
(8685, 'Baruch', 71, 2, 4, 'و اخضعهم تحت ايدي جميع الممالك التي حولنا وجعلهم عارا ودهشا في جميع الشعوب الذين شتتهم الرب بينهم'),
(8686, 'Baruch', 71, 2, 5, 'فاذا هم في الانحطاط بدل الرفعة لانا خطئنا الى الرب الهنا غير سامعين لصوته'),
(8687, 'Baruch', 71, 2, 6, 'للرب الهنا العدل ولنا ولابائنا خزي الوجوه كما في هذا اليوم'),
(8688, 'Baruch', 71, 2, 7, 'لان الرب تكلم علينا بجميع هذا الشر الذي حل بنا'),
(8689, 'Baruch', 71, 2, 8, 'و نحن لم نستعطف وجه الرب تائبين كل واحد عن افكار قلبه الشرير'),
(8690, 'Baruch', 71, 2, 9, 'فسهر الرب على الشر وجلبه الرب علينا لان الرب عادل في جميع اعماله التي اوصانا بها'),
(8691, 'Baruch', 71, 2, 10, 'فلم نسمع لصوته لنسلك في اوامر الرب التي جعلها امام وجوهنا'),
(8692, 'Baruch', 71, 2, 11, 'فالان ايها الرب اله اسرائيل الذي اخرج شعبه من ارض مصر بيد قديرة وبايات ومعجزات وقوة عظيمة وذراع مبسوطة واقامله اسما كما في هذا اليوم'),
(8693, 'Baruch', 71, 2, 12, 'انا خطئنا ونافقنا واثمنا ايها الرب الهنا في جميع رسومك'),
(8694, 'Baruch', 71, 2, 13, 'لينصرف غضبك عنا فقد بقينا نفرا قليلا في الامم الذين شتتنا بينهم'),
(8695, 'Baruch', 71, 2, 14, 'اسمع يا رب صلاتنا وتضرعنا وانقذنا لاجلك وانلنا حظوة امام وجوه الذين اجلونا'),
(8696, 'Baruch', 71, 2, 15, 'لكي تعرف الارض باسرها انك انت الرب الهنا وانه باسمك دعي اسرائيل وعشائره'),
(8697, 'Baruch', 71, 2, 16, 'ايها الرب التفت من بيت قدسك وانظر الينا وامل ايها الرب اذنك واستجب'),
(8698, 'Baruch', 71, 2, 17, 'افتح عينيك وانظر فانه ليس الاموات في الجحيم الذين اخذت ارواحهم عن احشائهم يعترفون للرب بالمجد والعدل'),
(8699, 'Baruch', 71, 2, 18, 'لكن الروح الكئيب من الشدة والذي يمشي منحنيا ضعيفا والعيون الكليلة والنفس الجائعة هم يعترفون لك بالمجد والعدل يا رب'),
(8700, 'Baruch', 71, 2, 19, 'فانا لا لاجل بر ابائنا وملوكنا نلقي تضرعنا امامك ايها الرب الهنا'),
(8701, 'Baruch', 71, 2, 20, 'بل لانك ارسلت سخطك وغضبك علينا كما تكلمت على السنة عبيدك الانبياء'),
(8702, 'Baruch', 71, 2, 21, 'هكذا قال الرب احنوا مناكبكم وتعبدوا لملك بابل فتسكنوا في الارض التي اعطيتها لابائكم'),
(8703, 'Baruch', 71, 2, 22, 'و ان لم تسمعوا لصوت الرب بان تتعبدوا لملك بابل'),
(8704, 'Baruch', 71, 2, 23, 'فاني ابطل من مدن يهوذا ومن شوارع اورشليم صوت الطرب وصوت الفرح صوت العروس وصوت العروسة وتكون كل الارض مستوحشة لا ساكن فيها'),
(8705, 'Baruch', 71, 2, 24, 'فلم نسمع لصوتك بان نتعبد لملك بابل فاقمت كلامك الذي تكلمت به على السنة عبيدك الانبياء ان تخرج عظام ملوكنا وعظام ابائنا من مواضعها'),
(8706, 'Baruch', 71, 2, 25, 'و ها انها مطروحة لحر النهار وقرس الليل وقد ماتوا في اوجاع اليمة بالجوع والسيف والطرد'),
(8707, 'Baruch', 71, 2, 26, 'و جعلت البيت الذي دعي باسمك كما في هذا اليوم لاجل شر ال اسرائيل وال يهوذا'),
(8708, 'Baruch', 71, 2, 27, 'و قد عاملتنا ايها الرب الهنا بكل رافتك وكل رحمتك العظيمة'),
(8709, 'Baruch', 71, 2, 28, 'كما تكلمت على لسان عبدك موسى يوم امرته ان يكتب شريعتك امام بني اسرائيل قائلا'),
(8710, 'Baruch', 71, 2, 29, 'ان لم تسمعوا لصوتي فان هذا الجمع العظيم الكثير ليصيرن نفرا قليلا في الامم الذين اشتتهم بينهم'),
(8711, 'Baruch', 71, 2, 30, 'فاني عالم بانهم لا يسمعون لي لانهم شعب قساة الرقاب لكنهم سيرجعون الى قلوبهم في ارض جلائهم'),
(8712, 'Baruch', 71, 2, 31, 'و يعلمون اني انا الرب الههم واعطيهم قلوبا واذانا سامعة'),
(8713, 'Baruch', 71, 2, 32, 'فيسبحونني في ارض جلائهم ويذكرون اسمي'),
(8714, 'Baruch', 71, 2, 33, 'و يتوبون عن صلابة رقابهم وعن شر اعمالهم لانهم يتذكرون طريق ابائهم الذين خطئوا امام الرب'),
(8715, 'Baruch', 71, 2, 34, 'و اعيدهم الى الارض التي حلفت عليها لابائهم ابراهيم واسحق ويعقوب فيتسلطون عليها واكثرهم فلا يقلون'),
(8716, 'Baruch', 71, 2, 35, 'و اقيم لهم عهدا ابديا فاكون لهم الها ويكونون لي شعبا ولا اعود ازعزع شعبي اسرائيل من الارض التي اعطيتها لهم'),
(8717, 'Baruch', 71, 3, 1, 'ايها الرب القدير اله اسرائيل قد صرخت اليك النفس في المضايق والروح في الكروب'),
(8718, 'Baruch', 71, 3, 2, 'فاسمع يا رب وارحم فانك اله رحيم ارحم فانا قد خطئنا اليك'),
(8719, 'Baruch', 71, 3, 3, 'فانك انت تدوم الى الابد اما نحن فنهلك الى الابد'),
(8720, 'Baruch', 71, 3, 4, 'ايها الرب القدير اله اسرائيل اسمع صلاة قوم اسرائيل وبني الذين خطئوا اليك الذين لم يسمعوا لصوت الههم وقد لحق الشر بنا'),
(8721, 'Baruch', 71, 3, 5, 'لا تذكر اثام ابائنا بل اذكر يدك واسمك في هذا الزمان'),
(8722, 'Baruch', 71, 3, 6, 'فانك انت الرب الهنا واياك نسبح يا رب'),
(8723, 'Baruch', 71, 3, 7, 'لانك لذلك جعلت مخافتك في قلوبنا ولندعو باسمك انا نسبحك في جلائنا لانا قد نبذنا عن قلوبنا كل اثم ابائنا الذين خطئوا امامك'),
(8724, 'Baruch', 71, 3, 8, 'و ها انا اليوم في الجلاء حيث شتتنا للتعيير واللعنة والعقاب لاجل جميع اثام ابائنا الذين ارتدوا عن الرب الهنا'),
(8725, 'Baruch', 71, 3, 9, 'اسمع يا اسرائيل وصايا الحياة اصغوا وتعلموا الفطنة'),
(8726, 'Baruch', 71, 3, 10, 'لماذا يا اسرائيل لماذا انت في ارض الاعداء'),
(8727, 'Baruch', 71, 3, 11, 'قد ذبلت في ارض الغربة وتنجست بالاموات وحسبت مع الذين هم في الجحيم'),
(8728, 'Baruch', 71, 3, 12, 'انك قد تركت ينبوع الحكمة'),
(8729, 'Baruch', 71, 3, 13, 'و لو انك سلكت في طريق الله لسكنت في السلام مدى الدهر'),
(8730, 'Baruch', 71, 3, 14, 'تعلم اين الفطنة واين القوة واين التعقل لكي تعلم ايضا اين طول الايام والحياة واين نور العيون والسلام'),
(8731, 'Baruch', 71, 3, 15, 'من وجد موضعها ومن بلغ الى كنوزها'),
(8732, 'Baruch', 71, 3, 16, 'اين رؤساء الامم والذين يتسلطون على وحوش الارض'),
(8733, 'Baruch', 71, 3, 17, 'و الذين يلاعبون طيور السماء'),
(8734, 'Baruch', 71, 3, 18, 'و يكنزون الفضة والذهب مما يتوكل عليه البشر ولا حد لكسبهم ويصوغون الفضة ويهتمون ولا استقصاء لمساعيهم'),
(8735, 'Baruch', 71, 3, 19, 'انهم قد اضمحلوا والى الجحيم هبطوا واخرون قاموا من مكانهم'),
(8736, 'Baruch', 71, 3, 20, 'احداث راوا النور وسكنوا الارض لكنهم لم يعرفوا طريق التادب'),
(8737, 'Baruch', 71, 3, 21, 'و لم يفهموا سبله وبنوهم لم يدركوه وابتعدوا عن طريقه'),
(8738, 'Baruch', 71, 3, 22, 'لم يسمع به في كنعان ولا تراءى في تيمان'),
(8739, 'Baruch', 71, 3, 23, 'و بنو هاجر ايضا المبتغون للتعقل على الارض وتجار مران وتيمان وقائلو الامثال ومبتغو التعقل لم يعرفوا طريق الحكمة ولم يتذكروا سبلها'),
(8740, 'Baruch', 71, 3, 24, 'يا اسرائيل ما اعظم بيت الله وما اوسع موضع ملكه'),
(8741, 'Baruch', 71, 3, 25, 'عظيم هو بغير حد وعال بغير قياس'),
(8742, 'Baruch', 71, 3, 26, 'هناك ولد الجبابرة المذكورون الذين كانوا في البدء الطوال القامات الحاذقون بالقتال'),
(8743, 'Baruch', 71, 3, 27, 'اولئك لم يخترهم الرب ولم يجعل لهم طريق التادب'),
(8744, 'Baruch', 71, 3, 28, 'فهلكوا لعدم الفطنة هلكوا لغباوتهم'),
(8745, 'Baruch', 71, 3, 29, 'من صعد الى السماء فتناولها ونزل بها من الغيوم'),
(8746, 'Baruch', 71, 3, 30, 'من اجتاز الى عبر البحر ووجدها واثرها على الذهب الابريز'),
(8747, 'Baruch', 71, 3, 31, 'ليس احد يعرف طريقها ويطلع على سبيلها'),
(8748, 'Baruch', 71, 3, 32, 'لكن العالم بكل شيء هو يعلمها وبعقله وجدها الذي ثبت الارض الى الابد وملاها حيوانا ذا اربع'),
(8749, 'Baruch', 71, 3, 33, 'الذي يرسل النور فينطلق يدعوه فيطيعه برعدة'),
(8750, 'Baruch', 71, 3, 34, 'ان النجوم اشرقت في محارسها وتهللت'),
(8751, 'Baruch', 71, 3, 35, 'دعاها فقالت نحن لديك واشرقت متهللة للذي صنعها'),
(8752, 'Baruch', 71, 3, 36, 'هذا هو الهنا ولا يعتبر حذاءه اخر'),
(8753, 'Baruch', 71, 3, 37, 'هو وجد طريق التادب بكماله وجعله ليعقوب عبده ولاسرائيل حبيبه'),
(8754, 'Baruch', 71, 3, 38, 'و بعد ذلك تراءى على الارض وتردد بين البشر'),
(8755, 'Baruch', 71, 4, 1, 'هذا كتاب اوامر الله والشريعة التي الى الابد كل من تمسك بها فله الحياة والذين يهملونها يموتون'),
(8756, 'Baruch', 71, 4, 2, 'تب يا يعقوب واتخذها وسر في الضياء تجاه نورها'),
(8757, 'Baruch', 71, 4, 3, 'لا تعط مجدك لاخر ومزيتك لامة غريبة'),
(8758, 'Baruch', 71, 4, 4, 'طوبى لنا يا اسرائيل لان ما يرضي عند الله معروف لدينا'),
(8759, 'Baruch', 71, 4, 5, 'ثقوا يا شعبي يا تذكار اسرائيل'),
(8760, 'Baruch', 71, 4, 6, 'فانكم لم تباعوا للامم لهلاككم ولكن بما انكم اسخطتم الله قد اسلمتم الى اعدائكم'),
(8761, 'Baruch', 71, 4, 7, 'لانكم اغضبتم صانعكم اذ ذبحتم للشياطين لا لله'),
(8762, 'Baruch', 71, 4, 8, 'و نسيتم رازقكم الاله الازلي وحزنتم مربيتكم اورشليم'),
(8763, 'Baruch', 71, 4, 9, 'انها رات الغضب الذي حل بكم من قبل الله فقالت اسمعن يا جارات صهيون ان الله قد جلب علي نوحا عظيما'),
(8764, 'Baruch', 71, 4, 10, 'فاني رايت سبي بني وبناتي الذي جلبه عليهم الازلي'),
(8765, 'Baruch', 71, 4, 11, 'اني ربيتهم بفرح ثم ودعتهم ببكاء ونوح'),
(8766, 'Baruch', 71, 4, 12, 'لا يشمتن احد بي انا الارملة التي ثكلت كثيرين فاني قد اوحشت لاجل خطايا بني لانهم زاغوا عن شريعة الله'),
(8767, 'Baruch', 71, 4, 13, 'و لم يعرفوا رسومه ولم يسلكوا في طرق وصايا الله ولم يسيروا في سبل التادب ببره'),
(8768, 'Baruch', 71, 4, 14, 'هلم يا جارات صهيون فاذكرن سبي بني وبناتي الذي جلبه عليهم الازلي'),
(8769, 'Baruch', 71, 4, 15, 'فانه جلب عليهم امة من بعيد امة وقحة اعجمية اللسان'),
(8770, 'Baruch', 71, 4, 16, 'لم تهب شيخا ولم تشفق على طفل فذهبوا باحباء الارملة واثكلوا المتوحدة بناتها'),
(8771, 'Baruch', 71, 4, 17, 'باي شيء استطيع ان اغيثكم'),
(8772, 'Baruch', 71, 4, 18, 'الذي جلب عليكم الشر هو ينقذكم من ايدي اعدائكم'),
(8773, 'Baruch', 71, 4, 19, 'سيروا يا بني سيروا اني بقيت مستوحشة'),
(8774, 'Baruch', 71, 4, 20, 'قد خلعت حلة السلام ولبست مسح التضرع اصرخ الى الازلي مدى ايامي'),
(8775, 'Baruch', 71, 4, 21, 'ثقوا يا بني واستغيثوا بالله فينقذكم من ايدي الاعداء المتسلطين عليكم'),
(8776, 'Baruch', 71, 4, 22, 'فاني قد رجوت بالازلي خلاصكم وحلت بي مسرة من لدن القدوس بالرحمة التي تؤتونها عما قليل من عند الازلي مخلصكم'),
(8777, 'Baruch', 71, 4, 23, 'قد ودعتكم ببكاء ونوح ولكن الله سيردكم لي بفرح ومسرة الى الابد'),
(8778, 'Baruch', 71, 4, 24, 'فكما ترى الان جارات صهيون سبيكم هكذا عما قليل سيرين خلاصكم من عند الله تؤتونه بمجد عظيم وببهاء الازلي'),
(8779, 'Baruch', 71, 4, 25, 'يا بني احتملوا بالصبر الغضب الذي حل بكم من الله قد اضطهدك العدو لكنك سترى هلاكه عن قليل وتطا رقابهم'),
(8780, 'Baruch', 71, 4, 26, 'ان مترفي سلكوا طرقا وعرة وسيقوا كغنم نهبتها الاعداء'),
(8781, 'Baruch', 71, 4, 27, 'ثقوا يا بني واستغيثوا بالله فان الذي جلب عليكم هذه سيتذكركم'),
(8782, 'Baruch', 71, 4, 28, 'و كما كنتم تهوون ان تشردوا عن الله فبقدر ذلك عشر مرات تلتمسونه تائبين'),
(8783, 'Baruch', 71, 4, 29, 'و الذي جلب عليكم الشر يجلب لكم المسرة الابدية مع خلاصكم'),
(8784, 'Baruch', 71, 4, 30, 'ثقي يا اورشليم فان الذي سماك باسمه يعزيك'),
(8785, 'Baruch', 71, 4, 31, 'ويل للذين جاروا عليك وشمتوا بسقوطك'),
(8786, 'Baruch', 71, 4, 32, 'ويل للمدن التي استعبدت بنيك ويل للتي اخذت اولادك'),
(8787, 'Baruch', 71, 4, 33, 'فانها كما شمتت بسقوطك وفرحت بخرابك كذلك ستكتئب عند دمارها'),
(8788, 'Baruch', 71, 4, 34, 'و ابطل مفاخرتها بكثرة سكانها واحول مرحها الى نوح'),
(8789, 'Baruch', 71, 4, 35, 'لان نار تنزل عليها من عند الازلي الى ايام كثيرة وتسكنها الشياطين طول الزمان'),
(8790, 'Baruch', 71, 4, 36, 'تطلعي يا اورشليم من حولك نحو المشرق وانظري المسرة الوافدة عليك من عند الله'),
(8791, 'Baruch', 71, 4, 37, 'ها ان بنيك الذين ودعتهم قادمون يقدمون مجتمعين من المشرق الى المغرب بكلمة القدوس مبتهجين بمجد الله'),
(8792, 'Baruch', 71, 5, 1, 'اخلعي يا اورشليم حلة النوح والمذلة والبسي بهاء المجد من عند الله الى الابد'),
(8793, 'Baruch', 71, 5, 2, 'تسربلي ثوب البر الذي من الله واجعلي على راسك تاج مجد الازلي'),
(8794, 'Baruch', 71, 5, 3, 'فان الله يظهر سناك لكل ما تحت السماء'),
(8795, 'Baruch', 71, 5, 4, 'و يكون اسمك من قبل الله الى الابد سلام البر ومجد عبادة الله'),
(8796, 'Baruch', 71, 5, 5, 'انهضي يا اورشليم وقفي في الاعالي وتطلعي من حولك نحو المشرق وانظري بنيك مجتمعين من مغرب الشمس الى مشرقها بكلمة القدوس مبتهجين بذكر الله'),
(8797, 'Baruch', 71, 6, 1, 'انه لاجل الخطايا التي خطئتم امام الله يسوقكم نبوكد نصر ملك بابل في الجلاء الى بابل'),
(8798, 'Baruch', 71, 6, 2, 'فاذا دخلتم بابل فستكونون هناك سنين كثيرة وزمانا طويلا الى سبعة اجيال وبعد ذلك اخرجكم من هناك بسلام'),
(8799, 'Baruch', 71, 6, 3, 'و الان فانكم سترون في بابل الهة من الفضة والذهب والخشب تحمل على المناكب وتلقي الرهبة على الامم'),
(8800, 'Baruch', 71, 6, 4, 'فاحترزوا ان تتشبهوا بالغرباء وتاخذكم منها رهبة'),
(8801, 'Baruch', 71, 6, 5, 'و اذا رايتم الجموع امامها ووراءها يسجدون لها فقولوا في قلوبكم لك يا رب ينبغي السجود'),
(8802, 'Baruch', 71, 6, 6, 'فان ملاكي معكم وهو يطالب بانفسكم'),
(8803, 'Baruch', 71, 6, 7, 'اما تلك فان لها السنة قد نحتها النجار وهي مغشاة بالذهب والفضة لكنها الهة زور لا تستطيع نطقا'),
(8804, 'Baruch', 71, 6, 8, 'ياخذ الناس لها ذهبا كما يؤخذ لعذراء تحب الزينة'),
(8805, 'Baruch', 71, 6, 9, 'فيصوغون اكاليل يجعلونها على رؤوس الهتهم وربما سرق الكهنة من الهتهم الذهب والفضة لمنفعة انفسهم'),
(8806, 'Baruch', 71, 6, 10, 'و قد يبذلون منهما بالزواني اللاتي في البيت يزينون الالهة بالملابس كالبشر وهي من الفضة والذهب والخشب'),
(8807, 'Baruch', 71, 6, 11, 'فهي لا تسلم من الصدا والسوس وان كانت تلبس الارجوان'),
(8808, 'Baruch', 71, 6, 12, 'و يمسحون وجوهها من غبار البيت المتراكم عليها'),
(8809, 'Baruch', 71, 6, 13, 'و في يد كل منها صولجان كالحاكم على بلد لكنه لا يقتل من يجرم اليه'),
(8810, 'Baruch', 71, 6, 14, 'و في يمينه سيف وفاس لكنه لا ينجي نفسه من الحرب واللصوص فحق بذلك انها ليست الهة'),
(8811, 'Baruch', 71, 6, 15, 'فلا تخافوها فانه كما ان الاناء المكسور لا ينفع صاحبه كذلك الهتهم'),
(8812, 'Baruch', 71, 6, 16, 'اذا نصبت في البيوت فعيونها تمتلئ غبارا من اقدام الداخلين'),
(8813, 'Baruch', 71, 6, 17, 'يحظر عليها في الديار كما يحظر على من اجرم الى الملك وكهنتها يحصنون بيوتها بابواب واقفال ومزاليج كما يفعل بمن حكم عليه بالموت لئلا تسلبها اللصوص'),
(8814, 'Baruch', 71, 6, 18, 'يوقدون لها من السرج اكثر مما يوقدون لانفسهم وهي لا تستطيع ان ترى منها شيئا'),
(8815, 'Baruch', 71, 6, 19, 'انما هي كجوائز البيت وقد ذكر ان حشرات الارض تنهش قلوبها فتؤكل هي وثيابها ولا تشعر'),
(8816, 'Baruch', 71, 6, 20, 'تسود وجوهها من الدخان الذي في البيت'),
(8817, 'Baruch', 71, 6, 21, 'على ابدانها ورؤوسها تثب البوم والخطاف وسائر الطيور والسنانير'),
(8818, 'Baruch', 71, 6, 22, 'فاعلموا من ذلك انها ليست الهة فلا تخافوها'),
(8819, 'Baruch', 71, 6, 23, 'و الذهب الذي يغشيها للزينة ان لم يمسح صداه لم يكن لها رونق كما انها اذ صيغ عليها لم تشعر'),
(8820, 'Baruch', 71, 6, 24, 'تبتاع بكل ثمن وان لم يكن فيها روح'),
(8821, 'Baruch', 71, 6, 25, 'ليس لها ارجل فتحمل على المناكب وبذلك تبدي للناس هوانها والذين يعبدونها هم ايضا يخزون'),
(8822, 'Baruch', 71, 6, 26, 'لانها اذا سقطت على الارض لا تقوم من نفسها ولا اذا نصبها احد تتحرك من نفسها ولا اذا اميلت تستقيم بل تقدم اليها الهدايا كما تقدم الى اموات'),
(8823, 'Baruch', 71, 6, 27, 'و كهنتها يبيعون ذبائحها لمنفعة انفسهم وكذلك نساؤهم يملحن ما بقي منها ولا يجعلن فيها حظا لمسكين ولا سقيم'),
(8824, 'Baruch', 71, 6, 28, 'الطامث والنفساء تلمسان ذبائحها فاذ قد علمتم من ذلك انها ليست الهة فلا تخافوها'),
(8825, 'Baruch', 71, 6, 29, 'لماذا تسمى الهة لان النساء يقدمن الهدايا لهذه الالهة التي هي من الفضة والذهب والخشب'),
(8826, 'Baruch', 71, 6, 30, 'و لان الكهنة يجلسون في بيوتها باقمصة ممزقة وهم محلوقو الرؤوس واللحى ورؤوسهم مكشوفة'),
(8827, 'Baruch', 71, 6, 31, 'و يعجون صائحين امام الهتهم كالجالسين على مادبة الميت'),
(8828, 'Baruch', 71, 6, 32, 'الكهنة ينزعون من ثيابها ما يكسون نساؤهم واولادهم'),
(8829, 'Baruch', 71, 6, 33, 'و اذا اساء اليها احد او احسن فلا تستطيع المكافاة ولا في وسعها ان تقيم ملكا او تخلعه'),
(8830, 'Baruch', 71, 6, 34, 'و لا تقدر ان تهب عرضا ولا نقدا واذا نذر احد نذرا ولم يقضه فلا تطالب'),
(8831, 'Baruch', 71, 6, 35, 'لا تنحي احدا من الموت ولا تنقذ الضعيف من يد القوي'),
(8832, 'Baruch', 71, 6, 36, 'لا ترد البصر لاعمى ولا تفرج عن ذي شدة'),
(8833, 'Baruch', 71, 6, 37, 'لا ترحم ارملة ولا تحسن الى يتيم'),
(8834, 'Baruch', 71, 6, 38, 'فهذه الالهة التي هي من الخشب مغشاة بالذهب والفضة تماثل حجارة من الجبل والذين يعبدونها يخزون'),
(8835, 'Baruch', 71, 6, 39, 'فكيف يسوغ ان تحسب او تسمى الهة'),
(8836, 'Baruch', 71, 6, 40, 'بل الكلدانيون انفسهم يزدرونها فانهم اذا راوا ابكم لا ينطق يقدمونه الى بال ويطلبون منه النطق كانه يشعر'),
(8837, 'Baruch', 71, 6, 41, 'و مع اختبارهم لها لا يتركون عبادتها لانهم لا يشعرون'),
(8838, 'Baruch', 71, 6, 42, 'و النساء يقعدن على الطرق متحزمات بالحبال يبخرن بالنخالة'),
(8839, 'Baruch', 71, 6, 43, 'فاذا اجتذب مجتاز واحدة منهن وضاجعها عيرت صاحبتها بانها لم تحظ مثلها ولم يقطع حبلها'),
(8840, 'Baruch', 71, 6, 44, 'و كل ما يصنع لهذه الالهة انما هو زور فكيف يسوغ ان تحسب او تسمى الهة'),
(8841, 'Baruch', 71, 6, 45, 'هي صنعة النجار والصايغ فلا تكون الا ما يريد صانعها'),
(8842, 'Baruch', 71, 6, 46, 'و الذين صنعوها قصيرو بقاء فكيف يكون ما صنعوه'),
(8843, 'Baruch', 71, 6, 47, 'انهم تركوا لمن يليهم زورا وعارا'),
(8844, 'Baruch', 71, 6, 48, 'و اذا اتى عليها حرب وشر ياتمر الكهنة فيما بينهم اين يختبئون بها'),
(8845, 'Baruch', 71, 6, 49, 'فكيف لا يشعر انها ليست بالهة وهي لا تخلص انفسها من الحرب والشر'),
(8846, 'Baruch', 71, 6, 50, 'و بما انها من الخشب مغشاة بالذهب والفضة فسيعلم فيما بعد انها زور ويتبين لجميع الامم والملوك انها ليست الهة بل صنعة ايدي الناس ولا شيء فيها من صنعة الله'),
(8847, 'Baruch', 71, 6, 51, 'فهل من حاجة الى التنبيه على انها ليست الهة'),
(8848, 'Baruch', 71, 6, 52, 'فانها لا تقيم ملكا على بلد ولا تعطي الناس مطرا'),
(8849, 'Baruch', 71, 6, 53, 'و لا تخاصم حتى لخصومة انفسها ولا تنقذ احدا من مظلمة اذ لا تستطيع شيئا وانما هي كالغربان التي بين السماء والارض'),
(8850, 'Baruch', 71, 6, 54, 'و اذا وقعت نار في بيت هذه الالهة المصنوعة من الخشب المغشاة بالذهب او الفضة فكهنتها يفرون وينجون اما هي فتحترق كجوائز البيت'),
(8851, 'Baruch', 71, 6, 55, 'انها لا تقاوم ملكا ولا عدوا فكيف يسوغ ان تحسب او تعد الهة'),
(8852, 'Baruch', 71, 6, 56, 'و هذه الالهة المصنوعة من الخشب المغشاة بالفضة والذهب لا تنجي انفسها من السراق او اللصوص'),
(8853, 'Baruch', 71, 6, 57, 'و الذين يستولون عليها ينزعون عنها الذهب والفضة والثياب التي عليها ويذهبون بها وهي لا تدافع عن انفسها'),
(8854, 'Baruch', 71, 6, 58, 'لا جرم ان ملكا من ذوي الباس او اناء نافعا في البيت يستخدمه مالكه خير من الهة الزور وبابا في البيت يحفظ ما فيه خير من الهة الزور وعمود من الخشب في قصر خير من الهة الزور'),
(8855, 'Baruch', 71, 6, 59, 'ان الشمس والقمر والنجوم تضيء وترسل لمنفعة الخلق وتطيع مرسلها'),
(8856, 'Baruch', 71, 6, 60, 'و كذلك البرق اذا لمع يروق العين والريح تهب في كل ناحية'),
(8857, 'Baruch', 71, 6, 61, 'و السحب يامرها الله ان تمر على كل المسكونة فتقضي ما امرت به'),
(8858, 'Baruch', 71, 6, 62, 'و النار المرسلة من فوق لتفني الجبال والغاب تفعل ما اوصيت به اما تلك فلا تعدل بهذه منظرا ولا قوة'),
(8859, 'Baruch', 71, 6, 63, 'فلا يسوغ ان تحسب او تسمى الهة اذ لا تستطيع ان تجري حكما او تصنع احسانا'),
(8860, 'Baruch', 71, 6, 64, 'فاذ قد علمتم انها ليست بالهة فلا تخافوها'),
(8861, 'Baruch', 71, 6, 65, 'فانها لا تلعن الملوك ولا تباركهم'),
(8862, 'Baruch', 71, 6, 66, 'و لا تبدي ايات في الامم ولا في السماء ولا تنير كالشمس ولا تضيء كالقمر'),
(8863, 'Baruch', 71, 6, 67, 'الوحوش خير منها لان في طاقتها ان تهرب الى ملجا وتنفع انفسها'),
(8864, 'Baruch', 71, 6, 68, 'و بالجملة فلا يتبين لنا بوجه من الوجوه انها الهة فلا تخافوها'),
(8865, 'Baruch', 71, 6, 69, 'مثل الهتهم المصنوعة من الخشب المغشاة بالذهب والفضة مثل شخص منصوب في مقثاة لا يحرس شيئا'),
(8866, 'Baruch', 71, 6, 70, 'و ايضا مثل الهتهم المصنوعة من الخشب المغشاة بالذهب والفضة مثل عوسج في بستان يقع عليه كل طير او مثل ميت مطروح فيالظلمة'),
(8867, 'Baruch', 71, 6, 71, 'و من الارجوان والقرمز اللذين ياكلهما العث عليها يعلم انها ليست الهة وفي اخر الامر هي ايضا تؤكل وتصير عارا فيالافاق'),
(8868, 'Baruch', 71, 6, 72, 'ان الرجل الصديق الذي لا صنم له افضل لانه بمعزل عن العار'),
(8869, 'Colossians', 51, 1, 1, ' بولس ، رسول يسوع المسيح بمشيئة الله ، وتيموثاوس الأخ '),
(8870, 'Colossians', 51, 1, 2, ' إلى القديسين في كولوسي ، والإخوة المؤمنين في المسيح : نعمة لكم وسلام من الله أبينا والرب يسوع المسيح '),
(8871, 'Colossians', 51, 1, 3, ' نشكر الله وأبا ربنا يسوع المسيح كل حين ، مصلين لأجلكم '),
(8872, 'Colossians', 51, 1, 4, ' إذ سمعنا إيمانكم بالمسيح يسوع ، ومحبتكم لجميع القديسين '),
(8873, 'Colossians', 51, 1, 5, ' من أجل الرجاء الموضوع لكم في السماوات ، الذي سمعتم به قبلا في كلمة حق الإنجيل '),
(8874, 'Colossians', 51, 1, 6, ' الذي قد حضر إليكم كما في كل العالم أيضا ، وهو مثمر كما فيكم أيضا منذ يوم سمعتم وعرفتم نعمة الله بالحقيقة '),
(8875, 'Colossians', 51, 1, 7, ' كما تعلمتم أيضا من أبفراس العبد الحبيب معنا ، الذي هو خادم أمين للمسيح لأجلكم '),
(8876, 'Colossians', 51, 1, 8, ' الذي أخبرنا أيضا بمحبتكم في الروح '),
(8877, 'Colossians', 51, 1, 9, ' من أجل ذلك نحن أيضا ، منذ يوم سمعنا ، لم نزل مصلين وطالبين لأجلكم أن تمتلئوا من معرفة مشيئته ، في كل حكمة وفهم روحي '),
(8878, 'Colossians', 51, 1, 10, ' لتسلكوا كما يحق للرب ، في كل رضى ، مثمرين في كل عمل صالح ، ونامين في معرفة الله '),
(8879, 'Colossians', 51, 1, 11, ' متقوين بكل قوة بحسب قدرة مجده ، لكل صبر وطول أناة بفرح '),
(8880, 'Colossians', 51, 1, 12, ' شاكرين الآب الذي أهلنا لشركة ميراث القديسين في النور '),
(8881, 'Colossians', 51, 1, 13, ' الذي أنقذنا من سلطان الظلمة ، ونقلنا إلى ملكوت ابن محبته '),
(8882, 'Colossians', 51, 1, 14, ' الذي لنا فيه الفداء ، بدمه غفران الخطايا '),
(8883, 'Colossians', 51, 1, 15, ' الذي هو صورة الله غير المنظور ، بكر كل خليقة '),
(8884, 'Colossians', 51, 1, 16, ' فإنه فيه خلق الكل : ما في السماوات وما على الأرض ، ما يرى وما لا يرى ، سواء كان عروشا أم سيادات أم رياسات أم سلاطين . الكل به وله قد خلق '),
(8885, 'Colossians', 51, 1, 17, ' الذي هو قبل كل شيء ، وفيه يقوم الكل '),
(8886, 'Colossians', 51, 1, 18, ' وهو رأس الجسد : الكنيسة . الذي هو البداءة ، بكر من الأموات ، لكي يكون هو متقدما في كل شيء '),
(8887, 'Colossians', 51, 1, 19, ' لأنه فيه سر أن يحل كل الملء '),
(8888, 'Colossians', 51, 1, 20, ' وأن يصالح به الكل لنفسه ، عاملا الصلح بدم صليبه ، بواسطته ، سواء كان : ما على الأرض ، أم ما في السماوات '),
(8889, 'Colossians', 51, 1, 21, ' وأنتم الذين كنتم قبلا أجنبيين وأعداء في الفكر ، في الأعمال الشريرة ، قد صالحكم الآن '),
(8890, 'Colossians', 51, 1, 22, ' في جسم بشريته بالموت ، ليحضركم قديسين وبلا لوم ولا شكوى أمامه '),
(8891, 'Colossians', 51, 1, 23, ' إن ثبتم على الإيمان ، متأسسين وراسخين وغير منتقلين عن رجاء الإنجيل ، الذي سمعتموه ، المكروز به في كل الخليقة التي تحت السماء ، الذي صرت أنا بولس خادما له '),
(8892, 'Colossians', 51, 1, 24, ' الذي الآن أفرح في آلامي لأجلكم ، وأكمل نقائص شدائد المسيح في جسمي لأجل جسده ، الذي هو الكنيسة '),
(8893, 'Colossians', 51, 1, 25, ' التي صرت أنا خادما لها ، حسب تدبير الله المعطى لي لأجلكم ، لتتميم كلمة الله '),
(8894, 'Colossians', 51, 1, 26, ' السر المكتوم منذ الدهور ومنذ الأجيال ، لكنه الآن قد أظهر لقديسيه '),
(8895, 'Colossians', 51, 1, 27, ' الذين أراد الله أن يعرفهم ما هو غنى مجد هذا السر في الأمم ، الذي هو المسيح فيكم رجاء المجد '),
(8896, 'Colossians', 51, 1, 28, ' الذي ننادي به منذرين كل إنسان ، ومعلمين كل إنسان ، بكل حكمة ، لكي نحضر كل إنسان كاملا في المسيح يسوع '),
(8897, 'Colossians', 51, 1, 29, ' الأمر الذي لأجله أتعب أيضا مجاهدا ، بحسب عمله الذي يعمل في بقوة '),
(8898, 'Colossians', 51, 2, 1, ' فإني أريد أن تعلموا أي جهاد لي لأجلكم ، ولأجل الذين في لاودكية ، وجميع الذين لم يروا وجهي في الجسد '),
(8899, 'Colossians', 51, 2, 2, ' لكي تتعزى قلوبهم مقترنة في المحبة لكل غنى يقين الفهم ، لمعرفة سر الله الآب والمسيح '),
(8900, 'Colossians', 51, 2, 3, ' المذخر فيه جميع كنوز الحكمة والعلم '),
(8901, 'Colossians', 51, 2, 4, ' وإنما أقول هذا لئلا يخدعكم أحد بكلام ملق '),
(8902, 'Colossians', 51, 2, 5, ' فإني وإن كنت غائبا في الجسد لكني معكم في الروح ، فرحا ، وناظرا ترتيبكم ومتانة إيمانكم في المسيح '),
(8903, 'Colossians', 51, 2, 6, ' فكما قبلتم المسيح يسوع الرب اسلكوا فيه '),
(8904, 'Colossians', 51, 2, 7, ' متأصلين ومبنيين فيه ، وموطدين في الإيمان ، كما علمتم ، متفاضلين فيه بالشكر '),
(8905, 'Colossians', 51, 2, 8, ' انظروا أن لا يكون أحد يسبيكم بالفلسفة وبغرور باطل ، حسب تقليد الناس ، حسب أركان العالم ، وليس حسب المسيح '),
(8906, 'Colossians', 51, 2, 9, ' فإنه فيه يحل كل ملء اللاهوت جسديا '),
(8907, 'Colossians', 51, 2, 10, ' وأنتم مملوؤون فيه ، الذي هو رأس كل رياسة وسلطان '),
(8908, 'Colossians', 51, 2, 11, ' وبه أيضا ختنتم ختانا غير مصنوع بيد ، بخلع جسم خطايا البشرية ، بختان المسيح '),
(8909, 'Colossians', 51, 2, 12, ' مدفونين معه في المعمودية ، التي فيها أقمتم أيضا معه بإيمان عمل الله ، الذي أقامه من الأموات '),
(8910, 'Colossians', 51, 2, 13, ' وإذ كنتم أمواتا في الخطايا وغلف جسدكم ، أحياكم معه ، مسامحا لكم بجميع الخطايا '),
(8911, 'Colossians', 51, 2, 14, ' إذ محا الصك الذي علينا في الفرائض ، الذي كان ضدا لنا ، وقد رفعه من الوسط مسمرا إياه بالصليب '),
(8912, 'Colossians', 51, 2, 15, ' إذ جرد الرياسات والسلاطين أشهرهم جهارا ، ظافرا بهم فيه '),
(8913, 'Colossians', 51, 2, 16, ' فلا يحكم عليكم أحد في أكل أو شرب ، أو من جهة عيد أو هلال أو سبت '),
(8914, 'Colossians', 51, 2, 17, ' التي هي ظل الأمور العتيدة ، وأما الجسد فللمسيح '),
(8915, 'Colossians', 51, 2, 18, ' لا يخسركم أحد الجعالة ، راغبا في التواضع وعبادة الملائكة ، متداخلا في ما لم ينظره ، منتفخا باطلا من قبل ذهنه الجسدي '),
(8916, 'Colossians', 51, 2, 19, ' وغير متمسك بالرأس الذي منه كل الجسد بمفاصل وربط ، متوازرا ومقترنا ينمو نموا من الله '),
(8917, 'Colossians', 51, 2, 20, ' إذا إن كنتم قد متم مع المسيح عن أركان العالم ، فلماذا كأنكم عائشون في العالم ؟ تفرض عليكم فرائض '),
(8918, 'Colossians', 51, 2, 21, ' لا تمس ولا تذق ولا تجس '),
(8919, 'Colossians', 51, 2, 22, ' التي هي جميعها للفناء في الاستعمال ، حسب وصايا وتعاليم الناس '),
(8920, 'Colossians', 51, 2, 23, ' التي لها حكاية حكمة ، بعبادة نافلة ، وتواضع ، وقهر الجسد ، ليس بقيمة ما من جهة إشباع البشرية '),
(8921, 'Colossians', 51, 3, 1, ' فإن كنتم قد قمتم مع المسيح فاطلبوا ما فوق ، حيث المسيح جالس عن يمين الله '),
(8922, 'Colossians', 51, 3, 2, ' اهتموا بما فوق لا بما على الأرض '),
(8923, 'Colossians', 51, 3, 3, ' لأنكم قد متم وحياتكم مستترة مع المسيح في الله '),
(8924, 'Colossians', 51, 3, 4, ' متى أظهر المسيح حياتنا ، فحينئذ تظهرون أنتم أيضا معه في المجد '),
(8925, 'Colossians', 51, 3, 5, ' فأميتوا أعضاءكم التي على الأرض : الزنا ، النجاسة ، الهوى ، الشهوة الردية ، الطمع الذي هو عبادة الأوثان '),
(8926, 'Colossians', 51, 3, 6, ' الأمور التي من أجلها يأتي غضب الله على أبناء المعصية '),
(8927, 'Colossians', 51, 3, 7, ' الذين بينهم أنتم أيضا سلكتم قبلا ، حين كنتم تعيشون فيها '),
(8928, 'Colossians', 51, 3, 8, ' وأما الآن فاطرحوا عنكم أنتم أيضا الكل : الغضب ، السخط ، الخبث ، التجديف ، الكلام القبيح من أفواهكم '),
(8929, 'Colossians', 51, 3, 9, ' لا تكذبوا بعضكم على بعض ، إذ خلعتم الإنسان العتيق مع أعماله '),
(8930, 'Colossians', 51, 3, 10, ' ولبستم الجديد الذي يتجدد للمعرفة حسب صورة خالقه '),
(8931, 'Colossians', 51, 3, 11, ' حيث ليس يوناني ويهودي ، ختان وغرلة ، بربري سكيثي ، عبد حر ، بل المسيح الكل وفي الكل '),
(8932, 'Colossians', 51, 3, 12, ' فالبسوا كمختاري الله القديسين المحبوبين أحشاء رأفات ، ولطفا ، وتواضعا ، ووداعة ، وطول أناة '),
(8933, 'Colossians', 51, 3, 13, ' محتملين بعضكم بعضا ، ومسامحين بعضكم بعضا إن كان لأحد على أحد شكوى ، كما غفر لكم المسيح هكذا أنتم أيضا '),
(8934, 'Colossians', 51, 3, 14, ' وعلى جميع هذه البسوا المحبة التي هي رباط الكمال '),
(8935, 'Colossians', 51, 3, 15, ' وليملك في قلوبكم سلام الله الذي إليه دعيتم في جسد واحد ، وكونوا شاكرين '),
(8936, 'Colossians', 51, 3, 16, ' لتسكن فيكم كلمة المسيح بغنى ، وأنتم بكل حكمة معلمون ومنذرون بعضكم بعضا ، بمزامير وتسابيح وأغاني روحية ، بنعمة ، مترنمين في قلوبكم للرب '),
(8937, 'Colossians', 51, 3, 17, ' وكل ما عملتم بقول أو فعل ، فاعملوا الكل باسم الرب يسوع ، شاكرين الله والآب به '),
(8938, 'Colossians', 51, 3, 18, ' أيتها النساء ، اخضعن لرجالكن كما يليق في الرب '),
(8939, 'Colossians', 51, 3, 19, ' أيها الرجال ، أحبوا نساءكم ، ولا تكونوا قساة عليهن '),
(8940, 'Colossians', 51, 3, 20, ' أيها الأولاد ، أطيعوا والديكم في كل شيء لأن هذا مرضي في الرب '),
(8941, 'Colossians', 51, 3, 21, ' أيها الآباء ، لا تغيظوا أولادكم لئلا يفشلوا '),
(8942, 'Colossians', 51, 3, 22, ' أيها العبيد ، أطيعوا في كل شيء سادتكم حسب الجسد ، لا بخدمة العين كمن يرضي الناس ، بل ببساطة القلب ، خائفين الرب '),
(8943, 'Colossians', 51, 3, 23, ' وكل ما فعلتم ، فاعملوا من القلب ، كما للرب ليس للناس '),
(8944, 'Colossians', 51, 3, 24, ' عالمين أنكم من الرب ستأخذون جزاء الميراث ، لأنكم تخدمون الرب المسيح '),
(8945, 'Colossians', 51, 3, 25, ' وأما الظالم فسينال ما ظلم به ، وليس محاباة '),
(8946, 'Colossians', 51, 4, 1, ' أيها السادة ، قدموا للعبيد العدل والمساواة ، عالمين أن لكم أنتم أيضا سيدا في السماوات '),
(8947, 'Colossians', 51, 4, 2, ' واظبوا على الصلاة ساهرين فيها بالشكر '),
(8948, 'Colossians', 51, 4, 3, ' مصلين في ذلك لأجلنا نحن أيضا ، ليفتح الرب لنا بابا للكلام ، لنتكلم بسر المسيح ، الذي من أجله أنا موثق أيضا '),
(8949, 'Colossians', 51, 4, 4, ' كي أظهره كما يجب أن أتكلم '),
(8950, 'Colossians', 51, 4, 5, ' اسلكوا بحكمة من جهة الذين هم من خارج ، مفتدين الوقت '),
(8951, 'Colossians', 51, 4, 6, ' ليكن كلامكم كل حين بنعمة ، مصلحا بملح ، لتعلموا كيف يجب أن تجاوبوا كل واحد '),
(8952, 'Colossians', 51, 4, 7, ' جميع أحوالي سيعرفكم بها تيخيكس الأخ الحبيب ، والخادم الأمين ، والعبد معنا في الرب '),
(8953, 'Colossians', 51, 4, 8, ' الذي أرسلته إليكم لهذا عينه ، ليعرف أحوالكم ويعزي قلوبكم '),
(8954, 'Colossians', 51, 4, 9, ' مع أنسيمس الأخ الأمين الحبيب الذي هو منكم . هما سيعرفانكم بكل ما ههنا '),
(8955, 'Colossians', 51, 4, 10, ' يسلم عليكم أرسترخس المأسور معي ، ومرقس ابن أخت برنابا ، الذي أخذتم لأجله وصايا . إن أتى إليكم فاقبلوه '),
(8956, 'Colossians', 51, 4, 11, ' ويسوع المدعو يسطس ، الذين هم من الختان . هؤلاء هم وحدهم العاملون معي لملكوت الله ، الذين صاروا لي تسلية '),
(8957, 'Colossians', 51, 4, 12, ' يسلم عليكم أبفراس ، الذي هو منكم ، عبد للمسيح ، مجاهد كل حين لأجلكم بالصلوات ، لكي تثبتوا كاملين وممتلئين في كل مشيئة الله '),
(8958, 'Colossians', 51, 4, 13, ' فإني أشهد فيه أن له غيرة كثيرة لأجلكم ، ولأجل الذين في لاودكية ، والذين في هيرابوليس '),
(8959, 'Colossians', 51, 4, 14, ' يسلم عليكم لوقا الطبيب الحبيب ، وديماس '),
(8960, 'Colossians', 51, 4, 15, ' سلموا على الإخوة الذين في لاودكية ، وعلى نمفاس وعلى الكنيسة التي في بيته '),
(8961, 'Colossians', 51, 4, 16, ' ومتى قرئت عندكم هذه الرسالة فاجعلوها تقرأ أيضا في كنيسة اللاودكيين ، والتي من لاودكية تقرأونها أنتم أيضا '),
(8962, 'Colossians', 51, 4, 17, ' وقولوا لأرخبس : انظر إلى الخدمة التي قبلتها في الرب لكي تتممها '),
(8963, 'Colossians', 51, 4, 18, ' السلام بيدي أنا بولس . اذكروا وثقي . النعمة معكم . آمين '),
(8964, 'Daniel', 27, 9, 14, ' فسهر الرب على الشر وجلبه علينا ، لأن الرب إلهنا بار في كل أعماله التي عملها إذ لم نسمع صوته '),
(8965, 'Daniel', 27, 9, 15, ' والآن أيها السيد إلهنا ، الذي أخرجت شعبك من أرض مصر بيد قوية ، وجعلت لنفسك اسما كما هو هذا اليوم ، قد أخطأنا ، عملنا شرا '),
(8966, 'Daniel', 27, 9, 16, ' يا سيد ، حسب كل رحمتك اصرف سخطك وغضبك عن مدينتك أورشليم جبل قدسك ، إذ لخطايانا ولآثام آبائنا صارت أورشليم وشعبك عارا عند جميع الذين حولنا '),
(8967, 'Daniel', 27, 9, 17, ' فاسمع الآن يا إلهنا صلاة عبدك وتضرعاته ، وأضئ بوجهك على مقدسك الخرب من أجل السيد '),
(8968, 'Daniel', 27, 9, 18, ' أمل أذنك يا إلهي واسمع . افتح عينيك وانظر خربنا والمدينة التي دعي اسمك عليها ، لأنه لا لأجل برنا نطرح تضرعاتنا أمام وجهك ، بل لأجل مراحمك العظيمة '),
(8969, 'Daniel', 27, 9, 19, ' يا سيد اسمع . يا سيد اغفر . يا سيد أصغ واصنع . لا تؤخر من أجل نفسك يا إلهي ، لأن اسمك دعي على مدينتك وعلى شعبك '),
(8970, 'Daniel', 27, 9, 20, ' وبينما أنا أتكلم وأصلي وأعترف بخطيتي وخطية شعبي إسرائيل ، وأطرح تضرعي أمام الرب إلهي عن جبل قدس إلهي '),
(8971, 'Daniel', 27, 9, 21, ' وأنا متكلم بعد بالصلاة ، إذا بالرجل جبرائيل الذي رأيته في الرؤيا في الابتداء مطارا واغفا لمسني عند وقت تقدمة المساء '),
(8972, 'Daniel', 27, 9, 22, ' وفهمني وتكلم معي وقال : يا دانيآل ، إني خرجت الآن لأعلمك الفهم '),
(8973, 'Daniel', 27, 9, 23, ' في ابتداء تضرعاتك خرج الأمر ، وأنا جئت لأخبرك لأنك أنت محبوب . فتأمل الكلام وافهم الرؤيا '),
(8974, 'Daniel', 27, 9, 24, ' سبعون أسبوعا قضيت على شعبك وعلى مدينتك المقدسة لتكميل المعصية وتتميم الخطايا ، ولكفارة الإثم ، وليؤتى بالبر الأبدي ، ولختم الرؤيا والنبوة ، ولمسح قدوس القدوسين '),
(8975, 'Daniel', 27, 9, 25, ' فاعلم وافهم أنه من خروج الأمر لتجديد أورشليم وبنائها إلى المسيح الرئيس سبعة أسابيع واثنان وستون أسبوعا ، يعود ويبنى سوق وخليج في ضيق الأزمنة '),
(8976, 'Daniel', 27, 9, 26, ' وبعد اثنين وستين أسبوعا يقطع المسيح وليس له ، وشعب رئيس آت يخرب المدينة والقدس ، وانتهاؤه بغمارة ، وإلى النهاية حرب وخرب قضي بها '),
(8977, 'Daniel', 27, 9, 27, ' ويثبت عهدا مع كثيرين في أسبوع واحد ، وفي وسط الأسبوع يبطل الذبيحة والتقدمة ، وعلى جناح الأرجاس مخرب حتى يتم ويصب المقضي على المخرب '),
(8978, 'Daniel', 27, 10, 1, ' في السنة الثالثة لكورش ملك فارس كشف أمر لدانيآل الذي سمي باسم بلطشاصر . والأمر حق والجهاد عظيم ، وفهم الأمر وله معرفة الرؤيا '),
(8979, 'Daniel', 27, 10, 2, ' في تلك الأيام أنا دانيآل كنت نائحا ثلاثة أسابيع أيام '),
(8980, 'Daniel', 27, 10, 3, ' لم آكل طعاما شهيا ولم يدخل في فمي لحم ولا خمر ، ولم أدهن حتى تمت ثلاثة أسابيع أيام '),
(8981, 'Daniel', 27, 10, 4, ' وفي اليوم الرابع والعشرين من الشهر الأول ، إذ كنت على جانب النهر العظيم هو دجلة '),
(8982, 'Daniel', 27, 10, 5, ' رفعت ونظرت فإذا برجل لابس كتانا ، وحقواه متنطقان بذهب أوفاز '),
(8983, 'Daniel', 27, 10, 6, ' وجسمه كالزبرجد ، ووجهه كمنظر البرق ، وعيناه كمصباحي نار ، وذراعاه ورجلاه كعين النحاس المصقول ، وصوت كلامه كصوت جمهور '),
(8984, 'Daniel', 27, 10, 7, ' فرأيت أنا دانيآل الرؤيا وحدي ، والرجال الذين كانوا معي لم يروا الرؤيا ، لكن وقع عليهم ارتعاد عظيم ، فهربوا ليختبئوا '),
(8985, 'Daniel', 27, 10, 8, ' فبقيت أنا وحدي ، ورأيت هذه الرؤيا العظيمة . ولم تبق في قوة ، ونضارتي تحولت في إلى فساد ، ولم أضبط قوة '),
(8986, 'Daniel', 27, 10, 9, ' وسمعت صوت كلامه . ولما سمعت صوت كلامه كنت مسبخا على وجهي ، ووجهي إلى الأرض '),
(8987, 'Daniel', 27, 10, 10, ' وإذا بيد لمستني وأقامتني مرتجفا على ركبتي وعلى كفي يدي '),
(8988, 'Daniel', 27, 10, 11, ' وقال لي : يا دانيآل ، أيها الرجل المحبوب افهم الكلام الذي أكلمك به ، وقم على مقامك لأني الآن أرسلت إليك . ولما تكلم معي بهذا الكلام قمت مرتعدا '),
(8989, 'Daniel', 27, 10, 12, ' فقال لي : لا تخف يا دانيآل ، لأنه من اليوم الأول الذي فيه جعلت قلبك للفهم ولإذلال نفسك قدام إلهك ، سمع كلامك ، وأنا أتيت لأجل كلامك '),
(8990, 'Daniel', 27, 10, 13, ' ورئيس مملكة فارس وقف مقابلي واحدا وعشرين يوما ، وهوذا ميخائيل واحد من الرؤساء الأولين جاء لإعانتي ، وأنا أبقيت هناك عند ملوك فارس '),
(8991, 'Daniel', 27, 10, 14, ' وجئت لأفهمك ما يصيب شعبك في الأيام الأخيرة ، لأن الرؤيا إلى أيام بعد '),
(8992, 'Daniel', 27, 10, 15, ' فلما تكلم معي بمثل هذا الكلام جعلت وجهي إلى الأرض وصمت '),
(8993, 'Daniel', 27, 10, 16, ' وهوذا كشبه بني آدم لمس شفتي ، ففتحت فمي وتكلمت وقلت للواقف أمامي : يا سيدي ، بالرؤيا انقلبت علي أوجاعي فما ضبطت قوة '),
(8994, 'Daniel', 27, 10, 17, ' فكيف يستطيع عبد سيدي هذا ، أن يتكلم مع سيدي هذا ، وأنا فحالا ، لم تثبت في قوة ولم تبق في نسمة '),
(8995, 'Daniel', 27, 10, 18, ' فعاد ولمسني كمنظر إنسان وقواني '),
(8996, 'Daniel', 27, 10, 19, ' وقال : لا تخف أيها الرجل المحبوب . سلام لك . تشدد . تقو . ولما كلمني تقويت وقلت : ليتكلم سيدي لأنك قويتني '),
(8997, 'Daniel', 27, 10, 20, ' فقال : هل عرفت لماذا جئت إليك ؟ فالآن أرجع وأحارب رئيس فارس . فإذا خرجت هوذا رئيس اليونان يأتي '),
(8998, 'Daniel', 27, 10, 21, ' ولكني أخبرك بالمرسوم في كتاب الحق . ولا أحد يتمسك معي على هؤلاء إلا ميخائيل رئيسكم '),
(8999, 'Daniel', 27, 11, 1, ' وأنا في السنة الأولى لداريوس المادي وقفت لأشدده وأقويه '),
(9000, 'Daniel', 27, 11, 2, ' والآن أخبرك بالحق . هوذا ثلاثة ملوك أيضا يقومون في فارس ، والرابع يستغني بغنى أوفر من جميعهم ، وحسب قوته بغناه يهيج الجميع على مملكة اليونان '),
(9001, 'Daniel', 27, 11, 3, ' ويقوم ملك جبار ويتسلط تسلطا عظيما ويفعل حسب إرادته '),
(9002, 'Daniel', 27, 11, 4, ' وكقيامه تنكسر مملكته وتنقسم إلى رياح السماء الأربع ، ولا لعقبه ولا حسب سلطانه الذي تسلط به ، لأن مملكته تنقرض وتكون لآخرين غير أولئك '),
(9003, 'Daniel', 27, 11, 5, ' ويتقوى ملك الجنوب . ومن رؤسائه من يقوى عليه ويتسلط . تسلط عظيم تسلطه '),
(9004, 'Daniel', 27, 11, 6, ' وبعد سنين يتعاهدان ، وبنت ملك الجنوب تأتي إلى ملك الشمال لإجراء الاتفاق ، ولكن لا تضبط الذراع قوة ، ولا يقوم هو ولا ذراعه . وتسلم هي والذين أتوا بها والذي ولدها ومن قواها في تلك الأوقات '),
(9005, 'Daniel', 27, 11, 7, ' ويقوم من فرع أصولها قائم مكانه ، ويأتي إلى الجيش ويدخل حصن ملك الشمال ويعمل بهم ويقوى '),
(9006, 'Daniel', 27, 11, 8, ' ويسبي إلى مصر آلهتهم أيضا مع مسبوكاتهم وآنيتهم الثمينة من فضة وذهب ، ويقتصر سنين عن ملك الشمال '),
(9007, 'Daniel', 27, 11, 9, ' فيدخل ملك الجنوب إلى مملكته ويرجع إلى أرضه '),
(9008, 'Daniel', 27, 11, 10, ' وبنوه يتهيجون فيجمعون جمهور جيوش عظيمة ، ويأتي آت ويغمر ويطمو ويرجع ويحارب حتى إلى حصنه '),
(9009, 'Daniel', 27, 11, 11, ' ويغتاظ ملك الجنوب ويخرج ويحاربه أي ملك الشمال ، ويقيم جمهورا عظيما فيسلم الجمهور في يده '),
(9010, 'Daniel', 27, 11, 12, ' فإذا رفع الجمهور يرتفع قلبه ويطرح ربوات ولا يعتز '),
(9011, 'Daniel', 27, 11, 13, ' فيرجع ملك الشمال ويقيم جمهورا أكثر من الأول ، ويأتي بعد حين ، بعد سنين بجيش عظيم وثروة جزيلة '),
(9012, 'Daniel', 27, 11, 14, ' وفي تلك الأوقات يقوم كثيرون على ملك الجنوب ، وبنو العتاة من شعبك يقومون لإثبات الرؤيا ويعثرون '),
(9013, 'Daniel', 27, 11, 15, ' فيأتي ملك الشمال ويقيم مترسة ويأخذ المدينة الحصينة ، فلا تقوم أمامه ذراعا الجنوب ولا قومه المنتخب ، ولا تكون له قوة للمقاومة '),
(9014, 'Daniel', 27, 11, 16, ' والآتي عليه يفعل كإرادته وليس من يقف أمامه ، ويقوم في الأرض البهية وهي بالتمام بيده '),
(9015, 'Daniel', 27, 11, 17, ' ويجعل وجهه ليدخل بسلطان كل مملكته ، ويجعل معه صلحا ، ويعطيه بنت النساء ليفسدها ، فلا تثبت ولا تكون له '),
(9016, 'Daniel', 27, 11, 18, ' ويحول وجهه إلى الجزائر ويأخذ كثيرا منها ، ويزيل رئيس تعييره فضلا عن رد تعييره عليه '),
(9017, 'Daniel', 27, 11, 19, ' ويحول وجهه إلى حصون أرضه ويعثر ويسقط ولا يوجد '),
(9018, 'Daniel', 27, 11, 20, ' فيقوم مكانه من يعبر جابي الجزية في فخر المملكة ، وفي أيام قليلة ينكسر لا بغضب ولا بحرب '),
(9019, 'Daniel', 27, 11, 21, ' فيقوم مكانه محتقر لم يجعلوا عليه فخر المملكة ، ويأتي بغتة ويمسك المملكة بالتملقات '),
(9020, 'Daniel', 27, 11, 22, ' وأذرع الجارف تجرف من قدامه وتنكسر ، وكذلك رئيس العهد '),
(9021, 'Daniel', 27, 11, 23, ' ومن المعاهدة معه يعمل بالمكر ويصعد ويعظم بقوم قليل '),
(9022, 'Daniel', 27, 11, 24, ' يدخل بغتة على أسمن البلاد ويفعل ما لم يفعله آباؤه ولا آباء آبائه . يبذر بينهم نهبا وغنيمة وغنى ، ويفكر أفكاره على الحصون ، وذلك إلى حين '),
(9023, 'Daniel', 27, 11, 25, ' وينهض قوته وقلبه على ملك الجنوب بجيش عظيم ، وملك الجنوب يتهيج إلى الحرب بجيش عظيم وقوي جدا ، ولكنه لا يثبت لأنهم يدبرون عليه تدابير '),
(9024, 'Daniel', 27, 11, 26, ' والآكلون أطايبه يكسرونه ، وجيشه يطمو ، ويسقط كثيرون قتلى '),
(9025, 'Daniel', 27, 11, 27, ' وهذان الملكان قلبهما لفعل الشر ، ويتكلمان بالكذب على مائدة واحدة ولا ينجح ، لأن الانتهاء بعد إلى ميعاد '),
(9026, 'Daniel', 27, 11, 28, ' فيرجع إلى أرضه بغنى جزيل وقلبه على العهد المقدس ، فيعمل ويرجع إلى أرضه '),
(9027, 'Daniel', 27, 11, 29, ' وفي الميعاد يعود ويدخل الجنوب ، ولكن لا يكون الآخر كالأول '),
(9028, 'Daniel', 27, 11, 30, ' فتأتي عليه سفن من كتيم فييئس ويرجع ويغتاظ على العهد المقدس ، ويعمل ويرجع ويصغى إلى الذين تركوا العهد المقدس '),
(9029, 'Daniel', 27, 11, 31, ' وتقوم منه أذرع وتنجس المقدس الحصين ، وتنزع المحرقة الدائمة ، وتجعل الرجس المخرب '),
(9030, 'Daniel', 27, 11, 32, ' والمتعدون على العهد يغويهم بالتملقات . أما الشعب الذين يعرفون إلههم فيقوون ويعملون '),
(9031, 'Daniel', 27, 11, 33, ' والفاهمون من الشعب يعلمون كثيرين . ويعثرون بالسيف وباللهيب وبالسبي وبالنهب أياما '),
(9032, 'Daniel', 27, 11, 34, ' فإذا عثروا يعانون عونا قليلا ، ويتصل بهم كثيرون بالتملقات '),
(9033, 'Daniel', 27, 11, 35, ' وبعض الفاهمين يعثرون امتحانا لهم للتطهير وللتبييض إلى وقت النهاية . لأنه بعد إلى الميعاد '),
(9034, 'Daniel', 27, 11, 36, ' ويفعل الملك كإرادته ، ويرتفع ويتعظم على كل إله ، ويتكلم بأمور عجيبة على إله الآلهة ، وينجح إلى إتمام الغضب ، لأن المقضي به يجرى '),
(9035, 'Daniel', 27, 11, 37, ' ولا يبالي بآلهة آبائه ولا بشهوة النساء ، وبكل إله لا يبالي لأنه يتعظم على الكل '),
(9036, 'Daniel', 27, 11, 38, ' ويكرم إله الحصون في مكانه ، وإلها لم تعرفه آباؤه ، يكرمه بالذهب والفضة وبالحجارة الكريمة والنفائس '),
(9037, 'Daniel', 27, 11, 39, ' ويفعل في الحصون الحصينة بإله غريب . من يعرفه يزيده مجدا ، ويسلطهم على كثيرين ، ويقسم الأرض أجرة '),
(9038, 'Daniel', 27, 11, 40, ' ففي وقت النهاية يحاربه ملك الجنوب ، فيثور عليه ملك الشمال بمركبات وبفرسان وبسفن كثيرة ، ويدخل الأراضي ويجرف ويطمو '),
(9039, 'Daniel', 27, 1, 1, ' في السنة الثالثة من ملك يهوياقيم ملك يهوذا ، ذهب نبوخذناصر ملك بابل إلى أورشليم وحاصرها '),
(9040, 'Daniel', 27, 1, 2, ' وسلم الرب بيده يهوياقيم ملك يهوذا مع بعض آنية بيت الله ، فجاء بها إلى أرض شنعار إلى بيت إلهه ، وأدخل الآنية إلى خزانة بيت إلهه '),
(9041, 'Daniel', 27, 1, 3, ' وأمر الملك أشفنز رئيس خصيانه بأن يحضر من بني إسرائيل ومن نسل الملك ومن الشرفاء '),
(9042, 'Daniel', 27, 1, 4, ' فتيانا لا عيب فيهم ، حسان المنظر ، حاذقين في كل حكمة وعارفين معرفة وذوي فهم بالعلم ، والذين فيهم قوة على الوقوف في قصر الملك ، فيعلموهم كتابة الكلدانيين ولسانهم '),
(9043, 'Daniel', 27, 1, 5, ' وعين لهم الملك وظيفة كل يوم بيومه من أطايب الملك ومن خمر مشروبه لتربيتهم ثلاث سنين ، وعند نهايتها يقفون أمام الملك '),
(9044, 'Daniel', 27, 1, 6, ' وكان بينهم من بني يهوذا : دانيآل وحننيا وميشائيل وعزريا '),
(9045, 'Daniel', 27, 1, 7, ' فجعل لهم رئيس الخصيان أسماء ، فسمى دانيآل بلطشاصر ، وحننيا شدرخ ، وميشائيل ميشخ ، وعزريا عبدنغو '),
(9046, 'Daniel', 27, 1, 8, ' أما دانيآل فجعل في قلبه أنه لا يتنجس بأطايب الملك ولا بخمر مشروبه ، فطلب من رئيس الخصيان أن لا يتنجس '),
(9047, 'Daniel', 27, 1, 9, ' وأعطى الله دانيآل نعمة ورحمة عند رئيس الخصيان '),
(9048, 'Daniel', 27, 1, 10, ' فقال رئيس الخصيان لدانيآل : إني أخاف سيدي الملك الذي عين طعامكم وشرابكم . فلماذا يرى وجوهكم أهزل من الفتيان الذين من جيلكم ، فتدينون رأسي للملك '),
(9049, 'Daniel', 27, 1, 11, ' فقال دانيآل لرئيس السقاة الذي ولاه رئيس الخصيان على دانيآل وحننيا وميشائيل وعزريا '),
(9050, 'Daniel', 27, 1, 12, ' جرب عبيدك عشرة أيام . فليعطونا القطاني لنأكل وماء لنشرب '),
(9051, 'Daniel', 27, 1, 13, ' ولينظروا إلى مناظرنا أمامك وإلى مناظر الفتيان الذين يأكلون من أطايب الملك . ثم اصنع بعبيدك كما ترى '),
(9052, 'Daniel', 27, 1, 14, ' فسمع لهم هذا الكلام وجربهم عشرة أيام '),
(9053, 'Daniel', 27, 1, 15, ' وعند نهاية العشرة الأيام ظهرت مناظرهم أحسن وأسمن لحما من كل الفتيان الآكلين من أطايب الملك '),
(9054, 'Daniel', 27, 1, 16, ' فكان رئيس السقاة يرفع أطايبهم وخمر مشروبهم ويعطيهم قطاني '),
(9055, 'Daniel', 27, 1, 17, ' أما هؤلاء الفتيان الأربعة فأعطاهم الله معرفة وعقلا في كل كتابة وحكمة ، وكان دانيآل فهيما بكل الرؤى والأحلام '),
(9056, 'Daniel', 27, 1, 18, ' وعند نهاية الأيام التي قال الملك أن يدخلوهم بعدها ، أتى بهم رئيس الخصيان إلى أمام نبوخذناصر '),
(9057, 'Daniel', 27, 1, 19, ' وكلمهم الملك فلم يوجد بينهم كلهم مثل دانيآل وحننيا وميشائيل وعزريا . فوقفوا أمام الملك '),
(9058, 'Daniel', 27, 1, 20, ' وفي كل أمر حكمة فهم الذي سألهم عنه الملك وجدهم عشرة أضعاف فوق كل المجوس والسحرة الذين في كل مملكته '),
(9059, 'Daniel', 27, 1, 21, ' وكان دانيآل إلى السنة الأولى لكورش الملك '),
(9060, 'Daniel', 27, 2, 1, ' وفي السنة الثانية من ملك نبوخذنصر ، حلم نبوخذنصر أحلاما ، فانزعجت روحه وطار عنه نومه '),
(9061, 'Daniel', 27, 2, 2, ' فأمر الملك بأن يستدعى المجوس والسحرة والعرافون والكلدانيون ليخبروا الملك بأحلامه . فأتوا ووقفوا أمام الملك '),
(9062, 'Daniel', 27, 2, 3, ' فقال لهم الملك : قد حلمت حلما وانزعجت روحي لمعرفة الحلم '),
(9063, 'Daniel', 27, 2, 4, ' فكلم الكلدانيون الملك بالأرامية : عش أيها الملك إلى الأبد . أخبر عبيدك بالحلم فنبين تعبيره '),
(9064, 'Daniel', 27, 2, 5, ' فأجاب الملك وقال للكلدانيين : قد خرج مني القول : إن لم تنبئوني بالحلم وبتعبيره ، تصيرون إربا إربا وتجعل بيوتكم مزبلة '),
(9065, 'Daniel', 27, 2, 6, ' وإن بينتم الحلم وتعبيره ، تنالون من قبلي هدايا وحلاوين وإكراما عظيما . فبينوا لي الحلم وتعبيره '),
(9066, 'Daniel', 27, 2, 7, ' فأجابوا ثانية وقالوا : ليخبر الملك عبيده بالحلم فنبين تعبيره '),
(9067, 'Daniel', 27, 2, 8, ' أجاب الملك وقال : إني أعلم يقينا أنكم تكتسبون وقتا ، إذ رأيتم أن القول قد خرج مني '),
(9068, 'Daniel', 27, 2, 9, ' بأنه إن لم تنبئوني بالحلم فقضاؤكم واحد . لأنكم قد اتفقتم على كلام كذب وفاسد لتتكلموا به قدامي إلى أن يتحول الوقت . فأخبروني بالحلم ، فأعلم أنكم تبينون لي تعبيره '),
(9069, 'Daniel', 27, 2, 10, ' أجاب الكلدانيون قدام الملك وقالوا : ليس على الأرض إنسان يستطيع أن يبين أمر الملك . لذلك ليس ملك عظيم ذو سلطان سأل أمرا مثل هذا من مجوسي أو ساحر أو كلداني '),
(9070, 'Daniel', 27, 2, 11, ' والأمر الذي يطلبه الملك عسر ، وليس آخر يبينه قدام الملك غير الآلهة الذين ليست سكناهم مع البشر '),
(9071, 'Daniel', 27, 2, 12, ' لأجل ذلك غضب الملك واغتاظ جدا وأمر بإبادة كل حكماء بابل '),
(9072, 'Daniel', 27, 2, 13, ' فخرج الأمر ، وكان الحكماء يقتلون . فطلبوا دانيآل وأصحابه ليقتلوهم '),
(9073, 'Daniel', 27, 2, 14, ' حينئذ أجاب دانيآل بحكمة وعقل لأريوخ رئيس شرط الملك الذي خرج ليقتل حكماء بابل ، أجاب وقال لأريوخ قائد الملك '),
(9074, 'Daniel', 27, 2, 15, ' لماذا اشتد الأمر من قبل الملك ؟  . حينئذ أخبر أريوخ دانيآل بالأمر '),
(9075, 'Daniel', 27, 2, 16, ' فدخل دانيآل وطلب من الملك أن يعطيه وقتا فيبين للملك التعبير '),
(9076, 'Daniel', 27, 2, 17, ' حينئذ مضى دانيآل إلى بيته ، وأعلم حننيا وميشائيل وعزريا أصحابه بالأمر '),
(9077, 'Daniel', 27, 2, 18, ' ليطلبوا المراحم من قبل إله السماوات من جهة هذا السر ، لكي لا يهلك دانيآل وأصحابه مع سائر حكماء بابل '),
(9078, 'Daniel', 27, 2, 19, ' حينئذ لدانيآل كشف السر في رؤيا الليل . فبارك دانيآل إله السماوات '),
(9079, 'Daniel', 27, 2, 20, ' أجاب دانيآل وقال : ليكن اسم الله مباركا من الأزل وإلى الأبد ، لأن له الحكمة والجبروت '),
(9080, 'Daniel', 27, 2, 21, ' وهو يغير الأوقات والأزمنة . يعزل ملوكا وينصب ملوكا . يعطي الحكماء حكمة ، ويعلم العارفين فهما '),
(9081, 'Daniel', 27, 2, 22, ' هو يكشف العمائق والأسرار . يعلم ما هو في الظلمة ، وعنده يسكن النور '),
(9082, 'Daniel', 27, 2, 23, ' إياك يا إله آبائي أحمد ، وأسبح الذي أعطاني الحكمة والقوة وأعلمني الآن ما طلبناه منك ، لأنك أعلمتنا أمر الملك '),
(9083, 'Daniel', 27, 2, 24, ' فمن أجل ذلك دخل دانيآل إلى أريوخ الذي عينه الملك لإبادة حكماء بابل ، مضى وقال له هكذا : لا تبد حكماء بابل . أدخلني إلى قدام الملك فأبين للملك التعبير '),
(9084, 'Daniel', 27, 2, 25, ' حينئذ دخل أريوخ بدانيآل إلى قدام الملك مسرعا وقال له هكذا : قد وجدت رجلا من بني سبي يهوذا الذي يعرف الملك بالتعبير '),
(9085, 'Daniel', 27, 2, 26, ' أجاب الملك وقال لدانيآل ، الذي اسمه بلطشاصر : هل تستطيع أنت على أن تعرفني بالحلم الذي رأيت ، وبتعبيره '),
(9086, 'Daniel', 27, 2, 27, ' أجاب دانيآل قدام الملك وقال : السر الذي طلبه الملك لا تقدر الحكماء ولا السحرة ولا المجوس ولا المنجمون على أن يبينوه للملك '),
(9087, 'Daniel', 27, 2, 28, ' لكن يوجد إله في السماوات كاشف الأسرار ، وقد عرف الملك نبوخذنصر ما يكون في الأيام الأخيرة . حلمك ورؤيا رأسك على فراشك هو هذا '),
(9088, 'Daniel', 27, 2, 29, ' أنت يا أيها الملك أفكارك على فراشك صعدت إلى ما يكون من بعد هذا ، وكاشف الأسرار يعرفك بما يكون '),
(9089, 'Daniel', 27, 2, 30, ' أما أنا فلم يكشف لي هذا السر لحكمة في أكثر من كل الأحياء ، ولكن لكي يعرف الملك بالتعبير ، ولكي تعلم أفكار قلبك '),
(9090, 'Daniel', 27, 2, 31, ' أنت أيها الملك كنت تنظر وإذا بتمثال عظيم . هذا التمثال العظيم البهي جدا وقف قبالتك ، ومنظره هائل '),
(9091, 'Daniel', 27, 2, 32, ' رأس هذا التمثال من ذهب جيد . صدره وذراعاه من فضة . بطنه وفخذاه من نحاس '),
(9092, 'Daniel', 27, 2, 33, ' ساقاه من حديد . قدماه بعضهما من حديد والبعض من خزف '),
(9093, 'Daniel', 27, 2, 34, ' كنت تنظر إلى أن قطع حجر بغير يدين ، فضرب التمثال على قدميه اللتين من حديد وخزف فسحقهما '),
(9094, 'Daniel', 27, 2, 35, ' فانسحق حينئذ الحديد والخزف والنحاس والفضة والذهب معا ، وصارت كعصافة البيدر في الصيف ، فحملتها الريح فلم يوجد لها مكان . أما الحجر الذي ضرب التمثال فصار جبلا كبيرا وملأ الأرض كلها '),
(9095, 'Daniel', 27, 2, 36, ' هذا هو الحلم . فنخبر بتعبيره قدام الملك '),
(9096, 'Daniel', 27, 2, 37, ' أنت أيها الملك ملك ملوك ، لأن إله السماوات أعطاك مملكة واقتدارا وسلطانا وفخرا '),
(9097, 'Daniel', 27, 2, 38, ' وحيثما يسكن بنو البشر ووحوش البر وطيور السماء دفعها ليدك وسلطك عليها جميعها . فأنت هذا الرأس من ذهب '),
(9098, 'Daniel', 27, 2, 39, ' وبعدك تقوم مملكة أخرى أصغر منك ومملكة ثالثة أخرى من نحاس فتتسلط على كل الأرض '),
(9099, 'Daniel', 27, 2, 40, ' وتكون مملكة رابعة صلبة كالحديد ، لأن الحديد يدق ويسحق كل شيء . وكالحديد الذي يكسر تسحق وتكسر كل هؤلاء '),
(9100, 'Daniel', 27, 2, 41, ' وبما رأيت القدمين والأصابع بعضها من خزف والبعض من حديد ، فالمملكة تكون منقسمة ، ويكون فيها قوة الحديد من حيث إنك رأيت الحديد مختلطا بخزف الطين '),
(9101, 'Daniel', 27, 2, 42, ' وأصابع القدمين بعضها من حديد والبعض من خزف ، فبعض المملكة يكون قويا والبعض قصما '),
(9102, 'Daniel', 27, 2, 43, ' وبما رأيت الحديد مختلطا بخزف الطين ، فإنهم يختلطون بنسل الناس ، ولكن لا يتلاصق هذا بذاك ، كما أن الحديد لا يختلط بالخزف '),
(9103, 'Daniel', 27, 2, 44, ' وفي أيام هؤلاء الملوك ، يقيم إله السماوات مملكة لن تنقرض أبدا ، وملكها لا يترك لشعب آخر ، وتسحق وتفني كل هذه الممالك ، وهي تثبت إلى الأبد '),
(9104, 'Daniel', 27, 2, 45, ' لأنك رأيت أنه قد قطع حجر من جبل لا بيدين ، فسحق الحديد والنحاس والخزف والفضة والذهب . الله العظيم قد عرف الملك ما سيأتي بعد هذا . الحلم حق وتعبيره يقين '),
(9105, 'Daniel', 27, 2, 46, ' حينئذ خر نبوخذنصر على وجهه وسجد لدانيآل ، وأمر بأن يقدموا له تقدمة وروائح سرور '),
(9106, 'Daniel', 27, 2, 47, ' فأجاب الملك دانيآل وقال : حقا إن إلهكم إله الآلهة ورب الملوك وكاشف الأسرار ، إذ استطعت على كشف هذا السر '),
(9107, 'Daniel', 27, 2, 48, ' حينئذ عظم الملك دانيآل وأعطاه عطايا كثيرة ، وسلطه على كل ولاية بابل وجعله رئيس الشحن على جميع حكماء بابل '),
(9108, 'Daniel', 27, 2, 49, ' فطلب دانيآل من الملك ، فولى شدرخ وميشخ وعبدنغو على أعمال ولاية بابل . أما دانيآل فكان في باب الملك '),
(9109, 'Daniel', 27, 4, 1, ' من نبوخذنصر الملك إلى كل الشعوب والأمم والألسنة الساكنين في الأرض كلها : ليكثر سلامكم '),
(9110, 'Daniel', 27, 4, 2, ' الآيات والعجائب التي صنعها معي الله العلي ، حسن عندي أن أخبر بها '),
(9111, 'Daniel', 27, 4, 3, ' آياته ما أعظمها ، وعجائبه ما أقواها ملكوته ملكوت أبدي وسلطانه إلى دور فدور '),
(9112, 'Daniel', 27, 4, 4, ' أنا نبوخذنصر قد كنت مطمئنا في بيتي وناضرا في قصري '),
(9113, 'Daniel', 27, 4, 5, ' رأيت حلما فروعني ، والأفكار على فراشي ورؤى رأسي أفزعتني '),
(9114, 'Daniel', 27, 4, 6, ' فصدر مني أمر بإحضار جميع حكماء بابل قدامي ليعرفوني بتعبير الحلم '),
(9115, 'Daniel', 27, 4, 7, ' حينئذ حضر المجوس والسحرة والكلدانيون والمنجمون ، وقصصت الحلم عليهم ، فلم يعرفوني بتعبيره '),
(9116, 'Daniel', 27, 4, 8, ' أخيرا دخل قدامي دانيآل الذي اسمه بلطشاصر كاسم إلهي ، والذي فيه روح الآلهة القدوسين ، فقصصت الحلم قدامه '),
(9117, 'Daniel', 27, 4, 9, ' يا بلطشاصر ، كبير المجوس ، من حيث إني أعلم أن فيك روح الآلهة القدوسين ، ولا يعسر عليك سر ، فأخبرني برؤى حلمي الذي رأيته وبتعبيره '),
(9118, 'Daniel', 27, 4, 10, ' فرؤى رأسي على فراشي هي : أني كنت أرى فإذا بشجرة في وسط الأرض وطولها عظيم '),
(9119, 'Daniel', 27, 4, 11, ' فكبرت الشجرة وقويت ، فبلغ علوها إلى السماء ومنظرها إلى أقصى كل الأرض '),
(9120, 'Daniel', 27, 4, 12, ' أوراقها جميلة وثمرها كثير وفيها طعام للجميع ، وتحتها استظل حيوان البر ، وفي أغصانها سكنت طيور السماء ، وطعم منها كل البشر '),
(9121, 'Daniel', 27, 4, 13, ' كنت أرى في رؤى رأسي على فراشي وإذا بساهر وقدوس نزل من السماء '),
(9122, 'Daniel', 27, 4, 14, ' فصرخ بشدة وقال هكذا : اقطعوا الشجرة ، واقضبوا أغصانها ، وانثروا أوراقها ، وابذروا ثمرها ، ليهرب الحيوان من تحتها والطيور من أغصانها ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(9123, 'Daniel', 27, 4, 15, ' ولكن اتركوا ساق أصلها في الأرض ، وبقيد من حديد ونحاس في عشب الحقل ، وليبتل بندى السماء ، وليكن نصيبه مع الحيوان في عشب الحقل '),
(9124, 'Daniel', 27, 4, 16, ' ليتغير قلبه عن الإنسانية ، وليعط قلب حيوان ، ولتمض عليه سبعة أزمنة '),
(9125, 'Daniel', 27, 4, 17, ' هذا الأمر بقضاء الساهرين ، والحكم بكلمة القدوسين ، لكى تعلم الأحياء أن العلي متسلط في مملكة الناس ، فيعطيها من يشاء ، وينصب عليها أدنى الناس '),
(9126, 'Daniel', 27, 4, 18, ' هذا الحلم رأيته أنا نبوخذنصر الملك . أما أنت يا بلطشاصر فبين تعبيره ، لأن كل حكماء مملكتي لا يستطيعون أن يعرفوني بالتعبير . أما أنت فتستطيع ، لأن فيك روح الآلهة القدوسين '),
(9127, 'Daniel', 27, 4, 19, ' حينئذ تحير دانيآل الذي اسمه بلطشاصر ساعة واحدة وأفزعته أفكاره . أجاب الملك وقال : يا بلطشاصر ، لا يفزعك الحلم ولا تعبيره . فأجاب بلطشاصر وقال : يا سيدي ، الحلم لمبغضيك وتعبيره لأعاديك '),
(9128, 'Daniel', 27, 4, 20, ' الشجرة التي رأيتها ، التي كبرت وقويت وبلغ علوها إلى السماء ، ومنظرها إلى كل الأرض '),
(9129, 'Daniel', 27, 4, 21, ' وأوراقها جميلة وثمرها كثير وفيها طعام للجميع ، وتحتها سكن حيوان البر ، وفي أغصانها سكنت طيور السماء '),
(9130, 'Daniel', 27, 4, 22, ' إنما هي أنت يا أيها الملك ، الذي كبرت وتقويت ، وعظمتك قد زادت وبلغت إلى السماء ، وسلطانك إلى أقصى الأرض '),
(9131, 'Daniel', 27, 4, 23, ' وحيث رأى الملك ساهرا وقدوسا نزل من السماء وقال : اقطعوا الشجرة وأهلكوها ، ولكن اتركوا ساق أصلها في الأرض ، وبقيد من حديد ونحاس في عشب الحقل ، وليبتل بندى السماء ، وليكن نصيبه مع حيوان البر ، حتى تمضي عليه سبعة أزمنة '),
(9132, 'Daniel', 27, 4, 24, ' فهذا هو التعبير أيها الملك ، وهذا هو قضاء العلي الذي يأتي على سيدي الملك '),
(9133, 'Daniel', 27, 4, 25, ' يطردونك من بين الناس ، وتكون سكناك مع حيوان البر ويطعمونك العشب كالثيران ، ويبلونك بندى السماء ، فتمضي عليك سبعة أزمنة حتى تعلم أن العلي متسلط في مملكة الناس ويعطيها من يشاء '),
(9134, 'Daniel', 27, 4, 26, ' وحيث أمروا بترك ساق أصول الشجرة ، فإن مملكتك تثبت لك عندما تعلم أن السماء سلطان '),
(9135, 'Daniel', 27, 4, 27, ' لذلك أيها الملك ، فلتكن مشورتي مقبولة لديك ، وفارق خطاياك بالبر وآثامك بالرحمة للمساكين ، لعله يطال اطمئنانك '),
(9136, 'Daniel', 27, 4, 28, ' كل هذا جاء على نبوخذنصر الملك '),
(9137, 'Daniel', 27, 4, 29, ' عند نهاية اثني عشر شهرا كان يتمشى على قصر مملكة بابل '),
(9138, 'Daniel', 27, 4, 30, ' وأجاب الملك فقال : أليست هذه بابل العظيمة التي بنيتها لبيت الملك بقوة اقتداري ، ولجلال مجدي '),
(9139, 'Daniel', 27, 4, 31, ' والكلمة بعد بفم الملك ، وقع صوت من السماء قائلا : لك يقولون يا نبوخذنصر الملك : إن الملك قد زال عنك '),
(9140, 'Daniel', 27, 4, 32, ' ويطردونك من بين الناس ، وتكون سكناك مع حيوان البر ، ويطعمونك العشب كالثيران ، فتمضي عليك سبعة أزمنة حتى تعلم أن العلي متسلط في مملكة الناس وأنه يعطيها من يشاء '),
(9141, 'Daniel', 27, 4, 33, ' في تلك الساعة تم الأمر على نبوخذنصر ، فطرد من بين الناس ، وأكل العشب كالثيران ، وابتل جسمه بندى السماء حتى طال شعره مثل النسور ، وأظفاره مثل الطيور '),
(9142, 'Daniel', 27, 4, 34, ' وعند انتهاء الأيام ، أنا نبوخذنصر ، رفعت عيني إلى السماء ، فرجع إلي عقلي ، وباركت العلي وسبحت وحمدت الحي إلى الأبد ، الذي سلطانه سلطان أبدي ، وملكوته إلى دور فدور '),
(9143, 'Daniel', 27, 4, 35, ' وحسبت جميع سكان الأرض كلا شيء ، وهو يفعل كما يشاء في جند السماء وسكان الأرض ، ولا يوجد من يمنع يده أو يقول له : ماذا تفعل '),
(9144, 'Daniel', 27, 4, 36, ' في ذلك الوقت رجع إلي عقلي ، وعاد إلي جلال مملكتي ومجدي وبهائي ، وطلبني مشيري وعظمائي ، وتثبت على مملكتي وازدادت لي عظمة كثيرة '),
(9145, 'Daniel', 27, 4, 37, ' فالآن ، أنا نبوخذنصر ، أسبح وأعظم وأحمد ملك السماء ، الذي كل أعماله حق وطرقه عدل ، ومن يسلك بالكبرياء فهو قادر على أن يذله '),
(9146, 'Daniel', 27, 5, 1, ' بيلشاصر الملك صنع وليمة عظيمة لعظمائه الألف ، وشرب خمرا قدام الألف '),
(9147, 'Daniel', 27, 5, 2, ' وإذ كان بيلشاصر يذوق الخمر ، أمر بإحضار آنية الذهب والفضة التي أخرجها نبوخذنصر أبوه من الهيكل الذي في أورشليم ، ليشرب بها الملك وعظماؤه وزوجاته وسراريه '),
(9148, 'Daniel', 27, 5, 3, ' حينئذ أحضروا آنية الذهب التي أخرجت من هيكل بيت الله الذي في أورشليم ، وشرب بها الملك وعظماؤه وزوجاته وسراريه '),
(9149, 'Daniel', 27, 5, 4, ' كانوا يشربون الخمر ويسبحون آلهة الذهب والفضة والنحاس والحديد والخشب والحجر '),
(9150, 'Daniel', 27, 5, 5, ' في تلك الساعة ظهرت أصابع يد إنسان ، وكتبت بإزاء النبراس على مكلس حائط قصر الملك ، والملك ينظر طرف اليد الكاتبة '),
(9151, 'Daniel', 27, 5, 6, ' حينئذ تغيرت هيئة الملك وأفزعته أفكاره ، وانحلت خرز حقويه ، واصطكت ركبتاه '),
(9152, 'Daniel', 27, 5, 7, ' فصرخ الملك بشدة لإدخال السحرة والكلدانيين والمنجمين ، فأجاب الملك وقال لحكماء بابل : أي رجل يقرأ هذه الكتابة ويبين لي تفسيرها فإنه يلبس الأرجوان وقلادة من ذهب في عنقه ، ويتسلط ثالثا في المملكة '),
(9153, 'Daniel', 27, 5, 8, ' ثم دخل كل حكماء الملك ، فلم يستطيعوا أن يقرأوا الكتابة ، ولا أن يعرفوا الملك بتفسيرها '),
(9154, 'Daniel', 27, 5, 9, ' ففزع الملك بيلشاصر جدا وتغيرت فيه هيئته ، واضطرب عظماؤه '),
(9155, 'Daniel', 27, 5, 10, ' أما الملكة فلسبب كلام الملك وعظمائه دخلت بيت الوليمة ، فأجابت الملكة وقالت : أيها الملك ، عش إلى الأبد لا تفزعك أفكارك ولا تتغير هيئتك '),
(9156, 'Daniel', 27, 5, 11, ' يوجد في مملكتك رجل فيه روح الآلهة القدوسين ، وفي أيام أبيك وجدت فيه نيرة وفطنة وحكمة كحكمة الآلهة ، والملك نبوخذنصر أبوك جعله كبير المجوس والسحرة والكلدانيين والمنجمين . أبوك الملك '),
(9157, 'Daniel', 27, 5, 12, ' من حيث إن روحا فاضلة ومعرفة وفطنة وتعبير الأحلام وتبيين ألغاز وحل عقد وجدت في دانيآل هذا ، الذي سماه الملك بلطشاصر . فليدع الآن دانيآل فيبين التفسير '),
(9158, 'Daniel', 27, 5, 13, ' حينئذ أدخل دانيآل إلى قدام الملك . فأجاب الملك وقال لدانيآل : أأنت هو دانيآل من بني سبي يهوذا ، الذي جلبه أبي الملك من يهوذا '),
(9159, 'Daniel', 27, 5, 14, ' قد سمعت عنك أن فيك روح الآلهة ، وأن فيك نيرة وفطنة وحكمة فاضلة '),
(9160, 'Daniel', 27, 5, 15, ' والآن أدخل قدامي الحكماء والسحرة ليقرأوا هذه الكتابة ويعرفوني بتفسيرها ، فلم يستطيعوا أن يبينوا تفسير الكلام '),
(9161, 'Daniel', 27, 5, 16, ' وأنا قد سمعت عنك أنك تستطيع أن تفسر تفسيرا وتحل عقدا . فإن استطعت الآن أن تقرأ الكتابة وتعرفني بتفسيرها فتلبس الأرجوان وقلادة من ذهب في عنقك وتتسلط ثالثا في المملكة '),
(9162, 'Daniel', 27, 5, 17, ' فأجاب دانيآل وقال قدام الملك : لتكن عطاياك لنفسك وهب هباتك لغيري . لكني أقرأ الكتابة للملك وأعرفه بالتفسير '),
(9163, 'Daniel', 27, 5, 18, ' أنت أيها الملك ، فالله العلي أعطى أباك نبوخذنصر ملكوتا وعظمة وجلالا وبهاء '),
(9164, 'Daniel', 27, 5, 19, ' وللعظمة التي أعطاه إياها كانت ترتعد وتفزع قدامه جميع الشعوب والأمم والألسنة . فأيا شاء قتل ، وأيا شاء استحيا ، وأيا شاء رفع ، وأيا شاء وضع '),
(9165, 'Daniel', 27, 5, 20, ' فلما ارتفع قلبه وقست روحه تجبرا ، انحط عن كرسي ملكه ، ونزعوا عنه جلاله '),
(9166, 'Daniel', 27, 5, 21, ' وطرد من بين الناس ، وتساوى قلبه بالحيوان ، وكانت سكناه مع الحمير الوحشية ، فأطعموه العشب كالثيران ، وابتل جسمه بندى السماء ، حتى علم أن الله العلي سلطان في مملكة الناس ، وأنه يقيم عليها من يشاء '),
(9167, 'Daniel', 27, 5, 22, ' وأنت يا بيلشاصر ابنه لم تضع قلبك ، مع أنك عرفت كل هذا '),
(9168, 'Daniel', 27, 5, 23, ' بل تعظمت على رب السماء ، فأحضروا قدامك آنية بيته ، وأنت وعظماؤك وزوجاتك وسراريك شربتم بها الخمر ، وسبحت آلهة الفضة والذهب والنحاس والحديد والخشب والحجر التي لا تبصر ولا تسمع ولا تعرف . أما الله الذي بيده نسمتك ، وله كل طرقك فلم تمجده '),
(9169, 'Daniel', 27, 5, 24, ' حينئذ أرسل من قبله طرف اليد ، فكتبت هذه الكتابة '),
(9170, 'Daniel', 27, 5, 25, ' وهذه هي الكتابة التي سطرت : منا منا تقيل وفرسين '),
(9171, 'Daniel', 27, 5, 26, ' وهذا تفسير الكلام : منا ، أحصى الله ملكوتك وأنهاه '),
(9172, 'Daniel', 27, 5, 27, ' تقيل ، وزنت بالموازين فوجدت ناقصا '),
(9173, 'Daniel', 27, 5, 28, ' فرس ، قسمت مملكتك وأعطيت لمادي وفارس '),
(9174, 'Daniel', 27, 5, 29, ' حينئذ أمر بيلشاصر أن يلبسوا دانيآل الأرجوان وقلادة من ذهب في عنقه ، وينادوا عليه أنه يكون متسلطا ثالثا في المملكة '),
(9175, 'Daniel', 27, 5, 30, ' في تلك الليلة قتل بيلشاصر ملك الكلدانيين '),
(9176, 'Daniel', 27, 5, 31, ' فأخذ المملكة داريوس المادي وهو ابن اثنتين وستين سنة '),
(9177, 'Daniel', 27, 6, 1, ' حسن عند داريوس أن يولي على المملكة مئة وعشرين مرزبانا يكونون على المملكة كلها '),
(9178, 'Daniel', 27, 6, 2, ' وعلى هؤلاء ثلاثة وزراء أحدهم دانيآل ، لتؤدي المرازبة إليهم الحساب فلا تصيب الملك خسارة '),
(9179, 'Daniel', 27, 6, 3, ' ففاق دانيآل هذا على الوزراء والمرازبة ، لأن فيه روحا فاضلة . وفكر الملك في أن يوليه على المملكة كلها '),
(9180, 'Daniel', 27, 6, 4, ' ثم إن الوزراء والمرازبة كانوا يطلبون علة يجدونها على دانيآل من جهة المملكة ، فلم يقدروا أن يجدوا علة ولا ذنبا ، لأنه كان أمينا ولم يوجد فيه خطأ ولا ذنب '),
(9181, 'Daniel', 27, 6, 5, ' فقال هؤلاء الرجال : لا نجد على دانيآل هذا علة إلا أن نجدها من جهة شريعة إلهه '),
(9182, 'Daniel', 27, 6, 6, ' حينئذ اجتمع هؤلاء الوزراء والمرازبة عند الملك وقالوا له هكذا : أيها الملك داريوس ، عش إلى الأبد '),
(9183, 'Daniel', 27, 6, 7, ' إن جميع وزراء المملكة والشحن والمرازبة والمشيرين والولاة قد تشاوروا على أن يضعوا أمرا ملكيا ويشددوا نهيا ، بأن كل من يطلب طلبة حتى ثلاثين يوما من إله أو إنسان إلا منك أيها الملك ، يطرح في جب الأسود '),
(9184, 'Daniel', 27, 6, 8, ' فثبت الآن النهي أيها الملك ، وأمض الكتابة لكي لا تتغير ، كشريعة مادي وفارس التي لا تنسخ '),
(9185, 'Daniel', 27, 6, 9, ' لأجل ذلك أمضى الملك داريوس الكتابة والنهي '),
(9186, 'Daniel', 27, 6, 10, ' فلما علم دانيآل بإمضاء الكتابة ذهب إلى بيته ، وكواه مفتوحة في عليته نحو أورشليم ، فجثا على ركبتيه ثلاث مرات في اليوم ، وصلى وحمد قدام إلهه كما كان يفعل قبل ذلك '),
(9187, 'Daniel', 27, 6, 11, ' فاجتمع حينئذ هؤلاء الرجال فوجدوا دانيآل يطلب ويتضرع قدام إلهه '),
(9188, 'Daniel', 27, 6, 12, ' فتقدموا وتكلموا قدام الملك في نهي الملك : ألم تمض أيها الملك نهيا بأن كل إنسان يطلب من إله أو إنسان حتى ثلاثين يوما إلا منك أيها الملك يطرح في جب الأسود ؟  . فأجاب الملك وقال : الأمر صحيح كشريعة مادي وفارس التي لا تنسخ '),
(9189, 'Daniel', 27, 6, 13, ' حينئذ أجابوا وقالوا قدام الملك : إن دانيآل الذي من بني سبي يهوذا لم يجعل لك أيها الملك اعتبارا ولا للنهي الذي أمضيته ، بل ثلاث مرات في اليوم يطلب طلبته '),
(9190, 'Daniel', 27, 6, 14, ' فلما سمع الملك هذا الكلام اغتاظ على نفسه جدا ، وجعل قلبه على دانيآل لينجيه ، واجتهد إلى غروب الشمس لينقذه '),
(9191, 'Daniel', 27, 6, 15, ' فاجتمع أولئك الرجال إلى الملك وقالوا للملك : اعلم أيها الملك أن شريعة مادي وفارس هي أن كل نهي أو أمر يضعه الملك لا يتغير '),
(9192, 'Daniel', 27, 6, 16, ' حينئذ أمر الملك فأحضروا دانيآل وطرحوه في جب الأسود . أجاب الملك وقال لدانيآل : إن إلهك الذي تعبده دائما هو ينجيك '),
(9193, 'Daniel', 27, 6, 17, ' وأتي بحجر ووضع على فم الجب وختمه الملك بخاتمه وخاتم عظمائه ، لئلا يتغير القصد في دانيآل '),
(9194, 'Daniel', 27, 6, 18, ' حينئذ مضى الملك إلى قصره وبات صائما ، ولم يؤت قدامه بسراريه وطار عنه نومه '),
(9195, 'Daniel', 27, 6, 19, ' ثم قام الملك باكرا عند الفجر وذهب مسرعا إلى جب الأسود '),
(9196, 'Daniel', 27, 6, 20, ' فلما اقترب إلى الجب نادى دانيآل بصوت أسيف . أجاب الملك وقال لدانيآل : يا دانيآل عبد الله الحي ، هل إلهك الذي تعبده دائما قدر على أن ينجيك من الأسود '),
(9197, 'Daniel', 27, 6, 21, ' فتكلم دانيآل مع الملك : يا أيها الملك ، عش إلى الأبد '),
(9198, 'Daniel', 27, 6, 22, ' إلهي أرسل ملاكه وسد أفواه الأسود فلم تضرني ، لأني وجدت بريئا قدامه ، وقدامك أيضا أيها الملك ، لم أفعل ذنبا '),
(9199, 'Daniel', 27, 6, 23, ' حينئذ فرح الملك به ، وأمر بأن يصعد دانيآل من الجب . فأصعد دانيآل من الجب ولم يوجد فيه ضرر ، لأنه آمن بإلهه '),
(9200, 'Daniel', 27, 6, 24, ' فأمر الملك فأحضروا أولئك الرجال الذين اشتكوا على دانيآل وطرحوهم في جب الأسود هم وأولادهم ونساءهم . ولم يصلوا إلى أسفل الجب حتى بطشت بهم الأسود وسحقت كل عظامهم '),
(9201, 'Daniel', 27, 6, 25, ' ثم كتب الملك داريوس إلى كل الشعوب والأمم والألسنة الساكنين في الأرض كلها : ليكثر سلامكم '),
(9202, 'Daniel', 27, 6, 26, ' من قبلي صدر أمر بأنه في كل سلطان مملكتي يرتعدون ويخافون قدام إله دانيآل ، لأنه هو الإله الحي القيوم إلى الأبد ، وملكوته لن يزول وسلطانه إلى المنتهى '),
(9203, 'Daniel', 27, 6, 27, ' هو ينجي وينقذ ويعمل الآيات والعجائب في السماوات وفي الأرض . هو الذي نجى دانيآل من يد الأسود '),
(9204, 'Daniel', 27, 6, 28, ' فنجح دانيآل هذا في ملك داريوس وفي ملك كورش الفارسي '),
(9205, 'Daniel', 27, 7, 1, ' في السنة الأولى لبيلشاصر ملك بابل ، رأى دانيآل حلما ورؤى رأسه على فراشه . حينئذ كتب الحلم وأخبر برأس الكلام '),
(9206, 'Daniel', 27, 7, 2, ' أجاب دانيآل وقال : كنت أرى في رؤياي ليلا وإذا بأربع رياح السماء هجمت على البحر الكبير '),
(9207, 'Daniel', 27, 7, 3, ' وصعد من البحر أربعة حيوانات عظيمة ، هذا مخالف ذاك '),
(9208, 'Daniel', 27, 7, 4, ' الأول كالأسد وله جناحا نسر . وكنت أنظر حتى انتتف جناحاه وانتصب عن الأرض ، وأوقف على رجلين كإنسان ، وأعطي قلب إنسان '),
(9209, 'Daniel', 27, 7, 5, ' وإذا بحيوان آخر ثان شبيه بالدب ، فارتفع على جنب واحد وفي فمه ثلاث أضلع بين أسنانه ، فقالوا له هكذا : قم كل لحما كثيرا '),
(9210, 'Daniel', 27, 7, 6, ' وبعد هذا كنت أرى وإذا بآخر مثل النمر وله على ظهره أربعة أجنحة طائر . وكان للحيوان أربعة رؤوس ، وأعطي سلطانا '),
(9211, 'Daniel', 27, 7, 7, ' بعد هذا كنت أرى في رؤى الليل وإذا بحيوان رابع هائل وقوي وشديد جدا ، وله أسنان من حديد كبيرة . أكل وسحق وداس الباقي برجليه . وكان مخالفا لكل الحيوانات الذين قبله ، وله عشرة قرون '),
(9212, 'Daniel', 27, 7, 8, ' كنت متأملا بالقرون ، وإذا بقرن آخر صغير طلع بينها ، وقلعت ثلاثة من القرون الأولى من قدامه ، وإذا بعيون كعيون الإنسان في هذا القرن ، وفم متكلم بعظائم '),
(9213, 'Daniel', 27, 7, 9, ' كنت أرى أنه وضعت عروش ، وجلس القديم الأيام . لباسه أبيض كالثلج ، وشعر رأسه كالصوف النقي ، وعرشه لهيب نار ، وبكراته نار متقدة '),
(9214, 'Daniel', 27, 7, 10, ' نهر نار جرى وخرج من قدامه . ألوف ألوف تخدمه ، وربوات ربوات وقوف قدامه . فجلس الدين ، وفتحت الأسفار '),
(9215, 'Daniel', 27, 7, 11, ' كنت أنظر حينئذ من أجل صوت الكلمات العظيمة التي تكلم بها القرن . كنت أرى إلى أن قتل الحيوان وهلك جسمه ودفع لوقيد النار '),
(9216, 'Daniel', 27, 7, 12, ' أما باقي الحيوانات فنزع عنهم سلطانهم ، ولكن أعطوا طول حياة إلى زمان ووقت '),
(9217, 'Daniel', 27, 7, 13, ' كنت أرى في رؤى الليل وإذا مع سحب السماء مثل ابن إنسان أتى وجاء إلى القديم الأيام ، فقربوه قدامه '),
(9218, 'Daniel', 27, 7, 14, ' فأعطي سلطانا ومجدا وملكوتا لتتعبد له كل الشعوب والأمم والألسنة . سلطانه سلطان أبدي ما لن يزول ، وملكوته ما لا ينقرض '),
(9219, 'Daniel', 27, 7, 15, ' أما أنا دانيآل فحزنت روحي في وسط جسمي وأفزعتني رؤى رأسي '),
(9220, 'Daniel', 27, 7, 16, ' فاقتربت إلى واحد من الوقوف وطلبت منه الحقيقة في كل هذا . فأخبرني وعرفني تفسير الأمور '),
(9221, 'Daniel', 27, 7, 17, ' هؤلاء الحيوانات العظيمة التي هي أربعة ، هي أربعة ملوك يقومون على الأرض '),
(9222, 'Daniel', 27, 7, 18, ' أما قديسو العلي فيأخذون المملكة ويمتلكون المملكة إلى الأبد وإلى أبد الآبدين '),
(9223, 'Daniel', 27, 7, 19, ' حينئذ رمت الحقيقة من جهة الحيوان الرابع الذي كان مخالفا لكلها ، وهائلا جدا وأسنانه من حديد وأظفاره من نحاس ، وقد أكل وسحق وداس الباقي برجليه '),
(9224, 'Daniel', 27, 7, 20, ' وعن القرون العشرة التي برأسه ، وعن الآخر الذي طلع فسقطت قدامه ثلاثة . وهذا القرن له عيون وفم متكلم بعظائم ومنظره أشد من رفقائه '),
(9225, 'Daniel', 27, 7, 21, ' وكنت أنظر وإذا هذا القرن يحارب القديسين فغلبهم '),
(9226, 'Daniel', 27, 7, 22, ' حتى جاء القديم الأيام ، وأعطي الدين لقديسي العلي ، وبلغ الوقت ، فامتلك القديسون المملكة '),
(9227, 'Daniel', 27, 7, 23, ' فقال هكذا : أما الحيوان الرابع فتكون مملكة رابعة على الأرض مخالفة لسائر الممالك ، فتأكل الأرض كلها وتدوسها وتسحقها '),
(9228, 'Daniel', 27, 7, 24, ' والقرون العشرة من هذه المملكة هي عشرة ملوك يقومون ، ويقوم بعدهم آخر ، وهو مخالف الأولين ، ويذل ثلاثة ملوك '),
(9229, 'Daniel', 27, 7, 25, ' ويتكلم بكلام ضد العلي ويبلي قديسي العلي ، ويظن أنه يغير الأوقات والسنة ، ويسلمون ليده إلى زمان وأزمنة ونصف زمان '),
(9230, 'Daniel', 27, 7, 26, ' فيجلس الدين وينزعون عنه سلطانه ليفنوا ويبيدوا إلى المنتهى '),
(9231, 'Daniel', 27, 7, 27, ' والمملكة والسلطان وعظمة المملكة تحت كل السماء تعطى لشعب قديسي العلي . ملكوته ملكوت أبدي ، وجميع السلاطين إياه يعبدون ويطيعون '),
(9232, 'Daniel', 27, 7, 28, ' إلى هنا نهاية الأمر . أما أنا دانيآل ، فأفكاري أفزعتني كثيرا ، وتغيرت علي هيئتي ، وحفظت الأمر في قلبي '),
(9233, 'Daniel', 27, 8, 1, ' في السنة الثالثة من ملك بيلشاصر الملك ، ظهرت لي أنا دانيآل رؤيا بعد التي ظهرت لي في الابتداء '),
(9234, 'Daniel', 27, 8, 2, ' فرأيت في الرؤيا ، وكان في رؤياي وأنا في شوشان القصر الذي في ولاية عيلام ، ورأيت في الرؤيا وأنا عند نهر أولاي '),
(9235, 'Daniel', 27, 8, 3, ' فرفعت عيني ورأيت وإذا بكبش واقف عند النهر وله قرنان والقرنان عاليان ، والواحد أعلى من الآخر ، والأعلى طالع أخيرا '),
(9236, 'Daniel', 27, 8, 4, ' رأيت الكبش ينطح غربا وشمالا وجنوبا فلم يقف حيوان قدامه ولا منقذ من يده ، وفعل كمرضاته وعظم '),
(9237, 'Daniel', 27, 8, 5, ' وبينما كنت متأملا إذا بتيس من المعز جاء من المغرب على وجه كل الأرض ولم يمس الأرض ، وللتيس قرن معتبر بين عينيه '),
(9238, 'Daniel', 27, 8, 6, ' وجاء إلى الكبش صاحب القرنين الذي رأيته واقفا عند النهر وركض إليه بشدة قوته '),
(9239, 'Daniel', 27, 8, 7, ' ورأيته قد وصل إلى جانب الكبش ، فاستشاط عليه وضرب الكبش وكسر قرنيه ، فلم تكن للكبش قوة على الوقوف أمامه ، وطرحه على الأرض وداسه ، ولم يكن للكبش منقذ من يده. '),
(9240, 'Daniel', 27, 8, 8, ' فتعظم تيس المعز جدا . ولما اعتز انكسر القرن العظيم ، وطلع عوضا عنه أربعة قرون معتبرة نحو رياح السماء الأربع '),
(9241, 'Daniel', 27, 8, 9, ' ومن واحد منها خرج قرن صغير ، وعظم جدا نحو الجنوب ونحو الشرق ونحو فخر الأراضي '),
(9242, 'Daniel', 27, 8, 10, ' وتعظم حتى إلى جند السماوات ، وطرح بعضا من الجند والنجوم إلى الأرض وداسهم '),
(9243, 'Daniel', 27, 8, 11, ' وحتى إلى رئيس الجند تعظم ، وبه أبطلت المحرقة الدائمة ، وهدم مسكن مقدسه '),
(9244, 'Daniel', 27, 8, 12, ' وجعل جند على المحرقة الدائمة بالمعصية ، فطرح الحق على الأرض وفعل ونجح '),
(9245, 'Daniel', 27, 8, 13, ' فسمعت قدوسا واحدا يتكلم . فقال قدوس واحد لفلان المتكلم : إلى متى الرؤيا من جهة المحرقة الدائمة ومعصية الخراب ، لبذل القدس والجند مدوسين '),
(9246, 'Daniel', 27, 8, 14, ' فقال لي : إلى ألفين وثلاث مئة صباح ومساء ، فيتبرأ القدس '),
(9247, 'Daniel', 27, 8, 15, ' وكان لما رأيت أنا دانيآل الرؤيا وطلبت المعنى ، إذا بشبه إنسان واقف قبالتي '),
(9248, 'Daniel', 27, 8, 16, ' وسمعت صوت إنسان بين أولاي ، فنادى وقال : يا جبرائيل ، فهم هذا الرجل الرؤيا '),
(9249, 'Daniel', 27, 8, 17, ' فجاء إلى حيث وقفت ، ولما جاء خفت وخررت على وجهي . فقال لي : افهم يا ابن آدم . إن الرؤيا لوقت المنتهى '),
(9250, 'Daniel', 27, 8, 18, ' وإذ كان يتكلم معي كنت مسبخا على وجهي إلى الأرض ، فلمسني وأوقفني على مقامي '),
(9251, 'Daniel', 27, 8, 19, ' وقال : هأنذا أعرفك ما يكون في آخر السخط . لأن لميعاد الانتهاء '),
(9252, 'Daniel', 27, 8, 20, ' أما الكبش الذي رأيته ذا القرنين فهو ملوك مادي وفارس '),
(9253, 'Daniel', 27, 8, 21, ' والتيس العافي ملك اليونان ، والقرن العظيم الذي بين عينيه هو الملك الأول '),
(9254, 'Daniel', 27, 8, 22, ' وإذ انكسر وقام أربعة عوضا عنه ، فستقوم أربع ممالك من الأمة ، ولكن ليس في قوته '),
(9255, 'Daniel', 27, 8, 23, ' وفي آخر مملكتهم عند تمام المعاصي يقوم ملك جافي الوجه وفاهم الحيل '),
(9256, 'Daniel', 27, 8, 24, ' وتعظم قوته ، ولكن ليس بقوته . يهلك عجبا وينجح ويفعل ويبيد العظماء وشعب القديسين '),
(9257, 'Daniel', 27, 8, 25, ' وبحذاقته ينجح أيضا المكر في يده ، ويتعظم بقلبه . وفي الاطمئنان يهلك كثيرين ، ويقوم على رئيس الرؤساء ، وبلا يد ينكسر '),
(9258, 'Daniel', 27, 8, 26, ' فرؤيا المساء والصباح التي قيلت هي حق . أما أنت فاكتم الرؤيا لأنها إلى أيام كثيرة '),
(9259, 'Daniel', 27, 8, 27, ' وأنا دانيآل ضعفت ونحلت أياما ، ثم قمت وباشرت أعمال الملك ، وكنت متحيرا من الرؤيا ولا فاهم '),
(9260, 'Daniel', 27, 9, 1, ' في السنة الأولى لداريوس بن أحشويروش من نسل الماديين الذي ملك على مملكة الكلدانيين '),
(9261, 'Daniel', 27, 9, 2, ' في السنة الأولى من ملكه ، أنا دانيآل فهمت من الكتب عدد السنين التي كانت عنها كلمة الرب إلى إرميا النبي ، لكمالة سبعين سنة على خراب أورشليم '),
(9262, 'Daniel', 27, 9, 3, ' فوجهت وجهي إلى الله السيد طالبا بالصلاة والتضرعات ، بالصوم والمسح والرماد '),
(9263, 'Daniel', 27, 9, 4, ' وصليت إلى الرب إلهي واعترفت وقلت : أيها الرب الإله العظيم المهوب ، حافظ العهد والرحمة لمحبيه وحافظي وصاياه '),
(9264, 'Daniel', 27, 9, 5, ' أخطأنا وأثمنا وعملنا الشر ، وتمردنا وحدنا عن وصاياك وعن أحكامك '),
(9265, 'Daniel', 27, 9, 6, ' وما سمعنا من عبيدك الأنبياء الذين باسمك كلموا ملوكنا ورؤساءنا وآباءنا وكل شعب الأرض '),
(9266, 'Daniel', 27, 9, 7, ' لك يا سيد البر ، أما لنا فخزي الوجوه ، كما هو اليوم لرجال يهوذا ولسكان أورشليم ، ولكل إسرائيل القريبين والبعيدين في كل الأراضي التي طردتهم إليها ، من أجل خيانتهم التي خانوك إياها '),
(9267, 'Daniel', 27, 9, 8, ' ياسيد ، لنا خزي الوجوه ، لملوكنا ، لرؤسائنا ولآبائنا لأننا أخطأنا إليك '),
(9268, 'Daniel', 27, 9, 9, ' للرب إلهنا المراحم والمغفرة ، لأننا تمردنا عليه '),
(9269, 'Daniel', 27, 9, 10, ' وما سمعنا صوت الرب إلهنا لنسلك في شرائعه التي جعلها أمامنا عن يد عبيده الأنبياء '),
(9270, 'Daniel', 27, 9, 11, ' وكل إسرائيل قد تعدى على شريعتك ، وحادوا لئلا يسمعوا صوتك ، فسكبت علينا اللعنة والحلف المكتوب في شريعة موسى عبد الله ، لأننا أخطأنا إليه '),
(9271, 'Daniel', 27, 9, 12, ' وقد أقام كلماته التي تكلم بها علينا وعلى قضاتنا الذين قضوا لنا ، ليجلب علينا شرا عظيما ، ما لم يجر تحت السماوات كلها كما أجري على أورشليم '),
(9272, 'Daniel', 27, 9, 13, ' كما كتب في شريعة موسى ، قد جاء علينا كل هذا الشر ، ولم نتضرع إلى وجه الرب إلهنا لنرجع من آثامنا ونفطن بحقك '),
(9273, 'Daniel', 27, 11, 41, ' ويدخل إلى الأرض البهية فيعثر كثيرون ، وهؤلاء يفلتون من يده : أدوم وموآب ورؤساء بني عمون '),
(9274, 'Daniel', 27, 11, 42, ' ويمد يده على الأراضي ، وأرض مصر لا تنجو '),
(9275, 'Daniel', 27, 11, 43, ' ويتسلط على كنوز الذهب والفضة وعلى كل نفائس مصر . واللوبيون والكوشيون عند خطواته '),
(9276, 'Daniel', 27, 11, 44, ' وتفزعه أخبار من الشرق ومن الشمال ، فيخرج بغضب عظيم ليخرب وليحرم كثيرين '),
(9277, 'Daniel', 27, 11, 45, ' وينصب فسطاطه بين البحور وجبل بهاء القدس ، ويبلغ نهايته ولا معين له '),
(9278, 'Daniel', 27, 12, 1, ' وفي ذلك الوقت يقوم ميخائيل الرئيس العظيم القائم لبني شعبك ، ويكون زمان ضيق لم يكن منذ كانت أمة إلى ذلك الوقت . وفي ذلك الوقت ينجى شعبك ، كل من يوجد مكتوبا في السفر '),
(9279, 'Daniel', 27, 12, 2, ' وكثيرون من الراقدين في تراب الأرض يستيقظون ، هؤلاء إلى الحياة الأبدية ، وهؤلاء إلى العار للازدراء الأبدي '),
(9280, 'Daniel', 27, 12, 3, ' والفاهمون يضيئون كضياء الجلد ، والذين ردوا كثيرين إلى البر كالكواكب إلى أبد الدهور '),
(9281, 'Daniel', 27, 12, 4, ' أما أنت يا دانيآل فأخف الكلام واختم السفر إلى وقت النهاية . كثيرون يتصفحونه والمعرفة تزداد '),
(9282, 'Daniel', 27, 12, 5, ' فنظرت أنا دانيآل وإذا باثنين آخرين قد وقفا واحد من هنا على شاطئ النهر ، وآخر من هناك على شاطئ النهر '),
(9283, 'Daniel', 27, 12, 6, ' وقال للرجل اللابس الكتان الذي من فوق مياه النهر : إلى متى انتهاء العجائب '),
(9284, 'Daniel', 27, 12, 7, ' فسمعت الرجل اللابس الكتان الذي من فوق مياه النهر ، إذ رفع يمناه ويسراه نحو السماوات وحلف بالحي إلى الأبد : إنه إلى زمان وزمانين ونصف . فإذا تم تفريق أيدي الشعب المقدس تتم كل هذه '),
(9285, 'Daniel', 27, 12, 8, ' وأنا سمعت وما فهمت . فقلت : يا سيدي ، ما هي آخر هذه '),
(9286, 'Daniel', 27, 12, 9, ' فقال : اذهب يا دانيآل لأن الكلمات مخفية ومختومة إلى وقت النهاية '),
(9287, 'Daniel', 27, 12, 10, ' كثيرون يتطهرون ويبيضون ويمحصون ، أما الأشرار فيفعلون شرا . ولا يفهم أحد الأشرار ، لكن الفاهمون يفهمون '),
(9288, 'Daniel', 27, 12, 11, ' ومن وقت إزالة المحرقة الدائمة وإقامة رجس المخرب ألف ومئتان وتسعون يوما '),
(9289, 'Daniel', 27, 12, 12, ' طوبى لمن ينتظر ويبلغ إلى الألف والثلاث مئة والخمسة والثلاثين يوما '),
(9290, 'Daniel', 27, 12, 13, ' أما أنت فاذهب إلى النهاية فتستريح ، وتقوم لقرعتك في نهاية الأيام '),
(9291, 'Daniel', 27, 3, 1, 'وان نبوخذنصر الملك صنع تمثالا من ذهب طوله ستون ذراعا وعرضه ست اذرع ونصبه في بقعة دورا في ولاية بابل'),
(9292, 'Daniel', 27, 3, 2, 'ثم ارسل نبوخذنصر الملك ليجمع المرازبة والشحن والولاة والقضاة والخزنة والفقهاء والمفتين وكل حكام الولايات لياتوا لتدشين التمثال الذي نصبه نبوخذنصر الملك'),
(9293, 'Daniel', 27, 3, 3, 'حينئذ اجتمع المرازبة والشحن والولاة والقضاة والخزنة والفقهاء والمفتون وكل حكام الولايات لتدشين التمثال الذي نصبه نبوخذنصر الملك ووقفوا امام التمثال الذي نصبه نبوخذنصر'),
(9294, 'Daniel', 27, 3, 4, 'و نادى مناد بشدة قد امرتم ايها الشعوب والامم والالسنة'),
(9295, 'Daniel', 27, 3, 5, 'عندما تسمعون صوت القرن والناي والعود والرباب والسنطير والمزمار وكل انواع العزف ان تخروا وتسجدوا لتمثال الذهب الذي نصبه نبوخذنصر الملك'),
(9296, 'Daniel', 27, 3, 6, 'و من لا يخر ويسجد ففي تلك الساعة يلقى في وسط اتون نار متقدة'),
(9297, 'Daniel', 27, 3, 7, 'لاجل ذلك وقتما سمع كل الشعوب صوت القرن والناي والعود والرباب والسنطير وكل انواع العزف خر كل الشعوب والامم والالسنة وسجدوا لتمثال الذهب الذي نصبه نبوخذنصر الملك'),
(9298, 'Daniel', 27, 3, 8, 'لاجل ذلك تقدم حينئذ رجال كلدانيون واشتكوا على اليهود'),
(9299, 'Daniel', 27, 3, 9, 'اجابوا وقالوا للملك نبوخذنصر ايها الملك عش الى الابد'),
(9300, 'Daniel', 27, 3, 10, 'انت ايها الملك قد اصدرت امرا بان كل انسان يسمع صوت القرن والناي والعود والرباب والسنطير والمزمار وكل انواع العزف يخر ويسجد لتمثال الذهب'),
(9301, 'Daniel', 27, 3, 11, 'و من لا يخر ويسجد فانه يلقى في وسط اتون نار متقدة'),
(9302, 'Daniel', 27, 3, 12, 'يوجد رجال يهود الذين وكلتهم على اعمال ولاية بابل شدرخ ومشيخ وعبد نغو هؤلاء الرجال لم يجعلوا لك ايها الملك اعتبارا الهتك لا يعبدون ولتمثال الذهب الذي نصبت لا يسجدون'),
(9303, 'Daniel', 27, 3, 13, 'حينئذ امر نبوخذنصر بغضب وغيظ باحضار شدرخ وميشخ وعبد نغو فاتوا بهؤلاء الرجال قدام الملك'),
(9304, 'Daniel', 27, 3, 14, 'فاجاب نبوخذنصر وقال لهم تعمدا يا شدرخ وميشخ وعبد نغو لا تعبدون الهتي ولا تسجدون لتمثال الذهب الذي نصبت'),
(9305, 'Daniel', 27, 3, 15, 'فان كنتم الان مستعدين عندما تسمعون صوت القرن والناي والعود والرباب والسنطير والمزمار وكل انواع العزف الى ان تخروا وتسجدوا للتمثال الذي عملته وان لم تسجدوا ففي تلك الساعة تلقون في وسط اتون النار المتقدة ومن هو الاله الذي ينقذكم من يدي'),
(9306, 'Daniel', 27, 3, 16, 'فاجاب شدرخ وميشخ وعبد نغو وقالوا للملك يا نبوخذنصر لا يلزمنا ان نجيبك عن هذا الامر'),
(9307, 'Daniel', 27, 3, 17, 'هوذا يوجد الهنا الذي نعبده يستطيع ان ينجينا من اتون النار المتقدة وان ينقذنا من يدك ايها الملك'),
(9308, 'Daniel', 27, 3, 18, 'و الا فليكن معلوما لك ايها الملك اننا لا نعبد الهتك ولا نسجد لتمثال الذهب الذي نصبته'),
(9309, 'Daniel', 27, 3, 19, 'حينئذ امتلا نبوخذنصر غيظا وتغير منظر وجهه على شدرخ وميشخ وعبد نغو فاجاب وامر بان يحموا الاتون سبعة اضعاف اكثر مما كان معتادا ان يحمى'),
(9310, 'Daniel', 27, 3, 20, 'و امر جبابرة القوة في جيشه بان يوثقوا شدرخ وميشخ وعبد نغو ويلقوهم في اتون النار المتقدة'),
(9311, 'Daniel', 27, 3, 21, 'ثم اوثق هؤلاء الرجال في سراويلهم واقمصتهم وارديتهم ولباسهم والقوا في وسط اتون النار المتقدة'),
(9312, 'Daniel', 27, 3, 22, 'و من حيث ان كلمة الملك شديدة والاتون قد حمي جدا قتل لهيب النار الرجال الذين رفعوا شدرخ وميشخ وعبد نغو'),
(9313, 'Daniel', 27, 3, 23, 'و هؤلاء الثلاثة الرجال شدرخ وميشخ وعبد نغو سقطوا موثقين في وسط اتون النار المتقدة'),
(9314, 'Daniel', 27, 3, 24, 'فكانوا يتمشون في وسط اللهيب مسبحين الله ومباركين الرب'),
(9315, 'Daniel', 27, 3, 25, 'و وقف عزريا وصلى هكذا وفتح فاه في وسط النار وقال'),
(9316, 'Daniel', 27, 3, 26, 'مبارك انت ايها الرب اله ابائنا وحميد واسمك ممجد الى الدهور'),
(9317, 'Daniel', 27, 3, 27, 'لانك عادل في جميع ما صنعت واعمالك كلها صدق وطرقك استقامة وجميع احكامك حق'),
(9318, 'Daniel', 27, 3, 28, 'و قد اجريت احكام حق في جميع ما جلبت علينا وعلى مدينة ابائنا المقدسة اورشليم لانك بالحق والحكم جلبت جميع ذلك لاجل خطايانا'),
(9319, 'Daniel', 27, 3, 29, 'اذ قد خطئنا واثمنا مرتدين عنك واجرمنا في كل شيء'),
(9320, 'Daniel', 27, 3, 30, 'و لم نسمع لوصاياك ولم نحفظها ولم نعمل بما اوصيتنا لكي يكون لنا خير'),
(9321, 'Daniel', 27, 3, 31, 'فجميع ما جلبت علينا وجميع ما صنعت بنا انما صنعته بحكم حق'),
(9322, 'Daniel', 27, 3, 32, 'فاسلمتنا الى ايدي اعداء اثمة وكفرة ذوي بغضاء وملك ظالم شر من كل من على الارض'),
(9323, 'Daniel', 27, 3, 33, 'و الان ليس لنا ان نفتح افواهنا فقد صرنا خزيا وعارا لعبيدك والقانتين لك'),
(9324, 'Daniel', 27, 3, 34, 'فلا تخذلنا الى الانقضاء لاجل اسمك ولا تنقض عهدك'),
(9325, 'Daniel', 27, 3, 35, 'و لا تصرف رحمتك عنا لاجل ابراهيم خليلك واسحق عبدك واسرائيل قديسك'),
(9326, 'Daniel', 27, 3, 36, 'الذين قلت لهم انك تكثر نسلهم كنجوم السماء وكالرمل الذي على شاطئ البحر'),
(9327, 'Daniel', 27, 3, 37, 'لقد جعلنا ايها الرب اقل عددا من كل امة ونحن اليوم اذلاء في كل الارض لاجل خطايانا'),
(9328, 'Daniel', 27, 3, 38, 'و ليس لنا في هذا الزمان رئيس ولا نبي ولا قائد ولا محرقة ولا ذبيحة ولا تقدمة ولا بخور ولا موضع لتقريب البواكير امامك'),
(9329, 'Daniel', 27, 3, 39, 'و لنيل رحمتك ولكن لانسحاق نفوسنا وتواضع ارواحنا اقبلنا'),
(9330, 'Daniel', 27, 3, 40, 'و كمحرقات الكباش والثيران وربوات الحملان السمان هكذا فلتكن ذبيحتنا امامك اليوم حتى ترضيك فانه لا خزي للمتوكلين عليك'),
(9331, 'Daniel', 27, 3, 41, 'انا نتبعك الان بكل قلوبنا ونتقيك ونبتغي وجهك'),
(9332, 'Daniel', 27, 3, 42, 'فلا تخزنا بل عاملنا بحسب رافتك وكثرة رحمتك'),
(9333, 'Daniel', 27, 3, 43, 'و انقذنا على حسب عجائبك واعط المجد لاسمك ايها الرب'),
(9334, 'Daniel', 27, 3, 44, 'و ليخجل جميع الذين اروا عبيدك المساوئ وليخزوا ساقطين عن كل اقتدارهم ولتحطم قوتهم'),
(9335, 'Daniel', 27, 3, 45, 'و ليعلموا انك انت الرب الاله وحدك المجيد في كل المسكونة'),
(9336, 'Daniel', 27, 3, 46, 'و لم يزل خدام الملك الذين القوهم يوقدون الاتون بالنفط والزفت والمشاقة والزرجون'),
(9337, 'Daniel', 27, 3, 47, 'فارتفع اللهيب فوق الاتون تسعا واربعين ذراعا'),
(9338, 'Daniel', 27, 3, 48, 'و انتشر واحرق الذين صادفهم حول الاتون من الكلدانيين'),
(9339, 'Daniel', 27, 3, 49, 'اما اصحاب عزريا فنزل ملاك الرب الى داخل الاتون وطرد لهيب النار عن الاتون'),
(9340, 'Daniel', 27, 3, 50, 'و جعل وسط الاتون ريحا ذات ندى تهب فلم تمسهم النار البتة ولم تسؤهم ولم تزعجهم'),
(9341, 'Daniel', 27, 3, 51, 'حينئذ سبح الثلاثة بفم واحد ومجدوا وباركوا الله في الاتون قائلين'),
(9342, 'Daniel', 27, 3, 52, 'مبارك انت ايها الرب اله ابائنا وحميد ورفيع الى الدهور ومبارك اسم مجدك القدوس ورفيع الى الدهور'),
(9343, 'Daniel', 27, 3, 53, 'مبارك انت في هيكل مجدك القدوس ومسبح وممجد الى الدهور'),
(9344, 'Daniel', 27, 3, 54, 'مبارك انت في عرش ملكك ومسبح ورفيع الى الدهور'),
(9345, 'Daniel', 27, 3, 55, 'مبارك انت ايها الناظر الاعماق الجالس على الكروبين ومسبح ورفيع الى الدهور'),
(9346, 'Daniel', 27, 3, 56, 'مبارك انت في جلد السماء ومسبح وممجد الى الدهور'),
(9347, 'Daniel', 27, 3, 57, 'باركي الرب يا جميع اعمال الرب سبحي وارفعيه الى الدهور'),
(9348, 'Daniel', 27, 3, 58, 'باركوا الرب يا ملائكة الرب سبحوا وارفعوه الى الدهور'),
(9349, 'Daniel', 27, 3, 59, 'باركي الرب ايتها السماوات سبحي وارفعيه الى الدهور'),
(9350, 'Daniel', 27, 3, 60, 'باركي الرب يا جميع المياه التي فوق السماء سبحي وارفعيه الى الدهور'),
(9351, 'Daniel', 27, 3, 61, 'باركي الرب يا جميع جنود الرب سبحي وارفعيه الى الدهور'),
(9352, 'Daniel', 27, 3, 62, 'باركا الرب ايها الشمس والقمر سبحا وارفعاه الى الدهور'),
(9353, 'Daniel', 27, 3, 63, 'باركي الرب يا نجوم السماء سبحي وارفعيه الى الدهور'),
(9354, 'Daniel', 27, 3, 64, 'باركي الرب يا جميع الامطار والانداء سبحي وارفعيه الى الدهور'),
(9355, 'Daniel', 27, 3, 65, 'باركي الرب يا جميع الرياح سبحي وارفعيه الى الدهور'),
(9356, 'Daniel', 27, 3, 66, 'باركا الرب ايها النار والحر سبحا وارفعاه الى الدهور'),
(9357, 'Daniel', 27, 3, 67, 'باركا الرب ايها البرد والحر سبحا وارفعاه الى الدهور'),
(9358, 'Daniel', 27, 3, 68, 'باركا الرب ايها الندى والجليد سبحا وارفعاه الى الدهور'),
(9359, 'Daniel', 27, 3, 69, 'باركا الرب ايها الجمد والبرد سبحا وارفعاه الى الدهور'),
(9360, 'Daniel', 27, 3, 70, 'باركا الرب ايها الصقيع والثلج سبحا وارفعاه الى الدهور'),
(9361, 'Daniel', 27, 3, 71, 'باركا الرب ايها الليل والنهار سبحا وارفعاه الى الدهور'),
(9362, 'Daniel', 27, 3, 72, 'باركا الرب ايها النور والظلمة سبحا وارفعاه الى الدهور'),
(9363, 'Daniel', 27, 3, 73, 'باركي الرب ايتها البروق والسحب سبحي وارفعيه الى الدهور'),
(9364, 'Daniel', 27, 3, 74, 'لتبارك الارض الرب لتسبح وترفعه الى الدهور'),
(9365, 'Daniel', 27, 3, 75, 'باركي الرب ايتها الجبال والتلال سبحي وارفعيه الى الدهور'),
(9366, 'Daniel', 27, 3, 76, 'باركي الرب يا جميع انبتة الارض سبحي وارفعيه الى الدهور'),
(9367, 'Daniel', 27, 3, 77, 'باركي الرب ايتها الينابيع سبحي وارفعيه الى الدهور'),
(9368, 'Daniel', 27, 3, 78, 'باركي الرب ايتها البحار والانهار سبحي وارفعيه الى الدهور'),
(9369, 'Daniel', 27, 3, 79, 'باركي الرب ايتها الحيتان وجميع ما يتحرك في المياه سبحي وارفعيه الى الدهور'),
(9370, 'Daniel', 27, 3, 80, 'باركي الرب يا جميع طيور السماء سبحي وارفعيه الى الدهور'),
(9371, 'Daniel', 27, 3, 81, 'باركي الرب يا جميع الوحوش والبهائم سبحي وارفعيه الى الدهور'),
(9372, 'Daniel', 27, 3, 82, 'باركوا الرب يا بني البشر سبحوا وارفعوه الى الدهور'),
(9373, 'Daniel', 27, 3, 83, 'باركوا الرب يا اسرائيل سبحوا وارفعوه الى الدهور'),
(9374, 'Daniel', 27, 3, 84, 'باركوا الرب يا كهنة الرب سبحوا وارفعوه الى الدهور'),
(9375, 'Daniel', 27, 3, 85, 'باركوا الرب يا عبيد الرب سبحوا وارفعوه الى الدهور'),
(9376, 'Daniel', 27, 3, 86, 'باركوا الرب يا ارواح ونفوس الصديقين سبحوا وارفعوه الى الدهور'),
(9377, 'Daniel', 27, 3, 87, 'باركوا الرب ايها القديسون والمتواضعو القلوب سبحوا وارفعوه الى الدهور'),
(9378, 'Daniel', 27, 3, 88, 'باركوا الرب يا حننيا وعزريا وميشائيل سبحوا وارفعوه الى الدهور لانه انقذنا من الجحيم وخلصنا من يد الموت ونجانا من وسط اتون اللهيب المضطرم ومن وسط النار'),
(9379, 'Daniel', 27, 3, 89, 'اعترفوا للرب لانه صالح لان الى الابد رحمته'),
(9380, 'Daniel', 27, 3, 90, 'باركوا يا جميع القانتين الرب اله الالهة سبحوا واعترفوا لان الى الابد رحمته'),
(9381, 'Daniel', 27, 3, 91, 'حينئذ تحير نبوخذنصر الملك وقام مسرعا فاجاب وقال لمشيريه الم نلقي ثلاثة رجال موثقين في وسط النار فاجابوا وقالوا للملك صحيح ايها الملك'),
(9382, 'Daniel', 27, 3, 92, 'اجاب وقال ها انا ناظر اربعة رجال محلولين يتمشون في وسط النار وما بهم ضرر ومنظر الرابع شبيه بابن الالهة'),
(9383, 'Daniel', 27, 3, 93, 'ثم اقترب نبوخذنصر الى باب اتون النار المتقدة واجاب فقال يا شدرخ وميشخ وعبد نغو يا عبيد الله العلي اخرجوا وتعالوا فخرج شدرخ وميشخ وعبد نغو من وسط النار'),
(9384, 'Daniel', 27, 3, 94, 'فاجتمعت المرازبة والشحن والولاة ومشيرو الملك وراوا هؤلاء الرجال الذين لم تكن للنار قوة على اجسامهم وشعرة من رؤوسهم لم تحترق وسراويلهم لم تتغير ورائحة النار لم تات عليهم'),
(9385, 'Daniel', 27, 3, 95, 'فاجاب نبوخذنصر وقال تبارك اله شدرخ وميشخ وعبد نغو الذي ارسل ملاكه وانقذ عبيده الذين اتكلوا عليه وغيروا كلمة الملك واسلموا اجسادهم لكيلا يعبدوا او يسجدوا لاله غير الههم'),
(9386, 'Daniel', 27, 3, 96, 'فمني قد صدر امر بان كل شعب وامة ولسان يتكلمون بالسوء على اله شدرخ وميشخ وعبد نغو فانهم يصيرون اربا اربا وتجعل بيوتهم مزبلة اذ ليس اله اخر يستطيع ان ينجي هكذا'),
(9387, 'Daniel', 27, 3, 97, 'حينئذ قدم الملك شدرخ وميشخ وعبد نغو في ولاية بابل'),
(9388, 'Daniel', 27, 13, 1, 'و كان في بابل رجل اسمه يوياقيم'),
(9389, 'Daniel', 27, 13, 2, 'و كان متزوجا امراة اسمها سوسنة ابنة حلقيا جميلة جدا ومتقية للرب'),
(9390, 'Daniel', 27, 13, 3, 'و كان ابواها صديقين فادبا ابنتهما على حسب شريعة موسى'),
(9391, 'Daniel', 27, 13, 4, 'و كان يواقيم غنيا جدا وكانت له حديقة تلي داره وكان اليهود يجتمعون اليه لانه كان اوجههم جميعا'),
(9392, 'Daniel', 27, 13, 5, 'و كان قد اقيم شيخان من الشعب للقضاء في تلك السنة وهما من الذين قال الرب فيهم ان الاثم قد صدر من بابل من شيوخ قضاة يحسبون مدبري الشعب'),
(9393, 'Daniel', 27, 13, 6, 'و كانا يترددان الى دار يوياقيم فياتيهما كل ذي دعوى'),
(9394, 'Daniel', 27, 13, 7, 'و كانت سوسنة متى انصرف الشعب عند الظهر تدخل وتتمشى في حديقة رجلها'),
(9395, 'Daniel', 27, 13, 8, 'فكان الشيخان يريانها كل يوم تدخل وتتمشى فكلفا بهواها'),
(9396, 'Daniel', 27, 13, 9, 'و اسلما عقولهما الى الفساد وصرفا اعينهما لئلا ينظرا الى السماء فيذكرا الاحكام العادلة'),
(9397, 'Daniel', 27, 13, 10, 'و كانا كلاهما مشغوفين بها ولم يكاشف احدهما الاخر بوجده'),
(9398, 'Daniel', 27, 13, 11, 'حياء من كشف هواهما ورغبة في مضاجعتها'),
(9399, 'Daniel', 27, 13, 12, 'و كانا كل يوم يجدان في الترقب لكي ينظراها'),
(9400, 'Daniel', 27, 13, 13, 'و ان احدهما قال للاخر لنتصرف الى بيوتنا فانها ساعة الغذاء فخرجا وتفارقا'),
(9401, 'Daniel', 27, 13, 14, 'ثم انقلبا ورجعا الى الموضع فسال بعضهما بعضا عن سبب رجوعه فاعترفا بهواهما وحينئذ اتفقا معا على وقت يمكنهما فيهان يخلوا بها'),
(9402, 'Daniel', 27, 13, 15, 'و كان في بعض الايام بينما هما مترقبان اليوم الموافق انها دخلت مثل امس فما قبل ومعها جاريتان فقط وارادت ان تغتسل في الحديقة لانه كان حر'),
(9403, 'Daniel', 27, 13, 16, 'و لم يكن هناك احد الا الشيخان وهما مختبئان يترقبانها'),
(9404, 'Daniel', 27, 13, 17, 'فقالت للجاريتين ائتياني بدهن وغسول واغلقا ابواب الحديقة لاغتسل'),
(9405, 'Daniel', 27, 13, 18, 'ففعلتا كما امرتهما اغلقتا ابواب الحديقة وخرجتا من ابواب السر لتاتيا بما امرتا به ولم تعلما ان الشيخين مختبئان هناك'),
(9406, 'Daniel', 27, 13, 19, 'فلما خرجت الجاريتان قام الشيخان وهجما عليها وقالا'),
(9407, 'Daniel', 27, 13, 20, 'ها ان ابواب الحديقة مغلقة ولا يرانا احد ونحن كلفان بهواك فوافقينا وكوني معنا'),
(9408, 'Daniel', 27, 13, 21, 'و الا فنشهد عليك انه كان معك شاب ولذلك صرفت الجاريتين عنك'),
(9409, 'Daniel', 27, 13, 22, 'فتنهدت سوسنة وقالت لقد ضاق بي الامر من كل جهة فاني ان فعلت هذا فهو لي موت وان لم افعل فلا انجو من ايديكما'),
(9410, 'Daniel', 27, 13, 23, 'و لكن خير لي ان لا افعل ثم اقع في ايديكما من ان اخطا امام الرب'),
(9411, 'Daniel', 27, 13, 24, 'و صرخت سوسنة بصوت عظيم فصرخ الشيخان عليها'),
(9412, 'Daniel', 27, 13, 25, 'و اسرع احدهما وفتح ابواب الحديقة'),
(9413, 'Daniel', 27, 13, 26, 'فلما سمع اهل البيت الصراخ في الحديقة وثبوا اليها من باب السر ليروا ما وقع لها'),
(9414, 'Daniel', 27, 13, 27, 'و لما تكلم الشيخان بكلامهما خجل العبيد جدا لانه لم يقل قط هذا القول على سوسنة'),
(9415, 'Daniel', 27, 13, 28, 'و في الغد لما اجتمع الشعب الى رجلها يوياقيم اتى الشيخان مضمرين نية اثيمة على سوسنة ليهلكاها'),
(9416, 'Daniel', 27, 13, 29, 'و قالا امام الشعب ارسلوا الى سوسنة بنة حلقيا التي هي امراة يوياقيم فارسلوا'),
(9417, 'Daniel', 27, 13, 30, 'فاتت هي ووالداها وبنوها وجميع ذوي قرابتها'),
(9418, 'Daniel', 27, 13, 31, 'و كانت سوسنة ترفة جدا وجميلة المنظر'),
(9419, 'Daniel', 27, 13, 32, 'فامر هذان الفاجران ان يكشف وجهها وكانت مبرقعة ليشبعا من جمالها'),
(9420, 'Daniel', 27, 13, 33, 'و كان اهلها وجميع الذين يعرفونها يبكون'),
(9421, 'Daniel', 27, 13, 34, 'فقام الشيخان في وسط الشعب ووضعا ايديهما على راسها'),
(9422, 'Daniel', 27, 13, 35, 'فرفعت طرفها الى السماء وهي باكية لان قلبها كان متوكلا على الرب'),
(9423, 'Daniel', 27, 13, 36, 'فقال الشيخان اننا كنا نتمشى في الحديقة وحدنا فاذا بهذه قد دخلت ومعها جاريتان واغلقت ابواب الحديقة ثم صرفت الجاريتين'),
(9424, 'Daniel', 27, 13, 37, 'فاتاها شاب كان مختبئا ووقع عليها'),
(9425, 'Daniel', 27, 13, 38, 'و كنا نحن في زاوية من الحديقة فلما راينا الاثم اسرعنا اليهما ورايناهما متعانقين'),
(9426, 'Daniel', 27, 13, 39, 'اما ذاك فلم نستطيع ان نمسكه لانه كان اقوى منا ففتح الابواب وفر'),
(9427, 'Daniel', 27, 13, 40, 'و اما هذه فقبضنا عليها وسالناها من الشاب فابت ان تخبرنا هذا ما نشهد به'),
(9428, 'Daniel', 27, 13, 41, 'فصدقهما المجمع لانهما شيخان وقاضيان في الشعب وحكموا عليها بالموت'),
(9429, 'Daniel', 27, 13, 42, 'فصرخت سوسنة بصوت عظيم وقالت ايها الاله الازلي البصير بالخفايا العالم بكل شيء قبل ان يكون'),
(9430, 'Daniel', 27, 13, 43, 'انك تعلم انهما شهدا علي بالزور وها انا اموت ولم اصنع شيئا مما افترى علي هذان'),
(9431, 'Daniel', 27, 13, 44, 'فاستجاب الرب لصوتها'),
(9432, 'Daniel', 27, 13, 45, 'و اذ كانت تساق الى الموت نبه الله روحا مقدسا لشاب حدث اسمه دانيال'),
(9433, 'Daniel', 27, 13, 46, 'فصرخ بصوت عظيم انا بريء من دم هذه'),
(9434, 'Daniel', 27, 13, 47, 'فالتفت اليه الشعب كله وقالوا ما هذا الكلام الذي قلته'),
(9435, 'Daniel', 27, 13, 48, 'فوقف في وسطهم وقال اهكذا انتم اغبياء يا بني اسرائيل حتى تقضوا على بنت اسرائيل بغير ان تفحصوا وتتحققوا الامر'),
(9436, 'Daniel', 27, 13, 49, 'ارجعوا الى القضاء فان هذين انما شهدا عليها بالزور'),
(9437, 'Daniel', 27, 13, 50, 'فاسرع الشعب كله ورجع فقال له الشيخان هلم اجلس بيننا وافدنا فقد اتاك الله مزية الشيوخ'),
(9438, 'Daniel', 27, 13, 51, 'فقال لهم دانيال فرقوهما بعضهما عن بعض فاحكم فيهما'),
(9439, 'Daniel', 27, 13, 52, 'فلما فرقا الواحد عن الاخر دعا احدهما وقال له يا ايها المتعتق الايام الشريرة لقد اتت عليك خطاياك التي ارتكبت من قبل'),
(9440, 'Daniel', 27, 13, 53, 'بقضائك اقضية ظلم وحكمك على الابرياء واطلاقكك للمجرمين وقد قال الله البريء والزكي لا تقتلهما'),
(9441, 'Daniel', 27, 13, 54, 'فالان ان كنت قد رايتها فقل تحت اي شجرة رايتهما يتحدثان فقال تحت الضروة'),
(9442, 'Daniel', 27, 13, 55, 'فقال دانيال لقد صوبت كذبك على راسك فملاك الله قد امر من لدن الله بان يشقك شطرين'),
(9443, 'Daniel', 27, 13, 56, 'ثم نحاه وامر باقبال الاخر فقال له يا نسل كنعان لا يهوذا قد فتنك الجمال واسلم الهوى قلبك الى الفساد'),
(9444, 'Daniel', 27, 13, 57, 'هكذا كنتما تصنعان مع بنات اسرائيل وكن يحدثنكما مخافة منكما اما بنت يهوذا فلم تحتمل فجوركما'),
(9445, 'Daniel', 27, 13, 58, 'فالان قل لي تحت اية شجرة صادفتهما يتحدثان فقال تحت السنديانة'),
(9446, 'Daniel', 27, 13, 59, 'فقال له دانيال وانت ايضا قد صوبت كذبك على راسك فملاك الله واقف وبيده سيف ليقطعك شطرين حتى يهلككما'),
(9447, 'Daniel', 27, 13, 60, 'فصرخ المجمع كله بصوت عظيم وباركوا الله مخلص الذين يرجونه'),
(9448, 'Daniel', 27, 13, 61, 'و قاموا على الشيخين وقد اثبت دانيال من نطقهما انهما شهدا بالزور وصنعوا بهما كما نويا ان يصنعا بالقريب'),
(9449, 'Daniel', 27, 13, 62, 'عملا بما في شريعة موسى فقتلوهما وخلص الدم الزكي في ذلك اليوم'),
(9450, 'Daniel', 27, 13, 63, 'فسبح حلقيا وامراته لاجل ابنتهما مع يوياقيم رجلها وذوي قرابتهم لانه لم يوجد فيها شيء قبيح'),
(9451, 'Daniel', 27, 13, 64, 'و عظم دانيال عند الشعب من ذلك اليوم فما بعد'),
(9452, 'Daniel', 27, 13, 65, 'و انضم الملك اسطواج الى ابائه واخذ كورش الفارسي ملكه'),
(9453, 'Daniel', 27, 14, 1, 'و كان دانيال نديما للملك ومكرما فوق جميع اصدقائه'),
(9454, 'Daniel', 27, 14, 2, 'و كان لاهل بابل صنم اسمه بال وكانوا ينفقون له كل يوم اثني عشر اردبا من السميذ واربعين شاة وستة امتار من الخمر'),
(9455, 'Daniel', 27, 14, 3, 'و كان الملك يعبده وينطلق كل يوم فيسجد له اما دانيال فكان يسجد لالهه فقال الملك لماذا لا تسجد لبال'),
(9456, 'Daniel', 27, 14, 4, 'فقال لاني لا اعبد اصناما صنعة الايدي بل الاله الحي خالق السماوات والارض الذي له السلطان على كل ذي جسد'),
(9457, 'Daniel', 27, 14, 5, 'فقال له الملك اتحسب ان بالا ليس باله حي او لا ترى كم ياكل ويشرب كل يوم'),
(9458, 'Daniel', 27, 14, 6, 'فضحك دانيال وقال لا تضل ايها الملك فان هذا باطنه طين وظاهره نحاس فلم ياكل قط'),
(9459, 'Daniel', 27, 14, 7, 'فغضب الملك ودعا كهنته وقال لهم ان لم تقولوا لي من الذي ياكل هذه النفقة تموتون'),
(9460, 'Daniel', 27, 14, 8, 'و ان بينتم ان بالا ياكل هذه يموت دانيال لانه جدف على بال فقال دانيال للملك ليفعل كما تقول'),
(9461, 'Daniel', 27, 14, 9, 'و كان كهنة بال سبعين كاهنا ما خلا النساء والاولاد فاتى الملك ودانيال الى بيت بال'),
(9462, 'Daniel', 27, 14, 10, 'فقال كهنة بال ها انا ننصرف الى الخارج وانت ايها الملك ضع الاطعمة وامزج الخمر وضعها ثم اغلق الباب واختم عليه بخاتمك'),
(9463, 'Daniel', 27, 14, 11, 'و في غد ارجع فان لم تجد بالا قد اكل الجميع فانا نموت والا فيموت دانيال الذي افترى علينا'),
(9464, 'Daniel', 27, 14, 12, 'و كانوا يستخفون بالامر لانهم كانوا قد صنعوا تحت المائدة مدخلا خفيا يدخلون منه كل يوم ويلتهمون الجميع'),
(9465, 'Daniel', 27, 14, 13, 'فلما خرجوا وضع الملك الاطعمة لبال فامر دانيال غلمانه فاتوا برماد وذروه في الهيكل كله بحضرة الملك وحده ثم خرجوا واغلقوا الباب وختموا عليه بخاتم الملك وانصرفوا'),
(9466, 'Daniel', 27, 14, 14, 'فلما كان الليل دخل الكهنة كعادتهم هم ونساؤهم واولادهم واكلوا الجميع وشربوا'),
(9467, 'Daniel', 27, 14, 15, 'و بكر الملك في الغد ودانيال معه'),
(9468, 'Daniel', 27, 14, 16, 'فقال اسالمة الخواتيم يا دانيال قال سالمة ايها الملك'),
(9469, 'Daniel', 27, 14, 17, 'و لما فتحت الابواب نظر الملك الى المائدة فهتف بصوت عال عظيم انت يا بال ولا مكر عندك'),
(9470, 'Daniel', 27, 14, 18, 'فضحك دانيال وامسك الملك لئلا يدخل الى داخل وقال انظر البلاط واعرف ما هذه الاثار'),
(9471, 'Daniel', 27, 14, 19, 'فقال الملك اني ارى اثار رجال ونساء واولاد وغضب الملك'),
(9472, 'Daniel', 27, 14, 20, 'حينئذ قبض على الكهنة ونسائهم واولادهم فاروه الابواب الخفية التي يدخلون منها وياكلون ما على المائدة'),
(9473, 'Daniel', 27, 14, 21, 'فقتلهم الملك واسلم بالا الى يد دانيال فحطمه هو وهيكله'),
(9474, 'Daniel', 27, 14, 22, 'و كان في بابل تنين عظيم وكان اهلها يعبدونه'),
(9475, 'Daniel', 27, 14, 23, 'فقال الملك لدانيال اتقول عن هذا ايضا انه نحاس ها انه حي ياكل ويشرب ولا تستطيع ان تقول انه ليس الها حيا فاسجد له'),
(9476, 'Daniel', 27, 14, 24, 'فقال دانيال اني انما اسجد للرب الهي لانه هو الاله الحي'),
(9477, 'Daniel', 27, 14, 25, 'و انت ايها الملك اجعل لي سلطانا فاقتل التنين بلا سيف ولا عصا فقال الملك قد جعلت لك'),
(9478, 'Daniel', 27, 14, 26, 'فاخذ دانيال زفتا وشحما وشعرا وطبخها معا وصنع اقراصا وجعلها في فم التنين فاكلها التنين فانشق فقال انظروا معبوداتكم'),
(9479, 'Daniel', 27, 14, 27, 'فلما سمع بذلك اهل بابل غضبوا جدا واجتمعوا على الملك وقالوا ان الملك قد صار يهوديا فحطم بالا وقتل التنين وذبح الكهنة'),
(9480, 'Daniel', 27, 14, 28, 'و اتوا الى الملك وقالوا له اسلم الينا دانيال والا قتلناك انت والك'),
(9481, 'Daniel', 27, 14, 29, 'فلما راهم الملك ثائرين به اضطر فاسلم دانيال اليهم'),
(9482, 'Daniel', 27, 14, 30, 'فالقوه في جب الاسود فكان هناك ستة ايام'),
(9483, 'Daniel', 27, 14, 31, 'و كان في الجب سبعة اسود يلقى لها كل يوم جثتان ونعجتان فلم يلق لها حينئذ شيء لكي تفترس دانيال'),
(9484, 'Daniel', 27, 14, 32, 'و كان حبقوق النبي في ارض يهوذا وكان قد طبخ طبيخا وثرد خبزا في جفنة وانطلق الى الصحراء ليحمله للحصادين'),
(9485, 'Daniel', 27, 14, 33, 'فقال ملاك الرب لحبقوق احمل الغداء الذي معك الى بابل الى دانيال في جب الاسود'),
(9486, 'Daniel', 27, 14, 34, 'فقال حبقوق ايها السيد اني لم ار بابل قط ولا اعرف الجب'),
(9487, 'Daniel', 27, 14, 35, 'فاخذ ملاك الرب بجمته وحمله بشعر راسه ووضعه في بابل عند الجب باندفاع روحه'),
(9488, 'Daniel', 27, 14, 36, 'فنادى حبقوق قائلا يا دانيال يا دانيال خذ الغداء الذي ارسله لك الله'),
(9489, 'Daniel', 27, 14, 37, 'فقال دانيال اللهم لقد ذكرتني ولم تخذل الذين يحبونك'),
(9490, 'Daniel', 27, 14, 38, 'و قام دانيال واكل ورد ملاك الرب حبقوق من ساعته الى موضعه'),
(9491, 'Daniel', 27, 14, 39, 'و في اليوم السابع اتى الملك ليبكي على دانيال فدنى من الجب ونظر فاذا بدانيال جالس'),
(9492, 'Daniel', 27, 14, 40, 'فهتف بصوت عال وقال عظيم انت ايها الرب اله دانيال ولا اله غيرك ثم اخرجه من جب الاسود'),
(9493, 'Daniel', 27, 14, 41, 'اما الذين سعوا به للهلاك فالقاهم في الجب فافترسوا من ساعتهم امامه'),
(9494, 'Daniel', 27, 14, 42, 'فقال الملك ليتق جميع سكان الارض اله دانيال فانه المخلص الصانع الايات والعجائب في الارض وهو الذي انقذ دانيال من جب الاسود'),
(9495, 'Deuteronomy', 5, 1, 1, ' هذا هو الكلام الذي كلم به موسى جميع إسرائيل ، في عبر الأردن ، في البرية في العربة ، قبالة سوف ، بين فاران وتوفل ولابان وحضيروت وذي ذهب '),
(9496, 'Deuteronomy', 5, 1, 2, ' أحد عشر يوما من حوريب على طريق جبل سعير إلى قادش برنيع '),
(9497, 'Deuteronomy', 5, 1, 3, ' ففي السنة الأربعين ، في الشهر الحادي عشر في الأول من الشهر ، كلم موسى بني إسرائيل حسب كل ما أوصاه الرب إليهم '),
(9498, 'Deuteronomy', 5, 1, 4, ' بعد ما ضرب سيحون ملك الأموريين الساكن في حشبون ، وعوج ملك باشان الساكن في عشتاروث في إذرعي '),
(9499, 'Deuteronomy', 5, 1, 5, ' في عبر الأردن ، في أرض موآب ، ابتدأ موسى يشرح هذه الشريعة قائلا '),
(9500, 'Deuteronomy', 5, 1, 6, ' الرب إلهنا كلمنا في حوريب قائلا : كفاكم قعود في هذا الجبل '),
(9501, 'Deuteronomy', 5, 1, 7, ' تحولوا وارتحلوا وادخلوا جبل الأموريين وكل ما يليه من العربة والجبل والسهل والجنوب وساحل البحر ، أرض الكنعاني ولبنان إلى النهر الكبير ، نهر الفرات '),
(9502, 'Deuteronomy', 5, 1, 8, ' انظر . قد جعلت أمامكم الأرض . ادخلوا وتملكوا الأرض التي أقسم الرب لآبائكم إبراهيم وإسحاق ويعقوب أن يعطيها لهم ولنسلهم من بعدهم '),
(9503, 'Deuteronomy', 5, 1, 9, ' وكلمتكم في ذلك الوقت قائلا : لا أقدر وحدي أن أحملكم '),
(9504, 'Deuteronomy', 5, 1, 10, ' الرب إلهكم قد كثركم . وهوذا أنتم اليوم كنجوم السماء في الكثرة '),
(9505, 'Deuteronomy', 5, 1, 11, ' الرب إله آبائكم يزيد عليكم مثلكم ألف مرة ، ويبارككم كما كلمكم '),
(9506, 'Deuteronomy', 5, 1, 12, ' كيف أحمل وحدي ثقلكم وحملكم وخصومتكم '),
(9507, 'Deuteronomy', 5, 1, 13, ' هاتوا من أسباطكم رجالا حكماء وعقلاء ومعروفين ، فأجعلهم رؤوسكم '),
(9508, 'Deuteronomy', 5, 1, 14, ' فأجبتموني وقلتم : حسن الأمر الذي تكلمت به أن يعمل '),
(9509, 'Deuteronomy', 5, 1, 15, ' فأخذت رؤوس أسباطكم رجالا حكماء ومعروفين ، وجعلتهم رؤوسا عليكم ، رؤساء ألوف ، ورؤساء مئات ، ورؤساء خماسين ، ورؤساء عشرات ، وعرفاء لأسباطكم '),
(9510, 'Deuteronomy', 5, 1, 16, ' وأمرت قضاتكم في ذلك الوقت قائلا : اسمعوا بين إخوتكم واقضوا بالحق بين الإنسان وأخيه ونزيله '),
(9511, 'Deuteronomy', 5, 1, 17, ' لا تنظروا إلى الوجوه في القضاء . للصغير كالكبير تسمعون . لا تهابوا وجه إنسان لأن القضاء لله . والأمر الذي يعسر عليكم تقدمونه إلي لأسمعه '),
(9512, 'Deuteronomy', 5, 1, 18, ' وأمرتكم في ذلك الوقت بكل الأمور التي تعملونها '),
(9513, 'Deuteronomy', 5, 1, 19, ' ثم ارتحلنا من حوريب ، وسلكنا كل ذلك القفر العظيم المخوف الذي رأيتم في طريق جبل الأموريين ، كما أمرنا الرب إلهنا . وجئنا إلى قادش برنيع '),
(9514, 'Deuteronomy', 5, 1, 20, ' فقلت لكم : قد جئتم إلى جبل الأموريين الذي أعطانا الرب إلهنا '),
(9515, 'Deuteronomy', 5, 1, 21, ' انظر . قد جعل الرب إلهك الأرض أمامك . اصعد تملك كما كلمك الرب إله آبائك . لا تخف ولا ترتعب '),
(9516, 'Deuteronomy', 5, 1, 22, ' فتقدمتم إلي جميعكم وقلتم : دعنا نرسل رجالا قدامنا ليتجسسوا لنا الأرض ، ويردوا إلينا خبرا عن الطريق التي نصعد فيها والمدن التي نأتي إليها '),
(9517, 'Deuteronomy', 5, 1, 23, ' فحسن الكلام لدي ، فأخذت منكم اثني عشر رجلا . رجلا واحدا من كل سبط '),
(9518, 'Deuteronomy', 5, 1, 24, ' فانصرفوا وصعدوا إلى الجبل وأتوا إلى وادي أشكول وتجسسوه '),
(9519, 'Deuteronomy', 5, 1, 25, ' وأخذوا في أيديهم من أثمار الأرض ونزلوا به إلينا ، وردوا لنا خبرا وقالوا : جيدة هي الأرض التي أعطانا الرب إلهنا '),
(9520, 'Deuteronomy', 5, 1, 26, ' لكنكم لم تشاءوا أن تصعدوا ، وعصيتم قول الرب إلهكم '),
(9521, 'Deuteronomy', 5, 1, 27, ' وتمرمرتم في خيامكم وقلتم : الرب بسبب بغضته لنا ، قد أخرجنا من أرض مصر ليدفعنا إلى أيدي الأموريين لكي يهلكنا '),
(9522, 'Deuteronomy', 5, 1, 28, ' إلى أين نحن صاعدون ؟ قد أذاب إخوتنا قلوبنا قائلين : شعب أعظم وأطول منا . مدن عظيمة محصنة إلى السماء ، وأيضا قد رأينا بني عناق هناك '),
(9523, 'Deuteronomy', 5, 1, 29, ' فقلت لكم : لا ترهبوا ولا تخافوا منهم '),
(9524, 'Deuteronomy', 5, 1, 30, ' الرب إلهكم السائر أمامكم هو يحارب عنكم حسب كل ما فعل معكم في مصر أمام أعينكم '),
(9525, 'Deuteronomy', 5, 1, 31, ' وفي البرية ، حيث رأيت كيف حملك الرب إلهك كما يحمل الإنسان ابنه في كل الطريق التي سلكتموها حتى جئتم إلى هذا المكان '),
(9526, 'Deuteronomy', 5, 1, 32, ' ولكن في هذا الأمر لستم واثقين بالرب إلهكم '),
(9527, 'Deuteronomy', 5, 1, 33, ' السائر أمامكم في الطريق ، ليلتمس لكم مكانا لنزولكم ، في نار ليلا ليريكم الطريق التي تسيرون فيها ، وفي سحاب نهارا '),
(9528, 'Deuteronomy', 5, 1, 34, ' وسمع الرب صوت كلامكم فسخط وأقسم قائلا '),
(9529, 'Deuteronomy', 5, 1, 35, ' لن يرى إنسان من هؤلاء الناس ، من هذا الجيل الشرير ، الأرض الجيدة التي أقسمت أن أعطيها لآبائكم '),
(9530, 'Deuteronomy', 5, 1, 36, ' ما عدا كالب بن يفنة . هو يراها ، وله أعطي الأرض التي وطئها ، ولبنيه ، لأنه قد اتبع الرب تماما '),
(9531, 'Deuteronomy', 5, 1, 37, ' وعلي أيضا غضب الرب بسببكم قائلا : وأنت أيضا لا تدخل إلى هناك '),
(9532, 'Deuteronomy', 5, 1, 38, ' يشوع بن نون الواقف أمامك هو يدخل إلى هناك . شدده لأنه هو يقسمها لإسرائيل '),
(9533, 'Deuteronomy', 5, 1, 39, ' وأما أطفالكم الذين قلتم يكونون غنيمة ، وبنوكم الذين لم يعرفوا اليوم الخير والشر فهم يدخلون إلى هناك ، ولهم أعطيها وهم يملكونها '),
(9534, 'Deuteronomy', 5, 1, 40, ' وأما أنتم فتحولوا وارتحلوا إلى البرية على طريق بحر سوف '),
(9535, 'Deuteronomy', 5, 1, 41, ' فأجبتم وقلتم لي : قد أخطأنا إلى الرب . نحن نصعد ونحارب حسب كل ما أمرنا الرب إلهنا . وتنطقتم كل واحد بعدة حربه ، واستخففتم الصعود إلى الجبل '),
(9536, 'Deuteronomy', 5, 1, 42, ' فقال الرب لي : قل لهم : لا تصعدوا ولا تحاربوا ، لأني لست في وسطكم لئلا تنكسروا أمام أعدائكم '),
(9537, 'Deuteronomy', 5, 1, 43, ' فكلمتكم ولم تسمعوا بل عصيتم قول الرب وطغيتم ، وصعدتم إلى الجبل '),
(9538, 'Deuteronomy', 5, 1, 44, ' فخرج الأموريون الساكنون في ذلك الجبل للقائكم وطردوكم كما يفعل النحل ، وكسروكم في سعير إلى حرمة '),
(9539, 'Deuteronomy', 5, 1, 45, ' فرجعتم وبكيتم أمام الرب ، ولم يسمع الرب لصوتكم ولا أصغى إليكم '),
(9540, 'Deuteronomy', 5, 1, 46, ' وقعدتم في قادش أياما كثيرة كالأيام التي قعدتم فيها '),
(9541, 'Deuteronomy', 5, 2, 1, ' ثم تحولنا وارتحلنا إلى البرية على طريق بحر سوف كما كلمني الرب ، ودرنا بجبل سعير أياما كثيرة '),
(9542, 'Deuteronomy', 5, 2, 2, ' ثم كلمني الرب قائلا '),
(9543, 'Deuteronomy', 5, 2, 3, ' كفاكم دوران بهذا الجبل . تحولوا نحو الشمال '),
(9544, 'Deuteronomy', 5, 2, 4, ' وأوص الشعب قائلا : أنتم مارون بتخم إخوتكم بني عيسو الساكنين في سعير ، فيخافون منكم فاحترزوا جدا ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(9545, 'Deuteronomy', 5, 2, 5, ' لا تهجموا عليهم ، لأني لا أعطيكم من أرضهم ولا وطأة قدم ، لأني لعيسو قد أعطيت جبل سعير ميراثا '),
(9546, 'Deuteronomy', 5, 2, 6, ' طعاما تشترون منهم بالفضة لتأكلوا ، وماء أيضا تبتاعون منهم بالفضة لتشربوا '),
(9547, 'Deuteronomy', 5, 2, 7, ' لأن الرب إلهك قد باركك في كل عمل يدك ، عارفا مسيرك في هذا القفر العظيم . الآن أربعون سنة للرب إلهك معك ، لم ينقص عنك شيء '),
(9548, 'Deuteronomy', 5, 2, 8, ' فعبرنا عن إخوتنا بني عيسو الساكنين في سعير على طريق العربة ، على أيلة ، وعلى عصيون جابر ، ثم تحولنا ومررنا في طريق برية موآب '),
(9549, 'Deuteronomy', 5, 2, 9, ' فقال لي الرب : لا تعاد موآب ولا تثر عليهم حربا ، لأني لا أعطيك من أرضهم ميراثا ، لأني لبني لوط قد أعطيت عار ميراثا '),
(9550, 'Deuteronomy', 5, 2, 10, ' الإيميون سكنوا فيها قبلا . شعب كبير وكثير وطويل كالعناقيين '),
(9551, 'Deuteronomy', 5, 2, 11, ' هم أيضا يحسبون رفائيين كالعناقيين ، لكن الموآبيين يدعونهم إيميين '),
(9552, 'Deuteronomy', 5, 2, 12, ' وفي سعير سكن قبلا الحوريون ، فطردهم بنو عيسو وأبادوهم من قدامهم وسكنوا مكانهم ، كما فعل إسرائيل بأرض ميراثهم التي أعطاهم الرب '),
(9553, 'Deuteronomy', 5, 2, 13, ' الآن قوموا واعبروا وادي زارد . فعبرنا وادي زارد '),
(9554, 'Deuteronomy', 5, 2, 14, ' والأيام التي سرنا فيها من قادش برنيع حتى عبرنا وادي زارد ، كانت ثماني وثلاثين سنة ، حتى فني كل الجيل ، رجال الحرب من وسط المحلة ، كما أقسم الرب لهم '),
(9555, 'Deuteronomy', 5, 2, 15, ' ويد الرب أيضا كانت عليهم لإبادتهم من وسط المحلة حتى فنوا '),
(9556, 'Deuteronomy', 5, 2, 16, ' فعندما فني جميع رجال الحرب بالموت من وسط الشعب '),
(9557, 'Deuteronomy', 5, 2, 17, ' كلمني الرب قائلا '),
(9558, 'Deuteronomy', 5, 2, 18, ' أنت مار اليوم بتخم موآب ، بعار '),
(9559, 'Deuteronomy', 5, 2, 19, ' فمتى قربت إلى تجاه بني عمون ، لا تعادهم ولا تهجموا عليهم ، لأني لا أعطيك من أرض بني عمون ميراثا ، لأني لبني لوط قد أعطيتها ميراثا '),
(9560, 'Deuteronomy', 5, 2, 20, ' هي أيضا تحسب أرض رفائيين . سكن الرفائيون فيها قبلا ، لكن العمونيين يدعونهم زمزميين '),
(9561, 'Deuteronomy', 5, 2, 21, ' شعب كبير وكثير وطويل كالعناقيين ، أبادهم الرب من قدامهم ، فطردوهم وسكنوا مكانهم '),
(9562, 'Deuteronomy', 5, 2, 22, ' كما فعل لبني عيسو الساكنين في سعير الذين أتلف الحوريين من قدامهم ، فطردوهم وسكنوا مكانهم إلى هذا اليوم '),
(9563, 'Deuteronomy', 5, 2, 23, ' والعويون الساكنون في القرى إلى غزة ، أبادهم الكفتوريون الذين خرجوا من كفتور وسكنوا مكانهم '),
(9564, 'Deuteronomy', 5, 2, 24, ' قوموا ارتحلوا واعبروا وادي أرنون . انظر . قد دفعت إلى يدك سيحون ملك حشبون الأموري وأرضه . ابتدئ تملك وأثر عليه حربا '),
(9565, 'Deuteronomy', 5, 2, 25, ' في هذا اليوم أبتدئ أجعل خشيتك وخوفك أمام وجوه الشعوب تحت كل السماء . الذين يسمعون خبرك يرتعدون ويجزعون أمامك '),
(9566, 'Deuteronomy', 5, 2, 26, ' فأرسلت رسلا من برية قديموت إلى سيحون ملك حشبون بكلام سلام قائلا '),
(9567, 'Deuteronomy', 5, 2, 27, ' أمر في أرضك . أسلك الطريق الطريق ، لا أميل يمينا ولا شمالا '),
(9568, 'Deuteronomy', 5, 2, 28, ' طعاما بالفضة تبيعني لآكل ، وماء بالفضة تعطيني لأشرب . أمر برجلي فقط '),
(9569, 'Deuteronomy', 5, 2, 29, ' كما فعل بي بنو عيسو الساكنون في سعير ، والموآبيون الساكنون في عار ، إلى أن أعبر الأردن إلى الأرض التي أعطانا الرب إلهنا '),
(9570, 'Deuteronomy', 5, 10, 3, ' فصنعت تابوتا من خشب السنط ، ونحت لوحين من حجر مثل الأولين ، وصعدت إلى الجبل واللوحان في يدي '),
(9571, 'Deuteronomy', 5, 10, 4, ' فكتب على اللوحين مثل الكتابة الأولى ، الكلمات العشر التي كلمكم بها الرب في الجبل من وسط النار في يوم الاجتماع ، وأعطاني الرب إياها '),
(9572, 'Deuteronomy', 5, 10, 5, ' ثم انصرفت ونزلت من الجبل ووضعت اللوحين في التابوت الذي صنعت ، فكانا هناك كما أمرني الرب '),
(9573, 'Deuteronomy', 5, 10, 6, ' وبنو إسرائيل ارتحلوا من آبار بني يعقان إلى موسير . هناك مات هارون ، وهناك دفن . فكهن ألعازار ابنه عوضا عنه '),
(9574, 'Deuteronomy', 5, 10, 7, ' من هناك ارتحلوا إلى الجدجود ومن الجدجود إلى يطبات ، أرض أنهار ماء '),
(9575, 'Deuteronomy', 5, 10, 8, ' في ذلك الوقت أفرز الرب سبط لاوي ليحملوا تابوت عهد الرب ، ولكي يقفوا أمام الرب ليخدموه ويباركوا باسمه إلى هذا اليوم '),
(9576, 'Deuteronomy', 5, 10, 9, ' لأجل ذلك لم يكن للاوي قسم ولا نصيب مع إخوته . الرب هو نصيبه كما كلمه الرب إلهك '),
(9577, 'Deuteronomy', 5, 10, 10, ' وأنا مكثت في الجبل كالأيام الأولى ، أربعين نهارا وأربعين ليلة . وسمع الرب لي تلك المرة أيضا ، ولم يشإ الرب أن يهلكك '),
(9578, 'Deuteronomy', 5, 10, 11, ' ثم قال لي الرب : قم اذهب للارتحال أمام الشعب ، فيدخلوا ويمتلكوا الأرض التي حلفت لآبائهم أن أعطيهم '),
(9579, 'Deuteronomy', 5, 10, 12, ' فالآن يا إسرائيل ، ماذا يطلب منك الرب إلهك إلا أن تتقي الرب إلهك لتسلك في كل طرقه ، وتحبه ، وتعبد الرب إلهك من كل قلبك ومن كل نفسك '),
(9580, 'Deuteronomy', 5, 10, 13, ' وتحفظ وصايا الرب وفرائضه التي أنا أوصيك بها اليوم لخيرك '),
(9581, 'Deuteronomy', 5, 10, 14, ' هوذا للرب إلهك السماوات وسماء السماوات والأرض وكل ما فيها '),
(9582, 'Deuteronomy', 5, 10, 15, ' ولكن الرب إنما التصق بآبائك ليحبهم ، فاختار من بعدهم نسلهم الذي هو أنتم فوق جميع الشعوب كما في هذا اليوم '),
(9583, 'Deuteronomy', 5, 10, 16, ' فاختنوا غرلة قلوبكم ، ولا تصلبوا رقابكم بعد '),
(9584, 'Deuteronomy', 5, 10, 17, ' لأن الرب إلهكم هو إله الآلهة ورب الأرباب ، الإله العظيم الجبار المهيب الذي لا يأخذ بالوجوه ولا يقبل رشوة '),
(9585, 'Deuteronomy', 5, 10, 18, ' الصانع حق اليتيم والأرملة ، والمحب الغريب ليعطيه طعاما ولباسا '),
(9586, 'Deuteronomy', 5, 10, 19, ' فأحبوا الغريب لأنكم كنتم غرباء في أرض مصر '),
(9587, 'Deuteronomy', 5, 10, 20, ' الرب إلهك تتقي . إياه تعبد ، وبه تلتصق ، وباسمه تحلف '),
(9588, 'Deuteronomy', 5, 10, 21, ' هو فخرك ، وهو إلهك الذي صنع معك تلك العظائم والمخاوف التي أبصرتها عيناك '),
(9589, 'Deuteronomy', 5, 10, 22, ' سبعين نفسا نزل آباؤك إلى مصر ، والآن قد جعلك الرب إلهك كنجوم السماء في الكثرة '),
(9590, 'Deuteronomy', 5, 11, 1, ' فأحبب الرب إلهك واحفظ حقوقه وفرائضه وأحكامه ووصاياه كل الأيام '),
(9591, 'Deuteronomy', 5, 11, 2, ' واعلموا اليوم أني لست أريد بنيكم الذين لم يعرفوا ولا رأوا تأديب الرب إلهكم ، عظمته ويده الشديدة وذراعه الرفيعة '),
(9592, 'Deuteronomy', 5, 11, 3, ' وآياته وصنائعه التي عملها في مصر بفرعون ملك مصر وبكل أرضه '),
(9593, 'Deuteronomy', 5, 11, 4, ' والتي عملها بجيش مصر بخيلهم ومراكبهم ، حيث أطاف مياه بحر سوف على وجوههم حين سعوا وراءكم ، فأبادهم الرب إلى هذا اليوم '),
(9594, 'Deuteronomy', 5, 11, 5, ' والتي عملها لكم في البرية حتى جئتم إلى هذا المكان '),
(9595, 'Deuteronomy', 5, 11, 6, ' والتي عملها بداثان وأبيرام ابني أليآب ابن رأوبين اللذين فتحت الأرض فاها وابتلعتهما مع بيوتهما وخيامهما وكل الموجودات التابعة لهما في وسط كل إسرائيل '),
(9596, 'Deuteronomy', 5, 11, 7, ' لأن أعينكم هي التي أبصرت كل صنائع الرب العظيمة التي عملها '),
(9597, 'Deuteronomy', 5, 11, 8, ' فاحفظوا كل الوصايا التي أنا أوصيكم بها اليوم لكي تتشددوا وتدخلوا وتمتلكوا الأرض التي أنتم عابرون إليها لتمتلكوها '),
(9598, 'Deuteronomy', 5, 11, 9, ' ولكي تطيلوا الأيام على الأرض التي أقسم الرب لآبائكم أن يعطيها لهم ولنسلهم ، أرض تفيض لبنا وعسلا '),
(9599, 'Deuteronomy', 5, 11, 10, ' لأن الأرض التي أنت داخل إليها لكي تمتلكها ليست مثل أرض مصر التي خرجت منها ، حيث كنت تزرع زرعك وتسقيه برجلك كبستان بقول '),
(9600, 'Deuteronomy', 5, 11, 11, ' بل الأرض التي أنتم عابرون إليها لكي تمتلكوها ، هي أرض جبال وبقاع . من مطر السماء تشرب ماء '),
(9601, 'Deuteronomy', 5, 11, 12, ' أرض يعتني بها الرب إلهك . عينا الرب إلهك عليها دائما من أول السنة إلى آخرها '),
(9602, 'Deuteronomy', 5, 11, 13, ' فإذا سمعتم لوصاياي التي أنا أوصيكم بها اليوم لتحبوا الرب إلهكم وتعبدوه من كل قلوبكم ومن كل أنفسكم '),
(9603, 'Deuteronomy', 5, 11, 14, ' أعطي مطر أرضكم في حينه : المبكر والمتأخر . فتجمع حنطتك وخمرك وزيتك '),
(9604, 'Deuteronomy', 5, 11, 15, ' وأعطي لبهائمك عشبا في حقلك فتأكل أنت وتشبع '),
(9605, 'Deuteronomy', 5, 11, 16, ' فاحترزوا من أن تنغوي قلوبكم فتزيغوا وتعبدوا آلهة أخرى وتسجدوا لها '),
(9606, 'Deuteronomy', 5, 11, 17, ' فيحمى غضب الرب عليكم ، ويغلق السماء فلا يكون مطر ، ولا تعطي الأرض غلتها ، فتبيدون سريعا عن الأرض الجيدة التي يعطيكم الرب '),
(9607, 'Deuteronomy', 5, 11, 18, ' فضعوا كلماتي هذه على قلوبكم ونفوسكم ، واربطوها علامة على أيديكم ، ولتكن عصائب بين عيونكم '),
(9608, 'Deuteronomy', 5, 11, 19, ' وعلموها أولادكم ، متكلمين بها حين تجلسون في بيوتكم ، وحين تمشون في الطريق ، وحين تنامون ، وحين تقومون '),
(9609, 'Deuteronomy', 5, 11, 20, ' واكتبها على قوائم أبواب بيتك وعلى أبوابك '),
(9610, 'Deuteronomy', 5, 11, 21, ' لكي تكثر أيامك وأيام أولادك على الأرض التي أقسم الرب لآبائك أن يعطيهم إياها ، كأيام السماء على الأرض '),
(9611, 'Deuteronomy', 5, 11, 22, ' لأنه إذا حفظتم جميع هذه الوصايا التي أنا أوصيكم بها لتعملوها ، لتحبوا الرب إلهكم وتسلكوا في جميع طرقه وتلتصقوا به '),
(9612, 'Deuteronomy', 5, 11, 23, ' يطرد الرب جميع هؤلاء الشعوب من أمامكم ، فترثون شعوبا أكبر وأعظم منكم '),
(9613, 'Deuteronomy', 5, 11, 24, ' كل مكان تدوسه بطون أقدامكم يكون لكم . من البرية ولبنان . من النهر ، نهر الفرات ، إلى البحر الغربي يكون تخمكم '),
(9614, 'Deuteronomy', 5, 11, 25, ' لا يقف إنسان في وجهكم . الرب إلهكم يجعل خشيتكم ورعبكم على كل الأرض التي تدوسونها كما كلمكم '),
(9615, 'Deuteronomy', 5, 11, 26, ' انظر . أنا واضع أمامكم اليوم بركة ولعنة '),
(9616, 'Deuteronomy', 5, 11, 27, ' البركة إذا سمعتم لوصايا الرب إلهكم التي أنا أوصيكم بها اليوم '),
(9617, 'Deuteronomy', 5, 11, 28, ' واللعنة إذا لم تسمعوا لوصايا الرب إلهكم ، وزغتم عن الطريق التي أنا أوصيكم بها اليوم لتذهبوا وراء آلهة أخرى لم تعرفوها '),
(9618, 'Deuteronomy', 5, 11, 29, ' وإذا جاء بك الرب إلهك إلى الأرض التي أنت داخل إليها لكي تمتلكها ، فاجعل البركة على جبل جرزيم ، واللعنة على جبل عيبال '),
(9619, 'Deuteronomy', 5, 11, 30, ' أما هما في عبر الأردن ، وراء طريق غروب الشمس في أرض الكنعانيين الساكنين في العربة ، مقابل الجلجال ، بجانب بلوطات مورة '),
(9620, 'Deuteronomy', 5, 11, 31, ' لأنكم عابرون الأردن لتدخلوا وتمتلكوا الأرض التي الرب إلهكم يعطيكم . تمتلكونها وتسكنونها '),
(9621, 'Deuteronomy', 5, 11, 32, ' فاحفظوا جميع الفرائض والأحكام التي أنا واضع أمامكم اليوم لتعملوها '),
(9622, 'Deuteronomy', 5, 12, 1, ' هذه هي الفرائض والأحكام التي تحفظون لتعملوها في الأرض التي أعطاك الرب إله آبائك لتمتلكها ، كل الأيام التي تحيون على الأرض '),
(9623, 'Deuteronomy', 5, 12, 2, ' تخربون جميع الأماكن حيث عبدت الأمم التي ترثونها آلهتها على الجبال الشامخة ، وعلى التلال ، وتحت كل شجرة خضراء '),
(9624, 'Deuteronomy', 5, 12, 3, ' وتهدمون مذابحهم ، وتكسرون أنصابهم ، وتحرقون سواريهم بالنار ، وتقطعون تماثيل آلهتهم ، وتمحون اسمهم من ذلك المكان '),
(9625, 'Deuteronomy', 5, 12, 4, ' لا تفعلوا هكذا للرب إلهكم '),
(9626, 'Deuteronomy', 5, 12, 5, ' بل المكان الذي يختاره الرب إلهكم من جميع أسباطكم ليضع اسمه فيه ، سكناه تطلبون وإلى هناك تأتون '),
(9627, 'Deuteronomy', 5, 12, 6, ' وتقدمون إلى هناك : محرقاتكم وذبائحكم وعشوركم ورفائع أيديكم ونذوركم ونوافلكم وأبكار بقركم وغنمكم '),
(9628, 'Deuteronomy', 5, 12, 7, ' وتأكلون هناك أمام الرب إلهكم ، وتفرحون بكل ما تمتد إليه أيديكم أنتم وبيوتكم كما بارككم الرب إلهكم '),
(9629, 'Deuteronomy', 5, 12, 8, ' لا تعملوا حسب كل ما نحن عاملون هنا اليوم ، أي كل إنسان مهما صلح في عينيه '),
(9630, 'Deuteronomy', 5, 12, 9, ' لأنكم لم تدخلوا حتى الآن إلى المقر والنصيب اللذين يعطيكم الرب إلهكم '),
(9631, 'Deuteronomy', 5, 12, 10, ' فمتى عبرتم الأردن وسكنتم الأرض التي يقسمها لكم الرب إلهكم ، وأراحكم من جميع أعدائكم الذين حواليكم وسكنتم آمنين '),
(9632, 'Deuteronomy', 5, 12, 11, ' فالمكان الذي يختاره الرب إلهكم ليحل اسمه فيه ، تحملون إليه كل ما أنا أوصيكم به : محرقاتكم وذبائحكم وعشوركم ورفائع أيديكم وكل خيار نذوركم التي تنذرونها للرب '),
(9633, 'Deuteronomy', 5, 12, 12, ' وتفرحون أمام الرب إلهكم أنتم وبنوكم وبناتكم وعبيدكم وإماؤكم ، واللاوي الذي في أبوابكم لأنه ليس له قسم ولا نصيب معكم '),
(9634, 'Deuteronomy', 5, 12, 13, ' احترز من أن تصعد محرقاتك في كل مكان تراه '),
(9635, 'Deuteronomy', 5, 12, 14, ' بل في المكان الذي يختاره الرب في أحد أسباطك . هناك تصعد محرقاتك ، وهناك تعمل كل ما أنا أوصيك به '),
(9636, 'Deuteronomy', 5, 12, 15, ' ولكن من كل ما تشتهي نفسك تذبح وتأكل لحما في جميع أبوابك ، حسب بركة الرب إلهك التي أعطاك . النجس والطاهر يأكلانه كالظبي والإيل '),
(9637, 'Deuteronomy', 5, 12, 16, ' وأما الدم فلا تأكله . على الأرض تسفكه كالماء '),
(9638, 'Deuteronomy', 5, 12, 17, ' لا يحل لك أن تأكل في أبوابك عشر حنطتك وخمرك وزيتك ، ولا أبكار بقرك وغنمك ، ولا شيئا من نذورك التي تنذر ، ونوافلك ورفائع يدك '),
(9639, 'Deuteronomy', 5, 12, 18, ' بل أمام الرب إلهك تأكلها في المكان الذي يختاره الرب إلهك ، أنت وابنك وابنتك وعبدك وأمتك واللاوي الذي في أبوابك ، وتفرح أمام الرب إلهك بكل ما امتدت إليه يدك '),
(9640, 'Deuteronomy', 5, 12, 19, ' احترز من أن تترك اللاوي ، كل أيامك على أرضك '),
(9641, 'Deuteronomy', 5, 12, 20, ' إذا وسع الرب إلهك تخومك كما كلمك وقلت : آكل لحما ، لأن نفسك تشتهي أن تأكل لحما . فمن كل ما تشتهي نفسك تأكل لحما '),
(9642, 'Deuteronomy', 5, 12, 21, ' إذا كان المكان الذي يختاره الرب إلهك ليضع اسمه فيه بعيدا عنك ، فاذبح من بقرك وغنمك التي أعطاك الرب كما أوصيتك ، وكل في أبوابك من كل ما اشتهت نفسك '),
(9643, 'Deuteronomy', 5, 12, 22, ' كما يؤكل الظبي والإيل هكذا تأكله . النجس والطاهر يأكلانه سواء '),
(9644, 'Deuteronomy', 5, 2, 30, ' لكن لم يشأ سيحون ملك حشبون أن يدعنا نمر به ، لأن الرب إلهك قسى روحه ، وقوى قلبه لكي يدفعه إلى يدك كما في هذا اليوم '),
(9645, 'Deuteronomy', 5, 2, 31, ' وقال الرب لي : انظر . قد ابتدأت أدفع أمامك سيحون وأرضه . ابتدئ تملك حتى تمتلك أرضه '),
(9646, 'Deuteronomy', 5, 2, 32, ' فخرج سيحون للقائنا هو وجميع قومه للحرب إلى ياهص '),
(9647, 'Deuteronomy', 5, 2, 33, ' فدفعه الرب إلهنا أمامنا ، فضربناه وبنيه وجميع قومه '),
(9648, 'Deuteronomy', 5, 2, 34, ' وأخذنا كل مدنه في ذلك الوقت ، وحرمنا من كل مدينة : الرجال والنساء والأطفال . لم نبق شاردا '),
(9649, 'Deuteronomy', 5, 2, 35, ' لكن البهائم نهبناها لأنفسنا ، وغنيمة المدن التي أخذنا '),
(9650, 'Deuteronomy', 5, 2, 36, ' من عروعير التي على حافة وادي أرنون والمدينة التي في الوادي ، إلى جلعاد ، لم تكن قرية قد امتنعت علينا . الجميع دفعه الرب إلهنا أمامنا '),
(9651, 'Deuteronomy', 5, 2, 37, ' ولكن أرض بني عمون لم نقربها . كل ناحية وادي يبوق ومدن الجبل وكل ما أوصى الرب إلهنا '),
(9652, 'Deuteronomy', 5, 3, 1, ' ثم تحولنا وصعدنا في طريق باشان ، فخرج عوج ملك باشان للقائنا هو وجميع قومه للحرب في إذرعي '),
(9653, 'Deuteronomy', 5, 3, 2, ' فقال لي الرب : لا تخف منه ، لأني قد دفعته إلى يدك وجميع قومه وأرضه ، فتفعل به كما فعلت بسيحون ملك الأموريين الذي كان ساكنا في حشبون '),
(9654, 'Deuteronomy', 5, 3, 3, ' فدفع الرب إلهنا إلى أيدينا عوج أيضا ملك باشان وجميع قومه ، فضربناه حتى لم يبق له شارد '),
(9655, 'Deuteronomy', 5, 3, 4, ' وأخذنا كل مدنه في ذلك الوقت . لم تكن قرية لم نأخذها منهم . ستون مدينة ، كل كورة أرجوب مملكة عوج في باشان '),
(9656, 'Deuteronomy', 5, 3, 5, ' كل هذه كانت مدنا محصنة بأسوار شامخة ، وأبواب ومزاليج . سوى قرى الصحراء الكثيرة جدا '),
(9657, 'Deuteronomy', 5, 3, 6, ' فحرمناها كما فعلنا بسيحون ملك حشبون ، محرمين كل مدينة : الرجال والنساء والأطفال '),
(9658, 'Deuteronomy', 5, 3, 7, ' لكن كل البهائم وغنيمة المدن نهبناها لأنفسنا '),
(9659, 'Deuteronomy', 5, 3, 8, ' وأخذنا في ذلك الوقت من يد ملكي الأموريين الأرض التي في عبر الأردن ، من وادي أرنون إلى جبل حرمون '),
(9660, 'Deuteronomy', 5, 3, 9, ' والصيدونيون يدعون حرمون سريون ، والأموريون يدعونه سنير '),
(9661, 'Deuteronomy', 5, 3, 10, ' كل مدن السهل وكل جلعاد وكل باشان إلى سلخة وإذرعي مدينتي مملكة عوج في باشان '),
(9662, 'Deuteronomy', 5, 3, 11, ' إن عوج ملك باشان وحده بقي من بقية الرفائيين . هوذا سريره سرير من حديد . أليس هو في ربة بني عمون ؟ طوله تسع أذرع ، وعرضه أربع أذرع بذراع رجل '),
(9663, 'Deuteronomy', 5, 3, 12, ' فهذه الأرض امتلكناها في ذلك الوقت من عروعير التي على وادي أرنون ، ونصف جبل جلعاد ومدنه أعطيت للرأوبينيين والجاديين '),
(9664, 'Deuteronomy', 5, 3, 13, ' وبقية جلعاد وكل باشان مملكة عوج أعطيت لنصف سبط منسى . كل كورة أرجوب مع كل باشان . وهي تدعى أرض الرفائيين '),
(9665, 'Deuteronomy', 5, 3, 14, ' يائير ابن منسى أخذ كل كورة أرجوب إلى تخم الجشوريين والمعكيين ، ودعاها على اسمه باشان حووث يائير إلى هذا اليوم '),
(9666, 'Deuteronomy', 5, 3, 15, ' ولماكير أعطيت جلعاد '),
(9667, 'Deuteronomy', 5, 3, 16, ' وللرأوبينيين والجاديين أعطيت من جلعاد إلى وادي أرنون وسط الوادي تخما ، وإلى وادي يبوق تخم بني عمون '),
(9668, 'Deuteronomy', 5, 3, 17, ' والعربة والأردن تخما من كنارة إلى بحر العربة ، بحر الملح ، تحت سفوح الفسجة نحو الشرق '),
(9669, 'Deuteronomy', 5, 3, 18, ' وأمرتكم في ذلك الوقت قائلا : الرب إلهكم قد أعطاكم هذه الأرض لتمتلكوها . متجردين تعبرون أمام إخوتكم بني إسرائيل ، كل ذوي بأس '),
(9670, 'Deuteronomy', 5, 3, 19, ' أما نساؤكم وأطفالكم ومواشيكم ، قد عرفت أن لكم مواشي كثيرة ، فتمكث في مدنكم التي أعطيتكم '),
(9671, 'Deuteronomy', 5, 3, 20, ' حتى يريح الرب إخوتكم مثلكم ويمتلكوا هم أيضا الأرض التي الرب إلهكم يعطيهم في عبر الأردن . ثم ترجعون كل واحد إلى ملكه الذي أعطيتكم '),
(9672, 'Deuteronomy', 5, 3, 21, ' وأمرت يشوع في ذلك الوقت قائلا : عيناك قد أبصرتا كل ما فعل الرب إلهكم بهذين الملكين . هكذا يفعل الرب بجميع الممالك التي أنت عابر إليها '),
(9673, 'Deuteronomy', 5, 3, 22, ' لا تخافوا منهم ، لأن الرب إلهكم هو المحارب عنكم '),
(9674, 'Deuteronomy', 5, 3, 23, ' وتضرعت إلى الرب في ذلك الوقت قائلا '),
(9675, 'Deuteronomy', 5, 3, 24, ' يا سيد الرب ، أنت قد ابتدأت تري عبدك عظمتك ويدك الشديدة . فإنه أي إله في السماء وعلى الأرض يعمل كأعمالك وكجبروتك '),
(9676, 'Deuteronomy', 5, 3, 25, ' دعني أعبر وأرى الأرض الجيدة التي في عبر الأردن ، هذا الجبل الجيد ولبنان '),
(9677, 'Deuteronomy', 5, 3, 26, ' لكن الرب غضب علي بسببكم ولم يسمع لي ، بل قال لي الرب : كفاك لا تعد تكلمني أيضا في هذا الأمر '),
(9678, 'Deuteronomy', 5, 3, 27, ' اصعد إلى رأس الفسجة وارفع عينيك إلى الغرب والشمال والجنوب والشرق ، وانظر بعينيك ، لكن لا تعبر هذا الأردن '),
(9679, 'Deuteronomy', 5, 3, 28, ' وأما يشوع فأوصه وشدده وشجعه ، لأنه هو يعبر أمام هذا الشعب ، وهو يقسم لهم الأرض التي تراها '),
(9680, 'Deuteronomy', 5, 3, 29, ' فمكثنا في الجواء مقابل بيت فغور '),
(9681, 'Deuteronomy', 5, 4, 1, ' فالآن يا إسرائيل اسمع الفرائض والأحكام التي أنا أعلمكم لتعملوها ، لكي تحيوا وتدخلوا وتمتلكوا الأرض التي الرب إله آبائكم يعطيكم '),
(9682, 'Deuteronomy', 5, 4, 2, ' لا تزيدوا على الكلام الذي أنا أوصيكم به ولا تنقصوا منه ، لكي تحفظوا وصايا الرب إلهكم التي أنا أوصيكم بها '),
(9683, 'Deuteronomy', 5, 4, 3, ' أعينكم قد أبصرت ما فعله الرب ببعل فغور . إن كل من ذهب وراء بعل فغور أباده الرب إلهكم من وسطكم '),
(9684, 'Deuteronomy', 5, 4, 4, ' وأما أنتم الملتصقون بالرب إلهكم فجميعكم أحياء اليوم '),
(9685, 'Deuteronomy', 5, 4, 5, ' انظر . قد علمتكم فرائض وأحكاما كما أمرني الرب إلهي ، لكي تعملوا هكذا في الأرض التي أنتم داخلون إليها لكي تمتلكوها '),
(9686, 'Deuteronomy', 5, 4, 6, ' فاحفظوا واعملوا . لأن ذلك حكمتكم وفطنتكم أمام أعين الشعوب الذين يسمعون كل هذه الفرائض ، فيقولون : هذا الشعب العظيم إنما هو شعب حكيم وفطن '),
(9687, 'Deuteronomy', 5, 4, 7, ' لأنه أي شعب هو عظيم له آلهة قريبة منه كالرب إلهنا في كل أدعيتنا إليه '),
(9688, 'Deuteronomy', 5, 4, 8, ' وأي شعب هو عظيم له فرائض وأحكام عادلة مثل كل هذه الشريعة التي أنا واضع أمامكم اليوم '),
(9689, 'Deuteronomy', 5, 4, 9, ' إنما احترز واحفظ نفسك جدا لئلا تنسى الأمور التي أبصرت عيناك ، ولئلا تزول من قلبك كل أيام حياتك . وعلمها أولادك وأولاد أولادك '),
(9690, 'Deuteronomy', 5, 4, 10, ' في اليوم الذي وقفت فيه أمام الرب إلهك في حوريب حين قال لي الرب : اجمع لي الشعب فأسمعهم كلامي ، لكي يتعلموا أن يخافوني كل الأيام التي هم فيها أحياء على الأرض ، ويعلموا أولادهم '),
(9691, 'Deuteronomy', 5, 4, 11, ' فتقدمتم ووقفتم في أسفل الجبل ، والجبل يضطرم بالنار إلى كبد السماء ، بظلام وسحاب وضباب '),
(9692, 'Deuteronomy', 5, 4, 12, ' فكلمكم الرب من وسط النار وأنتم سامعون صوت كلام ، ولكن لم تروا صورة بل صوتا '),
(9693, 'Deuteronomy', 5, 4, 13, ' وأخبركم بعهده الذي أمركم أن تعملوا به ، الكلمات العشر ، وكتبه على لوحي حجر '),
(9694, 'Deuteronomy', 5, 4, 14, ' وإياي أمر الرب في ذلك الوقت أن أعلمكم فرائض وأحكاما لكي تعملوها في الأرض التي أنتم عابرون إليها لتمتلكوها '),
(9695, 'Deuteronomy', 5, 4, 15, ' فاحتفظوا جدا لأنفسكم . فإنكم لم تروا صورة ما يوم كلمكم الرب في حوريب من وسط النار '),
(9696, 'Deuteronomy', 5, 4, 16, ' لئلا تفسدوا وتعملوا لأنفسكم تمثالا منحوتا ، صورة مثال ما ، شبه ذكر أو أنثى '),
(9697, 'Deuteronomy', 5, 4, 17, ' شبه بهيمة ما مما على الأرض ، شبه طير ما ذي جناح مما يطير في السماء '),
(9698, 'Deuteronomy', 5, 4, 18, ' شبه دبيب ما على الأرض ، شبه سمك ما مما في الماء من تحت الأرض '),
(9699, 'Deuteronomy', 5, 4, 19, ' ولئلا ترفع عينيك إلى السماء ، وتنظر الشمس والقمر والنجوم ، كل جند السماء التي قسمها الرب إلهك لجميع الشعوب التي تحت كل السماء ، فتغتر وتسجد لها وتعبدها '),
(9700, 'Deuteronomy', 5, 4, 20, ' وأنتم قد أخذكم الرب وأخرجكم من كور الحديد من مصر ، لكي تكونوا له شعب ميراث كما في هذا اليوم '),
(9701, 'Deuteronomy', 5, 4, 21, ' وغضب الرب علي بسببكم ، وأقسم إني لا أعبر الأردن ولا أدخل الأرض الجيدة التي الرب إلهك يعطيك نصيبا '),
(9702, 'Deuteronomy', 5, 4, 22, ' فأموت أنا في هذه الأرض ، لا أعبر الأردن ، وأما أنتم فتعبرون وتمتلكون تلك الأرض الجيدة '),
(9703, 'Deuteronomy', 5, 4, 23, ' احترزوا من أن تنسوا عهد الرب إلهكم الذي قطعه معكم ، وتصنعوا لأنفسكم تمثالا منحوتا ، صورة كل ما نهاك عنه الرب إلهك '),
(9704, 'Deuteronomy', 5, 4, 24, ' لأن الرب إلهك هو نار آكلة ، إله غيور '),
(9705, 'Deuteronomy', 5, 4, 25, ' إذا ولدتم أولادا وأولاد أولاد ، وأطلتم الزمان في الأرض ، وفسدتم وصنعتم تمثالا منحوتا صورة شيء ما ، وفعلتم الشر في عيني الرب إلهكم لإغاظته '),
(9706, 'Deuteronomy', 5, 4, 26, ' أشهد عليكم اليوم السماء والأرض أنكم تبيدون سريعا عن الأرض التي أنتم عابرون الأردن إليها لتمتلكوها . لا تطيلون الأيام عليها ، بل تهلكون لا محالة '),
(9707, 'Deuteronomy', 5, 4, 27, ' ويبددكم الرب في الشعوب ، فتبقون عددا قليلا بين الأمم التي يسوقكم الرب إليها '),
(9708, 'Deuteronomy', 5, 4, 28, ' وتصنعون هناك آلهة صنعة أيدي الناس من خشب وحجر مما لا يبصر ولا يسمع ولا يأكل ولا يشم '),
(9709, 'Deuteronomy', 5, 4, 29, ' ثم إن طلبت من هناك الرب إلهك تجده إذا التمسته بكل قلبك وبكل نفسك '),
(9710, 'Deuteronomy', 5, 4, 30, ' عندما ضيق عليك وأصابتك كل هذه الأمور في آخر الأيام ، ترجع إلى الرب إلهك وتسمع لقوله '),
(9711, 'Deuteronomy', 5, 4, 31, ' لأن الرب إلهك إله رحيم ، لا يتركك ولا يهلكك ولا ينسى عهد آبائك الذي أقسم لهم عليه '),
(9712, 'Deuteronomy', 5, 4, 32, ' فاسأل عن الأيام الأولى التي كانت قبلك ، من اليوم الذي خلق الله فيه الإنسان على الأرض ، ومن أقصاء السماء إلى أقصائها . هل جرى مثل هذا الأمر العظيم ، أو هل سمع نظيره '),
(9713, 'Deuteronomy', 5, 4, 33, ' هل سمع شعب صوت الله يتكلم من وسط النار كما سمعت أنت ، وعاش '),
(9714, 'Deuteronomy', 5, 4, 34, ' أو هل شرع الله أن يأتي ويأخذ لنفسه شعبا من وسط شعب ، بتجارب وآيات وعجائب وحرب ويد شديدة وذراع رفيعة ومخاوف عظيمة ، مثل كل ما فعل لكم الرب إلهكم في مصر أمام أعينكم '),
(9715, 'Deuteronomy', 5, 4, 35, ' إنك قد أريت لتعلم أن الرب هو الإله . ليس آخر سواه '),
(9716, 'Deuteronomy', 5, 4, 36, ' من السماء أسمعك صوته لينذرك ، وعلى الأرض أراك ناره العظيمة ، وسمعت كلامه من وسط النار '),
(9717, 'Deuteronomy', 5, 4, 37, ' ولأجل أنه أحب آباءك واختار نسلهم من بعدهم ، أخرجك بحضرته بقوته العظيمة من مصر '),
(9718, 'Deuteronomy', 5, 15, 13, ' وحين تطلقه حرا من عندك لا تطلقه فارغا '),
(9719, 'Deuteronomy', 5, 15, 14, ' تزوده من غنمك ومن بيدرك ومن معصرتك . كما باركك الرب إلهك تعطيه '),
(9720, 'Deuteronomy', 5, 15, 15, ' واذكر أنك كنت عبدا في أرض مصر ، ففداك الرب إلهك . لذلك أنا أوصيك بهذا الأمر اليوم '),
(9721, 'Deuteronomy', 5, 15, 16, ' ولكن إذا قال لك : لا أخرج من عندك . لأنه قد أحبك وبيتك ، إذ كان له خير عندك '),
(9722, 'Deuteronomy', 5, 15, 17, ' فخذ المخرز واجعله في أذنه وفي الباب ، فيكون لك عبدا مؤبدا . وهكذا تفعل لأمتك أيضا '),
(9723, 'Deuteronomy', 5, 15, 18, ' لا يصعب عليك أن تطلقه حرا من عندك ، لأنه ضعفي أجرة الأجير خدمك ست سنين . فيباركك الرب إلهك في كل ما تعمل '),
(9724, 'Deuteronomy', 5, 15, 19, ' كل بكر ذكر يولد من بقرك ومن غنمك تقدسه للرب إلهك . لا تشتغل على بكر بقرك ولا تجز بكر غنمك '),
(9725, 'Deuteronomy', 5, 15, 20, ' أمام الرب إلهك تأكله سنة بسنة ، في المكان الذي يختاره الرب ، أنت وبيتك '),
(9726, 'Deuteronomy', 5, 15, 21, ' ولكن إذا كان فيه عيب ، عرج أو عمى ، عيب ما رديء ، فلا تذبحه للرب إلهك '),
(9727, 'Deuteronomy', 5, 15, 22, ' في أبوابك تأكله . النجس والطاهر سواء كالظبي والأيل '),
(9728, 'Deuteronomy', 5, 15, 23, ' وأما دمه فلا تأكله . على الأرض تسفكه كالماء '),
(9729, 'Deuteronomy', 5, 16, 1, ' احفظ شهر أبيب واعمل فصحا للرب إلهك ، لأنه في شهر أبيب أخرجك الرب إلهك من مصر ليلا '),
(9730, 'Deuteronomy', 5, 16, 2, ' فتذبح الفصح للرب إلهك غنما وبقرا في المكان الذي يختاره الرب ليحل اسمه فيه '),
(9731, 'Deuteronomy', 5, 16, 3, ' لا تأكل عليه خميرا . سبعة أيام تأكل عليه فطيرا ، خبز المشقة ، لأنك بعجلة خرجت من أرض مصر ، لكي تذكر يوم خروجك من أرض مصر كل أيام حياتك '),
(9732, 'Deuteronomy', 5, 16, 4, ' ولا ير عندك خمير في جميع تخومك سبعة أيام ، ولا يبت شيء من اللحم الذي تذبح مساء في اليوم الأول إلى الغد '),
(9733, 'Deuteronomy', 5, 16, 5, ' لا يحل لك أن تذبح الفصح في أحد أبوابك التي يعطيك الرب إلهك '),
(9734, 'Deuteronomy', 5, 16, 6, ' بل في المكان الذي يختاره الرب إلهك ليحل اسمه فيه . هناك تذبح الفصح مساء نحو غروب الشمس في ميعاد خروجك من مصر '),
(9735, 'Deuteronomy', 5, 16, 7, ' وتطبخ وتأكل في المكان الذي يختاره الرب إلهك ، ثم تنصرف في الغد وتذهب إلى خيامك '),
(9736, 'Deuteronomy', 5, 16, 8, ' ستة أيام تأكل فطيرا ، وفي اليوم السابع اعتكاف للرب إلهك . لا تعمل فيه عملا '),
(9737, 'Deuteronomy', 5, 16, 9, ' سبعة أسابيع تحسب لك . من ابتداء المنجل في الزرع ، تبتدئ أن تحسب سبعة أسابيع '),
(9738, 'Deuteronomy', 5, 16, 10, ' وتعمل عيد أسابيع للرب إلهك على قدر ما تسمح يدك أن تعطي ، كما يباركك الرب إلهك '),
(9739, 'Deuteronomy', 5, 16, 11, ' وتفرح أمام الرب إلهك أنت وابنك وابنتك وعبدك وأمتك واللاوي الذي في أبوابك ، والغريب واليتيم والأرملة الذين في وسطك في المكان الذي يختاره الرب إلهك ليحل اسمه فيه '),
(9740, 'Deuteronomy', 5, 16, 12, ' وتذكر أنك كنت عبدا في مصر وتحفظ ، وتعمل هذه الفرائض '),
(9741, 'Deuteronomy', 5, 16, 13, ' تعمل لنفسك عيد المظال سبعة أيام عندما تجمع من بيدرك ومن معصرتك '),
(9742, 'Deuteronomy', 5, 16, 14, ' وتفرح في عيدك أنت وابنك وابنتك وعبدك وأمتك واللاوي والغريب واليتيم والأرملة الذين في أبوابك '),
(9743, 'Deuteronomy', 5, 16, 15, ' سبعة أيام تعيد للرب إلهك في المكان الذي يختاره الرب ، لأن الرب إلهك يباركك في كل محصولك وفي كل عمل يديك ، فلا تكون إلا فرحا '),
(9744, 'Deuteronomy', 5, 16, 16, ' ثلاث مرات في السنة يحضر جميع ذكورك أمام الرب إلهك في المكان الذي يختاره ، في عيد الفطير وعيد الأسابيع وعيد المظال . ولا يحضروا أمام الرب فارغين '),
(9745, 'Deuteronomy', 5, 16, 17, ' كل واحد حسبما تعطي يده ، كبركة الرب إلهك التي أعطاك '),
(9746, 'Deuteronomy', 5, 16, 18, ' قضاة وعرفاء تجعل لك في جميع أبوابك التي يعطيك الرب إلهك حسب أسباطك ، فيقضون للشعب قضاء عادلا '),
(9747, 'Deuteronomy', 5, 16, 19, ' لا تحرف القضاء ، ولا تنظر إلى الوجوه ، ولا تأخذ رشوة لأن الرشوة تعمي أعين الحكماء وتعوج كلام الصديقين '),
(9748, 'Deuteronomy', 5, 16, 20, ' العدل العدل تتبع ، لكي تحيا وتمتلك الأرض التي يعطيك الرب إلهك '),
(9749, 'Deuteronomy', 5, 16, 21, ' لا تنصب لنفسك سارية من شجرة ما بجانب مذبح الرب إلهك الذي تصنعه لك '),
(9750, 'Deuteronomy', 5, 16, 22, ' ولا تقم لك نصبا . الشيء الذي يبغضه الرب إلهك '),
(9751, 'Deuteronomy', 5, 17, 1, ' لا تذبح للرب إلهك ثورا أو شاة فيه عيب ، شيء ما رديء ، لأن ذلك رجس لدى الرب إلهك '),
(9752, 'Deuteronomy', 5, 17, 2, ' إذا وجد في وسطك في أحد أبوابك التي يعطيك الرب إلهك رجل أو امرأة يفعل شرا في عيني الرب إلهك بتجاوز عهده '),
(9753, 'Deuteronomy', 5, 17, 3, ' ويذهب ويعبد آلهة أخرى ويسجد لها ، أو للشمس أو للقمر أو لكل من جند السماء ، الشيء الذي لم أوص به '),
(9754, 'Deuteronomy', 5, 17, 4, ' وأخبرت وسمعت وفحصت جيدا وإذا الأمر صحيح أكيد . قد عمل ذلك الرجس في إسرائيل '),
(9755, 'Deuteronomy', 5, 17, 5, ' فأخرج ذلك الرجل أو تلك المرأة ، الذي فعل ذلك الأمر الشرير إلى أبوابك ، الرجل أو المرأة ، وارجمه بالحجارة حتى يموت '),
(9756, 'Deuteronomy', 5, 17, 6, ' على فم شاهدين أو ثلاثة شهود يقتل الذي يقتل . لا يقتل على فم شاهد واحد '),
(9757, 'Deuteronomy', 5, 17, 7, ' أيدي الشهود تكون عليه أولا لقتله ، ثم أيدي جميع الشعب أخيرا ، فتنزع الشر من وسطك '),
(9758, 'Deuteronomy', 5, 17, 8, ' إذا عسر عليك أمر في القضاء بين دم ودم ، أو بين دعوى ودعوى ، أو بين ضربة وضربة من أمور الخصومات في أبوابك ، فقم واصعد إلى المكان الذي يختاره الرب إلهك '),
(9759, 'Deuteronomy', 5, 17, 9, ' واذهب إلى الكهنة اللاويين وإلى القاضي الذي يكون في تلك الأيام ، واسأل فيخبروك بأمر القضاء '),
(9760, 'Deuteronomy', 5, 17, 10, ' فتعمل حسب الأمر الذي يخبرونك به من ذلك المكان الذي يختاره الرب ، وتحرص أن تعمل حسب كل ما يعلمونك '),
(9761, 'Deuteronomy', 5, 17, 11, ' حسب الشريعة التي يعلمونك والقضاء الذي يقولونه لك تعمل . لا تحد عن الأمر الذي يخبرونك به يمينا أو شمالا '),
(9762, 'Deuteronomy', 5, 17, 12, ' والرجل الذي يعمل بطغيان ، فلا يسمع للكاهن الواقف هناك ليخدم الرب إلهك ، أو للقاضي ، يقتل ذلك الرجل ، فتنزع الشر من إسرائيل '),
(9763, 'Deuteronomy', 5, 17, 13, ' فيسمع جميع الشعب ويخافون ولا يطغون بعد '),
(9764, 'Deuteronomy', 5, 17, 14, ' متى أتيت إلى الأرض التي يعطيك الرب إلهك ، وامتلكتها وسكنت فيها ، فإن قلت : أجعل علي ملكا كجميع الأمم الذين حولي '),
(9765, 'Deuteronomy', 5, 17, 15, ' فإنك تجعل عليك ملكا الذي يختاره الرب إلهك . من وسط إخوتك تجعل عليك ملكا . لا يحل لك أن تجعل عليك رجلا أجنبيا ليس هو أخاك '),
(9766, 'Deuteronomy', 5, 17, 16, ' ولكن لا يكثر له الخيل ، ولا يرد الشعب إلى مصر لكي يكثر الخيل ، والرب قد قال لكم : لا تعودوا ترجعون في هذه الطريق أيضا '),
(9767, 'Deuteronomy', 5, 17, 17, ' ولا يكثر له نساء لئلا يزيغ قلبه . وفضة وذهبا لا يكثر له كثيرا '),
(9768, 'Deuteronomy', 5, 17, 18, ' وعندما يجلس على كرسي مملكته ، يكتب لنفسه نسخة من هذه الشريعة في كتاب من عند الكهنة اللاويين '),
(9769, 'Deuteronomy', 5, 17, 19, ' فتكون معه ، ويقرأ فيها كل أيام حياته ، لكي يتعلم أن يتقي الرب إلهه ويحفظ جميع كلمات هذه الشريعة وهذه الفرائض ليعمل بها '),
(9770, 'Deuteronomy', 5, 17, 20, ' لئلا يرتفع قلبه على إخوته ، ولئلا يحيد عن الوصية يمينا أو شمالا . لكي يطيل الأيام على مملكته هو وبنوه في وسط إسرائيل '),
(9771, 'Deuteronomy', 5, 18, 1, ' لا يكون للكهنة اللاويين ، كل سبط لاوي ، قسم ولا نصيب مع إسرائيل . يأكلون وقائد الرب ونصيبه '),
(9772, 'Deuteronomy', 5, 18, 2, ' فلا يكون له نصيب في وسط إخوته . الرب هو نصيبه كما قال له '),
(9773, 'Deuteronomy', 5, 18, 3, ' وهذا يكون حق الكهنة من الشعب ، من الذين يذبحون الذبائح بقرا كانت أو غنما . يعطون الكاهن الساعد والفكين والكرش '),
(9774, 'Deuteronomy', 5, 18, 4, ' وتعطيه أول حنطتك وخمرك وزيتك ، وأول جزاز غنمك '),
(9775, 'Deuteronomy', 5, 18, 5, ' لأن الرب إلهك قد اختاره من جميع أسباطك لكي يقف ليخدم باسم الرب ، هو وبنوه كل الأيام '),
(9776, 'Deuteronomy', 5, 18, 6, ' وإذا جاء لاوي من أحد أبوابك من جميع إسرائيل حيث هو متغرب ، وجاء بكل رغبة نفسه إلى المكان الذي يختاره الرب '),
(9777, 'Deuteronomy', 5, 18, 7, ' وخدم باسم الرب إلهك مثل جميع إخوته اللاويين الواقفين هناك أمام الرب '),
(9778, 'Deuteronomy', 5, 18, 8, ' يأكلون أقساما متساوية ، عدا ما يبيعه عن آبائه '),
(9779, 'Deuteronomy', 5, 18, 9, ' متى دخلت الأرض التي يعطيك الرب إلهك ، لا تتعلم أن تفعل مثل رجس أولئك الأمم '),
(9780, 'Deuteronomy', 5, 18, 10, ' لا يوجد فيك من يجيز ابنه أو ابنته في النار ، ولا من يعرف عرافة ، ولا عائف ولا متفائل ولا ساحر '),
(9781, 'Deuteronomy', 5, 18, 11, ' ولا من يرقي رقية ، ولا من يسأل جانا أو تابعة ، ولا من يستشير الموتى '),
(9782, 'Deuteronomy', 5, 18, 12, ' لأن كل من يفعل ذلك مكروه عند الرب . وبسبب هذه الأرجاس ، الرب إلهك طاردهم من أمامك '),
(9783, 'Deuteronomy', 5, 18, 13, ' تكون كاملا لدى الرب إلهك '),
(9784, 'Deuteronomy', 5, 18, 14, ' إن هؤلاء الأمم الذين تخلفهم يسمعون للعائفين والعرافين . وأما أنت فلم يسمح لك الرب إلهك هكذا '),
(9785, 'Deuteronomy', 5, 18, 15, ' يقيم لك الرب إلهك نبيا من وسطك من إخوتك مثلي . له تسمعون '),
(9786, 'Deuteronomy', 5, 18, 16, ' حسب كل ما طلبت من الرب إلهك في حوريب يوم الاجتماع قائلا : لا أعود أسمع صوت الرب إلهي ولا أرى هذه النار العظيمة أيضا لئلا أموت '),
(9787, 'Deuteronomy', 5, 18, 17, ' قال لي الرب : قد أحسنوا في ما تكلموا '),
(9788, 'Deuteronomy', 5, 18, 18, ' أقيم لهم نبيا من وسط إخوتهم مثلك ، وأجعل كلامي في فمه ، فيكلمهم بكل ما أوصيه به '),
(9789, 'Deuteronomy', 5, 18, 19, ' ويكون أن الإنسان الذي لا يسمع لكلامي الذي يتكلم به باسمي أنا أطالبه '),
(9790, 'Deuteronomy', 5, 18, 20, ' وأما النبي الذي يطغي ، فيتكلم باسمي كلاما لم أوصه أن يتكلم به ، أو الذي يتكلم باسم آلهة أخرى ، فيموت ذلك النبي '),
(9791, 'Deuteronomy', 5, 18, 21, ' وإن قلت في قلبك : كيف نعرف الكلام الذي لم يتكلم به الرب '),
(9792, 'Deuteronomy', 5, 4, 38, ' لكي يطرد من أمامك شعوبا أكبر وأعظم منك ، ويأتي بك ويعطيك أرضهم نصيبا كما في هذا اليوم '),
(9793, 'Deuteronomy', 5, 4, 39, ' فاعلم اليوم وردد في قلبك أن الرب هو الإله في السماء من فوق ، وعلى الأرض من أسفل . ليس سواه '),
(9794, 'Deuteronomy', 5, 4, 40, ' واحفظ فرائضه ووصاياه التي أنا أوصيك بها اليوم لكي يحسن إليك وإلى أولادك من بعدك ، ولكي تطيل أيامك على الأرض التي الرب إلهك يعطيك إلى الأبد '),
(9795, 'Deuteronomy', 5, 4, 41, ' حينئذ أفرز موسى ثلاث مدن في عبر الأردن نحو شروق الشمس '),
(9796, 'Deuteronomy', 5, 4, 42, ' لكي يهرب إليها القاتل الذي يقتل صاحبه بغير علم ، وهو غير مبغض له منذ أمس وما قبله . يهرب إلى إحدى تلك المدن فيحيا '),
(9797, 'Deuteronomy', 5, 4, 43, ' باصر في البرية في أرض السهل للرأوبينيين ، وراموت في جلعاد للجاديين ، وجولان في باشان للمنسيين '),
(9798, 'Deuteronomy', 5, 4, 44, ' وهذه هي الشريعة التي وضعها موسى أمام بني إسرائيل '),
(9799, 'Deuteronomy', 5, 4, 45, ' هذه هي الشهادات والفرائض والأحكام التي كلم بها موسى بني إسرائيل عند خروجهم من مصر '),
(9800, 'Deuteronomy', 5, 4, 46, ' في عبر الأردن في الجواء مقابل بيت فغور ، في أرض سيحون ملك الأموريين الذي كان ساكنا في حشبون ، الذي ضربه موسى وبنو إسرائيل عند خروجهم من مصر '),
(9801, 'Deuteronomy', 5, 4, 47, ' وامتلكوا أرضه وأرض عوج ملك باشان ، ملكي الأموريين ، اللذين في عبر الأردن نحو شروق الشمس '),
(9802, 'Deuteronomy', 5, 4, 48, ' من عروعير التي على حافة وادي أرنون إلى جبل سيئون الذي هو حرمون '),
(9803, 'Deuteronomy', 5, 4, 49, ' وكل العربة في عبر الأردن نحو الشروق إلى بحر العربة تحت سفوح الفسجة '),
(9804, 'Deuteronomy', 5, 5, 1, ' ودعا موسى جميع إسرائيل وقال لهم : اسمع يا إسرائيل الفرائض والأحكام التي أتكلم بها في مسامعكم اليوم ، وتعلموها واحترزوا لتعملوها '),
(9805, 'Deuteronomy', 5, 5, 2, ' الرب إلهنا قطع معنا عهدا في حوريب '),
(9806, 'Deuteronomy', 5, 5, 3, ' ليس مع آبائنا قطع الرب هذا العهد ، بل معنا نحن الذين هنا اليوم جميعنا أحياء '),
(9807, 'Deuteronomy', 5, 5, 4, ' وجها لوجه تكلم الرب معنا في الجبل من وسط النار '),
(9808, 'Deuteronomy', 5, 5, 5, ' أنا كنت واقفا بين الرب وبينكم في ذلك الوقت لكي أخبركم بكلام الرب ، لأنكم خفتم من أجل النار ، ولم تصعدوا إلى الجبل . فقال '),
(9809, 'Deuteronomy', 5, 5, 6, ' أنا هو الرب إلهك الذي أخرجك من أرض مصر من بيت العبودية '),
(9810, 'Deuteronomy', 5, 5, 7, ' لا يكن لك آلهة أخرى أمامي '),
(9811, 'Deuteronomy', 5, 5, 8, ' لا تصنع لك تمثالا منحوتا صورة ما مما في السماء من فوق وما في الأرض من أسفل وما في الماء من تحت الأرض '),
(9812, 'Deuteronomy', 5, 5, 9, ' لا تسجد لهن ولا تعبدهن ، لأني أنا الرب إلهك إله غيور ، أفتقد ذنوب الآباء في الأبناء وفي الجيل الثالث والرابع من الذين يبغضونني '),
(9813, 'Deuteronomy', 5, 5, 10, ' وأصنع إحسانا إلى ألوف من محبي وحافظي وصاياي '),
(9814, 'Deuteronomy', 5, 5, 11, ' لا تنطق باسم الرب إلهك باطلا ، لأن الرب لا يبرئ من نطق باسمه باطلا '),
(9815, 'Deuteronomy', 5, 5, 12, ' احفظ يوم السبت لتقدسه كما أوصاك الرب إلهك '),
(9816, 'Deuteronomy', 5, 5, 13, ' ستة أيام تشتغل وتعمل جميع أعمالك '),
(9817, 'Deuteronomy', 5, 5, 14, ' وأما اليوم السابع فسبت للرب إلهك ، لا تعمل فيه عملا ما أنت وابنك وابنتك وعبدك وأمتك وثورك وحمارك وكل بهائمك ، ونزيلك الذي في أبوابك لكي يستريح ، عبدك وأمتك مثلك '),
(9818, 'Deuteronomy', 5, 5, 15, ' واذكر أنك كنت عبدا في أرض مصر ، فأخرجك الرب إلهك من هناك بيد شديدة وذراع ممدودة . لأجل ذلك أوصاك الرب إلهك أن تحفظ يوم السبت '),
(9819, 'Deuteronomy', 5, 5, 16, ' أكرم أباك وأمك كما أوصاك الرب إلهك ، لكي تطول أيامك ، ولكي يكون لك خير على الأرض التي يعطيك الرب إلهك '),
(9820, 'Deuteronomy', 5, 5, 17, ' لا تقتل '),
(9821, 'Deuteronomy', 5, 5, 18, ' ولا تزن '),
(9822, 'Deuteronomy', 5, 5, 19, ' ولا تسرق '),
(9823, 'Deuteronomy', 5, 5, 20, ' ولا تشهد على قريبك شهادة زور '),
(9824, 'Deuteronomy', 5, 5, 21, ' ولا تشته امرأة قريبك ، ولا تشته بيت قريبك ولا حقله ولا عبده ولا أمته ولا ثوره ولا حماره ولا كل ما لقريبك '),
(9825, 'Deuteronomy', 5, 5, 22, ' هذه الكلمات كلم بها الرب كل جماعتكم في الجبل من وسط النار والسحاب والضباب ، وصوت عظيم ولم يزد . وكتبها على لوحين من حجر وأعطاني إياها '),
(9826, 'Deuteronomy', 5, 5, 23, ' فلما سمعتم الصوت من وسط الظلام ، والجبل يشتعل بالنار ، تقدمتم إلي ، جميع رؤساء أسباطكم وشيوخكم '),
(9827, 'Deuteronomy', 5, 5, 24, ' وقلتم : هوذا الرب إلهنا قد أرانا مجده وعظمته ، وسمعنا صوته من وسط النار . هذا اليوم قد رأينا أن الله يكلم الإنسان ويحيا '),
(9828, 'Deuteronomy', 5, 5, 25, ' وأما الآن فلماذا نموت ؟ لأن هذه النار العظيمة تأكلنا . إن عدنا نسمع صوت الرب إلهنا أيضا نموت '),
(9829, 'Deuteronomy', 5, 5, 26, ' لأنه من هو من جميع البشر الذي سمع صوت الله الحي يتكلم من وسط النار مثلنا وعاش '),
(9830, 'Deuteronomy', 5, 5, 27, ' تقدم أنت واسمع كل ما يقول لك الرب إلهنا ، وكلمنا بكل ما يكلمك به الرب إلهنا ، فنسمع ونعمل '),
(9831, 'Deuteronomy', 5, 5, 28, ' فسمع الرب صوت كلامكم حين كلمتموني وقال لي الرب : سمعت صوت كلام هؤلاء الشعب الذي كلموك به . قد أحسنوا في كل ما تكلموا '),
(9832, 'Deuteronomy', 5, 5, 29, ' يا ليت قلبهم كان هكذا فيهم حتى يتقوني ويحفظوا جميع وصاياي كل الأيام ، لكي يكون لهم ولأولادهم خير إلى الأبد '),
(9833, 'Deuteronomy', 5, 5, 30, ' اذهب قل لهم : ارجعوا إلى خيامكم '),
(9834, 'Deuteronomy', 5, 5, 31, ' وأما أنت فقف هنا معي فأكلمك بجميع الوصايا والفرائض والأحكام التي تعلمهم فيعملونها في الأرض التي أنا أعطيهم ليمتلكوها '),
(9835, 'Deuteronomy', 5, 5, 32, ' فاحترزوا لتعملوا كما أمركم الرب إلهكم . لا تزيغوا يمينا ولا يسارا '),
(9836, 'Deuteronomy', 5, 5, 33, ' في جميع الطريق التي أوصاكم بها الرب إلهكم تسلكون ، لكي تحيوا ويكون لكم خير وتطيلوا الأيام في الأرض التي تمتلكونها '),
(9837, 'Deuteronomy', 5, 6, 1, ' وهذه هي الوصايا والفرائض والأحكام التي أمر الرب إلهكم أن أعلمكم لتعملوها في الأرض التي أنتم عابرون إليها لتمتلكوها '),
(9838, 'Deuteronomy', 5, 6, 2, ' لكي تتقي الرب إلهك وتحفظ جميع فرائضه ووصاياه التي أنا أوصيك بها ، أنت وابنك وابن ابنك كل أيام حياتك ، ولكي تطول أيامك '),
(9839, 'Deuteronomy', 5, 6, 3, ' فاسمع يا إسرائيل واحترز لتعمل ، لكي يكون لك خير وتكثر جدا ، كما كلمك الرب إله آبائك في أرض تفيض لبنا وعسلا '),
(9840, 'Deuteronomy', 5, 6, 4, ' اسمع يا إسرائيل : الرب إلهنا رب واحد '),
(9841, 'Deuteronomy', 5, 6, 5, ' فتحب الرب إلهك من كل قلبك ومن كل نفسك ومن كل قوتك '),
(9842, 'Deuteronomy', 5, 6, 6, ' ولتكن هذه الكلمات التي أنا أوصيك بها اليوم على قلبك '),
(9843, 'Deuteronomy', 5, 6, 7, ' وقصها على أولادك ، وتكلم بها حين تجلس في بيتك ، وحين تمشي في الطريق ، وحين تنام وحين تقوم '),
(9844, 'Deuteronomy', 5, 6, 8, ' واربطها علامة على يدك ، ولتكن عصائب بين عينيك '),
(9845, 'Deuteronomy', 5, 6, 9, ' واكتبها على قوائم أبواب بيتك وعلى أبوابك '),
(9846, 'Deuteronomy', 5, 6, 10, ' ومتى أتى بك الرب إلهك إلى الأرض التي حلف لآبائك إبراهيم وإسحاق ويعقوب أن يعطيك ، إلى مدن عظيمة جيدة لم تبنها '),
(9847, 'Deuteronomy', 5, 6, 11, ' وبيوت مملوءة كل خير لم تملأها ، وأبآر محفورة لم تحفرها ، وكروم وزيتون لم تغرسها ، وأكلت وشبعت '),
(9848, 'Deuteronomy', 5, 6, 12, ' فاحترز لئلا تنسى الرب الذي أخرجك من أرض مصر من بيت العبودية '),
(9849, 'Deuteronomy', 5, 6, 13, ' الرب إلهك تتقي ، وإياه تعبد ، وباسمه تحلف '),
(9850, 'Deuteronomy', 5, 6, 14, ' لا تسيروا وراء آلهة أخرى من آلهة الأمم التي حولكم '),
(9851, 'Deuteronomy', 5, 6, 15, ' لأن الرب إلهكم إله غيور في وسطكم ، لئلا يحمى غضب الرب إلهكم عليكم فيبيدكم عن وجه الأرض '),
(9852, 'Deuteronomy', 5, 6, 16, ' لا تجربوا الرب إلهكم كما جربتموه في مسة '),
(9853, 'Deuteronomy', 5, 6, 17, ' احفظوا وصايا الرب إلهكم وشهاداته وفرائضه التي أوصاكم بها '),
(9854, 'Deuteronomy', 5, 6, 18, ' واعمل الصالح والحسن في عيني الرب ، لكي يكون لك خير ، وتدخل وتمتلك الأرض الجيدة التي حلف الرب لآبائك '),
(9855, 'Deuteronomy', 5, 6, 19, ' أن ينفي جميع أعدائك من أمامك . كما تكلم الرب '),
(9856, 'Deuteronomy', 5, 6, 20, ' إذا سألك ابنك غدا قائلا : ما هي الشهادات والفرائض والأحكام التي أوصاكم بها الرب إلهنا '),
(9857, 'Deuteronomy', 5, 6, 21, ' تقول لابنك : كنا عبيدا لفرعون في مصر ، فأخرجنا الرب من مصر بيد شديدة '),
(9858, 'Deuteronomy', 5, 6, 22, ' وصنع الرب آيات وعجائب عظيمة ورديئة بمصر ، بفرعون وجميع بيته أمام أعيننا '),
(9859, 'Deuteronomy', 5, 6, 23, ' وأخرجنا من هناك لكي يأتي بنا ويعطينا الأرض التي حلف لآبائنا '),
(9860, 'Deuteronomy', 5, 6, 24, ' فأمرنا الرب أن نعمل جميع هذه الفرائض ونتقي الرب إلهنا ، ليكون لنا خير كل الأيام ، ويستبقينا كما في هذا اليوم '),
(9861, 'Deuteronomy', 5, 6, 25, ' وإنه يكون لنا بر إذا حفظنا جميع هذه الوصايا لنعملها أمام الرب إلهنا كما أوصانا '),
(9862, 'Deuteronomy', 5, 7, 1, ' متى أتى بك الرب إلهك إلى الأرض التي أنت داخل إليها لتمتلكها ، وطرد شعوبا كثيرة من أمامك : الحثيين والجرجاشيين والأموريين والكنعانيين والفرزيين والحويين واليبوسيين ، سبع شعوب أكثر وأعظم منك '),
(9863, 'Deuteronomy', 5, 7, 2, ' ودفعهم الرب إلهك أمامك ، وضربتهم ، فإنك تحرمهم . لا تقطع لهم عهدا ، ولا تشفق عليهم '),
(9864, 'Deuteronomy', 5, 7, 3, ' ولا تصاهرهم . بنتك لا تعط لابنه ، وبنته لا تأخذ لابنك '),
(9865, 'Deuteronomy', 5, 7, 4, ' لأنه يرد ابنك من ورائي فيعبد آلهة أخرى ، فيحمى غضب الرب عليكم ويهلككم سريعا '),
(9866, 'Deuteronomy', 5, 7, 5, ' ولكن هكذا تفعلون بهم : تهدمون مذابحهم ، وتكسرون أنصابهم ، وتقطعون سواريهم ، وتحرقون تماثيلهم بالنار '),
(9867, 'Deuteronomy', 5, 7, 6, ' لأنك أنت شعب مقدس للرب إلهك . إياك قد اختار الرب إلهك لتكون له شعبا أخص من جميع الشعوب الذين على وجه الأرض '),
(9868, 'Deuteronomy', 5, 7, 7, ' ليس من كونكم أكثر من سائر الشعوب ، التصق الرب بكم واختاركم ، لأنكم أقل من سائر الشعوب '),
(9869, 'Deuteronomy', 5, 7, 8, ' بل من محبة الرب إياكم ، وحفظه القسم الذي أقسم لآبائكم ، أخرجكم الرب بيد شديدة وفداكم من بيت العبودية من يد فرعون ملك مصر '),
(9870, 'Deuteronomy', 5, 7, 9, ' فاعلم أن الرب إلهك هو الله ، الإله الأمين ، الحافظ العهد والإحسان للذين يحبونه ويحفظون وصاياه إلى ألف جيل '),
(9871, 'Deuteronomy', 5, 7, 10, ' والمجازي الذين يبغضونه بوجوههم ليهلكهم . لا يمهل من يبغضه . بوجهه يجازيه '),
(9872, 'Deuteronomy', 5, 7, 11, ' فاحفظ الوصايا والفرائض والأحكام التي أنا أوصيك اليوم لتعملها '),
(9873, 'Deuteronomy', 5, 7, 12, ' ومن أجل أنكم تسمعون هذه الأحكام وتحفظون وتعملونها ، يحفظ لك الرب إلهك العهد والإحسان اللذين أقسم لآبائك '),
(9874, 'Deuteronomy', 5, 7, 13, ' ويحبك ويباركك ويكثرك ويبارك ثمرة بطنك وثمرة أرضك : قمحك وخمرك وزيتك ونتاج بقرك وإناث غنمك ، على الأرض التي أقسم لآبائك أنه يعطيك إياها '),
(9875, 'Deuteronomy', 5, 7, 14, ' مباركا تكون فوق جميع الشعوب . لا يكون عقيم ولا عاقر فيك ولا في بهائمك '),
(9876, 'Deuteronomy', 5, 7, 15, ' ويرد الرب عنك كل مرض ، وكل أدواء مصر الرديئة التي عرفتها لا يضعها عليك ، بل يجعلها على كل مبغضيك '),
(9877, 'Deuteronomy', 5, 7, 16, ' وتأكل كل الشعوب الذين الرب إلهك يدفع إليك . لا تشفق عيناك عليهم ولا تعبد آلهتهم ، لأن ذلك شرك لك '),
(9878, 'Deuteronomy', 5, 7, 17, ' إن قلت في قلبك : هؤلاء الشعوب أكثر مني . كيف أقدر أن أطردهم '),
(9879, 'Deuteronomy', 5, 7, 18, ' فلا تخف منهم . اذكر ما فعله الرب إلهك بفرعون وبجميع المصريين '),
(9880, 'Deuteronomy', 5, 7, 19, ' التجارب العظيمة التي أبصرتها عيناك ، والآيات والعجائب واليد الشديدة والذراع الرفيعة التي بها أخرجك الرب إلهك . هكذا يفعل الرب إلهك بجميع الشعوب التي أنت خائف من وجهها '),
(9881, 'Deuteronomy', 5, 7, 20, ' والزنابير أيضا يرسلها الرب إلهك عليهم حتى يفنى الباقون والمختفون من أمامك '),
(9882, 'Deuteronomy', 5, 7, 21, ' لا ترهب وجوههم ، لأن الرب إلهك في وسطك إله عظيم ومخوف '),
(9883, 'Deuteronomy', 5, 7, 22, ' ولكن الرب إلهك يطرد هؤلاء الشعوب من أمامك قليلا قليلا . لا تستطيع أن تفنيهم سريعا ، لئلا تكثر عليك وحوش البرية '),
(9884, 'Deuteronomy', 5, 7, 23, ' ويدفعهم الرب إلهك أمامك ويوقع بهم اضطرابا عظيما حتى يفنوا '),
(9885, 'Deuteronomy', 5, 7, 24, ' ويدفع ملوكهم إلى يدك ، فتمحو اسمهم من تحت السماء . لا يقف إنسان في وجهك حتى تفنيهم '),
(9886, 'Deuteronomy', 5, 7, 25, ' وتماثيل آلهتهم تحرقون بالنار . لا تشته فضة ولا ذهبا مما عليها لتأخذ لك ، لئلا تصاد به لأنه رجس عند الرب إلهك '),
(9887, 'Deuteronomy', 5, 7, 26, ' ولا تدخل رجسا إلى بيتك لئلا تكون محرما مثله . تستقبحه وتكرهه لأنه محرم '),
(9888, 'Deuteronomy', 5, 8, 1, ' جميع الوصايا التي أنا أوصيكم بها اليوم تحفظون لتعملوها ، لكي تحيوا وتكثروا وتدخلوا وتمتلكوا الأرض التي أقسم الرب لآبائكم '),
(9889, 'Deuteronomy', 5, 8, 2, ' وتتذكر كل الطريق التي فيها سار بك الرب إلهك هذه الأربعين سنة في القفر ، لكي يذلك ويجربك ليعرف ما في قلبك : أتحفظ وصاياه أم لا '),
(9890, 'Deuteronomy', 5, 8, 3, ' فأذلك وأجاعك وأطعمك المن الذي لم تكن تعرفه ولا عرفه آباؤك ، لكي يعلمك أنه ليس بالخبز وحده يحيا الإنسان ، بل بكل ما يخرج من فم الرب يحيا الإنسان '),
(9891, 'Deuteronomy', 5, 8, 4, ' ثيابك لم تبل عليك ، ورجلك لم تتورم هذه الأربعين سنة '),
(9892, 'Deuteronomy', 5, 8, 5, ' فاعلم في قلبك أنه كما يؤدب الإنسان ابنه قد أدبك الرب إلهك '),
(9893, 'Deuteronomy', 5, 8, 6, ' واحفظ وصايا الرب إلهك لتسلك في طرقه وتتقيه '),
(9894, 'Deuteronomy', 5, 8, 7, ' لأن الرب إلهك آت بك إلى أرض جيدة . أرض أنهار من عيون ، وغمار تنبع في البقاع والجبال '),
(9895, 'Deuteronomy', 5, 8, 8, ' أرض حنطة وشعير وكرم وتين ورمان . أرض زيتون زيت ، وعسل '),
(9896, 'Deuteronomy', 5, 8, 9, ' أرض ليس بالمسكنة تأكل فيها خبزا ، ولا يعوزك فيها شيء . أرض حجارتها حديد ، ومن جبالها تحفر نحاسا '),
(9897, 'Deuteronomy', 5, 8, 10, ' فمتى أكلت وشبعت تبارك الرب إلهك لأجل الأرض الجيدة التي أعطاك '),
(9898, 'Deuteronomy', 5, 8, 11, ' احترز من أن تنسى الرب إلهك ولا تحفظ وصاياه وأحكامه وفرائضه التي أنا أوصيك بها اليوم '),
(9899, 'Deuteronomy', 5, 8, 12, ' لئلا إذا أكلت وشبعت وبنيت بيوتا جيدة وسكنت '),
(9900, 'Deuteronomy', 5, 8, 13, ' وكثرت بقرك وغنمك ، وكثرت لك الفضة والذهب ، وكثر كل ما لك '),
(9901, 'Deuteronomy', 5, 8, 14, ' يرتفع قلبك وتنسى الرب إلهك الذي أخرجك من أرض مصر من بيت العبودية '),
(9902, 'Deuteronomy', 5, 8, 15, ' الذي سار بك في القفر العظيم المخوف ، مكان حيات محرقة وعقارب وعطش حيث ليس ماء . الذي أخرج لك ماء من صخرة الصوان '),
(9903, 'Deuteronomy', 5, 8, 16, ' الذي أطعمك في البرية المن الذي لم يعرفه آباؤك ، لكي يذلك ويجربك ، لكي يحسن إليك في آخرتك '),
(9904, 'Deuteronomy', 5, 8, 17, ' ولئلا تقول في قلبك : قوتي وقدرة يدي اصطنعت لي هذه الثروة '),
(9905, 'Deuteronomy', 5, 8, 18, ' بل اذكر الرب إلهك ، أنه هو الذي يعطيك قوة لاصطناع الثروة ، لكي يفي بعهده الذي أقسم لآبائك كما في هذا اليوم '),
(9906, 'Deuteronomy', 5, 8, 19, ' وإن نسيت الرب إلهك ، وذهبت وراء آلهة أخرى وعبدتها وسجدت لها ، أشهد عليكم اليوم أنكم تبيدون لا محالة '),
(9907, 'Deuteronomy', 5, 8, 20, ' كالشعوب الذين يبيدهم الرب من أمامكم كذلك تبيدون ، لأجل أنكم لم تسمعوا لقول الرب إلهكم '),
(9908, 'Deuteronomy', 5, 9, 1, ' اسمع يا إسرائيل ، أنت اليوم عابر الأردن لكي تدخل وتمتلك شعوبا أكبر وأعظم منك ، ومدنا عظيمة ومحصنة إلى السماء '),
(9909, 'Deuteronomy', 5, 9, 2, ' قوما عظاما وطوالا ، بني عناق الذين عرفتهم وسمعت : من يقف في وجه بني عناق '),
(9910, 'Deuteronomy', 5, 9, 3, ' فاعلم اليوم أن الرب إلهك هو العابر أمامك نارا آكلة . هو يبيدهم ويذلهم أمامك ، فتطردهم وتهلكهم سريعا كما كلمك الرب '),
(9911, 'Deuteronomy', 5, 9, 4, ' لا تقل في قلبك حين ينفيهم الرب إلهك من أمامك قائلا : لأجل بري أدخلني الرب لأمتلك هذه الأرض . ولأجل إثم هؤلاء الشعوب يطردهم الرب من أمامك '),
(9912, 'Deuteronomy', 5, 9, 5, ' ليس لأجل برك وعدالة قلبك تدخل لتمتلك أرضهم ، بل لأجل إثم أولئك الشعوب يطردهم الرب إلهك من أمامك ، ولكي يفي بالكلام الذي أقسم الرب عليه لآبائك إبراهيم وإسحاق ويعقوب '),
(9913, 'Deuteronomy', 5, 9, 6, ' فاعلم أنه ليس لأجل برك يعطيك الرب إلهك هذه الأرض الجيدة لتمتلكها ، لأنك شعب صلب الرقبة '),
(9914, 'Deuteronomy', 5, 9, 7, ' اذكر . لا تنس كيف أسخطت الرب إلهك في البرية . من اليوم الذي خرجت فيه من أرض مصر حتى أتيتم إلى هذا المكان كنتم تقاومون الرب '),
(9915, 'Deuteronomy', 5, 9, 8, ' حتى في حوريب أسخطتم الرب ، فغضب الرب عليكم ليبيدكم '),
(9916, 'Deuteronomy', 5, 9, 9, ' حين صعدت إلى الجبل لكي آخذ لوحي الحجر ، لوحي العهد الذي قطعه الرب معكم ، أقمت في الجبل أربعين نهارا وأربعين ليلة لا آكل خبزا ولا أشرب ماء '),
(9917, 'Deuteronomy', 5, 9, 10, ' وأعطاني الرب لوحي الحجر المكتوبين بأصبع الله ، وعليهما مثل جميع الكلمات التي كلمكم بها الرب في الجبل من وسط النار في يوم الاجتماع '),
(9918, 'Deuteronomy', 5, 9, 11, ' وفي نهاية الأربعين نهارا والأربعين ليلة ، لما أعطاني الرب لوحي الحجر ، لوحي العهد '),
(9919, 'Deuteronomy', 5, 9, 12, ' قال الرب لي : قم انزل عاجلا من هنا ، لأنه قد فسد شعبك الذي أخرجته من مصر . زاغوا سريعا عن الطريق التي أوصيتهم . صنعوا لأنفسهم تمثالا مسبوكا '),
(9920, 'Deuteronomy', 5, 9, 13, ' وكلمني الرب قائلا : رأيت هذا الشعب وإذا هو شعب صلب الرقبة '),
(9921, 'Deuteronomy', 5, 9, 14, ' اتركني فأبيدهم وأمحو اسمهم من تحت السماء ، وأجعلك شعبا أعظم وأكثر منهم '),
(9922, 'Deuteronomy', 5, 9, 15, ' فانصرفت ونزلت من الجبل ، والجبل يشتعل بالنار ، ولوحا العهد في يدي '),
(9923, 'Deuteronomy', 5, 9, 16, ' فنظرت وإذا أنتم قد أخطأتم إلى الرب إلهكم ، وصنعتم لأنفسكم عجلا مسبوكا ، وزغتم سريعا عن الطريق التي أوصاكم بها الرب '),
(9924, 'Deuteronomy', 5, 9, 17, ' فأخذت اللوحين وطرحتهما من يدي وكسرتهما أمام أعينكم '),
(9925, 'Deuteronomy', 5, 9, 18, ' ثم سقطت أمام الرب كالأول أربعين نهارا وأربعين ليلة ، لا آكل خبزا ولا أشرب ماء ، من أجل كل خطاياكم التي أخطأتم بها بعملكم الشر أمام الرب لإغاظته '),
(9926, 'Deuteronomy', 5, 9, 19, ' لأني فزعت من الغضب والغيظ الذي سخطه الرب عليكم ليبيدكم . فسمع لي الرب تلك المرة أيضا '),
(9927, 'Deuteronomy', 5, 9, 20, ' وعلى هارون غضب الرب جدا ليبيده . فصليت أيضا من أجل هارون في ذلك الوقت '),
(9928, 'Deuteronomy', 5, 9, 21, ' وأما خطيتكم ، العجل الذي صنعتموه ، فأخذته وأحرقته بالنار ، ورضضته وطحنته جيدا حتى نعم كالغبار . ثم طرحت غباره في النهر المنحدر من الجبل '),
(9929, 'Deuteronomy', 5, 9, 22, ' وفي تبعيرة ومسة وقبروت هتأوة أسخطتم الرب '),
(9930, 'Deuteronomy', 5, 9, 23, ' وحين أرسلكم الرب من قادش برنيع قائلا : اصعدوا امتلكوا الأرض التي أعطيتكم ، عصيتم قول الرب إلهكم ولم تصدقوه ولم تسمعوا لقوله '),
(9931, 'Deuteronomy', 5, 9, 24, ' قد كنتم تعصون الرب منذ يوم عرفتكم '),
(9932, 'Deuteronomy', 5, 9, 25, ' فسقطت أمام الرب الأربعين نهارا والأربعين ليلة التي سقطتها ، لأن الرب قال إنه يهلككم '),
(9933, 'Deuteronomy', 5, 9, 26, ' وصليت للرب وقلت : يا سيد الرب ، لا تهلك شعبك وميراثك الذي فديته بعظمتك ، الذي أخرجته من مصر بيد شديدة '),
(9934, 'Deuteronomy', 5, 9, 27, ' اذكر عبيدك إبراهيم وإسحاق ويعقوب . لا تلتفت إلى غلاظة هذا الشعب وإثمه وخطيته '),
(9935, 'Deuteronomy', 5, 9, 28, ' لئلا تقول الأرض التي أخرجتنا منها : لأجل أن الرب لم يقدر أن يدخلهم الأرض التي كلمهم عنها ، ولأجل أنه أبغضهم ، أخرجهم لكي يميتهم في البرية '),
(9936, 'Deuteronomy', 5, 9, 29, ' وهم شعبك وميراثك الذي أخرجته بقوتك العظيمة وبذراعك الرفيعة '),
(9937, 'Deuteronomy', 5, 10, 1, ' في ذلك الوقت قال لي الرب : انحت لك لوحين من حجر مثل الأولين ، واصعد إلي إلى الجبل ، واصنع لك تابوتا من خشب '),
(9938, 'Deuteronomy', 5, 10, 2, ' فأكتب على اللوحين الكلمات التي كانت على اللوحين الأولين اللذين كسرتهما ، وتضعهما في التابوت '),
(9939, 'Deuteronomy', 5, 25, 6, ' والبكر الذي تلده يقوم باسم أخيه الميت ، لئلا يمحى اسمه من إسرائيل '),
(9940, 'Deuteronomy', 5, 25, 7, ' وإن لم يرض الرجل أن يأخذ امرأة أخيه ، تصعد امرأة أخيه إلى الباب إلى الشيوخ وتقول : قد أبى أخو زوجي أن يقيم لأخيه اسما في إسرائيل . لم يشأ أن يقوم لي بواجب أخي الزوج '),
(9941, 'Deuteronomy', 5, 25, 8, ' فيدعوه شيوخ مدينته ويتكلمون معه . فإن أصر وقال : لا أرضى أن أتخذها '),
(9942, 'Deuteronomy', 5, 25, 9, ' تتقدم امرأة أخيه إليه أمام أعين الشيوخ ، وتخلع نعله من رجله ، وتبصق في وجهه ، وتصرح وتقول : هكذا يفعل بالرجل الذي لا يبني بيت أخيه '),
(9943, 'Deuteronomy', 5, 25, 10, ' فيدعى اسمه في إسرائيل بيت مخلوع النعل '),
(9944, 'Deuteronomy', 5, 25, 11, ' إذا تخاصم رجلان بعضهما بعضا ، رجل وأخوه ، وتقدمت امرأة أحدهما لكي تخلص رجلها من يد ضاربه ، ومدت يدها وأمسكت بعورته '),
(9945, 'Deuteronomy', 5, 25, 12, ' فاقطع يدها ، ولا تشفق عينك '),
(9946, 'Deuteronomy', 5, 25, 13, ' لا يكن لك في كيسك أوزان مختلفة كبيرة وصغيرة '),
(9947, 'Deuteronomy', 5, 25, 14, ' لا يكن لك في بيتك مكاييل مختلفة كبيرة وصغيرة '),
(9948, 'Deuteronomy', 5, 25, 15, ' وزن صحيح وحق يكون لك ، ومكيال صحيح وحق يكون لك ، لكي تطول أيامك على الأرض التي يعطيك الرب إلهك '),
(9949, 'Deuteronomy', 5, 25, 16, ' لأن كل من عمل ذلك ، كل من عمل غشا ، مكروه لدى الرب إلهك ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(9950, 'Deuteronomy', 5, 25, 17, ' اذكر ما فعله بك عماليق في الطريق عند خروجك من مصر '),
(9951, 'Deuteronomy', 5, 25, 18, ' كيف لاقاك في الطريق وقطع من مؤخرك كل المستضعفين وراءك ، وأنت كليل ومتعب ، ولم يخف الله '),
(9952, 'Deuteronomy', 5, 25, 19, ' فمتى أراحك الرب إلهك من جميع أعدائك حولك في الأرض التي يعطيك الرب إلهك نصيبا لكي تمتلكها ، تمحو ذكر عماليق من تحت السماء . لا تنس '),
(9953, 'Deuteronomy', 5, 26, 1, ' ومتى أتيت إلى الأرض التي يعطيك الرب إلهك نصيبا وامتلكتها وسكنت فيها '),
(9954, 'Deuteronomy', 5, 26, 2, ' فتأخذ من أول كل ثمر الأرض الذي تحصل من أرضك التي يعطيك الرب إلهك وتضعه في سلة وتذهب إلى المكان الذي يختاره الرب إلهك ليحل اسمه فيه '),
(9955, 'Deuteronomy', 5, 26, 3, ' وتأتي إلى الكاهن الذي يكون في تلك الأيام وتقول له : أعترف اليوم للرب إلهك أني قد دخلت الأرض التي حلف الرب لآبائنا أن يعطينا إياها '),
(9956, 'Deuteronomy', 5, 26, 4, ' فيأخذ الكاهن السلة من يدك ويضعها أمام مذبح الرب إلهك '),
(9957, 'Deuteronomy', 5, 26, 5, ' ثم تصرح وتقول أمام الرب إلهك : أراميا تائها كان أبي ، فانحدر إلى مصر وتغرب هناك في نفر قليل ، فصار هناك أمة كبيرة وعظيمة وكثيرة '),
(9958, 'Deuteronomy', 5, 26, 6, ' فأساء إلينا المصريون ، وثقلوا علينا وجعلوا علينا عبودية قاسية '),
(9959, 'Deuteronomy', 5, 26, 7, ' فلما صرخنا إلى الرب إله آبائنا سمع الرب صوتنا ، ورأى مشقتنا وتعبنا وضيقنا '),
(9960, 'Deuteronomy', 5, 26, 8, ' فأخرجنا الرب من مصر بيد شديدة وذراع رفيعة ومخاوف عظيمة وآيات وعجائب '),
(9961, 'Deuteronomy', 5, 26, 9, ' وأدخلنا هذا المكان ، وأعطانا هذه الأرض ، أرضا تفيض لبنا وعسلا '),
(9962, 'Deuteronomy', 5, 26, 10, ' فالآن هأنذا قد أتيت بأول ثمر الأرض التي أعطيتني يارب . ثم تضعه أمام الرب إلهك ، وتسجد أمام الرب إلهك '),
(9963, 'Deuteronomy', 5, 26, 11, ' وتفرح بجميع الخير الذي أعطاه الرب إلهك لك ولبيتك ، أنت واللاوي والغريب الذي في وسطك '),
(9964, 'Deuteronomy', 5, 26, 12, ' متى فرغت من تعشير كل عشور محصولك ، في السنة الثالثة ، سنة العشور ، وأعطيت اللاوي والغريب واليتيم والأرملة فأكلوا في أبوابك وشبعوا '),
(9965, 'Deuteronomy', 5, 26, 13, ' تقول أمام الرب إلهك : قد نزعت المقدس من البيت ، وأيضا أعطيته للاوي والغريب واليتيم والأرملة ، حسب كل وصيتك التي أوصيتني بها . لم أتجاوز وصاياك ولا نسيتها '),
(9966, 'Deuteronomy', 5, 26, 14, ' لم آكل منه في حزني ، ولا أخذت منه في نجاسة ، ولا أعطيت منه لأجل ميت ، بل سمعت لصوت الرب إلهي وعملت حسب كل ما أوصيتني '),
(9967, 'Deuteronomy', 5, 26, 15, ' اطلع من مسكن قدسك ، من السماء ، وبارك شعبك إسرائيل والأرض التي أعطيتنا ، كما حلفت لآبائنا ، أرضا تفيض لبنا وعسلا '),
(9968, 'Deuteronomy', 5, 26, 16, ' هذا اليوم قد أمرك الرب إلهك أن تعمل بهذه الفرائض والأحكام ، فاحفظ واعمل بها من كل قلبك ومن كل نفسك '),
(9969, 'Deuteronomy', 5, 26, 17, ' قد واعدت الرب اليوم أن يكون لك إلها ، وأن تسلك في طرقه وتحفظ فرائضه ووصاياه وأحكامه وتسمع لصوته '),
(9970, 'Deuteronomy', 5, 26, 18, ' وواعدك الرب اليوم أن تكون له شعبا خاصا ، كما قال لك ، وتحفظ جميع وصاياه '),
(9971, 'Deuteronomy', 5, 26, 19, ' وأن يجعلك مستعليا على جميع القبائل التي عملها في الثناء والاسم والبهاء ، وأن تكون شعبا مقدسا للرب إلهك ، كما قال '),
(9972, 'Deuteronomy', 5, 27, 1, ' وأوصى موسى وشيوخ إسرائيل الشعب قائلا : احفظوا جميع الوصايا التي أنا أوصيكم بها اليوم '),
(9973, 'Deuteronomy', 5, 27, 2, ' فيوم تعبرون الأردن إلى الأرض التي يعطيك الرب إلهك ، تقيم لنفسك حجارة كبيرة وتشيدها بالشيد '),
(9974, 'Deuteronomy', 5, 27, 3, ' وتكتب عليها جميع كلمات هذا الناموس ، حين تعبر لكي تدخل الأرض التي يعطيك الرب إلهك ، أرضا تفيض لبنا وعسلا ، كما قال لك الرب إله آبائك '),
(9975, 'Deuteronomy', 5, 27, 4, ' حين تعبرون الأردن ، تقيمون هذه الحجارة التي أنا أوصيكم بها اليوم في جبل عيبال ، وتكلسها بالكلس '),
(9976, 'Deuteronomy', 5, 27, 5, ' وتبني هناك مذبحا للرب إلهك ، مذبحا من حجارة لا ترفع عليها حديدا '),
(9977, 'Deuteronomy', 5, 27, 6, ' من حجارة صحيحة تبني مذبح الرب إلهك ، وتصعد عليه محرقات للرب إلهك '),
(9978, 'Deuteronomy', 5, 27, 7, ' وتذبح ذبائح سلامة ، وتأكل هناك وتفرح أمام الرب إلهك '),
(9979, 'Deuteronomy', 5, 27, 8, ' وتكتب على الحجارة جميع كلمات هذا الناموس نقشا جيدا '),
(9980, 'Deuteronomy', 5, 27, 9, ' ثم كلم موسى والكهنة اللاويون جميع إسرائيل قائلين : انصت واسمع يا إسرائيل . اليوم صرت شعبا للرب إلهك '),
(9981, 'Deuteronomy', 5, 27, 10, ' فاسمع لصوت الرب إلهك واعمل بوصاياه وفرائضه التي أنا أوصيك بها اليوم '),
(9982, 'Deuteronomy', 5, 27, 11, ' وأوصى موسى الشعب في ذلك اليوم قائلا '),
(9983, 'Deuteronomy', 5, 27, 12, ' هؤلاء يقفون على جبل جرزيم لكي يباركوا الشعب حين تعبرون الأردن : شمعون ولاوي ويهوذا ويساكر ويوسف وبنيامين '),
(9984, 'Deuteronomy', 5, 27, 13, ' وهؤلاء يقفون على جبل عيبال للعنة : رأوبين وجاد وأشير وزبولون ودان ونفتالي '),
(9985, 'Deuteronomy', 5, 27, 14, ' فيصرح اللاويون ويقولون لجميع قوم إسرائيل بصوت عال '),
(9986, 'Deuteronomy', 5, 27, 15, ' ملعون الإنسان الذي يصنع تمثالا منحوتا أو مسبوكا ، رجسا لدى الرب عمل يدي نحات ، ويضعه في الخفاء . ويجيب جميع الشعب ويقولون : آمين '),
(9987, 'Deuteronomy', 5, 27, 16, ' ملعون من يستخف بأبيه أو أمه . ويقول جميع الشعب : آمين '),
(9988, 'Deuteronomy', 5, 27, 17, ' ملعون من ينقل تخم صاحبه . ويقول جميع الشعب : آمين '),
(9989, 'Deuteronomy', 5, 27, 18, ' ملعون من يضل الأعمى عن الطريق . ويقول جميع الشعب : آمين '),
(9990, 'Deuteronomy', 5, 27, 19, ' ملعون من يعوج حق الغريب واليتيم والأرملة . ويقول جميع الشعب : آمين '),
(9991, 'Deuteronomy', 5, 27, 20, ' ملعون من يضطجع مع امرأة أبيه ، لأنه يكشف ذيل أبيه . ويقول جميع الشعب : آمين '),
(9992, 'Deuteronomy', 5, 27, 21, ' ملعون من يضطجع مع بهيمة ما . ويقول جميع الشعب : آمين '),
(9993, 'Deuteronomy', 5, 27, 22, ' ملعون من يضطجع مع أخته بنت أبيه أو بنت أمه . ويقول جميع الشعب : آمين '),
(9994, 'Deuteronomy', 5, 27, 23, ' ملعون من يضطجع مع حماته . ويقول جميع الشعب : آمين '),
(9995, 'Deuteronomy', 5, 27, 24, ' ملعون من يقتل قريبه في الخفاء . ويقول جميع الشعب : آمين '),
(9996, 'Deuteronomy', 5, 27, 25, ' ملعون من يأخذ رشوة لكي يقتل نفس دم بريء . ويقول جميع الشعب : آمين '),
(9997, 'Deuteronomy', 5, 27, 26, ' ملعون من لا يقيم كلمات هذا الناموس ليعمل بها . ويقول جميع الشعب : آمين '),
(9998, 'Deuteronomy', 5, 28, 1, ' وإن سمعت سمعا لصوت الرب إلهك لتحرص أن تعمل بجميع وصاياه التي أنا أوصيك بها اليوم ، يجعلك الرب إلهك مستعليا على جميع قبائل الأرض '),
(9999, 'Deuteronomy', 5, 28, 2, ' وتأتي عليك جميع هذه البركات وتدركك ، إذا سمعت لصوت الرب إلهك '),
(10000, 'Deuteronomy', 5, 28, 3, ' مباركا تكون في المدينة ، ومباركا تكون في الحقل '),
(10001, 'Deuteronomy', 5, 28, 4, ' ومباركة تكون ثمرة بطنك وثمرة أرضك وثمرة بهائمك ، نتاج بقرك وإناث غنمك '),
(10002, 'Deuteronomy', 5, 28, 5, ' مباركة تكون سلتك ومعجنك '),
(10003, 'Deuteronomy', 5, 28, 6, ' مباركا تكون في دخولك ، ومباركا تكون في خروجك '),
(10004, 'Deuteronomy', 5, 28, 7, ' يجعل الرب أعداءك القائمين عليك منهزمين أمامك . في طريق واحدة يخرجون عليك ، وفي سبع طرق يهربون أمامك '),
(10005, 'Deuteronomy', 5, 28, 8, ' يأمر لك الرب بالبركة في خزائنك وفي كل ما تمتد إليه يدك ، ويباركك في الأرض التي يعطيك الرب إلهك '),
(10006, 'Deuteronomy', 5, 28, 9, ' يقيمك الرب لنفسه شعبا مقدسا كما حلف لك ، إذا حفظت وصايا الرب إلهك وسلكت في طرقه '),
(10007, 'Deuteronomy', 5, 28, 10, ' فيرى جميع شعوب الأرض أن اسم الرب قد سمي عليك ويخافون منك '),
(10008, 'Deuteronomy', 5, 28, 11, ' ويزيدك الرب خيرا في ثمرة بطنك وثمرة بهائمك وثمرة أرضك على الأرض التي حلف الرب لآبائك أن يعطيك '),
(10009, 'Deuteronomy', 5, 28, 12, ' يفتح لك الرب كنزه الصالح ، السماء ، ليعطي مطر أرضك في حينه ، وليبارك كل عمل يدك ، فتقرض أمما كثيرة وأنت لا تقترض '),
(10010, 'Deuteronomy', 5, 28, 13, ' ويجعلك الرب رأسا لا ذنبا ، وتكون في الارتفاع فقط ولا تكون في الانحطاط ، إذا سمعت لوصايا الرب إلهك التي أنا أوصيك بها اليوم ، لتحفظ وتعمل '),
(10011, 'Deuteronomy', 5, 28, 14, ' ولا تزيغ عن جميع الكلمات التي أنا أوصيك بها اليوم يمينا أو شمالا ، لكي تذهب وراء آلهة أخرى لتعبدها '),
(10012, 'Deuteronomy', 5, 12, 23, ' لكن احترز أن لا تأكل الدم ، لأن الدم هو النفس . فلا تأكل النفس مع اللحم '),
(10013, 'Deuteronomy', 5, 12, 24, ' لا تأكله . على الأرض تسفكه كالماء '),
(10014, 'Deuteronomy', 5, 12, 25, ' لا تأكله لكي يكون لك ولأولادك من بعدك خير ، إذا عملت الحق في عيني الرب '),
(10015, 'Deuteronomy', 5, 12, 26, ' وأما أقداسك التي لك ونذورك ، فتحملها وتذهب إلى المكان الذي يختاره الرب '),
(10016, 'Deuteronomy', 5, 12, 27, ' فتعمل محرقاتك : اللحم والدم على مذبح الرب إلهك . وأما ذبائحك فيسفك دمها على مذبح الرب إلهك ، واللحم تأكله '),
(10017, 'Deuteronomy', 5, 12, 28, ' احفظ واسمع جميع هذه الكلمات التي أنا أوصيك بها لكي يكون لك ولأولادك من بعدك خير إلى الأبد ، إذا عملت الصالح والحق في عيني الرب إلهك '),
(10018, 'Deuteronomy', 5, 12, 29, ' متى قرض الرب إلهك من أمامك الأمم الذين أنت ذاهب إليهم لترثهم ، وورثتهم وسكنت أرضهم '),
(10019, 'Deuteronomy', 5, 12, 30, ' فاحترز من أن تصاد وراءهم من بعد ما بادوا من أمامك ، ومن أن تسأل عن آلهتهم قائلا : كيف عبد هؤلاء الأمم آلهتهم ، فأنا أيضا أفعل هكذا '),
(10020, 'Deuteronomy', 5, 12, 31, ' لا تعمل هكذا للرب إلهك ، لأنهم قد عملوا لآلهتهم كل رجس لدى الرب مما يكرهه ، إذ أحرقوا حتى بنيهم وبناتهم بالنار لآلهتهم '),
(10021, 'Deuteronomy', 5, 12, 32, ' كل الكلام الذي أوصيكم به احرصوا لتعملوه . لا تزد عليه ولا تنقص منه '),
(10022, 'Deuteronomy', 5, 13, 1, ' إذا قام في وسطك نبي أو حالم حلما ، وأعطاك آية أو أعجوبة '),
(10023, 'Deuteronomy', 5, 13, 2, ' ولو حدثت الآية أو الأعجوبة التي كلمك عنها قائلا : لنذهب وراء آلهة أخرى لم تعرفها ونعبدها '),
(10024, 'Deuteronomy', 5, 13, 3, ' فلا تسمع لكلام ذلك النبي أو الحالم ذلك الحلم ، لأن الرب إلهكم يمتحنكم لكي يعلم هل تحبون الرب إلهكم من كل قلوبكم ومن كل أنفسكم '),
(10025, 'Deuteronomy', 5, 13, 4, ' وراء الرب إلهكم تسيرون ، وإياه تتقون ، ووصاياه تحفظون ، وصوته تسمعون ، وإياه تعبدون ، وبه تلتصقون '),
(10026, 'Deuteronomy', 5, 13, 5, ' وذلك النبي أو الحالم ذلك الحلم يقتل ، لأنه تكلم بالزيغ من وراء الرب إلهكم الذي أخرجكم من أرض مصر ، وفداكم من بيت العبودية ، لكي يطوحكم عن الطريق التي أمركم الرب إلهكم أن تسلكوا فيها . فتنزعون الشر من بينكم '),
(10027, 'Deuteronomy', 5, 13, 6, ' وإذا أغواك سرا أخوك ابن أمك ، أو ابنك أو ابنتك أو امرأة حضنك ، أو صاحبك الذي مثل نفسك قائلا : نذهب ونعبد آلهة أخرى لم تعرفها أنت ولا آباؤك '),
(10028, 'Deuteronomy', 5, 13, 7, ' من آلهة الشعوب الذين حولك ، القريبين منك أو البعيدين عنك ، من أقصاء الأرض إلى أقصائها '),
(10029, 'Deuteronomy', 5, 13, 8, ' فلا ترض منه ولا تسمع له ولا تشفق عينك عليه ، ولا ترق له ولا تستره '),
(10030, 'Deuteronomy', 5, 13, 9, ' بل قتلا تقتله . يدك تكون عليه أولا لقتله ، ثم أيدي جميع الشعب أخيرا '),
(10031, 'Deuteronomy', 5, 13, 10, ' ترجمه بالحجارة حتى يموت ، لأنه التمس أن يطوحك عن الرب إلهك الذي أخرجك من أرض مصر من بيت العبودية '),
(10032, 'Deuteronomy', 5, 13, 11, ' فيسمع جميع إسرائيل ويخافون ، ولا يعودون يعملون مثل هذا الأمر الشرير في وسطك '),
(10033, 'Deuteronomy', 5, 13, 12, ' إن سمعت عن إحدى مدنك التي يعطيك الرب إلهك لتسكن فيها قولا '),
(10034, 'Deuteronomy', 5, 13, 13, ' قد خرج أناس بنو لئيم من وسطك وطوحوا سكان مدينتهم قائلين : نذهب ونعبد آلهة أخرى لم تعرفوها '),
(10035, 'Deuteronomy', 5, 13, 14, ' وفحصت وفتشت وسألت جيدا وإذا الأمر صحيح وأكيد ، قد عمل ذلك الرجس في وسطك '),
(10036, 'Deuteronomy', 5, 13, 15, ' فضربا تضرب سكان تلك المدينة بحد السيف ، وتحرمها بكل ما فيها مع بهائمها بحد السيف '),
(10037, 'Deuteronomy', 5, 13, 16, ' تجمع كل أمتعتها إلى وسط ساحتها ، وتحرق بالنار المدينة وكل أمتعتها كاملة للرب إلهك ، فتكون تلا إلى الأبد لا تبنى بعد '),
(10038, 'Deuteronomy', 5, 13, 17, ' ولا يلتصق بيدك شيء من المحرم ، لكي يرجع الرب من حمو غضبه ، ويعطيك رحمة . يرحمك ويكثرك كما حلف لآبائك '),
(10039, 'Deuteronomy', 5, 13, 18, ' إذا سمعت لصوت الرب إلهك لتحفظ جميع وصاياه التي أنا أوصيك بها اليوم ، لتعمل الحق في عيني الرب إلهك '),
(10040, 'Deuteronomy', 5, 14, 1, ' أنتم أولاد للرب إلهكم . لا تخمشوا أجسامكم ، ولا تجعلوا قرعة بين أعينكم لأجل ميت '),
(10041, 'Deuteronomy', 5, 14, 2, ' لأنك شعب مقدس للرب إلهك ، وقد اختارك الرب لكي تكون له شعبا خاصا فوق جميع الشعوب الذين على وجه الأرض '),
(10042, 'Deuteronomy', 5, 14, 3, ' لا تأكل رجسا ما '),
(10043, 'Deuteronomy', 5, 14, 4, ' هذه هي البهائم التي تأكلونها : البقر والضأن والمعز '),
(10044, 'Deuteronomy', 5, 14, 5, ' والإيل والظبي واليحمور والوعل والرئم والثيتل والمهاة '),
(10045, 'Deuteronomy', 5, 14, 6, ' وكل بهيمة من البهائم تشق ظلفا وتقسمه ظلفين وتجتر فإياها تأكلون '),
(10046, 'Deuteronomy', 5, 14, 7, ' إلا هذه فلا تأكلوها ، مما يجتر ومما يشق الظلف المنقسم : الجمل والأرنب والوبر ، لأنها تجتر لكنها لا تشق ظلفا ، فهي نجسة لكم '),
(10047, 'Deuteronomy', 5, 14, 8, ' والخنزير لأنه يشق الظلف لكنه لا يجتر فهو نجس لكم . فمن لحمها لا تأكلوا وجثثها لا تلمسوا '),
(10048, 'Deuteronomy', 5, 14, 9, ' وهذا تأكلونه من كل ما في المياه : كل ما له زعانف وحرشف تأكلونه '),
(10049, 'Deuteronomy', 5, 14, 10, ' لكن كل ما ليس له زعانف وحرشف لا تأكلوه . إنه نجس لكم '),
(10050, 'Deuteronomy', 5, 14, 11, ' كل طير طاهر تأكلون '),
(10051, 'Deuteronomy', 5, 14, 12, ' وهذا ما لا تأكلون منه : النسر والأنوق والعقاب '),
(10052, 'Deuteronomy', 5, 14, 13, ' والحدأة والباشق والشاهين على أجناسه '),
(10053, 'Deuteronomy', 5, 14, 14, ' وكل غراب على أجناسه '),
(10054, 'Deuteronomy', 5, 14, 15, ' والنعامة والظليم والسأف والباز على أجناسه '),
(10055, 'Deuteronomy', 5, 14, 16, ' والبوم والكركي والبجع '),
(10056, 'Deuteronomy', 5, 14, 17, ' والقوق والرخم والغواص '),
(10057, 'Deuteronomy', 5, 14, 18, ' واللقلق والببغاء على أجناسه ، والهدهد والخفاش '),
(10058, 'Deuteronomy', 5, 14, 19, ' وكل دبيب الطير نجس لكم . لا يؤكل '),
(10059, 'Deuteronomy', 5, 14, 20, ' كل طير طاهر تأكلون '),
(10060, 'Deuteronomy', 5, 14, 21, ' لا تأكلوا جثة ما . تعطيها للغريب الذي في أبوابك فيأكلها أو يبيعها لأجنبي ، لأنك شعب مقدس للرب إلهك . لا تطبخ جديا بلبن أمه '),
(10061, 'Deuteronomy', 5, 14, 22, ' تعشيرا تعشر كل محصول زرعك الذي يخرج من الحقل سنة بسنة '),
(10062, 'Deuteronomy', 5, 14, 23, ' وتأكل أمام الرب إلهك ، في المكان الذي يختاره ليحل اسمه فيه ، عشر حنطتك وخمرك وزيتك ، وأبكار بقرك وغنمك ، لكي تتعلم أن تتقي الرب إلهك كل الأيام '),
(10063, 'Deuteronomy', 5, 14, 24, ' ولكن إذا طال عليك الطريق حتى لا تقدر أن تحمله . إذا كان بعيدا عليك المكان الذي يختاره الرب إلهك ليجعل اسمه فيه ، إذ يباركك الرب إلهك '),
(10064, 'Deuteronomy', 5, 14, 25, ' فبعه بفضة ، وصر الفضة في يدك واذهب إلى المكان الذي يختاره الرب إلهك '),
(10065, 'Deuteronomy', 5, 14, 26, ' وأنفق الفضة في كل ما تشتهي نفسك في البقر والغنم والخمر والمسكر وكل ما تطلب منك نفسك ، وكل هناك أمام الرب إلهك وافرح أنت وبيتك '),
(10066, 'Deuteronomy', 5, 14, 27, ' واللاوي الذي في أبوابك لا تتركه ، لأنه ليس له قسم ولا نصيب معك '),
(10067, 'Deuteronomy', 5, 14, 28, ' في آخر ثلاث سنين تخرج كل عشر محصولك في تلك السنة وتضعه في أبوابك '),
(10068, 'Deuteronomy', 5, 14, 29, ' فيأتي اللاوي ، لأنه ليس له قسم ولا نصيب معك ، والغريب واليتيم والأرملة الذين في أبوابك ، ويأكلون ويشبعون ، لكي يباركك الرب إلهك في كل عمل يدك الذي تعمل '),
(10069, 'Deuteronomy', 5, 15, 1, ' في آخر سبع سنين تعمل إبراء '),
(10070, 'Deuteronomy', 5, 15, 2, ' وهذا هو حكم الإبراء : يبرئ كل صاحب دين يده مما أقرض صاحبه . لا يطالب صاحبه ولا أخاه ، لأنه قد نودي بإبراء للرب '),
(10071, 'Deuteronomy', 5, 15, 3, ' الأجنبي تطالب ، وأما ما كان لك عند أخيك فتبرئه يدك منه '),
(10072, 'Deuteronomy', 5, 15, 4, ' إلا إن لم يكن فيك فقير . لأن الرب إنما يباركك في الأرض التي يعطيك الرب إلهك نصيبا لتمتلكها '),
(10073, 'Deuteronomy', 5, 15, 5, ' إذا سمعت صوت الرب إلهك لتحفظ وتعمل كل هذه الوصايا التي أنا أوصيك اليوم '),
(10074, 'Deuteronomy', 5, 15, 6, ' يباركك الرب إلهك كما قال لك . فتقرض أمما كثيرة وأنت لا تقترض ، وتتسلط على أمم كثيرة وهم عليك لا يتسلطون '),
(10075, 'Deuteronomy', 5, 15, 7, ' إن كان فيك فقير ، أحد من إخوتك في أحد أبوابك في أرضك التي يعطيك الرب إلهك ، فلا تقس قلبك ، ولا تقبض يدك عن أخيك الفقير '),
(10076, 'Deuteronomy', 5, 15, 8, ' بل افتح يدك له وأقرضه مقدار ما يحتاج إليه '),
(10077, 'Deuteronomy', 5, 15, 9, ' احترز من أن يكون مع قلبك كلام لئيم قائلا : قد قربت السنة السابعة ، سنة الإبراء ، وتسوء عينك بأخيك الفقير ولا تعطيه ، فيصرخ عليك إلى الرب فتكون عليك خطية '),
(10078, 'Deuteronomy', 5, 15, 10, ' أعطه ولا يسوء قلبك عندما تعطيه ، لأنه بسبب هذا الأمر يباركك الرب إلهك في كل أعمالك وجميع ما تمتد إليه يدك '),
(10079, 'Deuteronomy', 5, 15, 11, ' لأنه لا تفقد الفقراء من الأرض . لذلك أنا أوصيك قائلا : افتح يدك لأخيك المسكين والفقير في أرضك '),
(10080, 'Deuteronomy', 5, 15, 12, ' إذا بيع لك أخوك العبراني أو أختك العبرانية وخدمك ست سنين ، ففي السنة السابعة تطلقه حرا من عندك '),
(10081, 'Deuteronomy', 5, 28, 15, ' ولكن إن لم تسمع لصوت الرب إلهك لتحرص أن تعمل بجميع وصاياه وفرائضه التي أنا أوصيك بها اليوم ، تأتي عليك جميع هذه اللعنات وتدركك '),
(10082, 'Deuteronomy', 5, 28, 16, ' ملعونا تكون في المدينة وملعونا تكون في الحقل '),
(10083, 'Deuteronomy', 5, 28, 17, ' ملعونة تكون سلتك ومعجنك '),
(10084, 'Deuteronomy', 5, 28, 18, ' ملعونة تكون ثمرة بطنك وثمرة أرضك ، نتاج بقرك وإناث غنمك '),
(10085, 'Deuteronomy', 5, 28, 19, ' ملعونا تكون في دخولك ، وملعونا تكون في خروجك '),
(10086, 'Deuteronomy', 5, 28, 20, ' يرسل الرب عليك اللعن والاضطراب والزجر في كل ما تمتد إليه يدك لتعمله ، حتى تهلك وتفنى سريعا من أجل سوء أفعالك إذ تركتني '),
(10087, 'Deuteronomy', 5, 28, 21, ' يلصق بك الرب الوبأ حتى يبيدك عن الأرض التي أنت داخل إليها لكي تمتلكها '),
(10088, 'Deuteronomy', 5, 28, 22, ' يضربك الرب بالسل والحمى والبرداء والالتهاب والجفاف واللفح والذبول ، فتتبعك حتى تفنيك '),
(10089, 'Deuteronomy', 5, 28, 23, ' وتكون سماؤك التي فوق رأسك نحاسا ، والأرض التي تحتك حديدا '),
(10090, 'Deuteronomy', 5, 28, 24, ' ويجعل الرب مطر أرضك غبارا ، وترابا ينزل عليك من السماء حتى تهلك '),
(10091, 'Deuteronomy', 5, 28, 25, ' يجعلك الرب منهزما أمام أعدائك . في طريق واحدة تخرج عليهم ، وفي سبع طرق تهرب أمامهم ، وتكون قلقا في جميع ممالك الأرض '),
(10092, 'Deuteronomy', 5, 28, 26, ' وتكون جثتك طعاما لجميع طيور السماء ووحوش الأرض وليس من يزعجها '),
(10093, 'Deuteronomy', 5, 28, 27, ' يضربك الرب بقرحة مصر وبالبواسير والجرب والحكة حتى لا تستطيع الشفاء '),
(10094, 'Deuteronomy', 5, 28, 28, ' يضربك الرب بجنون وعمى وحيرة قلب '),
(10095, 'Deuteronomy', 5, 28, 29, ' فتتلمس في الظهر كما يتلمس الأعمى في الظلام ، ولا تنجح في طرقك بل لا تكون إلا مظلوما مغصوبا كل الأيام وليس مخلص '),
(10096, 'Deuteronomy', 5, 28, 30, ' تخطب امرأة ورجل آخر يضطجع معها . تبني بيتا ولا تسكن فيه . تغرس كرما ولا تستغله '),
(10097, 'Deuteronomy', 5, 28, 31, ' يذبح ثورك أمام عينيك ولا تأكل منه . يغتصب حمارك من أمام وجهك ولا يرجع إليك . تدفع غنمك إلى أعدائك وليس لك مخلص '),
(10098, 'Deuteronomy', 5, 28, 32, ' يسلم بنوك وبناتك لشعب آخر وعيناك تنظران إليهم طول النهار ، فتكلان وليس في يدك طائلة '),
(10099, 'Deuteronomy', 5, 28, 33, ' ثمر أرضك وكل تعبك يأكله شعب لا تعرفه ، فلا تكون إلا مظلوما ومسحوقا كل الأيام '),
(10100, 'Deuteronomy', 5, 28, 34, ' وتكون مجنونا من منظر عينيك الذي تنظر '),
(10101, 'Deuteronomy', 5, 28, 35, ' يضربك الرب بقرح خبيث على الركبتين وعلى الساقين ، حتى لا تستطيع الشفاء من أسفل قدمك إلى قمة رأسك '),
(10102, 'Deuteronomy', 5, 28, 36, ' يذهب بك الرب وبملكك الذي تقيمه عليك إلى أمة لم تعرفها أنت ولا آباؤك ، وتعبد هناك آلهة أخرى من خشب وحجر '),
(10103, 'Deuteronomy', 5, 28, 37, ' وتكون دهشا ومثلا وهزأة في جميع الشعوب الذين يسوقك الرب إليهم '),
(10104, 'Deuteronomy', 5, 28, 38, ' بذارا كثيرا تخرج إلى الحقل ، وقليلا تجمع ، لأن الجراد يأكله '),
(10105, 'Deuteronomy', 5, 28, 39, ' كروما تغرس وتشتغل ، وخمرا لا تشرب ولا تجني ، لأن الدود يأكلها '),
(10106, 'Deuteronomy', 5, 28, 40, ' يكون لك زيتون في جميع تخومك ، وبزيت لا تدهن ، لأن زيتونك ينتثر '),
(10107, 'Deuteronomy', 5, 28, 41, ' بنين وبنات تلد ولا يكونون لك ، لأنهم إلى السبي يذهبون '),
(10108, 'Deuteronomy', 5, 28, 42, ' جميع أشجارك وأثمار أرضك يتولاه الصرصر '),
(10109, 'Deuteronomy', 5, 28, 43, ' الغريب الذي في وسطك يستعلي عليك متصاعدا ، وأنت تنحط متنازلا '),
(10110, 'Deuteronomy', 5, 28, 44, ' هو يقرضك وأنت لا تقرضه . هو يكون رأسا وأنت تكون ذنبا '),
(10111, 'Deuteronomy', 5, 28, 45, ' وتأتي عليك جميع هذه اللعنات وتتبعك وتدركك حتى تهلك ، لأنك لم تسمع لصوت الرب إلهك لتحفظ وصاياه وفرائضه التي أوصاك بها '),
(10112, 'Deuteronomy', 5, 28, 46, ' فتكون فيك آية وأعجوبة وفي نسلك إلى الأبد '),
(10113, 'Deuteronomy', 5, 28, 47, ' من أجل أنك لم تعبد الرب إلهك بفرح وبطيبة قلب لكثرة كل شيء '),
(10114, 'Deuteronomy', 5, 28, 48, ' تستعبد لأعدائك الذين يرسلهم الرب عليك في جوع وعطش وعري وعوز كل شيء . فيجعل نير حديد على عنقك حتى يهلكك '),
(10115, 'Deuteronomy', 5, 28, 49, ' يجلب الرب عليك أمة من بعيد ، من أقصاء الأرض كما يطير النسر ، أمة لا تفهم لسانها '),
(10116, 'Deuteronomy', 5, 28, 50, ' أمة جافية الوجه لا تهاب الشيخ ولا تحن إلى الولد '),
(10117, 'Deuteronomy', 5, 28, 51, ' فتأكل ثمرة بهائمك وثمرة أرضك حتى تهلك ، ولا تبقي لك قمحا ولا خمرا ولا زيتا ، ولا نتاج بقرك ولا إناث غنمك ، حتى تفنيك '),
(10118, 'Deuteronomy', 5, 28, 52, ' وتحاصرك في جميع أبوابك حتى تهبط أسوارك الشامخة الحصينة التي أنت تثق بها في كل أرضك . تحاصرك في جميع أبوابك ، في كل أرضك التي يعطيك الرب إلهك '),
(10119, 'Deuteronomy', 5, 28, 53, ' فتأكل ثمرة بطنك ، لحم بنيك وبناتك الذين أعطاك الرب إلهك في الحصار والضيقة التي يضايقك بها عدوك '),
(10120, 'Deuteronomy', 5, 28, 54, ' الرجل المتنعم فيك والمترفه جدا ، تبخل عينه على أخيه وامرأة حضنه وبقية أولاده الذين يبقيهم '),
(10121, 'Deuteronomy', 5, 28, 55, ' بأن يعطي أحدهم من لحم بنيه الذي يأكله ، لأنه لم يبق له شيء في الحصار والضيقة التي يضايقك بها عدوك في جميع أبوابك '),
(10122, 'Deuteronomy', 5, 28, 56, ' والمرأة المتنعمة فيك والمترفهة التي لم تجرب أن تضع أسفل قدمها على الأرض للتنعم والترفه ، تبخل عينها على رجل حضنها وعلى ابنها وبنتها '),
(10123, 'Deuteronomy', 5, 28, 57, ' بمشيمتها الخارجة من بين رجليها وبأولادها الذين تلدهم ، لأنها تأكلهم سرا في عوز كل شيء ، في الحصار والضيقة التي يضايقك بها عدوك في أبوابك '),
(10124, 'Deuteronomy', 5, 28, 58, ' إن لم تحرص لتعمل بجميع كلمات هذا الناموس المكتوبة في هذا السفر ، لتهاب هذا الاسم الجليل المرهوب ، الرب إلهك '),
(10125, 'Deuteronomy', 5, 28, 59, ' يجعل الرب ضرباتك وضربات نسلك عجيبة . ضربات عظيمة راسخة ، وأمراضا ردية ثابتة '),
(10126, 'Deuteronomy', 5, 28, 60, ' ويرد عليك جميع أدواء مصر التي فزعت منها ، فتلتصق بك '),
(10127, 'Deuteronomy', 5, 28, 61, ' أيضا كل مرض وكل ضربة لم تكتب في سفر الناموس هذا ، يسلطه الرب عليك حتى تهلك '),
(10128, 'Deuteronomy', 5, 28, 62, ' فتبقون نفرا قليلا عوض ما كنتم كنجوم السماء في الكثرة ، لأنك لم تسمع لصوت الرب إلهك '),
(10129, 'Deuteronomy', 5, 28, 63, ' وكما فرح الرب لكم ليحسن إليكم ويكثركم ، كذلك يفرح الرب لكم ليفنيكم ويهلككم ، فتستأصلون من الأرض التي أنت داخل إليها لتمتلكها '),
(10130, 'Deuteronomy', 5, 28, 64, ' ويبددك الرب في جميع الشعوب من أقصاء الأرض إلى أقصائها ، وتعبد هناك آلهة أخرى لم تعرفها أنت ولا آباؤك ، من خشب وحجر '),
(10131, 'Deuteronomy', 5, 28, 65, ' وفي تلك الأمم لا تطمئن ولا يكون قرار لقدمك ، بل يعطيك الرب هناك قلبا مرتجفا وكلال العينين وذبول النفس '),
(10132, 'Deuteronomy', 5, 28, 66, ' وتكون حياتك معلقة قدامك ، وترتعب ليلا ونهارا ولا تأمن على حياتك '),
(10133, 'Deuteronomy', 5, 28, 67, ' في الصباح تقول : يا ليته المساء ، وفي المساء تقول : يا ليته الصباح ، من ارتعاب قلبك الذي ترتعب ، ومن منظر عينيك الذي تنظر '),
(10134, 'Deuteronomy', 5, 28, 68, ' ويردك الرب إلى مصر في سفن في الطريق التي قلت لك لا تعد تراها ، فتباعون هناك لأعدائك عبيدا وإماء ، وليس من يشتري '),
(10135, 'Deuteronomy', 5, 29, 1, ' هذه هي كلمات العهد الذي أمر الرب موسى أن يقطعه مع بني إسرائيل في أرض موآب ، فضلا عن العهد الذي قطعه معهم في حوريب '),
(10136, 'Deuteronomy', 5, 29, 2, ' ودعا موسى جميع إسرائيل وقال لهم : أنتم شاهدتم ما فعل الرب أمام أعينكم في أرض مصر بفرعون وبجميع عبيده وبكل أرضه '),
(10137, 'Deuteronomy', 5, 29, 3, ' التجارب العظيمة التي أبصرتها عيناك ، وتلك الآيات والعجائب العظيمة '),
(10138, 'Deuteronomy', 5, 29, 4, ' ولكن لم يعطكم الرب قلبا لتفهموا ، وأعينا لتبصروا ، وآذانا لتسمعوا إلى هذا اليوم '),
(10139, 'Deuteronomy', 5, 29, 5, ' فقد سرت بكم أربعين سنة في البرية ، لم تبل ثيابكم عليكم ، ونعلك لم تبل على رجلك '),
(10140, 'Deuteronomy', 5, 29, 6, ' لم تأكلوا خبزا ولم تشربوا خمرا ولا مسكرا لكي تعلموا أني أنا الرب إلهكم '),
(10141, 'Deuteronomy', 5, 29, 7, ' ولما جئتم إلى هذا المكان خرج سيحون ملك حشبون وعوج ملك باشان للقائنا للحرب فكسرناهما '),
(10142, 'Deuteronomy', 5, 29, 8, ' وأخذنا أرضهما وأعطيناها نصيبا لرأوبين وجاد ونصف سبط منسى '),
(10143, 'Deuteronomy', 5, 29, 9, ' فاحفظوا كلمات هذا العهد واعملوا بها لكي تفلحوا في كل ما تفعلون '),
(10144, 'Deuteronomy', 5, 29, 10, ' أنتم واقفون اليوم جميعكم أمام الرب إلهكم : رؤساؤكم ، أسباطكم ، شيوخكم وعرفاؤكم وكل رجال إسرائيل '),
(10145, 'Deuteronomy', 5, 29, 11, ' وأطفالكم ونساؤكم ، وغريبكم الذي في وسط محلتكم ممن يحتطب حطبكم إلى من يستقي ماءكم '),
(10146, 'Deuteronomy', 5, 29, 12, ' لكي تدخل في عهد الرب إلهك وقسمه الذي يقطعه الرب إلهك معك اليوم '),
(10147, 'Deuteronomy', 5, 29, 13, ' لكي يقيمك اليوم لنفسه شعبا ، وهو يكون لك إلها كما قال لك ، وكما حلف لآبائك إبراهيم وإسحاق ويعقوب '),
(10148, 'Deuteronomy', 5, 29, 14, ' وليس معكم وحدكم أقطع أنا هذا العهد وهذا القسم '),
(10149, 'Deuteronomy', 5, 29, 15, ' بل مع الذي هو هنا معنا واقفا اليوم أمام الرب إلهنا ، ومع الذي ليس هنا معنا اليوم '),
(10150, 'Deuteronomy', 5, 29, 16, ' لأنكم قد عرفتم كيف أقمنا في أرض مصر ، وكيف اجتزنا في وسط الأمم الذين مررتم بهم '),
(10151, 'Deuteronomy', 5, 29, 17, ' ورأيتم أرجاسهم وأصنامهم التي عندهم من خشب وحجر وفضة وذهب '),
(10152, 'Deuteronomy', 5, 29, 18, ' لئلا يكون فيكم رجل أو امرأة أو عشيرة أو سبط قلبه اليوم منصرف عن الرب إلهنا لكي يذهب ليعبد آلهة تلك الأمم . لئلا يكون فيكم أصل يثمر علقما وأفسنتينا '),
(10153, 'Deuteronomy', 5, 29, 19, ' فيكون متى سمع كلام هذه اللعنة ، يتبرك في قلبه قائلا : يكون لي سلام ، إني بإصرار قلبي أسلك لإفناء الريان مع العطشان '),
(10154, 'Deuteronomy', 5, 29, 20, ' لا يشاء الرب أن يرفق به ، بل يدخن حينئذ غضب الرب وغيرته على ذلك الرجل ، فتحل عليه كل اللعنات المكتوبة في هذا الكتاب ، ويمحو الرب اسمه من تحت السماء '),
(10155, 'Deuteronomy', 5, 18, 22, ' فما تكلم به النبي باسم الرب ولم يحدث ولم يصر ، فهو الكلام الذي لم يتكلم به الرب ، بل بطغيان تكلم به النبي ، فلا تخف منه '),
(10156, 'Deuteronomy', 5, 19, 1, ' متى قرض الرب إلهك الأمم الذين الرب إلهك يعطيك أرضهم ، وورثتهم وسكنت مدنهم وبيوتهم '),
(10157, 'Deuteronomy', 5, 19, 2, ' تفرز لنفسك ثلاث مدن في وسط أرضك التي يعطيك الرب إلهك لتمتلكها '),
(10158, 'Deuteronomy', 5, 19, 3, ' تصلح الطريق وتثلث تخوم أرضك التي يقسم لك الرب إلهك ، فتكون لكي يهرب إليها كل قاتل '),
(10159, 'Deuteronomy', 5, 19, 4, ' وهذا هو حكم القاتل الذي يهرب إلى هناك فيحيا : من ضرب صاحبه بغير علم وهو غير مبغض له منذ أمس وما قبله '),
(10160, 'Deuteronomy', 5, 19, 5, ' ومن ذهب مع صاحبه في الوعر ليحتطب حطبا ، فاندفعت يده بالفأس ليقطع الحطب ، وأفلت الحديد من الخشب وأصاب صاحبه فمات ، فهو يهرب إلى إحدى تلك المدن فيحيا '),
(10161, 'Deuteronomy', 5, 19, 6, ' لئلا يسعى ولي الدم وراء القاتل حين يحمى قلبه ، ويدركه إذا طال الطريق ويقتله ، وليس عليه حكم الموت ، لأنه غير مبغض له منذ أمس وما قبله '),
(10162, 'Deuteronomy', 5, 19, 7, ' لأجل ذلك أنا آمرك قائلا : ثلاث مدن تفرز لنفسك '),
(10163, 'Deuteronomy', 5, 19, 8, ' وإن وسع الرب إلهك تخومك كما حلف لآبائك ، وأعطاك جميع الأرض التي قال إنه يعطي لآبائك '),
(10164, 'Deuteronomy', 5, 19, 9, ' إذ حفظت كل هذه الوصايا لتعملها ، كما أنا أوصيك اليوم لتحب الرب إلهك وتسلك في طرقه كل الأيام ، فزد لنفسك أيضا ثلاث مدن على هذه الثلاث '),
(10165, 'Deuteronomy', 5, 19, 10, ' حتى لا يسفك دم بريء في وسط أرضك التي يعطيك الرب إلهك نصيبا ، فيكون عليك دم '),
(10166, 'Deuteronomy', 5, 19, 11, ' ولكن إذا كان إنسان مبغضا لصاحبه ، فكمن له وقام عليه وضربه ضربة قاتلة فمات ، ثم هرب إلى إحدى تلك المدن '),
(10167, 'Deuteronomy', 5, 19, 12, ' يرسل شيوخ مدينته ويأخذونه من هناك ويدفعونه إلى يد ولي الدم فيموت '),
(10168, 'Deuteronomy', 5, 19, 13, ' لا تشفق عينك عليه . فتنزع دم البريء من إسرائيل ، فيكون لك خير '),
(10169, 'Deuteronomy', 5, 19, 14, ' لا تنقل تخم صاحبك الذي نصبه الأولون في نصيبك الذي تناله في الأرض التي يعطيك الرب إلهك لكي تمتلكها '),
(10170, 'Deuteronomy', 5, 19, 15, ' لا يقوم شاهد واحد على إنسان في ذنب ما أو خطية ما من جميع الخطايا التي يخطئ بها . على فم شاهدين أو على فم ثلاثة شهود يقوم الأمر '),
(10171, 'Deuteronomy', 5, 19, 16, ' إذا قام شاهد زور على إنسان ليشهد عليه بزيغ '),
(10172, 'Deuteronomy', 5, 19, 17, ' يقف الرجلان اللذان بينهما الخصومة أمام الرب ، أمام الكهنة والقضاة الذين يكونون في تلك الأيام '),
(10173, 'Deuteronomy', 5, 19, 18, ' فإن فحص القضاة جيدا ، وإذا الشاهد شاهد كاذب ، قد شهد بالكذب على أخيه '),
(10174, 'Deuteronomy', 5, 19, 19, ' فافعلوا به كما نوى أن يفعل بأخيه . فتنزعون الشر من وسطكم '),
(10175, 'Deuteronomy', 5, 19, 20, ' ويسمع الباقون فيخافون ، ولا يعودون يفعلون مثل ذلك الأمر الخبيث في وسطك '),
(10176, 'Deuteronomy', 5, 19, 21, ' لا تشفق عينك . نفس بنفس . عين بعين . سن بسن . يد بيد . رجل برجل '),
(10177, 'Deuteronomy', 5, 20, 1, ' إذا خرجت للحرب على عدوك ورأيت خيلا ومراكب ، قوما أكثر منك ، فلا تخف منهم ، لأن معك الرب إلهك الذي أصعدك من أرض مصر '),
(10178, 'Deuteronomy', 5, 20, 2, ' وعندما تقربون من الحرب يتقدم الكاهن ويخاطب الشعب '),
(10179, 'Deuteronomy', 5, 20, 3, ' ويقول لهم : اسمع يا إسرائيل : أنتم قربتم اليوم من الحرب على أعدائكم . لا تضعف قلوبكم . لا تخافوا ولا ترتعدوا ولا ترهبوا وجوههم '),
(10180, 'Deuteronomy', 5, 20, 4, ' لأن الرب إلهكم سائر معكم لكي يحارب عنكم أعداءكم ليخلصكم '),
(10181, 'Deuteronomy', 5, 20, 5, ' ثم يخاطب العرفاء الشعب قائلين : من هو الرجل الذي بنى بيتا جديدا ولم يدشنه ؟ ليذهب ويرجع إلى بيته لئلا يموت في الحرب فيدشنه رجل آخر '),
(10182, 'Deuteronomy', 5, 20, 6, ' ومن هو الرجل الذي غرس كرما ولم يبتكره ؟ ليذهب ويرجع إلى بيته لئلا يموت في الحرب فيبتكره رجل آخر '),
(10183, 'Deuteronomy', 5, 20, 7, ' ومن هو الرجل الذي خطب امرأة ولم يأخذها ؟ ليذهب ويرجع إلى بيته لئلا يموت في الحرب فيأخذها رجل آخر '),
(10184, 'Deuteronomy', 5, 20, 8, ' ثم يعود العرفاء يخاطبون الشعب ويقولون : من هو الرجل الخائف والضعيف القلب ؟ ليذهب ويرجع إلى بيته لئلا تذوب قلوب إخوته مثل قلبه '),
(10185, 'Deuteronomy', 5, 20, 9, ' وعند فراغ العرفاء من مخاطبة الشعب يقيمون رؤساء جنود على رأس الشعب '),
(10186, 'Deuteronomy', 5, 20, 10, ' حين تقرب من مدينة لكي تحاربها استدعها إلى الصلح '),
(10187, 'Deuteronomy', 5, 20, 11, ' فإن أجابتك إلى الصلح وفتحت لك ، فكل الشعب الموجود فيها يكون لك للتسخير ويستعبد لك '),
(10188, 'Deuteronomy', 5, 20, 12, ' وإن لم تسالمك ، بل عملت معك حربا ، فحاصرها '),
(10189, 'Deuteronomy', 5, 20, 13, ' وإذا دفعها الرب إلهك إلى يدك فاضرب جميع ذكورها بحد السيف '),
(10190, 'Deuteronomy', 5, 20, 14, ' وأما النساء والأطفال والبهائم وكل ما في المدينة ، كل غنيمتها ، فتغتنمها لنفسك ، وتأكل غنيمة أعدائك التي أعطاك الرب إلهك '),
(10191, 'Deuteronomy', 5, 20, 15, ' هكذا تفعل بجميع المدن البعيدة منك جدا التي ليست من مدن هؤلاء الأمم هنا '),
(10192, 'Deuteronomy', 5, 20, 16, ' وأما مدن هؤلاء الشعوب التي يعطيك الرب إلهك نصيبا فلا تستبق منها نسمة ما '),
(10193, 'Deuteronomy', 5, 20, 17, ' بل تحرمها تحريما : الحثيين والأموريين والكنعانيين والفرزيين والحويين واليبوسيين ، كما أمرك الرب إلهك '),
(10194, 'Deuteronomy', 5, 20, 18, ' لكي لا يعلموكم أن تعملوا حسب جميع أرجاسهم التي عملوا لآلهتهم ، فتخطئوا إلى الرب إلهكم '),
(10195, 'Deuteronomy', 5, 20, 19, ' إذا حاصرت مدينة أياما كثيرة محاربا إياها لكي تأخذها ، فلا تتلف شجرها بوضع فأس عليه . إنك منه تأكل . فلا تقطعه . لأنه هل شجرة الحقل إنسان حتى يذهب قدامك في الحصار '),
(10196, 'Deuteronomy', 5, 20, 20, ' وأما الشجر الذي تعرف أنه ليس شجرا يؤكل منه ، فإياه تتلف وتقطع وتبني حصنا على المدينة التي تعمل معك حربا حتى تسقط '),
(10197, 'Deuteronomy', 5, 21, 1, ' إذا وجد قتيل في الأرض التي يعطيك الرب إلهك لتمتلكها واقعا في الحقل ، لا يعلم من قتله '),
(10198, 'Deuteronomy', 5, 21, 2, ' يخرج شيوخك وقضاتك ويقيسون إلى المدن التي حول القتيل '),
(10199, 'Deuteronomy', 5, 21, 3, ' فالمدينة القربى من القتيل ، يأخذ شيوخ تلك المدينة عجلة من البقر لم يحرث عليها ، لم تجر بالنير '),
(10200, 'Deuteronomy', 5, 21, 4, ' وينحدر شيوخ تلك المدينة بالعجلة إلى واد دائم السيلان لم يحرث فيه ولم يزرع ، ويكسرون عنق العجلة في الوادي '),
(10201, 'Deuteronomy', 5, 21, 5, ' ثم يتقدم الكهنة بنو لاوي ، لأنه إياهم اختار الرب إلهك ليخدموه ويباركوا باسم الرب ، وحسب قولهم تكون كل خصومة وكل ضربة '),
(10202, 'Deuteronomy', 5, 21, 6, ' ويغسل جميع شيوخ تلك المدينة القريبين من القتيل أيديهم على العجلة المكسورة العنق في الوادي '),
(10203, 'Deuteronomy', 5, 21, 7, ' ويصرحون ويقولون : أيدينا لم تسفك هذا الدم ، وأعيننا لم تبصر '),
(10204, 'Deuteronomy', 5, 21, 8, ' اغفر لشعبك إسرائيل الذي فديت يارب ، ولا تجعل دم بريء في وسط شعبك إسرائيل . فيغفر لهم الدم '),
(10205, 'Deuteronomy', 5, 21, 9, ' فتنزع الدم البريء من وسطك إذا عملت الصالح في عيني الرب '),
(10206, 'Deuteronomy', 5, 21, 10, ' إذا خرجت لمحاربة أعدائك ودفعهم الرب إلهك إلى يدك ، وسبيت منهم سبيا '),
(10207, 'Deuteronomy', 5, 21, 11, ' ورأيت في السبي امرأة جميلة الصورة ، والتصقت بها واتخذتها لك زوجة '),
(10208, 'Deuteronomy', 5, 21, 12, ' فحين تدخلها إلى بيتك تحلق رأسها وتقلم أظفارها '),
(10209, 'Deuteronomy', 5, 21, 13, ' وتنزع ثياب سبيها عنها ، وتقعد في بيتك وتبكي أباها وأمها شهرا من الزمان ، ثم بعد ذلك تدخل عليها وتتزوج بها ، فتكون لك زوجة '),
(10210, 'Deuteronomy', 5, 21, 14, ' وإن لم تسر بها فأطلقها لنفسها . لا تبعها بيعا بفضة ، ولا تسترقها من أجل أنك قد أذللتها '),
(10211, 'Deuteronomy', 5, 21, 15, ' إذا كان لرجل امرأتان ، إحداهما محبوبة والأخرى مكروهة ، فولدتا له بنين ، المحبوبة والمكروهة . فإن كان الابن البكر للمكروهة '),
(10212, 'Deuteronomy', 5, 21, 16, ' فيوم يقسم لبنيه ما كان له ، لا يحل له أن يقدم ابن المحبوبة بكرا على ابن المكروهة البكر '),
(10213, 'Deuteronomy', 5, 21, 17, ' بل يعرف ابن المكروهة بكرا ليعطيه نصيب اثنين من كل ما يوجد عنده ، لأنه هو أول قدرته . له حق البكورية '),
(10214, 'Deuteronomy', 5, 21, 18, ' إذا كان لرجل ابن معاند ومارد لا يسمع لقول أبيه ولا لقول أمه ، ويؤدبانه فلا يسمع لهما '),
(10215, 'Deuteronomy', 5, 21, 19, ' يمسكه أبوه وأمه ويأتيان به إلى شيوخ مدينته وإلى باب مكانه '),
(10216, 'Deuteronomy', 5, 21, 20, ' ويقولان لشيوخ مدينته : ابننا هذا معاند ومارد لا يسمع لقولنا ، وهو مسرف وسكير '),
(10217, 'Deuteronomy', 5, 21, 21, ' فيرجمه جميع رجال مدينته بحجارة حتى يموت . فتنزع الشر من بينكم ، ويسمع كل إسرائيل ويخافون '),
(10218, 'Deuteronomy', 5, 21, 22, ' وإذا كان على إنسان خطية حقها الموت ، فقتل وعلقته على خشبة '),
(10219, 'Deuteronomy', 5, 21, 23, ' فلا تبت جثته على الخشبة ، بل تدفنه في ذلك اليوم ، لأن المعلق ملعون من الله . فلا تنجس أرضك التي يعطيك الرب إلهك نصيبا '),
(10220, 'Deuteronomy', 5, 22, 1, ' لا تنظر ثور أخيك أو شاته شاردا وتتغاضى عنه ، بل ترده إلى أخيك لا محالة '),
(10221, 'Deuteronomy', 5, 22, 2, ' وإن لم يكن أخوك قريبا منك أو لم تعرفه ، فضمه إلى داخل بيتك . ويكون عندك حتى يطلبه أخوك ، حينئذ ترده إليه '),
(10222, 'Deuteronomy', 5, 22, 3, ' وهكذا تفعل بحماره ، وهكذا تفعل بثيابه ، وهكذا تفعل بكل مفقود لأخيك يفقد منه وتجده . لا يحل لك أن تتغاضى '),
(10223, 'Deuteronomy', 5, 22, 4, ' لا تنظر حمار أخيك أو ثوره واقعا في الطريق وتتغافل عنه بل تقيمه معه لا محالة '),
(10224, 'Deuteronomy', 5, 22, 5, ' لا يكن متاع رجل على امرأة ، ولا يلبس رجل ثوب امرأة ، لأن كل من يعمل ذلك مكروه لدى الرب إلهك '),
(10225, 'Deuteronomy', 5, 22, 6, ' إذا اتفق قدامك عش طائر في الطريق في شجرة ما أو على الأرض ، فيه فراخ أو بيض ، والأم حاضنة الفراخ أو البيض ، فلا تأخذ الأم مع الأولاد '),
(10226, 'Deuteronomy', 5, 22, 7, ' أطلق الأم وخذ لنفسك الأولاد ، لكي يكون لك خير وتطيل الأيام '),
(10227, 'Deuteronomy', 5, 22, 8, ' إذا بنيت بيتا جديدا ، فاعمل حائطا لسطحك لئلا تجلب دما على بيتك إذا سقط عنه ساقط '),
(10228, 'Deuteronomy', 5, 22, 9, ' لا تزرع حقلك صنفين ، لئلا يتقدس الملء : الزرع الذي تزرع ومحصول الحقل '),
(10229, 'Deuteronomy', 5, 34, 11, ' في جميع الآيات والعجائب التي أرسله الرب ليعملها في أرض مصر بفرعون وبجميع عبيده وكل أرضه '),
(10230, 'Deuteronomy', 5, 34, 12, ' وفي كل اليد الشديدة وكل المخاوف العظيمة التي صنعها موسى أمام أعين جميع إسرائيل '),
(10231, 'Deuteronomy', 5, 22, 10, ' لا تحرث على ثور وحمار معا '),
(10232, 'Deuteronomy', 5, 22, 11, ' لا تلبس ثوبا مختلطا صوفا وكتانا معا '),
(10233, 'Deuteronomy', 5, 22, 12, ' اعمل لنفسك جدائل على أربعة أطراف ثوبك الذي تتغطى به '),
(10234, 'Deuteronomy', 5, 22, 13, ' إذا اتخذ رجل امرأة وحين دخل عليها أبغضها '),
(10235, 'Deuteronomy', 5, 22, 14, ' ونسب إليها أسباب كلام ، وأشاع عنها اسما رديا ، وقال : هذه المرأة اتخذتها ولما دنوت منها لم أجد لها عذرة '),
(10236, 'Deuteronomy', 5, 22, 15, ' يأخذ الفتاة أبوها وأمها ويخرجان علامة عذرتها إلى شيوخ المدينة إلى الباب '),
(10237, 'Deuteronomy', 5, 22, 16, ' ويقول أبو الفتاة للشيوخ : أعطيت هذا الرجل ابنتي زوجة فأبغضها '),
(10238, 'Deuteronomy', 5, 22, 17, ' وها هو قد جعل أسباب كلام قائلا : لم أجد لبنتك عذرة . وهذه علامة عذرة ابنتي . ويبسطان الثوب أمام شيوخ المدينة '),
(10239, 'Deuteronomy', 5, 22, 18, ' فيأخذ شيوخ تلك المدينة الرجل ويؤدبونه '),
(10240, 'Deuteronomy', 5, 22, 19, ' ويغرمونه بمئة من الفضة ، ويعطونها لأبي الفتاة ، لأنه أشاع اسما رديا عن عذراء من إسرائيل . فتكون له زوجة . لا يقدر أن يطلقها كل أيامه '),
(10241, 'Deuteronomy', 5, 22, 20, ' ولكن إن كان هذا الأمر صحيحا ، لم توجد عذرة للفتاة '),
(10242, 'Deuteronomy', 5, 22, 21, ' يخرجون الفتاة إلى باب بيت أبيها ، ويرجمها رجال مدينتها بالحجارة حتى تموت ، لأنها عملت قباحة في إسرائيل بزناها في بيت أبيها . فتنزع الشر من وسطك '),
(10243, 'Deuteronomy', 5, 22, 22, ' إذا وجد رجل مضطجعا مع امرأة زوجة بعل ، يقتل الاثنان : الرجل المضطجع مع المرأة ، والمرأة . فتنزع الشر من إسرائيل '),
(10244, 'Deuteronomy', 5, 22, 23, ' إذا كانت فتاة عذراء مخطوبة لرجل ، فوجدها رجل في المدينة واضطجع معها '),
(10245, 'Deuteronomy', 5, 22, 24, ' فأخرجوهما كليهما إلى باب تلك المدينة وارجموهما بالحجارة حتى يموتا . الفتاة من أجل أنها لم تصرخ في المدينة ، والرجل من أجل أنه أذل امرأة صاحبه . فتنزع الشر من وسطك '),
(10246, 'Deuteronomy', 5, 22, 25, ' ولكن إن وجد الرجل الفتاة المخطوبة في الحقل وأمسكها الرجل واضطجع معها ، يموت الرجل الذي اضطجع معها وحده '),
(10247, 'Deuteronomy', 5, 22, 26, ' وأما الفتاة فلا تفعل بها شيئا . ليس على الفتاة خطية للموت ، بل كما يقوم رجل على صاحبه ويقتله قتلا . هكذا هذا الأمر '),
(10248, 'Deuteronomy', 5, 22, 27, ' إنه في الحقل وجدها ، فصرخت الفتاة المخطوبة فلم يكن من يخلصها '),
(10249, 'Deuteronomy', 5, 22, 28, ' إذا وجد رجل فتاة عذراء غير مخطوبة ، فأمسكها واضطجع معها ، فوجدا '),
(10250, 'Deuteronomy', 5, 22, 29, ' يعطي الرجل الذي اضطجع معها لأبي الفتاة خمسين من الفضة ، وتكون هي له زوجة من أجل أنه قد أذلها . لا يقدر أن يطلقها كل أيامه '),
(10251, 'Deuteronomy', 5, 22, 30, ' لا يتخذ رجل امرأة أبيه ، ولا يكشف ذيل أبيه '),
(10252, 'Deuteronomy', 5, 23, 1, ' لا يدخل مخصي بالرض أو مجبوب في جماعة الرب '),
(10253, 'Deuteronomy', 5, 23, 2, ' لا يدخل ابن زنى في جماعة الرب . حتى الجيل العاشر لا يدخل منه أحد في جماعة الرب '),
(10254, 'Deuteronomy', 5, 23, 3, ' لا يدخل عموني ولا موآبي في جماعة الرب . حتى الجيل العاشر لا يدخل منهم أحد في جماعة الرب إلى الأبد '),
(10255, 'Deuteronomy', 5, 23, 4, ' من أجل أنهم لم يلاقوكم بالخبز والماء في الطريق عند خروجكم من مصر ، ولأنهم استأجروا عليك بلعام بن بعور من فتور أرام النهرين لكي يلعنك '),
(10256, 'Deuteronomy', 5, 23, 5, ' ولكن لم يشإ الرب إلهك أن يسمع لبلعام ، فحول لأجلك الرب إلهك اللعنة إلى بركة ، لأن الرب إلهك قد أحبك '),
(10257, 'Deuteronomy', 5, 23, 6, ' لا تلتمس سلامهم ولا خيرهم كل أيامك إلى الأبد '),
(10258, 'Deuteronomy', 5, 23, 7, ' لا تكره أدوميا لأنه أخوك . لا تكره مصريا لأنك كنت نزيلا في أرضه '),
(10259, 'Deuteronomy', 5, 23, 8, ' الأولاد الذين يولدون لهم في الجيل الثالث يدخلون منهم في جماعة الرب '),
(10260, 'Deuteronomy', 5, 23, 9, ' إذا خرجت في جيش على أعدائك فاحترز من كل شيء رديء '),
(10261, 'Deuteronomy', 5, 23, 10, ' إن كان فيك رجل غير طاهر من عارض الليل ، يخرج إلى خارج المحلة . لا يدخل إلى داخل المحلة '),
(10262, 'Deuteronomy', 5, 23, 11, ' ونحو إقبال المساء يغتسل بماء ، وعند غروب الشمس يدخل إلى داخل المحلة '),
(10263, 'Deuteronomy', 5, 23, 12, ' ويكون لك موضع خارج المحلة لتخرج إليه خارجا '),
(10264, 'Deuteronomy', 5, 23, 13, ' ويكون لك وتد مع عدتك لتحفر به عندما تجلس خارجا وترجع وتغطي برازك '),
(10265, 'Deuteronomy', 5, 23, 14, ' لأن الرب إلهك سائر في وسط محلتك ، لكي ينقذك ويدفع أعداءك أمامك . فلتكن محلتك مقدسة ، لئلا يرى فيك قذر شيء فيرجع عنك '),
(10266, 'Deuteronomy', 5, 23, 15, ' عبدا أبق إليك من مولاه لا تسلم إلى مولاه '),
(10267, 'Deuteronomy', 5, 23, 16, ' عندك يقيم في وسطك ، في المكان الذي يختاره في أحد أبوابك حيث يطيب له . لا تظلمه '),
(10268, 'Deuteronomy', 5, 23, 17, ' لا تكن زانية من بنات إسرائيل ، ولا يكن مأبون من بني إسرائيل '),
(10269, 'Deuteronomy', 5, 23, 18, ' لا تدخل أجرة زانية ولا ثمن كلب إلى بيت الرب إلهك عن نذر ما ، لأنهما كليهما رجس لدى الرب إلهك '),
(10270, 'Deuteronomy', 5, 23, 19, ' لا تقرض أخاك بربا ، ربا فضة ، أو ربا طعام ، أو ربا شيء ما مما يقرض بربا '),
(10271, 'Deuteronomy', 5, 23, 20, ' للأجنبي تقرض بربا ، ولكن لأخيك لا تقرض بربا ، لكي يباركك الرب إلهك في كل ما تمتد إليه يدك في الأرض التي أنت داخل إليها لتمتلكها '),
(10272, 'Deuteronomy', 5, 23, 21, ' إذا نذرت نذرا للرب إلهك فلا تؤخر وفاءه ، لأن الرب إلهك يطلبه منك فتكون عليك خطية '),
(10273, 'Deuteronomy', 5, 23, 22, ' ولكن إذا امتنعت أن تنذر لا تكون عليك خطية '),
(10274, 'Deuteronomy', 5, 23, 23, ' ما خرج من شفتيك احفظ واعمل ، كما نذرت للرب إلهك تبرعا ، كما تكلم فمك '),
(10275, 'Deuteronomy', 5, 23, 24, ' إذا دخلت كرم صاحبك فكل عنبا حسب شهوة نفسك ، شبعتك . ولكن في وعائك لا تجعل '),
(10276, 'Deuteronomy', 5, 23, 25, ' إذا دخلت زرع صاحبك فاقطف سنابل بيدك ، ولكن منجلا لا ترفع على زرع صاحبك '),
(10277, 'Deuteronomy', 5, 24, 1, ' إذا أخذ رجل امرأة وتزوج بها ، فإن لم تجد نعمة في عينيه لأنه وجد فيها عيب شيء ، وكتب لها كتاب طلاق ودفعه إلى يدها وأطلقها من بيته '),
(10278, 'Deuteronomy', 5, 24, 2, ' ومتى خرجت من بيته ذهبت وصارت لرجل آخر '),
(10279, 'Deuteronomy', 5, 24, 3, ' فإن أبغضها الرجل الأخير وكتب لها كتاب طلاق ودفعه إلى يدها وأطلقها من بيته ، أو إذا مات الرجل الأخير الذي اتخذها له زوجة '),
(10280, 'Deuteronomy', 5, 24, 4, ' لا يقدر زوجها الأول الذي طلقها أن يعود يأخذها لتصير له زوجة بعد أن تنجست . لأن ذلك رجس لدى الرب . فلا تجلب خطية على الأرض التي يعطيك الرب إلهك نصيبا '),
(10281, 'Deuteronomy', 5, 24, 5, ' إذا اتخذ رجل امرأة جديدة ، فلا يخرج في الجند ، ولا يحمل عليه أمر ما . حرا يكون في بيته سنة واحدة ، ويسر امرأته التي أخذها '),
(10282, 'Deuteronomy', 5, 24, 6, ' لا يسترهن أحد رحى أو مرداتها ، لأنه إنما يسترهن حياة '),
(10283, 'Deuteronomy', 5, 24, 7, ' إذا وجد رجل قد سرق نفسا من إخوته بني إسرائيل واسترقه وباعه ، يموت ذلك السارق ، فتنزع الشر من وسطك '),
(10284, 'Deuteronomy', 5, 24, 8, ' احرص في ضربة البرص لتحفظ جدا وتعمل حسب كل ما يعلمك الكهنة اللاويون . كما أمرتهم تحرصون أن تعملوا '),
(10285, 'Deuteronomy', 5, 24, 9, ' اذكر ما صنع الرب إلهك بمريم في الطريق عند خروجكم من مصر '),
(10286, 'Deuteronomy', 5, 24, 10, ' إذا أقرضت صاحبك قرضا ما ، فلا تدخل بيته لكي ترتهن رهنا منه '),
(10287, 'Deuteronomy', 5, 24, 11, ' في الخارج تقف ، والرجل الذي تقرضه يخرج إليك الرهن إلى الخارج '),
(10288, 'Deuteronomy', 5, 24, 12, ' وإن كان رجلا فقيرا فلا تنم في رهنه '),
(10289, 'Deuteronomy', 5, 24, 13, ' رد إليه الرهن عند غروب الشمس ، لكي ينام في ثوبه ويباركك ، فيكون لك بر لدى الرب إلهك '),
(10290, 'Deuteronomy', 5, 24, 14, ' لا تظلم أجيرا مسكينا وفقيرا من إخوتك أو من الغرباء الذين في أرضك ، في أبوابك '),
(10291, 'Deuteronomy', 5, 24, 15, ' في يومه تعطيه أجرته ، ولا تغرب عليها الشمس ، لأنه فقير وإليها حامل نفسه ، لئلا يصرخ عليك إلى الرب فتكون عليك خطية '),
(10292, 'Deuteronomy', 5, 24, 16, ' لا يقتل الآباء عن الأولاد ، ولا يقتل الأولاد عن الآباء . كل إنسان بخطيته يقتل '),
(10293, 'Deuteronomy', 5, 24, 17, ' لا تعوج حكم الغريب واليتيم ، ولا تسترهن ثوب الأرملة '),
(10294, 'Deuteronomy', 5, 24, 18, ' واذكر أنك كنت عبدا في مصر ففداك الرب إلهك من هناك . لذلك أنا أوصيك أن تعمل هذا الأمر '),
(10295, 'Deuteronomy', 5, 24, 19, ' إذا حصدت حصيدك في حقلك ونسيت حزمة في الحقل ، فلا ترجع لتأخذها ، للغريب واليتيم والأرملة تكون ، لكي يباركك الرب إلهك في كل عمل يديك '),
(10296, 'Deuteronomy', 5, 24, 20, ' وإذا خبطت زيتونك فلا تراجع الأغصان وراءك ، للغريب واليتيم والأرملة يكون '),
(10297, 'Deuteronomy', 5, 24, 21, ' إذا قطفت كرمك فلا تعلله وراءك . للغريب واليتيم والأرملة يكون '),
(10298, 'Deuteronomy', 5, 24, 22, ' واذكر أنك كنت عبدا في أرض مصر . لذلك أنا أوصيك أن تعمل هذا الأمر '),
(10299, 'Deuteronomy', 5, 25, 1, ' إذا كانت خصومة بين أناس وتقدموا إلى القضاء ليقضي القضاة بينهم ، فليبرروا البار ويحكموا على المذنب '),
(10300, 'Deuteronomy', 5, 25, 2, ' فإن كان المذنب مستوجب الضرب ، يطرحه القاضي ويجلدونه أمامه على قدر ذنبه بالعدد '),
(10301, 'Deuteronomy', 5, 25, 3, ' أربعين يجلده . لا يزد ، لئلا إذا زاد في جلده على هذه ضربات كثيرة ، يحتقر أخوك في عينيك '),
(10302, 'Deuteronomy', 5, 25, 4, ' لا تكم الثور في دراسه '),
(10303, 'Deuteronomy', 5, 25, 5, ' إذا سكن إخوة معا ومات واحد منهم وليس له ابن ، فلا تصر امرأة الميت إلى خارج لرجل أجنبي . أخو زوجها يدخل عليها ويتخذها لنفسه زوجة ، ويقوم لها بواجب أخي الزوج '),
(10304, 'Deuteronomy', 5, 29, 21, ' ويفرزه الرب للشر من جميع أسباط إسرائيل حسب جميع لعنات العهد المكتوبة في كتاب الشريعة هذا '),
(10305, 'Deuteronomy', 5, 29, 22, ' فيقول الجيل الأخير ، بنوكم الذين يقومون بعدكم ، والأجنبي الذي يأتي من أرض بعيدة ، حين يرون ضربات تلك الأرض وأمراضها التي يمرضها بها الرب '),
(10306, 'Deuteronomy', 5, 29, 23, ' كبريت وملح ، كل أرضها حريق ، لا تزرع ولا تنبت ولا يطلع فيها عشب ما ، كانقلاب سدوم وعمورة وأدمة وصبوييم ، التي قلبها الرب بغضبه وسخطه '),
(10307, 'Deuteronomy', 5, 29, 24, ' ويقول جميع الأمم : لماذا فعل الرب هكذا بهذه الأرض ؟ لماذا حمو هذا الغضب العظيم '),
(10308, 'Deuteronomy', 5, 29, 25, ' فيقولون : لأنهم تركوا عهد الرب إله آبائهم الذي قطعه معهم حين أخرجهم من أرض مصر '),
(10309, 'Deuteronomy', 5, 29, 26, ' وذهبوا وعبدوا آلهة أخرى وسجدوا لها . آلهة لم يعرفوها ولا قسمت لهم '),
(10310, 'Deuteronomy', 5, 29, 27, ' فاشتعل غضب الرب على تلك الأرض حتى جلب عليها كل اللعنات المكتوبة في هذا السفر '),
(10311, 'Deuteronomy', 5, 29, 28, ' واستأصلهم الرب من أرضهم بغضب وسخط وغيظ عظيم ، وألقاهم إلى أرض أخرى كما في هذا اليوم '),
(10312, 'Deuteronomy', 5, 29, 29, ' السرائر للرب إلهنا ، والمعلنات لنا ولبنينا إلى الأبد ، لنعمل بجميع كلمات هذه الشريعة '),
(10313, 'Deuteronomy', 5, 30, 1, ' ومتى أتت عليك كل هذه الأمور ، البركة واللعنة ، اللتان جعلتهما قدامك ، فإن رددت في قلبك بين جميع الأمم الذين طردك الرب إلهك إليهم '),
(10314, 'Deuteronomy', 5, 30, 2, ' ورجعت إلى الرب إلهك ، وسمعت لصوته حسب كل ما أنا أوصيك به اليوم ، أنت وبنوك ، بكل قلبك وبكل نفسك '),
(10315, 'Deuteronomy', 5, 30, 3, ' يرد الرب إلهك سبيك ويرحمك ، ويعود فيجمعك من جميع الشعوب الذين بددك إليهم الرب إلهك '),
(10316, 'Deuteronomy', 5, 30, 4, ' إن يكن قد بددك إلى أقصاء السماوات ، فمن هناك يجمعك الرب إلهك ، ومن هناك يأخذك '),
(10317, 'Deuteronomy', 5, 30, 5, ' ويأتي بك الرب إلهك إلى الأرض التي امتلكها آباؤك فتمتلكها ، ويحسن إليك ويكثرك أكثر من آبائك '),
(10318, 'Deuteronomy', 5, 30, 6, ' ويختن الرب إلهك قلبك وقلب نسلك ، لكي تحب الرب إلهك من كل قلبك ومن كل نفسك لتحيا '),
(10319, 'Deuteronomy', 5, 30, 7, ' ويجعل الرب إلهك كل هذه اللعنات على أعدائك ، وعلى مبغضيك الذين طردوك '),
(10320, 'Deuteronomy', 5, 30, 8, ' وأما أنت فتعود تسمع لصوت الرب ، وتعمل بجميع وصاياه التي أنا أوصيك بها اليوم '),
(10321, 'Deuteronomy', 5, 30, 9, ' فيزيدك الرب إلهك خيرا في كل عمل يدك ، في ثمرة بطنك وثمرة بهائمك وثمرة أرضك . لأن الرب يرجع ليفرح لك بالخير كما فرح لآبائك '),
(10322, 'Deuteronomy', 5, 30, 10, ' إذا سمعت لصوت الرب إلهك لتحفظ وصاياه وفرائضه المكتوبة في سفر الشريعة هذا . إذا رجعت إلى الرب إلهك بكل قلبك وبكل نفسك '),
(10323, 'Deuteronomy', 5, 30, 11, ' إن هذه الوصية التي أوصيك بها اليوم ليست عسرة عليك ولا بعيدة منك '),
(10324, 'Deuteronomy', 5, 30, 12, ' ليست هي في السماء حتى تقول : من يصعد لأجلنا إلى السماء ويأخذها لنا ويسمعنا إياها لنعمل بها '),
(10325, 'Deuteronomy', 5, 30, 13, ' ولا هي في عبر البحر حتى تقول : من يعبر لأجلنا البحر ويأخذها لنا ويسمعنا إياها لنعمل بها '),
(10326, 'Deuteronomy', 5, 30, 14, ' بل الكلمة قريبة منك جدا ، في فمك وفي قلبك لتعمل بها '),
(10327, 'Deuteronomy', 5, 30, 15, ' انظر . قد جعلت اليوم قدامك الحياة والخير ، والموت والشر '),
(10328, 'Deuteronomy', 5, 30, 16, ' بما أني أوصيتك اليوم أن تحب الرب إلهك وتسلك في طرقه وتحفظ وصاياه وفرائضه وأحكامه لكي تحيا وتنمو ، ويباركك الرب إلهك في الأرض التي أنت داخل إليها لكي تمتلكها '),
(10329, 'Deuteronomy', 5, 30, 17, ' فإن انصرف قلبك ولم تسمع ، بل غويت وسجدت لآلهة أخرى وعبدتها '),
(10330, 'Deuteronomy', 5, 30, 18, ' فإني أنبئكم اليوم أنكم لا محالة تهلكون . لا تطيل الأيام على الأرض التي أنت عابر الأردن لكي تدخلها وتمتلكها '),
(10331, 'Deuteronomy', 5, 30, 19, ' أشهد عليكم اليوم السماء والأرض . قد جعلت قدامك الحياة والموت . البركة واللعنة . فاختر الحياة لكي تحيا أنت ونسلك '),
(10332, 'Deuteronomy', 5, 30, 20, ' إذ تحب الرب إلهك وتسمع لصوته وتلتصق به ، لأنه هو حياتك والذي يطيل أيامك لكي تسكن على الأرض التي حلف الرب لآبائك إبراهيم وإسحاق ويعقوب أن يعطيهم إياها '),
(10333, 'Deuteronomy', 5, 31, 1, ' فذهب موسى وكلم بهذه الكلمات جميع إسرائيل '),
(10334, 'Deuteronomy', 5, 31, 2, ' وقال لهم : أنا اليوم ابن مئة وعشرين سنة . لا أستطيع الخروج والدخول بعد ، والرب قد قال لي : لا تعبر هذا الأردن '),
(10335, 'Deuteronomy', 5, 31, 3, ' الرب إلهك هو عابر قدامك . هو يبيد هؤلاء الأمم من قدامك فترثهم . يشوع عابر قدامك ، كما قال الرب '),
(10336, 'Deuteronomy', 5, 31, 4, ' ويفعل الرب بهم كما فعل بسيحون وعوج ملكي الأموريين اللذين أهلكهما ، وبأرضهما '),
(10337, 'Deuteronomy', 5, 31, 5, ' فمتى دفعهم الرب أمامكم تفعلون بهم حسب كل الوصايا التي أوصيتكم بها '),
(10338, 'Deuteronomy', 5, 31, 6, ' تشددوا وتشجعوا . لا تخافوا ولا ترهبوا وجوههم ، لأن الرب إلهك سائر معك . لا يهملك ولا يتركك '),
(10339, 'Deuteronomy', 5, 31, 7, ' فدعا موسى يشوع ، وقال له أمام أعين جميع إسرائيل : تشدد وتشجع ، لأنك أنت تدخل مع هذا الشعب الأرض التي أقسم الرب لآبائهم أن يعطيهم إياها ، وأنت تقسمها لهم '),
(10340, 'Deuteronomy', 5, 31, 8, ' والرب سائر أمامك . هو يكون معك . لا يهملك ولا يتركك . لا تخف ولا ترتعب '),
(10341, 'Deuteronomy', 5, 31, 9, ' وكتب موسى هذه التوراة وسلمها للكهنة بني لاوي حاملي تابوت عهد الرب ، ولجميع شيوخ إسرائيل '),
(10342, 'Deuteronomy', 5, 31, 10, ' وأمرهم موسى قائلا : في نهاية السبع السنين ، في ميعاد سنة الإبراء ، في عيد المظال '),
(10343, 'Deuteronomy', 5, 31, 11, ' حينما يجيء جميع إسرائيل لكي يظهروا أمام الرب إلهك في المكان الذي يختاره ، تقرأ هذه التوراة أمام كل إسرائيل في مسامعهم '),
(10344, 'Deuteronomy', 5, 31, 12, ' اجمع الشعب ، الرجال والنساء والأطفال والغريب الذي في أبوابك ، لكي يسمعوا ويتعلموا أن يتقوا الرب إلهكم ويحرصوا أن يعملوا بجميع كلمات هذه التوراة '),
(10345, 'Deuteronomy', 5, 31, 13, ' وأولادهم الذين لم يعرفوا ، يسمعون ويتعلمون أن يتقوا الرب إلهكم كل الأيام التي تحيون فيها على الأرض التي أنتم عابرون الأردن إليها لكي تمتلكوها '),
(10346, 'Deuteronomy', 5, 31, 14, ' وقال الرب لموسى : هوذا أيامك قد قربت لكي تموت . ادع يشوع ، وقفا في خيمة الاجتماع لكي أوصيه . فانطلق موسى ويشوع ووقفا في خيمة الاجتماع '),
(10347, 'Deuteronomy', 5, 31, 15, ' فتراءى الرب في الخيمة في عمود سحاب ، ووقف عمود السحاب على باب الخيمة '),
(10348, 'Deuteronomy', 5, 31, 16, ' وقال الرب لموسى : ها أنت ترقد مع آبائك ، فيقوم هذا الشعب ويفجر وراء آلهة الأجنبيين في الأرض التي هو داخل إليها في ما بينهم ، ويتركني وينكث عهدي الذي قطعته معه '),
(10349, 'Deuteronomy', 5, 31, 17, ' فيشتعل غضبي عليه في ذلك اليوم ، وأتركه وأحجب وجهي عنه ، فيكون مأكلة ، وتصيبه شرور كثيرة وشدائد حتى يقول في ذلك اليوم : أما لأن إلهي ليس في وسطي أصابتني هذه الشرور '),
(10350, 'Deuteronomy', 5, 31, 18, ' وأنا أحجب وجهي في ذلك اليوم لأجل جميع الشر الذي عمله ، إذ التفت إلى آلهة أخرى '),
(10351, 'Deuteronomy', 5, 31, 19, ' فالآن اكتبوا لأنفسكم هذا النشيد ، وعلم بني إسرائيل إياه . ضعه في أفواههم لكي يكون لي هذا النشيد شاهدا على بني إسرائيل '),
(10352, 'Deuteronomy', 5, 31, 20, ' لأني أدخلهم الأرض التي أقسمت لآبائهم ، الفائضة لبنا وعسلا ، فيأكلون ويشبعون ويسمنون ، ثم يلتفتون إلى آلهة أخرى ويعبدونها ويزدرون بي وينكثون عهدي '),
(10353, 'Deuteronomy', 5, 31, 21, ' فمتى أصابته شرور كثيرة وشدائد ، يجاوب هذا النشيد أمامه شاهدا ، لأنه لا ينسى من أفواه نسله . إني عرفت فكره الذي يفكر به اليوم قبل أن أدخله إلى الأرض كما أقسمت '),
(10354, 'Deuteronomy', 5, 31, 22, ' فكتب موسى هذا النشيد في ذلك اليوم وعلم بني إسرائيل إياه '),
(10355, 'Deuteronomy', 5, 31, 23, ' وأوصى يشوع بن نون وقال : تشدد وتشجع ، لأنك أنت تدخل ببني إسرائيل الأرض التي أقسمت لهم عنها ، وأنا أكون معك '),
(10356, 'Deuteronomy', 5, 31, 24, ' فعندما كمل موسى كتابة كلمات هذه التوراة في كتاب إلى تمامها ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(10357, 'Deuteronomy', 5, 31, 25, ' أمر موسى اللاويين حاملي تابوت عهد الرب قائلا '),
(10358, 'Deuteronomy', 5, 31, 26, ' خذوا كتاب التوراة هذا وضعوه بجانب تابوت عهد الرب إلهكم ، ليكون هناك شاهدا عليكم '),
(10359, 'Deuteronomy', 5, 31, 27, ' لأني أنا عارف تمردكم ورقابكم الصلبة . هوذا وأنا بعد حي معكم اليوم ، قد صرتم تقاومون الرب ، فكم بالحري بعد موتي '),
(10360, 'Deuteronomy', 5, 31, 28, ' اجمعوا إلي كل شيوخ أسباطكم وعرفاءكم لأنطق في مسامعهم بهذه الكلمات ، وأشهد عليهم السماء والأرض '),
(10361, 'Deuteronomy', 5, 31, 29, ' لأني عارف أنكم بعد موتي تفسدون وتزيغون عن الطريق الذي أوصيتكم به ، ويصيبكم الشر في آخر الأيام لأنكم تعملون الشر أمام الرب حتى تغيظوه بأعمال أيديكم '),
(10362, 'Deuteronomy', 5, 31, 30, ' فنطق موسى في مسامع كل جماعة إسرائيل بكلمات هذا النشيد إلى تمامه '),
(10363, 'Deuteronomy', 5, 32, 1, ' انصتي أيتها السماوات فأتكلم ، ولتسمع الأرض أقوال فمي '),
(10364, 'Deuteronomy', 5, 32, 2, ' يهطل كالمطر تعليمي ، ويقطر كالندى كلامي . كالطل على الكلاء ، وكالوابل على العشب '),
(10365, 'Deuteronomy', 5, 32, 3, ' إني باسم الرب أنادي . أعطوا عظمة لإلهنا '),
(10366, 'Deuteronomy', 5, 32, 4, ' هو الصخر الكامل صنيعه . إن جميع سبله عدل . إله أمانة لا جور فيه . صديق وعادل هو '),
(10367, 'Deuteronomy', 5, 32, 5, ' أفسد له الذين ليسوا أولاده عيبهم ، جيل أعوج ملتو '),
(10368, 'Deuteronomy', 5, 32, 6, ' ألرب تكافئون بهذا يا شعبا غبيا غير حكيم ؟ أليس هو أباك ومقتنيك ، هو عملك وأنشأك '),
(10369, 'Deuteronomy', 5, 32, 7, ' اذكر أيام القدم ، وتأملوا سني دور فدور . اسأل أباك فيخبرك ، وشيوخك فيقولوا لك '),
(10370, 'Deuteronomy', 5, 32, 8, ' حين قسم العلي للأمم ، حين فرق بني آدم ، نصب تخوما لشعوب حسب عدد بني إسرائيل '),
(10371, 'Deuteronomy', 5, 32, 9, ' إن قسم الرب هو شعبه . يعقوب حبل نصيبه '),
(10372, 'Deuteronomy', 5, 32, 10, ' وجده في أرض قفر ، وفي خلاء مستوحش خرب . أحاط به ولاحظه وصانه كحدقة عينه '),
(10373, 'Deuteronomy', 5, 32, 11, ' كما يحرك النسر عشه وعلى فراخه يرف ، ويبسط جناحيه ويأخذها ويحملها على مناكبه '),
(10374, 'Deuteronomy', 5, 32, 12, ' هكذا الرب وحده اقتاده وليس معه إله أجنبي '),
(10375, 'Deuteronomy', 5, 32, 13, ' أركبه على مرتفعات الأرض فأكل ثمار الصحراء ، وأرضعه عسلا من حجر ، وزيتا من صوان الصخر '),
(10376, 'Deuteronomy', 5, 32, 14, ' وزبدة بقر ولبن غنم ، مع شحم خراف وكباش أولاد باشان ، وتيوس مع دسم لب الحنطة ، ودم العنب شربته خمرا '),
(10377, 'Deuteronomy', 5, 32, 15, ' فسمن يشورون ورفس . سمنت وغلظت واكتسيت شحما فرفض الإله الذي عمله ، وغبي عن صخرة خلاصه '),
(10378, 'Deuteronomy', 5, 32, 16, ' أغاروه بالأجانب ، وأغاظوه بالأرجاس '),
(10379, 'Deuteronomy', 5, 32, 17, ' ذبحوا لأوثان ليست الله . لآلهة لم يعرفوها ، أحداث قد جاءت من قريب لم يرهبها آباؤكم '),
(10380, 'Deuteronomy', 5, 32, 18, ' الصخر الذي ولدك تركته ، ونسيت الله الذي أبدأك '),
(10381, 'Deuteronomy', 5, 32, 19, ' فرأى الرب ورذل من الغيظ بنيه وبناته '),
(10382, 'Deuteronomy', 5, 32, 20, ' وقال : أحجب وجهي عنهم ، وأنظر ماذا تكون آخرتهم . إنهم جيل متقلب ، أولاد لا أمانة فيهم '),
(10383, 'Deuteronomy', 5, 32, 21, ' هم أغاروني بما ليس إلها ، أغاظوني بأباطيلهم . فأنا أغيرهم بما ليس شعبا ، بأمة غبية أغيظهم '),
(10384, 'Deuteronomy', 5, 32, 22, ' إنه قد اشتعلت نار بغضبي فتتقد إلى الهاوية السفلى ، وتأكل الأرض وغلتها ، وتحرق أسس الجبال '),
(10385, 'Deuteronomy', 5, 32, 23, ' أجمع عليهم شرورا ، وأنفذ سهامي فيهم '),
(10386, 'Deuteronomy', 5, 32, 24, ' إذ هم خاوون من جوع ، ومنهوكون من حمى وداء سام ، أرسل فيهم أنياب الوحوش مع حمة زواحف الأرض '),
(10387, 'Deuteronomy', 5, 32, 25, ' من خارج السيف يثكل ، ومن داخل الخدور الرعبة . الفتى مع الفتاة والرضيع مع الأشيب '),
(10388, 'Deuteronomy', 5, 32, 26, ' قلت : أبددهم إلى الزوايا ، وأبطل من الناس ذكرهم '),
(10389, 'Deuteronomy', 5, 32, 27, ' لو لم أخف من إغاظة العدو ، من أن ينكر أضدادهم ، من أن يقولوا : يدنا ارتفعت وليس الرب فعل كل هذه '),
(10390, 'Deuteronomy', 5, 32, 28, ' إنهم أمة عديمة الرأي ولا بصيرة فيهم '),
(10391, 'Deuteronomy', 5, 32, 29, ' لو عقلوا لفطنوا بهذه وتأملوا آخرتهم '),
(10392, 'Deuteronomy', 5, 32, 30, ' كيف يطرد واحد ألفا ، ويهزم اثنان ربوة ، لولا أن صخرهم باعهم والرب سلمهم '),
(10393, 'Deuteronomy', 5, 32, 31, ' لأنه ليس كصخرنا صخرهم ، ولو كان أعداؤنا القضاة '),
(10394, 'Deuteronomy', 5, 32, 32, ' لأن من جفنة سدوم جفنتهم ، ومن كروم عمورة . عنبهم عنب سم ، ولهم عناقيد مرارة '),
(10395, 'Deuteronomy', 5, 32, 33, ' خمرهم حمة الثعابين وسم الأصلال القاتل '),
(10396, 'Deuteronomy', 5, 32, 34, ' أليس ذلك مكنوزا عندي ، مختوما عليه في خزائني '),
(10397, 'Deuteronomy', 5, 32, 35, ' لي النقمة والجزاء . في وقت تزل أقدامهم . إن يوم هلاكهم قريب والمهيآت لهم مسرعة '),
(10398, 'Deuteronomy', 5, 32, 36, ' لأن الرب يدين شعبه ، وعلى عبيده يشفق . حين يرى أن اليد قد مضت ، ولم يبق محجوز ولا مطلق '),
(10399, 'Deuteronomy', 5, 32, 37, ' يقول : أين آلهتهم ، الصخرة التي التجأوا إليها '),
(10400, 'Deuteronomy', 5, 32, 38, ' التي كانت تأكل شحم ذبائحهم وتشرب خمر سكائبهم ؟ لتقم وتساعدكم وتكن عليكم حماية '),
(10401, 'Deuteronomy', 5, 32, 39, ' انظروا الآن أنا أنا هو وليس إله معي . أنا أميت وأحيي . سحقت ، وإني أشفي ، وليس من يدي مخلص '),
(10402, 'Deuteronomy', 5, 32, 40, ' إني أرفع إلى السماء يدي وأقول : حي أنا إلى الأبد '),
(10403, 'Deuteronomy', 5, 32, 41, ' إذا سننت سيفي البارق ، وأمسكت بالقضاء يدي ، أرد نقمة على أضدادي ، وأجازي مبغضي '),
(10404, 'Deuteronomy', 5, 32, 42, ' أسكر سهامي بدم ، ويأكل سيفي لحما . بدم القتلى والسبايا ، ومن رؤوس قواد العدو '),
(10405, 'Deuteronomy', 5, 32, 43, ' تهللوا أيها الأمم ، شعبه ، لأنه ينتقم بدم عبيده ، ويرد نقمة على أضداده ، ويصفح عن أرضه عن شعبه '),
(10406, 'Deuteronomy', 5, 32, 44, ' فأتى موسى ونطق بجميع كلمات هذا النشيد في مسامع الشعب ، هو ويشوع بن نون '),
(10407, 'Deuteronomy', 5, 32, 45, ' ولما فرغ موسى من مخاطبة جميع إسرائيل بكل هذه الكلمات '),
(10408, 'Deuteronomy', 5, 32, 46, ' قال لهم : وجهوا قلوبكم إلى جميع الكلمات التي أنا أشهد عليكم بها اليوم ، لكي توصوا بها أولادكم ، ليحرصوا أن يعملوا بجميع كلمات هذه التوراة '),
(10409, 'Deuteronomy', 5, 32, 47, ' لأنها ليست أمرا باطلا عليكم ، بل هي حياتكم . وبهذا الأمر تطيلون الأيام على الأرض التي أنتم عابرون الأردن إليها لتمتلكوها '),
(10410, 'Deuteronomy', 5, 32, 48, ' وكلم الرب موسى في نفس ذلك اليوم قائلا '),
(10411, 'Deuteronomy', 5, 32, 49, ' اصعد إلى جبل عباريم هذا ، جبل نبو الذي في أرض موآب الذي قبالة أريحا ، وانظر أرض كنعان التي أنا أعطيها لبني إسرائيل ملكا '),
(10412, 'Deuteronomy', 5, 32, 50, ' ومت في الجبل الذي تصعد إليه ، وانضم إلى قومك ، كما مات هارون أخوك في جبل هور وضم إلى قومه '),
(10413, 'Deuteronomy', 5, 32, 51, ' لأنكما خنتماني في وسط بني إسرائيل عند ماء مريبة قادش في برية صين ، إذ لم تقدساني في وسط بني إسرائيل '),
(10414, 'Deuteronomy', 5, 32, 52, ' فإنك تنظر الأرض من قبالتها ، ولكنك لا تدخل إلى هناك إلى الأرض التي أنا أعطيها لبني إسرائيل '),
(10415, 'Deuteronomy', 5, 33, 1, ' وهذه هي البركة التي بارك بها موسى ، رجل الله ، بني إسرائيل قبل موته '),
(10416, 'Deuteronomy', 5, 33, 2, ' فقال : جاء الرب من سيناء ، وأشرق لهم من سعير ، وتلألأ من جبل فاران ، وأتى من ربوات القدس ، وعن يمينه نار شريعة لهم '),
(10417, 'Deuteronomy', 5, 33, 3, ' فأحب الشعب . جميع قديسيه في يدك ، وهم جالسون عند قدمك يتقبلون من أقوالك '),
(10418, 'Deuteronomy', 5, 33, 4, ' بناموس أوصانا موسى ميراثا لجماعة يعقوب '),
(10419, 'Deuteronomy', 5, 33, 5, ' وكان في يشورون ملكا حين اجتمع رؤساء الشعب أسباط إسرائيل معا '),
(10420, 'Deuteronomy', 5, 33, 6, ' ليحي رأوبين ولا يمت ، ولا يكن رجاله قليلين '),
(10421, 'Deuteronomy', 5, 33, 7, ' وهذه عن يهوذا قال : اسمع يارب صوت يهوذا ، وأت به إلى قومه . بيديه يقاتل لنفسه ، فكن عونا على أضداده '),
(10422, 'Deuteronomy', 5, 33, 8, ' وللاوي قال : تميمك وأوريمك لرجلك الصديق ، الذي جربته في مسة وخاصمته عند ماء مريبة '),
(10423, 'Deuteronomy', 5, 33, 9, ' الذي قال عن أبيه وأمه : لم أرهما ، وبإخوته لم يعترف ، وأولاده لم يعرف ، بل حفظوا كلامك وصانوا عهدك '),
(10424, 'Deuteronomy', 5, 33, 10, ' يعلمون يعقوب أحكامك ، وإسرائيل ناموسك . يضعون بخورا في أنفك ، ومحرقات على مذبحك '),
(10425, 'Deuteronomy', 5, 33, 11, ' بارك يارب قوته ، وارتض بعمل يديه . احطم متون مقاوميه ومبغضيه حتى لا يقوموا '),
(10426, 'Deuteronomy', 5, 33, 12, ' ولبنيامين قال : حبيب الرب يسكن لديه آمنا . يستره طول النهار ، وبين منكبيه يسكن '),
(10427, 'Deuteronomy', 5, 33, 13, ' وليوسف قال : مباركة من الرب أرضه ، بنفائس السماء بالندى ، وباللجة الرابضة تحت '),
(10428, 'Deuteronomy', 5, 33, 14, ' ونفائس مغلات الشمس ، ونفائس منبتات الأقمار '),
(10429, 'Deuteronomy', 5, 33, 15, ' ومن مفاخر الجبال القديمة ، ومن نفائس الإكام الأبدية '),
(10430, 'Deuteronomy', 5, 33, 16, ' ومن نفائس الأرض وملئها ، ورضى الساكن في العليقة . فلتأت على رأس يوسف وعلى قمة نذير إخوته '),
(10431, 'Deuteronomy', 5, 33, 17, ' بكر ثوره زينة له ، وقرناه قرنا رئم . بهما ينطح الشعوب معا إلى أقاصي الأرض . هما ربوات أفرايم وألوف منسى '),
(10432, 'Deuteronomy', 5, 33, 18, ' ولزبولون قال : افرح يا زبولون بخروجك ، وأنت يا يساكر بخيامك '),
(10433, 'Deuteronomy', 5, 33, 19, ' إلى الجبل يدعوان القبائل . هناك يذبحان ذبائح البر لأنهما يرتضعان من فيض البحار ، وذخائر مطمورة في الرمل '),
(10434, 'Deuteronomy', 5, 33, 20, ' ولجاد قال : مبارك الذي وسع جاد . كلبوة سكن وافترس الذراع مع قمة الرأس '),
(10435, 'Deuteronomy', 5, 33, 21, ' ورأى الأول لنفسه ، لأنه هناك قسم من الشارع محفوظا ، فأتى رأسا للشعب ، يعمل حق الرب وأحكامه مع إسرائيل '),
(10436, 'Deuteronomy', 5, 33, 22, ' ولدان قال : دان شبل أسد يثب من باشان '),
(10437, 'Deuteronomy', 5, 33, 23, ' ولنفتالي قال : يا نفتالي اشبع رضى ، وامتليء بركة من الرب ، واملك الغرب والجنوب '),
(10438, 'Deuteronomy', 5, 33, 24, ' ولأشير قال : مبارك من البنين أشير . ليكن مقبولا من إخوته ، ويغمس في الزيت رجله '),
(10439, 'Deuteronomy', 5, 33, 25, ' حديد ونحاس مزاليجك ، وكأيامك راحتك '),
(10440, 'Deuteronomy', 5, 33, 26, ' ليس مثل الله يا يشورون . يركب السماء في معونتك ، والغمام في عظمته '),
(10441, 'Deuteronomy', 5, 33, 27, ' الإله القديم ملجأ ، والأذرع الأبدية من تحت . فطرد من قدامك العدو وقال : أهلك '),
(10442, 'Deuteronomy', 5, 33, 28, ' فيسكن إسرائيل آمنا وحده . تكون عين يعقوب إلى أرض حنطة وخمر ، وسماؤه تقطر ندى '),
(10443, 'Deuteronomy', 5, 33, 29, ' طوباك يا إسرائيل من مثلك يا شعبا منصورا بالرب ؟ ترس عونك وسيف عظمتك فيتذلل لك أعداؤك ، وأنت تطأ مرتفعاتهم '),
(10444, 'Deuteronomy', 5, 34, 1, ' وصعد موسى من عربات موآب إلى جبل نبو ، إلى رأس الفسجة الذي قبالة أريحا ، فأراه الرب جميع الأرض من جلعاد إلى دان '),
(10445, 'Deuteronomy', 5, 34, 2, ' وجميع نفتالي وأرض أفرايم ومنسى ، وجميع أرض يهوذا إلى البحر الغربي '),
(10446, 'Deuteronomy', 5, 34, 3, ' والجنوب والدائرة بقعة أريحا مدينة النخل ، إلى صوغر '),
(10447, 'Deuteronomy', 5, 34, 4, ' وقال له الرب : هذه هي الأرض التي أقسمت لإبراهيم وإسحاق ويعقوب قائلا : لنسلك أعطيها . قد أريتك إياها بعينيك ، ولكنك إلى هناك لا تعبر '),
(10448, 'Deuteronomy', 5, 34, 5, ' فمات هناك موسى عبد الرب في أرض موآب حسب قول الرب '),
(10449, 'Deuteronomy', 5, 34, 6, ' ودفنه في الجواء في أرض موآب ، مقابل بيت فغور . ولم يعرف إنسان قبره إلى هذا اليوم '),
(10450, 'Deuteronomy', 5, 34, 7, ' وكان موسى ابن مئة وعشرين سنة حين مات ، ولم تكل عينه ولا ذهبت نضارته '),
(10451, 'Deuteronomy', 5, 34, 8, ' فبكى بنو إسرائيل موسى في عربات موآب ثلاثين يوما . فكملت أيام بكاء مناحة موسى '),
(10452, 'Deuteronomy', 5, 34, 9, ' ويشوع بن نون كان قد امتلأ روح حكمة ، إذ وضع موسى عليه يديه ، فسمع له بنو إسرائيل وعملوا كما أوصى الرب موسى '),
(10453, 'Deuteronomy', 5, 34, 10, ' ولم يقم بعد نبي في إسرائيل مثل موسى الذي عرفه الرب وجها لوجه '),
(10454, 'Ecclesiastes', 21, 7, 7, ' لأن الظلم يحمق الحكيم ، والعطية تفسد القلب '),
(10455, 'Ecclesiastes', 21, 7, 8, ' نهاية أمر خير من بدايته . طول الروح خير من تكبر الروح '),
(10456, 'Ecclesiastes', 21, 7, 9, ' لا تسرع بروحك إلى الغضب ، لأن الغضب يستقر في حضن الجهال '),
(10457, 'Ecclesiastes', 21, 7, 10, ' لا تقل : لماذا كانت الأيام الأولى خيرا من هذه ؟  ، لأنه ليس عن حكمة تسأل عن هذا '),
(10458, 'Ecclesiastes', 21, 7, 11, ' الحكمة صالحة مثل الميراث ، بل أفضل لناظري الشمس '),
(10459, 'Ecclesiastes', 21, 7, 12, ' لأن الذي في ظل الحكمة هو في ظل الفضة ، وفضل المعرفة هو إن الحكمة تحيي أصحابها '),
(10460, 'Ecclesiastes', 21, 7, 13, ' انظر عمل الله : لأنه من يقدر على تقويم ما قد عوجه '),
(10461, 'Ecclesiastes', 21, 7, 14, ' في يوم الخير كن بخير ، وفي يوم الشر اعتبر . إن الله جعل هذا مع ذاك ، لكيلا يجد الإنسان شيئا بعده '),
(10462, 'Ecclesiastes', 21, 7, 15, ' قد رأيت الكل في أيام بطلي : قد يكون بار يبيد في بره ، وقد يكون شرير يطول في شره '),
(10463, 'Ecclesiastes', 21, 7, 16, ' لا تكن بارا كثيرا ، ولا تكن حكيما بزيادة . لماذا تخرب نفسك '),
(10464, 'Ecclesiastes', 21, 7, 17, ' لا تكن شريرا كثيرا ، ولا تكن جاهلا . لماذا تموت في غير وقتك '),
(10465, 'Ecclesiastes', 21, 7, 18, ' حسن أن تتمسك بهذا ، وأيضا أن لا ترخي يدك عن ذاك ، لأن متقي الله يخرج منهما كليهما '),
(10466, 'Ecclesiastes', 21, 7, 19, ' الحكمة تقوي الحكيم أكثر من عشرة مسلطين ، الذين هم في المدينة '),
(10467, 'Ecclesiastes', 21, 7, 20, ' لأنه لا إنسان صديق في الأرض يعمل صلاحا ولا يخطئ '),
(10468, 'Ecclesiastes', 21, 7, 21, ' أيضا لا تضع قلبك على كل الكلام الذي يقال ، لئلا تسمع عبدك يسبك '),
(10469, 'Ecclesiastes', 21, 7, 22, ' لأن قلبك أيضا يعلم أنك أنت كذلك مرارا كثيرة سببت آخرين '),
(10470, 'Ecclesiastes', 21, 7, 23, ' كل هذا امتحنته بالحكمة . قلت : أكون حكيما . أما هي فبعيدة عني '),
(10471, 'Ecclesiastes', 21, 7, 24, ' بعيد ما كان بعيدا ، والعميق العميق من يجده '),
(10472, 'Ecclesiastes', 21, 7, 25, ' درت أنا وقلبي لأعلم ولأبحث ولأطلب حكمة وعقلا ، ولأعرف الشر أنه جهالة ، والحماقة أنها جنون '),
(10473, 'Ecclesiastes', 21, 7, 26, ' فوجدت أمر من الموت : المرأة التي هي شباك ، وقلبها أشراك ، ويداها قيود . الصالح قدام الله ينجو منها . أما الخاطئ فيؤخذ بها '),
(10474, 'Ecclesiastes', 21, 7, 27, ' انظر . هذا وجدته ، قال الجامعة : واحدة فواحدة لأجد النتيجة '),
(10475, 'Ecclesiastes', 21, 7, 28, ' التي لم تزل نفسي تطلبها فلم أجدها . رجلا واحدا بين ألف وجدت ، أما امرأة فبين كل أولئك لم أجد '),
(10476, 'Ecclesiastes', 21, 7, 29, ' انظر هذا وجدت فقط : أن الله صنع الإنسان مستقيما ، أما هم فطلبوا اختراعات كثيرة '),
(10477, 'Ecclesiastes', 21, 8, 1, ' من كالحكيم ؟ ومن يفهم تفسير أمر ؟ حكمة الإنسان تنير وجهه ، وصلابة وجهه تتغير '),
(10478, 'Ecclesiastes', 21, 8, 2, ' أنا أقول : احفظ أمر الملك ، وذاك بسبب يمين الله '),
(10479, 'Ecclesiastes', 21, 8, 3, ' لا تعجل إلى الذهاب من وجهه . لا تقف في أمر شاق ، لأنه يفعل كل ما شاء '),
(10480, 'Ecclesiastes', 21, 8, 4, ' حيث تكون كلمة الملك فهناك سلطان . ومن يقول له : ماذا تفعل '),
(10481, 'Ecclesiastes', 21, 8, 5, ' حافظ الوصية لا يشعر بأمر شاق ، وقلب الحكيم يعرف الوقت والحكم '),
(10482, 'Ecclesiastes', 21, 8, 6, ' لأن لكل أمر وقتا وحكما . لأن شر الإنسان عظيم عليه '),
(10483, 'Ecclesiastes', 21, 8, 7, ' لأنه لا يعلم ما سيكون . لأنه من يخبره كيف يكون '),
(10484, 'Ecclesiastes', 21, 8, 8, ' ليس لإنسان سلطان على الروح ليمسك الروح ، ولا سلطان على يوم الموت ، ولا تخلية في الحرب ، ولا ينجي الشر أصحابه '),
(10485, 'Ecclesiastes', 21, 8, 9, ' كل هذا رأيته إذ وجهت قلبي لكل عمل عمل تحت الشمس ، وقتما يتسلط إنسان على إنسان لضرر نفسه '),
(10486, 'Ecclesiastes', 21, 8, 10, ' وهكذا رأيت أشرارا يدفنون وضموا ، والذين عملوا بالحق ذهبوا من مكان القدس ونسوا في المدينة . هذا أيضا باطل '),
(10487, 'Ecclesiastes', 21, 8, 11, ' لأن القضاء على العمل الرديء لا يجرى سريعا ، فلذلك قد امتلأ قلب بني البشر فيهم لفعل الشر '),
(10488, 'Ecclesiastes', 21, 8, 12, ' الخاطئ وإن عمل شرا مئة مرة وطالت أيامه ، إلا أني أعلم أنه يكون خير للمتقين الله الذين يخافون قدامه '),
(10489, 'Ecclesiastes', 21, 8, 13, ' ولا يكون خير للشرير ، وكالظل لا يطيل أيامه لأنه لا يخشى قدام الله '),
(10490, 'Ecclesiastes', 21, 8, 14, ' يوجد باطل يجرى على الأرض : أن يوجد صديقون يصيبهم مثل عمل الأشرار ، ويوجد أشرار يصيبهم مثل عمل الصديقين . فقلت : إن هذا أيضا باطل '),
(10491, 'Ecclesiastes', 21, 8, 15, ' فمدحت الفرح ، لأنه ليس للإنسان خير تحت الشمس ، إلا أن يأكل ويشرب ويفرح ، وهذا يبقى له في تعبه مدة أيام حياته التي يعطيه الله إياها تحت الشمس '),
(10492, 'Ecclesiastes', 21, 8, 16, ' لما وجهت قلبي لأعرف الحكمة ، وأنظر العمل الذي عمل على الأرض ، وأنه نهارا وليلا لا يرى النوم بعينيه '),
(10493, 'Ecclesiastes', 21, 8, 17, ' رأيت كل عمل الله أن الإنسان لا يستطيع أن يجد العمل الذي عمل تحت الشمس . مهما تعب الإنسان في الطلب فلا يجده ، والحكيم أيضا ، وإن قال بمعرفته ، لا يقدر أن يجده '),
(10494, 'Ecclesiastes', 21, 9, 1, ' لأن هذا كله جعلته في قلبي ، وامتحنت هذا كله : أن الصديقين والحكماء وأعمالهم في يد الله . الإنسان لا يعلم حبا ولا بغضا . الكل أمامهم '),
(10495, 'Ecclesiastes', 21, 9, 2, ' الكل على ما للكل . حادثة واحدة للصديق وللشرير ، للصالح وللطاهر وللنجس ، للذابح وللذي لا يذبح ، كالصالح الخاطئ . الحالف كالذي يخاف الحلف '),
(10496, 'Ecclesiastes', 21, 9, 3, ' هذا أشر كل ما عمل تحت الشمس : أن حادثة واحدة للجميع . وأيضا قلب بني البشر ملآن من الشر ، والحماقة في قلبهم وهم أحياء ، وبعد ذلك يذهبون إلى الأموات '),
(10497, 'Ecclesiastes', 21, 9, 4, ' لأنه من يستثنى ؟ لكل الأحياء يوجد رجاء ، فإن الكلب الحي خير من الأسد الميت '),
(10498, 'Ecclesiastes', 21, 9, 5, ' لأن الأحياء يعلمون أنهم سيموتون ، أما الموتى فلا يعلمون شيئا ، وليس لهم أجر بعد لأن ذكرهم نسي '),
(10499, 'Ecclesiastes', 21, 9, 6, ' ومحبتهم وبغضتهم وحسدهم هلكت منذ زمان ، ولا نصيب لهم بعد إلى الأبد ، في كل ما عمل تحت الشمس '),
(10500, 'Ecclesiastes', 21, 9, 7, ' اذهب كل خبزك بفرح ، واشرب خمرك بقلب طيب ، لأن الله منذ زمان قد رضي عملك '),
(10501, 'Ecclesiastes', 21, 9, 8, ' لتكن ثيابك في كل حين بيضاء ، ولا يعوز رأسك الدهن '),
(10502, 'Ecclesiastes', 21, 9, 9, ' التذ عيشا مع المرأة التي أحببتها كل أيام حياة باطلك التي أعطاك إياها تحت الشمس ، كل أيام باطلك ، لأن ذلك نصيبك في الحياة وفي تعبك الذي تتعبه تحت الشمس '),
(10503, 'Ecclesiastes', 21, 9, 10, ' كل ما تجده يدك لتفعله فافعله بقوتك ، لأنه ليس من عمل ولا اختراع ولا معرفة ولا حكمة في الهاوية التي أنت ذاهب إليها '),
(10504, 'Ecclesiastes', 21, 9, 11, ' فعدت ورأيت تحت الشمس : أن السعي ليس للخفيف ، ولا الحرب للأقوياء ، ولا الخبز للحكماء ، ولا الغنى للفهماء ، ولا النعمة لذوي المعرفة ، لأنه الوقت والعرض يلاقيانهم كافة '),
(10505, 'Ecclesiastes', 21, 9, 12, ' لأن الإنسان أيضا لا يعرف وقته . كالأسماك التي تؤخذ بشبكة مهلكة ، وكالعصافير التي تؤخذ بالشرك ، كذلك تقتنص بنو البشر في وقت شر ، إذ يقع عليهم بغتة '),
(10506, 'Ecclesiastes', 21, 9, 13, ' هذه الحكمة رأيتها أيضا تحت الشمس ، وهي عظيمة عندي '),
(10507, 'Ecclesiastes', 21, 9, 14, ' مدينة صغيرة فيها أناس قليلون ، فجاء عليها ملك عظيم وحاصرها وبنى عليها أبراجا عظيمة '),
(10508, 'Ecclesiastes', 21, 9, 15, ' ووجد فيها رجل مسكين حكيم ، فنجى هو المدينة بحكمته . وما أحد ذكر ذلك الرجل المسكين '),
(10509, 'Ecclesiastes', 21, 9, 16, ' فقلت : الحكمة خير من القوة . أما حكمة المسكين فمحتقرة ، وكلامه لا يسمع '),
(10510, 'Ecclesiastes', 21, 9, 17, ' كلمات الحكماء تسمع في الهدوء ، أكثر من صراخ المتسلط بين الجهال '),
(10511, 'Ecclesiastes', 21, 9, 18, ' الحكمة خير من أدوات الحرب . أما خاطئ واحد فيفسد خيرا جزيلا '),
(10512, 'Ecclesiastes', 21, 10, 1, ' الذباب الميت ينتن ويخمر طيب العطار . جهالة قليلة أثقل من الحكمة ومن الكرامة '),
(10513, 'Ecclesiastes', 21, 10, 2, ' قلب الحكيم عن يمينه ، وقلب الجاهل عن يساره '),
(10514, 'Ecclesiastes', 21, 10, 3, ' أيضا إذا مشى الجاهل في الطريق ينقص فهمه ، ويقول لكل واحد : إنه جاهل '),
(10515, 'Ecclesiastes', 21, 10, 4, ' إن صعدت عليك روح المتسلط ، فلا تترك مكانك ، لأن الهدوء يسكن خطايا عظيمة '),
(10516, 'Ecclesiastes', 21, 10, 5, ' يوجد شر رأيته تحت الشمس ، كسهو صادر من قبل المتسلط '),
(10517, 'Ecclesiastes', 21, 10, 6, ' الجهالة جعلت في معالي كثيرة ، والأغنياء يجلسون في السافل '),
(10518, 'Ecclesiastes', 21, 10, 7, ' قد رأيت عبيدا على الخيل ، ورؤساء ماشين على الأرض كالعبيد '),
(10519, 'Ecclesiastes', 21, 10, 8, ' من يحفر هوة يقع فيها ، ومن ينقض جدارا تلدغه حية '),
(10520, 'Ecclesiastes', 21, 10, 9, ' من يقلع حجارة يوجع بها . من يشقق حطبا يكون في خطر منه '),
(10521, 'Ecclesiastes', 21, 10, 10, ' إن كل الحديد ولم يسنن هو حده ، فليزد القوة . أما الحكمة فنافعة للإنجاح '),
(10522, 'Ecclesiastes', 21, 10, 11, ' إن لدغت الحية بلا رقية ، فلا منفعة للراقي '),
(10523, 'Ecclesiastes', 21, 10, 12, ' كلمات فم الحكيم نعمة ، وشفتا الجاهل تبتلعانه '),
(10524, 'Ecclesiastes', 21, 10, 13, ' ابتداء كلام فمه جهالة ، وآخر فمه جنون رديء '),
(10525, 'Ecclesiastes', 21, 10, 14, ' والجاهل يكثر الكلام . لا يعلم إنسان ما يكون . و ماذا يصير بعده ، من يخبره '),
(10526, 'Ecclesiastes', 21, 10, 15, ' تعب الجهلاء يعييهم ، لأنه لا يعلم كيف يذهب إلى المدينة '),
(10527, 'Ecclesiastes', 21, 10, 16, ' ويل لك أيتها الأرض إذا كان ملكك ولدا ، ورؤساؤك يأكلون في الصباح '),
(10528, 'Ecclesiastes', 21, 10, 17, ' طوبى لك أيتها الأرض إذا كان ملكك ابن شرفاء ، ورؤساؤك يأكلون في الوقت للقوة لا للسكر '),
(10529, 'Ecclesiastes', 21, 10, 18, ' بالكسل الكثير يهبط السقف ، وبتدلي اليدين يكف البيت '),
(10530, 'Ecclesiastes', 21, 10, 19, ' للضحك يعملون وليمة ، والخمر تفرح العيش . أما الفضة فتحصل الكل '),
(10531, 'Ecclesiastes', 21, 10, 20, ' لا تسب الملك ولا في فكرك ، ولا تسب الغني في مضجعك ، لأن طير السماء ينقل الصوت ، وذو الجناح يخبر بالأمر '),
(10532, 'Ecclesiastes', 21, 11, 1, ' ارم خبزك على وجه المياه فإنك تجده بعد أيام كثيرة '),
(10533, 'Ecclesiastes', 21, 11, 2, ' أعط نصيبا لسبعة ، ولثمانية أيضا ، لأنك لست تعلم أي شر يكون على الأرض '),
(10534, 'Ecclesiastes', 21, 11, 3, ' إذا امتلأت السحب مطرا تريقه على الأرض . وإذا وقعت الشجرة نحو الجنوب أو نحو الشمال ، ففي الموضع حيث تقع الشجرة هناك تكون '),
(10535, 'Ecclesiastes', 21, 11, 4, ' من يرصد الريح لا يزرع ، ومن يراقب السحب لا يحصد '),
(10536, 'Ecclesiastes', 21, 11, 5, ' كما أنك لست تعلم ما هي طريق الريح ، ولا كيف العظام في بطن الحبلى ، كذلك لا تعلم أعمال الله الذي يصنع الجميع '),
(10537, 'Ecclesiastes', 21, 11, 6, ' في الصباح ازرع زرعك ، وفي المساء لا ترخ يدك ، لأنك لا تعلم أيهما ينمو : هذا أو ذاك ، أو أن يكون كلاهما جيدين سواء '),
(10538, 'Ecclesiastes', 21, 11, 7, ' النور حلو ، وخير للعينين أن تنظرا الشمس '),
(10539, 'Ecclesiastes', 21, 11, 8, ' لأنه إن عاش الإنسان سنين كثيرة فليفرح فيها كلها ، وليتذكر أيام الظلمة لأنها تكون كثيرة . كل ما يأتي باطل '),
(10540, 'Ecclesiastes', 21, 11, 9, ' افرح أيها الشاب في حداثتك ، وليسرك قلبك في أيام شبابك ، واسلك في طرق قلبك وبمرأى عينيك ، واعلم أنه على هذه الأمور كلها يأتي بك الله إلى الدينونة '),
(10541, 'Ecclesiastes', 21, 11, 10, ' فانزع الغم من قلبك ، وأبعد الشر عن لحمك ، لأن الحداثة والشباب باطلان '),
(10542, 'Ecclesiastes', 21, 12, 1, ' فاذكر خالقك في أيام شبابك ، قبل أن تأتي أيام الشر أو تجيء السنون إذ تقول : ليس لي فيها سرور '),
(10543, 'Ecclesiastes', 21, 12, 2, ' قبل ما تظلم الشمس والنور والقمر والنجوم ، وترجع السحب بعد المطر '),
(10544, 'Ecclesiastes', 21, 12, 3, ' في يوم يتزعزع فيه حفظة البيت ، وتتلوى رجال القوة ، وتبطل الطواحن لأنها قلت ، وتظلم النواظر من الشبابيك '),
(10545, 'Ecclesiastes', 21, 12, 4, ' وتغلق الأبواب في السوق . حين ينخفض صوت المطحنة ، ويقوم لصوت العصفور ، وتحط كل بنات الغناء '),
(10546, 'Ecclesiastes', 21, 12, 5, ' وأيضا يخافون من العالي ، وفي الطريق أهوال ، واللوز يزهر ، والجندب يستثقل ، والشهوة تبطل . لأن الإنسان ذاهب إلى بيته الأبدي ، والنادبون يطوفون في السوق '),
(10547, 'Ecclesiastes', 21, 12, 6, ' قبل ما ينفصم حبل الفضة ، أو ينسحق كوز الذهب ، أو تنكسر الجرة على العين ، أو تنقصف البكرة عند البئر '),
(10548, 'Ecclesiastes', 21, 12, 7, ' فيرجع التراب إلى الأرض كما كان ، وترجع الروح إلى الله الذي أعطاها '),
(10549, 'Ecclesiastes', 21, 12, 8, ' باطل الأباطيل ، قال الجامعة : الكل باطل '),
(10550, 'Ecclesiastes', 21, 12, 9, ' بقي أن الجامعة كان حكيما ، وأيضا علم الشعب علما ، ووزن وبحث وأتقن أمثالا كثيرة '),
(10551, 'Ecclesiastes', 21, 12, 10, ' الجامعة طلب أن يجد كلمات مسرة مكتوبة بالاستقامة ، كلمات حق '),
(10552, 'Ecclesiastes', 21, 12, 11, ' كلام الحكماء كالمناسيس ، وكأوتاد منغرزة ، أرباب الجماعات ، قد أعطيت من راع واحد '),
(10553, 'Ecclesiastes', 21, 12, 12, ' وبقي ، فمن هذا يا ابني تحذر : لعمل كتب كثيرة لا نهاية ، والدرس الكثير تعب للجسد '),
(10554, 'Ecclesiastes', 21, 12, 13, ' فلنسمع ختام الأمر كله : اتق الله واحفظ وصاياه ، لأن هذا هو الإنسان كله '),
(10555, 'Ecclesiastes', 21, 12, 14, ' لأن الله يحضر كل عمل إلى الدينونة ، على كل خفي ، إن كان خيرا أو شرا '),
(10556, 'Ecclesiastes', 21, 1, 1, ' كلام الجامعة ابن داود الملك في أورشليم '),
(10557, 'Ecclesiastes', 21, 1, 2, ' باطل الأباطيل ، قال الجامعة : باطل الأباطيل ، الكل باطل '),
(10558, 'Ecclesiastes', 21, 1, 3, ' ما الفائدة للإنسان من كل تعبه الذي يتعبه تحت الشمس '),
(10559, 'Ecclesiastes', 21, 1, 4, ' دور يمضي ودور يجيء ، والأرض قائمة إلى الأبد '),
(10560, 'Ecclesiastes', 21, 1, 5, ' والشمس تشرق ، والشمس تغرب ، وتسرع إلى موضعها حيث تشرق '),
(10561, 'Ecclesiastes', 21, 1, 6, ' الريح تذهب إلى الجنوب ، وتدور إلى الشمال . تذهب دائرة دورانا ، وإلى مداراتها ترجع الريح '),
(10562, 'Ecclesiastes', 21, 1, 7, ' كل الأنهار تجري إلى البحر ، والبحر ليس بملآن . إلى المكان الذي جرت منه الأنهار إلى هناك تذهب راجعة '),
(10563, 'Ecclesiastes', 21, 1, 8, ' كل الكلام يقصر . لا يستطيع الإنسان أن يخبر بالكل . العين لا تشبع من النظر ، والأذن لا تمتلئ من السمع '),
(10564, 'Ecclesiastes', 21, 1, 9, ' ما كان فهو ما يكون ، والذي صنع فهو الذي يصنع ، فليس تحت الشمس جديد '),
(10565, 'Ecclesiastes', 21, 1, 10, ' إن وجد شيء يقال عنه : انظر . هذا جديد . فهو منذ زمان كان في الدهور التي كانت قبلنا '),
(10566, 'Ecclesiastes', 21, 1, 11, ' ليس ذكر للأولين . والآخرون أيضا الذين سيكونون ، لا يكون لهم ذكر عند الذين يكونون بعدهم '),
(10567, 'Ecclesiastes', 21, 1, 12, ' أنا الجامعة كنت ملكا على إسرائيل في أورشليم '),
(10568, 'Ecclesiastes', 21, 1, 13, ' ووجهت قلبي للسؤال والتفتيش بالحكمة عن كل ما عمل تحت السماوات . هو عناء رديء جعلها الله لبني البشر ليعنوا فيه '),
(10569, 'Ecclesiastes', 21, 1, 14, ' رأيت كل الأعمال التي عملت تحت الشمس فإذا الكل باطل وقبض الريح '),
(10570, 'Ecclesiastes', 21, 1, 15, ' الأعوج لا يمكن أن يقوم ، والنقص لا يمكن أن يجبر '),
(10571, 'Ecclesiastes', 21, 1, 16, ' أنا ناجيت قلبي قائلا : ها أنا قد عظمت وازددت حكمة أكثر من كل من كان قبلي على أورشليم ، وقد رأى قلبي كثيرا من الحكمة والمعرفة '),
(10572, 'Ecclesiastes', 21, 1, 17, ' ووجهت قلبي لمعرفة الحكمة ولمعرفة الحماقة والجهل ، فعرفت أن هذا أيضا قبض الريح '),
(10573, 'Ecclesiastes', 21, 1, 18, ' لأن في كثرة الحكمة كثرة الغم ، والذي يزيد علما يزيد حزنا '),
(10574, 'Ecclesiastes', 21, 2, 1, ' قلت أنا في قلبي : هلم أمتحنك بالفرح فترى خيرا . وإذا هذا أيضا باطل '),
(10575, 'Ecclesiastes', 21, 2, 2, ' للضحك قلت : مجنون وللفرح : ماذا يفعل '),
(10576, 'Ecclesiastes', 21, 2, 3, ' افتكرت في قلبي أن أعلل جسدي بالخمر ، وقلبي يلهج بالحكمة ، وأن آخذ بالحماقة ، حتى أرى ما هو الخير لبني البشر حتى يفعلوه تحت السماوات مدة أيام حياتهم '),
(10577, 'Ecclesiastes', 21, 2, 4, ' فعظمت عملي : بنيت لنفسي بيوتا ، غرست لنفسي كروما '),
(10578, 'Ecclesiastes', 21, 2, 5, ' عملت لنفسي جنات وفراديس ، وغرست فيها أشجارا من كل نوع ثمر '),
(10579, 'Ecclesiastes', 21, 2, 6, ' عملت لنفسي برك مياه لتسقى بها المغارس المنبتة الشجر '),
(10580, 'Ecclesiastes', 21, 2, 7, ' قنيت عبيدا وجواري ، وكان لي ولدان البيت . وكانت لي أيضا قنية بقر وغنم أكثر من جميع الذين كانوا في أورشليم قبلي '),
(10581, 'Ecclesiastes', 21, 2, 8, ' جمعت لنفسي أيضا فضة وذهبا وخصوصيات الملوك والبلدان . اتخذت لنفسي مغنين ومغنيات وتنعمات بني البشر ، سيدة وسيدات '),
(10582, 'Ecclesiastes', 21, 2, 9, ' فعظمت وازددت أكثر من جميع الذين كانوا قبلي في أورشليم ، وبقيت أيضا حكمتي معي '),
(10583, 'Ecclesiastes', 21, 2, 10, ' ومهما اشتهته عيناي لم أمسكه عنهما . لم أمنع قلبي من كل فرح ، لأن قلبي فرح بكل تعبي . وهذا كان نصيبي من كل تعبي '),
(10584, 'Ecclesiastes', 21, 2, 11, ' ثم التفت أنا إلى كل أعمالي التي عملتها يداي ، وإلى التعب الذي تعبته في عمله ، فإذا الكل باطل وقبض الريح ، ولا منفعة تحت الشمس '),
(10585, 'Ecclesiastes', 21, 2, 12, ' ثم التفت لأنظر الحكمة والحماقة والجهل . فما الإنسان الذي يأتي وراء الملك الذي قد نصبوه منذ زمان '),
(10586, 'Ecclesiastes', 21, 2, 13, ' فرأيت أن للحكمة منفعة أكثر من الجهل ، كما أن للنور منفعة أكثر من الظلمة '),
(10587, 'Ecclesiastes', 21, 2, 14, ' الحكيم عيناه في رأسه ، أما الجاهل فيسلك في الظلام . وعرفت أنا أيضا أن حادثة واحدة تحدث لكليهما '),
(10588, 'Ecclesiastes', 21, 2, 15, ' فقلت في قلبي : كما يحدث للجاهل كذلك يحدث أيضا لي أنا . وإذ ذاك ، فلماذا أنا أوفر حكمة ؟  . فقلت في قلبي : هذا أيضا باطل '),
(10589, 'Ecclesiastes', 21, 2, 16, ' لأنه ليس ذكر للحكيم ولا للجاهل إلى الأبد . كما منذ زمان كذا الأيام الآتية : الكل ينسى . وكيف يموت الحكيم كالجاهل '),
(10590, 'Ecclesiastes', 21, 2, 17, ' فكرهت الحياة ، لأنه رديء عندي ، العمل الذي عمل تحت الشمس ، لأن الكل باطل وقبض الريح '),
(10591, 'Ecclesiastes', 21, 2, 18, ' فكرهت كل تعبي الذي تعبت فيه تحت الشمس حيث أتركه للإنسان الذي يكون بعدي '),
(10592, 'Ecclesiastes', 21, 2, 19, ' ومن يعلم ، هل يكون حكيما أو جاهلا ، ويستولي على كل تعبي الذي تعبت فيه وأظهرت فيه حكمتي تحت الشمس ؟ هذا أيضا باطل '),
(10593, 'Ecclesiastes', 21, 2, 20, ' فتحولت لكي أجعل قلبي ييئس من كل التعب الذي تعبت فيه تحت الشمس '),
(10594, 'Ecclesiastes', 21, 2, 21, ' لأنه قد يكون إنسان تعبه بالحكمة والمعرفة وبالفلاح ، فيتركه نصيبا لإنسان لم يتعب فيه . هذا أيضا باطل وشر عظيم '),
(10595, 'Ecclesiastes', 21, 2, 22, ' لأنه ماذا للإنسان من كل تعبه ، ومن اجتهاد قلبه الذي تعب فيه تحت الشمس '),
(10596, 'Ecclesiastes', 21, 2, 23, ' لأن كل أيامه أحزان ، وعمله غم . أيضا بالليل لا يستريح قلبه . هذا أيضا باطل هو '),
(10597, 'Ecclesiastes', 21, 2, 24, ' ليس للإنسان خير من أن يأكل ويشرب ويري نفسه خيرا في تعبه . رأيت هذا أيضا أنه من يد الله '),
(10598, 'Ecclesiastes', 21, 2, 25, ' لأنه من يأكل ومن يلتذ غيري '),
(10599, 'Ecclesiastes', 21, 2, 26, ' لأنه يؤتي الإنسان الصالح قدامه حكمة ومعرفة وفرحا ، أما الخاطئ فيعطيه شغل الجمع والتكويم ، ليعطي للصالح قدام الله . هذا أيضا باطل وقبض الريح '),
(10600, 'Ecclesiastes', 21, 3, 1, ' لكل شيء زمان ، ولكل أمر تحت السماوات وقت '),
(10601, 'Ecclesiastes', 21, 3, 2, ' للولادة وقت وللموت وقت . للغرس وقت ولقلع المغروس وقت '),
(10602, 'Ecclesiastes', 21, 3, 3, ' للقتل وقت وللشفاء وقت . للهدم وقت وللبناء وقت '),
(10603, 'Ecclesiastes', 21, 3, 4, ' للبكاء وقت وللضحك وقت . للنوح وقت وللرقص وقت '),
(10604, 'Ecclesiastes', 21, 3, 5, ' لتفريق الحجارة وقت ولجمع الحجارة وقت . للمعانقة وقت وللانفصال عن المعانقة وقت '),
(10605, 'Ecclesiastes', 21, 3, 6, ' للكسب وقت وللخسارة وقت . للصيانة وقت وللطرح وقت '),
(10606, 'Ecclesiastes', 21, 3, 7, ' للتمزيق وقت وللتخييط وقت . للسكوت وقت وللتكلم وقت '),
(10607, 'Ecclesiastes', 21, 3, 8, ' للحب وقت وللبغضة وقت . للحرب وقت وللصلح وقت '),
(10608, 'Ecclesiastes', 21, 3, 9, ' فأي منفعة لمن يتعب مما يتعب به '),
(10609, 'Ecclesiastes', 21, 3, 10, ' قد رأيت الشغل الذي أعطاه الله بني البشر ليشتغلوا به '),
(10610, 'Ecclesiastes', 21, 3, 11, ' صنع الكل حسنا في وقته ، وأيضا جعل الأبدية في قلبهم ، التي بلاها لا يدرك الإنسان العمل الذي يعمله الله من البداية إلى النهاية '),
(10611, 'Ecclesiastes', 21, 3, 12, ' عرفت أنه ليس لهم خير ، إلا أن يفرحوا ويفعلوا خيرا في حياتهم '),
(10612, 'Ecclesiastes', 21, 3, 13, ' وأيضا أن يأكل كل إنسان ويشرب ويرى خيرا من كل تعبه ، فهو عطية الله '),
(10613, 'Ecclesiastes', 21, 3, 14, ' قد عرفت أن كل ما يعمله الله أنه يكون إلى الأبد . لا شيء يزاد عليه ، ولا شيء ينقص منه ، وأن الله عمله حتى يخافوا أمامه '),
(10614, 'Ecclesiastes', 21, 3, 15, ' ما كان فمن القدم هو ، وما يكون فمن القدم قد كان . والله يطلب ما قد مضى '),
(10615, 'Ecclesiastes', 21, 3, 16, ' وأيضا رأيت تحت الشمس : موضع الحق هناك الظلم ، وموضع العدل هناك الجور '),
(10616, 'Ecclesiastes', 21, 3, 17, ' فقلت في قلبي : الله يدين الصديق والشرير ، لأن لكل أمر ولكل عمل وقتا هناك '),
(10617, 'Ecclesiastes', 21, 3, 18, ' قلت في قلبي : من جهة أمور بني البشر ، إن الله يمتحنهم ليريهم أنه كما البهيمة هكذا هم '),
(10618, 'Ecclesiastes', 21, 3, 19, ' لأن ما يحدث لبني البشر يحدث للبهيمة ، وحادثة واحدة لهم . موت هذا كموت ذاك ، ونسمة واحدة للكل . فليس للإنسان مزية على البهيمة ، لأن كليهما باطل '),
(10619, 'Ecclesiastes', 21, 3, 20, ' يذهب كلاهما إلى مكان واحد . كان كلاهما من التراب ، وإلى التراب يعود كلاهما '),
(10620, 'Ecclesiastes', 21, 3, 21, ' من يعلم روح بني البشر هل هي تصعد إلى فوق ؟ وروح البهيمة هل هي تنزل إلى أسفل ، إلى الأرض '),
(10621, 'Ecclesiastes', 21, 3, 22, ' فرأيت أنه لا شيء خير من أن يفرح الإنسان بأعماله ، لأن ذلك نصيبه . لأنه من يأتي به ليرى ما سيكون بعده '),
(10622, 'Ecclesiastes', 21, 4, 1, ' ثم رجعت ورأيت كل المظالم التي تجرى تحت الشمس : فهوذا دموع المظلومين ولا معز لهم ، ومن يد ظالميهم قهر ، أما هم فلا معز لهم '),
(10623, 'Ecclesiastes', 21, 4, 2, ' فغبطت أنا الأموات الذين قد ماتوا منذ زمان أكثر من الأحياء الذين هم عائشون بعد '),
(10624, 'Ecclesiastes', 21, 4, 3, ' وخير من كليهما الذي لم يولد بعد ، الذي لم ير العمل الرديء الذي عمل تحت الشمس '),
(10625, 'Ecclesiastes', 21, 4, 4, ' ورأيت كل التعب وكل فلاح عمل أنه حسد الإنسان من قريبه . وهذا أيضا باطل وقبض الريح '),
(10626, 'Ecclesiastes', 21, 4, 5, ' الكسلان يأكل لحمه وهو طاو يديه '),
(10627, 'Ecclesiastes', 21, 4, 6, ' حفنة راحة خير من حفنتي تعب وقبض الريح '),
(10628, 'Ecclesiastes', 21, 4, 7, ' ثم عدت ورأيت باطلا تحت الشمس '),
(10629, 'Ecclesiastes', 21, 4, 8, ' يوجد واحد ولا ثاني له ، وليس له ابن ولا أخ ، ولا نهاية لكل تعبه ، ولا تشبع عينه من الغنى . فلمن أتعب أنا وأحرم نفسي الخير ؟ هذا أيضا باطل وأمر رديء هو '),
(10630, 'Ecclesiastes', 21, 4, 9, ' اثنان خير من واحد ، لأن لهما أجرة لتعبهما صالحة '),
(10631, 'Ecclesiastes', 21, 4, 10, ' لأنه إن وقع أحدهما يقيمه رفيقه . وويل لمن هو وحده إن وقع ، إذ ليس ثان ليقيمه '),
(10632, 'Ecclesiastes', 21, 4, 11, ' أيضا إن اضطجع اثنان يكون لهما دفء ، أما الوحد فكيف يدفأ '),
(10633, 'Ecclesiastes', 21, 4, 12, ' وإن غلب أحد على الواحد يقف مقابله الاثنان ، والخيط المثلوث لا ينقطع سريعا '),
(10634, 'Ecclesiastes', 21, 4, 13, ' ولد فقير وحكيم خير من ملك شيخ جاهل ، الذي لا يعرف أن يحذر بعد '),
(10635, 'Ecclesiastes', 21, 4, 14, ' لأنه من السجن خرج إلى الملك ، والمولود ملكا قد يفتقر '),
(10636, 'Ecclesiastes', 21, 4, 15, ' رأيت كل الأحياء السائرين تحت الشمس مع الولد الثاني الذي يقوم عوضا عنه '),
(10637, 'Ecclesiastes', 21, 4, 16, ' لا نهاية لكل الشعب ، لكل الذين كان أمامهم . أيضا المتأخرون لا يفرحون به . فهذا أيضا باطل وقبض الريح '),
(10638, 'Ecclesiastes', 21, 5, 1, ' احفظ قدمك حين تذهب إلى بيت الله ، فالاستماع أقرب من تقديم ذبيحة الجهال ، لأنهم لا يبالون بفعل الشر '),
(10639, 'Ecclesiastes', 21, 5, 2, ' لا تستعجل فمك ولا يسرع قلبك إلى نطق كلام قدام الله ، لأن الله في السماوات وأنت على الأرض ، فلذلك لتكن كلماتك قليلة '),
(10640, 'Ecclesiastes', 21, 5, 3, ' لأن الحلم يأتي من كثرة الشغل ، وقول الجهل من كثرة الكلام '),
(10641, 'Ecclesiastes', 21, 5, 4, ' إذا نذرت نذرا لله فلا تتأخر عن الوفاء به ، لأنه لا يسر بالجهال . فأوف بما نذرته '),
(10642, 'Ecclesiastes', 21, 5, 5, ' أن لا تنذر خير من أن تنذر ولا تفي '),
(10643, 'Ecclesiastes', 21, 5, 6, ' لا تدع فمك يجعل جسدك يخطئ ، ولا تقل قدام الملاك : إنه سهو . لماذا يغضب الله على قولك ، ويفسد عمل يديك '),
(10644, 'Ecclesiastes', 21, 5, 7, ' لأن ذلك من كثرة الأحلام والأباطيل وكثرة الكلام . ولكن اخش الله '),
(10645, 'Ecclesiastes', 21, 5, 8, ' إن رأيت ظلم الفقير ونزع الحق والعدل في البلاد ، فلا ترتع من الأمر ، لأن فوق العالي عاليا يلاحظ ، والأعلى فوقهما '),
(10646, 'Ecclesiastes', 21, 5, 9, ' ومنفعة الأرض للكل . الملك مخدوم من الحقل '),
(10647, 'Ecclesiastes', 21, 5, 10, ' من يحب الفضة لا يشبع من الفضة ، ومن يحب الثروة لا يشبع من دخل . هذا أيضا باطل '),
(10648, 'Ecclesiastes', 21, 5, 11, ' إذا كثرت الخيرات كثر الذين يأكلونها ، وأي منفعة لصاحبها إلا رؤيتها بعينيه '),
(10649, 'Ecclesiastes', 21, 5, 12, ' نوم المشتغل حلو ، إن أكل قليلا أو كثيرا ، ووفر الغني لا يريحه حتى ينام '),
(10650, 'Ecclesiastes', 21, 5, 13, ' يوجد شر خبيث رأيته تحت الشمس : ثروة مصونة لصاحبها لضرره '),
(10651, 'Ecclesiastes', 21, 5, 14, ' فهلكت تلك الثروة بأمر سيئ ، ثم ولد ابنا وما بيده شيء '),
(10652, 'Ecclesiastes', 21, 5, 15, ' كما خرج من بطن أمه عريانا يرجع ذاهبا كما جاء ، ولا يأخذ شيئا من تعبه فيذهب به في يده '),
(10653, 'Ecclesiastes', 21, 5, 16, ' وهذا أيضا مصيبة رديئة ، في كل شيء كما جاء هكذا يذهب ، فأية منفعة له ، للذي تعب للريح '),
(10654, 'Ecclesiastes', 21, 5, 17, ' أيضا يأكل كل أيامه في الظلام ، ويغتم كثيرا مع حزن وغيظ '),
(10655, 'Ecclesiastes', 21, 5, 18, ' هوذا الذي رأيته أنا خيرا ، الذي هو حسن : أن يأكل الإنسان ويشرب ويرى خيرا من كل تعبه الذي يتعب فيه تحت الشمس مدة أيام حياته التي أعطاه الله إياها ، لأنه نصيبه '),
(10656, 'Ecclesiastes', 21, 5, 19, ' أيضا كل إنسان أعطاه الله غنى ومالا وسلطه عليه حتى يأكل منه ، ويأخذ نصيبه ، ويفرح بتعبه ، فهذا هو عطية الله '),
(10657, 'Ecclesiastes', 21, 5, 20, ' لأنه لا يذكر أيام حياته كثيرا ، لأن الله ملهيه بفرح قلبه '),
(10658, 'Ecclesiastes', 21, 6, 1, ' يوجد شر قد رأيته تحت الشمس وهو كثير بين الناس '),
(10659, 'Ecclesiastes', 21, 6, 2, ' رجل أعطاه الله غنى ومالا وكرامة ، وليس لنفسه عوز من كل ما يشتهيه ، ولم يعطه الله استطاعة على أن يأكل منه ، بل يأكله إنسان غريب . هذا باطل ومصيبة رديئة هو '),
(10660, 'Ecclesiastes', 21, 6, 3, ' إن ولد إنسان مئة ، وعاش سنين كثيرة حتى تصير أيام سنيه كثيرة ، ولم تشبع نفسه من الخير ، وليس له أيضا دفن ، فأقول إن السقط خير منه '),
(10661, 'Ecclesiastes', 21, 6, 4, ' لأنه في الباطل يجيء ، وفي الظلام يذهب ، واسمه يغطى بالظلام '),
(10662, 'Ecclesiastes', 21, 6, 5, ' وأيضا لم ير الشمس ولم يعلم . فهذا له راحة أكثر من ذاك '),
(10663, 'Ecclesiastes', 21, 6, 6, ' وإن عاش ألف سنة مضاعفة ولم ير خيرا ، أليس إلى موضع واحد يذهب الجميع '),
(10664, 'Ecclesiastes', 21, 6, 7, ' كل تعب الإنسان لفمه ، ومع ذلك فالنفس لا تمتلئ '),
(10665, 'Ecclesiastes', 21, 6, 8, ' لأنه ماذا يبقى للحكيم أكثر من الجاهل ؟ ماذا للفقير العارف السلوك أمام الأحياء '),
(10666, 'Ecclesiastes', 21, 6, 9, ' رؤية العيون خير من شهوة النفس . هذا أيضا باطل وقبض الريح '),
(10667, 'Ecclesiastes', 21, 6, 10, ' الذي كان فقد دعي باسم منذ زمان ، وهو معروف أنه إنسان ، ولا يستطيع أن يخاصم من هو أقوى منه '),
(10668, 'Ecclesiastes', 21, 6, 11, ' لأنه توجد أمور كثيرة تزيد الباطل . فأي فضل للإنسان '),
(10669, 'Ecclesiastes', 21, 6, 12, ' لأنه من يعرف ما هو خير للإنسان في الحياة ، مدة أيام حياة باطله التي يقضيها كالظل ؟ لأنه من يخبر الإنسان بما يكون بعده تحت الشمس '),
(10670, 'Ecclesiastes', 21, 7, 1, ' الصيت خير من الدهن الطيب ، ويوم الممات خير من يوم الولادة '),
(10671, 'Ecclesiastes', 21, 7, 2, ' الذهاب إلى بيت النوح خير من الذهاب إلى بيت الوليمة ، لأن ذاك نهاية كل إنسان ، والحي يضعه في قلبه '),
(10672, 'Ecclesiastes', 21, 7, 3, ' الحزن خير من الضحك ، لأنه بكآبة الوجه يصلح القلب '),
(10673, 'Ecclesiastes', 21, 7, 4, ' قلب الحكماء في بيت النوح ، وقلب الجهال في بيت الفرح '),
(10674, 'Ecclesiastes', 21, 7, 5, ' سمع الانتهار من الحكيم خير للإنسان من سمع غناء الجهال '),
(10675, 'Ecclesiastes', 21, 7, 6, ' لأنه كصوت الشوك تحت القدر هكذا ضحك الجهال . هذا أيضا باطل '),
(10676, 'Ephesians', 49, 5, 16, ' مفتدين الوقت لأن الأيام شريرة '),
(10677, 'Ephesians', 49, 5, 17, ' من أجل ذلك لا تكونوا أغبياء بل فاهمين ما هي مشيئة الرب '),
(10678, 'Ephesians', 49, 5, 18, ' ولا تسكروا بالخمر الذي فيه الخلاعة ، بل امتلئوا بالروح '),
(10679, 'Ephesians', 49, 5, 19, ' مكلمين بعضكم بعضا بمزامير وتسابيح وأغاني روحية ، مترنمين ومرتلين في قلوبكم للرب '),
(10680, 'Ephesians', 49, 5, 20, ' شاكرين كل حين على كل شيء في اسم ربنا يسوع المسيح ، لله والآب '),
(10681, 'Ephesians', 49, 5, 21, ' خاضعين بعضكم لبعض في خوف الله '),
(10682, 'Ephesians', 49, 5, 22, ' أيها النساء اخضعن لرجالكن كما للرب '),
(10683, 'Ephesians', 49, 5, 23, ' لأن الرجل هو رأس المرأة كما أن المسيح أيضا رأس الكنيسة ، وهو مخلص الجسد '),
(10684, 'Ephesians', 49, 5, 24, ' ولكن كما تخضع الكنيسة للمسيح ، كذلك النساء لرجالهن في كل شيء '),
(10685, 'Ephesians', 49, 5, 25, ' أيها الرجال ، أحبوا نساءكم كما أحب المسيح أيضا الكنيسة وأسلم نفسه لأجلها '),
(10686, 'Ephesians', 49, 5, 26, ' لكي يقدسها ، مطهرا إياها بغسل الماء بالكلمة '),
(10687, 'Ephesians', 49, 5, 27, ' لكي يحضرها لنفسه كنيسة مجيدة ، لا دنس فيها ولا غضن أو شيء من مثل ذلك ، بل تكون مقدسة وبلا عيب '),
(10688, 'Ephesians', 49, 5, 28, ' كذلك يجب على الرجال أن يحبوا نساءهم كأجسادهم . من يحب امرأته يحب نفسه '),
(10689, 'Ephesians', 49, 5, 29, ' فإنه لم يبغض أحد جسده قط ، بل يقوته ويربيه ، كما الرب أيضا للكنيسة '),
(10690, 'Ephesians', 49, 5, 30, ' لأننا أعضاء جسمه ، من لحمه ومن عظامه '),
(10691, 'Ephesians', 49, 5, 31, ' من أجل هذا يترك الرجل أباه وأمه ويلتصق بامرأته ، ويكون الاثنان جسدا واحدا '),
(10692, 'Ephesians', 49, 5, 32, ' هذا السر عظيم ، ولكنني أنا أقول من نحو المسيح والكنيسة '),
(10693, 'Ephesians', 49, 5, 33, ' وأما أنتم الأفراد ، فليحب كل واحد امرأته هكذا كنفسه ، وأما المرأة فلتهب رجلها '),
(10694, 'Ephesians', 49, 6, 1, ' أيها الأولاد ، أطيعوا والديكم في الرب لأن هذا حق '),
(10695, 'Ephesians', 49, 6, 2, ' أكرم أباك وأمك ، التي هي أول وصية بوعد '),
(10696, 'Ephesians', 49, 6, 3, ' لكي يكون لكم خير ، وتكونوا طوال الأعمار على الأرض '),
(10697, 'Ephesians', 49, 6, 4, ' وأنتم أيها الآباء ، لا تغيظوا أولادكم ، بل ربوهم بتأديب الرب وإنذاره '),
(10698, 'Ephesians', 49, 6, 5, ' أيها العبيد ، أطيعوا سادتكم حسب الجسد بخوف ورعدة ، في بساطة قلوبكم كما للمسيح '),
(10699, 'Ephesians', 49, 6, 6, ' لا بخدمة العين كمن يرضي الناس ، بل كعبيد المسيح ، عاملين مشيئة الله من القلب '),
(10700, 'Ephesians', 49, 6, 7, ' خادمين بنية صالحة كما للرب ، ليس للناس '),
(10701, 'Ephesians', 49, 6, 8, ' عالمين أن مهما عمل كل واحد من الخير فذلك يناله من الرب ، عبدا كان أم حرا '),
(10702, 'Ephesians', 49, 6, 9, ' وأنتم أيها السادة ، افعلوا لهم هذه الأمور ، تاركين التهديد ، عالمين أن سيدكم أنتم أيضا في السماوات ، وليس عنده محاباة '),
(10703, 'Ephesians', 49, 6, 10, ' أخيرا يا إخوتي تقووا في الرب وفي شدة قوته '),
(10704, 'Ephesians', 49, 6, 11, ' البسوا سلاح الله الكامل لكي تقدروا أن تثبتوا ضد مكايد إبليس '),
(10705, 'Ephesians', 49, 6, 12, ' فإن مصارعتنا ليست مع دم ولحم ، بل مع الرؤساء ، مع السلاطين ، مع ولاة العالم على ظلمة هذا الدهر ، مع أجناد الشر الروحية في السماويات '),
(10706, 'Ephesians', 49, 6, 13, ' من أجل ذلك احملوا سلاح الله الكامل لكي تقدروا أن تقاوموا في اليوم الشرير ، وبعد أن تتمموا كل شيء أن تثبتوا '),
(10707, 'Ephesians', 49, 6, 14, ' فاثبتوا ممنطقين أحقاءكم بالحق ، ولابسين درع البر '),
(10708, 'Ephesians', 49, 6, 15, ' وحاذين أرجلكم باستعداد إنجيل السلام '),
(10709, 'Ephesians', 49, 6, 16, ' حاملين فوق الكل ترس الإيمان ، الذي به تقدرون أن تطفئوا جميع سهام الشرير الملتهبة '),
(10710, 'Ephesians', 49, 6, 17, ' وخذوا خوذة الخلاص ، وسيف الروح الذي هو كلمة الله '),
(10711, 'Ephesians', 49, 6, 18, ' مصلين بكل صلاة وطلبة كل وقت في الروح ، وساهرين لهذا بعينه بكل مواظبة وطلبة ، لأجل جميع القديسين '),
(10712, 'Ephesians', 49, 6, 19, ' ولأجلي ، لكي يعطى لي كلام عند افتتاح فمي ، لأعلم جهارا بسر الإنجيل '),
(10713, 'Ephesians', 49, 6, 20, ' الذي لأجله أنا سفير في سلاسل ، لكي أجاهر فيه كما يجب أن أتكلم '),
(10714, 'Ephesians', 49, 6, 21, ' ولكن لكي تعلموا أنتم أيضا أحوالي ، ماذا أفعل ، يعرفكم بكل شيء تيخيكس الأخ الحبيب والخادم الأمين في الرب '),
(10715, 'Ephesians', 49, 6, 22, ' الذي أرسلته إليكم لهذا بعينه ، لكي تعلموا أحوالنا ، ولكي يعزي قلوبكم '),
(10716, 'Ephesians', 49, 6, 23, ' سلام على الإخوة ، ومحبة بإيمان من الله الآب والرب يسوع المسيح '),
(10717, 'Ephesians', 49, 6, 24, ' النعمة مع جميع الذين يحبون ربنا يسوع المسيح في عدم فساد . آمين '),
(10718, 'Ephesians', 49, 1, 1, ' بولس ، رسول يسوع المسيح بمشيئة الله ، إلى القديسين الذين في أفسس ، والمؤمنين في المسيح يسوع '),
(10719, 'Ephesians', 49, 1, 2, ' نعمة لكم وسلام من الله أبينا والرب يسوع المسيح '),
(10720, 'Ephesians', 49, 1, 3, ' مبارك الله أبو ربنا يسوع المسيح ، الذي باركنا بكل بركة روحية في السماويات في المسيح '),
(10721, 'Ephesians', 49, 1, 4, ' كما اختارنا فيه قبل تأسيس العالم ، لنكون قديسين وبلا لوم قدامه في المحبة '),
(10722, 'Ephesians', 49, 1, 5, ' إذ سبق فعيننا للتبني بيسوع المسيح لنفسه ، حسب مسرة مشيئته '),
(10723, 'Ephesians', 49, 1, 6, ' لمدح مجد نعمته التي أنعم بها علينا في المحبوب '),
(10724, 'Ephesians', 49, 1, 7, ' الذي فيه لنا الفداء بدمه ، غفران الخطايا ، حسب غنى نعمته '),
(10725, 'Ephesians', 49, 1, 8, ' التي أجزلها لنا بكل حكمة وفطنة '),
(10726, 'Ephesians', 49, 1, 9, ' إذ عرفنا بسر مشيئته ، حسب مسرته التي قصدها في نفسه '),
(10727, 'Ephesians', 49, 1, 10, ' لتدبير ملء الأزمنة ، ليجمع كل شيء في المسيح ، ما في السماوات وما على الأرض ، في ذاك '),
(10728, 'Ephesians', 49, 1, 11, ' الذي فيه أيضا نلنا نصيبا ، معينين سابقا حسب قصد الذي يعمل كل شيء حسب رأي مشيئته '),
(10729, 'Ephesians', 49, 1, 12, ' لنكون لمدح مجده ، نحن الذين قد سبق رجاؤنا في المسيح '),
(10730, 'Ephesians', 49, 1, 13, ' الذي فيه أيضا أنتم ، إذ سمعتم كلمة الحق ، إنجيل خلاصكم ، الذي فيه أيضا إذ آمنتم ختمتم بروح الموعد القدوس '),
(10731, 'Ephesians', 49, 1, 14, ' الذي هو عربون ميراثنا ، لفداء المقتنى ، لمدح مجده '),
(10732, 'Ephesians', 49, 1, 15, ' لذلك أنا أيضا إذ قد سمعت بإيمانكم بالرب يسوع ، ومحبتكم نحو جميع القديسين '),
(10733, 'Ephesians', 49, 1, 16, ' لا أزال شاكرا لأجلكم ، ذاكرا إياكم في صلواتي '),
(10734, 'Ephesians', 49, 1, 17, ' كي يعطيكم إله ربنا يسوع المسيح ، أبو المجد ، روح الحكمة والإعلان في معرفته '),
(10735, 'Ephesians', 49, 1, 18, ' مستنيرة عيون أذهانكم ، لتعلموا ما هو رجاء دعوته ، وما هو غنى مجد ميراثه في القديسين '),
(10736, 'Ephesians', 49, 1, 19, ' وما هي عظمة قدرته الفائقة نحونا نحن المؤمنين ، حسب عمل شدة قوته '),
(10737, 'Ephesians', 49, 1, 20, ' الذي عمله في المسيح ، إذ أقامه من الأموات ، وأجلسه عن يمينه في السماويات '),
(10738, 'Ephesians', 49, 1, 21, ' فوق كل رياسة وسلطان وقوة وسيادة ، وكل اسم يسمى ليس في هذا الدهر فقط بل في المستقبل أيضا '),
(10739, 'Ephesians', 49, 1, 22, ' وأخضع كل شيء تحت قدميه ، وإياه جعل رأسا فوق كل شيء للكنيسة '),
(10740, 'Ephesians', 49, 1, 23, ' التي هي جسده ، ملء الذي يملأ الكل في الكل '),
(10741, 'Ephesians', 49, 2, 1, ' وأنتم إذ كنتم أمواتا بالذنوب والخطايا '),
(10742, 'Ephesians', 49, 2, 2, ' التي سلكتم فيها قبلا حسب دهر هذا العالم ، حسب رئيس سلطان الهواء ، الروح الذي يعمل الآن في أبناء المعصية '),
(10743, 'Ephesians', 49, 2, 3, ' الذين نحن أيضا جميعا تصرفنا قبلا بينهم في شهوات جسدنا ، عاملين مشيئات الجسد والأفكار ، وكنا بالطبيعة أبناء الغضب كالباقين أيضا '),
(10744, 'Ephesians', 49, 2, 4, ' الله الذي هو غني في الرحمة ، من أجل محبته الكثيرة التي أحبنا بها '),
(10745, 'Ephesians', 49, 2, 5, ' ونحن أموات بالخطايا أحيانا مع المسيح - بالنعمة أنتم مخلصون '),
(10746, 'Ephesians', 49, 2, 6, ' وأقامنا معه ، وأجلسنا معه في السماويات في المسيح يسوع '),
(10747, 'Ephesians', 49, 2, 7, ' ليظهر في الدهور الآتية غنى نعمته الفائق ، باللطف علينا في المسيح يسوع '),
(10748, 'Ephesians', 49, 2, 8, ' لأنكم بالنعمة مخلصون ، بالإيمان ، وذلك ليس منكم . هو عطية الله '),
(10749, 'Ephesians', 49, 2, 9, ' ليس من أعمال كيلا يفتخر أحد '),
(10750, 'Ephesians', 49, 2, 10, ' لأننا نحن عمله ، مخلوقين في المسيح يسوع لأعمال صالحة ، قد سبق الله فأعدها لكي نسلك فيها '),
(10751, 'Ephesians', 49, 2, 11, ' لذلك اذكروا أنكم أنتم الأمم قبلا في الجسد ، المدعوين غرلة من المدعو ختانا مصنوعا باليد في الجسد '),
(10752, 'Ephesians', 49, 2, 12, ' أنكم كنتم في ذلك الوقت بدون مسيح ، أجنبيين عن رعوية إسرائيل ، وغرباء عن عهود الموعد ، لا رجاء لكم ، وبلا إله في العالم '),
(10753, 'Ephesians', 49, 2, 13, ' ولكن الآن في المسيح يسوع ، أنتم الذين كنتم قبلا بعيدين ، صرتم قريبين بدم المسيح '),
(10754, 'Ephesians', 49, 2, 14, ' لأنه هو سلامنا ، الذي جعل الاثنين واحدا ، ونقض حائط السياج المتوسط '),
(10755, 'Ephesians', 49, 2, 15, ' أي العداوة . مبطلا بجسده ناموس الوصايا في فرائض ، لكي يخلق الاثنين في نفسه إنسانا واحدا جديدا ، صانعا سلاما '),
(10756, 'Ephesians', 49, 2, 16, ' ويصالح الاثنين في جسد واحد مع الله بالصليب ، قاتلا العداوة به '),
(10757, 'Ephesians', 49, 2, 17, ' فجاء وبشركم بسلام ، أنتم البعيدين والقريبين '),
(10758, 'Ephesians', 49, 2, 18, ' لأن به لنا كلينا قدوما في روح واحد إلى الآب '),
(10759, 'Ephesians', 49, 2, 19, ' فلستم إذا بعد غرباء ونزلا ، بل رعية مع القديسين وأهل بيت الله '),
(10760, 'Ephesians', 49, 2, 20, ' مبنيين على أساس الرسل والأنبياء ، ويسوع المسيح نفسه حجر الزاوية '),
(10761, 'Ephesians', 49, 2, 21, ' الذي فيه كل البناء مركبا معا ، ينمو هيكلا مقدسا في الرب '),
(10762, 'Ephesians', 49, 2, 22, ' الذي فيه أنتم أيضا مبنيون معا ، مسكنا لله في الروح '),
(10763, 'Ephesians', 49, 3, 1, ' بسبب هذا أنا بولس ، أسير المسيح يسوع لأجلكم أيها الأمم '),
(10764, 'Ephesians', 49, 3, 2, ' إن كنتم قد سمعتم بتدبير نعمة الله المعطاة لي لأجلكم '),
(10765, 'Ephesians', 49, 3, 3, ' أنه بإعلان عرفني بالسر . كما سبقت فكتبت بالإيجاز '),
(10766, 'Ephesians', 49, 3, 4, ' الذي بحسبه حينما تقرأونه ، تقدرون أن تفهموا درايتي بسر المسيح '),
(10767, 'Ephesians', 49, 3, 5, ' الذي في أجيال أخر لم يعرف به بنو البشر ، كما قد أعلن الآن لرسله القديسين وأنبيائه بالروح '),
(10768, 'Ephesians', 49, 3, 6, ' أن الأمم شركاء في الميراث والجسد ونوال موعده في المسيح بالإنجيل '),
(10769, 'Ephesians', 49, 3, 7, ' الذي صرت أنا خادما له حسب موهبة نعمة الله المعطاة لي حسب فعل قوته '),
(10770, 'Ephesians', 49, 3, 8, ' لي أنا أصغر جميع القديسين ، أعطيت هذه النعمة ، أن أبشر بين الأمم بغنى المسيح الذي لا يستقصى '),
(10771, 'Ephesians', 49, 3, 9, ' وأنير الجميع في ما هو شركة السر المكتوم منذ الدهور في الله خالق الجميع بيسوع المسيح '),
(10772, 'Ephesians', 49, 3, 10, ' لكي يعرف الآن عند الرؤساء والسلاطين في السماويات ، بواسطة الكنيسة ، بحكمة الله المتنوعة '),
(10773, 'Ephesians', 49, 3, 11, ' حسب قصد الدهور الذي صنعه في المسيح يسوع ربنا '),
(10774, 'Ephesians', 49, 3, 12, ' الذي به لنا جراءة وقدوم بإيمانه عن ثقة '),
(10775, 'Ephesians', 49, 3, 13, ' لذلك أطلب أن لا تكلوا في شدائدي لأجلكم التي هي مجدكم '),
(10776, 'Ephesians', 49, 3, 14, ' بسبب هذا أحني ركبتي لدى أبي ربنا يسوع المسيح '),
(10777, 'Ephesians', 49, 3, 15, ' الذي منه تسمى كل عشيرة في السماوات وعلى الأرض '),
(10778, 'Ephesians', 49, 3, 16, ' لكي يعطيكم بحسب غنى مجده ، أن تتأيدوا بالقوة بروحه في الإنسان الباطن '),
(10779, 'Ephesians', 49, 3, 17, ' ليحل المسيح بالإيمان في قلوبكم '),
(10780, 'Ephesians', 49, 3, 18, ' وأنتم متأصلون ومتأسسون في المحبة ، حتى تستطيعوا أن تدركوا مع جميع القديسين ، ما هو العرض والطول والعمق والعلو '),
(10781, 'Ephesians', 49, 3, 19, ' وتعرفوا محبة المسيح الفائقة المعرفة ، لكي تمتلئوا إلى كل ملء الله '),
(10782, 'Ephesians', 49, 3, 20, ' والقادر أن يفعل فوق كل شيء ، أكثر جدا مما نطلب أو نفتكر ، بحسب القوة التي تعمل فينا '),
(10783, 'Ephesians', 49, 3, 21, ' له المجد في الكنيسة في المسيح يسوع إلى جميع أجيال دهر الدهور . آمين '),
(10784, 'Ephesians', 49, 4, 1, ' فأطلب إليكم ، أنا الأسير في الرب : أن تسلكوا كما يحق للدعوة التي دعيتم بها '),
(10785, 'Ephesians', 49, 4, 2, ' بكل تواضع ، ووداعة ، وبطول أناة ، محتملين بعضكم بعضا في المحبة '),
(10786, 'Ephesians', 49, 4, 3, ' مجتهدين أن تحفظوا وحدانية الروح برباط السلام '),
(10787, 'Ephesians', 49, 4, 4, ' جسد واحد ، وروح واحد ، كما دعيتم أيضا في رجاء دعوتكم الواحد '),
(10788, 'Ephesians', 49, 4, 5, ' رب واحد ، إيمان واحد ، معمودية واحدة '),
(10789, 'Ephesians', 49, 4, 6, ' إله وآب واحد للكل ، الذي على الكل وبالكل وفي كلكم '),
(10790, 'Ephesians', 49, 4, 7, ' ولكن لكل واحد منا أعطيت النعمة حسب قياس هبة المسيح '),
(10791, 'Ephesians', 49, 4, 8, ' لذلك يقول : إذ صعد إلى العلاء ، سبى سبيا ، وأعطى الناس عطايا '),
(10792, 'Ephesians', 49, 4, 9, ' وأما أنه صعد ، فما هو إلا إنه نزل أيضا أولا إلى أقسام الأرض السفلى '),
(10793, 'Ephesians', 49, 4, 10, ' الذي نزل هو الذي صعد أيضا فوق جميع السماوات ، لكي يملأ الكل '),
(10794, 'Ephesians', 49, 4, 11, ' وهو أعطى البعض أن يكونوا رسلا ، والبعض أنبياء ، والبعض مبشرين ، والبعض رعاة ومعلمين '),
(10795, 'Ephesians', 49, 4, 12, ' لأجل تكميل القديسين لعمل الخدمة ، لبنيان جسد المسيح '),
(10796, 'Ephesians', 49, 4, 13, ' إلى أن ننتهي جميعنا إلى وحدانية الإيمان ومعرفة ابن الله . إلى إنسان كامل . إلى قياس قامة ملء المسيح '),
(10797, 'Ephesians', 49, 4, 14, ' كي لا نكون في ما بعد أطفالا مضطربين ومحمولين بكل ريح تعليم ، بحيلة الناس ، بمكر إلى مكيدة الضلال '),
(10798, 'Ephesians', 49, 4, 15, ' بل صادقين في المحبة ، ننمو في كل شيء إلى ذاك الذي هو الرأس : المسيح '),
(10799, 'Ephesians', 49, 4, 16, ' الذي منه كل الجسد مركبا معا ، ومقترنا بمؤازرة كل مفصل ، حسب عمل ، على قياس كل جزء ، يحصل نمو الجسد لبنيانه في المحبة '),
(10800, 'Ephesians', 49, 4, 17, ' فأقول هذا وأشهد في الرب : أن لا تسلكوا في ما بعد كما يسلك سائر الأمم أيضا ببطل ذهنهم '),
(10801, 'Ephesians', 49, 4, 18, ' إذ هم مظلمو الفكر ، ومتجنبون عن حياة الله لسبب الجهل الذي فيهم بسبب غلاظة قلوبهم '),
(10802, 'Ephesians', 49, 4, 19, ' الذين - إذ هم قد فقدوا الحس - أسلموا نفوسهم للدعارة ليعملوا كل نجاسة في الطمع '),
(10803, 'Ephesians', 49, 4, 20, ' وأما أنتم فلم تتعلموا المسيح هكذا '),
(10804, 'Ephesians', 49, 4, 21, ' إن كنتم قد سمعتموه وعلمتم فيه كما هو حق في يسوع ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(10805, 'Ephesians', 49, 4, 22, ' أن تخلعوا من جهة التصرف السابق الإنسان العتيق الفاسد بحسب شهوات الغرور '),
(10806, 'Ephesians', 49, 4, 23, ' وتتجددوا بروح ذهنكم '),
(10807, 'Ephesians', 49, 4, 24, ' وتلبسوا الإنسان الجديد المخلوق بحسب الله في البر وقداسة الحق '),
(10808, 'Ephesians', 49, 4, 25, ' لذلك اطرحوا عنكم الكذب ، وتكلموا بالصدق كل واحد مع قريبه ، لأننا بعضنا أعضاء البعض '),
(10809, 'Ephesians', 49, 4, 26, ' اغضبوا ولا تخطئوا . لا تغرب الشمس على غيظكم '),
(10810, 'Ephesians', 49, 4, 27, ' ولا تعطوا إبليس مكانا '),
(10811, 'Ephesians', 49, 4, 28, ' لا يسرق السارق في ما بعد ، بل بالحري يتعب عاملا الصالح بيديه ، ليكون له أن يعطي من له احتياج '),
(10812, 'Ephesians', 49, 4, 29, ' لا تخرج كلمة ردية من أفواهكم ، بل كل ما كان صالحا للبنيان ، حسب الحاجة ، كي يعطي نعمة للسامعين '),
(10813, 'Ephesians', 49, 4, 30, ' ولا تحزنوا روح الله القدوس الذي به ختمتم ليوم الفداء '),
(10814, 'Ephesians', 49, 4, 31, ' ليرفع من بينكم كل مرارة وسخط وغضب وصياح وتجديف مع كل خبث '),
(10815, 'Ephesians', 49, 4, 32, ' وكونوا لطفاء بعضكم نحو بعض ، شفوقين متسامحين كما سامحكم الله أيضا في المسيح '),
(10816, 'Ephesians', 49, 5, 1, ' فكونوا متمثلين بالله كأولاد أحباء '),
(10817, 'Ephesians', 49, 5, 2, ' واسلكوا في المحبة كما أحبنا المسيح أيضا وأسلم نفسه لأجلنا ، قربانا وذبيحة لله رائحة طيبة '),
(10818, 'Ephesians', 49, 5, 3, ' وأما الزنا وكل نجاسة أو طمع فلا يسم بينكم كما يليق بقديسين '),
(10819, 'Ephesians', 49, 5, 4, ' ولا القباحة ، ولا كلام السفاهة ، والهزل التي لا تليق ، بل بالحري الشكر '),
(10820, 'Ephesians', 49, 5, 5, ' فإنكم تعلمون هذا أن كل زان أو نجس أو طماع - الذي هو عابد للأوثان - ليس له ميراث في ملكوت المسيح والله '),
(10821, 'Ephesians', 49, 5, 6, ' لا يغركم أحد بكلام باطل ، لأنه بسبب هذه الأمور يأتي غضب الله على أبناء المعصية '),
(10822, 'Ephesians', 49, 5, 7, ' فلا تكونوا شركاءهم '),
(10823, 'Ephesians', 49, 5, 8, ' لأنكم كنتم قبلا ظلمة ، وأما الآن فنور في الرب . اسلكوا كأولاد نور '),
(10824, 'Ephesians', 49, 5, 9, ' لأن ثمر الروح هو في كل صلاح وبر وحق '),
(10825, 'Ephesians', 49, 5, 10, ' مختبرين ما هو مرضي عند الرب '),
(10826, 'Ephesians', 49, 5, 11, ' ولا تشتركوا في أعمال الظلمة غير المثمرة بل بالحري وبخوها '),
(10827, 'Ephesians', 49, 5, 12, ' لأن الأمور الحادثة منهم سرا ، ذكرها أيضا قبيح '),
(10828, 'Ephesians', 49, 5, 13, ' ولكن الكل إذا توبخ يظهر بالنور . لأن كل ما أظهر فهو نور '),
(10829, 'Ephesians', 49, 5, 14, ' لذلك يقول : استيقظ أيها النائم ، وقم من الأموات ، فيضيء لك المسيح '),
(10830, 'Ephesians', 49, 5, 15, ' فانظروا كيف تسلكون بالتدقيق ، لا كجهلاء بل كحكماء '),
(10831, 'Esther', 17, 1, 2, ' أنه في تلك الأيام حين جلس الملك أحشويروش على كرسي ملكه الذي في شوشن القصر '),
(10832, 'Esther', 17, 1, 3, ' في السنة الثالثة من ملكه ، عمل وليمة لجميع رؤسائه وعبيده جيش فارس ومادي ، وأمامه شرفاء البلدان ورؤساؤها '),
(10833, 'Esther', 17, 1, 4, ' حين أظهر غنى مجد ملكه ووقار جلال عظمته أياما كثيرة ، مئة وثمانين يوما '),
(10834, 'Esther', 17, 1, 5, ' وعند انقضاء هذه الأيام ، عمل الملك لجميع الشعب الموجودين في شوشن القصر ، من الكبير إلى الصغير ، وليمة سبعة أيام في دار جنة قصر الملك '),
(10835, 'Esther', 17, 1, 6, ' بأنسجة بيضاء وخضراء وأسمانجونية معلقة بحبال من بز وأرجوان ، في حلقات من فضة ، وأعمدة من رخام ، وأسرة من ذهب وفضة ، على مجزع من بهت ومرمر ودر ورخام أسود '),
(10836, 'Esther', 17, 1, 7, ' وكان السقاء من ذهب ، والآنية مختلفة الأشكال ، والخمر الملكي بكثرة حسب كرم الملك '),
(10837, 'Esther', 17, 1, 8, ' وكان الشرب حسب الأمر . لم يكن غاصب ، لأنه هكذا رسم الملك على كل عظيم في بيته أن يعملوا حسب رضا كل واحد '),
(10838, 'Esther', 17, 1, 9, ' ووشتي الملكة عملت أيضا وليمة للنساء في بيت الملك الذي للملك أحشويروش '),
(10839, 'Esther', 17, 1, 10, ' في اليوم السابع لما طاب قلب الملك بالخمر ، قال لمهومان وبزثا وحربونا وبغثا وأبغثا وزيثار وكركس ، الخصيان السبعة الذين كانوا يخدمون بين يدي الملك أحشويروش '),
(10840, 'Esther', 17, 1, 11, ' أن يأتوا بوشتي الملكة إلى أمام الملك بتاج الملك ، ليري الشعوب والرؤساء جمالها ، لأنها كانت حسنة المنظر '),
(10841, 'Esther', 17, 1, 12, ' فأبت الملكة وشتي أن تأتي حسب أمر الملك عن يد الخصيان ، فاغتاظ الملك جدا واشتعل غضبه فيه '),
(10842, 'Esther', 17, 1, 13, ' وقال الملك للحكماء العارفين بالأزمنة ، لأنه هكذا كان أمر الملك نحو جميع العارفين بالسنة والقضاء '),
(10843, 'Esther', 17, 1, 14, ' وكان المقربون إليه كرشنا وشيثار وأدماثا وترشيش ومرس ومرسنا ومموكان ، سبعة رؤساء فارس ومادي الذين يرون وجه الملك ويجلسون أولا في الملك '),
(10844, 'Esther', 17, 1, 15, ' حسب السنة ، ماذا يعمل بالملكة وشتي لأنها لم تعمل كقول الملك أحشويروش عن يد الخصيان '),
(10845, 'Esther', 17, 1, 16, ' فقال مموكان أمام الملك والرؤساء : ليس إلى الملك وحده أذنبت وشتي الملكة ، بل إلى جميع الرؤساء وجميع الشعوب الذين في كل بلدان الملك أحشويروش '),
(10846, 'Esther', 17, 1, 17, ' لأنه سوف يبلغ خبر الملكة إلى جميع النساء ، حتى يحتقر أزواجهن في أعينهن عندما يقال : إن الملك أحشويروش أمر أن يؤتى بوشتي الملكة إلى أمامه فلم تأت '),
(10847, 'Esther', 17, 1, 18, ' وفي هذا اليوم تقوله رئيسات فارس ومادي اللواتي سمعن خبر الملكة لجميع رؤساء الملك . ومثل ذلك احتقار وغضب '),
(10848, 'Esther', 17, 1, 19, ' فإذا حسن عند الملك ، فليخرج أمر ملكي من عنده ، وليكتب في سنن فارس ومادي فلا يتغير ، أن لا تأت وشتي إلى أمام الملك أحشويروش ، وليعط الملك ملكها لمن هي أحسن منها '),
(10849, 'Esther', 17, 1, 20, ' فيسمع أمر الملك الذي يخرجه في كل مملكته لأنها عظيمة ، فتعطي جميع النساء الوقار لأزواجهن من الكبير إلى الصغير '),
(10850, 'Esther', 17, 1, 21, ' فحسن الكلام في أعين الملك والرؤساء ، وعمل الملك حسب قول مموكان '),
(10851, 'Esther', 17, 1, 22, ' وأرسل كتبا إلى كل بلدان الملك ، إلى كل بلاد حسب كتابتها ، وإلى كل شعب حسب لسانه ، ليكون كل رجل متسلطا في بيته ، ويتكلم بذلك بلسان شعبه '),
(10852, 'Esther', 17, 2, 1, ' بعد هذه الأمور لما خمد غضب الملك أحشويروش ، ذكر وشتي وما عملته وما حتم به عليها '),
(10853, 'Esther', 17, 2, 2, ' فقال غلمان الملك الذين يخدمونه : ليطلب للملك فتيات عذارى حسنات المنظر '),
(10854, 'Esther', 17, 2, 3, ' وليوكل الملك وكلاء في كل بلاد مملكته ليجمعوا كل الفتيات العذارى الحسنات المنظر إلى شوشن القصر ، إلى بيت النساء ، إلى يد هيجاي خصي الملك حارس النساء ، وليعطين أدهان عطرهن '),
(10855, 'Esther', 17, 2, 4, ' والفتاة التي تحسن في عيني الملك ، فلتملك مكان وشتي . فحسن الكلام في عيني الملك ، فعمل هكذا '),
(10856, 'Esther', 17, 2, 5, ' كان في شوشن القصر رجل يهودي اسمه مردخاي بن يائير بن شمعي بن قيس ، رجل يميني '),
(10857, 'Esther', 17, 2, 6, ' قد سبي من أورشليم مع السبي الذي سبي مع يكنيا ملك يهوذا الذي سباه نبوخذنصر ملك بابل '),
(10858, 'Esther', 17, 2, 7, ' وكان مربيا لهدسة أي أستير بنت عمه ، لأنه لم يكن لها أب ولا أم . وكانت الفتاة جميلة الصورة وحسنة المنظر ، وعند موت أبيها وأمها اتخذها مردخاي لنفسه ابنة '),
(10859, 'Esther', 17, 2, 8, ' فلما سمع كلام الملك وأمره ، وجمعت فتيات كثيرات إلى شوشن القصر إلى يد هيجاي ، أخذت أستير إلى بيت الملك إلى يد هيجاي حارس النساء '),
(10860, 'Esther', 17, 2, 9, ' وحسنت الفتاة في عينيه ونالت نعمة بين يديه ، فبادر بأدهان عطرها وأنصبتها ليعطيها إياها مع السبع الفتيات المختارات لتعطى لها من بيت الملك ، ونقلها مع فتياتها إلى أحسن مكان في بيت النساء '),
(10861, 'Esther', 17, 2, 10, ' ولم تخبر أستير عن شعبها وجنسها لأن مردخاي أوصاها أن لا تخبر '),
(10862, 'Esther', 17, 2, 11, ' وكان مردخاي يتمشى يوما فيوما أمام دار بيت النساء ، ليستعلم عن سلامة أستير وعما يصنع بها '),
(10863, 'Esther', 17, 2, 12, ' ولما بلغت نوبة فتاة ففتاة للدخول إلى الملك أحشويروش بعد أن يكون لها حسب سنة النساء اثنا عشر شهرا ، لأنه هكذا كانت تكمل أيام تعطرهن ، ستة أشهر بزيت المر وستة أشهر بالأطياب وأدهان تعطر النساء '),
(10864, 'Esther', 17, 2, 13, ' وهكذا كانت كل فتاة تدخل إلى الملك . وكل ما قالت عنه أعطي لها للدخول معها من بيت النساء إلى بيت الملك '),
(10865, 'Esther', 17, 2, 14, ' في المساء دخلت وفي الصباح رجعت إلى بيت النساء الثاني إلى يد شعشغاز خصي الملك حارس السراري . لم تعد تدخل إلى الملك إلا إذا سر بها الملك ودعيت باسمها '),
(10866, 'Esther', 17, 2, 15, ' ولما بلغت نوبة أستير ابنة أبيحائل عم مردخاي ، الذي اتخذها لنفسه ابنة ، للدخول إلى الملك ، لم تطلب شيئا إلا ما قال عنه هيجاي خصي الملك حارس النساء . وكانت أستير تنال نعمة في عيني كل من رآها '),
(10867, 'Esther', 17, 2, 16, ' وأخذت أستير إلى الملك أحشويروش إلى بيت ملكه في الشهر العاشر ، هو شهر طيبيت ، في السنة السابعة لملكه '),
(10868, 'Esther', 17, 2, 17, ' فأحب الملك أستير أكثر من جميع النساء ، ووجدت نعمة وإحسانا قدامه أكثر من جميع العذارى ، فوضع تاج الملك على رأسها وملكها مكان وشتي '),
(10869, 'Esther', 17, 2, 18, ' وعمل الملك وليمة عظيمة لجميع رؤسائه وعبيده ، وليمة أستير . وعمل راحة للبلاد وأعطى عطايا حسب كرم الملك '),
(10870, 'Esther', 17, 2, 19, ' ولما جمعت العذارى ثانية كان مردخاي جالسا بباب الملك '),
(10871, 'Esther', 17, 2, 20, ' ولم تكن أستير أخبرت عن جنسها وشعبها كما أوصاها مردخاي . وكانت أستير تعمل حسب قول مردخاي ، كما كانت في تربيتها عنده '),
(10872, 'Esther', 17, 2, 21, ' في تلك الأيام ، بينما كان مردخاي جالسا في باب الملك ، غضب بغثان وترش خصيا الملك حارسا الباب ، وطلبا أن يمدا أيديهما إلى الملك أحشويروش '),
(10873, 'Esther', 17, 2, 22, ' فعلم الأمر عند مردخاي ، فأخبر أستير الملكة ، فأخبرت أستير الملك باسم مردخاي '),
(10874, 'Esther', 17, 2, 23, ' ففحص عن الأمر ووجد ، فصلبا كلاهما على خشبة ، وكتب ذلك في سفر أخبار الأيام أمام الملك '),
(10875, 'Esther', 17, 8, 4, ' فمد الملك لأستير قضيب الذهب ، فقامت أستير ووقفت أمام الملك '),
(10876, 'Esther', 17, 8, 5, ' وقالت : إذا حسن عند الملك ، وإن كنت قد وجدت نعمة أمامه ، واستقام الأمر أمام الملك وحسنت أنا لديه ، فليكتب لكي ترد كتابات تدبير هامان بن همداثا الأجاجي التي كتبها لإبادة اليهود الذين في كل بلاد الملك '),
(10877, 'Esther', 17, 8, 6, ' لأنني كيف أستطيع أن أرى الشر الذي يصيب شعبي ؟ وكيف أستطيع أن أرى هلاك جنسي '),
(10878, 'Esther', 17, 8, 7, ' فقال الملك أحشويروش لأستير الملكة ومردخاي اليهودي : هوذا قد أعطيت بيت هامان لأستير ، أما هو فقد صلبوه على الخشبة من أجل أنه مد يده إلى اليهود '),
(10879, 'Esther', 17, 8, 8, ' فاكتبا أنتما إلى اليهود ما يحسن في أعينكما باسم الملك ، واختماه بخاتم الملك ، لأن الكتابة التي تكتب باسم الملك وتختم بخاتمه لا ترد '),
(10880, 'Esther', 17, 8, 9, ' فدعي كتاب الملك في ذلك الوقت في الشهر الثالث ، أي شهر سيوان ، في الثالث والعشرين منه ، وكتب حسب كل ما أمر به مردخاي إلى اليهود وإلى المرازبة والولاة ورؤساء البلدان التي من الهند إلى كوش ، مئة وسبع وعشرين كورة ، إلى كل كورة بكتابتها وكل شعب بلسانه ، وإلى اليهود بكتابتهم ولسانهم '),
(10881, 'Esther', 17, 1, 1, ' وحدث في أيام أحشويروش ، هو أحشويروش الذي ملك من الهند إلى كوش على مئة وسبع وعشرين كورة '),
(10882, 'Esther', 17, 8, 10, ' فكتب باسم الملك أحشويروش وختم بخاتم الملك ، وأرسل رسائل بأيدي بريد الخيل ركاب الجياد والبغال بني الرمك '),
(10883, 'Esther', 17, 8, 11, ' التي بها أعطى الملك اليهود في مدينة فمدينة أن يجتمعوا ويقفوا لأجل أنفسهم ، ويهلكوا ويقتلوا ويبيدوا قوة كل شعب وكورة تضادهم حتى الأطفال والنساء ، وأن يسلبوا غنيمتهم '),
(10884, 'Esther', 17, 8, 12, ' في يوم واحد في كل كور الملك أحشويروش ، في الثالث عشر من الشهر الثاني عشر ، أي شهر أذار '),
(10885, 'Esther', 17, 8, 13, ' صورة الكتابة المعطاة سنة في كل البلدان ، أشهرت على جميع الشعوب أن يكون اليهود مستعدين لهذا اليوم لينتقموا من أعدائهم '),
(10886, 'Esther', 17, 8, 14, ' فخرج البريد ركاب الجياد والبغال وأمر الملك يحثهم ويعجلهم ، وأعطي الأمر في شوشن القصر '),
(10887, 'Esther', 17, 8, 15, ' وخرج مردخاي من أمام الملك بلباس ملكي أسمانجوني وأبيض ، وتاج عظيم من ذهب ، وحلة من بز وأرجوان . وكانت مدينة شوشن متهللة وفرحة '),
(10888, 'Esther', 17, 8, 16, ' وكان لليهود نور وفرح وبهجة وكرامة '),
(10889, 'Esther', 17, 8, 17, ' وفي كل بلاد ومدينة ، كل مكان وصل إليه كلام الملك وأمره ، كان فرح وبهجة عند اليهود وولائم ويوم طيب . وكثيرون من شعوب الأرض تهودوا لأن رعب اليهود وقع عليهم '),
(10890, 'Esther', 17, 9, 1, ' وفي الشهر الثاني عشر ، أي شهر أذار ، في اليوم الثالث عشر منه ، حين قرب كلام الملك وأمره من الإجراء ، في اليوم الذي انتظر فيه أعداء اليهود أن يتسلطوا عليهم ، فتحول ذلك ، حتى إن اليهود تسلطوا على مبغضيهم '),
(10891, 'Esther', 17, 9, 2, ' اجتمع اليهود في مدنهم في كل بلاد الملك أحشويروش ليمدوا أيديهم إلى طالبي أذيتهم ، فلم يقف أحد قدامهم لأن رعبهم سقط على جميع الشعوب '),
(10892, 'Esther', 17, 9, 3, ' وكل رؤساء البلدان والمرازبة والولاة وعمال الملك ساعدوا اليهود ، لأن رعب مردخاي سقط عليهم '),
(10893, 'Esther', 17, 9, 4, ' لأن مردخاي كان عظيما في بيت الملك ، وسار خبره في كل البلدان ، لأن الرجل مردخاي كان يتزايد عظمة '),
(10894, 'Esther', 17, 9, 5, ' فضرب اليهود جميع أعدائهم ضربة سيف وقتل وهلاك ، وعملوا بمبغضيهم ما أرادوا '),
(10895, 'Esther', 17, 9, 6, ' وقتل اليهود في شوشن القصر وأهلكوا خمس مئة رجل '),
(10896, 'Esther', 17, 9, 7, ' وفرشنداثا ودلفون وأسفاثا '),
(10897, 'Esther', 17, 9, 8, ' وفوراثا وأدليا وأريداثا '),
(10898, 'Esther', 17, 9, 9, ' وفرمشتا وأريساي وأريداي ويزاثا '),
(10899, 'Esther', 17, 9, 10, ' عشرة ، بني هامان بن همداثا عدو اليهود ، قتلوهم ولكنهم لم يمدوا أيديهم إلى النهب '),
(10900, 'Esther', 17, 9, 11, ' في ذلك اليوم أتي بعدد القتلى في شوشن القصر إلى بين يدي الملك '),
(10901, 'Esther', 17, 9, 12, ' فقال الملك لأستير الملكة في شوشن القصر : قد قتل اليهود وأهلكوا خمس مئة رجل ، وبني هامان العشرة ، فماذا عملوا في باقي بلدان الملك ؟ فما هو سؤلك فيعطى لك ؟ وما هي طلبتك بعد فتقضى '),
(10902, 'Esther', 17, 9, 13, ' فقالت أستير : إن حسن عند الملك فليعط غدا أيضا لليهود الذين في شوشن أن يعملوا كما في هذا اليوم ، ويصلبوا بني هامان العشرة على الخشبة '),
(10903, 'Esther', 17, 9, 14, ' فأمر الملك أن يعملوا هكذا ، وأعطي الأمر في شوشن . فصلبوا بني هامان العشرة '),
(10904, 'Esther', 17, 9, 15, ' ثم اجتمع اليهود الذين في شوشن ، في اليوم الرابع عشر أيضا من شهر أذار ، وقتلوا في شوشن ثلاث مئة رجل ، ولكنهم لم يمدوا أيديهم إلى النهب '),
(10905, 'Esther', 17, 9, 16, ' وباقي اليهود الذين في بلدان الملك اجتمعوا ووقفوا لأجل أنفسهم واستراحوا من أعدائهم ، وقتلوا من مبغضيهم خمسة وسبعين ألفا ، ولكنهم لم يمدوا أيديهم إلى النهب '),
(10906, 'Esther', 17, 9, 17, ' في اليوم الثالث عشر من شهر أذار . واستراحوا في اليوم الرابع عشر منه وجعلوه يوم شرب وفرح '),
(10907, 'Esther', 17, 9, 18, ' واليهود الذين في شوشن اجتمعوا في الثالث عشر والرابع عشر منه ، واستراحوا في الخامس عشر وجعلوه يوم شرب وفرح '),
(10908, 'Esther', 17, 9, 19, ' لذلك يهود الأعراء ، الساكنون في مدن الأعراء ، جعلوا اليوم الرابع عشر من شهر أذار للفرح والشرب ، ويوما طيبا ولإرسال أنصبة من كل واحد إلى صاحبه '),
(10909, 'Esther', 17, 9, 20, ' وكتب مردخاي هذه الأمور وأرسل رسائل إلى جميع اليهود الذين في كل بلدان الملك أحشويروش القريبين والبعيدين '),
(10910, 'Esther', 17, 9, 21, ' ليوجب عليهم أن يعيدوا في اليوم الرابع عشر من شهر أذار ، واليوم الخامس عشر منه في كل سنة '),
(10911, 'Esther', 17, 9, 22, ' حسب الأيام التي استراح فيها اليهود من أعدائهم ، والشهر الذي تحول عندهم من حزن إلى فرح ومن نوح إلى يوم طيب ، ليجعلوها أيام شرب وفرح وإرسال أنصبة من كل واحد إلى صاحبه وعطايا للفقراء '),
(10912, 'Esther', 17, 9, 23, ' فقبل اليهود ما ابتدأوا يعملونه وما كتبه مردخاي إليهم '),
(10913, 'Esther', 17, 9, 24, ' ولأن هامان بن همداثا الأجاجي عدو اليهود جميعا تفكر على اليهود ليبيدهم وألقى فورا ، أي قرعة ، لإفنائهم وإبادتهم '),
(10914, 'Esther', 17, 9, 25, ' وعند دخولها إلى أمام الملك أمر بكتابة أن يرد تدبيره الرديء الذي دبره ضد اليهود على رأسه ، وأن يصلبوه هو وبنيه على الخشبة '),
(10915, 'Esther', 17, 9, 26, ' لذلك دعوا تلك الأيام فوريم على اسم الفور . لذلك من أجل جميع كلمات هذه الرسالة وما رأوه من ذلك وما أصابهم '),
(10916, 'Esther', 17, 9, 27, ' أوجب اليهود وقبلوا على أنفسهم وعلى نسلهم وعلى جميع الذين يلتصقون بهم حتى لا يزول ، أن يعيدوا هذين اليومين حسب كتابتهما وحسب أوقاتهما كل سنة '),
(10917, 'Esther', 17, 9, 28, ' وأن يذكر هذان اليومان ويحفظا في دور فدور وعشيرة فعشيرة وبلاد فبلاد ومدينة فمدينة . ويوما الفور هذان لا يزولان من وسط اليهود ، وذكرهما لا يفنى من نسلهم '),
(10918, 'Esther', 17, 9, 29, ' وكتبت أستير الملكة بنت أبيحائل ومردخاي اليهودي بكل سلطان بإيجاب رسالة الفوريم هذه ثانية '),
(10919, 'Esther', 17, 9, 30, ' وأرسل الكتابات إلى جميع اليهود ، إلى كور مملكة أحشويروش المئة والسبع والعشرين بكلام سلام وأمانة '),
(10920, 'Esther', 17, 9, 31, ' لإيجاب يومي الفوريم هذين في أوقاتهما ، كما أوجب عليهم مردخاي اليهودي وأستير الملكة ، وكما أوجبوا على أنفسهم وعلى نسلهم أمور الأصوام وصراخهم '),
(10921, 'Esther', 17, 9, 32, ' وأمر أستير أوجب أمور الفوريم هذه ، فكتبت في السفر '),
(10922, 'Esther', 17, 10, 1, ' ووضع الملك أحشويروش جزية على الأرض وجزائر البحر '),
(10923, 'Esther', 17, 10, 2, ' وكل عمل سلطانه وجبروته وإذاعة عظمة مردخاي الذي عظمه الملك ، أما هي مكتوبة في سفر أخبار الأيام لملوك مادي وفارس '),
(10924, 'Esther', 17, 10, 3, ' لأن مردخاي اليهودي كان ثاني الملك أحشويروش ، وعظيما بين اليهود ، ومقبولا عند كثرة إخوته ، طالبا الخير لشعبه ومتكلما بالسلام لكل نسله '),
(10925, 'Esther', 17, 3, 1, ' بعد هذه الأمور عظم الملك أحشويروش هامان بن همداثا الأجاجي ورقاه ، وجعل كرسيه فوق جميع الرؤساء الذين معه '),
(10926, 'Esther', 17, 3, 2, ' فكان كل عبيد الملك الذين بباب الملك يجثون ويسجدون لهامان ، لأنه هكذا أوصى به الملك . وأما مردخاي فلم يجث ولم يسجد '),
(10927, 'Esther', 17, 3, 3, ' فقال عبيد الملك الذين بباب الملك لمردخاي : لماذا تتعدى أمر الملك '),
(10928, 'Esther', 17, 3, 4, ' وإذ كانوا يكلمونه يوما فيوما ولم يكن يسمع لهم ، أخبروا هامان ليروا هل يقوم كلام مردخاي ، لأنه أخبرهم بأنه يهودي '),
(10929, 'Esther', 17, 3, 5, ' ولما رأى هامان أن مردخاي لا يجثو ولا يسجد له ، امتلأ هامان غضبا '),
(10930, 'Esther', 17, 3, 6, ' وازدري في عينيه أن يمد يده إلى مردخاي وحده ، لأنهم أخبروه عن شعب مردخاي . فطلب هامان أن يهلك جميع اليهود الذين في كل مملكة أحشويروش ، شعب مردخاي '),
(10931, 'Esther', 17, 3, 7, ' في الشهر الأول ، أي شهر نيسان ، في السنة الثانية عشرة للملك أحشويروش ، كانوا يلقون فورا ، أي قرعة ، أمام هامان ، من يوم إلى يوم ، ومن شهر إلى شهر ، إلى الثاني عشر ، أي شهر أذار '),
(10932, 'Esther', 17, 3, 8, ' فقال هامان للملك أحشويروش : إنه موجود شعب ما متشتت ومتفرق بين الشعوب في كل بلاد مملكتك ، وسننهم مغايرة لجميع الشعوب ، وهم لا يعملون سنن الملك ، فلا يليق بالملك تركهم '),
(10933, 'Esther', 17, 3, 9, ' فإذا حسن عند الملك فليكتب أن يبادوا ، وأنا أزن عشرة آلاف وزنة من الفضة في أيدي الذين يعملون العمل ليؤتى بها إلى خزائن الملك '),
(10934, 'Esther', 17, 3, 10, ' فنزع الملك خاتمه من يده وأعطاه لهامان بن همداثا الأجاجي عدو اليهود '),
(10935, 'Esther', 17, 3, 11, ' وقال الملك لهامان : الفضة قد أعطيت لك ، والشعب أيضا ، لتفعل به ما يحسن في عينيك '),
(10936, 'Esther', 17, 3, 12, ' فدعي كتاب الملك في الشهر الأول ، في اليوم الثالث عشر منه ، وكتب حسب كل ما أمر به هامان إلى مرازبة الملك وإلى ولاة بلاد فبلاد ، وإلى رؤساء شعب فشعب ، كل بلاد ككتابتها ، وكل شعب كلسانه ، كتب باسم الملك أحشويروش وختم بخاتم الملك '),
(10937, 'Esther', 17, 3, 13, ' وأرسلت الكتابات بيد السعاة إلى كل بلدان الملك لإهلاك وقتل وإبادة جميع اليهود ، من الغلام إلى الشيخ والأطفال والنساء في يوم واحد ، في الثالث عشر من الشهر الثاني عشر ، أي شهر أذار ، وأن يسلبوا غنيمتهم '),
(10938, 'Esther', 17, 3, 14, ' صورة الكتابة المعطاة سنة في كل البلدان ، أشهرت بين جميع الشعوب ليكونوا مستعدين لهذا اليوم '),
(10939, 'Esther', 17, 3, 15, ' فخرج السعاة وأمر الملك يحثهم ، وأعطي الأمر في شوشن القصر . وجلس الملك وهامان للشرب ، وأما المدينة شوشن فارتبكت '),
(10940, 'Esther', 17, 4, 1, ' ولما علم مردخاي كل ما عمل ، شق مردخاي ثيابه ولبس مسحا برماد وخرج إلى وسط المدينة وصرخ صرخة عظيمة مرة '),
(10941, 'Esther', 17, 4, 2, ' وجاء إلى قدام باب الملك ، لأنه لا يدخل أحد باب الملك وهو لابس مسحا '),
(10942, 'Esther', 17, 4, 3, ' وفي كل كورة حيثما وصل إليها أمر الملك وسنته ، كانت مناحة عظيمة عند اليهود ، وصوم وبكاء ونحيب . وانفرش مسح ورماد لكثيرين '),
(10943, 'Esther', 17, 4, 4, ' فدخلت جواري أستير وخصيانها وأخبروها ، فاغتمت الملكة جدا وأرسلت ثيابا لإلباس مردخاي ، ولأجل نزع مسحه عنه ، فلم يقبل '),
(10944, 'Esther', 17, 4, 5, ' فدعت أستير هتاخ ، واحدا من خصيان الملك الذي أوقفه بين يديها ، وأعطته وصية إلى مردخاي لتعلم ماذا ولماذا '),
(10945, 'Esther', 17, 4, 6, ' فخرج هتاخ إلى مردخاي إلى ساحة المدينة التي أمام باب الملك '),
(10946, 'Esther', 17, 4, 7, ' فأخبره مردخاي بكل ما أصابه ، وعن مبلغ الفضة الذي وعد هامان بوزنه لخزائن الملك عن اليهود لإبادتهم '),
(10947, 'Esther', 17, 4, 8, ' وأعطاه صورة كتابة الأمر الذي أعطي في شوشن لإهلاكهم ، لكي يريها لأستير ، ويخبرها ويوصيها أن تدخل إلى الملك وتتضرع إليه وتطلب منه لأجل شعبها '),
(10948, 'Esther', 17, 4, 9, ' فأتى هتاخ وأخبر أستير بكلام مردخاي '),
(10949, 'Esther', 17, 4, 10, ' فكلمت أستير هتاخ وأعطته وصية إلى مردخاي '),
(10950, 'Esther', 17, 4, 11, ' إن كل عبيد الملك وشعوب بلاد الملك يعلمون أن كل رجل دخل أو امرأة إلى الملك ، إلى الدار الداخلية ولم يدع ، فشريعته واحدة أن يقتل ، إلا الذي يمد له الملك قضيب الذهب فإنه يحيا . وأنا لم أدع لأدخل إلى الملك هذه الثلاثين يوما '),
(10951, 'Esther', 17, 4, 12, ' فأخبروا مردخاي بكلام أستير '),
(10952, 'Esther', 17, 4, 13, ' فقال مردخاي أن تجاوب أستير : لا تفتكري في نفسك أنك تنجين في بيت الملك دون جميع اليهود '),
(10953, 'Esther', 17, 4, 14, ' لأنك إن سكت سكوتا في هذا الوقت يكون الفرج والنجاة لليهود من مكان آخر ، وأما أنت وبيت أبيك فتبيدون . ومن يعلم إن كنت لوقت مثل هذا وصلت إلى الملك '),
(10954, 'Esther', 17, 4, 15, ' فقالت أستير أن يجاوب مردخاي '),
(10955, 'Esther', 17, 4, 16, ' اذهب اجمع جميع اليهود الموجودين في شوشن وصوموا من جهتي ولا تأكلوا ولا تشربوا ثلاثة أيام ليلا ونهارا . وأنا أيضا وجواري نصوم كذلك . وهكذا أدخل إلى الملك خلاف السنة . فإذا هلكت ، هلكت '),
(10956, 'Esther', 17, 4, 17, ' فانصرف مردخاي وعمل حسب كل ما أوصته به أستير '),
(10957, 'Esther', 17, 5, 1, ' وفي اليوم الثالث لبست أستير ثيابا ملكية ووقفت في دار بيت الملك الداخلية مقابل بيت الملك ، والملك جالس على كرسي ملكه في بيت الملك مقابل مدخل البيت '),
(10958, 'Esther', 17, 5, 2, ' فلما رأى الملك أستير الملكة واقفة في الدار نالت نعمة في عينيه ، فمد الملك لأستير قضيب الذهب الذي بيده ، فدنت أستير ولمست رأس القضيب '),
(10959, 'Esther', 17, 5, 3, ' فقال لها الملك : ما لك يا أستير الملكة ؟ وما هي طلبتك ؟ إلى نصف المملكة تعطى لك '),
(10960, 'Esther', 17, 5, 4, ' فقالت أستير : إن حسن عند الملك فليأت الملك وهامان اليوم إلى الوليمة التي عملتها له '),
(10961, 'Esther', 17, 5, 5, ' فقال الملك : أسرعوا بهامان ليفعل كلام أستير . فأتى الملك وهامان إلى الوليمة التي عملتها أستير '),
(10962, 'Esther', 17, 5, 6, ' فقال الملك لأستير عند شرب الخمر : ما هو سؤلك فيعطى لك ؟ وما هي طلبتك ؟ إلى نصف المملكة تقضى '),
(10963, 'Esther', 17, 5, 7, ' فأجابت أستير وقالت : إن سؤلي وطلبتي '),
(10964, 'Esther', 17, 5, 8, ' إن وجدت نعمة في عيني الملك ، وإذا حسن عند الملك أن يعطى سؤلي وتقضى طلبتي ، أن يأتي الملك وهامان إلى الوليمة التي أعملها لهما ، وغدا أفعل حسب أمر الملك '),
(10965, 'Esther', 17, 5, 9, ' فخرج هامان في ذلك اليوم فرحا وطيب القلب . ولكن لما رأى هامان مردخاي في باب الملك ولم يقم ولا تحرك له ، امتلأ هامان غيظا على مردخاي '),
(10966, 'Esther', 17, 5, 10, ' وتجلد هامان ودخل بيته وأرسل فاستحضر أحباءه وزرش زوجته '),
(10967, 'Esther', 17, 5, 11, ' وعدد لهم هامان عظمة غناه وكثرة بنيه ، وكل ما عظمه الملك به ورقاه على الرؤساء وعبيد الملك '),
(10968, 'Esther', 17, 5, 12, ' وقال هامان : حتى إن أستير الملكة لم تدخل مع الملك إلى الوليمة التي عملتها إلا إياي . وأنا غدا أيضا مدعو إليها مع الملك '),
(10969, 'Esther', 17, 5, 13, ' وكل هذا لا يساوي عندي شيئا كلما أرى مردخاي اليهودي جالسا في باب الملك '),
(10970, 'Esther', 17, 5, 14, ' فقالت له زرش زوجته وكل أحبائه : فليعملوا خشبة ارتفاعها خمسون ذراعا ، وفي الصباح قل للملك أن يصلبوا مردخاي عليها ، ثم ادخل مع الملك إلى الوليمة فرحا . فحسن الكلام عند هامان وعمل الخشبة '),
(10971, 'Esther', 17, 6, 1, ' في تلك الليلة طار نوم الملك ، فأمر بأن يؤتى بسفر تذكار أخبار الأيام فقرئت أمام الملك '),
(10972, 'Esther', 17, 6, 2, ' فوجد مكتوبا ما أخبر به مردخاي عن بغثانا وترش خصيي الملك حارسي الباب ، اللذين طلبا أن يمدا أيديهما إلى الملك أحشويروش '),
(10973, 'Esther', 17, 6, 3, ' فقال الملك : أية كرامة وعظمة عملت لمردخاي لأجل هذا ؟  . فقال غلمان الملك الذين يخدمونه : لم يعمل معه شيء '),
(10974, 'Esther', 17, 6, 4, ' فقال الملك : من في الدار ؟  . وكان هامان قد دخل دار بيت الملك الخارجية لكي يقول للملك أن يصلب مردخاي على الخشبة التي أعدها له '),
(10975, 'Esther', 17, 6, 5, ' فقال غلمان الملك له : هوذا هامان واقف في الدار . فقال الملك : ليدخل '),
(10976, 'Esther', 17, 6, 6, ' ولما دخل هامان قال له الملك : ماذا يعمل لرجل يسر الملك بأن يكرمه ؟  . فقال هامان في قلبه : من يسر الملك بأن يكرمه أكثر مني '),
(10977, 'Esther', 17, 6, 7, ' فقال هامان للملك : إن الرجل الذي يسر الملك بأن يكرمه '),
(10978, 'Esther', 17, 6, 8, ' يأتون باللباس السلطاني الذي يلبسه الملك ، وبالفرس الذي يركبه الملك ، وبتاج الملك الذي يوضع على رأسه '),
(10979, 'Esther', 17, 6, 9, ' ويدفع اللباس والفرس لرجل من رؤساء الملك الأشراف ، ويلبسون الرجل الذي سر الملك بأن يكرمه ويركبونه على الفرس في ساحة المدينة ، وينادون قدامه : هكذا يصنع للرجل الذي يسر الملك بأن يكرمه '),
(10980, 'Esther', 17, 6, 10, ' فقال الملك لهامان : أسرع وخذ اللباس والفرس كما تكلمت ، وافعل هكذا لمردخاي اليهودي الجالس في باب الملك . لا يسقط شيء من جميع ما قلته '),
(10981, 'Esther', 17, 6, 11, ' فأخذ هامان اللباس والفرس وألبس مردخاي وأركبه في ساحة المدينة ، ونادى قدامه : هكذا يصنع للرجل الذي يسر الملك بأن يكرمه '),
(10982, 'Esther', 17, 6, 12, ' ورجع مردخاي إلى باب الملك . وأما هامان فأسرع إلى بيته نائحا ومغطى الرأس '),
(10983, 'Esther', 17, 6, 13, ' وقص هامان على زرش زوجته وجميع أحبائه كل ما أصابه . فقال له حكماؤه وزرش زوجته : إذا كان مردخاي الذي ابتدأت تسقط قدامه من نسل اليهود ، فلا تقدر عليه ، بل تسقط قدامه سقوطا '),
(10984, 'Esther', 17, 6, 14, ' وفيما هم يكلمونه وصل خصيان الملك وأسرعوا للإتيان بهامان إلى الوليمة التي عملتها أستير '),
(10985, 'Esther', 17, 7, 1, ' فجاء الملك وهامان ليشربا عند أستير الملكة '),
(10986, 'Esther', 17, 7, 2, ' فقال الملك لأستير في اليوم الثاني أيضا عند شرب الخمر : ما هو سؤلك يا أستير الملكة فيعطى لك ؟ وما هي طلبتك ؟ ولو إلى نصف المملكة تقضى '),
(10987, 'Esther', 17, 7, 3, ' فأجابت أستير الملكة وقالت : إن كنت قد وجدت نعمة في عينيك أيها الملك ، وإذا حسن عند الملك ، فلتعط لي نفسي بسؤلي ، وشعبي بطلبتي '),
(10988, 'Esther', 17, 7, 4, ' لأننا قد بعنا أنا وشعبي للهلاك والقتل والإبادة . ولو بعنا عبيدا وإماء لكنت سكت ، مع أن العدو لا يعوض عن خسارة الملك '),
(10989, 'Esther', 17, 7, 5, ' فتكلم الملك أحشويروش وقال لأستير الملكة : من هو ؟ وأين هو هذا الذي يتجاسر بقلبه على أن يعمل هكذا '),
(10990, 'Esther', 17, 7, 6, ' فقالت أستير : هو رجل خصم وعدو ، هذا هامان الرديء . فارتاع هامان أمام الملك والملكة '),
(10991, 'Esther', 17, 7, 7, ' فقام الملك بغيظه عن شرب الخمر إلى جنة القصر . ووقف هامان ليتوسل عن نفسه إلى أستير الملكة ، لأنه رأى أن الشر قد أعد عليه من قبل الملك '),
(10992, 'Esther', 17, 7, 8, ' ولما رجع الملك من جنة القصر إلى بيت شرب الخمر ، وهامان متواقع على السرير الذي كانت أستير عليه ، قال الملك : هل أيضا يكبس الملكة معي في البيت ؟  . ولما خرجت الكلمة من فم الملك غطوا وجه هامان '),
(10993, 'Esther', 17, 7, 9, ' فقال حربونا ، واحد من الخصيان الذين بين يدي الملك : هوذا الخشبة أيضا التي عملها هامان لمردخاي الذي تكلم بالخير نحو الملك قائمة في بيت هامان ، ارتفاعها خمسون ذراعا . فقال الملك : اصلبوه عليها '),
(10994, 'Esther', 17, 7, 10, ' فصلبوا هامان على الخشبة التي أعدها لمردخاي . ثم سكن غضب الملك '),
(10995, 'Esther', 17, 8, 1, ' في ذلك اليوم أعطى الملك أحشويروش لأستير الملكة بيت هامان عدو اليهود . وأتى مردخاي إلى أمام الملك لأن أستير أخبرته بما هو لها '),
(10996, 'Esther', 17, 8, 2, ' ونزع الملك خاتمه الذي أخذه من هامان وأعطاه لمردخاي . وأقامت أستير مردخاي على بيت هامان '),
(10997, 'Esther', 17, 8, 3, ' ثم عادت أستير وتكلمت أمام الملك وسقطت عند رجليه وبكت وتضرعت إليه أن يزيل شر هامان الأجاجي وتدبيره الذي دبره على اليهود '),
(10998, 'Esther', 17, 10, 4, 'و قال مردكاي ان هذا كله انما كان من قبل الله'),
(10999, 'Esther', 17, 10, 5, 'و قد ذكرت حلما رايته يشير الى ذلك فلم يسقط منه شيء'),
(11000, 'Esther', 17, 10, 6, 'ينبوع صغير ازداد فصار نهرا ثم انقلب فصار نورا وشمسا وفاض بمياه كثيرة فهذا هو استير التي اتخذها الملك زوجة وشاء ان تكون ملكة'),
(11001, 'Esther', 17, 10, 7, 'و التنينان انا وهامان'),
(11002, 'Esther', 17, 10, 8, 'و الامم المجتمعون هم الذين طلبوا ان يمحوا اسم اليهود'),
(11003, 'Esther', 17, 10, 9, 'و شعبي هو اسرائيل الذي صرخ الى الرب فانقذ الرب شعبه وخلصنا من جميع الشرور وصنع ايات عظيمة ومعجزات في الامم'),
(11004, 'Esther', 17, 10, 10, 'و امر ان يكون سهمان احدهما لشعب الله والاخر لجميع الامم'),
(11005, 'Esther', 17, 10, 11, 'فبرز السهمان امام الله في اليوم المسمى منذ ذلك الزمان لجميع الامم'),
(11006, 'Esther', 17, 10, 12, 'و ذكر الرب شعبه ورحم ميراثه'),
(11007, 'Esther', 17, 10, 13, 'لذلك يحفظ هذان اليومان من شهر اذار اليوم الرابع عشر والخامس عشر من هذا الشهر بكل غيرة وفرح فيجتمع الشعب جماعة واحدة في كل اجيال شعب اسرائيل فيما بعد'),
(11008, 'Esther', 17, 11, 1, 'كان في السنة الرابعة من ملك تلماي وكلوبطرا ان دوسيتاوس الذي كان يقول عن نفسه انه كاهن ومن نسل لاوي وابنه تلماي اتيا برسالة فوريم هذه قائلين انها قد ترجمت في اورشليم بيد لوسيماكوس بن تلماي'),
(11009, 'Esther', 17, 11, 2, 'و كان في السنة الثانية من ملك ارتحششتا الاكبر في اليوم الاول من شهر نيسان ان مردكاي بن يائير بن شمعي بن قيش من سبط بنيامين راى حلما'),
(11010, 'Esther', 17, 11, 3, 'و هو رجل يهودي مقيم بمدينة شوشن رجل عظيم من عظماء بلاط الملك'),
(11011, 'Esther', 17, 11, 4, 'و كان من جملة اهل الجلاء الذين اخذهم نبوكد نصر ملك بابل من اورشليم مع يكنيا ملك يهوذا'),
(11012, 'Esther', 17, 11, 5, 'و هذا حلمه راى كان اصواتا وضوضاء ورعودا وزلازل واضطرابا في الارض'),
(11013, 'Esther', 17, 11, 6, 'ثم اذا بتنينين عظيمين متهيئان للاقتتال'),
(11014, 'Esther', 17, 11, 7, 'و قد تهيجت كل الامم باصواتهما لتقاتل شعب الابرار'),
(11015, 'Esther', 17, 11, 8, 'و كان ذلك اليوم يوم ظلمة وهول وشدة وضنك ورعب عظيم على الارض'),
(11016, 'Esther', 17, 11, 9, 'فاضطرب شعب الابرار خوفا من شرورهم متوقعين الموت'),
(11017, 'Esther', 17, 11, 10, 'و صرخوا الى الله وفيما هم يصرخون اذا بينبوع صغير قد تكاثر حتى صار نهرا عظيما وفاض بمياه كثيرة'),
(11018, 'Esther', 17, 11, 11, 'ثم اشرق النور والشمس فارتفع المتواضعون وافترسوا المتجبرين'),
(11019, 'Esther', 17, 11, 12, 'فلما راى مردكاي ذلك ونهض من مضجعه كان يفكر في ماذا يريد الله ان يفعل وكان ذلك لا يبرح من نفسه وهو يرغب ان يعرف ما معنى الحلم'),
(11020, 'Esther', 17, 12, 1, 'و كان حينئذ يقف بباب الملك مع بجتان وتارش خصيي الملك وهما حاجبا البلاط'),
(11021, 'Esther', 17, 12, 2, 'فبعد ان وقف على نواياهما وتقصى مدققا علم انهما يحاولان ان يلقيا ايديهما على الملك ارتحششتا فاطلع الملك على ذلك'),
(11022, 'Esther', 17, 12, 3, 'فالقاهما تحت العذاب فاقرا فامر بان يساقا الى الموت'),
(11023, 'Esther', 17, 12, 4, 'و كتب الملك ما وقع في سفر اخبار الايام وكذلك مردكاي كتب ذكر الامر'),
(11024, 'Esther', 17, 12, 5, 'ثم امره الملك ان يقيم ببيت الملك وامر له بهبات لانه اطلعه على ذلك'),
(11025, 'Esther', 17, 12, 6, 'و كان هامان بن همداتا الاجاجي له عند الملك كرامة عظيمة فاراد ان يؤذي مردكاي وشعبه بسبب خصيي الملك المقتولين'),
(11026, 'Esther', 17, 13, 1, 'من ارتحششتا الاكبر المالك من الهند الى الحبشة على المئة والسبعة والعشرين اقليما الى الرؤساء والقواد الذين في طاعته سلام'),
(11027, 'Esther', 17, 13, 2, 'اني مع كوني متسلطا على شعوب كثيرين وقد اخضعت المسكونة باسرها تحت يدي لم احب ان اسيء انفاذ مقدرتي العظيمة ولكني حكمت بالرحمة والحلم حتى يقضوا حياتهم بلا خوف وبسكينة ويتمتعوا بالسلام الذي يصبو اليه كل بشر'),
(11028, 'Esther', 17, 13, 3, 'فسالت اصحاب مشورتي كيف يتم ذلك فكان ان واحدا منهم يفوق من سواه في الحكمة والامانة وهو ثنيان الملك اسمه هامان'),
(11029, 'Esther', 17, 13, 4, 'قال لي ان في المسكونة شعبا متشتتا له شرائع جديدة يتصرف بخلاف عادة جميع الامم ويحتقر اوامر الملوك ويفسد نظام جميع الامم بفتنته'),
(11030, 'Esther', 17, 13, 5, 'فلما وقفنا على هذا وراينا ان شعبا واحدا متمرد على الناس طائفة تتبع شرائع فاسدة وتخالف اوامرنا وتقلق سلام واتفاق جميع الاقاليم الخاضعة لنا'),
(11031, 'Esther', 17, 13, 6, 'امرنا ان كل من يشير اليهم هامان المولى على جميع الاقاليم وثنيان الملك الذي نكرمه بمنزلة اب يبادون بايدي اعدائهم هم ونساؤهم واولادهم ولا يرحمهم احد في اليوم الرابع عشر من الشهر الثاني عشر شهر اذار من هذه السنة'),
(11032, 'Esther', 17, 13, 7, 'حتى اذا هبط اولئك الناس الخبثاء الى الجحيم في يوم واحد يرد الى مملكتنا السلام الذي اقلقوه'),
(11033, 'Esther', 17, 13, 8, 'فاما مردكاي فتضرع الى الرب متذكرا جميع اعماله'),
(11034, 'Esther', 17, 13, 9, 'و قال اللهم ايها الرب الملك القادر على الكل اذ كل شيء في طاعتك وليس من يقاوم مشيئتك اذا هممت بنجاة اسرائيل'),
(11035, 'Esther', 17, 13, 10, 'انت صنعت السماء والارض وكل ما تحت السماوات'),
(11036, 'Esther', 17, 13, 11, 'انت رب الجميع وليس من يقاوم عزتك'),
(11037, 'Esther', 17, 13, 12, 'انك تعرف كل شيء وتعلم اني لا تكبرا ولا احتقارا ولا رغبة في شيء من الكرامة فعلت هذا اني لم اسجد لهامان العاتي'),
(11038, 'Esther', 17, 13, 13, 'فاني مستعد ان اقبل حتى اثار قدميه عن طيب نفس لاجل نجاة اسرائيل'),
(11039, 'Esther', 17, 13, 14, 'و لكن خفت ان احول كرامة الهي الى انسان واعبد احدا سوى الهي'),
(11040, 'Esther', 17, 13, 15, 'فالان ايها الرب الملك اله ابراهيم ارحم شعبك لان اعداءنا يطلبون ان يهلكونا ويستاصلوا ميراثك'),
(11041, 'Esther', 17, 13, 16, 'لا تهمل نصيبك الذي افتديته لك من مصر'),
(11042, 'Esther', 17, 13, 17, 'و استجب لتضرعي واعطف على نصيبك وميراثك وحول حزننا فرحا لنحيا ونسبح اسمك ايها الرب ولا تسدد افواه المرنمين لك'),
(11043, 'Esther', 17, 13, 18, 'و كذلك جميع اسرائيل بروح واحد وتضرع واحد صرخوا الى الرب من اجل ان الموت اشرف عليهم يقينا'),
(11044, 'Esther', 17, 14, 1, 'و ان استير الملكة ايضا التجئت الى الرب خوفا من الخطر المشرف'),
(11045, 'Esther', 17, 14, 2, 'فخلعت ثياب الملك ولبست ثيابا للحزن والبكاء وعوض الاطياب المختلفة القت على راسها رمادا وزبلا وذللت جسدها بالصوم وجميع المواضع التي كانت تفرح فيها من قبل ملاتها من نتاف شعر راسها'),
(11046, 'Esther', 17, 14, 3, 'و كانت تتضرع الى الرب اله اسرائيل قائلة ايها الرب الذي هو وحده ملكنا اعني انا المنقطعة التي ليس لها معين سواك'),
(11047, 'Esther', 17, 14, 4, 'فان خطري بين يدي'),
(11048, 'Esther', 17, 14, 5, 'لقد سمعت من ابي انك ايها الرب اتخذت اسرائيل من جميع الامم واباءنا من جميع اسلافهم الاقدمين لتحوزهم ميراثا ابديا وصنعت معهم كما قلت'),
(11049, 'Esther', 17, 14, 6, 'انا قد خطئنا امامك ولذلك اسلمتنا الى ايدي اعدائنا'),
(11050, 'Esther', 17, 14, 7, 'لانا عبدنا الهتهم وانت عادل ايها الرب'),
(11051, 'Esther', 17, 14, 8, 'و الان لم يكفهم انهم استعبدونا عبودية شاقة جدا بل بما انهم يعزون قوة ايديهم الى اوثانهم'),
(11052, 'Esther', 17, 14, 9, 'يحاولون ان ينقضوا مواعيدك ويمحوا ميراثك ويسدوا افواه المسبحين لك ويطفئوا مجد هيكلك ومذبحك'),
(11053, 'Esther', 17, 14, 10, 'ليفتحوا افواه الامم فيسبحوا لقوة الاوثان ويمجدوا ملكا بشريا الى الابد'),
(11054, 'Esther', 17, 14, 11, 'لا تسلم ايها الرب صولجانك الى من ليسوا بشيء لئلا يضحكوا من هلاكنا ولكن اردد مشورتهم عليهم واهلك الذي ابتدا يشدد علينا'),
(11055, 'Esther', 17, 14, 12, 'اذكرنا يا رب واستعلن لنا في وقت ضنكنا وهبني ثقة ايها الرب ملك الالهة وملك كل قدرة'),
(11056, 'Esther', 17, 14, 13, 'الق في فمي كلاما مرصفا بحضرة ذاك الاسد وحول قلبه الى بغض عدونا لكي يهلك هو وسائر المتواطئين معه'),
(11057, 'Esther', 17, 14, 14, 'و ايانا فانقذنا بيدك واعني انا التي لا معونة لها سواك ايها الرب العالم بكل شيء'),
(11058, 'Esther', 17, 14, 15, 'انك تعلم اني ابغض مجد الظالمين واكره مضجع القلف وجميع الغرباء'),
(11059, 'Esther', 17, 14, 16, 'و انت عالم بضرورتي واني اكره سمة ابهتي ومجدي التي احملها على راسي ايام بروزي وامقتها كفرصة الطامث ولا احملها في ايام قراري'),
(11060, 'Esther', 17, 14, 17, 'و اني لم اكل على مائدة هامان ولا لذذت بوليمة الملك ولم اشرب خمر السكب'),
(11061, 'Esther', 17, 14, 18, 'و لم افرح انا امتك منذ نقلت الى ههنا الى اليوم الا بك ايها الرب اله ابراهيم'),
(11062, 'Esther', 17, 14, 19, 'الاله القدير على الجميع فاستجب لاصوات الذين ليس لهم رجاء غيرك ونجنا من ايدي الاثماء وانقذني من مخافتي'),
(11063, 'Esther', 17, 15, 1, 'و ان استير الملكة ايضا التجئت الى الرب خوفا من الخطر المشرف'),
(11064, 'Esther', 17, 15, 2, 'و امرها ان تدخل على الملك وتتوسل اليه لاجل شعبها وارضها'),
(11065, 'Esther', 17, 15, 3, 'و قال اذكري ايام مذلتك حيث نشات على يدي فان هامان ثنيان الملك قد تكلم في اهلاكنا'),
(11066, 'Esther', 17, 15, 4, 'فادعي الرب وكلمي الملك في امرنا وخلصينا من الموت'),
(11067, 'Esther', 17, 15, 5, 'ثم انها في اليوم الثالث نزعت ثياب حدادها ولبست ملابس مجدها'),
(11068, 'Esther', 17, 15, 6, 'و لما تبرجت ببزة الملك ودعت مدبر ومخلص الجميع الله اتخذت لها جاريتين'),
(11069, 'Esther', 17, 15, 7, 'فكانت تستند الى احداهما كانها لم تكن تستطيع ان تستقل لكثرة ترفها ورخوصتها'),
(11070, 'Esther', 17, 15, 8, 'و الجارية الاخرى كانت تتبع مولاتها رافعا اذيالها المنسحبة على الارض'),
(11071, 'Esther', 17, 15, 9, 'و كان احمرار وجهها وجمال عينيها ولمعانهما يخفي كابة نفسها المنقبضة بشدة خوفها'),
(11072, 'Esther', 17, 15, 10, 'فدخلت كل الابواب بابا بابا ثم وقفت قبالة الملك حيث كان جالسا على عرش ملكه بلباس الملك مزينا بالذهب والجواهر ومنظره رهيب'),
(11073, 'Esther', 17, 15, 11, 'فلما رفع وجهه ولاح من اتقاد عينيه غضب صدره سقطت الملكة واستحال لون وجهها الى صفرة واتكات راسها على الجارية استرخاء'),
(11074, 'Esther', 17, 15, 12, 'فحول الله روح الملك الى الحلم فاسرع ونهض عن العرش مشفقا وضمها بذراعيه حتى ثابت الى نفسها وكان يلاطفها بهذاالكلام'),
(11075, 'Esther', 17, 15, 13, 'ما لك يا استر انا اخوك لا تخافي'),
(11076, 'Esther', 17, 15, 14, 'انك لا تموتين انما الشريعة ليست عليك ولكن على العامة'),
(11077, 'Esther', 17, 15, 15, 'هلمي والمسي الصولجان'),
(11078, 'Esther', 17, 15, 16, 'و اذ لم تزل ساكتة اخذ صولجان الذهب وجعله على عنقها وقبلها وقال لماذا لا تكلمينني'),
(11079, 'Esther', 17, 15, 17, 'فاجابت وقالت اني رايتك يا سيدي كانك ملاك الله فاضطرب قلبي هيبة من مجدك'),
(11080, 'Esther', 17, 15, 18, 'لانك عجيب جدا يا سيدي ووجهك مملوء نعمة'),
(11081, 'Esther', 17, 15, 19, 'و فيما هي تتكلم سقطت ثانية وكاد يغشى عليها'),
(11082, 'Esther', 17, 15, 20, 'فاضطرب الملك وكان جميع اعوانه يلاطفونها'),
(11083, 'Esther', 17, 16, 1, 'من ارتحششتا العظيم المالك من الهند الى الحبشة الى القواد والرؤساء في المئة والسبعة والعشرين اقليما التي في طاعتنا سلام'),
(11084, 'Esther', 17, 16, 2, 'ان كثيرين يسيئون اتخاذ المجد الممنوح لهم فيتكبرون'),
(11085, 'Esther', 17, 16, 3, 'و يجتهدون لا ان يظلموا رعية الملوك فقط ولكن اذ لا يحسنون تحمل المجد الممنوح لهم يتامرون على الذين منحوه لهم'),
(11086, 'Esther', 17, 16, 4, 'و لا يكتفون بان لا يشكروا على الانعام وان ينابذوا الحقوق الانسانية بل يتوهمون انهم يستطيعون ان يفروا من قضاء الله المطلع على كل شيء'),
(11087, 'Esther', 17, 16, 5, 'و قد بلغ من حماقتهم انهم يحاولون بمكايد اكاذيبهم ان يسقطوا الذين سلمت اليهم المناصب وهم يجرونها بالتحري ويفعلون كل مايستاهلون به شكر الجميع'),
(11088, 'Esther', 17, 16, 6, 'و يخدعوا باحتيال مكرهم مسامع الرؤساء السليمة الذين يقيسون طباع غيرهم على طباعهم'),
(11089, 'Esther', 17, 16, 7, 'و هذا امر مختبر من التواريخ القديمة ومما يحدث كل يوم ان دسائس البعض تفسد خواطر الملوك الصالحة'),
(11090, 'Esther', 17, 16, 8, 'فلذلك ينبغي ان ينظر في سلم جميع الاقاليم'),
(11091, 'Esther', 17, 16, 9, 'فلا ينبغي ان يظن اننا نامر باشياء متباينة عن خفة عقل بل ذلك ناشئ عن اختلاف الازمنة وضروراتها التي حملتنا على ابراز الحكم بحسب مقتضى نفع الجميع'),
(11092, 'Esther', 17, 16, 10, 'و لكي تفهموا كلامنا باوضح بيانا فان هامان بن همداتا الذي هو مكدوني جنسا ومشربا وهو غريب عن دم الفرس وقد فضح رحمتنا بقساوته بعد ان اويناه غريبا'),
(11093, 'Esther', 17, 16, 11, 'و بعدما احسنا اليه حتى كان يدعى ابا لنا وكان الجميع يسجدون له سجودهم لثنيان الملك'),
(11094, 'Esther', 17, 16, 12, 'قد بلغ من شدة عتوه انه اجتهد ان يسلبنا الملك والحياة'),
(11095, 'Esther', 17, 16, 13, 'لانه سعى بدسائس جديدة لم تسمع باهلاك مردكاي الذي انما نحن في الحياة من امانته واحسانه وباهلاك قرينة ملكنا استير وسائر شعبها'),
(11096, 'Esther', 17, 16, 14, 'و كان في نفسه انه بعد قتلهم يترصد لنا في خلوتنا ويحول مملكة الفرس الى المكدونيين'),
(11097, 'Esther', 17, 16, 15, 'و نحن لم نجد قط ذنبا في اليهود المقضي عليهم بالموت بقضاء اخبث البشر بل بعكس ذلك وجدنا ان لهم سننا عادلة'),
(11098, 'Esther', 17, 16, 16, 'و هم بنو الله العلي العظيم الحي الى الابد الذي باحسانه سلم الملك الى ابائنا والينا وما برح محفوظا الى اليوم'),
(11099, 'Esther', 17, 16, 17, 'و حيث ذلك فاعلموا ان الرسائل التي وجهها باسمنا هي باطلة'),
(11100, 'Esther', 17, 16, 18, 'و بسبب تلك الجريمة قد علق امام ابواب هذه المدينة شوشن هو صاحب تلك المؤامرة وجميع انسبائه على خشبات فنال بذلك جزاء ما استحق من قبل الله لا من قبلنا'),
(11101, 'Esther', 17, 16, 19, 'فليعلن هذا الامر الذي نحن منفذوه الان في جميع المدن ليباح لليهود ان يعملوا بسننهم'),
(11102, 'Esther', 17, 16, 20, 'و ينبغي لكم ان تعضدوهم حتى يستمكنوا من قتل الذين كانوا متاهبين لقتلهم في اليوم الثالث عشر من الشهر الثاني عشر الذي يدعى اذار'),
(11103, 'Esther', 17, 16, 21, 'فان ذلك اليوم الذي كان لهم يوم حزن ونحيب قد حوله لهم الله القدير الى فرح'),
(11104, 'Esther', 17, 16, 22, 'و انتم ايضا فانظموا هذا اليوم بين سائر ايام الاعياد الاخرى وعيدوه بكل فرح حتى يعلم فيما بعد'),
(11105, 'Esther', 17, 16, 23, 'ان كل من يطيع الفرس بامانة يثاب على امانته ثوابا وافيا ومن يرصد لملكهم يهلك بجنايته'),
(11106, 'Esther', 17, 16, 24, 'و كل اقليم او مدينة يابى ان يشترك في هذا العيد فليهلك بالسيف والنار لا الناس فقط بل البهائم ايضا ليكون الى الابد عبرة للاستخفاف والعصيان'),
(11107, 'Exodus', 2, 1, 4, ' ودان ونفتالي وجاد وأشير '),
(11108, 'Exodus', 2, 1, 5, ' وكانت جميع نفوس الخارجين من صلب يعقوب سبعين نفسا . ولكن يوسف كان في مصر '),
(11109, 'Exodus', 2, 1, 6, ' ومات يوسف وكل إخوته وجميع ذلك الجيل '),
(11110, 'Exodus', 2, 1, 7, ' وأما بنو إسرائيل فأثمروا وتوالدوا ونموا وكثروا كثيرا جدا ، وامتلأت الأرض منهم '),
(11111, 'Exodus', 2, 1, 8, ' ثم قام ملك جديد على مصر لم يكن يعرف يوسف '),
(11112, 'Exodus', 2, 1, 9, ' فقال لشعبه : هوذا بنو إسرائيل شعب أكثر وأعظم منا '),
(11113, 'Exodus', 2, 1, 10, ' هلم نحتال لهم لئلا ينموا ، فيكون إذا حدثت حرب أنهم ينضمون إلى أعدائنا ويحاربوننا ويصعدون من الأرض '),
(11114, 'Exodus', 2, 1, 11, ' فجعلوا عليهم رؤساء تسخير لكي يذلوهم بأثقالهم ، فبنوا لفرعون مدينتي مخازن : فيثوم ، ورعمسيس '),
(11115, 'Exodus', 2, 1, 12, ' ولكن بحسبما أذلوهم هكذا نموا وامتدوا . فاختشوا من بني إسرائيل '),
(11116, 'Exodus', 2, 1, 13, ' فاستعبد المصريون بني إسرائيل بعنف '),
(11117, 'Exodus', 2, 1, 14, ' ومرروا حياتهم بعبودية قاسية في الطين واللبن وفي كل عمل في الحقل . كل عملهم الذي عملوه بواسطتهم عنفا '),
(11118, 'Exodus', 2, 1, 15, ' وكلم ملك مصر قابلتي العبرانيات اللتين اسم إحداهما شفرة واسم الأخرى فوعة '),
(11119, 'Exodus', 2, 1, 16, ' وقال : حينما تولدان العبرانيات وتنظرانهن على الكراسي ، إن كان ابنا فاقتلاه ، وإن كان بنتا فتحيا '),
(11120, 'Exodus', 2, 1, 17, ' ولكن القابلتين خافتا الله ولم تفعلا كما كلمهما ملك مصر ، بل استحيتا الأولاد '),
(11121, 'Exodus', 2, 1, 18, ' فدعا ملك مصر القابلتين وقال لهما : لماذا فعلتما هذا الأمر واستحييتما الأولاد '),
(11122, 'Exodus', 2, 1, 19, ' فقالت القابلتان لفرعون : إن النساء العبرانيات لسن كالمصريات ، فإنهن قويات يلدن قبل أن تأتيهن القابلة '),
(11123, 'Exodus', 2, 1, 20, ' فأحسن الله إلى القابلتين ، ونما الشعب وكثر جدا '),
(11124, 'Exodus', 2, 1, 21, ' وكان إذ خافت القابلتان الله أنه صنع لهما بيوتا '),
(11125, 'Exodus', 2, 1, 22, ' ثم أمر فرعون جميع شعبه قائلا : كل ابن يولد تطرحونه في النهر ، لكن كل بنت تستحيونها '),
(11126, 'Exodus', 2, 2, 1, ' وذهب رجل من بيت لاوي وأخذ بنت لاوي '),
(11127, 'Exodus', 2, 2, 2, ' فحبلت المرأة وولدت ابنا . ولما رأته أنه حسن ، خبأته ثلاثة أشهر '),
(11128, 'Exodus', 2, 2, 3, ' ولما لم يمكنها أن تخبئه بعد ، أخذت له سفطا من البردي وطلته بالحمر والزفت ، ووضعت الولد فيه ، ووضعته بين الحلفاء على حافة النهر '),
(11129, 'Exodus', 2, 2, 4, ' ووقفت أخته من بعيد لتعرف ماذا يفعل به '),
(11130, 'Exodus', 2, 2, 5, ' فنزلت ابنة فرعون إلى النهر لتغتسل ، وكانت جواريها ماشيات على جانب النهر . فرأت السفط بين الحلفاء ، فأرسلت أمتها وأخذته '),
(11131, 'Exodus', 2, 2, 6, ' ولما فتحته رأت الولد ، وإذا هو صبي يبكي . فرقت له وقالت : هذا من أولاد العبرانيين '),
(11132, 'Exodus', 2, 2, 7, ' فقالت أخته لابنة فرعون : هل أذهب وأدعو لك امرأة مرضعة من العبرانيات لترضع لك الولد '),
(11133, 'Exodus', 2, 2, 8, ' فقالت لها ابنة فرعون : اذهبي . فذهبت الفتاة ودعت أم الولد '),
(11134, 'Exodus', 2, 2, 9, ' فقالت لها ابنة فرعون : اذهبي بهذا الولد وأرضعيه لي وأنا أعطي أجرتك . فأخذت المرأة الولد وأرضعته '),
(11135, 'Exodus', 2, 2, 10, ' ولما كبر الولد جاءت به إلى ابنة فرعون فصار لها ابنا ، ودعت اسمه موسى وقالت : إني انتشلته من الماء '),
(11136, 'Exodus', 2, 2, 11, ' وحدث في تلك الأيام لما كبر موسى أنه خرج إلى إخوته لينظر في أثقالهم ، فرأى رجلا مصريا يضرب رجلا عبرانيا من إخوته '),
(11137, 'Exodus', 2, 2, 12, ' فالتفت إلى هنا وهناك ورأى أن ليس أحد ، فقتل المصري وطمره في الرمل '),
(11138, 'Exodus', 2, 2, 13, ' ثم خرج في اليوم الثاني وإذا رجلان عبرانيان يتخاصمان ، فقال للمذنب : لماذا تضرب صاحبك '),
(11139, 'Exodus', 2, 2, 14, ' فقال : من جعلك رئيسا وقاضيا علينا ؟ أمفتكر أنت بقتلي كما قتلت المصري ؟  . فخاف موسى وقال : حقا قد عرف الأمر '),
(11140, 'Exodus', 2, 2, 15, ' فسمع فرعون هذا الأمر ، فطلب أن يقتل موسى . فهرب موسى من وجه فرعون وسكن في أرض مديان ، وجلس عند البئر '),
(11141, 'Exodus', 2, 2, 16, ' وكان لكاهن مديان سبع بنات ، فأتين واستقين وملأن الأجران ليسقين غنم أبيهن '),
(11142, 'Exodus', 2, 2, 17, ' فأتى الرعاة وطردوهن . فنهض موسى وأنجدهن وسقى غنمهن '),
(11143, 'Exodus', 2, 2, 18, ' فلما أتين إلى رعوئيل أبيهن قال : ما بالكن أسرعتن في المجيء اليوم '),
(11144, 'Exodus', 2, 2, 19, ' فقلن : رجل مصري أنقذنا من أيدي الرعاة ، وإنه استقى لنا أيضا وسقى الغنم '),
(11145, 'Exodus', 2, 2, 20, ' فقال لبناته : وأين هو ؟ لماذا تركتن الرجل ؟ ادعونه ليأكل طعاما '),
(11146, 'Exodus', 2, 2, 21, ' فارتضى موسى أن يسكن مع الرجل ، فأعطى موسى صفورة ابنته '),
(11147, 'Exodus', 2, 2, 22, ' فولدت ابنا فدعا اسمه جرشوم ، لأنه قال : كنت نزيلا في أرض غريبة '),
(11148, 'Exodus', 2, 2, 23, ' وحدث في تلك الأيام الكثيرة أن ملك مصر مات . وتنهد بنو إسرائيل من العبودية وصرخوا ، فصعد صراخهم إلى الله من أجل العبودية '),
(11149, 'Exodus', 2, 2, 24, ' فسمع الله أنينهم ، فتذكر الله ميثاقه مع إبراهيم وإسحاق ويعقوب '),
(11150, 'Exodus', 2, 2, 25, ' ونظر الله بني إسرائيل وعلم الله '),
(11151, 'Exodus', 2, 3, 1, ' وأما موسى فكان يرعى غنم يثرون حميه كاهن مديان ، فساق الغنم إلى وراء البرية وجاء إلى جبل الله حوريب '),
(11152, 'Exodus', 2, 3, 2, ' وظهر له ملاك الرب بلهيب نار من وسط عليقة . فنظر وإذا العليقة تتوقد بالنار ، والعليقة لم تكن تحترق '),
(11153, 'Exodus', 2, 3, 3, ' فقال موسى : أميل الآن لأنظر هذا المنظر العظيم . لماذا لا تحترق العليقة '),
(11154, 'Exodus', 2, 3, 4, ' فلما رأى الرب أنه مال لينظر ، ناداه الله من وسط العليقة وقال : موسى ، موسى . فقال : هأنذا '),
(11155, 'Exodus', 2, 3, 5, ' فقال : لا تقترب إلى ههنا . اخلع حذاءك من رجليك ، لأن الموضع الذي أنت واقف عليه أرض مقدسة '),
(11156, 'Exodus', 2, 3, 6, ' ثم قال : أنا إله أبيك ، إله إبراهيم وإله إسحاق وإله يعقوب . فغطى موسى وجهه لأنه خاف أن ينظر إلى الله '),
(11157, 'Exodus', 2, 3, 7, ' فقال الرب : إني قد رأيت مذلة شعبي الذي في مصر وسمعت صراخهم من أجل مسخريهم . إني علمت أوجاعهم '),
(11158, 'Exodus', 2, 3, 8, ' فنزلت لأنقذهم من أيدي المصريين ، وأصعدهم من تلك الأرض إلى أرض جيدة وواسعة ، إلى أرض تفيض لبنا وعسلا ، إلى مكان الكنعانيين والحثيين والأموريين والفرزيين والحويين واليبوسيين '),
(11159, 'Exodus', 2, 3, 9, ' والآن هوذا صراخ بني إسرائيل قد أتى إلي ، ورأيت أيضا الضيقة التي يضايقهم بها المصريون '),
(11160, 'Exodus', 2, 3, 10, ' فالآن هلم فأرسلك إلى فرعون ، وتخرج شعبي بني إسرائيل من مصر '),
(11161, 'Exodus', 2, 3, 11, ' فقال موسى لله : من أنا حتى أذهب إلى فرعون ، وحتى أخرج بني إسرائيل من مصر '),
(11162, 'Exodus', 2, 3, 12, ' فقال : إني أكون معك ، وهذه تكون لك العلامة أني أرسلتك : حينما تخرج الشعب من مصر ، تعبدون الله على هذا الجبل '),
(11163, 'Exodus', 2, 3, 13, ' فقال موسى لله : ها أنا آتي إلى بني إسرائيل وأقول لهم : إله آبائكم أرسلني إليكم . فإذا قالوا لي : ما اسمه ؟ فماذا أقول لهم '),
(11164, 'Exodus', 2, 3, 14, ' فقال الله لموسى : أهيه الذي أهيه . وقال : هكذا تقول لبني إسرائيل : أهيه أرسلني إليكم '),
(11165, 'Exodus', 2, 3, 15, ' وقال الله أيضا لموسى : هكذا تقول لبني إسرائيل : يهوه إله آبائكم ، إله إبراهيم وإله إسحاق وإله يعقوب أرسلني إليكم . هذا اسمي إلى الأبد وهذا ذكري إلى دور فدور '),
(11166, 'Exodus', 2, 3, 16, ' اذهب واجمع شيوخ إسرائيل وقل لهم : الرب إله آبائكم ، إله إبراهيم وإسحاق ويعقوب ظهر لي قائلا : إني قد افتقدتكم وما صنع بكم في مصر '),
(11167, 'Exodus', 2, 3, 17, ' فقلت أصعدكم من مذلة مصر إلى أرض الكنعانيين والحثيين والأموريين والفرزيين والحويين واليبوسيين ، إلى أرض تفيض لبنا وعسلا '),
(11168, 'Exodus', 2, 3, 18, ' فإذا سمعوا لقولك ، تدخل أنت وشيوخ بني إسرائيل إلى ملك مصر وتقولون له : الرب إله العبرانيين التقانا ، فالآن نمضي سفر ثلاثة أيام في البرية ونذبح للرب إلهنا '),
(11169, 'Exodus', 2, 3, 19, ' ولكني أعلم أن ملك مصر لا يدعكم تمضون ولا بيد قوية '),
(11170, 'Exodus', 2, 3, 20, ' فأمد يدي وأضرب مصر بكل عجائبي التي أصنع فيها . وبعد ذلك يطلقكم '),
(11171, 'Exodus', 2, 3, 21, ' وأعطي نعمة لهذا الشعب في عيون المصريين . فيكون حينما تمضون أنكم لا تمضون فارغين '),
(11172, 'Exodus', 2, 3, 22, ' بل تطلب كل امرأة من جارتها ومن نزيلة بيتها أمتعة فضة وأمتعة ذهب وثيابا ، وتضعونها على بنيكم وبناتكم . فتسلبون المصريين '),
(11173, 'Exodus', 2, 4, 1, ' فأجاب موسى وقال : ولكن ها هم لا يصدقونني ولا يسمعون لقولي ، بل يقولون : لم يظهر لك الرب '),
(11174, 'Exodus', 2, 4, 2, ' فقال له الرب : ما هذه في يدك ؟ فقال : عصا '),
(11175, 'Exodus', 2, 4, 3, ' فقال : اطرحها إلى الأرض . فطرحها إلى الأرض فصارت حية ، فهرب موسى منها '),
(11176, 'Exodus', 2, 4, 4, ' ثم قال الرب لموسى : مد يدك وأمسك بذنبها . فمد يده وأمسك به ، فصارت عصا في يده '),
(11177, 'Exodus', 2, 4, 5, ' لكي يصدقوا أنه قد ظهر لك الرب إله آبائهم ، إله إبراهيم وإله إسحاق وإله يعقوب '),
(11178, 'Exodus', 2, 4, 6, ' ثم قال له الرب أيضا : أدخل يدك في عبك . فأدخل يده في عبه ثم أخرجها ، وإذا يده برصاء مثل الثلج '),
(11179, 'Exodus', 2, 4, 7, ' ثم قال له : رد يدك إلى عبك . فرد يده إلى عبه ثم أخرجها من عبه ، وإذا هي قد عادت مثل جسده '),
(11180, 'Exodus', 2, 4, 8, ' فيكون إذا لم يصدقوك ولم يسمعوا لصوت الآية الأولى ، أنهم يصدقون صوت الآية الأخيرة '),
(11181, 'Exodus', 2, 4, 9, ' ويكون إذا لم يصدقوا هاتين الآيتين ، ولم يسمعوا لقولك ، أنك تأخذ من ماء النهر وتسكب على اليابسة ، فيصير الماء الذي تأخذه من النهر دما على اليابسة '),
(11182, 'Exodus', 2, 4, 10, ' فقال موسى للرب : استمع أيها السيد ، لست أنا صاحب كلام منذ أمس ولا أول من أمس ، ولا من حين كلمت عبدك ، بل أنا ثقيل الفم واللسان '),
(11183, 'Exodus', 2, 4, 11, ' فقال له الرب : من صنع للإنسان فما ؟ أو من يصنع أخرس أو أصم أو بصيرا أو أعمى ؟ أما هو أنا الرب '),
(11184, 'Exodus', 2, 4, 12, ' فالآن اذهب وأنا أكون مع فمك وأعلمك ما تتكلم به '),
(11185, 'Exodus', 2, 4, 13, ' فقال : استمع أيها السيد ، أرسل بيد من ترسل '),
(11186, 'Exodus', 2, 4, 14, ' فحمي غضب الرب على موسى وقال : أليس هارون اللاوي أخاك ؟ أنا أعلم أنه هو يتكلم ، وأيضا ها هو خارج لاستقبالك . فحينما يراك يفرح بقلبه '),
(11187, 'Exodus', 2, 4, 15, ' فتكلمه وتضع الكلمات في فمه ، وأنا أكون مع فمك ومع فمه ، وأعلمكما ماذا تصنعان '),
(11188, 'Exodus', 2, 4, 16, ' وهو يكلم الشعب عنك . وهو يكون لك فما ، وأنت تكون له إلها '),
(11189, 'Exodus', 2, 4, 17, ' وتأخذ في يدك هذه العصا التي تصنع بها الآيات '),
(11190, 'Exodus', 2, 4, 18, ' فمضى موسى ورجع إلى يثرون حميه وقال له : أنا أذهب وأرجع إلى إخوتي الذين في مصر لأرى هل هم بعد أحياء . فقال يثرون لموسى : اذهب بسلام '),
(11191, 'Exodus', 2, 4, 19, ' وقال الرب لموسى في مديان : اذهب ارجع إلى مصر ، لأنه قد مات جميع القوم الذين كانوا يطلبون نفسك '),
(11192, 'Exodus', 2, 4, 20, ' فأخذ موسى امرأته وبنيه وأركبهم على الحمير ورجع إلى أرض مصر . وأخذ موسى عصا الله في يده '),
(11193, 'Exodus', 2, 4, 21, ' وقال الرب لموسى : عندما تذهب لترجع إلى مصر ، انظر جميع العجائب التي جعلتها في يدك واصنعها قدام فرعون . ولكني أشدد قلبه حتى لا يطلق الشعب '),
(11194, 'Exodus', 2, 4, 22, ' فتقول لفرعون : هكذا يقول الرب : إسرائيل ابني البكر '),
(11195, 'Exodus', 2, 4, 23, ' فقلت لك : أطلق ابني ليعبدني ، فأبيت أن تطلقه . ها أنا أقتل ابنك البكر '),
(11196, 'Exodus', 2, 4, 24, ' وحدث في الطريق في المنزل أن الرب التقاه وطلب أن يقتله '),
(11197, 'Exodus', 2, 4, 25, ' فأخذت صفورة صوانة وقطعت غرلة ابنها ومست رجليه . فقالت : إنك عريس دم لي '),
(11198, 'Exodus', 2, 4, 26, ' فانفك عنه . حينئذ قالت : عريس دم من أجل الختان '),
(11199, 'Exodus', 2, 4, 27, ' وقال الرب لهارون : اذهب إلى البرية لاستقبال موسى . فذهب والتقاه في جبل الله وقبله '),
(11200, 'Exodus', 2, 4, 28, ' فأخبر موسى هارون بجميع كلام الرب الذي أرسله ، وبكل الآيات التي أوصاه بها '),
(11201, 'Exodus', 2, 4, 29, ' ثم مضى موسى وهارون وجمعا جميع شيوخ بني إسرائيل '),
(11202, 'Exodus', 2, 4, 30, ' فتكلم هارون بجميع الكلام الذي كلم الرب موسى به ، وصنع الآيات أمام عيون الشعب '),
(11203, 'Exodus', 2, 4, 31, ' فآمن الشعب . ولما سمعوا أن الرب افتقد بني إسرائيل وأنه نظر مذلتهم ، خروا وسجدوا ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(11204, 'Exodus', 2, 5, 1, ' وبعد ذلك دخل موسى وهارون وقالا لفرعون : هكذا يقول الرب إله إسرائيل : أطلق شعبي ليعيدوا لي في البرية '),
(11205, 'Exodus', 2, 5, 2, ' فقال فرعون : من هو الرب حتى أسمع لقوله فأطلق إسرائيل ؟ لا أعرف الرب ، وإسرائيل لا أطلقه '),
(11206, 'Exodus', 2, 5, 3, ' فقالا : إله العبرانيين قد التقانا ، فنذهب سفر ثلاثة أيام في البرية ونذبح للرب إلهنا ، لئلا يصيبنا بالوبإ أو بالسيف '),
(11207, 'Exodus', 2, 5, 4, ' فقال لهما ملك مصر : لماذا يا موسى وهارون تبطلان الشعب من أعماله ؟ اذهبا إلى أثقالكما '),
(11208, 'Exodus', 2, 5, 5, ' وقال فرعون : هوذا الآن شعب الأرض كثير وأنتما تريحانهم من أثقالهم '),
(11209, 'Exodus', 2, 5, 6, ' فأمر فرعون في ذلك اليوم مسخري الشعب ومدبريه قائلا '),
(11210, 'Exodus', 2, 5, 7, ' لا تعودوا تعطون الشعب تبنا لصنع اللبن كأمس وأول من أمس . ليذهبوا هم ويجمعوا تبنا لأنفسهم '),
(11211, 'Exodus', 2, 5, 8, ' ومقدار اللبن الذي كانوا يصنعونه أمس ، وأول من أمس تجعلون عليهم . لا تنقصوا منه ، فإنهم متكاسلون ، لذلك يصرخون قائلين : نذهب ونذبح لإلهنا '),
(11212, 'Exodus', 2, 5, 9, ' ليثقل العمل على القوم حتى يشتغلوا به ولا يلتفتوا إلى كلام الكذب '),
(11213, 'Exodus', 2, 5, 10, ' فخرج مسخرو الشعب ومدبروه وكلموا الشعب ، قائلين : هكذا يقول فرعون : لست أعطيكم تبنا '),
(11214, 'Exodus', 2, 5, 11, ' اذهبوا أنتم وخذوا لأنفسكم تبنا من حيث تجدون . إنه لا ينقص من عملكم شيء '),
(11215, 'Exodus', 2, 5, 12, ' فتفرق الشعب في كل أرض مصر ليجمعوا قشا عوضا عن التبن '),
(11216, 'Exodus', 2, 5, 13, ' وكان المسخرون يعجلونهم قائلين : كملوا أعمالكم ، أمر كل يوم بيومه ، كما كان حينما كان التبن '),
(11217, 'Exodus', 2, 5, 14, ' فضرب مدبرو بني إسرائيل الذين أقامهم عليهم مسخرو فرعون ، وقيل لهم : لماذا لم تكملوا فريضتكم من صنع اللبن أمس واليوم كالأمس وأول من أمس '),
(11218, 'Exodus', 2, 5, 15, ' فأتى مدبرو بني إسرائيل وصرخوا إلى فرعون قائلين : لماذا تفعل هكذا بعبيدك '),
(11219, 'Exodus', 2, 5, 16, ' التبن ليس يعطى لعبيدك ، واللبن يقولون لنا : اصنعوه وهوذا عبيدك مضروبون ، وقد أخطأ شعبك '),
(11220, 'Exodus', 2, 5, 17, ' فقال : متكاسلون أنتم ، متكاسلون لذلك تقولون : نذهب ونذبح للرب '),
(11221, 'Exodus', 2, 5, 18, ' فالآن اذهبوا اعملوا . وتبن لا يعطى لكم ومقدار اللبن تقدمونه '),
(11222, 'Exodus', 2, 5, 19, ' فرأى مدبرو بني إسرائيل أنفسهم في بلية إذ قيل لهم لا تنقصوا من لبنكم أمر كل يوم بيومه '),
(11223, 'Exodus', 2, 5, 20, ' وصادفوا موسى وهارون واقفين للقائهم حين خرجوا من لدن فرعون '),
(11224, 'Exodus', 2, 5, 21, ' فقالوا لهما : ينظر الرب إليكما ويقضي ، لأنكما أنتنتما رائحتنا في عيني فرعون وفي عيون عبيده حتى تعطيا سيفا في أيديهم ليقتلونا '),
(11225, 'Exodus', 2, 5, 22, ' فرجع موسى إلى الرب وقال : يا سيد ، لماذا أسأت إلى هذا الشعب ؟ لماذا أرسلتني '),
(11226, 'Exodus', 2, 5, 23, ' فإنه منذ دخلت إلى فرعون لأتكلم باسمك ، أساء إلى هذا الشعب . وأنت لم تخلص شعبك '),
(11227, 'Exodus', 2, 6, 1, ' فقال الرب لموسى : الآن تنظر ما أنا أفعل بفرعون . فإنه بيد قوية يطلقهم ، وبيد قوية يطردهم من أرضه '),
(11228, 'Exodus', 2, 6, 2, ' ثم كلم الله موسى وقال له : أنا الرب '),
(11229, 'Exodus', 2, 6, 3, ' وأنا ظهرت لإبراهيم وإسحاق ويعقوب بأني الإله القادر على كل شيء . وأما باسمي يهوه فلم أعرف عندهم '),
(11230, 'Exodus', 2, 6, 4, ' وأيضا أقمت معهم عهدي : أن أعطيهم أرض كنعان أرض غربتهم التي تغربوا فيها '),
(11231, 'Exodus', 2, 6, 5, ' وأنا أيضا قد سمعت أنين بني إسرائيل الذين يستعبدهم المصريون ، وتذكرت عهدي '),
(11232, 'Exodus', 2, 6, 6, ' لذلك قل لبني إسرائيل : أنا الرب . وأنا أخرجكم من تحت أثقال المصريين وأنقذكم من عبوديتهم وأخلصكم بذراع ممدودة وبأحكام عظيمة '),
(11233, 'Exodus', 2, 6, 7, ' وأتخذكم لي شعبا ، وأكون لكم إلها . فتعلمون أني أنا الرب إلهكم الذي يخرجكم من تحت أثقال المصريين '),
(11234, 'Exodus', 2, 6, 8, ' وأدخلكم إلى الأرض التي رفعت يدي أن أعطيها لإبراهيم وإسحاق ويعقوب . وأعطيكم إياها ميراثا . أنا الرب '),
(11235, 'Exodus', 2, 6, 9, ' فكلم موسى هكذا بني إسرائيل ، ولكن لم يسمعوا لموسى من صغر النفس ، ومن العبودية القاسية '),
(11236, 'Exodus', 2, 6, 10, ' ثم كلم الرب موسى قائلا '),
(11237, 'Exodus', 2, 6, 11, ' ادخل قل لفرعون ملك مصر أن يطلق بني إسرائيل من أرضه '),
(11238, 'Exodus', 2, 6, 12, ' فتكلم موسى أمام الرب قائلا : هوذا بنو إسرائيل لم يسمعوا لي ، فكيف يسمعني فرعون وأنا أغلف الشفتين '),
(11239, 'Exodus', 2, 6, 13, ' فكلم الرب موسى وهارون ، وأوصى معهما إلى بني إسرائيل وإلى فرعون ملك مصر في إخراج بني إسرائيل من أرض مصر '),
(11240, 'Exodus', 2, 6, 14, ' هؤلاء رؤساء بيوت آبائهم : بنو رأوبين بكر إسرائيل : حنوك وفلو وحصرون وكرمي . هذه عشائر رأوبين '),
(11241, 'Exodus', 2, 6, 15, ' وبنو شمعون : يموئيل ويامين وأوهد وياكين وصوحر وشأول ابن الكنعانية . هذه عشائر شمعون '),
(11242, 'Exodus', 2, 6, 16, ' وهذه أسماء بني لاوي بحسب مواليدهم : جرشون وقهات ومراري . وكانت سنو حياة لاوي مئة وسبعا وثلاثين سنة '),
(11243, 'Exodus', 2, 6, 17, ' ابنا جرشون : لبني وشمعي بحسب عشائرهما '),
(11244, 'Exodus', 2, 6, 18, ' وبنو قهات : عمرام ويصهار وحبرون وعزيئيل . وكانت سنو حياة قهات مئة وثلاثا وثلاثين سنة '),
(11245, 'Exodus', 2, 6, 19, ' وابنا مراري : محلي وموشي . هذه عشائر اللاويين بحسب مواليدهم '),
(11246, 'Exodus', 2, 6, 20, ' وأخذ عمرام يوكابد عمته زوجة له . فولدت له هارون وموسى . وكانت سنو حياة عمرام مئة وسبعا وثلاثين سنة '),
(11247, 'Exodus', 2, 6, 21, ' وبنو يصهار : قورح ونافج وذكري '),
(11248, 'Exodus', 2, 6, 22, ' وبنو عزيئيل : ميشائيل وألصافان وستري '),
(11249, 'Exodus', 2, 6, 23, ' وأخذ هارون أليشابع بنت عميناداب أخت نحشون زوجة له ، فولدت له ناداب وأبيهو وألعازار وإيثامار '),
(11250, 'Exodus', 2, 6, 24, ' وبنو قورح : أسير وألقانة وأبيأساف . هذه عشائر القورحيين '),
(11251, 'Exodus', 2, 6, 25, ' وألعازار بن هارون أخذ لنفسه من بنات فوطيئيل زوجة ، فولدت له فينحاس . هؤلاء هم رؤساء آباء اللاويين بحسب عشائرهم '),
(11252, 'Exodus', 2, 6, 26, ' هذان هما هارون وموسى اللذان قال الرب لهما : أخرجا بني إسرائيل من أرض مصر بحسب أجنادهم '),
(11253, 'Exodus', 2, 6, 27, ' هما اللذان كلما فرعون ملك مصر في إخراج بني إسرائيل من مصر . هذان هما موسى وهارون '),
(11254, 'Exodus', 2, 1, 1, ' وهذه أسماء بني إسرائيل الذين جاءوا إلى مصر . مع يعقوب جاء كل إنسان وبيته '),
(11255, 'Exodus', 2, 1, 2, ' رأوبين وشمعون ولاوي ويهوذا '),
(11256, 'Exodus', 2, 1, 3, ' ويساكر وزبولون وبنيامين '),
(11257, 'Exodus', 2, 6, 28, ' وكان يوم كلم الرب موسى في أرض مصر '),
(11258, 'Exodus', 2, 6, 29, ' أن الرب كلمه قائلا : أنا الرب . كلم فرعون ملك مصر بكل ما أنا أكلمك به '),
(11259, 'Exodus', 2, 6, 30, ' فقال موسى أمام الرب : ها أنا أغلف الشفتين . فكيف يسمع لي فرعون '),
(11260, 'Exodus', 2, 7, 1, ' فقال الرب لموسى : انظر أنا جعلتك إلها لفرعون . وهارون أخوك يكون نبيك '),
(11261, 'Exodus', 2, 7, 2, ' أنت تتكلم بكل ما آمرك ، وهارون أخوك يكلم فرعون ليطلق بني إسرائيل من أرضه '),
(11262, 'Exodus', 2, 7, 3, ' ولكني أقسي قلب فرعون وأكثر آياتي وعجائبي في أرض مصر '),
(11263, 'Exodus', 2, 7, 4, ' ولا يسمع لكما فرعون حتى أجعل يدي على مصر ، فأخرج أجنادي ، شعبي بني إسرائيل من أرض مصر بأحكام عظيمة '),
(11264, 'Exodus', 2, 7, 5, ' فيعرف المصريون أني أنا الرب حينما أمد يدي على مصر وأخرج بني إسرائيل من بينهم '),
(11265, 'Exodus', 2, 7, 6, ' ففعل موسى وهارون كما أمرهما الرب . هكذا فعلا '),
(11266, 'Exodus', 2, 7, 7, ' وكان موسى ابن ثمانين سنة ، وهارون ابن ثلاث وثمانين سنة حين كلما فرعون '),
(11267, 'Exodus', 2, 7, 8, ' وكلم الرب موسى وهارون قائلا '),
(11268, 'Exodus', 2, 7, 9, ' إذا كلمكما فرعون قائلا : هاتيا عجيبة ، تقول لهارون : خذ عصاك واطرحها أمام فرعون فتصير ثعبانا '),
(11269, 'Exodus', 2, 7, 10, ' فدخل موسى وهارون إلى فرعون وفعلا هكذا كما أمر الرب . طرح هارون عصاه أمام فرعون وأمام عبيده فصارت ثعبانا '),
(11270, 'Exodus', 2, 7, 11, ' فدعا فرعون أيضا الحكماء والسحرة ، ففعل عرافو مصر أيضا بسحرهم كذلك '),
(11271, 'Exodus', 2, 7, 12, ' طرحوا كل واحد عصاه فصارت العصي ثعابين . ولكن عصا هارون ابتلعت عصيهم '),
(11272, 'Exodus', 2, 7, 13, ' فاشتد قلب فرعون فلم يسمع لهما ، كما تكلم الرب '),
(11273, 'Exodus', 2, 7, 14, ' ثم قال الرب لموسى : قلب فرعون غليظ . قد أبى أن يطلق الشعب '),
(11274, 'Exodus', 2, 7, 15, ' اذهب إلى فرعون في الصباح . إنه يخرج إلى الماء ، وقف للقائه على حافة النهر . والعصا التي تحولت حية تأخذها في يدك '),
(11275, 'Exodus', 2, 7, 16, ' وتقول له : الرب إله العبرانيين أرسلني إليك قائلا : أطلق شعبي ليعبدوني في البرية . وهوذا حتى الآن لم تسمع '),
(11276, 'Exodus', 2, 7, 17, ' هكذا يقول الرب : بهذا تعرف أني أنا الرب : ها أنا أضرب بالعصا التي في يدي على الماء الذي في النهر فيتحول دما '),
(11277, 'Exodus', 2, 7, 18, ' ويموت السمك الذي في النهر وينتن النهر . فيعاف المصريون أن يشربوا ماء من النهر '),
(11278, 'Exodus', 2, 7, 19, ' ثم قال الرب لموسى : قل لهارون : خذ عصاك ومد يدك على مياه المصريين ، على أنهارهم وعلى سواقيهم ، وعلى آجامهم ، وعلى كل مجتمعات مياههم لتصير دما . فيكون دم في كل أرض مصر في الأخشاب وفي الأحجار '),
(11279, 'Exodus', 2, 7, 20, ' ففعل هكذا موسى وهارون كما أمر الرب . رفع العصا وضرب الماء الذي في النهر أمام عيني فرعون وأمام عيون عبيده ، فتحول كل الماء الذي في النهر دما '),
(11280, 'Exodus', 2, 7, 21, ' ومات السمك الذي في النهر وأنتن النهر ، فلم يقدر المصريون أن يشربوا ماء من النهر . وكان الدم في كل أرض مصر '),
(11281, 'Exodus', 2, 7, 22, ' وفعل عرافو مصر كذلك بسحرهم . فاشتد قلب فرعون فلم يسمع لهما ، كما تكلم الرب '),
(11282, 'Exodus', 2, 7, 23, ' ثم انصرف فرعون ودخل بيته ولم يوجه قلبه إلى هذا أيضا '),
(11283, 'Exodus', 2, 7, 24, ' وحفر جميع المصريين حوالي النهر لأجل ماء ليشربوا ، لأنهم لم يقدروا أن يشربوا من ماء النهر '),
(11284, 'Exodus', 2, 7, 25, ' ولما كملت سبعة أيام بعد ما ضرب الرب النهر '),
(11285, 'Exodus', 2, 8, 1, ' قال الرب لموسى : ادخل إلى فرعون وقل له : هكذا يقول الرب : أطلق شعبي ليعبدوني '),
(11286, 'Exodus', 2, 8, 2, ' وإن كنت تأبى أن تطلقهم فها أنا أضرب جميع تخومك بالضفادع '),
(11287, 'Exodus', 2, 8, 3, ' فيفيض النهر ضفادع . فتصعد وتدخل إلى بيتك وإلى مخدع فراشك وعلى سريرك وإلى بيوت عبيدك وعلى شعبك وإلى تنانيرك وإلى معاجنك '),
(11288, 'Exodus', 2, 8, 4, ' عليك وعلى شعبك وعبيدك تصعد الضفادع '),
(11289, 'Exodus', 2, 8, 5, ' فقال الرب لموسى : قل لهارون : مد يدك بعصاك على الأنهار والسواقي والآجام ، وأصعد الضفادع على أرض مصر '),
(11290, 'Exodus', 2, 8, 6, ' فمد هارون يده على مياه مصر ، فصعدت الضفادع وغطت أرض مصر '),
(11291, 'Exodus', 2, 8, 7, ' وفعل كذلك العرافون بسحرهم وأصعدوا الضفادع على أرض مصر '),
(11292, 'Exodus', 2, 8, 8, ' فدعا فرعون موسى وهارون وقال : صليا إلى الرب ليرفع الضفادع عني وعن شعبي فأطلق الشعب ليذبحوا للرب '),
(11293, 'Exodus', 2, 8, 9, ' فقال موسى لفرعون : عين لي متى أصلي لأجلك ولأجل عبيدك وشعبك لقطع الضفادع عنك وعن بيوتك . ولكنها تبقى في النهر '),
(11294, 'Exodus', 2, 8, 10, ' فقال : غدا . فقال : كقولك . لكي تعرف أن ليس مثل الرب إلهنا '),
(11295, 'Exodus', 2, 8, 11, ' فترتفع الضفادع عنك وعن بيوتك وعبيدك وشعبك ، ولكنها تبقى في النهر '),
(11296, 'Exodus', 2, 8, 12, ' ثم خرج موسى وهارون من لدن فرعون ، وصرخ موسى إلى الرب من أجل الضفادع التي جعلها على فرعون '),
(11297, 'Exodus', 2, 8, 13, ' ففعل الرب كقول موسى . فماتت الضفادع من البيوت والدور والحقول '),
(11298, 'Exodus', 2, 8, 14, ' وجمعوها كوما كثيرة حتى أنتنت الأرض '),
(11299, 'Exodus', 2, 8, 15, ' فلما رأى فرعون أنه قد حصل الفرج أغلظ قلبه ولم يسمع لهما ، كما تكلم الرب '),
(11300, 'Exodus', 2, 8, 16, ' ثم قال الرب لموسى : قل لهارون : مد عصاك واضرب تراب الأرض ليصير بعوضا في جميع أرض مصر '),
(11301, 'Exodus', 2, 8, 17, ' ففعلا كذلك . مد هارون يده بعصاه وضرب تراب الأرض ، فصار البعوض على الناس وعلى البهائم . كل تراب الأرض صار بعوضا في جميع أرض مصر '),
(11302, 'Exodus', 2, 8, 18, ' وفعل كذلك العرافون بسحرهم ليخرجوا البعوض فلم يستطيعوا . وكان البعوض على الناس وعلى البهائم '),
(11303, 'Exodus', 2, 8, 19, ' فقال العرافون لفرعون : هذا إصبع الله . ولكن اشتد قلب فرعون فلم يسمع لهما ، كما تكلم الرب '),
(11304, 'Exodus', 2, 8, 20, ' ثم قال الرب لموسى : بكر في الصباح وقف أمام فرعون . إنه يخرج إلى الماء . وقل له : هكذا يقول الرب : أطلق شعبي ليعبدوني '),
(11305, 'Exodus', 2, 8, 21, ' فإنه إن كنت لا تطلق شعبي ، ها أنا أرسل عليك وعلى عبيدك وعلى شعبك وعلى بيوتك الذبان ، فتمتلئ بيوت المصريين ذبانا . وأيضا الأرض التي هم عليها '),
(11306, 'Exodus', 2, 8, 22, ' ولكن أميز في ذلك اليوم أرض جاسان حيث شعبي مقيم حتى لا يكون هناك ذبان . لكي تعلم أني أنا الرب في الأرض '),
(11307, 'Exodus', 2, 8, 23, ' وأجعل فرقا بين شعبي وشعبك . غدا تكون هذه الآية '),
(11308, 'Exodus', 2, 8, 24, ' ففعل الرب هكذا ، فدخلت ذبان كثيرة إلى بيت فرعون وبيوت عبيده . وفي كل أرض مصر خربت الأرض من الذبان '),
(11309, 'Exodus', 2, 8, 25, ' فدعا فرعون موسى وهارون وقال : اذهبوا اذبحوا لإلهكم في هذه الأرض '),
(11310, 'Exodus', 2, 8, 26, ' فقال موسى : لا يصلح أن نفعل هكذا ، لأننا إنما نذبح رجس المصريين للرب إلهنا . إن ذبحنا رجس المصريين أمام عيونهم أفلا يرجموننا '),
(11311, 'Exodus', 2, 8, 27, ' نذهب سفر ثلاثة أيام في البرية ونذبح للرب إلهنا كما يقول لنا '),
(11312, 'Exodus', 2, 8, 28, ' فقال فرعون : أنا أطلقكم لتذبحوا للرب إلهكم في البرية ، ولكن لا تذهبوا بعيدا . صليا لأجلي '),
(11313, 'Exodus', 2, 8, 29, ' فقال موسى : ها أنا أخرج من لدنك وأصلي إلى الرب ، فترتفع الذبان عن فرعون وعبيده وشعبه غدا . ولكن لا يعد فرعون يخاتل حتى لا يطلق الشعب ليذبح للرب '),
(11314, 'Exodus', 2, 8, 30, ' فخرج موسى من لدن فرعون وصلى إلى الرب '),
(11315, 'Exodus', 2, 8, 31, ' ففعل الرب كقول موسى ، فارتفع الذبان عن فرعون وعبيده وشعبه . لم تبق واحدة '),
(11316, 'Exodus', 2, 8, 32, ' ولكن أغلظ فرعون قلبه هذه المرة أيضا فلم يطلق الشعب '),
(11317, 'Exodus', 2, 9, 1, ' ثم قال الرب لموسى : ادخل إلى فرعون وقل له : هكذا يقول الرب إله العبرانيين : أطلق شعبي ليعبدوني '),
(11318, 'Exodus', 2, 9, 2, ' فإنه إن كنت تأبى أن تطلقهم وكنت تمسكهم بعد '),
(11319, 'Exodus', 2, 9, 3, ' فها يد الرب تكون على مواشيك التي في الحقل ، على الخيل والحمير والجمال والبقر والغنم ، وبأ ثقيلا جدا '),
(11320, 'Exodus', 2, 9, 4, ' ويميز الرب بين مواشي إسرائيل ومواشي المصريين . فلا يموت من كل ما لبني إسرائيل شيء '),
(11321, 'Exodus', 2, 9, 5, ' وعين الرب وقتا قائلا : غدا يفعل الرب هذا الأمر في الأرض '),
(11322, 'Exodus', 2, 9, 6, ' ففعل الرب هذا الأمر في الغد . فماتت جميع مواشي المصريين . وأما مواشي بني إسرائيل فلم يمت منها واحد '),
(11323, 'Exodus', 2, 9, 7, ' وأرسل فرعون وإذا مواشي إسرائيل لم يمت منها ولا واحد . ولكن غلظ قلب فرعون فلم يطلق الشعب '),
(11324, 'Exodus', 2, 9, 8, ' ثم قال الرب لموسى وهارون : خذا ملء أيديكما من رماد الأتون ، وليذره موسى نحو السماء أمام عيني فرعون '),
(11325, 'Exodus', 2, 9, 9, ' ليصير غبارا على كل أرض مصر . فيصير على الناس وعلى البهائم دمامل طالعة ببثور في كل أرض مصر '),
(11326, 'Exodus', 2, 9, 10, ' فأخذا رماد الأتون ووقفا أمام فرعون ، وذراه موسى نحو السماء ، فصار دمامل بثور طالعة في الناس وفي البهائم '),
(11327, 'Exodus', 2, 9, 11, ' ولم يستطع العرافون أن يقفوا أمام موسى من أجل الدمامل ، لأن الدمامل كانت في العرافين وفي كل المصريين '),
(11328, 'Exodus', 2, 9, 12, ' ولكن شدد الرب قلب فرعون فلم يسمع لهما ، كما كلم الرب موسى '),
(11329, 'Exodus', 2, 9, 13, ' ثم قال الرب لموسى : بكر في الصباح وقف أمام فرعون وقل له : هكذا يقول الرب إله العبرانيين : أطلق شعبي ليعبدوني '),
(11330, 'Exodus', 2, 9, 14, ' لأني هذه المرة أرسل جميع ضرباتي إلى قلبك وعلى عبيدك وشعبك ، لكي تعرف أن ليس مثلي في كل الأرض '),
(11331, 'Exodus', 2, 9, 15, ' فإنه الآن لو كنت أمد يدي وأضربك وشعبك بالوبإ ، لكنت تباد من الأرض '),
(11332, 'Exodus', 2, 9, 16, ' ولكن لأجل هذا أقمتك ، لكي أريك قوتي ، ولكي يخبر باسمي في كل الأرض '),
(11333, 'Exodus', 2, 9, 17, ' أنت معاند بعد لشعبي حتى لاتطلقه '),
(11334, 'Exodus', 2, 9, 18, ' ها أنا غدا مثل الآن أمطر بردا عظيما جدا لم يكن مثله في مصر منذ يوم تأسيسها إلى الآن '),
(11335, 'Exodus', 2, 9, 19, ' فالآن أرسل احم مواشيك وكل ما لك في الحقل . جميع الناس والبهائم الذين يوجدون في الحقل ولا يجمعون إلى البيوت ، ينزل عليهم البرد فيموتون '),
(11336, 'Exodus', 2, 9, 20, ' فالذي خاف كلمة الرب من عبيد فرعون هرب بعبيده ومواشيه إلى البيوت '),
(11337, 'Exodus', 2, 9, 21, ' وأما الذي لم يوجه قلبه إلى كلمة الرب فترك عبيده ومواشيه في الحقل '),
(11338, 'Exodus', 2, 9, 22, ' ثم قال الرب لموسى : مد يدك نحو السماء ليكون برد في كل أرض مصر : على الناس وعلى البهائم وعلى كل عشب الحقل في أرض مصر '),
(11339, 'Exodus', 2, 9, 23, ' فمد موسى عصاه نحو السماء ، فأعطى الرب رعودا وبردا ، وجرت نار على الأرض ، وأمطر الرب بردا على أرض مصر '),
(11340, 'Exodus', 2, 9, 24, ' فكان برد ، ونار متواصلة في وسط البرد . شيء عظيم جدا لم يكن مثله في كل أرض مصر منذ صارت أمة '),
(11341, 'Exodus', 2, 9, 25, ' فضرب البرد في كل أرض مصر جميع ما في الحقل من الناس والبهائم . وضرب البرد جميع عشب الحقل وكسر جميع شجر الحقل '),
(11342, 'Exodus', 2, 9, 26, ' إلا أرض جاسان حيث كان بنو إسرائيل ، فلم يكن فيها برد '),
(11343, 'Exodus', 2, 9, 27, ' فأرسل فرعون ودعا موسى وهارون وقال لهما : أخطأت هذه المرة . الرب هو البار وأنا وشعبي الأشرار '),
(11344, 'Exodus', 2, 9, 28, ' صليا إلى الرب ، وكفى حدوث رعود الله والبرد ، فأطلقكم ولا تعودوا تلبثون '),
(11345, 'Exodus', 2, 9, 29, ' فقال له موسى : عند خروجي من المدينة أبسط يدي إلى الرب ، فتنقطع الرعود ولا يكون البرد أيضا ، لكي تعرف أن للرب الأرض '),
(11346, 'Exodus', 2, 9, 30, ' وأما أنت وعبيدك فأنا أعلم أنكم لم تخشوا بعد من الرب الإله '),
(11347, 'Exodus', 2, 9, 31, ' فالكتان والشعير ضربا . لأن الشعير كان مسبلا والكتان مبزرا '),
(11348, 'Exodus', 2, 9, 32, ' وأما الحنطة والقطاني فلم تضرب لأنها كانت متأخرة '),
(11349, 'Exodus', 2, 9, 33, ' فخرج موسى من المدينة من لدن فرعون وبسط يديه إلى الرب ، فانقطعت الرعود والبرد ولم ينصب المطر على الأرض '),
(11350, 'Exodus', 2, 9, 34, ' ولكن فرعون لما رأى أن المطر والبرد والرعود انقطعت ، عاد يخطئ وأغلظ قلبه هو وعبيده '),
(11351, 'Exodus', 2, 9, 35, ' فاشتد قلب فرعون فلم يطلق بني إسرائيل ، كما تكلم الرب عن يد موسى '),
(11352, 'Exodus', 2, 10, 1, ' ثم قال الرب لموسى : ادخل إلى فرعون ، فإني أغلظت قلبه وقلوب عبيده لكي أصنع آياتي هذه بينهم '),
(11353, 'Exodus', 2, 10, 2, ' ولكي تخبر في مسامع ابنك وابن ابنك بما فعلته في مصر ، وبآياتي التي صنعتها بينهم ، فتعلمون أني أنا الرب '),
(11354, 'Exodus', 2, 10, 3, ' فدخل موسى وهارون إلى فرعون وقالا له : هكذا يقول الرب إله العبرانيين : إلى متى تأبى أن تخضع لي ؟ أطلق شعبي ليعبدوني '),
(11355, 'Exodus', 2, 10, 4, ' فإنه إن كنت تأبى أن تطلق شعبي ها أنا أجيء غدا بجراد على تخومك '),
(11356, 'Exodus', 2, 10, 5, ' فيغطي وجه الأرض حتى لا يستطاع نظر الأرض . ويأكل الفضلة السالمة الباقية لكم من البرد . ويأكل جميع الشجر النابت لكم من الحقل '),
(11357, 'Exodus', 2, 10, 6, ' ويملأ بيوتك وبيوت جميع عبيدك وبيوت جميع المصريين ، الأمر الذي لم يره آباؤك ولا آباء آبائك منذ يوم وجدوا على الأرض إلى هذا اليوم . ثم تحول وخرج من لدن فرعون '),
(11358, 'Exodus', 2, 10, 7, ' فقال عبيد فرعون له : إلى متى يكون هذا لنا فخا ؟ أطلق الرجال ليعبدوا الرب إلههم . ألم تعلم بعد أن مصر قد خربت '),
(11359, 'Exodus', 2, 10, 8, ' فرد موسى وهارون إلى فرعون ، فقال لهما : اذهبوا اعبدوا الرب إلهكم . ولكن من ومن هم الذين يذهبون '),
(11360, 'Exodus', 2, 10, 9, ' فقال موسى : نذهب بفتياننا وشيوخنا . نذهب ببنينا وبناتنا ، بغنمنا وبقرنا ، لأن لنا عيدا للرب '),
(11361, 'Exodus', 2, 10, 10, ' فقال لهما : يكون الرب معكم هكذا كما أطلقكم وأولادكم . انظروا ، إن قدام وجوهكم شرا '),
(11362, 'Exodus', 2, 10, 11, ' ليس هكذا . اذهبوا أنتم الرجال واعبدوا الرب . لأنكم لهذا طالبون . فطردا من لدن فرعون '),
(11363, 'Exodus', 2, 10, 12, ' ثم قال الرب لموسى : مد يدك على أرض مصر لأجل الجراد ، ليصعد على أرض مصر ويأكل كل عشب الأرض ، كل ما تركه البرد '),
(11364, 'Exodus', 2, 10, 13, ' فمد موسى عصاه على أرض مصر ، فجلب الرب على الأرض ريحا شرقية كل ذلك النهار وكل الليل . ولما كان الصباح ، حملت الريح الشرقية الجراد '),
(11365, 'Exodus', 2, 10, 14, ' فصعد الجراد على كل أرض مصر ، وحل في جميع تخوم مصر . شيء ثقيل جدا لم يكن قبله جراد هكذا مثله ، ولا يكون بعده كذلك '),
(11366, 'Exodus', 2, 10, 15, ' وغطى وجه كل الأرض حتى أظلمت الأرض . وأكل جميع عشب الأرض وجميع ثمر الشجر الذي تركه البرد ، حتى لم يبق شيء أخضر في الشجر ولا في عشب الحقل في كل أرض مصر '),
(11367, 'Exodus', 2, 10, 16, ' فدعا فرعون موسى وهارون مسرعا وقال : أخطأت إلى الرب إلهكما وإليكما '),
(11368, 'Exodus', 2, 10, 17, ' والآن اصفحا عن خطيتي هذه المرة فقط ، وصليا إلى الرب إلهكما ليرفع عني هذا الموت فقط '),
(11369, 'Exodus', 2, 10, 18, ' فخرج موسى من لدن فرعون وصلى إلى الرب '),
(11370, 'Exodus', 2, 10, 19, ' فرد الرب ريحا غربية شديدة جدا ، فحملت الجراد وطرحته إلى بحر سوف . لم تبق جرادة واحدة في كل تخوم مصر '),
(11371, 'Exodus', 2, 10, 20, ' ولكن شدد الرب قلب فرعون فلم يطلق بني إسرائيل '),
(11372, 'Exodus', 2, 10, 21, ' ثم قال الرب لموسى : مد يدك نحو السماء ليكون ظلام على أرض مصر ، حتى يلمس الظلام '),
(11373, 'Exodus', 2, 10, 22, ' فمد موسى يده نحو السماء فكان ظلام دامس في كل أرض مصر ثلاثة أيام '),
(11374, 'Exodus', 2, 10, 23, ' لم يبصر أحد أخاه ، ولا قام أحد من مكانه ثلاثة أيام . ولكن جميع بني إسرائيل كان لهم نور في مساكنهم '),
(11375, 'Exodus', 2, 10, 24, ' فدعا فرعون موسى وقال : اذهبوا اعبدوا الرب . غير أن غنمكم وبقركم تبقى . أولادكم أيضا تذهب معكم '),
(11376, 'Exodus', 2, 10, 25, ' فقال موسى : أنت تعطي أيضا في أيدينا ذبائح ومحرقات لنصنعها للرب إلهنا '),
(11377, 'Exodus', 2, 10, 26, ' فتذهب مواشينا أيضا معنا . لايبقى ظلف . لأننا منها نأخذ لعبادة الرب إلهنا . ونحن لا نعرف بماذا نعبد الرب حتى نأتي إلى هناك '),
(11378, 'Exodus', 2, 10, 27, ' ولكن شدد الرب قلب فرعون فلم يشأ أن يطلقهم '),
(11379, 'Exodus', 2, 10, 28, ' وقال له فرعون : اذهب عني . احترز . لا تر وجهي أيضا . إنك يوم ترى وجهي تموت '),
(11380, 'Exodus', 2, 10, 29, ' فقال موسى : نعما قلت . أنا لا أعود أرى وجهك أيضا '),
(11381, 'Exodus', 2, 11, 1, ' ثم قال الرب لموسى : ضربة واحدة أيضا أجلب على فرعون وعلى مصر . بعد ذلك يطلقكم من هنا . وعندما يطلقكم يطردكم طردا من هنا بالتمام '),
(11382, 'Exodus', 2, 11, 2, ' تكلم في مسامع الشعب أن يطلب كل رجل من صاحبه ، وكل امرأة من صاحبتها أمتعة فضة وأمتعة ذهب '),
(11383, 'Exodus', 2, 11, 3, ' وأعطى الرب نعمة للشعب في عيون المصريين . وأيضا الرجل موسى كان عظيما جدا في أرض مصر في عيون عبيد فرعون وعيون الشعب '),
(11384, 'Exodus', 2, 11, 4, ' وقال موسى : هكذا يقول الرب : إني نحو نصف الليل أخرج في وسط مصر '),
(11385, 'Exodus', 2, 11, 5, ' فيموت كل بكر في أرض مصر ، من بكر فرعون الجالس على كرسيه إلى بكر الجارية التي خلف الرحى ، وكل بكر بهيمة '),
(11386, 'Exodus', 2, 11, 6, ' ويكون صراخ عظيم في كل أرض مصر لم يكن مثله ولا يكون مثله أيضا '),
(11387, 'Exodus', 2, 11, 7, ' ولكن جميع بني إسرائيل لا يسنن كلب لسانه إليهم ، لا إلى الناس ولا إلى البهائم . لكي تعلموا أن الرب يميز بين المصريين وإسرائيل '),
(11388, 'Exodus', 2, 11, 8, ' فينزل إلي جميع عبيدك هؤلاء ، ويسجدون لي قائلين : اخرج أنت وجميع الشعب الذين في أثرك . وبعد ذلك أخرج . ثم خرج من لدن فرعون في حمو الغضب '),
(11389, 'Exodus', 2, 11, 9, ' وقال الرب لموسى : لا يسمع لكما فرعون لكي تكثر عجائبي في أرض مصر '),
(11390, 'Exodus', 2, 11, 10, ' وكان موسى وهارون يفعلان كل هذه العجائب أمام فرعون ، ولكن شدد الرب قلب فرعون ، فلم يطلق بني إسرائيل من أرضه '),
(11391, 'Exodus', 2, 12, 1, ' وكلم الرب موسى وهارون في أرض مصر قائلا '),
(11392, 'Exodus', 2, 12, 2, ' هذا الشهر يكون لكم رأس الشهور . هو لكم أول شهور السنة '),
(11393, 'Exodus', 2, 12, 3, ' كلما كل جماعة إسرائيل قائلين : في العاشر من هذا الشهر يأخذون لهم كل واحد شاة بحسب بيوت الآباء ، شاة للبيت '),
(11394, 'Exodus', 2, 12, 4, ' وإن كان البيت صغيرا عن أن يكون كفوا لشاة ، يأخذ هو وجاره القريب من بيته بحسب عدد النفوس . كل واحد على حسب أكله تحسبون للشاة '),
(11395, 'Exodus', 2, 12, 5, ' تكون لكم شاة صحيحة ذكرا ابن سنة ، تأخذونه من الخرفان أو من المواعز '),
(11396, 'Exodus', 2, 12, 6, ' ويكون عندكم تحت الحفظ إلى اليوم الرابع عشر من هذا الشهر . ثم يذبحه كل جمهور جماعة إسرائيل في العشية '),
(11397, 'Exodus', 2, 12, 7, ' ويأخذون من الدم ويجعلونه على القائمتين والعتبة العليا في البيوت التي يأكلونه فيها '),
(11398, 'Exodus', 2, 12, 8, ' ويأكلون اللحم تلك الليلة مشويا بالنار مع فطير . على أعشاب مرة يأكلونه '),
(11399, 'Exodus', 2, 12, 9, ' لا تأكلوا منه نيئا أو طبيخا مطبوخا بالماء ، بل مشويا بالنار . رأسه مع أكارعه وجوفه '),
(11400, 'Exodus', 2, 12, 10, ' ولا تبقوا منه إلى الصباح . والباقي منه إلى الصباح ، تحرقونه بالنار '),
(11401, 'Exodus', 2, 12, 11, ' وهكذا تأكلونه : أحقاؤكم مشدودة ، وأحذيتكم في أرجلكم ، وعصيكم في أيديكم . وتأكلونه بعجلة . هو فصح للرب '),
(11402, 'Exodus', 2, 12, 12, ' فإني أجتاز في أرض مصر هذه الليلة ، وأضرب كل بكر في أرض مصر من الناس والبهائم . وأصنع أحكاما بكل آلهة المصريين . أنا الرب '),
(11403, 'Exodus', 2, 12, 13, ' ويكون لكم الدم علامة على البيوت التي أنتم فيها ، فأرى الدم وأعبر عنكم ، فلا يكون عليكم ضربة للهلاك حين أضرب أرض مصر '),
(11404, 'Exodus', 2, 12, 14, ' ويكون لكم هذا اليوم تذكارا فتعيدونه عيدا للرب . في أجيالكم تعيدونه فريضة أبدية '),
(11405, 'Exodus', 2, 12, 15, ' سبعة أيام تأكلون فطيرا . اليوم الأول تعزلون الخمير من بيوتكم ، فإن كل من أكل خميرا من اليوم الأول إلى اليوم السابع تقطع تلك النفس من إسرائيل '),
(11406, 'Exodus', 2, 12, 16, ' ويكون لكم في اليوم الأول محفل مقدس ، وفي اليوم السابع محفل مقدس . لا يعمل فيهما عمل ما إلا ما تأكله كل نفس ، فذلك وحده يعمل منكم '),
(11407, 'Exodus', 2, 12, 17, ' وتحفظون الفطير لأني في هذا اليوم عينه أخرجت أجنادكم من أرض مصر ، فتحفظون هذا اليوم في أجيالكم فريضة أبدية '),
(11408, 'Exodus', 2, 12, 18, ' في الشهر الأول ، في اليوم الرابع عشر من الشهر ، مساء ، تأكلون فطيرا إلى اليوم الحادي والعشرين من الشهر مساء '),
(11409, 'Exodus', 2, 12, 19, ' سبعة أيام لا يوجد خمير في بيوتكم . فإن كل من أكل مختمرا تقطع تلك النفس من جماعة إسرائيل ، الغريب مع مولود الأرض '),
(11410, 'Exodus', 2, 12, 20, ' لا تأكلوا شيئا مختمرا . في جميع مساكنكم تأكلون فطيرا '),
(11411, 'Exodus', 2, 12, 21, ' فدعا موسى جميع شيوخ إسرائيل وقال لهم : اسحبوا وخذوا لكم غنما بحسب عشائركم واذبحوا الفصح '),
(11412, 'Exodus', 2, 12, 22, ' وخذوا باقة زوفا واغمسوها في الدم الذي في الطست ومسوا العتبة العليا والقائمتين بالدم الذي في الطست . وأنتم لا يخرج أحد منكم من باب بيته حتى الصباح '),
(11413, 'Exodus', 2, 12, 23, ' فإن الرب يجتاز ليضرب المصريين . فحين يرى الدم على العتبة العليا والقائمتين يعبر الرب عن الباب ولا يدع المهلك يدخل بيوتكم ليضرب '),
(11414, 'Exodus', 2, 12, 24, ' فتحفظون هذا الأمر فريضة لك ولأولادك إلى الأبد '),
(11415, 'Exodus', 2, 12, 25, ' ويكون حين تدخلون الأرض التي يعطيكم الرب كما تكلم ، أنكم تحفظون هذه الخدمة '),
(11416, 'Exodus', 2, 12, 26, ' ويكون حين يقول لكم أولادكم : ما هذه الخدمة لكم '),
(11417, 'Exodus', 2, 12, 27, ' أنكم تقولون : هي ذبيحة فصح للرب الذي عبر عن بيوت بني إسرائيل في مصر لما ضرب المصريين وخلص بيوتنا . فخر الشعب وسجدوا '),
(11418, 'Exodus', 2, 12, 28, ' ومضى بنو إسرائيل وفعلوا كما أمر الرب موسى وهارون . هكذا فعلوا '),
(11419, 'Exodus', 2, 12, 29, ' فحدث في نصف الليل أن الرب ضرب كل بكر في أرض مصر ، من بكر فرعون الجالس على كرسيه إلى بكر الأسير الذي في السجن ، وكل بكر بهيمة '),
(11420, 'Exodus', 2, 12, 30, ' فقام فرعون ليلا هو وكل عبيده وجميع المصريين . وكان صراخ عظيم في مصر ، لأنه لم يكن بيت ليس فيه ميت '),
(11421, 'Exodus', 2, 12, 31, ' فدعا موسى وهارون ليلا وقال : قوموا اخرجوا من بين شعبي أنتما وبنو إسرائيل جميعا ، واذهبوا اعبدوا الرب كما تكلمتم '),
(11422, 'Exodus', 2, 12, 32, ' خذوا غنمكم أيضا وبقركم كما تكلمتم واذهبوا . وباركوني أيضا '),
(11423, 'Exodus', 2, 12, 33, ' وألح المصريون على الشعب ليطلقوهم عاجلا من الأرض ، لأنهم قالوا : جميعنا أموات '),
(11424, 'Exodus', 2, 12, 34, ' فحمل الشعب عجينهم قبل أن يختمر ، ومعاجنهم مصرورة في ثيابهم على أكتافهم '),
(11425, 'Exodus', 2, 12, 35, ' وفعل بنو إسرائيل بحسب قول موسى . طلبوا من المصريين أمتعة فضة وأمتعة ذهب وثيابا '),
(11426, 'Exodus', 2, 12, 36, ' وأعطى الرب نعمة للشعب في عيون المصريين حتى أعاروهم . فسلبوا المصريين '),
(11427, 'Exodus', 2, 12, 37, ' فارتحل بنو إسرائيل من رعمسيس إلى سكوت ، نحو ست مئة ألف ماش من الرجال عدا الأولاد '),
(11428, 'Exodus', 2, 12, 38, ' وصعد معهم لفيف كثير أيضا مع غنم وبقر ، مواش وافرة جدا '),
(11429, 'Exodus', 2, 12, 39, ' وخبزوا العجين الذي أخرجوه من مصر خبز ملة فطيرا ، إذ كان لم يختمر . لأنهم طردوا من مصر ولم يقدروا أن يتأخروا ، فلم يصنعوا لأنفسهم زادا '),
(11430, 'Exodus', 2, 12, 40, ' وأما إقامة بني إسرائيل التي أقاموها في مصر فكانت أربع مئة وثلاثين سنة '),
(11431, 'Exodus', 2, 12, 41, ' وكان عند نهاية أربع مئة وثلاثين سنة ، في ذلك اليوم عينه ، أن جميع أجناد الرب خرجت من أرض مصر '),
(11432, 'Exodus', 2, 12, 42, ' هي ليلة تحفظ للرب لإخراجه إياهم من أرض مصر . هذه الليلة هي للرب . تحفظ من جميع بني إسرائيل في أجيالهم '),
(11433, 'Exodus', 2, 12, 43, ' وقال الرب لموسى وهارون : هذه فريضة الفصح : كل ابن غريب لا يأكل منه '),
(11434, 'Exodus', 2, 12, 44, ' ولكن كل عبد رجل مبتاع بفضة تختنه ثم يأكل منه '),
(11435, 'Exodus', 2, 12, 45, ' النزيل والأجير لا يأكلان منه '),
(11436, 'Exodus', 2, 12, 46, ' في بيت واحد يؤكل . لا تخرج من اللحم من البيت إلى خارج ، وعظما لا تكسروا منه '),
(11437, 'Exodus', 2, 12, 47, ' كل جماعة إسرائيل يصنعونه '),
(11438, 'Exodus', 2, 12, 48, ' وإذا نزل عندك نزيل وصنع فصحا للرب ، فليختن منه كل ذكر ، ثم يتقدم ليصنعه ، فيكون كمولود الأرض . وأما كل أغلف فلا يأكل منه '),
(11439, 'Exodus', 2, 12, 49, ' تكون شريعة واحدة لمولود الأرض وللنزيل النازل بينكم '),
(11440, 'Exodus', 2, 12, 50, ' ففعل جميع بني إسرائيل كما أمر الرب موسى وهارون . هكذا فعلوا '),
(11441, 'Exodus', 2, 12, 51, ' وكان في ذلك اليوم عينه أن الرب أخرج بني إسرائيل من أرض مصر بحسب أجنادهم '),
(11442, 'Exodus', 2, 13, 1, ' وكلم الرب موسى قائلا '),
(11443, 'Exodus', 2, 13, 2, ' قدس لي كل بكر ، كل فاتح رحم من بني إسرائيل ، من الناس ومن البهائم . إنه لي '),
(11444, 'Exodus', 2, 13, 3, ' وقال موسى للشعب : اذكروا هذا اليوم الذي فيه خرجتم من مصر من بيت العبودية ، فإنه بيد قوية أخرجكم الرب من هنا . ولا يؤكل خمير '),
(11445, 'Exodus', 2, 13, 4, ' اليوم أنتم خارجون في شهر أبيب '),
(11446, 'Exodus', 2, 13, 5, ' ويكون متى أدخلك الرب أرض الكنعانيين والحثيين والأموريين والحويين واليبوسيين التي حلف لآبائك أن يعطيك ، أرضا تفيض لبنا وعسلا ، أنك تصنع هذه الخدمة في هذا الشهر '),
(11447, 'Exodus', 2, 13, 6, ' سبعة أيام تأكل فطيرا ، وفي اليوم السابع عيد للرب '),
(11448, 'Exodus', 2, 13, 7, ' فطير يؤكل السبعة الأيام ، ولا يرى عندك مختمر ، ولا يرى عندك خمير في جميع تخومك '),
(11449, 'Exodus', 2, 13, 8, ' وتخبر ابنك في ذلك اليوم قائلا : من أجل ما صنع إلي الرب حين أخرجني من مصر '),
(11450, 'Exodus', 2, 13, 9, ' ويكون لك علامة على يدك ، وتذكارا بين عينيك ، لكي تكون شريعة الرب في فمك . لأنه بيد قوية أخرجك الرب من مصر '),
(11451, 'Exodus', 2, 13, 10, ' فتحفظ هذه الفريضة في وقتها من سنة إلى سنة '),
(11452, 'Exodus', 2, 13, 11, ' ويكون متى أدخلك الرب أرض الكنعانيين كما حلف لك ولآبائك ، وأعطاك إياها '),
(11453, 'Exodus', 2, 13, 12, ' أنك تقدم للرب كل فاتح رحم ، وكل بكر من نتاج البهائم التي تكون لك . الذكور للرب '),
(11454, 'Exodus', 2, 13, 13, ' ولكن كل بكر حمار تفديه بشاة . وإن لم تفده فتكسر عنقه . وكل بكر إنسان من أولادك تفديه '),
(11455, 'Exodus', 2, 13, 14, ' ويكون متى سألك ابنك غدا قائلا : ما هذا ؟ تقول له : بيد قوية أخرجنا الرب من مصر من بيت العبودية '),
(11456, 'Exodus', 2, 13, 15, ' وكان لما تقسى فرعون عن إطلاقنا أن الرب قتل كل بكر في أرض مصر ، من بكر الناس إلى بكر البهائم . لذلك أنا أذبح للرب الذكور من كل فاتح رحم ، وأفدي كل بكر من أولادي '),
(11457, 'Exodus', 2, 13, 16, ' فيكون علامة على يدك ، وعصابة بين عينيك . لأنه بيد قوية أخرجنا الرب من مصر '),
(11458, 'Exodus', 2, 13, 17, ' وكان لما أطلق فرعون الشعب أن الله لم يهدهم في طريق أرض الفلسطينيين مع أنها قريبة ، لأن الله قال : لئلا يندم الشعب إذا رأوا حربا ويرجعوا إلى مصر '),
(11459, 'Exodus', 2, 13, 18, ' فأدار الله الشعب في طريق برية بحر سوف . وصعد بنو إسرائيل متجهزين من أرض مصر '),
(11460, 'Exodus', 2, 13, 19, ' وأخذ موسى عظام يوسف معه ، لأنه كان قد استحلف بني إسرائيل بحلف قائلا : إن الله سيفتقدكم فتصعدون عظامي من هنا معكم '),
(11461, 'Exodus', 2, 13, 20, ' وارتحلوا من سكوت ونزلوا في إيثام في طرف البرية '),
(11462, 'Exodus', 2, 13, 21, ' وكان الرب يسير أمامهم نهارا في عمود سحاب ليهديهم في الطريق ، وليلا في عمود نار ليضيء لهم . لكي يمشوا نهارا وليلا '),
(11463, 'Exodus', 2, 13, 22, ' لم يبرح عمود السحاب نهارا وعمود النار ليلا من أمام الشعب '),
(11464, 'Exodus', 2, 14, 1, ' وكلم الرب موسى قائلا '),
(11465, 'Exodus', 2, 14, 2, ' كلم بني إسرائيل أن يرجعوا وينزلوا أمام فم الحيروث بين مجدل والبحر ، أمام بعل صفون . مقابله تنزلون عند البحر '),
(11466, 'Exodus', 2, 14, 3, ' فيقول فرعون عن بني إسرائيل : هم مرتبكون في الأرض . قد استغلق عليهم القفر '),
(11467, 'Exodus', 2, 14, 4, ' وأشدد قلب فرعون حتى يسعى وراءهم ، فأتمجد بفرعون وبجميع جيشه ، ويعرف المصريون أني أنا الرب . ففعلوا هكذا '),
(11468, 'Exodus', 2, 14, 5, ' فلما أخبر ملك مصر أن الشعب قد هرب ، تغير قلب فرعون وعبيده على الشعب . فقالوا : ماذا فعلنا حتى أطلقنا إسرائيل من خدمتنا '),
(11469, 'Exodus', 2, 14, 6, ' فشد مركبته وأخذ قومه معه '),
(11470, 'Exodus', 2, 14, 7, ' وأخذ ست مئة مركبة منتخبة وسائر مركبات مصر وجنودا مركبية على جميعها '),
(11471, 'Exodus', 2, 14, 8, ' وشدد الرب قلب فرعون ملك مصر حتى سعى وراء بني إسرائيل ، وبنو إسرائيل خارجون بيد رفيعة '),
(11472, 'Exodus', 2, 14, 9, ' فسعى المصريون وراءهم وأدركوهم . جميع خيل مركبات فرعون وفرسانه وجيشه ، وهم نازلون عند البحر عند فم الحيروث ، أمام بعل صفون '),
(11473, 'Exodus', 2, 14, 10, ' فلما اقترب فرعون رفع بنو إسرائيل عيونهم ، وإذا المصريون راحلون وراءهم . ففزعوا جدا ، وصرخ بنو إسرائيل إلى الرب '),
(11474, 'Exodus', 2, 14, 11, ' وقالوا لموسى : هل لأنه ليست قبور في مصر أخذتنا لنموت في البرية ؟ ماذا صنعت بنا حتى أخرجتنا من مصر '),
(11475, 'Exodus', 2, 24, 1, ' وقال لموسى : اصعد إلى الرب أنت وهارون وناداب وأبيهو ، وسبعون من شيوخ إسرائيل ، واسجدوا من بعيد '),
(11476, 'Exodus', 2, 24, 2, ' ويقترب موسى وحده إلى الرب ، وهم لا يقتربون . وأما الشعب فلا يصعد معه '),
(11477, 'Exodus', 2, 24, 3, ' فجاء موسى وحدث الشعب بجميع أقوال الرب وجميع الأحكام ، فأجاب جميع الشعب بصوت واحد وقالوا : كل الأقوال التي تكلم بها الرب نفعل '),
(11478, 'Exodus', 2, 24, 4, ' فكتب موسى جميع أقوال الرب . وبكر في الصباح وبنى مذبحا في أسفل الجبل ، واثني عشر عمودا لأسباط إسرائيل الاثني عشر '),
(11479, 'Exodus', 2, 24, 5, ' وأرسل فتيان بني إسرائيل ، فأصعدوا محرقات ، وذبحوا ذبائح سلامة للرب من الثيران '),
(11480, 'Exodus', 2, 24, 6, ' فأخذ موسى نصف الدم ووضعه في الطسوس . ونصف الدم رشه على المذبح '),
(11481, 'Exodus', 2, 24, 7, ' وأخذ كتاب العهد وقرأ في مسامع الشعب ، فقالوا : كل ما تكلم به الرب نفعل ونسمع له '),
(11482, 'Exodus', 2, 24, 8, ' وأخذ موسى الدم ورش على الشعب وقال : هوذا دم العهد الذي قطعه الرب معكم على جميع هذه الأقوال '),
(11483, 'Exodus', 2, 24, 9, ' ثم صعد موسى وهارون وناداب وأبيهو وسبعون من شيوخ إسرائيل '),
(11484, 'Exodus', 2, 24, 10, ' ورأوا إله إسرائيل ، وتحت رجليه شبه صنعة من العقيق الأزرق الشفاف ، وكذات السماء في النقاوة '),
(11485, 'Exodus', 2, 24, 11, ' ولكنه لم يمد يده إلى أشراف بني إسرائيل . فرأوا الله وأكلوا وشربوا '),
(11486, 'Exodus', 2, 24, 12, ' وقال الرب لموسى : اصعد إلي إلى الجبل ، وكن هناك ، فأعطيك لوحي الحجارة والشريعة والوصية التي كتبتها لتعليمهم '),
(11487, 'Exodus', 2, 24, 13, ' فقام موسى ويشوع خادمه . وصعد موسى إلى جبل الله '),
(11488, 'Exodus', 2, 24, 14, ' وأما الشيوخ فقال لهم : اجلسوا لنا ههنا حتى نرجع إليكم . وهوذا هارون وحور معكم . فمن كان صاحب دعوى فليتقدم إليهما '),
(11489, 'Exodus', 2, 24, 15, ' فصعد موسى إلى الجبل ، فغطى السحاب الجبل '),
(11490, 'Exodus', 2, 24, 16, ' وحل مجد الرب على جبل سيناء ، وغطاه السحاب ستة أيام . وفي اليوم السابع دعي موسى من وسط السحاب '),
(11491, 'Exodus', 2, 24, 17, ' وكان منظر مجد الرب كنار آكلة على رأس الجبل أمام عيون بني إسرائيل '),
(11492, 'Exodus', 2, 24, 18, ' ودخل موسى في وسط السحاب وصعد إلى الجبل . وكان موسى في الجبل أربعين نهارا وأربعين ليلة '),
(11493, 'Exodus', 2, 25, 1, ' وكلم الرب موسى قائلا '),
(11494, 'Exodus', 2, 25, 2, ' كلم بني إسرائيل أن يأخذوا لي تقدمة . من كل من يحثه قلبه تأخذون تقدمتي '),
(11495, 'Exodus', 2, 25, 3, ' وهذه هي التقدمة التي تأخذونها منهم : ذهب وفضة ونحاس '),
(11496, 'Exodus', 2, 25, 4, ' وأسمانجوني وأرجوان وقرمز وبوص وشعر معزى '),
(11497, 'Exodus', 2, 25, 5, ' وجلود كباش محمرة وجلود تخس وخشب سنط '),
(11498, 'Exodus', 2, 25, 6, ' وزيت للمنارة وأطياب لدهن المسحة وللبخور العطر '),
(11499, 'Exodus', 2, 25, 7, ' وحجارة جزع وحجارة ترصيع للرداء والصدرة '),
(11500, 'Exodus', 2, 25, 8, ' فيصنعون لي مقدسا لأسكن في وسطهم '),
(11501, 'Exodus', 2, 25, 9, ' بحسب جميع ما أنا أريك من مثال المسكن ، ومثال جميع آنيته هكذا تصنعون '),
(11502, 'Exodus', 2, 25, 10, ' فيصنعون تابوتا من خشب السنط ، طوله ذراعان ونصف ، وعرضه ذراع ونصف ، وارتفاعه ذراع ونصف '),
(11503, 'Exodus', 2, 25, 11, ' وتغشيه بذهب نقي . من داخل ومن خارج تغشيه ، وتصنع عليه إكليلا من ذهب حواليه '),
(11504, 'Exodus', 2, 25, 12, ' وتسبك له أربع حلقات من ذهب ، وتجعلها على قوائمه الأربع . على جانبه الواحد حلقتان ، وعلى جانبه الثاني حلقتان '),
(11505, 'Exodus', 2, 25, 13, ' وتصنع عصوين من خشب السنط وتغشيهما بذهب '),
(11506, 'Exodus', 2, 25, 14, ' وتدخل العصوين في الحلقات على جانبي التابوت ليحمل التابوت بهما '),
(11507, 'Exodus', 2, 25, 15, ' تبقى العصوان في حلقات التابوت . لا تنزعان منها '),
(11508, 'Exodus', 2, 25, 16, ' وتضع في التابوت الشهادة التي أعطيك '),
(11509, 'Exodus', 2, 25, 17, ' وتصنع غطاء من ذهب نقي طوله ذراعان ونصف ، وعرضه ذراع ونصف '),
(11510, 'Exodus', 2, 25, 18, ' وتصنع كروبين من ذهب . صنعة خراطة تصنعهما على طرفي الغطاء '),
(11511, 'Exodus', 2, 25, 19, ' فاصنع كروبا واحدا على الطرف من هنا ، وكروبا آخر على الطرف من هناك . من الغطاء تصنعون الكروبين على طرفيه '),
(11512, 'Exodus', 2, 25, 20, ' ويكون الكروبان باسطين أجنحتهما إلى فوق ، مظللين بأجنحتهما على الغطاء ، ووجهاهما كل واحد إلى الآخر . نحو الغطاء يكون وجها الكروبين '),
(11513, 'Exodus', 2, 25, 21, ' وتجعل الغطاء على التابوت من فوق ، وفي التابوت تضع الشهادة التي أعطيك '),
(11514, 'Exodus', 2, 25, 22, ' وأنا أجتمع بك هناك وأتكلم معك ، من على الغطاء من بين الكروبين اللذين على تابوت الشهادة ، بكل ما أوصيك به إلى بني إسرائيل '),
(11515, 'Exodus', 2, 25, 23, ' وتصنع مائدة من خشب السنط طولها ذراعان ، وعرضها ذراع ، وارتفاعها ذراع ونصف '),
(11516, 'Exodus', 2, 25, 24, ' وتغشيها بذهب نقي ، وتصنع لها إكليلا من ذهب حواليها '),
(11517, 'Exodus', 2, 25, 25, ' وتصنع لها حاجبا على شبر حواليها ، وتصنع لحاجبها إكليلا من ذهب حواليها '),
(11518, 'Exodus', 2, 25, 26, ' وتصنع لها أربع حلقات من ذهب ، وتجعل الحلقات على الزوايا الأربع التي لقوائمها الأربع '),
(11519, 'Exodus', 2, 25, 27, ' عند الحاجب تكون الحلقات بيوتا لعصوين لحمل المائدة '),
(11520, 'Exodus', 2, 25, 28, ' وتصنع العصوين من خشب السنط وتغشيهما بذهب ، فتحمل بهما المائدة '),
(11521, 'Exodus', 2, 25, 29, ' وتصنع صحافها وصحونها وكأساتها وجاماتها التي يسكب بها . من ذهب نقي تصنعها '),
(11522, 'Exodus', 2, 25, 30, ' وتجعل على المائدة خبز الوجوه أمامي دائما '),
(11523, 'Exodus', 2, 25, 31, ' وتصنع منارة من ذهب نقي . عمل الخراطة تصنع المنارة ، قاعدتها وساقها . تكون كأساتها وعجرها وأزهارها منها '),
(11524, 'Exodus', 2, 25, 32, ' وست شعب خارجة من جانبيها . من جانبها الواحد ثلاث شعب منارة ، ومن جانبها الثاني ثلاث شعب منارة '),
(11525, 'Exodus', 2, 25, 33, ' في الشعبة الواحدة ثلاث كأسات لوزية بعجرة وزهر ، وفي الشعبة الثانية ثلاث كأسات لوزية بعجرة وزهر ، وهكذا إلى الست الشعب الخارجة من المنارة '),
(11526, 'Exodus', 2, 25, 34, ' وفي المنارة أربع كأسات لوزية بعجرها وأزهارها '),
(11527, 'Exodus', 2, 25, 35, ' وتحت الشعبتين منها عجرة ، وتحت الشعبتين منها عجرة ، وتحت الشعبتين منها عجرة إلى الست الشعب الخارجة من المنارة '),
(11528, 'Exodus', 2, 25, 36, ' تكون عجرها وشعبها منها . جميعها خراطة واحدة من ذهب نقي '),
(11529, 'Exodus', 2, 25, 37, ' وتصنع سرجها سبعة ، فتصعد سرجها لتضيء إلى مقابلها '),
(11530, 'Exodus', 2, 25, 38, ' وملاقطها ومنافضها من ذهب نقي '),
(11531, 'Exodus', 2, 25, 39, ' من وزنة ذهب نقي تصنع مع جميع هذه الأواني '),
(11532, 'Exodus', 2, 25, 40, ' وانظر فاصنعها على مثالها الذي أظهر لك في الجبل '),
(11533, 'Exodus', 2, 26, 1, ' وأما المسكن فتصنعه من عشر شقق بوص مبروم وأسمانجوني وأرجوان وقرمز . بكروبيم صنعة حائك حاذق تصنعها '),
(11534, 'Exodus', 2, 26, 2, ' طول الشقة الواحدة ثمان وعشرون ذراعا ، وعرض الشقة الواحدة أربع أذرع . قياسا واحدا لجميع الشقق '),
(11535, 'Exodus', 2, 26, 3, ' تكون خمس من الشقق بعضها موصول ببعض ، وخمس شقق بعضها موصول ببعض '),
(11536, 'Exodus', 2, 26, 4, ' وتصنع عرى من أسمانجوني على حاشية الشقة الواحدة في الطرف من الموصل الواحد . وكذلك تصنع في حاشية الشقة الطرفية من الموصل الثاني '),
(11537, 'Exodus', 2, 26, 5, ' خمسين عروة تصنع في الشقة الواحدة ، وخمسين عروة تصنع في طرف الشقة الذي في الموصل الثاني . تكون العرى بعضها مقابل لبعض '),
(11538, 'Exodus', 2, 26, 6, ' وتصنع خمسين شظاظا من ذهب ، وتصل الشقتين بعضهما ببعض بالأشظة . فيصير المسكن واحدا '),
(11539, 'Exodus', 2, 26, 7, ' وتصنع شققا من شعر معزى خيمة على المسكن . إحدى عشرة شقة تصنعها '),
(11540, 'Exodus', 2, 26, 8, ' طول الشقة الواحدة ثلاثون ذراعا ، وعرض الشقة الواحدة أربع أذرع . قياسا واحدا للإحدى عشرة شقة '),
(11541, 'Exodus', 2, 26, 9, ' وتصل خمسا من الشقق وحدها ، وستا من الشقق وحدها . وتثني الشقة السادسة في وجه الخيمة '),
(11542, 'Exodus', 2, 26, 10, ' وتصنع خمسين عروة على حاشية الشقة الواحدة الطرفية من الموصل الواحد ، وخمسين عروة على حاشية الشقة من الموصل الثاني '),
(11543, 'Exodus', 2, 26, 11, ' وتصنع خمسين شظاظا من نحاس ، وتدخل الأشظة في العرى ، وتصل الخيمة فتصير واحدة '),
(11544, 'Exodus', 2, 26, 12, ' وأما المدلى الفاضل من شقق الخيمة ، نصف الشقة الموصلة الفاضل ، فيدلى على مؤخر المسكن '),
(11545, 'Exodus', 2, 26, 13, ' والذراع من هنا والذراع من هناك ، من الفاضل في طول شقق الخيمة ، تكونان مدلاتين على جانبي المسكن من هنا ومن هناك لتغطيته '),
(11546, 'Exodus', 2, 26, 14, ' وتصنع غطاء للخيمة من جلود كباش محمرة ، وغطاء من جلود تخس من فوق '),
(11547, 'Exodus', 2, 26, 15, ' وتصنع الألواح للمسكن من خشب السنط قائمة '),
(11548, 'Exodus', 2, 14, 12, ' أليس هذا هو الكلام الذي كلمناك به في مصر قائلين : كف عنا فنخدم المصريين ؟ لأنه خير لنا أن نخدم المصريين من أن نموت في البرية '),
(11549, 'Exodus', 2, 14, 13, ' فقال موسى للشعب : لا تخافوا . قفوا وانظروا خلاص الرب الذي يصنعه لكم اليوم . فإنه كما رأيتم المصريين اليوم ، لا تعودون ترونهم أيضا إلى الأبد '),
(11550, 'Exodus', 2, 14, 14, ' الرب يقاتل عنكم وأنتم تصمتون '),
(11551, 'Exodus', 2, 14, 15, ' فقال الرب لموسى : ما لك تصرخ إلي ؟ قل لبني إسرائيل أن يرحلوا '),
(11552, 'Exodus', 2, 14, 16, ' وارفع أنت عصاك ومد يدك على البحر وشقه ، فيدخل بنو إسرائيل في وسط البحر على اليابسة '),
(11553, 'Exodus', 2, 14, 17, ' وها أنا أشدد قلوب المصريين حتى يدخلوا وراءهم ، فأتمجد بفرعون وكل جيشه ، بمركباته وفرسانه '),
(11554, 'Exodus', 2, 14, 18, ' فيعرف المصريون أني أنا الرب حين أتمجد بفرعون ومركباته وفرسانه '),
(11555, 'Exodus', 2, 14, 19, ' فانتقل ملاك الله السائر أمام عسكر إسرائيل وسار وراءهم ، وانتقل عمود السحاب من أمامهم ووقف وراءهم '),
(11556, 'Exodus', 2, 14, 20, ' فدخل بين عسكر المصريين وعسكر إسرائيل ، وصار السحاب والظلام وأضاء الليل . فلم يقترب هذا إلى ذاك كل الليل '),
(11557, 'Exodus', 2, 14, 21, ' ومد موسى يده على البحر ، فأجرى الرب البحر بريح شرقية شديدة كل الليل ، وجعل البحر يابسة وانشق الماء '),
(11558, 'Exodus', 2, 14, 22, ' فدخل بنو إسرائيل في وسط البحر على اليابسة ، والماء سور لهم عن يمينهم وعن يسارهم '),
(11559, 'Exodus', 2, 14, 23, ' وتبعهم المصريون ودخلوا وراءهم . جميع خيل فرعون ومركباته وفرسانه إلى وسط البحر '),
(11560, 'Exodus', 2, 14, 24, ' وكان في هزيع الصبح أن الرب أشرف على عسكر المصريين في عمود النار والسحاب ، وأزعج عسكر المصريين '),
(11561, 'Exodus', 2, 14, 25, ' وخلع بكر مركباتهم حتى ساقوها بثقلة . فقال المصريون : نهرب من إسرائيل ، لأن الرب يقاتل المصريين عنهم '),
(11562, 'Exodus', 2, 14, 26, ' فقال الرب لموسى : مد يدك على البحر ليرجع الماء على المصريين ، على مركباتهم وفرسانهم '),
(11563, 'Exodus', 2, 14, 27, ' فمد موسى يده على البحر فرجع البحر عند إقبال الصبح إلى حاله الدائمة ، والمصريون هاربون إلى لقائه . فدفع الرب المصريين في وسط البحر '),
(11564, 'Exodus', 2, 14, 28, ' فرجع الماء وغطى مركبات وفرسان جميع جيش فرعون الذي دخل وراءهم في البحر . لم يبق منهم ولاواحد '),
(11565, 'Exodus', 2, 14, 29, ' وأما بنو إسرائيل فمشوا على اليابسة في وسط البحر ، والماء سور لهم عن يمينهم وعن يسارهم '),
(11566, 'Exodus', 2, 14, 30, ' فخلص الرب في ذلك اليوم إسرائيل من يد المصريين . ونظر إسرائيل المصريين أمواتا على شاطئ البحر '),
(11567, 'Exodus', 2, 14, 31, ' ورأى إسرائيل الفعل العظيم الذي صنعه الرب بالمصريين ، فخاف الشعب الرب وآمنوا بالرب وبعبده موسى '),
(11568, 'Exodus', 2, 15, 1, ' حينئذ رنم موسى وبنو إسرائيل هذه التسبيحة للرب وقالوا : أرنم للرب فإنه قد تعظم . الفرس وراكبه طرحهما في البحر '),
(11569, 'Exodus', 2, 15, 2, ' الرب قوتي ونشيدي ، وقد صار خلاصي . هذا إلهي فأمجده ، إله أبي فأرفعه '),
(11570, 'Exodus', 2, 15, 3, ' الرب رجل الحرب . الرب اسمه '),
(11571, 'Exodus', 2, 15, 4, ' مركبات فرعون وجيشه ألقاهما في البحر ، فغرق أفضل جنوده المركبية في بحر سوف '),
(11572, 'Exodus', 2, 15, 5, ' تغطيهم اللجج . قد هبطوا في الأعماق كحجر '),
(11573, 'Exodus', 2, 15, 6, ' يمينك يارب معتزة بالقدرة . يمينك يارب تحطم العدو '),
(11574, 'Exodus', 2, 15, 7, ' وبكثرة عظمتك تهدم مقاوميك . ترسل سخطك فيأكلهم كالقش '),
(11575, 'Exodus', 2, 15, 8, ' وبريح أنفك تراكمت المياه . انتصبت المجاري كرابية . تجمدت اللجج في قلب البحر '),
(11576, 'Exodus', 2, 15, 9, ' قال العدو : أتبع ، أدرك ، أقسم غنيمة . تمتلئ منهم نفسي . أجرد سيفي . تفنيهم يدي '),
(11577, 'Exodus', 2, 15, 10, ' نفخت بريحك فغطاهم البحر . غاصوا كالرصاص في مياه غامرة '),
(11578, 'Exodus', 2, 15, 11, ' من مثلك بين الآلهة يارب ؟ من مثلك معتزا في القداسة ، مخوفا بالتسابيح ، صانعا عجائب '),
(11579, 'Exodus', 2, 15, 12, ' تمد يمينك فتبتلعهم الأرض '),
(11580, 'Exodus', 2, 15, 13, ' ترشد برأفتك الشعب الذي فديته . تهديه بقوتك إلى مسكن قدسك '),
(11581, 'Exodus', 2, 15, 14, ' يسمع الشعوب فيرتعدون . تأخذ الرعدة سكان فلسطين '),
(11582, 'Exodus', 2, 15, 15, ' حينئذ يندهش أمراء أدوم . أقوياء موآب تأخذهم الرجفة . يذوب جميع سكان كنعان '),
(11583, 'Exodus', 2, 15, 16, ' تقع عليهم الهيبة والرعب . بعظمة ذراعك يصمتون كالحجر حتى يعبر شعبك يارب . حتى يعبر الشعب الذي اقتنيته '),
(11584, 'Exodus', 2, 15, 17, ' تجيء بهم وتغرسهم في جبل ميراثك ، المكان الذي صنعته يارب لسكنك المقدس الذي هيأته يداك يارب '),
(11585, 'Exodus', 2, 15, 18, ' الرب يملك إلى الدهر والأبد '),
(11586, 'Exodus', 2, 15, 19, ' فإن خيل فرعون دخلت بمركباته وفرسانه إلى البحر ، ورد الرب عليهم ماء البحر . وأما بنو إسرائيل فمشوا على اليابسة في وسط البحر '),
(11587, 'Exodus', 2, 15, 20, ' فأخذت مريم النبية أخت هارون الدف بيدها ، وخرجت جميع النساء وراءها بدفوف ورقص '),
(11588, 'Exodus', 2, 15, 21, ' وأجابتهم مريم : رنموا للرب فإنه قد تعظم . الفرس وراكبه طرحهما في البحر '),
(11589, 'Exodus', 2, 15, 22, ' ثم ارتحل موسى بإسرائيل من بحر سوف وخرجوا إلى برية شور . فساروا ثلاثة أيام في البرية ولم يجدوا ماء '),
(11590, 'Exodus', 2, 15, 23, ' فجاءوا إلى مارة ، ولم يقدروا أن يشربوا ماء من مارة لأنه مر . لذلك دعي اسمها مارة '),
(11591, 'Exodus', 2, 15, 24, ' فتذمر الشعب على موسى قائلين : ماذا نشرب '),
(11592, 'Exodus', 2, 15, 25, ' فصرخ إلى الرب . فأراه الرب شجرة فطرحها في الماء فصار الماء عذبا . هناك وضع له فريضة وحكما ، وهناك امتحنه '),
(11593, 'Exodus', 2, 15, 26, ' فقال : إن كنت تسمع لصوت الرب إلهك ، وتصنع الحق في عينيه ، وتصغى إلى وصاياه وتحفظ جميع فرائضه ، فمرضا ما مما وضعته على المصريين لا أضع عليك . فإني أنا الرب شافيك '),
(11594, 'Exodus', 2, 15, 27, ' ثم جاءوا إلى إيليم وهناك اثنتا عشرة عين ماء وسبعون نخلة . فنزلوا هناك عند الماء '),
(11595, 'Exodus', 2, 16, 1, ' ثم ارتحلوا من إيليم . وأتى كل جماعة بني إسرائيل إلى برية سين ، التي بين إيليم وسيناء في اليوم الخامس عشر من الشهر الثاني بعد خروجهم من أرض مصر '),
(11596, 'Exodus', 2, 16, 2, ' فتذمر كل جماعة بني إسرائيل على موسى وهارون في البرية '),
(11597, 'Exodus', 2, 16, 3, ' وقال لهما بنو إسرائيل : ليتنا متنا بيد الرب في أرض مصر ، إذ كنا جالسين عند قدور اللحم نأكل خبزا للشبع . فإنكما أخرجتمانا إلى هذا القفر لكي تميتا كل هذا الجمهور بالجوع '),
(11598, 'Exodus', 2, 16, 4, ' فقال الرب لموسى : ها أنا أمطر لكم خبزا من السماء . فيخرج الشعب ويلتقطون حاجة اليوم بيومها . لكي أمتحنهم ، أيسلكون في ناموسي أم لا '),
(11599, 'Exodus', 2, 16, 5, ' ويكون في اليوم السادس أنهم يهيئون ما يجيئون به فيكون ضعف ما يلتقطونه يوما فيوما '),
(11600, 'Exodus', 2, 16, 6, ' فقال موسى وهارون لجميع بني إسرائيل : في المساء تعلمون أن الرب أخرجكم من أرض مصر '),
(11601, 'Exodus', 2, 16, 7, ' وفي الصباح ترون مجد الرب لاستماعه تذمركم على الرب . وأما نحن فماذا حتى تتذمروا علينا '),
(11602, 'Exodus', 2, 16, 8, ' وقال موسى : ذلك بأن الرب يعطيكم في المساء لحما لتأكلوا ، وفي الصباح خبزا لتشبعوا ، لاستماع الرب تذمركم الذي تتذمرون عليه . وأما نحن فماذا ؟ ليس علينا تذمركم بل على الرب '),
(11603, 'Exodus', 2, 16, 9, ' وقال موسى لهارون : قل لكل جماعة بني إسرائيل : اقتربوا إلى أمام الرب لأنه قد سمع تذمركم '),
(11604, 'Exodus', 2, 16, 10, ' فحدث إذ كان هارون يكلم كل جماعة بني إسرائيل أنهم التفتوا نحو البرية ، وإذا مجد الرب قد ظهر في السحاب '),
(11605, 'Exodus', 2, 16, 11, ' فكلم الرب موسى قائلا '),
(11606, 'Exodus', 2, 16, 12, ' سمعت تذمر بني إسرائيل . كلمهم قائلا : في العشية تأكلون لحما ، وفي الصباح تشبعون خبزا ، وتعلمون أني أنا الرب إلهكم '),
(11607, 'Exodus', 2, 16, 13, ' فكان في المساء أن السلوى صعدت وغطت المحلة . وفي الصباح كان سقيط الندى حوالي المحلة '),
(11608, 'Exodus', 2, 16, 14, ' ولما ارتفع سقيط الندى إذا على وجه البرية شيء دقيق مثل قشور . دقيق كالجليد على الأرض '),
(11609, 'Exodus', 2, 16, 15, ' فلما رأى بنو إسرائيل قالوا بعضهم لبعض : من هو ؟ لأنهم لم يعرفوا ما هو . فقال لهم موسى : هو الخبز الذي أعطاكم الرب لتأكلوا '),
(11610, 'Exodus', 2, 16, 16, ' هذا هو الشيء الذي أمر به الرب . التقطوا منه كل واحد على حسب أكله . عمرا للرأس على عدد نفوسكم تأخذون ، كل واحد للذين في خيمته '),
(11611, 'Exodus', 2, 16, 17, ' ففعل بنو إسرائيل هكذا ، والتقطوا بين مكثر ومقلل '),
(11612, 'Exodus', 2, 16, 18, ' ولما كالوا بالعمر ، لم يفضل المكثر والمقلل لم ينقص . كانوا قد التقطوا كل واحد على حسب أكله '),
(11613, 'Exodus', 2, 16, 19, ' وقال لهم موسى : لا يبق أحد منه إلى الصباح '),
(11614, 'Exodus', 2, 16, 20, ' لكنهم لم يسمعوا لموسى ، بل أبقى منه أناس إلى الصباح ، فتولد فيه دود وأنتن . فسخط عليهم موسى '),
(11615, 'Exodus', 2, 16, 21, ' وكانوا يلتقطونه صباحا فصباحا كل واحد على حسب أكله . وإذا حميت الشمس كان يذوب '),
(11616, 'Exodus', 2, 16, 22, ' ثم كان في اليوم السادس أنهم التقطوا خبزا مضاعفا ، عمرين للواحد . فجاء كل رؤساء الجماعة وأخبروا موسى '),
(11617, 'Exodus', 2, 16, 23, ' فقال لهم : هذا ما قال الرب : غدا عطلة ، سبت مقدس للرب . اخبزوا ما تخبزون واطبخوا ما تطبخون . وكل ما فضل ضعوه عندكم ليحفظ إلى الغد '),
(11618, 'Exodus', 2, 16, 24, ' فوضعوه إلى الغد كما أمر موسى ، فلم ينتن ولا صار فيه دود '),
(11619, 'Exodus', 2, 16, 25, ' فقال موسى : كلوه اليوم ، لأن للرب اليوم سبتا . اليوم لا تجدونه في الحقل '),
(11620, 'Exodus', 2, 16, 26, ' ستة أيام تلتقطونه ، وأما اليوم السابع ففيه سبت ، لا يوجد فيه '),
(11621, 'Exodus', 2, 16, 27, ' وحدث في اليوم السابع أن بعض الشعب خرجوا ليلتقطوا فلم يجدوا '),
(11622, 'Exodus', 2, 16, 28, ' فقال الرب لموسى : إلى متى تأبون أن تحفظوا وصاياي وشرائعي '),
(11623, 'Exodus', 2, 16, 29, ' انظروا إن الرب أعطاكم السبت . لذلك هو يعطيكم في اليوم السادس خبز يومين . اجلسوا كل واحد في مكانه . لايخرج أحد من مكانه في اليوم السابع '),
(11624, 'Exodus', 2, 16, 30, ' فاستراح الشعب في اليوم السابع '),
(11625, 'Exodus', 2, 16, 31, ' ودعا بيت إسرائيل اسمه منا . وهو كبزر الكزبرة ، أبيض ، وطعمه كرقاق بعسل '),
(11626, 'Exodus', 2, 16, 32, ' وقال موسى : هذا هو الشيء الذي أمر به الرب . ملء العمر منه يكون للحفظ في أجيالكم . لكي يروا الخبز الذي أطعمتكم في البرية حين أخرجتكم من أرض مصر '),
(11627, 'Exodus', 2, 16, 33, ' وقال موسى لهارون : خذ قسطا واحدا واجعل فيه ملء العمر منا ، وضعه أمام الرب للحفظ في أجيالكم '),
(11628, 'Exodus', 2, 16, 34, ' كما أمر الرب موسى وضعه هارون أمام الشهادة للحفظ '),
(11629, 'Exodus', 2, 16, 35, ' وأكل بنو إسرائيل المن أربعين سنة حتى جاءوا إلى أرض عامرة . أكلوا المن حتى جاءوا إلى طرف أرض كنعان '),
(11630, 'Exodus', 2, 16, 36, ' وأما العمر فهو عشر الإيفة '),
(11631, 'Exodus', 2, 17, 1, ' ثم ارتحل كل جماعة بني إسرائيل من برية سين بحسب مراحلهم على موجب أمر الرب ، ونزلوا في رفيديم . ولم يكن ماء ليشرب الشعب '),
(11632, 'Exodus', 2, 17, 2, ' فخاصم الشعب موسى وقالوا : أعطونا ماء لنشرب . فقال لهم موسى : لماذا تخاصمونني ؟ لماذا تجربون الرب '),
(11633, 'Exodus', 2, 17, 3, ' وعطش هناك الشعب إلى الماء ، وتذمر الشعب على موسى وقالوا : لماذا أصعدتنا من مصر لتميتنا وأولادنا ومواشينا بالعطش '),
(11634, 'Exodus', 2, 17, 4, ' فصرخ موسى إلى الرب قائلا : ماذا أفعل بهذا الشعب ؟ بعد قليل يرجمونني '),
(11635, 'Exodus', 2, 17, 5, ' فقال الرب لموسى : مر قدام الشعب ، وخذ معك من شيوخ إسرائيل . وعصاك التي ضربت بها النهر خذها في يدك واذهب '),
(11636, 'Exodus', 2, 17, 6, ' ها أنا أقف أمامك هناك على الصخرة في حوريب ، فتضرب الصخرة فيخرج منها ماء ليشرب الشعب . ففعل موسى هكذا أمام عيون شيوخ إسرائيل '),
(11637, 'Exodus', 2, 17, 7, ' ودعا اسم الموضع مسة ومريبة من أجل مخاصمة بني إسرائيل ، ومن أجل تجربتهم للرب قائلين : أفي وسطنا الرب أم لا '),
(11638, 'Exodus', 2, 17, 8, ' وأتى عماليق وحارب إسرائيل في رفيديم ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(11639, 'Exodus', 2, 17, 9, ' فقال موسى ليشوع : انتخب لنا رجالا واخرج حارب عماليق . وغدا أقف أنا على رأس التلة وعصا الله في يدي '),
(11640, 'Exodus', 2, 17, 10, ' ففعل يشوع كما قال له موسى ليحارب عماليق . وأما موسى وهارون وحور فصعدوا على رأس التلة '),
(11641, 'Exodus', 2, 17, 11, ' وكان إذا رفع موسى يده أن إسرائيل يغلب ، وإذا خفض يده أن عماليق يغلب '),
(11642, 'Exodus', 2, 17, 12, ' فلما صارت يدا موسى ثقيلتين ، أخذا حجرا ووضعاه تحته فجلس عليه . ودعم هارون وحور يديه ، الواحد من هنا والآخر من هناك . فكانت يداه ثابتتين إلى غروب الشمس '),
(11643, 'Exodus', 2, 17, 13, ' فهزم يشوع عماليق وقومه بحد السيف '),
(11644, 'Exodus', 2, 17, 14, ' فقال الرب لموسى : اكتب هذا تذكارا في الكتاب ، وضعه في مسامع يشوع . فإني سوف أمحو ذكر عماليق من تحت السماء '),
(11645, 'Exodus', 2, 17, 15, ' فبنى موسى مذبحا ودعا اسمه يهوه نسي '),
(11646, 'Exodus', 2, 17, 16, ' وقال : إن اليد على كرسي الرب . للرب حرب مع عماليق من دور إلى دور '),
(11647, 'Exodus', 2, 18, 1, ' فسمع يثرون كاهن مديان ، حمو موسى ، كل ما صنع الله إلى موسى وإلى إسرائيل شعبه : أن الرب أخرج إسرائيل من مصر '),
(11648, 'Exodus', 2, 18, 2, ' فأخذ يثرون حمو موسى صفورة امرأة موسى بعد صرفها '),
(11649, 'Exodus', 2, 18, 3, ' وابنيها ، اللذين اسم أحدهما جرشوم ، لأنه قال : كنت نزيلا في أرض غريبة '),
(11650, 'Exodus', 2, 18, 4, ' واسم الآخر أليعازر ، لأنه قال : إله أبي كان عوني وأنقذني من سيف فرعون '),
(11651, 'Exodus', 2, 18, 5, ' وأتى يثرون حمو موسى وابناه وامرأته إلى موسى إلى البرية حيث كان نازلا عند جبل الله '),
(11652, 'Exodus', 2, 18, 6, ' فقال لموسى : أنا حموك يثرون ، آت إليك وامرأتك وابناها معها '),
(11653, 'Exodus', 2, 18, 7, ' فخرج موسى لاستقبال حميه وسجد وقبله . وسأل كل واحد صاحبه عن سلامته ، ثم دخلا إلى الخيمة '),
(11654, 'Exodus', 2, 18, 8, ' فقص موسى على حميه كل ما صنع الرب بفرعون والمصريين من أجل إسرائيل ، وكل المشقة التي أصابتهم في الطريق فخلصهم الرب '),
(11655, 'Exodus', 2, 18, 9, ' ففرح يثرون بجميع الخير الذي صنعه إلى إسرائيل الرب ، الذي أنقذه من أيدي المصريين '),
(11656, 'Exodus', 2, 18, 10, ' وقال يثرون : مبارك الرب الذي أنقذكم من أيدي المصريين ومن يد فرعون . الذي أنقذ الشعب من تحت أيدي المصريين '),
(11657, 'Exodus', 2, 18, 11, ' الآن علمت أن الرب أعظم من جميع الآلهة ، لأنه في الشيء الذي بغوا به كان عليهم '),
(11658, 'Exodus', 2, 18, 12, ' فأخذ يثرون حمو موسى محرقة وذبائح لله . وجاء هارون وجميع شيوخ إسرائيل ليأكلوا طعاما مع حمي موسى أمام الله '),
(11659, 'Exodus', 2, 18, 13, ' وحدث في الغد أن موسى جلس ليقضي للشعب . فوقف الشعب عند موسى من الصباح إلى المساء '),
(11660, 'Exodus', 2, 18, 14, ' فلما رأى حمو موسى كل ما هو صانع للشعب ، قال : ما هذا الأمر الذي أنت صانع للشعب ؟ ما بالك جالسا وحدك وجميع الشعب واقف عندك من الصباح إلى المساء '),
(11661, 'Exodus', 2, 18, 15, ' فقال موسى لحميه : إن الشعب يأتي إلي ليسأل الله '),
(11662, 'Exodus', 2, 18, 16, ' إذا كان لهم دعوى يأتون إلي فأقضي بين الرجل وصاحبه ، وأعرفهم فرائض الله وشرائعه '),
(11663, 'Exodus', 2, 18, 17, ' فقال حمو موسى له : ليس جيدا الأمر الذي أنت صانع '),
(11664, 'Exodus', 2, 18, 18, ' إنك تكل أنت وهذا الشعب الذي معك جميعا ، لأن الأمر أعظم منك . لا تستطيع أن تصنعه وحدك '),
(11665, 'Exodus', 2, 18, 19, ' الآن اسمع لصوتي فأنصحك . فليكن الله معك . كن أنت للشعب أمام الله ، وقدم أنت الدعاوي إلى الله '),
(11666, 'Exodus', 2, 18, 20, ' وعلمهم الفرائض والشرائع ، وعرفهم الطريق الذي يسلكونه ، والعمل الذي يعملونه '),
(11667, 'Exodus', 2, 18, 21, ' وأنت تنظر من جميع الشعب ذوي قدرة خائفين الله ، أمناء مبغضين الرشوة ، وتقيمهم عليهم رؤساء ألوف ، ورؤساء مئات ، ورؤساء خماسين ، ورؤساء عشرات '),
(11668, 'Exodus', 2, 18, 22, ' فيقضون للشعب كل حين . ويكون أن كل الدعاوي الكبيرة يجيئون بها إليك ، وكل الدعاوي الصغيرة يقضون هم فيها . وخفف عن نفسك ، فهم يحملون معك '),
(11669, 'Exodus', 2, 18, 23, ' إن فعلت هذا الأمر وأوصاك الله تستطيع القيام . وكل هذا الشعب أيضا يأتي إلى مكانه بالسلام '),
(11670, 'Exodus', 2, 18, 24, ' فسمع موسى لصوت حميه وفعل كل ماقال '),
(11671, 'Exodus', 2, 18, 25, ' واختار موسى ذوي قدرة من جميع إسرائيل وجعلهم رؤوسا على الشعب ، رؤساء ألوف ، ورؤساء مئات ، ورؤساء خماسين ، ورؤساء عشرات '),
(11672, 'Exodus', 2, 18, 26, ' فكانوا يقضون للشعب كل حين . الدعاوي العسرة يجيئون بها إلى موسى ، وكل الدعاوي الصغيرة يقضون هم فيها '),
(11673, 'Exodus', 2, 18, 27, ' ثم صرف موسى حماه فمضى إلى أرضه '),
(11674, 'Exodus', 2, 19, 1, ' في الشهر الثالث بعد خروج بني إسرائيل من أرض مصر ، في ذلك اليوم جاءوا إلى برية سيناء '),
(11675, 'Exodus', 2, 19, 2, ' ارتحلوا من رفيديم وجاءوا إلى برية سيناء فنزلوا في البرية . هناك نزل إسرائيل مقابل الجبل '),
(11676, 'Exodus', 2, 19, 3, ' وأما موسى فصعد إلى الله . فناداه الرب من الجبل قائلا : هكذا تقول لبيت يعقوب ، وتخبر بني إسرائيل '),
(11677, 'Exodus', 2, 19, 4, ' أنتم رأيتم ما صنعت بالمصريين . وأنا حملتكم على أجنحة النسور وجئت بكم إلي '),
(11678, 'Exodus', 2, 19, 5, ' فالآن إن سمعتم لصوتي ، وحفظتم عهدي تكونون لي خاصة من بين جميع الشعوب . فإن لي كل الأرض '),
(11679, 'Exodus', 2, 19, 6, ' وأنتم تكونون لي مملكة كهنة وأمة مقدسة . هذه هي الكلمات التي تكلم بها بني إسرائيل '),
(11680, 'Exodus', 2, 19, 7, ' فجاء موسى ودعا شيوخ الشعب ووضع قدامهم كل هذه الكلمات التي أوصاه بها الرب '),
(11681, 'Exodus', 2, 19, 8, ' فأجاب جميع الشعب معا وقالوا : كل ما تكلم به الرب نفعل . فرد موسى كلام الشعب إلى الرب '),
(11682, 'Exodus', 2, 19, 9, ' فقال الرب لموسى : ها أنا آت إليك في ظلام السحاب لكي يسمع الشعب حينما أتكلم معك ، فيؤمنوا بك أيضا إلى الأبد . وأخبر موسى الرب بكلام الشعب '),
(11683, 'Exodus', 2, 19, 10, ' فقال الرب لموسى : اذهب إلى الشعب وقدسهم اليوم وغدا ، وليغسلوا ثيابهم '),
(11684, 'Exodus', 2, 19, 11, ' ويكونوا مستعدين لليوم الثالث . لأنه في اليوم الثالث ينزل الرب أمام عيون جميع الشعب على جبل سيناء '),
(11685, 'Exodus', 2, 19, 12, ' وتقيم للشعب حدودا من كل ناحية ، قائلا : احترزوا من أن تصعدوا إلى الجبل أوتمسوا طرفه . كل من يمس الجبل يقتل قتلا '),
(11686, 'Exodus', 2, 19, 13, ' لا تمسه يد بل يرجم رجما أو يرمى رميا . بهيمة كان أم إنسانا لا يعيش . أما عند صوت البوق فهم يصعدون إلى الجبل '),
(11687, 'Exodus', 2, 19, 14, ' فانحدر موسى من الجبل إلى الشعب ، وقدس الشعب وغسلوا ثيابهم '),
(11688, 'Exodus', 2, 19, 15, ' وقال للشعب : كونوا مستعدين لليوم الثالث . لاتقربوا امرأة '),
(11689, 'Exodus', 2, 19, 16, ' وحدث في اليوم الثالث لما كان الصباح أنه صارت رعود وبروق وسحاب ثقيل على الجبل ، وصوت بوق شديد جدا . فارتعد كل الشعب الذي في المحلة '),
(11690, 'Exodus', 2, 19, 17, ' وأخرج موسى الشعب من المحلة لملاقاة الله ، فوقفوا في أسفل الجبل '),
(11691, 'Exodus', 2, 19, 18, ' وكان جبل سيناء كله يدخن من أجل أن الرب نزل عليه بالنار ، وصعد دخانه كدخان الأتون ، وارتجف كل الجبل جدا '),
(11692, 'Exodus', 2, 19, 19, ' فكان صوت البوق يزداد اشتدادا جدا ، وموسى يتكلم والله يجيبه بصوت '),
(11693, 'Exodus', 2, 19, 20, ' ونزل الرب على جبل سيناء ، إلى رأس الجبل ، ودعا الله موسى إلى رأس الجبل . فصعد موسى '),
(11694, 'Exodus', 2, 19, 21, ' فقال الرب لموسى : انحدر حذر الشعب لئلا يقتحموا إلى الرب لينظروا ، فيسقط منهم كثيرون '),
(11695, 'Exodus', 2, 19, 22, ' وليتقدس أيضا الكهنة الذين يقتربون إلى الرب لئلا يبطش بهم الرب '),
(11696, 'Exodus', 2, 19, 23, ' فقال موسى للرب : لا يقدر الشعب أن يصعد إلى جبل سيناء ، لأنك أنت حذرتنا قائلا : أقم حدودا للجبل وقدسه '),
(11697, 'Exodus', 2, 19, 24, ' فقال له الرب : اذهب انحدر ثم اصعد أنت وهارون معك . وأما الكهنة والشعب فلا يقتحموا ليصعدوا إلى الرب لئلا يبطش بهم '),
(11698, 'Exodus', 2, 19, 25, ' فانحدر موسى إلى الشعب وقال لهم '),
(11699, 'Exodus', 2, 20, 1, ' ثم تكلم الله بجميع هذه الكلمات قائلا '),
(11700, 'Exodus', 2, 20, 2, ' أنا الرب إلهك الذي أخرجك من أرض مصر من بيت العبودية '),
(11701, 'Exodus', 2, 20, 3, ' لا يكن لك آلهة أخرى أمامي '),
(11702, 'Exodus', 2, 20, 4, ' لاتصنع لك تمثالا منحوتا ، ولا صورة ما مما في السماء من فوق ، وما في الأرض من تحت ، وما في الماء من تحت الأرض '),
(11703, 'Exodus', 2, 20, 5, ' لا تسجد لهن ولا تعبدهن ، لأني أنا الرب إلهك إله غيور ، أفتقد ذنوب الآباء في الأبناء في الجيل الثالث والرابع من مبغضي '),
(11704, 'Exodus', 2, 20, 6, ' وأصنع إحسانا إلى ألوف من محبي وحافظي وصاياي '),
(11705, 'Exodus', 2, 20, 7, ' لا تنطق باسم الرب إلهك باطلا ، لأن الرب لا يبرئ من نطق باسمه باطلا '),
(11706, 'Exodus', 2, 20, 8, ' اذكر يوم السبت لتقدسه '),
(11707, 'Exodus', 2, 20, 9, ' ستة أيام تعمل وتصنع جميع عملك '),
(11708, 'Exodus', 2, 20, 10, ' وأما اليوم السابع ففيه سبت للرب إلهك . لا تصنع عملا ما أنت وابنك وابنتك وعبدك وأمتك وبهيمتك ونزيلك الذي داخل أبوابك '),
(11709, 'Exodus', 2, 20, 11, ' لأن في ستة أيام صنع الرب السماء والأرض والبحر وكل ما فيها ، واستراح في اليوم السابع . لذلك بارك الرب يوم السبت وقدسه '),
(11710, 'Exodus', 2, 20, 12, ' أكرم أباك وأمك لكي تطول أيامك على الأرض التي يعطيك الرب إلهك '),
(11711, 'Exodus', 2, 20, 13, ' لا تقتل '),
(11712, 'Exodus', 2, 20, 14, ' لا تزن '),
(11713, 'Exodus', 2, 20, 15, ' لا تسرق '),
(11714, 'Exodus', 2, 20, 16, ' لا تشهد على قريبك شهادة زور '),
(11715, 'Exodus', 2, 20, 17, ' لا تشته بيت قريبك . لا تشته امرأة قريبك ، ولا عبده ، ولا أمته ، ولا ثوره ، ولا حماره ، ولا شيئا مما لقريبك '),
(11716, 'Exodus', 2, 20, 18, ' وكان جميع الشعب يرون الرعود والبروق وصوت البوق ، والجبل يدخن . ولما رأى الشعب ارتعدوا ووقفوا من بعيد '),
(11717, 'Exodus', 2, 20, 19, ' وقالوا لموسى : تكلم أنت معنا فنسمع . ولا يتكلم معنا الله لئلا نموت '),
(11718, 'Exodus', 2, 20, 20, ' فقال موسى للشعب : لا تخافوا . لأن الله إنما جاء لكي يمتحنكم ، ولكي تكون مخافته أمام وجوهكم حتى لا تخطئوا '),
(11719, 'Exodus', 2, 20, 21, ' فوقف الشعب من بعيد ، وأما موسى فاقترب إلى الضباب حيث كان الله '),
(11720, 'Exodus', 2, 20, 22, ' فقال الرب لموسى : هكذا تقول لبني إسرائيل : أنتم رأيتم أنني من السماء تكلمت معكم '),
(11721, 'Exodus', 2, 20, 23, ' لا تصنعوا معي آلهة فضة ، ولا تصنعوا لكم آلهة ذهب '),
(11722, 'Exodus', 2, 20, 24, ' مذبحا من تراب تصنع لي وتذبح عليه محرقاتك وذبائح سلامتك ، غنمك وبقرك . في كل الأماكن التي فيها أصنع لاسمي ذكرا آتي إليك وأباركك '),
(11723, 'Exodus', 2, 20, 25, ' وإن صنعت لي مذبحا من حجارة فلا تبنه منها منحوتة . إذا رفعت عليها إزميلك تدنسها '),
(11724, 'Exodus', 2, 20, 26, ' ولا تصعد بدرج إلى مذبحي كيلا تنكشف عورتك عليه '),
(11725, 'Exodus', 2, 21, 1, ' وهذه هي الأحكام التي تضع أمامهم '),
(11726, 'Exodus', 2, 21, 2, ' إذا اشتريت عبدا عبرانيا ، فست سنين يخدم ، وفي السابعة يخرج حرا مجانا '),
(11727, 'Exodus', 2, 21, 3, ' إن دخل وحده فوحده يخرج . إن كان بعل امرأة ، تخرج امرأته معه '),
(11728, 'Exodus', 2, 21, 4, ' إن أعطاه سيده امرأة وولدت له بنين أو بنات ، فالمرأة وأولادها يكونون لسيده ، وهو يخرج وحده '),
(11729, 'Exodus', 2, 21, 5, ' ولكن إن قال العبد : أحب سيدي وامرأتي وأولادي ، لا أخرج حرا '),
(11730, 'Exodus', 2, 21, 6, ' يقدمه سيده إلى الله ، ويقربه إلى الباب أو إلى القائمة ، ويثقب سيده أذنه بالمثقب ، فيخدمه إلى الأبد '),
(11731, 'Exodus', 2, 21, 7, ' وإذا باع رجل ابنته أمة ، لا تخرج كما يخرج العبيد '),
(11732, 'Exodus', 2, 21, 8, ' إن قبحت في عيني سيدها الذي خطبها لنفسه ، يدعها تفك . وليس له سلطان أن يبيعها لقوم أجانب لغدره بها '),
(11733, 'Exodus', 2, 21, 9, ' وإن خطبها لابنه فبحسب حق البنات يفعل لها '),
(11734, 'Exodus', 2, 21, 10, ' إن اتخذ لنفسه أخرى ، لا ينقص طعامها وكسوتها ومعاشرتها '),
(11735, 'Exodus', 2, 21, 11, ' وإن لم يفعل لها هذه الثلاث تخرج مجانا بلا ثمن '),
(11736, 'Exodus', 2, 21, 12, ' من ضرب إنسانا فمات يقتل قتلا '),
(11737, 'Exodus', 2, 21, 13, ' ولكن الذي لم يتعمد ، بل أوقع الله في يده ، فأنا أجعل لك مكانا يهرب إليه '),
(11738, 'Exodus', 2, 21, 14, ' وإذا بغى إنسان على صاحبه ليقتله بغدر فمن عند مذبحي تأخذه للموت '),
(11739, 'Exodus', 2, 21, 15, ' ومن ضرب أباه أو أمه يقتل قتلا '),
(11740, 'Exodus', 2, 21, 16, ' ومن سرق إنسانا وباعه ، أو وجد في يده ، يقتل قتلا '),
(11741, 'Exodus', 2, 21, 17, ' ومن شتم أباه أو أمه يقتل قتلا '),
(11742, 'Exodus', 2, 21, 18, ' وإذا تخاصم رجلان فضرب أحدهما الآخر بحجر أو بلكمة ولم يقتل بل سقط في الفراش '),
(11743, 'Exodus', 2, 21, 19, ' فإن قام وتمشى خارجا على عكازه يكون الضارب بريئا . إلا أنه يعوض عطلته ، وينفق على شفائه '),
(11744, 'Exodus', 2, 21, 20, ' وإذا ضرب إنسان عبده أو أمته بالعصا فمات تحت يده ينتقم منه '),
(11745, 'Exodus', 2, 21, 21, ' لكن إن بقي يوما أو يومين لا ينتقم منه لأنه ماله '),
(11746, 'Exodus', 2, 21, 22, ' وإذا تخاصم رجال وصدموا امرأة حبلى فسقط ولدها ولم تحصل أذية ، يغرم كما يضع عليه زوج المرأة ، ويدفع عن يد القضاة '),
(11747, 'Exodus', 2, 21, 23, ' وإن حصلت أذية تعطي نفسا بنفس '),
(11748, 'Exodus', 2, 21, 24, ' وعينا بعين ، وسنا بسن ، ويدا بيد ، ورجلا برجل '),
(11749, 'Exodus', 2, 21, 25, ' وكيا بكي ، وجرحا بجرح ، ورضا برض '),
(11750, 'Exodus', 2, 21, 26, ' وإذا ضرب إنسان عين عبده ، أو عين أمته فأتلفها ، يطلقه حرا عوضا عن عينه '),
(11751, 'Exodus', 2, 21, 27, ' وإن أسقط سن عبده أو سن أمته يطلقه حرا عوضا عن سنه '),
(11752, 'Exodus', 2, 21, 28, ' وإذا نطح ثور رجلا أو امرأة فمات ، يرجم الثور ولا يؤكل لحمه . وأما صاحب الثور فيكون بريئا '),
(11753, 'Exodus', 2, 21, 29, ' ولكن إن كان ثورا نطاحا من قبل ، وقد أشهد على صاحبه ولم يضبطه ، فقتل رجلا أو امرأة ، فالثور يرجم وصاحبه أيضا يقتل '),
(11754, 'Exodus', 2, 21, 30, ' إن وضعت عليه فدية ، يدفع فداء نفسه كل ما يوضع عليه '),
(11755, 'Exodus', 2, 21, 31, ' أو إذا نطح ابنا أو نطح ابنة فبحسب هذا الحكم يفعل به '),
(11756, 'Exodus', 2, 21, 32, ' إن نطح الثور عبدا أو أمة ، يعطي سيده ثلاثين شاقل فضة ، والثور يرجم '),
(11757, 'Exodus', 2, 21, 33, ' وإذا فتح إنسان بئرا ، أو حفر إنسان بئرا ولم يغطه ، فوقع فيه ثور أو حمار '),
(11758, 'Exodus', 2, 21, 34, ' فصاحب البئر يعوض ويرد فضة لصاحبه ، والميت يكون له '),
(11759, 'Exodus', 2, 21, 35, ' وإذا نطح ثور إنسان ثور صاحبه فمات ، يبيعان الثور الحي ويقتسمان ثمنه . والميت أيضا يقتسمانه '),
(11760, 'Exodus', 2, 21, 36, ' لكن إذا علم أنه ثور نطاح من قبل ولم يضبطه صاحبه ، يعوض عن الثور بثور ، والميت يكون له '),
(11761, 'Exodus', 2, 22, 1, ' إذا سرق إنسان ثورا أو شاة فذبحه أو باعه ، يعوض عن الثور بخمسة ثيران ، وعن الشاة بأربعة من الغنم '),
(11762, 'Exodus', 2, 22, 2, ' إن وجد السارق وهو ينقب ، فضرب ومات ، فليس له دم '),
(11763, 'Exodus', 2, 22, 3, ' ولكن إن أشرقت عليه الشمس ، فله دم . إنه يعوض . إن لم يكن له يبع بسرقته '),
(11764, 'Exodus', 2, 22, 4, ' إن وجدت السرقة في يده حية ، ثورا كانت أم حمارا أم شاة ، يعوض باثنين '),
(11765, 'Exodus', 2, 22, 5, ' إذا رعى إنسان حقلا أو كرما وسرح مواشيه فرعت في حقل غيره ، فمن أجود حقله ، وأجود كرمه يعوض '),
(11766, 'Exodus', 2, 22, 6, ' إذا خرجت نار وأصابت شوكا فاحترقت أكداس أو زرع أو حقل ، فالذي أوقد الوقيد يعوض '),
(11767, 'Exodus', 2, 22, 7, ' إذا أعطى إنسان صاحبه فضة أو أمتعة للحفظ ، فسرقت من بيت الإنسان ، فإن وجد السارق ، يعوض باثنين '),
(11768, 'Exodus', 2, 22, 8, ' وإن لم يوجد السارق يقدم صاحب البيت إلى الله ليحكم هل لم يمد يده إلى ملك صاحبه '),
(11769, 'Exodus', 2, 22, 9, ' في كل دعوى جناية ، من جهة ثور أو حمار أو شاة أو ثوب أو مفقود ما ، يقال : إن هذا هو ، تقدم إلى الله دعواهما . فالذي يحكم الله بذنبه ، يعوض صاحبه باثنين '),
(11770, 'Exodus', 2, 22, 10, ' إذا أعطى إنسان صاحبه حمارا أو ثورا أو شاة أو بهيمة ما للحفظ ، فمات أو انكسر أو نهب وليس ناظر '),
(11771, 'Exodus', 2, 22, 11, ' فيمين الرب تكون بينهما ، هل لم يمد يده إلى ملك صاحبه . فيقبل صاحبه . فلا يعوض '),
(11772, 'Exodus', 2, 22, 12, ' وإن سرق من عنده يعوض صاحبه '),
(11773, 'Exodus', 2, 22, 13, ' إن افترس يحضره شهادة . لايعوض عن المفترس '),
(11774, 'Exodus', 2, 22, 14, ' وإذا استعار إنسان من صاحبه شيئا فانكسر أو مات ، وصاحبه ليس معه ، يعوض '),
(11775, 'Exodus', 2, 22, 15, ' وإن كان صاحبه معه لا يعوض . إن كان مستأجرا أتى بأجرته '),
(11776, 'Exodus', 2, 22, 16, ' وإذا راود رجل عذراء لم تخطب ، فاضطجع معها يمهرها لنفسه زوجة '),
(11777, 'Exodus', 2, 22, 17, ' إن أبى أبوها أن يعطيه إياها ، يزن له فضة كمهر العذارى '),
(11778, 'Exodus', 2, 22, 18, ' لا تدع ساحرة تعيش '),
(11779, 'Exodus', 2, 22, 19, ' كل من اضطجع مع بهيمة يقتل قتلا '),
(11780, 'Exodus', 2, 22, 20, ' من ذبح لآلهة غير الرب وحده ، يهلك '),
(11781, 'Exodus', 2, 22, 21, ' ولا تضطهد الغريب ولا تضايقه ، لأنكم كنتم غرباء في أرض مصر '),
(11782, 'Exodus', 2, 22, 22, ' لا تسيء إلى أرملة ما ولا يتيم '),
(11783, 'Exodus', 2, 22, 23, ' إن أسأت إليه فإني إن صرخ إلي أسمع صراخه '),
(11784, 'Exodus', 2, 22, 24, ' فيحمى غضبي وأقتلكم بالسيف ، فتصير نساؤكم أرامل ، وأولادكم يتامى '),
(11785, 'Exodus', 2, 22, 25, ' إن أقرضت فضة لشعبي الفقير الذي عندك فلا تكن له كالمرابي . لاتضعوا عليه ربا '),
(11786, 'Exodus', 2, 22, 26, ' إن ارتهنت ثوب صاحبك فإلى غروب الشمس ترده له '),
(11787, 'Exodus', 2, 22, 27, ' لأنه وحده غطاؤه ، هو ثوبه لجلده ، في ماذا ينام ؟ فيكون إذا صرخ إلي أني أسمع ، لأني رؤوف '),
(11788, 'Exodus', 2, 22, 28, ' لا تسب الله ، ولا تلعن رئيسا في شعبك '),
(11789, 'Exodus', 2, 22, 29, ' لا تؤخر ملء بيدرك ، وقطر معصرتك ، وأبكار بنيك تعطيني '),
(11790, 'Exodus', 2, 22, 30, ' كذلك تفعل ببقرك وغنمك . سبعة أيام يكون مع أمه ، وفي اليوم الثامن تعطيني إياه '),
(11791, 'Exodus', 2, 22, 31, ' وتكونون لي أناسا مقدسين . ولحم فريسة في الصحراء لا تأكلوا . للكلاب تطرحونه '),
(11792, 'Exodus', 2, 23, 1, ' لا تقبل خبرا كاذبا ، ولا تضع يدك مع المنافق لتكون شاهد ظلم '),
(11793, 'Exodus', 2, 23, 2, ' لا تتبع الكثيرين إلى فعل الشر ، ولاتجب في دعوى مائلا وراء الكثيرين للتحريف '),
(11794, 'Exodus', 2, 23, 3, ' ولا تحاب مع المسكين في دعواه '),
(11795, 'Exodus', 2, 23, 4, ' إذا صادفت ثور عدوك أو حماره شاردا ، ترده إليه '),
(11796, 'Exodus', 2, 23, 5, ' إذا رأيت حمار مبغضك واقعا تحت حمله وعدلت عن حله ، فلا بد أن تحل معه '),
(11797, 'Exodus', 2, 23, 6, ' لا تحرف حق فقيرك في دعواه '),
(11798, 'Exodus', 2, 23, 7, ' ابتعد عن كلام الكذب ، ولا تقتل البريء والبار ، لأني لا أبرر المذنب '),
(11799, 'Exodus', 2, 23, 8, ' ولا تأخذ رشوة ، لأن الرشوة تعمي المبصرين ، وتعوج كلام الأبرار '),
(11800, 'Exodus', 2, 23, 9, ' ولا تضايق الغريب فإنكم عارفون نفس الغريب ، لأنكم كنتم غرباء في أرض مصر '),
(11801, 'Exodus', 2, 23, 10, ' وست سنين تزرع أرضك وتجمع غلتها '),
(11802, 'Exodus', 2, 23, 11, ' وأما في السابعة فتريحها وتتركها ليأكل فقراء شعبك . وفضلتهم تأكلها وحوش البرية . كذلك تفعل بكرمك وزيتونك '),
(11803, 'Exodus', 2, 23, 12, ' ستة أيام تعمل عملك . وأما اليوم السابع ففيه تستريح ، لكي يستريح ثورك وحمارك ، ويتنفس ابن أمتك والغريب '),
(11804, 'Exodus', 2, 23, 13, ' وكل ما قلت لكم احتفظوا به ، ولاتذكروا اسم آلهة أخرى ، ولا يسمع من فمك '),
(11805, 'Exodus', 2, 23, 14, ' ثلاث مرات تعيد لي في السنة '),
(11806, 'Exodus', 2, 23, 15, ' تحفظ عيد الفطير . تأكل فطيرا سبعة أيام كما أمرتك في وقت شهر أبيب ، لأنه فيه خرجت من مصر . ولايظهروا أمامي فارغين '),
(11807, 'Exodus', 2, 23, 16, ' وعيد الحصاد أبكار غلاتك التي تزرع في الحقل . وعيد الجمع في نهاية السنة عندما تجمع غلاتك من الحقل '),
(11808, 'Exodus', 2, 23, 17, ' ثلاث مرات في السنة يظهر جميع ذكورك أمام السيد الرب '),
(11809, 'Exodus', 2, 23, 18, ' لا تذبح على خمير دم ذبيحتي ، ولا يبت شحم عيدي إلى الغد '),
(11810, 'Exodus', 2, 23, 19, ' أول أبكار أرضك تحضره إلى بيت الرب إلهك . لا تطبخ جديا بلبن أمه '),
(11811, 'Exodus', 2, 23, 20, ' ها أنا مرسل ملاكا أمام وجهك ليحفظك في الطريق ، وليجيء بك إلى المكان الذي أعددته '),
(11812, 'Exodus', 2, 23, 21, ' احترز منه واسمع لصوته ولا تتمرد عليه ، لأنه لا يصفح عن ذنوبكم ، لأن اسمي فيه '),
(11813, 'Exodus', 2, 23, 22, ' ولكن إن سمعت لصوته وفعلت كل ما أتكلم به ، أعادي أعداءك ، وأضايق مضايقيك '),
(11814, 'Exodus', 2, 23, 23, ' فإن ملاكي يسير أمامك ويجيء بك إلى الأموريين والحثيين والفرزيين والكنعانيين والحويين واليبوسيين ، فأبيدهم '),
(11815, 'Exodus', 2, 23, 24, ' لا تسجد لآلهتهم ، ولا تعبدها ، ولا تعمل كأعمالهم ، بل تبيدهم وتكسر أنصابهم '),
(11816, 'Exodus', 2, 23, 25, ' وتعبدون الرب إلهكم ، فيبارك خبزك وماءك ، وأزيل المرض من بينكم '),
(11817, 'Exodus', 2, 23, 26, ' لا تكون مسقطة ولا عاقر في أرضك ، وأكمل عدد أيامك '),
(11818, 'Exodus', 2, 23, 27, ' أرسل هيبتي أمامك ، وأزعج جميع الشعوب الذين تأتي عليهم ، وأعطيك جميع أعدائك مدبرين '),
(11819, 'Exodus', 2, 23, 28, ' وأرسل أمامك الزنابير . فتطرد الحويين والكنعانيين والحثيين من أمامك '),
(11820, 'Exodus', 2, 23, 29, ' لا أطردهم من أمامك في سنة واحدة ، لئلا تصير الأرض خربة ، فتكثر عليك وحوش البرية '),
(11821, 'Exodus', 2, 23, 30, ' قليلا قليلا أطردهم من أمامك إلى أن تثمر وتملك الأرض '),
(11822, 'Exodus', 2, 23, 31, ' وأجعل تخومك من بحر سوف إلى بحر فلسطين ، ومن البرية إلى النهر . فإني أدفع إلى أيديكم سكان الأرض ، فتطردهم من أمامك '),
(11823, 'Exodus', 2, 23, 32, ' لا تقطع معهم ولا مع آلهتهم عهدا '),
(11824, 'Exodus', 2, 23, 33, ' لا يسكنوا في أرضك لئلا يجعلوك تخطئ إلي . إذا عبدت آلهتهم فإنه يكون لك فخا '),
(11825, 'Exodus', 2, 26, 16, ' طول اللوح عشر أذرع ، وعرض اللوح الواحد ذراع ونصف '),
(11826, 'Exodus', 2, 26, 17, ' وللوح الواحد رجلان مقرونة إحداهما بالأخرى . هكذا تصنع لجميع ألواح المسكن '),
(11827, 'Exodus', 2, 26, 18, ' وتصنع الألواح للمسكن عشرين لوحا إلى جهة الجنوب نحو التيمن '),
(11828, 'Exodus', 2, 26, 19, ' وتصنع أربعين قاعدة من فضة تحت العشرين لوحا . تحت اللوح الواحد قاعدتان لرجليه ، وتحت اللوح الواحد قاعدتان لرجليه '),
(11829, 'Exodus', 2, 26, 20, ' ولجانب المسكن الثاني إلى جهة الشمال عشرين لوحا '),
(11830, 'Exodus', 2, 26, 21, ' وأربعين قاعدة لها من فضة . تحت اللوح الواحد قاعدتان ، وتحت اللوح الواحد قاعدتان '),
(11831, 'Exodus', 2, 26, 22, ' ولمؤخر المسكن نحو الغرب تصنع ستة ألواح '),
(11832, 'Exodus', 2, 26, 23, ' وتصنع لوحين لزاويتي المسكن في المؤخر '),
(11833, 'Exodus', 2, 26, 24, ' ويكونان مزدوجين من أسفل . وعلى سواء يكونان مزدوجين إلى رأسه إلى الحلقة الواحدة . هكذا يكون لكليهما . يكونان للزاويتين '),
(11834, 'Exodus', 2, 26, 25, ' فتكون ثمانية ألواح ، وقواعدها من فضة ست عشرة قاعدة . تحت اللوح الواحد قاعدتان ، وتحت اللوح الواحد قاعدتان '),
(11835, 'Exodus', 2, 26, 26, ' وتصنع عوارض من خشب السنط ، خمسا لألواح جانب المسكن الواحد '),
(11836, 'Exodus', 2, 26, 27, ' وخمس عوارض لألواح جانب المسكن الثاني ، وخمس عوارض لألواح جانب المسكن في المؤخر نحو الغرب '),
(11837, 'Exodus', 2, 26, 28, ' والعارضة الوسطى في وسط الألواح تنفذ من الطرف إلى الطرف '),
(11838, 'Exodus', 2, 26, 29, ' وتغشي الألواح بذهب ، وتصنع حلقاتها من ذهب بيوتا للعوارض ، وتغشي العوارض بذهب '),
(11839, 'Exodus', 2, 26, 30, ' وتقيم المسكن كرسمه الذي أظهر لك في الجبل '),
(11840, 'Exodus', 2, 26, 31, ' وتصنع حجابا من أسمانجوني وأرجوان وقرمز وبوص مبروم . صنعة حائك حاذق يصنعه بكروبيم '),
(11841, 'Exodus', 2, 26, 32, ' وتجعله على أربعة أعمدة من سنط مغشاة بذهب . رززها من ذهب . على أربع قواعد من فضة '),
(11842, 'Exodus', 2, 26, 33, ' وتجعل الحجاب تحت الأشظة . وتدخل إلى هناك داخل الحجاب تابوت الشهادة ، فيفصل لكم الحجاب بين القدس وقدس الأقداس '),
(11843, 'Exodus', 2, 26, 34, ' وتجعل الغطاء على تابوت الشهادة في قدس الأقداس '),
(11844, 'Exodus', 2, 26, 35, ' وتضع المائدة خارج الحجاب ، والمنارة مقابل المائدة على جانب المسكن نحو التيمن ، وتجعل المائدة على جانب الشمال '),
(11845, 'Exodus', 2, 26, 36, ' وتصنع سجفا لمدخل الخيمة من أسمانجوني وأرجوان وقرمز وبوص مبروم صنعة الطراز '),
(11846, 'Exodus', 2, 26, 37, ' وتصنع للسجف خمسة أعمدة من سنط وتغشيها بذهب . رززها من ذهب ، وتسبك لها خمس قواعد من نحاس '),
(11847, 'Exodus', 2, 27, 1, ' وتصنع المذبح من خشب السنط ، طوله خمس أذرع ، وعرضه خمس أذرع . مربعا يكون المذبح . وارتفاعه ثلاث أذرع '),
(11848, 'Exodus', 2, 27, 2, ' وتصنع قرونه على زواياه الأربع . منه تكون قرونه ، وتغشيه بنحاس '),
(11849, 'Exodus', 2, 27, 3, ' وتصنع قدوره لرفع رماده ، ورفوشه ومراكنه ومناشله ومجامره . جميع آنيته تصنعها من نحاس '),
(11850, 'Exodus', 2, 27, 4, ' وتصنع له شباكة صنعة الشبكة من نحاس ، وتصنع على الشبكة أربع حلقات من نحاس على أربعة أطرافه '),
(11851, 'Exodus', 2, 27, 5, ' وتجعلها تحت حاجب المذبح من أسفل ، وتكون الشبكة إلى نصف المذبح '),
(11852, 'Exodus', 2, 27, 6, ' وتصنع عصوين للمذبح ، عصوين من خشب السنط وتغشيهما بنحاس '),
(11853, 'Exodus', 2, 27, 7, ' وتدخل عصواه في الحلقات ، فتكون العصوان على جانبي المذبح حينما يحمل '),
(11854, 'Exodus', 2, 27, 8, ' مجوفا تصنعه من ألواح ، كما أظهر لك في الجبل هكذا يصنعونه '),
(11855, 'Exodus', 2, 27, 9, ' وتصنع دار المسكن . إلى جهة الجنوب نحو التيمن للدار أستار من بوص مبروم مئة ذراع طولا إلى الجهة الواحدة '),
(11856, 'Exodus', 2, 27, 10, ' وأعمدتها عشرون ، وقواعدها عشرون من نحاس . رزز الأعمدة وقضبانها من فضة '),
(11857, 'Exodus', 2, 27, 11, ' وكذلك إلى جهة الشمال في الطول أستار مئة ذراع طولا . وأعمدتها عشرون ، وقواعدها عشرون من نحاس . رزز الأعمدة وقضبانها من فضة '),
(11858, 'Exodus', 2, 27, 12, ' وفي عرض الدار إلى جهة الغرب أستار خمسون ذراعا . أعمدتها عشرة ، وقواعدها عشر '),
(11859, 'Exodus', 2, 27, 13, ' وعرض الدار إلى جهة الشرق نحو الشروق خمسون ذراعا '),
(11860, 'Exodus', 2, 27, 14, ' وخمس عشرة ذراعا من الأستار للجانب الواحد . أعمدتها ثلاثة وقواعدها ثلاث '),
(11861, 'Exodus', 2, 27, 15, ' وللجانب الثاني خمس عشرة ذراعا من الأستار . أعمدتها ثلاثة وقواعدها ثلاث '),
(11862, 'Exodus', 2, 27, 16, ' ولباب الدار سجف عشرون ذراعا من أسمانجوني وأرجوان وقرمز وبوص مبروم صنعة الطراز . أعمدته أربعة ، وقواعدها أربع '),
(11863, 'Exodus', 2, 27, 17, ' لكل أعمدة الدار حواليها قضبان من فضة . رززها من فضة ، وقواعدها من نحاس '),
(11864, 'Exodus', 2, 27, 18, ' طول الدار مئة ذراع ، وعرضها خمسون فخمسون ، وارتفاعها خمس أذرع من بوص مبروم ، وقواعدها من نحاس '),
(11865, 'Exodus', 2, 27, 19, ' جميع أواني المسكن في كل خدمته وجميع أوتاده وجميع أوتاد الدار من نحاس '),
(11866, 'Exodus', 2, 27, 20, ' وأنت تأمر بني إسرائيل أن يقدموا إليك زيت زيتون مرضوض نقيا للضوء لإصعاد السرج دائما '),
(11867, 'Exodus', 2, 27, 21, ' في خيمة الاجتماع ، خارج الحجاب الذي أمام الشهادة ، يرتبها هارون وبنوه من المساء إلى الصباح أمام الرب . فريضة دهرية في أجيالهم من بني إسرائيل '),
(11868, 'Exodus', 2, 28, 1, ' وقرب إليك هارون أخاك وبنيه معه من بين بني إسرائيل ليكهن لي . هارون ناداب وأبيهو ألعازار وإيثامار بني هارون '),
(11869, 'Exodus', 2, 28, 2, ' واصنع ثيابا مقدسة لهارون أخيك للمجد والبهاء '),
(11870, 'Exodus', 2, 28, 3, ' وتكلم جميع حكماء القلوب الذين ملأتهم روح حكمة ، أن يصنعوا ثياب هارون لتقديسه ليكهن لي '),
(11871, 'Exodus', 2, 28, 4, ' وهذه هي الثياب التي يصنعونها : صدرة ورداء وجبة وقميص مخرم وعمامة ومنطقة . فيصنعون ثيابا مقدسة لهارون أخيك ولبنيه ليكهن لي '),
(11872, 'Exodus', 2, 28, 5, ' وهم يأخذون الذهب والأسمانجوني والأرجوان والقرمز والبوص '),
(11873, 'Exodus', 2, 28, 6, ' فيصنعون الرداء من ذهب وأسمانجوني وأرجوان وقرمز وبوص مبروم صنعة حائك حاذق '),
(11874, 'Exodus', 2, 28, 7, ' يكون له كتفان موصولان في طرفيه ليتصل '),
(11875, 'Exodus', 2, 28, 8, ' وزنار شده الذي عليه يكون منه كصنعته . من ذهب وأسمانجوني وقرمز وبوص مبروم '),
(11876, 'Exodus', 2, 28, 9, ' وتأخذ حجري جزع وتنقش عليهما أسماء بني إسرائيل '),
(11877, 'Exodus', 2, 28, 10, ' ستة من أسمائهم على الحجر الواحد ، وأسماء الستة الباقين على الحجر الثاني حسب مواليدهم '),
(11878, 'Exodus', 2, 28, 11, ' صنعة نقاش الحجارة نقش الخاتم تنقش الحجرين على حسب أسماء بني إسرائيل . محاطين بطوقين من ذهب تصنعهما '),
(11879, 'Exodus', 2, 28, 12, ' وتضع الحجرين على كتفي الرداء حجري تذكار لبني إسرائيل . فيحمل هارون أسماءهم أمام الرب على كتفيه للتذكار '),
(11880, 'Exodus', 2, 28, 13, ' وتصنع طوقين من ذهب '),
(11881, 'Exodus', 2, 28, 14, ' وسلسلتين من ذهب نقي . مجدولتين تصنعهما صنعة الضفر ، وتجعل سلسلتي الضفائر في الطوقين '),
(11882, 'Exodus', 2, 28, 15, ' وتصنع صدرة قضاء . صنعة حائك حاذق كصنعة الرداء تصنعها . من ذهب وأسمانجوني وأرجوان وقرمز وبوص مبروم تصنعها '),
(11883, 'Exodus', 2, 28, 16, ' تكون مربعة مثنية ، طولها شبر وعرضها شبر '),
(11884, 'Exodus', 2, 28, 17, ' وترصع فيها ترصيع حجر أربعة صفوف حجارة . صف : عقيق أحمر وياقوت أصفر وزمرد ، الصف الأول '),
(11885, 'Exodus', 2, 28, 18, ' والصف الثاني : بهرمان وياقوت أزرق وعقيق أبيض '),
(11886, 'Exodus', 2, 28, 19, ' والصف الثالث : عين الهر ويشم وجمشت '),
(11887, 'Exodus', 2, 28, 20, ' والصف الرابع : زبرجد وجزع ويشب . تكون مطوقة بذهب في ترصيعها '),
(11888, 'Exodus', 2, 28, 21, ' وتكون الحجارة على أسماء بني إسرائيل ، اثني عشر على أسمائهم . كنقش الخاتم كل واحد على اسمه تكون للاثني عشر سبطا '),
(11889, 'Exodus', 2, 28, 22, ' وتصنع على الصدرة سلاسل مجدولة صنعة الضفر من ذهب نقي '),
(11890, 'Exodus', 2, 28, 23, ' وتصنع على الصدرة حلقتين من ذهب ، وتجعل الحلقتين على طرفي الصدرة '),
(11891, 'Exodus', 2, 28, 24, ' وتجعل ضفيرتي الذهب في الحلقتين على طرفي الصدرة '),
(11892, 'Exodus', 2, 28, 25, ' وتجعل طرفي الضفيرتين الآخرين في الطوقين ، وتجعلهما على كتفي الرداء إلى قدامه '),
(11893, 'Exodus', 2, 28, 26, ' وتصنع حلقتين من ذهب وتضعهما على طرفي الصدرة على حاشيتها التي إلى جهة الرداء من داخل '),
(11894, 'Exodus', 2, 28, 27, ' وتصنع حلقتين من ذهب ، وتجعلهما على كتفي الرداء من أسفل من قدامه عند وصله من فوق زنار الرداء '),
(11895, 'Exodus', 2, 28, 28, ' ويربطون الصدرة بحلقتيها إلى حلقتي الرداء بخيط من أسمانجوني لتكون على زنار الرداء ، ولا تنزع الصدرة عن الرداء '),
(11896, 'Exodus', 2, 28, 29, ' فيحمل هارون أسماء بني إسرائيل في صدرة القضاء على قلبه عند دخوله إلى القدس للتذكار أمام الرب دائما '),
(11897, 'Exodus', 2, 28, 30, ' وتجعل في صدرة القضاء الأوريم والتميم لتكون على قلب هارون عند دخوله أمام الرب . فيحمل هارون قضاء بني إسرائيل على قلبه أمام الرب دائما '),
(11898, 'Exodus', 2, 28, 31, ' وتصنع جبة الرداء كلها من أسمانجوني '),
(11899, 'Exodus', 2, 28, 32, ' وتكون فتحة رأسها في وسطها ، ويكون لفتحتها حاشية حواليها صنعة الحائك . كفتحة الدرع يكون لها . لا تشق '),
(11900, 'Exodus', 2, 28, 33, ' وتصنع على أذيالها رمانات من أسمانجوني وأرجوان وقرمز ، على أذيالها حواليها ، وجلاجل من ذهب بينها حواليها '),
(11901, 'Exodus', 2, 28, 34, ' جلجل ذهب ورمانة ، جلجل ذهب ورمانة ، على أذيال الجبة حواليها '),
(11902, 'Exodus', 2, 28, 35, ' فتكون على هارون للخدمة ليسمع صوتها عند دخوله إلى القدس أمام الرب ، وعند خروجه ، لئلا يموت '),
(11903, 'Exodus', 2, 28, 36, ' وتصنع صفيحة من ذهب نقي ، وتنقش عليها نقش خاتم : قدس للرب '),
(11904, 'Exodus', 2, 28, 37, ' وتضعها على خيط أسمانجوني لتكون على العمامة . إلى قدام العمامة تكون '),
(11905, 'Exodus', 2, 28, 38, ' فتكون على جبهة هارون ، فيحمل هارون إثم الأقداس التي يقدسها بنو إسرائيل ، جميع عطايا أقداسهم . وتكون على جبهته دائما للرضا عنهم أمام الرب '),
(11906, 'Exodus', 2, 28, 39, ' وتخرم القميص من بوص ، وتصنع العمامة من بوص ، والمنطقة تصنعها صنعة الطراز '),
(11907, 'Exodus', 2, 28, 40, ' ولبني هارون تصنع أقمصة ، وتصنع لهم مناطق ، وتصنع لهم قلانس للمجد والبهاء '),
(11908, 'Exodus', 2, 28, 41, ' وتلبس هارون أخاك إياها وبنيه معه ، وتمسحهم ، وتملأ أياديهم ، وتقدسهم ليكهنوا لي '),
(11909, 'Exodus', 2, 28, 42, ' وتصنع لهم سراويل من كتان لستر العورة . من الحقوين إلى الفخذين تكون '),
(11910, 'Exodus', 2, 28, 43, ' فتكون على هارون وبنيه عند دخولهم إلى خيمة الاجتماع ، أو عند اقترابهم إلى المذبح للخدمة في القدس ، لئلا يحملوا إثما ويموتوا . فريضة أبدية له ولنسله من بعده '),
(11911, 'Exodus', 2, 29, 1, ' وهذا ما تصنعه لهم لتقديسهم ليكهنوا لي : خذ ثورا واحدا ابن بقر ، وكبشين صحيحين '),
(11912, 'Exodus', 2, 29, 2, ' وخبز فطير ، وأقراص فطير ملتوتة بزيت ، ورقاق فطير مدهونة بزيت . من دقيق حنطة تصنعها '),
(11913, 'Exodus', 2, 29, 3, ' وتجعلها في سلة واحدة ، وتقدمها في السلة مع الثور والكبشين '),
(11914, 'Exodus', 2, 29, 4, ' وتقدم هارون وبنيه إلى باب خيمة الاجتماع وتغسلهم بماء '),
(11915, 'Exodus', 2, 29, 5, ' وتأخذ الثياب وتلبس هارون القميص وجبة الرداء والرداء والصدرة ، وتشده بزنار الرداء '),
(11916, 'Exodus', 2, 29, 6, ' وتضع العمامة على رأسه ، وتجعل الإكليل المقدس على العمامة '),
(11917, 'Exodus', 2, 29, 7, ' وتأخذ دهن المسحة وتسكبه على رأسه وتمسحه '),
(11918, 'Exodus', 2, 29, 8, ' وتقدم بنيه وتلبسهم أقمصة '),
(11919, 'Exodus', 2, 29, 9, ' وتنطقهم بمناطق ، هارون وبنيه ، وتشد لهم قلانس . فيكون لهم كهنوت فريضة أبدية . وتملأ يد هارون وأيدي بنيه '),
(11920, 'Exodus', 2, 29, 10, ' وتقدم الثور إلى قدام خيمة الاجتماع ، فيضع هارون وبنوه أيديهم على رأس الثور '),
(11921, 'Exodus', 2, 29, 11, ' فتذبح الثور أمام الرب عند باب خيمة الاجتماع '),
(11922, 'Exodus', 2, 29, 12, ' وتأخذ من دم الثور وتجعله على قرون المذبح بإصبعك ، وسائر الدم تصبه إلى أسفل المذبح '),
(11923, 'Exodus', 2, 29, 13, ' وتأخذ كل الشحم الذي يغشي الجوف ، وزيادة الكبد والكليتين والشحم الذي عليهما ، وتوقدها على المذبح '),
(11924, 'Exodus', 2, 29, 14, ' وأما لحم الثور وجلده وفرثه فتحرقها بنار خارج المحلة . هو ذبيحة خطية '),
(11925, 'Exodus', 2, 29, 15, ' وتأخذ الكبش الواحد ، فيضع هارون وبنوه أيديهم على رأس الكبش '),
(11926, 'Exodus', 2, 29, 16, ' فتذبح الكبش وتأخذ دمه وترشه على المذبح من كل ناحية '),
(11927, 'Exodus', 2, 29, 17, ' وتقطع الكبش إلى قطعه ، وتغسل جوفه وأكارعه وتجعلها على قطعه وعلى رأسه '),
(11928, 'Exodus', 2, 29, 18, ' وتوقد كل الكبش على المذبح . هو محرقة للرب . رائحة سرور ، وقود هو للرب '),
(11929, 'Exodus', 2, 29, 19, ' وتأخذ الكبش الثاني ، فيضع هارون وبنوه أيديهم على رأس الكبش '),
(11930, 'Exodus', 2, 29, 20, ' فتذبح الكبش وتأخذ من دمه وتجعل على شحمة أذن هارون ، وعلى شحم آذان بنيه اليمنى ، وعلى أباهم أيديهم اليمنى ، وعلى أباهم أرجلهم اليمنى . وترش الدم على المذبح من كل ناحية '),
(11931, 'Exodus', 2, 29, 21, ' وتأخذ من الدم الذي على المذبح ومن دهن المسحة ، وتنضح على هارون وثيابه ، وعلى بنيه وثياب بنيه معه ، فيتقدس هو وثيابه وبنوه وثياب بنيه معه '),
(11932, 'Exodus', 2, 29, 22, ' ثم تأخذ من الكبش : الشحم والإلية والشحم الذي يغشي الجوف ، وزيادة الكبد والكليتين ، والشحم الذي عليهما ، والساق اليمنى . فإنه كبش ملء '),
(11933, 'Exodus', 2, 29, 23, ' ورغيفا واحدا من الخبز ، وقرصا واحدا من الخبز بزيت ، ورقاقة واحدة من سلة الفطير التي أمام الرب '),
(11934, 'Exodus', 2, 29, 24, ' وتضع الجميع في يدي هارون وفي أيدي بنيه ، وترددها ترديدا أمام الرب '),
(11935, 'Exodus', 2, 29, 25, ' ثم تأخذها من أيديهم وتوقدها على المذبح فوق المحرقة رائحة سرور أمام الرب . وقود هو للرب '),
(11936, 'Exodus', 2, 29, 26, ' ثم تأخذ القص من كبش الملء الذي لهارون ، وتردده ترديدا أمام الرب ، فيكون لك نصيبا '),
(11937, 'Exodus', 2, 29, 27, ' وتقدس قص الترديد وساق الرفيعة الذي ردد والذي رفع من كبش الملء مما لهارون ولبنيه '),
(11938, 'Exodus', 2, 29, 28, ' فيكونان لهارون وبنيه فريضة أبدية من بني إسرائيل لأنهما رفيعة . ويكونان رفيعة من بني إسرائيل من ذبائح سلامتهم ، رفيعتهم للرب '),
(11939, 'Exodus', 2, 29, 29, ' والثياب المقدسة التي لهارون تكون لبنيه بعده ، ليمسحوا فيها ، ولتملأ فيها أيديهم '),
(11940, 'Exodus', 2, 29, 30, ' سبعة أيام يلبسها الكاهن الذي هو عوض عنه من بنيه ، الذي يدخل خيمة الاجتماع ليخدم في القدس '),
(11941, 'Exodus', 2, 29, 31, ' وأما كبش الملء فتأخذه وتطبخ لحمه في مكان مقدس '),
(11942, 'Exodus', 2, 29, 32, ' فيأكل هارون وبنوه لحم الكبش والخبز الذي في السلة عند باب خيمة الاجتماع '),
(11943, 'Exodus', 2, 29, 33, ' يأكلها الذين كفر بها عنهم لملء أيديهم لتقديسهم . وأما الأجنبي فلا يأكل لأنها مقدسة '),
(11944, 'Exodus', 2, 29, 34, ' وإن بقي شيء من لحم الملء أو من الخبز إلى الصباح ، تحرق الباقي بالنار . لا يؤكل لأنه مقدس '),
(11945, 'Exodus', 2, 29, 35, ' وتصنع لهارون وبنيه هكذا بحسب كل ما أمرتك . سبعة أيام تملأ أيديهم '),
(11946, 'Exodus', 2, 29, 36, ' وتقدم ثور خطية كل يوم لأجل الكفارة . وتطهر المذبح بتكفيرك عليه ، وتمسحه لتقديسه '),
(11947, 'Exodus', 2, 29, 37, ' سبعة أيام تكفر على المذبح وتقدسه ، فيكون المذبح قدس أقداس . كل ما مس المذبح يكون مقدسا '),
(11948, 'Exodus', 2, 29, 38, ' وهذا ما تقدمه على المذبح : خروفان حوليان كل يوم دائما '),
(11949, 'Exodus', 2, 29, 39, ' الخروف الواحد تقدمه صباحا ، والخروف الثاني تقدمه في العشية '),
(11950, 'Exodus', 2, 29, 40, ' وعشر من دقيق ملتوت بربع الهين من زيت الرض ، وسكيب ربع الهين من الخمر للخروف الواحد '),
(11951, 'Exodus', 2, 29, 41, ' والخروف الثاني تقدمه في العشية . مثل تقدمة الصباح وسكيبه تصنع له . رائحة سرور ، وقود للرب '),
(11952, 'Exodus', 2, 29, 42, ' محرقة دائمة في أجيالكم عند باب خيمة الاجتماع أمام الرب ، حيث أجتمع بكم لأكلمك هناك '),
(11953, 'Exodus', 2, 29, 43, ' وأجتمع هناك ببني إسرائيل فيقدس بمجدي '),
(11954, 'Exodus', 2, 29, 44, ' وأقدس خيمة الاجتماع والمذبح ، وهارون وبنوه أقدسهم لكي يكهنوا لي '),
(11955, 'Exodus', 2, 29, 45, ' وأسكن في وسط بني إسرائيل وأكون لهم إلها '),
(11956, 'Exodus', 2, 29, 46, ' فيعلمون أني أنا الرب إلههم الذي أخرجهم من أرض مصر لأسكن في وسطهم . أنا الرب إلههم '),
(11957, 'Exodus', 2, 30, 1, ' وتصنع مذبحا لإيقاد البخور . من خشب السنط تصنعه '),
(11958, 'Exodus', 2, 30, 2, ' طوله ذراع وعرضه ذراع . مربعا يكون . وارتفاعه ذراعان . منه تكون قرونه '),
(11959, 'Exodus', 2, 30, 3, ' وتغشيه بذهب نقي : سطحه وحيطانه حواليه وقرونه . وتصنع له إكليلا من ذهب حواليه '),
(11960, 'Exodus', 2, 30, 4, ' وتصنع له حلقتين من ذهب تحت إكليله على جانبيه . على الجانبين تصنعهما ، لتكونا بيتين لعصوين لحمله بهما '),
(11961, 'Exodus', 2, 30, 5, ' وتصنع العصوين من خشب السنط وتغشيهما بذهب '),
(11962, 'Exodus', 2, 30, 6, ' وتجعله قدام الحجاب الذي أمام تابوت الشهادة . قدام الغطاء الذي على الشهادة حيث أجتمع بك '),
(11963, 'Exodus', 2, 30, 7, ' فيوقد عليه هارون بخورا عطرا كل صباح ، حين يصلح السرج يوقده '),
(11964, 'Exodus', 2, 30, 8, ' وحين يصعد هارون السرج في العشية يوقده . بخورا دائما أمام الرب في أجيالكم '),
(11965, 'Exodus', 2, 30, 9, ' لا تصعدوا عليه بخورا غريبا ولا محرقة أو تقدمة ، ولا تسكبوا عليه سكيبا '),
(11966, 'Exodus', 2, 30, 10, ' ويصنع هارون كفارة على قرونه مرة في السنة . من دم ذبيحة الخطية التي للكفارة مرة في السنة يصنع كفارة عليه في أجيالكم . قدس أقداس هو للرب '),
(11967, 'Exodus', 2, 30, 11, ' وكلم الرب موسى قائلا '),
(11968, 'Exodus', 2, 30, 12, ' إذا أخذت كمية بني إسرائيل بحسب المعدودين منهم ، يعطون كل واحد فدية نفسه للرب عندما تعدهم ، لئلا يصير فيهم وبأ عندما تعدهم '),
(11969, 'Exodus', 2, 30, 13, ' هذا ما يعطيه كل من اجتاز إلى المعدودين : نصف الشاقل بشاقل القدس . الشاقل هو عشرون جيرة . نصف الشاقل تقدمة للرب '),
(11970, 'Exodus', 2, 30, 14, ' كل من اجتاز إلى المعدودين من ابن عشرين سنة فصاعدا يعطي تقدمة للرب '),
(11971, 'Exodus', 2, 30, 15, ' الغني لا يكثر والفقير لا يقلل عن نصف الشاقل حين تعطون تقدمة الرب للتكفير عن نفوسكم '),
(11972, 'Exodus', 2, 30, 16, ' وتأخذ فضة الكفارة من بني إسرائيل ، وتجعلها لخدمة خيمة الاجتماع . فتكون لبني إسرائيل تذكارا أمام الرب للتكفير عن نفوسكم '),
(11973, 'Exodus', 2, 30, 17, ' وكلم الرب موسى قائلا '),
(11974, 'Exodus', 2, 30, 18, ' وتصنع مرحضة من نحاس ، وقاعدتها من نحاس ، للاغتسال . وتجعلها بين خيمة الاجتماع والمذبح ، وتجعل فيها ماء '),
(11975, 'Exodus', 2, 30, 19, ' فيغسل هارون وبنوه أيديهم وأرجلهم منها '),
(11976, 'Exodus', 2, 30, 20, ' عند دخولهم إلى خيمة الاجتماع يغسلون بماء لئلا يموتوا ، أو عند اقترابهم إلى المذبح للخدمة ليوقدوا وقودا للرب '),
(11977, 'Exodus', 2, 30, 21, ' يغسلون أيديهم وأرجلهم لئلا يموتوا . ويكون لهم فريضة أبدية له ولنسله في أجيالهم '),
(11978, 'Exodus', 2, 30, 22, ' وكلم الرب موسى قائلا '),
(11979, 'Exodus', 2, 30, 23, ' وأنت تأخذ لك أفخر الأطياب : مرا قاطرا خمس مئة شاقل ، وقرفة عطرة نصف ذلك : مئتين وخمسين ، وقصب الذريرة مئتين وخمسين '),
(11980, 'Exodus', 2, 30, 24, ' وسليخة خمس مئة بشاقل القدس ، ومن زيت الزيتون هينا '),
(11981, 'Exodus', 2, 30, 25, ' وتصنعه دهنا مقدسا للمسحة . عطر عطارة صنعة العطار . دهنا مقدسا للمسحة يكون '),
(11982, 'Exodus', 2, 30, 26, ' وتمسح به خيمة الاجتماع ، وتابوت الشهادة '),
(11983, 'Exodus', 2, 30, 27, ' والمائدة وكل آنيتها ، والمنارة وآنيتها ، ومذبح البخور '),
(11984, 'Exodus', 2, 30, 28, ' ومذبح المحرقة وكل آنيته ، والمرحضة وقاعدتها '),
(11985, 'Exodus', 2, 30, 29, ' وتقدسها فتكون قدس أقداس . كل ما مسها يكون مقدسا '),
(11986, 'Exodus', 2, 30, 30, ' وتمسح هارون وبنيه وتقدسهم ليكهنوا لي '),
(11987, 'Exodus', 2, 30, 31, ' وتكلم بني إسرائيل قائلا : يكون هذا لي دهنا مقدسا للمسحة في أجيالكم '),
(11988, 'Exodus', 2, 30, 32, ' على جسد إنسان لا يسكب ، وعلى مقاديره لا تصنعوا مثله . مقدس هو ، ويكون مقدسا عندكم '),
(11989, 'Exodus', 2, 30, 33, ' كل من ركب مثله ومن جعل منه على أجنبي يقطع من شعبه '),
(11990, 'Exodus', 2, 30, 34, ' وقال الرب لموسى : خذ لك أعطارا : ميعة وأظفارا وقنة عطرة ولبانا نقيا . تكون أجزاء متساوية '),
(11991, 'Exodus', 2, 30, 35, ' فتصنعها بخورا عطرا صنعة العطار ، مملحا نقيا مقدسا '),
(11992, 'Exodus', 2, 30, 36, ' وتسحق منه ناعما ، وتجعل منه قدام الشهادة في خيمة الاجتماع حيث أجتمع بك . قدس أقداس يكون عندكم '),
(11993, 'Exodus', 2, 30, 37, ' والبخور الذي تصنعه على مقاديره لا تصنعوا لأنفسكم . يكون عندك مقدسا للرب '),
(11994, 'Exodus', 2, 30, 38, ' كل من صنع مثله ليشمه يقطع من شعبه '),
(11995, 'Exodus', 2, 31, 1, ' وكلم الرب موسى قائلا '),
(11996, 'Exodus', 2, 31, 2, ' انظر . قد دعوت بصلئيل بن أوري بن حور من سبط يهوذا باسمه '),
(11997, 'Exodus', 2, 31, 3, ' وملأته من روح الله بالحكمة والفهم والمعرفة وكل صنعة '),
(11998, 'Exodus', 2, 31, 4, ' لاختراع مخترعات ليعمل في الذهب والفضة والنحاس '),
(11999, 'Exodus', 2, 31, 5, ' ونقش حجارة للترصيع ، ونجارة الخشب ، ليعمل في كل صنعة '),
(12000, 'Exodus', 2, 31, 6, ' وها أنا قد جعلت معه أهوليآب بن أخيساماك من سبط دان . وفي قلب كل حكيم القلب جعلت حكمة ، ليصنعوا كل ما أمرتك '),
(12001, 'Exodus', 2, 31, 7, ' خيمة الاجتماع ، وتابوت الشهادة ، والغطاء الذي عليه ، وكل آنية الخيمة '),
(12002, 'Exodus', 2, 31, 8, ' والمائدة وآنيتها ، والمنارة الطاهرة وكل آنيتها ، ومذبح البخور '),
(12003, 'Exodus', 2, 31, 9, ' ومذبح المحرقة وكل آنيته ، والمرحضة وقاعدتها '),
(12004, 'Exodus', 2, 31, 10, ' والثياب المنسوجة ، والثياب المقدسة لهارون الكاهن وثياب بنيه للكهانة '),
(12005, 'Exodus', 2, 31, 11, ' ودهن المسحة والبخور العطر للقدس . حسب كل ما أمرتك به يصنعون '),
(12006, 'Exodus', 2, 31, 12, ' وكلم الرب موسى قائلا '),
(12007, 'Exodus', 2, 31, 13, ' وأنت تكلم بني إسرائيل قائلا : سبوتي تحفظونها ، لأنه علامة بيني وبينكم في أجيالكم لتعلموا أني أنا الرب الذي يقدسكم '),
(12008, 'Exodus', 2, 31, 14, ' فتحفظون السبت لأنه مقدس لكم . من دنسه يقتل قتلا . إن كل من صنع فيه عملا تقطع تلك النفس من بين شعبها '),
(12009, 'Exodus', 2, 31, 15, ' ستة أيام يصنع عمل ، وأما اليوم السابع ففيه سبت عطلة مقدس للرب . كل من صنع عملا في يوم السبت يقتل قتلا '),
(12010, 'Exodus', 2, 31, 16, ' فيحفظ بنو إسرائيل السبت ليصنعوا السبت في أجيالهم عهدا أبديا '),
(12011, 'Exodus', 2, 31, 17, ' هو بيني وبين بني إسرائيل علامة إلى الأبد . لأنه في ستة أيام صنع الرب السماء والأرض ، وفي اليوم السابع استراح وتنفس '),
(12012, 'Exodus', 2, 31, 18, ' ثم أعطى موسى عند فراغه من الكلام معه في جبل سيناء لوحي الشهادة : لوحي حجر مكتوبين بإصبع الله '),
(12013, 'Exodus', 2, 32, 1, ' ولما رأى الشعب أن موسى أبطأ في النزول من الجبل ، اجتمع الشعب على هارون وقالوا له : قم اصنع لنا آلهة تسير أمامنا ، لأن هذا موسى الرجل الذي أصعدنا من أرض مصر ، لا نعلم ماذا أصابه '),
(12014, 'Exodus', 2, 32, 2, ' فقال لهم هارون : انزعوا أقراط الذهب التي في آذان نسائكم وبنيكم وبناتكم واتوني بها '),
(12015, 'Exodus', 2, 32, 3, ' فنزع كل الشعب أقراط الذهب التي في آذانهم وأتوا بها إلى هارون '),
(12016, 'Exodus', 2, 32, 4, ' فأخذ ذلك من أيديهم وصوره بالإزميل ، وصنعه عجلا مسبوكا . فقالوا : هذه آلهتك يا إسرائيل التي أصعدتك من أرض مصر '),
(12017, 'Exodus', 2, 32, 5, ' فلما نظر هارون بنى مذبحا أمامه ، ونادى هارون وقال : غدا عيد للرب '),
(12018, 'Exodus', 2, 32, 6, ' فبكروا في الغد وأصعدوا محرقات وقدموا ذبائح سلامة . وجلس الشعب للأكل والشرب ثم قاموا للعب '),
(12019, 'Exodus', 2, 32, 7, ' فقال الرب لموسى : اذهب انزل . لأنه قد فسد شعبك الذي أصعدته من أرض مصر '),
(12020, 'Exodus', 2, 32, 8, ' زاغوا سريعا عن الطريق الذي أوصيتهم به . صنعوا لهم عجلا مسبوكا ، وسجدوا له وذبحوا له وقالوا : هذه آلهتك يا إسرائيل التي أصعدتك من أرض مصر '),
(12021, 'Exodus', 2, 32, 9, ' وقال الرب لموسى : رأيت هذا الشعب وإذا هو شعب صلب الرقبة '),
(12022, 'Exodus', 2, 32, 10, ' فالآن اتركني ليحمى غضبي عليهم وأفنيهم ، فأصيرك شعبا عظيما '),
(12023, 'Exodus', 2, 32, 11, ' فتضرع موسى أمام الرب إلهه ، وقال : لماذا يارب يحمى غضبك على شعبك الذي أخرجته من أرض مصر بقوة عظيمة ويد شديدة '),
(12024, 'Exodus', 2, 32, 12, ' لماذا يتكلم المصريون قائلين : أخرجهم بخبث ليقتلهم في الجبال ، ويفنيهم عن وجه الأرض ؟ ارجع عن حمو غضبك ، واندم على الشر بشعبك '),
(12025, 'Exodus', 2, 32, 13, ' اذكر إبراهيم وإسحاق وإسرائيل عبيدك الذين حلفت لهم بنفسك وقلت لهم : أكثر نسلكم كنجوم السماء ، وأعطي نسلكم كل هذه الأرض التي تكلمت عنها فيملكونها إلى الأبد '),
(12026, 'Exodus', 2, 32, 14, ' فندم الرب على الشر الذي قال إنه يفعله بشعبه '),
(12027, 'Exodus', 2, 32, 15, ' فانصرف موسى ونزل من الجبل ولوحا الشهادة في يده : لوحان مكتوبان على جانبيهما . من هنا ومن هنا كانا مكتوبين '),
(12028, 'Exodus', 2, 32, 16, ' واللوحان هما صنعة الله ، والكتابة كتابة الله منقوشة على اللوحين '),
(12029, 'Exodus', 2, 32, 17, ' وسمع يشوع صوت الشعب في هتافه فقال لموسى : صوت قتال في المحلة '),
(12030, 'Exodus', 2, 32, 18, ' فقال : ليس صوت صياح النصرة ولا صوت صياح الكسرة ، بل صوت غناء أنا سامع '),
(12031, 'Exodus', 2, 32, 19, ' وكان عندما اقترب إلى المحلة أنه أبصر العجل والرقص ، فحمي غضب موسى ، وطرح اللوحين من يديه وكسرهما في أسفل الجبل '),
(12032, 'Exodus', 2, 32, 20, ' ثم أخذ العجل الذي صنعوا وأحرقه بالنار ، وطحنه حتى صار ناعما ، وذراه على وجه الماء ، وسقى بني إسرائيل '),
(12033, 'Exodus', 2, 32, 21, ' وقال موسى لهارون : ماذا صنع بك هذا الشعب حتى جلبت عليه خطية عظيمة '),
(12034, 'Exodus', 2, 32, 22, ' فقال هارون : لا يحم غضب سيدي . أنت تعرف الشعب أنه في شر '),
(12035, 'Exodus', 2, 32, 23, ' فقالوا لي : اصنع لنا آلهة تسير أمامنا ، لأن هذا موسى الرجل الذي أصعدنا من أرض مصر ، لا نعلم ماذا أصابه '),
(12036, 'Exodus', 2, 32, 24, ' فقلت لهم : من له ذهب فلينزعه ويعطني . فطرحته في النار فخرج هذا العجل '),
(12037, 'Exodus', 2, 32, 25, ' ولما رأى موسى الشعب أنه معرى لأن هارون كان قد عراه للهزء بين مقاوميه '),
(12038, 'Exodus', 2, 32, 26, ' وقف موسى في باب المحلة ، وقال : من للرب فإلي . فاجتمع إليه جميع بني لاوي '),
(12039, 'Exodus', 2, 32, 27, ' فقال لهم : هكذا قال الرب إله إسرائيل : ضعوا كل واحد سيفه على فخذه ومروا وارجعوا من باب إلى باب في المحلة ، واقتلوا كل واحد أخاه وكل واحد صاحبه وكل واحد قريبه '),
(12040, 'Exodus', 2, 32, 28, ' ففعل بنو لاوي بحسب قول موسى . ووقع من الشعب في ذلك اليوم نحو ثلاثة آلاف رجل '),
(12041, 'Exodus', 2, 32, 29, ' وقال موسى : املأوا أيديكم اليوم للرب ، حتى كل واحد بابنه وبأخيه ، فيعطيكم اليوم بركة '),
(12042, 'Exodus', 2, 32, 30, ' وكان في الغد أن موسى قال للشعب : أنتم قد أخطأتم خطية عظيمة ، فأصعد الآن إلى الرب لعلي أكفر خطيتكم '),
(12043, 'Exodus', 2, 32, 31, ' فرجع موسى إلى الرب ، وقال : آه ، قد أخطأ هذا الشعب خطية عظيمة وصنعوا لأنفسهم آلهة من ذهب '),
(12044, 'Ezekiel', 26, 1, 1, ' كان في سنة الثلاثين ، في الشهر الرابع ، في الخامس من الشهر ، وأنا بين المسبيين عند نهر خابور ، أن السماوات انفتحت ، فرأيت رؤى الله '),
(12045, 'Ezekiel', 26, 1, 2, ' في الخامس من الشهر ، وهي السنة الخامسة من سبي يوياكين الملك '),
(12046, 'Ezekiel', 26, 1, 3, ' صار كلام الرب إلى حزقيال الكاهن ابن بوزي في أرض الكلدانيين عند نهر خابور . وكانت عليه هناك يد الرب '),
(12047, 'Ezekiel', 26, 1, 4, ' فنظرت وإذا بريح عاصفة جاءت من الشمال . سحابة عظيمة ونار متواصلة وحولها لمعان ، ومن وسطها كمنظر النحاس اللامع من وسط النار '),
(12048, 'Ezekiel', 26, 1, 5, ' ومن وسطها شبه أربعة حيوانات . وهذا منظرها : لها شبه إنسان '),
(12049, 'Ezekiel', 26, 4, 15, ' فقال لي : انظر . قد جعلت لك خثي البقر بدل خرء الإنسان ، فتصنع خبزك عليه '),
(12050, 'Ezekiel', 26, 4, 16, ' وقال لي : يا ابن آدم ، هأنذا أكسر قوام الخبز في أورشليم ، فيأكلون الخبز بالوزن وبالغم ، ويشربون الماء بالكيل وبالحيرة '),
(12051, 'Ezekiel', 26, 4, 17, ' لكي يعوزهم الخبز والماء ، ويتحيروا الرجل وأخوه ويفنوا بإثمهم '),
(12052, 'Ezekiel', 26, 5, 1, ' وأنت يا ابن آدم ، فخذ لنفسك سكينا حادا ، موسى الحلاق تأخذ لنفسك ، وأمررها على رأسك وعلى لحيتك . وخذ لنفسك ميزانا للوزن واقسمه '),
(12053, 'Ezekiel', 26, 5, 2, ' وأحرق بالنار ثلثه في وسط المدينة إذا تمت أيام الحصار . وخذ ثلثا واضربه بالسيف حواليه ، وذر ثلثا إلى الريح ، وأنا أستل سيفا وراءهم '),
(12054, 'Ezekiel', 26, 5, 3, ' وخذ منه قليلا بالعدد وصره في أذيالك '),
(12055, 'Ezekiel', 26, 5, 4, ' وخذ منه أيضا وألقه في وسط النار ، وأحرقه بالنار . منه تخرج نار على كل بيت إسرائيل '),
(12056, 'Ezekiel', 26, 5, 5, ' هكذا قال السيد الرب : هذه أورشليم . في وسط الشعوب قد أقمتها وحواليها الأراضي '),
(12057, 'Ezekiel', 26, 5, 6, ' فخالفت أحكامي بأشر من الأمم ، وفرائضي بأشر من الأراضي التي حواليها ، لأن أحكامي رفضوها وفرائضي لم يسلكوا فيها '),
(12058, 'Ezekiel', 26, 5, 7, ' لأجل ذلك هكذا قال السيد الرب : من أجل أنكم ضججتم أكثر من الأمم التي حواليكم ، ولم تسلكوا في فرائضي ، ولم تعملوا حسب أحكامي ، ولا عملتم حسب أحكام الأمم التي حواليكم '),
(12059, 'Ezekiel', 26, 5, 8, ' لذلك هكذا قال السيد الرب : ها إني أنا أيضا عليك ، وسأجري في وسطك أحكاما أمام عيون الأمم '),
(12060, 'Ezekiel', 26, 5, 9, ' وأفعل بك ما لم أفعل ، وما لن أفعل مثله بعد ، بسبب كل أرجاسك '),
(12061, 'Ezekiel', 26, 5, 10, ' لأجل ذلك تأكل الآباء الأبناء في وسطك ، والأبناء يأكلون آباءهم . وأجري فيك أحكاما ، وأذري بقيتك كلها في كل ريح '),
(12062, 'Ezekiel', 26, 5, 11, ' من أجل ذلك حي أنا ، يقول السيد الرب ، من أجل أنك قد نجست مقدسي بكل مكرهاتك وبكل أرجاسك ، فأنا أيضا أجز ولا تشفق عيني ، وأنا أيضا لا أعفو '),
(12063, 'Ezekiel', 26, 5, 12, ' ثلثك يموت بالوبإ ، وبالجوع يفنون في وسطك . وثلث يسقط بالسيف من حولك ، وثلث أذريه في كل ريح ، وأستل سيفا وراءهم '),
(12064, 'Ezekiel', 26, 5, 13, ' وإذا تم غضبي وأحللت سخطي عليهم وتشفيت ، يعلمون أني أنا الرب تكلمت في غيرتي ، إذا أتممت سخطي فيهم '),
(12065, 'Ezekiel', 26, 5, 14, ' وأجعلك خرابا وعارا بين الأمم التي حواليك أمام عيني كل عابر '),
(12066, 'Ezekiel', 26, 5, 15, ' فتكونين عارا ولعنة وتأديبا ودهشا للأمم التي حواليك ، إذا أجريت فيك أحكاما بغضب وبسخط وبتوبيخات حامية . أنا الرب تكلمت '),
(12067, 'Ezekiel', 26, 5, 16, ' إذا أرسلت عليهم سهام الجوع الشريرة التي تكون للخراب التي أرسلها لخرابكم ، وأزيد الجوع عليكم ، وأكسر لكم قوام الخبز '),
(12068, 'Ezekiel', 26, 5, 17, ' وإذا أرسلت عليكم الجوع والوحوش الرديئة فتثكلك ، ويعبر فيك الوبأ والدم ، وأجلب عليك سيفا . أنا الرب تكلمت '),
(12069, 'Ezekiel', 26, 6, 1, ' وكان إلي كلام الرب قائلا '),
(12070, 'Ezekiel', 26, 6, 2, ' يا ابن آدم ، اجعل وجهك نحو جبال إسرائيل وتنبأ عليها '),
(12071, 'Ezekiel', 26, 6, 3, ' وقل : يا جبال إسرائيل ، اسمعي كلمة السيد الرب . هكذا قال السيد الرب للجبال وللآكام ، للأودية وللأوطئة : هأنذا أنا جالب عليكم سيفا ، وأبيد مرتفعاتكم '),
(12072, 'Ezekiel', 26, 6, 4, ' فتخرب مذابحكم ، وتتكسر شمساتكم ، وأطرح قتلاكم قدام أصنامكم '),
(12073, 'Ezekiel', 26, 6, 5, ' وأضع جثث بني إسرائيل قدام أصنامهم ، وأذري عظامكم حول مذابحكم '),
(12074, 'Ezekiel', 26, 6, 6, ' في كل مساكنكم تقفر المدن ، وتخرب المرتفعات ، لكي تقفر وتخرب مذابحكم ، وتنكسر وتزول أصنامكم ، وتقطع شمساتكم ، وتمحى أعمالكم '),
(12075, 'Ezekiel', 26, 6, 7, ' وتسقط القتلى في وسطكم ، فتعلمون أني أنا الرب '),
(12076, 'Ezekiel', 26, 6, 8, ' وأبقي بقية ، إذ يكون لكم ناجون من السيف بين الأمم عند تذريكم في الأراضي '),
(12077, 'Ezekiel', 26, 6, 9, ' والناجون منكم يذكرونني بين الأمم الذين يسبون إليهم ، إذا كسرت قلبهم الزاني الذي حاد عني ، وعيونهم الزانية وراء أصنامهم ، ومقتوا أنفسهم لأجل الشرور التي فعلوها في كل رجاساتهم '),
(12078, 'Ezekiel', 26, 6, 10, ' ويعلمون أني أنا الرب ، لم أقل باطلا إني أفعل بهم هذا الشر '),
(12079, 'Ezekiel', 26, 6, 11, ' هكذا قال السيد الرب : اضرب بيدك واخبط برجلك ، وقل : آه على كل رجاسات بيت إسرائيل الشريرة ، حتى يسقطوا بالسيف وبالجوع وبالوبإ '),
(12080, 'Ezekiel', 26, 6, 12, ' البعيد يموت بالوبإ ، والقريب يسقط بالسيف ، والباقي والمنحصر يموت بالجوع ، فأتمم غضبي عليهم '),
(12081, 'Ezekiel', 26, 6, 13, ' فتعلمون أني أنا الرب ، إذا كانت قتلاهم وسط أصنامهم حول مذابحهم على كل أكمة عالية ، وفي رؤوس كل الجبال ، وتحت كل شجرة خضراء ، وتحت كل بلوطة غبياء ، الموضع الذي قربوا فيه رائحة سرور لكل أصنامهم '),
(12082, 'Ezekiel', 26, 6, 14, ' وأمد يدي عليهم ، وأصير الأرض مقفرة وخربة من القفر إلى دبلة في كل مساكنهم ، فيعلمون أني أنا الرب '),
(12083, 'Ezekiel', 26, 7, 1, ' وكان إلي كلام الرب قائلا '),
(12084, 'Ezekiel', 26, 7, 2, ' وأنت يا ابن آدم ، فهكذا قال السيد الرب لأرض إسرائيل : نهاية قد جاءت النهاية على زوايا الأرض الأربع '),
(12085, 'Ezekiel', 26, 7, 3, ' الآن النهاية عليك ، وأرسل غضبي عليك ، وأحكم عليك كطرقك ، وأجلب عليك كل رجاساتك '),
(12086, 'Ezekiel', 26, 7, 4, ' فلا تشفق عليك عيني ، ولا أعفو ، بل أجلب عليك طرقك وتكون رجاساتك في وسطك ، فتعلمون أني أنا الرب '),
(12087, 'Ezekiel', 26, 7, 5, ' هكذا قال السيد الرب : شر شر وحيد هوذا قد أتى '),
(12088, 'Ezekiel', 26, 7, 6, ' نهاية قد جاءت . جاءت النهاية . انتبهت إليك . ها هي قد جاءت '),
(12089, 'Ezekiel', 26, 7, 7, ' انتهى الدور إليك أيها الساكن في الأرض . بلغ الوقت . اقترب يوم اضطراب ، لا هتاف الجبال '),
(12090, 'Ezekiel', 26, 7, 8, ' الآن عن قريب أصب رجزي عليك ، وأتمم سخطي عليك ، وأحكم عليك كطرقك ، وأجلب عليك كل رجاساتك '),
(12091, 'Ezekiel', 26, 7, 9, ' فلا تشفق عيني ، ولا أعفو ، بل أجلب عليك كطرقك ، ورجاساتك تكون في وسطك ، فتعلمون أني أنا الرب الضارب '),
(12092, 'Ezekiel', 26, 7, 10, ' ها هوذا اليوم ، ها هوذا قد جاء دارت الدائرة . أزهرت العصا . أفرخت الكبرياء '),
(12093, 'Ezekiel', 26, 7, 11, ' قام الظلم إلى عصا الشر . لا يبقى منهم ولا من ثروتهم ولا من ضجيجهم ، ولا نوح عليهم '),
(12094, 'Ezekiel', 26, 7, 12, ' قد جاء الوقت . بلغ اليوم . فلا يفرحن الشاري ، ولا يحزنن البائع ، لأن الغضب على كل جمهورهم '),
(12095, 'Ezekiel', 26, 7, 13, ' لأن البائع لن يعود إلى المبيع ، وإن كانوا بعد بين الأحياء . لأن الرؤيا على كل جمهورها فلا يعود ، والإنسان بإثمه لا يشدد حياته ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(12096, 'Ezekiel', 26, 7, 14, ' قد نفخوا في البوق وأعدوا الكل ، ولا ذاهب إلى القتال ، لأن غضبي على كل جمهورهم '),
(12097, 'Ezekiel', 26, 7, 15, ' السيف من خارج ، والوبأ والجوع من داخل . الذي هو في الحقل يموت بالسيف ، والذي هو في المدينة يأكله الجوع والوبأ '),
(12098, 'Ezekiel', 26, 7, 16, ' وينفلت منهم منفلتون ويكونون على الجبال كحمام الأوطئة . كلهم يهدرون كل واحد على إثمه '),
(12099, 'Ezekiel', 26, 7, 17, ' كل الأيدي ترتخي ، وكل الركب تصير ماء '),
(12100, 'Ezekiel', 26, 7, 18, ' ويتنطقون بالمسح ويغشاهم رعب ، وعلى جميع الوجوه خزي ، وعلى جميع رؤوسهم قرع '),
(12101, 'Ezekiel', 26, 7, 19, ' يلقون فضتهم في الشوارع ، وذهبهم يكون لنجاسة . لا تستطيع فضتهم وذهبهم إنقاذهم في يوم غضب الرب . لا يشبعون منهما أنفسهم ، ولا يملأون جوفهم ، لأنهما صارا معثرة إثمهم '),
(12102, 'Ezekiel', 26, 7, 20, ' أما بهجة زينته فجعلها للكبرياء . جعلوا فيها أصنام مكرهاتهم ، رجاساتهم ، لأجل ذلك جعلتها لهم نجاسة '),
(12103, 'Ezekiel', 26, 7, 21, ' أسلمها إلى أيدي الغرباء للنهب ، وإلى أشرار الأرض سلبا فينجسونها '),
(12104, 'Ezekiel', 26, 7, 22, ' وأحول وجهي عنهم فينجسون سري ، ويدخله المعتنفون وينجسونه '),
(12105, 'Ezekiel', 26, 7, 23, ' اصنع السلسلة لأن الأرض قد امتلأت من أحكام الدم ، والمدينة امتلأت من الظلم '),
(12106, 'Ezekiel', 26, 7, 24, ' فآتي بأشر الأمم فيرثون بيوتهم ، وأبيد كبرياء الأشداء فتتنجس مقادسهم '),
(12107, 'Ezekiel', 26, 7, 25, ' الرعب آت فيطلبون السلام ولا يكون '),
(12108, 'Ezekiel', 26, 7, 26, ' ستأتي مصيبة على مصيبة ، ويكون خبر على خبر ، فيطلبون رؤيا من النبي ، والشريعة تباد عن الكاهن ، والمشورة عن الشيوخ '),
(12109, 'Ezekiel', 26, 7, 27, ' الملك ينوح والرئيس يلبس حيرة ، وأيدي شعب الأرض ترجف . كطريقهم أصنع بهم ، وكأحكامهم أحكم عليهم ، فيعلمون أني أنا الرب '),
(12110, 'Ezekiel', 26, 8, 1, ' وكان في السنة السادسة ، في الشهر السادس ، في الخامس من الشهر ، وأنا جالس في بيتي ، ومشايخ يهوذا جالسون أمامي ، أن يد السيد الرب وقعت علي هناك '),
(12111, 'Ezekiel', 26, 8, 2, ' فنظرت وإذا شبه كمنظر نار ، من منظر حقويه إلى تحت نار ، ومن حقويه إلى فوق كمنظر لمعان كشبه النحاس اللامع '),
(12112, 'Ezekiel', 26, 8, 3, ' ومد شبه يد وأخذني بناصية رأسي ، ورفعني روح بين الأرض والسماء ، وأتى بي في رؤى الله إلى أورشليم ، إلى مدخل الباب الداخلي المتجه نحو الشمال ، حيث مجلس تمثال الغيرة ، المهيج الغيرة '),
(12113, 'Ezekiel', 26, 8, 4, ' وإذا مجد إله إسرائيل هناك مثل الرؤيا التي رأيتها في البقعة '),
(12114, 'Ezekiel', 26, 8, 5, ' ثم قال لي : يا ابن آدم ، ارفع عينيك نحو طريق الشمال . فرفعت عيني نحو طريق الشمال ، وإذا من شمالي باب المذبح تمثال الغيرة هذا في المدخل '),
(12115, 'Ezekiel', 26, 8, 6, ' وقال لي : يا ابن آدم ، هل رأيت ما هم عاملون ؟ الرجاسات العظيمة التي بيت إسرائيل عاملها هنا لإبعادي عن مقدسي . وبعد تعود تنظر رجاسات أعظم '),
(12116, 'Ezekiel', 26, 8, 7, ' ثم جاء بي إلى باب الدار ، فنظرت وإذا ثقب في الحائط '),
(12117, 'Ezekiel', 26, 8, 8, ' ثم قال لي : يا ابن آدم ، انقب في الحائط . فنقبت في الحائط ، فإذا باب '),
(12118, 'Ezekiel', 26, 8, 9, ' وقال لي : ادخل وانظر الرجاسات الشريرة التي هم عاملوها هنا '),
(12119, 'Ezekiel', 26, 8, 10, ' فدخلت ونظرت وإذا كل شكل دبابات وحيوان نجس ، وكل أصنام بيت إسرائيل ، مرسومة على الحائط على دائره '),
(12120, 'Ezekiel', 26, 8, 11, ' وواقف قدامها سبعون رجلا من شيوخ بيت إسرائيل ، ويازنيا بن شافان قائم في وسطهم ، وكل واحد مجمرته في يده ، وعطر عنان البخور صاعد '),
(12121, 'Ezekiel', 26, 8, 12, ' ثم قال لي : أرأيت يا ابن آدم ما تفعله شيوخ بيت إسرائيل في الظلام ، كل واحد في مخادع تصاويره ؟ لأنهم يقولون : الرب لا يرانا الرب قد ترك الأرض '),
(12122, 'Ezekiel', 26, 12, 10, ' قل لهم : هكذا قال السيد الرب . هذا الوحي هو الرئيس في أورشليم وكل بيت إسرائيل والذين هم في وسطهم '),
(12123, 'Ezekiel', 26, 12, 11, ' قل : أنا آية لكم . كما صنعت هكذا يصنع بهم . إلى الجلاء إلى السبي يذهبون '),
(12124, 'Ezekiel', 26, 12, 12, ' والرئيس الذي في وسطهم يحمل على الكتف في العتمة ويخرج . ينقبون في الحائط ليخرجوا منه . يغطي وجهه لكيلا ينظر الأرض بعينيه '),
(12125, 'Ezekiel', 26, 12, 13, ' وأبسط شبكتي عليه فيؤخذ في شركي ، وآتي به إلى بابل إلى أرض الكلدانيين ، ولكن لا يراها وهناك يموت '),
(12126, 'Ezekiel', 26, 12, 14, ' وأذري في كل ريح جميع الذين حوله لنصره ، وكل جيوشه ، وأستل السيف وراءهم '),
(12127, 'Ezekiel', 26, 12, 15, ' فيعلمون أني أنا الرب حين أبددهم بين الأمم وأذريهم في الأراضي '),
(12128, 'Ezekiel', 26, 12, 16, ' وأبقي منهم رجالا معدودين من السيف ومن الجوع ومن الوبإ ، لكي يحدثوا بكل رجاساتهم بين الأمم التي يأتون إليها ، فيعلمون أني أنا الرب '),
(12129, 'Ezekiel', 26, 12, 17, ' وكانت إلي كلمة الرب قائلة '),
(12130, 'Ezekiel', 26, 12, 18, ' يا ابن آدم ، كل خبزك بارتعاش ، واشرب ماءك بارتعاد وغم '),
(12131, 'Ezekiel', 26, 12, 19, ' وقل لشعب الأرض : هكذا قال السيد الرب على سكان أورشليم في أرض إسرائيل : يأكلون خبزهم بالغم ، ويشربون ماءهم بحيرة ، لكي تخرب أرضها عن ملئها من ظلم كل الساكنين فيها '),
(12132, 'Ezekiel', 26, 12, 20, ' والمدن المسكونة تخرب ، والأرض تقفر ، فتعلمون أني أنا الرب '),
(12133, 'Ezekiel', 26, 12, 21, ' وكان إلي كلام الرب قائلا '),
(12134, 'Ezekiel', 26, 12, 22, ' يا ابن آدم ، ما هذا المثل الذي لكم على أرض إسرائيل ، القائل : قد طالت الأيام وخابت كل رؤيا '),
(12135, 'Ezekiel', 26, 12, 23, ' لذلك قل لهم : هكذا قال السيد الرب : أبطل هذا المثل فلا يمثلون به بعد في إسرائيل . بل قل لهم : قد اقتربت الأيام وكلام كل رؤيا '),
(12136, 'Ezekiel', 26, 12, 24, ' لأنه لا تكون بعد رؤيا باطلة ولا عرافة ملقة في وسط بيت إسرائيل '),
(12137, 'Ezekiel', 26, 12, 25, ' لأني أنا الرب أتكلم ، والكلمة التي أتكلم بها تكون . لا تطول بعد . لأني في أيامكم أيها البيت المتمرد أقول الكلمة وأجريها ، يقول السيد الرب '),
(12138, 'Ezekiel', 26, 12, 26, ' وكان إلي كلام الرب قائلا '),
(12139, 'Ezekiel', 26, 12, 27, ' يا ابن آدم ، هوذا بيت إسرائيل قائلون : الرؤيا التي هو رائيها هي إلى أيام كثيرة ، وهو متنبئ لأزمنة بعيدة '),
(12140, 'Ezekiel', 26, 12, 28, ' لذلك قل لهم : هكذا قال السيد الرب : لا يطول بعد شيء من كلامي . الكلمة التي تكلمت بها تكون ، يقول السيد الرب '),
(12141, 'Ezekiel', 26, 13, 1, ' وكان إلي كلام الرب قائلا '),
(12142, 'Ezekiel', 26, 13, 2, ' يا ابن آدم ، تنبأ على أنبياء إسرائيل الذين يتنبأون ، وقل للذين هم أنبياء من تلقاء ذواتهم : اسمعوا كلمة الرب '),
(12143, 'Ezekiel', 26, 13, 3, ' هكذا قال السيد الرب : ويل للأنبياء الحمقى الذاهبين وراء روحهم ولم يروا شيئا '),
(12144, 'Ezekiel', 26, 13, 4, ' أنبياؤك يا إسرائيل صاروا كالثعالب في الخرب '),
(12145, 'Ezekiel', 26, 13, 5, ' لم تصعدوا إلى الثغر ، ولم تبنوا جدارا لبيت إسرائيل للوقوف في الحرب في يوم الرب '),
(12146, 'Ezekiel', 26, 13, 6, ' رأوا باطلا وعرافة كاذبة . القائلون : وحي الرب ، والرب لم يرسلهم ، وانتظروا إثبات الكلمة '),
(12147, 'Ezekiel', 26, 13, 7, ' ألم تروا رؤيا باطلة ، وتكلمتم بعرافة كاذبة ، قائلين : وحي الرب ، وأنا لم أتكلم '),
(12148, 'Ezekiel', 26, 13, 8, ' لذلك هكذا قال السيد الرب : لأنكم تكلمتم بالباطل ورأيتم كذبا ، فلذلك ها أنا عليكم ، يقول السيد الرب '),
(12149, 'Ezekiel', 26, 13, 9, ' وتكون يدي على الأنبياء الذين يرون الباطل ، والذين يعرفون بالكذب . في مجلس شعبي لا يكونون ، وفي كتاب بيت إسرائيل لا يكتبون ، وإلى أرض إسرائيل لا يدخلون ، فتعلمون أني أنا السيد الرب '),
(12150, 'Ezekiel', 26, 13, 10, ' من أجل أنهم أضلوا شعبي قائلين : سلام وليس سلام . وواحد منهم يبني حائطا وها هم يملطونه بالطفال '),
(12151, 'Ezekiel', 26, 13, 11, ' فقل للذين يملطونه بالطفال : إنه يسقط . يكون مطر جارف ، وأنتن يا حجارة البرد تسقطن ، وريح عاصفة تشققه '),
(12152, 'Ezekiel', 26, 13, 12, ' وهوذا إذا سقط الحائط ، أفلا يقال لكم : أين الطين الذي طينتم به '),
(12153, 'Ezekiel', 26, 13, 13, ' لذلك هكذا قال السيد الرب : إني أشققه بريح عاصفة في غضبي ، ويكون مطر جارف في سخطي ، وحجارة برد في غيظي لإفنائه '),
(12154, 'Ezekiel', 26, 13, 14, ' فأهدم الحائط الذي ملطتموه بالطفال ، وألصقه بالأرض ، وينكشف أساسه فيسقط ، وتفنون أنتم في وسطه ، فتعلمون أني أنا الرب '),
(12155, 'Ezekiel', 26, 13, 15, ' فأتم غضبي على الحائط وعلى الذين ملطوه بالطفال ، وأقول لكم : ليس الحائط بموجود ولا الذين ملطوه '),
(12156, 'Ezekiel', 26, 13, 16, ' أي أنبياء إسرائيل الذين يتنبأون لأورشليم ويرون لها رؤى سلام ، ولا سلام ، يقول السيد الرب '),
(12157, 'Ezekiel', 26, 13, 17, ' وأنت يا ابن آدم ، فاجعل وجهك ضد بنات شعبك اللواتي يتنبأن من تلقاء ذواتهن ، وتنبأ عليهن '),
(12158, 'Ezekiel', 26, 13, 18, ' وقل : هكذا قال السيد الرب : ويل للواتي يخطن وسائد لكل أوصال الأيدي ، ويصنعن مخدات لرأس كل قامة لاصطياد النفوس . أفتصطدن نفوس شعبي وتستحيين أنفسكن '),
(12159, 'Ezekiel', 26, 13, 19, ' وتنجسنني عند شعبي لأجل حفنة شعير ، ولأجل فتات من الخبز ، لإماتة نفوس لا ينبغي أن تموت ، واستحياء نفوس لا ينبغي أن تحيا ، بكذبكن على شعبي السامعين للكذب '),
(12160, 'Ezekiel', 26, 13, 20, ' لذلك هكذا قال السيد الرب : ها أنا ضد وسائدكن التي تصطدن بها النفوس كالفراخ ، وأمزقها عن أذرعكن ، وأطلق النفوس ، النفوس التي تصطدنها كالفراخ '),
(12161, 'Ezekiel', 26, 13, 21, ' وأمزق مخداتكن وأنقذ شعبي من أيديكن ، فلا يكونون بعد في أيديكن للصيد ، فتعلمن أني أنا الرب '),
(12162, 'Ezekiel', 26, 13, 22, ' لأنكن أحزنتن قلب الصديق كذبا وأنا لم أحزنه ، وشددتن أيدي الشرير حتى لا يرجع عن طريقه الرديئة فيحيا '),
(12163, 'Ezekiel', 26, 13, 23, ' فلذلك لن تعدن ترين الباطل ولا تعرفن عرافة بعد ، وأنقذ شعبي من أيديكن ، فتعلمن أني أنا الرب '),
(12164, 'Ezekiel', 26, 14, 1, ' فجاء إلي رجال من شيوخ إسرائيل وجلسوا أمامي '),
(12165, 'Ezekiel', 26, 14, 2, ' فصارت إلي كلمة الرب قائلة '),
(12166, 'Ezekiel', 26, 14, 3, ' يا ابن آدم ، هؤلاء الرجال قد أصعدوا أصنامهم إلى قلوبهم ، ووضعوا معثرة إثمهم تلقاء أوجههم . فهل أسأل منهم سؤالا '),
(12167, 'Ezekiel', 26, 14, 4, ' لأجل ذلك كلمهم وقل لهم : هكذا قال السيد الرب : كل إنسان من بيت إسرائيل الذي يصعد أصنامه إلى قلبه ، ويضع معثرة إثمه تلقاء وجهه ، ثم يأتي إلى النبي ، فإني أنا الرب أجيبه حسب كثرة أصنامه '),
(12168, 'Ezekiel', 26, 14, 5, ' لكي آخذ بيت إسرائيل بقلوبهم ، لأنهم كلهم قد ارتدوا عني بأصنامهم '),
(12169, 'Ezekiel', 26, 14, 6, ' لذلك قل لبيت إسرائيل : هكذا قال السيد الرب : توبوا وارجعوا عن أصنامكم ، وعن كل رجاساتكم اصرفوا وجوهكم '),
(12170, 'Ezekiel', 26, 14, 7, ' لأن كل إنسان من بيت إسرائيل أو من الغرباء المتغربين في إسرائيل ، إذا ارتد عني وأصعد أصنامه إلى قلبه ، ووضع معثرة إثمه تلقاء وجهه ، ثم جاء إلى النبي ليسأله عني ، فإني أنا الرب أجيبه بنفسي '),
(12171, 'Ezekiel', 26, 14, 8, ' وأجعل وجهي ضد ذلك الإنسان وأجعله آية ومثلا ، وأستأصله من وسط شعبي ، فتعلمون أني أنا الرب '),
(12172, 'Ezekiel', 26, 14, 9, ' فإذا ضل النبي وتكلم كلاما ، فأنا الرب قد أضللت ذلك النبي ، وسأمد يدي عليه وأبيده من وسط شعبي إسرائيل '),
(12173, 'Ezekiel', 26, 14, 10, ' ويحملون إثمهم . كإثم السائل يكون إثم النبي '),
(12174, 'Ezekiel', 26, 14, 11, ' لكي لا يعود يضل عني بيت إسرائيل ، ولكي لا يعودوا يتنجسون بكل معاصيهم ، بل ليكونوا لي شعبا وأنا أكون لهم إلها ، يقول السيد الرب '),
(12175, 'Ezekiel', 26, 14, 12, ' وكانت إلي كلمة الرب قائلة '),
(12176, 'Ezekiel', 26, 14, 13, ' يا ابن آدم ، إن أخطأت إلي أرض وخانت خيانة ، فمددت يدي عليها وكسرت لها قوام الخبز ، وأرسلت عليها الجوع ، وقطعت منها الإنسان والحيوان '),
(12177, 'Ezekiel', 26, 14, 14, ' وكان فيها هؤلاء الرجال الثلاثة : نوح ودانيآل وأيوب ، فإنهم إنما يخلصون أنفسهم ببرهم ، يقول السيد الرب '),
(12178, 'Ezekiel', 26, 14, 15, ' إن عبرت في الأرض وحوشا رديئة فأثكلوها وصارت خرابا بلا عابر بسبب الوحوش '),
(12179, 'Ezekiel', 26, 14, 16, ' وفي وسطها هؤلاء الرجال الثلاثة ، فحي أنا ، يقول السيد الرب ، إنهم لا يخلصون بنين ولا بنات . هم وحدهم يخلصون والأرض تصير خربة '),
(12180, 'Ezekiel', 26, 14, 17, ' أو إن جلبت سيفا على تلك الأرض وقلت : يا سيف اعبر في الأرض ، وقطعت منها الإنسان والحيوان '),
(12181, 'Ezekiel', 26, 14, 18, ' وفي وسطها هؤلاء الرجال الثلاثة ، فحي أنا ، يقول السيد الرب ، إنهم لا يخلصون بنين ولا بنات ، بل هم وحدهم يخلصون '),
(12182, 'Ezekiel', 26, 14, 19, ' أو إن أرسلت وبأ على تلك الأرض ، وسكبت غضبي عليها بالدم لأقطع منها الإنسان والحيوان '),
(12183, 'Ezekiel', 26, 14, 20, ' وفي وسطها نوح ودانيآل وأيوب ، فحي أنا ، يقول السيد الرب ، إنهم لا يخلصون ابنا ولا ابنة . إنما يخلصون أنفسهم ببرهم '),
(12184, 'Ezekiel', 26, 14, 21, ' لأنه هكذا قال السيد الرب : كم بالحري إن أرسلت أحكامي الرديئة على أورشليم : سيفا وجوعا ووحشا رديئا ووبأ ، لأقطع منها الإنسان والحيوان '),
(12185, 'Ezekiel', 26, 14, 22, ' فهوذا بقية فيها ناجية تخرج بنون وبنات . هوذا يخرجون إليكم فتنظرون طريقهم وأعمالهم ، وتتعزون عن الشر الذي جلبته على أورشليم عن كل ما جلبته عليها '),
(12186, 'Ezekiel', 26, 14, 23, ' ويعزونكم إذ ترون طريقهم وأعمالهم ، فتعلمون أني لم أصنع بلا سبب كل ما صنعته فيها ، يقول السيد الرب '),
(12187, 'Ezekiel', 26, 15, 1, ' وكان إلي كلام الرب قائلا '),
(12188, 'Ezekiel', 26, 15, 2, ' يا ابن آدم ، ماذا يكون عود الكرم فوق كل عود أو فوق القضيب الذي من شجر الوعر '),
(12189, 'Ezekiel', 26, 15, 3, ' هل يؤخذ منه عود لاصطناع عمل ما ، أو يأخذون منه وتدا ليعلق عليه إناء ما '),
(12190, 'Ezekiel', 26, 15, 4, ' هوذا يطرح أكلا للنار . تأكل النار طرفيه ويحرق وسطه . فهل يصلح لعمل '),
(12191, 'Ezekiel', 26, 15, 5, ' هوذا حين كان صحيحا لم يكن يصلح لعمل ما ، فكم بالحري لا يصلح بعد لعمل إذ أكلته النار فاحترق '),
(12192, 'Ezekiel', 26, 15, 6, ' لذلك هكذا قال السيد الرب : مثل عود الكرم بين عيدان الوعر التي بذلتها أكلا للنار ، كذلك أبذل سكان أورشليم '),
(12193, 'Ezekiel', 26, 15, 7, ' وأجعل وجهي ضدهم . يخرجون من نار فتأكلهم نار ، فتعلمون أني أنا الرب حين أجعل وجهي ضدهم '),
(12194, 'Ezekiel', 26, 15, 8, ' وأجعل الأرض خرابا لأنهم خانوا خيانة ، يقول السيد الرب '),
(12195, 'Ezekiel', 26, 16, 1, ' وكانت إلي كلمة الرب قائلة '),
(12196, 'Ezekiel', 26, 16, 2, ' يا ابن آدم ، عرف أورشليم برجاساتها '),
(12197, 'Ezekiel', 26, 16, 3, ' وقل : هكذا قال السيد الرب لأورشليم : مخرجك ومولدك من أرض كنعان . أبوك أموري وأمك حثية '),
(12198, 'Ezekiel', 26, 16, 4, ' أما ميلادك يوم ولدت فلم تقطع سرتك ، ولم تغسلي بالماء للتنظف ، ولم تملحي تمليحا ، ولم تقمطي تقميطا '),
(12199, 'Ezekiel', 26, 16, 5, ' لم تشفق عليك عين لتصنع لك واحدة من هذه لترق لك ، بل طرحت على وجه الحقل بكراهة نفسك يوم ولدت '),
(12200, 'Ezekiel', 26, 16, 6, ' فمررت بك ورأيتك مدوسة بدمك ، فقلت لك : بدمك عيشي ، قلت لك : بدمك عيشي '),
(12201, 'Ezekiel', 26, 16, 7, ' جعلتك ربوة كنبات الحقل ، فربوت وكبرت ، وبلغت زينة الأزيان . نهد ثدياك ، ونبت شعرك وقد كنت عريانة وعارية '),
(12202, 'Ezekiel', 26, 16, 8, ' فمررت بك ورأيتك ، وإذا زمنك زمن الحب . فبسطت ذيلي عليك وسترت عورتك ، وحلفت لك ، ودخلت معك في عهد ، يقول السيد الرب ، فصرت لي '),
(12203, 'Ezekiel', 26, 16, 9, ' فحممتك بالماء ، وغسلت عنك دماءك ، ومسحتك بالزيت '),
(12204, 'Ezekiel', 26, 16, 10, ' وألبستك مطرزة ، ونعلتك بالتخس ، وأزرتك بالكتان ، وكسوتك بزا '),
(12205, 'Ezekiel', 26, 16, 11, ' وحليتك بالحلي ، فوضعت أسورة في يديك وطوقا في عنقك '),
(12206, 'Ezekiel', 26, 16, 12, ' ووضعت خزامة في أنفك وأقراطا في أذنيك وتاج جمال على رأسك '),
(12207, 'Ezekiel', 26, 16, 13, ' فتحليت بالذهب والفضة ، ولباسك الكتان والبز والمطرز . وأكلت السميذ والعسل والزيت ، وجملت جدا جدا ، فصلحت لمملكة '),
(12208, 'Ezekiel', 26, 16, 14, ' وخرج لك اسم في الأمم لجمالك ، لأنه كان كاملا ببهائي الذي جعلته عليك ، يقول السيد الرب '),
(12209, 'Ezekiel', 26, 16, 15, ' فاتكلت على جمالك ، وزنيت على اسمك ، وسكبت زناك على كل عابر فكان له '),
(12210, 'Ezekiel', 26, 16, 16, ' وأخذت من ثيابك وصنعت لنفسك مرتفعات موشاة ، وزنيت عليها . أمر لم يأت ولم يكن '),
(12211, 'Ezekiel', 26, 16, 17, ' وأخذت أمتعة زينتك من ذهبي ومن فضتي التي أعطيتك ، وصنعت لنفسك صور ذكور وزنيت بها '),
(12212, 'Ezekiel', 26, 16, 18, ' وأخذت ثيابك المطرزة وغطيتها بها ، ووضعت أمامها زيتي وبخوري '),
(12213, 'Ezekiel', 26, 16, 19, ' وخبزي الذي أعطيتك ، السميذ والزيت والعسل الذي أطعمتك ، وضعتها أمامها رائحة سرور . وهكذا كان ، يقول السيد الرب '),
(12214, 'Ezekiel', 26, 16, 20, ' أخذت بنيك وبناتك الذين ولدتهم لي ، وذبحتهم لها طعاما . أهو قليل من زناك '),
(12215, 'Ezekiel', 26, 16, 21, ' أنك ذبحت بني وجعلتهم يجوزون في النار لها '),
(12216, 'Ezekiel', 26, 16, 22, ' وفي كل رجاساتك وزناك لم تذكري أيام صباك ، إذ كنت عريانة وعارية وكنت مدوسة بدمك '),
(12217, 'Ezekiel', 26, 16, 23, ' وكان بعد كل شرك . ويل ، ويل لك يقول السيد الرب '),
(12218, 'Ezekiel', 26, 16, 24, ' أنك بنيت لنفسك قبة وصنعت لنفسك مرتفعة في كل شارع '),
(12219, 'Ezekiel', 26, 16, 25, ' في رأس كل طريق بنيت مرتفعتك ورجست جمالك ، وفرجت رجليك لكل عابر وأكثرت زناك '),
(12220, 'Ezekiel', 26, 16, 26, ' وزنيت مع جيرانك بني مصر الغلاظ اللحم ، وزدت في زناك لإغاظتي '),
(12221, 'Ezekiel', 26, 16, 27, ' فهأنذا قد مددت يدي عليك ، ومنعت عنك فريضتك ، وأسلمتك لمرام مبغضاتك ، بنات الفلسطينيين ، اللواتي يخجلن من طريقك الرذيلة '),
(12222, 'Ezekiel', 26, 16, 28, ' وزنيت مع بني أشور ، إذ كنت لم تشبعي فزنيت بهم ، ولم تشبعي أيضا '),
(12223, 'Ezekiel', 26, 16, 29, ' وكثرت زناك في أرض كنعان إلى أرض الكلدانيين ، وبهذا أيضا لم تشبعي '),
(12224, 'Ezekiel', 26, 16, 30, ' ما أمرض قلبك ، يقول السيد الرب ، إذ فعلت كل هذا فعل امرأة زانية سليطة '),
(12225, 'Ezekiel', 26, 16, 31, ' ببنائك قبتك في رأس كل طريق ، وصنعك مرتفعتك في كل شارع . ولم تكوني كزانية ، بل محتقرة الأجرة '),
(12226, 'Ezekiel', 26, 16, 32, ' أيتها الزوجة الفاسقة ، تأخذ أجنبيين مكان زوجها '),
(12227, 'Ezekiel', 26, 16, 33, ' لكل الزواني يعطون هدية ، أما أنت فقد أعطيت كل محبيك هداياك ، ورشيتهم ليأتوك من كل جانب للزنا بك '),
(12228, 'Ezekiel', 26, 16, 34, ' وصار فيك عكس عادة النساء في زناك ، إذ لم يزن وراءك ، بل أنت تعطين أجرة ولا أجرة تعطى لك ، فصرت بالعكس '),
(12229, 'Ezekiel', 26, 16, 35, ' فلذلك يا زانية اسمعي كلام الرب '),
(12230, 'Ezekiel', 26, 16, 36, ' هكذا قال السيد الرب : من أجل أنه قد أنفق نحاسك وانكشفت عورتك بزناك بمحبيك وبكل أصنام رجاساتك ، ولدماء بنيك الذين بذلتهم لها '),
(12231, 'Ezekiel', 26, 16, 37, ' لذلك هأنذا أجمع جميع محبيك الذين لذذت لهم ، وكل الذين أحببتهم مع كل الذين أبغضتهم ، فأجمعهم عليك من حولك ، وأكشف عورتك لهم لينظروا كل عورتك '),
(12232, 'Ezekiel', 26, 16, 38, ' وأحكم عليك أحكام الفاسقات السافكات الدم ، وأجعلك دم السخط والغيرة '),
(12233, 'Ezekiel', 26, 16, 39, ' وأسلمك ليدهم فيهدمون قبتك ويهدمون مرتفعاتك ، وينزعون عنك ثيابك ، ويأخذون أدوات زينتك ، ويتركونك عريانة وعارية '),
(12234, 'Ezekiel', 26, 16, 40, ' ويصعدون عليك جماعة ، ويرجمونك بالحجارة ويقطعونك بسيوفهم '),
(12235, 'Ezekiel', 26, 16, 41, ' ويحرقون بيوتك بالنار ، ويجرون عليك أحكاما قدام عيون نساء كثيرة . وأكفك عن الزنا ، وأيضا لا تعطين أجرة بعد '),
(12236, 'Ezekiel', 26, 16, 42, ' وأحل غضبي بك فتنصرف غيرتي عنك ، فأسكن ولا أغضب بعد '),
(12237, 'Ezekiel', 26, 16, 43, ' من أجل أنك لم تذكري أيام صباك ، بل أسخطتني في كل هذه ، فهأنذا أيضا أجلب طريقك على رأسك ، يقول السيد الرب ، فلا تفعلين هذه الرذيلة فوق رجاساتك كلها '),
(12238, 'Ezekiel', 26, 16, 44, ' هوذا كل ضارب مثل يضرب مثلا عليك قائلا : مثل الأم بنتها '),
(12239, 'Ezekiel', 26, 16, 45, ' ابنة أمك أنت ، الكارهة زوجها وبنيها . وأنت أخت أخواتك اللواتي كرهن أزواجهن وأبناءهن . أمكن حثية وأبوكن أموري '),
(12240, 'Ezekiel', 26, 16, 46, ' وأختك الكبرى السامرة هي وبناتها الساكنة عن شمالك ، وأختك الصغرى الساكنة عن يمينك هي سدوم وبناتها '),
(12241, 'Ezekiel', 26, 16, 47, ' ولا في طريقهن سلكت ، ولا مثل رجاساتهن فعلت ، كأن ذلك قليل فقط ، ففسدت أكثر منهن في كل طرقك '),
(12242, 'Ezekiel', 26, 16, 48, ' حي أنا ، يقول السيد الرب ، إن سدوم أختك لم تفعل هي ولا بناتها كما فعلت أنت وبناتك '),
(12243, 'Ezekiel', 26, 16, 49, ' هذا كان إثم أختك سدوم : الكبرياء والشبع من الخبز وسلام الاطمئنان كان لها ولبناتها ، ولم تشدد يد الفقير والمسكين '),
(12244, 'Ezekiel', 26, 16, 50, ' وتكبرن وعملن الرجس أمامي فنزعتهن كما رأيت '),
(12245, 'Ezekiel', 26, 16, 51, ' ولم تخطئ السامرة نصف خطاياك . بل زدت رجاساتك أكثر منهن ، وبررت أخواتك بكل رجاساتك التي فعلت '),
(12246, 'Ezekiel', 26, 16, 52, ' فاحملي أيضا خزيك ، أنت القاضية على أخواتك ، بخطاياك التي بها رجست أكثر منهن . هن أبر منك ، فاخجلي أنت أيضا ، واحملي عارك بتبريرك أخواتك '),
(12247, 'Ezekiel', 26, 16, 53, ' وأرجع سبيهن ، سبي سدوم وبناتها ، وسبي السامرة وبناتها ، وسبي مسبييك في وسطها '),
(12248, 'Ezekiel', 26, 16, 54, ' لكي تحملي عارك وتخزي من كل ما فعلت بتعزيتك إياهن '),
(12249, 'Ezekiel', 26, 16, 55, ' وأخواتك سدوم وبناتها يرجعن إلى حالتهن القديمة ، والسامرة وبناتها يرجعن إلى حالتهن القديمة ، وأنت وبناتك ترجعن إلى حالتكن القديمة '),
(12250, 'Ezekiel', 26, 16, 56, ' وأختك سدوم لم تكن تذكر في فمك يوم كبريائك '),
(12251, 'Ezekiel', 26, 16, 57, ' قبل ما انكشف شرك ، كما في زمان تعيير بنات أرام وكل من حولها ، بنات الفلسطينيين اللواتي يحتقرنك من كل جهة '),
(12252, 'Ezekiel', 26, 16, 58, ' رذيلتك ورجاساتك أنت تحملينها ، يقول الرب '),
(12253, 'Ezekiel', 26, 16, 59, ' لأنه هكذا قال السيد الرب : إني أفعل بك كما فعلت ، إذ ازدريت بالقسم لنكث العهد '),
(12254, 'Ezekiel', 26, 16, 60, ' ولكني أذكر عهدي معك في أيام صباك ، وأقيم لك عهدا أبديا '),
(12255, 'Ezekiel', 26, 16, 61, ' فتتذكرين طرقك وتخجلين إذ تقبلين أخواتك الكبر والصغر ، وأجعلهن لك بنات ، ولكن لا بعهدك '),
(12256, 'Ezekiel', 26, 16, 62, ' وأنا أقيم عهدي معك ، فتعلمين أني أنا الرب '),
(12257, 'Ezekiel', 26, 16, 63, ' لكي تتذكري فتخزي ولا تفتحي فاك بعد بسبب خزيك ، حين أغفر لك كل ما فعلت ، يقول السيد الرب '),
(12258, 'Ezekiel', 26, 17, 1, ' وكان إلي كلام الرب قائلا '),
(12259, 'Ezekiel', 26, 17, 2, ' يا ابن آدم ، حاج أحجية ومثل مثلا لبيت إسرائيل '),
(12260, 'Ezekiel', 26, 17, 3, ' وقل : هكذا قال السيد الرب : نسر عظيم كبير الجناحين ، طويل القوادم ، واسع المناكب ، ذو تهاويل ، جاء إلى لبنان وأخذ فرع الأرز '),
(12261, 'Ezekiel', 26, 17, 4, ' قصف رأس خراعيبه ، وجاء به إلى أرض كنعان ، وجعله في مدينة التجار '),
(12262, 'Ezekiel', 26, 17, 5, ' وأخذ من زرع الأرض وألقاه في حقل الزرع ، وجعله على مياه كثيرة . أقامه كالصفصاف '),
(12263, 'Ezekiel', 26, 1, 6, ' ولكل واحد أربعة أوجه ، ولكل واحد أربعة أجنحة '),
(12264, 'Ezekiel', 26, 1, 7, ' وأرجلها أرجل قائمة ، وأقدام أرجلها كقدم رجل العجل ، وبارقة كمنظر النحاس المصقول '),
(12265, 'Ezekiel', 26, 1, 8, ' وأيدي إنسان تحت أجنحتها على جوانبها الأربعة . ووجوهها وأجنحتها لجوانبها الأربعة '),
(12266, 'Ezekiel', 26, 1, 9, ' وأجنحتها متصلة الواحد بأخيه . لم تدر عند سيرها . كل واحد يسير إلى جهة وجهه '),
(12267, 'Ezekiel', 26, 1, 10, ' أما شبه وجوهها فوجه إنسان ووجه أسد لليمين لأربعتها ، ووجه ثور من الشمال لأربعتها ، ووجه نسر لأربعتها '),
(12268, 'Ezekiel', 26, 1, 11, ' فهذه أوجهها . أما أجنحتها فمبسوطة من فوق . لكل واحد اثنان متصلان أحدهما بأخيه ، واثنان يغطيان أجسامها '),
(12269, 'Ezekiel', 26, 1, 12, ' وكل واحد كان يسير إلى جهة وجهه . إلى حيث تكون الروح لتسير تسير . لم تدر عند سيرها '),
(12270, 'Ezekiel', 26, 1, 13, ' أما شبه الحيوانات فمنظرها كجمر نار متقدة ، كمنظر مصابيح هي سالكة بين الحيوانات . وللنار لمعان ، ومن النار كان يخرج برق '),
(12271, 'Ezekiel', 26, 1, 14, ' الحيوانات راكضة وراجعة كمنظر البرق '),
(12272, 'Ezekiel', 26, 1, 15, ' فنظرت الحيوانات وإذا بكرة واحدة على الأرض بجانب الحيوانات بأوجهها الأربعة '),
(12273, 'Ezekiel', 26, 1, 16, ' منظر البكرات وصنعتها كمنظر الزبرجد . وللأربع شكل واحد ، ومنظرها وصنعتها كأنها كانت بكرة وسط بكرة '),
(12274, 'Ezekiel', 26, 1, 17, ' لما سارت ، سارت على جوانبها الأربعة . لم تدر عند سيرها '),
(12275, 'Ezekiel', 26, 1, 18, ' أما أطرها فعالية ومخيفة . وأطرها ملآنة عيونا حواليها للأربع '),
(12276, 'Ezekiel', 26, 1, 19, ' فإذا سارت الحيوانات ، سارت البكرات بجانبها ، وإذا ارتفعت الحيوانات عن الأرض ارتفعت البكرات '),
(12277, 'Ezekiel', 26, 1, 20, ' إلى حيث تكون الروح لتسير يسيرون ، إلى حيث الروح لتسير والبكرات ترتفع معها ، لأن روح الحيوانات كانت في البكرات '),
(12278, 'Ezekiel', 26, 1, 21, ' فإذا سارت تلك سارت هذه ، وإذا وقفت تلك وقفت . وإذا ارتفعت تلك عن الأرض ارتفعت البكرات معها ، لأن روح الحيوانات كانت في البكرات '),
(12279, 'Ezekiel', 26, 1, 22, ' وعلى رؤوس الحيوانات شبه مقبب كمنظر البلور الهائل منتشرا على رؤوسها من فوق '),
(12280, 'Ezekiel', 26, 1, 23, ' وتحت المقبب أجنحتها مستقيمة الواحد نحو أخيه . لكل واحد اثنان يغطيان من هنا ، ولكل واحد اثنان يغطيان من هناك أجسامها '),
(12281, 'Ezekiel', 26, 1, 24, ' فلما سارت سمعت صوت أجنحتها كخرير مياه كثيرة ، كصوت القدير . صوت ضجة ، كصوت جيش . ولما وقفت أرخت أجنحتها '),
(12282, 'Ezekiel', 26, 1, 25, ' فكان صوت من فوق المقبب الذي على رؤوسها . إذا وقفت أرخت أجنحتها '),
(12283, 'Ezekiel', 26, 1, 26, ' وفوق المقبب الذي على رؤوسها شبه عرش كمنظر حجر العقيق الأزرق ، وعلى شبه العرش شبه كمنظر إنسان عليه من فوق '),
(12284, 'Ezekiel', 26, 1, 27, ' ورأيت مثل منظر النحاس اللامع كمنظر نار داخله من حوله ، من منظر حقويه إلى فوق ، ومن منظر حقويه إلى تحت ، رأيت مثل منظر نار ولها لمعان من حولها '),
(12285, 'Ezekiel', 26, 1, 28, ' كمنظر القوس التي في السحاب يوم مطر ، هكذا منظر اللمعان من حوله . هذا منظر شبه مجد الرب . ولما رأيته خررت على وجهي ، وسمعت صوت متكلم '),
(12286, 'Ezekiel', 26, 2, 1, ' فقال لي : يا ابن آدم ، قم على قدميك فأتكلم معك '),
(12287, 'Ezekiel', 26, 2, 2, ' فدخل في روح لما تكلم معي ، وأقامني على قدمي فسمعت المتكلم معي '),
(12288, 'Ezekiel', 26, 2, 3, ' وقال لي : يا ابن آدم ، أنا مرسلك إلى بني إسرائيل ، إلى أمة متمردة قد تمردت علي . هم وآباؤهم عصوا علي إلى ذات هذا اليوم '),
(12289, 'Ezekiel', 26, 2, 4, ' والبنون القساة الوجوه والصلاب القلوب ، أنا مرسلك إليهم . فتقول لهم : هكذا قال السيد الرب '),
(12290, 'Ezekiel', 26, 2, 5, ' وهم إن سمعوا وإن امتنعوا ، لأنهم بيت متمرد ، فإنهم يعلمون أن نبيا كان بينهم '),
(12291, 'Ezekiel', 26, 2, 6, ' أما أنت يا ابن آدم فلا تخف منهم ، ومن كلامهم لا تخف ، لأنهم قريس وسلاء لديك ، وأنت ساكن بين العقارب . من كلامهم لا تخف ومن وجوههم لا ترتعب ، لأنهم بيت متمرد '),
(12292, 'Ezekiel', 26, 2, 7, ' وتتكلم معهم بكلامي ، إن سمعوا وإن امتنعوا ، لأنهم متمردون '),
(12293, 'Ezekiel', 26, 2, 8, ' وأنت يا ابن آدم ، فاسمع ما أنا مكلمك به . لا تكن متمردا كالبيت المتمرد . افتح فمك وكل ما أنا معطيكه '),
(12294, 'Ezekiel', 26, 2, 9, ' فنظرت وإذا بيد ممدودة إلي ، وإذا بدرج سفر فيها '),
(12295, 'Ezekiel', 26, 2, 10, ' فنشره أمامي وهو مكتوب من داخل ومن قفاه ، وكتب فيه مراث ونحيب وويل '),
(12296, 'Ezekiel', 26, 3, 1, ' فقال لي : يا ابن آدم ، كل ما تجده . كل هذا الدرج ، واذهب كلم بيت إسرائيل '),
(12297, 'Ezekiel', 26, 3, 2, ' ففتحت فمي فأطعمني ذلك الدرج '),
(12298, 'Ezekiel', 26, 3, 3, ' وقال لي : يا ابن آدم ، أطعم بطنك واملأ جوفك من هذا الدرج الذي أنا معطيكه . فأكلته فصار في فمي كالعسل حلاوة '),
(12299, 'Ezekiel', 26, 3, 4, ' فقال لي : يا ابن آدم ، اذهب امض إلى بيت إسرائيل وكلمهم بكلامي '),
(12300, 'Ezekiel', 26, 3, 5, ' لأنك غير مرسل إلى شعب غامض اللغة وثقيل اللسان ، بل إلى بيت إسرائيل '),
(12301, 'Ezekiel', 26, 3, 6, ' لا إلى شعوب كثيرة غامضة اللغة وثقيلة اللسان لست تفهم كلامهم . فلو أرسلتك إلى هؤلاء لسمعوا لك '),
(12302, 'Ezekiel', 26, 3, 7, ' لكن بيت إسرائيل لا يشاء أن يسمع لك ، لأنهم لا يشاؤون أن يسمعوا لي . لأن كل بيت إسرائيل صلاب الجباه وقساة القلوب '),
(12303, 'Ezekiel', 26, 3, 8, ' هأنذا قد جعلت وجهك صلبا مثل وجوههم ، وجبهتك صلبة مثل جباههم '),
(12304, 'Ezekiel', 26, 3, 9, ' قد جعلت جبهتك كالماس أصلب من الصوان ، فلا تخفهم ولا ترتعب من وجوههم لأنهم بيت متمرد '),
(12305, 'Ezekiel', 26, 3, 10, ' وقال لي : يا ابن آدم ، كل الكلام الذي أكلمك به ، أوعه في قلبك واسمعه بأذنيك '),
(12306, 'Ezekiel', 26, 3, 11, ' وامض اذهب إلى المسبيين ، إلى بني شعبك ، وكلمهم وقل لهم : هكذا قال السيد الرب ، إن سمعوا وإن امتنعوا '),
(12307, 'Ezekiel', 26, 3, 12, ' ثم حملني روح ، فسمعت خلفي صوت رعد عظيم : مبارك مجد الرب من مكانه '),
(12308, 'Ezekiel', 26, 3, 13, ' وصوت أجنحة الحيوانات المتلاصقة الواحد بأخيه وصوت البكرات معها وصوت رعد عظيم '),
(12309, 'Ezekiel', 26, 3, 14, ' فحملني الروح وأخذني ، فذهبت مرا في حرارة روحي ، ويد الرب كانت شديدة علي '),
(12310, 'Ezekiel', 26, 3, 15, ' فجئت إلى المسبيين عند تل أبيب ، الساكنين عند نهر خابور . وحيث سكنوا هناك سكنت سبعة أيام متحيرا في وسطهم '),
(12311, 'Ezekiel', 26, 3, 16, ' وكان عند تمام السبعة الأيام أن كلمة الرب صارت إلي قائلة '),
(12312, 'Ezekiel', 26, 3, 17, ' يا ابن آدم ، قد جعلتك رقيبا لبيت إسرائيل . فاسمع الكلمة من فمي وأنذرهم من قبلي '),
(12313, 'Ezekiel', 26, 3, 18, ' إذا قلت للشرير : موتا تموت ، وما أنذرته أنت ولا تكلمت إنذارا للشرير من طريقه الرديئة لإحيائه ، فذلك الشرير يموت بإثمه ، أما دمه فمن يدك أطلبه '),
(12314, 'Ezekiel', 26, 3, 19, ' وإن أنذرت أنت الشرير ولم يرجع عن شره ولا عن طريقه الرديئة ، فإنه يموت بإثمه ، أما أنت فقد نجيت نفسك '),
(12315, 'Ezekiel', 26, 3, 20, ' والبار إن رجع عن بره وعمل إثما وجعلت معثرة أمامه فإنه يموت . لأنك لم تنذره ، يموت في خطيته ولا يذكر بره الذي عمله ، أما دمه فمن يدك أطلبه '),
(12316, 'Ezekiel', 26, 3, 21, ' وإن أنذرت أنت البار من أن يخطئ البار ، وهو لم يخطئ ، فإنه حياة يحيا لأنه أنذر ، وأنت تكون قد نجيت نفسك '),
(12317, 'Ezekiel', 26, 3, 22, ' وكانت يد الرب علي هناك ، وقال لي : قم اخرج إلى البقعة وهناك أكلمك '),
(12318, 'Ezekiel', 26, 3, 23, ' فقمت وخرجت إلى البقعة ، وإذا بمجد الرب واقف هناك كالمجد الذي رأيته عند نهر خابور ، فخررت على وجهي '),
(12319, 'Ezekiel', 26, 3, 24, ' فدخل في روح وأقامني على قدمي ، ثم كلمني وقال لي : اذهب أغلق على نفسك في وسط بيتك '),
(12320, 'Ezekiel', 26, 3, 25, ' وأنت يا ابن آدم ، فها هم يضعون عليك ربطا ويقيدونك بها ، فلا تخرج في وسطهم '),
(12321, 'Ezekiel', 26, 3, 26, ' وألصق لسانك بحنكك فتبكم ، ولا تكون لهم رجلا موبخا ، لأنهم بيت متمرد '),
(12322, 'Ezekiel', 26, 3, 27, ' فإذا كلمتك أفتح فمك فتقول لهم : هكذا قال السيد الرب : من يسمع فليسمع ، ومن يمتنع فليمتنع . لأنهم بيت متمرد '),
(12323, 'Ezekiel', 26, 4, 1, ' وأنت يا ابن آدم ، فخذ لنفسك لبنة وضعها أمامك ، وارسم عليها مدينة أورشليم '),
(12324, 'Ezekiel', 26, 4, 2, ' واجعل عليها حصارا ، وابن عليها برجا ، وأقم عليها مترسة ، واجعل عليها جيوشا ، وأقم عليها مجانق حولها '),
(12325, 'Ezekiel', 26, 4, 3, ' وخذ أنت لنفسك صاجا من حديد وانصبه سورا من حديد بينك وبين المدينة ، وثبت وجهك عليها ، فتكون في حصار وتحاصرها . تلك آية لبيت إسرائيل '),
(12326, 'Ezekiel', 26, 4, 4, ' واتكئ أنت على جنبك اليسار ، وضع عليه إثم بيت إسرائيل . على عدد الأيام التي فيها تتكئ عليه تحمل إثمهم '),
(12327, 'Ezekiel', 26, 4, 5, ' وأنا قد جعلت لك سني إثمهم حسب عدد الأيام ، ثلاث مئة يوم وتسعين يوما ، فتحمل إثم بيت إسرائيل '),
(12328, 'Ezekiel', 26, 4, 6, ' فإذا أتممتها ، فاتكئ على جنبك اليمين أيضا ، فتحمل إثم بيت يهوذا أربعين يوما . فقد جعلت لك كل يوم عوضا عن سنة '),
(12329, 'Ezekiel', 26, 4, 7, ' فثبت وجهك على حصار أورشليم وذراعك مكشوفة ، وتنبأ عليها '),
(12330, 'Ezekiel', 26, 4, 8, ' وهأنذا أجعل عليك ربطا فلا تقلب من جنب إلى جنب حتى تتمم أيام حصارك '),
(12331, 'Ezekiel', 26, 4, 9, ' وخذ أنت لنفسك قمحا وشعيرا وفولا وعدسا ودخنا وكرسنة وضعها في وعاء واحد ، واصنعها لنفسك خبزا كعدد الأيام التي تتكئ فيها على جنبك . ثلاث مئة يوم وتسعين يوما تأكله '),
(12332, 'Ezekiel', 26, 4, 10, ' وطعامك الذي تأكله يكون بالوزن . كل يوم عشرين شاقلا . من وقت إلى وقت تأكله '),
(12333, 'Ezekiel', 26, 4, 11, ' وتشرب الماء بالكيل ، سدس الهين ، من وقت إلى وقت تشربه '),
(12334, 'Ezekiel', 26, 4, 12, ' وتأكل كعكا من الشعير . على الخرء الذي يخرج من الإنسان تخبزه أمام عيونهم '),
(12335, 'Ezekiel', 26, 4, 13, ' وقال الرب : هكذا يأكل بنو إسرائيل خبزهم النجس بين الأمم الذين أطردهم إليهم '),
(12336, 'Ezekiel', 26, 4, 14, ' فقلت : آه ، يا سيد الرب ، ها نفسي لم تتنجس . ومن صباي إلى الآن لم آكل ميتة أو فريسة ، ولا دخل فمي لحم نجس '),
(12337, 'Ezekiel', 26, 8, 13, ' وقال لي : بعد تعود تنظر رجاسات أعظم هم عاملوها '),
(12338, 'Ezekiel', 26, 8, 14, ' فجاء بي إلى مدخل باب بيت الرب الذي من جهة الشمال ، وإذا هناك نسوة جالسات يبكين على تموز '),
(12339, 'Ezekiel', 26, 8, 15, ' فقال لي : أرأيت هذا يا ابن آدم ؟ بعد تعود تنظر رجاسات أعظم من هذه '),
(12340, 'Ezekiel', 26, 8, 16, ' فجاء بي إلى دار بيت الرب الداخلية ، وإذا عند باب هيكل الرب ، بين الرواق والمذبح ، نحو خمسة وعشرين رجلا ظهورهم نحو هيكل الرب ووجوههم نحو الشرق ، وهم ساجدون للشمس نحو الشرق '),
(12341, 'Ezekiel', 26, 8, 17, ' وقال لي : أرأيت يا ابن آدم ؟ أقليل لبيت يهوذا عمل الرجاسات التي عملوها هنا ؟ لأنهم قد ملأوا الأرض ظلما ويعودون لإغاظتي ، وها هم يقربون الغصن إلى أنفهم '),
(12342, 'Ezekiel', 26, 8, 18, ' فأنا أيضا أعامل بالغضب ، لا تشفق عيني ولا أعفو . وإن صرخوا في أذني بصوت عال لا أسمعهم '),
(12343, 'Ezekiel', 26, 9, 1, ' وصرخ في سمعي بصوت عال قائلا : قرب وكلاء المدينة ، كل واحد وعدته المهلكة بيده '),
(12344, 'Ezekiel', 26, 9, 2, ' وإذا بستة رجال مقبلين من طريق الباب الأعلى الذي هو من جهة الشمال ، وكل واحد عدته الساحقة بيده ، وفي وسطهم رجل لابس الكتان ، وعلى جانبه دواة كاتب . فدخلوا ووقفوا جانب مذبح النحاس '),
(12345, 'Ezekiel', 26, 9, 3, ' ومجد إله إسرائيل صعد عن الكروب الذي كان عليه إلى عتبة البيت . فدعا الرجل اللابس الكتان الذي دواة الكاتب على جانبه '),
(12346, 'Ezekiel', 26, 9, 4, ' وقال له الرب : اعبر في وسط المدينة ، في وسط أورشليم ، وسم سمة على جباه الرجال الذين يئنون ويتنهدون على كل الرجاسات المصنوعة في وسطها '),
(12347, 'Ezekiel', 26, 9, 5, ' وقال لأولئك في سمعي : اعبروا في المدينة وراءه واضربوا . لا تشفق أعينكم ولا تعفوا '),
(12348, 'Ezekiel', 26, 9, 6, ' الشيخ والشاب والعذراء والطفل والنساء ، اقتلوا للهلاك . ولا تقربوا من إنسان عليه السمة ، وابتدئوا من مقدسي . فابتدأوا بالرجال الشيوخ الذين أمام البيت '),
(12349, 'Ezekiel', 26, 9, 7, ' وقال لهم : نجسوا البيت ، واملأوا الدور قتلى . اخرجوا . فخرجوا وقتلوا في المدينة '),
(12350, 'Ezekiel', 26, 9, 8, ' وكان بينما هم يقتلون ، وأبقيت أنا ، أني خررت على وجهي وصرخت وقلت : آه ، يا سيد الرب هل أنت مهلك بقية إسرائيل كلها بصب رجزك على أورشليم '),
(12351, 'Ezekiel', 26, 9, 9, ' فقال لي : إن إثم بيت إسرائيل ويهوذا عظيم جدا جدا ، وقد امتلأت الأرض دماء ، وامتلأت المدينة جنفا . لأنهم يقولون : الرب قد ترك الأرض ، والرب لا يرى '),
(12352, 'Ezekiel', 26, 9, 10, ' وأنا أيضا عيني لا تشفق ولا أعفو . أجلب طريقهم على رؤوسهم '),
(12353, 'Ezekiel', 26, 9, 11, ' وإذا بالرجل اللابس الكتان الذي الدواة على جانبه رد جوابا قائلا : قد فعلت كما أمرتني '),
(12354, 'Ezekiel', 26, 10, 1, ' ثم نظرت وإذا على المقبب الذي على رأس الكروبيم شيء كحجر العقيق الأزرق ، كمنظر شبه عرش '),
(12355, 'Ezekiel', 26, 10, 2, ' وكلم الرجل اللابس الكتان وقال : ادخل بين البكرات تحت الكروب واملأ حفنتيك جمر نار من بين الكروبيم ، وذرها على المدينة . فدخل قدام عيني '),
(12356, 'Ezekiel', 26, 10, 3, ' والكروبيم واقفون عن يمين البيت حين دخل الرجل ، والسحابة ملأت الدار الداخلية '),
(12357, 'Ezekiel', 26, 10, 4, ' فارتفع مجد الرب عن الكروب إلى عتبة البيت . فامتلأ البيت من السحابة ، وامتلأت الدار من لمعان مجد الرب '),
(12358, 'Ezekiel', 26, 10, 5, ' وسمع صوت أجنحة الكروبيم إلى الدار الخارجية كصوت الله القدير إذا تكلم '),
(12359, 'Ezekiel', 26, 10, 6, ' وكان لما أمر الرجل اللابس الكتان قائلا : خذ نارا من بين البكرات ، من بين الكروبيم أنه دخل ووقف بجانب البكرة '),
(12360, 'Ezekiel', 26, 10, 7, ' ومد كروب يده من بين الكروبيم إلى النار التي بين الكروبيم ، فرفع منها ووضعها في حفنتي اللابس الكتان ، فأخذها وخرج '),
(12361, 'Ezekiel', 26, 10, 8, ' فظهر في الكروبيم شبه يد إنسان من تحت أجنحتها '),
(12362, 'Ezekiel', 26, 10, 9, ' ونظرت وإذا أربع بكرات بجانب الكروبيم . بكرة واحدة بجانب الكروب الواحد ، وبكرة أخرى بجانب الكروب الآخر . ومنظر البكرات كشبه حجر الزبرجد '),
(12363, 'Ezekiel', 26, 10, 10, ' ومنظرهن شكل واحد للأربع . كأنه كان بكرة وسط بكرة '),
(12364, 'Ezekiel', 26, 10, 11, ' لما سارت ، سارت على جوانبها الأربعة . لم تدر عند سيرها ، بل إلى الموضع الذي توجه إليه الرأس ذهبت وراءه . لم تدر عند سيرها '),
(12365, 'Ezekiel', 26, 10, 12, ' وكل جسمها وظهورها وأيديها وأجنحتها والبكرات ملآنة عيونا حواليها لبكراتها الأربع '),
(12366, 'Ezekiel', 26, 10, 13, ' أما البكرات فنودي إليها في سماعي : يا بكرة '),
(12367, 'Ezekiel', 26, 10, 14, ' ولكل واحد أربعة أوجه : الوجه الأول وجه كروب ، والوجه الثاني وجه إنسان ، والثالث وجه أسد ، والرابع وجه نسر '),
(12368, 'Ezekiel', 26, 10, 15, ' ثم صعد الكروبيم . هذا هو الحيوان الذي رأيته عند نهر خابور '),
(12369, 'Ezekiel', 26, 10, 16, ' وعند سير الكروبيم سارت البكرات بجانبها ، وعند رفع الكروبيم أجنحتها للارتفاع عن الأرض لم تدر البكرات أيضا عن جانبها '),
(12370, 'Ezekiel', 26, 10, 17, ' عند وقوفها وقفت هذه ، وعند ارتفاعها ارتفعت معها ، لأن فيها روح الحيوان '),
(12371, 'Ezekiel', 26, 10, 18, ' وخرج مجد الرب من على عتبة البيت ووقف على الكروبيم '),
(12372, 'Ezekiel', 26, 10, 19, ' فرفعت الكروبيم أجنحتها وصعدت عن الأرض قدام عيني . عند خروجها كانت البكرات معها ، ووقفت عند مدخل باب بيت الرب الشرقي ، ومجد إله إسرائيل عليها من فوق '),
(12373, 'Ezekiel', 26, 10, 20, ' هذا هو الحيوان الذي رأيته تحت إله إسرائيل عند نهر خابور . وعلمت أنها هي الكروبيم '),
(12374, 'Ezekiel', 26, 10, 21, ' لكل واحد أربعة أوجه ، ولكل واحد أربعة أجنحة ، وشبه أيدي إنسان تحت أجنحتها '),
(12375, 'Ezekiel', 26, 10, 22, ' وشكل وجوهها هو شكل الوجوه التي رأيتها عند نهر خابور ، مناظرها وذواتها . كل واحد يسير إلى جهة وجهه '),
(12376, 'Ezekiel', 26, 11, 1, ' ثم رفعني روح وأتى بي إلى باب بيت الرب الشرقي المتجه نحو الشرق ، وإذا عند مدخل الباب خمسة وعشرون رجلا ، ورأيت بينهم يازنيا بن عزور ، وفلطيا بن بنايا رئيسي الشعب '),
(12377, 'Ezekiel', 26, 11, 2, ' فقال لي : يا ابن آدم ، هؤلاء هم الرجال المفكرون بالإثم ، المشيرون مشورة رديئة في هذه المدينة '),
(12378, 'Ezekiel', 26, 11, 3, ' القائلون : ما هو قريب بناء البيوت هي القدر ونحن اللحم '),
(12379, 'Ezekiel', 26, 11, 4, ' لأجل ذلك تنبأ عليهم . تنبأ يا ابن آدم '),
(12380, 'Ezekiel', 26, 11, 5, ' وحل علي روح الرب وقال لي : قل : هكذا قال الرب : هكذا قلتم يا بيت إسرائيل ، وما يخطر ببالكم قد علمته '),
(12381, 'Ezekiel', 26, 11, 6, ' قد كثرتم قتلاكم في هذه المدينة وملأتم أزقتها بالقتلى '),
(12382, 'Ezekiel', 26, 11, 7, ' لذلك هكذا قال السيد الرب : قتلاكم الذين طرحتموهم في وسطها هم اللحم وهي القدر . وإياكم أخرج من وسطها '),
(12383, 'Ezekiel', 26, 11, 8, ' قد فزعتم من السيف ، فالسيف أجلبه عليكم ، يقول السيد الرب '),
(12384, 'Ezekiel', 26, 11, 9, ' وأخرجكم من وسطها وأسلمكم إلى أيدي الغرباء ، وأجري فيكم أحكاما '),
(12385, 'Ezekiel', 26, 11, 10, ' بالسيف تسقطون . في تخم إسرائيل أقضي عليكم ، فتعلمون أني أنا الرب '),
(12386, 'Ezekiel', 26, 11, 11, ' هذه لا تكون لكم قدرا ، ولا أنتم تكونون اللحم في وسطها . في تخم إسرائيل أقضي عليكم '),
(12387, 'Ezekiel', 26, 11, 12, ' فتعلمون أني أنا الرب الذي لم تسلكوا في فرائضه ، ولم تعملوا بأحكامه ، بل عملتم حسب أحكام الأمم الذين حولكم '),
(12388, 'Ezekiel', 26, 11, 13, ' وكان لما تنبأت أن فلطيا بن بنايا مات . فخررت على وجهي وصرخت بصوت عظيم وقلت : آه ، يا سيد الرب ، هل تفني أنت بقية إسرائيل '),
(12389, 'Ezekiel', 26, 11, 14, ' وكان إلي كلام الرب قائلا '),
(12390, 'Ezekiel', 26, 11, 15, ' يا ابن آدم ، إخوتك إخوتك ذوو قرابتك ، وكل بيت إسرائيل بأجمعه ، هم الذين قال لهم سكان أورشليم : ابتعدوا عن الرب . لنا أعطيت هذه الأرض ميراثا '),
(12391, 'Ezekiel', 26, 11, 16, ' لذلك قل : هكذا قال السيد الرب : وإن كنت قد أبعدتهم بين الأمم ، وإن كنت قد بددتهم في الأراضي ، فإني أكون لهم مقدسا صغيرا في الأراضي التي يأتون إليها '),
(12392, 'Ezekiel', 26, 11, 17, ' لذلك قل : هكذا قال السيد الرب : إني أجمعكم من بين الشعوب ، وأحشركم من الأراضي التي تبددتم فيها ، وأعطيكم أرض إسرائيل '),
(12393, 'Ezekiel', 26, 11, 18, ' فيأتون إلى هناك ويزيلون جميع مكرهاتها ، وجميع رجاساتها منها '),
(12394, 'Ezekiel', 26, 11, 19, ' وأعطيهم قلبا واحدا ، وأجعل في داخلكم روحا جديدا ، وأنزع قلب الحجر من لحمهم وأعطيهم قلب لحم '),
(12395, 'Ezekiel', 26, 11, 20, ' لكي يسلكوا في فرائضي ويحفظوا أحكامي ويعملوا بها ، ويكونوا لي شعبا ، فأنا أكون لهم إلها '),
(12396, 'Ezekiel', 26, 11, 21, ' أما الذين قلبهم ذاهب وراء قلب مكرهاتهم ورجاساتهم ، فإني أجلب طريقهم على رؤوسهم ، يقول السيد الرب '),
(12397, 'Ezekiel', 26, 11, 22, ' ثم رفعت الكروبيم أجنحتها والبكرات معها ، ومجد إله إسرائيل عليها من فوق '),
(12398, 'Ezekiel', 26, 11, 23, ' وصعد مجد الرب من على وسط المدينة ووقف على الجبل الذي على شرقي المدينة '),
(12399, 'Ezekiel', 26, 11, 24, ' وحملني روح وجاء بي في الرؤيا بروح الله إلى أرض الكلدانيين إلى المسبيين ، فصعدت عني الرؤيا التي رأيتها '),
(12400, 'Ezekiel', 26, 11, 25, ' فكلمت المسبيين بكل كلام الرب الذي أراني إياه '),
(12401, 'Ezekiel', 26, 12, 1, ' وكان إلي كلام الرب قائلا '),
(12402, 'Ezekiel', 26, 12, 2, ' يا ابن آدم ، أنت ساكن في وسط بيت متمرد ، الذين لهم أعين لينظروا ولا ينظرون . لهم آذان ليسمعوا ولا يسمعون ، لأنهم بيت متمرد '),
(12403, 'Ezekiel', 26, 12, 3, ' وأنت يا ابن آدم ، فهيئ لنفسك أهبة جلاء ، وارتحل قدام عيونهم نهارا ، وارتحل من مكانك إلى مكان آخر قدام عيونهم ، لعلهم ينظرون أنهم بيت متمرد '),
(12404, 'Ezekiel', 26, 12, 4, ' فتخرج أهبتك كأهبة الجلاء قدام عيونهم نهارا ، وأنت تخرج مساء قدام عيونهم كالخارجين إلى الجلاء '),
(12405, 'Ezekiel', 26, 12, 5, ' وانقب لنفسك في الحائط قدام عيونهم وأخرجها منه '),
(12406, 'Ezekiel', 26, 12, 6, ' واحمل على كتفك قدام عيونهم . في العتمة تخرجها . تغطي وجهك فلا ترى الأرض . لأني جعلتك آية لبيت إسرائيل '),
(12407, 'Ezekiel', 26, 12, 7, ' ففعلت هكذا كما أمرت ، فأخرجت أهبتي كأهبة الجلاء نهارا ، وفي المساء نقبت لنفسي في الحائط بيدي ، وأخرجت في العتمة ، وحملت على كتفي قدام عيونهم '),
(12408, 'Ezekiel', 26, 12, 8, ' وفي الصباح كانت إلي كلمة الرب قائلة '),
(12409, 'Ezekiel', 26, 12, 9, ' يا ابن آدم ، ألم يقل لك بيت إسرائيل ، البيت المتمرد : ماذا تصنع '),
(12410, 'Ezekiel', 26, 17, 6, ' فنبت وصار كرمة منتشرة قصيرة الساق . انعطفت عليه زراجينها وكانت أصولها تحته ، فصارت كرمة وأنبتت فروعا وأفرخت أغصانا '),
(12411, 'Ezekiel', 26, 17, 7, ' وكان نسر آخر عظيم كبير الجناحين واسع المنكب ، فإذا بهذه الكرمة عطفت عليه أصولها وأنبتت نحوه زراجينها ليسقيها في خمائل غرسها '),
(12412, 'Ezekiel', 26, 17, 8, ' في حقل جيد على مياه كثيرة هي مغروسة لتنبت أغصانها وتحمل ثمرا ، فتكون كرمة واسعة '),
(12413, 'Ezekiel', 26, 17, 9, ' قل : هكذا قال السيد الرب : هل تنجح ؟ أفلا يقلع أصولها ويقطع ثمرها فتيبس ؟ كل من أوراق أغصانها تيبس ، وليس بذراع عظيمة أو بشعب كثير ليقلعوها من أصولها '),
(12414, 'Ezekiel', 26, 17, 10, ' ها هي المغروسة ، فهل تنجح ؟ ألا تيبس يبسا كأن ريحا شرقية أصابتها ؟ في خمائل نبتها تيبس '),
(12415, 'Ezekiel', 26, 17, 11, ' وكان إلي كلام الرب قائلا '),
(12416, 'Ezekiel', 26, 17, 12, ' قل للبيت المتمرد : أما علمتم ما هذه ؟ قل : هوذا ملك بابل قد جاء إلى أورشليم وأخذ ملكها ورؤساءها وجاء بهم إليه إلى بابل '),
(12417, 'Ezekiel', 26, 17, 13, ' وأخذ من الزرع الملكي وقطع معه عهدا وأدخله في قسم ، وأخذ أقوياء الأرض '),
(12418, 'Ezekiel', 26, 17, 14, ' لتكون المملكة حقيرة ولا ترتفع ، لتحفظ العهد فتثبت '),
(12419, 'Ezekiel', 26, 17, 15, ' فتمرد عليه بإرساله رسله إلى مصر ليعطوه خيلا وشعبا كثيرين . فهل ينجح ؟ هل يفلت فاعل هذا ؟ أو ينقض عهدا ويفلت '),
(12420, 'Ezekiel', 26, 17, 16, ' حي أنا ، يقول السيد الرب ، إن في موضع الملك الذي ملكه ، الذي ازدرى قسمه ونقض عهده ، فعنده في وسط بابل يموت '),
(12421, 'Ezekiel', 26, 17, 17, ' ولا بجيش عظيم وجمع غفير يعينه فرعون في الحرب ، بإقامة مترسة وببناء برج لقطع نفوس كثيرة '),
(12422, 'Ezekiel', 26, 17, 18, ' إذ ازدرى القسم لنقض العهد ، وهوذا قد أعطى يده وفعل هذا كله فلا يفلت '),
(12423, 'Ezekiel', 26, 17, 19, ' لأجل ذلك هكذا قال السيد الرب : حي أنا ، إن قسمي الذي ازدراه ، وعهدي الذي نقضه ، أردهما على رأسه '),
(12424, 'Ezekiel', 26, 17, 20, ' وأبسط شبكتي عليه فيؤخذ في شركي ، وآتي به إلى بابل وأحاكمه هناك على خيانته التي خانني بها '),
(12425, 'Ezekiel', 26, 17, 21, ' وكل هاربيه وكل جيوشه يسقطون بالسيف ، والباقون يذرون في كل ريح ، فتعلمون أني أنا الرب تكلمت '),
(12426, 'Ezekiel', 26, 17, 22, ' هكذا قال السيد الرب : وآخذ أنا من فرع الأرز العالي وأغرسه ، وأقطف من رأس خراعيبه غصنا وأغرسه على جبل عال وشامخ '),
(12427, 'Ezekiel', 26, 17, 23, ' في جبل إسرائيل العالي أغرسه ، فينبت أغصانا ويحمل ثمرا ويكون أرزا واسعا ، فيسكن تحته كل طائر ، كل ذي جناح يسكن في ظل أغصانه '),
(12428, 'Ezekiel', 26, 17, 24, ' فتعلم جميع أشجار الحقل أني أنا الرب ، وضعت الشجرة الرفيعة ، ورفعت الشجرة الوضيعة ، ويبست الشجرة الخضراء ، وأفرخت الشجرة اليابسة . أنا الرب تكلمت وفعلت '),
(12429, 'Ezekiel', 26, 18, 1, ' وكان إلي كلام الرب قائلا '),
(12430, 'Ezekiel', 26, 18, 2, ' ما لكم أنتم تضربون هذا المثل على أرض إسرائيل ، قائلين : الآباء أكلوا الحصرم وأسنان الأبناء ضرست '),
(12431, 'Ezekiel', 26, 18, 3, ' حي أنا ، يقول السيد الرب ، لا يكون لكم من بعد أن تضربوا هذا المثل في إسرائيل '),
(12432, 'Ezekiel', 26, 18, 4, ' ها كل النفوس هي لي . نفس الأب كنفس الابن ، كلاهما لي . النفس التي تخطئ هي تموت '),
(12433, 'Ezekiel', 26, 18, 5, ' والإنسان الذي كان بارا وفعل حقا وعدلا '),
(12434, 'Ezekiel', 26, 18, 6, ' لم يأكل على الجبال ولم يرفع عينيه إلى أصنام بيت إسرائيل ، ولم ينجس امرأة قريبه ، ولم يقرب امرأة طامثا '),
(12435, 'Ezekiel', 26, 18, 7, ' ولم يظلم إنسانا ، بل رد للمديون رهنه ، ولم يغتصب اغتصابا بل بذل خبزه للجوعان ، وكسا العريان ثوبا '),
(12436, 'Ezekiel', 26, 18, 8, ' ولم يعط بالربا ، ولم يأخذ مرابحة ، وكف يده عن الجور ، وأجرى العدل الحق بين الإنسان والإنسان '),
(12437, 'Ezekiel', 26, 18, 9, ' وسلك في فرائضي وحفظ أحكامي ليعمل بالحق فهو بار . حياة يحيا ، يقول السيد الرب '),
(12438, 'Ezekiel', 26, 18, 10, ' فإن ولد ابنا معتنفا سفاك دم ، ففعل شيئا من هذه '),
(12439, 'Ezekiel', 26, 18, 11, ' ولم يفعل كل تلك ، بل أكل على الجبال ، ونجس امرأة قريبه '),
(12440, 'Ezekiel', 26, 18, 12, ' وظلم الفقير والمسكين ، واغتصب اغتصابا ، ولم يرد الرهن ، وقد رفع عينيه إلى الأصنام وفعل الرجس '),
(12441, 'Ezekiel', 26, 18, 13, ' وأعطى بالربا وأخذ المرابحة ، أفيحيا ؟ لا يحيا قد عمل كل هذه الرجاسات فموتا يموت . دمه يكون على نفسه '),
(12442, 'Ezekiel', 26, 18, 14, ' وإن ولد ابنا رأى جميع خطايا أبيه التي فعلها ، فرآها ولم يفعل مثلها '),
(12443, 'Ezekiel', 26, 18, 15, ' لم يأكل على الجبال ، ولم يرفع عينيه إلى أصنام بيت إسرائيل ، ولا نجس امرأة قريبه '),
(12444, 'Ezekiel', 26, 18, 16, ' ولا ظلم إنسانا ، ولا ارتهن رهنا ، ولا اغتصب اغتصابا ، بل بذل خبزه للجوعان ، وكسا العريان ثوبا '),
(12445, 'Ezekiel', 26, 18, 17, ' ورفع يده عن الفقير ، ولم يأخذ ربا ولا مرابحة ، بل أجرى أحكامي وسلك في فرائضي ، فإنه لا يموت بإثم أبيه . حياة يحيا '),
(12446, 'Ezekiel', 26, 18, 18, ' أما أبوه فلأنه ظلم ظلما ، واغتصب أخاه اغتصابا ، وعمل غير الصالح بين شعبه ، فهوذا يموت بإثمه '),
(12447, 'Ezekiel', 26, 18, 19, ' وأنتم تقولون : لماذا لا يحمل الابن من إثم الأب ؟ أما الابن فقد فعل حقا وعدلا . حفظ جميع فرائضي وعمل بها فحياة يحيا '),
(12448, 'Ezekiel', 26, 18, 20, ' النفس التي تخطئ هي تموت . الابن لا يحمل من إثم الأب ، والأب لا يحمل من إثم الابن . بر البار عليه يكون ، وشر الشرير عليه يكون '),
(12449, 'Ezekiel', 26, 18, 21, ' فإذا رجع الشرير عن جميع خطاياه التي فعلها وحفظ كل فرائضي وفعل حقا وعدلا فحياة يحيا . لا يموت '),
(12450, 'Ezekiel', 26, 18, 22, ' كل معاصيه التي فعلها لا تذكر عليه . في بره الذي عمل يحيا '),
(12451, 'Ezekiel', 26, 18, 23, ' هل مسرة أسر بموت الشرير ؟ يقول السيد الرب . ألا برجوعه عن طرقه فيحيا '),
(12452, 'Ezekiel', 26, 18, 24, ' وإذا رجع البار عن بره وعمل إثما وفعل مثل كل الرجاسات التي يفعلها الشرير ، أفيحيا ؟ كل بره الذي عمله لا يذكر . في خيانته التي خانها وفي خطيته التي أخطأ بها يموت '),
(12453, 'Ezekiel', 26, 18, 25, ' وأنتم تقولون : ليست طريق الرب مستوية . فاسمعوا الآن يا بيت إسرائيل : أطريقي هي غير مستوية ؟ أليست طرقكم غير مستوية '),
(12454, 'Ezekiel', 26, 18, 26, ' إذا رجع البار عن بره وعمل إثما ومات فيه ، فبإثمه الذي عمله يموت '),
(12455, 'Ezekiel', 26, 18, 27, ' وإذا رجع الشرير عن شره الذي فعل ، وعمل حقا وعدلا ، فهو يحيي نفسه '),
(12456, 'Ezekiel', 26, 18, 28, ' رأى فرجع عن كل معاصيه التي عملها فحياة يحيا . لا يموت '),
(12457, 'Ezekiel', 26, 18, 29, ' وبيت إسرائيل يقول : ليست طريق الرب مستوية . أطرقي غير مستقيمة يا بيت إسرائيل ؟ أليست طرقكم غير مستقيمة '),
(12458, 'Ezekiel', 26, 18, 30, ' من أجل ذلك أقضي عليكم يا بيت إسرائيل ، كل واحد كطرقه ، يقول السيد الرب . توبوا وارجعوا عن كل معاصيكم ، ولا يكون لكم الإثم مهلكة '),
(12459, 'Ezekiel', 26, 18, 31, ' اطرحوا عنكم كل معاصيكم التي عصيتم بها ، واعملوا لأنفسكم قلبا جديدا وروحا جديدة . فلماذا تموتون يا بيت إسرائيل '),
(12460, 'Ezekiel', 26, 18, 32, ' لأني لا أسر بموت من يموت ، يقول السيد الرب ، فارجعوا واحيوا '),
(12461, 'Ezekiel', 26, 19, 1, ' أما أنت فارفع مرثاة على رؤساء إسرائيل '),
(12462, 'Ezekiel', 26, 19, 2, ' وقل : ما هي أمك ؟ لبوة ربضت بين الأسود ، وربت جراءها بين الأشبال '),
(12463, 'Ezekiel', 26, 19, 3, ' ربت واحدا من جرائها فصار شبلا ، وتعلم افتراس الفريسة . أكل الناس '),
(12464, 'Ezekiel', 26, 19, 4, ' فلما سمعت به الأمم أخذ في حفرتهم ، فأتوا به بخزائم إلى أرض مصر '),
(12465, 'Ezekiel', 26, 19, 5, ' فلما رأت أنها قد انتظرت وهلك رجاؤها ، أخذت آخر من جرائها وصيرته شبلا '),
(12466, 'Ezekiel', 26, 19, 6, ' فتمشى بين الأسود . صار شبلا وتعلم افتراس الفريسة . أكل الناس '),
(12467, 'Ezekiel', 26, 19, 7, ' وعرف قصورهم وخرب مدنهم ، فأقفرت الأرض وملؤها من صوت زمجرته '),
(12468, 'Ezekiel', 26, 19, 8, ' فاتفق عليه الأمم من كل جهة من البلدان ، وبسطوا عليه شبكتهم ، فأخذ في حفرتهم '),
(12469, 'Ezekiel', 26, 19, 9, ' فوضعوه في قفص بخزائم وأحضروه إلى ملك بابل ، وأتوا به إلى القلاع لكيلا يسمع صوته بعد على جبال إسرائيل '),
(12470, 'Ezekiel', 26, 19, 10, ' أمك ككرمة ، مثلك غرست على المياه . كانت مثمرة مفرخة من كثرة المياه '),
(12471, 'Ezekiel', 26, 19, 11, ' وكان لها فروع قوية لقضبان المتسلطين ، وارتفع ساقها بين الأغصان الغبياء ، وظهرت في ارتفاعها بكثرة زراجينها '),
(12472, 'Ezekiel', 26, 19, 12, ' لكنها اقتلعت بغيظ وطرحت على الأرض ، وقد يبست ريح شرقية ثمرها . قصفت ويبست فروعها القوية . أكلتها النار '),
(12473, 'Ezekiel', 26, 19, 13, ' والآن غرست في القفر في أرض يابسة عطشانة '),
(12474, 'Ezekiel', 26, 19, 14, ' وخرجت نار من فرع عصيها أكلت ثمرها . وليس لها الآن فرع قوي لقضيب تسلط . هي رثاء وتكون لمرثاة '),
(12475, 'Ezekiel', 26, 20, 1, ' وكان في السنة السابعة ، في الشهر الخامس ، في العاشر من الشهر ، أن أناسا من شيوخ إسرائيل جاءوا ليسألوا الرب ، فجلسوا أمامي '),
(12476, 'Ezekiel', 26, 20, 2, ' فكان إلي كلام الرب قائلا '),
(12477, 'Ezekiel', 26, 20, 3, ' يا ابن آدم ، كلم شيوخ إسرائيل وقل لهم : هكذا قال السيد الرب : هل أنتم آتون لتسألوني ؟ حي أنا ، لا أسأل منكم ، يقول السيد الرب '),
(12478, 'Ezekiel', 26, 20, 4, ' هل تدينهم ؟ هل تدين يا ابن آدم ؟ عرفهم رجاسات آبائهم '),
(12479, 'Ezekiel', 26, 20, 5, ' وقل لهم : هكذا قال السيد الرب : في يوم اخترت إسرائيل ورفعت يدي لنسل بيت يعقوب ، وعرفتهم نفسي في أرض مصر ، ورفعت لهم يدي قائلا : أنا الرب إلهكم '),
(12480, 'Ezekiel', 26, 20, 6, ' في ذلك اليوم رفعت لهم يدي لأخرجهم من أرض مصر إلى الأرض التي تجسستها لهم ، تفيض لبنا وعسلا ، هي فخر كل الأراضي '),
(12481, 'Ezekiel', 26, 20, 7, ' وقلت لهم : اطرحوا كل إنسان منكم أرجاس عينيه ، ولا تتنجسوا بأصنام مصر . أنا الرب إلهكم '),
(12482, 'Ezekiel', 26, 20, 8, ' فتمردوا علي ولم يريدوا أن يسمعوا لي ، ولم يطرح الإنسان منهم أرجاس عينيه ، ولم يتركوا أصنام مصر . فقلت : إني أسكب رجزي عليهم لأتم عليهم سخطي في وسط أرض مصر '),
(12483, 'Ezekiel', 26, 20, 9, ' لكن صنعت لأجل اسمي لكيلا يتنجس أمام عيون الأمم الذين هم في وسطهم ، الذين عرفتهم نفسي أمام عيونهم بإخراجهم من أرض مصر '),
(12484, 'Ezekiel', 26, 20, 10, ' فأخرجتهم من أرض مصر وأتيت بهم إلى البرية '),
(12485, 'Ezekiel', 26, 20, 11, ' وأعطيتهم فرائضي وعرفتهم أحكامي التي إن عملها إنسان يحيا بها '),
(12486, 'Ezekiel', 26, 20, 12, ' وأعطيتهم أيضا سبوتي لتكون علامة بيني وبينهم ، ليعلموا أني أنا الرب مقدسهم '),
(12487, 'Ezekiel', 26, 20, 13, ' فتمرد علي بيت إسرائيل في البرية . لم يسلكوا في فرائضي ورفضوا أحكامي التي إن عملها إنسان يحيا بها ، ونجسوا سبوتي كثيرا . فقلت : إني أسكب رجزي عليهم في البرية لإفنائهم '),
(12488, 'Ezekiel', 26, 20, 14, ' لكن صنعت لأجل اسمي لكيلا يتنجس أمام عيون الأمم الذين أخرجتهم أمام عيونهم '),
(12489, 'Ezekiel', 26, 20, 15, ' ورفعت أيضا يدي لهم في البرية بأني لا آتي بهم إلى الأرض التي أعطيتهم إياها تفيض لبنا وعسلا ، هي فخر كل الأراضي '),
(12490, 'Ezekiel', 26, 20, 16, ' لأنهم رفضوا أحكامي ولم يسلكوا في فرائضي ، بل نجسوا سبوتي ، لأن قلبهم ذهب وراء أصنامهم '),
(12491, 'Ezekiel', 26, 20, 17, ' لكن عيني أشفقت عليهم عن إهلاكهم ، فلم أفنهم في البرية '),
(12492, 'Ezekiel', 26, 20, 18, ' وقلت لأبنائهم في البرية : لا تسلكوا في فرائض آبائكم ، ولا تحفظوا أحكامهم ، ولا تتنجسوا بأصنامهم '),
(12493, 'Ezekiel', 26, 20, 19, ' أنا الرب إلهكم ، فاسلكوا في فرائضي واحفظوا أحكامي واعملوا بها '),
(12494, 'Ezekiel', 26, 20, 20, ' وقدسوا سبوتي فتكون علامة بيني وبينكم ، لتعلموا أني أنا الرب إلهكم '),
(12495, 'Ezekiel', 26, 20, 21, ' فتمرد الأبناء علي . لم يسلكوا في فرائضي ولم يحفظوا أحكامي ليعملوها ، التي إن عملها إنسان يحيا بها ، ونجسوا سبوتي . فقلت : إني أسكب رجزي عليهم لأتم سخطي عليهم في البرية '),
(12496, 'Ezekiel', 26, 20, 22, ' ثم كففت يدي وصنعت لأجل اسمي لكيلا يتنجس أمام عيون الأمم الذين أخرجتهم أمام عيونهم '),
(12497, 'Ezekiel', 26, 20, 23, ' ورفعت أيضا يدي لهم في البرية لأفرقهم في الأمم وأذريهم في الأراضي '),
(12498, 'Ezekiel', 26, 20, 24, ' لأنهم لم يصنعوا أحكامي ، بل رفضوا فرائضي ، ونجسوا سبوتي ، وكانت عيونهم وراء أصنام آبائهم '),
(12499, 'Ezekiel', 26, 20, 25, ' وأعطيتهم أيضا فرائض غير صالحة ، وأحكاما لا يحيون بها '),
(12500, 'Ezekiel', 26, 20, 26, ' ونجستهم بعطاياهم إذ أجازوا في النار كل فاتح رحم ، لأبيدهم ، حتى يعلموا أني أنا الرب '),
(12501, 'Ezekiel', 26, 20, 27, ' لأجل ذلك كلم بيت إسرائيل يا ابن آدم ، وقل لهم : هكذا قال السيد الرب : في هذا أيضا جدف علي آباؤكم ، إذ خانوني خيانة ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(12502, 'Ezekiel', 26, 20, 28, ' لما أتيت بهم إلى الأرض التي رفعت لهم يدي لأعطيهم إياها ، فرأوا كل تل عال وكل شجرة غبياء ، فذبحوا هناك ذبائحهم ، وقربوا هناك قرابينهم المغيظة ، وقدموا هناك روائح سرورهم ، وسكبوا هناك سكائبهم '),
(12503, 'Ezekiel', 26, 20, 29, ' فقلت لهم : ما هذه المرتفعة التي تأتون إليها ؟ فدعي اسمها مرتفعة إلى هذا اليوم '),
(12504, 'Ezekiel', 26, 20, 30, ' لذلك قل لبيت إسرائيل : هكذا قال السيد الرب : هل تنجستم بطريق آبائكم ، وزنيتم وراء أرجاسهم '),
(12505, 'Ezekiel', 26, 20, 31, ' وبتقديم عطاياكم وإجازة أبنائكم في النار ، تتنجسون بكل أصنامكم إلى اليوم . فهل أسأل منكم يا بيت إسرائيل ؟ حي أنا ، يقول السيد الرب ، لا أسأل منكم '),
(12506, 'Ezekiel', 26, 20, 32, ' والذي يخطر ببالكم لن يكون ، إذ تقولون : نكون كالأمم ، كقبائل الأراضي فنعبد الخشب والحجر '),
(12507, 'Ezekiel', 26, 20, 33, ' حي أنا ، يقول السيد الرب ، إني بيد قوية وبذراع ممدودة ، وبسخط مسكوب أملك عليكم '),
(12508, 'Ezekiel', 26, 20, 34, ' وأخرجكم من بين الشعوب ، وأجمعكم من الأراضي التي تفرقتم فيها بيد قوية وبذراع ممدودة ، وبسخط مسكوب '),
(12509, 'Ezekiel', 26, 20, 35, ' وآتي بكم إلى برية الشعوب ، وأحاكمكم هناك وجها لوجه '),
(12510, 'Ezekiel', 26, 20, 36, ' كما حاكمت آباءكم في برية أرض مصر ، كذلك أحاكمكم ، يقول السيد الرب '),
(12511, 'Ezekiel', 26, 20, 37, ' وأمركم تحت العصا ، وأدخلكم في رباط العهد '),
(12512, 'Ezekiel', 26, 20, 38, ' وأعزل منكم المتمردين والعصاة علي . أخرجهم من أرض غربتهم ولا يدخلون أرض إسرائيل ، فتعلمون أني أنا الرب '),
(12513, 'Ezekiel', 26, 20, 39, ' أما أنتم يا بيت إسرائيل ، فهكذا قال السيد الرب : اذهبوا اعبدوا كل إنسان أصنامه . وبعد إن لم تسمعوا لي فلا تنجسوا اسمي القدوس ، بعد بعطاياكم وبأصنامكم '),
(12514, 'Ezekiel', 26, 20, 40, ' لأنه في جبل قدسي ، في جبل إسرائيل العالي ، يقول السيد الرب ، هناك يعبدني كل بيت إسرائيل ، كلهم في الأرض . هناك أرضى عنهم ، وهناك أطلب تقدماتكم وباكورات جزاكم مع جميع مقدساتكم '),
(12515, 'Ezekiel', 26, 20, 41, ' برائحة سروركم أرضى عنكم ، حين أخرجكم من بين الشعوب ، وأجمعكم من الأراضي التي تفرقتم فيها ، وأتقدس فيكم أمام عيون الأمم '),
(12516, 'Ezekiel', 26, 20, 42, ' فتعلمون أني أنا الرب ، حين آتي بكم إلى أرض إسرائيل ، إلى الأرض التي رفعت يدي لأعطي آباءكم إياها '),
(12517, 'Ezekiel', 26, 20, 43, ' وهناك تذكرون طرقكم وكل أعمالكم التي تنجستم بها ، وتمقتون أنفسكم لجميع الشرور التي فعلتم '),
(12518, 'Ezekiel', 26, 20, 44, ' فتعلمون أني أنا الرب إذا فعلت بكم من أجل اسمي . لا كطرقكم الشريرة ، ولا كأعمالكم الفاسدة يا بيت إسرائيل ، يقول السيد الرب '),
(12519, 'Ezekiel', 26, 20, 45, ' وكان إلي كلام الرب قائلا '),
(12520, 'Ezekiel', 26, 20, 46, ' يا ابن آدم ، اجعل وجهك نحو التيمن ، وتكلم نحو الجنوب ، وتنبأ على وعر الحقل في الجنوب '),
(12521, 'Ezekiel', 26, 20, 47, ' وقل لوعر الجنوب : اسمع كلام الرب . هكذا قال السيد الرب : هأنذا أضرم فيك نارا فتأكل كل شجرة خضراء فيك وكل شجرة يابسة . لا يطفأ لهيبها الملتهب ، وتحرق بها كل الوجوه من الجنوب إلى الشمال '),
(12522, 'Ezekiel', 26, 20, 48, ' فيرى كل بشر أني أنا الرب أضرمتها . لا تطفأ '),
(12523, 'Ezekiel', 26, 20, 49, ' فقلت : آه يا سيد الرب هم يقولون : أما يمثل هو أمثالا '),
(12524, 'Ezekiel', 26, 21, 1, ' وكان إلي كلام الرب قائلا '),
(12525, 'Ezekiel', 26, 21, 2, ' يا ابن آدم ، اجعل وجهك نحو أورشليم ، وتكلم على المقادس ، وتنبأ على أرض إسرائيل '),
(12526, 'Ezekiel', 26, 21, 3, ' وقل لأرض إسرائيل : هكذا قال الرب : هأنذا عليك ، وأستل سيفي من غمده فأقطع منك الصديق والشرير '),
(12527, 'Ezekiel', 26, 21, 4, ' من حيث أني أقطع منك الصديق والشرير ، فلذلك يخرج سيفي من غمده على كل بشر من الجنوب إلى الشمال '),
(12528, 'Ezekiel', 26, 21, 5, ' فيعلم كل بشر أني أنا الرب ، سللت سيفي من غمده . لا يرجع أيضا '),
(12529, 'Ezekiel', 26, 21, 6, ' أما أنت يا ابن آدم ، فتنهد بانكسار الحقوين ، وبمرارة تنهد أمام عيونهم '),
(12530, 'Ezekiel', 26, 21, 7, ' ويكون إذا قالوا لك : على م تتنهد ؟ أنك تقول : على الخبر ، لأنه جاء فيذوب كل قلب ، وترتخي كل الأيدي ، وتيأس كل روح ، وكل الركب تصير كالماء ، ها هي آتية وتكون ، يقول السيد الرب '),
(12531, 'Ezekiel', 26, 21, 8, ' وكان إلي كلام الرب قائلا '),
(12532, 'Ezekiel', 26, 21, 9, ' يا ابن آدم ، تنبأ وقل : هكذا قال الرب : قل : سيف ، سيف حدد وصقل أيضا '),
(12533, 'Ezekiel', 26, 21, 10, ' قد حدد ليذبح ذبحا . قد صقل لكي يبرق . فهل نبتهج ؟ عصا ابني تزدري بكل عود '),
(12534, 'Ezekiel', 26, 21, 11, ' وقد أعطاه ليصقل لكي يمسك بالكف . هذا السيف قد حدد وهو مصقول لكي يسلم ليد القاتل '),
(12535, 'Ezekiel', 26, 21, 12, ' اصرخ وولول يا ابن آدم ، لأنه يكون على شعبي وعلى كل رؤساء إسرائيل . أهوال بسبب السيف تكون على شعبي . لذلك اصفق على فخذك '),
(12536, 'Ezekiel', 26, 21, 13, ' لأنه امتحان . وماذا إن لم تكن أيضا العصا المزدرية ؟ يقول السيد الرب '),
(12537, 'Ezekiel', 26, 21, 14, ' فتنبأ أنت يا ابن آدم واصفق كفا على كف ، وليعد السيف ثالثة . هو سيف القتلى ، سيف القتل العظيم المحيق بهم '),
(12538, 'Ezekiel', 26, 21, 15, ' لذوبان القلب وتكثير المهالك ، لذلك جعلت على كل الأبواب سيفا متقلبا . آه قد جعل براقا . هو مصقول للذبح '),
(12539, 'Ezekiel', 26, 21, 16, ' انضم يمن ، انتصب شمل ، حيثما توجه حدك '),
(12540, 'Ezekiel', 26, 21, 17, ' وأنا أيضا أصفق كفي على كفي وأسكن غضبي . أنا الرب تكلمت '),
(12541, 'Ezekiel', 26, 21, 18, ' وكان إلي كلام الرب قائلا '),
(12542, 'Ezekiel', 26, 21, 19, ' وأنت يا ابن آدم ، عين لنفسك طريقين لمجيء سيف ملك بابل . من أرض واحدة تخرج الاثنتان . واصنع صوة ، على رأس طريق المدينة اصنعها '),
(12543, 'Ezekiel', 26, 21, 20, ' عين طريقا ليأتي السيف على ربة بني عمون ، وعلى يهوذا في أورشليم المنيعة '),
(12544, 'Ezekiel', 26, 21, 21, ' لأن ملك بابل قد وقف على أم الطريق ، على رأس الطريقين ليعرف عرافة . صقل السهام ، سأل بالترافيم ، نظر إلى الكبد '),
(12545, 'Ezekiel', 26, 21, 22, ' عن يمينه كانت العرافة على أورشليم لوضع المجانق ، لفتح الفم في القتل ، ولرفع الصوت بالهتاف ، لوضع المجانق على الأبواب ، لإقامة مترسة لبناء برج '),
(12546, 'Ezekiel', 26, 21, 23, ' وتكون لهم مثل عرافة كاذبة في عيونهم الحالفين لهم حلفا . لكنه يذكر الإثم حتى يؤخذوا '),
(12547, 'Ezekiel', 26, 21, 24, ' لذلك هكذا قال السيد الرب : من أجل أنكم ذكرتم بإثمكم عند انكشاف معاصيكم لإظهار خطاياكم في جميع أعمالكم ، فمن تذكيركم تؤخذون باليد '),
(12548, 'Ezekiel', 26, 21, 25, ' وأنت أيها النجس الشرير ، رئيس إسرائيل ، الذي قد جاء يومه في زمان إثم النهاية '),
(12549, 'Ezekiel', 26, 21, 26, ' هكذا قال السيد الرب : انزع العمامة . ارفع التاج . هذه لا تلك . ارفع الوضيع ، وضع الرفيع '),
(12550, 'Ezekiel', 26, 21, 27, ' منقلبا ، منقلبا ، منقلبا أجعله هذا أيضا لا يكون حتى يأتي الذي له الحكم فأعطيه إياه '),
(12551, 'Ezekiel', 26, 21, 28, ' وأنت يا ابن آدم ، فتنبأ وقل : هكذا قال السيد الرب ، في بني عمون وفي تعييرهم ، فقل : سيف ، سيف مسلول للذبح مصقول للغاية للبريق '),
(12552, 'Ezekiel', 26, 21, 29, ' إذ يرون لك باطلا ، إذ يعرفون لك كذبا ، ليجعلوك على أعناق القتلى الأشرار الذين جاء يومهم في زمان إثم النهاية '),
(12553, 'Ezekiel', 26, 21, 30, ' فهل أعيده إلى غمده ؟ ألا في الموضع الذي خلقت فيه في مولدك أحاكمك '),
(12554, 'Ezekiel', 26, 21, 31, ' وأسكب عليك غضبي ، وأنفخ عليك بنار غيظي ، وأسلمك ليد رجال متحرقين ماهرين للإهلاك '),
(12555, 'Ezekiel', 26, 21, 32, ' تكونين أكلة للنار . دمك يكون في وسط الأرض . لا تذكرين ، لأني أنا الرب تكلمت '),
(12556, 'Ezekiel', 26, 22, 1, ' وكان إلي كلام الرب قائلا '),
(12557, 'Ezekiel', 26, 22, 2, ' وأنت يا ابن آدم ، هل تدين ، هل تدين مدينة الدماء ؟ فعرفها كل رجاساتها '),
(12558, 'Ezekiel', 26, 22, 3, ' وقل : هكذا قال السيد الرب : أيتها المدينة السافكة الدم في وسطها ليأتي وقتها ، الصانعة أصناما لنفسها لتتنجس بها '),
(12559, 'Ezekiel', 26, 22, 4, ' قد أثمت بدمك الذي سفكت ، ونجست نفسك بأصنامك التي عملت ، وقربت أيامك وبلغت سنيك ، فلذلك جعلتك عارا للأمم ، وسخرة لجميع الأراضي '),
(12560, 'Ezekiel', 26, 22, 5, ' القريبة إليك والبعيدة عنك يسخرون منك ، يا نجسة الاسم ، يا كثيرة الشغب '),
(12561, 'Ezekiel', 26, 22, 6, ' هوذا رؤساء إسرائيل ، كل واحد حسب استطاعته ، كانوا فيك لأجل سفك الدم '),
(12562, 'Ezekiel', 26, 22, 7, ' فيك أهانوا أبا وأما . في وسطك عاملوا الغريب بالظلم . فيك اضطهدوا اليتيم والأرملة '),
(12563, 'Ezekiel', 26, 22, 8, ' ازدريت أقداسي ونجست سبوتي '),
(12564, 'Ezekiel', 26, 22, 9, ' كان فيك أناس وشاة لسفك الدم ، وفيك أكلوا على الجبال . في وسطك عملوا رذيلة '),
(12565, 'Ezekiel', 26, 22, 10, ' فيك كشف الإنسان عورة أبيه . فيك أذلوا المتنجسة بطمثها '),
(12566, 'Ezekiel', 26, 22, 11, ' إنسان فعل الرجس بامرأة قريبه . إنسان نجس كنته برذيلة . إنسان أذل فيك أخته بنت أبيه '),
(12567, 'Ezekiel', 26, 22, 12, ' فيك أخذوا الرشوة لسفك الدم . أخذت الربا والمرابحة ، وسلبت أقرباءك بالظلم ، ونسيتني ، يقول السيد الرب '),
(12568, 'Ezekiel', 26, 22, 13, ' فهأنذا قد صفقت بكفي بسبب خطفك الذي خطفت ، وبسبب دمك الذي كان في وسطك '),
(12569, 'Ezekiel', 26, 22, 14, ' فهل يثبت قلبك أو تقوى يداك في الأيام التي فيها أعاملك ؟ أنا الرب تكلمت وسأفعل '),
(12570, 'Ezekiel', 26, 22, 15, ' وأبددك بين الأمم ، وأذريك في الأراضي ، وأزيل نجاستك منك '),
(12571, 'Ezekiel', 26, 22, 16, ' وتتدنسين بنفسك أمام عيون الأمم ، وتعلمين أني أنا الرب '),
(12572, 'Ezekiel', 26, 22, 17, ' وكان إلي كلام الرب قائلا '),
(12573, 'Ezekiel', 26, 22, 18, ' يا ابن آدم ، قد صار لي بيت إسرائيل زغلا . كلهم نحاس وقصدير وحديد ورصاص في وسط كور . صاروا زغل فضة '),
(12574, 'Ezekiel', 26, 22, 19, ' لأجل ذلك هكذا قال السيد الرب : من حيث إنكم كلكم صرتم زغلا ، فلذلك هأنذا أجمعكم في وسط أورشليم '),
(12575, 'Ezekiel', 26, 22, 20, ' جمع فضة ونحاس وحديد ورصاص وقصدير إلى وسط كور لنفخ النار عليها لسبكها ، كذلك أجمعكم بغضبي وسخطي وأطرحكم وأسبككم '),
(12576, 'Ezekiel', 26, 22, 21, ' فأجمعكم وأنفخ عليكم في نار غضبي ، فتسبكون في وسطها '),
(12577, 'Ezekiel', 26, 22, 22, ' كما تسبك الفضة في وسط الكور ، كذلك تسبكون في وسطها ، فتعلمون أني أنا الرب سكبت سخطي عليكم '),
(12578, 'Ezekiel', 26, 22, 23, ' وكان إلي كلام الرب قائلا '),
(12579, 'Ezekiel', 26, 22, 24, ' يا ابن آدم ، قل لها : أنت الأرض التي لم تطهر ، لم يمطر عليها في يوم الغضب '),
(12580, 'Ezekiel', 26, 22, 25, ' فتنة أنبيائها في وسطها كأسد مزمجر يخطف الفريسة . أكلوا نفوسا . أخذوا الكنز والنفيس ، أكثروا أراملها في وسطها '),
(12581, 'Ezekiel', 26, 22, 26, ' كهنتها خالفوا شريعتي ونجسوا أقداسي . لم يميزوا بين المقدس والمحلل ، ولم يعلموا الفرق بين النجس والطاهر ، وحجبوا عيونهم عن سبوتي فتدنست في وسطهم '),
(12582, 'Ezekiel', 26, 22, 27, ' رؤساؤها في وسطها كذئاب خاطفة خطفا لسفك الدم ، لإهلاك النفوس لاكتساب كسب '),
(12583, 'Ezekiel', 26, 22, 28, ' وأنبياؤها قد طينوا لهم بالطفال ، رائين باطلا وعارفين لهم كذبا ، قائلين : هكذا قال السيد الرب ، والرب لم يتكلم '),
(12584, 'Ezekiel', 26, 22, 29, ' شعب الأرض ظلموا ظلما ، وغصبوا غصبا ، واضطهدوا الفقير والمسكين ، وظلموا الغريب بغير الحق '),
(12585, 'Ezekiel', 26, 22, 30, ' وطلبت من بينهم رجلا يبني جدارا ويقف في الثغر أمامي عن الأرض لكيلا أخربها ، فلم أجد '),
(12586, 'Ezekiel', 26, 22, 31, ' فسكبت سخطي عليهم . أفنيتهم بنار غضبي . جلبت طريقهم على رؤوسهم ، يقول السيد الرب '),
(12587, 'Ezekiel', 26, 23, 1, ' وكان إلي كلام الرب قائلا '),
(12588, 'Ezekiel', 26, 23, 2, ' يا ابن آدم ، كان امرأتان ابنتا أم واحدة '),
(12589, 'Ezekiel', 26, 23, 3, ' وزنتا بمصر . في صباهما زنتا . هناك دغدغت ثديهما ، وهناك تزغزغت ترائب عذرتهما '),
(12590, 'Ezekiel', 26, 23, 4, ' واسمهما : أهولة الكبيرة ، وأهوليبة أختها . وكانتا لي ، وولدتا بنين وبنات . واسماهما : السامرة أهولة ، وأورشليم أهوليبة '),
(12591, 'Ezekiel', 26, 23, 5, ' وزنت أهولة من تحتي وعشقت محبيها ، أشور الأبطال '),
(12592, 'Ezekiel', 26, 23, 6, ' اللابسين الأسمانجوني ولاة وشحنا ، كلهم شبان شهوة ، فرسان راكبون الخيل '),
(12593, 'Ezekiel', 26, 23, 7, ' فدفعت لهم عقرها لمختاري بني أشور كلهم ، وتنجست بكل من عشقتهم بكل أصنامهم '),
(12594, 'Ezekiel', 26, 23, 8, ' ولم تترك زناها من مصر أيضا ، لأنهم ضاجعوها في صباها ، وزغزغوا ترائب عذرتها وسكبوا عليها زناهم '),
(12595, 'Ezekiel', 26, 23, 9, ' لذلك سلمتها ليد عشاقها ، ليد بني أشور الذين عشقتهم '),
(12596, 'Ezekiel', 26, 23, 10, ' هم كشفوا عورتها . أخذوا بنيها وبناتها ، وذبحوها بالسيف ، فصارت عبرة للنساء . وأجروا عليها حكما '),
(12597, 'Ezekiel', 26, 23, 11, ' فلما رأت أختها أهوليبة ذلك أفسدت في عشقها أكثر منها ، وفي زناها أكثر من زنا أختها '),
(12598, 'Ezekiel', 26, 23, 12, ' عشقت بني أشور الولاة والشحن الأبطال اللابسين أفخر لباس ، فرسانا راكبين الخيل كلهم شبان شهوة '),
(12599, 'Ezekiel', 26, 23, 13, ' فرأيت أنها قد تنجست ، ولكلتيهما طريق واحدة '),
(12600, 'Ezekiel', 26, 23, 14, ' وزادت زناها . ولما نظرت إلى رجال مصورين على الحائط ، صور الكلدانيين مصورة بمغرة '),
(12601, 'Ezekiel', 26, 23, 15, ' منطقين بمناطق على أحقائهم ، عمائمهم مسدولة على رؤوسهم . كلهم في المنظر رؤساء مركبات شبه بني بابل الكلدانيين أرض ميلادهم '),
(12602, 'Ezekiel', 26, 23, 16, ' عشقتهم عند لمح عينيها إياهم ، وأرسلت إليهم رسلا إلى أرض الكلدانيين '),
(12603, 'Ezekiel', 26, 23, 17, ' فأتاها بنو بابل في مضجع الحب ونجسوها بزناهم ، فتنجست بهم ، وجفتهم نفسها '),
(12604, 'Ezekiel', 26, 23, 18, ' وكشفت زناها وكشفت عورتها ، فجفتها نفسي ، كما جفت نفسي أختها '),
(12605, 'Ezekiel', 26, 23, 19, ' وأكثرت زناها بذكرها أيام صباها التي فيها زنت بأرض مصر '),
(12606, 'Ezekiel', 26, 23, 20, ' وعشقت معشوقيهم الذين لحمهم كلحم الحمير ومنيهم كمني الخيل '),
(12607, 'Ezekiel', 26, 23, 21, ' وافتقدت رذيلة صباك بزغزغة المصريين ترائبك لأجل ثدي صباك '),
(12608, 'Ezekiel', 26, 23, 22, ' لأجل ذلك يا أهوليبة ، هكذا قال السيد الرب : هأنذا أهيج عليك عشاقك الذين جفتهم نفسك ، وآتي بهم عليك من كل جهة '),
(12609, 'Ezekiel', 26, 23, 23, ' بني بابل وكل الكلدانيين ، فقود وشوع وقوع ، ومعهم كل بني أشور ، شبان شهوة ، ولاة وشحن كلهم رؤساء مركبات وشهراء . كلهم راكبون الخيل '),
(12610, 'Ezekiel', 26, 23, 24, ' فيأتون عليك بأسلحة مركبات وعجلات ، وبجماعة شعوب يقيمون عليك الترس والمجن والخوذة من حولك ، وأسلم لهم الحكم فيحكمون عليك بأحكامهم '),
(12611, 'Ezekiel', 26, 23, 25, ' وأجعل غيرتي عليك فيعاملونك بالسخط . يقطعون أنفك وأذنيك ، وبقيتك تسقط بالسيف . يأخذون بنيك وبناتك ، وتؤكل بقيتك بالنار '),
(12612, 'Ezekiel', 26, 23, 26, ' وينزعون عنك ثيابك ، ويأخذون أدوات زينتك '),
(12613, 'Ezekiel', 26, 23, 27, ' وأبطل رذيلتك عنك وزناك من أرض مصر ، فلا ترفعين عينيك إليهم ولا تذكرين مصر بعد '),
(12614, 'Ezekiel', 26, 23, 28, ' لأنه هكذا قال السيد الرب : هأنذا أسلمك ليد الذين أبغضتهم ، ليد الذين جفتهم نفسك '),
(12615, 'Ezekiel', 26, 23, 29, ' فيعاملونك بالبغضاء ويأخذون كل تعبك ، ويتركونك عريانة وعارية ، فتنكشف عورة زناك ورذيلتك وزناك '),
(12616, 'Ezekiel', 26, 23, 30, ' أفعل بك هذا لأنك زنيت وراء الأمم ، لأنك تنجست بأصنامهم '),
(12617, 'Ezekiel', 26, 23, 31, ' في طريق أختك سلكت فأدفع كأسها ليدك '),
(12618, 'Ezekiel', 26, 23, 32, ' هكذا قال السيد الرب : إنك تشربين كأس أختك العميقة الكبيرة . تكونين للضحك وللاستهزاء . تسع كثيرا '),
(12619, 'Ezekiel', 26, 23, 33, ' تمتلئين سكرا وحزنا ، كأس التحير والخراب ، كأس أختك السامرة '),
(12620, 'Ezekiel', 26, 23, 34, ' فتشربينها وتمتصينها وتقضمين شقفها وتجتثين ثدييك ، لأني تكلمت ، يقول السيد الرب '),
(12621, 'Ezekiel', 26, 23, 35, ' لذلك هكذا قال السيد الرب : من أجل أنك نسيتني وطرحتني وراء ظهرك ، فتحملي أيضا رذيلتك وزناك '),
(12622, 'Ezekiel', 26, 23, 36, ' وقال الرب لي : يا ابن آدم ، أتحكم على أهولة وأهوليبة ؟ بل أخبرهما برجاساتهما '),
(12623, 'Ezekiel', 26, 29, 4, ' فأجعل خزائم في فكيك وألزق سمك أنهارك بحرشفك ، وأطلعك من وسط أنهارك وكل سمك أنهارك ملزق بحرشفك '),
(12624, 'Ezekiel', 26, 29, 5, ' وأتركك في البرية أنت وجميع سمك أنهارك . على وجه الحقل تسقط فلا تجمع ولا تلم . بذلتك طعاما لوحوش البر ولطيور السماء '),
(12625, 'Ezekiel', 26, 29, 6, ' ويعلم كل سكان مصر أني أنا الرب ، من أجل كونهم عكاز قصب لبيت إسرائيل '),
(12626, 'Ezekiel', 26, 29, 7, ' عند مسكهم بك بالكف ، انكسرت ومزقت لهم كل كتف ، ولما توكأوا عليك انكسرت وقلقلت كل متونهم '),
(12627, 'Ezekiel', 26, 29, 8, ' لذلك هكذا قال السيد الرب : هأنذا أجلب عليك سيفا ، وأستأصل منك الإنسان والحيوان '),
(12628, 'Ezekiel', 26, 29, 9, ' وتكون أرض مصر مقفرة وخربة ، فيعلمون أني أنا الرب ، لأنه قال : النهر لي وأنا عملته '),
(12629, 'Ezekiel', 26, 29, 10, ' لذلك هأنذا عليك وعلى أنهارك ، وأجعل أرض مصر خربا خربة مقفرة ، من مجدل إلى أسوان ، إلى تخم كوش '),
(12630, 'Ezekiel', 26, 29, 11, ' لا تمر فيها رجل إنسان ، ولا تمر فيها رجل بهيمة ، ولا تسكن أربعين سنة '),
(12631, 'Ezekiel', 26, 29, 12, ' وأجعل أرض مصر مقفرة في وسط الأراضي المقفرة ، ومدنها في وسط المدن الخربة تكون مقفرة أربعين سنة . وأشتت المصريين بين الأمم ، وأبددهم في الأراضي '),
(12632, 'Ezekiel', 26, 29, 13, ' لأنه هكذا قال السيد الرب : عند نهاية أربعين سنة أجمع المصريين من الشعوب الذين تشتتوا بينهم '),
(12633, 'Ezekiel', 26, 29, 14, ' وأرد سبي مصر ، وأرجعهم إلى أرض فتروس ، إلى أرض ميلادهم ، ويكونون هناك مملكة حقيرة '),
(12634, 'Ezekiel', 26, 29, 15, ' تكون أحقر الممالك فلا ترتفع بعد على الأمم ، وأقللهم لكيلا يتسلطوا على الأمم '),
(12635, 'Ezekiel', 26, 29, 16, ' فلا تكون بعد معتمدا لبيت إسرائيل ، مذكرة الإثم بانصرافهم وراءهم ، ويعلمون أني أنا السيد الرب '),
(12636, 'Ezekiel', 26, 29, 17, ' وكان في السنة السابعة والعشرين ، في الشهر الأول ، في أول الشهر ، أن كلام الرب كان إلي قائلا '),
(12637, 'Ezekiel', 26, 29, 18, ' يا ابن آدم ، إن نبوخذراصر ملك بابل استخدم جيشه خدمة شديدة على صور . كل رأس قرع ، وكل كتف تجردت ، ولم تكن له ولا لجيشه أجرة من صور لأجل خدمته التي خدم بها عليها '),
(12638, 'Ezekiel', 26, 29, 19, ' لذلك هكذا قال السيد الرب : هأنذا أبذل أرض مصر لنبوخذراصر ملك بابل ، فيأخذ ثروتها ، ويغنم غنيمتها ، وينهب نهبها فتكون أجرة لجيشه '),
(12639, 'Ezekiel', 26, 29, 20, ' قد أعطيته أرض مصر لأجل شغله الذي خدم به ، لأنهم عملوا لأجلي ، يقول السيد الرب '),
(12640, 'Ezekiel', 26, 29, 21, ' في ذلك اليوم أنبت قرنا لبيت إسرائيل . وأجعل لك فتح الفم في وسطهم ، فيعلمون أني أنا الرب '),
(12641, 'Ezekiel', 26, 30, 1, ' وكان إلي كلام الرب قائلا '),
(12642, 'Ezekiel', 26, 30, 2, ' يا ابن آدم تنبأ وقل : هكذا قال السيد الرب : ولولوا : يا لليوم '),
(12643, 'Ezekiel', 26, 30, 3, ' لأن اليوم قريب ، ويوم للرب قريب ، يوم غيم . يكون وقتا للأمم '),
(12644, 'Ezekiel', 26, 30, 4, ' ويأتي سيف على مصر ، ويكون في كوش خوف شديد ، عند سقوط القتلى في مصر ، ويأخذون ثروتها وتهدم أسسها '),
(12645, 'Ezekiel', 26, 30, 5, ' يسقط معهم بالسيف كوش وفوط ولود وكل اللفيف ، وكوب وبنو أرض العهد '),
(12646, 'Ezekiel', 26, 30, 6, ' هكذا قال الرب : ويسقط عاضدو مصر ، وتنحط كبرياء عزتها . من مجدل إلى أسوان يسقطون فيها بالسيف ، يقول السيد الرب '),
(12647, 'Ezekiel', 26, 30, 7, ' فتقفر في وسط الأراضي المقفرة ، وتكون مدنها في وسط المدن الخربة '),
(12648, 'Ezekiel', 26, 30, 8, ' فيعلمون أني أنا الرب عند إضرامي نارا في مصر ، ويكسر جميع أعوانها '),
(12649, 'Ezekiel', 26, 30, 9, ' في ذلك اليوم يخرج من قبلي رسل في سفن لتخويف كوش المطمئنة ، فيأتي عليهم خوف عظيم كما في يوم مصر ، لأنه هوذا يأتي '),
(12650, 'Ezekiel', 26, 30, 10, ' هكذا قال السيد الرب : إني أبيد ثروة مصر بيد نبوخذراصر ملك بابل '),
(12651, 'Ezekiel', 26, 30, 11, ' هو وشعبه معه ، عتاة الأمم يؤتى بهم لخراب الأرض ، فيجردون سيوفهم على مصر ويملأون الأرض من القتلى '),
(12652, 'Ezekiel', 26, 30, 12, ' وأجعل الأنهار يابسة وأبيع الأرض ليد الأشرار ، وأخرب الأرض وملأها بيد الغرباء . أنا الرب تكلمت '),
(12653, 'Ezekiel', 26, 30, 13, ' هكذا قال السيد الرب : وأبيد الأصنام وأبطل الأوثان من نوف . ولا يكون بعد رئيس من أرض مصر ، وألقي الرعب في أرض مصر '),
(12654, 'Ezekiel', 26, 30, 14, ' وأخرب فتروس ، وأضرم نارا في صوعن ، وأجري أحكاما في نو '),
(12655, 'Ezekiel', 26, 30, 15, ' وأسكب غضبي على سين ، حصن مصر ، وأستأصل جمهور نو '),
(12656, 'Ezekiel', 26, 30, 16, ' وأضرم نارا في مصر . سين تتوجع توجعا ، ونو تكون للتمزيق ، ولنوف ضيقات كل يوم '),
(12657, 'Ezekiel', 26, 30, 17, ' شبان آون وفيبستة يسقطون بالسيف ، وهما تذهبان إلى السبي '),
(12658, 'Ezekiel', 26, 30, 18, ' ويظلم النهار في تحفنحيس عند كسري أنيار مصر هناك . وتبطل فيها كبرياء عزها . أما هي فتغشاها سحابة ، وتذهب بناتها إلى السبي '),
(12659, 'Ezekiel', 26, 30, 19, ' فأجري أحكاما في مصر ، فيعلمون أني أنا الرب '),
(12660, 'Ezekiel', 26, 30, 20, ' وكان في السنة الحادية عشرة ، في الشهر الأول ، في السابع من الشهر ، أن كلام الرب صار إلي قائلا '),
(12661, 'Ezekiel', 26, 30, 21, ' يا ابن آدم ، إني كسرت ذراع فرعون ملك مصر ، وها هي لن تجبر بوضع رفائد ولا بوضع عصابة لتجبر فتمسك السيف '),
(12662, 'Ezekiel', 26, 30, 22, ' لذلك هكذا قال السيد الرب : هأنذا على فرعون ملك مصر ، فأكسر ذراعيه القوية والمكسورة ، وأسقط السيف من يده '),
(12663, 'Ezekiel', 26, 30, 23, ' وأشتت المصريين بين الأمم ، وأذريهم في الأراضي '),
(12664, 'Ezekiel', 26, 30, 24, ' وأشدد ذراعي ملك بابل وأجعل سيفي في يده ، وأكسر ذراعي فرعون فيئن قدامه أنين الجريح '),
(12665, 'Ezekiel', 26, 30, 25, ' وأشدد ذراعي ملك بابل ، أما ذراعا فرعون فتسقطان ، فيعلمون أني أنا الرب حين أجعل سيفي في يد ملك بابل ، فيمده على أرض مصر '),
(12666, 'Ezekiel', 26, 30, 26, ' وأشتت المصريين بين الأمم وأذريهم في الأراضي ، فيعلمون أني أنا الرب '),
(12667, 'Ezekiel', 26, 31, 1, ' وكان في السنة الحادية عشرة ، في الشهر الثالث ، في أول الشهر ، أن كلام الرب كان إلي قائلا '),
(12668, 'Ezekiel', 26, 31, 2, ' يا ابن آدم ، قل لفرعون ملك مصر وجمهوره : من أشبهت في عظمتك '),
(12669, 'Ezekiel', 26, 31, 3, ' هوذا أعلى الأرز في لبنان جميل الأغصان وأغبى الظل ، وقامته طويلة ، وكان فرعه بين الغيوم '),
(12670, 'Ezekiel', 26, 31, 4, ' قد عظمته المياه ، ورفعه الغمر . أنهاره جرت من حول مغرسه ، وأرسلت جداولها إلى كل أشجار الحقل '),
(12671, 'Ezekiel', 26, 31, 5, ' فلذلك ارتفعت قامته على جميع أشجار الحقل ، وكثرت أغصانه ، وطالت فروعه لكثرة المياه إذ نبت '),
(12672, 'Ezekiel', 26, 31, 6, ' وعششت في أغصانه كل طيور السماء ، وتحت فروعه ولدت كل حيوان البر ، وسكن تحت ظله كل الأمم العظيمة '),
(12673, 'Ezekiel', 26, 31, 7, ' فكان جميلا في عظمته وفي طول قضبانه ، لأن أصله كان على مياه كثيرة '),
(12674, 'Ezekiel', 26, 31, 8, ' الأرز في جنة الله لم يفقه ، السرو لم يشبه أغصانه ، والدلب لم يكن مثل فروعه . كل الأشجار في جنة الله لم تشبهه في حسنه '),
(12675, 'Ezekiel', 26, 31, 9, ' جعلته جميلا بكثرة قضبانه ، حتى حسدته كل أشجار عدن التي في جنة الله '),
(12676, 'Ezekiel', 26, 31, 10, ' لذلك هكذا قال السيد الرب : من أجل أنك ارتفعت قامتك ، وقد جعل فرعه بين الغيوم ، وارتفع قلبه بعلوه '),
(12677, 'Ezekiel', 26, 31, 11, ' أسلمته إلى يد قوي الأمم ، فيفعل به فعلا . لشره طردته '),
(12678, 'Ezekiel', 26, 31, 12, ' ويستأصله الغرباء عتاة الأمم ، ويتركونه ، فتتساقط قضبانه على الجبال وفي جميع الأودية ، وتنكسر قضبانه عند كل أنهار الأرض ، وينزل عن ظله كل شعوب الأرض ، ويتركونه '),
(12679, 'Ezekiel', 26, 31, 13, ' على هشيمه تستقر جميع طيور السماء ، وجميع حيوان البر تكون على قضبانه '),
(12680, 'Ezekiel', 26, 31, 14, ' لكيلا ترتفع شجرة ما وهي على المياه لقامتها ، ولا تجعل فرعها بين الغيوم ، ولا تقوم بلوطاتها في ارتفاعها كل شاربة ماء ، لأنها قد أسلمت جميعا إلى الموت ، إلى الأرض السفلى ، في وسط بني آدم مع الهابطين في الجب '),
(12681, 'Ezekiel', 26, 31, 15, ' هكذا قال السيد الرب : في يوم نزوله إلى الهاوية أقمت نوحا . كسوت عليه الغمر ، ومنعت أنهاره ، وفنيت المياه الكثيرة ، وأحزنت لبنان عليه ، وكل أشجار الحقل ذبلت عليه '),
(12682, 'Ezekiel', 26, 31, 16, ' من صوت سقوطه أرجفت الأمم عند إنزالي إياه إلى الهاوية مع الهابطين في الجب ، فتتعزى في الأرض السفلى كل أشجار عدن ، مختار لبنان وخياره كل شاربة ماء '),
(12683, 'Ezekiel', 26, 31, 17, ' هم أيضا نزلوا إلى الهاوية معه ، إلى القتلى بالسيف ، وزرعه الساكنون تحت ظله في وسط الأمم '),
(12684, 'Ezekiel', 26, 31, 18, ' من أشبهت في المجد والعظمة هكذا بين أشجار عدن ؟ ستحدر مع أشجار عدن إلى الأرض السفلى ، وتضطجع بين الغلف مع المقتولين بالسيف . هذا فرعون وكل جمهوره ، يقول السيد الرب '),
(12685, 'Ezekiel', 26, 32, 1, ' وكان في السنة الثانية عشرة ، في الشهر الثاني عشر ، في أول الشهر ، أن كلام الرب صار إلي قائلا '),
(12686, 'Ezekiel', 26, 32, 2, ' يا ابن آدم ، ارفع مرثاة على فرعون ملك مصر وقل له : أشبهت شبل الأمم وأنت نظير تمساح في البحار . اندفقت بأنهارك ، وكدرت الماء برجليك ، وعكرت أنهارهم '),
(12687, 'Ezekiel', 26, 32, 3, ' هكذا قال السيد الرب : إني أبسط عليك شبكتي مع جماعة شعوب كثيرة ، وهم يصعدونك في مجزفتي '),
(12688, 'Ezekiel', 26, 32, 4, ' وأتركك على الأرض ، وأطرحك على وجه الحقل ، وأقر عليك كل طيور السماء ، وأشبع منك وحوش الأرض كلها '),
(12689, 'Ezekiel', 26, 32, 5, ' وألقي لحمك على الجبال ، وأملأ الأودية من جيفك '),
(12690, 'Ezekiel', 26, 32, 6, ' وأسقي أرض فيضانك من دمك إلى الجبال ، وتمتلئ منك الآفاق '),
(12691, 'Ezekiel', 26, 32, 7, ' وعند إطفائي إياك أحجب السماوات ، وأظلم نجومها ، وأغشي الشمس بسحاب ، والقمر لا يضيء ضوءه '),
(12692, 'Ezekiel', 26, 32, 8, ' وأظلم فوقك كل أنوار السماء المنيرة ، وأجعل الظلمة على أرضك ، يقول السيد الرب '),
(12693, 'Ezekiel', 26, 32, 9, ' وأغم قلوب شعوب كثيرين عند إتياني بكسرك بين الأمم في أراض لم تعرفها '),
(12694, 'Ezekiel', 26, 32, 10, ' وأحير منك شعوبا كثيرين ، ملوكهم يقشعرون عليك اقشعرارا عندما أخطر بسيفي قدام وجوههم ، فيرجفون كل لحظة ، كل واحد على نفسه في يوم سقوطك '),
(12695, 'Ezekiel', 26, 32, 11, ' لأنه هكذا قال السيد الرب : سيف ملك بابل يأتي عليك '),
(12696, 'Ezekiel', 26, 32, 12, ' بسيوف الجبابرة أسقط جمهورك . كلهم عتاة الأمم ، فيسلبون كبرياء مصر ، ويهلك كل جمهورها '),
(12697, 'Ezekiel', 26, 32, 13, ' وأبيد جميع بهائمها عن المياه الكثيرة ، فلا تكدرها من بعد رجل إنسان ، ولا تعكرها أظلاف بهيمة '),
(12698, 'Ezekiel', 26, 32, 14, ' حينئذ أنضب مياههم وأجري أنهارهم كالزيت ، يقول السيد الرب '),
(12699, 'Ezekiel', 26, 32, 15, ' حين أجعل أرض مصر خرابا ، وتخلو الأرض من ملئها . عند ضربي جميع سكانها يعلمون أني أنا الرب '),
(12700, 'Ezekiel', 26, 32, 16, ' هذه مرثاة يرثون بها . بنات الأمم ترثو بها . على مصر وعلى كل جمهورها ترثو بها ، يقول السيد الرب '),
(12701, 'Ezekiel', 26, 32, 17, ' وكان في السنة الثانية عشرة ، في الخامس عشر من الشهر ، أن كلام الرب كان إلي قائلا '),
(12702, 'Ezekiel', 26, 32, 18, ' يا ابن آدم ، ولول على جمهور مصر ، وأحدره هو وبنات الأمم العظيمة إلى الأرض السفلى مع الهابطين في الجب '),
(12703, 'Ezekiel', 26, 32, 19, ' ممن نعمت أكثر ؟ انزل واضطجع مع الغلف '),
(12704, 'Ezekiel', 26, 32, 20, ' يسقطون في وسط القتلى بالسيف . قد أسلم السيف . امسكوها مع كل جمهورها '),
(12705, 'Ezekiel', 26, 32, 21, ' يكلمه أقوياء الجبابرة من وسط الهاوية مع أعوانه . قد نزلوا ، اضطجعوا غلفا قتلى بالسيف '),
(12706, 'Ezekiel', 26, 32, 22, ' هناك أشور وكل جماعتها . قبوره من حوله . كلهم قتلى ساقطون بالسيف '),
(12707, 'Ezekiel', 26, 32, 23, ' الذين جعلت قبورهم في أسافل الجب ، وجماعتها حول قبرها ، كلهم قتلى ساقطون بالسيف ، الذين جعلوا رعبا في أرض الأحياء '),
(12708, 'Ezekiel', 26, 32, 24, ' هناك عيلام وكل جمهورها حول قبرها ، كلهم قتلى ساقطون بالسيف ، الذين هبطوا غلفا إلى الأرض السفلى ، الذين جعلوا رعبهم في أرض الأحياء . فحملوا خزيهم مع الهابطين في الجب '),
(12709, 'Ezekiel', 26, 32, 25, ' قد جعلوا لها مضجعا بين القتلى ، مع كل جمهورها . حوله قبورهم كلهم غلف قتلى بالسيف ، مع أنه قد جعل رعبهم في أرض الأحياء . قد حملوا خزيهم مع الهابطين في الجب . قد جعل في وسط القتلى '),
(12710, 'Ezekiel', 26, 32, 26, ' هناك ماشك وتوبال وكل جمهورها ، حوله قبورها . كلهم غلف قتلى بالسيف ، مع أنهم جعلوا رعبهم في أرض الأحياء '),
(12711, 'Ezekiel', 26, 32, 27, ' ولا يضطجعون مع الجبابرة الساقطين من الغلف النازلين إلى الهاوية بأدوات حربهم ، وقد وضعت سيوفهم تحت رؤوسهم ، فتكون آثامهم على عظامهم مع أنهم رعب الجبابرة في أرض الأحياء '),
(12712, 'Ezekiel', 26, 32, 28, ' أما أنت ففي وسط الغلف تنكسر وتضطجع مع القتلى بالسيف '),
(12713, 'Ezekiel', 26, 32, 29, ' هناك أدوم وملوكها وكل رؤسائها الذين مع جبروتهم قد ألقوا مع القتلى بالسيف ، فيضطجعون مع الغلف ومع الهابطين في الجب '),
(12714, 'Ezekiel', 26, 32, 30, ' هناك أمراء الشمال كلهم وجميع الصيدونيين الهابطين مع القتلى برعبهم ، خزوا من جبروتهم واضطجعوا غلفا مع قتلى السيف ، وحملوا خزيهم مع الهابطين إلى الجب '),
(12715, 'Ezekiel', 26, 32, 31, ' يراهم فرعون ويتعزى عن كل جمهوره . قتلى بالسيف فرعون وكل جمهوره ، يقول السيد الرب '),
(12716, 'Ezekiel', 26, 32, 32, ' لأني جعلت رعبه في أرض الأحياء ، فيضجع بين الغلف مع قتلى السيف ، فرعون وكل جمهوره ، يقول السيد الرب '),
(12717, 'Ezekiel', 26, 33, 1, ' وكان إلي كلام الرب قائلا '),
(12718, 'Ezekiel', 26, 33, 2, ' يا ابن آدم ، كلم بني شعبك وقل لهم : إذا جلبت السيف على أرض ، فإن أخذ شعب الأرض رجلا من بينهم وجعلوه رقيبا لهم '),
(12719, 'Ezekiel', 26, 33, 3, ' فإذا رأى السيف مقبلا على الأرض نفخ في البوق وحذر الشعب '),
(12720, 'Ezekiel', 26, 33, 4, ' وسمع السامع صوت البوق ولم يتحذر ، فجاء السيف وأخذه ، فدمه يكون على رأسه '),
(12721, 'Ezekiel', 26, 33, 5, ' سمع صوت البوق ولم يتحذر ، فدمه يكون على نفسه . لو تحذر لخلص نفسه '),
(12722, 'Ezekiel', 26, 33, 6, ' فإن رأى الرقيب السيف مقبلا ولم ينفخ في البوق ولم يتحذر الشعب ، فجاء السيف وأخذ نفسا منهم ، فهو قد أخذ بذنبه ، أما دمه فمن يد الرقيب أطلبه '),
(12723, 'Ezekiel', 26, 33, 7, ' وأنت يا ابن آدم ، فقد جعلتك رقيبا لبيت إسرائيل ، فتسمع الكلام من فمي ، وتحذرهم من قبلي '),
(12724, 'Ezekiel', 26, 33, 8, ' إذا قلت للشرير : يا شرير موتا تموت . فإن لم تتكلم لتحذر الشرير من طريقه ، فذلك الشرير يموت بذنبه ، أما دمه فمن يدك أطلبه '),
(12725, 'Ezekiel', 26, 33, 9, ' وإن حذرت الشرير من طريقه ليرجع عنه ، ولم يرجع عن طريقه ، فهو يموت بذنبه . أما أنت فقد خلصت نفسك '),
(12726, 'Ezekiel', 26, 33, 10, ' وأنت يا ابن آدم فكلم بيت إسرائيل وقل : أنتم تتكلمون هكذا قائلين : إن معاصينا وخطايانا علينا ، وبها نحن فانون ، فكيف نحيا '),
(12727, 'Ezekiel', 26, 33, 11, ' قل لهم : حي أنا ، يقول السيد الرب ، إني لا أسر بموت الشرير ، بل بأن يرجع الشرير عن طريقه ويحيا . ارجعوا ، ارجعوا عن طرقكم الرديئة فلماذا تموتون يا بيت إسرائيل '),
(12728, 'Ezekiel', 26, 33, 12, ' وأنت يا ابن آدم ، فقل لبني شعبك : إن بر البار لا ينجيه في يوم معصيته ، والشرير لا يعثر بشره في يوم رجوعه عن شره . ولا يستطيع البار أن يحيا ببره في يوم خطيئته '),
(12729, 'Ezekiel', 26, 33, 13, ' إذا قلت للبار : حياة تحيا . فاتكل هو على بره وأثم ، فبره كله لا يذكر ، بل بإثمه الذي فعله يموت '),
(12730, 'Ezekiel', 26, 33, 14, ' وإذا قلت للشرير : موتا تموت . فإن رجع عن خطيته وعمل بالعدل والحق '),
(12731, 'Ezekiel', 26, 33, 15, ' إن رد الشرير الرهن وعوض عن المغتصب ، وسلك في فرائض الحياة بلا عمل إثم ، فإنه حياة يحيا . لا يموت '),
(12732, 'Ezekiel', 26, 33, 16, ' كل خطيته التي أخطأ بها لا تذكر عليه . عمل بالعدل والحق فيحيا حياة '),
(12733, 'Ezekiel', 26, 33, 17, ' وأبناء شعبك يقولون : ليست طريق الرب مستوية . بل هم طريقهم غير مستوية '),
(12734, 'Ezekiel', 26, 33, 18, ' عند رجوع البار عن بره وعند عمله إثما فإنه يموت به '),
(12735, 'Ezekiel', 26, 33, 19, ' وعند رجوع الشرير عن شره وعند عمله بالعدل والحق ، فإنه يحيا بهما '),
(12736, 'Ezekiel', 26, 33, 20, ' وأنتم تقولون : إن طريق الرب غير مستوية . إني أحكم على كل واحد منكم كطرقه يا بيت إسرائيل '),
(12737, 'Ezekiel', 26, 33, 21, ' وكان في السنة الثانية عشرة من سبينا ، في الشهر العاشر ، في الخامس من الشهر ، أنه جاء إلي منفلت من أورشليم ، فقال : قد ضربت المدينة '),
(12738, 'Ezekiel', 26, 33, 22, ' وكانت يد الرب علي مساء قبل مجيء المنفلت ، وفتحت فمي حتى جاء إلي صباحا ، فانفتح فمي ولم أكن بعد أبكم '),
(12739, 'Ezekiel', 26, 33, 23, ' فكان إلي كلام الرب قائلا '),
(12740, 'Ezekiel', 26, 33, 24, ' يا ابن آدم ، إن الساكنين في هذه الخرب في أرض إسرائيل يتكلمون قائلين : إن إبراهيم كان واحدا وقد ورث الأرض ، ونحن كثيرون ، لنا أعطيت الأرض ميراثا '),
(12741, 'Ezekiel', 26, 33, 25, ' لذلك قل لهم : هكذا قال السيد الرب : تأكلون بالدم وترفعون أعينكم إلى أصنامكم وتسفكون الدم ، أفترثون الأرض '),
(12742, 'Ezekiel', 26, 33, 26, ' وقفتم على سيفكم ، فعلتم الرجس ، وكل منكم نجس امرأة صاحبه ، أفترثون الأرض '),
(12743, 'Ezekiel', 26, 33, 27, ' قل لهم : هكذا قال السيد الرب : حي أنا ، إن الذين في الخرب يسقطون بالسيف ، والذي هو على وجه الحقل أبذله للوحش مأكلا ، والذين في الحصون وفي المغاير يموتون بالوبإ '),
(12744, 'Ezekiel', 26, 33, 28, ' فأجعل الأرض خربة مقفرة ، وتبطل كبرياء عزتها ، وتخرب جبال إسرائيل بلا عابر '),
(12745, 'Ezekiel', 26, 33, 29, ' فيعلمون أني أنا الرب حين أجعل الأرض خربة مقفرة على كل رجاساتهم التي فعلوها '),
(12746, 'Ezekiel', 26, 33, 30, ' وأنت يا ابن آدم ، فإن بني شعبك يتكلمون عليك بجانب الجدران ، وفي أبواب البيوت ، ويتكلم الواحد مع الآخر ، الرجل مع أخيه قائلين : هلم اسمعوا ما هو الكلام الخارج من عند الرب '),
(12747, 'Ezekiel', 26, 33, 31, ' ويأتون إليك كما يأتي الشعب ، ويجلسون أمامك كشعبي ، ويسمعون كلامك ولا يعملون به ، لأنهم بأفواههم يظهرون أشواقا وقلبهم ذاهب وراء كسبهم '),
(12748, 'Ezekiel', 26, 33, 32, ' وها أنت لهم كشعر أشواق لجميل الصوت يحسن العزف ، فيسمعون كلامك ولا يعملون به '),
(12749, 'Ezekiel', 26, 33, 33, ' وإذا جاء هذا ، لأنه يأتي ، فيعلمون أن نبيا كان في وسطهم '),
(12750, 'Ezekiel', 26, 34, 1, ' وكان إلي كلام الرب قائلا '),
(12751, 'Ezekiel', 26, 34, 2, ' يا ابن آدم ، تنبأ على رعاة إسرائيل ، تنبأ وقل لهم : هكذا قال السيد الرب للرعاة : ويل لرعاة إسرائيل الذين كانوا يرعون أنفسهم . ألا يرعى الرعاة الغنم '),
(12752, 'Ezekiel', 26, 34, 3, ' تأكلون الشحم ، وتلبسون الصوف وتذبحون السمين ، ولا ترعون الغنم '),
(12753, 'Ezekiel', 26, 34, 4, ' المريض لم تقووه ، والمجروح لم تعصبوه ، والمكسور لم تجبروه ، والمطرود لم تستردوه ، والضال لم تطلبوه ، بل بشدة وبعنف تسلطتم عليهم '),
(12754, 'Ezekiel', 26, 34, 5, ' فتشتتت بلا راع وصارت مأكلا لجميع وحوش الحقل ، وتشتتت '),
(12755, 'Ezekiel', 26, 34, 6, ' ضلت غنمي في كل الجبال ، وعلى كل تل عال ، وعلى كل وجه الأرض . تشتتت غنمي ولم يكن من يسأل أو يفتش '),
(12756, 'Ezekiel', 26, 34, 7, ' فلذلك أيها الرعاة اسمعوا كلام الرب '),
(12757, 'Ezekiel', 26, 34, 8, ' حي أنا ، يقول السيد الرب ، من حيث إن غنمي صارت غنيمة وصارت غنمي مأكلا لكل وحش الحقل ، إذ لم يكن راع ولا سأل رعاتي عن غنمي ، ورعى الرعاة أنفسهم ولم يرعوا غنمي '),
(12758, 'Ezekiel', 26, 34, 9, ' فلذلك أيها الرعاة اسمعوا كلام الرب '),
(12759, 'Ezekiel', 26, 34, 10, ' هكذا قال السيد الرب : هأنذا على الرعاة وأطلب غنمي من يدهم ، وأكفهم عن رعي الغنم ، ولا يرعى الرعاة أنفسهم بعد ، فأخلص غنمي من أفواههم فلا تكون لهم مأكلا '),
(12760, 'Ezekiel', 26, 34, 11, ' لأنه هكذا قال السيد الرب : هأنذا أسأل عن غنمي وأفتقدها '),
(12761, 'Ezekiel', 26, 34, 12, ' كما يفتقد الراعي قطيعه يوم يكون في وسط غنمه المشتتة ، هكذا أفتقد غنمي وأخلصها من جميع الأماكن التي تشتتت إليها في يوم الغيم والضباب '),
(12762, 'Ezekiel', 26, 34, 13, ' وأخرجها من الشعوب وأجمعها من الأراضي ، وآتي بها إلى أرضها وأرعاها على جبال إسرائيل وفي الأودية وفي جميع مساكن الأرض '),
(12763, 'Ezekiel', 26, 34, 14, ' أرعاها في مرعى جيد ، ويكون مراحها على جبال إسرائيل العالية . هنالك تربض في مراح حسن ، وفي مرعى دسم يرعون على جبال إسرائيل '),
(12764, 'Ezekiel', 26, 34, 15, ' أنا أرعى غنمي وأربضها ، يقول السيد الرب '),
(12765, 'Ezekiel', 26, 34, 16, ' وأطلب الضال ، وأسترد المطرود ، وأجبر الكسير ، وأعصب الجريح ، وأبيد السمين والقوي ، وأرعاها بعدل '),
(12766, 'Ezekiel', 26, 34, 17, ' وأنتم يا غنمي ، فهكذا قال السيد الرب : هأنذا أحكم بين شاة وشاة ، بين كباش وتيوس '),
(12767, 'Ezekiel', 26, 34, 18, ' أهو صغير عندكم أن ترعوا المرعى الجيد ، وبقية مراعيكم تدوسونها بأرجلكم ، وأن تشربوا من المياه العميقة ، والبقية تكدرونها بأقدامكم '),
(12768, 'Ezekiel', 26, 34, 19, ' وغنمي ترعى من دوس أقدامكم ، وتشرب من كدر أرجلكم '),
(12769, 'Ezekiel', 26, 23, 37, ' لأنهما قد زنتا وفي أيديهما دم ، وزنتا بأصنامهما وأيضا أجازتا بنيهما الذين ولدتاهم لي النار أكلا لها '),
(12770, 'Ezekiel', 26, 23, 38, ' وفعلتا أيضا بي هذا : نجستا مقدسي في ذلك اليوم ودنستا سبوتي '),
(12771, 'Ezekiel', 26, 23, 39, ' ولما ذبحتا بنيهما لأصنامهما ، أتتا في ذلك اليوم إلى مقدسي لتنجساه . فهوذا هكذا فعلتا في وسط بيتي '),
(12772, 'Ezekiel', 26, 23, 40, ' بل أرسلتما إلى رجال آتين من بعيد . الذين أرسل إليهم رسول فهوذا جاءوا . هم الذين لأجلهم استحممت وكحلت عينيك وتحليت بالحلي '),
(12773, 'Ezekiel', 26, 23, 41, ' وجلست على سرير فاخر أمامه مائدة منضضة ، ووضعت عليها بخوري وزيتي '),
(12774, 'Ezekiel', 26, 23, 42, ' وصوت جمهور مترفهين معها ، مع أناس من رعاع الخلق . أتي بسكارى من البرية ، الذين جعلوا أسورة على أيديهما وتاج جمال على رؤوسهما '),
(12775, 'Ezekiel', 26, 23, 43, ' فقلت عن البالية في الزنا : آلآن يزنون زنا معها وهي '),
(12776, 'Ezekiel', 26, 23, 44, ' فدخلوا عليها كما يدخل على امرأة زانية . هكذا دخلوا على أهولة وعلى أهوليبة المرأتين الزانيتين '),
(12777, 'Ezekiel', 26, 23, 45, ' والرجال الصديقون هم يحكمون عليهما حكم زانية وحكم سفاكة الدم ، لأنهما زانيتان وفي أيديهما دم '),
(12778, 'Ezekiel', 26, 23, 46, ' لأنه هكذا قال السيد الرب : إني أصعد عليهما جماعة وأسلمهما للجور والنهب '),
(12779, 'Ezekiel', 26, 23, 47, ' وترجمهما الجماعة بالحجارة ، ويقطعونهما بسيوفهم ، ويذبحون أبناءهما وبناتهما ، ويحرقون بيوتهما بالنار '),
(12780, 'Ezekiel', 26, 23, 48, ' فأبطل الرذيلة من الأرض ، فتتأدب جميع النساء ولا يفعلن مثل رذيلتكما '),
(12781, 'Ezekiel', 26, 23, 49, ' ويردون عليكما رذيلتكما ، فتحملان خطايا أصنامكما ، وتعلمان أني أنا السيد الرب '),
(12782, 'Ezekiel', 26, 24, 1, ' وكان كلام الرب إلي في السنة التاسعة ، في الشهر العاشر ، في العاشر من الشهر قائلا '),
(12783, 'Ezekiel', 26, 24, 2, ' يا ابن آدم ، اكتب لنفسك اسم اليوم ، هذا اليوم بعينه . فإن ملك بابل قد اقترب إلى أورشليم هذا اليوم بعينه '),
(12784, 'Ezekiel', 26, 24, 3, ' واضرب مثلا للبيت المتمرد وقل لهم : هكذا قال السيد الرب : ضع القدر . ضعها وأيضا صب فيها ماء '),
(12785, 'Ezekiel', 26, 24, 4, ' اجمع إليها قطعها ، كل قطعة طيبة : الفخذ والكتف . املأوها بخيار العظام '),
(12786, 'Ezekiel', 26, 24, 5, ' خذ من خيار الغنم وكومة العظام تحتها . أغلها إغلاء فتسلق أيضا عظامها في وسطها '),
(12787, 'Ezekiel', 26, 24, 6, ' لذلك هكذا قال السيد الرب : ويل لمدينة الدماء ، القدر التي فيها زنجارها ، وما خرج منها زنجارها . أخرجوها قطعة قطعة . لا تقع عليها قرعة '),
(12788, 'Ezekiel', 26, 24, 7, ' لأن دمها في وسطها . قد وضعته على ضح الصخر . لم ترقه على الأرض لتواريه بالتراب '),
(12789, 'Ezekiel', 26, 24, 8, ' لصعود الغضب ، لتنقم نقمة ، وضعت دمها على ضح الصخر لئلا يوارى '),
(12790, 'Ezekiel', 26, 24, 9, ' لذلك هكذا قال السيد الرب : ويل لمدينة الدماء . إني أنا أعظم كومتها '),
(12791, 'Ezekiel', 26, 24, 10, ' كثر الحطب ، أضرم النار ، أنضج اللحم ، تبله تتبيلا ، ولتحرق العظام '),
(12792, 'Ezekiel', 26, 24, 11, ' ثم ضعها فارغة على الجمر ليحمى نحاسها ويحرق ، فيذوب قذرها فيها ويفنى زنجارها '),
(12793, 'Ezekiel', 26, 24, 12, ' بمشقات تعبت ولم تخرج منها كثرة زنجارها . في النار زنجارها '),
(12794, 'Ezekiel', 26, 24, 13, ' في نجاستك رذيلة لأني طهرتك فلم تطهري ، ولن تطهري بعد من نجاستك حتى أحل غضبي عليك '),
(12795, 'Ezekiel', 26, 24, 14, ' أنا الرب تكلمت . يأتي فأفعله . لا أطلق ولا أشفق ولا أندم . حسب طرقك وحسب أعمالك يحكمون عليك ، يقول السيد الرب '),
(12796, 'Ezekiel', 26, 24, 15, ' وكان إلي كلام الرب قائلا '),
(12797, 'Ezekiel', 26, 24, 16, ' يا ابن آدم ، هأنذا آخذ عنك شهوة عينيك بضربة ، فلا تنح ولا تبك ولا تنزل دموعك '),
(12798, 'Ezekiel', 26, 24, 17, ' تنهد ساكتا . لا تعمل مناحة على أموات . لف عصابتك عليك ، واجعل نعليك في رجليك ، ولا تغط شاربيك ، ولا تأكل من خبز الناس '),
(12799, 'Ezekiel', 26, 24, 18, ' فكلمت الشعب صباحا وماتت زوجتي مساء . وفعلت في الغد كما أمرت '),
(12800, 'Ezekiel', 26, 24, 19, ' فقال لي الشعب : ألا تخبرنا ما لنا وهذه التي أنت صانعها '),
(12801, 'Ezekiel', 26, 24, 20, ' فأجبتهم : قد كان إلي كلام الرب قائلا '),
(12802, 'Ezekiel', 26, 24, 21, ' كلم بيت إسرائيل : هكذا قال السيد الرب : هأنذا منجس مقدسي فخر عزكم ، شهوة أعينكم ولذة نفوسكم . وأبناؤكم وبناتكم الذين خلفتم يسقطون بالسيف '),
(12803, 'Ezekiel', 26, 24, 22, ' وتفعلون كما فعلت : لا تغطون شواربكم ولا تأكلون من خبز الناس '),
(12804, 'Ezekiel', 26, 24, 23, ' وتكون عصائبكم على رؤوسكم ، ونعالكم في أرجلكم . لا تنوحون ولا تبكون وتفنون بآثامكم . تئنون بعضكم على بعض '),
(12805, 'Ezekiel', 26, 24, 24, ' ويكون حزقيال لكم آية . مثل كل ما صنع تصنعون . إذا جاء هذا ، تعلمون أني أنا السيد الرب '),
(12806, 'Ezekiel', 26, 24, 25, ' وأنت يا ابن آدم ، أفلا يكون في يوم آخذ عنهم عزهم ، سرور فخرهم ، شهوة عيونهم ورفعة نفسهم : أبناءهم وبناتهم '),
(12807, 'Ezekiel', 26, 24, 26, ' أن يأتي إليك في ذلك اليوم المنفلت ليسمع أذنيك '),
(12808, 'Ezekiel', 26, 24, 27, ' في ذلك اليوم ينفتح فمك للمنفلت وتتكلم ، ولا تكون من بعد أبكم . وتكون لهم آية ، فيعلمون أني أنا الرب '),
(12809, 'Ezekiel', 26, 25, 1, ' وكان إلي كلام الرب قائلا '),
(12810, 'Ezekiel', 26, 25, 2, ' يا ابن آدم ، اجعل وجهك نحو بني عمون وتنبأ عليهم '),
(12811, 'Ezekiel', 26, 25, 3, ' وقل لبني عمون : اسمعوا كلام السيد الرب : هكذا قال السيد الرب : من أجل أنك قلت : هه على مقدسي لأنه تنجس ، وعلى أرض إسرائيل لأنها خربت ، وعلى بيت يهوذا لأنهم ذهبوا إلى السبي '),
(12812, 'Ezekiel', 26, 25, 4, ' فلذلك هأنذا أسلمك لبني المشرق ملكا ، فيقيمون صيرهم فيك ، ويجعلون مساكنهم فيك . هم يأكلون غلتك وهم يشربون لبنك '),
(12813, 'Ezekiel', 26, 25, 5, ' وأجعل ربة مناخا للإبل ، وبني عمون مربضا للغنم ، فتعلمون أني أنا الرب '),
(12814, 'Ezekiel', 26, 25, 6, ' لأنه هكذا قال السيد الرب : من أجل أنك صفقت بيديك وخبطت برجليك وفرحت بكل إهانتك للموت على أرض إسرائيل '),
(12815, 'Ezekiel', 26, 25, 7, ' فلذلك هأنذا أمد يدي عليك وأسلمك غنيمة للأمم ، وأستأصلك من الشعوب ، وأبيدك من الأراضي . أخربك ، فتعلم أني أنا الرب '),
(12816, 'Ezekiel', 26, 25, 8, ' هكذا قال السيد الرب : من أجل أن موآب وسعير يقولون : هوذا بيت يهوذا مثل كل الأمم '),
(12817, 'Ezekiel', 26, 25, 9, ' لذلك هأنذا أفتح جانب موآب من المدن ، من مدنه من أقصاها ، بهاء الأرض ، بيت بشيموت وبعل معون وقريتايم '),
(12818, 'Ezekiel', 26, 25, 10, ' لبني المشرق على بني عمون ، وأجعلهم ملكا ، لكيلا يذكر بنو عمون بين الأمم '),
(12819, 'Ezekiel', 26, 25, 11, ' وبموآب أجري أحكاما ، فيعلمون أني أنا الرب '),
(12820, 'Ezekiel', 26, 25, 12, ' هكذا قال السيد الرب : من أجل أن أدوم قد عمل بالانتقام على بيت يهوذا وأساء إساءة وانتقم منه '),
(12821, 'Ezekiel', 26, 25, 13, ' لذلك هكذا قال السيد الرب : وأمد يدي على أدوم ، وأقطع منها الإنسان والحيوان ، وأصيرها خرابا . من التيمن وإلى ددان يسقطون بالسيف '),
(12822, 'Ezekiel', 26, 25, 14, ' وأجعل نقمتي في أدوم بيد شعبي إسرائيل ، فيفعلون بأدوم كغضبي وكسخطي ، فيعرفون نقمتي ، يقول السيد الرب '),
(12823, 'Ezekiel', 26, 25, 15, ' هكذا قال السيد الرب : من أجل أن الفلسطينيين قد عملوا بالانتقام ، وانتقموا نقمة بالإهانة إلى الموت للخراب من عداوة أبدية '),
(12824, 'Ezekiel', 26, 25, 16, ' فلذلك هكذا قال السيد الرب : هأنذا أمد يدي على الفلسطينيين وأستأصل الكريتيين ، وأهلك بقية ساحل البحر '),
(12825, 'Ezekiel', 26, 25, 17, ' وأجري عليهم نقمات عظيمة بتأديب سخط ، فيعلمون أني أنا الرب ، إذ أجعل نقمتي عليهم '),
(12826, 'Ezekiel', 26, 26, 1, ' وكان في السنة الحادية عشرة ، في أول الشهر ، أن كلام الرب كان إلي قائلا '),
(12827, 'Ezekiel', 26, 26, 2, ' يا ابن آدم ، من أجل أن صور قالت على أورشليم : هه قد انكسرت مصاريع الشعوب . قد تحولت إلي . أمتلئ إذ خربت '),
(12828, 'Ezekiel', 26, 26, 3, ' لذلك هكذا قال السيد الرب : هأنذا عليك يا صور فأصعد عليك أمما كثيرة كما يعلي البحر أمواجه '),
(12829, 'Ezekiel', 26, 26, 4, ' فيخربون أسوار صور ويهدمون أبراجها . وأسحي ترابها عنها وأصيرها ضح الصخر '),
(12830, 'Ezekiel', 26, 26, 5, ' فتصير مبسطا للشباك في وسط البحر ، لأني أنا تكلمت ، يقول السيد الرب . وتكون غنيمة للأمم '),
(12831, 'Ezekiel', 26, 26, 6, ' وبناتها اللواتي في الحقل تقتل بالسيف ، فيعلمون أني أنا الرب '),
(12832, 'Ezekiel', 26, 26, 7, ' لأنه هكذا قال السيد الرب : هأنذا أجلب على صور نبوخذراصر ملك بابل من الشمال ، ملك الملوك ، بخيل وبمركبات وبفرسان وجماعة وشعب كثير '),
(12833, 'Ezekiel', 26, 26, 8, ' فيقتل بناتك في الحقل بالسيف ، ويبني عليك معاقل ، ويبني عليك برجا ، ويقيم عليك مترسة ، ويرفع عليك ترسا '),
(12834, 'Ezekiel', 26, 26, 9, ' ويجعل مجانق على أسوارك ، ويهدم أبراجك بأدوات حربه '),
(12835, 'Ezekiel', 26, 26, 10, ' ولكثرة خيله يغطيك غبارها . من صوت الفرسان والعجلات والمركبات تتزلزل أسوارك عند دخوله أبوابك ، كما تدخل مدينة مثغورة '),
(12836, 'Ezekiel', 26, 26, 11, ' بحوافر خيله يدوس كل شوارعك . يقتل شعبك بالسيف فتسقط إلى الأرض أنصاب عزك '),
(12837, 'Ezekiel', 26, 26, 12, ' وينهبون ثروتك ، ويغنمون تجارتك ، ويهدون أسوارك ، ويهدمون بيوتك البهيجة ، ويضعون حجارتك وخشبك وترابك في وسط المياه '),
(12838, 'Ezekiel', 26, 26, 13, ' وأبطل قول أغانيك ، وصوت أعوادك لن يسمع بعد '),
(12839, 'Ezekiel', 26, 26, 14, ' وأصيرك كضح الصخر ، فتكونين مبسطا للشباك . لا تبنين بعد ، لأني أنا الرب تكلمت ، يقول السيد الرب '),
(12840, 'Ezekiel', 26, 26, 15, ' هكذا قال السيد الرب لصور : أما تتزلزل الجزائر عند صوت سقوطك ، عند صراخ الجرحى ، عند وقوع القتل في وسطك '),
(12841, 'Ezekiel', 26, 26, 16, ' فتنزل جميع رؤساء البحر عن كراسيهم ، ويخلعون جببهم ، وينزعون ثيابهم المطرزة . يلبسون رعدات ، ويجلسون على الأرض ، ويرتعدون كل لحظة ، ويتحيرون منك '),
(12842, 'Ezekiel', 26, 26, 17, ' ويرفعون عليك مرثاة ويقولون لك : كيف بدت يا معمورة من البحار ، المدينة الشهيرة التي كانت قوية في البحر هي وسكانها الذين أوقعوا رعبهم على جميع جيرانها '),
(12843, 'Ezekiel', 26, 26, 18, ' الآن ترتعد الجزائر يوم سقوطك وتضطرب الجزائر التي في البحر لزوالك '),
(12844, 'Ezekiel', 26, 26, 19, ' لأنه هكذا قال السيد الرب : حين أصيرك مدينة خربة كالمدن غير المسكونة ، حين أصعد عليك الغمر فتغشاك المياه الكثيرة '),
(12845, 'Ezekiel', 26, 26, 20, ' أهبطك مع الهابطين في الجب ، إلى شعب القدم ، وأجلسك في أسافل الأرض في الخرب الأبدية مع الهابطين في الجب ، لتكوني غير مسكونة ، وأجعل فخرا في أرض الأحياء '),
(12846, 'Ezekiel', 26, 26, 21, ' أصيرك أهوالا ، ولا تكونين ، وتطلبين فلا توجدين بعد إلى الأبد ، يقول السيد الرب '),
(12847, 'Ezekiel', 26, 27, 1, ' وكان إلي كلام الرب قائلا '),
(12848, 'Ezekiel', 26, 27, 2, ' وأنت يا ابن آدم ، فارفع مرثاة على صور '),
(12849, 'Ezekiel', 26, 27, 3, ' وقل لصور : أيتها الساكنة عند مداخل البحر ، تاجرة الشعوب إلى جزائر كثيرة ، هكذا قال السيد الرب : يا صور ، أنت قلت : أنا كاملة الجمال '),
(12850, 'Ezekiel', 26, 27, 4, ' تخومك في قلب البحور . بناؤوك تمموا جمالك '),
(12851, 'Ezekiel', 26, 27, 5, ' عملوا كل ألواحك من سرو سنير . أخذوا أرزا من لبنان ليصنعوه لك سواري '),
(12852, 'Ezekiel', 26, 27, 6, ' صنعوا من بلوط باشان مجاذيفك . صنعوا مقاعدك من عاج مطعم في البقس من جزائر كتيم '),
(12853, 'Ezekiel', 26, 27, 7, ' كتان مطرز من مصر هو شراعك ليكون لك راية . الأسمانجوني والأرجوان من جزائر أليشة كانا غطاءك '),
(12854, 'Ezekiel', 26, 27, 8, ' أهل صيدون وإرواد كانوا ملاحيك . حكماؤك يا صور الذين كانوا فيك هم ربابينك '),
(12855, 'Ezekiel', 26, 27, 9, ' شيوخ جبيل وحكماؤها كانوا فيك قلافوك . جميع سفن البحر وملاحوها كانوا فيك ليتاجروا بتجارتك '),
(12856, 'Ezekiel', 26, 27, 10, ' فارس ولود وفوط كانوا في جيشك ، رجال حربك . علقوا فيك ترسا وخوذة . هم صيروا بهاءك '),
(12857, 'Ezekiel', 26, 27, 11, ' بنو إرواد مع جيشك على الأسوار من حولك ، والأبطال كانوا في بروجك . علقوا أتراسهم على أسوارك من حولك . هم تمموا جمالك '),
(12858, 'Ezekiel', 26, 27, 12, ' ترشيش تاجرتك بكثرة كل غنى . بالفضة والحديد والقصدير والرصاص أقاموا أسواقك '),
(12859, 'Ezekiel', 26, 27, 13, ' ياوان وتوبال وماشك هم تجارك . بنفوس الناس وبآنية النحاس أقاموا تجارتك '),
(12860, 'Ezekiel', 26, 27, 14, ' ومن بيت توجرمة بالخيل والفرسان والبغال أقاموا أسواقك '),
(12861, 'Ezekiel', 26, 27, 15, ' بنو ددان تجارك . جزائر كثيرة تجار يدك . أدوا هديتك قرونا من العاج والآبنوس '),
(12862, 'Ezekiel', 26, 27, 16, ' أرام تاجرتك بكثرة صنائعك ، تاجروا في أسواقك بالبهرمان والأرجوان والمطرز والبوص والمرجان والياقوت '),
(12863, 'Ezekiel', 26, 27, 17, ' يهوذا وأرض إسرائيل هم تجارك . تاجروا في سوقك بحنطة منيت وحلاوى وعسل وزيت وبلسان '),
(12864, 'Ezekiel', 26, 27, 18, ' دمشق تاجرتك بكثرة صنائعك وكثرة كل غنى ، بخمر حلبون والصوف الأبيض '),
(12865, 'Ezekiel', 26, 27, 19, ' ودان وياوان قدموا غزلا في أسواقك . حديد مشغول وسليخة وقصب الذريرة كانت في سوقك '),
(12866, 'Ezekiel', 26, 27, 20, ' ددان تاجرتك بطنافس للركوب '),
(12867, 'Ezekiel', 26, 27, 21, ' العرب وكل رؤساء قيدار هم تجار يدك بالخرفان والكباش والأعتدة . في هذه كانوا تجارك '),
(12868, 'Ezekiel', 26, 27, 22, ' تجار شبا ورعمة هم تجارك . بأفخر كل أنواع الطيب وبكل حجر كريم والذهب أقاموا أسواقك '),
(12869, 'Ezekiel', 26, 27, 23, ' حران وكنة وعدن تجار شبا وأشور وكلمد تجارك '),
(12870, 'Ezekiel', 26, 27, 24, ' هؤلاء تجارك بنفائس ، بأردية أسمانجونية ومطرزة ، وأصونة مبرم معكومة بالحبال مصنوعة من الأرز بين بضائعك '),
(12871, 'Ezekiel', 26, 27, 25, ' سفن ترشيش قوافلك لتجارتك ، فامتلأت وتمجدت جدا في قلب البحار '),
(12872, 'Ezekiel', 26, 27, 26, ' ملاحوك قد أتوا بك إلى مياه كثيرة . كسرتك الريح الشرقية في قلب البحار '),
(12873, 'Ezekiel', 26, 27, 27, ' ثروتك وأسواقك وبضاعتك وملاحوك وربابينك وقلافوك والمتاجرون بمتجرك ، وجميع رجال حربك الذين فيك ، وكل جمعك الذي في وسطك يسقطون في قلب البحار في يوم سقوطك '),
(12874, 'Ezekiel', 26, 27, 28, ' من صوت صراخ ربابينك تتزلزل المسارح '),
(12875, 'Ezekiel', 26, 27, 29, ' وكل ممسكي المجذاف والملاحون ، وكل ربابين البحر ينزلون من سفنهم ويقفون على البر '),
(12876, 'Ezekiel', 26, 27, 30, ' ويسمعون صوتهم عليك ، ويصرخون بمرارة ، ويذرون ترابا فوق رؤوسهم ، ويتمرغون في الرماد '),
(12877, 'Ezekiel', 26, 27, 31, ' ويجعلون في أنفسهم قرعة عليك ، ويتنطقون بالمسوح ، ويبكون عليك بمرارة نفس نحيبا مرا '),
(12878, 'Ezekiel', 26, 27, 32, ' وفي نوحهم يرفعون عليك مناحة ويرثونك ، ويقولون : أية مدينة كصور كالمسكتة في قلب البحر '),
(12879, 'Ezekiel', 26, 27, 33, ' عند خروج بضائعك من البحار أشبعت شعوبا كثيرين . بكثرة ثروتك وتجارتك أغنيت ملوك الأرض '),
(12880, 'Ezekiel', 26, 27, 34, ' حين انكسارك من البحار في أعماق المياه سقط متجرك وكل جمعك '),
(12881, 'Ezekiel', 26, 27, 35, ' كل سكان الجزائر يتحيرون عليك ، وملوكهن يقشعرون اقشعرارا . يضطربون في الوجوه '),
(12882, 'Ezekiel', 26, 27, 36, ' التجار بين الشعوب يصفرون عليك فتكونين أهوالا ، ولا تكونين بعد إلى الأبد '),
(12883, 'Ezekiel', 26, 28, 1, ' وكان إلي كلام الرب قائلا '),
(12884, 'Ezekiel', 26, 28, 2, ' يا ابن آدم ، قل لرئيس صور : هكذا قال السيد الرب : من أجل أنه قد ارتفع قلبك وقلت : أنا إله . في مجلس الآلهة أجلس في قلب البحار . وأنت إنسان لا إله ، وإن جعلت قلبك كقلب الآلهة '),
(12885, 'Ezekiel', 26, 28, 3, ' ها أنت أحكم من دانيآل سر ما لا يخفى عليك '),
(12886, 'Ezekiel', 26, 28, 4, ' وبحكمتك وبفهمك حصلت لنفسك ثروة ، وحصلت الذهب والفضة في خزائنك '),
(12887, 'Ezekiel', 26, 28, 5, ' بكثرة حكمتك في تجارتك كثرت ثروتك ، فارتفع قلبك بسبب غناك '),
(12888, 'Ezekiel', 26, 28, 6, ' فلذلك هكذا قال السيد الرب : من أجل أنك جعلت قلبك كقلب الآلهة '),
(12889, 'Ezekiel', 26, 28, 7, ' لذلك هأنذا أجلب عليك غرباء ، عتاة الأمم ، فيجردون سيوفهم على بهجة حكمتك ويدنسون جمالك '),
(12890, 'Ezekiel', 26, 28, 8, ' ينزلونك إلى الحفرة ، فتموت موت القتلى في قلب البحار '),
(12891, 'Ezekiel', 26, 28, 9, ' هل تقول قولا أمام قاتلك : أنا إله ؟ وأنت إنسان لا إله في يد طاعنك '),
(12892, 'Ezekiel', 26, 28, 10, ' موت الغلف تموت بيد الغرباء ، لأني أنا تكلمت ، يقول السيد الرب '),
(12893, 'Ezekiel', 26, 28, 11, ' وكان إلي كلام الرب قائلا '),
(12894, 'Ezekiel', 26, 28, 12, ' يا ابن آدم ، ارفع مرثاة على ملك صور وقل له : هكذا قال السيد الرب : أنت خاتم الكمال ، ملآن حكمة وكامل الجمال '),
(12895, 'Ezekiel', 26, 28, 13, ' كنت في عدن جنة الله . كل حجر كريم ستارتك ، عقيق أحمر وياقوت أصفر وعقيق أبيض وزبرجد وجزع ويشب وياقوت أزرق وبهرمان وزمرد وذهب . أنشأوا فيك صنعة صيغة الفصوص وترصيعها يوم خلقت '),
(12896, 'Ezekiel', 26, 28, 14, ' أنت الكروب المنبسط المظلل ، وأقمتك . على جبل الله المقدس كنت . بين حجارة النار تمشيت '),
(12897, 'Ezekiel', 26, 28, 15, ' أنت كامل في طرقك من يوم خلقت حتى وجد فيك إثم '),
(12898, 'Ezekiel', 26, 28, 16, ' بكثرة تجارتك ملأوا جوفك ظلما فأخطأت . فأطرحك من جبل الله وأبيدك أيها الكروب المظلل من بين حجارة النار '),
(12899, 'Ezekiel', 26, 28, 17, ' قد ارتفع قلبك لبهجتك . أفسدت حكمتك لأجل بهائك . سأطرحك إلى الأرض ، وأجعلك أمام الملوك لينظروا إليك '),
(12900, 'Ezekiel', 26, 28, 18, ' قد نجست مقادسك بكثرة آثامك بظلم تجارتك ، فأخرج نارا من وسطك فتأكلك ، وأصيرك رمادا على الأرض أمام عيني كل من يراك '),
(12901, 'Ezekiel', 26, 28, 19, ' فيتحير منك جميع الذين يعرفونك بين الشعوب ، وتكون أهوالا ولا توجد بعد إلى الأبد '),
(12902, 'Ezekiel', 26, 28, 20, ' وكان إلي كلام الرب قائلا '),
(12903, 'Ezekiel', 26, 28, 21, ' يا ابن آدم ، اجعل وجهك نحو صيدون وتنبأ عليها '),
(12904, 'Ezekiel', 26, 28, 22, ' وقل : هكذا قال السيد الرب : هأنذا عليك يا صيدون وسأتمجد في وسطك ، فيعلمون أني أنا الرب حين أجري فيها أحكاما وأتقدس فيها '),
(12905, 'Ezekiel', 26, 28, 23, ' وأرسل عليها وبأ ودما إلى أزقتها ، ويسقط الجرحى في وسطها بالسيف الذي عليها من كل جانب ، فيعلمون أني أنا الرب '),
(12906, 'Ezekiel', 26, 28, 24, ' فلا يكون بعد لبيت إسرائيل سلاء ممرر ولا شوكة موجعة من كل الذين حولهم ، الذين يبغضونهم ، فيعلمون أني أنا السيد الرب '),
(12907, 'Ezekiel', 26, 28, 25, ' هكذا قال السيد الرب : عندما أجمع بيت إسرائيل من الشعوب الذين تفرقوا بينهم ، وأتقدس فيهم أمام عيون الأمم ، يسكنون في أرضهم التي أعطيتها لعبدي يعقوب '),
(12908, 'Ezekiel', 26, 28, 26, ' ويسكنون فيها آمنين ويبنون بيوتا ويغرسون كروما ، ويسكنون في أمن عندما أجري أحكاما على جميع مبغضيهم من حولهم ، فيعلمون أني أنا الرب إلههم '),
(12909, 'Ezekiel', 26, 29, 1, ' في السنة العاشرة ، في الثاني عشر من الشهر العاشر ، كان إلي كلام الرب قائلا '),
(12910, 'Ezekiel', 26, 29, 2, ' يا ابن آدم ، اجعل وجهك نحو فرعون ملك مصر وتنبأ عليه وعلى مصر كلها '),
(12911, 'Ezekiel', 26, 29, 3, ' تكلم وقل : هكذا قال السيد الرب : هأنذا عليك يا فرعون ملك مصر ، التمساح الكبير الرابض في وسط أنهاره ، الذي قال : نهري لي ، وأنا عملته لنفسي ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(12912, 'Ezekiel', 26, 42, 1, ' وأخرجني إلى الدار الخارجية من طريق جهة الشمال ، وأدخلني إلى المخدع الذي هو تجاه المكان المنفصل ، والذي هو قدام البناء إلى الشمال '),
(12913, 'Ezekiel', 26, 42, 2, ' إلى قدام طول مئة ذراع مدخل الشمال ، والعرض خمسون ذراعا '),
(12914, 'Ezekiel', 26, 42, 3, ' تجاه العشرين التي للدار الداخلية ، وتجاه المجزع الذي للدار الخارجية أسطوانة تجاه أسطوانة في الطبقات الثلاث '),
(12915, 'Ezekiel', 26, 42, 4, ' وأمام المخادع ممشى عشر أذرع عرضا . وإلى الداخلية طريق ، ذراع واحدة عرضا وأبوابها نحو الشمال '),
(12916, 'Ezekiel', 26, 42, 5, ' والمخادع العليا أقصر . لأن الأساطين أكلت من هذه . من أسافل البناء ومن أواسطه '),
(12917, 'Ezekiel', 26, 42, 6, ' لأنها ثلاث طبقات ، ولم يكن لها أعمدة كأعمدة الدور ، لذلك تضيق من الأسافل ومن الأواسط من الأرض '),
(12918, 'Ezekiel', 26, 42, 7, ' والحائط الذي من خارج مع المخادع نحو الدار الخارجية إلى قدام المخادع ، طوله خمسون ذراعا '),
(12919, 'Ezekiel', 26, 42, 8, ' لأن طول المخادع التي للدار الخارجية خمسون ذراعا . وهوذا أمام الهيكل مئة ذراع '),
(12920, 'Ezekiel', 26, 42, 9, ' ومن تحت هذه المخادع مدخل من الشرق من حيث يدخل إليها من الدار الخارجية '),
(12921, 'Ezekiel', 26, 42, 10, ' المخادع كانت في عرض جدار الدار نحو الشرق قدام المكان المنفصل وقبالة البناء '),
(12922, 'Ezekiel', 26, 42, 11, ' وأمامها طريق كمثل المخادع التي نحو الشمال ، كطولها هكذا عرضها وجميع مخارجها وكأشكالها وكأبوابها '),
(12923, 'Ezekiel', 26, 42, 12, ' وكأبواب المخادع التي نحو الجنوب باب على رأس الطريق . الطريق أمام الجدار الموافق نحو الشرق من حيث يدخل إليها '),
(12924, 'Ezekiel', 26, 42, 13, ' وقال لي : مخادع الشمال ومخادع الجنوب التي أمام المكان المنفصل هي مخادع مقدسة ، حيث يأكل الكهنة الذين يتقربون إلى الرب قدس الأقداس . هناك يضعون قدس الأقداس والتقدمة وذبيحة الخطية وذبيحة الإثم ، لأن المكان مقدس '),
(12925, 'Ezekiel', 26, 42, 14, ' عند دخول الكهنة لا يخرجون من القدس إلى الدار الخارجية ، بل يضعون هناك ثيابهم التي يخدمون بها لأنها مقدسة ، ويلبسون ثيابا غيرها ويتقدمون إلى ما هو للشعب '),
(12926, 'Ezekiel', 26, 42, 15, ' فلما أتم قياس البيت الداخلي ، أخرجني نحو الباب المتجه نحو المشرق وقاسه حواليه '),
(12927, 'Ezekiel', 26, 42, 16, ' قاس جانب المشرق بقصبة القياس ، خمس مئة قصبة بقصبة القياس حواليه '),
(12928, 'Ezekiel', 26, 42, 17, ' وقاس جانب الشمال ، خمس مئة قصبة بقصبة القياس حواليه '),
(12929, 'Ezekiel', 26, 42, 18, ' وقاس جانب الجنوب ، خمس مئة قصبة بقصبة القياس '),
(12930, 'Ezekiel', 26, 42, 19, ' ثم دار إلى جانب الغرب وقاس خمس مئة قصبة بقصبة القياس '),
(12931, 'Ezekiel', 26, 42, 20, ' قاسه من الجوانب الأربعة . له سور حواليه خمس مئة طولا ، وخمس مئة عرضا ، للفصل بين المقدس والمحلل '),
(12932, 'Ezekiel', 26, 43, 1, ' ثم ذهب بي إلى الباب ، الباب المتجه نحو الشرق '),
(12933, 'Ezekiel', 26, 43, 2, ' وإذا بمجد إله إسرائيل جاء من طريق الشرق وصوته كصوت مياه كثيرة ، والأرض أضاءت من مجده '),
(12934, 'Ezekiel', 26, 43, 3, ' والمنظر كالمنظر الذي رأيته ، كالمنظر الذي رأيته لما جئت لأخرب المدينة ، والمناظر كالمنظر الذي رأيت عند نهر خابور ، فخررت على وجهي '),
(12935, 'Ezekiel', 26, 43, 4, ' فجاء مجد الرب إلى البيت من طريق الباب المتجه نحو الشرق '),
(12936, 'Ezekiel', 26, 43, 5, ' فحملني روح وأتى بي إلى الدار الداخلية ، وإذا بمجد الرب قد ملأ البيت '),
(12937, 'Ezekiel', 26, 43, 6, ' وسمعته يكلمني من البيت ، وكان رجل واقفا عندي '),
(12938, 'Ezekiel', 26, 43, 7, ' وقال لي : يا ابن آدم ، هذا مكان كرسيي ومكان باطن قدمي حيث أسكن في وسط بني إسرائيل إلى الأبد ، ولا ينجس بعد بيت إسرائيل اسمي القدوس ، لا هم ولا ملوكهم ، لا بزناهم ولا بجثث ملوكهم في مرتفعاتهم '),
(12939, 'Ezekiel', 26, 43, 8, ' بجعلهم عتبتهم لدى عتبتي ، وقوائمهم لدى قوائمي ، وبيني وبينهم حائط ، فنجسوا اسمي القدوس برجاساتهم التي فعلوها ، فأفنيتهم بغضبي '),
(12940, 'Ezekiel', 26, 43, 9, ' فليبعدوا عني الآن زناهم وجثث ملوكهم فأسكن في وسطهم إلى الأبد '),
(12941, 'Ezekiel', 26, 43, 10, ' وأنت يا ابن آدم ، فأخبر بيت إسرائيل عن البيت ليخزوا من آثامهم ، وليقيسوا الرسم '),
(12942, 'Ezekiel', 26, 43, 11, ' فإن خزوا من كل ما فعلوه ، فعرفهم صورة البيت ورسمه ومخارجه ومداخله وكل أشكاله وكل فرائضه وكل أشكاله وكل شرائعه ، واكتب ذلك قدام أعينهم ليحفظوا كل رسومه وكل فرائضه ويعملوا بها '),
(12943, 'Ezekiel', 26, 43, 12, ' هذه سنة البيت : على رأس الجبل كل تخمه حواليه قدس أقداس . هذه هي سنة البيت '),
(12944, 'Ezekiel', 26, 43, 13, ' وهذه أقيسة المذبح بالأذرع ، والذراع هي ذراع وفتر : الحضن ذراع ، والعرض ذراع ، وحاشيته إلى شفته حواليه شبر واحد . هذا ظهر المذبح '),
(12945, 'Ezekiel', 26, 43, 14, ' ومن الحضن عند الأرض إلى الخصم الأسفل ذراعان ، والعرض ذراع . ومن الخصم الأصغر إلى الخصم الأكبر أربع أذرع ، والعرض ذراع '),
(12946, 'Ezekiel', 26, 43, 15, ' والموقد أربع أذرع . ومن الموقد إلى فوق أربعة قرون '),
(12947, 'Ezekiel', 26, 43, 16, ' والموقد اثنتا عشرة طولا ، باثنتي عشرة عرضا ، مربعا على جوانبه الأربعة '),
(12948, 'Ezekiel', 26, 43, 17, ' والخصم أربع عشرة طولا بأربع عشرة عرضا على جوانبه الأربعة . والحاشية حواليه نصف ذراع ، وحضنه ذراع حواليه ، ودرجاته تجاه المشرق '),
(12949, 'Ezekiel', 26, 43, 18, ' وقال لي : يا ابن آدم ، هكذا قال السيد الرب : هذه فرائض المذبح يوم صنعه لإصعاد المحرقة عليه ولرش الدم عليه '),
(12950, 'Ezekiel', 26, 43, 19, ' فتعطي الكهنة اللاويين الذين من نسل صادوق المقتربين إلي ليخدموني ، يقول السيد الرب ، ثورا من البقر لذبيحة خطية '),
(12951, 'Ezekiel', 26, 43, 20, ' وتأخذ من دمه وتضعه على قرونه الأربعة ، وعلى أربع زوايا الخصم وعلى الحاشية حواليها ، فتطهره وتكفر عنه '),
(12952, 'Ezekiel', 26, 43, 21, ' وتأخذ ثور الخطية فيحرق في الموضع المعين من البيت خارج المقدس '),
(12953, 'Ezekiel', 26, 43, 22, ' وفي اليوم الثاني تقرب تيسا من المعز صحيحا ذبيحة خطية ، فيطهرون المذبح كما طهروه بالثور '),
(12954, 'Ezekiel', 26, 43, 23, ' وإذا أكملت التطهير ، تقرب ثورا من البقر صحيحا ، وكبشا من الضأن صحيحا '),
(12955, 'Ezekiel', 26, 43, 24, ' وتقربهما قدام الرب ، ويلقي عليهما الكهنة ملحا ويصعدونهما محرقة للرب '),
(12956, 'Ezekiel', 26, 43, 25, ' سبعة أيام تعمل في كل يوم تيس الخطية . ويعملون ثورا من البقر وكبشا من الضأن صحيحين '),
(12957, 'Ezekiel', 26, 43, 26, ' سبعة أيام يكفرون عن المذبح ويطهرونه ويملأون يده '),
(12958, 'Ezekiel', 26, 43, 27, ' فإذا تمت هذه الأيام يكون في اليوم الثامن فصاعدا أن الكهنة يعملون على المذبح محرقاتكم وذبائحكم السلامية ، فأرضى عنكم ، يقول السيد الرب '),
(12959, 'Ezekiel', 26, 44, 1, ' ثم أرجعني إلى طريق باب المقدس الخارجي المتجه للمشرق ، وهو مغلق '),
(12960, 'Ezekiel', 26, 44, 2, ' فقال لي الرب : هذا الباب يكون مغلقا ، لا يفتح ولا يدخل منه إنسان ، لأن الرب إله إسرائيل دخل منه فيكون مغلقا '),
(12961, 'Ezekiel', 26, 44, 3, ' الرئيس ، الرئيس هو يجلس فيه ليأكل خبزا أمام الرب . من طريق رواق الباب يدخل ، ومن طريقه يخرج '),
(12962, 'Ezekiel', 26, 44, 4, ' ثم أتى بي في طريق باب الشمال إلى قدام البيت ، فنظرت وإذا بمجد الرب قد ملأ بيت الرب ، فخررت على وجهي '),
(12963, 'Ezekiel', 26, 44, 5, ' فقال لي الرب : يا ابن آدم ، اجعل قلبك وانظر بعينيك واسمع بأذنيك كل ما أقوله لك عن كل فرائض بيت الرب وعن كل سننه ، واجعل قلبك على مدخل البيت مع كل مخارج المقدس '),
(12964, 'Ezekiel', 26, 44, 6, ' وقل للمتمردين ، لبيت إسرائيل : هكذا قال السيد الرب : يكفيكم كل رجاساتكم يا بيت إسرائيل '),
(12965, 'Ezekiel', 26, 44, 7, ' بإدخالكم أبناء الغريب الغلف القلوب الغلف اللحم ليكونوا في مقدسي ، فينجسوا بيتي بتقريبكم خبزي الشحم والدم . فنقضوا عهدي فوق كل رجاساتكم '),
(12966, 'Ezekiel', 26, 44, 8, ' ولم تحرسوا حراسة أقداسي ، بل أقمتم حراسا يحرسون عنكم في مقدسي '),
(12967, 'Ezekiel', 26, 44, 9, ' هكذا قال السيد الرب : ابن الغريب أغلف القلب وأغلف اللحم لا يدخل مقدسي ، من كل ابن غريب الذي من وسط بني إسرائيل '),
(12968, 'Ezekiel', 26, 44, 10, ' بل اللاويون الذين ابتعدوا عني حين ضل إسرائيل ، فضلوا عني وراء أصنامهم ، يحملون إثمهم '),
(12969, 'Ezekiel', 26, 44, 11, ' ويكونون خداما في مقدسي ، حراس أبواب البيت وخدام البيت . هم يذبحون المحرقة والذبيحة للشعب ، وهم يقفون أمامهم ليخدموهم '),
(12970, 'Ezekiel', 26, 44, 12, ' لأنهم خدموهم أمام أصنامهم وكانوا معثرة إثم لبيت إسرائيل . لذلك رفعت يدي عليهم ، يقول السيد الرب ، فيحملون إثمهم '),
(12971, 'Ezekiel', 26, 44, 13, ' ولا يتقربون إلي ليكهنوا لي ، ولا للاقتراب إلى شيء من أقداسي إلى قدس الأقداس ، بل يحملون خزيهم ورجاساتهم التي فعلوها '),
(12972, 'Ezekiel', 26, 44, 14, ' وأجعلهم حارسي حراسة البيت لكل خدمة لكل ما يعمل فيه '),
(12973, 'Ezekiel', 26, 44, 15, ' أما الكهنة اللاويون أبناء صادوق الذين حرسوا حراسة مقدسي حين ضل عني بنو إسرائيل ، فهم يتقدمون إلي ليخدموني ، ويقفون أمامي ليقربوا لي الشحم والدم ، يقول السيد الرب '),
(12974, 'Ezekiel', 26, 44, 16, ' هم يدخلون مقدسي ويتقدمون إلى مائدتي ليخدموني ويحرسوا حراستي '),
(12975, 'Ezekiel', 26, 44, 17, ' ويكون عند دخولهم أبواب الدار الداخلية ، أنهم يلبسون ثيابا من كتان ، ولا يأتي عليهم صوف عند خدمتهم في أبواب الدار الداخلية ومن داخل '),
(12976, 'Ezekiel', 26, 44, 18, ' ولتكن عصائب من كتان على رؤوسهم ، ولتكن سراويل من كتان على أحقائهم . لا يتنطقون بما يعرق '),
(12977, 'Ezekiel', 26, 44, 19, ' وعند خروجهم إلى الدار الخارجية ، إلى الشعب ، إلى الدار الخارجية ، يخلعون ثيابهم التي خدموا بها ، ويضعونها في مخادع القدس ، ثم يلبسون ثيابا أخرى ولا يقدسون الشعب بثيابهم '),
(12978, 'Ezekiel', 26, 44, 20, ' ولا يحلقون رؤوسهم ، ولا يربون خصلا ، بل يجزون شعر رؤوسهم جزا '),
(12979, 'Ezekiel', 26, 44, 21, ' ولا يشرب كاهن خمرا عند دخوله إلى الدار الداخلية '),
(12980, 'Ezekiel', 26, 44, 22, ' ولا يأخذون أرملة ولا مطلقة زوجة ، بل يتخذون عذارى من نسل بيت إسرائيل ، أو أرملة التي كانت أرملة كاهن '),
(12981, 'Ezekiel', 26, 44, 23, ' ويرون شعبي التمييز بين المقدس والمحلل ، ويعلمونهم التمييز بين النجس والطاهر '),
(12982, 'Ezekiel', 26, 44, 24, ' وفي الخصام هم يقفون للحكم ، ويحكمون حسب أحكامي ، ويحفظون شرائعي وفرائضي في كل مواسمي ، ويقدسون سبوتي '),
(12983, 'Ezekiel', 26, 44, 25, ' ولا يدنوا من إنسان ميت فيتنجسوا . أما لأب أو أم أو ابن أو ابنة أو أخ أو أخت لم تكن لرجل يتنجسون '),
(12984, 'Ezekiel', 26, 44, 26, ' وبعد تطهيره يحسبون له سبعة أيام '),
(12985, 'Ezekiel', 26, 44, 27, ' وفي يوم دخوله إلى القدس إلى الدار الداخلية ليخدم في القدس ، يقرب ذبيحته عن الخطية ، يقول السيد الرب '),
(12986, 'Ezekiel', 26, 44, 28, ' ويكون لهم ميراثا . أنا ميراثهم . ولا تعطونهم ملكا في إسرائيل . أنا ملكهم '),
(12987, 'Ezekiel', 26, 34, 20, ' لذلك هكذا قال السيد الرب لهم : هأنذا أحكم بين الشاة السمينة والشاة المهزولة '),
(12988, 'Ezekiel', 26, 34, 21, ' لأنكم بهزتم بالجنب والكتف ، ونطحتم المريضة بقرونكم حتى شتتموها إلى خارج '),
(12989, 'Ezekiel', 26, 34, 22, ' فأخلص غنمي فلا تكون من بعد غنيمة ، وأحكم بين شاة وشاة '),
(12990, 'Ezekiel', 26, 34, 23, ' وأقيم عليها راعيا واحدا فيرعاها عبدي داود ، هو يرعاها وهو يكون لها راعيا '),
(12991, 'Ezekiel', 26, 34, 24, ' وأنا الرب أكون لهم إلها ، وعبدي داود رئيسا في وسطهم . أنا الرب تكلمت '),
(12992, 'Ezekiel', 26, 34, 25, ' وأقطع معهم عهد سلام ، وأنزع الوحوش الرديئة من الأرض ، فيسكنون في البرية مطمئنين وينامون في الوعور '),
(12993, 'Ezekiel', 26, 34, 26, ' وأجعلهم وما حول أكمتي بركة ، وأنزل عليهم المطر في وقته فتكون أمطار بركة '),
(12994, 'Ezekiel', 26, 34, 27, ' وتعطي شجرة الحقل ثمرتها ، وتعطي الأرض غلتها ، ويكونون آمنين في أرضهم ، ويعلمون أني أنا الرب عند تكسيري ربط نيرهم ، وإذا أنقذتهم من يد الذين استعبدوهم '),
(12995, 'Ezekiel', 26, 34, 28, ' فلا يكونون بعد غنيمة للأمم ، ولا يأكلهم وحش الأرض ، بل يسكنون آمنين ولا مخيف '),
(12996, 'Ezekiel', 26, 34, 29, ' وأقيم لهم غرسا لصيت فلا يكونون بعد مفنيي الجوع في الأرض ، ولا يحملون بعد تعيير الأمم '),
(12997, 'Ezekiel', 26, 34, 30, ' فيعلمون أني أنا الرب إلههم معهم ، وهم شعبي بيت إسرائيل ، يقول السيد الرب '),
(12998, 'Ezekiel', 26, 34, 31, ' وأنتم يا غنمي ، غنم مرعاي ، أناس أنتم . أنا إلهكم ، يقول السيد الرب '),
(12999, 'Ezekiel', 26, 35, 1, ' وكان إلي كلام الرب قائلا '),
(13000, 'Ezekiel', 26, 35, 2, ' يا ابن آدم ، اجعل وجهك نحو جبل سعير وتنبأ عليه '),
(13001, 'Ezekiel', 26, 35, 3, ' وقل له : هكذا قال السيد الرب : هأنذا عليك يا جبل سعير ، وأمد يدي عليك وأجعلك خرابا مقفرا '),
(13002, 'Ezekiel', 26, 35, 4, ' أجعل مدنك خربة ، وتكون أنت مقفرا ، وتعلم أني أنا الرب '),
(13003, 'Ezekiel', 26, 35, 5, ' لأنه كانت لك بغضة أبدية ، ودفعت بني إسرائيل إلى يد السيف في وقت مصيبتهم ، وقت إثم النهاية '),
(13004, 'Ezekiel', 26, 35, 6, ' لذلك حي أنا ، يقول السيد الرب ، إني أهيئك للدم ، والدم يتبعك . إذ لم تكره الدم فالدم يتبعك '),
(13005, 'Ezekiel', 26, 35, 7, ' فأجعل جبل سعير خرابا ومقفرا ، وأستأصل منه الذاهب والآئب '),
(13006, 'Ezekiel', 26, 35, 8, ' وأملأ جباله من قتلاه . تلالك وأوديتك وجميع أنهارك يسقطون فيها قتلى بالسيف '),
(13007, 'Ezekiel', 26, 35, 9, ' وأصيرك خربا أبدية ، ومدنك لن تعود ، فتعلمون أني أنا الرب '),
(13008, 'Ezekiel', 26, 35, 10, ' لأنك قلت : إن هاتين الأمتين ، وهاتين الأرضين تكونان لي فنمتلكهما والرب كان هناك '),
(13009, 'Ezekiel', 26, 35, 11, ' فلذلك ، حي أنا ، يقول السيد الرب ، لأفعلن كغضبك وكحسدك اللذين عاملت بهما من بغضتك لهم ، وأعرف بنفسي بينهم عندما أحكم عليك '),
(13010, 'Ezekiel', 26, 35, 12, ' فتعلم أني أنا الرب ، قد سمعت كل إهانتك التي تكلمت بها على جبال إسرائيل قائلا : قد خربت . قد أعطيناها مأكلا '),
(13011, 'Ezekiel', 26, 35, 13, ' قد تعظمتم علي بأفواهكم وكثرتم كلامكم علي . أنا سمعت '),
(13012, 'Ezekiel', 26, 35, 14, ' هكذا قال السيد الرب : عند فرح كل الأرض أجعلك مقفرا '),
(13013, 'Ezekiel', 26, 35, 15, ' كما فرحت على ميراث بيت إسرائيل لأنه خرب ، كذلك أفعل بك . تكون خرابا يا جبل سعير أنت وكل أدوم بأجمعها ، فيعلمون أني أنا الرب '),
(13014, 'Ezekiel', 26, 36, 1, ' وأنت يا ابن آدم ، فتنبأ لجبال إسرائيل وقل : يا جبال إسرائيل اسمعي كلمة الرب '),
(13015, 'Ezekiel', 26, 36, 2, ' هكذا قال السيد الرب : من أجل أن العدو قال عليكم : هه إن المرتفعات القديمة صارت لنا ميراثا '),
(13016, 'Ezekiel', 26, 36, 3, ' فلذلك تنبأ وقل : هكذا قال السيد الرب : من أجل أنهم قد أخربوكم وتهمموكم من كل جانب لتكونوا ميراثا لبقية الأمم ، وأصعدتم على شفاه اللسان ، وصرتم مذمة الشعب '),
(13017, 'Ezekiel', 26, 36, 4, ' لذلك فاسمعي يا جبال إسرائيل كلمة السيد الرب : هكذا قال السيد الرب للجبال وللآكام وللأنهار وللأودية وللخرب المقفرة وللمدن المهجورة التي صارت للنهب والاستهزاء لبقية الأمم الذين حولها '),
(13018, 'Ezekiel', 26, 36, 5, ' من أجل ذلك هكذا قال السيد الرب : إني في نار غيرتي تكلمت على بقية الأمم وعلى أدوم كلها ، الذين جعلوا أرضي ميراثا لهم بفرح كل القلب وبغضة نفس لنهبها غنيمة '),
(13019, 'Ezekiel', 26, 36, 6, ' فتنبأ على أرض إسرائيل وقل للجبال وللتلال وللأنهار وللأودية : هكذا قال السيد الرب : هأنذا في غيرتي وفي غضبي تكلمت من أجل أنكم حملتم تعيير الأمم '),
(13020, 'Ezekiel', 26, 36, 7, ' لذلك هكذا قال السيد الرب : إني رفعت يدي ، فالأمم الذين حولكم هم يحملون تعييرهم '),
(13021, 'Ezekiel', 26, 36, 8, ' أما أنتم يا جبال إسرائيل ، فإنكم تنبتون فروعكم وتثمرون ثمركم لشعبي إسرائيل ، لأنه قريب الإتيان '),
(13022, 'Ezekiel', 26, 36, 9, ' لأني أنا لكم وألتفت إليكم فتحرثون وتزرعون '),
(13023, 'Ezekiel', 26, 36, 10, ' وأكثر الناس عليكم ، كل بيت إسرائيل بأجمعه ، فتعمر المدن وتبنى الخرب '),
(13024, 'Ezekiel', 26, 36, 11, ' وأكثر عليكم الإنسان والبهيمة فيكثرون ويثمرون ، وأسكنكم حسب حالتكم القديمة ، وأحسن إليكم أكثر مما في أوائلكم ، فتعلمون أني أنا الرب '),
(13025, 'Ezekiel', 26, 36, 12, ' وأمشي الناس عليكم شعبي إسرائيل ، فيرثونك فتكون لهم ميراثا ولا تعود بعد تثكلهم '),
(13026, 'Ezekiel', 26, 36, 13, ' هكذا قال السيد الرب : من أجل أنهم قالوا لكم :  أنت أكالة الناس ومثكلة شعوبك '),
(13027, 'Ezekiel', 26, 36, 14, ' لذلك لن تأكلي الناس بعد ، ولا تثكلي شعوبك بعد ، يقول السيد الرب '),
(13028, 'Ezekiel', 26, 36, 15, ' ولا أسمع فيك من بعد تعيير الأمم ، ولا تحملين تعيير الشعوب بعد ، ولا تعثرين شعوبك بعد ، يقول السيد الرب '),
(13029, 'Ezekiel', 26, 36, 16, ' وكان إلي كلام الرب قائلا '),
(13030, 'Ezekiel', 26, 36, 17, ' يا ابن آدم ، إن بيت إسرائيل لما سكنوا أرضهم نجسوها بطريقهم وبأفعالهم . كانت طريقهم أمامي كنجاسة الطامث '),
(13031, 'Ezekiel', 26, 36, 18, ' فسكبت غضبي عليهم لأجل الدم الذي سفكوه على الأرض ، وبأصنامهم نجسوها '),
(13032, 'Ezekiel', 26, 36, 19, ' فبددتهم في الأمم فتذروا في الأراضي . كطريقهم وكأفعالهم دنتهم '),
(13033, 'Ezekiel', 26, 36, 20, ' فلما جاءوا إلى الأمم حيث جاءوا نجسوا اسمي القدوس ، إذ قالوا لهم : هؤلاء شعب الرب وقد خرجوا من أرضه '),
(13034, 'Ezekiel', 26, 36, 21, ' فتحننت على اسمي القدوس الذي نجسه بيت إسرائيل في الأمم حيث جاءوا '),
(13035, 'Ezekiel', 26, 36, 22, ' لذلك فقل لبيت إسرائيل : هكذا قال السيد الرب : ليس لأجلكم أنا صانع يا بيت إسرائيل ، بل لأجل اسمي القدوس الذي نجستموه في الأمم حيث جئتم '),
(13036, 'Ezekiel', 26, 36, 23, ' فأقدس اسمي العظيم المنجس في الأمم ، الذي نجستموه في وسطهم ، فتعلم الأمم أني أنا الرب ، يقول السيد الرب ، حين أتقدس فيكم قدام أعينهم '),
(13037, 'Ezekiel', 26, 36, 24, ' وآخذكم من بين الأمم وأجمعكم من جميع الأراضي وآتي بكم إلى أرضكم '),
(13038, 'Ezekiel', 26, 36, 25, ' وأرش عليكم ماء طاهرا فتطهرون . من كل نجاستكم ومن كل أصنامكم أطهركم '),
(13039, 'Ezekiel', 26, 36, 26, ' وأعطيكم قلبا جديدا ، وأجعل روحا جديدة في داخلكم ، وأنزع قلب الحجر من لحمكم وأعطيكم قلب لحم '),
(13040, 'Ezekiel', 26, 36, 27, ' وأجعل روحي في داخلكم ، وأجعلكم تسلكون في فرائضي ، وتحفظون أحكامي وتعملون بها '),
(13041, 'Ezekiel', 26, 36, 28, ' وتسكنون الأرض التي أعطيت آباءكم إياها ، وتكونون لي شعبا وأنا أكون لكم إلها '),
(13042, 'Ezekiel', 26, 36, 29, ' وأخلصكم من كل نجاساتكم . وأدعو الحنطة وأكثرها ولا أضع عليكم جوعا '),
(13043, 'Ezekiel', 26, 36, 30, ' وأكثر ثمر الشجر وغلة الحقل لكيلا تنالوا بعد عار الجوع بين الأمم '),
(13044, 'Ezekiel', 26, 36, 31, ' فتذكرون طرقكم الرديئة وأعمالكم غير الصالحة ، وتمقتون أنفسكم أمام وجوهكم من أجل آثامكم وعلى رجاساتكم '),
(13045, 'Ezekiel', 26, 36, 32, ' لا من أجلكم أنا صانع ، يقول السيد الرب ، فليكن معلوما لكم . فاخجلوا واخزوا من طرقكم يا بيت إسرائيل '),
(13046, 'Ezekiel', 26, 36, 33, ' هكذا قال السيد الرب : في يوم تطهيري إياكم من كل آثامكم ، أسكنكم في المدن ، فتبنى الخرب '),
(13047, 'Ezekiel', 26, 36, 34, ' وتفلح الأرض الخربة عوضا عن كونها خربة أمام عيني كل عابر '),
(13048, 'Ezekiel', 26, 36, 35, ' فيقولون : هذه الأرض الخربة صارت كجنة عدن ، والمدن الخربة والمقفرة والمنهدمة محصنة معمورة '),
(13049, 'Ezekiel', 26, 36, 36, ' فتعلم الأمم الذين تركوا حولكم أني أنا الرب ، بنيت المنهدمة وغرست المقفرة . أنا الرب تكلمت وسأفعل '),
(13050, 'Ezekiel', 26, 36, 37, ' هكذا قال السيد الرب : بعد هذه أطلب من بيت إسرائيل لأفعل لهم . أكثرهم كغنم أناس '),
(13051, 'Ezekiel', 26, 36, 38, ' كغنم مقدس ، كغنم أورشليم في مواسمها ، فتكون المدن الخربة ملآنة غنم أناس ، فيعلمون أني أنا الرب '),
(13052, 'Ezekiel', 26, 37, 1, ' كانت علي يد الرب ، فأخرجني بروح الرب وأنزلني في وسط البقعة وهي ملآنة عظاما '),
(13053, 'Ezekiel', 26, 37, 2, ' وأمرني عليها من حولها وإذا هي كثيرة جدا على وجه البقعة ، وإذا هي يابسة جدا '),
(13054, 'Ezekiel', 26, 37, 3, ' فقال لي : يا ابن آدم ، أتحيا هذه العظام ؟  . فقلت : يا سيد الرب أنت تعلم '),
(13055, 'Ezekiel', 26, 37, 4, ' فقال لي : تنبأ على هذه العظام وقل لها : أيتها العظام اليابسة ، اسمعي كلمة الرب '),
(13056, 'Ezekiel', 26, 37, 5, ' هكذا قال السيد الرب لهذه العظام : هأنذا أدخل فيكم روحا فتحيون '),
(13057, 'Ezekiel', 26, 37, 6, ' وأضع عليكم عصبا وأكسيكم لحما وأبسط عليكم جلدا وأجعل فيكم روحا ، فتحيون وتعلمون أني أنا الرب '),
(13058, 'Ezekiel', 26, 37, 7, ' فتنبأت كما أمرت . وبينما أنا أتنبأ كان صوت ، وإذا رعش ، فتقاربت العظام كل عظم إلى عظمه '),
(13059, 'Ezekiel', 26, 37, 8, ' ونظرت وإذا بالعصب واللحم كساها ، وبسط الجلد عليها من فوق ، وليس فيها روح '),
(13060, 'Ezekiel', 26, 37, 9, ' فقال لي : تنبأ للروح ، تنبأ يا ابن آدم ، وقل للروح : هكذا قال السيد الرب : هلم يا روح من الرياح الأربع وهب على هؤلاء القتلى ليحيوا '),
(13061, 'Ezekiel', 26, 37, 10, ' فتنبأت كما أمرني ، فدخل فيهم الروح ، فحيوا وقاموا على أقدامهم جيش عظيم جدا جدا '),
(13062, 'Ezekiel', 26, 37, 11, ' ثم قال لي : يا ابن آدم ، هذه العظام هي كل بيت إسرائيل . ها هم يقولون : يبست عظامنا وهلك رجاؤنا . قد انقطعنا '),
(13063, 'Ezekiel', 26, 37, 12, ' لذلك تنبأ وقل لهم : هكذا قال السيد الرب : هأنذا أفتح قبوركم وأصعدكم من قبوركم يا شعبي ، وآتي بكم إلى أرض إسرائيل '),
(13064, 'Ezekiel', 26, 37, 13, ' فتعلمون أني أنا الرب عند فتحي قبوركم وإصعادي إياكم من قبوركم يا شعبي '),
(13065, 'Ezekiel', 26, 37, 14, ' وأجعل روحي فيكم فتحيون ، وأجعلكم في أرضكم ، فتعلمون أني أنا الرب تكلمت وأفعل ، يقول الرب '),
(13066, 'Ezekiel', 26, 37, 15, ' وكان إلي كلام الرب قائلا '),
(13067, 'Ezekiel', 26, 37, 16, ' وأنت يا ابن آدم ، خذ لنفسك عصا واحدة واكتب عليها : ليهوذا ولبني إسرائيل رفقائه . وخذ عصا أخرى واكتب عليها : ليوسف ، عصا أفرايم وكل بيت إسرائيل رفقائه '),
(13068, 'Ezekiel', 26, 37, 17, ' واقرنهما الواحدة بالأخرى كعصا واحدة ، فتصيرا واحدة في يدك '),
(13069, 'Ezekiel', 26, 37, 18, ' فإذا كلمك أبناء شعبك قائلين : أما تخبرنا ما لك وهذا '),
(13070, 'Ezekiel', 26, 37, 19, ' فقل لهم : هكذا قال السيد الرب : هأنذا آخذ عصا يوسف التي في يد أفرايم وأسباط إسرائيل رفقاءه ، وأضم إليها عصا يهوذا ، وأجعلهم عصا واحدة فيصيرون واحدة في يدي '),
(13071, 'Ezekiel', 26, 37, 20, ' وتكون العصوان اللتان كتبت عليهما في يدك أمام أعينهم '),
(13072, 'Ezekiel', 26, 37, 21, ' وقل لهم : هكذا قال السيد الرب : هأنذا آخذ بني إسرائيل من بين الأمم التي ذهبوا إليها ، وأجمعهم من كل ناحية ، وآتي بهم إلى أرضهم '),
(13073, 'Ezekiel', 26, 37, 22, ' وأصيرهم أمة واحدة في الأرض على جبال إسرائيل ، وملك واحد يكون ملكا عليهم كلهم ، ولا يكونون بعد أمتين ، ولا ينقسمون بعد إلى مملكتين '),
(13074, 'Ezekiel', 26, 37, 23, ' ولا يتنجسون بعد بأصنامهم ولا برجاساتهم ولا بشيء من معاصيهم ، بل أخلصهم من كل مساكنهم التي فيها أخطأوا ، وأطهرهم فيكونون لي شعبا وأنا أكون لهم إلها '),
(13075, 'Ezekiel', 26, 37, 24, ' وداود عبدي يكون ملكا عليهم ، ويكون لجميعهم راع واحد ، فيسلكون في أحكامي ويحفظون فرائضي ويعملون بها '),
(13076, 'Ezekiel', 26, 37, 25, ' ويسكنون في الأرض التي أعطيت عبدي يعقوب إياها ، التي سكنها آباؤكم ، ويسكنون فيها هم وبنوهم وبنو بنيهم إلى الأبد ، وعبدي داود رئيس عليهم إلى الأبد '),
(13077, 'Ezekiel', 26, 37, 26, ' وأقطع معهم عهد سلام ، فيكون معهم عهدا مؤبدا ، وأقرهم وأكثرهم وأجعل مقدسي في وسطهم إلى الأبد '),
(13078, 'Ezekiel', 26, 37, 27, ' ويكون مسكني فوقهم ، وأكون لهم إلها ويكونون لي شعبا '),
(13079, 'Ezekiel', 26, 37, 28, ' فتعلم الأمم أني أنا الرب مقدس إسرائيل ، إذ يكون مقدسي في وسطهم إلى الأبد '),
(13080, 'Ezekiel', 26, 38, 1, ' وكان إلي كلام الرب قائلا '),
(13081, 'Ezekiel', 26, 38, 2, ' يا ابن آدم ، اجعل وجهك على جوج ، أرض ماجوج رئيس روش ماشك وتوبال ، وتنبأ عليه '),
(13082, 'Ezekiel', 26, 38, 3, ' وقل : هكذا قال السيد الرب : هأنذا عليك يا جوج رئيس روش ماشك وتوبال '),
(13083, 'Ezekiel', 26, 38, 4, ' وأرجعك ، وأضع شكائم في فكيك ، وأخرجك أنت وكل جيشك خيلا وفرسانا كلهم لابسين أفخر لباس ، جماعة عظيمة مع أتراس ومجان ، كلهم ممسكين السيوف '),
(13084, 'Ezekiel', 26, 38, 5, ' فارس وكوش وفوط معهم ، كلهم بمجن وخوذة '),
(13085, 'Ezekiel', 26, 38, 6, ' وجومر وكل جيوشه ، وبيت توجرمة من أقاصي الشمال مع كل جيشه ، شعوبا كثيرين معك '),
(13086, 'Ezekiel', 26, 38, 7, ' استعد وهيئ لنفسك أنت وكل جماعاتك المجتمعة إليك ، فصرت لهم موقرا '),
(13087, 'Ezekiel', 26, 38, 8, ' بعد أيام كثيرة تفتقد . في السنين الأخيرة تأتي إلى الأرض المستردة من السيف المجموعة من شعوب كثيرة على جبال إسرائيل التي كانت دائمة خربة ، للذين أخرجوا من الشعوب وسكنوا آمنين كلهم '),
(13088, 'Ezekiel', 26, 38, 9, ' وتصعد وتأتي كزوبعة ، وتكون كسحابة تغشي الأرض أنت وكل جيوشك وشعوب كثيرون معك '),
(13089, 'Ezekiel', 26, 38, 10, ' هكذا قال السيد الرب : ويكون في ذلك اليوم أن أمورا تخطر ببالك فتفكر فكرا رديئا '),
(13090, 'Ezekiel', 26, 38, 11, ' وتقول : إني أصعد على أرض أعراء . آتي الهادئين الساكنين في أمن ، كلهم ساكنون بغير سور وليس لهم عارضة ولا مصاريع '),
(13091, 'Ezekiel', 26, 38, 12, ' لسلب السلب ولغنم الغنيمة ، لرد يدك على خرب معمورة وعلى شعب مجموع من الأمم ، المقتني ماشية وقنية ، الساكن في أعالي الأرض '),
(13092, 'Ezekiel', 26, 38, 13, ' شبا وددان وتجار ترشيش وكل أشبالها يقولون لك : هل لسلب سلب أنت جاء ؟ هل لغنم غنيمة جمعت جماعتك ، لحمل الفضة والذهب ، لأخذ الماشية والقنية ، لنهب نهب عظيم '),
(13093, 'Ezekiel', 26, 38, 14, ' لذلك تنبأ يا ابن آدم ، وقل لجوج : هكذا قال السيد الرب : في ذلك اليوم عند سكنى شعبي إسرائيل آمنين ، أفلا تعلم '),
(13094, 'Ezekiel', 26, 38, 15, ' وتأتي من موضعك من أقاصي الشمال أنت وشعوب كثيرون معك ، كلهم راكبون خيلا ، جماعة عظيمة وجيش كثير '),
(13095, 'Ezekiel', 26, 38, 16, ' وتصعد على شعبي إسرائيل كسحابة تغشي الأرض . في الأيام الأخيرة يكون . وآتي بك على أرضي لكي تعرفني الأمم ، حين أتقدس فيك أمام أعينهم يا جوج '),
(13096, 'Ezekiel', 26, 38, 17, ' هكذا قال السيد الرب : هل أنت هو الذي تكلمت عنه في الأيام القديمة عن يد عبيدي أنبياء إسرائيل ، الذين تنبأوا في تلك الأيام سنينا أن آتي بك عليهم '),
(13097, 'Ezekiel', 26, 38, 18, ' ويكون في ذلك اليوم ، يوم مجيء جوج على أرض إسرائيل ، يقول السيد الرب ، أن غضبي يصعد في أنفي '),
(13098, 'Ezekiel', 26, 38, 19, ' وفي غيرتي ، في نار سخطي تكلمت ، أنه في ذلك اليوم يكون رعش عظيم في أرض إسرائيل '),
(13099, 'Ezekiel', 26, 38, 20, ' فترعش أمامي سمك البحر وطيور السماء ووحوش الحقل والدابات التي تدب على الأرض ، وكل الناس الذين على وجه الأرض ، وتندك الجبال وتسقط المعاقل وتسقط كل الأسوار إلى الأرض '),
(13100, 'Ezekiel', 26, 38, 21, ' وأستدعي السيف عليه في كل جبالي ، يقول السيد الرب ، فيكون سيف كل واحد على أخيه '),
(13101, 'Ezekiel', 26, 38, 22, ' وأعاقبه بالوبإ وبالدم ، وأمطر عليه وعلى جيشه وعلى الشعوب الكثيرة الذين معه مطرا جارفا وحجارة برد عظيمة ونارا وكبريتا '),
(13102, 'Ezekiel', 26, 38, 23, ' فأتعظم وأتقدس وأعرف في عيون أمم كثيرة ، فيعلمون أني أنا الرب '),
(13103, 'Ezekiel', 26, 39, 1, ' وأنت يا ابن آدم ، تنبأ على جوج وقل : هكذا قال السيد الرب : هأنذا عليك يا جوج رئيس روش ماشك وتوبال '),
(13104, 'Ezekiel', 26, 39, 2, ' وأردك وأقودك وأصعدك من أقاصي الشمال وآتي بك على جبال إسرائيل '),
(13105, 'Ezekiel', 26, 39, 3, ' وأضرب قوسك من يدك اليسرى ، وأسقط سهامك من يدك اليمنى '),
(13106, 'Ezekiel', 26, 39, 4, ' فتسقط على جبال إسرائيل أنت وكل جيشك والشعوب الذين معك . أبذلك مأكلا للطيور الكاسرة من كل نوع ولوحوش الحقل '),
(13107, 'Ezekiel', 26, 39, 5, ' على وجه الحقل تسقط ، لأني تكلمت ، يقول السيد الرب '),
(13108, 'Ezekiel', 26, 39, 6, ' وأرسل نارا على ماجوج وعلى الساكنين في الجزائر آمنين ، فيعلمون أني أنا الرب '),
(13109, 'Ezekiel', 26, 39, 7, ' وأعرف باسمي المقدس في وسط شعبي إسرائيل ، ولا أدع اسمي المقدس ينجس بعد ، فتعلم الأمم أني أنا الرب قدوس إسرائيل '),
(13110, 'Ezekiel', 26, 39, 8, ' ها هو قد أتى وصار ، يقول السيد الرب . هذا هو اليوم الذي تكلمت عنه '),
(13111, 'Ezekiel', 26, 39, 9, ' ويخرج سكان مدن إسرائيل ويشعلون ويحرقون السلاح والمجان والأتراس والقسي والسهام والحراب والرماح ، ويوقدون بها النار سبع سنين '),
(13112, 'Ezekiel', 26, 39, 10, ' فلا يأخذون من الحقل عودا ، ولا يحتطبون من الوعور ، لأنهم يحرقون السلاح بالنار ، وينهبون الذين نهبوهم ، ويسلبون الذين سلبوهم ، يقول السيد الرب '),
(13113, 'Ezekiel', 26, 39, 11, ' ويكون في ذلك اليوم ، أني أعطي جوجا موضعا هناك للقبر في إسرائيل ، ووادي عباريم بشرقي البحر ، فيسد نفس العابرين . وهناك يدفنون جوجا وجمهوره كله ، ويسمونه : وادي جمهور جوج '),
(13114, 'Ezekiel', 26, 39, 12, ' ويقبرهم بيت إسرائيل ليطهروا الأرض سبعة أشهر '),
(13115, 'Ezekiel', 26, 39, 13, ' كل شعب الأرض يقبرون ، ويكون لهم يوم تمجيدي مشهورا ، يقول السيد الرب '),
(13116, 'Ezekiel', 26, 39, 14, ' ويفرزون أناسا مستديمين عابرين في الأرض ، قابرين مع العابرين أولئك الذين بقوا على وجه الأرض . تطهيرا لها . بعد سبعة أشهر يفحصون '),
(13117, 'Ezekiel', 26, 39, 15, ' فيعبر العابرون في الأرض ، وإذا رأى أحد عظم إنسان يبني بجانبه صوة حتى يقبره القابرون في وادي جمهور جوج '),
(13118, 'Ezekiel', 26, 39, 16, ' وأيضا اسم المدينة همونة ، فيطهرون الأرض '),
(13119, 'Ezekiel', 26, 39, 17, ' وأنت يا ابن آدم ، فهكذا قال السيد الرب : قل لطائر كل جناح ، ولكل وحوش البر : اجتمعوا ، وتعالوا ، احتشدوا من كل جهة ، إلى ذبيحتي التي أنا ذابحها لكم ، ذبيحة عظيمة على جبال إسرائيل ، لتأكلوا لحما وتشربوا دما '),
(13120, 'Ezekiel', 26, 39, 18, ' تأكلون لحم الجبابرة وتشربون دم رؤساء الأرض . كباش وحملان وأعتدة وثيران كلها من مسمنات باشان '),
(13121, 'Ezekiel', 26, 39, 19, ' وتأكلون الشحم إلى الشبع ، وتشربون الدم إلى السكر من ذبيحتي التي ذبحتها لكم '),
(13122, 'Ezekiel', 26, 39, 20, ' فتشبعون على مائدتي من الخيل والمركبات والجبابرة وكل رجال الحرب ، يقول السيد الرب '),
(13123, 'Ezekiel', 26, 39, 21, ' وأجعل مجدي في الأمم ، وجميع الأمم يرون حكمي الذي أجريته ، ويدي التي جعلتها عليهم '),
(13124, 'Ezekiel', 26, 39, 22, ' فيعلم بيت إسرائيل أني أنا الرب إلههم من ذلك اليوم فصاعدا '),
(13125, 'Ezekiel', 26, 39, 23, ' وتعلم الأمم أن بيت إسرائيل قد أجلوا بإثمهم لأنهم خانوني ، فحجبت وجهي عنهم وسلمتهم ليد مضايقيهم ، فسقطوا كلهم بالسيف '),
(13126, 'Ezekiel', 26, 39, 24, ' كنجاستهم وكمعاصيهم فعلت معهم وحجبت وجهي عنهم '),
(13127, 'Ezekiel', 26, 39, 25, ' لذلك هكذا قال السيد الرب : الآن أرد سبي يعقوب ، وأرحم كل بيت إسرائيل ، وأغار على اسمي القدوس '),
(13128, 'Ezekiel', 26, 39, 26, ' فيحملون خزيهم وكل خيانتهم التي خانوني إياها عند سكنهم في أرضهم مطمئنين ولا مخيف '),
(13129, 'Ezekiel', 26, 39, 27, ' عند إرجاعي إياهم من الشعوب ، وجمعي إياهم من أراضي أعدائهم ، وتقديسي فيهم أمام عيون أمم كثيرين '),
(13130, 'Ezekiel', 26, 39, 28, ' يعلمون أني أنا الرب إلههم بإجلائي إياهم إلى الأمم ، ثم جمعهم إلى أرضهم . ولا أترك بعد هناك أحدا منهم '),
(13131, 'Ezekiel', 26, 39, 29, ' ولا أحجب وجهي عنهم بعد ، لأني سكبت روحي على بيت إسرائيل ، يقول السيد الرب '),
(13132, 'Ezekiel', 26, 40, 1, ' في السنة الخامسة والعشرين من سبينا ، في رأس السنة ، في العاشر من الشهر ، في السنة الرابعة عشرة ، بعد ما ضربت المدينة في نفس ذلك اليوم ، كانت علي يد الرب وأتى بي إلى هناك '),
(13133, 'Ezekiel', 26, 40, 2, ' في رؤى الله أتى بي إلى أرض إسرائيل ووضعني على جبل عال جدا ، عليه كبناء مدينة من جهة الجنوب '),
(13134, 'Ezekiel', 26, 40, 3, ' ولما أتى بي إلى هناك ، إذا برجل منظره كمنظر النحاس ، وبيده خيط كتان وقصبة القياس ، وهو واقف بالباب '),
(13135, 'Ezekiel', 26, 40, 4, ' فقال لي الرجل : يا ابن آدم ، انظر بعينيك واسمع بأذنيك واجعل قلبك إلى كل ما أريكه ، لأنه لأجل إراءتك أتي بك إلى هنا . أخبر بيت إسرائيل بكل ما ترى '),
(13136, 'Ezekiel', 26, 40, 5, ' وإذا بسور خارج البيت محيط به ، وبيد الرجل قصبة القياس ست أذرع طولا بالذراع وشبر . فقاس عرض البناء قصبة واحدة ، وسمكه قصبة واحدة '),
(13137, 'Ezekiel', 26, 40, 6, ' ثم جاء إلى الباب الذي وجهه نحو الشرق وصعد في درجه ، وقاس عتبة الباب قصبة واحدة عرضا ، والعتبة الأخرى قصبة واحدة عرضا '),
(13138, 'Ezekiel', 26, 40, 7, ' والغرفة قصبة واحدة طولا وقصبة واحدة عرضا ، وبين الغرفات خمس أذرع ، وعتبة الباب بجانب رواق الباب من داخل قصبة واحدة '),
(13139, 'Ezekiel', 26, 40, 8, ' وقاس رواق الباب من داخل قصبة واحدة '),
(13140, 'Ezekiel', 26, 40, 9, ' وقاس رواق الباب ثماني أذرع ، وعضائده ذراعين ، ورواق الباب من داخل '),
(13141, 'Ezekiel', 26, 40, 10, ' وغرفات الباب نحو الشرق ثلاث من هنا وثلاث من هناك . للثلاث قياس واحد ، وللعضائد قياس واحد من هنا ومن هناك '),
(13142, 'Ezekiel', 26, 40, 11, ' وقاس عرض مدخل الباب عشر أذرع ، وطول الباب ثلاث عشرة ذراعا '),
(13143, 'Ezekiel', 26, 40, 12, ' والحافة أمام الغرفات ذراع واحدة من هنا ، والحافة ذراع واحدة من هناك . والغرفة ست أذرع من هنا ، وست أذرع من هناك '),
(13144, 'Ezekiel', 26, 40, 13, ' ثم قاس الباب من سقف الغرفة الواحدة إلى سقف الأخرى عرض خمس وعشرين ذراعا . الباب مقابل الباب '),
(13145, 'Ezekiel', 26, 40, 14, ' وعمل عضائد ستين ذراعا إلى عضادة الدار حول الباب '),
(13146, 'Ezekiel', 26, 40, 15, ' وقدام باب المدخل إلى قدام رواق الباب الداخلي خمسون ذراعا '),
(13147, 'Ezekiel', 26, 40, 16, ' وللغرفات كوى مشبكة ، وللعضائد من داخل الباب حواليه ، وهكذا في القبب أيضا ، كوى حواليها من داخل ، وعلى العضادة نخيل '),
(13148, 'Ezekiel', 26, 40, 17, ' ثم أتى بي إلى الدار الخارجية ، وإذا بمخادع ومجزع مصنوع للدار حواليها . على المجزع ثلاثون مخدعا '),
(13149, 'Ezekiel', 26, 40, 18, ' والمجزع بجانب الأبواب مقابل طول الأبواب ، المجزع الأسفل '),
(13150, 'Ezekiel', 26, 40, 19, ' وقاس العرض من قدام الباب الأسفل إلى قدام الدار الداخلية من خارج ، مئة ذراع إلى الشرق وإلى الشمال '),
(13151, 'Ezekiel', 26, 40, 20, ' والباب المتجه نحو الشمال الذي للدار الخارجية قاس طوله وعرضه '),
(13152, 'Ezekiel', 26, 40, 21, ' وغرفاته ثلاث من هنا وثلاث من هناك ، وعضائده ومقببه كانت على قياس الباب الأول ، طولها خمسون ذراعا وعرضها خمس وعشرون ذراعا '),
(13153, 'Ezekiel', 26, 40, 22, ' وكواها ومقببها ونخيلها على قياس الباب المتجه نحو الشرق ، وكانوا يصعدون إليه في سبع درجات ، ومقببه أمامه '),
(13154, 'Ezekiel', 26, 40, 23, ' وللدار الداخلية باب مقابل باب للشمال وللشرق . وقاس من باب إلى باب مئة ذراع '),
(13155, 'Ezekiel', 26, 40, 24, ' ثم ذهب بي نحو الجنوب ، وإذا بباب نحو الجنوب ، فقاس عضائده ومقببه كهذه الأقيسة '),
(13156, 'Ezekiel', 26, 40, 25, ' وفيه كوى وفي مقببه من حواليه كتلك الكوى . الطول خمسون ذراعا والعرض خمس وعشرون ذراعا '),
(13157, 'Ezekiel', 26, 40, 26, ' وسبع درجات مصعده ومقببه قدامه ، وله نخيل واحدة من هنا وواحدة من هناك على عضائده '),
(13158, 'Ezekiel', 26, 40, 27, ' وللدار الداخلية باب نحو الجنوب . وقاس من الباب إلى الباب نحو الجنوب مئة ذراع '),
(13159, 'Ezekiel', 26, 40, 28, ' وأتى بي إلى الدار الداخلية من باب الجنوب ، وقاس باب الجنوب كهذه الأقيسة '),
(13160, 'Ezekiel', 26, 40, 29, ' وغرفاته وعضائده ومقببه كهذه الأقيسة . وفيه وفي مقببه كوى حواليه . الطول خمسون ذراعا والعرض خمس وعشرون ذراعا '),
(13161, 'Ezekiel', 26, 40, 30, ' وحواليه مقبب خمس وعشرون ذراعا طولا وخمس أذرع عرضا '),
(13162, 'Ezekiel', 26, 40, 31, ' ومقببه نحو الدار الخارجية ، وعلى عضائده نخيل ، ومصعده ثماني درجات '),
(13163, 'Ezekiel', 26, 40, 32, ' وأتى بي إلى الدار الداخلية نحو المشرق وقاس الباب كهذه الأقيسة '),
(13164, 'Ezekiel', 26, 40, 33, ' وغرفاته وعضائده ومقببه كهذه الأقيسة . وفيه وفي مقببه كوى حواليه . الطول خمسون ذراعا والعرض خمس وعشرون ذراعا '),
(13165, 'Ezekiel', 26, 40, 34, ' ومقببه نحو الدار الخارجية ، وعلى عضائده نخيل من هنا ومن هناك ، ومصعده ثماني درجات '),
(13166, 'Ezekiel', 26, 40, 35, ' وأتى بي إلى باب الشمال وقاس كهذه الأقيسة '),
(13167, 'Ezekiel', 26, 40, 36, ' غرفاته وعضائده ومقببه والكوى التي له حواليه . الطول خمسون ذراعا والعرض خمس وعشرون ذراعا '),
(13168, 'Ezekiel', 26, 40, 37, ' وعضائده نحو الدار الخارجية ، وعلى عضائده نخيل من هنا ومن هناك ، ومصعده ثماني درجات '),
(13169, 'Ezekiel', 26, 40, 38, ' وعند عضائد الأبواب مخدع ومدخله . هناك يغسلون المحرقة '),
(13170, 'Ezekiel', 26, 40, 39, ' وفي رواق الباب مائدتان من هنا ، ومائدتان من هناك ، لتذبح عليها المحرقة وذبيحة الخطيئة وذبيحة الإثم '),
(13171, 'Ezekiel', 26, 40, 40, ' وعلى الجانب من خارج حيث يصعد إلى مدخل باب الشمال مائدتان ، وعلى الجانب الآخر الذي لرواق الباب مائدتان '),
(13172, 'Ezekiel', 26, 40, 41, ' أربع موائد من هنا ، وأربع موائد من هناك على جانب الباب . ثماني موائد كانوا يذبحون عليها '),
(13173, 'Ezekiel', 26, 40, 42, ' والموائد الأربع للمحرقة من حجر نحيت ، الطول ذراع ونصف ، والعرض ذراع ونصف ، والسمك ذراع واحدة . كانوا يضعون عليها الأدوات التي يذبحون بها المحرقة والذبيحة '),
(13174, 'Ezekiel', 26, 40, 43, ' والمآزيب شبر واحد ممكنة في البيت من حوله . وعلى الموائد لحم القربان '),
(13175, 'Ezekiel', 26, 40, 44, ' ومن خارج الباب الداخلي مخادع المغنين في الدار الداخلية التي بجانب باب الشمال ، ووجوهها نحو الجنوب . واحد بجانب باب الشرق متجه نحو الشمال '),
(13176, 'Ezekiel', 26, 40, 45, ' وقال لي : هذا المخدع الذي وجهه نحو الجنوب هو للكهنة حارسي حراسة البيت '),
(13177, 'Ezekiel', 26, 40, 46, ' والمخدع الذي وجهه نحو الشمال للكهنة حارسي حراسة المذبح . هم بنو صادوق المقربون من بني لاوي إلى الرب ليخدموه '),
(13178, 'Ezekiel', 26, 40, 47, ' فقاس الدار مئة ذراع طولا ، ومئة ذراع عرضا ، مربعة ، والمذبح أمام البيت '),
(13179, 'Ezekiel', 26, 40, 48, ' وأتى بي إلى رواق البيت وقاس عضادة الرواق ، خمس أذرع من هنا وخمس أذرع من هناك ، وعرض الباب ثلاث أذرع من هنا وثلاث أذرع من هناك '),
(13180, 'Ezekiel', 26, 40, 49, ' طول الرواق عشرون ذراعا ، والعرض إحدى عشرة ذراعا عند الدرج الذي به كانوا يصعدون إليه . وعند العضائد أعمدة ، واحد من هنا وواحد من هناك '),
(13181, 'Ezekiel', 26, 41, 1, ' وأتى بي إلى الهيكل وقاس العضائد ، عرضها من هنا ست أذرع ، ومن هناك ست أذرع ، عرض الخيمة '),
(13182, 'Ezekiel', 26, 41, 2, ' وعرض المدخل عشر أذرع ، وجوانب المدخل من هنا خمس أذرع ومن هناك خمس أذرع . وقاس طوله أربعين ذراعا والعرض عشرين ذراعا '),
(13183, 'Ezekiel', 26, 41, 3, ' ثم جاء إلى داخل وقاس عضادة المدخل ذراعين ، والمدخل ست أذرع ، وعرض المدخل سبع أذرع '),
(13184, 'Ezekiel', 26, 41, 4, ' وقاس طوله عشرين ذراعا ، والعرض عشرين ذراعا إلى قدام الهيكل . وقال لي : هذا قدس الأقداس '),
(13185, 'Ezekiel', 26, 41, 5, ' وقاس حائط البيت ست أذرع ، وعرض الغرفة أربع أذرع حول البيت من كل جهة '),
(13186, 'Ezekiel', 26, 41, 6, ' والغرفات غرفة إلى غرفة ثلاثا وثلاثين مرة ، ودخلت في الحائط الذي للبيت للغرفات حوله لتتمكن ، ولا تتمكن في حائط البيت '),
(13187, 'Ezekiel', 26, 41, 7, ' واتسعت الغرفات وأحاطت صاعدا فصاعدا ، لأن محيط البيت كان صاعدا فصاعدا حول البيت . لذلك عرض البيت إلى فوق ، وهكذا من الأسفل يصعد إلى الأعلى في الوسط '),
(13188, 'Ezekiel', 26, 41, 8, ' ورأيت سمك البيت حواليه . أسس الغرفات قصبة تامة ست أذرع إلى المفصل '),
(13189, 'Ezekiel', 26, 41, 9, ' عرض الحائط الذي للغرفة من خارج خمس أذرع ، وما بقي ففسحة لغرفات البيت '),
(13190, 'Ezekiel', 26, 41, 10, ' وبين المخادع عرض عشرين ذراعا حول البيت من كل جانب '),
(13191, 'Ezekiel', 26, 41, 11, ' ومدخل الغرفة في الفسحة مدخل واحد نحو الشمال ، ومدخل آخر نحو الجنوب . وعرض مكان الفسحة خمس أذرع حواليه '),
(13192, 'Ezekiel', 26, 41, 12, ' والبناء الذي أمام المكان المنفصل عند الطرف نحو الغرب سبعون ذراعا عرضا ، وحائط البناء خمس أذرع عرضا من حوله ، وطوله تسعون ذراعا '),
(13193, 'Ezekiel', 26, 41, 13, ' وقاس البيت مئة ذراع طولا ، والمكان المنفصل والبناء مع حيطانه مئة ذراع طولا '),
(13194, 'Ezekiel', 26, 41, 14, ' وعرض وجه البيت والمكان المنفصل نحو الشرق مئة ذراع '),
(13195, 'Ezekiel', 26, 41, 15, ' وقاس طول البناء إلى قدام المكان المنفصل الذي وراءه وأساطينه من جانب إلى جانب مئة ذراع . مع الهيكل الداخلي وأروقة الدار '),
(13196, 'Ezekiel', 26, 41, 16, ' العتبات والكوى المشبكة والأساطين حوالي الطبقات الثلاث مقابل العتبة من ألواح خشب من كل جانب ، ومن الأرض إلى الكوى والكوى مغطاة '),
(13197, 'Ezekiel', 26, 41, 17, ' إلى ما فوق المدخل ، وإلى البيت الداخلي وإلى الخارج ، وإلى الحائط كله حواليه من داخل ومن خارج بهذه الأقيسة '),
(13198, 'Ezekiel', 26, 41, 18, ' وعمل فيه كروبيم ونخيل . نخلة بين كروب وكروب ، ولكل كروب وجهان '),
(13199, 'Ezekiel', 26, 41, 19, ' فوجه الإنسان نحو نخلة من هنا ، ووجه الشبل نحو نخلة من هنالك . عمل في كل البيت حواليه '),
(13200, 'Ezekiel', 26, 41, 20, ' من الأرض إلى ما فوق المدخل عمل كروبيم ونخيل ، وعلى حائط الهيكل '),
(13201, 'Ezekiel', 26, 41, 21, ' وقوائم الهيكل مربعة ، ووجه القدس منظره كمنظر وجه الهيكل '),
(13202, 'Ezekiel', 26, 41, 22, ' المذبح من خشب ثلاث أذرع ارتفاعا ، وطوله ذراعان ، وزواياه وطوله وحيطانه من خشب . وقال لي : هذه المائدة أمام الرب '),
(13203, 'Ezekiel', 26, 41, 23, ' وللهيكل وللقدس بابان '),
(13204, 'Ezekiel', 26, 41, 24, ' وللبابين مصراعان ، مصراعان ينطويان . مصراعان للباب الواحد ومصراعان للباب الآخر '),
(13205, 'Ezekiel', 26, 41, 25, ' وعمل عليها على مصاريع الهيكل كروبيم ونخيل كما عمل على الحيطان ، وغشاء من خشب على وجه الرواق من خارج '),
(13206, 'Ezekiel', 26, 41, 26, ' وكوى مشبكة ونخيل من هنا ومن هناك على جوانب الرواق وعلى غرفات البيت وعلى الأسكفات '),
(13207, 'Ezekiel', 26, 44, 29, ' يأكلون التقدمة وذبيحة الخطية وذبيحة الإثم ، وكل محرم في إسرائيل يكون لهم '),
(13208, 'Ezekiel', 26, 44, 30, ' وأوائل كل الباكورات جميعها ، وكل رفيعة من كل رفائعكم تكون للكهنة . وتعطون الكاهن أوائل عجينكم لتحل البركة على بيتك '),
(13209, 'Ezekiel', 26, 44, 31, ' لا يأكل الكاهن من ميتة ولا من فريسة ، طيرا كانت أو بهيمة '),
(13210, 'Ezekiel', 26, 45, 1, ' وإذا قسمتم الأرض ملكا ، تقدمون تقدمة للرب قدسا من الأرض طوله خمسة وعشرون ألفا طولا ، والعرض عشرة آلاف . هذا قدس بكل تخومه حواليه '),
(13211, 'Ezekiel', 26, 45, 2, ' يكون للقدس من هذا خمس مئة في خمس مئة ، مربعة حواليه ، وخمسون ذراعا مسرحا له حواليه '),
(13212, 'Ezekiel', 26, 45, 3, ' من هذا القياس تقيس طول خمسة وعشرين ألفا ، وعرض عشرة آلاف ، وفيه يكون المقدس ، قدس الأقداس '),
(13213, 'Ezekiel', 26, 45, 4, ' قدس من الأرض هو . يكون للكهنة خدام المقدس المقتربين لخدمة الرب ، ويكون لهم موضعا للبيوت ومقدسا للمقدس '),
(13214, 'Ezekiel', 26, 45, 5, ' وخمسة وعشرون ألفا في الطول وعشرة آلاف في العرض تكون للاويين خدام البيت لهم ملكا . عشرون مخدعا '),
(13215, 'Ezekiel', 26, 45, 6, ' وتجعلون ملك المدينة خمسة آلاف عرضا وخمسة وعشرين ألفا طولا ، موازيا تقدمة القدس ، فيكون لكل بيت إسرائيل '),
(13216, 'Ezekiel', 26, 45, 7, ' وللرئيس من هنا ومن هناك من تقدمة القدس ، ومن ملك المدينة قدام تقدمة القدس وقدام ملك المدينة من جهة الغرب غربا ، ومن جهة الشرق شرقا ، والطول مواز أحد القسمين من تخم الغرب إلى تخم الشرق '),
(13217, 'Ezekiel', 26, 45, 8, ' تكون له أرضا ملكا في إسرائيل ، ولا تعود رؤسائي يظلمون شعبي ، والأرض يعطونها لبيت إسرائيل لأسباطهم '),
(13218, 'Ezekiel', 26, 45, 9, ' هكذا قال السيد الرب : يكفيكم يا رؤساء إسرائيل . أزيلوا الجور والاغتصاب ، وأجروا الحق والعدل . ارفعوا الظلم عن شعبي ، يقول السيد الرب '),
(13219, 'Ezekiel', 26, 45, 10, ' موازين حق ، وإيفة حق ، وبث حق تكون لكم '),
(13220, 'Ezekiel', 26, 45, 11, ' تكون الإيفة والبث مقدارا واحدا ، لكي يسع البث عشر الحومر ، والإيفة عشر الحومر . على الحومر يكون مقدارهما '),
(13221, 'Ezekiel', 26, 45, 12, ' والشاقل عشرون جيرة . عشرون شاقلا وخمسة وعشرون شاقلا وخمسة عشر شاقلا تكون منكم '),
(13222, 'Ezekiel', 26, 45, 13, ' هذه هي التقدمة التي تقدمونها : سدس الإيفة من حومر الحنطة ، وتعطون سدس الإيفة من حومر الشعير '),
(13223, 'Ezekiel', 26, 45, 14, ' وفريضة الزيت بث من زيت . البث عشر من الكر ، من عشرة أبثاث للحومر ، لأن عشرة أبثاث حومر '),
(13224, 'Ezekiel', 26, 45, 15, ' وشاة واحدة من الضأن من المئتين من سقي إسرائيل تقدمة ومحرقة وذبائح سلامة ، للكفارة عنهم ، يقول السيد الرب '),
(13225, 'Ezekiel', 26, 45, 16, ' وهذه التقدمة للرئيس في إسرائيل تكون على كل شعب الأرض '),
(13226, 'Ezekiel', 26, 45, 17, ' وعلى الرئيس تكون المحرقات والتقدمة والسكيب في الأعياد وفي الشهور وفي السبوت وفي كل مواسم بيت إسرائيل . وهو يعمل ذبيحة الخطية والتقدمة والمحرقة وذبائح السلامة ، للكفارة عن بيت إسرائيل '),
(13227, 'Ezekiel', 26, 45, 18, ' هكذا قال السيد الرب : في الشهر الأول ، في أول الشهر ، تأخذ ثورا من البقر صحيحا وتطهر المقدس '),
(13228, 'Ezekiel', 26, 45, 19, ' ويأخذ الكاهن من دم ذبيحة الخطية ويضعه على قوائم البيت ، وعلى زوايا خصم المذبح الأربع ، وعلى قوائم باب الدار الداخلية '),
(13229, 'Ezekiel', 26, 45, 20, ' وهكذا تفعل في سابع الشهر عن الرجل الساهي أو الغوي ، فتكفرون عن البيت '),
(13230, 'Ezekiel', 26, 45, 21, ' في الشهر الأول ، في اليوم الرابع عشر من الشهر ، يكون لكم الفصح عيدا . سبعة أيام يؤكل الفطير '),
(13231, 'Ezekiel', 26, 45, 22, ' ويعمل الرئيس في ذلك اليوم عن نفسه وعن كل شعب الأرض ثورا ذبيحة خطية '),
(13232, 'Ezekiel', 26, 45, 23, ' وفي سبعة أيام العيد يعمل محرقة للرب : سبعة ثيران وسبعة كباش صحيحة ، كل يوم من السبعة الأيام . وكل يوم تيسا من المعز ذبيحة خطية '),
(13233, 'Ezekiel', 26, 45, 24, ' ويعمل التقدمة إيفة للثور ، وإيفة للكبش ، وهينا من زيت للإيفة '),
(13234, 'Ezekiel', 26, 45, 25, ' في الشهر السابع ، في اليوم الخامس عشر من الشهر ، في العيد يعمل مثل ذلك سبعة أيام كذبيحة الخطية وكالمحرقة وكالتقدمة وكالزيت '),
(13235, 'Ezekiel', 26, 46, 1, ' هكذا قال السيد الرب : باب الدار الداخلية المتجه للمشرق يكون مغلقا ستة أيام العمل ، وفي السبت يفتح . وأيضا في يوم رأس الشهر يفتح '),
(13236, 'Ezekiel', 26, 46, 2, ' ويدخل الرئيس من طريق رواق الباب من خارج ويقف عند قائمة الباب ، وتعمل الكهنة محرقته وذبائحه السلامية ، فيسجد على عتبة الباب ثم يخرج . أما الباب فلا يغلق إلى المساء '),
(13237, 'Ezekiel', 26, 46, 3, ' ويسجد شعب الأرض عند مدخل هذا الباب قدام الرب في السبوت وفي رؤوس الشهور '),
(13238, 'Ezekiel', 26, 46, 4, ' والمحرقة التي يقربها الرئيس للرب في يوم السبت : ستة حملان صحيحة وكبش صحيح '),
(13239, 'Ezekiel', 26, 46, 5, ' والتقدمة إيفة للكبش ، وللحملان تقدمة عطية يده ، وهين زيت للإيفة '),
(13240, 'Ezekiel', 26, 46, 6, ' وفي يوم رأس الشهر : ثور ابن بقر صحيح وستة حملان وكبش تكون صحيحة '),
(13241, 'Ezekiel', 26, 46, 7, ' ويعمل تقدمة إيفة للثور وإيفة للكبش . أما للحملان فحسبما تنال يده ، وللإيفة هين زيت '),
(13242, 'Ezekiel', 26, 46, 8, ' وعند دخول الرئيس يدخل من طريق رواق الباب ، ومن طريقه يخرج '),
(13243, 'Ezekiel', 26, 46, 9, ' وعند دخول شعب الأرض قدام الرب في المواسم ، فالداخل من طريق باب الشمال ليسجد يخرج من طريق باب الجنوب ، والداخل من طريق باب الجنوب يخرج من طريق باب الشمال . لا يرجع من طريق الباب الذي دخل منه ، بل يخرج مقابله '),
(13244, 'Ezekiel', 26, 46, 10, ' والرئيس في وسطهم يدخل عند دخولهم ، وعند خروجهم يخرجون معا '),
(13245, 'Ezekiel', 26, 46, 11, ' وفي الأعياد وفي المواسم تكون التقدمة إيفة للثور وإيفة للكبش . وللحملان عطية يده ، وللإيفة هين زيت '),
(13246, 'Ezekiel', 26, 46, 12, ' وإذا عمل الرئيس نافلة ، محرقة أو ذبائح سلامة ، نافلة للرب ، يفتح له الباب المتجه للمشرق ، فيعمل محرقته وذبائحه السلامية كما يعمل في يوم السبت ثم يخرج . وبعد خروجه يغلق الباب '),
(13247, 'Ezekiel', 26, 46, 13, ' وتعمل كل يوم محرقة للرب حملا حوليا صحيحا . صباحا صباحا تعمله '),
(13248, 'Ezekiel', 26, 46, 14, ' وتعمل عليه تقدمة صباحا صباحا سدس الإيفة ، وزيتا ثلث الهين لرش الدقيق . تقدمة للرب ، فريضة أبدية دائمة '),
(13249, 'Ezekiel', 26, 46, 15, ' ويعملون الحمل والتقدمة والزيت صباحا صباحا محرقة دائمة '),
(13250, 'Ezekiel', 26, 46, 16, ' هكذا قال السيد الرب : إن أعطى الرئيس رجلا من بنيه عطية ، فإرثها يكون لبنيه . ملكهم هي بالوراثة '),
(13251, 'Ezekiel', 26, 46, 17, ' فإن أعطى أحدا من عبيده عطية من ميراثه فتكون له إلى سنة العتق ، ثم ترجع للرئيس . ولكن ميراثه يكون لأولاده '),
(13252, 'Ezekiel', 26, 46, 18, ' ولا يأخذ الرئيس من ميراث الشعب طردا لهم من ملكهم . من ملكه يورث بنيه ، لكيلا يفرق شعبي ، الرجل عن ملكه '),
(13253, 'Ezekiel', 26, 46, 19, ' ثم أدخلني بالمدخل الذي بجانب الباب إلى مخادع القدس التي للكهنة المتجهة للشمال ، وإذا هناك موضع على الجانبين إلى الغرب '),
(13254, 'Ezekiel', 26, 46, 20, ' وقال لي : هذا هو الموضع الذي تطبخ فيه الكهنة ذبيحة الإثم وذبيحة الخطية ، وحيث يخبزون التقدمة ، لئلا يخرجوا بها إلى الدار الخارجية ليقدسوا الشعب '),
(13255, 'Ezekiel', 26, 46, 21, ' ثم أخرجني إلى الدار الخارجية وعبرني على زوايا الدار الأربع ، فإذا في كل زاوية من الدار دار '),
(13256, 'Ezekiel', 26, 46, 22, ' في زوايا الدار الأربع دور مصونة طولها أربعون وعرضها ثلاثون . للزوايا الأربع قياس واحد '),
(13257, 'Ezekiel', 26, 46, 23, ' ومحيطة بها حافة حول الأربعة ، ومطابخ معمولة تحت الحافات المحيطة بها '),
(13258, 'Ezekiel', 26, 46, 24, ' ثم قال لي : هذا بيت الطباخين حيث يطبخ خدام البيت ذبيحة الشعب '),
(13259, 'Ezekiel', 26, 47, 1, ' ثم أرجعني إلى مدخل البيت وإذا بمياه تخرج من تحت عتبة البيت نحو المشرق ، لأن وجه البيت نحو المشرق . والمياه نازلة من تحت جانب البيت الأيمن عن جنوب المذبح '),
(13260, 'Ezekiel', 26, 47, 2, ' ثم أخرجني من طريق باب الشمال ودار بي في الطريق من خارج إلى الباب الخارجي من الطريق الذي يتجه نحو المشرق ، وإذا بمياه جارية من الجانب الأيمن '),
(13261, 'Ezekiel', 26, 47, 3, ' وعند خروج الرجل نحو المشرق والخيط بيده ، قاس ألف ذراع وعبرني في المياه ، والمياه إلى الكعبين '),
(13262, 'Ezekiel', 26, 47, 4, ' ثم قاس ألفا وعبرني في المياه ، والمياه إلى الركبتين . ثم قاس ألفا وعبرني ، والمياه إلى الحقوين '),
(13263, 'Ezekiel', 26, 47, 5, ' ثم قاس ألفا ، وإذا بنهر لم أستطع عبوره ، لأن المياه طمت ، مياه سباحة ، نهر لا يعبر '),
(13264, 'Ezekiel', 26, 47, 6, ' وقال لي : أرأيت يا ابن آدم ؟  . ثم ذهب بي وأرجعني إلى شاطئ النهر '),
(13265, 'Ezekiel', 26, 47, 7, ' وعند رجوعي إذا على شاطئ النهر أشجار كثيرة جدا من هنا ومن هناك '),
(13266, 'Ezekiel', 26, 47, 8, ' وقال لي : هذه المياه خارجة إلى الدائرة الشرقية وتنزل إلى العربة وتذهب إلى البحر . إلى البحر هي خارجة فتشفى المياه '),
(13267, 'Ezekiel', 26, 47, 9, ' ويكون أن كل نفس حية تدب حيثما يأتي النهران تحيا . ويكون السمك كثيرا جدا لأن هذه المياه تأتي إلى هناك فتشفى ، ويحيا كل ما يأتي النهر إليه '),
(13268, 'Ezekiel', 26, 47, 10, ' ويكون الصيادون واقفين عليه . من عين جدي إلى عين عجلايم يكون لبسط الشباك ، ويكون سمكهم على أنواعه كسمك البحر العظيم كثيرا جدا '),
(13269, 'Ezekiel', 26, 47, 11, ' أما غمقاته وبركه فلا تشفى . تجعل للملح '),
(13270, 'Ezekiel', 26, 47, 12, ' وعلى النهر ينبت على شاطئه من هنا ومن هناك كل شجر للأكل ، لا يذبل ورقه ولا ينقطع ثمره . كل شهر يبكر لأن مياهه خارجة من المقدس ، ويكون ثمره للأكل وورقه للدواء '),
(13271, 'Ezekiel', 26, 47, 13, ' هكذا قال السيد الرب : هذا هو التخم الذي به تمتلكون الأرض بحسب أسباط إسرائيل الاثني عشر ، يوسف قسمان '),
(13272, 'Ezekiel', 26, 47, 14, ' وتمتلكونها أحدكم كصاحبه ، التي رفعت يدي لأعطي آباءكم إياها . وهذه الأرض تقع لكم نصيبا '),
(13273, 'Ezekiel', 26, 47, 15, ' وهذا تخم الأرض : نحو الشمال من البحر الكبير طريق حثلون إلى المجيء إلى صدد '),
(13274, 'Ezekiel', 26, 47, 16, ' حماة وبيروثة وسبرائم ، التي بين تخم دمشق وتخم حماة ، وحصر الوسطى ، التي على تخم حوران '),
(13275, 'Ezekiel', 26, 47, 17, ' ويكون التخم من البحر حصر عينان تخم دمشق والشمال شمالا وتخم حماة . وهذا جانب الشمال '),
(13276, 'Ezekiel', 26, 47, 18, ' وجانب الشرق بين حوران ودمشق وجلعاد وأرض إسرائيل الأردن . من التخم إلى البحر الشرقي تقيسون . وهذا جانب المشرق '),
(13277, 'Ezekiel', 26, 47, 19, ' وجانب الجنوب يمينا من ثامار إلى مياه مريبوث قادش النهر إلى البحر الكبير . وهذا جانب اليمين جنوبا '),
(13278, 'Ezekiel', 26, 47, 20, ' وجانب الغرب البحر الكبير من التخم إلى مقابل مدخل حماة . وهذا جانب الغرب '),
(13279, 'Ezekiel', 26, 47, 21, ' فتقتسمون هذه الأرض لكم لأسباط إسرائيل '),
(13280, 'Ezekiel', 26, 47, 22, ' ويكون أنكم تقسمونها بالقرعة لكم وللغرباء المتغربين في وسطكم الذين يلدون بنين في وسطكم ، فيكونون لكم كالوطنيين من بني إسرائيل . يقاسمونكم الميراث في وسط أسباط إسرائيل '),
(13281, 'Ezekiel', 26, 47, 23, ' ويكون أنه في السبط الذي فيه يتغرب غريب هناك تعطونه ميراثه ، يقول السيد الرب '),
(13282, 'Ezekiel', 26, 48, 1, ' وهذه أسماء الأسباط : من طرف الشمال ، إلى جانب طريق حثلون إلى مدخل حماة حصر عينان تخم دمشق شمالا إلى جانب حماة لدان . فيكون له من الشرق إلى البحر قسم واحد '),
(13283, 'Ezekiel', 26, 48, 2, ' وعلى تخم دان من جانب المشرق إلى جانب البحر لأشير قسم واحد '),
(13284, 'Ezekiel', 26, 48, 3, ' وعلى تخم أشير من جانب الشرق إلى جانب البحر لنفتالي قسم واحد '),
(13285, 'Ezekiel', 26, 48, 4, ' وعلى تخم نفتالي من جانب الشرق إلى جانب البحر لمنسى قسم واحد '),
(13286, 'Ezekiel', 26, 48, 5, ' وعلى تخم منسى من جانب الشرق إلى جانب البحر لأفرايم قسم واحد '),
(13287, 'Ezekiel', 26, 48, 6, ' وعلى تخم أفرايم من جانب الشرق إلى جانب البحر لرأوبين قسم واحد '),
(13288, 'Ezekiel', 26, 48, 7, ' وعلى تخم رأوبين من جانب الشرق إلى جانب البحر ليهوذا قسم واحد '),
(13289, 'Ezekiel', 26, 48, 8, ' وعلى تخم يهوذا من جانب الشرق إلى جانب البحر تكون التقدمة التي تقدمونها خمسة وعشرين ألفا عرضا ، والطول كأحد الأقسام من جانب الشرق إلى جانب البحر ، ويكون المقدس في وسطها '),
(13290, 'Ezekiel', 26, 48, 9, ' التقدمة التي تقدمونها للرب تكون خمسة وعشرين ألفا طولا ، وعشرة آلاف عرضا '),
(13291, 'Ezekiel', 26, 48, 10, ' ولهؤلاء تكون تقدمة القدس للكهنة . من جهة الشمال خمسة وعشرون ألفا في الطول ، ومن جهة البحر عشرة آلاف في العرض ، ومن جهة الشرق عشرة آلاف في العرض ، ومن جهة الجنوب خمسة وعشرون ألفا في الطول . ويكون مقدس الرب في وسطها '),
(13292, 'Ezekiel', 26, 48, 11, ' أما المقدس فللكهنة من بني صادوق الذين حرسوا حراستي ، الذين لم يضلوا حين ضل بنو إسرائيل كما ضل اللاويون '),
(13293, 'Ezekiel', 26, 48, 12, ' وتكون لهم تقدمة من تقدمة الأرض ، قدس أقداس على تخم اللاويين '),
(13294, 'Ezekiel', 26, 48, 13, ' وللاويين على موازاة تخم الكهنة خمسة وعشرون ألفا في الطول ، وعشرة آلاف في العرض . الطول كله خمسة وعشرون ألفا ، والعرض عشرة آلاف '),
(13295, 'Ezekiel', 26, 48, 14, ' ولا يبيعون منه ولا يبدلون ، ولا يصرفون باكورات الأرض لأنها مقدسة للرب '),
(13296, 'Ezekiel', 26, 48, 15, ' والخمسة الآلاف الفاضلة من العرض قدام الخمسة والعشرين ألفا هي محللة للمدينة للسكنى وللمسرح ، والمدينة تكون في وسطها '),
(13297, 'Ezekiel', 26, 48, 16, ' وهذه أقيستها : جانب الشمال أربعة آلاف وخمس مئة ، وجانب الجنوب أربعة آلاف وخمس مئة ، وجانب الشرق أربعة آلاف وخمس مئة ، وجانب الغرب أربعة آلاف وخمس مئة '),
(13298, 'Ezekiel', 26, 48, 17, ' ويكون مسرح للمدينة نحو الشمال مئتين وخمسين ، ونحو الجنوب مئتين وخمسين ، ونحو الشرق مئتين وخمسين ، ونحو الغرب مئتين وخمسين '),
(13299, 'Ezekiel', 26, 48, 18, ' والباقي من الطول موازيا تقدمة القدس عشرة آلاف نحو الشرق ، وعشرة آلاف نحو الغرب . ويكون موازيا تقدمة القدس ، وغلته تكون أكلا لخدمة المدينة '),
(13300, 'Ezekiel', 26, 48, 19, ' أما خدمة المدينة فيخدمونها من كل أسباط إسرائيل '),
(13301, 'Ezekiel', 26, 48, 20, ' كل التقدمة خمسة وعشرون ألفا بخمسة وعشرين ألفا . مربعة تقدمون تقدمة القدس مع ملك المدينة '),
(13302, 'Ezekiel', 26, 48, 21, ' والبقية للرئيس من هنا ومن هناك لتقدمة القدس ولملك المدينة قدام الخمسة والعشرين ألفا للتقدمة إلى تخم الشرق ، ومن جهة الغرب قدام الخمسة والعشرين ألفا على تخم الغرب موازيا أملاك الرئيس ، وتكون تقدمة القدس ومقدس البيت في وسطها '),
(13303, 'Ezekiel', 26, 48, 22, ' ومن ملك اللاويين من ملك المدينة في وسط الذي هو للرئيس ، ما بين تخم يهوذا وتخم بنيامين ، يكون للرئيس ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(13304, 'Ezekiel', 26, 48, 23, ' وباقي الأسباط : فمن جانب الشرق إلى جانب البحر لبنيامين قسم واحد '),
(13305, 'Ezekiel', 26, 48, 24, ' وعلى تخم بنيامين ، من جانب الشرق إلى جانب البحر لشمعون قسم واحد '),
(13306, 'Ezekiel', 26, 48, 25, ' وعلى تخم شمعون من جانب الشرق إلى جانب البحر ليساكر قسم واحد '),
(13307, 'Ezekiel', 26, 48, 26, ' وعلى تخم يساكر من جانب الشرق إلى جانب البحر لزبولون قسم واحد '),
(13308, 'Ezekiel', 26, 48, 27, ' وعلى تخم زبولون من جانب الشرق إلى جانب البحر لجاد قسم واحد '),
(13309, 'Ezekiel', 26, 48, 28, ' وعلى تخم جاد من جانب الجنوب يمينا يكون التخم من ثامار إلى مياه مريبة قادش النهر إلى البحر الكبير '),
(13310, 'Ezekiel', 26, 48, 29, ' هذه هي الأرض التي تقسمونها ملكا لأسباط إسرائيل ، وهذه حصصهم ، يقول السيد الرب '),
(13311, 'Ezekiel', 26, 48, 30, ' وهذه مخارج المدينة : من جانب الشمال أربعة آلاف وخمس مئة مقياس '),
(13312, 'Ezekiel', 26, 48, 31, ' وأبواب المدينة على أسماء أسباط إسرائيل . ثلاثة أبواب نحو الشمال : باب رأوبين وباب يهوذا وباب لاوي '),
(13313, 'Ezekiel', 26, 48, 32, ' وإلى جانب الشرق أربعة آلاف وخمس مئة ، وثلاثة أبواب : باب يوسف وباب بنيامين وباب دان '),
(13314, 'Ezekiel', 26, 48, 33, ' وجانب الجنوب أربعة آلاف وخمس مئة مقياس ، وثلاثة أبواب : باب شمعون وباب يساكر وباب زبولون '),
(13315, 'Ezekiel', 26, 48, 34, ' وجانب الغرب أربعة آلاف وخمس مئة ، وثلاثة أبواب : باب جاد وباب أشير وباب نفتالي '),
(13316, 'Ezekiel', 26, 48, 35, ' المحيط ثمانية عشر ألفا ، واسم المدينة من ذلك اليوم : يهوه شمه '),
(13317, 'Ezra', 15, 3, 2, ' وقام يشوع بن يوصاداق وإخوته الكهنة ، وزربابل بن شألتئيل وإخوته ، وبنوا مذبح إله إسرائيل ليصعدوا عليه محرقات ، كما هو مكتوب في شريعة موسى رجل الله '),
(13318, 'Ezra', 15, 3, 3, ' وأقاموا المذبح في مكانه ، لأنه كان عليهم رعب من شعوب الأراضي ، وأصعدوا عليه محرقات للرب ، محرقات الصباح والمساء '),
(13319, 'Ezra', 15, 3, 4, ' وحفظوا عيد المظال كما هو مكتوب ، ومحرقة يوم فيوم بالعدد كالمرسوم ، أمر اليوم بيومه '),
(13320, 'Ezra', 15, 3, 5, ' وبعد ذلك المحرقة الدائمة ، وللأهلة ولجميع مواسم الرب المقدسة ، ولكل من تبرع بمتبرع للرب '),
(13321, 'Ezra', 15, 3, 6, ' ابتدأوا من اليوم الأول من الشهر السابع يصعدون محرقات للرب ، وهيكل الرب لم يكن قد تأسس '),
(13322, 'Ezra', 15, 3, 7, ' وأعطوا فضة للنحاتين والنجارين ، ومأكلا ومشربا وزيتا للصيدونيين والصوريين ليأتوا بخشب أرز من لبنان إلى بحر يافا ، حسب إذن كورش ملك فارس لهم '),
(13323, 'Ezra', 15, 3, 8, ' وفي السنة الثانية من مجيئهم إلى بيت الله إلى أورشليم ، في الشهر الثاني ، شرع زربابل بن شألتئيل ويشوع بن يوصاداق وبقية إخوتهم الكهنة واللاويين وجميع القادمين من السبي إلى أورشليم ، وأقاموا اللاويين من ابن عشرين سنة فما فوق للمناظرة على عمل بيت الرب '),
(13324, 'Ezra', 15, 3, 9, ' ووقف يشوع مع بنيه وإخوته ، قدميئيل وبنيه بني يهوذا معا للمناظرة على عاملي الشغل في بيت الله ، وبني حيناداد مع بنيهم وإخوتهم اللاويين '),
(13325, 'Ezra', 15, 3, 10, ' ولما أسس البانون هيكل الرب ، أقاموا الكهنة بملابسهم بأبواق ، واللاويين بني آساف بالصنوج ، لتسبيح الرب على ترتيب داود ملك إسرائيل '),
(13326, 'Ezra', 15, 3, 11, ' وغنوا بالتسبيح والحمد للرب ، لأنه صالح لأن إلى الأبد رحمته على إسرائيل . وكل الشعب هتفوا هتافا عظيما بالتسبيح للرب لأجل تأسيس بيت الرب '),
(13327, 'Ezra', 15, 3, 12, ' وكثيرون من الكهنة واللاويين ورؤوس الآباء الشيوخ ، الذين رأوا البيت الأول ، بكوا بصوت عظيم عند تأسيس هذا البيت أمام أعينهم . وكثيرون كانوا يرفعون أصواتهم بالهتاف بفرح '),
(13328, 'Ezra', 15, 3, 13, ' ولم يكن الشعب يميز هتاف الفرح من صوت بكاء الشعب ، لأن الشعب كان يهتف هتافا عظيما حتى أن الصوت سمع من بعد '),
(13329, 'Ezra', 15, 4, 1, ' ولما سمع أعداء يهوذا وبنيامين أن بني السبي يبنون هيكلا للرب إله إسرائيل '),
(13330, 'Ezra', 15, 4, 2, ' تقدموا إلى زربابل ورؤوس الآباء وقالوا لهم : نبني معكم لأننا نظيركم نطلب إلهكم ، وله قد ذبحنا من أيام أسرحدون ملك أشور الذي أصعدنا إلى هنا '),
(13331, 'Ezra', 15, 4, 3, ' فقال لهم زربابل ويشوع وبقية رؤوس آباء إسرائيل : ليس لكم ولنا أن نبني بيتا لإلهنا ، ولكننا نحن وحدنا نبني للرب إله إسرائيل كما أمرنا الملك كورش ، ملك فارس '),
(13332, 'Ezra', 15, 4, 4, ' وكان شعب الأرض يرخون أيدي شعب يهوذا ويذعرونهم عن البناء '),
(13333, 'Ezra', 15, 4, 5, ' واستأجروا ضدهم مشيرين ليبطلوا مشورتهم كل أيام كورش ملك فارس وحتى ملك داريوس ملك فارس '),
(13334, 'Ezra', 15, 4, 6, ' وفي ملك أحشويروش ، في ابتداء ملكه ، كتبوا شكوى على سكان يهوذا وأورشليم '),
(13335, 'Ezra', 15, 4, 7, ' وفي أيام أرتحششتا كتب بشلام ومثرداث وطبئيل وسائر رفقائهم إلى أرتحششتا ملك فارس . وكتابة الرسالة مكتوبة بالأرامية ومترجمة بالأرامية '),
(13336, 'Ezra', 15, 4, 8, ' رحوم صاحب القضاء وشمشاي الكاتب كتبا رسالة ضد أورشليم إلى أرتحششتا الملك هكذا '),
(13337, 'Ezra', 15, 4, 9, ' كتب حينئذ رحوم صاحب القضاء وشمشاي الكاتب وسائر رفقائهما الدينيين والأفرستكيين والطرفليين والأفرسيين والأركويين والبابليين والشوشنيين والدهويين والعيلاميين '),
(13338, 'Ezra', 15, 4, 10, ' وسائر الأمم الذين سباهم أسنفر العظيم الشريف وأسكنهم مدن السامرة ، وسائر الذين في عبر النهر وإلى آخره '),
(13339, 'Ezra', 15, 4, 11, ' هذه صورة الرسالة التي أرسلوها إليه ، إلى أرتحششتا الملك : عبيدك القوم الذين في عبر النهر إلى آخره '),
(13340, 'Ezra', 15, 4, 12, ' ليعلم الملك أن اليهود الذين صعدوا من عندك إلينا قد أتوا إلى أورشليم ويبنون المدينة العاصية الردية ، وقد أكملوا أسوارها ورمموا أسسها '),
(13341, 'Ezra', 15, 4, 13, ' ليكن الآن معلوما لدى الملك أنه إذا بنيت هذه المدينة وأكملت أسوارها لا يؤدون جزية ولا خراجا ولا خفارة ، فأخيرا تضر الملوك '),
(13342, 'Ezra', 15, 4, 14, ' والآن بما إننا نأكل ملح دار الملك ، ولا يليق بنا أن نرى ضرر الملك ، لذلك أرسلنا فأعلمنا الملك '),
(13343, 'Ezra', 15, 4, 15, ' لكي يفتش في سفر أخبار آبائك ، فتجد في سفر الأخبار وتعلم أن هذه المدينة مدينة عاصية ومضرة للملوك والبلاد ، وقد عملوا عصيانا في وسطها منذ الأيام القديمة ، لذلك أخربت هذه المدينة '),
(13344, 'Ezra', 15, 4, 16, ' ونحن نعلم الملك أنه إذا بنيت هذه المدينة وأكملت أسوارها لا يكون لك عند ذلك نصيب في عبر النهر '),
(13345, 'Ezra', 15, 4, 17, ' فأرسل الملك جوابا : إلى رحوم صاحب القضاء وشمشاي الكاتب وسائر رفقائهما الساكنين في السامرة ، وباقي الذين في عبر النهر . سلام إلى آخره '),
(13346, 'Ezra', 15, 4, 18, ' الرسالة التي أرسلتموها إلينا قد قرئت بوضوح أمامي '),
(13347, 'Ezra', 15, 4, 19, ' وقد خرج من عندي أمر ففتشوا ووجد أن هذه المدينة منذ الأيام القديمة تقوم على الملوك ، وقد جرى فيها تمرد وعصيان '),
(13348, 'Ezra', 15, 4, 20, ' وقد كان ملوك مقتدرون على أورشليم وتسلطوا على جميع عبر النهر ، وقد أعطوا جزية وخراجا وخفارة '),
(13349, 'Ezra', 15, 4, 21, ' فالآن أخرجوا أمرا بتوقيف أولئك الرجال فلا تبنى هذه المدينة حتى يصدر مني أمر '),
(13350, 'Ezra', 15, 4, 22, ' فاحذروا من أن تقصروا عن عمل ذلك . لماذا يكثر الضرر لخسارة الملوك '),
(13351, 'Ezra', 15, 4, 23, ' حينئذ لما قرئت رسالة أرتحششتا الملك أمام رحوم وشمشاي الكاتب ورفقائهما ذهبوا بسرعة إلى أورشليم ، إلى اليهود ، وأوقفوهم بذراع وقوة '),
(13352, 'Ezra', 15, 4, 24, ' حينئذ توقف عمل بيت الله الذي في أورشليم ، وكان متوقفا إلى السنة الثانية من ملك داريوس ملك فارس '),
(13353, 'Ezra', 15, 5, 1, ' فتنبأ النبيان حجي النبي وزكريا بن عدو لليهود الذين في يهوذا وأورشليم باسم إله إسرائيل عليهم '),
(13354, 'Ezra', 15, 5, 2, ' حينئذ قام زربابل بن شألتئيل ويشوع بن يوصاداق ، وشرعا ببنيان بيت الله الذي في أورشليم ، ومعهما أنبياء الله يساعدونهما '),
(13355, 'Ezra', 15, 5, 3, ' في ذلك الزمان جاء إليهم تتناي والي عبر النهر وشتربوزناي ورفقاؤهما وقالوا لهم هكذا : من أمركم أن تبنوا هذا البيت وتكملوا هذا السور '),
(13356, 'Ezra', 15, 5, 4, ' حينئذ أخبرناهم على هذا المنوال ما هي أسماء الرجال الذين يبنون هذا البناء '),
(13357, 'Ezra', 15, 5, 5, ' وكانت على شيوخ اليهود عين إلههم فلم يوقفوهم حتى وصل الأمر إلى داريوس ، وحينئذ جاوبوا برسالة عن هذا '),
(13358, 'Ezra', 15, 5, 6, ' صورة الرسالة التي أرسلها تتناي والي عبر النهر وشتربوزناي ورفقاؤهما الأفرسكيين الذين في عبر النهر إلى داريوس الملك '),
(13359, 'Ezra', 15, 5, 7, ' أرسلوا إليه رسالة وكان مكتوبا فيها هكذا : لداريوس الملك كل سلام '),
(13360, 'Ezra', 15, 5, 8, ' ليكن معلوما لدى الملك أننا ذهبنا إلى بلاد يهوذا ، إلى بيت الإله العظيم ، وإذا به يبنى بحجارة عظيمة ، ويوضع خشب في الحيطان . وهذا العمل يعمل بسرعة وينجح في أيديهم '),
(13361, 'Ezra', 15, 5, 9, ' حينئذ سألنا أولئك الشيوخ وقلنا لهم هكذا : من أمركم ببناء هذا البيت وتكميل هذه الأسوار '),
(13362, 'Ezra', 15, 5, 10, ' وسألناهم أيضا عن أسمائهم لنعلمك ، وكتبنا أسماء الرجال رؤوسهم '),
(13363, 'Ezra', 15, 5, 11, ' وبمثل هذا الجواب جاوبوا قائلين : نحن عبيد إله السماء والأرض ، ونبني هذا البيت الذي بني قبل هذه السنين الكثيرة ، وقد بناه ملك عظيم لإسرائيل وأكمله '),
(13364, 'Ezra', 15, 5, 12, ' ولكن بعد أن أسخط آباؤنا إله السماء دفعهم ليد نبوخذنصر ملك بابل الكلداني ، الذي هدم هذا البيت وسبى الشعب إلى بابل '),
(13365, 'Ezra', 15, 5, 13, ' على أنه في السنة الأولى لكورش ملك بابل ، أصدر كورش الملك أمرا ببناء بيت الله هذا '),
(13366, 'Ezra', 15, 5, 14, ' حتى إن آنية بيت الله هذا ، التي من ذهب وفضة ، التي أخرجها نبوخذنصر من الهيكل الذي في أورشليم وأتى بها إلى الهيكل الذي في بابل ، أخرجها كورش الملك من الهيكل الذي في بابل وأعطيت لواحد اسمه شيشبصر الذي جعله واليا '),
(13367, 'Ezra', 15, 5, 15, ' وقال له : خذ هذه الآنية واذهب واحملها إلى الهيكل الذي في أورشليم ، وليبن بيت الله في مكانه '),
(13368, 'Ezra', 15, 5, 16, ' حينئذ جاء شيشبصر هذا ووضع أساس بيت الله الذي في أورشليم ، ومن ذلك الوقت إلى الآن يبنى ولم يكمل '),
(13369, 'Ezra', 15, 5, 17, ' والآن إذا حسن عند الملك فليفتش في بيت خزائن الملك الذي هو هناك في بابل : هل كان قد صدر أمر من كورش الملك ببناء بيت الله هذا في أورشليم ؟ وليرسل الملك إلينا مراده في ذلك '),
(13370, 'Ezra', 15, 6, 1, ' حينئذ أمر داريوس الملك ففتشوا في بيت الأسفار حيث كانت الخزائن موضوعة في بابل '),
(13371, 'Ezra', 15, 6, 2, ' فوجد في أحمثا ، في القصر الذي في بلاد مادي ، درج مكتوب فيه هكذا : تذكار '),
(13372, 'Ezra', 15, 6, 3, ' في السنة الأولى لكورش الملك ، أمر كورش الملك من جهة بيت الله في أورشليم : ليبن البيت ، المكان الذي يذبحون فيه ذبائح ، ولتوضع أسسه ، ارتفاعه ستون ذراعا وعرضه ستون ذراعا '),
(13373, 'Ezra', 15, 6, 4, ' بثلاثة صفوف من حجارة عظيمة ، وصف من خشب جديد . ولتعط النفقة من بيت الملك '),
(13374, 'Ezra', 15, 6, 5, ' وأيضا آنية بيت الله ، التي من ذهب وفضة ، التي أخرجها نبوخذنصر من الهيكل الذي في أورشليم وأتى بها إلى بابل ، فلترد وترجع إلى الهيكل الذي في أورشليم إلى مكانها ، وتوضع في بيت الله '),
(13375, 'Ezra', 15, 6, 6, ' والآن يا تتناي والي عبر النهر وشتربوزناي ورفقاءكما الأفرسكيين الذين في عبر النهر ، ابتعدوا من هناك '),
(13376, 'Ezra', 15, 6, 7, ' اتركوا عمل بيت الله هذا . أما والي اليهود وشيوخ اليهود فليبنوا بيت الله هذا في مكانه '),
(13377, 'Ezra', 15, 6, 8, ' وقد صدر مني أمر بما تعملون مع شيوخ اليهود هؤلاء في بناء بيت الله هذا . فمن مال الملك ، من جزية عبر النهر ، تعط النفقة عاجلا لهؤلاء الرجال حتى لا يبطلوا '),
(13378, 'Ezra', 15, 6, 9, ' وما يحتاجون إليه من الثيران والكباش والخراف محرقة لإله السماء ، وحنطة وملح وخمر وزيت حسب قول الكهنة الذين في أورشليم ، لتعط لهم يوما فيوما حتى لا يهدأوا '),
(13379, 'Ezra', 15, 6, 10, ' عن تقريب روائح سرور لإله السماء ، والصلاة لأجل حياة الملك وبنيه '),
(13380, 'Ezra', 15, 6, 11, ' وقد صدر مني أمر أن كل إنسان يغير هذا الكلام تسحب خشبة من بيته ويعلق مصلوبا عليها ، ويجعل بيته مزبلة من أجل هذا '),
(13381, 'Ezra', 15, 6, 12, ' والله الذي أسكن اسمه هناك يهلك كل ملك وشعب يمد يده لتغيير أو لهدم بيت الله هذا الذي في أورشليم . أنا داريوس قد أمرت فليفعل عاجلا '),
(13382, 'Ezra', 15, 6, 13, ' حينئذ تتناي والي عبر النهر وشتربوزناي ورفقاؤهما عملوا عاجلا حسبما أرسل داريوس الملك '),
(13383, 'Ezra', 15, 6, 14, ' وكان شيوخ اليهود يبنون وينجحون حسب نبوة حجي النبي وزكريا بن عدو . فبنوا وأكملوا حسب أمر إله إسرائيل وأمر كورش وداريوس وأرتحششتا ملك فارس '),
(13384, 'Ezra', 15, 6, 15, ' وكمل هذا البيت في اليوم الثالث من شهر أذار ، في السنة السادسة من ملك داريوس الملك '),
(13385, 'Ezra', 15, 6, 16, ' وبنو إسرائيل الكهنة واللاويون وباقي بني السبي دشنوا بيت الله هذا بفرح '),
(13386, 'Ezra', 15, 6, 17, ' وقربوا تدشينا لبيت الله هذا : مئة ثور ومئتي كبش وأربع مئة خروف واثني عشر تيس معزى ، ذبيحة خطية عن جميع إسرائيل ، حسب عدد أسباط إسرائيل '),
(13387, 'Ezra', 15, 6, 18, ' وأقاموا الكهنة في فرقهم واللاويين في أقسامهم على خدمة الله التي في أورشليم ، كما هو مكتوب في سفر موسى '),
(13388, 'Ezra', 15, 6, 19, ' وعمل بنو السبي الفصح في الرابع عشر من الشهر الأول '),
(13389, 'Ezra', 15, 6, 20, ' لأن الكهنة واللاويين تطهروا جميعا . كانوا كلهم طاهرين ، وذبحوا الفصح لجميع بني السبي ولإخوتهم الكهنة ولأنفسهم '),
(13390, 'Ezra', 15, 6, 21, ' وأكله بنو إسرائيل الراجعون من السبي مع جميع الذين انفصلوا إليهم من رجاسة أمم الأرض ، ليطلبوا الرب إله إسرائيل '),
(13391, 'Ezra', 15, 6, 22, ' وعملوا عيد الفطير سبعة أيام بفرح ، لأن الرب فرحهم وحول قلب ملك أشور نحوهم لتقوية أيديهم في عمل بيت الله إله إسرائيل '),
(13392, 'Ezra', 15, 7, 1, ' وبعد هذه الأمور في ملك أرتحششتا ملك فارس ، عزرا بن سرايا بن عزريا بن حلقيا '),
(13393, 'Ezra', 15, 7, 2, ' بن شلوم بن صادوق بن أخيطوب '),
(13394, 'Ezra', 15, 7, 3, ' بن أمريا بن عزريا بن مرايوث '),
(13395, 'Ezra', 15, 7, 4, ' بن زرحيا بن عزي بن بقي '),
(13396, 'Ezra', 15, 7, 5, ' بن أبيشوع بن فينحاس بن ألعازار بن هارون الكاهن الرأس '),
(13397, 'Ezra', 15, 7, 6, ' عزرا هذا صعد من بابل ، وهو كاتب ماهر في شريعة موسى التي أعطاها الرب إله إسرائيل . وأعطاه الملك حسب يد الرب إلهه عليه ، كل سؤله '),
(13398, 'Ezra', 15, 7, 7, ' وصعد معه من بني إسرائيل والكهنة واللاويين والمغنين والبوابين والنثينيم إلى أورشليم في السنة السابعة لأرتحششتا الملك '),
(13399, 'Ezra', 15, 7, 8, ' وجاء إلى أورشليم في الشهر الخامس ، في السنة السابعة للملك '),
(13400, 'Ezra', 15, 7, 9, ' لأنه في الشهر الأول ابتدأ يصعد من بابل ، وفي أول الشهر الخامس جاء إلى أورشليم حسب يد الله الصالحة عليه '),
(13401, 'Ezra', 15, 7, 10, ' لأن عزرا هيأ قلبه لطلب شريعة الرب والعمل بها ، وليعلم إسرائيل فريضة وقضاء '),
(13402, 'Ezra', 15, 7, 11, ' وهذه صورة الرسالة التي أعطاها الملك أرتحششتا لعزرا الكاهن الكاتب ، كاتب كلام وصايا الرب وفرائضه على إسرائيل '),
(13403, 'Ezra', 15, 7, 12, ' من أرتحششتا ملك الملوك ، إلى عزرا الكاهن كاتب شريعة إله السماء الكامل ، إلى آخره '),
(13404, 'Ezra', 15, 7, 13, ' قد صدر مني أمر أن كل من أراد في ملكي من شعب إسرائيل وكهنته واللاويين أن يرجع إلى أورشليم معك فليرجع '),
(13405, 'Ezra', 15, 7, 14, ' من أجل أنك مرسل من قبل الملك ومشيريه السبعة لأجل السؤال عن يهوذا وأورشليم حسب شريعة إلهك التي بيدك '),
(13406, 'Ezra', 15, 7, 15, ' ولحمل فضة وذهب تبرع به الملك ومشيروه لإله إسرائيل الذي في أورشليم مسكنه '),
(13407, 'Ezra', 15, 7, 16, ' وكل الفضة والذهب التي تجد في كل بلاد بابل ، مع تبرعات الشعب والكهنة المتبرعين لبيت إلههم الذي في أورشليم '),
(13408, 'Ezra', 15, 7, 17, ' لكي تشتري عاجلا بهذه الفضة ثيرانا وكباشا وخرافا وتقدماتها وسكائبها ، وتقربها على المذبح الذي في بيت إلهكم الذي في أورشليم '),
(13409, 'Ezra', 15, 7, 18, ' ومهما حسن عندك وعند إخوتك أن تعملوه بباقي الفضة والذهب ، فحسب إرادة إلهكم تعملونه '),
(13410, 'Ezra', 15, 7, 19, ' والآنية التي تعطى لك لأجل خدمة بيت إلهك فسلمها أمام إله أورشليم '),
(13411, 'Ezra', 15, 7, 20, ' وباقي احتياج بيت إلهك الذي يتفق لك أن تعطيه ، فأعطه من بيت خزائن الملك '),
(13412, 'Ezra', 15, 7, 21, ' ومني أنا أرتحششتا الملك صدر أمر إلى كل الخزنة الذين في عبر النهر أن كل ما يطلبه منكم عزرا الكاهن كاتب شريعة إله السماء فليعمل بسرعة '),
(13413, 'Ezra', 15, 7, 22, ' إلى مئة وزنة من الفضة ومئة كر من الحنطة ومئة بث من الخمر ومئة بث من الزيت ، والملح من دون تقييد '),
(13414, 'Ezra', 15, 7, 23, ' كل ما أمر به إله السماء فليعمل باجتهاد لبيت إله السماء ، لأنه لماذا يكون غضب على ملك الملك وبنيه '),
(13415, 'Ezra', 15, 7, 24, ' ونعلمكم أن جميع الكهنة واللاويين والمغنين والبوابين والنثينيم وخدام بيت الله هذا ، لا يؤذن أن يلقى عليهم جزية أو خراج أو خفارة '),
(13416, 'Ezra', 15, 7, 25, ' أما أنت يا عزرا ، فحسب حكمة إلهك التي بيدك ضع حكاما وقضاة يقضون لجميع الشعب الذي في عبر النهر من جميع من يعرف شرائع إلهك . والذين لا يعرفون فعلموهم '),
(13417, 'Ezra', 15, 7, 26, ' وكل من لا يعمل شريعة إلهك وشريعة الملك ، فليقض عليه عاجلا إما بالموت أو بالنفي أو بغرامة المال أو بالحبس '),
(13418, 'Ezra', 15, 7, 27, ' مبارك الرب إله آبائنا الذي جعل مثل هذا في قلب الملك لأجل تزيين بيت الرب الذي في أورشليم '),
(13419, 'Ezra', 15, 7, 28, ' وقد بسط علي رحمة أمام الملك ومشيريه وأمام جميع رؤساء الملك المقتدرين . وأما أنا فقد تشددت حسب يد الرب إلهي علي ، وجمعت من إسرائيل رؤساء ليصعدوا معي '),
(13420, 'Ezra', 15, 8, 1, ' وهؤلاء هم رؤوس آبائهم ونسبة الذين صعدوا معي في ملك أرتحششتا الملك من بابل '),
(13421, 'Ezra', 15, 8, 2, ' من بني فينحاس : جرشوم . من بني إيثامار : دانيال . من بني داود : حطوش '),
(13422, 'Ezra', 15, 8, 3, ' من بني شكنيا ، من بني فرعوش : زكريا ، وانتسب معه من الذكور مئة وخمسون '),
(13423, 'Ezra', 15, 8, 4, ' من بني فحث موآب : أليهوعيناي بن زرحيا ، ومعه مئتان من الذكور '),
(13424, 'Ezra', 15, 8, 5, ' من بني شكنيا : ابن يحزيئيل ، ومعه ثلاث مئة من الذكور '),
(13425, 'Ezra', 15, 8, 6, ' من بني عادين : عابد بن يوناثان ، ومعه خمسون من الذكور '),
(13426, 'Ezra', 15, 8, 7, ' من بني عيلام : يشعيا بن عثليا ، ومعه سبعون من الذكور '),
(13427, 'Ezra', 15, 8, 8, ' ومن بني شفطيا : زبديا بن ميخائيل ، ومعه ثمانون من الذكور '),
(13428, 'Ezra', 15, 10, 32, ' وبنيامين وملوخ وشمريا '),
(13429, 'Ezra', 15, 10, 33, ' من بني حشوم : متناي ومتاثا وزاباد وأليفلط ويريماي ومنسى وشمعي '),
(13430, 'Ezra', 15, 10, 34, ' من بني باني : معداي وعمرام وأوئيل '),
(13431, 'Ezra', 15, 10, 35, ' وبنايا وبيديا وكلوهي '),
(13432, 'Ezra', 15, 10, 36, ' وونيا ومريموث وألياشيب '),
(13433, 'Ezra', 15, 10, 37, ' ومتنيا ومتناي ويعسو '),
(13434, 'Ezra', 15, 10, 38, ' وباني وبنوي وشمعي '),
(13435, 'Ezra', 15, 10, 39, ' وشلميا وناثان وعدايا '),
(13436, 'Ezra', 15, 10, 40, ' ومكندباي وشاشاي وشاراي '),
(13437, 'Ezra', 15, 10, 41, ' وعزرئيل وشلميا وشمريا '),
(13438, 'Ezra', 15, 1, 1, ' وفي السنة الأولى لكورش ملك فارس عند تمام كلام الرب بفم إرميا ، نبه الرب روح كورش ملك فارس فأطلق نداء في كل مملكته وبالكتابة أيضا قائلا '),
(13439, 'Ezra', 15, 1, 2, ' هكذا قال كورش ملك فارس : جميع ممالك الأرض دفعها لي الرب إله السماء ، وهو أوصاني أن أبني له بيتا في أورشليم التي في يهوذا '),
(13440, 'Ezra', 15, 1, 3, ' من منكم من كل شعبه ، ليكن إلهه معه ، ويصعد إلى أورشليم التي في يهوذا فيبني بيت الرب إله إسرائيل . هو الإله الذي في أورشليم '),
(13441, 'Ezra', 15, 1, 4, ' وكل من بقي في أحد الأماكن حيث هو متغرب ، فلينجده أهل مكانه بفضة وبذهب وبأمتعة وببهائم ، مع التبرع لبيت الرب الذي في أورشليم '),
(13442, 'Ezra', 15, 1, 5, ' فقام رؤوس آباء يهوذا وبنيامين ، والكهنة واللاويون ، مع كل من نبه الله روحه ، ليصعدوا ليبنوا بيت الرب الذي في أورشليم '),
(13443, 'Ezra', 15, 1, 6, ' وكل الذين حولهم أعانوهم بآنية فضة وبذهب وبأمتعة وببهائم وبتحف ، فضلا عن كل ما تبرع به '),
(13444, 'Ezra', 15, 1, 7, ' والملك كورش أخرج آنية بيت الرب التي أخرجها نبوخذناصر من أورشليم وجعلها في بيت آلهته '),
(13445, 'Ezra', 15, 1, 8, ' أخرجها كورش ملك فارس عن يد مثرداث الخازن ، وعدها لشيشبصر رئيس يهوذا '),
(13446, 'Ezra', 15, 1, 9, ' وهذا عددها : ثلاثون طستا من ذهب ، وألف طست من فضة ، وتسعة وعشرون سكينا '),
(13447, 'Ezra', 15, 1, 10, ' وثلاثون قدحا من ذهب ، وأقداح فضة من الرتبة الثانية أربع مئة وعشرة ، وألف من آنية أخرى '),
(13448, 'Ezra', 15, 1, 11, ' جميع الآنية من الذهب والفضة خمسة آلاف وأربع مئة . الكل أصعده شيشبصر عند إصعاد السبي من بابل إلى أورشليم '),
(13449, 'Ezra', 15, 2, 1, ' وهؤلاء هم بنو الكورة الصاعدون من سبي المسبيين ، الذين سباهم نبوخذناصر ملك بابل إلى بابل ، ورجعوا إلى أورشليم ويهوذا ، كل واحد إلى مدينته '),
(13450, 'Ezra', 15, 2, 2, ' الذين جاءوا مع زربابل ، يشوع ، نحميا ، سرايا ، رعلايا ، مردخاي ، بلشان ، مسفار ، بغواي ، رحوم ، بعنة . عدد رجال شعب إسرائيل '),
(13451, 'Ezra', 15, 2, 3, ' بنو فرعوش ألفان ومئة واثنان وسبعون '),
(13452, 'Ezra', 15, 2, 4, ' بنو شفطيا ثلاث مئة واثنان وسبعون '),
(13453, 'Ezra', 15, 2, 5, ' بنو آرح سبع مئة وخمسة وسبعون '),
(13454, 'Ezra', 15, 2, 6, ' بنو فحث موآب من بني يشوع ويوآب ألفان وثمان مئة واثنا عشر '),
(13455, 'Ezra', 15, 2, 7, ' بنو عيلام ألف ومئتان وأربعة وخمسون '),
(13456, 'Ezra', 15, 2, 8, ' بنو زتو تسع مئة وخمسة وأربعون '),
(13457, 'Ezra', 15, 2, 9, ' بنو زكاي سبع مئة وستون '),
(13458, 'Ezra', 15, 2, 10, ' بنو باني ست مئة واثنان وأربعون '),
(13459, 'Ezra', 15, 2, 11, ' بنو باباي ست مئة وثلاثة وعشرون '),
(13460, 'Ezra', 15, 2, 12, ' بنو عرجد ألف ومئتان واثنان وعشرون '),
(13461, 'Ezra', 15, 2, 13, ' بنو أدونيقام ست مئة وستة وستون '),
(13462, 'Ezra', 15, 2, 14, ' بنو بغواي ألفان وستة وخمسون '),
(13463, 'Ezra', 15, 2, 15, ' بنو عادين أربع مئة وأربعة وخمسون '),
(13464, 'Ezra', 15, 2, 16, ' بنو آطير من يحزقيا ثمانية وتسعون '),
(13465, 'Ezra', 15, 2, 17, ' بنو بيصاي ثلاث مئة وثلاثة وعشرون '),
(13466, 'Ezra', 15, 2, 18, ' بنو يورة مئة واثنا عشر '),
(13467, 'Ezra', 15, 2, 19, ' بنو حشوم مئتان وثلاثة وعشرون '),
(13468, 'Ezra', 15, 2, 20, ' بنو جبار خمسة وتسعون '),
(13469, 'Ezra', 15, 2, 21, ' بنو بيت لحم مئة وثلاثة وعشرون '),
(13470, 'Ezra', 15, 2, 22, ' رجال نطوفة ستة وخمسون '),
(13471, 'Ezra', 15, 2, 23, ' رجال عناثوث مئة وثمانية وعشرون '),
(13472, 'Ezra', 15, 2, 24, ' بنو عزموت اثنان وأربعون '),
(13473, 'Ezra', 15, 2, 25, ' بنو قرية عاريم كفيرة وبئيروت سبع مئة وثلاثة وأربعون '),
(13474, 'Ezra', 15, 2, 26, ' بنو الرامة وجبع ست مئة وواحد وعشرون '),
(13475, 'Ezra', 15, 2, 27, ' رجال مخماس مئة واثنان وعشرون '),
(13476, 'Ezra', 15, 2, 28, ' رجال بيت إيل وعاي مئتان وثلاثة وعشرون '),
(13477, 'Ezra', 15, 2, 29, ' بنو نبو اثنان وخمسون '),
(13478, 'Ezra', 15, 2, 30, ' بنو مغبيش مئة وستة وخمسون '),
(13479, 'Ezra', 15, 2, 31, ' بنو عيلام الآخر ألف ومئتان وأربعة وخمسون '),
(13480, 'Ezra', 15, 2, 32, ' بنو حاريم ثلاث مئة وعشرون '),
(13481, 'Ezra', 15, 2, 33, ' بنو لود بنو حاديد وأونو سبع مئة وخمسة وعشرون '),
(13482, 'Ezra', 15, 2, 34, ' بنو أريحا ثلاث مئة وخمسة وأربعون '),
(13483, 'Ezra', 15, 2, 35, ' بنو سناءة ثلاثة آلاف وست مئة وثلاثون '),
(13484, 'Ezra', 15, 2, 36, ' أما الكهنة : فبنو يدعيا من بيت يشوع تسع مئة وثلاثة وسبعون '),
(13485, 'Ezra', 15, 2, 37, ' بنو إمير ألف واثنان وخمسون '),
(13486, 'Ezra', 15, 2, 38, ' بنو فشحور ألف ومئتان وسبعة وأربعون '),
(13487, 'Ezra', 15, 8, 9, ' من بني يوآب : عوبديا بن يحيئيل ، ومعه مئتان وثمانية عشر من الذكور '),
(13488, 'Ezra', 15, 8, 10, ' ومن بني شلوميث : ابن يوشفيا ، ومعه مئة وستون من الذكور '),
(13489, 'Ezra', 15, 8, 11, ' ومن بني باباي : زكريا بن باباي ، ومعه ثمانية وعشرون من الذكور '),
(13490, 'Ezra', 15, 8, 12, ' ومن بني عزجد : يوحانان بن هقاطان ، ومعه مئة وعشرة من الذكور '),
(13491, 'Ezra', 15, 8, 13, ' ومن بني أدونيقام الآخرين وهذه أسماؤهم : أليفلط ويعيئيل وشمعيا ، ومعهم ستون من الذكور '),
(13492, 'Ezra', 15, 8, 14, ' ومن بني بغواي : عوتاي وزبود ، ومعهما سبعون من الذكور '),
(13493, 'Ezra', 15, 8, 15, ' فجمعتهم إلى النهر الجاري إلى أهوا ونزلنا هناك ثلاثة أيام . وتأملت الشعب والكهنة ، ولكنني لم أجد أحدا من اللاويين هناك '),
(13494, 'Ezra', 15, 8, 16, ' فأرسلت إلى : أليعزر وأريئيل وشمعيا وألناثان وياريب وألناثان وناثان وزكريا ومشلام الرؤوس ، وإلى يوياريب وألناثان الفهيمين '),
(13495, 'Ezra', 15, 8, 17, ' وأرسلتهم إلى إدو الرأس في المكان المسمى كسفيا ، وجعلت في أفواههم كلاما يكلمون به إدو وإخوته النثينيم في المكان كسفيا ليأتوا إلينا بخدام لبيت إلهنا '),
(13496, 'Ezra', 15, 8, 18, ' فأتوا إلينا حسب يد الله الصالحة علينا برجل فطن من بني محلي بن لاوي بن إسرائيل وشربيا وبنيه وإخوته ثمانية عشر '),
(13497, 'Ezra', 15, 8, 19, ' وحشبيا ومعه يشعيا من بني مراري وإخوته وبنوهم عشرون '),
(13498, 'Ezra', 15, 8, 20, ' ومن النثينيم الذين جعلهم داود مع الرؤساء لخدمة اللاويين من النثينيم مئتين وعشرين . الجميع تعينوا بأسمائهم '),
(13499, 'Ezra', 15, 8, 21, ' وناديت هناك بصوم على نهر أهوا لكي نتذلل أمام إلهنا لنطلب منه طريقا مستقيمة لنا ولأطفالنا ولكل مالنا '),
(13500, 'Ezra', 15, 8, 22, ' لأني خجلت من أن أطلب من الملك جيشا وفرسانا لينجدونا على العدو في الطريق ، لأننا كلمنا الملك قائلين : إن يد إلهنا على كل طالبيه للخير ، وصولته وغضبه على كل من يتركه '),
(13501, 'Ezra', 15, 8, 23, ' فصمنا وطلبنا ذلك من إلهنا فاستجاب لنا '),
(13502, 'Ezra', 15, 8, 24, ' وأفرزت من رؤساء الكهنة اثني عشر : شربيا وحشبيا ، ومعهما من إخوتهما عشرة '),
(13503, 'Ezra', 15, 8, 25, ' ووزنت لهم الفضة والذهب والآنية ، تقدمة بيت إلهنا التي قدمها الملك ومشيروه ورؤساؤه وجميع إسرائيل الموجودين '),
(13504, 'Ezra', 15, 8, 26, ' وزنت ليدهم ست مئة وخمسين وزنة من الفضة ، ومئة وزنة من آنية الفضة ، ومئة وزنة من الذهب '),
(13505, 'Ezra', 15, 8, 27, ' وعشرين قدحا من الذهب ألف درهم ، وآنية من نحاس صقيل جيد ثمين كالذهب '),
(13506, 'Ezra', 15, 8, 28, ' وقلت لهم : أنتم مقدسون للرب ، والآنية مقدسة ، والفضة والذهب تبرع للرب إله آبائكم '),
(13507, 'Ezra', 15, 8, 29, ' فاسهروا واحفظوها حتى تزنوها أمام رؤساء الكهنة واللاويين ورؤساء آباء إسرائيل في أورشليم ، في مخادع بيت الرب '),
(13508, 'Ezra', 15, 8, 30, ' فأخذ الكهنة واللاويون وزن الفضة والذهب والآنية ليأتوا بها إلى أورشليم ، إلى بيت إلهنا '),
(13509, 'Ezra', 15, 8, 31, ' ثم رحلنا من نهر أهوا في الثاني عشر من الشهر الأول لنذهب إلى أورشليم ، وكانت يد إلهنا علينا ، فأنقذنا من يد العدو والكامن على الطريق '),
(13510, 'Ezra', 15, 8, 32, ' فأتينا إلى أورشليم وأقمنا هناك ثلاثة أيام '),
(13511, 'Ezra', 15, 8, 33, ' وفي اليوم الرابع وزنت الفضة والذهب والآنية في بيت إلهنا على يد مريموث بن أوريا الكاهن ، ومعه ألعازار بن فينحاس ، ومعهما يوزاباد بن يشوع ونوعديا بن بنوي اللاويان '),
(13512, 'Ezra', 15, 8, 34, ' بالعدد والوزن للكل ، وكتب كل الوزن في ذلك الوقت '),
(13513, 'Ezra', 15, 8, 35, ' وبنو السبي القادمون من السبي قربوا محرقات لإله إسرائيل ، اثني عشر ثورا عن كل إسرائيل ، وستة وتسعين كبشا وسبعة وسبعين خروفا واثني عشر تيسا ، ذبيحة خطية الجميع محرقة للرب '),
(13514, 'Ezra', 15, 8, 36, ' وأعطوا أوامر الملك لمرازبة الملك وولاة عبر النهر ، فأعانوا الشعب وبيت الله '),
(13515, 'Ezra', 15, 9, 1, ' ولما كملت هذه تقدم إلي الرؤساء قائلين : لم ينفصل شعب إسرائيل والكهنة واللاويون من شعوب الأراضي حسب رجاساتهم ، من الكنعانيين والحثيين والفرزيين واليبوسيين والعمونيين والموآبيين والمصريين والأموريين '),
(13516, 'Ezra', 15, 9, 2, ' لأنهم اتخذوا من بناتهم لأنفسهم ولبنيهم ، واختلط الزرع المقدس بشعوب الأراضي . وكانت يد الرؤساء والولاة في هذه الخيانة أولا '),
(13517, 'Ezra', 15, 9, 3, ' فلما سمعت بهذا الأمر مزقت ثيابي وردائي ونتفت شعر رأسي وذقني وجلست متحيرا '),
(13518, 'Ezra', 15, 9, 4, ' فاجتمع إلي كل من ارتعد من كلام إله إسرائيل من أجل خيانة المسبيين ، وأنا جلست متحيرا إلى تقدمة المساء '),
(13519, 'Ezra', 15, 9, 5, ' وعند تقدمة المساء قمت من تذللي ، وفي ثيابي وردائي الممزقة جثوت على ركبتي وبسطت يدي إلى الرب إلهي '),
(13520, 'Ezra', 15, 9, 6, ' وقلت : اللهم ، إني أخجل وأخزى من أن أرفع يا إلهي وجهي نحوك ، لأن ذنوبنا قد كثرت فوق رؤوسنا ، وآثامنا تعاظمت إلى السماء '),
(13521, 'Ezra', 15, 9, 7, ' منذ أيام آبائنا نحن في إثم عظيم إلى هذا اليوم . ولأجل ذنوبنا قد دفعنا نحن وملوكنا وكهنتنا ليد ملوك الأراضي للسيف والسبي والنهب وخزي الوجوه كهذا اليوم '),
(13522, 'Ezra', 15, 9, 8, ' والآن ، كلحيظة كانت رأفة من لدن الرب إلهنا ليبقي لنا نجاة ويعطينا وتدا في مكان قدسه ، لينير إلهنا أعيننا ويعطينا حياة قليلة في عبوديتنا '),
(13523, 'Ezra', 15, 9, 9, ' لأننا عبيد نحن ، وفي عبوديتنا لم يتركنا إلهنا بل بسط علينا رحمة أمام ملوك فارس ، ليعطينا حياة لنرفع بيت إلهنا ونقيم خرائبه ، وليعطينا حائطا في يهوذا وفي أورشليم '),
(13524, 'Ezra', 15, 9, 10, ' والآن ، فماذا نقول يا إلهنا بعد هذا ؟ لأننا قد تركنا وصاياك '),
(13525, 'Ezra', 15, 9, 11, ' التي أوصيت بها عن يد عبيدك الأنبياء قائلا : إن الأرض التي تدخلون لتمتلكوها هي أرض متنجسة بنجاسة شعوب الأراضي ، برجاساتهم التي ملأوها بها من جهة إلى جهة بنجاستهم '),
(13526, 'Ezra', 15, 9, 12, ' والآن ، فلا تعطوا بناتكم لبنيهم ولا تأخذوا بناتهم لبنيكم ، ولا تطلبوا سلامتهم وخيرهم إلى الأبد لكي تتشددوا وتأكلوا خير الأرض وتورثوا بنيكم إياها إلى الأبد '),
(13527, 'Ezra', 15, 9, 13, ' وبعد كل ما جاء علينا لأجل أعمالنا الرديئة وآثامنا العظيمة ، لأنك قد جازيتنا يا إلهنا أقل من آثامنا وأعطيتنا نجاة كهذه '),
(13528, 'Ezra', 15, 9, 14, ' أفنعود ونتعدى وصاياك ونصاهر شعوب هذه الرجاسات ؟ أما تسخط علينا حتى تفنينا فلا تكون بقية ولا نجاة '),
(13529, 'Ezra', 15, 9, 15, ' أيها الرب إله إسرائيل ، أنت بار لأننا بقينا ناجين كهذا اليوم . ها نحن أمامك في آثامنا ، لأنه ليس لنا أن نقف أمامك من أجل هذا '),
(13530, 'Ezra', 15, 10, 1, ' فلما صلى عزرا واعترف وهو باك وساقط أمام بيت الله ، اجتمع إليه من إسرائيل جماعة كثيرة جدا من الرجال والنساء والأولاد ، لأن الشعب بكى بكاء عظيما '),
(13531, 'Ezra', 15, 10, 2, ' وأجاب شكنيا بن يحيئيل من بني عيلام وقال لعزرا : إننا قد خنا إلهنا واتخذنا نساء غريبة من شعوب الأرض . ولكن الآن يوجد رجاء لإسرائيل في هذا '),
(13532, 'Ezra', 15, 10, 3, ' فلنقطع الآن عهدا مع إلهنا أن نخرج كل النساء والذين ولدوا منهن ، حسب مشورة سيدي ، والذين يخشون وصية إلهنا ، وليعمل حسب الشريعة '),
(13533, 'Ezra', 15, 10, 4, ' قم فإن عليك الأمر ونحن معك . تشجع وافعل '),
(13534, 'Ezra', 15, 10, 5, ' فقام عزرا واستحلف رؤساء الكهنة واللاويين وكل إسرائيل أن يعملوا حسب هذا الأمر ، فحلفوا '),
(13535, 'Ezra', 15, 10, 6, ' ثم قام عزرا من أمام بيت الله وذهب إلى مخدع يهوحانان بن ألياشيب . فانطلق إلى هناك وهو لم يأكل خبزا ولم يشرب ماء ، لأنه كان ينوح بسبب خيانة أهل السبي '),
(13536, 'Ezra', 15, 10, 7, ' وأطلقوا نداء في يهوذا وأورشليم إلى جميع بني السبي لكي يجتمعوا إلى أورشليم '),
(13537, 'Ezra', 15, 10, 8, ' وكل من لا يأتي في ثلاثة أيام حسب مشورة الرؤساء والشيوخ يحرم كل ماله ، وهو يفرز من جماعة أهل السبي '),
(13538, 'Ezra', 15, 10, 9, ' فاجتمع كل رجال يهوذا وبنيامين إلى أورشليم في الثلاثة الأيام ، أي في الشهر التاسع ، في العشرين من الشهر ، وجلس جميع الشعب في ساحة بيت الله مرتعدين من الأمر ومن الأمطار '),
(13539, 'Ezra', 15, 10, 10, ' فقام عزرا الكاهن وقال لهم : إنكم قد خنتم واتخذتم نساء غريبة لتزيدوا على إثم إسرائيل '),
(13540, 'Ezra', 15, 10, 11, ' فاعترفوا الآن للرب إله آبائكم واعملوا مرضاته ، وانفصلوا عن شعوب الأرض وعن النساء الغريبة '),
(13541, 'Ezra', 15, 10, 12, ' فأجاب كل الجماعة وقالوا بصوت عظيم : كما كلمتنا كذلك نعمل '),
(13542, 'Ezra', 15, 10, 13, ' إلا أن الشعب كثير ، والوقت وقت أمطار ، ولا طاقة لنا على الوقوف في الخارج ، والعمل ليس ليوم واحد أو لاثنين ، لأننا قد أكثرنا الذنب في هذا الأمر '),
(13543, 'Ezra', 15, 10, 14, ' فليقف رؤساؤنا لكل الجماعة . وكل الذين في مدننا قد اتخذوا نساء غريبة ، فليأتوا في أوقات معينة ومعهم شيوخ مدينة فمدينة وقضاتها ، حتى يرتد عنا حمو غضب إلهنا من أجل هذا الأمر '),
(13544, 'Ezra', 15, 10, 15, ' ويوناثان بن عسائيل ويحزيا بن تقوة فقط قاما على هذا ، ومشلام وشبتاي اللاوي ساعداهما '),
(13545, 'Ezra', 15, 10, 16, ' وفعل هكذا بنو السبي . وانفصل عزرا الكاهن ورجال رؤوس آباء ، حسب بيوت آبائهم ، وجميعهم بأسمائهم ، وجلسوا في اليوم الأول من الشهر العاشر للفحص عن الأمر '),
(13546, 'Ezra', 15, 10, 17, ' وانتهوا من كل الرجال الذين اتخذوا نساء غريبة في اليوم الأول من الشهر الأول '),
(13547, 'Ezra', 15, 10, 18, ' فوجد بين بني الكهنة من اتخذ نساء غريبة : فمن بني يشوع بن يوصاداق وإخوته : معشيا وأليعزر وياريب وجدليا '),
(13548, 'Ezra', 15, 10, 19, ' وأعطوا أيديهم لإخراج نسائهم مقربين كبش غنم لأجل إثمهم '),
(13549, 'Ezra', 15, 10, 20, ' ومن بني إمير : حناني وزبديا '),
(13550, 'Ezra', 15, 10, 21, ' ومن بني حاريم : معسيا وإيليا وشمعيا ويحيئيل وعزيا '),
(13551, 'Ezra', 15, 10, 22, ' ومن بني فشحور : أليوعيناي ومعسيا وإسماعيل ونثنئيل ويوزاباد وألعاسة '),
(13552, 'Ezra', 15, 10, 23, ' ومن اللاويين : يوزاباد وشمعي وقلايا ، هو قليطا ، وفتحيا ويهوذا وأليعزر '),
(13553, 'Ezra', 15, 10, 24, ' ومن المغنين : ألياشيب . ومن البوابين : شلوم وطالم وأوري '),
(13554, 'Ezra', 15, 10, 25, ' ومن إسرائيل من بني فرعوش : رميا ويزيا وملكيا وميامين وألعازار وملكيا وبنايا '),
(13555, 'Ezra', 15, 10, 26, ' ومن بني عيلام : متنيا وزكريا ويحيئيل وعبدي ويريموث وإيليا '),
(13556, 'Ezra', 15, 10, 27, ' ومن بني زتو : أليوعيناي وألياشيب ومتنيا ويريموث وزاباد وعزيزا '),
(13557, 'Ezra', 15, 10, 28, ' ومن بني باباي : يهوحانان وحننيا وزباي وعثلاي '),
(13558, 'Ezra', 15, 10, 29, ' ومن بني باني : مشلام وملوخ وعدايا وياشوب وشآل وراموث '),
(13559, 'Ezra', 15, 10, 30, ' ومن بني فحث موآب : عدنا وكلال وبنايا ومعسيا ومتنيا وبصلئيل وبنوي ومنسى '),
(13560, 'Ezra', 15, 10, 31, ' وبنو حاريم : أليعزر ويشيا وملكيا وشمعيا وشمعون '),
(13561, 'Ezra', 15, 2, 39, ' بنو حاريم ألف وسبعة عشر '),
(13562, 'Ezra', 15, 2, 40, ' أما اللاويون : فبنو يشوع وقدميئيل من بني هودويا أربعة وسبعون '),
(13563, 'Ezra', 15, 2, 41, ' المغنون بنو آساف مئة وثمانية وعشرون '),
(13564, 'Ezra', 15, 2, 42, ' بنو البوابين : بنو شلوم ، بنو آطير ، بنو طلمون ، بنو عقوب ، بنو حطيطا ، بنو شوباي ، الجميع مئة وتسعة وثلاثون '),
(13565, 'Ezra', 15, 2, 43, ' النثينيم : بنو صيحا ، بنو حسوفا ، بنو طباعوت '),
(13566, 'Ezra', 15, 2, 44, ' بنو قيروس ، بنو سيعها ، بنو فادون '),
(13567, 'Ezra', 15, 2, 45, ' بنو لبانة ، بنو حجابة ، بنو عقوب '),
(13568, 'Ezra', 15, 2, 46, ' بنو حاجاب ، بنو شملاي ، بنو حانان '),
(13569, 'Ezra', 15, 2, 47, ' بنو جديل ، بنو حجر ، بنو رآيا '),
(13570, 'Ezra', 15, 2, 48, ' بنو رصين ، بنو نقودا ، بنو جزام '),
(13571, 'Ezra', 15, 2, 49, ' بنو عزا ، بنو فاسيح ، بنو بيساي '),
(13572, 'Ezra', 15, 2, 50, ' بنو أسنة ، بنو معونيم ، بنو نفوسيم '),
(13573, 'Ezra', 15, 2, 51, ' بنو بقبوق ، بنو حقوفا ، بنو حرحور '),
(13574, 'Ezra', 15, 2, 52, ' بنو بصلوت ، بنو محيدا ، بنو حرشا '),
(13575, 'Ezra', 15, 2, 53, ' بنو برقوس ، بنو سيسرا ، بنو ثامح '),
(13576, 'Ezra', 15, 2, 54, ' بنو نصيح ، بنو حطيفا '),
(13577, 'Ezra', 15, 2, 55, ' بنو عبيد سليمان : بنو سوطاي ، بنو هسوفرث ، بنو فرودا '),
(13578, 'Ezra', 15, 2, 56, ' بنو يعلة ، بنو درقون ، بنو جديل '),
(13579, 'Ezra', 15, 2, 57, ' بنو شفطيا ، بنو حطيل ، بنو فوخرة الظباء ، بنو آمي '),
(13580, 'Ezra', 15, 2, 58, ' جميع النثينيم وبني عبيد سليمان ثلاث مئة واثنان وتسعون '),
(13581, 'Ezra', 15, 2, 59, ' وهؤلاء هم الذين صعدوا من تل ملح وتل حرشا ، كروب ، أدان ، إمير ، ولم يستطيعوا أن يبينوا بيوت آبائهم ونسلهم هل هم من إسرائيل '),
(13582, 'Ezra', 15, 2, 60, ' بنو دلايا ، بنو طوبيا ، بنو نقودا ، ست مئة واثنان وخمسون '),
(13583, 'Ezra', 15, 2, 61, ' ومن بني الكهنة : بنو حبايا ، بنو هقوص ، بنو برزلاي الذي أخذ امرأة من بنات برزلاي الجلعادي وتسمى باسمهم '),
(13584, 'Ezra', 15, 2, 62, ' هؤلاء فتشوا على كتابة أنسابهم فلم توجد ، فرذلوا من الكهنوت '),
(13585, 'Ezra', 15, 2, 63, ' وقال لهم الترشاثا أن لا يأكلوا من قدس الأقداس حتى يقوم كاهن للأوريم والتميم '),
(13586, 'Ezra', 15, 2, 64, ' كل الجمهور معا اثنان وأربعون ألفا وثلاث مئة وستون '),
(13587, 'Ezra', 15, 2, 65, ' فضلا عن عبيدهم وإمائهم فهؤلاء كانوا سبعة آلاف وثلاث مئة وسبعة وثلاثين ، ولهم من المغنين والمغنيات مئتان '),
(13588, 'Ezra', 15, 2, 66, ' خيلهم سبع مئة وستة وثلاثون . بغالهم مئتان وخمسة وأربعون '),
(13589, 'Ezra', 15, 2, 67, ' جمالهم أربع مئة وخمسة وثلاثون . حميرهم ستة آلاف وسبع مئة وعشرون '),
(13590, 'Ezra', 15, 2, 68, ' والبعض من رؤوس الآباء عند مجيئهم إلى بيت الرب الذي في أورشليم تبرعوا لبيت الرب لإقامته في مكانه '),
(13591, 'Ezra', 15, 2, 69, ' أعطوا حسب طاقتهم لخزانة العمل واحدا وستين ألف درهم من الذهب ، وخمسة آلاف منا من الفضة ، ومئة قميص للكهنة '),
(13592, 'Ezra', 15, 2, 70, ' فأقام الكهنة واللاويون وبعض الشعب والمغنون والبوابون والنثينيم في مدنهم ، وكل إسرائيل في مدنهم '),
(13593, 'Ezra', 15, 3, 1, ' ولما استهل الشهر السابع وبنو إسرائيل في مدنهم ، اجتمع الشعب كرجل واحد إلى أورشليم '),
(13594, 'Ezra', 15, 10, 42, ' وشلوم وأمريا ويوسف '),
(13595, 'Ezra', 15, 10, 43, ' من بني نبو : يعيئيل ومتثيا وزاباد وزبينا ويدو ويوئيل وبنايا '),
(13596, 'Ezra', 15, 10, 44, ' كل هؤلاء اتخذوا نساء غريبة ومنهن نساء قد وضعن بنين '),
(13597, 'Galatians', 48, 1, 1, ' بولس ، رسول لا من الناس ولا بإنسان ، بل بيسوع المسيح والله الآب الذي أقامه من الأموات '),
(13598, 'Galatians', 48, 1, 2, ' وجميع الإخوة الذين معي ، إلى كنائس غلاطية '),
(13599, 'Galatians', 48, 1, 3, ' نعمة لكم وسلام من الله الآب ، ومن ربنا يسوع المسيح '),
(13600, 'Galatians', 48, 1, 4, ' الذي بذل نفسه لأجل خطايانا ، لينقذنا من العالم الحاضر الشرير حسب إرادة الله وأبينا '),
(13601, 'Galatians', 48, 1, 5, ' الذي له المجد إلى أبد الآبدين . آمين '),
(13602, 'Galatians', 48, 1, 6, ' إني أتعجب أنكم تنتقلون هكذا سريعا عن الذي دعاكم بنعمة المسيح إلى إنجيل آخر '),
(13603, 'Galatians', 48, 1, 7, ' ليس هو آخر ، غير أنه يوجد قوم يزعجونكم ويريدون أن يحولوا إنجيل المسيح '),
(13604, 'Galatians', 48, 1, 8, ' ولكن إن بشرناكم نحن أو ملاك من السماء بغير ما بشرناكم ، فليكن أناثيما '),
(13605, 'Galatians', 48, 1, 9, ' كما سبقنا فقلنا أقول الآن أيضا : إن كان أحد يبشركم بغير ما قبلتم ، فليكن أناثيما '),
(13606, 'Galatians', 48, 1, 10, ' أفأستعطف الآن الناس أم الله ؟ أم أطلب أن أرضي الناس ؟ فلو كنت بعد أرضي الناس ، لم أكن عبدا للمسيح '),
(13607, 'Galatians', 48, 1, 11, ' وأعرفكم أيها الإخوة الإنجيل الذي بشرت به ، أنه ليس بحسب إنسان '),
(13608, 'Galatians', 48, 1, 12, ' لأني لم أقبله من عند إنسان ولا علمته . بل بإعلان يسوع المسيح '),
(13609, 'Galatians', 48, 1, 13, ' فإنكم سمعتم بسيرتي قبلا في الديانة اليهودية ، أني كنت أضطهد كنيسة الله بإفراط وأتلفها '),
(13610, 'Galatians', 48, 1, 14, ' وكنت أتقدم في الديانة اليهودية على كثيرين من أترابي في جنسي ، إذ كنت أوفر غيرة في تقليدات آبائي '),
(13611, 'Galatians', 48, 1, 15, ' ولكن لما سر الله الذي أفرزني من بطن أمي ، ودعاني بنعمته '),
(13612, 'Galatians', 48, 1, 16, ' أن يعلن ابنه في لأبشر به بين الأمم ، للوقت لم أستشر لحما ودما '),
(13613, 'Galatians', 48, 1, 17, ' ولا صعدت إلى أورشليم ، إلى الرسل الذين قبلي ، بل انطلقت إلى العربية ، ثم رجعت أيضا إلى دمشق '),
(13614, 'Galatians', 48, 1, 18, ' ثم بعد ثلاث سنين صعدت إلى أورشليم لأتعرف ببطرس ، فمكثت عنده خمسة عشر يوما '),
(13615, 'Galatians', 48, 1, 19, ' ولكنني لم أر غيره من الرسل إلا يعقوب أخا الرب '),
(13616, 'Galatians', 48, 1, 20, ' والذي أكتب به إليكم هوذا قدام الله أني لست أكذب فيه '),
(13617, 'Galatians', 48, 1, 21, ' وبعد ذلك جئت إلى أقاليم سورية وكيليكية '),
(13618, 'Galatians', 48, 1, 22, ' ولكنني كنت غير معروف بالوجه عند كنائس اليهودية التي في المسيح '),
(13619, 'Galatians', 48, 1, 23, ' غير أنهم كانوا يسمعون : أن الذي كان يضطهدنا قبلا ، يبشر الآن بالإيمان الذي كان قبلا يتلفه '),
(13620, 'Galatians', 48, 1, 24, ' فكانوا يمجدون الله في '),
(13621, 'Galatians', 48, 2, 1, ' ثم بعد أربع عشرة سنة صعدت أيضا إلى أورشليم مع برنابا ، آخذا معي تيطس أيضا '),
(13622, 'Galatians', 48, 2, 2, ' وإنما صعدت بموجب إعلان ، وعرضت عليهم الإنجيل الذي أكرز به بين الأمم ، ولكن بالانفراد على المعتبرين ، لئلا أكون أسعى أو قد سعيت باطلا '),
(13623, 'Galatians', 48, 2, 3, ' لكن لم يضطر ولا تيطس الذي كان معي ، وهو يوناني ، أن يختتن '),
(13624, 'Galatians', 48, 2, 4, ' ولكن بسبب الإخوة الكذبة المدخلين خفية ، الذين دخلوا اختلاسا ليتجسسوا حريتنا التي لنا في المسيح كي يستعبدونا '),
(13625, 'Galatians', 48, 2, 5, ' الذين لم نذعن لهم بالخضوع ولا ساعة ، ليبقى عندكم حق الإنجيل '),
(13626, 'Galatians', 48, 2, 6, ' وأما المعتبرون أنهم شيء - مهما كانوا ، لا فرق عندي ، الله لا يأخذ بوجه إنسان - فإن هؤلاء المعتبرين لم يشيروا علي بشيء '),
(13627, 'Galatians', 48, 2, 7, ' بل بالعكس ، إذ رأوا أني اؤتمنت على إنجيل الغرلة كما بطرس على إنجيل الختان '),
(13628, 'Galatians', 48, 2, 8, ' فإن الذي عمل في بطرس لرسالة الختان عمل في أيضا للأمم '),
(13629, 'Galatians', 48, 2, 9, ' فإذ علم بالنعمة المعطاة لي يعقوب وصفا ويوحنا ، المعتبرون أنهم أعمدة ، أعطوني وبرنابا يمين الشركة لنكون نحن للأمم ، وأما هم فللختان '),
(13630, 'Galatians', 48, 2, 10, ' غير أن نذكر الفقراء . وهذا عينه كنت اعتنيت أن أفعله '),
(13631, 'Galatians', 48, 2, 11, ' ولكن لما أتى بطرس إلى أنطاكية قاومته مواجهة ، لأنه كان ملوما '),
(13632, 'Galatians', 48, 2, 12, ' لأنه قبلما أتى قوم من عند يعقوب كان يأكل مع الأمم ، ولكن لما أتوا كان يؤخر ويفرز نفسه ، خائفا من الذين هم من الختان '),
(13633, 'Galatians', 48, 2, 13, ' وراءى معه باقي اليهود أيضا ، حتى إن برنابا أيضا انقاد إلى ريائهم '),
(13634, 'Galatians', 48, 2, 14, ' لكن لما رأيت أنهم لا يسلكون باستقامة حسب حق الإنجيل ، قلت لبطرس قدام الجميع : إن كنت وأنت يهودي تعيش أمميا لا يهوديا ، فلماذا تلزم الأمم أن يتهودوا '),
(13635, 'Galatians', 48, 2, 15, ' نحن بالطبيعة يهود ولسنا من الأمم خطاة '),
(13636, 'Galatians', 48, 2, 16, ' إذ نعلم أن الإنسان لا يتبرر بأعمال الناموس ، بل بإيمان يسوع المسيح ، آمنا نحن أيضا بيسوع المسيح ، لنتبرر بإيمان يسوع لا بأعمال الناموس . لأنه بأعمال الناموس لا يتبرر جسد ما '),
(13637, 'Galatians', 48, 2, 17, ' فإن كنا ونحن طالبون أن نتبرر في المسيح ، نوجد نحن أنفسنا أيضا خطاة ، أفالمسيح خادم للخطية ؟ حاشا '),
(13638, 'Galatians', 48, 2, 18, ' فإني إن كنت أبني أيضا هذا الذي قد هدمته ، فإني أظهر نفسي متعديا '),
(13639, 'Galatians', 48, 2, 19, ' لأني مت بالناموس للناموس لأحيا لله '),
(13640, 'Galatians', 48, 2, 20, ' مع المسيح صلبت ، فأحيا لا أنا ، بل المسيح يحيا في . فما أحياه الآن في الجسد ، فإنما أحياه في الإيمان ، إيمان ابن الله ، الذي أحبني وأسلم نفسه لأجلي '),
(13641, 'Galatians', 48, 2, 21, ' لست أبطل نعمة الله . لأنه إن كان بالناموس بر ، فالمسيح إذا مات بلا سبب '),
(13642, 'Galatians', 48, 3, 1, ' أيها الغلاطيون الأغبياء ، من رقاكم حتى لا تذعنوا للحق ؟ أنتم الذين أمام عيونكم قد رسم يسوع المسيح بينكم مصلوبا '),
(13643, 'Galatians', 48, 3, 2, ' أريد أن أتعلم منكم هذا فقط : أبأعمال الناموس أخذتم الروح أم بخبر الإيمان '),
(13644, 'Galatians', 48, 3, 3, ' أهكذا أنتم أغبياء أبعدما ابتدأتم بالروح تكملون الآن بالجسد '),
(13645, 'Galatians', 48, 3, 4, ' أهذا المقدار احتملتم عبثا ؟ إن كان عبثا '),
(13646, 'Galatians', 48, 3, 5, ' فالذي يمنحكم الروح ، ويعمل قوات فيكم ، أبأعمال الناموس أم بخبر الإيمان '),
(13647, 'Galatians', 48, 3, 6, ' كما آمن إبراهيم بالله فحسب له برا '),
(13648, 'Galatians', 48, 3, 7, ' اعلموا إذا أن الذين هم من الإيمان أولئك هم بنو إبراهيم '),
(13649, 'Galatians', 48, 3, 8, ' والكتاب إذ سبق فرأى أن الله بالإيمان يبرر الأمم ، سبق فبشر إبراهيم أن فيك تتبارك جميع الأمم '),
(13650, 'Galatians', 48, 3, 9, ' إذا الذين هم من الإيمان يتباركون مع إبراهيم المؤمن '),
(13651, 'Galatians', 48, 3, 10, ' لأن جميع الذين هم من أعمال الناموس هم تحت لعنة ، لأنه مكتوب : ملعون كل من لا يثبت في جميع ما هو مكتوب في كتاب الناموس ليعمل به '),
(13652, 'Galatians', 48, 3, 11, ' ولكن أن ليس أحد يتبرر بالناموس عند الله فظاهر ، لأن البار بالإيمان يحيا '),
(13653, 'Galatians', 48, 3, 12, ' ولكن الناموس ليس من الإيمان ، بل الإنسان الذي يفعلها سيحيا بها '),
(13654, 'Galatians', 48, 3, 13, ' المسيح افتدانا من لعنة الناموس ، إذ صار لعنة لأجلنا ، لأنه مكتوب : ملعون كل من علق على خشبة '),
(13655, 'Galatians', 48, 3, 14, ' لتصير بركة إبراهيم للأمم في المسيح يسوع ، لننال بالإيمان موعد الروح '),
(13656, 'Galatians', 48, 3, 15, ' أيها الإخوة بحسب الإنسان أقول : ليس أحد يبطل عهدا قد تمكن ولو من إنسان ، أو يزيد عليه '),
(13657, 'Galatians', 48, 3, 16, ' وأما المواعيد فقيلت في إبراهيم وفي نسله . لا يقول : وفي الأنسال كأنه عن كثيرين ، بل كأنه عن واحد : وفي نسلك الذي هو المسيح '),
(13658, 'Galatians', 48, 3, 17, ' وإنما أقول هذا : إن الناموس الذي صار بعد أربعمئة وثلاثين سنة ، لا ينسخ عهدا قد سبق فتمكن من الله نحو المسيح حتى يبطل الموعد '),
(13659, 'Galatians', 48, 3, 18, ' لأنه إن كانت الوراثة من الناموس ، فلم تكن أيضا من موعد . ولكن الله وهبها لإبراهيم بموعد '),
(13660, 'Galatians', 48, 3, 19, ' فلماذا الناموس ؟ قد زيد بسبب التعديات ، إلى أن يأتي النسل الذي قد وعد له ، مرتبا بملائكة في يد وسيط '),
(13661, 'Galatians', 48, 3, 20, ' وأما الوسيط فلا يكون لواحد . ولكن الله واحد '),
(13662, 'Galatians', 48, 3, 21, ' فهل الناموس ضد مواعيد الله ؟ حاشا لأنه لو أعطي ناموس قادر أن يحيي ، لكان بالحقيقة البر بالناموس '),
(13663, 'Galatians', 48, 3, 22, ' لكن الكتاب أغلق على الكل تحت الخطية ، ليعطى الموعد من إيمان يسوع المسيح للذين يؤمنون '),
(13664, 'Galatians', 48, 3, 23, ' ولكن قبلما جاء الإيمان كنا محروسين تحت الناموس ، مغلقا علينا إلى الإيمان العتيد أن يعلن '),
(13665, 'Galatians', 48, 3, 24, ' إذا قد كان الناموس مؤدبنا إلى المسيح ، لكي نتبرر بالإيمان '),
(13666, 'Galatians', 48, 3, 25, ' ولكن بعد ما جاء الإيمان ، لسنا بعد تحت مؤدب '),
(13667, 'Galatians', 48, 3, 26, ' لأنكم جميعا أبناء الله بالإيمان بالمسيح يسوع '),
(13668, 'Galatians', 48, 3, 27, ' لأن كلكم الذين اعتمدتم بالمسيح قد لبستم المسيح '),
(13669, 'Galatians', 48, 3, 28, ' ليس يهودي ولا يوناني . ليس عبد ولا حر . ليس ذكر وأنثى ، لأنكم جميعا واحد في المسيح يسوع '),
(13670, 'Galatians', 48, 3, 29, ' فإن كنتم للمسيح ، فأنتم إذا نسل إبراهيم ، وحسب الموعد ورثة '),
(13671, 'Galatians', 48, 4, 1, ' وإنما أقول : ما دام الوارث قاصرا لا يفرق شيئا عن العبد ، مع كونه صاحب الجميع '),
(13672, 'Galatians', 48, 4, 2, ' بل هو تحت أوصياء ووكلاء إلى الوقت المؤجل من أبيه '),
(13673, 'Galatians', 48, 4, 3, ' هكذا نحن أيضا : لما كنا قاصرين ، كنا مستعبدين تحت أركان العالم '),
(13674, 'Galatians', 48, 4, 4, ' ولكن لما جاء ملء الزمان ، أرسل الله ابنه مولودا من امرأة ، مولودا تحت الناموس '),
(13675, 'Galatians', 48, 4, 5, ' ليفتدي الذين تحت الناموس ، لننال التبني '),
(13676, 'Galatians', 48, 4, 6, ' ثم بما أنكم أبناء ، أرسل الله روح ابنه إلى قلوبكم صارخا : يا أبا الآب '),
(13677, 'Galatians', 48, 4, 7, ' إذا لست بعد عبدا بل ابنا ، وإن كنت ابنا فوارث لله بالمسيح '),
(13678, 'Galatians', 48, 4, 8, ' لكن حينئذ إذ كنتم لا تعرفون الله ، استعبدتم للذين ليسوا بالطبيعة آلهة '),
(13679, 'Galatians', 48, 4, 9, ' وأما الآن إذ عرفتم الله ، بل بالحري عرفتم من الله ، فكيف ترجعون أيضا إلى الأركان الضعيفة الفقيرة التي تريدون أن تستعبدوا لها من جديد '),
(13680, 'Galatians', 48, 4, 10, ' أتحفظون أياما وشهورا وأوقاتا وسنين '),
(13681, 'Galatians', 48, 4, 11, ' أخاف عليكم أن أكون قد تعبت فيكم عبثا '),
(13682, 'Galatians', 48, 4, 12, ' أتضرع إليكم أيها الإخوة ، كونوا كما أنا لأني أنا أيضا كما أنتم . لم تظلموني شيئا '),
(13683, 'Galatians', 48, 4, 13, ' ولكنكم تعلمون أني بضعف الجسد بشرتكم في الأول '),
(13684, 'Galatians', 48, 4, 14, ' وتجربتي التي في جسدي لم تزدروا بها ولا كرهتموها ، بل كملاك من الله قبلتموني ، كالمسيح يسوع '),
(13685, 'Galatians', 48, 4, 15, ' فماذا كان إذا تطويبكم ؟ لأني أشهد لكم أنه لو أمكن لقلعتم عيونكم وأعطيتموني '),
(13686, 'Galatians', 48, 4, 16, ' أفقد صرت إذا عدوا لكم لأني أصدق لكم '),
(13687, 'Galatians', 48, 4, 17, ' يغارون لكم ليس حسنا ، بل يريدون أن يصدوكم لكي تغاروا لهم '),
(13688, 'Galatians', 48, 4, 18, ' حسنة هي الغيرة في الحسنى كل حين ، وليس حين حضوري عندكم فقط '),
(13689, 'Galatians', 48, 4, 19, ' يا أولادي الذين أتمخض بكم أيضا إلى أن يتصور المسيح فيكم '),
(13690, 'Galatians', 48, 4, 20, ' ولكني كنت أريد أن أكون حاضرا عندكم الآن وأغير صوتي ، لأني متحير فيكم '),
(13691, 'Galatians', 48, 4, 21, ' قولوا لي ، أنتم الذين تريدون أن تكونوا تحت الناموس : ألستم تسمعون الناموس '),
(13692, 'Galatians', 48, 4, 22, ' فإنه مكتوب أنه كان لإبراهيم ابنان ، واحد من الجارية والآخر من الحرة '),
(13693, 'Galatians', 48, 4, 23, ' لكن الذي من الجارية ولد حسب الجسد ، وأما الذي من الحرة فبالموعد '),
(13694, 'Galatians', 48, 4, 24, ' وكل ذلك رمز ، لأن هاتين هما العهدان ، أحدهما من جبل سيناء ، الوالد للعبودية ، الذي هو هاجر '),
(13695, 'Galatians', 48, 4, 25, ' لأن هاجر جبل سيناء في العربية . ولكنه يقابل أورشليم الحاضرة ، فإنها مستعبدة مع بنيها '),
(13696, 'Galatians', 48, 4, 26, ' وأما أورشليم العليا ، التي هي أمنا جميعا ، فهي حرة '),
(13697, 'Galatians', 48, 4, 27, ' لأنه مكتوب : افرحي أيتها العاقر التي لم تلد . اهتفي واصرخي أيتها التي لم تتمخض ، فإن أولاد الموحشة أكثر من التي لها زوج '),
(13698, 'Galatians', 48, 4, 28, ' وأما نحن أيها الإخوة فنظير إسحاق ، أولاد الموعد '),
(13699, 'Galatians', 48, 4, 29, ' ولكن كما كان حينئذ الذي ولد حسب الجسد يضطهد الذي حسب الروح ، هكذا الآن أيضا '),
(13700, 'Galatians', 48, 4, 30, ' لكن ماذا يقول الكتاب ؟ اطرد الجارية وابنها ، لأنه لا يرث ابن الجارية مع ابن الحرة '),
(13701, 'Galatians', 48, 4, 31, ' إذا أيها الإخوة لسنا أولاد جارية بل أولاد الحرة '),
(13702, 'Galatians', 48, 5, 1, ' فاثبتوا إذا في الحرية التي قد حررنا المسيح بها ، ولا ترتبكوا أيضا بنير عبودية '),
(13703, 'Galatians', 48, 5, 2, ' ها أنا بولس أقول لكم : إنه إن اختتنتم لا ينفعكم المسيح شيئا '),
(13704, 'Galatians', 48, 5, 3, ' لكن أشهد أيضا لكل إنسان مختتن أنه ملتزم أن يعمل بكل الناموس '),
(13705, 'Galatians', 48, 5, 4, ' قد تبطلتم عن المسيح أيها الذين تتبررون بالناموس . سقطتم من النعمة '),
(13706, 'Galatians', 48, 5, 5, ' فإننا بالروح من الإيمان نتوقع رجاء بر '),
(13707, 'Galatians', 48, 5, 6, ' لأنه في المسيح يسوع لا الختان ينفع شيئا ولا الغرلة ، بل الإيمان العامل بالمحبة '),
(13708, 'Galatians', 48, 5, 7, ' كنتم تسعون حسنا . فمن صدكم حتى لا تطاوعوا للحق '),
(13709, 'Galatians', 48, 5, 8, ' هذه المطاوعة ليست من الذي دعاكم '),
(13710, 'Galatians', 48, 5, 9, ' خميرة صغيرة تخمر العجين كله '),
(13711, 'Galatians', 48, 5, 10, ' ولكنني أثق بكم في الرب أنكم لا تفتكرون شيئا آخر . ولكن الذي يزعجكم سيحمل الدينونة أي من كان '),
(13712, 'Galatians', 48, 5, 11, ' وأما أنا أيها الإخوة فإن كنت بعد أكرز بالختان ، فلماذا أضطهد بعد ؟ إذا عثرة الصليب قد بطلت '),
(13713, 'Galatians', 48, 5, 12, ' يا ليت الذين يقلقونكم يقطعون أيضا '),
(13714, 'Galatians', 48, 5, 13, ' فإنكم إنما دعيتم للحرية أيها الإخوة . غير أنه لا تصيروا الحرية فرصة للجسد ، بل بالمحبة اخدموا بعضكم بعضا '),
(13715, 'Galatians', 48, 5, 14, ' لأن كل الناموس في كلمة واحدة يكمل : تحب قريبك كنفسك '),
(13716, 'Galatians', 48, 5, 15, ' فإذا كنتم تنهشون وتأكلون بعضكم بعضا ، فانظروا لئلا تفنوا بعضكم بعضا '),
(13717, 'Galatians', 48, 5, 16, ' وإنما أقول : اسلكوا بالروح فلا تكملوا شهوة الجسد '),
(13718, 'Galatians', 48, 5, 17, ' لأن الجسد يشتهي ضد الروح والروح ضد الجسد ، وهذان يقاوم أحدهما الآخر ، حتى تفعلون ما لا تريدون '),
(13719, 'Galatians', 48, 5, 18, ' ولكن إذا انقدتم بالروح فلستم تحت الناموس '),
(13720, 'Galatians', 48, 5, 19, ' وأعمال الجسد ظاهرة ، التي هي : زنى ، عهارة ، نجاسة ، دعارة '),
(13721, 'Galatians', 48, 5, 20, ' عبادة الأوثان ، سحر ، عداوة ، خصام ، غيرة ، سخط ، تحزب ، شقاق ، بدعة '),
(13722, 'Galatians', 48, 5, 21, ' حسد ، قتل ، سكر ، بطر . وأمثال هذه التي أسبق فأقول لكم عنها كما سبقت فقلت أيضا : إن الذين يفعلون مثل هذه لا يرثون ملكوت الله '),
(13723, 'Galatians', 48, 5, 22, ' وأما ثمر الروح فهو : محبة ، فرح ، سلام ، طول أناة ، لطف ، صلاح ، إيمان '),
(13724, 'Galatians', 48, 5, 23, ' وداعة ، تعفف . ضد أمثال هذه ليس ناموس '),
(13725, 'Galatians', 48, 5, 24, ' ولكن الذين هم للمسيح قد صلبوا الجسد مع الأهواء والشهوات '),
(13726, 'Galatians', 48, 5, 25, ' إن كنا نعيش بالروح ، فلنسلك أيضا بحسب الروح '),
(13727, 'Galatians', 48, 5, 26, ' لا نكن معجبين نغاضب بعضنا بعضا ، ونحسد بعضنا بعضا '),
(13728, 'Galatians', 48, 6, 1, ' أيها الإخوة ، إن انسبق إنسان فأخذ في زلة ما ، فأصلحوا أنتم الروحانيين مثل هذا بروح الوداعة ، ناظرا إلى نفسك لئلا تجرب أنت أيضا '),
(13729, 'Galatians', 48, 6, 2, ' احملوا بعضكم أثقال بعض ، وهكذا تمموا ناموس المسيح '),
(13730, 'Galatians', 48, 6, 3, ' لأنه إن ظن أحد أنه شيء وهو ليس شيئا ، فإنه يغش نفسه '),
(13731, 'Galatians', 48, 6, 4, ' ولكن ليمتحن كل واحد عمله ، وحينئذ يكون له الفخر من جهة نفسه فقط ، لا من جهة غيره '),
(13732, 'Galatians', 48, 6, 5, ' لأن كل واحد سيحمل حمل نفسه '),
(13733, 'Galatians', 48, 6, 6, ' ولكن ليشارك الذي يتعلم الكلمة المعلم في جميع الخيرات '),
(13734, 'Galatians', 48, 6, 7, ' لا تضلوا الله لا يشمخ عليه . فإن الذي يزرعه الإنسان إياه يحصد أيضا '),
(13735, 'Galatians', 48, 6, 8, ' لأن من يزرع لجسده فمن الجسد يحصد فسادا ، ومن يزرع للروح فمن الروح يحصد حياة أبدية '),
(13736, 'Galatians', 48, 6, 9, ' فلا نفشل في عمل الخير لأننا سنحصد في وقته إن كنا لا نكل '),
(13737, 'Galatians', 48, 6, 10, ' فإذا حسبما لنا فرصة فلنعمل الخير للجميع ، ولاسيما لأهل الإيمان '),
(13738, 'Galatians', 48, 6, 11, ' انظروا ، ما أكبر الأحرف التي كتبتها إليكم بيدي '),
(13739, 'Galatians', 48, 6, 12, ' جميع الذين يريدون أن يعملوا منظرا حسنا في الجسد ، هؤلاء يلزمونكم أن تختتنوا ، لئلا يضطهدوا لأجل صليب المسيح فقط '),
(13740, 'Galatians', 48, 6, 13, ' لأن الذين يختتنون هم لا يحفظون الناموس ، بل يريدون أن تختتنوا أنتم لكي يفتخروا في جسدكم '),
(13741, 'Galatians', 48, 6, 14, ' وأما من جهتي ، فحاشا لي أن أفتخر إلا بصليب ربنا يسوع المسيح ، الذي به قد صلب العالم لي وأنا للعالم '),
(13742, 'Galatians', 48, 6, 15, ' لأنه في المسيح يسوع ليس الختان ينفع شيئا ولا الغرلة ، بل الخليقة الجديدة '),
(13743, 'Galatians', 48, 6, 16, ' فكل الذين يسلكون بحسب هذا القانون عليهم سلام ورحمة ، وعلى إسرائيل الله '),
(13744, 'Galatians', 48, 6, 17, ' في ما بعد لا يجلب أحد علي أتعابا ، لأني حامل في جسدي سمات الرب يسوع '),
(13745, 'Galatians', 48, 6, 18, ' نعمة ربنا يسوع المسيح مع روحكم أيها الإخوة . آمين '),
(13746, 'Genesis', 1, 1, 1, ' في البدء خلق الله السماوات والأرض '),
(13747, 'Genesis', 1, 1, 2, ' وكانت الأرض خربة وخالية ، وعلى وجه الغمر ظلمة ، وروح الله يرف على وجه المياه '),
(13748, 'Genesis', 1, 1, 3, ' وقال الله : ليكن نور ، فكان نور '),
(13749, 'Genesis', 1, 1, 4, ' ورأى الله النور أنه حسن . وفصل الله بين النور والظلمة '),
(13750, 'Genesis', 1, 1, 5, ' ودعا الله النور نهارا ، والظلمة دعاها ليلا . وكان مساء وكان صباح يوما واحدا '),
(13751, 'Genesis', 1, 1, 6, ' وقال الله : ليكن جلد في وسط المياه . وليكن فاصلا بين مياه ومياه ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(13752, 'Genesis', 1, 1, 7, ' فعمل الله الجلد ، وفصل بين المياه التي تحت الجلد والمياه التي فوق الجلد . وكان كذلك '),
(13753, 'Genesis', 1, 1, 8, ' ودعا الله الجلد سماء . وكان مساء وكان صباح يوما ثانيا '),
(13754, 'Genesis', 1, 1, 9, ' وقال الله : لتجتمع المياه تحت السماء إلى مكان واحد ، ولتظهر اليابسة . وكان كذلك '),
(13755, 'Genesis', 1, 1, 10, ' ودعا الله اليابسة أرضا ، ومجتمع المياه دعاه بحارا . ورأى الله ذلك أنه حسن '),
(13756, 'Genesis', 1, 1, 11, ' وقال الله : لتنبت الأرض عشبا وبقلا يبزر بزرا ، وشجرا ذا ثمر يعمل ثمرا كجنسه ، بزره فيه على الأرض . وكان كذلك '),
(13757, 'Genesis', 1, 1, 12, ' فأخرجت الأرض عشبا وبقلا يبزر بزرا كجنسه ، وشجرا يعمل ثمرا بزره فيه كجنسه . ورأى الله ذلك أنه حسن '),
(13758, 'Genesis', 1, 1, 13, ' وكان مساء وكان صباح يوما ثالثا '),
(13759, 'Genesis', 1, 1, 14, ' وقال الله : لتكن أنوار في جلد السماء لتفصل بين النهار والليل ، وتكون لآيات وأوقات وأيام وسنين '),
(13760, 'Genesis', 1, 1, 15, ' وتكون أنوارا في جلد السماء لتنير على الأرض . وكان كذلك '),
(13761, 'Genesis', 1, 1, 16, ' فعمل الله النورين العظيمين : النور الأكبر لحكم النهار ، والنور الأصغر لحكم الليل ، والنجوم '),
(13762, 'Genesis', 1, 1, 17, ' وجعلها الله في جلد السماء لتنير على الأرض '),
(13763, 'Genesis', 1, 1, 18, ' ولتحكم على النهار والليل ، ولتفصل بين النور والظلمة . ورأى الله ذلك أنه حسن '),
(13764, 'Genesis', 1, 1, 19, ' وكان مساء وكان صباح يوما رابعا '),
(13765, 'Genesis', 1, 1, 20, ' وقال الله : لتفض المياه زحافات ذات نفس حية ، وليطر طير فوق الأرض على وجه جلد السماء '),
(13766, 'Genesis', 1, 1, 21, ' فخلق الله التنانين العظام ، وكل ذوات الأنفس الحية الدبابة التى فاضت بها المياه كأجناسها ، وكل طائر ذي جناح كجنسه . ورأى الله ذلك أنه حسن '),
(13767, 'Genesis', 1, 1, 22, ' وباركها الله قائلا : أثمري واكثري واملإي المياه في البحار . وليكثر الطير على الأرض '),
(13768, 'Genesis', 1, 1, 23, ' وكان مساء وكان صباح يوما خامسا '),
(13769, 'Genesis', 1, 1, 24, ' وقال الله : لتخرج الأرض ذوات أنفس حية كجنسها : بهائم ، ودبابات ، ووحوش أرض كأجناسها . وكان كذلك '),
(13770, 'Genesis', 1, 1, 25, ' فعمل الله وحوش الأرض كأجناسها ، والبهائم كأجناسها ، وجميع دبابات الأرض كأجناسها . ورأى الله ذلك أنه حسن '),
(13771, 'Genesis', 1, 1, 26, ' وقال الله : نعمل الإنسان على صورتنا كشبهنا ، فيتسلطون على سمك البحر وعلى طير السماء وعلى البهائم ، وعلى كل الأرض ، وعلى جميع الدبابات التي تدب على الأرض '),
(13772, 'Genesis', 1, 1, 27, ' فخلق الله الإنسان على صورته . على صورة الله خلقه . ذكرا وأنثى خلقهم '),
(13773, 'Genesis', 1, 1, 28, ' وباركهم الله وقال لهم : أثمروا واكثروا واملأوا الأرض ، وأخضعوها ، وتسلطوا على سمك البحر وعلى طير السماء وعلى كل حيوان يدب على الأرض '),
(13774, 'Genesis', 1, 1, 29, ' وقال الله : إني قد أعطيتكم كل بقل يبزر بزرا على وجه كل الأرض ، وكل شجر فيه ثمر شجر يبزر بزرا لكم يكون طعاما '),
(13775, 'Genesis', 1, 1, 30, ' ولكل حيوان الأرض وكل طير السماء وكل دبابة على الأرض فيها نفس حية ، أعطيت كل عشب أخضر طعاما . وكان كذلك '),
(13776, 'Genesis', 1, 1, 31, ' ورأى الله كل ما عمله فإذا هو حسن جدا . وكان مساء وكان صباح يوما سادسا '),
(13777, 'Genesis', 1, 2, 1, ' فأكملت السماوات والأرض وكل جندها '),
(13778, 'Genesis', 1, 2, 2, ' وفرغ الله في اليوم السابع من عمله الذي عمل . فاستراح في اليوم السابع من جميع عمله الذي عمل '),
(13779, 'Genesis', 1, 2, 3, ' وبارك الله اليوم السابع وقدسه ، لأنه فيه استراح من جميع عمله الذي عمل الله خالقا '),
(13780, 'Genesis', 1, 2, 4, ' هذه مبادئ السماوات والأرض حين خلقت ، يوم عمل الرب الإله الأرض والسماوات '),
(13781, 'Genesis', 1, 2, 5, ' كل شجر البرية لم يكن بعد في الأرض ، وكل عشب البرية لم ينبت بعد ، لأن الرب الإله لم يكن قد أمطر على الأرض ، ولا كان إنسان ليعمل الأرض '),
(13782, 'Genesis', 1, 2, 6, ' ثم كان ضباب يطلع من الأرض ويسقي كل وجه الأرض '),
(13783, 'Genesis', 1, 2, 7, ' وجبل الرب الإله آدم ترابا من الأرض ، ونفخ في أنفه نسمة حياة . فصار آدم نفسا حية '),
(13784, 'Genesis', 1, 2, 8, ' وغرس الرب الإله جنة في عدن شرقا ، ووضع هناك آدم الذي جبله '),
(13785, 'Genesis', 1, 2, 9, ' وأنبت الرب الإله من الأرض كل شجرة شهية للنظر وجيدة للأكل ، وشجرة الحياة في وسط الجنة ، وشجرة معرفة الخير والشر '),
(13786, 'Genesis', 1, 2, 10, ' وكان نهر يخرج من عدن ليسقي الجنة ، ومن هناك ينقسم فيصير أربعة رؤوس '),
(13787, 'Genesis', 1, 2, 11, ' اسم الواحد فيشون ، وهو المحيط بجميع أرض الحويلة حيث الذهب '),
(13788, 'Genesis', 1, 2, 12, ' وذهب تلك الأرض جيد . هناك المقل وحجر الجزع '),
(13789, 'Genesis', 1, 2, 13, ' واسم النهر الثانى جيحون ، وهو المحيط بجميع أرض كوش '),
(13790, 'Genesis', 1, 2, 14, ' واسم النهر الثالث حداقل ، وهو الجاري شرقي أشور . والنهر الرابع الفرات '),
(13791, 'Genesis', 1, 2, 15, ' وأخذ الرب الإله آدم ووضعه في جنة عدن ليعملها ويحفظها '),
(13792, 'Genesis', 1, 2, 16, ' وأوصى الرب الإله آدم قائلا : من جميع شجر الجنة تأكل أكلا '),
(13793, 'Genesis', 1, 2, 17, ' وأما شجرة معرفة الخير والشر فلا تأكل منها ، لأنك يوم تأكل منها موتا تموت '),
(13794, 'Genesis', 1, 2, 18, ' وقال الرب الإله : ليس جيدا أن يكون آدم وحده ، فأصنع له معينا نظيره '),
(13795, 'Genesis', 1, 2, 19, ' وجبل الرب الإله من الأرض كل حيوانات البرية وكل طيور السماء ، فأحضرها إلى آدم ليرى ماذا يدعوها ، وكل ما دعا به آدم ذات نفس حية فهو اسمها '),
(13796, 'Genesis', 1, 2, 20, ' فدعا آدم بأسماء جميع البهائم وطيور السماء وجميع حيوانات البرية . وأما لنفسه فلم يجد معينا نظيره '),
(13797, 'Genesis', 1, 2, 21, ' فأوقع الرب الإله سباتا على آدم فنام ، فأخذ واحدة من أضلاعه وملأ مكانها لحما '),
(13798, 'Genesis', 1, 2, 22, ' وبنى الرب الإله الضلع التي أخذها من آدم امرأة وأحضرها إلى آدم '),
(13799, 'Genesis', 1, 2, 23, ' فقال آدم : هذه الآن عظم من عظامي ولحم من لحمي . هذه تدعى امرأة لأنها من امرء أخذت '),
(13800, 'Genesis', 1, 2, 24, ' لذلك يترك الرجل أباه وأمه ويلتصق بامرأته ويكونان جسدا واحدا '),
(13801, 'Genesis', 1, 2, 25, ' وكانا كلاهما عريانين ، آدم وامرأته ، وهما لا يخجلان '),
(13802, 'Genesis', 1, 3, 1, ' وكانت الحية أحيل جميع حيوانات البرية التي عملها الرب الإله ، فقالت للمرأة : أحقا قال الله لا تأكلا من كل شجر الجنة '),
(13803, 'Genesis', 1, 3, 2, ' فقالت المرأة للحية : من ثمر شجر الجنة نأكل '),
(13804, 'Genesis', 1, 3, 3, ' وأما ثمر الشجرة التي في وسط الجنة فقال الله : لا تأكلا منه ولا تمساه لئلا تموتا '),
(13805, 'Genesis', 1, 3, 4, ' فقالت الحية للمرأة : لن تموتا '),
(13806, 'Genesis', 1, 3, 5, ' بل الله عالم أنه يوم تأكلان منه تنفتح أعينكما وتكونان كالله عارفين الخير والشر '),
(13807, 'Genesis', 1, 3, 6, ' فرأت المرأة أن الشجرة جيدة للأكل ، وأنها بهجة للعيون ، وأن الشجرة شهية للنظر . فأخذت من ثمرها وأكلت ، وأعطت رجلها أيضا معها فأكل '),
(13808, 'Genesis', 1, 3, 7, ' فانفتحت أعينهما وعلما أنهما عريانان . فخاطا أوراق تين وصنعا لأنفسهما مآزر '),
(13809, 'Genesis', 1, 3, 8, ' وسمعا صوت الرب الإله ماشيا في الجنة عند هبوب ريح النهار ، فاختبأ آدم وامرأته من وجه الرب الإله في وسط شجر الجنة '),
(13810, 'Genesis', 1, 3, 9, ' فنادى الرب الإله آدم وقال له : أين أنت '),
(13811, 'Genesis', 1, 3, 10, ' فقال : سمعت صوتك في الجنة فخشيت ، لأني عريان فاختبأت '),
(13812, 'Genesis', 1, 3, 11, ' فقال : من أعلمك أنك عريان ؟ هل أكلت من الشجرة التي أوصيتك أن لا تأكل منها '),
(13813, 'Genesis', 1, 3, 12, ' فقال آدم : المرأة التي جعلتها معي هي أعطتني من الشجرة فأكلت '),
(13814, 'Genesis', 1, 3, 13, ' فقال الرب الإله للمرأة : ما هذا الذي فعلت ؟ فقالت المرأة : الحية غرتني فأكلت '),
(13815, 'Genesis', 1, 3, 14, ' فقال الرب الإله للحية : لأنك فعلت هذا ، ملعونة أنت من جميع البهائم ومن جميع وحوش البرية . على بطنك تسعين وترابا تأكلين كل أيام حياتك '),
(13816, 'Genesis', 1, 3, 15, ' وأضع عداوة بينك وبين المرأة ، وبين نسلك ونسلها . هو يسحق رأسك ، وأنت تسحقين عقبه '),
(13817, 'Genesis', 1, 3, 16, ' وقال للمرأة : تكثيرا أكثر أتعاب حبلك ، بالوجع تلدين أولادا . وإلى رجلك يكون اشتياقك وهو يسود عليك '),
(13818, 'Genesis', 1, 3, 17, ' وقال لآدم : لأنك سمعت لقول امرأتك وأكلت من الشجرة التي أوصيتك قائلا : لا تأكل منها ، ملعونة الأرض بسببك . بالتعب تأكل منها كل أيام حياتك '),
(13819, 'Genesis', 1, 3, 18, ' وشوكا وحسكا تنبت لك ، وتأكل عشب الحقل '),
(13820, 'Genesis', 1, 3, 19, ' بعرق وجهك تأكل خبزا حتى تعود إلى الأرض التي أخذت منها . لأنك تراب ، وإلى تراب تعود '),
(13821, 'Genesis', 1, 3, 20, ' ودعا آدم اسم امرأته حواء لأنها أم كل حي '),
(13822, 'Genesis', 1, 3, 21, ' وصنع الرب الإله لآدم وامرأته أقمصة من جلد وألبسهما '),
(13823, 'Genesis', 1, 3, 22, ' وقال الرب الإله : هوذا الإنسان قد صار كواحد منا عارفا الخير والشر . والآن لعله يمد يده ويأخذ من شجرة الحياة أيضا ويأكل ويحيا إلى الأبد '),
(13824, 'Genesis', 1, 3, 23, ' فأخرجه الرب الإله من جنة عدن ليعمل الأرض التي أخذ منها '),
(13825, 'Genesis', 1, 3, 24, ' فطرد الإنسان ، وأقام شرقي جنة عدن الكروبيم ، ولهيب سيف متقلب لحراسة طريق شجرة الحياة '),
(13826, 'Genesis', 1, 4, 1, ' وعرف آدم حواء امرأته فحبلت وولدت قايين . وقالت : اقتنيت رجلا من عند الرب '),
(13827, 'Genesis', 1, 4, 2, ' ثم عادت فولدت أخاه هابيل . وكان هابيل راعيا للغنم ، وكان قايين عاملا في الأرض '),
(13828, 'Genesis', 1, 4, 3, ' وحدث من بعد أيام أن قايين قدم من أثمار الأرض قربانا للرب '),
(13829, 'Genesis', 1, 4, 4, ' وقدم هابيل أيضا من أبكار غنمه ومن سمانها . فنظر الرب إلى هابيل وقربانه '),
(13830, 'Genesis', 1, 4, 5, ' ولكن إلى قايين وقربانه لم ينظر . فاغتاظ قايين جدا وسقط وجهه '),
(13831, 'Genesis', 1, 4, 6, ' فقال الرب لقايين : لماذا اغتظت ؟ ولماذا سقط وجهك '),
(13832, 'Genesis', 1, 4, 7, ' إن أحسنت أفلا رفع ؟ وإن لم تحسن فعند الباب خطية رابضة ، وإليك اشتياقها وأنت تسود عليها '),
(13833, 'Genesis', 1, 4, 8, ' وكلم قايين هابيل أخاه . وحدث إذ كانا في الحقل أن قايين قام على هابيل أخيه وقتله '),
(13834, 'Genesis', 1, 4, 9, ' فقال الرب لقايين : أين هابيل أخوك ؟ فقال : لا أعلم أحارس أنا لأخي '),
(13835, 'Genesis', 1, 4, 10, ' فقال : ماذا فعلت ؟ صوت دم أخيك صارخ إلي من الأرض '),
(13836, 'Genesis', 1, 4, 11, ' فالآن ملعون أنت من الأرض التي فتحت فاها لتقبل دم أخيك من يدك '),
(13837, 'Genesis', 1, 4, 12, ' متى عملت الأرض لا تعود تعطيك قوتها . تائها وهاربا تكون في الأرض '),
(13838, 'Genesis', 1, 4, 13, ' فقال قايين للرب : ذنبي أعظم من أن يحتمل '),
(13839, 'Genesis', 1, 4, 14, ' إنك قد طردتني اليوم عن وجه الأرض ، ومن وجهك أختفي وأكون تائها وهاربا في الأرض ، فيكون كل من وجدني يقتلني '),
(13840, 'Genesis', 1, 4, 15, ' فقال له الرب : لذلك كل من قتل قايين فسبعة أضعاف ينتقم منه . وجعل الرب لقايين علامة لكي لا يقتله كل من وجده '),
(13841, 'Genesis', 1, 4, 16, ' فخرج قايين من لدن الرب ، وسكن في أرض نود شرقي عدن '),
(13842, 'Genesis', 1, 4, 17, ' وعرف قايين امرأته فحبلت وولدت حنوك . وكان يبني مدينة ، فدعا اسم المدينة كاسم ابنه حنوك '),
(13843, 'Genesis', 1, 4, 18, ' وولد لحنوك عيراد . وعيراد ولد محويائيل . ومحويائيل ولد متوشائيل . ومتوشائيل ولد لامك '),
(13844, 'Genesis', 1, 4, 19, ' واتخذ لامك لنفسه امرأتين : اسم الواحدة عادة ، واسم الأخرى صلة '),
(13845, 'Genesis', 1, 4, 20, ' فولدت عادة يابال الذي كان أبا لساكني الخيام ورعاة المواشي '),
(13846, 'Genesis', 1, 4, 21, ' واسم أخيه يوبال الذي كان أبا لكل ضارب بالعود والمزمار '),
(13847, 'Genesis', 1, 4, 22, ' وصلة أيضا ولدت توبال قايين الضارب كل آلة من نحاس وحديد . وأخت توبال قايين نعمة '),
(13848, 'Genesis', 1, 4, 23, ' وقال لامك لامرأتيه عادة وصلة : اسمعا قولي يا امرأتي لامك ، وأصغيا لكلامي . فإني قتلت رجلا لجرحي ، وفتى لشدخي '),
(13849, 'Genesis', 1, 4, 24, ' إنه ينتقم لقايين سبعة أضعاف ، وأما للامك فسبعة وسبعين '),
(13850, 'Genesis', 1, 4, 25, ' وعرف آدم امرأته أيضا ، فولدت ابنا ودعت اسمه شيثا ، قائلة : لأن الله قد وضع لي نسلا آخر عوضا عن هابيل . لأن قايين كان قد قتله '),
(13851, 'Genesis', 1, 4, 26, ' ولشيث أيضا ولد ابن فدعا اسمه أنوش . حينئذ ابتدئ أن يدعى باسم الرب '),
(13852, 'Genesis', 1, 5, 1, ' هذا كتاب مواليد آدم ، يوم خلق الله الإنسان . على شبه الله عمله '),
(13853, 'Genesis', 1, 5, 2, ' ذكرا وأنثى خلقه ، وباركه ودعا اسمه آدم يوم خلق '),
(13854, 'Genesis', 1, 5, 3, ' وعاش آدم مئة وثلاثين سنة ، وولد ولدا على شبهه كصورته ودعا اسمه شيثا '),
(13855, 'Genesis', 1, 5, 4, ' وكانت أيام آدم بعد ما ولد شيثا ثماني مئة سنة ، وولد بنين وبنات '),
(13856, 'Genesis', 1, 5, 5, ' فكانت كل أيام آدم التي عاشها تسع مئة وثلاثين سنة ، ومات '),
(13857, 'Genesis', 1, 5, 6, ' وعاش شيث مئة وخمس سنين ، وولد أنوش '),
(13858, 'Genesis', 1, 5, 7, ' وعاش شيث بعد ما ولد أنوش ثماني مئة وسبع سنين ، وولد بنين وبنات '),
(13859, 'Genesis', 1, 5, 8, ' فكانت كل أيام شيث تسع مئة واثنتي عشرة سنة ، ومات '),
(13860, 'Genesis', 1, 5, 9, ' وعاش أنوش تسعين سنة ، وولد قينان '),
(13861, 'Genesis', 1, 5, 10, ' وعاش أنوش بعد ما ولد قينان ثماني مئة وخمس عشرة سنة ، وولد بنين وبنات '),
(13862, 'Genesis', 1, 5, 11, ' فكانت كل أيام أنوش تسع مئة وخمس سنين ، ومات '),
(13863, 'Genesis', 1, 5, 12, ' وعاش قينان سبعين سنة ، وولد مهللئيل '),
(13864, 'Genesis', 1, 5, 13, ' وعاش قينان بعد ما ولد مهللئيل ثماني مئة وأربعين سنة ، وولد بنين وبنات '),
(13865, 'Genesis', 1, 5, 14, ' فكانت كل أيام قينان تسع مئة وعشر سنين ، ومات '),
(13866, 'Genesis', 1, 5, 15, ' وعاش مهللئيل خمسا وستين سنة ، وولد يارد '),
(13867, 'Genesis', 1, 5, 16, ' وعاش مهللئيل بعد ما ولد يارد ثماني مئة وثلاثين سنة ، وولد بنين وبنات '),
(13868, 'Genesis', 1, 5, 17, ' فكانت كل أيام مهللئيل ثماني مئة وخمسا وتسعين سنة ، ومات '),
(13869, 'Genesis', 1, 5, 18, ' وعاش يارد مئة واثنتين وستين سنة ، وولد أخنوخ '),
(13870, 'Genesis', 1, 5, 19, ' وعاش يارد بعد ما ولد أخنوخ ثماني مئة سنة ، وولد بنين وبنات '),
(13871, 'Genesis', 1, 5, 20, ' فكانت كل أيام يارد تسع مئة واثنتين وستين سنة ، ومات '),
(13872, 'Genesis', 1, 5, 21, ' وعاش أخنوخ خمسا وستين سنة ، وولد متوشالح '),
(13873, 'Genesis', 1, 5, 22, ' وسار أخنوخ مع الله بعد ما ولد متوشالح ثلاث مئة سنة ، وولد بنين وبنات '),
(13874, 'Genesis', 1, 5, 23, ' فكانت كل أيام أخنوخ ثلاث مئة وخمسا وستين سنة '),
(13875, 'Genesis', 1, 5, 24, ' وسار أخنوخ مع الله ، ولم يوجد لأن الله أخذه '),
(13876, 'Genesis', 1, 5, 25, ' وعاش متوشالح مئة وسبعا وثمانين سنة ، وولد لامك '),
(13877, 'Genesis', 1, 5, 26, ' وعاش متوشالح بعد ما ولد لامك سبع مئة واثنتين وثمانين سنة ، وولد بنين وبنات '),
(13878, 'Genesis', 1, 5, 27, ' فكانت كل أيام متوشالح تسع مئة وتسعا وستين سنة ، ومات '),
(13879, 'Genesis', 1, 5, 28, ' وعاش لامك مئة واثنتين وثمانين سنة ، وولد ابنا '),
(13880, 'Genesis', 1, 5, 29, ' ودعا اسمه نوحا ، قائلا : هذا يعزينا عن عملنا وتعب أيدينا من قبل الأرض التي لعنها الرب '),
(13881, 'Genesis', 1, 5, 30, ' وعاش لامك بعد ما ولد نوحا خمس مئة وخمسا وتسعين سنة ، وولد بنين وبنات '),
(13882, 'Genesis', 1, 5, 31, ' فكانت كل أيام لامك سبع مئة وسبعا وسبعين سنة ، ومات '),
(13883, 'Genesis', 1, 5, 32, ' وكان نوح ابن خمس مئة سنة . وولد نوح : ساما ، وحاما،ويافث '),
(13884, 'Genesis', 1, 6, 1, ' وحدث لما ابتدأ الناس يكثرون على الأرض ، وولد لهم بنات '),
(13885, 'Genesis', 1, 6, 2, ' أن أبناء الله رأوا بنات الناس أنهن حسنات . فاتخذوا لأنفسهم نساء من كل ما اختاروا '),
(13886, 'Genesis', 1, 6, 3, ' فقال الرب : لا يدين روحي في الإنسان إلى الأبد ، لزيغانه ، هو بشر . وتكون أيامه مئة وعشرين سنة '),
(13887, 'Genesis', 1, 6, 4, ' كان في الأرض طغاة في تلك الأيام . وبعد ذلك أيضا إذ دخل بنو الله على بنات الناس وولدن لهم أولادا ، هؤلاء هم الجبابرة الذين منذ الدهر ذوو اسم '),
(13888, 'Genesis', 1, 6, 5, ' ورأى الرب أن شر الإنسان قد كثر في الأرض ، وأن كل تصور أفكار قلبه إنما هو شرير كل يوم '),
(13889, 'Genesis', 1, 6, 6, ' فحزن الرب أنه عمل الإنسان في الأرض ، وتأسف في قلبه '),
(13890, 'Genesis', 1, 6, 7, ' فقال الرب : أمحو عن وجه الأرض الإنسان الذي خلقته ، الإنسان مع بهائم ودبابات وطيور السماء ، لأني حزنت أني عملتهم '),
(13891, 'Genesis', 1, 6, 8, ' وأما نوح فوجد نعمة في عيني الرب '),
(13892, 'Genesis', 1, 6, 9, ' هذه مواليد نوح : كان نوح رجلا بارا كاملا في أجياله . وسار نوح مع الله '),
(13893, 'Genesis', 1, 6, 10, ' وولد نوح ثلاثة بنين : ساما ، وحاما ، ويافث '),
(13894, 'Genesis', 1, 6, 11, ' وفسدت الأرض أمام الله ، وامتلأت الأرض ظلما '),
(13895, 'Genesis', 1, 6, 12, ' ورأى الله الأرض فإذا هي قد فسدت ، إذ كان كل بشر قد أفسد طريقه على الأرض '),
(13896, 'Genesis', 1, 6, 13, ' فقال الله لنوح : نهاية كل بشر قد أتت أمامي ، لأن الأرض امتلأت ظلما منهم . فها أنا مهلكهم مع الأرض '),
(13897, 'Genesis', 1, 6, 14, ' اصنع لنفسك فلكا من خشب جفر . تجعل الفلك مساكن ، وتطليه من داخل ومن خارج بالقار '),
(13898, 'Genesis', 1, 6, 15, ' وهكذا تصنعه : ثلاث مئة ذراع يكون طول الفلك ، وخمسين ذراعا عرضه ، وثلاثين ذراعا ارتفاعه '),
(13899, 'Genesis', 1, 6, 16, ' وتصنع كوا للفلك ، وتكمله إلى حد ذراع من فوق . وتضع باب الفلك في جانبه . مساكن سفلية ومتوسطة وعلوية تجعله '),
(13900, 'Genesis', 1, 6, 17, ' فها أنا آت بطوفان الماء على الأرض لأهلك كل جسد فيه روح حياة من تحت السماء . كل ما في الأرض يموت '),
(13901, 'Genesis', 1, 6, 18, ' ولكن أقيم عهدي معك ، فتدخل الفلك أنت وبنوك وامرأتك ونساء بنيك معك '),
(13902, 'Genesis', 1, 6, 19, ' ومن كل حي من كل ذي جسد ، اثنين من كل تدخل إلى الفلك لاستبقائها معك . تكون ذكرا وأنثى '),
(13903, 'Genesis', 1, 6, 20, ' من الطيور كأجناسها ، ومن البهائم كأجناسها ، ومن كل دبابات الأرض كأجناسها . اثنين من كل تدخل إليك لاستبقائها '),
(13904, 'Genesis', 1, 6, 21, ' وأنت ، فخذ لنفسك من كل طعام يؤكل واجمعه عندك ، فيكون لك ولها طعاما '),
(13905, 'Genesis', 1, 6, 22, ' ففعل نوح حسب كل ما أمره به الله . هكذا فعل '),
(13906, 'Genesis', 1, 7, 1, ' وقال الرب لنوح : ادخل أنت وجميع بيتك إلى الفلك ، لأني إياك رأيت بارا لدي في هذا الجيل '),
(13907, 'Genesis', 1, 7, 2, ' من جميع البهائم الطاهرة تأخذ معك سبعة سبعة ذكرا وأنثى . ومن البهائم التي ليست بطاهرة اثنين : ذكرا وأنثى '),
(13908, 'Genesis', 1, 7, 3, ' ومن طيور السماء أيضا سبعة سبعة : ذكرا وأنثى . لاستبقاء نسل على وجه كل الأرض '),
(13909, 'Genesis', 1, 7, 4, ' لأني بعد سبعة أيام أيضا أمطر على الأرض أربعين يوما وأربعين ليلة . وأمحو عن وجه الأرض كل قائم عملته '),
(13910, 'Genesis', 1, 7, 5, ' ففعل نوح حسب كل ما أمره به الرب '),
(13911, 'Genesis', 1, 7, 6, ' ولما كان نوح ابن ست مئة سنة صار طوفان الماء على الأرض '),
(13912, 'Genesis', 1, 7, 7, ' فدخل نوح وبنوه وامرأته ونساء بنيه معه إلى الفلك من وجه مياه الطوفان '),
(13913, 'Genesis', 1, 7, 8, ' ومن البهائم الطاهرة والبهائم التي ليست بطاهرة ، ومن الطيور وكل ما يدب على الأرض '),
(13914, 'Genesis', 1, 7, 9, ' دخل اثنان اثنان إلى نوح إلى الفلك ، ذكرا وأنثى ، كما أمر الله نوحا '),
(13915, 'Genesis', 1, 7, 10, ' وحدث بعد السبعة الأيام أن مياه الطوفان صارت على الأرض '),
(13916, 'Genesis', 1, 7, 11, ' في سنة ست مئة من حياة نوح ، في الشهر الثانى ، في اليوم السابع عشر من الشهر في ذلك اليوم ، انفجرت كل ينابيع الغمر العظيم ، وانفتحت طاقات السماء '),
(13917, 'Genesis', 1, 7, 12, ' وكان المطر على الأرض أربعين يوما وأربعين ليلة '),
(13918, 'Genesis', 1, 7, 13, ' في ذلك اليوم عينه دخل نوح ، وسام وحام ويافث بنو نوح ، وامرأة نوح ، وثلاث نساء بنيه معهم إلى الفلك '),
(13919, 'Genesis', 1, 7, 14, ' هم وكل الوحوش كأجناسها ، وكل البهائم كأجناسها ، وكل الدبابات التي تدب على الأرض كأجناسها ، وكل الطيور كأجناسها : كل عصفور ، كل ذي جناح '),
(13920, 'Genesis', 1, 7, 15, ' ودخلت إلى نوح إلى الفلك ، اثنين اثنين من كل جسد فيه روح حياة '),
(13921, 'Genesis', 1, 7, 16, ' والداخلات دخلت ذكرا وأنثى ، من كل ذي جسد ، كما أمره الله . وأغلق الرب عليه '),
(13922, 'Genesis', 1, 7, 17, ' وكان الطوفان أربعين يوما على الأرض . وتكاثرت المياه ورفعت الفلك ، فارتفع عن الأرض '),
(13923, 'Genesis', 1, 7, 18, ' وتعاظمت المياه وتكاثرت جدا على الأرض ، فكان الفلك يسير على وجه المياه '),
(13924, 'Genesis', 1, 7, 19, ' وتعاظمت المياه كثيرا جدا على الأرض ، فتغطت جميع الجبال الشامخة التي تحت كل السماء '),
(13925, 'Genesis', 1, 7, 20, ' خمس عشرة ذراعا في الارتفاع تعاظمت المياه ، فتغطت الجبال '),
(13926, 'Genesis', 1, 7, 21, ' فمات كل ذي جسد كان يدب على الأرض من الطيور والبهائم والوحوش ، وكل الزحافات التي كانت تزحف على الأرض ، وجميع الناس '),
(13927, 'Genesis', 1, 7, 22, ' كل ما في أنفه نسمة روح حياة من كل ما في اليابسة مات '),
(13928, 'Genesis', 1, 7, 23, ' فمحا الله كل قائم كان على وجه الأرض : الناس ، والبهائم ، والدبابات ، وطيور السماء . فانمحت من الأرض . وتبقى نوح والذين معه في الفلك فقط '),
(13929, 'Genesis', 1, 7, 24, ' وتعاظمت المياه على الأرض مئة وخمسين يوما '),
(13930, 'Genesis', 1, 8, 1, ' ثم ذكر الله نوحا وكل الوحوش وكل البهائم التي معه في الفلك . وأجاز الله ريحا على الأرض فهدأت المياه '),
(13931, 'Genesis', 1, 8, 2, ' وانسدت ينابيع الغمر وطاقات السماء ، فامتنع المطر من السماء '),
(13932, 'Genesis', 1, 8, 3, ' ورجعت المياه عن الأرض رجوعا متواليا . وبعد مئة وخمسين يوما نقصت المياه '),
(13933, 'Genesis', 1, 8, 4, ' واستقر الفلك في الشهر السابع ، في اليوم السابع عشر من الشهر ، على جبال أراراط '),
(13934, 'Genesis', 1, 8, 5, ' وكانت المياه تنقص نقصا متواليا إلى الشهر العاشر . وفي العاشر في أول الشهر ، ظهرت رؤوس الجبال '),
(13935, 'Genesis', 1, 8, 6, ' وحدث من بعد أربعين يوما أن نوحا فتح طاقة الفلك التي كان قد عملها '),
(13936, 'Genesis', 1, 8, 7, ' وأرسل الغراب ، فخرج مترددا حتى نشفت المياه عن الأرض '),
(13937, 'Genesis', 1, 8, 8, ' ثم أرسل الحمامة من عنده ليرى هل قلت المياه عن وجه الأرض '),
(13938, 'Genesis', 1, 8, 9, ' فلم تجد الحمامة مقرا لرجلها ، فرجعت إليه إلى الفلك لأن مياها كانت على وجه كل الأرض . فمد يده وأخذها وأدخلها عنده إلى الفلك '),
(13939, 'Genesis', 1, 8, 10, ' فلبث أيضا سبعة أيام أخر وعاد فأرسل الحمامة من الفلك '),
(13940, 'Genesis', 1, 8, 11, ' فأتت إليه الحمامة عند المساء ، وإذا ورقة زيتون خضراء في فمها . فعلم نوح أن المياه قد قلت عن الأرض '),
(13941, 'Genesis', 1, 8, 12, ' فلبث أيضا سبعة أيام أخر وأرسل الحمامة فلم تعد ترجع إليه أيضا '),
(13942, 'Genesis', 1, 8, 13, ' وكان في السنة الواحدة والست مئة ، في الشهر الأول في أول الشهر ، أن المياه نشفت عن الأرض . فكشف نوح الغطاء عن الفلك ونظر ، فإذا وجه الأرض قد نشف '),
(13943, 'Genesis', 1, 8, 14, ' وفي الشهر الثاني ، في اليوم السابع والعشرين من الشهر ، جفت الأرض '),
(13944, 'Genesis', 1, 8, 15, ' وكلم الله نوحا قائلا '),
(13945, 'Genesis', 1, 8, 16, ' اخرج من الفلك أنت وامرأتك وبنوك ونساء بنيك معك '),
(13946, 'Genesis', 1, 8, 17, ' وكل الحيوانات التي معك من كل ذي جسد : الطيور ، والبهائم ، وكل الدبابات التي تدب على الأرض ، أخرجها معك . ولتتوالد في الأرض وتثمر وتكثر على الأرض '),
(13947, 'Genesis', 1, 8, 18, ' فخرج نوح وبنوه وامرأته ونساء بنيه معه '),
(13948, 'Genesis', 1, 8, 19, ' وكل الحيوانات ، كل الدبابات ، وكل الطيور ، كل ما يدب على الأرض ، كأنواعها خرجت من الفلك '),
(13949, 'Genesis', 1, 8, 20, ' وبنى نوح مذبحا للرب . وأخذ من كل البهائم الطاهرة ومن كل الطيور الطاهرة وأصعد محرقات على المذبح '),
(13950, 'Genesis', 1, 8, 21, ' فتنسم الرب رائحة الرضا . وقال الرب في قلبه : لا أعود ألعن الأرض أيضا من أجل الإنسان ، لأن تصور قلب الإنسان شرير منذ حداثته . ولا أعود أيضا أميت كل حي كما فعلت '),
(13951, 'Genesis', 1, 8, 22, ' مدة كل أيام الأرض : زرع وحصاد ، وبرد وحر ، وصيف وشتاء ، ونهار وليل،لا تزال '),
(13952, 'Genesis', 1, 9, 1, ' وبارك الله نوحا وبنيه وقال لهم : أثمروا واكثروا واملأوا الأرض '),
(13953, 'Genesis', 1, 9, 2, ' ولتكن خشيتكم ورهبتكم على كل حيوانات الأرض وكل طيور السماء ، مع كل ما يدب على الأرض ، وكل أسماك البحر . قد دفعت إلى أيديكم '),
(13954, 'Genesis', 1, 9, 3, ' كل دابة حية تكون لكم طعاما . كالعشب الأخضر دفعت إليكم الجميع '),
(13955, 'Genesis', 1, 9, 4, ' غير أن لحما بحياته ، دمه ، لا تأكلوه '),
(13956, 'Genesis', 1, 9, 5, ' وأطلب أنا دمكم لأنفسكم فقط . من يد كل حيوان أطلبه . ومن يد الإنسان أطلب نفس الإنسان ، من يد الإنسان أخيه '),
(13957, 'Genesis', 1, 9, 6, ' سافك دم الإنسان بالإنسان يسفك دمه . لأن الله على صورته عمل الإنسان '),
(13958, 'Genesis', 1, 9, 7, ' فأثمروا أنتم واكثروا وتوالدوا في الأرض وتكاثروا فيها '),
(13959, 'Genesis', 1, 9, 8, ' وكلم الله نوحا وبنيه معه قائلا '),
(13960, 'Genesis', 1, 9, 9, ' وها أنا مقيم ميثاقي معكم ومع نسلكم من بعدكم '),
(13961, 'Genesis', 1, 9, 10, ' ومع كل ذوات الأنفس الحية التي معكم : الطيور والبهائم وكل وحوش الأرض التي معكم ، من جميع الخارجين من الفلك حتى كل حيوان الأرض '),
(13962, 'Genesis', 1, 9, 11, ' أقيم ميثاقي معكم فلا ينقرض كل ذي جسد أيضا بمياه الطوفان . ولا يكون أيضا طوفان ليخرب الأرض '),
(13963, 'Genesis', 1, 9, 12, ' وقال الله : هذه علامة الميثاق الذي أنا واضعه بيني وبينكم ، وبين كل ذوات الأنفس الحية التي معكم إلى أجيال الدهر '),
(13964, 'Genesis', 1, 9, 13, ' وضعت قوسي في السحاب فتكون علامة ميثاق بيني وبين الأرض '),
(13965, 'Genesis', 1, 9, 14, ' فيكون متى أنشر سحابا على الأرض ، وتظهر القوس في السحاب '),
(13966, 'Genesis', 1, 9, 15, ' أني أذكر ميثاقي الذي بيني وبينكم وبين كل نفس حية في كل جسد . فلا تكون أيضا المياه طوفانا لتهلك كل ذي جسد '),
(13967, 'Genesis', 1, 9, 16, ' فمتى كانت القوس في السحاب ، أبصرها لأذكر ميثاقا أبديا بين الله وبين كل نفس حية في كل جسد على الأرض '),
(13968, 'Genesis', 1, 9, 17, ' وقال الله لنوح : هذه علامة الميثاق الذي أنا أقمته بيني وبين كل ذي جسد على الأرض '),
(13969, 'Genesis', 1, 9, 18, ' وكان بنو نوح الذين خرجوا من الفلك ساما وحاما ويافث . وحام هو أبو كنعان '),
(13970, 'Genesis', 1, 9, 19, ' هؤلاء الثلاثة هم بنو نوح . ومن هؤلاء تشعبت كل الأرض '),
(13971, 'Genesis', 1, 9, 20, ' وابتدأ نوح يكون فلاحا وغرس كرما '),
(13972, 'Genesis', 1, 9, 21, ' وشرب من الخمر فسكر وتعرى داخل خبائه '),
(13973, 'Genesis', 1, 9, 22, ' فأبصر حام أبو كنعان عورة أبيه ، وأخبر أخويه خارجا '),
(13974, 'Genesis', 1, 9, 23, ' فأخذ سام ويافث الرداء ووضعاه على أكتافهما ومشيا إلى الوراء ، وسترا عورة أبيهما ووجهاهما إلى الوراء . فلم يبصرا عورة أبيهما '),
(13975, 'Genesis', 1, 9, 24, ' فلما استيقظ نوح من خمره ، علم ما فعل به ابنه الصغير '),
(13976, 'Genesis', 1, 9, 25, ' فقال : ملعون كنعان عبد العبيد يكون لإخوته '),
(13977, 'Genesis', 1, 9, 26, ' وقال : مبارك الرب إله سام . وليكن كنعان عبدا لهم '),
(13978, 'Genesis', 1, 9, 27, ' ليفتح الله ليافث فيسكن في مساكن سام ، وليكن كنعان عبدا لهم '),
(13979, 'Genesis', 1, 9, 28, ' وعاش نوح بعد الطوفان ثلاث مئة وخمسين سنة '),
(13980, 'Genesis', 1, 9, 29, ' فكانت كل أيام نوح تسع مئة وخمسين سنة ، ومات '),
(13981, 'Genesis', 1, 10, 1, ' وهذه مواليد بني نوح : سام وحام ويافث . وولد لهم بنون بعد الطوفان '),
(13982, 'Genesis', 1, 10, 2, ' بنو يافث : جومر وماجوج وماداي وياوان وتوبال وماشك وتيراس '),
(13983, 'Genesis', 1, 10, 3, ' وبنو جومر : أشكناز وريفاث وتوجرمة '),
(13984, 'Genesis', 1, 10, 4, ' وبنو ياوان : أليشة وترشيش وكتيم ودودانيم '),
(13985, 'Genesis', 1, 10, 5, ' من هؤلاء تفرقت جزائر الأمم بأراضيهم ، كل إنسان كلسانه حسب قبائلهم بأممهم '),
(13986, 'Genesis', 1, 10, 6, ' وبنو حام : كوش ومصرايم وفوط وكنعان '),
(13987, 'Genesis', 1, 10, 7, ' وبنو كوش : سبا وحويلة وسبتة ورعمة وسبتكا . وبنو رعمة : شبا وددان '),
(13988, 'Genesis', 1, 10, 8, ' وكوش ولد نمرود الذي ابتدأ يكون جبارا في الأرض '),
(13989, 'Genesis', 1, 10, 9, ' الذي كان جبار صيد أمام الرب . لذلك يقال : كنمرود جبار صيد أمام الرب '),
(13990, 'Genesis', 1, 10, 10, ' وكان ابتداء مملكته بابل وأرك وأكد وكلنة ، في أرض شنعار '),
(13991, 'Genesis', 1, 10, 11, ' من تلك الأرض خرج أشور وبنى نينوى ورحوبوت عير وكالح '),
(13992, 'Genesis', 1, 10, 12, ' ورسن ، بين نينوى وكالح ، هي المدينة الكبيرة '),
(13993, 'Genesis', 1, 10, 13, ' ومصرايم ولد : لوديم وعناميم ولهابيم ونفتوحيم '),
(13994, 'Genesis', 1, 10, 14, ' وفتروسيم وكسلوحيم . الذين خرج منهم فلشتيم وكفتوريم '),
(13995, 'Genesis', 1, 10, 15, ' وكنعان ولد : صيدون بكره ، وحثا '),
(13996, 'Genesis', 1, 10, 16, ' واليبوسي والأموري والجرجاشي '),
(13997, 'Genesis', 1, 10, 17, ' والحوي والعرقي والسيني '),
(13998, 'Genesis', 1, 10, 18, ' والأروادي والصماري والحماتي . وبعد ذلك تفرقت قبائل الكنعاني '),
(13999, 'Genesis', 1, 10, 19, ' وكانت تخوم الكنعاني من صيدون ، حينما تجيء نحو جرار إلى غزة ، وحينما تجيء نحو سدوم وعمورة وأدمة وصبوييم إلى لاشع '),
(14000, 'Genesis', 1, 10, 20, ' هؤلاء بنو حام حسب قبائلهم كألسنتهم بأراضيهم وأممهم '),
(14001, 'Genesis', 1, 10, 21, ' وسام أبو كل بني عابر ، أخو يافث الكبير ، ولد له أيضا بنون '),
(14002, 'Genesis', 1, 10, 22, ' بنو سام : عيلام وأشور وأرفكشاد ولود وأرام '),
(14003, 'Genesis', 1, 10, 23, ' وبنو أرام : عوص وحول وجاثر وماش '),
(14004, 'Genesis', 1, 10, 24, ' وأرفكشاد ولد شالح ، وشالح ولد عابر '),
(14005, 'Genesis', 1, 10, 25, ' ولعابر ولد ابنان : اسم الواحد فالج لأن في أيامه قسمت الأرض . واسم أخيه يقطان '),
(14006, 'Genesis', 1, 10, 26, ' ويقطان ولد : ألموداد وشالف وحضرموت ويارح '),
(14007, 'Genesis', 1, 10, 27, ' وهدورام وأوزال ودقلة '),
(14008, 'Genesis', 1, 10, 28, ' وعوبال وأبيمايل وشبا '),
(14009, 'Genesis', 1, 10, 29, ' وأوفير وحويلة ويوباب . جميع هؤلاء بنو يقطان '),
(14010, 'Genesis', 1, 10, 30, ' وكان مسكنهم من ميشا حينما تجيء نحو سفار جبل المشرق '),
(14011, 'Genesis', 1, 10, 31, ' هؤلاء بنو سام حسب قبائلهم كألسنتهم بأراضيهم حسب أممهم '),
(14012, 'Genesis', 1, 10, 32, ' هؤلاء قبائل بني نوح حسب مواليدهم بأممهم . ومن هؤلاء تفرقت الأمم في الأرض بعد الطوفان '),
(14013, 'Genesis', 1, 11, 1, ' وكانت الأرض كلها لسانا واحدا ولغة واحدة '),
(14014, 'Genesis', 1, 11, 2, ' وحدث في ارتحالهم شرقا أنهم وجدوا بقعة في أرض شنعار وسكنوا هناك '),
(14015, 'Genesis', 1, 11, 3, ' وقال بعضهم لبعض : هلم نصنع لبنا ونشويه شيا . فكان لهم اللبن مكان الحجر ، وكان لهم الحمر مكان الطين '),
(14016, 'Genesis', 1, 11, 4, ' وقالوا : هلم نبن لأنفسنا مدينة وبرجا رأسه بالسماء . ونصنع لأنفسنا اسما لئلا نتبدد على وجه كل الأرض '),
(14017, 'Genesis', 1, 11, 5, ' فنزل الرب لينظر المدينة والبرج اللذين كان بنو آدم يبنونهما '),
(14018, 'Genesis', 1, 11, 6, ' وقال الرب : هوذا شعب واحد ولسان واحد لجميعهم ، وهذا ابتداؤهم بالعمل . والآن لا يمتنع عليهم كل ما ينوون أن يعملوه '),
(14019, 'Genesis', 1, 11, 7, ' هلم ننزل ونبلبل هناك لسانهم حتى لا يسمع بعضهم لسان بعض '),
(14020, 'Genesis', 1, 11, 8, ' فبددهم الرب من هناك على وجه كل الأرض ، فكفوا عن بنيان المدينة '),
(14021, 'Genesis', 1, 11, 9, ' لذلك دعي اسمها بابل لأن الرب هناك بلبل لسان كل الأرض . ومن هناك بددهم الرب على وجه كل الأرض '),
(14022, 'Genesis', 1, 11, 10, ' هذه مواليد سام : لما كان سام ابن مئة سنة ولد أرفكشاد ، بعد الطوفان بسنتين '),
(14023, 'Genesis', 1, 11, 11, ' وعاش سام بعد ما ولد أرفكشاد خمس مئة سنة ، وولد بنين وبنات '),
(14024, 'Genesis', 1, 11, 12, ' وعاش أرفكشاد خمسا وثلاثين سنة وولد شالح '),
(14025, 'Genesis', 1, 11, 13, ' وعاش أرفكشاد بعد ما ولد شالح أربع مئة وثلاث سنين ، وولد بنين وبنات '),
(14026, 'Genesis', 1, 11, 14, ' وعاش شالح ثلاثين سنة وولد عابر '),
(14027, 'Genesis', 1, 11, 15, ' وعاش شالح بعد ما ولد عابر أربع مئة وثلاث سنين ، وولد بنين وبنات '),
(14028, 'Genesis', 1, 11, 16, ' وعاش عابر أربعا وثلاثين سنة وولد فالج '),
(14029, 'Genesis', 1, 11, 17, ' وعاش عابر بعد ما ولد فالج أربع مئة وثلاثين سنة ، وولد بنين وبنات '),
(14030, 'Genesis', 1, 11, 18, ' وعاش فالج ثلاثين سنة وولد رعو '),
(14031, 'Genesis', 1, 11, 19, ' وعاش فالج بعد ما ولد رعو مئتين وتسع سنين ، وولد بنين وبنات '),
(14032, 'Genesis', 1, 11, 20, ' وعاش رعو اثنتين وثلاثين سنة وولد سروج '),
(14033, 'Genesis', 1, 11, 21, ' وعاش رعو بعد ما ولد سروج مئتين وسبع سنين ، وولد بنين وبنات '),
(14034, 'Genesis', 1, 11, 22, ' وعاش سروج ثلاثين سنة وولد ناحور '),
(14035, 'Genesis', 1, 11, 23, ' وعاش سروج بعد ما ولد ناحور مئتي سنة ، وولد بنين وبنات '),
(14036, 'Genesis', 1, 11, 24, ' وعاش ناحور تسعا وعشرين سنة وولد تارح '),
(14037, 'Genesis', 1, 11, 25, ' وعاش ناحور بعد ما ولد تارح مئة وتسع عشرة سنة ، وولد بنين وبنات '),
(14038, 'Genesis', 1, 11, 26, ' وعاش تارح سبعين سنة ، وولد أبرام وناحور وهاران '),
(14039, 'Genesis', 1, 11, 27, ' وهذه مواليد تارح : ولد تارح أبرام وناحور وهاران . وولد هاران لوطا '),
(14040, 'Genesis', 1, 11, 28, ' ومات هاران قبل تارح أبيه في أرض ميلاده في أور الكلدانيين '),
(14041, 'Genesis', 1, 11, 29, ' واتخذ أبرام وناحور لأنفسهما امرأتين : اسم امرأة أبرام ساراي ، واسم امرأة ناحور ملكة بنت هاران ، أبي ملكة وأبي يسكة '),
(14042, 'Genesis', 1, 11, 30, ' وكانت ساراي عاقرا ليس لها ولد '),
(14043, 'Genesis', 1, 11, 31, ' وأخذ تارح أبرام ابنه ، ولوطا بن هاران ، ابن ابنه ، وساراي كنته امرأة أبرام ابنه ، فخرجوا معا من أور الكلدانيين ليذهبوا إلى أرض كنعان . فأتوا إلى حاران وأقاموا هناك '),
(14044, 'Genesis', 1, 11, 32, ' وكانت أيام تارح مئتين وخمس سنين . ومات تارح في حاران '),
(14045, 'Genesis', 1, 12, 1, ' وقال الرب لأبرام : اذهب من أرضك ومن عشيرتك ومن بيت أبيك إلى الأرض التي أريك '),
(14046, 'Genesis', 1, 12, 2, ' فأجعلك أمة عظيمة وأباركك وأعظم اسمك ، وتكون بركة '),
(14047, 'Genesis', 1, 12, 3, ' وأبارك مباركيك ، ولاعنك ألعنه . وتتبارك فيك جميع قبائل الأرض '),
(14048, 'Genesis', 1, 12, 4, ' فذهب أبرام كما قال له الرب وذهب معه لوط . وكان أبرام ابن خمس وسبعين سنة لما خرج من حاران '),
(14049, 'Genesis', 1, 12, 5, ' فأخذ أبرام ساراي امرأته ، ولوطا ابن أخيه ، وكل مقتنياتهما التي اقتنيا والنفوس التي امتلكا في حاران . وخرجوا ليذهبوا إلى أرض كنعان . فأتوا إلى أرض كنعان '),
(14050, 'Genesis', 1, 12, 6, ' واجتاز أبرام في الأرض إلى مكان شكيم إلى بلوطة مورة . وكان الكنعانيون حينئذ في الأرض '),
(14051, 'Genesis', 1, 12, 7, ' وظهر الرب لأبرام وقال : لنسلك أعطي هذه الأرض . فبنى هناك مذبحا للرب الذي ظهر له '),
(14052, 'Genesis', 1, 12, 8, ' ثم نقل من هناك إلى الجبل شرقي بيت إيل ونصب خيمته . وله بيت إيل من المغرب وعاي من المشرق . فبنى هناك مذبحا للرب ودعا باسم الرب '),
(14053, 'Genesis', 1, 12, 9, ' ثم ارتحل أبرام ارتحالا متواليا نحو الجنوب '),
(14054, 'Genesis', 1, 12, 10, ' وحدث جوع في الأرض ، فانحدر أبرام إلى مصر ليتغرب هناك ، لأن الجوع في الأرض كان شديدا '),
(14055, 'Genesis', 1, 12, 11, ' وحدث لما قرب أن يدخل مصر أنه قال لساراي امرأته : إني قد علمت أنك امرأة حسنة المنظر '),
(14056, 'Genesis', 1, 12, 12, ' فيكون إذا رآك المصريون أنهم يقولون : هذه امرأته . فيقتلونني ويستبقونك '),
(14057, 'Genesis', 1, 12, 13, ' قولي إنك أختي ، ليكون لي خير بسببك وتحيا نفسي من أجلك '),
(14058, 'Genesis', 1, 12, 14, ' فحدث لما دخل أبرام إلى مصر أن المصريين رأوا المرأة أنها حسنة جدا '),
(14059, 'Genesis', 1, 12, 15, ' ورآها رؤساء فرعون ومدحوها لدى فرعون ، فأخذت المرأة إلى بيت فرعون '),
(14060, 'Genesis', 1, 12, 16, ' فصنع إلى أبرام خيرا بسببها ، وصار له غنم وبقر وحمير وعبيد وإماء وأتن وجمال '),
(14061, 'Genesis', 1, 12, 17, ' فضرب الرب فرعون وبيته ضربات عظيمة بسبب ساراي امرأة أبرام '),
(14062, 'Genesis', 1, 12, 18, ' فدعا فرعون أبرام وقال : ما هذا الذي صنعت بي ؟ لماذا لم تخبرني أنها امرأتك '),
(14063, 'Genesis', 1, 12, 19, ' لماذا قلت : هي أختي ، حتى أخذتها لي لتكون زوجتي ؟ والآن هوذا امرأتك خذها واذهب '),
(14064, 'Genesis', 1, 12, 20, ' فأوصى عليه فرعون رجالا فشيعوه وامرأته وكل ما كان له '),
(14065, 'Genesis', 1, 13, 1, ' فصعد أبرام من مصر هو وامرأته وكل ما كان له ، ولوط معه إلى الجنوب '),
(14066, 'Genesis', 1, 13, 2, ' وكان أبرام غنيا جدا في المواشي والفضة والذهب '),
(14067, 'Genesis', 1, 13, 3, ' وسار في رحلاته من الجنوب إلى بيت إيل ، إلى المكان الذي كانت خيمته فيه في البداءة ، بين بيت إيل وعاي '),
(14068, 'Genesis', 1, 13, 4, ' إلى مكان المذبح الذي عمله هناك أولا . ودعا هناك أبرام باسم الرب '),
(14069, 'Genesis', 1, 13, 5, ' ولوط السائر مع أبرام ، كان له أيضا غنم وبقر وخيام '),
(14070, 'Genesis', 1, 13, 6, ' ولم تحتملهما الأرض أن يسكنا معا ، إذ كانت أملاكهما كثيرة ، فلم يقدرا أن يسكنا معا '),
(14071, 'Genesis', 1, 13, 7, ' فحدثت مخاصمة بين رعاة مواشي أبرام ورعاة مواشي لوط . وكان الكنعانيون والفرزيون حينئذ ساكنين في الأرض '),
(14072, 'Genesis', 1, 13, 8, ' فقال أبرام للوط : لا تكن مخاصمة بيني وبينك ، وبين رعاتي ورعاتك ، لأننا نحن أخوان '),
(14073, 'Genesis', 1, 13, 9, ' أليست كل الأرض أمامك ؟ اعتزل عني . إن ذهبت شمالا فأنا يمينا ، وإن يمينا فأنا شمالا '),
(14074, 'Genesis', 1, 13, 10, ' فرفع لوط عينيه ورأى كل دائرة الأردن أن جميعها سقي ، قبلما أخرب الرب سدوم وعمورة ، كجنة الرب ، كأرض مصر . حينما تجيء إلى صوغر '),
(14075, 'Genesis', 1, 13, 11, ' فاختار لوط لنفسه كل دائرة الأردن ، وارتحل لوط شرقا . فاعتزل الواحد عن الآخر '),
(14076, 'Genesis', 1, 13, 12, ' أبرام سكن في أرض كنعان ، ولوط سكن في مدن الدائرة ، ونقل خيامه إلى سدوم '),
(14077, 'Genesis', 1, 13, 13, ' وكان أهل سدوم أشرارا وخطاة لدى الرب جدا '),
(14078, 'Genesis', 1, 13, 14, ' وقال الرب لأبرام ، بعد اعتزال لوط عنه : ارفع عينيك وانظر من الموضع الذي أنت فيه شمالا وجنوبا وشرقا وغربا '),
(14079, 'Genesis', 1, 13, 15, ' لأن جميع الأرض التي أنت ترى لك أعطيها ولنسلك إلى الأبد '),
(14080, 'Genesis', 1, 13, 16, ' وأجعل نسلك كتراب الأرض ، حتى إذا استطاع أحد أن يعد تراب الأرض فنسلك أيضا يعد '),
(14081, 'Genesis', 1, 13, 17, ' قم امش في الأرض طولها وعرضها ، لأني لك أعطيها '),
(14082, 'Genesis', 1, 13, 18, ' فنقل أبرام خيامه وأتى وأقام عند بلوطات ممرا التي في حبرون ، وبنى هناك مذبحا للرب '),
(14083, 'Genesis', 1, 14, 1, ' وحدث في أيام أمرافل ملك شنعار ، وأريوك ملك ألاسار ، وكدرلعومر ملك عيلام ، وتدعال ملك جوييم '),
(14084, 'Genesis', 1, 14, 2, ' أن هؤلاء صنعوا حربا مع بارع ملك سدوم ، وبرشاع ملك عمورة ، وشنآب ملك أدمة ، وشمئيبر ملك صبوييم ، وملك بالع التي هي صوغر '),
(14085, 'Genesis', 1, 14, 3, ' جميع هؤلاء اجتمعوا متعاهدين إلى عمق السديم الذي هو بحر الملح '),
(14086, 'Genesis', 1, 14, 4, ' اثنتي عشرة سنة استعبدوا لكدرلعومر ، والسنة الثالثة عشرة عصوا عليه '),
(14087, 'Genesis', 1, 14, 5, ' وفي السنة الرابعة عشرة أتى كدرلعومر والملوك الذين معه وضربوا الرفائيين في عشتاروث قرنايم ، والزوزيين في هام ، والإيميين في شوى قريتايم '),
(14088, 'Genesis', 1, 14, 6, ' والحوريين في جبلهم سعير إلى بطمة فاران التي عند البرية '),
(14089, 'Genesis', 1, 14, 7, ' ثم رجعوا وجاءوا إلى عين مشفاط التي هي قادش . وضربوا كل بلاد العمالقة ، وأيضا الأموريين الساكنين في حصون تامار '),
(14090, 'Genesis', 1, 14, 8, ' فخرج ملك سدوم ، وملك عمورة ، وملك أدمة ، وملك صبوييم ، وملك بالع ، التي هي صوغر ، ونظموا حربا معهم في عمق السديم '),
(14091, 'Genesis', 1, 14, 9, ' مع كدرلعومر ملك عيلام ، وتدعال ملك جوييم ، وأمرافل ملك شنعار ، وأريوك ملك ألاسار . أربعة ملوك مع خمسة '),
(14092, 'Genesis', 1, 14, 10, ' وعمق السديم كان فيه آبار حمر كثيرة . فهرب ملكا سدوم وعمورة وسقطا هناك ، والباقون هربوا إلى الجبل '),
(14093, 'Genesis', 1, 14, 11, ' فأخذوا جميع أملاك سدوم وعمورة وجميع أطعمتهم ومضوا '),
(14094, 'Genesis', 1, 14, 12, ' وأخذوا لوطا ابن أخي أبرام وأملاكه ومضوا ، إذ كان ساكنا في سدوم '),
(14095, 'Genesis', 1, 14, 13, ' فأتى من نجا وأخبر أبرام العبراني . وكان ساكنا عند بلوطات ممرا الأموري ، أخي أشكول وأخي عانر . وكانوا أصحاب عهد مع أبرام '),
(14096, 'Genesis', 1, 14, 14, ' فلما سمع أبرام ، أن أخاه سبي جر غلمانه المتمرنين ، ولدان بيته ، ثلاث مئة وثمانية عشر ، وتبعهم إلى دان '),
(14097, 'Genesis', 1, 14, 15, ' وانقسم عليهم ليلا هو وعبيده فكسرهم وتبعهم إلى حوبة التي عن شمال دمشق '),
(14098, 'Genesis', 1, 14, 16, ' واسترجع كل الأملاك ، واسترجع لوطا أخاه أيضا وأملاكه ، والنساء أيضا والشعب '),
(14099, 'Genesis', 1, 14, 17, ' فخرج ملك سدوم لاستقباله ، بعد رجوعه من كسرة كدرلعومر والملوك الذين معه إلى عمق شوى ، الذي هو عمق الملك '),
(14100, 'Genesis', 1, 14, 18, ' وملكي صادق ، ملك شاليم ، أخرج خبزا وخمرا . وكان كاهنا لله العلي '),
(14101, 'Genesis', 1, 14, 19, ' وباركه وقال : مبارك أبرام من الله العلي مالك السماوات والأرض '),
(14102, 'Genesis', 1, 14, 20, ' ومبارك الله العلي الذي أسلم أعداءك في يدك . فأعطاه عشرا من كل شيء '),
(14103, 'Genesis', 1, 14, 21, ' وقال ملك سدوم لأبرام : أعطني النفوس ، وأما الأملاك فخذها لنفسك '),
(14104, 'Genesis', 1, 14, 22, ' فقال أبرام لملك سدوم : رفعت يدي إلى الرب الإله العلي مالك السماء والأرض '),
(14105, 'Genesis', 1, 14, 23, ' لا آخذن لا خيطا ولا شراك نعل ولا من كل ما هو لك ، فلا تقول : أنا أغنيت أبرام '),
(14106, 'Genesis', 1, 14, 24, ' ليس لي غير الذي أكله الغلمان ، وأما نصيب الرجال الذين ذهبوا معي : عانر وأشكول وممرا ، فهم يأخذون نصيبهم '),
(14107, 'Genesis', 1, 15, 1, ' بعد هذه الأمور صار كلام الرب إلى أبرام في الرؤيا قائلا : لا تخف يا أبرام . أنا ترس لك . أجرك كثير جدا '),
(14108, 'Genesis', 1, 15, 2, ' فقال أبرام : أيها السيد الرب ، ماذا تعطيني وأنا ماض عقيما ، ومالك بيتي هو أليعازر الدمشقي '),
(14109, 'Genesis', 1, 15, 3, ' وقال أبرام أيضا : إنك لم تعطني نسلا ، وهوذا ابن بيتي وارث لي '),
(14110, 'Genesis', 1, 15, 4, ' فإذا كلام الرب إليه قائلا : لا يرثك هذا ، بل الذي يخرج من أحشائك هو يرثك '),
(14111, 'Genesis', 1, 15, 5, ' ثم أخرجه إلى خارج وقال : انظر إلى السماء وعد النجوم إن استطعت أن تعدها . وقال له : هكذا يكون نسلك '),
(14112, 'Genesis', 1, 15, 6, ' فآمن بالرب فحسبه له برا '),
(14113, 'Genesis', 1, 15, 7, ' وقال له : أنا الرب الذي أخرجك من أور الكلدانيين ليعطيك هذه الأرض لترثها '),
(14114, 'Genesis', 1, 15, 8, ' فقال : أيها السيد الرب ، بماذا أعلم أني أرثها '),
(14115, 'Genesis', 1, 15, 9, ' فقال له : خذ لي عجلة ثلاثية ، وعنزة ثلاثية ، وكبشا ثلاثيا ، ويمامة وحمامة '),
(14116, 'Genesis', 1, 15, 10, ' فأخذ هذه كلها وشقها من الوسط ، وجعل شق كل واحد مقابل صاحبه . وأما الطير فلم يشقه '),
(14117, 'Genesis', 1, 15, 11, ' فنزلت الجوارح على الجثث ، وكان أبرام يزجرها '),
(14118, 'Genesis', 1, 15, 12, ' ولما صارت الشمس إلى المغيب ، وقع على أبرام سبات ، وإذا رعبة مظلمة عظيمة واقعة عليه '),
(14119, 'Genesis', 1, 15, 13, ' فقال لأبرام : اعلم يقينا أن نسلك سيكون غريبا في أرض ليست لهم ، ويستعبدون لهم . فيذلونهم أربع مئة سنة '),
(14120, 'Genesis', 1, 15, 14, ' ثم الأمة التي يستعبدون لها أنا أدينها ، وبعد ذلك يخرجون بأملاك جزيلة '),
(14121, 'Genesis', 1, 15, 15, ' وأما أنت فتمضي إلى آبائك بسلام وتدفن بشيبة صالحة '),
(14122, 'Genesis', 1, 15, 16, ' وفي الجيل الرابع يرجعون إلى ههنا ، لأن ذنب الأموريين ليس إلى الآن كاملا '),
(14123, 'Genesis', 1, 15, 17, ' ثم غابت الشمس فصارت العتمة ، وإذا تنور دخان ومصباح نار يجوز بين تلك القطع '),
(14124, 'Genesis', 1, 15, 18, ' في ذلك اليوم قطع الرب مع أبرام ميثاقا قائلا : لنسلك أعطي هذه الأرض ، من نهر مصر إلى النهر الكبير ، نهر الفرات '),
(14125, 'Genesis', 1, 15, 19, ' القينيين والقنزيين والقدمونيين '),
(14126, 'Genesis', 1, 15, 20, ' والحثيين والفرزيين والرفائيين '),
(14127, 'Genesis', 1, 15, 21, ' والأموريين والكنعانيين والجرجاشيين واليبوسيين '),
(14128, 'Genesis', 1, 16, 1, ' وأما ساراي امرأة أبرام فلم تلد له . وكانت لها جارية مصرية اسمها هاجر '),
(14129, 'Genesis', 1, 16, 2, ' فقالت ساراي لأبرام : هوذا الرب قد أمسكني عن الولادة . ادخل على جاريتي لعلي أرزق منها بنين . فسمع أبرام لقول ساراي '),
(14130, 'Genesis', 1, 16, 3, ' فأخذت ساراي امرأة أبرام هاجر المصرية جاريتها ، من بعد عشر سنين لإقامة أبرام في أرض كنعان ، وأعطتها لأبرام رجلها زوجة له '),
(14131, 'Genesis', 1, 16, 4, ' فدخل على هاجر فحبلت . ولما رأت أنها حبلت صغرت مولاتها في عينيها '),
(14132, 'Genesis', 1, 16, 5, ' فقالت ساراي لأبرام : ظلمي عليك أنا دفعت جاريتي إلى حضنك ، فلما رأت أنها حبلت صغرت في عينيها . يقضي الرب بيني وبينك '),
(14133, 'Genesis', 1, 16, 6, ' فقال أبرام لساراي : هوذا جاريتك في يدك . افعلي بها ما يحسن في عينيك . فأذلتها ساراي ، فهربت من وجهها '),
(14134, 'Genesis', 1, 16, 7, ' فوجدها ملاك الرب على عين الماء في البرية ، على العين التي في طريق شور '),
(14135, 'Genesis', 1, 16, 8, ' وقال : يا هاجر جارية ساراي ، من أين أتيت ؟ وإلى أين تذهبين ؟  . فقالت : أنا هاربة من وجه مولاتي ساراي '),
(14136, 'Genesis', 1, 16, 9, ' فقال لها ملاك الرب : ارجعي إلى مولاتك واخضعي تحت يديها '),
(14137, 'Genesis', 1, 16, 10, ' وقال لها ملاك الرب : تكثيرا أكثر نسلك فلا يعد من الكثرة '),
(14138, 'Genesis', 1, 16, 11, ' وقال لها ملاك الرب : ها أنت حبلى ، فتلدين ابنا وتدعين اسمه إسماعيل ، لأن الرب قد سمع لمذلتك '),
(14139, 'Genesis', 1, 16, 12, ' وإنه يكون إنسانا وحشيا ، يده على كل واحد ، ويد كل واحد عليه ، وأمام جميع إخوته يسكن '),
(14140, 'Genesis', 1, 16, 13, ' فدعت اسم الرب الذي تكلم معها : أنت إيل رئي . لأنها قالت : أههنا أيضا رأيت بعد رؤية '),
(14141, 'Genesis', 1, 16, 14, ' لذلك دعيت البئر بئر لحي رئي . ها هي بين قادش وبارد '),
(14142, 'Genesis', 1, 16, 15, ' فولدت هاجر لأبرام ابنا . ودعا أبرام اسم ابنه الذي ولدته هاجر إسماعيل '),
(14143, 'Genesis', 1, 16, 16, ' كان أبرام ابن ست وثمانين سنة لما ولدت هاجر إسماعيل لأبرام '),
(14144, 'Genesis', 1, 17, 1, ' ولما كان أبرام ابن تسع وتسعين سنة ظهر الرب لأبرام وقال له : أنا الله القدير . سر أمامي وكن كاملا '),
(14145, 'Genesis', 1, 17, 2, ' فأجعل عهدي بيني وبينك ، وأكثرك كثيرا جدا '),
(14146, 'Genesis', 1, 17, 3, ' فسقط أبرام على وجهه . وتكلم الله معه قائلا '),
(14147, 'Genesis', 1, 17, 4, ' أما أنا فهوذا عهدي معك ، وتكون أبا لجمهور من الأمم '),
(14148, 'Genesis', 1, 17, 5, ' فلا يدعى اسمك بعد أبرام بل يكون اسمك إبراهيم ، لأني أجعلك أبا لجمهور من الأمم '),
(14149, 'Genesis', 1, 17, 6, ' وأثمرك كثيرا جدا ، وأجعلك أمما ، وملوك منك يخرجون '),
(14150, 'Genesis', 1, 17, 7, ' وأقيم عهدي بيني وبينك ، وبين نسلك من بعدك في أجيالهم ، عهدا أبديا ، لأكون إلها لك ولنسلك من بعدك '),
(14151, 'Genesis', 1, 17, 8, ' وأعطي لك ولنسلك من بعدك أرض غربتك ، كل أرض كنعان ملكا أبديا . وأكون إلههم '),
(14152, 'Genesis', 1, 17, 9, ' وقال الله لإبراهيم : وأما أنت فتحفظ عهدي ، أنت ونسلك من بعدك في أجيالهم '),
(14153, 'Genesis', 1, 17, 10, ' هذا هو عهدي الذي تحفظونه بيني وبينكم ، وبين نسلك من بعدك : يختن منكم كل ذكر '),
(14154, 'Genesis', 1, 17, 11, ' فتختنون في لحم غرلتكم ، فيكون علامة عهد بيني وبينكم '),
(14155, 'Genesis', 1, 17, 12, ' ابن ثمانية أيام يختن منكم كل ذكر في أجيالكم : وليد البيت ، والمبتاع بفضة من كل ابن غريب ليس من نسلك '),
(14156, 'Genesis', 1, 17, 13, ' يختن ختانا وليد بيتك والمبتاع بفضتك ، فيكون عهدي في لحمكم عهدا أبديا '),
(14157, 'Genesis', 1, 17, 14, ' وأما الذكر الأغلف الذي لا يختن في لحم غرلته فتقطع تلك النفس من شعبها . إنه قد نكث عهدي '),
(14158, 'Genesis', 1, 17, 15, ' وقال الله لإبراهيم : ساراي امرأتك لا تدعو اسمها ساراي ، بل اسمها سارة '),
(14159, 'Genesis', 1, 17, 16, ' وأباركها وأعطيك أيضا منها ابنا . أباركها فتكون أمما ، وملوك شعوب منها يكونون '),
(14160, 'Genesis', 1, 17, 17, ' فسقط إبراهيم على وجهه وضحك ، وقال في قلبه : هل يولد لابن مئة سنة ؟ وهل تلد سارة وهي بنت تسعين سنة '),
(14161, 'Genesis', 1, 17, 18, ' وقال إبراهيم لله : ليت إسماعيل يعيش أمامك '),
(14162, 'Genesis', 1, 17, 19, ' فقال الله : بل سارة امرأتك تلد لك ابنا وتدعو اسمه إسحاق . وأقيم عهدي معه عهدا أبديا لنسله من بعده '),
(14163, 'Genesis', 1, 17, 20, ' وأما إسماعيل فقد سمعت لك فيه . ها أنا أباركه وأثمره وأكثره كثيرا جدا . اثني عشر رئيسا يلد ، وأجعله أمة كبيرة '),
(14164, 'Genesis', 1, 17, 21, ' ولكن عهدي أقيمه مع إسحاق الذي تلده لك سارة في هذا الوقت في السنة الآتية '),
(14165, 'Genesis', 1, 17, 22, ' فلما فرغ من الكلام معه صعد الله عن إبراهيم '),
(14166, 'Genesis', 1, 17, 23, ' فأخذ إبراهيم إسماعيل ابنه ، وجميع ولدان بيته ، وجميع المبتاعين بفضته ، كل ذكر من أهل بيت إبراهيم ، وختن لحم غرلتهم في ذلك اليوم عينه كما كلمه الله '),
(14167, 'Genesis', 1, 17, 24, ' وكان إبراهيم ابن تسع وتسعين سنة حين ختن في لحم غرلته '),
(14168, 'Genesis', 1, 17, 25, ' وكان إسماعيل ابنه ابن ثلاث عشرة سنة حين ختن في لحم غرلته '),
(14169, 'Genesis', 1, 17, 26, ' في ذلك اليوم عينه ختن إبراهيم وإسماعيل ابنه '),
(14170, 'Genesis', 1, 17, 27, ' وكل رجال بيته ولدان البيت والمبتاعين بالفضة من ابن الغريب ختنوا معه '),
(14171, 'Genesis', 1, 18, 1, ' وظهر له الرب عند بلوطات ممرا وهو جالس في باب الخيمة وقت حر النهار '),
(14172, 'Genesis', 1, 18, 2, ' فرفع عينيه ونظر وإذا ثلاثة رجال واقفون لديه . فلما نظر ركض لاستقبالهم من باب الخيمة وسجد إلى الأرض '),
(14173, 'Genesis', 1, 18, 3, ' وقال : يا سيد ، إن كنت قد وجدت نعمة في عينيك فلا تتجاوز عبدك '),
(14174, 'Genesis', 1, 18, 4, ' ليؤخذ قليل ماء واغسلوا أرجلكم واتكئوا تحت الشجرة '),
(14175, 'Genesis', 1, 18, 5, ' فآخذ كسرة خبز ، فتسندون قلوبكم ثم تجتازون ، لأنكم قد مررتم على عبدكم . فقالوا : هكذا تفعل كما تكلمت '),
(14176, 'Genesis', 1, 18, 6, ' فأسرع إبراهيم إلى الخيمة إلى سارة ، وقال : أسرعي بثلاث كيلات دقيقا سميذا . اعجني واصنعي خبز ملة '),
(14177, 'Genesis', 1, 18, 7, ' ثم ركض إبراهيم إلى البقر وأخذ عجلا رخصا وجيدا وأعطاه للغلام فأسرع ليعمله '),
(14178, 'Genesis', 1, 18, 8, ' ثم أخذ زبدا ولبنا ، والعجل الذي عمله ، ووضعها قدامهم . وإذ كان هو واقفا لديهم تحت الشجرة أكلوا '),
(14179, 'Genesis', 1, 18, 9, ' وقالوا له : أين سارة امرأتك ؟ فقال : ها هي في الخيمة '),
(14180, 'Genesis', 1, 18, 10, ' فقال : إني أرجع إليك نحو زمان الحياة ويكون لسارة امرأتك ابن . وكانت سارة سامعة في باب الخيمة وهو وراءه '),
(14181, 'Genesis', 1, 18, 11, ' وكان إبراهيم وسارة شيخين متقدمين في الأيام ، وقد انقطع أن يكون لسارة عادة كالنساء '),
(14182, 'Genesis', 1, 18, 12, ' فضحكت سارة في باطنها قائلة : أبعد فنائي يكون لي تنعم ، وسيدي قد شاخ '),
(14183, 'Genesis', 1, 18, 13, ' فقال الرب لإبراهيم : لماذا ضحكت سارة قائلة : أفبالحقيقة ألد وأنا قد شخت '),
(14184, 'Genesis', 1, 18, 14, ' هل يستحيل على الرب شيء ؟ في الميعاد أرجع إليك نحو زمان الحياة ويكون لسارة ابن '),
(14185, 'Genesis', 1, 18, 15, ' فأنكرت سارة قائلة : لم أضحك . لأنها خافت . فقال : لا بل ضحكت '),
(14186, 'Genesis', 1, 18, 16, ' ثم قام الرجال من هناك وتطلعوا نحو سدوم . وكان إبراهيم ماشيا معهم ليشيعهم '),
(14187, 'Genesis', 1, 18, 17, ' فقال الرب : هل أخفي عن إبراهيم ما أنا فاعله '),
(14188, 'Genesis', 1, 18, 18, ' وإبراهيم يكون أمة كبيرة وقوية ، ويتبارك به جميع أمم الأرض '),
(14189, 'Genesis', 1, 18, 19, ' لأني عرفته لكي يوصي بنيه وبيته من بعده أن يحفظوا طريق الرب ، ليعملوا برا وعدلا ، لكي يأتي الرب لإبراهيم بما تكلم به '),
(14190, 'Genesis', 1, 18, 20, ' وقال الرب : إن صراخ سدوم وعمورة قد كثر ، وخطيتهم قد عظمت جدا '),
(14191, 'Genesis', 1, 18, 21, ' أنزل وأرى هل فعلوا بالتمام حسب صراخها الآتي إلي ، وإلا فأعلم '),
(14192, 'Genesis', 1, 18, 22, ' وانصرف الرجال من هناك وذهبوا نحو سدوم ، وأما إبراهيم فكان لم يزل قائما أمام الرب '),
(14193, 'Genesis', 1, 18, 23, ' فتقدم إبراهيم وقال : أفتهلك البار مع الأثيم '),
(14194, 'Genesis', 1, 18, 24, ' عسى أن يكون خمسون بارا في المدينة . أفتهلك المكان ولا تصفح عنه من أجل الخمسين بارا الذين فيه '),
(14195, 'Genesis', 1, 18, 25, ' حاشا لك أن تفعل مثل هذا الأمر ، أن تميت البار مع الأثيم ، فيكون البار كالأثيم . حاشا لك أديان كل الأرض لا يصنع عدلا '),
(14196, 'Genesis', 1, 18, 26, ' فقال الرب : إن وجدت في سدوم خمسين بارا في المدينة ، فإني أصفح عن المكان كله من أجلهم '),
(14197, 'Genesis', 1, 18, 27, ' فأجاب إبراهيم وقال : إني قد شرعت أكلم المولى وأنا تراب ورماد '),
(14198, 'Genesis', 1, 18, 28, ' ربما نقص الخمسون بارا خمسة . أتهلك كل المدينة بالخمسة ؟ فقال : لا أهلك إن وجدت هناك خمسة وأربعين '),
(14199, 'Genesis', 1, 18, 29, ' فعاد يكلمه أيضا وقال : عسى أن يوجد هناك أربعون . فقال : لا أفعل من أجل الأربعين '),
(14200, 'Genesis', 1, 18, 30, ' فقال : لايسخط المولى فأتكلم . عسى أن يوجد هناك ثلاثون . فقال : لا أفعل إن وجدت هناك ثلاثين '),
(14201, 'Genesis', 1, 18, 31, ' فقال : إني قد شرعت أكلم المولى . عسى أن يوجد هناك عشرون . فقال : لا أهلك من أجل العشرين '),
(14202, 'Genesis', 1, 18, 32, ' فقال : لا يسخط المولى فأتكلم هذه المرة فقط . عسى أن يوجد هناك عشرة . فقال : لا أهلك من أجل العشرة '),
(14203, 'Genesis', 1, 18, 33, ' وذهب الرب عندما فرغ من الكلام مع إبراهيم ، ورجع إبراهيم إلى مكانه '),
(14204, 'Genesis', 1, 19, 1, ' فجاء الملاكان إلى سدوم مساء ، وكان لوط جالسا في باب سدوم . فلما رآهما لوط قام لاستقبالهما ، وسجد بوجهه إلى الأرض '),
(14205, 'Genesis', 1, 19, 2, ' وقال : يا سيدي ، ميلا إلى بيت عبدكما وبيتا واغسلا أرجلكما ، ثم تبكران وتذهبان في طريقكما . فقالا : لا ، بل في الساحة نبيت '),
(14206, 'Genesis', 1, 19, 3, ' فألح عليهما جدا ، فمالا إليه ودخلا بيته ، فصنع لهما ضيافة وخبز فطيرا فأكلا '),
(14207, 'Genesis', 1, 19, 4, ' وقبلما اضطجعا أحاط بالبيت رجال المدينة ، رجال سدوم ، من الحدث إلى الشيخ ، كل الشعب من أقصاها '),
(14208, 'Genesis', 1, 19, 5, ' فنادوا لوطا وقالوا له : أين الرجلان اللذان دخلا إليك الليلة ؟ أخرجهما إلينا لنعرفهما '),
(14209, 'Genesis', 1, 19, 6, ' فخرج إليهم لوط إلى الباب وأغلق الباب وراءه '),
(14210, 'Genesis', 1, 19, 7, ' وقال : لا تفعلوا شرا يا إخوتي '),
(14211, 'Genesis', 1, 19, 8, ' هوذا لي ابنتان لم تعرفا رجلا . أخرجهما إليكم فافعلوا بهما كما يحسن في عيونكم . وأما هذان الرجلان فلا تفعلوا بهما شيئا ، لأنهما قد دخلا تحت ظل سقفي '),
(14212, 'Genesis', 1, 19, 9, ' فقالوا : ابعد إلى هناك . ثم قالوا : جاء هذا الإنسان ليتغرب ، وهو يحكم حكما . الآن نفعل بك شرا أكثر منهما . فألحوا على الرجل لوط جدا وتقدموا ليكسروا الباب '),
(14213, 'Genesis', 1, 19, 10, ' فمد الرجلان أيديهما وأدخلا لوطا إليهما إلى البيت وأغلقا الباب '),
(14214, 'Genesis', 1, 19, 11, ' وأما الرجال الذين على باب البيت فضرباهم بالعمى ، من الصغير إلى الكبير ، فعجزوا عن أن يجدوا الباب '),
(14215, 'Genesis', 1, 19, 12, ' وقال الرجلان للوط : من لك أيضا ههنا ؟ أصهارك وبنيك وبناتك وكل من لك في المدينة ، أخرج من المكان '),
(14216, 'Genesis', 1, 19, 13, ' لأننا مهلكان هذا المكان ، إذ قد عظم صراخهم أمام الرب ، فأرسلنا الرب لنهلكه '),
(14217, 'Genesis', 1, 19, 14, ' فخرج لوط وكلم أصهاره الآخذين بناته وقال : قوموا اخرجوا من هذا المكان ، لأن الرب مهلك المدينة . فكان كمازح في أعين أصهاره '),
(14218, 'Genesis', 1, 19, 15, ' ولما طلع الفجر كان الملاكان يعجلان لوطا قائلين : قم خذ امرأتك وابنتيك الموجودتين لئلا تهلك بإثم المدينة '),
(14219, 'Genesis', 1, 19, 16, ' ولما توانى ، أمسك الرجلان بيده وبيد امرأته وبيد ابنتيه ، لشفقة الرب عليه ، وأخرجاه ووضعاه خارج المدينة '),
(14220, 'Genesis', 1, 19, 17, ' وكان لما أخرجاهم إلى خارج أنه قال : اهرب لحياتك . لا تنظر إلى ورائك ، ولا تقف في كل الدائرة . اهرب إلى الجبل لئلا تهلك '),
(14221, 'Genesis', 1, 19, 18, ' فقال لهما لوط : لا يا سيد ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(14222, 'Genesis', 1, 19, 19, ' هوذا عبدك قد وجد نعمة في عينيك ، وعظمت لطفك الذي صنعت إلي باستبقاء نفسي ، وأنا لا أقدر أن أهرب إلى الجبل لعل الشر يدركني فأموت '),
(14223, 'Genesis', 1, 19, 20, ' هوذا المدينة هذه قريبة للهرب إليها وهي صغيرة . أهرب إلى هناك . أليست هي صغيرة ؟ فتحيا نفسي '),
(14224, 'Genesis', 1, 19, 21, ' فقال له : إني قد رفعت وجهك في هذا الأمر أيضا ، أن لا أقلب المدينة التي تكلمت عنها '),
(14225, 'Genesis', 1, 19, 22, ' أسرع اهرب إلى هناك لأني لا أستطيع أن أفعل شيئا حتى تجيء إلى هناك . لذلك دعي اسم المدينة صوغر '),
(14226, 'Genesis', 1, 19, 23, ' وإذ أشرقت الشمس على الأرض دخل لوط إلى صوغر '),
(14227, 'Genesis', 1, 19, 24, ' فأمطر الرب على سدوم وعمورة كبريتا ونارا من عند الرب من السماء '),
(14228, 'Genesis', 1, 19, 25, ' وقلب تلك المدن ، وكل الدائرة ، وجميع سكان المدن ، ونبات الأرض '),
(14229, 'Genesis', 1, 19, 26, ' ونظرت امرأته من ورائه فصارت عمود ملح '),
(14230, 'Genesis', 1, 19, 27, ' وبكر إبراهيم في الغد إلى المكان الذي وقف فيه أمام الرب '),
(14231, 'Genesis', 1, 19, 28, ' وتطلع نحو سدوم وعمورة ، ونحو كل أرض الدائرة ، ونظر وإذا دخان الأرض يصعد كدخان الأتون '),
(14232, 'Genesis', 1, 19, 29, ' وحدث لما أخرب الله مدن الدائرة أن الله ذكر إبراهيم ، وأرسل لوطا من وسط الانقلاب . حين قلب المدن التي سكن فيها لوط '),
(14233, 'Genesis', 1, 19, 30, ' وصعد لوط من صوغر وسكن في الجبل ، وابنتاه معه ، لأنه خاف أن يسكن في صوغر . فسكن في المغارة هو وابنتاه '),
(14234, 'Genesis', 1, 19, 31, ' وقالت البكر للصغيرة : أبونا قد شاخ ، وليس في الأرض رجل ليدخل علينا كعادة كل الأرض '),
(14235, 'Genesis', 1, 19, 32, ' هلم نسقي أبانا خمرا ونضطجع معه ، فنحيي من أبينا نسلا '),
(14236, 'Genesis', 1, 19, 33, ' فسقتا أباهما خمرا في تلك الليلة ، ودخلت البكر واضطجعت مع أبيها ، ولم يعلم باضطجاعها ولا بقيامها '),
(14237, 'Genesis', 1, 19, 34, ' وحدث في الغد أن البكر قالت للصغيرة : إني قد اضطجعت البارحة مع أبي . نسقيه خمرا الليلة أيضا فادخلي اضطجعي معه ، فنحيي من أبينا نسلا '),
(14238, 'Genesis', 1, 19, 35, ' فسقتا أباهما خمرا في تلك الليلة أيضا ، وقامت الصغيرة واضطجعت معه ، ولم يعلم باضطجاعها ولا بقيامها '),
(14239, 'Genesis', 1, 19, 36, ' فحبلت ابنتا لوط من أبيهما '),
(14240, 'Genesis', 1, 19, 37, ' فولدت البكر ابنا ودعت اسمه موآب ، وهو أبو الموآبيين إلى اليوم '),
(14241, 'Genesis', 1, 19, 38, ' والصغيرة أيضا ولدت ابنا ودعت اسمه بن عمي ، وهو أبو بني عمون إلى اليوم '),
(14242, 'Genesis', 1, 20, 1, ' وانتقل إبراهيم من هناك إلى أرض الجنوب ، وسكن بين قادش وشور ، وتغرب في جرار '),
(14243, 'Genesis', 1, 20, 2, ' وقال إبراهيم عن سارة امرأته : هي أختي . فأرسل أبيمالك ملك جرار وأخذ سارة '),
(14244, 'Genesis', 1, 20, 3, ' فجاء الله إلى أبيمالك في حلم الليل وقال له : ها أنت ميت من أجل المرأة التي أخذتها ، فإنها متزوجة ببعل '),
(14245, 'Genesis', 1, 20, 4, ' ولكن لم يكن أبيمالك قد اقترب إليها ، فقال : يا سيد ، أأمة بارة تقتل '),
(14246, 'Genesis', 1, 20, 5, ' ألم يقل هو لي : إنها أختي ، وهي أيضا نفسها قالت : هو أخي ؟ بسلامة قلبي ونقاوة يدي فعلت هذا '),
(14247, 'Genesis', 1, 20, 6, ' فقال له الله في الحلم : أنا أيضا علمت أنك بسلامة قلبك فعلت هذا . وأنا أيضا أمسكتك عن أن تخطئ إلي ، لذلك لم أدعك تمسها '),
(14248, 'Genesis', 1, 20, 7, ' فالآن رد امرأة الرجل ، فإنه نبي ، فيصلي لأجلك فتحيا . وإن كنت لست تردها ، فاعلم أنك موتا تموت ، أنت وكل من لك '),
(14249, 'Genesis', 1, 20, 8, ' فبكر أبيمالك في الغد ودعا جميع عبيده ، وتكلم بكل هذا الكلام في مسامعهم ، فخاف الرجال جدا '),
(14250, 'Genesis', 1, 20, 9, ' ثم دعا أبيمالك إبراهيم وقال له : ماذا فعلت بنا ؟ وبماذا أخطأت إليك حتى جلبت علي وعلى مملكتي خطية عظيمة ؟ أعمالا لا تعمل عملت بي '),
(14251, 'Genesis', 1, 20, 10, ' وقال أبيمالك لإبراهيم : ماذا رأيت حتى عملت هذا الشيء '),
(14252, 'Genesis', 1, 20, 11, ' فقال إبراهيم : إني قلت : ليس في هذا الموضع خوف الله البتة ، فيقتلونني لأجل امرأتي '),
(14253, 'Genesis', 1, 20, 12, ' وبالحقيقة أيضا هي أختي ابنة أبي ، غير أنها ليست ابنة أمي ، فصارت لي زوجة '),
(14254, 'Genesis', 1, 20, 13, ' وحدث لما أتاهني الله من بيت أبي أني قلت لها : هذا معروفك الذي تصنعين إلي : في كل مكان نأتي إليه قولي عني : هو أخي '),
(14255, 'Genesis', 1, 20, 14, ' فأخذ أبيمالك غنما وبقرا وعبيدا وإماء وأعطاها لإبراهيم ، ورد إليه سارة امرأته '),
(14256, 'Genesis', 1, 20, 15, ' وقال أبيمالك : هوذا أرضي قدامك . اسكن في ما حسن في عينيك '),
(14257, 'Genesis', 1, 20, 16, ' وقال لسارة : إني قد أعطيت أخاك ألفا من الفضة . ها هو لك غطاء عين من جهة كل ما عندك وعند كل واحد ، فأنصفت '),
(14258, 'Genesis', 1, 20, 17, ' فصلى إبراهيم إلى الله ، فشفى الله أبيمالك وامرأته وجواريه فولدن '),
(14259, 'Genesis', 1, 20, 18, ' لأن الرب كان قد أغلق كل رحم لبيت أبيمالك بسبب سارة امرأة إبراهيم '),
(14260, 'Genesis', 1, 21, 1, ' وافتقد الرب سارة كما قال ، وفعل الرب لسارة كما تكلم '),
(14261, 'Genesis', 1, 21, 2, ' فحبلت سارة وولدت لإبراهيم ابنا في شيخوخته ، في الوقت الذي تكلم الله عنه '),
(14262, 'Genesis', 1, 21, 3, ' ودعا إبراهيم اسم ابنه المولود له ، الذي ولدته له سارة إسحاق '),
(14263, 'Genesis', 1, 21, 4, ' وختن إبراهيم إسحاق ابنه وهو ابن ثمانية أيام كما أمره الله '),
(14264, 'Genesis', 1, 21, 5, ' وكان إبراهيم ابن مئة سنة حين ولد له إسحاق ابنه '),
(14265, 'Genesis', 1, 21, 6, ' وقالت سارة : قد صنع إلي الله ضحكا . كل من يسمع يضحك لي '),
(14266, 'Genesis', 1, 21, 7, ' وقالت : من قال لإبراهيم : سارة ترضع بنين ؟ حتى ولدت ابنا في شيخوخته '),
(14267, 'Genesis', 1, 21, 8, ' فكبر الولد وفطم . وصنع إبراهيم وليمة عظيمة يوم فطام إسحاق '),
(14268, 'Genesis', 1, 21, 9, ' ورأت سارة ابن هاجر المصرية الذي ولدته لإبراهيم يمزح '),
(14269, 'Genesis', 1, 21, 10, ' فقالت لإبراهيم : اطرد هذه الجارية وابنها ، لأن ابن هذه الجارية لا يرث مع ابني إسحاق '),
(14270, 'Genesis', 1, 21, 11, ' فقبح الكلام جدا في عيني إبراهيم لسبب ابنه '),
(14271, 'Genesis', 1, 21, 12, ' فقال الله لإبراهيم : لا يقبح في عينيك من أجل الغلام ومن أجل جاريتك . في كل ما تقول لك سارة اسمع لقولها ، لأنه بإسحاق يدعى لك نسل '),
(14272, 'Genesis', 1, 21, 13, ' وابن الجارية أيضا سأجعله أمة لأنه نسلك '),
(14273, 'Genesis', 1, 21, 14, ' فبكر إبراهيم صباحا وأخذ خبزا وقربة ماء وأعطاهما لهاجر ، واضعا إياهما على كتفها ، والولد ، وصرفها . فمضت وتاهت في برية بئر سبع '),
(14274, 'Genesis', 1, 21, 15, ' ولما فرغ الماء من القربة طرحت الولد تحت إحدى الأشجار '),
(14275, 'Genesis', 1, 21, 16, ' ومضت وجلست مقابله بعيدا نحو رمية قوس ، لأنها قالت : لاأنظر موت الولد . فجلست مقابله ورفعت صوتها وبكت '),
(14276, 'Genesis', 1, 21, 17, ' فسمع الله صوت الغلام ، ونادى ملاك الله هاجر من السماء وقال لها : ما لك يا هاجر ؟ لا تخافي ، لأن الله قد سمع لصوت الغلام حيث هو '),
(14277, 'Genesis', 1, 21, 18, ' قومي احملي الغلام وشدي يدك به ، لأني سأجعله أمة عظيمة '),
(14278, 'Genesis', 1, 21, 19, ' وفتح الله عينيها فأبصرت بئر ماء ، فذهبت وملأت القربة ماء وسقت الغلام '),
(14279, 'Genesis', 1, 21, 20, ' وكان الله مع الغلام فكبر ، وسكن في البرية ، وكان ينمو رامي قوس '),
(14280, 'Genesis', 1, 21, 21, ' وسكن في برية فاران ، وأخذت له أمه زوجة من أرض مصر '),
(14281, 'Genesis', 1, 21, 22, ' وحدث في ذلك الزمان أن أبيمالك وفيكول رئيس جيشه كلما إبراهيم قائلين : الله معك في كل ما أنت صانع '),
(14282, 'Genesis', 1, 21, 23, ' فالآن احلف لي بالله ههنا أنك لا تغدر بي ولا بنسلي وذريتي ، كالمعروف الذي صنعت إليك تصنع إلي وإلى الأرض التي تغربت فيها '),
(14283, 'Genesis', 1, 21, 24, ' فقال إبراهيم : أنا أحلف '),
(14284, 'Genesis', 1, 21, 25, ' وعاتب إبراهيم أبيمالك لسبب بئر الماء التي اغتصبها عبيد أبيمالك '),
(14285, 'Genesis', 1, 21, 26, ' فقال أبيمالك : لم أعلم من فعل هذا الأمر . أنت لم تخبرني ، ولا أنا سمعت سوى اليوم '),
(14286, 'Genesis', 1, 21, 27, ' فأخذ إبراهيم غنما وبقرا وأعطى أبيمالك ، فقطعا كلاهما ميثاقا '),
(14287, 'Genesis', 1, 21, 28, ' وأقام إبراهيم سبع نعاج من الغنم وحدها '),
(14288, 'Genesis', 1, 21, 29, ' فقال أبيمالك لإبراهيم : ما هي هذه السبع النعاج التي أقمتها وحدها '),
(14289, 'Genesis', 1, 21, 30, ' فقال : إنك سبع نعاج تأخذ من يدي ، لكي تكون لي شهادة بأني حفرت هذه البئر '),
(14290, 'Genesis', 1, 21, 31, ' لذلك دعا ذلك الموضع بئر سبع ، لأنهما هناك حلفا كلاهما '),
(14291, 'Genesis', 1, 21, 32, ' فقطعا ميثاقا في بئر سبع ، ثم قام أبيمالك وفيكول رئيس جيشه ورجعا إلى أرض الفلسطينيين '),
(14292, 'Genesis', 1, 21, 33, ' وغرس إبراهيم أثلا في بئر سبع ، ودعا هناك باسم الرب الإله السرمدي '),
(14293, 'Genesis', 1, 21, 34, ' وتغرب إبراهيم في أرض الفلسطينيين أياما كثيرة '),
(14294, 'Genesis', 1, 22, 1, ' وحدث بعد هذه الأمور أن الله امتحن إبراهيم ، فقال له : يا إبراهيم . فقال:هأنذا '),
(14295, 'Genesis', 1, 22, 2, ' فقال : خذ ابنك وحيدك ، الذي تحبه ، إسحاق ، واذهب إلى أرض المريا ، وأصعده هناك محرقة على أحد الجبال الذي أقول لك '),
(14296, 'Genesis', 1, 22, 3, ' فبكر إبراهيم صباحا وشد على حماره ، وأخذ اثنين من غلمانه معه ، وإسحاق ابنه ، وشقق حطبا لمحرقة ، وقام وذهب إلى الموضع الذي قال له الله '),
(14297, 'Genesis', 1, 22, 4, ' وفي اليوم الثالث رفع إبراهيم عينيه وأبصر الموضع من بعيد '),
(14298, 'Genesis', 1, 22, 5, ' فقال إبراهيم لغلاميه : اجلسا أنتما ههنا مع الحمار ، وأما أنا والغلام فنذهب إلى هناك ونسجد ، ثم نرجع إليكما '),
(14299, 'Genesis', 1, 22, 6, ' فأخذ إبراهيم حطب المحرقة ووضعه على إسحاق ابنه ، وأخذ بيده النار والسكين . فذهبا كلاهما معا '),
(14300, 'Genesis', 1, 22, 7, ' وكلم إسحاق إبراهيم أباه وقال : يا أبي . فقال : هأنذا يا ابني . فقال : هوذا النار والحطب ، ولكن أين الخروف للمحرقة '),
(14301, 'Genesis', 1, 22, 8, ' فقال إبراهيم : الله يرى له الخروف للمحرقة يا ابني . فذهبا كلاهما معا '),
(14302, 'Genesis', 1, 22, 9, ' فلما أتيا إلى الموضع الذي قال له الله ، بنى هناك إبراهيم المذبح ورتب الحطب وربط إسحاق ابنه ووضعه على المذبح فوق الحطب '),
(14303, 'Genesis', 1, 22, 10, ' ثم مد إبراهيم يده وأخذ السكين ليذبح ابنه '),
(14304, 'Genesis', 1, 22, 11, ' فناداه ملاك الرب من السماء وقال : إبراهيم إبراهيم . فقال : هأنذا '),
(14305, 'Genesis', 1, 22, 12, ' فقال : لا تمد يدك إلى الغلام ولا تفعل به شيئا ، لأني الآن علمت أنك خائف الله ، فلم تمسك ابنك وحيدك عني '),
(14306, 'Genesis', 1, 22, 13, ' فرفع إبراهيم عينيه ونظر وإذا كبش وراءه ممسكا في الغابة بقرنيه ، فذهب إبراهيم وأخذ الكبش وأصعده محرقة عوضا عن ابنه '),
(14307, 'Genesis', 1, 22, 14, ' فدعا إبراهيم اسم ذلك الموضع يهوه يرأه . حتى إنه يقال اليوم : في جبل الرب يرى '),
(14308, 'Genesis', 1, 22, 15, ' ونادى ملاك الرب إبراهيم ثانية من السماء '),
(14309, 'Genesis', 1, 22, 16, ' وقال : بذاتي أقسمت ، يقول الرب ، أني من أجل أنك فعلت هذا الأمر ، ولم تمسك ابنك وحيدك '),
(14310, 'Genesis', 1, 22, 17, ' أباركك مباركة ، وأكثر نسلك تكثيرا كنجوم السماء وكالرمل الذي على شاطئ البحر ، ويرث نسلك باب أعدائه '),
(14311, 'Genesis', 1, 22, 18, ' ويتبارك في نسلك جميع أمم الأرض ، من أجل أنك سمعت لقولي '),
(14312, 'Genesis', 1, 22, 19, ' ثم رجع إبراهيم إلى غلاميه ، فقاموا وذهبوا معا إلى بئر سبع . وسكن إبراهيم في بئر سبع '),
(14313, 'Genesis', 1, 22, 20, ' وحدث بعد هذه الأمور أن إبراهيم أخبر وقيل له : هوذا ملكة قد ولدت هي أيضا بنين لناحور أخيك '),
(14314, 'Genesis', 1, 22, 21, ' عوصا بكره ، وبوزا أخاه ، وقموئيل أبا أرام '),
(14315, 'Genesis', 1, 22, 22, ' وكاسد وحزوا وفلداش ويدلاف وبتوئيل '),
(14316, 'Genesis', 1, 22, 23, ' وولد بتوئيل رفقة . هؤلاء الثمانية ولدتهم ملكة لناحور أخي إبراهيم '),
(14317, 'Genesis', 1, 22, 24, ' وأما سريته ، واسمها رؤومة ، فولدت هي أيضا : طابح وجاحم وتاحش ومعكة '),
(14318, 'Genesis', 1, 23, 1, ' وكانت حياة سارة مئة وسبعا وعشرين سنة ، سني حياة سارة '),
(14319, 'Genesis', 1, 23, 2, ' وماتت سارة في قرية أربع ، التي هي حبرون ، في أرض كنعان . فأتى إبراهيم ليندب سارة ويبكي عليها '),
(14320, 'Genesis', 1, 23, 3, ' وقام إبراهيم من أمام ميته وكلم بني حث قائلا '),
(14321, 'Genesis', 1, 23, 4, ' أنا غريب ونزيل عندكم . أعطوني ملك قبر معكم لأدفن ميتي من أمامي '),
(14322, 'Genesis', 1, 23, 5, ' فأجاب بنو حث إبراهيم قائلين له '),
(14323, 'Genesis', 1, 23, 6, ' اسمعنا يا سيدي . أنت رئيس من الله بيننا . في أفضل قبورنا ادفن ميتك ، لا يمنع أحد منا قبره عنك حتى لا تدفن ميتك '),
(14324, 'Genesis', 1, 23, 7, ' فقام إبراهيم وسجد لشعب الأرض ، لبني حث '),
(14325, 'Genesis', 1, 23, 8, ' وكلمهم قائلا : إن كان في نفوسكم أن أدفن ميتي من أمامي ، فاسمعوني والتمسوا لي من عفرون بن صوحر '),
(14326, 'Genesis', 1, 23, 9, ' أن يعطيني مغارة المكفيلة التي له ، التي في طرف حقله . بثمن كامل يعطيني إياها في وسطكم ملك قبر '),
(14327, 'Genesis', 1, 23, 10, ' وكان عفرون جالسا بين بني حث ، فأجاب عفرون الحثي إبراهيم في مسامع بني حث ، لدى جميع الداخلين باب مدينته قائلا '),
(14328, 'Genesis', 1, 23, 11, ' لا يا سيدي ، اسمعني . الحقل وهبتك إياه ، والمغارة التي فيه لك وهبتها . لدى عيون بني شعبي وهبتك إياها . ادفن ميتك '),
(14329, 'Genesis', 1, 23, 12, ' فسجد إبراهيم أمام شعب الأرض '),
(14330, 'Genesis', 1, 23, 13, ' وكلم عفرون في مسامع شعب الأرض قائلا : بل إن كنت أنت إياه فليتك تسمعني . أعطيك ثمن الحقل . خذ مني فأدفن ميتي هناك '),
(14331, 'Genesis', 1, 23, 14, ' فأجاب عفرون إبراهيم قائلا له '),
(14332, 'Genesis', 1, 23, 15, ' يا سيدي ، اسمعني . أرض بأربع مئة شاقل فضة ، ما هي بيني وبينك ؟ فادفن ميتك '),
(14333, 'Genesis', 1, 23, 16, ' فسمع إبراهيم لعفرون ، ووزن إبراهيم لعفرون الفضة التي ذكرها في مسامع بني حث . أربع مئة شاقل فضة جائزة عند التجار '),
(14334, 'Genesis', 1, 23, 17, ' فوجب حقل عفرون الذي في المكفيلة التي أمام ممرا ، الحقل والمغارة التي فيه ، وجميع الشجر الذي في الحقل الذي في جميع حدوده حواليه '),
(14335, 'Genesis', 1, 23, 18, ' لإبراهيم ملكا لدى عيون بني حث ، بين جميع الداخلين باب مدينته '),
(14336, 'Genesis', 1, 23, 19, ' وبعد ذلك دفن إبراهيم سارة امرأته في مغارة حقل المكفيلة أمام ممرا ، التي هي حبرون ، في أرض كنعان '),
(14337, 'Genesis', 1, 23, 20, ' فوجب الحقل والمغارة التي فيه لإبراهيم ملك قبر من عند بني حث '),
(14338, 'Genesis', 1, 24, 1, ' وشاخ إبراهيم وتقدم في الأيام . وبارك الرب إبراهيم في كل شيء '),
(14339, 'Genesis', 1, 24, 2, ' وقال إبراهيم لعبده كبير بيته المستولي على كل ما كان له : ضع يدك تحت فخذي '),
(14340, 'Genesis', 1, 24, 3, ' فأستحلفك بالرب إله السماء وإله الأرض أن لا تأخذ زوجة لابني من بنات الكنعانيين الذين أنا ساكن بينهم '),
(14341, 'Genesis', 1, 24, 4, ' بل إلى أرضي وإلى عشيرتي تذهب وتأخذ زوجة لابني إسحاق '),
(14342, 'Genesis', 1, 24, 5, ' فقال له العبد : ربما لا تشاء المرأة أن تتبعني إلى هذه الأرض . هل أرجع بابنك إلى الأرض التي خرجت منها '),
(14343, 'Genesis', 1, 24, 6, ' فقال له إبراهيم : احترز من أن ترجع بابني إلى هناك '),
(14344, 'Genesis', 1, 24, 7, ' الرب إله السماء الذي أخذني من بيت أبي ومن أرض ميلادي ، والذي كلمني والذي أقسم لي قائلا : لنسلك أعطي هذه الأرض ، هو يرسل ملاكه أمامك ، فتأخذ زوجة لابني من هناك '),
(14345, 'Genesis', 1, 24, 8, ' وإن لم تشإ المرأة أن تتبعك ، تبرأت من حلفي هذا . أما ابني فلا ترجع به إلى هناك '),
(14346, 'Genesis', 1, 24, 9, ' فوضع العبد يده تحت فخذ إبراهيم مولاه ، وحلف له على هذا الأمر '),
(14347, 'Genesis', 1, 24, 10, ' ثم أخذ العبد عشرة جمال من جمال مولاه ، ومضى وجميع خيرات مولاه في يده . فقام وذهب إلى أرام النهرين إلى مدينة ناحور '),
(14348, 'Genesis', 1, 24, 11, ' وأناخ الجمال خارج المدينة عند بئر الماء وقت المساء ، وقت خروج المستقيات '),
(14349, 'Genesis', 1, 24, 12, ' وقال : أيها الرب إله سيدي إبراهيم ، يسر لي اليوم واصنع لطفا إلى سيدي إبراهيم '),
(14350, 'Genesis', 1, 24, 13, ' ها أنا واقف على عين الماء ، وبنات أهل المدينة خارجات ليستقين ماء '),
(14351, 'Genesis', 1, 24, 14, ' فليكن أن الفتاة التي أقول لها : أميلي جرتك لأشرب ، فتقول : اشرب وأنا أسقي جمالك أيضا ، هي التي عينتها لعبدك إسحاق . وبها أعلم أنك صنعت لطفا إلى سيدي '),
(14352, 'Genesis', 1, 24, 15, ' وإذ كان لم يفرغ بعد من الكلام ، إذا رفقة التي ولدت لبتوئيل ابن ملكة امرأة ناحور أخي إبراهيم ، خارجة وجرتها على كتفها '),
(14353, 'Genesis', 1, 24, 16, ' وكانت الفتاة حسنة المنظر جدا ، وعذراء لم يعرفها رجل . فنزلت إلى العين وملأت جرتها وطلعت '),
(14354, 'Genesis', 1, 24, 17, ' فركض العبد للقائها وقال : اسقيني قليل ماء من جرتك '),
(14355, 'Genesis', 1, 24, 18, ' فقالت : اشرب يا سيدي . وأسرعت وأنزلت جرتها على يدها وسقته '),
(14356, 'Genesis', 1, 24, 19, ' ولما فرغت من سقيه قالت : أستقي لجمالك أيضا حتى تفرغ من الشرب '),
(14357, 'Genesis', 1, 24, 20, ' فأسرعت وأفرغت جرتها في المسقاة ، وركضت أيضا إلى البئر لتستقي ، فاستقت لكل جماله '),
(14358, 'Genesis', 1, 24, 21, ' والرجل يتفرس فيها صامتا ليعلم : أأنجح الرب طريقه أم لا '),
(14359, 'Genesis', 1, 24, 22, ' وحدث عندما فرغت الجمال من الشرب أن الرجل أخذ خزامة ذهب وزنها نصف شاقل وسوارين على يديها وزنهما عشرة شواقل ذهب '),
(14360, 'Genesis', 1, 24, 23, ' وقال : بنت من أنت ؟ أخبريني : هل في بيت أبيك مكان لنا لنبيت '),
(14361, 'Genesis', 1, 24, 24, ' فقالت له : أنا بنت بتوئيل ابن ملكة الذي ولدته لناحور '),
(14362, 'Genesis', 1, 24, 25, ' وقالت له : عندنا تبن وعلف كثير ، ومكان لتبيتوا أيضا '),
(14363, 'Genesis', 1, 24, 26, ' فخر الرجل وسجد للرب '),
(14364, 'Genesis', 1, 24, 27, ' وقال : مبارك الرب إله سيدي إبراهيم الذي لم يمنع لطفه وحقه عن سيدي . إذ كنت أنا في الطريق ، هداني الرب إلى بيت إخوة سيدي '),
(14365, 'Genesis', 1, 24, 28, ' فركضت الفتاة وأخبرت بيت أمها بحسب هذه الأمور '),
(14366, 'Genesis', 1, 24, 29, ' وكان لرفقة أخ اسمه لابان ، فركض لابان إلى الرجل خارجا إلى العين '),
(14367, 'Genesis', 1, 24, 30, ' وحدث أنه إذ رأى الخزامة والسوارين على يدي أخته ، وإذ سمع كلام رفقة أخته قائلة : هكذا كلمني الرجل ، جاء إلى الرجل ، وإذا هو واقف عند الجمال على العين '),
(14368, 'Genesis', 1, 24, 31, ' فقال : ادخل يا مبارك الرب ، لماذا تقف خارجا وأنا قد هيأت البيت ومكانا للجمال '),
(14369, 'Genesis', 1, 24, 32, ' فدخل الرجل إلى البيت وحل عن الجمال ، فأعطى تبنا وعلفا للجمال ، وماء لغسل رجليه وأرجل الرجال الذين معه '),
(14370, 'Genesis', 1, 24, 33, ' ووضع قدامه ليأكل . فقال : لا آكل حتى أتكلم كلامي . فقال:تكلم '),
(14371, 'Genesis', 1, 24, 34, ' فقال : أنا عبد إبراهيم '),
(14372, 'Genesis', 1, 24, 35, ' والرب قد بارك مولاي جدا فصار عظيما ، وأعطاه غنما وبقرا وفضة وذهبا وعبيدا وإماء وجمالا وحميرا '),
(14373, 'Genesis', 1, 24, 36, ' وولدت سارة امرأة سيدي ابنا لسيدي بعد ما شاخت ، فقد أعطاه كل ما له '),
(14374, 'Genesis', 1, 24, 37, ' واستحلفني سيدي قائلا : لا تأخذ زوجة لابني من بنات الكنعانيين الذين أنا ساكن في أرضهم '),
(14375, 'Genesis', 1, 24, 38, ' بل إلى بيت أبي تذهب وإلى عشيرتي ، وتأخذ زوجة لابني '),
(14376, 'Genesis', 1, 24, 39, ' فقلت لسيدي : ربما لا تتبعني المرأة '),
(14377, 'Genesis', 1, 24, 40, ' فقال لي : إن الرب الذي سرت أمامه يرسل ملاكه معك وينجح طريقك ، فتأخذ زوجة لابني من عشيرتي ومن بيت أبي '),
(14378, 'Genesis', 1, 24, 41, ' حينئذ تتبرأ من حلفي حينما تجيء إلى عشيرتي . وإن لم يعطوك فتكون بريئا من حلفي '),
(14379, 'Genesis', 1, 24, 42, ' فجئت اليوم إلى العين ، وقلت : أيها الرب إله سيدي إبراهيم ، إن كنت تنجح طريقي الذي أنا سالك فيه '),
(14380, 'Genesis', 1, 24, 43, ' فها أنا واقف على عين الماء ، وليكن أن الفتاة التي تخرج لتستقي وأقول لها : اسقيني قليل ماء من جرتك '),
(14381, 'Genesis', 1, 24, 44, ' فتقول لي : اشرب أنت ، وأنا أستقي لجمالك أيضا ، هي المرأة التي عينها الرب لابن سيدي '),
(14382, 'Genesis', 1, 24, 45, ' وإذ كنت أنا لم أفرغ بعد من الكلام في قلبي ، إذا رفقة خارجة وجرتها على كتفها ، فنزلت إلى العين واستقت . فقلت لها : اسقيني '),
(14383, 'Genesis', 1, 24, 46, ' فأسرعت وأنزلت جرتها عنها وقالت : اشرب وأنا أسقي جمالك أيضا . فشربت ، وسقت الجمال أيضا '),
(14384, 'Genesis', 1, 24, 47, ' فسألتها وقلت : بنت من أنت ؟ فقالت : بنت بتوئيل بن ناحور الذي ولدته له ملكة . فوضعت الخزامة في أنفها والسوارين على يديها '),
(14385, 'Genesis', 1, 24, 48, ' وخررت وسجدت للرب ، وباركت الرب إله سيدي إبراهيم الذي هداني في طريق أمين لآخذ ابنة أخي سيدي لابنه '),
(14386, 'Genesis', 1, 24, 49, ' والآن إن كنتم تصنعون معروفا وأمانة إلى سيدي فأخبروني ، وإلا فأخبروني لأنصرف يمينا أو شمالا '),
(14387, 'Genesis', 1, 24, 50, ' فأجاب لابان وبتوئيل وقالا : من عند الرب خرج الأمر . لا نقدر أن نكلمك بشر أو خير '),
(14388, 'Genesis', 1, 24, 51, ' هوذا رفقة قدامك . خذها واذهب . فلتكن زوجة لابن سيدك ، كما تكلم الرب '),
(14389, 'Genesis', 1, 24, 52, ' وكان عندما سمع عبد إبراهيم كلامهم أنه سجد للرب إلى الأرض '),
(14390, 'Genesis', 1, 24, 53, ' وأخرج العبد آنية فضة وآنية ذهب وثيابا وأعطاها لرفقة ، وأعطى تحفا لأخيها ولأمها '),
(14391, 'Genesis', 1, 24, 54, ' فأكل وشرب هو والرجال الذين معه وباتوا . ثم قاموا صباحا فقال : اصرفوني إلى سيدي '),
(14392, 'Genesis', 1, 24, 55, ' فقال أخوها وأمها : لتمكث الفتاة عندنا أياما أو عشرة ، بعد ذلك تمضي '),
(14393, 'Genesis', 1, 24, 56, ' فقال لهم : لا تعوقوني والرب قد أنجح طريقي . اصرفوني لأذهب إلى سيدي '),
(14394, 'Genesis', 1, 24, 57, ' فقالوا : ندعو الفتاة ونسألها شفاها '),
(14395, 'Genesis', 1, 24, 58, ' فدعوا رفقة وقالوا لها : هل تذهبين مع هذا الرجل ؟ فقالت : أذهب '),
(14396, 'Genesis', 1, 24, 59, ' فصرفوا رفقة أختهم ومرضعتها وعبد إبراهيم ورجاله '),
(14397, 'Genesis', 1, 24, 60, ' وباركوا رفقة وقالوا لها : أنت أختنا . صيري ألوف ربوات ، وليرث نسلك باب مبغضيه '),
(14398, 'Genesis', 1, 24, 61, ' فقامت رفقة وفتياتها وركبن على الجمال وتبعن الرجل . فأخذ العبد رفقة ومضى '),
(14399, 'Genesis', 1, 24, 62, ' وكان إسحاق قد أتى من ورود بئر لحي رئي ، إذ كان ساكنا في أرض الجنوب '),
(14400, 'Genesis', 1, 24, 63, ' وخرج إسحاق ليتأمل في الحقل عند إقبال المساء ، فرفع عينيه ونظر وإذا جمال مقبلة '),
(14401, 'Genesis', 1, 24, 64, ' ورفعت رفقة عينيها فرأت إسحاق فنزلت عن الجمل '),
(14402, 'Genesis', 1, 24, 65, ' وقالت للعبد : من هذا الرجل الماشي في الحقل للقائنا ؟ فقال العبد : هو سيدي . فأخذت البرقع وتغطت '),
(14403, 'Genesis', 1, 24, 66, ' ثم حدث العبد إسحاق بكل الأمور التي صنع '),
(14404, 'Genesis', 1, 24, 67, ' فأدخلها إسحاق إلى خباء سارة أمه ، وأخذ رفقة فصارت له زوجة وأحبها . فتعزى إسحاق بعد موت أمه '),
(14405, 'Genesis', 1, 25, 1, ' وعاد إبراهيم فأخذ زوجة اسمها قطورة '),
(14406, 'Genesis', 1, 25, 2, ' فولدت له : زمران ويقشان ومدان ومديان ويشباق وشوحا '),
(14407, 'Genesis', 1, 25, 3, ' وولد يقشان : شبا وددان . وكان بنو ددان : أشوريم ولطوشيم ولأميم '),
(14408, 'Genesis', 1, 25, 4, ' وبنو مديان : عيفة وعفر وحنوك وأبيداع وألدعة . جميع هؤلاء بنو قطورة '),
(14409, 'Genesis', 1, 25, 5, ' وأعطى إبراهيم إسحاق كل ما كان له '),
(14410, 'Genesis', 1, 25, 6, ' وأما بنو السراري اللواتي كانت لإبراهيم فأعطاهم إبراهيم عطايا ، وصرفهم عن إسحاق ابنه شرقا إلى أرض المشرق ، وهو بعد حي '),
(14411, 'Genesis', 1, 25, 7, ' وهذه أيام سني حياة إبراهيم التي عاشها : مئة وخمس وسبعون سنة '),
(14412, 'Genesis', 1, 25, 8, ' وأسلم إبراهيم روحه ومات بشيبة صالحة ، شيخا وشبعان أياما ، وانضم إلى قومه '),
(14413, 'Genesis', 1, 25, 9, ' ودفنه إسحاق وإسماعيل ابناه في مغارة المكفيلة في حقل عفرون بن صوحر الحثي الذي أمام ممرا '),
(14414, 'Genesis', 1, 25, 10, ' الحقل الذي اشتراه إبراهيم من بني حث . هناك دفن إبراهيم وسارة امرأته '),
(14415, 'Genesis', 1, 25, 11, ' وكان بعد موت إبراهيم أن الله بارك إسحاق ابنه . وسكن إسحاق عند بئر لحي رئي '),
(14416, 'Genesis', 1, 25, 12, ' وهذه مواليد إسماعيل بن إبراهيم ، الذي ولدته هاجر المصرية جارية سارة لإبراهيم '),
(14417, 'Genesis', 1, 25, 13, ' وهذه أسماء بني إسماعيل بأسمائهم حسب مواليدهم : نبايوت بكر إسماعيل ، وقيدار ، وأدبئيل ومبسام '),
(14418, 'Genesis', 1, 25, 14, ' ومشماع ودومة ومسا '),
(14419, 'Genesis', 1, 25, 15, ' وحدار وتيما ويطور ونافيش وقدمة '),
(14420, 'Genesis', 1, 25, 16, ' هؤلاء هم بنو إسماعيل ، وهذه أسماؤهم بديارهم وحصونهم . اثنا عشر رئيسا حسب قبائلهم '),
(14421, 'Genesis', 1, 25, 17, ' وهذه سنو حياة إسماعيل : مئة وسبع وثلاثون سنة ، وأسلم روحه ومات وانضم إلى قومه '),
(14422, 'Genesis', 1, 25, 18, ' وسكنوا من حويلة إلى شور التي أمام مصر حينما تجيء نحو أشور . أمام جميع إخوته نزل '),
(14423, 'Genesis', 1, 25, 19, ' وهذه مواليد إسحاق بن إبراهيم : ولد إبراهيم إسحاق '),
(14424, 'Genesis', 1, 25, 20, ' وكان إسحاق ابن أربعين سنة لما اتخذ لنفسه زوجة ، رفقة بنت بتوئيل الأرامي ، أخت لابان الأرامي من فدان أرام '),
(14425, 'Genesis', 1, 25, 21, ' وصلى إسحاق إلى الرب لأجل امرأته لأنها كانت عاقرا ، فاستجاب له الرب ، فحبلت رفقة امرأته '),
(14426, 'Genesis', 1, 25, 22, ' وتزاحم الولدان في بطنها ، فقالت : إن كان هكذا فلماذا أنا ؟ فمضت لتسأل الرب '),
(14427, 'Genesis', 1, 25, 23, ' فقال لها الرب : في بطنك أمتان ، ومن أحشائك يفترق شعبان : شعب يقوى على شعب ، وكبير يستعبد لصغير '),
(14428, 'Genesis', 1, 25, 24, ' فلما كملت أيامها لتلد إذا في بطنها توأمان '),
(14429, 'Genesis', 1, 25, 25, ' فخرج ألأول أحمر ، كله كفروة شعر ، فدعوا اسمه عيسو '),
(14430, 'Genesis', 1, 25, 26, ' وبعد ذلك خرج أخوه ويده قابضة بعقب عيسو ، فدعي اسمه يعقوب . وكان إسحاق ابن ستين سنة لما ولدتهما '),
(14431, 'Genesis', 1, 25, 27, ' فكبر الغلامان ، وكان عيسو إنسانا يعرف الصيد ، إنسان البرية ، ويعقوب إنسانا كاملا يسكن الخيام '),
(14432, 'Genesis', 1, 25, 28, ' فأحب إسحاق عيسو لأن في فمه صيدا ، وأما رفقة فكانت تحب يعقوب '),
(14433, 'Genesis', 1, 25, 29, ' وطبخ يعقوب طبيخا ، فأتى عيسو من الحقل وهو قد أعيا '),
(14434, 'Genesis', 1, 25, 30, ' فقال عيسو ليعقوب : أطعمني من هذا الأحمر لأني قد أعييت . لذلك دعي اسمه أدوم '),
(14435, 'Genesis', 1, 25, 31, ' فقال يعقوب : بعني اليوم بكوريتك '),
(14436, 'Genesis', 1, 25, 32, ' فقال عيسو : ها أنا ماض إلى الموت ، فلماذا لي بكورية '),
(14437, 'Genesis', 1, 25, 33, ' فقال يعقوب : احلف لي اليوم . فحلف له ، فباع بكوريته ليعقوب '),
(14438, 'Genesis', 1, 25, 34, ' فأعطى يعقوب عيسو خبزا وطبيخ عدس ، فأكل وشرب وقام ومضى . فاحتقر عيسو البكورية '),
(14439, 'Genesis', 1, 26, 1, ' وكان في الأرض جوع غير الجوع الأول الذي كان في أيام إبراهيم ، فذهب إسحاق إلى أبيمالك ملك الفلسطينيين ، إلى جرار '),
(14440, 'Genesis', 1, 26, 2, ' وظهر له الرب وقال : لا تنزل إلى مصر . اسكن في الأرض التي أقول لك '),
(14441, 'Genesis', 1, 26, 3, ' تغرب في هذه الأرض فأكون معك وأباركك ، لأني لك ولنسلك أعطي جميع هذه البلاد ، وأفي بالقسم الذي أقسمت لإبراهيم أبيك '),
(14442, 'Genesis', 1, 26, 4, ' وأكثر نسلك كنجوم السماء ، وأعطي نسلك جميع هذه البلاد ، وتتبارك في نسلك جميع أمم الأرض '),
(14443, 'Genesis', 1, 26, 5, ' من أجل أن إبراهيم سمع لقولي وحفظ ما يحفظ لي : أوامري وفرائضي وشرائعي '),
(14444, 'Genesis', 1, 26, 6, ' فأقام إسحاق في جرار '),
(14445, 'Genesis', 1, 26, 7, ' وسأله أهل المكان عن امرأته ، فقال : هي أختي . لأنه خاف أن يقول : امرأتي لعل أهل المكان : يقتلونني من أجل رفقة لأنها كانت حسنة المنظر '),
(14446, 'Genesis', 1, 26, 8, ' وحدث إذ طالت له الأيام هناك أن أبيمالك ملك الفلسطينيين أشرف من الكوة ونظر ، وإذا إسحاق يلاعب رفقة امرأته '),
(14447, 'Genesis', 1, 26, 9, ' فدعا أبيمالك إسحاق وقال : إنما هي امرأتك فكيف قلت : هي أختي ؟ فقال له إسحاق : لأني قلت : لعلي أموت بسببها '),
(14448, 'Genesis', 1, 26, 10, ' فقال أبيمالك : ما هذا الذي صنعت بنا ؟ لولا قليل لاضطجع أحد الشعب مع امرأتك فجلبت علينا ذنبا '),
(14449, 'Genesis', 1, 26, 11, ' فأوصى أبيمالك جميع الشعب قائلا : الذي يمس هذا الرجل أو امرأته موتا يموت '),
(14450, 'Genesis', 1, 26, 12, ' وزرع إسحاق في تلك الأرض فأصاب في تلك السنة مئة ضعف ، وباركه الرب '),
(14451, 'Genesis', 1, 26, 13, ' فتعاظم الرجل وكان يتزايد في التعاظم حتى صار عظيما جدا '),
(14452, 'Genesis', 1, 26, 14, ' فكان له مواش من الغنم ومواش من البقر وعبيد كثيرون . فحسده الفلسطينيون '),
(14453, 'Genesis', 1, 26, 15, ' وجميع الآبار ، التي حفرها عبيد أبيه في أيام إبراهيم أبيه ، طمها الفلسطينيون وملأوها ترابا '),
(14454, 'Genesis', 1, 26, 16, ' وقال أبيمالك لإسحاق : اذهب من عندنا لأنك صرت أقوى منا جدا '),
(14455, 'Genesis', 1, 26, 17, ' فمضى إسحاق من هناك ، ونزل في وادي جرار وأقام هناك '),
(14456, 'Genesis', 1, 26, 18, ' فعاد إسحاق ونبش آبار الماء التي حفروها في أيام إبراهيم أبيه ، وطمها الفلسطينيون بعد موت أبيه ، ودعاها بأسماء كالأسماء التي دعاها بها أبوه '),
(14457, 'Genesis', 1, 26, 19, ' وحفر عبيد إسحاق في الوادي فوجدوا هناك بئر ماء حي '),
(14458, 'Genesis', 1, 26, 20, ' فخاصم رعاة جرار رعاة إسحاق قائلين : لنا الماء . فدعا اسم البئر عسق لأنهم نازعوه '),
(14459, 'Genesis', 1, 26, 21, ' ثم حفروا بئرا أخرى وتخاصموا عليها أيضا ، فدعا اسمها سطنة '),
(14460, 'Genesis', 1, 26, 22, ' ثم نقل من هناك وحفر بئرا أخرى ولم يتخاصموا عليها ، فدعا اسمها رحوبوت ، وقال : إنه الآن قد أرحب لنا الرب وأثمرنا في الأرض '),
(14461, 'Genesis', 1, 26, 23, ' ثم صعد من هناك إلى بئر سبع '),
(14462, 'Genesis', 1, 26, 24, ' فظهر له الرب في تلك الليلة وقال : أنا إله إبراهيم أبيك . لا تخف لأني معك ، وأباركك وأكثر نسلك من أجل إبراهيم عبدي '),
(14463, 'Genesis', 1, 26, 25, ' فبنى هناك مذبحا ودعا باسم الرب . ونصب هناك خيمته ، وحفر هناك عبيد إسحاق بئرا '),
(14464, 'Genesis', 1, 26, 26, ' وذهب إليه من جرار أبيمالك وأحزات من أصحابه وفيكول رئيس جيشه '),
(14465, 'Genesis', 1, 26, 27, ' فقال لهم إسحاق : ما بالكم أتيتم إلي وأنتم قد أبغضتموني وصرفتموني من عندكم '),
(14466, 'Genesis', 1, 26, 28, ' فقالوا : إننا قد رأينا أن الرب كان معك ، فقلنا : ليكن بيننا حلف ، بيننا وبينك ، ونقطع معك عهدا '),
(14467, 'Genesis', 1, 26, 29, ' أن لا تصنع بنا شرا ، كما لم نمسك وكما لم نصنع بك إلا خيرا وصرفناك بسلام . أنت الآن مبارك الرب '),
(14468, 'Genesis', 1, 26, 30, ' فصنع لهم ضيافة ، فأكلوا وشربوا '),
(14469, 'Genesis', 1, 26, 31, ' ثم بكروا في الغد وحلفوا بعضهم لبعض ، وصرفهم إسحاق . فمضوا من عنده بسلام '),
(14470, 'Genesis', 1, 26, 32, ' وحدث في ذلك اليوم أن عبيد إسحاق جاءوا وأخبروه عن البئر التي حفروا ، وقالوا له : قد وجدنا ماء '),
(14471, 'Genesis', 1, 26, 33, ' فدعاها شبعة ، لذلك اسم المدينة بئر سبع إلى هذا اليوم '),
(14472, 'Genesis', 1, 26, 34, ' ولما كان عيسو ابن أربعين سنة اتخذ زوجة : يهوديت ابنة بيري الحثي ، وبسمة ابنة إيلون الحثي '),
(14473, 'Genesis', 1, 26, 35, ' فكانتا مرارة نفس لإسحاق ورفقة '),
(14474, 'Genesis', 1, 27, 1, ' وحدث لما شاخ إسحاق وكلت عيناه عن النظر ، أنه دعا عيسو ابنه الأكبر وقال له : يا ابني . فقال له:هأنذا '),
(14475, 'Genesis', 1, 27, 2, ' فقال : إنني قد شخت ولست أعرف يوم وفاتي '),
(14476, 'Genesis', 1, 27, 3, ' فالآن خذ عدتك : جعبتك وقوسك ، واخرج إلى البرية وتصيد لي صيدا '),
(14477, 'Genesis', 1, 27, 4, ' واصنع لي أطعمة كما أحب ، وأتني بها لآكل حتى تباركك نفسي قبل أن أموت '),
(14478, 'Genesis', 1, 27, 5, ' وكانت رفقة سامعة إذ تكلم إسحاق مع عيسو ابنه . فذهب عيسو إلى البرية كي يصطاد صيدا ليأتي به '),
(14479, 'Genesis', 1, 27, 6, ' وأما رفقة فكلمت يعقوب ابنها قائلة : إني قد سمعت أباك يكلم عيسو أخاك قائلا '),
(14480, 'Genesis', 1, 27, 7, ' ائتني بصيد واصنع لي أطعمة لآكل وأباركك أمام الرب قبل وفاتي '),
(14481, 'Genesis', 1, 27, 8, ' فالآن يا ابني اسمع لقولي في ما أنا آمرك به '),
(14482, 'Genesis', 1, 27, 9, ' اذهب إلى الغنم وخذ لي من هناك جديين جيدين من المعزى ، فأصنعهما أطعمة لأبيك كما يحب '),
(14483, 'Genesis', 1, 27, 10, ' فتحضرها إلى أبيك ليأكل حتى يباركك قبل وفاته '),
(14484, 'Genesis', 1, 27, 11, ' فقال يعقوب لرفقة أمه : هوذا عيسو أخي رجل أشعر وأنا رجل أملس '),
(14485, 'Genesis', 1, 27, 12, ' ربما يجسني أبي فأكون في عينيه كمتهاون ، وأجلب على نفسي لعنة لا بركة '),
(14486, 'Genesis', 1, 27, 13, ' فقالت له أمه : لعنتك علي يا ابني . اسمع لقولي فقط واذهب خذ لي '),
(14487, 'Genesis', 1, 27, 14, ' فذهب وأخذ وأحضر لأمه ، فصنعت أمه أطعمة كما كان أبوه يحب '),
(14488, 'Genesis', 1, 27, 15, ' وأخذت رفقة ثياب عيسو ابنها الأكبر الفاخرة التي كانت عندها في البيت وألبست يعقوب ابنها الأصغر '),
(14489, 'Genesis', 1, 27, 16, ' وألبست يديه وملاسة عنقه جلود جديي المعزى '),
(14490, 'Genesis', 1, 27, 17, ' وأعطت الأطعمة والخبز التي صنعت في يد يعقوب ابنها '),
(14491, 'Genesis', 1, 27, 18, ' فدخل إلى أبيه وقال : يا أبي . فقال : هأنذا . من أنت يا ابني '),
(14492, 'Genesis', 1, 27, 19, ' فقال يعقوب لأبيه : أنا عيسو بكرك . قد فعلت كما كلمتني . قم اجلس وكل من صيدي لكي تباركني نفسك '),
(14493, 'Genesis', 1, 27, 20, ' فقال إسحاق لابنه : ما هذا الذي أسرعت لتجد يا ابني ؟ فقال : إن الرب إلهك قد يسر لي '),
(14494, 'Genesis', 1, 27, 21, ' فقال إسحاق ليعقوب : تقدم لأجسك يا ابني . أأنت هو ابني عيسو أم لا '),
(14495, 'Genesis', 1, 27, 22, ' فتقدم يعقوب إلى إسحاق أبيه ، فجسه وقال : الصوت صوت يعقوب ، ولكن اليدين يدا عيسو '),
(14496, 'Genesis', 1, 27, 23, ' ولم يعرفه لأن يديه كانتا مشعرتين كيدي عيسو أخيه ، فباركه '),
(14497, 'Genesis', 1, 27, 24, ' وقال : هل أنت هو ابني عيسو ؟ فقال : أنا هو '),
(14498, 'Genesis', 1, 27, 25, ' فقال : قدم لي لآكل من صيد ابني حتى تباركك نفسي . فقدم له فأكل ، وأحضر له خمرا فشرب '),
(14499, 'Genesis', 1, 27, 26, ' فقال له إسحاق أبوه : تقدم وقبلني يا ابني '),
(14500, 'Genesis', 1, 27, 27, ' فتقدم وقبله ، فشم رائحة ثيابه وباركه ، وقال : انظر رائحة ابني كرائحة حقل قد باركه الرب '),
(14501, 'Genesis', 1, 27, 28, ' فليعطك الله من ندى السماء ومن دسم الأرض . وكثرة حنطة وخمر '),
(14502, 'Genesis', 1, 27, 29, ' ليستعبد لك شعوب ، وتسجد لك قبائل . كن سيدا لإخوتك ، وليسجد لك بنو أمك . ليكن لاعنوك ملعونين ، ومباركوك مباركين '),
(14503, 'Genesis', 1, 27, 30, ' وحدث عندما فرغ إسحاق من بركة يعقوب ، ويعقوب قد خرج من لدن إسحاق أبيه ، أن عيسو أخاه أتى من صيده '),
(14504, 'Genesis', 1, 27, 31, ' فصنع هو أيضا أطعمة ودخل بها إلى أبيه وقال لأبيه : ليقم أبي ويأكل من صيد ابنه حتى تباركني نفسك '),
(14505, 'Genesis', 1, 27, 32, ' فقال له إسحاق أبوه : من أنت ؟ فقال : أنا ابنك بكرك عيسو '),
(14506, 'Genesis', 1, 27, 33, ' فارتعد إسحاق ارتعادا عظيما جدا وقال : فمن هو الذي اصطاد صيدا وأتى به إلي فأكلت من الكل قبل أن تجيء ، وباركته ؟ نعم ، ويكون مباركا '),
(14507, 'Genesis', 1, 27, 34, ' فعندما سمع عيسو كلام أبيه صرخ صرخة عظيمة ومرة جدا ، وقال لأبيه : باركني أنا أيضا يا أبي '),
(14508, 'Genesis', 1, 27, 35, ' فقال : قد جاء أخوك بمكر وأخذ بركتك '),
(14509, 'Genesis', 1, 27, 36, ' فقال : ألا إن اسمه دعي يعقوب ، فقد تعقبني الآن مرتين أخذ بكوريتي ، وهوذا الآن قد أخذ بركتي . ثم قال : أما أبقيت لي بركة '),
(14510, 'Genesis', 1, 27, 37, ' فأجاب إسحاق وقال لعيسو : إني قد جعلته سيدا لك ، ودفعت إليه جميع إخوته عبيدا ، وعضدته بحنطة وخمر . فماذا أصنع إليك يا ابني '),
(14511, 'Genesis', 1, 27, 38, ' فقال عيسو لأبيه : ألك بركة واحدة فقط يا أبي ؟ باركني أنا أيضا يا أبي . ورفع عيسو صوته وبكى '),
(14512, 'Genesis', 1, 27, 39, ' فأجاب إسحاق أبوه وقال له : هوذا بلا دسم الأرض يكون مسكنك ، وبلا ندى السماء من فوق '),
(14513, 'Genesis', 1, 27, 40, ' وبسيفك تعيش ، ولأخيك تستعبد ، ولكن يكون حينما تجمح أنك تكسر نيره عن عنقك '),
(14514, 'Genesis', 1, 27, 41, ' فحقد عيسو على يعقوب من أجل البركة التي باركه بها أبوه . وقال عيسو في قلبه : قربت أيام مناحة أبي ، فأقتل يعقوب أخي '),
(14515, 'Genesis', 1, 27, 42, ' فأخبرت رفقة بكلام عيسو ابنها الأكبر ، فأرسلت ودعت يعقوب ابنها الأصغر وقالت له : هوذا عيسو أخوك متسل من جهتك بأنه يقتلك '),
(14516, 'Genesis', 1, 27, 43, ' فالآن يا ابني اسمع لقولي ، وقم اهرب إلى أخي لابان إلى حاران '),
(14517, 'Genesis', 1, 27, 44, ' وأقم عنده أياما قليلة حتى يرتد سخط أخيك '),
(14518, 'Genesis', 1, 27, 45, ' حتى يرتد غضب أخيك عنك ، وينسى ما صنعت به . ثم أرسل فآخذك من هناك . لماذا أعدم اثنيكما في يوم واحد '),
(14519, 'Genesis', 1, 27, 46, ' وقالت رفقة لإسحاق : مللت حياتي من أجل بنات حث . إن كان يعقوب يأخذ زوجة من بنات حث مثل هؤلاء من بنات الأرض ، فلماذا لي حياة '),
(14520, 'Genesis', 1, 28, 1, ' فدعا إسحاق يعقوب وباركه ، وأوصاه وقال له : لا تأخذ زوجة من بنات كنعان '),
(14521, 'Genesis', 1, 28, 2, ' قم اذهب إلى فدان أرام ، إلى بيت بتوئيل أبي أمك ، وخذ لنفسك زوجة من هناك ، من بنات لابان أخي أمك '),
(14522, 'Genesis', 1, 28, 3, ' والله القدير يباركك ، ويجعلك مثمرا ، ويكثرك فتكون جمهورا من الشعوب '),
(14523, 'Genesis', 1, 28, 4, ' ويعطيك بركة إبراهيم لك ولنسلك معك ، لترث أرض غربتك التي أعطاها الله لإبراهيم '),
(14524, 'Genesis', 1, 28, 5, ' فصرف إسحاق يعقوب فذهب إلى فدان أرام ، إلى لابان بن بتوئيل الأرامي ، أخي رفقة أم يعقوب وعيسو '),
(14525, 'Genesis', 1, 28, 6, ' فلما رأى عيسو أن إسحاق بارك يعقوب وأرسله إلى فدان أرام ليأخذ لنفسه من هناك زوجة ، إذ باركه وأوصاه قائلا : لا تأخذ زوجة من بنات كنعان '),
(14526, 'Genesis', 1, 28, 7, ' وأن يعقوب سمع لأبيه وأمه وذهب إلى فدان أرام '),
(14527, 'Genesis', 1, 28, 8, ' رأى عيسو أن بنات كنعان شريرات في عيني إسحاق أبيه '),
(14528, 'Genesis', 1, 28, 9, ' فذهب عيسو إلى إسماعيل وأخذ محلة بنت إسماعيل بن إبراهيم ، أخت نبايوت ، زوجة له على نسائه '),
(14529, 'Genesis', 1, 28, 10, ' فخرج يعقوب من بئر سبع وذهب نحو حاران '),
(14530, 'Genesis', 1, 28, 11, ' وصادف مكانا وبات هناك لأن الشمس كانت قد غابت ، وأخذ من حجارة المكان ووضعه تحت رأسه ، فاضطجع في ذلك المكان '),
(14531, 'Genesis', 1, 28, 12, ' ورأى حلما ، وإذا سلم منصوبة على الأرض ورأسها يمس السماء ، وهوذا ملائكة الله صاعدة ونازلة عليها '),
(14532, 'Genesis', 1, 28, 13, ' وهوذا الرب واقف عليها ، فقال : أنا الرب إله إبراهيم أبيك وإله إسحاق . الأرض التي أنت مضطجع عليها أعطيها لك ولنسلك '),
(14533, 'Genesis', 1, 28, 14, ' ويكون نسلك كتراب الأرض ، وتمتد غربا وشرقا وشمالا وجنوبا ، ويتبارك فيك وفي نسلك جميع قبائل الأرض '),
(14534, 'Genesis', 1, 28, 15, ' وها أنا معك ، وأحفظك حيثما تذهب ، وأردك إلى هذه الأرض ، لأني لا أتركك حتى أفعل ما كلمتك به '),
(14535, 'Genesis', 1, 28, 16, ' فاستيقظ يعقوب من نومه وقال : حقا إن الرب في هذا المكان وأنا لم أعلم '),
(14536, 'Genesis', 1, 28, 17, ' وخاف وقال : ما أرهب هذا المكان ما هذا إلا بيت الله ، وهذا باب السماء '),
(14537, 'Genesis', 1, 28, 18, ' وبكر يعقوب في الصباح وأخذ الحجر الذي وضعه تحت رأسه وأقامه عمودا ، وصب زيتا على رأسه '),
(14538, 'Genesis', 1, 28, 19, ' ودعا اسم ذلك المكان بيت إيل ، ولكن اسم المدينة أولا كان لوز '),
(14539, 'Genesis', 1, 28, 20, ' ونذر يعقوب نذرا قائلا : إن كان الله معي ، وحفظني في هذا الطريق الذي أنا سائر فيه ، وأعطاني خبزا لآكل وثيابا لألبس '),
(14540, 'Genesis', 1, 28, 21, ' ورجعت بسلام إلى بيت أبي ، يكون الرب لي إلها '),
(14541, 'Genesis', 1, 28, 22, ' وهذا الحجر الذي أقمته عمودا يكون بيت الله ، وكل ما تعطيني فإني أعشره لك '),
(14542, 'Genesis', 1, 29, 1, ' ثم رفع يعقوب رجليه وذهب إلى أرض بني المشرق '),
(14543, 'Genesis', 1, 29, 2, ' ونظر وإذا في الحقل بئر وهناك ثلاثة قطعان غنم رابضة عندها ، لأنهم كانوا من تلك البئر يسقون القطعان ، والحجر على فم البئر كان كبيرا '),
(14544, 'Genesis', 1, 29, 3, ' فكان يجتمع إلى هناك جميع القطعان فيدحرجون الحجر عن فم البئر ويسقون الغنم ، ثم يردون الحجر على فم البئر إلى مكانه '),
(14545, 'Genesis', 1, 29, 4, ' فقال لهم يعقوب : يا إخوتي ، من أين أنتم ؟ فقالوا : نحن من حاران '),
(14546, 'Genesis', 1, 29, 5, ' فقال لهم : هل تعرفون لابان ابن ناحور ؟ فقالوا : نعرفه '),
(14547, 'Genesis', 1, 35, 11, ' وقال له الله : أنا الله القدير . أثمر واكثر . أمة وجماعة أمم تكون منك ، وملوك سيخرجون من صلبك '),
(14548, 'Genesis', 1, 35, 12, ' والأرض التي أعطيت إبراهيم وإسحاق ، لك أعطيها ، ولنسلك من بعدك أعطي الأرض '),
(14549, 'Genesis', 1, 35, 13, ' ثم صعد الله عنه في المكان الذي فيه تكلم معه '),
(14550, 'Genesis', 1, 35, 14, ' فنصب يعقوب عمودا في المكان الذي فيه تكلم معه ، عمودا من حجر ، وسكب عليه سكيبا ، وصب عليه زيتا '),
(14551, 'Genesis', 1, 35, 15, ' ودعا يعقوب اسم المكان الذي فيه تكلم الله معه بيت إيل '),
(14552, 'Genesis', 1, 35, 16, ' ثم رحلوا من بيت إيل . ولما كان مسافة من الأرض بعد حتى يأتوا إلى أفراتة ، ولدت راحيل وتعسرت ولادتها '),
(14553, 'Genesis', 1, 35, 17, ' وحدث حين تعسرت ولادتها أن القابلة قالت لها : لا تخافي ، لأن هذا أيضا ابن لك '),
(14554, 'Genesis', 1, 35, 18, ' وكان عند خروج نفسها ، لأنها ماتت ، أنها دعت اسمه بن أوني . وأما أبوه فدعاه بنيامين '),
(14555, 'Genesis', 1, 35, 19, ' فماتت راحيل ودفنت في طريق أفراتة ، التي هي بيت لحم '),
(14556, 'Genesis', 1, 35, 20, ' فنصب يعقوب عمودا على قبرها ، وهو عمود قبر راحيل إلى اليوم '),
(14557, 'Genesis', 1, 35, 21, ' ثم رحل إسرائيل ونصب خيمته وراء مجدل عدر '),
(14558, 'Genesis', 1, 35, 22, ' وحدث إذ كان إسرائيل ساكنا في تلك الأرض ، أن رأوبين ذهب واضطجع مع بلهة سرية أبيه ، وسمع إسرائيل وكان بنو يعقوب اثني عشر '),
(14559, 'Genesis', 1, 35, 23, ' بنو ليئة : رأوبين بكر يعقوب ، وشمعون ولاوي ويهوذا ويساكر وزبولون '),
(14560, 'Genesis', 1, 35, 24, ' وابنا راحيل : يوسف وبنيامين '),
(14561, 'Genesis', 1, 35, 25, ' وابنا بلهة جارية راحيل : دان ونفتالي '),
(14562, 'Genesis', 1, 35, 26, ' وابنا زلفة جارية ليئة : جاد وأشير . هؤلاء بنو يعقوب الذين ولدوا له في فدان أرام '),
(14563, 'Genesis', 1, 35, 27, ' وجاء يعقوب إلى إسحاق أبيه إلى ممرا ، قرية أربع ، التي هي حبرون ، حيث تغرب إبراهيم وإسحاق '),
(14564, 'Genesis', 1, 35, 28, ' وكانت أيام إسحاق مئة وثمانين سنة '),
(14565, 'Genesis', 1, 35, 29, ' فأسلم إسحاق روحه ومات وانضم إلى قومه ، شيخا وشبعان أياما . ودفنه عيسو ويعقوب ابناه '),
(14566, 'Genesis', 1, 36, 1, ' وهذه مواليد عيسو ، الذي هو أدوم '),
(14567, 'Genesis', 1, 36, 2, ' أخذ عيسو نساءه من بنات كنعان : عدا بنت إيلون الحثي ، وأهوليبامة بنت عنى بنت صبعون الحوي '),
(14568, 'Genesis', 1, 36, 3, ' وبسمة بنت إسماعيل أخت نبايوت '),
(14569, 'Genesis', 1, 36, 4, ' فولدت عدا لعيسو أليفاز ، وولدت بسمة رعوئيل '),
(14570, 'Genesis', 1, 36, 5, ' وولدت أهوليبامة : يعوش ويعلام وقورح . هؤلاء بنو عيسو الذين ولدوا له في أرض كنعان '),
(14571, 'Genesis', 1, 36, 6, ' ثم أخذ عيسو نساءه وبنيه وبناته وجميع نفوس بيته ومواشيه وكل بهائمه وكل مقتناه الذي اقتنى في أرض كنعان ، ومضى إلى أرض أخرى من وجه يعقوب أخيه '),
(14572, 'Genesis', 1, 36, 7, ' لأن أملاكهما كانت كثيرة على السكنى معا ، ولم تستطع أرض غربتهما أن تحملهما من أجل مواشيهما '),
(14573, 'Genesis', 1, 36, 8, ' فسكن عيسو في جبل سعير . وعيسو هو أدوم '),
(14574, 'Genesis', 1, 36, 9, ' وهذه مواليد عيسو أبي أدوم في جبل سعير '),
(14575, 'Genesis', 1, 36, 10, ' هذه أسماء بني عيسو : أليفاز ابن عدا امرأة عيسو ، ورعوئيل ابن بسمة امرأة عيسو '),
(14576, 'Genesis', 1, 36, 11, ' وكان بنو أليفاز : تيمان وأومار وصفوا وجعثام وقناز '),
(14577, 'Genesis', 1, 36, 12, ' وكانت تمناع سرية لأليفاز بن عيسو ، فولدت لأليفاز عماليق . هؤلاء بنو عدا امرأة عيسو '),
(14578, 'Genesis', 1, 36, 13, ' وهؤلاء بنو رعوئيل : نحث وزارح وشمة ومزة . هؤلاء كانوا بني بسمة امرأة عيسو '),
(14579, 'Genesis', 1, 36, 14, ' وهؤلاء كانوا بني أهوليبامة بنت عنى بنت صبعون امرأة عيسو ، ولدت لعيسو : يعوش ويعلام وقورح '),
(14580, 'Genesis', 1, 36, 15, ' هؤلاء أمراء بني عيسو : بنو أليفاز بكر عيسو : أمير تيمان وأمير أومار وأمير صفو وأمير قناز '),
(14581, 'Genesis', 1, 36, 16, ' وأمير قورح وأمير جعثام وأمير عماليق . هؤلاء أمراء أليفاز في أرض أدوم . هؤلاء بنو عدا '),
(14582, 'Genesis', 1, 36, 17, ' وهؤلاء بنو رعوئيل بن عيسو : أمير نحث وأمير زارح وأمير شمة وأمير مزة . هؤلاء أمراء رعوئيل في أرض أدوم . هؤلاء بنو بسمة امرأة عيسو '),
(14583, 'Genesis', 1, 36, 18, ' وهؤلاء بنو أهوليبامة امرأة عيسو : أمير يعوش وأمير يعلام وأمير قورح . هؤلاء أمراء أهوليبامة بنت عنى امرأة عيسو '),
(14584, 'Genesis', 1, 36, 19, ' هؤلاء بنو عيسو الذي هو أدوم ، وهؤلاء أمراؤهم '),
(14585, 'Genesis', 1, 36, 20, ' هؤلاء بنو سعير الحوري سكان الأرض : لوطان وشوبال وصبعون وعنى '),
(14586, 'Genesis', 1, 36, 21, ' وديشون وإيصر وديشان . هؤلاء أمراء الحوريين بنو سعير في أرض أدوم '),
(14587, 'Genesis', 1, 36, 22, ' وكان ابنا لوطان : حوري وهيمام . وكانت تمناع أخت لوطان '),
(14588, 'Genesis', 1, 36, 23, ' وهؤلاء بنو شوبال : علوان ومناحة وعيبال وشفو وأونام '),
(14589, 'Genesis', 1, 36, 24, ' وهذان ابنا صبعون : أية وعنى . هذا هو عنى الذي وجد الحمائم في البرية إذ كان يرعى حمير صبعون أبيه '),
(14590, 'Genesis', 1, 36, 25, ' وهذا ابن عنى : ديشون . وأهوليبامة هي بنت عنى '),
(14591, 'Genesis', 1, 36, 26, ' وهؤلاء بنو ديشان : حمدان وأشبان ويثران وكران '),
(14592, 'Genesis', 1, 36, 27, ' هؤلاء بنو إيصر : بلهان وزعوان وعقان '),
(14593, 'Genesis', 1, 36, 28, ' هذان ابنا ديشان : عوص وأران '),
(14594, 'Genesis', 1, 36, 29, ' هؤلاء أمراء الحوريين : أمير لوطان وأمير شوبال وأمير صبعون وأمير عنى '),
(14595, 'Genesis', 1, 36, 30, ' وأمير ديشون وأمير إيصر وأمير ديشان . هؤلاء أمراء الحوريين بأمرائهم في أرض سعير '),
(14596, 'Genesis', 1, 36, 31, ' وهؤلاء هم الملوك الذين ملكوا في أرض أدوم ، قبلما ملك ملك لبني إسرائيل '),
(14597, 'Genesis', 1, 36, 32, ' ملك في أدوم بالع بن بعور ، وكان اسم مدينته دنهابة '),
(14598, 'Genesis', 1, 36, 33, ' ومات بالع ، فملك مكانه يوباب بن زارح من بصرة '),
(14599, 'Genesis', 1, 36, 34, ' ومات يوباب ، فملك مكانه حوشام من أرض التيماني '),
(14600, 'Genesis', 1, 36, 35, ' ومات حوشام ، فملك مكانه هداد بن بداد الذي كسر مديان في بلاد موآب ، وكان اسم مدينته عويت '),
(14601, 'Genesis', 1, 36, 36, ' ومات هداد ، فملك مكانه سملة من مسريقة '),
(14602, 'Genesis', 1, 36, 37, ' ومات سملة ، فملك مكانه شأول من رحوبوت النهر '),
(14603, 'Genesis', 1, 36, 38, ' ومات شأول ، فملك مكانه بعل حانان بن عكبور '),
(14604, 'Genesis', 1, 36, 39, ' ومات بعل حانان بن عكبور ، فملك مكانه هدار وكان اسم مدينته فاعو ، واسم امرأته مهيطبئيل بنت مطرد بنت ماء ذهب '),
(14605, 'Genesis', 1, 36, 40, ' وهذه أسماء أمراء عيسو ، حسب قبائلهم وأماكنهم بأسمائهم : أمير تمناع وأمير علوة وأمير يتيت '),
(14606, 'Genesis', 1, 36, 41, ' وأمير أهوليبامة وأمير إيلة وأمير فينون '),
(14607, 'Genesis', 1, 36, 42, ' وأمير قناز وأمير تيمان وأمير مبصار '),
(14608, 'Genesis', 1, 36, 43, ' وأمير مجديئيل وأمير عيرام . هؤلاء أمراء أدوم حسب مساكنهم في أرض ملكهم . هذا هو عيسو أبو أدوم '),
(14609, 'Genesis', 1, 37, 1, ' وسكن يعقوب في أرض غربة أبيه ، في أرض كنعان '),
(14610, 'Genesis', 1, 37, 2, ' هذه مواليد يعقوب : يوسف إذ كان ابن سبع عشرة سنة ، كان يرعى مع إخوته الغنم وهو غلام عند بني بلهة وبني زلفة امرأتي أبيه ، وأتى يوسف بنميمتهم الرديئة إلى أبيهم '),
(14611, 'Genesis', 1, 37, 3, ' وأما إسرائيل فأحب يوسف أكثر من سائر بنيه لأنه ابن شيخوخته ، فصنع له قميصا ملونا '),
(14612, 'Genesis', 1, 37, 4, ' فلما رأى إخوته أن أباهم أحبه أكثر من جميع إخوته أبغضوه ، ولم يستطيعوا أن يكلموه بسلام '),
(14613, 'Genesis', 1, 37, 5, ' وحلم يوسف حلما وأخبر إخوته ، فازدادوا أيضا بغضا له '),
(14614, 'Genesis', 1, 37, 6, ' فقال لهم : اسمعوا هذا الحلم الذي حلمت '),
(14615, 'Genesis', 1, 37, 7, ' فها نحن حازمون حزما في الحقل ، وإذا حزمتي قامت وانتصبت ، فاحتاطت حزمكم وسجدت لحزمتي '),
(14616, 'Genesis', 1, 37, 8, ' فقال له إخوته : ألعلك تملك علينا ملكا أم تتسلط علينا تسلطا ؟ وازدادوا أيضا بغضا له من أجل أحلامه ومن أجل كلامه '),
(14617, 'Genesis', 1, 37, 9, ' ثم حلم أيضا حلما آخر وقصه على إخوته ، فقال : إني قد حلمت حلما أيضا ، وإذا الشمس والقمر وأحد عشر كوكبا ساجدة لي '),
(14618, 'Genesis', 1, 37, 10, ' وقصه على أبيه وعلى إخوته ، فانتهره أبوه وقال له : ما هذا الحلم الذي حلمت ؟ هل نأتي أنا وأمك وإخوتك لنسجد لك إلى الأرض '),
(14619, 'Genesis', 1, 29, 6, ' فقال لهم : هل له سلامة ؟ فقالوا : له سلامة . وهوذا راحيل ابنته آتية مع الغنم '),
(14620, 'Genesis', 1, 29, 7, ' فقال : هوذا النهار بعد طويل . ليس وقت اجتماع المواشي . اسقوا الغنم واذهبوا ارعوا '),
(14621, 'Genesis', 1, 29, 8, ' فقالوا : لا نقدر حتى تجتمع جميع القطعان ويدحرجوا الحجر عن فم البئر ، ثم نسقي الغنم '),
(14622, 'Genesis', 1, 29, 9, ' وإذ هو بعد يتكلم معهم أتت راحيل مع غنم أبيها ، لأنها كانت ترعى '),
(14623, 'Genesis', 1, 29, 10, ' فكان لما أبصر يعقوب راحيل بنت لابان خاله ، وغنم لابان خاله ، أن يعقوب تقدم ودحرج الحجر عن فم البئر وسقى غنم لابان خاله '),
(14624, 'Genesis', 1, 29, 11, ' وقبل يعقوب راحيل ورفع صوته وبكى '),
(14625, 'Genesis', 1, 29, 12, ' وأخبر يعقوب راحيل أنه أخو أبيها ، وأنه ابن رفقة ، فركضت وأخبرت أباها '),
(14626, 'Genesis', 1, 29, 13, ' فكان حين سمع لابان خبر يعقوب ابن أخته أنه ركض للقائه وعانقه وقبله وأتى به إلى بيته . فحدث لابان بجميع هذه الأمور '),
(14627, 'Genesis', 1, 29, 14, ' فقال له لابان : إنما أنت عظمي ولحمي . فأقام عنده شهرا من الزمان '),
(14628, 'Genesis', 1, 29, 15, ' ثم قال لابان ليعقوب : ألأنك أخي تخدمني مجانا ؟ أخبرني ما أجرتك '),
(14629, 'Genesis', 1, 29, 16, ' وكان للابان ابنتان ، اسم الكبرى ليئة واسم الصغرى راحيل '),
(14630, 'Genesis', 1, 29, 17, ' وكانت عينا ليئة ضعيفتين ، وأما راحيل فكانت حسنة الصورة وحسنة المنظر '),
(14631, 'Genesis', 1, 29, 18, ' وأحب يعقوب راحيل ، فقال : أخدمك سبع سنين براحيل ابنتك الصغرى '),
(14632, 'Genesis', 1, 29, 19, ' فقال لابان : أن أعطيك إياها أحسن من أن أعطيها لرجل آخر . أقم عندي '),
(14633, 'Genesis', 1, 29, 20, ' فخدم يعقوب براحيل سبع سنين ، وكانت في عينيه كأيام قليلة بسبب محبته لها '),
(14634, 'Genesis', 1, 29, 21, ' ثم قال يعقوب للابان : أعطني امرأتي لأن أيامي قد كملت ، فأدخل عليها '),
(14635, 'Genesis', 1, 29, 22, ' فجمع لابان جميع أهل المكان وصنع وليمة '),
(14636, 'Genesis', 1, 29, 23, ' وكان في المساء أنه أخذ ليئة ابنته وأتى بها إليه ، فدخل عليها '),
(14637, 'Genesis', 1, 29, 24, ' وأعطى لابان زلفة جاريته لليئة ابنته جارية '),
(14638, 'Genesis', 1, 29, 25, ' وفي الصباح إذا هي ليئة ، فقال للابان : ما هذا الذي صنعت بي ؟ أليس براحيل خدمت عندك ؟ فلماذا خدعتني '),
(14639, 'Genesis', 1, 29, 26, ' فقال لابان : لا يفعل هكذا في مكاننا أن تعطى الصغيرة قبل البكر '),
(14640, 'Genesis', 1, 29, 27, ' أكمل أسبوع هذه ، فنعطيك تلك أيضا ، بالخدمة التي تخدمني أيضا سبع سنين أخر '),
(14641, 'Genesis', 1, 29, 28, ' ففعل يعقوب هكذا . فأكمل أسبوع هذه ، فأعطاه راحيل ابنته زوجة له '),
(14642, 'Genesis', 1, 29, 29, ' وأعطى لابان راحيل ابنته بلهة جاريته جارية لها '),
(14643, 'Genesis', 1, 29, 30, ' فدخل على راحيل أيضا ، وأحب أيضا راحيل أكثر من ليئة . وعاد فخدم عنده سبع سنين أخر '),
(14644, 'Genesis', 1, 29, 31, ' ورأى الرب أن ليئة مكروهة ففتح رحمها ، وأما راحيل فكانت عاقرا '),
(14645, 'Genesis', 1, 29, 32, ' فحبلت ليئة وولدت ابنا ودعت اسمه رأوبين ، لأنها قالت : إن الرب قد نظر إلى مذلتي . إنه الآن يحبني رجلي '),
(14646, 'Genesis', 1, 29, 33, ' وحبلت أيضا وولدت ابنا ، وقالت : إن الرب قد سمع أني مكروهة فأعطاني هذا أيضا . فدعت اسمه شمعون '),
(14647, 'Genesis', 1, 29, 34, ' وحبلت أيضا وولدت ابنا ، وقالت : الآن هذه المرة يقترن بي رجلي ، لأني ولدت له ثلاثة بنين . لذلك دعي اسمه لاوي '),
(14648, 'Genesis', 1, 29, 35, ' وحبلت أيضا وولدت ابنا وقالت : هذه المرة أحمد الرب . لذلك دعت اسمه يهوذا . ثم توقفت عن الولادة '),
(14649, 'Genesis', 1, 30, 1, ' فلما رأت راحيل أنها لم تلد ليعقوب ، غارت راحيل من أختها ، وقالت ليعقوب : هب لي بنين ، وإلا فأنا أموت '),
(14650, 'Genesis', 1, 30, 2, ' فحمي غضب يعقوب على راحيل وقال : ألعلي مكان الله الذي منع عنك ثمرة البطن '),
(14651, 'Genesis', 1, 30, 3, ' فقالت : هوذا جاريتي بلهة ، ادخل عليها فتلد على ركبتي ، وأرزق أنا أيضا منها بنين '),
(14652, 'Genesis', 1, 30, 4, ' فأعطته بلهة جاريتها زوجة ، فدخل عليها يعقوب '),
(14653, 'Genesis', 1, 30, 5, ' فحبلت بلهة وولدت ليعقوب ابنا '),
(14654, 'Genesis', 1, 30, 6, ' فقالت راحيل : قد قضى لي الله وسمع أيضا لصوتي وأعطاني ابنا . لذلك دعت اسمه دانا '),
(14655, 'Genesis', 1, 30, 7, ' وحبلت أيضا بلهة جارية راحيل وولدت ابنا ثانيا ليعقوب '),
(14656, 'Genesis', 1, 30, 8, ' فقالت راحيل : مصارعات الله قد صارعت أختي وغلبت . فدعت اسمه نفتالي '),
(14657, 'Genesis', 1, 30, 9, ' ولما رأت ليئة أنها توقفت عن الولادة ، أخذت زلفة جاريتها وأعطتها ليعقوب زوجة '),
(14658, 'Genesis', 1, 30, 10, ' فولدت زلفة جارية ليئة ليعقوب ابنا '),
(14659, 'Genesis', 1, 30, 11, ' فقالت ليئة : بسعد . فدعت اسمه جادا '),
(14660, 'Genesis', 1, 30, 12, ' وولدت زلفة جارية ليئة ابنا ثانيا ليعقوب '),
(14661, 'Genesis', 1, 30, 13, ' فقالت ليئة : بغبطتي ، لأنه تغبطني بنات . فدعت اسمه أشير '),
(14662, 'Genesis', 1, 30, 14, ' ومضى رأوبين في أيام حصاد الحنطة فوجد لفاحا في الحقل وجاء به إلى ليئة أمه . فقالت راحيل لليئة : أعطيني من لفاح ابنك '),
(14663, 'Genesis', 1, 30, 15, ' فقالت لها : أقليل أنك أخذت رجلي فتأخذين لفاح ابني أيضا ؟ فقالت راحيل : إذا يضطجع معك الليلة عوضا عن لفاح ابنك '),
(14664, 'Genesis', 1, 30, 16, ' فلما أتى يعقوب من الحقل في المساء ، خرجت ليئة لملاقاته وقالت : إلي تجيء لأني قد استأجرتك بلفاح ابني . فاضطجع معها تلك الليلة '),
(14665, 'Genesis', 1, 30, 17, ' وسمع الله لليئة فحبلت وولدت ليعقوب ابنا خامسا '),
(14666, 'Genesis', 1, 30, 18, ' فقالت ليئة : قد أعطاني الله أجرتي ، لأني أعطيت جاريتي لرجلي . فدعت اسمه يساكر '),
(14667, 'Genesis', 1, 30, 19, ' وحبلت أيضا ليئة وولدت ابنا سادسا ليعقوب '),
(14668, 'Genesis', 1, 30, 20, ' فقالت ليئة : قد وهبني الله هبة حسنة . الآن يساكنني رجلي ، لأني ولدت له ستة بنين . فدعت اسمه زبولون '),
(14669, 'Genesis', 1, 30, 21, ' ثم ولدت ابنة ودعت اسمها دينة '),
(14670, 'Genesis', 1, 30, 22, ' وذكر الله راحيل ، وسمع لها الله وفتح رحمها '),
(14671, 'Genesis', 1, 30, 23, ' فحبلت وولدت ابنا فقالت : قد نزع الله عاري '),
(14672, 'Genesis', 1, 30, 24, ' ودعت اسمه يوسف قائلة : يزيدني الرب ابنا آخر '),
(14673, 'Genesis', 1, 30, 25, ' وحدث لما ولدت راحيل يوسف أن يعقوب قال للابان : اصرفني لأذهب إلى مكاني وإلى أرضي '),
(14674, 'Genesis', 1, 30, 26, ' أعطني نسائي وأولادي الذين خدمتك بهم فأذهب ، لأنك أنت تعلم خدمتي التي خدمتك '),
(14675, 'Genesis', 1, 30, 27, ' فقال له لابان : ليتني أجد نعمة في عينيك . قد تفاءلت فباركني الرب بسببك '),
(14676, 'Genesis', 1, 30, 28, ' وقال : عين لي أجرتك فأعطيك '),
(14677, 'Genesis', 1, 30, 29, ' فقال له : أنت تعلم ماذا خدمتك ، وماذا صارت مواشيك معي '),
(14678, 'Genesis', 1, 30, 30, ' لأن ما كان لك قبلي قليل فقد اتسع إلى كثير ، وباركك الرب في أثري . والآن متى أعمل أنا أيضا لبيتي '),
(14679, 'Genesis', 1, 30, 31, ' فقال : ماذا أعطيك ؟ فقال يعقوب : لاتعطيني شيئا . إن صنعت لي هذا الأمر أعود أرعى غنمك وأحفظها '),
(14680, 'Genesis', 1, 30, 32, ' أجتاز بين غنمك كلها اليوم ، واعزل أنت منها كل شاة رقطاء وبلقاء ، وكل شاة سوداء بين الخرفان ، وبلقاء ورقطاء بين المعزى . فيكون مثل ذلك أجرتي '),
(14681, 'Genesis', 1, 30, 33, ' ويشهد في بري يوم غد إذا جئت من أجل أجرتي قدامك . كل ما ليس أرقط أو أبلق بين المعزى وأسود بين الخرفان فهو مسروق عندي '),
(14682, 'Genesis', 1, 30, 34, ' فقال لابان : هوذا ليكن بحسب كلامك ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(14683, 'Genesis', 1, 30, 35, ' فعزل في ذلك اليوم التيوس المخططة والبلقاء ، وكل العناز الرقطاء والبلقاء ، كل ما فيه بياض وكل أسود بين الخرفان ، ودفعها إلى أيدي بنيه '),
(14684, 'Genesis', 1, 30, 36, ' وجعل مسيرة ثلاثة أيام بينه وبين يعقوب ، وكان يعقوب يرعى غنم لابان الباقية '),
(14685, 'Genesis', 1, 30, 37, ' فأخذ يعقوب لنفسه قضبانا خضرا من لبنى ولوز ودلب ، وقشر فيها خطوطا بيضا ، كاشطا عن البياض الذي على القضبان '),
(14686, 'Genesis', 1, 30, 38, ' وأوقف القضبان التي قشرها في الأجران في مساقي الماء حيث كانت الغنم تجيء لتشرب ، تجاه الغنم ، لتتوحم عند مجيئها لتشرب '),
(14687, 'Genesis', 1, 30, 39, ' فتوحمت الغنم عند القضبان ، وولدت الغنم مخططات ورقطا وبلقا '),
(14688, 'Genesis', 1, 30, 40, ' وأفرز يعقوب الخرفان وجعل وجوه الغنم إلى المخطط وكل أسود بين غنم لابان . وجعل له قطعانا وحده ولم يجعلها مع غنم لابان '),
(14689, 'Genesis', 1, 30, 41, ' وحدث كلما توحمت الغنم القوية أن يعقوب وضع القضبان أمام عيون الغنم في الأجران لتتوحم بين القضبان '),
(14690, 'Genesis', 1, 30, 42, ' وحين استضعفت الغنم لم يضعها ، فصارت الضعيفة للابان والقوية ليعقوب '),
(14691, 'Genesis', 1, 30, 43, ' فاتسع الرجل كثيرا جدا ، وكان له غنم كثير وجوار وعبيد وجمال وحمير '),
(14692, 'Genesis', 1, 31, 1, ' فسمع كلام بني لابان قائلين : أخذ يعقوب كل ما كان لأبينا ، ومما لأبينا صنع كل هذا المجد '),
(14693, 'Genesis', 1, 31, 2, ' ونظر يعقوب وجه لابان وإذا هو ليس معه كأمس وأول من أمس '),
(14694, 'Genesis', 1, 31, 3, ' وقال الرب ليعقوب : ارجع إلى أرض آبائك وإلى عشيرتك ، فأكون معك '),
(14695, 'Genesis', 1, 31, 4, ' فأرسل يعقوب ودعا راحيل وليئة إلى الحقل إلى غنمه '),
(14696, 'Genesis', 1, 31, 5, ' وقال لهما : أنا أرى وجه أبيكما أنه ليس نحوي كأمس وأول من أمس . ولكن إله أبي كان معي '),
(14697, 'Genesis', 1, 31, 6, ' وأنتما تعلمان أني بكل قوتي خدمت أباكما '),
(14698, 'Genesis', 1, 31, 7, ' وأما أبوكما فغدر بي وغير أجرتي عشر مرات . لكن الله لم يسمح له أن يصنع بي شرا '),
(14699, 'Genesis', 1, 31, 8, ' إن قال هكذا : الرقط تكون أجرتك ، ولدت كل الغنم رقطا . وإن قال هكذا : المخططة تكون أجرتك ، ولدت كل الغنم مخططة '),
(14700, 'Genesis', 1, 31, 9, ' فقد سلب الله مواشي أبيكما وأعطاني '),
(14701, 'Genesis', 1, 31, 10, ' وحدث في وقت توحم الغنم أني رفعت عيني ونظرت في حلم ، وإذا الفحول الصاعدة على الغنم مخططة ورقطاء ومنمرة '),
(14702, 'Genesis', 1, 31, 11, ' وقال لي ملاك الله في الحلم : يايعقوب . فقلت : هأنذا '),
(14703, 'Genesis', 1, 31, 12, ' فقال : ارفع عينيك وانظر . جميع الفحول الصاعدة على الغنم مخططة ورقطاء ومنمرة ، لأني قد رأيت كل مايصنع بك لابان '),
(14704, 'Genesis', 1, 31, 13, ' أنا إله بيت إيل حيث مسحت عمودا ، حيث نذرت لي نذرا . الآن قم اخرج من هذه الأرض وارجع إلى أرض ميلادك '),
(14705, 'Genesis', 1, 31, 14, ' فأجابت راحيل وليئة وقالتا له : ألنا أيضا نصيب وميراث في بيت أبينا '),
(14706, 'Genesis', 1, 31, 15, ' ألم نحسب منه أجنبيتين ، لأنه باعنا وقد أكل أيضا ثمننا '),
(14707, 'Genesis', 1, 31, 16, ' إن كل الغنى الذي سلبه الله من أبينا هو لنا ولأولادنا ، فالآن كل ما قال لك الله افعل '),
(14708, 'Genesis', 1, 31, 17, ' فقام يعقوب وحمل أولاده ونساءه على الجمال '),
(14709, 'Genesis', 1, 31, 18, ' وساق كل مواشيه وجميع مقتناه الذي كان قد اقتنى : مواشي اقتنائه التي اقتنى في فدان أرام ، ليجيء إلى إسحاق أبيه إلى أرض كنعان '),
(14710, 'Genesis', 1, 31, 19, ' وأما لابان فكان قد مضى ليجز غنمه ، فسرقت راحيل أصنام أبيها '),
(14711, 'Genesis', 1, 31, 20, ' وخدع يعقوب قلب لابان الأرامي إذ لم يخبره بأنه هارب '),
(14712, 'Genesis', 1, 31, 21, ' فهرب هو وكل ما كان له ، وقام وعبر النهر وجعل وجهه نحو جبل جلعاد '),
(14713, 'Genesis', 1, 31, 22, ' فأخبر لابان في اليوم الثالث بأن يعقوب قد هرب '),
(14714, 'Genesis', 1, 31, 23, ' فأخذ إخوته معه وسعى وراءه مسيرة سبعة أيام ، فأدركه في جبل جلعاد '),
(14715, 'Genesis', 1, 31, 24, ' وأتى الله إلى لابان الأرامي في حلم الليل وقال له : احترز من أن تكلم يعقوب بخير أو شر '),
(14716, 'Genesis', 1, 31, 25, ' فلحق لابان يعقوب ، ويعقوب قد ضرب خيمته في الجبل . فضرب لابان مع إخوته في جبل جلعاد '),
(14717, 'Genesis', 1, 31, 26, ' وقال لابان ليعقوب : ماذا فعلت ، وقد خدعت قلبي ، وسقت بناتي كسبايا السيف '),
(14718, 'Genesis', 1, 31, 27, ' لماذا هربت خفية وخدعتني ولم تخبرني حتى أشيعك بالفرح والأغاني ، بالدف والعود '),
(14719, 'Genesis', 1, 31, 28, ' ولم تدعني أقبل بني وبناتي ؟ الآن بغباوة فعلت '),
(14720, 'Genesis', 1, 31, 29, ' في قدرة يدي أن أصنع بكم شرا ، ولكن إله أبيكم كلمني البارحة قائلا : احترز من أن تكلم يعقوب بخير أو شر '),
(14721, 'Genesis', 1, 31, 30, ' والآن أنت ذهبت لأنك قد اشتقت إلى بيت أبيك ، ولكن لماذا سرقت آلهتي '),
(14722, 'Genesis', 1, 31, 31, ' فأجاب يعقوب وقال للابان : إني خفت لأني قلت لعلك تغتصب ابنتيك مني '),
(14723, 'Genesis', 1, 31, 32, ' الذي تجد آلهتك معه لا يعيش . قدام إخوتنا انظر ماذا معي وخذه لنفسك . ولم يكن يعقوب يعلم أن راحيل سرقتها '),
(14724, 'Genesis', 1, 31, 33, ' فدخل لابان خباء يعقوب وخباء ليئة وخباء الجاريتين ولم يجد . وخرج من خباء ليئة ودخل خباء راحيل '),
(14725, 'Genesis', 1, 31, 34, ' وكانت راحيل قد أخذت الأصنام ووضعتها في حداجة الجمل وجلست عليها . فجس لابان كل الخباء ولم يجد '),
(14726, 'Genesis', 1, 31, 35, ' وقالت لأبيها : لا يغتظ سيدي أني لا أستطيع أن أقوم أمامك لأن علي عادة النساء . ففتش ولم يجد الأصنام '),
(14727, 'Genesis', 1, 31, 36, ' فاغتاظ يعقوب وخاصم لابان . وأجاب يعقوب وقال للابان : ما جرمي ؟ ما خطيتي حتى حميت ورائي '),
(14728, 'Genesis', 1, 31, 37, ' إنك جسست جميع أثاثي . ماذا وجدت من جميع أثاث بيتك ؟ ضعه ههنا قدام إخوتي وإخوتك ، فلينصفوا بيننا الاثنين '),
(14729, 'Genesis', 1, 31, 38, ' الآن عشرين سنة أنا معك . نعاجك وعنازك لم تسقط ، وكباش غنمك لم آكل '),
(14730, 'Genesis', 1, 31, 39, ' فريسة لم أحضر إليك . أنا كنت أخسرها . من يدي كنت تطلبها . مسروقة النهار أو مسروقة الليل '),
(14731, 'Genesis', 1, 31, 40, ' كنت في النهار يأكلني الحر وفي الليل الجليد ، وطار نومي من عيني '),
(14732, 'Genesis', 1, 31, 41, ' الآن لي عشرون سنة في بيتك . خدمتك أربع عشرة سنة بابنتيك ، وست سنين بغنمك . وقد غيرت أجرتي عشر مرات '),
(14733, 'Genesis', 1, 31, 42, ' لولا أن إله أبي إله إبراهيم وهيبة إسحاق كان معي ، لكنت الآن قد صرفتني فارغا . مشقتي وتعب يدي قد نظر الله ، فوبخك البارحة '),
(14734, 'Genesis', 1, 31, 43, ' فأجاب لابان وقال ليعقوب : البنات بناتي ، والبنون بني ، والغنم غنمي ، وكل ما أنت ترى فهو لي . فبناتي ماذا أصنع بهن اليوم أو بأولادهن الذين ولدن '),
(14735, 'Genesis', 1, 31, 44, ' فالآن هلم نقطع عهدا أنا وأنت ، فيكون شاهدا بيني وبينك '),
(14736, 'Genesis', 1, 31, 45, ' فأخذ يعقوب حجرا وأوقفه عمودا '),
(14737, 'Genesis', 1, 31, 46, ' وقال يعقوب لإخوته : التقطوا حجارة . فأخذوا حجارة وعملوا رجمة وأكلوا هناك على الرجمة '),
(14738, 'Genesis', 1, 31, 47, ' ودعاها لابان يجر سهدوثا وأما يعقوب فدعاها جلعيد '),
(14739, 'Genesis', 1, 31, 48, ' وقال لابان : هذه الرجمة هي شاهدة بيني وبينك اليوم . لذلك دعي اسمها جلعيد '),
(14740, 'Genesis', 1, 31, 49, ' و المصفاة ، لأنه قال : ليراقب الرب بيني وبينك حينما نتوارى بعضنا عن بعض '),
(14741, 'Genesis', 1, 31, 50, ' إنك لا تذل بناتي ، ولاتأخذ نساء على بناتي . ليس إنسان معنا . انظر ، الله شاهد بيني وبينك '),
(14742, 'Genesis', 1, 31, 51, ' وقال لابان ليعقوب : هوذا هذه الرجمة ، وهوذا العمود الذي وضعت بيني وبينك '),
(14743, 'Genesis', 1, 31, 52, ' شاهدة هذه الرجمة وشاهد العمود أني لا أتجاوز هذه الرجمة إليك ، وأنك لا تتجاوز هذه الرجمة وهذا العمود إلي للشر '),
(14744, 'Genesis', 1, 31, 53, ' إله إبراهيم وآلهة ناحور ، آلهة أبيهما ، يقضون بيننا . وحلف يعقوب بهيبة أبيه إسحاق '),
(14745, 'Genesis', 1, 31, 54, ' وذبح يعقوب ذبيحة في الجبل ودعا إخوته ليأكلوا طعاما ، فأكلوا طعاما وباتوا في الجبل '),
(14746, 'Genesis', 1, 31, 55, ' ثم بكر لابان صباحا وقبل بنيه وبناته وباركهم ومضى . ورجع لابان إلى مكانه '),
(14747, 'Genesis', 1, 32, 1, ' وأما يعقوب فمضى في طريقه ولاقاه ملائكة الله '),
(14748, 'Genesis', 1, 32, 2, ' وقال يعقوب إذ رآهم : هذا جيش الله . فدعا اسم ذلك المكان محنايم '),
(14749, 'Genesis', 1, 32, 3, ' وأرسل يعقوب رسلا قدامه إلى عيسو أخيه إلى أرض سعير بلاد أدوم '),
(14750, 'Genesis', 1, 32, 4, ' وأمرهم قائلا : هكذا تقولون لسيدي عيسو : هكذا قال عبدك يعقوب : تغربت عند لابان ولبثت إلى الآن '),
(14751, 'Genesis', 1, 32, 5, ' وقد صار لي بقر وحمير وغنم وعبيد وإماء . وأرسلت لأخبر سيدي لكي أجد نعمة في عينيك '),
(14752, 'Genesis', 1, 32, 6, ' فرجع الرسل إلى يعقوب قائلين : أتينا إلى أخيك ، إلى عيسو ، وهو أيضا قادم للقائك ، وأربع مئة رجل معه '),
(14753, 'Genesis', 1, 32, 7, ' فخاف يعقوب جدا وضاق به الأمر ، فقسم القوم الذين معه والغنم والبقر والجمال إلى جيشين '),
(14754, 'Genesis', 1, 32, 8, ' وقال : إن جاء عيسو إلى الجيش الواحد وضربه ، يكون الجيش الباقي ناجيا '),
(14755, 'Genesis', 1, 32, 9, ' وقال يعقوب : يا إله أبي إبراهيم وإله أبي إسحاق ، الرب الذي قال لي : ارجع إلى أرضك وإلى عشيرتك فأحسن إليك '),
(14756, 'Genesis', 1, 32, 10, ' صغير أنا عن جميع ألطافك وجميع الأمانة التي صنعت إلى عبدك . فإني بعصاي عبرت هذا الأردن ، والآن قد صرت جيشين '),
(14757, 'Genesis', 1, 32, 11, ' نجني من يد أخي ، من يد عيسو ، لأني خائف منه أن يأتي ويضربني الأم مع البنين '),
(14758, 'Genesis', 1, 32, 12, ' وأنت قد قلت : إني أحسن إليك وأجعل نسلك كرمل البحر الذي لا يعد للكثرة '),
(14759, 'Genesis', 1, 32, 13, ' وبات هناك تلك الليلة وأخذ مما أتى بيده هدية لعيسو أخيه '),
(14760, 'Genesis', 1, 32, 14, ' مئتي عنز وعشرين تيسا ، مئتي نعجة وعشرين كبشا '),
(14761, 'Genesis', 1, 32, 15, ' ثلاثين ناقة مرضعة وأولادها ، أربعين بقرة وعشرة ثيران ، عشرين أتانا وعشرة حمير '),
(14762, 'Genesis', 1, 32, 16, ' ودفعها إلى يد عبيده قطيعا قطيعا على حدة . وقال لعبيده : اجتازوا قدامي واجعلوا فسحة بين قطيع وقطيع '),
(14763, 'Genesis', 1, 32, 17, ' وأمر الأول قائلا : إذا صادفك عيسو أخي وسألك قائلا : لمن أنت ؟ وإلى أين تذهب ؟ ولمن هذا الذي قدامك '),
(14764, 'Genesis', 1, 32, 18, ' تقول : لعبدك يعقوب . هو هدية مرسلة لسيدي عيسو ، وها هو أيضا وراءنا '),
(14765, 'Genesis', 1, 32, 19, ' وأمر أيضا الثانى والثالث وجميع السائرين وراء القطعان قائلا : بمثل هذا الكلام تكلمون عيسو حينما تجدونه '),
(14766, 'Genesis', 1, 32, 20, ' وتقولون : هوذا عبدك يعقوب أيضا وراءنا . لأنه قال : أستعطف وجهه بالهدية السائرة أمامي ، وبعد ذلك أنظر وجهه ، عسى أن يرفع وجهي '),
(14767, 'Genesis', 1, 32, 21, ' فاجتازت الهدية قدامه ، وأما هو فبات تلك الليلة في المحلة '),
(14768, 'Genesis', 1, 32, 22, ' ثم قام في تلك الليلة وأخذ امرأتيه وجاريتيه وأولاده الأحد عشر وعبر مخاضة يبوق '),
(14769, 'Genesis', 1, 32, 23, ' أخذهم وأجازهم الوادي ، وأجاز ما كان له '),
(14770, 'Genesis', 1, 32, 24, ' فبقي يعقوب وحده ، وصارعه إنسان حتى طلوع الفجر '),
(14771, 'Genesis', 1, 32, 25, ' ولما رأى أنه لا يقدر عليه ، ضرب حق فخذه ، فانخلع حق فخذ يعقوب في مصارعته معه '),
(14772, 'Genesis', 1, 32, 26, ' وقال : أطلقني ، لأنه قد طلع الفجر . فقال : لا أطلقك إن لم تباركني '),
(14773, 'Genesis', 1, 32, 27, ' فقال له : ما اسمك ؟ فقال : يعقوب '),
(14774, 'Genesis', 1, 32, 28, ' فقال : لا يدعى اسمك في ما بعد يعقوب بل إسرائيل ، لأنك جاهدت مع الله والناس وقدرت '),
(14775, 'Genesis', 1, 32, 29, ' وسأل يعقوب وقال : أخبرني باسمك . فقال : لماذا تسأل عن اسمي ؟ وباركه هناك '),
(14776, 'Genesis', 1, 32, 30, ' فدعا يعقوب اسم المكان فنيئيل قائلا : لأني نظرت الله وجها لوجه ، ونجيت نفسي '),
(14777, 'Genesis', 1, 32, 31, ' وأشرقت له الشمس إذ عبر فنوئيل وهو يخمع على فخذه '),
(14778, 'Genesis', 1, 32, 32, ' لذلك لا يأكل بنو إسرائيل عرق النسا الذي على حق الفخذ إلى هذا اليوم ، لأنه ضرب حق فخذ يعقوب على عرق النسا '),
(14779, 'Genesis', 1, 33, 1, ' ورفع يعقوب عينيه ونظر وإذا عيسو مقبل ومعه أربع مئة رجل ، فقسم الأولاد على ليئة وعلى راحيل وعلى الجاريتين '),
(14780, 'Genesis', 1, 33, 2, ' ووضع الجاريتين وأولادهما أولا ، وليئة وأولادها وراءهم ، وراحيل ويوسف أخيرا '),
(14781, 'Genesis', 1, 33, 3, ' وأما هو فاجتاز قدامهم وسجد إلى الأرض سبع مرات حتى اقترب إلى أخيه '),
(14782, 'Genesis', 1, 33, 4, ' فركض عيسو للقائه وعانقه ووقع على عنقه وقبله ، وبكيا '),
(14783, 'Genesis', 1, 33, 5, ' ثم رفع عينيه وأبصر النساء والأولاد وقال : ما هؤلاء منك ؟ فقال : الأولاد الذين أنعم الله بهم على عبدك '),
(14784, 'Genesis', 1, 33, 6, ' فاقتربت الجاريتان هما وأولادهما وسجدتا '),
(14785, 'Genesis', 1, 33, 7, ' ثم اقتربت ليئة أيضا وأولادها وسجدوا . وبعد ذلك اقترب يوسف وراحيل وسجدا '),
(14786, 'Genesis', 1, 33, 8, ' فقال : ماذا منك كل هذا الجيش الذي صادفته ؟ فقال : لأجد نعمة في عيني سيدي '),
(14787, 'Genesis', 1, 33, 9, ' فقال عيسو : لي كثير ، يا أخي . ليكن لك الذي لك '),
(14788, 'Genesis', 1, 33, 10, ' فقال يعقوب : لا . إن وجدت نعمة في عينيك تأخذ هديتي من يدي ، لأني رأيت وجهك كما يرى وجه الله ، فرضيت علي '),
(14789, 'Genesis', 1, 33, 11, ' خذ بركتي التي أتي بها إليك ، لأن الله قد أنعم علي ولي كل شيء . وألح عليه فأخذ '),
(14790, 'Genesis', 1, 33, 12, ' ثم قال : لنرحل ونذهب ، وأذهب أنا قدامك '),
(14791, 'Genesis', 1, 33, 13, ' فقال له : سيدي عالم أن الأولاد رخصة ، والغنم والبقر التي عندي مرضعة ، فإن استكدوها يوما واحدا ماتت كل الغنم '),
(14792, 'Genesis', 1, 33, 14, ' ليجتز سيدي قدام عبده ، وأنا أستاق على مهلي في إثر الأملاك التي قدامي ، وفي إثر الأولاد ، حتى أجيء إلى سيدي إلى سعير '),
(14793, 'Genesis', 1, 33, 15, ' فقال عيسو : أترك عندك من القوم الذين معي . فقال : لماذا ؟ دعني أجد نعمة في عيني سيدي '),
(14794, 'Genesis', 1, 33, 16, ' فرجع عيسو ذلك اليوم في طريقه إلى سعير '),
(14795, 'Genesis', 1, 33, 17, ' وأما يعقوب فارتحل إلى سكوت ، وبنى لنفسه بيتا ، وصنع لمواشيه مظلات . لذلك دعا اسم المكان سكوت '),
(14796, 'Genesis', 1, 33, 18, ' ثم أتى يعقوب سالما إلى مدينة شكيم التي في أرض كنعان ، حين جاء من فدان أرام . ونزل أمام المدينة '),
(14797, 'Genesis', 1, 33, 19, ' وابتاع قطعة الحقل التي نصب فيها خيمته من يد بني حمور أبي شكيم بمئة قسيطة '),
(14798, 'Genesis', 1, 33, 20, ' وأقام هناك مذبحا ودعاه إيل إله إسرائيل '),
(14799, 'Genesis', 1, 34, 1, ' وخرجت دينة ابنة ليئة التي ولدتها ليعقوب لتنظر بنات الأرض '),
(14800, 'Genesis', 1, 34, 2, ' فرآها شكيم ابن حمور الحوي رئيس الأرض ، وأخذها واضطجع معها وأذلها '),
(14801, 'Genesis', 1, 34, 3, ' وتعلقت نفسه بدينة ابنة يعقوب ، وأحب الفتاة ولاطف الفتاة '),
(14802, 'Genesis', 1, 34, 4, ' فكلم شكيم حمور أباه قائلا : خذ لي هذه الصبية زوجة '),
(14803, 'Genesis', 1, 34, 5, ' وسمع يعقوب أنه نجس دينة ابنته . وأما بنوه فكانوا مع مواشيه في الحقل ، فسكت يعقوب حتى جاءوا '),
(14804, 'Genesis', 1, 34, 6, ' فخرج حمور أبو شكيم إلى يعقوب ليتكلم معه '),
(14805, 'Genesis', 1, 34, 7, ' وأتى بنو يعقوب من الحقل حين سمعوا . وغضب الرجال واغتاظوا جدا لأنه صنع قباحة في إسرائيل بمضاجعة ابنة يعقوب ، وهكذا لا يصنع '),
(14806, 'Genesis', 1, 34, 8, ' وتكلم حمور معهم قائلا : شكيم ابني قد تعلقت نفسه بابنتكم . أعطوه إياها زوجة '),
(14807, 'Genesis', 1, 34, 9, ' وصاهرونا . تعطوننا بناتكم ، وتأخذون لكم بناتنا '),
(14808, 'Genesis', 1, 34, 10, ' وتسكنون معنا ، وتكون الأرض قدامكم . اسكنوا واتجروا فيها وتملكوا بها '),
(14809, 'Genesis', 1, 34, 11, ' ثم قال شكيم لأبيها ولإخوتها : دعوني أجد نعمة في أعينكم . فالذي تقولون لي أعطي '),
(14810, 'Genesis', 1, 34, 12, ' كثروا علي جدا مهرا وعطية ، فأعطي كما تقولون لي . وأعطوني الفتاة زوجة '),
(14811, 'Genesis', 1, 34, 13, ' فأجاب بنو يعقوب شكيم وحمور أباه بمكر وتكلموا . لأنه كان قد نجس دينة أختهم '),
(14812, 'Genesis', 1, 34, 14, ' فقالوا لهما : لا نستطيع أن نفعل هذا الأمر أن نعطي أختنا لرجل أغلف ، لأنه عار لنا '),
(14813, 'Genesis', 1, 34, 15, ' غير أننا بهذا نواتيكم : إن صرتم مثلنا بختنكم كل ذكر '),
(14814, 'Genesis', 1, 34, 16, ' نعطيكم بناتنا ونأخذ لنا بناتكم ، ونسكن معكم ونصير شعبا واحدا '),
(14815, 'Genesis', 1, 34, 17, ' وإن لم تسمعوا لنا ، أن تختتنوا ، نأخذ ابنتنا ونمضي '),
(14816, 'Genesis', 1, 34, 18, ' فحسن كلامهم في عيني حمور وفي عيني شكيم بن حمور '),
(14817, 'Genesis', 1, 34, 19, ' ولم يتأخر الغلام أن يفعل الأمر ، لأنه كان مسرورا بابنة يعقوب . وكان أكرم جميع بيت أبيه '),
(14818, 'Genesis', 1, 34, 20, ' فأتى حمور وشكيم ابنه إلى باب مدينتهما ، وكلما أهل مدينتهما قائلين '),
(14819, 'Genesis', 1, 34, 21, ' هؤلاء القوم مسالمون لنا . فليسكنوا في الأرض ويتجروا فيها . وهوذا الأرض واسعة الطرفين أمامهم . نأخذ لنا بناتهم زوجات ونعطيهم بناتنا '),
(14820, 'Genesis', 1, 34, 22, ' غير أنه بهذا فقط يواتينا القوم على السكن معنا لنصير شعبا واحدا : بختننا كل ذكر كما هم مختونون '),
(14821, 'Genesis', 1, 34, 23, ' ألا تكون مواشيهم ومقتناهم وكل بهائمهم لنا ؟ نواتيهم فقط فيسكنون معنا '),
(14822, 'Genesis', 1, 34, 24, ' فسمع لحمور وشكيم ابنه جميع الخارجين من باب المدينة ، واختتن كل ذكر . كل الخارجين من باب المدينة '),
(14823, 'Genesis', 1, 34, 25, ' فحدث في اليوم الثالث إذ كانوا متوجعين أن ابني يعقوب ، شمعون ولاوي أخوي دينة ، أخذا كل واحد سيفه وأتيا على المدينة بأمن وقتلا كل ذكر '),
(14824, 'Genesis', 1, 34, 26, ' وقتلا حمور وشكيم ابنه بحد السيف ، وأخذا دينة من بيت شكيم وخرجا '),
(14825, 'Genesis', 1, 34, 27, ' ثم أتى بنو يعقوب على القتلى ونهبوا المدينة ، لأنهم نجسوا أختهم '),
(14826, 'Genesis', 1, 34, 28, ' غنمهم وبقرهم وحميرهم وكل ما في المدينة وما في الحقل أخذوه '),
(14827, 'Genesis', 1, 34, 29, ' وسبوا ونهبوا كل ثروتهم وكل أطفالهم ، ونساءهم وكل ما في البيوت '),
(14828, 'Genesis', 1, 34, 30, ' فقال يعقوب لشمعون ولاوي : كدرتماني بتكريهكما إياي عند سكان الأرض الكنعانيين والفرزيين ، وأنا نفر قليل . فيجتمعون علي ويضربونني ، فأبيد أنا وبيتي '),
(14829, 'Genesis', 1, 34, 31, ' فقالا : أنظير زانية يفعل بأختنا '),
(14830, 'Genesis', 1, 35, 1, ' ثم قال الله ليعقوب : قم اصعد إلى بيت إيل وأقم هناك ، واصنع هناك مذبحا لله الذي ظهر لك حين هربت من وجه عيسو أخيك '),
(14831, 'Genesis', 1, 35, 2, ' فقال يعقوب لبيته ولكل من كان معه : اعزلوا الآلهة الغريبة التي بينكم وتطهروا وأبدلوا ثيابكم '),
(14832, 'Genesis', 1, 35, 3, ' ولنقم ونصعد إلى بيت إيل ، فأصنع هناك مذبحا لله الذي استجاب لي في يوم ضيقتي ، وكان معي في الطريق الذي ذهبت فيه '),
(14833, 'Genesis', 1, 35, 4, ' فأعطوا يعقوب كل الآلهة الغريبة التي في أيديهم والأقراط التي في آذانهم ، فطمرها يعقوب تحت البطمة التي عند شكيم '),
(14834, 'Genesis', 1, 35, 5, ' ثم رحلوا ، وكان خوف الله على المدن التي حولهم ، فلم يسعوا وراء بني يعقوب '),
(14835, 'Genesis', 1, 35, 6, ' فأتى يعقوب إلى لوز التي في أرض كنعان ، وهي بيت إيل . هو وجميع القوم الذين معه '),
(14836, 'Genesis', 1, 35, 7, ' وبنى هناك مذبحا ، ودعا المكان إيل بيت إيل لأنه هناك ظهر له الله حين هرب من وجه أخيه '),
(14837, 'Genesis', 1, 35, 8, ' وماتت دبورة مرضعة رفقة ودفنت تحت بيت إيل تحت البلوطة ، فدعا اسمها ألون باكوت '),
(14838, 'Genesis', 1, 35, 9, ' وظهر الله ليعقوب أيضا حين جاء من فدان أرام وباركه '),
(14839, 'Genesis', 1, 35, 10, ' وقال له الله : اسمك يعقوب . لا يدعى اسمك فيما بعد يعقوب ، بل يكون اسمك إسرائيل . فدعا اسمه إسرائيل '),
(14840, 'Genesis', 1, 37, 11, ' فحسده إخوته ، وأما أبوه فحفظ الأمر '),
(14841, 'Genesis', 1, 37, 12, ' ومضى إخوته ليرعوا غنم أبيهم عند شكيم '),
(14842, 'Genesis', 1, 37, 13, ' فقال إسرائيل ليوسف : أليس إخوتك يرعون عند شكيم ؟ تعال فأرسلك إليهم . فقال له:هأنذا '),
(14843, 'Genesis', 1, 37, 14, ' فقال له : اذهب انظر سلامة إخوتك وسلامة الغنم ورد لي خبرا . فأرسله من وطاء حبرون فأتى إلى شكيم '),
(14844, 'Genesis', 1, 37, 15, ' فوجده رجل وإذا هو ضال في الحقل . فسأله الرجل قائلا : ماذا تطلب '),
(14845, 'Genesis', 1, 37, 16, ' فقال : أنا طالب إخوتي . أخبرني أين يرعون '),
(14846, 'Genesis', 1, 37, 17, ' فقال الرجل : قد ارتحلوا من هنا ، لأني سمعتهم يقولون : لنذهب إلى دوثان . فذهب يوسف وراء إخوته فوجدهم في دوثان '),
(14847, 'Genesis', 1, 37, 18, ' فلما أبصروه من بعيد ، قبلما اقترب إليهم ، احتالوا له ليميتوه '),
(14848, 'Genesis', 1, 37, 19, ' فقال بعضهم لبعض : هوذا هذا صاحب الأحلام قادم '),
(14849, 'Genesis', 1, 37, 20, ' فالآن هلم نقتله ونطرحه في إحدى الآبار ونقول : وحش رديء أكله . فنرى ماذا تكون أحلامه '),
(14850, 'Genesis', 1, 37, 21, ' فسمع رأوبين وأنقذه من أيديهم ، وقال : لا نقتله '),
(14851, 'Genesis', 1, 37, 22, ' وقال لهم رأوبين : لا تسفكوا دما . اطرحوه في هذه البئر التي في البرية ولا تمدوا إليه يدا . لكي ينقذه من أيديهم ليرده إلى أبيه '),
(14852, 'Genesis', 1, 37, 23, ' فكان لما جاء يوسف إلى إخوته أنهم خلعوا عن يوسف قميصه ، القميص الملون الذي عليه '),
(14853, 'Genesis', 1, 37, 24, ' وأخذوه وطرحوه في البئر . وأما البئر فكانت فارغة ليس فيها ماء '),
(14854, 'Genesis', 1, 37, 25, ' ثم جلسوا ليأكلوا طعاما . فرفعوا عيونهم ونظروا وإذا قافلة إسماعيليين مقبلة من جلعاد ، وجمالهم حاملة كثيراء وبلسانا ولاذنا ، ذاهبين لينزلوا بها إلى مصر '),
(14855, 'Genesis', 1, 37, 26, ' فقال يهوذا لإخوته : ما الفائدة أن نقتل أخانا ونخفي دمه '),
(14856, 'Genesis', 1, 37, 27, ' تعالوا فنبيعه للإسماعيليين ، ولا تكن أيدينا عليه لأنه أخونا ولحمنا . فسمع له إخوته '),
(14857, 'Genesis', 1, 37, 28, ' واجتاز رجال مديانيون تجار ، فسحبوا يوسف وأصعدوه من البئر ، وباعوا يوسف للإسماعيليين بعشرين من الفضة . فأتوا بيوسف إلى مصر '),
(14858, 'Genesis', 1, 37, 29, ' ورجع رأوبين إلى البئر ، وإذا يوسف ليس في البئر ، فمزق ثيابه '),
(14859, 'Genesis', 1, 37, 30, ' ثم رجع إلى إخوته وقال : الولد ليس موجودا ، وأنا إلى أين أذهب '),
(14860, 'Genesis', 1, 37, 31, ' فأخذوا قميص يوسف وذبحوا تيسا من المعزى وغمسوا القميص في الدم '),
(14861, 'Genesis', 1, 37, 32, ' وأرسلوا القميص الملون وأحضروه إلى أبيهم وقالوا : وجدنا هذا . حقق أقميص ابنك هو أم لا '),
(14862, 'Genesis', 1, 37, 33, ' فتحققه وقال : قميص ابني وحش رديء أكله ، افترس يوسف افتراسا '),
(14863, 'Genesis', 1, 37, 34, ' فمزق يعقوب ثيابه ، ووضع مسحا على حقويه ، وناح على ابنه أياما كثيرة '),
(14864, 'Genesis', 1, 37, 35, ' فقام جميع بنيه وجميع بناته ليعزوه ، فأبى أن يتعزى وقال : إني أنزل إلى ابني نائحا إلى الهاوية . وبكى عليه أبوه '),
(14865, 'Genesis', 1, 37, 36, ' وأما المديانيون فباعوه في مصر لفوطيفار خصي فرعون ، رئيس الشرط '),
(14866, 'Genesis', 1, 38, 1, ' وحدث في ذلك الزمان أن يهوذا نزل من عند إخوته ، ومال إلى رجل عدلامي اسمه حيرة '),
(14867, 'Genesis', 1, 38, 2, ' ونظر يهوذا هناك ابنة رجل كنعاني اسمه شوع ، فأخذها ودخل عليها '),
(14868, 'Genesis', 1, 38, 3, ' فحبلت وولدت ابنا ودعا اسمه عيرا '),
(14869, 'Genesis', 1, 38, 4, ' ثم حبلت أيضا وولدت ابنا ودعت اسمه أونان '),
(14870, 'Genesis', 1, 38, 5, ' ثم عادت فولدت أيضا ابنا ودعت اسمه شيلة . وكان في كزيب حين ولدته '),
(14871, 'Genesis', 1, 38, 6, ' وأخذ يهوذا زوجة لعير بكره اسمها ثامار '),
(14872, 'Genesis', 1, 38, 7, ' وكان عير بكر يهوذا شريرا في عيني الرب ، فأماته الرب '),
(14873, 'Genesis', 1, 38, 8, ' فقال يهوذا لأونان : ادخل على امرأة أخيك وتزوج بها ، وأقم نسلا لأخيك '),
(14874, 'Genesis', 1, 38, 9, ' فعلم أونان أن النسل لا يكون له ، فكان إذ دخل على امرأة أخيه أنه أفسد على الأرض ، لكي لا يعطي نسلا لأخيه '),
(14875, 'Genesis', 1, 38, 10, ' فقبح في عيني الرب ما فعله ، فأماته أيضا '),
(14876, 'Genesis', 1, 38, 11, ' فقال يهوذا لثامار كنته : اقعدي أرملة في بيت أبيك حتى يكبر شيلة ابني . لأنه قال : لعله يموت هو أيضا كأخويه . فمضت ثامار وقعدت في بيت أبيها '),
(14877, 'Genesis', 1, 38, 12, ' ولما طال الزمان ماتت ابنة شوع امرأة يهوذا . ثم تعزى يهوذا فصعد إلى جزاز غنمه إلى تمنة ، هو وحيرة صاحبه العدلامي '),
(14878, 'Genesis', 1, 38, 13, ' فأخبرت ثامار وقيل لها : هوذا حموك صاعد إلى تمنة ليجز غنمه '),
(14879, 'Genesis', 1, 38, 14, ' فخلعت عنها ثياب ترملها ، وتغطت ببرقع وتلففت ، وجلست في مدخل عينايم التي على طريق تمنة ، لأنها رأت أن شيلة قد كبر وهي لم تعط له زوجة '),
(14880, 'Genesis', 1, 38, 15, ' فنظرها يهوذا وحسبها زانية ، لأنها كانت قد غطت وجهها '),
(14881, 'Genesis', 1, 38, 16, ' فمال إليها على الطريق وقال : هاتي أدخل عليك . لأنه لم يعلم أنها كنته . فقالت : ماذا تعطيني لكي تدخل علي '),
(14882, 'Genesis', 1, 38, 17, ' فقال : إني أرسل جدي معزى من الغنم . فقالت : هل تعطيني رهنا حتى ترسله '),
(14883, 'Genesis', 1, 38, 18, ' فقال : ما الرهن الذي أعطيك ؟ فقالت : خاتمك وعصابتك وعصاك التي في يدك . فأعطاها ودخل عليها ، فحبلت منه '),
(14884, 'Genesis', 1, 38, 19, ' ثم قامت ومضت وخلعت عنها برقعها ولبست ثياب ترملها '),
(14885, 'Genesis', 1, 38, 20, ' فأرسل يهوذا جدي المعزى بيد صاحبه العدلامي ليأخذ الرهن من يد المرأة ، فلم يجدها '),
(14886, 'Genesis', 1, 38, 21, ' فسأل أهل مكانها قائلا : أين الزانية التي كانت في عينايم على الطريق ؟ فقالوا : لم تكن ههنا زانية '),
(14887, 'Genesis', 1, 38, 22, ' فرجع إلى يهوذا وقال : لم أجدها . وأهل المكان أيضا قالوا : لم تكن ههنا زانية '),
(14888, 'Genesis', 1, 38, 23, ' فقال يهوذا : لتأخذ لنفسها ، لئلا نصير إهانة . إني قد أرسلت هذا الجدي وأنت لم تجدها '),
(14889, 'Genesis', 1, 38, 24, ' ولما كان نحو ثلاثة أشهر ، أخبر يهوذا وقيل له : قد زنت ثامار كنتك ، وها هي حبلى أيضا من الزنا . فقال يهوذا : أخرجوها فتحرق '),
(14890, 'Genesis', 1, 38, 25, ' أما هي فلما أخرجت أرسلت إلى حميها قائلة : من الرجل الذي هذه له أنا حبلى وقالت : حقق لمن الخاتم والعصابة والعصا هذه '),
(14891, 'Genesis', 1, 38, 26, ' فتحققها يهوذا وقال : هي أبر مني ، لأني لم أعطها لشيلة ابني . فلم يعد يعرفها أيضا '),
(14892, 'Genesis', 1, 38, 27, ' وفي وقت ولادتها إذا في بطنها توأمان '),
(14893, 'Genesis', 1, 38, 28, ' وكان في ولادتها أن أحدهما أخرج يدا فأخذت القابلة وربطت على يده قرمزا ، قائلة : هذا خرج أولا '),
(14894, 'Genesis', 1, 38, 29, ' ولكن حين رد يده ، إذا أخوه قد خرج . فقالت : لماذا اقتحمت ؟ عليك اقتحام . فدعي اسمه فارص '),
(14895, 'Genesis', 1, 38, 30, ' وبعد ذلك خرج أخوه الذي على يده القرمز . فدعي اسمه زارح '),
(14896, 'Genesis', 1, 39, 1, ' وأما يوسف فأنزل إلى مصر ، واشتراه فوطيفار خصي فرعون رئيس الشرط ، رجل مصري ، من يد الإسماعيليين الذين أنزلوه إلى هناك '),
(14897, 'Genesis', 1, 39, 2, ' وكان الرب مع يوسف فكان رجلا ناجحا ، وكان في بيت سيده المصري '),
(14898, 'Genesis', 1, 39, 3, ' ورأى سيده أن الرب معه ، وأن كل ما يصنع كان الرب ينجحه بيده '),
(14899, 'Genesis', 1, 39, 4, ' فوجد يوسف نعمة في عينيه ، وخدمه ، فوكله على بيته ودفع إلى يده كل ما كان له '),
(14900, 'Genesis', 1, 39, 5, ' وكان من حين وكله على بيته ، وعلى كل ما كان له ، أن الرب بارك بيت المصري بسبب يوسف . وكانت بركة الرب على كل ما كان له في البيت وفي الحقل '),
(14901, 'Genesis', 1, 39, 6, ' فترك كل ما كان له في يد يوسف . ولم يكن معه يعرف شيئا إلا الخبز الذي يأكل . وكان يوسف حسن الصورة وحسن المنظر '),
(14902, 'Genesis', 1, 39, 7, ' وحدث بعد هذه الأمور أن امرأة سيده رفعت عينيها إلى يوسف وقالت : اضطجع معي '),
(14903, 'Genesis', 1, 39, 8, ' فأبى وقال لامرأة سيده : هوذا سيدي لا يعرف معي ما في البيت ، وكل ما له قد دفعه إلى يدي '),
(14904, 'Genesis', 1, 39, 9, ' ليس هو في هذا البيت أعظم مني . ولم يمسك عني شيئا غيرك ، لأنك امرأته . فكيف أصنع هذا الشر العظيم وأخطئ إلى الله '),
(14905, 'Genesis', 1, 39, 10, ' وكان إذ كلمت يوسف يوما فيوما أنه لم يسمع لها أن يضطجع بجانبها ليكون معها '),
(14906, 'Genesis', 1, 39, 11, ' ثم حدث نحو هذا الوقت أنه دخل البيت ليعمل عمله ، ولم يكن إنسان من أهل البيت هناك في البيت '),
(14907, 'Genesis', 1, 39, 12, ' فأمسكته بثوبه قائلة : اضطجع معي . فترك ثوبه في يدها وهرب وخرج إلى خارج '),
(14908, 'Genesis', 1, 39, 13, ' وكان لما رأت أنه ترك ثوبه في يدها وهرب إلى خارج '),
(14909, 'Genesis', 1, 39, 14, ' أنها نادت أهل بيتها ، وكلمتهم قائلة : انظروا قد جاء إلينا برجل عبراني ليداعبنا دخل إلي ليضطجع معي ، فصرخت بصوت عظيم '),
(14910, 'Genesis', 1, 39, 15, ' وكان لما سمع أني رفعت صوتي وصرخت ، أنه ترك ثوبه بجانبي وهرب وخرج إلى خارج '),
(14911, 'Genesis', 1, 39, 16, ' فوضعت ثوبه بجانبها حتى جاء سيده إلى بيته '),
(14912, 'Genesis', 1, 39, 17, ' فكلمته بمثل هذا الكلام قائلة : دخل إلي العبد العبراني الذي جئت به إلينا ليداعبني '),
(14913, 'Genesis', 1, 39, 18, ' وكان لما رفعت صوتي وصرخت ، أنه ترك ثوبه بجانبي وهرب إلى خارج '),
(14914, 'Genesis', 1, 39, 19, ' فكان لما سمع سيده كلام امرأته الذي كلمته به قائلة : بحسب هذا الكلام صنع بي عبدك ، أن غضبه حمي '),
(14915, 'Genesis', 1, 39, 20, ' فأخذ يوسف سيده ووضعه في بيت السجن ، المكان الذي كان أسرى الملك محبوسين فيه . وكان هناك في بيت السجن '),
(14916, 'Genesis', 1, 39, 21, ' ولكن الرب كان مع يوسف ، وبسط إليه لطفا ، وجعل نعمة له في عيني رئيس بيت السجن '),
(14917, 'Genesis', 1, 39, 22, ' فدفع رئيس بيت السجن إلى يد يوسف جميع الأسرى الذين في بيت السجن . وكل ما كانوا يعملون هناك كان هو العامل '),
(14918, 'Genesis', 1, 39, 23, ' ولم يكن رئيس بيت السجن ينظر شيئا البتة مما في يده ، لأن الرب كان معه ، ومهما صنع كان الرب ينجحه '),
(14919, 'Genesis', 1, 40, 1, ' وحدث بعد هذه الأمور أن ساقي ملك مصر والخباز أذنبا إلى سيدهما ملك مصر '),
(14920, 'Genesis', 1, 40, 2, ' فسخط فرعون على خصييه : رئيس السقاة ورئيس الخبازين '),
(14921, 'Genesis', 1, 40, 3, ' فوضعهما في حبس بيت رئيس الشرط ، في بيت السجن ، المكان الذي كان يوسف محبوسا فيه '),
(14922, 'Genesis', 1, 40, 4, ' فأقام رئيس الشرط يوسف عندهما فخدمهما . وكانا أياما في الحبس '),
(14923, 'Genesis', 1, 40, 5, ' وحلما كلاهما حلما في ليلة واحدة ، كل واحد حلمه ، كل واحد بحسب تعبير حلمه ، ساقي ملك مصر وخبازه ، المحبوسان في بيت السجن '),
(14924, 'Genesis', 1, 40, 6, ' فدخل يوسف إليهما في الصباح ونظرهما ، وإذا هما مغتمان '),
(14925, 'Genesis', 1, 40, 7, ' فسأل خصيي فرعون اللذين معه في حبس بيت سيده قائلا : لماذا وجهاكما مكمدان اليوم '),
(14926, 'Genesis', 1, 40, 8, ' فقالا له : حلمنا حلما وليس من يعبره . فقال لهما يوسف : أليست لله التعابير ؟ قصا علي '),
(14927, 'Genesis', 1, 40, 9, ' فقص رئيس السقاة حلمه على يوسف وقال له : كنت في حلمي وإذا كرمة أمامي '),
(14928, 'Genesis', 1, 40, 10, ' وفي الكرمة ثلاثة قضبان ، وهي إذ أفرخت طلع زهرها ، وأنضجت عناقيدها عنبا '),
(14929, 'Genesis', 1, 40, 11, ' وكانت كأس فرعون في يدي ، فأخذت العنب وعصرته في كأس فرعون ، وأعطيت الكأس في يد فرعون '),
(14930, 'Genesis', 1, 40, 12, ' فقال له يوسف : هذا تعبيره : الثلاثة القضبان هي ثلاثة أيام '),
(14931, 'Genesis', 1, 40, 13, ' في ثلاثة أيام أيضا يرفع فرعون رأسك ويردك إلى مقامك ، فتعطي كأس فرعون في يده كالعادة الأولى حين كنت ساقيه '),
(14932, 'Genesis', 1, 40, 14, ' وإنما إذا ذكرتني عندك حينما يصير لك خير ، تصنع إلي إحسانا وتذكرني لفرعون ، وتخرجني من هذا البيت '),
(14933, 'Genesis', 1, 40, 15, ' لأني قد سرقت من أرض العبرانيين ، وهنا أيضا لم أفعل شيئا حتى وضعوني في السجن '),
(14934, 'Genesis', 1, 40, 16, ' فلما رأى رئيس الخبازين أنه عبر جيدا ، قال ليوسف : كنت أنا أيضا في حلمي وإذا ثلاثة سلال حوارى على رأسي '),
(14935, 'Genesis', 1, 40, 17, ' وفي السل الأعلى من جميع طعام فرعون من صنعة الخباز . والطيور تأكله من السل عن رأسي '),
(14936, 'Genesis', 1, 40, 18, ' فأجاب يوسف وقال : هذا تعبيره : الثلاثة السلال هي ثلاثة أيام '),
(14937, 'Genesis', 1, 40, 19, ' في ثلاثة أيام أيضا يرفع فرعون رأسك عنك ، ويعلقك على خشبة ، وتأكل الطيور لحمك عنك '),
(14938, 'Genesis', 1, 40, 20, ' فحدث في اليوم الثالث ، يوم ميلاد فرعون ، أنه صنع وليمة لجميع عبيده ، ورفع رأس رئيس السقاة ورأس رئيس الخبازين بين عبيده '),
(14939, 'Genesis', 1, 40, 21, ' ورد رئيس السقاة إلى سقيه ، فأعطى الكأس في يد فرعون '),
(14940, 'Genesis', 1, 40, 22, ' وأما رئيس الخبازين فعلقه ، كما عبر لهما يوسف '),
(14941, 'Genesis', 1, 40, 23, ' ولكن لم يذكر رئيس السقاة يوسف بل نسيه '),
(14942, 'Genesis', 1, 41, 1, ' وحدث من بعد سنتين من الزمان أن فرعون رأى حلما : وإذا هو واقف عند النهر '),
(14943, 'Genesis', 1, 41, 2, ' وهوذا سبع بقرات طالعة من النهر حسنة المنظر وسمينة اللحم ، فارتعت في روضة '),
(14944, 'Genesis', 1, 41, 3, ' ثم هوذا سبع بقرات أخرى طالعة وراءها من النهر قبيحة المنظر ورقيقة اللحم ، فوقفت بجانب البقرات الأولى على شاطئ النهر '),
(14945, 'Genesis', 1, 41, 4, ' فأكلت البقرات القبيحة المنظر والرقيقة اللحم البقرات السبع الحسنة المنظر والسمينة . واستيقظ فرعون '),
(14946, 'Genesis', 1, 41, 5, ' ثم نام فحلم ثانية : وهوذا سبع سنابل طالعة في ساق واحد سمينة وحسنة '),
(14947, 'Genesis', 1, 41, 6, ' ثم هوذا سبع سنابل رقيقة وملفوحة بالريح الشرقية نابتة وراءها '),
(14948, 'Genesis', 1, 41, 7, ' فابتلعت السنابل الرقيقة السنابل السبع السمينة الممتلئة . واستيقظ فرعون ، وإذا هو حلم '),
(14949, 'Genesis', 1, 41, 8, ' وكان في الصباح أن نفسه انزعجت ، فأرسل ودعا جميع سحرة مصر وجميع حكمائها . وقص عليهم فرعون حلمه ، فلم يكن من يعبره لفرعون '),
(14950, 'Genesis', 1, 41, 9, ' ثم كلم رئيس السقاة فرعون قائلا : أنا أتذكر اليوم خطاياي '),
(14951, 'Genesis', 1, 41, 10, ' فرعون سخط على عبديه ، فجعلني في حبس بيت رئيس الشرط أنا ورئيس الخبازين '),
(14952, 'Genesis', 1, 41, 11, ' فحلمنا حلما في ليلة واحدة أنا وهو . حلمنا كل واحد بحسب تعبير حلمه '),
(14953, 'Genesis', 1, 41, 12, ' وكان هناك معنا غلام عبراني عبد لرئيس الشرط ، فقصصنا عليه ، فعبر لنا حلمينا . عبر لكل واحد بحسب حلمه '),
(14954, 'Genesis', 1, 41, 13, ' وكما عبر لنا هكذا حدث . ردني أنا إلى مقامي ، وأما هو فعلقه '),
(14955, 'Genesis', 1, 41, 14, ' فأرسل فرعون ودعا يوسف ، فأسرعوا به من السجن . فحلق وأبدل ثيابه ودخل على فرعون '),
(14956, 'Genesis', 1, 41, 15, ' فقال فرعون ليوسف : حلمت حلما وليس من يعبره . وأنا سمعت عنك قولا ، إنك تسمع أحلاما لتعبرها '),
(14957, 'Genesis', 1, 41, 16, ' فأجاب يوسف فرعون قائلا : ليس لي . الله يجيب بسلامة فرعون '),
(14958, 'Genesis', 1, 41, 17, ' فقال فرعون ليوسف : إني كنت في حلمي واقفا على شاطئ النهر '),
(14959, 'Genesis', 1, 41, 18, ' وهوذا سبع بقرات طالعة من النهر سمينة اللحم وحسنة الصورة ، فارتعت في روضة '),
(14960, 'Genesis', 1, 41, 19, ' ثم هوذا سبع بقرات أخرى طالعة وراءها مهزولة وقبيحة الصورة جدا ورقيقة اللحم . لم أنظر في كل أرض مصر مثلها في القباحة '),
(14961, 'Genesis', 1, 41, 20, ' فأكلت البقرات الرقيقة والقبيحة البقرات السبع الأولى السمينة '),
(14962, 'Genesis', 1, 41, 21, ' فدخلت أجوافها ، ولم يعلم أنها دخلت في أجوافها ، فكان منظرها قبيحا كما في الأول . واستيقظت '),
(14963, 'Genesis', 1, 41, 22, ' ثم رأيت في حلمي وهوذا سبع سنابل طالعة في ساق واحد ممتلئة وحسنة '),
(14964, 'Genesis', 1, 41, 23, ' ثم هوذا سبع سنابل يابسة رقيقة ملفوحة بالريح الشرقية نابتة وراءها '),
(14965, 'Genesis', 1, 41, 24, ' فابتلعت السنابل الرقيقة السنابل السبع الحسنة . فقلت للسحرة ، ولم يكن من يخبرني '),
(14966, 'Genesis', 1, 41, 25, ' فقال يوسف لفرعون : حلم فرعون واحد . قد أخبر الله فرعون بما هو صانع '),
(14967, 'Genesis', 1, 41, 26, ' البقرات السبع الحسنة هي سبع سنين ، والسنابل السبع الحسنة هي سبع سنين . هو حلم واحد '),
(14968, 'Genesis', 1, 41, 27, ' والبقرات السبع الرقيقة القبيحة التي طلعت وراءها هي سبع سنين ، والسنابل السبع الفارغة الملفوحة بالريح الشرقية تكون سبع سنين جوعا '),
(14969, 'Genesis', 1, 41, 28, ' هو الأمر الذي كلمت به فرعون . قد أظهر الله لفرعون ما هو صانع '),
(14970, 'Genesis', 1, 41, 29, ' هوذا سبع سنين قادمة شبعا عظيما في كل أرض مصر '),
(14971, 'Genesis', 1, 41, 30, ' ثم تقوم بعدها سبع سنين جوعا ، فينسى كل الشبع في أرض مصر ويتلف الجوع الأرض '),
(14972, 'Genesis', 1, 41, 31, ' ولا يعرف الشبع في الأرض من أجل ذلك الجوع بعده ، لأنه يكون شديدا جدا '),
(14973, 'Genesis', 1, 41, 32, ' وأما عن تكرار الحلم على فرعون مرتين ، فلأن الأمر مقرر من قبل الله ، والله مسرع ليصنعه '),
(14974, 'Genesis', 1, 41, 33, ' فالآن لينظر فرعون رجلا بصيرا وحكيما ويجعله على أرض مصر '),
(14975, 'Genesis', 1, 41, 34, ' يفعل فرعون فيوكل نظارا على الأرض ، ويأخذ خمس غلة أرض مصر في سبع سني الشبع '),
(14976, 'Genesis', 1, 41, 35, ' فيجمعون جميع طعام هذه السنين الجيدة القادمة ، ويخزنون قمحا تحت يد فرعون طعاما في المدن ويحفظونه '),
(14977, 'Genesis', 1, 41, 36, ' فيكون الطعام ذخيرة للأرض لسبع سني الجوع التي تكون في أرض مصر ، فلا تنقرض الأرض بالجوع '),
(14978, 'Genesis', 1, 41, 37, ' فحسن الكلام في عيني فرعون وفي عيون جميع عبيده '),
(14979, 'Genesis', 1, 41, 38, ' فقال فرعون لعبيده : هل نجد مثل هذا رجلا فيه روح الله '),
(14980, 'Genesis', 1, 41, 39, ' ثم قال فرعون ليوسف : بعد ما أعلمك الله كل هذا ، ليس بصير وحكيم مثلك '),
(14981, 'Genesis', 1, 41, 40, ' أنت تكون على بيتي ، وعلى فمك يقبل جميع شعبي إلا إن الكرسي أكون فيه أعظم منك '),
(14982, 'Genesis', 1, 41, 41, ' ثم قال فرعون ليوسف : انظر ، قد جعلتك على كل أرض مصر '),
(14983, 'Genesis', 1, 41, 42, ' وخلع فرعون خاتمه من يده وجعله في يد يوسف ، وألبسه ثياب بوص ، ووضع طوق ذهب في عنقه '),
(14984, 'Genesis', 1, 41, 43, ' وأركبه في مركبته الثانية ، ونادوا أمامه اركعوا . وجعله على كل أرض مصر '),
(14985, 'Genesis', 1, 41, 44, ' وقال فرعون ليوسف : أنا فرعون . فبدونك لا يرفع إنسان يده ولا رجله في كل أرض مصر '),
(14986, 'Genesis', 1, 41, 45, ' ودعا فرعون اسم يوسف صفنات فعنيح ، وأعطاه أسنات بنت فوطي فارع كاهن أون زوجة . فخرج يوسف على أرض مصر '),
(14987, 'Genesis', 1, 41, 46, ' وكان يوسف ابن ثلاثين سنة لما وقف قدام فرعون ملك مصر . فخرج يوسف من لدن فرعون واجتاز في كل أرض مصر '),
(14988, 'Genesis', 1, 41, 47, ' وأثمرت الأرض في سبع سني الشبع بحزم '),
(14989, 'Genesis', 1, 41, 48, ' فجمع كل طعام السبع سنين التي كانت في أرض مصر ، وجعل طعاما في المدن . طعام حقل المدينة الذي حواليها جعله فيها '),
(14990, 'Genesis', 1, 41, 49, ' وخزن يوسف قمحا كرمل البحر ، كثيرا جدا حتى ترك العدد ، إذ لم يكن له عدد '),
(14991, 'Genesis', 1, 41, 50, ' وولد ليوسف ابنان قبل أن تأتي سنة الجوع ، ولدتهما له أسنات بنت فوطي فارع كاهن أون '),
(14992, 'Genesis', 1, 41, 51, ' ودعا يوسف اسم البكر منسى قائلا : لأن الله أنساني كل تعبي وكل بيت أبي '),
(14993, 'Genesis', 1, 41, 52, ' ودعا اسم الثانى أفرايم قائلا : لأن الله جعلني مثمرا في أرض مذلتي '),
(14994, 'Genesis', 1, 41, 53, ' ثم كملت سبع سني الشبع الذي كان في أرض مصر '),
(14995, 'Genesis', 1, 41, 54, ' وابتدأت سبع سني الجوع تأتي كما قال يوسف ، فكان جوع في جميع البلدان . وأما جميع أرض مصر فكان فيها خبز '),
(14996, 'Genesis', 1, 41, 55, ' ولما جاعت جميع أرض مصر وصرخ الشعب إلى فرعون لأجل الخبز ، قال فرعون لكل المصريين : اذهبوا إلى يوسف ، والذي يقول لكم افعلوا '),
(14997, 'Genesis', 1, 41, 56, ' وكان الجوع على كل وجه الأرض ، وفتح يوسف جميع ما فيه طعام وباع للمصريين . واشتد الجوع في أرض مصر '),
(14998, 'Genesis', 1, 41, 57, ' وجاءت كل الأرض إلى مصر إلى يوسف لتشتري قمحا ، لأن الجوع كان شديدا في كل الأرض '),
(14999, 'Genesis', 1, 42, 1, ' فلما رأى يعقوب أنه يوجد قمح في مصر ، قال يعقوب لبنيه : لماذا تنظرون بعضكم إلى بعض '),
(15000, 'Genesis', 1, 42, 2, ' وقال إني قد سمعت أنه يوجد قمح في مصر . انزلوا إلى هناك واشتروا لنا من هناك لنحيا ولا نموت '),
(15001, 'Genesis', 1, 42, 3, ' فنزل عشرة من إخوة يوسف ليشتروا قمحا من مصر '),
(15002, 'Genesis', 1, 42, 4, ' وأما بنيامين أخو يوسف فلم يرسله يعقوب مع إخوته ، لأنه قال : لعله تصيبه أذية '),
(15003, 'Genesis', 1, 42, 5, ' فأتى بنو إسرائيل ليشتروا بين الذين أتوا ، لأن الجوع كان في أرض كنعان '),
(15004, 'Genesis', 1, 42, 6, ' وكان يوسف هو المسلط على الأرض ، وهو البائع لكل شعب الأرض . فأتى إخوة يوسف وسجدوا له بوجوههم إلى الأرض '),
(15005, 'Genesis', 1, 42, 7, ' ولما نظر يوسف إخوته عرفهم ، فتنكر لهم وتكلم معهم بجفاء ، وقال لهم : من أين جئتم ؟ فقالوا : من أرض كنعان لنشتري طعاما '),
(15006, 'Genesis', 1, 42, 8, ' وعرف يوسف إخوته ، وأما هم فلم يعرفوه '),
(15007, 'Genesis', 1, 42, 9, ' فتذكر يوسف الأحلام التي حلم عنهم ، وقال لهم : جواسيس أنتم لتروا عورة الأرض جئتم '),
(15008, 'Genesis', 1, 42, 10, ' فقالوا له : لا يا سيدي ، بل عبيدك جاءوا ليشتروا طعاما '),
(15009, 'Genesis', 1, 42, 11, ' نحن جميعنا بنو رجل واحد . نحن أمناء ، ليس عبيدك جواسيس '),
(15010, 'Genesis', 1, 42, 12, ' فقال لهم : كلا بل لتروا عورة الأرض جئتم '),
(15011, 'Genesis', 1, 42, 13, ' فقالوا : عبيدك اثنا عشر أخا . نحن بنو رجل واحد في أرض كنعان . وهوذا الصغير عند أبينا اليوم ، والواحد مفقود '),
(15012, 'Genesis', 1, 42, 14, ' فقال لهم يوسف : ذلك ما كلمتكم به قائلا : جواسيس أنتم '),
(15013, 'Genesis', 1, 42, 15, ' بهذا تمتحنون . وحياة فرعون لا تخرجون من هنا إلا بمجيء أخيكم الصغير إلى هنا '),
(15014, 'Genesis', 1, 42, 16, ' أرسلوا منكم واحدا ليجيء بأخيكم ، وأنتم تحبسون ، فيمتحن كلامكم هل عندكم صدق . وإلا فوحياة فرعون إنكم لجواسيس '),
(15015, 'Genesis', 1, 42, 17, ' فجمعهم إلى حبس ثلاثة أيام '),
(15016, 'Genesis', 1, 42, 18, ' ثم قال لهم يوسف في اليوم الثالث : افعلوا هذا واحيوا . أنا خائف الله '),
(15017, 'Genesis', 1, 42, 19, ' إن كنتم أمناء فليحبس أخ واحد منكم في بيت حبسكم ، وانطلقوا أنتم وخذوا قمحا لمجاعة بيوتكم '),
(15018, 'Genesis', 1, 42, 20, ' وأحضروا أخاكم الصغير إلي ، فيتحقق كلامكم ولا تموتوا . ففعلوا هكذا '),
(15019, 'Genesis', 1, 42, 21, ' وقالوا بعضهم لبعض : حقا إننا مذنبون إلى أخينا الذي رأينا ضيقة نفسه لما استرحمنا ولم نسمع . لذلك جاءت علينا هذه الضيقة '),
(15020, 'Genesis', 1, 42, 22, ' فأجابهم رأوبين قائلا : ألم أكلمكم قائلا : لاتأثموا بالولد ، وأنتم لم تسمعوا ؟ فهوذا دمه يطلب '),
(15021, 'Genesis', 1, 42, 23, ' وهم لم يعلموا أن يوسف فاهم لأن الترجمان كان بينهم '),
(15022, 'Genesis', 1, 42, 24, ' فتحول عنهم وبكى ، ثم رجع إليهم وكلمهم ، وأخذ منهم شمعون وقيده أمام عيونهم '),
(15023, 'Genesis', 1, 42, 25, ' ثم أمر يوسف أن تملأ أوعيتهم قمحا ، وترد فضة كل واحد إلى عدله ، وأن يعطوا زادا للطريق . ففعل لهم هكذا '),
(15024, 'Genesis', 1, 42, 26, ' فحملوا قمحهم على حميرهم ومضوا من هناك '),
(15025, 'Genesis', 1, 42, 27, ' فلما فتح أحدهم عدله ليعطي عليقا لحماره في المنزل ، رأى فضته وإذا هي في فم عدله '),
(15026, 'Genesis', 1, 42, 28, ' فقال لإخوته : ردت فضتي وها هي في عدلي . فطارت قلوبهم وارتعدوا بعضهم في بعض قائلين : ما هذا الذي صنعه الله بنا '),
(15027, 'Genesis', 1, 42, 29, ' فجاءوا إلى يعقوب أبيهم إلى أرض كنعان ، وأخبروه بكل ما أصابهم قائلين '),
(15028, 'Genesis', 1, 42, 30, ' تكلم معنا الرجل سيد الأرض بجفاء ، وحسبنا جواسيس الأرض '),
(15029, 'Genesis', 1, 42, 31, ' فقلنا له : نحن أمناء ، لسنا جواسيس '),
(15030, 'Genesis', 1, 42, 32, ' نحن اثنا عشر أخا بنو أبينا . الواحد مفقود والصغير اليوم عند أبينا في أرض كنعان '),
(15031, 'Genesis', 1, 42, 33, ' فقال لنا الرجل سيد الأرض : بهذا أعرف أنكم أمناء . دعوا أخا واحدا منكم عندي ، وخذوا لمجاعة بيوتكم وانطلقوا '),
(15032, 'Genesis', 1, 42, 34, ' وأحضروا أخاكم الصغير إلي فأعرف أنكم لستم جواسيس ، بل أنكم أمناء ، فأعطيكم أخاكم وتتجرون في الأرض '),
(15033, 'Genesis', 1, 42, 35, ' وإذ كانوا يفرغون عدالهم إذا صرة فضة كل واحد في عدله . فلما رأوا صرر فضتهم هم وأبوهم خافوا '),
(15034, 'Genesis', 1, 42, 36, ' فقال لهم يعقوب : أعدمتموني الأولاد . يوسف مفقود ، وشمعون مفقود ، وبنيامين تأخذونه . صار كل هذا علي '),
(15035, 'Genesis', 1, 42, 37, ' وكلم رأوبين أباه قائلا : اقتل ابني إن لم أجئ به إليك . سلمه بيدي وأنا أرده إليك '),
(15036, 'Genesis', 1, 42, 38, ' فقال : لا ينزل ابني معكم ، لأن أخاه قد مات ، وهو وحده باق . فإن أصابته أذية في الطريق التي تذهبون فيها تنزلون شيبتي بحزن إلى الهاوية '),
(15037, 'Genesis', 1, 43, 1, ' وكان الجوع شديدا في الأرض '),
(15038, 'Genesis', 1, 43, 2, ' وحدث لما فرغوا من أكل القمح الذي جاءوا به من مصر ، أن أباهم قال لهم : ارجعوا اشتروا لنا قليلا من الطعام '),
(15039, 'Genesis', 1, 43, 3, ' فكلمه يهوذا قائلا : إن الرجل قد أشهد علينا قائلا : لا ترون وجهي بدون أن يكون أخوكم معكم '),
(15040, 'Genesis', 1, 43, 4, ' إن كنت ترسل أخانا معنا ، ننزل ونشتري لك طعاما '),
(15041, 'Genesis', 1, 43, 5, ' ولكن إن كنت لا ترسله لا ننزل . لأن الرجل قال لنا : لا ترون وجهي بدون أن يكون أخوكم معكم '),
(15042, 'Genesis', 1, 43, 6, ' فقال إسرائيل : لماذا أسأتم إلي حتى أخبرتم الرجل أن لكم أخا أيضا '),
(15043, 'Genesis', 1, 43, 7, ' فقالوا : إن الرجل قد سأل عنا وعن عشيرتنا ، قائلا : هل أبوكم حي بعد ؟ هل لكم أخ ؟ فأخبرناه بحسب هذا الكلام . هل كنا نعلم أنه يقول : انزلوا بأخيكم '),
(15044, 'Genesis', 1, 43, 8, ' وقال يهوذا لإسرائيل أبيه : أرسل الغلام معي لنقوم ونذهب ونحيا ولا نموت ، نحن وأنت وأولادنا جميعا '),
(15045, 'Genesis', 1, 43, 9, ' أنا أضمنه . من يدي تطلبه . إن لم أجئ به إليك وأوقفه قدامك ، أصر مذنبا إليك كل الأيام '),
(15046, 'Genesis', 1, 43, 10, ' لأننا لو لم نتوان لكنا قد رجعنا الآن مرتين '),
(15047, 'Genesis', 1, 43, 11, ' فقال لهم إسرائيل أبوهم : إن كان هكذا فافعلوا هذا : خذوا من أفخر جنى الأرض في أوعيتكم ، وأنزلوا للرجل هدية . قليلا من البلسان ، وقليلا من العسل ، وكثيراء ولاذنا وفستقا ولوزا '),
(15048, 'Genesis', 1, 43, 12, ' وخذوا فضة أخرى في أياديكم . والفضة المردودة في أفواه عدالكم ردوها في أياديكم ، لعله كان سهوا '),
(15049, 'Genesis', 1, 43, 13, ' وخذوا أخاكم وقوموا ارجعوا إلى الرجل '),
(15050, 'Genesis', 1, 43, 14, ' والله القدير يعطيكم رحمة أمام الرجل حتى يطلق لكم أخاكم الآخر وبنيامين . وأنا إذا عدمت الأولاد عدمتهم '),
(15051, 'Genesis', 1, 43, 15, ' فأخذ الرجال هذه الهدية ، وأخذوا ضعف الفضة في أياديهم ، وبنيامين ، وقاموا ونزلوا إلى مصر ووقفوا أمام يوسف '),
(15052, 'Genesis', 1, 43, 16, ' فلما رأى يوسف بنيامين معهم ، قال للذي على بيته : أدخل الرجال إلى البيت واذبح ذبيحة وهيئ ، لأن الرجال يأكلون معي عند الظهر '),
(15053, 'Genesis', 1, 43, 17, ' ففعل الرجل كما قال يوسف . وأدخل الرجل الرجال إلى بيت يوسف '),
(15054, 'Genesis', 1, 43, 18, ' فخاف الرجال إذ أدخلوا إلى بيت يوسف ، وقالوا : لسبب الفضة التي رجعت أولا في عدالنا نحن قد أدخلنا ليهجم علينا ويقع بنا ويأخذنا عبيدا وحميرنا '),
(15055, 'Genesis', 1, 43, 19, ' فتقدموا إلى الرجل الذي على بيت يوسف ، وكلموه في باب البيت '),
(15056, 'Genesis', 1, 43, 20, ' وقالوا : استمع يا سيدي ، إننا قد نزلنا أولا لنشتري طعاما '),
(15057, 'Genesis', 1, 43, 21, ' وكان لما أتينا إلى المنزل أننا فتحنا عدالنا ، وإذا فضة كل واحد في فم عدله . فضتنا بوزنها . فقد رددناها في أيادينا '),
(15058, 'Genesis', 1, 43, 22, ' وأنزلنا فضة أخرى في أيادينا لنشتري طعاما . لا نعلم من وضع فضتنا في عدالنا '),
(15059, 'Genesis', 1, 43, 23, ' فقال : سلام لكم ، لا تخافوا . إلهكم وإله أبيكم أعطاكم كنزا في عدالكم . فضتكم وصلت إلي . ثم أخرج إليهم شمعون '),
(15060, 'Genesis', 1, 43, 24, ' وأدخل الرجل الرجال إلى بيت يوسف وأعطاهم ماء ليغسلوا أرجلهم ، وأعطى عليقا لحميرهم '),
(15061, 'Genesis', 1, 43, 25, ' وهيأوا الهدية إلى أن يجيء يوسف عند الظهر ، لأنهم سمعوا أنهم هناك يأكلون طعاما '),
(15062, 'Genesis', 1, 43, 26, ' فلما جاء يوسف إلى البيت أحضروا إليه الهدية التي في أياديهم إلى البيت ، وسجدوا له إلى الأرض '),
(15063, 'Genesis', 1, 46, 5, ' فقام يعقوب من بئر سبع ، وحمل بنو إسرائيل يعقوب أباهم وأولادهم ونساءهم في العجلات التي أرسل فرعون لحمله '),
(15064, 'Genesis', 1, 46, 6, ' وأخذوا مواشيهم ومقتناهم الذي اقتنوا في أرض كنعان ، وجاءوا إلى مصر . يعقوب وكل نسله معه '),
(15065, 'Genesis', 1, 46, 7, ' بنوه وبنو بنيه معه ، وبناته وبنات بنيه وكل نسله ، جاء بهم معه إلى مصر '),
(15066, 'Genesis', 1, 46, 8, ' وهذه أسماء بني إسرائيل الذين جاءوا إلى مصر : يعقوب وبنوه . بكر يعقوب رأوبين '),
(15067, 'Genesis', 1, 46, 9, ' وبنو رأوبين : حنوك وفلو وحصرون وكرمي '),
(15068, 'Genesis', 1, 46, 10, ' وبنو شمعون : يموئيل ويامين وأوهد وياكين وصوحر وشأول ابن الكنعانية '),
(15069, 'Genesis', 1, 46, 11, ' وبنو لاوي : جرشون وقهات ومراري '),
(15070, 'Genesis', 1, 46, 12, ' وبنو يهوذا : عير وأونان وشيلة وفارص وزارح . وأما عير وأونان فماتا في أرض كنعان . وكان ابنا فارص : حصرون وحامول '),
(15071, 'Genesis', 1, 46, 13, ' وبنو يساكر : تولاع وفوة ويوب وشمرون '),
(15072, 'Genesis', 1, 46, 14, ' وبنو زبولون : سارد وإيلون وياحلئيل '),
(15073, 'Genesis', 1, 46, 15, ' هؤلاء بنو ليئة الذين ولدتهم ليعقوب في فدان أرام مع دينة ابنته . جميع نفوس بنيه وبناته ثلاث وثلاثون '),
(15074, 'Genesis', 1, 46, 16, ' وبنو جاد : صفيون وحجي وشوني وأصبون وعيري وأرودي وأرئيلي '),
(15075, 'Genesis', 1, 46, 17, ' وبنو أشير : يمنة ويشوة ويشوي وبريعة ، وسارح هي أختهم . وابنا بريعة : حابر وملكيئيل '),
(15076, 'Genesis', 1, 46, 18, ' هؤلاء بنو زلفة التي أعطاها لابان لليئة ابنته ، فولدت هؤلاء ليعقوب ، ست عشرة نفسا '),
(15077, 'Genesis', 1, 46, 19, ' ابنا راحيل امرأة يعقوب : يوسف وبنيامين '),
(15078, 'Genesis', 1, 46, 20, ' وولد ليوسف في أرض مصر : منسى وأفرايم ، اللذان ولدتهما له أسنات بنت فوطي فارع كاهن أون '),
(15079, 'Genesis', 1, 46, 21, ' وبنو بنيامين : بالع وباكر وأشبيل وجيرا ونعمان وإيحي وروش ومفيم وحفيم وأرد '),
(15080, 'Genesis', 1, 46, 22, ' هؤلاء بنو راحيل الذين ولدوا ليعقوب . جميع النفوس أربع عشرة '),
(15081, 'Genesis', 1, 46, 23, ' وابن دان : حوشيم '),
(15082, 'Genesis', 1, 46, 24, ' وبنو نفتالي : ياحصئيل وجوني ويصر وشليم '),
(15083, 'Genesis', 1, 46, 25, ' هؤلاء بنو بلهة التي أعطاها لابان لراحيل ابنته . فولدت هؤلاء ليعقوب . جميع الانفس سبع '),
(15084, 'Genesis', 1, 46, 26, ' جميع النفوس ليعقوب التي أتت إلى مصر ، الخارجة من صلبه ، ما عدا نساء بني يعقوب ، جميع النفوس ست وستون نفسا '),
(15085, 'Genesis', 1, 46, 27, ' وابنا يوسف اللذان ولدا له في مصر نفسان . جميع نفوس بيت يعقوب التي جاءت إلى مصر سبعون '),
(15086, 'Genesis', 1, 46, 28, ' فأرسل يهوذا أمامه إلى يوسف ليري الطريق أمامه إلى جاسان ، ثم جاءوا إلى أرض جاسان '),
(15087, 'Genesis', 1, 46, 29, ' فشد يوسف مركبته وصعد لاستقبال إسرائيل أبيه إلى جاسان . ولما ظهر له وقع على عنقه وبكى على عنقه زمانا '),
(15088, 'Genesis', 1, 46, 30, ' فقال إسرائيل ليوسف : أموت الان بعد ما رأيت وجهك أنك حي بعد '),
(15089, 'Genesis', 1, 46, 31, ' ثم قال يوسف لاخوته ولبيت أبيه : أصعد وأخبر فرعون وأقول له : إخوتي وبيت أبي الذين في أرض كنعان جاءوا إلي '),
(15090, 'Genesis', 1, 46, 32, ' والرجال رعاة غنم ، فإنهم كانوا أهل مواش ، وقد جاءوا بغنمهم وبقرهم وكل ما لهم '),
(15091, 'Genesis', 1, 46, 33, ' فيكون إذا دعاكم فرعون وقال : ما صناعتكم '),
(15092, 'Genesis', 1, 46, 34, ' أن تقولوا : عبيدك أهل مواش منذ صبانا إلى الان ، نحن وآباؤنا جميعا . لكي تسكنوا في أرض جاسان . لان كل راعي غنم رجس للمصريين '),
(15093, 'Genesis', 1, 47, 1, ' فأتى يوسف وأخبر فرعون وقال : أبي وإخوتي وغنمهم وبقرهم وكل ما لهم جاءوا من أرض كنعان ، وهوذا هم في أرض جاسان '),
(15094, 'Genesis', 1, 47, 2, ' وأخذ من جملة إخوته خمسة رجال وأوقفهم أمام فرعون '),
(15095, 'Genesis', 1, 47, 3, ' فقال فرعون لاخوته : ما صناعتكم ؟ فقالوا لفرعون : عبيدك رعاة غنم نحن وآباؤنا جميعا '),
(15096, 'Genesis', 1, 47, 4, ' وقالوا لفرعون : جئنا لنتغرب في الارض ، إذ ليس لغنم عبيدك مرعى ، لان الجوع شديد في أرض كنعان . فالان ليسكن عبيدك في أرض جاسان '),
(15097, 'Genesis', 1, 47, 5, ' فكلم فرعون يوسف قائلا : أبوك وإخوتك جاءوا إليك '),
(15098, 'Genesis', 1, 47, 6, ' أرض مصر قدامك . في أفضل الارض أسكن أباك وإخوتك ، ليسكنوا في أرض جاسان . وإن علمت أنه يوجد بينهم ذوو قدرة ، فاجعلهم رؤساء مواش على التي لي '),
(15099, 'Genesis', 1, 47, 7, ' ثم أدخل يوسف يعقوب أباه وأوقفه أمام فرعون . وبارك يعقوب فرعون '),
(15100, 'Genesis', 1, 47, 8, ' فقال فرعون ليعقوب : كم هي أيام سني حياتك '),
(15101, 'Genesis', 1, 47, 9, ' فقال يعقوب لفرعون : أيام سني غربتي مئة وثلاثون سنة . قليلة و ردية كانت أيام سني حياتي ، ولم تبلغ إلى أيام سني حياة آبائي في أيام غربتهم '),
(15102, 'Genesis', 1, 47, 10, ' وبارك يعقوب فرعون وخرج من لدن فرعون '),
(15103, 'Genesis', 1, 47, 11, ' فأسكن يوسف أباه وإخوته وأعطاهم ملكا في أرض مصر ، في أفضل الارض ، في أرض رعمسيس كما أمر فرعون '),
(15104, 'Genesis', 1, 47, 12, ' وعال يوسف أباه وإخوته وكل بيت أبيه بطعام على حسب الاولاد '),
(15105, 'Genesis', 1, 47, 13, ' ولم يكن خبز في كل الارض ، لان الجوع كان شديدا جدا . فخورت أرض مصر وأرض كنعان من أجل الجوع '),
(15106, 'Genesis', 1, 47, 14, ' فجمع يوسف كل الفضة الموجودة في أرض مصر وفي أرض كنعان بالقمح الذي اشتروا ، وجاء يوسف بالفضة إلى بيت فرعون '),
(15107, 'Genesis', 1, 47, 15, ' فلما فرغت الفضة من أرض مصر ومن أرض كنعان أتى جميع المصريين إلى يوسف قائلين : أعطنا خبزا ، فلماذا نموت قدامك ؟ لان ليس فضة أيضا '),
(15108, 'Genesis', 1, 47, 16, ' فقال يوسف : هاتوا مواشيكم فأعطيكم بمواشيكم ، إن لم يكن فضة أيضا '),
(15109, 'Genesis', 1, 47, 17, ' فجاءوا بمواشيهم إلى يوسف ، فأعطاهم يوسف خبزا بالخيل وبمواشي الغنم والبقر وبالحمير . فقاتهم بالخبز تلك السنة بدل جميع مواشيهم '),
(15110, 'Genesis', 1, 47, 18, ' ولما تمت تلك السنة أتوا إليه في السنة الثانية وقالوا له : لا نخفي عن سيدي أنه إذ قد فرغت الفضة ، ومواشي البهائم عند سيدي ، لم يبق قدام سيدي إلا أجسادنا وأرضنا '),
(15111, 'Genesis', 1, 47, 19, ' لماذا نموت أمام عينيك نحن وأرضنا جميعا ؟ اشترنا وأرضنا بالخبز ، فنصير نحن وأرضنا عبيدا لفرعون ، وأعط بذارا لنحيا ولا نموت ولا تصير أرضنا قفرا '),
(15112, 'Genesis', 1, 47, 20, ' فاشترى يوسف كل أرض مصر لفرعون ، إذ باع المصريون كل واحد حقله ، لان الجوع اشتد عليهم . فصارت الارض لفرعون '),
(15113, 'Genesis', 1, 47, 21, ' وأما الشعب فنقلهم إلى المدن من أقصى حد مصر إلى أقصاه '),
(15114, 'Genesis', 1, 47, 22, ' إلا إن أرض الكهنة لم يشترها ، إذ كانت للكهنة فريضة من قبل فرعون ، فأكلوا فريضتهم التي أعطاهم فرعون ، لذلك لم يبيعوا أرضهم '),
(15115, 'Genesis', 1, 47, 23, ' فقال يوسف للشعب : إني قد اشتريتكم اليوم وأرضكم لفرعون . هوذا لكم بذار فتزرعون الارض '),
(15116, 'Genesis', 1, 47, 24, ' ويكون عند الغلة أنكم تعطون خمسا لفرعون ، والاربعة الاجزاء تكون لكم بذارا للحقل ، وطعاما لكم ولمن في بيوتكم ، وطعاما لاولادكم '),
(15117, 'Genesis', 1, 47, 25, ' فقالوا : أحييتنا . ليتنا نجد نعمة في عيني سيدي فنكون عبيدا لفرعون '),
(15118, 'Genesis', 1, 47, 26, ' فجعلها يوسف فرضا على أرض مصر إلى هذا اليوم : لفرعون الخمس . إلا إن أرض الكهنة وحدهم لم تصر لفرعون '),
(15119, 'Genesis', 1, 47, 27, ' وسكن إسرائيل في أرض مصر ، في أرض جاسان ، وتملكوا فيها وأثمروا وكثروا جدا '),
(15120, 'Genesis', 1, 47, 28, ' وعاش يعقوب في أرض مصر سبع عشرة سنة . فكانت أيام يعقوب ، سنو حياته مئة وسبعا وأربعين سنة '),
(15121, 'Genesis', 1, 47, 29, ' ولما قربت أيام إسرائيل أن يموت دعا ابنه يوسف وقال له : إن كنت قد وجدت نعمة في عينيك فضع يدك تحت فخذي واصنع معي معروفا وأمانة : لا تدفني في مصر '),
(15122, 'Genesis', 1, 47, 30, ' بل أضطجع مع آبائي ، فتحملني من مصر وتدفنني في مقبرتهم . فقال : أنا أفعل بحسب قولك '),
(15123, 'Genesis', 1, 47, 31, ' فقال : احلف لي . فحلف له . فسجد إسرائيل على رأس السرير '),
(15124, 'Genesis', 1, 48, 1, ' وحدث بعد هذه الأمور أنه قيل ليوسف : هوذا أبوك مريض . فأخذ معه ابنيه منسى وأفرايم '),
(15125, 'Genesis', 1, 48, 2, ' فأخبر يعقوب وقيل له : هوذا ابنك يوسف قادم إليك . فتشدد إسرائيل وجلس على السرير '),
(15126, 'Genesis', 1, 48, 3, ' وقال يعقوب ليوسف : الله القادر على كل شيء ظهر لي في لوز ، في أرض كنعان ، وباركني ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(15127, 'Genesis', 1, 48, 4, ' وقال لي : ها أنا أجعلك مثمرا وأكثرك ، وأجعلك جمهورا من الأمم ، وأعطي نسلك هذه الأرض من بعدك ملكا أبديا '),
(15128, 'Genesis', 1, 48, 5, ' والآن ابناك المولودان لك في أرض مصر ، قبلما أتيت إليك إلى مصر هما لي . أفرايم ومنسى كرأوبين وشمعون يكونان لي '),
(15129, 'Genesis', 1, 48, 6, ' وأما أولأدك الذين تلد بعدهما فيكونون لك . على اسم أخويهم يسمون في نصيبهم '),
(15130, 'Genesis', 1, 48, 7, ' وأنا حين جئت من فدان ماتت عندي راحيل في أرض كنعان في الطريق ، إذ بقيت مسافة من الأرض حتى آتي إلى أفراتة ، فدفنتها هناك في طريق أفراتة ، التي هي بيت لحم '),
(15131, 'Genesis', 1, 48, 8, ' ورأى إسرائيل ابني يوسف فقال : من هذان '),
(15132, 'Genesis', 1, 48, 9, ' فقال يوسف لأبيه : هما ابناي اللذان أعطاني الله ههنا . فقال : قدمهما إلي لأباركهما '),
(15133, 'Genesis', 1, 48, 10, ' وأما عينا إسرائيل فكانتا قد ثقلتا من الشيخوخة ، لا يقدر أن يبصر ، فقربهما إليه فقبلهما واحتضنهما '),
(15134, 'Genesis', 1, 48, 11, ' وقال إسرائيل ليوسف : لم أكن أظن أني أرى وجهك ، وهوذا الله قد أراني نسلك أيضا '),
(15135, 'Genesis', 1, 48, 12, ' ثم أخرجهما يوسف من بين ركبتيه وسجد أمام وجهه إلى الأرض '),
(15136, 'Genesis', 1, 48, 13, ' وأخذ يوسف الاثنين أفرايم بيمينه عن يسار إسرائيل ، ومنسى بيساره عن يمين إسرائيل وقربهما إليه '),
(15137, 'Genesis', 1, 43, 27, ' فسأل عن سلامتهم ، وقال : أسالم أبوكم الشيخ الذي قلتم عنه ؟ أحي هو بعد '),
(15138, 'Genesis', 1, 43, 28, ' فقالوا : عبدك أبونا سالم . هو حي بعد . وخروا وسجدوا '),
(15139, 'Genesis', 1, 43, 29, ' فرفع عينيه ونظر بنيامين أخاه ابن أمه ، وقال : أهذا أخوكم الصغير الذي قلتم لي عنه ؟ ثم قال : الله ينعم عليك يا ابني '),
(15140, 'Genesis', 1, 43, 30, ' واستعجل يوسف لأن أحشاءه حنت إلى أخيه وطلب مكانا ليبكي ، فدخل المخدع وبكى هناك '),
(15141, 'Genesis', 1, 43, 31, ' ثم غسل وجهه وخرج وتجلد ، وقال : قدموا طعاما '),
(15142, 'Genesis', 1, 43, 32, ' فقدموا له وحده ، ولهم وحدهم ، وللمصريين الآكلين عنده وحدهم ، لأن المصريين لا يقدرون أن يأكلوا طعاما مع العبرانيين ، لأنه رجس عند المصريين '),
(15143, 'Genesis', 1, 43, 33, ' فجلسوا قدامه : البكر بحسب بكوريته ، والصغير بحسب صغره ، فبهت الرجال بعضهم إلى بعض '),
(15144, 'Genesis', 1, 43, 34, ' ورفع حصصا من قدامه إليهم ، فكانت حصة بنيامين أكثر من حصص جميعهم خمسة أضعاف . وشربوا ورووا معه '),
(15145, 'Genesis', 1, 44, 1, ' ثم أمر الذي على بيته قائلا : املأ عدال الرجال طعاما حسب ما يطيقون حمله ، وضع فضة كل واحد في فم عدله '),
(15146, 'Genesis', 1, 44, 2, ' وطاسي ، طاس الفضة ، تضع في فم عدل الصغير ، وثمن قمحه . ففعل بحسب كلام يوسف الذي تكلم به '),
(15147, 'Genesis', 1, 44, 3, ' فلما أضاء الصبح انصرف الرجال هم وحميرهم '),
(15148, 'Genesis', 1, 44, 4, ' ولما كانوا قد خرجوا من المدينة ولم يبتعدوا ، قال يوسف للذي على بيته : قم اسع وراء الرجال ، ومتى أدركتهم فقل لهم : لماذا جازيتم شرا عوضا عن خير '),
(15149, 'Genesis', 1, 44, 5, ' أليس هذا هو الذي يشرب سيدي فيه ؟ وهو يتفاءل به . أسأتم في ما صنعتم '),
(15150, 'Genesis', 1, 44, 6, ' فأدركهم وقال لهم هذا الكلام '),
(15151, 'Genesis', 1, 44, 7, ' فقالوا له : لماذا يتكلم سيدي مثل هذا الكلام ؟ حاشا لعبيدك أن يفعلوا مثل هذا الأمر '),
(15152, 'Genesis', 1, 44, 8, ' هوذا الفضة التي وجدنا في أفواه عدالنا رددناها إليك من أرض كنعان . فكيف نسرق من بيت سيدك فضة أو ذهبا '),
(15153, 'Genesis', 1, 44, 9, ' الذي يوجد معه من عبيدك يموت ، ونحن أيضا نكون عبيدا لسيدي '),
(15154, 'Genesis', 1, 44, 10, ' فقال : نعم ، الآن بحسب كلامكم هكذا يكون . الذي يوجد معه يكون لي عبدا ، وأما أنتم فتكونون أبرياء '),
(15155, 'Genesis', 1, 44, 11, ' فاستعجلوا وأنزلوا كل واحد عدله إلى الأرض ، وفتحوا كل واحد عدله '),
(15156, 'Genesis', 1, 44, 12, ' ففتش مبتدئا من الكبير حتى انتهى إلى الصغير ، فوجد الطاس في عدل بنيامين '),
(15157, 'Genesis', 1, 44, 13, ' فمزقوا ثيابهم وحمل كل واحد على حماره ورجعوا إلى المدينة '),
(15158, 'Genesis', 1, 44, 14, ' فدخل يهوذا وإخوته إلى بيت يوسف وهو بعد هناك ، ووقعوا أمامه على الأرض '),
(15159, 'Genesis', 1, 44, 15, ' فقال لهم يوسف : ما هذا الفعل الذي فعلتم ؟ ألم تعلموا أن رجلا مثلي يتفاءل '),
(15160, 'Genesis', 1, 44, 16, ' فقال يهوذا : ماذا نقول لسيدي ؟ ماذا نتكلم ؟ وبماذا نتبرر ؟ الله قد وجد إثم عبيدك . ها نحن عبيد لسيدي ، نحن والذي وجد الطاس في يده جميعا '),
(15161, 'Genesis', 1, 44, 17, ' فقال : حاشا لي أن أفعل هذا الرجل الذي وجد الطاس في يده هو يكون لي عبدا ، وأما أنتم فاصعدوا بسلام إلى أبيكم '),
(15162, 'Genesis', 1, 44, 18, ' ثم تقدم إليه يهوذا وقال : استمع يا سيدي . ليتكلم عبدك كلمة في أذني سيدي ولا يحم غضبك على عبدك ، لأنك مثل فرعون '),
(15163, 'Genesis', 1, 44, 19, ' سيدي سأل عبيده قائلا : هل لكم أب أوأخ '),
(15164, 'Genesis', 1, 44, 20, ' فقلنا لسيدي : لنا أب شيخ ، وابن شيخوخة صغير ، مات أخوه وبقي هو وحده لأمه ، وأبوه يحبه '),
(15165, 'Genesis', 1, 44, 21, ' فقلت لعبيدك : انزلوا به إلي فأجعل نظري عليه '),
(15166, 'Genesis', 1, 44, 22, ' فقلنا لسيدي : لايقدر الغلام أن يترك أباه ، وإن ترك أباه يموت '),
(15167, 'Genesis', 1, 44, 23, ' فقلت لعبيدك : إن لم ينزل أخوكم الصغير معكم لا تعودوا تنظرون وجهي '),
(15168, 'Genesis', 1, 44, 24, ' فكان لما صعدنا إلى عبدك أبي أننا أخبرناه بكلام سيدي '),
(15169, 'Genesis', 1, 44, 25, ' ثم قال أبونا : ارجعوا اشتروا لنا قليلا من الطعام '),
(15170, 'Genesis', 1, 44, 26, ' فقلنا : لا نقدر أن ننزل ، وإنما إذا كان أخونا الصغير معنا ننزل ، لأننا لا نقدر أن ننظر وجه الرجل وأخونا الصغير ليس معنا '),
(15171, 'Genesis', 1, 44, 27, ' فقال لنا عبدك أبي : أنتم تعلمون أن امرأتي ولدت لي اثنين '),
(15172, 'Genesis', 1, 44, 28, ' فخرج الواحد من عندي ، وقلت : إنما هو قد افترس افتراسا ، ولم أنظره إلى الآن '),
(15173, 'Genesis', 1, 44, 29, ' فإذا أخذتم هذا أيضا من أمام وجهي وأصابته أذية ، تنزلون شيبتي بشر إلى الهاوية '),
(15174, 'Genesis', 1, 44, 30, ' فالآن متى جئت إلى عبدك أبي ، والغلام ليس معنا ، ونفسه مرتبطة بنفسه '),
(15175, 'Genesis', 1, 44, 31, ' يكون متى رأى أن الغلام مفقود ، أنه يموت ، فينزل عبيدك شيبة عبدك أبينا بحزن إلى الهاوية '),
(15176, 'Genesis', 1, 44, 32, ' لأن عبدك ضمن الغلام لأبي قائلا : إن لم أجئ به إليك أصر مذنبا إلى أبي كل الأيام '),
(15177, 'Genesis', 1, 44, 33, ' فالآن ليمكث عبدك عوضا عن الغلام ، عبدا لسيدي ، ويصعد الغلام مع إخوته '),
(15178, 'Genesis', 1, 44, 34, ' لأني كيف أصعد إلى أبي والغلام ليس معي ؟ لئلا أنظر الشر الذي يصيب أبي '),
(15179, 'Genesis', 1, 45, 1, ' فلم يستطع يوسف أن يضبط نفسه لدى جميع الواقفين عنده فصرخ : أخرجوا كل إنسان عني . فلم يقف أحد عنده حين عرف يوسف إخوته بنفسه '),
(15180, 'Genesis', 1, 45, 2, ' فأطلق صوته بالبكاء ، فسمع المصريون وسمع بيت فرعون '),
(15181, 'Genesis', 1, 45, 3, ' وقال يوسف لإخوته : أنا يوسف . أحي أبي بعد ؟ فلم يستطع إخوته أن يجيبوه ، لأنهم ارتاعوا منه '),
(15182, 'Genesis', 1, 45, 4, ' فقال يوسف لإخوته : تقدموا إلي . فتقدموا . فقال : أنا يوسف أخوكم الذي بعتموه إلى مصر '),
(15183, 'Genesis', 1, 45, 5, ' والآن لا تتأسفوا ولا تغتاظوا لأنكم بعتموني إلى هنا ، لأنه لاستبقاء حياة أرسلني الله قدامكم '),
(15184, 'Genesis', 1, 45, 6, ' لأن للجوع في الأرض الآن سنتين . وخمس سنين أيضا لا تكون فيها فلاحة ولا حصاد '),
(15185, 'Genesis', 1, 45, 7, ' فقد أرسلني الله قدامكم ليجعل لكم بقية في الأرض وليستبقي لكم نجاة عظيمة '),
(15186, 'Genesis', 1, 45, 8, ' فالآن ليس أنتم أرسلتموني إلى هنا بل الله . وهو قد جعلني أبا لفرعون وسيدا لكل بيته ومتسلطا على كل أرض مصر '),
(15187, 'Genesis', 1, 45, 9, ' أسرعوا واصعدوا إلى أبي وقولوا له : هكذا يقول ابنك يوسف : قد جعلني الله سيدا لكل مصر . انزل إلي . لا تقف '),
(15188, 'Genesis', 1, 45, 10, ' فتسكن في أرض جاسان وتكون قريبا مني ، أنت وبنوك وبنو بنيك وغنمك وبقرك وكل مالك '),
(15189, 'Genesis', 1, 45, 11, ' وأعولك هناك ، لأنه يكون أيضا خمس سنين جوعا . لئلا تفتقر أنت وبيتك وكل ما لك '),
(15190, 'Genesis', 1, 45, 12, ' وهوذا عيونكم ترى ، وعينا أخي بنيامين ، أن فمي هو الذي يكلمكم '),
(15191, 'Genesis', 1, 45, 13, ' وتخبرون أبي بكل مجدي في مصر وبكل مارأيتم ، وتستعجلون وتنزلون بأبي إلى هنا '),
(15192, 'Genesis', 1, 45, 14, ' ثم وقع على عنق بنيامين أخيه وبكى ، وبكى بنيامين على عنقه '),
(15193, 'Genesis', 1, 45, 15, ' وقبل جميع إخوته وبكى عليهم . وبعد ذلك تكلم إخوته معه '),
(15194, 'Genesis', 1, 45, 16, ' وسمع الخبر في بيت فرعون ، وقيل : جاء إخوة يوسف . فحسن في عيني فرعون وفي عيون عبيده '),
(15195, 'Genesis', 1, 45, 17, ' فقال فرعون ليوسف : قل لإخوتك : افعلوا هذا : حملوا دوابكم وانطلقوا ، اذهبوا إلى أرض كنعان '),
(15196, 'Genesis', 1, 45, 18, ' وخذوا أباكم وبيوتكم وتعالوا إلي ، فأعطيكم خيرات أرض مصر وتأكلوا دسم الأرض '),
(15197, 'Genesis', 1, 45, 19, ' فأنت قد أمرت ، افعلوا هذا : خذوا لكم من أرض مصر عجلات لأولادكم ونسائكم ، واحملوا أباكم وتعالوا '),
(15198, 'Genesis', 1, 45, 20, ' ولا تحزن عيونكم على أثاثكم ، لأن خيرات جميع أرض مصر لكم '),
(15199, 'Genesis', 1, 45, 21, ' ففعل بنو إسرائيل هكذا . وأعطاهم يوسف عجلات بحسب أمر فرعون ، وأعطاهم زادا للطريق '),
(15200, 'Genesis', 1, 45, 22, ' وأعطى كل واحد منهم حلل ثياب ، وأما بنيامين فأعطاه ثلاث مئة من الفضة وخمس حلل ثياب '),
(15201, 'Genesis', 1, 45, 23, ' وأرسل لأبيه هكذا : عشرة حمير حاملة من خيرات مصر ، وعشر أتن حاملة حنطة ، وخبزا وطعاما لأبيه لأجل الطريق '),
(15202, 'Genesis', 1, 45, 24, ' ثم صرف إخوته فانطلقوا ، وقال لهم : لا تتغاضبوا في الطريق '),
(15203, 'Genesis', 1, 45, 25, ' فصعدوا من مصر وجاءوا إلى أرض كنعان ، إلى يعقوب أبيهم '),
(15204, 'Genesis', 1, 45, 26, ' وأخبروه قائلين : يوسف حي بعد ، وهو متسلط على كل أَرض مصر . فجمد قلبه لأَنه لم يصدقهم '),
(15205, 'Genesis', 1, 45, 27, ' ثم كلموه بكل كلام يوسف الذي كلمهم به ، وأبصر العجلات التي أرسلها يوسف لتحمله . فعاشت روح يعقوب أَبيهم '),
(15206, 'Genesis', 1, 45, 28, ' فقال إسرائيل : كفى يوسف ابني حي بعد . أذهب وأراه قبل أن أموت '),
(15207, 'Genesis', 1, 46, 1, ' فارتحل إسرائيل وكل ما كان له وأتى إلى بئر سبع ، وذبح ذبائح لاله أبيه إسحاق '),
(15208, 'Genesis', 1, 46, 2, ' فكلم الله إسرائيل في رؤى الليل وقال : يعقوب ، يعقوب . فقال:هأنذا '),
(15209, 'Genesis', 1, 46, 3, ' فقال : أنا الله ، إله أبيك . لا تخف من النزول إلى مصر ، لاني أجعلك أمة عظيمة هناك '),
(15210, 'Genesis', 1, 46, 4, ' أنا أنزل معك إلى مصر ، وأنا أصعدك أيضا . ويضع يوسف يده على عينيك '),
(15211, 'Genesis', 1, 48, 14, ' فمد إسرائيل يمينه ووضعها على رأس أفرايم وهو الصغير ، ويساره على رأس منسى . وضع يديه بفطنة فإن منسى كان البكر '),
(15212, 'Genesis', 1, 48, 15, ' وبارك يوسف وقال : الله الذي سار أمامه أبواي إبراهيم وإسحاق ، الله الذي رعاني منذ وجودي إلى هذا اليوم '),
(15213, 'Genesis', 1, 48, 16, ' الملاك الذي خلصني من كل شر ، يبارك الغلامين . وليدع عليهما اسمي واسم أبوي إبراهيم وإسحاق ، وليكثرا كثيرا في الأرض '),
(15214, 'Genesis', 1, 48, 17, ' فلما رأى يوسف أن أباه وضع يده اليمنى على رأس أفرايم ، ساء ذلك في عينيه ، فأمسك بيد أبيه لينقلها عن رأس أفرايم إلى رأس منسى '),
(15215, 'Genesis', 1, 48, 18, ' وقال يوسف لأبيه : ليس هكذا يا أبي ، لأن هذا هو البكر . ضع يمينك على رأسه '),
(15216, 'Genesis', 1, 48, 19, ' فأبى أبوه وقال : علمت يا ابني ، علمت . هو أيضا يكون شعبا ، وهو أيضا يصير كبيرا . ولكن أخاه الصغير يكون أكبر منه ، ونسله يكون جمهورا من الأمم '),
(15217, 'Genesis', 1, 48, 20, ' وباركهما في ذلك اليوم قائلا : بك يبارك إسرائيل قائلا : يجعلك الله كأفرايم وكمنسى . فقدم أفرايم على منسى '),
(15218, 'Genesis', 1, 48, 21, ' وقال إسرائيل ليوسف : ها أنا أموت ، ولكن الله سيكون معكم ويردكم إلى أرض آبائكم '),
(15219, 'Genesis', 1, 48, 22, ' وأنا قد وهبت لك سهما واحدا فوق إخوتك ، أخذته من يد الأموريين بسيفي وقوسي '),
(15220, 'Genesis', 1, 49, 1, ' ودعا يعقوب بنيه وقال : اجتمعوا لأنبئكم بما يصيبكم في آخر الايام '),
(15221, 'Genesis', 1, 49, 2, ' اجتمعوا واسمعوا يا بني يعقوب ، واصغوا إلى إسرائيل أبيكم '),
(15222, 'Genesis', 1, 49, 3, ' رأوبين ، أنت بكري ، قوتي وأول قدرتي ، فضل الرفعة وفضل العز '),
(15223, 'Genesis', 1, 49, 4, ' فائرا كالماء لا تتفضل ، لانك صعدت على مضجع أبيك . حينئذ دنسته . على فراشي صعد '),
(15224, 'Genesis', 1, 49, 5, ' شمعون ولاوي أخوان ، آلات ظلم سيوفهما '),
(15225, 'Genesis', 1, 49, 6, ' في مجلسهما لا تدخل نفسي . بمجمعهما لا تتحد كرامتي . لانهما في غضبهما قتلا إنسانا ، وفي رضاهما عرقبا ثورا '),
(15226, 'Genesis', 1, 49, 7, ' ملعون غضبهما فإنه شديد ، وسخطهما فإنه قاس . أقسمهما في يعقوب ، وأفرقهما في إسرائيل '),
(15227, 'Genesis', 1, 49, 8, ' يهوذا ، إياك يحمد إخوتك ، يدك على قفا أعدائك ، يسجد لك بنو أبيك '),
(15228, 'Genesis', 1, 49, 9, ' يهوذا جرو أسد ، من فريسة صعدت يا ابني ، جثا وربض كأسد وكلبوة . من ينهضه '),
(15229, 'Genesis', 1, 49, 10, ' لا يزول قضيب من يهوذا ومشترع من بين رجليه حتى يأتي شيلون وله يكون خضوع شعوب '),
(15230, 'Genesis', 1, 49, 11, ' رابطا بالكرمة جحشه ، وبالجفنة ابن أتانه ، غسل بالخمر لباسه ، وبدم العنب ثوبه '),
(15231, 'Genesis', 1, 49, 12, ' مسود العينين من الخمر ، ومبيض الاسنان من اللبن '),
(15232, 'Genesis', 1, 49, 13, ' زبولون ، عند ساحل البحر يسكن ، وهو عند ساحل السفن ، وجانبه عند صيدون '),
(15233, 'Genesis', 1, 49, 14, ' يساكر ، حمار جسيم رابض بين الحظائر '),
(15234, 'Genesis', 1, 49, 15, ' فرأى المحل أنه حسن ، والارض أنها نزهة ، فأحنى كتفه للحمل وصار للجزية عبدا '),
(15235, 'Genesis', 1, 49, 16, ' دان ، يدين شعبه كأحد أسباط إسرائيل '),
(15236, 'Genesis', 1, 49, 17, ' يكون دان حية على الطريق ، أفعوانا على السبيل ، يلسع عقبي الفرس فيسقط راكبه إلى الوراء '),
(15237, 'Genesis', 1, 49, 18, ' لخلاصك انتظرت يارب '),
(15238, 'Genesis', 1, 49, 19, ' جاد ، يزحمه جيش ، ولكنه يزحم مؤخره '),
(15239, 'Genesis', 1, 49, 20, ' أشير ، خبزه سمين وهو يعطي لذات ملوك '),
(15240, 'Genesis', 1, 49, 21, ' نفتالي ، أيلة مسيبة يعطي أقوالا حسنة '),
(15241, 'Genesis', 1, 49, 22, ' يوسف ، غصن شجرة مثمرة ، غصن شجرة مثمرة على عين . أغصان قد ارتفعت فوق حائط '),
(15242, 'Genesis', 1, 49, 23, ' فمررته ورمته واضطهدته أرباب السهام '),
(15243, 'Genesis', 1, 49, 24, ' ولكن ثبتت بمتانة قوسه ، وتشددت سواعد يديه . من يدي عزيز يعقوب ، من هناك ، من الراعي صخر إسرائيل '),
(15244, 'Genesis', 1, 49, 25, ' من إله أبيك الذي يعينك ، ومن القادر على كل شيء الذي يباركك ، تأتي بركات السماء من فوق ، وبركات الغمر الرابض تحت . بركات الثديين والرحم '),
(15245, 'Genesis', 1, 49, 26, ' بركات أبيك فاقت على بركات أبوي . إلى منية الآكام الدهرية تكون على رأس يوسف ، وعلى قمة نذير إخوته '),
(15246, 'Genesis', 1, 49, 27, ' بنيامين ذئب يفترس . في الصباح يأكل غنيمة ، وعند المساء يقسم نهبا '),
(15247, 'Genesis', 1, 49, 28, ' جميع هؤلاء هم أسباط إسرائيل الاثنا عشر . وهذا ما كلمهم به أبوهم وباركهم . كل واحد بحسب بركته باركهم '),
(15248, 'Genesis', 1, 49, 29, ' وأوصاهم وقال لهم : أنا أنضم إلى قومي . ادفنوني عند آبائي في المغارة التي في حقل عفرون الحثي '),
(15249, 'Genesis', 1, 49, 30, ' في المغارة التي في حقل المكفيلة ، التي أمام ممرا في أرض كنعان ، التي اشتراها إبراهيم مع الحقل من عفرون الحثي ملك قبر '),
(15250, 'Genesis', 1, 49, 31, ' هناك دفنوا إبراهيم وسارة امرأته . هناك دفنوا إسحاق ورفقة امرأته ، وهناك دفنت ليئة '),
(15251, 'Genesis', 1, 49, 32, ' شراء الحقل والمغارة التي فيه كان من بني حث '),
(15252, 'Genesis', 1, 49, 33, ' ولما فرغ يعقوب من توصية بنيه ضم رجليه إلى السرير ، وأسلم الروح وانضم إلى قومه '),
(15253, 'Genesis', 1, 50, 1, ' فوقع يوسف على وجه أبيه وبكى عليه وقبله '),
(15254, 'Genesis', 1, 50, 2, ' وأمر يوسف عبيده الاطباء أن يحنطوا أباه . فحنط الاطباء إسرائيل '),
(15255, 'Genesis', 1, 50, 3, ' وكمل له أربعون يوما ، لانه هكذا تكمل أيام المحنطين . وبكى عليه المصريون سبعين يوما '),
(15256, 'Genesis', 1, 50, 4, ' وبعد ما مضت أيام بكائه كلم يوسف بيت فرعون قائلا : إن كنت قد وجدت نعمة في عيونكم ، فتكلموا في مسامع فرعون قائلين '),
(15257, 'Genesis', 1, 50, 5, ' أبي استحلفني قائلا : ها أنا أموت . في قبري الذي حفرت لنفسي في أرض كنعان هناك تدفنني ، فالآن أصعد لادفن أبي وأرجع '),
(15258, 'Genesis', 1, 50, 6, ' فقال فرعون : اصعد وادفن أباك كما استحلفك '),
(15259, 'Genesis', 1, 50, 7, ' فصعد يوسف ليدفن أباه ، وصعد معه جميع عبيد فرعون ، شيوخ بيته وجميع شيوخ أرض مصر '),
(15260, 'Genesis', 1, 50, 8, ' وكل بيت يوسف وإخوته وبيت أبيه ، غير أنهم تركوا أولادهم وغنمهم وبقرهم في أرض جاسان '),
(15261, 'Genesis', 1, 50, 9, ' وصعد معه مركبات وفرسان ، فكان الجيش كثيرا جدا '),
(15262, 'Genesis', 1, 50, 10, ' فأتوا إلى بيدر أطاد الذي في عبر الأردن وناحوا هناك نوحا عظيما وشديدا جدا ، وصنع لابيه مناحة سبعة أيام '),
(15263, 'Genesis', 1, 50, 11, ' فلما رأى أهل البلاد الكنعانيون المناحة في بيدر أطاد قالوا : هذه مناحة ثقيلة للمصريين . لذلك دعي اسمه آبل مصرايم . الذي في عبر الأردن '),
(15264, 'Genesis', 1, 50, 12, ' وفعل له بنوه هكذا كما أوصاهم '),
(15265, 'Genesis', 1, 50, 13, ' حمله بنوه إلى أرض كنعان ودفنوه في مغارة حقل المكفيلة ، التي اشتراها إبراهيم مع الحقل ملك قبر من عفرون الحثي أمام ممرا '),
(15266, 'Genesis', 1, 50, 14, ' ثم رجع يوسف إلى مصر هو وإخوته وجميع الذين صعدوا معه لدفن أبيه بعد ما دفن أباه '),
(15267, 'Genesis', 1, 50, 15, ' ولما رأى إخوة يوسف أن أباهم قد مات ، قالوا : لعل يوسف يضطهدنا ويرد علينا جميع الشر الذي صنعنا به '),
(15268, 'Genesis', 1, 50, 16, ' فأوصوا إلى يوسف قائلين : أبوك أوصى قبل موته قائلا '),
(15269, 'Genesis', 1, 50, 17, ' هكذا تقولون ليوسف : آه اصفح عن ذنب إخوتك وخطيتهم ، فإنهم صنعوا بك شرا . فالآن اصفح عن ذنب عبيد إله أبيك . فبكى يوسف حين كلموه '),
(15270, 'Genesis', 1, 50, 18, ' وأتى إخوته أيضا ووقعوا أمامه وقالوا : ها نحن عبيدك '),
(15271, 'Genesis', 1, 50, 19, ' فقال لهم يوسف : لا تخافوا . لانه هل أنا مكان الله '),
(15272, 'Genesis', 1, 50, 20, ' أنتم قصدتم لي شرا ، أما الله فقصد به خيرا ، لكي يفعل كما اليوم ، ليحيي شعبا كثيرا '),
(15273, 'Genesis', 1, 50, 21, ' فالآن لاتخافوا . أنا أعولكم وأولادكم . فعزاهم وطيب قلوبهم '),
(15274, 'Genesis', 1, 50, 22, ' وسكن يوسف في مصر هو وبيت أبيه ، وعاش يوسف مئة وعشر سنين '),
(15275, 'Genesis', 1, 50, 23, ' ورأى يوسف لافرايم أولاد الجيل الثالث . وأولاد ماكير بن منسى أيضا ولدوا على ركبتي يوسف '),
(15276, 'Genesis', 1, 50, 24, ' وقال يوسف لإخوته : أنا أموت ، ولكن الله سيفتقدكم ويصعدكم من هذه الارض إلى الارض التي حلف لإبراهيم وإسحاق ويعقوب '),
(15277, 'Genesis', 1, 50, 25, ' واستحلف يوسف بني إسرائيل قائلا : الله سيفتقدكم فتصعدون عظامي من هنا '),
(15278, 'Genesis', 1, 50, 26, ' ثم مات يوسف وهو ابن مئة وعشر سنين ، فحنطوه ووضع في تابوت في مصر '),
(15279, 'Habakkuk', 35, 1, 1, ' الوحي الذي رآه حبقوق النبي '),
(15280, 'Habakkuk', 35, 1, 2, ' حتى متى يارب أدعو وأنت لا تسمع ؟ أصرخ إليك من الظلم وأنت لا تخلص '),
(15281, 'Habakkuk', 35, 1, 3, ' لم تريني إثما ، وتبصر جورا ؟ وقدامي اغتصاب وظلم ويحدث خصام وترفع المخاصمة نفسها '),
(15282, 'Habakkuk', 35, 1, 4, ' لذلك جمدت الشريعة ولا يخرج الحكم بتة ، لأن الشرير يحيط بالصديق ، فلذلك يخرج الحكم معوجا '),
(15283, 'Habakkuk', 35, 1, 5, ' انظروا بين الأمم ، وأبصروا وتحيروا حيرة . لأني عامل عملا في أيامكم لا تصدقون به إن أخبر به '),
(15284, 'Habakkuk', 35, 1, 6, ' فهأنذا مقيم الكلدانيين الأمة المرة القاحمة السالكة في رحاب الأرض لتملك مساكن ليست لها '),
(15285, 'Habakkuk', 35, 1, 7, ' هي هائلة ومخوفة . من قبل نفسها يخرج حكمها وجلالها '),
(15286, 'Habakkuk', 35, 1, 8, ' وخيلها أسرع من النمور ، وأحد من ذئاب المساء . وفرسانها ينتشرون ، وفرسانها يأتون من بعيد ، ويطيرون كالنسر المسرع إلى الأكل '),
(15287, 'Habakkuk', 35, 1, 9, ' يأتون كلهم للظلم . منظر وجوههم إلى قدام ، ويجمعون سبيا كالرمل '),
(15288, 'Habakkuk', 35, 1, 10, ' وهي تسخر من الملوك ، والرؤساء ضحكة لها . وتضحك على كل حصن ، وتكوم التراب وتأخذه '),
(15289, 'Habakkuk', 35, 1, 11, ' ثم تتعدى روحها فتعبر وتأثم . هذه قوتها إلهها '),
(15290, 'Habakkuk', 35, 1, 12, ' ألست أنت منذ الأزل يارب إلهي قدوسي ؟ لا نموت . يارب للحكم جعلتها ، ويا صخر للتأديب أسستها '),
(15291, 'Habakkuk', 35, 1, 13, ' عيناك أطهر من أن تنظرا الشر ، ولا تستطيع النظر إلى الجور ، فلم تنظر إلى الناهبين ، وتصمت حين يبلع الشرير من هو أبر منه '),
(15292, 'Habakkuk', 35, 1, 14, ' وتجعل الناس كسمك البحر ، كدبابات لا سلطان لها '),
(15293, 'Habakkuk', 35, 1, 15, ' تطلع الكل بشصها ، وتصطادهم بشبكتها وتجمعهم في مصيدتها ، فلذلك تفرح وتبتهج '),
(15294, 'Habakkuk', 35, 1, 16, ' لذلك تذبح لشبكتها ، وتبخر لمصيدتها ، لأنه بهما سمن نصيبها ، وطعامها مسمن '),
(15295, 'Habakkuk', 35, 1, 17, ' أفلأجل هذا تفرغ شبكتها ولا تعفو عن قتل الأمم دائما '),
(15296, 'Habakkuk', 35, 2, 1, ' على مرصدي أقف ، وعلى الحصن أنتصب ، وأراقب لأرى ماذا يقول لي ، وماذا أجيب عن شكواي '),
(15297, 'Habakkuk', 35, 2, 2, ' فأجابني الرب وقال : اكتب الرؤيا وانقشها على الألواح لكي يركض قارئها '),
(15298, 'Habakkuk', 35, 2, 3, ' لأن الرؤيا بعد إلى الميعاد ، وفي النهاية تتكلم ولا تكذب . إن توانت فانتظرها لأنها ستأتي إتيانا ولا تتأخر '),
(15299, 'Habakkuk', 35, 2, 4, ' هوذا منتفخة غير مستقيمة نفسه فيه . والبار بإيمانه يحيا '),
(15300, 'Habakkuk', 35, 2, 5, ' وحقا إن الخمر غادرة . الرجل متكبر ولا يهدأ . الذي قد وسع نفسه كالهاوية ، وهو كالموت فلا يشبع ، بل يجمع إلى نفسه كل الأمم ، ويضم إلى نفسه جميع الشعوب '),
(15301, 'Habakkuk', 35, 2, 6, ' فهلا ينطق هؤلاء كلهم بهجو عليه ولغز شماتة به ، ويقولون : ويل للمكثر ما ليس له إلى متى ؟ وللمثقل نفسه رهونا '),
(15302, 'Habakkuk', 35, 2, 7, ' ألا يقوم بغتة مقارضوك ، ويستيقظ مزعزعوك ، فتكون غنيمة لهم '),
(15303, 'Habakkuk', 35, 2, 8, ' لأنك سلبت أمما كثيرة ، فبقية الشعوب كلها تسلبك لدماء الناس وظلم الأرض والمدينة وجميع الساكنين فيها '),
(15304, 'Habakkuk', 35, 2, 9, ' ويل للمكسب بيته كسبا شريرا ليجعل عشه في العلو لينجو من كف الشر '),
(15305, 'Habakkuk', 35, 2, 10, ' تآمرت الخزي لبيتك . إبادة شعوب كثيرة وأنت مخطئ لنفسك '),
(15306, 'Habakkuk', 35, 2, 11, ' لأن الحجر يصرخ من الحائط فيجيبه الجائز من الخشب '),
(15307, 'Habakkuk', 35, 2, 12, ' ويل للباني مدينة بالدماء ، وللمؤسس قرية بالإثم '),
(15308, 'Habakkuk', 35, 2, 13, ' أليس من قبل رب الجنود أن الشعوب يتعبون للنار ، والأمم للباطل يعيون '),
(15309, 'Habakkuk', 35, 2, 14, ' لأن الأرض تمتلئ من معرفة مجد الرب كما تغطي المياه البحر '),
(15310, 'Habakkuk', 35, 2, 15, ' ويل لمن يسقي صاحبه سافحا حموك ومسكرا أيضا ، للنظر إلى عوراتهم '),
(15311, 'Habakkuk', 35, 2, 16, ' قد شبعت خزيا عوضا عن المجد . فاشرب أنت أيضا واكشف غرلتك تدور إليك كأس يمين الرب ، وقياء الخزي على مجدك '),
(15312, 'Habakkuk', 35, 2, 17, ' لأن ظلم لبنان يغطيك ، واغتصاب البهائم الذي روعها ، لأجل دماء الناس وظلم الأرض والمدينة وجميع الساكنين فيها '),
(15313, 'Habakkuk', 35, 2, 18, ' ماذا نفع التمثال المنحوت حتى نحته صانعه ؟ أو المسبوك ومعلم الكذب حتى إن الصانع صنعة يتكل عليها ، فيصنع أوثانا بكما '),
(15314, 'Habakkuk', 35, 2, 19, ' ويل للقائل للعود : استيقظ وللحجر الأصم : انتبه أهو يعلم ؟ ها هو مطلي بالذهب والفضة ، ولا روح البتة في داخله '),
(15315, 'Habakkuk', 35, 2, 20, ' أما الرب ففي هيكل قدسه . فاسكتي قدامه يا كل الأرض '),
(15316, 'Habakkuk', 35, 3, 1, ' صلاة لحبقوق النبي على الشجوية '),
(15317, 'Habakkuk', 35, 3, 2, ' يارب ، قد سمعت خبرك فجزعت . يارب ، عملك في وسط السنين أحيه . في وسط السنين عرف . في الغضب اذكر الرحمة '),
(15318, 'Habakkuk', 35, 3, 3, ' الله جاء من تيمان ، والقدوس من جبل فاران . سلاه . جلاله غطى السماوات ، والأرض امتلأت من تسبيحه '),
(15319, 'Habakkuk', 35, 3, 4, ' وكان لمعان كالنور . له من يده شعاع ، وهناك استتار قدرته '),
(15320, 'Habakkuk', 35, 3, 5, ' قدامه ذهب الوبأ ، وعند رجليه خرجت الحمى '),
(15321, 'Habakkuk', 35, 3, 6, ' وقف وقاس الأرض . نظر فرجف الأمم ودكت الجبال الدهرية وخسفت آكام القدم . مسالك الأزل له '),
(15322, 'Habakkuk', 35, 3, 7, ' رأيت خيام كوشان تحت بلية . رجفت شقق أرض مديان '),
(15323, 'Habakkuk', 35, 3, 8, ' هل على الأنهار حمي يارب ؟ هل على الأنهار غضبك ؟ أو على البحر سخطك حتى إنك ركبت خيلك ، مركباتك مركبات الخلاص '),
(15324, 'Habakkuk', 35, 3, 9, ' عريت قوسك تعرية . سباعيات سهام كلمتك . سلاه . شققت الأرض أنهارا '),
(15325, 'Habakkuk', 35, 3, 10, ' أبصرتك ففزعت الجبال . سيل المياه طما . أعطت اللجة صوتها . رفعت يديها إلى العلاء '),
(15326, 'Habakkuk', 35, 3, 11, ' الشمس والقمر وقفا في بروجهما لنور سهامك الطائرة ، للمعان برق مجدك '),
(15327, 'Habakkuk', 35, 3, 12, ' بغضب خطرت في الأرض ، بسخط دست الأمم '),
(15328, 'Habakkuk', 35, 3, 13, ' خرجت لخلاص شعبك ، لخلاص مسيحك . سحقت رأس بيت الشرير معريا الأساس حتى العنق . سلاه '),
(15329, 'Habakkuk', 35, 3, 14, ' ثقبت بسهامه رأس قبائله . عصفوا لتشتيتي . ابتهاجهم كما لأكل المسكين في الخفية '),
(15330, 'Habakkuk', 35, 3, 15, ' سلكت البحر بخيلك ، كوم المياه الكثيرة '),
(15331, 'Habakkuk', 35, 3, 16, ' سمعت فارتعدت أحشائي . من الصوت رجفت شفتاي . دخل النخر في عظامي ، وارتعدت في مكاني لأستريح في يوم الضيق ، عند صعود الشعب الذي يزحمنا '),
(15332, 'Habakkuk', 35, 3, 17, ' فمع أنه لا يزهر التين ، ولا يكون حمل في الكروم . يكذب عمل الزيتونة ، والحقول لا تصنع طعاما . ينقطع الغنم من الحظيرة ، ولا بقر في المذاود '),
(15333, 'Habakkuk', 35, 3, 18, ' فإني أبتهج بالرب وأفرح بإله خلاصي '),
(15334, 'Habakkuk', 35, 3, 19, ' الرب السيد قوتي ، ويجعل قدمي كالأيائل ، ويمشيني على مرتفعاتي لرئيس المغنين على آلاتي ذوات الأوتار '),
(15335, 'Haggai', 37, 1, 1, ' في السنة الثانية لداريوس الملك ، في الشهر السادس في أول يوم من الشهر ، كانت كلمة الرب عن يد حجي النبي إلى زربابل بن شألتيئيل والي يهوذا ، وإلى يهوشع بن يهوصادق الكاهن العظيم قائلا '),
(15336, 'Haggai', 37, 1, 2, ' هكذا قال رب الجنود قائلا : هذا الشعب قال إن الوقت لم يبلغ وقت بناء بيت الرب '),
(15337, 'Haggai', 37, 1, 3, ' فكانت كلمة الرب عن يد حجي النبي قائلا '),
(15338, 'Haggai', 37, 1, 4, ' هل الوقت لكم أنتم أن تسكنوا في بيوتكم المغشاة ، وهذا البيت خراب '),
(15339, 'Haggai', 37, 1, 5, ' والآن فهكذا قال رب الجنود : اجعلوا قلبكم على طرقكم '),
(15340, 'Haggai', 37, 1, 6, ' زرعتم كثيرا ودخلتم قليلا . تأكلون وليس إلى الشبع . تشربون ولا تروون . تكتسون ولا تدفأون . والآخذ أجرة يأخذ أجرة لكيس منقوب '),
(15341, 'Haggai', 37, 1, 7, ' هكذا قال رب الجنود : اجعلوا قلبكم على طرقكم '),
(15342, 'Haggai', 37, 1, 8, ' اصعدوا إلى الجبل وأتوا بخشب وابنوا البيت ، فأرضى عليه وأتمجد ، قال الرب '),
(15343, 'Haggai', 37, 1, 9, ' انتظرتم كثيرا وإذا هو قليل . ولما أدخلتموه البيت نفخت عليه . لماذا ؟ يقول رب الجنود . لأجل بيتي الذي هو خراب ، وأنتم راكضون كل إنسان إلى بيته '),
(15344, 'Haggai', 37, 1, 10, ' لذلك منعت السماوات من فوقكم الندى ، ومنعت الأرض غلتها '),
(15345, 'Haggai', 37, 1, 11, ' ودعوت بالحر على الأرض وعلى الجبال وعلى الحنطة وعلى المسطار وعلى الزيت وعلى ما تنبته الأرض ، وعلى الناس وعلى البهائم ، وعلى كل أتعاب اليدين '),
(15346, 'Haggai', 37, 1, 12, ' حينئذ سمع زربابل بن شألتيئيل ويهوشع بن يهوصادق الكاهن العظيم ، وكل بقية الشعب صوت الرب إلههم وكلام حجي النبي كما أرسله الرب إلههم . وخاف الشعب أمام وجه الرب '),
(15347, 'Haggai', 37, 1, 13, ' فقال حجي رسول الرب برسالة الرب لجميع الشعب قائلا : أنا معكم ، يقول الرب '),
(15348, 'Haggai', 37, 1, 14, ' ونبه الرب روح زربابل بن شألتيئيل والي يهوذا ، وروح يهوشع بن يهوصادق الكاهن العظيم ، وروح كل بقية الشعب . فجاءوا وعملوا الشغل في بيت رب الجنود إلههم '),
(15349, 'Haggai', 37, 1, 15, ' في اليوم الرابع والعشرين من الشهر السادس ، في السنة الثانية لداريوس الملك '),
(15350, 'Haggai', 37, 2, 1, ' في الشهر السابع في الحادي والعشرين من الشهر ، كانت كلمة الرب عن يد حجي النبي قائلا '),
(15351, 'Haggai', 37, 2, 2, ' كلم زربابل بن شألتيئيل والي يهوذا ، ويهوشع بن يهوصادق الكاهن العظيم وبقية الشعب قائلا '),
(15352, 'Haggai', 37, 2, 3, ' من الباقي فيكم الذي رأى هذا البيت في مجده الأول ؟ وكيف تنظرونه الآن ؟ أما هو في أعينكم كلا شيء '),
(15353, 'Haggai', 37, 2, 4, ' فالآن تشدد يا زربابل ، يقول الرب . وتشدد يا يهوشع بن يهوصادق الكاهن العظيم ، وتشددوا يا جميع شعب الأرض ، يقول الرب . واعملوا فإني معكم ، يقول رب الجنود '),
(15354, 'Haggai', 37, 2, 5, ' حسب الكلام الذي عاهدتكم به عند خروجكم من مصر ، وروحي قائم في وسطكم . لا تخافوا '),
(15355, 'Haggai', 37, 2, 6, ' لأنه هكذا قال رب الجنود : هي مرة ، بعد قليل ، فأزلزل السماوات والأرض والبحر واليابسة '),
(15356, 'Haggai', 37, 2, 7, ' وأزلزل كل الأمم . ويأتي مشتهى كل الأمم ، فأملأ هذا البيت مجدا ، قال رب الجنود '),
(15357, 'Haggai', 37, 2, 8, ' لي الفضة ولي الذهب ، يقول رب الجنود '),
(15358, 'Haggai', 37, 2, 9, ' مجد هذا البيت الأخير يكون أعظم من مجد الأول ، قال رب الجنود . وفي هذا المكان أعطي السلام ، يقول رب الجنود '),
(15359, 'Haggai', 37, 2, 10, ' في الرابع والعشرين من الشهر التاسع ، في السنة الثانية لداريوس ، كانت كلمة الرب عن يد حجي النبي قائلا '),
(15360, 'Haggai', 37, 2, 11, ' هكذا قال رب الجنود : اسأل الكهنة عن الشريعة قائلا '),
(15361, 'Haggai', 37, 2, 12, ' إن حمل إنسان لحما مقدسا في طرف ثوبه ومس بطرفه خبزا أو طبيخا أو خمرا أو زيتا أو طعاما ما ، فهل يتقدس ؟  . فأجاب الكهنة وقالوا : لا '),
(15362, 'Haggai', 37, 2, 13, ' فقال حجي : إن كان المنجس بميت يمس شيئا من هذه ، فهل يتنجس ؟  . فأجاب الكهنة وقالوا : يتنجس '),
(15363, 'Haggai', 37, 2, 14, ' فأجاب حجي وقال : هكذا هذا الشعب ، وهكذا هذه الأمة قدامي ، يقول الرب ، وهكذا كل عمل أيديهم وما يقربونه هناك . هو نجس '),
(15364, 'Haggai', 37, 2, 15, ' والآن فاجعلوا قلبكم من هذا اليوم فراجعا ، قبل وضع حجر على حجر في هيكل الرب '),
(15365, 'Haggai', 37, 2, 16, ' مذ تلك الأيام كان أحدكم يأتي إلى عرمة عشرين فكانت عشرة . أتى إلى حوض المعصرة ليغرف خمسين فورة فكانت عشرين '),
(15366, 'Haggai', 37, 2, 17, ' قد ضربتكم باللفح وباليرقان وبالبرد في كل عمل أيديكم ، وما رجعتم إلي ، يقول الرب '),
(15367, 'Haggai', 37, 2, 18, ' فاجعلوا قلبكم من هذا اليوم فصاعدا ، من اليوم الرابع والعشرين من الشهر التاسع ، من اليوم الذي فيه تأسس هيكل الرب ، اجعلوا قلبكم '),
(15368, 'Haggai', 37, 2, 19, ' هل البذر في الأهراء بعد ؟ والكرم والتين والرمان والزيتون لم يحمل بعد . فمن هذا اليوم أبارك '),
(15369, 'Haggai', 37, 2, 20, ' وصارت كلمة الرب ثانية إلى حجي ، في الرابع والعشرين من الشهر قائلا '),
(15370, 'Haggai', 37, 2, 21, ' كلم زربابل والي يهوذا قائلا : إني أزلزل السماوات والأرض '),
(15371, 'Haggai', 37, 2, 22, ' وأقلب كرسي الممالك ، وأبيد قوة ممالك الأمم ، وأقلب المركبات والراكبين فيها ، وينحط الخيل وراكبوها ، كل منها بسيف أخيه '),
(15372, 'Haggai', 37, 2, 23, ' في ذلك اليوم ، يقول رب الجنود ، آخذك يا زربابل عبدي ابن شألتيئيل ، يقول الرب ، وأجعلك كخاتم ، لأني قد اخترتك ، يقول رب الجنود '),
(15373, 'Hebrews', 58, 1, 1, ' الله ، بعد ما كلم الآباء بالأنبياء قديما ، بأنواع وطرق كثيرة '),
(15374, 'Hebrews', 58, 1, 2, ' كلمنا في هذه الأيام الأخيرة في ابنه ، الذي جعله وارثا لكل شيء ، الذي به أيضا عمل العالمين '),
(15375, 'Hebrews', 58, 1, 3, ' الذي ، وهو بهاء مجده ، ورسم جوهره ، وحامل كل الأشياء بكلمة قدرته ، بعد ما صنع بنفسه تطهيرا لخطايانا ، جلس في يمين العظمة في الأعالي '),
(15376, 'Hebrews', 58, 1, 4, ' صائرا أعظم من الملائكة بمقدار ما ورث اسما أفضل منهم '),
(15377, 'Hebrews', 58, 1, 5, ' لأنه لمن من الملائكة قال قط : أنت ابني أنا اليوم ولدتك ؟ وأيضا : أنا أكون له أبا وهو يكون لي ابنا '),
(15378, 'Hebrews', 58, 1, 6, ' وأيضا متى أدخل البكر إلى العالم يقول : ولتسجد له كل ملائكة الله '),
(15379, 'Hebrews', 58, 1, 7, ' وعن الملائكة يقول : الصانع ملائكته رياحا وخدامه لهيب نار '),
(15380, 'Hebrews', 58, 1, 8, ' وأما عن الابن : كرسيك يا ألله إلى دهر الدهور . قضيب استقامة قضيب ملكك '),
(15381, 'Hebrews', 58, 1, 9, ' أحببت البر وأبغضت الإثم . من أجل ذلك مسحك الله إلهك بزيت الابتهاج أكثر من شركائك '),
(15382, 'Hebrews', 58, 1, 10, ' وأنت يا رب في البدء أسست الأرض ، والسماوات هي عمل يديك '),
(15383, 'Hebrews', 58, 1, 11, ' هي تبيد ولكن أنت تبقى ، وكلها كثوب تبلى '),
(15384, 'Hebrews', 58, 1, 12, ' وكرداء تطويها فتتغير . ولكن أنت أنت ، وسنوك لن تفنى '),
(15385, 'Hebrews', 58, 1, 13, ' ثم لمن من الملائكة قال قط : اجلس عن يميني حتى أضع أعداءك موطئا لقدميك '),
(15386, 'Hebrews', 58, 1, 14, ' أليس جميعهم أرواحا خادمة مرسلة للخدمة لأجل العتيدين أن يرثوا الخلاص '),
(15387, 'Hebrews', 58, 2, 1, ' لذلك يجب أن نتنبه أكثر إلى ما سمعنا لئلا نفوته '),
(15388, 'Hebrews', 58, 2, 2, ' لأنه إن كانت الكلمة التي تكلم بها ملائكة قد صارت ثابتة ، وكل تعد ومعصية نال مجازاة عادلة '),
(15389, 'Hebrews', 58, 2, 3, ' فكيف ننجو نحن إن أهملنا خلاصا هذا مقداره ؟ قد ابتدأ الرب بالتكلم به ، ثم تثبت لنا من الذين سمعوا '),
(15390, 'Hebrews', 58, 2, 4, ' شاهدا الله معهم بآيات وعجائب وقوات متنوعة ومواهب الروح القدس ، حسب إرادته '),
(15391, 'Hebrews', 58, 2, 5, ' فإنه لملائكة لم يخضع العالم العتيد الذي نتكلم عنه '),
(15392, 'Hebrews', 58, 2, 6, ' لكن شهد واحد في موضع قائلا : ما هو الإنسان حتى تذكره ؟ أو ابن الإنسان حتى تفتقده '),
(15393, 'Hebrews', 58, 2, 7, ' وضعته قليلا عن الملائكة . بمجد وكرامة كللته ، وأقمته على أعمال يديك '),
(15394, 'Hebrews', 58, 2, 8, ' أخضعت كل شيء تحت قدميه . لأنه إذ أخضع الكل له لم يترك شيئا غير خاضع له . على أننا الآن لسنا نرى الكل بعد مخضعا له '),
(15395, 'Hebrews', 58, 2, 9, ' ولكن الذي وضع قليلا عن الملائكة ، يسوع ، نراه مكللا بالمجد والكرامة ، من أجل ألم الموت ، لكي يذوق بنعمة الله الموت لأجل كل واحد '),
(15396, 'Hebrews', 58, 2, 10, ' لأنه لاق بذاك الذي من أجله الكل وبه الكل ، وهو آت بأبناء كثيرين إلى المجد ، أن يكمل رئيس خلاصهم بالآلام '),
(15397, 'Hebrews', 58, 2, 11, ' لأن المقدس والمقدسين جميعهم من واحد ، فلهذا السبب لا يستحي أن يدعوهم إخوة '),
(15398, 'Hebrews', 58, 2, 12, ' قائلا : أخبر باسمك إخوتي ، وفي وسط الكنيسة أسبحك '),
(15399, 'Hebrews', 58, 2, 13, ' وأيضا : أنا أكون متوكلا عليه . وأيضا : ها أنا والأولاد الذين أعطانيهم الله '),
(15400, 'Hebrews', 58, 2, 14, ' فإذ قد تشارك الأولاد في اللحم والدم اشترك هو أيضا كذلك فيهما ، لكي يبيد بالموت ذاك الذي له سلطان الموت ، أي إبليس '),
(15401, 'Hebrews', 58, 2, 15, ' ويعتق أولئك الذين - خوفا من الموت - كانوا جميعا كل حياتهم تحت العبودية '),
(15402, 'Hebrews', 58, 2, 16, ' لأنه حقا ليس يمسك الملائكة ، بل يمسك نسل إبراهيم '),
(15403, 'Hebrews', 58, 2, 17, ' من ثم كان ينبغي أن يشبه إخوته في كل شيء ، لكي يكون رحيما ، ورئيس كهنة أمينا في ما لله حتى يكفر خطايا الشعب '),
(15404, 'Hebrews', 58, 2, 18, ' لأنه في ما هو قد تألم مجربا يقدر أن يعين المجربين '),
(15405, 'Hebrews', 58, 3, 1, ' من ثم أيها الإخوة القديسون ، شركاء الدعوة السماوية ، لاحظوا رسول اعترافنا ورئيس كهنته المسيح يسوع '),
(15406, 'Hebrews', 58, 3, 2, ' حال كونه أمينا للذي أقامه ، كما كان موسى أيضا في كل بيته '),
(15407, 'Hebrews', 58, 3, 3, ' فإن هذا قد حسب أهلا لمجد أكثر من موسى ، بمقدار ما لباني البيت من كرامة أكثر من البيت '),
(15408, 'Hebrews', 58, 3, 4, ' لأن كل بيت يبنيه إنسان ما ، ولكن باني الكل هو الله '),
(15409, 'Hebrews', 58, 3, 5, ' وموسى كان أمينا في كل بيته كخادم ، شهادة للعتيد أن يتكلم به '),
(15410, 'Hebrews', 58, 3, 6, ' وأما المسيح فكابن على بيته . وبيته نحن إن تمسكنا بثقة الرجاء وافتخاره ثابتة إلى النهاية '),
(15411, 'Hebrews', 58, 3, 7, ' لذلك كما يقول الروح القدس : اليوم ، إن سمعتم صوته '),
(15412, 'Hebrews', 58, 3, 8, ' فلا تقسوا قلوبكم ، كما في الإسخاط ، يوم التجربة في القفر '),
(15413, 'Hebrews', 58, 3, 9, ' حيث جربني آباؤكم . اختبروني وأبصروا أعمالي أربعين سنة '),
(15414, 'Hebrews', 58, 3, 10, ' لذلك مقت ذلك الجيل ، وقلت : إنهم دائما يضلون في قلوبهم ، ولكنهم لم يعرفوا سبلي '),
(15415, 'Hebrews', 58, 3, 11, ' حتى أقسمت في غضبي : لن يدخلوا راحتي '),
(15416, 'Hebrews', 58, 3, 12, ' انظروا أيها الإخوة أن لا يكون في أحدكم قلب شرير بعدم إيمان في الارتداد عن الله الحي '),
(15417, 'Hebrews', 58, 3, 13, ' بل عظوا أنفسكم كل يوم ، ما دام الوقت يدعى اليوم ، لكي لا يقسى أحد منكم بغرور الخطية '),
(15418, 'Hebrews', 58, 3, 14, ' لأننا قد صرنا شركاء المسيح ، إن تمسكنا ببداءة الثقة ثابتة إلى النهاية '),
(15419, 'Hebrews', 58, 3, 15, ' إذ قيل : اليوم ، إن سمعتم صوته فلا تقسوا قلوبكم ، كما في الإسخاط '),
(15420, 'Hebrews', 58, 3, 16, ' فمن هم الذين إذ سمعوا أسخطوا ؟ أليس جميع الذين خرجوا من مصر بواسطة موسى '),
(15421, 'Hebrews', 58, 3, 17, ' ومن مقت أربعين سنة ؟ أليس الذين أخطأوا ، الذين جثثهم سقطت في القفر '),
(15422, 'Hebrews', 58, 3, 18, ' ولمن أقسم : لن يدخلوا راحته ، إلا للذين لم يطيعوا '),
(15423, 'Hebrews', 58, 3, 19, ' فنرى أنهم لم يقدروا أن يدخلوا لعدم الإيمان '),
(15424, 'Hebrews', 58, 4, 1, ' فلنخف ، أنه مع بقاء وعد بالدخول إلى راحته ، يرى أحد منكم أنه قد خاب منه '),
(15425, 'Hebrews', 58, 4, 2, ' لأننا نحن أيضا قد بشرنا كما أولئك ، لكن لم تنفع كلمة الخبر أولئك . إذ لم تكن ممتزجة بالإيمان في الذين سمعوا '),
(15426, 'Hebrews', 58, 4, 3, ' لأننا نحن المؤمنين ندخل الراحة ، كما قال : حتى أقسمت في غضبي : لن يدخلوا راحتي مع كون الأعمال قد أكملت منذ تأسيس العالم '),
(15427, 'Hebrews', 58, 4, 4, ' لأنه قال في موضع عن السابع هكذا : واستراح الله في اليوم السابع من جميع أعماله '),
(15428, 'Hebrews', 58, 4, 5, ' وفي هذا أيضا : لن يدخلوا راحتي '),
(15429, 'Hebrews', 58, 4, 6, ' فإذ بقي أن قوما يدخلونها ، والذين بشروا أولا لم يدخلوا لسبب العصيان '),
(15430, 'Hebrews', 58, 4, 7, ' يعين أيضا يوما قائلا في داود : اليوم بعد زمان هذا مقداره ، كما قيل : اليوم ، إن سمعتم صوته فلا تقسوا قلوبكم '),
(15431, 'Hebrews', 58, 4, 8, ' لأنه لو كان يشوع قد أراحهم لما تكلم بعد ذلك عن يوم آخر '),
(15432, 'Hebrews', 58, 4, 9, ' إذا بقيت راحة لشعب الله '),
(15433, 'Hebrews', 58, 4, 10, ' لأن الذي دخل راحته استراح هو أيضا من أعماله ، كما الله من أعماله '),
(15434, 'Hebrews', 58, 4, 11, ' فلنجتهد أن ندخل تلك الراحة ، لئلا يسقط أحد في عبرة العصيان هذه عينها '),
(15435, 'Hebrews', 58, 4, 12, ' لأن كلمة الله حية وفعالة وأمضى من كل سيف ذي حدين ، وخارقة إلى مفرق النفس والروح والمفاصل والمخاخ ، ومميزة أفكار القلب ونياته '),
(15436, 'Hebrews', 58, 4, 13, ' وليست خليقة غير ظاهرة قدامه ، بل كل شيء عريان ومكشوف لعيني ذلك الذي معه أمرنا '),
(15437, 'Hebrews', 58, 4, 14, ' فإذ لنا رئيس كهنة عظيم قد اجتاز السماوات ، يسوع ابن الله ، فلنتمسك بالإقرار '),
(15438, 'Hebrews', 58, 4, 15, ' لأن ليس لنا رئيس كهنة غير قادر أن يرثي لضعفاتنا ، بل مجرب في كل شيء مثلنا ، بلا خطية '),
(15439, 'Hebrews', 58, 4, 16, ' فلنتقدم بثقة إلى عرش النعمة لكي ننال رحمة ونجد نعمة عونا في حينه '),
(15440, 'Hebrews', 58, 5, 1, ' لأن كل رئيس كهنة مأخوذ من الناس يقام لأجل الناس في ما لله ، لكي يقدم قرابين وذبائح عن الخطايا '),
(15441, 'Hebrews', 58, 5, 2, ' قادرا أن يترفق بالجهال والضالين ، إذ هو أيضا محاط بالضعف '),
(15442, 'Hebrews', 58, 5, 3, ' ولهذا الضعف يلتزم أنه كما يقدم عن الخطايا لأجل الشعب هكذا أيضا لأجل نفسه '),
(15443, 'Hebrews', 58, 5, 4, ' ولا يأخذ أحد هذه الوظيفة بنفسه ، بل المدعو من الله ، كما هارون أيضا '),
(15444, 'Hebrews', 58, 5, 5, ' كذلك المسيح أيضا لم يمجد نفسه ليصير رئيس كهنة ، بل الذي قال له : أنت ابني أنا اليوم ولدتك '),
(15445, 'Hebrews', 58, 5, 6, ' كما يقول أيضا في موضع آخر : أنت كاهن إلى الأبد على رتبة ملكي صادق '),
(15446, 'Hebrews', 58, 5, 7, ' الذي ، في أيام جسده ، إذ قدم بصراخ شديد ودموع طلبات وتضرعات للقادر أن يخلصه من الموت ، وسمع له من أجل تقواه '),
(15447, 'Hebrews', 58, 5, 8, ' مع كونه ابنا تعلم الطاعة مما تألم به '),
(15448, 'Hebrews', 58, 5, 9, ' وإذ كمل صار لجميع الذين يطيعونه ، سبب خلاص أبدي '),
(15449, 'Hebrews', 58, 5, 10, ' مدعوا من الله رئيس كهنة على رتبة ملكي صادق '),
(15450, 'Hebrews', 58, 5, 11, ' الذي من جهته الكلام كثير عندنا ، وعسر التفسير لننطق به ، إذ قد صرتم متباطئي المسامع '),
(15451, 'Hebrews', 58, 5, 12, ' لأنكم - إذ كان ينبغي أن تكونوا معلمين لسبب طول الزمان - تحتاجون أن يعلمكم أحد ما هي أركان بداءة أقوال الله ، وصرتم محتاجين إلى اللبن ، لا إلى طعام قوي '),
(15452, 'Hebrews', 58, 5, 13, ' لأن كل من يتناول اللبن هو عديم الخبرة في كلام البر ، لأنه طفل '),
(15453, 'Hebrews', 58, 5, 14, ' وأما الطعام القوي فللبالغين ، الذين بسبب التمرن قد صارت لهم الحواس مدربة على التمييز بين الخير والشر '),
(15454, 'Hebrews', 58, 6, 1, ' لذلك ونحن تاركون كلام بداءة المسيح ، لنتقدم إلى الكمال ، غير واضعين أيضا أساس التوبة من الأعمال الميتة ، والإيمان بالله '),
(15455, 'Hebrews', 58, 6, 2, ' تعليم المعموديات ، ووضع الأيادي ، قيامة الأموات ، والدينونة الأبدية '),
(15456, 'Hebrews', 58, 6, 3, ' وهذا سنفعله إن أذن الله '),
(15457, 'Hebrews', 58, 6, 4, ' لأن الذين استنيروا مرة ، وذاقوا الموهبة السماوية وصاروا شركاء الروح القدس '),
(15458, 'Hebrews', 58, 6, 5, ' وذاقوا كلمة الله الصالحة وقوات الدهر الآتي '),
(15459, 'Hebrews', 58, 6, 6, ' وسقطوا ، لا يمكن تجديدهم أيضا للتوبة ، إذ هم يصلبون لأنفسهم ابن الله ثانية ويشهرونه '),
(15460, 'Hebrews', 58, 6, 7, ' لأن أرضا قد شربت المطر الآتي عليها مرارا كثيرة ، وأنتجت عشبا صالحا للذين فلحت من أجلهم ، تنال بركة من الله '),
(15461, 'Hebrews', 58, 6, 8, ' ولكن إن أخرجت شوكا وحسكا ، فهي مرفوضة وقريبة من اللعنة ، التي نهايتها للحريق '),
(15462, 'Hebrews', 58, 6, 9, ' ولكننا قد تيقنا من جهتكم أيها الأحباء ، أمورا أفضل ، ومختصة بالخلاص ، وإن كنا نتكلم هكذا '),
(15463, 'Hebrews', 58, 6, 10, ' لأن الله ليس بظالم حتى ينسى عملكم وتعب المحبة التي أظهرتموها نحو اسمه ، إذ قد خدمتم القديسين وتخدمونهم '),
(15464, 'Hebrews', 58, 6, 11, ' ولكننا نشتهي أن كل واحد منكم يظهر هذا الاجتهاد عينه ليقين الرجاء إلى النهاية '),
(15465, 'Hebrews', 58, 6, 12, ' لكي لا تكونوا متباطئين بل متمثلين بالذين بالإيمان والأناة يرثون المواعيد '),
(15466, 'Hebrews', 58, 6, 13, ' فإنه لما وعد الله إبراهيم ، إذ لم يكن له أعظم يقسم به ، أقسم بنفسه '),
(15467, 'Hebrews', 58, 6, 14, ' قائلا : إني لأباركنك بركة وأكثرنك تكثيرا '),
(15468, 'Hebrews', 58, 6, 15, ' وهكذا إذ تأنى نال الموعد '),
(15469, 'Hebrews', 58, 6, 16, ' فإن الناس يقسمون بالأعظم ، ونهاية كل مشاجرة عندهم لأجل التثبيت هي القسم '),
(15470, 'Hebrews', 58, 6, 17, ' فلذلك إذ أراد الله أن يظهر أكثر كثيرا لورثة الموعد عدم تغير قضائه ، توسط بقسم '),
(15471, 'Hebrews', 58, 6, 18, ' حتى بأمرين عديمي التغير ، لا يمكن أن الله يكذب فيهما ، تكون لنا تعزية قوية ، نحن الذين التجأنا لنمسك بالرجاء الموضوع أمامنا '),
(15472, 'Hebrews', 58, 6, 19, ' الذي هو لنا كمرساة للنفس مؤتمنة وثابتة ، تدخل إلى ما داخل الحجاب '),
(15473, 'Hebrews', 58, 6, 20, ' حيث دخل يسوع كسابق لأجلنا ، صائرا على رتبة ملكي صادق ، رئيس كهنة إلى الأبد '),
(15474, 'Hebrews', 58, 7, 1, ' لأن ملكي صادق هذا ، ملك ساليم ، كاهن الله العلي ، الذي استقبل إبراهيم راجعا من كسرة الملوك وباركه '),
(15475, 'Hebrews', 58, 7, 2, ' الذي قسم له إبراهيم عشرا من كل شيء . المترجم أولا ملك البر ثم أيضا ملك ساليم أي ملك السلام '),
(15476, 'Hebrews', 58, 7, 3, ' بلا أب ، بلا أم ، بلا نسب . لا بداءة أيام له ولا نهاية حياة . بل هو مشبه بابن الله . هذا يبقى كاهنا إلى الأبد '),
(15477, 'Hebrews', 58, 7, 4, ' ثم انظروا ما أعظم هذا الذي أعطاه إبراهيم رئيس الآباء ، عشرا أيضا من رأس الغنائم '),
(15478, 'Hebrews', 58, 7, 5, ' وأما الذين هم من بني لاوي ، الذين يأخذون الكهنوت ، فلهم وصية أن يعشروا الشعب بمقتضى الناموس ، أي إخوتهم ، مع أنهم قد خرجوا من صلب إبراهيم '),
(15479, 'Hebrews', 58, 7, 6, ' ولكن الذي ليس له نسب منهم قد عشر إبراهيم ، وبارك الذي له المواعيد '),
(15480, 'Hebrews', 58, 7, 7, ' وبدون كل مشاجرة : الأصغر يبارك من الأكبر '),
(15481, 'Hebrews', 58, 7, 8, ' وهنا أناس مائتون يأخذون عشرا ، وأما هناك فالمشهود له بأنه حي '),
(15482, 'Hebrews', 58, 7, 9, ' حتى أقول كلمة : إن لاوي أيضا الآخذ الأعشار قد عشر بإبراهيم '),
(15483, 'Hebrews', 58, 7, 10, ' لأنه كان بعد في صلب أبيه حين استقبله ملكي صادق '),
(15484, 'Hebrews', 58, 7, 11, ' فلو كان بالكهنوت اللاوي كمال - إذ الشعب أخذ الناموس عليه - ماذا كانت الحاجة بعد إلى أن يقوم كاهن آخر على رتبة ملكي صادق ؟ ولا يقال على رتبة هارون '),
(15485, 'Hebrews', 58, 7, 12, ' لأنه إن تغير الكهنوت ، فبالضرورة يصير تغير للناموس أيضا '),
(15486, 'Hebrews', 58, 7, 13, ' لأن الذي يقال عنه هذا كان شريكا في سبط آخر لم يلازم أحد منه المذبح '),
(15487, 'Hebrews', 58, 7, 14, ' فإنه واضح أن ربنا قد طلع من سبط يهوذا ، الذي لم يتكلم عنه موسى شيئا من جهة الكهنوت '),
(15488, 'Hebrews', 58, 7, 15, ' وذلك أكثر وضوحا أيضا إن كان على شبه ملكي صادق يقوم كاهن آخر '),
(15489, 'Hebrews', 58, 7, 16, ' قد صار ليس بحسب ناموس وصية جسدية ، بل بحسب قوة حياة لا تزول '),
(15490, 'Hebrews', 58, 7, 17, ' لأنه يشهد أنك : كاهن إلى الأبد على رتبة ملكي صادق '),
(15491, 'Hebrews', 58, 7, 18, ' فإنه يصير إبطال الوصية السابقة من أجل ضعفها وعدم نفعها '),
(15492, 'Hebrews', 58, 7, 19, ' إذ الناموس لم يكمل شيئا . ولكن يصير إدخال رجاء أفضل به نقترب إلى الله '),
(15493, 'Hebrews', 58, 7, 20, ' وعلى قدر ما إنه ليس بدون قسم '),
(15494, 'Hebrews', 58, 7, 21, ' لأن أولئك بدون قسم قد صاروا كهنة ، وأما هذا فبقسم من القائل له : أقسم الرب ولن يندم ، أنت كاهن إلى الأبد على رتبة ملكي صادق '),
(15495, 'Hebrews', 58, 7, 22, ' على قدر ذلك قد صار يسوع ضامنا لعهد أفضل '),
(15496, 'Hebrews', 58, 7, 23, ' وأولئك قد صاروا كهنة كثيرين من أجل منعهم بالموت عن البقاء '),
(15497, 'Hebrews', 58, 7, 24, ' وأما هذا فمن أجل أنه يبقى إلى الأبد ، له كهنوت لا يزول '),
(15498, 'Hebrews', 58, 7, 25, ' فمن ثم يقدر أن يخلص أيضا إلى التمام الذين يتقدمون به إلى الله ، إذ هو حي في كل حين ليشفع فيهم '),
(15499, 'Hebrews', 58, 7, 26, ' لأنه كان يليق بنا رئيس كهنة مثل هذا ، قدوس بلا شر ولا دنس ، قد انفصل عن الخطاة وصار أعلى من السماوات '),
(15500, 'Hebrews', 58, 7, 27, ' الذي ليس له اضطرار كل يوم مثل رؤساء الكهنة أن يقدم ذبائح أولا عن خطايا نفسه ثم عن خطايا الشعب ، لأنه فعل هذا مرة واحدة ، إذ قدم نفسه '),
(15501, 'Hebrews', 58, 7, 28, ' فإن الناموس يقيم أناسا بهم ضعف رؤساء كهنة . وأما كلمة القسم التي بعد الناموس فتقيم ابنا مكملا إلى الأبد '),
(15502, 'Hebrews', 58, 8, 1, ' وأما رأس الكلام فهو : أن لنا رئيس كهنة مثل هذا ، قد جلس في يمين عرش العظمة في السماوات '),
(15503, 'Hebrews', 58, 8, 2, ' خادما للأقداس والمسكن الحقيقي الذي نصبه الرب لا إنسان '),
(15504, 'Hebrews', 58, 8, 3, ' لأن كل رئيس كهنة يقام لكي يقدم قرابين وذبائح . فمن ثم يلزم أن يكون لهذا أيضا شيء يقدمه '),
(15505, 'Hebrews', 58, 8, 4, ' فإنه لو كان على الأرض لما كان كاهنا ، إذ يوجد الكهنة الذين يقدمون قرابين حسب الناموس '),
(15506, 'Hebrews', 58, 8, 5, ' الذين يخدمون شبه السماويات وظلها ، كما أوحي إلى موسى وهو مزمع أن يصنع المسكن . لأنه قال : انظر أن تصنع كل شيء حسب المثال الذي أظهر لك في الجبل '),
(15507, 'Hebrews', 58, 8, 6, ' ولكنه الآن قد حصل على خدمة أفضل بمقدار ما هو وسيط أيضا لعهد أعظم ، قد تثبت على مواعيد أفضل '),
(15508, 'Hebrews', 58, 8, 7, ' فإنه لو كان ذلك الأول بلا عيب لما طلب موضع لثان '),
(15509, 'Hebrews', 58, 8, 8, ' لأنه يقول لهم لائما : هوذا أيام تأتي ، يقول الرب ، حين أكمل مع بيت إسرائيل ومع بيت يهوذا عهدا جديدا '),
(15510, 'Hebrews', 58, 8, 9, ' لا كالعهد الذي عملته مع آبائهم يوم أمسكت بيدهم لأخرجهم من أرض مصر ، لأنهم لم يثبتوا في عهدي ، وأنا أهملتهم ، يقول الرب '),
(15511, 'Hebrews', 58, 8, 10, ' لأن هذا هو العهد الذي أعهده مع بيت إسرائيل بعد تلك الأيام ، يقول الرب : أجعل نواميسي في أذهانهم ، وأكتبها على قلوبهم ، وأنا أكون لهم إلها وهم يكونون لي شعبا '),
(15512, 'Hebrews', 58, 8, 11, ' ولا يعلمون كل واحد قريبه ، وكل واحد أخاه قائلا : اعرف الرب ، لأن الجميع سيعرفونني من صغيرهم إلى كبيرهم '),
(15513, 'Hebrews', 58, 8, 12, ' لأني أكون صفوحا عن آثامهم ، ولا أذكر خطاياهم وتعدياتهم في ما بعد '),
(15514, 'Hebrews', 58, 8, 13, ' فإذ قال جديدا عتق الأول . وأما ما عتق وشاخ فهو قريب من الاضمحلال '),
(15515, 'Hebrews', 58, 9, 1, ' ثم العهد الأول كان له أيضا فرائض خدمة والقدس العالمي '),
(15516, 'Hebrews', 58, 9, 2, ' لأنه نصب المسكن الأول الذي يقال له القدس الذي كان فيه المنارة ، والمائدة ، وخبز التقدمة '),
(15517, 'Hebrews', 58, 9, 3, ' ووراء الحجاب الثاني المسكن الذي يقال له قدس الأقداس '),
(15518, 'Hebrews', 58, 9, 4, ' فيه مبخرة من ذهب ، وتابوت العهد مغشى من كل جهة بالذهب ، الذي فيه قسط من ذهب فيه المن ، وعصا هارون التي أفرخت ، ولوحا العهد '),
(15519, 'Hebrews', 58, 9, 5, ' وفوقه كروبا المجد مظللين الغطاء . أشياء ليس لنا الآن أن نتكلم عنها بالتفصيل '),
(15520, 'Hebrews', 58, 9, 6, ' ثم إذ صارت هذه مهيأة هكذا ، يدخل الكهنة إلى المسكن الأول كل حين ، صانعين الخدمة '),
(15521, 'Hebrews', 58, 9, 7, ' وأما إلى الثاني فرئيس الكهنة فقط مرة في السنة ، ليس بلا دم يقدمه عن نفسه وعن جهالات الشعب '),
(15522, 'Hebrews', 58, 9, 8, ' معلنا الروح القدس بهذا أن طريق الأقداس لم يظهر بعد ، ما دام المسكن الأول له إقامة '),
(15523, 'Hebrews', 58, 9, 9, ' الذي هو رمز للوقت الحاضر ، الذي فيه تقدم قرابين وذبائح ، لا يمكن من جهة الضمير أن تكمل الذي يخدم '),
(15524, 'Hebrews', 58, 9, 10, ' وهي قائمة بأطعمة وأشربة وغسلات مختلفة وفرائض جسدية فقط ، موضوعة إلى وقت الإصلاح '),
(15525, 'Hebrews', 58, 9, 11, ' وأما المسيح ، وهو قد جاء رئيس كهنة للخيرات العتيدة ، فبالمسكن الأعظم والأكمل ، غير المصنوع بيد ، أي الذي ليس من هذه الخليقة '),
(15526, 'Hebrews', 58, 9, 12, ' وليس بدم تيوس وعجول ، بل بدم نفسه ، دخل مرة واحدة إلى الأقداس ، فوجد فداء أبديا '),
(15527, 'Hebrews', 58, 9, 13, ' لأنه إن كان دم ثيران وتيوس ورماد عجلة مرشوش على المنجسين ، يقدس إلى طهارة الجسد '),
(15528, 'Hebrews', 58, 9, 14, ' فكم بالحري يكون دم المسيح ، الذي بروح أزلي قدم نفسه لله بلا عيب ، يطهر ضمائركم من أعمال ميتة لتخدموا الله الحي '),
(15529, 'Hebrews', 58, 9, 15, ' ولأجل هذا هو وسيط عهد جديد ، لكي يكون المدعوون - إذ صار موت لفداء التعديات التي في العهد الأول - ينالون وعد الميراث الأبدي '),
(15530, 'Hebrews', 58, 9, 16, ' لأنه حيث توجد وصية ، يلزم بيان موت الموصي '),
(15531, 'Hebrews', 58, 9, 17, ' لأن الوصية ثابتة على الموتى ، إذ لا قوة لها البتة ما دام الموصي حيا '),
(15532, 'Hebrews', 58, 9, 18, ' فمن ثم الأول أيضا لم يكرس بلا دم '),
(15533, 'Hebrews', 58, 9, 19, ' لأن موسى بعدما كلم جميع الشعب بكل وصية بحسب الناموس ، أخذ دم العجول والتيوس ، مع ماء ، وصوفا قرمزيا وزوفا ، ورش الكتاب نفسه وجميع الشعب '),
(15534, 'Hebrews', 58, 9, 20, ' قائلا : هذا هو دم العهد الذي أوصاكم الله به '),
(15535, 'Hebrews', 58, 9, 21, ' والمسكن أيضا وجميع آنية الخدمة رشها كذلك بالدم '),
(15536, 'Hebrews', 58, 9, 22, ' وكل شيء تقريبا يتطهر حسب الناموس بالدم ، وبدون سفك دم لا تحصل مغفرة '),
(15537, 'Hebrews', 58, 9, 23, ' فكان يلزم أن أمثلة الأشياء التي في السماوات تطهر بهذه ، وأما السماويات عينها ، فبذبائح أفضل من هذه '),
(15538, 'Hebrews', 58, 9, 24, ' لأن المسيح لم يدخل إلى أقداس مصنوعة بيد أشباه الحقيقية ، بل إلى السماء عينها ، ليظهر الآن أمام وجه الله لأجلنا '),
(15539, 'Hebrews', 58, 9, 25, ' ولا ليقدم نفسه مرارا كثيرة ، كما يدخل رئيس الكهنة إلى الأقداس كل سنة بدم آخر '),
(15540, 'Hebrews', 58, 9, 26, ' فإذ ذاك كان يجب أن يتألم مرارا كثيرة منذ تأسيس العالم ، ولكنه الآن قد أظهر مرة عند انقضاء الدهور ليبطل الخطية بذبيحة نفسه '),
(15541, 'Hebrews', 58, 9, 27, ' وكما وضع للناس أن يموتوا مرة ثم بعد ذلك الدينونة '),
(15542, 'Hebrews', 58, 9, 28, ' هكذا المسيح أيضا ، بعدما قدم مرة لكي يحمل خطايا كثيرين ، سيظهر ثانية بلا خطية للخلاص للذين ينتظرونه '),
(15543, 'Hebrews', 58, 10, 1, ' لأن الناموس ، إذ له ظل الخيرات العتيدة لا نفس صورة الأشياء ، لا يقدر أبدا بنفس الذبائح كل سنة ، التي يقدمونها على الدوام ، أن يكمل الذين يتقدمون '),
(15544, 'Hebrews', 58, 10, 2, ' وإلا ، أفما زالت تقدم ؟ من أجل أن الخادمين ، وهم مطهرون مرة ، لا يكون لهم أيضا ضمير خطايا '),
(15545, 'Hebrews', 58, 10, 3, ' لكن فيها كل سنة ذكر خطايا '),
(15546, 'Hebrews', 58, 10, 4, ' لأنه لا يمكن أن دم ثيران وتيوس يرفع خطايا '),
(15547, 'Hebrews', 58, 10, 5, ' لذلك عند دخوله إلى العالم يقول : ذبيحة وقربانا لم ترد ، ولكن هيأت لي جسدا '),
(15548, 'Hebrews', 58, 10, 6, ' بمحرقات وذبائح للخطية لم تسر '),
(15549, 'Hebrews', 58, 10, 7, ' ثم قلت : هنذا أجيء . في درج الكتاب مكتوب عني ، لأفعل مشيئتك يا ألله '),
(15550, 'Hebrews', 58, 10, 8, ' إذ يقول آنفا : إنك ذبيحة وقربانا ومحرقات وذبائح للخطية لم ترد ولا سررت بها . التي تقدم حسب الناموس '),
(15551, 'Hebrews', 58, 10, 9, ' ثم قال : هنذا أجيء لأفعل مشيئتك يا الله . ينزع الأول لكي يثبت الثاني '),
(15552, 'Hebrews', 58, 10, 10, ' فبهذه المشيئة نحن مقدسون بتقديم جسد يسوع المسيح مرة واحدة '),
(15553, 'Hebrews', 58, 10, 11, ' وكل كاهن يقوم كل يوم يخدم ويقدم مرارا كثيرة تلك الذبائح عينها ، التي لا تستطيع البتة أن تنزع الخطية '),
(15554, 'Hebrews', 58, 10, 12, ' وأما هذا فبعدما قدم عن الخطايا ذبيحة واحدة ، جلس إلى الأبد عن يمين الله '),
(15555, 'Hebrews', 58, 10, 13, ' منتظرا بعد ذلك حتى توضع أعداؤه موطئا لقدميه '),
(15556, 'Hebrews', 58, 10, 14, ' لأنه بقربان واحد قد أكمل إلى الأبد المقدسين '),
(15557, 'Hebrews', 58, 10, 15, ' ويشهد لنا الروح القدس أيضا . لأنه بعدما قال سابقا '),
(15558, 'Hebrews', 58, 10, 16, ' هذا هو العهد الذي أعهده معهم بعد تلك الأيام ، يقول الرب ، أجعل نواميسي في قلوبهم وأكتبها في أذهانهم '),
(15559, 'Hebrews', 58, 10, 17, ' ولن أذكر خطاياهم وتعدياتهم في ما بعد '),
(15560, 'Hebrews', 58, 10, 18, ' وإنما حيث تكون مغفرة لهذه لا يكون بعد قربان عن الخطية '),
(15561, 'Hebrews', 58, 10, 19, ' فإذ لنا أيها الإخوة ثقة بالدخول إلى الأقداس بدم يسوع '),
(15562, 'Hebrews', 58, 10, 20, ' طريقا كرسه لنا حديثا حيا ، بالحجاب ، أي جسده '),
(15563, 'Hebrews', 58, 10, 21, ' وكاهن عظيم على بيت الله '),
(15564, 'Hebrews', 58, 10, 22, ' لنتقدم بقلب صادق في يقين الإيمان ، مرشوشة قلوبنا من ضمير شرير ، ومغتسلة أجسادنا بماء نقي '),
(15565, 'Hebrews', 58, 10, 23, ' لنتمسك بإقرار الرجاء راسخا ، لأن الذي وعد هو أمين '),
(15566, 'Hebrews', 58, 10, 24, ' ولنلاحظ بعضنا بعضا للتحريض على المحبة والأعمال الحسنة '),
(15567, 'Hebrews', 58, 10, 25, ' غير تاركين اجتماعنا كما لقوم عادة ، بل واعظين بعضنا بعضا ، وبالأكثر على قدر ما ترون اليوم يقرب '),
(15568, 'Hebrews', 58, 10, 26, ' فإنه إن أخطأنا باختيارنا بعدما أخذنا معرفة الحق ، لا تبقى بعد ذبيحة عن الخطايا '),
(15569, 'Hebrews', 58, 10, 27, ' بل قبول دينونة مخيف ، وغيرة نار عتيدة أن تأكل المضادين '),
(15570, 'Hebrews', 58, 10, 28, ' من خالف ناموس موسى فعلى شاهدين أو ثلاثة شهود يموت بدون رأفة '),
(15571, 'Hebrews', 58, 10, 29, ' فكم عقابا أشر تظنون أنه يحسب مستحقا من داس ابن الله ، وحسب دم العهد الذي قدس به دنسا ، وازدرى بروح النعمة '),
(15572, 'Hebrews', 58, 10, 30, ' فإننا نعرف الذي قال : لي الانتقام ، أنا أجازي ، يقول الرب . وأيضا : الرب يدين شعبه ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(15573, 'Hebrews', 58, 10, 31, ' مخيف هو الوقوع في يدي الله الحي '),
(15574, 'Hebrews', 58, 10, 32, ' ولكن تذكروا الأيام السالفة التي فيها بعدما أنرتم صبرتم على مجاهدة آلام كثيرة '),
(15575, 'Hebrews', 58, 10, 33, ' من جهة مشهورين بتعييرات وضيقات ، ومن جهة صائرين شركاء الذين تصرف فيهم هكذا '),
(15576, 'Hebrews', 58, 10, 34, ' لأنكم رثيتم لقيودي أيضا ، وقبلتم سلب أموالكم بفرح ، عالمين في أنفسكم أن لكم مالا أفضل في السماوات وباقيا '),
(15577, 'Hebrews', 58, 10, 35, ' فلا تطرحوا ثقتكم التي لها مجازاة عظيمة '),
(15578, 'Hebrews', 58, 10, 36, ' لأنكم تحتاجون إلى الصبر ، حتى إذا صنعتم مشيئة الله تنالون الموعد '),
(15579, 'Hebrews', 58, 10, 37, ' لأنه بعد قليل جدا : سيأتي الآتي ولا يبطئ '),
(15580, 'Hebrews', 58, 10, 38, ' أما البار فبالإيمان يحيا ، وإن ارتد لا تسر به نفسي '),
(15581, 'Hebrews', 58, 10, 39, ' وأما نحن فلسنا من الارتداد للهلاك ، بل من الإيمان لاقتناء النفس '),
(15582, 'Hebrews', 58, 11, 1, ' وأما الإيمان فهو الثقة بما يرجى والإيقان بأمور لا ترى '),
(15583, 'Hebrews', 58, 11, 2, ' فإنه في هذا شهد للقدماء '),
(15584, 'Hebrews', 58, 11, 3, ' بالإيمان نفهم أن العالمين أتقنت بكلمة الله ، حتى لم يتكون ما يرى مما هو ظاهر '),
(15585, 'Hebrews', 58, 11, 4, ' بالإيمان قدم هابيل لله ذبيحة أفضل من قايين . فبه شهد له أنه بار ، إذ شهد الله لقرابينه . وبه ، وإن مات ، يتكلم بعد '),
(15586, 'Hebrews', 58, 11, 5, ' بالإيمان نقل أخنوخ لكي لا يرى الموت ، ولم يوجد لأن الله نقله . إذ قبل نقله شهد له بأنه قد أرضى الله '),
(15587, 'Hebrews', 58, 11, 6, ' ولكن بدون إيمان لا يمكن إرضاؤه ، لأنه يجب أن الذي يأتي إلى الله يؤمن بأنه موجود ، وأنه يجازي الذين يطلبونه '),
(15588, 'Hebrews', 58, 11, 7, ' بالإيمان نوح لما أوحي إليه عن أمور لم تر بعد خاف ، فبنى فلكا لخلاص بيته ، فبه دان العالم ، وصار وارثا للبر الذي حسب الإيمان '),
(15589, 'Hebrews', 58, 11, 8, ' بالإيمان إبراهيم لما دعي أطاع أن يخرج إلى المكان الذي كان عتيدا أن يأخذه ميراثا ، فخرج وهو لا يعلم إلى أين يأتي '),
(15590, 'Hebrews', 58, 11, 9, ' بالإيمان تغرب في أرض الموعد كأنها غريبة ، ساكنا في خيام مع إسحاق ويعقوب الوارثين معه لهذا الموعد عينه '),
(15591, 'Hebrews', 58, 11, 10, ' لأنه كان ينتظر المدينة التي لها الأساسات ، التي صانعها وبارئها الله '),
(15592, 'Hebrews', 58, 11, 11, ' بالإيمان سارة نفسها أيضا أخذت قدرة على إنشاء نسل ، وبعد وقت السن ولدت ، إذ حسبت الذي وعد صادقا '),
(15593, 'Hebrews', 58, 11, 12, ' لذلك ولد أيضا من واحد ، وذلك من ممات ، مثل نجوم السماء في الكثرة ، وكالرمل الذي على شاطئ البحر الذي لا يعد '),
(15594, 'Hebrews', 58, 11, 13, ' في الإيمان مات هؤلاء أجمعون ، وهم لم ينالوا المواعيد ، بل من بعيد نظروها وصدقوها وحيوها ، وأقروا بأنهم غرباء ونزلاء على الأرض '),
(15595, 'Hebrews', 58, 11, 14, ' فإن الذين يقولون مثل هذا يظهرون أنهم يطلبون وطنا '),
(15596, 'Hebrews', 58, 11, 15, ' فلو ذكروا ذلك الذي خرجوا منه ، لكان لهم فرصة للرجوع '),
(15597, 'Hebrews', 58, 11, 16, ' ولكن الآن يبتغون وطنا أفضل ، أي سماويا . لذلك لا يستحي بهم الله أن يدعى إلههم ، لأنه أعد لهم مدينة '),
(15598, 'Hebrews', 58, 11, 17, ' بالإيمان قدم إبراهيم إسحاق وهو مجرب . قدم الذي قبل المواعيد ، وحيده '),
(15599, 'Hebrews', 58, 11, 18, ' الذي قيل له : إنه بإسحاق يدعى لك نسل '),
(15600, 'Hebrews', 58, 11, 19, ' إذ حسب أن الله قادر على الإقامة من الأموات أيضا ، الذين منهم أخذه أيضا في مثال '),
(15601, 'Hebrews', 58, 11, 20, ' بالإيمان إسحاق بارك يعقوب وعيسو من جهة أمور عتيدة '),
(15602, 'Hebrews', 58, 11, 21, ' بالإيمان يعقوب عند موته بارك كل واحد من ابني يوسف ، وسجد على رأس عصاه '),
(15603, 'Hebrews', 58, 11, 22, ' بالإيمان يوسف عند موته ذكر خروج بني إسرائيل وأوصى من جهة عظامه '),
(15604, 'Hebrews', 58, 11, 23, ' بالإيمان موسى ، بعدما ولد ، أخفاه أبواه ثلاثة أشهر ، لأنهما رأيا الصبي جميلا ، ولم يخشيا أمر الملك '),
(15605, 'Hebrews', 58, 11, 24, ' بالإيمان موسى لما كبر أبى أن يدعى ابن ابنة فرعون '),
(15606, 'Hebrews', 58, 11, 25, ' مفضلا بالأحرى أن يذل مع شعب الله على أن يكون له تمتع وقتي بالخطية '),
(15607, 'Hebrews', 58, 11, 26, ' حاسبا عار المسيح غنى أعظم من خزائن مصر ، لأنه كان ينظر إلى المجازاة '),
(15608, 'Hebrews', 58, 11, 27, ' بالإيمان ترك مصر غير خائف من غضب الملك ، لأنه تشدد ، كأنه يرى من لا يرى '),
(15609, 'Hebrews', 58, 11, 28, ' بالإيمان صنع الفصح ورش الدم لئلا يمسهم الذي أهلك الأبكار '),
(15610, 'Hebrews', 58, 11, 29, ' بالإيمان اجتازوا في البحر الأحمر كما في اليابسة ، الأمر الذي لما شرع فيه المصريون غرقوا '),
(15611, 'Hebrews', 58, 11, 30, ' بالإيمان سقطت أسوار أريحا بعدما طيف حولها سبعة أيام '),
(15612, 'Hebrews', 58, 11, 31, ' بالإيمان راحاب الزانية لم تهلك مع العصاة ، إذ قبلت الجاسوسين بسلام '),
(15613, 'Hebrews', 58, 11, 32, ' وماذا أقول أيضا ؟ لأنه يعوزني الوقت إن أخبرت عن جدعون ، وباراق ، وشمشون ، ويفتاح ، وداود ، وصموئيل ، والأنبياء '),
(15614, 'Hebrews', 58, 11, 33, ' الذين بالإيمان : قهروا ممالك ، صنعوا برا ، نالوا مواعيد ، سدوا أفواه أسود '),
(15615, 'Hebrews', 58, 11, 34, ' أطفأوا قوة النار ، نجوا من حد السيف ، تقووا من ضعف ، صاروا أشداء في الحرب ، هزموا جيوش غرباء '),
(15616, 'Hebrews', 58, 11, 35, ' أخذت نساء أمواتهن بقيامة . وآخرون عذبوا ولم يقبلوا النجاة لكي ينالوا قيامة أفضل '),
(15617, 'Hebrews', 58, 11, 36, ' وآخرون تجربوا في هزء وجلد ، ثم في قيود أيضا وحبس '),
(15618, 'Hebrews', 58, 11, 37, ' رجموا ، نشروا ، جربوا ، ماتوا قتلا بالسيف ، طافوا في جلود غنم وجلود معزى ، معتازين مكروبين مذلين '),
(15619, 'Hebrews', 58, 11, 38, ' وهم لم يكن العالم مستحقا لهم . تائهين في براري وجبال ومغاير وشقوق الأرض '),
(15620, 'Hebrews', 58, 11, 39, ' فهؤلاء كلهم ، مشهودا لهم بالإيمان ، لم ينالوا الموعد '),
(15621, 'Hebrews', 58, 11, 40, ' إذ سبق الله فنظر لنا شيئا أفضل ، لكي لا يكملوا بدوننا '),
(15622, 'Hebrews', 58, 12, 1, ' لذلك نحن أيضا إذ لنا سحابة من الشهود مقدار هذه محيطة بنا ، لنطرح كل ثقل ، والخطية المحيطة بنا بسهولة ، ولنحاضر بالصبر في الجهاد الموضوع أمامنا '),
(15623, 'Hebrews', 58, 12, 2, ' ناظرين إلى رئيس الإيمان ومكمله يسوع ، الذي من أجل السرور الموضوع أمامه ، احتمل الصليب مستهينا بالخزي ، فجلس في يمين عرش الله '),
(15624, 'Hebrews', 58, 12, 3, ' فتفكروا في الذي احتمل من الخطاة مقاومة لنفسه مثل هذه لئلا تكلوا وتخوروا في نفوسكم '),
(15625, 'Hebrews', 58, 12, 4, ' لم تقاوموا بعد حتى الدم مجاهدين ضد الخطية '),
(15626, 'Hebrews', 58, 12, 5, ' وقد نسيتم الوعظ الذي يخاطبكم كبنين : يا ابني ، لا تحتقر تأديب الرب ، ولا تخر إذا وبخك '),
(15627, 'Hebrews', 58, 12, 6, ' لأن الذي يحبه الرب يؤدبه ، ويجلد كل ابن يقبله '),
(15628, 'Hebrews', 58, 12, 7, ' إن كنتم تحتملون التأديب يعاملكم الله كالبنين . فأي ابن لا يؤدبه أبوه '),
(15629, 'Hebrews', 58, 12, 8, ' ولكن إن كنتم بلا تأديب ، قد صار الجميع شركاء فيه ، فأنتم نغول لا بنون '),
(15630, 'Hebrews', 58, 12, 9, ' ثم قد كان لنا آباء أجسادنا مؤدبين ، وكنا نهابهم . أفلا نخضع بالأولى جدا لأبي الأرواح ، فنحيا '),
(15631, 'Hebrews', 58, 12, 10, ' لأن أولئك أدبونا أياما قليلة حسب استحسانهم ، وأما هذا فلأجل المنفعة ، لكي نشترك في قداسته '),
(15632, 'Hebrews', 58, 12, 11, ' ولكن كل تأديب في الحاضر لا يرى أنه للفرح بل للحزن . وأما أخيرا فيعطي الذين يتدربون به ثمر بر للسلام '),
(15633, 'Hebrews', 58, 12, 12, ' لذلك قوموا الأيادي المسترخية والركب المخلعة '),
(15634, 'Hebrews', 58, 12, 13, ' واصنعوا لأرجلكم مسالك مستقيمة ، لكي لا يعتسف الأعرج ، بل بالحري يشفى '),
(15635, 'Hebrews', 58, 12, 14, ' اتبعوا السلام مع الجميع ، والقداسة التي بدونها لن يرى أحد الرب '),
(15636, 'Hebrews', 58, 12, 15, ' ملاحظين لئلا يخيب أحد من نعمة الله . لئلا يطلع أصل مرارة ويصنع انزعاجا ، فيتنجس به كثيرون '),
(15637, 'Hebrews', 58, 12, 16, ' لئلا يكون أحد زانيا أو مستبيحا كعيسو ، الذي لأجل أكلة واحدة باع بكوريته '),
(15638, 'Hebrews', 58, 12, 17, ' فإنكم تعلمون أنه أيضا بعد ذلك ، لما أراد أن يرث البركة رفض ، إذ لم يجد للتوبة مكانا ، مع أنه طلبها بدموع '),
(15639, 'Hebrews', 58, 12, 18, ' لأنكم لم تأتوا إلى جبل ملموس مضطرم بالنار ، وإلى ضباب وظلام وزوبعة '),
(15640, 'Hebrews', 58, 12, 19, ' وهتاف بوق وصوت كلمات ، استعفى الذين سمعوه من أن تزاد لهم كلمة '),
(15641, 'Hebrews', 58, 12, 20, ' لأنهم لم يحتملوا ما أمر به : وإن مست الجبل بهيمة ، ترجم أو ترمى بسهم '),
(15642, 'Hebrews', 58, 12, 21, ' وكان المنظر هكذا مخيفا حتى قال موسى : أنا مرتعب ومرتعد '),
(15643, 'Hebrews', 58, 12, 22, ' بل قد أتيتم إلى جبل صهيون ، وإلى مدينة الله الحي . أورشليم السماوية ، وإلى ربوات هم محفل ملائكة '),
(15644, 'Hebrews', 58, 12, 23, ' وكنيسة أبكار مكتوبين في السماوات ، وإلى الله ديان الجميع ، وإلى أرواح أبرار مكملين '),
(15645, 'Hebrews', 58, 12, 24, ' وإلى وسيط العهد الجديد : يسوع ، وإلى دم رش يتكلم أفضل من هابيل '),
(15646, 'Hebrews', 58, 12, 25, ' انظروا أن لا تستعفوا من المتكلم . لأنه إن كان أولئك لم ينجوا إذ استعفوا من المتكلم على الأرض ، فبالأولى جدا لا ننجو نحن المرتدين عن الذي من السماء '),
(15647, 'Hebrews', 58, 12, 26, ' الذي صوته زعزع الأرض حينئذ ، وأما الآن فقد وعد قائلا : إني مرة أيضا أزلزل لا الأرض فقط بل السماء أيضا '),
(15648, 'Hebrews', 58, 12, 27, ' فقوله مرة أيضا يدل على تغيير الأشياء المتزعزعة كمصنوعة ، لكي تبقى التي لا تتزعزع '),
(15649, 'Hebrews', 58, 12, 28, ' لذلك ونحن قابلون ملكوتا لا يتزعزع ، ليكن عندنا شكر به نخدم الله خدمة مرضية ، بخشوع وتقوى '),
(15650, 'Hebrews', 58, 12, 29, ' لأن إلهنا نار آكلة '),
(15651, 'Hebrews', 58, 13, 1, ' لتثبت المحبة الأخوية '),
(15652, 'Hebrews', 58, 13, 2, ' لا تنسوا إضافة الغرباء ، لأن بها أضاف أناس ملائكة وهم لا يدرون '),
(15653, 'Hebrews', 58, 13, 3, ' اذكروا المقيدين كأنكم مقيدون معهم ، والمذلين كأنكم أنتم أيضا في الجسد '),
(15654, 'Hebrews', 58, 13, 4, ' ليكن الزواج مكرما عند كل واحد ، والمضجع غير نجس . وأما العاهرون والزناة فسيدينهم الله '),
(15655, 'Hebrews', 58, 13, 5, ' لتكن سيرتكم خالية من محبة المال . كونوا مكتفين بما عندكم ، لأنه قال : لا أهملك ولا أتركك '),
(15656, 'Hebrews', 58, 13, 6, ' حتى إننا نقول واثقين : الرب معين لي فلا أخاف . ماذا يصنع بي إنسان '),
(15657, 'Hebrews', 58, 13, 7, ' اذكروا مرشديكم الذين كلموكم بكلمة الله . انظروا إلى نهاية سيرتهم فتمثلوا بإيمانهم '),
(15658, 'Hebrews', 58, 13, 8, ' يسوع المسيح هو هو أمسا واليوم وإلى الأبد '),
(15659, 'Hebrews', 58, 13, 9, ' لا تساقوا بتعاليم متنوعة وغريبة ، لأنه حسن أن يثبت القلب بالنعمة ، لا بأطعمة لم ينتفع بها الذين تعاطوها '),
(15660, 'Hebrews', 58, 13, 10, ' لنا مذبح لا سلطان للذين يخدمون المسكن أن يأكلوا منه '),
(15661, 'Hebrews', 58, 13, 11, ' فإن الحيوانات التي يدخل بدمها عن الخطية إلى الأقداس بيد رئيس الكهنة تحرق أجسامها خارج المحلة '),
(15662, 'Hebrews', 58, 13, 12, ' لذلك يسوع أيضا ، لكي يقدس الشعب بدم نفسه ، تألم خارج الباب '),
(15663, 'Hebrews', 58, 13, 13, ' فلنخرج إذا إليه خارج المحلة حاملين عاره '),
(15664, 'Hebrews', 58, 13, 14, ' لأن ليس لنا هنا مدينة باقية ، لكننا نطلب العتيدة '),
(15665, 'Hebrews', 58, 13, 15, ' فلنقدم به في كل حين لله ذبيحة التسبيح ، أي ثمر شفاه معترفة باسمه '),
(15666, 'Hebrews', 58, 13, 16, ' ولكن لا تنسوا فعل الخير والتوزيع ، لأنه بذبائح مثل هذه يسر الله '),
(15667, 'Hebrews', 58, 13, 17, ' أطيعوا مرشديكم واخضعوا ، لأنهم يسهرون لأجل نفوسكم كأنهم سوف يعطون حسابا ، لكي يفعلوا ذلك بفرح ، لا آنين ، لأن هذا غير نافع لكم '),
(15668, 'Hebrews', 58, 13, 18, ' صلوا لأجلنا ، لأننا نثق أن لنا ضميرا صالحا ، راغبين أن نتصرف حسنا في كل شيء '),
(15669, 'Hebrews', 58, 13, 19, ' ولكن أطلب أكثر أن تفعلوا هذا لكي أرد إليكم بأكثر سرعة '),
(15670, 'Hebrews', 58, 13, 20, ' وإله السلام الذي أقام من الأموات راعي الخراف العظيم ، ربنا يسوع ، بدم العهد الأبدي '),
(15671, 'Hebrews', 58, 13, 21, ' ليكملكم في كل عمل صالح لتصنعوا مشيئته ، عاملا فيكم ما يرضي أمامه بيسوع المسيح ، الذي له المجد إلى أبد الآبدين . آمين '),
(15672, 'Hebrews', 58, 13, 22, ' وأطلب إليكم أيها الإخوة أن تحتملوا كلمة الوعظ ، لأني بكلمات قليلة كتبت إليكم '),
(15673, 'Hebrews', 58, 13, 23, ' اعلموا أنه قد أطلق الأخ تيموثاوس ، الذي معه سوف أراكم ، إن أتى سريعا '),
(15674, 'Hebrews', 58, 13, 24, ' سلموا على جميع مرشديكم وجميع القديسين . يسلم عليكم الذين من إيطاليا '),
(15675, 'Hebrews', 58, 13, 25, ' النعمة مع جميعكم . آمين '),
(15676, 'Hosea', 28, 10, 1, ' إسرائيل جفنة ممتدة . يخرج ثمرا لنفسه . على حسب كثرة ثمره قد كثر المذابح . على حسب جودة أرضه أجاد الأنصاب '),
(15677, 'Hosea', 28, 10, 2, ' قد قسموا قلوبهم . الآن يعاقبون . هو يحطم مذابحهم ، يخرب أنصابهم '),
(15678, 'Hosea', 28, 10, 3, ' إنهم الآن يقولون : لا ملك لنا لأننا لا نخاف الرب ، فالملك ماذا يصنع بنا '),
(15679, 'Hosea', 28, 10, 4, ' يتكلمون كلاما بأقسام باطلة . يقطعون عهدا فينبت القضاء عليهم كالعلقم في أتلام الحقل '),
(15680, 'Hosea', 28, 10, 5, ' على عجول بيت آون يخاف سكان السامرة . إن شعبه ينوح عليه ، وكهنته عليه يرتعدون على مجده ، لأنه انتفى عنه '),
(15681, 'Hosea', 28, 10, 6, ' وهو أيضا يجلب إلى أشور هدية لملك عدو . يأخذ أفرايم خزيا ، ويخجل إسرائيل على رأيه '),
(15682, 'Hosea', 28, 10, 7, ' السامرة ملكها يبيد كغثاء على وجه الماء '),
(15683, 'Hosea', 28, 10, 8, ' وتخرب شوامخ آون ، خطية إسرائيل . يطلع الشوك والحسك على مذابحهم ، ويقولون للجبال : غطينا ، وللتلال : اسقطي علينا '),
(15684, 'Hosea', 28, 10, 9, ' من أيام جبعة أخطأت يا إسرائيل . هناك وقفوا . لم تدركهم في جبعة الحرب على بني الإثم '),
(15685, 'Hosea', 28, 10, 10, ' حينما أريد أؤدبهم ، ويجتمع عليهم شعوب في ارتباطهم بإثميهم '),
(15686, 'Hosea', 28, 10, 11, ' وأفرايم عجلة متمرنة تحب الدراس ، ولكني أجتاز على عنقها الحسن . أركب على أفرايم . يفلح يهوذا . يمهد يعقوب '),
(15687, 'Hosea', 28, 10, 12, ' ازرعوا لأنفسكم بالبر . احصدوا بحسب الصلاح . احرثوا لأنفسكم حرثا ، فإنه وقت لطلب الرب حتى يأتي ويعلمكم البر '),
(15688, 'Hosea', 28, 10, 13, ' قد حرثتم النفاق ، حصدتم الإثم ، أكلتم ثمر الكذب . لأنك وثقت بطريقك ، بكثرة أبطالك '),
(15689, 'Hosea', 28, 10, 14, ' يقوم ضجيج في شعوبك ، وتخرب جميع حصونك كإخراب شلمان بيت أربئيل في يوم الحرب . الأم مع الأولاد حطمت '),
(15690, 'Hosea', 28, 10, 15, ' هكذا تصنع بكم بيت إيل من أجل رداءة شركم . في الصبح يهلك ملك إسرائيل هلاكا '),
(15691, 'Hosea', 28, 11, 1, ' لما كان إسرائيل غلاما أحببته ، ومن مصر دعوت ابني '),
(15692, 'Hosea', 28, 11, 2, ' كل ما دعوهم ذهبوا من أمامهم يذبحون للبعليم ، ويبخرون للتماثيل المنحوتة '),
(15693, 'Hosea', 28, 11, 3, ' وأنا درجت أفرايم ممسكا إياهم بأذرعهم ، فلم يعرفوا أني شفيتهم '),
(15694, 'Hosea', 28, 11, 4, ' كنت أجذبهم بحبال البشر ، بربط المحبة ، وكنت لهم كمن يرفع النير عن أعناقهم ، ومددت إليه مطعما إياه '),
(15695, 'Hosea', 28, 11, 5, ' لا يرجع إلى أرض مصر ، بل أشور هو ملكه ، لأنهم أبوا أن يرجعوا '),
(15696, 'Hosea', 28, 11, 6, ' يثور السيف في مدنهم ويتلف عصيها ، ويأكلهم من أجل آرائهم '),
(15697, 'Hosea', 28, 11, 7, ' وشعبي جانحون إلى الارتداد عني ، فيدعونهم إلى العلي ولا أحد يرفعه '),
(15698, 'Hosea', 28, 11, 8, ' كيف أجعلك يا أفرايم ، أصيرك يا إسرائيل كيف أجعلك كأدمة ، أصنعك كصبوييم قد انقلب علي قلبي . اضطرمت مراحمي جميعا '),
(15699, 'Hosea', 28, 11, 9, ' لا أجري حمو غضبي . لا أعود أخرب أفرايم ، لأني الله لا إنسان ، القدوس في وسطك فلا آتي بسخط '),
(15700, 'Hosea', 28, 11, 10, ' وراء الرب يمشون . كأسد يزمجر . فإنه يزمجر فيسرع البنون من البحر '),
(15701, 'Hosea', 28, 11, 11, ' يسرعون كعصفور من مصر ، وكحمامة من أرض أشور ، فأسكنهم في بيوتهم ، يقول الرب '),
(15702, 'Hosea', 28, 11, 12, ' قد أحاط بي أفرايم بالكذب ، وبيت إسرائيل بالمكر ، ولم يزل يهوذا شاردا عن الله وعن القدوس الأمين '),
(15703, 'Hosea', 28, 12, 1, ' أفرايم راعي الريح ، وتابع الريح الشرقية . كل يوم يكثر الكذب والاغتصاب ، ويقطعون مع أشور عهدا ، والزيت إلى مصر يجلب '),
(15704, 'Hosea', 28, 12, 2, ' فللرب خصام مع يهوذا ، وهو مزمع أن يعاقب يعقوب بحسب طرقه . بحسب أفعاله يرد عليه '),
(15705, 'Hosea', 28, 12, 3, ' في البطن قبض بعقب أخيه ، وبقوته جاهد مع الله '),
(15706, 'Hosea', 28, 12, 4, ' جاهد مع الملاك وغلب . بكى واسترحمه . وجده في بيت إيل وهناك تكلم معنا '),
(15707, 'Hosea', 28, 12, 5, ' والرب إله الجنود يهوه اسمه '),
(15708, 'Hosea', 28, 12, 6, ' وأنت فارجع إلى إلهك . احفظ الرحمة والحق ، وانتظر إلهك دائما '),
(15709, 'Hosea', 28, 12, 7, ' مثل الكنعاني في يده موازين الغش . يحب أن يظلم '),
(15710, 'Hosea', 28, 12, 8, ' فقال أفرايم : إني صرت غنيا . وجدت لنفسي ثروة . جميع أتعابي لا يجدون لي فيها ذنبا هو خطية '),
(15711, 'Hosea', 28, 12, 9, ' وأنا الرب إلهك من أرض مصر حتى أسكنك الخيام كأيام الموسم '),
(15712, 'Hosea', 28, 12, 10, ' وكلمت الأنبياء وكثرت الرؤى ، وبيد الأنبياء مثلت أمثالا '),
(15713, 'Hosea', 28, 12, 11, ' إنهم في جلعاد قد صاروا إثما ، بطلا لا غير . في الجلجال ذبحوا ثيرانا ، ومذابحهم كرجم في أتلام الحقل '),
(15714, 'Hosea', 28, 12, 12, ' وهرب يعقوب إلى صحراء أرام ، وخدم إسرائيل لأجل امرأة ، ولأجل امرأة رعى '),
(15715, 'Hosea', 28, 12, 13, ' وبنبي أصعد الرب إسرائيل من مصر ، وبنبي حفظ '),
(15716, 'Hosea', 28, 12, 14, ' أغاظه إسرائيل بمرارة ، فيترك دماءه عليه ، ويرد سيده عاره عليه '),
(15717, 'Hosea', 28, 13, 1, ' لما تكلم أفرايم برعدة ، ترفع في إسرائيل . ولما أثم ببعل مات '),
(15718, 'Hosea', 28, 13, 2, ' والآن يزدادون خطية ، ويصنعون لأنفسهم تماثيل مسبوكة من فضتهم ، أصناما بحذاقتهم ، كلها عمل الصناع . عنها هم يقولون : ذابحو الناس يقبلون العجول '),
(15719, 'Hosea', 28, 13, 3, ' لذلك يكونون كسحاب الصبح ، وكالندى الماضي باكرا . كعصافة تخطف من البيدر ، وكدخان من الكوة '),
(15720, 'Hosea', 28, 13, 4, ' وأنا الرب إلهك من أرض مصر ، وإلها سواي لست تعرف ، ولا مخلص غيري '),
(15721, 'Hosea', 28, 13, 5, ' أنا عرفتك في البرية في أرض العطش '),
(15722, 'Hosea', 28, 13, 6, ' لما رعوا شبعوا . شبعوا وارتفعت قلوبهم ، لذلك نسوني '),
(15723, 'Hosea', 28, 13, 7, ' فأكون لهم كأسد . أرصد على الطريق كنمر '),
(15724, 'Hosea', 28, 13, 8, ' أصدمهم كدبة مثكل ، وأشق شغاف قلبهم ، وآكلهم هناك كلبوة . يمزقهم وحش البرية '),
(15725, 'Hosea', 28, 13, 9, ' هلاكك يا إسرائيل أنك علي ، على عونك '),
(15726, 'Hosea', 28, 13, 10, ' فأين هو ملكك حتى يخلصك في جميع مدنك ؟ وقضاتك حيث قلت : أعطني ملكا ورؤساء '),
(15727, 'Hosea', 28, 13, 11, ' أنا أعطيتك ملكا بغضبي وأخذته بسخطي '),
(15728, 'Hosea', 28, 13, 12, ' إثم أفرايم مصرور . خطيته مكنوزة '),
(15729, 'Hosea', 28, 13, 13, ' مخاض الوالدة يأتي عليه . هو ابن غير حكيم ، إذ لم يقف في الوقت في مولد البنين '),
(15730, 'Hosea', 28, 13, 14, ' من يد الهاوية أفديهم . من الموت أخلصهم . أين أوباؤك يا موت ؟ أين شوكتك يا هاوية ؟ تختفي الندامة عن عيني '),
(15731, 'Hosea', 28, 13, 15, ' وإن كان مثمرا بين إخوة ، تأتي ريح شرقية ، ريح الرب طالعة من القفر فتجف عينه وييبس ينبوعه . هي تنهب كنز كل متاع شهي '),
(15732, 'Hosea', 28, 13, 16, ' تجازى السامرة لأنها قد تمردت على إلهها . بالسيف يسقطون . تحطم أطفالهم ، والحوامل تشق '),
(15733, 'Hosea', 28, 14, 1, ' ارجع يا إسرائيل إلى الرب إلهك ، لأنك قد تعثرت بإثمك '),
(15734, 'Hosea', 28, 14, 2, ' خذوا معكم كلاما وارجعوا إلى الرب . قولوا له : ارفع كل إثم واقبل حسنا ، فنقدم عجول شفاهنا '),
(15735, 'Hosea', 28, 14, 3, ' لا يخلصنا أشور . لا نركب على الخيل ، ولا نقول أيضا لعمل أيدينا : آلهتنا . إنه بك يرحم اليتيم '),
(15736, 'Hosea', 28, 14, 4, ' أنا أشفي ارتدادهم . أحبهم فضلا ، لأن غضبي قد ارتد عنه '),
(15737, 'Hosea', 28, 14, 5, ' أكون لإسرائيل كالندى . يزهر كالسوسن ، ويضرب أصوله كلبنان '),
(15738, 'Hosea', 28, 14, 6, ' تمتد خراعيبه ، ويكون بهاؤه كالزيتونة ، وله رائحة كلبنان '),
(15739, 'Hosea', 28, 14, 7, ' يعود الساكنون في ظله يحيون حنطة ويزهرون كجفنة . يكون ذكرهم كخمر لبنان '),
(15740, 'Hosea', 28, 14, 8, ' يقول أفرايم : ما لي أيضا وللأصنام ؟ أنا قد أجبت فألاحظه . أنا كسروة خضراء . من قبلي يوجد ثمرك '),
(15741, 'Hosea', 28, 14, 9, ' من هو حكيم حتى يفهم هذه الأمور ، وفهيم حتى يعرفها فإن طرق الرب مستقيمة ، والأبرار يسلكون فيها ، وأما المنافقون فيعثرون فيها '),
(15742, 'Hosea', 28, 1, 1, ' قول الرب الذي صار إلى هوشع بن بئيري ، في أيام عزيا ويوثام وآحاز وحزقيا ملوك يهوذا ، وفي أيام يربعام بن يوآش ملك إسرائيل '),
(15743, 'Hosea', 28, 1, 2, ' أول ما كلم الرب هوشع ، قال الرب لهوشع : اذهب خذ لنفسك امرأة زنى وأولاد زنى ، لأن الأرض قد زنت زنى تاركة الرب '),
(15744, 'Hosea', 28, 1, 3, ' فذهب وأخذ جومر بنت دبلايم ، فحبلت وولدت له ابنا '),
(15745, 'Hosea', 28, 1, 4, ' فقال له الرب : ادع اسمه يزرعيل ، لأنني بعد قليل أعاقب بيت ياهو على دم يزرعيل ، وأبيد مملكة بيت إسرائيل '),
(15746, 'Hosea', 28, 1, 5, ' ويكون في ذلك اليوم أني أكسر قوس إسرائيل في وادي يزرعيل '),
(15747, 'Hosea', 28, 1, 6, ' ثم حبلت أيضا وولدت بنتا ، فقال له : ادع اسمها لورحامة ، لأني لا أعود أرحم بيت إسرائيل أيضا ، بل أنزعهم نزعا '),
(15748, 'Hosea', 28, 1, 7, ' وأما بيت يهوذا فأرحمهم وأخلصهم بالرب إلههم ، ولا أخلصهم بقوس وبسيف وبحرب وبخيل وبفرسان '),
(15749, 'Hosea', 28, 1, 8, ' ثم فطمت لورحامة وحبلت فولدت ابنا '),
(15750, 'Hosea', 28, 1, 9, ' فقال : ادع اسمه لوعمي ، لأنكم لستم شعبي وأنا لا أكون لكم '),
(15751, 'Hosea', 28, 1, 10, ' لكن يكون عدد بني إسرائيل كرمل البحر الذي لا يكال ولا يعد ، ويكون عوضا عن أن يقال لهم : لستم شعبي ، يقال لهم : أبناء الله الحي '),
(15752, 'Hosea', 28, 1, 11, ' ويجمع بنو يهوذا وبنو إسرائيل معا ويجعلون لأنفسهم رأسا واحدا ، ويصعدون من الأرض ، لأن يوم يزرعيل عظيم '),
(15753, 'Hosea', 28, 2, 1, ' قولوا لإخوتكم عمي ولأخواتكم رحامة '),
(15754, 'Hosea', 28, 2, 2, ' حاكموا أمكم حاكموا ، لأنها ليست امرأتي وأنا لست رجلها ، لكي تعزل زناها عن وجهها وفسقها من بين ثدييها '),
(15755, 'Hosea', 28, 2, 3, ' لئلا أجردها عريانة وأوقفها كيوم ولادتها ، وأجعلها كقفر ، وأصيرها كأرض يابسة ، وأميتها بالعطش '),
(15756, 'Hosea', 28, 2, 4, ' ولا أرحم أولادها لأنهم أولاد زنى '),
(15757, 'Hosea', 28, 2, 5, ' لأن أمهم قد زنت . التي حبلت بهم صنعت خزيا . لأنها قالت : أذهب وراء محبي الذين يعطون خبزي ومائي ، صوفي وكتاني ، زيتي وأشربتي '),
(15758, 'Hosea', 28, 2, 6, ' لذلك هأنذا أسيج طريقك بالشوك ، وأبني حائطها حتى لا تجد مسالكها '),
(15759, 'Hosea', 28, 2, 7, ' فتتبع محبيها ولا تدركهم ، وتفتش عليهم ولا تجدهم . فتقول : أذهب وأرجع إلى رجلي الأول ، لأنه حينئذ كان خير لي من الآن '),
(15760, 'Hosea', 28, 2, 8, ' وهي لم تعرف أني أنا أعطيتها القمح والمسطار والزيت ، وكثرت لها فضة وذهبا جعلوه لبعل '),
(15761, 'Hosea', 28, 2, 9, ' لذلك أرجع وآخذ قمحي في حينه ، ومسطاري في وقته ، وأنزع صوفي وكتاني اللذين لستر عورتها '),
(15762, 'Hosea', 28, 2, 10, ' والآن أكشف عورتها أمام عيون محبيها ولا ينقذها أحد من يدي '),
(15763, 'Hosea', 28, 2, 11, ' وأبطل كل أفراحها : أعيادها ورؤوس شهورها وسبوتها وجميع مواسمها '),
(15764, 'Hosea', 28, 2, 12, ' وأخرب كرمها وتينها اللذين قالت : هما أجرتي التي أعطانيها محبي ، وأجعلهما وعرا فيأكلهما حيوان البرية '),
(15765, 'Hosea', 28, 2, 13, ' وأعاقبها على أيام بعليم التي فيها كانت تبخر لهم وتتزين بخزائمها وحليها وتذهب وراء محبيها وتنساني أنا ، يقول الرب '),
(15766, 'Hosea', 28, 2, 14, ' لكن هأنذا أتملقها وأذهب بها إلى البرية وألاطفها '),
(15767, 'Hosea', 28, 2, 15, ' وأعطيها كرومها من هناك ، ووادي عخور بابا للرجاء . وهي تغني هناك كأيام صباها ، وكيوم صعودها من أرض مصر '),
(15768, 'Hosea', 28, 2, 16, ' ويكون في ذلك اليوم ، يقول الرب ، أنك تدعينني : رجلي ، ولا تدعينني بعد بعلي '),
(15769, 'Hosea', 28, 2, 17, ' وأنزع أسماء البعليم من فمها ، فلا تذكر أيضا بأسمائها '),
(15770, 'Hosea', 28, 2, 18, ' وأقطع لهم عهدا في ذلك اليوم مع حيوان البرية وطيور السماء ودبابات الأرض ، وأكسر القوس والسيف والحرب من الأرض ، وأجعلهم يضطجعون آمنين '),
(15771, 'Hosea', 28, 2, 19, ' وأخطبك لنفسي إلى الأبد . وأخطبك لنفسي بالعدل والحق والإحسان والمراحم '),
(15772, 'Hosea', 28, 2, 20, ' أخطبك لنفسي بالأمانة فتعرفين الرب '),
(15773, 'Hosea', 28, 2, 21, ' ويكون في ذلك اليوم أني أستجيب ، يقول الرب ، أستجيب السماوات وهي تستجيب الأرض '),
(15774, 'Hosea', 28, 2, 22, ' والأرض تستجيب القمح والمسطار والزيت ، وهي تستجيب يزرعيل '),
(15775, 'Hosea', 28, 2, 23, ' وأزرعها لنفسي في الأرض ، وأرحم لورحامة ، وأقول للوعمي : أنت شعبي ، وهو يقول : أنت إلهي '),
(15776, 'Hosea', 28, 3, 1, ' وقال الرب لي : اذهب أيضا أحبب امرأة حبيبة صاحب وزانية ، كمحبة الرب لبني إسرائيل وهم ملتفتون إلى آلهة أخرى ومحبون لأقراص الزبيب '),
(15777, 'Hosea', 28, 3, 2, ' فاشتريتها لنفسي بخمسة عشر شاقل فضة وبحومر ولثك شعير '),
(15778, 'Hosea', 28, 3, 3, ' وقلت لها : تقعدين أياما كثيرة لا تزني ولا تكوني لرجل ، وأنا كذلك لك '),
(15779, 'Hosea', 28, 3, 4, ' لأن بني إسرائيل سيقعدون أياما كثيرة بلا ملك ، وبلا رئيس ، وبلا ذبيحة ، وبلا تمثال ، وبلا أفود وترافيم '),
(15780, 'Hosea', 28, 3, 5, ' بعد ذلك يعود بنو إسرائيل ويطلبون الرب إلههم وداود ملكهم ، ويفزعون إلى الرب وإلى جوده في آخر الأيام '),
(15781, 'Hosea', 28, 4, 1, ' اسمعوا قول الرب يا بني إسرائيل : إن للرب محاكمة مع سكان الأرض ، لأنه لا أمانة ولا إحسان ولا معرفة الله في الأرض '),
(15782, 'Hosea', 28, 4, 2, ' لعن وكذب وقتل وسرقة وفسق . يعتنفون ، ودماء تلحق دماء '),
(15783, 'Hosea', 28, 4, 3, ' لذلك تنوح الأرض ويذبل كل من يسكن فيها مع حيوان البرية وطيور السماء ، وأسماك البحر أيضا تنتزع '),
(15784, 'Hosea', 28, 4, 4, ' ولكن لا يحاكم أحد ولا يعاتب أحد . وشعبك كمن يخاصم كاهنا '),
(15785, 'Hosea', 28, 4, 5, ' فتتعثر في النهار ويتعثر أيضا النبي معك في الليل ، وأنا أخرب أمك '),
(15786, 'Hosea', 28, 4, 6, ' قد هلك شعبي من عدم المعرفة . لأنك أنت رفضت المعرفة أرفضك أنا حتى لا تكهن لي . ولأنك نسيت شريعة إلهك أنسى أنا أيضا بنيك '),
(15787, 'Hosea', 28, 4, 7, ' على حسبما كثروا ، هكذا أخطأوا إلي ، فأبدل كرامتهم بهوان '),
(15788, 'Hosea', 28, 4, 8, ' يأكلون خطية شعبي وإلى إثمهم يحملون نفوسهم '),
(15789, 'Hosea', 28, 4, 9, ' فيكون كما الشعب هكذا الكاهن . وأعاقبهم على طرقهم وأرد أعمالهم عليهم '),
(15790, 'Hosea', 28, 4, 10, ' فيأكلون ولا يشبعون ، ويزنون ولا يكثرون ، لأنهم قد تركوا عبادة الرب '),
(15791, 'Hosea', 28, 4, 11, ' الزنى والخمر والسلافة تخلب القلب '),
(15792, 'Hosea', 28, 4, 12, ' شعبي يسأل خشبه ، وعصاه تخبره ، لأن روح الزنى قد أضلهم فزنوا من تحت إلههم '),
(15793, 'Hosea', 28, 4, 13, ' يذبحون على رؤوس الجبال ، ويبخرون على التلال تحت البلوط واللبنى والبطم لأن ظلها حسن لذلك تزني بناتكم وتفسق كناتكم '),
(15794, 'Hosea', 28, 4, 14, ' لا أعاقب بناتكم لأنهن يزنين ، ولا كناتكم لأنهن يفسقن . لأنهم يعتزلون مع الزانيات ويذبحون مع الناذرات الزنى . وشعب لا يعقل يصرع '),
(15795, 'Hosea', 28, 4, 15, ' إن كنت أنت زانيا يا إسرائيل فلا يأثم يهوذا . ولا تأتوا إلى الجلجال ولا تصعدوا إلى بيت آون ولا تحلفوا : حي هو الرب '),
(15796, 'Hosea', 28, 4, 16, ' إنه قد جمح إسرائيل كبقرة جامحة . الآن يرعاهم الرب كخروف في مكان واسع '),
(15797, 'Hosea', 28, 4, 17, ' أفرايم موثق بالأصنام . اتركوه '),
(15798, 'Hosea', 28, 4, 18, ' متى انتهت منادمتهم زنوا زنى . أحب مجانها ، أحبوا الهوان '),
(15799, 'Hosea', 28, 4, 19, ' قد صرتها الريح في أجنحتها ، وخجلوا من ذبائحهم '),
(15800, 'Hosea', 28, 5, 1, ' اسمعوا هذا أيها الكهنة وانصتوا يا بيت إسرائيل وأصغوا يا بيت الملك لأن عليكم القضاء ، إذ صرتم فخا في مصفاة ، وشبكة مبسوطة على تابور '),
(15801, 'Hosea', 28, 5, 2, ' وقد توغلوا في ذبائح الزيغان ، فأنا تأديب لجميعهم '),
(15802, 'Hosea', 28, 5, 3, ' أنا أعرف أفرايم . وإسرائيل ليس مخفيا عني . إنك الآن زنيت يا أفرايم . قد تنجس إسرائيل '),
(15803, 'Hosea', 28, 5, 4, ' أفعالهم لا تدعهم يرجعون إلى إلههم ، لأن روح الزنى في باطنهم ، وهم لا يعرفون الرب '),
(15804, 'Hosea', 28, 5, 5, ' وقد أذلت عظمة إسرائيل في وجهه ، فيتعثر إسرائيل وأفرايم في إثمهما ، ويتعثر يهوذا أيضا معهما '),
(15805, 'Hosea', 28, 5, 6, ' يذهبون بغنمهم وبقرهم ليطلبوا الرب ولا يجدونه . قد تنحى عنهم '),
(15806, 'Hosea', 28, 5, 7, ' قد غدروا بالرب . لأنهم ولدوا أولادا أجنبيين ، الآن يأكلهم شهر مع أنصبتهم '),
(15807, 'Hosea', 28, 5, 8, ' اضربوا بالبوق في جبعة ، بالقرن في الرامة . اصرخوا في بيت آون . وراءك يا بنيامين '),
(15808, 'Hosea', 28, 5, 9, ' يصير أفرايم خرابا في يوم التأديب . في أسباط إسرائيل أعلمت اليقين '),
(15809, 'Hosea', 28, 5, 10, ' صارت رؤساء يهوذا كناقلي التخوم . فأسكب عليهم سخطي كالماء '),
(15810, 'Hosea', 28, 5, 11, ' أفرايم مظلوم مسحوق القضاء ، لأنه ارتضى أن يمضي وراء الوصية '),
(15811, 'Hosea', 28, 5, 12, ' فأنا لأفرايم كالعث ، ولبيت يهوذا كالسوس '),
(15812, 'Hosea', 28, 5, 13, ' ورأى أفرايم مرضه ويهوذا جرحه ، فمضى أفرايم إلى أشور ، وأرسل إلى ملك عدو . ولكنه لا يستطيع أن يشفيكم ولا أن يزيل منكم الجرح '),
(15813, 'Hosea', 28, 5, 14, ' لأني لأفرايم كالأسد ، ولبيت يهوذا كشبل الأسد . فإني أنا أفترس وأمضي وآخذ ولا منقذ '),
(15814, 'Hosea', 28, 5, 15, ' أذهب وأرجع إلى مكاني حتى يجازوا ويطلبوا وجهي . في ضيقهم يبكرون إلي '),
(15815, 'Hosea', 28, 6, 1, ' هلم نرجع إلى الرب لأنه هو افترس فيشفينا ، ضرب فيجبرنا '),
(15816, 'Hosea', 28, 6, 2, ' يحيينا بعد يومين . في اليوم الثالث يقيمنا فنحيا أمامه '),
(15817, 'Hosea', 28, 6, 3, ' لنعرف فلنتتبع لنعرف الرب . خروجه يقين كالفجر . يأتي إلينا كالمطر . كمطر متأخر يسقي الأرض '),
(15818, 'Hosea', 28, 6, 4, ' ماذا أصنع بك يا أفرايم ؟ ماذا أصنع بك يا يهوذا ؟ فإن إحسانكم كسحاب الصبح ، وكالندى الماضي باكرا '),
(15819, 'Hosea', 28, 6, 5, ' لذلك أقرضهم بالأنبياء . أقتلهم بأقوال فمي . والقضاء عليك كنور قد خرج '),
(15820, 'Hosea', 28, 6, 6, ' إني أريد رحمة لا ذبيحة ، ومعرفة الله أكثر من محرقات '),
(15821, 'Hosea', 28, 6, 7, ' ولكنهم كآدم تعدوا العهد . هناك غدروا بي '),
(15822, 'Hosea', 28, 6, 8, ' جلعاد قرية فاعلي الإثم مدوسة بالدم '),
(15823, 'Hosea', 28, 6, 9, ' وكما يكمن لصوص لإنسان ، كذلك زمرة الكهنة في الطريق يقتلون نحو شكيم . إنهم قد صنعوا فاحشة '),
(15824, 'Hosea', 28, 6, 10, ' في بيت إسرائيل رأيت أمرا فظيعا . هناك زنى أفرايم . تنجس إسرائيل '),
(15825, 'Hosea', 28, 6, 11, ' وأنت أيضا يا يهوذا قد أعد لك حصاد ، عندما أرد سبي شعبي '),
(15826, 'Hosea', 28, 7, 1, ' حينما كنت أشفي إسرائيل ، أعلن إثم أفرايم وشرور السامرة ، فإنهم قد صنعوا غشا . السارق دخل والغزاة نهبوا في الخارج '),
(15827, 'Hosea', 28, 7, 2, ' ولا يفتكرون في قلوبهم أني قد تذكرت كل شرهم . الآن قد أحاطت بهم أفعالهم . صارت أمام وجهي '),
(15828, 'Hosea', 28, 7, 3, ' بشرهم يفرحون الملك ، وبكذبهم الرؤساء '),
(15829, 'Hosea', 28, 7, 4, ' كلهم فاسقون كتنور محمى من الخباز . يبطل الإيقاد من وقتما يعجن العجين إلى أن يختمر '),
(15830, 'Hosea', 28, 7, 5, ' يوم ملكنا يمرض الرؤساء من سورة الخمر . يبسط يده مع المستهزئين '),
(15831, 'Hosea', 28, 7, 6, ' لأنهم يقربون قلوبهم في مكيدتهم كالتنور . كل الليل ينام خبازهم ، وفي الصباح يكون محمى كنار ملتهبة '),
(15832, 'Hosea', 28, 7, 7, ' كلهم حامون كالتنور وأكلوا قضاتهم . جميع ملوكهم سقطوا . ليس بينهم من يدعو إلي '),
(15833, 'Hosea', 28, 7, 8, ' أفرايم يختلط بالشعوب . أفرايم صار خبز ملة لم يقلب '),
(15834, 'Hosea', 28, 7, 9, ' أكل الغرباء ثروته وهو لا يعرف ، وقد رش عليه الشيب وهو لا يعرف '),
(15835, 'Hosea', 28, 7, 10, ' وقد أذلت عظمة إسرائيل في وجهه ، وهم لا يرجعون إلى الرب إلههم ولا يطلبونه مع كل هذا '),
(15836, 'Hosea', 28, 7, 11, ' وصار أفرايم كحمامة رعناء بلا قلب . يدعون مصر . يمضون إلى أشور '),
(15837, 'Hosea', 28, 7, 12, ' عندما يمضون أبسط عليهم شبكتي . ألقيهم كطيور السماء . أؤدبهم بحسب خبر جماعتهم '),
(15838, 'Hosea', 28, 7, 13, ' ويل لهم لأنهم هربوا عني . تبا لهم لأنهم أذنبوا إلي . أنا أفديهم وهم تكلموا علي بكذب '),
(15839, 'Hosea', 28, 7, 14, ' ولا يصرخون إلي بقلوبهم حينما يولولون على مضاجعهم . يتجمعون لأجل القمح والخمر ، ويرتدون عني '),
(15840, 'Hosea', 28, 7, 15, ' وأنا أنذرتهم وشددت أذرعهم ، وهم يفكرون علي بالشر '),
(15841, 'Hosea', 28, 7, 16, ' يرجعون ليس إلى العلي . قد صاروا كقوس مخطئة . يسقط رؤساؤهم بالسيف من أجل سخط ألسنتهم . هذا هزؤهم في أرض مصر '),
(15842, 'Hosea', 28, 8, 1, ' إلى فمك بالبوق كالنسر على بيت الرب . لأنهم قد تجاوزوا عهدي وتعدوا على شريعتي '),
(15843, 'Hosea', 28, 8, 2, ' إلي يصرخون : يا إلهي ، نعرفك نحن إسرائيل '),
(15844, 'Hosea', 28, 8, 3, ' قد كره إسرائيل الصلاح فيتبعه العدو '),
(15845, 'Hosea', 28, 8, 4, ' هم أقاموا ملوكا وليس مني . أقاموا رؤساء وأنا لم أعرف . صنعوا لأنفسهم من فضتهم وذهبهم أصناما لكي ينقرضوا '),
(15846, 'Hosea', 28, 8, 5, ' قد زنخ عجلك يا سامرة . حمي غضبي عليهم . إلى متى لا يستطيعون النقاوة '),
(15847, 'Hosea', 28, 8, 6, ' إنه هو أيضا من إسرائيل . صنعه الصانع وليس هو إلها . إن عجل السامرة يصير كسرا '),
(15848, 'Hosea', 28, 8, 7, ' إنهم يزرعون الريح ويحصدون الزوبعة . زرع ليس له غلة لا يصنع دقيقا . وإن صنع ، فالغرباء تبتلعه '),
(15849, 'Hosea', 28, 8, 8, ' قد ابتلع إسرائيل . الآن صاروا بين الأمم كإناء لا مسرة فيه '),
(15850, 'Hosea', 28, 8, 9, ' لأنهم صعدوا إلى أشور مثل حمار وحشي معتزل بنفسه . استأجر أفرايم محبين '),
(15851, 'Hosea', 28, 8, 10, ' إني وإن كانوا يستأجرون بين الأمم ، الآن أجمعهم فينفكون قليلا من ثقل ملك الرؤساء '),
(15852, 'Hosea', 28, 8, 11, ' لأن أفرايم كثر مذابح للخطية ، صارت له المذابح للخطية '),
(15853, 'Hosea', 28, 8, 12, ' أكتب له كثرة شرائعي ، فهي تحسب أجنبية '),
(15854, 'Hosea', 28, 8, 13, ' أما ذبائح تقدماتي فيذبحون لحما ويأكلون . الرب لا يرتضيها . الآن يذكر إثمهم ويعاقب خطيتهم . إنهم إلى مصر يرجعون '),
(15855, 'Hosea', 28, 8, 14, ' وقد نسي إسرائيل صانعه وبنى قصورا ، وكثر يهوذا مدنا حصينة . لكني أرسل على مدنه نارا فتأكل قصوره '),
(15856, 'Hosea', 28, 9, 1, ' لا تفرح يا إسرائيل طربا كالشعوب ، لأنك قد زنيت عن إلهك . أحببت الأجرة على جميع بيادر الحنطة '),
(15857, 'Hosea', 28, 9, 2, ' لا يطعمهم البيدر والمعصرة ، ويكذب عليهم المسطار '),
(15858, 'Hosea', 28, 9, 3, ' لا يسكنون في أرض الرب ، بل يرجع أفرايم إلى مصر ، ويأكلون النجس في أشور '),
(15859, 'Hosea', 28, 9, 4, ' لا يسكبون للرب خمرا ولا تسره ذبائحهم . إنها لهم كخبز الحزن . كل من أكله يتنجس . إن خبزهم لنفسهم . لا يدخل بيت الرب '),
(15860, 'Hosea', 28, 9, 5, ' ماذا تصنعون في يوم الموسم ، وفي يوم عيد الرب '),
(15861, 'Hosea', 28, 9, 6, ' إنهم قد ذهبوا من الخراب . تجمعهم مصر . تدفنهم موف . يرث القريص نفائس فضتهم . يكون العوسج في منازلهم '),
(15862, 'Hosea', 28, 9, 7, ' جاءت أيام العقاب . جاءت أيام الجزاء . سيعرف إسرائيل . النبي أحمق . إنسان الروح مجنون من كثرة إثمك وكثرة الحقد '),
(15863, 'Hosea', 28, 9, 8, ' أفرايم منتظر عند إلهي . النبي فخ صياد على جميع طرقه . حقد في بيت إلهه '),
(15864, 'Hosea', 28, 9, 9, ' قد توغلوا ، فسدوا كأيام جبعة . سيذكر إثمهم . سيعاقب خطاياهم '),
(15865, 'Hosea', 28, 9, 10, ' وجدت إسرائيل كعنب في البرية . رأيت آباءكم كباكورة على تينة في أولها . أما هم فجاءوا إلى بعل فغور ، ونذروا أنفسهم للخزي ، وصاروا رجسا كما أحبوا '),
(15866, 'Hosea', 28, 9, 11, ' أفرايم تطير كرامتهم كطائر من الولادة ومن البطن ومن الحبل '),
(15867, 'Hosea', 28, 9, 12, ' وإن ربوا أولادهم أثكلهم إياهم حتى لا يكون إنسان . ويل لهم أيضا متى انصرفت عنهم '),
(15868, 'Hosea', 28, 9, 13, ' أفرايم كما أرى كصور مغروس في مرعى ، ولكن أفرايم سيخرج بنيه إلى القاتل '),
(15869, 'Hosea', 28, 9, 14, ' أعطهم يارب . ماذا تعطي ؟ أعطهم رحما مسقطا وثديين يبسين '),
(15870, 'Hosea', 28, 9, 15, ' كل شرهم في الجلجال . إني هناك أبغضتهم . من أجل سوء أفعالهم أطردهم من بيتي . لا أعود أحبهم . جميع رؤسائهم متمردون '),
(15871, 'Hosea', 28, 9, 16, ' أفرايم مضروب . أصلهم قد جف . لا يصنعون ثمرا . وإن ولدوا أميت مشتهيات بطونهم '),
(15872, 'Hosea', 28, 9, 17, ' يرفضهم إلهي لأنهم لم يسمعوا له ، فيكونون تائهين بين الأمم '),
(15873, 'Isaiah', 23, 1, 6, ' من أسفل القدم إلى الرأس ليس فيه صحة ، بل جرح وأحباط وضربة طرية لم تعصر ولم تعصب ولم تلين بالزيت '),
(15874, 'Isaiah', 23, 1, 7, ' بلادكم خربة . مدنكم محرقة بالنار . أرضكم تأكلها غرباء قدامكم ، وهي خربة كانقلاب الغرباء '),
(15875, 'Isaiah', 23, 1, 8, ' فبقيت ابنة صهيون كمظلة في كرم ، كخيمة في مقثأة ، كمدينة محاصرة '),
(15876, 'Isaiah', 23, 1, 9, ' لولا أن رب الجنود أبقى لنا بقية صغيرة ، لصرنا مثل سدوم وشابهنا عمورة '),
(15877, 'Isaiah', 23, 1, 10, ' اسمعوا كلام الرب يا قضاة سدوم أصغوا إلى شريعة إلهنا يا شعب عمورة '),
(15878, 'Isaiah', 23, 1, 11, ' لماذا لي كثرة ذبائحكم ، يقول الرب . اتخمت من محرقات كباش وشحم مسمنات ، وبدم عجول وخرفان وتيوس ما أسر '),
(15879, 'Isaiah', 23, 1, 12, ' حينما تأتون لتظهروا أمامي ، من طلب هذا من أيديكم أن تدوسوا دوري '),
(15880, 'Isaiah', 23, 1, 13, ' لا تعودوا تأتون بتقدمة باطلة . البخور هو مكرهة لي . رأس الشهر والسبت ونداء المحفل . لست أطيق الإثم والاعتكاف '),
(15881, 'Isaiah', 23, 1, 14, ' رؤوس شهوركم وأعيادكم بغضتها نفسي . صارت علي ثقلا . مللت حملها '),
(15882, 'Isaiah', 23, 1, 15, ' فحين تبسطون أيديكم أستر عيني عنكم ، وإن كثرتم الصلاة لا أسمع . أيديكم ملآنة دما '),
(15883, 'Isaiah', 23, 1, 16, ' اغتسلوا . تنقوا . اعزلوا شر أفعالكم من أمام عيني . كفوا عن فعل الشر '),
(15884, 'Isaiah', 23, 1, 17, ' تعلموا فعل الخير . اطلبوا الحق . انصفوا المظلوم . اقضوا لليتيم . حاموا عن الأرملة '),
(15885, 'Isaiah', 23, 1, 18, ' هلم نتحاجج ، يقول الرب . إن كانت خطاياكم كالقرمز تبيض كالثلج . إن كانت حمراء كالدودي تصير كالصوف '),
(15886, 'Isaiah', 23, 1, 19, ' إن شئتم وسمعتم تأكلون خير الأرض '),
(15887, 'Isaiah', 23, 1, 20, ' وإن أبيتم وتمردتم تؤكلون بالسيف . لأن فم الرب تكلم '),
(15888, 'Isaiah', 23, 1, 21, ' كيف صارت القرية الأمينة زانية ملآنة حقا . كان العدل يبيت فيها ، وأما الآن فالقاتلون '),
(15889, 'Isaiah', 23, 1, 22, ' صارت فضتك زغلا وخمرك مغشوشة بماء '),
(15890, 'Isaiah', 23, 1, 23, ' رؤساؤك متمردون ولغفاء اللصوص . كل واحد منهم يحب الرشوة ويتبع العطايا . لا يقضون لليتيم ، ودعوى الأرملة لا تصل إليهم '),
(15891, 'Isaiah', 23, 1, 24, ' لذلك يقول السيد رب الجنود عزيز إسرائيل : آه إني أستريح من خصمائي وأنتقم من أعدائي '),
(15892, 'Isaiah', 23, 1, 25, ' وأرد يدي عليك ، وأنقي زغلك كأنه بالبورق ، وأنزع كل قصديرك '),
(15893, 'Isaiah', 23, 1, 26, ' وأعيد قضاتك كما في الأول ، ومشيريك كما في البداءة . بعد ذلك تدعين مدينة العدل ، القرية الأمينة '),
(15894, 'Isaiah', 23, 1, 27, ' صهيون تفدى بالحق ، وتائبوها بالبر '),
(15895, 'Isaiah', 23, 1, 28, ' وهلاك المذنبين والخطاة يكون سواء ، وتاركو الرب يفنون '),
(15896, 'Isaiah', 23, 1, 29, ' لأنهم يخجلون من أشجار البطم التي اشتهيتموها ، وتخزون من الجنات التي اخترتموها '),
(15897, 'Isaiah', 23, 1, 30, ' لأنكم تصيرون كبطمة قد ذبل ورقها ، وكجنة ليس لها ماء '),
(15898, 'Isaiah', 23, 1, 31, ' ويصير القوي مشاقة وعمله شرارا ، فيحترقان كلاهما معا وليس من يطفئ '),
(15899, 'Isaiah', 23, 2, 1, ' الأمور التي رآها إشعياء بن آموص من جهة يهوذا وأورشليم '),
(15900, 'Isaiah', 23, 2, 2, ' ويكون في آخر الأيام أن جبل بيت الرب يكون ثابتا في رأس الجبال ، ويرتفع فوق التلال ، وتجري إليه كل الأمم '),
(15901, 'Isaiah', 23, 2, 3, ' وتسير شعوب كثيرة ، ويقولون : هلم نصعد إلى جبل الرب ، إلى بيت إله يعقوب ، فيعلمنا من طرقه ونسلك في سبله . لأنه من صهيون تخرج الشريعة ، ومن أورشليم كلمة الرب '),
(15902, 'Isaiah', 23, 2, 4, ' فيقضي بين الأمم وينصف لشعوب كثيرين ، فيطبعون سيوفهم سككا ورماحهم مناجل . لا ترفع أمة على أمة سيفا ، ولا يتعلمون الحرب في ما بعد '),
(15903, 'Isaiah', 23, 2, 5, ' يا بيت يعقوب ، هلم فنسلك في نور الرب '),
(15904, 'Isaiah', 23, 2, 6, ' فإنك رفضت شعبك بيت يعقوب لأنهم امتلأوا من المشرق ، وهم عائفون كالفلسطينيين ، ويصافحون أولاد الأجانب '),
(15905, 'Isaiah', 23, 2, 7, ' وامتلأت أرضهم فضة وذهبا ولا نهاية لكنوزهم ، وامتلأت أرضهم خيلا ولا نهاية لمركباتهم '),
(15906, 'Isaiah', 23, 2, 8, ' وامتلأت أرضهم أوثانا . يسجدون لعمل أيديهم لما صنعته أصابعهم '),
(15907, 'Isaiah', 23, 2, 9, ' وينخفض الإنسان ، وينطرح الرجل ، فلا تغفر لهم '),
(15908, 'Isaiah', 23, 2, 10, ' ادخل إلى الصخرة واختبئ في التراب من أمام هيبة الرب ومن بهاء عظمته '),
(15909, 'Isaiah', 23, 2, 11, ' توضع عينا تشامخ الإنسان ، وتخفض رفعة الناس ، ويسمو الرب وحده في ذلك اليوم '),
(15910, 'Isaiah', 23, 2, 12, ' فإن لرب الجنود يوما على كل متعظم وعال ، وعلى كل مرتفع فيوضع '),
(15911, 'Isaiah', 23, 2, 13, ' وعلى كل أرز لبنان العالي المرتفع ، وعلى كل بلوط باشان '),
(15912, 'Isaiah', 23, 2, 14, ' وعلى كل الجبال العالية ، وعلى كل التلال المرتفعة '),
(15913, 'Isaiah', 23, 2, 15, ' وعلى كل برج عال ، وعلى كل سور منيع '),
(15914, 'Isaiah', 23, 2, 16, ' وعلى كل سفن ترشيش ، وعلى كل الأعلام البهجة '),
(15915, 'Isaiah', 23, 2, 17, ' فيخفض تشامخ الإنسان ، وتوضع رفعة الناس ، ويسمو الرب وحده في ذلك اليوم '),
(15916, 'Isaiah', 23, 2, 18, ' وتزول الأوثان بتمامها '),
(15917, 'Isaiah', 23, 2, 19, ' ويدخلون في مغاير الصخور ، وفي حفائر التراب من أمام هيبة الرب ، ومن بهاء عظمته ، عند قيامه ليرعب الأرض '),
(15918, 'Isaiah', 23, 2, 20, ' في ذلك اليوم يطرح الإنسان أوثانه الفضية وأوثانه الذهبية ، التي عملوها له للسجود ، للجرذان والخفافيش '),
(15919, 'Isaiah', 23, 2, 21, ' ليدخل في نقر الصخور وفي شقوق المعاقل ، من أمام هيبة الرب ومن بهاء عظمته عند قيامه ليرعب الأرض '),
(15920, 'Isaiah', 23, 2, 22, ' كفوا عن الإنسان الذي في أنفه نسمة ، لأنه ماذا يحسب '),
(15921, 'Isaiah', 23, 3, 1, ' فإنه هوذا السيد رب الجنود ينزع من أورشليم ومن يهوذا السند والركن ، كل سند خبز ، وكل سند ماء '),
(15922, 'Isaiah', 23, 3, 2, ' الجبار ورجل الحرب . القاضي والنبي والعراف والشيخ '),
(15923, 'Isaiah', 23, 3, 3, ' رئيس الخمسين والمعتبر والمشير ، والماهر بين الصناع ، والحاذق بالرقية '),
(15924, 'Isaiah', 23, 3, 4, ' وأجعل صبيانا رؤساء لهم ، وأطفالا تتسلط عليهم '),
(15925, 'Isaiah', 23, 3, 5, ' ويظلم الشعب بعضهم بعضا ، والرجل صاحبه . يتمرد الصبي على الشيخ ، والدنيء على الشريف '),
(15926, 'Isaiah', 23, 3, 6, ' إذا أمسك إنسان بأخيه في بيت أبيه قائلا : لك ثوب فتكون لنا رئيسا ، وهذا الخراب تحت يدك '),
(15927, 'Isaiah', 23, 3, 7, ' يرفع صوته في ذلك اليوم قائلا : لا أكون عاصبا وفي بيتي لا خبز ولا ثوب . لا تجعلوني رئيس الشعب '),
(15928, 'Isaiah', 23, 3, 8, ' لأن أورشليم عثرت ، ويهوذا سقطت ، لأن لسانهما وأفعالهما ضد الرب لإغاظة عيني مجده '),
(15929, 'Isaiah', 23, 3, 9, ' نظر وجوههم يشهد عليهم ، وهم يخبرون بخطيتهم كسدوم . لا يخفونها . ويل لنفوسهم لأنهم يصنعون لأنفسهم شرا '),
(15930, 'Isaiah', 23, 3, 10, ' قولوا للصديق خير لأنهم يأكلون ثمر أفعالهم '),
(15931, 'Isaiah', 23, 3, 11, ' ويل للشرير . شر لأن مجازاة يديه تعمل به '),
(15932, 'Isaiah', 23, 3, 12, ' شعبي ظالموه أولاد ، ونساء يتسلطن عليه . يا شعبي ، مرشدوك مضلون ، ويبلعون طريق مسالكك '),
(15933, 'Isaiah', 23, 25, 3, ' لذلك يكرمك شعب قوي ، وتخاف منك قرية أمم عتاة '),
(15934, 'Isaiah', 23, 25, 4, ' لأنك كنت حصنا للمسكين ، حصنا للبائس في ضيقه ، ملجأ من السيل ، ظلا من الحر ، إذ كانت نفخة العتاة كسيل على حائط '),
(15935, 'Isaiah', 23, 25, 5, ' كحر في يبس تخفض ضجيج الأعاجم . كحر بظل غيم يذل غناء العتاة '),
(15936, 'Isaiah', 23, 25, 6, ' ويصنع رب الجنود لجميع الشعوب في هذا الجبل وليمة سمائن ، وليمة خمر على دردي ، سمائن ممخة ، دردي مصفى '),
(15937, 'Isaiah', 23, 25, 7, ' ويفني في هذا الجبل وجه النقاب . النقاب الذي على كل الشعوب ، والغطاء المغطى به على كل الأمم '),
(15938, 'Isaiah', 23, 25, 8, ' يبلع الموت إلى الأبد ، ويمسح السيد الرب الدموع عن كل الوجوه ، وينزع عار شعبه عن كل الأرض ، لأن الرب قد تكلم '),
(15939, 'Isaiah', 23, 25, 9, ' ويقال في ذلك اليوم : هوذا هذا إلهنا . انتظرناه فخلصنا . هذا هو الرب انتظرناه . نبتهج ونفرح بخلاصه '),
(15940, 'Isaiah', 23, 25, 10, ' لأن يد الرب تستقر على هذا الجبل ، ويداس موآب في مكانه كما يداس التبن في ماء المزبلة '),
(15941, 'Isaiah', 23, 25, 11, ' فيبسط يديه فيه كما يبسط السابح ليسبح ، فيضع كبرياءه مع مكايد يديه '),
(15942, 'Isaiah', 23, 25, 12, ' وصرح ارتفاع أسوارك يخفضه ، يضعه ، يلصقه بالأرض إلى التراب '),
(15943, 'Isaiah', 23, 26, 1, ' في ذلك اليوم يغنى بهذه الأغنية في أرض يهوذا : لنا مدينة قوية . يجعل الخلاص أسوارا ومترسة '),
(15944, 'Isaiah', 23, 26, 2, ' افتحوا الأبواب لتدخل الأمة البارة الحافظة الأمانة '),
(15945, 'Isaiah', 23, 26, 3, ' ذو الرأي الممكن تحفظه سالما سالما ، لأنه عليك متوكل '),
(15946, 'Isaiah', 23, 26, 4, ' توكلوا على الرب إلى الأبد ، لأن في ياه الرب صخر الدهور '),
(15947, 'Isaiah', 23, 26, 5, ' لأنه يخفض سكان العلاء ، يضع القرية المرتفعة . يضعها إلى الأرض . يلصقها بالتراب '),
(15948, 'Isaiah', 23, 26, 6, ' تدوسها الرجل ، رجلا البائس ، أقدام المساكين '),
(15949, 'Isaiah', 23, 26, 7, ' طريق الصديق استقامة . تمهد أيها المستقيم سبيل الصديق '),
(15950, 'Isaiah', 23, 26, 8, ' ففي طريق أحكامك يارب انتظرناك . إلى اسمك وإلى ذكرك شهوة النفس '),
(15951, 'Isaiah', 23, 26, 9, ' بنفسي اشتهيتك في الليل . أيضا بروحي في داخلي إليك أبتكر . لأنه حينما تكون أحكامك في الأرض يتعلم سكان المسكونة العدل '),
(15952, 'Isaiah', 23, 26, 10, ' يرحم المنافق ولا يتعلم العدل . في أرض الاستقامة يصنع شرا ولا يرى جلال الرب '),
(15953, 'Isaiah', 23, 26, 11, ' يارب ، ارتفعت يدك ولا يرون . يرون ويخزون من الغيرة على الشعب وتأكلهم نار أعدائك '),
(15954, 'Isaiah', 23, 26, 12, ' يارب ، تجعل لنا سلاما لأنك كل أعمالنا صنعتها لنا '),
(15955, 'Isaiah', 23, 26, 13, ' أيها الرب إلهنا ، قد استولى علينا سادة سواك . بك وحدك نذكر اسمك '),
(15956, 'Isaiah', 23, 26, 14, ' هم أموات لا يحيون . أخيلة لا تقوم . لذلك عاقبت وأهلكتهم وأبدت كل ذكرهم '),
(15957, 'Isaiah', 23, 26, 15, ' زدت الأمة يارب ، زدت الأمة . تمجدت . وسعت كل أطراف الأرض '),
(15958, 'Isaiah', 23, 26, 16, ' يارب في الضيق طلبوك . سكبوا مخافتة عند تأديبك إياهم '),
(15959, 'Isaiah', 23, 26, 17, ' كما أن الحبلى التي تقارب الولادة تتلوى وتصرخ في مخاضها ، هكذا كنا قدامك يارب '),
(15960, 'Isaiah', 23, 26, 18, ' حبلنا تلوينا كأننا ولدنا ريحا . لم نصنع خلاصا في الأرض ، ولم يسقط سكان المسكونة '),
(15961, 'Isaiah', 23, 26, 19, ' تحيا أمواتك ، تقوم الجثث . استيقظوا ، ترنموا يا سكان التراب . لأن طلك طل أعشاب ، والأرض تسقط الأخيلة '),
(15962, 'Isaiah', 23, 26, 20, ' هلم يا شعبي ادخل مخادعك ، وأغلق أبوابك خلفك . اختبئ نحو لحيظة حتى يعبر الغضب '),
(15963, 'Isaiah', 23, 26, 21, ' لأنه هوذا الرب يخرج من مكانه ليعاقب إثم سكان الأرض فيهم ، فتكشف الأرض دماءها ولا تغطي قتلاها في ما بعد '),
(15964, 'Isaiah', 23, 27, 1, ' في ذلك اليوم يعاقب الرب بسيفه القاسي العظيم الشديد لوياثان ، الحية الهاربة . لوياثان الحية المتحوية ، ويقتل التنين الذي في البحر '),
(15965, 'Isaiah', 23, 27, 2, ' في ذلك اليوم غنوا للكرمة المشتهاة '),
(15966, 'Isaiah', 23, 27, 3, ' أنا الرب حارسها . أسقيها كل لحظة . لئلا يوقع بها أحرسها ليلا ونهارا '),
(15967, 'Isaiah', 23, 27, 4, ' ليس لي غيظ . ليت علي الشوك والحسك في القتال فأهجم عليها وأحرقها معا '),
(15968, 'Isaiah', 23, 27, 5, ' أو يتمسك بحصني فيصنع صلحا معي . صلحا يصنع معي '),
(15969, 'Isaiah', 23, 27, 6, ' في المستقبل يتأصل يعقوب . يزهر ويفرع إسرائيل ، ويملأون وجه المسكونة ثمارا '),
(15970, 'Isaiah', 23, 27, 7, ' هل ضربه كضربة ضاربيه ، أو قتل كقتل قتلاه '),
(15971, 'Isaiah', 23, 27, 8, ' بزجر إذ طلقتها خاصمتها . أزالها بريحه العاصفة في يوم الشرقية '),
(15972, 'Isaiah', 23, 27, 9, ' لذلك بهذا يكفر إثم يعقوب . وهذا كل الثمر نزع خطيته : في جعله كل حجارة المذبح كحجارة كلس مكسرة . لا تقوم السواري ولا الشمسات '),
(15973, 'Isaiah', 23, 27, 10, ' لأن المدينة الحصينة متوحدة . المسكن مهجور ومتروك كالقفر . هناك يرعى العجل ، وهناك يربض ويتلف أغصانها '),
(15974, 'Isaiah', 23, 27, 11, ' حينما تيبس أغصانها تتكسر ، فتأتي نساء وتوقدها . لأنه ليس شعبا ذا فهم ، لذلك لا يرحمه صانعه ولا يترأف عليه جابله '),
(15975, 'Isaiah', 23, 27, 12, ' ويكون في ذلك اليوم أن الرب يجني من مجرى النهر إلى وادي مصر ، وأنتم تلقطون واحدا واحدا يا بني إسرائيل '),
(15976, 'Isaiah', 23, 27, 13, ' ويكون في ذلك اليوم أنه يضرب ببوق عظيم ، فيأتي التائهون في أرض أشور ، والمنفيون في أرض مصر ، ويسجدون للرب في الجبل المقدس في أورشليم '),
(15977, 'Isaiah', 23, 28, 1, ' ويل لإكليل فخر سكارى أفرايم ، وللزهر الذابل ، جمال بهائه الذي على رأس وادي سمائن ، المضروبين بالخمر '),
(15978, 'Isaiah', 23, 28, 2, ' هوذا شديد وقوي للسيد كانهيال البرد ، كنوء مهلك ، كسيل مياه غزيرة جارفة ، قد ألقاه إلى الأرض بشدة '),
(15979, 'Isaiah', 23, 28, 3, ' بالأرجل يداس إكليل فخر سكارى أفرايم '),
(15980, 'Isaiah', 23, 28, 4, ' ويكون الزهر الذابل ، جمال بهائه الذي على رأس وادي السمائن كباكورة التين قبل الصيف ، التي يراها الناظر فيبلعها وهي في يده '),
(15981, 'Isaiah', 23, 28, 5, ' في ذلك اليوم يكون رب الجنود إكليل جمال وتاج بهاء لبقية شعبه '),
(15982, 'Isaiah', 23, 28, 6, ' وروح القضاء للجالس للقضاء ، وبأسا للذين يردون الحرب إلى الباب '),
(15983, 'Isaiah', 23, 28, 7, ' ولكن هؤلاء أيضا ضلوا بالخمر وتاهوا بالمسكر . الكاهن والنبي ترنحا بالمسكر . ابتلعتهما الخمر . تاها من المسكر ، ضلا في الرؤيا ، قلقا في القضاء '),
(15984, 'Isaiah', 23, 28, 8, ' فإن جميع الموائد امتلأت قيئا وقذرا . ليس مكان '),
(15985, 'Isaiah', 23, 28, 9, ' لمن يعلم معرفة ، ولمن يفهم تعليما ؟ أللمفطومين عن اللبن ، للمفصولين عن الثدي '),
(15986, 'Isaiah', 23, 28, 10, ' لأنه أمر على أمر . أمر على أمر . فرض على فرض . فرض على فرض . هنا قليل هناك قليل '),
(15987, 'Isaiah', 23, 28, 11, ' إنه بشفة لكناء وبلسان آخر يكلم هذا الشعب '),
(15988, 'Isaiah', 23, 28, 12, ' الذين قال لهم : هذه هي الراحة . أريحوا الرازح ، وهذا هو السكون . ولكن لم يشاءوا أن يسمعوا '),
(15989, 'Isaiah', 23, 28, 13, ' فكان لهم قول الرب : أمرا على أمر . أمرا على أمر . فرضا على فرض . فرضا على فرض . هنا قليلا هناك قليلا ، لكي يذهبوا ويسقطوا إلى الوراء وينكسروا ويصادوا فيؤخذوا '),
(15990, 'Isaiah', 23, 28, 14, ' لذلك اسمعوا كلام الرب يا رجال الهزء ، ولاة هذا الشعب الذي في أورشليم '),
(15991, 'Isaiah', 23, 28, 15, ' لأنكم قلتم : قد عقدنا عهدا مع الموت ، وصنعنا ميثاقا مع الهاوية . السوط الجارف إذا عبر لا يأتينا ، لأننا جعلنا الكذب ملجأنا ، وبالغش استترنا '),
(15992, 'Isaiah', 23, 28, 16, ' لذلك هكذا يقول السيد الرب : هأنذا أؤسس في صهيون حجرا ، حجر امتحان ، حجر زاوية كريما ، أساسا مؤسسا : من آمن لا يهرب '),
(15993, 'Isaiah', 23, 28, 17, ' وأجعل الحق خيطا والعدل مطمارا ، فيخطف البرد ملجأ الكذب ، ويجرف الماء الستارة '),
(15994, 'Isaiah', 23, 28, 18, ' ويمحى عهدكم مع الموت ، ولا يثبت ميثاقكم مع الهاوية . السوط الجارف إذا عبر تكونون له للدوس '),
(15995, 'Isaiah', 23, 28, 19, ' كلما عبر يأخذكم ، فإنه كل صباح يعبر ، في النهار وفي الليل ، ويكون فهم الخبر فقط انزعاجا '),
(15996, 'Isaiah', 23, 28, 20, ' لأن الفراش قد قصر عن التمدد ، والغطاء ضاق عن الالتحاف '),
(15997, 'Isaiah', 23, 28, 21, ' لأنه كما في جبل فراصيم يقوم الرب ، وكما في الوطاء عند جبعون يسخط ليفعل فعله ، فعله الغريب ، وليعمل عمله ، عمله الغريب '),
(15998, 'Isaiah', 23, 28, 22, ' فالآن لا تكونوا متهكمين لئلا تشدد ربطكم ، لأني سمعت فناء قضي به من قبل السيد رب الجنود على كل الأرض '),
(15999, 'Isaiah', 23, 28, 23, ' اصغوا واسمعوا صوتي . انصتوا واسمعوا قولي '),
(16000, 'Isaiah', 23, 28, 24, ' هل يحرث الحارث كل يوم ليزرع ، ويشق أرضه ويمهدها '),
(16001, 'Isaiah', 23, 28, 25, ' أليس أنه إذا سوى وجهها يبذر الشونيز ويذري الكمون ، ويضع الحنطة في أتلام ، والشعير في مكان معين ، والقطاني في حدودها '),
(16002, 'Isaiah', 23, 28, 26, ' فيرشده . بالحق يعلمه إلهه '),
(16003, 'Isaiah', 23, 28, 27, ' إن الشونيز لا يدرس بالنورج ، ولا تدار بكرة العجلة على الكمون ، بل بالقضيب يخبط الشونيز ، والكمون بالعصا '),
(16004, 'Isaiah', 23, 28, 28, ' يدق القمح لأنه لا يدرسه إلى الأبد ، فيسوق بكرة عجلته وخيله . لا يسحقه '),
(16005, 'Isaiah', 23, 28, 29, ' هذا أيضا خرج من قبل رب الجنود . عجيب الرأي عظيم الفهم '),
(16006, 'Isaiah', 23, 29, 1, ' ويل لأريئيل ، لأريئيل قرية نزل عليها داود . زيدوا سنة على سنة . لتدر الأعياد '),
(16007, 'Isaiah', 23, 29, 2, ' وأنا أضايق أريئيل فيكون نوح وحزن ، وتكون لي كأريئيل '),
(16008, 'Isaiah', 23, 29, 3, ' وأحيط بك كالدائرة ، وأضايق عليك بحصن ، وأقيم عليك متارس '),
(16009, 'Isaiah', 23, 29, 4, ' فتتضعين وتتكلمين من الأرض ، وينخفض قولك من التراب ، ويكون صوتك كخيال من الأرض ، ويشقشق قولك من التراب '),
(16010, 'Isaiah', 23, 29, 5, ' ويصير جمهور أعدائك كالغبار الدقيق ، وجمهور العتاة كالعصافة المارة . ويكون ذلك في لحظة بغتة '),
(16011, 'Isaiah', 23, 29, 6, ' من قبل رب الجنود تفتقد برعد وزلزلة وصوت عظيم ، بزوبعة وعاصف ولهيب نار آكلة '),
(16012, 'Isaiah', 23, 29, 7, ' ويكون كحلم ، كرؤيا الليل جمهور كل الأمم المتجندين على أريئيل ، كل المتجندين عليها وعلى قلاعها والذين يضايقونها '),
(16013, 'Isaiah', 23, 29, 8, ' ويكون كما يحلم الجائع أنه يأكل ، ثم يستيقظ وإذا نفسه فارغة . وكما يحلم العطشان أنه يشرب ، ثم يستيقظ وإذا هو رازح ونفسه مشتهية . هكذا يكون جمهور كل الأمم المتجندين على جبل صهيون '),
(16014, 'Isaiah', 23, 29, 9, ' توانوا وابهتوا . تلذذوا واعموا . قد سكروا وليس من الخمر . ترنحوا وليس من المسكر '),
(16015, 'Isaiah', 23, 29, 10, ' لأن الرب قد سكب عليكم روح سبات وأغمض عيونكم . الأنبياء ورؤساؤكم الناظرون غطاهم '),
(16016, 'Isaiah', 23, 29, 11, ' وصارت لكم رؤيا الكل مثل كلام السفر المختوم الذي يدفعونه لعارف الكتابة قائلين : اقرأ هذا . فيقول : لا أستطيع لأنه مختوم '),
(16017, 'Isaiah', 23, 29, 12, ' أو يدفع الكتاب لمن لا يعرف الكتابة ويقال له : اقرأ هذا . فيقول : لا أعرف الكتابة '),
(16018, 'Isaiah', 23, 29, 13, ' فقال السيد : لأن هذا الشعب قد اقترب إلي بفمه وأكرمني بشفتيه ، وأما قلبه فأبعده عني ، وصارت مخافتهم مني وصية الناس معلمة '),
(16019, 'Isaiah', 23, 29, 14, ' لذلك هأنذا أعود أصنع بهذا الشعب عجبا وعجيبا ، فتبيد حكمة حكمائه ، ويختفي فهم فهمائه '),
(16020, 'Isaiah', 23, 29, 15, ' ويل للذين يتعمقون ليكتموا رأيهم عن الرب ، فتصير أعمالهم في الظلمة ، ويقولون : من يبصرنا ومن يعرفنا '),
(16021, 'Isaiah', 23, 29, 16, ' يالتحريفكم هل يحسب الجابل كالطين ، حتى يقول المصنوع عن صانعه : لم يصنعني . أو تقول الجبلة عن جابلها : لم يفهم '),
(16022, 'Isaiah', 23, 29, 17, ' أليس في مدة يسيرة جدا يتحول لبنان بستانا ، والبستان يحسب وعرا '),
(16023, 'Isaiah', 23, 29, 18, ' ويسمع في ذلك اليوم الصم أقوال السفر ، وتنظر من القتام والظلمة عيون العمي '),
(16024, 'Isaiah', 23, 29, 19, ' ويزداد البائسون فرحا بالرب ، ويهتف مساكين الناس بقدوس إسرائيل '),
(16025, 'Isaiah', 23, 29, 20, ' لأن العاتي قد باد ، وفني المستهزئ ، وانقطع كل الساهرين على الإثم '),
(16026, 'Isaiah', 23, 29, 21, ' الذين جعلوا الإنسان يخطئ بكلمة ، ونصبوا فخا للمنصف في الباب ، وصدوا البار بالبطل '),
(16027, 'Isaiah', 23, 29, 22, ' لذلك هكذا يقول لبيت يعقوب الرب الذي فدى إبراهيم : ليس الآن يخجل يعقوب ، وليس الآن يصفار وجهه '),
(16028, 'Isaiah', 23, 29, 23, ' بل عند رؤية أولاده عمل يدي في وسطه يقدسون اسمي ، ويقدسون قدوس يعقوب ، ويرهبون إله إسرائيل '),
(16029, 'Isaiah', 23, 29, 24, ' ويعرف الضالو الأرواح فهما ، ويتعلم المتمردون تعليما ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(16030, 'Isaiah', 23, 30, 1, ' ويل للبنين المتمردين ، يقول الرب ، حتى أنهم يجرون رأيا وليس مني ، ويسكبون سكيبا وليس بروحي ، ليزيدوا خطيئة على خطيئة '),
(16031, 'Isaiah', 23, 30, 2, ' الذين يذهبون لينزلوا إلى مصر ولم يسألوا فمي ، ليلتجئوا إلى حصن فرعون ويحتموا بظل مصر '),
(16032, 'Isaiah', 23, 30, 3, ' فيصير لكم حصن فرعون خجلا ، والاحتماء بظل مصر خزيا '),
(16033, 'Isaiah', 23, 30, 4, ' لأن رؤساءه صاروا في صوعن ، وبلغ رسله إلى حانيس '),
(16034, 'Isaiah', 23, 30, 5, ' قد خجل الجميع من شعب لا ينفعهم . ليس للمعونة ولا للمنفعة ، بل للخجل وللخزي '),
(16035, 'Isaiah', 23, 30, 6, ' وحي من جهة بهائم الجنوب : في أرض شدة وضيقة ، منها اللبوة والأسد ، الأفعى والثعبان السام الطيار ، يحملون على أكتاف الحمير ثروتهم ، وعلى أسنمة الجمال كنوزهم ، إلى شعب لا ينفع '),
(16036, 'Isaiah', 23, 30, 7, ' فإن مصر تعين باطلا وعبثا ، لذلك دعوتها رهب الجلوس '),
(16037, 'Isaiah', 23, 30, 8, ' تعال الآن اكتب هذا عندهم على لوح وارسمه في سفر ، ليكون لزمن آت للأبد إلى الدهور '),
(16038, 'Isaiah', 23, 30, 9, ' لأنه شعب متمرد ، أولاد كذبة ، أولاد لم يشاءوا أن يسمعوا شريعة الرب '),
(16039, 'Isaiah', 23, 30, 10, ' الذين يقولون للرائين : لا تروا ، وللناظرين : لا تنظروا لنا مستقيمات . كلمونا بالناعمات . انظروا مخادعات '),
(16040, 'Isaiah', 23, 30, 11, ' حيدوا عن الطريق . ميلوا عن السبيل . اعزلوا من أمامنا قدوس إسرائيل '),
(16041, 'Isaiah', 23, 30, 12, ' لذلك هكذا يقول قدوس إسرائيل : لأنكم رفضتم هذا القول وتوكلتم على الظلم والاعوجاج واستندتم عليهما '),
(16042, 'Isaiah', 23, 30, 13, ' لذلك يكون لكم هذا الإثم كصدع منقض ناتئ في جدار مرتفع ، يأتي هده بغتة في لحظة '),
(16043, 'Isaiah', 23, 30, 14, ' ويكسر ككسر إناء الخزافين ، مسحوقا بلا شفقة ، حتى لا يوجد في مسحوقه شقفة لأخذ نار من الموقدة ، أو لغرف ماء من الجب '),
(16044, 'Isaiah', 23, 30, 15, ' لأنه هكذا قال السيد الرب قدوس إسرائيل : بالرجوع والسكون تخلصون . بالهدوء والطمأنينة تكون قوتكم . فلم تشاءوا '),
(16045, 'Isaiah', 23, 30, 16, ' وقلتم : لا . بل على خيل نهرب . لذلك تهربون . وعلى خيل سريعة نركب . لذلك يسرع طاردوكم '),
(16046, 'Isaiah', 23, 30, 17, ' يهرب ألف من زجرة واحد . من زجرة خمسة تهربون ، حتى أنكم تبقون كسارية على رأس جبل ، وكراية على أكمة '),
(16047, 'Isaiah', 23, 30, 18, ' ولذلك ينتظر الرب ليتراءف عليكم . ولذلك يقوم ليرحمكم ، لأن الرب إله حق . طوبى لجميع منتظريه '),
(16048, 'Isaiah', 23, 30, 19, ' لأن الشعب في صهيون يسكن في أورشليم . لا تبكي بكاء . يتراءف عليك عند صوت صراخك . حينما يسمع يستجيب لك '),
(16049, 'Isaiah', 23, 30, 20, ' ويعطيكم السيد خبزا في الضيق وماء في الشدة . لا يختبئ معلموك بعد ، بل تكون عيناك تريان معلميك '),
(16050, 'Isaiah', 23, 30, 21, ' وأذناك تسمعان كلمة خلفك قائلة : هذه هي الطريق . اسلكوا فيها . حينما تميلون إلى اليمين وحينما تميلون إلى اليسار '),
(16051, 'Isaiah', 23, 30, 22, ' وتنجسون صفائح تماثيل فضتكم المنحوتة ، وغشاء تمثال ذهبكم المسبوك . تطرحها مثل فرصة حائض . تقول لها : اخرجي '),
(16052, 'Isaiah', 23, 30, 23, ' ثم يعطي مطر زرعك الذي تزرع الأرض به ، وخبز غلة الأرض ، فيكون دسما وسمينا ، وترعى ماشيتك في ذلك اليوم في مرعى واسع '),
(16053, 'Isaiah', 23, 30, 24, ' والأبقار والحمير التي تعمل الأرض تأكل علفا مملحا مذرى بالمنسف والمذراة '),
(16054, 'Isaiah', 23, 30, 25, ' ويكون على كل جبل عال وعلى كل أكمة مرتفعة سواق ومجاري مياه في يوم المقتلة العظيمة ، حينما تسقط الأبراج '),
(16055, 'Isaiah', 23, 30, 26, ' ويكون نور القمر كنور الشمس ، ونور الشمس يكون سبعة أضعاف كنور سبعة أيام ، في يوم يجبر الرب كسر شعبه ويشفي رض ضربه '),
(16056, 'Isaiah', 23, 30, 27, ' هوذا اسم الرب يأتي من بعيد . غضبه مشتعل والحريق عظيم . شفتاه ممتلئتان سخطا ، ولسانه كنار آكلة '),
(16057, 'Isaiah', 23, 30, 28, ' ونفخته كنهر غامر يبلغ إلى الرقبة . لغربلة الأمم بغربال السوء ، وعلى فكوك الشعوب رسن مضل '),
(16058, 'Isaiah', 23, 30, 29, ' تكون لكم أغنية كليلة تقديس عيد ، وفرح قلب كالسائر بالناي ، ليأتي إلى جبل الرب ، إلى صخر إسرائيل '),
(16059, 'Isaiah', 23, 30, 30, ' ويسمع الرب جلال صوته ، ويري نزول ذراعه بهيجان غضب ولهيب نار آكلة ، نوء وسيل وحجارة برد '),
(16060, 'Isaiah', 23, 30, 31, ' لأنه من صوت الرب يرتاع أشور . بالقضيب يضرب '),
(16061, 'Isaiah', 23, 30, 32, ' ويكون كل مرور عصا القضاء التي ينزلها الرب عليه بالدفوف والعيدان . وبحروب ثائرة يحاربه '),
(16062, 'Isaiah', 23, 30, 33, ' لأن تفتة مرتبة منذ الأمس ، مهيأة هي أيضا للملك ، عميقة واسعة ، كومتها نار وحطب بكثرة . نفخة الرب كنهر كبريت توقدها '),
(16063, 'Isaiah', 23, 31, 1, ' ويل للذين ينزلون إلى مصر للمعونة ، ويستندون على الخيل ويتوكلون على المركبات لأنها كثيرة ، وعلى الفرسان لأنهم أقوياء جدا ، ولا ينظرون إلى قدوس إسرائيل ولا يطلبون الرب '),
(16064, 'Isaiah', 23, 31, 2, ' وهو أيضا حكيم ويأتي بالشر ولا يرجع بكلامه ، ويقوم على بيت فاعلي الشر وعلى معونة فاعلي الإثم '),
(16065, 'Isaiah', 23, 31, 3, ' وأما المصريون فهم أناس لا آلهة ، وخيلهم جسد لا روح . والرب يمد يده فيعثر المعين ، ويسقط المعان ويفنيان كلاهما معا '),
(16066, 'Isaiah', 23, 48, 12, ' اسمع لي يا يعقوب ، وإسرائيل الذي دعوته : أنا هو . أنا الأول وأنا الآخر '),
(16067, 'Isaiah', 23, 48, 13, ' ويدي أسست الأرض ، ويميني نشرت السماوات . أنا أدعوهن فيقفن معا '),
(16068, 'Isaiah', 23, 48, 14, ' اجتمعوا كلكم واسمعوا . من منهم أخبر بهذه ؟ قد أحبه الرب . يصنع مسرته ببابل ، ويكون ذراعه على الكلدانيين '),
(16069, 'Isaiah', 23, 48, 15, ' أنا أنا تكلمت ودعوته . أتيت به فينجح طريقه '),
(16070, 'Isaiah', 23, 48, 16, ' تقدموا إلي . اسمعوا هذا : لم أتكلم من البدء في الخفاء . منذ وجوده أنا هناك . والآن السيد الرب أرسلني وروحه '),
(16071, 'Isaiah', 23, 41, 19, ' أجعل في البرية الأرز والسنط والآس وشجرة الزيت . أضع في البادية السرو والسنديان والشربين معا '),
(16072, 'Isaiah', 23, 41, 20, ' لكي ينظروا ويعرفوا ويتنبهوا ويتأملوا معا أن يد الرب فعلت هذا وقدوس إسرائيل أبدعه '),
(16073, 'Isaiah', 23, 41, 21, ' قدموا دعواكم ، يقول الرب . أحضروا حججكم ، يقول ملك يعقوب '),
(16074, 'Isaiah', 23, 41, 22, ' ليقدموها ويخبرونا بما سيعرض . ما هي الأوليات ؟ أخبروا فنجعل عليها قلوبنا ونعرف آخرتها ، أو أعلمونا المستقبلات '),
(16075, 'Isaiah', 23, 41, 23, ' أخبروا بالآتيات فيما بعد فنعرف أنكم آلهة ، وافعلوا خيرا أو شرا فنلتفت وننظر معا '),
(16076, 'Isaiah', 23, 41, 24, ' ها أنتم من لا شيء ، وعملكم من العدم . رجس هو الذي يختاركم '),
(16077, 'Isaiah', 23, 41, 25, ' قد أنهضته من الشمال فأتى . من مشرق الشمس يدعو باسمي . يأتي على الولاة كما على الملاط ، وكخزاف يدوس الطين '),
(16078, 'Isaiah', 23, 41, 26, ' من أخبر من البدء حتى نعرف ، ومن قبل حتى نقول : هو صادق ؟ لا مخبر ولا مسمع ولا سامع أقوالكم '),
(16079, 'Isaiah', 23, 41, 27, ' أنا أولا قلت لصهيون : ها ها هم . ولأورشليم جعلت مبشرا '),
(16080, 'Isaiah', 23, 41, 28, ' ونظرت فليس إنسان ، ومن هؤلاء فليس مشير حتى أسألهم فيردون كلمة '),
(16081, 'Isaiah', 23, 41, 29, ' ها كلهم باطل ، وأعمالهم عدم ، ومسبوكاتهم ريح وخلاء '),
(16082, 'Isaiah', 23, 42, 1, ' هوذا عبدي الذي أعضده ، مختاري الذي سرت به نفسي . وضعت روحي عليه فيخرج الحق للأمم '),
(16083, 'Isaiah', 23, 42, 2, ' لا يصيح ولا يرفع ولا يسمع في الشارع صوته '),
(16084, 'Isaiah', 23, 42, 3, ' قصبة مرضوضة لا يقصف ، وفتيلة خامدة لا يطفئ . إلى الأمان يخرج الحق '),
(16085, 'Isaiah', 23, 42, 4, ' لا يكل ولا ينكسر حتى يضع الحق في الأرض ، وتنتظر الجزائر شريعته '),
(16086, 'Isaiah', 23, 42, 5, ' هكذا يقول الله الرب ، خالق السماوات وناشرها ، باسط الأرض ونتائجها ، معطي الشعب عليها نسمة ، والساكنين فيها روحا '),
(16087, 'Isaiah', 23, 42, 6, ' أنا الرب قد دعوتك بالبر ، فأمسك بيدك وأحفظك وأجعلك عهدا للشعب ونورا للأمم '),
(16088, 'Isaiah', 23, 42, 7, ' لتفتح عيون العمي ، لتخرج من الحبس المأسورين ، من بيت السجن الجالسين في الظلمة '),
(16089, 'Isaiah', 23, 42, 8, ' أنا الرب هذا اسمي ، ومجدي لا أعطيه لآخر ، ولا تسبيحي للمنحوتات '),
(16090, 'Isaiah', 23, 42, 9, ' هوذا الأوليات قد أتت ، والحديثات أنا مخبر بها . قبل أن تنبت أعلمكم بها '),
(16091, 'Isaiah', 23, 42, 10, ' غنوا للرب أغنية جديدة ، تسبيحه من أقصى الأرض . أيها المنحدرون في البحر وملؤه والجزائر وسكانها '),
(16092, 'Isaiah', 23, 42, 11, ' لترفع البرية ومدنها صوتها ، الديار التي سكنها قيدار . لتترنم سكان سالع . من رؤوس الجبال ليهتفوا '),
(16093, 'Isaiah', 23, 42, 12, ' ليعطوا الرب مجدا ويخبروا بتسبيحه في الجزائر '),
(16094, 'Isaiah', 23, 42, 13, ' الرب كالجبار يخرج . كرجل حروب ينهض غيرته . يهتف ويصرخ ويقوى على أعدائه '),
(16095, 'Isaiah', 23, 42, 14, ' قد صمت منذ الدهر . سكت . تجلدت . كالوالدة أصيح . أنفخ وأنخر معا '),
(16096, 'Isaiah', 23, 42, 15, ' أخرب الجبال والآكام وأجفف كل عشبها ، وأجعل الأنهار يبسا وأنشف الآجام '),
(16097, 'Isaiah', 23, 42, 16, ' وأسير العمي في طريق لم يعرفوها . في مسالك لم يدروها أمشيهم . أجعل الظلمة أمامهم نورا ، والمعوجات مستقيمة . هذه الأمور أفعلها ولاأتركهم '),
(16098, 'Isaiah', 23, 42, 17, ' قد ارتدوا إلى الوراء . يخزى خزيا المتكلون على المنحوتات ، القائلون للمسبوكات : أنتن آلهتنا '),
(16099, 'Isaiah', 23, 42, 18, ' أيها الصم اسمعوا . أيها العمي انظروا لتبصروا '),
(16100, 'Isaiah', 23, 42, 19, ' من هو أعمى إلا عبدي ، وأصم كرسولي الذي أرسله ؟ من هو أعمى كالكامل ، وأعمى كعبد الرب '),
(16101, 'Isaiah', 23, 42, 20, ' ناظر كثيرا ولا تلاحظ . مفتوح الأذنين ولا يسمع '),
(16102, 'Isaiah', 23, 42, 21, ' الرب قد سر من أجل بره . يعظم الشريعة ويكرمها '),
(16103, 'Isaiah', 23, 42, 22, ' ولكنه شعب منهوب ومسلوب . قد اصطيد في الحفر كله ، وفي بيوت الحبوس اختبأوا . صاروا نهبا ولا منقذ ، وسلبا وليس من يقول : رد '),
(16104, 'Isaiah', 23, 42, 23, ' من منكم يسمع هذا ؟ يصغى ويسمع لما بعد '),
(16105, 'Isaiah', 23, 42, 24, ' من دفع يعقوب إلى السلب وإسرائيل إلى الناهبين ؟ أليس الرب الذي أخطأنا إليه ولم يشاءوا أن يسلكوا في طرقه ولم يسمعوا لشريعته '),
(16106, 'Isaiah', 23, 42, 25, ' فسكب عليه حمو غضبه وشدة الحرب ، فأوقدته من كل ناحية ولم يعرف ، وأحرقته ولم يضع في قلبه '),
(16107, 'Isaiah', 23, 43, 1, ' والآن هكذا يقول الرب ، خالقك يا يعقوب وجابلك يا إسرائيل : لا تخف لأني فديتك . دعوتك باسمك . أنت لي '),
(16108, 'Isaiah', 23, 43, 2, ' إذا اجتزت في المياه فأنا معك ، وفي الأنهار فلا تغمرك . إذا مشيت في النار فلا تلذع ، واللهيب لا يحرقك '),
(16109, 'Isaiah', 23, 43, 3, ' لأني أنا الرب إلهك قدوس إسرائيل ، مخلصك . جعلت مصر فديتك ، كوش وسبا عوضك '),
(16110, 'Isaiah', 23, 43, 4, ' إذ صرت عزيزا في عيني مكرما ، وأنا قد أحببتك . أعطي أناسا عوضك وشعوبا عوض نفسك '),
(16111, 'Isaiah', 23, 43, 5, ' لا تخف فإني معك . من المشرق آتي بنسلك ، ومن المغرب أجمعك '),
(16112, 'Isaiah', 23, 43, 6, ' أقول للشمال : أعط ، وللجنوب : لا تمنع . ايت ببني من بعيد ، وببناتي من أقصى الأرض '),
(16113, 'Isaiah', 23, 43, 7, ' بكل من دعي باسمي ولمجدي خلقته وجبلته وصنعته '),
(16114, 'Isaiah', 23, 43, 8, ' أخرج الشعب الأعمى وله عيون ، والأصم وله آذان '),
(16115, 'Isaiah', 23, 43, 9, ' اجتمعوا يا كل الأمم معا ولتلتئم القبائل . من منهم يخبر بهذا ويعلمنا بالأوليات ؟ ليقدموا شهودهم ويتبرروا . أو ليسمعوا فيقولوا : صدق '),
(16116, 'Isaiah', 23, 43, 10, ' أنتم شهودي ، يقول الرب ، وعبدي الذي اخترته ، لكي تعرفوا وتؤمنوا بي وتفهموا أني أنا هو . قبلي لم يصور إله وبعدي لا يكون '),
(16117, 'Isaiah', 23, 43, 11, ' أنا أنا الرب ، وليس غيري مخلص '),
(16118, 'Isaiah', 23, 43, 12, ' أنا أخبرت وخلصت وأعلمت وليس بينكم غريب . وأنتم شهودي ، يقول الرب ، وأنا الله '),
(16119, 'Isaiah', 23, 43, 13, ' أيضا من اليوم أنا هو ، ولا منقذ من يدي . أفعل ، ومن يرد '),
(16120, 'Isaiah', 23, 43, 14, ' هكذا يقول الرب فاديكم قدوس إسرائيل : لأجلكم أرسلت إلى بابل وألقيت المغاليق كلها والكلدانيين في سفن ترنمهم '),
(16121, 'Isaiah', 23, 43, 15, ' أنا الرب قدوسكم ، خالق إسرائيل ، ملككم '),
(16122, 'Isaiah', 23, 43, 16, ' هكذا يقول الرب الجاعل في البحر طريقا وفي المياه القوية مسلكا '),
(16123, 'Isaiah', 23, 43, 17, ' المخرج المركبة والفرس ، الجيش والعز . يضطجعون معا لا يقومون . قد خمدوا . كفتيلة انطفأوا '),
(16124, 'Isaiah', 23, 43, 18, ' لا تذكروا الأوليات ، والقديمات لا تتأملوا بها '),
(16125, 'Isaiah', 23, 43, 19, ' هأنذا صانع أمرا جديدا . الآن ينبت . ألا تعرفونه ؟ أجعل في البرية طريقا ، في القفر أنهارا '),
(16126, 'Isaiah', 23, 43, 20, ' يمجدني حيوان الصحراء ، الذئاب وبنات النعام ، لأني جعلت في البرية ماء ، أنهارا في القفر ، لأسقي شعبي مختاري '),
(16127, 'Isaiah', 23, 43, 21, ' هذا الشعب جبلته لنفسي . يحدث بتسبيحي '),
(16128, 'Isaiah', 23, 43, 22, ' وأنت لم تدعني يا يعقوب ، حتى تتعب من أجلي يا إسرائيل '),
(16129, 'Isaiah', 23, 43, 23, ' لم تحضر لي شاة محرقتك ، وبذبائحك لم تكرمني . لم أستخدمك بتقدمة ولا أتعبتك بلبان '),
(16130, 'Isaiah', 23, 43, 24, ' لم تشتر لي بفضة قصبا ، وبشحم ذبائحك لم تروني . لكن استخدمتني بخطاياك وأتعبتني بآثامك '),
(16131, 'Isaiah', 23, 43, 25, ' أنا أنا هو الماحي ذنوبك لأجل نفسي ، وخطاياك لا أذكرها '),
(16132, 'Isaiah', 23, 43, 26, ' ذكرني فنتحاكم معا . حدث لكي تتبرر '),
(16133, 'Isaiah', 23, 43, 27, ' أبوك الأول أخطأ ، ووسطاؤك عصوا علي '),
(16134, 'Isaiah', 23, 43, 28, ' فدنست رؤساء القدس ، ودفعت يعقوب إلى اللعن ، وإسرائيل إلى الشتائم '),
(16135, 'Isaiah', 23, 44, 1, ' والآن اسمع يا يعقوب عبدي ، وإسرائيل الذي اخترته '),
(16136, 'Isaiah', 23, 44, 2, ' هكذا يقول الرب صانعك وجابلك من الرحم ، معينك : لا تخف يا عبدي يعقوب ، ويا يشورون الذي اخترته '),
(16137, 'Isaiah', 23, 44, 3, ' لأني أسكب ماء على العطشان ، وسيولا على اليابسة . أسكب روحي على نسلك وبركتي على ذريتك '),
(16138, 'Isaiah', 23, 44, 4, ' فينبتون بين العشب مثل الصفصاف على مجاري المياه '),
(16139, 'Isaiah', 23, 44, 5, ' هذا يقول : أنا للرب ، وهذا يكني باسم يعقوب ، وهذا يكتب بيده : للرب ، وباسم إسرائيل يلقب '),
(16140, 'Isaiah', 23, 44, 6, ' هكذا يقول الرب ملك إسرائيل وفاديه ، رب الجنود : أنا الأول وأنا الآخر ، ولا إله غيري '),
(16141, 'Isaiah', 23, 44, 7, ' ومن مثلي ؟ ينادي ، فليخبر به ويعرضه لي منذ وضعت الشعب القديم . والمستقبلات وما سيأتي ليخبروهم بها '),
(16142, 'Isaiah', 23, 44, 8, ' لا ترتعبوا ولا ترتاعوا . أما أعلمتك منذ القديم وأخبرتك ؟ فأنتم شهودي . هل يوجد إله غيري ؟ ولا صخرة لا أعلم بها '),
(16143, 'Isaiah', 23, 44, 9, ' الذين يصورون صنما كلهم باطل ، ومشتهياتهم لا تنفع ، وشهودهم هي . لا تبصر ولا تعرف حتى تخزى '),
(16144, 'Isaiah', 23, 44, 10, ' من صور إلها وسبك صنما لغير نفع '),
(16145, 'Isaiah', 23, 44, 11, ' ها كل أصحابه يخزون والصناع هم من الناس . يجتمعون كلهم ، يقفون يرتعبون ويخزون معا '),
(16146, 'Isaiah', 23, 44, 12, ' طبع الحديد قدوما ، وعمل في الفحم ، وبالمطارق يصوره فيصنعه بذراع قوته . يجوع أيضا فليس له قوة . لم يشرب ماء وقد تعب '),
(16147, 'Isaiah', 23, 44, 13, ' نجر خشبا . مد الخيط . بالمخرز يعلمه ، يصنعه بالأزاميل ، وبالدوارة يرسمه . فيصنعه كشبه رجل ، كجمال إنسان ، ليسكن في البيت '),
(16148, 'Isaiah', 23, 44, 14, ' قطع لنفسه أرزا وأخذ سنديانا وبلوطا ، واختار لنفسه من أشجار الوعر . غرس سنوبرا والمطر ينميه '),
(16149, 'Isaiah', 23, 44, 15, ' فيصير للناس للإيقاد . ويأخذ منه ويتدفأ . يشعل أيضا ويخبز خبزا ، ثم يصنع إلها فيسجد قد صنعه صنما وخر له '),
(16150, 'Isaiah', 23, 44, 16, ' نصفه أحرقه بالنار . على نصفه يأكل لحما . يشوي مشويا ويشبع يتدفأ أيضا ويقول : بخ قد تدفأت . رأيت نارا '),
(16151, 'Isaiah', 23, 44, 17, ' وبقيته قد صنعها إلها ، صنما لنفسه يخر له ويسجد ، ويصلي إليه ويقول : نجني لأنك أنت إلهي '),
(16152, 'Isaiah', 23, 52, 4, ' لأنه هكذا قال السيد الرب : إلى مصر نزل شعبي أولا ليتغرب هناك . ثم ظلمه أشور بلا سبب '),
(16153, 'Isaiah', 23, 52, 5, ' فالآن ماذا لي هنا ، يقول الرب ، حتى أخذ شعبي مجانا ؟ المتسلطون عليه يصيحون ، يقول الرب ، ودائما كل يوم اسمي يهان '),
(16154, 'Isaiah', 23, 52, 6, ' لذلك يعرف شعبي اسمي . لذلك في ذلك اليوم يعرفون أني أنا هو المتكلم . هأنذا '),
(16155, 'Isaiah', 23, 52, 7, ' ما أجمل على الجبال قدمي المبشر ، المخبر بالسلام ، المبشر بالخير ، المخبر بالخلاص ، القائل لصهيون : قد ملك إلهك '),
(16156, 'Isaiah', 23, 52, 8, ' صوت مراقبيك . يرفعون صوتهم . يترنمون معا ، لأنهم يبصرون عينا لعين عند رجوع الرب إلى صهيون '),
(16157, 'Isaiah', 23, 52, 9, ' أشيدي ترنمي معا يا خرب أورشليم ، لأن الرب قد عزى شعبه . فدى أورشليم '),
(16158, 'Isaiah', 23, 52, 10, ' قد شمر الرب عن ذراع قدسه أمام عيون كل الأمم ، فترى كل أطراف الأرض خلاص إلهنا '),
(16159, 'Isaiah', 23, 52, 11, ' اعتزلوا ، اعتزلوا . اخرجوا من هناك . لا تمسوا نجسا . اخرجوا من وسطها . تطهروا يا حاملي آنية الرب '),
(16160, 'Isaiah', 23, 52, 12, ' لأنكم لا تخرجون بالعجلة ، ولا تذهبون هاربين . لأن الرب سائر أمامكم ، وإله إسرائيل يجمع ساقتكم '),
(16161, 'Isaiah', 23, 52, 13, ' هوذا عبدي يعقل ، يتعالى ويرتقي ويتسامى جدا '),
(16162, 'Isaiah', 23, 52, 14, ' كما اندهش منك كثيرون . كان منظره كذا مفسدا أكثر من الرجل ، وصورته أكثر من بني آدم '),
(16163, 'Isaiah', 23, 52, 15, ' هكذا ينضح أمما كثيرين . من أجله يسد ملوك أفواههم ، لأنهم قد أبصروا ما لم يخبروا به ، وما لم يسمعوه فهموه '),
(16164, 'Isaiah', 23, 53, 1, ' من صدق خبرنا ، ولمن استعلنت ذراع الرب '),
(16165, 'Isaiah', 23, 53, 2, ' نبت قدامه كفرخ وكعرق من أرض يابسة ، لا صورة له ولا جمال فننظر إليه ، ولا منظر فنشتهيه '),
(16166, 'Isaiah', 23, 53, 3, ' محتقر ومخذول من الناس ، رجل أوجاع ومختبر الحزن ، وكمستر عنه وجوهنا ، محتقر فلم نعتد به '),
(16167, 'Isaiah', 23, 53, 4, ' لكن أحزاننا حملها ، وأوجاعنا تحملها . ونحن حسبناه مصابا مضروبا من الله ومذلولا '),
(16168, 'Isaiah', 23, 53, 5, ' وهو مجروح لأجل معاصينا ، مسحوق لأجل آثامنا . تأديب سلامنا عليه ، وبحبره شفينا '),
(16169, 'Isaiah', 23, 53, 6, ' كلنا كغنم ضللنا . ملنا كل واحد إلى طريقه ، والرب وضع عليه إثم جميعنا '),
(16170, 'Isaiah', 23, 53, 7, ' ظلم أما هو فتذلل ولم يفتح فاه . كشاة تساق إلى الذبح ، وكنعجة صامتة أمام جازيها فلم يفتح فاه '),
(16171, 'Isaiah', 23, 53, 8, ' من الضغطة ومن الدينونة أخذ . وفي جيله من كان يظن أنه قطع من أرض الأحياء ، أنه ضرب من أجل ذنب شعبي '),
(16172, 'Isaiah', 23, 53, 9, ' وجعل مع الأشرار قبره ، ومع غني عند موته . على أنه لم يعمل ظلما ، ولم يكن في فمه غش '),
(16173, 'Isaiah', 23, 53, 10, ' أما الرب فسر بأن يسحقه بالحزن . إن جعل نفسه ذبيحة إثم يرى نسلا تطول أيامه ، ومسرة الرب بيده تنجح '),
(16174, 'Isaiah', 23, 53, 11, ' من تعب نفسه يرى ويشبع ، وعبدي البار بمعرفته يبرر كثيرين ، وآثامهم هو يحملها '),
(16175, 'Isaiah', 23, 53, 12, ' لذلك أقسم له بين الأعزاء ومع العظماء يقسم غنيمة ، من أجل أنه سكب للموت نفسه وأحصي مع أثمة ، وهو حمل خطية كثيرين وشفع في المذنبين '),
(16176, 'Isaiah', 23, 54, 1, ' ترنمي أيتها العاقر التي لم تلد . أشيدي بالترنم أيتها التي لم تمخض ، لأن بني المستوحشة أكثر من بني ذات البعل ، قال الرب '),
(16177, 'Isaiah', 23, 54, 2, ' أوسعي مكان خيمتك ، ولتبسط شقق مساكنك . لا تمسكي . أطيلي أطنابك وشددي أوتادك '),
(16178, 'Isaiah', 23, 54, 3, ' لأنك تمتدين إلى اليمين وإلى اليسار ، ويرث نسلك أمما ، ويعمر مدنا خربة '),
(16179, 'Isaiah', 23, 54, 4, ' لا تخافي لأنك لا تخزين ، ولا تخجلي لأنك لا تستحين . فإنك تنسين خزي صباك ، وعار ترملك لا تذكرينه بعد '),
(16180, 'Isaiah', 23, 54, 5, ' لأن بعلك هو صانعك ، رب الجنود اسمه ، ووليك قدوس إسرائيل ، إله كل الأرض يدعى '),
(16181, 'Isaiah', 23, 54, 6, ' لأنه كامرأة مهجورة ومحزونة الروح دعاك الرب ، وكزوجة الصبا إذا رذلت ، قال إلهك '),
(16182, 'Isaiah', 23, 54, 7, ' لحيظة تركتك ، وبمراحم عظيمة سأجمعك '),
(16183, 'Isaiah', 23, 54, 8, ' بفيضان الغضب حجبت وجهي عنك لحظة ، وبإحسان أبدي أرحمك ، قال وليك الرب '),
(16184, 'Isaiah', 23, 54, 9, ' لأنه كمياه نوح هذه لي . كما حلفت أن لا تعبر بعد مياه نوح على الأرض ، هكذا حلفت أن لا أغضب عليك ولا أزجرك '),
(16185, 'Isaiah', 23, 54, 10, ' فإن الجبال تزول ، والآكام تتزعزع ، أما إحساني فلا يزول عنك ، وعهد سلامي لا يتزعزع ، قال راحمك الرب '),
(16186, 'Isaiah', 23, 54, 11, ' أيتها الذليلة المضطربة غير المتعزية ، هأنذا أبني بالأثمد حجارتك ، وبالياقوت الأزرق أؤسسك '),
(16187, 'Isaiah', 23, 54, 12, ' وأجعل شرفك ياقوتا ، وأبوابك حجارة بهرمانية ، وكل تخومك حجارة كريمة '),
(16188, 'Isaiah', 23, 54, 13, ' وكل بنيك تلاميذ الرب ، وسلام بنيك كثيرا '),
(16189, 'Isaiah', 23, 54, 14, ' بالبر تثبتين بعيدة عن الظلم فلا تخافين ، وعن الارتعاب فلا يدنو منك '),
(16190, 'Isaiah', 23, 54, 15, ' ها إنهم يجتمعون اجتماعا ليس من عندي . من اجتمع عليك فإليك يسقط '),
(16191, 'Isaiah', 23, 54, 16, ' هأنذا قد خلقت الحداد الذي ينفخ الفحم في النار ويخرج آلة لعمله ، وأنا خلقت المهلك ليخرب '),
(16192, 'Isaiah', 23, 54, 17, ' كل آلة صورت ضدك لا تنجح ، وكل لسان يقوم عليك في القضاء تحكمين عليه . هذا هو ميراث عبيد الرب وبرهم من عندي ، يقول الرب '),
(16193, 'Isaiah', 23, 55, 1, ' أيها العطاش جميعا هلموا إلى المياه ، والذي ليس له فضة تعالوا اشتروا وكلوا . هلموا اشتروا بلا فضة وبلا ثمن خمرا ولبنا '),
(16194, 'Isaiah', 23, 55, 2, ' لماذا تزنون فضة لغير خبز ، وتعبكم لغير شبع ؟ استمعوا لي استماعا وكلوا الطيب ، ولتتلذذ بالدسم أنفسكم '),
(16195, 'Isaiah', 23, 55, 3, ' أميلوا آذانكم وهلموا إلي . اسمعوا فتحيا أنفسكم . وأقطع لكم عهدا أبديا ، مراحم داود الصادقة '),
(16196, 'Isaiah', 23, 55, 4, ' هوذا قد جعلته شارعا للشعوب ، رئيسا وموصيا للشعوب '),
(16197, 'Isaiah', 23, 55, 5, ' ها أمة لا تعرفها تدعوها ، وأمة لم تعرفك تركض إليك ، من أجل الرب إلهك وقدوس إسرائيل لأنه قد مجدك '),
(16198, 'Isaiah', 23, 55, 6, ' اطلبوا الرب ما دام يوجد . ادعوه وهو قريب '),
(16199, 'Isaiah', 23, 55, 7, ' ليترك الشرير طريقه ، ورجل الإثم أفكاره ، وليتب إلى الرب فيرحمه ، وإلى إلهنا لأنه يكثر الغفران '),
(16200, 'Isaiah', 23, 55, 8, ' لأن أفكاري ليست أفكاركم ، ولا طرقكم طرقي ، يقول الرب '),
(16201, 'Isaiah', 23, 55, 9, ' لأنه كما علت السماوات عن الأرض ، هكذا علت طرقي عن طرقكم وأفكاري عن أفكاركم '),
(16202, 'Isaiah', 23, 55, 10, ' لأنه كما ينزل المطر والثلج من السماء ولا يرجعان إلى هناك ، بل يرويان الأرض ويجعلانها تلد وتنبت وتعطي زرعا للزارع وخبزا للآكل '),
(16203, 'Isaiah', 23, 55, 11, ' هكذا تكون كلمتي التي تخرج من فمي . لا ترجع إلي فارغة ، بل تعمل ما سررت به وتنجح في ما أرسلتها له '),
(16204, 'Isaiah', 23, 55, 12, ' لأنكم بفرح تخرجون وبسلام تحضرون . الجبال والآكام تشيد أمامكم ترنما ، وكل شجر الحقل تصفق بالأيادي '),
(16205, 'Isaiah', 23, 55, 13, ' عوضا عن الشوك ينبت سرو ، وعوضا عن القريس يطلع آس . ويكون للرب اسما ، علامة أبدية لا تنقطع '),
(16206, 'Isaiah', 23, 56, 1, ' هكذا قال الرب : احفظوا الحق وأجروا العدل . لأنه قريب مجيء خلاصي واستعلان بري '),
(16207, 'Isaiah', 23, 56, 2, ' طوبى للإنسان الذي يعمل هذا ، ولابن الإنسان الذي يتمسك به ، الحافظ السبت لئلا ينجسه ، والحافظ يده من كل عمل شر '),
(16208, 'Isaiah', 23, 56, 3, ' فلا يتكلم ابن الغريب الذي اقترن بالرب قائلا : إفرازا أفرزني الرب من شعبه . ولا يقل الخصي : ها أنا شجرة يابسة '),
(16209, 'Isaiah', 23, 1, 1, ' رؤيا إشعياء بن آموص ، التي رآها على يهوذا وأورشليم ، في أيام عزيا ويوثام وآحاز وحزقيا ملوك يهوذا '),
(16210, 'Isaiah', 23, 1, 2, ' اسمعي أيتها السماوات وأصغي أيتها الأرض ، لأن الرب يتكلم : ربيت بنين ونشأتهم ، أما هم فعصوا علي '),
(16211, 'Isaiah', 23, 1, 3, ' الثور يعرف قانيه والحمار معلف صاحبه ، أما إسرائيل فلا يعرف . شعبي لا يفهم '),
(16212, 'Isaiah', 23, 1, 4, ' ويل للأمة الخاطئة ، الشعب الثقيل الإثم ، نسل فاعلي الشر ، أولاد مفسدين تركوا الرب ، استهانوا بقدوس إسرائيل ، ارتدوا إلى وراء '),
(16213, 'Isaiah', 23, 1, 5, ' على م تضربون بعد ؟ تزدادون زيغانا كل الرأس مريض ، وكل القلب سقيم '),
(16214, 'Isaiah', 23, 3, 13, ' قد انتصب الرب للمخاصمة ، وهو قائم لدينونة الشعوب '),
(16215, 'Isaiah', 23, 3, 14, ' الرب يدخل في المحاكمة مع شيوخ شعبه ورؤسائهم : وأنتم قد أكلتم الكرم . سلب البائس في بيوتكم '),
(16216, 'Isaiah', 23, 3, 15, ' ما لكم تسحقون شعبي ، وتطحنون وجوه البائسين ؟ يقول السيد رب الجنود '),
(16217, 'Isaiah', 23, 3, 16, ' وقال الرب : من أجل أن بنات صهيون يتشامخن ، ويمشين ممدودات الأعناق ، وغامزات بعيونهن ، وخاطرات في مشيهن ، ويخشخشن بأرجلهن '),
(16218, 'Isaiah', 23, 3, 17, ' يصلع السيد هامة بنات صهيون ، ويعري الرب عورتهن '),
(16219, 'Isaiah', 23, 3, 18, ' ينزع السيد في ذلك اليوم زينة الخلاخيل والضفائر والأهلة '),
(16220, 'Isaiah', 23, 3, 19, ' والحلق والأساور والبراقع '),
(16221, 'Isaiah', 23, 3, 20, ' والعصائب والسلاسل والمناطق وحناجر الشمامات والأحراز '),
(16222, 'Isaiah', 23, 3, 21, ' والخواتم وخزائم الأنف '),
(16223, 'Isaiah', 23, 3, 22, ' والثياب المزخرفة والعطف والأردية والأكياس '),
(16224, 'Isaiah', 23, 3, 23, ' والمرائي والقمصان والعمائم والأزر '),
(16225, 'Isaiah', 23, 3, 24, ' فيكون عوض الطيب عفونة ، وعوض المنطقة حبل ، وعوض الجدائل قرعة ، وعوض الديباج زنار مسح ، وعوض الجمال كي '),
(16226, 'Isaiah', 23, 3, 25, ' رجالك يسقطون بالسيف ، وأبطالك في الحرب '),
(16227, 'Isaiah', 23, 3, 26, ' فتئن وتنوح أبوابها ، وهي فارغة تجلس على الأرض '),
(16228, 'Isaiah', 23, 4, 1, ' فتمسك سبع نساء برجل واحد في ذلك اليوم قائلات : نأكل خبزنا ونلبس ثيابنا . ليدع فقط اسمك علينا . انزع عارنا '),
(16229, 'Isaiah', 23, 4, 2, ' في ذلك اليوم يكون غصن الرب بهاء ومجدا ، وثمر الأرض فخرا وزينة للناجين من إسرائيل '),
(16230, 'Isaiah', 23, 4, 3, ' ويكون أن الذي يبقى في صهيون والذي يترك في أورشليم ، يسمى قدوسا . كل من كتب للحياة في أورشليم '),
(16231, 'Isaiah', 23, 4, 4, ' إذا غسل السيد قذر بنات صهيون ، ونقى دم أورشليم من وسطها بروح القضاء وبروح الإحراق '),
(16232, 'Isaiah', 23, 4, 5, ' يخلق الرب على كل مكان من جبل صهيون وعلى محفلها سحابة نهارا ، ودخانا ولمعان نار ملتهبة ليلا ، لأن على كل مجد غطاء '),
(16233, 'Isaiah', 23, 4, 6, ' وتكون مظلة للفيء نهارا من الحر ، ولملجأ ولمخبأ من السيل ومن المطر '),
(16234, 'Isaiah', 23, 5, 1, ' لأنشدن عن حبيبي نشيد محبي لكرمه : كان لحبيبي كرم على أكمة خصبة '),
(16235, 'Isaiah', 23, 5, 2, ' فنقبه ونقى حجارته وغرسه كرم سورق ، وبنى برجا في وسطه ، ونقر فيه أيضا معصرة ، فانتظر أن يصنع عنبا فصنع عنبا رديئا '),
(16236, 'Isaiah', 23, 5, 3, ' والآن يا سكان أورشليم ورجال يهوذا ، احكموا بيني وبين كرمي '),
(16237, 'Isaiah', 23, 5, 4, ' ماذا يصنع أيضا لكرمي وأنا لم أصنعه له ؟ لماذا إذ انتظرت أن يصنع عنبا ، صنع عنبا رديئا '),
(16238, 'Isaiah', 23, 5, 5, ' فالآن أعرفكم ماذا أصنع بكرمي : أنزع سياجه فيصير للرعي . أهدم جدرانه فيصير للدوس '),
(16239, 'Isaiah', 23, 5, 6, ' وأجعله خرابا لا يقضب ولا ينقب ، فيطلع شوك وحسك . وأوصي الغيم أن لا يمطر عليه مطرا '),
(16240, 'Isaiah', 23, 5, 7, ' إن كرم رب الجنود هو بيت إسرائيل ، وغرس لذته رجال يهوذا . فانتظر حقا فإذا سفك دم ، وعدلا فإذا صراخ '),
(16241, 'Isaiah', 23, 5, 8, ' ويل للذين يصلون بيتا ببيت ، ويقرنون حقلا بحقل ، حتى لم يبق موضع . فصرتم تسكنون وحدكم في وسط الأرض '),
(16242, 'Isaiah', 23, 5, 9, ' في أذني قال رب الجنود : ألا إن بيوتا كثيرة تصير خرابا بيوتا كبيرة وحسنة بلا ساكن '),
(16243, 'Isaiah', 23, 5, 10, ' لأن عشرة فدادين كرم تصنع بثا واحدا ، وحومر بذار يصنع إيفة '),
(16244, 'Isaiah', 23, 5, 11, ' ويل للمبكرين صباحا يتبعون المسكر ، للمتأخرين في العتمة تلهبهم الخمر '),
(16245, 'Isaiah', 23, 5, 12, ' وصار العود والرباب والدف والناي والخمر ولائمهم ، وإلى فعل الرب لا ينظرون ، وعمل يديه لا يرون '),
(16246, 'Isaiah', 23, 5, 13, ' لذلك سبي شعبي لعدم المعرفة ، وتصير شرفاؤه رجال جوع ، وعامته يابسين من العطش '),
(16247, 'Isaiah', 23, 5, 14, ' لذلك وسعت الهاوية نفسها ، وفغرت فاها بلا حد ، فينزل بهاؤها وجمهورها وضجيجها والمبتهج فيها '),
(16248, 'Isaiah', 23, 5, 15, ' ويذل الإنسان ويحط الرجل ، وعيون المستعلين توضع '),
(16249, 'Isaiah', 23, 5, 16, ' ويتعالى رب الجنود بالعدل ، ويتقدس الإله القدوس بالبر '),
(16250, 'Isaiah', 23, 5, 17, ' وترعى الخرفان حيثما تساق ، وخرب السمان تأكلها الغرباء '),
(16251, 'Isaiah', 23, 5, 18, ' ويل للجاذبين الإثم بحبال البطل ، والخطية كأنه بربط العجلة '),
(16252, 'Isaiah', 23, 5, 19, ' القائلين : ليسرع ، ليعجل عمله لكي نرى ، وليقرب ويأت مقصد قدوس إسرائيل لنعلم '),
(16253, 'Isaiah', 23, 5, 20, ' ويل للقائلين للشر خيرا وللخير شرا ، الجاعلين الظلام نورا والنور ظلاما ، الجاعلين المر حلوا والحلو مرا '),
(16254, 'Isaiah', 23, 5, 21, ' ويل للحكماء في أعين أنفسهم ، والفهماء عند ذواتهم '),
(16255, 'Isaiah', 23, 5, 22, ' ويل للأبطال على شرب الخمر ، ولذوي القدرة على مزج المسكر '),
(16256, 'Isaiah', 23, 5, 23, ' الذين يبررون الشرير من أجل الرشوة ، وأما حق الصديقين فينزعونه منهم '),
(16257, 'Isaiah', 23, 5, 24, ' لذلك كما يأكل لهيب النار القش ، ويهبط الحشيش الملتهب ، يكون أصلهم كالعفونة ، ويصعد زهرهم كالغبار ، لأنهم رذلوا شريعة رب الجنود ، واستهانوا بكلام قدوس إسرائيل '),
(16258, 'Isaiah', 23, 5, 25, ' من أجل ذلك حمي غضب الرب على شعبه ، ومد يده عليه وضربه ، حتى ارتعدت الجبال وصارت جثثهم كالزبل في الأزقة . مع كل هذا لم يرتد غضبه ، بل يده ممدودة بعد '),
(16259, 'Isaiah', 23, 5, 26, ' فيرفع راية للأمم من بعيد ، ويصفر لهم من أقصى الأرض ، فإذا هم بالعجلة يأتون سريعا '),
(16260, 'Isaiah', 23, 5, 27, ' ليس فيهم رازح ولا عاثر . لا ينعسون ولا ينامون ، ولا تنحل حزم أحقائهم ، ولا تنقطع سيور أحذيتهم '),
(16261, 'Isaiah', 23, 5, 28, ' الذين سهامهم مسنونة ، وجميع قسيهم ممدودة . حوافر خيلهم تحسب كالصوان ، وبكراتهم كالزوبعة '),
(16262, 'Isaiah', 23, 5, 29, ' لهم زمجرة كاللبوة ، ويزمجرون كالشبل ، ويهرون ويمسكون الفريسة ويستخلصونها ولا منقذ '),
(16263, 'Isaiah', 23, 5, 30, ' يهرون عليهم في ذلك اليوم كهدير البحر . فإن نظر إلى الأرض فهوذا ظلام الضيق ، والنور قد أظلم بسحبها '),
(16264, 'Isaiah', 23, 6, 1, ' في سنة وفاة عزيا الملك ، رأيت السيد جالسا على كرسي عال ومرتفع ، وأذياله تملأ الهيكل '),
(16265, 'Isaiah', 23, 6, 2, ' السرافيم واقفون فوقه ، لكل واحد ستة أجنحة ، باثنين يغطي وجهه ، وباثنين يغطي رجليه ، وباثنين يطير '),
(16266, 'Isaiah', 23, 6, 3, ' وهذا نادى ذاك وقال : قدوس ، قدوس ، قدوس رب الجنود . مجده ملء كل الأرض '),
(16267, 'Isaiah', 23, 6, 4, ' فاهتزت أساسات العتب من صوت الصارخ ، وامتلأ البيت دخانا '),
(16268, 'Isaiah', 23, 6, 5, ' فقلت : ويل لي إني هلكت ، لأني إنسان نجس الشفتين ، وأنا ساكن بين شعب نجس الشفتين ، لأن عيني قد رأتا الملك رب الجنود '),
(16269, 'Isaiah', 23, 6, 6, ' فطار إلي واحد من السرافيم وبيده جمرة قد أخذها بملقط من على المذبح '),
(16270, 'Isaiah', 23, 6, 7, ' ومس بها فمي وقال : إن هذه قد مست شفتيك ، فانتزع إثمك ، وكفر عن خطيتك '),
(16271, 'Isaiah', 23, 6, 8, ' ثم سمعت صوت السيد قائلا : من أرسل ؟ ومن يذهب من أجلنا فقلت : هأنذا أرسلني '),
(16272, 'Isaiah', 23, 6, 9, ' فقال : اذهب وقل لهذا الشعب : اسمعوا سمعا ولا تفهموا ، وأبصروا إبصارا ولا تعرفوا '),
(16273, 'Isaiah', 23, 6, 10, ' غلظ قلب هذا الشعب وثقل أذنيه واطمس عينيه ، لئلا يبصر بعينيه ويسمع بأذنيه ويفهم بقلبه ، ويرجع فيشفى '),
(16274, 'Isaiah', 23, 6, 11, ' فقلت : إلى متى أيها السيد ؟  . فقال : إلى أن تصير المدن خربة بلا ساكن ، والبيوت بلا إنسان ، وتخرب الأرض وتقفر '),
(16275, 'Isaiah', 23, 6, 12, ' ويبعد الرب الإنسان ، ويكثر الخراب في وسط الأرض '),
(16276, 'Isaiah', 23, 6, 13, ' وإن بقي فيها عشر بعد ، فيعود ويصير للخراب ، ولكن كالبطمة والبلوطة ، التي وإن قطعت فلها ساق ، يكون ساقه زرعا مقدسا '),
(16277, 'Isaiah', 23, 7, 1, ' وحدث في أيام آحاز بن يوثام بن عزيا ملك يهوذا ، أن رصين ملك أرام صعد مع فقح بن رمليا ملك إسرائيل إلى أورشليم لمحاربتها ، فلم يقدر أن يحاربها '),
(16278, 'Isaiah', 23, 7, 2, ' وأخبر بيت داود وقيل له : قد حلت أرام في أفرايم . فرجف قلبه وقلوب شعبه كرجفان شجر الوعر قدام الريح '),
(16279, 'Isaiah', 23, 7, 3, ' فقال الرب لإشعياء : اخرج لملاقاة آحاز ، أنت وشآرياشوب ابنك ، إلى طرف قناة البركة العليا ، إلى سكة حقل القصار '),
(16280, 'Isaiah', 23, 7, 4, ' وقل له : احترز واهدأ . لا تخف ولا يضعف قلبك من أجل ذنبي هاتين الشعلتين المدخنتين ، بحمو غضب رصين وأرام وابن رمليا '),
(16281, 'Isaiah', 23, 7, 5, ' لأن أرام تآمرت عليك بشر مع أفرايم وابن رمليا قائلة '),
(16282, 'Isaiah', 23, 7, 6, ' نصعد على يهوذا ونقوضها ونستفتحها لأنفسنا ، ونملك في وسطها ملكا ، ابن طبئيل '),
(16283, 'Isaiah', 23, 7, 7, ' هكذا يقول السيد الرب : لا تقوم لا تكون '),
(16284, 'Isaiah', 23, 7, 8, ' لأن رأس أرام دمشق ، ورأس دمشق رصين . وفي مدة خمس وستين سنة ينكسر أفرايم حتى لا يكون شعبا '),
(16285, 'Isaiah', 23, 7, 9, ' ورأس أفرايم السامرة ، ورأس السامرة ابن رمليا . إن لم تؤمنوا فلا تأمنوا '),
(16286, 'Isaiah', 23, 7, 10, ' ثم عاد الرب فكلم آحاز قائلا '),
(16287, 'Isaiah', 23, 7, 11, ' اطلب لنفسك آية من الرب إلهك . عمق طلبك أو رفعه إلى فوق '),
(16288, 'Isaiah', 23, 7, 12, ' فقال آحاز : لا أطلب ولا أجرب الرب '),
(16289, 'Isaiah', 23, 7, 13, ' فقال : اسمعوا يا بيت داود هل هو قليل عليكم أن تضجروا الناس حتى تضجروا إلهي أيضا '),
(16290, 'Isaiah', 23, 7, 14, ' ولكن يعطيكم السيد نفسه آية : ها العذراء تحبل وتلد ابنا وتدعو اسمه عمانوئيل '),
(16291, 'Isaiah', 23, 7, 15, ' زبدا وعسلا يأكل متى عرف أن يرفض الشر ويختار الخير '),
(16292, 'Isaiah', 23, 7, 16, ' لأنه قبل أن يعرف الصبي أن يرفض الشر ويختار الخير ، تخلى الأرض التي أنت خاش من ملكيها '),
(16293, 'Isaiah', 23, 7, 17, ' يجلب الرب عليك وعلى شعبك وعلى بيت أبيك ، أياما لم تأت منذ يوم اعتزال أفرايم عن يهوذا ، أي ملك أشور '),
(16294, 'Isaiah', 23, 7, 18, ' ويكون في ذلك اليوم أن الرب يصفر للذباب الذي في أقصى ترع مصر ، وللنحل الذي في أرض أشور '),
(16295, 'Isaiah', 23, 7, 19, ' فتأتي وتحل جميعها في الأودية الخربة وفي شقوق الصخور ، وفي كل غاب الشوك ، وفي كل المراعي '),
(16296, 'Isaiah', 23, 7, 20, ' في ذلك اليوم يحلق السيد بموسى مستأجرة في عبر النهر ، بملك أشور ، الرأس وشعر الرجلين ، وتنزع اللحية أيضا '),
(16297, 'Isaiah', 23, 7, 21, ' ويكون في ذلك اليوم أن الإنسان يربي عجلة بقر وشاتين '),
(16298, 'Isaiah', 23, 7, 22, ' ويكون أنه من كثرة صنعها اللبن يأكل زبدا ، فإن كل من أبقي في الأرض يأكل زبدا وعسلا '),
(16299, 'Isaiah', 23, 7, 23, ' ويكون في ذلك اليوم أن كل موضع كان فيه ألف جفنة بألف من الفضة ، يكون للشوك والحسك '),
(16300, 'Isaiah', 23, 7, 24, ' بالسهام والقوس يؤتى إلى هناك ، لأن كل الأرض تكون شوكا وحسكا '),
(16301, 'Isaiah', 23, 7, 25, ' وجميع الجبال التي تنقب بالمعول ، لا يؤتى إليها خوفا من الشوك والحسك ، فتكون لسرح البقر ولدوس الغنم '),
(16302, 'Isaiah', 23, 8, 1, ' وقال لي الرب : خذ لنفسك لوحا كبيرا ، واكتب عليه بقلم إنسان : لمهير شلال حاش بز '),
(16303, 'Isaiah', 23, 8, 2, ' وأن أشهد لنفسي شاهدين أمينين : أوريا الكاهن ، وزكريا بن يبرخيا '),
(16304, 'Isaiah', 23, 8, 3, ' فاقتربت إلى النبية فحبلت وولدت ابنا . فقال لي الرب : ادع اسمه مهير شلال حاش بز '),
(16305, 'Isaiah', 23, 8, 4, ' لأنه قبل أن يعرف الصبي أن يدعو : يا أبي ويا أمي ، تحمل ثروة دمشق وغنيمة السامرة قدام ملك أشور '),
(16306, 'Isaiah', 23, 8, 5, ' ثم عاد الرب يكلمني أيضا قائلا '),
(16307, 'Isaiah', 23, 8, 6, ' لأن هذا الشعب رذل مياه شيلوه الجارية بسكوت ، وسر برصين وابن رمليا '),
(16308, 'Isaiah', 23, 8, 7, ' لذلك هوذا السيد يصعد عليهم مياه النهر القوية والكثيرة ، ملك أشور وكل مجده ، فيصعد فوق جميع مجاريه ويجري فوق جميع شطوطه '),
(16309, 'Isaiah', 23, 8, 8, ' ويندفق إلى يهوذا . يفيض ويعبر . يبلغ العنق . ويكون بسط جناحيه ملء عرض بلادك يا عمانوئيل '),
(16310, 'Isaiah', 23, 8, 9, ' هيجوا أيها الشعوب وانكسروا ، وأصغي يا جميع أقاصي الأرض . احتزموا وانكسروا احتزموا وانكسروا '),
(16311, 'Isaiah', 23, 8, 10, ' تشاوروا مشورة فتبطل . تكلموا كلمة فلا تقوم ، لأن الله معنا '),
(16312, 'Isaiah', 23, 8, 11, ' فإنه هكذا قال لي الرب بشدة اليد ، وأنذرني أن لا أسلك في طريق هذا الشعب قائلا '),
(16313, 'Isaiah', 23, 8, 12, ' لا تقولوا : فتنة لكل ما يقول له هذا الشعب فتنة ، ولا تخافوا خوفه ولا ترهبوا '),
(16314, 'Isaiah', 23, 8, 13, ' قدسوا رب الجنود فهو خوفكم وهو رهبتكم '),
(16315, 'Isaiah', 23, 8, 14, ' ويكون مقدسا وحجر صدمة وصخرة عثرة لبيتي إسرائيل ، وفخا وشركا لسكان أورشليم '),
(16316, 'Isaiah', 23, 8, 15, ' فيعثر بها كثيرون ويسقطون ، فينكسرون ويعلقون فيلقطون '),
(16317, 'Isaiah', 23, 8, 16, ' صر الشهادة . اختم الشريعة بتلاميذي '),
(16318, 'Isaiah', 23, 8, 17, ' فأصطبر للرب الساتر وجهه عن بيت يعقوب وأنتظره '),
(16319, 'Isaiah', 23, 8, 18, ' هأنذا والأولاد الذين أعطانيهم الرب آيات ، وعجائب في إسرائيل من عند رب الجنود الساكن في جبل صهيون '),
(16320, 'Isaiah', 23, 8, 19, ' وإذا قالوا لكم : اطلبوا إلى أصحاب التوابع والعرافين المشقشقين والهامسين . ألا يسأل شعب إلهه ؟ أيسأل الموتى لأجل الأحياء '),
(16321, 'Isaiah', 23, 8, 20, ' إلى الشريعة وإلى الشهادة . إن لم يقولوا مثل هذا القول فليس لهم فجر '),
(16322, 'Isaiah', 23, 8, 21, ' فيعبرون فيها مضايقين وجائعين . ويكون حينما يجوعون أنهم يحنقون ويسبون ملكهم وإلههم ويلتفتون إلى فوق '),
(16323, 'Isaiah', 23, 8, 22, ' وينظرون إلى الأرض وإذا شدة وظلمة ، قتام الضيق ، وإلى الظلام هم مطرودون '),
(16324, 'Isaiah', 23, 9, 1, ' ولكن لا يكون ظلام للتي عليها ضيق . كما أهان الزمان الأول أرض زبولون وأرض نفتالي ، يكرم الأخير طريق البحر ، عبر الأردن ، جليل الأمم '),
(16325, 'Isaiah', 23, 9, 2, ' الشعب السالك في الظلمة أبصر نورا عظيما . الجالسون في أرض ظلال الموت أشرق عليهم نور '),
(16326, 'Isaiah', 23, 9, 3, ' أكثرت الأمة . عظمت لها الفرح . يفرحون أمامك كالفرح في الحصاد . كالذين يبتهجون عندما يقتسمون غنيمة '),
(16327, 'Isaiah', 23, 9, 4, ' لأن نير ثقله ، وعصا كتفه ، وقضيب مسخره كسرتهن كما في يوم مديان '),
(16328, 'Isaiah', 23, 9, 5, ' لأن كل سلاح المتسلح في الوغى وكل رداء مدحرج في الدماء ، يكون للحريق ، مأكلا للنار '),
(16329, 'Isaiah', 23, 9, 6, ' لأنه يولد لنا ولد ونعطى ابنا ، وتكون الرياسة على كتفه ، ويدعى اسمه عجيبا مشيرا ، إلها قديرا ، أبا أبديا ، رئيس السلام '),
(16330, 'Isaiah', 23, 9, 7, ' لنمو رياسته ، وللسلام لا نهاية على كرسي داود وعلى مملكته ، ليثبتها ويعضدها بالحق والبر ، من الآن إلى الأبد . غيرة رب الجنود تصنع هذا '),
(16331, 'Isaiah', 23, 9, 8, ' أرسل الرب قولا في يعقوب فوقع في إسرائيل '),
(16332, 'Isaiah', 23, 9, 9, ' فيعرف الشعب كله ، أفرايم وسكان السامرة ، القائلون بكبرياء وبعظمة قلب '),
(16333, 'Isaiah', 23, 9, 10, ' قد هبط اللبن فنبني بحجارة منحوتة . قطع الجميز فنستخلفه بأرز '),
(16334, 'Isaiah', 23, 9, 11, ' فيرفع الرب أخصام رصين عليه ويهيج أعداءه '),
(16335, 'Isaiah', 23, 9, 12, ' الأراميين من قدام والفلسطينيين من وراء ، فيأكلون إسرائيل بكل الفم . مع كل هذا لم يرتد غضبه ، بل يده ممدودة بعد '),
(16336, 'Isaiah', 23, 9, 13, ' والشعب لم يرجع إلى ضاربه ولم يطلب رب الجنود '),
(16337, 'Isaiah', 23, 9, 14, ' فيقطع الرب من إسرائيل الرأس والذنب ، النخل والأسل ، في يوم واحد '),
(16338, 'Isaiah', 23, 9, 15, ' الشيخ والمعتبر هو الرأس ، والنبي الذي يعلم بالكذب هو الذنب '),
(16339, 'Isaiah', 23, 9, 16, ' وصار مرشدو هذا الشعب مضلين ، ومرشدوه مبتلعين '),
(16340, 'Isaiah', 23, 9, 17, ' لأجل ذلك لا يفرح السيد بفتيانه ، ولا يرحم يتاماه وأرامله ، لأن كل واحد منهم منافق وفاعل شر . وكل فم متكلم بالحماقة . مع كل هذا لم يرتد غضبه ، بل يده ممدودة بعد '),
(16341, 'Isaiah', 23, 9, 18, ' لأن الفجور يحرق كالنار ، تأكل الشوك والحسك ، وتشعل غاب الوعر فتلتف عمود دخان '),
(16342, 'Isaiah', 23, 9, 19, ' بسخط رب الجنود تحرق الأرض ، ويكون الشعب كمأكل للنار . لا يشفق الإنسان على أخيه '),
(16343, 'Isaiah', 23, 9, 20, ' يلتهم على اليمين فيجوع ، ويأكل على الشمال فلا يشبع . يأكلون كل واحد لحم ذراعه '),
(16344, 'Isaiah', 23, 9, 21, ' منسى أفرايم ، وأفرايم منسى ، وهما معا على يهوذا . مع كل هذا لم يرتد غضبه ، بل يده ممدودة بعد '),
(16345, 'Isaiah', 23, 10, 1, ' ويل للذين يقضون أقضية البطل ، وللكتبة الذين يسجلون جورا '),
(16346, 'Isaiah', 23, 10, 2, ' ليصدوا الضعفاء عن الحكم ، ويسلبوا حق بائسي شعبي ، لتكون الأرامل غنيمتهم وينهبوا الأيتام '),
(16347, 'Isaiah', 23, 10, 3, ' وماذا تفعلون في يوم العقاب ، حين تأتي التهلكة من بعيد ؟ إلى من تهربون للمعونة ، وأين تتركون مجدكم '),
(16348, 'Isaiah', 23, 10, 4, ' إما يجثون بين الأسرى ، وإما يسقطون تحت القتلى . مع كل هذا لم يرتد غضبه ، بل يده ممدودة بعد '),
(16349, 'Isaiah', 23, 10, 5, ' ويل لأشور قضيب غضبي ، والعصا في يدهم هي سخطي '),
(16350, 'Isaiah', 23, 10, 6, ' على أمة منافقة أرسله ، وعلى شعب سخطي أوصيه ، ليغتنم غنيمة وينهب نهبا ، ويجعلهم مدوسين كطين الأزقة '),
(16351, 'Isaiah', 23, 10, 7, ' أما هو فلا يفتكر هكذا ، ولا يحسب قلبه هكذا . بل في قلبه أن يبيد ويقرض أمما ليست بقليلة '),
(16352, 'Isaiah', 23, 10, 8, ' فإنه يقول : أليست رؤسائي جميعا ملوكا '),
(16353, 'Isaiah', 23, 10, 9, ' أليست كلنو مثل كركميش ؟ أليست حماة مثل أرفاد ؟ أليست السامرة مثل دمشق '),
(16354, 'Isaiah', 23, 10, 10, ' كما أصابت يدي ممالك الأوثان ، وأصنامها المنحوتة هي أكثر من التي لأورشليم وللسامرة '),
(16355, 'Isaiah', 23, 10, 11, ' أفليس كما صنعت بالسامرة وبأوثانها أصنع بأورشليم وأصنامها '),
(16356, 'Isaiah', 23, 10, 12, ' فيكون متى أكمل السيد كل عمله بجبل صهيون وبأورشليم ، أني أعاقب ثمر عظمة قلب ملك أشور وفخر رفعة عينيه '),
(16357, 'Isaiah', 23, 10, 13, ' لأنه قال : بقدرة يدي صنعت ، وبحكمتي . لأني فهيم . ونقلت تخوم شعوب ، ونهبت ذخائرهم ، وحططت الملوك كبطل '),
(16358, 'Isaiah', 23, 10, 14, ' فأصابت يدي ثروة الشعوب كعش ، وكما يجمع بيض مهجور ، جمعت أنا كل الأرض ، ولم يكن مرفرف جناح ولا فاتح فم ولا مصفصف '),
(16359, 'Isaiah', 23, 10, 15, ' هل تفتخر الفأس على القاطع بها ، أو يتكبر المنشار على مردده ؟ كأن القضيب يحرك رافعه كأن العصا ترفع من ليس هو عودا '),
(16360, 'Isaiah', 23, 10, 16, ' لذلك يرسل السيد ، سيد الجنود ، على سمانه هزالا ، ويوقد تحت مجده وقيدا كوقيد النار '),
(16361, 'Isaiah', 23, 10, 17, ' ويصير نور إسرائيل نارا وقدوسه لهيبا ، فيحرق ويأكل حسكه وشوكه في يوم واحد '),
(16362, 'Isaiah', 23, 10, 18, ' ويفني مجد وعره وبستانه ، النفس والجسد جميعا . فيكون كذوبان المريض '),
(16363, 'Isaiah', 23, 10, 19, ' وبقية أشجار وعره تكون قليلة حتى يكتبها صبي '),
(16364, 'Isaiah', 23, 10, 20, ' ويكون في ذلك اليوم أن بقية إسرائيل والناجين من بيت يعقوب لا يعودون يتوكلون أيضا على ضاربهم ، بل يتوكلون على الرب قدوس إسرائيل بالحق '),
(16365, 'Isaiah', 23, 10, 21, ' ترجع البقية ، بقية يعقوب ، إلى الله القدير '),
(16366, 'Isaiah', 23, 10, 22, ' لأنه وإن كان شعبك يا إسرائيل كرمل البحر ترجع بقية منه . قد قضي بفناء فائض بالعدل '),
(16367, 'Isaiah', 23, 10, 23, ' لأن السيد رب الجنود يصنع فناء وقضاء في كل الأرض '),
(16368, 'Isaiah', 23, 10, 24, ' ولكن هكذا يقول السيد رب الجنود : لا تخف من أشور يا شعبي الساكن في صهيون . يضربك بالقضيب ، ويرفع عصاه عليك على أسلوب مصر '),
(16369, 'Isaiah', 23, 10, 25, ' لأنه بعد قليل جدا يتم السخط وغضبي في إبادتهم '),
(16370, 'Isaiah', 23, 10, 26, ' ويقيم عليه رب الجنود سوطا ، كضربة مديان عند صخرة غراب ، وعصاه على البحر ، ويرفعها على أسلوب مصر '),
(16371, 'Isaiah', 23, 10, 27, ' ويكون في ذلك اليوم أن حمله يزول عن كتفك ، ونيره عن عنقك ، ويتلف النير بسبب السمانة '),
(16372, 'Isaiah', 23, 10, 28, ' قد جاء إلى عياث . عبر بمجرون . وضع في مخماش أمتعته '),
(16373, 'Isaiah', 23, 10, 29, ' عبروا المعبر . باتوا في جبع . ارتعدت الرامة . هربت جبعة شاول '),
(16374, 'Isaiah', 23, 10, 30, ' اصهلي بصوتك يا بنت جليم . اسمعي يا ليشة . مسكينة هي عناثوث '),
(16375, 'Isaiah', 23, 10, 31, ' هربت مدمينة . احتمى سكان جيبيم '),
(16376, 'Isaiah', 23, 10, 32, ' اليوم يقف في نوب . يهز يده على جبل بنت صهيون ، أكمة أورشليم '),
(16377, 'Isaiah', 23, 10, 33, ' هوذا السيد رب الجنود يقضب الأغصان برعب ، والمرتفعو القامة يقطعون ، والمتشامخون ينخفضون '),
(16378, 'Isaiah', 23, 10, 34, ' ويقطع غاب الوعر بالحديد ، ويسقط لبنان بقدير '),
(16379, 'Isaiah', 23, 11, 1, ' ويخرج قضيب من جذع يسى ، وينبت غصن من أصوله '),
(16380, 'Isaiah', 23, 11, 2, ' ويحل عليه روح الرب ، روح الحكمة والفهم ، روح المشورة والقوة ، روح المعرفة ومخافة الرب '),
(16381, 'Isaiah', 23, 11, 3, ' ولذته تكون في مخافة الرب ، فلا يقضي بحسب نظر عينيه ، ولا يحكم بحسب سمع أذنيه '),
(16382, 'Isaiah', 23, 11, 4, ' بل يقضي بالعدل للمساكين ، ويحكم بالإنصاف لبائسي الأرض ، ويضرب الأرض بقضيب فمه ، ويميت المنافق بنفخة شفتيه '),
(16383, 'Isaiah', 23, 11, 5, ' ويكون البر منطقه متنيه ، والأمانة منطقة حقويه '),
(16384, 'Isaiah', 23, 11, 6, ' فيسكن الذئب مع الخروف ، ويربض النمر مع الجدي ، والعجل والشبل والمسمن معا ، وصبي صغير يسوقها '),
(16385, 'Isaiah', 23, 11, 7, ' والبقرة والدبة ترعيان . تربض أولادهما معا ، والأسد كالبقر يأكل تبنا '),
(16386, 'Isaiah', 23, 11, 8, ' ويلعب الرضيع على سرب الصل ، ويمد الفطيم يده على جحر الأفعوان '),
(16387, 'Isaiah', 23, 11, 9, ' لا يسوؤون ولا يفسدون في كل جبل قدسي ، لأن الأرض تمتلئ من معرفة الرب كما تغطي المياه البحر '),
(16388, 'Isaiah', 23, 11, 10, ' ويكون في ذلك اليوم أن أصل يسى القائم راية للشعوب ، إياه تطلب الأمم ، ويكون محله مجدا '),
(16389, 'Isaiah', 23, 11, 11, ' ويكون في ذلك اليوم أن السيد يعيد يده ثانية ليقتني بقية شعبه ، التي بقيت ، من أشور ، ومن مصر ، ومن فتروس ، ومن كوش ، ومن عيلام ، ومن شنعار ، ومن حماة ، ومن جزائر البحر '),
(16390, 'Isaiah', 23, 11, 12, ' ويرفع راية للأمم ، ويجمع منفيي إسرائيل ، ويضم مشتتي يهوذا من أربعة أطراف الأرض '),
(16391, 'Isaiah', 23, 11, 13, ' فيزول حسد أفرايم ، وينقرض المضايقون من يهوذا . أفرايم لا يحسد يهوذا ، ويهوذا لا يضايق أفرايم '),
(16392, 'Isaiah', 23, 11, 14, ' وينقضان على أكتاف الفلسطينيين غربا ، وينهبون بني المشرق معا . يكون على أدوم وموآب امتداد يدهما ، وبنو عمون في طاعتهما '),
(16393, 'Isaiah', 23, 11, 15, ' ويبيد الرب لسان بحر مصر ، ويهز يده على النهر بقوة ريحه ، ويضربه إلى سبع سواق ، ويجيز فيها بالأحذية '),
(16394, 'Isaiah', 23, 11, 16, ' وتكون سكة لبقية شعبه التي بقيت من أشور ، كما كان لإسرائيل يوم صعوده من أرض مصر '),
(16395, 'Isaiah', 23, 12, 1, ' وتقول في ذلك اليوم : أحمدك يارب ، لأنه إذ غضبت علي ارتد غضبك فتعزيني '),
(16396, 'Isaiah', 23, 12, 2, ' هوذا الله خلاصي فأطمئن ولا أرتعب ، لأن ياه يهوه قوتي وترنيمتي وقد صار لي خلاصا '),
(16397, 'Isaiah', 23, 12, 3, ' فتستقون مياها بفرح من ينابيع الخلاص '),
(16398, 'Isaiah', 23, 12, 4, ' وتقولون في ذلك اليوم : احمدوا الرب . ادعوا باسمه . عرفوا بين الشعوب بأفعاله . ذكروا بأن اسمه قد تعالى '),
(16399, 'Isaiah', 23, 12, 5, ' رنموا للرب لأنه قد صنع مفتخرا . ليكن هذا معروفا في كل الأرض '),
(16400, 'Isaiah', 23, 12, 6, ' صوتي واهتفي يا ساكنة صهيون ، لأن قدوس إسرائيل عظيم في وسطك '),
(16401, 'Isaiah', 23, 13, 1, ' وحي من جهة بابل رآه إشعياء بن آموص '),
(16402, 'Isaiah', 23, 13, 2, ' أقيموا راية على جبل أقرع . ارفعوا صوتا إليهم . أشيروا باليد ليدخلوا أبواب العتاة '),
(16403, 'Isaiah', 23, 13, 3, ' أنا أوصيت مقدسي ، ودعوت أبطالي لأجل غضبي ، مفتخري عظمتي '),
(16404, 'Isaiah', 23, 13, 4, ' صوت جمهور على الجبال شبه قوم كثيرين . صوت ضجيج ممالك أمم مجتمعة . رب الجنود يعرض جيش الحرب '),
(16405, 'Isaiah', 23, 13, 5, ' يأتون من أرض بعيدة ، من أقصى السماوات ، الرب وأدوات سخطه ليخرب كل الأرض '),
(16406, 'Isaiah', 23, 13, 6, ' ولولوا لأن يوم الرب قريب ، قادم كخراب من القادر على كل شيء '),
(16407, 'Isaiah', 23, 13, 7, ' لذلك ترتخي كل الأيادي ، ويذوب كل قلب إنسان '),
(16408, 'Isaiah', 23, 13, 8, ' فيرتاعون . تأخذهم أوجاع ومخاض . يتلوون كوالدة . يبهتون بعضهم إلى بعض . وجوههم وجوه لهيب '),
(16409, 'Isaiah', 23, 13, 9, ' هوذا يوم الرب قادم ، قاسيا بسخط وحمو غضب ، ليجعل الأرض خرابا ويبيد منها خطاتها '),
(16410, 'Isaiah', 23, 13, 10, ' فإن نجوم السماوات وجبابرتها لا تبرز نورها . تظلم الشمس عند طلوعها ، والقمر لا يلمع بضوئه '),
(16411, 'Isaiah', 23, 13, 11, ' وأعاقب المسكونة على شرها ، والمنافقين على إثمهم ، وأبطل تعظم المستكبرين ، وأضع تجبر العتاة '),
(16412, 'Isaiah', 23, 13, 12, ' وأجعل الرجل أعز من الذهب الإبريز ، والإنسان أعز من ذهب أوفير '),
(16413, 'Isaiah', 23, 13, 13, ' لذلك أزلزل السماوات وتتزعزع الأرض من مكانها في سخط رب الجنود وفي يوم حمو غضبه '),
(16414, 'Isaiah', 23, 13, 14, ' ويكونون كظبي طريد ، وكغنم بلا من يجمعها . يلتفتون كل واحد إلى شعبه ، ويهربون كل واحد إلى أرضه '),
(16415, 'Isaiah', 23, 13, 15, ' كل من وجد يطعن ، وكل من انحاش يسقط بالسيف '),
(16416, 'Isaiah', 23, 13, 16, ' وتحطم أطفالهم أمام عيونهم ، وتنهب بيوتهم وتفضح نساؤهم '),
(16417, 'Isaiah', 23, 13, 17, ' هأنذا أهيج عليهم الماديين الذين لا يعتدون بالفضة ، ولا يسرون بالذهب '),
(16418, 'Isaiah', 23, 13, 18, ' فتحطم القسي الفتيان ، ولا يرحمون ثمرة البطن . لا تشفق عيونهم على الأولاد '),
(16419, 'Isaiah', 23, 13, 19, ' وتصير بابل ، بهاء الممالك وزينة فخر الكلدانيين ، كتقليب الله سدوم وعمورة '),
(16420, 'Isaiah', 23, 13, 20, ' لا تعمر إلى الأبد ، ولا تسكن إلى دور فدور ، ولا يخيم هناك أعرابي ، ولا يربض هناك رعاة '),
(16421, 'Isaiah', 23, 13, 21, ' بل تربض هناك وحوش القفر ، ويملأ البوم بيوتهم ، وتسكن هناك بنات النعام ، وترقص هناك معز الوحش '),
(16422, 'Isaiah', 23, 13, 22, ' وتصيح بنات آوى في قصورهم ، والذئاب في هياكل التنعم ، ووقتها قريب المجيء وأيامها لا تطول '),
(16423, 'Isaiah', 23, 14, 1, ' لأن الرب سيرحم يعقوب ويختار أيضا إسرائيل ، ويريحهم في أرضهم ، فتقترن بهم الغرباء وينضمون إلى بيت يعقوب '),
(16424, 'Isaiah', 23, 14, 2, ' ويأخذهم شعوب ويأتون بهم إلى موضعهم ، ويمتلكهم بيت إسرائيل في أرض الرب عبيدا وإماء ، ويسبون الذين سبوهم ويتسلطون على ظالميهم '),
(16425, 'Isaiah', 23, 14, 3, ' ويكون في يوم يريحك الرب من تعبك ومن انزعاجك ، ومن العبودية القاسية التي استعبدت بها '),
(16426, 'Isaiah', 23, 14, 4, ' أنك تنطق بهذا الهجو على ملك بابل وتقول : كيف باد الظالم ، بادت المغطرسة '),
(16427, 'Isaiah', 23, 14, 5, ' قد كسر الرب عصا الأشرار ، قضيب المتسلطين '),
(16428, 'Isaiah', 23, 14, 6, ' الضارب الشعوب بسخط ، ضربة بلا فتور . المتسلط بغضب على الأمم ، باضطهاد بلا إمساك '),
(16429, 'Isaiah', 23, 14, 7, ' استراحت ، اطمأنت كل الأرض . هتفوا ترنما '),
(16430, 'Isaiah', 23, 14, 8, ' حتى السرو يفرح عليك ، وأرز لبنان قائلا : منذ اضطجعت لم يصعد علينا قاطع '),
(16431, 'Isaiah', 23, 14, 9, ' الهاوية من أسفل مهتزة لك ، لاستقبال قدومك ، منهضة لك الأخيلة ، جميع عظماء الأرض . أقامت كل ملوك الأمم عن كراسيهم '),
(16432, 'Isaiah', 23, 14, 10, ' كلهم يجيبون ويقولون لك : أأنت أيضا قد ضعفت نظيرنا وصرت مثلنا '),
(16433, 'Isaiah', 23, 14, 11, ' أهبط إلى الهاوية فخرك ، رنة أعوادك . تحتك تفرش الرمة ، وغطاؤك الدود '),
(16434, 'Isaiah', 23, 14, 12, ' كيف سقطت من السماء يا زهرة ، بنت الصبح ؟ كيف قطعت إلى الأرض يا قاهر الأمم '),
(16435, 'Isaiah', 23, 14, 13, ' وأنت قلت في قلبك : أصعد إلى السماوات . أرفع كرسيي فوق كواكب الله ، وأجلس على جبل الاجتماع في أقاصي الشمال '),
(16436, 'Isaiah', 23, 14, 14, ' أصعد فوق مرتفعات السحاب . أصير مثل العلي '),
(16437, 'Isaiah', 23, 14, 15, ' لكنك انحدرت إلى الهاوية ، إلى أسافل الجب '),
(16438, 'Isaiah', 23, 14, 16, ' الذين يرونك يتطلعون إليك ، يتأملون فيك . أهذا هو الرجل الذي زلزل الأرض وزعزع الممالك '),
(16439, 'Isaiah', 23, 14, 17, ' الذي جعل العالم كقفر ، وهدم مدنه ، الذي لم يطلق أسراه إلى بيوتهم '),
(16440, 'Isaiah', 23, 14, 18, ' كل ملوك الأمم بأجمعهم اضطجعوا بالكرامة كل واحد في بيته '),
(16441, 'Isaiah', 23, 14, 19, ' وأما أنت فقد طرحت من قبرك كغصن أشنع ، كلباس القتلى المضروبين بالسيف ، الهابطين إلى حجارة الجب ، كجثة مدوسة '),
(16442, 'Isaiah', 23, 14, 20, ' لا تتحد بهم في القبر لأنك أخربت أرضك ، قتلت شعبك . لا يسمى إلى الأبد نسل فاعلي الشر '),
(16443, 'Isaiah', 23, 14, 21, ' هيئوا لبنيه قتلا بإثم آبائهم ، فلا يقوموا ولا يرثوا الأرض ولا يملأوا وجه العالم مدنا '),
(16444, 'Isaiah', 23, 14, 22, ' فأقوم عليهم ، يقول رب الجنود . وأقطع من بابل اسما وبقية ونسلا وذرية ، يقول الرب '),
(16445, 'Isaiah', 23, 14, 23, ' وأجعلها ميراثا للقنفذ ، وآجام مياه ، وأكنسها بمكنسة الهلاك ، يقول رب الجنود '),
(16446, 'Isaiah', 23, 14, 24, ' قد حلف رب الجنود قائلا : إنه كما قصدت يصير ، وكما نويت يثبت '),
(16447, 'Isaiah', 23, 14, 25, ' أن أحطم أشور في أرضي وأدوسه على جبالي ، فيزول عنهم نيره ، ويزول عن كتفهم حمله '),
(16448, 'Isaiah', 23, 14, 26, ' هذا هو القضاء المقضي به على كل الأرض ، وهذه هي اليد الممدودة على كل الأمم '),
(16449, 'Isaiah', 23, 20, 1, ' في سنة مجيء ترتان إلى أشدود ، حين أرسله سرجون ملك أشور فحارب أشدود وأخذها '),
(16450, 'Isaiah', 23, 20, 2, ' في ذلك الوقت تكلم الرب عن يد إشعياء بن آموص قائلا : اذهب وحل المسح عن حقويك واخلع حذاءك عن رجليك . ففعل هكذا ومشى معرى وحافيا '),
(16451, 'Isaiah', 23, 20, 3, ' فقال الرب : كما مشى عبدي إشعياء معرى وحافيا ثلاث سنين ، آية وأعجوبة على مصر وعلى كوش '),
(16452, 'Isaiah', 23, 20, 4, ' هكذا يسوق ملك أشور سبي مصر وجلاء كوش ، الفتيان والشيوخ ، عراة وحفاة ومكشوفي الأستاه خزيا لمصر '),
(16453, 'Isaiah', 23, 20, 5, ' فيرتاعون ويخجلون من أجل كوش رجائهم ، ومن أجل مصر فخرهم '),
(16454, 'Isaiah', 23, 20, 6, ' ويقول ساكن هذا الساحل في ذلك اليوم : هوذا هكذا ملجأنا الذي هربنا إليه للمعونة لننجو من ملك أشور ، فكيف نسلم نحن '),
(16455, 'Isaiah', 23, 21, 1, ' وحي من جهة برية البحر : كزوابع في الجنوب عاصفة ، يأتي من البرية من أرض مخوفة '),
(16456, 'Isaiah', 23, 21, 2, ' قد أعلنت لي رؤيا قاسية : الناهب ناهبا والمخرب مخربا . اصعدي يا عيلام . حاصري يا مادي . قد أبطلت كل أنينها '),
(16457, 'Isaiah', 23, 21, 3, ' لذلك امتلأت حقواي وجعا ، وأخذني مخاض كمخاض الوالدة . تلويت حتى لا أسمع . اندهشت حتى لا أنظر '),
(16458, 'Isaiah', 23, 21, 4, ' تاه قلبي . بغتني رعب . ليلة لذتي جعلها لي رعدة '),
(16459, 'Isaiah', 23, 21, 5, ' يرتبون المائدة ، يحرسون الحراسة ، يأكلون . يشربون . قوموا أيها الرؤساء امسحوا المجن '),
(16460, 'Isaiah', 23, 21, 6, ' لأنه هكذا قال لي السيد : اذهب أقم الحارس . ليخبر بما يرى '),
(16461, 'Isaiah', 23, 21, 7, ' فرأى ركابا أزواج فرسان . ركاب حمير . ركاب جمال . فأصغى إصغاء شديدا '),
(16462, 'Isaiah', 23, 21, 8, ' ثم صرخ كأسد : أيها السيد ، أنا قائم على المرصد دائما في النهار ، وأنا واقف على المحرس كل الليالي '),
(16463, 'Isaiah', 23, 21, 9, ' وهوذا ركاب من الرجال . أزواج من الفرسان . فأجاب وقال : سقطت ، سقطت بابل ، وجميع تماثيل آلهتها المنحوتة كسرها إلى الأرض '),
(16464, 'Isaiah', 23, 21, 10, ' يا دياستي وبني بيدري ما سمعته من رب الجنود إله إسرائيل أخبرتكم به '),
(16465, 'Isaiah', 23, 21, 11, ' وحي من جهة دومة : صرخ إلي صارخ من سعير : يا حارس ، ما من الليل ؟ يا حارس ، ما من الليل '),
(16466, 'Isaiah', 23, 21, 12, ' قال الحارس : أتى صباح وأيضا ليل . إن كنتم تطلبون فاطلبوا . ارجعوا ، تعالوا '),
(16467, 'Isaiah', 23, 21, 13, ' وحي من جهة بلاد العرب : في الوعر في بلاد العرب تبيتين ، يا قوافل الددانيين '),
(16468, 'Isaiah', 23, 21, 14, ' هاتوا ماء لملاقاة العطشان ، يا سكان أرض تيماء . وافوا الهارب بخبزه '),
(16469, 'Isaiah', 23, 21, 15, ' فإنهم من أمام السيوف قد هربوا . من أمام السيف المسلول ، ومن أمام القوس المشدودة ، ومن أمام شدة الحرب '),
(16470, 'Isaiah', 23, 21, 16, ' فإنه هكذا قال لي السيد : في مدة سنة كسنة الأجير يفنى كل مجد قيدار '),
(16471, 'Isaiah', 23, 21, 17, ' وبقية عدد قسي أبطال بني قيدار تقل ، لأن الرب إله إسرائيل قد تكلم ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(16472, 'Isaiah', 23, 22, 1, ' وحي من جهة وادي الرؤيا : فما لك أنك صعدت جميعا على السطوح '),
(16473, 'Isaiah', 23, 22, 2, ' يا ملآنة من الجلبة ، المدينة العجاجة ، القرية المفتخرة ؟ قتلاك ليس هم قتلى السيف ولا موتى الحرب '),
(16474, 'Isaiah', 23, 22, 3, ' جميع رؤسائك هربوا معا . أسروا بالقسي . كل الموجودين بك أسروا معا . من بعيد فروا '),
(16475, 'Isaiah', 23, 22, 4, ' لذلك قلت : اقتصروا عني ، فأبكي بمرارة . لا تلحوا بتعزيتي عن خراب بنت شعبي '),
(16476, 'Isaiah', 23, 22, 5, ' إن للسيد رب الجنود في وادي الرؤيا يوم شغب ودوس وارتباك . نقب سور وصراخ إلى الجبل '),
(16477, 'Isaiah', 23, 22, 6, ' فعيلام قد حملت الجعبة بمركبات رجال فرسان ، وقير قد كشفت المجن '),
(16478, 'Isaiah', 23, 22, 7, ' فتكون أفضل أوديتك ملآنة مركبات ، والفرسان تصطف اصطفافا نحو الباب '),
(16479, 'Isaiah', 23, 22, 8, ' ويكشف ستر يهوذا ، فتنظر في ذلك اليوم إلى أسلحة بيت الوعر '),
(16480, 'Isaiah', 23, 22, 9, ' ورأيتم شقوق مدينة داود أنها صارت كثيرة ، وجمعتم مياه البركة السفلى '),
(16481, 'Isaiah', 23, 22, 10, ' وعددتم بيوت أورشليم وهدمتم البيوت لتحصين السور '),
(16482, 'Isaiah', 23, 22, 11, ' وصنعتم خندقا بين السورين لمياه البركة العتيقة . لكن لم تنظروا إلى صانعه ، ولم تروا مصوره من قديم '),
(16483, 'Isaiah', 23, 22, 12, ' ودعا السيد رب الجنود في ذلك اليوم إلى البكاء والنوح والقرعة والتنطق بالمسح '),
(16484, 'Isaiah', 23, 22, 13, ' فهوذا بهجة وفرح ، ذبح بقر ونحر غنم ، أكل لحم وشرب خمر لنأكل ونشرب ، لأننا غدا نموت '),
(16485, 'Isaiah', 23, 22, 14, ' فأعلن في أذني رب الجنود : لا يغفرن لكم هذا الإثم حتى تموتوا ، يقول السيد رب الجنود '),
(16486, 'Isaiah', 23, 22, 15, ' هكذا قال السيد رب الجنود : اذهب ادخل إلى هذا جليس الملك ، إلى شبنا الذي على البيت '),
(16487, 'Isaiah', 23, 22, 16, ' ما لك ههنا ؟ ومن لك ههنا حتى نقرت لنفسك ههنا قبرا أيها الناقر في العلو قبره ، الناحت لنفسه في الصخر مسكنا '),
(16488, 'Isaiah', 23, 22, 17, ' هوذا الرب يطرحك طرحا يا رجل ، ويغطيك تغطية '),
(16489, 'Isaiah', 23, 22, 18, ' يلفك لف لفيفة كالكرة إلى أرض واسعة الطرفين . هناك تموت ، وهناك تكون مركبات مجدك ، يا خزي بيت سيدك '),
(16490, 'Isaiah', 23, 22, 19, ' وأطردك من منصبك ، ومن مقامك يحطك '),
(16491, 'Isaiah', 23, 22, 20, ' ويكون في ذلك اليوم أني أدعو عبدي ألياقيم بن حلقيا '),
(16492, 'Isaiah', 23, 22, 21, ' وألبسه ثوبك ، وأشده بمنطقتك ، وأجعل سلطانك في يده ، فيكون أبا لسكان أورشليم ولبيت يهوذا '),
(16493, 'Isaiah', 23, 22, 22, ' وأجعل مفتاح بيت داود على كتفه ، فيفتح وليس من يغلق ، ويغلق وليس من يفتح '),
(16494, 'Isaiah', 23, 22, 23, ' وأثبته وتدا في موضع أمين ، ويكون كرسي مجد لبيت أبيه '),
(16495, 'Isaiah', 23, 22, 24, ' ويعلقون عليه كل مجد بيت أبيه ، الفروع والقضبان ، كل آنية صغيرة من آنية الطسوس إلى آنية القناني جميعا '),
(16496, 'Isaiah', 23, 22, 25, ' في ذلك اليوم ، يقول رب الجنود ، يزول الوتد المثبت في موضع أمين ويقطع ويسقط . ويباد الثقل الذي عليه ، لأن الرب قد تكلم '),
(16497, 'Isaiah', 23, 23, 1, ' وحي من جهة صور : ولولي يا سفن ترشيش ، لأنها خربت حتى ليس بيت حتى ليس مدخل . من أرض كتيم أعلن لهم '),
(16498, 'Isaiah', 23, 23, 2, ' اندهشوا يا سكان الساحل . تجار صيدون العابرون البحر ملأوك '),
(16499, 'Isaiah', 23, 23, 3, ' وغلتها ، زرع شيحور ، حصاد النيل ، على مياه كثيرة فصارت متجرة لأمم '),
(16500, 'Isaiah', 23, 23, 4, ' اخجلي يا صيدون لأن البحر ، حصن البحر ، نطق قائلا : لم أتمخض ولا ولدت ولا ربيت شبابا ولا نشأت عذارى '),
(16501, 'Isaiah', 23, 23, 5, ' عند وصول الخبر إلى مصر ، يتوجعون ، عند وصول خبر صور '),
(16502, 'Isaiah', 23, 23, 6, ' اعبروا إلى ترشيش . ولولوا يا سكان الساحل '),
(16503, 'Isaiah', 23, 23, 7, ' أهذه لكم المفتخرة التي منذ الأيام القديمة قدمها ؟ تنقلها رجلاها بعيدا للتغرب '),
(16504, 'Isaiah', 23, 23, 8, ' من قضى بهذا على صور المتوجة التي تجارها رؤساء ؟ متسببوها موقرو الأرض '),
(16505, 'Isaiah', 23, 23, 9, ' رب الجنود قضى به ليدنس كبرياء كل مجد ، ويهين كل موقري الأرض '),
(16506, 'Isaiah', 23, 23, 10, ' اجتازي أرضك كالنيل يا بنت ترشيش . ليس حصر في ما بعد '),
(16507, 'Isaiah', 23, 23, 11, ' مد يده على البحر . أرعد ممالك . أمر الرب من جهة كنعان أن تخرب حصونها '),
(16508, 'Isaiah', 23, 23, 12, ' وقال : لا تعودين تفتخرين أيضا أيتها المنهتكة ، العذراء بنت صيدون . قومي إلى كتيم . اعبري . هناك أيضا لا راحة لك '),
(16509, 'Isaiah', 23, 23, 13, ' هوذا أرض الكلدانيين . هذا الشعب لم يكن . أسسها أشور لأهل البرية . قد أقاموا أبراجهم . دمروا قصورها . جعلها ردما '),
(16510, 'Isaiah', 23, 23, 14, ' ولولي يا سفن ترشيش لأن حصنك قد أخرب '),
(16511, 'Isaiah', 23, 23, 15, ' ويكون في ذلك اليوم أن صور تنسى سبعين سنة كأيام ملك واحد . من بعد سبعين سنة يكون لصور كأغنية الزانية '),
(16512, 'Isaiah', 23, 23, 16, ' خذي عودا . طوفي في المدينة أيتها الزانية المنسية . أحسني العزف ، أكثري الغناء لكي تذكري '),
(16513, 'Isaiah', 23, 23, 17, ' ويكون من بعد سبعين سنة أن الرب يتعهد صور فتعود إلى أجرتها ، وتزني مع كل ممالك البلاد على وجه الأرض '),
(16514, 'Isaiah', 23, 23, 18, ' وتكون تجارتها وأجرتها قدسا للرب . لا تخزن ولا تكنز ، بل تكون تجارتها للمقيمين أمام الرب ، لأكل إلى الشبع وللباس فاخر '),
(16515, 'Isaiah', 23, 24, 1, ' هوذا الرب يخلي الأرض ويفرغها ويقلب وجهها ويبدد سكانها '),
(16516, 'Isaiah', 23, 24, 2, ' وكما يكون الشعب هكذا الكاهن . كما العبد هكذا سيده . كما الأمة هكذا سيدتها . كما الشاري هكذا البائع . كما المقرض هكذا المقترض . وكما الدائن هكذا المديون '),
(16517, 'Isaiah', 23, 24, 3, ' تفرغ الأرض إفراغا وتنهب نهبا ، لأن الرب قد تكلم بهذا القول '),
(16518, 'Isaiah', 23, 24, 4, ' ناحت ذبلت الأرض . حزنت ذبلت المسكونة . حزن مرتفعو شعب الأرض '),
(16519, 'Isaiah', 23, 24, 5, ' والأرض تدنست تحت سكانها لأنهم تعدوا الشرائع ، غيروا الفريضة ، نكثوا العهد الأبدي '),
(16520, 'Isaiah', 23, 24, 6, ' لذلك لعنة أكلت الأرض وعوقب الساكنون فيها . لذلك احترق سكان الأرض وبقي أناس قلائل '),
(16521, 'Isaiah', 23, 24, 7, ' ناح المسطار ، ذبلت الكرمة ، أن كل مسروري القلوب '),
(16522, 'Isaiah', 23, 24, 8, ' بطل فرح الدفوف ، انقطع ضجيج المبتهجين ، بطل فرح العود '),
(16523, 'Isaiah', 23, 24, 9, ' لا يشربون خمرا بالغناء . يكون المسكر مرا لشاربيه '),
(16524, 'Isaiah', 23, 31, 4, ' لأنه هكذا قال لي الرب : كما يهر فوق فريسته الأسد والشبل الذي يدعى عليه جماعة من الرعاة وهو لا يرتاع من صوتهم ولا يتذلل لجمهورهم ، هكذا ينزل رب الجنود للمحاربة عن جبل صهيون وعن أكمتها '),
(16525, 'Isaiah', 23, 31, 5, ' كطيور مرفة هكذا يحامي رب الجنود عن أورشليم . يحامي فينقذ . يعفو فينجي '),
(16526, 'Isaiah', 23, 31, 6, ' ارجعوا إلى الذي ارتد بنو إسرائيل عنه متعمقين '),
(16527, 'Isaiah', 23, 31, 7, ' لأن في ذلك اليوم يرفضون كل واحد أوثان فضته وأوثان ذهبه التي صنعتها لكم أيديكم خطيئة '),
(16528, 'Isaiah', 23, 31, 8, ' ويسقط أشور بسيف غير رجل ، وسيف غير إنسان يأكله ، فيهرب من أمام السيف ، ويكون مختاروه تحت الجزية '),
(16529, 'Isaiah', 23, 31, 9, ' وصخره من الخوف يزول ، ومن الراية يرتعب رؤساؤه ، يقول الرب الذي له نار في صهيون ، وله تنور في أورشليم '),
(16530, 'Isaiah', 23, 32, 1, ' هوذا بالعدل يملك ملك ، ورؤساء بالحق يترأسون '),
(16531, 'Isaiah', 23, 32, 2, ' ويكون إنسان كمخبأ من الريح وستارة من السيل ، كسواقي ماء في مكان يابس ، كظل صخرة عظيمة في أرض معيية '),
(16532, 'Isaiah', 23, 32, 3, ' ولا تحسر عيون الناظرين ، وآذان السامعين تصغى '),
(16533, 'Isaiah', 23, 32, 4, ' وقلوب المتسرعين تفهم علما ، وألسنة العييين تبادر إلى التكلم فصيحا '),
(16534, 'Isaiah', 23, 32, 5, ' ولا يدعى اللئيم بعد كريما ، ولا الماكر يقال له نبيل '),
(16535, 'Isaiah', 23, 32, 6, ' لأن اللئيم يتكلم باللؤم ، وقلبه يعمل إثما ليصنع نفاقا ، ويتكلم على الرب بافتراء ، ويفرغ نفس الجائع ويقطع شرب العطشان '),
(16536, 'Isaiah', 23, 32, 7, ' والماكر آلاته رديئة . هو يتآمر بالخبائث ليهلك البائسين بأقوال الكذب ، حتى في تكلم المسكين بالحق '),
(16537, 'Isaiah', 23, 32, 8, ' وأما الكريم فبالكرائم يتآمر ، وهو بالكرائم يقوم '),
(16538, 'Isaiah', 23, 32, 9, ' أيتها النساء المطمئنات ، قمن اسمعن صوتي . أيتها البنات الواثقات ، اصغين لقولي '),
(16539, 'Isaiah', 23, 32, 10, ' أياما على سنة ترتعدن أيتها الواثقات ، لأنه قد مضى القطاف . الاجتناء لا يأتي '),
(16540, 'Isaiah', 23, 32, 11, ' ارتجفن أيتها المطمئنات . ارتعدن أيتها الواثقات . تجردن وتعرين وتنطقن على الأحقاء '),
(16541, 'Isaiah', 23, 32, 12, ' لاطمات على الثدي من أجل الحقول المشتهاة ، ومن أجل الكرمة المثمرة '),
(16542, 'Isaiah', 23, 32, 13, ' على أرض شعبي يطلع شوك وحسك حتى في كل بيوت الفرح من المدينة المبتهجة '),
(16543, 'Isaiah', 23, 32, 14, ' لأن القصر قد هدم . جمهور المدينة قد ترك . الأكمة والبرج صارا مغاير إلى الأبد ، مرحا لحمير الوحش ، مرعى للقطعان '),
(16544, 'Isaiah', 23, 32, 15, ' إلى أن يسكب علينا روح من العلاء ، فتصير البرية بستانا ، ويحسب البستان وعرا '),
(16545, 'Isaiah', 23, 32, 16, ' فيسكن في البرية الحق ، والعدل في البستان يقيم '),
(16546, 'Isaiah', 23, 32, 17, ' ويكون صنع العدل سلاما ، وعمل العدل سكونا وطمأنينة إلى الأبد '),
(16547, 'Isaiah', 23, 32, 18, ' ويسكن شعبي في مسكن السلام ، وفي مساكن مطمئنة وفي محلات أمينة '),
(16548, 'Isaiah', 23, 32, 19, ' وينزل برد بهبوط الوعر ، وإلى الحضيض توضع المدينة '),
(16549, 'Isaiah', 23, 32, 20, ' طوباكم أيها الزارعون على كل المياه ، المسرحون أرجل الثور والحمار '),
(16550, 'Isaiah', 23, 33, 1, ' ويل لك أيها المخرب وأنت لم تخرب ، وأيها الناهب ولم ينهبوك . حين تنتهي من التخريب تخرب ، وحين تفرغ من النهب ينهبونك '),
(16551, 'Isaiah', 23, 33, 2, ' يارب ، تراءف علينا . إياك انتظرنا . كن عضدهم في الغدوات . خلاصنا أيضا في وقت الشدة '),
(16552, 'Isaiah', 23, 33, 3, ' من صوت الضجيج هربت الشعوب . من ارتفاعك تبددت الأمم '),
(16553, 'Isaiah', 23, 33, 4, ' ويجنى سلبكم جنى الجراد . كتراكض الجندب يتراكض عليه '),
(16554, 'Isaiah', 23, 33, 5, ' تعالى الرب لأنه ساكن في العلاء . ملأ صهيون حقا وعدلا '),
(16555, 'Isaiah', 23, 33, 6, ' فيكون أمان أوقاتك وفرة خلاص وحكمة ومعرفة . مخافة الرب هي كنزه '),
(16556, 'Isaiah', 23, 33, 7, ' هوذا أبطالهم قد صرخوا خارجا . رسل السلام يبكون بمرارة '),
(16557, 'Isaiah', 23, 33, 8, ' خلت السكك . باد عابر السبيل . نكث العهد . رذل المدن . لم يعتد بإنسان '),
(16558, 'Isaiah', 23, 33, 9, ' ناحت ، ذبلت الأرض . خجل لبنان وتلف . صار شارون كالبادية . نثر باشان وكرمل '),
(16559, 'Isaiah', 23, 33, 10, ' الآن أقوم ، يقول الرب . الآن أصعد . الآن أرتفع '),
(16560, 'Isaiah', 23, 33, 11, ' تحبلون بحشيش ، تلدون قشيشا . نفسكم نار تأكلكم '),
(16561, 'Isaiah', 23, 33, 12, ' وتصير الشعوب وقود كلس ، أشواكا مقطوعة تحرق بالنار '),
(16562, 'Isaiah', 23, 33, 13, ' اسمعوا أيها البعيدون ما صنعت ، واعرفوا أيها القريبون بطشي '),
(16563, 'Isaiah', 23, 33, 14, ' ارتعب في صهيون الخطاة . أخذت الرعدة المنافقين : من منا يسكن في نار آكلة ؟ من منا يسكن في وقائد أبدية '),
(16564, 'Isaiah', 23, 33, 15, ' السالك بالحق والمتكلم بالاستقامة ، الراذل مكسب المظالم ، النافض يديه من قبض الرشوة ، الذي يسد أذنيه عن سمع الدماء ، ويغمض عينيه عن النظر إلى الشر '),
(16565, 'Isaiah', 23, 33, 16, ' هو في الأعالي يسكن . حصون الصخور ملجأه . يعطى خبزه ، ومياهه مأمونة '),
(16566, 'Isaiah', 23, 33, 17, ' الملك ببهائه تنظر عيناك . تريان أرضا بعيدة '),
(16567, 'Isaiah', 23, 33, 18, ' قلبك يتذكر الرعب : أين الكاتب ؟ أين الجابي ؟ أين الذي عد الأبراج '),
(16568, 'Isaiah', 23, 33, 19, ' الشعب الشرس لا ترى . الشعب الغامض اللغة عن الإدراك ، العيي بلسان لا يفهم '),
(16569, 'Isaiah', 23, 33, 20, ' انظر صهيون مدينة أعيادنا . عيناك تريان أورشليم مسكنا مطمئنا ، خيمة لا تنتقل ، لا تقلع أوتادها إلى الأبد ، وشيء من أطنابها لا ينقطع '),
(16570, 'Isaiah', 23, 33, 21, ' بل هناك الرب العزيز لنا مكان أنهار وترع واسعة الشواطئ . لا يسير فيها قارب بمقذاف ، وسفينة عظيمة لا تجتاز فيها '),
(16571, 'Isaiah', 23, 33, 22, ' فإن الرب قاضينا . الرب شارعنا . الرب ملكنا هو يخلصنا '),
(16572, 'Isaiah', 23, 33, 23, ' ارتخت حبالك . لا يشددون قاعدة ساريتهم . لا ينشرون قلعا . حينئذ قسم سلب غنيمة كثيرة . العرج نهبوا نهبا '),
(16573, 'Isaiah', 23, 33, 24, ' ولا يقول ساكن : أنا مرضت . الشعب الساكن فيها مغفور الإثم '),
(16574, 'Isaiah', 23, 34, 1, ' اقتربوا أيها الأمم لتسمعوا ، وأيها الشعوب اصغوا . لتسمع الأرض وملؤها . المسكونة وكل نتائجها '),
(16575, 'Isaiah', 23, 34, 2, ' لأن للرب سخطا على كل الأمم ، وحموا على كل جيشهم . قد حرمهم ، دفعهم إلى الذبح '),
(16576, 'Isaiah', 23, 34, 3, ' فقتلاهم تطرح ، وجيفهم تصعد نتانتها ، وتسيل الجبال بدمائهم '),
(16577, 'Isaiah', 23, 34, 4, ' ويفنى كل جند السماوات ، وتلتف السماوات كدرج ، وكل جندها ينتثر كانتثار الورق من الكرمة والسقاط من التينة '),
(16578, 'Isaiah', 23, 34, 5, ' لأنه قد روي في السماوات سيفي . هوذا على أدوم ينزل ، وعلى شعب حرمته للدينونة '),
(16579, 'Isaiah', 23, 34, 6, ' للرب سيف قد امتلأ دما ، اطلى بشحم ، بدم خراف وتيوس ، بشحم كلى كباش . لأن للرب ذبيحة في بصرة وذبحا عظيما في أرض أدوم '),
(16580, 'Isaiah', 23, 34, 7, ' ويسقط البقر الوحشي معها والعجول مع الثيران ، وتروى أرضهم من الدم ، وترابهم من الشحم يسمن '),
(16581, 'Isaiah', 23, 34, 8, ' لأن للرب يوم انتقام ، سنة جزاء من أجل دعوى صهيون '),
(16582, 'Isaiah', 23, 34, 9, ' وتتحول أنهارها زفتا ، وترابها كبريتا ، وتصير أرضها زفتا مشتعلا '),
(16583, 'Isaiah', 23, 34, 10, ' ليلا ونهارا لا تنطفئ . إلى الأبد يصعد دخانها . من دور إلى دور تخرب . إلى أبد الآبدين لا يكون من يجتاز فيها '),
(16584, 'Isaiah', 23, 34, 11, ' ويرثها القوق والقنفذ ، والكركي والغراب يسكنان فيها ، ويمد عليها خيط الخراب ومطمار الخلاء '),
(16585, 'Isaiah', 23, 34, 12, ' أشرافها ليس هناك من يدعونه للملك ، وكل رؤسائها يكونون عدما '),
(16586, 'Isaiah', 23, 34, 13, ' ويطلع في قصورها الشوك . القريص والعوسج في حصونها . فتكون مسكنا للذئاب ودارا لبنات النعام '),
(16587, 'Isaiah', 23, 34, 14, ' وتلاقي وحوش القفر بنات آوى ، ومعز الوحش يدعو صاحبه . هناك يستقر الليل ويجد لنفسه محلا '),
(16588, 'Isaiah', 23, 34, 15, ' هناك تحجر النكازة وتبيض وتفرخ وتربي تحت ظلها . وهناك تجتمع الشواهين بعضها ببعض '),
(16589, 'Isaiah', 23, 34, 16, ' فتشوا في سفر الرب واقرأوا . واحدة من هذه لا تفقد . لا يغادر شيء صاحبه ، لأن فمه هو قد أمر ، وروحه هو جمعها '),
(16590, 'Isaiah', 23, 34, 17, ' وهو قد ألقى لها قرعة ، ويده قسمتها لها بالخيط . إلى الأبد ترثها . إلى دور فدور تسكن فيها '),
(16591, 'Isaiah', 23, 35, 1, ' تفرح البرية والأرض اليابسة ، ويبتهج القفر ويزهر كالنرجس '),
(16592, 'Isaiah', 23, 35, 2, ' يزهر إزهارا ويبتهج ابتهاجا ويرنم . يدفع إليه مجد لبنان . بهاء كرمل وشارون . هم يرون مجد الرب ، بهاء إلهنا '),
(16593, 'Isaiah', 23, 35, 3, ' شددوا الأيادي المسترخية ، والركب المرتعشة ثبتوها '),
(16594, 'Isaiah', 23, 35, 4, ' قولوا لخائفي القلوب : تشددوا لا تخافوا . هوذا إلهكم . الانتقام يأتي . جزاء الله . هو يأتي ويخلصكم '),
(16595, 'Isaiah', 23, 35, 5, ' حينئذ تتفقح عيون العمي ، وآذان الصم تتفتح '),
(16596, 'Isaiah', 23, 35, 6, ' حينئذ يقفز الأعرج كالإيل ويترنم لسان الأخرس ، لأنه قد انفجرت في البرية مياه ، وأنهار في القفر '),
(16597, 'Isaiah', 23, 35, 7, ' ويصير السراب أجما ، والمعطشة ينابيع ماء . في مسكن الذئاب ، في مربضها دار للقصب والبردي '),
(16598, 'Isaiah', 23, 35, 8, ' وتكون هناك سكة وطريق يقال لها : الطريق المقدسة . لا يعبر فيها نجس ، بل هي لهم . من سلك في الطريق حتى الجهال ، لا يضل '),
(16599, 'Isaiah', 23, 14, 27, ' فإن رب الجنود قد قضى ، فمن يبطل ؟ ويده هي الممدودة ، فمن يردها '),
(16600, 'Isaiah', 23, 14, 28, ' في سنة وفاة الملك آحاز كان هذا الوحي '),
(16601, 'Isaiah', 23, 14, 29, ' لا تفرحي يا جميع فلسطين ، لأن القضيب الضاربك انكسر ، فإنه من أصل الحية يخرج أفعوان ، وثمرته تكون ثعبانا مسما طيارا '),
(16602, 'Isaiah', 23, 14, 30, ' وترعى أبكار المساكين ، ويربض البائسون بالأمان ، وأميت أصلك بالجوع ، فيقتل بقيتك '),
(16603, 'Isaiah', 23, 14, 31, ' ولول أيها الباب . اصرخي أيتها المدينة . قد ذاب جميعك يا فلسطين لأنه من الشمال يأتي دخان ، وليس شاذ في جيوشه '),
(16604, 'Isaiah', 23, 14, 32, ' فبماذا يجاب رسل الأمم ؟ إن الرب أسس صهيون ، وبها يحتمي بائسو شعبه '),
(16605, 'Isaiah', 23, 15, 1, ' وحي من جهة موآب : إنه في ليلة خربت عار موآب وهلكت . إنه في ليلة خربت قير موآب وهلكت '),
(16606, 'Isaiah', 23, 15, 2, ' إلى البيت وديبون يصعدون إلى المرتفعات للبكاء . تولول موآب على نبو وعلى ميدبا . في كل رأس منها قرعة . كل لحية مجزوزة '),
(16607, 'Isaiah', 23, 15, 3, ' في أزقتها يأتزرون بمسح . على سطوحها وفي ساحاتها يولول كل واحد منها سيالا بالبكاء '),
(16608, 'Isaiah', 23, 15, 4, ' وتصرخ حشبون وألعالة . يسمع صوتهما إلى ياهص . لذلك يصرخ متسلحو موآب . نفسها ترتعد فيها '),
(16609, 'Isaiah', 23, 15, 5, ' يصرخ قلبي من أجل موآب . الهاربين منها إلى صوغر كعجلة ثلاثية ، لأنهم يصعدون في عقبة اللوحيث بالبكاء ، لأنهم في طريق حورونايم يرفعون صراخ الانكسار '),
(16610, 'Isaiah', 23, 15, 6, ' لأن مياه نمريم تصير خربة ، لأن العشب يبس . الكلأ فني . الخضرة لا توجد '),
(16611, 'Isaiah', 23, 15, 7, ' لذلك الثروة التي اكتسبوها وذخائرهم يحملونها إلى عبر وادي الصفصاف '),
(16612, 'Isaiah', 23, 15, 8, ' لأن الصراخ قد أحاط بتخوم موآب . إلى أجلايم ولولتها . وإلى بئر إيليم ولولتها '),
(16613, 'Isaiah', 23, 15, 9, ' لأن مياه ديمون تمتلئ دما ، لأني أجعل على ديمون زوائد . على الناجين من موآب أسدا وعلى بقية الأرض '),
(16614, 'Isaiah', 23, 16, 1, ' أرسلوا خرفان حاكم الأرض من سالع نحو البرية إلى جبل ابنة صهيون '),
(16615, 'Isaiah', 23, 16, 2, ' ويحدث أنه كطائر تائه ، كفراخ منفرة تكون بنات موآب في معابر أرنون '),
(16616, 'Isaiah', 23, 16, 3, ' هاتي مشورة ، اصنعي إنصافا ، اجعلي ظلك كالليل في وسط الظهيرة ، استري المطرودين ، لا تظهري الهاربين '),
(16617, 'Isaiah', 23, 16, 4, ' ليتغرب عندك مطرودو موآب . كوني سترا لهم من وجه المخرب ، لأن الظالم يبيد ، وينتهي الخراب ، ويفنى عن الأرض الدائسون '),
(16618, 'Isaiah', 23, 16, 5, ' فيثبت الكرسي بالرحمة ، ويجلس عليه بالأمانة في خيمة داود قاض ، ويطلب الحق ويبادر بالعدل '),
(16619, 'Isaiah', 23, 16, 6, ' قد سمعنا بكبرياء موآب المتكبرة جدا ، عظمتها وكبريائها وصلفها بطل افتخارها '),
(16620, 'Isaiah', 23, 16, 7, ' لذلك تولول موآب . على موآب كلها يولول . تئنون على أسس قير حارسة ، إنما هي مضروبة '),
(16621, 'Isaiah', 23, 16, 8, ' لأن حقول حشبون ذبلت . كرمة سبمة كسر أمراء الأمم أفضلها . وصلت إلى يعزير . تاهت في البرية ، امتدت أغصانها ، عبرت البحر '),
(16622, 'Isaiah', 23, 16, 9, ' لذلك أبكي بكاء يعزير على كرمة سبمة . أرويكما بدموعي يا حشبون وألعالة ، لأنه على قطافك وعلى حصادك قد وقعت جلبة '),
(16623, 'Isaiah', 23, 16, 10, ' وانتزع الفرح والابتهاج من البستان ، ولا يغنى في الكروم ولا يترنم ، ولا يدوس دائس خمرا في المعاصر . أبطلت الهتاف '),
(16624, 'Isaiah', 23, 16, 11, ' لذلك ترن أحشائي كعود من أجل موآب وبطني من أجل قير حارس '),
(16625, 'Isaiah', 23, 16, 12, ' ويكون إذا ظهرت ، إذا تعبت موآب على المرتفعة ودخلت إلى مقدسها تصلي ، أنها لا تفوز '),
(16626, 'Isaiah', 23, 16, 13, ' هذا هو الكلام الذي كلم به الرب موآب منذ زمان '),
(16627, 'Isaiah', 23, 16, 14, ' والآن تكلم الرب قائلا : في ثلاث سنين كسني الأجير يهان مجد موآب بكل الجمهور العظيم ، وتكون البقية قليلة صغيرة لا كبيرة '),
(16628, 'Isaiah', 23, 17, 1, ' وحي من جهة دمشق : هوذا دمشق تزال من بين المدن وتكون رجمة ردم '),
(16629, 'Isaiah', 23, 17, 2, ' مدن عروعير متروكة . تكون للقطعان ، فتربض وليس من يخيف '),
(16630, 'Isaiah', 23, 17, 3, ' ويزول الحصن من أفرايم والملك من دمشق وبقية أرام . فتصير كمجد بني إسرائيل ، يقول رب الجنود '),
(16631, 'Isaiah', 23, 17, 4, ' ويكون في ذلك اليوم أن مجد يعقوب يذل ، وسمانة لحمه تهزل '),
(16632, 'Isaiah', 23, 17, 5, ' ويكون كجمع الحصادين الزرع ، وذراعه تحصد السنابل ، ويكون كمن يلقط سنابل في وادي رفايم '),
(16633, 'Isaiah', 23, 17, 6, ' وتبقى فيه خصاصة كنفض زيتونة ، حبتان أو ثلاث في رأس الفرع ، وأربع أو خمس في أفنان المثمرة ، يقول الرب إله إسرائيل '),
(16634, 'Isaiah', 23, 17, 7, ' في ذلك اليوم يلتفت الإنسان إلى صانعه وتنظر عيناه إلى قدوس إسرائيل '),
(16635, 'Isaiah', 23, 17, 8, ' ولا يلتفت إلى المذابح صنعة يديه ، ولا ينظر إلى ما صنعته أصابعه : السواري والشمسات '),
(16636, 'Isaiah', 23, 17, 9, ' في ذلك اليوم تصير مدنه الحصينة كالردم في الغاب ، والشوامخ التي تركوها من وجه بني إسرائيل فصارت خرابا '),
(16637, 'Isaiah', 23, 17, 10, ' لأنك نسيت إله خلاصك ولم تذكري صخرة حصنك ، لذلك تغرسين أغراسا نزهة وتنصبين نصبة غريبة '),
(16638, 'Isaiah', 23, 17, 11, ' يوم غرسك تسيجينها ، وفي الصباح تجعلين زرعك يزهر . ولكن يهرب الحصيد في يوم الضربة المهلكة والكآبة العديمة الرجاء '),
(16639, 'Isaiah', 23, 17, 12, ' آه ضجيج شعوب كثيرة تضج كضجيج البحر ، وهدير قبائل تهدر كهدير مياه غزيرة '),
(16640, 'Isaiah', 23, 17, 13, ' قبائل تهدر كهدير مياه كثيرة . ولكنه ينتهرها فتهرب بعيدا ، وتطرد كعصافة الجبال أمام الريح ، وكالجل أمام الزوبعة '),
(16641, 'Isaiah', 23, 17, 14, ' في وقت المساء إذا رعب . قبل الصبح ليسوا هم . هذا نصيب ناهبينا وحظ سالبينا '),
(16642, 'Isaiah', 23, 18, 1, ' يا أرض حفيف الأجنحة التي في عبر أنهار كوش '),
(16643, 'Isaiah', 23, 18, 2, ' المرسلة رسلا في البحر وفي قوارب من البردي على وجه المياه . اذهبوا أيها الرسل السريعون إلى أمة طويلة وجرداء ، إلى شعب مخوف منذ كان فصاعدا ، أمة قوة وشدة ودوس ، قد خرقت الأنهار أرضها '),
(16644, 'Isaiah', 23, 18, 3, ' يا جميع سكان المسكونة وقاطني الأرض ، عندما ترتفع الراية على الجبال تنظرون ، وعندما يضرب بالبوق تسمعون '),
(16645, 'Isaiah', 23, 18, 4, ' لأنه هكذا قال لي الرب : إني أهدأ وأنظر في مسكني كالحر الصافي على البقل ، كغيم الندى في حر الحصاد '),
(16646, 'Isaiah', 23, 18, 5, ' فإنه قبل الحصاد ، عند تمام الزهر ، وعندما يصير الزهر حصرما نضيجا ، يقطع القضبان بالمناجل ، وينزع الأفنان ويطرحها '),
(16647, 'Isaiah', 23, 18, 6, ' تترك معا لجوارح الجبال ولوحوش الأرض ، فتصيف عليها الجوارح ، وتشتي عليها جميع وحوش الأرض '),
(16648, 'Isaiah', 23, 18, 7, ' في ذلك اليوم تقدم هدية لرب الجنود من شعب طويل وأجرد ، ومن شعب مخوف منذ كان فصاعدا ، من أمة ذات قوة وشدة ودوس ، قد خرقت الأنهار أرضها ، إلى موضع اسم رب الجنود ، جبل صهيون '),
(16649, 'Isaiah', 23, 19, 1, ' وحي من جهة مصر : هوذا الرب راكب على سحابة سريعة وقادم إلى مصر ، فترتجف أوثان مصر من وجهه ، ويذوب قلب مصر داخلها '),
(16650, 'Isaiah', 23, 19, 2, ' وأهيج مصريين على مصريين ، فيحاربون كل واحد أخاه وكل واحد صاحبه : مدينة مدينة ، ومملكة مملكة '),
(16651, 'Isaiah', 23, 19, 3, ' وتهراق روح مصر داخلها ، وأفني مشورتها ، فيسألون الأوثان والعازفين وأصحاب التوابع والعرافين '),
(16652, 'Isaiah', 23, 19, 4, ' وأغلق على المصريين في يد مولى قاس ، فيتسلط عليهم ملك عزيز ، يقول السيد رب الجنود '),
(16653, 'Isaiah', 23, 19, 5, ' وتنشف المياه من البحر ، ويجف النهر وييبس '),
(16654, 'Isaiah', 23, 19, 6, ' وتنتن الأنهار ، وتضعف وتجف سواقي مصر ، ويتلف القصب والأسل '),
(16655, 'Isaiah', 23, 19, 7, ' والرياض على النيل على حافة النيل ، وكل مزرعة على النيل تيبس وتتبدد ولا تكون '),
(16656, 'Isaiah', 23, 19, 8, ' والصيادون يئنون ، وكل الذين يلقون شصا في النيل ينوحون . والذين يبسطون شبكة على وجه المياه يحزنون '),
(16657, 'Isaiah', 23, 19, 9, ' ويخزى الذين يعملون الكتان الممشط ، والذين يحيكون الأنسجة البيضاء '),
(16658, 'Isaiah', 23, 19, 10, ' وتكون عمدها مسحوقة ، وكل العاملين بالأجرة مكتئبي النفس '),
(16659, 'Isaiah', 23, 19, 11, ' إن رؤساء صوعن أغبياء حكماء مشيري فرعون مشورتهم بهيمية كيف تقولون لفرعون : أنا ابن حكماء ، ابن ملوك قدماء '),
(16660, 'Isaiah', 23, 19, 12, ' فأين هم حكماؤك ؟ فليخبروك . ليعرفوا ماذا قضى به رب الجنود على مصر '),
(16661, 'Isaiah', 23, 19, 13, ' رؤساء صوعن صاروا أغبياء . رؤساء نوف انخدعوا . وأضل مصر وجوه أسباطها '),
(16662, 'Isaiah', 23, 19, 14, ' مزج الرب في وسطها روح غي ، فأضلوا مصر في كل عملها ، كترنح السكران في قيئه '),
(16663, 'Isaiah', 23, 19, 15, ' فلا يكون لمصر عمل يعمله رأس أو ذنب ، نخلة أو أسلة '),
(16664, 'Isaiah', 23, 19, 16, ' في ذلك اليوم تكون مصر كالنساء ، فترتعد وترجف من هزة يد رب الجنود التي يهزها عليها '),
(16665, 'Isaiah', 23, 19, 17, ' وتكون أرض يهوذا رعبا لمصر . كل من تذكرها يرتعب من أمام قضاء رب الجنود الذي يقضي به عليها '),
(16666, 'Isaiah', 23, 19, 18, ' في ذلك اليوم يكون في أرض مصر خمس مدن تتكلم بلغة كنعان وتحلف لرب الجنود ، يقال لإحداها مدينة الشمس '),
(16667, 'Isaiah', 23, 19, 19, ' في ذلك اليوم يكون مذبح للرب في وسط أرض مصر ، وعمود للرب عند تخمها '),
(16668, 'Isaiah', 23, 19, 20, ' فيكون علامة وشهادة لرب الجنود في أرض مصر . لأنهم يصرخون إلى الرب بسبب المضايقين ، فيرسل لهم مخلصا ومحاميا وينقذهم '),
(16669, 'Isaiah', 23, 19, 21, ' فيعرف الرب في مصر ، ويعرف المصريون الرب في ذلك اليوم ، ويقدمون ذبيحة وتقدمة ، وينذرون للرب نذرا ويوفون به '),
(16670, 'Isaiah', 23, 19, 22, ' ويضرب الرب مصر ضاربا فشافيا ، فيرجعون إلى الرب فيستجيب لهم ويشفيهم '),
(16671, 'Isaiah', 23, 19, 23, ' في ذلك اليوم تكون سكة من مصر إلى أشور ، فيجيء الأشوريون إلى مصر والمصريون إلى أشور ، ويعبد المصريون مع الأشوريين '),
(16672, 'Isaiah', 23, 19, 24, ' في ذلك اليوم يكون إسرائيل ثلثا لمصر ولأشور ، بركة في الأرض '),
(16673, 'Isaiah', 23, 19, 25, ' بها يبارك رب الجنود قائلا : مبارك شعبي مصر ، وعمل يدي أشور ، وميراثي إسرائيل '),
(16674, 'Isaiah', 23, 35, 9, ' لا يكون هناك أسد . وحش مفترس لا يصعد إليها . لا يوجد هناك . بل يسلك المفديون فيها '),
(16675, 'Isaiah', 23, 35, 10, ' ومفديو الرب يرجعون ويأتون إلى صهيون بترنم ، وفرح أبدي على رؤوسهم . ابتهاج وفرح يدركانهم . ويهرب الحزن والتنهد '),
(16676, 'Isaiah', 23, 36, 1, ' وكان في السنة الرابعة عشرة للملك حزقيا أن سنحاريب ملك أشور صعد على كل مدن يهوذا الحصينة وأخذها '),
(16677, 'Isaiah', 23, 36, 2, ' وأرسل ملك أشور ربشاقى من لاخيش إلى أورشليم ، إلى الملك حزقيا بجيش عظيم ، فوقف عند قناة البركة العليا في طريق حقل القصار '),
(16678, 'Isaiah', 23, 36, 3, ' فخرج إليه ألياقيم بن حلقيا الذي على البيت ، وشبنة الكاتب ، ويوآخ بن آساف المسجل '),
(16679, 'Isaiah', 23, 36, 4, ' فقال لهم ربشاقى : قولوا لحزقيا : هكذا يقول الملك العظيم ملك أشور : ما هو هذا الاتكال الذي اتكلته '),
(16680, 'Isaiah', 23, 36, 5, ' أقول إنما كلام الشفتين هو مشورة وبأس للحرب . والآن على من اتكلت حتى عصيت علي '),
(16681, 'Isaiah', 23, 36, 6, ' إنك قد اتكلت على عكاز هذه القصبة المرضوضة ، على مصر ، التي إذا توكأ أحد عليها دخلت في كفه وثقبتها . هكذا فرعون ملك مصر لجميع المتوكلين عليه '),
(16682, 'Isaiah', 23, 36, 7, ' وإذا قلت لي : على الرب إلهنا اتكلنا ، أفليس هو الذي أزال حزقيا مرتفعاته ومذابحه ، وقال ليهوذا ولأورشليم : أمام هذا المذبح تسجدون '),
(16683, 'Isaiah', 23, 36, 8, ' فالآن راهن سيدي ملك أشور ، فأعطيك ألفي فرس إن استطعت أن تجعل عليها راكبين '),
(16684, 'Isaiah', 23, 36, 9, ' فكيف ترد وجه وال واحد من عبيد سيدي الصغار ، وتتكل على مصر لأجل مركبات وفرسان '),
(16685, 'Isaiah', 23, 36, 10, ' والآن هل بدون الرب صعدت على هذه الأرض لأخربها ؟ الرب قال لي : اصعد إلى هذه الأرض واخربها '),
(16686, 'Isaiah', 23, 36, 11, ' فقال ألياقيم وشبنة ويوآخ لربشاقى : كلم عبيدك بالأرامي لأننا نفهمه ، ولا تكلمنا باليهودي في مسامع الشعب الذين على السور '),
(16687, 'Isaiah', 23, 36, 12, ' فقال ربشاقى : هل إلى سيدك وإليك أرسلني سيدي لكي أتكلم بهذا الكلام ؟ أليس إلى الرجال الجالسين على السور ، ليأكلوا عذرتهم ويشربوا بولهم معكم '),
(16688, 'Isaiah', 23, 36, 13, ' ثم وقف ربشاقى ونادى بصوت عظيم باليهودي وقال : اسمعوا كلام الملك العظيم ملك أشور '),
(16689, 'Isaiah', 23, 36, 14, ' هكذا يقول الملك : لا يخدعكم حزقيا لأنه لا يقدر أن ينقذكم '),
(16690, 'Isaiah', 23, 36, 15, ' ولا يجعلكم حزقيا تتكلون على الرب قائلا : إنقاذا ينقذنا الرب . لا تدفع هذه المدينة إلى يد ملك أشور '),
(16691, 'Isaiah', 23, 36, 16, ' لا تسمعوا لحزقيا . لأنه هكذا يقول ملك أشور : اعقدوا معي صلحا ، واخرجوا إلي وكلوا كل واحد من جفنته ، وكل واحد من تينته ، واشربوا كل واحد ماء بئره '),
(16692, 'Isaiah', 23, 36, 17, ' حتى آتي وآخذكم إلى أرض مثل أرضكم ، أرض حنطة وخمر ، أرض خبز وكروم '),
(16693, 'Isaiah', 23, 36, 18, ' لا يغركم حزقيا قائلا : الرب ينقذنا . هل أنقذ آلهة الأمم كل واحد أرضه من يد ملك أشور '),
(16694, 'Isaiah', 23, 36, 19, ' أين آلهة حماة وأرفاد ؟ أين آلهة سفروايم ؟ هل أنقذوا السامرة من يدي '),
(16695, 'Isaiah', 23, 36, 20, ' من من كل آلهة هذه الأراضي أنقذ أرضهم من يدي ، حتى ينقذ الرب أورشليم من يدي '),
(16696, 'Isaiah', 23, 36, 21, ' فسكتوا ولم يجيبوا بكلمة لأن أمر الملك كان قائلا : لا تجيبوه '),
(16697, 'Isaiah', 23, 36, 22, ' فجاء ألياقيم بن حلقيا الذي على البيت وشبنة الكاتب ويوآخ بن آساف المسجل إلى حزقيا وثيابهم ممزقة ، فأخبروه بكلام ربشاقى '),
(16698, 'Isaiah', 23, 37, 1, ' فلما سمع الملك حزقيا ذلك مزق ثيابه وتغطى بمسح ودخل بيت الرب '),
(16699, 'Isaiah', 23, 37, 2, ' وأرسل ألياقيم الذي على البيت وشبنة الكاتب وشيوخ الكهنة متغطين بمسوح إلى إشعياء بن آموص النبي '),
(16700, 'Isaiah', 23, 37, 3, ' فقالوا له : هكذا يقول حزقيا : هذا اليوم يوم شدة وتأديب وإهانة ، لأن الأجنة دنت إلى المولد ولا قوة على الولادة '),
(16701, 'Isaiah', 23, 37, 4, ' لعل الرب إلهك يسمع كلام ربشاقى الذي أرسله ملك أشور سيده ليعير الإله الحي ، فيوبخ على الكلام الذي سمعه الرب إلهك . فارفع صلاة لأجل البقية الموجودة '),
(16702, 'Isaiah', 23, 37, 5, ' فجاء عبيد الملك حزقيا إلى إشعياء '),
(16703, 'Isaiah', 23, 37, 6, ' فقال لهم إشعياء : هكذا تقولون لسيدكم : هكذا يقول الرب : لا تخف بسبب الكلام الذي سمعته ، الذي جدف علي به غلمان ملك أشور '),
(16704, 'Isaiah', 23, 37, 7, ' هأنذا أجعل فيه روحا فيسمع خبرا ويرجع إلى أرضه ، وأسقطه بالسيف في أرضه '),
(16705, 'Isaiah', 23, 37, 8, ' فرجع ربشاقى ووجد ملك أشور يحارب لبنة ، لأنه سمع أنه ارتحل عن لخيش '),
(16706, 'Isaiah', 23, 37, 9, ' وسمع عن ترهاقة ملك كوش قولا : قد خرج ليحاربك . فلما سمع أرسل رسلا إلى حزقيا قائلا '),
(16707, 'Isaiah', 23, 37, 10, ' هكذا تكلمون حزقيا ملك يهوذا قائلين : لا يخدعك إلهك الذي أنت متوكل عليه ، قائلا : لا تدفع أورشليم إلى يد ملك أشور '),
(16708, 'Isaiah', 23, 37, 11, ' إنك قد سمعت ما فعل ملوك أشور بجميع الأراضي لتحريمها . وهل تنجو أنت '),
(16709, 'Isaiah', 23, 37, 12, ' هل أنقذ آلهة الأمم هؤلاء الذين أهلكهم آبائي ، جوزان وحاران ورصف وبني عدن ، الذين في تلسار '),
(16710, 'Isaiah', 23, 37, 13, ' أين ملك حماة وملك أرفاد وملك مدينة سفروايم وهينع وعوا '),
(16711, 'Isaiah', 23, 37, 14, ' فأخذ حزقيا الرسائل من يد الرسل وقرأها ، ثم صعد إلى بيت الرب ، ونشرها حزقيا أمام الرب '),
(16712, 'Isaiah', 23, 37, 15, ' وصلى حزقيا إلى الرب قائلا '),
(16713, 'Isaiah', 23, 37, 16, ' يارب الجنود ، إله إسرائيل الجالس فوق الكروبيم ، أنت هو الإله وحدك لكل ممالك الأرض . أنت صنعت السماوات والأرض '),
(16714, 'Isaiah', 23, 37, 17, ' أمل يارب أذنك واسمع . افتح يارب عينيك وانظر ، واسمع كل كلام سنحاريب الذي أرسله ليعير الله الحي '),
(16715, 'Isaiah', 23, 37, 18, ' حقا يارب إن ملوك أشور قد خربوا كل الأمم وأرضهم '),
(16716, 'Isaiah', 23, 37, 19, ' ودفعوا آلهتهم إلى النار ، لأنهم ليسوا آلهة بل صنعة أيدي الناس ، خشب وحجر ، فأبادوهم '),
(16717, 'Isaiah', 23, 37, 20, ' والآن أيها الرب إلهنا خلصنا من يده ، فتعلم ممالك الأرض كلها أنك أنت الرب وحدك '),
(16718, 'Isaiah', 23, 37, 21, ' فأرسل إشعياء بن آموص إلى حزقيا قائلا : هكذا يقول الرب إله إسرائيل الذي صليت إليه من جهة سنحاريب ملك أشور '),
(16719, 'Isaiah', 23, 37, 22, ' هذا هو الكلام الذي تكلم به الرب عليه : احتقرتك . استهزأت بك العذراء ابنة صهيون . نحوك أنغضت ابنة أورشليم رأسها '),
(16720, 'Isaiah', 23, 37, 23, ' من عيرت وجدفت ، وعلى من عليت صوتا ، وقد رفعت إلى العلاء عينيك ؟ على قدوس إسرائيل '),
(16721, 'Isaiah', 23, 37, 24, ' عن يد عبيدك عيرت السيد ، وقلت : بكثرة مركباتي قد صعدت إلى علو الجبال ، عقاب لبنان ، فأقطع أرزه الطويل وأفضل سروه ، وأدخل أقصى علوه ، وعر كرمله '),
(16722, 'Isaiah', 23, 37, 25, ' أنا قد حفرت وشربت مياها ، وأنشف ببطن قدمي جميع خلجان مصر '),
(16723, 'Isaiah', 23, 37, 26, ' ألم تسمع ؟ منذ البعيد صنعته . منذ الأيام القديمة صورته . الآن أتيت به . فتكون لتخريب مدن محصنة حتى تصير روابي خربة '),
(16724, 'Isaiah', 23, 37, 27, ' فسكانها قصار الأيدي قد ارتاعوا وخجلوا . صاروا كعشب الحقل وكالنبات الأخضر ، كحشيش السطوح ، وكالملفوح قبل نموه '),
(16725, 'Isaiah', 23, 37, 28, ' ولكنني عالم بجلوسك وخروجك ودخولك وهيجانك علي '),
(16726, 'Isaiah', 23, 37, 29, ' لأن هيجانك علي وعجرفتك قد صعدا إلى أذني ، أضع خزامتي في أنفك وشكيمتي في شفتيك ، وأردك في الطريق الذي جئت فيه '),
(16727, 'Isaiah', 23, 37, 30, ' وهذه لك العلامة : تأكلون هذه السنة زريعا ، وفي السنة الثانية خلفة ، وأما السنة الثالثة ففيها تزرعون وتحصدون ، وتغرسون كروما وتأكلون أثمارها '),
(16728, 'Isaiah', 23, 37, 31, ' ويعود الناجون من بيت يهوذا الباقون يتأصلون إلى أسفل ، ويصنعون ثمرا إلى ما فوق '),
(16729, 'Isaiah', 23, 37, 32, ' لأنه من أورشليم تخرج بقية ، وناجون من جبل صهيون . غيرة رب الجنود تصنع هذا '),
(16730, 'Isaiah', 23, 37, 33, ' لذلك هكذا يقول الرب عن ملك أشور : لا يدخل هذه المدينة ، ولا يرمي هناك سهما ، ولا يتقدم عليها بترس ، ولا يقيم عليها مترسة '),
(16731, 'Isaiah', 23, 37, 34, ' في الطريق الذي جاء فيه يرجع ، وإلى هذه المدينة لا يدخل ، يقول الرب '),
(16732, 'Isaiah', 23, 37, 35, ' وأحامي عن هذه المدينة لأخلصها من أجل نفسي ، ومن أجل داود عبدي '),
(16733, 'Isaiah', 23, 37, 36, ' فخرج ملاك الرب وضرب من جيش أشور مئة وخمسة وثمانين ألفا . فلما بكروا صباحا إذا هم جميعا جثث ميتة '),
(16734, 'Isaiah', 23, 37, 37, ' فانصرف سنحاريب ملك أشور وذهب راجعا وأقام في نينوى '),
(16735, 'Isaiah', 23, 37, 38, ' وفيما هو ساجد في بيت نسروخ إلهه ضربه أدرملك وشرآصر ابناه بالسيف ، ونجوا إلى أرض أراراط . وملك أسرحدون ابنه عوضا عنه '),
(16736, 'Isaiah', 23, 38, 1, ' في تلك الأيام مرض حزقيا للموت ، فجاء إليه إشعياء بن آموص النبي وقال له : هكذا يقول الرب : أوص بيتك لأنك تموت ولا تعيش '),
(16737, 'Isaiah', 23, 38, 2, ' فوجه حزقيا وجهه إلى الحائط وصلى إلى الرب '),
(16738, 'Isaiah', 23, 38, 3, ' وقال : آه يارب ، اذكر كيف سرت أمامك بالأمانة وبقلب سليم وفعلت الحسن في عينيك . وبكى حزقيا بكاء عظيما '),
(16739, 'Isaiah', 23, 38, 4, ' فصار قول الرب إلى إشعياء قائلا '),
(16740, 'Isaiah', 23, 38, 5, ' اذهب وقل لحزقيا : هكذا يقول الرب إله داود أبيك : قد سمعت صلاتك . قد رأيت دموعك . هأنذا أضيف إلى أيامك خمس عشرة سنة '),
(16741, 'Isaiah', 23, 38, 6, ' ومن يد ملك أشور أنقذك وهذه المدينة . وأحامي عن هذه المدينة '),
(16742, 'Isaiah', 23, 38, 7, ' وهذه لك العلامة من قبل الرب على أن الرب يفعل هذا الأمر الذي تكلم به '),
(16743, 'Isaiah', 23, 38, 8, ' هأنذا أرجع ظل الدرجات الذي نزل في درجات آحاز بالشمس عشر درجات إلى الوراء . فرجعت الشمس عشر درجات في الدرجات التي نزلتها '),
(16744, 'Isaiah', 23, 38, 9, ' كتابة لحزقيا ملك يهوذا إذ مرض وشفي من مرضه '),
(16745, 'Isaiah', 23, 38, 10, ' أنا قلت : في عز أيامي أذهب إلى أبواب الهاوية . قد أعدمت بقية سني '),
(16746, 'Isaiah', 23, 38, 11, ' قلت : لا أرى الرب . الرب في أرض الأحياء . لا أنظر إنسانا بعد مع سكان الفانية '),
(16747, 'Isaiah', 23, 38, 12, ' مسكني قد انقلع وانتقل عني كخيمة الراعي . لففت كالحائك حياتي . من النول يقطعني . النهار والليل تفنيني '),
(16748, 'Isaiah', 23, 24, 10, ' دمرت قرية الخراب . أغلق كل بيت عن الدخول '),
(16749, 'Isaiah', 23, 24, 11, ' صراخ على الخمر في الأزقة . غرب كل فرح . انتفى سرور الأرض '),
(16750, 'Isaiah', 23, 24, 12, ' الباقي في المدينة خراب ، وضرب الباب ردما '),
(16751, 'Isaiah', 23, 24, 13, ' إنه هكذا يكون في وسط الأرض بين الشعوب كنفاضة زيتونة ، كالخصاصة إذ انتهى القطاف '),
(16752, 'Isaiah', 23, 24, 14, ' هم يرفعون أصواتهم ويترنمون . لأجل عظمة الرب يصوتون من البحر '),
(16753, 'Isaiah', 23, 24, 15, ' لذلك في المشارق مجدوا الرب . في جزائر البحر مجدوا اسم الرب إله إسرائيل '),
(16754, 'Isaiah', 23, 24, 16, ' من أطراف الأرض سمعنا ترنيمة : مجدا للبار . فقلت : يا تلفي ، يا تلفي ويل لي الناهبون نهبوا . الناهبون نهبوا نهبا '),
(16755, 'Isaiah', 23, 24, 17, ' عليك رعب وحفرة وفخ يا ساكن الأرض '),
(16756, 'Isaiah', 23, 24, 18, ' ويكون أن الهارب من صوت الرعب يسقط في الحفرة ، والصاعد من وسط الحفرة يؤخذ بالفخ . لأن ميازيب من العلاء انفتحت ، وأسس الأرض تزلزلت '),
(16757, 'Isaiah', 23, 24, 19, ' انسحقت الأرض انسحاقا . تشققت الأرض تشققا . تزعزعت الأرض تزعزعا '),
(16758, 'Isaiah', 23, 24, 20, ' ترنحت الأرض ترنحا كالسكران ، وتدلدلت كالعرزال ، وثقل عليها ذنبها ، فسقطت ولا تعود تقوم '),
(16759, 'Isaiah', 23, 24, 21, ' ويكون في ذلك اليوم أن الرب يطالب جند العلاء في العلاء ، وملوك الأرض على الأرض '),
(16760, 'Isaiah', 23, 24, 22, ' ويجمعون جمعا كأسارى في سجن ، ويغلق عليهم في حبس ، ثم بعد أيام كثيرة يتعهدون '),
(16761, 'Isaiah', 23, 24, 23, ' ويخجل القمر وتخزى الشمس ، لأن رب الجنود قد ملك في جبل صهيون وفي أورشليم ، وقدام شيوخه مجد '),
(16762, 'Isaiah', 23, 25, 1, ' يارب ، أنت إلهي أعظمك . أحمد اسمك لأنك صنعت عجبا . مقاصدك منذ القديم أمانة وصدق '),
(16763, 'Isaiah', 23, 25, 2, ' لأنك جعلت مدينة رجمة . قرية حصينة ردما . قصر أعاجم أن لا تكون مدينة . لا يبنى إلى الأبد '),
(16764, 'Isaiah', 23, 48, 17, ' هكذا يقول الرب فاديك قدوس إسرائيل : أنا الرب إلهك معلمك لتنتفع ، وأمشيك في طريق تسلك فيه '),
(16765, 'Isaiah', 23, 48, 18, ' ليتك أصغيت لوصاياي ، فكان كنهر سلامك وبرك كلجج البحر '),
(16766, 'Isaiah', 23, 48, 19, ' وكان كالرمل نسلك ، وذرية أحشائك كأحشائه . لا ينقطع ولا يباد اسمه من أمامي '),
(16767, 'Isaiah', 23, 48, 20, ' اخرجوا من بابل ، اهربوا من أرض الكلدانيين . بصوت الترنم أخبروا . نادوا بهذا . شيعوه إلى أقصى الأرض . قولوا : قد فدى الرب عبده يعقوب '),
(16768, 'Isaiah', 23, 48, 21, ' ولم يعطشوا في القفار التي سيرهم فيها . أجرى لهم من الصخر ماء ، وشق الصخر ففاضت المياه '),
(16769, 'Isaiah', 23, 48, 22, ' لا سلام ، قال الرب للأشرار '),
(16770, 'Isaiah', 23, 49, 1, ' اسمعي لي أيتها الجزائر ، واصغوا أيها الأمم من بعيد : الرب من البطن دعاني . من أحشاء أمي ذكر اسمي '),
(16771, 'Isaiah', 23, 49, 2, ' وجعل فمي كسيف حاد . في ظل يده خبأني وجعلني سهما مبريا . في كنانته أخفاني '),
(16772, 'Isaiah', 23, 49, 3, ' وقال لي : أنت عبدي إسرائيل الذي به أتمجد '),
(16773, 'Isaiah', 23, 49, 4, ' أما أنا فقلت : عبثا تعبت . باطلا وفارغا أفنيت قدرتي . لكن حقي عند الرب ، وعملي عند إلهي '),
(16774, 'Isaiah', 23, 49, 5, ' والآن قال الرب جابلي من البطن عبدا له ، لإرجاع يعقوب إليه ، فينضم إليه إسرائيل فأتمجد في عيني الرب ، وإلهي يصير قوتي '),
(16775, 'Isaiah', 23, 49, 6, ' فقال : قليل أن تكون لي عبدا لإقامة أسباط يعقوب ، ورد محفوظي إسرائيل . فقد جعلتك نورا للأمم لتكون خلاصي إلى أقصى الأرض '),
(16776, 'Isaiah', 23, 49, 7, ' هكذا قال الرب فادي إسرائيل ، قدوسه ، للمهان النفس ، لمكروه الأمة ، لعبد المتسلطين : ينظر ملوك فيقومون . رؤساء فيسجدون . لأجل الرب الذي هو أمين ، وقدوس إسرائيل الذي قد اختارك '),
(16777, 'Isaiah', 23, 49, 8, ' هكذا قال الرب : في وقت القبول استجبتك ، وفي يوم الخلاص أعنتك . فأحفظك وأجعلك عهدا للشعب ، لإقامة الأرض ، لتمليك أملاك البراري '),
(16778, 'Isaiah', 23, 49, 9, ' قائلا للأسرى : اخرجوا . للذين في الظلام : اظهروا . على الطرق يرعون وفي كل الهضاب مرعاهم '),
(16779, 'Isaiah', 23, 49, 10, ' لا يجوعون ولا يعطشون ، ولا يضربهم حر ولا شمس ، لأن الذي يرحمهم يهديهم وإلى ينابيع المياه يوردهم '),
(16780, 'Isaiah', 23, 49, 11, ' وأجعل كل جبالي طريقا ، ومناهجي ترتفع '),
(16781, 'Isaiah', 23, 49, 12, ' هؤلاء من بعيد يأتون ، وهؤلاء من الشمال ومن المغرب ، وهؤلاء من أرض سينيم '),
(16782, 'Isaiah', 23, 49, 13, ' ترنمي أيتها السماوات ، وابتهجي أيتها الأرض . لتشد الجبال بالترنم ، لأن الرب قد عزى شعبه ، وعلى بائسيه يترحم '),
(16783, 'Isaiah', 23, 49, 14, ' وقالت صهيون : قد تركني الرب ، وسيدي نسيني '),
(16784, 'Isaiah', 23, 49, 15, ' هل تنسى المرأة رضيعها فلا ترحم ابن بطنها ؟ حتى هؤلاء ينسين ، وأنا لا أنساك '),
(16785, 'Isaiah', 23, 49, 16, ' هوذا على كفي نقشتك . أسوارك أمامي دائما '),
(16786, 'Isaiah', 23, 49, 17, ' قد أسرع بنوك . هادموك ومخربوك منك يخرجون '),
(16787, 'Isaiah', 23, 49, 18, ' ارفعي عينيك حواليك وانظري . كلهم قد اجتمعوا ، أتوا إليك . حي أنا ، يقول الرب ، إنك تلبسين كلهم كحلي ، وتتنطقين بهم كعروس '),
(16788, 'Isaiah', 23, 49, 19, ' إن خربك وبراريك وأرض خرابك ، إنك تكونين الآن ضيقة على السكان ، ويتباعد مبتلعوك '),
(16789, 'Isaiah', 23, 49, 20, ' يقول أيضا في أذنيك بنو ثكلك : ضيق علي المكان . وسعي لي لأسكن '),
(16790, 'Isaiah', 23, 49, 21, ' فتقولين في قلبك : من ولد لي هؤلاء وأنا ثكلى ، وعاقر منفية ومطرودة ؟ وهؤلاء من رباهم ؟ هأنذا كنت متروكة وحدي . هؤلاء أين كانوا '),
(16791, 'Isaiah', 23, 49, 22, ' هكذا قال السيد الرب : ها إني أرفع إلى الأمم يدي وإلى الشعوب أقيم رايتي ، فيأتون بأولادك في الأحضان ، وبناتك على الأكتاف يحملن '),
(16792, 'Isaiah', 23, 49, 23, ' ويكون الملوك حاضنيك وسيداتهم مرضعاتك . بالوجوه إلى الأرض يسجدون لك ، ويلحسون غبار رجليك ، فتعلمين أني أنا الرب الذي لا يخزى منتظروه '),
(16793, 'Isaiah', 23, 49, 24, ' هل تسلب من الجبار غنيمة ؟ وهل يفلت سبي المنصور '),
(16794, 'Isaiah', 23, 49, 25, ' فإنه هكذا قال الرب : حتى سبي الجبار يسلب ، وغنيمة العاتي تفلت . وأنا أخاصم مخاصمك وأخلص أولادك '),
(16795, 'Isaiah', 23, 49, 26, ' وأطعم ظالميك لحم أنفسهم ، ويسكرون بدمهم كما من سلاف ، فيعلم كل بشر أني أنا الرب مخلصك ، وفاديك عزيز يعقوب '),
(16796, 'Isaiah', 23, 50, 1, ' هكذا قال الرب : أين كتاب طلاق أمكم التي طلقتها ، أو من هو من غرمائي الذي بعته إياكم ؟ هوذا من أجل آثامكم قد بعتم ، ومن أجل ذنوبكم طلقت أمكم '),
(16797, 'Isaiah', 23, 50, 2, ' لماذا جئت وليس إنسان ، ناديت وليس مجيب ؟ هل قصرت يدي عن الفداء ؟ وهل ليس في قدرة للإنقاذ ؟ هوذا بزجرتي أنشف البحر . أجعل الأنهار قفرا . ينتن سمكها من عدم الماء ، ويموت بالعطش '),
(16798, 'Isaiah', 23, 50, 3, ' ألبس السماوات ظلاما ، وأجعل المسح غطاءها '),
(16799, 'Isaiah', 23, 50, 4, ' أعطاني السيد الرب لسان المتعلمين لأعرف أن أغيث المعيي بكلمة . يوقظ كل صباح ، يوقظ لي أذنا ، لأسمع كالمتعلمين '),
(16800, 'Isaiah', 23, 50, 5, ' السيد الرب فتح لي أذنا وأنا لم أعاند . إلى الوراء لم أرتد '),
(16801, 'Isaiah', 23, 50, 6, ' بذلت ظهري للضاربين ، وخدي للناتفين . وجهي لم أستر عن العار والبصق '),
(16802, 'Isaiah', 23, 50, 7, ' والسيد الرب يعينني ، لذلك لا أخجل . لذلك جعلت وجهي كالصوان وعرفت أني لا أخزى '),
(16803, 'Isaiah', 23, 50, 8, ' قريب هو الذي يبررني . من يخاصمني ؟ لنتواقف من هو صاحب دعوى معي ؟ ليتقدم إلي '),
(16804, 'Isaiah', 23, 50, 9, ' هوذا السيد الرب يعينني . من هو الذي يحكم علي ؟ هوذا كلهم كالثوب يبلون . يأكلهم العث '),
(16805, 'Isaiah', 23, 50, 10, ' من منكم خائف الرب ، سامع لصوت عبده ؟ من الذي يسلك في الظلمات ولا نور له ؟ فليتكل على اسم الرب ويستند إلى إلهه '),
(16806, 'Isaiah', 23, 50, 11, ' يا هؤلاء جميعكم ، القادحين نارا ، المتنطقين بشرار ، اسلكوا بنور ناركم وبالشرار الذي أوقدتموه . من يدي صار لكم هذا . في الوجع تضطجعون '),
(16807, 'Isaiah', 23, 51, 1, ' اسمعوا لي أيها التابعون البر الطالبون الرب : انظروا إلى الصخر الذي منه قطعتم ، وإلى نقرة الجب التي منها حفرتم '),
(16808, 'Isaiah', 23, 51, 2, ' انظروا إلى إبراهيم أبيكم ، وإلى سارة التي ولدتكم . لأني دعوته وهو واحد وباركته وأكثرته '),
(16809, 'Isaiah', 23, 51, 3, ' فإن الرب قد عزى صهيون . عزى كل خربها ، ويجعل بريتها كعدن ، وباديتها كجنة الرب . الفرح والابتهاج يوجدان فيها . الحمد وصوت الترنم '),
(16810, 'Isaiah', 23, 51, 4, ' انصتوا إلي يا شعبي ، ويا أمتي اصغي إلي : لأن شريعة من عندي تخرج ، وحقي أثبته نورا للشعوب '),
(16811, 'Isaiah', 23, 51, 5, ' قريب بري . قد برز خلاصي ، وذراعاي يقضيان للشعوب . إياي ترجو الجزائر وتنتظر ذراعي '),
(16812, 'Isaiah', 23, 51, 6, ' ارفعوا إلى السماوات عيونكم ، وانظروا إلى الأرض من تحت . فإن السماوات كالدخان تضمحل ، والأرض كالثوب تبلى ، وسكانها كالبعوض يموتون . أما خلاصي فإلى الأبد يكون وبري لا ينقض '),
(16813, 'Isaiah', 23, 51, 7, ' اسمعوا لي يا عارفي البر ، الشعب الذي شريعتي في قلبه : لا تخافوا من تعيير الناس ، ومن شتائمهم لا ترتاعوا '),
(16814, 'Isaiah', 23, 51, 8, ' لأنه كالثوب يأكلهم العث ، وكالصوف يأكلهم السوس . أما بري فإلى الأبد يكون ، وخلاصي إلى دور الأدوار '),
(16815, 'Isaiah', 23, 51, 9, ' استيقظي ، استيقظي البسي قوة يا ذراع الرب استيقظي كما في أيام القدم ، كما في الأدوار القديمة . ألست أنت القاطعة رهب ، الطاعنة التنين '),
(16816, 'Isaiah', 23, 51, 10, ' ألست أنت هي المنشفة البحر ، مياه الغمر العظيم ، الجاعلة أعماق البحر طريقا لعبور المفديين '),
(16817, 'Isaiah', 23, 51, 11, ' ومفديو الرب يرجعون ويأتون إلى صهيون بالترنم ، وعلى رؤوسهم فرح أبدي . ابتهاج وفرح يدركانهم . يهرب الحزن والتنهد '),
(16818, 'Isaiah', 23, 51, 12, ' أنا أنا هو معزيكم . من أنت حتى تخافي من إنسان يموت ، ومن ابن الإنسان الذي يجعل كالعشب '),
(16819, 'Isaiah', 23, 51, 13, ' وتنسى الرب صانعك ، باسط السماوات ومؤسس الأرض ، وتفزع دائما كل يوم من غضب المضايق عندما هيأ للإهلاك . وأين غضب المضايق '),
(16820, 'Isaiah', 23, 51, 14, ' سريعا يطلق المنحني ، ولا يموت في الجب ولا يعدم خبزه '),
(16821, 'Isaiah', 23, 51, 15, ' وأنا الرب إلهك مزعج البحر فتعج لججه . رب الجنود اسمه '),
(16822, 'Isaiah', 23, 51, 16, ' وقد جعلت أقوالي في فمك ، وبظل يدي سترتك لغرس السماوات وتأسيس الأرض ، ولتقول لصهيون : أنت شعبي '),
(16823, 'Isaiah', 23, 51, 17, ' انهضي ، انهضي قومي يا أورشليم التي شربت من يد الرب كأس غضبه ، ثفل كأس الترنح شربت . مصصت '),
(16824, 'Isaiah', 23, 51, 18, ' ليس لها من يقودها من جميع البنين الذين ولدتهم ، وليس من يمسك بيدها من جميع البنين الذين ربتهم '),
(16825, 'Isaiah', 23, 51, 19, ' اثنان هما ملاقياك . من يرثي لك ؟ الخراب والانسحاق والجوع والسيف . بمن أعزيك '),
(16826, 'Isaiah', 23, 51, 20, ' بنوك قد أعيوا . اضطجعوا في رأس كل زقاق كالوعل في شبكة . الملآنون من غضب الرب ، من زجرة إلهك '),
(16827, 'Isaiah', 23, 51, 21, ' لذلك اسمعي هذا أيتها البائسة والسكرى وليس بالخمر '),
(16828, 'Isaiah', 23, 51, 22, ' هكذا قال سيدك الرب ، وإلهك الذي يحاكم لشعبه : هأنذا قد أخذت من يدك كأس الترنح ، ثفل كأس غضبي . لا تعودين تشربينها في ما بعد '),
(16829, 'Isaiah', 23, 51, 23, ' وأضعها في يد معذبيك الذين قالوا لنفسك : انحني لنعبر . فوضعت كالأرض ظهرك وكالزقاق للعابرين '),
(16830, 'Isaiah', 23, 52, 1, ' استيقظي ، استيقظي البسي عزك يا صهيون البسي ثياب جمالك يا أورشليم ، المدينة المقدسة ، لأنه لا يعود يدخلك في ما بعد أغلف ولا نجس '),
(16831, 'Isaiah', 23, 52, 2, ' انتفضي من التراب . قومي اجلسي يا أورشليم . انحلي من ربط عنقك أيتها المسبية ابنة صهيون '),
(16832, 'Isaiah', 23, 52, 3, ' فإنه هكذا قال الرب : مجانا بعتم ، وبلا فضة تفكون '),
(16833, 'Isaiah', 23, 38, 13, ' صرخت إلى الصباح . كالأسد هكذا يهشم جميع عظامي . النهار والليل تفنيني '),
(16834, 'Isaiah', 23, 38, 14, ' كسنونة مزقزقة هكذا أصيح . أهدر كحمامة . قد ضعفت عيناي ناظرة إلى العلاء . يارب ، قد تضايقت . كن لي ضامنا '),
(16835, 'Isaiah', 23, 38, 15, ' بماذا أتكلم ، فإنه قال لي وهو قد فعل . أتمشى متمهلا كل سني من أجل مرارة نفسي '),
(16836, 'Isaiah', 23, 38, 16, ' أيها السيد ، بهذه يحيون ، وبها كل حياة روحي فتشفيني وتحييني '),
(16837, 'Isaiah', 23, 38, 17, ' هوذا للسلامة قد تحولت لي المرارة ، وأنت تعلقت بنفسي من وهدة الهلاك ، فإنك طرحت وراء ظهرك كل خطاياي '),
(16838, 'Isaiah', 23, 38, 18, ' لأن الهاوية لا تحمدك . الموت لا يسبحك . لا يرجو الهابطون إلى الجب أمانتك '),
(16839, 'Isaiah', 23, 38, 19, ' الحي الحي هو يحمدك كما أنا اليوم . الأب يعرف البنين حقك '),
(16840, 'Isaiah', 23, 38, 20, ' الرب لخلاصي . فنعزف بأوتارنا كل أيام حياتنا في بيت الرب '),
(16841, 'Isaiah', 23, 38, 21, ' وكان إشعياء قد قال : ليأخذوا قرص تين ويضمدوه على الدبل فيبرأ '),
(16842, 'Isaiah', 23, 38, 22, ' وحزقيا قال : ما هي العلامة أني أصعد إلى بيت الرب '),
(16843, 'Isaiah', 23, 39, 1, ' في ذلك الزمان أرسل مرودخ بلادان بن بلادان ملك بابل رسائل وهدية إلى حزقيا ، لأنه سمع أنه مرض ثم صح '),
(16844, 'Isaiah', 23, 39, 2, ' ففرح بهم حزقيا وأراهم بيت ذخائره : الفضة والذهب والأطياب والزيت الطيب ، وكل بيت أسلحته وكل ما وجد في خزائنه . لم يكن شيء لم يرهم إياه حزقيا في بيته وفي كل ملكه '),
(16845, 'Isaiah', 23, 39, 3, ' فجاء إشعياء النبي إلى الملك حزقيا وقال له : ماذا قال هؤلاء الرجال ، ومن أين جاءوا إليك ؟  . فقال حزقيا : جاءوا إلي من أرض بعيدة ، من بابل '),
(16846, 'Isaiah', 23, 39, 4, ' فقال : ماذا رأوا في بيتك ؟  . فقال حزقيا : رأوا كل ما في بيتي . ليس في خزائني شيء لم أرهم إياه '),
(16847, 'Isaiah', 23, 39, 5, ' فقال إشعياء لحزقيا : اسمع قول رب الجنود '),
(16848, 'Isaiah', 23, 39, 6, ' هوذا تأتي أيام يحمل فيها كل ما في بيتك ، وما خزنه آباؤك إلى هذا اليوم ، إلى بابل . لا يترك شيء ، يقول الرب '),
(16849, 'Isaiah', 23, 39, 7, ' ومن بنيك الذين يخرجون منك الذين تلدهم ، يأخذون ، فيكونون خصيانا في قصر ملك بابل '),
(16850, 'Isaiah', 23, 39, 8, ' فقال حزقيا لإشعياء : جيد هو قول الرب الذي تكلمت به . وقال : فإنه يكون سلام وأمان في أيامي '),
(16851, 'Isaiah', 23, 40, 1, ' عزوا ، عزوا شعبي ، يقول إلهكم '),
(16852, 'Isaiah', 23, 40, 2, ' طيبوا قلب أورشليم ونادوها بأن جهادها قد كمل ، أن إثمها قد عفي عنه ، أنها قد قبلت من يد الرب ضعفين عن كل خطاياها '),
(16853, 'Isaiah', 23, 40, 3, ' صوت صارخ في البرية : أعدوا طريق الرب . قوموا في القفر سبيلا لإلهنا '),
(16854, 'Isaiah', 23, 40, 4, ' كل وطاء يرتفع ، وكل جبل وأكمة ينخفض ، ويصير المعوج مستقيما ، والعراقيب سهلا '),
(16855, 'Isaiah', 23, 40, 5, ' فيعلن مجد الرب ويراه كل بشر جميعا ، لأن فم الرب تكلم '),
(16856, 'Isaiah', 23, 40, 6, ' صوت قائل : ناد . فقال : بماذا أنادي ؟  . كل جسد عشب ، وكل جماله كزهر الحقل '),
(16857, 'Isaiah', 23, 40, 7, ' يبس العشب ، ذبل الزهر ، لأن نفخة الرب هبت عليه . حقا الشعب عشب '),
(16858, 'Isaiah', 23, 40, 8, ' يبس العشب ، ذبل الزهر . وأما كلمة إلهنا فتثبت إلى الأبد '),
(16859, 'Isaiah', 23, 40, 9, ' على جبل عال اصعدي ، يا مبشرة صهيون . ارفعي صوتك بقوة ، يا مبشرة أورشليم . ارفعي لا تخافي . قولي لمدن يهوذا : هوذا إلهك '),
(16860, 'Isaiah', 23, 40, 10, ' هوذا السيد الرب بقوة يأتي وذراعه تحكم له . هوذا أجرته معه وعملته قدامه '),
(16861, 'Isaiah', 23, 40, 11, ' كراع يرعى قطيعه . بذراعه يجمع الحملان ، وفي حضنه يحملها ، ويقود المرضعات '),
(16862, 'Isaiah', 23, 40, 12, ' من كال بكفه المياه ، وقاس السماوات بالشبر ، وكال بالكيل تراب الأرض ، ووزن الجبال بالقبان ، والآكام بالميزان '),
(16863, 'Isaiah', 23, 40, 13, ' من قاس روح الرب ، ومن مشيره يعلمه '),
(16864, 'Isaiah', 23, 40, 14, ' من استشاره فأفهمه وعلمه في طريق الحق ، وعلمه معرفة وعرفه سبيل الفهم '),
(16865, 'Isaiah', 23, 40, 15, ' هوذا الأمم كنقطة من دلو ، وكغبار الميزان تحسب . هوذا الجزائر يرفعها كدقة '),
(16866, 'Isaiah', 23, 40, 16, ' ولبنان ليس كافيا للإيقاد ، وحيوانه ليس كافيا لمحرقة '),
(16867, 'Isaiah', 23, 40, 17, ' كل الأمم كلا شيء قدامه . من العدم والباطل تحسب عنده '),
(16868, 'Isaiah', 23, 40, 18, ' فبمن تشبهون الله ، وأي شبه تعادلون به '),
(16869, 'Isaiah', 23, 40, 19, ' الصنم يسبكه الصانع ، والصائغ يغشيه بذهب ويصوغ سلاسل فضة '),
(16870, 'Isaiah', 23, 40, 20, ' الفقير عن التقدمة ينتخب خشبا لا يسوس ، يطلب له صانعا ماهرا لينصب صنما لا يتزعزع '),
(16871, 'Isaiah', 23, 40, 21, ' ألا تعلمون ؟ ألا تسمعون ؟ ألم تخبروا من البداءة ؟ ألم تفهموا من أساسات الأرض '),
(16872, 'Isaiah', 23, 40, 22, ' الجالس على كرة الأرض وسكانها كالجندب . الذي ينشر السماوات كسرادق ، ويبسطها كخيمة للسكن '),
(16873, 'Isaiah', 23, 40, 23, ' الذي يجعل العظماء لا شيئا ، ويصير قضاة الأرض كالباطل '),
(16874, 'Isaiah', 23, 40, 24, ' لم يغرسوا بل لم يزرعوا ولم يتأصل في الأرض ساقهم . فنفخ أيضا عليهم فجفوا ، والعاصف كالعصف يحملهم '),
(16875, 'Isaiah', 23, 40, 25, ' فبمن تشبهونني فأساويه ؟ يقول القدوس '),
(16876, 'Isaiah', 23, 40, 26, ' ارفعوا إلى العلاء عيونكم وانظروا ، من خلق هذه ؟ من الذي يخرج بعدد جندها ، يدعو كلها بأسماء ؟ لكثرة القوة وكونه شديد القدرة لا يفقد أحد '),
(16877, 'Isaiah', 23, 40, 27, ' لماذا تقول يا يعقوب وتتكلم يا إسرائيل : قد اختفت طريقي عن الرب وفات حقي إلهي '),
(16878, 'Isaiah', 23, 40, 28, ' أما عرفت أم لم تسمع ؟ إله الدهر الرب خالق أطراف الأرض لا يكل ولا يعيا . ليس عن فهمه فحص '),
(16879, 'Isaiah', 23, 40, 29, ' يعطي المعيي قدرة ، ولعديم القوة يكثر شدة '),
(16880, 'Isaiah', 23, 40, 30, ' الغلمان يعيون ويتعبون ، والفتيان يتعثرون تعثرا '),
(16881, 'Isaiah', 23, 40, 31, ' وأما منتظرو الرب فيجددون قوة . يرفعون أجنحة كالنسور . يركضون ولا يتعبون . يمشون ولا يعيون '),
(16882, 'Isaiah', 23, 41, 1, ' انصتي إلي أيتها الجزائر ولتجدد القبائل قوة . ليقتربوا ثم يتكلموا . لنتقدم معا إلى المحاكمة '),
(16883, 'Isaiah', 23, 41, 2, ' من أنهض من المشرق الذي يلاقيه النصر عند رجليه ؟ دفع أمامه أمما وعلى ملوك سلطه . جعلهم كالتراب بسيفه ، وكالقش المنذري بقوسه '),
(16884, 'Isaiah', 23, 41, 3, ' طردهم . مر سالما في طريق لم يسلكه برجليه '),
(16885, 'Isaiah', 23, 41, 4, ' من فعل وصنع داعيا الأجيال من البدء ؟ أنا الرب الأول ، ومع الآخرين أنا هو '),
(16886, 'Isaiah', 23, 41, 5, ' نظرت الجزائر فخافت . أطراف الأرض ارتعدت . اقتربت وجاءت '),
(16887, 'Isaiah', 23, 41, 6, ' كل واحد يساعد صاحبه ويقول لأخيه : تشدد '),
(16888, 'Isaiah', 23, 41, 7, ' فشدد النجار الصائغ . الصاقل بالمطرقة الضارب على السندان ، قائلا عن الإلحام : هو جيد . فمكنه بمسامير حتى لا يتقلقل '),
(16889, 'Isaiah', 23, 41, 8, ' وأما أنت يا إسرائيل عبدي ، يا يعقوب الذي اخترته ، نسل إبراهيم خليلي '),
(16890, 'Isaiah', 23, 41, 9, ' الذي أمسكته من أطراف الأرض ، ومن أقطارها دعوته ، وقلت لك : أنت عبدي . اخترتك ولم أرفضك '),
(16891, 'Isaiah', 23, 41, 10, ' لا تخف لأني معك . لا تتلفت لأني إلهك . قد أيدتك وأعنتك وعضدتك بيمين بري '),
(16892, 'Isaiah', 23, 41, 11, ' إنه سيخزى ويخجل جميع المغتاظين عليك . يكون كلا شيء مخاصموك ويبيدون '),
(16893, 'Isaiah', 23, 41, 12, ' تفتش على منازعيك ولا تجدهم . يكون محاربوك كلا شيء وكالعدم '),
(16894, 'Isaiah', 23, 41, 13, ' لأني أنا الرب إلهك الممسك بيمينك ، القائل لك : لا تخف . أنا أعينك '),
(16895, 'Isaiah', 23, 41, 14, ' لا تخف يا دودة يعقوب ، يا شرذمة إسرائيل . أنا أعينك ، يقول الرب ، وفاديك قدوس إسرائيل '),
(16896, 'Isaiah', 23, 41, 15, ' هأنذا قد جعلتك نورجا محددا جديدا ذا أسنان . تدرس الجبال وتسحقها ، وتجعل الآكام كالعصافة '),
(16897, 'Isaiah', 23, 41, 16, ' تذريها فالريح تحملها والعاصف تبددها ، وأنت تبتهج بالرب . بقدوس إسرائيل تفتخر '),
(16898, 'Isaiah', 23, 41, 17, ' البائسون والمساكين طالبون ماء ولا يوجد . لسانهم من العطش قد يبس . أنا الرب أستجيب لهم . أنا إله إسرائيل لا أتركهم '),
(16899, 'Isaiah', 23, 41, 18, ' أفتح على الهضاب أنهارا ، وفي وسط البقاع ينابيع . أجعل القفر أجمة ماء ، والأرض اليابسة مفاجر مياه '),
(16900, 'Isaiah', 23, 56, 4, ' لأنه هكذا قال الرب للخصيان الذين يحفظون سبوتي ، ويختارون ما يسرني ، ويتمسكون بعهدي ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(16901, 'Isaiah', 23, 56, 5, ' إني أعطيهم في بيتي وفي أسواري نصبا واسما أفضل من البنين والبنات . أعطيهم اسما أبديا لا ينقطع '),
(16902, 'Isaiah', 23, 56, 6, ' وأبناء الغريب الذين يقترنون بالرب ليخدموه وليحبوا اسم الرب ليكونوا له عبيدا ، كل الذين يحفظون السبت لئلا ينجسوه ، ويتمسكون بعهدي '),
(16903, 'Isaiah', 23, 56, 7, ' آتي بهم إلى جبل قدسي ، وأفرحهم في بيت صلاتي ، وتكون محرقاتهم وذبائحهم مقبولة على مذبحي ، لأن بيتي بيت الصلاة يدعى لكل الشعوب '),
(16904, 'Isaiah', 23, 56, 8, ' يقول السيد الرب جامع منفيي إسرائيل : أجمع بعد إليه ، إلى مجموعيه '),
(16905, 'Isaiah', 23, 56, 9, ' يا جميع وحوش البر ، تعالي للأكل . يا جميع الوحوش التي في الوعر '),
(16906, 'Isaiah', 23, 56, 10, ' مراقبوه عمي كلهم . لا يعرفون . كلهم كلاب بكم لا تقدر أن تنبح . حالمون مضطجعون ، محبو النوم '),
(16907, 'Isaiah', 23, 56, 11, ' والكلاب شرهة لا تعرف الشبع . وهم رعاة لا يعرفون الفهم . التفتوا جميعا إلى طرقهم ، كل واحد إلى الربح عن أقصى '),
(16908, 'Isaiah', 23, 56, 12, ' هلموا آخذ خمرا ولنشتف مسكرا ، ويكون الغد كهذا اليوم عظيما بل أزيد جدا '),
(16909, 'Isaiah', 23, 57, 1, ' باد الصديق وليس أحد يضع ذلك في قلبه . ورجال الإحسان يضمون ، وليس من يفطن بأنه من وجه الشر يضم الصديق '),
(16910, 'Isaiah', 23, 57, 2, ' يدخل السلام . يستريحون في مضاجعهم . السالك بالاستقامة '),
(16911, 'Isaiah', 23, 57, 3, ' أما أنتم فتقدموا إلى هنا يا بني الساحرة ، نسل الفاسق والزانية '),
(16912, 'Isaiah', 23, 57, 4, ' بمن تسخرون ، وعلى من تفغرون الفم وتدلعون اللسان ؟ أما أنتم أولاد المعصية ، نسل الكذب '),
(16913, 'Isaiah', 23, 57, 5, ' المتوقدون إلى الأصنام تحت كل شجرة خضراء ، القاتلون الأولاد في الأودية تحت شقوق المعاقل '),
(16914, 'Isaiah', 23, 57, 6, ' في حجارة الوادي الملس نصيبك . تلك هي قرعتك . لتلك سكبت سكيبا وأصعدت تقدمة . أعن هذه أتعزى '),
(16915, 'Isaiah', 23, 57, 7, ' على جبل عال ومرتفع وضعت مضجعك ، وإلى هناك صعدت لتذبحي ذبيحة '),
(16916, 'Isaiah', 23, 57, 8, ' وراء الباب والقائمة وضعت تذكارك ، لأنك لغيري كشفت وصعدت . أوسعت مضجعك وقطعت لنفسك عهدا معهم . أحببت مضجعهم . نظرت فرصة '),
(16917, 'Isaiah', 23, 57, 9, ' وسرت إلى الملك بالدهن ، وأكثرت أطيابك ، وأرسلت رسلك إلى بعد ونزلت حتى إلى الهاوية '),
(16918, 'Isaiah', 23, 61, 6, ' أما أنتم فتدعون كهنة الرب ، تسمون خدام إلهنا . تأكلون ثروة الأمم ، وعلى مجدهم تتأمرون '),
(16919, 'Isaiah', 23, 61, 7, ' عوضا عن خزيكم ضعفان ، وعوضا عن الخجل يبتهجون بنصيبهم . لذلك يرثون في أرضهم ضعفين . بهجة أبدية تكون لهم '),
(16920, 'Isaiah', 23, 61, 8, ' لأني أنا الرب محب العدل ، مبغض المختلس بالظلم . وأجعل أجرتهم أمينة ، وأقطع لهم عهدا أبديا '),
(16921, 'Isaiah', 23, 61, 9, ' ويعرف بين الأمم نسلهم ، وذريتهم في وسط الشعوب . كل الذين يرونهم يعرفونهم أنهم نسل باركه الرب '),
(16922, 'Isaiah', 23, 61, 10, ' فرحا أفرح بالرب . تبتهج نفسي بإلهي ، لأنه قد ألبسني ثياب الخلاص . كساني رداء البر ، مثل عريس يتزين بعمامة ، ومثل عروس تتزين بحليها '),
(16923, 'Isaiah', 23, 61, 11, ' لأنه كما أن الأرض تخرج نباتها ، وكما أن الجنة تنبت مزروعاتها ، هكذا السيد الرب ينبت برا وتسبيحا أمام كل الأمم '),
(16924, 'Isaiah', 23, 62, 1, ' من أجل صهيون لا أسكت ، ومن أجل أورشليم لا أهدأ ، حتى يخرج برها كضياء وخلاصها كمصباح يتقد '),
(16925, 'Isaiah', 23, 62, 2, ' فترى الأمم برك ، وكل الملوك مجدك ، وتسمين باسم جديد يعينه فم الرب '),
(16926, 'Isaiah', 23, 62, 3, ' وتكونين إكليل جمال بيد الرب ، وتاجا ملكيا بكف إلهك '),
(16927, 'Isaiah', 23, 62, 4, ' لا يقال بعد لك : مهجورة ، ولا يقال بعد لأرضك : موحشة ، بل تدعين : حفصيبة ، وأرضك تدعى : بعولة . لأن الرب يسر بك ، وأرضك تصير ذات بعل '),
(16928, 'Isaiah', 23, 62, 5, ' لأنه كما يتزوج الشاب عذراء ، يتزوجك بنوك . وكفرح العريس بالعروس يفرح بك إلهك '),
(16929, 'Isaiah', 23, 62, 6, ' على أسوارك يا أورشليم أقمت حراسا لا يسكتون كل النهار وكل الليل على الدوام . يا ذاكري الرب لا تسكتوا '),
(16930, 'Isaiah', 23, 62, 7, ' ولا تدعوه يسكت ، حتى يثبت ويجعل أورشليم تسبيحة في الأرض '),
(16931, 'Isaiah', 23, 62, 8, ' حلف الرب بيمينه وبذراع عزته قائلا : إني لا أدفع بعد قمحك مأكلا لأعدائك ، ولا يشرب بنو الغرباء خمرك التي تعبت فيها '),
(16932, 'Isaiah', 23, 62, 9, ' بل يأكله الذين جنوه ويسبحون الرب ، ويشربه جامعوه في ديار قدسي '),
(16933, 'Isaiah', 23, 62, 10, ' اعبروا ، اعبروا بالأبواب ، هيئوا طريق الشعب . أعدوا ، أعدوا السبيل ، نقوه من الحجارة ، ارفعوا الراية للشعب '),
(16934, 'Isaiah', 23, 62, 11, ' هوذا الرب قد أخبر إلى أقصى الأرض ، قولوا لابنة صهيون : هوذا مخلصك آت . ها أجرته معه وجزاؤه أمامه '),
(16935, 'Isaiah', 23, 62, 12, ' ويسمونهم : شعبا مقدسا ، مفديي الرب . وأنت تسمين : المطلوبة ، المدينة غير المهجورة '),
(16936, 'Isaiah', 23, 63, 1, ' من ذا الآتي من أدوم ، بثياب حمر من بصرة ؟ هذا البهي بملابسه ، المتعظم بكثرة قوته . أنا المتكلم بالبر ، العظيم للخلاص '),
(16937, 'Isaiah', 23, 63, 2, ' ما بال لباسك محمر ، وثيابك كدائس المعصرة '),
(16938, 'Isaiah', 23, 63, 3, ' قد دست المعصرة وحدي ، ومن الشعوب لم يكن معي أحد . فدستهم بغضبي ، ووطئتهم بغيظي . فرش عصيرهم على ثيابي ، فلطخت كل ملابسي '),
(16939, 'Isaiah', 23, 63, 4, ' لأن يوم النقمة في قلبي ، وسنة مفديي قد أتت '),
(16940, 'Isaiah', 23, 63, 5, ' فنظرت ولم يكن معين ، وتحيرت إذ لم يكن عاضد ، فخلصت لي ذراعي ، وغيظي عضدني '),
(16941, 'Isaiah', 23, 63, 6, ' فدست شعوبا بغضبي وأسكرتهم بغيظي ، وأجريت على الأرض عصيرهم '),
(16942, 'Isaiah', 23, 63, 7, ' إحسانات الرب أذكر ، تسابيح الرب ، حسب كل ما كافأنا به الرب ، والخير العظيم لبيت إسرائيل الذي كافأهم به حسب مراحمه ، وحسب كثرة إحساناته '),
(16943, 'Isaiah', 23, 63, 8, ' وقد قال حقا : إنهم شعبي ، بنون لا يخونون . فصار لهم مخلصا '),
(16944, 'Isaiah', 23, 63, 9, ' في كل ضيقهم تضايق ، وملاك حضرته خلصهم . بمحبته ورأفته هو فكهم ورفعهم وحملهم كل الأيام القديمة '),
(16945, 'Isaiah', 23, 63, 10, ' ولكنهم تمردوا وأحزنوا روح قدسه ، فتحول لهم عدوا ، وهو حاربهم '),
(16946, 'Isaiah', 23, 63, 11, ' ثم ذكر الأيام القديمة ، موسى وشعبه : أين الذي أصعدهم من البحر مع راعي غنمه ؟ أين الذي جعل في وسطهم روح قدسه '),
(16947, 'Isaiah', 23, 63, 12, ' الذي سير ليمين موسى ذراع مجده ، الذي شق المياه قدامهم ليصنع لنفسه اسما أبديا '),
(16948, 'Isaiah', 23, 63, 13, ' الذي سيرهم في اللجج ، كفرس في البرية فلم يعثروا '),
(16949, 'Isaiah', 23, 63, 14, ' كبهائم تنزل إلى وطاء ، روح الرب أراحهم . هكذا قدت شعبك لتصنع لنفسك اسم مجد '),
(16950, 'Isaiah', 23, 63, 15, ' تطلع من السماوات وانظر من مسكن قدسك ومجدك : أين غيرتك وجبروتك ؟ زفير أحشائك ومراحمك نحوي امتنعت '),
(16951, 'Isaiah', 23, 63, 16, ' فإنك أنت أبونا وإن لم يعرفنا إبراهيم ، وإن لم يدرنا إسرائيل . أنت يارب أبونا ، ولينا منذ الأبد اسمك '),
(16952, 'Isaiah', 23, 63, 17, ' لماذا أضللتنا يارب عن طرقك ، قسيت قلوبنا عن مخافتك ؟ ارجع من أجل عبيدك ، أسباط ميراثك '),
(16953, 'Isaiah', 23, 63, 18, ' إلى قليل امتلك شعب قدسك . مضايقونا داسوا مقدسك '),
(16954, 'Isaiah', 23, 63, 19, ' قد كنا منذ زمان كالذين لم تحكم عليهم ، ولم يدع عليهم باسمك '),
(16955, 'Isaiah', 23, 64, 1, ' ليتك تشق السماوات وتنزل من حضرتك تتزلزل الجبال '),
(16956, 'Isaiah', 23, 64, 2, ' كما تشعل النار الهشيم ، وتجعل النار المياه تغلي ، لتعرف أعداءك اسمك ، لترتعد الأمم من حضرتك '),
(16957, 'Isaiah', 23, 64, 3, ' حين صنعت مخاوف لم ننتظرها ، نزلت ، تزلزلت الجبال من حضرتك '),
(16958, 'Isaiah', 23, 64, 4, ' ومنذ الأزل لم يسمعوا ولم يصغوا . لم تر عين إلها غيرك يصنع لمن ينتظره '),
(16959, 'Isaiah', 23, 64, 5, ' تلاقي الفرح الصانع البر . الذين يذكرونك في طرقك . ها أنت سخطت إذ أخطأنا . هي إلى الأبد فنخلص '),
(16960, 'Isaiah', 23, 64, 6, ' وقد صرنا كلنا كنجس ، وكثوب عدة كل أعمال برنا ، وقد ذبلنا كورقة ، وآثامنا كريح تحملنا '),
(16961, 'Isaiah', 23, 64, 7, ' وليس من يدعو باسمك أو ينتبه ليتمسك بك ، لأنك حجبت وجهك عنا ، وأذبتنا بسبب آثامنا '),
(16962, 'Isaiah', 23, 64, 8, ' والآن يارب أنت أبونا . نحن الطين وأنت جابلنا ، وكلنا عمل يديك '),
(16963, 'Isaiah', 23, 64, 9, ' لا تسخط كل السخط يارب ، ولا تذكر الإثم إلى الأبد . ها انظر . شعبك كلنا '),
(16964, 'Isaiah', 23, 64, 10, ' مدن قدسك صارت برية . صهيون صارت برية ، وأورشليم موحشة '),
(16965, 'Isaiah', 23, 64, 11, ' بيت قدسنا وجمالنا حيث سبحك آباؤنا ، قد صار حريق نار ، وكل مشتهياتنا صارت خرابا '),
(16966, 'Isaiah', 23, 64, 12, ' ألأجل هذه تتجلد يارب ؟ أتسكت وتذلنا كل الذل '),
(16967, 'Isaiah', 23, 65, 1, ' أصغيت إلى الذين لم يسألوا . وجدت من الذين لم يطلبوني . قلت : هأنذا ، هأنذا . لأمة لم تسم باسمي '),
(16968, 'Isaiah', 23, 65, 2, ' بسطت يدي طول النهار إلى شعب متمرد سائر في طريق غير صالح وراء أفكاره '),
(16969, 'Isaiah', 23, 65, 3, ' شعب يغيظني بوجهي . دائما يذبح في الجنات ، ويبخر على الآجر '),
(16970, 'Isaiah', 23, 65, 4, ' يجلس في القبور ، ويبيت في المدافن . يأكل لحم الخنزير ، وفي آنيته مرق لحوم نجسة '),
(16971, 'Isaiah', 23, 65, 5, ' يقول : قف عندك . لا تدن مني لأني أقدس منك . هؤلاء دخان في أنفي ، نار متقدة كل النهار '),
(16972, 'Isaiah', 23, 65, 6, ' ها قد كتب أمامي . لا أسكت بل أجازي . أجازي في حضنهم '),
(16973, 'Isaiah', 23, 65, 7, ' آثامكم وآثام آبائكم معا ، قال الرب ، الذين بخروا على الجبال ، وعيروني على الآكام ، فأكيل عملهم الأول في حضنهم '),
(16974, 'Isaiah', 23, 65, 8, ' هكذا قال الرب : كما أن السلاف يوجد في العنقود ، فيقول قائل : لا تهلكه لأن فيه بركة . هكذا أعمل لأجل عبيدي حتى لا أهلك الكل '),
(16975, 'Isaiah', 23, 65, 9, ' بل أخرج من يعقوب نسلا ومن يهوذا وارثا لجبالي ، فيرثها مختاري ، وتسكن عبيدي هناك '),
(16976, 'Isaiah', 23, 65, 10, ' فيكون شارون مرعى غنم ، ووادي عخور مربض بقر ، لشعبي الذين طلبوني '),
(16977, 'Isaiah', 23, 65, 11, ' أما أنتم الذين تركوا الرب ونسوا جبل قدسي ، ورتبوا للسعد الأكبر مائدة ، وملأوا للسعد الأصغر خمرا ممزوجة '),
(16978, 'Isaiah', 23, 65, 12, ' فإني أعينكم للسيف ، وتجثون كلكم للذبح ، لأني دعوت فلم تجيبوا ، تكلمت فلم تسمعوا ، بل عملتم الشر في عيني ، واخترتم ما لم أسر به '),
(16979, 'Isaiah', 23, 65, 13, ' لذلك هكذا قال السيد الرب : هوذا عبيدي يأكلون وأنتم تجوعون . هوذا عبيدي يشربون وأنتم تعطشون . هوذا عبيدي يفرحون وأنتم تخزون '),
(16980, 'Isaiah', 23, 65, 14, ' هوذا عبيدي يترنمون من طيبة القلب وأنتم تصرخون من كآبة القلب ، ومن انكسار الروح تولولون '),
(16981, 'Isaiah', 23, 65, 15, ' وتخلفون اسمكم لعنة لمختاري ، فيميتك السيد الرب ويسمي عبيده اسما آخر '),
(16982, 'Isaiah', 23, 65, 16, ' فالذي يتبرك في الأرض يتبرك بإله الحق ، والذي يحلف في الأرض يحلف بإله الحق ، لأن الضيقات الأولى قد نسيت ، ولأنها استترت عن عيني '),
(16983, 'Isaiah', 23, 65, 17, ' لأني هأنذا خالق سماوات جديدة وأرضا جديدة ، فلا تذكر الأولى ولا تخطر على بال '),
(16984, 'Isaiah', 23, 65, 18, ' بل افرحوا وابتهجوا إلى الأبد في ما أنا خالق ، لأني هأنذا خالق أورشليم بهجة وشعبها فرحا '),
(16985, 'Isaiah', 23, 65, 19, ' فأبتهج بأورشليم وأفرح بشعبي ، ولا يسمع بعد فيها صوت بكاء ولا صوت صراخ '),
(16986, 'Isaiah', 23, 65, 20, ' لا يكون بعد هناك طفل أيام ، ولا شيخ لم يكمل أيامه . لأن الصبي يموت ابن مئة سنة ، والخاطئ يلعن ابن مئة سنة '),
(16987, 'Isaiah', 23, 65, 21, ' ويبنون بيوتا ويسكنون فيها ، ويغرسون كروما ويأكلون أثمارها '),
(16988, 'Isaiah', 23, 65, 22, ' لا يبنون وآخر يسكن ، ولا يغرسون وآخر يأكل . لأنه كأيام شجرة أيام شعبي ، ويستعمل مختاري عمل أيديهم '),
(16989, 'Isaiah', 23, 65, 23, ' لا يتعبون باطلا ولا يلدون للرعب ، لأنهم نسل مباركي الرب ، وذريتهم معهم '),
(16990, 'Isaiah', 23, 65, 24, ' ويكون أني قبلما يدعون أنا أجيب ، وفيما هم يتكلمون بعد أنا أسمع '),
(16991, 'Isaiah', 23, 65, 25, ' الذئب والحمل يرعيان معا ، والأسد يأكل التبن كالبقر . أما الحية فالتراب طعامها . لا يؤذون ولا يهلكون في كل جبل قدسي ، قال الرب '),
(16992, 'Isaiah', 23, 66, 1, ' هكذا قال الرب : السماوات كرسيي ، والأرض موطئ قدمي . أين البيت الذي تبنون لي ؟ وأين مكان راحتي '),
(16993, 'Isaiah', 23, 66, 2, ' وكل هذه صنعتها يدي ، فكانت كل هذه ، يقول الرب . وإلى هذا أنظر : إلى المسكين والمنسحق الروح والمرتعد من كلامي '),
(16994, 'Isaiah', 23, 66, 3, ' من يذبح ثورا فهو قاتل إنسان . من يذبح شاة فهو ناحر كلب . من يصعد تقدمة يصعد دم خنزير . من أحرق لبانا فهو مبارك وثنا . بل هم اختاروا طرقهم ، وبمكرهاتهم سرت أنفسهم '),
(16995, 'Isaiah', 23, 66, 4, ' فأنا أيضا أختار مصائبهم ، ومخاوفهم أجلبها عليهم . من أجل أني دعوت فلم يكن مجيب . تكلمت فلم يسمعوا . بل عملوا القبيح في عيني ، واختاروا ما لم أسر به '),
(16996, 'Isaiah', 23, 66, 5, ' اسمعوا كلام الرب أيها المرتعدون من كلامه : قال إخوتكم الذين أبغضوكم وطردوكم من أجل اسمي : ليتمجد الرب . فيظهر لفرحكم ، وأما هم فيخزون '),
(16997, 'Isaiah', 23, 66, 6, ' صوت ضجيج من المدينة ، صوت من الهيكل ، صوت الرب مجازيا أعداءه '),
(16998, 'Isaiah', 23, 66, 7, ' قبل أن يأخذها الطلق ولدت . قبل أن يأتي عليها المخاض ولدت ذكرا '),
(16999, 'Isaiah', 23, 66, 8, ' من سمع مثل هذا ؟ من رأى مثل هذه ؟ هل تمخض بلاد في يوم واحد ، أو تولد أمة دفعة واحدة ؟ فقد مخضت صهيون ، بل ولدت بنيها '),
(17000, 'Isaiah', 23, 66, 9, ' هل أنا أمخض ولا أولد ، يقول الرب ، أو أنا المولد هل أغلق الرحم ، قال إلهك '),
(17001, 'Isaiah', 23, 66, 10, ' افرحوا مع أورشليم وابتهجوا معها ، يا جميع محبيها . افرحوا معها فرحا ، يا جميع النائحين عليها '),
(17002, 'Isaiah', 23, 66, 11, ' لكي ترضعوا وتشبعوا من ثدي تعزياتها ، لكي تعصروا وتتلذذوا من درة مجدها '),
(17003, 'Isaiah', 23, 66, 12, ' لأنه هكذا قال الرب : هأنذا أدير عليها سلاما كنهر ، ومجد الأمم كسيل جارف ، فترضعون ، وعلى الأيدي تحملون وعلى الركبتين تدللون '),
(17004, 'Isaiah', 23, 66, 13, ' كإنسان تعزيه أمه هكذا أعزيكم أنا ، وفي أورشليم تعزون '),
(17005, 'Isaiah', 23, 66, 14, ' فترون وتفرح قلوبكم ، وتزهو عظامكم كالعشب ، وتعرف يد الرب عند عبيده ، ويحنق على أعدائه '),
(17006, 'Isaiah', 23, 66, 15, ' لأنه هوذا الرب بالنار يأتي ، ومركباته كزوبعة ليرد بحمو غضبه ، وزجره بلهيب نار '),
(17007, 'Isaiah', 23, 66, 16, ' لأن الرب بالنار يعاقب وبسيفه على كل بشر ، ويكثر قتلى الرب '),
(17008, 'Isaiah', 23, 66, 17, ' الذين يقدسون ويطهرون أنفسهم في الجنات وراء واحد في الوسط ، آكلين لحم الخنزير والرجس والجرذ ، يفنون معا ، يقول الرب '),
(17009, 'Isaiah', 23, 66, 18, ' وأنا أجازي أعمالهم وأفكارهم . حدث لجمع كل الأمم والألسنة ، فيأتون ويرون مجدي '),
(17010, 'Isaiah', 23, 66, 19, ' وأجعل فيهم آية ، وأرسل منهم ناجين إلى الأمم ، إلى ترشيش وفول ولود النازعين في القوس ، إلى توبال وياوان ، إلى الجزائر البعيدة التي لم تسمع خبري ولا رأت مجدي ، فيخبرون بمجدي بين الأمم '),
(17011, 'Isaiah', 23, 66, 20, ' ويحضرون كل إخوتكم من كل الأمم ، تقدمة للرب ، على خيل وبمركبات وبهوادج وبغال وهجن إلى جبل قدسي أورشليم ، قال الرب ، كما يحضر بنو إسرائيل تقدمة في إناء طاهر إلى بيت الرب '),
(17012, 'Isaiah', 23, 66, 21, ' وأتخذ أيضا منهم كهنة ولاويين ، قال الرب '),
(17013, 'Isaiah', 23, 66, 22, ' لأنه كما أن السماوات الجديدة والأرض الجديدة التي أنا صانع تثبت أمامي ، يقول الرب ، هكذا يثبت نسلكم واسمكم '),
(17014, 'Isaiah', 23, 66, 23, ' ويكون من هلال إلى هلال ومن سبت إلى سبت ، أن كل ذي جسد يأتي ليسجد أمامي ، قال الرب '),
(17015, 'Isaiah', 23, 66, 24, ' ويخرجون ويرون جثث الناس الذين عصوا علي ، لأن دودهم لا يموت ونارهم لا تطفأ ، ويكونون رذالة لكل ذي جسد '),
(17016, 'Isaiah', 23, 44, 18, ' لا يعرفون ولا يفهمون لأنه قد طمست عيونهم عن الإبصار ، وقلوبهم عن التعقل '),
(17017, 'Isaiah', 23, 44, 19, ' ولا يردد في قلبه وليس له معرفة ولا فهم حتى يقول : نصفه قد أحرقت بالنار ، وخبزت أيضا على جمره خبزا ، شويت لحما وأكلت . أفأصنع بقيته رجسا ، ولساق شجرة أخر '),
(17018, 'Isaiah', 23, 44, 20, ' يرعى رمادا . قلب مخدوع قد أضله فلا ينجي نفسه ولا يقول : أليس كذب في يميني '),
(17019, 'Isaiah', 23, 44, 21, ' اذكر هذه يا يعقوب ، يا إسرائيل ، فإنك أنت عبدي . قد جبلتك . عبد لي أنت . يا إسرائيل لا تنسي مني '),
(17020, 'Isaiah', 23, 44, 22, ' قد محوت كغيم ذنوبك وكسحابة خطاياك . ارجع إلي لأني فديتك '),
(17021, 'Isaiah', 23, 44, 23, ' ترنمي أيتها السماوات لأن الرب قد فعل . اهتفي يا أسافل الأرض . أشيدي أيتها الجبال ترنما ، الوعر وكل شجرة فيه ، لأن الرب قد فدى يعقوب ، وفي إسرائيل تمجد '),
(17022, 'Isaiah', 23, 44, 24, ' هكذا يقول الرب فاديك وجابلك من البطن : أنا الرب صانع كل شيء ، ناشر السماوات وحدي ، باسط الأرض . من معي '),
(17023, 'Isaiah', 23, 44, 25, ' مبطل آيات المخادعين ومحمق العرافين . مرجع الحكماء إلى الوراء ، ومجهل معرفتهم '),
(17024, 'Isaiah', 23, 44, 26, ' مقيم كلمة عبده ، ومتمم رأي رسله . القائل عن أورشليم : ستعمر ، ولمدن يهوذا : ستبنين ، وخربها أقيم '),
(17025, 'Isaiah', 23, 44, 27, ' القائل للجة : انشفي ، وأنهارك أجفف '),
(17026, 'Isaiah', 23, 44, 28, ' القائل عن كورش : راعي ، فكل مسرتي يتمم . ويقول عن أورشليم : ستبنى ، وللهيكل : ستؤسس '),
(17027, 'Isaiah', 23, 45, 1, ' هكذا يقول الرب لمسيحه ، لكورش الذي أمسكت بيمينه لأدوس أمامه أمما ، وأحقاء ملوك أحل ، لأفتح أمامه المصراعين ، والأبواب لا تغلق '),
(17028, 'Isaiah', 23, 45, 2, ' أنا أسير قدامك والهضاب أمهد . أكسر مصراعي النحاس ، ومغاليق الحديد أقصف '),
(17029, 'Isaiah', 23, 45, 3, ' وأعطيك ذخائر الظلمة وكنوز المخابئ ، لكي تعرف أني أنا الرب الذي يدعوك باسمك ، إله إسرائيل '),
(17030, 'Isaiah', 23, 45, 4, ' لأجل عبدي يعقوب ، وإسرائيل مختاري ، دعوتك باسمك . لقبتك وأنت لست تعرفني '),
(17031, 'Isaiah', 23, 45, 5, ' أنا الرب وليس آخر . لا إله سواي . نطقتك وأنت لم تعرفني '),
(17032, 'Isaiah', 23, 45, 6, ' لكي يعلموا من مشرق الشمس ومن مغربها أن ليس غيري . أنا الرب وليس آخر '),
(17033, 'Isaiah', 23, 45, 7, ' مصور النور وخالق الظلمة ، صانع السلام وخالق الشر . أنا الرب صانع كل هذه '),
(17034, 'Isaiah', 23, 45, 8, ' اقطري أيتها السماوات من فوق ، ولينزل الجو برا . لتنفتح الأرض فيثمر الخلاص ، ولتنبت برا معا . أنا الرب قد خلقته '),
(17035, 'Isaiah', 23, 45, 9, ' ويل لمن يخاصم جابله . خزف بين أخزاف الأرض . هل يقول الطين لجابله : ماذا تصنع ؟ أو يقول : عملك ليس له يدان '),
(17036, 'Isaiah', 23, 45, 10, ' ويل للذي يقول لأبيه : ماذا تلد ؟ وللمرأة : ماذا تلدين '),
(17037, 'Isaiah', 23, 45, 11, ' هكذا يقول الرب قدوس إسرائيل وجابله : اسألوني عن الآتيات من جهة بني ومن جهة عمل يدي أوصوني '),
(17038, 'Isaiah', 23, 45, 12, ' أنا صنعت الأرض وخلقت الإنسان عليها . يداي أنا نشرتا السماوات ، وكل جندها أنا أمرت '),
(17039, 'Isaiah', 23, 45, 13, ' أنا قد أنهضته بالنصر ، وكل طرقه أسهل . هو يبني مدينتي ويطلق سبيي ، لا بثمن ولا بهدية ، قال رب الجنود '),
(17040, 'Isaiah', 23, 45, 14, ' هكذا قال الرب : تعب مصر وتجارة كوش والسبئيون ذوو القامة إليك يعبرون ولك يكونون . خلفك يمشون . بالقيود يمرون ولك يسجدون . إليك يتضرعون قائلين : فيك وحدك الله وليس آخر . ليس إله '),
(17041, 'Isaiah', 23, 45, 15, ' حقا أنت إله محتجب يا إله إسرائيل المخلص '),
(17042, 'Isaiah', 23, 45, 16, ' قد خزوا وخجلوا كلهم . مضوا بالخجل جميعا ، الصانعون التماثيل '),
(17043, 'Isaiah', 23, 45, 17, ' أما إسرائيل فيخلص بالرب خلاصا أبديا . لا تخزون ولا تخجلون إلى دهور الأبد '),
(17044, 'Isaiah', 23, 45, 18, ' لأنه هكذا قال الرب : خالق السماوات هو الله . مصور الأرض وصانعها . هو قررها . لم يخلقها باطلا . للسكن صورها . أنا الرب وليس آخر '),
(17045, 'Isaiah', 23, 45, 19, ' لم أتكلم بالخفاء في مكان من الأرض مظلم . لم أقل لنسل يعقوب : باطلا اطلبوني . أنا الرب متكلم بالصدق ، مخبر بالاستقامة '),
(17046, 'Isaiah', 23, 45, 20, ' اجتمعوا وهلموا تقدموا معا أيها الناجون من الأمم . لا يعلم الحاملون خشب صنمهم ، والمصلون إلى إله لا يخلص '),
(17047, 'Isaiah', 23, 45, 21, ' أخبروا . قدموا . وليتشاوروا معا . من أعلم بهذه منذ القديم ، أخبر بها منذ زمان ؟ أليس أنا الرب ولا إله آخر غيري ؟ إله بار ومخلص . ليس سواي '),
(17048, 'Isaiah', 23, 45, 22, ' التفتوا إلي واخلصوا يا جميع أقاصي الأرض ، لأني أنا الله وليس آخر '),
(17049, 'Isaiah', 23, 45, 23, ' بذاتي أقسمت ، خرج من فمي الصدق كلمة لا ترجع : إنه لي تجثو كل ركبة ، يحلف كل لسان '),
(17050, 'Isaiah', 23, 45, 24, ' قال لي : إنما بالرب البر والقوة . إليه يأتي ، ويخزى جميع المغتاظين عليه '),
(17051, 'Isaiah', 23, 45, 25, ' بالرب يتبرر ويفتخر كل نسل إسرائيل '),
(17052, 'Isaiah', 23, 46, 1, ' قد جثا بيل ، انحنى نبو . صارت تماثيلهما على الحيوانات والبهائم . محمولاتكم محملة حملا للمعيي '),
(17053, 'Isaiah', 23, 46, 2, ' قد انحنت . جثت معا . لم تقدر أن تنجي الحمل ، وهي نفسها قد مضت في السبي '),
(17054, 'Isaiah', 23, 46, 3, ' اسمعوا لي يا بيت يعقوب وكل بقية بيت إسرائيل ، المحملين علي من البطن ، المحمولين من الرحم '),
(17055, 'Isaiah', 23, 46, 4, ' وإلى الشيخوخة أنا هو ، وإلى الشيبة أنا أحمل . قد فعلت ، وأنا أرفع ، وأنا أحمل وأنجي '),
(17056, 'Isaiah', 23, 46, 5, ' بمن تشبهونني وتسوونني وتمثلونني لنتشابه '),
(17057, 'Isaiah', 23, 46, 6, ' الذين يفرغون الذهب من الكيس ، والفضة بالميزان يزنون . يستأجرون صائغا ليصنعها إلها ، يخرون ويسجدون '),
(17058, 'Isaiah', 23, 46, 7, ' يرفعونه على الكتف . يحملونه ويضعونه في مكانه ليقف . من موضعه لا يبرح . يزعق أحد إليه فلا يجيب . من شدته لا يخلصه '),
(17059, 'Isaiah', 23, 46, 8, ' اذكروا هذا وكونوا رجالا . رددوه في قلوبكم أيها العصاة '),
(17060, 'Isaiah', 23, 46, 9, ' اذكروا الأوليات منذ القديم ، لأني أنا الله وليس آخر . الإله وليس مثلي '),
(17061, 'Isaiah', 23, 46, 10, ' مخبر منذ البدء بالأخير ، ومنذ القديم بما لم يفعل ، قائلا : رأيي يقوم وأفعل كل مسرتي '),
(17062, 'Isaiah', 23, 46, 11, ' داع من المشرق الكاسر ، من أرض بعيدة رجل مشورتي . قد تكلمت فأجريه . قضيت فأفعله '),
(17063, 'Isaiah', 23, 46, 12, ' اسمعوا لي يا أشداء القلوب البعيدين عن البر '),
(17064, 'Isaiah', 23, 46, 13, ' قد قربت بري ، لا يبعد . وخلاصي لا يتأخر . وأجعل في صهيون خلاصا ، لإسرائيل جلالي '),
(17065, 'Isaiah', 23, 47, 1, ' انزلي واجلسي على التراب أيتها العذراء ابنة بابل . اجلسي على الأرض بلا كرسي يا ابنة الكلدانيين ، لأنك لا تعودين تدعين ناعمة ومترفهة '),
(17066, 'Isaiah', 23, 47, 2, ' خذي الرحى واطحني دقيقا . اكشفي نقابك . شمري الذيل . اكشفي الساق . اعبري الأنهار '),
(17067, 'Isaiah', 23, 47, 3, ' تنكشف عورتك وترى معاريك . آخذ نقمة ولا أصالح أحدا '),
(17068, 'Isaiah', 23, 47, 4, ' فادينا رب الجنود اسمه . قدوس إسرائيل '),
(17069, 'Isaiah', 23, 47, 5, ' اجلسي صامتة وادخلي في الظلام يا ابنة الكلدانيين ، لأنك لا تعودين تدعين سيدة الممالك '),
(17070, 'Isaiah', 23, 47, 6, ' غضبت على شعبي . دنست ميراثي ودفعتهم إلى يدك . لم تصنعي لهم رحمة . على الشيخ ثقلت نيرك جدا '),
(17071, 'Isaiah', 23, 47, 7, ' وقلت : إلى الأبد أكون سيدة حتى لم تضعي هذه في قلبك . لم تذكري آخرتها '),
(17072, 'Isaiah', 23, 47, 8, ' فالآن اسمعي هذا أيتها المتنعمة الجالسة بالطمأنينة ، القائلة في قلبها : أنا وليس غيري . لا أقعد أرملة ولا أعرف الثكل '),
(17073, 'Isaiah', 23, 47, 9, ' فيأتي عليك هذان الاثنان بغتة في يوم واحد : الثكل والترمل . بالتمام قد أتيا عليك مع كثرة سحورك ، مع وفور رقاك جدا '),
(17074, 'Isaiah', 23, 47, 10, ' وأنت اطمأننت في شرك . قلت : ليس من يراني . حكمتك ومعرفتك هما أفتناك ، فقلت في قلبك : أنا وليس غيري '),
(17075, 'Isaiah', 23, 47, 11, ' فيأتي عليك شر لا تعرفين فجره ، وتقع عليك مصيبة لا تقدرين أن تصديها ، وتأتي عليك بغتة تهلكة لا تعرفين بها '),
(17076, 'Isaiah', 23, 47, 12, ' قفي في رقاك وفي كثرة سحورك التي فيها تعبت منذ صباك ، ربما يمكنك أن تنفعي ، ربما ترعبين '),
(17077, 'Isaiah', 23, 47, 13, ' قد ضعفت من كثرة مشوراتك . ليقف قاسمو السماء الراصدون النجوم ، المعرفون عند رؤوس الشهور ، ويخلصوك مما يأتي عليك '),
(17078, 'Isaiah', 23, 47, 14, ' ها إنهم قد صاروا كالقش . أحرقتهم النار . لا ينجون أنفسهم من يد اللهيب . ليس هو جمرا للاستدفاء ولا نارا للجلوس تجاهها '),
(17079, 'Isaiah', 23, 47, 15, ' هكذا صار لك الذين تعبت فيهم . تجارك منذ صباك قد شردوا كل واحد على وجهه ، وليس من يخلصك '),
(17080, 'Isaiah', 23, 48, 1, ' اسمعوا هذا يا بيت يعقوب ، المدعوين باسم إسرائيل ، الذين خرجوا من مياه يهوذا ، الحالفين باسم الرب ، والذين يذكرون إله إسرائيل ، ليس بالصدق ولا بالحق '),
(17081, 'Isaiah', 23, 48, 2, ' فإنهم يسمون من مدينة القدس ويسندون إلى إله إسرائيل . رب الجنود اسمه '),
(17082, 'Isaiah', 23, 48, 3, ' بالأوليات منذ زمان أخبرت ، ومن فمي خرجت وأنبأت بها . بغتة صنعتها فأتت '),
(17083, 'Isaiah', 23, 48, 4, ' لمعرفتي أنك قاس ، وعضل من حديد عنقك ، وجبهتك نحاس '),
(17084, 'Isaiah', 23, 48, 5, ' أخبرتك منذ زمان . قبلما أتت أنبأتك ، لئلا تقول : صنمي قد صنعها ، ومنحوتي ومسبوكي أمر بها '),
(17085, 'Isaiah', 23, 48, 6, ' قد سمعت فانظر كلها . وأنتم ألا تخبرون ؟ قد أنبأتك بحديثات منذ الآن ، وبمخفيات لم تعرفها '),
(17086, 'Isaiah', 23, 48, 7, ' الآن خلقت وليس منذ زمان ، وقبل اليوم لم تسمع بها ، لئلا تقول : هأنذا قد عرفتها '),
(17087, 'Isaiah', 23, 48, 8, ' لم تسمع ولم تعرف ، ومنذ زمان لم تنفتح أذنك ، فإني علمت أنك تغدر غدرا ، ومن البطن سميت عاصيا '),
(17088, 'Isaiah', 23, 48, 9, ' من أجل اسمي أبطئ غضبي ، ومن أجل فخري أمسك عنك حتى لا أقطعك '),
(17089, 'Isaiah', 23, 48, 10, ' هأنذا قد نقيتك وليس بفضة . اخترتك في كور المشقة '),
(17090, 'Isaiah', 23, 48, 11, ' من أجل نفسي ، من أجل نفسي أفعل . لأنه كيف يدنس اسمي ؟ وكرامتي لا أعطيها لآخر '),
(17091, 'Isaiah', 23, 57, 10, ' بطول أسفارك أعييت ، ولم تقولي : يئست . شهوتك وجدت ، لذلك لم تضعفي '),
(17092, 'Isaiah', 23, 57, 11, ' وممن خشيت وخفت حتى خنت ، وإياي لم تذكري ، ولا وضعت في قلبك ؟ أما أنا ساكت ، وذلك منذ القديم ، فإياي لم تخافي '),
(17093, 'Isaiah', 23, 57, 12, ' أنا أخبر ببرك وبأعمالك فلا تفيدك '),
(17094, 'Isaiah', 23, 57, 13, ' إذ تصرخين فلينقذك جموعك . ولكن الريح تحملهم كلهم . تأخذهم نفخة . أما المتوكل علي فيملك الأرض ويرث جبل قدسي '),
(17095, 'Isaiah', 23, 57, 14, ' ويقول : أعدوا ، أعدوا . هيئوا الطريق . ارفعوا المعثرة من طريق شعبي '),
(17096, 'Isaiah', 23, 57, 15, ' لأنه هكذا قال العلي المرتفع ، ساكن الأبد ، القدوس اسمه : في الموضع المرتفع المقدس أسكن ، ومع المنسحق والمتواضع الروح ، لأحيي روح المتواضعين ، ولأحيي قلب المنسحقين '),
(17097, 'Isaiah', 23, 57, 16, ' لأني لا أخاصم إلى الأبد ، ولا أغضب إلى الدهر . لأن الروح يغشى عليها أمامي ، والنسمات التي صنعتها '),
(17098, 'Isaiah', 23, 57, 17, ' من أجل إثم مكسبه غضبت وضربته . استترت وغضبت ، فذهب عاصيا في طريق قلبه '),
(17099, 'Isaiah', 23, 57, 18, ' رأيت طرقه وسأشفيه وأقوده ، وأرد تعزيات له ولنائحيه '),
(17100, 'Isaiah', 23, 57, 19, ' خالقا ثمر الشفتين . سلام سلام للبعيد وللقريب ، قال الرب ، وسأشفيه '),
(17101, 'Isaiah', 23, 57, 20, ' أما الأشرار فكالبحر المضطرب لأنه لا يستطيع أن يهدأ ، وتقذف مياهه حمأة وطينا '),
(17102, 'Isaiah', 23, 57, 21, ' ليس سلام ، قال إلهي ، للأشرار '),
(17103, 'Isaiah', 23, 58, 1, ' ناد بصوت عال . لا تمسك . ارفع صوتك كبوق وأخبر شعبي بتعديهم ، وبيت يعقوب بخطاياهم '),
(17104, 'Isaiah', 23, 58, 2, ' وإياي يطلبون يوما فيوما ، ويسرون بمعرفة طرقي كأمة عملت برا ، ولم تترك قضاء إلهها . يسألونني عن أحكام البر . يسرون بالتقرب إلى الله '),
(17105, 'Isaiah', 23, 58, 3, ' يقولون : لماذا صمنا ولم تنظر ، ذللنا أنفسنا ولم تلاحظ ؟ ها إنكم في يوم صومكم توجدون مسرة ، وبكل أشغالكم تسخرون '),
(17106, 'Isaiah', 23, 58, 4, ' ها إنكم للخصومة والنزاع تصومون ، ولتضربوا بلكمة الشر . لستم تصومون كما اليوم لتسميع صوتكم في العلاء '),
(17107, 'Isaiah', 23, 58, 5, ' أمثل هذا يكون صوم أختاره ؟ يوما يذلل الإنسان فيه نفسه ، يحني كالأسلة رأسه ، ويفرش تحته مسحا ورمادا . هل تسمي هذا صوما ويوما مقبولا للرب '),
(17108, 'Isaiah', 23, 58, 6, ' أليس هذا صوما أختاره : حل قيود الشر . فك عقد النير ، وإطلاق المسحوقين أحرارا ، وقطع كل نير '),
(17109, 'Isaiah', 23, 58, 7, ' أليس أن تكسر للجائع خبزك ، وأن تدخل المساكين التائهين إلى بيتك ؟ إذا رأيت عريانا أن تكسوه ، وأن لا تتغاضى عن لحمك '),
(17110, 'Isaiah', 23, 58, 8, ' حينئذ ينفجر مثل الصبح نورك ، وتنبت صحتك سريعا ، ويسير برك أمامك ، ومجد الرب يجمع ساقتك '),
(17111, 'Isaiah', 23, 58, 9, ' حينئذ تدعو فيجيب الرب . تستغيث فيقول : هأنذا . إن نزعت من وسطك النير والإيماء بالأصبع وكلام الإثم '),
(17112, 'Isaiah', 23, 58, 10, ' وأنفقت نفسك للجائع ، وأشبعت النفس الذليلة ، يشرق في الظلمة نورك ، ويكون ظلامك الدامس مثل الظهر '),
(17113, 'Isaiah', 23, 58, 11, ' ويقودك الرب على الدوام ، ويشبع في الجدوب نفسك ، وينشط عظامك ، فتصير كجنة ريا وكنبع مياه لا تنقطع مياهه '),
(17114, 'Isaiah', 23, 58, 12, ' ومنك تبنى الخرب القديمة . تقيم أساسات دور فدور ، فيسمونك : مرمم الثغرة ، مرجع المسالك للسكنى '),
(17115, 'Isaiah', 23, 58, 13, ' إن رددت عن السبت رجلك ، عن عمل مسرتك يوم قدسي ، ودعوت السبت لذة ، ومقدس الرب مكرما ، وأكرمته عن عمل طرقك وعن إيجاد مسرتك والتكلم بكلامك '),
(17116, 'Isaiah', 23, 58, 14, ' فإنك حينئذ تتلذذ بالرب ، وأركبك على مرتفعات الأرض ، وأطعمك ميراث يعقوب أبيك ، لأن فم الرب تكلم '),
(17117, 'Isaiah', 23, 59, 1, ' ها إن يد الرب لم تقصر عن أن تخلص ، ولم تثقل أذنه عن أن تسمع '),
(17118, 'Isaiah', 23, 59, 2, ' بل آثامكم صارت فاصلة بينكم وبين إلهكم ، وخطاياكم سترت وجهه عنكم حتى لا يسمع '),
(17119, 'Isaiah', 23, 59, 3, ' لأن أيديكم قد تنجست بالدم ، وأصابعكم بالإثم . شفاهكم تكلمت بالكذب ، ولسانكم يلهج بالشر '),
(17120, 'Isaiah', 23, 59, 4, ' ليس من يدعو بالعدل ، وليس من يحاكم بالحق . يتكلون على الباطل ، ويتكلمون بالكذب . قد حبلوا بتعب ، وولدوا إثما '),
(17121, 'Isaiah', 23, 59, 5, ' فقسوا بيض أفعى ، ونسجوا خيوط العنكبوت . الآكل من بيضهم يموت ، والتي تكسر تخرج أفعى '),
(17122, 'Isaiah', 23, 59, 6, ' خيوطهم لا تصير ثوبا ، ولا يكتسون بأعمالهم . أعمالهم أعمال إثم ، وفعل الظلم في أيديهم '),
(17123, 'Isaiah', 23, 59, 7, ' أرجلهم إلى الشر تجري ، وتسرع إلى سفك الدم الزكي . أفكارهم أفكار إثم . في طرقهم اغتصاب وسحق '),
(17124, 'Isaiah', 23, 59, 8, ' طريق السلام لم يعرفوه ، وليس في مسالكهم عدل . جعلوا لأنفسهم سبلا معوجة . كل من يسير فيها لا يعرف سلاما '),
(17125, 'Isaiah', 23, 59, 9, ' من أجل ذلك ابتعد الحق عنا ، ولم يدركنا العدل . ننتظر نورا فإذا ظلام . ضياء فنسير في ظلام دامس '),
(17126, 'Isaiah', 23, 59, 10, ' نتلمس الحائط كعمي ، وكالذي بلا أعين نتجسس . قد عثرنا في الظهر كما في العتمة ، في الضباب كموتى '),
(17127, 'Isaiah', 23, 59, 11, ' نزأر كلنا كدبة ، وكحمام هدرا نهدر . ننتظر عدلا وليس هو ، وخلاصا فيبتعد عنا '),
(17128, 'Isaiah', 23, 59, 12, ' لأن معاصينا كثرت أمامك ، وخطايانا تشهد علينا ، لأن معاصينا معنا ، وآثامنا نعرفها '),
(17129, 'Isaiah', 23, 59, 13, ' تعدينا وكذبنا على الرب ، وحدنا من وراء إلهنا . تكلمنا بالظلم والمعصية . حبلنا ولهجنا من القلب بكلام الكذب '),
(17130, 'Isaiah', 23, 59, 14, ' وقد ارتد الحق إلى الوراء ، والعدل يقف بعيدا . لأن الصدق سقط في الشارع ، والاستقامة لا تستطيع الدخول '),
(17131, 'Isaiah', 23, 59, 15, ' وصار الصدق معدوما ، والحائد عن الشر يسلب . فرأى الرب وساء في عينيه أنه ليس عدل '),
(17132, 'Isaiah', 23, 59, 16, ' فرأى أنه ليس إنسان ، وتحير من أنه ليس شفيع . فخلصت ذراعه لنفسه ، وبره هو عضده '),
(17133, 'Isaiah', 23, 59, 17, ' فلبس البر كدرع ، وخوذة الخلاص على رأسه . ولبس ثياب الانتقام كلباس ، واكتسى بالغيرة كرداء '),
(17134, 'Isaiah', 23, 59, 18, ' حسب الأعمال هكذا يجازي مبغضيه سخطا ، وأعداءه عقابا . جزاء يجازي الجزائر '),
(17135, 'Isaiah', 23, 59, 19, ' فيخافون من المغرب اسم الرب ، ومن مشرق الشمس مجده . عندما يأتي العدو كنهر فنفخة الرب تدفعه '),
(17136, 'Isaiah', 23, 59, 20, ' ويأتي الفادي إلى صهيون وإلى التائبين عن المعصية في يعقوب ، يقول الرب '),
(17137, 'Isaiah', 23, 59, 21, ' أما أنا فهذا عهدي معهم ، قال الرب : روحي الذي عليك ، وكلامي الذي وضعته في فمك لا يزول من فمك ، ولا من فم نسلك ، ولا من فم نسل نسلك ، قال الرب ، من الآن وإلى الأبد '),
(17138, 'Isaiah', 23, 60, 1, ' قومي استنيري لأنه قد جاء نورك ، ومجد الرب أشرق عليك '),
(17139, 'Isaiah', 23, 60, 2, ' لأنه ها هي الظلمة تغطي الأرض والظلام الدامس الأمم . أما عليك فيشرق الرب ، ومجده عليك يرى '),
(17140, 'Isaiah', 23, 60, 3, ' فتسير الأمم في نورك ، والملوك في ضياء إشراقك '),
(17141, 'Isaiah', 23, 60, 4, ' ارفعي عينيك حواليك وانظري . قد اجتمعوا كلهم . جاءوا إليك . يأتي بنوك من بعيد وتحمل بناتك على الأيدي '),
(17142, 'Isaiah', 23, 60, 5, ' حينئذ تنظرين وتنيرين ويخفق قلبك ويتسع ، لأنه تتحول إليك ثروة البحر ، ويأتي إليك غنى الأمم '),
(17143, 'Isaiah', 23, 60, 6, ' تغطيك كثرة الجمال ، بكران مديان وعيفة كلها تأتي من شبا . تحمل ذهبا ولبانا ، وتبشر بتسابيح الرب '),
(17144, 'Isaiah', 23, 60, 7, ' كل غنم قيدار تجتمع إليك . كباش نبايوت تخدمك . تصعد مقبولة على مذبحي ، وأزين بيت جمالي '),
(17145, 'Isaiah', 23, 60, 8, ' من هؤلاء الطائرون كسحاب وكالحمام إلى بيوتها '),
(17146, 'Isaiah', 23, 60, 9, ' إن الجزائر تنتظرني ، وسفن ترشيش في الأول ، لتأتي ببنيك من بعيد وفضتهم وذهبهم معهم ، لاسم الرب إلهك وقدوس إسرائيل ، لأنه قد مجدك '),
(17147, 'Isaiah', 23, 60, 10, ' وبنو الغريب يبنون أسوارك ، وملوكهم يخدمونك . لأني بغضبي ضربتك ، وبرضواني رحمتك '),
(17148, 'Isaiah', 23, 60, 11, ' وتنفتح أبوابك دائما . نهارا وليلا لا تغلق . ليؤتى إليك بغنى الأمم ، وتقاد ملوكهم '),
(17149, 'Isaiah', 23, 60, 12, ' لأن الأمة والمملكة التي لا تخدمك تبيد ، وخرابا تخرب الأمم '),
(17150, 'Isaiah', 23, 60, 13, ' مجد لبنان إليك يأتي . السرو والسنديان والشربين معا لزينة مكان مقدسي ، وأمجد موضع رجلي '),
(17151, 'Isaiah', 23, 60, 14, ' وبنو الذين قهروك يسيرون إليك خاضعين ، وكل الذين أهانوك يسجدون لدى باطن قدميك ، ويدعونك : مدينة الرب ، صهيون قدوس إسرائيل '),
(17152, 'Isaiah', 23, 60, 15, ' عوضا عن كونك مهجورة ومبغضة بلا عابر بك ، أجعلك فخرا أبديا فرح دور فدور '),
(17153, 'Isaiah', 23, 60, 16, ' وترضعين لبن الأمم ، وترضعين ثدي ملوك ، وتعرفين أني أنا الرب مخلصك ووليك عزيز يعقوب '),
(17154, 'Isaiah', 23, 60, 17, ' عوضا عن النحاس آتي بالذهب ، وعوضا عن الحديد آتي بالفضة ، وعوضا عن الخشب بالنحاس ، وعوضا عن الحجارة بالحديد ، وأجعل وكلاءك سلاما وولاتك برا '),
(17155, 'Isaiah', 23, 60, 18, ' لا يسمع بعد ظلم في أرضك ، ولا خراب أو سحق في تخومك ، بل تسمين أسوارك : خلاصا وأبوابك : تسبيحا '),
(17156, 'Isaiah', 23, 60, 19, ' لا تكون لك بعد الشمس نورا في النهار ، ولا القمر ينير لك مضيئا ، بل الرب يكون لك نورا أبديا وإلهك زينتك '),
(17157, 'Isaiah', 23, 60, 20, ' لا تغيب بعد شمسك ، وقمرك لا ينقص ، لأن الرب يكون لك نورا أبديا ، وتكمل أيام نوحك '),
(17158, 'Isaiah', 23, 60, 21, ' وشعبك كلهم أبرار . إلى الأبد يرثون الأرض ، غصن غرسي عمل يدي لأتمجد '),
(17159, 'Isaiah', 23, 60, 22, ' الصغير يصير ألفا والحقير أمة قوية . أنا الرب في وقته أسرع به '),
(17160, 'Isaiah', 23, 61, 1, ' روح السيد الرب علي ، لأن الرب مسحني لأبشر المساكين ، أرسلني لأعصب منكسري القلب ، لأنادي للمسبيين بالعتق ، وللمأسورين بالإطلاق '),
(17161, 'Isaiah', 23, 61, 2, ' لأنادي بسنة مقبولة للرب ، وبيوم انتقام لإلهنا . لأعزي كل النائحين '),
(17162, 'Isaiah', 23, 61, 3, ' لأجعل لنائحي صهيون ، لأعطيهم جمالا عوضا عن الرماد ، ودهن فرح عوضا عن النوح ، ورداء تسبيح عوضا عن الروح اليائسة ، فيدعون أشجار البر ، غرس الرب للتمجيد '),
(17163, 'Isaiah', 23, 61, 4, ' ويبنون الخرب القديمة . يقيمون الموحشات الأول ، ويجددون المدن الخربة ، موحشات دور فدور '),
(17164, 'Isaiah', 23, 61, 5, ' ويقف الأجانب ويرعون غنمكم ، ويكون بنو الغريب حراثيكم وكراميكم '),
(17165, 'James', 59, 1, 1, ' يعقوب ، عبد الله والرب يسوع المسيح ، يهدي السلام إلى الاثني عشر سبطا الذين في الشتات '),
(17166, 'James', 59, 1, 2, ' احسبوه كل فرح يا إخوتي حينما تقعون في تجارب متنوعة '),
(17167, 'James', 59, 1, 3, ' عالمين أن امتحان إيمانكم ينشئ صبرا '),
(17168, 'James', 59, 1, 4, ' وأما الصبر فليكن له عمل تام ، لكي تكونوا تامين وكاملين غير ناقصين في شيء '),
(17169, 'James', 59, 1, 5, ' وإنما إن كان أحدكم تعوزه حكمة ، فليطلب من الله الذي يعطي الجميع بسخاء ولا يعير ، فسيعطى له '),
(17170, 'James', 59, 1, 6, ' ولكن ليطلب بإيمان غير مرتاب البتة ، لأن المرتاب يشبه موجا من البحر تخبطه الريح وتدفعه '),
(17171, 'James', 59, 1, 7, ' فلا يظن ذلك الإنسان أنه ينال شيئا من عند الرب '),
(17172, 'James', 59, 1, 8, ' رجل ذو رأيين هو متقلقل في جميع طرقه '),
(17173, 'James', 59, 1, 9, ' وليفتخر الأخ المتضع بارتفاعه '),
(17174, 'James', 59, 1, 10, ' وأما الغني فباتضاعه ، لأنه كزهر العشب يزول '),
(17175, 'James', 59, 1, 11, ' لأن الشمس أشرقت بالحر ، فيبست العشب ، فسقط زهره وفني جمال منظره . هكذا يذبل الغني أيضا في طرقه '),
(17176, 'James', 59, 1, 12, ' طوبى للرجل الذي يحتمل التجربة ، لأنه إذا تزكى ينال إكليل الحياة الذي وعد به الرب للذين يحبونه '),
(17177, 'James', 59, 1, 13, ' لا يقل أحد إذا جرب : إني أجرب من قبل الله ، لأن الله غير مجرب بالشرور ، وهو لا يجرب أحدا '),
(17178, 'James', 59, 1, 14, ' ولكن كل واحد يجرب إذا انجذب وانخدع من شهوته '),
(17179, 'James', 59, 1, 15, ' ثم الشهوة إذا حبلت تلد خطية ، والخطية إذا كملت تنتج موتا '),
(17180, 'James', 59, 1, 16, ' لا تضلوا يا إخوتي الأحباء '),
(17181, 'James', 59, 1, 17, ' كل عطية صالحة وكل موهبة تامة هي من فوق ، نازلة من عند أبي الأنوار ، الذي ليس عنده تغيير ولا ظل دوران '),
(17182, 'James', 59, 1, 18, ' شاء فولدنا بكلمة الحق لكي نكون باكورة من خلائقه '),
(17183, 'James', 59, 1, 19, ' إذا يا إخوتي الأحباء ، ليكن كل إنسان مسرعا في الاستماع ، مبطئا في التكلم ، مبطئا في الغضب '),
(17184, 'James', 59, 1, 20, ' لأن غضب الإنسان لا يصنع بر الله '),
(17185, 'James', 59, 1, 21, ' لذلك اطرحوا كل نجاسة وكثرة شر ، فاقبلوا بوداعة الكلمة المغروسة القادرة أن تخلص نفوسكم '),
(17186, 'James', 59, 1, 22, ' ولكن كونوا عاملين بالكلمة ، لا سامعين فقط خادعين نفوسكم '),
(17187, 'James', 59, 1, 23, ' لأنه إن كان أحد سامعا للكلمة وليس عاملا ، فذاك يشبه رجلا ناظرا وجه خلقته في مرآة '),
(17188, 'James', 59, 1, 24, ' فإنه نظر ذاته ومضى ، وللوقت نسي ما هو '),
(17189, 'James', 59, 1, 25, ' ولكن من اطلع على الناموس الكامل - ناموس الحرية - وثبت ، وصار ليس سامعا ناسيا بل عاملا بالكلمة ، فهذا يكون مغبوطا في عمله '),
(17190, 'James', 59, 1, 26, ' إن كان أحد فيكم يظن أنه دين ، وهو ليس يلجم لسانه ، بل يخدع قلبه ، فديانة هذا باطلة '),
(17191, 'James', 59, 1, 27, ' الديانة الطاهرة النقية عند الله الآب هي هذه : افتقاد اليتامى والأرامل في ضيقتهم ، وحفظ الإنسان نفسه بلا دنس من العالم '),
(17192, 'James', 59, 2, 1, ' يا إخوتي ، لا يكن لكم إيمان ربنا يسوع المسيح ، رب المجد ، في المحاباة '),
(17193, 'James', 59, 2, 2, ' فإنه إن دخل إلى مجمعكم رجل بخواتم ذهب في لباس بهي ، ودخل أيضا فقير بلباس وسخ '),
(17194, 'James', 59, 2, 3, ' فنظرتم إلى اللابس اللباس البهي وقلتم له : اجلس أنت هنا حسنا . وقلتم للفقير : قف أنت هناك أو : اجلس هنا تحت موطئ قدمي '),
(17195, 'James', 59, 2, 4, ' فهل لا ترتابون في أنفسكم ، وتصيرون قضاة أفكار شريرة '),
(17196, 'James', 59, 2, 5, ' اسمعوا يا إخوتي الأحباء : أما اختار الله فقراء هذا العالم أغنياء في الإيمان ، وورثة الملكوت الذي وعد به الذين يحبونه '),
(17197, 'James', 59, 2, 6, ' وأما أنتم فأهنتم الفقير . أليس الأغنياء يتسلطون عليكم وهم يجرونكم إلى المحاكم '),
(17198, 'James', 59, 2, 7, ' أما هم يجدفون على الاسم الحسن الذي دعي به عليكم '),
(17199, 'James', 59, 2, 8, ' فإن كنتم تكملون الناموس الملوكي حسب الكتاب : تحب قريبك كنفسك . فحسنا تفعلون '),
(17200, 'James', 59, 2, 9, ' ولكن إن كنتم تحابون ، تفعلون خطية ، موبخين من الناموس كمتعدين '),
(17201, 'James', 59, 2, 10, ' لأن من حفظ كل الناموس ، وإنما عثر في واحدة ، فقد صار مجرما في الكل '),
(17202, 'James', 59, 2, 11, ' لأن الذي قال : لا تزن ، قال أيضا : لا تقتل . فإن لم تزن ولكن قتلت ، فقد صرت متعديا الناموس '),
(17203, 'James', 59, 2, 12, ' هكذا تكلموا وهكذا افعلوا كعتيدين أن تحاكموا بناموس الحرية '),
(17204, 'James', 59, 2, 13, ' لأن الحكم هو بلا رحمة لمن لم يعمل رحمة ، والرحمة تفتخر على الحكم '),
(17205, 'James', 59, 2, 14, ' ما المنفعة يا إخوتي إن قال أحد إن له إيمانا ولكن ليس له أعمال ، هل يقدر الإيمان أن يخلصه '),
(17206, 'James', 59, 2, 15, ' إن كان أخ وأخت عريانين ومعتازين للقوت اليومي '),
(17207, 'James', 59, 2, 16, ' فقال لهما أحدكم : امضيا بسلام ، استدفئا واشبعا ولكن لم تعطوهما حاجات الجسد ، فما المنفعة '),
(17208, 'James', 59, 2, 17, ' هكذا الإيمان أيضا ، إن لم يكن له أعمال ، ميت في ذاته '),
(17209, 'James', 59, 2, 18, ' لكن يقول قائل : أنت لك إيمان ، وأنا لي أعمال أرني إيمانك بدون أعمالك ، وأنا أريك بأعمالي إيماني '),
(17210, 'James', 59, 2, 19, ' أنت تؤمن أن الله واحد . حسنا تفعل . والشياطين يؤمنون ويقشعرون '),
(17211, 'James', 59, 2, 20, ' ولكن هل تريد أن تعلم أيها الإنسان الباطل أن الإيمان بدون أعمال ميت '),
(17212, 'James', 59, 2, 21, ' ألم يتبرر إبراهيم أبونا بالأعمال ، إذ قدم إسحاق ابنه على المذبح '),
(17213, 'James', 59, 2, 22, ' فترى أن الإيمان عمل مع أعماله ، وبالأعمال أكمل الإيمان '),
(17214, 'James', 59, 2, 23, ' وتم الكتاب القائل : فآمن إبراهيم بالله فحسب له برا ودعي خليل الله '),
(17215, 'James', 59, 2, 24, ' ترون إذا أنه بالأعمال يتبرر الإنسان ، لا بالإيمان وحده '),
(17216, 'James', 59, 2, 25, ' كذلك راحاب الزانية أيضا ، أما تبررت بالأعمال ، إذ قبلت الرسل وأخرجتهم في طريق آخر '),
(17217, 'James', 59, 2, 26, ' لأنه كما أن الجسد بدون روح ميت ، هكذا الإيمان أيضا بدون أعمال ميت '),
(17218, 'James', 59, 3, 1, ' لا تكونوا معلمين كثيرين يا إخوتي ، عالمين أننا نأخذ دينونة أعظم '),
(17219, 'James', 59, 3, 2, ' لأننا في أشياء كثيرة نعثر جميعنا . إن كان أحد لا يعثر في الكلام فذاك رجل كامل ، قادر أن يلجم كل الجسد أيضا '),
(17220, 'James', 59, 3, 3, ' هوذا الخيل ، نضع اللجم في أفواهها لكي تطاوعنا ، فندير جسمها كله '),
(17221, 'James', 59, 3, 4, ' هوذا السفن أيضا ، وهي عظيمة بهذا المقدار ، وتسوقها رياح عاصفة ، تديرها دفة صغيرة جدا إلى حيثما شاء قصد المدير '),
(17222, 'James', 59, 3, 5, ' هكذا اللسان أيضا ، هو عضو صغير ويفتخر متعظما . هوذا نار قليلة ، أي وقود تحرق '),
(17223, 'James', 59, 3, 6, ' فاللسان نار عالم الإثم . هكذا جعل في أعضائنا اللسان ، الذي يدنس الجسم كله ، ويضرم دائرة الكون ، ويضرم من جهنم '),
(17224, 'James', 59, 3, 7, ' لأن كل طبع للوحوش والطيور والزحافات والبحريات يذلل ، وقد تذلل للطبع البشري '),
(17225, 'James', 59, 3, 8, ' وأما اللسان ، فلا يستطيع أحد من الناس أن يذلله . هو شر لا يضبط ، مملو سما مميتا '),
(17226, 'James', 59, 3, 9, ' به نبارك الله الآب ، وبه نلعن الناس الذين قد تكونوا على شبه الله '),
(17227, 'James', 59, 3, 10, ' من الفم الواحد تخرج بركة ولعنة لا يصلح يا إخوتي أن تكون هذه الأمور هكذا '),
(17228, 'James', 59, 3, 11, ' ألعل ينبوعا ينبع من نفس عين واحدة العذب والمر '),
(17229, 'James', 59, 3, 12, ' هل تقدر يا إخوتي تينة أن تصنع زيتونا ، أو كرمة تينا ؟ ولا كذلك ينبوع يصنع ماء مالحا وعذبا '),
(17230, 'James', 59, 3, 13, ' من هو حكيم وعالم بينكم ، فلير أعماله بالتصرف الحسن في وداعة الحكمة '),
(17231, 'James', 59, 3, 14, ' ولكن إن كان لكم غيرة مرة وتحزب في قلوبكم ، فلا تفتخروا وتكذبوا على الحق '),
(17232, 'James', 59, 3, 15, ' ليست هذه الحكمة نازلة من فوق ، بل هي أرضية نفسانية شيطانية '),
(17233, 'James', 59, 3, 16, ' لأنه حيث الغيرة والتحزب ، هناك التشويش وكل أمر رديء '),
(17234, 'James', 59, 3, 17, ' وأما الحكمة التي من فوق فهي أولا طاهرة ، ثم مسالمة ، مترفقة ، مذعنة ، مملوة رحمة وأثمارا صالحة ، عديمة الريب والرياء '),
(17235, 'James', 59, 3, 18, ' وثمر البر يزرع في السلام من الذين يفعلون السلام '),
(17236, 'James', 59, 4, 1, ' من أين الحروب والخصومات بينكم ؟ أليست من هنا : من لذاتكم المحاربة في أعضائكم '),
(17237, 'James', 59, 4, 2, ' تشتهون ولستم تمتلكون . تقتلون وتحسدون ولستم تقدرون أن تنالوا . تخاصمون وتحاربون ولستم تمتلكون ، لأنكم لا تطلبون '),
(17238, 'James', 59, 4, 3, ' تطلبون ولستم تأخذون ، لأنكم تطلبون رديا لكي تنفقوا في لذاتكم '),
(17239, 'James', 59, 4, 4, ' أيها الزناة والزواني ، أما تعلمون أن محبة العالم عداوة لله ؟ فمن أراد أن يكون محبا للعالم ، فقد صار عدوا لله '),
(17240, 'James', 59, 4, 5, ' أم تظنون أن الكتاب يقول باطلا : الروح الذي حل فينا يشتاق إلى الحسد '),
(17241, 'James', 59, 4, 6, ' ولكنه يعطي نعمة أعظم . لذلك يقول : يقاوم الله المستكبرين ، وأما المتواضعون فيعطيهم نعمة '),
(17242, 'James', 59, 4, 7, ' فاخضعوا لله . قاوموا إبليس فيهرب منكم '),
(17243, 'James', 59, 4, 8, ' اقتربوا إلى الله فيقترب إليكم . نقوا أيديكم أيها الخطاة ، وطهروا قلوبكم يا ذوي الرأيين '),
(17244, 'James', 59, 4, 9, ' اكتئبوا ونوحوا وابكوا . ليتحول ضحككم إلى نوح ، وفرحكم إلى غم '),
(17245, 'James', 59, 4, 10, ' اتضعوا قدام الرب فيرفعكم '),
(17246, 'James', 59, 4, 11, ' لا يذم بعضكم بعضا أيها الإخوة . الذي يذم أخاه ويدين أخاه يذم الناموس ويدين الناموس . وإن كنت تدين الناموس ، فلست عاملا بالناموس ، بل ديانا له '),
(17247, 'James', 59, 4, 12, ' واحد هو واضع الناموس ، القادر أن يخلص ويهلك . فمن أنت يا من تدين غيرك '),
(17248, 'James', 59, 4, 13, ' هلم الآن أيها القائلون : نذهب اليوم أو غدا إلى هذه المدينة أو تلك ، وهناك نصرف سنة واحدة ونتجر ونربح '),
(17249, 'James', 59, 4, 14, ' أنتم الذين لا تعرفون أمر الغد لأنه ما هي حياتكم ؟ إنها بخار ، يظهر قليلا ثم يضمحل '),
(17250, 'James', 59, 4, 15, ' عوض أن تقولوا : إن شاء الرب وعشنا نفعل هذا أو ذاك '),
(17251, 'James', 59, 4, 16, ' وأما الآن فإنكم تفتخرون في تعظمكم . كل افتخار مثل هذا رديء '),
(17252, 'James', 59, 4, 17, ' فمن يعرف أن يعمل حسنا ولا يعمل ، فذلك خطية له '),
(17253, 'James', 59, 5, 1, ' هلم الآن أيها الأغنياء ، ابكوا مولولين على شقاوتكم القادمة '),
(17254, 'James', 59, 5, 2, ' غناكم قد تهرأ ، وثيابكم قد أكلها العث '),
(17255, 'James', 59, 5, 3, ' ذهبكم وفضتكم قد صدئا ، وصدأهما يكون شهادة عليكم ، ويأكل لحومكم كنار قد كنزتم في الأيام الأخيرة '),
(17256, 'James', 59, 5, 4, ' هوذا أجرة الفعلة الذين حصدوا حقولكم ، المبخوسة منكم تصرخ ، وصياح الحصادين قد دخل إلى أذني رب الجنود '),
(17257, 'James', 59, 5, 5, ' قد ترفهتم على الأرض ، وتنعمتم وربيتم قلوبكم ، كما في يوم الذبح '),
(17258, 'James', 59, 5, 6, ' حكمتم على البار . قتلتموه . لا يقاومكم '),
(17259, 'James', 59, 5, 7, ' فتأنوا أيها الإخوة إلى مجيء الرب . هوذا الفلاح ينتظر ثمر الأرض الثمين ، متأنيا عليه حتى ينال المطر المبكر والمتأخر '),
(17260, 'James', 59, 5, 8, ' فتأنوا أنتم وثبتوا قلوبكم ، لأن مجيء الرب قد اقترب '),
(17261, 'James', 59, 5, 9, ' لا يئن بعضكم على بعض أيها الإخوة لئلا تدانوا . هوذا الديان واقف قدام الباب '),
(17262, 'James', 59, 5, 10, ' خذوا يا إخوتي مثالا لاحتمال المشقات والأناة : الأنبياء الذين تكلموا باسم الرب '),
(17263, 'James', 59, 5, 11, ' ها نحن نطوب الصابرين . قد سمعتم بصبر أيوب ورأيتم عاقبة الرب . لأن الرب كثير الرحمة ورؤوف '),
(17264, 'James', 59, 5, 12, ' ولكن قبل كل شيء يا إخوتي ، لا تحلفوا ، لا بالسماء ، ولا بالأرض ، ولا بقسم آخر . بل لتكن نعمكم نعم ، ولاكم لا ، لئلا تقعوا تحت دينونة '),
(17265, 'James', 59, 5, 13, ' أعلى أحد بينكم مشقات ؟ فليصل . أمسرور أحد ؟ فليرتل '),
(17266, 'James', 59, 5, 14, ' أمريض أحد بينكم ؟ فليدع شيوخ الكنيسة فيصلوا عليه ويدهنوه بزيت باسم الرب '),
(17267, 'James', 59, 5, 15, ' وصلاة الإيمان تشفي المريض ، والرب يقيمه ، وإن كان قد فعل خطية تغفر له '),
(17268, 'James', 59, 5, 16, ' اعترفوا بعضكم لبعض بالزلات ، وصلوا بعضكم لأجل بعض ، لكي تشفوا . طلبة البار تقتدر كثيرا في فعلها '),
(17269, 'James', 59, 5, 17, ' كان إيليا إنسانا تحت الآلام مثلنا ، وصلى صلاة أن لا تمطر ، فلم تمطر على الأرض ثلاث سنين وستة أشهر '),
(17270, 'James', 59, 5, 18, ' ثم صلى أيضا ، فأعطت السماء مطرا ، وأخرجت الأرض ثمرها '),
(17271, 'James', 59, 5, 19, ' أيها الإخوة ، إن ضل أحد بينكم عن الحق فرده أحد '),
(17272, 'James', 59, 5, 20, ' فليعلم أن من رد خاطئا عن ضلال طريقه ، يخلص نفسا من الموت ، ويستر كثرة من الخطايا '),
(17273, 'Jeremiah', 24, 1, 1, ' كلام إرميا بن حلقيا من الكهنة الذين في عناثوث في أرض بنيامين '),
(17274, 'Jeremiah', 24, 1, 2, ' الذي كانت كلمة الرب إليه في أيام يوشيا بن آمون ملك يهوذا ، في السنة الثالثة عشرة من ملكه '),
(17275, 'Jeremiah', 24, 1, 3, ' وكانت في أيام يهوياقيم بن يوشيا ملك يهوذا ، إلى تمام السنة الحادية عشرة لصدقيا بن يوشيا ملك يهوذا ، إلى سبي أورشليم في الشهر الخامس '),
(17276, 'Jeremiah', 24, 1, 4, ' فكانت كلمة الرب إلي قائلا '),
(17277, 'Jeremiah', 24, 1, 5, ' قبلما صورتك في البطن عرفتك ، وقبلما خرجت من الرحم قدستك . جعلتك نبيا للشعوب '),
(17278, 'Jeremiah', 24, 1, 6, ' فقلت : آه ، يا سيد الرب ، إني لا أعرف أن أتكلم لأني ولد '),
(17279, 'Jeremiah', 24, 1, 7, ' فقال الرب لي : لا تقل إني ولد ، لأنك إلى كل من أرسلك إليه تذهب وتتكلم بكل ما آمرك به '),
(17280, 'Jeremiah', 24, 1, 8, ' لا تخف من وجوههم ، لأني أنا معك لأنقذك ، يقول الرب '),
(17281, 'Jeremiah', 24, 1, 9, ' ومد الرب يده ولمس فمي ، وقال الرب لي : ها قد جعلت كلامي في فمك '),
(17282, 'Jeremiah', 24, 1, 10, ' انظر قد وكلتك هذا اليوم على الشعوب وعلى الممالك ، لتقلع وتهدم وتهلك وتنقض وتبني وتغرس '),
(17283, 'Jeremiah', 24, 1, 11, ' ثم صارت كلمة الرب إلي قائلا : ماذا أنت راء يا إرميا ؟  . فقلت : أنا راء قضيب لوز '),
(17284, 'Jeremiah', 24, 1, 12, ' فقال الرب لي : أحسنت الرؤية ، لأني أنا ساهر على كلمتي لأجريها '),
(17285, 'Jeremiah', 24, 1, 13, ' ثم صارت كلمة الرب إلي ثانية قائلا : ماذا أنت راء ؟  . فقلت : إني راء قدرا منفوخة ، ووجهها من جهة الشمال '),
(17286, 'Jeremiah', 24, 1, 14, ' فقال الرب لي : من الشمال ينفتح الشر على كل سكان الأرض '),
(17287, 'Jeremiah', 24, 1, 15, ' لأني هأنذا داع كل عشائر ممالك الشمال ، يقول الرب ، فيأتون ويضعون كل واحد كرسيه في مدخل أبواب أورشليم ، وعلى كل أسوارها حواليها ، وعلى كل مدن يهوذا '),
(17288, 'Jeremiah', 24, 1, 16, ' وأقيم دعواي على كل شرهم ، لأنهم تركوني وبخروا لآلهة أخرى ، وسجدوا لأعمال أيديهم '),
(17289, 'Jeremiah', 24, 1, 17, ' أما أنت فنطق حقويك وقم وكلمهم بكل ما آمرك به . لا ترتع من وجوههم لئلا أريعك أمامهم '),
(17290, 'Jeremiah', 24, 1, 18, ' هأنذا قد جعلتك اليوم مدينة حصينة وعمود حديد وأسوار نحاس على كل الأرض ، لملوك يهوذا ولرؤسائها ولكهنتها ولشعب الأرض '),
(17291, 'Jeremiah', 24, 1, 19, ' فيحاربونك ولا يقدرون عليك ، لأني أنا معك ، يقول الرب ، لأنقذك '),
(17292, 'Jeremiah', 24, 2, 1, ' وصارت إلي كلمة الرب قائلا '),
(17293, 'Jeremiah', 24, 2, 2, ' اذهب وناد في أذني أورشليم قائلا : هكذا قال الرب : قد ذكرت لك غيرة صباك ، محبة خطبتك ، ذهابك ورائي في البرية في أرض غير مزروعة '),
(17294, 'Jeremiah', 24, 2, 3, ' إسرائيل قدس للرب ، أوائل غلته . كل آكليه يأثمون . شر يأتي عليهم ، يقول الرب '),
(17295, 'Jeremiah', 24, 2, 4, ' اسمعوا كلمة الرب يا بيت يعقوب ، وكل عشائر بيت إسرائيل '),
(17296, 'Jeremiah', 24, 2, 5, ' هكذا قال الرب : ماذا وجد في آباؤكم من جور حتى ابتعدوا عني وساروا وراء الباطل وصاروا باطلا '),
(17297, 'Jeremiah', 24, 2, 6, ' ولم يقولوا : أين هو الرب الذي أصعدنا من أرض مصر ، الذي سار بنا في البرية في أرض قفر وحفر ، في أرض يبوسة وظل الموت ، في أرض لم يعبرها رجل ولم يسكنها إنسان '),
(17298, 'Jeremiah', 24, 2, 7, ' وأتيت بكم إلى أرض بساتين لتأكلوا ثمرها وخيرها . فأتيتم ونجستم أرضي وجعلتم ميراثي رجسا '),
(17299, 'Jeremiah', 24, 2, 8, ' الكهنة لم يقولوا : أين هو الرب ؟ وأهل الشريعة لم يعرفوني ، والرعاة عصوا علي ، والأنبياء تنبأوا ببعل ، وذهبوا وراء ما لا ينفع '),
(17300, 'Jeremiah', 24, 2, 9, ' لذلك أخاصمكم بعد ، يقول الرب ، وبني بنيكم أخاصم '),
(17301, 'Jeremiah', 24, 2, 10, ' فاعبروا جزائر كتيم ، وانظروا ، وأرسلوا إلى قيدار ، وانتبهوا جدا ، وانظروا : هل صار مثل هذا '),
(17302, 'Jeremiah', 24, 2, 11, ' هل بدلت أمة آلهة ، وهي ليست آلهة ؟ أما شعبي فقد بدل مجده بما لا ينفع '),
(17303, 'Jeremiah', 24, 2, 12, ' ابهتي أيتها السماوات من هذا ، واقشعري وتحيري جدا ، يقول الرب '),
(17304, 'Jeremiah', 24, 2, 13, ' لأن شعبي عمل شرين : تركوني أنا ينبوع المياه الحية ، لينقروا لأنفسهم أبآرا ، أبآرا مشققة لا تضبط ماء '),
(17305, 'Jeremiah', 24, 2, 14, ' أعبد إسرائيل ، أو مولود البيت هو ؟ لماذا صار غنيمة '),
(17306, 'Jeremiah', 24, 2, 15, ' زمجرت عليه الأشبال . أطلقت صوتها وجعلت أرضه خربة . أحرقت مدنه فلا ساكن '),
(17307, 'Jeremiah', 24, 2, 16, ' وبنو نوف وتحفنيس قد شجوا هامتك '),
(17308, 'Jeremiah', 24, 2, 17, ' أما صنعت هذا بنفسك ، إذ تركت الرب إلهك حينما كان مسيرك في الطريق '),
(17309, 'Jeremiah', 24, 2, 18, ' والآن ما لك وطريق مصر لشرب مياه شيحور ؟ وما لك وطريق أشور لشرب مياه النهر '),
(17310, 'Jeremiah', 24, 2, 19, ' يوبخك شرك ، وعصيانك يؤدبك . فاعلمي وانظري أن تركك الرب إلهك شر ومر ، وأن خشيتي ليست فيك ، يقول السيد رب الجنود '),
(17311, 'Jeremiah', 24, 2, 20, ' لأنه منذ القديم كسرت نيرك وقطعت قيودك ، وقلت : لا أتعبد . لأنك على كل أكمة عالية وتحت كل شجرة خضراء أنت اضطجعت زانية '),
(17312, 'Jeremiah', 24, 2, 21, ' وأنا قد غرستك كرمة سورق ، زرع حق كلها . فكيف تحولت لي سروغ جفنة غريبة '),
(17313, 'Jeremiah', 24, 2, 22, ' فإنك وإن اغتسلت بنطرون ، وأكثرت لنفسك الأشنان ، فقد نقش إثمك أمامي ، يقول السيد الرب '),
(17314, 'Jeremiah', 24, 2, 23, ' كيف تقولين : لم أتنجس . وراء بعليم لم أذهب ؟ انظري طريقك في الوادي . اعرفي ما عملت ، يا ناقة خفيفة ضبعة في طرقها '),
(17315, 'Jeremiah', 24, 2, 24, ' يا أتان الفراء ، قد تعودت البرية في شهوة نفسها تستنشق الريح . عند ضبعها من يردها ؟ كل طالبيها لا يعيون . في شهرها يجدونها '),
(17316, 'Jeremiah', 24, 2, 25, ' احفظي رجلك من الحفاء وحلقك من الظمإ . فقلت : باطل لا لأني قد أحببت الغرباء ووراءهم أذهب '),
(17317, 'Jeremiah', 24, 2, 26, ' كخزي السارق إذا وجد هكذا خزي بيت إسرائيل ، هم وملوكهم ورؤساؤهم وكهنتهم وأنبياؤهم '),
(17318, 'Jeremiah', 24, 2, 27, ' قائلين للعود : أنت أبي ، وللحجر : أنت ولدتني . لأنهم حولوا نحوي القفا لا الوجه ، وفي وقت بليتهم يقولون : قم وخلصنا '),
(17319, 'Jeremiah', 24, 2, 28, ' فأين آلهتك التي صنعت لنفسك ؟ فليقوموا إن كانوا يخلصونك في وقت بليتك . لأنه على عدد مدنك صارت آلهتك يا يهوذا '),
(17320, 'Jeremiah', 24, 2, 29, ' لماذا تخاصمونني ؟ كلكم عصيتموني ، يقول الرب '),
(17321, 'Jeremiah', 24, 2, 30, ' لباطل ضربت بنيكم . لم يقبلوا تأديبا . أكل سيفكم أنبياءكم كأسد مهلك '),
(17322, 'Jeremiah', 24, 2, 31, ' أنتم أيها الجيل ، انظروا كلمة الرب . هل صرت برية لإسرائيل أو أرض ظلام دامس ؟ لماذا قال شعبي : قد شردنا ، لا نجيء إليك بعد '),
(17323, 'Jeremiah', 24, 2, 32, ' هل تنسى عذراء زينتها ، أو عروس مناطقها ؟ أما شعبي فقد نسيني أياما بلا عدد '),
(17324, 'Jeremiah', 24, 2, 33, ' لماذا تحسنين طريقك لتطلبي المحبة ؟ لذلك علمت الشريرات أيضا طرقك '),
(17325, 'Jeremiah', 24, 2, 34, ' أيضا في أذيالك وجد دم نفوس المساكين الأزكياء . لا بالنقب وجدته ، بل على كل هذه '),
(17326, 'Jeremiah', 24, 2, 35, ' وتقولين : لأني تبرأت ارتد غضبه عني حقا . هأنذا أحاكمك لأنك قلت : لم أخطئ '),
(17327, 'Jeremiah', 24, 2, 36, ' لماذا تركضين لتبدلي طريقك ؟ من مصر أيضا تخزين كما خزيت من أشور '),
(17328, 'Jeremiah', 24, 2, 37, ' من هنا أيضا تخرجين ويداك على رأسك ، لأن الرب قد رفض ثقاتك ، فلا تنجحين فيها ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(17329, 'Jeremiah', 24, 3, 1, ' قائلا : إذا طلق رجل امرأته فانطلقت من عنده وصارت لرجل آخر ، فهل يرجع إليها بعد ؟ ألا تتنجس تلك الأرض نجاسة ؟ أما أنت فقد زنيت بأصحاب كثيرين لكن ارجعي إلي ، يقول الرب '),
(17330, 'Jeremiah', 24, 3, 2, ' ارفعي عينيك إلى الهضاب وانظري ، أين لم تضاجعي ؟ في الطرقات جلست لهم كأعرابي في البرية ، ونجست الأرض بزناك وبشرك '),
(17331, 'Jeremiah', 24, 3, 3, ' فامتنع الغيث ولم يكن مطر متأخر . وجبهة امرأة زانية كانت لك . أبيت أن تخجلي '),
(17332, 'Jeremiah', 24, 3, 4, ' ألست من الآن تدعينني : يا أبي ، أليف صباي أنت '),
(17333, 'Jeremiah', 24, 3, 5, ' هل يحقد إلى الدهر ، أو يحفظ غضبه إلى الأبد ؟ ها قد تكلمت وعملت شرورا ، واستطعت '),
(17334, 'Jeremiah', 24, 3, 6, ' وقال الرب لي في أيام يوشيا الملك : هل رأيت ما فعلت العاصية إسرائيل ؟ انطلقت إلى كل جبل عال ، وإلى كل شجرة خضراء وزنت هناك '),
(17335, 'Jeremiah', 24, 3, 7, ' فقلت بعدما فعلت كل هذه : ارجعي إلي . فلم ترجع . فرأت أختها الخائنة يهوذا '),
(17336, 'Jeremiah', 24, 3, 8, ' فرأيت أنه لأجل كل الأسباب إذ زنت العاصية إسرائيل فطلقتها وأعطيتها كتاب طلاقها ، لم تخف الخائنة يهوذا أختها ، بل مضت وزنت هي أيضا '),
(17337, 'Jeremiah', 24, 3, 9, ' وكان من هوان زناها أنها نجست الأرض وزنت مع الحجر ومع الشجر '),
(17338, 'Jeremiah', 24, 3, 10, ' وفي كل هذا أيضا لم ترجع إلي أختها الخائنة يهوذا بكل قلبها ، بل بالكذب ، يقول الرب '),
(17339, 'Jeremiah', 24, 3, 11, ' فقال الرب لي : قد بررت نفسها العاصية إسرائيل أكثر من الخائنة يهوذا '),
(17340, 'Jeremiah', 24, 3, 12, ' اذهب وناد بهذه الكلمات نحو الشمال ، وقل : ارجعي أيتها العاصية إسرائيل ، يقول الرب . لا أوقع غضبي بكم لأني رؤوف ، يقول الرب . لا أحقد إلى الأبد '),
(17341, 'Jeremiah', 24, 3, 13, ' اعرفي فقط إثمك أنك إلى الرب إلهك أذنبت ، وفرقت طرقك للغرباء تحت كل شجرة خضراء ، ولصوتي لم تسمعوا ، يقول الرب '),
(17342, 'Jeremiah', 24, 3, 14, ' ارجعوا أيها البنون العصاة ، يقول الرب ، لأني سدت عليكم فآخذكم واحدا من المدينة ، واثنين من العشيرة ، وآتي بكم إلى صهيون '),
(17343, 'Jeremiah', 24, 3, 15, ' وأعطيكم رعاة حسب قلبي ، فيرعونكم بالمعرفة والفهم '),
(17344, 'Jeremiah', 24, 3, 16, ' ويكون إذ تكثرون وتثمرون في الأرض في تلك الأيام ، يقول الرب ، أنهم لا يقولون بعد : تابوت عهد الرب ، ولا يخطر على بال ، ولا يذكرونه ولا يتعهدونه ولا يصنع بعد '),
(17345, 'Jeremiah', 24, 3, 17, ' في ذلك الزمان يسمون أورشليم كرسي الرب ، ويجتمع إليها كل الأمم ، إلى اسم الرب ، إلى أورشليم ، ولا يذهبون بعد وراء عناد قلبهم الشرير '),
(17346, 'Jeremiah', 24, 3, 18, ' في تلك الأيام يذهب بيت يهوذا مع بيت إسرائيل ، ويأتيان معا من أرض الشمال إلى الأرض التي ملكت آباءكم إياها '),
(17347, 'Jeremiah', 24, 3, 19, ' وأنا قلت : كيف أضعك بين البنين ، وأعطيك أرضا شهية ، ميراث مجد أمجاد الأمم ؟ وقلت : تدعينني يا أبي ، ومن ورائي لا ترجعين '),
(17348, 'Jeremiah', 24, 3, 20, ' حقا إنه كما تخون المرأة قرينها ، هكذا خنتموني يا بيت إسرائيل ، يقول الرب '),
(17349, 'Jeremiah', 24, 3, 21, ' سمع صوت على الهضاب ، بكاء تضرعات بني إسرائيل . لأنهم عوجوا طريقهم . نسوا الرب إلههم '),
(17350, 'Jeremiah', 24, 3, 22, ' ارجعوا أيها البنون العصاة فأشفي عصيانكم . ها قد أتينا إليك ، لأنك أنت الرب إلهنا '),
(17351, 'Jeremiah', 24, 3, 23, ' حقا باطلة هي الآكام ثروة الجبال . حقا بالرب إلهنا خلاص إسرائيل '),
(17352, 'Jeremiah', 24, 3, 24, ' وقد أكل الخزي تعب آبائنا منذ صبانا ، غنمهم وبقرهم بنيهم وبناتهم '),
(17353, 'Jeremiah', 24, 3, 25, ' نضطجع في خزينا ويغطينا خجلنا ، لأننا إلى الرب إلهنا أخطأنا ، نحن وآباؤنا منذ صبانا إلى هذا اليوم ، ولم نسمع لصوت الرب إلهنا '),
(17354, 'Jeremiah', 24, 4, 1, ' إن رجعت يا إسرائيل ، يقول الرب ، إن رجعت إلي وإن نزعت مكرهاتك من أمامي ، فلا تتيه '),
(17355, 'Jeremiah', 24, 4, 2, ' وإن حلفت : حي هو الرب ، بالحق والعدل والبر ، فتتبرك الشعوب به ، وبه يفتخرون '),
(17356, 'Jeremiah', 24, 4, 3, ' لأنه هكذا قال الرب لرجال يهوذا ولأورشليم : احرثوا لأنفسكم حرثا ولا تزرعوا في الأشواك '),
(17357, 'Jeremiah', 24, 4, 4, ' اختتنوا للرب وانزعوا غرل قلوبكم يا رجال يهوذا وسكان أورشليم ، لئلا يخرج كنار غيظي ، فيحرق وليس من يطفئ ، بسبب شر أعمالكم '),
(17358, 'Jeremiah', 24, 4, 5, ' أخبروا في يهوذا ، وسمعوا في أورشليم ، وقولوا : اضربوا بالبوق في الأرض . نادوا بصوت عال وقولوا : اجتمعوا ، فلندخل المدن الحصينة '),
(17359, 'Jeremiah', 24, 4, 6, ' ارفعوا الراية نحو صهيون . احتموا . لا تقفوا . لأني آتي بشر من الشمال ، وكسر عظيم '),
(17360, 'Jeremiah', 24, 4, 7, ' قد صعد الأسد من غابته ، وزحف مهلك الأمم . خرج من مكانه ليجعل أرضك خرابا . تخرب مدنك فلا ساكن '),
(17361, 'Jeremiah', 24, 4, 8, ' من أجل ذلك تنطقوا بمسوح . الطموا وولولوا لأنه لم يرتد حمو غضب الرب عنا '),
(17362, 'Jeremiah', 24, 4, 9, ' ويكون في ذلك اليوم ، يقول الرب ، أن قلب الملك يعدم ، وقلوب الرؤساء . وتتحير الكهنة وتتعجب الأنبياء '),
(17363, 'Jeremiah', 24, 4, 10, ' فقلت : آه ، يا سيد الرب ، حقا إنك خداعا خادعت هذا الشعب وأورشليم ، قائلا : يكون لكم سلام وقد بلغ السيف النفس '),
(17364, 'Jeremiah', 24, 4, 11, ' في ذلك الزمان يقال لهذا الشعب ولأورشليم : ريح لافحة من الهضاب في البرية نحو بنت شعبي ، لا للتذرية ولا للتنقية '),
(17365, 'Jeremiah', 24, 4, 12, ' ريح أشد تأتي لي من هذه . الآن أنا أيضا أحاكمهم '),
(17366, 'Jeremiah', 24, 4, 13, ' هوذا كسحاب يصعد ، وكزوبعة مركباته . أسرع من النسور خيله . ويل لنا لأننا قد أخربنا '),
(17367, 'Jeremiah', 24, 4, 14, ' اغسلي من الشر قلبك يا أورشليم لكي تخلصي . إلى متى تبيت في وسطك أفكارك الباطلة '),
(17368, 'Jeremiah', 24, 4, 15, ' لأن صوتا يخبر من دان ، ويسمع ببلية من جبل أفرايم '),
(17369, 'Jeremiah', 24, 4, 16, ' اذكروا للأمم . انظروا . أسمعوا على أورشليم . المحاصرون آتون من أرض بعيدة ، فيطلقون على مدن يهوذا صوتهم '),
(17370, 'Jeremiah', 24, 4, 17, ' كحارسي حقل صاروا عليها حواليها ، لأنها تمردت علي ، يقول الرب '),
(17371, 'Jeremiah', 24, 4, 18, ' طريقك وأعمالك صنعت هذه لك . هذا شرك . فإنه مر ، فإنه قد بلغ قلبك '),
(17372, 'Jeremiah', 24, 4, 19, ' أحشائي ، أحشائي توجعني جدران قلبي . يئن في قلبي . لا أستطيع السكوت . لأنك سمعت يا نفسي صوت البوق وهتاف الحرب '),
(17373, 'Jeremiah', 24, 4, 20, ' بكسر على كسر نودي ، لأنه قد خربت كل الأرض . بغتة خربت خيامي ، وشققي في لحظة '),
(17374, 'Jeremiah', 24, 4, 21, ' حتى متى أرى الراية وأسمع صوت البوق '),
(17375, 'Jeremiah', 24, 4, 22, ' لأن شعبي أحمق . إياي لم يعرفوا . هم بنون جاهلون وهم غير فاهمين . هم حكماء في عمل الشر ، ولعمل الصالح ما يفهمون '),
(17376, 'Jeremiah', 24, 4, 23, ' نظرت إلى الأرض وإذا هي خربة وخالية ، وإلى السماوات فلا نور لها '),
(17377, 'Jeremiah', 24, 4, 24, ' نظرت إلى الجبال وإذا هي ترتجف ، وكل الآكام تقلقلت '),
(17378, 'Jeremiah', 24, 4, 25, ' نظرت وإذا لا إنسان ، وكل طيور السماء هربت '),
(17379, 'Jeremiah', 24, 4, 26, ' نظرت وإذا البستان برية ، وكل مدنها نقضت من وجه الرب ، من وجه حمو غضبه '),
(17380, 'Jeremiah', 24, 4, 27, ' لأنه هكذا قال الرب : خرابا تكون كل الأرض ، ولكنني لا أفنيها '),
(17381, 'Jeremiah', 24, 4, 28, ' من أجل ذلك تنوح الأرض وتظلم السماوات من فوق ، من أجل أني قد تكلمت . قصدت ولا أندم ولا أرجع عنه '),
(17382, 'Jeremiah', 24, 4, 29, ' من صوت الفارس ورامي القوس كل المدينة هاربة . دخلوا الغابات وصعدوا على الصخور . كل المدن متروكة ، ولا إنسان ساكن فيها '),
(17383, 'Jeremiah', 24, 4, 30, ' وأنت أيتها الخربة ، ماذا تعملين ؟ إذا لبست قرمزا ، إذا تزينت بزينة من ذهب ، إذا كحلت بالأثمد عينيك ، فباطلا تحسنين ذاتك ، فقد رذلك العاشقون . يطلبون نفسك '),
(17384, 'Jeremiah', 24, 4, 31, ' لأني سمعت صوتا كماخضة ، ضيقا مثل ضيق بكرية . صوت ابنة صهيون تزفر . تبسط يديها قائلة : ويل لي ، لأن نفسي قد أغمي عليها بسبب القاتلين '),
(17385, 'Jeremiah', 24, 5, 1, ' طوفوا في شوارع أورشليم وانظروا ، واعرفوا وفتشوا في ساحاتها ، هل تجدون إنسانا أو يوجد عامل بالعدل طالب الحق ، فأصفح عنها '),
(17386, 'Jeremiah', 24, 5, 2, ' وإن قالوا : حي هو الرب . فإنهم يحلفون بالكذب '),
(17387, 'Jeremiah', 24, 5, 3, ' يارب ، أليست عيناك على الحق ؟ ضربتهم فلم يتوجعوا . أفنيتهم وأبوا قبول التأديب . صلبوا وجوههم أكثر من الصخر . أبوا الرجوع '),
(17388, 'Jeremiah', 24, 5, 4, ' أما أنا فقلت : إنما هم مساكين . قد جهلوا لأنهم لم يعرفوا طريق الرب ، قضاء إلههم '),
(17389, 'Jeremiah', 24, 5, 5, ' أنطلق إلى العظماء وأكلمهم لأنهم عرفوا طريق الرب ، قضاء إلههم . أما هم فقد كسروا النير جميعا وقطعوا الربط '),
(17390, 'Jeremiah', 24, 5, 6, ' من أجل ذلك يضربهم الأسد من الوعر . ذئب المساء يهلكهم . يكمن النمر حول مدنهم . كل من خرج منها يفترس لأن ذنوبهم كثرت . تعاظمت معاصيهم '),
(17391, 'Jeremiah', 24, 5, 7, ' كيف أصفح لك عن هذه ؟ بنوك تركوني وحلفوا بما ليست آلهة . ولما أشبعتهم زنوا ، وفي بيت زانية تزاحموا '),
(17392, 'Jeremiah', 24, 5, 8, ' صاروا حصنا معلوفة سائبة . صهلوا كل واحد على امرأة صاحبه '),
(17393, 'Jeremiah', 24, 5, 9, ' أما أعاقب على هذا ، يقول الرب ؟ أو ما تنتقم نفسي من أمة كهذه '),
(17394, 'Jeremiah', 24, 5, 10, ' اصعدوا على أسوارها واخربوا ولكن لا تفنوها . انزعوا أفنانها لأنها ليست للرب '),
(17395, 'Jeremiah', 24, 5, 11, ' لأنه خيانة خانني بيت إسرائيل وبيت يهوذا ، يقول الرب '),
(17396, 'Jeremiah', 24, 5, 12, ' جحدوا الرب وقالوا : ليس هو ، ولا يأتي علينا شر ، ولا نرى سيفا ولا جوعا '),
(17397, 'Jeremiah', 24, 5, 13, ' والأنبياء يصيرون ريحا ، والكلمة ليست فيهم . هكذا يصنع بهم '),
(17398, 'Jeremiah', 24, 5, 14, ' لذلك هكذا قال الرب إله الجنود : من أجل أنكم تتكلمون بهذه الكلمة ، هأنذا جاعل كلامي في فمك نارا ، وهذا الشعب حطبا ، فتأكلهم '),
(17399, 'Jeremiah', 24, 5, 15, ' هأنذا أجلب عليكم أمة من بعد يا بيت إسرائيل ، يقول الرب . أمة قوية . أمة منذ القديم . أمة لا تعرف لسانها ولا تفهم ما تتكلم به '),
(17400, 'Jeremiah', 24, 5, 16, ' جعبتهم كقبر مفتوح . كلهم جبابرة '),
(17401, 'Jeremiah', 24, 5, 17, ' فيأكلون حصادك وخبزك الذي يأكله بنوك وبناتك . يأكلون غنمك وبقرك . يأكلون جفنتك وتينك . يهلكون بالسيف مدنك الحصينة التي أنت متكل عليها '),
(17402, 'Jeremiah', 24, 5, 18, ' وأيضا في تلك الأيام ، يقول الرب ، لا أفنيكم '),
(17403, 'Jeremiah', 24, 5, 19, ' ويكون حين تقولون : لماذا صنع الرب إلهنا بنا كل هذه ؟ تقول لهم : كما أنكم تركتموني وعبدتم آلهة غريبة في أرضكم ، هكذا تعبدون الغرباء في أرض ليست لكم '),
(17404, 'Jeremiah', 24, 5, 20, ' أخبروا بهذا في بيت يعقوب وأسمعوا به في يهوذا قائلين '),
(17405, 'Jeremiah', 24, 5, 21, ' اسمع هذا أيها الشعب الجاهل والعديم الفهم ، الذين لهم أعين ولا يبصرون . لهم آذان ولا يسمعون '),
(17406, 'Jeremiah', 24, 5, 22, ' أإياي لا تخشون ، يقول الرب ؟ أولا ترتعدون من وجهي ؟ أنا الذي وضعت الرمل تخوما للبحر فريضة أبدية لا يتعداها ، فتتلاطم ولا تستطيع ، وتعج أمواجه ولا تتجاوزها '),
(17407, 'Jeremiah', 24, 5, 23, ' وصار لهذا الشعب قلب عاص ومتمرد . عصوا ومضوا '),
(17408, 'Jeremiah', 24, 5, 24, ' ولم يقولوا بقلوبهم : لنخف الرب إلهنا الذي يعطي المطر المبكر والمتأخر في وقته . يحفظ لنا أسابيع الحصاد المفروضة '),
(17409, 'Jeremiah', 24, 5, 25, ' آثامكم عكست هذه ، وخطاياكم منعت الخير عنكم '),
(17410, 'Jeremiah', 24, 5, 26, ' لأنه وجد في شعبي أشرار يرصدون كمنحن من القانصين ، ينصبون أشراكا يمسكون الناس '),
(17411, 'Jeremiah', 24, 5, 27, ' مثل قفص ملآن طيورا هكذا بيوتهم ملآنة مكرا . من أجل ذلك عظموا واستغنوا '),
(17412, 'Jeremiah', 24, 5, 28, ' سمنوا . لمعوا . أيضا تجاوزوا في أمور الشر . لم يقضوا في الدعوى ، دعوى اليتيم . وقد نجحوا . وبحق المساكين لم يقضوا '),
(17413, 'Jeremiah', 24, 5, 29, ' أفلأجل هذه لا أعاقب ، يقول الرب ؟ أولا تنتقم نفسي من أمة كهذه '),
(17414, 'Jeremiah', 24, 5, 30, ' صار في الأرض دهش وقشعريرة '),
(17415, 'Jeremiah', 24, 5, 31, ' الأنبياء يتنبأون بالكذب ، والكهنة تحكم على أيديهم ، وشعبي هكذا أحب . وماذا تعملون في آخرتها '),
(17416, 'Jeremiah', 24, 6, 1, ' اهربوا يا بني بنيامين من وسط أورشليم ، واضربوا بالبوق في تقوع ، وعلى بيت هكاريم ارفعوا علم نار ، لأن الشر أشرف من الشمال وكسر عظيم '),
(17417, 'Jeremiah', 24, 6, 2, ' الجميلة اللطيفة ابنة صهيون أهلكها '),
(17418, 'Jeremiah', 24, 6, 3, ' إليها تأتي الرعاة وقطعانهم . ينصبون عندها خياما حواليها . يرعون كل واحد في مكانه '),
(17419, 'Jeremiah', 24, 6, 4, ' قدسوا عليها حربا . قوموا فنصعد في الظهيرة . ويل لنا لأن النهار مال ، لأن ظلال المساء امتدت '),
(17420, 'Jeremiah', 24, 6, 5, ' قوموا فنصعد في الليل ونهدم قصورها '),
(17421, 'Jeremiah', 24, 6, 6, ' لأنه هكذا قال رب الجنود : اقطعوا أشجارا . أقيموا حول أورشليم مترسة . هي المدينة المعاقبة . كلها ظلم في وسطها '),
(17422, 'Jeremiah', 24, 6, 7, ' كما تنبع العين مياهها ، هكذا تنبع هي شرها . ظلم وخطف يسمع فيها . أمامي دائما مرض وضرب '),
(17423, 'Jeremiah', 24, 6, 8, ' تأدبي يا أورشليم لئلا تجفوك نفسي . لئلا أجعلك خرابا ، أرضا غير مسكونة '),
(17424, 'Jeremiah', 24, 6, 9, ' هكذا قال رب الجنود : تعليلا يعللون ، كجفنة ، بقية إسرائيل . رد يدك كقاطف إلى السلال '),
(17425, 'Jeremiah', 24, 6, 10, ' من أكلمهم وأنذرهم فيسمعوا ؟ ها إن أذنهم غلفاء فلا يقدرون أن يصغوا . ها إن كلمة الرب صارت لهم عارا . لا يسرون بها '),
(17426, 'Jeremiah', 24, 6, 11, ' فامتلأت من غيظ الرب . مللت الطاقة . أسكبه على الأطفال في الخارج وعلى مجلس الشبان معا ، لأن الرجل والمرأة يؤخذان كلاهما ، والشيخ مع الممتلئ أياما '),
(17427, 'Jeremiah', 24, 6, 12, ' وتتحول بيوتهم إلى آخرين ، الحقول والنساء معا ، لأني أمد يدي على سكان الأرض ، يقول الرب '),
(17428, 'Jeremiah', 24, 6, 13, ' لأنهم من صغيرهم إلى كبيرهم ، كل واحد مولع بالربح . ومن النبي إلى الكاهن ، كل واحد يعمل بالكذب '),
(17429, 'Jeremiah', 24, 6, 14, ' ويشفون كسر بنت شعبي على عثم قائلين : سلام ، سلام . ولا سلام '),
(17430, 'Jeremiah', 24, 6, 15, ' هل خزوا لأنهم عملوا رجسا ؟ بل لم يخزوا خزيا ولم يعرفوا الخجل . لذلك يسقطون بين الساقطين . في وقت معاقبتهم يعثرون ، قال الرب '),
(17431, 'Jeremiah', 24, 6, 16, ' هكذا قال الرب : قفوا على الطرق وانظروا ، واسألوا عن السبل القديمة : أين هو الطريق الصالح ؟ وسيروا فيه ، فتجدوا راحة لنفوسكم . ولكنهم قالوا : لا نسير فيه '),
(17432, 'Jeremiah', 24, 6, 17, ' وأقمت عليكم رقباء قائلين : اصغوا لصوت البوق . فقالوا : لا نصغى '),
(17433, 'Jeremiah', 24, 6, 18, ' لذلك اسمعوا يا أيها الشعوب ، واعرفي أيتها الجماعة ما هو بينهم '),
(17434, 'Jeremiah', 24, 6, 19, ' اسمعي أيتها الأرض : هأنذا جالب شرا على هذا الشعب ثمر أفكارهم ، لأنهم لم يصغوا لكلامي ، وشريعتي رفضوها '),
(17435, 'Jeremiah', 24, 6, 20, ' لماذا يأتي لي اللبان من شبا ، وقصب الذريرة من أرض بعيدة ؟ محرقاتكم غير مقبولة ، وذبائحكم لا تلذ لي '),
(17436, 'Jeremiah', 24, 6, 21, ' لذلك هكذا قال الرب : هأنذا جاعل لهذا الشعب معثرات فيعثر بها الآباء والأبناء معا . الجار وصاحبه يبيدان '),
(17437, 'Jeremiah', 24, 6, 22, ' هكذا قال الرب : هوذا شعب قادم من أرض الشمال ، وأمة عظيمة تقوم من أقاصي الأرض '),
(17438, 'Jeremiah', 24, 6, 23, ' تمسك القوس والرمح . هي قاسية لا ترحم . صوتها كالبحر يعج ، وعلى خيل تركب ، مصطفة كإنسان لمحاربتك يا ابنة صهيون '),
(17439, 'Jeremiah', 24, 6, 24, ' سمعنا خبرها . ارتخت أيدينا . أمسكنا ضيق ووجع كالماخض '),
(17440, 'Jeremiah', 24, 6, 25, ' لا تخرجوا إلى الحقل وفي الطريق لا تمشوا ، لأن سيف العدو خوف من كل جهة '),
(17441, 'Jeremiah', 24, 6, 26, ' يا ابنة شعبي ، تنطقي بمسح وتمرغي في الرماد . نوح وحيد اصنعي لنفسك مناحة مرة ، لأن المخرب يأتي علينا بغتة '),
(17442, 'Jeremiah', 24, 6, 27, ' قد جعلتك برجا في شعبي ، حصنا ، لتعرف وتمتحن طريقهم '),
(17443, 'Jeremiah', 24, 6, 28, ' كلهم عصاة متمردون ساعون في الوشاية . هم نحاس وحديد . كلهم مفسدون '),
(17444, 'Jeremiah', 24, 6, 29, ' احترق المنفاخ من النار . فني الرصاص . باطلا صاغ الصائغ ، والأشرار لا يفرزون '),
(17445, 'Jeremiah', 24, 6, 30, ' فضة مرفوضة يدعون . لأن الرب قد رفضهم '),
(17446, 'Jeremiah', 24, 7, 1, ' الكلمة التي صارت إلى إرميا من قبل الرب قائلا '),
(17447, 'Jeremiah', 24, 7, 2, ' قف في باب بيت الرب وناد هناك بهذه الكلمة وقل : اسمعوا كلمة الرب يا جميع يهوذا الداخلين في هذه الأبواب لتسجدوا للرب '),
(17448, 'Jeremiah', 24, 7, 3, ' هكذا قال رب الجنود إله إسرائيل : أصلحوا طرقكم وأعمالكم فأسكنكم في هذا الموضع '),
(17449, 'Jeremiah', 24, 7, 4, ' لا تتكلوا على كلام الكذب قائلين : هيكل الرب ، هيكل الرب ، هيكل الرب هو '),
(17450, 'Jeremiah', 24, 7, 5, ' لأنكم إن أصلحتم إصلاحا طرقكم وأعمالكم ، إن أجريتم عدلا بين الإنسان وصاحبه '),
(17451, 'Jeremiah', 24, 7, 6, ' إن لم تظلموا الغريب واليتيم والأرملة ، ولم تسفكوا دما زكيا في هذا الموضع ، ولم تسيروا وراء آلهة أخرى لأذائكم '),
(17452, 'Jeremiah', 24, 7, 7, ' فإني أسكنكم في هذا الموضع ، في الأرض التي أعطيت لآبائكم من الأزل وإلى الأبد '),
(17453, 'Jeremiah', 24, 7, 8, ' ها إنكم متكلون على كلام الكذب الذي لا ينفع '),
(17454, 'Jeremiah', 24, 7, 9, ' أتسرقون وتقتلون وتزنون وتحلفون كذبا وتبخرون للبعل ، وتسيرون وراء آلهة أخرى لم تعرفوها '),
(17455, 'Jeremiah', 24, 7, 10, ' ثم تأتون وتقفون أمامي في هذا البيت الذي دعي باسمي عليه وتقولون : قد أنقذنا . حتى تعملوا كل هذه الرجاسات '),
(17456, 'Jeremiah', 24, 7, 11, ' هل صار هذا البيت الذي دعي باسمي عليه مغارة لصوص في أعينكم ؟ هأنذا أيضا قد رأيت ، يقول الرب '),
(17457, 'Jeremiah', 24, 7, 12, ' لكن اذهبوا إلى موضعي الذي في شيلوه الذي أسكنت فيه اسمي أولا ، وانظروا ما صنعت به من أجل شر شعبي إسرائيل '),
(17458, 'Jeremiah', 24, 7, 13, ' والآن من أجل عملكم هذه الأعمال ، يقول الرب ، وقد كلمتكم مبكرا ومكلما فلم تسمعوا ، ودعوتكم فلم تجيبوا '),
(17459, 'Jeremiah', 24, 7, 14, ' أصنع بالبيت الذي دعي باسمي عليه الذي أنتم متكلون عليه ، وبالموضع الذي أعطيتكم وآباءكم إياه ، كما صنعت بشيلوه '),
(17460, 'Jeremiah', 24, 7, 15, ' وأطرحكم من أمامي كما طرحت كل إخوتكم ، كل نسل أفرايم '),
(17461, 'Jeremiah', 24, 7, 16, ' وأنت فلا تصل لأجل هذا الشعب ولا ترفع لأجلهم دعاء ولا صلاة ، ولا تلح علي لأني لا أسمعك '),
(17462, 'Jeremiah', 24, 7, 17, ' أما ترى ماذا يعملون في مدن يهوذا وفي شوارع أورشليم '),
(17463, 'Jeremiah', 24, 7, 18, ' الأبناء يلتقطون حطبا ، والآباء يوقدون النار ، والنساء يعجن العجين ، ليصنعن كعكا لملكة السماوات ، ولسكب سكائب لآلهة أخرى لكي يغيظوني '),
(17464, 'Jeremiah', 24, 7, 19, ' أفإياي يغيظون ، يقول الرب ؟ أليس أنفسهم لأجل خزي وجوههم '),
(17465, 'Jeremiah', 24, 7, 20, ' لذلك هكذا قال السيد الرب : ها غضبي وغيظي ينسكبان على هذا الموضع ، على الناس وعلى البهائم وعلى شجر الحقل وعلى ثمر الأرض ، فيتقدان ولا ينطفئان '),
(17466, 'Jeremiah', 24, 7, 21, ' هكذا قال رب الجنود إله إسرائيل : ضموا محرقاتكم إلى ذبائحكم وكلوا لحما '),
(17467, 'Jeremiah', 24, 7, 22, ' لأني لم أكلم آباءكم ولا أوصيتهم يوم أخرجتهم من أرض مصر من جهة محرقة وذبيحة '),
(17468, 'Jeremiah', 24, 7, 23, ' بل إنما أوصيتهم بهذا الأمر قائلا : اسمعوا صوتي فأكون لكم إلها ، وأنتم تكونون لي شعبا ، وسيروا في كل الطريق الذي أوصيكم به ليحسن إليكم '),
(17469, 'Jeremiah', 24, 7, 24, ' فلم يسمعوا ولم يميلوا أذنهم ، بل ساروا في مشورات وعناد قلبهم الشرير ، وأعطوا القفا لا الوجه '),
(17470, 'Jeremiah', 24, 7, 25, ' فمن اليوم الذي خرج فيه آباؤكم من أرض مصر إلى هذا اليوم ، أرسلت إليكم كل عبيدي الأنبياء ، مبكرا كل يوم ومرسلا '),
(17471, 'Jeremiah', 24, 7, 26, ' فلم يسمعوا لي ولم يميلوا أذنهم ، بل صلبوا رقابهم . أساءوا أكثر من آبائهم '),
(17472, 'Jeremiah', 24, 7, 27, ' فتكلمهم بكل هذه الكلمات ولا يسمعون لك ، وتدعوهم ولا يجيبونك '),
(17473, 'Jeremiah', 24, 7, 28, ' فتقول لهم : هذه هي الأمة التي لم تسمع لصوت الرب إلهها ولم تقبل تأديبا . باد الحق وقطع عن أفواههم '),
(17474, 'Jeremiah', 24, 7, 29, ' جزي شعرك واطرحيه ، وارفعي على الهضاب مرثاة ، لأن الرب قد رفض ورذل جيل رجزه '),
(17475, 'Jeremiah', 24, 7, 30, ' لأن بني يهوذا قد عملوا الشر في عيني ، يقول الرب . وضعوا مكرهاتهم في البيت الذي دعي باسمي لينجسوه '),
(17476, 'Jeremiah', 24, 7, 31, ' وبنوا مرتفعات توفة التي في وادي ابن هنوم ليحرقوا بنيهم وبناتهم بالنار ، الذي لم آمر به ولا صعد على قلبي '),
(17477, 'Jeremiah', 24, 7, 32, ' لذلك ها هي أيام تأتي ، يقول الرب ، ولا يسمى بعد توفة ولا وادي ابن هنوم ، بل وادي القتل . ويدفنون في توفة حتى لا يكون موضع '),
(17478, 'Jeremiah', 24, 7, 33, ' وتصير جثث هذا الشعب أكلا لطيور السماء ولوحوش الأرض ، ولا مزعج '),
(17479, 'Jeremiah', 24, 7, 34, ' وأبطل من مدن يهوذا ومن شوارع أورشليم صوت الطرب وصوت الفرح ، صوت العريس وصوت العروس ، لأن الأرض تصير خرابا '),
(17480, 'Jeremiah', 24, 8, 1, ' في ذلك الزمان ، يقول الرب ، يخرجون عظام ملوك يهوذا وعظام رؤسائه وعظام الكهنة وعظام الأنبياء وعظام سكان أورشليم من قبورهم '),
(17481, 'Jeremiah', 24, 8, 2, ' ويبسطونها للشمس وللقمر ولكل جنود السماوات التي أحبوها والتي عبدوها والتي ساروا وراءها والتي استشاروها والتي سجدوا لها . لا تجمع ولا تدفن ، بل تكون دمنة على وجه الأرض '),
(17482, 'Jeremiah', 24, 8, 3, ' ويختار الموت على الحياة عند كل البقية الباقية من هذه العشيرة الشريرة الباقية في كل الأماكن التي طردتهم إليها ، يقول رب الجنود '),
(17483, 'Jeremiah', 24, 8, 4, ' وتقول لهم : هكذا قال الرب : هل يسقطون ولا يقومون ، أو يرتد أحد ولا يرجع '),
(17484, 'Jeremiah', 24, 8, 5, ' فلماذا ارتد هذا الشعب في أورشليم ارتدادا دائما ؟ تمسكوا بالمكر . أبوا أن يرجعوا '),
(17485, 'Jeremiah', 24, 8, 6, ' صغيت وسمعت . بغير المستقيم يتكلمون . ليس أحد يتوب عن شره قائلا : ماذا عملت ؟ كل واحد رجع إلى مسراه كفرس ثائر في الحرب '),
(17486, 'Jeremiah', 24, 8, 7, ' بل اللقلق في السماوات يعرف ميعاده ، واليمامة والسنونة المزقزقة حفظتا وقت مجيئهما . أما شعبي فلم يعرف قضاء الرب '),
(17487, 'Jeremiah', 24, 8, 8, ' كيف تقولون : نحن حكماء وشريعة الرب معنا ؟ حقا إنه إلى الكذب حولها قلم الكتبة الكاذب '),
(17488, 'Jeremiah', 24, 8, 9, ' خزي الحكماء . ارتاعوا وأخذوا . ها قد رفضوا كلمة الرب ، فأية حكمة لهم '),
(17489, 'Jeremiah', 24, 8, 10, ' لذلك أعطي نساءهم لآخرين ، وحقولهم لمالكين ، لأنهم من الصغير إلى الكبير ، كل واحد مولع بالربح . من النبي إلى الكاهن ، كل واحد يعمل بالكذب '),
(17490, 'Jeremiah', 24, 8, 11, ' ويشفون كسر بنت شعبي على عثم ، قائلين : سلام ، سلام . ولا سلام '),
(17491, 'Jeremiah', 24, 8, 12, ' هل خزوا لأنهم عملوا رجسا ؟ بل لم يخزوا خزيا ، ولم يعرفوا الخجل لذلك يسقطون بين الساقطين . في وقت معاقبتهم يعثرون ، قال الرب '),
(17492, 'Jeremiah', 24, 8, 13, ' نزعا أنزعهم ، يقول الرب . لا عنب في الجفنة ، ولا تين في التينة ، والورق ذبل ، وأعطيهم ما يزول عنهم '),
(17493, 'Jeremiah', 24, 8, 14, ' لماذا نحن جلوس ؟ اجتمعوا فلندخل إلى المدن الحصينة ونصمت هناك . لأن الرب إلهنا قد أصمتنا وأسقانا ماء العلقم ، لأننا قد أخطأنا إلى الرب '),
(17494, 'Jeremiah', 24, 8, 15, ' انتظرنا السلام ولم يكن خير ، وزمان الشفاء وإذا رعب '),
(17495, 'Jeremiah', 24, 8, 16, ' من دان سمعت حمحمة خيله . عند صوت صهيل جياده ارتجفت كل الأرض . فأتوا وأكلوا الأرض وملأها ، المدينة والساكنين فيها '),
(17496, 'Jeremiah', 24, 8, 17, ' لأني هأنذا مرسل عليكم حيات ، أفاعي لا ترقى ، فتلدغكم ، يقول الرب '),
(17497, 'Jeremiah', 24, 8, 18, ' من مفرج عني الحزن ؟ قلبي في سقيم '),
(17498, 'Jeremiah', 24, 8, 19, ' هوذا صوت استغاثة بنت شعبي من أرض بعيدة : ألعل الرب ليس في صهيون ، أو ملكها ليس فيها ؟  . لماذا أغاظوني بمنحوتاتهم ، بأباطيل غريبة '),
(17499, 'Jeremiah', 24, 8, 20, ' مضى الحصاد ، انتهى الصيف ، ونحن لم نخلص '),
(17500, 'Jeremiah', 24, 8, 21, ' من أجل سحق بنت شعبي انسحقت . حزنت . أخذتني دهشة '),
(17501, 'Jeremiah', 24, 8, 22, ' أليس بلسان في جلعاد ، أم ليس هناك طبيب ؟ فلماذا لم تعصب بنت شعبي '),
(17502, 'Jeremiah', 24, 9, 1, ' يا ليت رأسي ماء ، وعيني ينبوع دموع ، فأبكي نهارا وليلا قتلى بنت شعبي '),
(17503, 'Jeremiah', 24, 9, 2, ' يا ليت لي في البرية مبيت مسافرين ، فأترك شعبي وأنطلق من عندهم ، لأنهم جميعا زناة ، جماعة خائنين '),
(17504, 'Jeremiah', 24, 9, 3, ' يمدون ألسنتهم كقسيهم للكذب . لا للحق قووا في الأرض . لأنهم خرجوا من شر إلى شر ، وإياي لم يعرفوا ، يقول الرب '),
(17505, 'Jeremiah', 24, 9, 4, ' احترزوا كل واحد من صاحبه ، وعلى كل أخ لا تتكلوا ، لأن كل أخ يعقب عقبا ، وكل صاحب يسعى في الوشاية '),
(17506, 'Jeremiah', 24, 9, 5, ' ويختل الإنسان صاحبه ولا يتكلمون بالحق . علموا ألسنتهم التكلم بالكذب ، وتعبوا في الافتراء '),
(17507, 'Jeremiah', 24, 9, 6, ' مسكنك في وسط المكر . بالمكر أبوا أن يعرفوني ، يقول الرب '),
(17508, 'Jeremiah', 24, 9, 7, ' لذلك هكذا قال رب الجنود : هأنذا أنقيهم وأمتحنهم . لأني ماذا أعمل من أجل بنت شعبي '),
(17509, 'Jeremiah', 24, 9, 8, ' لسانهم سهم قتال يتكلم بالغش . بفمه يكلم صاحبه بسلام ، وفي قلبه يضع له كمينا '),
(17510, 'Jeremiah', 24, 9, 9, ' أفما أعاقبهم على هذه ، يقول الرب ؟ أم لا تنتقم نفسي من أمة كهذه '),
(17511, 'Jeremiah', 24, 9, 10, ' على الجبال أرفع بكاء ومرثاة ، وعلى مراعي البرية ندبا ، لأنها احترقت ، فلا إنسان عابر ولا يسمع صوت الماشية . من طير السماوات إلى البهائم هربت مضت '),
(17512, 'Jeremiah', 24, 9, 11, ' وأجعل أورشليم رجما ومأوى بنات آوى ، ومدن يهوذا أجعلها خرابا بلا ساكن '),
(17513, 'Jeremiah', 24, 9, 12, ' من هو الإنسان الحكيم الذي يفهم هذه ، والذي كلمه فم الرب ، فيخبر بها ؟ لماذا بادت الأرض واحترقت كبرية بلا عابر '),
(17514, 'Jeremiah', 24, 9, 13, ' فقال الرب : على تركهم شريعتي التي جعلتها أمامهم ، ولم يسمعوا لصوتي ولم يسلكوا بها '),
(17515, 'Jeremiah', 24, 9, 14, ' بل سلكوا وراء عناد قلوبهم ووراء البعليم التي علمهم إياها آباؤهم '),
(17516, 'Jeremiah', 24, 9, 15, ' لذلك هكذا قال رب الجنود إله إسرائيل : هأنذا أطعم هذا الشعب أفسنتينا وأسقيهم ماء العلقم '),
(17517, 'Jeremiah', 24, 9, 16, ' وأبددهم في أمم لم يعرفوها هم ولا آباؤهم ، وأطلق وراءهم السيف حتى أفنيهم '),
(17518, 'Jeremiah', 24, 9, 17, ' هكذا قال رب الجنود : تأملوا وادعوا النادبات فيأتين ، وأرسلوا إلى الحكيمات فيقبلن '),
(17519, 'Jeremiah', 24, 9, 18, ' ويسرعن ويرفعن علينا مرثاة ، فتذرف أعيننا دموعا وتفيض أجفاننا ماء '),
(17520, 'Jeremiah', 24, 9, 19, ' لأن صوت رثاية سمع من صهيون : كيف أهلكنا ؟ خزينا جدا لأننا تركنا الأرض ، لأنهم هدموا مساكننا '),
(17521, 'Jeremiah', 24, 9, 20, ' بل اسمعن أيتها النساء كلمة الرب ، ولتقبل آذانكن كلمة فمه ، وعلمن بناتكن الرثاية ، والمرأة صاحبتها الندب '),
(17522, 'Jeremiah', 24, 9, 21, ' لأن الموت طلع إلى كوانا ، دخل قصورنا ليقطع الأطفال من خارج ، والشبان من الساحات '),
(17523, 'Jeremiah', 24, 9, 22, ' تكلم : هكذا يقول الرب : وتسقط جثة الإنسان كدمنة على وجه الحقل ، وكقبضة وراء الحاصد وليس من يجمع '),
(17524, 'Jeremiah', 24, 9, 23, ' هكذا قال الرب : لا يفتخرن الحكيم بحكمته ، ولا يفتخر الجبار بجبروته ، ولا يفتخر الغني بغناه '),
(17525, 'Jeremiah', 24, 9, 24, ' بل بهذا ليفتخرن المفتخر : بأنه يفهم ويعرفني أني أنا الرب الصانع رحمة وقضاء وعدلا في الأرض ، لأني بهذه أسر ، يقول الرب '),
(17526, 'Jeremiah', 24, 9, 25, ' ها أيام تأتي ، يقول الرب ، وأعاقب كل مختون وأغلف '),
(17527, 'Jeremiah', 24, 9, 26, ' مصر ويهوذا وأدوم وبني عمون وموآب ، وكل مقصوصي الشعر مستديرا الساكنين في البرية ، لأن كل الأمم غلف ، وكل بيت إسرائيل غلف القلوب '),
(17528, 'Jeremiah', 24, 10, 1, ' اسمعوا الكلمة التي تكلم بها الرب عليكم يا بيت إسرائيل '),
(17529, 'Jeremiah', 24, 10, 2, ' هكذا قال الرب : لا تتعلموا طريق الأمم ، ومن آيات السماوات لا ترتعبوا ، لأن الأمم ترتعب منها '),
(17530, 'Jeremiah', 24, 10, 3, ' لأن فرائض الأمم باطلة . لأنها شجرة يقطعونها من الوعر . صنعة يدي نجار بالقدوم '),
(17531, 'Jeremiah', 24, 10, 4, ' بالفضة والذهب يزينونها ، وبالمسامير والمطارق يشددونها فلا تتحرك '),
(17532, 'Jeremiah', 24, 10, 5, ' هي كاللعين في مقثأة فلا تتكلم تحمل حملا لأنها لا تمشي لا تخافوها لأنها لا تضر ، ولا فيها أن تصنع خيرا '),
(17533, 'Jeremiah', 24, 10, 6, ' لا مثل لك يارب عظيم أنت ، وعظيم اسمك في الجبروت '),
(17534, 'Jeremiah', 24, 10, 7, ' من لا يخافك يا ملك الشعوب ؟ لأنه بك يليق . لأنه في جميع حكماء الشعوب وفي كل ممالكهم ليس مثلك '),
(17535, 'Jeremiah', 24, 10, 8, ' بلدوا وحمقوا معا . أدب أباطيل هو الخشب '),
(17536, 'Jeremiah', 24, 10, 9, ' فضة مطرقة تجلب من ترشيش ، وذهب من أوفاز ، صنعة صانع ويدي صائغ . أسمانجوني وأرجوان لباسها . كلها صنعة حكماء '),
(17537, 'Jeremiah', 24, 10, 10, ' أما الرب الإله فحق . هو إله حي وملك أبدي . من سخطه ترتعد الأرض ، ولا تطيق الأمم غضبه '),
(17538, 'Jeremiah', 24, 10, 11, ' هكذا تقولون لهم : الآلهة التي لم تصنع السماوات والأرض تبيد من الأرض ومن تحت هذه السماوات '),
(17539, 'Jeremiah', 24, 10, 12, ' صانع الأرض بقوته ، مؤسس المسكونة بحكمته ، وبفهمه بسط السماوات '),
(17540, 'Jeremiah', 24, 10, 13, ' إذا أعطى قولا تكون كثرة مياه في السماوات ، ويصعد السحاب من أقاصي الأرض . صنع بروقا للمطر ، وأخرج الريح من خزائنه '),
(17541, 'Jeremiah', 24, 10, 14, ' بلد كل إنسان من معرفته . خزي كل صائغ من التمثال ، لأن مسبوكه كذب ولا روح فيه '),
(17542, 'Jeremiah', 24, 10, 15, ' هي باطلة صنعة الأضاليل . في وقت عقابها تبيد '),
(17543, 'Jeremiah', 24, 10, 16, ' ليس كهذه نصيب يعقوب ، لأنه مصور الجميع ، وإسرائيل قضيب ميراثه . رب الجنود اسمه '),
(17544, 'Jeremiah', 24, 10, 17, ' اجمعي من الأرض حزمك أيتها الساكنة في الحصار '),
(17545, 'Jeremiah', 24, 10, 18, ' لأنه هكذا قال الرب : هأنذا رام من مقلاع سكان الأرض هذه المرة ، وأضيق عليهم لكي يشعروا '),
(17546, 'Jeremiah', 24, 10, 19, ' ويل لي من أجل سحقي ضربتي عديمة الشفاء فقلت : إنما هذه مصيبة فأحتملها '),
(17547, 'Jeremiah', 24, 10, 20, ' خيمتي خربت ، وكل أطنابي قطعت . بني خرجوا عني وليسوا . ليس من يبسط بعد خيمتي ويقيم شققي '),
(17548, 'Jeremiah', 24, 10, 21, ' لأن الرعاة بلدوا والرب لم يطلبوا . من أجل ذلك لم ينجحوا ، وكل رعيتهم تبددت '),
(17549, 'Jeremiah', 24, 10, 22, ' هوذا صوت خبر جاء ، واضطراب عظيم من أرض الشمال لجعل مدن يهوذا خرابا ، مأوى بنات آوى '),
(17550, 'Jeremiah', 24, 10, 23, ' عرفت يارب أنه ليس للإنسان طريقه . ليس لإنسان يمشي أن يهدي خطواته '),
(17551, 'Jeremiah', 24, 10, 24, ' أدبني يارب ولكن بالحق ، لا بغضبك لئلا تفنيني '),
(17552, 'Jeremiah', 24, 10, 25, ' اسكب غضبك على الأمم التي لم تعرفك ، وعلى العشائر التي لم تدع باسمك . لأنهم أكلوا يعقوب . أكلوه وأفنوه وأخربوا مسكنه '),
(17553, 'Jeremiah', 24, 11, 1, ' الكلام الذي صار إلى إرميا من قبل الرب قائلا '),
(17554, 'Jeremiah', 24, 11, 2, ' اسمعوا كلام هذا العهد ، وكلموا رجال يهوذا وسكان أورشليم '),
(17555, 'Jeremiah', 24, 11, 3, ' فتقول لهم : هكذا قال الرب إله إسرائيل : ملعون الإنسان الذي لا يسمع كلام هذا العهد '),
(17556, 'Jeremiah', 24, 11, 4, ' الذي أمرت به آباءكم يوم أخرجتهم من أرض مصر ، من كور الحديد قائلا : اسمعوا صوتي واعملوا به حسب كل ما آمركم به ، فتكونوا لي شعبا ، وأنا أكون لكم إلها '),
(17557, 'Jeremiah', 24, 11, 5, ' لأقيم الحلف الذي حلفت لآبائكم أن أعطيهم أرضا تفيض لبنا وعسلا كهذا اليوم . فأجبت وقلت : آمين يارب '),
(17558, 'Jeremiah', 24, 11, 6, ' فقال الرب لي : ناد بكل هذا الكلام في مدن يهوذا ، وفي شوارع أورشليم قائلا : اسمعوا كلام هذا العهد واعملوا به '),
(17559, 'Jeremiah', 24, 11, 7, ' لأني أشهدت على آبائكم إشهادا يوم أصعدتهم من أرض مصر إلى هذا اليوم ، مبكرا ومشهدا قائلا : اسمعوا صوتي '),
(17560, 'Jeremiah', 24, 11, 8, ' فلم يسمعوا ولم يميلوا أذنهم ، بل سلكوا كل واحد في عناد قلبه الشرير . فجلبت عليهم كل كلام هذا العهد الذي أمرتهم أن يصنعوه ولم يصنعوه '),
(17561, 'Jeremiah', 24, 11, 9, ' وقال الرب لي : توجد فتنة بين رجال يهوذا وسكان أورشليم '),
(17562, 'Jeremiah', 24, 11, 10, ' قد رجعوا إلى آثام آبائهم الأولين الذين أبوا أن يسمعوا كلامي ، وقد ذهبوا وراء آلهة أخرى ليعبدوها . قد نقض بيت إسرائيل وبيت يهوذا عهدي الذي قطعته مع آبائهم '),
(17563, 'Jeremiah', 24, 11, 11, ' لذلك هكذا قال الرب : هأنذا جالب عليهم شرا لا يستطيعون أن يخرجوا منه ، ويصرخون إلي فلا أسمع لهم '),
(17564, 'Jeremiah', 24, 11, 12, ' فينطلق مدن يهوذا وسكان أورشليم ويصرخون إلى الآلهة التي يبخرون لها ، فلن تخلصهم في وقت بليتهم '),
(17565, 'Jeremiah', 24, 11, 13, ' لأنه بعدد مدنك صارت آلهتك يا يهوذا ، وبعدد شوارع أورشليم وضعتم مذابح للخزي ، مذابح للتبخير للبعل '),
(17566, 'Jeremiah', 24, 11, 14, ' وأنت فلا تصل لأجل هذا الشعب ، ولا ترفع لأجلهم دعاء ولا صلاة ، لأني لا أسمع في وقت صراخهم إلي من قبل بليتهم '),
(17567, 'Jeremiah', 24, 11, 15, ' ما لحبيبتي في بيتي ؟ قد عملت فظائع كثيرة ، واللحم المقدس قد عبر عنك . إذا صنعت الشر حينئذ تبتهجين '),
(17568, 'Jeremiah', 24, 11, 16, ' زيتونة خضراء ذات ثمر جميل الصورة دعا الرب اسمك . بصوت ضجة عظيمة أوقد نارا عليها فانكسرت أغصانها '),
(17569, 'Jeremiah', 24, 11, 17, ' ورب الجنود غارسك قد تكلم عليك شرا ، من أجل شر بيت إسرائيل وبيت يهوذا الذي صنعوه ضد أنفسهم ليغيظوني بتبخيرهم للبعل '),
(17570, 'Jeremiah', 24, 11, 18, ' والرب عرفني فعرفت . حينئذ أريتني أفعالهم '),
(17571, 'Jeremiah', 24, 11, 19, ' وأنا كخروف داجن يساق إلى الذبح ، ولم أعلم أنهم فكروا علي أفكارا ، قائلين : لنهلك الشجرة بثمرها ، ونقطعه من أرض الأحياء ، فلا يذكر بعد اسمه '),
(17572, 'Jeremiah', 24, 11, 20, ' فيارب الجنود ، القاضي العدل ، فاحص الكلى والقلب ، دعني أرى انتقامك منهم لأني لك كشفت دعواي '),
(17573, 'Jeremiah', 24, 11, 21, ' لذلك هكذا قال الرب عن أهل عناثوث الذين يطلبون نفسك قائلين : لا تتنبأ باسم الرب فلا تموت بيدنا '),
(17574, 'Jeremiah', 24, 11, 22, ' لذلك هكذا قال رب الجنود : هأنذا أعاقبهم . يموت الشبان بالسيف ، ويموت بنوهم وبناتهم بالجوع '),
(17575, 'Jeremiah', 24, 11, 23, ' ولا تكون لهم بقية ، لأني أجلب شرا على أهل عناثوث سنة عقابهم '),
(17576, 'Jeremiah', 24, 12, 1, ' أبر أنت يارب من أن أخاصمك . لكن أكلمك من جهة أحكامك : لماذا تنجح طريق الأشرار ؟ اطمأن كل الغادرين غدرا '),
(17577, 'Jeremiah', 24, 12, 2, ' غرستهم فأصلوا . نموا وأثمروا ثمرا . أنت قريب في فمهم وبعيد من كلاهم '),
(17578, 'Jeremiah', 24, 12, 3, ' وأنت يارب عرفتني . رأيتني واختبرت قلبي من جهتك . افرزهم كغنم للذبح ، وخصصهم ليوم القتل '),
(17579, 'Jeremiah', 24, 12, 4, ' حتى متى تنوح الأرض وييبس عشب كل الحقل ؟ من شر الساكنين فيها فنيت البهائم والطيور ، لأنهم قالوا : لا يرى آخرتنا '),
(17580, 'Jeremiah', 24, 12, 5, ' إن جريت مع المشاة فأتعبوك ، فكيف تباري الخيل ؟ وإن كنت منبطحا في أرض السلام ، فكيف تعمل في كبرياء الأردن '),
(17581, 'Jeremiah', 24, 12, 6, ' لأن إخوتك أنفسهم وبيت أبيك قد غادروك هم أيضا . هم أيضا نادوا وراءك بصوت عال . لا تأتمنهم إذا كلموك بالخير '),
(17582, 'Jeremiah', 24, 12, 7, ' قد تركت بيتي . رفضت ميراثي . دفعت حبيبة نفسي ليد أعدائها '),
(17583, 'Jeremiah', 24, 12, 8, ' صار لي ميراثي كأسد في الوعر . نطق علي بصوته . من أجل ذلك أبغضته '),
(17584, 'Jeremiah', 24, 12, 9, ' جارحة ضبع ميراثي لي . الجوارح حواليه عليه . هلم اجمعوا كل حيوان الحقل . ايتوا بها للأكل '),
(17585, 'Jeremiah', 24, 12, 10, ' رعاة كثيرون أفسدوا كرمي ، داسوا نصيبي . جعلوا نصيبي المشتهى برية خربة '),
(17586, 'Jeremiah', 24, 12, 11, ' جعلوه خرابا ينوح علي وهو خرب . خربت كل الأرض ، لأنه لا أحد يضع في قلبه '),
(17587, 'Jeremiah', 24, 12, 12, ' على جميع الروابي في البرية أتى الناهبون ، لأن سيفا للرب يأكل من أقصى الأرض إلى أقصى الأرض . ليس سلام لأحد من البشر '),
(17588, 'Jeremiah', 24, 12, 13, ' زرعوا حنطة وحصدوا شوكا . أعيوا ولم ينتفعوا ، بل خزوا من غلاتكم ، من حمو غضب الرب '),
(17589, 'Jeremiah', 24, 12, 14, ' هكذا قال الرب على جميع جيراني الأشرار الذين يلمسون الميراث الذي أورثته لشعبي إسرائيل : هأنذا أقتلعهم عن أرضهم وأقتلع بيت يهوذا من وسطهم '),
(17590, 'Jeremiah', 24, 12, 15, ' ويكون بعد اقتلاعي إياهم ، أني أرجع فأرحمهم ، وأردهم كل واحد إلى ميراثه ، وكل واحد إلى أرضه '),
(17591, 'Jeremiah', 24, 12, 16, ' ويكون إذا تعلموا علما طرق شعبي أن يحلفوا باسمي : حي هو الرب ، كما علموا شعبي أن يحلفوا ببعل ، أنهم يبنون في وسط شعبي '),
(17592, 'Jeremiah', 24, 12, 17, ' وإن لم يسمعوا ، فإني أقتلع تلك الأمة اقتلاعا وأبيدها ، يقول الرب '),
(17593, 'Jeremiah', 24, 13, 1, ' هكذا قال الرب لي : اذهب واشتر لنفسك منطقة من كتان وضعها على حقويك ولا تدخلها في الماء '),
(17594, 'Jeremiah', 24, 13, 2, ' فاشتريت المنطقة كقول الرب ووضعتها على حقوي '),
(17595, 'Jeremiah', 24, 13, 3, ' فصار كلام الرب إلي ثانية قائلا '),
(17596, 'Jeremiah', 24, 13, 4, ' خذ المنطقة التي اشتريتها التي هي على حقويك ، وقم انطلق إلى الفرات ، واطمرها هناك في شق صخر '),
(17597, 'Jeremiah', 24, 13, 5, ' فانطلقت وطمرتها عند الفرات كما أمرني الرب '),
(17598, 'Jeremiah', 24, 13, 6, ' وكان بعد أيام كثيرة أن الرب قال لي : قم انطلق إلى الفرات وخذ من هناك المنطقة التي أمرتك أن تطمرها هناك '),
(17599, 'Jeremiah', 24, 13, 7, ' فانطلقت إلى الفرات ، وحفرت وأخذت المنطقة من الموضع الذي طمرتها فيه . وإذا بالمنطقة قد فسدت . لا تصلح لشيء '),
(17600, 'Jeremiah', 24, 13, 8, ' فصار كلام الرب إلي قائلا '),
(17601, 'Jeremiah', 24, 13, 9, ' هكذا قال الرب : هكذا أفسد كبرياء يهوذا ، وكبرياء أورشليم العظيمة '),
(17602, 'Jeremiah', 24, 13, 10, ' هذا الشعب الشرير الذي يأبى أن يسمع كلامي ، الذي يسلك في عناد قلبه ويسير وراء آلهة أخرى ليعبدها ويسجد لها ، يصير كهذه المنطقة التي لا تصلح لشيء '),
(17603, 'Jeremiah', 24, 13, 11, ' لأنه كما تلتصق المنطقة بحقوي الإنسان ، هكذا ألصقت بنفسي كل بيت إسرائيل وكل بيت يهوذا ، يقول الرب ، ليكونوا لي شعبا واسما وفخرا ومجدا ، ولكنهم لم يسمعوا '),
(17604, 'Jeremiah', 24, 13, 12, ' فتقول لهم هذه الكلمة : هكذا قال الرب إله إسرائيل : كل زق يمتلئ خمرا . فيقولون لك : أما نعرف معرفة أن كل زق يمتلئ خمرا '),
(17605, 'Jeremiah', 24, 13, 13, ' فتقول لهم : هكذا قال الرب : هأنذا أملأ كل سكان هذه الأرض والملوك الجالسين لداود على كرسيه ، والكهنة والأنبياء وكل سكان أورشليم سكرا '),
(17606, 'Jeremiah', 24, 13, 14, ' وأحطمهم الواحد على أخيه ، الآباء والأبناء معا ، يقول الرب . لا أشفق ولا أترأف ولا أرحم من إهلاكهم '),
(17607, 'Jeremiah', 24, 13, 15, ' اسمعوا واصغوا . لا تتعظموا لأن الرب تكلم '),
(17608, 'Jeremiah', 24, 13, 16, ' أعطوا الرب إلهكم مجدا قبل أن يجعل ظلاما ، وقبلما تعثر أرجلكم على جبال العتمة ، فتنتظرون نورا فيجعله ظل موت ، ويجعله ظلاما دامسا '),
(17609, 'Jeremiah', 24, 13, 17, ' وإن لم تسمعوا ذلك ، فإن نفسي تبكي في أماكن مستترة من أجل الكبرياء ، وتبكي عيني بكاء وتذرف الدموع ، لأنه قد سبي قطيع الرب '),
(17610, 'Jeremiah', 24, 13, 18, ' قل للملك وللملكة : اتضعا واجلسا ، لأنه قد هبط عن رأسيكما تاج مجدكما '),
(17611, 'Jeremiah', 24, 13, 19, ' أغلقت مدن الجنوب وليس من يفتح . سبيت يهوذا كلها . سبيت بالتمام '),
(17612, 'Jeremiah', 24, 13, 20, ' ارفعوا أعينكم وانظروا المقبلين من الشمال . أين القطيع الذي أعطي لك ، غنم مجدك '),
(17613, 'Jeremiah', 24, 13, 21, ' ماذا تقولين حين يعاقبك ، وقد علمتهم على نفسك قوادا للرياسة ؟ أما تأخذك الأوجاع كامرأة ماخض '),
(17614, 'Jeremiah', 24, 13, 22, ' وإن قلت في قلبك : لماذا أصابتني هذه ؟  . لأجل عظمة إثمك هتك ذيلاك وانكشف عنفا عقباك '),
(17615, 'Jeremiah', 24, 13, 23, ' هل يغير الكوشي جلده أو النمر رقطه ؟ فأنتم أيضا تقدرون أن تصنعوا خيرا أيها المتعلمون الشر '),
(17616, 'Jeremiah', 24, 13, 24, ' فأبددهم كقش يعبر مع ريح البرية '),
(17617, 'Jeremiah', 24, 13, 25, ' هذه قرعتك ، النصيب المكيل لك من عندي ، يقول الرب ، لأنك نسيتني واتكلت على الكذب '),
(17618, 'Jeremiah', 24, 13, 26, ' فأنا أيضا أرفع ذيليك على وجهك فيرى خزيك '),
(17619, 'Jeremiah', 24, 13, 27, ' فسقك وصهيلك ورذالة زناك على الآكام في الحقل . قد رأيت مكرهاتك . ويل لك يا أورشليم لا تطهرين . حتى متى بعد '),
(17620, 'Jeremiah', 24, 14, 1, ' كلمة الرب التي صارت إلى إرميا من جهة القحط '),
(17621, 'Jeremiah', 24, 14, 2, ' ناحت يهوذا وأبوابها ذبلت . حزنت إلى الأرض وصعد عويل أورشليم '),
(17622, 'Jeremiah', 24, 14, 3, ' وأشرافهم أرسلوا أصاغرهم للماء . أتوا إلى الأجباب فلم يجدوا ماء . رجعوا بآنيتهم فارغة . خزوا وخجلوا وغطوا رؤوسهم '),
(17623, 'Jeremiah', 24, 14, 4, ' من أجل أن الأرض قد تشققت ، لأنه لم يكن مطر على الأرض خزي الفلاحون . غطوا رؤوسهم '),
(17624, 'Jeremiah', 24, 14, 5, ' حتى أن الإيلة أيضا في الحقل ولدت وتركت ، لأنه لم يكن كلأ '),
(17625, 'Jeremiah', 24, 14, 6, ' الفراء وقفت على الهضاب تستنشق الريح مثل بنات آوى . كلت عيونها لأنه ليس عشب '),
(17626, 'Jeremiah', 24, 14, 7, ' وإن تكن آثامنا تشهد علينا يارب ، فاعمل لأجل اسمك . لأن معاصينا كثرت . إليك أخطأنا '),
(17627, 'Jeremiah', 24, 14, 8, ' يا رجاء إسرائيل ، مخلصه في زمان الضيق ، لماذا تكون كغريب في الأرض ، وكمسافر يميل ليبيت '),
(17628, 'Jeremiah', 24, 14, 9, ' لماذا تكون كإنسان قد تحير ، كجبار لا يستطيع أن يخلص ؟ وأنت في وسطنا يارب ، وقد دعينا باسمك . لا تتركنا '),
(17629, 'Jeremiah', 24, 14, 10, ' هكذا قال الرب لهذا الشعب : هكذا أحبوا أن يجولوا . لم يمنعوا أرجلهم ، فالرب لم يقبلهم . الآن يذكر إثمهم ويعاقب خطاياهم '),
(17630, 'Jeremiah', 24, 14, 11, ' وقال الرب لي : لا تصل لأجل هذا الشعب للخير '),
(17631, 'Jeremiah', 24, 14, 12, ' حين يصومون لا أسمع صراخهم ، وحين يصعدون محرقة وتقدمة لا أقبلهم ، بل بالسيف والجوع والوبإ أنا أفنيهم '),
(17632, 'Jeremiah', 24, 14, 13, ' فقلت : آه ، أيها السيد الرب هوذا الأنبياء يقولون لهم لا ترون سيفا ، ولا يكون لكم جوع بل سلاما ثابتا أعطيكم في هذا الموضع '),
(17633, 'Jeremiah', 24, 14, 14, ' فقال الرب لي : بالكذب يتنبأ الأنبياء باسمي . لم أرسلهم ، ولا أمرتهم ، ولا كلمتهم . برؤيا كاذبة وعرافة وباطل ومكر قلوبهم هم يتنبأون لكم '),
(17634, 'Jeremiah', 24, 14, 15, ' لذلك هكذا قال الرب عن الأنبياء الذين يتنبأون باسمي وأنا لم أرسلهم ، وهم يقولون : لا يكون سيف ولا جوع في هذه الأرض : بالسيف والجوع يفنى أولئك الأنبياء '),
(17635, 'Jeremiah', 24, 14, 16, ' والشعب الذي يتنبأون له يكون مطروحا في شوارع أورشليم من جرى الجوع والسيف ، وليس من يدفنهم هم ونساؤهم وبنوهم وبناتهم ، وأسكب عليهم شرهم '),
(17636, 'Jeremiah', 24, 14, 17, ' وتقول لهم هذه الكلمة : لتذرف عيناي دموعا ليلا ونهارا ولا تكفا ، لأن العذراء بنت شعبي سحقت سحقا عظيما ، بضربة موجعة جدا '),
(17637, 'Jeremiah', 24, 14, 18, ' إذا خرجت إلى الحقل ، فإذا القتلى بالسيف . وإذا دخلت المدينة ، فإذا المرضى بالجوع ، لأن النبي والكاهن كليهما يطوفان في الأرض ولا يعرفان شيئا '),
(17638, 'Jeremiah', 24, 14, 19, ' هل رفضت يهوذا رفضا ، أو كرهت نفسك صهيون ؟ لماذا ضربتنا ولا شفاء لنا ؟ انتظرنا السلام فلم يكن خير ، وزمان الشفاء فإذا رعب '),
(17639, 'Jeremiah', 24, 14, 20, ' قد عرفنا يارب شرنا ، إثم آبائنا ، لأننا قد أخطأنا إليك '),
(17640, 'Jeremiah', 24, 14, 21, ' لا ترفض لأجل اسمك . لا تهن كرسي مجدك . اذكر . لا تنقض عهدك معنا '),
(17641, 'Jeremiah', 24, 14, 22, ' هل يوجد في أباطيل الأمم من يمطر ، أو هل تعطي السماوات وابلا ؟ أما أنت هو الرب إلهنا ؟ فنرجوك ، لأنك أنت صنعت كل هذه '),
(17642, 'Jeremiah', 24, 15, 1, ' ثم قال الرب لي : وإن وقف موسى وصموئيل أمامي لا تكون نفسي نحو هذا الشعب . اطرحهم من أمامي فيخرجوا '),
(17643, 'Jeremiah', 24, 15, 2, ' ويكون إذا قالوا لك : إلى أين نخرج ؟ أنك تقول لهم : هكذا قال الرب : الذين للموت فإلى الموت ، والذين للسيف فإلى السيف ، والذين للجوع فإلى الجوع ، والذين للسبي فإلى السبي '),
(17644, 'Jeremiah', 24, 15, 3, ' وأوكل عليهم أربعة أنواع ، يقول الرب : السيف للقتل ، والكلاب للسحب ، وطيور السماء ووحوش الأرض للأكل والإهلاك '),
(17645, 'Jeremiah', 24, 15, 4, ' وأدفعهم للقلق في كل ممالك الأرض من أجل منسى بن حزقيا ملك يهوذا ، من أجل ما صنع في أورشليم '),
(17646, 'Jeremiah', 24, 15, 5, ' فمن يشفق عليك يا أورشليم ، ومن يعزيك ، ومن يميل ليسأل عن سلامتك '),
(17647, 'Jeremiah', 24, 15, 6, ' أنت تركتني ، يقول الرب . إلى الوراء سرت . فأمد يدي عليك وأهلكك . مللت من الندامة '),
(17648, 'Jeremiah', 24, 15, 7, ' وأذريهم بمذراة في أبواب الأرض . أثكل وأبيد شعبي . لم يرجعوا عن طرقهم '),
(17649, 'Jeremiah', 24, 15, 8, ' كثرت لي أراملهم أكثر من رمل البحار . جلبت عليهم ، على أم الشبان ، ناهبا في الظهيرة . أوقعت عليها بغتة رعدة ورعبات '),
(17650, 'Jeremiah', 24, 15, 9, ' ذبلت والدة السبعة . أسلمت نفسها . غربت شمسها إذ بعد نهار . خزيت وخجلت . أما بقيتهم فللسيف أدفعها أمام أعدائهم ، يقول الرب '),
(17651, 'Jeremiah', 24, 15, 10, ' ويل لي يا أمي لأنك ولدتني إنسان خصام وإنسان نزاع لكل الأرض . لم أقرض ولا أقرضوني ، وكل واحد يلعنني '),
(17652, 'Jeremiah', 24, 15, 11, ' قال الرب : إني أحلك للخير . إني أجعل العدو يتضرع إليك في وقت الشر وفي وقت الضيق '),
(17653, 'Jeremiah', 24, 15, 12, ' هل يكسر الحديد الحديد الذي من الشمال والنحاس '),
(17654, 'Jeremiah', 24, 15, 13, ' ثروتك وخزائنك أدفعها للنهب ، لا بثمن ، بل بكل خطاياك وفي كل تخومك '),
(17655, 'Jeremiah', 24, 15, 14, ' وأعبرك مع أعدائك في أرض لم تعرفها ، لأن نارا قد أشعلت بغضبي توقد عليكم '),
(17656, 'Jeremiah', 24, 15, 15, ' أنت يارب عرفت . اذكرني وتعهدني وانتقم لي من مضطهدي . بطول أناتك لا تأخذني . اعرف احتمالي العار لأجلك '),
(17657, 'Jeremiah', 24, 15, 16, ' وجد كلامك فأكلته ، فكان كلامك لي للفرح ولبهجة قلبي ، لأني دعيت باسمك يارب إله الجنود '),
(17658, 'Jeremiah', 24, 15, 17, ' لم أجلس في محفل المازحين مبتهجا . من أجل يدك جلست وحدي ، لأنك قد ملأتني غضبا '),
(17659, 'Jeremiah', 24, 15, 18, ' لماذا كان وجعي دائما وجرحي عديم الشفاء ، يأبى أن يشفى ؟ أتكون لي مثل كاذب ، مثل مياه غير دائمة '),
(17660, 'Jeremiah', 24, 15, 19, ' لذلك هكذا قال الرب : إن رجعت أرجعك ، فتقف أمامي . وإذا أخرجت الثمين من المرذول فمثل فمي تكون . هم يرجعون إليك وأنت لا ترجع إليهم '),
(17661, 'Jeremiah', 24, 15, 20, ' وأجعلك لهذا الشعب سور نحاس حصينا ، فيحاربونك ولا يقدرون عليك ، لأني معك لأخلصك وأنقذك ، يقول الرب '),
(17662, 'Jeremiah', 24, 15, 21, ' فأنقذك من يد الأشرار وأفديك من كف العتاة '),
(17663, 'Jeremiah', 24, 16, 1, ' ثم صار إلي كلام الرب قائلا '),
(17664, 'Jeremiah', 24, 16, 2, ' لا تتخذ لنفسك امرأة ، ولا يكن لك بنون ولا بنات في هذا الموضع '),
(17665, 'Jeremiah', 24, 16, 3, ' لأنه هكذا قال الرب عن البنين وعن البنات المولودين في هذا الموضع ، وعن أمهاتهم اللواتي ولدنهم ، وعن آبائهم الذين ولدوهم في هذه الأرض '),
(17666, 'Jeremiah', 24, 16, 4, ' ميتات أمراض يموتون . لا يندبون ولا يدفنون ، بل يكونون دمنة على وجه الأرض ، وبالسيف والجوع يفنون ، وتكون جثثهم أكلا لطيور السماء ولوحوش الأرض '),
(17667, 'Jeremiah', 24, 16, 5, ' لأنه هكذا قال الرب : لا تدخل بيت النوح ولا تمض للندب ولا تعزهم ، لأني نزعت سلامي من هذا الشعب ، يقول الرب ، الإحسان والمراحم '),
(17668, 'Jeremiah', 24, 16, 6, ' فيموت الكبار والصغار في هذه الأرض . لا يدفنون ولا يندبونهم ، ولا يخمشون أنفسهم ولا يجعلون قرعة من أجلهم '),
(17669, 'Jeremiah', 24, 16, 7, ' ولا يكسرون خبزا في المناحة ليعزوهم عن ميت ، ولا يسقونهم كأس التعزية عن أب أو أم '),
(17670, 'Jeremiah', 24, 16, 8, ' ولا تدخل بيت الوليمة لتجلس معهم للأكل والشرب '),
(17671, 'Jeremiah', 24, 16, 9, ' لأنه هكذا قال رب الجنود إله إسرائيل : هأنذا مبطل من هذا الموضع ، أمام أعينكم وفي أيامكم ، صوت الطرب وصوت الفرح ، صوت العريس وصوت العروس '),
(17672, 'Jeremiah', 24, 16, 10, ' ويكون حين تخبر هذا الشعب بكل هذه الأمور أنهم يقولون لك : لماذا تكلم الرب علينا بكل هذا الشر العظيم ، فما هو ذنبنا وما هي خطيتنا التي أخطأناها إلى الرب إلهنا '),
(17673, 'Jeremiah', 24, 16, 11, ' فتقول لهم : من أجل أن آباءكم قد تركوني ، يقول الرب ، وذهبوا وراء آلهة أخرى وعبدوها وسجدوا لها ، وإياي تركوا ، وشريعتي لم يحفظوها '),
(17674, 'Jeremiah', 24, 16, 12, ' وأنتم أسأتم في عملكم أكثر من آبائكم . وها أنتم ذاهبون كل واحد وراء عناد قلبه الشرير حتى لا تسمعوا لي '),
(17675, 'Jeremiah', 24, 16, 13, ' فأطردكم من هذه الأرض إلى أرض لم تعرفوها أنتم ولا آباؤكم ، فتعبدون هناك آلهة أخرى نهارا وليلا حيث لا أعطيكم نعمة '),
(17676, 'Jeremiah', 24, 16, 14, ' لذلك ها أيام تأتي ، يقول الرب ، ولا يقال بعد : حي هو الرب الذي أصعد بني إسرائيل من أرض مصر '),
(17677, 'Jeremiah', 24, 16, 15, ' بل : حي هو الرب الذي أصعد بني إسرائيل من أرض الشمال ومن جميع الأراضي التي طردهم إليها . فأرجعهم إلى أرضهم التي أعطيت آباءهم إياها '),
(17678, 'Jeremiah', 24, 16, 16, ' هأنذا أرسل إلى جزافين كثيرين ، يقول الرب ، فيصطادونهم ، ثم بعد ذلك أرسل إلى كثيرين من القانصين فيقتنصونهم عن كل جبل وعن كل أكمة ومن شقوق الصخور '),
(17679, 'Jeremiah', 24, 16, 17, ' لأن عيني على كل طرقهم . لم تستتر عن وجهي ، ولم يختف إثمهم من أمام عيني '),
(17680, 'Jeremiah', 24, 16, 18, ' وأعاقب أولا إثمهم وخطيتهم ضعفين ، لأنهم دنسوا أرضي ، وبجثث مكرهاتهم ورجاساتهم قد ملأوا ميراثي '),
(17681, 'Jeremiah', 24, 16, 19, ' يارب ، عزي وحصني وملجإي في يوم الضيق ، إليك تأتي الأمم من أطراف الأرض ، ويقولون : إنما ورث آباؤنا كذبا وأباطيل وما لا منفعة فيه '),
(17682, 'Jeremiah', 24, 16, 20, ' هل يصنع الإنسان لنفسه آلهة وهي ليست آلهة '),
(17683, 'Jeremiah', 24, 16, 21, ' لذلك هأنذا أعرفهم هذه المرة ، أعرفهم يدي وجبروتي ، فيعرفون أن اسمي يهوه '),
(17684, 'Jeremiah', 24, 17, 1, ' خطية يهوذا مكتوبة بقلم من حديد ، برأس من الماس منقوشة على لوح قلبهم وعلى قرون مذابحكم '),
(17685, 'Jeremiah', 24, 17, 2, ' كذكر بنيهم مذابحهم ، وسواريهم عند أشجار خضر على آكام مرتفعة '),
(17686, 'Jeremiah', 24, 17, 3, ' يا جبلي في الحقل ، أجعل ثروتك ، كل خزائنك للنهب ، ومرتفعاتك للخطية في كل تخومك '),
(17687, 'Jeremiah', 24, 17, 4, ' وتتبرأ وبنفسك عن ميراثك الذي أعطيتك إياه ، وأجعلك تخدم أعداءك في أرض لم تعرفها ، لأنكم قد أضرمتم نارا بغضبي تتقد إلى الأبد '),
(17688, 'Jeremiah', 24, 17, 5, ' هكذا قال الرب : ملعون الرجل الذي يتكل على الإنسان ، ويجعل البشر ذراعه ، وعن الرب يحيد قلبه '),
(17689, 'Jeremiah', 24, 17, 6, ' ويكون مثل العرعر في البادية ، ولا يرى إذا جاء الخير ، بل يسكن الحرة في البرية ، أرضا سبخة وغير مسكونة '),
(17690, 'Jeremiah', 24, 17, 7, ' مبارك الرجل الذي يتكل على الرب ، وكان الرب متكله '),
(17691, 'Jeremiah', 24, 17, 8, ' فإنه يكون كشجرة مغروسة على مياه ، وعلى نهر تمد أصولها ، ولا ترى إذا جاء الحر ، ويكون ورقها أخضر ، وفي سنة القحط لا تخاف ، ولا تكف عن الإثمار '),
(17692, 'Jeremiah', 24, 17, 9, ' القلب أخدع من كل شيء وهو نجيس ، من يعرفه '),
(17693, 'Jeremiah', 24, 17, 10, ' أنا الرب فاحص القلب مختبر الكلى لأعطي كل واحد حسب طرقه ، حسب ثمر أعماله '),
(17694, 'Jeremiah', 24, 17, 11, ' حجلة تحضن ما لم تبض محصل الغنى بغير حق . في نصف أيامه يتركه وفي آخرته يكون أحمق '),
(17695, 'Jeremiah', 24, 17, 12, ' كرسي مجد مرتفع من الابتداء هو موضع مقدسنا '),
(17696, 'Jeremiah', 24, 17, 13, ' أيها الرب رجاء إسرائيل ، كل الذين يتركونك يخزون . الحائدون عني في التراب يكتبون ، لأنهم تركوا الرب ينبوع المياه الحية '),
(17697, 'Jeremiah', 24, 17, 14, ' اشفني يارب فأشفى . خلصني فأخلص ، لأنك أنت تسبيحتي '),
(17698, 'Jeremiah', 24, 17, 15, ' ها هم يقولون لي : أين هي كلمة الرب ؟ لتأت '),
(17699, 'Jeremiah', 24, 17, 16, ' أما أنا فلم أعتزل عن أن أكون راعيا وراءك ، ولا اشتهيت يوم البلية . أنت عرفت . ما خرج من شفتي كان مقابل وجهك '),
(17700, 'Jeremiah', 24, 17, 17, ' لا تكن لي رعبا . أنت ملجإي في يوم الشر '),
(17701, 'Jeremiah', 24, 17, 18, ' ليخز طاردي ولا أخز أنا . ليرتعبوا هم ولا أرتعب أنا . اجلب عليهم يوم الشر واسحقهم سحقا مضاعفا '),
(17702, 'Jeremiah', 24, 17, 19, ' هكذا قال الرب لي : اذهب وقف في باب بني الشعب الذي يدخل منه ملوك يهوذا ويخرجون منه ، وفي كل أبواب أورشليم '),
(17703, 'Jeremiah', 24, 17, 20, ' وقل لهم : اسمعوا كلمة الرب يا ملوك يهوذا ، وكل يهوذا ، وكل سكان أورشليم الداخلين من هذه الأبواب '),
(17704, 'Jeremiah', 24, 17, 21, ' هكذا قال الرب : تحفظوا بأنفسكم ولا تحملوا حملا يوم السبت ولا تدخلوه في أبواب أورشليم '),
(17705, 'Jeremiah', 24, 17, 22, ' ولا تخرجوا حملا من بيوتكم يوم السبت ، ولا تعملوا شغلا ما ، بل قدسوا يوم السبت كما أمرت آباءكم '),
(17706, 'Jeremiah', 24, 17, 23, ' فلم يسمعوا ولم يميلوا أذنهم ، بل قسوا أعناقهم لئلا يسمعوا ولئلا يقبلوا تأديبا '),
(17707, 'Jeremiah', 24, 17, 24, ' ويكون إذا سمعتم لي سمعا ، يقول الرب ، ولم تدخلوا حملا في أبواب هذه المدينة يوم السبت ، بل قدستم يوم السبت ولم تعملوا فيه شغلا ما '),
(17708, 'Jeremiah', 24, 17, 25, ' أنه يدخل في أبواب هذه المدينة ملوك ورؤساء جالسون على كرسي داود ، راكبون في مركبات وعلى خيل ، هم ورؤساؤهم رجال يهوذا وسكان أورشليم ، وتسكن هذه المدينة إلى الأبد '),
(17709, 'Jeremiah', 24, 17, 26, ' ويأتون من مدن يهوذا ، ومن حوالي أورشليم ومن أرض بنيامين ومن السهل ومن الجبال ومن الجنوب ، يأتون بمحرقات وذبائح وتقدمات ولبان ، ويدخلون بذبائح شكر إلى بيت الرب '),
(17710, 'Jeremiah', 24, 17, 27, ' ولكن إن لم تسمعوا لي لتقدسوا يوم السبت لكيلا تحملوا حملا ولا تدخلوه في أبواب أورشليم يوم السبت ، فإني أشعل نارا في أبوابها فتأكل قصور أورشليم ولا تنطفئ '),
(17711, 'Jeremiah', 24, 18, 1, ' الكلام الذي صار إلى إرميا من قبل الرب قائلا '),
(17712, 'Jeremiah', 24, 18, 2, ' قم انزل إلى بيت الفخاري وهناك أسمعك كلامي '),
(17713, 'Jeremiah', 24, 18, 3, ' فنزلت إلى بيت الفخاري ، وإذا هو يصنع عملا على الدولاب '),
(17714, 'Jeremiah', 24, 18, 4, ' ففسد الوعاء الذي كان يصنعه من الطين بيد الفخاري ، فعاد وعمله وعاء آخر كما حسن في عيني الفخاري أن يصنعه '),
(17715, 'Jeremiah', 24, 18, 5, ' فصار إلي كلام الرب قائلا '),
(17716, 'Jeremiah', 24, 18, 6, ' أما أستطيع أن أصنع بكم كهذا الفخاري يا بيت إسرائيل ، يقول الرب ؟ هوذا كالطين بيد الفخاري أنتم هكذا بيدي يا بيت إسرائيل '),
(17717, 'Jeremiah', 24, 18, 7, ' تارة أتكلم على أمة وعلى مملكة بالقلع والهدم والإهلاك '),
(17718, 'Jeremiah', 24, 18, 8, ' فترجع تلك الأمة التي تكلمت عليها عن شرها ، فأندم عن الشر الذي قصدت أن أصنعه بها '),
(17719, 'Jeremiah', 24, 18, 9, ' وتارة أتكلم على أمة وعلى مملكة بالبناء والغرس '),
(17720, 'Jeremiah', 24, 18, 10, ' فتفعل الشر في عيني ، فلا تسمع لصوتي ، فأندم عن الخير الذي قلت إني أحسن إليها به '),
(17721, 'Jeremiah', 24, 18, 11, ' فالآن كلم رجال يهوذا وسكان أورشليم قائلا : هكذا قال الرب : هأنذا مصدر عليكم شرا ، وقاصد عليكم قصدا . فارجعوا كل واحد عن طريقه الرديء ، وأصلحوا طرقكم وأعمالكم '),
(17722, 'Jeremiah', 24, 18, 12, ' فقالوا : باطل لأننا نسعى وراء أفكارنا ، وكل واحد يعمل حسب عناد قلبه الرديء '),
(17723, 'Jeremiah', 24, 18, 13, ' لذلك هكذا قال الرب : اسألوا بين الأمم . من سمع كهذه ؟ ما يقشعر منه جدا عملت عذراء إسرائيل '),
(17724, 'Jeremiah', 24, 18, 14, ' هل يخلو صخر حقلي من ثلج لبنان ؟ أو هل تنشف المياه المنفجرة الباردة الجارية '),
(17725, 'Jeremiah', 24, 18, 15, ' لأن شعبي قد نسيني بخروا للباطل ، وقد أعثروهم في طرقهم ، في السبل القديمة ليسلكوا في شعب ، في طريق غير مسهل '),
(17726, 'Jeremiah', 24, 18, 16, ' لتجعل أرضهم خرابا وصفيرا أبديا . كل مار فيها يدهش وينغض رأسه '),
(17727, 'Jeremiah', 24, 18, 17, ' كريح شرقية أبددهم أمام العدو . أريهم القفا لا الوجه في يوم مصيبتهم '),
(17728, 'Jeremiah', 24, 18, 18, ' فقالوا : هلم فنفكر على إرميا أفكارا ، لأن الشريعة لا تبيد عن الكاهن ، ولا المشورة عن الحكيم ، ولا الكلمة عن النبي . هلم فنضربه باللسان ولكل كلامه لا نصغي '),
(17729, 'Jeremiah', 24, 18, 19, ' أصغ لي يارب ، واسمع صوت أخصامي '),
(17730, 'Jeremiah', 24, 18, 20, ' هل يجازى عن خير بشر ؟ لأنهم حفروا حفرة لنفسي . اذكر وقوفي أمامك لأتكلم عنهم بالخير لأرد غضبك عنهم ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(17731, 'Jeremiah', 24, 18, 21, ' لذلك سلم بنيهم للجوع ، وادفعهم ليد السيف ، فتصير نساؤهم ثكالى وأرامل ، وتصير رجالهم قتلى الموت ، وشبانهم مضروبي السيف في الحرب '),
(17732, 'Jeremiah', 24, 18, 22, ' ليسمع صياح من بيوتهم إذ تجلب عليهم جيشا بغتة . لأنهم حفروا حفرة ليمسكوني ، وطمروا فخاخا لرجلي '),
(17733, 'Jeremiah', 24, 18, 23, ' وأنت يارب عرفت كل مشورتهم علي للموت . لا تصفح عن إثمهم ، ولا تمح خطيتهم من أمامك ، بل ليكونوا متعثرين أمامك . في وقت غضبك عاملهم '),
(17734, 'Jeremiah', 24, 19, 1, ' هكذا قال الرب : اذهب واشتر إبريق فخاري من خزف ، وخذ من شيوخ الشعب ومن شيوخ الكهنة '),
(17735, 'Jeremiah', 24, 19, 2, ' واخرج إلى وادي ابن هنوم الذي عند مدخل باب الفخار ، وناد هناك بالكلمات التي أكلمك بها '),
(17736, 'Jeremiah', 24, 19, 3, ' وقل : اسمعوا كلمة الرب يا ملوك يهوذا وسكان أورشليم . هكذا قال رب الجنود إله إسرائيل : هأنذا جالب على هذا الموضع شرا ، كل من سمع به تطن أذناه '),
(17737, 'Jeremiah', 24, 19, 4, ' من أجل أنهم تركوني ، وأنكروا هذا الموضع وبخروا فيه لآلهة أخرى لم يعرفوها هم ولا آباؤهم ولا ملوك يهوذا ، وملأوا هذا الموضع من دم الأزكياء '),
(17738, 'Jeremiah', 24, 19, 5, ' وبنوا مرتفعات للبعل ليحرقوا أولادهم بالنار محرقات للبعل ، الذي لم أوص ولا تكلمت به ولا صعد على قلبي '),
(17739, 'Jeremiah', 24, 19, 6, ' لذلك ها أيام تأتي ، يقول الرب ، ولا يدعى بعد هذا الموضع توفة ولا وادي ابن هنوم ، بل وادي القتل '),
(17740, 'Jeremiah', 24, 19, 7, ' وأنقض مشورة يهوذا وأورشليم في هذا الموضع ، وأجعلهم يسقطون بالسيف أمام أعدائهم وبيد طالبي نفوسهم ، وأجعل جثثهم أكلا لطيور السماء ولوحوش الأرض '),
(17741, 'Jeremiah', 24, 19, 8, ' وأجعل هذه المدينة للدهش والصفير . كل عابر بها يدهش ويصفر من أجل كل ضرباتها '),
(17742, 'Jeremiah', 24, 19, 9, ' وأطعمهم لحم بنيهم ولحم بناتهم ، فيأكلون كل واحد لحم صاحبه في الحصار والضيق الذي يضايقهم به أعداؤهم وطالبو نفوسهم '),
(17743, 'Jeremiah', 24, 19, 10, ' ثم تكسر الإبريق أمام أعين القوم الذين يسيرون معك '),
(17744, 'Jeremiah', 24, 19, 11, ' وتقول لهم : هكذا قال رب الجنود : هكذا أكسر هذا الشعب وهذه المدينة كما يكسر وعاء الفخاري بحيث لا يمكن جبره بعد ، وفي توفة يدفنون حتى لا يكون موضع للدفن '),
(17745, 'Jeremiah', 24, 19, 12, ' هكذا أصنع لهذا الموضع ، يقول الرب ، ولسكانه . وأجعل هذه المدينة مثل توفة '),
(17746, 'Jeremiah', 24, 19, 13, ' وتكون بيوت أورشليم وبيوت ملوك يهوذا كموضع توفة ، نجسة كل البيوت التي بخروا على سطوحها لكل جند السماء وسكبوا سكائب لآلهة أخرى '),
(17747, 'Jeremiah', 24, 19, 14, ' ثم جاء إرميا من توفة التي أرسله الرب إليها ليتنبأ ، ووقف في دار بيت الرب وقال لكل الشعب '),
(17748, 'Jeremiah', 24, 19, 15, ' هكذا قال رب الجنود إله إسرائيل : هأنذا جالب على هذه المدينة وعلى كل قراها كل الشر الذي تكلمت به عليها ، لأنهم صلبوا رقابهم فلم يسمعوا لكلامي '),
(17749, 'Jeremiah', 24, 20, 1, ' وسمع فشحور بن إمير الكاهن ، وهو ناظر أول في بيت الرب ، إرميا يتنبأ بهذه الكلمات '),
(17750, 'Jeremiah', 24, 20, 2, ' فضرب فشحور إرميا النبي ، وجعله في المقطرة التي في باب بنيامين الأعلى الذي عند بيت الرب '),
(17751, 'Jeremiah', 24, 20, 3, ' وكان في الغد أن فشحور أخرج إرميا من المقطرة . فقال له إرميا : لم يدع الرب اسمك فشحور ، بل مجور مسابيب '),
(17752, 'Jeremiah', 24, 20, 4, ' لأنه هكذا قال الرب : هأنذا أجعلك خوفا لنفسك ولكل محبيك ، فيسقطون بسيف أعدائهم وعيناك تنظران ، وأدفع كل يهوذا ليد ملك بابل فيسبيهم إلى بابل ويضربهم بالسيف '),
(17753, 'Jeremiah', 24, 20, 5, ' وأدفع كل ثروة هذه المدينة وكل تعبها وكل مثمناتها وكل خزائن ملوك يهوذا ، أدفعها ليد أعدائهم ، فيغنمونها ويأخذونها ويحضرونها إلى بابل '),
(17754, 'Jeremiah', 24, 20, 6, ' وأنت يا فشحور وكل سكان بيتك تذهبون في السبي ، وتأتي إلى بابل وهناك تموت ، وهناك تدفن أنت وكل محبيك الذين تنبأت لهم بالكذب '),
(17755, 'Jeremiah', 24, 20, 7, ' قد أقنعتني يارب فاقتنعت ، وألححت علي فغلبت . صرت للضحك كل النهار . كل واحد استهزأ بي '),
(17756, 'Jeremiah', 24, 20, 8, ' لأني كلما تكلمت صرخت . ناديت : ظلم واغتصاب ، لأن كلمة الرب صارت لي للعار وللسخرة كل النهار '),
(17757, 'Jeremiah', 24, 20, 9, ' فقلت : لا أذكره ولا أنطق بعد باسمه . فكان في قلبي كنار محرقة محصورة في عظامي ، فمللت من الإمساك ولم أستطع '),
(17758, 'Jeremiah', 24, 20, 10, ' لأني سمعت مذمة من كثيرين . خوف من كل جانب . يقولون : اشتكوا ، فنشتكي عليه . كل أصحابي يراقبون ظلعي قائلين : لعله يطغى فنقدر عليه وننتقم منه '),
(17759, 'Jeremiah', 24, 20, 11, ' ولكن الرب معي كجبار قدير . من أجل ذلك يعثر مضطهدي ولا يقدرون . خزوا جدا لأنهم لم ينجحوا ، خزيا أبديا لا ينسى '),
(17760, 'Jeremiah', 24, 20, 12, ' فيارب الجنود ، مختبر الصديق ، ناظر الكلى والقلب ، دعني أرى نقمتك منهم لأني لك كشفت دعواي '),
(17761, 'Jeremiah', 24, 20, 13, ' رنموا للرب ، سبحوا الرب ، لأنه قد أنقذ نفس المسكين من يد الأشرار '),
(17762, 'Jeremiah', 24, 20, 14, ' ملعون اليوم الذي ولدت فيه اليوم الذي ولدتني فيه أمي لا يكن مباركا '),
(17763, 'Jeremiah', 24, 20, 15, ' ملعون الإنسان الذي بشر أبي قائلا : قد ولد لك ابن ، مفرحا إياه فرحا '),
(17764, 'Jeremiah', 24, 20, 16, ' وليكن ذلك الإنسان كالمدن التي قلبها الرب ولم يندم ، فيسمع صياحا في الصباح وجلبة في وقت الظهيرة '),
(17765, 'Jeremiah', 24, 20, 17, ' لأنه لم يقتلني من الرحم ، فكانت لي أمي قبري ورحمها حبلى إلى الأبد '),
(17766, 'Jeremiah', 24, 20, 18, ' لماذا خرجت من الرحم ، لأرى تعبا وحزنا فتفنى بالخزي أيامي '),
(17767, 'Jeremiah', 24, 21, 1, ' الكلام الذي صار إلى إرميا من قبل الرب ، حين أرسل إليه الملك صدقيا فشحور بن ملكيا وصفنيا بن معسيا الكاهن قائلا '),
(17768, 'Jeremiah', 24, 21, 2, ' اسأل الرب من أجلنا ، لأن نبوخذراصر ملك بابل يحاربنا . لعل الرب يصنع معنا حسب كل عجائبه فيصعد عنا '),
(17769, 'Jeremiah', 24, 32, 9, ' فاشتريت من حنمئيل ابن عمي الحقل الذي في عناثوث ، ووزنت له الفضة ، سبعة عشر شاقلا من الفضة '),
(17770, 'Jeremiah', 24, 32, 10, ' وكتبته في صك وختمت وأشهدت شهودا ، ووزنت الفضة بموازين '),
(17771, 'Jeremiah', 24, 32, 11, ' وأخذت صك الشراء المختوم حسب الوصية والفريضة والمفتوح '),
(17772, 'Jeremiah', 24, 32, 12, ' وسلمت صك الشراء لباروخ بن نيريا بن محسيا أمام حنمئيل ابن عمي ، وأمام الشهود الذين أمضوا صك الشراء أمام كل اليهود الجالسين في دار السجن '),
(17773, 'Jeremiah', 24, 32, 13, ' وأوصيت باروخ أمامهم قائلا '),
(17774, 'Jeremiah', 24, 32, 14, ' هكذا قال رب الجنود إله إسرائيل : خذ هذين الصكين ، صك الشراء هذا المختوم ، والصك المفتوح هذا ، واجعلهما في إناء من خزف لكي يبقيا أياما كثيرة '),
(17775, 'Jeremiah', 24, 32, 15, ' لأنه هكذا قال رب الجنود إله إسرائيل : سيشترون بعد بيوتا وحقولا وكروما في هذه الأرض '),
(17776, 'Jeremiah', 24, 32, 16, ' ثم صليت إلى الرب بعد تسليم صك الشراء لباروخ بن نيريا قائلا '),
(17777, 'Jeremiah', 24, 32, 17, ' آه ، أيها السيد الرب ، ها إنك قد صنعت السماوات والأرض بقوتك العظيمة ، وبذراعك الممدودة . لا يعسر عليك شيء '),
(17778, 'Jeremiah', 24, 32, 18, ' صانع الإحسان لألوف ، ومجازي ذنب الآباء في حضن بنيهم بعدهم ، الإله العظيم الجبار ، رب الجنود اسمه '),
(17779, 'Jeremiah', 24, 32, 19, ' عظيم في المشورة ، وقادر في العمل ، الذي عيناك مفتوحتان على كل طرق بني آدم لتعطي كل واحد حسب طرقه ، وحسب ثمر أعماله '),
(17780, 'Jeremiah', 24, 32, 20, ' الذي جعلت آيات وعجائب في أرض مصر إلى هذا اليوم ، وفي إسرائيل وفي الناس ، وجعلت لنفسك اسما كهذا اليوم '),
(17781, 'Jeremiah', 24, 32, 21, ' وأخرجت شعبك إسرائيل من أرض مصر بآيات وعجائب ، وبيد شديدة وذراع ممدودة ومخافة عظيمة '),
(17782, 'Jeremiah', 24, 32, 22, ' وأعطيتهم هذه الأرض التي حلفت لآبائهم أن تعطيهم إياها ، أرضا تفيض لبنا وعسلا '),
(17783, 'Jeremiah', 24, 32, 23, ' فأتوا وامتلكوها ، ولم يسمعوا لصوتك ، ولا ساروا في شريعتك . كل ما أوصيتهم أن يعملوه لم يعملوه ، فأوقعت بهم كل هذا الشر '),
(17784, 'Jeremiah', 24, 32, 24, ' ها المتارس قد أتوا إلى المدينة ليأخذوها ، وقد دفعت المدينة ليد الكلدانيين الذين يحاربونها بسبب السيف والجوع والوبإ ، وما تكلمت به فقد حدث ، وها أنت ناظر '),
(17785, 'Jeremiah', 24, 32, 25, ' وقد قلت أنت لي أيها السيد الرب : اشتر لنفسك الحقل بفضة وأشهد شهودا ، وقد دفعت المدينة ليد الكلدانيين '),
(17786, 'Jeremiah', 24, 32, 26, ' ثم صارت كلمة الرب إلى إرميا قائلة '),
(17787, 'Jeremiah', 24, 32, 27, ' هأنذا الرب إله كل ذي جسد . هل يعسر علي أمر ما '),
(17788, 'Jeremiah', 24, 32, 28, ' لذلك هكذا قال الرب : هأنذا أدفع هذه المدينة ليد الكلدانيين وليد نبوخذراصر ملك بابل فيأخذها '),
(17789, 'Jeremiah', 24, 32, 29, ' فيأتي الكلدانيون الذين يحاربون هذه المدينة ، فيشعلون هذه المدينة بالنار ، ويحرقونها والبيوت التي بخروا على سطوحها للبعل وسكبوا سكائب لآلهة أخرى ليغيظوني '),
(17790, 'Jeremiah', 24, 32, 30, ' لأن بني إسرائيل وبني يهوذا إنما صنعوا الشر في عيني منذ صباهم . لأن بني إسرائيل إنما أغاظوني بعمل أيديهم ، يقول الرب '),
(17791, 'Jeremiah', 24, 32, 31, ' لأن هذه المدينة قد صارت لي لغضبي ولغيظي من اليوم الذي فيه بنوها إلى هذا اليوم ، لأنزعها من أمام وجهي '),
(17792, 'Jeremiah', 24, 32, 32, ' من أجل كل شر بني إسرائيل وبني يهوذا الذي عملوه ليغيظوني به ، هم وملوكهم ورؤساؤهم وكهنتهم وأنبياؤهم ورجال يهوذا وسكان أورشليم '),
(17793, 'Jeremiah', 24, 32, 33, ' وقد حولوا لي القفا لا الوجه . وقد علمتهم مبكرا ومعلما ، ولكنهم لم يسمعوا ليقبلوا أدبا '),
(17794, 'Jeremiah', 24, 32, 34, ' بل وضعوا مكرهاتهم في البيت الذي دعي باسمي ، لينجسوه '),
(17795, 'Jeremiah', 24, 32, 35, ' وبنوا المرتفعات للبعل التي في وادي ابن هنوم ، ليجيزوا بنيهم وبناتهم في النار لمولك ، الأمر الذي لم أوصهم به ، ولا صعد على قلبي ، ليعملوا هذا الرجس ، ليجعلوا يهوذا يخطئ '),
(17796, 'Jeremiah', 24, 32, 36, ' والآن لذلك هكذا قال الرب إله إسرائيل عن هذه المدينة التي تقولون إنها قد دفعت ليد ملك بابل بالسيف والجوع والوبإ '),
(17797, 'Jeremiah', 24, 32, 37, ' هأنذا أجمعهم من كل الأراضي التي طردتهم إليها بغضبي وغيظي وبسخط عظيم ، وأردهم إلى هذا الموضع ، وأسكنهم آمنين '),
(17798, 'Jeremiah', 24, 32, 38, ' ويكونون لي شعبا وأنا أكون لهم إلها '),
(17799, 'Jeremiah', 24, 32, 39, ' وأعطيهم قلبا واحدا وطريقا واحدا ليخافوني كل الأيام ، لخيرهم وخير أولادهم بعدهم '),
(17800, 'Jeremiah', 24, 32, 40, ' وأقطع لهم عهدا أبديا أني لا أرجع عنهم لأحسن إليهم ، وأجعل مخافتي في قلوبهم فلا يحيدون عني '),
(17801, 'Jeremiah', 24, 32, 41, ' وأفرح بهم لأحسن إليهم ، وأغرسهم في هذه الأرض بالأمانة بكل قلبي وبكل نفسي '),
(17802, 'Jeremiah', 24, 32, 42, ' لأنه هكذا قال الرب : كما جلبت على هذا الشعب كل هذا الشر العظيم ، هكذا أجلب أنا عليهم كل الخير الذي تكلمت به إليهم '),
(17803, 'Jeremiah', 24, 32, 43, ' فتشترى الحقول في هذه الأرض التي تقولون إنها خربة بلا إنسان وبلا حيوان ، وقد دفعت ليد الكلدانيين '),
(17804, 'Jeremiah', 24, 32, 44, ' يشترون الحقول بفضة ، ويكتبون ذلك في صكوك ، ويختمون ويشهدون شهودا في أرض بنيامين وحوالي أورشليم ، وفي مدن يهوذا ومدن الجبل ومدن السهل ومدن الجنوب ، لأني أرد سبيهم ، يقول الرب '),
(17805, 'Jeremiah', 24, 33, 1, ' ثم صارت كلمة الرب إلى إرميا ثانية وهو محبوس بعد في دار السجن قائلة '),
(17806, 'Jeremiah', 24, 33, 2, ' هكذا قال الرب صانعها ، الرب مصورها ليثبتها ، يهوه اسمه '),
(17807, 'Jeremiah', 24, 33, 3, ' ادعني فأجيبك وأخبرك بعظائم وعوائص لم تعرفها '),
(17808, 'Jeremiah', 24, 33, 4, ' لأنه هكذا قال الرب إله إسرائيل عن بيوت هذه المدينة وعن بيوت ملوك يهوذا التي هدمت للمتاريس والمجانيق '),
(17809, 'Jeremiah', 24, 33, 5, ' يأتون ليحاربوا الكلدانيين ويملأوها من جيف الناس الذين ضربتهم بغضبي وغيظي ، والذين سترت وجهي عن هذه المدينة لأجل كل شرهم '),
(17810, 'Jeremiah', 24, 33, 6, ' هأنذا أضع عليها رفادة وعلاجا ، وأشفيهم وأعلن لهم كثرة السلام والأمانة '),
(17811, 'Jeremiah', 24, 33, 7, ' وأرد سبي يهوذا وسبي إسرائيل وأبنيهم كالأول '),
(17812, 'Jeremiah', 24, 33, 8, ' وأطهرهم من كل إثمهم الذي أخطأوا به إلي ، وأغفر كل ذنوبهم التي أخطأوا بها إلي ، والتي عصوا بها علي '),
(17813, 'Jeremiah', 24, 33, 9, ' فتكون لي اسم فرح للتسبيح وللزينة لدى كل أمم الأرض ، الذين يسمعون بكل الخير الذي أصنعه معهم ، فيخافون ويرتعدون من أجل كل الخير ومن أجل كل السلام الذي أصنعه لها '),
(17814, 'Jeremiah', 24, 33, 10, ' هكذا قال الرب : سيسمع بعد في هذا الموضع الذي تقولون إنه خرب بلا إنسان وبلا حيوان ، في مدن يهوذا ، وفي شوارع أورشليم الخربة بلا إنسان ولا ساكن ولا بهيمة '),
(17815, 'Jeremiah', 24, 33, 11, ' صوت الطرب وصوت الفرح ، صوت العريس وصوت العروس ، صوت القائلين : احمدوا رب الجنود لأن الرب صالح ، لأن إلى الأبد رحمته . صوت الذين يأتون بذبيحة الشكر إلى بيت الرب ، لأني أرد سبي الأرض كالأول ، يقول الرب '),
(17816, 'Jeremiah', 24, 33, 12, ' هكذا قال رب الجنود : سيكون بعد في هذا الموضع الخرب بلا إنسان ولا بهيمة وفي كل مدنه ، مسكن الرعاة المربضين الغنم '),
(17817, 'Jeremiah', 24, 33, 13, ' في مدن الجبل ومدن السهل ومدن الجنوب ، وفي أرض بنيامين وحوالي أورشليم ، وفي مدن يهوذا ، تمر أيضا الغنم تحت يدي المحصي ، يقول الرب '),
(17818, 'Jeremiah', 24, 33, 14, ' ها أيام تأتي ، يقول الرب ، وأقيم الكلمة الصالحة التي تكلمت بها إلى بيت إسرائيل وإلى بيت يهوذا '),
(17819, 'Jeremiah', 24, 33, 15, ' في تلك الأيام وفي ذلك الزمان أنبت لداود غصن البر ، فيجري عدلا وبرا في الأرض '),
(17820, 'Jeremiah', 24, 33, 16, ' في تلك الأيام يخلص يهوذا ، وتسكن أورشليم آمنة ، وهذا ما تتسمى به : الرب برنا '),
(17821, 'Jeremiah', 24, 33, 17, ' لأنه هكذا قال الرب : لا ينقطع لداود إنسان يجلس على كرسي بيت إسرائيل '),
(17822, 'Jeremiah', 24, 33, 18, ' ولا ينقطع للكهنة اللاويين إنسان من أمامي يصعد محرقة ، ويحرق تقدمة ، ويهييء ذبيحة كل الأيام '),
(17823, 'Jeremiah', 24, 33, 19, ' ثم صارت كلمة الرب إلى إرميا قائلة '),
(17824, 'Jeremiah', 24, 33, 20, ' هكذا قال الرب : إن نقضتم عهدي مع النهار ، وعهدي مع الليل حتى لا يكون نهار ولا ليل في وقتهما '),
(17825, 'Jeremiah', 24, 33, 21, ' فإن عهدي أيضا مع داود عبدي ينقض ، فلا يكون له ابن مالكا على كرسيه ، ومع اللاويين الكهنة خادمي '),
(17826, 'Jeremiah', 24, 33, 22, ' كما أن جند السماوات لا يعد ، ورمل البحر لا يحصى ، هكذا أكثر نسل داود عبدي واللاويين خادمي '),
(17827, 'Jeremiah', 24, 33, 23, ' ثم صارت كلمة الرب إلى إرميا قائلة '),
(17828, 'Jeremiah', 24, 33, 24, ' أما ترى ما تكلم به هذا الشعب قائلا : إن العشيرتين اللتين اختارهما الرب قد رفضهما . فقد احتقروا شعبي حتى لا يكونوا بعد أمة أمامهم '),
(17829, 'Jeremiah', 24, 33, 25, ' هكذا قال الرب : إن كنت لم أجعل عهدي مع النهار والليل ، فرائض السماوات والأرض '),
(17830, 'Jeremiah', 24, 33, 26, ' فإني أيضا أرفض نسل يعقوب وداود عبدي ، فلا آخذ من نسله حكاما لنسل إبراهيم وإسحاق ويعقوب ، لأني أرد سبيهم وأرحمهم '),
(17831, 'Jeremiah', 24, 34, 1, ' الكلمة التي صارت إلى إرميا من قبل الرب حين كان نبوخذناصر ملك بابل وكل جيشه وكل ممالك أراضي سلطان يده وكل الشعوب ، يحاربون أورشليم وكل مدنها قائلة '),
(17832, 'Jeremiah', 24, 34, 2, ' هكذا قال الرب إله إسرائيل : اذهب وكلم صدقيا ملك يهوذا وقل له : هكذا قال الرب : هأنذا أدفع هذه المدينة ليد ملك بابل فيحرقها بالنار '),
(17833, 'Jeremiah', 24, 34, 3, ' وأنت لا تفلت من يده ، بل تمسك إمساكا وتدفع ليده ، وترى عيناك عيني ملك بابل ، وتكلمه فما لفم وتذهب إلى بابل '),
(17834, 'Jeremiah', 24, 34, 4, ' ولكن اسمع كلمة الرب يا صدقيا ملك يهوذا . هكذا قال الرب من جهتك : لا تموت بالسيف '),
(17835, 'Jeremiah', 24, 34, 5, ' بسلام تموت ، وبإحراق آبائك الملوك الأولين الذين كانوا قبلك ، هكذا يحرقون لك ويندبونك قائلين : آه ، يا سيد . لأني أنا تكلمت بالكلمة ، يقول الرب '),
(17836, 'Jeremiah', 24, 34, 6, ' فكلم إرميا النبي صدقيا ملك يهوذا بكل هذا الكلام في أورشليم '),
(17837, 'Jeremiah', 24, 34, 7, ' إذ كان جيش ملك بابل يحارب أورشليم وكل مدن يهوذا الباقية : لخيش وعزيقة . لأن هاتين بقيتا في مدن يهوذا مدينتين حصينتين '),
(17838, 'Jeremiah', 24, 34, 8, ' الكلمة التي صارت إلى إرميا من قبل الرب ، بعد قطع الملك صدقيا عهدا مع كل الشعب الذي في أورشليم لينادوا بالعتق '),
(17839, 'Jeremiah', 24, 34, 9, ' أن يطلق كل واحد عبده وكل واحد أمته العبراني والعبرانية حرين ، حتى لا يستعبدهما ، أي أخويه اليهوديين ، أحد '),
(17840, 'Jeremiah', 24, 34, 10, ' فلما سمع كل الرؤساء وكل الشعب الذين دخلوا في العهد أن يطلقوا كل واحد عبده ، وكل واحد أمته حرين ولا يستعبدوهما بعد ، أطاعوا وأطلقوا '),
(17841, 'Jeremiah', 24, 34, 11, ' ولكنهم عادوا بعد ذلك فأرجعوا العبيد والإماء الذين أطلقوهم أحرارا ، وأخضعوهم عبيدا وإماء '),
(17842, 'Jeremiah', 24, 34, 12, ' فصارت كلمة الرب إلى إرميا من قبل الرب قائلة '),
(17843, 'Jeremiah', 24, 34, 13, ' هكذا قال الرب إله إسرائيل : أنا قطعت عهدا مع آبائكم يوم أخرجتهم من أرض مصر من بيت العبيد قائلا '),
(17844, 'Jeremiah', 24, 34, 14, ' في نهاية سبع سنين تطلقون كل واحد أخاه العبراني الذي بيع لك وخدمك ست سنين ، فتطلقه حرا من عندك . ولكن لم يسمع آباؤكم لي ولا أمالوا أذنهم '),
(17845, 'Jeremiah', 24, 34, 15, ' وقد رجعتم أنتم اليوم وفعلتم ما هو مستقيم في عيني ، منادين بالعتق كل واحد إلى صاحبه ، وقطعتم عهدا أمامي في البيت الذي دعي باسمي '),
(17846, 'Jeremiah', 24, 34, 16, ' ثم عدتم ودنستم اسمي وأرجعتم كل واحد عبده ، وكل واحد أمته الذين أطلقتموهم أحرارا لأنفسهم ، وأخضعتموهم ليكونوا لكم عبيدا وإماء '),
(17847, 'Jeremiah', 24, 34, 17, ' لذلك هكذا قال الرب : أنتم لم تسمعوا لي لتنادوا بالعتق كل واحد إلى أخيه ، وكل واحد إلى صاحبه . هأنذا أنادي لكم بالعتق ، يقول الرب ، للسيف والوبإ والجوع ، وأجعلكم قلقا لكل ممالك الأرض '),
(17848, 'Jeremiah', 24, 34, 18, ' وأدفع الناس الذين تعدوا عهدي ، الذين لم يقيموا كلام العهد الذي قطعوه أمامي . العجل الذي قطعوه إلى اثنين ، وجازوا بين قطعتيه '),
(17849, 'Jeremiah', 24, 34, 19, ' رؤساء يهوذا ورؤساء أورشليم ، الخصيان والكهنة وكل شعب الأرض الذين جازوا بين قطعتي العجل '),
(17850, 'Jeremiah', 24, 34, 20, ' أدفعهم ليد أعدائهم وليد طالبي نفوسهم ، فتكون جثثهم أكلا لطيور السماء ووحوش الأرض '),
(17851, 'Jeremiah', 24, 34, 21, ' وأدفع صدقيا ملك يهوذا ورؤساءه ليد أعدائهم ، وليد طالبي نفوسهم ، وليد جيش ملك بابل الذين صعدوا عنكم '),
(17852, 'Jeremiah', 24, 34, 22, ' هأنذا آمر ، يقول الرب ، وأردهم إلى هذه المدينة فيحاربونها ويأخذونها ويحرقونها بالنار ، وأجعل مدن يهوذا خربة بلا ساكن '),
(17853, 'Jeremiah', 24, 35, 1, ' الكلمة التي صارت إلى إرميا من قبل الرب في أيام يهوياقيم بن يوشيا ملك يهوذا قائلة '),
(17854, 'Jeremiah', 24, 35, 2, ' اذهب إلى بيت الركابيين وكلمهم ، وادخل بهم إلى بيت الرب إلى أحد المخادع واسقهم خمرا '),
(17855, 'Jeremiah', 24, 35, 3, ' فأخذت يازنيا بن إرميا بن حبصينيا وإخوته وكل بنيه وكل بيت الركابيين '),
(17856, 'Jeremiah', 24, 35, 4, ' ودخلت بهم إلى بيت الرب إلى مخدع بني حانان بن يجدليا رجل الله ، الذي بجانب مخدع الرؤساء ، الذي فوق مخدع معسيا بن شلوم حارس الباب '),
(17857, 'Jeremiah', 24, 35, 5, ' وجعلت أمام بني بيت الركابيين طاسات ملآنة خمرا وأقداحا ، وقلت لهم : اشربوا خمرا '),
(17858, 'Jeremiah', 24, 35, 6, ' فقالوا : لا نشرب خمرا ، لأن يوناداب بن ركاب أبانا أوصانا قائلا : لا تشربوا خمرا أنتم ولا بنوكم إلى الأبد '),
(17859, 'Jeremiah', 24, 35, 7, ' ولا تبنوا بيتا ، ولا تزرعوا زرعا ، ولا تغرسوا كرما ، ولا تكن لكم ، بل اسكنوا في الخيام كل أيامكم ، لكي تحيوا أياما كثيرة على وجه الأرض التي أنتم متغربون فيها '),
(17860, 'Jeremiah', 24, 35, 8, ' فسمعنا لصوت يوناداب بن ركاب أبينا في كل ما أوصانا به ، أن لا نشرب خمرا كل أيامنا ، نحن ونساؤنا وبنونا وبناتنا '),
(17861, 'Jeremiah', 24, 35, 9, ' وأن لا نبني بيوتا لسكنانا ، وأن لا يكون لنا كرم ولا حقل ولا زرع '),
(17862, 'Jeremiah', 24, 35, 10, ' فسكنا في الخيام ، وسمعنا وعملنا حسب كل ما أوصانا به يوناداب أبونا '),
(17863, 'Jeremiah', 24, 35, 11, ' ولكن كان لما صعد نبوخذراصر ملك بابل إلى الأرض ، أننا قلنا : هلم فندخل إلى أورشليم من وجه جيش الكلدانيين ومن وجه جيش الأراميين . فسكنا في أورشليم '),
(17864, 'Jeremiah', 24, 35, 12, ' ثم صارت كلمة الرب إلى إرميا قائلة '),
(17865, 'Jeremiah', 24, 35, 13, ' هكذا قال رب الجنود إله إسرائيل : اذهب وقل لرجال يهوذا وسكان أورشليم : أما تقبلون تأديبا لتسمعوا كلامي ، يقول الرب '),
(17866, 'Jeremiah', 24, 35, 14, ' قد أقيم كلام يوناداب بن ركاب الذي أوصى به بنيه أن لا يشربوا خمرا ، فلم يشربوا إلى هذا اليوم لأنهم سمعوا وصية أبيهم . وأنا قد كلمتكم مبكرا ومكلما ولم تسمعوا لي '),
(17867, 'Jeremiah', 24, 35, 15, ' وقد أرسلت إليكم كل عبيدي الأنبياء مبكرا ومرسلا قائلا : ارجعوا كل واحد عن طريقه الرديئة ، وأصلحوا أعمالكم ، ولا تذهبوا وراء آلهة أخرى لتعبدوها ، فتسكنوا في الأرض التي أعطيتكم وآباءكم . فلم تميلوا أذنكم ، ولا سمعتم لي '),
(17868, 'Jeremiah', 24, 35, 16, ' لأن بني يوناداب بن ركاب قد أقاموا وصية أبيهم التي أوصاهم بها . أما هذا الشعب فلم يسمع لي '),
(17869, 'Jeremiah', 24, 35, 17, ' لذلك هكذا قال الرب إله الجنود ، إله إسرائيل : هأنذا أجلب على يهوذا وعلى كل سكان أورشليم كل الشر الذي تكلمت به عليهم ، لأني كلمتهم فلم يسمعوا ، ودعوتهم فلم يجيبوا '),
(17870, 'Jeremiah', 24, 35, 18, ' وقال إرميا لبيت الركابيين : هكذا قال رب الجنود إله إسرائيل : من أجل أنكم سمعتم لوصية يوناداب أبيكم ، وحفظتم كل وصاياه وعملتم حسب كل ما أوصاكم به '),
(17871, 'Jeremiah', 24, 35, 19, ' لذلك هكذا قال رب الجنود إله إسرائيل : لا ينقطع ليوناداب بن ركاب إنسان يقف أمامي كل الأيام '),
(17872, 'Jeremiah', 24, 36, 1, ' وكان في السنة الرابعة ليهوياقيم بن يوشيا ملك يهوذا ، أن هذه الكلمة صارت إلى إرميا من قبل الرب قائلة '),
(17873, 'Jeremiah', 24, 36, 2, ' خذ لنفسك درج سفر ، واكتب فيه كل الكلام الذي كلمتك به على إسرائيل وعلى يهوذا وعلى كل الشعوب ، من اليوم الذي كلمتك فيه ، من أيام يوشيا إلى هذا اليوم '),
(17874, 'Jeremiah', 24, 36, 3, ' لعل بيت يهوذا يسمعون كل الشر الذي أنا مفكر أن أصنعه بهم ، فيرجعوا كل واحد عن طريقه الرديء ، فأغفر ذنبهم وخطيتهم '),
(17875, 'Jeremiah', 24, 36, 4, ' فدعا إرميا باروخ بن نيريا ، فكتب باروخ عن فم إرميا كل كلام الرب الذي كلمه به في درج السفر '),
(17876, 'Jeremiah', 24, 36, 5, ' وأوصى إرميا باروخ قائلا : أنا محبوس لا أقدر أن أدخل بيت الرب '),
(17877, 'Jeremiah', 24, 36, 6, ' فادخل أنت واقرأ في الدرج الذي كتبت عن فمي كل كلام الرب في آذان الشعب ، في بيت الرب في يوم الصوم ، واقرأه أيضا في آذان كل يهوذا القادمين من مدنهم '),
(17878, 'Jeremiah', 24, 36, 7, ' لعل تضرعهم يقع أمام الرب ، فيرجعوا كل واحد عن طريقه الرديء ، لأنه عظيم الغضب والغيظ اللذان تكلم بهما الرب على هذا الشعب '),
(17879, 'Jeremiah', 24, 36, 8, ' ففعل باروخ بن نيريا حسب كل ما أوصاه به إرميا النبي ، بقراءته في السفر كلام الرب في بيت الرب '),
(17880, 'Jeremiah', 24, 36, 9, ' وكان في السنة الخامسة ليهوياقيم بن يوشيا ملك يهوذا ، في الشهر التاسع ، أنهم نادوا لصوم أمام الرب ، كل الشعب في أورشليم ، وكل الشعب القادمين من مدن يهوذا إلى أورشليم '),
(17881, 'Jeremiah', 24, 36, 10, ' فقرأ باروخ في السفر كلام إرميا في بيت الرب في مخدع جمريا بن شافان الكاتب ، في الدار العليا ، في مدخل باب بيت الرب الجديد ، في آذان كل الشعب '),
(17882, 'Jeremiah', 24, 36, 11, ' فلما سمع ميخايا بن جمريا بن شافان كل كلام الرب من السفر '),
(17883, 'Jeremiah', 24, 36, 12, ' نزل إلى بيت الملك ، إلى مخدع الكاتب ، وإذا كل الرؤساء جلوس هناك : أليشاماع الكاتب ، ودلايا بن شمعيا ، وألناثان بن عكبور ، وجمريا بن شافان ، وصدقيا بن حننيا ، وكل الرؤساء '),
(17884, 'Jeremiah', 24, 36, 13, ' فأخبرهم ميخايا بكل الكلام الذي سمعه عندما قرأ باروخ السفر في آذان الشعب '),
(17885, 'Jeremiah', 24, 36, 14, ' فأرسل كل الرؤساء إلى باروخ يهودي بن نثنيا بن شلميا بن كوشي قائلين : الدرج الذي قرأت فيه في آذان الشعب ، خذه بيدك وتعال . فأخذ باروخ بن نيريا الدرج بيده وأتى إليهم '),
(17886, 'Jeremiah', 24, 36, 15, ' فقالوا له : اجلس واقرأه في آذاننا . فقرأ باروخ في آذانهم '),
(17887, 'Jeremiah', 24, 36, 16, ' فكان لما سمعوا كل الكلام أنهم خافوا ناظرين بعضهم إلى بعض ، وقالوا لباروخ : إخبارا نخبر الملك بكل هذا الكلام '),
(17888, 'Jeremiah', 24, 36, 17, ' ثم سألوا باروخ قائلين : أخبرنا كيف كتبت كل هذا الكلام عن فمه '),
(17889, 'Jeremiah', 24, 36, 18, ' فقال لهم باروخ : بفمه كان يقرأ لي كل هذا الكلام ، وأنا كنت أكتب في السفر بالحبر '),
(17890, 'Jeremiah', 24, 36, 19, ' فقال الرؤساء لباروخ : اذهب واختبئ أنت وإرميا ولا يعلم إنسان أين أنتما '),
(17891, 'Jeremiah', 24, 36, 20, ' ثم دخلوا إلى الملك إلى الدار ، وأودعوا الدرج في مخدع أليشاماع الكاتب ، وأخبروا في أذني الملك بكل الكلام '),
(17892, 'Jeremiah', 24, 36, 21, ' فأرسل الملك يهودي ليأخذ الدرج ، فأخذه من مخدع أليشاماع الكاتب ، وقرأه يهودي في أذني الملك ، وفي آذان كل الرؤساء الواقفين لدى الملك '),
(17893, 'Jeremiah', 24, 36, 22, ' وكان الملك جالسا في بيت الشتاء في الشهر التاسع ، والكانون قدامه متقد '),
(17894, 'Jeremiah', 24, 36, 23, ' وكان لما قرأ يهودي ثلاثة شطور أو أربعة أنه شقه بمبراة الكاتب ، وألقاه إلى النار التي في الكانون ، حتى فني كل الدرج في النار التي في الكانون '),
(17895, 'Jeremiah', 24, 36, 24, ' ولم يخف الملك ولا كل عبيده السامعين كل هذا الكلام ، ولا شققوا ثيابهم '),
(17896, 'Jeremiah', 24, 36, 25, ' ولكن ألناثان ودلايا وجمريا ترجوا الملك أن لا يحرق الدرج فلم يسمع لهم '),
(17897, 'Jeremiah', 24, 36, 26, ' بل أمر الملك يرحمئيل ابن الملك ، وسرايا بن عزرئيل ، وشلميا بن عبدئيل ، أن يقبضوا على باروخ الكاتب وإرميا النبي ، ولكن الرب خبأهما '),
(17898, 'Jeremiah', 24, 36, 27, ' ثم صارت كلمة الرب إلى إرميا بعد إحراق الملك الدرج والكلام الذي كتبه باروخ عن فم إرميا قائلة '),
(17899, 'Jeremiah', 24, 36, 28, ' عد فخذ لنفسك درجا آخر ، واكتب فيه كل الكلام الأول الذي كان في الدرج الأول الذي أحرقه يهوياقيم ملك يهوذا '),
(17900, 'Jeremiah', 24, 36, 29, ' وقل ليهوياقيم ملك يهوذا : هكذا قال الرب : أنت قد أحرقت ذلك الدرج قائلا : لماذا كتبت فيه قائلا : مجيئا يجيء ملك بابل ويهلك هذه الأرض ، ويلاشي منها الإنسان والحيوان '),
(17901, 'Jeremiah', 24, 36, 30, ' لذلك هكذا قال الرب عن يهوياقيم ملك يهوذا : لا يكون له جالس على كرسي داود ، وتكون جثته مطروحة للحر نهارا ، وللبرد ليلا '),
(17902, 'Jeremiah', 24, 36, 31, ' وأعاقبه ونسله وعبيده على إثمهم ، وأجلب عليهم وعلى سكان أورشليم وعلى رجال يهوذا كل الشر الذي كلمتهم عنه ولم يسمعوا '),
(17903, 'Jeremiah', 24, 36, 32, ' فأخذ إرميا درجا آخر ودفعه لباروخ بن نيريا الكاتب ، فكتب فيه عن فم إرميا كل كلام السفر الذي أحرقه يهوياقيم ملك يهوذا بالنار ، وزيد عليه أيضا كلام كثير مثله '),
(17904, 'Jeremiah', 24, 37, 1, ' وملك الملك صدقيا بن يوشيا مكان كنياهو بن يهوياقيم ، الذي ملكه نبوخذراصر ملك بابل في أرض يهوذا '),
(17905, 'Jeremiah', 24, 37, 2, ' ولم يسمع هو ولا عبيده ولا شعب الأرض لكلام الرب الذي تكلم به عن يد إرميا النبي '),
(17906, 'Jeremiah', 24, 37, 3, ' وأرسل الملك صدقيا يهوخل بن شلميا ، وصفنيا بن معسيا الكاهن إلى إرميا النبي قائلا : صل لأجلنا إلى الرب إلهنا '),
(17907, 'Jeremiah', 24, 37, 4, ' وكان إرميا يدخل ويخرج في وسط الشعب ، إذ لم يكونوا قد جعلوه في بيت السجن '),
(17908, 'Jeremiah', 24, 37, 5, ' وخرج جيش فرعون من مصر . فلما سمع الكلدانيون المحاصرون أورشليم بخبرهم ، صعدوا عن أورشليم '),
(17909, 'Jeremiah', 24, 37, 6, ' فصارت كلمة الرب إلى إرميا النبي قائلة '),
(17910, 'Jeremiah', 24, 37, 7, ' هكذا قال الرب إله إسرائيل : هكذا تقولون لملك يهوذا الذي أرسلكم إلي لتستشيروني : ها إن جيش فرعون الخارج إليكم لمساعدتكم ، يرجع إلى أرضه ، إلى مصر '),
(17911, 'Jeremiah', 24, 37, 8, ' ويرجع الكلدانيون ويحاربون هذه المدينة ويأخذونها ويحرقونها بالنار '),
(17912, 'Jeremiah', 24, 37, 9, ' هكذا قال الرب : لا تخدعوا أنفسكم قائلين : إن الكلدانيين سيذهبون عنا ، لأنهم لا يذهبون '),
(17913, 'Jeremiah', 24, 37, 10, ' لأنكم وإن ضربتم كل جيش الكلدانيين الذين يحاربونكم ، وبقي منهم رجال قد طعنوا ، فإنهم يقومون كل واحد في خيمته ويحرقون هذه المدينة بالنار '),
(17914, 'Jeremiah', 24, 37, 11, ' وكان لما أصعد جيش الكلدانيين عن أورشليم من وجه جيش فرعون '),
(17915, 'Jeremiah', 24, 37, 12, ' أن إرميا خرج من أورشليم لينطلق إلى أرض بنيامين لينساب من هناك في وسط الشعب '),
(17916, 'Jeremiah', 24, 37, 13, ' وفيما هو في باب بنيامين ، إذا هناك ناظر الحراس ، اسمه يرئيا بن شلميا بن حننيا ، فقبض على إرميا النبي قائلا : إنك تقع للكلدانيين '),
(17917, 'Jeremiah', 24, 37, 14, ' فقال إرميا : كذب لا أقع للكلدانيين . ولم يسمع له ، فقبض يرئيا على إرميا وأتى به إلى الرؤساء '),
(17918, 'Jeremiah', 24, 21, 3, ' فقال لهما إرميا : هكذا تقولان لصدقيا '),
(17919, 'Jeremiah', 24, 21, 4, ' هكذا قال الرب إله إسرائيل : هأنذا أرد أدوات الحرب التي بيدكم التي أنتم محاربون بها ملك بابل والكلدانيين الذين يحاصرونكم خارج السور ، وأجمعهم في وسط هذه المدينة '),
(17920, 'Jeremiah', 24, 21, 5, ' وأنا أحاربكم بيد ممدودة وبذراع شديدة ، وبغضب وحمو وغيظ عظيم '),
(17921, 'Jeremiah', 24, 21, 6, ' وأضرب سكان هذه المدينة ، الناس والبهائم معا . بوبإ عظيم يموتون '),
(17922, 'Jeremiah', 24, 21, 7, ' ثم بعد ذلك قال الرب : أدفع صدقيا ملك يهوذا وعبيده والشعب والباقين في هذه المدينة من الوبإ والسيف والجوع ليد نبوخذراصر ملك بابل وليد أعدائهم وليد طالبي نفوسهم ، فيضربهم بحد السيف . لا يترأف عليهم ولا يشفق ولا يرحم '),
(17923, 'Jeremiah', 24, 21, 8, ' وتقول لهذا الشعب : هكذا قال الرب : هأنذا أجعل أمامكم طريق الحياة وطريق الموت '),
(17924, 'Jeremiah', 24, 21, 9, ' الذي يقيم في هذه المدينة يموت بالسيف والجوع والوبإ . والذي يخرج ويسقط إلى الكلدانيين الذين يحاصرونكم يحيا وتصير نفسه له غنيمة '),
(17925, 'Jeremiah', 24, 21, 10, ' لأني قد جعلت وجهي على هذه المدينة للشر لا للخير ، يقول الرب . ليد ملك بابل تدفع فيحرقها بالنار '),
(17926, 'Jeremiah', 24, 21, 11, ' ولبيت ملك يهوذا تقول : اسمعوا كلمة الرب '),
(17927, 'Jeremiah', 24, 21, 12, ' يابيت داود ، هكذا قال الرب : اقضوا في الصباح عدلا ، وأنقذوا المغصوب من يد الظالم ، لئلا يخرج كنار غضبي فيحرق وليس من يطفئ ، من أجل شر أعمالكم '),
(17928, 'Jeremiah', 24, 21, 13, ' هأنذا ضدك يا ساكنة العمق ، صخرة السهل ، يقول الرب . الذين يقولون : من ينزل علينا ومن يدخل إلى منازلنا '),
(17929, 'Jeremiah', 24, 21, 14, ' ولكنني أعاقبكم حسب ثمر أعمالكم ، يقول الرب ، وأشعل نارا في وعره فتأكل ما حواليها '),
(17930, 'Jeremiah', 24, 22, 1, ' هكذا قال الرب : انزل إلى بيت ملك يهوذا وتكلم هناك بهذه الكلمة '),
(17931, 'Jeremiah', 24, 22, 2, ' وقل : اسمع كلمة الرب يا ملك يهوذا الجالس على كرسي داود ، أنت وعبيدك وشعبك الداخلين في هذه الأبواب '),
(17932, 'Jeremiah', 24, 22, 3, ' هكذا قال الرب : أجروا حقا وعدلا ، وأنقذوا المغصوب من يد الظالم ، والغريب واليتيم والأرملة . لا تضطهدوا ولا تظلموا ، ولا تسفكوا دما زكيا في هذا الموضع '),
(17933, 'Jeremiah', 24, 22, 4, ' لأنكم إن فعلتم هذا الأمر يدخل في أبواب هذا البيت ملوك جالسون لداود على كرسيه راكبين في مركبات وعلى خيل . هو وعبيده وشعبه '),
(17934, 'Jeremiah', 24, 22, 5, ' وإن لم تسمعوا لهذه الكلمات فقد أقسمت بنفسي ، يقول الرب ، إن هذا البيت يكون خرابا '),
(17935, 'Jeremiah', 24, 22, 6, ' لأنه هكذا قال الرب عن بيت ملك يهوذا : جلعاد أنت لي . رأس من لبنان . إني أجعلك برية ، مدنا غير مسكونة '),
(17936, 'Jeremiah', 24, 22, 7, ' وأقدس عليك مهلكين ، كل واحد وآلاته ، فيقطعون خيار أرزك ويلقونه في النار '),
(17937, 'Jeremiah', 24, 22, 8, ' ويعبر أمم كثيرة في هذه المدينة ، ويقولون الواحد لصاحبه : لماذا فعل الرب مثل هذا لهذه المدينة العظيمة '),
(17938, 'Jeremiah', 24, 22, 9, ' فيقولون : من أجل أنهم تركوا عهد الرب إلههم وسجدوا لآلهة أخرى وعبدوها '),
(17939, 'Jeremiah', 24, 22, 10, ' لا تبكوا ميتا ولا تندبوه . ابكوا ، ابكوا من يمضي ، لأنه لا يرجع بعد فيرى أرض ميلاده '),
(17940, 'Jeremiah', 24, 22, 11, ' لأنه هكذا قال الرب عن شلوم بن يوشيا ملك يهوذا ، المالك عوضا عن يوشيا أبيه : الذي خرج من هذا الموضع لا يرجع إليه بعد '),
(17941, 'Jeremiah', 24, 22, 12, ' بل في الموضع الذي سبوه إليه يموت . وهذه الأرض لا يراها بعد '),
(17942, 'Jeremiah', 24, 22, 13, ' ويل لمن يبني بيته بغير عدل وعلاليه بغير حق ، الذي يستخدم صاحبه مجانا ولا يعطيه أجرته '),
(17943, 'Jeremiah', 24, 22, 14, ' القائل : أبني لنفسي بيتا وسيعا وعلالي فسيحة . ويشق لنفسه كوى ويسقف بأرز ويدهن بمغرة '),
(17944, 'Jeremiah', 24, 22, 15, ' هل تملك لأنك أنت تحاذي الأرز ؟ أما أكل أبوك وشرب وأجرى حقا وعدلا ؟ حينئذ كان له خير '),
(17945, 'Jeremiah', 24, 22, 16, ' قضى قضاء الفقير والمسكين ، حينئذ كان خير . أليس ذلك معرفتي ، يقول الرب '),
(17946, 'Jeremiah', 24, 22, 17, ' لأن عينيك وقلبك ليست إلا على خطفك ، وعلى الدم الزكي لتسفكه ، وعلى الاغتصاب والظلم لتعملهما '),
(17947, 'Jeremiah', 24, 22, 18, ' لذلك هكذا قال الرب عن يهوياقيم بن يوشيا ملك يهوذا : لا يندبونه قائلين : آه يا أخي أو آه يا أختي لا يندبونه قائلين : آه يا سيد أو آه يا جلاله '),
(17948, 'Jeremiah', 24, 22, 19, ' يدفن دفن حمار مسحوبا ومطروحا بعيدا عن أبواب أورشليم '),
(17949, 'Jeremiah', 24, 22, 20, ' اصعدي على لبنان واصرخي ، وفي باشان أطلقي صوتك ، واصرخي من عباريم ، لأنه قد سحق كل محبيك '),
(17950, 'Jeremiah', 24, 22, 21, ' تكلمت إليك في راحتك . قلت : لا أسمع . هذا طريقك منذ صباك ، أنك لا تسمعين لصوتي '),
(17951, 'Jeremiah', 24, 22, 22, ' كل رعاتك ترعاهم الريح ، ومحبوك يذهبون إلى السبي . فحينئذ تخزين وتخجلين لأجل كل شرك '),
(17952, 'Jeremiah', 24, 22, 23, ' أيتها الساكنة في لبنان المعششة في الأرز ، كم يشفق عليك عند إتيان المخاض عليك ، الوجع كوالدة '),
(17953, 'Jeremiah', 24, 22, 24, ' حي أنا ، يقول الرب ، ولو كان كنياهو بن يهوياقيم ملك يهوذا خاتما على يدي اليمنى فإني من هناك أنزعك '),
(17954, 'Jeremiah', 24, 22, 25, ' وأسلمك ليد طالبي نفسك ، وليد الذين تخاف منهم ، وليد نبوخذراصر ملك بابل ، وليد الكلدانيين '),
(17955, 'Jeremiah', 24, 22, 26, ' وأطرحك وأمك التي ولدتك إلى أرض أخرى لم تولدا فيها ، وهناك تموتان '),
(17956, 'Jeremiah', 24, 22, 27, ' أما الأرض التي يشتاقان إلى الرجوع إليها ، فلا يرجعان إليها '),
(17957, 'Jeremiah', 24, 22, 28, ' هل هذا الرجل كنياهو وعاء خزف مهان مكسور ، أو إناء ليست فيه مسرة ؟ لماذا طرح هو ونسله وألقوا إلى أرض لم يعرفوها '),
(17958, 'Jeremiah', 24, 22, 29, ' يا أرض ، يا أرض ، يا أرض اسمعي كلمة الرب '),
(17959, 'Jeremiah', 24, 22, 30, ' هكذا قال الرب : اكتبوا هذا الرجل عقيما ، رجلا لا ينجح في أيامه ، لأنه لا ينجح من نسله أحد جالسا على كرسي داود وحاكما بعد في يهوذا '),
(17960, 'Jeremiah', 24, 23, 1, ' ويل للرعاة الذين يهلكون ويبددون غنم رعيتي ، يقول الرب '),
(17961, 'Jeremiah', 24, 23, 2, ' لذلك هكذا قال الرب إله إسرائيل عن الرعاة الذين يرعون شعبي : أنتم بددتم غنمي وطردتموها ولم تتعهدوها . هأنذا أعاقبكم على شر أعمالكم ، يقول الرب '),
(17962, 'Jeremiah', 24, 23, 3, ' وأنا أجمع بقية غنمي من جميع الأراضي التي طردتها إليها ، وأردها إلى مرابضها فتثمر وتكثر '),
(17963, 'Jeremiah', 24, 23, 4, ' وأقيم عليها رعاة يرعونها فلا تخاف بعد ولا ترتعد ولا تفقد ، يقول الرب '),
(17964, 'Jeremiah', 24, 23, 5, ' ها أيام تأتي ، يقول الرب ، وأقيم لداود غصن بر ، فيملك ملك وينجح ، ويجري حقا وعدلا في الأرض '),
(17965, 'Jeremiah', 24, 23, 6, ' في أيامه يخلص يهوذا ، ويسكن إسرائيل آمنا ، وهذا هو اسمه الذي يدعونه به : الرب برنا '),
(17966, 'Jeremiah', 24, 23, 7, ' لذلك ها أيام تأتي ، يقول الرب ، ولا يقولون بعد : حي هو الرب الذي أصعد بني إسرائيل من أرض مصر '),
(17967, 'Jeremiah', 24, 23, 8, ' بل : حي هو الرب الذي أصعد وأتى بنسل بيت إسرائيل من أرض الشمال ومن جميع الأراضي التي طردتهم إليها فيسكنون في أرضهم '),
(17968, 'Jeremiah', 24, 23, 9, ' في الأنبياء : انسحق قلبي في وسطي . ارتخت كل عظامي . صرت كإنسان سكران ومثل رجل غلبته الخمر ، من أجل الرب ومن أجل كلام قدسه '),
(17969, 'Jeremiah', 24, 23, 10, ' لأن الأرض امتلأت من الفاسقين . لأنه من أجل اللعن ناحت الأرض . جفت مراعي البرية ، وصار سعيهم للشر ، وجبروتهم للباطل '),
(17970, 'Jeremiah', 24, 23, 11, ' لأن الأنبياء والكهنة تنجسوا جميعا ، بل في بيتي وجدت شرهم ، يقول الرب '),
(17971, 'Jeremiah', 24, 23, 12, ' لذلك يكون طريقهم لهم كمزالق في ظلام دامس ، فيطردون ويسقطون فيها ، لأني أجلب عليهم شرا سنة عقابهم ، يقول الرب '),
(17972, 'Jeremiah', 24, 23, 13, ' وقد رأيت في أنبياء السامرة حماقة . تنبأوا بالبعل وأضلوا شعبي إسرائيل '),
(17973, 'Jeremiah', 24, 23, 14, ' وفي أنبياء أورشليم رأيت ما يقشعر منه . يفسقون ويسلكون بالكذب ، ويشددون أيادي فاعلي الشر حتى لا يرجعوا الواحد عن شره . صاروا لي كلهم كسدوم ، وسكانها كعمورة '),
(17974, 'Jeremiah', 24, 23, 15, ' لذلك هكذا قال رب الجنود عن الأنبياء : هأنذا أطعمهم أفسنتينا وأسقيهم ماء العلقم ، لأنه من عند أنبياء أورشليم خرج نفاق في كل الأرض '),
(17975, 'Jeremiah', 24, 23, 16, ' هكذا قال رب الجنود : لا تسمعوا لكلام الأنبياء الذين يتنبأون لكم ، فإنهم يجعلونكم باطلا . يتكلمون برؤيا قلبهم لا عن فم الرب '),
(17976, 'Jeremiah', 24, 23, 17, ' قائلين قولا لمحتقري : قال الرب : يكون لكم سلام ويقولون لكل من يسير في عناد قلبه : لا يأتي عليكم شر '),
(17977, 'Jeremiah', 24, 23, 18, ' لأنه من وقف في مجلس الرب ورأى وسمع كلمته ؟ من أصغى لكلمته وسمع '),
(17978, 'Jeremiah', 24, 23, 19, ' ها زوبعة الرب . غيظ يخرج ، ونوء هائج . على رؤوس الأشرار يثور '),
(17979, 'Jeremiah', 24, 23, 20, ' لا يرتد غضب الرب حتى يجري ويقيم مقاصد قلبه . في آخر الأيام تفهمون فهما '),
(17980, 'Jeremiah', 24, 23, 21, ' لم أرسل الأنبياء بل هم جروا . لم أتكلم معهم بل هم تنبأوا '),
(17981, 'Jeremiah', 24, 23, 22, ' ولو وقفوا في مجلسي لأخبروا شعبي بكلامي وردوهم عن طريقهم الرديء وعن شر أعمالهم '),
(17982, 'Jeremiah', 24, 23, 23, ' ألعلي إله من قريب ، يقول الرب ، ولست إلها من بعيد '),
(17983, 'Jeremiah', 24, 23, 24, ' إذا اختبأ إنسان في أماكن مستترة أفما أراه أنا ، يقول الرب ؟ أما أملأ أنا السماوات والأرض ، يقول الرب '),
(17984, 'Jeremiah', 24, 23, 25, ' قد سمعت ما قاله الأنبياء الذين تنبأوا باسمي بالكذب قائلين : حلمت ، حلمت '),
(17985, 'Jeremiah', 24, 23, 26, ' حتى متى يوجد في قلب الأنبياء المتنبئين بالكذب ؟ بل هم أنبياء خداع قلبهم '),
(17986, 'Jeremiah', 24, 23, 27, ' الذين يفكرون أن ينسوا شعبي اسمي بأحلامهم التي يقصونها الرجل على صاحبه ، كما نسي آباؤهم اسمي لأجل البعل '),
(17987, 'Jeremiah', 24, 23, 28, ' النبي الذي معه حلم فليقص حلما ، والذي معه كلمتي فليتكلم بكلمتي بالحق . ما للتبن مع الحنطة ، يقول الرب '),
(17988, 'Jeremiah', 24, 23, 29, ' أليست هكذا كلمتي كنار ، يقول الرب ، وكمطرقة تحطم الصخر '),
(17989, 'Jeremiah', 24, 23, 30, ' لذلك هأنذا على الأنبياء ، يقول الرب ، الذين يسرقون كلمتي بعضهم من بعض '),
(17990, 'Jeremiah', 24, 23, 31, ' هأنذا على الأنبياء ، يقول الرب ، الذين يأخذون لسانهم ويقولون : قال '),
(17991, 'Jeremiah', 24, 23, 32, ' هأنذا على الذين يتنبأون بأحلام كاذبة ، يقول الرب ، الذين يقصونها ويضلون شعبي بأكاذيبهم ومفاخراتهم وأنا لم أرسلهم ولا أمرتهم . فلم يفيدوا هذا الشعب فائدة ، يقول الرب '),
(17992, 'Jeremiah', 24, 23, 33, ' وإذا سألك هذا الشعب أو نبي أو كاهن قائلا : ما وحي الرب ؟ فقل لهم : أي وحي ؟ إني أرفضكم ، هو قول الرب '),
(17993, 'Jeremiah', 24, 23, 34, ' فالنبي أو الكاهن أو الشعب الذي يقول : وحي الرب ، أعاقب ذلك الرجل وبيته '),
(17994, 'Jeremiah', 24, 23, 35, ' هكذا تقولون الرجل لصاحبه والرجل لأخيه : بماذا أجاب الرب ؟ وماذا تكلم به الرب '),
(17995, 'Jeremiah', 24, 23, 36, ' أما وحي الرب فلا تذكروه بعد ، لأن كلمة كل إنسان تكون وحيه ، إذ قد حرفتم كلام الإله الحي رب الجنود إلهنا '),
(17996, 'Jeremiah', 24, 23, 37, ' هكذا تقول للنبي : بماذا أجابك الرب ؟ وماذا تكلم به الرب '),
(17997, 'Jeremiah', 24, 23, 38, ' وإذا كنتم تقولون : وحي الرب ، فلذلك هكذا قال الرب : من أجل قولكم هذه الكلمة : وحي الرب ، وقد أرسلت إليكم قائلا لا تقولوا : وحي الرب '),
(17998, 'Jeremiah', 24, 23, 39, ' لذلك هأنذا أنساكم نسيانا ، وأرفضكم من أمام وجهي ، أنتم والمدينة التي أعطيتكم وآباءكم إياها '),
(17999, 'Jeremiah', 24, 23, 40, ' وأجعل عليكم عارا أبديا وخزيا أبديا لا ينسى '),
(18000, 'Jeremiah', 24, 24, 1, ' أراني الرب وإذا سلتا تين موضوعتان أمام هيكل الرب بعد ما سبى نبوخذراصر ملك بابل يكنيا بن يهوياقيم ملك يهوذا ورؤساء يهوذا والنجارين والحدادين من أورشليم ، وأتى بهم إلى بابل '),
(18001, 'Jeremiah', 24, 24, 2, ' في السلة الواحدة تين جيد جدا مثل التين الباكوري ، وفي السلة الأخرى تين رديء جدا لا يؤكل من رداءته '),
(18002, 'Jeremiah', 24, 24, 3, ' فقال لي الرب : ماذا أنت راء يا إرميا ؟  . فقلت : تينا . التين الجيد جيد جدا ، والتين الرديء رديء جدا لا يؤكل من رداءته '),
(18003, 'Jeremiah', 24, 24, 4, ' ثم صار كلام الرب إلي قائلا '),
(18004, 'Jeremiah', 24, 24, 5, ' هكذا قال الرب إله إسرائيل : كهذا التين الجيد هكذا أنظر إلى سبي يهوذا الذي أرسلته من هذا الموضع إلى أرض الكلدانيين للخير '),
(18005, 'Jeremiah', 24, 24, 6, ' وأجعل عيني عليهم للخير ، وأرجعهم إلى هذه الأرض ، وأبنيهم ولا أهدمهم ، وأغرسهم ولا أقلعهم '),
(18006, 'Jeremiah', 24, 24, 7, ' وأعطيهم قلبا ليعرفوني أني أنا الرب ، فيكونوا لي شعبا وأنا أكون لهم إلها ، لأنهم يرجعون إلي بكل قلبهم '),
(18007, 'Jeremiah', 24, 24, 8, ' وكالتين الرديء الذي لا يؤكل من رداءته ، هكذا قال الرب ، هكذا أجعل صدقيا ملك يهوذا ورؤساءه وبقية أورشليم الباقية في هذه الأرض والساكنة في أرض مصر '),
(18008, 'Jeremiah', 24, 24, 9, ' وأسلمهم للقلق والشر في جميع ممالك الأرض عارا ومثلا وهزأة ولعنة في جميع المواضع التي أطردهم إليها '),
(18009, 'Jeremiah', 24, 24, 10, ' وأرسل عليهم السيف والجوع والوبأ حتى يفنوا عن وجه الأرض التي أعطيتهم وآباءهم إياها '),
(18010, 'Jeremiah', 24, 25, 1, ' الكلام الذي صار إلى إرميا عن كل شعب يهوذا ، في السنة الرابعة ليهوياقيم بن يوشيا ملك يهوذا ، هي السنة الأولى لنبوخذراصر ملك بابل '),
(18011, 'Jeremiah', 24, 25, 2, ' الذي تكلم به إرميا النبي على كل شعب يهوذا وعلى كل سكان أورشليم قائلا '),
(18012, 'Jeremiah', 24, 25, 3, ' من السنة الثالثة عشرة ليوشيا بن آمون ملك يهوذا إلى هذا اليوم ، هذه الثلاث والعشرين سنة ، صارت كلمة الرب إلي فكلمتكم مبكرا ومكلما فلم تسمعوا '),
(18013, 'Jeremiah', 24, 25, 4, ' وقد أرسل الرب إليكم كل عبيده الأنبياء مبكرا ومرسلا فلم تسمعوا ولم تميلوا أذنكم للسمع '),
(18014, 'Jeremiah', 24, 25, 5, ' قائلين : ارجعوا كل واحد عن طريقه الرديء وعن شر أعمالكم واسكنوا في الأرض التي أعطاكم الرب إياها وآباءكم من الأزل وإلى الأبد '),
(18015, 'Jeremiah', 24, 25, 6, ' ولا تسلكوا وراء آلهة أخرى لتعبدوها وتسجدوا لها ، ولا تغيظوني بعمل أيديكم فلا أسيء إليكم '),
(18016, 'Jeremiah', 24, 25, 7, ' فلم تسمعوا لي ، يقول الرب ، لتغيظوني بعمل أيديكم شرا لكم '),
(18017, 'Jeremiah', 24, 25, 8, ' لذلك هكذا قال رب الجنود : من أجل أنكم لم تسمعوا لكلامي '),
(18018, 'Jeremiah', 24, 25, 9, ' هأنذا أرسل فآخذ كل عشائر الشمال ، يقول الرب ، وإلى نبوخذراصر عبدي ملك بابل ، وآتي بهم على هذه الأرض وعلى كل سكانها وعلى كل هذه الشعوب حواليها ، فأحرمهم وأجعلهم دهشا وصفيرا وخربا أبدية '),
(18019, 'Jeremiah', 24, 25, 10, ' وأبيد منهم صوت الطرب وصوت الفرح ، صوت العريس وصوت العروس ، صوت الأرحية ونور السراج '),
(18020, 'Jeremiah', 24, 25, 11, ' وتصير كل هذه الأرض خرابا ودهشا ، وتخدم هذه الشعوب ملك بابل سبعين سنة '),
(18021, 'Jeremiah', 24, 25, 12, ' ويكون عند تمام السبعين سنة أني أعاقب ملك بابل ، وتلك الأمة ، يقول الرب ، على إثمهم وأرض الكلدانيين ، وأجعلها خربا أبدية '),
(18022, 'Jeremiah', 24, 25, 13, ' وأجلب على تلك الأرض كل كلامي الذي تكلمت به عليها ، كل ما كتب في هذا السفر الذي تنبأ به إرميا على كل الشعوب '),
(18023, 'Jeremiah', 24, 25, 14, ' لأنه قد استعبدهم أيضا أمم كثيرة وملوك عظام ، فأجازيهم حسب أعمالهم وحسب عمل أياديهم '),
(18024, 'Jeremiah', 24, 25, 15, ' لأنه هكذا قال لي الرب إله إسرائيل : خذ كأس خمر هذا السخط من يدي ، واسق جميع الشعوب الذين أرسلك أنا إليهم إياها '),
(18025, 'Jeremiah', 24, 25, 16, ' فيشربوا ويترنحوا ويتجننوا من أجل السيف الذي أرسله أنا بينهم '),
(18026, 'Jeremiah', 24, 25, 17, ' فأخذت الكأس من يد الرب وسقيت كل الشعوب الذين أرسلني الرب إليهم '),
(18027, 'Jeremiah', 24, 25, 18, ' أورشليم ومدن يهوذا وملوكها ورؤساءها ، لجعلها خرابا ودهشا وصفيرا ولعنة كهذا اليوم '),
(18028, 'Jeremiah', 24, 25, 19, ' وفرعون ملك مصر وعبيده ورؤساءه وكل شعبه '),
(18029, 'Jeremiah', 24, 25, 20, ' وكل اللفيف ، وكل ملوك أرض عوص ، وكل ملوك أرض فلسطين وأشقلون وغزة وعقرون وبقية أشدود '),
(18030, 'Jeremiah', 24, 25, 21, ' وأدوم وموآب وبني عمون '),
(18031, 'Jeremiah', 24, 25, 22, ' وكل ملوك صور ، وكل ملوك صيدون ، وملوك الجزائر التي في عبر البحر '),
(18032, 'Jeremiah', 24, 25, 23, ' وددان وتيماء وبوز ، وكل مقصوصي الشعر مستديرا '),
(18033, 'Jeremiah', 24, 25, 24, ' وكل ملوك العرب ، وكل ملوك اللفيف الساكنين في البرية '),
(18034, 'Jeremiah', 24, 25, 25, ' وكل ملوك زمري ، وكل ملوك عيلام ، وكل ملوك مادي '),
(18035, 'Jeremiah', 24, 25, 26, ' وكل ملوك الشمال القريبين والبعيدين ، كل واحد مع أخيه ، وكل ممالك الأرض التي على وجه الأرض . وملك شيشك يشرب بعدهم '),
(18036, 'Jeremiah', 24, 25, 27, ' وتقول لهم : هكذا قال رب الجنود إله إسرائيل : اشربوا واسكروا وتقيأوا واسقطوا ولا تقوموا من أجل السيف الذي أرسله أنا بينكم '),
(18037, 'Jeremiah', 24, 25, 28, ' ويكون إذا أبوا أن يأخذوا الكأس من يدك ليشربوا ، أنك تقول لهم : هكذا قال رب الجنود : تشربون شربا '),
(18038, 'Jeremiah', 24, 25, 29, ' لأني هأنذا أبتدئ أسيء إلى المدينة التي دعي اسمي عليها ، فهل تتبرأون أنتم ؟ لا تتبرأون ، لأني أنا أدعو السيف على كل سكان الأرض ، يقول رب الجنود '),
(18039, 'Jeremiah', 24, 25, 30, ' وأنت فتنبأ عليهم بكل هذا الكلام ، وقل لهم : الرب من العلاء يزمجر ، ومن مسكن قدسه يطلق صوته ، يزأر زئيرا على مسكنه ، بهتاف كالدائسين يصرخ ضد كل سكان الأرض '),
(18040, 'Jeremiah', 24, 25, 31, ' بلغ الضجيج إلى أطراف الأرض ، لأن للرب خصومة مع الشعوب . هو يحاكم كل ذي جسد . يدفع الأشرار للسيف ، يقول الرب '),
(18041, 'Jeremiah', 24, 25, 32, ' هكذا قال رب الجنود : هوذا الشر يخرج من أمة إلى أمة ، وينهض نوء عظيم من أطراف الأرض '),
(18042, 'Jeremiah', 24, 25, 33, ' وتكون قتلى الرب في ذلك اليوم من أقصاء الأرض إلى أقصاء الأرض . لا يندبون ولا يضمون ولا يدفنون . يكونون دمنة على وجه الأرض '),
(18043, 'Jeremiah', 24, 25, 34, ' ولولوا أيها الرعاة واصرخوا ، وتمرغوا يا رؤساء الغنم ، لأن أيامكم قد كملت للذبح . وأبددكم فتسقطون كإناء شهي '),
(18044, 'Jeremiah', 24, 25, 35, ' ويبيد المناص عن الرعاة ، والنجاة عن رؤساء الغنم '),
(18045, 'Jeremiah', 24, 25, 36, ' صوت صراخ الرعاة ، وولولة رؤساء الغنم . لأن الرب قد أهلك مرعاهم '),
(18046, 'Jeremiah', 24, 25, 37, ' وبادت مراعي السلام من أجل حمو غضب الرب '),
(18047, 'Jeremiah', 24, 25, 38, ' ترك كشبل عيصه ، لأن أرضهم صارت خرابا من أجل الظالم ومن أجل حمو غضبه '),
(18048, 'Jeremiah', 24, 26, 1, ' في ابتداء ملك يهوياقيم بن يوشيا ملك يهوذا ، صار هذا الكلام من قبل الرب قائلا '),
(18049, 'Jeremiah', 24, 26, 2, ' هكذا قال الرب : قف في دار بيت الرب ، وتكلم على كل مدن يهوذا القادمة للسجود في بيت الرب بكل الكلام الذي أوصيتك أن تتكلم به إليهم . لا تنقص كلمة '),
(18050, 'Jeremiah', 24, 26, 3, ' لعلهم يسمعون ويرجعون كل واحد عن طريقه الشرير ، فأندم عن الشر الذي قصدت أن أصنعه بهم ، من أجل شر أعمالهم '),
(18051, 'Jeremiah', 24, 26, 4, ' وتقول لهم هكذا قال الرب : إن لم تسمعوا لي لتسلكوا في شريعتي التي جعلتها أمامكم '),
(18052, 'Jeremiah', 24, 26, 5, ' لتسمعوا لكلام عبيدي الأنبياء الذين أرسلتهم أنا إليكم مبكرا ومرسلا إياهم ، فلم تسمعوا '),
(18053, 'Jeremiah', 24, 26, 6, ' أجعل هذا البيت كشيلوه ، وهذه المدينة أجعلها لعنة لكل شعوب الأرض '),
(18054, 'Jeremiah', 24, 26, 7, ' وسمع الكهنة والأنبياء وكل الشعب إرميا يتكلم بهذا الكلام في بيت الرب '),
(18055, 'Jeremiah', 24, 26, 8, ' وكان لما فرغ إرميا من التكلم بكل ما أوصاه الرب أن يكلم كل الشعب به ، أن الكهنة والأنبياء وكل الشعب أمسكوه قائلين : تموت موتا '),
(18056, 'Jeremiah', 24, 26, 9, ' لماذا تنبأت باسم الرب قائلا : مثل شيلوه يكون هذا البيت ، وهذه المدينة تكون خربة بلا ساكن ؟  . واجتمع كل الشعب على إرميا في بيت الرب '),
(18057, 'Jeremiah', 24, 26, 10, ' فلما سمع رؤساء يهوذا بهذه الأمور ، صعدوا من بيت الملك إلى بيت الرب وجلسوا في مدخل باب الرب الجديد '),
(18058, 'Jeremiah', 24, 26, 11, ' فتكلم الكهنة والأنبياء مع الرؤساء وكل الشعب قائلين : حق الموت على هذا الرجل لأنه قد تنبأ على هذه المدينة كما سمعتم بآذانكم '),
(18059, 'Jeremiah', 24, 26, 12, ' فكلم إرميا كل الرؤساء وكل الشعب قائلا : الرب أرسلني لأتنبأ على هذا البيت وعلى هذه المدينة بكل الكلام الذي سمعتموه '),
(18060, 'Jeremiah', 24, 26, 13, ' فالآن أصلحوا طرقكم وأعمالكم ، واسمعوا لصوت الرب إلهكم ، فيندم الرب عن الشر الذي تكلم به عليكم '),
(18061, 'Jeremiah', 24, 26, 14, ' أما أنا فهأنذا بيدكم . اصنعوا بي كما هو حسن ومستقيم في أعينكم '),
(18062, 'Jeremiah', 24, 26, 15, ' لكن اعلموا علما أنكم إن قتلتموني ، تجعلون دما زكيا على أنفسكم وعلى هذه المدينة وعلى سكانها ، لأنه حقا قد أرسلني الرب إليكم لأتكلم في آذانكم بكل هذا الكلام '),
(18063, 'Jeremiah', 24, 26, 16, ' فقال الرؤساء وكل الشعب للكهنة والأنبياء : ليس على هذا الرجل حق الموت ، لأنه إنما كلمنا باسم الرب إلهنا '),
(18064, 'Jeremiah', 24, 26, 17, ' فقام أناس من شيوخ الأرض وكلموا كل جماعة الشعب قائلين '),
(18065, 'Jeremiah', 24, 26, 18, ' إن ميخا المورشتي تنبأ في أيام حزقيا ملك يهوذا ، وكلم كل شعب يهوذا قائلا : هكذا قال رب الجنود : إن صهيون تفلح كحقل وتصير أورشليم خربا وجبل البيت شوامخ وعر '),
(18066, 'Jeremiah', 24, 26, 19, ' هل قتلا قتله حزقيا ملك يهوذا وكل يهوذا ؟ ألم يخف الرب وطلب وجه الرب ، فندم الرب عن الشر الذي تكلم به عليهم ؟ فنحن عاملون شرا عظيما ضد أنفسنا '),
(18067, 'Jeremiah', 24, 26, 20, ' وقد كان رجل أيضا يتنبأ باسم الرب ، أوريا بن شمعيا من قرية يعاريم ، فتنبأ على هذه المدينة وعلى هذه الأرض بكل كلام إرميا '),
(18068, 'Jeremiah', 24, 26, 21, ' ولما سمع الملك يهوياقيم وكل أبطاله وكل الرؤساء كلامه ، طلب الملك أن يقتله . فلما سمع أوريا خاف وهرب وأتى إلى مصر '),
(18069, 'Jeremiah', 24, 26, 22, ' فأرسل الملك يهوياقيم أناسا إلى مصر ، ألناثان بن عكبور ورجالا معه إلى مصر '),
(18070, 'Jeremiah', 24, 26, 23, ' فأخرجوا أوريا من مصر وأتوا به إلى الملك يهوياقيم ، فضربه بالسيف وطرح جثته في قبور بني الشعب '),
(18071, 'Jeremiah', 24, 26, 24, ' ولكن يد أخيقام بن شافان كانت مع إرميا حتى لا يدفع ليد الشعب ليقتلوه '),
(18072, 'Jeremiah', 24, 27, 1, ' في ابتداء ملك يهوياقيم بن يوشيا ملك يهوذا ، صار هذا الكلام إلى إرميا من قبل الرب قائلا '),
(18073, 'Jeremiah', 24, 27, 2, ' هكذا قال الرب لي : اصنع لنفسك ربطا وأنيارا ، واجعلها على عنقك '),
(18074, 'Jeremiah', 24, 27, 3, ' وأرسلها إلى ملك أدوم ، وإلى ملك موآب ، وإلى ملك بني عمون ، وإلى ملك صور ، وإلى ملك صيدون ، بيد الرسل القادمين إلى أورشليم ، إلى صدقيا ملك يهوذا '),
(18075, 'Jeremiah', 24, 27, 4, ' وأوصهم إلى سادتهم قائلا : هكذا قال رب الجنود إله إسرائيل : هكذا تقولون لسادتكم '),
(18076, 'Jeremiah', 24, 27, 5, ' إني أنا صنعت الأرض والإنسان والحيوان الذي على وجه الأرض ، بقوتي العظيمة وبذراعي الممدودة ، وأعطيتها لمن حسن في عيني '),
(18077, 'Jeremiah', 24, 27, 6, ' والآن قد دفعت كل هذه الأراضي ليد نبوخذناصر ملك بابل عبدي ، وأعطيته أيضا حيوان الحقل ليخدمه '),
(18078, 'Jeremiah', 24, 27, 7, ' فتخدمه كل الشعوب ، وابنه وابن ابنه ، حتى يأتي وقت أرضه أيضا ، فتستخدمه شعوب كثيرة وملوك عظام '),
(18079, 'Jeremiah', 24, 27, 8, ' ويكون أن الأمة أو المملكة التي لا تخدم نبوخذناصر ملك بابل ، والتي لا تجعل عنقها تحت نير ملك بابل ، إني أعاقب تلك الأمة بالسيف والجوع والوبإ ، يقول الرب ، حتى أفنيها بيده '),
(18080, 'Jeremiah', 24, 27, 9, ' فلا تسمعوا أنتم لأنبيائكم وعرافيكم وحالميكم وعائفيكم وسحرتكم الذين يكلمونكم قائلين : لا تخدموا ملك بابل '),
(18081, 'Jeremiah', 24, 27, 10, ' لأنهم إنما يتنبأون لكم بالكذب ، لكي يبعدوكم من أرضكم ، ولأطردكم فتهلكوا '),
(18082, 'Jeremiah', 24, 27, 11, ' والأمة التي تدخل عنقها تحت نير ملك بابل وتخدمه ، أجعلها تستقر في أرضها ، يقول الرب ، وتعملها وتسكن بها '),
(18083, 'Jeremiah', 24, 27, 12, ' وكلمت صدقيا ملك يهوذا بكل هذا الكلام ، قائلا : أدخلوا أعناقكم تحت نير ملك بابل واخدموه وشعبه واحيوا '),
(18084, 'Jeremiah', 24, 27, 13, ' لماذا تموتون أنت وشعبك بالسيف بالجوع والوبإ ، كما تكلم الرب عن الأمة التي لا تخدم ملك بابل '),
(18085, 'Jeremiah', 24, 27, 14, ' فلا تسمعوا لكلام الأنبياء الذين يكلمونكم قائلين : لا تخدموا ملك بابل ، لأنهم إنما يتنبأون لكم بالكذب '),
(18086, 'Jeremiah', 24, 27, 15, ' لأني لم أرسلهم ، يقول الرب ، بل هم يتنبأون باسمي بالكذب ، لكي أطردكم فتهلكوا أنتم والأنبياء الذين يتنبأون لكم '),
(18087, 'Jeremiah', 24, 27, 16, ' وكلمت الكهنة وكل هذا الشعب قائلا : هكذا قال الرب : لا تسمعوا لكلام أنبيائكم الذين يتنبأون لكم قائلين : ها آنية بيت الرب سترد سريعا من بابل . لأنهم إنما يتنبأون لكم بالكذب '),
(18088, 'Jeremiah', 24, 27, 17, ' لا تسمعوا لهم . اخدموا ملك بابل واحيوا . لماذا تصير هذه المدينة خربة '),
(18089, 'Jeremiah', 24, 27, 18, ' فإن كانوا أنبياء ، وإن كانت كلمة الرب معهم ، فليتوسلوا إلى رب الجنود لكي لا تذهب إلى بابل الآنية الباقية في بيت الرب وبيت ملك يهوذا وفي أورشليم '),
(18090, 'Jeremiah', 24, 27, 19, ' لأنه هكذا قال رب الجنود عن الأعمدة وعن البحر وعن القواعد وعن سائر الآنية الباقية في هذه المدينة '),
(18091, 'Jeremiah', 24, 27, 20, ' التي لم يأخذها نبوخذناصر ملك بابل عند سبيه يكنيا بن يهوياقيم ملك يهوذا من أورشليم إلى بابل وكل أشراف يهوذا وأورشليم '),
(18092, 'Jeremiah', 24, 27, 21, ' إنه هكذا قال رب الجنود إله إسرائيل عن الآنية الباقية في بيت الرب وبيت ملك يهوذا وفي أورشليم '),
(18093, 'Jeremiah', 24, 27, 22, ' يؤتى بها إلى بابل ، وتكون هناك إلى يوم افتقادي إياها ، يقول الرب ، فأصعدها وأردها إلى هذا الموضع '),
(18094, 'Jeremiah', 24, 28, 1, ' وحدث في تلك السنة في ابتداء ملك صدقيا ملك يهوذا ، في السنة الرابعة ، في الشهر الخامس ، أن حننيا بن عزور النبي الذي من جبعون كلمني في بيت الرب أمام الكهنة وكل الشعب قائلا '),
(18095, 'Jeremiah', 24, 28, 2, ' هكذا تكلم رب الجنود إله إسرائيل قائلا : قد كسرت نير ملك بابل '),
(18096, 'Jeremiah', 24, 28, 3, ' في سنتين من الزمان أرد إلى هذا الموضع كل آنية بيت الرب التي أخذها نبوخذناصر ملك بابل من هذا الموضع ، وذهب بها إلى بابل '),
(18097, 'Jeremiah', 24, 28, 4, ' وأرد إلى هذا الموضع يكنيا بن يهوياقيم ملك يهوذا وكل سبي يهوذا الذين ذهبوا إلى بابل ، يقول الرب ، لأني أكسر نير ملك بابل '),
(18098, 'Jeremiah', 24, 28, 5, ' فكلم إرميا النبي حننيا النبي أمام الكهنة وأمام كل الشعب الواقفين في بيت الرب '),
(18099, 'Jeremiah', 24, 28, 6, ' وقال إرميا النبي : آمين . هكذا ليصنع الرب . ليقم الرب كلامك الذي تنبأت به ، فيرد آنية بيت الرب وكل السبي من بابل إلى هذا الموضع '),
(18100, 'Jeremiah', 24, 28, 7, ' ولكن اسمع هذه الكلمة التي أتكلم أنا بها في أذنيك وفي آذان كل الشعب '),
(18101, 'Jeremiah', 24, 28, 8, ' إن الأنبياء الذين كانوا قبلي وقبلك منذ القديم وتنبأوا على أراض كثيرة وعلى ممالك عظيمة بالحرب والشر والوبإ '),
(18102, 'Jeremiah', 24, 28, 9, ' النبي الذي تنبأ بالسلام ، فعند حصول كلمة النبي عرف ذلك النبي أن الرب قد أرسله حقا '),
(18103, 'Jeremiah', 24, 28, 10, ' ثم أخذ حننيا النبي النير عن عنق إرميا النبي وكسره ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(18104, 'Jeremiah', 24, 28, 11, ' وتكلم حننيا أمام كل الشعب قائلا : هكذا قال الرب : هكذا أكسر نير نبوخذناصر ملك بابل في سنتين من الزمان عن عنق كل الشعوب . وانطلق إرميا النبي في سبيله '),
(18105, 'Jeremiah', 24, 28, 12, ' ثم صار كلام الرب إلى إرميا النبي ، بعدما كسر حننيا النبي النير عن عنق إرميا النبي ، قائلا '),
(18106, 'Jeremiah', 24, 28, 13, ' اذهب وكلم حننيا قائلا : هكذا قال الرب : قد كسرت أنيار الخشب وعملت عوضا عنها أنيارا من حديد '),
(18107, 'Jeremiah', 24, 28, 14, ' لأنه هكذا قال رب الجنود إله إسرائيل : قد جعلت نيرا من حديد على عنق كل هؤلاء الشعوب ليخدموا نبوخذناصر ملك بابل ، فيخدمونه وقد أعطيته أيضا حيوان الحقل '),
(18108, 'Jeremiah', 24, 28, 15, ' فقال إرميا النبي لحننيا النبي : اسمع يا حننيا . إن الرب لم يرسلك ، وأنت قد جعلت هذا الشعب يتكل على الكذب '),
(18109, 'Jeremiah', 24, 28, 16, ' لذلك هكذا قال الرب : هأنذا طاردك عن وجه الأرض . هذه السنة تموت ، لأنك تكلمت بعصيان على الرب '),
(18110, 'Jeremiah', 24, 28, 17, ' فمات حننيا النبي في تلك السنة في الشهر السابع '),
(18111, 'Jeremiah', 24, 29, 1, ' هذا كلام الرسالة التي أرسلها إرميا النبي من أورشليم إلى بقية شيوخ السبي ، وإلى الكهنة والأنبياء ، وإلى كل الشعب الذين سباهم نبوخذناصر من أورشليم إلى بابل '),
(18112, 'Jeremiah', 24, 29, 2, ' بعد خروج يكنيا الملك والملكة والخصيان ورؤساء يهوذا وأورشليم والنجارين والحدادين من أورشليم '),
(18113, 'Jeremiah', 24, 29, 3, ' بيد ألعاسة بن شافان ، وجمريا بن حلقيا ، اللذين أرسلهما صدقيا ملك يهوذا إلى نبوخذناصر ملك بابل إلى بابل قائلا '),
(18114, 'Jeremiah', 24, 29, 4, ' هكذا قال رب الجنود إله إسرائيل لكل السبي الذي سبيته من أورشليم إلى بابل '),
(18115, 'Jeremiah', 24, 29, 5, ' ابنوا بيوتا واسكنوا ، واغرسوا جنات وكلوا ثمرها '),
(18116, 'Jeremiah', 24, 29, 6, ' خذوا نساء ولدوا بنين وبنات وخذوا لبنيكم نساء وأعطوا بناتكم لرجال فيلدن بنين وبنات ، واكثروا هناك ولا تقلوا '),
(18117, 'Jeremiah', 24, 29, 7, ' واطلبوا سلام المدينة التي سبيتكم إليها ، وصلوا لأجلها إلى الرب ، لأنه بسلامها يكون لكم سلام '),
(18118, 'Jeremiah', 24, 29, 8, ' لأنه هكذا قال رب الجنود إله إسرائيل : لا تغشكم أنبياؤكم الذين في وسطكم وعرافوكم ، ولا تسمعوا لأحلامكم التي تتحلمونها '),
(18119, 'Jeremiah', 24, 29, 9, ' لأنهم إنما يتنبأون لكم باسمي بالكذب . أنا لم أرسلهم ، يقول الرب '),
(18120, 'Jeremiah', 24, 29, 10, ' لأنه هكذا قال الرب : إني عند تمام سبعين سنة لبابل ، أتعهدكم وأقيم لكم كلامي الصالح ، بردكم إلى هذا الموضع '),
(18121, 'Jeremiah', 24, 29, 11, ' لأني عرفت الأفكار التي أنا مفتكر بها عنكم ، يقول الرب ، أفكار سلام لا شر ، لأعطيكم آخرة ورجاء '),
(18122, 'Jeremiah', 24, 29, 12, ' فتدعونني وتذهبون وتصلون إلي فأسمع لكم '),
(18123, 'Jeremiah', 24, 29, 13, ' وتطلبونني فتجدونني إذ تطلبونني بكل قلبكم '),
(18124, 'Jeremiah', 24, 29, 14, ' فأوجد لكم ، يقول الرب ، وأرد سبيكم وأجمعكم من كل الأمم ومن كل المواضع التي طردتكم إليها ، يقول الرب ، وأردكم إلى الموضع الذي سبيتكم منه '),
(18125, 'Jeremiah', 24, 29, 15, ' لأنكم قلتم : قد أقام لنا الرب نبيين في بابل '),
(18126, 'Jeremiah', 24, 29, 16, ' فهكذا قال الرب للملك الجالس على كرسي داود ، ولكل الشعب الجالس في هذه المدينة ، إخوتكم الذين لم يخرجوا معكم في السبي '),
(18127, 'Jeremiah', 24, 29, 17, ' هكذا قال رب الجنود : هأنذا أرسل عليهم السيف والجوع والوبأ ، وأجعلهم كتين رديء لا يؤكل من الرداءة '),
(18128, 'Jeremiah', 24, 29, 18, ' وألحقهم بالسيف والجوع والوبإ ، وأجعلهم قلقا لكل ممالك الأرض ، حلفا ودهشا وصفيرا وعارا في جميع الأمم الذين طردتهم إليهم '),
(18129, 'Jeremiah', 24, 29, 19, ' من أجل أنهم لم يسمعوا لكلامي ، يقول الرب ، إذ أرسلت إليهم عبيدي الأنبياء مبكرا ومرسلا ولم تسمعوا ، يقول الرب '),
(18130, 'Jeremiah', 24, 29, 20, ' وأنتم فاسمعوا كلمة الرب يا جميع السبي الذين أرسلتهم من أورشليم إلى بابل '),
(18131, 'Jeremiah', 24, 29, 21, ' هكذا قال رب الجنود إله إسرائيل عن أخآب بن قولايا ، وعن صدقيا بن معسيا ، اللذين يتنبآن لكم باسمي بالكذب : هأنذا أدفعهما ليد نبوخذراصر ملك بابل فيقتلهما أمام عيونكم '),
(18132, 'Jeremiah', 24, 29, 22, ' وتؤخذ منهما لعنة لكل سبي يهوذا الذين في بابل ، فيقال : يجعلك الرب مثل صدقيا ومثل أخآب اللذين قلاهما ملك بابل بالنار '),
(18133, 'Jeremiah', 24, 29, 23, ' من أجل أنهما عملا قبيحا في إسرائيل ، وزنيا بنساء أصحابهما ، وتكلما باسمي كلاما كاذبا لم أوصهما به ، وأنا العارف والشاهد ، يقول الرب '),
(18134, 'Jeremiah', 24, 29, 24, ' وكلم شمعيا النحلامي قائلا '),
(18135, 'Jeremiah', 24, 29, 25, ' هكذا تكلم رب الجنود إله إسرائيل قائلا : من أجل أنك أرسلت رسائل باسمك إلى كل الشعب الذي في أورشليم ، وإلى صفنيا بن معسيا الكاهن ، وإلى كل الكهنة قائلا '),
(18136, 'Jeremiah', 24, 29, 26, ' قد جعلك الرب كاهنا عوضا عن يهوياداع الكاهن ، لتكونوا وكلاء في بيت الرب لكل رجل مجنون ومتنبئ ، فتدفعه إلى المقطرة والقيود '),
(18137, 'Jeremiah', 24, 29, 27, ' والآن لماذا لم تزجر إرميا العناثوثي المتنبئ لكم '),
(18138, 'Jeremiah', 24, 29, 28, ' لأنه لذلك أرسل إلينا إلى بابل قائلا : إنها مستطيلة . ابنوا بيوتا واسكنوا ، واغرسوا جنات وكلوا ثمرها '),
(18139, 'Jeremiah', 24, 29, 29, ' فقرأ صفنيا الكاهن هذه الرسالة في أذني إرميا النبي '),
(18140, 'Jeremiah', 24, 29, 30, ' ثم صار كلام الرب إلى إرميا قائلا '),
(18141, 'Jeremiah', 24, 29, 31, ' أرسل إلى كل السبي قائلا : هكذا قال الرب لشمعيا النحلامي : من أجل أن شمعيا قد تنبأ لكم وأنا لم أرسله ، وجعلكم تتكلون على الكذب '),
(18142, 'Jeremiah', 24, 29, 32, ' لذلك هكذا قال الرب : هأنذا أعاقب شمعيا النحلامي ونسله . لا يكون له إنسان يجلس في وسط هذا الشعب ، ولا يرى الخير الذي سأصنعه لشعبي ، يقول الرب ، لأنه تكلم بعصيان على الرب '),
(18143, 'Jeremiah', 24, 30, 1, ' الكلام الذي صار إلى إرميا من قبل الرب قائلا '),
(18144, 'Jeremiah', 24, 30, 2, ' هكذا تكلم الرب إله إسرائيل قائلا : اكتب كل الكلام الذي تكلمت به إليك في سفر '),
(18145, 'Jeremiah', 24, 30, 3, ' لأنه ها أيام تأتي ، يقول الرب ، وأرد سبي شعبي إسرائيل ويهوذا ، يقول الرب ، وأرجعهم إلى الأرض التي أعطيت آباءهم إياها فيمتلكونها '),
(18146, 'Jeremiah', 24, 30, 4, ' فهذا هو الكلام الذي تكلم به الرب عن إسرائيل وعن يهوذا '),
(18147, 'Jeremiah', 24, 30, 5, ' لأنه هكذا قال الرب : صوت ارتعاد سمعنا . خوف ولا سلام '),
(18148, 'Jeremiah', 24, 30, 6, ' اسألوا وانظروا إن كان ذكر يضع لماذا أرى كل رجل يداه على حقويه كماخض ، وتحول كل وجه إلى صفرة '),
(18149, 'Jeremiah', 24, 30, 7, ' آه لأن ذلك اليوم عظيم وليس مثله . وهو وقت ضيق على يعقوب ، ولكنه سيخلص منه '),
(18150, 'Jeremiah', 24, 30, 8, ' ويكون في ذلك اليوم ، يقول رب الجنود ، أني أكسر نيره عن عنقك ، وأقطع ربطك ، ولا يستعبده بعد الغرباء '),
(18151, 'Jeremiah', 24, 30, 9, ' بل يخدمون الرب إلههم وداود ملكهم الذي أقيمه لهم '),
(18152, 'Jeremiah', 24, 30, 10, ' أما أنت يا عبدي يعقوب فلا تخف ، يقول الرب ، ولا ترتعب يا إسرائيل ، لأني هأنذا أخلصك من بعيد ، ونسلك من أرض سبيه ، فيرجع يعقوب ويطمئن ويستريح ولا مزعج '),
(18153, 'Jeremiah', 24, 30, 11, ' لأني أنا معك ، يقول الرب ، لأخلصك . وإن أفنيت جميع الأمم الذين بددتك إليهم ، فأنت لا أفنيك ، بل أؤدبك بالحق ، ولا أبرئك تبرئة '),
(18154, 'Jeremiah', 24, 30, 12, ' لأنه هكذا قال الرب : كسرك عديم الجبر وجرحك عضال '),
(18155, 'Jeremiah', 24, 30, 13, ' ليس من يقضي حاجتك للعصر . ليس لك عقاقير رفادة '),
(18156, 'Jeremiah', 24, 30, 14, ' قد نسيك كل محبيك . إياك لم يطلبوا . لأني ضربتك ضربة عدو ، تأديب قاس ، لأن إثمك قد كثر ، وخطاياك تعاظمت '),
(18157, 'Jeremiah', 24, 30, 15, ' ما بالك تصرخين بسبب كسرك ؟ جرحك عديم البرء ، لأن إثمك قد كثر ، وخطاياك تعاظمت ، قد صنعت هذه بك '),
(18158, 'Jeremiah', 24, 30, 16, ' لذلك يؤكل كل آكليك ، ويذهب كل أعدائك قاطبة إلى السبي ، ويكون كل سالبيك سلبا ، وأدفع كل ناهبيك للنهب '),
(18159, 'Jeremiah', 24, 30, 17, ' لأني أرفدك وأشفيك من جروحك ، يقول الرب . لأنهم قد دعوك منفية صهيون التي لا سائل عنها '),
(18160, 'Jeremiah', 24, 30, 18, ' هكذا قال الرب : هأنذا أرد سبي خيام يعقوب ، وأرحم مساكنه ، وتبنى المدينة على تلها ، والقصر يسكن على عادته '),
(18161, 'Jeremiah', 24, 30, 19, ' ويخرج منهم الحمد وصوت اللاعبين ، وأكثرهم ولا يقلون ، وأعظمهم ولا يصغرون '),
(18162, 'Jeremiah', 24, 30, 20, ' ويكون بنوهم كما في القديم ، وجماعتهم تثبت أمامي ، وأعاقب كل مضايقيهم '),
(18163, 'Jeremiah', 24, 30, 21, ' ويكون حاكمهم منهم ، ويخرج واليهم من وسطهم ، وأقربه فيدنو إلي ، لأنه من هو هذا الذي أرهن قلبه ليدنو إلي ، يقول الرب '),
(18164, 'Jeremiah', 24, 30, 22, ' وتكونون لي شعبا وأنا أكون لكم إلها '),
(18165, 'Jeremiah', 24, 30, 23, ' هوذا زوبعة الرب تخرج بغضب ، نوء جارف . على رأس الأشرار يثور '),
(18166, 'Jeremiah', 24, 30, 24, ' لا يرتد حمو غضب الرب حتى يفعل ، وحتى يقيم مقاصد قلبه . في آخر الأيام تفهمونها '),
(18167, 'Jeremiah', 24, 31, 1, ' في ذلك الزمان ، يقول الرب ، أكون إلها لكل عشائر إسرائيل ، وهم يكونون لي شعبا '),
(18168, 'Jeremiah', 24, 31, 2, ' هكذا قال الرب : قد وجد نعمة في البرية ، الشعب الباقي عن السيف ، إسرائيل حين سرت لأريحه '),
(18169, 'Jeremiah', 24, 31, 3, ' تراءى لي الرب من بعيد : ومحبة أبدية أحببتك ، من أجل ذلك أدمت لك الرحمة '),
(18170, 'Jeremiah', 24, 31, 4, ' سأبنيك بعد ، فتبنين يا عذراء إسرائيل . تتزينين بعد بدفوفك ، وتخرجين في رقص اللاعبين '),
(18171, 'Jeremiah', 24, 31, 5, ' تغرسين بعد كروما في جبال السامرة . يغرس الغارسون ويبتكرون '),
(18172, 'Jeremiah', 24, 31, 6, ' لأنه يكون يوم ينادي فيه النواطير في جبال أفرايم : قوموا فنصعد إلى صهيون ، إلى الرب إلهنا '),
(18173, 'Jeremiah', 24, 31, 7, ' لأنه هكذا قال الرب : رنموا ليعقوب فرحا ، واهتفوا برأس الشعوب . سمعوا ، سبحوا ، وقولوا : خلص يارب شعبك بقية إسرائيل '),
(18174, 'Jeremiah', 24, 31, 8, ' هأنذا آتي بهم من أرض الشمال ، وأجمعهم من أطراف الأرض . بينهم الأعمى والأعرج ، الحبلى والماخض معا . جمع عظيم يرجع إلى هنا '),
(18175, 'Jeremiah', 24, 31, 9, ' بالبكاء يأتون ، وبالتضرعات أقودهم . أسيرهم إلى أنهار ماء في طريق مستقيمة لا يعثرون فيها . لأني صرت لإسرائيل أبا ، وأفرايم هو بكري '),
(18176, 'Jeremiah', 24, 31, 10, ' اسمعوا كلمة الرب أيها الأمم ، وأخبروا في الجزائر البعيدة ، وقولوا : مبدد إسرائيل يجمعه ويحرسه كراع قطيعه '),
(18177, 'Jeremiah', 24, 31, 11, ' لأن الرب فدى يعقوب وفكه من يد الذي هو أقوى منه '),
(18178, 'Jeremiah', 24, 31, 12, ' فيأتون ويرنمون في مرتفع صهيون ، ويجرون إلى جود الرب على الحنطة وعلى الخمر وعلى الزيت وعلى أبناء الغنم والبقر . وتكون نفسهم كجنة ريا ، ولا يعودون يذوبون بعد '),
(18179, 'Jeremiah', 24, 31, 13, ' حينئذ تفرح العذراء بالرقص ، والشبان والشيوخ معا . وأحول نوحهم إلى طرب ، وأعزيهم وأفرحهم من حزنهم '),
(18180, 'Jeremiah', 24, 31, 14, ' وأروي نفس الكهنة من الدسم ، ويشبع شعبي من جودي ، يقول الرب '),
(18181, 'Jeremiah', 24, 31, 15, ' هكذا قال الرب : صوت سمع في الرامة ، نوح ، بكاء مر . راحيل تبكي على أولادها ، وتأبى أن تتعزى عن أولادها لأنهم ليسوا بموجودين '),
(18182, 'Jeremiah', 24, 31, 16, ' هكذا قال الرب : امنعي صوتك عن البكاء ، وعينيك عن الدموع ، لأنه يوجد جزاء لعملك ، يقول الرب . فيرجعون من أرض العدو '),
(18183, 'Jeremiah', 24, 31, 17, ' ويوجد رجاء لآخرتك ، يقول الرب . فيرجع الأبناء إلى تخمهم '),
(18184, 'Jeremiah', 24, 31, 18, ' سمعا سمعت أفرايم ينتحب : أدبتني فتأدبت كعجل غير مروض . توبني فأتوب ، لأنك أنت الرب إلهي '),
(18185, 'Jeremiah', 24, 31, 19, ' لأني بعد رجوعي ندمت ، وبعد تعلمي صفقت على فخذي . خزيت وخجلت لأني قد حملت عار صباي '),
(18186, 'Jeremiah', 24, 31, 20, ' هل أفرايم ابن عزيز لدي ، أو ولد مسر ؟ لأني كلما تكلمت به أذكره بعد ذكرا . من أجل ذلك حنت أحشائي إليه . رحمة أرحمه ، يقول الرب '),
(18187, 'Jeremiah', 24, 31, 21, ' انصبي لنفسك صوى . اجعلي لنفسك أنصابا . اجعلي قلبك نحو السكة ، الطريق التي ذهبت فيها . ارجعي يا عذراء إسرائيل . ارجعي إلى مدنك هذه '),
(18188, 'Jeremiah', 24, 31, 22, ' حتى متى تطوفين أيتها البنت المرتدة ؟ لأن الرب قد خلق شيئا حديثا في الأرض . أنثى تحيط برجل '),
(18189, 'Jeremiah', 24, 31, 23, ' هكذا قال رب الجنود إله إسرائيل : سيقولون بعد هذه الكلمة في أرض يهوذا وفي مدنها ، عندما أرد سبيهم : يباركك الرب يا مسكن البر ، يا أيها الجبل المقدس '),
(18190, 'Jeremiah', 24, 31, 24, ' فيسكن فيه يهوذا وكل مدنه معا ، الفلاحون والذين يسرحون القطعان '),
(18191, 'Jeremiah', 24, 31, 25, ' لأني أرويت النفس المعيية ، وملأت كل نفس ذائبة '),
(18192, 'Jeremiah', 24, 31, 26, ' على ذلك استيقظت ونظرت ولذ لي نومي '),
(18193, 'Jeremiah', 24, 31, 27, ' ها أيام تأتي ، يقول الرب ، وأزرع بيت إسرائيل وبيت يهوذا بزرع إنسان وزرع حيوان '),
(18194, 'Jeremiah', 24, 31, 28, ' ويكون كما سهرت عليهم للاقتلاع والهدم والقرض والإهلاك والأذى ، كذلك أسهر عليهم للبناء والغرس ، يقول الرب '),
(18195, 'Jeremiah', 24, 31, 29, ' في تلك الأيام لا يقولون بعد : الآباء أكلوا حصرما ، وأسنان الأبناء ضرست '),
(18196, 'Jeremiah', 24, 31, 30, ' بل كل واحد يموت بذنبه . كل إنسان يأكل الحصرم تضرس أسنانه '),
(18197, 'Jeremiah', 24, 31, 31, ' ها أيام تأتي ، يقول الرب ، وأقطع مع بيت إسرائيل ومع بيت يهوذا عهدا جديدا '),
(18198, 'Jeremiah', 24, 31, 32, ' ليس كالعهد الذي قطعته مع آبائهم يوم أمسكتهم بيدهم لأخرجهم من أرض مصر ، حين نقضوا عهدي فرفضتهم ، يقول الرب '),
(18199, 'Jeremiah', 24, 31, 33, ' بل هذا هو العهد الذي أقطعه مع بيت إسرائيل بعد تلك الأيام ، يقول الرب : أجعل شريعتي في داخلهم وأكتبها على قلوبهم ، وأكون لهم إلها وهم يكونون لي شعبا '),
(18200, 'Jeremiah', 24, 31, 34, ' ولا يعلمون بعد كل واحد صاحبه ، وكل واحد أخاه ، قائلين : اعرفوا الرب ، لأنهم كلهم سيعرفونني من صغيرهم إلى كبيرهم ، يقول الرب ، لأني أصفح عن إثمهم ، ولا أذكر خطيتهم بعد '),
(18201, 'Jeremiah', 24, 31, 35, ' هكذا قال الرب الجاعل الشمس للإضاءة نهارا ، وفرائض القمر والنجوم للإضاءة ليلا ، الزاجر البحر حين تعج أمواجه ، رب الجنود اسمه '),
(18202, 'Jeremiah', 24, 31, 36, ' إن كانت هذه الفرائض تزول من أمامي ، يقول الرب ، فإن نسل إسرائيل أيضا يكف من أن يكون أمة أمامي كل الأيام '),
(18203, 'Jeremiah', 24, 31, 37, ' هكذا قال الرب : إن كانت السماوات تقاس من فوق وتفحص أساسات الأرض من أسفل ، فإني أنا أيضا أرفض كل نسل إسرائيل من أجل كل ما عملوا ، يقول الرب '),
(18204, 'Jeremiah', 24, 31, 38, ' ها أيام تأتي ، يقول الرب ، وتبنى المدينة للرب من برج حننئيل إلى باب الزاوية '),
(18205, 'Jeremiah', 24, 31, 39, ' ويخرج بعد خيط القياس مقابله على أكمة جارب ، ويستدير إلى جوعة '),
(18206, 'Jeremiah', 24, 31, 40, ' ويكون كل وادي الجثث والرماد ، وكل الحقول إلى وادي قدرون إلى زاوية باب الخيل شرقا ، قدسا للرب . لا تقلع ولا تهدم إلى الأبد '),
(18207, 'Jeremiah', 24, 32, 1, ' الكلمة التي صارت إلى إرميا من قبل الرب ، في السنة العاشرة لصدقيا ملك يهوذا ، هي السنة الثامنة عشرة لنبوخذراصر '),
(18208, 'Jeremiah', 24, 32, 2, ' وكان حينئذ جيش ملك بابل يحاصر أورشليم ، وكان إرميا النبي محبوسا في دار السجن الذي في بيت ملك يهوذا '),
(18209, 'Jeremiah', 24, 32, 3, ' لأن صدقيا ملك يهوذا حبسه قائلا : لماذا تنبأت قائلا : هكذا قال الرب : هأنذا أدفع هذه المدينة ليد ملك بابل ، فيأخذها '),
(18210, 'Jeremiah', 24, 32, 4, ' وصدقيا ملك يهوذا لا يفلت من يد الكلدانيين بل إنما يدفع ليد ملك بابل ، ويكلمه فما لفم وعيناه تريان عينيه '),
(18211, 'Jeremiah', 24, 32, 5, ' ويسير بصدقيا إلى بابل فيكون هناك حتى أفتقده ، يقول الرب . إن حاربتم الكلدانيين لا تنجحون '),
(18212, 'Jeremiah', 24, 32, 6, ' فقال إرميا : كلمة الرب صارت إلي قائلة '),
(18213, 'Jeremiah', 24, 32, 7, ' هوذا حنمئيل بن شلوم عمك يأتي إليك قائلا : اشتر لنفسك حقلي الذي في عناثوث ، لأن لك حق الفكاك للشراء '),
(18214, 'Jeremiah', 24, 32, 8, ' فجاء إلي حنمئيل ابن عمي حسب كلمة الرب إلى دار السجن ، وقال لي : اشتر حقلي الذي في عناثوث الذي في أرض بنيامين ، لأن لك حق الإرث ، ولك الفكاك . اشتره لنفسك . فعرفت أنها كلمة الرب '),
(18215, 'Jeremiah', 24, 37, 15, ' فغضب الرؤساء على إرميا ، وضربوه وجعلوه في بيت السجن ، في بيت يوناثان الكاتب ، لأنهم جعلوه بيت السجن '),
(18216, 'Jeremiah', 24, 37, 16, ' فلما دخل إرميا إلى بيت الجب ، وإلى المقببات ، أقام إرميا هناك أياما كثيرة '),
(18217, 'Jeremiah', 24, 37, 17, ' ثم أرسل الملك صدقيا وأخذه ، وسأله الملك في بيته سرا وقال : هل توجد كلمة من قبل الرب ؟  . فقال إرميا : توجد . فقال : إنك تدفع ليد ملك بابل '),
(18218, 'Jeremiah', 24, 37, 18, ' ثم قال إرميا للملك صدقيا : ما هي خطيتي إليك وإلى عبيدك وإلى هذا الشعب ، حتى جعلتموني في بيت السجن '),
(18219, 'Jeremiah', 24, 37, 19, ' فأين أنبياؤكم الذين تنبأوا لكم قائلين : لا يأتي ملك بابل عليكم ، ولا على هذه الأرض '),
(18220, 'Jeremiah', 24, 37, 20, ' فالآن اسمع يا سيدي الملك . ليقع تضرعي أمامك ، ولا تردني إلى بيت يوناثان الكاتب ، فلا أموت هناك '),
(18221, 'Jeremiah', 24, 37, 21, ' فأمر الملك صدقيا أن يضعوا إرميا في دار السجن ، وأن يعطى رغيف خبز كل يوم من سوق الخبازين ، حتى ينفد كل الخبز من المدينة . فأقام إرميا في دار السجن '),
(18222, 'Jeremiah', 24, 38, 1, ' وسمع شفطيا بن متان ، وجدليا بن فشحور ، ويوخل بن شلميا ، وفشحور بن ملكيا ، الكلام الذي كان إرميا يكلم به كل الشعب قائلا '),
(18223, 'Jeremiah', 24, 38, 2, ' هكذا قال الرب : الذي يقيم في هذه المدينة يموت بالسيف والجوع والوبإ . أما الذي يخرج إلى الكلدانيين فإنه يحيا وتكون له نفسه غنيمة فيحيا '),
(18224, 'Jeremiah', 24, 38, 3, ' هكذا قال الرب : هذه المدينة ستدفع دفعا ليد جيش ملك بابل فيأخذها '),
(18225, 'Jeremiah', 24, 38, 4, ' فقال الرؤساء للملك : ليقتل هذا الرجل ، لأنه بذلك يضعف أيادي رجال الحرب الباقين في هذه المدينة ، وأيادي كل الشعب ، إذ يكلمهم بمثل هذا الكلام . لأن هذا الرجل لا يطلب السلام لهذا الشعب بل الشر '),
(18226, 'Jeremiah', 24, 38, 5, ' فقال الملك صدقيا : ها هو بيدكم ، لأن الملك لا يقدر عليكم في شيء '),
(18227, 'Jeremiah', 24, 38, 6, ' فأخذوا إرميا وألقوه في جب ملكيا ابن الملك ، الذي في دار السجن ، ودلوا إرميا بحبال . ولم يكن في الجب ماء بل وحل ، فغاص إرميا في الوحل '),
(18228, 'Jeremiah', 24, 38, 7, ' فلما سمع عبد ملك الكوشي ، رجل خصي ، وهو في بيت الملك ، أنهم جعلوا إرميا في الجب ، والملك جالس في باب بنيامين '),
(18229, 'Jeremiah', 24, 38, 8, ' خرج عبد ملك من بيت الملك وكلم الملك قائلا '),
(18230, 'Jeremiah', 24, 38, 9, ' يا سيدي الملك ، قد أساء هؤلاء الرجال في كل ما فعلوا بإرميا النبي ، الذي طرحوه في الجب ، فإنه يموت في مكانه بسبب الجوع ، لأنه ليس بعد خبز في المدينة '),
(18231, 'Jeremiah', 24, 38, 10, ' فأمر الملك عبد ملك الكوشي قائلا : خذ معك من هنا ثلاثين رجلا ، وأطلع إرميا من الجب قبلما يموت '),
(18232, 'Jeremiah', 24, 38, 11, ' فأخذ عبد ملك الرجال معه ، ودخل إلى بيت الملك ، إلى أسفل المخزن ، وأخذ من هناك ثيابا رثة وملابس بالية ودلاها إلى إرميا إلى الجب بحبال '),
(18233, 'Jeremiah', 24, 38, 12, ' وقال عبد ملك الكوشي لإرميا : ضع الثياب الرثة والملابس البالية تحت إبطيك تحت الحبال . ففعل إرميا كذلك '),
(18234, 'Jeremiah', 24, 38, 13, ' فجذبوا إرميا بالحبال وأطلعوه من الجب . فأقام إرميا في دار السجن '),
(18235, 'Jeremiah', 24, 38, 14, ' فأرسل الملك صدقيا وأخذ إرميا النبي إليه ، إلى المدخل الثالث الذي في بيت الرب ، وقال الملك لإرميا : أنا أسألك عن أمر . لا تخف عني شيئا '),
(18236, 'Jeremiah', 24, 38, 15, ' فقال إرميا لصدقيا : إذا أخبرتك أفما تقتلني قتلا ؟ وإذا أشرت عليك فلا تسمع لي '),
(18237, 'Jeremiah', 24, 38, 16, ' فحلف الملك صدقيا لإرميا سرا قائلا : حي هو الرب الذي صنع لنا هذه النفس ، إني لا أقتلك ولا أدفعك ليد هؤلاء الرجال الذين يطلبون نفسك '),
(18238, 'Jeremiah', 24, 38, 17, ' فقال إرميا لصدقيا : هكذا قال الرب إله الجنود إله إسرائيل : إن كنت تخرج خروجا إلى رؤساء ملك بابل ، تحيا نفسك ولا تحرق هذه المدينة بالنار ، بل تحيا أنت وبيتك '),
(18239, 'Jeremiah', 24, 38, 18, ' ولكن إن كنت لا تخرج إلى رؤساء ملك بابل ، تدفع هذه المدينة ليد الكلدانيين فيحرقونها بالنار ، وأنت لا تفلت من يدهم '),
(18240, 'Jeremiah', 24, 38, 19, ' فقال صدقيا الملك لإرميا : إني أخاف من اليهود الذين قد سقطوا للكلدانيين لئلا يدفعوني ليدهم فيزدروا بي '),
(18241, 'Jeremiah', 24, 38, 20, ' فقال إرميا : لا يدفعونك . اسمع لصوت الرب في ما أكلمك أنا به ، فيحسن إليك وتحيا نفسك '),
(18242, 'Jeremiah', 24, 38, 21, ' وإن كنت تأبى الخروج ، فهذه هي الكلمة التي أراني الرب إياها '),
(18243, 'Jeremiah', 24, 38, 22, ' ها كل النساء اللواتي بقين في بيت ملك يهوذا ، يخرجن إلى رؤساء ملك بابل وهن يقلن : قد خدعك وقدر عليك مسالموك . غاصت في الحمأة رجلاك وارتدتا إلى الوراء '),
(18244, 'Jeremiah', 24, 38, 23, ' ويخرجون كل نسائك وبنيك إلى الكلدانيين ، وأنت لا تفلت من يدهم ، لأنك أنت تمسك بيد ملك بابل ، وهذه المدينة تحرق بالنار '),
(18245, 'Jeremiah', 24, 38, 24, ' فقال صدقيا لإرميا : لا يعلم أحد بهذا الكلام ، فلا تموت '),
(18246, 'Jeremiah', 24, 38, 25, ' وإذا سمع الرؤساء أني كلمتك ، وأتوا إليك وقالوا لك : أخبرنا بماذا كلمت الملك ، لا تخف عنا فلا نقتلك ، وماذا قال لك الملك '),
(18247, 'Jeremiah', 24, 38, 26, ' فقل لهم : إني ألقيت تضرعي أمام الملك حتى لا يردني إلى بيت يوناثان لأموت هناك '),
(18248, 'Jeremiah', 24, 38, 27, ' فأتى كل الرؤساء إلى إرميا وسألوه ، فأخبرهم حسب كل هذا الكلام الذي أوصاه به الملك . فسكتوا عنه لأن الأمر لم يسمع '),
(18249, 'Jeremiah', 24, 38, 28, ' فأقام إرميا في دار السجن إلى اليوم الذي أخذت فيه أورشليم . ولما أخذت أورشليم '),
(18250, 'Jeremiah', 24, 39, 1, ' في السنة التاسعة لصدقيا ملك يهوذا في الشهر العاشر ، أتى نبوخذراصر ملك بابل وكل جيشه إلى أورشليم وحاصروها '),
(18251, 'Jeremiah', 24, 39, 2, ' وفي السنة الحادية عشرة لصدقيا ، في الشهر الرابع ، في تاسع الشهر فتحت المدينة '),
(18252, 'Jeremiah', 24, 39, 3, ' ودخل كل رؤساء ملك بابل وجلسوا في الباب الأوسط : نرجل شراصر ، وسمجر نبو ، وسرسخيم رئيس الخصيان ، ونرجل شراصر رئيس المجوس ، وكل بقية رؤساء ملك بابل '),
(18253, 'Jeremiah', 24, 39, 4, ' فلما رآهم صدقيا ملك يهوذا وكل رجال الحرب ، هربوا وخرجوا ليلا من المدينة في طريق جنة الملك ، من الباب بين السورين ، وخرج هو في طريق العربة '),
(18254, 'Jeremiah', 24, 39, 5, ' فسعى جيش الكلدانيين وراءهم ، فأدركوا صدقيا في عربات أريحا ، فأخذوه وأصعدوه إلى نبوخذناصر ملك بابل إلى ربلة في أرض حماة ، فكلمه بالقضاء عليه '),
(18255, 'Jeremiah', 24, 39, 6, ' فقتل ملك بابل بني صدقيا في ربلة أمام عينيه ، وقتل ملك بابل كل أشراف يهوذا '),
(18256, 'Jeremiah', 24, 39, 7, ' وأعمى عيني صدقيا ، وقيده بسلاسل نحاس ليأتي به إلى بابل '),
(18257, 'Jeremiah', 24, 39, 8, ' أما بيت الملك وبيوت الشعب فأحرقها الكلدانيون بالنار ، ونقضوا أسوار أورشليم '),
(18258, 'Jeremiah', 24, 39, 9, ' وبقية الشعب الذين بقوا في المدينة ، والهاربون الذين سقطوا له ، وبقية الشعب الذين بقوا ، سباهم نبوزرادان رئيس الشرط إلى بابل '),
(18259, 'Jeremiah', 24, 39, 10, ' ولكن بعض الشعب الفقراء الذين لم يكن لهم شيء ، تركهم نبوزرادان رئيس الشرط في أرض يهوذا ، وأعطاهم كروما وحقولا في ذلك اليوم '),
(18260, 'Jeremiah', 24, 39, 11, ' وأوصى نبوخذراصر ملك بابل على إرميا نبوزرادان رئيس الشرط قائلا '),
(18261, 'Jeremiah', 24, 39, 12, ' خذه وضع عينيك عليه ، ولا تفعل به شيئا رديئا ، بل كما يكلمك هكذا افعل معه '),
(18262, 'Jeremiah', 24, 39, 13, ' فأرسل نبوزرادان رئيس الشرط ونبوشزبان رئيس الخصيان ونرجل شراصر رئيس المجوس وكل رؤساء ملك بابل '),
(18263, 'Jeremiah', 24, 39, 14, ' أرسلوا فأخذوا إرميا من دار السجن وأسلموه لجدليا بن أخيقام بن شافان ليخرج به إلى البيت . فسكن بين الشعب '),
(18264, 'Jeremiah', 24, 39, 15, ' وصارت كلمة الرب إلى إرميا إذ كان محبوسا في دار السجن قائلة '),
(18265, 'Jeremiah', 24, 39, 16, ' اذهب وكلم عبد ملك الكوشي قائلا : هكذا قال رب الجنود إله إسرائيل : هأنذا جالب كلامي على هذه المدينة للشر لا للخير ، فيحدث أمامك في ذلك اليوم '),
(18266, 'Jeremiah', 24, 39, 17, ' ولكنني أنقذك في ذلك اليوم ، يقول الرب ، فلا تسلم ليد الناس الذين أنت خائف منهم '),
(18267, 'Jeremiah', 24, 39, 18, ' بل إنما أنجيك نجاة ، فلا تسقط بالسيف ، بل تكون لك نفسك غنيمة ، لأنك قد توكلت علي ، يقول الرب '),
(18268, 'Jeremiah', 24, 40, 1, ' الكلمة التي صارت إلى إرميا من قبل الرب ، بعد ما أرسله نبوزرادان رئيس الشرط من الرامة ، إذ أخذه وهو مقيد بالسلاسل في وسط كل سبي أورشليم ويهوذا الذين سبوا إلى بابل '),
(18269, 'Jeremiah', 24, 40, 2, ' فأخذ رئيس الشرط إرميا وقال له : إن الرب إلهك قد تكلم بهذا الشر على هذا الموضع '),
(18270, 'Jeremiah', 24, 40, 3, ' فجلب الرب وفعل كما تكلم ، لأنكم قد أخطأتم إلى الرب ولم تسمعوا لصوته ، فحدث لكم هذا الأمر '),
(18271, 'Jeremiah', 24, 40, 4, ' فالآن هأنذا أحلك اليوم من القيود التي على يدك . فإن حسن في عينيك أن تأتي معي إلى بابل فتعال ، فأجعل عيني عليك . وإن قبح في عينيك أن تأتي معي إلى بابل فامتنع . انظر . كل الأرض هي أمامك ، فحيثما حسن وكان مستقيما في عينيك أن تنطلق فانطلق إلى هناك '),
(18272, 'Jeremiah', 24, 40, 5, ' وإذ كان لم يرجع بعد ، قال : ارجع إلى جدليا بن أخيقام بن شافان الذي أقامه ملك بابل على مدن يهوذا ، وأقم عنده في وسط الشعب ، وانطلق إلى حيث كان مستقيما في عينيك أن تنطلق . وأعطاه رئيس الشرط زادا وهدية وأطلقه '),
(18273, 'Jeremiah', 24, 40, 6, ' فجاء إرميا إلى جدليا بن أخيقام إلى المصفاة ، وأقام عنده في وسط الشعب الباقين في الأرض '),
(18274, 'Jeremiah', 24, 40, 7, ' فلما سمع كل رؤساء الجيوش الذين في الحقل هم ورجالهم أن ملك بابل قد أقام جدليا بن أخيقام على الأرض ، وأنه وكله على الرجال والنساء والأطفال وعلى فقراء الأرض الذين لم يسبوا إلى بابل '),
(18275, 'Jeremiah', 24, 40, 8, ' أتى إلى جدليا إلى المصفاة : إسماعيل بن نثنيا ، ويوحانان ويوناثان ابنا قاريح ، وسرايا بن تنحومث ، وبنو عيفاي النطوفاتي ، ويزنيا ابن المعكي ، هم ورجالهم '),
(18276, 'Jeremiah', 24, 40, 9, ' فحلف لهم جدليا بن أخيقام بن شافان ولرجالهم قائلا : لا تخافوا من أن تخدموا الكلدانيين . اسكنوا في الأرض ، واخدموا ملك بابل فيحسن إليكم '),
(18277, 'Jeremiah', 24, 40, 10, ' أما أنا فهأنذا ساكن في المصفاة لأقف أمام الكلدانيين الذين يأتون إلينا . أما أنتم فاجمعوا خمرا وتينا وزيتا وضعوا في أوعيتكم ، واسكنوا في مدنكم التي أخذتموها '),
(18278, 'Jeremiah', 24, 40, 11, ' وكذلك كل اليهود الذين في موآب ، وبين بني عمون ، وفي أدوم ، والذين في كل الأراضي ، سمعوا أن ملك بابل قد جعل بقية ليهوذا ، وقد أقام عليهم جدليا بن أخيقام بن شافان '),
(18279, 'Jeremiah', 24, 40, 12, ' فرجع كل اليهود من كل المواضع التي طوحوا إليها وأتوا إلى أرض يهوذا ، إلى جدليا ، إلى المصفاة ، وجمعوا خمرا وتينا كثيرا جدا '),
(18280, 'Jeremiah', 24, 40, 13, ' ثم إن يوحانان بن قاريح وكل رؤساء الجيوش الذين في الحقل أتوا إلى جدليا إلى المصفاة '),
(18281, 'Jeremiah', 24, 40, 14, ' وقالوا له : أتعلم علما أن بعليس ملك بني عمون قد أرسل إسماعيل بن نثنيا ليقتلك ؟  . فلم يصدقهم جدليا بن أخيقام '),
(18282, 'Jeremiah', 24, 40, 15, ' فكلم يوحانان بن قاريح جدليا سرا في المصفاة قائلا : دعني أنطلق وأضرب إسماعيل بن نثنيا ولا يعلم إنسان . لماذا يقتلك فيتبدد كل يهوذا المجتمع إليك ، وتهلك بقية يهوذا '),
(18283, 'Jeremiah', 24, 40, 16, ' فقال جدليا بن أخيقام ليوحانان بن قاريح : لا تفعل هذا الأمر ، لأنك إنما تتكلم بالكذب عن إسماعيل '),
(18284, 'Jeremiah', 24, 41, 1, ' وكان في الشهر السابع ، أن إسماعيل بن نثنيا بن أليشاماع ، من النسل الملوكي ، جاء هو وعظماء الملك وعشرة رجال معه إلى جدليا بن أخيقام إلى المصفاة ، وأكلوا هناك خبزا معا في المصفاة '),
(18285, 'Jeremiah', 24, 41, 2, ' فقام إسماعيل بن نثنيا والعشرة الرجال الذين كانوا معه وضربوا جدليا بن أخيقام بن شافان بالسيف فقتلوه ، هذا الذي أقامه ملك بابل على الأرض '),
(18286, 'Jeremiah', 24, 41, 3, ' وكل اليهود الذين كانوا معه ، أي مع جدليا ، في المصفاة والكلدانيون الذين وجدوا هناك ، ورجال الحرب ، ضربهم إسماعيل '),
(18287, 'Jeremiah', 24, 41, 4, ' وكان في اليوم الثاني بعد قتله جدليا ولم يعلم إنسان '),
(18288, 'Jeremiah', 24, 41, 5, ' أن رجالا أتوا من شكيم ومن شيلو ومن السامرة ، ثمانين رجلا محلوقي اللحى ومشققي الثياب ومخمشين ، وبيدهم تقدمة ولبان ليدخلوهما إلى بيت الرب '),
(18289, 'Jeremiah', 24, 41, 6, ' فخرج إسماعيل بن نثنيا للقائهم من المصفاة سائرا وباكيا . فكان لما لقيهم أنه قال لهم : هلم إلى جدليا بن أخيقام '),
(18290, 'Jeremiah', 24, 41, 7, ' فكان لما أتوا إلى وسط المدينة ، أن إسماعيل بن نثنيا قتلهم وألقاهم إلى وسط الجب ، هو والرجال الذين معه '),
(18291, 'Jeremiah', 24, 41, 8, ' ولكن وجد فيهم عشرة رجال قالوا لإسماعيل : لا تقتلنا لأنه يوجد لنا خزائن في الحقل : قمح وشعير وزيت وعسل . فامتنع ولم يقتلهم بين إخوتهم '),
(18292, 'Jeremiah', 24, 41, 9, ' فالجب الذي طرح فيه إسماعيل كل جثث الرجال الذين قتلهم بسبب جدليا ، هو الذي صنعه الملك آسا من وجه بعشا ملك إسرائيل . فملأه إسماعيل بن نثنيا من القتلى '),
(18293, 'Jeremiah', 24, 41, 10, ' فسبى إسماعيل كل بقية الشعب الذين في المصفاة ، بنات الملك وكل الشعب الذي بقي في المصفاة ، الذين أقام عليهم نبوزرادان رئيس الشرط جدليا بن أخيقام ، سباهم إسماعيل بن نثنيا وذهب ليعبر إلى بني عمون '),
(18294, 'Jeremiah', 24, 41, 11, ' فلما سمع يوحانان بن قاريح وكل رؤساء الجيوش الذين معه بكل الشر الذي فعله إسماعيل بن نثنيا '),
(18295, 'Jeremiah', 24, 41, 12, ' أخذوا كل الرجال وساروا ليحاربوا إسماعيل بن نثنيا ، فوجدوه عند المياه الكثيرة التي في جبعون '),
(18296, 'Jeremiah', 24, 41, 13, ' ولما رأى كل الشعب الذي مع إسماعيل يوحانان بن قاريح وكل رؤساء الجيوش الذين معهم فرحوا '),
(18297, 'Jeremiah', 24, 41, 14, ' فدار كل الشعب الذي سباه إسماعيل من المصفاة ، ورجعوا وساروا إلى يوحانان بن قاريح '),
(18298, 'Jeremiah', 24, 41, 15, ' أما إسماعيل بن نثنيا فهرب بثمانية رجال من وجه يوحانان وسار إلى بني عمون '),
(18299, 'Jeremiah', 24, 41, 16, ' فأخذ يوحانان بن قاريح وكل رؤساء الجيوش الذين معه ، كل بقية الشعب الذين استردهم من إسماعيل بن نثنيا من المصفاة ، بعد قتل جدليا بن أخيقام ، رجال الحرب المقتدرين والنساء والأطفال والخصيان الذين استردهم من جبعون '),
(18300, 'Jeremiah', 24, 41, 17, ' فساروا وأقاموا في جيروت كمهام التي بجانب بيت لحم ، لكي يسيروا ويدخلوا مصر '),
(18301, 'Jeremiah', 24, 41, 18, ' من وجه الكلدانيين لأنهم كانوا خائفين منهم ، لأن إسماعيل بن نثنيا كان قد ضرب جدليا بن أخيقام الذي أقامه ملك بابل على الأرض '),
(18302, 'Jeremiah', 24, 42, 1, ' فتقدم كل رؤساء الجيوش ويوحانان بن قاريح ، ويزنيا بن هوشعيا ، وكل الشعب من الصغير إلى الكبير '),
(18303, 'Jeremiah', 24, 42, 2, ' وقالوا لإرميا النبي : ليت تضرعنا يقع أمامك ، فتصلي لأجلنا إلى الرب إلهك لأجل كل هذه البقية . لأننا قد بقينا قليلين من كثيرين كما ترانا عيناك '),
(18304, 'Jeremiah', 24, 42, 3, ' فيخبرنا الرب إلهك عن الطريق الذي نسير فيه ، والأمر الذي نفعله '),
(18305, 'Jeremiah', 24, 42, 4, ' فقال لهم إرميا النبي : قد سمعت . هأنذا أصلي إلى الرب إلهكم كقولكم ، ويكون أن كل الكلام الذي يجيبكم الرب أخبركم به . لا أمنع عنكم شيئا '),
(18306, 'Jeremiah', 24, 42, 5, ' فقالوا هم لإرميا : ليكن الرب بيننا شاهدا صادقا وأمينا إننا نفعل حسب كل أمر يرسلك به الرب إلهك إلينا '),
(18307, 'Jeremiah', 24, 42, 6, ' إن خيرا وإن شرا . فإننا نسمع لصوت الرب إلهك الذي نحن مرسلوك إليه ليحسن إلينا إذا سمعنا لصوت الرب إلهنا '),
(18308, 'Jeremiah', 24, 42, 7, ' وكان بعد عشرة أيام أن كلمة الرب صارت إلى إرميا '),
(18309, 'Jeremiah', 24, 42, 8, ' فدعا يوحانان بن قاريح وكل رؤساء الجيوش الذين معه ، وكل الشعب من الصغير إلى الكبير '),
(18310, 'Jeremiah', 24, 42, 9, ' وقال لهم : هكذا قال الرب إله إسرائيل الذي أرسلتموني إليه لكي ألقي تضرعكم أمامه '),
(18311, 'Jeremiah', 24, 42, 10, ' إن كنتم تسكنون في هذه الأرض ، فإني أبنيكم ولا أنقضكم ، وأغرسكم ولا أقتلعكم . لأني ندمت عن الشر الذي صنعته بكم '),
(18312, 'Jeremiah', 24, 42, 11, ' لا تخافوا ملك بابل الذي أنتم خائفوه . لا تخافوه ، يقول الرب ، لأني أنا معكم لأخلصكم وأنقذكم من يده '),
(18313, 'Jeremiah', 24, 42, 12, ' وأعطيكم نعمة ، فيرحمكم ويردكم إلى أرضكم '),
(18314, 'Jeremiah', 24, 42, 13, ' وإن قلتم : لا نسكن في هذه الأرض . ولم تسمعوا لصوت الرب إلهكم '),
(18315, 'Jeremiah', 24, 42, 14, ' قائلين : لا بل إلى أرض مصر نذهب ، حيث لا نرى حربا ، ولا نسمع صوت بوق ، ولا نجوع للخبز ، وهناك نسكن '),
(18316, 'Jeremiah', 24, 42, 15, ' فالآن لذلك اسمعوا كلمة الرب يا بقية يهوذا ، هكذا قال رب الجنود إله إسرائيل : إن كنتم تجعلون وجوهكم للدخول إلى مصر ، وتذهبون لتتغربوا هناك '),
(18317, 'Jeremiah', 24, 42, 16, ' يحدث أن السيف الذي أنتم خائفون منه يدرككم هناك في أرض مصر ، والجوع الذي أنتم خائفون منه يلحقكم هناك في مصر ، فتموتون هناك '),
(18318, 'Jeremiah', 24, 42, 17, ' ويكون أن كل الرجال الذين جعلوا وجوههم للدخول إلى مصر ليتغربوا هناك ، يموتون بالسيف والجوع والوبإ ، ولا يكون منهم باق ولا ناج من الشر الذي أجلبه أنا عليهم '),
(18319, 'Jeremiah', 24, 42, 18, ' لأنه هكذا قال رب الجنود إله إسرائيل : كما انسكب غضبي وغيظي على سكان أورشليم ، هكذا ينسكب غيظي عليكم عند دخولكم إلى مصر ، فتصيرون حلفا ودهشا ولعنة وعارا ، ولا ترون بعد هذا الموضع '),
(18320, 'Jeremiah', 24, 42, 19, ' قد تكلم الرب عليكم يا بقية يهوذا : لا تدخلوا مصر . اعلموا علما أني قد أنذرتكم اليوم '),
(18321, 'Jeremiah', 24, 42, 20, ' لأنكم قد خدعتم أنفسكم إذ أرسلتموني إلى الرب إلهكم قائلين : صل لأجلنا إلى الرب إلهنا ، وحسب كل ما يقوله الرب إلهنا هكذا أخبرنا فنفعل '),
(18322, 'Jeremiah', 24, 42, 21, ' فقد أخبرتكم اليوم فلم تسمعوا لصوت الرب إلهكم ، ولا لشيء مما أرسلني به إليكم '),
(18323, 'Jeremiah', 24, 42, 22, ' فالآن اعلموا علما أنكم تموتون بالسيف والجوع والوبإ في الموضع الذي ابتغيتم أن تدخلوه لتتغربوا فيه '),
(18324, 'Jeremiah', 24, 43, 1, ' وكان لما فرغ إرميا من أن كلم كل الشعب بكل كلام الرب إلههم ، الذي أرسله الرب إلههم إليهم ، بكل هذا الكلام '),
(18325, 'Jeremiah', 24, 43, 2, ' أن عزريا بن هوشعيا ويوحانان بن قاريح ، وكل الرجال المتكبرين كلموا إرميا قائلين : أنت متكلم بالكذب لم يرسلك الرب إلهنا لتقول : لا تذهبوا إلى مصر لتتغربوا هناك '),
(18326, 'Jeremiah', 24, 43, 3, ' بل باروخ بن نيريا مهيجك علينا لتدفعنا ليد الكلدانيين ليقتلونا ، وليسبونا إلى بابل '),
(18327, 'Jeremiah', 24, 43, 4, ' فلم يسمع يوحانان بن قاريح وكل رؤساء الجيوش وكل الشعب لصوت الرب بالإقامة في أرض يهوذا '),
(18328, 'Jeremiah', 24, 43, 5, ' بل أخذ يوحانان بن قاريح ، وكل رؤساء الجيوش ، كل بقية يهوذا الذين رجعوا من كل الأمم الذين طوحوا إليهم ليتغربوا في أرض يهوذا '),
(18329, 'Jeremiah', 24, 43, 6, ' الرجال والنساء والأطفال وبنات الملك ، وكل الأنفس الذين تركهم نبوزرادان رئيس الشرط ، مع جدليا بن أخيقام بن شافان ، وإرميا النبي وباروخ بن نيريا '),
(18330, 'Jeremiah', 24, 43, 7, ' فجاءوا إلى أرض مصر لأنهم لم يسمعوا لصوت الرب وأتوا إلى تحفنحيس '),
(18331, 'Jeremiah', 24, 43, 8, ' ثم صارت كلمة الرب إلى إرميا في تحفنحيس قائلة '),
(18332, 'Jeremiah', 24, 43, 9, ' خذ بيدك حجارة كبيرة واطمرها في الملاط ، في الملبن الذي عند باب بيت فرعون في تحفنحيس أمام رجال يهود '),
(18333, 'Jeremiah', 24, 43, 10, ' وقل لهم : هكذا قال رب الجنود إله إسرائيل : هأنذا أرسل وآخذ نبوخذراصر ملك بابل عبدي ، وأضع كرسيه فوق هذه الحجارة التي طمرتها فيبسط ديباجه عليها '),
(18334, 'Jeremiah', 24, 43, 11, ' ويأتي ويضرب أرض مصر ، الذي للموت فللموت ، والذي للسبي فللسبي ، والذي للسيف فللسيف '),
(18335, 'Jeremiah', 24, 43, 12, ' وأوقد نارا في بيوت آلهة مصر فيحرقها ويسبيها ، ويلبس أرض مصر كما يلبس الراعي رداءه ، ثم يخرج من هناك بسلام '),
(18336, 'Jeremiah', 24, 43, 13, ' ويكسر أنصاب بيت شمس التي في أرض مصر ، ويحرق بيوت آلهة مصر بالنار '),
(18337, 'Jeremiah', 24, 44, 1, ' الكلمة التي صارت إلى إرميا من جهة كل اليهود الساكنين في أرض مصر ، الساكنين في مجدل وفي تحفنحيس ، وفي نوف وفي أرض فتروس قائلة '),
(18338, 'Jeremiah', 24, 44, 2, ' هكذا قال رب الجنود إله إسرائيل : أنتم رأيتم كل الشر الذي جلبته على أورشليم ، وعلى كل مدن يهوذا ، فها هي خربة هذا اليوم وليس فيها ساكن '),
(18339, 'Jeremiah', 24, 44, 3, ' من أجل شرهم الذي فعلوه ليغيظوني ، إذ ذهبوا ليبخروا ويعبدوا آلهة أخرى لم يعرفوها هم ولا أنتم ولا آباؤكم '),
(18340, 'Jeremiah', 24, 44, 4, ' فأرسلت إليكم كل عبيدي الأنبياء مبكرا ومرسلا قائلا : لا تفعلوا أمر هذا الرجس الذي أبغضته '),
(18341, 'Jeremiah', 24, 44, 5, ' فلم يسمعوا ولا أمالوا أذنهم ليرجعوا عن شرهم فلا يبخروا لآلهة أخرى '),
(18342, 'Jeremiah', 24, 44, 6, ' فانسكب غيظي وغضبي ، واشتعلا في مدن يهوذا وفي شوارع أورشليم ، فصارت خربة مقفرة كهذا اليوم '),
(18343, 'Jeremiah', 24, 44, 7, ' فالآن هكذا قال الرب إله الجنود ، إله إسرائيل : لماذا أنتم فاعلون شرا عظيما ضد أنفسكم لانقراضكم رجالا ونساء أطفالا ورضعا من وسط يهوذا ولا تبقى لكم بقية '),
(18344, 'Jeremiah', 24, 44, 8, ' لإغاظتي بأعمال أياديكم ، إذ تبخرون لآلهة أخرى في أرض مصر التي أتيتم إليها لتتغربوا فيها ، لكي تنقرضوا ولكي تصيروا لعنة وعارا بين كل أمم الأرض '),
(18345, 'Jeremiah', 24, 44, 9, ' هل نسيتم شرور آبائكم وشرور ملوك يهوذا وشرور نسائهم ، وشروركم وشرور نسائكم التي فعلت في أرض يهوذا وفي شوارع أورشليم '),
(18346, 'Jeremiah', 24, 44, 10, ' لم يذلوا إلى هذا اليوم ، ولا خافوا ولا سلكوا في شريعتي وفرائضي التي جعلتها أمامكم وأمام آبائكم '),
(18347, 'Jeremiah', 24, 44, 11, ' لذلك هكذا قال رب الجنود إله إسرائيل : هأنذا أجعل وجهي عليكم للشر ، ولأقرض كل يهوذا '),
(18348, 'Jeremiah', 24, 44, 12, ' وآخذ بقية يهوذا الذين جعلوا وجوههم للدخول إلى أرض مصر ليتغربوا هناك ، فيفنون كلهم في أرض مصر . يسقطون بالسيف وبالجوع . يفنون من الصغير إلى الكبير بالسيف والجوع . يموتون ويصيرون حلفا ودهشا ولعنة وعارا '),
(18349, 'Jeremiah', 24, 44, 13, ' وأعاقب الذين يسكنون في أرض مصر ، كما عاقبت أورشليم بالسيف والجوع والوبإ '),
(18350, 'Jeremiah', 24, 44, 14, ' ولا يكون ناج ولا باق لبقية يهوذا الآتين ليتغربوا هناك في أرض مصر ، ليرجعوا إلى أرض يهوذا التي يشتاقون إلى الرجوع لأجل السكن فيها ، لأنه لا يرجع منهم إلا المنفلتون '),
(18351, 'Jeremiah', 24, 44, 15, ' فأجاب إرميا كل الرجال الذين عرفوا أن نساءهم يبخرن لآلهة أخرى ، وكل النساء الواقفات ، محفل كبير ، وكل الشعب الساكن في أرض مصر في فتروس قائلين '),
(18352, 'Jeremiah', 24, 44, 16, ' إننا لا نسمع لك الكلمة التي كلمتنا بها باسم الرب '),
(18353, 'Jeremiah', 24, 44, 17, ' بل سنعمل كل أمر خرج من فمنا ، فنبخر لملكة السماوات ، ونسكب لها سكائب . كما فعلنا نحن وآباؤنا وملوكنا ورؤساؤنا في أرض يهوذا وفي شوارع أورشليم ، فشبعنا خبزا وكنا بخير ولم نر شرا '),
(18354, 'Jeremiah', 24, 44, 18, ' ولكن من حين كففنا عن التبخير لملكة السماوات وسكب سكائب لها ، احتجنا إلى كل ، وفنينا بالسيف والجوع '),
(18355, 'Jeremiah', 24, 44, 19, ' وإذ كنا نبخر لملكة السماوات ونسكب لها سكائب ، فهل بدون رجالنا كنا نصنع لها كعكا لنعبدها ونسكب لها السكائب '),
(18356, 'Jeremiah', 24, 44, 20, ' فكلم إرميا كل الشعب ، الرجال والنساء وكل الشعب الذين جاوبوه بهذا الكلام قائلا '),
(18357, 'Jeremiah', 24, 44, 21, ' أليس البخور الذي بخرتموه في مدن يهوذا وفي شوارع أورشليم ، أنتم وآباؤكم وملوككم ورؤساؤكم وشعب الأرض ، هو الذي ذكره الرب وصعد على قلبه '),
(18358, 'Jeremiah', 24, 44, 22, ' ولم يستطع الرب أن يحتمل بعد من أجل شر أعمالكم ، من أجل الرجاسات التي فعلتم ، فصارت أرضكم خربة ودهشا ولعنة بلا ساكن كهذا اليوم '),
(18359, 'Jeremiah', 24, 44, 23, ' من أجل أنكم قد بخرتم وأخطأتم إلى الرب ، ولم تسمعوا لصوت الرب ، ولم تسلكوا في شريعته وفرائضه وشهاداته من أجل ذلكم قد أصابكم هذا الشر كهذا اليوم '),
(18360, 'Jeremiah', 24, 44, 24, ' ثم قال إرميا لكل الشعب ولكل النساء : اسمعوا كلمة الرب يا جميع يهوذا الذين في أرض مصر '),
(18361, 'Jeremiah', 24, 44, 25, ' هكذا تكلم رب الجنود إله إسرائيل قائلا : أنتم ونساؤكم تكلمتم بفمكم وأكملتم بأياديكم قائلين : إننا إنما نتمم نذورنا التي نذرناها ، أن نبخر لملكة السماوات ونسكب لها سكائب ، فإنهن يقمن نذوركم ، ويتممن نذوركم '),
(18362, 'Jeremiah', 24, 44, 26, ' لذلك اسمعوا كلمة الرب يا جميع يهوذا الساكنين في أرض مصر : هأنذا قد حلفت باسمي العظيم ، قال الرب ، إن اسمي لن يسمى بعد بفم إنسان ما من يهوذا في كل أرض مصر قائلا : حي السيد الرب '),
(18363, 'Jeremiah', 24, 44, 27, ' هأنذا أسهر عليهم للشر لا للخير ، فيفنى كل رجال يهوذا الذين في أرض مصر بالسيف والجوع حتى يتلاشوا '),
(18364, 'Jeremiah', 24, 44, 28, ' والناجون من السيف يرجعون من أرض مصر إلى أرض يهوذا نفرا قليلا ، فيعلم كل بقية يهوذا الذين أتوا إلى أرض مصر ليتغربوا فيها ، كلمة أينا تقوم '),
(18365, 'Jeremiah', 24, 44, 29, ' وهذه هي العلامة لكم ، يقول الرب ، إني أعاقبكم في هذا الموضع ، لتعلموا أنه لا بد أن يقوم كلامي عليكم للشر '),
(18366, 'Jeremiah', 24, 44, 30, ' هكذا قال الرب : هأنذا أدفع فرعون حفرع ملك مصر ليد أعدائه وليد طالبي نفسه ، كما دفعت صدقيا ملك يهوذا ليد نبوخذراصر ملك بابل عدوه وطالب نفسه '),
(18367, 'Jeremiah', 24, 45, 1, ' الكلمة التي تكلم بها إرميا النبي إلى باروخ بن نيريا عند كتابته هذا الكلام في سفر عن فم إرميا ، في السنة الرابعة ليهوياقيم بن يوشيا ملك يهوذا قائلا '),
(18368, 'Jeremiah', 24, 45, 2, ' هكذا قال الرب إله إسرائيل لك يا باروخ '),
(18369, 'Jeremiah', 24, 45, 3, ' قد قلت : ويل لي لأن الرب قد زاد حزنا على ألمي . قد غشي علي في تنهدي ، ولم أجد راحة '),
(18370, 'Jeremiah', 24, 45, 4, ' هكذا تقول له : هكذا قال الرب : هأنذا أهدم ما بنيته ، وأقتلع ما غرسته ، وكل هذه الأرض '),
(18371, 'Jeremiah', 24, 45, 5, ' وأنت فهل تطلب لنفسك أمورا عظيمة ؟ لا تطلب لأني هأنذا جالب شرا على كل ذي جسد ، يقول الرب ، وأعطيك نفسك غنيمة في كل المواضع التي تسير إليها '),
(18372, 'Jeremiah', 24, 46, 1, ' كلمة الرب التي صارت إلى إرميا النبي عن الأمم '),
(18373, 'Jeremiah', 24, 46, 2, ' عن مصر ، عن جيش فرعون نخو ملك مصر الذي كان على نهر الفرات في كركميش ، الذي ضربه نبوخذراصر ملك بابل في السنة الرابعة ليهوياقيم بن يوشيا ملك يهوذا '),
(18374, 'Jeremiah', 24, 46, 3, ' أعدوا المجن والترس وتقدموا للحرب '),
(18375, 'Jeremiah', 24, 46, 4, ' أسرجوا الخيل ، واصعدوا أيها الفرسان ، وانتصبوا بالخوذ . اصقلوا الرماح . البسوا الدروع '),
(18376, 'Jeremiah', 24, 46, 5, ' لماذا أراهم مرتعبين ومدبرين إلى الوراء ، وقد تحطمت أبطالهم وفروا هاربين ، ولم يلتفتوا ؟ الخوف حواليهم ، يقول الرب '),
(18377, 'Jeremiah', 24, 46, 6, ' الخفيف لا ينوص والبطل لا ينجو . في الشمال بجانب نهر الفرات عثروا وسقطوا '),
(18378, 'Jeremiah', 24, 46, 7, ' من هذا الصاعد كالنيل ، كأنهار تتلاطم أمواهها '),
(18379, 'Jeremiah', 24, 46, 8, ' تصعد مصر كالنيل ، وكأنهار تتلاطم المياه . فيقول : أصعد وأغطي الأرض . أهلك المدينة والساكنين فيها '),
(18380, 'Jeremiah', 24, 46, 9, ' اصعدي أيتها الخيل ، وهيجي أيتها المركبات ، ولتخرج الأبطال : كوش وفوط القابضان المجن ، واللوديون القابضون والمادون القوس '),
(18381, 'Jeremiah', 24, 46, 10, ' فهذا اليوم للسيد رب الجنود يوم نقمة للانتقام من مبغضيه ، فيأكل السيف ويشبع ويرتوي من دمهم . لأن للسيد رب الجنود ذبيحة في أرض الشمال عند نهر الفرات '),
(18382, 'Jeremiah', 24, 46, 11, ' اصعدي إلى جلعاد وخذي بلسانا يا عذراء ، بنت مصر . باطلا تكثرين العقاقير . لا رفادة لك '),
(18383, 'Jeremiah', 24, 46, 12, ' قد سمعت الأمم بخزيك ، وقد ملأ الأرض عويلك ، لأن بطلا يصدم بطلا فيسقطان كلاهما معا '),
(18384, 'Jeremiah', 24, 46, 13, ' الكلمة التي تكلم بها الرب إلى إرميا النبي في مجيء نبوخذراصر ملك بابل ليضرب أرض مصر '),
(18385, 'Jeremiah', 24, 46, 14, ' أخبروا في مصر ، وأسمعوا في مجدل ، وأسمعوا في نوف وفي تحفنحيس . قولوا انتصب وتهيأ ، لأن السيف يأكل حواليك '),
(18386, 'Jeremiah', 24, 46, 15, ' لماذا انطرح مقتدروك ؟ لا يقفون ، لأن الرب قد طرحهم '),
(18387, 'Jeremiah', 24, 46, 16, ' كثر العاثرين حتى يسقط الواحد على صاحبه ، ويقولوا : قوموا فنرجع إلى شعبنا ، وإلى أرض ميلادنا من وجه السيف الصارم '),
(18388, 'Jeremiah', 24, 46, 17, ' قد نادوا هناك : فرعون ملك مصر هالك . قد فات الميعاد '),
(18389, 'Jeremiah', 24, 46, 18, ' حي أنا ، يقول الملك رب الجنود اسمه ، كتابور بين الجبال ، وككرمل عند البحر يأتي '),
(18390, 'Jeremiah', 24, 46, 19, ' اصنعي لنفسك أهبة جلاء أيتها البنت الساكنة مصر ، لأن نوف تصير خربة وتحرق فلا ساكن '),
(18391, 'Jeremiah', 24, 46, 20, ' مصر عجلة حسنة جدا . الهلاك من الشمال جاء جاء '),
(18392, 'Jeremiah', 24, 46, 21, ' أيضا مستأجروها في وسطها كعجول صيرة . لأنهم هم أيضا يرتدون ، يهربون معا . لم يقفوا لأن يوم هلاكهم أتى عليهم ، وقت عقابهم '),
(18393, 'Jeremiah', 24, 46, 22, ' صوتها يمشي كحية ، لأنهم يسيرون بجيش ، وقد جاءوا إليها بالفؤوس كمحتطبي حطب '),
(18394, 'Jeremiah', 24, 46, 23, ' يقطعون وعرها ، يقول الرب ، وإن يكن لا يحصى ، لأنهم قد كثروا أكثر من الجراد ، ولا عدد لهم '),
(18395, 'Jeremiah', 24, 46, 24, ' قد أخزيت بنت مصر ودفعت ليد شعب الشمال '),
(18396, 'Jeremiah', 24, 46, 25, ' قال رب الجنود إله إسرائيل : هأنذا أعاقب أمون نو وفرعون ومصر وآلهتها وملوكها ، فرعون والمتوكلين عليه '),
(18397, 'Jeremiah', 24, 46, 26, ' وأدفعهم ليد طالبي نفوسهم ، وليد نبوخذراصر ملك بابل ، وليد عبيده . ثم بعد ذلك تسكن كالأيام القديمة ، يقول الرب '),
(18398, 'Jeremiah', 24, 46, 27, ' وأنت فلا تخف يا عبدي يعقوب ، ولا ترتعب يا إسرائيل ، لأني هأنذا أخلصك من بعيد ، ونسلك من أرض سبيهم ، فيرجع يعقوب ويطمئن ويستريح ولا مخيف '),
(18399, 'Jeremiah', 24, 46, 28, ' أما أنت يا عبدي يعقوب فلا تخف ، لأني أنا معك ، لأني أفني كل الأمم الذين بددتك إليهم . أما أنت فلا أفنيك ، بل أؤدبك بالحق ولا أبرئك تبرئة '),
(18400, 'Jeremiah', 24, 47, 1, ' كلمة الرب التي صارت إلى إرميا النبي عن الفلسطينيين قبل ضرب فرعون غزة '),
(18401, 'Jeremiah', 24, 47, 2, ' هكذا قال الرب : ها مياه تصعد من الشمال وتكون سيلا جارفا ، فتغشي الأرض وملأها ، المدينة والساكنين فيها ، فيصرخ الناس ، ويولول كل سكان الأرض '),
(18402, 'Jeremiah', 24, 47, 3, ' من صوت قرع حوافر أقويائه ، من صرير مركباته وصريف بكراته لا تلتفت الآباء إلى البنين ، بسبب ارتخاء الأيادي '),
(18403, 'Jeremiah', 24, 47, 4, ' بسبب اليوم الآتي لهلاك كل الفلسطينيين ، لينقرض من صور وصيدون كل بقية تعين ، لأن الرب يهلك الفلسطينيين ، بقية جزيرة كفتور '),
(18404, 'Jeremiah', 24, 47, 5, ' أتى الصلع على غزة . أهلكت أشقلون مع بقية وطائهم . حتى متى تخمشين نفسك '),
(18405, 'Jeremiah', 24, 47, 6, ' آه ، يا سيف الرب ، حتى متى لا تستريح ؟ انضم إلى غمدك اهدأ واسكن '),
(18406, 'Jeremiah', 24, 47, 7, ' كيف يستريح والرب قد أوصاه على أشقلون ، وعلى ساحل البحر هناك واعده '),
(18407, 'Jeremiah', 24, 48, 1, ' عن موآب : هكذا قال رب الجنود إله إسرائيل : ويل لنبو لأنها قد خربت . خزيت وأخذت قريتايم . خزيت مسجاب وارتعبت '),
(18408, 'Jeremiah', 24, 48, 2, ' ليس موجودا بعد فخر موآب . في حشبون فكروا عليها شرا . هلم فنقرضها من أن تكون أمة . وأنت أيضا يا مدمين تصمين ويذهب وراءك السيف '),
(18409, 'Jeremiah', 24, 48, 3, ' صوت صياح من حورونايم ، هلاك وسحق عظيم '),
(18410, 'Jeremiah', 24, 48, 4, ' قد حطمت موآب ، وأسمع صغارها صراخا '),
(18411, 'Jeremiah', 24, 48, 5, ' لأنه في عقبة لوحيت يصعد بكاء على بكاء ، لأنه في منحدر حورونايم سمع الأعداء صراخ انكسار '),
(18412, 'Jeremiah', 24, 48, 6, ' اهربوا نجوا أنفسكم ، وكونوا كعرعر في البرية '),
(18413, 'Jeremiah', 24, 48, 7, ' فمن أجل اتكالك على أعمالك وعلى خزائنك ستؤخذين أنت أيضا ، ويخرج كموش إلى السبي ، كهنته ورؤساؤه معا '),
(18414, 'Jeremiah', 24, 48, 8, ' ويأتي المهلك إلى كل مدينة ، فلا تفلت مدينة ، فيبيد الوطاء ، ويهلك السهل كما قال الرب '),
(18415, 'Jeremiah', 24, 48, 9, ' أعطوا موآب جناحا لأنها تخرج طائرة وتصير مدنها خربة بلا ساكن فيها '),
(18416, 'Jeremiah', 24, 48, 10, ' ملعون من يعمل عمل الرب برخاء ، وملعون من يمنع سيفه عن الدم '),
(18417, 'Jeremiah', 24, 48, 11, ' مستريح موآب منذ صباه ، وهو مستقر على درديه ، ولم يفرغ من إناء إلى إناء ، ولم يذهب إلى السبي . لذلك بقي طعمه فيه ، ورائحته لم تتغير '),
(18418, 'Jeremiah', 24, 48, 12, ' لذلك ها أيام تأتي ، يقول الرب ، وأرسل إليه مصغين فيصغونه ، ويفرغون آنيته ، ويكسرون أوعيتهم '),
(18419, 'Jeremiah', 24, 48, 13, ' فيخجل موآب من كموش ، كما خجل بيت إسرائيل من بيت إيل متكلهم '),
(18420, 'Jeremiah', 24, 48, 14, ' كيف تقولون نحن جبابرة ورجال قوة للحرب '),
(18421, 'Jeremiah', 24, 48, 15, ' أهلكت موآب وصعدت مدنها ، وخيار منتخبيها نزلوا للقتل ، يقول الملك رب الجنود اسمه '),
(18422, 'Jeremiah', 24, 48, 16, ' قريب مجيء هلاك موآب ، وبليتها مسرعة جدا '),
(18423, 'Jeremiah', 24, 48, 17, ' اندبوها يا جميع الذين حواليها ، وكل العارفين اسمها قولوا : كيف انكسر قضيب العز ، عصا الجلال '),
(18424, 'Jeremiah', 24, 48, 18, ' انزلي من المجد ، اجلسي في الظماء أيتها الساكنة بنت ديبون ، لأن مهلك موآب قد صعد إليك وأهلك حصونك '),
(18425, 'Jeremiah', 24, 48, 19, ' قفي على الطريق وتطلعي يا ساكنة عروعير . اسألي الهارب والناجية . قولي : ماذا حدث '),
(18426, 'Jeremiah', 24, 48, 20, ' قد خزي موآب لأنه قد نقض . ولولوا واصرخوا . أخبروا في أرنون أن موآب قد أهلك '),
(18427, 'Jeremiah', 24, 48, 21, ' وقد جاء القضاء على أرض السهل ، على حولون وعلى يهصة وعلى ميفعة '),
(18428, 'Jeremiah', 24, 48, 22, ' وعلى ديبون وعلى نبو وعلى بيت دبلتايم '),
(18429, 'Jeremiah', 24, 48, 23, ' وعلى قريتايم وعلى بيت جامول وعلى بيت معون '),
(18430, 'Jeremiah', 24, 48, 24, ' وعلى قريوت وعلى بصرة وعلى كل مدن أرض موآب البعيدة والقريبة '),
(18431, 'Jeremiah', 24, 48, 25, ' عضب قرن موآب ، وتحطمت ذراعه ، يقول الرب '),
(18432, 'Jeremiah', 24, 48, 26, ' أسكروه لأنه قد تعاظم على الرب ، فيتمرغ موآب في قيائه ، وهو أيضا يكون ضحكة '),
(18433, 'Jeremiah', 24, 48, 27, ' أفما كان إسرائيل ضحكة لك ؟ هل وجد بين اللصوص حتى أنك كلما كنت تتكلم به كنت تنغض الرأس '),
(18434, 'Jeremiah', 24, 48, 28, ' خلوا المدن ، واسكنوا في الصخر يا سكان موآب ، وكونوا كحمامة تعشش في جوانب فم الحفرة '),
(18435, 'Jeremiah', 24, 48, 29, ' قد سمعنا بكبرياء موآب . هو متكبر جدا . بعظمته وبكبريائه وجلاله وارتفاع قلبه '),
(18436, 'Jeremiah', 24, 48, 30, ' أنا عرفت سخطه ، يقول الرب ، إنه باطل . أكاذيبه فعلت باطلا '),
(18437, 'Jeremiah', 24, 48, 31, ' من أجل ذلك أولول على موآب ، وعلى موآب كله أصرخ . يؤن على رجال قير حارس '),
(18438, 'Jeremiah', 24, 48, 32, ' أبكي عليك بكاء يعزير ، يا جفنة سبمة . قد عبرت قضبانك البحر ، وصلت إلى بحر يعزير . وقع المهلك على جناك ، وعلى قطافك '),
(18439, 'Jeremiah', 24, 48, 33, ' ونزع الفرح والطرب من البستان ، ومن أرض موآب . وقد أبطلت الخمر من المعاصر . لا يداس بهتاف . جلبة لا هتاف '),
(18440, 'Jeremiah', 24, 48, 34, ' قد أطلقوا صوتهم من صراخ حشبون إلى ألعالة إلى ياهص ، من صوغر إلى حورونايم ، كعجلة ثلاثية ، لأن مياه نمريم أيضا تصير خربة '),
(18441, 'Jeremiah', 24, 48, 35, ' وأبطل من موآب ، يقول الرب ، من يصعد في مرتفعة ، ومن يبخر لآلهته '),
(18442, 'Jeremiah', 24, 48, 36, ' من أجل ذلك يصوت قلبي لموآب كناي ، ويصوت قلبي لرجال قير حارس كناي ، لأن الثروة التي اكتسبوها قد بادت '),
(18443, 'Jeremiah', 24, 48, 37, ' لأن كل رأس أقرع ، وكل لحية مجزوزة ، وعلى كل الأيادي خموش ، وعلى الأحقاء مسوح '),
(18444, 'Jeremiah', 24, 48, 38, ' على كل سطوح موآب وفي شوارعها كلها نوح ، لأني قد حطمت موآب كإناء لا مسرة به ، يقول الرب '),
(18445, 'Jeremiah', 24, 48, 39, ' يولولون قائلين : كيف نقضت ؟ كيف حولت موآب قفاها بخزي ؟ فقد صارت موآب ضحكة ورعبا لكل من حواليها '),
(18446, 'Jeremiah', 24, 48, 40, ' لأنه هكذا قال الرب : ها هو يطير كنسر ، ويبسط جناحيه على موآب '),
(18447, 'Jeremiah', 24, 48, 41, ' قد أخذت قريوت ، وأمسكت الحصينات ، وسيكون قلب جبابرة موآب في ذلك اليوم كقلب امرأة ماخض '),
(18448, 'Jeremiah', 24, 48, 42, ' ويهلك موآب عن أن يكون شعبا ، لأنه قد تعاظم على الرب '),
(18449, 'Jeremiah', 24, 48, 43, ' خوف وحفرة وفخ عليك يا ساكن موآب ، يقول الرب '),
(18450, 'Jeremiah', 24, 48, 44, ' الذي يهرب من وجه الخوف يسقط في الحفرة ، والذي يصعد من الحفرة يعلق في الفخ ، لأني أجلب عليها ، أي على موآب ، سنة عقابهم ، يقول الرب '),
(18451, 'Jeremiah', 24, 48, 45, ' في ظل حشبون وقف الهاربون بلا قوة ، لأنه قد خرجت نار من حشبون ، ولهيب من وسط سيحون ، فأكلت زاوية موآب ، وهامة بني الوغى '),
(18452, 'Jeremiah', 24, 48, 46, ' ويل لك يا موآب باد شعب كموش ، لأن بنيك قد أخذوا إلى السبي وبناتك إلى الجلاء '),
(18453, 'Jeremiah', 24, 48, 47, ' ولكنني أرد سبي موآب في آخر الأيام ، يقول الرب . إلى هنا قضاء موآب '),
(18454, 'Jeremiah', 24, 49, 1, ' عن بني عمون : هكذا قال الرب : أليس لإسرائيل بنون ، أو لا وارث له ؟ لماذا يرث ملكهم جاد ، وشعبه يسكن في مدنه '),
(18455, 'Jeremiah', 24, 49, 2, ' لذلك ها أيام تأتي ، يقول الرب ، وأسمع في ربة بني عمون جلبة حرب ، وتصير تلا خربا ، وتحرق بناتها بالنار ، فيرث إسرائيل الذين ورثوه ، يقول الرب '),
(18456, 'Jeremiah', 24, 49, 3, ' ولولي يا حشبون لأن عاي قد خربت . اصرخن يا بنات ربة . تنطقن بمسوح . اندبن وطوفن بين الجدران ، لأن ملكهم يذهب إلى السبي هو وكهنته ورؤساؤه معا '),
(18457, 'Jeremiah', 24, 49, 4, ' ما بالك تفتخرين بالأوطية ؟ قد فاض وطاؤك دما أيتها البنت المرتدة والمتوكلة على خزائنها ، قائلة : من يأتي إلي '),
(18458, 'Jeremiah', 24, 49, 5, ' هأنذا أجلب عليك خوفا ، يقول السيد رب الجنود ، من جميع الذين حواليك ، وتطردون كل واحد إلى ما أمامه ، وليس من يجمع التائهين '),
(18459, 'Jeremiah', 24, 49, 6, ' ثم بعد ذلك أرد سبي بني عمون ، يقول الرب '),
(18460, 'Jeremiah', 24, 49, 7, ' عن أدوم : هكذا قال رب الجنود : ألا حكمة بعد في تيمان ؟ هل بادت المشورة من الفهماء ؟ هل فرغت حكمتهم '),
(18461, 'Jeremiah', 24, 49, 8, ' اهربوا . التفتوا . تعمقوا في السكن يا سكان ددان ، لأني قد جلبت عليه بلية عيسو حين عاقبته '),
(18462, 'Jeremiah', 24, 49, 9, ' لو أتاك القاطفون ، أفما كانوا يتركون علالة ؟ أو اللصوص ليلا ، أفما كانوا يهلكون ما يكفيهم '),
(18463, 'Jeremiah', 24, 49, 10, ' ولكنني جردت عيسو ، وكشفت مستتراته فلا يستطيع أن يختبئ . هلك نسله وإخوته وجيرانه ، فلا يوجد '),
(18464, 'Jeremiah', 24, 49, 11, ' اترك أيتامك أنا أحييهم ، وأراملك علي ليتوكلن '),
(18465, 'Jeremiah', 24, 49, 12, ' لأنه هكذا قال الرب : ها إن الذين لا حق لهم أن يشربوا الكأس قد شربوا ، فهل أنت تتبرأ تبرؤا ؟ لا تتبرأ بل إنما تشرب شربا '),
(18466, 'Jeremiah', 24, 49, 13, ' لأني بذاتي حلفت ، يقول الرب ، إن بصرة تكون دهشا وعارا وخرابا ولعنة ، وكل مدنها تكون خربا أبدية '),
(18467, 'Jeremiah', 24, 49, 14, ' قد سمعت خبرا من قبل الرب ، وأرسل رسول إلى الأمم قائلا : تجمعوا وتعالوا عليها ، وقوموا للحرب '),
(18468, 'Jeremiah', 24, 49, 15, ' لأني ها قد جعلتك صغيرا بين الشعوب ، ومحتقرا بين الناس '),
(18469, 'Jeremiah', 24, 49, 16, ' قد غرك تخويفك ، كبرياء قلبك ، يا ساكن في محاجئ الصخر ، الماسك مرتفع الأكمة . وإن رفعت كنسر عشك ، فمن هناك أحدرك ، يقول الرب '),
(18470, 'Jeremiah', 24, 49, 17, ' وتصير أدوم عجبا . كل مار بها يتعجب ويصفر بسبب كل ضرباتها '),
(18471, 'Jeremiah', 24, 49, 18, ' كانقلاب سدوم وعمورة ومجاوراتهما ، يقول الرب ، لا يسكن هناك إنسان ولا يتغرب فيها ابن آدم '),
(18472, 'Jeremiah', 24, 49, 19, ' هوذا يصعد كأسد من كبرياء الأردن إلى مرعى دائم . لأني أغمز وأجعله يركض عنه . فمن هو منتخب ، فأقيمه عليه ؟ لأنه من مثلي ؟ ومن يحاكمني ؟ ومن هو الراعي الذي يقف أمامي '),
(18473, 'Jeremiah', 24, 49, 20, ' لذلك اسمعوا مشورة الرب التي قضى بها على أدوم ، وأفكاره التي افتكر بها على سكان تيمان : إن صغار الغنم تسحبهم . إنه يخرب مسكنهم عليهم '),
(18474, 'Jeremiah', 24, 49, 21, ' من صوت سقوطهم رجفت الأرض . صرخة سمع صوتها في بحر سوف ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(18475, 'Jeremiah', 24, 49, 22, ' هوذا كنسر يرتفع ويطير ويبسط جناحيه على بصرة ، ويكون قلب جبابرة أدوم في ذلك اليوم كقلب امرأة ماخض '),
(18476, 'Jeremiah', 24, 49, 23, ' عن دمشق : خزيت حماة وأرفاد . قد ذابوا لأنهم قد سمعوا خبرا رديئا . في البحر اضطراب لا يستطيع الهدوء '),
(18477, 'Jeremiah', 24, 49, 24, ' ارتخت دمشق والتفتت للهرب . أمسكتها الرعدة ، وأخذها الضيق والأوجاع كماخض '),
(18478, 'Jeremiah', 24, 49, 25, ' كيف لم تترك المدينة الشهيرة ، قرية فرحي '),
(18479, 'Jeremiah', 24, 49, 26, ' لذلك تسقط شبانها في شوارعها ، وتهلك كل رجال الحرب في ذلك اليوم ، يقول رب الجنود '),
(18480, 'Jeremiah', 24, 49, 27, ' وأشعل نارا في سور دمشق فتأكل قصور بنهدد '),
(18481, 'Jeremiah', 24, 49, 28, ' عن قيدار وعن ممالك حاصور التي ضربها نبوخذراصر ملك بابل : هكذا قال الرب : قوموا اصعدوا إلى قيدار . اخربوا بني المشرق '),
(18482, 'Jeremiah', 24, 49, 29, ' يأخذون خيامهم وغنمهم ، ويأخذون لأنفسهم شققهم وكل آنيتهم وجمالهم ، وينادون إليهم : الخوف من كل جانب '),
(18483, 'Jeremiah', 24, 49, 30, ' اهربوا . انهزموا جدا . تعمقوا في السكن يا سكان حاصور ، يقول الرب ، لأن نبوخذراصر ملك بابل قد أشار عليكم مشورة ، وفكر عليكم فكرا '),
(18484, 'Jeremiah', 24, 49, 31, ' قوموا اصعدوا إلى أمة مطمئنة ساكنة آمنة ، يقول الرب ، لا مصاريع ولا عوارض لها . تسكن وحدها '),
(18485, 'Jeremiah', 24, 49, 32, ' وتكون جمالهم نهبا ، وكثرة ماشيتهم غنيمة ، وأذري لكل ريح مقصوصي الشعر مستديرا ، وآتي بهلاكهم من كل جهاته ، يقول الرب '),
(18486, 'Jeremiah', 24, 49, 33, ' وتكون حاصور مسكن بنات آوى ، وخربة إلى الأبد . لا يسكن هناك إنسان ، ولا يتغرب فيها ابن آدم '),
(18487, 'Jeremiah', 24, 49, 34, ' كلمة الرب التي صارت إلى إرميا النبي على عيلام ، في ابتداء ملك صدقيا ملك يهوذا قائلة '),
(18488, 'Jeremiah', 24, 49, 35, ' هكذا قال رب الجنود : هأنذا أحطم قوس عيلام أول قوتهم '),
(18489, 'Jeremiah', 24, 49, 36, ' وأجلب على عيلام أربع رياح من أربعة أطراف السماء ، وأذريهم لكل هذه الرياح ولا تكون أمة إلا ويأتي إليها منفيو عيلام '),
(18490, 'Jeremiah', 24, 49, 37, ' وأجعل العيلاميين يرتعبون أمام أعدائهم وأمام طالبي نفوسهم ، وأجلب عليهم شرا ، حمو غضبي ، يقول الرب . وأرسل وراءهم السيف حتى أفنيهم '),
(18491, 'Jeremiah', 24, 49, 38, ' وأضع كرسيي في عيلام ، وأبيد من هناك الملك والرؤساء ، يقول الرب '),
(18492, 'Jeremiah', 24, 49, 39, ' ويكون في آخر الأيام أني أرد سبي عيلام ، يقول الرب '),
(18493, 'Jeremiah', 24, 50, 1, ' الكلمة التي تكلم بها الرب عن بابل وعن أرض الكلدانيين على يد إرميا النبي '),
(18494, 'Jeremiah', 24, 50, 2, ' أخبروا في الشعوب ، وأسمعوا وارفعوا راية . أسمعوا لا تخفوا . قولوا : أخذت بابل . خزي بيل . انسحق مرودخ . خزيت أوثانها . انسحقت أصنامها '),
(18495, 'Jeremiah', 24, 50, 3, ' لأنه قد طلعت عليها أمة من الشمال هي تجعل أرضها خربة فلا يكون فيها ساكن . من إنسان إلى حيوان هربوا وذهبوا '),
(18496, 'Jeremiah', 24, 50, 4, ' في تلك الأيام وفي ذلك الزمان ، يقول الرب ، يأتي بنو إسرائيل هم وبنو يهوذا معا . يسيرون سيرا ، ويبكون ويطلبون الرب إلههم '),
(18497, 'Jeremiah', 24, 50, 5, ' يسألون عن طريق صهيون ، ووجوههم إلى هناك ، قائلين : هلم فنلصق بالرب بعهد أبدي لا ينسى '),
(18498, 'Jeremiah', 24, 50, 6, ' كان شعبي خرافا ضالة ، قد أضلتهم رعاتهم . على الجبال أتاهوهم . ساروا من جبل إلى أكمة . نسوا مربضهم '),
(18499, 'Jeremiah', 24, 50, 7, ' كل الذين وجدوهم أكلوهم ، وقال مبغضوهم : لا نذنب من أجل أنهم أخطأوا إلى الرب ، مسكن البر ورجاء آبائهم الرب '),
(18500, 'Jeremiah', 24, 50, 8, ' اهربوا من وسط بابل واخرجوا من أرض الكلدانيين ، وكونوا مثل كراريز أمام الغنم '),
(18501, 'Jeremiah', 24, 50, 9, ' لأني هأنذا أوقظ وأصعد على بابل جمهور شعوب عظيمة من أرض الشمال ، فيصطفون عليها . من هناك تؤخذ . نبالهم كبطل مهلك لا يرجع فارغا '),
(18502, 'Jeremiah', 24, 50, 10, ' وتكون أرض الكلدانيين غنيمة . كل مغتنميها يشبعون ، يقول الرب '),
(18503, 'Jeremiah', 24, 50, 11, ' لأنكم قد فرحتم وشمتم يا ناهبي ميراثي ، وقفزتم كعجلة في الكلإ ، وصهلتم كخيل '),
(18504, 'Jeremiah', 24, 50, 12, ' تخزى أمكم جدا . تخجل التي ولدتكم . ها آخرة الشعوب برية وأرض ناشفة وقفر '),
(18505, 'Jeremiah', 24, 50, 13, ' بسبب سخط الرب لا تسكن ، بل تصير خربة بالتمام . كل مار ببابل يتعجب ويصفر بسبب كل ضرباتها '),
(18506, 'Jeremiah', 24, 50, 14, ' اصطفوا على بابل حواليها يا جميع الذين ينزعون في القوس . ارموا عليها . لا توفروا السهام لأنها قد أخطأت إلى الرب '),
(18507, 'Jeremiah', 24, 50, 15, ' اهتفوا عليها حواليها . قد أعطت يدها . سقطت أسسها . نقضت أسوارها . لأنها نقمة الرب هي ، فانقموا منها . كما فعلت افعلوا بها '),
(18508, 'Jeremiah', 24, 50, 16, ' اقطعوا الزارع من بابل ، وماسك المنجل في وقت الحصاد . من وجه السيف القاسي يرجعون كل واحد إلى شعبه ، ويهربون كل واحد إلى أرضه '),
(18509, 'Jeremiah', 24, 50, 17, ' إسرائيل غنم متبددة . قد طردته السباع . أولا أكله ملك أشور ، ثم هذا الأخير ، نبوخذراصر ملك بابل هرس عظامه '),
(18510, 'Jeremiah', 24, 50, 18, ' لذلك هكذا قال رب الجنود إله إسرائيل : هأنذا أعاقب ملك بابل وأرضه كما عاقبت ملك أشور '),
(18511, 'Jeremiah', 24, 50, 19, ' وأرد إسرائيل إلى مسكنه ، فيرعى كرمل وباشان ، وفي جبل أفرايم وجلعاد تشبع نفسه '),
(18512, 'Jeremiah', 24, 50, 20, ' في تلك الأيام وفي ذلك الزمان ، يقول الرب ، يطلب إثم إسرائيل فلا يكون ، وخطية يهوذا فلا توجد ، لأني أغفر لمن أبقيه '),
(18513, 'Jeremiah', 24, 50, 21, ' اصعد على أرض مراثايم . عليها وعلى سكان فقود . اخرب وحرم وراءهم ، يقول الرب ، وافعل حسب كل ما أمرتك به '),
(18514, 'Jeremiah', 24, 50, 22, ' صوت حرب في الأرض ، وانحطام عظيم '),
(18515, 'Jeremiah', 24, 50, 23, ' كيف قطعت وتحطمت مطرقة كل الأرض ؟ كيف صارت بابل خربة بين الشعوب '),
(18516, 'Jeremiah', 24, 50, 24, ' قد نصبت لك شركا ، فعلقت يا بابل ، وأنت لم تعرفي قد وجدت وأمسكت لأنك قد خاصمت الرب '),
(18517, 'Jeremiah', 24, 50, 25, ' فتح الرب خزانته ، وأخرج آلات رجزه ، لأن للسيد رب الجنود عملا في أرض الكلدانيين '),
(18518, 'Jeremiah', 24, 50, 26, ' هلم إليها من الأقصى . افتحوا أهراءها . كوموها عراما ، وحرموها ولا تكن لها بقية '),
(18519, 'Jeremiah', 24, 50, 27, ' أهلكوا كل عجولها . لتنزل للذبح . ويل لهم لأنه قد أتى يومهم ، زمان عقابهم '),
(18520, 'Jeremiah', 24, 50, 28, ' صوت هاربين وناجين من أرض بابل ، ليخبروا في صهيون بنقمة الرب إلهنا ، نقمة هيكله '),
(18521, 'Jeremiah', 24, 50, 29, ' ادعوا إلى بابل أصحاب القسي . لينزل عليها كل من ينزع في القوس حواليها . لا يكن ناج . كافئوها نظير عملها . افعلوا بها حسب كل ما فعلت ، لأنها بغت على الرب ، على قدوس إسرائيل '),
(18522, 'Jeremiah', 24, 50, 30, ' لذلك يسقط شبانها في الشوارع ، وكل رجال حربها يهلكون في ذلك اليوم ، يقول الرب '),
(18523, 'Jeremiah', 24, 50, 31, ' هأنذا عليك أيتها الباغية ، يقول السيد رب الجنود ، لأنه قد أتى يومك حين عقابي إياك '),
(18524, 'Jeremiah', 24, 50, 32, ' فيعثر الباغي ويسقط ولا يكون له من يقيمه ، وأشعل نارا في مدنه فتأكل كل ما حواليها '),
(18525, 'Jeremiah', 24, 50, 33, ' هكذا قال رب الجنود : إن بني إسرائيل وبني يهوذا معا مظلومون ، وكل الذين سبوهم أمسكوهم . أبوا أن يطلقوهم '),
(18526, 'Jeremiah', 24, 50, 34, ' وليهم قوي . رب الجنود اسمه . يقيم دعواهم لكي يريح الأرض ويزعج سكان بابل '),
(18527, 'Jeremiah', 24, 50, 35, ' سيف على الكلدانيين ، يقول الرب ، وعلى سكان بابل ، وعلى رؤسائها ، وعلى حكمائها '),
(18528, 'Jeremiah', 24, 50, 36, ' سيف على المخادعين ، فيصيرون حمقا . سيف على أبطالها فيرتعبون '),
(18529, 'Jeremiah', 24, 50, 37, ' سيف على خيلها وعلى مركباتها وعلى كل اللفيف الذي في وسطها ، فيصيرون نساء . سيف على خزائنها فتنهب '),
(18530, 'Jeremiah', 24, 50, 38, ' حر على مياهها فتنشف ، لأنها أرض منحوتات هي ، وبالأصنام تجن '),
(18531, 'Jeremiah', 24, 50, 39, ' لذلك تسكن وحوش القفر مع بنات آوى ، وتسكن فيها رعال النعام ، ولا تسكن بعد إلى الأبد ، ولا تعمر إلى دور فدور '),
(18532, 'Jeremiah', 24, 50, 40, ' كقلب الله سدوم وعمورة ومجاوراتها ، يقول الرب ، لا يسكن هناك إنسان ، ولا يتغرب فيها ابن آدم '),
(18533, 'Jeremiah', 24, 50, 41, ' هوذا شعب مقبل من الشمال ، وأمة عظيمة ، ويوقظ ملوك كثيرون من أقاصي الأرض '),
(18534, 'Jeremiah', 24, 50, 42, ' يمسكون القوس والرمح . هم قساة لا يرحمون . صوتهم يعج كبحر ، وعلى خيل يركبون ، مصطفين كرجل واحد لمحاربتك يا بنت بابل '),
(18535, 'Jeremiah', 24, 50, 43, ' سمع ملك بابل خبرهم فارتخت يداه . أخذته الضيقة والوجع كماخض '),
(18536, 'Jeremiah', 24, 50, 44, ' ها هو يصعد كأسد من كبرياء الأردن إلى مرعى دائم . لأني أغمز وأجعلهم يركضون عنه . فمن هو منتخب فأقيمه عليه ؟ لأنه من مثلي ؟ ومن يحاكمني ؟ ومن هو الراعي الذي يقف أمامي '),
(18537, 'Jeremiah', 24, 50, 45, ' لذلك اسمعوا مشورة الرب التي قضى بها على بابل ، وأفكاره التي افتكر بها على أرض الكلدانيين : إن صغار الغنم تسحبهم . إنه يخرب مسكنهم عليهم '),
(18538, 'Jeremiah', 24, 50, 46, ' من القول : أخذت بابل . رجفت الأرض وسمع صراخ في الشعوب '),
(18539, 'Jeremiah', 24, 51, 1, ' هكذا قال الرب : هأنذا أوقظ على بابل وعلى الساكنين في وسط القائمين علي ريحا مهلكة '),
(18540, 'Jeremiah', 24, 51, 2, ' وأرسل إلى بابل مذرين فيذرونها ويفرغون أرضها ، لأنهم يكونون عليها من كل جهة في يوم الشر '),
(18541, 'Jeremiah', 24, 51, 3, ' على النازع في قوسه ، فلينزع النازع ، وعلى المفتخر بدرعه ، فلا تشفقوا على منتخبيها ، بل حرموا كل جندها '),
(18542, 'Jeremiah', 24, 51, 4, ' فتسقط القتلى في أرض الكلدانيين ، والمطعونون في شوارعها '),
(18543, 'Jeremiah', 24, 51, 5, ' لأن إسرائيل ويهوذا ليسا بمقطوعين عن إلههما ، عن رب الجنود ، وإن تكن أرضهما ملآنة إثما على قدوس إسرائيل '),
(18544, 'Jeremiah', 24, 51, 6, ' اهربوا من وسط بابل ، وانجوا كل واحد بنفسه . لا تهلكوا بذنبها ، لأن هذا زمان انتقام الرب ، هو يؤدي لها جزاءها '),
(18545, 'Jeremiah', 24, 51, 7, ' بابل كأس ذهب بيد الرب تسكر كل الأرض . من خمرها شربت الشعوب . من أجل ذلك جنت الشعوب '),
(18546, 'Jeremiah', 24, 51, 8, ' سقطت بابل بغتة وتحطمت . ولولوا عليها . خذوا بلسانا لجرحها لعلها تشفى '),
(18547, 'Jeremiah', 24, 51, 9, ' داوينا بابل فلم تشف . دعوها ، ولنذهب كل واحد إلى أرضه ، لأن قضاءها وصل إلى السماء ، وارتفع إلى السحاب '),
(18548, 'Jeremiah', 24, 51, 10, ' قد أخرج الرب برنا . هلم فنقص في صهيون عمل الرب إلهنا '),
(18549, 'Jeremiah', 24, 51, 11, ' سنوا السهام . أعدوا الأتراس . قد أيقظ الرب روح ملوك مادي ، لأن قصده على بابل أن يهلكها . لأنه نقمة الرب ، نقمة هيكله '),
(18550, 'Jeremiah', 24, 51, 12, ' على أسوار بابل ارفعوا الراية . شددوا الحراسة . أقيموا الحراس . أعدوا الكمين ، لأن الرب قد قصد وأيضا فعل ما تكلم به على سكان بابل '),
(18551, 'Jeremiah', 24, 51, 13, ' أيتها الساكنة على مياه كثيرة ، الوافرة الخزائن ، قد أتت آخرتك ، كيل اغتصابك '),
(18552, 'Jeremiah', 24, 51, 14, ' قد حلف رب الجنود بنفسه : إني لأملأنك أناسا كالغوغاء ، فيرفعون عليك جلبة '),
(18553, 'Jeremiah', 24, 51, 15, ' صانع الأرض بقوته ، ومؤسس المسكونة بحكمته ، وبفهمه مد السماوات '),
(18554, 'Jeremiah', 24, 51, 16, ' إذا أعطى قولا تكون كثرة مياه في السماوات ، ويصعد السحاب من أقاصي الأرض . صنع بروقا للمطر ، وأخرج الريح من خزائنه '),
(18555, 'Jeremiah', 24, 51, 17, ' بلد كل إنسان بمعرفته . خزي كل صائغ من التمثال لأن مسبوكه كذب ولا روح فيه '),
(18556, 'Jeremiah', 24, 51, 18, ' هي باطلة ، صنعة الأضاليل . في وقت عقابها تبيد '),
(18557, 'Jeremiah', 24, 51, 19, ' ليس كهذه نصيب يعقوب ، لأنه مصور الجميع ، وقضيب ميراثه ، رب الجنود اسمه '),
(18558, 'Jeremiah', 24, 51, 20, ' أنت لي فأس وأدوات حرب ، فأسحق بك الأمم ، وأهلك بك الممالك '),
(18559, 'Jeremiah', 24, 51, 21, ' وأكسر بك الفرس وراكبه ، وأسحق بك المركبة وراكبها '),
(18560, 'Jeremiah', 24, 51, 22, ' وأسحق بك الرجل والمرأة ، وأسحق بك الشيخ والفتى ، وأسحق بك الغلام والعذراء '),
(18561, 'Jeremiah', 24, 51, 23, ' وأسحق بك الراعي وقطيعه ، وأسحق بك الفلاح وفدانه ، وأسحق بك الولاة والحكام '),
(18562, 'Jeremiah', 24, 51, 24, ' وأكافئ بابل وكل سكان أرض الكلدانيين على كل شرهم الذي فعلوه في صهيون ، أمام عيونكم ، يقول الرب '),
(18563, 'Jeremiah', 24, 51, 25, ' هأنذا عليك أيها الجبل المهلك ، يقول الرب ، المهلك كل الأرض ، فأمد يدي عليك وأدحرجك عن الصخور ، وأجعلك جبلا محرقا '),
(18564, 'Jeremiah', 24, 51, 26, ' فلا يأخذون منك حجرا لزاوية ، ولا حجرا لأسس ، بل تكون خرابا إلى الأبد ، يقول الرب '),
(18565, 'Jeremiah', 24, 51, 27, ' ارفعوا الراية في الأرض . اضربوا بالبوق في الشعوب . قدسوا عليها الأمم . نادوا عليها ممالك أراراط ومني وأشكناز . أقيموا عليها قائدا . أصعدوا الخيل كغوغاء مقشعرة '),
(18566, 'Jeremiah', 24, 51, 28, ' قدسوا عليها الشعوب ، ملوك مادي ، ولاتها وكل حكامها وكل أرض سلطانها '),
(18567, 'Jeremiah', 24, 51, 29, ' فترتجف الأرض وتتوجع ، لأن أفكار الرب تقوم على بابل ، ليجعل أرض بابل خرابا بلا ساكن '),
(18568, 'Jeremiah', 24, 51, 30, ' كف جبابرة بابل عن الحرب ، وجلسوا في الحصون . نضبت شجاعتهم . صاروا نساء . حرقوا مساكنها . تحطمت عوارضها '),
(18569, 'Jeremiah', 24, 51, 31, ' يركض عداء للقاء عداء ، ومخبر للقاء مخبر ، ليخبر ملك بابل بأن مدينته قد أخذت عن أقصى '),
(18570, 'Jeremiah', 24, 51, 32, ' وأن المعابر قد أمسكت ، والقصب أحرقوه بالنار ، ورجال الحرب اضطربت '),
(18571, 'Jeremiah', 24, 51, 33, ' لأنه هكذا قال رب الجنود إله إسرائيل : إن بنت بابل كبيدر وقت دوسه . بعد قليل يأتي عليها وقت الحصاد '),
(18572, 'Jeremiah', 24, 51, 34, ' أكلني أفناني نبوخذراصر ملك بابل . جعلني إناء فارغا . ابتلعني كتنين ، وملأ جوفه من نعمي . طوحني '),
(18573, 'Jeremiah', 24, 51, 35, ' ظلمي ولحمي على بابل تقول ساكنة صهيون . ودمي على سكان أرض الكلدانيين تقول أورشليم '),
(18574, 'Jeremiah', 24, 51, 36, ' لذلك هكذا قال الرب : هأنذا أخاصم خصومتك ، وأنتقم نقمتك ، وأنشف بحرها ، وأجفف ينبوعها '),
(18575, 'Jeremiah', 24, 51, 37, ' وتكون بابل كوما ، ومأوى بنات آوى ، ودهشا وصفيرا بلا ساكن '),
(18576, 'Jeremiah', 24, 51, 38, ' يزمجرون معا كأشبال . يزأرون كجراء أسود '),
(18577, 'Jeremiah', 24, 51, 39, ' عند حرارتهم أعد لهم شرابا وأسكرهم ، لكي يفرحوا ويناموا نوما أبديا ، ولا يستيقظوا ، يقول الرب '),
(18578, 'Jeremiah', 24, 51, 40, ' أنزلهم كخراف للذبح وككباش مع أعتدة '),
(18579, 'Jeremiah', 24, 51, 41, ' كيف أخذت شيشك ، وأمسكت فخر كل الأرض ؟ كيف صارت بابل دهشا في الشعوب '),
(18580, 'Jeremiah', 24, 51, 42, ' طلع البحر على بابل ، فتغطت بكثرة أمواجه '),
(18581, 'Jeremiah', 24, 51, 43, ' صارت مدنها خرابا ، أرضا ناشفة وقفرا ، أرضا لا يسكن فيها إنسان ولا يعبر فيها ابن آدم '),
(18582, 'Jeremiah', 24, 51, 44, ' وأعاقب بيل في بابل ، وأخرج من فمه ما ابتلعه ، فلا تجري إليه الشعوب بعد ، ويسقط سور بابل أيضا '),
(18583, 'Jeremiah', 24, 51, 45, ' اخرجوا من وسطها يا شعبي ، ولينج كل واحد نفسه من حمو غضب الرب '),
(18584, 'Jeremiah', 24, 51, 46, ' ولا يضعف قلبكم فتخافوا من الخبر الذي سمع في الأرض ، فإنه يأتي خبر في هذه السنة ، ثم بعده في السنة الأخرى ، خبر وظلم في الأرض ، متسلط على متسلط '),
(18585, 'Jeremiah', 24, 51, 47, ' لذلك ها أيام تأتي وأعاقب منحوتات بابل ، فتخزى كل أرضها وتسقط كل قتلاها في وسطها '),
(18586, 'Jeremiah', 24, 51, 48, ' فتهتف على بابل السماوات والأرض وكل ما فيها ، لأن الناهبين يأتون عليها من الشمال ، يقول الرب '),
(18587, 'Jeremiah', 24, 51, 49, ' كما أسقطت بابل قتلى إسرائيل ، تسقط أيضا قتلى بابل في كل الأرض '),
(18588, 'Jeremiah', 24, 51, 50, ' أيها الناجون من السيف اذهبوا . لا تقفوا . اذكروا الرب من بعيد ، ولتخطر أورشليم ببالكم '),
(18589, 'Jeremiah', 24, 51, 51, ' قد خزينا لأننا قد سمعنا عارا . غطى الخجل وجوهنا لأن الغرباء قد دخلوا مقادس بيت الرب '),
(18590, 'Jeremiah', 24, 51, 52, ' لذلك ها أيام تأتي ، يقول الرب ، وأعاقب منحوتاتها ، ويتنهد الجرحى في كل أرضها '),
(18591, 'Jeremiah', 24, 51, 53, ' فلو صعدت بابل إلى السماوات ، ولو حصنت علياء عزها ، فمن عندي يأتي عليها الناهبون ، يقول الرب '),
(18592, 'Jeremiah', 24, 51, 54, ' صوت صراخ من بابل وانحطام عظيم من أرض الكلدانيين '),
(18593, 'Jeremiah', 24, 51, 55, ' لأن الرب مخرب بابل وقد أباد منها الصوت العظيم ، وقد عجت أمواجهم كمياه كثيرة وأطلق ضجيج صوتهم '),
(18594, 'Jeremiah', 24, 51, 56, ' لأنه جاء عليها ، على بابل ، المخرب ، وأخذ جبابرتها ، وتحطمت قسيهم ، لأن الرب إله مجازاة يكافئ مكافأة '),
(18595, 'Jeremiah', 24, 51, 57, ' وأسكر رؤساءها وحكماءها وولاتها وحكامها وأبطالها فينامون نوما أبديا ، ولا يستيقظون ، يقول الملك رب الجنود اسمه '),
(18596, 'Jeremiah', 24, 51, 58, ' هكذا قال رب الجنود : إن أسوار بابل العريضة تدمر تدميرا ، وأبوابها الشامخة تحرق بالنار ، فتتعب الشعوب للباطل ، والقبائل للنار حتى تعيا '),
(18597, 'Jeremiah', 24, 51, 59, ' الأمر الذي أوصى به إرميا النبي سرايا بن نيريا بن محسيا ، عند ذهابه مع صدقيا ملك يهوذا إلى بابل في السنة الرابعة لملكه ، وكان سرايا رئيس المحلة '),
(18598, 'Jeremiah', 24, 51, 60, ' فكتب إرميا كل الشر الآتي على بابل في سفر واحد ، كل هذا الكلام المكتوب على بابل '),
(18599, 'Jeremiah', 24, 51, 61, ' وقال إرميا لسرايا : إذا دخلت إلى بابل ونظرت وقرأت كل هذا الكلام '),
(18600, 'Jeremiah', 24, 51, 62, ' فقل : أنت يارب قد تكلمت على هذا الموضع لتقرضه حتى لا يكون فيه ساكن من الناس إلى البهائم ، بل يكون خربا أبدية '),
(18601, 'Jeremiah', 24, 51, 63, ' ويكون إذا فرغت من قراءة هذا السفر أنك تربط به حجرا وتطرحه إلى وسط الفرات '),
(18602, 'Jeremiah', 24, 51, 64, ' وتقول : هكذا تغرق بابل ولا تقوم ، من الشر الذي أنا جالبه عليها ويعيون . إلى هنا كلام إرميا '),
(18603, 'Jeremiah', 24, 52, 1, ' كان صدقيا ابن إحدى وعشرين سنة حين ملك ، وملك إحدى عشرة سنة في أورشليم ، واسم أمه حميطل بنت إرميا من لبنة '),
(18604, 'Jeremiah', 24, 52, 2, ' وعمل الشر في عيني الرب حسب كل ما عمل يهوياقيم '),
(18605, 'Jeremiah', 24, 52, 3, ' لأنه لأجل غضب الرب على أورشليم ويهوذا حتى طرحهم من أمام وجهه ، كان أن صدقيا تمرد على ملك بابل '),
(18606, 'Jeremiah', 24, 52, 4, ' وفي السنة التاسعة لملكه ، في الشهر العاشر ، في عاشر الشهر ، جاء نبوخذراصر ملك بابل هو وكل جيشه على أورشليم ونزلوا عليها وبنوا عليها أبراجا حواليها '),
(18607, 'Jeremiah', 24, 52, 5, ' فدخلت المدينة في الحصار إلى السنة الحادية عشرة للملك صدقيا '),
(18608, 'Jeremiah', 24, 52, 6, ' في الشهر الرابع ، في تاسع الشهر اشتد الجوع في المدينة ، ولم يكن خبز لشعب الأرض '),
(18609, 'Jeremiah', 24, 52, 7, ' فثغرت المدينة وهرب كل رجال القتال ، وخرجوا من المدينة ليلا في طريق الباب بين السورين اللذين عند جنة الملك ، والكلدانيون عند المدينة حواليها ، فذهبوا في طريق البرية '),
(18610, 'Jeremiah', 24, 52, 8, ' فتبعت جيوش الكلدانيين الملك ، فأدركوا صدقيا في برية أريحا ، وتفرق كل جيشه عنه '),
(18611, 'Jeremiah', 24, 52, 9, ' فأخذوا الملك وأصعدوه إلى ملك بابل إلى ربلة في أرض حماة ، فكلمه بالقضاء عليه '),
(18612, 'Jeremiah', 24, 52, 10, ' فقتل ملك بابل بني صدقيا أمام عينيه ، وقتل أيضا كل رؤساء يهوذا في ربلة '),
(18613, 'Jeremiah', 24, 52, 11, ' وأعمى عيني صدقيا ، وقيده بسلسلتين من نحاس ، وجاء به ملك بابل إلى بابل ، وجعله في السجن إلى يوم وفاته '),
(18614, 'Jeremiah', 24, 52, 12, ' وفي الشهر الخامس ، في عاشر الشهر ، وهي السنة التاسعة عشرة للملك نبوخذراصر ملك بابل ، جاء نبوزرادان رئيس الشرط ، الذي كان يقف أمام ملك بابل إلى أورشليم '),
(18615, 'Jeremiah', 24, 52, 13, ' وأحرق بيت الرب ، وبيت الملك ، وكل بيوت أورشليم ، وكل بيوت العظماء ، أحرقها بالنار '),
(18616, 'Jeremiah', 24, 52, 14, ' وكل أسوار أورشليم مستديرا هدمها كل جيش الكلدانيين الذي مع رئيس الشرط '),
(18617, 'Jeremiah', 24, 52, 15, ' وسبى نبوزرادان ، رئيس الشرط ، بعضا من فقراء الشعب ، وبقية الشعب الذين بقوا في المدينة ، والهاربين الذين سقطوا إلى ملك بابل ، وبقية الجمهور '),
(18618, 'Jeremiah', 24, 52, 16, ' ولكن نبوزرادان ، رئيس الشرط ، أبقى من مساكين الأرض كرامين وفلاحين '),
(18619, 'Jeremiah', 24, 52, 17, ' وكسر الكلدانيون أعمدة النحاس التي لبيت الرب ، والقواعد وبحر النحاس الذي في بيت الرب ، وحملوا كل نحاسها إلى بابل '),
(18620, 'Jeremiah', 24, 52, 18, ' وأخذوا القدور والرفوش والمقاص والمناضح والصحون وكل آنية النحاس التي كانوا يخدمون بها '),
(18621, 'Jeremiah', 24, 52, 19, ' وأخذ رئيس الشرط الطسوس والمجامر والمناضح والقدور والمناير والصحون والأقداح ، ما كان من ذهب فالذهب ، وما كان من فضة فالفضة '),
(18622, 'Jeremiah', 24, 52, 20, ' والعمودين والبحر الواحد ، والاثني عشر ثورا من نحاس التي تحت القواعد ، التي عملها الملك سليمان لبيت الرب . لم يكن وزن لنحاس كل هذه الأدوات '),
(18623, 'Jeremiah', 24, 52, 21, ' أما العمودان فكان طول العمود الواحد ثماني عشرة ذراعا ، وخيط اثنتا عشرة ذراعا يحيط به ، وغلظه أربع أصابع ، وهو أجوف '),
(18624, 'Jeremiah', 24, 52, 22, ' وعليه تاج من نحاس ، ارتفاع التاج الواحد خمس أذرع . وعلى التاج حواليه شبكة ورمانات ، الكل من نحاس . ومثل ذلك للعمود الثاني ، والرمانات '),
(18625, 'Jeremiah', 24, 52, 23, ' وكانت الرمانات ستا وتسعين للجانب . كل الرمانات مئة على الشبكة حواليها '),
(18626, 'Jeremiah', 24, 52, 24, ' وأخذ رئيس الشرط سرايا الكاهن الأول ، وصفنيا الكاهن الثاني وحارسي الباب الثلاثة '),
(18627, 'Jeremiah', 24, 52, 25, ' وأخذ من المدينة خصيا واحدا كان وكيلا على رجال الحرب ، وسبعة رجال من الذين ينظرون وجه الملك ، الذين وجدوا في المدينة ، وكاتب رئيس الجند الذي كان يجمع شعب الأرض للتجند ، وستين رجلا من شعب الأرض ، الذين وجدوا في وسط المدينة '),
(18628, 'Jeremiah', 24, 52, 26, ' أخذهم نبوزرادان رئيس الشرط ، وسار بهم إلى ملك بابل ، إلى ربلة '),
(18629, 'Jeremiah', 24, 52, 27, ' فضربهم ملك بابل وقتلهم في ربلة في أرض حماة . فسبي يهوذا من أرضه '),
(18630, 'Jeremiah', 24, 52, 28, ' هذا هو الشعب الذي سباه نبوخذراصر في السنة السابعة : من اليهود ثلاثة آلاف وثلاثة وعشرون '),
(18631, 'Jeremiah', 24, 52, 29, ' وفي السنة الثامنة عشرة لنبوخذراصر سبي من أورشليم ثمان مئة واثنان وثلاثون نفسا '),
(18632, 'Jeremiah', 24, 52, 30, ' في السنة الثالثة والعشرين لنبوخذراصر ، سبى نبوزرادان رئيس الشرط من اليهود سبع مئة وخمسا وأربعين نفسا . جملة النفوس أربعة آلاف وست مئة '),
(18633, 'Jeremiah', 24, 52, 31, ' وفي السنة السابعة والثلاثين لسبي يهوياكين ، في الشهر الثاني عشر ، في الخامس والعشرين من الشهر ، رفع أويل مرودخ ملك بابل ، في سنة تملكه ، رأس يهوياكين ملك يهوذا ، وأخرجه من السجن '),
(18634, 'Jeremiah', 24, 52, 32, ' وكلمه بخير ، وجعل كرسيه فوق كراسي الملوك الذين معه في بابل '),
(18635, 'Jeremiah', 24, 52, 33, ' وغير ثياب سجنه ، وكان يأكل دائما الخبز أمامه كل أيام حياته '),
(18636, 'Jeremiah', 24, 52, 34, ' ووظيفته وظيفة دائمة تعطى له من عند ملك بابل ، أمر كل يوم بيومه ، إلى يوم وفاته ، كل أيام حياته '),
(18637, 'Job', 18, 1, 1, ' كان رجل في أرض عوص اسمه أيوب . وكان هذا الرجل كاملا ومستقيما ، يتقي الله ويحيد عن الشر '),
(18638, 'Job', 18, 1, 2, ' وولد له سبعة بنين وثلاث بنات '),
(18639, 'Job', 18, 1, 3, ' وكانت مواشيه سبعة آلاف من الغنم ، وثلاثة آلاف جمل ، وخمس مئة فدان بقر ، وخمس مئة أتان ، وخدمه كثيرين جدا . فكان هذا الرجل أعظم كل بني المشرق '),
(18640, 'Job', 18, 1, 4, ' وكان بنوه يذهبون ويعملون وليمة في بيت كل واحد منهم في يومه ، ويرسلون ويستدعون أخواتهم الثلاث ليأكلن ويشربن معهم '),
(18641, 'Job', 18, 1, 5, ' وكان لما دارت أيام الوليمة ، أن أيوب أرسل فقدسهم ، وبكر في الغد وأصعد محرقات على عددهم كلهم ، لأن أيوب قال : ربما أخطأ بني وجدفوا على الله في قلوبهم . هكذا كان أيوب يفعل كل الأيام '),
(18642, 'Job', 18, 1, 6, ' وكان ذات يوم أنه جاء بنو الله ليمثلوا أمام الرب ، وجاء الشيطان أيضا في وسطهم '),
(18643, 'Job', 18, 1, 7, ' فقال الرب للشيطان : من أين جئت ؟  . فأجاب الشيطان الرب وقال : من الجولان في الأرض ، ومن التمشي فيها '),
(18644, 'Job', 18, 1, 8, ' فقال الرب للشيطان : هل جعلت قلبك على عبدي أيوب ؟ لأنه ليس مثله في الأرض . رجل كامل ومستقيم ، يتقي الله ويحيد عن الشر '),
(18645, 'Job', 18, 1, 9, ' فأجاب الشيطان الرب وقال : هل مجانا يتقي أيوب الله '),
(18646, 'Job', 18, 1, 10, ' أليس أنك سيجت حوله وحول بيته وحول كل ما له من كل ناحية ؟ باركت أعمال يديه فانتشرت مواشيه في الأرض '),
(18647, 'Job', 18, 1, 11, ' ولكن ابسط يدك الآن ومس كل ما له ، فإنه في وجهك يجدف عليك '),
(18648, 'Job', 18, 1, 12, ' فقال الرب للشيطان : هوذا كل ما له في يدك ، وإنما إليه لا تمد يدك . ثم خرج الشيطان من أمام وجه الرب '),
(18649, 'Job', 18, 1, 13, ' وكان ذات يوم وأبناؤه وبناته يأكلون ويشربون خمرا في بيت أخيهم الأكبر '),
(18650, 'Job', 18, 1, 14, ' أن رسولا جاء إلى أيوب وقال : البقر كانت تحرث ، والأتن ترعى بجانبها '),
(18651, 'Job', 18, 1, 15, ' فسقط عليها السبئيون وأخذوها ، وضربوا الغلمان بحد السيف ، ونجوت أنا وحدي لأخبرك '),
(18652, 'Job', 18, 1, 16, ' وبينما هو يتكلم إذ جاء آخر وقال : نار الله سقطت من السماء فأحرقت الغنم والغلمان وأكلتهم ، ونجوت أنا وحدي لأخبرك '),
(18653, 'Job', 18, 1, 17, ' وبينما هو يتكلم إذ جاء آخر وقال : الكلدانيون عينوا ثلاث فرق ، فهجموا على الجمال وأخذوها ، وضربوا الغلمان بحد السيف ، ونجوت أنا وحدي لأخبرك '),
(18654, 'Job', 18, 1, 18, ' وبينما هو يتكلم إذ جاء آخر وقال : بنوك وبناتك كانوا يأكلون ويشربون خمرا في بيت أخيهم الأكبر '),
(18655, 'Job', 18, 1, 19, ' وإذا ريح شديدة جاءت من عبر القفر وصدمت زوايا البيت الأربع ، فسقط على الغلمان فماتوا ، ونجوت أنا وحدي لأخبرك '),
(18656, 'Job', 18, 1, 20, ' فقام أيوب ومزق جبته ، وجز شعر رأسه ، وخر على الأرض وسجد '),
(18657, 'Job', 18, 1, 21, ' وقال : عريانا خرجت من بطن أمي ، وعريانا أعود إلى هناك . الرب أعطى والرب أخذ ، فليكن اسم الرب مباركا '),
(18658, 'Job', 18, 1, 22, ' في كل هذا لم يخطئ أيوب ولم ينسب لله جهالة '),
(18659, 'Job', 18, 2, 1, ' وكان ذات يوم أنه جاء بنو الله ليمثلوا أمام الرب ، وجاء الشيطان أيضا في وسطهم ليمثل أمام الرب '),
(18660, 'Job', 18, 2, 2, ' فقال الرب للشيطان : من أين جئت ؟  . فأجاب الشيطان الرب وقال : من الجولان في الأرض ، ومن التمشي فيها '),
(18661, 'Job', 18, 2, 3, ' فقال الرب للشيطان : هل جعلت قلبك على عبدي أيوب ؟ لأنه ليس مثله في الأرض . رجل كامل ومستقيم يتقي الله ويحيد عن الشر . وإلى الآن هو متمسك بكماله ، وقد هيجتني عليه لأبتلعه بلا سبب '),
(18662, 'Job', 18, 2, 4, ' فأجاب الشيطان الرب وقال : جلد بجلد ، وكل ما للإنسان يعطيه لأجل نفسه '),
(18663, 'Job', 18, 2, 5, ' ولكن ابسط الآن يدك ومس عظمه ولحمه ، فإنه في وجهك يجدف عليك '),
(18664, 'Job', 18, 2, 6, ' فقال الرب للشيطان : ها هو في يدك ، ولكن احفظ نفسه '),
(18665, 'Job', 18, 2, 7, ' فخرج الشيطان من حضرة الرب ، وضرب أيوب بقرح رديء من باطن قدمه إلى هامته '),
(18666, 'Job', 18, 2, 8, ' فأخذ لنفسه شقفة ليحتك بها وهو جالس في وسط الرماد '),
(18667, 'Job', 18, 2, 9, ' فقالت له امرأته : أنت متمسك بعد بكمالك ؟ بارك الله ومت '),
(18668, 'Job', 18, 2, 10, ' فقال لها : تتكلمين كلاما كإحدى الجاهلات أالخير نقبل من عند الله ، والشر لا نقبل ؟  . في كل هذا لم يخطئ أيوب بشفتيه '),
(18669, 'Job', 18, 2, 11, ' فلما سمع أصحاب أيوب الثلاثة بكل الشر الذي أتى عليه ، جاءوا كل واحد من مكانه : أليفاز التيماني وبلدد الشوحي وصوفر النعماتي ، وتواعدوا أن يأتوا ليرثوا له ويعزوه '),
(18670, 'Job', 18, 2, 12, ' ورفعوا أعينهم من بعيد ولم يعرفوه ، فرفعوا أصواتهم وبكوا ، ومزق كل واحد جبته ، وذروا ترابا فوق رؤوسهم نحو السماء '),
(18671, 'Job', 18, 2, 13, ' وقعدوا معه على الأرض سبعة أيام وسبع ليال ، ولم يكلمه أحد بكلمة ، لأنهم رأوا أن كآبته كانت عظيمة جدا '),
(18672, 'Job', 18, 3, 1, ' بعد هذا فتح أيوب فاه وسب يومه '),
(18673, 'Job', 18, 3, 2, ' وأخذ أيوب يتكلم فقال '),
(18674, 'Job', 18, 3, 3, ' ليته هلك اليوم الذي ولدت فيه ، والليل الذي قال : قد حبل برجل '),
(18675, 'Job', 18, 3, 4, ' ليكن ذلك اليوم ظلاما . لا يعتن به الله من فوق ، ولا يشرق عليه نهار '),
(18676, 'Job', 18, 3, 5, ' ليملكه الظلام وظل الموت . ليحل عليه سحاب . لترعبه كاسفات النهار '),
(18677, 'Job', 18, 3, 6, ' أما ذلك الليل فليمسكه الدجى ، ولا يفرح بين أيام السنة ، ولا يدخلن في عدد الشهور '),
(18678, 'Job', 18, 3, 7, ' هوذا ذلك الليل ليكن عاقرا ، لا يسمع فيه هتاف '),
(18679, 'Job', 18, 3, 8, ' ليلعنه لاعنو اليوم المستعدون لإيقاظ التنين '),
(18680, 'Job', 18, 3, 9, ' لتظلم نجوم عشائه . لينتظر النور ولا يكن ، ولا ير هدب الصبح '),
(18681, 'Job', 18, 3, 10, ' لأنه لم يغلق أبواب بطن أمي ، ولم يستر الشقاوة عن عيني '),
(18682, 'Job', 18, 3, 11, ' لم لم أمت من الرحم ؟ عندما خرجت من البطن ، لم لم أسلم الروح '),
(18683, 'Job', 18, 3, 12, ' لماذا أعانتني الركب ؟ ولم الثدي حتى أرضع '),
(18684, 'Job', 18, 3, 13, ' لأني قد كنت الآن مضطجعا ساكنا . حينئذ كنت نمت مستريحا '),
(18685, 'Job', 18, 3, 14, ' مع ملوك ومشيري الأرض ، الذين بنوا أهراما لأنفسهم '),
(18686, 'Job', 18, 3, 15, ' أو مع رؤساء لهم ذهب ، المالئين بيوتهم فضة '),
(18687, 'Job', 18, 3, 16, ' أو كسقط مطمور فلم أكن ، كأجنة لم يروا نورا '),
(18688, 'Job', 18, 3, 17, ' هناك يكف المنافقون عن الشغب ، وهناك يستريح المتعبون '),
(18689, 'Job', 18, 3, 18, ' الأسرى يطمئنون جميعا ، لا يسمعون صوت المسخر '),
(18690, 'Job', 18, 3, 19, ' الصغير كما الكبير هناك ، والعبد حر من سيده '),
(18691, 'Job', 18, 3, 20, ' لم يعطى لشقي نور ، وحياة لمري النفس '),
(18692, 'Job', 18, 3, 21, ' الذين ينتظرون الموت وليس هو ، ويحفرون عليه أكثر من الكنوز '),
(18693, 'Job', 18, 3, 22, ' المسرورين إلى أن يبتهجوا ، الفرحين عندما يجدون قبرا '),
(18694, 'Job', 18, 3, 23, ' لرجل قد خفي عليه طريقه ، وقد سيج الله حوله '),
(18695, 'Job', 18, 3, 24, ' لأنه مثل خبزي يأتي أنيني ، ومثل المياه تنسكب زفرتي '),
(18696, 'Job', 18, 3, 25, ' لأني ارتعابا ارتعبت فأتاني ، والذي فزعت منه جاء علي '),
(18697, 'Job', 18, 3, 26, ' لم أطمئن ولم أسكن ولم أسترح ، وقد جاء الرجز '),
(18698, 'Job', 18, 4, 1, ' فأجاب أليفاز التيماني وقال '),
(18699, 'Job', 18, 4, 2, ' إن امتحن أحد كلمة معك ، فهل تستاء ؟ ولكن من يستطيع الامتناع عن الكلام '),
(18700, 'Job', 18, 4, 3, ' ها أنت قد أرشدت كثيرين ، وشددت أيادي مرتخية '),
(18701, 'Job', 18, 4, 4, ' قد أقام كلامك العاثر ، وثبت الركب المرتعشة '),
(18702, 'Job', 18, 4, 5, ' والآن إذ جاء عليك ضجرت ، إذ مسك ارتعت '),
(18703, 'Job', 18, 4, 6, ' أليست تقواك هي معتمدك ، ورجاؤك كمال طرقك '),
(18704, 'Job', 18, 4, 7, ' اذكر : من هلك وهو بريء ؟ وأين أبيد المستقيمون '),
(18705, 'Job', 18, 4, 8, ' كما قد رأيت : أن الحارثين إثما ، والزارعين شقاوة يحصدونها '),
(18706, 'Job', 18, 4, 9, ' بنسمة الله يبيدون ، وبريح أنفه يفنون '),
(18707, 'Job', 18, 4, 10, ' زمجرة الأسد وصوت الزئير وأنياب الأشبال تكسرت '),
(18708, 'Job', 18, 4, 11, ' الليث هالك لعدم الفريسة ، وأشبال اللبوة تبددت '),
(18709, 'Job', 18, 4, 12, ' ثم إلي تسللت كلمة ، فقبلت أذني منها ركزا '),
(18710, 'Job', 18, 4, 13, ' في الهواجس من رؤى الليل ، عند وقوع سبات على الناس '),
(18711, 'Job', 18, 4, 14, ' أصابني رعب ورعدة ، فرجفت كل عظامي '),
(18712, 'Job', 18, 4, 15, ' فمرت روح على وجهي ، اقشعر شعر جسدي '),
(18713, 'Job', 18, 4, 16, ' وقفت ولكني لم أعرف منظرها ، شبه قدام عيني . سمعت صوتا منخفضا '),
(18714, 'Job', 18, 4, 17, ' أالإنسان أبر من الله ؟ أم الرجل أطهر من خالقه '),
(18715, 'Job', 18, 4, 18, ' هوذا عبيده لا يأتمنهم ، وإلى ملائكته ينسب حماقة '),
(18716, 'Job', 18, 4, 19, ' فكم بالحري سكان بيوت من طين ، الذين أساسهم في التراب ، ويسحقون مثل العث '),
(18717, 'Job', 18, 4, 20, ' بين الصباح والمساء يحطمون . بدون منتبه إليهم إلى الأبد يبيدون '),
(18718, 'Job', 18, 4, 21, ' أما انتزعت منهم طنبهم ؟ يموتون بلا حكمة '),
(18719, 'Job', 18, 5, 1, ' ادع الآن . فهل لك من مجيب ؟ وإلى أي القديسين تلتفت '),
(18720, 'Job', 18, 5, 2, ' لأن الغيظ يقتل الغبي ، والغيرة تميت الأحمق '),
(18721, 'Job', 18, 5, 3, ' إني رأيت الغبي يتأصل وبغتة لعنت مربضه '),
(18722, 'Job', 18, 5, 4, ' بنوه بعيدون عن الأمن ، وقد تحطموا في الباب ولا منقذ '),
(18723, 'Job', 18, 5, 5, ' الذين يأكل الجوعان حصيدهم ، ويأخذه حتى من الشوك ، ويشتف الظمآن ثروتهم '),
(18724, 'Job', 18, 5, 6, ' إن البلية لا تخرج من التراب ، والشقاوة لا تنبت من الأرض '),
(18725, 'Job', 18, 5, 7, ' ولكن الإنسان مولود للمشقة كما أن الجوارح لارتفاع الجناح '),
(18726, 'Job', 18, 5, 8, ' لكن كنت أطلب إلى الله ، وعلى الله أجعل أمري '),
(18727, 'Job', 18, 5, 9, ' الفاعل عظائم لا تفحص وعجائب لا تعد '),
(18728, 'Job', 18, 5, 10, ' المنزل مطرا على وجه الأرض ، والمرسل المياه على البراري '),
(18729, 'Job', 18, 5, 11, ' الجاعل المتواضعين في العلى ، فيرتفع المحزونون إلى أمن '),
(18730, 'Job', 18, 5, 12, ' المبطل أفكار المحتالين ، فلا تجري أيديهم قصدا '),
(18731, 'Job', 18, 5, 13, ' الآخذ الحكماء بحيلتهم ، فتتهور مشورة الماكرين '),
(18732, 'Job', 18, 11, 2, ' أكثرة الكلام لا يجاوب ، أم رجل مهذار يتبرر '),
(18733, 'Job', 18, 11, 3, ' أصلفك يفحم الناس ، أم تلخ وليس من يخزيك '),
(18734, 'Job', 18, 11, 4, ' إذ تقول : تعليمي زكي ، وأنا بار في عينيك '),
(18735, 'Job', 18, 11, 5, ' ولكن يا ليت الله يتكلم ويفتح شفتيه معك '),
(18736, 'Job', 18, 11, 6, ' ويعلن لك خفيات الحكمة إنها مضاعفة الفهم ، فتعلم أن الله يغرمك بأقل من إثمك '),
(18737, 'Job', 18, 11, 7, ' أإلى عمق الله تتصل ، أم إلى نهاية القدير تنتهي '),
(18738, 'Job', 18, 11, 8, ' هو أعلى من السماوات ، فماذا عساك أن تفعل ؟ أعمق من الهاوية ، فماذا تدري '),
(18739, 'Job', 18, 11, 9, ' أطول من الأرض طوله ، وأعرض من البحر '),
(18740, 'Job', 18, 11, 10, ' إن بطش أو أغلق أو جمع ، فمن يرده '),
(18741, 'Job', 18, 11, 11, ' لأنه هو يعلم أناس السوء ، ويبصر الإثم ، فهل لا ينتبه '),
(18742, 'Job', 18, 11, 12, ' أما الرجل ففارغ عديم الفهم ، وكجحش الفرا يولد الإنسان '),
(18743, 'Job', 18, 11, 13, ' إن أعددت أنت قلبك ، وبسطت إليه يديك '),
(18744, 'Job', 18, 11, 14, ' إن أبعدت الإثم الذي في يدك ، ولا يسكن الظلم في خيمتك '),
(18745, 'Job', 18, 11, 15, ' حينئذ ترفع وجهك بلا عيب ، وتكون ثابتا ولا تخاف '),
(18746, 'Job', 18, 11, 16, ' لأنك تنسى المشقة . كمياه عبرت تذكرها '),
(18747, 'Job', 18, 11, 17, ' وفوق الظهيرة يقوم حظك . الظلام يتحول صباحا '),
(18748, 'Job', 18, 11, 18, ' وتطمئن لأنه يوجد رجاء . تتجسس حولك وتضطجع آمنا '),
(18749, 'Job', 18, 11, 19, ' وتربض وليس من يزعج ، ويتضرع إلى وجهك كثيرون '),
(18750, 'Job', 18, 11, 20, ' أما عيون الأشرار فتتلف ، ومناصهم يبيد ، ورجاؤهم تسليم النفس '),
(18751, 'Job', 18, 12, 1, ' فأجاب أيوب وقال '),
(18752, 'Job', 18, 12, 2, ' صحيح إنكم أنتم شعب ومعكم تموت الحكمة '),
(18753, 'Job', 18, 12, 3, ' غير أنه لي فهم مثلكم . لست أنا دونكم . ومن ليس عنده مثل هذه '),
(18754, 'Job', 18, 12, 4, ' رجلا سخرة لصاحبه صرت . دعا الله فاستجابه . سخرة هو الصديق الكامل '),
(18755, 'Job', 18, 12, 5, ' للمبتلي هوان في أفكار المطمئن ، مهيأ لمن زلت قدمه '),
(18756, 'Job', 18, 12, 6, ' خيام المخربين مستريحة ، والذين يغيظون الله مطمئنون ، الذين يأتون بإلههم في يدهم '),
(18757, 'Job', 18, 12, 7, ' فاسأل البهائم فتعلمك ، وطيور السماء فتخبرك '),
(18758, 'Job', 18, 12, 8, ' أو كلم الأرض فتعلمك ، ويحدثك سمك البحر '),
(18759, 'Job', 18, 12, 9, ' من لا يعلم من كل هؤلاء أن يد الرب صنعت هذا '),
(18760, 'Job', 18, 12, 10, ' الذي بيده نفس كل حي وروح كل البشر '),
(18761, 'Job', 18, 12, 11, ' أفليست الأذن تمتحن الأقوال ، كما أن الحنك يستطعم طعامه '),
(18762, 'Job', 18, 12, 12, ' عند الشيب حكمة ، وطول الأيام فهم '),
(18763, 'Job', 18, 12, 13, ' عنده الحكمة والقدرة . له المشورة والفطنة '),
(18764, 'Job', 18, 12, 14, ' هوذا يهدم فلا يبنى . يغلق على إنسان فلا يفتح '),
(18765, 'Job', 18, 12, 15, ' يمنع المياه فتيبس . يطلقها فتقلب الأرض '),
(18766, 'Job', 18, 12, 16, ' عنده العز والفهم . له المضل والمضل '),
(18767, 'Job', 18, 12, 17, ' يذهب بالمشيرين أسرى ، ويحمق القضاة '),
(18768, 'Job', 18, 12, 18, ' يحل مناطق الملوك ، ويشد أحقاءهم بوثاق '),
(18769, 'Job', 18, 12, 19, ' يذهب بالكهنة أسرى ، ويقلب الأقوياء '),
(18770, 'Job', 18, 12, 20, ' يقطع كلام الأمناء ، وينزع ذوق الشيوخ '),
(18771, 'Job', 18, 12, 21, ' يلقي هوانا على الشرفاء ، ويرخي منطقة الأشداء '),
(18772, 'Job', 18, 12, 22, ' يكشف العمائق من الظلام ، ويخرج ظل الموت إلى النور '),
(18773, 'Job', 18, 12, 23, ' يكثر الأمم ثم يبيدها . يوسع للأمم ثم يجليها '),
(18774, 'Job', 18, 12, 24, ' ينزع عقول رؤساء شعب الأرض ، ويضلهم في تيه بلا طريق '),
(18775, 'Job', 18, 12, 25, ' يتلمسون في الظلام وليس نور ، ويرنحهم مثل السكران '),
(18776, 'Job', 18, 13, 1, ' هذا كله رأته عيني . سمعته أذني وفطنت به '),
(18777, 'Job', 18, 13, 2, ' ما تعرفونه عرفته أنا أيضا . لست دونكم '),
(18778, 'Job', 18, 13, 3, ' ولكني أريد أن أكلم القدير ، وأن أحاكم إلى الله '),
(18779, 'Job', 18, 13, 4, ' أما أنتم فملفقو كذب . أطباء بطالون كلكم '),
(18780, 'Job', 18, 13, 5, ' ليتكم تصمتون صمتا . يكون ذلك لكم حكمة '),
(18781, 'Job', 18, 13, 6, ' اسمعوا الآن حجتي ، واصغوا إلى دعاوي شفتي '),
(18782, 'Job', 18, 13, 7, ' أتقولون لأجل الله ظلما ، وتتكلمون بغش لأجله '),
(18783, 'Job', 18, 13, 8, ' أتحابون وجهه ، أم عن الله تخاصمون '),
(18784, 'Job', 18, 13, 9, ' أخير لكم أن يفحصكم ، أم تخاتلونه كما يخاتل الإنسان '),
(18785, 'Job', 18, 13, 10, ' توبيخا يوبخكم إن حابيتم الوجوه خفية '),
(18786, 'Job', 18, 13, 11, ' فهلا يرهبكم جلاله ، ويسقط عليكم رعبه '),
(18787, 'Job', 18, 13, 12, ' خطبكم أمثال رماد ، وحصونكم حصون من طين '),
(18788, 'Job', 18, 13, 13, ' اسكتوا عني فأتكلم أنا ، وليصبني مهما أصاب '),
(18789, 'Job', 18, 13, 14, ' لماذا آخذ لحمي بأسناني ، وأضع نفسي في كفي '),
(18790, 'Job', 18, 13, 15, ' هوذا يقتلني . لا أنتظر شيئا . فقط أزكي طريقي قدامه '),
(18791, 'Job', 18, 13, 16, ' فهذا يعود إلى خلاصي ، أن الفاجر لا يأتي قدامه '),
(18792, 'Job', 18, 13, 17, ' سمعا اسمعوا أقوالي وتصريحي بمسامعكم '),
(18793, 'Job', 18, 13, 18, ' هأنذا قد أحسنت الدعوى . أعلم أني أتبرر '),
(18794, 'Job', 18, 13, 19, ' من هو الذي يخاصمني حتى أصمت الآن وأسلم الروح '),
(18795, 'Job', 18, 13, 20, ' إنما أمرين لا تفعل بي ، فحينئذ لا أختفي من حضرتك '),
(18796, 'Job', 18, 13, 21, ' أبعد يديك عني ، ولا تدع هيبتك ترعبني '),
(18797, 'Job', 18, 13, 22, ' ثم ادع فأنا أجيب ، أو أتكلم فتجاوبني '),
(18798, 'Job', 18, 13, 23, ' كم لي من الآثام والخطايا ؟ أعلمني ذنبي وخطيتي '),
(18799, 'Job', 18, 13, 24, ' لماذا تحجب وجهك ، وتحسبني عدوا لك '),
(18800, 'Job', 18, 13, 25, ' أترعب ورقة مندفعة ، وتطارد قشا يابسا '),
(18801, 'Job', 18, 13, 26, ' لأنك كتبت علي أمورا مرة ، وورثتني آثام صباي '),
(18802, 'Job', 18, 13, 27, ' فجعلت رجلي في المقطرة ، ولاحظت جميع مسالكي ، وعلى أصول رجلي نبشت '),
(18803, 'Job', 18, 13, 28, ' وأنا كمتسوس يبلى ، كثوب أكله العث '),
(18804, 'Job', 18, 14, 1, ' الإنسان مولود المرأة ، قليل الأيام وشبعان تعبا '),
(18805, 'Job', 18, 14, 2, ' يخرج كالزهر ثم ينحسم ويبرح كالظل ولا يقف '),
(18806, 'Job', 18, 14, 3, ' فعلى مثل هذا حدقت عينيك ، وإياي أحضرت إلى المحاكمة معك '),
(18807, 'Job', 18, 14, 4, ' من يخرج الطاهر من النجس ؟ لا أحد '),
(18808, 'Job', 18, 14, 5, ' إن كانت أيامه محدودة ، وعدد أشهره عندك ، وقد عينت أجله فلا يتجاوزه '),
(18809, 'Job', 18, 14, 6, ' فأقصر عنه ليسترح ، إلى أن يسر كالأجير بانتهاء يومه '),
(18810, 'Job', 18, 14, 7, ' لأن للشجرة رجاء . إن قطعت تخلف أيضا ولا تعدم خراعيبها '),
(18811, 'Job', 18, 14, 8, ' ولو قدم في الأرض أصلها ، ومات في التراب جذعها '),
(18812, 'Job', 18, 14, 9, ' فمن رائحة الماء تفرخ وتنبت فروعا كالغرس '),
(18813, 'Job', 18, 14, 10, ' أما الرجل فيموت ويبلى . الإنسان يسلم الروح ، فأين هو '),
(18814, 'Job', 18, 14, 11, ' قد تنفد المياه من البحرة ، والنهر ينشف ويجف '),
(18815, 'Job', 18, 14, 12, ' والإنسان يضطجع ولا يقوم . لا يستيقظون حتى لا تبقى السماوات ، ولا ينتبهون من نومهم '),
(18816, 'Job', 18, 14, 13, ' ليتك تواريني في الهاوية ، وتخفيني إلى أن ينصرف غضبك ، وتعين لي أجلا فتذكرني '),
(18817, 'Job', 18, 14, 14, ' إن مات رجل أفيحيا ؟ كل أيام جهادي أصبر إلى أن يأتي بدلي '),
(18818, 'Job', 18, 14, 15, ' تدعو فأنا أجيبك . تشتاق إلى عمل يدك '),
(18819, 'Job', 18, 14, 16, ' أما الآن فتحصي خطواتي ، ألا تحافظ على خطيتي '),
(18820, 'Job', 18, 14, 17, ' معصيتي مختوم عليها في صرة ، وتلفق علي فوق إثمي '),
(18821, 'Job', 18, 14, 18, ' إن الجبل الساقط ينتثر ، والصخر يزحزح من مكانه '),
(18822, 'Job', 18, 14, 19, ' الحجارة تبليها المياه وتجرف سيولها تراب الأرض ، وكذلك أنت تبيد رجاء الإنسان '),
(18823, 'Job', 18, 14, 20, ' تتجبر عليه أبدا فيذهب . تغير وجهه وتطرده '),
(18824, 'Job', 18, 14, 21, ' يكرم بنوه ولا يعلم ، أو يصغرون ولا يفهم بهم '),
(18825, 'Job', 18, 14, 22, ' إنما على ذاته يتوجع لحمه وعلى ذاتها تنوح نفسه '),
(18826, 'Job', 18, 15, 1, ' فأجاب أليفاز التيماني وقال '),
(18827, 'Job', 18, 15, 2, ' ألعل الحكيم يجيب عن معرفة باطلة ، ويملأ بطنه من ريح شرقية '),
(18828, 'Job', 18, 15, 3, ' فيحتج بكلام لا يفيد ، وبأحاديث لا ينتفع بها '),
(18829, 'Job', 18, 15, 4, ' أما أنت فتنافي المخافة ، وتناقض التقوى لدى الله '),
(18830, 'Job', 18, 15, 5, ' لأن فمك يذيع إثمك ، وتختار لسان المحتالين '),
(18831, 'Job', 18, 15, 6, ' إن فمك يستذنبك ، لا أنا ، وشفتاك تشهدان عليك '),
(18832, 'Job', 18, 15, 7, ' أصورت أول الناس أم أبدئت قبل التلال '),
(18833, 'Job', 18, 15, 8, ' هل تنصت في مجلس الله ، أو قصرت الحكمة على نفسك '),
(18834, 'Job', 18, 15, 9, ' ماذا تعرفه ولا نعرفه نحن ؟ وماذا تفهم وليس هو عندنا '),
(18835, 'Job', 18, 15, 10, ' عندنا الشيخ والأشيب ، أكبر أياما من أبيك '),
(18836, 'Job', 18, 15, 11, ' أقليلة عندك تعزيات الله ، والكلام معك بالرفق '),
(18837, 'Job', 18, 15, 12, ' لماذا يأخذك قلبك ؟ ولماذا تختلج عيناك '),
(18838, 'Job', 18, 15, 13, ' حتى ترد على الله وتخرج من فيك أقوالا '),
(18839, 'Job', 18, 15, 14, ' من هو الإنسان حتى يزكو ، أو مولود المرأة حتى يتبرر '),
(18840, 'Job', 18, 15, 15, ' هوذا قديسوه لا يأتمنهم ، والسماوات غير طاهرة بعينيه '),
(18841, 'Job', 18, 15, 16, ' فبالحري مكروه وفاسد الإنسان الشارب الإثم كالماء '),
(18842, 'Job', 18, 15, 17, ' أوحي إليك ، اسمع لي فأحدث بما رأيته '),
(18843, 'Job', 18, 15, 18, ' ما أخبر به حكماء عن آبائهم فلم يكتموه '),
(18844, 'Job', 18, 15, 19, ' الذين لهم وحدهم أعطيت الأرض ، ولم يعبر بينهم غريب '),
(18845, 'Job', 18, 15, 20, ' الشرير هو يتلوى كل أيامه ، وكل عدد السنين المعدودة للعاتي '),
(18846, 'Job', 18, 15, 21, ' صوت رعوب في أذنيه . في ساعة سلام يأتيه المخرب '),
(18847, 'Job', 18, 15, 22, ' لا يأمل الرجوع من الظلمة ، وهو مرتقب للسيف '),
(18848, 'Job', 18, 15, 23, ' تائه هو لأجل الخبز حيثما يجده ، ويعلم أن يوم الظلمة مهيأ بين يديه '),
(18849, 'Job', 18, 15, 24, ' يرهبه الضر والضيق . يتجبران عليه كملك مستعد للوغى '),
(18850, 'Job', 18, 15, 25, ' لأنه مد على الله يده ، وعلى القدير تجبر '),
(18851, 'Job', 18, 15, 26, ' عاديا عليه ، متصلب العنق بأوقاف مجانه معبأة '),
(18852, 'Job', 18, 15, 27, ' لأنه قد كسا وجهه سمنا ، وربى شحما على كليتيه '),
(18853, 'Job', 18, 15, 28, ' فيسكن مدنا خربة ، بيوتا غير مسكونة عتيدة أن تصير رجما '),
(18854, 'Job', 18, 15, 29, ' لا يستغني ، ولا تثبت ثروته ، ولا يمتد في الأرض مقتناه '),
(18855, 'Job', 18, 15, 30, ' لا تزول عنه الظلمة . خراعيبه تيبسها السموم ، وبنفخة فمه يزول '),
(18856, 'Job', 18, 15, 31, ' لا يتكل على السوء . يضل . لأن السوء يكون أجرته '),
(18857, 'Job', 18, 15, 32, ' قبل يومه يتوفى ، وسعفه لا يخضر '),
(18858, 'Job', 18, 15, 33, ' يساقط كالجفنة حصرمه ، وينثر كالزيتون زهره '),
(18859, 'Job', 18, 15, 34, ' لأن جماعة الفجار عاقر ، والنار تأكل خيام الرشوة '),
(18860, 'Job', 18, 15, 35, ' حبل شقاوة وولد إثما ، وبطنه أنشأ غشا '),
(18861, 'Job', 18, 16, 1, ' فأجاب أيوب وقال '),
(18862, 'Job', 18, 16, 2, ' قد سمعت كثيرا مثل هذا . معزون متعبون كلكم '),
(18863, 'Job', 18, 16, 3, ' هل من نهاية لكلام فارغ ؟ أو ماذا يهيجك حتى تجاوب '),
(18864, 'Job', 18, 16, 4, ' أنا أيضا أستطيع أن أتكلم مثلكم ، لو كانت أنفسكم مكان نفسي ، وأن أسرد عليكم أقوالا وأنغض رأسي إليكم '),
(18865, 'Job', 18, 16, 5, ' بل كنت أشددكم بفمي ، وتعزية شفتي تمسككم '),
(18866, 'Job', 18, 16, 6, ' إن تكلمت لم تمتنع كآبتي ، وإن سكت فماذا يذهب عني '),
(18867, 'Job', 18, 16, 7, ' إنه الآن ضجرني . خربت كل جماعتي '),
(18868, 'Job', 18, 16, 8, ' قبضت علي . وجد شاهد . قام علي هزالي يجاوب في وجهي '),
(18869, 'Job', 18, 16, 9, ' غضبه افترسني واضطهدني . حرق علي أسنانه . عدوي يحدد عينيه علي '),
(18870, 'Job', 18, 16, 10, ' فغروا علي أفواههم . لطموني على فكي تعييرا . تعاونوا علي جميعا '),
(18871, 'Job', 18, 16, 11, ' دفعني الله إلى الظالم ، وفي أيدي الأشرار طرحني '),
(18872, 'Job', 18, 16, 12, ' كنت مستريحا فزعزعني ، وأمسك بقفاي فحطمني ، ونصبني له غرضا '),
(18873, 'Job', 18, 16, 13, ' أحاطت بي رماته . شق كليتي ولم يشفق . سفك مرارتي على الأرض '),
(18874, 'Job', 18, 16, 14, ' يقتحمني اقتحاما على اقتحام . يعدو علي كجبار '),
(18875, 'Job', 18, 16, 15, ' خطت مسحا على جلدي ، ودسست في التراب قرني '),
(18876, 'Job', 18, 16, 16, ' احمر وجهي من البكاء ، وعلى هدبي ظل الموت '),
(18877, 'Job', 18, 16, 17, ' مع أنه لا ظلم في يدي ، وصلاتي خالصة '),
(18878, 'Job', 18, 16, 18, ' يا أرض لا تغطي دمي ، ولا يكن مكان لصراخي '),
(18879, 'Job', 18, 16, 19, ' أيضا الآن هوذا في السماوات شهيدي ، وشاهدي في الأعالي '),
(18880, 'Job', 18, 16, 20, ' المستهزئون بي هم أصحابي . لله تقطر عيني '),
(18881, 'Job', 18, 16, 21, ' لكي يحاكم الإنسان عند الله كابن آدم لدى صاحبه '),
(18882, 'Job', 18, 16, 22, ' إذا مضت سنون قليلة أسلك في طريق لا أعود منها '),
(18883, 'Job', 18, 17, 1, ' روحي تلفت . أيامي انطفأت . إنما القبور لي '),
(18884, 'Job', 18, 17, 2, ' لولا المخاتلون عندي ، وعيني تبيت على مشاجراتهم '),
(18885, 'Job', 18, 17, 3, ' كن ضامني عند نفسك . من هو الذي يصفق يدي '),
(18886, 'Job', 18, 17, 4, ' لأنك منعت قلبهم عن الفطنة ، لأجل ذلك لا ترفعهم '),
(18887, 'Job', 18, 17, 5, ' الذي يسلم الأصحاب للسلب ، تتلف عيون بنيه '),
(18888, 'Job', 18, 17, 6, ' أوقفني مثلا للشعوب ، وصرت للبصق في الوجه '),
(18889, 'Job', 18, 17, 7, ' كلت عيني من الحزن ، وأعضائي كلها كالظل '),
(18890, 'Job', 18, 17, 8, ' يتعجب المستقيمون من هذا ، والبرئ ينتهض على الفاجر '),
(18891, 'Job', 18, 17, 9, ' أما الصديق فيستمسك بطريقه ، والطاهر اليدين يزداد قوة '),
(18892, 'Job', 18, 17, 10, ' ولكن ارجعوا كلكم وتعالوا ، فلا أجد فيكم حكيما '),
(18893, 'Job', 18, 17, 11, ' أيامي قد عبرت . مقاصدي ، إرث قلبي ، قد انتزعت '),
(18894, 'Job', 18, 17, 12, ' يجعلون الليل نهارا ، نورا قريبا للظلمة '),
(18895, 'Job', 18, 17, 13, ' إذا رجوت الهاوية بيتا لي ، وفي الظلام مهدت فراشي '),
(18896, 'Job', 18, 17, 14, ' وقلت للقبر : أنت أبي ، وللدود : أنت أمي وأختي '),
(18897, 'Job', 18, 17, 15, ' فأين إذا آمالي ؟ آمالي ، من يعاينها '),
(18898, 'Job', 18, 17, 16, ' تهبط إلى مغاليق الهاوية إذ ترتاح معا في التراب '),
(18899, 'Job', 18, 18, 1, ' فأجاب بلدد الشوحي وقال '),
(18900, 'Job', 18, 18, 2, ' إلى متى تضعون أشراكا للكلام ؟ تعقلوا وبعد نتكلم '),
(18901, 'Job', 18, 18, 3, ' لماذا حسبنا كالبهيمة ، وتنجسنا في عيونكم '),
(18902, 'Job', 18, 18, 4, ' يا أيها المفترس نفسه في غيظه ، هل لأجلك تخلى الأرض ، أو يزحزح الصخر من مكانه '),
(18903, 'Job', 18, 18, 5, ' نعم نور الأشرار ينطفئ ، ولا يضيء لهيب ناره '),
(18904, 'Job', 18, 18, 6, ' النور يظلم في خيمته ، وسراجه فوقه ينطفئ '),
(18905, 'Job', 18, 18, 7, ' تقصر خطوات قوته ، وتصرعه مشورته '),
(18906, 'Job', 18, 18, 8, ' لأن رجليه تدفعانه في المصلاة فيمشي إلى شبكة '),
(18907, 'Job', 18, 18, 9, ' يمسك الفخ بعقبه ، وتتمكن منه الشرك '),
(18908, 'Job', 18, 18, 10, ' مطمورة في الأرض حبالته ، ومصيدته في السبيل '),
(18909, 'Job', 18, 18, 11, ' ترهبه أهوال من حوله ، وتذعره عند رجليه '),
(18910, 'Job', 18, 18, 12, ' تكون قوته جائعة والبوار مهيأ بجانبه '),
(18911, 'Job', 18, 18, 13, ' يأكل أعضاء جسده . يأكل أعضاءه بكر الموت '),
(18912, 'Job', 18, 18, 14, ' ينقطع عن خيمته ، عن اعتماده ، ويساق إلى ملك الأهوال '),
(18913, 'Job', 18, 18, 15, ' يسكن في خيمته من ليس له . يذر على مربضه كبريت '),
(18914, 'Job', 18, 18, 16, ' من تحت تيبس أصوله ، ومن فوق يقطع فرعه '),
(18915, 'Job', 18, 18, 17, ' ذكره يبيد من الأرض ، ولا اسم له على وجه البر '),
(18916, 'Job', 18, 18, 18, ' يدفع من النور إلى الظلمة ، ومن المسكونة يطرد '),
(18917, 'Job', 18, 18, 19, ' لا نسل ولا عقب له بين شعبه ، ولا شارد في محاله '),
(18918, 'Job', 18, 18, 20, ' يتعجب من يومه المتأخرون ، ويقشعر الأقدمون '),
(18919, 'Job', 18, 18, 21, ' إنما تلك مساكن فاعلي الشر ، وهذا مقام من لا يعرف الله '),
(18920, 'Job', 18, 19, 1, ' فأجاب أيوب وقال '),
(18921, 'Job', 18, 19, 2, ' حتى متى تعذبون نفسي وتسحقونني بالكلام '),
(18922, 'Job', 18, 19, 3, ' هذه عشر مرات أخزيتموني . لم تخجلوا من أن تحكروني '),
(18923, 'Job', 18, 19, 4, ' وهبني ضللت حقا . علي تستقر ضلالتي '),
(18924, 'Job', 18, 19, 5, ' إن كنتم بالحق تستكبرون علي ، فثبتوا علي عاري '),
(18925, 'Job', 18, 19, 6, ' فاعلموا إذا أن الله قد عوجني ، ولف علي أحبولته '),
(18926, 'Job', 18, 19, 7, ' ها إني أصرخ ظلما فلا أستجاب . أدعو وليس حكم '),
(18927, 'Job', 18, 19, 8, ' قد حوط طريقي فلا أعبر ، وعلى سبلي جعل ظلاما '),
(18928, 'Job', 18, 19, 9, ' أزال عني كرامتي ونزع تاج رأسي '),
(18929, 'Job', 18, 19, 10, ' هدمني من كل جهة فذهبت ، وقلع مثل شجرة رجائي '),
(18930, 'Job', 18, 19, 11, ' وأضرم علي غضبه ، وحسبني كأعدائه '),
(18931, 'Job', 18, 19, 12, ' معا جاءت غزاته ، وأعدوا علي طريقهم ، وحلوا حول خيمتي '),
(18932, 'Job', 18, 19, 13, ' قد أبعد عني إخوتي ، ومعارفي زاغوا عني '),
(18933, 'Job', 18, 19, 14, ' أقاربي قد خذلوني ، والذين عرفوني نسوني '),
(18934, 'Job', 18, 19, 15, ' نزلاء بيتي وإمائي يحسبونني أجنبيا . صرت في أعينهم غريبا '),
(18935, 'Job', 18, 19, 16, ' عبدي دعوت فلم يجب . بفمي تضرعت إليه '),
(18936, 'Job', 18, 19, 17, ' نكهتي مكروهة عند امرأتي ، وخممت عند أبناء أحشائي '),
(18937, 'Job', 18, 19, 18, ' الأولاد أيضا قد رذلوني . إذا قمت يتكلمون علي '),
(18938, 'Job', 18, 19, 19, ' كرهني كل رجالي ، والذين أحببتهم انقلبوا علي '),
(18939, 'Job', 18, 19, 20, ' عظمي قد لصق بجلدي ولحمي ، ونجوت بجلد أسناني '),
(18940, 'Job', 18, 19, 21, ' تراءفوا ، تراءفوا أنتم علي يا أصحابي ، لأن يد الله قد مستني '),
(18941, 'Job', 18, 19, 22, ' لماذا تطاردونني كما الله ، ولا تشبعون من لحمي '),
(18942, 'Job', 18, 19, 23, ' ليت كلماتي الآن تكتب . يا ليتها رسمت في سفر '),
(18943, 'Job', 18, 19, 24, ' ونقرت إلى الأبد في الصخر بقلم حديد وبرصاص '),
(18944, 'Job', 18, 19, 25, ' أما أنا فقد علمت أن وليي حي ، والآخر على الأرض يقوم '),
(18945, 'Job', 18, 19, 26, ' وبعد أن يفنى جلدي هذا ، وبدون جسدي أرى الله '),
(18946, 'Job', 18, 19, 27, ' الذي أراه أنا لنفسي ، وعيناي تنظران وليس آخر . إلى ذلك تتوق كليتاي في جوفي '),
(18947, 'Job', 18, 19, 28, ' فإنكم تقولون : لماذا نطارده ؟ والكلام الأصلي يوجد عندي '),
(18948, 'Job', 18, 19, 29, ' خافوا على أنفسكم من السيف ، لأن الغيظ من آثام السيف . لكي تعلموا ما هو القضاء '),
(18949, 'Job', 18, 20, 1, ' فأجاب صوفر النعماتي وقال '),
(18950, 'Job', 18, 20, 2, ' من أجل ذلك هواجسي تجيبني ، ولهذا هيجاني في '),
(18951, 'Job', 18, 20, 3, ' تعيير توبيخي أسمع . وروح من فهمي يجيبني '),
(18952, 'Job', 18, 20, 4, ' أما علمت هذا من القديم ، منذ وضع الإنسان على الأرض '),
(18953, 'Job', 18, 20, 5, ' أن هتاف الأشرار من قريب ، وفرح الفاجر إلى لحظة '),
(18954, 'Job', 18, 20, 6, ' ولو بلغ السماوات طوله ، ومس رأسه السحاب '),
(18955, 'Job', 18, 20, 7, ' كجلته إلى الأبد يبيد . الذين رأوه يقولون : أين هو '),
(18956, 'Job', 18, 20, 8, ' كالحلم يطير فلا يوجد ، ويطرد كطيف الليل '),
(18957, 'Job', 18, 20, 9, ' عين أبصرته لا تعود تراه ، ومكانه لن يراه بعد '),
(18958, 'Job', 18, 20, 10, ' بنوه يترضون الفقراء ، ويداه تردان ثروته '),
(18959, 'Job', 18, 20, 11, ' عظامه ملآنة شبيبة ، ومعه في التراب تضطجع '),
(18960, 'Job', 18, 20, 12, ' إن حلا في فمه الشر ، وأخفاه تحت لسانه '),
(18961, 'Job', 18, 20, 13, ' أشفق عليه ولم يتركه ، بل حبسه وسط حنكه '),
(18962, 'Job', 18, 20, 14, ' فخبزه في أمعائه يتحول ، مرارة أصلال في بطنه '),
(18963, 'Job', 18, 20, 15, ' قد بلع ثروة فيتقيأها . الله يطردها من بطنه '),
(18964, 'Job', 18, 20, 16, ' سم الأصلال يرضع . يقتله لسان الأفعى '),
(18965, 'Job', 18, 20, 17, ' لا يرى الجداول أنهار سواقي عسل ولبن '),
(18966, 'Job', 18, 20, 18, ' يرد تعبه ولا يبلعه . كمال تحت رجع . ولا يفرح '),
(18967, 'Job', 18, 20, 19, ' لأنه رضض المساكين ، وتركهم ، واغتصب بيتا ولم يبنه '),
(18968, 'Job', 18, 20, 20, ' لأنه لم يعرف في بطنه قناعة ، لا ينجو بمشتهاه '),
(18969, 'Job', 18, 20, 21, ' ليست من أكله بقية ، لأجل ذلك لا يدوم خيره '),
(18970, 'Job', 18, 20, 22, ' مع ملء رغده يتضايق . تأتي عليه يد كل شقي '),
(18971, 'Job', 18, 20, 23, ' يكون عندما يملأ بطنه ، أن الله يرسل عليه حمو غضبه ، ويمطره عليه عند طعامه '),
(18972, 'Job', 18, 20, 24, ' يفر من سلاح حديد . تخرقه قوس نحاس '),
(18973, 'Job', 18, 20, 25, ' جذبه فخرج من بطنه ، والبارق من مرارته مرق . عليه رعوب '),
(18974, 'Job', 18, 20, 26, ' كل ظلمة مختبأة لذخائره . تأكله نار لم تنفخ . ترعى البقية في خيمته '),
(18975, 'Job', 18, 20, 27, ' السماوات تعلن إثمه ، والأرض تنهض عليه '),
(18976, 'Job', 18, 20, 28, ' تزول غلة بيته . تهراق في يوم غضبه '),
(18977, 'Job', 18, 20, 29, ' هذا نصيب الإنسان الشرير من عند الله ، وميراث أمره من القدير '),
(18978, 'Job', 18, 21, 1, ' فأجاب أيوب وقال '),
(18979, 'Job', 18, 21, 2, ' اسمعوا قولي سمعا ، وليكن هذا تعزيتكم '),
(18980, 'Job', 18, 21, 3, ' احتملوني وأنا أتكلم ، وبعد كلامي استهزئوا '),
(18981, 'Job', 18, 21, 4, ' أما أنا فهل شكواي من إنسان ، وإن كانت ، فلماذا لا تضيق روحي '),
(18982, 'Job', 18, 21, 5, ' تفرسوا في وتعجبوا وضعوا اليد على الفم '),
(18983, 'Job', 18, 21, 6, ' عندما أتذكر أرتاع ، وأخذت بشري رعدة '),
(18984, 'Job', 18, 21, 7, ' لماذا تحيا الأشرار ويشيخون ، نعم ويتجبرون قوة '),
(18985, 'Job', 18, 21, 8, ' نسلهم قائم أمامهم معهم ، وذريتهم في أعينهم '),
(18986, 'Job', 18, 21, 9, ' بيوتهم آمنة من الخوف ، وليس عليهم عصا الله '),
(18987, 'Job', 18, 21, 10, ' ثورهم يلقح ولا يخطئ . بقرتهم تنتج ولا تسقط '),
(18988, 'Job', 18, 21, 11, ' يسرحون مثل الغنم رضعهم ، وأطفالهم ترقص '),
(18989, 'Job', 18, 21, 12, ' يحملون الدف والعود ، ويطربون بصوت المزمار '),
(18990, 'Job', 18, 21, 13, ' يقضون أيامهم بالخير . في لحظة يهبطون إلى الهاوية '),
(18991, 'Job', 18, 21, 14, ' فيقولون لله : ابعد عنا ، وبمعرفة طرقك لا نسر '),
(18992, 'Job', 18, 21, 15, ' من هو القدير حتى نعبده ؟ وماذا ننتفع إن التمسناه '),
(18993, 'Job', 18, 21, 16, ' هوذا ليس في يدهم خيرهم . لتبعد عني مشورة الأشرار '),
(18994, 'Job', 18, 21, 17, ' كم ينطفئ سراج الأشرار ، ويأتي عليهم بوارهم ؟ أو يقسم لهم أوجاعا في غضبه '),
(18995, 'Job', 18, 21, 18, ' أو يكونون كالتبن قدام الريح ، وكالعصافة التي تسرقها الزوبعة '),
(18996, 'Job', 18, 21, 19, ' الله يخزن إثمه لبنيه . ليجازه نفسه فيعلم '),
(18997, 'Job', 18, 21, 20, ' لتنظر عيناه هلاكه ، ومن حمة القدير يشرب '),
(18998, 'Job', 18, 21, 21, ' فما هي مسرته في بيته بعده ، وقد تعين عدد شهوره '),
(18999, 'Job', 18, 21, 22, ' أالله يعلم معرفة ، وهو يقضي على العالين '),
(19000, 'Job', 18, 21, 23, ' هذا يموت في عين كماله . كله مطمئن وساكن '),
(19001, 'Job', 18, 21, 24, ' أحواضه ملآنة لبنا ، ومخ عظامه طري '),
(19002, 'Job', 18, 21, 25, ' وذلك يموت بنفس مرة ولم يذق خيرا ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(19003, 'Job', 18, 21, 26, ' كلاهما يضطجعان معا في التراب والدود يغشاهما '),
(19004, 'Job', 18, 21, 27, ' هوذا قد علمت أفكاركم والنيات التي بها تظلمونني '),
(19005, 'Job', 18, 21, 28, ' لأنكم تقولون : أين بيت العاتي ؟ وأين خيمة مساكن الأشرار '),
(19006, 'Job', 18, 21, 29, ' أفلم تسألوا عابري السبيل ، ولم تفطنوا لدلائلهم '),
(19007, 'Job', 18, 21, 30, ' إنه ليوم البوار يمسك الشرير . ليوم السخط يقادون '),
(19008, 'Job', 18, 21, 31, ' من يعلن طريقه لوجهه ؟ ومن يجازيه على ما عمل '),
(19009, 'Job', 18, 21, 32, ' هو إلى القبور يقاد ، وعلى المدفن يسهر '),
(19010, 'Job', 18, 21, 33, ' حلو له مدر الوادي . يزحف كل إنسان وراءه ، وقدامه ما لا عدد له '),
(19011, 'Job', 18, 21, 34, ' فكيف تعزونني باطلا وأجوبتكم بقيت خيانة '),
(19012, 'Job', 18, 22, 1, ' فأجاب أليفاز التيماني وقال '),
(19013, 'Job', 18, 22, 2, ' هل ينفع الإنسان الله ؟ بل ينفع نفسه الفطن '),
(19014, 'Job', 18, 22, 3, ' هل من مسرة للقدير إذا تبررت ، أو من فائدة إذا قومت طرقك '),
(19015, 'Job', 18, 22, 4, ' هل على تقواك يوبخك ، أو يدخل معك في المحاكمة '),
(19016, 'Job', 18, 22, 5, ' أليس شرك عظيما ، وآثامك لا نهاية لها '),
(19017, 'Job', 18, 22, 6, ' لأنك ارتهنت أخاك بلا سبب ، وسلبت ثياب العراة '),
(19018, 'Job', 18, 22, 7, ' ماء لم تسق العطشان ، وعن الجوعان منعت خبزا '),
(19019, 'Job', 18, 22, 8, ' أما صاحب القوة فله الأرض ، والمترفع الوجه ساكن فيها '),
(19020, 'Job', 18, 22, 9, ' الأرامل أرسلت خاليات ، وذراع اليتامى انسحقت '),
(19021, 'Job', 18, 22, 10, ' لأجل ذلك حواليك فخاخ ، ويريعك رعب بغتة '),
(19022, 'Job', 18, 22, 11, ' أو ظلمة فلا ترى ، وفيض المياه يغطيك '),
(19023, 'Job', 18, 22, 12, ' هوذا الله في علو السماوات . وانظر رأس الكواكب ما أعلاه '),
(19024, 'Job', 18, 22, 13, ' فقلت : كيف يعلم الله ؟ هل من وراء الضباب يقضي '),
(19025, 'Job', 18, 22, 14, ' السحاب ستر له فلا يرى ، وعلى دائرة السماوات يتمشى '),
(19026, 'Job', 18, 22, 15, ' هل تحفظ طريق القدم الذي داسه رجال الإثم '),
(19027, 'Job', 18, 22, 16, ' الذين قبض عليهم قبل الوقت ؟ الغمر انصب على أساسهم '),
(19028, 'Job', 18, 22, 17, ' القائلين لله : ابعد عنا . وماذا يفعل القدير لهم '),
(19029, 'Job', 18, 22, 18, ' وهو قد ملأ بيوتهم خيرا . لتبعد عني مشورة الأشرار '),
(19030, 'Job', 18, 22, 19, ' الأبرار ينظرون ويفرحون ، والبريء يستهزئ بهم قائلين '),
(19031, 'Job', 18, 22, 20, ' ألم يبد مقاومونا ، وبقيتهم قد أكلتها النار '),
(19032, 'Job', 18, 22, 21, ' تعرف به واسلم . بذلك يأتيك خير '),
(19033, 'Job', 18, 22, 22, ' اقبل الشريعة من فيه ، وضع كلامه في قلبك '),
(19034, 'Job', 18, 22, 23, ' إن رجعت إلى القدير تبنى . إن أبعدت ظلما من خيمتك '),
(19035, 'Job', 18, 22, 24, ' وألقيت التبر على التراب وذهب أوفير بين حصا الأودية '),
(19036, 'Job', 18, 22, 25, ' يكون القدير تبرك وفضة أتعاب لك '),
(19037, 'Job', 18, 22, 26, ' لأنك حينئذ تتلذذ بالقدير وترفع إلى الله وجهك '),
(19038, 'Job', 18, 22, 27, ' تصلي له فيستمع لك ، ونذورك توفيها '),
(19039, 'Job', 18, 22, 28, ' وتجزم أمرا فيثبت لك ، وعلى طرقك يضيء نور '),
(19040, 'Job', 18, 22, 29, ' إذا وضعوا تقول : رفع . ويخلص المنخفض العينين '),
(19041, 'Job', 18, 22, 30, ' ينجي غير البريء ، وينجى بطهارة يديك '),
(19042, 'Job', 18, 23, 1, ' فأجاب أيوب وقال '),
(19043, 'Job', 18, 23, 2, ' اليوم أيضا شكواي تمرد . ضربتي أثقل من تنهدي '),
(19044, 'Job', 18, 23, 3, ' من يعطيني أن أجده ، فآتي إلى كرسيه '),
(19045, 'Job', 18, 23, 4, ' أحسن الدعوى أمامه ، وأملأ فمي حججا '),
(19046, 'Job', 18, 23, 5, ' فأعرف الأقوال التي بها يجيبني ، وأفهم ما يقوله لي '),
(19047, 'Job', 18, 23, 6, ' أبكثرة قوة يخاصمني ؟ كلا ولكنه كان ينتبه إلي '),
(19048, 'Job', 18, 23, 7, ' هنالك كان يحاجه المستقيم ، وكنت أنجو إلى الأبد من قاضي '),
(19049, 'Job', 18, 23, 8, ' هأنذا أذهب شرقا فليس هو هناك ، وغربا فلا أشعر به '),
(19050, 'Job', 18, 23, 9, ' شمالا حيث عمله فلا أنظره . يتعطف الجنوب فلا أراه '),
(19051, 'Job', 18, 23, 10, ' لأنه يعرف طريقي . إذا جربني أخرج كالذهب '),
(19052, 'Job', 18, 23, 11, ' بخطواته استمسكت رجلي . حفظت طريقه ولم أحد '),
(19053, 'Job', 18, 23, 12, ' من وصية شفتيه لم أبرح . أكثر من فريضتي ذخرت كلام فيه '),
(19054, 'Job', 18, 23, 13, ' أما هو فوحده ، فمن يرده ؟ ونفسه تشتهي فيفعل '),
(19055, 'Job', 18, 23, 14, ' لأنه يتمم المفروض علي ، وكثير مثل هذه عنده '),
(19056, 'Job', 18, 23, 15, ' من أجل ذلك أرتاع قدامه . أتأمل فأرتعب منه '),
(19057, 'Job', 18, 23, 16, ' لأن الله قد أضعف قلبي ، والقدير روعني '),
(19058, 'Job', 18, 23, 17, ' لأني لم أقطع قبل الظلام ، ومن وجهي لم يغط الدجى '),
(19059, 'Job', 18, 24, 1, ' لماذا إذ لم تختبئ الأزمنة من القدير ، لا يرى عارفوه يومه '),
(19060, 'Job', 18, 24, 2, ' ينقلون التخوم . يغتصبون قطيعا ويرعونه '),
(19061, 'Job', 18, 24, 3, ' يستاقون حمار اليتامى ، ويرتهنون ثور الأرملة '),
(19062, 'Job', 18, 24, 4, ' يصدون الفقراء عن الطريق . مساكين الأرض يختبئون جميعا '),
(19063, 'Job', 18, 24, 5, ' ها هم كالفراء في القفر يخرجون إلى عملهم يبكرون للطعام . البادية لهم خبز لأولادهم '),
(19064, 'Job', 18, 24, 6, ' في الحقل يحصدون علفهم ، ويعللون كرم الشرير '),
(19065, 'Job', 18, 24, 7, ' يبيتون عراة بلا لبس ، وليس لهم كسوة في البرد '),
(19066, 'Job', 18, 24, 8, ' يبتلون من مطر الجبال ، ولعدم الملجإ يعتنقون الصخر '),
(19067, 'Job', 18, 24, 9, ' يخطفون اليتيم عن الثدي ، ومن المساكين يرتهنون '),
(19068, 'Job', 18, 24, 10, ' عراة يذهبون بلا لبس ، وجائعين يحملون حزما '),
(19069, 'Job', 18, 24, 11, ' يعصرون الزيت داخل أسوارهم . يدوسون المعاصر ويعطشون '),
(19070, 'Job', 18, 24, 12, ' من الوجع أناس يئنون ، ونفس الجرحى تستغيث ، والله لا ينتبه إلى الظلم '),
(19071, 'Job', 18, 24, 13, ' أولئك يكونون بين المتمردين على النور . لا يعرفون طرقه ولا يلبثون في سبله '),
(19072, 'Job', 18, 24, 14, ' مع النور يقوم القاتل ، يقتل المسكين والفقير ، وفي الليل يكون كاللص '),
(19073, 'Job', 18, 24, 15, ' وعين الزاني تلاحظ العشاء . يقول : لا تراقبني عين . فيجعل سترا على وجهه '),
(19074, 'Job', 18, 24, 16, ' ينقبون البيوت في الظلام . في النهار يغلقون على أنفسهم . لا يعرفون النور '),
(19075, 'Job', 18, 24, 17, ' لأنه سواء عليهم الصباح وظل الموت . لأنهم يعلمون أهوال ظل الموت '),
(19076, 'Job', 18, 24, 18, ' خفيف هو على وجه المياه . ملعون نصيبهم في الأرض . لا يتوجه إلى طريق الكروم '),
(19077, 'Job', 18, 24, 19, ' القحط والقيظ يذهبان بمياه الثلج ، كذا الهاوية بالذين أخطأوا '),
(19078, 'Job', 18, 24, 20, ' تنساه الرحم ، يستحليه الدود . لا يذكر بعد ، وينكسر الأثيم كشجرة '),
(19079, 'Job', 18, 24, 21, ' يسيء إلى العاقر التي لم تلد ، ولا يحسن إلى الأرملة '),
(19080, 'Job', 18, 24, 22, ' يمسك الأعزاء بقوته . يقوم فلا يأمن أحد بحياته '),
(19081, 'Job', 18, 24, 23, ' يعطيه طمأنينة فيتوكل ، ولكن عيناه على طرقهم '),
(19082, 'Job', 18, 24, 24, ' يترفعون قليلا ثم لا يكونون ويحطون . كالكل يجمعون ، وكرأس السنبلة يقطعون '),
(19083, 'Job', 18, 24, 25, ' وإن لم يكن كذا ، فمن يكذبني ويجعل كلامي لا شيئا '),
(19084, 'Job', 18, 25, 1, ' فأجاب بلدد الشوحي وقال '),
(19085, 'Job', 18, 25, 2, ' السلطان والهيبة عنده . هو صانع السلام في أعاليه '),
(19086, 'Job', 18, 25, 3, ' هل من عدد لجنوده ؟ وعلى من لا يشرق نوره '),
(19087, 'Job', 18, 25, 4, ' فكيف يتبرر الإنسان عند الله ؟ وكيف يزكو مولود المرأة '),
(19088, 'Job', 18, 25, 5, ' هوذا نفس القمر لا يضيء ، والكواكب غير نقية في عينيه '),
(19089, 'Job', 18, 25, 6, ' فكم بالحري الإنسان الرمة ، وابن آدم الدود '),
(19090, 'Job', 18, 26, 1, ' فأجاب أيوب وقال '),
(19091, 'Job', 18, 26, 2, ' كيف أعنت من لا قوة له ، وخلصت ذراعا لا عز لها '),
(19092, 'Job', 18, 26, 3, ' كيف أشرت على من لا حكمة له ، وأظهرت الفهم بكثرة '),
(19093, 'Job', 18, 26, 4, ' لمن أعلنت أقوالا ، ونسمة من خرجت منك '),
(19094, 'Job', 18, 26, 5, ' الأخيلة ترتعد من تحت المياه وسكانها '),
(19095, 'Job', 18, 26, 6, ' الهاوية عريانة قدامه ، والهلاك ليس له غطاء '),
(19096, 'Job', 18, 26, 7, ' يمد الشمال على الخلاء ، ويعلق الأرض على لا شيء '),
(19097, 'Job', 18, 26, 8, ' يصر المياه في سحبه فلا يتمزق الغيم تحتها '),
(19098, 'Job', 18, 26, 9, ' يحجب وجه كرسيه باسطا عليه سحابه '),
(19099, 'Job', 18, 26, 10, ' رسم حدا على وجه المياه عند اتصال النور بالظلمة '),
(19100, 'Job', 18, 26, 11, ' أعمدة السماوات ترتعد وترتاع من زجره '),
(19101, 'Job', 18, 26, 12, ' بقوته يزعج البحر ، وبفهمه يسحق رهب '),
(19102, 'Job', 18, 26, 13, ' بنفخته السماوات مسفرة ويداه أبدأتا الحية الهاربة '),
(19103, 'Job', 18, 26, 14, ' ها هذه أطراف طرقه ، وما أخفض الكلام الذي نسمعه منه ، وأما رعد جبروته ، فمن يفهم '),
(19104, 'Job', 18, 27, 1, ' وعاد أيوب ينطق بمثله فقال '),
(19105, 'Job', 18, 27, 2, ' حي هو الله الذي نزع حقي ، والقدير الذي أمر نفسي '),
(19106, 'Job', 18, 27, 3, ' إنه ما دامت نسمتي في ، ونفخة الله في أنفي '),
(19107, 'Job', 18, 27, 4, ' لن تتكلم شفتاي إثما ، ولا يلفظ لساني بغش '),
(19108, 'Job', 18, 27, 5, ' حاشا لي أن أبرركم حتى أسلم الروح لا أعزل كمالي عني '),
(19109, 'Job', 18, 27, 6, ' تمسكت ببري ولا أرخيه . قلبي لا يعير يوما من أيامي '),
(19110, 'Job', 18, 27, 7, ' ليكن عدوي كالشرير ، ومعاندي كفاعل الشر '),
(19111, 'Job', 18, 27, 8, ' لأنه ما هو رجاء الفاجر عندما يقطعه ، عندما يسلب الله نفسه '),
(19112, 'Job', 18, 27, 9, ' أفيسمع الله صراخه إذا جاء عليه ضيق '),
(19113, 'Job', 18, 27, 10, ' أم يتلذذ بالقدير ؟ هل يدعو الله في كل حين '),
(19114, 'Job', 18, 27, 11, ' إني أعلمكم بيد الله . لا أكتم ما هو عند القدير '),
(19115, 'Job', 18, 27, 12, ' ها أنتم كلكم قد رأيتم ، فلماذا تتبطلون تبطلا ؟ قائلين '),
(19116, 'Job', 18, 27, 13, ' هذا نصيب الإنسان الشرير من عند الله ، وميراث العتاة الذي ينالونه من القدير '),
(19117, 'Job', 18, 27, 14, ' إن كثر بنوه فللسيف ، وذريته لا تشبع خبزا '),
(19118, 'Job', 18, 27, 15, ' بقيته تدفن بالموتان ، وأرامله لا تبكي '),
(19119, 'Job', 18, 27, 16, ' إن كنز فضة كالتراب ، وأعد ملابس كالطين '),
(19120, 'Job', 18, 27, 17, ' فهو يعد والبار يلبسه ، والبرئ يقسم الفضة '),
(19121, 'Job', 18, 27, 18, ' يبني بيته كالعث ، أو كمظلة صنعها الناطور '),
(19122, 'Job', 18, 27, 19, ' يضطجع غنيا ولكنه لا يضم . يفتح عينيه ولا يكون '),
(19123, 'Job', 18, 27, 20, ' الأهوال تدركه كالمياه . ليلا تختطفه الزوبعة '),
(19124, 'Job', 18, 27, 21, ' تحمله الشرقية فيذهب ، وتجرفه من مكانه '),
(19125, 'Job', 18, 27, 22, ' يلقي الله عليه ولا يشفق . من يده يهرب هربا '),
(19126, 'Job', 18, 27, 23, ' يصفقون عليه بأيديهم ، ويصفرون عليه من مكانه '),
(19127, 'Job', 18, 28, 1, ' لأنه يوجد للفضة معدن ، وموضع للذهب حيث يمحصونه '),
(19128, 'Job', 18, 28, 2, ' الحديد يستخرج من التراب ، والحجر يسكب نحاسا '),
(19129, 'Job', 18, 28, 3, ' قد جعل للظلمة نهاية ، وإلى كل طرف هو يفحص . حجر الظلمة وظل الموت '),
(19130, 'Job', 18, 28, 4, ' حفر منجما بعيدا عن السكان . بلا موطئ للقدم ، متدلين بعيدين من الناس يتدلدلون '),
(19131, 'Job', 18, 28, 5, ' أرض يخرج منها الخبز ، أسفلها ينقلب كما بالنار '),
(19132, 'Job', 18, 28, 6, ' حجارتها هي موضع الياقوت الأزرق ، وفيها تراب الذهب '),
(19133, 'Job', 18, 28, 7, ' سبيل لم يعرفه كاسر ، ولم تبصره عين باشق '),
(19134, 'Job', 18, 28, 8, ' ولم تدسه أجراء السبع ، ولم يعده الزائر '),
(19135, 'Job', 18, 28, 9, ' إلى الصوان يمد يده . يقلب الجبال من أصولها '),
(19136, 'Job', 18, 28, 10, ' ينقر في الصخور سربا ، وعينه ترى كل ثمين '),
(19137, 'Job', 18, 28, 11, ' يمنع رشح الأنهار ، وأبرز الخفيات إلى النور '),
(19138, 'Job', 18, 28, 12, ' أما الحكمة فمن أين توجد ، وأين هو مكان الفهم '),
(19139, 'Job', 18, 28, 13, ' لا يعرف الإنسان قيمتها ولا توجد في أرض الأحياء '),
(19140, 'Job', 18, 28, 14, ' الغمر يقول : ليست هي في ، والبحر يقول : ليست هي عندي '),
(19141, 'Job', 18, 28, 15, ' لا يعطى ذهب خالص بدلها ، ولا توزن فضة ثمنا لها '),
(19142, 'Job', 18, 28, 16, ' لا توزن بذهب أوفير أو بالجزع الكريم أو الياقوت الأزرق '),
(19143, 'Job', 18, 28, 17, ' لا يعادلها الذهب ولا الزجاج ، ولا تبدل بإناء ذهب إبريز '),
(19144, 'Job', 18, 28, 18, ' لا يذكر المرجان أو البلور ، وتحصيل الحكمة خير من اللآلئ '),
(19145, 'Job', 18, 28, 19, ' لا يعادلها ياقوت كوش الأصفر ، ولا توزن بالذهب الخالص '),
(19146, 'Job', 18, 28, 20, ' فمن أين تأتي الحكمة ، وأين هو مكان الفهم '),
(19147, 'Job', 18, 28, 21, ' إذ أخفيت عن عيون كل حي ، وسترت عن طير السماء '),
(19148, 'Job', 18, 28, 22, ' الهلاك والموت يقولان : بآذاننا قد سمعنا خبرها '),
(19149, 'Job', 18, 28, 23, ' الله يفهم طريقها ، وهو عالم بمكانها '),
(19150, 'Job', 18, 28, 24, ' لأنه هو ينظر إلى أقاصي الأرض . تحت كل السماوات يرى '),
(19151, 'Job', 18, 28, 25, ' ليجعل للريح وزنا ، ويعاير المياه بمقياس '),
(19152, 'Job', 18, 28, 26, ' لما جعل للمطر فريضة ، ومذهبا للصواعق '),
(19153, 'Job', 18, 28, 27, ' حينئذ رآها وأخبر بها ، هيأها وأيضا بحث عنها '),
(19154, 'Job', 18, 28, 28, ' وقال للإنسان : هوذا مخافة الرب هي الحكمة ، والحيدان عن الشر هو الفهم '),
(19155, 'Job', 18, 29, 1, ' وعاد أيوب ينطق بمثله فقال '),
(19156, 'Job', 18, 29, 2, ' يا ليتني كما في الشهور السالفة وكالأيام التي حفظني الله فيها '),
(19157, 'Job', 18, 29, 3, ' حين أضاء سراجه على رأسي ، وبنوره سلكت الظلمة '),
(19158, 'Job', 18, 29, 4, ' كما كنت في أيام خريفي ، ورضا الله على خيمتي '),
(19159, 'Job', 18, 29, 5, ' والقدير بعد معي وحولي غلماني '),
(19160, 'Job', 18, 29, 6, ' إذ غسلت خطواتي باللبن ، والصخر سكب لي جداول زيت '),
(19161, 'Job', 18, 29, 7, ' حين كنت أخرج إلى الباب في القرية ، وأهيئ في الساحة مجلسي '),
(19162, 'Job', 18, 29, 8, ' رآني الغلمان فاختبأوا ، والأشياخ قاموا ووقفوا '),
(19163, 'Job', 18, 29, 9, ' العظماء أمسكوا عن الكلام ، ووضعوا أيديهم على أفواههم '),
(19164, 'Job', 18, 29, 10, ' صوت الشرفاء اختفى ، ولصقت ألسنتهم بأحناكهم '),
(19165, 'Job', 18, 29, 11, ' لأن الأذن سمعت فطوبتني ، والعين رأت فشهدت لي '),
(19166, 'Job', 18, 29, 12, ' لأني أنقذت المسكين المستغيث واليتيم ولا معين له '),
(19167, 'Job', 18, 29, 13, ' بركة الهالك حلت علي ، وجعلت قلب الأرملة يسر '),
(19168, 'Job', 18, 5, 14, ' في النهار يصدمون ظلاما ، ويتلمسون في الظهيرة كما في الليل '),
(19169, 'Job', 18, 5, 15, ' المنجي البائس من السيف ، من فمهم ومن يد القوي '),
(19170, 'Job', 18, 5, 16, ' فيكون للذليل رجاء وتسد الخطية فاها '),
(19171, 'Job', 18, 5, 17, ' هوذا طوبى لرجل يؤدبه الله . فلا ترفض تأديب القدير '),
(19172, 'Job', 18, 5, 18, ' لأنه هو يجرح ويعصب . يسحق ويداه تشفيان '),
(19173, 'Job', 18, 5, 19, ' في ست شدائد ينجيك ، وفي سبع لا يمسك سوء '),
(19174, 'Job', 18, 5, 20, ' في الجوع يفديك من الموت ، وفي الحرب من حد السيف '),
(19175, 'Job', 18, 5, 21, ' من سوط اللسان تختبأ ، فلا تخاف من الخراب إذا جاء '),
(19176, 'Job', 18, 5, 22, ' تضحك على الخراب والمحل ، ولا تخشى وحوش الأرض '),
(19177, 'Job', 18, 5, 23, ' لأنه مع حجارة الحقل عهدك ، ووحوش البرية تسالمك '),
(19178, 'Job', 18, 5, 24, ' فتعلم أن خيمتك آمنة ، وتتعهد مربضك ولا تفقد شيئا '),
(19179, 'Job', 18, 5, 25, ' وتعلم أن زرعك كثير وذريتك كعشب الأرض '),
(19180, 'Job', 18, 5, 26, ' تدخل المدفن في شيخوخة ، كرفع الكدس في أوانه '),
(19181, 'Job', 18, 5, 27, ' ها إن ذا قد بحثنا عنه . كذا هو . فاسمعه واعلم أنت لنفسك '),
(19182, 'Job', 18, 6, 1, ' فأجاب أيوب وقال '),
(19183, 'Job', 18, 6, 2, ' ليت كربي وزن ، ومصيبتي رفعت في الموازين جميعها '),
(19184, 'Job', 18, 6, 3, ' لأنها الآن أثقل من رمل البحر . من أجل ذلك لغا كلامي '),
(19185, 'Job', 18, 6, 4, ' لأن سهام القدير في وحمتها شاربة روحي . أهوال الله مصطفة ضدي '),
(19186, 'Job', 18, 6, 5, ' هل ينهق الفرا على العشب ، أو يخور الثور على علفه '),
(19187, 'Job', 18, 6, 6, ' هل يؤكل المسيخ بلا ملح ، أو يوجد طعم في مرق البقلة '),
(19188, 'Job', 18, 6, 7, ' ماعافت نفسي أن تمسها ، هذه صارت مثل خبزي الكريه '),
(19189, 'Job', 18, 6, 8, ' يا ليت طلبتي تأتي ويعطيني الله رجائي '),
(19190, 'Job', 18, 6, 9, ' أن يرضى الله بأن يسحقني ، ويطلق يده فيقطعني '),
(19191, 'Job', 18, 6, 10, ' فلا تزال تعزيتي وابتهاجي في عذاب ، لا يشفق : أني لم أجحد كلام القدوس '),
(19192, 'Job', 18, 6, 11, ' ما هي قوتي حتى أنتظر ؟ وما هي نهايتي حتى أصبر نفسي '),
(19193, 'Job', 18, 6, 12, ' هل قوتي قوة الحجارة ؟ هل لحمي نحاس '),
(19194, 'Job', 18, 6, 13, ' ألا إنه ليست في معونتي ، والمساعدة مطرودة عني '),
(19195, 'Job', 18, 6, 14, ' حق المحزون معروف من صاحبه ، وإن ترك خشية القدير '),
(19196, 'Job', 18, 6, 15, ' أما إخواني فقد غدروا مثل الغدير . مثل ساقية الوديان يعبرون '),
(19197, 'Job', 18, 6, 16, ' التي هي عكرة من البرد ، ويختفي فيها الجليد '),
(19198, 'Job', 18, 6, 17, ' إذا جرت انقطعت . إذا حميت جفت من مكانها '),
(19199, 'Job', 18, 6, 18, ' يعرج السفر عن طريقهم ، يدخلون التيه فيهلكون '),
(19200, 'Job', 18, 6, 19, ' نظرت قوافل تيماء . سيارة سباء رجوها '),
(19201, 'Job', 18, 6, 20, ' خزوا في ما كانوا مطمئنين . جاءوا إليها فخجلوا '),
(19202, 'Job', 18, 6, 21, ' فالآن قد صرتم مثلها . رأيتم ضربة ففزعتم '),
(19203, 'Job', 18, 6, 22, ' هل قلت : أعطوني شيئا ، أو من مالكم ارشوا من أجلي '),
(19204, 'Job', 18, 6, 23, ' أو نجوني من يد الخصم ، أو من يد العتاة افدوني '),
(19205, 'Job', 18, 6, 24, ' علموني فأنا أسكت ، وفهموني في أي شيء ضللت '),
(19206, 'Job', 18, 6, 25, ' ما أشد الكلام المستقيم ، وأما التوبيخ منكم فعلى ماذا يبرهن '),
(19207, 'Job', 18, 6, 26, ' هل تحسبون أن توبخوا كلمات ، وكلام اليائس للريح '),
(19208, 'Job', 18, 6, 27, ' بل تلقون على اليتيم ، وتحفرون حفرة لصاحبكم '),
(19209, 'Job', 18, 6, 28, ' والآن تفرسوا في ، فإني على وجوهكم لا أكذب '),
(19210, 'Job', 18, 6, 29, ' ارجعوا . لا يكونن ظلم . ارجعوا أيضا . فيه حقي '),
(19211, 'Job', 18, 6, 30, ' هل في لساني ظلم ، أم حنكي لا يميز فسادا '),
(19212, 'Job', 18, 7, 1, ' أليس جهاد للإنسان على الأرض ، وكأيام الأجير أيامه '),
(19213, 'Job', 18, 7, 2, ' كما يتشوق العبد إلى الظل ، وكما يترجى الأجير أجرته '),
(19214, 'Job', 18, 7, 3, ' هكذا تعين لي أشهر سوء ، وليالي شقاء قسمت لي '),
(19215, 'Job', 18, 7, 4, ' إذا اضطجعت أقول : متى أقوم ؟ الليل يطول ، وأشبع قلقا حتى الصبح '),
(19216, 'Job', 18, 7, 5, ' لبس لحمي الدود مع مدر التراب . جلدي كرش وساخ '),
(19217, 'Job', 18, 7, 6, ' أيامي أسرع من الوشيعة ، وتنتهي بغير رجاء '),
(19218, 'Job', 18, 7, 7, ' اذكر أن حياتي إنما هي ريح ، وعيني لا تعود ترى خيرا '),
(19219, 'Job', 18, 7, 8, ' لا تراني عين ناظري . عيناك علي ولست أنا '),
(19220, 'Job', 18, 7, 9, ' السحاب يضمحل ويزول ، هكذا الذي ينزل إلى الهاوية لا يصعد '),
(19221, 'Job', 18, 7, 10, ' لا يرجع بعد إلى بيته ، ولا يعرفه مكانه بعد '),
(19222, 'Job', 18, 7, 11, ' أنا أيضا لا أمنع فمي . أتكلم بضيق روحي . أشكو بمرارة نفسي '),
(19223, 'Job', 18, 7, 12, ' أبحر أنا أم تنين ، حتى جعلت علي حارسا '),
(19224, 'Job', 18, 7, 13, ' إن قلت : فراشي يعزيني ، مضجعي ينزع كربتي '),
(19225, 'Job', 18, 7, 14, ' تريعني بالأحلام ، وترهبني برؤى '),
(19226, 'Job', 18, 7, 15, ' فاختارت نفسي الخنق ، الموت على عظامي هذه '),
(19227, 'Job', 18, 7, 16, ' قد ذبت . لا إلى الأبد أحيا . كف عني لأن أيامي نفخة '),
(19228, 'Job', 18, 7, 17, ' ما هو الإنسان حتى تعتبره ، وحتى تضع عليه قلبك '),
(19229, 'Job', 18, 7, 18, ' وتتعهده كل صباح ، وكل لحظة تمتحنه '),
(19230, 'Job', 18, 7, 19, ' حتى متى لا تلتفت عني ولا ترخيني ريثما أبلع ريقي '),
(19231, 'Job', 18, 7, 20, ' أأخطأت ؟ ماذا أفعل لك يا رقيب الناس ؟ لماذا جعلتني عاثورا لنفسك حتى أكون على نفسي حملا '),
(19232, 'Job', 18, 7, 21, ' ولماذا لا تغفر ذنبي ، ولا تزيل إثمي ؟ لأني الآن أضطجع في التراب ، تطلبني فلا أكون '),
(19233, 'Job', 18, 8, 1, ' فأجاب بلدد الشوحي وقال '),
(19234, 'Job', 18, 8, 2, ' إلى متى تقول هذا ، وتكون أقوال فيك ريحا شديدة '),
(19235, 'Job', 18, 8, 3, ' هل الله يعوج القضاء ، أو القدير يعكس الحق '),
(19236, 'Job', 18, 8, 4, ' إذ أخطأ إليه بنوك ، دفعهم إلى يد معصيتهم '),
(19237, 'Job', 18, 8, 5, ' فإن بكرت أنت إلى الله وتضرعت إلى القدير '),
(19238, 'Job', 18, 8, 6, ' إن كنت أنت زكيا مستقيما ، فإنه الآن يتنبه لك ويسلم مسكن برك '),
(19239, 'Job', 18, 8, 7, ' وإن تكن أولاك صغيرة فآخرتك تكثر جدا '),
(19240, 'Job', 18, 8, 8, ' اسأل القرون الأولى وتأكد مباحث آبائهم '),
(19241, 'Job', 18, 8, 9, ' لأننا نحن من أمس ولا نعلم ، لأن أيامنا على الأرض ظل '),
(19242, 'Job', 18, 8, 10, ' فهلا يعلمونك ؟ يقولون لك ، ومن قلوبهم يخرجون أقوالا قائلين '),
(19243, 'Job', 18, 8, 11, ' هل ينمي البردي في غير الغمقة ، أو تنبت الحلفاء بلا ماء '),
(19244, 'Job', 18, 8, 12, ' وهو بعد في نضارته لم يقطع ، ييبس قبل كل العشب '),
(19245, 'Job', 18, 8, 13, ' هكذا سبل كل الناسين الله ، ورجاء الفاجر يخيب '),
(19246, 'Job', 18, 8, 14, ' فينقطع اعتماده ، ومتكله بيت العنكبوت '),
(19247, 'Job', 18, 8, 15, ' يستند إلى بيته فلا يثبت . يتمسك به فلا يقوم '),
(19248, 'Job', 18, 8, 16, ' هو رطب تجاه الشمس وعلى جنته تنبت خراعيبه '),
(19249, 'Job', 18, 8, 17, ' وأصوله مشتبكة في الرجمة ، فترى محل الحجارة '),
(19250, 'Job', 18, 8, 18, ' إن اقتلعه من مكانه ، يجحده قائلا : ما رأيتك '),
(19251, 'Job', 18, 8, 19, ' هذا هو فرح طريقه ، ومن التراب ينبت آخر '),
(19252, 'Job', 18, 8, 20, ' هوذا الله لا يرفض الكامل ، ولا يأخذ بيد فاعلي الشر '),
(19253, 'Job', 18, 8, 21, ' عندما يملأ فاك ضحكا ، وشفتيك هتافا '),
(19254, 'Job', 18, 8, 22, ' يلبس مبغضوك خزيا ، أما خيمة الأشرار فلا تكون '),
(19255, 'Job', 18, 9, 1, ' فأجاب أيوب وقال '),
(19256, 'Job', 18, 9, 2, ' صحيح . قد علمت أنه كذا ، فكيف يتبرر الإنسان عند الله '),
(19257, 'Job', 18, 9, 3, ' إن شاء أن يحاجه ، لا يجيبه عن واحد من ألف '),
(19258, 'Job', 18, 9, 4, ' هو حكيم القلب وشديد القوة . من تصلب عليه فسلم '),
(19259, 'Job', 18, 9, 5, ' المزحزح الجبال ولا تعلم ، الذي يقلبها في غضبه '),
(19260, 'Job', 18, 9, 6, ' المزعزع الأرض من مقرها ، فتتزلزل أعمدتها '),
(19261, 'Job', 18, 9, 7, ' الآمر الشمس فلا تشرق ، ويختم على النجوم '),
(19262, 'Job', 18, 9, 8, ' الباسط السماوات وحده ، والماشي على أعالي البحر '),
(19263, 'Job', 18, 9, 9, ' صانع النعش والجبار والثريا ومخادع الجنوب '),
(19264, 'Job', 18, 9, 10, ' فاعل عظائم لا تفحص ، وعجائب لا تعد '),
(19265, 'Job', 18, 9, 11, ' هوذا يمر علي ولا أراه ، ويجتاز فلا أشعر به '),
(19266, 'Job', 18, 9, 12, ' إذا خطف فمن يرده ؟ ومن يقول له : ماذا تفعل '),
(19267, 'Job', 18, 9, 13, ' الله لا يرد غضبه . ينحني تحته أعوان رهب '),
(19268, 'Job', 18, 9, 14, ' كم بالأقل أنا أجاوبه وأختار كلامي معه '),
(19269, 'Job', 18, 9, 15, ' لأني وإن تبررت لا أجاوب ، بل أسترحم دياني '),
(19270, 'Job', 18, 9, 16, ' لو دعوت فاستجاب لي ، لما آمنت بأنه سمع صوتي '),
(19271, 'Job', 18, 9, 17, ' ذاك الذي يسحقني بالعاصفة ، ويكثر جروحي بلا سبب '),
(19272, 'Job', 18, 9, 18, ' لا يدعني آخذ نفسي ، ولكن يشبعني مرائر '),
(19273, 'Job', 18, 9, 19, ' إن كان من جهة قوة القوي ، يقول : هأنذا . وإن كان من جهة القضاء يقول : من يحاكمني '),
(19274, 'Job', 18, 9, 20, ' إن تبررت يحكم علي فمي ، وإن كنت كاملا يستذنبني '),
(19275, 'Job', 18, 9, 21, ' كامل أنا . لا أبالي بنفسي . رذلت حياتي '),
(19276, 'Job', 18, 9, 22, ' هي واحدة . لذلك قلت : إن الكامل والشرير هو يفنيهما '),
(19277, 'Job', 18, 9, 23, ' إذا قتل السوط بغتة ، يستهزئ بتجربة الأبرياء '),
(19278, 'Job', 18, 9, 24, ' الأرض مسلمة ليد الشرير . يغشي وجوه قضاتها . وإن لم يكن هو ، فإذا من '),
(19279, 'Job', 18, 9, 25, ' أيامي أسرع من عداء ، تفر ولا ترى خيرا '),
(19280, 'Job', 18, 9, 26, ' تمر مع سفن البردي . كنسر ينقض إلى قنصه '),
(19281, 'Job', 18, 9, 27, ' إن قلت : أنسى كربتي ، أطلق وجهي وأتبلج '),
(19282, 'Job', 18, 9, 28, ' أخاف من كل أوجاعي عالما أنك لا تبرئني '),
(19283, 'Job', 18, 9, 29, ' أنا مستذنب ، فلماذا أتعب عبثا '),
(19284, 'Job', 18, 9, 30, ' ولو اغتسلت في الثلج ، ونظفت يدي بالإشنان '),
(19285, 'Job', 18, 9, 31, ' فإنك في النقع تغمسني حتى تكرهني ثيابي '),
(19286, 'Job', 18, 9, 32, ' لأنه ليس هو إنسانا مثلي فأجاوبه ، فنأتي جميعا إلى المحاكمة '),
(19287, 'Job', 18, 9, 33, ' ليس بيننا مصالح يضع يده على كلينا '),
(19288, 'Job', 18, 9, 34, ' ليرفع عني عصاه ولا يبغتني رعبه '),
(19289, 'Job', 18, 9, 35, ' إذا أتكلم ولا أخافه ، لأني لست هكذا عند نفسي '),
(19290, 'Job', 18, 10, 1, ' قد كرهت نفسي حياتي . أسيب شكواي . أتكلم في مرارة نفسي '),
(19291, 'Job', 18, 10, 2, ' قائلا لله : لا تستذنبني . فهمني لماذا تخاصمني '),
(19292, 'Job', 18, 10, 3, ' أحسن عندك أن تظلم ، أن ترذل عمل يديك ، وتشرق على مشورة الأشرار '),
(19293, 'Job', 18, 10, 4, ' ألك عينا بشر ، أم كنظر الإنسان تنظر '),
(19294, 'Job', 18, 10, 5, ' أأيامك كأيام الإنسان ، أم سنوك كأيام الرجل '),
(19295, 'Job', 18, 10, 6, ' حتى تبحث عن إثمي وتفتش على خطيتي '),
(19296, 'Job', 18, 10, 7, ' في علمك أني لست مذنبا ، ولا منقذ من يدك '),
(19297, 'Job', 18, 10, 8, ' يداك كونتاني وصنعتاني كلي جميعا ، أفتبتلعني '),
(19298, 'Job', 18, 10, 9, ' اذكر أنك جبلتني كالطين ، أفتعيدني إلى التراب '),
(19299, 'Job', 18, 10, 10, ' ألم تصبني كاللبن ، وخثرتني كالجبن '),
(19300, 'Job', 18, 10, 11, ' كسوتني جلدا ولحما ، فنسجتني بعظام وعصب '),
(19301, 'Job', 18, 10, 12, ' منحتني حياة ورحمة ، وحفظت عنايتك روحي '),
(19302, 'Job', 18, 10, 13, ' لكنك كتمت هذه في قلبك . علمت أن هذا عندك '),
(19303, 'Job', 18, 10, 14, ' إن أخطأت تلاحظني ولا تبرئني من إثمي '),
(19304, 'Job', 18, 10, 15, ' إن أذنبت فويل لي ، وإن تبررت لا أرفع رأسي . إني شبعان هوانا وناظر مذلتي '),
(19305, 'Job', 18, 10, 16, ' وإن ارتفع تصطادني كأسد ، ثم تعود وتتجبر علي '),
(19306, 'Job', 18, 10, 17, ' تجدد شهودك تجاهي ، وتزيد غضبك علي . نوب وجيش ضدي '),
(19307, 'Job', 18, 10, 18, ' فلماذا أخرجتني من الرحم ؟ كنت قد أسلمت الروح ولم ترني عين '),
(19308, 'Job', 18, 10, 19, ' فكنت كأني لم أكن ، فأقاد من الرحم إلى القبر '),
(19309, 'Job', 18, 10, 20, ' أليست أيامي قليلة ؟ اترك كف عني فأتبلج قليلا '),
(19310, 'Job', 18, 10, 21, ' قبل أن أذهب ولا أعود . إلى أرض ظلمة وظل الموت '),
(19311, 'Job', 18, 10, 22, ' أرض ظلام مثل دجى ظل الموت وبلا ترتيب ، وإشراقها كالدجى '),
(19312, 'Job', 18, 11, 1, ' فأجاب صوفر النعماتي وقال '),
(19313, 'Job', 18, 29, 14, ' لبست البر فكساني . كجبة وعمامة كان عدلي '),
(19314, 'Job', 18, 29, 15, ' كنت عيونا للعمي ، وأرجلا للعرج '),
(19315, 'Job', 18, 29, 16, ' أب أنا للفقراء ، ودعوى لم أعرفها فحصت عنها '),
(19316, 'Job', 18, 29, 17, ' هشمت أضراس الظالم ، ومن بين أسنانه خطفت الفريسة '),
(19317, 'Job', 18, 29, 18, ' فقلت : إني في وكري أسلم الروح ، ومثل السمندل أكثر أياما '),
(19318, 'Job', 18, 29, 19, ' أصلي كان منبسطا إلى المياه ، والطل بات على أغصاني '),
(19319, 'Job', 18, 29, 20, ' كرامتي بقيت حديثة عندي ، وقوسي تجددت في يدي '),
(19320, 'Job', 18, 29, 21, ' لي سمعوا وانتظروا ، ونصتوا عند مشورتي '),
(19321, 'Job', 18, 29, 22, ' بعد كلامي لم يثنوا ، وقولي قطر عليهم '),
(19322, 'Job', 18, 29, 23, ' وانتظروني مثل المطر ، وفغروا أفواههم كما للمطر المتأخر '),
(19323, 'Job', 18, 29, 24, ' إن ضحكت عليهم لم يصدقوا ، ونور وجهي لم يعبسوا '),
(19324, 'Job', 18, 29, 25, ' كنت أختار طريقهم وأجلس رأسا ، وأسكن كملك في جيش ، كمن يعزي النائحين '),
(19325, 'Job', 18, 30, 1, ' وأما الآن فقد ضحك علي أصاغري أياما ، الذين كنت أستنكف من أن أجعل آباءهم مع كلاب غنمي '),
(19326, 'Job', 18, 30, 2, ' قوة أيديهم أيضا ما هي لي . فيهم عجزت الشيخوخة '),
(19327, 'Job', 18, 30, 3, ' في العوز والمحل مهزولون ، عارقون اليابسة التي هي منذ أمس خراب وخربة '),
(19328, 'Job', 18, 30, 4, ' الذين يقطفون الملاح عند الشيح ، وأصول الرتم خبزهم '),
(19329, 'Job', 18, 30, 5, ' من الوسط يطردون . يصيحون عليهم كما على لص '),
(19330, 'Job', 18, 30, 6, ' للسكن في أودية مرعبة وثقب التراب والصخور '),
(19331, 'Job', 18, 30, 7, ' بين الشيح ينهقون . تحت العوسج ينكبون '),
(19332, 'Job', 18, 30, 8, ' أبناء الحماقة ، بل أبناء أناس بلا اسم ، سيطوا من الأرض '),
(19333, 'Job', 18, 30, 9, ' أما الآن فصرت أغنيتهم ، وأصبحت لهم مثلا '),
(19334, 'Job', 18, 30, 10, ' يكرهونني . يبتعدون عني ، وأمام وجهي لم يمسكوا عن البسق '),
(19335, 'Job', 18, 30, 11, ' لأنه أطلق العنان وقهرني ، فنزعوا الزمام قدامي '),
(19336, 'Job', 18, 30, 12, ' عن اليمين الفروخ يقومون يزيحون رجلي ، ويعدون علي طرقهم للبوار '),
(19337, 'Job', 18, 30, 13, ' أفسدوا سبلي . أعانوا على سقوطي . لا مساعد عليهم '),
(19338, 'Job', 18, 30, 14, ' يأتون كصدع عريض . تحت الهدة يتدحرجون '),
(19339, 'Job', 18, 30, 15, ' انقلبت علي أهوال . طردت كالريح نعمتي ، فعبرت كالسحاب سعادتي '),
(19340, 'Job', 18, 30, 16, ' فالآن انهالت نفسي علي ، وأخذتني أيام المذلة '),
(19341, 'Job', 18, 30, 17, ' الليل ينخر عظامي في ، وعارقي لا تهجع '),
(19342, 'Job', 18, 30, 18, ' بكثرة الشدة تنكر لبسي . مثل جيب قميصي حزمتني '),
(19343, 'Job', 18, 30, 19, ' قد طرحني في الوحل ، فأشبهت التراب والرماد '),
(19344, 'Job', 18, 30, 20, ' إليك أصرخ فما تستجيب لي . أقوم فما تنتبه إلي '),
(19345, 'Job', 18, 30, 21, ' تحولت إلى جاف من نحوي . بقدرة يدك تضطهدني '),
(19346, 'Job', 18, 30, 22, ' حملتني ، أركبتني الريح وذوبتني تشوها '),
(19347, 'Job', 18, 30, 23, ' لأني أعلم أنك إلى الموت تعيدني ، وإلى بيت ميعاد كل حي '),
(19348, 'Job', 18, 30, 24, ' ولكن في الخراب ألا يمد يدا ؟ في البلية ألا يستغيث عليها '),
(19349, 'Job', 18, 30, 25, ' ألم أبك لمن عسر يومه ؟ ألم تكتئب نفسي على المسكين '),
(19350, 'Job', 18, 30, 26, ' حينما ترجيت الخير جاء الشر ، وانتظرت النور فجاء الدجى '),
(19351, 'Job', 18, 30, 27, ' أمعائي تغلي ولا تكف . تقدمتني أيام المذلة '),
(19352, 'Job', 18, 30, 28, ' اسوددت لكن بلا شمس . قمت في الجماعة أصرخ '),
(19353, 'Job', 18, 30, 29, ' صرت أخا للذئاب ، وصاحبا لرئال النعام '),
(19354, 'Job', 18, 30, 30, ' حرش جلدي علي وعظامي احترت من الحرارة في '),
(19355, 'Job', 18, 30, 31, ' صار عودي للنوح ، ومزماري لصوت الباكين '),
(19356, 'Job', 18, 31, 1, ' عهدا قطعت لعيني ، فكيف أتطلع في عذراء '),
(19357, 'Job', 18, 31, 2, ' وما هي قسمة الله من فوق ، ونصيب القدير من الأعالي '),
(19358, 'Job', 18, 31, 3, ' أليس البوار لعامل الشر ، والنكر لفاعلي الإثم '),
(19359, 'Job', 18, 31, 4, ' أليس هو ينظر طرقي ، ويحصي جميع خطواتي '),
(19360, 'Job', 18, 31, 5, ' إن كنت قد سلكت مع الكذب ، أو أسرعت رجلي إلى الغش '),
(19361, 'Job', 18, 31, 6, ' ليزني في ميزان الحق ، فيعرف الله كمالي '),
(19362, 'Job', 18, 31, 7, ' إن حادت خطواتي عن الطريق ، وذهب قلبي وراء عيني ، أو لصق عيب بكفي '),
(19363, 'Job', 18, 31, 8, ' أزرع وغيري يأكل ، وفروعي تستأصل '),
(19364, 'Job', 18, 31, 9, ' إن غوي قلبي على امرأة ، أو كمنت على باب قريبي '),
(19365, 'Job', 18, 31, 10, ' فلتطحن امرأتي لآخر ، ولينحن عليها آخرون '),
(19366, 'Job', 18, 31, 11, ' لأن هذه رذيلة ، وهي إثم يعرض للقضاة '),
(19367, 'Job', 18, 31, 12, ' لأنها نار تأكل حتى إلى الهلاك ، وتستأصل كل محصولي '),
(19368, 'Job', 18, 31, 13, ' إن كنت رفضت حق عبدي وأمتي في دعواهما علي '),
(19369, 'Job', 18, 31, 14, ' فماذا كنت أصنع حين يقوم الله ؟ وإذا افتقد ، فبماذا أجيبه '),
(19370, 'Job', 18, 31, 15, ' أوليس صانعي في البطن صانعه ، وقد صورنا واحد في الرحم '),
(19371, 'Job', 18, 31, 16, ' إن كنت منعت المساكين عن مرادهم ، أو أفنيت عيني الأرملة '),
(19372, 'Job', 18, 31, 17, ' أو أكلت لقمتي وحدي فما أكل منها اليتيم '),
(19373, 'Job', 18, 31, 18, ' بل منذ صباي كبر عندي كأب ، ومن بطن أمي هديتها '),
(19374, 'Job', 18, 31, 19, ' إن كنت رأيت هالكا لعدم اللبس أو فقيرا بلا كسوة '),
(19375, 'Job', 18, 31, 20, ' إن لم تباركني حقواه وقد استدفأ بجزة غنمي '),
(19376, 'Job', 18, 31, 21, ' إن كنت قد هززت يدي على اليتيم لما رأيت عوني في الباب '),
(19377, 'Job', 18, 31, 22, ' فلتسقط عضدي من كتفي ، ولتنكسر ذراعي من قصبتها '),
(19378, 'Job', 18, 31, 23, ' لأن البوار من الله رعب علي ، ومن جلاله لم أستطع '),
(19379, 'Job', 18, 31, 24, ' إن كنت قد جعلت الذهب عمدتي ، أو قلت للإبريز : أنت متكلي '),
(19380, 'Job', 18, 31, 25, ' إن كنت قد فرحت إذ كثرت ثروتي ولأن يدي وجدت كثيرا '),
(19381, 'Job', 18, 31, 26, ' إن كنت قد نظرت إلى النور حين ضاء ، أو إلى القمر يسير بالبهاء '),
(19382, 'Job', 18, 31, 27, ' وغوي قلبي سرا ، ولثم يدي فمي '),
(19383, 'Job', 18, 31, 28, ' فهذا أيضا إثم يعرض للقضاة ، لأني أكون قد جحدت الله من فوق '),
(19384, 'Job', 18, 31, 29, ' إن كنت قد فرحت ببلية مبغضي أو شمت حين أصابه سوء '),
(19385, 'Job', 18, 31, 30, ' بل لم أدع حنكي يخطئ في طلب نفسه بلعنة '),
(19386, 'Job', 18, 31, 31, ' إن كان أهل خيمتي لم يقولوا : من يأتي بأحد لم يشبع من طعامه '),
(19387, 'Job', 18, 34, 8, ' ويسير متحدا مع فاعلي الإثم ، وذاهبا مع أهل الشر '),
(19388, 'Job', 18, 34, 9, ' لأنه قال : لا ينتفع الإنسان بكونه مرضيا عند الله '),
(19389, 'Job', 18, 34, 10, ' لأجل ذلك اسمعوا لي يا ذوي الألباب . حاشا لله من الشر ، وللقدير من الظلم '),
(19390, 'Job', 18, 34, 11, ' لأنه يجازي الإنسان على فعله ، وينيل الرجل كطريقه '),
(19391, 'Job', 18, 34, 12, ' فحقا إن الله لا يفعل سوءا ، والقدير لا يعوج القضاء '),
(19392, 'Job', 18, 34, 13, ' من وكله بالأرض ، ومن صنع المسكونة كلها '),
(19393, 'Job', 18, 34, 14, ' إن جعل عليه قلبه ، إن جمع إلى نفسه روحه ونسمته '),
(19394, 'Job', 18, 34, 15, ' يسلم الروح كل بشر جميعا ، ويعود الإنسان إلى التراب '),
(19395, 'Job', 18, 34, 16, ' فإن كان لك فهم فاسمع هذا ، واصغ إلى صوت كلماتي '),
(19396, 'Job', 18, 34, 17, ' ألعل من يبغض الحق يتسلط ، أم البار الكبير تستذنب '),
(19397, 'Job', 18, 34, 18, ' أيقال للملك : يا لئيم ، وللندباء : يا أشرار '),
(19398, 'Job', 18, 34, 19, ' الذي لا يحابي بوجوه الرؤساء ، ولا يعتبر موسعا دون فقير . لأنهم جميعهم عمل يديه '),
(19399, 'Job', 18, 34, 20, ' بغتة يموتون وفي نصف الليل . يرتج الشعب ويزولون ، وينزع الأعزاء لا بيد '),
(19400, 'Job', 18, 34, 21, ' لأن عينيه على طرق الإنسان ، وهو يرى كل خطواته '),
(19401, 'Job', 18, 34, 22, ' لا ظلام ولا ظل موت حيث تختفي عمال الإثم '),
(19402, 'Job', 18, 34, 23, ' لأنه لا يلاحظ الإنسان زمانا للدخول في المحاكمة مع الله '),
(19403, 'Job', 18, 34, 24, ' يحطم الأعزاء من دون فحص ، ويقيم آخرين مكانهم '),
(19404, 'Job', 18, 34, 25, ' لكنه يعرف أعمالهم ، ويقلبهم ليلا فينسحقون '),
(19405, 'Job', 18, 34, 26, ' لكونهم أشرارا ، يصفقهم في مرأى الناظرين '),
(19406, 'Job', 18, 34, 27, ' لأنهم انصرفوا من ورائه ، وكل طرقه لم يتأملوها '),
(19407, 'Job', 18, 34, 28, ' حتى بلغوا إليه صراخ المسكين ، فسمع زعقة البائسين '),
(19408, 'Job', 18, 34, 29, ' إذا هو سكن ، فمن يشغب ؟ وإذا حجب وجهه ، فمن يراه سواء كان على أمة أو على إنسان '),
(19409, 'Job', 18, 34, 30, ' حتى لا يملك الفاجر ولا يكون شركا للشعب '),
(19410, 'Job', 18, 34, 31, ' ولكن هل لله قال : احتملت . لا أعود أفسد '),
(19411, 'Job', 18, 34, 32, ' ما لم أبصره فأرنيه أنت . إن كنت قد فعلت إثما فلا أعود أفعله '),
(19412, 'Job', 18, 34, 33, ' هل كرأيك يجازيه ، قائلا : لأنك رفضت ؟ فأنت تختار لا أنا ، وبما تعرفه تكلم '),
(19413, 'Job', 18, 34, 34, ' ذوو الألباب يقولون لي ، بل الرجل الحكيم الذي يسمعني يقول '),
(19414, 'Job', 18, 34, 35, ' إن أيوب يتكلم بلا معرفة ، وكلامه ليس بتعقل '),
(19415, 'Job', 18, 34, 36, ' فليت أيوب كان يمتحن إلى الغاية من أجل أجوبته كأهل الإثم '),
(19416, 'Job', 18, 34, 37, ' لكنه أضاف إلى خطيته معصية . يصفق بيننا ، ويكثر كلامه على الله '),
(19417, 'Job', 18, 35, 1, ' فأجاب أليهو وقال '),
(19418, 'Job', 18, 35, 2, ' أتحسب هذا حقا ؟ قلت : أنا أبر من الله '),
(19419, 'Job', 18, 35, 3, ' لأنك قلت : ماذا يفيدك ؟ بماذا أنتفع أكثر من خطيتي '),
(19420, 'Job', 18, 35, 4, ' أنا أرد عليك كلاما ، وعلى أصحابك معك '),
(19421, 'Job', 18, 35, 5, ' انظر إلى السماوات وأبصر ، ولاحظ الغمام . إنها أعلى منك '),
(19422, 'Job', 18, 35, 6, ' إن أخطأت فماذا فعلت به ؟ وإن كثرت معاصيك فماذا عملت له '),
(19423, 'Job', 18, 35, 7, ' إن كنت بارا فماذا أعطيته ؟ أو ماذا يأخذه من يدك '),
(19424, 'Job', 18, 35, 8, ' لرجل مثلك شرك ، ولابن آدم برك '),
(19425, 'Job', 18, 35, 9, ' من كثرة المظالم يصرخون . يستغيثون من ذراع الأعزاء '),
(19426, 'Job', 18, 35, 10, ' ولم يقولوا : أين الله صانعي ، مؤتي الأغاني في الليل '),
(19427, 'Job', 18, 35, 11, ' الذي يعلمنا أكثر من وحوش الأرض ، ويجعلنا أحكم من طيور السماء '),
(19428, 'Job', 18, 35, 12, ' ثم يصرخون من كبرياء الأشرار ولا يستجيب '),
(19429, 'Job', 18, 35, 13, ' ولكن الله لا يسمع كذبا ، والقدير لا ينظر إليه '),
(19430, 'Job', 18, 35, 14, ' فإذا قلت إنك لست تراه ، فالدعوى قدامه ، فاصبر له '),
(19431, 'Job', 18, 35, 15, ' وأما الآن فلأن غضبه لا يطالب ، ولا يبالي بكثرة الزلات '),
(19432, 'Job', 18, 35, 16, ' فغر أيوب فاه بالباطل ، وكبر الكلام بلا معرفة '),
(19433, 'Job', 18, 36, 1, ' وعاد أليهو فقال '),
(19434, 'Job', 18, 36, 2, ' اصبر علي قليلا ، فأبدي لك أنه بعد لأجل الله كلام '),
(19435, 'Job', 18, 36, 3, ' أحمل معرفتي من بعيد ، وأنسب برا لصانعي '),
(19436, 'Job', 18, 36, 4, ' حقا لا يكذب كلامي . صحيح المعرفة عندك '),
(19437, 'Job', 18, 36, 5, ' هوذا الله عزيز ، ولكنه لا يرذل أحدا . عزيز قدرة القلب '),
(19438, 'Job', 18, 36, 6, ' لا يحيي الشرير ، بل يجري قضاء البائسين '),
(19439, 'Job', 18, 36, 7, ' لا يحول عينيه عن البار ، بل مع الملوك يجلسهم على الكرسي أبدا ، فيرتفعون '),
(19440, 'Job', 18, 36, 8, ' إن أوثقوا بالقيود ، إن أخذوا في حبالة الذل '),
(19441, 'Job', 18, 36, 9, ' فيظهر لهم أفعالهم ومعاصيهم ، لأنهم تجبروا '),
(19442, 'Job', 18, 36, 10, ' ويفتح آذانهم للإنذار ، ويأمر بأن يرجعوا عن الإثم '),
(19443, 'Job', 18, 36, 11, ' إن سمعوا وأطاعوا قضوا أيامهم بالخير وسنيهم بالنعم '),
(19444, 'Job', 18, 36, 12, ' وإن لم يسمعوا ، فبحربة الموت يزولون ، ويموتون بعدم المعرفة '),
(19445, 'Job', 18, 36, 13, ' أما فجار القلب فيذخرون غضبا . لا يستغيثون إذا هو قيدهم '),
(19446, 'Job', 18, 36, 14, ' تموت نفسهم في الصبا وحياتهم بين المأبونين '),
(19447, 'Job', 18, 36, 15, ' ينجي البائس في ذله ، ويفتح آذانهم في الضيق '),
(19448, 'Job', 18, 36, 16, ' وأيضا يقودك من وجه الضيق إلى رحب لا حصر فيه ، ويملأ مؤونة مائدتك دهنا '),
(19449, 'Job', 18, 36, 17, ' حجة الشرير أكملت ، فالحجة والقضاء يمسكانك '),
(19450, 'Job', 18, 36, 18, ' عند غضبه لعله يقودك بصفقة . فكثرة الفدية لا تفكك '),
(19451, 'Job', 18, 36, 19, ' هل يعتبر غناك ؟ لا التبر ولا جميع قوى الثروة '),
(19452, 'Job', 18, 36, 20, ' لا تشتاق إلى الليل الذي يرفع شعوبا من مواضعهم '),
(19453, 'Job', 18, 36, 21, ' احذر . لا تلتفت إلى الإثم لأنك اخترت هذا على الذل '),
(19454, 'Job', 18, 36, 22, ' هوذا الله يتعالى بقدرته . من مثله معلما '),
(19455, 'Job', 18, 36, 23, ' من فرض عليه طريقه ، أو من يقول له : قد فعلت شرا '),
(19456, 'Job', 18, 36, 24, ' اذكر أن تعظم عمله الذي يغني به الناس '),
(19457, 'Job', 18, 36, 25, ' كل إنسان يبصر به . الناس ينظرونه من بعيد '),
(19458, 'Job', 18, 36, 26, ' هوذا الله عظيم ولا نعرفه وعدد سنيه لا يفحص '),
(19459, 'Job', 18, 36, 27, ' لأنه يجذب قطار الماء . تسح مطرا من ضبابها '),
(19460, 'Job', 18, 36, 28, ' الذي تهطله السحب وتقطره على أناس كثيرين '),
(19461, 'Job', 18, 36, 29, ' فهل يعلل أحد عن شق الغيم أو قصيف مظلته '),
(19462, 'Job', 18, 36, 30, ' هوذا بسط نوره على نفسه ، ثم يتغطى بأصول اليم '),
(19463, 'Job', 18, 36, 31, ' لأنه بهذه يدين الشعوب ، ويرزق القوت بكثرة '),
(19464, 'Job', 18, 36, 32, ' يغطي كفيه بالنور ، ويأمره على العدو '),
(19465, 'Job', 18, 36, 33, ' يخبر به رعده ، المواشي أيضا بصعوده '),
(19466, 'Job', 18, 37, 1, ' فلهذا اضطرب قلبي وخفق من موضعه '),
(19467, 'Job', 18, 37, 2, ' اسمعوا سماعا رعد صوته والرمزمة الخارجة من فيه '),
(19468, 'Job', 18, 37, 3, ' تحت كل السماوات يطلقها ، كذا نوره إلى أكناف الأرض '),
(19469, 'Job', 18, 37, 4, ' بعد يزمجر صوت ، يرعد بصوت جلاله ، ولا يؤخرها إذ سمع صوته '),
(19470, 'Job', 18, 37, 5, ' الله يرعد بصوته عجبا . يصنع عظائم لا ندركها '),
(19471, 'Job', 18, 37, 6, ' لأنه يقول للثلج : اسقط على الأرض . كذا لوابل المطر ، وابل أمطار عزه '),
(19472, 'Job', 18, 37, 7, ' يختم على يد كل إنسان ، ليعلم كل الناس خالقهم '),
(19473, 'Job', 18, 37, 8, ' فتدخل الحيوانات المآوي ، وتستقر في أوجرتها '),
(19474, 'Job', 18, 37, 9, ' من الجنوب تأتي الأعصار ، ومن الشمال البرد '),
(19475, 'Job', 18, 37, 10, ' من نسمة الله يجعل الجمد ، وتتضيق سعة المياه '),
(19476, 'Job', 18, 37, 11, ' أيضا بري يطرح الغيم . يبدد سحاب نوره '),
(19477, 'Job', 18, 37, 12, ' فهي مدورة متقلبة بإدارته ، لتفعل كل ما يأمر به على وجه الأرض المسكونة '),
(19478, 'Job', 18, 37, 13, ' سواء كان للتأديب أو لأرضه أو للرحمة يرسلها '),
(19479, 'Job', 18, 37, 14, ' انصت إلى هذا يا أيوب ، وقف وتأمل بعجائب الله '),
(19480, 'Job', 18, 37, 15, ' أتدرك انتباه الله إليها ، أو إضاءة نور سحابه '),
(19481, 'Job', 18, 37, 16, ' أتدرك موازنة السحاب ، معجزات الكامل المعارف '),
(19482, 'Job', 18, 37, 17, ' كيف تسخن ثيابك إذا سكنت الأرض من ريح الجنوب '),
(19483, 'Job', 18, 37, 18, ' هل صفحت معه الجلد الممكن كالمرآة المسبوكة '),
(19484, 'Job', 18, 37, 19, ' علمنا ما نقول له . إننا لا نحسن الكلام بسبب الظلمة '),
(19485, 'Job', 18, 37, 20, ' هل يقص عليه كلامي إذا تكلمت ؟ هل ينطق الإنسان لكي يبتلع '),
(19486, 'Job', 18, 37, 21, ' والآن لا يرى النور الباهر الذي هو في الجلد ، ثم تعبر الريح فتنقيه '),
(19487, 'Job', 18, 37, 22, ' من الشمال يأتي ذهب . عند الله جلال مرهب '),
(19488, 'Job', 18, 37, 23, ' القدير لا ندركه . عظيم القوة والحق ، وكثير البر . لا يجاوب '),
(19489, 'Job', 18, 37, 24, ' لذلك فلتخفه الناس . كل حكيم القلب لا يراعي '),
(19490, 'Job', 18, 38, 1, ' فأجاب الرب أيوب من العاصفة وقال '),
(19491, 'Job', 18, 38, 2, ' من هذا الذي يظلم القضاء بكلام بلا معرفة '),
(19492, 'Job', 18, 38, 3, ' اشدد الآن حقويك كرجل ، فإني أسألك فتعلمني '),
(19493, 'Job', 18, 38, 4, ' أين كنت حين أسست الأرض ؟ أخبر إن كان عندك فهم '),
(19494, 'Job', 18, 38, 5, ' من وضع قياسها ؟ لأنك تعلم أو من مد عليها مطمارا '),
(19495, 'Job', 18, 38, 6, ' على أي شيء قرت قواعدها ؟ أو من وضع حجر زاويتها '),
(19496, 'Job', 18, 38, 7, ' عندما ترنمت كواكب الصبح معا ، وهتف جميع بني الله '),
(19497, 'Job', 18, 38, 8, ' ومن حجز البحر بمصاريع حين اندفق فخرج من الرحم '),
(19498, 'Job', 18, 38, 9, ' إذ جعلت السحاب لباسه ، والضباب قماطه '),
(19499, 'Job', 18, 38, 10, ' وجزمت عليه حدي ، وأقمت له مغاليق ومصاريع '),
(19500, 'Job', 18, 38, 11, ' وقلت : إلى هنا تأتي ولا تتعدى ، وهنا تتخم كبرياء لججك '),
(19501, 'Job', 18, 38, 12, ' هل في أيامك أمرت الصبح ؟ هل عرفت الفجر موضعه '),
(19502, 'Job', 18, 38, 13, ' ليمسك بأكناف الأرض ، فينفض الأشرار منها '),
(19503, 'Job', 18, 38, 14, ' تتحول كطين الخاتم ، وتقف كأنها لابسة '),
(19504, 'Job', 18, 38, 15, ' ويمنع عن الأشرار نورهم ، وتنكسر الذراع المرتفعة '),
(19505, 'Job', 18, 38, 16, ' هل انتهيت إلى ينابيع البحر ، أو في مقصورة الغمر تمشيت '),
(19506, 'Job', 18, 38, 17, ' هل انكشفت لك أبواب الموت ، أو عاينت أبواب ظل الموت '),
(19507, 'Job', 18, 38, 18, ' هل أدركت عرض الأرض ؟ أخبر إن عرفته كله '),
(19508, 'Job', 18, 38, 19, ' أين الطريق إلى حيث يسكن النور ؟ والظلمة أين مقامها '),
(19509, 'Job', 18, 38, 20, ' حتى تأخذها إلى تخومها وتعرف سبل بيتها '),
(19510, 'Job', 18, 38, 21, ' تعلم ، لأنك حينئذ كنت قد ولدت ، وعدد أيامك كثير '),
(19511, 'Job', 18, 38, 22, ' أدخلت إلى خزائن الثلج ، أم أبصرت مخازن البرد '),
(19512, 'Job', 18, 38, 23, ' التي أبقيتها لوقت الضر ، ليوم القتال والحرب '),
(19513, 'Job', 18, 38, 24, ' في أي طريق يتوزع النور ، وتتفرق الشرقية على الأرض '),
(19514, 'Job', 18, 38, 25, ' من فرع قنوات للهطل ، وطريقا للصواعق '),
(19515, 'Job', 18, 38, 26, ' ليمطر على أرض حيث لا إنسان ، على قفر لا أحد فيه '),
(19516, 'Job', 18, 38, 27, ' ليروي البلقع والخلاء وينبت مخرج العشب '),
(19517, 'Job', 18, 38, 28, ' هل للمطر أب ؟ ومن ولد مآجل الطل '),
(19518, 'Job', 18, 38, 29, ' من بطن من خرج الجمد ؟ صقيع السماء ، من ولده '),
(19519, 'Job', 18, 38, 30, ' كحجر صارت المياه . اختبأت . وتلكد وجه الغمر '),
(19520, 'Job', 18, 38, 31, ' هل تربط أنت عقد الثريا ، أو تفك ربط الجبار '),
(19521, 'Job', 18, 38, 32, ' أتخرج المنازل في أوقاتها وتهدي النعش مع بناته '),
(19522, 'Job', 18, 38, 33, ' هل عرفت سنن السماوات ، أو جعلت تسلطها على الأرض '),
(19523, 'Job', 18, 38, 34, ' أترفع صوتك إلى السحب فيغطيك فيض المياه '),
(19524, 'Job', 18, 38, 35, ' أترسل البروق فتذهب وتقول لك : ها نحن '),
(19525, 'Job', 18, 38, 36, ' من وضع في الطخاء حكمة ، أو من أظهر في الشهب فطنة '),
(19526, 'Job', 18, 38, 37, ' من يحصي الغيوم بالحكمة ، ومن يسكب أزقاق السماوات '),
(19527, 'Job', 18, 38, 38, ' إذ ينسبك التراب سبكا ويتلاصق المدر '),
(19528, 'Job', 18, 38, 39, ' أتصطاد للبوة فريسة ، أم تشبع نفس الأشبال '),
(19529, 'Job', 18, 38, 40, ' حين تجرمز في عريسها وتجلس في عيصها للكمون '),
(19530, 'Job', 18, 38, 41, ' من يهيئ للغراب صيده ، إذ تنعب فراخه إلى الله ، وتتردد لعدم القوت '),
(19531, 'Job', 18, 39, 1, ' أتعرف وقت ولادة وعول الصخور ، أو تلاحظ مخاض الأيائل '),
(19532, 'Job', 18, 39, 2, ' أتحسب الشهور التي تكملها ، أو تعلم ميقات ولادتهن '),
(19533, 'Job', 18, 39, 3, ' يبركن ويضعن أولادهن . يدفعن أوجاعهن '),
(19534, 'Job', 18, 31, 32, ' غريب لم يبت في الخارج . فتحت للمسافر أبوابي '),
(19535, 'Job', 18, 31, 33, ' إن كنت قد كتمت كالناس ذنبي لإخفاء إثمي في حضني '),
(19536, 'Job', 18, 31, 34, ' إذ رهبت جمهورا غفيرا ، وروعتني إهانة العشائر ، فكففت ولم أخرج من الباب '),
(19537, 'Job', 18, 31, 35, ' من لي بمن يسمعني ؟ هوذا إمضائي . ليجبني القدير . ومن لي بشكوى كتبها خصمي '),
(19538, 'Job', 18, 31, 36, ' فكنت أحملها على كتفي . كنت أعصبها تاجا لي '),
(19539, 'Job', 18, 31, 37, ' كنت أخبره بعدد خطواتي وأدنو منه كشريف '),
(19540, 'Job', 18, 31, 38, ' إن كانت أرضي قد صرخت علي وتباكت أتلامها جميعا '),
(19541, 'Job', 18, 31, 39, ' إن كنت قد أكلت غلتها بلا فضة ، أو أطفأت أنفس أصحابها '),
(19542, 'Job', 18, 31, 40, ' فعوض الحنطة لينبت شوك ، وبدل الشعير زوان '),
(19543, 'Job', 18, 31, 0, ' تمت أقوال أيوب. '),
(19544, 'Job', 18, 32, 1, ' فكف هؤلاء الرجال الثلاثة عن مجاوبة أيوب لكونه بارا في عيني نفسه '),
(19545, 'Job', 18, 32, 2, ' فحمي غضب أليهو بن برخئيل البوزي من عشيرة رام . على أيوب حمي غضبه لأنه حسب نفسه أبر من الله '),
(19546, 'Job', 18, 32, 3, ' وعلى أصحابه الثلاثة حمي غضبه ، لأنهم لم يجدوا جوابا واستذنبوا أيوب '),
(19547, 'Job', 18, 32, 4, ' وكان أليهو قد صبر على أيوب بالكلام ، لأنهم أكثر منه أياما '),
(19548, 'Job', 18, 32, 5, ' فلما رأى أليهو أنه لا جواب في أفواه الرجال الثلاثة حمي غضبه '),
(19549, 'Job', 18, 32, 6, ' فأجاب أليهو بن برخئيل البوزي وقال : أنا صغير في الأيام وأنتم شيوخ ، لأجل ذلك خفت وخشيت أن أبدي لكم رأيي '),
(19550, 'Job', 18, 32, 7, ' قلت : الأيام تتكلم وكثرة السنين تظهر حكمة '),
(19551, 'Job', 18, 32, 8, ' ولكن في الناس روحا ، ونسمة القدير تعقلهم '),
(19552, 'Job', 18, 32, 9, ' ليس الكثيرو الأيام حكماء ، ولا الشيوخ يفهمون الحق '),
(19553, 'Job', 18, 32, 10, ' لذلك قلت : اسمعوني . أنا أيضا أبدي رأيي '),
(19554, 'Job', 18, 32, 11, ' هأنذا قد صبرت لكلامكم . أصغيت إلى حججكم حتى فحصتم الأقوال '),
(19555, 'Job', 18, 32, 12, ' فتأملت فيكم وإذ ليس من حج أيوب ، ولا جواب منكم لكلامه '),
(19556, 'Job', 18, 32, 13, ' فلا تقولوا : قد وجدنا حكمة . الله يغلبه لا الإنسان '),
(19557, 'Job', 18, 32, 14, ' فإنه لم يوجه إلي كلامه ولا أرد عليه أنا بكلامكم '),
(19558, 'Job', 18, 32, 15, ' تحيروا . لم يجيبوا بعد . انتزع عنهم الكلام '),
(19559, 'Job', 18, 32, 16, ' فانتظرت لأنهم لم يتكلموا . لأنهم وقفوا ، لم يجيبوا بعد '),
(19560, 'Job', 18, 32, 17, ' فأجيب أنا أيضا حصتي ، وأبدي أنا أيضا رأيي '),
(19561, 'Job', 18, 32, 18, ' لأني ملآن أقوالا . روح باطني تضايقني '),
(19562, 'Job', 18, 32, 19, ' هوذا بطني كخمر لم تفتح . كالزقاق الجديدة يكاد ينشق '),
(19563, 'Job', 18, 32, 20, ' أتكلم فأفرج . أفتح شفتي وأجيب '),
(19564, 'Job', 18, 32, 21, ' لا أحابين وجه رجل ولا أملث إنسانا '),
(19565, 'Job', 18, 32, 22, ' لأني لا أعرف الملث . لأنه عن قليل يأخذني صانعي '),
(19566, 'Job', 18, 33, 1, ' ولكن اسمع الآن يا أيوب أقوالي ، واصغ إلى كل كلامي '),
(19567, 'Job', 18, 33, 2, ' هأنذا قد فتحت فمي . لساني نطق في حنكي '),
(19568, 'Job', 18, 33, 3, ' استقامة قلبي كلامي ، ومعرفة شفتي هما تنطقان بها خالصة '),
(19569, 'Job', 18, 33, 4, ' روح الله صنعني ونسمة القدير أحيتني '),
(19570, 'Job', 18, 33, 5, ' إن استطعت فأجبني . أحسن الدعوى أمامي . انتصب '),
(19571, 'Job', 18, 33, 6, ' هأنذا حسب قولك عوضا عن الله . أنا أيضا من الطين تقرصت '),
(19572, 'Job', 18, 33, 7, ' هوذا هيبتي لا ترهبك وجلالي لا يثقل عليك '),
(19573, 'Job', 18, 33, 8, ' إنك قد قلت في مسامعي ، وصوت أقوالك سمعت '),
(19574, 'Job', 18, 33, 9, ' قلت : أنا بريء بلا ذنب . زكي أنا ولا إثم لي '),
(19575, 'Job', 18, 33, 10, ' هوذا يطلب علي علل عداوة . يحسبني عدوا له '),
(19576, 'Job', 18, 33, 11, ' وضع رجلي في المقطرة . يراقب كل طرقي '),
(19577, 'Job', 18, 33, 12, ' ها إنك في هذا لم تصب . أنا أجيبك ، لأن الله أعظم من الإنسان '),
(19578, 'Job', 18, 33, 13, ' لماذا تخاصمه ؟ لأن كل أموره لا يجاوب عنها '),
(19579, 'Job', 18, 33, 14, ' لكن الله يتكلم مرة ، وباثنتين لا يلاحظ الإنسان '),
(19580, 'Job', 18, 33, 15, ' في حلم في رؤيا الليل ، عند سقوط سبات على الناس ، في النعاس على المضجع '),
(19581, 'Job', 18, 33, 16, ' حينئذ يكشف آذان الناس ويختم على تأديبهم '),
(19582, 'Job', 18, 33, 17, ' ليحول الإنسان عن عمله ، ويكتم الكبرياء عن الرجل '),
(19583, 'Job', 18, 33, 18, ' ليمنع نفسه عن الحفرة وحياته من الزوال بحربة الموت '),
(19584, 'Job', 18, 33, 19, ' أيضا يؤدب بالوجع على مضجعه ، ومخاصمة عظامه دائمة '),
(19585, 'Job', 18, 33, 20, ' فتكره حياته خبزا ، ونفسه الطعام الشهي '),
(19586, 'Job', 18, 33, 21, ' فيبلى لحمه عن العيان ، وتنبري عظامه فلا ترى '),
(19587, 'Job', 18, 33, 22, ' وتقرب نفسه إلى القبر ، وحياته إلى المميتين '),
(19588, 'Job', 18, 33, 23, ' إن وجد عنده مرسل ، وسيط واحد من ألف ليعلن للإنسان استقامته '),
(19589, 'Job', 18, 33, 24, ' يتراءف عليه ويقول : أطلقه عن الهبوط إلى الحفرة ، قد وجدت فدية '),
(19590, 'Job', 18, 33, 25, ' يصير لحمه أغض من لحم الصبي ، ويعود إلى أيام شبابه '),
(19591, 'Job', 18, 33, 26, ' يصلي إلى الله فيرضى عنه ، ويعاين وجهه بهتاف فيرد على الإنسان بره '),
(19592, 'Job', 18, 33, 27, ' يغني بين الناس فيقول : قد أخطأت ، وعوجت المستقيم ، ولم أجاز عليه '),
(19593, 'Job', 18, 33, 28, ' فدى نفسي من العبور إلى الحفرة ، فترى حياتي النور '),
(19594, 'Job', 18, 33, 29, ' هوذا كل هذه يفعلها الله مرتين وثلاثا بالإنسان '),
(19595, 'Job', 18, 33, 30, ' ليرد نفسه من الحفرة ، ليستنير بنور الأحياء '),
(19596, 'Job', 18, 33, 31, ' فاصغ يا أيوب واستمع لي . انصت فأنا أتكلم '),
(19597, 'Job', 18, 33, 32, ' إن كان عندك كلام فأجبني . تكلم . فإني أريد تبريرك '),
(19598, 'Job', 18, 33, 33, ' وإلا فاستمع أنت لي . انصت فأعلمك الحكمة '),
(19599, 'Job', 18, 34, 1, ' فأجاب أليهو وقال '),
(19600, 'Job', 18, 34, 2, ' اسمعوا أقوالي أيها الحكماء ، واصغوا لي أيها العارفون '),
(19601, 'Job', 18, 34, 3, ' لأن الأذن تمتحن الأقوال ، كما أن الحنك يذوق طعاما '),
(19602, 'Job', 18, 34, 4, ' لنمتحن لأنفسنا الحق ، ونعرف بين أنفسنا ما هو طيب '),
(19603, 'Job', 18, 34, 5, ' لأن أيوب قال : تبررت ، والله نزع حقي '),
(19604, 'Job', 18, 34, 6, ' عند محاكمتي أكذب . جرحي عديم الشفاء من دون ذنب '),
(19605, 'Job', 18, 34, 7, ' فأي إنسان كأيوب يشرب الهزء كالماء '),
(19606, 'Job', 18, 39, 4, ' تبلغ أولادهن . تربو في البرية . تخرج ولا تعود إليهن '),
(19607, 'Job', 18, 39, 5, ' من سرح الفراء حرا ، ومن فك ربط حمار الوحش '),
(19608, 'Job', 18, 39, 6, ' الذي جعلت البرية بيته والسباخ مسكنه '),
(19609, 'Job', 18, 39, 7, ' يضحك على جمهور القرية . لا يسمع زجر السائق '),
(19610, 'Job', 18, 39, 8, ' دائرة الجبال مرعاه ، وعلى كل خضرة يفتش '),
(19611, 'Job', 18, 39, 9, ' أيرضى الثور الوحشي أن يخدمك ، أم يبيت عند معلفك '),
(19612, 'Job', 18, 39, 10, ' أتربط الثور الوحشي برباطه في التلم ، أم يمهد الأودية وراءك '),
(19613, 'Job', 18, 39, 11, ' أتثق به لأن قوته عظيمة ، أو تترك له تعبك '),
(19614, 'Job', 18, 39, 12, ' أتأتمنه أنه يأتي بزرعك ويجمع إلى بيدرك '),
(19615, 'Job', 18, 39, 13, ' جناح النعامة يرفرف . أفهو منكب رؤوف ، أم ريش '),
(19616, 'Job', 18, 39, 14, ' لأنها تترك بيضها وتحميه في التراب '),
(19617, 'Job', 18, 39, 15, ' وتنسى أن الرجل تضغطه ، أو حيوان البر يدوسه '),
(19618, 'Job', 18, 39, 16, ' تقسو على أولادها كأنها ليست لها . باطل تعبها بلا أسف '),
(19619, 'Job', 18, 39, 17, ' لأن الله قد أنساها الحكمة ، ولم يقسم لها فهما '),
(19620, 'Job', 18, 39, 18, ' عندما تحوذ نفسها إلى العلاء ، تضحك على الفرس وعلى راكبه '),
(19621, 'Job', 18, 39, 19, ' هل أنت تعطي الفرس قوته وتكسو عنقه عرفا '),
(19622, 'Job', 18, 39, 20, ' أتوثبه كجرادة ؟ نفخ منخره مرعب '),
(19623, 'Job', 18, 39, 21, ' يبحث في الوادي وينفز ببأس . يخرج للقاء الأسلحة '),
(19624, 'Job', 18, 39, 22, ' يضحك على الخوف ولا يرتاع ، ولا يرجع عن السيف '),
(19625, 'Job', 18, 39, 23, ' عليه تصل السهام وسنان الرمح والمزراق '),
(19626, 'Job', 18, 39, 24, ' في وثبه ورجزه يلتهم الأرض ، ولا يؤمن أنه صوت البوق '),
(19627, 'Job', 18, 39, 25, ' عند نفخ البوق يقول : هه ومن بعيد يستروح القتال صياح القواد والهتاف '),
(19628, 'Job', 18, 39, 26, ' أمن فهمك يستقل العقاب وينشر جناحيه نحو الجنوب '),
(19629, 'Job', 18, 39, 27, ' أو بأمرك يحلق النسر ويعلي وكره '),
(19630, 'Job', 18, 39, 28, ' يسكن الصخر ويبيت على سن الصخر والمعقل '),
(19631, 'Job', 18, 39, 29, ' من هناك يتحسس قوته . تبصره عيناه من بعيد '),
(19632, 'Job', 18, 39, 30, ' فراخه تحسو الدم ، وحيثما تكن القتلى فهناك هو '),
(19633, 'Job', 18, 40, 1, ' فأجاب الرب أيوب فقال '),
(19634, 'Job', 18, 40, 2, ' هل يخاصم القدير موبخه ، أم المحاج الله يجاوبه '),
(19635, 'Job', 18, 40, 3, ' فأجاب أيوب الرب وقال '),
(19636, 'Job', 18, 40, 4, ' ها أنا حقير ، فماذا أجاوبك ؟ وضعت يدي على فمي '),
(19637, 'Job', 18, 40, 5, ' مرة تكلمت فلا أجيب ، ومرتين فلا أزيد '),
(19638, 'Job', 18, 40, 6, ' فأجاب الرب أيوب من العاصفة فقال '),
(19639, 'Job', 18, 40, 7, ' الآن شد حقويك كرجل . أسألك فتعلمني '),
(19640, 'Job', 18, 40, 8, ' لعلك تناقض حكمي ، تستذنبني لكي تتبرر أنت '),
(19641, 'Job', 18, 40, 9, ' هل لك ذراع كما لله ، وبصوت مثل صوته ترعد '),
(19642, 'Job', 18, 40, 10, ' تزين الآن بالجلال والعز ، والبس المجد والبهاء '),
(19643, 'Job', 18, 40, 11, ' فرق فيض غضبك ، وانظر كل متعظم واخفضه '),
(19644, 'Job', 18, 40, 12, ' انظر إلى كل متعظم وذلله ، ودس الأشرار في مكانهم '),
(19645, 'Job', 18, 40, 13, ' اطمرهم في التراب معا ، واحبس وجوههم في الظلام '),
(19646, 'Job', 18, 40, 14, ' فأنا أيضا أحمدك لأن يمينك تخلصك '),
(19647, 'Job', 18, 40, 15, ' هوذا بهيموث الذي صنعته معك يأكل العشب مثل البقر '),
(19648, 'Job', 18, 40, 16, ' ها هي قوته في متنيه ، وشدته في عضل بطنه '),
(19649, 'Job', 18, 40, 17, ' يخفض ذنبه كأرزة . عروق فخذيه مضفورة '),
(19650, 'Job', 18, 40, 18, ' عظامه أنابيب نحاس ، جرمها حديد ممطول '),
(19651, 'Job', 18, 40, 19, ' هو أول أعمال الله . الذي صنعه أعطاه سيفه '),
(19652, 'Job', 18, 40, 20, ' لأن الجبال تخرج له مرعى ، وجميع وحوش البر تلعب هناك ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(19653, 'Job', 18, 40, 21, ' تحت السدرات يضطجع في ستر القصب والغمقة '),
(19654, 'Job', 18, 40, 22, ' تظلله السدرات بظلها . يحيط به صفصاف السواقي '),
(19655, 'Job', 18, 40, 23, ' هوذا النهر يفيض فلا يفر هو . يطمئن ولو اندفق الأردن في فمه '),
(19656, 'Job', 18, 40, 24, ' هل يؤخذ من أمامه ؟ هل يثقب أنفه بخزامة '),
(19657, 'Job', 18, 41, 1, ' أتصطاد لوياثان بشص ، أو تضغط لسانه بحبل '),
(19658, 'Job', 18, 41, 2, ' أتضع أسلة في خطمه ، أم تثقب فكه بخزامة '),
(19659, 'Job', 18, 41, 3, ' أيكثر التضرعات إليك ، أم يتكلم معك باللين '),
(19660, 'Job', 18, 41, 4, ' هل يقطع معك عهدا فتتخذه عبدا مؤبدا '),
(19661, 'Job', 18, 41, 5, ' أتلعب معه كالعصفور ، أو تربطه لأجل فتياتك '),
(19662, 'Job', 18, 41, 6, ' هل تحفر جماعة الصيادين لأجله حفرة ، أو يقسمونه بين الكنعانيين '),
(19663, 'Job', 18, 41, 7, ' أتملأ جلده حرابا ورأسه بإلال السمك '),
(19664, 'Job', 18, 41, 8, ' ضع يدك عليه . لا تعد تذكر القتال '),
(19665, 'Job', 18, 41, 9, ' هوذا الرجاء به كاذب . ألا يكب أيضا برؤيته '),
(19666, 'Job', 18, 41, 10, ' ليس من شجاع يوقظه ، فمن يقف إذا بوجهي '),
(19667, 'Job', 18, 41, 11, ' من تقدمني فأوفيه ؟ ما تحت كل السماوات هو لي '),
(19668, 'Job', 18, 41, 12, ' لا أسكت عن أعضائه ، وخبر قوته وبهجة عدته '),
(19669, 'Job', 18, 41, 13, ' من يكشف وجه لبسه ، ومن يدنو من مثنى لجمته '),
(19670, 'Job', 18, 41, 14, ' من يفتح مصراعي فمه ؟ دائرة أسنانه مرعبة '),
(19671, 'Job', 18, 41, 15, ' فخره مجان مانعة محكمة مضغوطة بخاتم '),
(19672, 'Job', 18, 41, 16, ' الواحد يمس الآخر ، فالريح لا تدخل بينها '),
(19673, 'Job', 18, 41, 17, ' كل منها ملتصق بصاحبه ، متلكدة لا تنفصل '),
(19674, 'Job', 18, 41, 18, ' عطاسه يبعث نورا ، وعيناه كهدب الصبح '),
(19675, 'Job', 18, 41, 19, ' من فيه تخرج مصابيح . شرار نار تتطاير منه '),
(19676, 'Job', 18, 41, 20, ' من منخريه يخرج دخان كأنه من قدر منفوخ أو من مرجل '),
(19677, 'Job', 18, 41, 21, ' نفسه يشعل جمرا ، ولهيب يخرج من فيه '),
(19678, 'Job', 18, 41, 22, ' في عنقه تبيت القوة ، وأمامه يدوس الهول '),
(19679, 'Job', 18, 41, 23, ' مطاوي لحمه متلاصقة مسبوكة عليه لا تتحرك '),
(19680, 'Job', 18, 41, 24, ' قلبه صلب كالحجر ، وقاس كالرحى '),
(19681, 'Job', 18, 41, 25, ' عند نهوضه تفزع الأقوياء . من المخاوف يتيهون '),
(19682, 'Job', 18, 41, 26, ' سيف الذي يلحقه لا يقوم ، ولا رمح ولا مزراق ولا درع '),
(19683, 'Job', 18, 41, 27, ' يحسب الحديد كالتبن ، والنحاس كالعود النخر '),
(19684, 'Job', 18, 41, 28, ' لا يستفزه نبل القوس . حجارة المقلاع ترجع عنه كالقش '),
(19685, 'Job', 18, 41, 29, ' يحسب المقمعة كقش ، ويضحك على اهتزاز الرمح '),
(19686, 'Job', 18, 41, 30, ' تحته قطع خزف حادة . يمدد نورجا على الطين '),
(19687, 'Job', 18, 41, 31, ' يجعل العمق يغلي كالقدر ، ويجعل البحر كقدر عطارة '),
(19688, 'Job', 18, 41, 32, ' يضيء السبيل وراءه فيحسب اللج أشيب '),
(19689, 'Job', 18, 41, 33, ' ليس له في الأرض نظير . صنع لعدم الخوف '),
(19690, 'Job', 18, 41, 34, ' يشرف على كل متعال . هو ملك على كل بني الكبرياء '),
(19691, 'Job', 18, 42, 1, ' فأجاب أيوب الرب فقال '),
(19692, 'Job', 18, 42, 2, ' قد علمت أنك تستطيع كل شيء ، ولا يعسر عليك أمر '),
(19693, 'Job', 18, 42, 3, ' فمن ذا الذي يخفي القضاء بلا معرفة ؟ ولكني قد نطقت بما لم أفهم . بعجائب فوقي لم أعرفها '),
(19694, 'Job', 18, 42, 4, ' اسمع الآن وأنا أتكلم . أسألك فتعلمني '),
(19695, 'Job', 18, 42, 5, ' بسمع الأذن قد سمعت عنك ، والآن رأتك عيني '),
(19696, 'Job', 18, 42, 6, ' لذلك أرفض وأندم في التراب والرماد '),
(19697, 'Job', 18, 42, 7, ' وكان بعدما تكلم الرب مع أيوب بهذا الكلام ، أن الرب قال لأليفاز التيماني : قد احتمى غضبي عليك وعلى كلا صاحبيك ، لأنكم لم تقولوا في الصواب كعبدي أيوب '),
(19698, 'Job', 18, 42, 8, ' والآن فخذوا لأنفسكم سبعة ثيران وسبعة كباش واذهبوا إلى عبدي أيوب ، وأصعدوا محرقة لأجل أنفسكم ، وعبدي أيوب يصلي من أجلكم ، لأني أرفع وجهه لئلا أصنع معكم حسب حماقتكم ، لأنكم لم تقولوا في الصواب كعبدي أيوب '),
(19699, 'Job', 18, 42, 9, ' فذهب أليفاز التيماني وبلدد الشوحي وصوفر النعماتي ، وفعلوا كما قال الرب لهم . ورفع الرب وجه أيوب '),
(19700, 'Job', 18, 42, 10, ' ورد الرب سبي أيوب لما صلى لأجل أصحابه ، وزاد الرب على كل ما كان لأيوب ضعفا '),
(19701, 'Job', 18, 42, 11, ' فجاء إليه كل إخوته وكل أخواته وكل معارفه من قبل ، وأكلوا معه خبزا في بيته ، ورثوا له وعزوه عن كل الشر الذي جلبه الرب عليه ، وأعطاه كل منهم قسيطة واحدة ، وكل واحد قرطا من ذهب '),
(19702, 'Job', 18, 42, 12, ' وبارك الرب آخرة أيوب أكثر من أولاه . وكان له أربعة عشر ألفا من الغنم ، وستة آلاف من الإبل ، وألف فدان من البقر ، وألف أتان '),
(19703, 'Job', 18, 42, 13, ' وكان له سبعة بنين وثلاث بنات '),
(19704, 'Job', 18, 42, 14, ' وسمى اسم الأولى يميمة ، واسم الثانية قصيعة ، واسم الثالثة قرن هفوك '),
(19705, 'Job', 18, 42, 15, ' ولم توجد نساء جميلات كبنات أيوب في كل الأرض ، وأعطاهن أبوهن ميراثا بين إخوتهن '),
(19706, 'Job', 18, 42, 16, ' وعاش أيوب بعد هذا مئة وأربعين سنة ، ورأى بنيه وبني بنيه إلى أربعة أجيال '),
(19707, 'Job', 18, 42, 17, ' ثم مات أيوب شيخا وشبعان الأيام '),
(19708, 'Joel', 29, 1, 1, ' قول الرب الذي صار إلى يوئيل بن فثوئيل '),
(19709, 'Joel', 29, 1, 2, ' اسمعوا هذا أيها الشيوخ ، وأصغوا يا جميع سكان الأرض هل حدث هذا في أيامكم ، أو في أيام آبائكم '),
(19710, 'Joel', 29, 1, 3, ' أخبروا بنيكم عنه ، وبنوكم بنيهم ، وبنوهم دورا آخر '),
(19711, 'Joel', 29, 1, 4, ' فضلة القمص أكلها الزحاف ، وفضلة الزحاف أكلها الغوغاء ، وفضلة الغوغاء أكلها الطيار '),
(19712, 'Joel', 29, 1, 5, ' اصحوا أيها السكارى ، وابكوا وولولوا يا جميع شاربي الخمر ، على العصير لأنه انقطع عن أفواهكم '),
(19713, 'Joel', 29, 1, 6, ' إذ قد صعدت على أرضي أمة قوية بلا عدد ، أسنانها أسنان الأسد ، ولها أضراس اللبوة '),
(19714, 'Joel', 29, 1, 7, ' جعلت كرمتي خربة وتينتي متهشمة . قد قشرتها وطرحتها فابيضت قضبانها '),
(19715, 'Joel', 29, 1, 8, ' نوحي يا أرضي كعروس مؤتزرة بمسح من أجل بعل صباها '),
(19716, 'Joel', 29, 1, 9, ' انقطعت التقدمة والسكيب عن بيت الرب . ناحت الكهنة خدام الرب '),
(19717, 'Joel', 29, 1, 10, ' تلف الحقل ، ناحت الأرض لأنه قد تلف القمح ، جف المسطار ، ذبل الزيت '),
(19718, 'Joel', 29, 1, 11, ' خجل الفلاحون ، ولول الكرامون على الحنطة وعلى الشعير ، لأنه قد تلف حصيد الحقل '),
(19719, 'Joel', 29, 1, 12, ' الجفنة يبست ، والتينة ذبلت . الرمانة والنخلة والتفاحة ، كل أشجار الحقل يبست . إنه قد يبست البهجة من بني البشر '),
(19720, 'Joel', 29, 1, 13, ' تنطقوا ونوحوا أيها الكهنة . ولولوا يا خدام المذبح . ادخلوا بيتوا بالمسوح يا خدام إلهي ، لأنه قد امتنع عن بيت إلهكم التقدمة والسكيب '),
(19721, 'Joel', 29, 1, 14, ' قدسوا صوما . نادوا باعتكاف . اجمعوا الشيوخ ، جميع سكان الأرض إلى بيت الرب إلهكم واصرخوا إلى الرب '),
(19722, 'Joel', 29, 1, 15, ' آه على اليوم لأن يوم الرب قريب . يأتي كخراب من القادر على كل شيء '),
(19723, 'Joel', 29, 1, 16, ' أما انقطع الطعام تجاه عيوننا ؟ الفرح والابتهاج عن بيت إلهنا '),
(19724, 'Joel', 29, 1, 17, ' عفنت الحبوب تحت مدرها . خلت الأهراء . انهدمت المخازن لأنه قد يبس القمح '),
(19725, 'Joel', 29, 1, 18, ' كم تئن البهائم هامت قطعان البقر لأن ليس لها مرعى . حتى قطعان الغنم تفنى '),
(19726, 'Joel', 29, 1, 19, ' إليك يارب أصرخ ، لأن نارا قد أكلت مراعي البرية ، ولهيبا أحرق جميع أشجار الحقل '),
(19727, 'Joel', 29, 1, 20, ' حتى بهائم الصحراء تنظر إليك ، لأن جداول المياه قد جفت ، والنار أكلت مراعي البرية '),
(19728, 'Joel', 29, 2, 1, ' اضربوا بالبوق في صهيون . صوتوا في جبل قدسي ليرتعد جميع سكان الأرض لأن يوم الرب قادم ، لأنه قريب '),
(19729, 'Joel', 29, 2, 2, ' يوم ظلام وقتام ، يوم غيم وضباب ، مثل الفجر ممتدا على الجبال . شعب كثير وقوي لم يكن نظيره منذ الأزل ، ولا يكون أيضا بعده إلى سني دور فدور '),
(19730, 'Joel', 29, 2, 3, ' قدامه نار تأكل ، وخلفه لهيب يحرق . الأرض قدامه كجنة عدن وخلفه قفر خرب ، ولا تكون منه نجاة '),
(19731, 'Joel', 29, 2, 4, ' كمنظر الخيل منظره ، ومثل الأفراس يركضون '),
(19732, 'Joel', 29, 2, 5, ' كصريف المركبات على رؤوس الجبال يثبون . كزفير لهيب نار تأكل قشا . كقوم أقوياء مصطفين للقتال '),
(19733, 'Joel', 29, 2, 6, ' منه ترتعد الشعوب . كل الوجوه تجمع حمرة '),
(19734, 'Joel', 29, 2, 7, ' يجرون كأبطال . يصعدون السور كرجال الحرب ، ويمشون كل واحد في طريقه ، ولا يغيرون سبلهم '),
(19735, 'Joel', 29, 2, 8, ' ولا يزاحم بعضهم بعضا . يمشون كل واحد في سبيله ، وبين الأسلحة يقعون ولا ينكسرون '),
(19736, 'Joel', 29, 2, 9, ' يتراكضون في المدينة . يجرون على السور . يصعدون إلى البيوت . يدخلون من الكوى كاللص '),
(19737, 'Joel', 29, 2, 10, ' قدامه ترتعد الأرض وترجف السماء . الشمس والقمر يظلمان ، والنجوم تحجز لمعانها '),
(19738, 'Joel', 29, 2, 11, ' والرب يعطي صوته أمام جيشه . إن عسكره كثير جدا . فإن صانع قوله قوي ، لأن يوم الرب عظيم ومخوف جدا ، فمن يطيقه '),
(19739, 'Joel', 29, 2, 12, ' ولكن الآن ، يقول الرب ، ارجعوا إلي بكل قلوبكم ، وبالصوم والبكاء والنوح '),
(19740, 'Joel', 29, 2, 13, ' ومزقوا قلوبكم لا ثيابكم . وارجعوا إلى الرب إلهكم لأنه رؤوف رحيم ، بطيء الغضب وكثير الرأفة ويندم على الشر '),
(19741, 'Joel', 29, 2, 14, ' لعله يرجع ويندم ، فيبقي وراءه بركة ، تقدمة وسكيبا للرب إلهكم '),
(19742, 'Joel', 29, 2, 15, ' اضربوا بالبوق في صهيون . قدسوا صوما . نادوا باعتكاف '),
(19743, 'Joel', 29, 2, 16, ' اجمعوا الشعب . قدسوا الجماعة . احشدوا الشيوخ . اجمعوا الأطفال وراضعي الثدي . ليخرج العريس من مخدعه والعروس من حجلتها '),
(19744, 'Joel', 29, 2, 17, ' ليبك الكهنة خدام الرب بين الرواق والمذبح ، ويقولوا : اشفق يارب على شعبك ، ولا تسلم ميراثك للعار حتى تجعلهم الأمم مثلا . لماذا يقولون بين الشعوب : أين إلههم '),
(19745, 'Joel', 29, 2, 18, ' فيغار الرب لأرضه ويرق لشعبه '),
(19746, 'Joel', 29, 2, 19, ' ويجيب الرب ويقول لشعبه : هأنذا مرسل لكم قمحا ومسطارا وزيتا لتشبعوا منها ، ولا أجعلكم أيضا عارا بين الأمم '),
(19747, 'Joel', 29, 2, 20, ' والشمالي أبعده عنكم ، وأطرده إلى أرض ناشفة ومقفرة . مقدمته إلى البحر الشرقي ، وساقته إلى البحر الغربي ، فيصعد نتنه ، وتطلع زهمته ، لأنه قد تصلف في عمله '),
(19748, 'Joel', 29, 2, 21, ' لا تخافي أيتها الأرض . ابتهجي وافرحي لأن الرب يعظم عمله '),
(19749, 'Joel', 29, 2, 22, ' لا تخافي يا بهائم الصحراء ، فإن مراعي البرية تنبت ، لأن الأشجار تحمل ثمرها ، التينة والكرمة تعطيان قوتهما '),
(19750, 'Joel', 29, 2, 23, ' ويا بني صهيون ، ابتهجوا وافرحوا بالرب إلهكم ، لأنه يعطيكم المطر المبكر على حقه ، وينزل عليكم مطرا مبكرا ومتأخرا في أول الوقت '),
(19751, 'Joel', 29, 2, 24, ' فتملأ البيادر حنطة ، وتفيض حياض المعاصر خمرا وزيتا '),
(19752, 'Joel', 29, 2, 25, ' وأعوض لكم عن السنين التي أكلها الجراد ، الغوغاء والطيار والقمص ، جيشي العظيم الذي أرسلته عليكم '),
(19753, 'Joel', 29, 2, 26, ' فتأكلون أكلا وتشبعون وتسبحون اسم الرب إلهكم الذي صنع معكم عجبا ، ولا يخزى شعبي إلى الأبد '),
(19754, 'Joel', 29, 2, 27, ' وتعلمون أني أنا في وسط إسرائيل ، وأني أنا الرب إلهكم وليس غيري . ولا يخزى شعبي إلى الأبد '),
(19755, 'Joel', 29, 2, 28, ' ويكون بعد ذلك أني أسكب روحي على كل بشر ، فيتنبأ بنوكم وبناتكم ، ويحلم شيوخكم أحلاما ، ويرى شبابكم رؤى '),
(19756, 'Joel', 29, 2, 29, ' وعلى العبيد أيضا وعلى الإماء أسكب روحي في تلك الأيام '),
(19757, 'Joel', 29, 2, 30, ' وأعطي عجائب في السماء والأرض ، دما ونارا وأعمدة دخان '),
(19758, 'Joel', 29, 2, 31, ' تتحول الشمس إلى ظلمة ، والقمر إلى دم قبل أن يجيء يوم الرب العظيم المخوف '),
(19759, 'Joel', 29, 2, 32, ' ويكون أن كل من يدعو باسم الرب ينجو . لأنه في جبل صهيون وفي أورشليم تكون نجاة ، كما قال الرب . وبين الباقين من يدعوه الرب '),
(19760, 'Joel', 29, 3, 1, ' لأنه هوذا في تلك الأيام وفي ذلك الوقت ، عندما أرد سبي يهوذا وأورشليم '),
(19761, 'Joel', 29, 3, 2, ' أجمع كل الأمم وأنزلهم إلى وادي يهوشافاط ، وأحاكمهم هناك على شعبي وميراثي إسرائيل الذين بددوهم بين الأمم وقسموا أرضي '),
(19762, 'Joel', 29, 3, 3, ' وألقوا قرعة على شعبي ، وأعطوا الصبي بزانية ، وباعوا البنت بخمر ليشربوا '),
(19763, 'Joel', 29, 3, 4, ' وماذا أنتن لي يا صور وصيدون وجميع دائرة فلسطين ؟ هل تكافئونني عن العمل ، أم هل تصنعون بي شيئا ؟ سريعا بالعجل أرد عملكم على رؤوسكم '),
(19764, 'Joel', 29, 3, 5, ' لأنكم أخذتم فضتي وذهبي ، وأدخلتم نفائسي الجيدة إلى هياكلكم '),
(19765, 'Joel', 29, 3, 6, ' وبعتم بني يهوذا وبني أورشليم لبني الياوانيين لكي تبعدوهم عن تخومهم '),
(19766, 'Joel', 29, 3, 7, ' هأنذا أنهضهم من الموضع الذي بعتموهم إليه ، وأرد عملكم على رؤوسكم '),
(19767, 'Joel', 29, 3, 8, ' وأبيع بنيكم وبناتكم بيد بني يهوذا ليبيعوهم للسبائيين ، لأمة بعيدة ، لأن الرب قد تكلم '),
(19768, 'Joel', 29, 3, 9, ' نادوا بهذا بين الأمم . قدسوا حربا . أنهضوا الأبطال . ليتقدم ويصعد كل رجال الحرب '),
(19769, 'Joel', 29, 3, 10, ' اطبعوا سكاتكم سيوفا ، ومناجلكم رماحا . ليقل الضعيف : بطل أنا '),
(19770, 'Joel', 29, 3, 11, ' أسرعوا وهلموا يا جميع الأمم من كل ناحية واجتمعوا . إلى هناك أنزل يارب أبطالك '),
(19771, 'Joel', 29, 3, 12, ' تنهض وتصعد الأمم إلى وادي يهوشافاط ، لأني هناك أجلس لأحاكم جميع الأمم من كل ناحية '),
(19772, 'Joel', 29, 3, 13, ' أرسلوا المنجل لأن الحصيد قد نضج . هلموا دوسوا لأنه قد امتلأت المعصرة . فاضت الحياض لأن شرهم كثير '),
(19773, 'Joel', 29, 3, 14, ' جماهير جماهير في وادي القضاء ، لأن يوم الرب قريب في وادي القضاء '),
(19774, 'Joel', 29, 3, 15, ' الشمس والقمر يظلمان ، والنجوم تحجز لمعانها '),
(19775, 'Joel', 29, 3, 16, ' والرب من صهيون يزمجر ، ومن أورشليم يعطي صوته ، فترجف السماء والأرض . ولكن الرب ملجأ لشعبه ، وحصن لبني إسرائيل '),
(19776, 'Joel', 29, 3, 17, ' فتعرفون أني أنا الرب إلهكم ، ساكنا في صهيون جبل قدسي . وتكون أورشليم مقدسة ولا يجتاز فيها الأعاجم في ما بعد '),
(19777, 'Joel', 29, 3, 18, ' ويكون في ذلك اليوم أن الجبال تقطر عصيرا ، والتلال تفيض لبنا ، وجميع ينابيع يهوذا تفيض ماء ، ومن بيت الرب يخرج ينبوع ويسقي وادي السنط '),
(19778, 'Joel', 29, 3, 19, ' مصر تصير خرابا ، وأدوم تصير قفرا خربا ، من أجل ظلمهم لبني يهوذا الذين سفكوا دما بريئا في أرضهم '),
(19779, 'Joel', 29, 3, 20, ' ولكن يهوذا تسكن إلى الأبد ، وأورشليم إلى دور فدور '),
(19780, 'Joel', 29, 3, 21, ' وأبرئ دمهم الذي لم أبرئه ، والرب يسكن في صهيون '),
(19781, 'John', 43, 1, 1, ' في البدء كان الكلمة ، والكلمة كان عند الله ، وكان الكلمة الله '),
(19782, 'John', 43, 1, 2, ' هذا كان في البدء عند الله '),
(19783, 'John', 43, 1, 3, ' كل شيء به كان ، وبغيره لم يكن شيء مما كان '),
(19784, 'John', 43, 1, 4, ' فيه كانت الحياة ، والحياة كانت نور الناس '),
(19785, 'John', 43, 1, 5, ' والنور يضيء في الظلمة ، والظلمة لم تدركه '),
(19786, 'John', 43, 1, 6, ' كان إنسان مرسل من الله اسمه يوحنا '),
(19787, 'John', 43, 1, 7, ' هذا جاء للشهادة ليشهد للنور ، لكي يؤمن الكل بواسطته '),
(19788, 'John', 43, 1, 8, ' لم يكن هو النور ، بل ليشهد للنور '),
(19789, 'John', 43, 1, 9, ' كان النور الحقيقي الذي ينير كل إنسان آتيا إلى العالم '),
(19790, 'John', 43, 1, 10, ' كان في العالم ، وكون العالم به ، ولم يعرفه العالم '),
(19791, 'John', 43, 1, 11, ' إلى خاصته جاء ، وخاصته لم تقبله '),
(19792, 'John', 43, 1, 12, ' وأما كل الذين قبلوه فأعطاهم سلطانا أن يصيروا أولاد الله ، أي المؤمنون باسمه '),
(19793, 'John', 43, 1, 13, ' الذين ولدوا ليس من دم ، ولا من مشيئة جسد ، ولا من مشيئة رجل ، بل من الله '),
(19794, 'John', 43, 1, 14, ' والكلمة صار جسدا وحل بيننا ، ورأينا مجده ، مجدا كما لوحيد من الآب ، مملوءا نعمة وحقا '),
(19795, 'John', 43, 1, 15, ' يوحنا شهد له ونادى قائلا : هذا هو الذي قلت عنه : إن الذي يأتي بعدي صار قدامي ، لأنه كان قبلي '),
(19796, 'John', 43, 1, 16, ' ومن ملئه نحن جميعا أخذنا ، ونعمة فوق نعمة '),
(19797, 'John', 43, 1, 17, ' لأن الناموس بموسى أعطي ، أما النعمة والحق فبيسوع المسيح صارا '),
(19798, 'John', 43, 1, 18, ' الله لم يره أحد قط . الابن الوحيد الذي هو في حضن الآب هو خبر '),
(19799, 'John', 43, 1, 19, ' وهذه هي شهادة يوحنا ، حين أرسل اليهود من أورشليم كهنة ولاويين ليسألوه : من أنت '),
(19800, 'John', 43, 1, 20, ' فاعترف ولم ينكر ، وأقر : إني لست أنا المسيح '),
(19801, 'John', 43, 1, 21, ' فسألوه : إذا ماذا ؟ إيليا أنت ؟ فقال : لست أنا . ألنبي أنت ؟ فأجاب : لا '),
(19802, 'John', 43, 1, 22, ' فقالوا له : من أنت ، لنعطي جوابا للذين أرسلونا ؟ ماذا تقول عن نفسك '),
(19803, 'John', 43, 1, 23, ' قال : أنا صوت صارخ في البرية : قوموا طريق الرب ، كما قال إشعياء النبي '),
(19804, 'John', 43, 1, 24, ' وكان المرسلون من الفريسيين '),
(19805, 'John', 43, 1, 25, ' فسألوه وقالوا له : فما بالك تعمد إن كنت لست المسيح ، ولا إيليا ، ولا النبي '),
(19806, 'John', 43, 1, 26, ' أجابهم يوحنا قائلا : أنا أعمد بماء ، ولكن في وسطكم قائم الذي لستم تعرفونه '),
(19807, 'John', 43, 1, 27, ' هو الذي يأتي بعدي ، الذي صار قدامي ، الذي لست بمستحق أن أحل سيور حذائه '),
(19808, 'John', 43, 1, 28, ' هذا كان في بيت عبرة في عبر الأردن حيث كان يوحنا يعمد '),
(19809, 'John', 43, 1, 29, ' وفي الغد نظر يوحنا يسوع مقبلا إليه ، فقال : هوذا حمل الله الذي يرفع خطية العالم '),
(19810, 'John', 43, 1, 30, ' هذا هو الذي قلت عنه : يأتي بعدي ، رجل صار قدامي ، لأنه كان قبلي '),
(19811, 'John', 43, 1, 31, ' وأنا لم أكن أعرفه . لكن ليظهر لإسرائيل لذلك جئت أعمد بالماء '),
(19812, 'John', 43, 1, 32, ' وشهد يوحنا قائلا : إني قد رأيت الروح نازلا مثل حمامة من السماء فاستقر عليه '),
(19813, 'John', 43, 1, 33, ' وأنا لم أكن أعرفه ، لكن الذي أرسلني لأعمد بالماء ، ذاك قال لي : الذي ترى الروح نازلا ومستقرا عليه ، فهذا هو الذي يعمد بالروح القدس '),
(19814, 'John', 43, 1, 34, ' وأنا قد رأيت وشهدت أن هذا هو ابن الله '),
(19815, 'John', 43, 1, 35, ' وفي الغد أيضا كان يوحنا واقفا هو واثنان من تلاميذه '),
(19816, 'John', 43, 1, 36, ' فنظر إلى يسوع ماشيا ، فقال : هوذا حمل الله '),
(19817, 'John', 43, 1, 37, ' فسمعه التلميذان يتكلم ، فتبعا يسوع '),
(19818, 'John', 43, 1, 38, ' فالتفت يسوع ونظرهما يتبعان ، فقال لهما : ماذا تطلبان ؟ فقالا : ربي الذي تفسيره يا معلم . أين تمكث '),
(19819, 'John', 43, 1, 39, ' فقال لهما : تعاليا وانظرا . فأتيا ونظرا أين كان يمكث ، ومكثا عنده ذلك اليوم . وكان نحو الساعة العاشرة '),
(19820, 'John', 43, 1, 40, ' كان أندراوس أخو سمعان بطرس واحدا من الاثنين اللذين سمعا يوحنا وتبعاه '),
(19821, 'John', 43, 1, 41, ' هذا وجد أولا أخاه سمعان ، فقال له : قد وجدنا مسيا الذي تفسيره : المسيح '),
(19822, 'John', 43, 1, 42, ' فجاء به إلى يسوع . فنظر إليه يسوع وقال : أنت سمعان بن يونا . أنت تدعى صفا الذي تفسيره : بطرس '),
(19823, 'John', 43, 1, 43, ' في الغد أراد يسوع أن يخرج إلى الجليل ، فوجد فيلبس فقال له : اتبعني '),
(19824, 'John', 43, 1, 44, ' وكان فيلبس من بيت صيدا ، من مدينة أندراوس وبطرس '),
(19825, 'John', 43, 1, 45, ' فيلبس وجد نثنائيل وقال له : وجدنا الذي كتب عنه موسى في الناموس والأنبياء يسوع ابن يوسف الذي من الناصرة '),
(19826, 'John', 43, 1, 46, ' فقال له نثنائيل : أمن الناصرة يمكن أن يكون شيء صالح ؟ قال له فيلبس : تعال وانظر '),
(19827, 'John', 43, 1, 47, ' ورأى يسوع نثنائيل مقبلا إليه ، فقال عنه : هوذا إسرائيلي حقا لا غش فيه '),
(19828, 'John', 43, 1, 48, ' قال له نثنائيل : من أين تعرفني ؟ أجاب يسوع وقال له : قبل أن دعاك فيلبس وأنت تحت التينة ، رأيتك '),
(19829, 'John', 43, 1, 49, ' أجاب نثنائيل وقال له : يا معلم ، أنت ابن الله أنت ملك إسرائيل '),
(19830, 'John', 43, 1, 50, ' أجاب يسوع وقال له : هل آمنت لأني قلت لك : إني رأيتك تحت التينة ؟ سوف ترى أعظم من هذا '),
(19831, 'John', 43, 1, 51, ' وقال له : الحق الحق أقول لكم : من الآن ترون السماء مفتوحة ، وملائكة الله يصعدون وينزلون على ابن الإنسان '),
(19832, 'John', 43, 2, 1, ' وفي اليوم الثالث كان عرس في قانا الجليل ، وكانت أم يسوع هناك '),
(19833, 'John', 43, 2, 2, ' ودعي أيضا يسوع وتلاميذه إلى العرس '),
(19834, 'John', 43, 2, 3, ' ولما فرغت الخمر ، قالت أم يسوع له : ليس لهم خمر '),
(19835, 'John', 43, 2, 4, ' قال لها يسوع : ما لي ولك يا امرأة ؟ لم تأت ساعتي بعد '),
(19836, 'John', 43, 2, 5, ' قالت أمه للخدام : مهما قال لكم فافعلوه '),
(19837, 'John', 43, 2, 6, ' وكانت ستة أجران من حجارة موضوعة هناك ، حسب تطهير اليهود ، يسع كل واحد مطرين أو ثلاثة '),
(19838, 'John', 43, 2, 7, ' قال لهم يسوع : املأوا الأجران ماء . فملأوها إلى فوق '),
(19839, 'John', 43, 2, 8, ' ثم قال لهم : استقوا الآن وقدموا إلى رئيس المتكإ . فقدموا '),
(19840, 'John', 43, 2, 9, ' فلما ذاق رئيس المتكإ الماء المتحول خمرا ، ولم يكن يعلم من أين هي ، لكن الخدام الذين كانوا قد استقوا الماء علموا ، دعا رئيس المتكإ العريس '),
(19841, 'John', 43, 2, 10, ' وقال له : كل إنسان إنما يضع الخمر الجيدة أولا ، ومتى سكروا فحينئذ الدون . أما أنت فقد أبقيت الخمر الجيدة إلى الآن '),
(19842, 'John', 43, 2, 11, ' هذه بداية الآيات فعلها يسوع في قانا الجليل ، وأظهر مجده ، فآمن به تلاميذه '),
(19843, 'John', 43, 2, 12, ' وبعد هذا انحدر إلى كفرناحوم ، هو وأمه وإخوته وتلاميذه ، وأقاموا هناك أياما ليست كثيرة '),
(19844, 'John', 43, 2, 13, ' وكان فصح اليهود قريبا ، فصعد يسوع إلى أورشليم '),
(19845, 'John', 43, 2, 14, ' ووجد في الهيكل الذين كانوا يبيعون بقرا وغنما وحماما ، والصيارف جلوسا '),
(19846, 'John', 43, 2, 15, ' فصنع سوطا من حبال وطرد الجميع من الهيكل ، الغنم والبقر ، وكب دراهم الصيارف وقلب موائدهم '),
(19847, 'John', 43, 2, 16, ' وقال لباعة الحمام : ارفعوا هذه من ههنا لا تجعلوا بيت أبي بيت تجارة '),
(19848, 'John', 43, 2, 17, ' فتذكر تلاميذه أنه مكتوب : غيرة بيتك أكلتني '),
(19849, 'John', 43, 2, 18, ' فأجاب اليهود وقالوا له : أية آية ترينا حتى تفعل هذا '),
(19850, 'John', 43, 2, 19, ' أجاب يسوع وقال لهم : انقضوا هذا الهيكل ، وفي ثلاثة أيام أقيمه '),
(19851, 'John', 43, 2, 20, ' فقال اليهود : في ست وأربعين سنة بني هذا الهيكل ، أفأنت في ثلاثة أيام تقيمه '),
(19852, 'John', 43, 2, 21, ' وأما هو فكان يقول عن هيكل جسده '),
(19853, 'John', 43, 2, 22, ' فلما قام من الأموات ، تذكر تلاميذه أنه قال هذا ، فآمنوا بالكتاب والكلام الذي قاله يسوع '),
(19854, 'John', 43, 2, 23, ' ولما كان في أورشليم في عيد الفصح ، آمن كثيرون باسمه ، إذ رأوا الآيات التي صنع '),
(19855, 'John', 43, 2, 24, ' لكن يسوع لم يأتمنهم على نفسه ، لأنه كان يعرف الجميع '),
(19856, 'John', 43, 2, 25, ' ولأنه لم يكن محتاجا أن يشهد أحد عن الإنسان ، لأنه علم ما كان في الإنسان '),
(19857, 'John', 43, 3, 1, ' كان إنسان من الفريسيين اسمه نيقوديموس ، رئيس لليهود '),
(19858, 'John', 43, 3, 2, ' هذا جاء إلى يسوع ليلا وقال له : يا معلم ، نعلم أنك قد أتيت من الله معلما ، لأن ليس أحد يقدر أن يعمل هذه الآيات التي أنت تعمل إن لم يكن الله معه '),
(19859, 'John', 43, 3, 3, ' أجاب يسوع وقال له : الحق الحق أقول لك : إن كان أحد لا يولد من فوق لا يقدر أن يرى ملكوت الله '),
(19860, 'John', 43, 3, 4, ' قال له نيقوديموس : كيف يمكن الإنسان أن يولد وهو شيخ ؟ ألعله يقدر أن يدخل بطن أمه ثانية ويولد '),
(19861, 'John', 43, 3, 5, ' أجاب يسوع : الحق الحق أقول لك : إن كان أحد لا يولد من الماء والروح لا يقدر أن يدخل ملكوت الله '),
(19862, 'John', 43, 3, 6, ' المولود من الجسد جسد هو ، والمولود من الروح هو روح '),
(19863, 'John', 43, 3, 7, ' لا تتعجب أني قلت لك : ينبغي أن تولدوا من فوق '),
(19864, 'John', 43, 3, 8, ' الريح تهب حيث تشاء ، وتسمع صوتها ، لكنك لا تعلم من أين تأتي ولا إلى أين تذهب . هكذا كل من ولد من الروح '),
(19865, 'John', 43, 3, 9, ' أجاب نيقوديموس وقال له : كيف يمكن أن يكون هذا '),
(19866, 'John', 43, 3, 10, ' أجاب يسوع وقال له : أنت معلم إسرائيل ولست تعلم هذا '),
(19867, 'John', 43, 3, 11, ' الحق الحق أقول لك : إننا إنما نتكلم بما نعلم ونشهد بما رأينا ، ولستم تقبلون شهادتنا '),
(19868, 'John', 43, 3, 12, ' إن كنت قلت لكم الأرضيات ولستم تؤمنون ، فكيف تؤمنون إن قلت لكم السماويات '),
(19869, 'John', 43, 3, 13, ' وليس أحد صعد إلى السماء إلا الذي نزل من السماء ، ابن الإنسان الذي هو في السماء '),
(19870, 'John', 43, 3, 14, ' وكما رفع موسى الحية في البرية هكذا ينبغي أن يرفع ابن الإنسان '),
(19871, 'John', 43, 3, 15, ' لكي لا يهلك كل من يؤمن به بل تكون له الحياة الأبدية '),
(19872, 'John', 43, 3, 16, ' لأنه هكذا أحب الله العالم حتى بذل ابنه الوحيد ، لكي لا يهلك كل من يؤمن به ، بل تكون له الحياة الأبدية '),
(19873, 'John', 43, 3, 17, ' لأنه لم يرسل الله ابنه إلى العالم ليدين العالم ، بل ليخلص به العالم '),
(19874, 'John', 43, 3, 18, ' الذي يؤمن به لا يدان ، والذي لا يؤمن قد دين ، لأنه لم يؤمن باسم ابن الله الوحيد '),
(19875, 'John', 43, 3, 19, ' وهذه هي الدينونة : إن النور قد جاء إلى العالم ، وأحب الناس الظلمة أكثر من النور ، لأن أعمالهم كانت شريرة '),
(19876, 'John', 43, 3, 20, ' لأن كل من يعمل السيآت يبغض النور ، ولا يأتي إلى النور لئلا توبخ أعماله '),
(19877, 'John', 43, 3, 21, ' وأما من يفعل الحق فيقبل إلى النور ، لكي تظهر أعماله أنها بالله معمولة '),
(19878, 'John', 43, 3, 22, ' وبعد هذا جاء يسوع وتلاميذه إلى أرض اليهودية ، ومكث معهم هناك ، وكان يعمد '),
(19879, 'John', 43, 3, 23, ' وكان يوحنا أيضا يعمد في عين نون بقرب ساليم ، لأنه كان هناك مياه كثيرة ، وكانوا يأتون ويعتمدون '),
(19880, 'John', 43, 3, 24, ' لأنه لم يكن يوحنا قد ألقي بعد في السجن '),
(19881, 'John', 43, 3, 25, ' وحدثت مباحثة من تلاميذ يوحنا مع يهود من جهة التطهير '),
(19882, 'John', 43, 3, 26, ' فجاءوا إلى يوحنا وقالوا له : يا معلم ، هوذا الذي كان معك في عبر الأردن ، الذي أنت قد شهدت له ، هو يعمد ، والجميع يأتون إليه '),
(19883, 'John', 43, 3, 27, ' أجاب يوحنا وقال : لا يقدر إنسان أن يأخذ شيئا إن لم يكن قد أعطي من السماء '),
(19884, 'John', 43, 3, 28, ' أنتم أنفسكم تشهدون لي أني قلت : لست أنا المسيح بل إني مرسل أمامه '),
(19885, 'John', 43, 3, 29, ' من له العروس فهو العريس ، وأما صديق العريس الذي يقف ويسمعه فيفرح فرحا من أجل صوت العريس . إذا فرحي هذا قد كمل '),
(19886, 'John', 43, 3, 30, ' ينبغي أن ذلك يزيد وأني أنا أنقص '),
(19887, 'John', 43, 3, 31, ' الذي يأتي من فوق هو فوق الجميع ، والذي من الأرض هو أرضي ، ومن الأرض يتكلم . الذي يأتي من السماء هو فوق الجميع '),
(19888, 'John', 43, 3, 32, ' وما رآه وسمعه به يشهد ، وشهادته ليس أحد يقبلها '),
(19889, 'John', 43, 3, 33, ' ومن قبل شهادته فقد ختم أن الله صادق '),
(19890, 'John', 43, 3, 34, ' لأن الذي أرسله الله يتكلم بكلام الله . لأنه ليس بكيل يعطي الله الروح '),
(19891, 'John', 43, 3, 35, ' الآب يحب الابن وقد دفع كل شيء في يده '),
(19892, 'John', 43, 3, 36, ' الذي يؤمن بالابن له حياة أبدية ، والذي لا يؤمن بالابن لن يرى حياة بل يمكث عليه غضب الله '),
(19893, 'John', 43, 4, 1, ' فلما علم الرب أن الفريسيين سمعوا أن يسوع يصير ويعمد تلاميذ أكثر من يوحنا '),
(19894, 'John', 43, 4, 2, ' مع أن يسوع نفسه لم يكن يعمد بل تلاميذه '),
(19895, 'John', 43, 4, 3, ' ترك اليهودية ومضى أيضا إلى الجليل '),
(19896, 'John', 43, 4, 4, ' وكان لا بد له أن يجتاز السامرة '),
(19897, 'John', 43, 4, 5, ' فأتى إلى مدينة من السامرة يقال لها سوخار ، بقرب الضيعة التي وهبها يعقوب ليوسف ابنه '),
(19898, 'John', 43, 4, 6, ' وكانت هناك بئر يعقوب . فإذ كان يسوع قد تعب من السفر ، جلس هكذا على البئر ، وكان نحو الساعة السادسة '),
(19899, 'John', 43, 4, 7, ' فجاءت امرأة من السامرة لتستقي ماء ، فقال لها يسوع : أعطيني لأشرب '),
(19900, 'John', 43, 4, 8, ' لأن تلاميذه كانوا قد مضوا إلى المدينة ليبتاعوا طعاما '),
(19901, 'John', 43, 4, 9, ' فقالت له المرأة السامرية : كيف تطلب مني لتشرب ، وأنت يهودي وأنا امرأة سامرية ؟ لأن اليهود لا يعاملون السامريين '),
(19902, 'John', 43, 4, 10, ' أجاب يسوع وقال لها : لو كنت تعلمين عطية الله ، ومن هو الذي يقول لك أعطيني لأشرب ، لطلبت أنت منه فأعطاك ماء حيا '),
(19903, 'John', 43, 4, 11, ' قالت له المرأة : يا سيد ، لا دلو لك والبئر عميقة . فمن أين لك الماء الحي '),
(19904, 'John', 43, 4, 12, ' ألعلك أعظم من أبينا يعقوب ، الذي أعطانا البئر ، وشرب منها هو وبنوه ومواشيه '),
(19905, 'John', 43, 4, 13, ' أجاب يسوع وقال لها : كل من يشرب من هذا الماء يعطش أيضا '),
(19906, 'John', 43, 4, 14, ' ولكن من يشرب من الماء الذي أعطيه أنا فلن يعطش إلى الأبد ، بل الماء الذي أعطيه يصير فيه ينبوع ماء ينبع إلى حياة أبدية '),
(19907, 'John', 43, 4, 15, ' قالت له المرأة : يا سيد أعطني هذا الماء ، لكي لا أعطش ولا آتي إلى هنا لأستقي '),
(19908, 'John', 43, 4, 16, ' قال لها يسوع : اذهبي وادعي زوجك وتعالي إلى ههنا '),
(19909, 'John', 43, 4, 17, ' أجابت المرأة وقالت : ليس لي زوج . قال لها يسوع : حسنا قلت : ليس لي زوج '),
(19910, 'John', 43, 4, 18, ' لأنه كان لك خمسة أزواج ، والذي لك الآن ليس هو زوجك . هذا قلت بالصدق '),
(19911, 'John', 43, 4, 19, ' قالت له المرأة : يا سيد ، أرى أنك نبي '),
(19912, 'John', 43, 4, 20, ' آباؤنا سجدوا في هذا الجبل ، وأنتم تقولون : إن في أورشليم الموضع الذي ينبغي أن يسجد فيه '),
(19913, 'John', 43, 4, 21, ' قال لها يسوع : يا امرأة ، صدقيني أنه تأتي ساعة ، لا في هذا الجبل ، ولا في أورشليم تسجدون للآب '),
(19914, 'John', 43, 4, 22, ' أنتم تسجدون لما لستم تعلمون ، أما نحن فنسجد لما نعلم . لأن الخلاص هو من اليهود '),
(19915, 'John', 43, 4, 23, ' ولكن تأتي ساعة ، وهي الآن ، حين الساجدون الحقيقيون يسجدون للآب بالروح والحق ، لأن الآب طالب مثل هؤلاء الساجدين له '),
(19916, 'John', 43, 4, 24, ' الله روح . والذين يسجدون له فبالروح والحق ينبغي أن يسجدوا '),
(19917, 'John', 43, 4, 25, ' قالت له المرأة : أنا أعلم أن مسيا ، الذي يقال له المسيح ، يأتي . فمتى جاء ذاك يخبرنا بكل شيء '),
(19918, 'John', 43, 4, 26, ' قال لها يسوع : أنا الذي أكلمك هو '),
(19919, 'John', 43, 4, 27, ' وعند ذلك جاء تلاميذه ، وكانوا يتعجبون أنه يتكلم مع امرأة . ولكن لم يقل أحد : ماذا تطلب ؟ أو لماذا تتكلم معها '),
(19920, 'John', 43, 4, 28, ' فتركت المرأة جرتها ومضت إلى المدينة وقالت للناس '),
(19921, 'John', 43, 4, 29, ' هلموا انظروا إنسانا قال لي كل ما فعلت . ألعل هذا هو المسيح '),
(19922, 'John', 43, 4, 30, ' فخرجوا من المدينة وأتوا إليه '),
(19923, 'John', 43, 4, 31, ' وفي أثناء ذلك سأله تلاميذه قائلين : يا معلم ، كل '),
(19924, 'John', 43, 4, 32, ' فقال لهم : أنا لي طعام لآكل لستم تعرفونه أنتم '),
(19925, 'John', 43, 4, 33, ' فقال التلاميذ بعضهم لبعض : ألعل أحدا أتاه بشيء ليأكل '),
(19926, 'John', 43, 4, 34, ' قال لهم يسوع : طعامي أن أعمل مشيئة الذي أرسلني وأتمم عمله '),
(19927, 'John', 43, 4, 35, ' أما تقولون : إنه يكون أربعة أشهر ثم يأتي الحصاد ؟ ها أنا أقول لكم : ارفعوا أعينكم وانظروا الحقول إنها قد ابيضت للحصاد '),
(19928, 'John', 43, 4, 36, ' والحاصد يأخذ أجرة ويجمع ثمرا للحياة الأبدية ، لكي يفرح الزارع والحاصد معا '),
(19929, 'John', 43, 4, 37, ' لأنه في هذا يصدق القول : إن واحدا يزرع وآخر يحصد '),
(19930, 'John', 43, 4, 38, ' أنا أرسلتكم لتحصدوا ما لم تتعبوا فيه . آخرون تعبوا وأنتم قد دخلتم على تعبهم '),
(19931, 'John', 43, 4, 39, ' فآمن به من تلك المدينة كثيرون من السامريين بسبب كلام المرأة التي كانت تشهد أنه : قال لي كل ما فعلت '),
(19932, 'John', 43, 4, 40, ' فلما جاء إليه السامريون سألوه أن يمكث عندهم ، فمكث هناك يومين '),
(19933, 'John', 43, 4, 41, ' فآمن به أكثر جدا بسبب كلامه '),
(19934, 'John', 43, 4, 42, ' وقالوا للمرأة : إننا لسنا بعد بسبب كلامك نؤمن ، لأننا نحن قد سمعنا ونعلم أن هذا هو بالحقيقة المسيح مخلص العالم '),
(19935, 'John', 43, 4, 43, ' وبعد اليومين خرج من هناك ومضى إلى الجليل '),
(19936, 'John', 43, 4, 44, ' لأن يسوع نفسه شهد أن : ليس لنبي كرامة في وطنه '),
(19937, 'John', 43, 4, 45, ' فلما جاء إلى الجليل قبله الجليليون ، إذ كانوا قد عاينوا كل ما فعل في أورشليم في العيد ، لأنهم هم أيضا جاءوا إلى العيد '),
(19938, 'John', 43, 4, 46, ' فجاء يسوع أيضا إلى قانا الجليل ، حيث صنع الماء خمرا . وكان خادم للملك ابنه مريض في كفرناحوم '),
(19939, 'John', 43, 4, 47, ' هذا إذ سمع أن يسوع قد جاء من اليهودية إلى الجليل ، انطلق إليه وسأله أن ينزل ويشفي ابنه لأنه كان مشرفا على الموت '),
(19940, 'John', 43, 4, 48, ' فقال له يسوع : لا تؤمنون إن لم تروا آيات وعجائب '),
(19941, 'John', 43, 4, 49, ' قال له خادم الملك : يا سيد ، انزل قبل أن يموت ابني '),
(19942, 'John', 43, 4, 50, ' قال له يسوع : اذهب . ابنك حي . فآمن الرجل بالكلمة التي قالها له يسوع ، وذهب '),
(19943, 'John', 43, 4, 51, ' وفيما هو نازل استقبله عبيده وأخبروه قائلين : إن ابنك حي '),
(19944, 'John', 43, 4, 52, ' فاستخبرهم عن الساعة التي فيها أخذ يتعافى ، فقالوا له : أمس في الساعة السابعة تركته الحمى '),
(19945, 'John', 43, 4, 53, ' ففهم الأب أنه في تلك الساعة التي قال له فيها يسوع : إن ابنك حي . فآمن هو وبيته كله '),
(19946, 'John', 43, 4, 54, ' هذه أيضا آية ثانية صنعها يسوع لما جاء من اليهودية إلى الجليل '),
(19947, 'John', 43, 5, 1, ' وبعد هذا كان عيد لليهود ، فصعد يسوع إلى أورشليم '),
(19948, 'John', 43, 5, 2, ' وفي أورشليم عند باب الضأن بركة يقال لها بالعبرانية بيت حسدا لها خمسة أروقة '),
(19949, 'John', 43, 5, 3, ' في هذه كان مضطجعا جمهور كثير من مرضى وعمي وعرج وعسم ، يتوقعون تحريك الماء '),
(19950, 'John', 43, 5, 4, ' لأن ملاكا كان ينزل أحيانا في البركة ويحرك الماء . فمن نزل أولا بعد تحريك الماء كان يبرأ من أي مرض اعتراه '),
(19951, 'John', 43, 5, 5, ' وكان هناك إنسان به مرض منذ ثمان وثلاثين سنة '),
(19952, 'John', 43, 5, 6, ' هذا رآه يسوع مضطجعا ، وعلم أن له زمانا كثيرا ، فقال له : أتريد أن تبرأ '),
(19953, 'John', 43, 5, 7, ' أجابه المريض : يا سيد ، ليس لي إنسان يلقيني في البركة متى تحرك الماء . بل بينما أنا آت ، ينزل قدامي آخر '),
(19954, 'John', 43, 5, 8, ' قال له يسوع : قم . احمل سريرك وامش '),
(19955, 'John', 43, 5, 9, ' فحالا برئ الإنسان وحمل سريره ومشى . وكان في ذلك اليوم سبت '),
(19956, 'John', 43, 5, 10, ' فقال اليهود للذي شفي : إنه سبت لا يحل لك أن تحمل سريرك '),
(19957, 'John', 43, 5, 11, ' أجابهم : إن الذي أبرأني هو قال لي : احمل سريرك وامش '),
(19958, 'John', 43, 5, 12, ' فسألوه : من هو الإنسان الذي قال لك : احمل سريرك وامش '),
(19959, 'John', 43, 5, 13, ' أما الذي شفي فلم يكن يعلم من هو ، لأن يسوع اعتزل ، إذ كان في الموضع جمع '),
(19960, 'John', 43, 5, 14, ' بعد ذلك وجده يسوع في الهيكل وقال له : ها أنت قد برئت ، فلا تخطئ أيضا ، لئلا يكون لك أشر '),
(19961, 'John', 43, 5, 15, ' فمضى الإنسان وأخبر اليهود أن يسوع هو الذي أبرأه '),
(19962, 'John', 43, 5, 16, ' ولهذا كان اليهود يطردون يسوع ، ويطلبون أن يقتلوه ، لأنه عمل هذا في سبت '),
(19963, 'John', 43, 5, 17, ' فأجابهم يسوع : أبي يعمل حتى الآن وأنا أعمل '),
(19964, 'John', 43, 5, 18, ' فمن أجل هذا كان اليهود يطلبون أكثر أن يقتلوه ، لأنه لم ينقض السبت فقط ، بل قال أيضا إن الله أبوه ، معادلا نفسه بالله '),
(19965, 'John', 43, 5, 19, ' فأجاب يسوع وقال لهم : الحق الحق أقول لكم : لا يقدر الابن أن يعمل من نفسه شيئا إلا ما ينظر الآب يعمل . لأن مهما عمل ذاك فهذا يعمله الابن كذلك '),
(19966, 'John', 43, 5, 20, ' لأن الآب يحب الابن ويريه جميع ما هو يعمله ، وسيريه أعمالا أعظم من هذه لتتعجبوا أنتم '),
(19967, 'John', 43, 5, 21, ' لأنه كما أن الآب يقيم الأموات ويحيي ، كذلك الابن أيضا يحيي من يشاء '),
(19968, 'John', 43, 5, 22, ' لأن الآب لا يدين أحدا ، بل قد أعطى كل الدينونة للابن '),
(19969, 'John', 43, 5, 23, ' لكي يكرم الجميع الابن كما يكرمون الآب . من لا يكرم الابن لا يكرم الآب الذي أرسله '),
(19970, 'John', 43, 5, 24, ' الحق الحق أقول لكم : إن من يسمع كلامي ويؤمن بالذي أرسلني فله حياة أبدية ، ولا يأتي إلى دينونة ، بل قد انتقل من الموت إلى الحياة '),
(19971, 'John', 43, 5, 25, ' الحق الحق أقول لكم : إنه تأتي ساعة وهي الآن ، حين يسمع الأموات صوت ابن الله ، والسامعون يحيون '),
(19972, 'John', 43, 5, 26, ' لأنه كما أن الآب له حياة في ذاته ، كذلك أعطى الابن أيضا أن تكون له حياة في ذاته '),
(19973, 'John', 43, 5, 27, ' وأعطاه سلطانا أن يدين أيضا ، لأنه ابن الإنسان '),
(19974, 'John', 43, 5, 28, ' لا تتعجبوا من هذا ، فإنه تأتي ساعة فيها يسمع جميع الذين في القبور صوته '),
(19975, 'John', 43, 5, 29, ' فيخرج الذين فعلوا الصالحات إلى قيامة الحياة ، والذين عملوا السيئات إلى قيامة الدينونة '),
(19976, 'John', 43, 5, 30, ' أنا لا أقدر أن أفعل من نفسي شيئا . كما أسمع أدين ، ودينونتي عادلة ، لأني لا أطلب مشيئتي بل مشيئة الآب الذي أرسلني '),
(19977, 'John', 43, 5, 31, ' إن كنت أشهد لنفسي فشهادتي ليست حقا '),
(19978, 'John', 43, 5, 32, ' الذي يشهد لي هو آخر ، وأنا أعلم أن شهادته التي يشهدها لي هي حق '),
(19979, 'John', 43, 5, 33, ' أنتم أرسلتم إلى يوحنا فشهد للحق '),
(19980, 'John', 43, 5, 34, ' وأنا لا أقبل شهادة من إنسان ، ولكني أقول هذا لتخلصوا أنتم '),
(19981, 'John', 43, 5, 35, ' كان هو السراج الموقد المنير ، وأنتم أردتم أن تبتهجوا بنوره ساعة '),
(19982, 'John', 43, 5, 36, ' وأما أنا فلي شهادة أعظم من يوحنا ، لأن الأعمال التي أعطاني الآب لأكملها ، هذه الأعمال بعينها التي أنا أعملها هي تشهد لي أن الآب قد أرسلني '),
(19983, 'John', 43, 5, 37, ' والآب نفسه الذي أرسلني يشهد لي . لم تسمعوا صوته قط ، ولا أبصرتم هيئته '),
(19984, 'John', 43, 5, 38, ' وليست لكم كلمته ثابتة فيكم ، لأن الذي أرسله هو لستم أنتم تؤمنون به '),
(19985, 'John', 43, 5, 39, ' فتشوا الكتب لأنكم تظنون أن لكم فيها حياة أبدية . وهي التي تشهد لي '),
(19986, 'John', 43, 5, 40, ' ولا تريدون أن تأتوا إلي لتكون لكم حياة '),
(19987, 'John', 43, 5, 41, ' مجدا من الناس لست أقبل '),
(19988, 'John', 43, 5, 42, ' ولكني قد عرفتكم أن ليست لكم محبة الله في أنفسكم '),
(19989, 'John', 43, 5, 43, ' أنا قد أتيت باسم أبي ولستم تقبلونني . إن أتى آخر باسم نفسه فذلك تقبلونه '),
(19990, 'John', 43, 5, 44, ' كيف تقدرون أن تؤمنوا وأنتم تقبلون مجدا بعضكم من بعض ، والمجد الذي من الإله الواحد لستم تطلبونه '),
(19991, 'John', 43, 5, 45, ' لا تظنوا أني أشكوكم إلى الآب . يوجد الذي يشكوكم وهو موسى ، الذي عليه رجاؤكم '),
(19992, 'John', 43, 5, 46, ' لأنكم لو كنتم تصدقون موسى لكنتم تصدقونني ، لأنه هو كتب عني '),
(19993, 'John', 43, 5, 47, ' فإن كنتم لستم تصدقون كتب ذاك ، فكيف تصدقون كلامي '),
(19994, 'John', 43, 6, 1, ' بعد هذا مضى يسوع إلى عبر بحر الجليل ، وهو بحر طبرية '),
(19995, 'John', 43, 6, 2, ' وتبعه جمع كثير لأنهم أبصروا آياته التي كان يصنعها في المرضى '),
(19996, 'John', 43, 6, 3, ' فصعد يسوع إلى جبل وجلس هناك مع تلاميذه '),
(19997, 'John', 43, 6, 4, ' وكان الفصح ، عيد اليهود ، قريبا '),
(19998, 'John', 43, 6, 5, ' فرفع يسوع عينيه ونظر أن جمعا كثيرا مقبل إليه ، فقال لفيلبس : من أين نبتاع خبزا ليأكل هؤلاء '),
(19999, 'John', 43, 6, 6, ' وإنما قال هذا ليمتحنه ، لأنه هو علم ما هو مزمع أن يفعل '),
(20000, 'John', 43, 6, 7, ' أجابه فيلبس : لا يكفيهم خبز بمئتي دينار ليأخذ كل واحد منهم شيئا يسيرا '),
(20001, 'John', 43, 6, 8, ' قال له واحد من تلاميذه ، وهو أندراوس أخو سمعان بطرس '),
(20002, 'John', 43, 6, 9, ' هنا غلام معه خمسة أرغفة شعير وسمكتان ، ولكن ما هذا لمثل هؤلاء '),
(20003, 'John', 43, 6, 10, ' فقال يسوع : اجعلوا الناس يتكئون . وكان في المكان عشب كثير ، فاتكأ الرجال وعددهم نحو خمسة آلاف '),
(20004, 'John', 43, 6, 11, ' وأخذ يسوع الأرغفة وشكر ، ووزع على التلاميذ ، والتلاميذ أعطوا المتكئين . وكذلك من السمكتين بقدر ما شاءوا '),
(20005, 'John', 43, 6, 12, ' فلما شبعوا ، قال لتلاميذه : اجمعوا الكسر الفاضلة لكي لا يضيع شيء '),
(20006, 'John', 43, 6, 13, ' فجمعوا وملأوا اثنتي عشرة قفة من الكسر ، من خمسة أرغفة الشعير ، التي فضلت عن الآكلين '),
(20007, 'John', 43, 6, 14, ' فلما رأى الناس الآية التي صنعها يسوع قالوا : إن هذا هو بالحقيقة النبي الآتي إلى العالم '),
(20008, 'John', 43, 6, 15, ' وأما يسوع فإذ علم أنهم مزمعون أن يأتوا ويختطفوه ليجعلوه ملكا ، انصرف أيضا إلى الجبل وحده '),
(20009, 'John', 43, 6, 16, ' ولما كان المساء نزل تلاميذه إلى البحر '),
(20010, 'John', 43, 6, 17, ' فدخلوا السفينة وكانوا يذهبون إلى عبر البحر إلى كفرناحوم . وكان الظلام قد أقبل ، ولم يكن يسوع قد أتى إليهم '),
(20011, 'John', 43, 6, 18, ' وهاج البحر من ريح عظيمة تهب '),
(20012, 'John', 43, 6, 19, ' فلما كانوا قد جذفوا نحو خمس وعشرين أو ثلاثين غلوة ، نظروا يسوع ماشيا على البحر مقتربا من السفينة ، فخافوا '),
(20013, 'John', 43, 6, 20, ' فقال لهم : أنا هو ، لا تخافوا '),
(20014, 'John', 43, 6, 21, ' فرضوا أن يقبلوه في السفينة . وللوقت صارت السفينة إلى الأرض التي كانوا ذاهبين إليها '),
(20015, 'John', 43, 6, 22, ' وفي الغد لما رأى الجمع الذين كانوا واقفين في عبر البحر أنه لم تكن هناك سفينة أخرى سوى واحدة ، وهي تلك التي دخلها تلاميذه ، وأن يسوع لم يدخل السفينة مع تلاميذه بل مضى تلاميذه وحدهم '),
(20016, 'John', 43, 6, 23, ' غير أنه جاءت سفن من طبرية إلى قرب الموضع الذي أكلوا فيه الخبز ، إذ شكر الرب '),
(20017, 'John', 43, 6, 24, ' فلما رأى الجمع أن يسوع ليس هو هناك ولا تلاميذه ، دخلوا هم أيضا السفن وجاءوا إلى كفرناحوم يطلبون يسوع '),
(20018, 'John', 43, 6, 25, ' ولما وجدوه في عبر البحر ، قالوا له : يا معلم ، متى صرت هنا '),
(20019, 'John', 43, 6, 26, ' أجابهم يسوع وقال : الحق الحق أقول لكم : أنتم تطلبونني ليس لأنكم رأيتم آيات ، بل لأنكم أكلتم من الخبز فشبعتم '),
(20020, 'John', 43, 6, 27, ' اعملوا لا للطعام البائد ، بل للطعام الباقي للحياة الأبدية الذي يعطيكم ابن الإنسان ، لأن هذا الله الآب قد ختمه '),
(20021, 'John', 43, 6, 28, ' فقالوا له : ماذا نفعل حتى نعمل أعمال الله '),
(20022, 'John', 43, 6, 29, ' أجاب يسوع وقال لهم : هذا هو عمل الله : أن تؤمنوا بالذي هو أرسله '),
(20023, 'John', 43, 6, 30, ' فقالوا له : فأية آية تصنع لنرى ونؤمن بك ؟ ماذا تعمل '),
(20024, 'John', 43, 6, 31, ' آباؤنا أكلوا المن في البرية ، كما هو مكتوب : أنه أعطاهم خبزا من السماء ليأكلوا '),
(20025, 'John', 43, 6, 32, ' فقال لهم يسوع : الحق الحق أقول لكم : ليس موسى أعطاكم الخبز من السماء ، بل أبي يعطيكم الخبز الحقيقي من السماء '),
(20026, 'John', 43, 6, 33, ' لأن خبز الله هو النازل من السماء الواهب حياة للعالم '),
(20027, 'John', 43, 6, 34, ' فقالوا له : يا سيد ، أعطنا في كل حين هذا الخبز '),
(20028, 'John', 43, 6, 35, ' فقال لهم يسوع : أنا هو خبز الحياة . من يقبل إلي فلا يجوع ، ومن يؤمن بي فلا يعطش أبدا '),
(20029, 'John', 43, 6, 36, ' ولكني قلت لكم : إنكم قد رأيتموني ، ولستم تؤمنون '),
(20030, 'John', 43, 6, 37, ' كل ما يعطيني الآب فإلي يقبل ، ومن يقبل إلي لا أخرجه خارجا '),
(20031, 'John', 43, 6, 38, ' لأني قد نزلت من السماء ، ليس لأعمل مشيئتي ، بل مشيئة الذي أرسلني '),
(20032, 'John', 43, 6, 39, ' وهذه مشيئة الآب الذي أرسلني : أن كل ما أعطاني لا أتلف منه شيئا ، بل أقيمه في اليوم الأخير '),
(20033, 'John', 43, 6, 40, ' لأن هذه هي مشيئة الذي أرسلني : أن كل من يرى الابن ويؤمن به تكون له حياة أبدية ، وأنا أقيمه في اليوم الأخير '),
(20034, 'John', 43, 6, 41, ' فكان اليهود يتذمرون عليه لأنه قال : أنا هو الخبز الذي نزل من السماء '),
(20035, 'John', 43, 6, 42, ' وقالوا : أليس هذا هو يسوع بن يوسف ، الذي نحن عارفون بأبيه وأمه ؟ فكيف يقول هذا : إني نزلت من السماء '),
(20036, 'John', 43, 6, 43, ' فأجاب يسوع وقال لهم : لا تتذمروا فيما بينكم '),
(20037, 'John', 43, 6, 44, ' لا يقدر أحد أن يقبل إلي إن لم يجتذبه الآب الذي أرسلني ، وأنا أقيمه في اليوم الأخير '),
(20038, 'John', 43, 6, 45, ' إنه مكتوب في الأنبياء : ويكون الجميع متعلمين من الله . فكل من سمع من الآب وتعلم يقبل إلي '),
(20039, 'John', 43, 6, 46, ' ليس أن أحدا رأى الآب إلا الذي من الله . هذا قد رأى الآب '),
(20040, 'John', 43, 6, 47, ' الحق الحق أقول لكم : من يؤمن بي فله حياة أبدية '),
(20041, 'John', 43, 6, 48, ' أنا هو خبز الحياة '),
(20042, 'John', 43, 6, 49, ' آباؤكم أكلوا المن في البرية وماتوا '),
(20043, 'John', 43, 6, 50, ' هذا هو الخبز النازل من السماء ، لكي يأكل منه الإنسان ولا يموت '),
(20044, 'John', 43, 6, 51, ' أنا هو الخبز الحي الذي نزل من السماء . إن أكل أحد من هذا الخبز يحيا إلى الأبد . والخبز الذي أنا أعطي هو جسدي الذي أبذله من أجل حياة العالم '),
(20045, 'John', 43, 6, 52, ' فخاصم اليهود بعضهم بعضا قائلين : كيف يقدر هذا أن يعطينا جسده لنأكل '),
(20046, 'John', 43, 6, 53, ' فقال لهم يسوع : الحق الحق أقول لكم : إن لم تأكلوا جسد ابن الإنسان وتشربوا دمه ، فليس لكم حياة فيكم '),
(20047, 'John', 43, 6, 54, ' من يأكل جسدي ويشرب دمي فله حياة أبدية ، وأنا أقيمه في اليوم الأخير '),
(20048, 'John', 43, 6, 55, ' لأن جسدي مأكل حق ودمي مشرب حق '),
(20049, 'John', 43, 6, 56, ' من يأكل جسدي ويشرب دمي يثبت في وأنا فيه '),
(20050, 'John', 43, 6, 57, ' كما أرسلني الآب الحي ، وأنا حي بالآب ، فمن يأكلني فهو يحيا بي '),
(20051, 'John', 43, 6, 58, ' هذا هو الخبز الذي نزل من السماء . ليس كما أكل آباؤكم المن وماتوا . من يأكل هذا الخبز فإنه يحيا إلى الأبد '),
(20052, 'John', 43, 6, 59, ' قال هذا في المجمع وهو يعلم في كفرناحوم '),
(20053, 'John', 43, 6, 60, ' فقال كثيرون من تلاميذه ، إذ سمعوا : إن هذا الكلام صعب من يقدر أن يسمعه '),
(20054, 'John', 43, 6, 61, ' فعلم يسوع في نفسه أن تلاميذه يتذمرون على هذا ، فقال لهم : أهذا يعثركم '),
(20055, 'John', 43, 6, 62, ' فإن رأيتم ابن الإنسان صاعدا إلى حيث كان أولا '),
(20056, 'John', 43, 6, 63, ' الروح هو الذي يحيي . أما الجسد فلا يفيد شيئا . الكلام الذي أكلمكم به هو روح وحياة '),
(20057, 'John', 43, 6, 64, ' ولكن منكم قوم لا يؤمنون . لأن يسوع من البدء علم من هم الذين لا يؤمنون ، ومن هو الذي يسلمه '),
(20058, 'John', 43, 6, 65, ' فقال : لهذا قلت لكم : إنه لا يقدر أحد أن يأتي إلي إن لم يعط من أبي '),
(20059, 'John', 43, 6, 66, ' من هذا الوقت رجع كثيرون من تلاميذه إلى الوراء ، ولم يعودوا يمشون معه '),
(20060, 'John', 43, 6, 67, ' فقال يسوع للاثني عشر : ألعلكم أنتم أيضا تريدون أن تمضوا '),
(20061, 'John', 43, 6, 68, ' فأجابه سمعان بطرس : يا رب ، إلى من نذهب ؟ كلام الحياة الأبدية عندك '),
(20062, 'John', 43, 6, 69, ' ونحن قد آمنا وعرفنا أنك أنت المسيح ابن الله الحي '),
(20063, 'John', 43, 6, 70, ' أجابهم يسوع : أليس أني أنا اخترتكم ، الاثني عشر ؟ وواحد منكم شيطان '),
(20064, 'John', 43, 6, 71, ' قال عن يهوذا سمعان الإسخريوطي ، لأن هذا كان مزمعا أن يسلمه ، وهو واحد من الاثني عشر '),
(20065, 'John', 43, 7, 1, ' وكان يسوع يتردد بعد هذا في الجليل ، لأنه لم يرد أن يتردد في اليهودية لأن اليهود كانوا يطلبون أن يقتلوه '),
(20066, 'John', 43, 7, 2, ' وكان عيد اليهود ، عيد المظال ، قريبا '),
(20067, 'John', 43, 7, 3, ' فقال له إخوته : انتقل من هنا واذهب إلى اليهودية ، لكي يرى تلاميذك أيضا أعمالك التي تعمل '),
(20068, 'John', 43, 7, 4, ' لأنه ليس أحد يعمل شيئا في الخفاء وهو يريد أن يكون علانية . إن كنت تعمل هذه الأشياء فأظهر نفسك للعالم '),
(20069, 'John', 43, 7, 5, ' لأن إخوته أيضا لم يكونوا يؤمنون به '),
(20070, 'John', 43, 7, 6, ' فقال لهم يسوع : إن وقتي لم يحضر بعد ، وأما وقتكم ففي كل حين حاضر '),
(20071, 'John', 43, 7, 7, ' لا يقدر العالم أن يبغضكم ، ولكنه يبغضني أنا ، لأني أشهد عليه أن أعماله شريرة '),
(20072, 'John', 43, 7, 8, ' اصعدوا أنتم إلى هذا العيد . أنا لست أصعد بعد إلى هذا العيد ، لأن وقتي لم يكمل بعد '),
(20073, 'John', 43, 7, 9, ' قال لهم هذا ومكث في الجليل '),
(20074, 'John', 43, 7, 10, ' ولما كان إخوته قد صعدوا ، حينئذ صعد هو أيضا إلى العيد ، لا ظاهرا بل كأنه في الخفاء '),
(20075, 'John', 43, 7, 11, ' فكان اليهود يطلبونه في العيد ، ويقولون : أين ذاك '),
(20076, 'John', 43, 7, 12, ' وكان في الجموع مناجاة كثيرة من نحوه . بعضهم يقولون : إنه صالح . وآخرون يقولون : لا ، بل يضل الشعب '),
(20077, 'John', 43, 7, 13, ' ولكن لم يكن أحد يتكلم عنه جهارا لسبب الخوف من اليهود '),
(20078, 'John', 43, 7, 14, ' ولما كان العيد قد انتصف ، صعد يسوع إلى الهيكل ، وكان يعلم '),
(20079, 'John', 43, 7, 15, ' فتعجب اليهود قائلين : كيف هذا يعرف الكتب ، وهو لم يتعلم '),
(20080, 'John', 43, 7, 16, ' أجابهم يسوع وقال : تعليمي ليس لي بل للذي أرسلني '),
(20081, 'John', 43, 7, 17, ' إن شاء أحد أن يعمل مشيئته يعرف التعليم ، هل هو من الله ، أم أتكلم أنا من نفسي '),
(20082, 'John', 43, 7, 18, ' من يتكلم من نفسه يطلب مجد نفسه ، وأما من يطلب مجد الذي أرسله فهو صادق وليس فيه ظلم '),
(20083, 'John', 43, 7, 19, ' أليس موسى قد أعطاكم الناموس ؟ وليس أحد منكم يعمل الناموس لماذا تطلبون أن تقتلوني '),
(20084, 'John', 43, 7, 20, ' أجاب الجمع وقالوا : بك شيطان . من يطلب أن يقتلك '),
(20085, 'John', 43, 7, 21, ' أجاب يسوع وقال لهم : عملا واحدا عملت فتتعجبون جميعا '),
(20086, 'John', 43, 7, 22, ' لهذا أعطاكم موسى الختان ، ليس أنه من موسى ، بل من الآباء . ففي السبت تختنون الإنسان '),
(20087, 'John', 43, 7, 23, ' فإن كان الإنسان يقبل الختان في السبت ، لئلا ينقض ناموس موسى ، أفتسخطون علي لأني شفيت إنسانا كله في السبت '),
(20088, 'John', 43, 7, 24, ' لا تحكموا حسب الظاهر بل احكموا حكما عادلا '),
(20089, 'John', 43, 7, 25, ' فقال قوم من أهل أورشليم : أليس هذا هو الذي يطلبون أن يقتلوه '),
(20090, 'John', 43, 7, 26, ' وها هو يتكلم جهارا ولا يقولون له شيئا ألعل الرؤساء عرفوا يقينا أن هذا هو المسيح حقا '),
(20091, 'John', 43, 7, 27, ' ولكن هذا نعلم من أين هو ، وأما المسيح فمتى جاء لا يعرف أحد من أين هو '),
(20092, 'John', 43, 7, 28, ' فنادى يسوع وهو يعلم في الهيكل قائلا : تعرفونني وتعرفون من أين أنا ، ومن نفسي لم آت ، بل الذي أرسلني هو حق ، الذي أنتم لستم تعرفونه '),
(20093, 'John', 43, 7, 29, ' أنا أعرفه لأني منه ، وهو أرسلني '),
(20094, 'John', 43, 7, 30, ' فطلبوا أن يمسكوه ، ولم يلق أحد يدا عليه ، لأن ساعته لم تكن قد جاءت بعد '),
(20095, 'John', 43, 7, 31, ' فآمن به كثيرون من الجمع ، وقالوا : ألعل المسيح متى جاء يعمل آيات أكثر من هذه التي عملها هذا '),
(20096, 'John', 43, 7, 32, ' سمع الفريسيون الجمع يتناجون بهذا من نحوه ، فأرسل الفريسيون ورؤساء الكهنة خداما ليمسكوه '),
(20097, 'John', 43, 7, 33, ' فقال لهم يسوع : أنا معكم زمانا يسيرا بعد ، ثم أمضي إلى الذي أرسلني '),
(20098, 'John', 43, 7, 34, ' ستطلبونني ولا تجدونني ، وحيث أكون أنا لا تقدرون أنتم أن تأتوا '),
(20099, 'John', 43, 7, 35, ' فقال اليهود فيما بينهم : إلى أين هذا مزمع أن يذهب حتى لا نجده نحن ؟ ألعله مزمع أن يذهب إلى شتات اليونانيين ويعلم اليونانيين '),
(20100, 'John', 43, 7, 36, ' ما هذا القول الذي قال : ستطلبونني ولا تجدونني ، وحيث أكون أنا لا تقدرون أنتم أن تأتوا '),
(20101, 'John', 43, 7, 37, ' وفي اليوم الأخير العظيم من العيد وقف يسوع ونادى قائلا : إن عطش أحد فليقبل إلي ويشرب '),
(20102, 'John', 43, 7, 38, ' من آمن بي ، كما قال الكتاب ، تجري من بطنه أنهار ماء حي '),
(20103, 'John', 43, 7, 39, ' قال هذا عن الروح الذي كان المؤمنون به مزمعين أن يقبلوه ، لأن الروح القدس لم يكن قد أعطي بعد ، لأن يسوع لم يكن قد مجد بعد '),
(20104, 'John', 43, 7, 40, ' فكثيرون من الجمع لما سمعوا هذا الكلام قالوا : هذا بالحقيقة هو النبي '),
(20105, 'John', 43, 7, 41, ' آخرون قالوا : هذا هو المسيح . وآخرون قالوا : ألعل المسيح من الجليل يأتي '),
(20106, 'John', 43, 7, 42, ' ألم يقل الكتاب إنه من نسل داود ، ومن بيت لحم ، القرية التي كان داود فيها ، يأتي المسيح '),
(20107, 'John', 43, 7, 43, ' فحدث انشقاق في الجمع لسببه '),
(20108, 'John', 43, 7, 44, ' وكان قوم منهم يريدون أن يمسكوه ، ولكن لم يلق أحد عليه الأيادي '),
(20109, 'John', 43, 7, 45, ' فجاء الخدام إلى رؤساء الكهنة والفريسيين . فقال هؤلاء لهم : لماذا لم تأتوا به '),
(20110, 'John', 43, 7, 46, ' أجاب الخدام : لم يتكلم قط إنسان هكذا مثل هذا الإنسان '),
(20111, 'John', 43, 7, 47, ' فأجابهم الفريسيون : ألعلكم أنتم أيضا قد ضللتم '),
(20112, 'John', 43, 7, 48, ' ألعل أحدا من الرؤساء أو من الفريسيين آمن به '),
(20113, 'John', 43, 7, 49, ' ولكن هذا الشعب الذي لا يفهم الناموس هو ملعون '),
(20114, 'John', 43, 7, 50, ' قال لهم نيقوديموس ، الذي جاء إليه ليلا ، وهو واحد منهم '),
(20115, 'John', 43, 7, 51, ' ألعل ناموسنا يدين إنسانا لم يسمع منه أولا ويعرف ماذا فعل '),
(20116, 'John', 43, 7, 52, ' أجابوا وقالوا له : ألعلك أنت أيضا من الجليل ؟ فتش وانظر إنه لم يقم نبي من الجليل '),
(20117, 'John', 43, 7, 53, ' فمضى كل واحد إلى بيته '),
(20118, 'John', 43, 8, 1, ' أما يسوع فمضى إلى جبل الزيتون '),
(20119, 'John', 43, 8, 2, ' ثم حضر أيضا إلى الهيكل في الصبح ، وجاء إليه جميع الشعب فجلس يعلمهم '),
(20120, 'John', 43, 8, 3, ' وقدم إليه الكتبة والفريسيون امرأة أمسكت في زنا . ولما أقاموها في الوسط '),
(20121, 'John', 43, 8, 4, ' قالوا له : يا معلم ، هذه المرأة أمسكت وهي تزني في ذات الفعل '),
(20122, 'John', 43, 8, 5, ' وموسى في الناموس أوصانا أن مثل هذه ترجم . فماذا تقول أنت '),
(20123, 'John', 43, 8, 6, ' قالوا هذا ليجربوه ، لكي يكون لهم ما يشتكون به عليه . وأما يسوع فانحنى إلى أسفل وكان يكتب بإصبعه على الأرض '),
(20124, 'John', 43, 8, 7, ' ولما استمروا يسألونه ، انتصب وقال لهم : من كان منكم بلا خطية فليرمها أولا بحجر '),
(20125, 'John', 43, 8, 8, ' ثم انحنى أيضا إلى أسفل وكان يكتب على الأرض '),
(20126, 'John', 43, 8, 9, ' وأما هم فلما سمعوا وكانت ضمائرهم تبكتهم ، خرجوا واحدا فواحدا ، مبتدئين من الشيوخ إلى الآخرين . وبقي يسوع وحده والمرأة واقفة في الوسط '),
(20127, 'John', 43, 8, 10, ' فلما انتصب يسوع ولم ينظر أحدا سوى المرأة ، قال لها : يا امرأة ، أين هم أولئك المشتكون عليك ؟ أما دانك أحد '),
(20128, 'John', 43, 8, 11, ' فقالت لا أحد ، يا سيد . فقال لها يسوع : ولا أنا أدينك . اذهبي ولا تخطئي أيضا '),
(20129, 'John', 43, 8, 12, ' ثم كلمهم يسوع أيضا قائلا : أنا هو نور العالم . من يتبعني فلا يمشي في الظلمة بل يكون له نور الحياة '),
(20130, 'John', 43, 8, 13, ' فقال له الفريسيون : أنت تشهد لنفسك . شهادتك ليست حقا '),
(20131, 'John', 43, 8, 14, ' أجاب يسوع وقال لهم : وإن كنت أشهد لنفسي فشهادتي حق ، لأني أعلم من أين أتيت وإلى أين أذهب . وأما أنتم فلا تعلمون من أين آتي ولا إلى أين أذهب '),
(20132, 'John', 43, 8, 15, ' أنتم حسب الجسد تدينون ، أما أنا فلست أدين أحدا '),
(20133, 'John', 43, 8, 16, ' وإن كنت أنا أدين فدينونتي حق ، لأني لست وحدي ، بل أنا والآب الذي أرسلني '),
(20134, 'John', 43, 8, 17, ' وأيضا في ناموسكم مكتوب أن شهادة رجلين حق '),
(20135, 'John', 43, 8, 18, ' أنا هو الشاهد لنفسي ، ويشهد لي الآب الذي أرسلني '),
(20136, 'John', 43, 8, 19, ' فقالوا له : أين هو أبوك ؟ أجاب يسوع : لستم تعرفونني أنا ولا أبي . لو عرفتموني لعرفتم أبي أيضا '),
(20137, 'John', 43, 8, 20, ' هذا الكلام قاله يسوع في الخزانة وهو يعلم في الهيكل . ولم يمسكه أحد ، لأن ساعته لم تكن قد جاءت بعد '),
(20138, 'John', 43, 8, 21, ' قال لهم يسوع أيضا : أنا أمضي وستطلبونني ، وتموتون في خطيتكم . حيث أمضي أنا لا تقدرون أنتم أن تأتوا '),
(20139, 'John', 43, 8, 22, ' فقال اليهود : ألعله يقتل نفسه حتى يقول : حيث أمضي أنا لا تقدرون أنتم أن تأتوا '),
(20140, 'John', 43, 8, 23, ' فقال لهم : أنتم من أسفل ، أما أنا فمن فوق . أنتم من هذا العالم ، أما أنا فلست من هذا العالم '),
(20141, 'John', 43, 8, 24, ' فقلت لكم : إنكم تموتون في خطاياكم ، لأنكم إن لم تؤمنوا أني أنا هو تموتون في خطاياكم '),
(20142, 'John', 43, 8, 25, ' فقالوا له : من أنت ؟ فقال لهم يسوع : أنا من البدء ما أكلمكم أيضا به '),
(20143, 'John', 43, 8, 26, ' إن لي أشياء كثيرة أتكلم وأحكم بها من نحوكم ، لكن الذي أرسلني هو حق . وأنا ما سمعته منه ، فهذا أقوله للعالم '),
(20144, 'John', 43, 8, 27, ' ولم يفهموا أنه كان يقول لهم عن الآب '),
(20145, 'John', 43, 8, 28, ' فقال لهم يسوع : متى رفعتم ابن الإنسان ، فحينئذ تفهمون أني أنا هو ، ولست أفعل شيئا من نفسي ، بل أتكلم بهذا كما علمني أبي '),
(20146, 'John', 43, 8, 29, ' والذي أرسلني هو معي ، ولم يتركني الآب وحدي ، لأني في كل حين أفعل ما يرضيه ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(20147, 'John', 43, 8, 30, ' وبينما هو يتكلم بهذا آمن به كثيرون '),
(20148, 'John', 43, 8, 31, ' فقال يسوع لليهود الذين آمنوا به : إنكم إن ثبتم في كلامي فبالحقيقة تكونون تلاميذي '),
(20149, 'John', 43, 8, 32, ' وتعرفون الحق ، والحق يحرركم '),
(20150, 'John', 43, 8, 33, ' أجابوه : إننا ذرية إبراهيم ، ولم نستعبد لأحد قط كيف تقول أنت : إنكم تصيرون أحرارا '),
(20151, 'John', 43, 8, 34, ' أجابهم يسوع : الحق الحق أقول لكم : إن كل من يعمل الخطية هو عبد للخطية '),
(20152, 'John', 43, 8, 35, ' والعبد لا يبقى في البيت إلى الأبد ، أما الابن فيبقى إلى الأبد '),
(20153, 'John', 43, 8, 36, ' فإن حرركم الابن فبالحقيقة تكونون أحرارا '),
(20154, 'John', 43, 8, 37, ' أنا عالم أنكم ذرية إبراهيم . لكنكم تطلبون أن تقتلوني لأن كلامي لا موضع له فيكم '),
(20155, 'John', 43, 8, 38, ' أنا أتكلم بما رأيت عند أبي ، وأنتم تعملون ما رأيتم عند أبيكم '),
(20156, 'John', 43, 8, 39, ' أجابوا وقالوا له : أبونا هو إبراهيم . قال لهم يسوع : لو كنتم أولاد إبراهيم ، لكنتم تعملون أعمال إبراهيم '),
(20157, 'John', 43, 8, 40, ' ولكنكم الآن تطلبون أن تقتلوني ، وأنا إنسان قد كلمكم بالحق الذي سمعه من الله . هذا لم يعمله إبراهيم '),
(20158, 'John', 43, 8, 41, ' أنتم تعملون أعمال أبيكم . فقالوا له : إننا لم نولد من زنا . لنا أب واحد وهو الله '),
(20159, 'John', 43, 8, 42, ' فقال لهم يسوع : لو كان الله أباكم لكنتم تحبونني ، لأني خرجت من قبل الله وأتيت . لأني لم آت من نفسي ، بل ذاك أرسلني '),
(20160, 'John', 43, 8, 43, ' لماذا لا تفهمون كلامي ؟ لأنكم لا تقدرون أن تسمعوا قولي '),
(20161, 'John', 43, 8, 44, ' أنتم من أب هو إبليس ، وشهوات أبيكم تريدون أن تعملوا . ذاك كان قتالا للناس من البدء ، ولم يثبت في الحق لأنه ليس فيه حق . متى تكلم بالكذب فإنما يتكلم مما له ، لأنه كذاب وأبو الكذاب '),
(20162, 'John', 43, 8, 45, ' وأما أنا فلأني أقول الحق لستم تؤمنون بي '),
(20163, 'John', 43, 8, 46, ' من منكم يبكتني على خطية ؟ فإن كنت أقول الحق ، فلماذا لستم تؤمنون بي '),
(20164, 'John', 43, 8, 47, ' الذي من الله يسمع كلام الله . لذلك أنتم لستم تسمعون ، لأنكم لستم من الله '),
(20165, 'John', 43, 8, 48, ' فأجاب اليهود وقالوا له : ألسنا نقول حسنا : إنك سامري وبك شيطان '),
(20166, 'John', 43, 8, 49, ' أجاب يسوع : أنا ليس بي شيطان ، لكني أكرم أبي وأنتم تهينونني '),
(20167, 'John', 43, 8, 50, ' أنا لست أطلب مجدي . يوجد من يطلب ويدين '),
(20168, 'John', 43, 8, 51, ' الحق الحق أقول لكم : إن كان أحد يحفظ كلامي فلن يرى الموت إلى الأبد '),
(20169, 'John', 43, 8, 52, ' فقال له اليهود : الآن علمنا أن بك شيطانا . قد مات إبراهيم والأنبياء ، وأنت تقول : إن كان أحد يحفظ كلامي فلن يذوق الموت إلى الأبد '),
(20170, 'John', 43, 8, 53, ' ألعلك أعظم من أبينا إبراهيم الذي مات ؟ والأنبياء ماتوا . من تجعل نفسك '),
(20171, 'John', 43, 8, 54, ' أجاب يسوع : إن كنت أمجد نفسي فليس مجدي شيئا . أبي هو الذي يمجدني ، الذي تقولون أنتم إنه إلهكم '),
(20172, 'John', 43, 8, 55, ' ولستم تعرفونه . وأما أنا فأعرفه . وإن قلت : إني لست أعرفه أكون مثلكم كاذبا ، لكني أعرفه وأحفظ قوله '),
(20173, 'John', 43, 8, 56, ' أبوكم إبراهيم تهلل بأن يرى يومي فرأى وفرح '),
(20174, 'John', 43, 8, 57, ' فقال له اليهود : ليس لك خمسون سنة بعد ، أفرأيت إبراهيم '),
(20175, 'John', 43, 8, 58, ' قال لهم يسوع : الحق الحق أقول لكم : قبل أن يكون إبراهيم أنا كائن '),
(20176, 'John', 43, 8, 59, ' فرفعوا حجارة ليرجموه . أما يسوع فاختفى وخرج من الهيكل مجتازا في وسطهم ومضى هكذا '),
(20177, 'John', 43, 9, 1, ' وفيما هو مجتاز رأى إنسانا أعمى منذ ولادته '),
(20178, 'John', 43, 9, 2, ' فسأله تلاميذه قائلين : يا معلم ، من أخطأ : هذا أم أبواه حتى ولد أعمى '),
(20179, 'John', 43, 9, 3, ' أجاب يسوع : لا هذا أخطأ ولاأبواه ، لكن لتظهر أعمال الله فيه '),
(20180, 'John', 43, 9, 4, ' ينبغي أن أعمل أعمال الذي أرسلني ما دام نهار . يأتي ليل حين لا يستطيع أحد أن يعمل '),
(20181, 'John', 43, 9, 5, ' ما دمت في العالم فأنا نور العالم '),
(20182, 'John', 43, 9, 6, ' قال هذا وتفل على الأرض وصنع من التفل طينا وطلى بالطين عيني الأعمى '),
(20183, 'John', 43, 9, 7, ' وقال له : اذهب اغتسل في بركة سلوام الذي تفسيره : مرسل ، فمضى واغتسل وأتى بصيرا '),
(20184, 'John', 43, 9, 8, ' فالجيران والذين كانوا يرونه قبلا أنه كان أعمى ، قالوا : أليس هذا هو الذي كان يجلس ويستعطي '),
(20185, 'John', 43, 9, 9, ' آخرون قالوا : هذا هو . وآخرون : إنه يشبهه . وأما هو فقال : إني أنا هو '),
(20186, 'John', 43, 9, 10, ' فقالوا له : كيف انفتحت عيناك '),
(20187, 'John', 43, 9, 11, ' أجاب ذاك وقال : إنسان يقال له يسوع صنع طينا وطلى عيني ، وقال لي : اذهب إلى بركة سلوام واغتسل . فمضيت واغتسلت فأبصرت '),
(20188, 'John', 43, 9, 12, ' فقالوا له : أين ذاك ؟ قال : لا أعلم '),
(20189, 'John', 43, 9, 13, ' فأتوا إلى الفريسيين بالذي كان قبلا أعمى '),
(20190, 'John', 43, 9, 14, ' وكان سبت حين صنع يسوع الطين وفتح عينيه '),
(20191, 'John', 43, 9, 15, ' فسأله الفريسيون أيضا كيف أبصر ، فقال لهم : وضع طينا على عيني واغتسلت ، فأنا أبصر '),
(20192, 'John', 43, 9, 16, ' فقال قوم من الفريسيين : هذا الإنسان ليس من الله ، لأنه لا يحفظ السبت . آخرون قالوا : كيف يقدر إنسان خاطئ أن يعمل مثل هذه الآيات ؟ وكان بينهم انشقاق '),
(20193, 'John', 43, 9, 17, ' قالوا أيضا للأعمى : ماذا تقول أنت عنه من حيث إنه فتح عينيك ؟ فقال : إنه نبي '),
(20194, 'John', 43, 9, 18, ' فلم يصدق اليهود عنه أنه كان أعمى فأبصر حتى دعوا أبوي الذي أبصر '),
(20195, 'John', 43, 9, 19, ' فسألوهما قائلين : أهذا ابنكما الذي تقولان إنه ولد أعمى ؟ فكيف يبصر الآن '),
(20196, 'John', 43, 9, 20, ' أجابهم أبواه وقالا : نعلم أن هذا ابننا ، وأنه ولد أعمى '),
(20197, 'John', 43, 9, 21, ' وأما كيف يبصر الآن فلا نعلم . أو من فتح عينيه فلا نعلم . هو كامل السن . اسألوه فهو يتكلم عن نفسه '),
(20198, 'John', 43, 9, 22, ' قال أبواه هذا لأنهما كانا يخافان من اليهود ، لأن اليهود كانوا قد تعاهدوا أنه إن اعترف أحد بأنه المسيح يخرج من المجمع '),
(20199, 'John', 43, 9, 23, ' لذلك قال أبواه : إنه كامل السن ، اسألوه '),
(20200, 'John', 43, 9, 24, ' فدعوا ثانية الإنسان الذي كان أعمى ، وقالوا له : أعط مجدا لله . نحن نعلم أن هذا الإنسان خاطئ '),
(20201, 'John', 43, 9, 25, ' فأجاب ذاك وقال : أخاطئ هو ؟ لست أعلم . إنما أعلم شيئا واحدا : أني كنت أعمى والآن أبصر '),
(20202, 'John', 43, 9, 26, ' فقالوا له أيضا : ماذا صنع بك ؟ كيف فتح عينيك '),
(20203, 'John', 43, 9, 27, ' أجابهم : قد قلت لكم ولم تسمعوا . لماذا تريدون أن تسمعوا أيضا ؟ ألعلكم أنتم تريدون أن تصيروا له تلاميذ '),
(20204, 'John', 43, 9, 28, ' فشتموه وقالوا : أنت تلميذ ذاك ، وأما نحن فإننا تلاميذ موسى '),
(20205, 'John', 43, 9, 29, ' نحن نعلم أن موسى كلمه الله ، وأما هذا فما نعلم من أين هو '),
(20206, 'John', 43, 9, 30, ' أجاب الرجل وقال لهم : إن في هذا عجبا إنكم لستم تعلمون من أين هو ، وقد فتح عيني '),
(20207, 'John', 43, 9, 31, ' ونعلم أن الله لا يسمع للخطاة . ولكن إن كان أحد يتقي الله ويفعل مشيئته ، فلهذا يسمع '),
(20208, 'John', 43, 9, 32, ' منذ الدهر لم يسمع أن أحدا فتح عيني مولود أعمى '),
(20209, 'John', 43, 9, 33, ' لو لم يكن هذا من الله لم يقدر أن يفعل شيئا '),
(20210, 'John', 43, 9, 34, ' أجابوا وقالوا له : في الخطايا ولدت أنت بجملتك ، وأنت تعلمنا فأخرجوه خارجا '),
(20211, 'John', 43, 9, 35, ' فسمع يسوع أنهم أخرجوه خارجا ، فوجده وقال له : أتؤمن بابن الله '),
(20212, 'John', 43, 9, 36, ' أجاب ذاك وقال : من هو يا سيد لأومن به '),
(20213, 'John', 43, 9, 37, ' فقال له يسوع : قد رأيته ، والذي يتكلم معك هو هو '),
(20214, 'John', 43, 9, 38, ' فقال : أومن يا سيد . وسجد له '),
(20215, 'John', 43, 9, 39, ' فقال يسوع : لدينونة أتيت أنا إلى هذا العالم ، حتى يبصر الذين لا يبصرون ويعمى الذين يبصرون '),
(20216, 'John', 43, 9, 40, ' فسمع هذا الذين كانوا معه من الفريسيين ، وقالوا له : ألعلنا نحن أيضا عميان '),
(20217, 'John', 43, 9, 41, ' قال لهم يسوع : لو كنتم عميانا لما كانت لكم خطية . ولكن الآن تقولون إننا نبصر ، فخطيتكم باقية '),
(20218, 'John', 43, 10, 1, ' الحق الحق أقول لكم : إن الذي لا يدخل من الباب إلى حظيرة الخراف ، بل يطلع من موضع آخر ، فذاك سارق ولص '),
(20219, 'John', 43, 10, 2, ' وأما الذي يدخل من الباب فهو راعي الخراف '),
(20220, 'John', 43, 10, 3, ' لهذا يفتح البواب ، والخراف تسمع صوته ، فيدعو خرافه الخاصة بأسماء ويخرجها '),
(20221, 'John', 43, 10, 4, ' ومتى أخرج خرافه الخاصة يذهب أمامها ، والخراف تتبعه ، لأنها تعرف صوته '),
(20222, 'John', 43, 10, 5, ' وأما الغريب فلا تتبعه بل تهرب منه ، لأنها لا تعرف صوت الغرباء '),
(20223, 'John', 43, 10, 6, ' هذا المثل قاله لهم يسوع ، وأما هم فلم يفهموا ما هو الذي كان يكلمهم به '),
(20224, 'John', 43, 10, 7, ' فقال لهم يسوع أيضا : الحق الحق أقول لكم : إني أنا باب الخراف '),
(20225, 'John', 43, 10, 8, ' جميع الذين أتوا قبلي هم سراق ولصوص ، ولكن الخراف لم تسمع لهم '),
(20226, 'John', 43, 10, 9, ' أنا هو الباب . إن دخل بي أحد فيخلص ويدخل ويخرج ويجد مرعى '),
(20227, 'John', 43, 10, 10, ' السارق لا يأتي إلا ليسرق ويذبح ويهلك ، وأما أنا فقد أتيت لتكون لهم حياة وليكون لهم أفضل '),
(20228, 'John', 43, 10, 11, ' أنا هو الراعي الصالح ، والراعي الصالح يبذل نفسه عن الخراف '),
(20229, 'John', 43, 10, 12, ' وأما الذي هو أجير ، وليس راعيا ، الذي ليست الخراف له ، فيرى الذئب مقبلا ويترك الخراف ويهرب ، فيخطف الذئب الخراف ويبددها '),
(20230, 'John', 43, 10, 13, ' والأجير يهرب لأنه أجير ، ولا يبالي بالخراف '),
(20231, 'John', 43, 10, 14, ' أما أنا فإني الراعي الصالح ، وأعرف خاصتي وخاصتي تعرفني '),
(20232, 'John', 43, 10, 15, ' كما أن الآب يعرفني وأنا أعرف الآب . وأنا أضع نفسي عن الخراف '),
(20233, 'John', 43, 10, 16, ' ولي خراف أخر ليست من هذه الحظيرة ، ينبغي أن آتي بتلك أيضا فتسمع صوتي ، وتكون رعية واحدة وراع واحد '),
(20234, 'John', 43, 10, 17, ' لهذا يحبني الآب ، لأني أضع نفسي لآخذها أيضا '),
(20235, 'John', 43, 10, 18, ' ليس أحد يأخذها مني ، بل أضعها أنا من ذاتي . لي سلطان أن أضعها ولي سلطان أن آخذها أيضا . هذه الوصية قبلتها من أبي '),
(20236, 'John', 43, 10, 19, ' فحدث أيضا انشقاق بين اليهود بسبب هذا الكلام '),
(20237, 'John', 43, 10, 20, ' فقال كثيرون منهم : به شيطان وهو يهذي . لماذا تستمعون له '),
(20238, 'John', 43, 10, 21, ' آخرون قالوا : ليس هذا كلام من به شيطان . ألعل شيطانا يقدر أن يفتح أعين العميان '),
(20239, 'John', 43, 10, 22, ' وكان عيد التجديد في أورشليم ، وكان شتاء '),
(20240, 'John', 43, 10, 23, ' وكان يسوع يتمشى في الهيكل في رواق سليمان '),
(20241, 'John', 43, 10, 24, ' فاحتاط به اليهود وقالوا له : إلى متى تعلق أنفسنا ؟ إن كنت أنت المسيح فقل لنا جهرا '),
(20242, 'John', 43, 10, 25, ' أجابهم يسوع : إني قلت لكم ولستم تؤمنون . الأعمال التي أنا أعملها باسم أبي هي تشهد لي '),
(20243, 'John', 43, 10, 26, ' ولكنكم لستم تؤمنون لأنكم لستم من خرافي ، كما قلت لكم '),
(20244, 'John', 43, 10, 27, ' خرافي تسمع صوتي ، وأنا أعرفها فتتبعني '),
(20245, 'John', 43, 10, 28, ' وأنا أعطيها حياة أبدية ، ولن تهلك إلى الأبد ، ولا يخطفها أحد من يدي '),
(20246, 'John', 43, 10, 29, ' أبي الذي أعطاني إياها هو أعظم من الكل ، ولا يقدر أحد أن يخطف من يد أبي '),
(20247, 'John', 43, 10, 30, ' أنا والآب واحد '),
(20248, 'John', 43, 10, 31, ' فتناول اليهود أيضا حجارة ليرجموه '),
(20249, 'John', 43, 10, 32, ' أجابهم يسوع : أعمالا كثيرة حسنة أريتكم من عند أبي . بسبب أي عمل منها ترجمونني '),
(20250, 'John', 43, 10, 33, ' أجابه اليهود قائلين : لسنا نرجمك لأجل عمل حسن ، بل لأجل تجديف ، فإنك وأنت إنسان تجعل نفسك إلها '),
(20251, 'John', 43, 10, 34, ' أجابهم يسوع : أليس مكتوبا في ناموسكم : أنا قلت إنكم آلهة '),
(20252, 'John', 43, 10, 35, ' إن قال آلهة لأولئك الذين صارت إليهم كلمة الله ، ولا يمكن أن ينقض المكتوب '),
(20253, 'John', 43, 10, 36, ' فالذي قدسه الآب وأرسله إلى العالم ، أتقولون له : إنك تجدف ، لأني قلت : إني ابن الله '),
(20254, 'John', 43, 10, 37, ' إن كنت لست أعمل أعمال أبي فلا تؤمنوا بي '),
(20255, 'John', 43, 10, 38, ' ولكن إن كنت أعمل ، فإن لم تؤمنوا بي فآمنوا بالأعمال ، لكي تعرفوا وتؤمنوا أن الآب في وأنا فيه '),
(20256, 'John', 43, 10, 39, ' فطلبوا أيضا أن يمسكوه فخرج من أيديهم '),
(20257, 'John', 43, 10, 40, ' ومضى أيضا إلى عبر الأردن إلى المكان الذي كان يوحنا يعمد فيه أولا ومكث هناك '),
(20258, 'John', 43, 10, 41, ' فأتى إليه كثيرون وقالوا : إن يوحنا لم يفعل آية واحدة ، ولكن كل ما قاله يوحنا عن هذا كان حقا '),
(20259, 'John', 43, 10, 42, ' فآمن كثيرون به هناك '),
(20260, 'John', 43, 11, 1, ' وكان إنسان مريضا وهو لعازر ، من بيت عنيا من قرية مريم ومرثا أختها '),
(20261, 'John', 43, 11, 2, ' وكانت مريم ، التي كان لعازر أخوها مريضا ، هي التي دهنت الرب بطيب ، ومسحت رجليه بشعرها '),
(20262, 'John', 43, 11, 3, ' فأرسلت الأختان إليه قائلتين : يا سيد ، هوذا الذي تحبه مريض '),
(20263, 'John', 43, 11, 4, ' فلما سمع يسوع ، قال : هذا المرض ليس للموت ، بل لأجل مجد الله ، ليتمجد ابن الله به '),
(20264, 'John', 43, 11, 5, ' وكان يسوع يحب مرثا وأختها ولعازر '),
(20265, 'John', 43, 11, 6, ' فلما سمع أنه مريض مكث حينئذ في الموضع الذي كان فيه يومين '),
(20266, 'John', 43, 11, 7, ' ثم بعد ذلك قال لتلاميذه : لنذهب إلى اليهودية أيضا '),
(20267, 'John', 43, 11, 8, ' قال له التلاميذ : يا معلم ، الآن كان اليهود يطلبون أن يرجموك ، وتذهب أيضا إلى هناك '),
(20268, 'John', 43, 11, 9, ' أجاب يسوع : أليست ساعات النهار اثنتي عشرة ؟ إن كان أحد يمشي في النهار لا يعثر لأنه ينظر نور هذا العالم '),
(20269, 'John', 43, 11, 10, ' ولكن إن كان أحد يمشي في الليل يعثر ، لأن النور ليس فيه '),
(20270, 'John', 43, 11, 11, ' قال هذا وبعد ذلك قال لهم : لعازر حبيبنا قد نام . لكني أذهب لأوقظه '),
(20271, 'John', 43, 11, 12, ' فقال تلاميذه : يا سيد ، إن كان قد نام فهو يشفى '),
(20272, 'John', 43, 11, 13, ' وكان يسوع يقول عن موته ، وهم ظنوا أنه يقول عن رقاد النوم '),
(20273, 'John', 43, 11, 14, ' فقال لهم يسوع حينئذ علانية : لعازر مات '),
(20274, 'John', 43, 11, 15, ' وأنا أفرح لأجلكم إني لم أكن هناك ، لتؤمنوا . ولكن لنذهب إليه '),
(20275, 'John', 43, 11, 16, ' فقال توما ، الذي يقال له التوأم ، للتلاميذ رفقائه : لنذهب نحن أيضا لكي نموت معه '),
(20276, 'John', 43, 11, 17, ' فلما أتى يسوع وجد أنه قد صار له أربعة أيام في القبر '),
(20277, 'John', 43, 11, 18, ' وكانت بيت عنيا قريبة من أورشليم نحو خمس عشرة غلوة '),
(20278, 'John', 43, 11, 19, ' وكان كثيرون من اليهود قد جاءوا إلى مرثا ومريم ليعزوهما عن أخيهما '),
(20279, 'John', 43, 11, 20, ' فلما سمعت مرثا أن يسوع آت لاقته ، وأما مريم فاستمرت جالسة في البيت '),
(20280, 'John', 43, 11, 21, ' فقالت مرثا ليسوع : يا سيد ، لو كنت ههنا لم يمت أخي '),
(20281, 'John', 43, 11, 22, ' لكني الآن أيضا أعلم أن كل ما تطلب من الله يعطيك الله إياه '),
(20282, 'John', 43, 11, 23, ' قال لها يسوع : سيقوم أخوك '),
(20283, 'John', 43, 11, 24, ' قالت له مرثا : أنا أعلم أنه سيقوم في القيامة ، في اليوم الأخير '),
(20284, 'John', 43, 11, 25, ' قال لها يسوع : أنا هو القيامة والحياة . من آمن بي ولو مات فسيحيا '),
(20285, 'John', 43, 11, 26, ' وكل من كان حيا وآمن بي فلن يموت إلى الأبد . أتؤمنين بهذا '),
(20286, 'John', 43, 11, 27, ' قالت له : نعم يا سيد . أنا قد آمنت أنك أنت المسيح ابن الله ، الآتي إلى العالم '),
(20287, 'John', 43, 11, 28, ' ولما قالت هذا مضت ودعت مريم أختها سرا ، قائلة : المعلم قد حضر ، وهو يدعوك '),
(20288, 'John', 43, 11, 29, ' أما تلك فلما سمعت قامت سريعا وجاءت إليه '),
(20289, 'John', 43, 11, 30, ' ولم يكن يسوع قد جاء إلى القرية ، بل كان في المكان الذي لاقته فيه مرثا '),
(20290, 'John', 43, 11, 31, ' ثم إن اليهود الذين كانوا معها في البيت يعزونها ، لما رأوا مريم قامت عاجلا وخرجت ، تبعوها قائلين : إنها تذهب إلى القبر لتبكي هناك '),
(20291, 'John', 43, 11, 32, ' فمريم لما أتت إلى حيث كان يسوع ورأته ، خرت عند رجليه قائلة له : يا سيد ، لو كنت ههنا لم يمت أخي '),
(20292, 'John', 43, 11, 33, ' فلما رآها يسوع تبكي ، واليهود الذين جاءوا معها يبكون ، انزعج بالروح واضطرب '),
(20293, 'John', 43, 11, 34, ' وقال : أين وضعتموه ؟ قالوا له : يا سيد ، تعال وانظر '),
(20294, 'John', 43, 11, 35, ' بكى يسوع '),
(20295, 'John', 43, 11, 36, ' فقال اليهود : انظروا كيف كان يحبه '),
(20296, 'John', 43, 11, 37, ' وقال بعض منهم : ألم يقدر هذا الذي فتح عيني الأعمى أن يجعل هذا أيضا لا يموت '),
(20297, 'John', 43, 11, 38, ' فانزعج يسوع أيضا في نفسه وجاء إلى القبر ، وكان مغارة وقد وضع عليه حجر '),
(20298, 'John', 43, 11, 39, ' قال يسوع : ارفعوا الحجر . قالت له مرثا ، أخت الميت : يا سيد ، قد أنتن لأن له أربعة أيام '),
(20299, 'John', 43, 11, 40, ' قال لها يسوع : ألم أقل لك : إن آمنت ترين مجد الله '),
(20300, 'John', 43, 11, 41, ' فرفعوا الحجر حيث كان الميت موضوعا ، ورفع يسوع عينيه إلى فوق ، وقال : أيها الآب ، أشكرك لأنك سمعت لي '),
(20301, 'John', 43, 11, 42, ' وأنا علمت أنك في كل حين تسمع لي . ولكن لأجل هذا الجمع الواقف قلت ، ليؤمنوا أنك أرسلتني '),
(20302, 'John', 43, 11, 43, ' ولما قال هذا صرخ بصوت عظيم : لعازر ، هلم خارجا '),
(20303, 'John', 43, 11, 44, ' فخرج الميت ويداه ورجلاه مربوطات بأقمطة ، ووجهه ملفوف بمنديل . فقال لهم يسوع : حلوه ودعوه يذهب '),
(20304, 'John', 43, 11, 45, ' فكثيرون من اليهود الذين جاءوا إلى مريم ، ونظروا ما فعل يسوع ، آمنوا به '),
(20305, 'John', 43, 11, 46, ' وأما قوم منهم فمضوا إلى الفريسيين وقالوا لهم عما فعل يسوع '),
(20306, 'John', 43, 11, 47, ' فجمع رؤساء الكهنة والفريسيون مجمعا وقالوا : ماذا نصنع ؟ فإن هذا الإنسان يعمل آيات كثيرة '),
(20307, 'John', 43, 11, 48, ' إن تركناه هكذا يؤمن الجميع به ، فيأتي الرومانيون ويأخذون موضعنا وأمتنا '),
(20308, 'John', 43, 11, 49, ' فقال لهم واحد منهم ، وهو قيافا ، كان رئيسا للكهنة في تلك السنة : أنتم لستم تعرفون شيئا '),
(20309, 'John', 43, 11, 50, ' ولا تفكرون أنه خير لنا أن يموت إنسان واحد عن الشعب ولا تهلك الأمة كلها '),
(20310, 'John', 43, 11, 51, ' ولم يقل هذا من نفسه ، بل إذ كان رئيسا للكهنة في تلك السنة ، تنبأ أن يسوع مزمع أن يموت عن الأمة '),
(20311, 'John', 43, 11, 52, ' وليس عن الأمة فقط ، بل ليجمع أبناء الله المتفرقين إلى واحد '),
(20312, 'John', 43, 11, 53, ' فمن ذلك اليوم تشاوروا ليقتلوه '),
(20313, 'John', 43, 11, 54, ' فلم يكن يسوع أيضا يمشي بين اليهود علانية ، بل مضى من هناك إلى الكورة القريبة من البرية ، إلى مدينة يقال لها أفرايم ، ومكث هناك مع تلاميذه '),
(20314, 'John', 43, 11, 55, ' وكان فصح اليهود قريبا . فصعد كثيرون من الكور إلى أورشليم قبل الفصح ليطهروا أنفسهم '),
(20315, 'John', 43, 11, 56, ' فكانوا يطلبون يسوع ويقولون فيما بينهم ، وهم واقفون في الهيكل : ماذا تظنون ؟ هل هو لا يأتي إلى العيد '),
(20316, 'John', 43, 11, 57, ' وكان أيضا رؤساء الكهنة والفريسيون قد أصدروا أمرا أنه إن عرف أحد أين هو فليدل عليه ، لكي يمسكوه '),
(20317, 'John', 43, 12, 1, ' ثم قبل الفصح بستة أيام أتى يسوع إلى بيت عنيا ، حيث كان لعازر الميت الذي أقامه من الأموات '),
(20318, 'John', 43, 12, 2, ' فصنعوا له هناك عشاء . وكانت مرثا تخدم ، وأما لعازر فكان أحد المتكئين معه '),
(20319, 'John', 43, 12, 3, ' فأخذت مريم منا من طيب ناردين خالص كثير الثمن ، ودهنت قدمي يسوع ، ومسحت قدميه بشعرها ، فامتلأ البيت من رائحة الطيب '),
(20320, 'John', 43, 12, 4, ' فقال واحد من تلاميذه ، وهو يهوذا سمعان الإسخريوطي ، المزمع أن يسلمه '),
(20321, 'John', 43, 12, 5, ' لماذا لم يبع هذا الطيب بثلاثمئة دينار ويعط للفقراء '),
(20322, 'John', 43, 12, 6, ' قال هذا ليس لأنه كان يبالي بالفقراء ، بل لأنه كان سارقا ، وكان الصندوق عنده ، وكان يحمل ما يلقى فيه '),
(20323, 'John', 43, 12, 7, ' فقال يسوع : اتركوها إنها ليوم تكفيني قد حفظته '),
(20324, 'John', 43, 12, 8, ' لأن الفقراء معكم في كل حين ، وأما أنا فلست معكم في كل حين '),
(20325, 'John', 43, 12, 9, ' فعلم جمع كثير من اليهود أنه هناك ، فجاءوا ليس لأجل يسوع فقط ، بل لينظروا أيضا لعازر الذي أقامه من الأموات '),
(20326, 'John', 43, 12, 10, ' فتشاور رؤساء الكهنة ليقتلوا لعازر أيضا '),
(20327, 'John', 43, 12, 11, ' لأن كثيرين من اليهود كانوا بسببه يذهبون ويؤمنون بيسوع '),
(20328, 'John', 43, 12, 12, ' وفي الغد سمع الجمع الكثير الذي جاء إلى العيد أن يسوع آت إلى أورشليم '),
(20329, 'John', 43, 12, 13, ' فأخذوا سعوف النخل وخرجوا للقائه ، وكانوا يصرخون : أوصنا مبارك الآتي باسم الرب ملك إسرائيل '),
(20330, 'John', 43, 12, 14, ' ووجد يسوع جحشا فجلس عليه كما هو مكتوب '),
(20331, 'John', 43, 12, 15, ' لا تخافي يا ابنة صهيون . هوذا ملكك يأتي جالسا على جحش أتان '),
(20332, 'John', 43, 12, 16, ' وهذه الأمور لم يفهمها تلاميذه أولا ، ولكن لما تمجد يسوع ، حينئذ تذكروا أن هذه كانت مكتوبة عنه ، وأنهم صنعوا هذه له '),
(20333, 'John', 43, 12, 17, ' وكان الجمع الذي معه يشهد أنه دعا لعازر من القبر وأقامه من الأموات '),
(20334, 'John', 43, 12, 18, ' لهذا أيضا لاقاه الجمع ، لأنهم سمعوا أنه كان قد صنع هذه الآية '),
(20335, 'John', 43, 12, 19, ' فقال الفريسيون بعضهم لبعض : انظروا إنكم لا تنفعون شيئا هوذا العالم قد ذهب وراءه '),
(20336, 'John', 43, 12, 20, ' وكان أناس يونانيون من الذين صعدوا ليسجدوا في العيد '),
(20337, 'John', 43, 12, 21, ' فتقدم هؤلاء إلى فيلبس الذي من بيت صيدا الجليل ، وسألوه قائلين : يا سيد ، نريد أن نرى يسوع '),
(20338, 'John', 43, 12, 22, ' فأتى فيلبس وقال لأندراوس ، ثم قال أندراوس وفيلبس ليسوع '),
(20339, 'John', 43, 12, 23, ' وأما يسوع فأجابهما قائلا : قد أتت الساعة ليتمجد ابن الإنسان '),
(20340, 'John', 43, 12, 24, ' الحق الحق أقول لكم : إن لم تقع حبة الحنطة في الأرض وتمت فهي تبقى وحدها . ولكن إن ماتت تأتي بثمر كثير '),
(20341, 'John', 43, 12, 25, ' من يحب نفسه يهلكها ، ومن يبغض نفسه في هذا العالم يحفظها إلى حياة أبدية '),
(20342, 'John', 43, 12, 26, ' إن كان أحد يخدمني فليتبعني ، وحيث أكون أنا هناك أيضا يكون خادمي . وإن كان أحد يخدمني يكرمه الآب '),
(20343, 'John', 43, 12, 27, ' الآن نفسي قد اضطربت . وماذا أقول : أيها الآب نجني من هذه الساعة ؟ ولكن لأجل هذا أتيت إلى هذه الساعة '),
(20344, 'John', 43, 12, 28, ' أيها الآب مجد اسمك . فجاء صوت من السماء : مجدت ، وأمجد أيضا '),
(20345, 'John', 43, 12, 29, ' فالجمع الذي كان واقفا وسمع ، قال : قد حدث رعد . وآخرون قالوا : قد كلمه ملاك '),
(20346, 'John', 43, 12, 30, ' أجاب يسوع وقال : ليس من أجلي صار هذا الصوت ، بل من أجلكم '),
(20347, 'John', 43, 12, 31, ' الآن دينونة هذا العالم . الآن يطرح رئيس هذا العالم خارجا '),
(20348, 'John', 43, 12, 32, ' وأنا إن ارتفعت عن الأرض أجذب إلي الجميع '),
(20349, 'John', 43, 12, 33, ' قال هذا مشيرا إلى أية ميتة كان مزمعا أن يموت '),
(20350, 'John', 43, 12, 34, ' فأجابه الجمع : نحن سمعنا من الناموس أن المسيح يبقى إلى الأبد ، فكيف تقول أنت إنه ينبغي أن يرتفع ابن الإنسان ؟ من هو هذا ابن الإنسان '),
(20351, 'John', 43, 12, 35, ' فقال لهم يسوع : النور معكم زمانا قليلا بعد ، فسيروا ما دام لكم النور لئلا يدرككم الظلام . والذي يسير في الظلام لا يعلم إلى أين يذهب '),
(20352, 'John', 43, 12, 36, ' ما دام لكم النور آمنوا بالنور لتصيروا أبناء النور . تكلم يسوع بهذا ثم مضى واختفى عنهم '),
(20353, 'John', 43, 12, 37, ' ومع أنه كان قد صنع أمامهم آيات هذا عددها ، لم يؤمنوا به '),
(20354, 'John', 43, 12, 38, ' ليتم قول إشعياء النبي الذي قاله : يا رب ، من صدق خبرنا ؟ ولمن استعلنت ذراع الرب '),
(20355, 'John', 43, 12, 39, ' لهذا لم يقدروا أن يؤمنوا . لأن إشعياء قال أيضا '),
(20356, 'John', 43, 12, 40, ' قد أعمى عيونهم ، وأغلظ قلوبهم ، لئلا يبصروا بعيونهم ، ويشعروا بقلوبهم ، ويرجعوا فأشفيهم '),
(20357, 'John', 43, 12, 41, ' قال إشعياء هذا حين رأى مجده وتكلم عنه '),
(20358, 'John', 43, 12, 42, ' ولكن مع ذلك آمن به كثيرون من الرؤساء أيضا ، غير أنهم لسبب الفريسيين لم يعترفوا به ، لئلا يصيروا خارج المجمع '),
(20359, 'John', 43, 12, 43, ' لأنهم أحبوا مجد الناس أكثر من مجد الله '),
(20360, 'John', 43, 12, 44, ' فنادى يسوع وقال : الذي يؤمن بي ، ليس يؤمن بي بل بالذي أرسلني '),
(20361, 'John', 43, 12, 45, ' والذي يراني يرى الذي أرسلني '),
(20362, 'John', 43, 12, 46, ' أنا قد جئت نورا إلى العالم ، حتى كل من يؤمن بي لا يمكث في الظلمة '),
(20363, 'John', 43, 12, 47, ' وإن سمع أحد كلامي ولم يؤمن فأنا لا أدينه ، لأني لم آت لأدين العالم بل لأخلص العالم '),
(20364, 'John', 43, 12, 48, ' من رذلني ولم يقبل كلامي فله من يدينه . الكلام الذي تكلمت به هو يدينه في اليوم الأخير '),
(20365, 'John', 43, 12, 49, ' لأني لم أتكلم من نفسي ، لكن الآب الذي أرسلني هو أعطاني وصية : ماذا أقول وبماذا أتكلم '),
(20366, 'John', 43, 12, 50, ' وأنا أعلم أن وصيته هي حياة أبدية . فما أتكلم أنا به ، فكما قال لي الآب هكذا أتكلم '),
(20367, 'John', 43, 13, 1, ' أما يسوع قبل عيد الفصح ، وهو عالم أن ساعته قد جاءت لينتقل من هذا العالم إلى الآب ، إذ كان قد أحب خاصته الذين في العالم ، أحبهم إلى المنتهى '),
(20368, 'John', 43, 13, 2, ' فحين كان العشاء ، وقد ألقى الشيطان في قلب يهوذا سمعان الإسخريوطي أن يسلمه '),
(20369, 'John', 43, 13, 3, ' يسوع وهو عالم أن الآب قد دفع كل شيء إلى يديه ، وأنه من عند الله خرج ، وإلى الله يمضي '),
(20370, 'John', 43, 13, 4, ' قام عن العشاء ، وخلع ثيابه ، وأخذ منشفة واتزر بها '),
(20371, 'John', 43, 13, 5, ' ثم صب ماء في مغسل ، وابتدأ يغسل أرجل التلاميذ ويمسحها بالمنشفة التي كان متزرا بها '),
(20372, 'John', 43, 13, 6, ' فجاء إلى سمعان بطرس . فقال له ذاك : يا سيد ، أنت تغسل رجلي '),
(20373, 'John', 43, 13, 7, ' أجاب يسوع وقال له : لست تعلم أنت الآن ما أنا أصنع ، ولكنك ستفهم فيما بعد '),
(20374, 'John', 43, 13, 8, ' قال له بطرس : لن تغسل رجلي أبدا أجابه يسوع : إن كنت لا أغسلك فليس لك معي نصيب '),
(20375, 'John', 43, 13, 9, ' قال له سمعان بطرس : يا سيد ، ليس رجلي فقط بل أيضا يدي ورأسي '),
(20376, 'John', 43, 13, 10, ' قال له يسوع : الذي قد اغتسل ليس له حاجة إلا إلى غسل رجليه ، بل هو طاهر كله . وأنتم طاهرون ولكن ليس كلكم '),
(20377, 'John', 43, 13, 11, ' لأنه عرف مسلمه ، لذلك قال : لستم كلكم طاهرين '),
(20378, 'John', 43, 13, 12, ' فلما كان قد غسل أرجلهم وأخذ ثيابه واتكأ أيضا ، قال لهم : أتفهمون ما قد صنعت بكم '),
(20379, 'John', 43, 13, 13, ' أنتم تدعونني معلما وسيدا ، وحسنا تقولون ، لأني أنا كذلك '),
(20380, 'John', 43, 13, 14, ' فإن كنت وأنا السيد والمعلم قد غسلت أرجلكم ، فأنتم يجب عليكم أن يغسل بعضكم أرجل بعض '),
(20381, 'John', 43, 13, 15, ' لأني أعطيتكم مثالا ، حتى كما صنعت أنا بكم تصنعون أنتم أيضا '),
(20382, 'John', 43, 13, 16, ' الحق الحق أقول لكم : إنه ليس عبد أعظم من سيده ، ولا رسول أعظم من مرسله '),
(20383, 'John', 43, 13, 17, ' إن علمتم هذا فطوباكم إن عملتموه '),
(20384, 'John', 43, 13, 18, ' لست أقول عن جميعكم . أنا أعلم الذين اخترتهم . لكن ليتم الكتاب : الذي يأكل معي الخبز رفع علي عقبه '),
(20385, 'John', 43, 13, 19, ' أقول لكم الآن قبل أن يكون ، حتى متى كان تؤمنون أني أنا هو '),
(20386, 'John', 43, 13, 20, ' الحق الحق أقول لكم : الذي يقبل من أرسله يقبلني ، والذي يقبلني يقبل الذي أرسلني '),
(20387, 'John', 43, 13, 21, ' لما قال يسوع هذا اضطرب بالروح ، وشهد وقال : الحق الحق أقول لكم : إن واحدا منكم سيسلمني '),
(20388, 'John', 43, 13, 22, ' فكان التلاميذ ينظرون بعضهم إلى بعض وهم محتارون في من قال عنه '),
(20389, 'John', 43, 13, 23, ' وكان متكئا في حضن يسوع واحد من تلاميذه ، كان يسوع يحبه '),
(20390, 'John', 43, 13, 24, ' فأومأ إليه سمعان بطرس أن يسأل من عسى أن يكون الذي قال عنه '),
(20391, 'John', 43, 13, 25, ' فاتكأ ذاك على صدر يسوع وقال له : يا سيد ، من هو '),
(20392, 'John', 43, 13, 26, ' أجاب يسوع : هو ذاك الذي أغمس أنا اللقمة وأعطيه . فغمس اللقمة وأعطاها ليهوذا سمعان الإسخريوطي '),
(20393, 'John', 43, 13, 27, ' فبعد اللقمة دخله الشيطان . فقال له يسوع : ما أنت تعمله فاعمله بأكثر سرعة '),
(20394, 'John', 43, 13, 28, ' وأما هذا فلم يفهم أحد من المتكئين لماذا كلمه به '),
(20395, 'John', 43, 13, 29, ' لأن قوما ، إذ كان الصندوق مع يهوذا ، ظنوا أن يسوع قال له : اشتر ما نحتاج إليه للعيد ، أو أن يعطي شيئا للفقراء '),
(20396, 'John', 43, 13, 30, ' فذاك لما أخذ اللقمة خرج للوقت . وكان ليلا '),
(20397, 'John', 43, 13, 31, ' فلما خرج قال يسوع : الآن تمجد ابن الإنسان وتمجد الله فيه '),
(20398, 'John', 43, 13, 32, ' إن كان الله قد تمجد فيه ، فإن الله سيمجده في ذاته ، ويمجده سريعا '),
(20399, 'John', 43, 13, 33, ' يا أولادي ، أنا معكم زمانا قليلا بعد . ستطلبونني ، وكما قلت لليهود : حيث أذهب أنا لا تقدرون أنتم أن تأتوا ، أقول لكم أنتم الآن '),
(20400, 'John', 43, 13, 34, ' وصية جديدة أنا أعطيكم : أن تحبوا بعضكم بعضا . كما أحببتكم أنا تحبون أنتم أيضا بعضكم بعضا '),
(20401, 'John', 43, 13, 35, ' بهذا يعرف الجميع أنكم تلاميذي : إن كان لكم حب بعضا لبعض '),
(20402, 'John', 43, 13, 36, ' قال له سمعان بطرس : يا سيد ، إلى أين تذهب ؟ أجابه يسوع : حيث أذهب لا تقدر الآن أن تتبعني ، ولكنك ستتبعني أخيرا '),
(20403, 'John', 43, 13, 37, ' قال له بطرس : يا سيد ، لماذا لا أقدر أن أتبعك الآن ؟ إني أضع نفسي عنك '),
(20404, 'John', 43, 13, 38, ' أجابه يسوع : أتضع نفسك عني ؟ الحق الحق أقول لك : لا يصيح الديك حتى تنكرني ثلاث مرات '),
(20405, 'John', 43, 14, 1, ' لا تضطرب قلوبكم . أنتم تؤمنون بالله فآمنوا بي '),
(20406, 'John', 43, 14, 2, ' في بيت أبي منازل كثيرة ، وإلا فإني كنت قد قلت لكم . أنا أمضي لأعد لكم مكانا '),
(20407, 'John', 43, 14, 3, ' وإن مضيت وأعددت لكم مكانا آتي أيضا وآخذكم إلي ، حتى حيث أكون أنا تكونون أنتم أيضا '),
(20408, 'John', 43, 14, 4, ' وتعلمون حيث أنا أذهب وتعلمون الطريق '),
(20409, 'John', 43, 14, 5, ' قال له توما : يا سيد ، لسنا نعلم أين تذهب ، فكيف نقدر أن نعرف الطريق '),
(20410, 'John', 43, 14, 6, ' قال له يسوع : أنا هو الطريق والحق والحياة . ليس أحد يأتي إلى الآب إلا بي '),
(20411, 'John', 43, 14, 7, ' لو كنتم قد عرفتموني لعرفتم أبي أيضا . ومن الآن تعرفونه وقد رأيتموه '),
(20412, 'John', 43, 14, 8, ' قال له فيلبس : يا سيد ، أرنا الآب وكفانا '),
(20413, 'John', 43, 14, 9, ' قال له يسوع : أنا معكم زمانا هذه مدته ولم تعرفني يا فيلبس الذي رآني فقد رأى الآب ، فكيف تقول أنت : أرنا الآب '),
(20414, 'John', 43, 14, 10, ' ألست تؤمن أني أنا في الآب والآب في ؟ الكلام الذي أكلمكم به لست أتكلم به من نفسي ، لكن الآب الحال في هو يعمل الأعمال '),
(20415, 'John', 43, 14, 11, ' صدقوني أني في الآب والآب في ، وإلا فصدقوني لسبب الأعمال نفسها '),
(20416, 'John', 43, 14, 12, ' الحق الحق أقول لكم : من يؤمن بي فالأعمال التي أنا أعملها يعملها هو أيضا ، ويعمل أعظم منها ، لأني ماض إلى أبي '),
(20417, 'John', 43, 14, 13, ' ومهما سألتم باسمي فذلك أفعله ليتمجد الآب بالابن '),
(20418, 'John', 43, 14, 14, ' إن سألتم شيئا باسمي فإني أفعله '),
(20419, 'John', 43, 14, 15, ' إن كنتم تحبونني فاحفظوا وصاياي '),
(20420, 'John', 43, 14, 16, ' وأنا أطلب من الآب فيعطيكم معزيا آخر ليمكث معكم إلى الأبد '),
(20421, 'John', 43, 14, 17, ' روح الحق الذي لا يستطيع العالم أن يقبله ، لأنه لا يراه ولا يعرفه ، وأما أنتم فتعرفونه لأنه ماكث معكم ويكون فيكم '),
(20422, 'John', 43, 14, 18, ' لا أترككم يتامى . إني آتي إليكم '),
(20423, 'John', 43, 14, 19, ' بعد قليل لا يراني العالم أيضا ، وأما أنتم فترونني . إني أنا حي فأنتم ستحيون '),
(20424, 'John', 43, 14, 20, ' في ذلك اليوم تعلمون أني أنا في أبي ، وأنتم في ، وأنا فيكم '),
(20425, 'John', 43, 14, 21, ' الذي عنده وصاياي ويحفظها فهو الذي يحبني ، والذي يحبني يحبه أبي ، وأنا أحبه ، وأظهر له ذاتي '),
(20426, 'John', 43, 14, 22, ' قال له يهوذا ليس الإسخريوطي : يا سيد ، ماذا حدث حتى إنك مزمع أن تظهر ذاتك لنا وليس للعالم '),
(20427, 'John', 43, 14, 23, ' أجاب يسوع وقال له : إن أحبني أحد يحفظ كلامي ، ويحبه أبي ، وإليه نأتي ، وعنده نصنع منزلا '),
(20428, 'John', 43, 14, 24, ' الذي لا يحبني لا يحفظ كلامي . والكلام الذي تسمعونه ليس لي بل للآب الذي أرسلني '),
(20429, 'John', 43, 14, 25, ' بهذا كلمتكم وأنا عندكم '),
(20430, 'John', 43, 14, 26, ' وأما المعزي ، الروح القدس ، الذي سيرسله الآب باسمي ، فهو يعلمكم كل شيء ، ويذكركم بكل ما قلته لكم '),
(20431, 'John', 43, 14, 27, ' سلاما أترك لكم . سلامي أعطيكم . ليس كما يعطي العالم أعطيكم أنا . لا تضطرب قلوبكم ولا ترهب '),
(20432, 'John', 43, 14, 28, ' سمعتم أني قلت لكم : أنا أذهب ثم آتي إليكم . لو كنتم تحبونني لكنتم تفرحون لأني قلت أمضي إلى الآب ، لأن أبي أعظم مني '),
(20433, 'John', 43, 14, 29, ' وقلت لكم الآن قبل أن يكون ، حتى متى كان تؤمنون '),
(20434, 'John', 43, 14, 30, ' لا أتكلم أيضا معكم كثيرا ، لأن رئيس هذا العالم يأتي وليس له في شيء '),
(20435, 'John', 43, 14, 31, ' ولكن ليفهم العالم أني أحب الآب ، وكما أوصاني الآب هكذا أفعل . قوموا ننطلق من ههنا '),
(20436, 'John', 43, 15, 1, ' أنا الكرمة الحقيقية وأبي الكرام '),
(20437, 'John', 43, 15, 2, ' كل غصن في لا يأتي بثمر ينزعه ، وكل ما يأتي بثمر ينقيه ليأتي بثمر أكثر '),
(20438, 'John', 43, 15, 3, ' أنتم الآن أنقياء لسبب الكلام الذي كلمتكم به '),
(20439, 'John', 43, 15, 4, ' اثبتوا في وأنا فيكم . كما أن الغصن لا يقدر أن يأتي بثمر من ذاته إن لم يثبت في الكرمة ، كذلك أنتم أيضا إن لم تثبتوا في '),
(20440, 'John', 43, 15, 5, ' أنا الكرمة وأنتم الأغصان . الذي يثبت في وأنا فيه هذا يأتي بثمر كثير ، لأنكم بدوني لا تقدرون أن تفعلوا شيئا '),
(20441, 'John', 43, 15, 6, ' إن كان أحد لا يثبت في يطرح خارجا كالغصن ، فيجف ويجمعونه ويطرحونه في النار ، فيحترق '),
(20442, 'John', 43, 15, 7, ' إن ثبتم في وثبت كلامي فيكم تطلبون ما تريدون فيكون لكم '),
(20443, 'John', 43, 15, 8, ' بهذا يتمجد أبي : أن تأتوا بثمر كثير فتكونون تلاميذي '),
(20444, 'John', 43, 15, 9, ' كما أحبني الآب كذلك أحببتكم أنا . اثبتوا في محبتي '),
(20445, 'John', 43, 15, 10, ' إن حفظتم وصاياي تثبتون في محبتي ، كما أني أنا قد حفظت وصايا أبي وأثبت في محبته '),
(20446, 'John', 43, 15, 11, ' كلمتكم بهذا لكي يثبت فرحي فيكم ويكمل فرحكم '),
(20447, 'John', 43, 15, 12, ' هذه هي وصيتي أن تحبوا بعضكم بعضا كما أحببتكم '),
(20448, 'John', 43, 15, 13, ' ليس لأحد حب أعظم من هذا : أن يضع أحد نفسه لأجل أحبائه '),
(20449, 'John', 43, 15, 14, ' أنتم أحبائي إن فعلتم ما أوصيكم به '),
(20450, 'John', 43, 15, 15, ' لا أعود أسميكم عبيدا ، لأن العبد لا يعلم ما يعمل سيده ، لكني قد سميتكم أحباء لأني أعلمتكم بكل ما سمعته من أبي '),
(20451, 'John', 43, 15, 16, ' ليس أنتم اخترتموني بل أنا اخترتكم ، وأقمتكم لتذهبوا وتأتوا بثمر ، ويدوم ثمركم ، لكي يعطيكم الآب كل ما طلبتم باسمي '),
(20452, 'John', 43, 15, 17, ' بهذا أوصيكم حتى تحبوا بعضكم بعضا '),
(20453, 'John', 43, 15, 18, ' إن كان العالم يبغضكم فاعلموا أنه قد أبغضني قبلكم '),
(20454, 'John', 43, 15, 19, ' لو كنتم من العالم لكان العالم يحب خاصته . ولكن لأنكم لستم من العالم ، بل أنا اخترتكم من العالم ، لذلك يبغضكم العالم '),
(20455, 'John', 43, 15, 20, ' اذكروا الكلام الذي قلته لكم : ليس عبد أعظم من سيده . إن كانوا قد اضطهدوني فسيضطهدونكم ، وإن كانوا قد حفظوا كلامي فسيحفظون كلامكم '),
(20456, 'John', 43, 15, 21, ' لكنهم إنما يفعلون بكم هذا كله من أجل اسمي ، لأنهم لا يعرفون الذي أرسلني '),
(20457, 'John', 43, 15, 22, ' لو لم أكن قد جئت وكلمتهم ، لم تكن لهم خطية ، وأما الآن فليس لهم عذر في خطيتهم '),
(20458, 'John', 43, 15, 23, ' الذي يبغضني يبغض أبي أيضا '),
(20459, 'John', 43, 15, 24, ' لو لم أكن قد عملت بينهم أعمالا لم يعملها أحد غيري ، لم تكن لهم خطية ، وأما الآن فقد رأوا وأبغضوني أنا وأبي '),
(20460, 'John', 43, 15, 25, ' لكن لكي تتم الكلمة المكتوبة في ناموسهم : إنهم أبغضوني بلا سبب '),
(20461, 'John', 43, 15, 26, ' ومتى جاء المعزي الذي سأرسله أنا إليكم من الآب ، روح الحق ، الذي من عند الآب ينبثق ، فهو يشهد لي '),
(20462, 'John', 43, 15, 27, ' وتشهدون أنتم أيضا لأنكم معي من الابتداء '),
(20463, 'John', 43, 16, 1, ' قد كلمتكم بهذا لكي لا تعثروا '),
(20464, 'John', 43, 16, 2, ' سيخرجونكم من المجامع ، بل تأتي ساعة فيها يظن كل من يقتلكم أنه يقدم خدمة لله '),
(20465, 'John', 43, 16, 3, ' وسيفعلون هذا بكم لأنهم لم يعرفوا الآب ولا عرفوني '),
(20466, 'John', 43, 16, 4, ' لكني قد كلمتكم بهذا حتى إذا جاءت الساعة تذكرون أني أنا قلته لكم . ولم أقل لكم من البداية لأني كنت معكم '),
(20467, 'John', 43, 16, 5, ' وأما الآن فأنا ماض إلى الذي أرسلني ، وليس أحد منكم يسألني : أين تمضي '),
(20468, 'John', 43, 16, 6, ' لكن لأني قلت لكم هذا قد ملأ الحزن قلوبكم '),
(20469, 'John', 43, 16, 7, ' لكني أقول لكم الحق : إنه خير لكم أن أنطلق ، لأنه إن لم أنطلق لا يأتيكم المعزي ، ولكن إن ذهبت أرسله إليكم '),
(20470, 'John', 43, 16, 8, ' ومتى جاء ذاك يبكت العالم على خطية وعلى بر وعلى دينونة '),
(20471, 'John', 43, 16, 9, ' أما على خطية فلأنهم لا يؤمنون بي '),
(20472, 'John', 43, 16, 10, ' وأما على بر فلأني ذاهب إلى أبي ولا ترونني أيضا '),
(20473, 'John', 43, 16, 11, ' وأما على دينونة فلأن رئيس هذا العالم قد دين '),
(20474, 'John', 43, 16, 12, ' إن لي أمورا كثيرة أيضا لأقول لكم ، ولكن لا تستطيعون أن تحتملوا الآن '),
(20475, 'John', 43, 16, 13, ' وأما متى جاء ذاك ، روح الحق ، فهو يرشدكم إلى جميع الحق ، لأنه لا يتكلم من نفسه ، بل كل ما يسمع يتكلم به ، ويخبركم بأمور آتية '),
(20476, 'John', 43, 16, 14, ' ذاك يمجدني ، لأنه يأخذ مما لي ويخبركم '),
(20477, 'John', 43, 16, 15, ' كل ما للآب هو لي . لهذا قلت إنه يأخذ مما لي ويخبركم '),
(20478, 'John', 43, 16, 16, ' بعد قليل لا تبصرونني ، ثم بعد قليل أيضا ترونني ، لأني ذاهب إلى الآب '),
(20479, 'John', 43, 16, 17, ' فقال قوم من تلاميذه ، بعضهم لبعض : ما هو هذا الذي يقوله لنا : بعد قليل لا تبصرونني ، ثم بعد قليل أيضا ترونني ، ولأني ذاهب إلى الآب '),
(20480, 'John', 43, 16, 18, ' فقالوا : ما هو هذا القليل الذي يقول عنه ؟ لسنا نعلم بماذا يتكلم '),
(20481, 'John', 43, 16, 19, ' فعلم يسوع أنهم كانوا يريدون أن يسألوه ، فقال لهم : أعن هذا تتساءلون فيما بينكم ، لأني قلت : بعد قليل لا تبصرونني ، ثم بعد قليل أيضا ترونني '),
(20482, 'John', 43, 16, 20, ' الحق الحق أقول لكم : إنكم ستبكون وتنوحون والعالم يفرح . أنتم ستحزنون ، ولكن حزنكم يتحول إلى فرح '),
(20483, 'John', 43, 16, 21, ' المرأة وهي تلد تحزن لأن ساعتها قد جاءت ، ولكن متى ولدت الطفل لا تعود تذكر الشدة لسبب الفرح ، لأنه قد ولد إنسان في العالم '),
(20484, 'John', 43, 16, 22, ' فأنتم كذلك ، عندكم الآن حزن . ولكني سأراكم أيضا فتفرح قلوبكم ، ولا ينزع أحد فرحكم منكم '),
(20485, 'John', 43, 16, 23, ' وفي ذلك اليوم لا تسألونني شيئا . الحق الحق أقول لكم : إن كل ما طلبتم من الآب باسمي يعطيكم '),
(20486, 'John', 43, 16, 24, ' إلى الآن لم تطلبوا شيئا باسمي . اطلبوا تأخذوا ، ليكون فرحكم كاملا '),
(20487, 'John', 43, 16, 25, ' قد كلمتكم بهذا بأمثال ، ولكن تأتي ساعة حين لا أكلمكم أيضا بأمثال ، بل أخبركم عن الآب علانية '),
(20488, 'John', 43, 16, 26, ' في ذلك اليوم تطلبون باسمي . ولست أقول لكم إني أنا أسأل الآب من أجلكم '),
(20489, 'John', 43, 16, 27, ' لأن الآب نفسه يحبكم ، لأنكم قد أحببتموني ، وآمنتم أني من عند الله خرجت '),
(20490, 'John', 43, 16, 28, ' خرجت من عند الآب ، وقد أتيت إلى العالم ، وأيضا أترك العالم وأذهب إلى الآب '),
(20491, 'John', 43, 16, 29, ' قال له تلاميذه : هوذا الآن تتكلم علانية ولست تقول مثلا واحدا '),
(20492, 'John', 43, 16, 30, ' الآن نعلم أنك عالم بكل شيء ، ولست تحتاج أن يسألك أحد . لهذا نؤمن أنك من الله خرجت '),
(20493, 'John', 43, 16, 31, ' أجابهم يسوع : ألآن تؤمنون '),
(20494, 'John', 43, 16, 32, ' هوذا تأتي ساعة ، وقد أتت الآن ، تتفرقون فيها كل واحد إلى خاصته ، وتتركونني وحدي . وأنا لست وحدي لأن الآب معي '),
(20495, 'John', 43, 16, 33, ' قد كلمتكم بهذا ليكون لكم في سلام . في العالم سيكون لكم ضيق ، ولكن ثقوا : أنا قد غلبت العالم '),
(20496, 'John', 43, 17, 1, ' تكلم يسوع بهذا ورفع عينيه نحو السماء وقال : أيها الآب ، قد أتت الساعة . مجد ابنك ليمجدك ابنك أيضا '),
(20497, 'John', 43, 17, 2, ' إذ أعطيته سلطانا على كل جسد ليعطي حياة أبدية لكل من أعطيته '),
(20498, 'John', 43, 17, 3, ' وهذه هي الحياة الأبدية : أن يعرفوك أنت الإله الحقيقي وحدك ويسوع المسيح الذي أرسلته '),
(20499, 'John', 43, 17, 4, ' أنا مجدتك على الأرض . العمل الذي أعطيتني لأعمل قد أكملته '),
(20500, 'John', 43, 17, 5, ' والآن مجدني أنت أيها الآب عند ذاتك بالمجد الذي كان لي عندك قبل كون العالم '),
(20501, 'John', 43, 17, 6, ' أنا أظهرت اسمك للناس الذين أعطيتني من العالم . كانوا لك وأعطيتهم لي ، وقد حفظوا كلامك '),
(20502, 'John', 43, 17, 7, ' والآن علموا أن كل ما أعطيتني هو من عندك '),
(20503, 'John', 43, 17, 8, ' لأن الكلام الذي أعطيتني قد أعطيتهم ، وهم قبلوا وعلموا يقينا أني خرجت من عندك ، وآمنوا أنك أنت أرسلتني '),
(20504, 'John', 43, 17, 9, ' من أجلهم أنا أسأل . لست أسأل من أجل العالم ، بل من أجل الذين أعطيتني لأنهم لك '),
(20505, 'John', 43, 17, 10, ' وكل ما هو لي فهو لك ، وما هو لك فهو لي ، وأنا ممجد فيهم '),
(20506, 'John', 43, 17, 11, ' ولست أنا بعد في العالم ، وأما هؤلاء فهم في العالم ، وأنا آتي إليك . أيها الآب القدوس ، احفظهم في اسمك الذين أعطيتني ، ليكونوا واحدا كما نحن '),
(20507, 'John', 43, 17, 12, ' حين كنت معهم في العالم كنت أحفظهم في اسمك . الذين أعطيتني حفظتهم ، ولم يهلك منهم أحد إلا ابن الهلاك ليتم الكتاب '),
(20508, 'John', 43, 17, 13, ' أما الآن فإني آتي إليك . وأتكلم بهذا في العالم ليكون لهم فرحي كاملا فيهم '),
(20509, 'John', 43, 17, 14, ' أنا قد أعطيتهم كلامك ، والعالم أبغضهم لأنهم ليسوا من العالم ، كما أني أنا لست من العالم '),
(20510, 'John', 43, 17, 15, ' لست أسأل أن تأخذهم من العالم بل أن تحفظهم من الشرير '),
(20511, 'John', 43, 17, 16, ' ليسوا من العالم كما أني أنا لست من العالم '),
(20512, 'John', 43, 17, 17, ' قدسهم في حقك . كلامك هو حق '),
(20513, 'John', 43, 17, 18, ' كما أرسلتني إلى العالم أرسلتهم أنا إلى العالم '),
(20514, 'John', 43, 17, 19, ' ولأجلهم أقدس أنا ذاتي ، ليكونوا هم أيضا مقدسين في الحق '),
(20515, 'John', 43, 17, 20, ' ولست أسأل من أجل هؤلاء فقط ، بل أيضا من أجل الذين يؤمنون بي بكلامهم '),
(20516, 'John', 43, 17, 21, ' ليكون الجميع واحدا ، كما أنك أنت أيها الآب في وأنا فيك ، ليكونوا هم أيضا واحدا فينا ، ليؤمن العالم أنك أرسلتني '),
(20517, 'John', 43, 17, 22, ' وأنا قد أعطيتهم المجد الذي أعطيتني ، ليكونوا واحدا كما أننا نحن واحد '),
(20518, 'John', 43, 17, 23, ' أنا فيهم وأنت في ليكونوا مكملين إلى واحد ، وليعلم العالم أنك أرسلتني ، وأحببتهم كما أحببتني '),
(20519, 'John', 43, 17, 24, ' أيها الآب أريد أن هؤلاء الذين أعطيتني يكونون معي حيث أكون أنا ، لينظروا مجدي الذي أعطيتني ، لأنك أحببتني قبل إنشاء العالم '),
(20520, 'John', 43, 17, 25, ' أيها الآب البار ، إن العالم لم يعرفك ، أما أنا فعرفتك ، وهؤلاء عرفوا أنك أنت أرسلتني '),
(20521, 'John', 43, 17, 26, ' وعرفتهم اسمك وسأعرفهم ، ليكون فيهم الحب الذي أحببتني به ، وأكون أنا فيهم '),
(20522, 'John', 43, 18, 1, ' قال يسوع هذا وخرج مع تلاميذه إلى عبر وادي قدرون ، حيث كان بستان دخله هو وتلاميذه '),
(20523, 'John', 43, 18, 2, ' وكان يهوذا مسلمه يعرف الموضع ، لأن يسوع اجتمع هناك كثيرا مع تلاميذه '),
(20524, 'John', 43, 18, 3, ' فأخذ يهوذا الجند وخداما من عند رؤساء الكهنة والفريسيين ، وجاء إلى هناك بمشاعل ومصابيح وسلاح '),
(20525, 'John', 43, 18, 4, ' فخرج يسوع وهو عالم بكل ما يأتي عليه ، وقال لهم : من تطلبون '),
(20526, 'John', 43, 18, 5, ' أجابوه : يسوع الناصري . قال لهم يسوع : أنا هو . وكان يهوذا مسلمه أيضا واقفا معهم '),
(20527, 'John', 43, 18, 6, ' فلما قال لهم : إني أنا هو ، رجعوا إلى الوراء وسقطوا على الأرض '),
(20528, 'John', 43, 18, 7, ' فسألهم أيضا : من تطلبون ؟ فقالوا : يسوع الناصري '),
(20529, 'John', 43, 18, 8, ' أجاب يسوع : قد قلت لكم : إني أنا هو . فإن كنتم تطلبونني فدعوا هؤلاء يذهبون '),
(20530, 'John', 43, 18, 9, ' ليتم القول الذي قاله : إن الذين أعطيتني لم أهلك منهم أحدا '),
(20531, 'John', 43, 18, 10, ' ثم إن سمعان بطرس كان معه سيف ، فاستله وضرب عبد رئيس الكهنة ، فقطع أذنه اليمنى . وكان اسم العبد ملخس '),
(20532, 'John', 43, 18, 11, ' فقال يسوع لبطرس : اجعل سيفك في الغمد الكأس التي أعطاني الآب ألا أشربها '),
(20533, 'John', 43, 18, 12, ' ثم إن الجند والقائد وخدام اليهود قبضوا على يسوع وأوثقوه '),
(20534, 'John', 43, 18, 13, ' ومضوا به إلى حنان أولا ، لأنه كان حما قيافا الذي كان رئيسا للكهنة في تلك السنة '),
(20535, 'John', 43, 18, 14, ' وكان قيافا هو الذي أشار على اليهود أنه خير أن يموت إنسان واحد عن الشعب '),
(20536, 'John', 43, 18, 15, ' وكان سمعان بطرس والتلميذ الآخر يتبعان يسوع ، وكان ذلك التلميذ معروفا عند رئيس الكهنة ، فدخل مع يسوع إلى دار رئيس الكهنة '),
(20537, 'John', 43, 18, 16, ' وأما بطرس فكان واقفا عند الباب خارجا . فخرج التلميذ الآخر الذي كان معروفا عند رئيس الكهنة ، وكلم البوابة فأدخل بطرس '),
(20538, 'John', 43, 18, 17, ' فقالت الجارية البوابة لبطرس : ألست أنت أيضا من تلاميذ هذا الإنسان ؟ قال ذاك : لست أنا '),
(20539, 'John', 43, 18, 18, ' وكان العبيد والخدام واقفين ، وهم قد أضرموا جمرا لأنه كان برد ، وكانوا يصطلون ، وكان بطرس واقفا معهم يصطلي '),
(20540, 'John', 43, 18, 19, ' فسأل رئيس الكهنة يسوع عن تلاميذه وعن تعليمه '),
(20541, 'John', 43, 18, 20, ' أجابه يسوع : أنا كلمت العالم علانية . أنا علمت كل حين في المجمع وفي الهيكل حيث يجتمع اليهود دائما . وفي الخفاء لم أتكلم بشيء '),
(20542, 'John', 43, 18, 21, ' لماذا تسألني أنا ؟ اسأل الذين قد سمعوا ماذا كلمتهم . هوذا هؤلاء يعرفون ماذا قلت أنا '),
(20543, 'John', 43, 18, 22, ' ولما قال هذا لطم يسوع واحد من الخدام كان واقفا ، قائلا : أهكذا تجاوب رئيس الكهنة '),
(20544, 'John', 43, 18, 23, ' أجابه يسوع : إن كنت قد تكلمت رديا فاشهد على الردي ، وإن حسنا فلماذا تضربني '),
(20545, 'John', 43, 18, 24, ' وكان حنان قد أرسله موثقا إلى قيافا رئيس الكهنة '),
(20546, 'John', 43, 18, 25, ' وسمعان بطرس كان واقفا يصطلي . فقالوا له : ألست أنت أيضا من تلاميذه ؟ فأنكر ذاك وقال : لست أنا '),
(20547, 'John', 43, 18, 26, ' قال واحد من عبيد رئيس الكهنة ، وهو نسيب الذي قطع بطرس أذنه : أما رأيتك أنا معه في البستان '),
(20548, 'John', 43, 18, 27, ' فأنكر بطرس أيضا . وللوقت صاح الديك '),
(20549, 'John', 43, 18, 28, ' ثم جاءوا بيسوع من عند قيافا إلى دار الولاية ، وكان صبح . ولم يدخلوا هم إلى دار الولاية لكي لا يتنجسوا ، فيأكلون الفصح '),
(20550, 'John', 43, 18, 29, ' فخرج بيلاطس إليهم وقال : أية شكاية تقدمون على هذا الإنسان '),
(20551, 'John', 43, 18, 30, ' أجابوا وقالوا له : لو لم يكن فاعل شر لما كنا قد سلمناه إليك '),
(20552, 'John', 43, 18, 31, ' فقال لهم بيلاطس : خذوه أنتم واحكموا عليه حسب ناموسكم . فقال له اليهود : لا يجوز لنا أن نقتل أحدا '),
(20553, 'John', 43, 18, 32, ' ليتم قول يسوع الذي قاله مشيرا إلى أية ميتة كان مزمعا أن يموت '),
(20554, 'John', 43, 18, 33, ' ثم دخل بيلاطس أيضا إلى دار الولاية ودعا يسوع ، وقال له : أنت ملك اليهود '),
(20555, 'John', 43, 18, 34, ' أجابه يسوع : أمن ذاتك تقول هذا ، أم آخرون قالوا لك عني '),
(20556, 'John', 43, 18, 35, ' أجابه بيلاطس : ألعلي أنا يهودي ؟ أمتك ورؤساء الكهنة أسلموك إلي . ماذا فعلت '),
(20557, 'John', 43, 18, 36, ' أجاب يسوع : مملكتي ليست من هذا العالم . لو كانت مملكتي من هذا العالم ، لكان خدامي يجاهدون لكي لا أسلم إلى اليهود . ولكن الآن ليست مملكتي من هنا '),
(20558, 'John', 43, 18, 37, ' فقال له بيلاطس : أفأنت إذا ملك ؟ أجاب يسوع : أنت تقول : إني ملك . لهذا قد ولدت أنا ، ولهذا قد أتيت إلى العالم لأشهد للحق . كل من هو من الحق يسمع صوتي '),
(20559, 'John', 43, 18, 38, ' قال له بيلاطس : ما هو الحق ؟  . ولما قال هذا خرج أيضا إلى اليهود وقال لهم : أنا لست أجد فيه علة واحدة '),
(20560, 'John', 43, 18, 39, ' ولكم عادة أن أطلق لكم واحدا في الفصح . أفتريدون أن أطلق لكم ملك اليهود '),
(20561, 'John', 43, 18, 40, ' فصرخوا أيضا جميعهم قائلين : ليس هذا بل باراباس . وكان باراباس لصا '),
(20562, 'John', 43, 19, 1, ' فحينئذ أخذ بيلاطس يسوع وجلده '),
(20563, 'John', 43, 19, 2, ' وضفر العسكر إكليلا من شوك ووضعوه على رأسه ، وألبسوه ثوب أرجوان '),
(20564, 'John', 43, 19, 3, ' وكانوا يقولون : السلام يا ملك اليهود . وكانوا يلطمونه '),
(20565, 'John', 43, 19, 4, ' فخرج بيلاطس أيضا خارجا وقال لهم : ها أنا أخرجه إليكم لتعلموا أني لست أجد فيه علة واحدة '),
(20566, 'John', 43, 19, 5, ' فخرج يسوع خارجا وهو حامل إكليل الشوك وثوب الأرجوان . فقال لهم بيلاطس : هوذا الإنسان '),
(20567, 'John', 43, 19, 6, ' فلما رآه رؤساء الكهنة والخدام صرخوا قائلين : اصلبه اصلبه . قال لهم بيلاطس : خذوه أنتم واصلبوه ، لأني لست أجد فيه علة '),
(20568, 'John', 43, 19, 7, ' أجابه اليهود : لنا ناموس ، وحسب ناموسنا يجب أن يموت ، لأنه جعل نفسه ابن الله '),
(20569, 'John', 43, 19, 8, ' فلما سمع بيلاطس هذا القول ازداد خوفا '),
(20570, 'John', 43, 19, 9, ' فدخل أيضا إلى دار الولاية وقال ليسوع : من أين أنت ؟  . وأما يسوع فلم يعطه جوابا '),
(20571, 'John', 43, 19, 10, ' فقال له بيلاطس : أما تكلمني ؟ ألست تعلم أن لي سلطانا أن أصلبك وسلطانا أن أطلقك '),
(20572, 'John', 43, 19, 11, ' أجاب يسوع : لم يكن لك علي سلطان البتة ، لو لم تكن قد أعطيت من فوق . لذلك الذي أسلمني إليك له خطية أعظم '),
(20573, 'John', 43, 19, 12, ' من هذا الوقت كان بيلاطس يطلب أن يطلقه ، ولكن اليهود كانوا يصرخون قائلين : إن أطلقت هذا فلست محبا لقيصر . كل من يجعل نفسه ملكا يقاوم قيصر '),
(20574, 'John', 43, 19, 13, ' فلما سمع بيلاطس هذا القول أخرج يسوع ، وجلس على كرسي الولاية في موضع يقال له البلاط وبالعبرانية جباثا '),
(20575, 'John', 43, 19, 14, ' وكان استعداد الفصح ، ونحو الساعة السادسة . فقال لليهود : هوذا ملككم '),
(20576, 'John', 43, 19, 15, ' فصرخوا : خذه خذه اصلبه قال لهم بيلاطس : أأصلب ملككم ؟ أجاب رؤساء الكهنة : ليس لنا ملك إلا قيصر '),
(20577, 'John', 43, 19, 16, ' فحينئذ أسلمه إليهم ليصلب فأخذوا يسوع ومضوا به '),
(20578, 'John', 43, 19, 17, ' فخرج وهو حامل صليبه إلى الموضع الذي يقال له موضع الجمجمة ويقال له بالعبرانية جلجثة '),
(20579, 'John', 43, 19, 18, ' حيث صلبوه ، وصلبوا اثنين آخرين معه من هنا ومن هنا ، ويسوع في الوسط '),
(20580, 'John', 43, 19, 19, ' وكتب بيلاطس عنوانا ووضعه على الصليب . وكان مكتوبا : يسوع الناصري ملك اليهود '),
(20581, 'John', 43, 19, 20, ' فقرأ هذا العنوان كثيرون من اليهود ، لأن المكان الذي صلب فيه يسوع كان قريبا من المدينة . وكان مكتوبا بالعبرانية واليونانية واللاتينية '),
(20582, 'John', 43, 19, 21, ' فقال رؤساء كهنة اليهود لبيلاطس : لا تكتب : ملك اليهود ، بل : إن ذاك قال : أنا ملك اليهود '),
(20583, 'John', 43, 19, 22, ' أجاب بيلاطس : ما كتبت قد كتبت '),
(20584, 'John', 43, 19, 23, ' ثم إن العسكر لما كانوا قد صلبوا يسوع ، أخذوا ثيابه وجعلوها أربعة أقسام ، لكل عسكري قسما . وأخذوا القميص أيضا . وكان القميص بغير خياطة ، منسوجا كله من فوق '),
(20585, 'John', 43, 19, 24, ' فقال بعضهم لبعض : لا نشقه ، بل نقترع عليه لمن يكون . ليتم الكتاب القائل : اقتسموا ثيابي بينهم ، وعلى لباسي ألقوا قرعة . هذا فعله العسكر '),
(20586, 'John', 43, 19, 25, ' وكانت واقفات عند صليب يسوع ، أمه ، وأخت أمه ، مريم زوجة كلوبا ، ومريم المجدلية '),
(20587, 'John', 43, 19, 26, ' فلما رأى يسوع أمه ، والتلميذ الذي كان يحبه واقفا ، قال لأمه : يا امرأة ، هوذا ابنك '),
(20588, 'John', 43, 19, 27, ' ثم قال للتلميذ : هوذا أمك . ومن تلك الساعة أخذها التلميذ إلى خاصته '),
(20589, 'John', 43, 19, 28, ' بعد هذا رأى يسوع أن كل شيء قد كمل ، فلكي يتم الكتاب قال : أنا عطشان '),
(20590, 'John', 43, 19, 29, ' وكان إناء موضوعا مملوا خلا ، فملأوا إسفنجة من الخل ، ووضعوها على زوفا وقدموها إلى فمه '),
(20591, 'John', 43, 19, 30, ' فلما أخذ يسوع الخل قال : قد أكمل . ونكس رأسه وأسلم الروح '),
(20592, 'John', 43, 19, 31, ' ثم إذ كان استعداد ، فلكي لا تبقى الأجساد على الصليب في السبت ، لأن يوم ذلك السبت كان عظيما ، سأل اليهود بيلاطس أن تكسر سيقانهم ويرفعوا '),
(20593, 'John', 43, 19, 32, ' فأتى العسكر وكسروا ساقي الأول والآخر المصلوب معه '),
(20594, 'John', 43, 19, 33, ' وأما يسوع فلما جاءوا إليه لم يكسروا ساقيه ، لأنهم رأوه قد مات '),
(20595, 'John', 43, 19, 34, ' لكن واحدا من العسكر طعن جنبه بحربة ، وللوقت خرج دم وماء '),
(20596, 'John', 43, 19, 35, ' والذي عاين شهد ، وشهادته حق ، وهو يعلم أنه يقول الحق لتؤمنوا أنتم '),
(20597, 'John', 43, 19, 36, ' لأن هذا كان ليتم الكتاب القائل : عظم لا يكسر منه '),
(20598, 'John', 43, 19, 37, ' وأيضا يقول كتاب آخر : سينظرون إلى الذي طعنوه '),
(20599, 'John', 43, 19, 38, ' ثم إن يوسف الذي من الرامة ، وهو تلميذ يسوع ، ولكن خفية لسبب الخوف من اليهود ، سأل بيلاطس أن يأخذ جسد يسوع ، فأذن بيلاطس . فجاء وأخذ جسد يسوع '),
(20600, 'John', 43, 19, 39, ' وجاء أيضا نيقوديموس ، الذي أتى أولا إلى يسوع ليلا ، وهو حامل مزيج مر وعود نحو مئة منا '),
(20601, 'John', 43, 19, 40, ' فأخذا جسد يسوع ، ولفاه بأكفان مع الأطياب ، كما لليهود عادة أن يكفنوا '),
(20602, 'John', 43, 19, 41, ' وكان في الموضع الذي صلب فيه بستان ، وفي البستان قبر جديد لم يوضع فيه أحد قط '),
(20603, 'John', 43, 19, 42, ' فهناك وضعا يسوع لسبب استعداد اليهود ، لأن القبر كان قريبا '),
(20604, 'John', 43, 20, 1, ' وفي أول الأسبوع جاءت مريم المجدلية إلى القبر باكرا ، والظلام باق . فنظرت الحجر مرفوعا عن القبر '),
(20605, 'John', 43, 20, 2, ' فركضت وجاءت إلى سمعان بطرس وإلى التلميذ الآخر الذي كان يسوع يحبه ، وقالت لهما : أخذوا السيد من القبر ، ولسنا نعلم أين وضعوه '),
(20606, 'John', 43, 20, 3, ' فخرج بطرس والتلميذ الآخر وأتيا إلى القبر '),
(20607, 'John', 43, 20, 4, ' وكان الاثنان يركضان معا . فسبق التلميذ الآخر بطرس وجاء أولا إلى القبر '),
(20608, 'John', 43, 20, 5, ' وانحنى فنظر الأكفان موضوعة ، ولكنه لم يدخل '),
(20609, 'John', 43, 20, 6, ' ثم جاء سمعان بطرس يتبعه ، ودخل القبر ونظر الأكفان موضوعة '),
(20610, 'John', 43, 20, 7, ' والمنديل الذي كان على رأسه ليس موضوعا مع الأكفان ، بل ملفوفا في موضع وحده '),
(20611, 'John', 43, 20, 8, ' فحينئذ دخل أيضا التلميذ الآخر الذي جاء أولا إلى القبر ، ورأى فآمن '),
(20612, 'John', 43, 20, 9, ' لأنهم لم يكونوا بعد يعرفون الكتاب : أنه ينبغي أن يقوم من الأموات '),
(20613, 'John', 43, 20, 10, ' فمضى التلميذان أيضا إلى موضعهما '),
(20614, 'John', 43, 20, 11, ' أما مريم فكانت واقفة عند القبر خارجا تبكي . وفيما هي تبكي انحنت إلى القبر '),
(20615, 'John', 43, 20, 12, ' فنظرت ملاكين بثياب بيض جالسين واحدا عند الرأس والآخر عند الرجلين ، حيث كان جسد يسوع موضوعا '),
(20616, 'John', 43, 20, 13, ' فقالا لها : يا امرأة ، لماذا تبكين ؟ قالت لهما : إنهم أخذوا سيدي ، ولست أعلم أين وضعوه '),
(20617, 'John', 43, 20, 14, ' ولما قالت هذا التفتت إلى الوراء ، فنظرت يسوع واقفا ، ولم تعلم أنه يسوع '),
(20618, 'John', 43, 20, 15, ' قال لها يسوع : يا امرأة ، لماذا تبكين ؟ من تطلبين ؟ فظنت تلك أنه البستاني ، فقالت له : يا سيد ، إن كنت أنت قد حملته فقل لي : أين وضعته ، وأنا آخذه '),
(20619, 'John', 43, 20, 16, ' قال لها يسوع : يا مريم فالتفتت تلك وقالت له : ربوني الذي تفسيره : يا معلم '),
(20620, 'John', 43, 20, 17, ' قال لها يسوع : لا تلمسيني لأني لم أصعد بعد إلى أبي . ولكن اذهبي إلى إخوتي وقولي لهم : إني أصعد إلى أبي وأبيكم وإلهي وإلهكم '),
(20621, 'John', 43, 20, 18, ' فجاءت مريم المجدلية وأخبرت التلاميذ أنها رأت الرب ، وأنه قال لها هذا '),
(20622, 'John', 43, 20, 19, ' ولما كانت عشية ذلك اليوم ، وهو أول الأسبوع ، وكانت الأبواب مغلقة حيث كان التلاميذ مجتمعين لسبب الخوف من اليهود ، جاء يسوع ووقف في الوسط ، وقال لهم : سلام لكم '),
(20623, 'John', 43, 20, 20, ' ولما قال هذا أراهم يديه وجنبه ، ففرح التلاميذ إذ رأوا الرب ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(20624, 'John', 43, 20, 21, ' فقال لهم يسوع أيضا : سلام لكم كما أرسلني الآب أرسلكم أنا '),
(20625, 'John', 43, 20, 22, ' ولما قال هذا نفخ وقال لهم : اقبلوا الروح القدس '),
(20626, 'John', 43, 20, 23, ' من غفرتم خطاياه تغفر له ، ومن أمسكتم خطاياه أمسكت '),
(20627, 'John', 43, 20, 24, ' أما توما ، أحد الاثني عشر ، الذي يقال له التوأم ، فلم يكن معهم حين جاء يسوع '),
(20628, 'John', 43, 20, 25, ' فقال له التلاميذ الآخرون : قد رأينا الرب . فقال لهم : إن لم أبصر في يديه أثر المسامير ، وأضع إصبعي في أثر المسامير ، وأضع يدي في جنبه ، لا أومن '),
(20629, 'John', 43, 20, 26, ' وبعد ثمانية أيام كان تلاميذه أيضا داخلا وتوما معهم . فجاء يسوع والأبواب مغلقة ، ووقف في الوسط وقال : سلام لكم '),
(20630, 'John', 43, 20, 27, ' ثم قال لتوما : هات إصبعك إلى هنا وأبصر يدي ، وهات يدك وضعها في جنبي ، ولا تكن غير مؤمن بل مؤمنا '),
(20631, 'John', 43, 20, 28, ' أجاب توما وقال له : ربي وإلهي '),
(20632, 'John', 43, 20, 29, ' قال له يسوع : لأنك رأيتني يا توما آمنت طوبى للذين آمنوا ولم يروا '),
(20633, 'John', 43, 20, 30, ' وآيات أخر كثيرة صنع يسوع قدام تلاميذه لم تكتب في هذا الكتاب '),
(20634, 'John', 43, 20, 31, ' وأما هذه فقد كتبت لتؤمنوا أن يسوع هو المسيح ابن الله ، ولكي تكون لكم إذا آمنتم حياة باسمه '),
(20635, 'John', 43, 21, 1, ' بعد هذا أظهر أيضا يسوع نفسه للتلاميذ على بحر طبرية . ظهر هكذا '),
(20636, 'John', 43, 21, 2, ' كان سمعان بطرس ، وتوما الذي يقال له التوأم ، ونثنائيل الذي من قانا الجليل ، وابنا زبدي ، واثنان آخران من تلاميذه مع بعضهم '),
(20637, 'John', 43, 21, 3, ' قال لهم سمعان بطرس : أنا أذهب لأتصيد . قالوا له : نذهب نحن أيضا معك . فخرجوا ودخلوا السفينة للوقت . وفي تلك الليلة لم يمسكوا شيئا '),
(20638, 'John', 43, 21, 4, ' ولما كان الصبح ، وقف يسوع على الشاطئ . ولكن التلاميذ لم يكونوا يعلمون أنه يسوع '),
(20639, 'John', 43, 21, 5, ' فقال لهم يسوع : يا غلمان ألعل عندكم إداما ؟  . أجابوه : لا '),
(20640, 'John', 43, 21, 6, ' فقال لهم : ألقوا الشبكة إلى جانب السفينة الأيمن فتجدوا . فألقوا ، ولم يعودوا يقدرون أن يجذبوها من كثرة السمك '),
(20641, 'John', 43, 21, 7, ' فقال ذلك التلميذ الذي كان يسوع يحبه لبطرس : هو الرب . فلما سمع سمعان بطرس أنه الرب ، اتزر بثوبه ، لأنه كان عريانا ، وألقى نفسه في البحر '),
(20642, 'John', 43, 21, 8, ' وأما التلاميذ الآخرون فجاءوا بالسفينة ، لأنهم لم يكونوا بعيدين عن الأرض إلا نحو مئتي ذراع ، وهم يجرون شبكة السمك '),
(20643, 'John', 43, 21, 9, ' فلما خرجوا إلى الأرض نظروا جمرا موضوعا وسمكا موضوعا عليه وخبزا '),
(20644, 'John', 43, 21, 10, ' قال لهم يسوع : قدموا من السمك الذي أمسكتم الآن '),
(20645, 'John', 43, 21, 11, ' فصعد سمعان بطرس وجذب الشبكة إلى الأرض ، ممتلئة سمكا كبيرا ، مئة وثلاثا وخمسين . ومع هذه الكثرة لم تتخرق الشبكة '),
(20646, 'John', 43, 21, 12, ' قال لهم يسوع : هلموا تغدوا . ولم يجسر أحد من التلاميذ أن يسأله : من أنت ؟ إذ كانوا يعلمون أنه الرب '),
(20647, 'John', 43, 21, 13, ' ثم جاء يسوع وأخذ الخبز وأعطاهم وكذلك السمك '),
(20648, 'John', 43, 21, 14, ' هذه مرة ثالثة ظهر يسوع لتلاميذه بعدما قام من الأموات '),
(20649, 'John', 43, 21, 15, ' فبعد ما تغدوا قال يسوع لسمعان بطرس : يا سمعان بن يونا ، أتحبني أكثر من هؤلاء ؟ قال له : نعم يا رب ، أنت تعلم أني أحبك . قال له : ارع خرافي '),
(20650, 'John', 43, 21, 16, ' قال له أيضا ثانية : يا سمعان بن يونا ، أتحبني ؟ قال له : نعم يا رب ، أنت تعلم أني أحبك . قال له : ارع غنمي '),
(20651, 'John', 43, 21, 17, ' قال له ثالثة : يا سمعان بن يونا ، أتحبني ؟ فحزن بطرس لأنه قال له ثالثة : أتحبني ؟ فقال له : يا رب ، أنت تعلم كل شيء . أنت تعرف أني أحبك . قال له يسوع : ارع غنمي '),
(20652, 'John', 43, 21, 18, ' الحق الحق أقول لك : لما كنت أكثر حداثة كنت تمنطق ذاتك وتمشي حيث تشاء . ولكن متى شخت فإنك تمد يديك وآخر يمنطقك ، ويحملك حيث لا تشاء '),
(20653, 'John', 43, 21, 19, ' قال هذا مشيرا إلى أية ميتة كان مزمعا أن يمجد الله بها . ولما قال هذا قال له : اتبعني '),
(20654, 'John', 43, 21, 20, ' فالتفت بطرس ونظر التلميذ الذي كان يسوع يحبه يتبعه ، وهو أيضا الذي اتكأ على صدره وقت العشاء ، وقال : يا سيد ، من هو الذي يسلمك '),
(20655, 'John', 43, 21, 21, ' فلما رأى بطرس هذا ، قال ليسوع : يا رب ، وهذا ما له '),
(20656, 'John', 43, 21, 22, ' قال له يسوع : إن كنت أشاء أنه يبقى حتى أجيء ، فماذا لك ؟ اتبعني أنت '),
(20657, 'John', 43, 21, 23, ' فذاع هذا القول بين الإخوة : إن ذلك التلميذ لا يموت . ولكن لم يقل له يسوع إنه لا يموت ، بل : إن كنت أشاء أنه يبقى حتى أجيء ، فماذا لك '),
(20658, 'John', 43, 21, 24, ' هذا هو التلميذ الذي يشهد بهذا وكتب هذا . ونعلم أن شهادته حق '),
(20659, 'John', 43, 21, 25, ' وأشياء أخر كثيرة صنعها يسوع ، إن كتبت واحدة واحدة ، فلست أظن أن العالم نفسه يسع الكتب المكتوبة . آمين '),
(20660, 'Jonah', 32, 1, 1, ' وصار قول الرب إلى يونان بن أمتاي قائلا '),
(20661, 'Jonah', 32, 1, 2, ' قم اذهب إلى نينوى المدينة العظيمة وناد عليها ، لأنه قد صعد شرهم أمامي '),
(20662, 'Jonah', 32, 1, 3, ' فقام يونان ليهرب إلى ترشيش من وجه الرب ، فنزل إلى يافا ووجد سفينة ذاهبة إلى ترشيش ، فدفع أجرتها ونزل فيها ، ليذهب معهم إلى ترشيش من وجه الرب '),
(20663, 'Jonah', 32, 1, 4, ' فأرسل الرب ريحا شديدة إلى البحر ، فحدث نوء عظيم في البحر حتى كادت السفينة تنكسر '),
(20664, 'Jonah', 32, 1, 5, ' فخاف الملاحون وصرخوا كل واحد إلى إلهه ، وطرحوا الأمتعة التي في السفينة إلى البحر ليخففوا عنهم . وأما يونان فكان قد نزل إلى جوف السفينة واضطجع ونام نوما ثقيلا '),
(20665, 'Jonah', 32, 1, 6, ' فجاء إليه رئيس النوتية وقال له : ما لك نائما ؟ قم اصرخ إلى إلهك عسى أن يفتكر الإله فينا فلا نهلك '),
(20666, 'Jonah', 32, 1, 7, ' وقال بعضهم لبعض : هلم نلقي قرعا لنعرف بسبب من هذه البلية . فألقوا قرعا ، فوقعت القرعة على يونان '),
(20667, 'Jonah', 32, 1, 8, ' فقالوا له : أخبرنا بسبب من هذه المصيبة علينا ؟ ما هو عملك ؟ ومن أين أتيت ؟ ما هي أرضك ؟ ومن أي شعب أنت '),
(20668, 'Jonah', 32, 1, 9, ' فقال لهم : أنا عبراني ، وأنا خائف من الرب إله السماء الذي صنع البحر والبر '),
(20669, 'Jonah', 32, 1, 10, ' فخاف الرجال خوفا عظيما ، وقالوا له : لماذا فعلت هذا ؟  . فإن الرجال عرفوا أنه هارب من وجه الرب ، لأنه أخبرهم '),
(20670, 'Jonah', 32, 1, 11, ' فقالوا له : ماذا نصنع بك ليسكن البحر عنا ؟  . لأن البحر كان يزداد اضطرابا '),
(20671, 'Jonah', 32, 1, 12, ' فقال لهم : خذوني واطرحوني في البحر فيسكن البحر عنكم ، لأنني عالم أنه بسببي هذا النوء العظيم عليكم '),
(20672, 'Jonah', 32, 1, 13, ' ولكن الرجال جذفوا ليرجعوا السفينة إلى البر فلم يستطيعوا ، لأن البحر كان يزداد اضطرابا عليهم '),
(20673, 'Jonah', 32, 1, 14, ' فصرخوا إلى الرب وقالوا : آه يارب ، لا نهلك من أجل نفس هذا الرجل ، ولا تجعل علينا دما بريئا ، لأنك يارب فعلت كما شئت '),
(20674, 'Jonah', 32, 1, 15, ' ثم أخذوا يونان وطرحوه في البحر ، فوقف البحر عن هيجانه '),
(20675, 'Jonah', 32, 1, 16, ' فخاف الرجال من الرب خوفا عظيما ، وذبحوا ذبيحة للرب ونذروا نذورا '),
(20676, 'Jonah', 32, 1, 17, ' وأما الرب فأعد حوتا عظيما ليبتلع يونان . فكان يونان في جوف الحوت ثلاثة أيام وثلاث ليال '),
(20677, 'Jonah', 32, 2, 1, ' فصلى يونان إلى الرب إلهه من جوف الحوت '),
(20678, 'Jonah', 32, 2, 2, ' وقال : دعوت من ضيقي الرب ، فاستجابني . صرخت من جوف الهاوية ، فسمعت صوتي '),
(20679, 'Jonah', 32, 2, 3, ' لأنك طرحتني في العمق في قلب البحار ، فأحاط بي نهر . جازت فوقي جميع تياراتك ولججك '),
(20680, 'Jonah', 32, 2, 4, ' فقلت : قد طردت من أمام عينيك . ولكنني أعود أنظر إلى هيكل قدسك '),
(20681, 'Jonah', 32, 2, 5, ' قد اكتنفتني مياه إلى النفس . أحاط بي غمر . التف عشب البحر برأسي '),
(20682, 'Jonah', 32, 2, 6, ' نزلت إلى أسافل الجبال . مغاليق الأرض علي إلى الأبد . ثم أصعدت من الوهدة حياتي أيها الرب إلهي '),
(20683, 'Jonah', 32, 2, 7, ' حين أعيت في نفسي ذكرت الرب ، فجاءت إليك صلاتي إلى هيكل قدسك '),
(20684, 'Jonah', 32, 2, 8, ' الذين يراعون أباطيل كاذبة يتركون نعمتهم '),
(20685, 'Jonah', 32, 2, 9, ' أما أنا فبصوت الحمد أذبح لك ، وأوفي بما نذرته . للرب الخلاص '),
(20686, 'Jonah', 32, 2, 10, ' وأمر الرب الحوت فقذف يونان إلى البر '),
(20687, 'Jonah', 32, 3, 1, ' ثم صار قول الرب إلى يونان ثانية قائلا '),
(20688, 'Jonah', 32, 3, 2, ' قم اذهب إلى نينوى المدينة العظيمة ، وناد لها المناداة التي أنا مكلمك بها '),
(20689, 'Jonah', 32, 3, 3, ' فقام يونان وذهب إلى نينوى بحسب قول الرب . أما نينوى فكانت مدينة عظيمة لله مسيرة ثلاثة أيام '),
(20690, 'Jonah', 32, 3, 4, ' فابتدأ يونان يدخل المدينة مسيرة يوم واحد ، ونادى وقال : بعد أربعين يوما تنقلب نينوى '),
(20691, 'Jonah', 32, 3, 5, ' فآمن أهل نينوى بالله ونادوا بصوم ولبسوا مسوحا من كبيرهم إلى صغيرهم '),
(20692, 'Jonah', 32, 3, 6, ' وبلغ الأمر ملك نينوى ، فقام عن كرسيه وخلع رداءه عنه ، وتغطى بمسح وجلس على الرماد '),
(20693, 'Jonah', 32, 3, 7, ' ونودي وقيل في نينوى عن أمر الملك وعظمائه قائلا : لا تذق الناس ولا البهائم ولا البقر ولا الغنم شيئا . لا ترع ولا تشرب ماء '),
(20694, 'Jonah', 32, 3, 8, ' وليتغط بمسوح الناس والبهائم ، ويصرخوا إلى الله بشدة ، ويرجعوا كل واحد عن طريقه الرديئة وعن الظلم الذي في أيديهم '),
(20695, 'Jonah', 32, 3, 9, ' لعل الله يعود ويندم ويرجع عن حمو غضبه فلا نهلك '),
(20696, 'Jonah', 32, 3, 10, ' فلما رأى الله أعمالهم أنهم رجعوا عن طريقهم الرديئة ، ندم الله على الشر الذي تكلم أن يصنعه بهم ، فلم يصنعه '),
(20697, 'Jonah', 32, 4, 1, ' فغم ذلك يونان غما شديدا ، فاغتاظ '),
(20698, 'Jonah', 32, 4, 2, ' وصلى إلى الرب وقال : آه يارب ، أليس هذا كلامي إذ كنت بعد في أرضي ؟ لذلك بادرت إلى الهرب إلى ترشيش ، لأني علمت أنك إله رؤوف ورحيم بطيء الغضب وكثير الرحمة ونادم على الشر '),
(20699, 'Jonah', 32, 4, 3, ' فالآن يارب ، خذ نفسي مني ، لأن موتي خير من حياتي '),
(20700, 'Jonah', 32, 4, 4, ' فقال الرب : هل اغتظت بالصواب '),
(20701, 'Jonah', 32, 4, 5, ' وخرج يونان من المدينة وجلس شرقي المدينة ، وصنع لنفسه هناك مظلة وجلس تحتها في الظل ، حتى يرى ماذا يحدث في المدينة '),
(20702, 'Jonah', 32, 4, 6, ' فأعد الرب الإله يقطينة فارتفعت فوق يونان لتكون ظلا على رأسه ، لكي يخلصه من غمه . ففرح يونان من أجل اليقطينة فرحا عظيما '),
(20703, 'Jonah', 32, 4, 7, ' ثم أعد الله دودة عند طلوع الفجر في الغد ، فضربت اليقطينة فيبست '),
(20704, 'Jonah', 32, 4, 8, ' وحدث عند طلوع الشمس أن الله أعد ريحا شرقية حارة ، فضربت الشمس على رأس يونان فذبل . فطلب لنفسه الموت ، وقال : موتي خير من حياتي '),
(20705, 'Jonah', 32, 4, 9, ' فقال الله ليونان : هل اغتظت بالصواب من أجل اليقطينة ؟  . فقال : اغتظت بالصواب حتى الموت '),
(20706, 'Jonah', 32, 4, 10, ' فقال الرب : أنت شفقت على اليقطينة التي لم تتعب فيها ولا ربيتها ، التي بنت ليلة كانت وبنت ليلة هلكت '),
(20707, 'Jonah', 32, 4, 11, ' أفلا أشفق أنا على نينوى المدينة العظيمة التي يوجد فيها أكثر من اثنتي عشرة ربوة من الناس الذين لا يعرفون يمينهم من شمالهم ، وبهائم كثيرة '),
(20708, 'Joshua', 6, 1, 1, ' وكان بعد موت موسى عبد الرب أن الرب كلم يشوع بن نون خادم موسى قائلا '),
(20709, 'Joshua', 6, 1, 2, ' موسى عبدي قد مات . فالآن قم اعبر هذا الأردن أنت وكل هذا الشعب إلى الأرض التي أنا معطيها لهم أي لبني إسرائيل '),
(20710, 'Joshua', 6, 1, 3, ' كل موضع تدوسه بطون أقدامكم لكم أعطيته ، كما كلمت موسى '),
(20711, 'Joshua', 6, 1, 4, ' من البرية ولبنان هذا إلى النهر الكبير نهر الفرات ، جميع أرض الحثيين ، وإلى البحر الكبير نحو مغرب الشمس يكون تخمكم '),
(20712, 'Joshua', 6, 1, 5, ' لا يقف إنسان في وجهك كل أيام حياتك . كما كنت مع موسى أكون معك . لا أهملك ولا أتركك '),
(20713, 'Joshua', 6, 1, 6, ' تشدد وتشجع ، لأنك أنت تقسم لهذا الشعب الأرض التي حلفت لآبائهم أن أعطيهم '),
(20714, 'Joshua', 6, 1, 7, ' إنما كن متشددا ، وتشجع جدا لكي تتحفظ للعمل حسب كل الشريعة التي أمرك بها موسى عبدي . لا تمل عنها يمينا ولا شمالا لكي تفلح حيثما تذهب '),
(20715, 'Joshua', 6, 1, 8, ' لا يبرح سفر هذه الشريعة من فمك ، بل تلهج فيه نهارا وليلا ، لكي تتحفظ للعمل حسب كل ما هو مكتوب فيه . لأنك حينئذ تصلح طريقك وحينئذ تفلح '),
(20716, 'Joshua', 6, 1, 9, ' أما أمرتك ؟ تشدد وتشجع لا ترهب ولا ترتعب لأن الرب إلهك معك حيثما تذهب '),
(20717, 'Joshua', 6, 1, 10, ' فأمر يشوع عرفاء الشعب قائلا '),
(20718, 'Joshua', 6, 1, 11, ' جوزوا في وسط المحلة وأمروا الشعب قائلين : هيئوا لأنفسكم زادا ، لأنكم بعد ثلاثة أيام تعبرون الأردن هذا لكي تدخلوا فتمتلكوا الأرض التي يعطيكم الرب إلهكم لتمتلكوها '),
(20719, 'Joshua', 6, 1, 12, ' ثم كلم يشوع الرأوبينيين والجاديين ونصف سبط منسى قائلا '),
(20720, 'Joshua', 6, 1, 13, ' اذكروا الكلام الذي أمركم به موسى عبد الرب قائلا : الرب إلهكم قد أراحكم وأعطاكم هذه الأرض '),
(20721, 'Joshua', 6, 1, 14, ' نساؤكم وأطفالكم ومواشيكم تلبث في الأرض التي أعطاكم موسى في عبر الأردن ، وأنتم تعبرون متجهزين أمام إخوتكم ، كل الأبطال ذوي البأس ، وتعينونهم '),
(20722, 'Joshua', 6, 1, 15, ' حتى يريح الرب إخوتكم مثلكم ، ويمتلكوا هم أيضا الأرض التي يعطيهم الرب إلهكم . ثم ترجعون إلى أرض ميراثكم وتمتلكونها ، التي أعطاكم موسى عبد الرب في عبر الأردن نحو شروق الشمس '),
(20723, 'Joshua', 6, 1, 16, ' فأجابوا يشوع قائلين : كل ما أمرتنا به نعمله ، وحيثما ترسلنا نذهب '),
(20724, 'Joshua', 6, 1, 17, ' حسب كل ما سمعنا لموسى نسمع لك . إنما الرب إلهك يكون معك كما كان مع موسى '),
(20725, 'Joshua', 6, 1, 18, ' كل إنسان يعصى قولك ولا يسمع كلامك في كل ما تأمره به يقتل . إنما كن متشددا وتشجع '),
(20726, 'Joshua', 6, 2, 1, ' فأرسل يشوع بن نون من شطيم رجلين جاسوسين سرا ، قائلا : اذهبا انظرا الأرض وأريحا . فذهبا ودخلا بيت امرأة زانية اسمها راحاب واضطجعا هناك '),
(20727, 'Joshua', 6, 2, 2, ' فقيل لملك أريحا : هوذا قد دخل إلى هنا الليلة رجلان من بني إسرائيل لكي يتجسسا الأرض '),
(20728, 'Joshua', 6, 2, 3, ' فأرسل ملك أريحا إلى راحاب يقول : أخرجي الرجلين اللذين أتيا إليك ودخلا بيتك ، لأنهما قد أتيا لكي يتجسسا الأرض كلها '),
(20729, 'Joshua', 6, 2, 4, ' فأخذت المرأة الرجلين وخبأتهما وقالت : نعم جاء إلي الرجلان ولم أعلم من أين هما '),
(20730, 'Joshua', 6, 2, 5, ' وكان نحو انغلاق الباب في الظلام أنه خرج الرجلان . لست أعلم أين ذهب الرجلان . اسعوا سريعا وراءهما حتى تدركوهما '),
(20731, 'Joshua', 6, 2, 6, ' وأما هي فأطلعتهما على السطح ووارتهما بين عيدان كتان لها منضدة على السطح '),
(20732, 'Joshua', 6, 2, 7, ' فسعى القوم وراءهما في طريق الأردن إلى المخاوض . وحالما خرج الذين سعوا وراءهما ، أغلقوا الباب '),
(20733, 'Joshua', 6, 2, 8, ' وأما هما فقبل أن يضطجعا ، صعدت إليهما إلى السطح '),
(20734, 'Joshua', 6, 2, 9, ' وقالت للرجلين : علمت أن الرب قد أعطاكم الأرض ، وأن رعبكم قد وقع علينا ، وأن جميع سكان الأرض ذابوا من أجلكم '),
(20735, 'Joshua', 6, 2, 10, ' لأننا قد سمعنا كيف يبس الرب مياه بحر سوف قدامكم عند خروجكم من مصر ، وما عملتموه بملكي الأموريين اللذين في عبر الأردن : سيحون وعوج ، اللذين حرمتموهما '),
(20736, 'Joshua', 6, 2, 11, ' سمعنا فذابت قلوبنا ولم تبق بعد روح في إنسان بسببكم ، لأن الرب إلهكم هو الله في السماء من فوق وعلى الأرض من تحت '),
(20737, 'Joshua', 6, 2, 12, ' فالآن احلفا لي بالرب وأعطياني علامة أمانة . لأني قد عملت معكما معروفا . بأن تعملا أنتما أيضا مع بيت أبي معروفا '),
(20738, 'Joshua', 6, 2, 13, ' وتستحييا أبي وأمي وإخوتي وأخواتي وكل ما لهم وتخلصا أنفسنا من الموت '),
(20739, 'Joshua', 6, 2, 14, ' فقال لها الرجلان : نفسنا عوضكم للموت إن لم تفشوا أمرنا هذا . ويكون إذا أعطانا الرب الأرض أننا نعمل معك معروفا وأمانة '),
(20740, 'Joshua', 6, 2, 15, ' فأنزلتهما بحبل من الكوة ، لأن بيتها بحائط السور ، وهي سكنت بالسور '),
(20741, 'Joshua', 6, 2, 16, ' وقالت لهما : اذهبا إلى الجبل لئلا يصادفكما السعاة ، واختبئا هناك ثلاثة أيام حتى يرجع السعاة ، ثم اذهبا في طريقكما '),
(20742, 'Joshua', 6, 2, 17, ' فقال لها الرجلان : نحن بريئان من يمينك هذا الذي حلفتنا به '),
(20743, 'Joshua', 6, 2, 18, ' هوذا نحن نأتي إلى الأرض ، فاربطي هذا الحبل من خيوط القرمز في الكوة التي أنزلتنا منها ، واجمعي إليك في البيت أباك وأمك وإخوتك وسائر بيت أبيك '),
(20744, 'Joshua', 6, 2, 19, ' فيكون أن كل من يخرج من أبواب بيتك إلى خارج ، فدمه على رأسه ، ونحن نكون بريئين . وأما كل من يكون معك في البيت فدمه على رأسنا إذا وقعت عليه يد '),
(20745, 'Joshua', 6, 2, 20, ' وإن أفشيت أمرنا هذا نكون بريئين من حلفك الذي حلفتنا '),
(20746, 'Joshua', 6, 2, 21, ' فقالت : هو هكذا حسب كلامكما . وصرفتهما فذهبا . وربطت حبل القرمز في الكوة '),
(20747, 'Joshua', 6, 2, 22, ' فانطلقا وجاءا إلى الجبل ولبثا هناك ثلاثة أيام حتى رجع السعاة . وفتش السعاة في كل الطريق فلم يجدوهما '),
(20748, 'Joshua', 6, 2, 23, ' ثم رجع الرجلان ونزلا عن الجبل وعبرا وأتيا إلى يشوع بن نون وقصا عليه كل ما أصابهما '),
(20749, 'Joshua', 6, 2, 24, ' وقالا ليشوع : إن الرب قد دفع بيدنا الأرض كلها ، وقد ذاب كل سكان الأرض بسببنا '),
(20750, 'Joshua', 6, 3, 1, ' فبكر يشوع في الغد وارتحلوا من شطيم وأتوا إلى الأردن ، هو وكل بني إسرائيل ، وباتوا هناك قبل أن عبروا '),
(20751, 'Joshua', 6, 3, 2, ' وكان بعد ثلاثة أيام أن العرفاء جازوا في وسط المحلة '),
(20752, 'Joshua', 6, 3, 3, ' وأمروا الشعب قائلين : عندما ترون تابوت عهد الرب إلهكم والكهنة اللاويين حاملين إياه ، فارتحلوا من أماكنكم وسيروا وراءه '),
(20753, 'Joshua', 6, 3, 4, ' ولكن يكون بينكم وبينه مسافة نحو ألفي ذراع بالقياس . لا تقربوا منه لكي تعرفوا الطريق الذي تسيرون فيه . لأنكم لم تعبروا هذا الطريق من قبل '),
(20754, 'Joshua', 6, 3, 5, ' وقال يشوع للشعب : تقدسوا لأن الرب يعمل غدا في وسطكم عجائب '),
(20755, 'Joshua', 6, 3, 6, ' وقال يشوع للكهنة : احملوا تابوت العهد واعبروا أمام الشعب . فحملوا تابوت العهد وساروا أمام الشعب '),
(20756, 'Joshua', 6, 3, 7, ' فقال الرب ليشوع : اليوم أبتدئ أعظمك في أعين جميع إسرائيل لكي يعلموا أني كما كنت مع موسى أكون معك '),
(20757, 'Joshua', 6, 3, 8, ' وأما أنت فأمر الكهنة حاملي تابوت العهد قائلا : عندما تأتون إلى ضفة مياه الأردن تقفون في الأردن '),
(20758, 'Joshua', 6, 3, 9, ' فقال يشوع لبني إسرائيل : تقدموا إلى هنا واسمعوا كلام الرب إلهكم '),
(20759, 'Joshua', 6, 3, 10, ' ثم قال يشوع : بهذا تعلمون أن الله الحي في وسطكم ، وطردا يطرد من أمامكم الكنعانيين والحثيين والحويين والفرزيين والجرجاشيين والأموريين واليبوسيين '),
(20760, 'Joshua', 6, 3, 11, ' هوذا تابوت عهد سيد كل الأرض عابر أمامكم في الأردن '),
(20761, 'Joshua', 6, 3, 12, ' فالآن انتخبوا اثني عشر رجلا من أسباط إسرائيل ، رجلا واحدا من كل سبط '),
(20762, 'Joshua', 6, 3, 13, ' ويكون حينما تستقر بطون أقدام الكهنة حاملي تابوت الرب سيد الأرض كلها في مياه الأردن ، أن مياه الأردن ، المياه المنحدرة من فوق ، تنفلق وتقف ندا واحدا '),
(20763, 'Joshua', 6, 3, 14, ' ولما ارتحل الشعب من خيامهم لكي يعبروا الأردن ، والكهنة حاملو تابوت العهد أمام الشعب '),
(20764, 'Joshua', 6, 3, 15, ' فعند إتيان حاملي التابوت إلى الأردن وانغماس أرجل الكهنة حاملي التابوت في ضفة المياه ، والأردن ممتلئ إلى جميع شطوطه كل أيام الحصاد '),
(20765, 'Joshua', 6, 3, 16, ' وقفت المياه المنحدرة من فوق ، وقامت ندا واحدا بعيدا جدا عن أدام المدينة التي إلى جانب صرتان ، والمنحدرة إلى بحر العربة بحر الملح انقطعت تماما ، وعبر الشعب مقابل أريحا '),
(20766, 'Joshua', 6, 3, 17, ' فوقف الكهنة حاملو تابوت عهد الرب على اليابسة في وسط الأردن راسخين ، وجميع إسرائيل عابرون على اليابسة حتى انتهى جميع الشعب من عبور الأردن '),
(20767, 'Joshua', 6, 4, 1, ' وكان لما انتهى جميع الشعب من عبور الأردن أن الرب كلم يشوع قائلا '),
(20768, 'Joshua', 6, 4, 2, ' انتخبوا من الشعب اثني عشر رجلا ، رجلا واحدا من كل سبط '),
(20769, 'Joshua', 6, 4, 3, ' وأمروهم قائلين : احملوا من هنا من وسط الأردن ، من موقف أرجل الكهنة راسخة ، اثني عشر حجرا ، وعبروها معكم وضعوها في المبيت الذي تبيتون فيه الليلة '),
(20770, 'Joshua', 6, 4, 4, ' فدعا يشوع الاثني عشر رجلا الذين عينهم من بني إسرائيل ، رجلا واحدا من كل سبط '),
(20771, 'Joshua', 6, 4, 5, ' وقال لهم يشوع : اعبروا أمام تابوت الرب إلهكم إلى وسط الأردن ، وارفعوا كل رجل حجرا واحدا على كتفه حسب عدد أسباط بني إسرائيل '),
(20772, 'Joshua', 6, 4, 6, ' لكي تكون هذه علامة في وسطكم . إذا سأل غدا بنوكم قائلين : ما لكم وهذه الحجارة '),
(20773, 'Joshua', 6, 4, 7, ' تقولون لهم : إن مياه الأردن قد انفلقت أمام تابوت عهد الرب . عند عبوره الأردن انفلقت مياه الأردن . فتكون هذه الحجارة تذكارا لبني إسرائيل إلى الدهر '),
(20774, 'Joshua', 6, 4, 8, ' ففعل بنو إسرائيل هكذا كما أمر يشوع ، وحملوا اثني عشر حجرا من وسط الأردن ، كما قال الرب ليشوع ، حسب عدد أسباط بني إسرائيل ، وعبروها معهم إلى المبيت ووضعوها هناك '),
(20775, 'Joshua', 6, 4, 9, ' ونصب يشوع اثني عشر حجرا في وسط الأردن تحت موقف أرجل الكهنة حاملي تابوت العهد . وهي هناك إلى هذا اليوم '),
(20776, 'Joshua', 6, 4, 10, ' والكهنة حاملو التابوت وقفوا في وسط الأردن حتى انتهى كل شيء أمر الرب يشوع أن يكلم به الشعب ، حسب كل ما أمر به موسى يشوع . وأسرع الشعب فعبروا '),
(20777, 'Joshua', 6, 4, 11, ' وكان لما انتهى كل الشعب من العبور ، أنه عبر تابوت الرب والكهنة في حضرة الشعب '),
(20778, 'Joshua', 6, 4, 12, ' وعبر بنو رأوبين وبنو جاد ونصف سبط منسى متجهزين أمام بني إسرائيل ، كما كلمهم موسى '),
(20779, 'Joshua', 6, 4, 13, ' نحو أربعين ألفا متجردين للجند عبروا أمام الرب للحرب إلى عربات أريحا '),
(20780, 'Joshua', 6, 12, 16, ' ملك مقيدة واحد . ملك بيت إيل واحد '),
(20781, 'Joshua', 6, 12, 17, ' ملك تفوح واحد . ملك حافر واحد '),
(20782, 'Joshua', 6, 12, 18, ' ملك أفيق واحد . ملك لشارون واحد '),
(20783, 'Joshua', 6, 12, 19, ' ملك مادون واحد . ملك حاصور واحد '),
(20784, 'Joshua', 6, 12, 20, ' ملك شمرون مرأون واحد . ملك أكشاف واحد '),
(20785, 'Joshua', 6, 12, 21, ' ملك تعنك واحد . ملك مجدو واحد '),
(20786, 'Joshua', 6, 12, 22, ' ملك قادش واحد . ملك يقنعام في كرمل واحد '),
(20787, 'Joshua', 6, 12, 23, ' ملك دور في مرتفعات دور واحد . ملك جوييم في الجلجال واحد '),
(20788, 'Joshua', 6, 12, 24, ' ملك ترصة واحد . جميع الملوك واحد وثلاثون '),
(20789, 'Joshua', 6, 13, 1, ' وشاخ يشوع . تقدم في الأيام . فقال له الرب : أنت قد شخت . تقدمت في الأيام . وقد بقيت أرض كثيرة جدا للامتلاك '),
(20790, 'Joshua', 6, 13, 2, ' هذه هي الأرض الباقية : كل دائرة الفلسطينيين ، وكل الجشوريين '),
(20791, 'Joshua', 6, 13, 3, ' من الشيحور الذي هو أمام مصر إلى تخم عقرون شمالا تحسب للكنعانيين أقطاب الفلسطينيين الخمسة : الغزي والأشدودي والأشقلوني والجتي والعقروني ، والعويين '),
(20792, 'Joshua', 6, 13, 4, ' من التيمن كل أرض الكنعانيين ، ومغارة التي للصيدونيين إلى أفيق إلى تخم الأموريين '),
(20793, 'Joshua', 6, 13, 5, ' وأرض الجبليين ، وكل لبنان نحو شروق الشمس ، من بعل جاد تحت جبل حرمون إلى مدخل حماة '),
(20794, 'Joshua', 6, 13, 6, ' جميع سكان الجبل من لبنان إلى مسرفوت مايم ، جميع الصيدونيين . أنا أطردهم من أمام بني إسرائيل . إنما اقسمها بالقرعة لإسرائيل ملكا كما أمرتك '),
(20795, 'Joshua', 6, 13, 7, ' والآن اقسم هذه الأرض ملكا للتسعة الأسباط ونصف سبط منسى '),
(20796, 'Joshua', 6, 13, 8, ' معهم أخذ الرأوبينيون والجاديون ملكهم الذي أعطاهم موسى في عبر الأردن نحو الشروق ، كما أعطاهم موسى عبد الرب '),
(20797, 'Joshua', 6, 13, 9, ' من عروعير التي على حافة وادي أرنون والمدينة التي في وسط الوادي ، وكل سهل ميدبا إلى ديبون '),
(20798, 'Joshua', 6, 13, 10, ' وجميع مدن سيحون ملك الأموريين الذي ملك في حشبون إلى تخم بني عمون '),
(20799, 'Joshua', 6, 13, 11, ' وجلعاد وتخوم الجشوريين والمعكيين ، وكل جبل حرمون ، وكل باشان إلى سلخة '),
(20800, 'Joshua', 6, 13, 12, ' كل مملكة عوج في باشان الذي ملك في عشتاروث وفي إذرعي . هو بقي من بقية الرفائيين ، وضربهم موسى وطردهم '),
(20801, 'Joshua', 6, 13, 13, ' ولم يطرد بنو إسرائيل الجشوريين والمعكيين ، فسكن الجشوري والمعكي في وسط إسرائيل إلى هذا اليوم '),
(20802, 'Joshua', 6, 13, 14, ' لكن لسبط لاوي لم يعط نصيبا . وقائد الرب إله إسرائيل هي نصيبه كما كلمه '),
(20803, 'Joshua', 6, 13, 15, ' وأعطى موسى سبط بني رأوبين حسب عشائرهم '),
(20804, 'Joshua', 6, 13, 16, ' فكان تخمهم من عروعير التي على حافة وادي أرنون والمدينة التي في وسط الوادي ، وكل السهل عند ميدبا '),
(20805, 'Joshua', 6, 13, 17, ' حشبون وجميع مدنها التي في السهل ، وديبون وباموت بعل وبيت بعل معون '),
(20806, 'Joshua', 6, 13, 18, ' ويهصة وقديموت وميفعة '),
(20807, 'Joshua', 6, 13, 19, ' وقريتايم وسبمة وصارث الشحر في جبل الوادي '),
(20808, 'Joshua', 6, 13, 20, ' وبيت فغور وسفوح الفسجة وبيت يشيموت '),
(20809, 'Joshua', 6, 13, 21, ' وكل مدن السهل ، وكل مملكة سيحون ملك الأموريين الذي ملك في حشبون ، الذي ضربه موسى مع رؤساء مديان : أوي وراقم وصور وحور ورابع ، أمراء سيحون ساكني الأرض '),
(20810, 'Joshua', 6, 13, 22, ' وبلعام بن بعور العراف قتله بنو إسرائيل بالسيف مع قتلاهم '),
(20811, 'Joshua', 6, 13, 23, ' وكان تخم بني رأوبين الأردن وتخومه . هذا نصيب بني رأوبين حسب عشائرهم ، المدن وضياعها '),
(20812, 'Joshua', 6, 13, 24, ' وأعطى موسى لسبط جاد ، بني جاد حسب عشائرهم '),
(20813, 'Joshua', 6, 13, 25, ' فكان تخمهم يعزير وكل مدن جلعاد ونصف أرض بني عمون إلى عروعير التي هي أمام ربة '),
(20814, 'Joshua', 6, 13, 26, ' ومن حشبون إلى رامة المصفاة وبطونيم ، ومن محنايم إلى تخم دبير '),
(20815, 'Joshua', 6, 13, 27, ' وفي الوادي بيت هارام ، وبيت نمرة ، وسكوت ، وصافون بقية مملكة سيحون ملك حشبون ، الأردن وتخومه إلى طرف بحر كنروت في عبر الأردن نحو الشروق '),
(20816, 'Joshua', 6, 13, 28, ' هذا نصيب بني جاد حسب عشائرهم ، المدن وضياعها '),
(20817, 'Joshua', 6, 13, 29, ' وأعطى موسى لنصف سبط منسى ، وكان لنصف سبط بني منسى حسب عشائرهم '),
(20818, 'Joshua', 6, 13, 30, ' وكان تخمهم من محنايم ، كل باشان ، كل مملكة عوج ملك باشان ، وكل حووث يائير التي في باشان ، ستين مدينة '),
(20819, 'Joshua', 6, 13, 31, ' ونصف جلعاد وعشتاروث وإذرعي مدن مملكة عوج في باشان لبني ماكير بن منسى ، لنصف بني ماكير حسب عشائرهم '),
(20820, 'Joshua', 6, 13, 32, ' فهذه هي التي قسمها موسى في عربات موآب في عبر أردن أريحا نحو الشروق '),
(20821, 'Joshua', 6, 13, 33, ' وأما سبط لاوي فلم يعطه موسى نصيبا . الرب إله إسرائيل هو نصيبهم كما كلمهم '),
(20822, 'Joshua', 6, 14, 1, ' فهذه هي التي امتلكها بنو إسرائيل في أرض كنعان ، التي ملكهم إياها ألعازار الكاهن ويشوع بن نون ورؤساء آباء أسباط بني إسرائيل '),
(20823, 'Joshua', 6, 14, 2, ' نصيبهم بالقرعة كما أمر الرب عن يد موسى للتسعة الأسباط ونصف السبط '),
(20824, 'Joshua', 6, 14, 3, ' لأن موسى أعطى نصيب السبطين ونصف السبط في عبر الأردن . وأما اللاويون فلم يعطهم نصيبا في وسطهم '),
(20825, 'Joshua', 6, 14, 4, ' لأن بني يوسف كانوا سبطين : منسى وأفرايم . ولم يعطوا اللاويين قسما في الأرض إلا مدنا للسكن ، ومسارحها لمواشيهم ومقتناهم '),
(20826, 'Joshua', 6, 14, 5, ' كما أمر الرب موسى هكذا فعل بنو إسرائيل وقسموا الأرض '),
(20827, 'Joshua', 6, 14, 6, ' فتقدم بنو يهوذا إلى يشوع في الجلجال . وقال له كالب بن يفنة القنزي : أنت تعلم الكلام الذي كلم به الرب موسى رجل الله من جهتي ومن جهتك في قادش برنيع '),
(20828, 'Joshua', 6, 14, 7, ' كنت ابن أربعين سنة حين أرسلني موسى عبد الرب من قادش برنيع لأتجسس الأرض . فرجعت إليه بكلام عما في قلبي '),
(20829, 'Joshua', 6, 14, 8, ' وأما إخوتي الذين صعدوا معي فأذابوا قلب الشعب . وأما أنا فاتبعت تماما الرب إلهي '),
(20830, 'Joshua', 6, 14, 9, ' فحلف موسى في ذلك اليوم قائلا : إن الأرض التي وطئتها رجلك لك تكون نصيبا ولأولادك إلى الأبد ، لأنك اتبعت الرب إلهي تماما '),
(20831, 'Joshua', 6, 14, 10, ' والآن فها قد استحياني الرب كما تكلم هذه الخمس والأربعين سنة ، من حين كلم الرب موسى بهذا الكلام حين سار إسرائيل في القفر . والآن فها أنا اليوم ابن خمس وثمانين سنة '),
(20832, 'Joshua', 6, 14, 11, ' فلم أزل اليوم متشددا كما في يوم أرسلني موسى . كما كانت قوتي حينئذ ، هكذا قوتي الآن للحرب وللخروج وللدخول '),
(20833, 'Joshua', 6, 14, 12, ' فالآن أعطني هذا الجبل الذي تكلم عنه الرب في ذلك اليوم . لأنك أنت سمعت في ذلك اليوم أن العناقيين هناك ، والمدن عظيمة محصنة . لعل الرب معي فأطردهم كما تكلم الرب '),
(20834, 'Joshua', 6, 14, 13, ' فباركه يشوع ، وأعطى حبرون لكالب بن يفنة ملكا '),
(20835, 'Joshua', 6, 14, 14, ' لذلك صارت حبرون لكالب بن يفنة القنزي ملكا إلى هذا اليوم ، لأنه اتبع تماما الرب إله إسرائيل '),
(20836, 'Joshua', 6, 14, 15, ' واسم حبرون قبلا قرية أربع ، الرجل الأعظم في العناقيين . واستراحت الأرض من الحرب '),
(20837, 'Joshua', 6, 15, 1, ' وكانت القرعة لسبط بني يهوذا حسب عشائرهم : إلى تخم أدوم برية صين نحو الجنوب ، أقصى التيمن '),
(20838, 'Joshua', 6, 15, 2, ' وكان تخمهم الجنوبي أقصى بحر الملح من اللسان المتوجه نحو الجنوب '),
(20839, 'Joshua', 6, 15, 3, ' وخرج إلى جنوب عقبة عقربيم وعبر إلى صين ، وصعد من جنوب قادش برنيع وعبر إلى حصرون ، وصعد إلى أدار إلى القرقع '),
(20840, 'Joshua', 6, 15, 4, ' وعبر إلى عصمون وخرج إلى وادي مصر . وكانت مخارج التخم عند البحر . هذا يكون تخمكم الجنوبي '),
(20841, 'Joshua', 6, 15, 5, ' وتخم الشرق بحر الملح إلى طرف الأردن . وتخم جانب الشمال من لسان البحر أقصى الأردن '),
(20842, 'Joshua', 6, 15, 6, ' وصعد التخم إلى بيت حجلة وعبر من شمال بيت العربة ، وصعد التخم إلى حجر بوهن بن رأوبين '),
(20843, 'Joshua', 6, 15, 7, ' وصعد التخم إلى دبير من وادي عخور وتوجه نحو الشمال إلى الجلجال التي مقابل عقبة أدميم التي من جنوبي الوادي . وعبر التخم إلى مياه عين شمس ، وكانت مخارجه إلى عين روجل '),
(20844, 'Joshua', 6, 15, 8, ' وصعد التخم في وادي ابن هنوم إلى جانب اليبوسي من الجنوب ، هي أورشليم . وصعد التخم إلى رأس الجبل الذي قبالة وادي هنوم غربا ، الذي هو في طرف وادي الرفائيين شمالا '),
(20845, 'Joshua', 6, 15, 9, ' وامتد التخم من رأس الجبل إلى منبع مياه نفتوح ، وخرج إلى مدن جبل عفرون وامتد التخم إلى بعلة ، هي قرية يعاريم '),
(20846, 'Joshua', 6, 15, 10, ' وامتد التخم من بعلة غربا إلى جبل سعير ، وعبر إلى جانب جبل يعاريم من الشمال ، هي كسالون . ونزل إلى بيت شمس وعبر إلى تمنة '),
(20847, 'Joshua', 6, 15, 11, ' وخرج التخم إلى جانب عقرون نحو الشمال وامتد التخم إلى شكرون وعبر جبل البعلة وخرج إلى يبنئيل . وكان مخارج التخم عند البحر '),
(20848, 'Joshua', 6, 15, 12, ' والتخم الغربي البحر الكبير وتخومه . هذا تخم بني يهوذا مستديرا حسب عشائرهم '),
(20849, 'Joshua', 6, 15, 13, ' وأعطى كالب بن يفنة قسما في وسط بني يهوذا حسب قول الرب ليشوع : قرية أربع أبي عناق ، هي حبرون '),
(20850, 'Joshua', 6, 15, 14, ' وطرد كالب من هناك بني عناق الثلاثة : شيشاي وأخيمان وتلماي ، أولاد عناق '),
(20851, 'Joshua', 6, 15, 15, ' وصعد من هناك إلى سكان دبير . وكان اسم دبير قبلا قرية سفر '),
(20852, 'Joshua', 6, 4, 14, ' في ذلك اليوم عظم الرب يشوع في أعين جميع إسرائيل ، فهابوه كما هابوا موسى كل أيام حياته '),
(20853, 'Joshua', 6, 4, 15, ' وكلم الرب يشوع قائلا '),
(20854, 'Joshua', 6, 4, 16, ' مر الكهنة حاملي تابوت الشهادة أن يصعدوا من الأردن '),
(20855, 'Joshua', 6, 4, 17, ' فأمر يشوع الكهنة قائلا : اصعدوا من الأردن '),
(20856, 'Joshua', 6, 4, 18, ' فكان لما صعد الكهنة حاملو تابوت عهد الرب من وسط الأردن ، واجتذبت بطون أقدام الكهنة إلى اليابسة ، أن مياه الأردن رجعت إلى مكانها وجرت كما من قبل إلى كل شطوطه '),
(20857, 'Joshua', 6, 4, 19, ' وصعد الشعب من الأردن في اليوم العاشر من الشهر الأول ، وحلوا في الجلجال في تخم أريحا الشرقي '),
(20858, 'Joshua', 6, 4, 20, ' والاثنا عشر حجرا التي أخذوها من الأردن نصبها يشوع في الجلجال '),
(20859, 'Joshua', 6, 4, 21, ' وكلم بني إسرائيل قائلا : إذا سأل بنوكم غدا آباءهم قائلين : ما هذه الحجارة '),
(20860, 'Joshua', 6, 4, 22, ' تعلمون بنيكم قائلين : على اليابسة عبر إسرائيل هذا الأردن '),
(20861, 'Joshua', 6, 4, 23, ' لأن الرب إلهكم قد يبس مياه الأردن من أمامكم حتى عبرتم ، كما فعل الرب إلهكم ببحر سوف الذي يبسه من أمامنا حتى عبرنا '),
(20862, 'Joshua', 6, 4, 24, ' لكي تعلم جميع شعوب الأرض يد الرب أنها قوية ، لكي تخافوا الرب إلهكم كل الأيام '),
(20863, 'Joshua', 6, 5, 1, ' وعندما سمع جميع ملوك الأموريين الذين في عبر الأردن غربا ، وجميع ملوك الكنعانيين الذين على البحر ، أن الرب قد يبس مياه الأردن من أمام بني إسرائيل حتى عبرنا ، ذابت قلوبهم ولم تبق فيهم روح بعد من جراء بني إسرائيل '),
(20864, 'Joshua', 6, 5, 2, ' في ذلك الوقت قال الرب ليشوع : اصنع لنفسك سكاكين من صوان ، وعد فاختن بني إسرائيل ثانية '),
(20865, 'Joshua', 6, 5, 3, ' فصنع يشوع سكاكين من صوان وختن بني إسرائيل في تل القلف '),
(20866, 'Joshua', 6, 5, 4, ' وهذا هو سبب ختن يشوع إياهم : أن جميع الشعب الخارجين من مصر ، الذكور ، جميع رجال الحرب ، ماتوا في البرية على الطريق بخروجهم من مصر '),
(20867, 'Joshua', 6, 5, 5, ' لأن جميع الشعب الذين خرجوا كانوا مختونين ، وأما جميع الشعب الذين ولدوا في القفر على الطريق بخروجهم من مصر فلم يختنوا '),
(20868, 'Joshua', 6, 5, 6, ' لأن بني إسرائيل ساروا أربعين سنة في القفر حتى فني جميع الشعب ، رجال الحرب الخارجين من مصر ، الذين لم يسمعوا لقول الرب ، الذين حلف الرب لهم أنه لا يريهم الأرض التي حلف الرب لآبائهم أن يعطينا إياها ، الأرض التي تفيض لبنا وعسلا '),
(20869, 'Joshua', 6, 5, 7, ' وأما بنوهم فأقامهم مكانهم . فإياهم ختن يشوع لأنهم كانوا قلفا ، إذ لم يختنوهم في الطريق '),
(20870, 'Joshua', 6, 5, 8, ' وكان بعدما انتهى جميع الشعب من الاختتان ، أنهم أقاموا في أماكنهم في المحلة حتى برئوا '),
(20871, 'Joshua', 6, 5, 9, ' وقال الرب ليشوع : اليوم قد دحرجت عنكم عار مصر . فدعي اسم ذلك المكان الجلجال إلى هذا اليوم '),
(20872, 'Joshua', 6, 5, 10, ' فحل بنو إسرائيل في الجلجال ، وعملوا الفصح في اليوم الرابع عشر من الشهر مساء في عربات أريحا '),
(20873, 'Joshua', 6, 5, 11, ' وأكلوا من غلة الأرض في الغد بعد الفصح فطيرا وفريكا في نفس ذلك اليوم '),
(20874, 'Joshua', 6, 5, 12, ' وانقطع المن في الغد عند أكلهم من غلة الأرض ، ولم يكن بعد لبني إسرائيل من . فأكلوا من محصول أرض كنعان في تلك السنة '),
(20875, 'Joshua', 6, 5, 13, ' وحدث لما كان يشوع عند أريحا أنه رفع عينيه ونظر ، وإذا برجل واقف قبالته ، وسيفه مسلول بيده . فسار يشوع إليه وقال له : هل لنا أنت أو لأعدائنا '),
(20876, 'Joshua', 6, 5, 14, ' فقال : كلا ، بل أنا رئيس جند الرب . الآن أتيت . فسقط يشوع على وجهه إلى الأرض وسجد ، وقال له : بماذا يكلم سيدي عبده '),
(20877, 'Joshua', 6, 5, 15, ' فقال رئيس جند الرب ليشوع : اخلع نعلك من رجلك ، لأن المكان الذي أنت واقف عليه هو مقدس . ففعل يشوع كذلك '),
(20878, 'Joshua', 6, 6, 1, ' وكانت أريحا مغلقة مقفلة بسبب بني إسرائيل . لا أحد يخرج ولا أحد يدخل '),
(20879, 'Joshua', 6, 6, 2, ' فقال الرب ليشوع : انظر . قد دفعت بيدك أريحا وملكها ، جبابرة البأس '),
(20880, 'Joshua', 6, 6, 3, ' تدورون دائرة المدينة ، جميع رجال الحرب . حول المدينة مرة واحدة . هكذا تفعلون ستة أيام '),
(20881, 'Joshua', 6, 6, 4, ' وسبعة كهنة يحملون أبواق الهتاف السبعة أمام التابوت . وفي اليوم السابع تدورون دائرة المدينة سبع مرات ، والكهنة يضربون بالأبواق '),
(20882, 'Joshua', 6, 6, 5, ' ويكون عند امتداد صوت قرن الهتاف ، عند استماعكم صوت البوق ، أن جميع الشعب يهتف هتافا عظيما ، فيسقط سور المدينة في مكانه ، ويصعد الشعب كل رجل مع وجهه '),
(20883, 'Joshua', 6, 6, 6, ' فدعا يشوع بن نون الكهنة وقال لهم : احملوا تابوت العهد . وليحمل سبعة كهنة سبعة أبواق هتاف أمام تابوت الرب '),
(20884, 'Joshua', 6, 6, 7, ' وقالوا للشعب : اجتازوا ودوروا دائرة المدينة ، وليجتز المتجرد أمام تابوت الرب '),
(20885, 'Joshua', 6, 6, 8, ' وكان كما قال يشوع للشعب . اجتاز السبعة الكهنة حاملين أبواق الهتاف السبعة أمام الرب ، وضربوا بالأبواق . وتابوت عهد الرب سائر وراءهم '),
(20886, 'Joshua', 6, 6, 9, ' وكل متجرد سائر أمام الكهنة الضاربين بالأبواق . والساقة سائرة وراء التابوت . كانوا يسيرون ويضربون بالأبواق '),
(20887, 'Joshua', 6, 6, 10, ' وأمر يشوع الشعب قائلا : لا تهتفوا ولا تسمعوا صوتكم ، ولا تخرج من أفواهكم كلمة حتى يوم أقول لكم : اهتفوا . فتهتفون '),
(20888, 'Joshua', 6, 6, 11, ' فدار تابوت الرب حول المدينة مرة واحدة . ثم دخلوا المحلة وباتوا في المحلة '),
(20889, 'Joshua', 6, 6, 12, ' فبكر يشوع في الغد ، وحمل الكهنة تابوت الرب '),
(20890, 'Joshua', 6, 6, 13, ' والسبعة الكهنة الحاملون أبواق الهتاف السبعة أمام تابوت الرب سائرون سيرا وضاربون بالأبواق ، والمتجردون سائرون أمامهم ، والساقة سائرة وراء تابوت الرب . كانوا يسيرون ويضربون بالأبواق '),
(20891, 'Joshua', 6, 6, 14, ' وداروا بالمدينة في اليوم الثاني مرة واحدة ، ثم رجعوا إلى المحلة . هكذا فعلوا ستة أيام '),
(20892, 'Joshua', 6, 6, 15, ' وكان في اليوم السابع أنهم بكروا عند طلوع الفجر وداروا دائرة المدينة على هذا المنوال سبع مرات . في ذلك اليوم فقط داروا دائرة المدينة سبع مرات '),
(20893, 'Joshua', 6, 6, 16, ' وكان في المرة السابعة عندما ضرب الكهنة بالأبواق أن يشوع قال للشعب : اهتفوا ، لأن الرب قد أعطاكم المدينة '),
(20894, 'Joshua', 6, 6, 17, ' فتكون المدينة وكل ما فيها محرما للرب . راحاب الزانية فقط تحيا هي وكل من معها في البيت ، لأنها قد خبأت المرسلين اللذين أرسلناهما '),
(20895, 'Joshua', 6, 6, 18, ' وأما أنتم فاحترزوا من الحرام لئلا تحرموا ، وتأخذوا من الحرام وتجعلوا محلة إسرائيل محرمة وتكدروها '),
(20896, 'Joshua', 6, 6, 19, ' وكل الفضة والذهب وآنية النحاس والحديد تكون قدسا للرب وتدخل في خزانة الرب '),
(20897, 'Joshua', 6, 6, 20, ' فهتف الشعب وضربوا بالأبواق . وكان حين سمع الشعب صوت البوق أن الشعب هتف هتافا عظيما ، فسقط السور في مكانه ، وصعد الشعب إلى المدينة كل رجل مع وجهه ، وأخذوا المدينة '),
(20898, 'Joshua', 6, 6, 21, ' وحرموا كل ما في المدينة من رجل وامرأة ، من طفل وشيخ ، حتى البقر والغنم والحمير بحد السيف '),
(20899, 'Joshua', 6, 6, 22, ' وقال يشوع للرجلين اللذين تجسسا الأرض : ادخلا بيت المرأة الزانية وأخرجا من هناك المرأة وكل ما لها كما حلفتما لها '),
(20900, 'Joshua', 6, 6, 23, ' فدخل الغلامان الجاسوسان وأخرجا راحاب وأباها وأمها وإخوتها وكل ما لها ، وأخرجا كل عشائرها وتركاهم خارج محلة إسرائيل '),
(20901, 'Joshua', 6, 6, 24, ' وأحرقوا المدينة بالنار مع كل ما بها ، إنما الفضة والذهب وآنية النحاس والحديد جعلوها في خزانة بيت الرب '),
(20902, 'Joshua', 6, 6, 25, ' واستحيا يشوع راحاب الزانية وبيت أبيها وكل ما لها ، وسكنت في وسط إسرائيل إلى هذا اليوم ، لأنها خبأت المرسلين اللذين أرسلهما يشوع لكي يتجسسا أريحا '),
(20903, 'Joshua', 6, 6, 26, ' وحلف يشوع في ذلك الوقت قائلا : ملعون قدام الرب الرجل الذي يقوم ويبني هذه المدينة أريحا . ببكره يؤسسها وبصغيره ينصب أبوابها '),
(20904, 'Joshua', 6, 6, 27, ' وكان الرب مع يشوع ، وكان خبره في جميع الأرض '),
(20905, 'Joshua', 6, 7, 1, ' وخان بنو إسرائيل خيانة في الحرام ، فأخذ عخان بن كرمي بن زبدي بن زارح من سبط يهوذا من الحرام ، فحمي غضب الرب على بني إسرائيل '),
(20906, 'Joshua', 6, 7, 2, ' وأرسل يشوع رجالا من أريحا إلى عاي التي عند بيت آون شرقي بيت إيل ، وكلمهم قائلا : اصعدوا تجسسوا الأرض . فصعد الرجال وتجسسوا عاي '),
(20907, 'Joshua', 6, 7, 3, ' ثم رجعوا إلى يشوع وقالوا له : لا يصعد كل الشعب ، بل يصعد نحو ألفي رجل أو ثلاثة آلاف رجل ويضربوا عاي . لا تكلف كل الشعب إلى هناك لأنهم قليلون '),
(20908, 'Joshua', 6, 7, 4, ' فصعد من الشعب إلى هناك نحو ثلاثة آلاف رجل ، وهربوا أمام أهل عاي '),
(20909, 'Joshua', 6, 7, 5, ' فضرب منهم أهل عاي نحو ستة وثلاثين رجلا ، ولحقوهم من أمام الباب إلى شباريم وضربوهم في المنحدر . فذاب قلب الشعب وصار مثل الماء '),
(20910, 'Joshua', 6, 7, 6, ' فمزق يشوع ثيابه وسقط على وجهه إلى الأرض أمام تابوت الرب إلى المساء ، هو وشيوخ إسرائيل ، ووضعوا ترابا على رؤوسهم '),
(20911, 'Joshua', 6, 7, 7, ' وقال يشوع : آه يا سيد الرب لماذا عبرت هذا الشعب الأردن تعبيرا لكي تدفعنا إلى يد الأموريين ليبيدونا ؟ ليتنا ارتضينا وسكنا في عبر الأردن '),
(20912, 'Joshua', 6, 7, 8, ' أسألك يا سيد : ماذا أقول بعدما حول إسرائيل قفاه أمام أعدائه '),
(20913, 'Joshua', 6, 7, 9, ' فيسمع الكنعانيون وجميع سكان الأرض ويحيطون بنا ويقرضون اسمنا من الأرض . وماذا تصنع لاسمك العظيم '),
(20914, 'Joshua', 6, 7, 10, ' فقال الرب ليشوع : قم لماذا أنت ساقط على وجهك '),
(20915, 'Joshua', 6, 7, 11, ' قد أخطأ إسرائيل ، بل تعدوا عهدي الذي أمرتهم به ، بل أخذوا من الحرام ، بل سرقوا ، بل أنكروا ، بل وضعوا في أمتعتهم '),
(20916, 'Joshua', 6, 7, 12, ' فلم يتمكن بنو إسرائيل للثبوت أمام أعدائهم . يديرون قفاهم أمام أعدائهم لأنهم محرومون ، ولا أعود أكون معكم إن لم تبيدوا الحرام من وسطكم '),
(20917, 'Joshua', 6, 7, 13, ' قم قدس الشعب وقل : تقدسوا للغد . لأنه هكذا قال الرب إله إسرائيل : في وسطك حرام يا إسرائيل ، فلا تتمكن للثبوت أمام أعدائك حتى تنزعوا الحرام من وسطكم '),
(20918, 'Joshua', 6, 7, 14, ' فتتقدمون في الغد بأسباطكم ، ويكون أن السبط الذي يأخذه الرب يتقدم بعشائره ، والعشيرة التي يأخذها الرب تتقدم ببيوتها ، والبيت الذي يأخذه الرب يتقدم برجاله '),
(20919, 'Joshua', 6, 7, 15, ' ويكون المأخوذ بالحرام يحرق بالنار هو وكل ما له ، لأنه تعدى عهد الرب ، ولأنه عمل قباحة في إسرائيل '),
(20920, 'Joshua', 6, 7, 16, ' فبكر يشوع في الغد وقدم إسرائيل بأسباطه ، فأخذ سبط يهوذا '),
(20921, 'Joshua', 6, 7, 17, ' ثم قدم قبيلة يهوذا فأخذت عشيرة الزارحيين . ثم قدم عشيرة الزارحيين برجالهم فأخذ زبدي '),
(20922, 'Joshua', 6, 7, 18, ' فقدم بيته برجاله فأخذ عخان بن كرمي بن زبدي بن زارح من سبط يهوذا '),
(20923, 'Joshua', 6, 7, 19, ' فقال يشوع لعخان : يا ابني ، أعط الآن مجدا للرب إله إسرائيل ، واعترف له وأخبرني الآن ماذا عملت . لا تخف عني '),
(20924, 'Joshua', 6, 7, 20, ' فأجاب عخان يشوع وقال : حقا إني قد أخطأت إلى الرب إله إسرائيل وصنعت كذا وكذا '),
(20925, 'Joshua', 6, 7, 21, ' رأيت في الغنيمة رداء شنعاريا نفيسا ، ومئتي شاقل فضة ، ولسان ذهب وزنه خمسون شاقلا ، فاشتهيتها وأخذتها . وها هي مطمورة في الأرض في وسط خيمتي ، والفضة تحتها '),
(20926, 'Joshua', 6, 16, 4, ' فملك ابنا يوسف منسى وأفرايم '),
(20927, 'Joshua', 6, 16, 5, ' وكان تخم بني أفرايم حسب عشائرهم . وكان تخم نصيبهم شرقا : عطاروت أدار إلى بيت حورون العليا '),
(20928, 'Joshua', 6, 16, 6, ' وخرج التخم نحو البحر إلى المكمتة شمالا ، ودار التخم شرقا إلى تآنة شيلوه وعبرها شرقي ينوحة '),
(20929, 'Joshua', 6, 16, 7, ' ونزل من ينوحة إلى عطاروت ونعرات ووصل إلى أريحا وخرج إلى الأردن '),
(20930, 'Joshua', 6, 16, 8, ' وجاز التخم من تفوح غربا إلى وادي قانة ، وكانت مخارجه عند البحر '),
(20931, 'Joshua', 6, 16, 9, ' هذا هو نصيب سبط بني أفرايم حسب عشائرهم مع المدن المفرزة لبني أفرايم في وسط نصيب بني منسى . جميع المدن وضياعها '),
(20932, 'Joshua', 6, 16, 10, ' فلم يطردوا الكنعانيين الساكنين في جازر . فسكن الكنعانيون في وسط أفرايم إلى هذا اليوم ، وكانوا عبيدا تحت الجزية '),
(20933, 'Joshua', 6, 17, 1, ' وكانت القرعة لسبط منسى ، لأنه هو بكر يوسف . لماكير بكر منسى أبي جلعاد ، لأنه كان رجل حرب ، وكانت جلعاد وباشان له '),
(20934, 'Joshua', 6, 17, 2, ' وكانت لبني منسى الباقين حسب عشائرهم . لبني أبيعزر ولبني حالق ، ولبني أسريئيل ، ولبني شكم ، ولبني حافر ، ولبني شميداع ، هؤلاء هم بنو منسى بن يوسف ، الذكور حسب عشائرهم '),
(20935, 'Joshua', 6, 17, 3, ' وأما صلفحاد بن حافر بن جلعاد بن ماكير بن منسى فلم يكن له بنون بل بنات . وهذه أسماء بناته : محلة ونوعة وحجلة وملكة وترصة '),
(20936, 'Joshua', 6, 17, 4, ' فتقدمن أمام ألعازار الكاهن وأمام يشوع بن نون وأمام الرؤساء وقلن : الرب أمر موسى أن يعطينا نصيبا بين إخوتنا . فأعطاهن حسب قول الرب نصيبا بين إخوة أبيهن '),
(20937, 'Joshua', 6, 17, 5, ' فأصاب منسى عشر حصص ، ما عدا أرض جلعاد وباشان التي في عبر الأردن '),
(20938, 'Joshua', 6, 17, 6, ' لأن بنات منسى أخذن نصيبا بين بنيه ، وكانت أرض جلعاد لبني منسى الباقين '),
(20939, 'Joshua', 6, 17, 7, ' وكان تخم منسى من أشير إلى المكمتة التي مقابل شكيم ، وامتد التخم نحو اليمين إلى سكان عين تفوح '),
(20940, 'Joshua', 6, 17, 8, ' كان لمنسى أرض تفوح . وأما تفوح إلى تخم منسى هي لبني أفرايم '),
(20941, 'Joshua', 6, 17, 9, ' ونزل التخم إلى وادي قانة جنوبي الوادي . هذه مدن أفرايم بين مدن منسى . وتخم منسى شمالي الوادي ، وكانت مخارجه عند البحر '),
(20942, 'Joshua', 6, 17, 10, ' من الجنوب لأفرايم ، ومن الشمال لمنسى . وكان البحر تخمه . ووصل إلى أشير شمالا ، وإلى يساكر نحو الشروق '),
(20943, 'Joshua', 6, 17, 11, ' وكان لمنسى في يساكر وفي أشير بيت شان وقراها ، ويبلعام وقراها ، وسكان دور وقراها ، وسكان عين دور وقراها ، وسكان تعنك وقراها ، وسكان مجدو وقراها المرتفعات الثلاث '),
(20944, 'Joshua', 6, 17, 12, ' ولم يقدر بنو منسى أن يملكوا هذه المدن ، فعزم الكنعانيون على السكن في تلك الأرض '),
(20945, 'Joshua', 6, 17, 13, ' وكان لما تشدد بنو إسرائيل أنهم جعلوا الكنعانيين تحت الجزية ، ولم يطردوهم طردا '),
(20946, 'Joshua', 6, 17, 14, ' وكلم بنو يوسف يشوع قائلين : لماذا أعطيتني قرعة واحدة وحصة واحدة نصيبا وأنا شعب عظيم ، لأنه إلى الآن قد باركني الرب '),
(20947, 'Joshua', 6, 17, 15, ' فقال لهم يشوع : إن كنت شعبا عظيما ، فاصعد إلى الوعر واقطع لنفسك هناك في أرض الفرزيين والرفائيين ، إذا ضاق عليك جبل أفرايم '),
(20948, 'Joshua', 6, 17, 16, ' فقال بنو يوسف : لا يكفينا الجبل . ولجميع الكنعانيين الساكنين في أرض الوادي مركبات حديد . للذين في بيت شان وقراها ، وللذين في وادي يزرعيل '),
(20949, 'Joshua', 6, 17, 17, ' فكلم يشوع بيت يوسف ، أفرايم ومنسى ، قائلا : أنت شعب عظيم ولك قوة عظيمة ، لا تكون لك قرعة واحدة '),
(20950, 'Joshua', 6, 17, 18, ' بل يكون لك الجبل لأنه وعر ، فتقطعه وتكون لك مخارجه . فتطرد الكنعانيين لأن لهم مركبات حديد لأنهم أشداء '),
(20951, 'Joshua', 6, 18, 1, ' واجتمع كل جماعة بني إسرائيل في شيلوه ونصبوا هناك خيمة الاجتماع ، وأخضعت الأرض قدامهم '),
(20952, 'Joshua', 6, 18, 2, ' وبقي من بني إسرائيل ممن لم يقسموا نصيبهم ، سبعة أسباط '),
(20953, 'Joshua', 6, 18, 3, ' فقال يشوع لبني إسرائيل : حتى متى أنتم متراخون عن الدخول لامتلاك الأرض التي أعطاكم إياها الرب إله آبائكم '),
(20954, 'Joshua', 6, 18, 4, ' هاتوا ثلاثة رجال من كل سبط فأرسلهم فيقوموا ويسيروا في الأرض ويكتبوها بحسب أنصبتهم ، ثم يأتوا إلي '),
(20955, 'Joshua', 6, 18, 5, ' وليقسموها إلى سبعة أقسام ، فيقيم يهوذا على تخمه من الجنوب ، ويقيم بيت يوسف على تخمهم من الشمال '),
(20956, 'Joshua', 6, 18, 6, ' وأنتم تكتبون الأرض سبعة أقسام ، ثم تأتون إلي هنا فألقي لكم قرعة ههنا أمام الرب إلهنا '),
(20957, 'Joshua', 6, 18, 7, ' لأنه ليس للاويين قسم في وسطكم ، لأن كهنوت الرب هو نصيبهم . وجاد ورأوبين ونصف سبط منسى قد أخذوا نصيبهم في عبر الأردن نحو الشروق ، الذي أعطاهم إياه موسى عبد الرب '),
(20958, 'Joshua', 6, 18, 8, ' فقام الرجال وذهبوا . وأوصى يشوع الذاهبين لكتابة الأرض قائلا : اذهبوا وسيروا في الأرض واكتبوها ، ثم ارجعوا إلي فألقي لكم هنا قرعة أمام الرب في شيلوه '),
(20959, 'Joshua', 6, 18, 9, ' فسار الرجال وعبروا في الأرض وكتبوها حسب المدن سبعة أقسام في سفر ، ثم جاءوا إلى يشوع إلى المحلة في شيلوه '),
(20960, 'Joshua', 6, 18, 10, ' فألقى لهم يشوع قرعة في شيلوه أمام الرب ، وهناك قسم يشوع الأرض لبني إسرائيل حسب فرقهم '),
(20961, 'Joshua', 6, 18, 11, ' وطلعت قرعة سبط بني بنيامين حسب عشائرهم ، وخرج تخم قرعتهم بين بني يهوذا وبني يوسف '),
(20962, 'Joshua', 6, 18, 12, ' وكان تخمهم من جهة الشمال من الأردن . وصعد التخم إلى جانب أريحا من الشمال وصعد في الجبل غربا ، وكانت مخارجه عند برية بيت آون '),
(20963, 'Joshua', 6, 18, 13, ' وعبر التخم من هناك إلى لوز ، إلى جانب لوز الجنوبي ، هي بيت إيل ، ونزل التخم إلى عطاروت إدار على الجبل الذي إلى جنوب بيت حورون السفلى '),
(20964, 'Joshua', 6, 18, 14, ' وامتد التخم ودار إلى جهة الغرب جنوبا من الجبل الذي مقابل بيت حورون جنوبا . وكانت مخارجه عند قرية بعل ، هي قرية يعاريم . مدينة لبني يهوذا . هذه هي جهة الغرب '),
(20965, 'Joshua', 6, 18, 15, ' وجهة الجنوب هي أقصى قرية يعاريم . وخرج التخم غربا وخرج إلى منبع مياه نفتوح '),
(20966, 'Joshua', 6, 18, 16, ' ونزل التخم إلى طرف الجبل الذي مقابل وادي ابن هنوم الذي في وادي الرفائيين شمالا ، ونزل إلى وادي هنوم إلى جانب اليبوسيين من الجنوب ، ونزل إلى عين روجل '),
(20967, 'Joshua', 6, 18, 17, ' وامتد من الشمال وخرج إلى عين شمس ، وخرج إلى جليلوت التي مقابل عقبة أدميم ، ونزل إلى حجر بوهن بن رأوبين '),
(20968, 'Joshua', 6, 18, 18, ' وعبر إلى الكتف مقابل العربة شمالا ، ونزل إلى العربة '),
(20969, 'Joshua', 6, 18, 19, ' وعبر التخم إلى جانب بيت حجلة شمالا . وكانت مخارج التخم عند لسان بحر الملح شمالا إلى طرف الأردن جنوبا . هذا هو تخم الجنوب '),
(20970, 'Joshua', 6, 18, 20, ' والأردن يتخمه من جهة الشرق . فهذا هو نصيب بني بنيامين مع تخومه مستديرا حسب عشائرهم '),
(20971, 'Joshua', 6, 18, 21, ' وكانت مدن سبط بني بنيامين حسب عشائرهم : أريحا وبيت حجلة ووادي قصيص '),
(20972, 'Joshua', 6, 18, 22, ' وبيت العربة وصمارايم وبيت إيل '),
(20973, 'Joshua', 6, 18, 23, ' والعويم والفارة وعفرة '),
(20974, 'Joshua', 6, 18, 24, ' وكفر العموني والعفني وجبع ، ست عشرة مدينة مع ضياعها '),
(20975, 'Joshua', 6, 18, 25, ' جبعون والرامة وبئيروت '),
(20976, 'Joshua', 6, 18, 26, ' والمصفاة والكفيرة والموصة '),
(20977, 'Joshua', 6, 18, 27, ' وراقم ويرفئيل وترالة '),
(20978, 'Joshua', 6, 18, 28, ' وصيلع وآلف واليبوسي ، هي أورشليم ، وجبعة وقرية . أربع عشرة مدينة مع ضياعها . هذا هو نصيب بني بنيامين حسب عشائرهم '),
(20979, 'Joshua', 6, 19, 1, ' وخرجت القرعة الثانية لشمعون ، لسبط بني شمعون حسب عشائرهم ، وكان نصيبهم داخل نصيب بني يهوذا '),
(20980, 'Joshua', 6, 19, 2, ' فكان لهم في نصيبهم : بئر سبع وشبع ومولادة '),
(20981, 'Joshua', 6, 19, 3, ' وحصر شوعال وبالة وعاصم '),
(20982, 'Joshua', 6, 19, 4, ' وألتولد وبتول وحرمة '),
(20983, 'Joshua', 6, 19, 5, ' وصقلغ وبيت المركبوت وحصر سوسة '),
(20984, 'Joshua', 6, 19, 6, ' وبيت لباوت وشاروحين . ثلاث عشرة مدينة مع ضياعها '),
(20985, 'Joshua', 6, 19, 7, ' عين ورمون وعاتر وعاشان . أربع مدن مع ضياعها '),
(20986, 'Joshua', 6, 19, 8, ' وجميع الضياع التي حوالي هذه المدن إلى بعلة بئر رامة الجنوب . هذا هو نصيب سبط بني شمعون حسب عشائرهم '),
(20987, 'Joshua', 6, 19, 9, ' ومن قسم بني يهوذا كان نصيب بني شمعون . لأن قسم بني يهوذا كان كثيرا عليهم ، فملك بنو شمعون داخل نصيبهم '),
(20988, 'Joshua', 6, 19, 10, ' وطلعت القرعة الثالثة لبني زبولون حسب عشائرهم . وكان تخم نصيبهم إلى ساريد '),
(20989, 'Joshua', 6, 19, 11, ' وصعد تخمهم نحو الغرب ومرعلة ، ووصل إلى دباشة ، ووصل إلى الوادي الذي مقابل يقنعام '),
(20990, 'Joshua', 6, 19, 12, ' ودار من ساريد شرقا نحو شروق الشمس على تخم كسلوت تابور ، وخرج إلى الدبرة وصعد إلى يافيع '),
(20991, 'Joshua', 6, 19, 13, ' ومن هناك عبر شرقا نحو الشروق إلى جت حافر إلى عت قاصين ، وخرج إلى رمون وامتد إلى نيعة '),
(20992, 'Joshua', 6, 21, 22, ' وقبصايم ومسرحها ، وبيت حورون ومسرحها . أربع مدن '),
(20993, 'Joshua', 6, 21, 23, ' ومن سبط دان إلتقى ومسرحها ، وجبثون ومسرحها '),
(20994, 'Joshua', 6, 21, 24, ' وأيلون ومسرحها ، وجت رمون ومسرحها . أربع مدن '),
(20995, 'Joshua', 6, 21, 25, ' ومن نصف سبط منسى تعنك ومسرحها ، وجت رمون ومسرحها . مدينتين اثنتين '),
(20996, 'Joshua', 6, 21, 26, ' كل المدن عشر مع مسارحها لعشائر بني قهات الباقين '),
(20997, 'Joshua', 6, 21, 27, ' ولبني جرشون من عشائر اللاويين : مدينة ملجإ القاتل من نصف سبط منسى جولان في باشان ومسرحها ، وبعشترة ومسرحها ، مدينتان ثنتان '),
(20998, 'Joshua', 6, 21, 28, ' ومن سبط يساكر : قشيون ومسرحها ، ودبرة ومسرحها '),
(20999, 'Joshua', 6, 21, 29, ' ويرموت ومسرحها ، وعين جنيم ومسرحها . أربع مدن '),
(21000, 'Joshua', 6, 21, 30, ' ومن سبط أشير مشآل ومسرحها ، وعبدون ومسرحها '),
(21001, 'Joshua', 6, 21, 31, ' وحلقة ومسرحها ، ورحوب ومسرحها ،  . أربع مدن '),
(21002, 'Joshua', 6, 21, 32, ' ومن سبط نفتالي مدينة ملجإ القاتل قادش في الجليل ومسرحها ، وحموت دور ومسرحها ، وقرتان ومسرحها ،  . ثلاث مدن '),
(21003, 'Joshua', 6, 21, 33, ' جميع مدن الجرشونيين حسب عشائرهم ثلاث عشرة مدينة مع مسارحها '),
(21004, 'Joshua', 6, 21, 34, ' ولعشائر بني مراري اللاويين الباقين من سبط زبولون يقنعام ومسرحها ، وقرتة ومسرحها '),
(21005, 'Joshua', 6, 21, 35, ' ودمنة ومسرحها ، ونحلال ومسرحها ،  . أربع مدن '),
(21006, 'Joshua', 6, 21, 36, ' ومن سبط رأوبين باصر ومسرحها ، ويهصة ومسرحها '),
(21007, 'Joshua', 6, 21, 37, ' وقديموت ومسرحها ، وميفعة ومسرحها ،  . أربع مدن '),
(21008, 'Joshua', 6, 21, 38, ' ومن سبط جاد مدينة ملجإ القاتل راموت في جلعاد ومسرحها ، ومحنايم ومسرحها '),
(21009, 'Joshua', 6, 21, 39, ' حشبون ومسرحها ، ويعزير ومسرحها . كل المدن أربع '),
(21010, 'Joshua', 6, 21, 40, ' فجميع المدن التي لبني مراري حسب عشائرهم الباقين من عشائر اللاويين . وكانت قرعتهم اثنتا عشرة مدينة '),
(21011, 'Joshua', 6, 21, 41, ' جميع مدن اللاويين في وسط ملك بني إسرائيل ثمان وأربعون مدينة مع مسارحها '),
(21012, 'Joshua', 6, 21, 42, ' كانت هذه المدن مدينة مدينة مع مسارحها حواليها . هكذا لكل هذه المدن '),
(21013, 'Joshua', 6, 21, 43, ' فأعطى الرب إسرائيل جميع الأرض التي أقسم أن يعطيها لآبائهم فامتلكوها وسكنوا بها '),
(21014, 'Joshua', 6, 21, 44, ' فأراحهم الرب حواليهم حسب كل ما أقسم لآبائهم ، ولم يقف قدامهم رجل من جميع أعدائهم ، بل دفع الرب جميع أعدائهم بأيديهم '),
(21015, 'Joshua', 6, 21, 45, ' لم تسقط كلمة من جميع الكلام الصالح الذي كلم به الرب بيت إسرائيل ، بل الكل صار '),
(21016, 'Joshua', 6, 22, 1, ' حينئذ دعا يشوع الرأوبينيين والجاديين ونصف سبط منسى '),
(21017, 'Joshua', 6, 22, 2, ' وقال لهم : إنكم قد حفظتم كل ما أمركم به موسى عبد الرب ، وسمعتم صوتي في كل ما أمرتكم به '),
(21018, 'Joshua', 6, 22, 3, ' ولم تتركوا إخوتكم هذه الأيام الكثيرة إلى هذا اليوم ، وحفظتم ما يحفظ ، وصية الرب إلهكم '),
(21019, 'Joshua', 6, 22, 4, ' والآن قد أراح الرب إلهكم إخوتكم كما قال لهم . فانصرفوا الآن واذهبوا إلى خيامكم في أرض ملككم التي أعطاكم موسى عبد الرب ، في عبر الأردن '),
(21020, 'Joshua', 6, 22, 5, ' وإنما احرصوا جدا أن تعملوا الوصية والشريعة التي أمركم بها موسى عبد الرب : أن تحبوا الرب إلهكم ، وتسيروا في كل طرقه ، وتحفظوا وصاياه ، وتلصقوا به وتعبدوه بكل قلبكم وبكل نفسكم '),
(21021, 'Joshua', 6, 22, 6, ' ثم باركهم يشوع وصرفهم ، فذهبوا إلى خيامهم '),
(21022, 'Joshua', 6, 22, 7, ' ولنصف سبط منسى أعطى موسى في باشان ، وأما نصفه الآخر فأعطاهم يشوع مع إخوتهم في عبر الأردن غربا . وعندما صرفهم يشوع أيضا إلى خيامهم باركهم '),
(21023, 'Joshua', 6, 22, 8, ' وكلمهم قائلا : بمال كثير ارجعوا إلى خيامكم ، وبمواش كثيرة جدا ، بفضة وذهب ونحاس وحديد وملابس كثيرة جدا . اقسموا غنيمة أعدائكم مع إخوتكم '),
(21024, 'Joshua', 6, 22, 9, ' فرجع بنو رأوبين وبنو جاد ونصف سبط منسى ، وذهبوا من عند بني إسرائيل من شيلوه التي في أرض كنعان لكي يسيروا إلى أرض جلعاد ، أرض ملكهم التي تملكوا بها حسب قول الرب على يد موسى '),
(21025, 'Joshua', 6, 22, 10, ' وجاءوا إلى دائرة الأردن التي في أرض كنعان . وبنى بنو رأوبين وبنو جاد ونصف سبط منسى هناك مذبحا على الأردن ، مذبحا عظيم المنظر '),
(21026, 'Joshua', 6, 22, 11, ' فسمع بنو إسرائيل قولا : هوذا قد بنى بنو رأوبين وبنو جاد ونصف سبط منسى مذبحا في وجه أرض كنعان ، في دائرة الأردن مقابل بني إسرائيل '),
(21027, 'Joshua', 6, 22, 12, ' ولما سمع بنو إسرائيل اجتمعت كل جماعة بني إسرائيل في شيلوه لكي يصعدوا إليهم للحرب '),
(21028, 'Joshua', 6, 22, 13, ' فأرسل بنو إسرائيل إلى بني رأوبين وبني جاد ونصف سبط منسى إلى أرض جلعاد ، فينحاس بن ألعازار الكاهن '),
(21029, 'Joshua', 6, 22, 14, ' وعشرة رؤساء معه ، رئيسا واحدا من كل بيت أب من جميع أسباط إسرائيل ، كل واحد رئيس بيت آبائهم في ألوف إسرائيل '),
(21030, 'Joshua', 6, 22, 15, ' فجاءوا إلى بني رأوبين وبني جاد ونصف سبط منسى إلى أرض جلعاد ، وكلموهم قائلين ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(21031, 'Joshua', 6, 22, 16, ' هكذا قالت كل جماعة الرب : ما هذه الخيانة التي خنتم بها إله إسرائيل ، بالرجوع اليوم عن الرب ، ببنيانكم لأنفسكم مذبحا لتتمردوا اليوم على الرب '),
(21032, 'Joshua', 6, 22, 17, ' أقليل لنا إثم فغور الذي لم نتطهر منه إلى هذا اليوم ، وكان الوبأ في جماعة الرب '),
(21033, 'Joshua', 6, 22, 18, ' حتى ترجعوا أنتم اليوم عن الرب ؟ فيكون أنكم اليوم تتمردون على الرب ، وهو غدا يسخط على كل جماعة إسرائيل '),
(21034, 'Joshua', 6, 22, 19, ' ولكن إذا كانت نجسة أرض ملككم فاعبروا إلى أرض ملك الرب التي يسكن فيها مسكن الرب وتملكوا بيننا ، وعلى الرب لا تتمردوا ، وعلينا لا تتمردوا ببنائكم لأنفسكم مذبحا غير مذبح الرب إلهنا '),
(21035, 'Joshua', 6, 22, 20, ' أما خان عخان بن زارح خيانة في الحرام ، فكان السخط على كل جماعة إسرائيل ، وهو رجل لم يهلك وحده بإثمه '),
(21036, 'Joshua', 6, 22, 21, ' فأجاب بنو رأوبين وبنو جاد ونصف سبط منسى وقالوا لرؤساء ألوف إسرائيل '),
(21037, 'Joshua', 6, 22, 22, ' إله الآلهة الرب ، إله الآلهة الرب هو يعلم ، وإسرائيل سيعلم . إن كان بتمرد وإن كان بخيانة على الرب ، لا تخلصنا هذا اليوم '),
(21038, 'Joshua', 6, 22, 23, ' بنياننا لأنفسنا مذبحا للرجوع عن الرب ، أو لإصعاد محرقة عليه أو تقدمة أو لعمل ذبائح سلامة عليه ، فالرب هو يطالب '),
(21039, 'Joshua', 6, 22, 24, ' وإن كنا لم نفعل ذلك خوفا وعن سبب قائلين : غدا يكلم بنوكم بنينا قائلين : ما لكم وللرب إله إسرائيل '),
(21040, 'Joshua', 6, 22, 25, ' قد جعل الرب تخما بيننا وبينكم يا بني رأوبين وبني جاد : الأردن . ليس لكم قسم في الرب . فيرد بنوكم بنينا حتى لا يخافوا الرب '),
(21041, 'Joshua', 6, 22, 26, ' فقلنا نصنع نحن لأنفسنا . نبني مذبحا ، لا للمحرقة ولا للذبيحة '),
(21042, 'Joshua', 6, 22, 27, ' بل ليكون هو شاهدا بيننا وبينكم وبين أجيالنا بعدنا ، لكي نخدم خدمة الرب أمامه بمحرقاتنا وذبائحنا وذبائح سلامتنا ، ولا يقول بنوكم غدا لبنينا : ليس لكم قسم في الرب '),
(21043, 'Joshua', 6, 22, 28, ' وقلنا : يكون متى قالوا كذا لنا ولأجيالنا غدا ، أننا نقول : انظروا شبه مذبح الرب الذي عمل آباؤنا ، لا للمحرقة ولا للذبيحة ، بل هو شاهد بيننا وبينكم '),
(21044, 'Joshua', 6, 22, 29, ' حاشا لنا منه أن نتمرد على الرب ونرجع اليوم عن الرب لبناء مذبح للمحرقة أو التقدمة أو الذبيحة ، عدا مذبح الرب إلهنا الذي هو قدام مسكنه '),
(21045, 'Joshua', 6, 22, 30, ' فسمع فينحاس الكاهن ورؤساء الجماعة ورؤوس ألوف إسرائيل الذين معه الكلام الذي تكلم به بنو رأوبين وبنو جاد وبنو منسى ، فحسن في أعينهم '),
(21046, 'Joshua', 6, 22, 31, ' فقال فينحاس بن ألعازار الكاهن لبني رأوبين وبني جاد وبني منسى : اليوم علمنا أن الرب بيننا لأنكم لم تخونوا الرب بهذه الخيانة . فالآن قد أنقذتم بني إسرائيل من يد الرب '),
(21047, 'Joshua', 6, 22, 32, ' ثم رجع فينحاس بن ألعازار الكاهن والرؤساء من عند بني رأوبين وبني جاد من أرض جلعاد إلى أرض كنعان إلى بني إسرائيل ، وردوا عليهم خبرا '),
(21048, 'Joshua', 6, 22, 33, ' فحسن الأمر في أعين بني إسرائيل ، وبارك بنو إسرائيل الله ، ولم يفتكروا بالصعود إليهم للحرب وتخريب الأرض التي كان بنو رأوبين وبنو جاد ساكنين بها '),
(21049, 'Joshua', 6, 22, 34, ' وسمى بنو رأوبين وبنو جاد المذبح عيدا لأنه شاهد بيننا أن الرب هو الله '),
(21050, 'Joshua', 6, 23, 1, ' وكان غب أيام كثيرة ، بعدما أراح الرب إسرائيل من أعدائهم حواليهم ، أن يشوع شاخ . تقدم في الأيام '),
(21051, 'Joshua', 6, 23, 2, ' فدعا يشوع جميع إسرائيل وشيوخه ورؤساءه وقضاته وعرفاءه وقال لهم : أنا قد شخت . تقدمت في الأيام '),
(21052, 'Joshua', 6, 23, 3, ' وأنتم قد رأيتم كل ما عمل الرب إلهكم بجميع أولئك الشعوب من أجلكم ، لأن الرب إلهكم هو المحارب عنكم '),
(21053, 'Joshua', 6, 23, 4, ' انظروا . قد قسمت لكم بالقرعة هؤلاء الشعوب الباقين ملكا حسب أسباطكم ، من الأردن وجميع الشعوب التي قرضتها ، والبحر العظيم نحو غروب الشمس '),
(21054, 'Joshua', 6, 23, 5, ' والرب إلهكم هو ينفيهم من أمامكم ويطردهم من قدامكم ، فتملكون أرضهم كما كلمكم الرب إلهكم '),
(21055, 'Joshua', 6, 23, 6, ' فتشددوا جدا لتحفظوا وتعملوا كل المكتوب في سفر شريعة موسى حتى لا تحيدوا عنها يمينا أو شمالا '),
(21056, 'Joshua', 6, 23, 7, ' حتى لا تدخلوا إلى هؤلاء الشعوب ، أولئك الباقين معكم ، ولا تذكروا اسم آلهتهم ، ولا تحلفوا بها ، ولا تعبدوها ، ولا تسجدوا لها '),
(21057, 'Joshua', 6, 23, 8, ' ولكن الصقوا بالرب إلهكم كما فعلتم إلى هذا اليوم '),
(21058, 'Joshua', 6, 23, 9, ' قد طرد الرب من أمامكم شعوبا عظيمة وقوية ، وأما أنتم فلم يقف أحد قدامكم إلى هذا اليوم '),
(21059, 'Joshua', 6, 23, 10, ' رجل واحد منكم يطرد ألفا ، لأن الرب إلهكم هو المحارب عنكم كما كلمكم '),
(21060, 'Joshua', 6, 23, 11, ' فاحتفظوا جدا لأنفسكم أن تحبوا الرب إلهكم '),
(21061, 'Joshua', 6, 23, 12, ' ولكن إذا رجعتم ولصقتم ببقية هؤلاء الشعوب ، أولئك الباقين معكم ، وصاهرتموهم ودخلتم إليهم وهم إليكم '),
(21062, 'Joshua', 6, 23, 13, ' فاعلموا يقينا أن الرب إلهكم لا يعود يطرد أولئك الشعوب من أمامكم ، فيكونوا لكم فخا وشركا وسوطا على جوانبكم ، وشوكا في أعينكم ، حتى تبيدوا عن تلك الأرض الصالحة التي أعطاكم إياها الرب إلهكم '),
(21063, 'Joshua', 6, 23, 14, ' وها أنا اليوم ذاهب في طريق الأرض كلها . وتعلمون بكل قلوبكم وكل أنفسكم أنه لم تسقط كلمة واحدة من جميع الكلام الصالح الذي تكلم به الرب عنكم . الكل صار لكم . لم تسقط منه كلمة واحدة '),
(21064, 'Joshua', 6, 23, 15, ' ويكون كما أنه أتى عليكم كل الكلام الصالح الذي تكلم به الرب إلهكم عنكم ، كذلك يجلب عليكم الرب كل الكلام الرديء حتى يبيدكم عن هذه الأرض الصالحة التي أعطاكم الرب إلهكم '),
(21065, 'Joshua', 6, 23, 16, ' حينما تتعدون عهد الرب إلهكم الذي أمركم به وتسيرون وتعبدون آلهة أخرى وتسجدون لها ، يحمى غضب الرب عليكم فتبيدون سريعا عن الأرض الصالحة التي أعطاكم '),
(21066, 'Joshua', 6, 24, 1, ' وجمع يشوع جميع أسباط إسرائيل إلى شكيم . ودعا شيوخ إسرائيل ورؤساءهم وقضاتهم وعرفاءهم فمثلوا أمام الرب '),
(21067, 'Joshua', 6, 7, 22, ' فأرسل يشوع رسلا فركضوا إلى الخيمة وإذا هي مطمورة في خيمته والفضة تحتها '),
(21068, 'Joshua', 6, 7, 23, ' فأخذوها من وسط الخيمة وأتوا بها إلى يشوع وإلى جميع بني إسرائيل ، وبسطوها أمام الرب '),
(21069, 'Joshua', 6, 7, 24, ' فأخذ يشوع عخان بن زارح والفضة والرداء ولسان الذهب وبنيه وبناته وبقره وحميره وغنمه وخيمته وكل ما له ، وجميع إسرائيل معه ، وصعدوا بهم إلى وادي عخور '),
(21070, 'Joshua', 6, 7, 25, ' فقال يشوع : كيف كدرتنا ؟ يكدرك الرب في هذا اليوم . فرجمه جميع إسرائيل بالحجارة وأحرقوهم بالنار ورموهم بالحجارة '),
(21071, 'Joshua', 6, 7, 26, ' وأقاموا فوقه رجمة حجارة عظيمة إلى هذا اليوم . فرجع الرب عن حمو غضبه . ولذلك دعي اسم ذلك المكان وادي عخور إلى هذا اليوم '),
(21072, 'Joshua', 6, 8, 1, ' فقال الرب ليشوع : لا تخف ولا ترتعب . خذ معك جميع رجال الحرب ، وقم اصعد إلى عاي . انظر . قد دفعت بيدك ملك عاي وشعبه ومدينته وأرضه '),
(21073, 'Joshua', 6, 8, 2, ' فتفعل بعاي وملكها كما فعلت بأريحا وملكها . غير أن غنيمتها وبهائمها تنهبونها لنفوسكم . اجعل كمينا للمدينة من ورائها '),
(21074, 'Joshua', 6, 8, 3, ' فقام يشوع وجميع رجال الحرب للصعود إلى عاي . وانتخب يشوع ثلاثين ألف رجل جبابرة البأس وأرسلهم ليلا '),
(21075, 'Joshua', 6, 8, 4, ' وأوصاهم قائلا : انظروا أنتم تكمنون للمدينة من وراء المدينة . لا تبتعدوا من المدينة كثيرا ، وكونوا كلكم مستعدين '),
(21076, 'Joshua', 6, 8, 5, ' وأما أنا وجميع الشعب الذي معي فنقترب إلى المدينة . ويكون حينما يخرجون للقائنا كما في الأول أننا نهرب قدامهم '),
(21077, 'Joshua', 6, 8, 6, ' فيخرجون وراءنا حتى نجذبهم عن المدينة . لأنهم يقولون إنهم هاربون أمامنا كما في الأول . فنهرب قدامهم '),
(21078, 'Joshua', 6, 8, 7, ' وأنتم تقومون من المكمن وتملكون المدينة ، ويدفعها الرب إلهكم بيدكم '),
(21079, 'Joshua', 6, 8, 8, ' ويكون عند أخذكم المدينة أنكم تضرمون المدينة بالنار . كقول الرب تفعلون . انظروا . قد أوصيتكم '),
(21080, 'Joshua', 6, 8, 9, ' فأرسلهم يشوع ، فساروا إلى المكمن ، ولبثوا بين بيت إيل وعاي غربي عاي . وبات يشوع تلك الليلة في وسط الشعب '),
(21081, 'Joshua', 6, 8, 10, ' فبكر يشوع في الغد وعد الشعب ، وصعد هو وشيوخ إسرائيل قدام الشعب إلى عاي '),
(21082, 'Joshua', 6, 8, 11, ' وجميع رجال الحرب الذين معه صعدوا وتقدموا وأتوا إلى مقابل المدينة ، ونزلوا شمالي عاي ، والوادي بينهم وبين عاي '),
(21083, 'Joshua', 6, 8, 12, ' فأخذ نحو خمسة آلاف رجل وجعلهم كمينا بين بيت إيل وعاي غربي المدينة '),
(21084, 'Joshua', 6, 8, 13, ' وأقاموا الشعب ، أي كل الجيش الذي شمالي المدينة ، وكمينه غربي المدينة . وسار يشوع تلك الليلة إلى وسط الوادي '),
(21085, 'Joshua', 6, 8, 14, ' وكان لما رأى ملك عاي ذلك أنهم أسرعوا وبكروا ، وخرج رجال المدينة للقاء إسرائيل للحرب ، هو وجميع شعبه في الميعاد إلى قدام السهل ، وهو لا يعلم أن عليه كمينا وراء المدينة '),
(21086, 'Joshua', 6, 8, 15, ' فأعطى يشوع وجميع إسرائيل انكسارا أمامهم وهربوا في طريق البرية '),
(21087, 'Joshua', 6, 8, 16, ' فألقي الصوت على جميع الشعب الذين في المدينة للسعي وراءهم ، فسعوا وراء يشوع وانجذبوا عن المدينة '),
(21088, 'Joshua', 6, 8, 17, ' ولم يبق في عاي أو في بيت إيل رجل لم يخرج وراء إسرائيل . فتركوا المدينة مفتوحة وسعوا وراء إسرائيل '),
(21089, 'Joshua', 6, 8, 18, ' فقال الرب ليشوع : مد المزراق الذي بيدك نحو عاي لأني بيدك أدفعها . فمد يشوع المزراق الذي بيده نحو المدينة '),
(21090, 'Joshua', 6, 8, 19, ' فقام الكمين بسرعة من مكانه وركضوا عندما مد يده ، ودخلوا المدينة وأخذوها ، وأسرعوا وأحرقوا المدينة بالنار '),
(21091, 'Joshua', 6, 8, 20, ' فالتفت رجال عاي إلى ورائهم ونظروا وإذا دخان المدينة قد صعد إلى السماء . فلم يكن لهم مكان للهرب هنا أو هناك . والشعب الهارب إلى البرية انقلب على الطارد '),
(21092, 'Joshua', 6, 8, 21, ' ولما رأى يشوع وجميع إسرائيل أن الكمين قد أخذ المدينة ، وأن دخان المدينة قد صعد ، انثنوا وضربوا رجال عاي '),
(21093, 'Joshua', 6, 8, 22, ' وهؤلاء خرجوا من المدينة للقائهم ، فكانوا في وسط إسرائيل ، هؤلاء من هنا وأولئك من هناك . وضربوهم حتى لم يبق منهم شارد ولا منفلت '),
(21094, 'Joshua', 6, 8, 23, ' وأما ملك عاي فأمسكوه حيا وتقدموا به إلى يشوع '),
(21095, 'Joshua', 6, 8, 24, ' وكان لما انتهى إسرائيل من قتل جميع سكان عاي في الحقل في البرية حيث لحقوهم وسقطوا جميعا بحد السيف حتى فنوا ، أن جميع إسرائيل رجع إلى عاي وضربوها بحد السيف '),
(21096, 'Joshua', 6, 8, 25, ' فكان جميع الذين سقطوا في ذلك اليوم من رجال ونساء اثني عشر ألفا ، جميع أهل عاي '),
(21097, 'Joshua', 6, 8, 26, ' ويشوع لم يرد يده التي مدها بالمزراق حتى حرم جميع سكان عاي '),
(21098, 'Joshua', 6, 8, 27, ' لكن البهائم وغنيمة تلك المدينة نهبها إسرائيل لأنفسهم حسب قول الرب الذي أمر به يشوع '),
(21099, 'Joshua', 6, 8, 28, ' وأحرق يشوع عاي وجعلها تلا أبديا خرابا إلى هذا اليوم '),
(21100, 'Joshua', 6, 8, 29, ' وملك عاي علقه على الخشبة إلى وقت المساء . وعند غروب الشمس أمر يشوع فأنزلوا جثته عن الخشبة وطرحوها عند مدخل باب المدينة ، وأقاموا عليها رجمة حجارة عظيمة إلى هذا اليوم '),
(21101, 'Joshua', 6, 8, 30, ' حينئذ بنى يشوع مذبحا للرب إله إسرائيل في جبل عيبال '),
(21102, 'Joshua', 6, 8, 31, ' كما أمر موسى عبد الرب بني إسرائيل ، كما هو مكتوب في سفر توراة موسى . مذبح حجارة صحيحة لم يرفع أحد عليها حديدا ، وأصعدوا عليه محرقات للرب ، وذبحوا ذبائح سلامة '),
(21103, 'Joshua', 6, 8, 32, ' وكتب هناك على الحجارة نسخة توراة موسى التي كتبها أمام بني إسرائيل '),
(21104, 'Joshua', 6, 8, 33, ' وجميع إسرائيل وشيوخهم ، والعرفاء وقضاتهم ، وقفوا جانب التابوت من هنا ومن هناك مقابل الكهنة اللاويين حاملي تابوت عهد الرب . الغريب كما الوطني . نصفهم إلى جهة جبل جرزيم ، ونصفهم إلى جهة جبل عيبال ، كما أمر موسى عبد الرب أولا لبركة شعب إسرائيل '),
(21105, 'Joshua', 6, 8, 34, ' وبعد ذلك قرأ جميع كلام التوراة : البركة واللعنة ، حسب كل ما كتب في سفر التوراة '),
(21106, 'Joshua', 6, 8, 35, ' لم تكن كلمة من كل ما أمر به موسى لم يقرأها يشوع قدام كل جماعة إسرائيل والنساء والأطفال والغريب السائر في وسطهم '),
(21107, 'Joshua', 6, 9, 1, ' ولما سمع جميع الملوك الذين في عبر الأردن في الجبل وفي السهل وفي كل ساحل البحر الكبير إلى جهة لبنان ، الحثيون والأموريون والكنعانيون والفرزيون والحويون واليبوسيون '),
(21108, 'Joshua', 6, 9, 2, ' اجتمعوا معا لمحاربة يشوع وإسرائيل بصوت واحد '),
(21109, 'Joshua', 6, 9, 3, ' وأما سكان جبعون لما سمعوا بما عمله يشوع بأريحا وعاي '),
(21110, 'Joshua', 6, 9, 4, ' فهم عملوا بغدر ، ومضوا وداروا وأخذوا جوالق بالية لحميرهم ، وزقاق خمر بالية مشققة ومربوطة '),
(21111, 'Joshua', 6, 9, 5, ' ونعالا بالية ومرقعة في أرجلهم ، وثيابا رثة عليهم ، وكل خبز زادهم يابس قد صار فتاتا '),
(21112, 'Joshua', 6, 9, 6, ' وساروا إلى يشوع إلى المحلة في الجلجال ، وقالوا له ولرجال إسرائيل : من أرض بعيدة جئنا . والآن اقطعوا لنا عهدا '),
(21113, 'Joshua', 6, 9, 7, ' فقال رجال إسرائيل للحويين : لعلك ساكن في وسطي ، فكيف أقطع لك عهدا '),
(21114, 'Joshua', 6, 9, 8, ' فقالوا ليشوع : عبيدك نحن . فقال لهم يشوع : من أنتم ؟ ومن أين جئتم '),
(21115, 'Joshua', 6, 9, 9, ' فقالوا له : من أرض بعيدة جدا جاء عبيدك على اسم الرب إلهك ، لأننا سمعنا خبره وكل ما عمل بمصر '),
(21116, 'Joshua', 6, 9, 10, ' وكل ما عمل بملكي الأموريين اللذين في عبر الأردن : سيحون ملك حشبون وعوج ملك باشان الذي في عشتاروث '),
(21117, 'Joshua', 6, 9, 11, ' فكلمنا شيوخنا وجميع سكان أرضنا قائلين : خذوا بأيديكم زادا للطريق ، واذهبوا للقائهم وقولوا لهم : عبيدكم نحن . والآن اقطعوا لنا عهدا '),
(21118, 'Joshua', 6, 9, 12, ' هذا خبزنا سخنا تزودناه من بيوتنا يوم خروجنا لكي نسير إليكم ، وها هو الآن يابس قد صار فتاتا '),
(21119, 'Joshua', 6, 9, 13, ' وهذه زقاق الخمر التي ملأناها جديدة ، هوذا قد تشققت . وهذه ثيابنا ونعالنا قد بليت من طول الطريق جدا '),
(21120, 'Joshua', 6, 9, 14, ' فأخذ الرجال من زادهم ، ومن فم الرب لم يسألوا '),
(21121, 'Joshua', 6, 9, 15, ' فعمل يشوع لهم صلحا وقطع لهم عهدا لاستحيائهم ، وحلف لهم رؤساء الجماعة '),
(21122, 'Joshua', 6, 9, 16, ' وفي نهاية ثلاثة أيام بعدما قطعوا لهم عهدا سمعوا أنهم قريبون إليهم وأنهم ساكنون في وسطهم '),
(21123, 'Joshua', 6, 9, 17, ' فارتحل بنو إسرائيل وجاءوا إلى مدنهم في اليوم الثالث . ومدنهم هي جبعون والكفيرة وبئيروت وقرية يعاريم '),
(21124, 'Joshua', 6, 9, 18, ' ولم يضربهم بنو إسرائيل لأن رؤساء الجماعة حلفوا لهم بالرب إله إسرائيل . فتذمر كل الجماعة على الرؤساء '),
(21125, 'Joshua', 6, 9, 19, ' فقال جميع الرؤساء لكل الجماعة : إننا قد حلفنا لهم بالرب إله إسرائيل . والآن لا نتمكن من مسهم '),
(21126, 'Joshua', 6, 9, 20, ' هذا نصنعه لهم ونستحييهم فلا يكون علينا سخط من أجل الحلف الذي حلفنا لهم '),
(21127, 'Joshua', 6, 9, 21, ' وقال لهم الرؤساء : يحيون ويكونون محتطبي حطب ومستقي ماء لكل الجماعة كما كلمهم الرؤساء '),
(21128, 'Joshua', 6, 9, 22, ' فدعاهم يشوع وكلمهم قائلا : لماذا خدعتمونا قائلين : نحن بعيدون عنكم جدا ، وأنتم ساكنون في وسطنا '),
(21129, 'Joshua', 6, 9, 23, ' فالآن ملعونون أنتم . فلا ينقطع منكم العبيد ومحتطبو الحطب ومستقو الماء لبيت إلهي '),
(21130, 'Joshua', 6, 9, 24, ' فأجابوا يشوع وقالوا : أخبر عبيدك إخبارا بما أمر به الرب إلهك موسى عبده أن يعطيكم كل الأرض ، ويبيد جميع سكان الأرض من أمامكم . فخفنا جدا على أنفسنا من قبلكم ، ففعلنا هذا الأمر '),
(21131, 'Joshua', 6, 9, 25, ' والآن فهوذا نحن بيدك ، فافعل بنا ما هو صالح وحق في عينيك أن تعمل '),
(21132, 'Joshua', 6, 9, 26, ' ففعل بهم هكذا ، وأنقذهم من يد بني إسرائيل فلم يقتلوهم '),
(21133, 'Joshua', 6, 9, 27, ' وجعلهم يشوع في ذلك اليوم محتطبي حطب ومستقي ماء للجماعة ولمذبح الرب إلى هذا اليوم ، في المكان الذي يختاره '),
(21134, 'Joshua', 6, 10, 1, ' فلما سمع أدوني صادق ملك أورشليم أن يشوع قد أخذ عاي وحرمها . كما فعل بأريحا وملكها فعل بعاي وملكها ، وأن سكان جبعون قد صالحوا إسرائيل وكانوا في وسطهم '),
(21135, 'Joshua', 6, 10, 2, ' خاف جدا ، لأن جبعون مدينة عظيمة كإحدى المدن الملكية ، وهي أعظم من عاي ، وكل رجالها جبابرة '),
(21136, 'Joshua', 6, 10, 3, ' فأرسل أدوني صادق ملك أورشليم إلى هوهام ملك حبرون ، وفرآم ملك يرموت ، ويافيع ملك لخيش ، ودبير ملك عجلون يقول '),
(21137, 'Joshua', 6, 10, 4, ' اصعدوا إلي وأعينوني ، فنضرب جبعون لأنها صالحت يشوع وبني إسرائيل '),
(21138, 'Joshua', 6, 10, 5, ' فاجتمع ملوك الأموريين الخمسة : ملك أورشليم ، وملك حبرون ، وملك يرموت ، وملك لخيش ، وملك عجلون ، وصعدوا هم وكل جيوشهم ونزلوا على جبعون وحاربوها '),
(21139, 'Joshua', 6, 10, 6, ' فأرسل أهل جبعون إلى يشوع إلى المحلة في الجلجال يقولون : لا ترخ يديك عن عبيدك . اصعد إلينا عاجلا وخلصنا وأعنا ، لأنه قد اجتمع علينا جميع ملوك الأموريين الساكنين في الجبل '),
(21140, 'Joshua', 6, 10, 7, ' فصعد يشوع من الجلجال هو وجميع رجال الحرب معه وكل جبابرة البأس '),
(21141, 'Joshua', 6, 10, 8, ' فقال الرب ليشوع : لا تخفهم ، لأني بيدك قد أسلمتهم . لا يقف رجل منهم بوجهك '),
(21142, 'Joshua', 6, 10, 9, ' فأتى إليهم يشوع بغتة . صعد الليل كله من الجلجال '),
(21143, 'Joshua', 6, 10, 10, ' فأزعجهم الرب أمام إسرائيل ، وضربهم ضربة عظيمة في جبعون ، وطردهم في طريق عقبة بيت حورون ، وضربهم إلى عزيقة وإلى مقيدة '),
(21144, 'Joshua', 6, 10, 11, ' وبينما هم هاربون من أمام إسرائيل وهم في منحدر بيت حورون ، رماهم الرب بحجارة عظيمة من السماء إلى عزيقة فماتوا . والذين ماتوا بحجارة البرد هم أكثر من الذين قتلهم بنو إسرائيل بالسيف '),
(21145, 'Joshua', 6, 10, 12, ' حينئذ كلم يشوع الرب ، يوم أسلم الرب الأموريين أمام بني إسرائيل ، وقال أمام عيون إسرائيل : يا شمس دومي على جبعون ، ويا قمر على وادي أيلون '),
(21146, 'Joshua', 6, 10, 13, ' فدامت الشمس ووقف القمر حتى انتقم الشعب من أعدائه . أليس هذا مكتوبا في سفر ياشر ؟ فوقفت الشمس في كبد السماء ولم تعجل للغروب نحو يوم كامل '),
(21147, 'Joshua', 6, 10, 14, ' ولم يكن مثل ذلك اليوم قبله ولا بعده سمع فيه الرب صوت إنسان ، لأن الرب حارب عن إسرائيل '),
(21148, 'Joshua', 6, 10, 15, ' ثم رجع يشوع وجميع إسرائيل معه إلى المحلة في الجلجال '),
(21149, 'Joshua', 6, 10, 16, ' فهرب أولئك الخمسة الملوك واختبأوا في مغارة في مقيدة '),
(21150, 'Joshua', 6, 10, 17, ' فأخبر يشوع وقيل له : قد وجد الملوك الخمسة مختبئين في مغارة في مقيدة '),
(21151, 'Joshua', 6, 10, 18, ' فقال يشوع : دحرجوا حجارة عظيمة على فم المغارة ، وأقيموا عليها رجالا لأجل حفظهم '),
(21152, 'Joshua', 6, 10, 19, ' وأما أنتم فلا تقفوا ، بل اسعوا وراء أعدائكم واضربوا مؤخرهم . لا تدعوهم يدخلون مدنهم ، لأن الرب إلهكم قد أسلمهم بيدكم '),
(21153, 'Joshua', 6, 10, 20, ' ولما انتهى يشوع وبنو إسرائيل من ضربهم ضربة عظيمة جدا حتى فنوا ، والشرد الذين شردوا منهم دخلوا المدن المحصنة '),
(21154, 'Joshua', 6, 10, 21, ' رجع جميع الشعب إلى المحلة إلى يشوع في مقيدة بسلام . لم يسن أحد لسانه على بني إسرائيل '),
(21155, 'Joshua', 6, 10, 22, ' فقال يشوع : افتحوا فم المغارة وأخرجوا إلي هؤلاء الخمسة الملوك من المغارة '),
(21156, 'Joshua', 6, 10, 23, ' ففعلوا كذلك ، وأخرجوا إليه أولئك الملوك الخمسة من المغارة : ملك أورشليم ، وملك حبرون ، وملك يرموت ، وملك لخيش ، وملك عجلون '),
(21157, 'Joshua', 6, 10, 24, ' وكان لما أخرجوا أولئك الملوك إلى يشوع أن يشوع دعا كل رجال إسرائيل ، وقال لقواد رجال الحرب الذين ساروا معه : تقدموا وضعوا أرجلكم على أعناق هؤلاء الملوك . فتقدموا ووضعوا أرجلهم على أعناقهم '),
(21158, 'Joshua', 6, 10, 25, ' فقال لهم يشوع : لا تخافوا ولا ترتعبوا . تشددوا وتشجعوا . لأنه هكذا يفعل الرب بجميع أعدائكم الذين تحاربونهم '),
(21159, 'Joshua', 6, 10, 26, ' وضربهم يشوع بعد ذلك وقتلهم وعلقهم على خمس خشب ، وبقوا معلقين على الخشب حتى المساء '),
(21160, 'Joshua', 6, 10, 27, ' وكان عند غروب الشمس أن يشوع أمر فأنزلوهم عن الخشب وطرحوهم في المغارة التي اختبأوا فيها ، ووضعوا حجارة كبيرة على فم المغارة حتى إلى هذا اليوم عينه '),
(21161, 'Joshua', 6, 10, 28, ' وأخذ يشوع مقيدة في ذلك اليوم وضربها بحد السيف ، وحرم ملكها هو وكل نفس بها . لم يبق شاردا ، وفعل بملك مقيدة كما فعل بملك أريحا '),
(21162, 'Joshua', 6, 10, 29, ' ثم اجتاز يشوع من مقيدة وكل إسرائيل معه إلى لبنة ، وحارب لبنة '),
(21163, 'Joshua', 6, 10, 30, ' فدفعها الرب هي أيضا بيد إسرائيل مع ملكها ، فضربها بحد السيف وكل نفس بها . لم يبق بها شاردا ، وفعل بملكها كما فعل بملك أريحا '),
(21164, 'Joshua', 6, 10, 31, ' ثم اجتاز يشوع وكل إسرائيل معه من لبنة إلى لخيش ونزل عليها وحاربها '),
(21165, 'Joshua', 6, 10, 32, ' فدفع الرب لخيش بيد إسرائيل ، فأخذها في اليوم الثاني وضربها بحد السيف وكل نفس بها حسب كل ما فعل بلبنة '),
(21166, 'Joshua', 6, 10, 33, ' حينئذ صعد هورام ملك جازر لإعانة لخيش ، وضربه يشوع مع شعبه حتى لم يبق له شاردا '),
(21167, 'Joshua', 6, 10, 34, ' ثم اجتاز يشوع وكل إسرائيل معه من لخيش إلى عجلون فنزلوا عليها وحاربوها '),
(21168, 'Joshua', 6, 10, 35, ' وأخذوها في ذلك اليوم وضربوها بحد السيف ، وحرم كل نفس بها في ذلك اليوم حسب كل ما فعل بلخيش '),
(21169, 'Joshua', 6, 10, 36, ' ثم صعد يشوع وجميع إسرائيل معه من عجلون إلى حبرون وحاربوها '),
(21170, 'Joshua', 6, 10, 37, ' وأخذوها وضربوها بحد السيف مع ملكها وكل مدنها وكل نفس بها . لم يبق شاردا حسب كل ما فعل بعجلون ، فحرمها وكل نفس بها '),
(21171, 'Joshua', 6, 10, 38, ' ثم رجع يشوع وكل إسرائيل معه إلى دبير وحاربها '),
(21172, 'Joshua', 6, 10, 39, ' وأخذها مع ملكها وكل مدنها ، وضربوها بحد السيف وحرموا كل نفس بها . لم يبق شاردا ، كما فعل بحبرون كذلك فعل بدبير وملكها ، وكما فعل بلبنة وملكها '),
(21173, 'Joshua', 6, 10, 40, ' فضرب يشوع كل أرض الجبل والجنوب والسهل والسفوح وكل ملوكها . لم يبق شاردا ، بل حرم كل نسمة كما أمر الرب إله إسرائيل '),
(21174, 'Joshua', 6, 10, 41, ' فضربهم يشوع من قادش برنيع إلى غزة وجميع أرض جوشن إلى جبعون '),
(21175, 'Joshua', 6, 10, 42, ' وأخذ يشوع جميع أولئك الملوك وأرضهم دفعة واحدة ، لأن الرب إله إسرائيل حارب عن إسرائيل '),
(21176, 'Joshua', 6, 10, 43, ' ثم رجع يشوع وجميع إسرائيل معه إلى المحلة إلى الجلجال '),
(21177, 'Joshua', 6, 11, 1, ' فلما سمع يابين ملك حاصور ، أرسل إلى يوباب ملك مادون ، وإلى ملك شمرون ، وإلى ملك أكشاف '),
(21178, 'Joshua', 6, 11, 2, ' وإلى الملوك الذين إلى الشمال في الجبل ، وفي العربة جنوبي كنروت ، وفي السهل ، وفي مرتفعات دور غربا '),
(21179, 'Joshua', 6, 11, 3, ' الكنعانيين في الشرق والغرب ، والأموريين والحثيين والفرزيين واليبوسيين في الجبل ، والحويين تحت حرمون في أرض المصفاة '),
(21180, 'Joshua', 6, 11, 4, ' فخرجوا هم وكل جيوشهم معهم ، شعبا غفيرا كالرمل الذي على شاطئ البحر في الكثرة ، بخيل ومركبات كثيرة جدا '),
(21181, 'Joshua', 6, 11, 5, ' فاجتمع جميع هؤلاء الملوك بميعاد وجاءوا ونزلوا معا على مياه ميروم لكي يحاربوا إسرائيل '),
(21182, 'Joshua', 6, 11, 6, ' فقال الرب ليشوع : لا تخفهم ، لأني غدا في مثل هذا الوقت أدفعهم جميعا قتلى أمام إسرائيل ، فتعرقب خيلهم ، وتحرق مركباتهم بالنار '),
(21183, 'Joshua', 6, 11, 7, ' فجاء يشوع وجميع رجال الحرب معه عليهم عند مياه ميروم بغتة وسقطوا عليهم '),
(21184, 'Joshua', 6, 11, 8, ' فدفعهم الرب بيد إسرائيل ، فضربوهم وطردوهم إلى صيدون العظيمة ، وإلى مسرفوت مايم ، وإلى بقعة مصفاة شرقا . فضربوهم حتى لم يبق لهم شارد '),
(21185, 'Joshua', 6, 11, 9, ' ففعل يشوع بهم كما قال له الرب . عرقب خيلهم ، وأحرق مركباتهم بالنار '),
(21186, 'Joshua', 6, 11, 10, ' ثم رجع يشوع في ذلك الوقت وأخذ حاصور وضرب ملكها بالسيف ، لأن حاصور كانت قبلا رأس جميع تلك الممالك '),
(21187, 'Joshua', 6, 11, 11, ' وضربوا كل نفس بها بحد السيف . حرموهم ، ولم تبق نسمة ، وأحرق حاصور بالنار '),
(21188, 'Joshua', 6, 11, 12, ' فأخذ يشوع كل مدن أولئك الملوك وجميع ملوكها وضربهم بحد السيف . حرمهم كما أمر موسى عبد الرب '),
(21189, 'Joshua', 6, 11, 13, ' غير أن المدن القائمة على تلالها لم يحرقها إسرائيل ، ما عدا حاصور وحدها أحرقها يشوع '),
(21190, 'Joshua', 6, 11, 14, ' وكل غنيمة تلك المدن والبهائم نهبها بنو إسرائيل لأنفسهم . وأما الرجال فضربوهم جميعا بحد السيف حتى أبادوهم . لم يبقوا نسمة '),
(21191, 'Joshua', 6, 11, 15, ' كما أمر الرب موسى عبده هكذا أمر موسى يشوع ، وهكذا فعل يشوع . لم يهمل شيئا من كل ما أمر به الرب موسى '),
(21192, 'Joshua', 6, 11, 16, ' فأخذ يشوع كل تلك الأرض : الجبل ، وكل الجنوب ، وكل أرض جوشن والسهل والعربة وجبل إسرائيل وسهله '),
(21193, 'Joshua', 6, 11, 17, ' من الجبل الأقرع الصاعد إلى سعير إلى بعل جاد في بقعة لبنان تحت جبل حرمون . وأخذ جميع ملوكها وضربهم وقتلهم '),
(21194, 'Joshua', 6, 11, 18, ' فعمل يشوع حربا مع أولئك الملوك أياما كثيرة '),
(21195, 'Joshua', 6, 11, 19, ' لم تكن مدينة صالحت بني إسرائيل إلا الحويين سكان جبعون ، بل أخذوا الجميع بالحرب '),
(21196, 'Joshua', 6, 11, 20, ' لأنه كان من قبل الرب أن يشدد قلوبهم حتى يلاقوا إسرائيل للمحاربة فيحرموا ، فلا تكون عليهم رأفة ، بل يبادون كما أمر الرب موسى '),
(21197, 'Joshua', 6, 11, 21, ' وجاء يشوع في ذلك الوقت وقرض العناقيين من الجبل ، من حبرون ومن دبير ومن عناب ، ومن جميع جبل يهوذا ، ومن كل جبل إسرائيل . حرمهم يشوع مع مدنهم '),
(21198, 'Joshua', 6, 11, 22, ' فلم يتبق عناقيون في أرض بني إسرائيل ، لكن بقوا في غزة وجت وأشدود '),
(21199, 'Joshua', 6, 11, 23, ' فأخذ يشوع كل الأرض حسب كل ما كلم به الرب موسى ، وأعطاها يشوع ملكا لإسرائيل حسب فرقهم وأسباطهم . واستراحت الأرض من الحرب '),
(21200, 'Joshua', 6, 12, 1, ' وهؤلاء هم ملوك الأرض الذين ضربهم بنو إسرائيل وامتلكوا أرضهم في عبر الأردن نحو شروق الشمس ، من وادي أرنون إلى جبل حرمون وكل العربة نحو الشروق '),
(21201, 'Joshua', 6, 12, 2, ' سيحون ملك الأموريين الساكن في حشبون ، المتسلط من عروعير التي على حافة وادي أرنون ووسط الوادي ونصف جلعاد إلى وادي يبوق تخوم بني عمون '),
(21202, 'Joshua', 6, 12, 3, ' والعربة إلى بحر كنروت نحو الشروق ، وإلى بحر العربة (بحر الملح) نحو الشروق ، طريق بيت يشيموت ، ومن التيمن تحت سفوح الفسجة '),
(21203, 'Joshua', 6, 12, 4, ' وتخوم عوج ملك باشان من بقية الرفائيين الساكن في عشتاروث وفي إذرعي '),
(21204, 'Joshua', 6, 12, 5, ' والمتسلط على جبل حرمون وسلخة وعلى كل باشان إلى تخم الجشوريين والمعكيين ونصف جلعاد ، تخوم سيحون ملك حشبون '),
(21205, 'Joshua', 6, 12, 6, ' موسى عبد الرب وبنو إسرائيل ضربوها . وأعطاها موسى عبد الرب ميراثا للرأوبينيين والجاديين ولنصف سبط منسى '),
(21206, 'Joshua', 6, 12, 7, ' وهؤلاء هم ملوك الأرض الذين ضربهم يشوع وبنو إسرائيل في عبر الأردن غربا ، من بعل جاد في بقعة لبنان إلى الجبل الأقرع الصاعد إلى سعير . وأعطاها يشوع لأسباط إسرائيل ميراثا حسب فرقهم '),
(21207, 'Joshua', 6, 12, 8, ' في الجبل والسهل والعربة والسفوح والبرية والجنوب : الحثيون والأموريون والكنعانيون والفرزيون والحويون واليبوسيون '),
(21208, 'Joshua', 6, 12, 9, ' ملك أريحا واحد . ملك عاي التي بجانب بيت إيل واحد '),
(21209, 'Joshua', 6, 12, 10, ' ملك أورشليم واحد . ملك حبرون واحد '),
(21210, 'Joshua', 6, 12, 11, ' ملك يرموت واحد . ملك لخيش واحد '),
(21211, 'Joshua', 6, 12, 12, ' ملك عجلون واحد . ملك جازر واحد '),
(21212, 'Joshua', 6, 12, 13, ' ملك دبير واحد . ملك جادر واحد '),
(21213, 'Joshua', 6, 12, 14, ' ملك حرمة واحد . ملك عراد واحد '),
(21214, 'Joshua', 6, 12, 15, ' ملك لبنة واحد . ملك عدلام واحد '),
(21215, 'Joshua', 6, 15, 16, ' وقال كالب : من يضرب قرية سفر ويأخذها أعطيه عكسة ابنتي امرأة '),
(21216, 'Joshua', 6, 15, 17, ' فأخذها عثنيئيل بن قناز أخو كالب . فأعطاه عكسة ابنته امرأة '),
(21217, 'Joshua', 6, 15, 18, ' وكان عند دخولها أنها غرته بطلب حقل من أبيها . فنزلت عن الحمار فقال لها كالب : ما لك '),
(21218, 'Joshua', 6, 15, 19, ' فقالت : أعطني بركة . لأنك أعطيتني أرض الجنوب فأعطني ينابيع ماء . فأعطاها الينابيع العليا والينابيع السفلى '),
(21219, 'Joshua', 6, 15, 20, ' هذا نصيب سبط بني يهوذا حسب عشائرهم '),
(21220, 'Joshua', 6, 15, 21, ' وكانت المدن القصوى التي لسبط بني يهوذا إلى تخم أدوم جنوبا : قبصئيل وعيدر وياجور '),
(21221, 'Joshua', 6, 15, 22, ' وقينة وديمونة وعدعدة '),
(21222, 'Joshua', 6, 15, 23, ' وقادش وحاصور ويثنان '),
(21223, 'Joshua', 6, 15, 24, ' وزيف وطالم وبعلوت '),
(21224, 'Joshua', 6, 15, 25, ' وحاصور وحدتة وقريوت وحصرون ، هي حاصور '),
(21225, 'Joshua', 6, 15, 26, ' وأمام وشماع ومولادة '),
(21226, 'Joshua', 6, 15, 27, ' وحصر جدة وحشمون وبيت فالط '),
(21227, 'Joshua', 6, 15, 28, ' وحصر شوعال وبئر سبع وبزيوتية '),
(21228, 'Joshua', 6, 15, 29, ' وبعلة وعييم وعاصم '),
(21229, 'Joshua', 6, 15, 30, ' وألتولد وكسيل وحرمة '),
(21230, 'Joshua', 6, 15, 31, ' وصقلغ ومدمنة وسنسنة '),
(21231, 'Joshua', 6, 15, 32, ' ولباوت وشلحيم وعين ورمون . كل المدن تسع وعشرون مع ضياعها '),
(21232, 'Joshua', 6, 15, 33, ' في السهل : أشتأول وصرعة وأشنة '),
(21233, 'Joshua', 6, 15, 34, ' وزانوح وعين جنيم وتفوح وعينام '),
(21234, 'Joshua', 6, 15, 35, ' ويرموت وعدلام وسوكوه وعزيقة '),
(21235, 'Joshua', 6, 15, 36, ' وشعرايم وعديتايم والجديرة وجديروتايم . أربع عشرة مدينة مع ضياعها '),
(21236, 'Joshua', 6, 15, 37, ' صنان وحداشة ومجدل جاد '),
(21237, 'Joshua', 6, 15, 38, ' ودلعان والمصفاة ويقتئيل '),
(21238, 'Joshua', 6, 15, 39, ' ولخيش وبصقة وعجلون '),
(21239, 'Joshua', 6, 15, 40, ' وكبون ولحمام وكتليش '),
(21240, 'Joshua', 6, 15, 41, ' وجديروت بيت داجون ونعمة ومقيدة . ست عشرة مدينة مع ضياعها '),
(21241, 'Joshua', 6, 15, 42, ' لبنة وعاتر وعاشان '),
(21242, 'Joshua', 6, 15, 43, ' ويفتاح وأشنة ونصيب '),
(21243, 'Joshua', 6, 15, 44, ' وقعيلة وأكزيب ومريشة . تسع مدن مع ضياعها '),
(21244, 'Joshua', 6, 15, 45, ' عقرون وقراها وضياعها '),
(21245, 'Joshua', 6, 15, 46, ' من عقرون غربا كل ما بقرب أشدود وضياعها '),
(21246, 'Joshua', 6, 15, 47, ' أشدود وقراها وضياعها ، وغزة وقراها وضياعها إلى وادي مصر والبحر الكبير وتخومه '),
(21247, 'Joshua', 6, 15, 48, ' وفي الجبل : شامير ويتير وسوكوه '),
(21248, 'Joshua', 6, 15, 49, ' ودنة وقرية سنة ، هي دبير '),
(21249, 'Joshua', 6, 15, 50, ' وعناب وأشتموه وعانيم '),
(21250, 'Joshua', 6, 15, 51, ' وجوشن وحولون وجيلوه . إحدى عشرة مدينة مع ضياعها '),
(21251, 'Joshua', 6, 15, 52, ' أراب ودومة وأشعان '),
(21252, 'Joshua', 6, 15, 53, ' وينوم وبيت تفوح وأفيقة '),
(21253, 'Joshua', 6, 15, 54, ' وحمطة وقرية أربع ، هي حبرون ، وصيعور . تسع مدن مع ضياعها '),
(21254, 'Joshua', 6, 15, 55, ' معون وكرمل وزيف ويوطة '),
(21255, 'Joshua', 6, 15, 56, ' ويزرعيل ويقدعام وزانوح '),
(21256, 'Joshua', 6, 15, 57, ' والقاين وجبعة وتمنة . عشر مدن مع ضياعها '),
(21257, 'Joshua', 6, 15, 58, ' حلحول وبيت صور وجدور '),
(21258, 'Joshua', 6, 15, 59, ' ومعارة وبيت عنوت وألتقون . ست مدن مع ضياعها '),
(21259, 'Joshua', 6, 15, 60, ' قرية بعل ، هي قرية يعاريم ، والربة . مدينتان مع ضياعهما '),
(21260, 'Joshua', 6, 15, 61, ' في البرية : بيت العربة ومدين وسكاكة '),
(21261, 'Joshua', 6, 15, 62, ' والنبشان ومدينة الملح وعين جدي . ست مدن مع ضياعها '),
(21262, 'Joshua', 6, 15, 63, ' وأما اليبوسيون الساكنون في أورشليم فلم يقدر بنو يهوذا على طردهم ، فسكن اليبوسيون مع بني يهوذا في أورشليم إلى هذا اليوم '),
(21263, 'Joshua', 6, 16, 1, ' وخرجت القرعة لبني يوسف من أردن أريحا إلى ماء أريحا نحو الشروق إلى البرية الصاعدة من أريحا في جبل بيت إيل '),
(21264, 'Joshua', 6, 16, 2, ' وخرجت من بيت إيل إلى لوز وعبرت إلى تخم الأركيين إلى عطاروت '),
(21265, 'Joshua', 6, 16, 3, ' ونزلت غربا إلى تخم اليفلطيين إلى تخم بيت حورون السفلى ، وإلى جازر ، وكانت مخارجها عند البحر '),
(21266, 'Joshua', 6, 19, 14, ' ودار بها التخم شمالا إلى حناتون ، وكانت مخارجه عند وادي يفتحئيل '),
(21267, 'Joshua', 6, 19, 15, ' وقطة ونهلال وشمرون ويدالة وبيت لحم . اثنتا عشرة مدينة مع ضياعها '),
(21268, 'Joshua', 6, 19, 16, ' هذا هو نصيب بني زبولون حسب عشائرهم . هذه المدن مع ضياعها '),
(21269, 'Joshua', 6, 19, 17, ' وخرجت القرعة الرابعة ليساكر . لبني يساكر حسب عشائرهم '),
(21270, 'Joshua', 6, 19, 18, ' وكان تخمهم إلى يزرعيل والكسلوت وشونم '),
(21271, 'Joshua', 6, 19, 19, ' وحفارايم وشيئون وأناحرة '),
(21272, 'Joshua', 6, 19, 20, ' وربيت وقشيون وآبص '),
(21273, 'Joshua', 6, 19, 21, ' ورمة وعين جنيم وعين حدة وبيت فصيص '),
(21274, 'Joshua', 6, 19, 22, ' ووصل التخم إلى تابور وشحصيمة وبيت شمس . وكانت مخارج تخمهم عند الأردن . ست عشرة مدينة مع ضياعها '),
(21275, 'Joshua', 6, 19, 23, ' هذا هو نصيب بني يساكر حسب عشائرهم . المدن مع ضياعها '),
(21276, 'Joshua', 6, 19, 24, ' وخرجت القرعة الخامسة لسبط بني أشير حسب عشائرهم '),
(21277, 'Joshua', 6, 19, 25, ' وكان تخمهم حلقة وحلي وباطن وأكشاف '),
(21278, 'Joshua', 6, 19, 26, ' وألملك وعمعاد ومشآل ، ووصل إلى كرمل غربا وإلى شيحور لبنة '),
(21279, 'Joshua', 6, 19, 27, ' ورجع نحو مشرق الشمس إلى بيت داجون ، ووصل إلى زبولون وإلى وادي يفتحئيل شمالي بيت العامق ونعيئيل وخرج إلى كابول عن اليسار '),
(21280, 'Joshua', 6, 19, 28, ' وعبرون ورحوب وحمون وقانة إلى صيدون العظيمة '),
(21281, 'Joshua', 6, 19, 29, ' ورجع التخم إلى الرامة وإلى المدينة المحصنة صور ، ثم رجع التخم إلى حوصة . وكانت مخارجه عند البحر في كورة أكزيب '),
(21282, 'Joshua', 6, 19, 30, ' وعمة وأفيق ورحوب . اثنتان وعشرون مدينة مع ضياعها '),
(21283, 'Joshua', 6, 19, 31, ' هذا هو نصيب سبط بني أشير حسب عشائرهم . هذه المدن مع ضياعها '),
(21284, 'Joshua', 6, 19, 32, ' لبني نفتالي خرجت القرعة السادسة . لبني نفتالي حسب عشائرهم '),
(21285, 'Joshua', 6, 19, 33, ' وكان تخمهم من حالف من البلوطة عند صعننيم وأدامي الناقب ويبنئيل إلى لقوم . وكانت مخارجه عند الأردن '),
(21286, 'Joshua', 6, 19, 34, ' ورجع التخم غربا إلى أزنوت تابور ، وخرج من هناك إلى حقوق ووصل إلى زبولون جنوبا ، ووصل إلى أشير غربا ، وإلى يهوذا الأردن نحو شروق الشمس '),
(21287, 'Joshua', 6, 19, 35, ' ومدن محصنة : الصديم وصير وحمة ورقة وكنارة '),
(21288, 'Joshua', 6, 19, 36, ' وأدامة والرامة وحاصور '),
(21289, 'Joshua', 6, 19, 37, ' وقادش وإذرعي وعين حاصور '),
(21290, 'Joshua', 6, 19, 38, ' ويرأون ومجدل إيل وحوريم وبيت عناة وبيت شمس . تسع عشرة مدينة مع ضياعها '),
(21291, 'Joshua', 6, 19, 39, ' هذا هو نصيب سبط بني نفتالي حسب عشائرهم . المدن مع ضياعها '),
(21292, 'Joshua', 6, 19, 40, ' لسبط بني دان حسب عشائرهم خرجت القرعة السابعة '),
(21293, 'Joshua', 6, 19, 41, ' وكان تخم نصيبهم صرعة وأشتأول وعير شمس '),
(21294, 'Joshua', 6, 19, 42, ' وشعلبين وأيلون ويتلة '),
(21295, 'Joshua', 6, 19, 43, ' وإيلون وتمنة وعقرون '),
(21296, 'Joshua', 6, 19, 44, ' وإلتقيه وجبثون وبعلة '),
(21297, 'Joshua', 6, 19, 45, ' ويهود وبني برق وجت رمون '),
(21298, 'Joshua', 6, 19, 46, ' ومياه اليرقون والرقون مع التخوم التي مقابل يافا '),
(21299, 'Joshua', 6, 19, 47, ' وخرج تخم بني دان منهم وصعد بنو دان ، وحاربوا لشم وأخذوها وضربوها بحد السيف وملكوها وسكنوها ، ودعوا لشم دان ، كاسم دان أبيهم '),
(21300, 'Joshua', 6, 19, 48, ' هذا هو نصيب سبط بني دان حسب عشائرهم . هذه المدن مع ضياعها '),
(21301, 'Joshua', 6, 19, 49, ' ولما انتهوا من قسمة الأرض حسب تخومها ، أعطى بنو إسرائيل يشوع بن نون نصيبا في وسطهم '),
(21302, 'Joshua', 6, 19, 50, ' حسب قول الرب أعطوه المدينة التي طلب : تمنة سارح في جبل أفرايم ، فبنى المدينة وسكن بها '),
(21303, 'Joshua', 6, 19, 51, ' هذه هي الأنصبة التي قسمها ألعازار الكاهن ويشوع بن نون ورؤساء آباء أسباط بني إسرائيل بالقرعة في شيلوه أمام الرب لدى باب خيمة الاجتماع ، وانتهوا من قسمة الأرض '),
(21304, 'Joshua', 6, 20, 1, ' وكلم الرب يشوع قائلا '),
(21305, 'Joshua', 6, 20, 2, ' كلم بني إسرائيل قائلا : اجعلوا لأنفسكم مدن الملجإ كما كلمتكم على يد موسى 3لكي يهرب إليها القاتل ضارب نفس سهوا بغير علم ، فتكون لكم ملجأ من ولي الدم '),
(21306, 'Joshua', 6, 20, 4, ' فيهرب إلى واحدة من هذه المدن ، ويقف في مدخل باب المدينة ويتكلم بدعواه في آذان شيوخ تلك المدينة ، فيضمونه إليهم إلى المدينة ويعطونه مكانا فيسكن معهم '),
(21307, 'Joshua', 6, 20, 5, ' وإذا تبعه ولي الدم فلا يسلموا القاتل بيده لأنه بغير علم ضرب قريبه ، وهو غير مبغض له من قبل '),
(21308, 'Joshua', 6, 20, 6, ' ويسكن في تلك المدينة حتى يقف أمام الجماعة للقضاء ، إلى أن يموت الكاهن العظيم الذي يكون في تلك الأيام . حينئذ يرجع القاتل ويأتي إلى مدينته وبيته ، إلى المدينة التي هرب منها '),
(21309, 'Joshua', 6, 20, 7, ' فقدسوا قادش في الجليل في جبل نفتالي ، وشكيم في جبل أفرايم ، وقرية أربع ، هي حبرون ، في جبل يهوذا '),
(21310, 'Joshua', 6, 20, 8, ' وفي عبر أردن أريحا نحو الشروق جعلوا باصر في البرية في السهل من سبط رأوبين ، وراموت في جلعاد من سبط جاد ، وجولان في باشان من سبط منسى '),
(21311, 'Joshua', 6, 20, 9, ' هذه هي مدن الملجإ لكل بني إسرائيل وللغريب النازل في وسطهم لكي يهرب إليها كل ضارب نفس سهوا ، فلا يموت بيد ولي الدم حتى يقف أمام الجماعة '),
(21312, 'Joshua', 6, 21, 1, ' ثم تقدم رؤساء آباء اللاويين إلى ألعازار الكاهن وإلى يشوع بن نون وإلى رؤساء آباء أسباط بني إسرائيل '),
(21313, 'Joshua', 6, 21, 2, ' وكلموهم في شيلوه في أرض كنعان قائلين : قد أمر الرب على يد موسى أن نعطى مدنا للسكن مع مسارحها لبهائمنا '),
(21314, 'Joshua', 6, 21, 3, ' فأعطى بنو إسرائيل اللاويين من نصيبهم ، حسب قول الرب ، هذه المدن مع مسارحها '),
(21315, 'Joshua', 6, 21, 4, ' فخرجت القرعة لعشائر القهاتيين . فكان لبني هارون الكاهن من اللاويين بالقرعة ثلاث عشرة مدينة من سبط يهوذا ومن سبط شمعون ومن سبط بنيامين '),
(21316, 'Joshua', 6, 21, 5, ' ولبني قهات الباقين عشر مدن بالقرعة من عشائر سبط أفرايم ومن سبط دان ومن نصف سبط منسى '),
(21317, 'Joshua', 6, 21, 6, ' ولبني جرشون ثلاث عشرة مدينة بالقرعة من عشائر سبط يساكر ومن سبط أشير ومن سبط نفتالي ومن نصف سبط منسى في باشان '),
(21318, 'Joshua', 6, 21, 7, ' ولبني مراري حسب عشائرهم اثنتا عشرة مدينة من سبط رأوبين ومن سبط جاد ومن سبط زبولون '),
(21319, 'Joshua', 6, 21, 8, ' فأعطى بنو إسرائيل اللاويين هذه المدن ومسارحها بالقرعة ، كما أمر الرب على يد موسى '),
(21320, 'Joshua', 6, 21, 9, ' وأعطوا من سبط بني يهوذا ومن سبط بني شمعون هذه المدن المسماة بأسمائها '),
(21321, 'Joshua', 6, 21, 10, ' فكانت لبني هارون من عشائر القهاتيين من بني لاوي ، لأن القرعة الأولى كانت لهم '),
(21322, 'Joshua', 6, 21, 11, ' وأعطوهم قرية أربع أبي عناق ، هي حبرون ، في جبل يهوذا مع مسرحها حواليها '),
(21323, 'Joshua', 6, 21, 12, ' وأما حقل المدينة وضياعها فأعطوها لكالب بن يفنة ملكا له '),
(21324, 'Joshua', 6, 21, 13, ' وأعطوا لبني هارون الكاهن مدينة ملجإ القاتل حبرون مع مسارحها ، ولبنة ومسارحها '),
(21325, 'Joshua', 6, 21, 14, ' ويتير ومسرحها ، وأشتموع ومسرحها '),
(21326, 'Joshua', 6, 21, 15, ' وحولون ومسرحها ، ودبير ومسرحها '),
(21327, 'Joshua', 6, 21, 16, ' وعين ومسرحها ، ويطة ومسرحها ، وبيت شمس ومسرحها . تسع مدن من هذين السبطين '),
(21328, 'Joshua', 6, 21, 17, ' ومن سبط بنيامين : جبعون ومسرحها ، وجبع ومسرحها '),
(21329, 'Joshua', 6, 21, 18, ' عناثوث ومسرحها ، وعلمون ومسرحها . أربع مدن '),
(21330, 'Joshua', 6, 21, 19, ' جميع مدن بني هارون الكهنة ثلاث عشرة مدينة مع مسارحها '),
(21331, 'Joshua', 6, 21, 20, ' وأما عشائر بني قهات ، اللاويين الباقين من بني قهات ، فكانت مدن قرعتهم من سبط أفرايم '),
(21332, 'Joshua', 6, 21, 21, ' وأعطوهم شكيم ومسرحها ، في جبل أفرايم مدينة ملجإ القاتل ، وجازر ومسرحها '),
(21333, 'Joshua', 6, 24, 2, ' وقال يشوع لجميع الشعب : هكذا قال الرب إله إسرائيل : آباؤكم سكنوا في عبر النهر منذ الدهر . تارح أبو إبراهيم وأبو ناحور ، وعبدوا آلهة أخرى '),
(21334, 'Joshua', 6, 24, 3, ' فأخذت إبراهيم أباكم من عبر النهر وسرت به في كل أرض كنعان ، وأكثرت نسله وأعطيته إسحاق '),
(21335, 'Joshua', 6, 24, 4, ' وأعطيت إسحاق يعقوب وعيسو ، وأعطيت عيسو جبل سعير ليملكه . وأما يعقوب وبنوه فنزلوا إلى مصر '),
(21336, 'Joshua', 6, 24, 5, ' وأرسلت موسى وهارون وضربت مصر حسب ما فعلت في وسطها ، ثم أخرجتكم '),
(21337, 'Joshua', 6, 24, 6, ' فأخرجت آباءكم من مصر ، ودخلتم البحر وتبع المصريون آباءكم بمركبات وفرسان إلى بحر سوف '),
(21338, 'Joshua', 6, 24, 7, ' فصرخوا إلى الرب ، فجعل ظلاما بينكم وبين المصريين ، وجلب عليهم البحر فغطاهم . ورأت أعينكم ما فعلت في مصر ، وأقمتم في القفر أياما كثيرة '),
(21339, 'Joshua', 6, 24, 8, ' ثم أتيت بكم إلى أرض الأموريين الساكنين في عبر الأردن فحاربوكم ، ودفعتهم بيدكم فملكتم أرضهم وأهلكتهم من أمامكم '),
(21340, 'Joshua', 6, 24, 9, ' وقام بالاق بن صفور ملك موآب وحارب إسرائيل ، وأرسل ودعا بلعام بن بعور لكي يلعنكم '),
(21341, 'Joshua', 6, 24, 10, ' ولم أشأ أن أسمع لبلعام ، فبارككم بركة وأنقذتكم من يده '),
(21342, 'Joshua', 6, 24, 11, ' ثم عبرتم الأردن وأتيتم إلى أريحا . فحاربكم أصحاب أريحا : الأموريون والفرزيون والكنعانيون والحثيون والجرجاشيون والحويون واليبوسيون ، فدفعتهم بيدكم '),
(21343, 'Joshua', 6, 24, 12, ' وأرسلت قدامكم الزنابير وطردتهم من أمامكم ، أي ملكي الأموريين ، لا بسيفك ولا بقوسك '),
(21344, 'Joshua', 6, 24, 13, ' وأعطيتكم أرضا لم تتعبوا عليها ، ومدنا لم تبنوها وتسكنون بها ، ومن كروم وزيتون لم تغرسوها تأكلون '),
(21345, 'Joshua', 6, 24, 14, ' فالآن اخشوا الرب واعبدوه بكمال وأمانة ، وانزعوا الآلهة الذين عبدهم آباؤكم في عبر النهر وفي مصر ، واعبدوا الرب '),
(21346, 'Joshua', 6, 24, 15, ' وإن ساء في أعينكم أن تعبدوا الرب ، فاختاروا لأنفسكم اليوم من تعبدون : إن كان الآلهة الذين عبدهم آباؤكم الذين في عبر النهر ، وإن كان آلهة الأموريين الذين أنتم ساكنون في أرضهم . وأما أنا وبيتي فنعبد الرب '),
(21347, 'Joshua', 6, 24, 16, ' فأجاب الشعب وقالوا : حاشا لنا أن نترك الرب لنعبد آلهة أخرى '),
(21348, 'Joshua', 6, 24, 17, ' لأن الرب إلهنا هو الذي أصعدنا وآباءنا من أرض مصر من بيت العبودية ، والذي عمل أمام أعيننا تلك الآيات العظيمة ، وحفظنا في كل الطريق التي سرنا فيها وفي جميع الشعوب الذين عبرنا في وسطهم '),
(21349, 'Joshua', 6, 24, 18, ' وطرد الرب من أمامنا جميع الشعوب ، والأموريين الساكنين الأرض . فنحن أيضا نعبد الرب لأنه هو إلهنا '),
(21350, 'Joshua', 6, 24, 19, ' فقال يشوع للشعب : لا تقدرون أن تعبدوا الرب لأنه إله قدوس وإله غيور هو . لا يغفر ذنوبكم وخطاياكم '),
(21351, 'Joshua', 6, 24, 20, ' وإذا تركتم الرب وعبدتم آلهة غريبة يرجع فيسيء إليكم ويفنيكم بعد أن أحسن إليكم '),
(21352, 'Joshua', 6, 24, 21, ' فقال الشعب ليشوع : لا . بل الرب نعبد '),
(21353, 'Joshua', 6, 24, 22, ' فقال يشوع للشعب : أنتم شهود على أنفسكم أنكم قد اخترتم لأنفسكم الرب لتعبدوه . فقالوا : نحن شهود '),
(21354, 'Joshua', 6, 24, 23, ' فالآن انزعوا الآلهة الغريبة التي في وسطكم وأميلوا قلوبكم إلى الرب إله إسرائيل '),
(21355, 'Joshua', 6, 24, 24, ' فقال الشعب ليشوع : الرب إلهنا نعبد ولصوته نسمع '),
(21356, 'Joshua', 6, 24, 25, ' وقطع يشوع عهدا للشعب في ذلك اليوم ، وجعل لهم فريضة وحكما في شكيم '),
(21357, 'Joshua', 6, 24, 26, ' وكتب يشوع هذا الكلام في سفر شريعة الله . وأخذ حجرا كبيرا ونصبه هناك تحت البلوطة التي عند مقدس الرب '),
(21358, 'Joshua', 6, 24, 27, ' ثم قال يشوع لجميع الشعب : إن هذا الحجر يكون شاهدا علينا ، لأنه قد سمع كل كلام الرب الذي كلمنا به ، فيكون شاهدا عليكم لئلا تجحدوا إلهكم '),
(21359, 'Joshua', 6, 24, 28, ' ثم صرف يشوع الشعب كل واحد إلى ملكه '),
(21360, 'Joshua', 6, 24, 29, ' وكان بعد هذا الكلام أنه مات يشوع بن نون عبد الرب ابن مئة وعشر سنين '),
(21361, 'Joshua', 6, 24, 30, ' فدفنوه في تخم ملكه ، في تمنة سارح التي في جبل أفرايم شمالي جبل جاعش '),
(21362, 'Joshua', 6, 24, 31, ' وعبد إسرائيل الرب كل أيام يشوع ، وكل أيام الشيوخ الذين طالت أيامهم بعد يشوع والذين عرفوا كل عمل الرب الذي عمله لإسرائيل '),
(21363, 'Joshua', 6, 24, 32, ' وعظام يوسف التي أصعدها بنو إسرائيل من مصر دفنوها في شكيم ، في قطعة الحقل التي اشتراها يعقوب من بني حمور أبي شكيم بمئة قسيطة ، فصارت لبني يوسف ملكا '),
(21364, 'Joshua', 6, 24, 33, ' ومات ألعازار بن هارون فدفنوه في جبعة فينحاس ابنه التي أعطيت له في جبل أفرايم '),
(21365, 'Jude', 65, 1, 1, ' يهوذا ، عبد يسوع المسيح ، وأخو يعقوب ، إلى المدعوين المقدسين في الله الآب ، والمحفوظين ليسوع المسيح '),
(21366, 'Jude', 65, 1, 2, ' لتكثر لكم الرحمة والسلام والمحبة '),
(21367, 'Jude', 65, 1, 3, ' أيها الأحباء ، إذ كنت أصنع كل الجهد لأكتب إليكم عن الخلاص المشترك ، اضطررت أن أكتب إليكم واعظا أن تجتهدوا لأجل الإيمان المسلم مرة للقديسين '),
(21368, 'Jude', 65, 1, 4, ' لأنه دخل خلسة أناس قد كتبوا منذ القديم لهذه الدينونة ، فجار ، يحولون نعمة إلهنا إلى الدعارة ، وينكرون السيد الوحيد : الله وربنا يسوع المسيح '),
(21369, 'Jude', 65, 1, 5, ' فأريد أن أذكركم ، ولو علمتم هذا مرة ، أن الرب بعدما خلص الشعب من أرض مصر ، أهلك أيضا الذين لم يؤمنوا '),
(21370, 'Jude', 65, 1, 6, ' والملائكة الذين لم يحفظوا رياستهم ، بل تركوا مسكنهم حفظهم إلى دينونة اليوم العظيم بقيود أبدية تحت الظلام '),
(21371, 'Jude', 65, 1, 7, ' كما أن سدوم وعمورة والمدن التي حولهما ، إذ زنت على طريق مثلهما ، ومضت وراء جسد آخر ، جعلت عبرة مكابدة عقاب نار أبدية '),
(21372, 'Jude', 65, 1, 8, ' ولكن كذلك هؤلاء أيضا ، المحتلمون ، ينجسون الجسد ، ويتهاونون بالسيادة ، ويفترون على ذوي الأمجاد '),
(21373, 'Jude', 65, 1, 9, ' وأما ميخائيل رئيس الملائكة ، فلما خاصم إبليس محاجا عن جسد موسى ، لم يجسر أن يورد حكم افتراء ، بل قال : لينتهرك الرب '),
(21374, 'Jude', 65, 1, 10, ' ولكن هؤلاء يفترون على ما لا يعلمون . وأما ما يفهمونه بالطبيعة ، كالحيوانات غير الناطقة ، ففي ذلك يفسدون '),
(21375, 'Jude', 65, 1, 11, ' ويل لهم لأنهم سلكوا طريق قايين ، وانصبوا إلى ضلالة بلعام لأجل أجرة ، وهلكوا في مشاجرة قورح '),
(21376, 'Jude', 65, 1, 12, ' هؤلاء صخور في ولائمكم المحبية ، صانعين ولائم معا بلا خوف ، راعين أنفسهم . غيوم بلا ماء تحملها الرياح . أشجار خريفية بلا ثمر ميتة مضاعفا ، مقتلعة '),
(21377, 'Jude', 65, 1, 13, ' أمواج بحر هائجة مزبدة بخزيهم . نجوم تائهة محفوظ لها قتام الظلام إلى الأبد '),
(21378, 'Jude', 65, 1, 14, ' وتنبأ عن هؤلاء أيضا أخنوخ السابع من آدم قائلا : هوذا قد جاء الرب في ربوات قديسيه '),
(21379, 'Jude', 65, 1, 15, ' ليصنع دينونة على الجميع ، ويعاقب جميع فجارهم على جميع أعمال فجورهم التي فجروا بها ، وعلى جميع الكلمات الصعبة التي تكلم بها عليه خطاة فجار '),
(21380, 'Jude', 65, 1, 16, ' هؤلاء هم مدمدمون متشكون ، سالكون بحسب شهواتهم ، وفمهم يتكلم بعظائم ، يحابون بالوجوه من أجل المنفعة '),
(21381, 'Jude', 65, 1, 17, ' وأما أنتم أيها الأحباء فاذكروا الأقوال التي قالها سابقا رسل ربنا يسوع المسيح '),
(21382, 'Jude', 65, 1, 18, ' فإنهم قالوا لكم : إنه في الزمان الأخير سيكون قوم مستهزئون ، سالكين بحسب شهوات فجورهم '),
(21383, 'Jude', 65, 1, 19, ' هؤلاء هم المعتزلون بأنفسهم ، نفسانيون لا روح لهم '),
(21384, 'Jude', 65, 1, 20, ' وأما أنتم أيها الأحباء فابنوا أنفسكم على إيمانكم الأقدس ، مصلين في الروح القدس '),
(21385, 'Jude', 65, 1, 21, ' واحفظوا أنفسكم في محبة الله ، منتظرين رحمة ربنا يسوع المسيح للحياة الأبدية '),
(21386, 'Jude', 65, 1, 22, ' وارحموا البعض مميزين '),
(21387, 'Jude', 65, 1, 23, ' وخلصوا البعض بالخوف ، مختطفين من النار ، مبغضين حتى الثوب المدنس من الجسد '),
(21388, 'Jude', 65, 1, 24, ' والقادر أن يحفظكم غير عاثرين ، ويوقفكم أمام مجده بلا عيب في الابتهاج '),
(21389, 'Jude', 65, 1, 25, ' الإله الحكيم الوحيد مخلصنا ، له المجد والعظمة والقدرة والسلطان ، الآن وإلى كل الدهور . آمين '),
(21390, 'Judges', 7, 2, 8, ' ومات يشوع بن نون عبد الرب ابن مئة وعشر سنين '),
(21391, 'Judges', 7, 2, 9, ' فدفنوه في تخم ملكه في تمنة حارس في جبل أفرايم ، شمالي جبل جاعش '),
(21392, 'Judges', 7, 2, 10, ' وكل ذلك الجيل أيضا انضم إلى آبائه ، وقام بعدهم جيل آخر لم يعرف الرب ، ولا العمل الذي عمل لإسرائيل '),
(21393, 'Judges', 7, 2, 11, ' وفعل بنو إسرائيل الشر في عيني الرب وعبدوا البعليم '),
(21394, 'Judges', 7, 2, 12, ' وتركوا الرب إله آبائهم الذي أخرجهم من أرض مصر ، وساروا وراء آلهة أخرى من آلهة الشعوب الذين حولهم ، وسجدوا لها وأغاظوا الرب '),
(21395, 'Judges', 7, 2, 13, ' تركوا الرب وعبدوا البعل وعشتاروث '),
(21396, 'Judges', 7, 2, 14, ' فحمي غضب الرب على إسرائيل ، فدفعهم بأيدي ناهبين نهبوهم ، وباعهم بيد أعدائهم حولهم ، ولم يقدروا بعد على الوقوف أمام أعدائهم '),
(21397, 'Judges', 7, 2, 15, ' حيثما خرجوا كانت يد الرب عليهم للشر ، كما تكلم الرب وكما أقسم الرب لهم . فضاق بهم الأمر جدا '),
(21398, 'Judges', 7, 2, 16, ' وأقام الرب قضاة فخلصوهم من يد ناهبيهم '),
(21399, 'Judges', 7, 2, 17, ' ولقضاتهم أيضا لم يسمعوا ، بل زنوا وراء آلهة أخرى وسجدوا لها . حادوا سريعا عن الطريق التي سار بها آباؤهم لسمع وصايا الرب ، لم يفعلوا هكذا '),
(21400, 'Judges', 7, 2, 18, ' وحينما أقام الرب لهم قضاة ، كان الرب مع القاضي ، وخلصهم من يد أعدائهم كل أيام القاضي ، لأن الرب ندم من أجل أنينهم بسبب مضايقيهم وزاحميهم '),
(21401, 'Judges', 7, 2, 19, ' وعند موت القاضي كانوا يرجعون ويفسدون أكثر من آبائهم ، بالذهاب وراء آلهة أخرى ليعبدوها ويسجدوا لها . لم يكفوا عن أفعالهم وطريقهم القاسية '),
(21402, 'Judges', 7, 2, 20, ' فحمي غضب الرب على إسرائيل وقال : من أجل أن هذا الشعب قد تعدوا عهدي الذي أوصيت به آباءهم ولم يسمعوا لصوتي '),
(21403, 'Judges', 7, 2, 21, ' فأنا أيضا لا أعود أطرد إنسانا من أمامهم من الأمم الذين تركهم يشوع عند موته '),
(21404, 'Judges', 7, 2, 22, ' لكي أمتحن بهم إسرائيل : أيحفظون طريق الرب ليسلكوا بها كما حفظها آباؤهم ، أم لا '),
(21405, 'Judges', 7, 2, 23, ' فترك الرب أولئك الأمم ولم يطردهم سريعا ولم يدفعهم بيد يشوع '),
(21406, 'Judges', 7, 3, 1, ' فهؤلاء هم الأمم الذين تركهم الرب ليمتحن بهم إسرائيل ، كل الذين لم يعرفوا جميع حروب كنعان '),
(21407, 'Judges', 7, 3, 2, ' إنما لمعرفة أجيال بني إسرائيل لتعليمهم الحرب . الذين لم يعرفوها قبل فقط '),
(21408, 'Judges', 7, 3, 3, ' أقطاب الفلسطينيين الخمسة ، وجميع الكنعانيين والصيدونيين والحويين سكان جبل لبنان ، من جبل بعل حرمون إلى مدخل حماة '),
(21409, 'Judges', 7, 3, 4, ' كانوا لامتحان إسرائيل بهم ، لكي يعلم هل يسمعون وصايا الرب التي أوصى بها آباءهم عن يد موسى '),
(21410, 'Judges', 7, 3, 5, ' فسكن بنو إسرائيل في وسط الكنعانيين والحثيين والأموريين والفرزيين والحويين واليبوسيين '),
(21411, 'Judges', 7, 3, 6, ' واتخذوا بناتهم لأنفسهم نساء ، وأعطوا بناتهم لبنيهم وعبدوا آلهتهم '),
(21412, 'Judges', 7, 3, 7, ' فعمل بنو إسرائيل الشر في عيني الرب ، ونسوا الرب إلههم وعبدوا البعليم والسواري '),
(21413, 'Judges', 7, 3, 8, ' فحمي غضب الرب على إسرائيل ، فباعهم بيد كوشان رشعتايم ملك أرام النهرين . فعبد بنو إسرائيل كوشان رشعتايم ثماني سنين '),
(21414, 'Judges', 7, 3, 9, ' وصرخ بنو إسرائيل إلى الرب ، فأقام الرب مخلصا لبني إسرائيل فخلصهم ، عثنيئيل بن قناز أخا كالب الأصغر '),
(21415, 'Judges', 7, 3, 10, ' فكان عليه روح الرب ، وقضى لإسرائيل . وخرج للحرب فدفع الرب ليده كوشان رشعتايم ملك أرام ، واعتزت يده على كوشان رشعتايم '),
(21416, 'Judges', 7, 3, 11, ' واستراحت الأرض أربعين سنة . ومات عثنيئيل بن قناز '),
(21417, 'Judges', 7, 3, 12, ' وعاد بنو إسرائيل يعملون الشر في عيني الرب ، فشدد الرب عجلون ملك موآب على إسرائيل ، لأنهم عملوا الشر في عيني الرب '),
(21418, 'Judges', 7, 3, 13, ' فجمع إليه بني عمون وعماليق ، وسار وضرب إسرائيل ، وامتلكوا مدينة النخل '),
(21419, 'Judges', 7, 3, 14, ' فعبد بنو إسرائيل عجلون ملك موآب ثماني عشرة سنة '),
(21420, 'Judges', 7, 3, 15, ' وصرخ بنو إسرائيل إلى الرب ، فأقام لهم الرب مخلصا إهود بن جيرا البنياميني ، رجلا أعسر . فأرسل بنو إسرائيل بيده هدية لعجلون ملك موآب '),
(21421, 'Judges', 7, 3, 16, ' فعمل إهود لنفسه سيفا ، ذا حدين طوله ذراع ، وتقلده تحت ثيابه على فخذه اليمنى '),
(21422, 'Judges', 7, 3, 17, ' وقدم الهدية لعجلون ملك موآب . وكان عجلون رجلا سمينا جدا '),
(21423, 'Judges', 7, 3, 18, ' وكان لما انتهى من تقديم الهدية ، صرف القوم حاملي الهدية '),
(21424, 'Judges', 7, 3, 19, ' وأما هو فرجع من عند المنحوتات التي لدى الجلجال وقال : لي كلام سر إليك أيها الملك . فقال : صه . وخرج من عنده جميع الواقفين لديه '),
(21425, 'Judges', 7, 3, 20, ' فدخل إليه إهود وهو جالس في علية برود كانت له وحده . وقال إهود : عندي كلام الله إليك . فقام عن الكرسي '),
(21426, 'Judges', 7, 3, 21, ' فمد إهود يده اليسرى وأخذ السيف عن فخذه اليمنى وضربه في بطنه '),
(21427, 'Judges', 7, 3, 22, ' فدخل القائم أيضا وراء النصل ، وطبق الشحم وراء النصل لأنه لم يجذب السيف من بطنه . وخرج من الحتار '),
(21428, 'Judges', 7, 3, 23, ' فخرج إهود من الرواق وأغلق أبواب العلية وراءه وأقفلها '),
(21429, 'Judges', 7, 3, 24, ' ولما خرج ، جاء عبيده ونظروا وإذا أبواب العلية مقفلة ، فقالوا : إنه مغط رجليه في مخدع البرود '),
(21430, 'Judges', 7, 3, 25, ' فلبثوا حتى خجلوا وإذا هو لا يفتح أبواب العلية . فأخذوا المفتاح وفتحوا وإذا سيدهم ساقط على الأرض ميتا '),
(21431, 'Judges', 7, 3, 26, ' وأما إهود فنجا ، إذ هم مبهوتون ، وعبر المنحوتات ونجا إلى سعيرة '),
(21432, 'Judges', 7, 3, 27, ' وكان عند مجيئه أنه ضرب بالبوق في جبل أفرايم ، فنزل معه بنو إسرائيل عن الجبل وهو قدامهم '),
(21433, 'Judges', 7, 3, 28, ' وقال لهم : اتبعوني لأن الرب قد دفع أعداءكم الموآبيين ليدكم . فنزلوا وراءه وأخذوا مخاوض الأردن إلى موآب ، ولم يدعوا أحدا يعبر '),
(21434, 'Judges', 7, 3, 29, ' فضربوا من موآب في ذلك الوقت نحو عشرة آلاف رجل ، كل نشيط ، وكل ذي بأس ، ولم ينج أحد '),
(21435, 'Judges', 7, 3, 30, ' فذل الموآبيون في ذلك اليوم تحت يد إسرائيل . واستراحت الأرض ثمانين سنة '),
(21436, 'Judges', 7, 3, 31, ' وكان بعده شمجر بن عناة ، فضرب من الفلسطينيين ست مئة رجل بمنساس البقر . وهو أيضا خلص إسرائيل '),
(21437, 'Judges', 7, 4, 1, ' وعاد بنو إسرائيل يعملون الشر في عيني الرب بعد موت إهود '),
(21438, 'Judges', 7, 4, 2, ' فباعهم الرب بيد يابين ملك كنعان الذي ملك في حاصور . ورئيس جيشه سيسرا ، وهو ساكن في حروشة الأمم '),
(21439, 'Judges', 7, 4, 3, ' فصرخ بنو إسرائيل إلى الرب ، لأنه كان له تسع مئة مركبة من حديد ، وهو ضايق بني إسرائيل بشدة ، عشرين سنة '),
(21440, 'Judges', 7, 4, 4, ' ودبورة امرأة نبية زوجة لفيدوت ، هي قاضية إسرائيل في ذلك الوقت '),
(21441, 'Judges', 7, 4, 5, ' وهي جالسة تحت نخلة دبورة بين الرامة وبيت إيل في جبل أفرايم . وكان بنو إسرائيل يصعدون إليها للقضاء '),
(21442, 'Judges', 7, 4, 6, ' فأرسلت ودعت باراق بن أبينوعم من قادش نفتالي ، وقالت له : ألم يأمر الرب إله إسرائيل : اذهب وازحف إلى جبل تابور ، وخذ معك عشرة آلاف رجل من بني نفتالي ومن بني زبولون '),
(21443, 'Judges', 7, 4, 7, ' فأجذب إليك ، إلى نهر قيشون سيسرا رئيس جيش يابين بمركباته وجمهوره وأدفعه ليدك '),
(21444, 'Judges', 7, 4, 8, ' فقال لها باراق : إن ذهبت معي أذهب ، وإن لم تذهبي معي فلا أذهب '),
(21445, 'Judges', 7, 4, 9, ' فقالت : إني أذهب معك ، غير أنه لا يكون لك فخر في الطريق التي أنت سائر فيها . لأن الرب يبيع سيسرا بيد امرأة . فقامت دبورة وذهبت مع باراق إلى قادش '),
(21446, 'Judges', 7, 4, 10, ' ودعا باراق زبولون ونفتالي إلى قادش ، وصعد ومعه عشرة آلاف رجل . وصعدت دبورة معه '),
(21447, 'Judges', 7, 4, 11, ' وحابر القيني انفرد من قاين ، من بني حوباب حمي موسى ، وخيم حتى إلى بلوطة في صعنايم التي عند قادش '),
(21448, 'Judges', 7, 4, 12, ' وأخبروا سيسرا بأنه قد صعد باراق بن أبينوعم إلى جبل تابور '),
(21449, 'Judges', 7, 4, 13, ' فدعا سيسرا جميع مركباته ، تسع مئة مركبة من حديد ، وجميع الشعب الذي معه من حروشة الأمم إلى نهر قيشون '),
(21450, 'Judges', 7, 4, 14, ' فقالت دبورة لباراق : قم ، لأن هذا هو اليوم الذي دفع فيه الرب سيسرا ليدك . ألم يخرج الرب قدامك ؟ فنزل باراق من جبل تابور ووراءه عشرة آلاف رجل '),
(21451, 'Judges', 7, 4, 15, ' فأزعج الرب سيسرا وكل المركبات وكل الجيش بحد السيف أمام باراق . فنزل سيسرا عن المركبة وهرب على رجليه '),
(21452, 'Judges', 7, 4, 16, ' وتبع باراق المركبات والجيش إلى حروشة الأمم . وسقط كل جيش سيسرا بحد السيف . لم يبق ولا واحد '),
(21453, 'Judges', 7, 4, 17, ' وأما سيسرا فهرب على رجليه إلى خيمة ياعيل امرأة حابر القيني ، لأنه كان صلح بين يابين ملك حاصور وبيت حابر القيني ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(21454, 'Judges', 7, 4, 18, ' فخرجت ياعيل لاستقبال سيسرا وقالت له : مل يا سيدي ، مل إلي . لا تخف . فمال إليها إلى الخيمة وغطته باللحاف '),
(21455, 'Judges', 7, 4, 19, ' فقال لها : اسقيني قليل ماء لأني قد عطشت . ففتحت وطب اللبن وأسقته ثم غطته '),
(21456, 'Judges', 7, 4, 20, ' فقال لها : قفي بباب الخيمة ، ويكون إذا جاء أحد وسألك : أهنا رجل ؟ أنك تقولين لا '),
(21457, 'Judges', 7, 4, 21, ' فأخذت ياعيل امرأة حابر وتد الخيمة وجعلت الميتدة في يدها ، وقارت إليه وضربت الوتد في صدغه فنفذ إلى الأرض ، وهو متثقل في النوم ومتعب ، فمات '),
(21458, 'Judges', 7, 4, 22, ' وإذا بباراق يطارد سيسرا ، فخرجت ياعيل لاستقباله وقالت له : تعال فأريك الرجل الذي أنت طالبه . فجاء إليها وإذا سيسرا ساقط ميتا والوتد في صدغه '),
(21459, 'Judges', 7, 4, 23, ' فأذل الله في ذلك اليوم يابين ملك كنعان أمام بني إسرائيل '),
(21460, 'Judges', 7, 4, 24, ' وأخذت يد بني إسرائيل تتزايد وتقسو على يابين ملك كنعان حتى قرضوا يابين ملك كنعان '),
(21461, 'Judges', 7, 5, 1, ' فترنمت دبورة وباراق بن أبينوعم في ذلك اليوم قائلين '),
(21462, 'Judges', 7, 5, 2, ' لأجل قيادة القواد في إسرائيل ، لأجل انتداب الشعب ، باركوا الرب '),
(21463, 'Judges', 7, 5, 3, ' اسمعوا أيها الملوك واصغوا أيها العظماء . أنا ، أنا للرب أترنم . أزمر للرب إله إسرائيل '),
(21464, 'Judges', 7, 5, 4, ' يارب بخروجك من سعير ، بصعودك من صحراء أدوم ، الأرض ارتعدت . السماوات أيضا قطرت . كذلك السحب قطرت ماء '),
(21465, 'Judges', 7, 5, 5, ' تزلزلت الجبال من وجه الرب ، وسيناء هذا من وجه الرب إله إسرائيل '),
(21466, 'Judges', 7, 5, 6, ' في أيام شمجر بن عناة ، في أيام ياعيل ، استراحت الطرق ، وعابرو السبل ساروا في مسالك معوجة '),
(21467, 'Judges', 7, 5, 7, ' خذل الحكام في إسرائيل . خذلوا حتى قمت أنا دبورة . قمت أما في إسرائيل '),
(21468, 'Judges', 7, 5, 8, ' اختار آلهة حديثة . حينئذ حرب الأبواب . هل كان يرى مجن أو رمح في أربعين ألفا من إسرائيل '),
(21469, 'Judges', 7, 5, 9, ' قلبي نحو قضاة إسرائيل المنتدبين في الشعب . باركوا الرب '),
(21470, 'Judges', 7, 5, 10, ' أيها الراكبون الأتن الصحر ، الجالسون على طنافس ، والسالكون في الطريق ، سبحوا '),
(21471, 'Judges', 7, 5, 11, ' من صوت المحاصين بين الأحواض هناك يثنون على حق الرب ، حق حكامه في إسرائيل . حينئذ نزل شعب الرب إلى الأبواب '),
(21472, 'Judges', 7, 5, 12, ' استيقظي ، استيقظي يا دبورة استيقظي ، استيقظي وتكلمي بنشيد قم يا باراق واسب سبيك ، يا ابن أبينوعم '),
(21473, 'Judges', 7, 5, 13, ' حينئذ تسلط الشارد على عظماء الشعب . الرب سلطني على الجبابرة '),
(21474, 'Judges', 7, 5, 14, ' جاء من أفرايم الذين مقرهم بين عماليق ، وبعدك بنيامين مع قومك . من ماكير نزل قضاة ، ومن زبولون ماسكون بقضيب القائد '),
(21475, 'Judges', 7, 5, 15, ' والرؤساء في يساكر مع دبورة . وكما يساكر هكذا باراق . اندفع إلى الوادي وراءه . على مساقي رأوبين أقضية قلب عظيمة '),
(21476, 'Judges', 7, 5, 16, ' لماذا أقمت بين الحظائر لسمع الصفير للقطعان . لدى مساقي رأوبين مباحث قلب عظيمة '),
(21477, 'Judges', 7, 5, 17, ' جلعاد في عبر الأردن سكن . ودان ، لماذا استوطن لدى السفن ؟ وأشير أقام على ساحل البحر ، وفي فرضه سكن '),
(21478, 'Judges', 7, 5, 18, ' زبولون شعب أهان نفسه إلى الموت مع نفتالي على روابي الحقل '),
(21479, 'Judges', 7, 5, 19, ' جاء ملوك . حاربوا . حينئذ حارب ملوك كنعان في تعنك على مياه مجدو . بضع فضة لم يأخذوا '),
(21480, 'Judges', 7, 5, 20, ' من السماوات حاربوا . الكواكب من حبكها حاربت سيسرا '),
(21481, 'Judges', 7, 5, 21, ' نهر قيشون جرفهم . نهر وقائع نهر قيشون . دوسي يا نفسي بعز '),
(21482, 'Judges', 7, 5, 22, ' حينئذ ضربت أعقاب الخيل من السوق ، سوق أقويائه '),
(21483, 'Judges', 7, 5, 23, ' العنوا ميروز قال ملاك الرب . العنوا ساكنيها لعنا ، لأنهم لم يأتوا لمعونة الرب ، معونة الرب بين الجبابرة '),
(21484, 'Judges', 7, 5, 24, ' تبارك على النساء ياعيل امرأة حابر القيني . على النساء في الخيام تبارك '),
(21485, 'Judges', 7, 5, 25, ' طلب ماء فأعطته لبنا . في قصعة العظماء قدمت زبدة '),
(21486, 'Judges', 7, 5, 26, ' مدت يدها إلى الوتد ، ويمينها إلى مضراب العملة ، وضربت سيسرا وسحقت رأسه ، شدخت وخرقت صدغه '),
(21487, 'Judges', 7, 5, 27, ' بين رجليها انطرح ، سقط ، اضطجع . بين رجليها انطرح ، سقط . حيث انطرح فهناك سقط مقتولا '),
(21488, 'Judges', 7, 5, 28, ' من الكوة أشرفت وولولت أم سيسرا من الشباك : لماذا أبطأت مركباته عن المجيء ؟ لماذا تأخرت خطوات مراكبه '),
(21489, 'Judges', 7, 5, 29, ' فأجابتها أحكم سيداتها ، بل هي ردت جوابا لنفسها '),
(21490, 'Judges', 7, 5, 30, ' ألم يجدوا ويقسموا الغنيمة فتاة أو فتاتين لكل رجل غنيمة ثياب مصبوغة لسيسرا غنيمة ثياب مصبوغة مطرزة ثياب مصبوغة مطرزة الوجهين غنيمة لعنقي '),
(21491, 'Judges', 7, 5, 31, ' هكذا يبيد جميع أعدائك يارب . وأحباؤه كخروج الشمس في جبروتها . واستراحت الأرض أربعين سنة '),
(21492, 'Judges', 7, 6, 1, ' وعمل بنو إسرائيل الشر في عيني الرب ، فدفعهم الرب ليد مديان سبع سنين '),
(21493, 'Judges', 7, 6, 2, ' فاعتزت يد مديان على إسرائيل . بسبب المديانيين عمل بنو إسرائيل لأنفسهم الكهوف التي في الجبال والمغاير والحصون '),
(21494, 'Judges', 7, 6, 3, ' وإذا زرع إسرائيل ، كان يصعد المديانيون والعمالقة وبنو المشرق ، يصعدون عليهم '),
(21495, 'Judges', 7, 6, 4, ' وينزلون عليهم ويتلفون غلة الأرض إلى مجيئك إلى غزة ، ولا يتركون لإسرائيل قوت الحياة ، ولا غنما ولا بقرا ولا حميرا '),
(21496, 'Judges', 7, 6, 5, ' لأنهم كانوا يصعدون بمواشيهم وخيامهم ويجيئون كالجراد في الكثرة وليس لهم ولجمالهم عدد ، ودخلوا الأرض لكي يخربوها '),
(21497, 'Judges', 7, 6, 6, ' فذل إسرائيل جدا من قبل المديانيين . وصرخ بنو إسرائيل إلى الرب '),
(21498, 'Judges', 7, 6, 7, ' وكان لما صرخ بنو إسرائيل إلى الرب بسبب المديانيين '),
(21499, 'Judges', 7, 6, 8, ' أن الرب أرسل رجلا نبيا إلى بني إسرائيل ، فقال لهم : هكذا قال الرب إله إسرائيل : إني قد أصعدتكم من مصر وأخرجتكم من بيت العبودية '),
(21500, 'Judges', 7, 6, 9, ' وأنقذتكم من يد المصريين ومن يد جميع مضايقيكم ، وطردتهم من أمامكم وأعطيتكم أرضهم '),
(21501, 'Judges', 7, 6, 10, ' وقلت لكم : أنا الرب إلهكم . لا تخافوا آلهة الأموريين الذين أنتم ساكنون أرضهم . ولم تسمعوا لصوتي '),
(21502, 'Judges', 7, 6, 11, ' وأتى ملاك الرب وجلس تحت البطمة التي في عفرة التي ليوآش الأبيعزري . وابنه جدعون كان يخبط حنطة في المعصرة لكي يهربها من المديانيين '),
(21503, 'Judges', 7, 6, 12, ' فظهر له ملاك الرب وقال له : الرب معك يا جبار البأس '),
(21504, 'Judges', 7, 6, 13, ' فقال له جدعون : أسألك يا سيدي ، إذا كان الرب معنا فلماذا أصابتنا كل هذه ؟ وأين كل عجائبه التي أخبرنا بها آباؤنا قائلين : ألم يصعدنا الرب من مصر ؟ والآن قد رفضنا الرب وجعلنا في كف مديان '),
(21505, 'Judges', 7, 6, 14, ' فالتفت إليه الرب وقال : اذهب بقوتك هذه وخلص إسرائيل من كف مديان . أما أرسلتك '),
(21506, 'Judges', 7, 6, 15, ' فقال له : أسألك يا سيدي ، بماذا أخلص إسرائيل ؟ ها عشيرتي هي الذلى في منسى ، وأنا الأصغر في بيت أبي '),
(21507, 'Judges', 7, 6, 16, ' فقال له الرب : إني أكون معك ، وستضرب المديانيين كرجل واحد '),
(21508, 'Judges', 7, 6, 17, ' فقال له : إن كنت قد وجدت نعمة في عينيك فاصنع لي علامة أنك أنت تكلمني '),
(21509, 'Judges', 7, 6, 18, ' لا تبرح من ههنا حتى آتي إليك وأخرج تقدمتي وأضعها أمامك . فقال : إني أبقى حتى ترجع '),
(21510, 'Judges', 7, 6, 19, ' فدخل جدعون وعمل جدي معزى وإيفة دقيق فطيرا . أما اللحم فوضعه في سل ، وأما المرق فوضعه في قدر ، وخرج بها إليه إلى تحت البطمة وقدمها '),
(21511, 'Judges', 7, 6, 20, ' فقال له ملاك الله : خذ اللحم والفطير وضعهما على تلك الصخرة واسكب المرق . ففعل كذلك '),
(21512, 'Judges', 7, 6, 21, ' فمد ملاك الرب طرف العكاز الذي بيده ومس اللحم والفطير ، فصعدت نار من الصخرة وأكلت اللحم والفطير . وذهب ملاك الرب عن عينيه '),
(21513, 'Judges', 7, 6, 22, ' فرأى جدعون أنه ملاك الرب ، فقال جدعون : آه يا سيدي الرب لأني قد رأيت ملاك الرب وجها لوجه '),
(21514, 'Judges', 7, 6, 23, ' فقال له الرب : السلام لك . لا تخف . لا تموت '),
(21515, 'Judges', 7, 6, 24, ' فبنى جدعون هناك مذبحا للرب ودعاه يهوه شلوم . إلى هذا اليوم لم يزل في عفرة الأبيعزريين '),
(21516, 'Judges', 7, 6, 25, ' وكان في تلك الليلة أن الرب قال له : خذ ثور البقر الذي لأبيك ، وثورا ثانيا ابن سبع سنين ، واهدم مذبح البعل الذي لأبيك ، واقطع السارية التي عنده '),
(21517, 'Judges', 7, 6, 26, ' وابن مذبحا للرب إلهك على رأس هذا الحصن بترتيب ، وخذ الثور الثاني وأصعد محرقة على حطب السارية التي تقطعها '),
(21518, 'Judges', 7, 6, 27, ' فأخذ جدعون عشرة رجال من عبيده وعمل كما كلمه الرب . وإذ كان يخاف من بيت أبيه وأهل المدينة أن يعمل ذلك نهارا ، فعمله ليلا '),
(21519, 'Judges', 7, 6, 28, ' فبكر أهل المدينة في الغد وإذا بمذبح البعل قد هدم والسارية التي عنده قد قطعت ، والثور الثاني قد أصعد على المذبح الذي بني '),
(21520, 'Judges', 7, 6, 29, ' فقالوا الواحد لصاحبه : من عمل هذا الأمر ؟ فسألوا وبحثوا فقالوا : إن جدعون بن يوآش قد فعل هذا الأمر '),
(21521, 'Judges', 7, 6, 30, ' فقال أهل المدينة ليوآش : أخرج ابنك لكي يموت ، لأنه هدم مذبح البعل وقطع السارية التي عنده '),
(21522, 'Judges', 7, 6, 31, ' فقال يوآش لجميع القائمين عليه : أنتم تقاتلون للبعل ، أم أنتم تخلصونه ؟ من يقاتل له يقتل في هذا الصباح . إن كان إلها فليقاتل لنفسه لأن مذبحه قد هدم '),
(21523, 'Judges', 7, 6, 32, ' فدعاه في ذلك اليوم يربعل قائلا : ليقاتله البعل لأنه قد هدم مذبحه '),
(21524, 'Judges', 7, 6, 33, ' واجتمع جميع المديانيين والعمالقة وبني المشرق معا وعبروا ونزلوا في وادي يزرعيل '),
(21525, 'Judges', 7, 6, 34, ' ولبس روح الرب جدعون فضرب بالبوق ، فاجتمع أبيعزر وراءه '),
(21526, 'Judges', 7, 6, 35, ' وأرسل رسلا إلى جميع منسى ، فاجتمع هو أيضا وراءه ، وأرسل رسلا إلى أشير وزبولون ونفتالي فصعدوا للقائهم '),
(21527, 'Judges', 7, 6, 36, ' وقال جدعون لله : إن كنت تخلص بيدي إسرائيل كما تكلمت '),
(21528, 'Judges', 7, 6, 37, ' فها إني واضع جزة الصوف في البيدر ، فإن كان طل على الجزة وحدها ، وجفاف على الأرض كلها ، علمت أنك تخلص بيدي إسرائيل كما تكلمت '),
(21529, 'Judges', 7, 6, 38, ' وكان كذلك . فبكر في الغد وضغط الجزة وعصر طلا من الجزة ، ملء قصعة ماء '),
(21530, 'Judges', 7, 6, 39, ' فقال جدعون لله : لا يحم غضبك علي فأتكلم هذه المرة فقط . أمتحن هذه المرة فقط بالجزة . فليكن جفاف في الجزة وحدها وعلى كل الأرض ليكن طل '),
(21531, 'Judges', 7, 6, 40, ' ففعل الله كذلك في تلك الليلة . فكان جفاف في الجزة وحدها وعلى الأرض كلها كان طل '),
(21532, 'Judges', 7, 7, 1, ' فبكر يربعل ، أي جدعون ، وكل الشعب الذي معه ونزلوا على عين حرود . وكان جيش المديانيين شماليهم عند تل مورة في الوادي '),
(21533, 'Judges', 7, 7, 2, ' وقال الرب لجدعون : إن الشعب الذي معك كثير علي لأدفع المديانيين بيدهم ، لئلا يفتخر علي إسرائيل قائلا : يدي خلصتني '),
(21534, 'Judges', 7, 7, 3, ' والآن ناد في آذان الشعب قائلا : من كان خائفا ومرتعدا فليرجع وينصرف من جبل جلعاد . فرجع من الشعب اثنان وعشرون ألفا . وبقي عشرة آلاف '),
(21535, 'Judges', 7, 7, 4, ' وقال الرب لجدعون : لم يزل الشعب كثيرا . انزل بهم إلى الماء فأنقيهم لك هناك . ويكون أن الذي أقول لك عنه : هذا يذهب معك ، فهو يذهب معك . وكل من أقول لك عنه : هذا لا يذهب معك فهو لا يذهب '),
(21536, 'Judges', 7, 7, 5, ' فنزل بالشعب إلى الماء . وقال الرب لجدعون : كل من يلغ بلسانه من الماء كما يلغ الكلب فأوقفه وحده . وكذا كل من جثا على ركبتيه للشرب '),
(21537, 'Judges', 7, 7, 6, ' وكان عدد الذين ولغوا بيدهم إلى فمهم ثلاث مئة رجل . وأما باقي الشعب جميعا فجثوا على ركبهم لشرب الماء '),
(21538, 'Judges', 7, 7, 7, ' فقال الرب لجدعون : بالثلاث مئة الرجل الذين ولغوا أخلصكم وأدفع المديانيين ليدك . وأما سائر الشعب فليذهبوا كل واحد إلى مكانه '),
(21539, 'Judges', 7, 7, 8, ' فأخذ الشعب زادا بيدهم مع أبواقهم . وأرسل سائر رجال إسرائيل كل واحد إلى خيمته ، وأمسك الثلاث مئة الرجل . وكانت محلة المديانيين تحته في الوادي '),
(21540, 'Judges', 7, 7, 9, ' وكان في تلك الليلة أن الرب قال له : قم انزل إلى المحلة ، لأني قد دفعتها إلى يدك '),
(21541, 'Judges', 7, 7, 10, ' وإن كنت خائفا من النزول ، فانزل أنت وفورة غلامك إلى المحلة '),
(21542, 'Judges', 7, 7, 11, ' وتسمع ما يتكلمون به ، وبعد تتشدد يداك وتنزل إلى المحلة . فنزل هو وفورة غلامه إلى آخر المتجهزين الذين في المحلة '),
(21543, 'Judges', 7, 7, 12, ' وكان المديانيون والعمالقة وكل بني المشرق حالين في الوادي كالجراد في الكثرة ، وجمالهم لا عدد لها كالرمل الذي على شاطئ البحر في الكثرة '),
(21544, 'Judges', 7, 7, 13, ' وجاء جدعون فإذا رجل يخبر صاحبه بحلم ويقول : هوذا قد حلمت حلما ، وإذا رغيف خبز شعير يتدحرج في محلة المديانيين ، وجاء إلى الخيمة وضربها فسقطت ، وقلبها إلى فوق فسقطت الخيمة '),
(21545, 'Judges', 7, 7, 14, ' فأجاب صاحبه وقال : ليس ذلك إلأ سيف جدعون بن يوآش رجل إسرائيل . قد دفع الله إلى يده المديانيين وكل الجيش '),
(21546, 'Judges', 7, 7, 15, ' وكان لما سمع جدعون خبر الحلم وتفسيره ، أنه سجد ورجع إلى محلة إسرائيل وقال : قوموا لأن الرب قد دفع إلى يدكم جيش المديانيين '),
(21547, 'Judges', 7, 7, 16, ' وقسم الثلاث مئة الرجل إلى ثلاث فرق ، وجعل أبواقا في أيديهم كلهم ، وجرارا فارغة ومصابيح في وسط الجرار '),
(21548, 'Judges', 7, 7, 17, ' وقال لهم : انظروا إلي وافعلوا كذلك . وها أنا آت إلى طرف المحلة ، فيكون كما أفعل أنكم هكذا تفعلون '),
(21549, 'Judges', 7, 7, 18, ' ومتى ضربت بالبوق أنا وكل الذين معي ، فاضربوا أنتم أيضا بالأبواق حول كل المحلة ، وقولوا : للرب ولجدعون '),
(21550, 'Judges', 7, 7, 19, ' فجاء جدعون والمئة الرجل الذين معه إلى طرف المحلة في أول الهزيع الأوسط ، وكانوا إذ ذاك قد أقاموا الحراس ، فضربوا بالأبواق وكسروا الجرار التي بأيديهم '),
(21551, 'Judges', 7, 7, 20, ' فضربت الفرق الثلاث بالأبواق وكسروا الجرار ، وأمسكوا المصابيح بأيديهم اليسرى والأبواق بأيديهم اليمنى ليضربوا بها ، وصرخوا : سيف للرب ولجدعون '),
(21552, 'Judges', 7, 7, 21, ' ووقفوا كل واحد في مكانه حول المحلة . فركض كل الجيش وصرخوا وهربوا '),
(21553, 'Judges', 7, 7, 22, ' وضرب الثلاث المئين بالأبواق ، وجعل الرب سيف كل واحد بصاحبه وبكل الجيش . فهرب الجيش إلى بيت شطة ، إلى صردة حتى إلى حافة آبل محولة ، إلى طباة '),
(21554, 'Judges', 7, 7, 23, ' فاجتمع رجال إسرائيل من نفتالي ومن أشير ومن كل منسى وتبعوا المديانيين '),
(21555, 'Judges', 7, 7, 24, ' فأرسل جدعون رسلا إلى كل جبل أفرايم قائلا : انزلوا للقاء المديانيين وخذوا منهم المياه إلى بيت بارة والأردن . فاجتمع كل رجال أفرايم وأخذوا المياه إلى بيت بارة والأردن '),
(21556, 'Judges', 7, 7, 25, ' وأمسكوا أميري المديانيين غرابا وذئبا ، وقتلوا غرابا على صخرة غراب ، وأما ذئب فقتلوه في معصرة ذئب . وتبعوا المديانيين وأتوا برأسي غراب وذئب إلى جدعون من عبر الأردن '),
(21557, 'Judges', 7, 8, 1, ' وقال له رجال أفرايم : ما هذا الأمر الذي فعلت بنا ، إذ لم تدعنا عند ذهابك لمحاربة المديانيين ؟  . وخاصموه بشدة '),
(21558, 'Judges', 7, 8, 2, ' فقال لهم : ماذا فعلت الآن نظيركم ؟ أليس خصاصة أفرايم خيرا من قطاف أبيعزر '),
(21559, 'Judges', 7, 8, 3, ' ليدكم دفع الله أميري المديانيين غرابا وذئبا . وماذا قدرت أن أعمل نظيركم ؟  . حينئذ ارتخت روحهم عنه عندما تكلم بهذا الكلام '),
(21560, 'Judges', 7, 8, 4, ' وجاء جدعون إلى الأردن وعبر هو والثلاث مئة الرجل الذين معه معيين ومطاردين '),
(21561, 'Judges', 7, 8, 5, ' فقال لأهل سكوت : أعطوا أرغفة خبز للقوم الذين معي لأنهم معيون ، وأنا ساع وراء زبح وصلمناع ملكي مديان '),
(21562, 'Judges', 7, 8, 6, ' فقال رؤساء سكوت : هل أيدي زبح وصلمناع بيدك الآن حتى نعطي جندك خبزا '),
(21563, 'Judges', 7, 8, 7, ' فقال جدعون : لذلك عندما يدفع الرب زبح وصلمناع بيدي أدرس لحمكم مع أشواك البرية بالنوارج '),
(21564, 'Judges', 7, 8, 8, ' وصعد من هناك إلى فنوئيل وكلمهم هكذا . فأجابه أهل فنوئيل كما أجاب أهل سكوت '),
(21565, 'Judges', 7, 8, 9, ' فكلم أيضا أهل فنوئيل قائلا : عند رجوعي بسلام أهدم هذا البرج '),
(21566, 'Judges', 7, 8, 10, ' وكان زبح وصلمناع في قرقر وجيشهما معهما نحو خمسة عشر ألفا ، كل الباقين من جميع جيش بني المشرق . والذين سقطوا مئة وعشرون ألف رجل مخترطي السيف '),
(21567, 'Judges', 7, 8, 11, ' وصعد جدعون في طريق ساكني الخيام شرقي نوبح ويجبهة ، وضرب الجيش وكان الجيش مطمئنا '),
(21568, 'Judges', 7, 8, 12, ' فهرب زبح وصلمناع ، فتبعهما وأمسك ملكي مديان زبح وصلمناع وأزعج كل الجيش '),
(21569, 'Judges', 7, 8, 13, ' ورجع جدعون بن يوآش من الحرب من عند عقبة حارس '),
(21570, 'Judges', 7, 8, 14, ' وأمسك غلاما من أهل سكوت وسأله ، فكتب له رؤساء سكوت وشيوخها ، سبعة وسبعين رجلا '),
(21571, 'Judges', 7, 8, 15, ' ودخل إلى أهل سكوت وقال : هوذا زبح وصلمناع اللذان عيرتموني بهما قائلين : هل أيدي زبح وصلمناع بيدك الآن حتى نعطي رجالك المعيين خبزا '),
(21572, 'Judges', 7, 8, 16, ' وأخذ شيوخ المدينة وأشواك البرية والنوارج وعلم بها أهل سكوت '),
(21573, 'Judges', 7, 8, 17, ' وهدم برج فنوئيل وقتل رجال المدينة '),
(21574, 'Judges', 7, 8, 18, ' وقال لزبح وصلمناع : كيف الرجال الذين قتلتماهم في تابور ؟ فقالا : مثلهم مثلك . كل واحد كصورة أولاد ملك '),
(21575, 'Judges', 7, 8, 19, ' فقال : هم إخوتي بنو أمي . حي هو الرب لو استحييتماهم لما قتلتكما '),
(21576, 'Judges', 7, 8, 20, ' وقال ليثر بكره : قم اقتلهما . فلم يخترط الغلام سيفه ، لأنه خاف ، بما أنه فتى بعد '),
(21577, 'Judges', 7, 8, 21, ' فقال زبح وصلمناع : قم أنت وقع علينا ، لأنه مثل الرجل بطشه . فقام جدعون وقتل زبح وصلمناع ، وأخذ الأهلة التي في أعناق جمالهما '),
(21578, 'Judges', 7, 8, 22, ' وقال رجال إسرائيل لجدعون : تسلط علينا أنت وابنك وابن ابنك ، لأنك قد خلصتنا من يد مديان '),
(21579, 'Judges', 7, 8, 23, ' فقال لهم جدعون : لا أتسلط أنا عليكم ولا يتسلط ابني عليكم . الرب يتسلط عليكم '),
(21580, 'Judges', 7, 8, 24, ' ثم قال لهم جدعون : أطلب منكم طلبة : أن تعطوني كل واحد أقراط غنيمته . لأنه كان لهم أقراط ذهب لأنهم إسماعيليون '),
(21581, 'Judges', 7, 8, 25, ' فقالوا : إننا نعطي . وفرشوا رداء وطرحوا عليه كل واحد أقراط غنيمته '),
(21582, 'Judges', 7, 8, 26, ' وكان وزن أقراط الذهب التي طلب ألفا وسبع مئة شاقل ذهبا ، ما عدا الأهلة والحلق وأثواب الأرجوان التي على ملوك مديان ، وما عدا القلائد التي في أعناق جمالهم '),
(21583, 'Judges', 7, 8, 27, ' فصنع جدعون منها أفودا وجعله في مدينته في عفرة . وزنى كل إسرائيل وراءه هناك ، فكان ذلك لجدعون وبيته فخا '),
(21584, 'Judges', 7, 8, 28, ' وذل مديان أمام بني إسرائيل ولم يعودوا يرفعون رؤوسهم . واستراحت الأرض أربعين سنة في أيام جدعون '),
(21585, 'Judges', 7, 8, 29, ' وذهب يربعل بن يوآش وأقام في بيته '),
(21586, 'Judges', 7, 8, 30, ' وكان لجدعون سبعون ولدا خارجون من صلبه ، لأنه كانت له نساء كثيرات '),
(21587, 'Judges', 7, 8, 31, ' وسريته التي في شكيم ولدت له هي أيضا ابنا فسماه أبيمالك '),
(21588, 'Judges', 7, 8, 32, ' ومات جدعون بن يوآش بشيبة صالحة ، ودفن في قبر يوآش أبيه في عفرة أبيعزر '),
(21589, 'Judges', 7, 8, 33, ' وكان بعد موت جدعون أن بني إسرائيل رجعوا وزنوا وراء البعليم ، وجعلوا لهم بعل بريث إلها '),
(21590, 'Judges', 7, 8, 34, ' ولم يذكر بنو إسرائيل الرب إلههم الذي أنقذهم من يد جميع أعدائهم من حولهم '),
(21591, 'Judges', 7, 8, 35, ' ولم يعملوا معروفا مع بيت يربعل ، جدعون ، نظير كل الخير الذي عمل مع إسرائيل '),
(21592, 'Judges', 7, 9, 1, ' وذهب أبيمالك بن يربعل إلى شكيم إلى إخوة أمه ، وكلمهم وجميع عشيرة بيت أبي أمه قائلا '),
(21593, 'Judges', 7, 9, 2, ' تكلموا الآن في آذان جميع أهل شكيم . أيما هو خير لكم : أأن يتسلط عليكم سبعون رجلا ، جميع بني يربعل ، أم أن يتسلط عليكم رجل واحد ؟ واذكروا أني أنا عظمكم ولحمكم '),
(21594, 'Judges', 7, 9, 3, ' فتكلم إخوة أمه عنه في آذان كل أهل شكيم بجميع هذا الكلام . فمال قلبهم وراء أبيمالك ، لأنهم قالوا : أخونا هو '),
(21595, 'Judges', 7, 9, 4, ' وأعطوه سبعين شاقل فضة من بيت بعل بريث ، فاستأجر بها أبيمالك رجالا بطالين طائشين ، فسعوا وراءه '),
(21596, 'Judges', 7, 9, 5, ' ثم جاء إلى بيت أبيه في عفرة وقتل إخوته بني يربعل ، سبعين رجلا ، على حجر واحد . وبقي يوثام بن يربعل الأصغر لأنه اختبأ '),
(21597, 'Judges', 7, 9, 6, ' فاجتمع جميع أهل شكيم وكل سكان القلعة وذهبوا وجعلوا أبيمالك ملكا عند بلوطة النصب الذي في شكيم '),
(21598, 'Judges', 7, 9, 7, ' وأخبروا يوثام فذهب ووقف على رأس جبل جرزيم ، ورفع صوته ونادى وقال لهم : اسمعوا لي يا أهل شكيم ، يسمع لكم الله '),
(21599, 'Judges', 7, 9, 8, ' مرة ذهبت الأشجار لتمسح عليها ملكا . فقالت للزيتونة : املكي علينا '),
(21600, 'Judges', 7, 9, 9, ' فقالت لها الزيتونة : أأترك دهني الذي به يكرمون بي الله والناس ، وأذهب لكي أملك على الأشجار '),
(21601, 'Judges', 7, 9, 10, ' ثم قالت الأشجار للتينة : تعالي أنت واملكي علينا '),
(21602, 'Judges', 7, 9, 11, ' فقالت لها التينة : أأترك حلاوتي وثمري الطيب وأذهب لكي أملك على الأشجار '),
(21603, 'Judges', 7, 9, 12, ' فقالت الأشجار للكرمة : تعالي أنت واملكي علينا '),
(21604, 'Judges', 7, 9, 13, ' فقالت لها الكرمة : أأترك مسطاري الذي يفرح الله والناس وأذهب لكي أملك على الأشجار '),
(21605, 'Judges', 7, 9, 14, ' ثم قالت جميع الأشجار للعوسج : تعال أنت واملك علينا '),
(21606, 'Judges', 7, 9, 15, ' فقال العوسج للأشجار : إن كنتم بالحق تمسحونني عليكم ملكا فتعالوا واحتموا تحت ظلي . وإلأ فتخرج نار من العوسج وتأكل أرز لبنان '),
(21607, 'Judges', 7, 9, 16, ' فالآن إن كنتم قد عملتم بالحق والصحة إذ جعلتم أبيمالك ملكا ، وإن كنتم قد فعلتم خيرا مع يربعل ومع بيته ، وإن كنتم قد فعلتم له حسب عمل يديه '),
(21608, 'Judges', 7, 9, 17, ' لأن أبي قد حارب عنكم وخاطر بنفسه وأنقذكم من يد مديان '),
(21609, 'Judges', 7, 9, 18, ' وأنتم قد قمتم اليوم على بيت أبي وقتلتم بنيه ، سبعين رجلا على حجر واحد ، وملكتم أبيمالك ابن أمته على أهل شكيم لأنه أخوكم '),
(21610, 'Judges', 7, 9, 19, ' فإن كنتم قد عملتم بالحق والصحة مع يربعل ومع بيته في هذا اليوم ، فافرحوا أنتم بأبيمالك ، وليفرح هو أيضا بكم '),
(21611, 'Judges', 7, 9, 20, ' وإلأ فتخرج نار من أبيمالك وتأكل أهل شكيم وسكان القلعة ، وتخرج نار من أهل شكيم ومن سكان القلعة وتأكل أبيمالك '),
(21612, 'Judges', 7, 9, 21, ' ثم هرب يوثام وفر وذهب إلى بئر ، وأقام هناك من وجه أبيمالك أخيه '),
(21613, 'Judges', 7, 9, 22, ' فترأس أبيمالك على إسرائيل ثلاث سنين '),
(21614, 'Judges', 7, 9, 23, ' وأرسل الرب روحا رديا بين أبيمالك وأهل شكيم ، فغدر أهل شكيم بأبيمالك '),
(21615, 'Judges', 7, 1, 1, ' وكان بعد موت يشوع أن بني إسرائيل سألوا الرب قائلين : من منا يصعد إلى الكنعانيين أولا لمحاربتهم '),
(21616, 'Judges', 7, 1, 2, ' فقال الرب : يهوذا يصعد . هوذا قد دفعت الأرض ليده '),
(21617, 'Judges', 7, 1, 3, ' فقال يهوذا لشمعون أخيه : اصعد معي في قرعتي لكي نحارب الكنعانيين ، فأصعد أنا أيضا معك في قرعتك . فذهب شمعون معه '),
(21618, 'Judges', 7, 1, 4, ' فصعد يهوذا ، ودفع الرب الكنعانيين والفرزيين بيدهم ، فضربوا منهم في بازق عشرة آلاف رجل '),
(21619, 'Judges', 7, 1, 5, ' ووجدوا أدوني بازق في بازق ، فحاربوه وضربوا الكنعانيين والفرزيين '),
(21620, 'Judges', 7, 1, 6, ' فهرب أدوني بازق ، فتبعوه وأمسكوه وقطعوا أباهم يديه ورجليه '),
(21621, 'Judges', 7, 1, 7, ' فقال أدوني بازق : سبعون ملكا مقطوعة أباهم أيديهم وأرجلهم كانوا يلتقطون تحت مائدتي . كما فعلت كذلك جازاني الله . وأتوا به إلى أورشليم فمات هناك '),
(21622, 'Judges', 7, 1, 8, ' وحارب بنو يهوذا أورشليم وأخذوها وضربوها بحد السيف ، وأشعلوا المدينة بالنار '),
(21623, 'Judges', 7, 1, 9, ' وبعد ذلك نزل بنو يهوذا لمحاربة الكنعانيين سكان الجبل والجنوب والسهل '),
(21624, 'Judges', 7, 1, 10, ' وسار يهوذا على الكنعانيين الساكنين في حبرون ، وكان اسم حبرون قبلا قرية أربع . وضربوا شيشاي وأخيمان وتلماي '),
(21625, 'Judges', 7, 1, 11, ' وسار من هناك على سكان دبير ، واسم دبير قبلا قرية سفر '),
(21626, 'Judges', 7, 1, 12, ' فقال كالب : الذي يضرب قرية سفر ويأخذها ، أعطيه عكسة ابنتي امرأة '),
(21627, 'Judges', 7, 1, 13, ' فأخذها عثنيئيل بن قناز ، أخو كالب الأصغر منه . فأعطاه عكسة ابنته امرأة '),
(21628, 'Judges', 7, 1, 14, ' وكان عند دخولها أنها غرته بطلب حقل من أبيها . فنزلت عن الحمار ، فقال لها كالب : ما لك '),
(21629, 'Judges', 7, 1, 15, ' فقالت له : أعطني بركة . لأنك أعطيتني أرض الجنوب ، فأعطني ينابيع ماء . فأعطاها كالب الينابيع العليا والينابيع السفلى '),
(21630, 'Judges', 7, 1, 16, ' وبنو القيني حمي موسى صعدوا من مدينة النخل مع بني يهوذا إلى برية يهوذا التي في جنوبي عراد ، وذهبوا وسكنوا مع الشعب '),
(21631, 'Judges', 7, 1, 17, ' وذهب يهوذا مع شمعون أخيه وضربوا الكنعانيين سكان صفاة وحرموها ، ودعوا اسم المدينة حرمة '),
(21632, 'Judges', 7, 1, 18, ' وأخذ يهوذا غزة وتخومها ، وأشقلون وتخومها ، وعقرون وتخومها '),
(21633, 'Judges', 7, 1, 19, ' وكان الرب مع يهوذا فملك الجبل ، ولكن لم يطرد سكان الوادي لأن لهم مركبات حديد '),
(21634, 'Judges', 7, 1, 20, ' وأعطوا لكالب حبرون كما تكلم موسى . فطرد من هناك بني عناق الثلاثة '),
(21635, 'Judges', 7, 1, 21, ' وبنو بنيامين لم يطردوا اليبوسيين سكان أورشليم ، فسكن اليبوسيون مع بني بنيامين في أورشليم إلى هذا اليوم '),
(21636, 'Judges', 7, 1, 22, ' وصعد بيت يوسف أيضا إلى بيت إيل والرب معهم '),
(21637, 'Judges', 7, 1, 23, ' واستكشف بيت يوسف عن بيت إيل ، وكان اسم المدينة قبلا لوز '),
(21638, 'Judges', 7, 1, 24, ' فرأى المراقبون رجلا خارجا من المدينة ، فقالوا له : أرنا مدخل المدينة فنعمل معك معروفا '),
(21639, 'Judges', 7, 1, 25, ' فأراهم مدخل المدينة ، فضربوا المدينة بحد السيف ، وأما الرجل وكل عشيرته فأطلقوهم '),
(21640, 'Judges', 7, 1, 26, ' فانطلق الرجل إلى أرض الحثيين وبنى مدينة ودعا اسمها لوز وهو اسمها إلى هذا اليوم '),
(21641, 'Judges', 7, 1, 27, ' ولم يطرد منسى أهل بيت شان وقراها ، ولا أهل تعنك وقراها ، ولا سكان دور وقراها ، ولا سكان يبلعام وقراها ، ولا سكان مجدو وقراها . فعزم الكنعانيون على السكن في تلك الأرض '),
(21642, 'Judges', 7, 1, 28, ' وكان لما تشدد إسرائيل أنه وضع الكنعانيين تحت الجزية ولم يطردهم طردا '),
(21643, 'Judges', 7, 1, 29, ' وأفرايم لم يطرد الكنعانيين الساكنين في جازر ، فسكن الكنعانيون في وسطه في جازر '),
(21644, 'Judges', 7, 1, 30, ' زبولون لم يطرد سكان قطرون ، ولا سكان نهلول ، فسكن الكنعانيون في وسطه وكانوا تحت الجزية '),
(21645, 'Judges', 7, 1, 31, ' ولم يطرد أشير سكان عكو ، ولا سكان صيدون وأحلب وأكزيب وحلبة وأفيق ورحوب '),
(21646, 'Judges', 7, 1, 32, ' فسكن الأشيريون في وسط الكنعانيين سكان الأرض ، لأنهم لم يطردوهم '),
(21647, 'Judges', 7, 1, 33, ' ونفتالي لم يطرد سكان بيت شمس ، ولا سكان بيت عناة ، بل سكن في وسط الكنعانيين سكان الأرض . فكان سكان بيت شمس وبيت عناة تحت الجزية لهم '),
(21648, 'Judges', 7, 1, 34, ' وحصر الأموريون بني دان في الجبل لأنهم لم يدعوهم ينزلون إلى الوادي '),
(21649, 'Judges', 7, 1, 35, ' فعزم الأموريون على السكن في جبل حارس في أيلون وفي شعلبيم . وقويت يد بيت يوسف فكانوا تحت الجزية '),
(21650, 'Judges', 7, 1, 36, ' وكان تخم الأموريين من عقبة عقربيم من سالع فصاعدا '),
(21651, 'Judges', 7, 2, 1, ' وصعد ملاك الرب من الجلجال إلى بوكيم وقال : قد أصعدتكم من مصر وأتيت بكم إلى الأرض التي أقسمت لآبائكم ، وقلت : لا أنكث عهدي معكم إلى الأبد '),
(21652, 'Judges', 7, 2, 2, ' وأنتم فلا تقطعوا عهدا مع سكان هذه الأرض . اهدموا مذابحهم . ولم تسمعوا لصوتي . فماذا عملتم '),
(21653, 'Judges', 7, 2, 3, ' فقلت أيضا : لا أطردهم من أمامكم ، بل يكونون لكم مضايقين ، وتكون آلهتهم لكم شركا '),
(21654, 'Judges', 7, 2, 4, ' وكان لما تكلم ملاك الرب بهذا الكلام إلى جميع بني إسرائيل ، أن الشعب رفعوا صوتهم وبكوا '),
(21655, 'Judges', 7, 2, 5, ' فدعوا اسم ذلك المكان بوكيم . وذبحوا هناك للرب '),
(21656, 'Judges', 7, 2, 6, ' وصرف يشوع الشعب ، فذهب بنو إسرائيل كل واحد إلى ملكه لأجل امتلاك الأرض '),
(21657, 'Judges', 7, 2, 7, ' وعبد الشعب الرب كل أيام يشوع ، وكل أيام الشيوخ الذين طالت أيامهم بعد يشوع الذين رأوا كل عمل الرب العظيم الذي عمل لإسرائيل '),
(21658, 'Judges', 7, 9, 24, ' ليأتي ظلم بني يربعل السبعين ، ويجلب دمهم على أبيمالك أخيهم الذي قتلهم ، وعلى أهل شكيم الذين شددوا يديه لقتل إخوته '),
(21659, 'Judges', 7, 9, 25, ' فوضع له أهل شكيم كمينا على رؤوس الجبال ، وكانوا يستلبون كل من عبر بهم في الطريق . فأخبر أبيمالك '),
(21660, 'Judges', 7, 9, 26, ' وجاء جعل بن عابد مع إخوته وعبروا إلى شكيم فوثق به أهل شكيم '),
(21661, 'Judges', 7, 9, 27, ' وخرجوا إلى الحقل وقطفوا كرومهم وداسوا وصنعوا تمجيدا ، ودخلوا بيت إلههم وأكلوا وشربوا ولعنوا أبيمالك '),
(21662, 'Judges', 7, 9, 28, ' فقال جعل بن عابد : من هو أبيمالك ومن هو شكيم حتى نخدمه ؟ أما هو ابن يربعل ، وزبول وكيله ؟ اخدموا رجال حمور أبي شكيم . فلماذا نخدمه نحن '),
(21663, 'Judges', 7, 9, 29, ' من يجعل هذا الشعب بيدي فأعزل أبيمالك . وقال لأبيمالك : كثر جندك واخرج '),
(21664, 'Judges', 7, 9, 30, ' ولما سمع زبول رئيس المدينة كلام جعل بن عابد حمي غضبه '),
(21665, 'Judges', 7, 9, 31, ' وأرسل رسلا إلى أبيمالك في ترمة يقول : هوذا جعل بن عابد وإخوته قد أتوا إلى شكيم ، وها هم يهيجون المدينة ضدك '),
(21666, 'Judges', 7, 9, 32, ' فالآن قم ليلا أنت والشعب الذي معك واكمن في الحقل '),
(21667, 'Judges', 7, 9, 33, ' ويكون في الصباح عند شروق الشمس أنك تبكر وتقتحم المدينة . وها هو والشعب الذي معه يخرجون إليك فتفعل به حسبما تجده يدك '),
(21668, 'Judges', 7, 9, 34, ' فقام أبيمالك وكل الشعب الذي معه ليلا وكمنوا لشكيم أربع فرق '),
(21669, 'Judges', 7, 9, 35, ' فخرج جعل بن عابد ووقف في مدخل باب المدينة . فقام أبيمالك والشعب الذي معه من المكمن '),
(21670, 'Judges', 7, 9, 36, ' ورأى جعل الشعب فقال لزبول : هوذا شعب نازل عن رؤوس الجبال . فقال له زبول : إنك ترى ظل الجبال كأنه أناس '),
(21671, 'Judges', 7, 9, 37, ' فعاد جعل وتكلم أيضا قائلا : هوذا شعب نازل من عند أعالي الأرض ، وفرقة واحدة آتية عن طريق بلوطة العائفين '),
(21672, 'Judges', 7, 9, 38, ' فقال له زبول : أين الآن فوك الذي قلت به : من هو أبيمالك حتى نخدمه ؟ أليس هذا هو الشعب الذي رذلته ؟ فاخرج الآن وحاربه '),
(21673, 'Judges', 7, 9, 39, ' فخرج جعل أمام أهل شكيم وحارب أبيمالك '),
(21674, 'Judges', 7, 9, 40, ' فهزمه أبيمالك ، فهرب من قدامه وسقط قتلى كثيرون حتى عند مدخل الباب '),
(21675, 'Judges', 7, 9, 41, ' فأقام أبيمالك في أرومة . وطرد زبول جعلا وإخوته عن الإقامة في شكيم '),
(21676, 'Judges', 7, 9, 42, ' وكان في الغد أن الشعب خرج إلى الحقل وأخبروا أبيمالك '),
(21677, 'Judges', 7, 9, 43, ' فأخذ القوم وقسمهم إلى ثلاث فرق ، وكمن في الحقل ونظر وإذا الشعب يخرج من المدينة ، فقام عليهم وضربهم '),
(21678, 'Judges', 7, 9, 44, ' وأبيمالك والفرقة التي معه اقتحموا ووقفوا في مدخل باب المدينة . وأما الفرقتان فهجمتا على كل من في الحقل وضربتاه '),
(21679, 'Judges', 7, 9, 45, ' وحارب أبيمالك المدينة كل ذلك اليوم ، وأخذ المدينة وقتل الشعب الذي بها ، وهدم المدينة وزرعها ملحا '),
(21680, 'Judges', 7, 9, 46, ' وسمع كل أهل برج شكيم فدخلوا إلى صرح بيت إيل بريث '),
(21681, 'Judges', 7, 9, 47, ' فأخبر أبيمالك أن كل أهل برج شكيم قد اجتمعوا '),
(21682, 'Judges', 7, 9, 48, ' فصعد أبيمالك إلى جبل صلمون هو وكل الشعب الذي معه . وأخذ أبيمالك الفؤوس بيده ، وقطع غصن شجر ورفعه ووضعه على كتفه ، وقال للشعب الذي معه : ما رأيتموني أفعله فأسرعوا افعلوا مثلي '),
(21683, 'Judges', 7, 9, 49, ' فقطع الشعب أيضا كل واحد غصنا وساروا وراء أبيمالك ، ووضعوها على الصرح ، وأحرقوا عليهم الصرح بالنار . فمات أيضا جميع أهل برج شكيم ، نحو ألف رجل وامرأة '),
(21684, 'Judges', 7, 9, 50, ' ثم ذهب أبيمالك إلى تاباص ونزل في تاباص وأخذها '),
(21685, 'Judges', 7, 9, 51, ' وكان برج قوي في وسط المدينة فهرب إليه جميع الرجال والنساء وكل أهل المدينة ، وأغلقوا وراءهم ، وصعدوا إلى سطح البرج '),
(21686, 'Judges', 7, 9, 52, ' فجاء أبيمالك إلى البرج وحاربه ، واقترب إلى باب البرج ليحرقه بالنار '),
(21687, 'Judges', 7, 9, 53, ' فطرحت امرأة قطعة رحى على رأس أبيمالك فشجت جمجمته '),
(21688, 'Judges', 7, 9, 54, ' فدعا حالا الغلام حامل عدته وقال له : اخترط سيفك واقتلني ، لئلا يقولوا عني : قتلته امرأة . فطعنه الغلام فمات '),
(21689, 'Judges', 7, 9, 55, ' ولما رأى رجال إسرائيل أن أبيمالك قد مات ، ذهب كل واحد إلى مكانه '),
(21690, 'Judges', 7, 9, 56, ' فرد الله شر أبيمالك الذي فعله بأبيه لقتله إخوته السبعين '),
(21691, 'Judges', 7, 9, 57, ' وكل شر أهل شكيم رده الله على رؤوسهم ، وأتت عليهم لعنة يوثام بن يربعل '),
(21692, 'Judges', 7, 10, 1, ' وقام بعد أبيمالك لتخليص إسرائيل تولع بن فواة بن دودو ، رجل من يساكر ، كان ساكنا في شامير في جبل أفرايم '),
(21693, 'Judges', 7, 10, 2, ' فقضى لإسرائيل ثلاثا وعشرين سنة ومات ودفن في شامير '),
(21694, 'Judges', 7, 10, 3, ' ثم قام بعده يائير الجلعادي ، فقضى لإسرائيل اثنتين وعشرين سنة '),
(21695, 'Judges', 7, 10, 4, ' وكان له ثلاثون ولدا يركبون على ثلاثين جحشا ، ولهم ثلاثون مدينة . منهم يدعونها حووث يائير إلى هذا اليوم . هي في أرض جلعاد '),
(21696, 'Judges', 7, 10, 5, ' ومات يائير ودفن في قامون '),
(21697, 'Judges', 7, 10, 6, ' وعاد بنو إسرائيل يعملون الشر في عيني الرب ، وعبدوا البعليم والعشتاروث وآلهة أرام وآلهة صيدون وآلهة موآب وآلهة بني عمون وآلهة الفلسطينيين ، وتركوا الرب ولم يعبدوه '),
(21698, 'Judges', 7, 10, 7, ' فحمي غضب الرب على إسرائيل وباعهم بيد الفلسطينيين وبيد بني عمون '),
(21699, 'Judges', 7, 10, 8, ' فحطموا ورضضوا بني إسرائيل في تلك السنة . ثماني عشرة سنة . جميع بني إسرائيل الذين في عبر الأردن في أرض الأموريين الذين في جلعاد '),
(21700, 'Judges', 7, 10, 9, ' وعبر بنو عمون الأردن ليحاربوا أيضا يهوذا وبنيامين وبيت أفرايم . فتضايق إسرائيل جدا '),
(21701, 'Judges', 7, 10, 10, ' فصرخ بنو إسرائيل إلى الرب قائلين : أخطأنا إليك لأننا تركنا إلهنا وعبدنا البعليم '),
(21702, 'Judges', 7, 10, 11, ' فقال الرب لبني إسرائيل : أليس من المصريين والأموريين وبني عمون والفلسطينيين خلصتكم '),
(21703, 'Judges', 7, 10, 12, ' والصيدونيون والعمالقة والمعونيون قد ضايقوكم فصرختم إلي فخلصتكم من أيديهم '),
(21704, 'Judges', 7, 10, 13, ' وأنتم قد تركتموني وعبدتم آلهة أخرى . لذلك لا أعود أخلصكم '),
(21705, 'Judges', 7, 10, 14, ' امضوا واصرخوا إلى الآلهة التي اخترتموها ، لتخلصكم هي في زمان ضيقكم '),
(21706, 'Judges', 7, 10, 15, ' فقال بنو إسرائيل للرب : أخطأنا ، فافعل بنا كل ما يحسن في عينيك . إنما أنقذنا هذا اليوم '),
(21707, 'Judges', 7, 10, 16, ' وأزالوا الآلهة الغريبة من وسطهم وعبدوا الرب ، فضاقت نفسه بسبب مشقة إسرائيل '),
(21708, 'Judges', 7, 10, 17, ' فاجتمع بنو عمون ونزلوا في جلعاد ، واجتمع بنو إسرائيل ونزلوا في المصفاة '),
(21709, 'Judges', 7, 10, 18, ' فقال الشعب رؤساء جلعاد الواحد لصاحبه : أي هو الرجل الذي يبتدئ بمحاربة بني عمون ؟ فإنه يكون رأسا لجميع سكان جلعاد '),
(21710, 'Judges', 7, 11, 1, ' وكان يفتاح الجلعادي جبار بأس ، وهو ابن امرأة زانية . وجلعاد ولد يفتاح '),
(21711, 'Judges', 7, 11, 2, ' ثم ولدت امرأة جلعاد له بنين . فلما كبر بنو المرأة طردوا يفتاح ، وقالوا له : لا ترث في بيت أبينا لأنك أنت ابن امرأة أخرى '),
(21712, 'Judges', 7, 11, 3, ' فهرب يفتاح من وجه إخوته وأقام في أرض طوب . فاجتمع إلى يفتاح رجال بطالون وكانوا يخرجون معه '),
(21713, 'Judges', 7, 11, 4, ' وكان بعد أيام أن بني عمون حاربوا إسرائيل '),
(21714, 'Judges', 7, 11, 5, ' ولما حارب بنو عمون إسرائيل ذهب شيوخ جلعاد ليأتوا بيفتاح من أرض طوب '),
(21715, 'Judges', 7, 11, 6, ' وقالوا ليفتاح : تعال وكن لنا قائدا فنحارب بني عمون '),
(21716, 'Judges', 7, 11, 7, ' فقال يفتاح لشيوخ جلعاد : أما أبغضتموني أنتم وطردتموني من بيت أبي ؟ فلماذا أتيتم إلي الآن إذ تضايقتم '),
(21717, 'Judges', 7, 11, 8, ' فقال شيوخ جلعاد ليفتاح : لذلك قد رجعنا الآن إليك لتذهب معنا وتحارب بني عمون ، وتكون لنا رأسا لكل سكان جلعاد '),
(21718, 'Judges', 7, 11, 9, ' فقال يفتاح لشيوخ جلعاد : إذا أرجعتموني لمحاربة بني عمون ودفعهم الرب أمامي فأنا أكون لكم رأسا '),
(21719, 'Judges', 7, 11, 10, ' فقال شيوخ جلعاد ليفتاح : الرب يكون سامعا بيننا إن كنا لا نفعل هكذا حسب كلامك '),
(21720, 'Judges', 7, 11, 11, ' فذهب يفتاح مع شيوخ جلعاد ، وجعله الشعب عليهم رأسا وقائدا . فتكلم يفتاح بجميع كلامه أمام الرب في المصفاة '),
(21721, 'Judges', 7, 11, 12, ' فأرسل يفتاح رسلا إلى ملك بني عمون يقول : ما لي ولك أنك أتيت إلي للمحاربة في أرضي '),
(21722, 'Judges', 7, 11, 13, ' فقال ملك بني عمون لرسل يفتاح : لأن إسرائيل قد أخذ أرضي عند صعوده من مصر ، من أرنون إلى اليبوق وإلى الأردن . فالآن ردها بسلام '),
(21723, 'Judges', 7, 11, 14, ' وعاد أيضا يفتاح وأرسل رسلا إلى ملك بني عمون '),
(21724, 'Judges', 7, 11, 15, ' وقال له : هكذا يقول يفتاح : لم يأخذ إسرائيل أرض موآب ولا أرض بني عمون '),
(21725, 'Judges', 7, 11, 16, ' لأنه عند صعود إسرائيل من مصر سار في القفر إلى بحر سوف وأتى إلى قادش '),
(21726, 'Judges', 7, 11, 17, ' وأرسل إسرائيل رسلا إلى ملك أدوم قائلا : دعني أعبر في أرضك . فلم يسمع ملك أدوم . فأرسل أيضا إلى ملك موآب فلم يرض . فأقام إسرائيل في قادش '),
(21727, 'Judges', 7, 11, 18, ' وسار في القفر ودار بأرض أدوم وأرض موآب وأتى من مشرق الشمس إلى أرض موآب ونزل في عبر أرنون ، ولم يأتوا إلى تخم موآب لأن أرنون تخم موآب '),
(21728, 'Judges', 7, 11, 19, ' ثم أرسل إسرائيل رسلا إلى سيحون ملك الأموريين ، ملك حشبون ، وقال له إسرائيل : دعني أعبر في أرضك إلى مكاني '),
(21729, 'Judges', 7, 11, 20, ' ولم يأمن سيحون لإسرائيل أن يعبر في تخمه ، بل جمع سيحون كل شعبه ونزلوا في ياهص وحاربوا إسرائيل '),
(21730, 'Judges', 7, 11, 21, ' فدفع الرب إله إسرائيل سيحون وكل شعبه ليد إسرائيل فضربوهم ، وامتلك إسرائيل كل أرض الأموريين سكان تلك الأرض '),
(21731, 'Judges', 7, 11, 22, ' فامتلكوا كل تخم الأموريين من أرنون إلى اليبوق ومن القفر إلى الأردن '),
(21732, 'Judges', 7, 11, 23, ' والآن الرب إله إسرائيل قد طرد الأموريين من أمام شعبه إسرائيل . أفأنت تمتلكه '),
(21733, 'Judges', 7, 11, 24, ' أليس ما يملكك إياه كموش إلهك تمتلك ؟ وجميع الذين طردهم الرب إلهنا من أمامنا فإياهم نمتلك '),
(21734, 'Judges', 7, 11, 25, ' والآن فهل أنت خير من بالاق بن صفور ملك موآب ؟ فهل خاصم إسرائيل أو حاربهم محاربة '),
(21735, 'Judges', 7, 11, 26, ' حين أقام إسرائيل في حشبون وقراها ، وعروعير وقراها وكل المدن التي على جانب أرنون ثلاث مئة سنة ؟ فلماذا لم تستردها في تلك المدة '),
(21736, 'Judges', 7, 11, 27, ' فأنا لم أخطئ إليك . وأما أنت فإنك تفعل بي شرا بمحاربتي . ليقض الرب القاضي اليوم بين بني إسرائيل وبني عمون '),
(21737, 'Judges', 7, 11, 28, ' فلم يسمع ملك بني عمون لكلام يفتاح الذي أرسل إليه '),
(21738, 'Judges', 7, 11, 29, ' فكان روح الرب على يفتاح ، فعبر جلعاد ومنسى وعبر مصفاة جلعاد ، ومن مصفاة جلعاد عبر إلى بني عمون '),
(21739, 'Judges', 7, 11, 30, ' ونذر يفتاح نذرا للرب قائلا : إن دفعت بني عمون ليدي '),
(21740, 'Judges', 7, 11, 31, ' فالخارج الذي يخرج من أبواب بيتي للقائي عند رجوعي بالسلامة من عند بني عمون يكون للرب ، وأصعده محرقة '),
(21741, 'Judges', 7, 11, 32, ' ثم عبر يفتاح إلى بني عمون لمحاربتهم . فدفعهم الرب ليده '),
(21742, 'Judges', 7, 11, 33, ' فضربهم من عروعير إلى مجيئك إلى منيت ، عشرين مدينة ، وإلى آبل الكروم ضربة عظيمة جدا . فذل بنو عمون أمام بني إسرائيل '),
(21743, 'Judges', 7, 11, 34, ' ثم أتى يفتاح إلى المصفاة إلى بيته ، وإذا بابنته خارجة للقائه بدفوف ورقص . وهي وحيدة . لم يكن له ابن ولا ابنة غيرها '),
(21744, 'Judges', 7, 11, 35, ' وكان لما رآها أنه مزق ثيابه وقال : آه يا بنتي قد أحزنتني حزنا وصرت بين مكدري ، لأني قد فتحت فمي إلى الرب ولا يمكنني الرجوع '),
(21745, 'Judges', 7, 11, 36, ' فقالت له : يا أبي ، هل فتحت فاك إلى الرب ؟ فافعل بي كما خرج من فيك ، بما أن الرب قد انتقم لك من أعدائك بني عمون '),
(21746, 'Judges', 7, 11, 37, ' ثم قالت لأبيها : فليفعل لي هذا الأمر : اتركني شهرين فأذهب وأنزل على الجبال وأبكي عذراويتي أنا وصاحباتي '),
(21747, 'Judges', 7, 11, 38, ' فقال : اذهبي . وأرسلها إلى شهرين . فذهبت هي وصاحباتها وبكت عذراويتها على الجبال '),
(21748, 'Judges', 7, 11, 39, ' وكان عند نهاية الشهرين أنها رجعت إلى أبيها ، ففعل بها نذره الذي نذر . وهي لم تعرف رجلا . فصارت عادة في إسرائيل '),
(21749, 'Judges', 7, 11, 40, ' أن بنات إسرائيل يذهبن من سنة إلى سنة لينحن على بنت يفتاح الجلعادي أربعة أيام في السنة '),
(21750, 'Judges', 7, 12, 1, ' واجتمع رجال أفرايم وعبروا إلى جهة الشمال ، وقالوا ليفتاح : لماذا عبرت لمحاربة بني عمون ولم تدعنا للذهاب معك ؟ نحرق بيتك عليك بنار '),
(21751, 'Judges', 7, 12, 2, ' فقال لهم يفتاح : صاحب خصام شديد كنت أنا وشعبي مع بني عمون ، وناديتكم فلم تخلصوني من يدهم '),
(21752, 'Judges', 7, 12, 3, ' ولما رأيت أنكم لا تخلصون ، وضعت نفسي في يدي وعبرت إلى بني عمون ، فدفعهم الرب ليدي . فلماذا صعدتم علي اليوم هذا لمحاربتي '),
(21753, 'Judges', 7, 12, 4, ' وجمع يفتاح كل رجال جلعاد وحارب أفرايم ، فضرب رجال جلعاد أفرايم لأنهم قالوا : أنتم منفلتو أفرايم . جلعاد بين أفرايم ومنسى '),
(21754, 'Judges', 7, 12, 5, ' فأخذ الجلعاديون مخاوض الأردن لأفرايم . وكان إذ قال منفلتو أفرايم : دعوني أعبر . كان رجال جلعاد يقولون له : أأنت أفرايمي ؟ فإن قال : لا '),
(21755, 'Judges', 7, 12, 6, ' كانوا يقولون له : قل إذا : شبولت فيقول : سبولت ولم يتحفظ للفظ بحق . فكانوا يأخذونه ويذبحونه على مخاوض الأردن . فسقط في ذلك الوقت من أفرايم اثنان وأربعون ألفا '),
(21756, 'Judges', 7, 12, 7, ' وقضى يفتاح لإسرائيل ست سنين . ومات يفتاح الجلعادي ودفن في إحدى مدن جلعاد '),
(21757, 'Judges', 7, 12, 0, ' إبصان وإيلون وعبدون '),
(21758, 'Judges', 7, 12, 8, ' وقضى بعده لإسرائيل إبصان من بيت لحم '),
(21759, 'Judges', 7, 12, 9, ' وكان له ثلاثون ابنا وثلاثون ابنة أرسلهن إلى الخارج ، وأتى من الخارج بثلاثين ابنة لبنيه . وقضى لإسرائيل سبع سنين '),
(21760, 'Judges', 7, 12, 10, ' ومات إبصان ودفن في بيت لحم '),
(21761, 'Judges', 7, 12, 11, ' وقضى بعده لإسرائيل إيلون الزبولوني . قضى لإسرائيل عشر سنين '),
(21762, 'Judges', 7, 12, 12, ' ومات إيلون الزبولوني ودفن في أيلون ، في أرض زبولون '),
(21763, 'Judges', 7, 12, 13, ' وقضى بعده لإسرائيل عبدون بن هليل الفرعتوني '),
(21764, 'Judges', 7, 12, 14, ' وكان له أربعون ابنا وثلاثون حفيدا يركبون على سبعين جحشا . قضى لإسرائيل ثماني سنين '),
(21765, 'Judges', 7, 12, 15, ' ومات عبدون بن هليل الفرعتوني ودفن في فرعتون ، في أرض أفرايم ، في جبل العمالقة '),
(21766, 'Judges', 7, 13, 1, ' ثم عاد بنو إسرائيل يعملون الشر في عيني الرب ، فدفعهم الرب ليد الفلسطينيين أربعين سنة '),
(21767, 'Judges', 7, 13, 2, ' وكان رجل من صرعة من عشيرة الدانيين اسمه منوح ، وامرأته عاقر لم تلد '),
(21768, 'Judges', 7, 13, 3, ' فتراءى ملاك الرب للمرأة وقال لها : ها أنت عاقر لم تلدي ، ولكنك تحبلين وتلدين ابنا '),
(21769, 'Judges', 7, 13, 4, ' والآن فاحذري ولا تشربي خمرا ولا مسكرا ، ولا تأكلي شيئا نجسا '),
(21770, 'Judges', 7, 13, 5, ' فها إنك تحبلين وتلدين ابنا ، ولا يعل موسى رأسه ، لأن الصبي يكون نذيرا لله من البطن ، وهو يبدأ يخلص إسرائيل من يد الفلسطينيين '),
(21771, 'Judges', 7, 13, 6, ' فدخلت المرأة وكلمت رجلها قائلة : جاء إلي رجل الله ، ومنظره كمنظر ملاك الله ، مرهب جدا . ولم أسأله : من أين هو ، ولا هو أخبرني عن اسمه '),
(21772, 'Judges', 7, 13, 7, ' وقال لي : ها أنت تحبلين وتلدين ابنا . والآن فلا تشربي خمرا ولا مسكرا ، ولا تأكلي شيئا نجسا ، لأن الصبي يكون نذيرا لله من البطن إلى يوم موته '),
(21773, 'Judges', 7, 13, 8, ' فصلى منوح إلى الرب وقال : أسألك يا سيدي أن يأتي أيضا إلينا رجل الله الذي أرسلته ، ويعلمنا : ماذا نعمل للصبي الذي يولد '),
(21774, 'Judges', 7, 13, 9, ' فسمع الله لصوت منوح ، فجاء ملاك الله أيضا إلى المرأة وهي جالسة في الحقل ، ومنوح رجلها ليس معها '),
(21775, 'Judges', 7, 13, 10, ' فأسرعت المرأة وركضت وأخبرت رجلها وقالت له : هوذا قد تراءى لي الرجل الذي جاء إلي ذلك اليوم '),
(21776, 'Judges', 7, 13, 11, ' فقام منوح وسار وراء امرأته وجاء إلى الرجل ، وقال له : أأنت الرجل الذي تكلم مع المرأة ؟ فقال : أنا هو '),
(21777, 'Judges', 7, 13, 12, ' فقال منوح : عند مجيء كلامك ، ماذا يكون حكم الصبي ومعاملته '),
(21778, 'Judges', 7, 13, 13, ' فقال ملاك الرب لمنوح : من كل ما قلت للمرأة فلتحتفظ '),
(21779, 'Judges', 7, 13, 14, ' من كل ما يخرج من جفنة الخمر لا تأكل ، وخمرا ومسكرا لا تشرب ، وكل نجس لا تأكل . لتحذر من كل ما أوصيتها '),
(21780, 'Judges', 7, 13, 15, ' فقال منوح لملاك الرب : دعنا نعوقك ونعمل لك جدي معزى '),
(21781, 'Judges', 7, 13, 16, ' فقال ملاك الرب لمنوح : ولو عوقتني لا آكل من خبزك ، وإن عملت محرقة فللرب أصعدها . لأن منوح لم يعلم أنه ملاك الرب '),
(21782, 'Judges', 7, 13, 17, ' فقال منوح لملاك الرب : ما اسمك حتى إذا جاء كلامك نكرمك '),
(21783, 'Judges', 7, 13, 18, ' فقال له ملاك الرب : لماذا تسأل عن اسمي وهو عجيب '),
(21784, 'Judges', 7, 13, 19, ' فأخذ منوح جدي المعزى والتقدمة وأصعدهما على الصخرة للرب . فعمل عملا عجيبا ومنوح وامرأته ينظران '),
(21785, 'Judges', 7, 13, 20, ' فكان عند صعود اللهيب عن المذبح نحو السماء ، أن ملاك الرب صعد في لهيب المذبح ، ومنوح وامرأته ينظران . فسقطا على وجهيهما إلى الأرض '),
(21786, 'Judges', 7, 13, 21, ' ولم يعد ملاك الرب يتراءى لمنوح وامرأته . حينئذ عرف منوح أنه ملاك الرب '),
(21787, 'Judges', 7, 13, 22, ' فقال منوح لامرأته : نموت موتا لأننا قد رأينا الله '),
(21788, 'Judges', 7, 13, 23, ' فقالت له امرأته : لو أراد الرب أن يميتنا ، لما أخذ من يدنا محرقة وتقدمة ، ولما أرانا كل هذه ، ولما كان في مثل هذا الوقت أسمعنا مثل هذه '),
(21789, 'Judges', 7, 13, 24, ' فولدت المرأة ابنا ودعت اسمه شمشون . فكبر الصبي وباركه الرب '),
(21790, 'Judges', 7, 13, 25, ' وابتدأ روح الرب يحركه في محلة دان بين صرعة وأشتأول '),
(21791, 'Judges', 7, 14, 1, ' ونزل شمشون إلى تمنة ، ورأى امرأة في تمنة من بنات الفلسطينيين '),
(21792, 'Judges', 7, 14, 2, ' فصعد وأخبر أباه وأمه وقال : قد رأيت امرأة في تمنة من بنات الفلسطينيين ، فالآن خذاها لي امرأة '),
(21793, 'Judges', 7, 14, 3, ' فقال له أبوه وأمه : أليس في بنات إخوتك وفي كل شعبي امرأة حتى أنك ذاهب لتأخذ امرأة من الفلسطينيين الغلف ؟ فقال شمشون لأبيه : إياها خذ لي لأنها حسنت في عيني '),
(21794, 'Judges', 7, 14, 4, ' ولم يعلم أبوه وأمه أن ذلك من الرب ، لأنه كان يطلب علة على الفلسطينيين . وفي ذلك الوقت كان الفلسطينيون متسلطين على إسرائيل '),
(21795, 'Judges', 7, 14, 5, ' فنزل شمشون وأبوه وأمه إلى تمنة ، وأتوا إلى كروم تمنة . وإذا بشبل أسد يزمجر للقائه '),
(21796, 'Judges', 7, 14, 6, ' فحل عليه روح الرب ، فشقه كشق الجدي ، وليس في يده شيء . ولم يخبر أباه وأمه بما فعل '),
(21797, 'Judges', 7, 14, 7, ' فنزل وكلم المرأة فحسنت في عيني شمشون '),
(21798, 'Judges', 7, 14, 8, ' ولما رجع بعد أيام لكي يأخذها ، مال لكي يرى رمة الأسد ، وإذا دبر من النحل في جوف الأسد مع عسل '),
(21799, 'Judges', 7, 14, 9, ' فاشتار منه على كفيه ، وكان يمشي ويأكل ، وذهب إلى أبيه وأمه وأعطاهما فأكلا ، ولم يخبرهما أنه من جوف الأسد اشتار العسل '),
(21800, 'Judges', 7, 14, 10, ' ونزل أبوه إلى المرأة ، فعمل هناك شمشون وليمة ، لأنه هكذا كان يفعل الفتيان '),
(21801, 'Judges', 7, 14, 11, ' فلما رأوه أحضروا ثلاثين من الأصحاب ، فكانوا معه '),
(21802, 'Judges', 7, 14, 12, ' فقال لهم شمشون : لأحاجينكم أحجية ، فإذا حللتموها لي في سبعة أيام الوليمة وأصبتموها ، أعطيكم ثلاثين قميصا وثلاثين حلة ثياب '),
(21803, 'Judges', 7, 14, 13, ' وإن لم تقدروا أن تحلوها لي ، تعطوني أنتم ثلاثين قميصا وثلاثين حلة ثياب . فقالوا له : حاج أحجيتك فنسمعها '),
(21804, 'Judges', 7, 14, 14, ' فقال لهم : من الآكل خرج أكل ، ومن الجافي خرجت حلاوة . فلم يستطيعوا أن يحلوا الأحجية في ثلاثة أيام '),
(21805, 'Judges', 7, 14, 15, ' وكان في اليوم السابع أنهم قالوا لامرأة شمشون : تملقي رجلك لكي يظهر لنا الأحجية ، لئلا نحرقك وبيت أبيك بنار . ألتسلبونا دعوتمونا أم لا '),
(21806, 'Judges', 7, 14, 16, ' فبكت امرأة شمشون لديه وقالت : إنما كرهتني ولا تحبني . قد حاجيت بني شعبي أحجية وإياي لم تخبر . فقال لها : هوذا أبي وأمي لم أخبرهما ، فهل إياك أخبر '),
(21807, 'Judges', 7, 14, 17, ' فبكت لديه السبعة الأيام التي فيها كانت لهم الوليمة . وكان في اليوم السابع أنه أخبرها لأنها ضايقته ، فأظهرت الأحجية لبني شعبها '),
(21808, 'Judges', 7, 14, 18, ' فقال له رجال المدينة في اليوم السابع قبل غروب الشمس : أي شيء أحلى من العسل ، وما أجفى من الأسد ؟ فقال لهم : لو لم تحرثوا على عجلتي ، لما وجدتم أحجيتي '),
(21809, 'Judges', 7, 14, 19, ' وحل عليه روح الرب فنزل إلى أشقلون وقتل منهم ثلاثين رجلا ، وأخذ سلبهم وأعطى الحلل لمظهري الأحجية . وحمي غضبه وصعد إلى بيت أبيه '),
(21810, 'Judges', 7, 14, 20, ' فصارت امرأة شمشون لصاحبه الذي كان يصاحبه '),
(21811, 'Judges', 7, 15, 1, ' وكان بعد مدة في أيام حصاد الحنطة ، أن شمشون افتقد امرأته بجدي معزى '),
(21812, 'Judges', 7, 15, 2, ' وقال : أدخل إلى امرأتي إلى حجرتها . ولكن أباها لم يدعه أن يدخل . وقال أبوها : إني قلت إنك قد كرهتها فأعطيتها لصاحبك . أليست أختها الصغيرة أحسن منها ؟ فلتكن لك عوضا عنها '),
(21813, 'Judges', 7, 15, 3, ' فقال لهم شمشون : إني بريء الآن من الفلسطينيين إذا عملت بهم شرا '),
(21814, 'Judges', 7, 15, 4, ' وذهب شمشون وأمسك ثلاث مئة ابن آوى ، وأخذ مشاعل وجعل ذنبا إلى ذنب ، ووضع مشعلا بين كل ذنبين في الوسط '),
(21815, 'Judges', 7, 15, 5, ' ثم أضرم المشاعل نارا وأطلقها بين زروع الفلسطينيين ، فأحرق الأكداس والزرع وكروم الزيتون '),
(21816, 'Judges', 7, 15, 6, ' فقال الفلسطينيون : من فعل هذا ؟ فقالوا : شمشون صهر التمني ، لأنه أخذ امرأته وأعطاها لصاحبه . فصعد الفلسطينيون وأحرقوها وأباها بالنار '),
(21817, 'Judges', 7, 15, 7, ' فقال لهم شمشون : ولو فعلتم هذا فإني أنتقم منكم ، وبعد أكف '),
(21818, 'Judges', 7, 15, 8, ' وضربهم ساقا على فخذ ضربا عظيما . ثم نزل وأقام في شق صخرة عيطم '),
(21819, 'Judges', 7, 15, 9, ' وصعد الفلسطينيون ونزلوا في يهوذا وتفرقوا في لحي '),
(21820, 'Judges', 7, 15, 10, ' فقال رجال يهوذا : لماذا صعدتم علينا ؟ فقالوا : صعدنا لكي نوثق شمشون لنفعل به كما فعل بنا '),
(21821, 'Judges', 7, 15, 11, ' فنزل ثلاثة آلاف رجل من يهوذا إلى شق صخرة عيطم ، وقالوا لشمشون : أما علمت أن الفلسطينيين متسلطون علينا ؟ فماذا فعلت بنا ؟ فقال لهم : كما فعلوا بي هكذا فعلت بهم '),
(21822, 'Judges', 7, 15, 12, ' فقالوا له : نزلنا لكي نوثقك ونسلمك إلى يد الفلسطينيين . فقال لهم شمشون : احلفوا لي أنكم أنتم لا تقعون علي '),
(21823, 'Judges', 7, 15, 13, ' فكلموه قائلين : كلا . ولكننا نوثقك ونسلمك إلى يدهم ، وقتلا لا نقتلك . فأوثقوه بحبلين جديدين وأصعدوه من الصخرة '),
(21824, 'Judges', 7, 15, 14, ' ولما جاء إلى لحي ، صاح الفلسطينيون للقائه . فحل عليه روح الرب ، فكان الحبلان اللذان على ذراعيه ككتان أحرق بالنار ، فانحل الوثاق عن يديه '),
(21825, 'Judges', 7, 15, 15, ' ووجد لحي حمار طريا ، فمد يده وأخذه وضرب به ألف رجل '),
(21826, 'Judges', 7, 15, 16, ' فقال شمشون : بلحي حمار كومة كومتين . بلحي حمار قتلت ألف رجل '),
(21827, 'Judges', 7, 15, 17, ' ولما فرغ من الكلام رمى اللحي من يده ، ودعا ذلك المكان رمت لحي '),
(21828, 'Judges', 7, 15, 18, ' ثم عطش جدا فدعا الرب وقال : إنك قد جعلت بيد عبدك هذا الخلاص العظيم ، والآن أموت من العطش وأسقط بيد الغلف '),
(21829, 'Judges', 7, 15, 19, ' فشق الله الكفة التي في لحي ، فخرج منها ماء ، فشرب ورجعت روحه فانتعش . لذلك دعا اسمه عين هقوري التي في لحي إلى هذا اليوم '),
(21830, 'Judges', 7, 15, 20, ' وقضى لإسرائيل في أيام الفلسطينيين عشرين سنة '),
(21831, 'Judges', 7, 16, 1, ' ثم ذهب شمشون إلى غزة ، ورأى هناك امرأة زانية فدخل إليها '),
(21832, 'Judges', 7, 16, 2, ' فقيل للغزيين : قد أتى شمشون إلى هنا . فأحاطوا به وكمنوا له الليل كله عند باب المدينة . فهدأوا الليل كله قائلين : عند ضوء الصباح نقتله '),
(21833, 'Judges', 7, 16, 3, ' فاضطجع شمشون إلى نصف الليل ، ثم قام في نصف الليل وأخذ مصراعي باب المدينة والقائمتين وقلعهما مع العارضة ، ووضعها على كتفيه وصعد بها إلى رأس الجبل الذي مقابل حبرون '),
(21834, 'Judges', 7, 16, 4, ' وكان بعد ذلك أنه أحب امرأة في وادي سورق اسمها دليلة '),
(21835, 'Judges', 7, 16, 5, ' فصعد إليها أقطاب الفلسطينيين وقالوا لها : تملقيه وانظري بماذا قوته العظيمة ، وبماذا نتمكن منه لكي نوثقه لإذلاله ، فنعطيك كل واحد ألفا ومئة شاقل فضة '),
(21836, 'Judges', 7, 16, 6, ' فقالت دليلة لشمشون : أخبرني بماذا قوتك العظيمة ؟ وبماذا توثق لإذلالك '),
(21837, 'Judges', 7, 16, 7, ' فقال لها شمشون : إذا أوثقوني بسبعة أوتار طرية لم تجف ، أضعف وأصير كواحد من الناس '),
(21838, 'Judges', 7, 16, 8, ' فأصعد لها أقطاب الفلسطينيين سبعة أوتار طرية لم تجف ، فأوثقته بها '),
(21839, 'Judges', 7, 16, 9, ' والكمين لابث عندها في الحجرة . فقالت له : الفلسطينيون عليك يا شمشون . فقطع الأوتار كما يقطع فتيل المشاقة إذا شم النار ، ولم تعلم قوته '),
(21840, 'Judges', 7, 16, 10, ' فقالت دليلة لشمشون : ها قد ختلتني وكلمتني بالكذب ، فأخبرني الآن بماذا توثق '),
(21841, 'Judges', 7, 16, 11, ' فقال لها : إذا أوثقوني بحبال جديدة لم تستعمل ، أضعف وأصير كواحد من الناس '),
(21842, 'Judges', 7, 16, 12, ' فأخذت دليلة حبالا جديدة وأوثقته بها ، وقالت له : الفلسطينيون عليك يا شمشون ، والكمين لابث في الحجرة . فقطعها عن ذراعيه كخيط '),
(21843, 'Judges', 7, 16, 13, ' فقالت دليلة لشمشون : حتى الآن ختلتني وكلمتني بالكذب ، فأخبرني بماذا توثق ؟  . فقال لها : إذا ضفرت سبع خصل رأسي مع السدى '),
(21844, 'Judges', 7, 16, 14, ' فمكنتها بالوتد . وقالت له : الفلسطينيون عليك يا شمشون . فانتبه من نومه وقلع وتد النسيج والسدى '),
(21845, 'Judges', 7, 16, 15, ' فقالت له : كيف تقول أحبك ، وقلبك ليس معي ؟ هوذا ثلاث مرات قد ختلتني ولم تخبرني بماذا قوتك العظيمة '),
(21846, 'Judges', 7, 16, 16, ' ولما كانت تضايقه بكلامها كل يوم وألحت عليه ، ضاقت نفسه إلى الموت '),
(21847, 'Judges', 7, 16, 17, ' فكشف لها كل قلبه ، وقال لها : لم يعل موسى رأسي لأني نذير الله من بطن أمي ، فإن حلقت تفارقني قوتي وأضعف وأصير كأحد الناس '),
(21848, 'Judges', 7, 16, 18, ' ولما رأت دليلة أنه قد أخبرها بكل ما بقلبه ، أرسلت فدعت أقطاب الفلسطينيين وقالت : اصعدوا هذه المرة فإنه قد كشف لي كل قلبه . فصعد إليها أقطاب الفلسطينيين وأصعدوا الفضة بيدهم '),
(21849, 'Judges', 7, 16, 19, ' وأنامته على ركبتيها ودعت رجلا وحلقت سبع خصل رأسه ، وابتدأت بإذلاله ، وفارقته قوته '),
(21850, 'Judges', 7, 16, 20, ' وقالت : الفلسطينيون عليك يا شمشون . فانتبه من نومه وقال : أخرج حسب كل مرة وأنتفض . ولم يعلم أن الرب قد فارقه '),
(21851, 'Judges', 7, 16, 21, ' فأخذه الفلسطينيون وقلعوا عينيه ، ونزلوا به إلى غزة وأوثقوه بسلاسل نحاس . وكان يطحن في بيت السجن '),
(21852, 'Judges', 7, 16, 22, ' وابتدأ شعر رأسه ينبت بعد أن حلق '),
(21853, 'Judges', 7, 16, 23, ' وأما أقطاب الفلسطينيين فاجتمعوا ليذبحوا ذبيحة عظيمة لداجون إلههم ويفرحوا ، وقالوا : قد دفع إلهنا ليدنا شمشون عدونا '),
(21854, 'Judges', 7, 16, 24, ' ولما رآه الشعب مجدوا إلههم ، لأنهم قالوا : قد دفع إلهنا ليدنا عدونا الذي خرب أرضنا وكثر قتلانا '),
(21855, 'Judges', 7, 16, 25, ' وكان لما طابت قلوبهم أنهم قالوا : ادعوا شمشون ليلعب لنا . فدعوا شمشون من بيت السجن ، فلعب أمامهم . وأوقفوه بين الأعمدة '),
(21856, 'Judges', 7, 16, 26, ' فقال شمشون للغلام الماسك بيده : دعني ألمس الأعمدة التي البيت قائم عليها لأستند عليها '),
(21857, 'Judges', 7, 16, 27, ' وكان البيت مملوءا رجالا ونساء ، وكان هناك جميع أقطاب الفلسطينيين ، وعلى السطح نحو ثلاثة آلاف رجل وامرأة ينظرون لعب شمشون '),
(21858, 'Judges', 7, 16, 28, ' فدعا شمشون الرب وقال : يا سيدي الرب ، اذكرني وشددني يا الله هذه المرة فقط ، فأنتقم نقمة واحدة عن عيني من الفلسطينيين '),
(21859, 'Judges', 7, 16, 29, ' وقبض شمشون على العمودين المتوسطين اللذين كان البيت قائما عليهما ، واستند عليهما الواحد بيمينه والآخر بيساره ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(21860, 'Judges', 7, 16, 30, ' وقال شمشون : لتمت نفسي مع الفلسطينيين . وانحنى بقوة فسقط البيت على الأقطاب وعلى كل الشعب الذي فيه ، فكان الموتى الذين أماتهم في موته ، أكثر من الذين أماتهم في حياته '),
(21861, 'Judges', 7, 16, 31, ' فنزل إخوته وكل بيت أبيه وحملوه وصعدوا به ودفنوه بين صرعة وأشتأول ، في قبر منوح أبيه . وهو قضى لإسرائيل عشرين سنة '),
(21862, 'Judges', 7, 17, 1, ' وكان رجل من جبل أفرايم اسمه ميخا '),
(21863, 'Judges', 7, 17, 2, ' فقال لأمه : إن الألف والمئة شاقل الفضة التي أخذت منك ، وأنت لعنت وقلت أيضا في أذني . هوذا الفضة معي . أنا أخذتها . فقالت أمه : مبارك أنت من الرب يا ابني '),
(21864, 'Judges', 7, 17, 3, ' فرد الألف والمئة شاقل الفضة لأمه . فقالت أمه : تقديسا قدست الفضة للرب من يدي لابني لعمل تمثال منحوت وتمثال مسبوك . فالآن أردها لك '),
(21865, 'Judges', 7, 17, 4, ' فرد الفضة لأمه ، فأخذت أمه مئتي شاقل فضة وأعطتها للصائغ فعملها تمثالا منحوتا وتمثالا مسبوكا . وكانا في بيت ميخا '),
(21866, 'Judges', 7, 17, 5, ' وكان للرجل ميخا بيت للآلهة ، فعمل أفودا وترافيم وملأ يد واحد من بنيه فصار له كاهنا '),
(21867, 'Judges', 7, 17, 6, ' وفي تلك الأيام لم يكن ملك في إسرائيل . كان كل واحد يعمل ما يحسن في عينيه '),
(21868, 'Judges', 7, 17, 7, ' وكان غلام من بيت لحم يهوذا من عشيرة يهوذا ، وهو لاوي متغرب هناك '),
(21869, 'Judges', 7, 17, 8, ' فذهب الرجل من المدينة من بيت لحم يهوذا لكي يتغرب حيثما اتفق . فأتى إلى جبل أفرايم إلى بيت ميخا وهو آخذ في طريقه '),
(21870, 'Judges', 7, 17, 9, ' فقال له ميخا : من أين أتيت ؟ فقال له : أنا لاوي من بيت لحم يهوذا ، وأنا ذاهب لكي أتغرب حيثما اتفق '),
(21871, 'Judges', 7, 17, 10, ' فقال له ميخا : أقم عندي وكن لي أبا وكاهنا ، وأنا أعطيك عشرة شواقل فضة في السنة ، وحلة ثياب ، وقوتك . فذهب معه اللاوي '),
(21872, 'Judges', 7, 17, 11, ' فرضي اللاوي بالإقامة مع الرجل ، وكان الغلام له كأحد بنيه '),
(21873, 'Judges', 7, 17, 12, ' فملأ ميخا يد اللاوي ، وكان الغلام له كاهنا ، وكان في بيت ميخا '),
(21874, 'Judges', 7, 17, 13, ' فقال ميخا : الآن علمت أن الرب يحسن إلي ، لأنه صار لي اللاوي كاهنا '),
(21875, 'Judges', 7, 18, 1, ' وفي تلك الأيام لم يكن ملك في إسرائيل ، وفي تلك الأيام كان سبط الدانيين يطلب له ملكا للسكنى لأنه إلى ذلك اليوم لم يقع له نصيب في وسط أسباط إسرائيل '),
(21876, 'Judges', 7, 18, 2, ' فأرسل بنو دان من عشيرتهم خمسة رجال منهم ، رجالا بني بأس من صرعة ومن أشتأول لتجسس الأرض وفحصها . وقالوا لهم : اذهبوا افحصوا الأرض . فجاءوا إلى جبل أفرايم إلى بيت ميخا وباتوا هناك '),
(21877, 'Judges', 7, 18, 3, ' وبينما هم عند بيت ميخا عرفوا صوت الغلام اللاوي ، فمالوا إلى هناك وقالوا له : من جاء بك إلى هنا ؟ وماذا أنت عامل في هذا المكان ؟ وما لك هنا '),
(21878, 'Judges', 7, 18, 4, ' فقال لهم : كذا وكذا عمل لي ميخا ، وقد استأجرني فصرت له كاهنا '),
(21879, 'Judges', 7, 18, 5, ' فقالوا له : اسأل إذن من الله لنعلم : هل ينجح طريقنا الذي نحن سائرون فيه '),
(21880, 'Judges', 7, 18, 6, ' فقال لهم الكاهن : اذهبوا بسلام . أمام الرب طريقكم الذي تسيرون فيه '),
(21881, 'Judges', 7, 18, 7, ' فذهب الخمسة الرجال وجاءوا إلى لايش . ورأوا الشعب الذين فيها ساكنين بطمأنينة كعادة الصيدونيين مستريحين مطمئنين ، وليس في الأرض مؤذ بأمر وارث رياسة . وهم بعيدون عن الصيدونيين وليس لهم أمر مع إنسان '),
(21882, 'Judges', 7, 18, 8, ' وجاءوا إلى إخوتهم إلى صرعة وأشتأول . فقال لهم إخوتهم : ما أنتم '),
(21883, 'Judges', 7, 18, 9, ' فقالوا : قوموا نصعد إليهم ، لأننا رأينا الأرض وهوذا هي جيدة جدا وأنتم ساكتون . لا تتكاسلوا عن الذهاب لتدخلوا وتملكوا الأرض '),
(21884, 'Judges', 7, 18, 10, ' عند مجيئكم تأتون إلى شعب مطمئن ، والأرض واسعة الطرفين . إن الله قد دفعها ليدكم . مكان ليس فيه عوز لشيء مما في الأرض '),
(21885, 'Judges', 7, 18, 11, ' فارتحل من هناك من عشيرة الدانيين من صرعة ومن أشتأول ست مئة رجل متسلحين بعدة الحرب '),
(21886, 'Judges', 7, 18, 12, ' وصعدوا وحلوا في قرية يعاريم في يهوذا . لذلك دعوا ذلك المكان محلة دان إلى هذا اليوم . هوذا هي وراء قرية يعاريم '),
(21887, 'Judges', 7, 18, 13, ' وعبروا من هناك إلى جبل أفرايم وجاءوا إلى بيت ميخا '),
(21888, 'Judges', 7, 18, 14, ' فأجاب الخمسة الرجال الذين ذهبوا لتجسس أرض لايش وقالوا لإخوتهم : أتعلمون أن في هذه البيوت أفودا وترافيم وتمثالا منحوتا وتمثالا مسبوكا . فالآن اعلموا ما تفعلون '),
(21889, 'Judges', 7, 18, 15, ' فمالوا إلى هناك وجاءوا إلى بيت الغلام اللاوي ، بيت ميخا ، وسلموا عليه '),
(21890, 'Judges', 7, 18, 16, ' والست مئة الرجل المتسلحون بعدتهم للحرب واقفون عند مدخل الباب ، هؤلاء من بني دان '),
(21891, 'Judges', 7, 18, 17, ' فصعد الخمسة الرجال الذين ذهبوا لتجسس الأرض ودخلوا إلى هناك ، وأخذوا التمثال المنحوت والأفود والترافيم والتمثال المسبوك ، والكاهن واقف عند مدخل الباب مع الست مئة الرجل المتسلحين بعدة الحرب '),
(21892, 'Judges', 7, 18, 18, ' وهؤلاء دخلوا بيت ميخا وأخذوا التمثال المنحوت والأفود والترافيم والتمثال المسبوك . فقال لهم الكاهن : ماذا تفعلون '),
(21893, 'Judges', 7, 18, 19, ' فقالوا له : اخرس ضع يدك على فمك واذهب معنا وكن لنا أبا وكاهنا . أهو خير لك أن تكون كاهنا لبيت رجل واحد ، أم أن تكون كاهنا لسبط ولعشيرة في إسرائيل '),
(21894, 'Judges', 7, 18, 20, ' فطاب قلب الكاهن ، وأخذ الأفود والترافيم والتمثال المنحوت ودخل في وسط الشعب '),
(21895, 'Judges', 7, 18, 21, ' ثم انصرفوا وذهبوا ووضعوا الأطفال والماشية والثقل قدامهم '),
(21896, 'Judges', 7, 18, 22, ' ولما ابتعدوا عن بيت ميخا اجتمع الرجال الذين في البيوت التي عند بيت ميخا وأدركوا بني دان '),
(21897, 'Judges', 7, 18, 23, ' وصاحوا إلى بني دان فالتفتوا ، وقالوا لميخا : ما لك صرخت '),
(21898, 'Judges', 7, 18, 24, ' فقال : آلهتي التي عملت قد أخذتموها مع الكاهن وذهبتم ، فماذا لي بعد ؟ وما هذا تقولون لي : ما لك '),
(21899, 'Judges', 7, 18, 25, ' فقال له بنو دان : لا تسمع صوتك بيننا لئلا يقع بكم رجال أنفسهم مرة ، فتنزع نفسك وأنفس بيتك '),
(21900, 'Judges', 7, 18, 26, ' وسار بنو دان في طريقهم . ولما رأى ميخا أنهم أشد منه انصرف ورجع إلى بيته '),
(21901, 'Judges', 7, 18, 27, ' وأما هم فأخذوا ما صنع ميخا ، والكاهن الذي كان له ، وجاءوا إلى لايش إلى شعب مستريح مطمئن ، وضربوهم بحد السيف وأحرقوا المدينة بالنار '),
(21902, 'Judges', 7, 18, 28, ' ولم يكن من ينقذ لأنها بعيدة عن صيدون ، ولم يكن لهم أمر مع إنسان ، وهي في الوادي الذي لبيت رحوب . فبنوا المدينة وسكنوا بها '),
(21903, 'Judges', 7, 18, 29, ' ودعوا اسم المدينة دان باسم دان أبيهم الذي ولد لإسرائيل . ولكن اسم المدينة أولا لايش '),
(21904, 'Judges', 7, 18, 30, ' وأقام بنو دان لأنفسهم التمثال المنحوت . وكان يهوناثان ابن جرشوم بن منسى هو وبنوه كهنة لسبط الدانيين إلى يوم سبي الأرض '),
(21905, 'Judges', 7, 18, 31, ' ووضعوا لأنفسهم تمثال ميخا المنحوت الذي عمله ، كل الأيام التي كان فيها بيت الله في شيلوه '),
(21906, 'Judges', 7, 19, 1, ' وفي تلك الأيام حين لم يكن ملك في إسرائيل ، كان رجل لاوي متغربا في عقاب جبل أفرايم ، فاتخذ له امرأة سرية من بيت لحم يهوذا '),
(21907, 'Judges', 7, 19, 2, ' فزنت عليه سريته وذهبت من عنده إلى بيت أبيها في بيت لحم يهوذا ، وكانت هناك أياما أربعة أشهر '),
(21908, 'Judges', 7, 19, 3, ' فقام رجلها وسار وراءها ليطيب قلبها ويردها ، ومعه غلامه وحماران . فأدخلته بيت أبيها . فلما رآه أبو الفتاة فرح بلقائه '),
(21909, 'Judges', 7, 19, 4, ' وأمسكه حموه أبو الفتاة ، فمكث معه ثلاثة أيام ، فأكلوا وشربوا وباتوا هناك '),
(21910, 'Judges', 7, 19, 5, ' وكان في اليوم الرابع أنهم بكروا صباحا وقام للذهاب . فقال أبو الفتاة لصهره : أسند قلبك بكسرة خبز ، وبعد تذهبون '),
(21911, 'Judges', 7, 19, 6, ' فجلسا وأكلا كلاهما معا وشربا . وقال أبو الفتاة للرجل : ارتض وبت ، وليطب قلبك '),
(21912, 'Judges', 7, 19, 7, ' ولما قام الرجل للذهاب ، ألح عليه حموه فعاد وبات هناك '),
(21913, 'Judges', 7, 19, 8, ' ثم بكر في الغد في اليوم الخامس للذهاب . فقال أبو الفتاة : أسند قلبك ، وتوانوا حتى يميل النهار . وأكلا كلاهما '),
(21914, 'Judges', 7, 19, 9, ' ثم قام الرجل للذهاب هو وسريته وغلامه ، فقال له حموه أبو الفتاة : إن النهار قد مال إلى الغروب . بيتوا الآن . هوذا آخر النهار . بت هنا وليطب قلبك ، وغدا تبكرون في طريقكم وتذهب إلى خيمتك '),
(21915, 'Judges', 7, 19, 10, ' فلم يرد الرجل أن يبيت ، بل قام وذهب وجاء إلى مقابل يبوس ، هي أورشليم ، ومعه حماران مشدودان وسريته معه '),
(21916, 'Judges', 7, 19, 11, ' وفيما هم عند يبوس والنهار قد انحدر جدا ، قال الغلام لسيده : تعال نميل إلى مدينة اليبوسيين هذه ونبيت فيها '),
(21917, 'Judges', 7, 19, 12, ' فقال له سيده : لا نميل إلى مدينة غريبة حيث ليس أحد من بني إسرائيل هنا . نعبر إلى جبعة '),
(21918, 'Judges', 7, 19, 13, ' وقال لغلامه : تعال نتقدم إلى أحد الأماكن ونبيت في جبعة أو في الرامة '),
(21919, 'Judges', 7, 19, 14, ' فعبروا وذهبوا . وغابت لهم الشمس عند جبعة التي لبنيامين '),
(21920, 'Judges', 7, 19, 15, ' فمالوا إلى هناك لكي يدخلوا ويبيتوا في جبعة . فدخل وجلس في ساحة المدينة ولم يضمهم أحد إلى بيته للمبيت '),
(21921, 'Judges', 7, 19, 16, ' وإذا برجل شيخ جاء من شغله من الحقل عند المساء . والرجل من جبل أفرايم ، وهو غريب في جبعة ، ورجال المكان بنيامينيون '),
(21922, 'Judges', 7, 19, 17, ' فرفع عينيه ورأى الرجل المسافر في ساحة المدينة ، فقال الرجل الشيخ : إلى أين تذهب ؟ ومن أين أتيت '),
(21923, 'Judges', 7, 19, 18, ' فقال له : نحن عابرون من بيت لحم يهوذا إلى عقاب جبل أفرايم . أنا من هناك ، وقد ذهبت إلى بيت لحم يهوذا ، وأنا ذاهب إلى بيت الرب وليس أحد يضمني إلى البيت '),
(21924, 'Judges', 7, 19, 19, ' وأيضا عندنا تبن وعلف لحميرنا ، وأيضا خبز وخمر لي ولأمتك وللغلام الذي مع عبيدك . ليس احتياج إلى شيء '),
(21925, 'Judges', 7, 19, 20, ' فقال الرجل الشيخ : السلام لك . إنما كل احتياجك علي ، ولكن لا تبت في الساحة '),
(21926, 'Judges', 7, 19, 21, ' وجاء به إلى بيته ، وعلف حميرهم ، فغسلوا أرجلهم وأكلوا وشربوا '),
(21927, 'Judges', 7, 19, 22, ' وفيما هم يطيبون قلوبهم ، إذا برجال المدينة ، رجال بني بليعال ، أحاطوا بالبيت قارعين الباب ، وكلموا الرجل صاحب البيت الشيخ قائلين : أخرج الرجل الذي دخل بيتك فنعرفه '),
(21928, 'Judges', 7, 19, 23, ' فخرج إليهم الرجل صاحب البيت وقال لهم : لا يا إخوتي . لا تفعلوا شرا . بعدما دخل هذا الرجل بيتي لا تفعلوا هذه القباحة '),
(21929, 'Judges', 7, 19, 24, ' هوذا ابنتي العذراء وسريته . دعوني أخرجهما ، فأذلوهما وافعلوا بهما ما يحسن في أعينكم . وأما هذا الرجل فلا تعملوا به هذا الأمر القبيح '),
(21930, 'Judges', 7, 19, 25, ' فلم يرد الرجال أن يسمعوا له . فأمسك الرجل سريته وأخرجها إليهم خارجا ، فعرفوها وتعللوا بها الليل كله إلى الصباح . وعند طلوع الفجر أطلقوها '),
(21931, 'Judges', 7, 19, 26, ' فجاءت المرأة عند إقبال الصباح وسقطت عند باب بيت الرجل حيث سيدها هناك إلى الضوء '),
(21932, 'Judges', 7, 19, 27, ' فقام سيدها في الصباح وفتح أبواب البيت وخرج للذهاب في طريقه ، وإذا بالمرأة سريته ساقطة على باب البيت ، ويداها على العتبة '),
(21933, 'Judges', 7, 19, 28, ' فقال لها : قومي نذهب . فلم يكن مجيب . فأخذها على الحمار وقام الرجل وذهب إلى مكانه '),
(21934, 'Judges', 7, 19, 29, ' ودخل بيته وأخذ السكين وأمسك سريته وقطعها مع عظامها إلى اثنتي عشرة قطعة ، وأرسلها إلى جميع تخوم إسرائيل '),
(21935, 'Judges', 7, 19, 30, ' وكل من رأى قال : لم يكن ولم ير مثل هذا من يوم صعود بني إسرائيل من أرض مصر إلى هذا اليوم . تبصروا فيه وتشاوروا وتكلموا '),
(21936, 'Judges', 7, 20, 1, ' فخرج جميع بني إسرائيل ، واجتمعت الجماعة كرجل واحد ، من دان إلى بئر سبع مع أرض جلعاد ، إلى الرب في المصفاة '),
(21937, 'Judges', 7, 20, 2, ' ووقف وجوه جميع الشعب ، جميع أسباط إسرائيل في مجمع شعب الله ، أربع مئة ألف راجل مخترطي السيف '),
(21938, 'Judges', 7, 20, 3, ' فسمع بنو بنيامين أن بني إسرائيل قد صعدوا إلى المصفاة . وقال بنو إسرائيل : تكلموا ، كيف كانت هذه القباحة '),
(21939, 'Judges', 7, 20, 4, ' فأجاب الرجل اللاوي بعل المرأة المقتولة وقال : دخلت أنا وسريتي إلى جبعة التي لبنيامين لنبيت '),
(21940, 'Judges', 7, 20, 5, ' فقام علي أصحاب جبعة وأحاطوا علي بالبيت ليلا وهموا بقتلي ، وأذلوا سريتي حتى ماتت '),
(21941, 'Judges', 7, 20, 6, ' فأمسكت سريتي وقطعتها وأرسلتها إلى جميع حقول ملك إسرائيل ، لأنهم فعلوا رذالة وقباحة في إسرائيل '),
(21942, 'Judges', 7, 20, 7, ' هوذا كلكم بنو إسرائيل . هاتوا حكمكم ورأيكم ههنا '),
(21943, 'Judges', 7, 20, 8, ' فقام جميع الشعب كرجل واحد وقالوا : لا يذهب أحد منا إلى خيمته ولا يميل أحد إلى بيته '),
(21944, 'Judges', 7, 20, 9, ' والآن هذا هو الأمر الذي نعمله بجبعة . عليها بالقرعة '),
(21945, 'Judges', 7, 20, 10, ' فنأخذ عشرة رجال من المئة من جميع أسباط إسرائيل ، ومئة من الألف ، وألفا من الربوة ، لأجل أخذ زاد للشعب ليفعلوا عند دخولهم جبعة ببنيامين حسب كل القباحة التي فعلت بإسرائيل '),
(21946, 'Judges', 7, 20, 11, ' فاجتمع جميع رجال إسرائيل على المدينة متحدين كرجل واحد '),
(21947, 'Judges', 7, 20, 12, ' وأرسل أسباط إسرائيل رجالا إلى جميع أسباط بنيامين قائلين : ما هذا الشر الذي صار فيكم '),
(21948, 'Judges', 7, 20, 13, ' فالآن سلموا القوم بني بليعال الذين في جبعة لكي نقتلهم وننزع الشر من إسرائيل . فلم يرد بنو بنيامين أن يسمعوا لصوت إخوتهم بني إسرائيل '),
(21949, 'Judges', 7, 20, 14, ' فاجتمع بنو بنيامين من المدن إلى جبعة لكي يخرجوا لمحاربة بني إسرائيل '),
(21950, 'Judges', 7, 20, 15, ' وعد بنو بنيامين في ذلك اليوم من المدن ستة وعشرين ألف رجل مخترطي السيف ، ما عدا سكان جبعة الذين عدوا سبع مئة رجل منتخبين '),
(21951, 'Judges', 7, 20, 16, ' من جميع هذا الشعب سبع مئة رجل منتخبون عسر . كل هؤلاء يرمون الحجر بالمقلاع على الشعرة ولا يخطئون '),
(21952, 'Judges', 7, 20, 17, ' وعد رجال إسرائيل ، ما عدا بنيامين ، أربع مئة ألف رجل مخترطي السيف . كل هؤلاء رجال حرب '),
(21953, 'Judges', 7, 20, 18, ' فقاموا وصعدوا إلى بيت إيل وسألوا الله وقال بنو إسرائيل : من يصعد منا أولا لمحاربة بني بنيامين ؟ فقال الرب : يهوذا أولا '),
(21954, 'Judges', 7, 20, 19, ' فقام بنو إسرائيل في الصباح ونزلوا على جبعة '),
(21955, 'Judges', 7, 20, 20, ' وخرج رجال إسرائيل لمحاربة بنيامين ، وصف رجال إسرائيل أنفسهم للحرب عند جبعة '),
(21956, 'Judges', 7, 20, 21, ' فخرج بنو بنيامين من جبعة وأهلكوا من إسرائيل في ذلك اليوم اثنين وعشرين ألف رجل إلى الأرض '),
(21957, 'Judges', 7, 20, 22, ' وتشدد الشعب ، رجال إسرائيل ، وعادوا فاصطفوا للحرب في المكان الذي اصطفوا فيه في اليوم الأول '),
(21958, 'Judges', 7, 20, 23, ' ثم صعد بنو إسرائيل وبكوا أمام الرب إلى المساء ، وسألوا الرب قائلين : هل أعود أتقدم لمحاربة بني بنيامين أخي ؟ فقال الرب : اصعدوا إليه '),
(21959, 'Judges', 7, 20, 24, ' فتقدم بنو إسرائيل إلى بني بنيامين في اليوم الثاني '),
(21960, 'Judges', 7, 20, 25, ' فخرج بنيامين للقائهم من جبعة في اليوم الثاني ، وأهلك من بني إسرائيل أيضا ثمانية عشر ألف رجل إلى الأرض . كل هؤلاء مخترطو السيف '),
(21961, 'Judges', 7, 20, 26, ' فصعد جميع بني إسرائيل وكل الشعب وجاءوا إلى بيت إيل وبكوا وجلسوا هناك أمام الرب ، وصاموا ذلك اليوم إلى المساء ، وأصعدوا محرقات وذبائح سلامة أمام الرب '),
(21962, 'Judges', 7, 20, 27, ' وسأل بنو إسرائيل الرب ، وهناك تابوت عهد الله في تلك الأيام '),
(21963, 'Judges', 7, 20, 28, ' وفينحاس بن ألعازار بن هارون واقف أمامه في تلك الأيام ، قائلين : أأعود أيضا للخروج لمحاربة بني بنيامين أخي أم أكف ؟ فقال الرب : اصعدوا ، لأني غدا أدفعهم ليدك '),
(21964, 'Judges', 7, 20, 29, ' ووضع إسرائيل كمينا على جبعة محيطا '),
(21965, 'Judges', 7, 20, 30, ' وصعد بنو إسرائيل على بني بنيامين في اليوم الثالث واصطفوا عند جبعة كالمرة الأولى والثانية '),
(21966, 'Judges', 7, 20, 31, ' فخرج بنو بنيامين للقاء الشعب وانجذبوا عن المدينة ، وأخذوا يضربون من الشعب قتلى كالمرة الأولى والثانية في السكك التي إحداها تصعد إلى بيت إيل ، والأخرى إلى جبعة في الحقل ، نحو ثلاثين رجلا من إسرائيل '),
(21967, 'Judges', 7, 20, 32, ' وقال بنو بنيامين : إنهم منهزمون أمامنا كما في الأول . وأما بنو إسرائيل فقالوا : لنهرب ونجذبهم عن المدينة إلى السكك '),
(21968, 'Judges', 7, 20, 33, ' وقام جميع رجال إسرائيل من أماكنهم واصطفوا في بعل تامار ، وثار كمين إسرائيل من مكانه من عراء جبعة '),
(21969, 'Judges', 7, 20, 34, ' وجاء من مقابل جبعة عشرة آلاف رجل منتخبون من كل إسرائيل ، وكانت الحرب شديدة ، وهم لم يعلموا أن الشر قد مسهم '),
(21970, 'Judges', 7, 20, 35, ' فضرب الرب بنيامين أمام إسرائيل ، وأهلك بنو إسرائيل من بنيامين في ذلك اليوم خمسة وعشرين ألف رجل ومئة رجل . كل هؤلاء مخترطو السيف '),
(21971, 'Judges', 7, 20, 36, ' ورأى بنو بنيامين أنهم قد انكسروا . وأعطى رجال إسرائيل مكانا لبنيامين لأنهم اتكلوا على الكمين الذي وضعوه على جبعة '),
(21972, 'Judges', 7, 20, 37, ' فأسرع الكمين واقتحموا جبعة ، وزحف الكمين وضرب المدينة كلها بحد السيف '),
(21973, 'Judges', 7, 20, 38, ' وكان الميعاد بين رجال إسرائيل وبين الكمين ، إصعادهم بكثرة ، علامة الدخان من المدينة '),
(21974, 'Judges', 7, 20, 39, ' ولما انقلب رجال إسرائيل في الحرب ابتدأ بنيامين يضربون قتلى من رجال إسرائيل نحو ثلاثين رجلا ، لأنهم قالوا : إنما هم منهزمون من أمامنا كالحرب الأولى '),
(21975, 'Judges', 7, 20, 40, ' ولما ابتدأت العلامة تصعد من المدينة ، عمود دخان ، التفت بنيامين إلى ورائه وإذا بالمدينة كلها تصعد نحو السماء '),
(21976, 'Judges', 7, 20, 41, ' ورجع رجال إسرائيل وهرب رجال بنيامين برعدة ، لأنهم رأوا أن الشر قد مسهم '),
(21977, 'Judges', 7, 20, 42, ' ورجعوا أمام بني إسرائيل في طريق البرية ، ولكن القتال أدركهم ، والذين من المدن أهلكوهم في وسطهم '),
(21978, 'Judges', 7, 20, 43, ' فحاوطوا بنيامين وطاردوهم بسهولة ، وأدركوهم مقابل جبعة لجهة شروق الشمس '),
(21979, 'Judges', 7, 20, 44, ' فسقط من بنيامين ثمانية عشر ألف رجل ، جميع هؤلاء ذوو بأس '),
(21980, 'Judges', 7, 20, 45, ' فداروا وهربوا إلى البرية إلى صخرة رمون . فالتقطوا منهم في السكك خمسة آلاف رجل ، وشدوا وراءهم إلى جدعوم ، وقتلوا منهم ألفي رجل '),
(21981, 'Judges', 7, 20, 46, ' وكان جميع الساقطين من بنيامين خمسة وعشرين ألف رجل مخترطي السيف في ذلك اليوم . جميع هؤلاء ذوو بأس '),
(21982, 'Judges', 7, 20, 47, ' ودار وهرب إلى البرية إلى صخرة رمون ست مئة رجل ، وأقاموا في صخرة رمون أربعة أشهر '),
(21983, 'Judges', 7, 20, 48, ' ورجع رجال بني إسرائيل إلى بني بنيامين وضربوهم بحد السيف من المدينة بأسرها ، حتى البهائم ، حتى كل ما وجد . وأيضا جميع المدن التي وجدت أحرقوها بالنار '),
(21984, 'Judges', 7, 21, 1, ' ورجال إسرائيل حلفوا في المصفاة قائلين : لا يسلم أحد منا ابنته لبنيامين امرأة '),
(21985, 'Judges', 7, 21, 2, ' وجاء الشعب إلى بيت إيل وأقاموا هناك إلى المساء أمام الله ، ورفعوا صوتهم وبكوا بكاء عظيما '),
(21986, 'Judges', 7, 21, 3, ' وقالوا : لماذا يارب إله إسرائيل حدثت هذه في إسرائيل ، حتى يفقد اليوم من إسرائيل سبط '),
(21987, 'Judges', 7, 21, 4, ' وفي الغد بكر الشعب وبنوا هناك مذبحا ، وأصعدوا محرقات وذبائح سلامة '),
(21988, 'Judges', 7, 21, 5, ' وقال بنو إسرائيل : من هو الذي لم يصعد في المجمع من جميع أسباط إسرائيل إلى الرب ؟ لأنه صار الحلف العظيم على الذي لم يصعد إلى الرب إلى المصفاة قائلا : يمات موتا '),
(21989, 'Judges', 7, 21, 6, ' وندم بنو إسرائيل على بنيامين أخيهم وقالوا : قد انقطع اليوم سبط واحد من إسرائيل '),
(21990, 'Judges', 7, 21, 7, ' ماذا نعمل للباقين منهم في أمر النساء ، وقد حلفنا نحن بالرب أن لا نعطيهم من بناتنا نساء '),
(21991, 'Judges', 7, 21, 8, ' وقالوا : أي سبط من أسباط إسرائيل لم يصعد إلى الرب إلى المصفاة ؟ وهوذا لم يأت إلى المحلة رجل من يابيش جلعاد إلى المجمع '),
(21992, 'Judges', 7, 21, 9, ' فعد الشعب فلم يكن هناك رجل من سكان يابيش جلعاد '),
(21993, 'Judges', 7, 21, 10, ' فأرسلت الجماعة إلى هناك اثني عشر ألف رجل من بني البأس ، وأوصوهم قائلين : اذهبوا واضربوا سكان يابيش جلعاد بحد السيف مع النساء والأطفال '),
(21994, 'Judges', 7, 21, 11, ' وهذا ما تعملونه : تحرمون كل ذكر وكل امرأة عرفت اضطجاع ذكر '),
(21995, 'Judges', 7, 21, 12, ' فوجدوا من سكان يابيش جلعاد أربع مئة فتاة عذارى لم يعرفن رجلا بالاضطجاع مع ذكر ، وجاءوا بهن إلى المحلة إلى شيلوه التي في أرض كنعان '),
(21996, 'Judges', 7, 21, 13, ' وأرسلت الجماعة كلها وكلمت بني بنيامين الذين في صخرة رمون واستدعتهم إلى الصلح '),
(21997, 'Judges', 7, 21, 14, ' فرجع بنيامين في ذلك الوقت ، فأعطوهم النساء اللواتي استحيوهن من نساء يابيش جلعاد . ولم يكفوهم هكذا '),
(21998, 'Judges', 7, 21, 15, ' وندم الشعب من أجل بنيامين ، لأن الرب جعل شقا في أسباط إسرائيل '),
(21999, 'Judges', 7, 21, 16, ' فقال شيوخ الجماعة : ماذا نصنع بالباقين في أمر النساء ، لأنه قد انقطعت النساء من بنيامين '),
(22000, 'Judges', 7, 21, 17, ' وقالوا : ميراث نجاة لبنيامين ، ولا يمحى سبط من إسرائيل '),
(22001, 'Judges', 7, 21, 18, ' ونحن لا نقدر أن نعطيهم نساء من بناتنا ، لأن بني إسرائيل حلفوا قائلين : ملعون من أعطى امرأة لبنيامين '),
(22002, 'Judges', 7, 21, 19, ' ثم قالوا : هوذا عيد الرب في شيلوه من سنة إلى سنة شمالي بيت إيل ، شرقي الطريق الصاعدة من بيت إيل إلى شكيم وجنوبي لبونة '),
(22003, 'Judges', 7, 21, 20, ' وأوصوا بني بنيامين قائلين : امضوا واكمنوا في الكروم '),
(22004, 'Judges', 7, 21, 21, ' وانظروا . فإذا خرجت بنات شيلوه ليدرن في الرقص ، فاخرجوا أنتم من الكروم واخطفوا لأنفسكم كل واحد امرأته من بنات شيلوه ، واذهبوا إلى أرض بنيامين '),
(22005, 'Judges', 7, 21, 22, ' فإذا جاء آباؤهن أو إخوتهن لكي يشكوا إلينا ، نقول لهم : تراءفوا عليهم لأجلنا ، لأننا لم نأخذ لكل واحد امرأته في الحرب ، لأنكم أنتم لم تعطوهم في الوقت حتى تكونوا قد أثمتم '),
(22006, 'Judges', 7, 21, 23, ' ففعل هكذا بنو بنيامين ، واتخذوا نساء حسب عددهم من الراقصات اللواتي اختطفوهن ، وذهبوا ورجعوا إلى ملكهم وبنوا المدن وسكنوا بها '),
(22007, 'Judges', 7, 21, 24, ' فسار من هناك بنو إسرائيل في ذلك الوقت كل واحد إلى سبطه وعشيرته ، وخرجوا من هناك كل واحد إلى ملكه '),
(22008, 'Judges', 7, 21, 25, ' في تلك الأيام لم يكن ملك في إسرائيل . كل واحد عمل ما حسن في عينيه '),
(22009, 'Judith', 68, 1, 1, 'كان ارفكشاد ملك الماديين قد اخضع امما كثيرة لسلطانه وبنى مدينة منيعة جدا سماها احمتا'),
(22010, 'Judith', 68, 1, 2, 'بناها من حجارة مربعة منحوتة وابتنى اسوارها على ارتفاع سبعين ذراعا في عرض ثلاثين ذراعا وشيد بروجها على ارتفاع مئة ذراع'),
(22011, 'Judith', 68, 1, 3, 'مساحة كل جانب من مربعها عشرون قدما وجعل ابوابها في علو الابراج'),
(22012, 'Judith', 68, 1, 4, 'و كان يفتخر بقدرته وسطوة جيشه وعزة مراكبه'),
(22013, 'Judith', 68, 1, 5, 'و ان نبوكد نصر ملك اشور الذي كان مالكا على نينوى المدينة العظيمة في السنة الثانية عشرة من ملكه حارب ارفشكاد فظفر به'),
(22014, 'Judith', 68, 1, 6, 'في الصحراء العظيمة التي يقال لها رعاوى عند الفرات ودجلة ويادسون في صحراء اريوك ملك عليم'),
(22015, 'Judith', 68, 1, 7, 'فعظم اذ ذاك ملك نبوكد نصر وسمت نفسه فراسل جميع سكان قيليقية ودمشق ولبنان'),
(22016, 'Judith', 68, 1, 8, 'و الامم التي في الكرمل وقيدار وسكان الجليل في صحراء يزرعيل الواسعة'),
(22017, 'Judith', 68, 1, 9, 'و جميع من في السامرة وعبر الاردن الى اورشليم وفي جميع ارض يسى الى حدود الحبشة'),
(22018, 'Judith', 68, 1, 10, 'الى جميع اولئك بعث نبوكد نصر ملك اشور رسلا'),
(22019, 'Judith', 68, 1, 11, 'فابى جميعهم اتفاقا وردوا الرسل خائبين وطردوهم بلا كرامة'),
(22020, 'Judith', 68, 1, 12, 'فاستشاط حينئذ نبوكد نصر الملك غضبا على تلك الارض باسرها وحلف بعرشه وملكه لينتقمن من جميع تلك البلاد'),
(22021, 'Judith', 68, 2, 1, 'و في السنة الثالثة عشرة لنبوكد نصر وفي اليوم الثاني والعشرين من الشهر الاول تمت الكلمة في بيت نبوكد نصر ملك اشور بالانتقام'),
(22022, 'Judith', 68, 2, 2, 'فدعا جميع الشيوخ وكل قواده ورجال حربه وواضعهم مشورة سرية'),
(22023, 'Judith', 68, 2, 3, 'و قال لهم ان في نفسه ان يخضع كل الارض لملكه'),
(22024, 'Judith', 68, 2, 4, 'و اذ حسن ذلك لدى الجميع استدعى نبوكد نصر الملك اليفانا قائد جيشه'),
(22025, 'Judith', 68, 2, 5, 'و قال له اخرج على جميع ممالك الغرب وخصوصا الذين استهانوا باوامري'),
(22026, 'Judith', 68, 2, 6, 'و لا تشفق عينك على مملكة ما واخضع لي جميع المدن المحصنة'),
(22027, 'Judith', 68, 2, 7, 'فدعا اليفانا القواد وعظماء جيش اشور واحصى عدد رجال الحرب كما امره الملك مئة وعشرين الف راجل مقاتلين واثني عشر الف فارس ارباب قسي'),
(22028, 'Judith', 68, 2, 8, 'و سير امام جيوشه عددا لا يحصى من الجمال بما يكفي الجيش بكثرة ومن اصورة البقر وقطعان الغنم ما لا يحصى'),
(22029, 'Judith', 68, 2, 9, 'و امر ان تجمع الحنطة من كل سورية عند عبوره'),
(22030, 'Judith', 68, 2, 10, 'و اخذ من بيت الملك من الذهب والفضة شيئا كثيرا جدا'),
(22031, 'Judith', 68, 2, 11, 'ثم ارتحل بجميع جيشه ومراكبه وفرسانه وارباب القسي وكانوا يغطون وجه الارض كالجراد'),
(22032, 'Judith', 68, 2, 12, 'فلما جاوز تخوم اشور انتهى الى جبال انجة العظيمة التي الى يسار قيليقية وزحف على جميع قلاعهم وتسلم كل الحصون'),
(22033, 'Judith', 68, 2, 13, 'و فتح مدينة ملوطة المشهورة ونهب جميع بني ترشيش وبني اسماعيل الذين حيال البرية وجهة جنوب ارض كلون'),
(22034, 'Judith', 68, 2, 14, 'ثم عبر الفرات واتى الى ما بين النهرين وقهر جميع ما هناك من المدن المشيدة من وادي ممرا الى حد البحر'),
(22035, 'Judith', 68, 2, 15, 'و استولى على حدودها من قيليقية الى تخوم يافث التي الى الجنوب'),
(22036, 'Judith', 68, 2, 16, 'و اسر جميع بني مدين وغنم كل ثروتهم وكل من قاومهم قتله بحد السيف'),
(22037, 'Judith', 68, 2, 17, 'و بعد ذلك انحدر الى صحاري دمشق في ايام الحصاد واحرق جميع حقولهم وقطع كل اشجارهم وكرومهم'),
(22038, 'Judith', 68, 2, 18, 'فوقع رعبه على جميع سكان الارض'),
(22039, 'Judith', 68, 3, 1, 'حينئذ انفذ اليه جميع ملوك ورؤساء المدن والاقاليم رسلهم من سورية التي بين النهرين وسورية صوبال ولوبية وقيليقية فاتوا اليفانا وقالوا له'),
(22040, 'Judith', 68, 3, 2, 'ليكف غضبك عنا فخير ان نحيا عبيدا لنبوكد نصر الملك العظيم وندين لك من ان نموت ونخرب ونتحمل خسف العبودية'),
(22041, 'Judith', 68, 3, 3, 'و هذه مدائننا باسرها وجميع ما نملكه وجبالنا وهضابنا وحقولنا ومواشينا من اصورة البقر وقطعان الغنم والمعز والخيل والابل وجميع مقتنانا وعيالنا بين يديك'),
(22042, 'Judith', 68, 3, 4, 'جميع ما هو لنا تحت امرك'),
(22043, 'Judith', 68, 3, 5, 'و نحن وبنونا عبيد لك'),
(22044, 'Judith', 68, 3, 6, 'فكن في قدومك علينا مولى سلام واستخدمنا بما يحسن عندك'),
(22045, 'Judith', 68, 3, 7, 'حينئذ انحدر من الجبال مع الفرسان بقوة عظيمة واستولى على جميع المدن وكل سكان الارض'),
(22046, 'Judith', 68, 3, 8, 'و اخذ من جميع المدن انصارا له من ذوي الباس ومختارين للحرب'),
(22047, 'Judith', 68, 3, 9, 'فحل على جميع تلك البلدان خوف عظيم حتى خرج للقائه سكان جميع المدن الرؤساء والاشراف مع شعوبهم'),
(22048, 'Judith', 68, 3, 10, 'و استقبلوه بالاكاليل والمصابيح راقصين بالطبول والنايات'),
(22049, 'Judith', 68, 3, 11, 'و لا بصنعهم هذا امكنهم ان يلينوا قساوة قلبه'),
(22050, 'Judith', 68, 3, 12, 'فانه دمر مدنهم وقطع غاباتهم'),
(22051, 'Judith', 68, 3, 13, 'لان نبوكد نصر الملك كان قد امره ان يبيد جميع الهة الارض حتى يدعى هو وحده الها بين جميع تلك الامم التي تدين له بسطوة اليفانا'),
(22052, 'Judith', 68, 3, 14, 'ثم عبر سورية صوبال وبامية كلها وجميع ما بين النهرين واتى الادوميين في ارض جبع'),
(22053, 'Judith', 68, 3, 15, 'و اخذ مدائنهم واقام هناك ثلاثين يوما امر فيها ان تجمع كل قوة جيشه'),
(22054, 'Judith', 68, 4, 1, 'و سمع بنو اسرائيل المقيمون بارض يهوذا فخافوا جدا من وجهه'),
(22055, 'Judith', 68, 4, 2, 'و اخذ الارتعاد بفرائصهم مخافة ان يفعل باورشليم وبهيكل الرب كما فعل بسائر المدن وهياكلها'),
(22056, 'Judith', 68, 4, 3, 'فارسلوا الى جميع السامرة في كل وجه الى حد اريحا وضبطوا رؤوس الجبال كلها'),
(22057, 'Judith', 68, 4, 4, 'و سوروا قراهم وجمعوا الحنطة استعدادا للقتال'),
(22058, 'Judith', 68, 4, 5, 'و كتب الياقيم الكاهن الى جميع الساكنين قبالة يزرعيل التي حيال الصحراء الكبيرة الى جانب دوتان والى جميع الذين يمكن ان يجاز في اراضيهم'),
(22059, 'Judith', 68, 4, 6, 'ان يضبطوا مراقي الجبال التي يمكن ان تسلك الى اورشليم ويحفظوا المضايق التي يمكن ان يجاز منها بين الجبال'),
(22060, 'Judith', 68, 4, 7, 'ففعل بنو اسرائيل كما رسم كاهن الرب الياقيم'),
(22061, 'Judith', 68, 4, 8, 'و صرخ كل الشعب الى الرب بابتهال عظيم وذللوا نفوسهم بالصوم والصلاة هم ونساؤهم'),
(22062, 'Judith', 68, 4, 9, 'و لبس الكهنة المسوح وطرحوا الاطفال امام هيكل الرب وغطوا مذبح الرب بمسح'),
(22063, 'Judith', 68, 4, 10, 'و صرخوا جملة الى الرب اله اسرائيل ان لا يجعل اطفالهم غنيمة ونساءهم مقتسما للاعداء ومدنهم خرابا واقداسهم نجاسة واياهم عارا بين الامم'),
(22064, 'Judith', 68, 4, 11, 'و جال الياقيم كاهن الرب العظيم في جميع اسرائيل وكلمهم قائلا'),
(22065, 'Judith', 68, 4, 12, 'اعلموا ان الرب يستجيب لصلواتكم ان واظبتم على الصوم والصلوات امام الرب'),
(22066, 'Judith', 68, 4, 13, 'اذكروا موسى عبد الرب كيف قهر العمالقة الذين كانوا متكلين على باسهم وقدرتهم وجيشهم وتروسهم ومراكبهم وفرسانهم فقهرهم مقاتلا لا بالسيف بل بالصلوات الطاهرة'),
(22067, 'Judith', 68, 4, 14, 'هكذا يكون جميع اعداء اسرائيل اذا واظبتم على العمل الذي بداتم به'),
(22068, 'Judith', 68, 4, 15, 'و اذ خاطبهم بهذا الكلام تضرعوا الى الرب وكانوا لا يبرحون من امام الرب'),
(22069, 'Judith', 68, 4, 16, 'و كان الذين يقدمون المحرقات الى الرب لابسين المسوح يقربون ذبائح للرب والرماد على رؤوسهم'),
(22070, 'Judith', 68, 4, 17, 'و كانوا بجملتهم يصلون الى الله من كل قلوبهم ان يفتقد شعب اسرائيل'),
(22071, 'Judith', 68, 5, 1, 'و اخبر اليفانا رئيس جيش الاشوريين ان بني اسرائيل قد تاهبوا للمدافعة وانهم قد سدوا طرق الجبال'),
(22072, 'Judith', 68, 5, 2, 'فاستشاط اليفانا غضبا في شدة حنقه ودعا جميع رؤساء مواب وقواد عمون'),
(22073, 'Judith', 68, 5, 3, 'و قال لهم قولوا لي من اولئك الشعب الذين ضبطوا الجبال وما مدنهم وكيف هي وما قوتها وما قدرتهم وكثرتهم ومن قائد جيشهم'),
(22074, 'Judith', 68, 5, 4, 'و كيف استخفوا بنا دون جميع سكان المشرق ولم يخرجوا لاستقبالنا ليتلقونا بالسلم'),
(22075, 'Judith', 68, 5, 5, 'فاجابه احيور قائد جميع بني عمون قائلا ان تنازلت فسمعت لي يا سيدي اقول الحق بين يديك في امر اولئك الشعب المقيمين بالجبال ولا تخرج لفظة كاذبة من فمي'),
(22076, 'Judith', 68, 5, 6, 'ان اولئك الشعب هم من نسل الكلدانيين'),
(22077, 'Judith', 68, 5, 7, 'و كان اول مقامهم فيما بين النهرين لانهم ابوا اتباع الهة ابائهم المقيمين بارض الكلدانيين'),
(22078, 'Judith', 68, 5, 8, 'فتركوا سنن ابائهم التي كانت لالهة كثيرة'),
(22079, 'Judith', 68, 5, 9, 'و سجدوا لاله السماء الواحد وهو امرهم ان يخرجوا من هناك ويسكنوا في حاران فلما عم الجوع الارض كلها هبطوا الى مصر وتكاثروا هناك مدة اربع مئة سنة حتى كان جيشهم لا يحصى'),
(22080, 'Judith', 68, 5, 10, 'و اذ كان ملك مصر يعنتهم بالاثقال ويستعبدهم في بناء مدنه بالطين واللبن صرخوا الى ربهم فضرب جميع ارض مصر ضربات مختلفة'),
(22081, 'Judith', 68, 5, 11, 'و بعد ان طردهم المصريون من ارضهم وكفت الضربة عنهم ارادوا امساكهم ليردوهم الى عبوديتهم'),
(22082, 'Judith', 68, 5, 12, 'و فيما هم هاربون فلق لهم اله السماء البحر وجمدت المياه من الجانبين فعبروا على حضيض البحر على اليبس'),
(22083, 'Judith', 68, 5, 13, 'و تعقبهم هناك جيش المصريين بلا عدد فغمرتهم المياه حتى لم يبق منهم احد يخبر اعقابهم'),
(22084, 'Judith', 68, 5, 14, 'فخرجوا من البحر الاحمر ونزلوا برية جبل سيناء حيث لم يكن يقدر ان يسكن انسان ولا يستريح ابن بشر'),
(22085, 'Judith', 68, 5, 15, 'و هناك حولت لهم ينابيع المياه المرة عذبة ليشربوا ورزقوا طعاما من السماء مدة اربعين سنة'),
(22086, 'Judith', 68, 5, 16, 'و حيثما دخلوا بلا قوس ولا سهم ولا ترس ولا سيف قاتل الههم عنهم وظفر'),
(22087, 'Judith', 68, 5, 17, 'و لم يكن من يستهين بهؤلاء الشعب الا اذا تركوا عبادة الرب الههم'),
(22088, 'Judith', 68, 5, 18, 'فكانوا كلما عبدوا غير الههم اسلموا للغنيمة والسيف والعار'),
(22089, 'Judith', 68, 5, 19, 'و كلما تابوا عن تركهم عبادة الههم اتاهم اله السماء قوة للمدافعة'),
(22090, 'Judith', 68, 5, 20, 'فكسروا امامهم ملوك الكنعانيين واليبوسيين والفرزيين والحثيين والحويين والاموريين وجميع الجبابرة الذين في حشبون واستحوذوا على اراضيهم ومدائنهم'),
(22091, 'Judith', 68, 5, 21, 'و كانوا ما داموا لا يخطاون امام الههم يصيبهم خير لان الههم يبغض الاثم'),
(22092, 'Judith', 68, 5, 22, 'فلما ان حادوا قبل هذه السنين عن الطريق التي امرهم الله ان يسلكوها انكسروا في الحروب امام شعوب كثيرة وجلي كثيرون منهم الى ارض غير ارضهم'),
(22093, 'Judith', 68, 5, 23, 'غير انهم من عهد قريب قد تابوا الى الرب الههم واجتمعوا من شتاتهم حيث تبددوا وصعدوا الى هذه الجبال كلها وعادوا فتملكوا في اورشليم حيث اقداسهم'),
(22094, 'Judith', 68, 5, 24, 'و الان يا سيدي انظر فان كان لاولئك الشعب اثم امام الههم فلنصعد اليهم لان الههم يسلمهم اليك ويستعبدون تحت نير سلطانك'),
(22095, 'Judith', 68, 5, 25, 'و ان لم يكن لاولئك الشعب اثم امام الههم فلا طاقة لنا بهم لان الههم يدافع عنهم فنكون عارا على جميع وجه الارض'),
(22096, 'Judith', 68, 5, 26, 'فلما فرغ احيور من هذا الكلام غضب جميع عظماء اليفانا وهموا بقتله قائلين بعضهم لبعض'),
(22097, 'Judith', 68, 5, 27, 'من يقول ان لبني اسرائيل طاقة بمقاومة الملك نبوكد نصر وجيوشه وهم قوم لا سلاح لهم ولا قوة ولا لهم خبرة في امر الحرب'),
(22098, 'Judith', 68, 5, 28, 'فلكي يعلم احيور انه انما يخادعنا نصعد الان الى الجبال واذا اخذ جبابرتهم فحينئذ نجعله موردا للسيف ايضا معهم'),
(22099, 'Judith', 68, 5, 29, 'حتى تعلم كل امة ان نبوكد نصر هو اله الارض ولا اله غيره'),
(22100, 'Judith', 68, 6, 1, 'فلما فرغوا من كلامهم اشتد غضب اليفانا جدا وقال لاحيور'),
(22101, 'Judith', 68, 6, 2, 'بما انك تنبات لنا قائلا ان شعب اسرائيل يدافع عنه الهه فلكي اريك ان لا اله الا نبوكد نصر'),
(22102, 'Judith', 68, 6, 3, 'فانا اذا ضربناهم كلهم كرجل واحد فحينئذ انت ايضا تهلك بسيف الاشوريين وجميع اسرائيل يهلكون معك'),
(22103, 'Judith', 68, 6, 4, 'فتعلم عن خبرة ان نبوكد نصر هو رب الارض كلها وحينئذ سيف جيشي يخترق جنبيك فتسقط طعينا بين جرحى اسرائيل ولا يبقى فيك نسمة الا ريثما تستاصل معهم'),
(22104, 'Judith', 68, 6, 5, 'و ان كنت تخال ان نبوتك صادقة فلا يسقط وجهك وليفارقك الاصفرار الذي علا وجهك ان كنت تظن ان كلامي هذا لا يمكن ان يتم'),
(22105, 'Judith', 68, 6, 6, 'و لكي تعلم انك تختبر هذا معهم فها انك من هذه الساعة تنضم الى شعبهم واذا نالهم من سيفي عقوبة ما استحقوه فانك تكون معهم تحت طائلة الانتقام'),
(22106, 'Judith', 68, 6, 7, 'ثم امر اليفانا عبيده ان يقبضوا على احيور وياخذوه الى بيت فلوى ويسلموه الى ايدي بني اسرائيل'),
(22107, 'Judith', 68, 6, 8, 'فاخذه عبيد اليفانا وساروا في الصحراء ولما دنوا من الجبال خرج عليهم الرماة بالمقاليع'),
(22108, 'Judith', 68, 6, 9, 'فانحازوا الى جانب الجبل وربطوا احيور الى شجرة بيديه ورجليه وبعد ان ربطوه هكذا بالحبال تركوه ورجعوا الى سيدهم'),
(22109, 'Judith', 68, 6, 10, 'فنزل بنو اسرائيل من بيت فلوى واتوه فحلوه واخذوه الى بيت فلوى واقاموه في وسط الشعب وسالوه لم تركه الاشوريون مربوطا'),
(22110, 'Judith', 68, 6, 11, 'و كان في تلك عزيا بن ميخا من سبط شمعون وكرمي الذي هو عتنيئيل اميرين هناك'),
(22111, 'Judith', 68, 6, 12, 'فتكلم احيور بين ايدي الشيوخ وبحضرة الجميع بكل ما ذكره عن سؤال اليفانا وكيف هم قوم اليفانا ان يقتلوه بسبب هذا الكلام'),
(22112, 'Judith', 68, 6, 13, 'و كيف امرهم اليفانا وهو مغضب ان يدفعوه الى ايدي الاسرائيليين وفي قصده انه انه متى ظفر ببني اسرائيل يامر بقتل احيور بضروب مختلفة من العذاب لاجل انه قال ان اله السماء هو المدافع عنهم'),
(22113, 'Judith', 68, 6, 14, 'فلما قص عليهم احيور جميع ذلك خر الشعب كلهم على وجوههم ساجدين للرب ورفعوا صلواتهم الى الرب بالبكاء والعويل عامة بقلب واحد'),
(22114, 'Judith', 68, 6, 15, 'قائلين ايها الرب اله السماء والارض انظر الى عتوهم والتفت الى تذللنا ولا تغفل وجوه قديسيك واعلن انك لم تترك المتوكلين عليك وانك تذل المتوكلين على انفسهم والمفتخرين بقوتهم'),
(22115, 'Judith', 68, 6, 16, 'و بعد هذا البكاء وانقضاء صلاة الشعب ذلك اليوم كله عزوا احيور'),
(22116, 'Judith', 68, 6, 17, 'قائلين اله ابائنا الذي انذرت بقوته يمن عليك بهذه المنية ان تنظر انت هلاكهم'),
(22117, 'Judith', 68, 6, 18, 'و اذا اتى الرب الهنا عبيده هذا الخلاص فليكن هو الها لك فيما بيننا ان احببت ان تكون معنا باهلك كلهم'),
(22118, 'Judith', 68, 6, 19, 'و لما انتهت المشورة اخذوا عزيا الى بيته وصنع له عشاء عظيما'),
(22119, 'Judith', 68, 6, 20, 'و دعا الشيوخ كلهم فاكلوا بعد انقضاء الصوم'),
(22120, 'Judith', 68, 6, 21, 'ثم دعوا كل الشعب وباتوا في موضع الاجتماع يصلون ويستغيثون باله اسرائيل ذلك الليل كله'),
(22121, 'Judith', 68, 7, 1, 'و في اليوم الثاني امر اليفانا جميع عسكره ان يزحفوا على بيت فلوى'),
(22122, 'Judith', 68, 7, 2, 'و كان رجالة الحرب مئة وعشرين الفا والفرسان اثنين وعشرين الفا ما خلا الرجال المجلوين وجميع الفتيان الذين استصحبهم من الاقاليم والمدن'),
(22123, 'Judith', 68, 7, 3, 'فتاهب جميعهم لمقاتلة بني اسرائيل وجاءوا من جانب الجبل الى القمة التي تنظر الى دوتان من الموضع الذي يقال له بلما الى قليمون التي قبالة يزرعيل'),
(22124, 'Judith', 68, 7, 4, 'فلما راى بنو اسرائيل كثرتهم خروا على الارض وحثوا الرماد على رؤوسهم وصلوا بقلب واحد الى اله اسرائيل ليظهر رحمته على شعبه'),
(22125, 'Judith', 68, 7, 5, 'ثم اخذ كل رجل سلاحه واقاموا في الاماكن المفضية الى المضيق بين الجبال ولم يزالوا حارسين كل النهار والليل'),
(22126, 'Judith', 68, 7, 6, 'و لما كان اليفانا يطوف في الارض وجد العين التي كانت تجري الى داخل المدينة من ناحية الجنوب لها قناة خارج المدينة فامر ان يقطعوا القناة'),
(22127, 'Judith', 68, 7, 7, 'و كانت عيون اخر على قرب من السور كانوا يخرجون فيستقون منها خفية لكي يكسروا حدة عطشهم وان كانوا لا يرتوون'),
(22128, 'Judith', 68, 7, 8, 'فتقدم بنو عمون ومواب الى اليفانا وقالوا له ان بني اسرائيل لا يتكلون على الرمح والسهم ولكن الجبال تزرهم والتلال التي بين الهوى تحصنهم'),
(22129, 'Judith', 68, 7, 9, 'فالان حتى تظفر بهم بلا قتال اقم ارصادا على الينابيع لئلا يستقوا منها ماء فتقتلهم بغير سيف او يلجئهم ما يصيرون اليه من الضنك ان يسلموا مدينتهم التي يعدونها منيعة من اجل انها على الجبال'),
(22130, 'Judith', 68, 7, 10, 'فاعجب اليفانا وسائر عبيده بهذا الكلام فجعل ارصادا على العيون من اصحاب المئة على كل عين من جميع الجهات'),
(22131, 'Judith', 68, 7, 11, 'فاقاموا على هذه المحافظة عشرين يوما حتى جفت مياه ابار بيت فلوى وحياضها باسرها حتى لم يكن في داخل المدينة ما يرويهم يوما واحدا لان الماء كان يعطى للشعب كل يوم بمقدار'),
(22132, 'Judith', 68, 7, 12, 'حينئذ اجتمع على عزيا جميع الرجال والنساء والشبان والاطفال وكلهم بصوت واحد'),
(22133, 'Judith', 68, 7, 13, 'و قالوا يحكم الله بيننا وبينك فانك قد جنيت علينا شرورا اذ ابيت ان تخاطب الاشوريين بالمسالمة ولذلك باعنا الله الى ايديهم'),
(22134, 'Judith', 68, 7, 14, 'و الان فانه ليس لنا من نصير ولكنا نصرع امام عيونهم من قبل العطش والدمار العظيم'),
(22135, 'Judith', 68, 7, 15, 'فالان ادعوا جميع من في المدينة ولنستسلم باجمعنا الى اصحاب اليفانا من تلقاء انفسنا'),
(22136, 'Judith', 68, 7, 16, 'فخير لنا ان نبارك الرب ونحن احياء في الجلاء من ان نموت ونكون عارا عند جميع البشر بعد ان نكون عاينا نساءنا واطفالنا يموتون امامنا'),
(22137, 'Judith', 68, 7, 17, 'و نستحلفكم اليوم بالسماء والارض وباله ابائنا الذي ينتقم منا بحسب خطايانا ان تسلموا المدينة الى ايدي جيش اليفانا فيقضى اجلنا سريعا بحد السيف ولا يتمادى في اوار العطش'),
(22138, 'Judith', 68, 7, 18, 'فلما قالوا هذا حدث بكاء وعويل عظيم في الجماعة كلها وصرخوا الى الله بصوت واحد ساعات كثيرة قائلين'),
(22139, 'Judith', 68, 7, 19, 'قد خطئنا نحن واباؤنا وصنعنا الظلم والاثم'),
(22140, 'Judith', 68, 7, 20, 'ارحمنا لانك رحيم او فانتقم عن اثامنا بان تعاقبنا انت ولا تسلم المعترفين بك الى شعب لا يعرفك'),
(22141, 'Judith', 68, 7, 21, 'لئلا يقال في الامم اين الههم'),
(22142, 'Judith', 68, 7, 22, 'ثم انهم كلوا من الصراخ وخاروا من البكاء فسكتوا'),
(22143, 'Judith', 68, 7, 23, 'فقام عزيا ودموعه سائلة وقال لهم كونوا طيبي القلوب يا اخوتي ولننتظر رحمة من لدن الرب هذه الخمسة الايام'),
(22144, 'Judith', 68, 7, 24, 'فلعله يكف غضبه ويقيم مجدا لاسمه'),
(22145, 'Judith', 68, 7, 25, 'فاذا انقضت خمسة ايام ولم تاتنا معونة فعلنا ما تقولون'),
(22146, 'Judith', 68, 8, 1, 'و لما سمعت هذا الكلام يهوديت الارملة وهي بنت مراري بن ايدوس ابن يوسف بن عزيا بن الاي ابن يمنور بن جدعون بن رفائيم بن احيطوب بن ملكيا ابن عانان بن نتنيا بن شالتيئيل بن شمعون بن راوبين'),
(22147, 'Judith', 68, 8, 2, 'و كان بعلها منسى وقد مات في ايام حصاد الشعير'),
(22148, 'Judith', 68, 8, 3, 'لانه كان يحث رابطي الحزم في الحقل فصخد الحر راسه فمات في بيت فلوى مدينته وقبر هناك مع ابائه'),
(22149, 'Judith', 68, 8, 4, 'و كانت يهوديت قد بقيت ارملة منذ ثلاث سنين وستة اشهر'),
(22150, 'Judith', 68, 8, 5, 'و كانت قد هيات لها في اعلى بيتها غرفة سرية وكانت تقيم فيها مع جواريها وتغلقها'),
(22151, 'Judith', 68, 8, 6, 'و كان على حقويها مسح وكانت تصوم جميع ايام حياتها ما خلا السبوت ورؤوس الشهور واعياد ال اسرائيل'),
(22152, 'Judith', 68, 8, 7, 'و كانت جميلة المنظر جدا وقد ترك لها بعلها ثروة واسعة وحشما كثيرين واملاكا مملوءة باصورة البقر وقطعان الغنم'),
(22153, 'Judith', 68, 8, 8, 'و كانت لها شهرة بين جميع الناس من اجل انها كانت تتقي الرب جدا ولم يكن احد يقول عليها كلمة سوء'),
(22154, 'Judith', 68, 8, 9, 'فهذه لما سمعت ان عزيا وعد بان يسلم المدينة بعد خمسة ايام انفذت الى الشيخين كبري وكرمي'),
(22155, 'Judith', 68, 8, 10, 'فوافياها فقالت لهما ما هذا الامر الذي وافق عليه عزيا ان يسلم المدينة الى الاشوريين اذا لم تاتنا معونة الى خمسة ايام'),
(22156, 'Judith', 68, 8, 11, 'من انتم حتى تجربوا الرب'),
(22157, 'Judith', 68, 8, 12, 'ليس هذا بكلام يستعطف الرحمة ولكنه بالاحرى يهيج الغضب ويضرم السخط'),
(22158, 'Judith', 68, 8, 13, 'فانكم قد ضربتم اجلا لرحمة الرب وعينتم له يوما كما شئتم'),
(22159, 'Judith', 68, 8, 14, 'و لكن بما ان الرب طويل الاناة فلنندم على هذا ونلتمس غفرانه بالدموع المسكوبة'),
(22160, 'Judith', 68, 8, 15, 'انه ليس وعيد الله كوعيد الانسان ولا هو يستشيط حنقا كابن البشر'),
(22161, 'Judith', 68, 8, 16, 'لذلك فلنذلل له انفسنا ونعبده بروح متواضع'),
(22162, 'Judith', 68, 8, 17, 'و لنسال الرب باكين ان يؤتينا رحمته بحسب مشيئته لنفتخر بتواضعنا مثلما اضطربت قلوبنا بتكبرهم'),
(22163, 'Judith', 68, 8, 18, 'فانا لم نجر على خطايا ابائنا الذين تركوا الههم وعبدوا الهة غريبة'),
(22164, 'Judith', 68, 8, 19, 'فاسلموا من اجل ذلك الاثم الى السيف والنهب والخزي بين اعدائهم لكنا نحن لا نعرف الها غيره'),
(22165, 'Judith', 68, 8, 20, 'فنترجى بالتواضع تعزيته وهو ينتقم لدمنا عن اعنات اعدائنا لنا ويذل جميع الامم الواثبين علينا ويخزيهم الرب الهنا'),
(22166, 'Judith', 68, 8, 21, 'و الان يا اخوتي بما انكم انتم شيوخ في شعب الله وبكم نفوسهم منوطة فانهضوا قلوبهم بكلامكم حتى يذكروا ان اباءنا انما ورد عليهم البلاء ليمتحنوا هل يعبدون الههم بالحق'),
(22167, 'Judith', 68, 8, 22, 'فينبغي لهم ان يذكروا كيف امتحن ابونا ابراهيم وبعد ان جرب بشدائد كثيرة صار خليلا لله'),
(22168, 'Judith', 68, 8, 23, 'و هكذا اسحق وهكذا يعقوب وهكذا موسى وجميع الذين رضي الله منهم جازوا في شدائد كثيرة وبقوا على امانتهم'),
(22169, 'Judith', 68, 8, 24, 'فاما الذين لم يقبلوا البلايا بخشية الرب بل ابدوا جزعهم وعاد تذمرهم على الرب'),
(22170, 'Judith', 68, 8, 25, 'فاستاصلهم المستاصل وهلكوا بالحيات'),
(22171, 'Judith', 68, 8, 26, 'و اما نحن الان فلا نجزع لما نقاسيه'),
(22172, 'Judith', 68, 8, 27, 'بل لنحسب ان هذه العقوبات هي دون خطايانا ونعتقد ان ضربات الرب التي نؤدب بها كالعبيد انما هي للاصلاح لا للاهلاك'),
(22173, 'Judith', 68, 8, 28, 'فقال لها عزيا والشيوخ جميع مقالك حق ولا عيب في كلماتك'),
(22174, 'Judith', 68, 8, 29, 'فالان صلي عنا لانك امراة قديسة متقية لله'),
(22175, 'Judith', 68, 8, 30, 'فقالت لهم يهوديت كما انكم عرفتم ان ما تكلمت به هو من قبل الله'),
(22176, 'Judith', 68, 8, 31, 'فاعلموا عن خبرة ان ما عزمت عليه هو من قبل الله وصلوا حتى يؤيد الله مشورتي'),
(22177, 'Judith', 68, 8, 32, 'ففي هذه الليلة تقفون انتم على الباب وانا اخرج مع وصيفتي وصلوا ان ينظر الرب الى شعبه اسرائيل خمسة ايام كما قلتم'),
(22178, 'Judith', 68, 8, 33, 'و انا لا احب ان تفحصوا عن قصدي ومن الان حتى اعلمكم به لا تصنعوا شيئا غير الصلاة عني الى الرب الهنا'),
(22179, 'Judith', 68, 8, 34, 'فقال لها عزيا امير يهوذا اذهبي بسلام وليكن الرب معك في الانتقام من اعدائنا وانصرفوا راجعين'),
(22180, 'Judith', 68, 9, 1, 'و بينما هم ذاهبون دخلت يهوديت معبدها ولبست مسحا والقت رمادا على راسها وخرت امام الرب وصرخت الى الرب قائلة'),
(22181, 'Judith', 68, 9, 2, 'ايها الرب اله ابي شمعون الذي اعطاه سيفا لينتقم من الغرباء الذين بنجاستهم فضحوا وكشفوا عذراء للخزي'),
(22182, 'Judith', 68, 9, 3, 'فجعلت نساءهم غنيمة وبناتهم سبيا وكل سلبهم مقتسما بين عبيدك الذين غاروا غيرتك اتوسل اليك ايها الرب الهي ان تعينني انا الارملة'),
(22183, 'Judith', 68, 9, 4, 'فان لك الافعال الاولى وانت قدرت بعضها في عقب بعض وما اردته كان'),
(22184, 'Judith', 68, 9, 5, 'فان طرائقك جميعها مهياة وقد اقمت احكامك بعنايتك'),
(22185, 'Judith', 68, 9, 6, 'فانظر الان الى معسكر الاشوريين كما تنازلت فنظرت الى معسكر المصريين حين كانوا يسعون في اثر عبيدك بسلاحهم متوكلين على مراكبهم وفرسانهم وعلى كثرة رجال حربهم'),
(22186, 'Judith', 68, 9, 7, 'حينئذ نظرت الى معسكرهم فزعجتهم الظلمة'),
(22187, 'Judith', 68, 9, 8, 'التزقت اقدامهم بالعمق وغطتهم المياه'),
(22188, 'Judith', 68, 9, 9, 'يا رب فليكن مثلهم هؤلاء المتوكلون على كثرة عددهم ومراكبهم وحرابهم وتروسهم وسهامهم المفتخرون برماحهم'),
(22189, 'Judith', 68, 9, 10, 'و هم لا يعلمون انك انت الهنا الذي يمحق الحروب منذ البدء وان اسمك الرب'),
(22190, 'Judith', 68, 9, 11, 'فارفع ذراعك كما فعلت من البدء واحطم قوتهم بقوتك ولتسقط بغضبك قوة الذين يطمعون انفسهم في ابتذال اقداسك وتنجيس مسكن اسمك وهدم قرن مذبحك بسيفهم'),
(22191, 'Judith', 68, 9, 12, 'اجعل يا رب كبرياءه تقطع بنفس سيفه'),
(22192, 'Judith', 68, 9, 13, 'ليصد بفخ نظره الي واضربه بعذوبة الكلام الخارج من شفتي'),
(22193, 'Judith', 68, 9, 14, 'و هبني ثباتا في قلبي حتى ازدريه وقوة حتى اهلكه'),
(22194, 'Judith', 68, 9, 15, 'فيكون هذا ذكرا لاسمك اذا اهلكته يد امراة'),
(22195, 'Judith', 68, 9, 16, 'لانها ليست قوتك بالكثرة يا رب ولا مرضاتك بقدرة الخيل ومنذ البدء لا ترضى من المتكبرين بل يسرك دائما تضرع المتواضعين الودعاء'),
(22196, 'Judith', 68, 9, 17, 'يا اله السماوات خالق المياه ورب كل خليقة استجبني انا المسكينة المتضرعة والمتوكلة على رحمتك'),
(22197, 'Judith', 68, 9, 18, 'و اذكر يا رب ميثاقك واجعل الكلام في في وثبت مشورة قلبي ليثبت بيتك في قدسك'),
(22198, 'Judith', 68, 9, 19, 'فيعرف جميع الامم انك انت الاله وليس اخر سواك'),
(22199, 'Judith', 68, 10, 1, 'و كان لما فرغت من صراخها الى الرب انها قامت من المكان الذي كانت فيه منطرحة امام الرب'),
(22200, 'Judith', 68, 10, 2, 'و دعت وصيفتها ونزلت الى بيتها والقت عنها المسح ونزعت عنها ثياب ارمالها'),
(22201, 'Judith', 68, 10, 3, 'و استحمت وادهنت باطياب نفيسة وفرقت شعرها وجعلت تاجا على راسها ولبست ثياب فرحها واحتذت بحذاء ولبست الدمالج والسواسن والقرطة والخواتم وتزينت بكل زينتها'),
(22202, 'Judith', 68, 10, 4, 'و زادها الرب ايضا بهاء من اجل ان تزينها هذا لم يكن عن شهوة بل عن فضيلة ولذلك زاد الرب في جمالها حتى ظهرت في عيون الجميع ببهاء لا يمثل'),
(22203, 'Judith', 68, 10, 5, 'و حملت وصيفتها زق خمر واناء زيت ودقيقا وتينا يابسا وخبزا وجبنا وانطلقت'),
(22204, 'Judith', 68, 10, 6, 'فلما بلغتا باب المدينة وجدتا عزيا وشيوخ المدينة منتظرين'),
(22205, 'Judith', 68, 10, 7, 'فلما راوها اندهشوا وتعجبوا جدا من جمالها'),
(22206, 'Judith', 68, 10, 8, 'غير انهم لم يسالوها عن شيء بل تركوها تجوز قائلين اله ابائنا يمنحك نعمة ويؤيد كل مشورة قلبك بقوته حتى تفتخر بك اورشليم ويكون اسمك محصى في عداد القديسين والابرار'),
(22207, 'Judith', 68, 10, 9, 'فقال كل من هناك بصوت واحد امين امين'),
(22208, 'Judith', 68, 10, 10, 'فخرجت يهوديت من الباب هي وامتها وكانت تصلي الى الرب'),
(22209, 'Judith', 68, 10, 11, 'و كان انها لما نزلت من الجبل عند تبلج النهار لقيتها طلائع الاشوريين فامسكوها قائلين من اين جئت والى اين تذهبين'),
(22210, 'Judith', 68, 10, 12, 'فاجابت اني بنت للعبرانيين وقد هربت من بينهم لاني ايقنت انهم سيكونون غنيمة لكم لانهم استخفوا بكم وابوا ان يستسلموا لكم طوعا حتى يظفروا منكم برحمة'),
(22211, 'Judith', 68, 10, 13, 'فلاجل هذا فكرت في نفسي وقلت انطلق الى امام الامير اليفانا لاخبره باسرارهم واعلمه من اي مدخل يستطيع ان يظفر بهم ولا يقتل رجلا من جيشه'),
(22212, 'Judith', 68, 10, 14, 'فلما سمع اولئك الرجال كلامها وهم ينظرون الى وجهها اندهشت ابصارهم لشدة تعجبهم من حسنها'),
(22213, 'Judith', 68, 10, 15, 'فقالوا لها قد وقيت نفسك باتخاذك هذه المشورة ان تنزلي الى سيدنا'),
(22214, 'Judith', 68, 10, 16, 'فاعلمي انك اذا وقفت بحضرته يحسن اليك وتقعين من قلبه احسن موقع ثم اخذوها الى خيمة اليفانا واخبروه بها'),
(22215, 'Judith', 68, 10, 17, 'فلما دخلت عليه اصطيد اليفانا لساعته بعينيها'),
(22216, 'Judith', 68, 10, 18, 'فقال له اشراطه من يزدري بشعب العبرانيين ولهم نسوة مثل هذه جميلات السن اهلا لان نقاتلهم لاجلهن'),
(22217, 'Judith', 68, 10, 19, 'و اذ رات يهوديت اليفانا جالسا في الخيمة المنسوجة من ارجوان وذهب وزمرد وجواهر'),
(22218, 'Judith', 68, 10, 20, 'و نظرت الى وجهه خرت له ساجدة على الارض فانهضها عبيد اليفانا بامر سيدهم'),
(22219, 'Judith', 68, 11, 1, 'حينئذ قال لها اليفانا لتطب نفسك ولا يكن في قلبك روع لاني لم اضر قط برجل اثر الخضوع لنبوكد نصر الملك'),
(22220, 'Judith', 68, 11, 2, 'و اما شعبك فلو لم يزدروا بي لما اشرعت رمحي عليهم'),
(22221, 'Judith', 68, 11, 3, 'و الان فقولي لي لاي سبب فارقتهم واثرت المجيء الينا'),
(22222, 'Judith', 68, 11, 4, 'فقالت له يهوديت اسمع كلام امتك فانك اذا اتبعت قول امتك يتم الرب الامر لك'),
(22223, 'Judith', 68, 11, 5, 'ليحي نبوكد نصر ملك الارض ولتحي قوته التي فيك لتاديب جميع الانفس الغاوية لانه لا الناس فقط يخضعون له بك بل وحوش البر ايضا تنقاد له'),
(22224, 'Judith', 68, 11, 6, 'لان ذكاء عقلك قد شاع في جميع الامم واهل العصر كلهم يعلمون انك انت وحدك صالح وجبار في جميع مملكته وحسن سياستك مشهور في جميع الاقاليم'),
(22225, 'Judith', 68, 11, 7, 'و ليس بخاف ما تكلم به احيور ولم يجهل ما امرت ان يصيبه'),
(22226, 'Judith', 68, 11, 8, 'و من المحقق ان الهنا قد بلغ من غضبه من الخطايا انه ارسل انبياءه الى شعبه بانه سيسلمهم لاجل خطاياهم'),
(22227, 'Judith', 68, 11, 9, 'و لعلم بني اسرائيل بانهم قد اهانوا الههم قد حل رعبك عليهم'),
(22228, 'Judith', 68, 11, 10, 'و فضلا عن ذلك فان الجوع قد اخذ منهم وهم معدودون في الموتى من عوز الماء'),
(22229, 'Judith', 68, 11, 11, 'حتى عزموا ان يذبحوا بهائمهم ليشربوا دماءها'),
(22230, 'Judith', 68, 11, 12, 'و اقداس الرب الههم التي امر الله ان لا تلمس من الحنطة والخمر والزيت قد هموا ان ينفقوها وهم يريدون ان ياكلوا ما لا يحل حتى لمسه بالايدي فحيث انهم يفعلون هذا فقد ثبت انهم سيسلمون للهلاك'),
(22231, 'Judith', 68, 11, 13, 'و بما ان امتك قد علمت بهذا هربت من عندهم وقد بعثني الرب لاخبرك بهذا'),
(22232, 'Judith', 68, 11, 14, 'و انا امتك اعبد الله حتى الان عندك ايضا وامتك تخرج وتصلي الى الله'),
(22233, 'Judith', 68, 11, 15, 'فيقول لي متى يرد عليهم خطيئتهم فاجيء واخبرك بذلك حتى اخذك الى وسط اورشليم ويكون لك جميع شعب اسرائيل مثل الغنم التي لا راعيلها ولا ينبح عليك كلب'),
(22234, 'Judith', 68, 11, 16, 'و هذه كلها قد لقنتها من عناية الله'),
(22235, 'Judith', 68, 11, 17, 'و حيث ان الله قد غضب عليهم فانا مرسلة لاخبرك بهذه الامور'),
(22236, 'Judith', 68, 11, 18, 'فحسن هذا الكلام كله لدى اليفانا وعبيده وكانوا يتعجبون من حكمتها ويقولون بعضهم لبعض'),
(22237, 'Judith', 68, 11, 19, 'ليس مثل هذه المراة على الارض في المنظر والجمال والحكمة في الكلام'),
(22238, 'Judith', 68, 11, 20, 'فقال لها اليفانا قد احسن الله اليك اذ ارسلك امام الشعب لتسلميه انت الى ايدينا'),
(22239, 'Judith', 68, 11, 21, 'و بما ان وعدك حسن ان فعل الهك لي ذلك فهو يكون الها لي وانت تكونين عظيمة في بيت نبوكد نصر وينوه باسمك في كل الارض'),
(22240, 'Judith', 68, 12, 1, 'حينئذ امرهم ان يدخلوها موضع خزائنه وامر ان تمكث هناك واوصى بما يعطى لها من مائدته'),
(22241, 'Judith', 68, 12, 2, 'فاجابته يهوديت وقالت اني لا استطيع ان اكل مما امرت ان يعطى لي لئلا تكون علي خطيئة ولكني اكل مما اتيت به'),
(22242, 'Judith', 68, 12, 3, 'فقال لها اليفانا اذا فرغ هذا الذي اتيت به فما نصنع بك'),
(22243, 'Judith', 68, 12, 4, 'فقالت يهوديت تحيا نفسك يا سيدي ان امتك لا تنفق هذه جميعها حتى يصنع الله بيدي ما في خاطري فادخلها عبيده الخيمة التي امر بها'),
(22244, 'Judith', 68, 12, 5, 'فلما صارت في داخلها سالت ان يرخص لها ان تخرج في الليل قبل الصباح لتصلي وتتضرع الى الرب'),
(22245, 'Judith', 68, 12, 6, 'فاوصى اصحاب مخدعه ان ياذنوا لها كما تحب في ان تخرج وتدخل لتعبد الهها ثلاثة ايام'),
(22246, 'Judith', 68, 12, 7, 'فكانت تخرج ليلا الى وادي بيت فلوى وتغتسل في عين الماء'),
(22247, 'Judith', 68, 12, 8, 'و بعد صعودها كانت تتضرع الى اله اسرائيل ان يرشد طريقها لتخلص شعبها'),
(22248, 'Judith', 68, 12, 9, 'ثم تدخل وتقيم في خيمتها طاهرة الى ان تاخذ طعامها في المساء'),
(22249, 'Judith', 68, 12, 10, 'و كان في اليوم الرابع ان اليفانا صنع عشاء لعبيده وقال لبوغا خصيه انطلق الان واقنع تلك العبرانية ان ترضى بالاقامة معي طوعا'),
(22250, 'Judith', 68, 12, 11, 'فانه عار عند الاشوريين ان تسخر المراة من الرجل وتمضي عنه نقية'),
(22251, 'Judith', 68, 12, 12, 'فدخل حينئذ بوغا على يهوديت وقال لا تحتشمي ايتها الفتاة الصالحة ان تدخلي على سيدي وتكرمي امام وجهه وتاكلي معه وتشربي خمرا بفرح'),
(22252, 'Judith', 68, 12, 13, 'فاجابته يهوديت من انا حتى اخالف سيدي'),
(22253, 'Judith', 68, 12, 14, 'كل ما حسن وجاد في عينيه فانا اصنعه وكل ما يرضى به فهو عندي حسن جدا كل ايام حياتي'),
(22254, 'Judith', 68, 12, 15, 'ثم قامت وتزينت بملابسها ودخلت فوقفت امامه'),
(22255, 'Judith', 68, 12, 16, 'فاضطرب قلب اليفانا لانه كان قد اشتدت شهوته'),
(22256, 'Judith', 68, 12, 17, 'و قال لها اليفانا اشربي الان واتكئي بفرح فانك قد ظفرت امامي بحظوة'),
(22257, 'Judith', 68, 12, 18, 'فقالت يهوديت اشرب يا سيدي من اجل انها قد عظمت نفسي اليوم اكثر من جميع ايام حياتي'),
(22258, 'Judith', 68, 12, 19, 'ثم اخذت واكلت وشربت بحضرته مما كانت قد هياته لها جاريتها'),
(22259, 'Judith', 68, 12, 20, 'ففرح اليفانا بازائها وشرب من الخمر شيئا كثيرا جدا اكثر مما شرب في جميع حياته'),
(22260, 'Judith', 68, 13, 1, 'و لما امسوا اسرع عبيده الى منازلهم واغلق بوغا ابواب المخدع ومضى'),
(22261, 'Judith', 68, 13, 2, 'و كانوا جميعهم قد ثقلوا من الخمر'),
(22262, 'Judith', 68, 13, 3, 'و كانت يهوديت وحدها في المخدع'),
(22263, 'Judith', 68, 13, 4, 'و اليفانا مضطجع على السرير نائما لشدة سكره'),
(22264, 'Judith', 68, 13, 5, 'فامرت يهوديت جاريتها ان تقف خارجا امام المخدع وتترصد'),
(22265, 'Judith', 68, 13, 6, 'و وقفت يهوديت امام السرير وكانت تصلي بالدموع وتحرك شفتيها وهي ساكتة'),
(22266, 'Judith', 68, 13, 7, 'و تقول ايدني ايها الرب اله اسرائيل وانظر في هذه الساعة الى عمل يدي حتى تنهض اورشليم مدينتك كما وعدت وانا اتم ما عزمت عليه واثقة باني اقدر عليه بمعونتك'),
(22267, 'Judith', 68, 13, 8, 'و بعد ان قالت هذا دنت من العمود الذي في راس سريره فحلت خنجره المعلق به مربوطا'),
(22268, 'Judith', 68, 13, 9, 'و استلته ثم اخذت بشعر راسه وقالت ايدني ايها الرب الاله في هذه الساعة'),
(22269, 'Judith', 68, 13, 10, 'ثم ضربت مرتين على عنقه فقطعت راسه ونزعت خيمة سريره عن العمد ودحرجت جثته عن السرير');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(22270, 'Judith', 68, 13, 11, 'و بعد هنيهة خرجت وناولت وصيفتها راس اليفانا وامرتها ان تضعه في مزودها'),
(22271, 'Judith', 68, 13, 12, 'و خرجتا كلتاهما على عادتهما كانهما خارجتان للصلاة واجتازتا المعسكر ودارتا في الوادي حتى انتهتا الى باب المدينة'),
(22272, 'Judith', 68, 13, 13, 'فنادت يهوديت من بعد حراس السور افتحوا الابواب فان الله معنا وقد اجرى قوة في اسرائيل'),
(22273, 'Judith', 68, 13, 14, 'فكان انه لما سمع الرجال صوتها دعوا شيوخ المدينة'),
(22274, 'Judith', 68, 13, 15, 'و بادروا اليها جميعهم من اصغرهم الى اكبرهم لانه لم يكن في امالهم انها ترجع بعد'),
(22275, 'Judith', 68, 13, 16, 'ثم اوقدوا مصابيح واجتمعوا حولها باسرهم فصعدت الى اعلى موضع وامرت بالسكوت فلما سكتوا كلهم'),
(22276, 'Judith', 68, 13, 17, 'قالت يهوديت سبحوا الرب الهنا الذي لم يخذل المتوكلين عليه'),
(22277, 'Judith', 68, 13, 18, 'و بي انا امته اتم رحمته التي وعد بها ال اسرائيل وقتل بيدي عدو شعبه هذه الليلة'),
(22278, 'Judith', 68, 13, 19, 'ثم اخرجت راس اليفانا من المزود وارتهم اياه قائلة ها هوذا راس اليفانا رئيس جيش الاشوريين وهذه خيمة سريره التي كان مضطجعا فيها في سكره حيث ضربه الرب الهنا بيد امراة'),
(22279, 'Judith', 68, 13, 20, 'حي الرب انه حفظني ملاكه في مسيري من ههنا وفي اقامتي هناك وفي ايابي الى هنا ولم ياذن الرب ان تتدنس امته ولكن ارجعني اليكم بغير نجاسة خطيئة فرحة بغلبته وخلاصي وخلاصكم'),
(22280, 'Judith', 68, 13, 21, 'فاشكروا له كلكم لانه صالح لان رحمته الى الابد'),
(22281, 'Judith', 68, 13, 22, 'فسجدوا باجمعهم للرب وقالوا لها قد باركك الرب بقوته لانه بك افنى اعداءنا'),
(22282, 'Judith', 68, 13, 23, 'و قال لها عزيا رئيس شعب اسرائيل مباركة انت يا بنية من الرب الاله العلي فوق جميع نساء الارض'),
(22283, 'Judith', 68, 13, 24, 'تبارك الرب الذي خلق السماء والارض الذي سدد يدك لضرب راس قائد اعدائنا'),
(22284, 'Judith', 68, 13, 25, 'فانه عظم اليوم اسمك هكذا حتى لا يبرح مدحك من افواه الناس الذين يذكرون قوة الرب الى الابد الذين لاجلهم لم تشفقي على نفسك لاجل ضيقة وشدة جنسك بل رددت الهلاك امام الهنا'),
(22285, 'Judith', 68, 13, 26, 'فقال كل الشعب امين امين'),
(22286, 'Judith', 68, 13, 27, 'ثم دعوا احيور فجاء فقالت له يهوديت ان اله اسرائيل الذي شهدت له بانه ينتقم من اعدائه هو قطع في هذه الليلة بيدي راس جميع الكفار'),
(22287, 'Judith', 68, 13, 28, 'و حتى تعلم ان الامر هكذا فهوذا راس اليفانا الذي اهان اله اسرائيل باستخفاف كبريائه وتهددك بالموت اذ قال لك اذا اسرشعب اسرائيل امر ان يخترقوا جنبيك بالسيف'),
(22288, 'Judith', 68, 13, 29, 'فلما راى احيور راس اليفانا ارتاع خوفا وسقط بوجهه على الارض وهلعت نفسه'),
(22289, 'Judith', 68, 13, 30, 'و بعدما ثابت اليه روحه وانتعش خر قدامها ساجدا لها وقال'),
(22290, 'Judith', 68, 13, 31, 'مباركة انت من الهك في كل خيام يعقوب وفي كل امة يسمع فيها باسمك يعظم لاجلك اله اسرائيل'),
(22291, 'Judith', 68, 14, 1, 'و قالت يهوديت لجميع الشعب اسمعوا لي يا اخوتي علقوا هذا الراس على اسوارنا'),
(22292, 'Judith', 68, 14, 2, 'و متى طلعت الشمس فلياخذ كل واحد سلاحه واخرجوا بهجمة لا لتنحدروا الى اسفل ولكن كانكم تقصدون المهاجمة'),
(22293, 'Judith', 68, 14, 3, 'فعند ذلك يضطر الجواسيس ان يهربوا الى رئيسهم لينبهوه للقتال'),
(22294, 'Judith', 68, 14, 4, 'فاذا جرى قوادهم الى خيمة اليفانا يجدونه بلا راس متمرغا في دمه فيقع عليهم الذعر'),
(22295, 'Judith', 68, 14, 5, 'فاذا علمتم انهم هاربون فاسعوا على اعقابهم امنين فان الرب يسحقهم تحت ارجلكم'),
(22296, 'Judith', 68, 14, 6, 'و لما راى احيور القوة التي اجراها اله اسرائيل ترك سنة الامم وامن بالله وختن لحم قلفته وضم الى شعب اسرائيل هو وكل ذريته الى اليوم'),
(22297, 'Judith', 68, 14, 7, 'و عندما تبلج النهار علقوا راس اليفانا على الاسوار واخذ كل رجل سلاحه ثم خرجوا بجلبة عظيمة وصراخ'),
(22298, 'Judith', 68, 14, 8, 'فلما راى الجواسيس ذلك بادروا الى خيمة اليفانا'),
(22299, 'Judith', 68, 14, 9, 'فجاء من في الخيمة وضجوا امام مدخل المخدع لينبهوه واحدثوا ضوضاء حتى يستيقظ اليفانا بضوضائهم من غير ان يوقظه احد'),
(22300, 'Judith', 68, 14, 10, 'و لم يكن احد يجسر ان يقرع او يدخل باب مخدع قائد الاشوريين'),
(22301, 'Judith', 68, 14, 11, 'فلما جاء قواده ورؤساء الالوف وجميع عظماء جيش ملك اشور قالوا للحجاب'),
(22302, 'Judith', 68, 14, 12, 'ادخلوا وايقظوه لان الفئران قد خرجت من حجرتها واجترات على مهايجتنا للقتال'),
(22303, 'Judith', 68, 14, 13, 'فحينئذ دخل بوغا مخدعه فوقف عند السجف ثم صفق بكفيه لانه كان يظن انه نائم مع يهوديت'),
(22304, 'Judith', 68, 14, 14, 'فلما لم يشعر بحركة يسمعها دنا من السجف ورفعه فلما راى جثة اليفانا بلا راس وهي مضرجة بدمه مطروحة على الارض اعول بصوت عظيم ومزق ثيابه'),
(22305, 'Judith', 68, 14, 15, 'ثم دخل خيمة يهوديت فلم يجدها فخرج الى الشعب خارجا'),
(22306, 'Judith', 68, 14, 16, 'و قال امراة عبرانية بلبلت بيت الملك نبوكد نصر هوذا اليفانا مطروح على الارض بلا راس'),
(22307, 'Judith', 68, 14, 17, 'فلما سمع رؤساء جيش الاشوريين مزقوا ثيابهم جميعا ووقع عليهم من الخوف والرعب ما لا يطاق واضطربت قلوبهم جدا'),
(22308, 'Judith', 68, 14, 18, 'و حدث بين معسكرهم عويل لا نظير له'),
(22309, 'Judith', 68, 15, 1, 'و لما سمع كل الجيش ان اليفانا قد قطع راسه طارت عقولهم ومشورتهم ولم يعودوا يبالون الا بالخوف والرعب فاستنجدوا بالهزيمة'),
(22310, 'Judith', 68, 15, 2, 'و لم يكلم احد صاحبه بل طاطا كل منهم راسه وتركوا كل شيء وكانوا يسارعون لينجوا من العبرانيين الذين سمعوهم اتين عليهم بسلاحهم فهربوا في طرق الصحراء وشعاب التلال'),
(22311, 'Judith', 68, 15, 3, 'فلما راهم بنو اسرائيل هاربين سعوا على اعقابهم ونزلوا وهم يهتفون بالابواق مجلبين وراءهم'),
(22312, 'Judith', 68, 15, 4, 'و كان الاشوريون متبددين وهم مندفعون في هزيمتهم وبنو اسرائيل صبة واحدة في اثارهم فاهلكوا كل من ادركوه'),
(22313, 'Judith', 68, 15, 5, 'و ارسل عزيا رسلا الى جميع مدن ونواحي اسرائيل'),
(22314, 'Judith', 68, 15, 6, 'فكل بلدة ومدينة ارسلت في اثرهم شبانا منتخبين مدججين في السلاح فطردوهم بحد السيف الى ان بلغوا الى اخر تخمهم'),
(22315, 'Judith', 68, 15, 7, 'و دخل بقية سكان بيت فلوى محلة اشور فاخذوا كل ما تركه الاشوريون عندما هربوا وكان شيئا كثيرا'),
(22316, 'Judith', 68, 15, 8, 'و الذين رجعوا الى بيت فلوى منصورين جاءوا بجميع اموالهم حتى كانت المواشي والبهائم وجميع اثاثهم بلا عدد فاثروا جميعهم من صغيرهم الى كبيرهم من غنيمتهم'),
(22317, 'Judith', 68, 15, 9, 'و اتى يوياقيم الكاهن العظيم من اورشليم الى بيت فلوى مع جميع شيوخه ليرى يهوديت'),
(22318, 'Judith', 68, 15, 10, 'فلما خرجت اليه باركوها كلهم بصوت واحد قائلين انت مجد اورشليم وفرح اسرائيل وفخر شعبنا'),
(22319, 'Judith', 68, 15, 11, 'فانك قد صنعت بباس وثبت قلبك فاحببت العفاف ولم تعرفي رجلا بعد رجلك فلهذا ايدتك يد الرب فكوني مباركة الى الابد'),
(22320, 'Judith', 68, 15, 12, 'فقال جميع الشعب امين امين'),
(22321, 'Judith', 68, 15, 13, 'و لم يكد شعب اسرائيل في ثلاثين يوما يجمعون غنيمة الاشوريين'),
(22322, 'Judith', 68, 15, 14, 'و كل ما تبين انه كان من خواص اليفانا دفعوه الى يهوديت من ذهب وفضة وثياب وجواهر وامتعة كل هذه اعطاها لها الشعب'),
(22323, 'Judith', 68, 15, 15, 'و كان جميع الشعب يفرحون مع النساء والعذارى والشبان بالاعواد والقياثير'),
(22324, 'Judith', 68, 16, 1, 'حينئذ انشدت يهوديت هذا النشيد للرب فقالت'),
(22325, 'Judith', 68, 16, 2, 'سبحوا الرب بالدفوف رنموا للرب على الصنوج انشدوا له انشادا جديدا عظموه وادعوا باسمه'),
(22326, 'Judith', 68, 16, 3, 'الرب يمحق الحروب الرب اسمه'),
(22327, 'Judith', 68, 16, 4, 'جعل معسكره في وسط شعبه لينقذنا من ايدي جميع اعدائنا'),
(22328, 'Judith', 68, 16, 5, 'اتى اشور من الجبال الشمالية اتى في كثرة قوته فسدت كثرته الاودية وخيوله غطت الوهاد'),
(22329, 'Judith', 68, 16, 6, 'قال انه سيحرق تخومي ويقتل فتياني بالسيف ويجعل اطفالي غنيمة وابكاري سبيا'),
(22330, 'Judith', 68, 16, 7, 'الرب القدير ضربه واسلمه الى يد امراة فطعنته'),
(22331, 'Judith', 68, 16, 8, 'ان جبارهم لم يسقط بايدي الشبان ولم يبطش به بنو طيطان ولا جبابرة طوال تعرضوا له بل يهوديت ابنة مراري بجمال وجهها اهلكته'),
(22332, 'Judith', 68, 16, 9, 'نزعت ثياب ارمالها وتردت بثياب فرحها لابتهاج بني اسرائيل'),
(22333, 'Judith', 68, 16, 10, 'دهنت وجهها بالطيب وضمت ضفائرها بالتاج ولبست حللها الفاخرة لتفتنه'),
(22334, 'Judith', 68, 16, 11, 'بهاء حذائها خطف ابصاره وجمالها اسر نفسه فقطعت بالخنجر عنقه'),
(22335, 'Judith', 68, 16, 12, 'ارتاعت فارس من ثباتها والماديون من جراتها'),
(22336, 'Judith', 68, 16, 13, 'حينئذ اعولت محلة الاشوريين عندما ظهر متواضعي ملتهبين من العطش'),
(22337, 'Judith', 68, 16, 14, 'بنو الجواري اثخنوهم وقتلوهم كانهم صبية منهزمون فهلكوا في القتال بين يدي الرب الهي'),
(22338, 'Judith', 68, 16, 15, 'فلنسبح الرب تسبيحا ونرنم نشيدا جديدا لالهنا'),
(22339, 'Judith', 68, 16, 16, 'ايها الرب ادوناي انك عظيم شهير بجبروتك ولا يقوى عليك احد'),
(22340, 'Judith', 68, 16, 17, 'اياك فلتعبد خليقتك باسرها لانك انت قلت فكانوا ارسلت روحك فخلقوا وليس من يقاوم كلمتك'),
(22341, 'Judith', 68, 16, 18, 'تهتز الجبال من اساسها مع المياه والصخور كالشمع تذوب امام وجهك'),
(22342, 'Judith', 68, 16, 19, 'و الذين يتقونك يكونون اعزة عندك في كل شيء'),
(22343, 'Judith', 68, 16, 20, 'الويل للامة القائمة على شعبي الرب القدير ينتقم منهم وفي يوم الدينونة يفتقدهم'),
(22344, 'Judith', 68, 16, 21, 'يجعل لحومهم للنار والدود لكي يحترقوا ويتالموا الى الابد'),
(22345, 'Judith', 68, 16, 22, 'و كان بعد هذا ان جميع الشعب بعد غلبتهم جاءوا الى اورشليم ليسجدوا للرب ولما تطهروا قدموا جميعهم محرقاتهم ونذورهم واوعادهم'),
(22346, 'Judith', 68, 16, 23, 'و يهوديت ايضا قدمت جميع ادوات حرب اليفانا التي اعطاها لها الشعب والخيمة التي اخذتها من سريره ابسال نسيان'),
(22347, 'Judith', 68, 16, 24, 'و كان الشعب مسرورين بمشاهدة المقدسات وعيدوا لفرح هذه الغلبة مع يهوديت ثلاثة اشهر'),
(22348, 'Judith', 68, 16, 25, 'و بعد تلك الايام رجع كل واحد الى بيته وعظمت يهوديت في بيت فلوى جدا وكانت اجل من في جميع ارض اسرائيل'),
(22349, 'Judith', 68, 16, 26, 'و كان فيها العفاف مقرونا بالشجاعة ولم تعد تعرف رجلا كل ايام حياتها منذ وفاة منسى بعلها'),
(22350, 'Judith', 68, 16, 27, 'و كانت في الاعياد تظهر بمجد عظيم'),
(22351, 'Judith', 68, 16, 28, 'و بقيت في بيت بعلها مئة وخمس سنين واعتقت وصيفتها وتوفيت ودفنت مع بعلها في بيت فلوى'),
(22352, 'Judith', 68, 16, 29, 'فناح عليها جميع الشعب سبعة ايام'),
(22353, 'Judith', 68, 16, 30, 'و لم يكن مدة حياتها كلها من يقلق اسرائيل ولا بعد موتها سنين كثيرة'),
(22354, 'Judith', 68, 16, 31, 'و احصي يوم هذه الغلبة عند العبرانيين في عداد الايام المقدسة واليهود يعيدونه منذ ذلك الوقت الى يومنا هذا'),
(22355, 'Lamentations', 25, 3, 47, ' صار علينا خوف ورعب ، هلاك وسحق '),
(22356, 'Lamentations', 25, 3, 48, ' سكبت عيناي ينابيع ماء على سحق بنت شعبي '),
(22357, 'Lamentations', 25, 3, 49, ' عيني تسكب ولا تكف بلا انقطاع '),
(22358, 'Lamentations', 25, 3, 50, ' حتى يشرف وينظر الرب من السماء '),
(22359, 'Lamentations', 25, 3, 51, ' عيني تؤثر في نفسي لأجل كل بنات مدينتي '),
(22360, 'Lamentations', 25, 3, 52, ' قد اصطادتني أعدائي كعصفور بلا سبب '),
(22361, 'Lamentations', 25, 3, 53, ' قرضوا في الجب حياتي وألقوا علي حجارة '),
(22362, 'Lamentations', 25, 3, 54, ' طفت المياه فوق رأسي . قلت : قد قرضت '),
(22363, 'Lamentations', 25, 3, 55, ' دعوت باسمك يارب من الجب الأسفل '),
(22364, 'Lamentations', 25, 3, 56, ' لصوتي سمعت : لا تستر أذنك عن زفرتي ، عن صياحي '),
(22365, 'Lamentations', 25, 3, 57, ' دنوت يوم دعوتك . قلت : لا تخف '),
(22366, 'Lamentations', 25, 3, 58, ' خاصمت يا سيد خصومات نفسي . فككت حياتي '),
(22367, 'Lamentations', 25, 3, 59, ' رأيت يارب ظلمي . أقم دعواي '),
(22368, 'Lamentations', 25, 3, 60, ' رأيت كل نقمتهم ، كل أفكارهم علي '),
(22369, 'Lamentations', 25, 3, 61, ' سمعت تعييرهم يارب ، كل أفكارهم علي '),
(22370, 'Lamentations', 25, 3, 62, ' كلام مقاومي ومؤامرتهم علي اليوم كله '),
(22371, 'Lamentations', 25, 3, 63, ' انظر إلى جلوسهم ووقوفهم ، أنا أغنيتهم '),
(22372, 'Lamentations', 25, 3, 64, ' رد لهم جزاء يارب حسب عمل أياديهم '),
(22373, 'Lamentations', 25, 3, 65, ' أعطهم غشاوة قلب ، لعنتك لهم '),
(22374, 'Lamentations', 25, 3, 66, ' اتبع بالغضب وأهلكهم من تحت سماوات الرب '),
(22375, 'Lamentations', 25, 4, 1, ' كيف اكدر الذهب ، تغير الإبريز الجيد انهالت حجارة القدس في رأس كل شارع '),
(22376, 'Lamentations', 25, 4, 2, ' بنو صهيون الكرماء الموزونون بالذهب النقي ، كيف حسبوا أباريق خزف عمل يدي فخاري '),
(22377, 'Lamentations', 25, 4, 3, ' بنات آوى أيضا أخرجت أطباءها ، أرضعت أجراءها . أما بنت شعبي فجافية كالنعام في البرية '),
(22378, 'Lamentations', 25, 4, 4, ' لصق لسان الراضع بحنكه من العطش . الأطفال يسألون خبزا وليس من يكسره لهم '),
(22379, 'Lamentations', 25, 4, 5, ' الذين كانوا يأكلون المآكل الفاخرة قد هلكوا في الشوارع . الذين كانوا يتربون على القرمز احتضنوا المزابل '),
(22380, 'Lamentations', 25, 4, 6, ' وقد صار عقاب بنت شعبي أعظم من قصاص خطية سدوم التي انقلبت كأنه في لحظة ، ولم تلق عليها أياد '),
(22381, 'Lamentations', 25, 4, 7, ' كان نذرها أنقى من الثلج وأكثر بياضا من اللبن ، وأجسامهم أشد حمرة من المرجان . جرزهم كالياقوت الأزرق '),
(22382, 'Lamentations', 25, 4, 8, ' صارت صورتهم أشد ظلاما من السواد . لم يعرفوا في الشوارع . لصق جلدهم بعظمهم . صار يابسا كالخشب '),
(22383, 'Lamentations', 25, 4, 9, ' كانت قتلى السيف خيرا من قتلى الجوع . لأن هؤلاء يذوبون مطعونين لعدم أثمار الحقل '),
(22384, 'Lamentations', 25, 4, 10, ' أيادي النساء الحنائن طبخت أولادهن . صاروا طعاما لهن في سحق بنت شعبي '),
(22385, 'Lamentations', 25, 4, 11, ' أتم الرب غيظه . سكب حمو غضبه وأشعل نارا في صهيون فأكلت أسسها '),
(22386, 'Lamentations', 25, 4, 12, ' لم تصدق ملوك الأرض وكل سكان المسكونة أن العدو والمبغض يدخلان أبواب أورشليم '),
(22387, 'Lamentations', 25, 4, 13, ' من أجل خطايا أنبيائها ، وآثام كهنتها السافكين في وسطها دم الصديقين '),
(22388, 'Lamentations', 25, 4, 14, ' تاهوا كعمي في الشوارع ، وتلطخوا بالدم حتى لم يستطع أحد أن يمس ملابسهم '),
(22389, 'Lamentations', 25, 4, 15, ' حيدوا نجس ينادون إليهم . حيدوا حيدوا لا تمسوا . إذ هربوا تاهوا أيضا . قالوا بين الأمم : إنهم لا يعودون يسكنون '),
(22390, 'Lamentations', 25, 4, 16, ' وجه الرب قسمهم . لا يعود ينظر إليهم . لم يرفعوا وجوه الكهنة ، ولم يترأفوا على الشيوخ '),
(22391, 'Lamentations', 25, 4, 17, ' أما نحن فقد كلت أعيننا من النظر إلى عوننا الباطل . في برجنا انتظرنا أمة لا تخلص '),
(22392, 'Lamentations', 25, 4, 18, ' نصبوا فخاخا لخطواتنا حتى لا نمشي في ساحاتنا . قربت نهايتنا . كملت أيامنا لأن نهايتنا قد أتت '),
(22393, 'Lamentations', 25, 4, 19, ' صار طاردونا أخف من نسور السماء . على الجبال جدوا في أثرنا . في البرية كمنوا لنا '),
(22394, 'Lamentations', 25, 4, 20, ' نفس أنوفنا ، مسيح الرب ، أخذ في حفرهم . الذي قلنا عنه : في ظله نعيش بين الأمم '),
(22395, 'Lamentations', 25, 4, 21, ' اطربي وافرحي يا بنت أدوم ، يا ساكنة عوص . عليك أيضا تمر الكأس . تسكرين وتتعرين '),
(22396, 'Lamentations', 25, 4, 22, ' قد تم إثمك يا بنت صهيون . لا يعود يسبيك . سيعاقب إثمك يا بنت أدوم ويعلن خطاياك '),
(22397, 'Lamentations', 25, 5, 1, ' اذكر يارب ماذا صار لنا . أشرف وانظر إلى عارنا '),
(22398, 'Lamentations', 25, 5, 2, ' قد صار ميراثنا للغرباء . بيوتنا للأجانب '),
(22399, 'Lamentations', 25, 5, 3, ' صرنا أيتاما بلا أب . أمهاتنا كأرامل '),
(22400, 'Lamentations', 25, 5, 4, ' شربنا ماءنا بالفضة . حطبنا بالثمن يأتي '),
(22401, 'Lamentations', 25, 5, 5, ' على أعناقنا نضطهد . نتعب ولا راحة لنا '),
(22402, 'Lamentations', 25, 5, 6, ' أعطينا اليد للمصريين والأشوريين لنشبع خبزا '),
(22403, 'Lamentations', 25, 5, 7, ' آباؤنا أخطأوا وليسوا بموجودين ، ونحن نحمل آثامهم '),
(22404, 'Lamentations', 25, 5, 8, ' عبيد حكموا علينا . ليس من يخلص من أيديهم '),
(22405, 'Lamentations', 25, 5, 9, ' بأنفسنا نأتي بخبزنا من جرى سيف البرية '),
(22406, 'Lamentations', 25, 5, 10, ' جلودنا اسودت كتنور من جرى نيران الجوع '),
(22407, 'Lamentations', 25, 5, 11, ' أذلوا النساء في صهيون ، العذارى في مدن يهوذا '),
(22408, 'Lamentations', 25, 5, 12, ' الرؤساء بأيديهم يعلقون ، ولم تعتبر وجوه الشيوخ '),
(22409, 'Lamentations', 25, 5, 13, ' أخذوا الشبان للطحن ، والصبيان عثروا تحت الحطب '),
(22410, 'Lamentations', 25, 5, 14, ' كفت الشيوخ عن الباب ، والشبان عن غنائهم '),
(22411, 'Lamentations', 25, 5, 15, ' مضى فرح قلبنا . صار رقصنا نوحا '),
(22412, 'Lamentations', 25, 5, 16, ' سقط إكليل رأسنا . ويل لنا لأننا قد أخطأنا '),
(22413, 'Lamentations', 25, 5, 17, ' من أجل هذا حزن قلبنا . من أجل هذه أظلمت عيوننا '),
(22414, 'Lamentations', 25, 5, 18, ' من أجل جبل صهيون الخرب . الثعالب ماشية فيه '),
(22415, 'Lamentations', 25, 5, 19, ' أنت يارب إلى الأبد تجلس . كرسيك إلى دور فدور '),
(22416, 'Lamentations', 25, 5, 20, ' لماذا تنسانا إلى الأبد وتتركنا طول الأيام '),
(22417, 'Lamentations', 25, 5, 21, ' ارددنا يارب إليك فنرتد . جدد أيامنا كالقديم '),
(22418, 'Lamentations', 25, 5, 22, ' هل كل الرفض رفضتنا ؟ هل غضبت علينا جدا '),
(22419, 'Lamentations', 25, 1, 1, ' كيف جلست وحدها المدينة الكثيرة الشعب كيف صارت كأرملة العظيمة في الأمم . السيدة في البلدان صارت تحت الجزية '),
(22420, 'Lamentations', 25, 1, 2, ' تبكي في الليل بكاء ، ودموعها على خديها . ليس لها معز من كل محبيها . كل أصحابها غدروا بها ، صاروا لها أعداء '),
(22421, 'Lamentations', 25, 1, 3, ' قد سبيت يهوذا من المذلة ومن كثرة العبودية . هي تسكن بين الأمم . لا تجد راحة . قد أدركها كل طارديها بين الضيقات '),
(22422, 'Lamentations', 25, 1, 4, ' طرق صهيون نائحة لعدم الآتين إلى العيد . كل أبوابها خربة . كهنتها يتنهدون . عذاراها مذللة وهي في مرارة '),
(22423, 'Lamentations', 25, 1, 5, ' صار مضايقوها رأسا . نجح أعداؤها لأن الرب قد أذلها لأجل كثرة ذنوبها . ذهب أولادها إلى السبي قدام العدو '),
(22424, 'Lamentations', 25, 1, 6, ' وقد خرج من بنت صهيون كل بهائها . صارت رؤساؤها كأيائل لا تجد مرعى ، فيسيرون بلا قوة أمام الطارد '),
(22425, 'Lamentations', 25, 1, 7, ' قد ذكرت أورشليم في أيام مذلتها وتطوحها كل مشتهياتها التي كانت في أيام القدم . عند سقوط شعبها بيد العدو وليس من يساعدها . رأتها الأعداء . ضحكوا على هلاكها '),
(22426, 'Lamentations', 25, 1, 8, ' قد أخطأت أورشليم خطية ، من أجل ذلك صارت رجسة . كل مكرميها يحتقرونها لأنهم رأوا عورتها ، وهي أيضا تتنهد وترجع إلى الوراء '),
(22427, 'Lamentations', 25, 1, 9, ' نجاستها في أذيالها . لم تذكر آخرتها وقد انحطت انحطاطا عجيبا . ليس لها معز . انظر يارب إلى مذلتي لأن العدو قد تعظم '),
(22428, 'Lamentations', 25, 1, 10, ' بسط العدو يده على كل مشتهياتها ، فإنها رأت الأمم دخلوا مقدسها ، الذين أمرت أن لا يدخلوا في جماعتك '),
(22429, 'Lamentations', 25, 1, 11, ' كل شعبها يتنهدون ، يطلبون خبزا . دفعوا مشتهياتهم للأكل لأجل رد النفس . انظر يارب وتطلع لأني قد صرت محتقرة '),
(22430, 'Lamentations', 25, 1, 12, ' أما إليكم يا جميع عابري الطريق ؟ تطلعوا وانظروا إن كان حزن مثل حزني الذي صنع بي ، الذي أذلني به الرب يوم حمو غضبه '),
(22431, 'Lamentations', 25, 1, 13, ' من العلاء أرسل نارا إلى عظامي فسرت فيها . بسط شبكة لرجلي . ردني إلى الوراء . جعلني خربة . اليوم كله مغمومة '),
(22432, 'Lamentations', 25, 1, 14, ' شد نير ذنوبي بيده ، ضفرت ، صعدت على عنقي . نزع قوتي . دفعني السيد إلى أيد لا أستطيع القيام منها '),
(22433, 'Lamentations', 25, 1, 15, ' رذل السيد كل مقتدري في وسطي . دعا علي جماعة لحطم شباني . داس السيد العذراء بنت يهوذا معصرة '),
(22434, 'Lamentations', 25, 1, 16, ' على هذه أنا باكية . عيني ، عيني تسكب مياها لأنه قد ابتعد عني المعزي ، راد نفسي . صار بني هالكين لأنه قد تجبر العدو '),
(22435, 'Lamentations', 25, 1, 17, ' بسطت صهيون يديها . لا معزي لها . أمر الرب على يعقوب أن يكون مضايقوه حواليه . صارت أورشليم نجسة بينهم '),
(22436, 'Lamentations', 25, 1, 18, ' بار هو الرب لأني قد عصيت أمره . اسمعوا يا جميع الشعوب وانظروا إلى حزني . عذاراي وشباني ذهبوا إلى السبي '),
(22437, 'Lamentations', 25, 1, 19, ' ناديت محبي . هم خدعوني . كهنتي وشيوخي في المدينة ماتوا ، إذ طلبوا لذواتهم طعاما ليردوا أنفسهم '),
(22438, 'Lamentations', 25, 1, 20, ' انظر يارب ، فإني في ضيق أحشائي غلت . ارتد قلبي في باطني لأني قد عصيت متمردة . في الخارج يثكل السيف ، وفي البيت مثل الموت '),
(22439, 'Lamentations', 25, 1, 21, ' سمعوا أني تنهدت . لا معزي لي . كل أعدائي سمعوا ببليتي . فرحوا لأنك فعلت . تأتي باليوم الذي ناديت به فيصيرون مثلي '),
(22440, 'Lamentations', 25, 1, 22, ' ليأت كل شرهم أمامك . وافعل بهم كما فعلت بي من أجل كل ذنوبي ، لأن تنهداتي كثيرة وقلبي مغشي عليه '),
(22441, 'Lamentations', 25, 2, 1, ' كيف غطى السيد بغضبه ابنة صهيون بالظلام ألقى من السماء إلى الأرض فخر إسرائيل ، ولم يذكر موطئ قدميه في يوم غضبه '),
(22442, 'Lamentations', 25, 2, 2, ' ابتلع السيد ولم يشفق كل مساكن يعقوب . نقض بسخطه حصون بنت يهوذا . أوصلها إلى الأرض . نجس المملكة ورؤساءها '),
(22443, 'Lamentations', 25, 2, 3, ' عضب بحمو غضبه كل قرن لإسرائيل . رد إلى الوراء يمينه أمام العدو ، واشتعل في يعقوب مثل نار ملتهبة تأكل ما حواليها '),
(22444, 'Lamentations', 25, 2, 4, ' مد قوسه كعدو . نصب يمينه كمبغض وقتل كل مشتهيات العين في خباء بنت صهيون . سكب كنار غيظه '),
(22445, 'Lamentations', 25, 2, 5, ' صار السيد كعدو . ابتلع إسرائيل . ابتلع كل قصوره . أهلك حصونه ، وأكثر في بنت يهوذا النوح والحزن '),
(22446, 'Lamentations', 25, 2, 6, ' ونزع كما من جنة مظلته . أهلك مجتمعه . أنسى الرب في صهيون الموسم والسبت ، ورذل بسخط غضبه الملك والكاهن '),
(22447, 'Lamentations', 25, 2, 7, ' كره السيد مذبحه . رذل مقدسه . حصر في يد العدو أسوار قصورها . أطلقوا الصوت في بيت الرب كما في يوم الموسم '),
(22448, 'Lamentations', 25, 2, 8, ' قصد الرب أن يهلك سور بنت صهيون . مد المطمار . لم يردد يده عن الإهلاك ، وجعل المترسة والسور ينوحان . قد حزنا معا '),
(22449, 'Lamentations', 25, 2, 9, ' تاخت في الأرض أبوابها . أهلك وحطم عوارضها . ملكها ورؤساؤها بين الأمم . لا شريعة . أنبياؤها أيضا لا يجدون رؤيا من قبل الرب '),
(22450, 'Lamentations', 25, 2, 10, ' شيوخ بنت صهيون يجلسون على الأرض ساكتين . يرفعون التراب على رؤوسهم . يتنطقون بالمسوح . تحني عذارى أورشليم رؤوسهن إلى الأرض '),
(22451, 'Lamentations', 25, 2, 11, ' كلت من الدموع عيناي . غلت أحشائي . انسكبت على الأرض كبدي على سحق بنت شعبي ، لأجل غشيان الأطفال والرضع في ساحات القرية '),
(22452, 'Lamentations', 25, 2, 12, ' يقولون لأمهاتهم : أين الحنطة والخمر ؟  ، إذ يغشى عليهم كجريح في ساحات المدينة ، إذ تسكب نفسهم في أحضان أمهاتهم '),
(22453, 'Lamentations', 25, 2, 13, ' بماذا أنذرك ؟ بماذا أحذرك ؟ بماذا أشبهك يا ابنة أورشليم ؟ بماذا أقايسك فأعزيك أيتها العذراء بنت صهيون ؟ لأن سحقك عظيم كالبحر . من يشفيك '),
(22454, 'Lamentations', 25, 2, 14, ' أنبياؤك رأوا لك كذبا وباطلا ، ولم يعلنوا إثمك ليردوا سبيك ، بل رأوا لك وحيا كاذبا وطوائح '),
(22455, 'Lamentations', 25, 2, 15, ' يصفق عليك بالأيادي كل عابري الطريق . يصفرون وينغضون رؤوسهم على بنت أورشليم قائلين : أهذه هي المدينة التي يقولون إنها كمال الجمال ، بهجة كل الأرض '),
(22456, 'Lamentations', 25, 2, 16, ' يفتح عليك أفواههم كل أعدائك . يصفرون ويحرقون الأسنان . يقولون : قد أهلكناها . حقا إن هذا اليوم الذي رجوناه . قد وجدناه قد رأيناه '),
(22457, 'Lamentations', 25, 2, 17, ' فعل الرب ما قصد . تمم قوله الذي أوعد به منذ أيام القدم . قد هدم ولم يشفق وأشمت بك العدو . نصب قرن أعدائك '),
(22458, 'Lamentations', 25, 2, 18, ' صرخ قلبهم إلى السيد . يا سور بنت صهيون اسكبي الدمع كنهر نهارا وليلا . لا تعطي ذاتك راحة . لا تكف حدقة عينك '),
(22459, 'Lamentations', 25, 2, 19, ' قومي اهتفي في الليل في أول الهزع . اسكبي كمياه قلبك قبالة وجه السيد . ارفعي إليه يديك لأجل نفس أطفالك المغشي عليهم من الجوع في رأس كل شارع '),
(22460, 'Lamentations', 25, 2, 20, ' انظر يارب وتطلع بمن فعلت هكذا ؟ أتأكل النساء ثمرهن ، أطفال الحضانة ؟ أيقتل في مقدس السيد الكاهن والنبي '),
(22461, 'Lamentations', 25, 2, 21, ' اضطجعت على الأرض في الشوارع الصبيان والشيوخ . عذاراي وشباني سقطوا بالسيف . قد قتلت في يوم غضبك . ذبحت ولم تشفق '),
(22462, 'Lamentations', 25, 2, 22, ' قد دعوت كما في يوم موسم مخاوفي حوالي ، فلم يكن في يوم غضب الرب ناج ولا باق . الذين حضنتهم وربيتهم أفناهم عدوي '),
(22463, 'Lamentations', 25, 3, 1, ' أنا هو الرجل الذي رأى مذلة بقضيب سخطه '),
(22464, 'Lamentations', 25, 3, 2, ' قادني وسيرني في الظلام ولا نور '),
(22465, 'Lamentations', 25, 3, 3, ' حقا إنه يعود ويرد علي يده اليوم كله '),
(22466, 'Lamentations', 25, 3, 4, ' أبلى لحمي وجلدي . كسر عظامي '),
(22467, 'Lamentations', 25, 3, 5, ' بنى علي وأحاطني بعلقم ومشقة '),
(22468, 'Lamentations', 25, 3, 6, ' أسكنني في ظلمات كموتى القدم '),
(22469, 'Lamentations', 25, 3, 7, ' سيج علي فلا أستطيع الخروج . ثقل سلسلتي '),
(22470, 'Lamentations', 25, 3, 8, ' أيضا حين أصرخ وأستغيث يصد صلاتي '),
(22471, 'Lamentations', 25, 3, 9, ' سيج طرقي بحجارة منحوتة . قلب سبلي '),
(22472, 'Lamentations', 25, 3, 10, ' هو لي دب كامن ، أسد في مخابىء '),
(22473, 'Lamentations', 25, 3, 11, ' ميل طرقي ومزقني . جعلني خرابا '),
(22474, 'Lamentations', 25, 3, 12, ' مد قوسه ونصبني كغرض للسهم '),
(22475, 'Lamentations', 25, 3, 13, ' أدخل في كليتي نبال جعبته '),
(22476, 'Lamentations', 25, 3, 14, ' صرت ضحكة لكل شعبي ، وأغنية لهم اليوم كله '),
(22477, 'Lamentations', 25, 3, 15, ' أشبعني مرائر وأرواني أفسنتينا '),
(22478, 'Lamentations', 25, 3, 16, ' وجرش بالحصى أسناني . كبسني بالرماد '),
(22479, 'Lamentations', 25, 3, 17, ' وقد أبعدت عن السلام نفسي . نسيت الخير '),
(22480, 'Lamentations', 25, 3, 18, ' وقلت : بادت ثقتي ورجائي من الرب '),
(22481, 'Lamentations', 25, 3, 19, ' ذكر مذلتي وتيهاني أفسنتين وعلقم '),
(22482, 'Lamentations', 25, 3, 20, ' ذكرا تذكر نفسي وتنحني في '),
(22483, 'Lamentations', 25, 3, 21, ' أردد هذا في قلبي ، من أجل ذلك أرجو '),
(22484, 'Lamentations', 25, 3, 22, ' إنه من إحسانات الرب أننا لم نفن ، لأن مراحمه لا تزول '),
(22485, 'Lamentations', 25, 3, 23, ' هي جديدة في كل صباح . كثيرة أمانتك '),
(22486, 'Lamentations', 25, 3, 24, ' نصيبي هو الرب ، قالت نفسي ، من أجل ذلك أرجوه '),
(22487, 'Lamentations', 25, 3, 25, ' طيب هو الرب للذين يترجونه ، للنفس التي تطلبه '),
(22488, 'Lamentations', 25, 3, 26, ' جيد أن ينتظر الإنسان ويتوقع بسكوت خلاص الرب '),
(22489, 'Lamentations', 25, 3, 27, ' جيد للرجل أن يحمل النير في صباه '),
(22490, 'Lamentations', 25, 3, 28, ' يجلس وحده ويسكت ، لأنه قد وضعه عليه '),
(22491, 'Lamentations', 25, 3, 29, ' يجعل في التراب فمه لعله يوجد رجاء '),
(22492, 'Lamentations', 25, 3, 30, ' يعطي خده لضاربه . يشبع عارا '),
(22493, 'Lamentations', 25, 3, 31, ' لأن السيد لا يرفض إلى الأبد '),
(22494, 'Lamentations', 25, 3, 32, ' فإنه ولو أحزن يرحم حسب كثرة مراحمه '),
(22495, 'Lamentations', 25, 3, 33, ' لأنه لا يذل من قلبه ، ولا يحزن بني الإنسان '),
(22496, 'Lamentations', 25, 3, 34, ' أن يدوس أحد تحت رجليه كل أسرى الأرض '),
(22497, 'Lamentations', 25, 3, 35, ' أن يحرف حق الرجل أمام وجه العلي '),
(22498, 'Lamentations', 25, 3, 36, ' أن يقلب الإنسان في دعواه . السيد لا يرى '),
(22499, 'Lamentations', 25, 3, 37, ' من ذا الذي يقول فيكون والرب لم يأمر '),
(22500, 'Lamentations', 25, 3, 38, ' من فم العلي ألا تخرج الشرور والخير '),
(22501, 'Lamentations', 25, 3, 39, ' لماذا يشتكي الإنسان الحي ، الرجل من قصاص خطاياه '),
(22502, 'Lamentations', 25, 3, 40, ' لنفحص طرقنا ونمتحنها ونرجع إلى الرب '),
(22503, 'Lamentations', 25, 3, 41, ' لنرفع قلوبنا وأيدينا إلى الله في السماوات '),
(22504, 'Lamentations', 25, 3, 42, ' نحن أذنبنا وعصينا . أنت لم تغفر '),
(22505, 'Lamentations', 25, 3, 43, ' التحفت بالغضب وطردتنا . قتلت ولم تشفق '),
(22506, 'Lamentations', 25, 3, 44, ' التحفت بالسحاب حتى لا تنفذ الصلاة '),
(22507, 'Lamentations', 25, 3, 45, ' جعلتنا وسخا وكرها في وسط الشعوب '),
(22508, 'Lamentations', 25, 3, 46, ' فتح كل أعدائنا أفواههم علينا '),
(22509, 'Leviticus', 3, 5, 16, ' ويعوض عما أخطأ به من القدس ، ويزيد عليه خمسه ، ويدفعه إلى الكاهن ، فيكفر الكاهن عنه بكبش الإثم ، فيصفح عنه '),
(22510, 'Leviticus', 3, 5, 17, ' وإذا أخطأ أحد وعمل واحدة من جميع مناهي الرب التي لا ينبغي عملها ، ولم يعلم ، كان مذنبا وحمل ذنبه '),
(22511, 'Leviticus', 3, 5, 18, ' فيأتي بكبش صحيح من الغنم بتقويمك ، ذبيحة إثم ، إلى الكاهن ، فيكفر عنه الكاهن من سهوه الذي سها وهو لا يعلم ، فيصفح عنه '),
(22512, 'Leviticus', 3, 5, 19, ' إنه ذبيحة إثم . قد أثم إثما إلى الرب '),
(22513, 'Leviticus', 3, 6, 1, ' وكلم الرب موسى قائلا '),
(22514, 'Leviticus', 3, 6, 2, ' إذا أخطأ أحد وخان خيانة بالرب ، وجحد صاحبه وديعة أو أمانة أو مسلوبا ، أو اغتصب من صاحبه '),
(22515, 'Leviticus', 3, 6, 3, ' أو وجد لقطة وجحدها ، وحلف كاذبا على شيء من كل ما يفعله الإنسان مخطئا به '),
(22516, 'Leviticus', 3, 6, 4, ' فإذا أخطأ وأذنب ، يرد المسلوب الذي سلبه ، أو المغتصب الذي اغتصبه ، أوالوديعة التي أودعت عنده ، أو اللقطة التي وجدها '),
(22517, 'Leviticus', 3, 6, 5, ' أو كل ما حلف عليه كاذبا . يعوضه برأسه ، ويزيد عليه خمسه . إلى الذي هو له يدفعه يوم ذبيحة إثمه '),
(22518, 'Leviticus', 3, 6, 6, ' ويأتي إلى الرب بذبيحة لإثمه : كبشا صحيحا من الغنم بتقويمك ، ذبيحة إثم إلى الكاهن '),
(22519, 'Leviticus', 3, 6, 7, ' فيكفر عنه الكاهن أمام الرب ، فيصفح عنه في الشيء من كل ما فعله مذنبا به '),
(22520, 'Leviticus', 3, 6, 8, ' وكلم الرب موسى قائلا '),
(22521, 'Leviticus', 3, 6, 9, ' أوص هارون وبنيه قائلا : هذه شريعة المحرقة : هي المحرقة تكون على الموقدة فوق المذبح كل الليل حتى الصباح ، ونار المذبح تتقد عليه '),
(22522, 'Leviticus', 3, 6, 10, ' ثم يلبس الكاهن ثوبه من كتان ، ويلبس سراويل من كتان على جسده ، ويرفع الرماد الذي صيرت النار المحرقة إياه على المذبح ، ويضعه بجانب المذبح '),
(22523, 'Leviticus', 3, 6, 11, ' ثم يخلع ثيابه ويلبس ثيابا أخرى ، ويخرج الرماد إلى خارج المحلة ، إلى مكان طاهر '),
(22524, 'Leviticus', 3, 6, 12, ' والنار على المذبح تتقد عليه . لا تطفأ . ويشعل عليها الكاهن حطبا كل صباح ، ويرتب عليها المحرقة ، ويوقد عليها شحم ذبائح السلامة '),
(22525, 'Leviticus', 3, 6, 13, ' نار دائمة تتقد على المذبح . لا تطفأ '),
(22526, 'Leviticus', 3, 6, 14, ' وهذه شريعة التقدمة : يقدمها بنو هارون أمام الرب إلى قدام المذبح '),
(22527, 'Leviticus', 3, 6, 15, ' ويأخذ منها بقبضته بعض دقيق التقدمة وزيتها وكل اللبان الذي على التقدمة ، ويوقد على المذبح رائحة سرور تذكارها للرب '),
(22528, 'Leviticus', 3, 6, 16, ' والباقي منها يأكله هارون وبنوه . فطيرا يؤكل في مكان مقدس . في دار خيمة الاجتماع يأكلونه '),
(22529, 'Leviticus', 3, 6, 17, ' لا يخبز خميرا . قد جعلته نصيبهم من وقائدي . إنها قدس أقداس كذبيحة الخطية وذبيحة الإثم '),
(22530, 'Leviticus', 3, 6, 18, ' كل ذكر من بني هارون يأكل منها . فريضة دهرية في أجيالكم من وقائد الرب . كل من مسها يتقدس '),
(22531, 'Leviticus', 3, 6, 19, ' وكلم الرب موسى قائلا '),
(22532, 'Leviticus', 3, 6, 20, ' هذا قربان هارون وبنيه الذي يقربونه للرب يوم مسحته : عشر الإيفة من دقيق تقدمة دائمة ، نصفها صباحا ، ونصفها مساء '),
(22533, 'Leviticus', 3, 6, 21, ' على صاج تعمل بزيت ، مربوكة تأتي بها . ثرائد تقدمة ، فتاتا تقربها رائحة سرور للرب '),
(22534, 'Leviticus', 3, 6, 22, ' والكاهن الممسوح عوضا عنه من بنيه يعملها فريضة دهرية للرب . توقد بكمالها '),
(22535, 'Leviticus', 3, 6, 23, ' وكل تقدمة كاهن تحرق بكمالها . لا تؤكل '),
(22536, 'Leviticus', 3, 6, 24, ' وكلم الرب موسى قائلا '),
(22537, 'Leviticus', 3, 6, 25, ' كلم هارون وبنيه قائلا : هذه شريعة ذبيحة الخطية : في المكان الذي تذبح فيه المحرقة ، تذبح ذبيحة الخطية أمام الرب . إنها قدس أقداس '),
(22538, 'Leviticus', 3, 6, 26, ' الكاهن الذي يعملها للخطية يأكلها . في مكان مقدس تؤكل في دار خيمة الاجتماع '),
(22539, 'Leviticus', 3, 6, 27, ' كل من مس لحمها يتقدس . وإذا انتثر من دمها على ثوب تغسل ما انتثر عليه في مكان مقدس '),
(22540, 'Leviticus', 3, 6, 28, ' وأما إناء الخزف الذي تطبخ فيه فيكسر . وإن طبخت في إناء نحاس ، يجلى ويشطف بماء '),
(22541, 'Leviticus', 3, 6, 29, ' كل ذكر من الكهنة يأكل منها . إنها قدس أقداس '),
(22542, 'Leviticus', 3, 6, 30, ' وكل ذبيحة خطية يدخل من دمها إلى خيمة الاجتماع للتكفير في القدس ، لا تؤكل . تحرق بنار '),
(22543, 'Leviticus', 3, 7, 1, ' وهذه شريعة ذبيحة الإثم : إنها قدس أقداس '),
(22544, 'Leviticus', 3, 7, 2, ' في المكان الذي يذبحون فيه المحرقة ، يذبحون ذبيحة الإثم ، ويرش دمها على المذبح مستديرا '),
(22545, 'Leviticus', 3, 7, 3, ' ويقرب منها كل شحمها : الألية ، والشحم الذي يغشي الأحشاء '),
(22546, 'Leviticus', 3, 7, 4, ' والكليتين والشحم الذي عليهما ، الذي على الخاصرتين ، وزيادة الكبد مع الكليتين ينزعها '),
(22547, 'Leviticus', 3, 7, 5, ' ويوقدهن الكاهن على المذبح وقودا للرب . إنها ذبيحة إثم '),
(22548, 'Leviticus', 3, 7, 6, ' كل ذكر من الكهنة يأكل منها . في مكان مقدس تؤكل . إنها قدس أقداس '),
(22549, 'Leviticus', 3, 7, 7, ' ذبيحة الإثم كذبيحة الخطية ، لهما شريعة واحدة . الكاهن الذي يكفر بها تكون له '),
(22550, 'Leviticus', 3, 7, 8, ' والكاهن الذي يقرب محرقة إنسان فجلد المحرقة التي يقربها يكون له '),
(22551, 'Leviticus', 3, 7, 9, ' وكل تقدمة خبزت في التنور ، وكل ما عمل في طاجن أو على صاج يكون للكاهن الذي يقربه '),
(22552, 'Leviticus', 3, 7, 10, ' وكل تقدمة ملتوتة بزيت أو ناشفة تكون لجميع بني هارون ، كل إنسان كأخيه '),
(22553, 'Leviticus', 3, 7, 11, ' وهذه شريعة ذبيحة السلامة . الذي يقربها للرب '),
(22554, 'Leviticus', 3, 7, 12, ' إن قربها لأجل الشكر ، يقرب على ذبيحة الشكر أقراص فطير ملتوتة بزيت ، ورقاق فطير مدهونة بزيت ، ودقيقا مربوكا أقراصا ملتوتة بزيت '),
(22555, 'Leviticus', 3, 7, 13, ' مع أقراص خبز خمير يقرب قربانه على ذبيحة شكر سلامته '),
(22556, 'Leviticus', 3, 7, 14, ' ويقرب منه واحدا من كل قربان رفيعة للرب ، يكون للكاهن الذي يرش دم ذبيحة السلامة '),
(22557, 'Leviticus', 3, 7, 15, ' ولحم ذبيحة شكر سلامته يؤكل يوم قربانه . لا يبقي منه شيئا إلى الصباح '),
(22558, 'Leviticus', 3, 7, 16, ' وإن كانت ذبيحة قربانه نذرا أو نافلة ، ففي يوم تقريبه ذبيحته تؤكل . وفي الغد يؤكل ما فضل منها '),
(22559, 'Leviticus', 3, 7, 17, ' وأما الفاضل من لحم الذبيحة في اليوم الثالث فيحرق بالنار '),
(22560, 'Leviticus', 3, 7, 18, ' وإن أكل من لحم ذبيحة سلامته في اليوم الثالث لا تقبل . الذي يقربها لا تحسب له ، تكون نجاسة ، والنفس التي تأكل منها تحمل ذنبها '),
(22561, 'Leviticus', 3, 7, 19, ' واللحم الذي مس شيئا ما نجسا لا يؤكل . يحرق بالنار . واللحم يأكل كل طاهر منه '),
(22562, 'Leviticus', 3, 7, 20, ' وأما النفس التي تأكل لحما من ذبيحة السلامة التي للرب ونجاستها عليها فتقطع تلك النفس من شعبها '),
(22563, 'Leviticus', 3, 7, 21, ' والنفس التي تمس شيئا ما نجسا نجاسة إنسان أو بهيمة نجسة أو مكروها ما نجسا ، ثم تأكل من لحم ذبيحة السلامة التي للرب ، تقطع تلك النفس من شعبها '),
(22564, 'Leviticus', 3, 7, 22, ' وكلم الرب موسى قائلا '),
(22565, 'Leviticus', 3, 7, 23, ' كلم بني إسرائيل قائلا : كل شحم ثور أو كبش أو ماعز لا تأكلوا '),
(22566, 'Leviticus', 3, 7, 24, ' وأما شحم الميتة وشحم المفترسة فيستعمل لكل عمل ، لكن أكلا لا تأكلوه '),
(22567, 'Leviticus', 3, 7, 25, ' إن كل من أكل شحما من البهائم التي يقرب منها وقودا للرب تقطع من شعبها ، النفس التي تأكل '),
(22568, 'Leviticus', 3, 7, 26, ' وكل دم لا تأكلوا في جميع مساكنكم من الطير ومن البهائم '),
(22569, 'Leviticus', 3, 7, 27, ' كل نفس تأكل شيئا من الدم تقطع تلك النفس من شعبها '),
(22570, 'Leviticus', 3, 7, 28, ' وكلم الرب موسى قائلا '),
(22571, 'Leviticus', 3, 7, 29, ' كلم بني إسرائيل قائلا : الذي يقرب ذبيحة سلامته للرب ، يأتي بقربانه إلى الرب من ذبيحة سلامته '),
(22572, 'Leviticus', 3, 7, 30, ' يداه تأتيان بوقائد الرب . الشحم يأتي به مع الصدر . أما الصدر فلكي يردده ترديدا أمام الرب '),
(22573, 'Leviticus', 3, 7, 31, ' فيوقد الكاهن الشحم على المذبح ، ويكون الصدر لهارون وبنيه '),
(22574, 'Leviticus', 3, 7, 32, ' والساق اليمنى تعطونها رفيعة للكاهن من ذبائح سلامتكم '),
(22575, 'Leviticus', 3, 7, 33, ' الذي يقرب دم ذبيحة السلامة والشحم من بني هارون ، تكون له الساق اليمنى نصيبا '),
(22576, 'Leviticus', 3, 7, 34, ' لأن صدر الترديد وساق الرفيعة قد أخذتهما من بني إسرائيل من ذبائح سلامتهم وأعطيتهما لهارون الكاهن ولبنيه فريضة دهرية من بني إسرائيل '),
(22577, 'Leviticus', 3, 7, 35, ' تلك مسحة هارون ومسحة بنيه من وقائد الرب يوم تقديمهم ليكهنوا للرب '),
(22578, 'Leviticus', 3, 7, 36, ' التي أمر الرب أن تعطى لهم يوم مسحه إياهم من بني إسرائيل ، فريضة دهرية في أجيالهم '),
(22579, 'Leviticus', 3, 7, 37, ' تلك شريعة المحرقة ، والتقدمة ، وذبيحة الخطية ، وذبيحة الإثم ، وذبيحة الملء ، وذبيحة السلامة '),
(22580, 'Leviticus', 3, 7, 38, ' التي أمر الرب بها موسى في جبل سيناء ، يوم أمره بني إسرائيل بتقريب قرابينهم للرب في برية سيناء '),
(22581, 'Leviticus', 3, 8, 1, ' وكلم الرب موسى قائلا '),
(22582, 'Leviticus', 3, 8, 2, ' خذ هارون وبنيه معه ، والثياب ودهن المسحة وثور الخطية والكبشين وسل الفطير '),
(22583, 'Leviticus', 3, 8, 3, ' واجمع كل الجماعة إلى باب خيمة الاجتماع '),
(22584, 'Leviticus', 3, 8, 4, ' ففعل موسى كما أمره الرب . فاجتمعت الجماعة إلى باب خيمة الاجتماع '),
(22585, 'Leviticus', 3, 8, 5, ' ثم قال موسى للجماعة : هذا ما أمر الرب أن يفعل '),
(22586, 'Leviticus', 3, 8, 6, ' فقدم موسى هارون وبنيه وغسلهم بماء '),
(22587, 'Leviticus', 3, 8, 7, ' وجعل عليه القميص ونطقه بالمنطقة وألبسه الجبة وجعل عليه الرداء ، ونطقه بزنار الرداء وشده به '),
(22588, 'Leviticus', 3, 8, 8, ' ووضع عليه الصدرة وجعل في الصدرة الأوريم والتميم '),
(22589, 'Leviticus', 3, 8, 9, ' ووضع العمامة على رأسه ، ووضع على العمامة إلى جهة وجهه صفيحة الذهب ، الإكليل المقدس ، كما أمر الرب موسى '),
(22590, 'Leviticus', 3, 8, 10, ' ثم أخذ موسى دهن المسحة ومسح المسكن وكل ما فيه وقدسه '),
(22591, 'Leviticus', 3, 8, 11, ' ونضح منه على المذبح سبع مرات ، ومسح المذبح وجميع آنيته ، والمرحضة وقاعدتها لتقديسها '),
(22592, 'Leviticus', 3, 8, 12, ' وصب من دهن المسحة على رأس هارون ومسحه لتقديسه '),
(22593, 'Leviticus', 3, 8, 13, ' ثم قدم موسى بني هارون وألبسهم أقمصة ونطقهم بمناطق وشد لهم قلانس ، كما أمر الرب موسى '),
(22594, 'Leviticus', 3, 8, 14, ' ثم قدم ثور الخطية ، ووضع هارون وبنوه أيديهم على رأس ثور الخطية '),
(22595, 'Leviticus', 3, 8, 15, ' فذبحه ، وأخذ موسى الدم وجعله على قرون المذبح مستديرا بإصبعه ، وطهر المذبح . ثم صب الدم إلى أسفل المذبح وقدسه تكفيرا عنه '),
(22596, 'Leviticus', 3, 8, 16, ' وأخذ كل الشحم الذي على الأحشاء وزيادة الكبد والكليتين وشحمهما ، وأوقده موسى على المذبح '),
(22597, 'Leviticus', 3, 8, 17, ' وأما الثور : جلده ولحمه وفرثه ، فأحرقه بنار خارج المحلة ، كما أمر الرب موسى '),
(22598, 'Leviticus', 3, 8, 18, ' ثم قدم كبش المحرقة ، فوضع هارون وبنوه أيديهم على رأس الكبش '),
(22599, 'Leviticus', 3, 8, 19, ' فذبحه ، ورش موسى الدم على المذبح مستديرا '),
(22600, 'Leviticus', 3, 8, 20, ' وقطع الكبش إلى قطعه . وأوقد موسى الرأس والقطع والشحم '),
(22601, 'Leviticus', 3, 8, 21, ' وأما الأحشاء والأكارع فغسلها بماء ، وأوقد موسى كل الكبش على المذبح . إنه محرقة لرائحة سرور . وقود هو للرب ، كما أمر الرب موسى '),
(22602, 'Leviticus', 3, 8, 22, ' ثم قدم الكبش الثاني ، كبش الملء ، فوضع هارون وبنوه أيديهم على رأس الكبش '),
(22603, 'Leviticus', 3, 8, 23, ' فذبحه ، وأخذ موسى من دمه وجعل على شحمة أذن هارون اليمنى ، وعلى إبهام يده اليمنى ، وعلى إبهام رجله اليمنى '),
(22604, 'Leviticus', 3, 8, 24, ' ثم قدم موسى بني هارون وجعل من الدم على شحم آذانهم اليمنى ، وعلى أباهم أيديهم اليمنى ، وعلى أباهم أرجلهم اليمنى ، ثم رش موسى الدم على المذبح مستديرا '),
(22605, 'Leviticus', 3, 8, 25, ' ثم أخذ الشحم : الألية وكل الشحم الذي على الأحشاء ، وزيادة الكبد والكليتين وشحمهما ، والساق اليمنى '),
(22606, 'Leviticus', 3, 8, 26, ' ومن سل الفطير الذي أمام الرب ، أخذ قرصا واحدا فطيرا ، وقرصا واحدا من الخبز بزيت ، ورقاقة واحدة ، ووضعها على الشحم وعلى الساق اليمنى '),
(22607, 'Leviticus', 3, 8, 27, ' وجعل الجميع على كفي هارون وكفوف بنيه ، ورددها ترديدا أمام الرب '),
(22608, 'Leviticus', 3, 8, 28, ' ثم أخذها موسى عن كفوفهم ، وأوقدها على المذبح فوق المحرقة . إنها قربان ملء لرائحة سرور . وقود هي للرب '),
(22609, 'Leviticus', 3, 8, 29, ' ثم أخذ موسى الصدر وردده ترديدا أمام الرب من كبش الملء . لموسى كان نصيبا ، كما أمر الرب موسى '),
(22610, 'Leviticus', 3, 8, 30, ' ثم أخذ موسى من دهن المسحة ومن الدم الذي على المذبح ، ونضح على هارون وعلى ثيابه ، وعلى بنيه وعلى ثياب بنيه معه . وقدس هارون وثيابه وبنيه وثياب بنيه معه '),
(22611, 'Leviticus', 3, 8, 31, ' ثم قال موسى لهارون وبنيه : اطبخوا اللحم لدى باب خيمة الاجتماع ، وهناك تأكلونه والخبز الذي في سل قربان الملء ، كما أمرت قائلا : هارون وبنوه يأكلونه '),
(22612, 'Leviticus', 3, 8, 32, ' والباقي من اللحم والخبز تحرقونه بالنار '),
(22613, 'Leviticus', 3, 8, 33, ' ومن لدن باب خيمة الاجتماع ، لا تخرجون سبعة أيام إلى يوم كمال أيام ملئكم ، لأنه سبعة أيام يملأ أيديكم '),
(22614, 'Leviticus', 3, 8, 34, ' كما فعل في هذا اليوم ، قد أمر الرب أن يفعل للتكفير عنكم '),
(22615, 'Leviticus', 3, 8, 35, ' ولدى باب خيمة الاجتماع تقيمون نهارا وليلا سبعة أيام ، وتحفظون شعائر الرب فلا تموتون ، لأني هكذا أمرت '),
(22616, 'Leviticus', 3, 8, 36, ' فعمل هارون وبنوه كل ما أمر به الرب على يد موسى '),
(22617, 'Leviticus', 3, 9, 1, ' وفي اليوم الثامن دعا موسى هارون وبنيه وشيوخ إسرائيل '),
(22618, 'Leviticus', 3, 9, 2, ' وقال لهارون : خذ لك عجلا ابن بقر لذبيحة خطية ، وكبشا لمحرقة صحيحين ، وقدمهما أمام الرب '),
(22619, 'Leviticus', 3, 9, 3, ' وكلم بني إسرائيل قائلا : خذوا تيسا من المعز لذبيحة خطية ، وعجلا وخروفا حوليين صحيحين لمحرقة '),
(22620, 'Leviticus', 3, 9, 4, ' وثورا وكبشا لذبيحة سلامة للذبح أمام الرب ، وتقدمة ملتوتة بزيت . لأن الرب اليوم يتراءى لكم '),
(22621, 'Leviticus', 3, 9, 5, ' فأخذوا ما أمر به موسى إلى قدام خيمة الاجتماع . وتقدم كل الجماعة ووقفوا أمام الرب '),
(22622, 'Leviticus', 3, 9, 6, ' فقال موسى : هذا ما أمر به الرب . تعملونه فيتراءى لكم مجد الرب '),
(22623, 'Leviticus', 3, 9, 7, ' ثم قال موسى لهارون : تقدم إلى المذبح واعمل ذبيحة خطيتك ومحرقتك ، وكفر عن نفسك وعن الشعب . واعمل قربان الشعب وكفر عنهم كما أمر الرب '),
(22624, 'Leviticus', 3, 9, 8, ' فتقدم هارون إلى المذبح وذبح عجل الخطية الذي له '),
(22625, 'Leviticus', 3, 9, 9, ' وقدم بنو هارون إليه الدم ، فغمس إصبعه في الدم وجعل على قرون المذبح ، ثم صب الدم إلى أسفل المذبح '),
(22626, 'Leviticus', 3, 9, 10, ' والشحم والكليتين وزيادة الكبد من ذبيحة الخطية أوقدها على المذبح ، كما أمر الرب موسى '),
(22627, 'Leviticus', 3, 9, 11, ' وأما اللحم والجلد فأحرقهما بنار خارج المحلة '),
(22628, 'Leviticus', 3, 9, 12, ' ثم ذبح المحرقة ، فناوله بنو هارون الدم ، فرشه على المذبح مستديرا '),
(22629, 'Leviticus', 3, 9, 13, ' ثم ناولوه المحرقة بقطعها والرأس ، فأوقدها على المذبح '),
(22630, 'Leviticus', 3, 9, 14, ' وغسل الأحشاء والأكارع وأوقدها فوق المحرقة على المذبح '),
(22631, 'Leviticus', 3, 9, 15, ' ثم قدم قربان الشعب ، وأخذ تيس الخطية الذي للشعب وذبحه وعمله للخطية كالأول '),
(22632, 'Leviticus', 3, 9, 16, ' ثم قدم المحرقة وعملها كالعادة '),
(22633, 'Leviticus', 3, 9, 17, ' ثم قدم التقدمة وملأ كفه منها ، وأوقدها على المذبح ، عدا محرقة الصباح '),
(22634, 'Leviticus', 3, 9, 18, ' ثم ذبح الثور والكبش ذبيحة السلامة التي للشعب . وناوله بنو هارون الدم فرشه على المذبح مستديرا '),
(22635, 'Leviticus', 3, 9, 19, ' والشحم من الثور ومن الكبش : الألية وما يغشي ، والكليتين وزيادة الكبد '),
(22636, 'Leviticus', 3, 10, 2, ' فخرجت نار من عند الرب وأكلتهما ، فماتا أمام الرب '),
(22637, 'Leviticus', 3, 10, 3, ' فقال موسى لهارون : هذا ما تكلم به الرب قائلا : في القريبين مني أتقدس ، وأمام جميع الشعب أتمجد . فصمت هارون '),
(22638, 'Leviticus', 3, 10, 4, ' فدعا موسى ميشائيل وألصافان ابني عزيئيل عم هارون ، وقال لهما : تقدما ارفعا أخويكما من قدام القدس إلى خارج المحلة '),
(22639, 'Leviticus', 3, 10, 5, ' فتقدما ورفعاهما في قميصيهما إلى خارج المحلة ، كما قال موسى '),
(22640, 'Leviticus', 3, 10, 6, ' وقال موسى لهارون وألعازار وإيثامار ابنيه : لاتكشفوا رؤوسكم ولا تشقوا ثيابكم لئلا تموتوا ، ويسخط على كل الجماعة . وأما إخوتكم كل بيت إسرائيل فيبكون على الحريق الذي أحرقه الرب '),
(22641, 'Leviticus', 3, 10, 7, ' ومن باب خيمة الاجتماع لا تخرجوا لئلا تموتوا ، لأن دهن مسحة الرب عليكم . ففعلوا حسب كلام موسى '),
(22642, 'Leviticus', 3, 10, 8, ' وكلم الرب هارون قائلا '),
(22643, 'Leviticus', 3, 10, 9, ' خمرا ومسكرا لا تشرب أنت وبنوك معك عند دخولكم إلى خيمة الاجتماع لكي لا تموتوا . فرضا دهريا في أجيالكم '),
(22644, 'Leviticus', 3, 10, 10, ' وللتمييز بين المقدس والمحلل وبين النجس والطاهر '),
(22645, 'Leviticus', 3, 10, 11, ' ولتعليم بني إسرائيل جميع الفرائض التي كلمهم الرب بها بيد موسى '),
(22646, 'Leviticus', 3, 10, 12, ' وقال موسى لهارون وألعازار وإيثامار ابنيه الباقيين : خذوا التقدمة الباقية من وقائد الرب وكلوها فطيرا بجانب المذبح لأنها قدس أقداس '),
(22647, 'Leviticus', 3, 10, 13, ' كلوها في مكان مقدس لأنها فريضتك وفريضة بنيك من وقائد الرب ، فإنني هكذا أمرت '),
(22648, 'Leviticus', 3, 10, 14, ' وأما صدر الترديد وساق الرفيعة فتأكلونهما في مكان طاهر أنت وبنوك وبناتك معك ، لأنهما جعلا فريضتك وفريضة بنيك من ذبائح سلامة بني إسرائيل '),
(22649, 'Leviticus', 3, 10, 15, ' ساق الرفيعة وصدر الترديد يأتون بهما مع وقائد الشحم ليرددا ترديدا أمام الرب ، فيكونان لك ولبنيك معك فريضة دهرية ، كما أمر الرب '),
(22650, 'Leviticus', 3, 10, 16, ' وأما تيس الخطية فإن موسى طلبه فإذا هو قد احترق . فسخط على ألعازار وإيثامار ، ابني هارون الباقيين ، وقال '),
(22651, 'Leviticus', 3, 10, 17, ' ما لكما لم تأكلا ذبيحة الخطية في المكان المقدس ؟ لأنها قدس أقداس ، وقد أعطاكما إياها لتحملا إثم الجماعة تكفيرا عنهم أمام الرب '),
(22652, 'Leviticus', 3, 10, 18, ' إنه لم يؤت بدمها إلى القدس داخلا . أكلا تأكلانها في القدس كما أمرت '),
(22653, 'Leviticus', 3, 10, 19, ' فقال هارون لموسى : إنهما اليوم قد قربا ذبيحة خطيتهما ومحرقتهما أمام الرب ، وقد أصابني مثل هذه . فلو أكلت ذبيحة الخطية اليوم ، هل كان يحسن في عيني الرب '),
(22654, 'Leviticus', 3, 10, 20, ' فلما سمع موسى حسن في عينيه '),
(22655, 'Leviticus', 3, 11, 1, ' وكلم الرب موسى وهارون قائلا لهما '),
(22656, 'Leviticus', 3, 11, 2, ' كلما بني إسرائيل قائلين : هذه هي الحيوانات التي تأكلونها من جميع البهائم التي على الأرض '),
(22657, 'Leviticus', 3, 11, 3, ' كل ما شق ظلفا وقسمه ظلفين ، ويجتر من البهائم ، فإياه تأكلون '),
(22658, 'Leviticus', 3, 11, 4, ' إلا هذه فلا تأكلوها مما يجتر ومما يشق الظلف : الجمل ، لأنه يجتر لكنه لا يشق ظلفا ، فهو نجس لكم '),
(22659, 'Leviticus', 3, 11, 5, ' والوبر ، لأنه يجتر لكنه لا يشق ظلفا ، فهو نجس لكم '),
(22660, 'Leviticus', 3, 11, 6, ' والأرنب ، لأنه يجتر لكنه لا يشق ظلفا ، فهو نجس لكم '),
(22661, 'Leviticus', 3, 11, 7, ' والخنزير ، لأنه يشق ظلفا ويقسمه ظلفين ، لكنه لا يجتر ، فهو نجس لكم '),
(22662, 'Leviticus', 3, 11, 8, ' من لحمها لاتأكلوا وجثثها لا تلمسوا . إنها نجسة لكم '),
(22663, 'Leviticus', 3, 11, 9, ' وهذا تأكلونه من جميع ما في المياه : كل ما له زعانف وحرشف في المياه ، في البحار وفي الأنهار ، فإياه تأكلون '),
(22664, 'Leviticus', 3, 11, 10, ' لكن كل ما ليس له زعانف وحرشف في البحار وفي الأنهار ، من كل دبيب في المياه ومن كل نفس حية في المياه ، فهو مكروه لكم '),
(22665, 'Leviticus', 3, 11, 11, ' ومكروها يكون لكم . من لحمه لا تأكلوا ، وجثته تكرهون '),
(22666, 'Leviticus', 3, 11, 12, ' كل ما ليس له زعانف وحرشف في المياه فهو مكروه لكم '),
(22667, 'Leviticus', 3, 11, 13, ' وهذه تكرهونها من الطيور . لا تؤكل . إنها مكروهة : النسر والأنوق والعقاب '),
(22668, 'Leviticus', 3, 11, 14, ' والحدأة والباشق على أجناسه '),
(22669, 'Leviticus', 3, 11, 15, ' وكل غراب على أجناسه '),
(22670, 'Leviticus', 3, 11, 16, ' والنعامة والظليم والسأف والباز على أجناسه '),
(22671, 'Leviticus', 3, 11, 17, ' والبوم والغواص والكركي '),
(22672, 'Leviticus', 3, 11, 18, ' والبجع والقوق والرخم '),
(22673, 'Leviticus', 3, 11, 19, ' واللقلق والببغا على أجناسه ، والهدهد والخفاش '),
(22674, 'Leviticus', 3, 11, 20, ' وكل دبيب الطير الماشي على أربع . فهو مكروه لكم '),
(22675, 'Leviticus', 3, 11, 21, ' إلا هذا تأكلونه من جميع دبيب الطير الماشي على أربع : ما له كراعان فوق رجليه يثب بهما على الأرض '),
(22676, 'Leviticus', 3, 11, 22, ' هذا منه تأكلون : الجراد على أجناسه ، والدبا على أجناسه ، والحرجوان على أجناسه ، والجندب على أجناسه '),
(22677, 'Leviticus', 3, 11, 23, ' لكن سائر دبيب الطير الذي له أربع أرجل فهو مكروه لكم '),
(22678, 'Leviticus', 3, 11, 24, ' من هذه تتنجسون . كل من مس جثثها يكون نجسا إلى المساء '),
(22679, 'Leviticus', 3, 11, 25, ' وكل من حمل من جثثها يغسل ثيابه ويكون نجسا إلى المساء '),
(22680, 'Leviticus', 3, 11, 26, ' وجميع البهائم التي لها ظلف ولكن لا تشقه شقا أو لا تجتر ، فهي نجسة لكم . كل من مسها يكون نجسا '),
(22681, 'Leviticus', 3, 11, 27, ' وكل ما يمشي على كفوفه من جميع الحيوانات الماشية على أربع ، فهو نجس لكم . كل من مس جثثها يكون نجسا إلى المساء '),
(22682, 'Leviticus', 3, 11, 28, ' ومن حمل جثثها يغسل ثيابه ويكون نجسا إلى المساء . إنها نجسة لكم '),
(22683, 'Leviticus', 3, 11, 29, ' وهذا هو النجس لكم من الدبيب الذي يدب على الأرض : ابن عرس والفأر والضب على أجناسه '),
(22684, 'Leviticus', 3, 11, 30, ' والحرذون والورل والوزغة والعظاية والحرباء '),
(22685, 'Leviticus', 3, 11, 31, ' هذه هي النجسة لكم من كل الدبيب . كل من مسها بعد موتها يكون نجسا إلى المساء '),
(22686, 'Leviticus', 3, 11, 32, ' وكل ما وقع عليه واحد منها بعد موتها يكون نجسا . من كل متاع خشب أو ثوب أو جلد أو بلاس . كل متاع يعمل به عمل يلقى في الماء ويكون نجسا إلى المساء ثم يطهر '),
(22687, 'Leviticus', 3, 11, 33, ' وكل متاع خزف وقع فيه منها ، فكل ما فيه يتنجس ، وأما هو فتكسرونه '),
(22688, 'Leviticus', 3, 11, 34, ' ما يأتي عليه ماء من كل طعام يؤكل يكون نجسا . وكل شراب يشرب في كل متاع يكون نجسا '),
(22689, 'Leviticus', 3, 11, 35, ' وكل ما وقع عليه واحدة من جثثها يكون نجسا . التنور والموقدة يهدمان . إنها نجسة وتكون نجسة لكم '),
(22690, 'Leviticus', 3, 11, 36, ' إلا العين والبئر ، مجتمعي الماء ، تكونان طاهرتين . لكن ما مس جثثها يكون نجسا '),
(22691, 'Leviticus', 3, 11, 37, ' وإذا وقعت واحدة من جثثها على شيء من بزر زرع يزرع فهو طاهر '),
(22692, 'Leviticus', 3, 11, 38, ' لكن إذا جعل ماء على بزر فوقع عليه واحدة من جثثها ، فإنه نجس لكم '),
(22693, 'Leviticus', 3, 11, 39, ' وإذا مات واحد من البهائم التي هي طعام لكم ، فمن مس جثته يكون نجسا إلى المساء '),
(22694, 'Leviticus', 3, 11, 40, ' ومن أكل من جثته يغسل ثيابه ويكون نجسا إلى المساء . ومن حمل جثته يغسل ثيابه ويكون نجسا إلى المساء '),
(22695, 'Leviticus', 3, 11, 41, ' وكل دبيب يدب على الأرض فهو مكروه لا يؤكل '),
(22696, 'Leviticus', 3, 11, 42, ' كل ما يمشي على بطنه ، وكل ما يمشي على أربع مع كل ما كثرت أرجله من كل دبيب يدب على الأرض ، لا تأكلوه لأنه مكروه '),
(22697, 'Leviticus', 3, 11, 43, ' لا تدنسوا أنفسكم بدبيب يدب ، ولا تتنجسوا به ، ولا تكونوا به نجسين '),
(22698, 'Leviticus', 3, 11, 44, ' إني أنا الرب إلهكم فتتقدسون وتكونون قديسين ، لأني أنا قدوس . ولا تنجسوا أنفسكم بدبيب يدب على الأرض '),
(22699, 'Leviticus', 3, 11, 45, ' إني أنا الرب الذي أصعدكم من أرض مصر ليكون لكم إلها . فتكونون قديسين لأني أنا قدوس '),
(22700, 'Leviticus', 3, 11, 46, ' هذه شريعة البهائم والطيور وكل نفس حية تسعى في الماء وكل نفس تدب على الأرض '),
(22701, 'Leviticus', 3, 11, 47, ' للتمييز بين النجس والطاهر ، وبين الحيوانات التي تؤكل ، والحيوانات التي لا تؤكل '),
(22702, 'Leviticus', 3, 12, 1, ' وكلم الرب موسى قائلا '),
(22703, 'Leviticus', 3, 12, 2, ' كلم بني إسرائيل قائلا : إذا حبلت امرأة وولدت ذكرا ، تكون نجسة سبعة أيام . كما في أيام طمث علتها تكون نجسة '),
(22704, 'Leviticus', 3, 12, 3, ' وفي اليوم الثامن يختن لحم غرلته '),
(22705, 'Leviticus', 3, 12, 4, ' ثم تقيم ثلاثة وثلاثين يوما في دم تطهيرها . كل شيء مقدس لا تمس ، وإلى المقدس لا تجئ حتى تكمل أيام تطهيرها '),
(22706, 'Leviticus', 3, 12, 5, ' وإن ولدت أنثى ، تكون نجسة أسبوعين كما في طمثها . ثم تقيم ستة وستين يوما في دم تطهيرها '),
(22707, 'Leviticus', 3, 12, 6, ' ومتى كملت أيام تطهيرها لأجل ابن أو ابنة ، تأتي بخروف حولي محرقة ، وفرخ حمامة أو يمامة ذبيحة خطية إلى باب خيمة الاجتماع ، إلى الكاهن '),
(22708, 'Leviticus', 3, 12, 7, ' فيقدمهما أمام الرب ويكفر عنها ، فتطهر من ينبوع دمها . هذه شريعة التي تلد ذكرا أو أنثى '),
(22709, 'Leviticus', 3, 12, 8, ' وإن لم تنل يدها كفاية لشاة تأخذ يمامتين أو فرخي حمام ، الواحد محرقة ، والآخر ذبيحة خطية ، فيكفر عنها الكاهن فتطهر '),
(22710, 'Leviticus', 3, 13, 1, ' وكلم الرب موسى وهارون قائلا '),
(22711, 'Leviticus', 3, 13, 2, ' إذا كان إنسان في جلد جسده ناتئ أو قوباء أو لمعة تصير في جلد جسده ضربة برص ، يؤتى به إلى هارون الكاهن أو إلى أحد بنيه الكهنة '),
(22712, 'Leviticus', 3, 13, 3, ' فإن رأى الكاهن الضربة في جلد الجسد ، وفي الضربة شعر قد ابيض ، ومنظر الضربة أعمق من جلد جسده ، فهي ضربة برص . فمتى رآه الكاهن يحكم بنجاسته '),
(22713, 'Leviticus', 3, 13, 4, ' لكن إن كانت الضربة لمعة بيضاء في جلد جسده ، ولم يكن منظرها أعمق من الجلد ، ولم يبيض شعرها ، يحجز الكاهن المضروب سبعة أيام '),
(22714, 'Leviticus', 3, 13, 5, ' فإن رآه الكاهن في اليوم السابع وإذا في عينه الضربة قد وقفت ، ولم تمتد الضربة في الجلد ، يحجزه الكاهن سبعة أيام ثانية '),
(22715, 'Leviticus', 3, 13, 6, ' فإن رآه الكاهن في اليوم السابع ثانية وإذا الضربة كامدة اللون ، ولم تمتد الضربة في الجلد ، يحكم الكاهن بطهارته . إنها حزاز . فيغسل ثيابه ويكون طاهرا '),
(22716, 'Leviticus', 3, 13, 7, ' لكن إن كانت القوباء تمتد في الجلد بعد عرضه على الكاهن لتطهيره ، يعرض على الكاهن ثانية '),
(22717, 'Leviticus', 3, 13, 8, ' فإن رأى الكاهن وإذا القوباء قد امتدت في الجلد ، يحكم الكاهن بنجاسته . إنها برص '),
(22718, 'Leviticus', 3, 13, 9, ' إن كانت في إنسان ضربة برص فيؤتى به إلى الكاهن '),
(22719, 'Leviticus', 3, 13, 10, ' فإن رأى الكاهن وإذا في الجلد ناتئ أبيض ، قد صير الشعر أبيض ، وفي الناتئ وضح من لحم حي '),
(22720, 'Leviticus', 3, 13, 11, ' فهو برص مزمن في جلد جسده . فيحكم الكاهن بنجاسته . لا يحجزه لأنه نجس '),
(22721, 'Leviticus', 3, 13, 12, ' لكن إن كان البرص قد أفرخ في الجلد ، وغطى البرص كل جلد المضروب من رأسه إلى قدميه حسب كل ما تراه عينا الكاهن '),
(22722, 'Leviticus', 3, 13, 13, ' ورأى الكاهن وإذا البرص قد غطى كل جسمه ، يحكم بطهارة المضروب . كله قد ابيض . إنه طاهر '),
(22723, 'Leviticus', 3, 13, 14, ' لكن يوم يرى فيه لحم حي يكون نجسا '),
(22724, 'Leviticus', 3, 13, 15, ' فمتى رأى الكاهن اللحم الحي يحكم بنجاسته . اللحم الحي نجس . إنه برص '),
(22725, 'Leviticus', 3, 13, 16, ' ثم إن عاد اللحم الحي وابيض يأتي إلى الكاهن '),
(22726, 'Leviticus', 3, 13, 17, ' فإن رآه الكاهن وإذا الضربة قد صارت بيضاء ، يحكم الكاهن بطهارة المضروب . إنه طاهر ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(22727, 'Leviticus', 3, 13, 18, ' وإذا كان الجسم في جلده دملة قد برئت '),
(22728, 'Leviticus', 3, 13, 19, ' وصار في موضع الدملة ناتئ أبيض ، أو لمعة بيضاء ضاربة إلى الحمرة ، يعرض على الكاهن '),
(22729, 'Leviticus', 3, 13, 20, ' فإن رأى الكاهن وإذا منظرها أعمق من الجلد وقد ابيض شعرها ، يحكم الكاهن بنجاسته . إنها ضربة برص أفرخت في الدملة '),
(22730, 'Leviticus', 3, 13, 21, ' لكن إن رآها الكاهن وإذا ليس فيها شعر أبيض ، وليست أعمق من الجلد ، وهي كامدة اللون ، يحجزه الكاهن سبعة أيام '),
(22731, 'Leviticus', 3, 13, 22, ' فإن كانت قد امتدت في الجلد يحكم الكاهن بنجاسته . إنها ضربة '),
(22732, 'Leviticus', 3, 13, 23, ' لكن إن وقفت اللمعة مكانها ولم تمتد ، فهي أثر الدملة . فيحكم الكاهن بطهارته '),
(22733, 'Leviticus', 3, 13, 24, ' أو إذا كان الجسم في جلده كي نار ، وكان حي الكي لمعة بيضاء ضاربة إلى الحمرة أوبيضاء '),
(22734, 'Leviticus', 3, 13, 25, ' ورآها الكاهن وإذا الشعر في اللمعة قد ابيض ، ومنظرها أعمق من الجلد ، فهي برص قد أفرخ في الكي . فيحكم الكاهن بنجاسته . إنها ضربة برص '),
(22735, 'Leviticus', 3, 13, 26, ' لكن إن رآها الكاهن وإذا ليس في اللمعة شعر أبيض ، وليست أعمق من الجلد ، وهي كامدة اللون ، يحجزه الكاهن سبعة أيام '),
(22736, 'Leviticus', 3, 13, 27, ' ثم يراه الكاهن في اليوم السابع . فإن كانت قد امتدت في الجلد ، يحكم الكاهن بنجاسته . إنها ضربة برص '),
(22737, 'Leviticus', 3, 13, 28, ' لكن إن وقفت اللمعة مكانها ، لم تمتد في الجلد ، وكانت كامدة اللون ، فهي ناتئ الكي ، فالكاهن يحكم بطهارته لأنها أثر الكي '),
(22738, 'Leviticus', 3, 13, 29, ' وإذا كان رجل أو امرأة فيه ضربة في الرأس أو في الذقن '),
(22739, 'Leviticus', 3, 13, 30, ' ورأى الكاهن الضربة وإذا منظرها أعمق من الجلد ، وفيها شعر أشقر دقيق ، يحكم الكاهن بنجاسته . إنها قرع . برص الرأس أوالذقن '),
(22740, 'Leviticus', 3, 13, 31, ' لكن إذا رأى الكاهن ضربة القرع وإذا منظرها ليس أعمق من الجلد ، لكن ليس فيها شعر أسود ، يحجز الكاهن المضروب بالقرع سبعة أيام '),
(22741, 'Leviticus', 3, 13, 32, ' فإن رأى الكاهن الضربة في اليوم السابع وإذا القرع لم يمتد ، ولم يكن فيه شعر أشقر ، ولا منظر القرع أعمق من الجلد '),
(22742, 'Leviticus', 3, 13, 33, ' فليحلق . لكن لا يحلق القرع . ويحجز الكاهن الأقرع سبعة أيام ثانية '),
(22743, 'Leviticus', 3, 13, 34, ' فإن رأى الكاهن الأقرع في اليوم السابع وإذا القرع لم يمتد في الجلد ، وليس منظره أعمق من الجلد ، يحكم الكاهن بطهارته ، فيغسل ثيابه ويكون طاهرا '),
(22744, 'Leviticus', 3, 13, 35, ' لكن إن كان القرع يمتد في الجلد بعد الحكم بطهارته '),
(22745, 'Leviticus', 3, 13, 36, ' ورآه الكاهن وإذا القرع قد امتد في الجلد ، فلا يفتش الكاهن على الشعر الأشقر . إنه نجس '),
(22746, 'Leviticus', 3, 13, 37, ' لكن إن وقف في عينيه ونبت فيه شعر أسود ، فقد برئ القرع . إنه طاهر فيحكم الكاهن بطهارته '),
(22747, 'Leviticus', 3, 13, 38, ' وإذا كان رجل أو امرأة في جلد جسده لمع ، لمع بيض '),
(22748, 'Leviticus', 3, 13, 39, ' ورأى الكاهن وإذا في جلد جسده لمع كامدة اللون بيضاء ، فذلك بهق قد أفرخ في الجلد . إنه طاهر '),
(22749, 'Leviticus', 3, 13, 40, ' وإذا كان إنسان قد ذهب شعر رأسه فهو أقرع . إنه طاهر '),
(22750, 'Leviticus', 3, 13, 41, ' وإن ذهب شعر رأسه من جهة وجهه فهو أصلع . إنه طاهر '),
(22751, 'Leviticus', 3, 13, 42, ' لكن إذا كان في القرعة أو في الصلعة ضربة بيضاء ضاربة إلى الحمرة ، فهو برص مفرخ في قرعته أو في صلعته '),
(22752, 'Leviticus', 3, 13, 43, ' فإن رآه الكاهن وإذا ناتئ الضربة أبيض ضارب إلى الحمرة في قرعته أو في صلعته ، كمنظر البرص في جلد الجسد '),
(22753, 'Leviticus', 3, 13, 44, ' فهو إنسان أبرص . إنه نجس . فيحكم الكاهن بنجاسته . إن ضربته في رأسه '),
(22754, 'Leviticus', 3, 13, 45, ' والأبرص الذي فيه الضربة ، تكون ثيابه مشقوقة ، ورأسه يكون مكشوفا ، ويغطي شاربيه ، وينادي : نجس ، نجس '),
(22755, 'Leviticus', 3, 13, 46, ' كل الأيام التي تكون الضربة فيه يكون نجسا . إنه نجس . يقيم وحده . خارج المحلة يكون مقامه '),
(22756, 'Leviticus', 3, 13, 47, ' وأما الثوب فإذا كان فيه ضربة برص ، ثوب صوف أو ثوب كتان '),
(22757, 'Leviticus', 3, 13, 48, ' في السدى أو اللحمة من الصوف أو الكتان ، أو في جلد أو في كل مصنوع من جلد '),
(22758, 'Leviticus', 3, 13, 49, ' وكانت الضربة ضاربة إلى الخضرة أو إلى الحمرة في الثوب أو في الجلد ، في السدى أو اللحمة أو في متاع ما من جلد ، فإنها ضربة برص ، فتعرض على الكاهن '),
(22759, 'Leviticus', 3, 13, 50, ' فيرى الكاهن الضربة ويحجز المضروب سبعة أيام '),
(22760, 'Leviticus', 3, 13, 51, ' فمتى رأى الضربة في اليوم السابع إذا كانت الضربة قد امتدت في الثوب ، في السدى أو اللحمة أو في الجلد من كل ما يصنع من جلد للعمل ، فالضربة برص مفسد . إنها نجسة '),
(22761, 'Leviticus', 3, 13, 52, ' فيحرق الثوب أو السدى أو اللحمة من الصوف أو الكتان أو متاع الجلد الذي كانت فيه الضربة ، لأنها برص مفسد . بالنار يحرق '),
(22762, 'Leviticus', 3, 13, 53, ' لكن إن رأى الكاهن وإذا الضربة لم تمتد في الثوب في السدى أو اللحمة أو في متاع الجلد '),
(22763, 'Leviticus', 3, 13, 54, ' يأمر الكاهن أن يغسلوا ما فيه الضربة ، ويحجزه سبعة أيام ثانية '),
(22764, 'Leviticus', 3, 13, 55, ' فإن رأى الكاهن بعد غسل المضروب وإذا الضربة لم تغير منظرها ، ولا امتدت الضربة ، فهو نجس . بالنار تحرقه . إنها نخروب في جردة باطنه أو ظاهره '),
(22765, 'Leviticus', 3, 13, 56, ' لكن إن رأى الكاهن وإذا الضربة كامدة اللون بعد غسله ، يمزقها من الثوب أو الجلد من السدى أو اللحمة '),
(22766, 'Leviticus', 3, 13, 57, ' ثم إن ظهرت أيضا في الثوب في السدى أو اللحمة أو في متاع الجلد فهي مفرخة . بالنار تحرق ما فيه الضربة '),
(22767, 'Leviticus', 3, 13, 58, ' وأما الثوب ، السدى أو اللحمة أو متاع الجلد الذي تغسله وتزول منه الضربة ، فيغسل ثانية فيطهر '),
(22768, 'Leviticus', 3, 13, 59, ' هذه شريعة ضربة البرص في الصوف أو الكتان ، في السدى أو اللحمة أو في كل متاع من جلد ، للحكم بطهارته أو نجاسته '),
(22769, 'Leviticus', 3, 14, 1, ' وكلم الرب موسى قائلا '),
(22770, 'Leviticus', 3, 14, 2, ' هذه تكون شريعة الأبرص : يوم طهره ، يؤتى به إلى الكاهن '),
(22771, 'Leviticus', 3, 14, 3, ' ويخرج الكاهن إلى خارج المحلة ، فإن رأى الكاهن وإذا ضربة البرص قد برئت من الأبرص '),
(22772, 'Leviticus', 3, 14, 4, ' يأمر الكاهن أن يؤخذ للمتطهر عصفوران حيان طاهران ، وخشب أرز وقرمز وزوفا '),
(22773, 'Leviticus', 3, 14, 5, ' ويأمر الكاهن أن يذبح العصفور الواحد في إناء خزف على ماء حي '),
(22774, 'Leviticus', 3, 14, 6, ' أما العصفور الحي فيأخذه مع خشب الأرز والقرمز والزوفا ويغمسها مع العصفور الحي في دم العصفور المذبوح على الماء الحي '),
(22775, 'Leviticus', 3, 14, 7, ' وينضح على المتطهر من البرص سبع مرات فيطهره ، ثم يطلق العصفور الحي على وجه الصحراء '),
(22776, 'Leviticus', 3, 14, 8, ' فيغسل المتطهر ثيابه ويحلق كل شعره ويستحم بماء فيطهر . ثم يدخل المحلة ، لكن يقيم خارج خيمته سبعة أيام '),
(22777, 'Leviticus', 3, 14, 9, ' وفي اليوم السابع يحلق كل شعره : رأسه ولحيته وحواجب عينيه وجميع شعره يحلق . ويغسل ثيابه ويرحض جسده بماء فيطهر '),
(22778, 'Leviticus', 3, 14, 10, ' ثم في اليوم الثامن يأخذ خروفين صحيحين ونعجة واحدة حولية صحيحة وثلاثة أعشار دقيق تقدمة ملتوتة بزيت ولج زيت '),
(22779, 'Leviticus', 3, 14, 11, ' فيوقف الكاهن المطهر الإنسان المتطهر وإياها أمام الرب لدى باب خيمة الاجتماع '),
(22780, 'Leviticus', 3, 14, 12, ' ثم يأخذ الكاهن الخروف الواحد ويقربه ذبيحة إثم مع لج الزيت . يرددهما ترديدا أمام الرب '),
(22781, 'Leviticus', 3, 14, 13, ' ويذبح الخروف في الموضع الذي يذبح فيه ذبيحة الخطية والمحرقة في المكان المقدس ، لأن ذبيحة الإثم كذبيحة الخطية للكاهن . إنها قدس أقداس '),
(22782, 'Leviticus', 3, 14, 14, ' ويأخذ الكاهن من دم ذبيحة الإثم ويجعل الكاهن على شحمة أذن المتطهر اليمنى ، وعلى إبهام يده اليمنى ، وعلى إبهام رجله اليمنى '),
(22783, 'Leviticus', 3, 14, 15, ' ويأخذ الكاهن من لج الزيت ويصب في كف الكاهن اليسرى '),
(22784, 'Leviticus', 3, 14, 16, ' ويغمس الكاهن إصبعه اليمنى في الزيت الذي على كفه اليسرى ، وينضح من الزيت بإصبعه سبع مرات أمام الرب '),
(22785, 'Leviticus', 3, 14, 17, ' ومما فضل من الزيت الذي في كفه يجعل الكاهن على شحمة أذن المتطهر اليمنى ، وعلى إبهام يده اليمنى ، وعلى إبهام رجله اليمنى ، على دم ذبيحة الإثم '),
(22786, 'Leviticus', 3, 14, 18, ' والفاضل من الزيت الذي في كف الكاهن يجعله على رأس المتطهر ، ويكفر عنه الكاهن أمام الرب '),
(22787, 'Leviticus', 3, 14, 19, ' ثم يعمل الكاهن ذبيحة الخطية ويكفر عن المتطهر من نجاسته . ثم يذبح المحرقة '),
(22788, 'Leviticus', 3, 14, 20, ' ويصعد الكاهن المحرقة والتقدمة على المذبح ويكفر عنه الكاهن فيطهر '),
(22789, 'Leviticus', 3, 14, 21, ' لكن إن كان فقيرا ولا تنال يده ، يأخذ خروفا واحدا ذبيحة إثم لترديد ، تكفيرا عنه ، وعشرا واحدا من دقيق ملتوت بزيت لتقدمة ، ولج زيت '),
(22790, 'Leviticus', 3, 14, 22, ' ويمامتين أو فرخي حمام كما تنال يده ، فيكون الواحد ذبيحة خطية ، والآخر محرقة '),
(22791, 'Leviticus', 3, 14, 23, ' ويأتي بها في اليوم الثامن لطهره إلى الكاهن ، إلى باب خيمة الاجتماع أمام الرب '),
(22792, 'Leviticus', 3, 14, 24, ' فيأخذ الكاهن كبش الإثم ولج الزيت ، ويرددهما الكاهن ترديدا أمام الرب '),
(22793, 'Leviticus', 3, 14, 25, ' ثم يذبح كبش الإثم ، ويأخذ الكاهن من دم ذبيحة الإثم ويجعل على شحمة أذن المتطهر اليمنى ، وعلى إبهام يده اليمنى ، وعلى إبهام رجله اليمنى '),
(22794, 'Leviticus', 3, 14, 26, ' ويصب الكاهن من الزيت في كف الكاهن اليسرى '),
(22795, 'Leviticus', 3, 14, 27, ' وينضح الكاهن بإصبعه اليمنى من الزيت الذي في كفه اليسرى سبع مرات أمام الرب '),
(22796, 'Leviticus', 3, 14, 28, ' ويجعل الكاهن من الزيت الذي في كفه على شحمة أذن المتطهر اليمنى ، وعلى إبهام يده اليمنى ، وعلى إبهام رجله اليمنى ، على موضع دم ذبيحة الإثم '),
(22797, 'Leviticus', 3, 14, 29, ' والفاضل من الزيت الذي في كف الكاهن يجعله على رأس المتطهر تكفيرا عنه أمام الرب '),
(22798, 'Leviticus', 3, 14, 30, ' ثم يعمل واحدة من اليمامتين أو من فرخي الحمام ، مما تنال يده '),
(22799, 'Leviticus', 3, 14, 31, ' ما تنال يده : الواحد ذبيحة خطية ، والآخر محرقة مع التقدمة . ويكفر الكاهن عن المتطهر أمام الرب '),
(22800, 'Leviticus', 3, 14, 32, ' هذه شريعة الذي فيه ضربة برص الذي لا تنال يده في تطهيره '),
(22801, 'Leviticus', 3, 14, 33, ' وكلم الرب موسى وهارون قائلا '),
(22802, 'Leviticus', 3, 14, 34, ' متى جئتم إلى أرض كنعان التي أعطيكم ملكا ، وجعلت ضربة برص في بيت في أرض ملككم '),
(22803, 'Leviticus', 3, 14, 35, ' يأتي الذي له البيت ، ويخبر الكاهن قائلا : قد ظهر لي شبه ضربة في البيت '),
(22804, 'Leviticus', 3, 14, 36, ' فيأمر الكاهن أن يفرغوا البيت قبل دخول الكاهن ليرى الضربة ، لئلا يتنجس كل ما في البيت . وبعد ذلك يدخل الكاهن ليرى البيت '),
(22805, 'Leviticus', 3, 14, 37, ' فإذا رأى الضربة ، وإذا الضربة في حيطان البيت نقر ضاربة إلى الخضرة أو إلى الحمرة ، ومنظرها أعمق من الحائط '),
(22806, 'Leviticus', 3, 14, 38, ' يخرج الكاهن من البيت إلى باب البيت ، ويغلق البيت سبعة أيام '),
(22807, 'Leviticus', 3, 14, 39, ' فإذا رجع الكاهن في اليوم السابع ورأى وإذا الضربة قد امتدت في حيطان البيت '),
(22808, 'Leviticus', 3, 14, 40, ' يأمر الكاهن أن يقلعوا الحجارة التي فيها الضربة ويطرحوها خارج المدينة في مكان نجس '),
(22809, 'Leviticus', 3, 14, 41, ' ويقشر البيت من داخل حواليه ، ويطرحون التراب الذي يقشرونه خارج المدينة في مكان نجس '),
(22810, 'Leviticus', 3, 14, 42, ' ويأخذون حجارة أخرى ويدخلونها في مكان الحجارة ، ويأخذ ترابا آخر ويطين البيت '),
(22811, 'Leviticus', 3, 14, 43, ' فإن رجعت الضربة وأفرخت في البيت بعد قلع الحجارة وقشر البيت وتطيينه '),
(22812, 'Leviticus', 3, 14, 44, ' وأتى الكاهن ورأى وإذا الضربة قد امتدت في البيت ، فهي برص مفسد في البيت . إنه نجس '),
(22813, 'Leviticus', 3, 14, 45, ' فيهدم البيت : حجارته وأخشابه وكل تراب البيت ، ويخرجها إلى خارج المدينة إلى مكان نجس '),
(22814, 'Leviticus', 3, 14, 46, ' ومن دخل إلى البيت في كل أيام انغلاقه ، يكون نجسا إلى المساء '),
(22815, 'Leviticus', 3, 14, 47, ' ومن نام في البيت يغسل ثيابه . ومن أكل في البيت يغسل ثيابه '),
(22816, 'Leviticus', 3, 14, 48, ' لكن إن أتى الكاهن ورأى وإذا الضربة لم تمتد في البيت بعد تطيين البيت ، يطهر الكاهن البيت . لأن الضربة قد برئت '),
(22817, 'Leviticus', 3, 14, 49, ' فيأخذ لتطهير البيت عصفورين وخشب أرز وقرمزا وزوفا '),
(22818, 'Leviticus', 3, 14, 50, ' ويذبح العصفور الواحد في إناء خزف على ماء حي '),
(22819, 'Leviticus', 3, 14, 51, ' ويأخذ خشب الأرز والزوفا والقرمز والعصفور الحي ويغمسها في دم العصفور المذبوح وفي الماء الحي ، وينضح البيت سبع مرات '),
(22820, 'Leviticus', 3, 14, 52, ' ويطهر البيت بدم العصفور وبالماء الحي وبالعصفور الحي وبخشب الأرز وبالزوفا وبالقرمز '),
(22821, 'Leviticus', 3, 14, 53, ' ثم يطلق العصفور الحي إلى خارج المدينة على وجه الصحراء ويكفر عن البيت فيطهر '),
(22822, 'Leviticus', 3, 14, 54, ' هذه هي الشريعة لكل ضربة من البرص وللقرع '),
(22823, 'Leviticus', 3, 14, 55, ' ولبرص الثوب والبيت '),
(22824, 'Leviticus', 3, 14, 56, ' وللناتئ وللقوباء وللمعة '),
(22825, 'Leviticus', 3, 14, 57, ' للتعليم في يوم النجاسة ويوم الطهارة . هذه شريعة البرص '),
(22826, 'Leviticus', 3, 15, 1, ' وكلم الرب موسى وهارون قائلا '),
(22827, 'Leviticus', 3, 15, 2, ' كلما بني إسرائيل وقولا لهم : كل رجل يكون له سيل من لحمه ، فسيله نجس '),
(22828, 'Leviticus', 3, 15, 3, ' وهذه تكون نجاسته بسيله : إن كان لحمه يبصق سيله ، أو يحتبس لحمه عن سيله ، فذلك نجاسته '),
(22829, 'Leviticus', 3, 15, 4, ' كل فراش يضطجع عليه الذي له السيل يكون نجسا ، وكل متاع يجلس عليه يكون نجسا '),
(22830, 'Leviticus', 3, 15, 5, ' ومن مس فراشه يغسل ثيابه ويستحم بماء ، ويكون نجسا إلى المساء '),
(22831, 'Leviticus', 3, 15, 6, ' ومن جلس على المتاع الذي يجلس عليه ذو السيل ، يغسل ثيابه ويستحم بماء ، ويكون نجسا إلى المساء '),
(22832, 'Leviticus', 3, 15, 7, ' ومن مس لحم ذي السيل يغسل ثيابه ويستحم بماء ، ويكون نجسا إلى المساء '),
(22833, 'Leviticus', 3, 15, 8, ' وإن بصق ذو السيل على طاهر ، يغسل ثيابه ويستحم بماء ، ويكون نجسا إلى المساء '),
(22834, 'Leviticus', 3, 15, 9, ' وكل ما يركب عليه ذو السيل يكون نجسا '),
(22835, 'Leviticus', 3, 15, 10, ' وكل من مس كل ما كان تحته يكون نجسا إلى المساء ، ومن حملهن يغسل ثيابه ويستحم بماء ، ويكون نجسا إلى المساء '),
(22836, 'Leviticus', 3, 15, 11, ' وكل من مسه ذو السيل ولم يغسل يديه بماء ، يغسل ثيابه ويستحم بماء ويكون نجسا إلى المساء '),
(22837, 'Leviticus', 3, 15, 12, ' وإناء الخزف الذي يمسه ذو السيل يكسر . وكل إناء خشب يغسل بماء '),
(22838, 'Leviticus', 3, 15, 13, ' وإذا طهر ذو السيل من سيله ، يحسب له سبعة أيام لطهره ، ويغسل ثيابه ويرحض جسده بماء حي فيطهر '),
(22839, 'Leviticus', 3, 15, 14, ' وفي اليوم الثامن يأخذ لنفسه يمامتين أو فرخي حمام ، ويأتي إلى أمام الرب ، إلى باب خيمة الاجتماع ، ويعطيهما للكاهن '),
(22840, 'Leviticus', 3, 15, 15, ' فيعملهما الكاهن : الواحد ذبيحة خطية ، والآخر محرقة . ويكفر عنه الكاهن أمام الرب من سيله '),
(22841, 'Leviticus', 3, 15, 16, ' وإذا حدث من رجل اضطجاع زرع ، يرحض كل جسده بماء ، ويكون نجسا إلى المساء '),
(22842, 'Leviticus', 3, 15, 17, ' وكل ثوب وكل جلد يكون عليه اضطجاع زرع يغسل بماء ، ويكون نجسا إلى المساء '),
(22843, 'Leviticus', 3, 15, 18, ' والمرأة التي يضطجع معها رجل اضطجاع زرع ، يستحمان بماء ، ويكونان نجسين إلى المساء '),
(22844, 'Leviticus', 3, 15, 19, ' وإذا كانت امرأة لها سيل ، وكان سيلها دما في لحمها ، فسبعة أيام تكون في طمثها . وكل من مسها يكون نجسا إلى المساء '),
(22845, 'Leviticus', 3, 15, 20, ' وكل ما تضطجع عليه في طمثها يكون نجسا ، وكل ما تجلس عليه يكون نجسا '),
(22846, 'Leviticus', 3, 15, 21, ' وكل من مس فراشها يغسل ثيابه ويستحم بماء ، ويكون نجسا إلى المساء '),
(22847, 'Leviticus', 3, 15, 22, ' وكل من مس متاعا تجلس عليه ، يغسل ثيابه ويستحم بماء ، ويكون نجسا إلى المساء '),
(22848, 'Leviticus', 3, 15, 23, ' وإن كان على الفراش أو على المتاع الذي هي جالسة عليه عندما يمسه ، يكون نجسا إلى المساء '),
(22849, 'Leviticus', 3, 15, 24, ' وإن اضطجع معها رجل فكان طمثها عليه يكون نجسا سبعة أيام . وكل فراش يضطجع عليه يكون نجسا '),
(22850, 'Leviticus', 3, 15, 25, ' وإذا كانت امرأة يسيل سيل دمها أياما كثيرة في غير وقت طمثها ، أو إذا سال بعد طمثها ، فتكون كل أيام سيلان نجاستها كما في أيام طمثها . إنها نجسة '),
(22851, 'Leviticus', 3, 15, 26, ' كل فراش تضطجع عليه كل أيام سيلها يكون لها كفراش طمثها . وكل الأمتعة التي تجلس عليها تكون نجسة كنجاسة طمثها '),
(22852, 'Leviticus', 3, 15, 27, ' وكل من مسهن يكون نجسا ، فيغسل ثيابه ويستحم بماء ، ويكون نجسا إلى المساء '),
(22853, 'Leviticus', 3, 15, 28, ' وإذا طهرت من سيلها تحسب ، لنفسها سبعة أيام ثم تطهر '),
(22854, 'Leviticus', 3, 15, 29, ' وفي اليوم الثامن تأخذ لنفسها يمامتين أو فرخي حمام ، وتأتي بهما إلى الكاهن إلى باب خيمة الاجتماع '),
(22855, 'Leviticus', 3, 15, 30, ' فيعمل الكاهن : الواحد ذبيحة خطية ، والآخر محرقة . ويكفر عنها الكاهن أمام الرب من سيل نجاستها '),
(22856, 'Leviticus', 3, 15, 31, ' فتعزلان بني إسرائيل عن نجاستهم لئلا يموتوا في نجاستهم بتنجيسهم مسكني الذي في وسطهم '),
(22857, 'Leviticus', 3, 15, 32, ' هذه شريعة ذي السيل ، والذي يحدث منه اضطجاع زرع فيتنجس بها '),
(22858, 'Leviticus', 3, 15, 33, ' والعليلة في طمثها ، والسائل سيله : الذكر والأنثى ، والرجل الذي يضطجع مع نجسة '),
(22859, 'Leviticus', 3, 16, 1, ' وكلم الرب موسى بعد موت ابني هارون عندما اقتربا أمام الرب وماتا '),
(22860, 'Leviticus', 3, 16, 2, ' وقال الرب لموسى : كلم هارون أخاك أن لا يدخل كل وقت إلى القدس داخل الحجاب أمام الغطاء الذي على التابوت لئلا يموت ، لأني في السحاب أتراءى على الغطاء '),
(22861, 'Leviticus', 3, 16, 3, ' بهذا يدخل هارون إلى القدس : بثور ابن بقر لذبيحة خطية ، وكبش لمحرقة '),
(22862, 'Leviticus', 3, 16, 4, ' يلبس قميص كتان مقدسا ، وتكون سراويل كتان على جسده ، ويتنطق بمنطقة كتان ، ويتعمم بعمامة كتان . إنها ثياب مقدسة . فيرحض جسده بماء ويلبسها '),
(22863, 'Leviticus', 3, 16, 5, ' ومن جماعة بني إسرائيل يأخذ تيسين من المعز لذبيحة خطية ، وكبشا واحدا لمحرقة '),
(22864, 'Leviticus', 3, 16, 6, ' ويقرب هارون ثور الخطية الذي له ، ويكفر عن نفسه وعن بيته '),
(22865, 'Leviticus', 3, 16, 7, ' ويأخذ التيسين ويوقفهما أمام الرب لدى باب خيمة الاجتماع '),
(22866, 'Leviticus', 3, 16, 8, ' ويلقي هارون على التيسين قرعتين : قرعة للرب وقرعة لعزازيل '),
(22867, 'Leviticus', 3, 16, 9, ' ويقرب هارون التيس الذي خرجت عليه القرعة للرب ويعمله ذبيحة خطية '),
(22868, 'Leviticus', 3, 16, 10, ' وأما التيس الذي خرجت عليه القرعة لعزازيل فيوقف حيا أمام الرب ، ليكفر عنه ليرسله إلى عزازيل إلى البرية '),
(22869, 'Leviticus', 3, 16, 11, ' ويقدم هارون ثور الخطية الذي له ويكفر عن نفسه وعن بيته ، ويذبح ثور الخطية الذي له '),
(22870, 'Leviticus', 3, 16, 12, ' ويأخذ ملء المجمرة جمر نار عن المذبح من أمام الرب ، وملء راحتيه بخورا عطرا دقيقا ، ويدخل بهما إلى داخل الحجاب '),
(22871, 'Leviticus', 3, 16, 13, ' ويجعل البخور على النار أمام الرب ، فتغشي سحابة البخور الغطاء الذي على الشهادة فلا يموت '),
(22872, 'Leviticus', 3, 16, 14, ' ثم يأخذ من دم الثور وينضح بإصبعه على وجه الغطاء إلى الشرق . وقدام الغطاء ينضح سبع مرات من الدم بإصبعه '),
(22873, 'Leviticus', 3, 16, 15, ' ثم يذبح تيس الخطية الذي للشعب ، ويدخل بدمه إلى داخل الحجاب . ويفعل بدمه كما فعل بدم الثور : ينضحه على الغطاء وقدام الغطاء '),
(22874, 'Leviticus', 3, 16, 16, ' فيكفر عن القدس من نجاسات بني إسرائيل ومن سيئاتهم مع كل خطاياهم . وهكذا يفعل لخيمة الاجتماع القائمة بينهم في وسط نجاساتهم '),
(22875, 'Leviticus', 3, 16, 17, ' ولا يكن إنسان في خيمة الاجتماع من دخوله للتكفير في القدس إلى خروجه ، فيكفر عن نفسه وعن بيته وعن كل جماعة إسرائيل '),
(22876, 'Leviticus', 3, 16, 18, ' ثم يخرج إلى المذبح الذي أمام الرب ويكفر عنه . يأخذ من دم الثور ومن دم التيس ويجعل على قرون المذبح مستديرا '),
(22877, 'Leviticus', 3, 16, 19, ' وينضح عليه من الدم بإصبعه سبع مرات ، ويطهره ويقدسه من نجاسات بني إسرائيل '),
(22878, 'Leviticus', 3, 16, 20, ' ومتى فرغ من التكفير عن القدس وعن خيمة الاجتماع وعن المذبح ، يقدم التيس الحي '),
(22879, 'Leviticus', 3, 16, 21, ' ويضع هارون يديه على رأس التيس الحي ويقر عليه بكل ذنوب بني إسرائيل ، وكل سيئاتهم مع كل خطاياهم ، ويجعلها على رأس التيس ، ويرسله بيد من يلاقيه إلى البرية '),
(22880, 'Leviticus', 3, 16, 22, ' ليحمل التيس عليه كل ذنوبهم إلى أرض مقفرة ، فيطلق التيس في البرية '),
(22881, 'Leviticus', 3, 16, 23, ' ثم يدخل هارون إلى خيمة الاجتماع ويخلع ثياب الكتان التي لبسها عند دخوله إلى القدس ويضعها هناك '),
(22882, 'Leviticus', 3, 16, 24, ' ويرحض جسده بماء في مكان مقدس ، ثم يلبس ثيابه ويخرج ويعمل محرقته ومحرقة الشعب ، ويكفر عن نفسه وعن الشعب '),
(22883, 'Leviticus', 3, 16, 25, ' وشحم ذبيحة الخطية يوقده على المذبح '),
(22884, 'Leviticus', 3, 16, 26, ' والذي أطلق التيس إلى عزازيل يغسل ثيابه ويرحض جسده بماء ، وبعد ذلك يدخل إلى المحلة '),
(22885, 'Leviticus', 3, 16, 27, ' وثور الخطية وتيس الخطية اللذان أتي بدمهما للتكفير في القدس يخرجهما إلى خارج المحلة ، ويحرقون بالنار جلديهما ولحمهما وفرثهما '),
(22886, 'Leviticus', 3, 16, 28, ' والذي يحرقهما يغسل ثيابه ويرحض جسده بماء ، وبعد ذلك يدخل إلى المحلة '),
(22887, 'Leviticus', 3, 16, 29, ' ويكون لكم فريضة دهرية ، أنكم في الشهر السابع في عاشر الشهر تذللون نفوسكم ، وكل عمل لا تعملون : الوطني والغريب النازل في وسطكم '),
(22888, 'Leviticus', 3, 16, 30, ' لأنه في هذا اليوم يكفر عنكم لتطهيركم . من جميع خطاياكم أمام الرب تطهرون '),
(22889, 'Leviticus', 3, 16, 31, ' سبت عطلة هو لكم ، وتذللون نفوسكم فريضة دهرية '),
(22890, 'Leviticus', 3, 16, 32, ' ويكفر الكاهن الذي يمسحه ، والذي يملأ يده للكهانة عوضا عن أبيه . يلبس ثياب الكتان ، الثياب المقدسة '),
(22891, 'Leviticus', 3, 16, 33, ' ويكفر عن مقدس القدس . وعن خيمة الاجتماع والمذبح يكفر . وعن الكهنة وكل شعب الجماعة يكفر '),
(22892, 'Leviticus', 3, 16, 34, ' وتكون هذه لكم فريضة دهرية للتكفير عن بني إسرائيل من جميع خطاياهم مرة في السنة . ففعل كما أمر الرب موسى '),
(22893, 'Leviticus', 3, 17, 1, ' وكلم الرب موسى قائلا '),
(22894, 'Leviticus', 3, 17, 2, ' كلم هارون وبنيه وجميع بني إسرائيل وقل لهم : هذا هو الأمر الذي يوصي به الرب قائلا '),
(22895, 'Leviticus', 3, 17, 3, ' كل إنسان من بيت إسرائيل يذبح بقرا أو غنما أو معزى في المحلة ، أو يذبح خارج المحلة '),
(22896, 'Leviticus', 3, 17, 4, ' وإلى باب خيمة الاجتماع لا يأتي به ليقرب قربانا للرب أمام مسكن الرب ، يحسب على ذلك الإنسان دم . قد سفك دما . فيقطع ذلك الإنسان من شعبه '),
(22897, 'Leviticus', 3, 17, 5, ' لكي يأتي بنو إسرائيل بذبائحهم التي يذبحونها على وجه الصحراء ويقدموها للرب إلى باب خيمة الاجتماع إلى الكاهن ، ويذبحوها ذبائح سلامة للرب '),
(22898, 'Leviticus', 3, 17, 6, ' ويرش الكاهن الدم على مذبح الرب لدى باب خيمة الاجتماع ، ويوقد الشحم لرائحة سرور للرب '),
(22899, 'Leviticus', 3, 17, 7, ' ولا يذبحوا بعد ذبائحهم للتيوس التي هم يزنون وراءها . فريضة دهرية تكون هذه لهم في أجيالهم '),
(22900, 'Leviticus', 3, 17, 8, ' وتقول لهم : كل إنسان من بيت إسرائيل ومن الغرباء الذين ينزلون في وسطكم يصعد محرقة أو ذبيحة '),
(22901, 'Leviticus', 3, 17, 9, ' ولا يأتي بها إلى باب خيمة الاجتماع ليصنعها للرب ، يقطع ذلك الإنسان من شعبه '),
(22902, 'Leviticus', 3, 17, 10, ' وكل إنسان من بيت إسرائيل ومن الغرباء النازلين في وسطكم يأكل دما ، أجعل وجهي ضد النفس الآكلة الدم وأقطعها من شعبها '),
(22903, 'Leviticus', 3, 17, 11, ' لأن نفس الجسد هي في الدم ، فأنا أعطيتكم إياه على المذبح للتكفير عن نفوسكم ، لأن الدم يكفر عن النفس '),
(22904, 'Leviticus', 3, 17, 12, ' لذلك قلت لبني إسرائيل : لا تأكل نفس منكم دما ، ولا يأكل الغريب النازل في وسطكم دما '),
(22905, 'Leviticus', 3, 17, 13, ' وكل إنسان من بني إسرائيل ومن الغرباء النازلين في وسطكم يصطاد صيدا ، وحشا أو طائرا يؤكل ، يسفك دمه ويغطيه بالتراب '),
(22906, 'Leviticus', 3, 17, 14, ' لأن نفس كل جسد دمه هو بنفسه ، فقلت لبني إسرائيل : لا تأكلوا دم جسد ما ، لأن نفس كل جسد هي دمه . كل من أكله يقطع '),
(22907, 'Leviticus', 3, 17, 15, ' وكل إنسان يأكل ميتة أو فريسة ، وطنيا كان أو غريبا ، يغسل ثيابه ويستحم بماء ، ويبقى نجسا إلى المساء ثم يكون طاهرا '),
(22908, 'Leviticus', 3, 17, 16, ' وإن لم يغسل ولم يرحض جسده يحمل ذنبه '),
(22909, 'Leviticus', 3, 18, 1, ' وكلم الرب موسى قائلا '),
(22910, 'Leviticus', 3, 18, 2, ' كلم بني إسرائيل وقل لهم : أنا الرب إلهكم '),
(22911, 'Leviticus', 3, 18, 3, ' مثل عمل أرض مصر التي سكنتم فيها لا تعملوا ، ومثل عمل أرض كنعان التي أنا آت بكم إليها لا تعملوا ، وحسب فرائضهم لا تسلكوا '),
(22912, 'Leviticus', 3, 18, 4, ' أحكامي تعملون ، وفرائضي تحفظون لتسلكوا فيها . أنا الرب إلهكم '),
(22913, 'Leviticus', 3, 18, 5, ' فتحفظون فرائضي وأحكامي ، التي إذا فعلها الإنسان يحيا بها . أنا الرب '),
(22914, 'Leviticus', 3, 18, 6, ' لا يقترب إنسان إلى قريب جسده ليكشف العورة . أنا الرب '),
(22915, 'Leviticus', 3, 18, 7, ' عورة أبيك وعورة أمك لا تكشف . إنها أمك لا تكشف عورتها '),
(22916, 'Leviticus', 3, 18, 8, ' عورة امرأة أبيك لا تكشف . إنها عورة أبيك '),
(22917, 'Leviticus', 3, 18, 9, ' عورة أختك بنت أبيك أو بنت أمك ، المولودة في البيت أو المولودة خارجا ، لا تكشف عورتها '),
(22918, 'Leviticus', 3, 18, 10, ' عورة ابنة ابنك ، أو ابنة بنتك لا تكشف عورتها . إنها عورتك '),
(22919, 'Leviticus', 3, 18, 11, ' عورة بنت امرأة أبيك المولودة من أبيك لا تكشف عورتها . إنها أختك '),
(22920, 'Leviticus', 3, 18, 12, ' عورة أخت أبيك لا تكشف . إنها قريبة أبيك '),
(22921, 'Leviticus', 3, 18, 13, ' عورة أخت أمك لا تكشف . إنها قريبة أمك '),
(22922, 'Leviticus', 3, 18, 14, ' عورة أخي أبيك لا تكشف . إلى امرأته لا تقترب . إنها عمتك '),
(22923, 'Leviticus', 3, 18, 15, ' عورة كنتك لا تكشف . إنها امرأة ابنك . لا تكشف عورتها '),
(22924, 'Leviticus', 3, 18, 16, ' عورة امرأة أخيك لا تكشف . إنها عورة أخيك '),
(22925, 'Leviticus', 3, 18, 17, ' عورة امرأة وبنتها لا تكشف . ولا تأخذ ابنة ابنها ، أو ابنة بنتها لتكشف عورتها . إنهما قريبتاها . إنه رذيلة '),
(22926, 'Leviticus', 3, 18, 18, ' ولا تأخذ امرأة على أختها للضر لتكشف عورتها معها في حياتها '),
(22927, 'Leviticus', 3, 18, 19, ' ولا تقترب إلى امرأة في نجاسة طمثها لتكشف عورتها '),
(22928, 'Leviticus', 3, 18, 20, ' ولا تجعل مع امرأة صاحبك مضجعك لزرع ، فتتنجس بها '),
(22929, 'Leviticus', 3, 18, 21, ' ولا تعط من زرعك للإجازة لمولك لئلا تدنس اسم إلهك . أنا الرب '),
(22930, 'Leviticus', 3, 18, 22, ' ولا تضاجع ذكرا مضاجعة امرأة . إنه رجس '),
(22931, 'Leviticus', 3, 18, 23, ' ولا تجعل مع بهيمة مضجعك فتتنجس بها . ولا تقف امرأة أمام بهيمة لنزائها . إنه فاحشة '),
(22932, 'Leviticus', 3, 18, 24, ' بكل هذه لا تتنجسوا ، لأنه بكل هذه قد تنجس الشعوب الذين أنا طاردهم من أمامكم '),
(22933, 'Leviticus', 3, 18, 25, ' فتنجست الأرض . فأجتزي ذنبها منها ، فتقذف الأرض سكانها '),
(22934, 'Leviticus', 3, 18, 26, ' لكن تحفظون أنتم فرائضي وأحكامي ، ولا تعملون شيئا من جميع هذه الرجسات ، لا الوطني ولا الغريب النازل في وسطكم '),
(22935, 'Leviticus', 3, 18, 27, ' لأن جميع هذه الرجسات قد عملها أهل الأرض الذين قبلكم فتنجست الأرض '),
(22936, 'Leviticus', 3, 18, 28, ' فلا تقذفكم الأرض بتنجيسكم إياها كما قذفت الشعوب التي قبلكم '),
(22937, 'Leviticus', 3, 18, 29, ' بل كل من عمل شيئا من جميع هذه الرجسات تقطع الأنفس التي تعملها من شعبها '),
(22938, 'Leviticus', 3, 18, 30, ' فتحفظون شعائري لكي لا تعملوا شيئا من الرسوم الرجسة التي عملت قبلكم ولا تتنجسوا بها . أنا الرب إلهكم '),
(22939, 'Leviticus', 3, 19, 1, ' وكلم الرب موسى قائلا '),
(22940, 'Leviticus', 3, 19, 2, ' كلم كل جماعة بني إسرائيل وقل لهم : تكونون قديسين لأني قدوس الرب إلهكم '),
(22941, 'Leviticus', 3, 19, 3, ' تهابون كل إنسان أمه وأباه ، وتحفظون سبوتي . أنا الرب إلهكم '),
(22942, 'Leviticus', 3, 19, 4, ' لا تلتفتوا إلى الأوثان ، وآلهة مسبوكة لا تصنعوا لأنفسكم . أنا الرب إلهكم '),
(22943, 'Leviticus', 3, 19, 5, ' ومتى ذبحتم ذبيحة سلامة للرب فللرضا عنكم تذبحونها '),
(22944, 'Leviticus', 3, 19, 6, ' يوم تذبحونها تؤكل ، وفي الغد . والفاضل إلى اليوم الثالث يحرق بالنار '),
(22945, 'Leviticus', 3, 19, 7, ' وإذا أكلت في اليوم الثالث فذلك نجاسة لا يرضى به '),
(22946, 'Leviticus', 3, 19, 8, ' ومن أكل منها يحمل ذنبه لأنه قد دنس قدس الرب . فتقطع تلك النفس من شعبها '),
(22947, 'Leviticus', 3, 19, 9, ' وعندما تحصدون حصيد أرضكم لا تكمل زوايا حقلك في الحصاد . ولقاط حصيدك لاتلتقط '),
(22948, 'Leviticus', 3, 19, 10, ' وكرمك لا تعلله ، ونثار كرمك لاتلتقط . للمسكين والغريب تتركه . أنا الرب إلهكم '),
(22949, 'Leviticus', 3, 19, 11, ' لا تسرقوا ، ولا تكذبوا ، ولا تغدروا أحدكم بصاحبه '),
(22950, 'Leviticus', 3, 19, 12, ' ولا تحلفوا باسمي للكذب ، فتدنس اسم إلهك . أنا الرب '),
(22951, 'Leviticus', 3, 19, 13, ' لا تغصب قريبك ولا تسلب ، ولا تبت أجرة أجير عندك إلى الغد '),
(22952, 'Leviticus', 3, 19, 14, ' لا تشتم الأصم ، وقدام الأعمى لا تجعل معثرة ، بل اخش إلهك . أنا الرب '),
(22953, 'Leviticus', 3, 19, 15, ' لا ترتكبوا جورا في القضاء . لاتأخذوا بوجه مسكين ولا تحترم وجه كبير . بالعدل تحكم لقريبك '),
(22954, 'Leviticus', 3, 19, 16, ' لا تسع في الوشاية بين شعبك . لا تقف على دم قريبك . أنا الرب '),
(22955, 'Leviticus', 3, 19, 17, ' لا تبغض أخاك في قلبك . إنذارا تنذر صاحبك ، ولا تحمل لأجله خطية '),
(22956, 'Leviticus', 3, 19, 18, ' لا تنتقم ولا تحقد على أبناء شعبك ، بل تحب قريبك كنفسك . أنا الرب '),
(22957, 'Leviticus', 3, 19, 19, ' فرائضي تحفظون . لا تنز بهائمك جنسين ، وحقلك لا تزرع صنفين ، ولا يكن عليك ثوب مصنف من صنفين '),
(22958, 'Leviticus', 3, 19, 20, ' وإذا اضطجع رجل مع امرأة اضطجاع زرع وهي أمة مخطوبة لرجل ، ولم تفد فداء ولا أعطيت حريتها ، فليكن تأديب . لا يقتلا لأنها لم تعتق '),
(22959, 'Leviticus', 3, 19, 21, ' ويأتي إلى الرب بذبيحة لإثمه إلى باب خيمة الاجتماع : كبشا ، ذبيحة إثم '),
(22960, 'Leviticus', 3, 19, 22, ' فيكفر عنه الكاهن بكبش الإثم أمام الرب من خطيته التي أخطأ ، فيصفح له عن خطيته التي أخطأ '),
(22961, 'Leviticus', 3, 19, 23, ' ومتى دخلتم الأرض وغرستم كل شجرة للطعام ، تحسبون ثمرها غرلتها . ثلاث سنين تكون لكم غلفاء . لا يؤكل منها '),
(22962, 'Leviticus', 3, 19, 24, ' وفي السنة الرابعة يكون كل ثمرها قدسا لتمجيد الرب '),
(22963, 'Leviticus', 3, 19, 25, ' وفي السنة الخامسة تأكلون ثمرها ، لتزيد لكم غلتها . أنا الرب إلهكم '),
(22964, 'Leviticus', 3, 19, 26, ' لا تأكلوا بالدم . لا تتفاءلوا ولا تعيفوا '),
(22965, 'Leviticus', 3, 19, 27, ' لا تقصروا رؤوسكم مستديرا ، ولا تفسد عارضيك '),
(22966, 'Leviticus', 3, 19, 28, ' ولا تجرحوا أجسادكم لميت . وكتابة وسم لا تجعلوا فيكم . أنا الرب '),
(22967, 'Leviticus', 3, 19, 29, ' لا تدنس ابنتك بتعريضها للزنى لئلا تزني الأرض وتمتلئ الأرض رذيلة '),
(22968, 'Leviticus', 3, 19, 30, ' سبوتي تحفظون ، ومقدسي تهابون . أنا الرب '),
(22969, 'Leviticus', 3, 19, 31, ' لا تلتفتوا إلى الجان ولا تطلبوا التوابع ، فتتنجسوا بهم . أنا الرب إلهكم '),
(22970, 'Leviticus', 3, 19, 32, ' من أمام الأشيب تقوم وتحترم وجه الشيخ ، وتخشى إلهك . أنا الرب '),
(22971, 'Leviticus', 3, 19, 33, ' وإذا نزل عندك غريب في أرضكم فلا تظلموه '),
(22972, 'Leviticus', 3, 19, 34, ' كالوطني منكم يكون لكم الغريب النازل عندكم ، وتحبه كنفسك ، لأنكم كنتم غرباء في أرض مصر . أنا الرب إلهكم '),
(22973, 'Leviticus', 3, 19, 35, ' لا ترتكبوا جورا في القضاء ، لا في القياس ، ولا في الوزن ، ولا في الكيل '),
(22974, 'Leviticus', 3, 19, 36, ' ميزان حق ، ووزنات حق ، وإيفة حق ، وهين حق تكون لكم . أنا الرب إلهكم الذي أخرجكم من أرض مصر '),
(22975, 'Leviticus', 3, 19, 37, ' فتحفظون كل فرائضي ، وكل أحكامي ، وتعملونها . أنا الرب '),
(22976, 'Leviticus', 3, 20, 1, ' وكلم الرب موسى قائلا '),
(22977, 'Leviticus', 3, 20, 2, ' وتقول لبني إسرائيل : كل إنسان من بني إسرائيل ومن الغرباء النازلين في إسرائيل أعطى من زرعه لمولك فإنه يقتل . يرجمه شعب الأرض بالحجارة '),
(22978, 'Leviticus', 3, 20, 3, ' وأجعل أنا وجهي ضد ذلك الإنسان ، وأقطعه من شعبه ، لأنه أعطى من زرعه لمولك لكي ينجس مقدسي ، ويدنس اسمي القدوس '),
(22979, 'Leviticus', 3, 20, 4, ' وإن غمض شعب الأرض أعينهم عن ذلك الإنسان عندما يعطي من زرعه لمولك ، فلم يقتلوه '),
(22980, 'Leviticus', 3, 20, 5, ' فإني أضع وجهي ضد ذلك الإنسان ، وضد عشيرته ، وأقطعه وجميع الفاجرين وراءه ، بالزنى وراء مولك من شعبهم '),
(22981, 'Leviticus', 3, 20, 6, ' والنفس التي تلتفت إلى الجان ، وإلى التوابع لتزني وراءهم ، أجعل وجهي ضد تلك النفس وأقطعها من شعبها '),
(22982, 'Leviticus', 3, 20, 7, ' فتتقدسون وتكونون قديسين ، لأني أنا الرب إلهكم '),
(22983, 'Leviticus', 3, 20, 8, ' وتحفظون فرائضي وتعملونها . أنا الرب مقدسكم '),
(22984, 'Leviticus', 3, 20, 9, ' كل إنسان سب أباه أو أمه فإنه يقتل . قد سب أباه أو أمه . دمه عليه '),
(22985, 'Leviticus', 3, 20, 10, ' وإذا زنى رجل مع امرأة ، فإذا زنى مع امرأة قريبه ، فإنه يقتل الزاني والزانية '),
(22986, 'Leviticus', 3, 20, 11, ' وإذا اضطجع رجل مع امرأة أبيه ، فقد كشف عورة أبيه . إنهما يقتلان كلاهما . دمهما عليهما '),
(22987, 'Leviticus', 3, 20, 12, ' وإذا اضطجع رجل مع كنته ، فإنهما يقتلان كلاهما . قد فعلا فاحشة . دمهما عليهما '),
(22988, 'Leviticus', 3, 20, 13, ' وإذا اضطجع رجل مع ذكر اضطجاع امرأة ، فقد فعلا كلاهما رجسا . إنهما يقتلان . دمهما عليهما '),
(22989, 'Leviticus', 3, 20, 14, ' وإذا اتخذ رجل امرأة وأمها فذلك رذيلة . بالنار يحرقونه وإياهما ، لكي لا يكون رذيلة بينكم '),
(22990, 'Leviticus', 3, 20, 15, ' وإذا جعل رجل مضجعه مع بهيمة ، فإنه يقتل ، والبهيمة تميتونها '),
(22991, 'Leviticus', 3, 20, 16, ' وإذا اقتربت امرأة إلى بهيمة لنزائها ، تميت المرأة والبهيمة . إنهما يقتلان . دمهما عليهما '),
(22992, 'Leviticus', 3, 20, 17, ' وإذا أخذ رجل أخته بنت أبيه أو بنت أمه ، ورأى عورتها ورأت هي عورته ، فذلك عار . يقطعان أمام أعين بني شعبهما . قد كشف عورة أخته . يحمل ذنبه '),
(22993, 'Leviticus', 3, 20, 18, ' وإذا اضطجع رجل مع امرأة طامث وكشف عورتها ، عرى ينبوعها وكشفت هي ينبوع دمها ، يقطعان كلاهما من شعبهما '),
(22994, 'Leviticus', 3, 20, 19, ' عورة أخت أمك ، أو أخت أبيك لا تكشف . إنه قد عرى قريبته . يحملان ذنبهما '),
(22995, 'Leviticus', 3, 20, 20, ' وإذا اضطجع رجل مع امرأة عمه فقد كشف عورة عمه . يحملان ذنبهما . يموتان عقيمين '),
(22996, 'Leviticus', 3, 20, 21, ' وإذا أخذ رجل امرأة أخيه ، فذلك نجاسة . قد كشف عورة أخيه . يكونان عقيمين '),
(22997, 'Leviticus', 3, 20, 22, ' فتحفظون جميع فرائضي وجميع أحكامي ، وتعملونها لكي لا تقذفكم الأرض التي أنا آت بكم إليها لتسكنوا فيها '),
(22998, 'Leviticus', 3, 20, 23, ' ولا تسلكون في رسوم الشعوب الذين أنا طاردهم من أمامكم . لأنهم قد فعلوا كل هذه ، فكرهتهم '),
(22999, 'Leviticus', 3, 20, 24, ' وقلت لكم : ترثون أنتم أرضهم ، وأنا أعطيكم إياها لترثوها ، أرضا تفيض لبنا وعسلا . أنا الرب إلهكم الذي ميزكم من الشعوب '),
(23000, 'Leviticus', 3, 20, 25, ' فتميزون بين البهائم الطاهرة والنجسة ، وبين الطيور النجسة والطاهرة . فلا تدنسوا نفوسكم بالبهائم والطيور ، ولا بكل ما يدب على الأرض مما ميزته لكم ليكون نجسا '),
(23001, 'Leviticus', 3, 20, 26, ' وتكونون لي قديسين لأني قدوس أنا الرب ، وقد ميزتكم من الشعوب لتكونوا لي '),
(23002, 'Leviticus', 3, 20, 27, ' وإذا كان في رجل أو امرأة جان أو تابعة فإنه يقتل . بالحجارة يرجمونه . دمه عليه '),
(23003, 'Leviticus', 3, 21, 1, ' وقال الرب لموسى : كلم الكهنة بني هارون وقل لهم : لا يتنجس أحد منكم لميت في قومه '),
(23004, 'Leviticus', 3, 21, 2, ' إلا لأقربائه الأقرب إليه : أمه وأبيه وابنه وابنته وأخيه '),
(23005, 'Leviticus', 3, 21, 3, ' وأخته العذراء القريبة إليه التي لم تصر لرجل . لأجلها يتنجس '),
(23006, 'Leviticus', 3, 21, 4, ' كزوج لا يتنجس بأهله لتدنيسه '),
(23007, 'Leviticus', 3, 21, 5, ' لا يجعلوا قرعة في رؤوسهم ، ولا يحلقوا عوارض لحاهم ، ولا يجرحوا جراحة في أجسادهم '),
(23008, 'Leviticus', 3, 21, 6, ' مقدسين يكونون لإلههم ، ولا يدنسون اسم إلههم ، لأنهم يقربون وقائد الرب طعام إلههم ، فيكونون قدسا '),
(23009, 'Leviticus', 3, 21, 7, ' امرأة زانية أو مدنسة لا يأخذوا ، ولا يأخذوا امرأة مطلقة من زوجها . لأنه مقدس لإلهه '),
(23010, 'Leviticus', 3, 21, 8, ' فتحسبه مقدسا لأنه يقرب خبز إلهك . مقدسا يكون عندك لأني قدوس أنا الرب مقدسكم '),
(23011, 'Leviticus', 3, 21, 9, ' وإذا تدنست ابنة كاهن بالزنى فقد دنست أباها . بالنار تحرق '),
(23012, 'Leviticus', 3, 21, 10, ' والكاهن الأعظم بين إخوته الذي صب على رأسه دهن المسحة ، وملئت يده ليلبس الثياب ، لا يكشف رأسه ، ولا يشق ثيابه '),
(23013, 'Leviticus', 3, 21, 11, ' ولا يأتي إلى نفس ميتة ، ولا يتنجس لأبيه أو أمه '),
(23014, 'Leviticus', 3, 21, 12, ' ولا يخرج من المقدس لئلا يدنس مقدس إلهه ، لأن إكليل دهن مسحة إلهه عليه . أنا الرب '),
(23015, 'Leviticus', 3, 21, 13, ' هذا يأخذ امرأة عذراء '),
(23016, 'Leviticus', 3, 21, 14, ' أما الأرملة والمطلقة والمدنسة والزانية فمن هؤلاء لا يأخذ ، بل يتخذ عذراء من قومه امرأة '),
(23017, 'Leviticus', 3, 21, 15, ' ولا يدنس زرعه بين شعبه لأني أنا الرب مقدسه '),
(23018, 'Leviticus', 3, 21, 16, ' وكلم الرب موسى قائلا '),
(23019, 'Leviticus', 3, 21, 17, ' كلم هارون قائلا : إذا كان رجل من نسلك في أجيالهم فيه عيب فلا يتقدم ليقرب خبز إلهه '),
(23020, 'Leviticus', 3, 21, 18, ' لأن كل رجل فيه عيب لا يتقدم . لا رجل أعمى ولا أعرج ، ولا أفطس ولا زوائدي '),
(23021, 'Leviticus', 3, 21, 19, ' ولا رجل فيه كسر رجل أو كسر يد '),
(23022, 'Leviticus', 3, 21, 20, ' ولا أحدب ولا أكشم ، ولا من في عينه بياض ، ولا أجرب ولا أكلف ، ولا مرضوض الخصى '),
(23023, 'Leviticus', 3, 21, 21, ' كل رجل فيه عيب من نسل هارون الكاهن لا يتقدم ليقرب وقائد الرب . فيه عيب لا يتقدم ليقرب خبز إلهه '),
(23024, 'Leviticus', 3, 21, 22, ' خبز إلهه من قدس الأقداس ومن القدس يأكل '),
(23025, 'Leviticus', 3, 21, 23, ' لكن إلى الحجاب لا يأتي ، وإلى المذبح لا يقترب ، لأن فيه عيبا ، لئلا يدنس مقدسي ، لأني أنا الرب مقدسهم '),
(23026, 'Leviticus', 3, 21, 24, ' فكلم موسى هارون وبنيه وكل بني إسرائيل '),
(23027, 'Leviticus', 3, 22, 1, ' وكلم الرب موسى قائلا '),
(23028, 'Leviticus', 3, 22, 2, ' كلم هارون وبنيه أن يتوقوا أقداس بني إسرائيل التي يقدسونها لي ولا يدنسوا اسمي القدوس . أنا الرب '),
(23029, 'Leviticus', 3, 22, 3, ' قل لهم : في أجيالكم كل إنسان من جميع نسلكم اقترب إلى الأقداس التي يقدسها بنو إسرائيل للرب ، ونجاسته عليه ، تقطع تلك النفس من أمامي . أنا الرب '),
(23030, 'Leviticus', 3, 22, 4, ' كل إنسان من نسل هارون وهو أبرص أو ذو سيل ، لا يأكل من الأقداس حتى يطهر . ومن مس شيئا نجسا لميت ، أو إنسان حدث منه اضطجاع زرع '),
(23031, 'Leviticus', 3, 22, 5, ' أو إنسان مس دبيبا يتنجس به ، أو إنسانا يتنجس به لنجاسة فيه '),
(23032, 'Leviticus', 3, 22, 6, ' فالذي يمس ذلك يكون نجسا إلى المساء ، ولا يأكل من الأقداس ، بل يرحض جسده بماء '),
(23033, 'Leviticus', 3, 22, 7, ' فمتى غربت الشمس يكون طاهرا ، ثم يأكل من الأقداس لأنها طعامه '),
(23034, 'Leviticus', 3, 22, 8, ' ميتة أو فريسة لا يأكل فيتنجس بها . أنا الرب '),
(23035, 'Leviticus', 3, 22, 9, ' فيحفظون شعائري لكي لا يحملوا لأجلها خطية يموتون بها لأنهم يدنسونها . أنا الرب مقدسهم '),
(23036, 'Leviticus', 3, 22, 10, ' وكل أجنبي لا يأكل قدسا . نزيل كاهن وأجيره لا يأكلون قدسا '),
(23037, 'Leviticus', 3, 22, 11, ' لكن إذا اشترى كاهن أحدا شراء فضة ، فهو يأكل منه ، والمولود في بيته . هما يأكلان من طعامه '),
(23038, 'Leviticus', 3, 22, 12, ' وإذا صارت ابنة كاهن لرجل أجنبي لا تأكل من رفيعة الأقداس '),
(23039, 'Leviticus', 3, 22, 13, ' وأما ابنة كاهن قد صارت أرملة أو مطلقة ، ولم يكن لها نسل ، ورجعت إلى بيت أبيها كما في صباها ، فتأكل من طعام أبيها . لكن كل أجنبي لا يأكل منه '),
(23040, 'Leviticus', 3, 22, 14, ' وإذا أكل إنسان قدسا سهوا ، يزيد عليه خمسه ويدفع القدس للكاهن '),
(23041, 'Leviticus', 3, 22, 15, ' فلا يدنسون أقداس بني إسرائيل التي يرفعونها للرب '),
(23042, 'Leviticus', 3, 22, 16, ' فيحملونهم ذنب إثم بأكلهم أقداسهم . لأني أنا الرب مقدسهم '),
(23043, 'Leviticus', 3, 22, 17, ' وكلم الرب موسى قائلا '),
(23044, 'Leviticus', 3, 22, 18, ' كلم هارون وبنيه وجميع بني إسرائيل وقل لهم : كل إنسان من بيت إسرائيل ومن الغرباء في إسرائيل ، قرب قربانه من جميع نذورهم وجميع نوافلهم التي يقربونها للرب محرقة '),
(23045, 'Leviticus', 3, 22, 19, ' فللرضا عنكم يكون ذكرا صحيحا من البقر أو الغنم أو المعز '),
(23046, 'Leviticus', 3, 22, 20, ' كل ما كان فيه عيب لا تقربوه لأنه لا يكون للرضا عنكم '),
(23047, 'Leviticus', 3, 22, 21, ' وإذا قرب إنسان ذبيحة سلامة للرب وفاء لنذر ، أو نافلة من البقر أو الأغنام ، تكون صحيحة للرضا . كل عيب لا يكون فيها '),
(23048, 'Leviticus', 3, 22, 22, ' الأعمى والمكسور والمجروح والبثير والأجرب والأكلف ، هذه لا تقربوها للرب ، ولا تجعلوا منها وقودا على المذبح للرب '),
(23049, 'Leviticus', 3, 22, 23, ' وأما الثور أو الشاة الزوائدي أو القزم فنافلة تعمله ، ولكن لنذر لا يرضى به '),
(23050, 'Leviticus', 3, 22, 24, ' ومرضوض الخصية ومسحوقها ومقطوعها لا تقربوا للرب . وفي أرضكم لا تعملوها '),
(23051, 'Leviticus', 3, 22, 25, ' ومن يد ابن الغريب لا تقربوا خبز إلهكم من جميع هذه ، لأن فيها فسادها . فيها عيب لا يرضى بها عنكم '),
(23052, 'Leviticus', 3, 22, 26, ' وكلم الرب موسى قائلا '),
(23053, 'Leviticus', 3, 22, 27, ' متى ولد بقر أو غنم أو معزى يكون سبعة أيام تحت أمه ، ثم من اليوم الثامن فصاعدا يرضى به قربان وقود للرب '),
(23054, 'Leviticus', 3, 22, 28, ' وأما البقرة أو الشاة فلا تذبحوها وابنها في يوم واحد '),
(23055, 'Leviticus', 3, 22, 29, ' ومتى ذبحتم ذبيحة شكر للرب ، فللرضا عنكم تذبحونها '),
(23056, 'Leviticus', 3, 22, 30, ' في ذلك اليوم تؤكل . لا تبقوا منها إلى الغد . أنا الرب '),
(23057, 'Leviticus', 3, 22, 31, ' فتحفظون وصاياي وتعملونها . أنا الرب '),
(23058, 'Leviticus', 3, 22, 32, ' ولا تدنسون اسمي القدوس ، فأتقدس في وسط بني إسرائيل . أنا الرب مقدسكم '),
(23059, 'Leviticus', 3, 22, 33, ' الذي أخرجكم من أرض مصر ليكون لكم إلها . أنا الرب '),
(23060, 'Leviticus', 3, 23, 1, ' وكلم الرب موسى قائلا '),
(23061, 'Leviticus', 3, 23, 2, ' كلم بني إسرائيل وقل لهم : مواسم الرب التي فيها تنادون محافل مقدسة . هذه هي مواسمي '),
(23062, 'Leviticus', 3, 23, 3, ' ستة أيام يعمل عمل ، وأما اليوم السابع ففيه سبت عطلة محفل مقدس . عملا ما لا تعملوا . إنه سبت للرب في جميع مساكنكم '),
(23063, 'Leviticus', 3, 23, 4, ' هذه مواسم الرب ، المحافل المقدسة التي تنادون بها في أوقاتها '),
(23064, 'Leviticus', 3, 23, 5, ' في الشهر الأول ، في الرابع عشر من الشهر ، بين العشاءين فصح للرب '),
(23065, 'Leviticus', 3, 23, 6, ' وفي اليوم الخامس عشر من هذا الشهر عيد الفطير للرب . سبعة أيام تأكلون فطيرا '),
(23066, 'Leviticus', 3, 23, 7, ' في اليوم الأول يكون لكم محفل مقدس . عملا ما من الشغل لا تعملوا '),
(23067, 'Leviticus', 3, 23, 8, ' وسبعة أيام تقربون وقودا للرب . في اليوم السابع يكون محفل مقدس . عملا ما من الشغل لا تعملوا '),
(23068, 'Leviticus', 3, 23, 9, ' وكلم الرب موسى قائلا '),
(23069, 'Leviticus', 3, 23, 10, ' كلم بني إسرائيل وقل لهم : متى جئتم إلى الأرض التي أنا أعطيكم وحصدتم حصيدها ، تأتون بحزمة أول حصيدكم إلى الكاهن '),
(23070, 'Leviticus', 3, 23, 11, ' فيردد الحزمة أمام الرب للرضا عنكم . في غد السبت يرددها الكاهن '),
(23071, 'Leviticus', 3, 23, 12, ' وتعملون يوم ترديدكم الحزمة خروفا صحيحا حوليا محرقة للرب '),
(23072, 'Leviticus', 3, 23, 13, ' وتقدمته عشرين من دقيق ملتوت بزيت ، وقودا للرب رائحة سرور ، وسكيبه ربع الهين من خمر '),
(23073, 'Leviticus', 3, 23, 14, ' وخبزا وفريكا وسويقا لا تأكلوا إلى هذا اليوم عينه ، إلى أن تأتوا بقربان إلهكم ، فريضة دهرية في أجيالكم في جميع مساكنكم '),
(23074, 'Leviticus', 3, 23, 15, ' ثم تحسبون لكم من غد السبت من يوم إتيانكم بحزمة الترديد سبعة أسابيع تكون كاملة '),
(23075, 'Leviticus', 3, 23, 16, ' إلى غد السبت السابع تحسبون خمسين يوما ، ثم تقربون تقدمة جديدة للرب '),
(23076, 'Leviticus', 3, 23, 17, ' من مساكنكم تأتون بخبز ترديد ، رغيفين عشرين يكونان من دقيق ، ويخبزان خميرا باكورة للرب '),
(23077, 'Leviticus', 3, 23, 18, ' وتقربون مع الخبز سبعة خراف صحيحة حولية ، وثورا واحدا ابن بقر ، وكبشين محرقة للرب مع تقدمتها وسكيبها وقود رائحة سرور للرب '),
(23078, 'Leviticus', 3, 23, 19, ' وتعملون تيسا واحدا من المعز ذبيحة خطية ، وخروفين حوليين ذبيحة سلامة '),
(23079, 'Leviticus', 3, 23, 20, ' فيرددها الكاهن مع خبز الباكورة ترديدا أمام الرب مع الخروفين ، فتكون للكاهن قدسا للرب '),
(23080, 'Leviticus', 3, 23, 21, ' وتنادون في ذلك اليوم عينه محفلا مقدسا يكون لكم . عملا ما من الشغل لاتعملوا . فريضة دهرية في جميع مساكنكم في أجيالكم '),
(23081, 'Leviticus', 3, 23, 22, ' وعندما تحصدون حصيد أرضكم ، لا تكمل زوايا حقلك في حصادك ، ولقاط حصيدك لاتلتقط . للمسكين والغريب تتركه . أنا الرب إلهكم '),
(23082, 'Leviticus', 3, 23, 23, ' وكلم الرب موسى قائلا '),
(23083, 'Leviticus', 3, 23, 24, ' كلم بني إسرائيل قائلا : في الشهر السابع ، في أول الشهر يكون لكم عطلة ، تذكار هتاف البوق ، محفل مقدس '),
(23084, 'Leviticus', 3, 23, 25, ' عملا ما من الشغل لاتعملوا ، لكن تقربون وقودا للرب '),
(23085, 'Leviticus', 3, 23, 26, ' وكلم الرب موسى قائلا '),
(23086, 'Leviticus', 3, 23, 27, ' أما العاشر من هذا الشهر السابع ، فهو يوم الكفارة . محفلا مقدسا يكون لكم . تذللون نفوسكم وتقربون وقودا للرب '),
(23087, 'Leviticus', 3, 23, 28, ' عملا ما لا تعملوا في هذا اليوم عينه ، لأنه يوم كفارة للتكفير عنكم أمام الرب إلهكم '),
(23088, 'Leviticus', 3, 23, 29, ' إن كل نفس لاتتذلل في هذا اليوم عينه تقطع من شعبها '),
(23089, 'Leviticus', 3, 23, 30, ' وكل نفس تعمل عملا ما في هذا اليوم عينه أبيد تلك النفس من شعبها '),
(23090, 'Leviticus', 3, 23, 31, ' عملا مالا تعملوا . فريضة دهرية في أجيالكم في جميع مساكنكم '),
(23091, 'Leviticus', 3, 23, 32, ' إنه سبت عطلة لكم ، فتذللون نفوسكم . في تاسع الشهر عند المساء . من المساء إلى المساء تسبتون سبتكم '),
(23092, 'Leviticus', 3, 23, 33, ' وكلم الرب موسى قائلا '),
(23093, 'Leviticus', 3, 23, 34, ' كلم بني إسرائيل قائلا : في اليوم الخامس عشر من هذا الشهر السابع عيد المظال سبعة أيام للرب '),
(23094, 'Leviticus', 3, 23, 35, ' في اليوم الأول محفل مقدس . عملا ما من الشغل لا تعملوا '),
(23095, 'Leviticus', 3, 23, 36, ' سبعة أيام تقربون وقودا للرب . في اليوم الثامن يكون لكم محفل مقدس تقربون وقودا للرب . إنه اعتكاف . كل عمل شغل لا تعملوا '),
(23096, 'Leviticus', 3, 23, 37, ' هذه هي مواسم الرب التي فيها تنادون محافل مقدسة لتقريب وقود للرب ، محرقة وتقدمة وذبيحة وسكيبا أمر اليوم بيومه '),
(23097, 'Leviticus', 3, 23, 38, ' عدا سبوت الرب ، وعدا عطاياكم وجميع نذوركم ، وجميع نوافلكم التي تعطونها للرب '),
(23098, 'Leviticus', 3, 23, 39, ' أما اليوم الخامس عشر من الشهر السابع ففيه ، عندما تجمعون غلة الأرض ، تعيدون عيدا للرب سبعة أيام . في اليوم الأول عطلة وفي اليوم الثامن عطلة '),
(23099, 'Leviticus', 3, 23, 40, ' وتأخذون لأنفسكم في اليوم الأول ثمر أشجار بهجة وسعف النخل وأغصان أشجار غبياء وصفصاف الوادي ، وتفرحون أمام الرب إلهكم سبعة أيام '),
(23100, 'Leviticus', 3, 23, 41, ' تعيدونه عيدا للرب سبعة أيام في السنة فريضة دهرية في أجيالكم . في الشهر السابع تعيدونه '),
(23101, 'Leviticus', 3, 23, 42, ' في مظال تسكنون سبعة أيام . كل الوطنيين في إسرائيل يسكنون في المظال '),
(23102, 'Leviticus', 3, 23, 43, ' لكي تعلم أجيالكم أني في مظال أسكنت بني إسرائيل لما أخرجتهم من أرض مصر . أنا الرب إلهكم '),
(23103, 'Leviticus', 3, 23, 44, ' فأخبر موسى بني إسرائيل بمواسم الرب '),
(23104, 'Leviticus', 3, 24, 1, ' وكلم الرب موسى قائلا '),
(23105, 'Leviticus', 3, 24, 2, ' أوص بني إسرائيل أن يقدموا إليك زيت زيتون مرضوض نقيا للضوء لإيقاد السرج دائما '),
(23106, 'Leviticus', 3, 24, 3, ' خارج حجاب الشهادة في خيمة الاجتماع يرتبها هارون من المساء إلى الصباح أمام الرب دائما فريضة دهرية في أجيالكم '),
(23107, 'Leviticus', 3, 24, 4, ' على المنارة الطاهرة يرتب السرج أمام الرب دائما '),
(23108, 'Leviticus', 3, 24, 5, ' وتأخذ دقيقا وتخبزه اثني عشر قرصا . عشرين يكون القرص الواحد '),
(23109, 'Leviticus', 3, 24, 6, ' وتجعلها صفين ، كل صف ستة على المائدة الطاهرة أمام الرب '),
(23110, 'Leviticus', 3, 24, 7, ' وتجعل على كل صف لبانا نقيا فيكون للخبز تذكارا وقودا للرب '),
(23111, 'Leviticus', 3, 24, 8, ' في كل يوم سبت يرتبه أمام الرب دائما ، من عند بني إسرائيل ميثاقا دهريا '),
(23112, 'Leviticus', 3, 24, 9, ' فيكون لهارون وبنيه ، فيأكلونه في مكان مقدس ، لأنه قدس أقداس له من وقائد الرب فريضة دهرية '),
(23113, 'Leviticus', 3, 24, 10, ' وخرج ابن امرأة إسرائيلية ، وهو ابن رجل مصري ، في وسط بني إسرائيل . وتخاصم في المحلة ابن الإسرائيلية ورجل إسرائيلي '),
(23114, 'Leviticus', 3, 24, 11, ' فجدف ابن الإسرائيلية على الاسم وسب . فأتوا به إلى موسى . وكان اسم أمه شلومية بنت دبري من سبط دان '),
(23115, 'Leviticus', 3, 24, 12, ' فوضعوه في المحرس ليعلن لهم عن فم الرب '),
(23116, 'Leviticus', 3, 24, 13, ' فكلم الرب موسى قائلا '),
(23117, 'Leviticus', 3, 24, 14, ' أخرج الذي سب إلى خارج المحلة ، فيضع جميع السامعين أيديهم على رأسه ، ويرجمه كل الجماعة '),
(23118, 'Leviticus', 3, 24, 15, ' وكلم بني إسرائيل قائلا : كل من سب إلهه يحمل خطيته '),
(23119, 'Leviticus', 3, 24, 16, ' ومن جدف على اسم الرب فإنه يقتل . يرجمه كل الجماعة رجما . الغريب كالوطني عندما يجدف على الاسم يقتل '),
(23120, 'Leviticus', 3, 24, 17, ' وإذا أمات أحد إنسانا فإنه يقتل '),
(23121, 'Leviticus', 3, 24, 18, ' ومن أمات بهيمة يعوض عنها نفسا بنفس '),
(23122, 'Leviticus', 3, 24, 19, ' وإذا أحدث إنسان في قريبه عيبا ، فكما فعل كذلك يفعل به '),
(23123, 'Leviticus', 3, 24, 20, ' كسر بكسر ، وعين بعين ، وسن بسن . كما أحدث عيبا في الإنسان كذلك يحدث فيه '),
(23124, 'Leviticus', 3, 24, 21, ' من قتل بهيمة يعوض عنها ، ومن قتل إنسانا يقتل '),
(23125, 'Leviticus', 3, 24, 22, ' حكم واحد يكون لكم . الغريب يكون كالوطني . إني أنا الرب إلهكم '),
(23126, 'Leviticus', 3, 24, 23, ' فكلم موسى بني إسرائيل أن يخرجوا الذي سب إلى خارج المحلة ويرجموه بالحجارة . ففعل بنو إسرائيل كما أمر الرب موسى '),
(23127, 'Leviticus', 3, 25, 1, ' وكلم الرب موسى في جبل سيناء قائلا '),
(23128, 'Leviticus', 3, 25, 2, ' كلم بني إسرائيل وقل لهم : متى أتيتم إلى الأرض التي أنا أعطيكم تسبت الأرض سبتا للرب '),
(23129, 'Leviticus', 3, 25, 3, ' ست سنين تزرع حقلك ، وست سنين تقضب كرمك وتجمع غلتهما '),
(23130, 'Leviticus', 3, 25, 4, ' وأما السنة السابعة ففيها يكون للأرض سبت عطلة ، سبتا للرب . لا تزرع حقلك ولا تقضب كرمك '),
(23131, 'Leviticus', 3, 25, 5, ' زريع حصيدك لا تحصد ، وعنب كرمك المحول لا تقطف . سنة عطلة تكون للأرض '),
(23132, 'Leviticus', 3, 25, 6, ' ويكون سبت الأرض لكم طعاما . لك ولعبدك ولأمتك ولأجيرك ولمستوطنك النازلين عندك '),
(23133, 'Leviticus', 3, 25, 7, ' ولبهائمك وللحيوان الذي في أرضك تكون كل غلتها طعاما '),
(23134, 'Leviticus', 3, 25, 8, ' وتعد لك سبعة سبوت سنين . سبع سنين سبع مرات . فتكون لك أيام السبعة السبوت السنوية تسعا وأربعين سنة '),
(23135, 'Leviticus', 3, 25, 9, ' ثم تعبر بوق الهتاف في الشهر السابع في عاشر الشهر . في يوم الكفارة تعبرون البوق في جميع أرضكم '),
(23136, 'Leviticus', 3, 25, 10, ' وتقدسون السنة الخمسين ، وتنادون بالعتق في الأرض لجميع سكانها . تكون لكم يوبيلا ، وترجعون كل إلى ملكه ، وتعودون كل إلى عشيرته '),
(23137, 'Leviticus', 3, 25, 11, ' يوبيلا تكون لكم السنة الخمسون . لا تزرعوا ولا تحصدوا زريعها ، ولا تقطفوا كرمها المحول '),
(23138, 'Leviticus', 3, 25, 12, ' إنها يوبيل . مقدسة تكون لكم . من الحقل تأكلون غلتها '),
(23139, 'Leviticus', 3, 25, 13, ' في سنة اليوبيل هذه ترجعون كل إلى ملكه '),
(23140, 'Leviticus', 3, 25, 14, ' فمتى بعت صاحبك مبيعا ، أو اشتريت من يد صاحبك ، فلا يغبن أحدكم أخاه '),
(23141, 'Leviticus', 3, 25, 15, ' حسب عدد السنين بعد اليوبيل تشتري من صاحبك ، وحسب سني الغلة يبيعك '),
(23142, 'Leviticus', 3, 25, 16, ' على قدر كثرة السنين تكثر ثمنه ، وعلى قدر قلة السنين تقلل ثمنه ، لأنه عدد الغلات يبيعك '),
(23143, 'Leviticus', 3, 25, 17, ' فلا يغبن أحدكم صاحبه ، بل اخش إلهك . إني أنا الرب إلهكم '),
(23144, 'Leviticus', 3, 25, 18, ' فتعملون فرائضي وتحفظون أحكامي وتعملونها لتسكنوا على الأرض آمنين '),
(23145, 'Leviticus', 3, 25, 19, ' وتعطي الأرض ثمرها فتأكلون للشبع ، وتسكنون عليها آمنين '),
(23146, 'Leviticus', 3, 25, 20, ' وإذا قلتم : ماذا نأكل في السنة السابعة إن لم نزرع ولم نجمع غلتنا '),
(23147, 'Leviticus', 3, 25, 21, ' فإني آمر ببركتي لكم في السنة السادسة ، فتعمل غلة لثلاث سنين '),
(23148, 'Leviticus', 3, 25, 22, ' فتزرعون السنة الثامنة وتأكلون من الغلة العتيقة إلى السنة التاسعة . إلى أن تأتي غلتها تأكلون عتيقا '),
(23149, 'Leviticus', 3, 25, 23, ' والأرض لا تباع بتة ، لأن لي الأرض ، وأنتم غرباء ونزلاء عندي '),
(23150, 'Leviticus', 3, 25, 24, ' بل في كل أرض ملككم تجعلون فكاكا للأرض '),
(23151, 'Leviticus', 3, 25, 25, ' إذا افتقر أخوك فباع من ملكه ، يأتي وليه الأقرب إليه ويفك مبيع أخيه '),
(23152, 'Leviticus', 3, 25, 26, ' ومن لم يكن له ولي ، فإن نالت يده ووجد مقدار فكاكه '),
(23153, 'Leviticus', 3, 25, 27, ' يحسب سني بيعه ، ويرد الفاضل للإنسان الذي باع له ، فيرجع إلى ملكه '),
(23154, 'Leviticus', 3, 25, 28, ' وإن لم تنل يده كفاية ليرد له ، يكون مبيعه في يد شاريه إلى سنة اليوبيل ، ثم يخرج في اليوبيل فيرجع إلى ملكه '),
(23155, 'Leviticus', 3, 25, 29, ' وإذا باع إنسان بيت سكن في مدينة ذات سور ، فيكون فكاكه إلى تمام سنة بيعه . سنة يكون فكاكه '),
(23156, 'Leviticus', 3, 25, 30, ' وإن لم يفك قبل أن تكمل له سنة تامة ، وجب البيت الذي في المدينة ذات السور بتة لشاريه في أجياله . لا يخرج في اليوبيل '),
(23157, 'Leviticus', 3, 25, 31, ' لكن بيوت القرى التي ليس لها سور حولها ، فمع حقول الأرض تحسب . يكون لها فكاك ، وفي اليوبيل تخرج '),
(23158, 'Leviticus', 3, 25, 32, ' وأما مدن اللاويين ، بيوت مدن ملكهم ، فيكون لها فكاك مؤبد للاويين '),
(23159, 'Leviticus', 3, 25, 33, ' والذي يفكه من اللاويين المبيع من بيت أو من مدينة ملكه يخرج في اليوبيل ، لأن بيوت مدن اللاويين هي ملكهم في وسط بني إسرائيل '),
(23160, 'Leviticus', 3, 25, 34, ' وأما حقول المسارح لمدنهم فلا تباع ، لأنها ملك دهري لهم '),
(23161, 'Leviticus', 3, 25, 35, ' وإذا افتقر أخوك وقصرت يده عندك ، فاعضده غريبا أو مستوطنا فيعيش معك '),
(23162, 'Leviticus', 3, 25, 36, ' لا تأخذ منه ربا ولا مرابحة ، بل اخش إلهك ، فيعيش أخوك معك '),
(23163, 'Leviticus', 3, 25, 37, ' فضتك لا تعطه بالربا ، وطعامك لا تعط بالمرابحة '),
(23164, 'Leviticus', 3, 25, 38, ' أنا الرب إلهكم الذي أخرجكم من أرض مصر ليعطيكم أرض كنعان ، فيكون لكم إلها '),
(23165, 'Leviticus', 3, 25, 39, ' وإذا افتقر أخوك عندك وبيع لك ، فلا تستعبده استعباد عبد '),
(23166, 'Leviticus', 3, 25, 40, ' كأجير ، كنزيل يكون عندك . إلى سنة اليوبيل يخدم عندك '),
(23167, 'Leviticus', 3, 25, 41, ' ثم يخرج من عندك هو وبنوه معه ويعود إلى عشيرته ، وإلى ملك آبائه يرجع '),
(23168, 'Leviticus', 3, 25, 42, ' لأنهم عبيدي الذين أخرجتهم من أرض مصر ، لا يباعون بيع العبيد '),
(23169, 'Leviticus', 3, 25, 43, ' لا تتسلط عليه بعنف ، بل اخش إلهك '),
(23170, 'Leviticus', 3, 25, 44, ' وأما عبيدك وإماؤك الذين يكونون لك ، فمن الشعوب الذين حولكم . منهم تقتنون عبيدا وإماء ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(23171, 'Leviticus', 3, 25, 45, ' وأيضا من أبناء المستوطنين النازلين عندكم ، منهم تقتنون ومن عشائرهم الذين عندكم الذين يلدونهم في أرضكم ، فيكونون ملكا لكم '),
(23172, 'Leviticus', 3, 25, 46, ' وتستملكونهم لأبنائكم من بعدكم ميراث ملك . تستعبدونهم إلى الدهر . وأما إخوتكم بنو إسرائيل فلا يتسلط إنسان على أخيه بعنف '),
(23173, 'Leviticus', 3, 25, 47, ' وإذا طالت يد غريب أو نزيل عندك ، وافتقر أخوك عنده وبيع للغريب المستوطن عندك أو لنسل عشيرة الغريب '),
(23174, 'Leviticus', 3, 25, 48, ' فبعد بيعه يكون له فكاك . يفكه واحد من إخوته '),
(23175, 'Leviticus', 3, 25, 49, ' أو يفكه عمه أو ابن عمه ، أو يفكه واحد من أقرباء جسده من عشيرته ، أو إذا نالت يده يفك نفسه '),
(23176, 'Leviticus', 3, 25, 50, ' فيحاسب شاريه من سنة بيعه له إلى سنة اليوبيل ، ويكون ثمن بيعه حسب عدد السنين . كأيام أجير يكون عنده '),
(23177, 'Leviticus', 3, 25, 51, ' إن بقي كثير من السنين فعلى قدرها يرد فكاكه من ثمن شرائه '),
(23178, 'Leviticus', 3, 25, 52, ' وإن بقي قليل من السنين إلى سنة اليوبيل يحسب له وعلى قدر سنيه يرد فكاكه '),
(23179, 'Leviticus', 3, 25, 53, ' كأجير من سنة إلى سنة يكون عنده . لا يتسلط عليه بعنف أمام عينيك '),
(23180, 'Leviticus', 3, 25, 54, ' وإن لم يفك بهؤلاء ، يخرج في سنة اليوبيل هو وبنوه معه '),
(23181, 'Leviticus', 3, 25, 55, ' لأن بني إسرائيل لي عبيد . هم عبيدي الذين أخرجتهم من أرض مصر . أنا الرب إلهكم '),
(23182, 'Leviticus', 3, 26, 1, ' لا تصنعوا لكم أوثانا ، ولا تقيموا لكم تمثالا منحوتا أو نصبا ، ولا تجعلوا في أرضكم حجرا مصورا لتسجدوا له . لأني أنا الرب إلهكم '),
(23183, 'Leviticus', 3, 26, 2, ' سبوتي تحفظون ومقدسي تهابون . أنا الرب '),
(23184, 'Leviticus', 3, 26, 3, ' إذا سلكتم في فرائضي وحفظتم وصاياي وعملتم بها '),
(23185, 'Leviticus', 3, 26, 4, ' أعطي مطركم في حينه ، وتعطي الأرض غلتها ، وتعطي أشجار الحقل أثمارها '),
(23186, 'Leviticus', 3, 26, 5, ' ويلحق دراسكم بالقطاف ، ويلحق القطاف بالزرع ، فتأكلون خبزكم للشبع وتسكنون في أرضكم آمنين '),
(23187, 'Leviticus', 3, 26, 6, ' وأجعل سلاما في الأرض ، فتنامون وليس من يزعجكم . وأبيد الوحوش الرديئة من الأرض ، ولا يعبر سيف في أرضكم '),
(23188, 'Leviticus', 3, 26, 7, ' وتطردون أعداءكم فيسقطون أمامكم بالسيف '),
(23189, 'Leviticus', 3, 26, 8, ' يطرد خمسة منكم مئة ، ومئة منكم يطردون ربوة ، ويسقط أعداؤكم أمامكم بالسيف '),
(23190, 'Leviticus', 3, 26, 9, ' وألتفت إليكم وأثمركم وأكثركم وأفي ميثاقي معكم '),
(23191, 'Leviticus', 3, 26, 10, ' فتأكلون العتيق المعتق ، وتخرجون العتيق من وجه الجديد '),
(23192, 'Leviticus', 3, 26, 11, ' وأجعل مسكني في وسطكم ، ولا ترذلكم نفسي '),
(23193, 'Leviticus', 3, 26, 12, ' وأسير بينكم وأكون لكم إلها وأنتم تكونون لي شعبا '),
(23194, 'Leviticus', 3, 26, 13, ' أنا الرب إلهكم الذي أخرجكم من أرض مصر من كونكم لهم عبيدا ، وقطع قيود نيركم وسيركم قياما '),
(23195, 'Leviticus', 3, 26, 14, ' لكن إن لم تسمعوا لي ولم تعملوا كل هذه الوصايا '),
(23196, 'Leviticus', 3, 26, 15, ' وإن رفضتم فرائضي وكرهت أنفسكم أحكامي ، فما عملتم كل وصاياي ، بل نكثتم ميثاقي '),
(23197, 'Leviticus', 3, 26, 16, ' فإني أعمل هذه بكم : أسلط عليكم رعبا وسلا وحمى تفني العينين وتتلف النفس . وتزرعون باطلا زرعكم فيأكله أعداؤكم '),
(23198, 'Leviticus', 3, 26, 17, ' وأجعل وجهي ضدكم فتنهزمون أمام أعدائكم ، ويتسلط عليكم مبغضوكم ، وتهربون وليس من يطردكم '),
(23199, 'Leviticus', 3, 26, 18, ' وإن كنتم مع ذلك لا تسمعون لي ، أزيد على تأديبكم سبعة أضعاف حسب خطاياكم '),
(23200, 'Leviticus', 3, 26, 19, ' فأحطم فخار عزكم ، وأصير سماءكم كالحديد ، وأرضكم كالنحاس '),
(23201, 'Leviticus', 3, 26, 20, ' فتفرغ باطلا قوتكم ، وأرضكم لا تعطي غلتها ، وأشجار الأرض لا تعطي أثمارها '),
(23202, 'Leviticus', 3, 26, 21, ' وإن سلكتم معي بالخلاف ، ولم تشاءوا أن تسمعوا لي ، أزيد عليكم ضربات سبعة أضعاف حسب خطاياكم '),
(23203, 'Leviticus', 3, 26, 22, ' أطلق عليكم وحوش البرية فتعدمكم الأولاد ، وتقرض بهائمكم ، وتقللكم فتوحش طرقكم '),
(23204, 'Leviticus', 3, 26, 23, ' وإن لم تتأدبوا مني بذلك ، بل سلكتم معي بالخلاف '),
(23205, 'Leviticus', 3, 26, 24, ' فإني أنا أسلك معكم بالخلاف ، وأضربكم سبعة أضعاف حسب خطاياكم '),
(23206, 'Leviticus', 3, 26, 25, ' أجلب عليكم سيفا ينتقم نقمة الميثاق ، فتجتمعون إلى مدنكم وأرسل في وسطكم الوبأ فتدفعون بيد العدو '),
(23207, 'Leviticus', 3, 26, 26, ' بكسري لكم عصا الخبز . تخبز عشر نساء خبزكم في تنور واحد ، ويرددن خبزكم بالوزن ، فتأكلون ولا تشبعون '),
(23208, 'Leviticus', 3, 26, 27, ' وإن كنتم بذلك لا تسمعون لي بل سلكتم معي بالخلاف '),
(23209, 'Leviticus', 3, 26, 28, ' فأنا أسلك معكم بالخلاف ساخطا ، وأؤدبكم سبعة أضعاف حسب خطاياكم '),
(23210, 'Leviticus', 3, 26, 29, ' فتأكلون لحم بنيكم ، ولحم بناتكم تأكلون '),
(23211, 'Leviticus', 3, 26, 30, ' وأخرب مرتفعاتكم ، وأقطع شمساتكم ، وألقي جثثكم على جثث أصنامكم ، وترذلكم نفسي '),
(23212, 'Leviticus', 3, 26, 31, ' وأصير مدنكم خربة ، ومقادسكم موحشة ، ولا أشتم رائحة سروركم '),
(23213, 'Leviticus', 3, 26, 32, ' وأوحش الأرض فيستوحش منها أعداؤكم الساكنون فيها '),
(23214, 'Leviticus', 3, 26, 33, ' وأذريكم بين الأمم ، وأجرد وراءكم السيف فتصير أرضكم موحشة ، ومدنكم تصير خربة '),
(23215, 'Leviticus', 3, 26, 34, ' حينئذ تستوفي الأرض سبوتها كل أيام وحشتها وأنتم في أرض أعدائكم . حينئذ تسبت الأرض وتستوفي سبوتها '),
(23216, 'Leviticus', 3, 26, 35, ' كل أيام وحشتها تسبت ما لم تسبته من سبوتكم في سكنكم عليها '),
(23217, 'Leviticus', 3, 26, 36, ' والباقون منكم ألقي الجبانة في قلوبهم في أراضي أعدائهم ، فيهزمهم صوت ورقة مندفعة ، فيهربون كالهرب من السيف ، ويسقطون وليس طارد '),
(23218, 'Leviticus', 3, 26, 37, ' ويعثر بعضهم ببعض كما من أمام السيف وليس طارد ، ولا يكون لكم قيام أمام أعدائكم '),
(23219, 'Leviticus', 3, 26, 38, ' فتهلكون بين الشعوب وتأكلكم أرض أعدائكم '),
(23220, 'Leviticus', 3, 26, 39, ' والباقون منكم يفنون بذنوبهم في أراضي أعدائكم . وأيضا بذنوب آبائهم معهم يفنون '),
(23221, 'Leviticus', 3, 26, 40, ' لكن إن أقروا بذنوبهم وذنوب آبائهم في خيانتهم التي خانوني بها ، وسلوكهم معي الذي سلكوا بالخلاف '),
(23222, 'Leviticus', 3, 26, 41, ' وإني أيضا سلكت معهم بالخلاف وأتيت بهم إلى أرض أعدائهم . إلا أن تخضع حينئذ قلوبهم الغلف ، ويستوفوا حينئذ عن ذنوبهم '),
(23223, 'Leviticus', 3, 26, 42, ' أذكر ميثاقي مع يعقوب ، وأذكر أيضا ميثاقي مع إسحاق ، وميثاقي مع إبراهيم ، وأذكر الأرض '),
(23224, 'Leviticus', 3, 26, 43, ' والأرض تترك منهم وتستوفي سبوتها في وحشتها منهم ، وهم يستوفون عن ذنوبهم لأنهم قد أبوا أحكامي وكرهت أنفسهم فرائضي '),
(23225, 'Leviticus', 3, 26, 44, ' ولكن مع ذلك أيضا متى كانوا في أرض أعدائهم ، ما أبيتهم ولا كرهتهم حتى أبيدهم وأنكث ميثاقي معهم ، لأني أنا الرب إلههم '),
(23226, 'Leviticus', 3, 26, 45, ' بل أذكر لهم الميثاق مع الأولين الذين أخرجتهم من أرض مصر أمام أعين الشعوب لأكون لهم إلها . أنا الرب '),
(23227, 'Leviticus', 3, 26, 46, ' هذه هي الفرائض والأحكام والشرائع التي وضعها الرب بينه وبين بني إسرائيل في جبل سيناء بيد موسى '),
(23228, 'Leviticus', 3, 27, 1, ' وكلم الرب موسى قائلا '),
(23229, 'Leviticus', 3, 27, 2, ' كلم بني إسرائيل وقل لهم : إذا أفرز إنسان نذرا حسب تقويمك نفوسا للرب '),
(23230, 'Leviticus', 3, 27, 3, ' فإن كان تقويمك لذكر من ابن عشرين سنة إلى ابن ستين سنة ، يكون تقويمك خمسين شاقل فضة على شاقل المقدس '),
(23231, 'Leviticus', 3, 27, 4, ' وإن كان أنثى يكون تقويمك ثلاثين شاقلا '),
(23232, 'Leviticus', 3, 27, 5, ' وإن كان من ابن خمس سنين إلى ابن عشرين سنة يكون تقويمك لذكر عشرين شاقلا ، ولأنثى عشرة شواقل '),
(23233, 'Leviticus', 3, 27, 6, ' وإن كان من ابن شهر إلى ابن خمس سنين يكون تقويمك لذكر خمسة شواقل فضة ، ولأنثى يكون تقويمك ثلاثة شواقل فضة '),
(23234, 'Leviticus', 3, 27, 7, ' وإن كان من ابن ستين سنة فصاعدا فإن كان ذكرا يكون تقويمك خمسة عشر شاقلا ، وأما للأنثى فعشرة شواقل '),
(23235, 'Leviticus', 3, 27, 8, ' وإن كان فقيرا عن تقويمك يوقفه أمام الكاهن فيقومه الكاهن . على قدر ما تنال يد الناذر يقومه الكاهن '),
(23236, 'Leviticus', 3, 27, 9, ' وإن كان بهيمة مما يقربونه قربانا للرب ، فكل ما يعطي منه للرب يكون قدسا '),
(23237, 'Leviticus', 3, 27, 10, ' لا يغيره ولا يبدله جيدا برديء ، أو رديئا بجيد . وإن أبدل بهيمة ببهيمة تكون هي وبديلها قدسا '),
(23238, 'Leviticus', 3, 27, 11, ' وإن كان بهيمة نجسة مما لا يقربونه قربانا للرب يوقف البهيمة أمام الكاهن '),
(23239, 'Leviticus', 3, 27, 12, ' فيقومها الكاهن جيدة أم رديئة . فحسب تقويمك يا كاهن هكذا يكون '),
(23240, 'Leviticus', 3, 27, 13, ' فإن فكها يزيد خمسها على تقويمك '),
(23241, 'Leviticus', 3, 27, 14, ' وإذا قدس إنسان بيته قدسا للرب ، يقومه الكاهن جيدا أم رديئا '),
(23242, 'Leviticus', 3, 27, 0, ' وكما يقومه الكاهن هكذا يقوم '),
(23243, 'Leviticus', 3, 27, 15, ' فإن كان المقدس يفك بيته ، يزيد خمس فضة تقويمك عليه فيكون له '),
(23244, 'Leviticus', 3, 27, 16, ' وإن قدس إنسان بعض حقل ملكه للرب ، يكون تقويمك على قدر بذاره . بذار حومر من الشعير بخمسين شاقل فضة '),
(23245, 'Leviticus', 3, 27, 17, ' إن قدس حقله من سنة اليوبيل فحسب تقويمك يقوم '),
(23246, 'Leviticus', 3, 27, 18, ' وإن قدس حقله بعد سنة اليوبيل يحسب له الكاهن الفضة على قدر السنين الباقية إلى سنة اليوبيل ، فينقص من تقويمك '),
(23247, 'Leviticus', 3, 27, 19, ' فإن فك الحقل مقدسه ، يزيد خمس فضة تقويمك عليه فيجب له '),
(23248, 'Leviticus', 3, 27, 20, ' لكن إن لم يفك الحقل وبيع الحقل لإنسان آخر لا يفك بعد '),
(23249, 'Leviticus', 3, 27, 21, ' بل يكون الحقل عند خروجه في اليوبيل قدسا للرب كالحقل المحرم . للكاهن يكون ملكه '),
(23250, 'Leviticus', 3, 27, 22, ' وإن قدس للرب حقلا من شرائه ليس من حقول ملكه '),
(23251, 'Leviticus', 3, 27, 23, ' يحسب له الكاهن مبلغ تقويمك إلى سنة اليوبيل ، فيعطي تقويمك في ذلك اليوم قدسا للرب '),
(23252, 'Leviticus', 3, 27, 24, ' وفي سنة اليوبيل يرجع الحقل إلى الذي اشتراه منه ، إلى الذي له ملك الأرض '),
(23253, 'Leviticus', 3, 27, 25, ' وكل تقويمك يكون على شاقل المقدس . عشرين جيرة يكون الشاقل '),
(23254, 'Leviticus', 3, 27, 26, ' لكن البكر الذي يفرز بكرا للرب من البهائم فلا يقدسه أحد . ثورا كان أو شاة فهو للرب '),
(23255, 'Leviticus', 3, 27, 27, ' وإن كان من البهائم النجسة يفديه حسب تقويمك ويزيد خمسه عليه . وإن لم يفك ، فيباع حسب تقويمك '),
(23256, 'Leviticus', 3, 27, 28, ' أما كل محرم يحرمه إنسان للرب من كل ما له من الناس والبهائم ومن حقول ملكه فلا يباع ولا يفك . إن كل محرم هو قدس أقداس للرب '),
(23257, 'Leviticus', 3, 27, 29, ' كل محرم يحرم من الناس لا يفدى . يقتل قتلا '),
(23258, 'Leviticus', 3, 27, 30, ' وكل عشر الأرض من حبوب الأرض وأثمار الشجر فهو للرب . قدس للرب '),
(23259, 'Leviticus', 3, 27, 31, ' وإن فك إنسان بعض عشره يزيد خمسه عليه '),
(23260, 'Leviticus', 3, 27, 32, ' وأما كل عشر البقر والغنم فكل ما يعبر تحت العصا يكون العاشر قدسا للرب '),
(23261, 'Leviticus', 3, 27, 33, ' لا يفحص أجيد هو أم رديء ، ولا يبدله . وإن أبدله يكون هو وبديله قدسا . لا يفك '),
(23262, 'Leviticus', 3, 27, 34, ' هذه هي الوصايا التي أوصى الرب بها موسى إلى بني إسرائيل في جبل سيناء '),
(23263, 'Leviticus', 3, 1, 1, 'و دعا الرب موسى و كلمه من خيمة الاجتماع قائلا'),
(23264, 'Leviticus', 3, 1, 2, 'كلم بني اسرائيل و قل لهم اذا قرب انسان منكم قربانا للرب من البهائم فمن البقر و الغنم تقربون قرابينكم'),
(23265, 'Leviticus', 3, 1, 3, 'ان كان قربانه محرقة من البقر فذكرا صحيحا يقربه الى باب خيمة الاجتماع يقدمه للرضا عنه امام الرب'),
(23266, 'Leviticus', 3, 1, 4, 'و يضع يده على راس المحرقة فيرضى عليه للتكفير عنه'),
(23267, 'Leviticus', 3, 1, 5, 'و يذبح العجل امام الرب و يقرب بنو هرون الكهنة الدم و يرشون الدم مستديرا على المذبح الذي لدى باب خيمة الاجتماع'),
(23268, 'Leviticus', 3, 1, 6, 'و يسلخ المحرقة و يقطعها الى قطعها'),
(23269, 'Leviticus', 3, 1, 7, 'و يجعل بنو هرون الكاهن نارا على المذبح و يرتبون حطبا على النار'),
(23270, 'Leviticus', 3, 1, 8, 'و يرتب بنو هرون الكهنة القطع مع الراس و الشحم فوق الحطب الذي على النار التي على المذبح'),
(23271, 'Leviticus', 3, 1, 9, 'و اما احشاؤه و اكارعه فيغسلها بماء و يوقد الكاهن الجميع على المذبح محرقة وقود رائحة سرور للرب'),
(23272, 'Leviticus', 3, 1, 10, 'و ان كان قربانه من الغنم الضان او المعز محرقة فذكرا صحيحا يقربه'),
(23273, 'Leviticus', 3, 1, 11, 'و يذبحه على جانب المذبح الى الشمال امام الرب و يرش بنو هرون الكهنة دمه على المذبح مستديرا'),
(23274, 'Leviticus', 3, 1, 12, 'و يقطعه الى قطعه مع راسه و شحمه و يرتبهن الكاهن فوق الحطب الذي على النار التي على المذبح'),
(23275, 'Leviticus', 3, 1, 13, 'و اما الاحشاء و الاكارع فيغسلها بماء و يقرب الكاهن الجميع و يوقد على المذبح انه محرقة وقود رائحة سرور للرب'),
(23276, 'Leviticus', 3, 1, 14, 'و ان كان قربانه للرب من الطير محرقة يقرب قربانه من اليمام او من افراخ الحمام'),
(23277, 'Leviticus', 3, 1, 15, 'يقدمه الكاهن الى المذبح و يحز راسه و يوقد على المذبح و يعصر دمه على حائط المذبح'),
(23278, 'Leviticus', 3, 1, 16, 'و ينزع حوصلته بفرثها و يطرحها الى جانب المذبح شرقا الى مكان الرماد'),
(23279, 'Leviticus', 3, 1, 17, 'و يشقه بين جناحيه لا يفصله و يوقده الكاهن على المذبح فوق الحطب الذي على النار انه محرقة وقود رائحة سرور للرب'),
(23280, 'Leviticus', 3, 2, 1, 'و اذا قرب احد قربان تقدمة للرب يكون قربانه من دقيق و يسكب عليها زيتا و يجعل عليها لبانا'),
(23281, 'Leviticus', 3, 2, 2, 'و ياتي بها الى بني هرون الكهنة و يقبض منها ملء قبضته من دقيقها و زيتها مع كل لبانها و يوقد الكاهن تذكارها على المذبح وقود رائحة سرور للرب'),
(23282, 'Leviticus', 3, 2, 3, 'و الباقي من التقدمة هو لهرون و بنيه قدس اقداس من وقائد الرب'),
(23283, 'Leviticus', 3, 2, 4, 'و اذا قربت قربان تقدمة مخبوزة في تنور تكون اقراصا من دقيق فطيرا ملتوتة بزيت و رقاقا فطيرا مدهونة بزيت'),
(23284, 'Leviticus', 3, 2, 5, 'و ان كان قربانك تقدمة على الصاج تكون من دقيق ملتوتة بزيت فطيرا'),
(23285, 'Leviticus', 3, 2, 6, 'تفتها فتاتا و تسكب عليها زيتا انها تقدمة'),
(23286, 'Leviticus', 3, 2, 7, 'و ان كان قربانك تقدمة من طاجن فمن دقيق بزيت تعمله'),
(23287, 'Leviticus', 3, 2, 8, 'فتاتي بالتقدمة التي تصطنع من هذه الى الرب و تقدمها الى الكاهن فيدنو بها الى المذبح'),
(23288, 'Leviticus', 3, 2, 9, 'و ياخذ الكاهن من التقدمة تذكارها و يوقد على المذبح وقود رائحة سرور للرب'),
(23289, 'Leviticus', 3, 2, 10, 'و الباقي من التقدمة هو لهرون و بنيه قدس اقداس من وقائد الرب'),
(23290, 'Leviticus', 3, 2, 11, 'كل التقدمات التي تقربونها للرب لا تصطنع خميرا لان كل خمير و كل عسل لا توقدوا منهما وقودا للرب'),
(23291, 'Leviticus', 3, 2, 12, 'قربان اوائل تقربونهما للرب لكن على المذبح لا يصعدان لرائحة سرور'),
(23292, 'Leviticus', 3, 2, 13, 'و كل قربان من تقادمك بالملح تملحه و لا تخل تقدمتك من ملح عهد الهك على جميع قرابينك تقرب ملحا'),
(23293, 'Leviticus', 3, 2, 14, 'و ان قربت تقدمة باكورات للرب ففريكا مشويا بالنار جريشا سويقا تقرب تقدمة باكوراتك'),
(23294, 'Leviticus', 3, 2, 15, 'و تجعل عليها زيتا و تضع عليها لبانا انها تقدمة'),
(23295, 'Leviticus', 3, 2, 16, 'فيوقد الكاهن تذكارها من جريشها و زيتها مع جميع لبانها وقودا للرب'),
(23296, 'Leviticus', 3, 3, 1, 'و ان كان قربانه ذبيحة سلامة فان قرب من البقر ذكرا او انثى فصحيحا يقربه امام الرب'),
(23297, 'Leviticus', 3, 3, 2, 'يضع يده على راس قربانه و يذبحه لدى باب خيمة الاجتماع و يرش بنو هرون الكهنة الدم على المذبح مستديرا'),
(23298, 'Leviticus', 3, 3, 3, 'و يقرب من ذبيحة السلامة وقودا للرب الشحم الذي يغشي الاحشاء و سائر الشحم الذي على الاحشاء'),
(23299, 'Leviticus', 3, 3, 4, 'و الكليتين و الشحم الذي عليهما الذي على الخاصرتين و زيادة الكبد مع الكليتين ينزعها'),
(23300, 'Leviticus', 3, 3, 5, 'و يوقدها بنو هرون على المذبح على المحرقة التي فوق الحطب الذي على النار وقود رائحة سرور للرب'),
(23301, 'Leviticus', 3, 3, 6, 'و ان كان قربانه من الغنم ذبيحة سلامة للرب ذكرا او انثى فصحيحا يقربه'),
(23302, 'Leviticus', 3, 3, 7, 'ان قرب قربانه من الضان يقدمه امام الرب'),
(23303, 'Leviticus', 3, 3, 8, 'يضع يده على راس قربانه و يذبحه قدام خيمة الاجتماع و يرش بنو هرون دمه على المذبح مستديرا'),
(23304, 'Leviticus', 3, 3, 9, 'و يقرب من ذبيحة السلامة شحمها وقودا للرب الالية صحيحة من عند العصعص ينزعها و الشحم الذي يغشي الاحشاء و سائر الشحم الذي على الاحشاء'),
(23305, 'Leviticus', 3, 3, 10, 'و الكليتين و الشحم الذي عليهما الذي على الخاصرتين و زيادة الكبد مع الكليتين ينزعها'),
(23306, 'Leviticus', 3, 3, 11, 'و يوقدها الكاهن على المذبح طعام وقود للرب'),
(23307, 'Leviticus', 3, 3, 12, 'و ان كان قربانه من المعز يقدمه امام الرب'),
(23308, 'Leviticus', 3, 3, 13, 'يضع يده على راسه و يذبحه قدام خيمة الاجتماع و يرش بنو هرون دمه على المذبح مستديرا'),
(23309, 'Leviticus', 3, 3, 14, 'و يقرب منه قربانه وقودا للرب الشحم الذي يغشي الاحشاء و سائر الشحم الذي على الاحشاء'),
(23310, 'Leviticus', 3, 3, 15, 'و الكليتين و الشحم الذي عليهما الذي على الخاصرتين و زيادة الكبد مع الكليتين ينزعها'),
(23311, 'Leviticus', 3, 3, 16, 'و يوقدهن الكاهن على المذبح طعام وقود لرائحة سرور كل الشحم للرب'),
(23312, 'Leviticus', 3, 3, 17, 'فريضة دهرية في اجيالكم في جميع مساكنكم لا تاكلوا شيئا من الشحم و لا من الدم'),
(23313, 'Leviticus', 3, 4, 1, 'و كلم الرب موسى قائلا'),
(23314, 'Leviticus', 3, 4, 2, 'كلم بني اسرائيل قائلا اذا اخطات نفس سهوا في شيء من جميع مناهي الرب التي لا ينبغي عملها و عملت واحدة منها'),
(23315, 'Leviticus', 3, 4, 3, 'ان كان الكاهن الممسوح يخطئ لاثم الشعب يقرب عن خطيته التي اخطا ثورا ابن بقر صحيحا للرب ذبيحة خطية'),
(23316, 'Leviticus', 3, 4, 4, 'يقدم الثور الى باب خيمة الاجتماع امام الرب و يضع يده على راس الثور و يذبح الثور امام الرب'),
(23317, 'Leviticus', 3, 4, 5, 'و ياخذ الكاهن الممسوح من دم الثور و يدخل به الى خيمة الاجتماع'),
(23318, 'Leviticus', 3, 4, 6, 'و يغمس الكاهن اصبعه في الدم و ينضح من الدم سبع مرات امام الرب لدى حجاب القدس'),
(23319, 'Leviticus', 3, 4, 7, 'و يجعل الكاهن من الدم على قرون مذبح البخور العطر الذي في خيمة الاجتماع امام الرب و سائر دم الثور يصبه الى اسفل مذبح المحرقة الذي لدى باب خيمة الاجتماع'),
(23320, 'Leviticus', 3, 4, 8, 'و جميع شحم ثور الخطية ينزعه عنه الشحم الذي يغشي الاحشاء و سائر الشحم الذي على الاحشاء'),
(23321, 'Leviticus', 3, 4, 9, 'و الكليتين و الشحم الذي عليهما الذي على الخاصرتين و زيادة الكبد مع الكليتين ينزعها'),
(23322, 'Leviticus', 3, 4, 10, 'كما تنزع من ثور ذبيحة السلامة و يوقدهن الكاهن على مذبح المحرقة'),
(23323, 'Leviticus', 3, 4, 11, 'و اما جلد الثور و كل لحمه مع راسه و اكارعه و احشائه و فرثه'),
(23324, 'Leviticus', 3, 4, 12, 'فيخرج سائر الثور الى خارج المحلة الى مكان طاهر الى مرمى الرماد و يحرقها على حطب بالنار على مرمى الرماد تحرق'),
(23325, 'Leviticus', 3, 4, 13, 'و ان سها كل جماعة اسرائيل و اخفي امر عن اعين المجمع و عملوا واحدة من جميع مناهي الرب التي لا ينبغي عملها و اثموا'),
(23326, 'Leviticus', 3, 4, 14, 'ثم عرفت الخطية التي اخطاوا بها يقرب المجمع ثورا ابن بقر ذبيحة خطية ياتون به الى قدام خيمة الاجتماع'),
(23327, 'Leviticus', 3, 4, 15, 'و يضع شيوخ الجماعة ايديهم على راس الثور امام الرب و يذبح الثور امام الرب'),
(23328, 'Leviticus', 3, 4, 16, 'و يدخل الكاهن الممسوح من دم الثور الى خيمة الاجتماع'),
(23329, 'Leviticus', 3, 4, 17, 'و يغمس الكاهن اصبعه في الدم و ينضح سبع مرات امام الرب لدى الحجاب'),
(23330, 'Leviticus', 3, 4, 18, 'و يجعل من الدم على قرون المذبح الذي امام الرب في خيمة الاجتماع و سائر الدم يصبه الى اسفل مذبح المحرقة الذي لدى باب خيمة الاجتماع'),
(23331, 'Leviticus', 3, 4, 19, 'و جميع شحمه ينزعه عنه و يوقده على المذبح'),
(23332, 'Leviticus', 3, 4, 20, 'و يفعل بالثور كما فعل بثور الخطية كذلك يفعل به و يكفر عنهم الكاهن فيصفح عنهم'),
(23333, 'Leviticus', 3, 4, 21, 'ثم يخرج الثور الى خارج المحلة و يحرقه كما احرق الثور الاول انه ذبيحة خطية المجمع'),
(23334, 'Leviticus', 3, 4, 22, 'اذا اخطا رئيس و عمل بسهو واحدة من جميع مناهي الرب الهه التي لا ينبغي عملها و اثم'),
(23335, 'Leviticus', 3, 4, 23, 'ثم اعلم بخطيته التي اخطا بها ياتي بقربانه تيسا من المعز ذكرا صحيحا'),
(23336, 'Leviticus', 3, 4, 24, 'و يضع يده على راس التيس و يذبحه في الموضع الذي يذبح فيه المحرقة امام الرب انه ذبيحة خطية'),
(23337, 'Leviticus', 3, 4, 25, 'و ياخذ الكاهن من دم ذبيحة الخطية باصبعه و يجعل على قرون مذبح المحرقة ثم يصب دمه الى اسفل مذبح المحرقة'),
(23338, 'Leviticus', 3, 4, 26, 'و جميع شحمه يوقده على المذبح كشحم ذبيحة السلامة و يكفر الكاهن عنه من خطيته فيصفح عنه'),
(23339, 'Leviticus', 3, 4, 27, 'و ان اخطا احد من عامة الارض سهوا بعمله واحدة من مناهي الرب التي لا ينبغي عملها و اثم'),
(23340, 'Leviticus', 3, 4, 28, 'ثم اعلم بخطيته التي اخطا بها ياتي بقربانه عنزا من المعز انثى صحيحة عن خطيته التي اخطا'),
(23341, 'Leviticus', 3, 4, 29, 'و يضع يده على راس ذبيحة الخطية و يذبح ذبيحة الخطية في موضع المحرقة'),
(23342, 'Leviticus', 3, 4, 30, 'و ياخذ الكاهن من دمها باصبعه و يجعل على قرون مذبح المحرقة و يصب سائر دمها الى اسفل المذبح'),
(23343, 'Leviticus', 3, 4, 31, 'و جميع شحمها ينزعه كما نزع الشحم عن ذبيحة السلامة و يوقد الكاهن على المذبح رائحة سرور للرب و يكفر عنه الكاهن فيصفح عنه'),
(23344, 'Leviticus', 3, 4, 32, 'و ان اتى بقربانه من الضان ذبيحة خطية ياتي بها انثى صحيحة'),
(23345, 'Leviticus', 3, 4, 33, 'و يضع يده على راس ذبيحة الخطية و يذبحها ذبيحة خطية في الموضع الذي يذبح فيه المحرقة'),
(23346, 'Leviticus', 3, 4, 34, 'و ياخذ الكاهن من دم ذبيحة الخطية باصبعه و يجعل على قرون مذبح المحرقة و يصب سائر الدم الى اسفل المذبح'),
(23347, 'Leviticus', 3, 4, 35, 'و جميع شحمه ينزعه كما ينزع شحم الضان عن ذبيحة السلامة و يوقده الكاهن على المذبح على وقائد الرب و يكفر عنه الكاهن من خطيته التي اخطا فيصفح عنه'),
(23348, 'Leviticus', 3, 5, 1, 'و اذا اخطا احد و سمع صوت حلف و هو شاهد يبصر او يعرف فان لم يخبر به حمل ذنبه'),
(23349, 'Leviticus', 3, 5, 2, 'او اذا مس احد شيئا نجسا جثة وحش نجس او جثة بهيمة نجسة او جثة دبيب نجس و اخفي عنه فهو نجس و مذنب'),
(23350, 'Leviticus', 3, 5, 3, 'او اذا مس نجاسة انسان من جميع نجاساته التي يتنجس بها و اخفي عنه ثم علم فهو مذنب'),
(23351, 'Leviticus', 3, 5, 4, 'او اذا حلف احد مفترطا بشفتيه للاساءة او للاحسان من جميع ما يفترط به الانسان في اليمين و اخفي عنه ثم علم فهو مذنب في شيء من ذلك'),
(23352, 'Leviticus', 3, 5, 5, 'فان كان يذنب في شيء من هذه يقر بما قد اخطا به'),
(23353, 'Leviticus', 3, 5, 6, 'و ياتي الى الرب بذبيحة لاثمه عن خطيته التي اخطا بها انثى من الاغنام نعجة او عنزا من المعز ذبيحة خطية فيكفر عنه الكاهن من خطيته'),
(23354, 'Leviticus', 3, 5, 7, 'و ان لم تنل يده كفاية لشاة فياتي بذبيحة لاثمه الذي اخطا به يمامتين او فرخي حمام الى الرب احدهما ذبيحة خطية و الاخر محرقة'),
(23355, 'Leviticus', 3, 5, 8, 'ياتي بهما الى الكاهن فيقرب الذي للخطية اولا يحز راسه من قفاه و لا يفصله'),
(23356, 'Leviticus', 3, 5, 9, 'و ينضح من دم ذبيحة الخطية على حائط المذبح و الباقي من الدم يعصر الى اسفل المذبح انه ذبيحة خطية'),
(23357, 'Leviticus', 3, 5, 10, 'و اما الثاني فيعمله محرقة كالعادة فيكفر عنه الكاهن من خطيته التي اخطا فيصفح عنه'),
(23358, 'Leviticus', 3, 5, 11, 'و ان لم تنل يده يمامتين او فرخي حمام فياتي بقربانه عما اخطا به عشر الايفة من دقيق قربان خطية لا يضع عليه زيتا و لا يجعل عليه لبانا لانه قربان خطية'),
(23359, 'Leviticus', 3, 5, 12, 'ياتي به الى الكاهن فيقبض الكاهن منه ملء قبضته تذكاره و يوقده على المذبح على وقائد الرب انه قربان خطية'),
(23360, 'Leviticus', 3, 5, 13, 'فيكفر عنه الكاهن من خطيته التي اخطا بها في واحدة من ذلك فيصفح عنه و يكون للكاهن كالتقدمة'),
(23361, 'Leviticus', 3, 5, 14, 'و كلم الرب موسى قائلا'),
(23362, 'Leviticus', 3, 5, 15, 'اذا خان احد خيانة و اخطا سهوا في اقداس الرب ياتي الى الرب بذبيحة لاثمه كبشا صحيحا من الغنم بتقويمك من شواقل فضة على شاقل القدس ذبيحة اثم'),
(23363, 'Luke', 42, 1, 69, ' وأقام لنا قرن خلاص في بيت داود فتاه '),
(23364, 'Luke', 42, 1, 70, ' كما تكلم بفم أنبيائه القديسين الذين هم منذ الدهر '),
(23365, 'Luke', 42, 1, 71, ' خلاص من أعدائنا ومن أيدي جميع مبغضينا '),
(23366, 'Luke', 42, 1, 72, ' ليصنع رحمة مع آبائنا ويذكر عهده المقدس '),
(23367, 'Luke', 42, 1, 73, ' القسم الذي حلف لإبراهيم أبينا '),
(23368, 'Luke', 42, 1, 74, ' أن يعطينا إننا بلا خوف ، منقذين من أيدي أعدائنا ، نعبده '),
(23369, 'Luke', 42, 1, 75, ' بقداسة وبر قدامه جميع أيام حياتنا '),
(23370, 'Luke', 42, 1, 76, ' وأنت أيها الصبي نبي العلي تدعى ، لأنك تتقدم أمام وجه الرب لتعد طرقه '),
(23371, 'Luke', 42, 1, 77, ' لتعطي شعبه معرفة الخلاص بمغفرة خطاياهم '),
(23372, 'Luke', 42, 1, 78, ' بأحشاء رحمة إلهنا التي بها افتقدنا المشرق من العلاء '),
(23373, 'Luke', 42, 1, 79, ' ليضيء على الجالسين في الظلمة وظلال الموت ، لكي يهدي أقدامنا في طريق السلام '),
(23374, 'Luke', 42, 1, 80, ' أما الصبي فكان ينمو ويتقوى بالروح ، وكان في البراري إلى يوم ظهوره لإسرائيل '),
(23375, 'Luke', 42, 2, 1, ' وفي تلك الأيام صدر أمر من أوغسطس قيصر بأن يكتتب كل المسكونة '),
(23376, 'Luke', 42, 2, 2, ' وهذا الاكتتاب الأول جرى إذ كان كيرينيوس والي سورية '),
(23377, 'Luke', 42, 2, 3, ' فذهب الجميع ليكتتبوا ، كل واحد إلى مدينته '),
(23378, 'Luke', 42, 2, 4, ' فصعد يوسف أيضا من الجليل من مدينة الناصرة إلى اليهودية ، إلى مدينة داود التي تدعى بيت لحم ، لكونه من بيت داود وعشيرته '),
(23379, 'Luke', 42, 2, 5, ' ليكتتب مع مريم امرأته المخطوبة وهي حبلى '),
(23380, 'Luke', 42, 2, 6, ' وبينما هما هناك تمت أيامها لتلد '),
(23381, 'Luke', 42, 2, 7, ' فولدت ابنها البكر وقمطته وأضجعته في المذود ، إذ لم يكن لهما موضع في المنزل '),
(23382, 'Luke', 42, 2, 8, ' وكان في تلك الكورة رعاة متبدين يحرسون حراسات الليل على رعيتهم '),
(23383, 'Luke', 42, 2, 9, ' وإذا ملاك الرب وقف بهم ، ومجد الرب أضاء حولهم ، فخافوا خوفا عظيما '),
(23384, 'Luke', 42, 2, 10, ' فقال لهم الملاك : لا تخافوا فها أنا أبشركم بفرح عظيم يكون لجميع الشعب '),
(23385, 'Luke', 42, 2, 11, ' أنه ولد لكم اليوم في مدينة داود مخلص هو المسيح الرب '),
(23386, 'Luke', 42, 2, 12, ' وهذه لكم العلامة : تجدون طفلا مقمطا مضجعا في مذود '),
(23387, 'Luke', 42, 2, 13, ' وظهر بغتة مع الملاك جمهور من الجند السماوي مسبحين الله وقائلين '),
(23388, 'Luke', 42, 2, 14, ' المجد لله في الأعالي ، وعلى الأرض السلام ، وبالناس المسرة '),
(23389, 'Luke', 42, 2, 15, ' ولما مضت عنهم الملائكة إلى السماء ، قال الرجال الرعاة بعضهم لبعض : لنذهب الآن إلى بيت لحم وننظر هذا الأمر الواقع الذي أعلمنا به الرب '),
(23390, 'Luke', 42, 2, 16, ' فجاءوا مسرعين ، ووجدوا مريم ويوسف والطفل مضجعا في المذود '),
(23391, 'Luke', 42, 2, 17, ' فلما رأوه أخبروا بالكلام الذي قيل لهم عن هذا الصبي '),
(23392, 'Luke', 42, 2, 18, ' وكل الذين سمعوا تعجبوا مما قيل لهم من الرعاة '),
(23393, 'Luke', 42, 2, 19, ' وأما مريم فكانت تحفظ جميع هذا الكلام متفكرة به في قلبها '),
(23394, 'Luke', 42, 2, 20, ' ثم رجع الرعاة وهم يمجدون الله ويسبحونه على كل ما سمعوه ورأوه كما قيل لهم '),
(23395, 'Luke', 42, 2, 21, ' ولما تمت ثمانية أيام ليختنوا الصبي سمي يسوع ، كما تسمى من الملاك قبل أن حبل به في البطن '),
(23396, 'Luke', 42, 2, 22, ' ولما تمت أيام تطهيرها ، حسب شريعة موسى ، صعدوا به إلى أورشليم ليقدموه للرب '),
(23397, 'Luke', 42, 2, 23, ' كما هو مكتوب في ناموس الرب : أن كل ذكر فاتح رحم يدعى قدوسا للرب '),
(23398, 'Luke', 42, 2, 24, ' ولكي يقدموا ذبيحة كما قيل في ناموس الرب : زوج يمام أو فرخي حمام '),
(23399, 'Luke', 42, 2, 25, ' وكان رجل في أورشليم اسمه سمعان ، وهذا الرجل كان بارا تقيا ينتظر تعزية إسرائيل ، والروح القدس كان عليه '),
(23400, 'Luke', 42, 2, 26, ' وكان قد أوحي إليه بالروح القدس أنه لا يرى الموت قبل أن يرى مسيح الرب '),
(23401, 'Luke', 42, 2, 27, ' فأتى بالروح إلى الهيكل . وعندما دخل بالصبي يسوع أبواه ، ليصنعا له حسب عادة الناموس '),
(23402, 'Luke', 42, 2, 28, ' أخذه على ذراعيه وبارك الله وقال '),
(23403, 'Luke', 42, 2, 29, ' الآن تطلق عبدك يا سيد حسب قولك بسلام '),
(23404, 'Luke', 42, 2, 30, ' لأن عيني قد أبصرتا خلاصك '),
(23405, 'Luke', 42, 2, 31, ' الذي أعددته قدام وجه جميع الشعوب '),
(23406, 'Luke', 42, 2, 32, ' نور إعلان للأمم ، ومجدا لشعبك إسرائيل '),
(23407, 'Luke', 42, 2, 33, ' وكان يوسف وأمه يتعجبان مما قيل فيه '),
(23408, 'Luke', 42, 2, 34, ' وباركهما سمعان ، وقال لمريم أمه : ها إن هذا قد وضع لسقوط وقيام كثيرين في إسرائيل ، ولعلامة تقاوم '),
(23409, 'Luke', 42, 2, 35, ' وأنت أيضا يجوز في نفسك سيف ، لتعلن أفكار من قلوب كثيرة '),
(23410, 'Luke', 42, 2, 36, ' وكانت نبية ، حنة بنت فنوئيل من سبط أشير ، وهي متقدمة في أيام كثيرة ، قد عاشت مع زوج سبع سنين بعد بكوريتها '),
(23411, 'Luke', 42, 2, 37, ' وهي أرملة نحو أربع وثمانين سنة ، لا تفارق الهيكل ، عابدة بأصوام وطلبات ليلا ونهارا '),
(23412, 'Luke', 42, 2, 38, ' فهي في تلك الساعة وقفت تسبح الرب ، وتكلمت عنه مع جميع المنتظرين فداء في أورشليم '),
(23413, 'Luke', 42, 2, 39, ' ولما أكملوا كل شيء حسب ناموس الرب ، رجعوا إلى الجليل إلى مدينتهم الناصرة '),
(23414, 'Luke', 42, 2, 40, ' وكان الصبي ينمو ويتقوى بالروح ، ممتلئا حكمة ، وكانت نعمة الله عليه '),
(23415, 'Luke', 42, 2, 41, ' وكان أبواه يذهبان كل سنة إلى أورشليم في عيد الفصح '),
(23416, 'Luke', 42, 2, 42, ' ولما كانت له اثنتا عشرة سنة صعدوا إلى أورشليم كعادة العيد '),
(23417, 'Luke', 42, 2, 43, ' وبعدما أكملوا الأيام بقي عند رجوعهما الصبي يسوع في أورشليم ، ويوسف وأمه لم يعلما '),
(23418, 'Luke', 42, 2, 44, ' وإذ ظناه بين الرفقة ، ذهبا مسيرة يوم ، وكانا يطلبانه بين الأقرباء والمعارف '),
(23419, 'Luke', 42, 2, 45, ' ولما لم يجداه رجعا إلى أورشليم يطلبانه '),
(23420, 'Luke', 42, 2, 46, ' وبعد ثلاثة أيام وجداه في الهيكل ، جالسا في وسط المعلمين ، يسمعهم ويسألهم '),
(23421, 'Luke', 42, 2, 47, ' وكل الذين سمعوه بهتوا من فهمه وأجوبته '),
(23422, 'Luke', 42, 2, 48, ' فلما أبصراه اندهشا . وقالت له أمه : يا بني ، لماذا فعلت بنا هكذا ؟ هوذا أبوك وأنا كنا نطلبك معذبين '),
(23423, 'Luke', 42, 2, 49, ' فقال لهما : لماذا كنتما تطلبانني ؟ ألم تعلما أنه ينبغي أن أكون في ما لأبي '),
(23424, 'Luke', 42, 2, 50, ' فلم يفهما الكلام الذي قاله لهما '),
(23425, 'Luke', 42, 2, 51, ' ثم نزل معهما وجاء إلى الناصرة وكان خاضعا لهما . وكانت أمه تحفظ جميع هذه الأمور في قلبها '),
(23426, 'Luke', 42, 2, 52, ' وأما يسوع فكان يتقدم في الحكمة والقامة والنعمة ، عند الله والناس '),
(23427, 'Luke', 42, 3, 1, ' وفي السنة الخامسة عشرة من سلطنة طيباريوس قيصر ، إذ كان بيلاطس البنطي واليا على اليهودية ، وهيرودس رئيس ربع على الجليل ، وفيلبس أخوه رئيس ربع على إيطورية وكورة تراخونيتس ، وليسانيوس رئيس ربع على الأبلية '),
(23428, 'Luke', 42, 3, 2, ' في أيام رئيس الكهنة حنان وقيافا ، كانت كلمة الله على يوحنا بن زكريا في البرية '),
(23429, 'Luke', 42, 3, 3, ' فجاء إلى جميع الكورة المحيطة بالأردن يكرز بمعمودية التوبة لمغفرة الخطايا '),
(23430, 'Luke', 42, 3, 4, ' كما هو مكتوب في سفر أقوال إشعياء النبي القائل : صوت صارخ في البرية : أعدوا طريق الرب ، اصنعوا سبله مستقيمة '),
(23431, 'Luke', 42, 3, 5, ' كل واد يمتلئ ، وكل جبل وأكمة ينخفض ، وتصير المعوجات مستقيمة ، والشعاب طرقا سهلة '),
(23432, 'Luke', 42, 3, 6, ' ويبصر كل بشر خلاص الله '),
(23433, 'Luke', 42, 3, 7, ' وكان يقول للجموع الذين خرجوا ليعتمدوا منه : يا أولاد الأفاعي ، من أراكم أن تهربوا من الغضب الآتي '),
(23434, 'Luke', 42, 3, 8, ' فاصنعوا أثمارا تليق بالتوبة . ولا تبتدئوا تقولون في أنفسكم : لنا إبراهيم أبا . لأني أقول لكم : إن الله قادر أن يقيم من هذه الحجارة أولادا لإبراهيم '),
(23435, 'Luke', 42, 3, 9, ' والآن قد وضعت الفأس على أصل الشجر ، فكل شجرة لا تصنع ثمرا جيدا تقطع وتلقى في النار '),
(23436, 'Luke', 42, 3, 10, ' وسأله الجموع قائلين : فماذا نفعل '),
(23437, 'Luke', 42, 3, 11, ' فأجاب وقال لهم : من له ثوبان فليعط من ليس له ، ومن له طعام فليفعل هكذا '),
(23438, 'Luke', 42, 3, 12, ' وجاء عشارون أيضا ليعتمدوا فقالوا له : يا معلم ، ماذا نفعل '),
(23439, 'Luke', 42, 3, 13, ' فقال لهم : لا تستوفوا أكثر مما فرض لكم '),
(23440, 'Luke', 42, 3, 14, ' وسأله جنديون أيضا قائلين : وماذا نفعل نحن ؟ فقال لهم : لا تظلموا أحدا ، ولا تشوا بأحد ، واكتفوا بعلائفكم '),
(23441, 'Luke', 42, 3, 15, ' وإذ كان الشعب ينتظر ، والجميع يفكرون في قلوبهم عن يوحنا لعله المسيح '),
(23442, 'Luke', 42, 3, 16, ' أجاب يوحنا الجميع قائلا : أنا أعمدكم بماء ، ولكن يأتي من هو أقوى مني ، الذي لست أهلا أن أحل سيور حذائه . هو سيعمدكم بالروح القدس ونار '),
(23443, 'Luke', 42, 3, 17, ' الذي رفشه في يده ، وسينقي بيدره ، ويجمع القمح إلى مخزنه ، وأما التبن فيحرقه بنار لا تطفأ '),
(23444, 'Luke', 42, 3, 18, ' وبأشياء أخر كثيرة كان يعظ الشعب ويبشرهم '),
(23445, 'Luke', 42, 3, 19, ' أما هيرودس رئيس الربع فإذ توبخ منه لسبب هيروديا امرأة فيلبس أخيه ، ولسبب جميع الشرور التي كان هيرودس يفعلها '),
(23446, 'Luke', 42, 3, 20, ' زاد هذا أيضا على الجميع أنه حبس يوحنا في السجن '),
(23447, 'Luke', 42, 3, 21, ' ولما اعتمد جميع الشعب اعتمد يسوع أيضا . وإذ كان يصلي انفتحت السماء '),
(23448, 'Luke', 42, 3, 22, ' ونزل عليه الروح القدس بهيئة جسمية مثل حمامة . وكان صوت من السماء قائلا : أنت ابني الحبيب ، بك سررت '),
(23449, 'Luke', 42, 3, 23, ' ولما ابتدأ يسوع كان له نحو ثلاثين سنة ، وهو على ما كان يظن ابن يوسف ، بن هالي '),
(23450, 'Luke', 42, 3, 24, ' بن متثات ، بن لاوي ، بن ملكي ، بن ينا ، بن يوسف '),
(23451, 'Luke', 42, 3, 25, ' بن متاثيا ، بن عاموص ، بن ناحوم ، بن حسلي ، بن نجاي '),
(23452, 'Luke', 42, 3, 26, ' بن مآث ، بن متاثيا ، بن شمعي ، بن يوسف ، بن يهوذا '),
(23453, 'Luke', 42, 3, 27, ' بن يوحنا ، بن ريسا ، بن زربابل ، بن شألتيئيل ، بن نيري '),
(23454, 'Luke', 42, 3, 28, ' بن ملكي ، بن أدي ، بن قصم ، بن ألمودام ، بن عير '),
(23455, 'Luke', 42, 3, 29, ' بن يوسي ، بن أليعازر ، بن يوريم ، بن متثات ، بن لاوي '),
(23456, 'Luke', 42, 3, 30, ' بن شمعون ، بن يهوذا ، بن يوسف ، بن يونان ، بن ألياقيم '),
(23457, 'Luke', 42, 3, 31, ' بن مليا ، بن مينان ، بن متاثا ، بن ناثان ، بن داود '),
(23458, 'Luke', 42, 3, 32, ' بن يسى ، بن عوبيد ، بن بوعز ، بن سلمون ، بن نحشون '),
(23459, 'Luke', 42, 3, 33, ' بن عميناداب ، بن أرام ، بن حصرون ، بن فارص ، بن يهوذا '),
(23460, 'Luke', 42, 3, 34, ' بن يعقوب ، بن إسحاق ، بن إبراهيم ، بن تارح ، بن ناحور '),
(23461, 'Luke', 42, 3, 35, ' بن سروج ، بن رعو ، بن فالج ، بن عابر ، بن شالح '),
(23462, 'Luke', 42, 3, 36, ' بن قينان ، بن أرفكشاد ، بن سام ، بن نوح ، بن لامك '),
(23463, 'Luke', 42, 3, 37, ' بن متوشالح ، بن أخنوخ ، بن يارد ، بن مهللئيل ، بن قينان '),
(23464, 'Luke', 42, 3, 38, ' بن أنوش ، بن شيت ، بن آدم ، ابن الله '),
(23465, 'Luke', 42, 4, 1, ' أما يسوع فرجع من الأردن ممتلئا من الروح القدس ، وكان يقتاد بالروح في البرية '),
(23466, 'Luke', 42, 4, 2, ' أربعين يوما يجرب من إبليس . ولم يأكل شيئا في تلك الأيام . ولما تمت جاع أخيرا '),
(23467, 'Luke', 42, 4, 3, ' وقال له إبليس : إن كنت ابن الله ، فقل لهذا الحجر أن يصير خبزا '),
(23468, 'Luke', 42, 4, 4, ' فأجابه يسوع قائلا : مكتوب : أن ليس بالخبز وحده يحيا الإنسان ، بل بكل كلمة من الله '),
(23469, 'Luke', 42, 4, 5, ' ثم أصعده إبليس إلى جبل عال وأراه جميع ممالك المسكونة في لحظة من الزمان '),
(23470, 'Luke', 42, 4, 6, ' وقال له إبليس : لك أعطي هذا السلطان كله ومجدهن ، لأنه إلي قد دفع ، وأنا أعطيه لمن أريد '),
(23471, 'Luke', 42, 4, 7, ' فإن سجدت أمامي يكون لك الجميع '),
(23472, 'Luke', 42, 4, 8, ' فأجابه يسوع وقال : اذهب يا شيطان إنه مكتوب : للرب إلهك تسجد وإياه حده تعبد '),
(23473, 'Luke', 42, 4, 9, ' ثم جاء به إلى أورشليم ، وأقامه على جناح الهيكل وقال له : إن كنت ابن الله فاطرح نفسك من هنا إلى أسفل '),
(23474, 'Luke', 42, 4, 10, ' لأنه مكتوب : أنه يوصي ملائكته بك لكي يحفظوك '),
(23475, 'Luke', 42, 4, 11, ' وأنهم على أياديهم يحملونك لكي لا تصدم بحجر رجلك '),
(23476, 'Luke', 42, 4, 12, ' فأجاب يسوع وقال له : إنه قيل : لا تجرب الرب إلهك '),
(23477, 'Luke', 42, 4, 13, ' ولما أكمل إبليس كل تجربة فارقه إلى حين '),
(23478, 'Luke', 42, 4, 14, ' ورجع يسوع بقوة الروح إلى الجليل ، وخرج خبر عنه في جميع الكورة المحيطة '),
(23479, 'Luke', 42, 4, 15, ' وكان يعلم في مجامعهم ممجدا من الجميع '),
(23480, 'Luke', 42, 4, 16, ' وجاء إلى الناصرة حيث كان قد تربى . ودخل المجمع حسب عادته يوم السبت وقام ليقرأ '),
(23481, 'Luke', 42, 4, 17, ' فدفع إليه سفر إشعياء النبي . ولما فتح السفر وجد الموضع الذي كان مكتوبا فيه '),
(23482, 'Luke', 42, 4, 18, ' روح الرب علي ، لأنه مسحني لأبشر المساكين ، أرسلني لأشفي المنكسري القلوب ، لأنادي للمأسورين بالإطلاق وللعمي بالبصر ، وأرسل المنسحقين في الحرية '),
(23483, 'Luke', 42, 4, 19, ' وأكرز بسنة الرب المقبولة '),
(23484, 'Luke', 42, 4, 20, ' ثم طوى السفر وسلمه إلى الخادم ، وجلس . وجميع الذين في المجمع كانت عيونهم شاخصة إليه '),
(23485, 'Luke', 42, 4, 21, ' فابتدأ يقول لهم : إنه اليوم قد تم هذا المكتوب في مسامعكم '),
(23486, 'Luke', 42, 4, 22, ' وكان الجميع يشهدون له ويتعجبون من كلمات النعمة الخارجة من فمه ، ويقولون : أليس هذا ابن يوسف '),
(23487, 'Luke', 42, 4, 23, ' فقال لهم : على كل حال تقولون لي هذا المثل : أيها الطبيب اشف نفسك كم سمعنا أنه جرى في كفرناحوم ، فافعل ذلك هنا أيضا في وطنك '),
(23488, 'Luke', 42, 4, 24, ' وقال : الحق أقول لكم : إنه ليس نبي مقبولا في وطنه '),
(23489, 'Luke', 42, 4, 25, ' وبالحق أقول لكم : إن أرامل كثيرة كن في إسرائيل في أيام إيليا حين أغلقت السماء مدة ثلاث سنين وستة أشهر ، لما كان جوع عظيم في الأرض كلها '),
(23490, 'Luke', 42, 4, 26, ' ولم يرسل إيليا إلى واحدة منها ، إلا إلى امرأة أرملة ، إلى صرفة صيداء '),
(23491, 'Luke', 42, 4, 27, ' وبرص كثيرون كانوا في إسرائيل في زمان أليشع النبي ، ولم يطهر واحد منهم إلا نعمان السرياني '),
(23492, 'Luke', 42, 4, 28, ' فامتلأ غضبا جميع الذين في المجمع حين سمعوا هذا '),
(23493, 'Luke', 42, 7, 3, ' فلما سمع عن يسوع ، أرسل إليه شيوخ اليهود يسأله أن يأتي ويشفي عبده '),
(23494, 'Luke', 42, 7, 4, ' فلما جاءوا إلى يسوع طلبوا إليه باجتهاد قائلين : إنه مستحق أن يفعل له هذا '),
(23495, 'Luke', 42, 7, 5, ' لأنه يحب أمتنا ، وهو بنى لنا المجمع '),
(23496, 'Luke', 42, 7, 6, ' فذهب يسوع معهم . وإذ كان غير بعيد عن البيت ، أرسل إليه قائد المئة أصدقاء يقول له يا سيد ، لا تتعب . لأني لست مستحقا أن تدخل تحت سقفي '),
(23497, 'Luke', 42, 7, 7, ' لذلك لم أحسب نفسي أهلا أن آتي إليك . لكن قل كلمة فيبرأ غلامي '),
(23498, 'Luke', 42, 7, 8, ' لأني أنا أيضا إنسان مرتب تحت سلطان ، لي جند تحت يدي . وأقول لهذا : اذهب فيذهب ، ولآخر : ائت فيأتي ، ولعبدي : افعل هذا فيفعل '),
(23499, 'Luke', 42, 7, 9, ' ولما سمع يسوع هذا تعجب منه ، والتفت إلى الجمع الذي يتبعه وقال : أقول لكم : لم أجد ولا في إسرائيل إيمانا بمقدار هذا '),
(23500, 'Luke', 42, 7, 10, ' ورجع المرسلون إلى البيت ، فوجدوا العبد المريض قد صح '),
(23501, 'Luke', 42, 7, 11, ' وفي اليوم التالي ذهب إلى مدينة تدعى نايين ، وذهب معه كثيرون من تلاميذه وجمع كثير '),
(23502, 'Luke', 42, 7, 12, ' فلما اقترب إلى باب المدينة ، إذا ميت محمول ، ابن وحيد لأمه ، وهي أرملة ومعها جمع كثير من المدينة '),
(23503, 'Luke', 42, 7, 13, ' فلما رآها الرب تحنن عليها ، وقال لها : لا تبكي '),
(23504, 'Luke', 42, 7, 14, ' ثم تقدم ولمس النعش ، فوقف الحاملون . فقال : أيها الشاب ، لك أقول : قم '),
(23505, 'Luke', 42, 7, 15, ' فجلس الميت وابتدأ يتكلم ، فدفعه إلى أمه '),
(23506, 'Luke', 42, 7, 16, ' فأخذ الجميع خوف ، ومجدوا الله قائلين : قد قام فينا نبي عظيم ، وافتقد الله شعبه '),
(23507, 'Luke', 42, 7, 17, ' وخرج هذا الخبر عنه في كل اليهودية وفي جميع الكورة المحيطة '),
(23508, 'Luke', 42, 7, 18, ' فأخبر يوحنا تلاميذه بهذا كله '),
(23509, 'Luke', 42, 7, 19, ' فدعا يوحنا اثنين من تلاميذه ، وأرسل إلى يسوع قائلا : أنت هو الآتي أم ننتظر آخر '),
(23510, 'Luke', 42, 7, 20, ' فلما جاء إليه الرجلان قالا : يوحنا المعمدان قد أرسلنا إليك قائلا : أنت هو الآتي أم ننتظر آخر '),
(23511, 'Luke', 42, 7, 21, ' وفي تلك الساعة شفى كثيرين من أمراض وأدواء وأرواح شريرة ، ووهب البصر لعميان كثيرين '),
(23512, 'Luke', 42, 7, 22, ' فأجاب يسوع وقال لهما : اذهبا وأخبرا يوحنا بما رأيتما وسمعتما : إن العمي يبصرون ، والعرج يمشون ، والبرص يطهرون ، والصم يسمعون ، والموتى يقومون ، والمساكين يبشرون '),
(23513, 'Luke', 42, 7, 23, ' وطوبى لمن لا يعثر في '),
(23514, 'Luke', 42, 7, 24, ' فلما مضى رسولا يوحنا ، ابتدأ يقول للجموع عن يوحنا : ماذا خرجتم إلى البرية لتنظروا ؟ أقصبة تحركها الريح '),
(23515, 'Luke', 42, 7, 25, ' بل ماذا خرجتم لتنظروا ؟ أإنسانا لابسا ثيابا ناعمة ؟ هوذا الذين في اللباس الفاخر والتنعم هم في قصور الملوك '),
(23516, 'Luke', 42, 7, 26, ' بل ماذا خرجتم لتنظروا ؟ أنبيا ؟ نعم ، أقول لكم : وأفضل من نبي '),
(23517, 'Luke', 42, 7, 27, ' هذا هو الذي كتب عنه : ها أنا أرسل أمام وجهك ملاكي الذي يهيئ طريقك قدامك '),
(23518, 'Luke', 42, 7, 28, ' لأني أقول لكم : إنه بين المولودين من النساء ليس نبي أعظم من يوحنا المعمدان ، ولكن الأصغر في ملكوت الله أعظم منه '),
(23519, 'Luke', 42, 7, 29, ' وجميع الشعب إذ سمعوا والعشارون برروا الله معتمدين بمعمودية يوحنا '),
(23520, 'Luke', 42, 7, 30, ' وأما الفريسيون والناموسيون فرفضوا مشورة الله من جهة أنفسهم ، غير معتمدين منه '),
(23521, 'Luke', 42, 7, 31, ' ثم قال الرب : فبمن أشبه أناس هذا الجيل ؟ وماذا يشبهون '),
(23522, 'Luke', 42, 7, 32, ' يشبهون أولادا جالسين في السوق ينادون بعضهم بعضا ويقولون : زمرنا لكم فلم ترقصوا . نحنا لكم فلم تبكوا '),
(23523, 'Luke', 42, 7, 33, ' لأنه جاء يوحنا المعمدان لا يأكل خبزا ولا يشرب خمرا ، فتقولون : به شيطان '),
(23524, 'Luke', 42, 7, 34, ' جاء ابن الإنسان يأكل ويشرب ، فتقولون : هوذا إنسان أكول وشريب خمر ، محب للعشارين والخطاة '),
(23525, 'Luke', 42, 7, 35, ' والحكمة تبررت من جميع بنيها '),
(23526, 'Luke', 42, 7, 36, ' وسأله واحد من الفريسيين أن يأكل معه ، فدخل بيت الفريسي واتكأ '),
(23527, 'Luke', 42, 7, 37, ' وإذا امرأة في المدينة كانت خاطئة ، إذ علمت أنه متكئ في بيت الفريسي ، جاءت بقارورة طيب '),
(23528, 'Luke', 42, 7, 38, ' ووقفت عند قدميه من ورائه باكية ، وابتدأت تبل قدميه بالدموع ، وكانت تمسحهما بشعر رأسها ، وتقبل قدميه وتدهنهما بالطيب '),
(23529, 'Luke', 42, 7, 39, ' فلما رأى الفريسي الذي دعاه ذلك ، تكلم في نفسه قائلا : لو كان هذا نبيا ، لعلم من هذه الامرأة التي تلمسه وما هي إنها خاطئة '),
(23530, 'Luke', 42, 7, 40, ' فأجاب يسوع وقال له : يا سمعان ، عندي شيء أقوله لك . فقال : قل ، يا معلم '),
(23531, 'Luke', 42, 7, 41, ' كان لمداين مديونان . على الواحد خمسمئة دينار وعلى الآخر خمسون '),
(23532, 'Luke', 42, 7, 42, ' وإذ لم يكن لهما ما يوفيان سامحهما جميعا . فقل : أيهما يكون أكثر حبا له '),
(23533, 'Luke', 42, 7, 43, ' فأجاب سمعان وقال : أظن الذي سامحه بالأكثر . فقال له : بالصواب حكمت '),
(23534, 'Luke', 42, 7, 44, ' ثم التفت إلى المرأة وقال لسمعان : أتنظر هذه المرأة ؟ إني دخلت بيتك ، وماء لأجل رجلي لم تعط . وأما هي فقد غسلت رجلي بالدموع ومسحتهما بشعر رأسها '),
(23535, 'Luke', 42, 7, 45, ' قبلة لم تقبلني ، وأما هي فمنذ دخلت لم تكف عن تقبيل رجلي '),
(23536, 'Luke', 42, 7, 46, ' بزيت لم تدهن رأسي ، وأما هي فقد دهنت بالطيب رجلي '),
(23537, 'Luke', 42, 7, 47, ' من أجل ذلك أقول لك : قد غفرت خطاياها الكثيرة ، لأنها أحبت كثيرا . والذي يغفر له قليل يحب قليلا '),
(23538, 'Luke', 42, 7, 48, ' ثم قال لها : مغفورة لك خطاياك '),
(23539, 'Luke', 42, 7, 49, ' فابتدأ المتكئون معه يقولون في أنفسهم : من هذا الذي يغفر خطايا أيضا '),
(23540, 'Luke', 42, 7, 50, ' فقال للمرأة : إيمانك قد خلصك ، اذهبي بسلام '),
(23541, 'Luke', 42, 8, 1, ' وعلى أثر ذلك كان يسير في مدينة وقرية يكرز ويبشر بملكوت الله ، ومعه الاثنا عشر '),
(23542, 'Luke', 42, 8, 2, ' وبعض النساء كن قد شفين من أرواح شريرة وأمراض : مريم التي تدعى المجدلية التي خرج منها سبعة شياطين '),
(23543, 'Luke', 42, 8, 3, ' ويونا امرأة خوزي وكيل هيرودس ، وسوسنة ، وأخر كثيرات كن يخدمنه من أموالهن '),
(23544, 'Luke', 42, 8, 4, ' فلما اجتمع جمع كثير أيضا من الذين جاءوا إليه من كل مدينة ، قال بمثل '),
(23545, 'Luke', 42, 8, 5, ' خرج الزارع ليزرع زرعه . وفيما هو يزرع سقط بعض على الطريق ، فانداس وأكلته طيور السماء '),
(23546, 'Luke', 42, 8, 6, ' وسقط آخر على الصخر ، فلما نبت جف لأنه لم تكن له رطوبة '),
(23547, 'Luke', 42, 8, 7, ' وسقط آخر في وسط الشوك ، فنبت معه الشوك وخنقه '),
(23548, 'Luke', 42, 8, 8, ' وسقط آخر في الأرض الصالحة ، فلما نبت صنع ثمرا مئة ضعف . قال هذا ونادى : من له أذنان للسمع فليسمع '),
(23549, 'Luke', 42, 8, 9, ' فسأله تلاميذه قائلين : ما عسى أن يكون هذا المثل '),
(23550, 'Luke', 42, 8, 10, ' فقال : لكم قد أعطي أن تعرفوا أسرار ملكوت الله ، وأما للباقين فبأمثال ، حتى إنهم : مبصرين لا يبصرون ، وسامعين لا يفهمون '),
(23551, 'Luke', 42, 8, 11, ' وهذا هو المثل : الزرع هو كلام الله '),
(23552, 'Luke', 42, 8, 12, ' والذين على الطريق هم الذين يسمعون ، ثم يأتي إبليس وينزع الكلمة من قلوبهم لئلا يؤمنوا فيخلصوا '),
(23553, 'Luke', 42, 8, 13, ' والذين على الصخر هم الذين متى سمعوا يقبلون الكلمة بفرح ، وهؤلاء ليس لهم أصل ، فيؤمنون إلى حين ، وفي وقت التجربة يرتدون '),
(23554, 'Luke', 42, 8, 14, ' والذي سقط بين الشوك هم الذين يسمعون ، ثم يذهبون فيختنقون من هموم الحياة وغناها ولذاتها ، ولا ينضجون ثمرا '),
(23555, 'Luke', 42, 8, 15, ' والذي في الأرض الجيدة ، هو الذين يسمعون الكلمة فيحفظونها في قلب جيد صالح ، ويثمرون بالصبر '),
(23556, 'Luke', 42, 8, 16, ' وليس أحد يوقد سراجا ويغطيه بإناء أو يضعه تحت سرير ، بل يضعه على منارة ، لينظر الداخلون النور '),
(23557, 'Luke', 42, 8, 17, ' لأنه ليس خفي لا يظهر ، ولا مكتوم لا يعلم ويعلن '),
(23558, 'Luke', 42, 8, 18, ' فانظروا كيف تسمعون ، لأن من له سيعطى ، ومن ليس له فالذي يظنه له يؤخذ منه '),
(23559, 'Luke', 42, 8, 19, ' وجاء إليه أمه وإخوته ، ولم يقدروا أن يصلوا إليه لسبب الجمع '),
(23560, 'Luke', 42, 8, 20, ' فأخبروه قائلين : أمك وإخوتك واقفون خارجا ، يريدون أن يروك '),
(23561, 'Luke', 42, 8, 21, ' فأجاب وقال لهم : أمي وإخوتي هم الذين يسمعون كلمة الله ويعملون بها '),
(23562, 'Luke', 42, 8, 22, ' وفي أحد الأيام دخل سفينة هو وتلاميذه ، فقال لهم : لنعبر إلى عبر البحيرة . فأقلعوا '),
(23563, 'Luke', 42, 8, 23, ' وفيما هم سائرون نام . فنزل نوء ريح في البحيرة ، وكانوا يمتلئون ماء وصاروا في خطر '),
(23564, 'Luke', 42, 8, 24, ' فتقدموا وأيقظوه قائلين : يا معلم ، يا معلم ، إننا نهلك . فقام وانتهر الريح وتموج الماء ، فانتهيا وصار هدو '),
(23565, 'Luke', 42, 8, 25, ' ثم قال لهم : أين إيمانكم ؟ فخافوا وتعجبوا قائلين فيما بينهم : من هو هذا ؟ فإنه يأمر الرياح أيضا والماء فتطيعه '),
(23566, 'Luke', 42, 8, 26, ' وساروا إلى كورة الجدريين التي هي مقابل الجليل '),
(23567, 'Luke', 42, 8, 27, ' ولما خرج إلى الأرض استقبله رجل من المدينة كان فيه شياطين منذ زمان طويل ، وكان لا يلبس ثوبا ، ولا يقيم في بيت ، بل في القبور '),
(23568, 'Luke', 42, 8, 28, ' فلما رأى يسوع صرخ وخر له ، وقال بصوت عظيم : ما لي ولك يا يسوع ابن الله العلي ؟ أطلب منك أن لا تعذبني '),
(23569, 'Luke', 42, 8, 29, ' لأنه أمر الروح النجس أن يخرج من الإنسان . لأنه منذ زمان كثير كان يخطفه ، وقد ربط بسلاسل وقيود محروسا ، وكان يقطع الربط ويساق من الشيطان إلى البراري '),
(23570, 'Luke', 42, 8, 30, ' فسأله يسوع قائلا : ما اسمك ؟ فقال : لجئون . لأن شياطين كثيرة دخلت فيه '),
(23571, 'Luke', 42, 8, 31, ' وطلب إليه أن لا يأمرهم بالذهاب إلى الهاوية '),
(23572, 'Luke', 42, 8, 32, ' وكان هناك قطيع خنازير كثيرة ترعى في الجبل ، فطلبوا إليه أن يأذن لهم بالدخول فيها ، فأذن لهم '),
(23573, 'Luke', 42, 8, 33, ' فخرجت الشياطين من الإنسان ودخلت في الخنازير ، فاندفع القطيع من على الجرف إلى البحيرة واختنق '),
(23574, 'Luke', 42, 8, 34, ' فلما رأى الرعاة ما كان هربوا وذهبوا وأخبروا في المدينة وفي الضياع '),
(23575, 'Luke', 42, 8, 35, ' فخرجوا ليروا ما جرى . وجاءوا إلى يسوع فوجدوا الإنسان الذي كانت الشياطين قد خرجت منه لابسا وعاقلا ، جالسا عند قدمي يسوع ، فخافوا '),
(23576, 'Luke', 42, 8, 36, ' فأخبرهم أيضا الذين رأوا كيف خلص المجنون '),
(23577, 'Luke', 42, 8, 37, ' فطلب إليه كل جمهور كورة الجدريين أن يذهب عنهم ، لأنه اعتراهم خوف عظيم . فدخل السفينة ورجع '),
(23578, 'Luke', 42, 8, 38, ' أما الرجل الذي خرجت منه الشياطين فطلب إليه أن يكون معه ، ولكن يسوع صرفه قائلا '),
(23579, 'Luke', 42, 8, 39, ' ارجع إلى بيتك وحدث بكم صنع الله بك . فمضى وهو ينادي في المدينة كلها بكم صنع به يسوع '),
(23580, 'Luke', 42, 8, 40, ' ولما رجع يسوع قبله الجمع لأنهم كانوا جميعهم ينتظرونه '),
(23581, 'Luke', 42, 8, 41, ' وإذا رجل اسمه يايرس قد جاء ، وكان رئيس المجمع ، فوقع عند قدمي يسوع وطلب إليه أن يدخل بيته '),
(23582, 'Luke', 42, 8, 42, ' لأنه كان له بنت وحيدة لها نحو اثنتي عشرة سنة ، وكانت في حال الموت . ففيما هو منطلق زحمته الجموع '),
(23583, 'Luke', 42, 8, 43, ' وامرأة بنزف دم منذ اثنتي عشرة سنة ، وقد أنفقت كل معيشتها للأطباء ، ولم تقدر أن تشفى من أحد '),
(23584, 'Luke', 42, 8, 44, ' جاءت من ورائه ولمست هدب ثوبه . ففي الحال وقف نزف دمها '),
(23585, 'Luke', 42, 8, 45, ' فقال يسوع : من الذي لمسني ؟ وإذ كان الجميع ينكرون ، قال بطرس والذين معه : يا معلم ، الجموع يضيقون عليك ويزحمونك ، وتقول : من الذي لمسني '),
(23586, 'Luke', 42, 8, 46, ' فقال يسوع : قد لمسني واحد ، لأني علمت أن قوة قد خرجت مني '),
(23587, 'Luke', 42, 8, 47, ' فلما رأت المرأة أنها لم تختف ، جاءت مرتعدة وخرت له ، وأخبرته قدام جميع الشعب لأي سبب لمسته ، وكيف برئت في الحال '),
(23588, 'Luke', 42, 8, 48, ' فقال لها : ثقي يا ابنة ، إيمانك قد شفاك ، اذهبي بسلام '),
(23589, 'Luke', 42, 8, 49, ' وبينما هو يتكلم ، جاء واحد من دار رئيس المجمع قائلا له : قد ماتت ابنتك . لا تتعب المعلم '),
(23590, 'Luke', 42, 8, 50, ' فسمع يسوع ، وأجابه قائلا : لا تخف آمن فقط ، فهي تشفى '),
(23591, 'Luke', 42, 8, 51, ' فلما جاء إلى البيت لم يدع أحدا يدخل إلا بطرس ويعقوب ويوحنا ، وأبا الصبية وأمها '),
(23592, 'Luke', 42, 8, 52, ' وكان الجميع يبكون عليها ويلطمون . فقال : لا تبكوا . لم تمت لكنها نائمة '),
(23593, 'Luke', 42, 8, 53, ' فضحكوا عليه ، عارفين أنها ماتت '),
(23594, 'Luke', 42, 8, 54, ' فأخرج الجميع خارجا ، وأمسك بيدها ونادى قائلا : يا صبية ، قومي '),
(23595, 'Luke', 42, 8, 55, ' فرجعت روحها وقامت في الحال . فأمر أن تعطى لتأكل '),
(23596, 'Luke', 42, 8, 56, ' فبهت والداها . فأوصاهما أن لا يقولا لأحد عما كان '),
(23597, 'Luke', 42, 9, 1, ' ودعا تلاميذه الاثني عشر ، وأعطاهم قوة وسلطانا على جميع الشياطين وشفاء أمراض '),
(23598, 'Luke', 42, 9, 2, ' وأرسلهم ليكرزوا بملكوت الله ويشفوا المرضى '),
(23599, 'Luke', 42, 9, 3, ' وقال لهم : لا تحملوا شيئا للطريق : لا عصا ولا مزودا ولا خبزا ولا فضة ، ولا يكون للواحد ثوبان '),
(23600, 'Luke', 42, 9, 4, ' وأي بيت دخلتموه فهناك أقيموا ، ومن هناك اخرجوا '),
(23601, 'Luke', 42, 9, 5, ' وكل من لا يقبلكم فاخرجوا من تلك المدينة ، وانفضوا الغبار أيضا عن أرجلكم شهادة عليهم '),
(23602, 'Luke', 42, 9, 6, ' فلما خرجوا كانوا يجتازون في كل قرية يبشرون ويشفون في كل موضع '),
(23603, 'Luke', 42, 9, 7, ' فسمع هيرودس رئيس الربع بجميع ما كان منه ، وارتاب ، لأن قوما كانوا يقولون : إن يوحنا قد قام من الأموات '),
(23604, 'Luke', 42, 9, 8, ' وقوما : إن إيليا ظهر . وآخرين : إن نبيا من القدماء قام '),
(23605, 'Luke', 42, 9, 9, ' فقال هيرودس : يوحنا أنا قطعت رأسه . فمن هو هذا الذي أسمع عنه مثل هذا ؟ وكان يطلب أن يراه '),
(23606, 'Luke', 42, 9, 10, ' ولما رجع الرسل أخبروه بجميع ما فعلوا ، فأخذهم وانصرف منفردا إلى موضع خلاء لمدينة تسمى بيت صيدا '),
(23607, 'Luke', 42, 9, 11, ' فالجموع إذ علموا تبعوه ، فقبلهم وكلمهم عن ملكوت الله ، والمحتاجون إلى الشفاء شفاهم '),
(23608, 'Luke', 42, 9, 12, ' فابتدأ النهار يميل . فتقدم الاثنا عشر وقالوا له : اصرف الجمع ليذهبوا إلى القرى والضياع حوالينا فيبيتوا ويجدوا طعاما ، لأننا ههنا في موضع خلاء '),
(23609, 'Luke', 42, 9, 13, ' فقال لهم : أعطوهم أنتم ليأكلوا . فقالوا : ليس عندنا أكثر من خمسة أرغفة وسمكتين ، إلا أن نذهب ونبتاع طعاما لهذا الشعب كله '),
(23610, 'Luke', 42, 9, 14, ' لأنهم كانوا نحو خمسة آلاف رجل . فقال لتلاميذه : أتكئوهم فرقا خمسين خمسين '),
(23611, 'Luke', 42, 9, 15, ' ففعلوا هكذا ، وأتكأوا الجميع '),
(23612, 'Luke', 42, 9, 16, ' فأخذ الأرغفة الخمسة والسمكتين ، ورفع نظره نحو السماء وباركهن ، ثم كسر وأعطى التلاميذ ليقدموا للجمع '),
(23613, 'Luke', 42, 9, 17, ' فأكلوا وشبعوا جميعا . ثم رفع ما فضل عنهم من الكسر اثنتا عشرة قفة '),
(23614, 'Luke', 42, 9, 18, ' وفيما هو يصلي على انفراد كان التلاميذ معه . فسألهم قائلا : من تقول الجموع أني أنا '),
(23615, 'Luke', 42, 9, 19, ' فأجابوا وقالوا : يوحنا المعمدان . وآخرون : إيليا . وآخرون : إن نبيا من القدماء قام '),
(23616, 'Luke', 42, 9, 20, ' فقال لهم : وأنتم ، من تقولون أني أنا ؟ فأجاب بطرس وقال : مسيح الله '),
(23617, 'Luke', 42, 9, 21, ' فانتهرهم وأوصى أن لا يقولوا ذلك لأحد '),
(23618, 'Luke', 42, 9, 22, ' قائلا : إنه ينبغي أن ابن الإنسان يتألم كثيرا ، ويرفض من الشيوخ ورؤساء الكهنة والكتبة ، ويقتل ، وفي اليوم الثالث يقوم '),
(23619, 'Luke', 42, 9, 23, ' وقال للجميع : إن أراد أحد أن يأتي ورائي ، فلينكر نفسه ويحمل صليبه كل يوم ، ويتبعني '),
(23620, 'Luke', 42, 9, 24, ' فإن من أراد أن يخلص نفسه يهلكها ، ومن يهلك نفسه من أجلي فهذا يخلصها '),
(23621, 'Luke', 42, 9, 25, ' لأنه ماذا ينتفع الإنسان لو ربح العالم كله ، وأهلك نفسه أو خسرها '),
(23622, 'Luke', 42, 9, 26, ' لأن من استحى بي وبكلامي ، فبهذا يستحي ابن الإنسان متى جاء بمجده ومجد الآب والملائكة القديسين '),
(23623, 'Luke', 42, 9, 27, ' حقا أقول لكم : إن من القيام ههنا قوما لا يذوقون الموت حتى يروا ملكوت الله '),
(23624, 'Luke', 42, 9, 28, ' وبعد هذا الكلام بنحو ثمانية أيام ، أخذ بطرس ويوحنا ويعقوب وصعد إلى جبل ليصلي '),
(23625, 'Luke', 42, 9, 29, ' وفيما هو يصلي صارت هيئة وجهه متغيرة ، ولباسه مبيضا لامعا '),
(23626, 'Luke', 42, 9, 30, ' وإذا رجلان يتكلمان معه ، وهما موسى وإيليا '),
(23627, 'Luke', 42, 9, 31, ' اللذان ظهرا بمجد ، وتكلما عن خروجه الذي كان عتيدا أن يكمله في أورشليم '),
(23628, 'Luke', 42, 9, 32, ' وأما بطرس واللذان معه فكانوا قد تثقلوا بالنوم . فلما استيقظوا رأوا مجده ، والرجلين الواقفين معه '),
(23629, 'Luke', 42, 9, 33, ' وفيما هما يفارقانه قال بطرس ليسوع يا معلم ، جيد أن نكون ههنا . فلنصنع ثلاث مظال : لك واحدة ، ولموسى واحدة ، ولإيليا واحدة . وهو لا يعلم ما يقول '),
(23630, 'Luke', 42, 9, 34, ' وفيما هو يقول ذلك كانت سحابة فظللتهم . فخافوا عندما دخلوا في السحابة '),
(23631, 'Luke', 42, 9, 35, ' وصار صوت من السحابة قائلا : هذا هو ابني الحبيب . له اسمعوا '),
(23632, 'Luke', 42, 9, 36, ' ولما كان الصوت وجد يسوع وحده ، وأما هم فسكتوا ولم يخبروا أحدا في تلك الأيام بشيء مما أبصروه '),
(23633, 'Luke', 42, 9, 37, ' وفي اليوم التالي إذ نزلوا من الجبل ، استقبله جمع كثير '),
(23634, 'Luke', 42, 9, 38, ' وإذا رجل من الجمع صرخ قائلا : يا معلم ، أطلب إليك . انظر إلى ابني ، فإنه وحيد لي '),
(23635, 'Luke', 42, 9, 39, ' وها روح يأخذه فيصرخ بغتة ، فيصرعه مزبدا ، وبالجهد يفارقه مرضضا إياه '),
(23636, 'Luke', 42, 9, 40, ' وطلبت من تلاميذك أن يخرجوه فلم يقدروا ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(23637, 'Luke', 42, 9, 41, ' فأجاب يسوع وقال : أيها الجيل غير المؤمن والملتوي إلى متى أكون معكم وأحتملكم ؟ قدم ابنك إلى هنا '),
(23638, 'Luke', 42, 9, 42, ' وبينما هو آت مزقه الشيطان وصرعه ، فانتهر يسوع الروح النجس ، وشفى الصبي وسلمه إلى أبيه '),
(23639, 'Luke', 42, 9, 43, ' فبهت الجميع من عظمة الله . وإذ كان الجميع يتعجبون من كل ما فعل يسوع ، قال لتلاميذه '),
(23640, 'Luke', 42, 9, 44, ' ضعوا أنتم هذا الكلام في آذانكم : إن ابن الإنسان سوف يسلم إلى أيدي الناس '),
(23641, 'Luke', 42, 9, 45, ' وأما هم فلم يفهموا هذا القول ، وكان مخفى عنهم لكي لا يفهموه ، وخافوا أن يسألوه عن هذا القول '),
(23642, 'Luke', 42, 9, 46, ' وداخلهم فكر من عسى أن يكون أعظم فيهم '),
(23643, 'Luke', 42, 9, 47, ' فعلم يسوع فكر قلبهم ، وأخذ ولدا وأقامه عنده '),
(23644, 'Luke', 42, 9, 48, ' وقال لهم : من قبل هذا الولد باسمي يقبلني ، ومن قبلني يقبل الذي أرسلني ، لأن الأصغر فيكم جميعا هو يكون عظيما '),
(23645, 'Luke', 42, 9, 49, ' فأجاب يوحنا وقال : يا معلم ، رأينا واحدا يخرج الشياطين باسمك فمنعناه ، لأنه ليس يتبع معنا '),
(23646, 'Luke', 42, 9, 50, ' فقال له يسوع : لا تمنعوه ، لأن من ليس علينا فهو معنا '),
(23647, 'Luke', 42, 9, 51, ' وحين تمت الأيام لارتفاعه ثبت وجهه لينطلق إلى أورشليم '),
(23648, 'Luke', 42, 9, 52, ' وأرسل أمام وجهه رسلا ، فذهبوا ودخلوا قرية للسامريين حتى يعدوا له '),
(23649, 'Luke', 42, 9, 53, ' فلم يقبلوه لأن وجهه كان متجها نحو أورشليم '),
(23650, 'Luke', 42, 9, 54, ' فلما رأى ذلك تلميذاه يعقوب ويوحنا ، قالا : يا رب ، أتريد أن نقول أن تنزل نار من السماء فتفنيهم ، كما فعل إيليا أيضا '),
(23651, 'Luke', 42, 9, 55, ' فالتفت وانتهرهما وقال : لستما تعلمان من أي روح أنتما '),
(23652, 'Luke', 42, 9, 56, ' لأن ابن الإنسان لم يأت ليهلك أنفس الناس ، بل ليخلص . فمضوا إلى قرية أخرى '),
(23653, 'Luke', 42, 9, 57, ' وفيما هم سائرون في الطريق قال له واحد : يا سيد ، أتبعك أينما تمضي '),
(23654, 'Luke', 42, 9, 58, ' فقال له يسوع : للثعالب أوجرة ، ولطيور السماء أوكار ، وأما ابن الإنسان فليس له أين يسند رأسه '),
(23655, 'Luke', 42, 9, 59, ' وقال لآخر : اتبعني . فقال : يا سيد ، ائذن لي أن أمضي أولا وأدفن أبي '),
(23656, 'Luke', 42, 9, 60, ' فقال له يسوع : دع الموتى يدفنون موتاهم ، وأما أنت فاذهب وناد بملكوت الله '),
(23657, 'Luke', 42, 9, 61, ' وقال آخر أيضا : أتبعك يا سيد ، ولكن ائذن لي أولا أن أودع الذين في بيتي '),
(23658, 'Luke', 42, 9, 62, ' فقال له يسوع : ليس أحد يضع يده على المحراث وينظر إلى الوراء يصلح لملكوت الله '),
(23659, 'Luke', 42, 10, 1, ' وبعد ذلك عين الرب سبعين آخرين أيضا ، وأرسلهم اثنين اثنين أمام وجهه إلى كل مدينة وموضع حيث كان هو مزمعا أن يأتي '),
(23660, 'Luke', 42, 10, 2, ' فقال لهم : إن الحصاد كثير ، ولكن الفعلة قليلون . فاطلبوا من رب الحصاد أن يرسل فعلة إلى حصاده '),
(23661, 'Luke', 42, 10, 3, ' اذهبوا ها أنا أرسلكم مثل حملان بين ذئاب '),
(23662, 'Luke', 42, 10, 4, ' لا تحملوا كيسا ولا مزودا ولا أحذية ، ولا تسلموا على أحد في الطريق '),
(23663, 'Luke', 42, 10, 5, ' وأي بيت دخلتموه فقولوا أولا : سلام لهذا البيت '),
(23664, 'Luke', 42, 10, 6, ' فإن كان هناك ابن السلام يحل سلامكم عليه ، وإلا فيرجع إليكم '),
(23665, 'Luke', 42, 10, 7, ' وأقيموا في ذلك البيت آكلين وشاربين مما عندهم ، لأن الفاعل مستحق أجرته . لا تنتقلوا من بيت إلى بيت '),
(23666, 'Luke', 42, 10, 8, ' وأية مدينة دخلتموها وقبلوكم ، فكلوا مما يقدم لكم '),
(23667, 'Luke', 42, 10, 9, ' واشفوا المرضى الذين فيها ، وقولوا لهم : قد اقترب منكم ملكوت الله '),
(23668, 'Luke', 42, 10, 10, ' وأية مدينة دخلتموها ولم يقبلوكم ، فاخرجوا إلى شوارعها وقولوا '),
(23669, 'Luke', 42, 10, 11, ' حتى الغبار الذي لصق بنا من مدينتكم ننفضه لكم . ولكن اعلموا هذا إنه قد اقترب منكم ملكوت الله '),
(23670, 'Luke', 42, 10, 12, ' وأقول لكم : إنه يكون لسدوم في ذلك اليوم حالة أكثر احتمالا مما لتلك المدينة '),
(23671, 'Luke', 42, 10, 13, ' ويل لك يا كورزين ويل لك يا بيت صيدا لأنه لو صنعت في صور وصيداء القوات المصنوعة فيكما ، لتابتا قديما جالستين في المسوح والرماد '),
(23672, 'Luke', 42, 10, 14, ' ولكن صور وصيداء يكون لهما في الدين حالة أكثر احتمالا مما لكما '),
(23673, 'Luke', 42, 10, 15, ' وأنت يا كفرناحوم المرتفعة إلى السماء ستهبطين إلى الهاوية '),
(23674, 'Luke', 42, 10, 16, ' الذي يسمع منكم يسمع مني ، والذي يرذلكم يرذلني ، والذي يرذلني يرذل الذي أرسلني '),
(23675, 'Luke', 42, 10, 17, ' فرجع السبعون بفرح قائلين : يا رب ، حتى الشياطين تخضع لنا باسمك '),
(23676, 'Luke', 42, 10, 18, ' فقال لهم : رأيت الشيطان ساقطا مثل البرق من السماء '),
(23677, 'Luke', 42, 10, 19, ' ها أنا أعطيكم سلطانا لتدوسوا الحيات والعقارب وكل قوة العدو ، ولا يضركم شيء '),
(23678, 'Luke', 42, 10, 20, ' ولكن لا تفرحوا بهذا : أن الأرواح تخضع لكم ، بل افرحوا بالحري أن أسماءكم كتبت في السماوات '),
(23679, 'Luke', 42, 10, 21, ' وفي تلك الساعة تهلل يسوع بالروح وقال : أحمدك أيها الآب ، رب السماء والأرض ، لأنك أخفيت هذه عن الحكماء والفهماء وأعلنتها للأطفال . نعم أيها الآب ، لأن هكذا صارت المسرة أمامك '),
(23680, 'Luke', 42, 10, 22, ' والتفت إلى تلاميذه وقال : كل شيء قد دفع إلي من أبي . وليس أحد يعرف من هو الابن إلا الآب ، ولا من هو الآب إلا الابن ، ومن أراد الابن أن يعلن له '),
(23681, 'Luke', 42, 10, 23, ' والتفت إلى تلاميذه على انفراد وقال : طوبى للعيون التي تنظر ما تنظرونه '),
(23682, 'Luke', 42, 10, 24, ' لأني أقول لكم : إن أنبياء كثيرين وملوكا أرادوا أن ينظروا ما أنتم تنظرون ولم ينظروا ، وأن يسمعوا ما أنتم تسمعون ولم يسمعوا '),
(23683, 'Luke', 42, 10, 25, ' وإذا ناموسي قام يجربه قائلا : يا معلم ، ماذا أعمل لأرث الحياة الأبدية '),
(23684, 'Luke', 42, 10, 26, ' فقال له : ما هو مكتوب في الناموس . كيف تقرأ '),
(23685, 'Luke', 42, 10, 27, ' فأجاب وقال : تحب الرب إلهك من كل قلبك ، ومن كل نفسك ، ومن كل قدرتك ، ومن كل فكرك ، وقريبك مثل نفسك '),
(23686, 'Luke', 42, 10, 28, ' فقال له : بالصواب أجبت . افعل هذا فتحيا '),
(23687, 'Luke', 42, 10, 29, ' وأما هو فإذ أراد أن يبرر نفسه ، قال ليسوع : ومن هو قريبي '),
(23688, 'Luke', 42, 10, 30, ' فأجاب يسوع وقال : إنسان كان نازلا من أورشليم إلى أريحا ، فوقع بين لصوص ، فعروه وجرحوه ، ومضوا وتركوه بين حي وميت '),
(23689, 'Luke', 42, 10, 31, ' فعرض أن كاهنا نزل في تلك الطريق ، فرآه وجاز مقابله '),
(23690, 'Luke', 42, 10, 32, ' وكذلك لاوي أيضا ، إذ صار عند المكان جاء ونظر وجاز مقابله '),
(23691, 'Luke', 42, 10, 33, ' ولكن سامريا مسافرا جاء إليه ، ولما رآه تحنن '),
(23692, 'Luke', 42, 10, 34, ' فتقدم وضمد جراحاته ، وصب عليها زيتا وخمرا ، وأركبه على دابته ، وأتى به إلى فندق واعتنى به '),
(23693, 'Luke', 42, 10, 35, ' وفي الغد لما مضى أخرج دينارين وأعطاهما لصاحب الفندق ، وقال له : اعتن به ، ومهما أنفقت أكثر فعند رجوعي أوفيك '),
(23694, 'Luke', 42, 10, 36, ' فأي هؤلاء الثلاثة ترى صار قريبا للذي وقع بين اللصوص '),
(23695, 'Luke', 42, 10, 37, ' فقال : الذي صنع معه الرحمة . فقال له يسوع : اذهب أنت أيضا واصنع هكذا '),
(23696, 'Luke', 42, 10, 38, ' وفيما هم سائرون دخل قرية ، فقبلته امرأة اسمها مرثا في بيتها '),
(23697, 'Luke', 42, 10, 39, ' وكانت لهذه أخت تدعى مريم ، التي جلست عند قدمي يسوع وكانت تسمع كلامه '),
(23698, 'Luke', 42, 10, 40, ' وأما مرثا فكانت مرتبكة في خدمة كثيرة . فوقفت وقالت : يا رب ، أما تبالي بأن أختي قد تركتني أخدم وحدي ؟ فقل لها أن تعينني '),
(23699, 'Luke', 42, 10, 41, ' فأجاب يسوع وقال لها : مرثا ، مرثا ، أنت تهتمين وتضطربين لأجل أمور كثيرة '),
(23700, 'Luke', 42, 10, 42, ' ولكن الحاجة إلى واحد . فاختارت مريم النصيب الصالح الذي لن ينزع منها '),
(23701, 'Luke', 42, 11, 1, ' وإذ كان يصلي في موضع ، لما فرغ ، قال واحد من تلاميذه : يا رب ، علمنا أن نصلي كما علم يوحنا أيضا تلاميذه '),
(23702, 'Luke', 42, 11, 2, ' فقال لهم : متى صليتم فقولوا : أبانا الذي في السماوات ، ليتقدس اسمك ، ليأت ملكوتك ، لتكن مشيئتك كما في السماء كذلك على الأرض '),
(23703, 'Luke', 42, 11, 3, ' خبزنا كفافنا أعطنا كل يوم '),
(23704, 'Luke', 42, 11, 4, ' واغفر لنا خطايانا لأننا نحن أيضا نغفر لكل من يذنب إلينا ، ولا تدخلنا في تجربة لكن نجنا من الشرير '),
(23705, 'Luke', 42, 11, 5, ' ثم قال لهم : من منكم يكون له صديق ، ويمضي إليه نصف الليل ، ويقول له يا صديق ، أقرضني ثلاثة أرغفة '),
(23706, 'Luke', 42, 11, 6, ' لأن صديقا لي جاءني من سفر ، وليس لي ما أقدم له '),
(23707, 'Luke', 42, 11, 7, ' فيجيب ذلك من داخل ويقول : لا تزعجني الباب مغلق الآن ، وأولادي معي في الفراش . لا أقدر أن أقوم وأعطيك '),
(23708, 'Luke', 42, 11, 8, ' أقول لكم : وإن كان لا يقوم ويعطيه لكونه صديقه ، فإنه من أجل لجاجته يقوم ويعطيه قدر ما يحتاج '),
(23709, 'Luke', 42, 11, 9, ' وأنا أقول لكم : اسألوا تعطوا ، اطلبوا تجدوا ، اقرعوا يفتح لكم '),
(23710, 'Luke', 42, 11, 10, ' لأن كل من يسأل يأخذ ، ومن يطلب يجد ، ومن يقرع يفتح له '),
(23711, 'Luke', 42, 11, 11, ' فمن منكم ، وهو أب ، يسأله ابنه خبزا ، أفيعطيه حجرا ؟ أو سمكة ، أفيعطيه حية بدل السمكة '),
(23712, 'Luke', 42, 11, 12, ' أو إذا سأله بيضة ، أفيعطيه عقربا '),
(23713, 'Luke', 42, 11, 13, ' فإن كنتم وأنتم أشرار تعرفون أن تعطوا أولادكم عطايا جيدة ، فكم بالحري الآب الذي من السماء ، يعطي الروح القدس للذين يسألونه '),
(23714, 'Luke', 42, 11, 14, ' وكان يخرج شيطانا ، وكان ذلك أخرس . فلما أخرج الشيطان تكلم الأخرس ، فتعجب الجموع '),
(23715, 'Luke', 42, 11, 15, ' وأما قوم منهم فقالوا : ببعلزبول رئيس الشياطين يخرج الشياطين '),
(23716, 'Luke', 42, 11, 16, ' وآخرون طلبوا منه آية من السماء يجربونه '),
(23717, 'Luke', 42, 11, 17, ' فعلم أفكارهم ، وقال لهم : كل مملكة منقسمة على ذاتها تخرب ، وبيت منقسم على بيت يسقط '),
(23718, 'Luke', 42, 11, 18, ' فإن كان الشيطان أيضا ينقسم على ذاته ، فكيف تثبت مملكته ؟ لأنكم تقولون : إني ببعلزبول أخرج الشياطين '),
(23719, 'Luke', 42, 11, 19, ' فإن كنت أنا ببعلزبول أخرج الشياطين ، فأبناؤكم بمن يخرجون ؟ لذلك هم يكونون قضاتكم '),
(23720, 'Luke', 42, 11, 20, ' ولكن إن كنت بأصبع الله أخرج الشياطين ، فقد أقبل عليكم ملكوت الله '),
(23721, 'Luke', 42, 11, 21, ' حينما يحفظ القوي داره متسلحا ، تكون أمواله في أمان '),
(23722, 'Luke', 42, 11, 22, ' ولكن متى جاء من هو أقوى منه فإنه يغلبه ، وينزع سلاحه الكامل الذي اتكل عليه ، ويوزع غنائمه '),
(23723, 'Luke', 42, 11, 23, ' من ليس معي فهو علي ، ومن لا يجمع معي فهو يفرق '),
(23724, 'Luke', 42, 11, 24, ' متى خرج الروح النجس من الإنسان ، يجتاز في أماكن ليس فيها ماء يطلب راحة ، وإذ لا يجد يقول : أرجع إلى بيتي الذي خرجت منه '),
(23725, 'Luke', 42, 11, 25, ' فيأتي ويجده مكنوسا مزينا '),
(23726, 'Luke', 42, 11, 26, ' ثم يذهب ويأخذ سبعة أرواح أخر أشر منه ، فتدخل وتسكن هناك ، فتصير أواخر ذلك الإنسان أشر من أوائله '),
(23727, 'Luke', 42, 11, 27, ' وفيما هو يتكلم بهذا ، رفعت امرأة صوتها من الجمع وقالت له : طوبى للبطن الذي حملك والثديين اللذين رضعتهما '),
(23728, 'Luke', 42, 11, 28, ' أما هو فقال : بل طوبى للذين يسمعون كلام الله ويحفظونه '),
(23729, 'Luke', 42, 11, 29, ' وفيما كان الجموع مزدحمين ، ابتدأ يقول : هذا الجيل شرير . يطلب آية ، ولا تعطى له آية إلا آية يونان النبي '),
(23730, 'Luke', 42, 11, 30, ' لأنه كما كان يونان آية لأهل نينوى ، كذلك يكون ابن الإنسان أيضا لهذا الجيل '),
(23731, 'Luke', 42, 11, 31, ' ملكة التيمن ستقوم في الدين مع رجال هذا الجيل وتدينهم ، لأنها أتت من أقاصي الأرض لتسمع حكمة سليمان ، وهوذا أعظم من سليمان ههنا '),
(23732, 'Luke', 42, 11, 32, ' رجال نينوى سيقومون في الدين مع هذا الجيل ويدينونه ، لأنهم تابوا بمناداة يونان ، وهوذا أعظم من يونان ههنا '),
(23733, 'Luke', 42, 11, 33, ' ليس أحد يوقد سراجا ويضعه في خفية ، ولا تحت المكيال ، بل على المنارة ، لكي ينظر الداخلون النور '),
(23734, 'Luke', 42, 11, 34, ' سراج الجسد هو العين ، فمتى كانت عينك بسيطة فجسدك كله يكون نيرا ، ومتى كانت شريرة فجسدك يكون مظلما '),
(23735, 'Luke', 42, 11, 35, ' انظر إذا لئلا يكون النور الذي فيك ظلمة '),
(23736, 'Luke', 42, 11, 36, ' فإن كان جسدك كله نيرا ليس فيه جزء مظلم ، يكون نيرا كله ، كما حينما يضيء لك السراج بلمعانه '),
(23737, 'Luke', 42, 11, 37, ' وفيما هو يتكلم سأله فريسي أن يتغدى عنده ، فدخل واتكأ '),
(23738, 'Luke', 42, 11, 38, ' وأما الفريسي فلما رأى ذلك تعجب أنه لم يغتسل أولا قبل الغداء '),
(23739, 'Luke', 42, 11, 39, ' فقال له الرب : أنتم الآن أيها الفريسيون تنقون خارج الكأس والقصعة ، وأما باطنكم فمملوء اختطافا وخبثا '),
(23740, 'Luke', 42, 11, 40, ' يا أغبياء ، أليس الذي صنع الخارج صنع الداخل أيضا '),
(23741, 'Luke', 42, 11, 41, ' بل أعطوا ما عندكم صدقة ، فهوذا كل شيء يكون نقيا لكم '),
(23742, 'Luke', 42, 11, 42, ' ولكن ويل لكم أيها الفريسيون لأنكم تعشرون النعنع والسذاب وكل بقل ، وتتجاوزون عن الحق ومحبة الله . كان ينبغي أن تعملوا هذه ولا تتركوا تلك '),
(23743, 'Luke', 42, 11, 43, ' ويل لكم أيها الفريسيون لأنكم تحبون المجلس الأول في المجامع ، والتحيات في الأسواق '),
(23744, 'Luke', 42, 11, 44, ' ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم مثل القبور المختفية ، والذين يمشون عليها لا يعلمون '),
(23745, 'Luke', 42, 11, 45, ' فأجاب واحد من الناموسيين وقال له : يا معلم ، حين تقول هذا تشتمنا نحن أيضا '),
(23746, 'Luke', 42, 11, 46, ' فقال : وويل لكم أنتم أيها الناموسيون لأنكم تحملون الناس أحمالا عسرة الحمل وأنتم لا تمسون الأحمال بإحدى أصابعكم '),
(23747, 'Luke', 42, 11, 47, ' ويل لكم لأنكم تبنون قبور الأنبياء ، وآباؤكم قتلوهم '),
(23748, 'Luke', 42, 11, 48, ' إذا تشهدون وترضون بأعمال آبائكم ، لأنهم هم قتلوهم وأنتم تبنون قبورهم '),
(23749, 'Luke', 42, 11, 49, ' لذلك أيضا قالت حكمة الله : إني أرسل إليهم أنبياء ورسلا ، فيقتلون منهم ويطردون '),
(23750, 'Luke', 42, 11, 50, ' لكي يطلب من هذا الجيل دم جميع الأنبياء المهرق منذ إنشاء العالم '),
(23751, 'Luke', 42, 11, 51, ' من دم هابيل إلى دم زكريا الذي أهلك بين المذبح والبيت . نعم ، أقول لكم : إنه يطلب من هذا الجيل '),
(23752, 'Luke', 42, 11, 52, ' ويل لكم أيها الناموسيون لأنكم أخذتم مفتاح المعرفة . ما دخلتم أنتم ، والداخلون منعتموهم '),
(23753, 'Luke', 42, 11, 53, ' وفيما هو يكلمهم بهذا ، ابتدأ الكتبة والفريسيون يحنقون جدا ، ويصادرونه على أمور كثيرة '),
(23754, 'Luke', 42, 11, 54, ' وهم يراقبونه طالبين أن يصطادوا شيئا من فمه لكي يشتكوا عليه '),
(23755, 'Luke', 42, 12, 1, ' وفي أثناء ذلك ، إذ اجتمع ربوات الشعب ، حتى كان بعضهم يدوس بعضا ، ابتدأ يقول لتلاميذه : أولا تحرزوا لأنفسكم من خمير الفريسيين الذي هو الرياء '),
(23756, 'Luke', 42, 12, 2, ' فليس مكتوم لن يستعلن ، ولا خفي لن يعرف '),
(23757, 'Luke', 42, 12, 3, ' لذلك كل ما قلتموه في الظلمة يسمع في النور ، وما كلمتم به الأذن في المخادع ينادى به على السطوح '),
(23758, 'Luke', 42, 12, 4, ' ولكن أقول لكم يا أحبائي : لا تخافوا من الذين يقتلون الجسد ، وبعد ذلك ليس لهم ما يفعلون أكثر '),
(23759, 'Luke', 42, 12, 5, ' بل أريكم ممن تخافون : خافوا من الذي بعدما يقتل ، له سلطان أن يلقي في جهنم . نعم ، أقول لكم : من هذا خافوا '),
(23760, 'Luke', 42, 12, 6, ' أليست خمسة عصافير تباع بفلسين ، وواحد منها ليس منسيا أمام الله '),
(23761, 'Luke', 42, 12, 7, ' بل شعور رؤوسكم أيضا جميعها محصاة . فلا تخافوا أنتم أفضل من عصافير كثيرة '),
(23762, 'Luke', 42, 12, 8, ' وأقول لكم : كل من اعترف بي قدام الناس ، يعترف به ابن الإنسان قدام ملائكة الله '),
(23763, 'Luke', 42, 12, 9, ' ومن أنكرني قدام الناس ، ينكر قدام ملائكة الله '),
(23764, 'Luke', 42, 12, 10, ' وكل من قال كلمة على ابن الإنسان يغفر له ، وأما من جدف على الروح القدس فلا يغفر له '),
(23765, 'Luke', 42, 12, 11, ' ومتى قدموكم إلى المجامع والرؤساء والسلاطين فلا تهتموا كيف أو بما تحتجون أو بما تقولون '),
(23766, 'Luke', 42, 12, 12, ' لأن الروح القدس يعلمكم في تلك الساعة ما يجب أن تقولوه '),
(23767, 'Luke', 42, 12, 13, ' وقال له واحد من الجمع : يا معلم ، قل لأخي أن يقاسمني الميراث '),
(23768, 'Luke', 42, 12, 14, ' فقال له : يا إنسان ، من أقامني عليكما قاضيا أو مقسما '),
(23769, 'Luke', 42, 12, 15, ' وقال لهم : انظروا وتحفظوا من الطمع ، فإنه متى كان لأحد كثير فليست حياته من أمواله '),
(23770, 'Luke', 42, 12, 16, ' وضرب لهم مثلا قائلا : إنسان غني أخصبت كورته '),
(23771, 'Luke', 42, 12, 17, ' ففكر في نفسه قائلا : ماذا أعمل ، لأن ليس لي موضع أجمع فيه أثماري '),
(23772, 'Luke', 42, 12, 18, ' وقال : أعمل هذا : أهدم مخازني وأبني أعظم ، وأجمع هناك جميع غلاتي وخيراتي '),
(23773, 'Luke', 42, 12, 19, ' وأقول لنفسي : يا نفس لك خيرات كثيرة ، موضوعة لسنين كثيرة . استريحي وكلي واشربي وافرحي '),
(23774, 'Luke', 42, 12, 20, ' فقال له الله : يا غبي هذه الليلة تطلب نفسك منك ، فهذه التي أعددتها لمن تكون '),
(23775, 'Luke', 42, 12, 21, ' هكذا الذي يكنز لنفسه وليس هو غنيا لله '),
(23776, 'Luke', 42, 12, 22, ' وقال لتلاميذه : من أجل هذا أقول لكم : لا تهتموا لحياتكم بما تأكلون ، ولا للجسد بما تلبسون '),
(23777, 'Luke', 42, 12, 23, ' الحياة أفضل من الطعام ، والجسد أفضل من اللباس '),
(23778, 'Luke', 42, 12, 24, ' تأملوا الغربان : أنها لا تزرع ولا تحصد ، وليس لها مخدع ولا مخزن ، والله يقيتها . كم أنتم بالحري أفضل من الطيور '),
(23779, 'Luke', 42, 12, 25, ' ومن منكم إذا اهتم يقدر أن يزيد على قامته ذراعا واحدة '),
(23780, 'Luke', 42, 12, 26, ' فإن كنتم لا تقدرون ولا على الأصغر ، فلماذا تهتمون بالبواقي '),
(23781, 'Luke', 42, 12, 27, ' تأملوا الزنابق كيف تنمو : لا تتعب ولا تغزل ، ولكن أقول لكم : إنه ولا سليمان في كل مجده كان يلبس كواحدة منها '),
(23782, 'Luke', 42, 12, 28, ' فإن كان العشب الذي يوجد اليوم في الحقل ويطرح غدا في التنور يلبسه الله هكذا ، فكم بالحري يلبسكم أنتم يا قليلي الإيمان '),
(23783, 'Luke', 42, 12, 29, ' فلا تطلبوا أنتم ما تأكلون وما تشربون ولا تقلقوا '),
(23784, 'Luke', 42, 12, 30, ' فإن هذه كلها تطلبها أمم العالم . وأما أنتم فأبوكم يعلم أنكم تحتاجون إلى هذه '),
(23785, 'Luke', 42, 12, 31, ' بل اطلبوا ملكوت الله ، وهذه كلها تزاد لكم '),
(23786, 'Luke', 42, 12, 32, ' لا تخف ، أيها القطيع الصغير ، لأن أباكم قد سر أن يعطيكم الملكوت '),
(23787, 'Luke', 42, 12, 33, ' بيعوا ما لكم وأعطوا صدقة . اعملوا لكم أكياسا لا تفنى وكنزا لا ينفد في السماوات ، حيث لا يقرب سارق ولا يبلي سوس '),
(23788, 'Luke', 42, 12, 34, ' لأنه حيث يكون كنزكم هناك يكون قلبكم أيضا '),
(23789, 'Luke', 42, 12, 35, ' لتكن أحقاؤكم ممنطقة وسرجكم موقدة '),
(23790, 'Luke', 42, 12, 36, ' وأنتم مثل أناس ينتظرون سيدهم متى يرجع من العرس ، حتى إذا جاء وقرع يفتحون له للوقت '),
(23791, 'Luke', 42, 12, 37, ' طوبى لأولئك العبيد الذين إذا جاء سيدهم يجدهم ساهرين . الحق أقول لكم : إنه يتمنطق ويتكئهم ويتقدم ويخدمهم '),
(23792, 'Luke', 42, 12, 38, ' وإن أتى في الهزيع الثاني أو أتى في الهزيع الثالث ووجدهم هكذا ، فطوبى لأولئك العبيد '),
(23793, 'Luke', 42, 12, 39, ' وإنما اعلموا هذا : أنه لو عرف رب البيت في أية ساعة يأتي السارق لسهر ، ولم يدع بيته ينقب '),
(23794, 'Luke', 42, 12, 40, ' فكونوا أنتم إذا مستعدين ، لأنه في ساعة لا تظنون يأتي ابن الإنسان '),
(23795, 'Luke', 42, 12, 41, ' فقال له بطرس : يا رب ، ألنا تقول هذا المثل أم للجميع أيضا '),
(23796, 'Luke', 42, 12, 42, ' فقال الرب : فمن هو الوكيل الأمين الحكيم الذي يقيمه سيده على خدمه ليعطيهم العلوفة في حينها '),
(23797, 'Luke', 42, 12, 43, ' طوبى لذلك العبد الذي إذا جاء سيده يجده يفعل هكذا '),
(23798, 'Luke', 42, 12, 44, ' بالحق أقول لكم : إنه يقيمه على جميع أمواله '),
(23799, 'Luke', 42, 12, 45, ' ولكن إن قال ذلك العبد في قلبه : سيدي يبطئ قدومه ، فيبتدئ يضرب الغلمان والجواري ، ويأكل ويشرب ويسكر '),
(23800, 'Luke', 42, 12, 46, ' يأتي سيد ذلك العبد في يوم لا ينتظره وفي ساعة لا يعرفها ، فيقطعه ويجعل نصيبه مع الخائنين '),
(23801, 'Luke', 42, 12, 47, ' وأما ذلك العبد الذي يعلم إرادة سيده ولا يستعد ولا يفعل بحسب إرادته ، فيضرب كثيرا '),
(23802, 'Luke', 42, 12, 48, ' ولكن الذي لا يعلم ، ويفعل ما يستحق ضربات ، يضرب قليلا . فكل من أعطي كثيرا يطلب منه كثير ، ومن يودعونه كثيرا يطالبونه بأكثر '),
(23803, 'Luke', 42, 12, 49, ' جئت لألقي نارا على الأرض ، فماذا أريد لو اضطرمت '),
(23804, 'Luke', 42, 12, 50, ' ولي صبغة أصطبغها ، وكيف أنحصر حتى تكمل '),
(23805, 'Luke', 42, 12, 51, ' أتظنون أني جئت لأعطي سلاما على الأرض ؟ كلا ، أقول لكم : بل انقساما '),
(23806, 'Luke', 42, 12, 52, ' لأنه يكون من الآن خمسة في بيت واحد منقسمين : ثلاثة على اثنين ، واثنان على ثلاثة '),
(23807, 'Luke', 42, 12, 53, ' ينقسم الأب على الابن ، والابن على الأب ، والأم على البنت ، والبنت على الأم ، والحماة على كنتها ، والكنة على حماتها '),
(23808, 'Luke', 42, 12, 54, ' ثم قال أيضا للجموع : إذا رأيتم السحاب تطلع من المغارب فللوقت تقولون : إنه يأتي مطر ، فيكون هكذا '),
(23809, 'Luke', 42, 12, 55, ' وإذا رأيتم ريح الجنوب تهب تقولون : إنه سيكون حر ، فيكون '),
(23810, 'Luke', 42, 12, 56, ' يا مراؤون تعرفون أن تميزوا وجه الأرض والسماء ، وأما هذا الزمان فكيف لا تميزونه '),
(23811, 'Luke', 42, 12, 57, ' ولماذا لا تحكمون بالحق من قبل نفوسكم '),
(23812, 'Luke', 42, 12, 58, ' حينما تذهب مع خصمك إلى الحاكم ، ابذل الجهد وأنت في الطريق لتتخلص منه ، لئلا يجرك إلى القاضي ، ويسلمك القاضي إلى الحاكم ، فيلقيك الحاكم في السجن '),
(23813, 'Luke', 42, 12, 59, ' أقول لك : لا تخرج من هناك حتى توفي الفلس الأخير '),
(23814, 'Luke', 42, 13, 1, ' وكان حاضرا في ذلك الوقت قوم يخبرونه عن الجليليين الذين خلط بيلاطس دمهم بذبائحهم '),
(23815, 'Luke', 42, 13, 2, ' فأجاب يسوع وقال لهم : أتظنون أن هؤلاء الجليليين كانوا خطاة أكثر من كل الجليليين لأنهم كابدوا مثل هذا '),
(23816, 'Luke', 42, 13, 3, ' كلا أقول لكم : بل إن لم تتوبوا فجميعكم كذلك تهلكون '),
(23817, 'Luke', 42, 13, 4, ' أو أولئك الثمانية عشر الذين سقط عليهم البرج في سلوام وقتلهم ، أتظنون أن هؤلاء كانوا مذنبين أكثر من جميع الناس الساكنين في أورشليم '),
(23818, 'Luke', 42, 13, 5, ' كلا أقول لكم : بل إن لم تتوبوا فجميعكم كذلك تهلكون '),
(23819, 'Luke', 42, 13, 6, ' وقال هذا المثل : كانت لواحد شجرة تين مغروسة في كرمه ، فأتى يطلب فيها ثمرا ولم يجد '),
(23820, 'Luke', 42, 13, 7, ' فقال للكرام : هوذا ثلاث سنين آتي أطلب ثمرا في هذه التينة ولم أجد . اقطعها لماذا تبطل الأرض أيضا '),
(23821, 'Luke', 42, 13, 8, ' فأجاب وقال له : يا سيد ، اتركها هذه السنة أيضا ، حتى أنقب حولها وأضع زبلا '),
(23822, 'Luke', 42, 13, 9, ' فإن صنعت ثمرا ، وإلا ففيما بعد تقطعها '),
(23823, 'Luke', 42, 13, 10, ' وكان يعلم في أحد المجامع في السبت '),
(23824, 'Luke', 42, 13, 11, ' وإذا امرأة كان بها روح ضعف ثماني عشرة سنة ، وكانت منحنية ولم تقدر أن تنتصب البتة '),
(23825, 'Luke', 42, 13, 12, ' فلما رآها يسوع دعاها وقال لها : يا امرأة ، إنك محلولة من ضعفك '),
(23826, 'Luke', 42, 13, 13, ' ووضع عليها يديه ، ففي الحال استقامت ومجدت الله '),
(23827, 'Luke', 42, 13, 14, ' فأجاب رئيس المجمع ، وهو مغتاظ لأن يسوع أبرأ في السبت ، وقال للجمع : هي ستة أيام ينبغي فيها العمل ، ففي هذه ائتوا واستشفوا ، وليس في يوم السبت '),
(23828, 'Luke', 42, 13, 15, ' فأجابه الرب وقال : يا مرائي ألا يحل كل واحد منكم في السبت ثوره أو حماره من المذود ويمضي به ويسقيه '),
(23829, 'Luke', 42, 13, 16, ' وهذه ، وهي ابنة إبراهيم ، قد ربطها الشيطان ثماني عشرة سنة ، أما كان ينبغي أن تحل من هذا الرباط في يوم السبت '),
(23830, 'Luke', 42, 13, 17, ' وإذ قال هذا أخجل جميع الذين كانوا يعاندونه ، وفرح كل الجمع بجميع الأعمال المجيدة الكائنة منه '),
(23831, 'Luke', 42, 13, 18, ' فقال : ماذا يشبه ملكوت الله ؟ وبماذا أشبهه '),
(23832, 'Luke', 42, 13, 19, ' يشبه حبة خردل أخذها إنسان وألقاها في بستانه ، فنمت وصارت شجرة كبيرة ، وتآوت طيور السماء في أغصانها '),
(23833, 'Luke', 42, 13, 20, ' وقال أيضا : بماذا أشبه ملكوت الله '),
(23834, 'Luke', 42, 13, 21, ' يشبه خميرة أخذتها امرأة وخبأتها في ثلاثة أكيال دقيق حتى اختمر الجميع '),
(23835, 'Luke', 42, 13, 22, ' واجتاز في مدن وقرى يعلم ويسافر نحو أورشليم '),
(23836, 'Luke', 42, 13, 23, ' فقال له واحد : يا سيد ، أقليل هم الذين يخلصون ؟ فقال لهم '),
(23837, 'Luke', 42, 13, 24, ' اجتهدوا أن تدخلوا من الباب الضيق ، فإني أقول لكم : إن كثيرين سيطلبون أن يدخلوا ولا يقدرون '),
(23838, 'Luke', 42, 13, 25, ' من بعد ما يكون رب البيت قد قام وأغلق الباب ، وابتدأتم تقفون خارجا وتقرعون الباب قائلين : يا رب ، يا رب افتح لنا . يجيب ، ويقول لكم : لا أعرفكم من أين أنتم '),
(23839, 'Luke', 42, 13, 26, ' حينئذ تبتدئون تقولون : أكلنا قدامك وشربنا ، وعلمت في شوارعنا '),
(23840, 'Luke', 42, 13, 27, ' فيقول : أقول لكم : لا أعرفكم من أين أنتم ، تباعدوا عني يا جميع فاعلي الظلم '),
(23841, 'Luke', 42, 13, 28, ' هناك يكون البكاء وصرير الأسنان ، متى رأيتم إبراهيم وإسحاق ويعقوب وجميع الأنبياء في ملكوت الله ، وأنتم مطروحون خارجا '),
(23842, 'Luke', 42, 13, 29, ' ويأتون من المشارق ومن المغارب ومن الشمال والجنوب ، ويتكئون في ملكوت الله '),
(23843, 'Luke', 42, 13, 30, ' وهوذا آخرون يكونون أولين ، وأولون يكونون آخرين '),
(23844, 'Luke', 42, 13, 31, ' في ذلك اليوم تقدم بعض الفريسيين قائلين له : اخرج واذهب من ههنا ، لأن هيرودس يريد أن يقتلك '),
(23845, 'Luke', 42, 13, 32, ' فقال لهم : امضوا وقولوا لهذا الثعلب : ها أنا أخرج شياطين ، وأشفي اليوم وغدا ، وفي اليوم الثالث أكمل '),
(23846, 'Luke', 42, 13, 33, ' بل ينبغي أن أسير اليوم وغدا وما يليه ، لأنه لا يمكن أن يهلك نبي خارجا عن أورشليم '),
(23847, 'Luke', 42, 13, 34, ' يا أورشليم ، يا أورشليم يا قاتلة الأنبياء وراجمة المرسلين إليها ، كم مرة أردت أن أجمع أولادك كما تجمع الدجاجة فراخها تحت جناحيها ، ولم تريدوا '),
(23848, 'Luke', 42, 13, 35, ' هوذا بيتكم يترك لكم خرابا والحق أقول لكم : إنكم لا ترونني حتى يأتي وقت تقولون فيه : مبارك الآتي باسم الرب '),
(23849, 'Luke', 42, 14, 1, ' وإذ جاء إلى بيت أحد رؤساء الفريسيين في السبت ليأكل خبزا ، كانوا يراقبونه '),
(23850, 'Luke', 42, 14, 2, ' وإذا إنسان مستسق كان قدامه '),
(23851, 'Luke', 42, 14, 3, ' فأجاب يسوع وكلم الناموسيين والفريسيين قائلا : هل يحل الإبراء في السبت '),
(23852, 'Luke', 42, 14, 4, ' فسكتوا . فأمسكه وأبرأه وأطلقه '),
(23853, 'Luke', 42, 14, 5, ' ثم أجابهم وقال : من منكم يسقط حماره أو ثوره في بئر ولا ينشله حالا في يوم السبت '),
(23854, 'Luke', 42, 14, 6, ' فلم يقدروا أن يجيبوه عن ذلك '),
(23855, 'Luke', 42, 14, 7, ' وقال للمدعوين مثلا ، وهو يلاحظ كيف اختاروا المتكآت الأولى قائلا لهم '),
(23856, 'Luke', 42, 14, 8, ' متى دعيت من أحد إلى عرس فلا تتكئ في المتكإ الأول ، لعل أكرم منك يكون قد دعي منه '),
(23857, 'Luke', 42, 14, 9, ' فيأتي الذي دعاك وإياه ويقول لك : أعط مكانا لهذا . فحينئذ تبتدئ بخجل تأخذ الموضع الأخير '),
(23858, 'Luke', 42, 14, 10, ' بل متى دعيت فاذهب واتكئ في الموضع الأخير ، حتى إذا جاء الذي دعاك يقول لك : يا صديق ، ارتفع إلى فوق . حينئذ يكون لك مجد أمام المتكئين معك '),
(23859, 'Luke', 42, 14, 11, ' لأن كل من يرفع نفسه يتضع ومن يضع نفسه يرتفع '),
(23860, 'Luke', 42, 14, 12, ' وقال أيضا للذي دعاه : إذا صنعت غداء أو عشاء فلا تدع أصدقاءك ولا إخوتك ولا أقرباءك ولا الجيران الأغنياء ، لئلا يدعوك هم أيضا ، فتكون لك مكافاة '),
(23861, 'Luke', 42, 14, 13, ' بل إذا صنعت ضيافة فادع : المساكين ، الجدع ، العرج ، العمي '),
(23862, 'Luke', 42, 14, 14, ' فيكون لك الطوبى إذ ليس لهم حتى يكافوك ، لأنك تكافى في قيامة الأبرار '),
(23863, 'Luke', 42, 14, 15, ' فلما سمع ذلك واحد من المتكئين قال له : طوبى لمن يأكل خبزا في ملكوت الله '),
(23864, 'Luke', 42, 14, 16, ' فقال له : إنسان صنع عشاء عظيما ودعا كثيرين '),
(23865, 'Luke', 42, 14, 17, ' وأرسل عبده في ساعة العشاء ليقول للمدعوين : تعالوا لأن كل شيء قد أعد '),
(23866, 'Luke', 42, 14, 18, ' فابتدأ الجميع برأي واحد يستعفون . قال له الأول : إني اشتريت حقلا ، وأنا مضطر أن أخرج وأنظره . أسألك أن تعفيني '),
(23867, 'Luke', 42, 14, 19, ' وقال آخر : إني اشتريت خمسة أزواج بقر ، وأنا ماض لأمتحنها . أسألك أن تعفيني '),
(23868, 'Luke', 42, 14, 20, ' وقال آخر : إني تزوجت بامرأة ، فلذلك لا أقدر أن أجيء '),
(23869, 'Luke', 42, 14, 21, ' فأتى ذلك العبد وأخبر سيده بذلك . حينئذ غضب رب البيت ، وقال لعبده : اخرج عاجلا إلى شوارع المدينة وأزقتها ، وأدخل إلى هنا المساكين والجدع والعرج والعمي '),
(23870, 'Luke', 42, 14, 22, ' فقال العبد : يا سيد ، قد صار كما أمرت ، ويوجد أيضا مكان '),
(23871, 'Luke', 42, 14, 23, ' فقال السيد للعبد : اخرج إلى الطرق والسياجات وألزمهم بالدخول حتى يمتلئ بيتي '),
(23872, 'Luke', 42, 14, 24, ' لأني أقول لكم : إنه ليس واحد من أولئك الرجال المدعوين يذوق عشائي '),
(23873, 'Luke', 42, 14, 25, ' وكان جموع كثيرة سائرين معه ، فالتفت وقال لهم '),
(23874, 'Luke', 42, 14, 26, ' إن كان أحد يأتي إلي ولا يبغض أباه وأمه وامرأته وأولاده وإخوته وأخواته ، حتى نفسه أيضا ، فلا يقدر أن يكون لي تلميذا '),
(23875, 'Luke', 42, 14, 27, ' ومن لا يحمل صليبه ويأتي ورائي فلا يقدر أن يكون لي تلميذا '),
(23876, 'Luke', 42, 14, 28, ' ومن منكم وهو يريد أن يبني برجا لا يجلس أولا ويحسب النفقة ، هل عنده ما يلزم لكماله '),
(23877, 'Luke', 42, 14, 29, ' لئلا يضع الأساس ولا يقدر أن يكمل ، فيبتدئ جميع الناظرين يهزأون به '),
(23878, 'Luke', 42, 14, 30, ' قائلين : هذا الإنسان ابتدأ يبني ولم يقدر أن يكمل '),
(23879, 'Luke', 42, 14, 31, ' وأي ملك إن ذهب لمقاتلة ملك آخر في حرب ، لا يجلس أولا ويتشاور : هل يستطيع أن يلاقي بعشرة آلاف الذي يأتي عليه بعشرين ألفا '),
(23880, 'Luke', 42, 14, 32, ' وإلا فما دام ذلك بعيدا ، يرسل سفارة ويسأل ما هو للصلح '),
(23881, 'Luke', 42, 14, 33, ' فكذلك كل واحد منكم لا يترك جميع أمواله ، لا يقدر أن يكون لي تلميذا '),
(23882, 'Luke', 42, 14, 34, ' الملح جيد . ولكن إذا فسد الملح ، فبماذا يصلح '),
(23883, 'Luke', 42, 14, 35, ' لا يصلح لأرض ولا لمزبلة ، فيطرحونه خارجا . من له أذنان للسمع ، فليسمع '),
(23884, 'Luke', 42, 15, 1, ' وكان جميع العشارين والخطاة يدنون منه ليسمعوه '),
(23885, 'Luke', 42, 15, 2, ' فتذمر الفريسيون والكتبة قائلين : هذا يقبل خطاة ويأكل معهم '),
(23886, 'Luke', 42, 15, 3, ' فكلمهم بهذا المثل قائلا '),
(23887, 'Luke', 42, 15, 4, ' أي إنسان منكم له مئة خروف ، وأضاع واحدا منها ، ألا يترك التسعة والتسعين في البرية ، ويذهب لأجل الضال حتى يجده '),
(23888, 'Luke', 42, 15, 5, ' وإذا وجده يضعه على منكبيه فرحا '),
(23889, 'Luke', 42, 15, 6, ' ويأتي إلى بيته ويدعو الأصدقاء والجيران قائلا لهم : افرحوا معي ، لأني وجدت خروفي الضال '),
(23890, 'Luke', 42, 15, 7, ' أقول لكم : إنه هكذا يكون فرح في السماء بخاطئ واحد يتوب أكثر من تسعة وتسعين بارا لا يحتاجون إلى توبة '),
(23891, 'Luke', 42, 15, 8, ' أو أية امرأة لها عشرة دراهم ، إن أضاعت درهما واحدا ، ألا توقد سراجا وتكنس البيت وتفتش باجتهاد حتى تجده '),
(23892, 'Luke', 42, 15, 9, ' وإذا وجدته تدعو الصديقات والجارات قائلة : افرحن معي لأني وجدت الدرهم الذي أضعته '),
(23893, 'Luke', 42, 15, 10, ' هكذا ، أقول لكم : يكون فرح قدام ملائكة الله بخاطئ واحد يتوب '),
(23894, 'Luke', 42, 15, 11, ' وقال : إنسان كان له ابنان '),
(23895, 'Luke', 42, 15, 12, ' فقال أصغرهما لأبيه : يا أبي أعطني القسم الذي يصيبني من المال . فقسم لهما معيشته '),
(23896, 'Luke', 42, 15, 13, ' وبعد أيام ليست بكثيرة جمع الابن الأصغر كل شيء وسافر إلى كورة بعيدة ، وهناك بذر ماله بعيش مسرف '),
(23897, 'Luke', 42, 15, 14, ' فلما أنفق كل شيء ، حدث جوع شديد في تلك الكورة ، فابتدأ يحتاج '),
(23898, 'Luke', 42, 15, 15, ' فمضى والتصق بواحد من أهل تلك الكورة ، فأرسله إلى حقوله ليرعى خنازير '),
(23899, 'Luke', 42, 15, 16, ' وكان يشتهي أن يملأ بطنه من الخرنوب الذي كانت الخنازير تأكله ، فلم يعطه أحد '),
(23900, 'Luke', 42, 15, 17, ' فرجع إلى نفسه وقال : كم من أجير لأبي يفضل عنه الخبز وأنا أهلك جوعا '),
(23901, 'Luke', 42, 15, 18, ' أقوم وأذهب إلى أبي وأقول له : يا أبي ، أخطأت إلى السماء وقدامك '),
(23902, 'Luke', 42, 15, 19, ' ولست مستحقا بعد أن أدعى لك ابنا . اجعلني كأحد أجراك '),
(23903, 'Luke', 42, 15, 20, ' فقام وجاء إلى أبيه . وإذ كان لم يزل بعيدا رآه أبوه ، فتحنن وركض ووقع على عنقه وقبله '),
(23904, 'Luke', 42, 15, 21, ' فقال له الابن : يا أبي ، أخطأت إلى السماء وقدامك ، ولست مستحقا بعد أن أدعى لك ابنا '),
(23905, 'Luke', 42, 15, 22, ' فقال الأب لعبيده : أخرجوا الحلة الأولى وألبسوه ، واجعلوا خاتما في يده ، وحذاء في رجليه '),
(23906, 'Luke', 42, 15, 23, ' وقدموا العجل المسمن واذبحوه فنأكل ونفرح '),
(23907, 'Luke', 42, 15, 24, ' لأن ابني هذا كان ميتا فعاش ، وكان ضالا فوجد . فابتدأوا يفرحون '),
(23908, 'Luke', 42, 15, 25, ' وكان ابنه الأكبر في الحقل . فلما جاء وقرب من البيت ، سمع صوت آلات طرب ورقصا '),
(23909, 'Luke', 42, 15, 26, ' فدعا واحدا من الغلمان وسأله : ما عسى أن يكون هذا '),
(23910, 'Luke', 42, 15, 27, ' فقال له : أخوك جاء فذبح أبوك العجل المسمن ، لأنه قبله سالما '),
(23911, 'Luke', 42, 15, 28, ' فغضب ولم يرد أن يدخل . فخرج أبوه يطلب إليه '),
(23912, 'Luke', 42, 15, 29, ' فأجاب وقال لأبيه : ها أنا أخدمك سنين هذا عددها ، وقط لم أتجاوز وصيتك ، وجديا لم تعطني قط لأفرح مع أصدقائي '),
(23913, 'Luke', 42, 15, 30, ' ولكن لما جاء ابنك هذا الذي أكل معيشتك مع الزواني ، ذبحت له العجل المسمن '),
(23914, 'Luke', 42, 15, 31, ' فقال له : يا بني أنت معي في كل حين ، وكل ما لي فهو لك '),
(23915, 'Luke', 42, 15, 32, ' ولكن كان ينبغي أن نفرح ونسر ، لأن أخاك هذا كان ميتا فعاش ، وكان ضالا فوجد '),
(23916, 'Luke', 42, 16, 1, ' وقال أيضا لتلاميذه : كان إنسان غني له وكيل ، فوشي به إليه بأنه يبذر أمواله '),
(23917, 'Luke', 42, 16, 2, ' فدعاه وقال له : ما هذا الذي أسمع عنك ؟ أعط حساب وكالتك لأنك لا تقدر أن تكون وكيلا بعد '),
(23918, 'Luke', 42, 16, 3, ' فقال الوكيل في نفسه : ماذا أفعل ؟ لأن سيدي يأخذ مني الوكالة . لست أستطيع أن أنقب ، وأستحي أن أستعطي '),
(23919, 'Luke', 42, 16, 4, ' قد علمت ماذا أفعل ، حتى إذا عزلت عن الوكالة يقبلوني في بيوتهم '),
(23920, 'Luke', 42, 16, 5, ' فدعا كل واحد من مديوني سيده ، وقال للأول : كم عليك لسيدي '),
(23921, 'Luke', 42, 16, 6, ' فقال : مئة بث زيت . فقال له : خذ صكك واجلس عاجلا واكتب خمسين '),
(23922, 'Luke', 42, 16, 7, ' ثم قال لآخر : وأنت كم عليك ؟ فقال : مئة كر قمح . فقال له : خذ صكك واكتب ثمانين '),
(23923, 'Luke', 42, 16, 8, ' فمدح السيد وكيل الظلم إذ بحكمة فعل ، لأن أبناء هذا الدهر أحكم من أبناء النور في جيلهم '),
(23924, 'Luke', 42, 16, 9, ' وأنا أقول لكم : اصنعوا لكم أصدقاء بمال الظلم ، حتى إذا فنيتم يقبلونكم في المظال الأبدية '),
(23925, 'Luke', 42, 16, 10, ' الأمين في القليل أمين أيضا في الكثير ، والظالم في القليل ظالم أيضا في الكثير '),
(23926, 'Luke', 42, 16, 11, ' فإن لم تكونوا أمناء في مال الظلم ، فمن يأتمنكم على الحق '),
(23927, 'Luke', 42, 16, 12, ' وإن لم تكونوا أمناء في ما هو للغير ، فمن يعطيكم ما هو لكم '),
(23928, 'Luke', 42, 16, 13, ' لا يقدر خادم أن يخدم سيدين ، لأنه إما أن يبغض الواحد ويحب الآخر ، أو يلازم الواحد ويحتقر الآخر . لا تقدرون أن تخدموا الله والمال '),
(23929, 'Luke', 42, 16, 14, ' وكان الفريسيون أيضا يسمعون هذا كله ، وهم محبون للمال ، فاستهزأوا به '),
(23930, 'Luke', 42, 16, 15, ' فقال لهم : أنتم الذين تبررون أنفسكم قدام الناس ولكن الله يعرف قلوبكم . إن المستعلي عند الناس هو رجس قدام الله '),
(23931, 'Luke', 42, 16, 16, ' كان الناموس والأنبياء إلى يوحنا . ومن ذلك الوقت يبشر بملكوت الله ، وكل واحد يغتصب نفسه إليه '),
(23932, 'Luke', 42, 16, 17, ' ولكن زوال السماء والأرض أيسر من أن تسقط نقطة واحدة من الناموس '),
(23933, 'Luke', 42, 16, 18, ' كل من يطلق امرأته ويتزوج بأخرى يزني ، وكل من يتزوج بمطلقة من رجل يزني '),
(23934, 'Luke', 42, 16, 19, ' كان إنسان غني وكان يلبس الأرجوان والبز وهو يتنعم كل يوم مترفها '),
(23935, 'Luke', 42, 16, 20, ' وكان مسكين اسمه لعازر ، الذي طرح عند بابه مضروبا بالقروح '),
(23936, 'Luke', 42, 16, 21, ' ويشتهي أن يشبع من الفتات الساقط من مائدة الغني ، بل كانت الكلاب تأتي وتلحس قروحه '),
(23937, 'Luke', 42, 16, 22, ' فمات المسكين وحملته الملائكة إلى حضن إبراهيم . ومات الغني أيضا ودفن '),
(23938, 'Luke', 42, 16, 23, ' فرفع عينيه في الجحيم وهو في العذاب ، ورأى إبراهيم من بعيد ولعازر في حضنه '),
(23939, 'Luke', 42, 16, 24, ' فنادى وقال : يا أبي إبراهيم ، ارحمني ، وأرسل لعازر ليبل طرف إصبعه بماء ويبرد لساني ، لأني معذب في هذا اللهيب '),
(23940, 'Luke', 42, 16, 25, ' فقال إبراهيم : يا ابني ، اذكر أنك استوفيت خيراتك في حياتك ، وكذلك لعازر البلايا . والآن هو يتعزى وأنت تتعذب '),
(23941, 'Luke', 42, 16, 26, ' وفوق هذا كله ، بيننا وبينكم هوة عظيمة قد أثبتت ، حتى إن الذين يريدون العبور من ههنا إليكم لا يقدرون ، ولا الذين من هناك يجتازون إلينا '),
(23942, 'Luke', 42, 16, 27, ' فقال : أسألك إذا ، يا أبت ، أن ترسله إلى بيت أبي '),
(23943, 'Luke', 42, 16, 28, ' لأن لي خمسة إخوة ، حتى يشهد لهم لكيلا يأتوا هم أيضا إلى موضع العذاب هذا '),
(23944, 'Luke', 42, 16, 29, ' قال له إبراهيم : عندهم موسى والأنبياء ، ليسمعوا منهم '),
(23945, 'Luke', 42, 16, 30, ' فقال : لا ، يا أبي إبراهيم ، بل إذا مضى إليهم واحد من الأموات يتوبون '),
(23946, 'Luke', 42, 16, 31, ' فقال له : إن كانوا لا يسمعون من موسى والأنبياء ، ولا إن قام واحد من الأموات يصدقون '),
(23947, 'Luke', 42, 17, 1, ' وقال لتلاميذه : لا يمكن إلا أن تأتي العثرات ، ولكن ويل للذي تأتي بواسطته '),
(23948, 'Luke', 42, 17, 2, ' خير له لو طوق عنقه بحجر رحى وطرح في البحر ، من أن يعثر أحد هؤلاء الصغار '),
(23949, 'Luke', 42, 17, 3, ' احترزوا لأنفسكم . وإن أخطأ إليك أخوك فوبخه ، وإن تاب فاغفر له '),
(23950, 'Luke', 42, 17, 4, ' وإن أخطأ إليك سبع مرات في اليوم ، ورجع إليك سبع مرات في اليوم قائلا : أنا تائب ، فاغفر له '),
(23951, 'Luke', 42, 17, 5, ' فقال الرسل للرب : زد إيماننا '),
(23952, 'Luke', 42, 17, 6, ' فقال الرب : لو كان لكم إيمان مثل حبة خردل ، لكنتم تقولون لهذه الجميزة : انقلعي وانغرسي في البحر فتطيعكم '),
(23953, 'Luke', 42, 17, 7, ' ومن منكم له عبد يحرث أو يرعى ، يقول له إذا دخل من الحقل : تقدم سريعا واتكئ '),
(23954, 'Luke', 42, 17, 8, ' بل ألا يقول له : أعدد ما أتعشى به ، وتمنطق واخدمني حتى آكل وأشرب ، وبعد ذلك تأكل وتشرب أنت '),
(23955, 'Luke', 42, 17, 9, ' فهل لذلك العبد فضل لأنه فعل ما أمر به ؟ لا أظن '),
(23956, 'Luke', 42, 17, 10, ' كذلك أنتم أيضا ، متى فعلتم كل ما أمرتم به فقولوا : إننا عبيد بطالون ، لأننا إنما عملنا ما كان يجب علينا '),
(23957, 'Luke', 42, 17, 11, ' وفي ذهابه إلى أورشليم اجتاز في وسط السامرة والجليل '),
(23958, 'Luke', 42, 17, 12, ' وفيما هو داخل إلى قرية استقبله عشرة رجال برص ، فوقفوا من بعيد '),
(23959, 'Luke', 42, 17, 13, ' ورفعوا صوتا قائلين : يا يسوع ، يا معلم ، ارحمنا '),
(23960, 'Luke', 42, 17, 14, ' فنظر وقال لهم : اذهبوا وأروا أنفسكم للكهنة . وفيما هم منطلقون طهروا '),
(23961, 'Luke', 42, 17, 15, ' فواحد منهم لما رأى أنه شفي ، رجع يمجد الله بصوت عظيم '),
(23962, 'Luke', 42, 17, 16, ' وخر على وجهه عند رجليه شاكرا له ، وكان سامريا '),
(23963, 'Luke', 42, 17, 17, ' فأجاب يسوع وقال : أليس العشرة قد طهروا ؟ فأين التسعة '),
(23964, 'Luke', 42, 17, 18, ' ألم يوجد من يرجع ليعطي مجدا لله غير هذا الغريب الجنس '),
(23965, 'Luke', 42, 17, 19, ' ثم قال له : قم وامض ، إيمانك خلصك '),
(23966, 'Luke', 42, 17, 20, ' ولما سأله الفريسيون : متى يأتي ملكوت الله ؟ أجابهم وقال : لا يأتي ملكوت الله بمراقبة '),
(23967, 'Luke', 42, 17, 21, ' ولا يقولون : هوذا ههنا ، أو : هوذا هناك لأن ها ملكوت الله داخلكم '),
(23968, 'Luke', 42, 17, 22, ' وقال للتلاميذ : ستأتي أيام فيها تشتهون أن تروا يوما واحدا من أيام ابن الإنسان ولا ترون '),
(23969, 'Luke', 42, 17, 23, ' ويقولون لكم : هوذا ههنا أو : هوذا هناك لا تذهبوا ولا تتبعوا '),
(23970, 'Luke', 42, 17, 24, ' لأنه كما أن البرق الذي يبرق من ناحية تحت السماء يضيء إلى ناحية تحت السماء ، كذلك يكون أيضا ابن الإنسان في يومه '),
(23971, 'Luke', 42, 17, 25, ' ولكن ينبغي أولا أن يتألم كثيرا ويرفض من هذا الجيل '),
(23972, 'Luke', 42, 17, 26, ' وكما كان في أيام نوح كذلك يكون أيضا في أيام ابن الإنسان '),
(23973, 'Luke', 42, 17, 27, ' كانوا يأكلون ويشربون ، ويزوجون ويتزوجون ، إلى اليوم الذي فيه دخل نوح الفلك ، وجاء الطوفان وأهلك الجميع '),
(23974, 'Luke', 42, 17, 28, ' كذلك أيضا كما كان في أيام لوط : كانوا يأكلون ويشربون ، ويشترون ويبيعون ، ويغرسون ويبنون '),
(23975, 'Luke', 42, 17, 29, ' ولكن اليوم الذي فيه خرج لوط من سدوم ، أمطر نارا وكبريتا من السماء فأهلك الجميع '),
(23976, 'Luke', 42, 17, 30, ' هكذا يكون في اليوم الذي فيه يظهر ابن الإنسان '),
(23977, 'Luke', 42, 17, 31, ' في ذلك اليوم من كان على السطح وأمتعته في البيت فلا ينزل ليأخذها ، والذي في الحقل كذلك لا يرجع إلى الوراء '),
(23978, 'Luke', 42, 17, 32, ' اذكروا امرأة لوط '),
(23979, 'Luke', 42, 17, 33, ' من طلب أن يخلص نفسه يهلكها ، ومن أهلكها يحييها '),
(23980, 'Luke', 42, 17, 34, ' أقول لكم : إنه في تلك الليلة يكون اثنان على فراش واحد ، فيؤخذ الواحد ويترك الآخر '),
(23981, 'Luke', 42, 17, 35, ' تكون اثنتان تطحنان معا ، فتؤخذ الواحدة وتترك الأخرى '),
(23982, 'Luke', 42, 17, 36, ' يكون اثنان في الحقل ، فيؤخذ الواحد ويترك الآخر '),
(23983, 'Luke', 42, 17, 37, ' فأجابوا وقالوا له : أين يا رب ؟ فقال لهم : حيث تكون الجثة هناك تجتمع النسور '),
(23984, 'Luke', 42, 18, 1, ' وقال لهم أيضا مثلا في أنه ينبغي أن يصلى كل حين ولا يمل '),
(23985, 'Luke', 42, 18, 2, ' قائلا : كان في مدينة قاض لا يخاف الله ولا يهاب إنسانا '),
(23986, 'Luke', 42, 18, 3, ' وكان في تلك المدينة أرملة . وكانت تأتي إليه قائلة : أنصفني من خصمي '),
(23987, 'Luke', 42, 18, 4, ' وكان لا يشاء إلى زمان . ولكن بعد ذلك قال في نفسه : وإن كنت لا أخاف الله ولا أهاب إنسانا '),
(23988, 'Luke', 42, 18, 5, ' فإني لأجل أن هذه الأرملة تزعجني ، أنصفها ، لئلا تأتي دائما فتقمعني '),
(23989, 'Luke', 42, 18, 6, ' وقال الرب : اسمعوا ما يقول قاضي الظلم '),
(23990, 'Luke', 42, 18, 7, ' أفلا ينصف الله مختاريه ، الصارخين إليه نهارا وليلا ، وهو متمهل عليهم '),
(23991, 'Luke', 42, 18, 8, ' أقول لكم : إنه ينصفهم سريعا ولكن متى جاء ابن الإنسان ، ألعله يجد الإيمان على الأرض '),
(23992, 'Luke', 42, 18, 9, ' وقال لقوم واثقين بأنفسهم أنهم أبرار ، ويحتقرون الآخرين هذا المثل '),
(23993, 'Luke', 42, 18, 10, ' إنسانان صعدا إلى الهيكل ليصليا ، واحد فريسي والآخر عشار '),
(23994, 'Luke', 42, 18, 11, ' أما الفريسي فوقف يصلي في نفسه هكذا : اللهم أنا أشكرك أني لست مثل باقي الناس الخاطفين الظالمين الزناة ، ولا مثل هذا العشار '),
(23995, 'Luke', 42, 18, 12, ' أصوم مرتين في الأسبوع ، وأعشر كل ما أقتنيه '),
(23996, 'Luke', 42, 18, 13, ' وأما العشار فوقف من بعيد ، لا يشاء أن يرفع عينيه نحو السماء ، بل قرع على صدره قائلا : اللهم ارحمني ، أنا الخاطئ '),
(23997, 'Luke', 42, 18, 14, ' أقول لكم : إن هذا نزل إلى بيته مبررا دون ذاك ، لأن كل من يرفع نفسه يتضع ، ومن يضع نفسه يرتفع '),
(23998, 'Luke', 42, 18, 15, ' فقدموا إليه الأطفال أيضا ليلمسهم ، فلما رآهم التلاميذ انتهروهم '),
(23999, 'Luke', 42, 18, 16, ' أما يسوع فدعاهم وقال : دعوا الأولاد يأتون إلي ولا تمنعوهم ، لأن لمثل هؤلاء ملكوت الله '),
(24000, 'Luke', 42, 18, 17, ' الحق أقول لكم : من لا يقبل ملكوت الله مثل ولد فلن يدخله '),
(24001, 'Luke', 42, 18, 18, ' وسأله رئيس قائلا : أيها المعلم الصالح ، ماذا أعمل لأرث الحياة الأبدية '),
(24002, 'Luke', 42, 18, 19, ' فقال له يسوع : لماذا تدعوني صالحا ؟ ليس أحد صالحا إلا واحد وهو الله '),
(24003, 'Luke', 42, 18, 20, ' أنت تعرف الوصايا : لا تزن . لا تقتل . لا تسرق . لا تشهد بالزور . أكرم أباك وأمك '),
(24004, 'Luke', 42, 18, 21, ' فقال : هذه كلها حفظتها منذ حداثتي '),
(24005, 'Luke', 42, 18, 22, ' فلما سمع يسوع ذلك قال له : يعوزك أيضا شيء : بع كل ما لك ووزع على الفقراء ، فيكون لك كنز في السماء ، وتعال اتبعني '),
(24006, 'Luke', 42, 18, 23, ' فلما سمع ذلك حزن ، لأنه كان غنيا جدا '),
(24007, 'Luke', 42, 18, 24, ' فلما رآه يسوع قد حزن ، قال : ما أعسر دخول ذوي الأموال إلى ملكوت الله '),
(24008, 'Luke', 42, 18, 25, ' لأن دخول جمل من ثقب إبرة أيسر من أن يدخل غني إلى ملكوت الله '),
(24009, 'Luke', 42, 18, 26, ' فقال الذين سمعوا : فمن يستطيع أن يخلص '),
(24010, 'Luke', 42, 18, 27, ' فقال : غير المستطاع عند الناس مستطاع عند الله '),
(24011, 'Luke', 42, 18, 28, ' فقال بطرس : ها نحن قد تركنا كل شيء وتبعناك '),
(24012, 'Luke', 42, 18, 29, ' فقال لهم : الحق أقول لكم : إن ليس أحد ترك بيتا أو والدين أو إخوة أو امرأة أو أولادا من أجل ملكوت الله '),
(24013, 'Luke', 42, 18, 30, ' إلا ويأخذ في هذا الزمان أضعافا كثيرة ، وفي الدهر الآتي الحياة الأبدية '),
(24014, 'Luke', 42, 18, 31, ' وأخذ الاثني عشر وقال لهم : ها نحن صاعدون إلى أورشليم ، وسيتم كل ما هو مكتوب بالأنبياء عن ابن الإنسان '),
(24015, 'Luke', 42, 18, 32, ' لأنه يسلم إلى الأمم ، ويستهزأ به ، ويشتم ويتفل عليه '),
(24016, 'Luke', 42, 18, 33, ' ويجلدونه ، ويقتلونه ، وفي اليوم الثالث يقوم '),
(24017, 'Luke', 42, 18, 34, ' وأما هم فلم يفهموا من ذلك شيئا ، وكان هذا الأمر مخفى عنهم ، ولم يعلموا ما قيل '),
(24018, 'Luke', 42, 18, 35, ' ولما اقترب من أريحا كان أعمى جالسا على الطريق يستعطي '),
(24019, 'Luke', 42, 18, 36, ' فلما سمع الجمع مجتازا سأل : ما عسى أن يكون هذا '),
(24020, 'Luke', 42, 18, 37, ' فأخبروه أن يسوع الناصري مجتاز '),
(24021, 'Luke', 42, 18, 38, ' فصرخ قائلا : يا يسوع ابن داود ، ارحمني '),
(24022, 'Luke', 42, 18, 39, ' فانتهره المتقدمون ليسكت ، أما هو فصرخ أكثر كثيرا : يا ابن داود ، ارحمني '),
(24023, 'Luke', 42, 18, 40, ' فوقف يسوع وأمر أن يقدم إليه . ولما اقترب سأله '),
(24024, 'Luke', 42, 18, 41, ' قائلا : ماذا تريد أن أفعل بك ؟ فقال : يا سيد ، أن أبصر '),
(24025, 'Luke', 42, 18, 42, ' فقال له يسوع : أبصر . إيمانك قد شفاك '),
(24026, 'Luke', 42, 18, 43, ' وفي الحال أبصر ، وتبعه وهو يمجد الله . وجميع الشعب إذ رأوا سبحوا الله '),
(24027, 'Luke', 42, 19, 1, ' ثم دخل واجتاز في أريحا '),
(24028, 'Luke', 42, 19, 2, ' وإذا رجل اسمه زكا ، وهو رئيس للعشارين وكان غنيا '),
(24029, 'Luke', 42, 19, 3, ' وطلب أن يرى يسوع من هو ، ولم يقدر من الجمع ، لأنه كان قصير القامة '),
(24030, 'Luke', 42, 19, 4, ' فركض متقدما وصعد إلى جميزة لكي يراه ، لأنه كان مزمعا أن يمر من هناك '),
(24031, 'Luke', 42, 19, 5, ' فلما جاء يسوع إلى المكان ، نظر إلى فوق فرآه ، وقال له : يا زكا ، أسرع وانزل ، لأنه ينبغي أن أمكث اليوم في بيتك '),
(24032, 'Luke', 42, 19, 6, ' فأسرع ونزل وقبله فرحا '),
(24033, 'Luke', 42, 19, 7, ' فلما رأى الجميع ذلك تذمروا قائلين : إنه دخل ليبيت عند رجل خاطئ '),
(24034, 'Luke', 42, 19, 8, ' فوقف زكا وقال للرب : ها أنا يا رب أعطي نصف أموالي للمساكين ، وإن كنت قد وشيت بأحد أرد أربعة أضعاف '),
(24035, 'Luke', 42, 19, 9, ' فقال له يسوع : اليوم حصل خلاص لهذا البيت ، إذ هو أيضا ابن إبراهيم '),
(24036, 'Luke', 42, 19, 10, ' لأن ابن الإنسان قد جاء لكي يطلب ويخلص ما قد هلك '),
(24037, 'Luke', 42, 19, 11, ' وإذ كانوا يسمعون هذا عاد فقال مثلا ، لأنه كان قريبا من أورشليم ، وكانوا يظنون أن ملكوت الله عتيد أن يظهر في الحال '),
(24038, 'Luke', 42, 19, 12, ' فقال : إنسان شريف الجنس ذهب إلى كورة بعيدة ليأخذ لنفسه ملكا ويرجع '),
(24039, 'Luke', 42, 19, 13, ' فدعا عشرة عبيد له وأعطاهم عشرة أمناء ، وقال لهم : تاجروا حتى آتي '),
(24040, 'Luke', 42, 19, 14, ' وأما أهل مدينته فكانوا يبغضونه ، فأرسلوا وراءه سفارة قائلين : لا نريد أن هذا يملك علينا '),
(24041, 'Luke', 42, 19, 15, ' ولما رجع بعدما أخذ الملك ، أمر أن يدعى إليه أولئك العبيد الذين أعطاهم الفضة ، ليعرف بما تاجر كل واحد '),
(24042, 'Luke', 42, 19, 16, ' فجاء الأول قائلا : يا سيد ، مناك ربح عشرة أمناء '),
(24043, 'Luke', 42, 19, 17, ' فقال له : نعما أيها العبد الصالح لأنك كنت أمينا في القليل ، فليكن لك سلطان على عشر مدن '),
(24044, 'Luke', 42, 19, 18, ' ثم جاء الثاني قائلا : يا سيد ، مناك عمل خمسة أمناء '),
(24045, 'Luke', 42, 19, 19, ' فقال لهذا أيضا : وكن أنت على خمس مدن '),
(24046, 'Luke', 42, 19, 20, ' ثم جاء آخر قائلا : يا سيد ، هوذا مناك الذي كان عندي موضوعا في منديل '),
(24047, 'Luke', 42, 19, 21, ' لأني كنت أخاف منك ، إذ أنت إنسان صارم ، تأخذ ما لم تضع وتحصد ما لم تزرع '),
(24048, 'Luke', 42, 19, 22, ' فقال له : من فمك أدينك أيها العبد الشرير . عرفت أني إنسان صارم ، آخذ ما لم أضع ، وأحصد ما لم أزرع '),
(24049, 'Luke', 42, 19, 23, ' فلماذا لم تضع فضتي على مائدة الصيارفة ، فكنت متى جئت أستوفيها مع ربا '),
(24050, 'Luke', 42, 19, 24, ' ثم قال للحاضرين : خذوا منه المنا وأعطوه للذي عنده العشرة الأمناء '),
(24051, 'Luke', 42, 19, 25, ' فقالوا له : يا سيد ، عنده عشرة أمناء '),
(24052, 'Luke', 42, 19, 26, ' لأني أقول لكم : إن كل من له يعطى ، ومن ليس له فالذي عنده يؤخذ منه '),
(24053, 'Luke', 42, 19, 27, ' أما أعدائي ، أولئك الذين لم يريدوا أن أملك عليهم ، فأتوا بهم إلى هنا واذبحوهم قدامي '),
(24054, 'Luke', 42, 19, 28, ' ولما قال هذا تقدم صاعدا إلى أورشليم '),
(24055, 'Luke', 42, 19, 29, ' وإذ قرب من بيت فاجي وبيت عنيا ، عند الجبل الذي يدعى جبل الزيتون ، أرسل اثنين من تلاميذه '),
(24056, 'Luke', 42, 19, 30, ' قائلا : اذهبا إلى القرية التي أمامكما ، وحين تدخلانها تجدان جحشا مربوطا لم يجلس عليه أحد من الناس قط . فحلاه وأتيا به '),
(24057, 'Luke', 42, 19, 31, ' وإن سألكما أحد : لماذا تحلانه ؟ فقولا له هكذا : إن الرب محتاج إليه '),
(24058, 'Luke', 42, 19, 32, ' فمضى المرسلان ووجدا كما قال لهما '),
(24059, 'Luke', 42, 19, 33, ' وفيما هما يحلان الجحش قال لهما أصحابه : لماذا تحلان الجحش '),
(24060, 'Luke', 42, 19, 34, ' فقالا : الرب محتاج إليه '),
(24061, 'Luke', 42, 19, 35, ' وأتيا به إلى يسوع ، وطرحا ثيابهما على الجحش ، وأركبا يسوع '),
(24062, 'Luke', 42, 19, 36, ' وفيما هو سائر فرشوا ثيابهم في الطريق '),
(24063, 'Luke', 42, 19, 37, ' ولما قرب عند منحدر جبل الزيتون ، ابتدأ كل جمهور التلاميذ يفرحون ويسبحون الله بصوت عظيم ، لأجل جميع القوات التي نظروا '),
(24064, 'Luke', 42, 19, 38, ' قائلين : مبارك الملك الآتي باسم الرب سلام في السماء ومجد في الأعالي '),
(24065, 'Luke', 42, 19, 39, ' وأما بعض الفريسيين من الجمع فقالوا له : يا معلم ، انتهر تلاميذك '),
(24066, 'Luke', 42, 19, 40, ' فأجاب وقال لهم : أقول لكم : إنه إن سكت هؤلاء فالحجارة تصرخ '),
(24067, 'Luke', 42, 19, 41, ' وفيما هو يقترب نظر إلى المدينة وبكى عليها '),
(24068, 'Luke', 42, 19, 42, ' قائلا : إنك لو علمت أنت أيضا ، حتى في يومك هذا ، ما هو لسلامك ولكن الآن قد أخفي عن عينيك '),
(24069, 'Luke', 42, 19, 43, ' فإنه ستأتي أيام ويحيط بك أعداؤك بمترسة ، ويحدقون بك ويحاصرونك من كل جهة '),
(24070, 'Luke', 42, 19, 44, ' ويهدمونك وبنيك فيك ، ولا يتركون فيك حجرا على حجر ، لأنك لم تعرفي زمان افتقادك '),
(24071, 'Luke', 42, 19, 45, ' ولما دخل الهيكل ابتدأ يخرج الذين كانوا يبيعون ويشترون فيه '),
(24072, 'Luke', 42, 19, 46, ' قائلا لهم : مكتوب : إن بيتي بيت الصلاة . وأنتم جعلتموه مغارة لصوص '),
(24073, 'Luke', 42, 19, 47, ' وكان يعلم كل يوم في الهيكل ، وكان رؤساء الكهنة والكتبة مع وجوه الشعب يطلبون أن يهلكوه '),
(24074, 'Luke', 42, 19, 48, ' ولم يجدوا ما يفعلون ، لأن الشعب كله كان متعلقا به يسمع منه '),
(24075, 'Luke', 42, 20, 1, ' وفي أحد تلك الأيام إذ كان يعلم الشعب في الهيكل ويبشر ، وقف رؤساء الكهنة والكتبة مع الشيوخ '),
(24076, 'Luke', 42, 20, 2, ' وكلموه قائلين : قل لنا : بأي سلطان تفعل هذا ؟ أو من هو الذي أعطاك هذا السلطان '),
(24077, 'Luke', 42, 20, 3, ' فأجاب وقال لهم : وأنا أيضا أسألكم كلمة واحدة ، فقولوا لي '),
(24078, 'Luke', 42, 20, 4, ' معمودية يوحنا : من السماء كانت أم من الناس '),
(24079, 'Luke', 42, 20, 5, ' فتآمروا فيما بينهم قائلين : إن قلنا : من السماء ، يقول : فلماذا لم تؤمنوا به '),
(24080, 'Luke', 42, 20, 6, ' وإن قلنا : من الناس ، فجميع الشعب يرجموننا ، لأنهم واثقون بأن يوحنا نبي '),
(24081, 'Luke', 42, 20, 7, ' فأجابوا أنهم لا يعلمون من أين '),
(24082, 'Luke', 42, 20, 8, ' فقال لهم يسوع : ولا أنا أقول لكم بأي سلطان أفعل هذا '),
(24083, 'Luke', 42, 20, 9, ' وابتدأ يقول للشعب هذا المثل : إنسان غرس كرما وسلمه إلى كرامين وسافر زمانا طويلا '),
(24084, 'Luke', 42, 20, 10, ' وفي الوقت أرسل إلى الكرامين عبدا لكي يعطوه من ثمر الكرم ، فجلده الكرامون ، وأرسلوه فارغا '),
(24085, 'Luke', 42, 20, 11, ' فعاد وأرسل عبدا آخر ، فجلدوا ذلك أيضا وأهانوه ، وأرسلوه فارغا '),
(24086, 'Luke', 42, 20, 12, ' ثم عاد فأرسل ثالثا ، فجرحوا هذا أيضا وأخرجوه '),
(24087, 'Luke', 42, 20, 13, ' فقال صاحب الكرم : ماذا أفعل ؟ أرسل ابني الحبيب ، لعلهم إذا رأوه يهابون '),
(24088, 'Luke', 42, 20, 14, ' فلما رآه الكرامون تآمروا فيما بينهم قائلين : هذا هو الوارث هلموا نقتله لكي يصير لنا الميراث '),
(24089, 'Luke', 42, 20, 15, ' فأخرجوه خارج الكرم وقتلوه . فماذا يفعل بهم صاحب الكرم '),
(24090, 'Luke', 42, 20, 16, ' يأتي ويهلك هؤلاء الكرامين ويعطي الكرم لآخرين . فلما سمعوا قالوا : حاشا '),
(24091, 'Luke', 42, 20, 17, ' فنظر إليهم وقال : إذا ما هو هذا المكتوب : الحجر الذي رفضه البناؤون هو قد صار رأس الزاوية '),
(24092, 'Luke', 42, 20, 18, ' كل من يسقط على ذلك الحجر يترضض ، ومن سقط هو عليه يسحقه '),
(24093, 'Luke', 42, 20, 19, ' فطلب رؤساء الكهنة والكتبة أن يلقوا الأيادي عليه في تلك الساعة ، ولكنهم خافوا الشعب ، لأنهم عرفوا أنه قال هذا المثل عليهم '),
(24094, 'Luke', 42, 20, 20, ' فراقبوه وأرسلوا جواسيس يتراءون أنهم أبرار لكي يمسكوه بكلمة ، حتى يسلموه إلى حكم الوالي وسلطانه '),
(24095, 'Luke', 42, 20, 21, ' فسألوه قائلين : يا معلم ، نعلم أنك بالاستقامة تتكلم وتعلم ، ولا تقبل الوجوه ، بل بالحق تعلم طريق الله '),
(24096, 'Luke', 42, 20, 22, ' أيجوز لنا أن نعطي جزية لقيصر أم لا '),
(24097, 'Luke', 42, 20, 23, ' فشعر بمكرهم وقال لهم : لماذا تجربونني '),
(24098, 'Luke', 42, 20, 24, ' أروني دينارا . لمن الصورة والكتابة ؟ فأجابوا وقالوا : لقيصر '),
(24099, 'Luke', 42, 20, 25, ' فقال لهم : أعطوا إذا ما لقيصر لقيصر وما لله لله '),
(24100, 'Luke', 42, 20, 26, ' فلم يقدروا أن يمسكوه بكلمة قدام الشعب ، وتعجبوا من جوابه وسكتوا '),
(24101, 'Luke', 42, 20, 27, ' وحضر قوم من الصدوقيين ، الذين يقاومون أمر القيامة ، وسألوه '),
(24102, 'Luke', 42, 20, 28, ' قائلين : يا معلم ، كتب لنا موسى : إن مات لأحد أخ وله امرأة ، ومات بغير ولد ، يأخذ أخوه المرأة ويقيم نسلا لأخيه '),
(24103, 'Luke', 42, 20, 29, ' فكان سبعة إخوة . وأخذ الأول امرأة ومات بغير ولد '),
(24104, 'Luke', 42, 20, 30, ' فأخذ الثاني المرأة ومات بغير ولد '),
(24105, 'Luke', 42, 20, 31, ' ثم أخذها الثالث ، وهكذا السبعة . ولم يتركوا ولدا وماتوا '),
(24106, 'Luke', 42, 20, 32, ' وآخر الكل ماتت المرأة أيضا '),
(24107, 'Luke', 42, 20, 33, ' ففي القيامة ، لمن منهم تكون زوجة ؟ لأنها كانت زوجة للسبعة '),
(24108, 'Luke', 42, 20, 34, ' فأجاب وقال لهم يسوع : أبناء هذا الدهر يزوجون ويزوجون '),
(24109, 'Luke', 42, 20, 35, ' ولكن الذين حسبوا أهلا للحصول على ذلك الدهر والقيامة من الأموات ، لا يزوجون ولا يزوجون '),
(24110, 'Luke', 42, 20, 36, ' إذ لا يستطيعون أن يموتوا أيضا ، لأنهم مثل الملائكة ، وهم أبناء الله ، إذ هم أبناء القيامة '),
(24111, 'Luke', 42, 20, 37, ' وأما أن الموتى يقومون ، فقد دل عليه موسى أيضا في أمر العليقة كما يقول : الرب إله إبراهيم وإله إسحاق وإله يعقوب '),
(24112, 'Luke', 42, 20, 38, ' وليس هو إله أموات بل إله أحياء ، لأن الجميع عنده أحياء '),
(24113, 'Luke', 42, 20, 39, ' فأجاب قوم من الكتبة وقالوا : يا معلم ، حسنا قلت '),
(24114, 'Luke', 42, 20, 40, ' ولم يتجاسروا أيضا أن يسألوه عن شيء '),
(24115, 'Luke', 42, 20, 41, ' وقال لهم : كيف يقولون إن المسيح ابن داود ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(24116, 'Luke', 42, 20, 42, ' وداود نفسه يقول في كتاب المزامير : قال الرب لربي : اجلس عن يميني '),
(24117, 'Luke', 42, 20, 43, ' حتى أضع أعداءك موطئا لقدميك '),
(24118, 'Luke', 42, 20, 44, ' فإذا داود يدعوه ربا . فكيف يكون ابنه '),
(24119, 'Luke', 42, 20, 45, ' وفيما كان جميع الشعب يسمعون قال لتلاميذه '),
(24120, 'Luke', 42, 20, 46, ' احذروا من الكتبة الذين يرغبون المشي بالطيالسة ، ويحبون التحيات في الأسواق ، والمجالس الأولى في المجامع ، والمتكآت الأولى في الولائم '),
(24121, 'Luke', 42, 20, 47, ' الذين يأكلون بيوت الأرامل ، ولعلة يطيلون الصلوات . هؤلاء يأخذون دينونة أعظم '),
(24122, 'Luke', 42, 21, 1, ' وتطلع فرأى الأغنياء يلقون قرابينهم في الخزانة '),
(24123, 'Luke', 42, 21, 2, ' ورأى أيضا أرملة مسكينة ألقت هناك فلسين '),
(24124, 'Luke', 42, 21, 3, ' فقال : بالحق أقول لكم : إن هذه الأرملة الفقيرة ألقت أكثر من الجميع '),
(24125, 'Luke', 42, 21, 4, ' لأن هؤلاء من فضلتهم ألقوا في قرابين الله ، وأما هذه فمن إعوازها ، ألقت كل المعيشة التي لها '),
(24126, 'Luke', 42, 21, 5, ' وإذ كان قوم يقولون عن الهيكل إنه مزين بحجارة حسنة وتحف ، قال '),
(24127, 'Luke', 42, 21, 6, ' هذه التي ترونها ، ستأتي أيام لا يترك فيها حجر على حجر لا ينقض '),
(24128, 'Luke', 42, 21, 7, ' فسألوه قائلين : يا معلم ، متى يكون هذا ؟ وما هي العلامة عندما يصير هذا '),
(24129, 'Luke', 42, 21, 8, ' فقال : انظروا لا تضلوا . فإن كثيرين سيأتون باسمي قائلين : إني أنا هو والزمان قد قرب فلا تذهبوا وراءهم '),
(24130, 'Luke', 42, 21, 9, ' فإذا سمعتم بحروب وقلاقل فلا تجزعوا ، لأنه لابد أن يكون هذا أولا ، ولكن لا يكون المنتهى سريعا '),
(24131, 'Luke', 42, 21, 10, ' ثم قال لهم : تقوم أمة على أمة ومملكة على مملكة '),
(24132, 'Luke', 42, 21, 11, ' وتكون زلازل عظيمة في أماكن ، ومجاعات وأوبئة . وتكون مخاوف وعلامات عظيمة من السماء '),
(24133, 'Luke', 42, 21, 12, ' وقبل هذا كله يلقون أيديهم عليكم ويطردونكم ، ويسلمونكم إلى مجامع وسجون ، وتساقون أمام ملوك وولاة لأجل اسمي '),
(24134, 'Luke', 42, 21, 13, ' فيؤول ذلك لكم شهادة '),
(24135, 'Luke', 42, 21, 14, ' فضعوا في قلوبكم أن لا تهتموا من قبل لكي تحتجوا '),
(24136, 'Luke', 42, 21, 15, ' لأني أنا أعطيكم فما وحكمة لا يقدر جميع معانديكم أن يقاوموها أو يناقضوها '),
(24137, 'Luke', 42, 21, 16, ' وسوف تسلمون من الوالدين والإخوة والأقرباء والأصدقاء ، ويقتلون منكم '),
(24138, 'Luke', 42, 21, 17, ' وتكونون مبغضين من الجميع من أجل اسمي '),
(24139, 'Luke', 42, 21, 18, ' ولكن شعرة من رؤوسكم لا تهلك '),
(24140, 'Luke', 42, 21, 19, ' بصبركم اقتنوا أنفسكم '),
(24141, 'Luke', 42, 21, 20, ' ومتى رأيتم أورشليم محاطة بجيوش ، فحينئذ اعلموا أنه قد اقترب خرابها '),
(24142, 'Luke', 42, 21, 21, ' حينئذ ليهرب الذين في اليهودية إلى الجبال ، والذين في وسطها فليفروا خارجا ، والذين في الكور فلا يدخلوها '),
(24143, 'Luke', 42, 21, 22, ' لأن هذه أيام انتقام ، ليتم كل ما هو مكتوب '),
(24144, 'Luke', 42, 21, 23, ' وويل للحبالى والمرضعات في تلك الأيام لأنه يكون ضيق عظيم على الأرض وسخط على هذا الشعب '),
(24145, 'Luke', 42, 21, 24, ' ويقعون بفم السيف ، ويسبون إلى جميع الأمم ، وتكون أورشليم مدوسة من الأمم ، حتى تكمل أزمنة الأمم '),
(24146, 'Luke', 42, 21, 25, ' وتكون علامات في الشمس والقمر والنجوم ، وعلى الأرض كرب أمم بحيرة . البحر والأمواج تضج '),
(24147, 'Luke', 42, 21, 26, ' والناس يغشى عليهم من خوف وانتظار ما يأتي على المسكونة ، لأن قوات السماوات تتزعزع '),
(24148, 'Luke', 42, 21, 27, ' وحينئذ يبصرون ابن الإنسان آتيا في سحابة بقوة ومجد كثير '),
(24149, 'Luke', 42, 21, 28, ' ومتى ابتدأت هذه تكون ، فانتصبوا وارفعوا رؤوسكم لأن نجاتكم تقترب '),
(24150, 'Luke', 42, 21, 29, ' وقال لهم مثلا : انظروا إلى شجرة التين وكل الأشجار '),
(24151, 'Luke', 42, 21, 30, ' متى أفرخت تنظرون وتعلمون من أنفسكم أن الصيف قد قرب '),
(24152, 'Luke', 42, 21, 31, ' هكذا أنتم أيضا ، متى رأيتم هذه الأشياء صائرة ، فاعلموا أن ملكوت الله قريب '),
(24153, 'Luke', 42, 21, 32, ' الحق أقول لكم : إنه لا يمضي هذا الجيل حتى يكون الكل '),
(24154, 'Luke', 42, 21, 33, ' السماء والأرض تزولان ، ولكن كلامي لا يزول '),
(24155, 'Luke', 42, 21, 34, ' فاحترزوا لأنفسكم لئلا تثقل قلوبكم في خمار وسكر وهموم الحياة ، فيصادفكم ذلك اليوم بغتة '),
(24156, 'Luke', 42, 21, 35, ' لأنه كالفخ يأتي على جميع الجالسين على وجه كل الأرض '),
(24157, 'Luke', 42, 21, 36, ' اسهروا إذا وتضرعوا في كل حين ، لكي تحسبوا أهلا للنجاة من جميع هذا المزمع أن يكون ، وتقفوا قدام ابن الإنسان '),
(24158, 'Luke', 42, 21, 37, ' وكان في النهار يعلم في الهيكل ، وفي الليل يخرج ويبيت في الجبل الذي يدعى جبل الزيتون '),
(24159, 'Luke', 42, 21, 38, ' وكان كل الشعب يبكرون إليه في الهيكل ليسمعوه '),
(24160, 'Luke', 42, 22, 1, ' وقرب عيد الفطير ، الذي يقال له الفصح '),
(24161, 'Luke', 42, 22, 2, ' وكان رؤساء الكهنة والكتبة يطلبون كيف يقتلونه ، لأنهم خافوا الشعب '),
(24162, 'Luke', 42, 22, 3, ' فدخل الشيطان في يهوذا الذي يدعى الإسخريوطي ، وهو من جملة الاثني عشر '),
(24163, 'Luke', 42, 22, 4, ' فمضى وتكلم مع رؤساء الكهنة وقواد الجند كيف يسلمه إليهم '),
(24164, 'Luke', 42, 22, 5, ' ففرحوا وعاهدوه أن يعطوه فضة '),
(24165, 'Luke', 42, 22, 6, ' فواعدهم . وكان يطلب فرصة ليسلمه إليهم خلوا من جمع '),
(24166, 'Luke', 42, 22, 7, ' وجاء يوم الفطير الذي كان ينبغي أن يذبح فيه الفصح '),
(24167, 'Luke', 42, 22, 8, ' فأرسل بطرس ويوحنا قائلا : اذهبا وأعدا لنا الفصح لنأكل '),
(24168, 'Luke', 42, 22, 9, ' فقالا له : أين تريد أن نعد '),
(24169, 'Luke', 42, 22, 10, ' فقال لهما : إذا دخلتما المدينة يستقبلكما إنسان حامل جرة ماء . اتبعاه إلى البيت حيث يدخل '),
(24170, 'Luke', 42, 22, 11, ' وقولا لرب البيت : يقول لك المعلم : أين المنزل حيث آكل الفصح مع تلاميذي '),
(24171, 'Luke', 42, 22, 12, ' فذاك يريكما علية كبيرة مفروشة . هناك أعدا '),
(24172, 'Luke', 42, 22, 13, ' فانطلقا ووجدا كما قال لهما ، فأعدا الفصح '),
(24173, 'Luke', 42, 22, 14, ' ولما كانت الساعة اتكأ والاثنا عشر رسولا معه '),
(24174, 'Luke', 42, 22, 15, ' وقال لهم : شهوة اشتهيت أن آكل هذا الفصح معكم قبل أن أتألم '),
(24175, 'Luke', 42, 22, 16, ' لأني أقول لكم : إني لا آكل منه بعد حتى يكمل في ملكوت الله '),
(24176, 'Luke', 42, 22, 17, ' ثم تناول كأسا وشكر وقال : خذوا هذه واقتسموها بينكم '),
(24177, 'Luke', 42, 22, 18, ' لأني أقول لكم : إني لا أشرب من نتاج الكرمة حتى يأتي ملكوت الله '),
(24178, 'Luke', 42, 22, 19, ' وأخذ خبزا وشكر وكسر وأعطاهم قائلا : هذا هو جسدي الذي يبذل عنكم . اصنعوا هذا لذكري '),
(24179, 'Luke', 42, 22, 20, ' وكذلك الكأس أيضا بعد العشاء قائلا : هذه الكأس هي العهد الجديد بدمي الذي يسفك عنكم '),
(24180, 'Luke', 42, 22, 21, ' ولكن هوذا يد الذي يسلمني هي معي على المائدة '),
(24181, 'Luke', 42, 22, 22, ' وابن الإنسان ماض كما هو محتوم ، ولكن ويل لذلك الإنسان الذي يسلمه '),
(24182, 'Luke', 42, 22, 23, ' فابتدأوا يتساءلون فيما بينهم : من ترى منهم هو المزمع أن يفعل هذا '),
(24183, 'Luke', 42, 22, 24, ' وكانت بينهم أيضا مشاجرة من منهم يظن أنه يكون أكبر '),
(24184, 'Luke', 42, 22, 25, ' فقال لهم : ملوك الأمم يسودونهم ، والمتسلطون عليهم يدعون محسنين '),
(24185, 'Luke', 42, 22, 26, ' وأما أنتم فليس هكذا ، بل الكبير فيكم ليكن كالأصغر ، والمتقدم كالخادم '),
(24186, 'Luke', 42, 22, 27, ' لأن من هو أكبر : ألذي يتكئ أم الذي يخدم ؟ أليس الذي يتكئ ؟ ولكني أنا بينكم كالذي يخدم '),
(24187, 'Luke', 42, 22, 28, ' أنتم الذين ثبتوا معي في تجاربي '),
(24188, 'Luke', 42, 22, 29, ' وأنا أجعل لكم كما جعل لي أبي ملكوتا '),
(24189, 'Luke', 42, 22, 30, ' لتأكلوا وتشربوا على مائدتي في ملكوتي ، وتجلسوا على كراسي تدينون أسباط إسرائيل الاثني عشر '),
(24190, 'Luke', 42, 22, 31, ' وقال الرب : سمعان ، سمعان ، هوذا الشيطان طلبكم لكي يغربلكم كالحنطة '),
(24191, 'Luke', 42, 22, 32, ' ولكني طلبت من أجلك لكي لا يفنى إيمانك . وأنت متى رجعت ثبت إخوتك '),
(24192, 'Luke', 42, 22, 33, ' فقال له : يا رب ، إني مستعد أن أمضي معك حتى إلى السجن وإلى الموت '),
(24193, 'Luke', 42, 22, 34, ' فقال : أقول لك يا بطرس : لا يصيح الديك اليوم قبل أن تنكر ثلاث مرات أنك تعرفني '),
(24194, 'Luke', 42, 22, 35, ' ثم قال لهم : حين أرسلتكم بلا كيس ولا مزود ولا أحذية ، هل أعوزكم شيء ؟ فقالوا : لا '),
(24195, 'Luke', 42, 22, 36, ' فقال لهم : لكن الآن ، من له كيس فليأخذه ومزود كذلك . ومن ليس له فليبع ثوبه ويشتر سيفا '),
(24196, 'Luke', 42, 22, 37, ' لأني أقول لكم : إنه ينبغي أن يتم في أيضا هذا المكتوب : وأحصي مع أثمة . لأن ما هو من جهتي له انقضاء '),
(24197, 'Luke', 42, 22, 38, ' فقالوا : يا رب ، هوذا هنا سيفان . فقال لهم : يكفي '),
(24198, 'Luke', 42, 22, 39, ' وخرج ومضى كالعادة إلى جبل الزيتون ، وتبعه أيضا تلاميذه '),
(24199, 'Luke', 42, 22, 40, ' ولما صار إلى المكان قال لهم : صلوا لكي لا تدخلوا في تجربة '),
(24200, 'Luke', 42, 22, 41, ' وانفصل عنهم نحو رمية حجر وجثا على ركبتيه وصلى '),
(24201, 'Luke', 42, 22, 42, ' قائلا : يا أبتاه ، إن شئت أن تجيز عني هذه الكأس . ولكن لتكن لا إرادتي بل إرادتك '),
(24202, 'Luke', 42, 22, 43, ' وظهر له ملاك من السماء يقويه '),
(24203, 'Luke', 42, 22, 44, ' وإذ كان في جهاد كان يصلي بأشد لجاجة ، وصار عرقه كقطرات دم نازلة على الأرض '),
(24204, 'Luke', 42, 22, 45, ' ثم قام من الصلاة وجاء إلى تلاميذه ، فوجدهم نياما من الحزن '),
(24205, 'Luke', 42, 22, 46, ' فقال لهم : لماذا أنتم نيام ؟ قوموا وصلوا لئلا تدخلوا في تجربة '),
(24206, 'Luke', 42, 22, 47, ' وبينما هو يتكلم إذا جمع ، والذي يدعى يهوذا ، أحد الاثني عشر ، يتقدمهم ، فدنا من يسوع ليقبله '),
(24207, 'Luke', 42, 22, 48, ' فقال له يسوع يا يهوذا ، أبقبلة تسلم ابن الإنسان '),
(24208, 'Luke', 42, 22, 49, ' فلما رأى الذين حوله ما يكون ، قالوا : يا رب ، أنضرب بالسيف '),
(24209, 'Luke', 42, 22, 50, ' وضرب واحد منهم عبد رئيس الكهنة فقطع أذنه اليمنى '),
(24210, 'Luke', 42, 22, 51, ' فأجاب يسوع وقال : دعوا إلى هذا ولمس أذنه وأبرأها '),
(24211, 'Luke', 42, 22, 52, ' ثم قال يسوع لرؤساء الكهنة وقواد جند الهيكل والشيوخ المقبلين عليه : كأنه على لص خرجتم بسيوف وعصي '),
(24212, 'Luke', 42, 22, 53, ' إذ كنت معكم كل يوم في الهيكل لم تمدوا علي الأيادي . ولكن هذه ساعتكم وسلطان الظلمة '),
(24213, 'Luke', 42, 22, 54, ' فأخذوه وساقوه وأدخلوه إلى بيت رئيس الكهنة . وأما بطرس فتبعه من بعيد '),
(24214, 'Luke', 42, 22, 55, ' ولما أضرموا نارا في وسط الدار وجلسوا معا ، جلس بطرس بينهم '),
(24215, 'Luke', 42, 22, 56, ' فرأته جارية جالسا عند النار فتفرست فيه وقالت : وهذا كان معه '),
(24216, 'Luke', 42, 22, 57, ' فأنكره قائلا : لست أعرفه يا امرأة '),
(24217, 'Luke', 42, 22, 58, ' وبعد قليل رآه آخر وقال : وأنت منهم فقال بطرس : يا إنسان ، لست أنا '),
(24218, 'Luke', 42, 22, 59, ' ولما مضى نحو ساعة واحدة أكد آخر قائلا : بالحق إن هذا أيضا كان معه ، لأنه جليلي أيضا '),
(24219, 'Luke', 42, 22, 60, ' فقال بطرس : يا إنسان ، لست أعرف ما تقول . وفي الحال بينما هو يتكلم صاح الديك '),
(24220, 'Luke', 42, 22, 61, ' فالتفت الرب ونظر إلى بطرس ، فتذكر بطرس كلام الرب ، كيف قال له : إنك قبل أن يصيح الديك تنكرني ثلاث مرات '),
(24221, 'Luke', 42, 22, 62, ' فخرج بطرس إلى خارج وبكى بكاء مرا '),
(24222, 'Luke', 42, 22, 63, ' والرجال الذين كانوا ضابطين يسوع كانوا يستهزئون به وهم يجلدونه '),
(24223, 'Luke', 42, 22, 64, ' وغطوه وكانوا يضربون وجهه ويسألونه قائلين : تنبأ من هو الذي ضربك '),
(24224, 'Luke', 42, 22, 65, ' وأشياء أخر كثيرة كانوا يقولون عليه مجدفين '),
(24225, 'Luke', 42, 22, 66, ' ولما كان النهار اجتمعت مشيخة الشعب : رؤساء الكهنة والكتبة ، وأصعدوه إلى مجمعهم '),
(24226, 'Luke', 42, 22, 67, ' قائلين : إن كنت أنت المسيح ، فقل لنا . فقال لهم : إن قلت لكم لا تصدقون '),
(24227, 'Luke', 42, 22, 68, ' وإن سألت لا تجيبونني ولا تطلقونني '),
(24228, 'Luke', 42, 22, 69, ' منذ الآن يكون ابن الإنسان جالسا عن يمين قوة الله '),
(24229, 'Luke', 42, 22, 70, ' فقال الجميع : أفأنت ابن الله ؟ فقال لهم : أنتم تقولون إني أنا هو '),
(24230, 'Luke', 42, 22, 71, ' فقالوا : ما حاجتنا بعد إلى شهادة ؟ لأننا نحن سمعنا من فمه '),
(24231, 'Luke', 42, 23, 1, ' فقام كل جمهورهم وجاءوا به إلى بيلاطس '),
(24232, 'Luke', 42, 23, 2, ' وابتدأوا يشتكون عليه قائلين : إننا وجدنا هذا يفسد الأمة ، ويمنع أن تعطى جزية لقيصر ، قائلا : إنه هو مسيح ملك '),
(24233, 'Luke', 42, 23, 3, ' فسأله بيلاطس قائلا : أنت ملك اليهود ؟ فأجابه وقال : أنت تقول '),
(24234, 'Luke', 42, 23, 4, ' فقال بيلاطس لرؤساء الكهنة والجموع : إني لا أجد علة في هذا الإنسان '),
(24235, 'Luke', 42, 23, 5, ' فكانوا يشددون قائلين : إنه يهيج الشعب وهو يعلم في كل اليهودية مبتدئا من الجليل إلى هنا '),
(24236, 'Luke', 42, 23, 6, ' فلما سمع بيلاطس ذكر الجليل ، سأل : هل الرجل جليلي '),
(24237, 'Luke', 42, 23, 7, ' وحين علم أنه من سلطنة هيرودس ، أرسله إلى هيرودس ، إذ كان هو أيضا تلك الأيام في أورشليم '),
(24238, 'Luke', 42, 23, 8, ' وأما هيرودس فلما رأى يسوع فرح جدا ، لأنه كان يريد من زمان طويل أن يراه ، لسماعه عنه أشياء كثيرة ، وترجى أن يري آية تصنع منه '),
(24239, 'Luke', 42, 23, 9, ' وسأله بكلام كثير فلم يجبه بشيء '),
(24240, 'Luke', 42, 23, 10, ' ووقف رؤساء الكهنة والكتبة يشتكون عليه باشتداد '),
(24241, 'Luke', 42, 23, 11, ' فاحتقره هيرودس مع عسكره واستهزأ به ، وألبسه لباسا لامعا ، ورده إلى بيلاطس '),
(24242, 'Luke', 42, 23, 12, ' فصار بيلاطس وهيرودس صديقين مع بعضهما في ذلك اليوم ، لأنهما كانا من قبل في عداوة بينهما '),
(24243, 'Luke', 42, 23, 13, ' فدعا بيلاطس رؤساء الكهنة والعظماء والشعب '),
(24244, 'Luke', 42, 23, 14, ' وقال لهم : قد قدمتم إلي هذا الإنسان كمن يفسد الشعب . وها أنا قد فحصت قدامكم ولم أجد في هذا الإنسان علة مما تشتكون به عليه '),
(24245, 'Luke', 42, 23, 15, ' ولا هيرودس أيضا ، لأني أرسلتكم إليه . وها لا شيء يستحق الموت صنع منه '),
(24246, 'Luke', 42, 23, 16, ' فأنا أؤدبه وأطلقه '),
(24247, 'Luke', 42, 23, 17, ' وكان مضطرا أن يطلق لهم كل عيد واحدا '),
(24248, 'Luke', 42, 23, 18, ' فصرخوا بجملتهم قائلين : خذ هذا وأطلق لنا باراباس '),
(24249, 'Luke', 42, 23, 19, ' وذاك كان قد طرح في السجن لأجل فتنة حدثت في المدينة وقتل '),
(24250, 'Luke', 42, 23, 20, ' فناداهم أيضا بيلاطس وهو يريد أن يطلق يسوع '),
(24251, 'Luke', 42, 23, 21, ' فصرخوا قائلين : اصلبه اصلبه '),
(24252, 'Luke', 42, 23, 22, ' فقال لهم ثالثة : فأي شر عمل هذا ؟ إني لم أجد فيه علة للموت ، فأنا أؤدبه وأطلقه '),
(24253, 'Luke', 42, 23, 23, ' فكانوا يلجون بأصوات عظيمة طالبين أن يصلب . فقويت أصواتهم وأصوات رؤساء الكهنة '),
(24254, 'Luke', 42, 23, 24, ' فحكم بيلاطس أن تكون طلبتهم '),
(24255, 'Luke', 42, 23, 25, ' فأطلق لهم الذي طرح في السجن لأجل فتنة وقتل ، الذي طلبوه ، وأسلم يسوع لمشيئتهم '),
(24256, 'Luke', 42, 23, 26, ' ولما مضوا به أمسكوا سمعان ، رجلا قيروانيا كان آتيا من الحقل ، ووضعوا عليه الصليب ليحمله خلف يسوع '),
(24257, 'Luke', 42, 23, 27, ' وتبعه جمهور كثير من الشعب ، والنساء اللواتي كن يلطمن أيضا وينحن عليه '),
(24258, 'Luke', 42, 23, 28, ' فالتفت إليهن يسوع وقال : يا بنات أورشليم ، لا تبكين علي بل ابكين على أنفسكن وعلى أولادكن '),
(24259, 'Luke', 42, 23, 29, ' لأنه هوذا أيام تأتي يقولون فيها : طوبى للعواقر والبطون التي لم تلد والثدي التي لم ترضع '),
(24260, 'Luke', 42, 23, 30, ' حينئذ يبتدئون يقولون للجبال : اسقطي علينا وللآكام : غطينا '),
(24261, 'Luke', 42, 23, 31, ' لأنه إن كانوا بالعود الرطب يفعلون هذا ، فماذا يكون باليابس '),
(24262, 'Luke', 42, 23, 32, ' وجاءوا أيضا باثنين آخرين مذنبين ليقتلا معه '),
(24263, 'Luke', 42, 23, 33, ' ولما مضوا به إلى الموضع الذي يدعى جمجمة صلبوه هناك مع المذنبين ، واحدا عن يمينه والآخر عن يساره '),
(24264, 'Luke', 42, 23, 34, ' فقال يسوع : يا أبتاه ، اغفر لهم ، لأنهم لا يعلمون ماذا يفعلون . وإذ اقتسموا ثيابه اقترعوا عليها '),
(24265, 'Luke', 42, 23, 35, ' وكان الشعب واقفين ينظرون ، والرؤساء أيضا معهم يسخرون به قائلين : خلص آخرين ، فليخلص نفسه إن كان هو المسيح مختار الله '),
(24266, 'Luke', 42, 23, 36, ' والجند أيضا استهزأوا به وهم يأتون ويقدمون له خلا '),
(24267, 'Luke', 42, 23, 37, ' قائلين : إن كنت أنت ملك اليهود فخلص نفسك '),
(24268, 'Luke', 42, 23, 38, ' وكان عنوان مكتوب فوقه بأحرف يونانية ورومانية وعبرانية : هذا هو ملك اليهود '),
(24269, 'Luke', 42, 23, 39, ' وكان واحد من المذنبين المعلقين يجدف عليه قائلا : إن كنت أنت المسيح ، فخلص نفسك وإيانا '),
(24270, 'Luke', 42, 23, 40, ' فأجاب الآخر وانتهره قائلا : أولا أنت تخاف الله ، إذ أنت تحت هذا الحكم بعينه '),
(24271, 'Luke', 42, 23, 41, ' أما نحن فبعدل ، لأننا ننال استحقاق ما فعلنا ، وأما هذا فلم يفعل شيئا ليس في محله '),
(24272, 'Luke', 42, 23, 42, ' ثم قال ليسوع : اذكرني يا رب متى جئت في ملكوتك '),
(24273, 'Luke', 42, 23, 43, ' فقال له يسوع : الحق أقول لك : إنك اليوم تكون معي في الفردوس '),
(24274, 'Luke', 42, 23, 44, ' وكان نحو الساعة السادسة ، فكانت ظلمة على الأرض كلها إلى الساعة التاسعة '),
(24275, 'Luke', 42, 23, 45, ' وأظلمت الشمس ، وانشق حجاب الهيكل من وسطه '),
(24276, 'Luke', 42, 23, 46, ' ونادى يسوع بصوت عظيم وقال : يا أبتاه ، في يديك أستودع روحي . ولما قال هذا أسلم الروح '),
(24277, 'Luke', 42, 23, 47, ' فلما رأى قائد المئة ما كان ، مجد الله قائلا : بالحقيقة كان هذا الإنسان بارا '),
(24278, 'Luke', 42, 23, 48, ' وكل الجموع الذين كانوا مجتمعين لهذا المنظر ، لما أبصروا ما كان ، رجعوا وهم يقرعون صدورهم '),
(24279, 'Luke', 42, 23, 49, ' وكان جميع معارفه ، ونساء كن قد تبعنه من الجليل ، واقفين من بعيد ينظرون ذلك '),
(24280, 'Luke', 42, 23, 50, ' وإذا رجل اسمه يوسف ، وكان مشيرا ورجلا صالحا بارا '),
(24281, 'Luke', 42, 23, 51, ' هذا لم يكن موافقا لرأيهم وعملهم ، وهو من الرامة مدينة لليهود . وكان هو أيضا ينتظر ملكوت الله '),
(24282, 'Luke', 42, 23, 52, ' هذا تقدم إلى بيلاطس وطلب جسد يسوع '),
(24283, 'Luke', 42, 23, 53, ' وأنزله ، ولفه بكتان ، ووضعه في قبر منحوت حيث لم يكن أحد وضع قط '),
(24284, 'Luke', 42, 23, 54, ' وكان يوم الاستعداد والسبت يلوح '),
(24285, 'Luke', 42, 23, 55, ' وتبعته نساء كن قد أتين معه من الجليل ، ونظرن القبر وكيف وضع جسده '),
(24286, 'Luke', 42, 23, 56, ' فرجعن وأعددن حنوطا وأطيابا . وفي السبت استرحن حسب الوصية '),
(24287, 'Luke', 42, 24, 1, ' ثم في أول الأسبوع ، أول الفجر ، أتين إلى القبر حاملات الحنوط الذي أعددنه ، ومعهن أناس '),
(24288, 'Luke', 42, 24, 2, ' فوجدن الحجر مدحرجا عن القبر '),
(24289, 'Luke', 42, 24, 3, ' فدخلن ولم يجدن جسد الرب يسوع '),
(24290, 'Luke', 42, 24, 4, ' وفيما هن محتارات في ذلك ، إذا رجلان وقفا بهن بثياب براقة '),
(24291, 'Luke', 42, 24, 5, ' وإذ كن خائفات ومنكسات وجوههن إلى الأرض ، قالا لهن : لماذا تطلبن الحي بين الأموات '),
(24292, 'Luke', 42, 24, 6, ' ليس هو ههنا ، لكنه قام اذكرن كيف كلمكن وهو بعد في الجليل '),
(24293, 'Luke', 42, 24, 7, ' قائلا : إنه ينبغي أن يسلم ابن الإنسان في أيدي أناس خطاة ، ويصلب ، وفي اليوم الثالث يقوم '),
(24294, 'Luke', 42, 24, 8, ' فتذكرن كلامه '),
(24295, 'Luke', 42, 24, 9, ' ورجعن من القبر ، وأخبرن الأحد عشر وجميع الباقين بهذا كله '),
(24296, 'Luke', 42, 24, 10, ' وكانت مريم المجدلية ويونا ومريم أم يعقوب والباقيات معهن ، اللواتي قلن هذا للرسل '),
(24297, 'Luke', 42, 24, 11, ' فتراءى كلامهن لهم كالهذيان ولم يصدقوهن '),
(24298, 'Luke', 42, 24, 12, ' فقام بطرس وركض إلى القبر ، فانحنى ونظر الأكفان موضوعة وحدها ، فمضى متعجبا في نفسه مما كان '),
(24299, 'Luke', 42, 24, 13, ' وإذا اثنان منهم كانا منطلقين في ذلك اليوم إلى قرية بعيدة عن أورشليم ستين غلوة ، اسمها عمواس '),
(24300, 'Luke', 42, 24, 14, ' وكانا يتكلمان بعضهما مع بعض عن جميع هذه الحوادث '),
(24301, 'Luke', 42, 24, 15, ' وفيما هما يتكلمان ويتحاوران ، اقترب إليهما يسوع نفسه وكان يمشي معهما '),
(24302, 'Luke', 42, 24, 16, ' ولكن أمسكت أعينهما عن معرفته '),
(24303, 'Luke', 42, 24, 17, ' فقال لهما : ما هذا الكلام الذي تتطارحان به وأنتما ماشيان عابسين '),
(24304, 'Luke', 42, 24, 18, ' فأجاب أحدهما ، الذي اسمه كليوباس وقال له : هل أنت متغرب وحدك في أورشليم ولم تعلم الأمور التي حدثت فيها في هذه الأيام '),
(24305, 'Luke', 42, 24, 19, ' فقال لهما : وما هي ؟ فقالا : المختصة بيسوع الناصري ، الذي كان إنسانا نبيا مقتدرا في الفعل والقول أمام الله وجميع الشعب '),
(24306, 'Luke', 42, 24, 20, ' كيف أسلمه رؤساء الكهنة وحكامنا لقضاء الموت وصلبوه '),
(24307, 'Luke', 42, 24, 21, ' ونحن كنا نرجو أنه هو المزمع أن يفدي إسرائيل . ولكن ، مع هذا كله ، اليوم له ثلاثة أيام منذ حدث ذلك '),
(24308, 'Luke', 42, 24, 22, ' بل بعض النساء منا حيرننا إذ كن باكرا عند القبر '),
(24309, 'Luke', 42, 24, 23, ' ولما لم يجدن جسده أتين قائلات : إنهن رأين منظر ملائكة قالوا إنه حي '),
(24310, 'Luke', 42, 24, 24, ' ومضى قوم من الذين معنا إلى القبر ، فوجدوا هكذا كما قالت أيضا النساء ، وأما هو فلم يروه '),
(24311, 'Luke', 42, 24, 25, ' فقال لهما : أيها الغبيان والبطيئا القلوب في الإيمان بجميع ما تكلم به الأنبياء '),
(24312, 'Luke', 42, 24, 26, ' أما كان ينبغي أن المسيح يتألم بهذا ويدخل إلى مجده '),
(24313, 'Luke', 42, 24, 27, ' ثم ابتدأ من موسى ومن جميع الأنبياء يفسر لهما الأمور المختصة به في جميع الكتب '),
(24314, 'Luke', 42, 24, 28, ' ثم اقتربوا إلى القرية التي كانا منطلقين إليها ، وهو تظاهر كأنه منطلق إلى مكان أبعد '),
(24315, 'Luke', 42, 24, 29, ' فألزماه قائلين : امكث معنا ، لأنه نحو المساء وقد مال النهار . فدخل ليمكث معهما '),
(24316, 'Luke', 42, 24, 30, ' فلما اتكأ معهما ، أخذ خبزا وبارك وكسر وناولهما '),
(24317, 'Luke', 42, 24, 31, ' فانفتحت أعينهما وعرفاه ثم اختفى عنهما '),
(24318, 'Luke', 42, 24, 32, ' فقال بعضهما لبعض : ألم يكن قلبنا ملتهبا فينا إذ كان يكلمنا في الطريق ويوضح لنا الكتب '),
(24319, 'Luke', 42, 24, 33, ' فقاما في تلك الساعة ورجعا إلى أورشليم ، ووجدا الأحد عشر مجتمعين ، هم والذين معهم '),
(24320, 'Luke', 42, 24, 34, ' وهم يقولون : إن الرب قام بالحقيقة وظهر لسمعان '),
(24321, 'Luke', 42, 24, 35, ' وأما هما فكانا يخبران بما حدث في الطريق ، وكيف عرفاه عند كسر الخبز '),
(24322, 'Luke', 42, 24, 36, ' وفيما هم يتكلمون بهذا وقف يسوع نفسه في وسطهم ، وقال لهم : سلام لكم '),
(24323, 'Luke', 42, 24, 37, ' فجزعوا وخافوا ، وظنوا أنهم نظروا روحا '),
(24324, 'Luke', 42, 24, 38, ' فقال لهم : ما بالكم مضطربين ، ولماذا تخطر أفكار في قلوبكم '),
(24325, 'Luke', 42, 24, 39, ' انظروا يدي ورجلي : إني أنا هو جسوني وانظروا ، فإن الروح ليس له لحم وعظام كما ترون لي '),
(24326, 'Luke', 42, 24, 40, ' وحين قال هذا أراهم يديه ورجليه '),
(24327, 'Luke', 42, 24, 41, ' وبينما هم غير مصدقين من الفرح ، ومتعجبون ، قال لهم : أعندكم ههنا طعام '),
(24328, 'Luke', 42, 24, 42, ' فناولوه جزءا من سمك مشوي ، وشيئا من شهد عسل '),
(24329, 'Luke', 42, 24, 43, ' فأخذ وأكل قدامهم '),
(24330, 'Luke', 42, 24, 44, ' وقال لهم : هذا هو الكلام الذي كلمتكم به وأنا بعد معكم : أنه لا بد أن يتم جميع ما هو مكتوب عني في ناموس موسى والأنبياء والمزامير '),
(24331, 'Luke', 42, 24, 45, ' حينئذ فتح ذهنهم ليفهموا الكتب '),
(24332, 'Luke', 42, 24, 46, ' وقال لهم : هكذا هو مكتوب ، وهكذا كان ينبغي أن المسيح يتألم ويقوم من الأموات في اليوم الثالث '),
(24333, 'Luke', 42, 24, 47, ' وأن يكرز باسمه بالتوبة ومغفرة الخطايا لجميع الأمم ، مبتدأ من أورشليم '),
(24334, 'Luke', 42, 24, 48, ' وأنتم شهود لذلك '),
(24335, 'Luke', 42, 24, 49, ' وها أنا أرسل إليكم موعد أبي . فأقيموا في مدينة أورشليم إلى أن تلبسوا قوة من الأعالي '),
(24336, 'Luke', 42, 24, 50, ' وأخرجهم خارجا إلى بيت عنيا ، ورفع يديه وباركهم '),
(24337, 'Luke', 42, 24, 51, ' وفيما هو يباركهم ، انفرد عنهم وأصعد إلى السماء '),
(24338, 'Luke', 42, 24, 52, ' فسجدوا له ورجعوا إلى أورشليم بفرح عظيم '),
(24339, 'Luke', 42, 24, 53, ' وكانوا كل حين في الهيكل يسبحون ويباركون الله . آمين '),
(24340, 'Luke', 42, 1, 1, ' إذ كان كثيرون قد أخذوا بتأليف قصة في الأمور المتيقنة عندنا '),
(24341, 'Luke', 42, 1, 2, ' كما سلمها إلينا الذين كانوا منذ البدء معاينين وخداما للكلمة '),
(24342, 'Luke', 42, 1, 3, ' رأيت أنا أيضا إذ قد تتبعت كل شيء من الأول بتدقيق ، أن أكتب على التوالي إليك أيها العزيز ثاوفيلس '),
(24343, 'Luke', 42, 1, 4, ' لتعرف صحة الكلام الذي علمت به '),
(24344, 'Luke', 42, 1, 5, ' كان في أيام هيرودس ملك اليهودية كاهن اسمه زكريا من فرقة أبيا ، وامرأته من بنات هارون واسمها أليصابات '),
(24345, 'Luke', 42, 1, 6, ' وكانا كلاهما بارين أمام الله ، سالكين في جميع وصايا الرب وأحكامه بلا لوم '),
(24346, 'Luke', 42, 1, 7, ' ولم يكن لهما ولد ، إذ كانت أليصابات عاقرا . وكانا كلاهما متقدمين في أيامهما '),
(24347, 'Luke', 42, 1, 8, ' فبينما هو يكهن في نوبة فرقته أمام الله '),
(24348, 'Luke', 42, 1, 9, ' حسب عادة الكهنوت ، أصابته القرعة أن يدخل إلى هيكل الرب ويبخر '),
(24349, 'Luke', 42, 1, 10, ' وكان كل جمهور الشعب يصلون خارجا وقت البخور '),
(24350, 'Luke', 42, 1, 11, ' فظهر له ملاك الرب واقفا عن يمين مذبح البخور '),
(24351, 'Luke', 42, 1, 12, ' فلما رآه زكريا اضطرب ووقع عليه خوف '),
(24352, 'Luke', 42, 1, 13, ' فقال له الملاك : لا تخف يا زكريا ، لأن طلبتك قد سمعت ، وامرأتك أليصابات ستلد لك ابنا وتسميه يوحنا '),
(24353, 'Luke', 42, 1, 14, ' ويكون لك فرح وابتهاج ، وكثيرون سيفرحون بولادته '),
(24354, 'Luke', 42, 1, 15, ' لأنه يكون عظيما أمام الرب ، وخمرا ومسكرا لا يشرب ، ومن بطن أمه يمتلئ من الروح القدس '),
(24355, 'Luke', 42, 1, 16, ' ويرد كثيرين من بني إسرائيل إلى الرب إلههم '),
(24356, 'Luke', 42, 1, 17, ' ويتقدم أمامه بروح إيليا وقوته ، ليرد قلوب الآباء إلى الأبناء ، والعصاة إلى فكر الأبرار ، لكي يهيئ للرب شعبا مستعدا '),
(24357, 'Luke', 42, 1, 18, ' فقال زكريا للملاك : كيف أعلم هذا ، لأني أنا شيخ وامرأتي متقدمة في أيامها '),
(24358, 'Luke', 42, 1, 19, ' فأجاب الملاك وقال له : أنا جبرائيل الواقف قدام الله ، وأرسلت لأكلمك وأبشرك بهذا '),
(24359, 'Luke', 42, 1, 20, ' وها أنت تكون صامتا ولا تقدر أن تتكلم ، إلى اليوم الذي يكون فيه هذا ، لأنك لم تصدق كلامي الذي سيتم في وقته '),
(24360, 'Luke', 42, 1, 21, ' وكان الشعب منتظرين زكريا ومتعجبين من إبطائه في الهيكل '),
(24361, 'Luke', 42, 1, 22, ' فلما خرج لم يستطع أن يكلمهم ، ففهموا أنه قد رأى رؤيا في الهيكل . فكان يومئ إليهم وبقي صامتا '),
(24362, 'Luke', 42, 1, 23, ' ولما كملت أيام خدمته مضى إلى بيته '),
(24363, 'Luke', 42, 1, 24, ' وبعد تلك الأيام حبلت أليصابات امرأته ، وأخفت نفسها خمسة أشهر قائلة '),
(24364, 'Luke', 42, 1, 25, ' هكذا قد فعل بي الرب في الأيام التي فيها نظر إلي ، لينزع عاري بين الناس '),
(24365, 'Luke', 42, 1, 26, ' وفي الشهر السادس أرسل جبرائيل الملاك من الله إلى مدينة من الجليل اسمها ناصرة '),
(24366, 'Luke', 42, 1, 27, ' إلى عذراء مخطوبة لرجل من بيت داود اسمه يوسف . واسم العذراء مريم '),
(24367, 'Luke', 42, 1, 28, ' فدخل إليها الملاك وقال : سلام لك أيتها المنعم عليها الرب معك . مباركة أنت في النساء '),
(24368, 'Luke', 42, 1, 29, ' فلما رأته اضطربت من كلامه ، وفكرت : ما عسى أن تكون هذه التحية '),
(24369, 'Luke', 42, 1, 30, ' فقال لها الملاك : لا تخافي يا مريم ، لأنك قد وجدت نعمة عند الله '),
(24370, 'Luke', 42, 1, 31, ' وها أنت ستحبلين وتلدين ابنا وتسمينه يسوع '),
(24371, 'Luke', 42, 1, 32, ' هذا يكون عظيما ، وابن العلي يدعى ، ويعطيه الرب الإله كرسي داود أبيه '),
(24372, 'Luke', 42, 1, 33, ' ويملك على بيت يعقوب إلى الأبد ، ولا يكون لملكه نهاية '),
(24373, 'Luke', 42, 1, 34, ' فقالت مريم للملاك : كيف يكون هذا وأنا لست أعرف رجلا '),
(24374, 'Luke', 42, 1, 35, ' فأجاب الملاك وقال لها : الروح القدس يحل عليك ، وقوة العلي تظللك ، فلذلك أيضا القدوس المولود منك يدعى ابن الله '),
(24375, 'Luke', 42, 1, 36, ' وهوذا أليصابات نسيبتك هي أيضا حبلى بابن في شيخوختها ، وهذا هو الشهر السادس لتلك المدعوة عاقرا '),
(24376, 'Luke', 42, 1, 37, ' لأنه ليس شيء غير ممكن لدى الله '),
(24377, 'Luke', 42, 1, 38, ' فقالت مريم : هوذا أنا أمة الرب . ليكن لي كقولك فمضى من عندها الملاك '),
(24378, 'Luke', 42, 1, 39, ' فقامت مريم في تلك الأيام وذهبت بسرعة إلى الجبال إلى مدينة يهوذا '),
(24379, 'Luke', 42, 1, 40, ' ودخلت بيت زكريا وسلمت على أليصابات '),
(24380, 'Luke', 42, 1, 41, ' فلما سمعت أليصابات سلام مريم ارتكض الجنين في بطنها ، وامتلأت أليصابات من الروح القدس '),
(24381, 'Luke', 42, 1, 42, ' وصرخت بصوت عظيم وقالت : مباركة أنت في النساء ومباركة هي ثمرة بطنك '),
(24382, 'Luke', 42, 1, 43, ' فمن أين لي هذا أن تأتي أم ربي إلي '),
(24383, 'Luke', 42, 1, 44, ' فهوذا حين صار صوت سلامك في أذني ارتكض الجنين بابتهاج في بطني '),
(24384, 'Luke', 42, 1, 45, ' فطوبى للتي آمنت أن يتم ما قيل لها من قبل الرب '),
(24385, 'Luke', 42, 1, 46, ' فقالت مريم : تعظم نفسي الرب '),
(24386, 'Luke', 42, 1, 47, ' وتبتهج روحي بالله مخلصي '),
(24387, 'Luke', 42, 1, 48, ' لأنه نظر إلى اتضاع أمته . فهوذا منذ الآن جميع الأجيال تطوبني '),
(24388, 'Luke', 42, 1, 49, ' لأن القدير صنع بي عظائم ، واسمه قدوس '),
(24389, 'Luke', 42, 1, 50, ' ورحمته إلى جيل الأجيال للذين يتقونه '),
(24390, 'Luke', 42, 1, 51, ' صنع قوة بذراعه . شتت المستكبرين بفكر قلوبهم '),
(24391, 'Luke', 42, 1, 52, ' أنزل الأعزاء عن الكراسي ورفع المتضعين '),
(24392, 'Luke', 42, 1, 53, ' أشبع الجياع خيرات وصرف الأغنياء فارغين '),
(24393, 'Luke', 42, 1, 54, ' عضد إسرائيل فتاه ليذكر رحمة '),
(24394, 'Luke', 42, 1, 55, ' كما كلم آباءنا لإبراهيم ونسله إلى الأبد '),
(24395, 'Luke', 42, 1, 56, ' فمكثت مريم عندها نحو ثلاثة أشهر ، ثم رجعت إلى بيتها '),
(24396, 'Luke', 42, 1, 57, ' وأما أليصابات فتم زمانها لتلد ، فولدت ابنا '),
(24397, 'Luke', 42, 1, 58, ' وسمع جيرانها وأقرباؤها أن الرب عظم رحمته لها ، ففرحوا معها '),
(24398, 'Luke', 42, 1, 59, ' وفي اليوم الثامن جاءوا ليختنوا الصبي ، وسموه باسم أبيه زكريا '),
(24399, 'Luke', 42, 1, 60, ' فأجابت أمه وقالت : لا بل يسمى يوحنا '),
(24400, 'Luke', 42, 1, 61, ' فقالوا لها : ليس أحد في عشيرتك تسمى بهذا الاسم '),
(24401, 'Luke', 42, 1, 62, ' ثم أومأوا إلى أبيه ، ماذا يريد أن يسمى '),
(24402, 'Luke', 42, 1, 63, ' فطلب لوحا وكتب قائلا : اسمه يوحنا . فتعجب الجميع '),
(24403, 'Luke', 42, 1, 64, ' وفي الحال انفتح فمه ولسانه وتكلم وبارك الله '),
(24404, 'Luke', 42, 1, 65, ' فوقع خوف على كل جيرانهم . وتحدث بهذه الأمور جميعها في كل جبال اليهودية '),
(24405, 'Luke', 42, 1, 66, ' فأودعها جميع السامعين في قلوبهم قائلين : أترى ماذا يكون هذا الصبي ؟  . وكانت يد الرب معه '),
(24406, 'Luke', 42, 1, 67, ' وامتلأ زكريا أبوه من الروح القدس ، وتنبأ قائلا '),
(24407, 'Luke', 42, 1, 68, ' مبارك الرب إله إسرائيل لأنه افتقد وصنع فداء لشعبه '),
(24408, 'Luke', 42, 4, 29, ' فقاموا وأخرجوه خارج المدينة ، وجاءوا به إلى حافة الجبل الذي كانت مدينتهم مبنية عليه حتى يطرحوه إلى أسفل '),
(24409, 'Luke', 42, 4, 30, ' أما هو فجاز في وسطهم ومضى '),
(24410, 'Luke', 42, 4, 31, ' وانحدر إلى كفرناحوم ، مدينة من الجليل ، وكان يعلمهم في السبوت '),
(24411, 'Luke', 42, 4, 32, ' فبهتوا من تعليمه ، لأن كلامه كان بسلطان '),
(24412, 'Luke', 42, 4, 33, ' وكان في المجمع رجل به روح شيطان نجس ، فصرخ بصوت عظيم '),
(24413, 'Luke', 42, 4, 34, ' قائلا : آه ما لنا ولك يا يسوع الناصري ؟ أتيت لتهلكنا أنا أعرفك من أنت : قدوس الله '),
(24414, 'Luke', 42, 4, 35, ' فانتهره يسوع قائلا : اخرس واخرج منه . فصرعه الشيطان في الوسط وخرج منه ولم يضره شيئا '),
(24415, 'Luke', 42, 4, 36, ' فوقعت دهشة على الجميع ، وكانوا يخاطبون بعضهم بعضا قائلين : ما هذه الكلمة ؟ لأنه بسلطان وقوة يأمر الأرواح النجسة فتخرج '),
(24416, 'Luke', 42, 4, 37, ' وخرج صيت عنه إلى كل موضع في الكورة المحيطة '),
(24417, 'Luke', 42, 4, 38, ' ولما قام من المجمع دخل بيت سمعان . وكانت حماة سمعان قد أخذتها حمى شديدة . فسألوه من أجلها '),
(24418, 'Luke', 42, 4, 39, ' فوقف فوقها وانتهر الحمى فتركتها وفي الحال قامت وصارت تخدمهم '),
(24419, 'Luke', 42, 4, 40, ' وعند غروب الشمس ، جميع الذين كان عندهم سقماء بأمراض مختلفة قدموهم إليه ، فوضع يديه على كل واحد منهم وشفاهم '),
(24420, 'Luke', 42, 4, 41, ' وكانت شياطين أيضا تخرج من كثيرين وهي تصرخ وتقول : أنت المسيح ابن الله فانتهرهم ولم يدعهم يتكلمون ، لأنهم عرفوه أنه المسيح '),
(24421, 'Luke', 42, 4, 42, ' ولما صار النهار خرج وذهب إلى موضع خلاء ، وكان الجموع يفتشون عليه . فجاءوا إليه وأمسكوه لئلا يذهب عنهم '),
(24422, 'Luke', 42, 4, 43, ' فقال لهم : إنه ينبغي لي أن أبشر المدن الأخر أيضا بملكوت الله ، لأني لهذا قد أرسلت '),
(24423, 'Luke', 42, 4, 44, ' فكان يكرز في مجامع الجليل '),
(24424, 'Luke', 42, 5, 1, ' وإذ كان الجمع يزدحم عليه ليسمع كلمة الله ، كان واقفا عند بحيرة جنيسارت '),
(24425, 'Luke', 42, 5, 2, ' فرأى سفينتين واقفتين عند البحيرة ، والصيادون قد خرجوا منهما وغسلوا الشباك '),
(24426, 'Luke', 42, 5, 3, ' فدخل إحدى السفينتين التي كانت لسمعان ، وسأله أن يبعد قليلا عن البر . ثم جلس وصار يعلم الجموع من السفينة '),
(24427, 'Luke', 42, 5, 4, ' ولما فرغ من الكلام قال لسمعان : ابعد إلى العمق وألقوا شباككم للصيد '),
(24428, 'Luke', 42, 5, 5, ' فأجاب سمعان وقال له : يا معلم ، قد تعبنا الليل كله ولم نأخذ شيئا . ولكن على كلمتك ألقي الشبكة '),
(24429, 'Luke', 42, 5, 6, ' ولما فعلوا ذلك أمسكوا سمكا كثيرا جدا ، فصارت شبكتهم تتخرق '),
(24430, 'Luke', 42, 5, 7, ' فأشاروا إلى شركائهم الذين في السفينة الأخرى أن يأتوا ويساعدوهم . فأتوا وملأوا السفينتين حتى أخذتا في الغرق '),
(24431, 'Luke', 42, 5, 8, ' فلما رأى سمعان بطرس ذلك خر عند ركبتي يسوع قائلا : اخرج من سفينتي يا رب ، لأني رجل خاطئ '),
(24432, 'Luke', 42, 5, 9, ' إذ اعترته وجميع الذين معه دهشة على صيد السمك الذي أخذوه '),
(24433, 'Luke', 42, 5, 10, ' وكذلك أيضا يعقوب ويوحنا ابنا زبدي اللذان كانا شريكي سمعان . فقال يسوع لسمعان : لا تخف من الآن تكون تصطاد الناس '),
(24434, 'Luke', 42, 5, 11, ' ولما جاءوا بالسفينتين إلى البر تركوا كل شيء وتبعوه '),
(24435, 'Luke', 42, 5, 12, ' وكان في إحدى المدن ، فإذا رجل مملوء برصا . فلما رأى يسوع خر على وجهه وطلب إليه قائلا : يا سيد ، إن أردت تقدر أن تطهرني '),
(24436, 'Luke', 42, 5, 13, ' فمد يده ولمسه قائلا : أريد ، فاطهر . وللوقت ذهب عنه البرص '),
(24437, 'Luke', 42, 5, 14, ' فأوصاه أن لا يقول لأحد . بل امض وأر نفسك للكاهن ، وقدم عن تطهيرك كما أمر موسى شهادة لهم '),
(24438, 'Luke', 42, 5, 15, ' فذاع الخبر عنه أكثر . فاجتمع جموع كثيرة لكي يسمعوا ويشفوا به من أمراضهم '),
(24439, 'Luke', 42, 5, 16, ' وأما هو فكان يعتزل في البراري ويصلي '),
(24440, 'Luke', 42, 5, 17, ' وفي أحد الأيام كان يعلم ، وكان فريسيون ومعلمون للناموس جالسين وهم قد أتوا من كل قرية من الجليل واليهودية وأورشليم . وكانت قوة الرب لشفائهم '),
(24441, 'Luke', 42, 5, 18, ' وإذا برجال يحملون على فراش إنسانا مفلوجا ، وكانوا يطلبون أن يدخلوا به ويضعوه أمامه '),
(24442, 'Luke', 42, 5, 19, ' ولما لم يجدوا من أين يدخلون به لسبب الجمع ، صعدوا على السطح ودلوه مع الفراش من بين الأجر إلى الوسط قدام يسوع '),
(24443, 'Luke', 42, 5, 20, ' فلما رأى إيمانهم قال له : أيها الإنسان ، مغفورة لك خطاياك '),
(24444, 'Luke', 42, 5, 21, ' فابتدأ الكتبة والفريسيون يفكرون قائلين : من هذا الذي يتكلم بتجاديف ؟ من يقدر أن يغفر خطايا إلا الله وحده '),
(24445, 'Luke', 42, 5, 22, ' فشعر يسوع بأفكارهم ، وأجاب وقال لهم : ماذا تفكرون في قلوبكم '),
(24446, 'Luke', 42, 5, 23, ' أيما أيسر : أن يقال : مغفورة لك خطاياك ، أم أن يقال : قم وامش '),
(24447, 'Luke', 42, 5, 24, ' ولكن لكي تعلموا أن لابن الإنسان سلطانا على الأرض أن يغفر الخطايا ، قال للمفلوج : لك أقول : قم واحمل فراشك واذهب إلى بيتك '),
(24448, 'Luke', 42, 5, 25, ' ففي الحال قام أمامهم ، وحمل ما كان مضطجعا عليه ، ومضى إلى بيته وهو يمجد الله '),
(24449, 'Luke', 42, 5, 26, ' فأخذت الجميع حيرة ومجدوا الله ، وامتلأوا خوفا قائلين : إننا قد رأينا اليوم عجائب '),
(24450, 'Luke', 42, 5, 27, ' وبعد هذا خرج فنظر عشارا اسمه لاوي جالسا عند مكان الجباية ، فقال له : اتبعني '),
(24451, 'Luke', 42, 5, 28, ' فترك كل شيء وقام وتبعه '),
(24452, 'Luke', 42, 5, 29, ' وصنع له لاوي ضيافة كبيرة في بيته . والذين كانوا متكئين معهم كانوا جمعا كثيرا من عشارين وآخرين '),
(24453, 'Luke', 42, 5, 30, ' فتذمر كتبتهم والفريسيون على تلاميذه قائلين : لماذا تأكلون وتشربون مع عشارين وخطاة '),
(24454, 'Luke', 42, 5, 31, ' فأجاب يسوع وقال لهم : لا يحتاج الأصحاء إلى طبيب ، بل المرضى '),
(24455, 'Luke', 42, 5, 32, ' لم آت لأدعو أبرارا بل خطاة إلى التوبة '),
(24456, 'Luke', 42, 5, 33, ' وقالوا له : لماذا يصوم تلاميذ يوحنا كثيرا ويقدمون طلبات ، وكذلك تلاميذ الفريسيين أيضا ، وأما تلاميذك فيأكلون ويشربون '),
(24457, 'Luke', 42, 5, 34, ' فقال لهم : أتقدرون أن تجعلوا بني العرس يصومون ما دام العريس معهم '),
(24458, 'Luke', 42, 5, 35, ' ولكن ستأتي أيام حين يرفع العريس عنهم ، فحينئذ يصومون في تلك الأيام '),
(24459, 'Luke', 42, 5, 36, ' وقال لهم أيضا مثلا : ليس أحد يضع رقعة من ثوب جديد على ثوب عتيق ، وإلا فالجديد يشقه ، والعتيق لا توافقه الرقعة التي من الجديد '),
(24460, 'Luke', 42, 5, 37, ' وليس أحد يجعل خمرا جديدة في زقاق عتيقة لئلا تشق الخمر الجديدة الزقاق ، فهي تهرق والزقاق تتلف '),
(24461, 'Luke', 42, 5, 38, ' بل يجعلون خمرا جديدة في زقاق جديدة ، فتحفظ جميعا '),
(24462, 'Luke', 42, 5, 39, ' وليس أحد إذا شرب العتيق يريد للوقت الجديد ، لأنه يقول : العتيق أطيب '),
(24463, 'Luke', 42, 6, 1, ' وفي السبت الثاني بعد الأول اجتاز بين الزروع . وكان تلاميذه يقطفون السنابل ويأكلون وهم يفركونها بأيديهم '),
(24464, 'Luke', 42, 6, 2, ' فقال لهم قوم من الفريسيين : لماذا تفعلون ما لا يحل فعله في السبوت '),
(24465, 'Luke', 42, 6, 3, ' فأجاب يسوع وقال لهم : أما قرأتم ولا هذا الذي فعله داود ، حين جاع هو والذين كانوا معه '),
(24466, 'Luke', 42, 6, 4, ' كيف دخل بيت الله وأخذ خبز التقدمة وأكل ، وأعطى الذين معه أيضا ، الذي لا يحل أكله إلا للكهنة فقط '),
(24467, 'Luke', 42, 6, 5, ' وقال لهم : إن ابن الإنسان هو رب السبت أيضا '),
(24468, 'Luke', 42, 6, 6, ' وفي سبت آخر دخل المجمع وصار يعلم . وكان هناك رجل يده اليمنى يابسة '),
(24469, 'Luke', 42, 6, 7, ' وكان الكتبة والفريسيون يراقبونه هل يشفي في السبت ، لكي يجدوا عليه شكاية '),
(24470, 'Luke', 42, 6, 8, ' أما هو فعلم أفكارهم ، وقال للرجل الذي يده يابسة : قم وقف في الوسط . فقام ووقف '),
(24471, 'Luke', 42, 6, 9, ' ثم قال لهم يسوع : أسألكم شيئا : هل يحل في السبت فعل الخير أو فعل الشر ؟ تخليص نفس أو إهلاكها '),
(24472, 'Luke', 42, 6, 10, ' ثم نظر حوله إلى جميعهم وقال للرجل : مد يدك . ففعل هكذا . فعادت يده صحيحة كالأخرى '),
(24473, 'Luke', 42, 6, 11, ' فامتلأوا حمقا وصاروا يتكالمون فيما بينهم ماذا يفعلون بيسوع '),
(24474, 'Luke', 42, 6, 12, ' وفي تلك الأيام خرج إلى الجبل ليصلي . وقضى الليل كله في الصلاة لله '),
(24475, 'Luke', 42, 6, 13, ' ولما كان النهار دعا تلاميذه ، واختار منهم اثني عشر ، الذين سماهم أيضا رسلا '),
(24476, 'Luke', 42, 6, 14, ' سمعان الذي سماه أيضا بطرس وأندراوس أخاه . يعقوب ويوحنا . فيلبس وبرثولماوس '),
(24477, 'Luke', 42, 6, 15, ' متى وتوما . يعقوب بن حلفى وسمعان الذي يدعى الغيور '),
(24478, 'Luke', 42, 6, 16, ' يهوذا أخا يعقوب ، ويهوذا الإسخريوطي الذي صار مسلما أيضا '),
(24479, 'Luke', 42, 6, 17, ' ونزل معهم ووقف في موضع سهل ، هو وجمع من تلاميذه ، وجمهور كثير من الشعب ، من جميع اليهودية وأورشليم وساحل صور وصيداء ، الذين جاءوا ليسمعوه ويشفوا من أمراضهم '),
(24480, 'Luke', 42, 6, 18, ' والمعذبون من أرواح نجسة . وكانوا يبرأون '),
(24481, 'Luke', 42, 6, 19, ' وكل الجمع طلبوا أن يلمسوه ، لأن قوة كانت تخرج منه وتشفي الجميع '),
(24482, 'Luke', 42, 6, 20, ' ورفع عينيه إلى تلاميذه وقال : طوباكم أيها المساكين ، لأن لكم ملكوت الله '),
(24483, 'Luke', 42, 6, 21, ' طوباكم أيها الجياع الآن ، لأنكم تشبعون . طوباكم أيها الباكون الآن ، لأنكم ستضحكون '),
(24484, 'Luke', 42, 6, 22, ' طوباكم إذا أبغضكم الناس ، وإذا أفرزوكم وعيروكم ، وأخرجوا اسمكم كشرير من أجل ابن الإنسان '),
(24485, 'Luke', 42, 6, 23, ' افرحوا في ذلك اليوم وتهللوا ، فهوذا أجركم عظيم في السماء . لأن آباءهم هكذا كانوا يفعلون بالأنبياء '),
(24486, 'Luke', 42, 6, 24, ' ولكن ويل لكم أيها الأغنياء ، لأنكم قد نلتم عزاءكم '),
(24487, 'Luke', 42, 6, 25, ' ويل لكم أيها الشباعى ، لأنكم ستجوعون . ويل لكم أيها الضاحكون الآن ، لأنكم ستحزنون وتبكون '),
(24488, 'Luke', 42, 6, 26, ' ويل لكم إذا قال فيكم جميع الناس حسنا . لأنه هكذا كان آباؤهم يفعلون بالأنبياء الكذبة '),
(24489, 'Luke', 42, 6, 27, ' لكني أقول لكم أيها السامعون : أحبوا أعداءكم ، أحسنوا إلى مبغضيكم '),
(24490, 'Luke', 42, 6, 28, ' باركوا لاعنيكم ، وصلوا لأجل الذين يسيئون إليكم '),
(24491, 'Luke', 42, 6, 29, ' من ضربك على خدك فاعرض له الآخر أيضا ، ومن أخذ رداءك فلا تمنعه ثوبك أيضا '),
(24492, 'Luke', 42, 6, 30, ' وكل من سألك فأعطه ، ومن أخذ الذي لك فلا تطالبه '),
(24493, 'Luke', 42, 6, 31, ' وكما تريدون أن يفعل الناس بكم افعلوا أنتم أيضا بهم هكذا '),
(24494, 'Luke', 42, 6, 32, ' وإن أحببتم الذين يحبونكم ، فأي فضل لكم ؟ فإن الخطاة أيضا يحبون الذين يحبونهم '),
(24495, 'Luke', 42, 6, 33, ' وإذا أحسنتم إلى الذين يحسنون إليكم ، فأي فضل لكم ؟ فإن الخطاة أيضا يفعلون هكذا '),
(24496, 'Luke', 42, 6, 34, ' وإن أقرضتم الذين ترجون أن تستردوا منهم ، فأي فضل لكم ؟ فإن الخطاة أيضا يقرضون الخطاة لكي يستردوا منهم المثل '),
(24497, 'Luke', 42, 6, 35, ' بل أحبوا أعداءكم ، وأحسنوا وأقرضوا وأنتم لا ترجون شيئا ، فيكون أجركم عظيما وتكونوا بني العلي ، فإنه منعم على غير الشاكرين والأشرار '),
(24498, 'Luke', 42, 6, 36, ' فكونوا رحماء كما أن أباكم أيضا رحيم '),
(24499, 'Luke', 42, 6, 37, ' ولا تدينوا فلا تدانوا . لا تقضوا على أحد فلا يقضى عليكم . اغفروا يغفر لكم '),
(24500, 'Luke', 42, 6, 38, ' أعطوا تعطوا ، كيلا جيدا ملبدا مهزوزا فائضا يعطون في أحضانكم . لأنه بنفس الكيل الذي به تكيلون يكال لكم '),
(24501, 'Luke', 42, 6, 39, ' وضرب لهم مثلا : هل يقدر أعمى أن يقود أعمى ؟ أما يسقط الاثنان في حفرة '),
(24502, 'Luke', 42, 6, 40, ' ليس التلميذ أفضل من معلمه ، بل كل من صار كاملا يكون مثل معلمه '),
(24503, 'Luke', 42, 6, 41, ' لماذا تنظر القذى الذي في عين أخيك ، وأما الخشبة التي في عينك فلا تفطن لها '),
(24504, 'Luke', 42, 6, 42, ' أو كيف تقدر أن تقول لأخيك : يا أخي ، دعني أخرج القذى الذي في عينك ، وأنت لا تنظر الخشبة التي في عينك ؟ يا مرائي أخرج أولا الخشبة من عينك ، وحينئذ تبصر جيدا أن تخرج القذى الذي في عين أخيك '),
(24505, 'Luke', 42, 6, 43, ' لأنه ما من شجرة جيدة تثمر ثمرا رديا ، ولا شجرة ردية تثمر ثمرا جيدا '),
(24506, 'Luke', 42, 6, 44, ' لأن كل شجرة تعرف من ثمرها . فإنهم لا يجتنون من الشوك تينا ، ولا يقطفون من العليق عنبا '),
(24507, 'Luke', 42, 6, 45, ' الإنسان الصالح من كنز قلبه الصالح يخرج الصلاح ، والإنسان الشرير من كنز قلبه الشرير يخرج الشر . فإنه من فضلة القلب يتكلم فمه '),
(24508, 'Luke', 42, 6, 46, ' ولماذا تدعونني : يا رب ، يا رب ، وأنتم لا تفعلون ما أقوله '),
(24509, 'Luke', 42, 6, 47, ' كل من يأتي إلي ويسمع كلامي ويعمل به أريكم من يشبه '),
(24510, 'Luke', 42, 6, 48, ' يشبه إنسانا بنى بيتا ، وحفر وعمق ووضع الأساس على الصخر . فلما حدث سيل صدم النهر ذلك البيت ، فلم يقدر أن يزعزعه ، لأنه كان مؤسسا على الصخر '),
(24511, 'Luke', 42, 6, 49, ' وأما الذي يسمع ولا يعمل ، فيشبه إنسانا بنى بيته على الأرض من دون أساس ، فصدمه النهر فسقط حالا ، وكان خراب ذلك البيت عظيما '),
(24512, 'Luke', 42, 7, 1, ' ولما أكمل أقواله كلها في مسامع الشعب دخل كفرناحوم '),
(24513, 'Luke', 42, 7, 2, ' وكان عبد لقائد مئة ، مريضا مشرفا على الموت ، وكان عزيزا عنده '),
(24514, 'Malachi', 39, 2, 12, ' يقطع الرب الرجل الذي يفعل هذا ، الساهر والمجيب من خيام يعقوب ، ومن يقرب تقدمة لرب الجنود '),
(24515, 'Malachi', 39, 2, 13, ' وقد فعلتم هذا ثانية مغطين مذبح الرب بالدموع ، بالبكاء والصراخ ، فلا تراعى التقدمة بعد ، ولا يقبل المرضي من يدكم '),
(24516, 'Malachi', 39, 2, 14, ' فقلتم : لماذا ؟ من أجل أن الرب هو الشاهد بينك وبين امرأة شبابك التي أنت غدرت بها ، وهي قرينتك وامرأة عهدك '),
(24517, 'Malachi', 39, 2, 15, ' أفلم يفعل واحد وله بقية الروح ؟ ولماذا الواحد ؟ طالبا زرع الله . فاحذروا لروحكم ولا يغدر أحد بامرأة شبابه '),
(24518, 'Malachi', 39, 2, 16, ' لأنه يكره الطلاق ، قال الرب إله إسرائيل ، وأن يغطي أحد الظلم بثوبه ، قال رب الجنود . فاحذروا لروحكم لئلا تغدروا '),
(24519, 'Malachi', 39, 2, 17, ' لقد أتعبتم الرب بكلامكم . وقلتم : بم أتعبناه ؟  . بقولكم : كل من يفعل الشر فهو صالح في عيني الرب ، وهو يسر بهم . أو : أين إله العدل '),
(24520, 'Malachi', 39, 3, 1, ' هأنذا أرسل ملاكي فيهيئ الطريق أمامي . ويأتي بغتة إلى هيكله السيد الذي تطلبونه ، وملاك العهد الذي تسرون به . هوذا يأتي ، قال رب الجنود '),
(24521, 'Malachi', 39, 3, 2, ' ومن يحتمل يوم مجيئه ؟ ومن يثبت عند ظهوره ؟ لأنه مثل نار الممحص ، ومثل أشنان القصار '),
(24522, 'Malachi', 39, 3, 3, ' فيجلس ممحصا ومنقيا للفضة . فينقي بني لاوي ويصفيهم كالذهب والفضة ، ليكونوا مقربين للرب ، تقدمة بالبر '),
(24523, 'Malachi', 39, 3, 4, ' فتكون تقدمة يهوذا وأورشليم مرضية للرب كما في أيام القدم وكما في السنين القديمة '),
(24524, 'Malachi', 39, 3, 5, ' وأقترب إليكم للحكم ، وأكون شاهدا سريعا على السحرة وعلى الفاسقين وعلى الحالفين زورا وعلى السالبين أجرة الأجير : الأرملة واليتيم ، ومن يصد الغريب ولا يخشاني ، قال رب الجنود '),
(24525, 'Malachi', 39, 3, 6, ' لأني أنا الرب لا أتغير فأنتم يا بني يعقوب لم تفنوا '),
(24526, 'Malachi', 39, 3, 7, ' من أيام آبائكم حدتم عن فرائضي ولم تحفظوها . ارجعوا إلي أرجع إليكم ، قال رب الجنود . فقلتم : بماذا نرجع '),
(24527, 'Malachi', 39, 3, 8, ' أيسلب الإنسان الله ؟ فإنكم سلبتموني . فقلتم : بم سلبناك ؟ في العشور والتقدمة '),
(24528, 'Malachi', 39, 3, 9, ' قد لعنتم لعنا وإياي أنتم سالبون ، هذه الأمة كلها '),
(24529, 'Malachi', 39, 3, 10, ' هاتوا جميع العشور إلى الخزنة ليكون في بيتي طعام ، وجربوني بهذا ، قال رب الجنود ، إن كنت لا أفتح لكم كوى السماوات ، وأفيض عليكم بركة حتى لا توسع '),
(24530, 'Malachi', 39, 3, 11, ' وأنتهر من أجلكم الآكل فلا يفسد لكم ثمر الأرض ، ولا يعقر لكم الكرم في الحقل ، قال رب الجنود '),
(24531, 'Malachi', 39, 3, 12, ' ويطوبكم كل الأمم ، لأنكم تكونون أرض مسرة ، قال رب الجنود '),
(24532, 'Malachi', 39, 3, 13, ' أقوالكم اشتدت علي ، قال الرب . وقلتم : ماذا قلنا عليك '),
(24533, 'Malachi', 39, 3, 14, ' قلتم : عبادة الله باطلة ، وما المنفعة من أننا حفظنا شعائره ، وأننا سلكنا بالحزن قدام رب الجنود '),
(24534, 'Malachi', 39, 3, 15, ' والآن نحن مطوبون المستكبرين وأيضا فاعلو الشر يبنون . بل جربوا الله ونجوا '),
(24535, 'Malachi', 39, 3, 16, ' حينئذ كلم متقو الرب كل واحد قريبه ، والرب أصغى وسمع ، وكتب أمامه سفر تذكرة للذين اتقوا الرب وللمفكرين في اسمه '),
(24536, 'Malachi', 39, 3, 17, ' ويكونون لي ، قال رب الجنود ، في اليوم الذي أنا صانع خاصة ، وأشفق عليهم كما يشفق الإنسان على ابنه الذي يخدمه '),
(24537, 'Malachi', 39, 3, 18, ' فتعودون وتميزون بين الصديق والشرير ، بين من يعبد الله ومن لا يعبده '),
(24538, 'Malachi', 39, 4, 1, ' فهوذا يأتي اليوم المتقد كالتنور ، وكل المستكبرين وكل فاعلي الشر يكونون قشا ، ويحرقهم اليوم الآتي ، قال رب الجنود ، فلا يبقي لهم أصلا ولا فرعا '),
(24539, 'Malachi', 39, 4, 2, ' ولكم أيها المتقون اسمي تشرق شمس البر والشفاء في أجنحتها ، فتخرجون وتنشأون كعجول الصيرة '),
(24540, 'Malachi', 39, 4, 3, ' وتدوسون الأشرار لأنهم يكونون رمادا تحت بطون أقدامكم يوم أفعل هذا ، قال رب الجنود '),
(24541, 'Malachi', 39, 4, 4, ' اذكروا شريعة موسى عبدي التي أمرته بها في حوريب على كل إسرائيل . الفرائض والأحكام '),
(24542, 'Malachi', 39, 4, 5, ' هأنذا أرسل إليكم إيليا النبي قبل مجيء يوم الرب ، اليوم العظيم والمخوف '),
(24543, 'Malachi', 39, 4, 6, ' فيرد قلب الآباء على الأبناء ، وقلب الأبناء على آبائهم . لئلا آتي وأضرب الأرض بلعن '),
(24544, 'Malachi', 39, 1, 1, ' وحي كلمة الرب لإسرائيل عن يد ملاخي '),
(24545, 'Malachi', 39, 1, 2, ' أحببتكم ، قال الرب . وقلتم : بم أحببتنا ؟ أليس عيسو أخا ليعقوب ، يقول الرب ، وأحببت يعقوب '),
(24546, 'Malachi', 39, 1, 3, ' وأبغضت عيسو ، وجعلت جباله خرابا وميراثه لذئاب البرية '),
(24547, 'Malachi', 39, 1, 4, ' لأن أدوم قال : قد هدمنا ، فنعود ونبني الخرب . هكذا قال رب الجنود : هم يبنون وأنا أهدم . ويدعونهم تخوم الشر ، والشعب الذي غضب عليه الرب إلى الأبد '),
(24548, 'Malachi', 39, 1, 5, ' فترى أعينكم وتقولون : ليتعظم الرب من عند تخم إسرائيل '),
(24549, 'Malachi', 39, 1, 6, ' الابن يكرم أباه ، والعبد يكرم سيده . فإن كنت أنا أبا ، فأين كرامتي ؟ وإن كنت سيدا ، فأين هيبتي ؟ قال لكم رب الجنود . أيها الكهنة المحتقرون اسمي . وتقولون : بم احتقرنا اسمك '),
(24550, 'Malachi', 39, 1, 7, ' تقربون خبزا نجسا على مذبحي . وتقولون : بم نجسناك ؟ بقولكم : إن مائدة الرب محتقرة '),
(24551, 'Malachi', 39, 1, 8, ' وإن قربتم الأعمى ذبيحة ، أفليس ذلك شرا ؟ وإن قربتم الأعرج والسقيم ، أفليس ذلك شرا ؟ قربه لواليك ، أفيرضى عليك أو يرفع وجهك ؟ قال رب الجنود '),
(24552, 'Malachi', 39, 1, 9, ' والآن ترضوا وجه الله فيتراءف علينا . هذه كانت من يدكم . هل يرفع وجهكم ؟ قال رب الجنود '),
(24553, 'Malachi', 39, 1, 10, ' من فيكم يغلق الباب بل لا توقدون على مذبحي مجانا . ليست لي مسرة بكم ، قال رب الجنود ، ولا أقبل تقدمة من يدكم '),
(24554, 'Malachi', 39, 1, 11, ' لأنه من مشرق الشمس إلى مغربها اسمي عظيم بين الأمم ، وفي كل مكان يقرب لاسمي بخور وتقدمة طاهرة ، لأن اسمي عظيم بين الأمم ، قال رب الجنود '),
(24555, 'Malachi', 39, 1, 12, ' أما أنتم فمنجسوه ، بقولكم : إن مائدة الرب تنجست ، وثمرتها محتقر طعامها '),
(24556, 'Malachi', 39, 1, 13, ' وقلتم : ما هذه المشقة ؟ وتأففتم عليه ، قال رب الجنود . وجئتم بالمغتصب والأعرج والسقيم ، فأتيتم بالتقدمة . فهل أقبلها من يدكم ؟ قال الرب '),
(24557, 'Malachi', 39, 1, 14, ' وملعون الماكر الذي يوجد في قطيعه ذكر وينذر ويذبح للسيد عائبا . لأني أنا ملك عظيم ، قال رب الجنود ، واسمي مهيب بين الأمم '),
(24558, 'Malachi', 39, 2, 1, ' والآن إليكم هذه الوصية أيها الكهنة '),
(24559, 'Malachi', 39, 2, 2, ' إن كنتم لا تسمعون ولا تجعلون في القلب لتعطوا مجدا لاسمي ، قال رب الجنود . فإني أرسل عليكم اللعن ، وألعن بركاتكم ، بل قد لعنتها ، لأنكم لستم جاعلين في القلب '),
(24560, 'Malachi', 39, 2, 3, ' هأنذا أنتهر لكم الزرع ، وأمد الفرث على وجوهكم ، فرث أعيادكم ، فتنزعون معه '),
(24561, 'Malachi', 39, 2, 4, ' فتعلمون أني أرسلت إليكم هذه الوصية لكون عهدي مع لاوي ، قال رب الجنود '),
(24562, 'Malachi', 39, 2, 5, ' كان عهدي معه للحياة والسلام ، وأعطيته إياهما للتقوى . فاتقاني ، ومن اسمي ارتاع هو '),
(24563, 'Malachi', 39, 2, 6, ' شريعة الحق كانت في فيه ، وإثم لم يوجد في شفتيه . سلك معي في السلام والاستقامة ، وأرجع كثيرين عن الإثم '),
(24564, 'Malachi', 39, 2, 7, ' لأن شفتي الكاهن تحفظان معرفة ، ومن فمه يطلبون الشريعة ، لأنه رسول رب الجنود '),
(24565, 'Malachi', 39, 2, 8, ' أما أنتم فحدتم عن الطريق وأعثرتم كثيرين بالشريعة . أفسدتم عهد لاوي ، قال رب الجنود '),
(24566, 'Malachi', 39, 2, 9, ' فأنا أيضا صيرتكم محتقرين ودنيئين عند كل الشعب ، كما أنكم لم تحفظوا طرقي بل حابيتم في الشريعة '),
(24567, 'Malachi', 39, 2, 10, ' أليس أب واحد لكلنا ؟ أليس إله واحد خلقنا ؟ فلم نغدر الرجل بأخيه لتدنيس عهد آبائنا '),
(24568, 'Malachi', 39, 2, 11, ' غدر يهوذا ، وعمل الرجس في إسرائيل وفي أورشليم . لأن يهوذا قد نجس قدس الرب الذي أحبه ، وتزوج بنت إله غريب '),
(24569, 'Mark', 41, 1, 1, ' بدء إنجيل يسوع المسيح ابن الله '),
(24570, 'Mark', 41, 1, 2, ' كما هو مكتوب في الأنبياء ها أنا أرسل أمام وجهك ملاكي ، الذي يهيئ طريقك قدامك '),
(24571, 'Mark', 41, 1, 3, ' صوت صارخ في البرية : أعدوا طريق الرب ، اصنعوا سبله مستقيمة '),
(24572, 'Mark', 41, 1, 4, ' كان يوحنا يعمد في البرية ويكرز بمعمودية التوبة لمغفرة الخطايا '),
(24573, 'Mark', 41, 1, 5, ' وخرج إليه جميع كورة اليهودية وأهل أورشليم واعتمدوا جميعهم منه في نهر الأردن ، معترفين بخطاياهم '),
(24574, 'Mark', 41, 1, 6, ' وكان يوحنا يلبس وبر الإبل ، ومنطقة من جلد على حقويه ، ويأكل جرادا وعسلا بريا '),
(24575, 'Mark', 41, 1, 7, ' وكان يكرز قائلا : يأتي بعدي من هو أقوى مني ، الذي لست أهلا أن أنحني وأحل سيور حذائه '),
(24576, 'Mark', 41, 1, 8, ' أنا عمدتكم بالماء ، وأما هو فسيعمدكم بالروح القدس '),
(24577, 'Mark', 41, 1, 9, ' وفي تلك الأيام جاء يسوع من ناصرة الجليل واعتمد من يوحنا في الأردن '),
(24578, 'Mark', 41, 1, 10, ' وللوقت وهو صاعد من الماء رأى السماوات قد انشقت ، والروح مثل حمامة نازلا عليه '),
(24579, 'Mark', 41, 1, 11, ' وكان صوت من السماوات : أنت ابني الحبيب الذي به سررت '),
(24580, 'Mark', 41, 1, 12, ' وللوقت أخرجه الروح إلى البرية '),
(24581, 'Mark', 41, 1, 13, ' وكان هناك في البرية أربعين يوما يجرب من الشيطان . وكان مع الوحوش . وصارت الملائكة تخدمه '),
(24582, 'Mark', 41, 1, 14, ' وبعدما أسلم يوحنا جاء يسوع إلى الجليل يكرز ببشارة ملكوت الله '),
(24583, 'Mark', 41, 1, 15, ' ويقول : قد كمل الزمان واقترب ملكوت الله ، فتوبوا وآمنوا بالإنجيل '),
(24584, 'Mark', 41, 1, 16, ' وفيما هو يمشي عند بحر الجليل أبصر سمعان وأندراوس أخاه يلقيان شبكة في البحر ، فإنهما كانا صيادين '),
(24585, 'Mark', 41, 1, 17, ' فقال لهما يسوع : هلم ورائي فأجعلكما تصيران صيادي الناس '),
(24586, 'Mark', 41, 1, 18, ' فللوقت تركا شباكهما وتبعاه '),
(24587, 'Mark', 41, 1, 19, ' ثم اجتاز من هناك قليلا فرأى يعقوب بن زبدي  يوحنا أخاه ، وهما في السفينة يصلحان الشباك '),
(24588, 'Mark', 41, 1, 20, ' دعاهما للوقت . فتركا أباهما زبدي في السفينة مع الأجرى وذهبا وراءه '),
(24589, 'Mark', 41, 1, 21, ' ثم دخلوا كفرناحوم ، وللوقت دخل المجمع في السبت وصار يعلم '),
(24590, 'Mark', 41, 1, 22, ' فبهتوا من تعليمه لأنه كان يعلمهم كمن له سلطان وليس كالكتبة '),
(24591, 'Mark', 41, 1, 23, ' وكان في مجمعهم رجل به روح نجس ، فصرخ '),
(24592, 'Mark', 41, 1, 24, ' قائلا : آه ما لنا ولك يا يسوع الناصري ؟ أتيت لتهلكنا أنا أعرفك من أنت : قدوس الله '),
(24593, 'Mark', 41, 1, 25, ' فانتهره يسوع قائلا : اخرس واخرج منه '),
(24594, 'Mark', 41, 1, 26, ' فصرعه الروح النجس وصاح بصوت عظيم وخرج منه '),
(24595, 'Mark', 41, 1, 27, ' فتحيروا كلهم ، حتى سأل بعضهم بعضا قائلين : ما هذا ؟ ما هو هذا التعليم الجديد ؟ لأنه بسلطان يأمر حتى الأرواح النجسة فتطيعه '),
(24596, 'Mark', 41, 1, 28, ' فخرج خبره للوقت في كل الكورة المحيطة بالجليل '),
(24597, 'Mark', 41, 1, 29, ' ولما خرجوا من المجمع جاءوا للوقت إلى بيت سمعان وأندراوس مع يعقوب ويوحنا '),
(24598, 'Mark', 41, 1, 30, ' وكانت حماة سمعان مضطجعة محمومة ، فللوقت أخبروه عنها '),
(24599, 'Mark', 41, 1, 31, ' فتقدم وأقامها ماسكا بيدها ، فتركتها الحمى حالا  صارت تخدمهم '),
(24600, 'Mark', 41, 1, 32, ' ولما صار المساء ، إذ غربت الشمس ، قدموا إليه جميع السقماء والمجانين '),
(24601, 'Mark', 41, 1, 33, ' وكانت المدينة كلها مجتمعة على الباب '),
(24602, 'Mark', 41, 1, 34, ' فشفى كثيرين كانوا مرضى بأمراض مختلفة ، وأخرج شياطين كثيرة ، ولم يدع الشياطين يتكلمون لأنهم عرفوه '),
(24603, 'Mark', 41, 1, 35, ' وفي الصبح باكرا جدا قام وخرج ومضى إلى موضع خلاء ، وكان يصلي هناك '),
(24604, 'Mark', 41, 1, 36, ' فتبعه سمعان والذين معه '),
(24605, 'Mark', 41, 1, 37, ' ولما وجدوه قالوا له : إن الجميع يطلبونك '),
(24606, 'Mark', 41, 1, 38, ' فقال لهم : لنذهب إلى القرى المجاورة لأكرز هناك أيضا ، لأني لهذا خرجت '),
(24607, 'Mark', 41, 1, 39, ' فكان يكرز في مجامعهم في كل الجليل ويخرج الشياطين '),
(24608, 'Mark', 41, 1, 40, ' فأتى إليه أبرص يطلب إليه جاثيا وقائلا له : إن أردت تقدر أن تطهرني ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(24609, 'Mark', 41, 1, 41, ' فتحنن يسوع ومد يده ولمسه وقال له : أريد ، فاطهر '),
(24610, 'Mark', 41, 1, 42, ' فللوقت وهو يتكلم ذهب عنه البرص وطهر '),
(24611, 'Mark', 41, 1, 43, ' فانتهره وأرسله للوقت '),
(24612, 'Mark', 41, 1, 44, ' وقال له : انظر ، لا تقل لأحد شيئا ، بل اذهب أر نفسك للكاهن وقدم عن تطهيرك ما أمر به موسى ، شهادة لهم '),
(24613, 'Mark', 41, 1, 45, ' وأما هو فخرج وابتدأ ينادي كثيرا ويذيع الخبر ، حتى لم يعد يقدر أن يدخل مدينة ظاهرا ، بل كان خارجا في مواضع خالية ، وكانوا يأتون إليه من كل ناحية '),
(24614, 'Mark', 41, 2, 1, ' ثم دخل كفرناحوم أيضا بعد أيام ، فسمع أنه في بيت '),
(24615, 'Mark', 41, 2, 2, ' وللوقت اجتمع كثيرون حتى لم يعد يسع ولا ما حول الباب . فكان يخاطبهم بالكلمة '),
(24616, 'Mark', 41, 2, 3, ' وجاءوا إليه مقدمين مفلوجا يحمله أربعة '),
(24617, 'Mark', 41, 2, 4, ' وإذ لم يقدروا أن يقتربوا إليه من أجل الجمع ، كشفوا السقف حيث كان . وبعد ما نقبوه دلوا السرير الذي كان المفلوج مضطجعا عليه '),
(24618, 'Mark', 41, 2, 5, ' فلما رأى يسوع إيمانهم ، قال للمفلوج : يا بني ، مغفورة لك خطاياك '),
(24619, 'Mark', 41, 2, 6, ' وكان قوم من الكتبة هناك جالسين يفكرون في قلوبهم '),
(24620, 'Mark', 41, 2, 7, ' لماذا يتكلم هذا هكذا بتجاديف ؟ من يقدر أن يغفر خطايا إلا الله وحده '),
(24621, 'Mark', 41, 2, 8, ' فللوقت شعر يسوع بروحه أنهم يفكرون هكذا في أنفسهم ، فقال لهم : لماذا تفكرون بهذا في قلوبكم '),
(24622, 'Mark', 41, 2, 9, ' أيما أيسر ، أن يقال للمفلوج : مغفورة لك خطاياك ، أم أن يقال : قم واحمل سريرك وامش '),
(24623, 'Mark', 41, 2, 10, ' ولكن لكي تعلموا أن لابن الإنسان سلطانا على الأرض أن يغفر الخطايا . قال للمفلوج '),
(24624, 'Mark', 41, 2, 11, ' لك أقول : قم واحمل سريرك واذهب إلى بيتك '),
(24625, 'Mark', 41, 2, 12, ' فقام للوقت وحمل السرير وخرج قدام الكل ، حتى بهت الجميع ومجدوا الله قائلين : ما رأينا مثل هذا قط '),
(24626, 'Mark', 41, 2, 13, ' ثم خرج أيضا إلى البحر . وأتى إليه كل الجمع فعلمهم '),
(24627, 'Mark', 41, 2, 14, ' وفيما هو مجتاز رأى لاوي بن حلفى جالسا عند مكان الجباية ، فقال له : اتبعني . فقام وتبعه '),
(24628, 'Mark', 41, 2, 15, ' وفيما هو متكئ في بيته كان كثيرون من العشارين والخطاة يتكئون مع يسوع وتلاميذه ، لأنهم كانوا كثيرين وتبعوه. '),
(24629, 'Mark', 41, 2, 16, ' وأما الكتبة والفريسيون فلما رأوه يأكل مع العشارين والخطاة ، قالوا لتلاميذه : ما باله يأكل ويشرب مع العشارين والخطاة '),
(24630, 'Mark', 41, 2, 17, ' فلما سمع يسوع قال لهم : لا يحتاج الأصحاء إلى طبيب بل المرضى . لم آت لأدعو أبرارا بل خطاة إلى التوبة '),
(24631, 'Mark', 41, 2, 18, ' وكان تلاميذ يوحنا والفريسيين يصومون ، فجاءوا وقالوا له : لماذا يصوم تلاميذ يوحنا والفريسيين ، وأما تلاميذك فلا يصومون '),
(24632, 'Mark', 41, 2, 19, ' فقال لهم يسوع : هل يستطيع بنو العرس أن يصوموا والعريس معهم ؟ مادام العريس معهم لا يستطيعون أن يصوموا '),
(24633, 'Mark', 41, 2, 20, ' ولكن ستأتي أيام حين يرفع العريس عنهم ، فحينئذ يصومون في تلك الأيام '),
(24634, 'Mark', 41, 2, 21, ' ليس أحد يخيط رقعة من قطعة جديدة على ثوب عتيق ، وإلا فالملء الجديد يأخذ من العتيق فيصير الخرق أردأ '),
(24635, 'Mark', 41, 2, 22, ' وليس أحد يجعل خمرا جديدة في زقاق عتيقة ، لئلا تشق الخمر الجديدة الزقاق ، فالخمر تنصب والزقاق تتلف . بل يجعلون خمرا جديدة في زقاق جديدة '),
(24636, 'Mark', 41, 2, 23, ' واجتاز في السبت بين الزروع ، فابتدأ تلاميذه يقطفون السنابل وهم سائرون '),
(24637, 'Mark', 41, 2, 24, ' فقال له الفريسيون : انظر لماذا يفعلون في السبت ما لا يحل '),
(24638, 'Mark', 41, 2, 25, ' فقال لهم : أما قرأتم قط ما فعله داود حين احتاج وجاع هو والذين معه '),
(24639, 'Mark', 41, 2, 26, ' كيف دخل بيت الله في أيام أبيأثار رئيس الكهنة ، وأكل خبز التقدمة الذي لا يحل أكله إلا للكهنة ، وأعطى الذين كانوا معه أيضا '),
(24640, 'Mark', 41, 2, 27, ' ثم قال لهم : السبت إنما جعل لأجل الإنسان ، لا الإنسان لأجل السبت '),
(24641, 'Mark', 41, 2, 28, ' إذا ابن الإنسان هو رب السبت أيضا '),
(24642, 'Mark', 41, 3, 1, ' ثم دخل أيضا إلى المجمع ، وكان هناك رجل يده يابسة '),
(24643, 'Mark', 41, 3, 2, ' فصاروا يراقبونه : هل يشفيه في السبت ؟ لكي يشتكوا عليه '),
(24644, 'Mark', 41, 3, 3, ' فقال للرجل الذي له اليد اليابسة : قم في الوسط '),
(24645, 'Mark', 41, 3, 4, ' ثم قال لهم : هل يحل في السبت فعل الخير أو فعل الشر ؟ تخليص نفس أو قتل ؟ فسكتوا '),
(24646, 'Mark', 41, 3, 5, ' فنظر حوله إليهم بغضب ، حزينا على غلاظة قلوبهم ، وقال للرجل : مد يدك . فمدها ، فعادت يده صحيحة كالأخرى '),
(24647, 'Mark', 41, 3, 6, ' فخرج الفريسيون للوقت مع الهيرودسيين وتشاوروا عليه لكي يهلكوه '),
(24648, 'Mark', 41, 3, 7, ' فانصرف يسوع مع تلاميذه إلى البحر ، وتبعه جمع كثير من الجليل ومن اليهودية '),
(24649, 'Mark', 41, 3, 8, ' ومن أورشليم ومن أدومية ومن عبر الأردن والذين حول صور وصيداء ، جمع كثير ، إذ سمعوا كم صنع أتوا إليه '),
(24650, 'Mark', 41, 3, 9, ' فقال لتلاميذه أن تلازمه سفينة صغيرة لسبب الجمع ، كي لا يزحموه '),
(24651, 'Mark', 41, 3, 10, ' لأنه كان قد شفى كثيرين ، حتى وقع عليه ليلمسه كل من فيه داء '),
(24652, 'Mark', 41, 3, 11, ' والأرواح النجسة حينما نظرته خرت له وصرخت قائلة : إنك أنت ابن الله '),
(24653, 'Mark', 41, 3, 12, ' وأوصاهم كثيرا أن لا يظهروه '),
(24654, 'Mark', 41, 3, 13, ' ثم صعد إلى الجبل ودعا الذين أرادهم فذهبوا إليه '),
(24655, 'Mark', 41, 3, 14, ' وأقام اثني عشر ليكونوا معه ، وليرسلهم ليكرزوا '),
(24656, 'Mark', 41, 3, 15, ' ويكون لهم سلطان على شفاء الأمراض وإخراج الشياطين '),
(24657, 'Mark', 41, 3, 16, ' وجعل لسمعان اسم بطرس '),
(24658, 'Mark', 41, 3, 17, ' ويعقوب بن زبدي ويوحنا أخا يعقوب ، وجعل لهما اسم بوانرجس أي ابني الرعد '),
(24659, 'Mark', 41, 3, 18, ' وأندراوس ، وفيلبس ، وبرثولماوس ، ومتى ، وتوما ، ويعقوب بن حلفى ، وتداوس ، وسمعان القانوي '),
(24660, 'Mark', 41, 3, 19, ' ويهوذا الإسخريوطي الذي أسلمه . ثم أتوا إلى بيت '),
(24661, 'Mark', 41, 3, 20, ' فاجتمع أيضا جمع حتى لم يقدروا ولا على أكل خبز '),
(24662, 'Mark', 41, 3, 21, ' ولما سمع أقرباؤه خرجوا ليمسكوه ، لأنهم قالوا : إنه مختل '),
(24663, 'Mark', 41, 3, 22, ' وأما الكتبة الذين نزلوا من أورشليم فقالوا : إن معه بعلزبول وإنه برئيس الشياطين يخرج الشياطين '),
(24664, 'Mark', 41, 3, 23, ' فدعاهم وقال لهم بأمثال : كيف يقدر شيطان أن يخرج شيطانا '),
(24665, 'Mark', 41, 3, 24, ' وإن انقسمت مملكة على ذاتها لا تقدر تلك المملكة أن تثبت '),
(24666, 'Mark', 41, 3, 25, ' وإن انقسم بيت على ذاته لا يقدر ذلك البيت أن يثبت '),
(24667, 'Mark', 41, 3, 26, ' وإن قام الشيطان على ذاته وانقسم لا يقدر أن يثبت ، بل يكون له انقضاء '),
(24668, 'Mark', 41, 3, 27, ' لا يستطيع أحد أن يدخل بيت قوي وينهب أمتعته ، إن لم يربط القوي أولا ، وحينئذ ينهب بيته '),
(24669, 'Mark', 41, 3, 28, ' الحق أقول لكم : إن جميع الخطايا تغفر لبني البشر ، والتجاديف التي يجدفونها '),
(24670, 'Mark', 41, 3, 29, ' ولكن من جدف على الروح القدس فليس له مغفرة إلى الأبد ، بل هو مستوجب دينونة أبدية '),
(24671, 'Mark', 41, 3, 30, ' لأنهم قالوا : إن معه روحا نجسا '),
(24672, 'Mark', 41, 3, 31, ' فجاءت حينئذ إخوته وأمه ووقفوا خارجا وأرسلوا إليه يدعونه '),
(24673, 'Mark', 41, 3, 32, ' وكان الجمع جالسا حوله ، فقالوا له : هوذا أمك وإخوتك خارجا يطلبونك '),
(24674, 'Mark', 41, 3, 33, ' فأجابهم قائلا : من أمي وإخوتي '),
(24675, 'Mark', 41, 3, 34, ' ثم نظر حوله إلى الجالسين وقال : ها أمي وإخوتي '),
(24676, 'Mark', 41, 3, 35, ' لأن من يصنع مشيئة الله هو أخي وأختي وأمي '),
(24677, 'Mark', 41, 4, 1, ' وابتدأ أيضا يعلم عند البحر ، فاجتمع إليه جمع كثير حتى إنه دخل السفينة وجلس على البحر ، والجمع كله كان عند البحر على الأرض. '),
(24678, 'Mark', 41, 4, 2, ' فكان يعلمهم كثيرا بأمثال . وقال لهم في تعليمه '),
(24679, 'Mark', 41, 4, 3, ' اسمعوا هوذا الزارع قد خرج ليزرع '),
(24680, 'Mark', 41, 4, 4, ' وفيما هو يزرع سقط بعض على الطريق ، فجاءت طيور السماء وأكلته '),
(24681, 'Mark', 41, 4, 5, ' وسقط آخر على مكان محجر ، حيث لم تكن له تربة كثيرة ، فنبت حالا إذ لم يكن له عمق أرض '),
(24682, 'Mark', 41, 4, 6, ' ولكن لما أشرقت الشمس احترق ، وإذ لم يكن له أصل جف '),
(24683, 'Mark', 41, 4, 7, ' وسقط آخر في الشوك ، فطلع الشوك وخنقه فلم يعط ثمرا '),
(24684, 'Mark', 41, 4, 8, ' وسقط آخر في الأرض الجيدة ، فأعطى ثمرا يصعد وينمو ، فأتى واحد بثلاثين وآخر بستين وآخر بمئة '),
(24685, 'Mark', 41, 4, 9, ' ثم قال لهم : من له أذنان للسمع ، فليسمع '),
(24686, 'Mark', 41, 4, 10, ' ولما كان وحده سأله الذين حوله مع الاثني عشر عن المثل '),
(24687, 'Mark', 41, 4, 11, ' فقال لهم : قد أعطي لكم أن تعرفوا سر ملكوت الله . وأما الذين هم من خارج فبالأمثال يكون لهم كل شيء '),
(24688, 'Mark', 41, 4, 12, ' لكي يبصروا مبصرين ولا ينظروا ، ويسمعوا سامعين ولا يفهموا ، لئلا يرجعوا فتغفر لهم خطاياهم '),
(24689, 'Mark', 41, 4, 13, ' ثم قال لهم : أما تعلمون هذا المثل ؟ فكيف تعرفون جميع الأمثال '),
(24690, 'Mark', 41, 4, 14, ' الزارع يزرع الكلمة '),
(24691, 'Mark', 41, 4, 15, ' وهؤلاء هم الذين على الطريق : حيث تزرع الكلمة ، وحينما يسمعون يأتي الشيطان للوقت وينزع الكلمة المزروعة في قلوبهم '),
(24692, 'Mark', 41, 4, 16, ' وهؤلاء كذلك هم الذين زرعوا على الأماكن المحجرة : الذين حينما يسمعون الكلمة يقبلونها للوقت بفرح '),
(24693, 'Mark', 41, 4, 17, ' ولكن ليس لهم أصل في ذواتهم ، بل هم إلى حين . فبعد ذلك إذا حدث ضيق أو اضطهاد من أجل الكلمة ، فللوقت يعثرون '),
(24694, 'Mark', 41, 4, 18, ' وهؤلاء هم الذين زرعوا بين الشوك : هؤلاء هم الذين يسمعون الكلمة '),
(24695, 'Mark', 41, 4, 19, ' وهموم هذا العالم وغرور الغنى وشهوات سائر الأشياء تدخل وتخنق الكلمة فتصير بلا ثمر '),
(24696, 'Mark', 41, 4, 20, ' وهؤلاء هم الذين زرعوا على الأرض الجيدة : الذين يسمعون الكلمة ويقبلونها ، ويثمرون : واحد ثلاثين وآخر ستين وآخر مئة '),
(24697, 'Mark', 41, 4, 21, ' ثم قال لهم : هل يؤتى بسراج ليوضع تحت المكيال أو تحت السرير ؟ أليس ليوضع على المنارة '),
(24698, 'Mark', 41, 4, 22, ' لأنه ليس شيء خفي لا يظهر ، ولا صار مكتوما إلا ليعلن '),
(24699, 'Mark', 41, 4, 23, ' إن كان لأحد أذنان للسمع ، فليسمع '),
(24700, 'Mark', 41, 4, 24, ' وقال لهم : انظروا ما تسمعون بالكيل الذي به تكيلون يكال لكم ويزاد لكم أيها السامعون '),
(24701, 'Mark', 41, 4, 25, ' لأن من له سيعطى ، وأما من ليس له فالذي عنده سيؤخذ منه '),
(24702, 'Mark', 41, 4, 26, ' وقال : هكذا ملكوت الله : كأن إنسانا يلقي البذار على الأرض '),
(24703, 'Mark', 41, 4, 27, ' وينام ويقوم ليلا ونهارا ، والبذار يطلع وينمو ، وهو لا يعلم كيف '),
(24704, 'Mark', 41, 4, 28, ' لأن الأرض من ذاتها تأتي بثمر . أولا نباتا ، ثم سنبلا ، ثم قمحا ملآن في السنبل '),
(24705, 'Mark', 41, 4, 29, ' وأما متى أدرك الثمر ، فللوقت يرسل المنجل لأن الحصاد قد حضر '),
(24706, 'Mark', 41, 4, 30, ' وقال : بماذا نشبه ملكوت الله ؟ أو بأي مثل نمثله '),
(24707, 'Mark', 41, 4, 31, ' مثل حبة خردل ، متى زرعت في الأرض فهي أصغر جميع البزور التي على الأرض '),
(24708, 'Mark', 41, 4, 32, ' ولكن متى زرعت تطلع وتصير أكبر جميع البقول ، وتصنع أغصانا كبيرة ، حتى تستطيع طيور السماء أن تتآوى تحت ظلها '),
(24709, 'Mark', 41, 4, 33, ' وبأمثال كثيرة مثل هذه كان يكلمهم حسبما كانوا يستطيعون أن يسمعوا '),
(24710, 'Mark', 41, 4, 34, ' وبدون مثل لم يكن يكلمهم . وأما على انفراد فكان يفسر لتلاميذه كل شيء '),
(24711, 'Mark', 41, 4, 35, ' وقال لهم في ذلك اليوم لما كان المساء : لنجتز إلى العبر '),
(24712, 'Mark', 41, 4, 36, ' فصرفوا الجمع وأخذوه كما كان في السفينة . وكانت معه أيضا سفن أخرى صغيرة '),
(24713, 'Mark', 41, 4, 37, ' فحدث نوء ريح عظيم ، فكانت الأمواج تضرب إلى السفينة حتى صارت تمتلئ '),
(24714, 'Mark', 41, 4, 38, ' وكان هو في المؤخر على وسادة نائما . فأيقظوه وقالوا له : يا معلم ، أما يهمك أننا نهلك '),
(24715, 'Mark', 41, 4, 39, ' فقام وانتهر الريح ، وقال للبحر : اسكت ابكم . فسكنت الريح وصار هدوء عظيم '),
(24716, 'Mark', 41, 4, 40, ' وقال لهم : ما بالكم خائفين هكذا ؟ كيف لا إيمان لكم '),
(24717, 'Mark', 41, 4, 41, ' فخافوا خوفا عظيما ، وقالوا بعضهم لبعض : من هو هذا ؟ فإن الريح أيضا والبحر يطيعانه '),
(24718, 'Mark', 41, 5, 1, ' وجاءوا إلى عبر البحر إلى كورة الجدريين '),
(24719, 'Mark', 41, 5, 2, ' ولما خرج من السفينة للوقت استقبله من القبور إنسان به روح نجس '),
(24720, 'Mark', 41, 5, 3, ' كان مسكنه في القبور ، ولم يقدر أحد أن يربطه ولا بسلاسل '),
(24721, 'Mark', 41, 5, 4, ' لأنه قد ربط كثيرا بقيود وسلاسل فقطع السلاسل وكسر القيود ، فلم يقدر أحد أن يذلله '),
(24722, 'Mark', 41, 5, 5, ' وكان دائما ليلا ونهارا في الجبال وفي القبور ، يصيح ويجرح نفسه بالحجارة '),
(24723, 'Mark', 41, 5, 6, ' فلما رأى يسوع من بعيد ركض وسجد له '),
(24724, 'Mark', 41, 5, 7, ' وصرخ بصوت عظيم وقال : ما لي ولك يا يسوع ابن الله العلي ؟ أستحلفك بالله أن لا تعذبني '),
(24725, 'Mark', 41, 5, 8, ' لأنه قال له : اخرج من الإنسان يا أيها الروح النجس '),
(24726, 'Mark', 41, 5, 9, ' وسأله : ما اسمك ؟ فأجاب قائلا : اسمي لجئون ، لأننا كثيرون '),
(24727, 'Mark', 41, 5, 10, ' وطلب إليه كثيرا أن لا يرسلهم إلى خارج الكورة '),
(24728, 'Mark', 41, 5, 11, ' وكان هناك عند الجبال قطيع كبير من الخنازير يرعى '),
(24729, 'Mark', 41, 5, 12, ' فطلب إليه كل الشياطين قائلين : أرسلنا إلى الخنازير لندخل فيها '),
(24730, 'Mark', 41, 5, 13, ' فأذن لهم يسوع للوقت . فخرجت الأرواح النجسة ودخلت في الخنازير ، فاندفع القطيع من على الجرف إلى البحر . وكان نحو ألفين ، فاختنق في البحر '),
(24731, 'Mark', 41, 5, 14, ' وأما رعاة الخنازير فهربوا وأخبروا في المدينة وفي الضياع . فخرجوا ليروا ما جرى '),
(24732, 'Mark', 41, 5, 15, ' وجاءوا إلى يسوع فنظروا المجنون الذي كان فيه اللجئون جالسا ولابسا وعاقلا ، فخافوا '),
(24733, 'Mark', 41, 5, 16, ' فحدثهم الذين رأوا كيف جرى للمجنون وعن الخنازير '),
(24734, 'Mark', 41, 5, 17, ' فابتدأوا يطلبون إليه أن يمضي من تخومهم '),
(24735, 'Mark', 41, 5, 18, ' ولما دخل السفينة طلب إليه الذي كان مجنونا أن يكون معه '),
(24736, 'Mark', 41, 5, 19, ' فلم يدعه يسوع ، بل قال له : اذهب إلى بيتك وإلى أهلك ، وأخبرهم كم صنع الرب بك ورحمك '),
(24737, 'Mark', 41, 5, 20, ' فمضى وابتدأ ينادي في العشر المدن كم صنع به يسوع . فتعجب الجميع '),
(24738, 'Mark', 41, 5, 21, ' ولما اجتاز يسوع في السفينة أيضا إلى العبر ، اجتمع إليه جمع كثير ، وكان عند البحر '),
(24739, 'Mark', 41, 5, 22, ' وإذا واحد من رؤساء المجمع اسمه يايرس جاء . ولما رآه خر عند قدميه '),
(24740, 'Mark', 41, 5, 23, ' وطلب إليه كثيرا قائلا : ابنتي الصغيرة على آخر نسمة . ليتك تأتي وتضع يدك عليها لتشفى فتحيا '),
(24741, 'Mark', 41, 5, 24, ' فمضى معه وتبعه جمع كثير وكانوا يزحمونه '),
(24742, 'Mark', 41, 5, 25, ' وامرأة بنزف دم منذ اثنتي عشرة سنة '),
(24743, 'Mark', 41, 5, 26, ' وقد تألمت كثيرا من أطباء كثيرين ، وأنفقت كل ما عندها ولم تنتفع شيئا ، بل صارت إلى حال أردأ '),
(24744, 'Mark', 41, 5, 27, ' لما سمعت بيسوع ، جاءت في الجمع من وراء ، ومست ثوبه '),
(24745, 'Mark', 41, 5, 28, ' لأنها قالت : إن مسست ولو ثيابه شفيت '),
(24746, 'Mark', 41, 5, 29, ' فللوقت جف ينبوع دمها ، وعلمت في جسمها أنها قد برئت من الداء '),
(24747, 'Mark', 41, 5, 30, ' فللوقت التفت يسوع بين الجمع شاعرا في نفسه بالقوة التي خرجت منه ، وقال : من لمس ثيابي '),
(24748, 'Mark', 41, 5, 31, ' فقال له تلاميذه : أنت تنظر الجمع يزحمك ، وتقول : من لمسني '),
(24749, 'Mark', 41, 5, 32, ' وكان ينظر حوله ليرى التي فعلت هذا '),
(24750, 'Mark', 41, 5, 33, ' وأما المرأة فجاءت وهي خائفة ومرتعدة ، عالمة بما حصل لها ، فخرت وقالت له الحق كله '),
(24751, 'Mark', 41, 5, 34, ' فقال لها : يا ابنة ، إيمانك قد شفاك ، اذهبي بسلام وكوني صحيحة من دائك '),
(24752, 'Mark', 41, 5, 35, ' وبينما هو يتكلم جاءوا من دار رئيس المجمع قائلين : ابنتك ماتت . لماذا تتعب المعلم بعد '),
(24753, 'Mark', 41, 5, 36, ' فسمع يسوع لوقته الكلمة التي قيلت ، فقال لرئيس المجمع : لا تخف آمن فقط '),
(24754, 'Mark', 41, 5, 37, ' ولم يدع أحدا يتبعه إلا بطرس ويعقوب ، ويوحنا أخا يعقوب '),
(24755, 'Mark', 41, 5, 38, ' فجاء إلى بيت رئيس المجمع ورأى ضجيجا . يبكون ويولولون كثيرا '),
(24756, 'Mark', 41, 5, 39, ' فدخل وقال لهم : لماذا تضجون وتبكون ؟ لم تمت الصبية لكنها نائمة '),
(24757, 'Mark', 41, 5, 40, ' فضحكوا عليه . أما هو فأخرج الجميع ، وأخذ أبا الصبية وأمها والذين معه ودخل حيث كانت الصبية مضطجعة '),
(24758, 'Mark', 41, 5, 41, ' وأمسك بيد الصبية وقال لها : طليثا ، قومي . الذي تفسيره : يا صبية ، لك أقول : قومي '),
(24759, 'Mark', 41, 5, 42, ' وللوقت قامت الصبية ومشت ، لأنها كانت ابنة اثنتي عشرة سنة . فبهتوا بهتا عظيما '),
(24760, 'Mark', 41, 5, 43, ' فأوصاهم كثيرا أن لا يعلم أحد بذلك . وقال أن تعطى لتأكل '),
(24761, 'Mark', 41, 6, 1, ' وخرج من هناك وجاء إلى وطنه وتبعه تلاميذه '),
(24762, 'Mark', 41, 6, 2, ' ولما كان السبت ، ابتدأ يعلم في المجمع . وكثيرون إذ سمعوا بهتوا قائلين : من أين لهذا هذه ؟ وما هذه الحكمة التي أعطيت له حتى تجري على يديه قوات مثل هذه '),
(24763, 'Mark', 41, 6, 3, ' أليس هذا هو النجار ابن مريم ، وأخو يعقوب ويوسي ويهوذا وسمعان ؟ أوليست أخواته ههنا عندنا ؟ فكانوا يعثرون به '),
(24764, 'Mark', 41, 6, 4, ' فقال لهم يسوع : ليس نبي بلا كرامة إلا في وطنه وبين أقربائه وفي بيته '),
(24765, 'Mark', 41, 6, 5, ' ولم يقدر أن يصنع هناك ولا قوة واحدة ، غير أنه وضع يديه على مرضى قليلين فشفاهم '),
(24766, 'Mark', 41, 6, 6, ' وتعجب من عدم إيمانهم . وصار يطوف القرى المحيطة يعلم '),
(24767, 'Mark', 41, 6, 7, ' ودعا الاثني عشر وابتدأ يرسلهم اثنين اثنين ، وأعطاهم سلطانا على الأرواح النجسة '),
(24768, 'Mark', 41, 6, 8, ' وأوصاهم أن لا يحملوا شيئا للطريق غير عصا فقط ، لا مزودا ولا خبزا ولا نحاسا في المنطقة '),
(24769, 'Mark', 41, 6, 9, ' بل يكونوا مشدودين بنعال ، ولا يلبسوا ثوبين '),
(24770, 'Mark', 41, 6, 10, ' وقال لهم : حيثما دخلتم بيتا فأقيموا فيه حتى تخرجوا من هناك '),
(24771, 'Mark', 41, 6, 11, ' وكل من لا يقبلكم ولا يسمع لكم ، فاخرجوا من هناك وانفضوا التراب الذي تحت أرجلكم شهادة عليهم . الحق أقول لكم : ستكون لأرض سدوم وعمورة يوم الدين حالة أكثر احتمالا مما لتلك المدينة '),
(24772, 'Mark', 41, 6, 12, ' فخرجوا وصاروا يكرزون أن يتوبوا '),
(24773, 'Mark', 41, 6, 13, ' وأخرجوا شياطين كثيرة ، ودهنوا بزيت مرضى كثيرين فشفوهم '),
(24774, 'Mark', 41, 6, 14, ' فسمع هيرودس الملك ، لأن اسمه صار مشهورا . وقال : إن يوحنا المعمدان قام من الأموات ولذلك تعمل به القوات '),
(24775, 'Mark', 41, 6, 15, ' قال آخرون : إنه إيليا . وقال آخرون : إنه نبي أو كأحد الأنبياء '),
(24776, 'Mark', 41, 6, 16, ' ولكن لما سمع هيرودس قال : هذا هو يوحنا الذي قطعت أنا رأسه . إنه قام من الأموات '),
(24777, 'Mark', 41, 6, 17, ' لأن هيرودس نفسه كان قد أرسل وأمسك يوحنا وأوثقه في السجن من أجل هيروديا امرأة فيلبس أخيه ، إذ كان قد تزوج بها '),
(24778, 'Mark', 41, 6, 18, ' لأن يوحنا كان يقول لهيرودس : لا يحل أن تكون لك امرأة أخيك '),
(24779, 'Mark', 41, 6, 19, ' فحنقت هيروديا عليه ، وأرادت أن تقتله ولم تقدر '),
(24780, 'Mark', 41, 6, 20, ' لأن هيرودس كان يهاب يوحنا عالما أنه رجل بار وقديس ، وكان يحفظه . وإذ سمعه ، فعل كثيرا ، وسمعه بسرور '),
(24781, 'Mark', 41, 6, 21, ' وإذ كان يوم موافق ، لما صنع هيرودس في مولده عشاء لعظمائه وقواد الألوف ووجوه الجليل '),
(24782, 'Mark', 41, 6, 22, ' دخلت ابنة هيروديا ورقصت ، فسرت هيرودس والمتكئين معه . فقال الملك للصبية : مهما أردت اطلبي مني فأعطيك '),
(24783, 'Mark', 41, 6, 23, ' وأقسم لها أن مهما طلبت مني لأعطينك حتى نصف مملكتي '),
(24784, 'Mark', 41, 6, 24, ' فخرجت وقالت لأمها : ماذا أطلب ؟ فقالت : رأس يوحنا المعمدان '),
(24785, 'Mark', 41, 6, 25, ' فدخلت للوقت بسرعة إلى الملك وطلبت قائلة : أريد أن تعطيني حالا رأس يوحنا المعمدان على طبق '),
(24786, 'Mark', 41, 6, 26, ' فحزن الملك جدا . ولأجل الأقسام والمتكئين لم يرد أن يردها '),
(24787, 'Mark', 41, 6, 27, ' فللوقت أرسل الملك سيافا وأمر أن يؤتى برأسه '),
(24788, 'Mark', 41, 6, 28, ' فمضى وقطع رأسه في السجن . وأتى برأسه على طبق وأعطاه للصبية ، والصبية أعطته لأمها '),
(24789, 'Mark', 41, 6, 29, ' ولما سمع تلاميذه ، جاءوا ورفعوا جثته ووضعوها في قبر '),
(24790, 'Mark', 41, 6, 30, ' واجتمع الرسل إلى يسوع وأخبروه بكل شيء ، كل ما فعلوا وكل ما علموا '),
(24791, 'Mark', 41, 6, 31, ' فقال لهم : تعالوا أنتم منفردين إلى موضع خلاء واستريحوا قليلا . لأن القادمين والذاهبين كانوا كثيرين ، ولم تتيسر لهم فرصة للأكل '),
(24792, 'Mark', 41, 6, 32, ' فمضوا في السفينة إلى موضع خلاء منفردين '),
(24793, 'Mark', 41, 6, 33, ' فرآهم الجموع منطلقين ، وعرفه كثيرون . فتراكضوا إلى هناك من جميع المدن مشاة ، وسبقوهم واجتمعوا إليه '),
(24794, 'Mark', 41, 6, 34, ' فلما خرج يسوع رأى جمعا كثيرا ، فتحنن عليهم إذ كانوا كخراف لا راعي لها ، فابتدأ يعلمهم كثيرا '),
(24795, 'Mark', 41, 6, 35, ' وبعد ساعات كثيرة تقدم إليه تلاميذه قائلين : الموضع خلاء والوقت مضى '),
(24796, 'Mark', 41, 6, 36, ' اصرفهم لكي يمضوا إلى الضياع والقرى حوالينا ويبتاعوا لهم خبزا ، لأن ليس عندهم ما يأكلون '),
(24797, 'Mark', 41, 6, 37, ' فأجاب وقال لهم : أعطوهم أنتم ليأكلوا . فقالوا له : أنمضي ونبتاع خبزا بمئتي دينار ونعطيهم ليأكلوا '),
(24798, 'Mark', 41, 6, 38, ' فقال لهم : كم رغيفا عندكم ؟ اذهبوا وانظروا . ولما علموا قالوا : خمسة وسمكتان '),
(24799, 'Mark', 41, 6, 39, ' فأمرهم أن يجعلوا الجميع يتكئون رفاقا رفاقا على العشب الأخضر '),
(24800, 'Mark', 41, 6, 40, ' فاتكأوا صفوفا صفوفا : مئة مئة وخمسين خمسين '),
(24801, 'Mark', 41, 6, 41, ' فأخذ الأرغفة الخمسة والسمكتين ، ورفع نظره نحو السماء ، وبارك ثم كسر الأرغفة ، وأعطى تلاميذه ليقدموا إليهم ، وقسم السمكتين للجميع '),
(24802, 'Mark', 41, 6, 42, ' فأكل الجميع وشبعوا '),
(24803, 'Mark', 41, 6, 43, ' ثم رفعوا من الكسر اثنتي عشرة قفة مملوة ، ومن السمك '),
(24804, 'Mark', 41, 6, 44, ' وكان الذين أكلوا من الأرغفة نحو خمسة آلاف رجل '),
(24805, 'Mark', 41, 6, 45, ' وللوقت ألزم تلاميذه أن يدخلوا السفينة ويسبقوا إلى العبر ، إلى بيت صيدا ، حتى يكون قد صرف الجمع '),
(24806, 'Mark', 41, 6, 46, ' وبعدما ودعهم مضى إلى الجبل ليصلي '),
(24807, 'Mark', 41, 6, 47, ' ولما صار المساء كانت السفينة في وسط البحر ، وهو على البر وحده '),
(24808, 'Mark', 41, 6, 48, ' ورآهم معذبين في الجذف ، لأن الريح كانت ضدهم . ونحو الهزيع الرابع من الليل أتاهم ماشيا على البحر ، وأراد أن يتجاوزهم '),
(24809, 'Mark', 41, 6, 49, ' فلما رأوه ماشيا على البحر ظنوه خيالا ، فصرخوا '),
(24810, 'Mark', 41, 6, 50, ' لأن الجميع رأوه واضطربوا . فللوقت كلمهم وقال لهم : ثقوا أنا هو . لا تخافوا '),
(24811, 'Mark', 41, 6, 51, ' فصعد إليهم إلى السفينة فسكنت الريح ، فبهتوا وتعجبوا في أنفسهم جدا إلى الغاية '),
(24812, 'Mark', 41, 6, 52, ' لأنهم لم يفهموا بالأرغفة إذ كانت قلوبهم غليظة '),
(24813, 'Mark', 41, 6, 53, ' فلما عبروا جاءوا إلى أرض جنيسارت وأرسوا '),
(24814, 'Mark', 41, 6, 54, ' ولما خرجوا من السفينة للوقت عرفوه '),
(24815, 'Mark', 41, 6, 55, ' فطافوا جميع تلك الكورة المحيطة ، وابتدأوا يحملون المرضى على أسرة إلى حيث سمعوا أنه هناك '),
(24816, 'Mark', 41, 6, 56, ' وحيثما دخل إلى قرى أو مدن أو ضياع ، وضعوا المرضى في الأسواق ، وطلبوا إليه أن يلمسوا ولو هدب ثوبه . وكل من لمسه شفي. '),
(24817, 'Mark', 41, 7, 1, ' واجتمع إليه الفريسيون وقوم من الكتبة قادمين من أورشليم '),
(24818, 'Mark', 41, 7, 2, ' ولما رأوا بعضا من تلاميذه يأكلون خبزا بأيد دنسة ، أي غير مغسولة ، لاموا '),
(24819, 'Mark', 41, 7, 3, ' لأن الفريسيين وكل اليهود إن لم يغسلوا أيديهم باعتناء ، لا يأكلون ، متمسكين بتقليد الشيوخ '),
(24820, 'Mark', 41, 7, 4, ' ومن السوق إن لم يغتسلوا لا يأكلون . وأشياء أخرى كثيرة تسلموها للتمسك بها ، من غسل كؤوس وأباريق وآنية نحاس وأسرة '),
(24821, 'Mark', 41, 7, 5, ' ثم سأله الفريسيون والكتبة : لماذا لا يسلك تلاميذك حسب تقليد الشيوخ ، بل يأكلون خبزا بأيد غير مغسولة '),
(24822, 'Mark', 41, 7, 6, ' فأجاب وقال لهم : حسنا تنبأ إشعياء عنكم أنتم المرائين كما هو مكتوب : هذا الشعب يكرمني بشفتيه ، وأما قلبه فمبتعد عني بعيدا، '),
(24823, 'Mark', 41, 7, 7, ' وباطلا يعبدونني وهم يعلمون تعاليم هي وصايا الناس '),
(24824, 'Mark', 41, 7, 8, ' لأنكم تركتم وصية الله وتتمسكون بتقليد الناس : غسل الأباريق والكؤوس ، وأمورا أخر كثيرة مثل هذه تفعلون '),
(24825, 'Mark', 41, 7, 9, ' ثم قال لهم : حسنا رفضتم وصية الله لتحفظوا تقليدكم '),
(24826, 'Mark', 41, 7, 10, ' لأن موسى قال : أكرم أباك وأمك ، ومن يشتم أبا أو أما فليمت موتا '),
(24827, 'Mark', 41, 7, 11, ' وأما أنتم فتقولون : إن قال إنسان لأبيه أو أمه : قربان ، أي هدية ، هو الذي تنتفع به مني '),
(24828, 'Mark', 41, 7, 12, ' فلا تدعونه في ما بعد يفعل شيئا لأبيه أو أمه '),
(24829, 'Mark', 41, 7, 13, ' مبطلين كلام الله بتقليدكم الذي سلمتموه . وأمورا كثيرة مثل هذه تفعلون '),
(24830, 'Mark', 41, 7, 14, ' ثم دعا كل الجمع وقال لهم : اسمعوا مني كلكم وافهموا '),
(24831, 'Mark', 41, 7, 15, ' ليس شيء من خارج الإنسان إذا دخل فيه يقدر أن ينجسه ، لكن الأشياء التي تخرج منه هي التي تنجس الإنسان '),
(24832, 'Mark', 41, 7, 16, ' إن كان لأحد أذنان للسمع ، فليسمع '),
(24833, 'Mark', 41, 7, 17, ' ولما دخل من عند الجمع إلى البيت ، سأله تلاميذه عن المثل '),
(24834, 'Mark', 41, 7, 18, ' فقال لهم : أفأنتم أيضا هكذا غير فاهمين ؟ أما تفهمون أن كل ما يدخل الإنسان من خارج لا يقدر أن ينجسه '),
(24835, 'Mark', 41, 7, 19, ' لأنه لا يدخل إلى قلبه بل إلى الجوف ، ثم يخرج إلى الخلاء ، وذلك يطهر كل الأطعمة '),
(24836, 'Mark', 41, 7, 20, ' ثم قال : إن الذي يخرج من الإنسان ذلك ينجس الإنسان '),
(24837, 'Mark', 41, 7, 21, ' لأنه من الداخل ، من قلوب الناس ، تخرج الأفكار الشريرة : زنى ، فسق ، قتل '),
(24838, 'Mark', 41, 7, 22, ' سرقة ، طمع ، خبث ، مكر ، عهارة ، عين شريرة ، تجديف ، كبرياء ، جهل '),
(24839, 'Mark', 41, 7, 23, ' جميع هذه الشرور تخرج من الداخل وتنجس الإنسان '),
(24840, 'Mark', 41, 7, 24, ' ثم قام من هناك ومضى إلى تخوم صور وصيداء ، ودخل بيتا وهو يريد أن لا يعلم أحد ، فلم يقدر أن يختفي '),
(24841, 'Mark', 41, 7, 25, ' لأن امرأة كان بابنتها روح نجس سمعت به ، فأتت وخرت عند قدميه '),
(24842, 'Mark', 41, 7, 26, ' وكانت الامرأة أممية ، وفي جنسها فينيقية سورية . فسألته أن يخرج الشيطان من ابنتها '),
(24843, 'Mark', 41, 7, 27, ' وأما يسوع فقال لها : دعي البنين أولا يشبعون ، لأنه ليس حسنا أن يؤخذ خبز البنين ويطرح للكلاب '),
(24844, 'Mark', 41, 7, 28, ' فأجابت وقالت له : نعم ، يا سيد والكلاب أيضا تحت المائدة تأكل من فتات البنين '),
(24845, 'Mark', 41, 7, 29, ' فقال لها : لأجل هذه الكلمة ، اذهبي . قد خرج الشيطان من ابنتك '),
(24846, 'Mark', 41, 7, 30, ' فذهبت إلى بيتها ووجدت الشيطان قد خرج ، والابنة مطروحة على الفراش '),
(24847, 'Mark', 41, 7, 31, ' ثم خرج أيضا من تخوم صور وصيداء ، وجاء إلى بحر الجليل في وسط حدود المدن العشر '),
(24848, 'Mark', 41, 7, 32, ' وجاءوا إليه بأصم أعقد ، وطلبوا إليه أن يضع يده عليه '),
(24849, 'Mark', 41, 7, 33, ' فأخذه من بين الجمع على ناحية ، ووضع أصابعه في أذنيه وتفل ولمس لسانه '),
(24850, 'Mark', 41, 7, 34, ' ورفع نظره نحو السماء ، وأن وقال له : إفثا . أي انفتح '),
(24851, 'Mark', 41, 7, 35, ' وللوقت انفتحت أذناه ، وانحل رباط لسانه ، وتكلم مستقيما '),
(24852, 'Mark', 41, 7, 36, ' فأوصاهم أن لا يقولوا لأحد . ولكن على قدر ما أوصاهم كانوا ينادون أكثر كثيرا '),
(24853, 'Mark', 41, 7, 37, ' وبهتوا إلى الغاية قائلين : إنه عمل كل شيء حسنا جعل الصم يسمعون والخرس يتكلمون '),
(24854, 'Mark', 41, 8, 1, ' في تلك الأيام إذ كان الجمع كثيرا جدا ، ولم يكن لهم ما يأكلون ، دعا يسوع تلاميذه وقال لهم '),
(24855, 'Mark', 41, 8, 2, ' إني أشفق على الجمع ، لأن الآن لهم ثلاثة أيام يمكثون معي وليس لهم ما يأكلون '),
(24856, 'Mark', 41, 8, 3, ' وإن صرفتهم إلى بيوتهم صائمين يخورون في الطريق ، لأن قوما منهم جاءوا من بعيد '),
(24857, 'Mark', 41, 8, 4, ' فأجابه تلاميذه : من أين يستطيع أحد أن يشبع هؤلاء خبزا هنا في البرية '),
(24858, 'Mark', 41, 8, 5, ' فسألهم : كم عندكم من الخبز ؟ فقالوا : سبعة '),
(24859, 'Mark', 41, 8, 6, ' فأمر الجمع أن يتكئوا على الأرض ، وأخذ السبع خبزات وشكر وكسر وأعطى تلاميذه ليقدموا ، فقدموا إلى الجمع '),
(24860, 'Mark', 41, 8, 7, ' وكان معهم قليل من صغار السمك ، فبارك وقال أن يقدموا هذه أيضا '),
(24861, 'Mark', 41, 8, 8, ' فأكلوا وشبعوا . ثم رفعوا فضلات الكسر : سبعة سلال '),
(24862, 'Mark', 41, 8, 9, ' وكان الآكلون نحو أربعة آلاف . ثم صرفهم '),
(24863, 'Mark', 41, 8, 10, ' وللوقت دخل السفينة مع تلاميذه وجاء إلى نواحي دلمانوثة '),
(24864, 'Mark', 41, 8, 11, ' فخرج الفريسيون وابتدأوا يحاورونه طالبين منه آية من السماء ، لكي يجربوه '),
(24865, 'Mark', 41, 8, 12, ' فتنهد بروحه وقال : لماذا يطلب هذا الجيل آية ؟ الحق أقول لكم : لن يعطى هذا الجيل آية '),
(24866, 'Mark', 41, 8, 13, ' ثم تركهم ودخل أيضا السفينة ومضى إلى العبر '),
(24867, 'Mark', 41, 8, 14, ' ونسوا أن يأخذوا خبزا ، ولم يكن معهم في السفينة إلا رغيف واحد '),
(24868, 'Mark', 41, 8, 15, ' وأوصاهم قائلا : انظروا وتحرزوا من خمير الفريسيين وخمير هيرودس '),
(24869, 'Mark', 41, 8, 16, ' ففكروا قائلين بعضهم لبعض : ليس عندنا خبز '),
(24870, 'Mark', 41, 8, 17, ' فعلم يسوع وقال لهم : لماذا تفكرون أن ليس عندكم خبز ؟ ألا تشعرون بعد ولا تفهمون ؟ أحتى الآن قلوبكم غليظة '),
(24871, 'Mark', 41, 8, 18, ' ألكم أعين ولا تبصرون ، ولكم آذان ولا تسمعون ، ولا تذكرون '),
(24872, 'Mark', 41, 8, 19, ' حين كسرت الأرغفة الخمسة للخمسة الآلاف ، كم قفة مملوة كسرا رفعتم ؟ قالوا له : اثنتي عشرة '),
(24873, 'Mark', 41, 8, 20, ' وحين السبعة للأربعة الآلاف ، كم سل كسر مملوا رفعتم ؟ قالوا : سبعة '),
(24874, 'Mark', 41, 8, 21, ' فقال لهم : كيف لا تفهمون '),
(24875, 'Mark', 41, 8, 22, ' وجاء إلى بيت صيدا ، فقدموا إليه أعمى وطلبوا إليه أن يلمسه '),
(24876, 'Mark', 41, 8, 23, ' فأخذ بيد الأعمى وأخرجه إلى خارج القرية ، وتفل في عينيه ، ووضع يديه عليه وسأله : هل أبصر شيئا '),
(24877, 'Mark', 41, 8, 24, ' فتطلع وقال : أبصر الناس كأشجار يمشون '),
(24878, 'Mark', 41, 8, 25, ' ثم وضع يديه أيضا على عينيه ، وجعله يتطلع . فعاد صحيحا وأبصر كل إنسان جليا '),
(24879, 'Mark', 41, 8, 26, ' فأرسله إلى بيته قائلا : لا تدخل القرية ، ولا تقل لأحد في القرية '),
(24880, 'Mark', 41, 8, 27, ' ثم خرج يسوع وتلاميذه إلى قرى قيصرية فيلبس . وفي الطريق سأل تلاميذه قائلا لهم : من يقول الناس : إني أنا '),
(24881, 'Mark', 41, 8, 28, ' فأجابوا : يوحنا المعمدان . وآخرون : إيليا . وآخرون : واحد من الأنبياء '),
(24882, 'Mark', 41, 8, 29, ' فقال لهم : وأنتم ، من تقولون : إني أنا ؟ فأجاب بطرس وقال له : أنت المسيح '),
(24883, 'Mark', 41, 8, 30, ' فانتهرهم كي لا يقولوا لأحد عنه '),
(24884, 'Mark', 41, 8, 31, ' وابتدأ يعلمهم أن ابن الإنسان ينبغي أن يتألم كثيرا ، ويرفض من الشيوخ ورؤساء الكهنة والكتبة ، ويقتل ، وبعد ثلاثة أيام يقوم '),
(24885, 'Mark', 41, 8, 32, ' وقال القول علانية . فأخذه بطرس إليه وابتدأ ينتهره '),
(24886, 'Mark', 41, 8, 33, ' فالتفت وأبصر تلاميذه ، فانتهر بطرس قائلا : اذهب عني يا شيطان لأنك لا تهتم بما لله لكن بما للناس '),
(24887, 'Mark', 41, 8, 34, ' ودعا الجمع مع تلاميذه وقال لهم : من أراد أن يأتي ورائي فلينكر نفسه ويحمل صليبه ويتبعني '),
(24888, 'Mark', 41, 8, 35, ' فإن من أراد أن يخلص نفسه يهلكها ، ومن يهلك نفسه من أجلي ومن أجل الإنجيل فهو يخلصها '),
(24889, 'Mark', 41, 8, 36, ' لأنه ماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه '),
(24890, 'Mark', 41, 8, 37, ' أو ماذا يعطي الإنسان فداء عن نفسه '),
(24891, 'Mark', 41, 8, 38, ' لأن من استحى بي وبكلامي في هذا الجيل الفاسق الخاطئ ، فإن ابن الإنسان يستحي به متى جاء بمجد أبيه مع الملائكة القديسين '),
(24892, 'Mark', 41, 9, 1, ' وقال لهم : الحق أقول لكم : إن من القيام ههنا قوما لا يذوقون الموت حتى يروا ملكوت الله قد أتى بقوة '),
(24893, 'Mark', 41, 9, 2, ' وبعد ستة أيام أخذ يسوع بطرس ويعقوب ويوحنا ، وصعد بهم إلى جبل عال منفردين وحدهم . وتغيرت هيئته قدامهم '),
(24894, 'Mark', 41, 9, 3, ' وصارت ثيابه تلمع بيضاء جدا كالثلج ، لا يقدر قصار على الأرض أن يبيض مثل ذلك '),
(24895, 'Mark', 41, 9, 4, ' وظهر لهم إيليا مع موسى ، وكانا يتكلمان مع يسوع '),
(24896, 'Mark', 41, 9, 5, ' فجعل بطرس يقول ليسوع : يا سيدي ، جيد أن نكون ههنا . فلنصنع ثلاث مظال : لك واحدة ، ولموسى واحدة ، ولإيليا واحدة '),
(24897, 'Mark', 41, 9, 6, ' لأنه لم يكن يعلم ما يتكلم به إذ كانوا مرتعبين '),
(24898, 'Mark', 41, 9, 7, ' وكانت سحابة تظللهم . فجاء صوت من السحابة قائلا : هذا هو ابني الحبيب . له اسمعوا '),
(24899, 'Mark', 41, 9, 8, ' فنظروا حولهم بغتة ولم يروا أحدا غير يسوع وحده معهم '),
(24900, 'Mark', 41, 9, 9, ' وفيما هم نازلون من الجبل ، أوصاهم أن لا يحدثوا أحدا بما أبصروا ، إلا متى قام ابن الإنسان من الأموات '),
(24901, 'Mark', 41, 9, 10, ' فحفظوا الكلمة لأنفسهم يتساءلون : ما هو القيام من الأموات '),
(24902, 'Mark', 41, 9, 11, ' فسألوه قائلين : لماذا يقول الكتبة : إن إيليا ينبغي أن يأتي أولا '),
(24903, 'Mark', 41, 9, 12, ' فأجاب وقال لهم : إن إيليا يأتي أولا ويرد كل شيء . وكيف هو مكتوب عن ابن الإنسان أن يتألم كثيرا ويرذل '),
(24904, 'Mark', 41, 9, 13, ' لكن أقول لكم : إن إيليا أيضا قد أتى ، وعملوا به كل ما أرادوا ، كما هو مكتوب عنه '),
(24905, 'Mark', 41, 9, 14, ' ولما جاء إلى التلاميذ رأى جمعا كثيرا حولهم وكتبة يحاورونهم '),
(24906, 'Mark', 41, 9, 15, ' وللوقت كل الجمع لما رأوه تحيروا ، وركضوا وسلموا عليه '),
(24907, 'Mark', 41, 9, 16, ' فسأل الكتبة : بماذا تحاورونهم '),
(24908, 'Mark', 41, 9, 17, ' فأجاب واحد من الجمع وقال : يا معلم ، قد قدمت إليك ابني به روح أخرس '),
(24909, 'Mark', 41, 9, 18, ' وحيثما أدركه يمزقه فيزبد ويصر بأسنانه وييبس . فقلت لتلاميذك أن يخرجوه فلم يقدروا '),
(24910, 'Mark', 41, 9, 19, ' فأجاب وقال لهم : أيها الجيل غير المؤمن ، إلى متى أكون معكم ؟ إلى متى أحتملكم ؟ قدموه إلي '),
(24911, 'Mark', 41, 9, 20, ' فقدموه إليه . فلما رآه للوقت صرعه الروح ، فوقع على الأرض يتمرغ ويزبد '),
(24912, 'Mark', 41, 9, 21, ' فسأل أباه : كم من الزمان منذ أصابه هذا ؟ فقال : منذ صباه '),
(24913, 'Mark', 41, 9, 22, ' وكثيرا ما ألقاه في النار وفي الماء ليهلكه . لكن إن كنت تستطيع شيئا فتحنن علينا وأعنا '),
(24914, 'Mark', 41, 9, 23, ' فقال له يسوع : إن كنت تستطيع أن تؤمن . كل شيء مستطاع للمؤمن '),
(24915, 'Mark', 41, 9, 24, ' فللوقت صرخ أبو الولد بدموع وقال : أومن يا سيد ، فأعن عدم إيماني '),
(24916, 'Mark', 41, 9, 25, ' فلما رأى يسوع أن الجمع يتراكضون ، انتهر الروح النجس قائلا له : أيها الروح الأخرس الأصم ، أنا آمرك : اخرج منه ولا تدخله أيضا '),
(24917, 'Mark', 41, 9, 26, ' فصرخ وصرعه شديدا وخرج . فصار كميت ، حتى قال كثيرون : إنه مات '),
(24918, 'Mark', 41, 9, 27, ' فأمسكه يسوع بيده وأقامه ، فقام '),
(24919, 'Mark', 41, 9, 28, ' ولما دخل بيتا سأله تلاميذه على انفراد : لماذا لم نقدر نحن أن نخرجه '),
(24920, 'Mark', 41, 9, 29, ' فقال لهم : هذا الجنس لا يمكن أن يخرج بشيء إلا بالصلاة والصوم '),
(24921, 'Mark', 41, 9, 30, ' وخرجوا من هناك واجتازوا الجليل ، ولم يرد أن يعلم أحد '),
(24922, 'Mark', 41, 9, 31, ' لأنه كان يعلم تلاميذه ويقول لهم : إن ابن الإنسان يسلم إلى أيدي الناس فيقتلونه . وبعد أن يقتل يقوم في اليوم الثالث '),
(24923, 'Mark', 41, 9, 32, ' وأما هم فلم يفهموا القول ، وخافوا أن يسألوه '),
(24924, 'Mark', 41, 9, 33, ' وجاء إلى كفرناحوم . وإذ كان في البيت سألهم : بماذا كنتم تتكالمون فيما بينكم في الطريق '),
(24925, 'Mark', 41, 9, 34, ' فسكتوا ، لأنهم تحاجوا في الطريق بعضهم مع بعض في من هو أعظم '),
(24926, 'Mark', 41, 9, 35, ' فجلس ونادى الاثني عشر وقال لهم : إذا أراد أحد أن يكون أولا فيكون آخر الكل وخادما للكل '),
(24927, 'Mark', 41, 9, 36, ' فأخذ ولدا وأقامه في وسطهم ثم احتضنه وقال لهم '),
(24928, 'Mark', 41, 9, 37, ' من قبل واحدا من أولاد مثل هذا باسمي يقبلني ، ومن قبلني فليس يقبلني أنا بل الذي أرسلني '),
(24929, 'Mark', 41, 9, 38, ' فأجابه يوحنا قائلا : يا معلم ، رأينا واحدا يخرج شياطين باسمك وهو ليس يتبعنا ، فمنعناه لأنه ليس يتبعنا '),
(24930, 'Mark', 41, 9, 39, ' فقال يسوع : لا تمنعوه ، لأنه ليس أحد يصنع قوة باسمي ويستطيع سريعا أن يقول علي شرا '),
(24931, 'Mark', 41, 9, 40, ' لأن من ليس علينا فهو معنا '),
(24932, 'Mark', 41, 9, 41, ' لأن من سقاكم كأس ماء باسمي لأنكم للمسيح ، فالحق أقول لكم : إنه لا يضيع أجره '),
(24933, 'Mark', 41, 9, 42, ' ومن أعثر أحد الصغار المؤمنين بي ، فخير له لو طوق عنقه بحجر رحى وطرح في البحر '),
(24934, 'Mark', 41, 9, 43, ' وإن أعثرتك يدك فاقطعها . خير لك أن تدخل الحياة أقطع من أن تكون لك يدان وتمضي إلى جهنم ، إلى النار التي لا تطفأ '),
(24935, 'Mark', 41, 9, 44, ' حيث دودهم لا يموت والنار لا تطفأ '),
(24936, 'Mark', 41, 9, 45, ' وإن أعثرتك رجلك فاقطعها . خير لك أن تدخل الحياة أعرج من أن تكون لك رجلان وتطرح في جهنم في النار التي لا تطفأ '),
(24937, 'Mark', 41, 9, 46, ' حيث دودهم لا يموت والنار لا تطفأ '),
(24938, 'Mark', 41, 9, 47, ' وإن أعثرتك عينك فاقلعها . خير لك أن تدخل ملكوت الله أعور من أن تكون لك عينان وتطرح في جهنم النار '),
(24939, 'Mark', 41, 9, 48, ' حيث دودهم لا يموت والنار لا تطفأ '),
(24940, 'Mark', 41, 9, 49, ' لأن كل واحد يملح بنار ، وكل ذبيحة تملح بملح '),
(24941, 'Mark', 41, 9, 50, ' الملح جيد . ولكن إذا صار الملح بلا ملوحة ، فبماذا تصلحونه ؟ ليكن لكم في أنفسكم ملح ، وسالموا بعضكم بعضا '),
(24942, 'Mark', 41, 10, 1, ' وقام من هناك وجاء إلى تخوم اليهودية من عبر الأردن . فاجتمع إليه جموع أيضا ، وكعادته كان أيضا يعلمهم '),
(24943, 'Mark', 41, 10, 2, ' فتقدم الفريسيون وسألوه : هل يحل للرجل أن يطلق امرأته ؟ ليجربوه '),
(24944, 'Mark', 41, 10, 3, ' فأجاب وقال لهم : بماذا أوصاكم موسى '),
(24945, 'Mark', 41, 10, 4, ' فقالوا : موسى أذن أن يكتب كتاب طلاق ، فتطلق '),
(24946, 'Mark', 41, 10, 5, ' فأجاب يسوع وقال لهم : من أجل قساوة قلوبكم كتب لكم هذه الوصية '),
(24947, 'Mark', 41, 10, 6, ' ولكن من بدء الخليقة ، ذكرا وأنثى خلقهما الله '),
(24948, 'Mark', 41, 10, 7, ' من أجل هذا يترك الرجل أباه وأمه ويلتصق بامرأته '),
(24949, 'Mark', 41, 10, 8, ' ويكون الاثنان جسدا واحدا . إذا ليسا بعد اثنين بل جسد واحد '),
(24950, 'Mark', 41, 10, 9, ' فالذي جمعه الله لا يفرقه إنسان '),
(24951, 'Mark', 41, 10, 10, ' ثم في البيت سأله تلاميذه أيضا عن ذلك '),
(24952, 'Mark', 41, 10, 11, ' فقال لهم : من طلق امرأته وتزوج بأخرى يزني عليها '),
(24953, 'Mark', 41, 10, 12, ' وإن طلقت امرأة زوجها وتزوجت بآخر تزني '),
(24954, 'Mark', 41, 10, 13, ' وقدموا إليه أولادا لكي يلمسهم . وأما التلاميذ فانتهروا الذين قدموهم '),
(24955, 'Mark', 41, 10, 14, ' فلما رأى يسوع ذلك اغتاظ وقال لهم : دعوا الأولاد يأتون إلي ولا تمنعوهم ، لأن لمثل هؤلاء ملكوت الله '),
(24956, 'Mark', 41, 10, 15, ' الحق أقول لكم : من لا يقبل ملكوت الله مثل ولد فلن يدخله '),
(24957, 'Mark', 41, 10, 16, ' فاحتضنهم ووضع يديه عليهم وباركهم '),
(24958, 'Mark', 41, 10, 17, ' وفيما هو خارج إلى الطريق ، ركض واحد وجثا له وسأله : أيها المعلم الصالح ، ماذا أعمل لأرث الحياة الأبدية '),
(24959, 'Mark', 41, 10, 18, ' فقال له يسوع : لماذا تدعوني صالحا ؟ ليس أحد صالحا إلا واحد وهو الله '),
(24960, 'Mark', 41, 10, 19, ' أنت تعرف الوصايا : لا تزن . لا تقتل . لا تسرق . لا تشهد بالزور . لا تسلب . أكرم أباك وأمك '),
(24961, 'Mark', 41, 10, 20, ' فأجاب وقال له : يا معلم ، هذه كلها حفظتها منذ حداثتي '),
(24962, 'Mark', 41, 10, 21, ' فنظر إليه يسوع وأحبه ، وقال له : يعوزك شيء واحد : اذهب بع كل ما لك وأعط الفقراء ، فيكون لك كنز في السماء ، وتعال اتبعني حاملا الصليب '),
(24963, 'Mark', 41, 10, 22, ' فاغتم على القول ومضى حزينا ، لأنه كان ذا أموال كثيرة '),
(24964, 'Mark', 41, 10, 23, ' فنظر يسوع حوله وقال لتلاميذه : ما أعسر دخول ذوي الأموال إلى ملكوت الله '),
(24965, 'Mark', 41, 10, 24, ' فتحير التلاميذ من كلامه . فأجاب يسوع أيضا وقال لهم : يا بني ، ما أعسر دخول المتكلين على الأموال إلى ملكوت الله '),
(24966, 'Mark', 41, 10, 25, ' مرور جمل من ثقب إبرة أيسر من أن يدخل غني إلى ملكوت الله '),
(24967, 'Mark', 41, 10, 26, ' فبهتوا إلى الغاية قائلين بعضهم لبعض : فمن يستطيع أن يخلص '),
(24968, 'Mark', 41, 10, 27, ' فنظر إليهم يسوع وقال : عند الناس غير مستطاع ، ولكن ليس عند الله ، لأن كل شيء مستطاع عند الله '),
(24969, 'Mark', 41, 10, 28, ' وابتدأ بطرس يقول له : ها نحن قد تركنا كل شيء وتبعناك '),
(24970, 'Mark', 41, 10, 29, ' فأجاب يسوع وقال : الحق أقول لكم : ليس أحد ترك بيتا أو إخوة أو أخوات أو أبا أو أما أو امرأة أو أولادا أو حقولا ، لأجلي ولأجل الإنجيل '),
(24971, 'Mark', 41, 10, 30, ' إلا ويأخذ مئة ضعف الآن في هذا الزمان ، بيوتا وإخوة وأخوات وأمهات وأولادا وحقولا ، مع اضطهادات ، وفي الدهر الآتي الحياة الأبدية '),
(24972, 'Mark', 41, 10, 31, ' ولكن كثيرون أولون يكونون آخرين ، والآخرون أولين '),
(24973, 'Mark', 41, 10, 32, ' وكانوا في الطريق صاعدين إلى أورشليم ويتقدمهم يسوع ، وكانوا يتحيرون . وفيما هم يتبعون كانوا يخافون . فأخذ الاثني عشر أيضا وابتدأ يقول لهم عما سيحدث له '),
(24974, 'Mark', 41, 10, 33, ' ها نحن صاعدون إلى أورشليم ، وابن الإنسان يسلم إلى رؤساء الكهنة والكتبة ، فيحكمون عليه بالموت ، ويسلمونه إلى الأمم '),
(24975, 'Mark', 41, 10, 34, ' فيهزأون به ويجلدونه ويتفلون عليه ويقتلونه ، وفي اليوم الثالث يقوم '),
(24976, 'Mark', 41, 10, 35, ' وتقدم إليه يعقوب ويوحنا ابنا زبدي قائلين : يا معلم ، نريد أن تفعل لنا كل ما طلبنا '),
(24977, 'Mark', 41, 10, 36, ' فقال لهما : ماذا تريدان أن أفعل لكما '),
(24978, 'Mark', 41, 10, 37, ' فقالا له : أعطنا أن نجلس واحد عن يمينك والآخر عن يسارك في مجدك '),
(24979, 'Mark', 41, 10, 38, ' فقال لهما يسوع : لستما تعلمان ما تطلبان . أتستطيعان أن تشربا الكأس التي أشربها أنا ، وأن تصطبغا بالصبغة التي أصطبغ بها أنا '),
(24980, 'Mark', 41, 10, 39, ' فقالا له : نستطيع . فقال لهما يسوع : أما الكأس التي أشربها أنا فتشربانها ، وبالصبغة التي أصطبغ بها أنا تصطبغان '),
(24981, 'Mark', 41, 10, 40, ' وأما الجلوس عن يميني وعن يساري فليس لي أن أعطيه إلا للذين أعد لهم '),
(24982, 'Mark', 41, 10, 41, ' ولما سمع العشرة ابتدأوا يغتاظون من أجل يعقوب ويوحنا '),
(24983, 'Mark', 41, 10, 42, ' فدعاهم يسوع وقال لهم : أنتم تعلمون أن الذين يحسبون رؤساء الأمم يسودونهم ، وأن عظماءهم يتسلطون عليهم '),
(24984, 'Mark', 41, 10, 43, ' فلا يكون هكذا فيكم . بل من أراد أن يصير فيكم عظيما ، يكون لكم خادما '),
(24985, 'Mark', 41, 10, 44, ' ومن أراد أن يصير فيكم أولا ، يكون للجميع عبدا '),
(24986, 'Mark', 41, 10, 45, ' لأن ابن الإنسان أيضا لم يأت ليخدم بل ليخدم وليبذل نفسه فدية عن كثيرين '),
(24987, 'Mark', 41, 10, 46, ' وجاءوا إلى أريحا . وفيما هو خارج من أريحا مع تلاميذه وجمع غفير ، كان بارتيماوس الأعمى ابن تيماوس جالسا على الطريق يستعطي '),
(24988, 'Mark', 41, 10, 47, ' فلما سمع أنه يسوع الناصري ، ابتدأ يصرخ ويقول : يا يسوع ابن داود ، ارحمني '),
(24989, 'Mark', 41, 10, 48, ' فانتهره كثيرون ليسكت ، فصرخ أكثر كثيرا : يا ابن داود ، ارحمني '),
(24990, 'Mark', 41, 10, 49, ' فوقف يسوع وأمر أن ينادى . فنادوا الأعمى قائلين له : ثق قم هوذا يناديك '),
(24991, 'Mark', 41, 10, 50, ' فطرح رداءه وقام وجاء إلى يسوع '),
(24992, 'Mark', 41, 10, 51, ' فأجاب يسوع وقال له : ماذا تريد أن أفعل بك ؟ فقال له الأعمى : يا سيدي ، أن أبصر '),
(24993, 'Mark', 41, 10, 52, ' فقال له يسوع : اذهب . إيمانك قد شفاك . فللوقت أبصر ، وتبع يسوع في الطريق '),
(24994, 'Mark', 41, 11, 1, ' ولما قربوا من أورشليم إلى بيت فاجي وبيت عنيا ، عند جبل الزيتون ، أرسل اثنين من تلاميذه '),
(24995, 'Mark', 41, 11, 2, ' وقال لهما : اذهبا إلى القرية التي أمامكما ، فللوقت وأنتما داخلان إليها تجدان جحشا مربوطا لم يجلس عليه أحد من الناس . فحلاه وأتيا به '),
(24996, 'Mark', 41, 11, 3, ' وإن قال لكما أحد : لماذا تفعلان هذا ؟ فقولا : الرب محتاج إليه . فللوقت يرسله إلى هنا '),
(24997, 'Mark', 41, 11, 4, ' فمضيا ووجدا الجحش مربوطا عند الباب خارجا على الطريق ، فحلاه '),
(24998, 'Mark', 41, 11, 5, ' فقال لهما قوم من القيام هناك : ماذا تفعلان ، تحلان الجحش '),
(24999, 'Mark', 41, 11, 6, ' فقالا لهم كما أوصى يسوع . فتركوهما '),
(25000, 'Mark', 41, 11, 7, ' فأتيا بالجحش إلى يسوع ، وألقيا عليه ثيابهما فجلس عليه '),
(25001, 'Mark', 41, 11, 8, ' وكثيرون فرشوا ثيابهم في الطريق . وآخرون قطعوا أغصانا من الشجر وفرشوها في الطريق '),
(25002, 'Mark', 41, 11, 9, ' والذين تقدموا ، والذين تبعوا كانوا يصرخون قائلين : أوصنا مبارك الآتي باسم الرب '),
(25003, 'Mark', 41, 11, 10, ' مباركة مملكة أبينا داود الآتية باسم الرب أوصنا في الأعالي '),
(25004, 'Mark', 41, 11, 11, ' فدخل يسوع أورشليم والهيكل ، ولما نظر حوله إلى كل شيء إذ كان الوقت قد أمسى ، خرج إلى بيت عنيا مع الاثني عشر '),
(25005, 'Mark', 41, 11, 12, ' وفي الغد لما خرجوا من بيت عنيا جاع '),
(25006, 'Mark', 41, 11, 13, ' فنظر شجرة تين من بعيد عليها ورق ، وجاء لعله يجد فيها شيئا . فلما جاء إليها لم يجد شيئا إلا ورقا ، لأنه لم يكن وقت التين '),
(25007, 'Mark', 41, 11, 14, ' فأجاب يسوع وقال لها : لا يأكل أحد منك ثمرا بعد إلى الأبد . وكان تلاميذه يسمعون '),
(25008, 'Mark', 41, 11, 15, ' وجاءوا إلى أورشليم . ولما دخل يسوع الهيكل ابتدأ يخرج الذين كانوا يبيعون ويشترون في الهيكل ، وقلب موائد الصيارفة وكراسي باعة الحمام '),
(25009, 'Mark', 41, 11, 16, ' ولم يدع أحدا يجتاز الهيكل بمتاع '),
(25010, 'Mark', 41, 11, 17, ' وكان يعلم قائلا لهم : أليس مكتوبا : بيتي بيت صلاة يدعى لجميع الأمم ؟ وأنتم جعلتموه مغارة لصوص '),
(25011, 'Mark', 41, 11, 18, ' وسمع الكتبة ورؤساء الكهنة فطلبوا كيف يهلكونه ، لأنهم خافوه ، إذ بهت الجمع كله من تعليمه '),
(25012, 'Mark', 41, 11, 19, ' ولما صار المساء ، خرج إلى خارج المدينة '),
(25013, 'Mark', 41, 11, 20, ' وفي الصباح إذ كانوا مجتازين رأوا التينة قد يبست من الأصول '),
(25014, 'Mark', 41, 11, 21, ' فتذكر بطرس وقال له : يا سيدي ، انظر التينة التي لعنتها قد يبست '),
(25015, 'Mark', 41, 11, 22, ' فأجاب يسوع وقال لهم : ليكن لكم إيمان بالله '),
(25016, 'Mark', 41, 11, 23, ' لأني الحق أقول لكم : إن من قال لهذا الجبل : انتقل وانطرح في البحر ولا يشك في قلبه ، بل يؤمن أن ما يقوله يكون ، فمهما قال يكون له '),
(25017, 'Mark', 41, 11, 24, ' لذلك أقول لكم : كل ما تطلبونه حينما تصلون ، فآمنوا أن تنالوه ، فيكون لكم '),
(25018, 'Mark', 41, 11, 25, ' ومتى وقفتم تصلون ، فاغفروا إن كان لكم على أحد شيء ، لكي يغفر لكم أيضا أبوكم الذي في السماوات زلاتكم '),
(25019, 'Mark', 41, 11, 26, ' وإن لم تغفروا أنتم لا يغفر أبوكم الذي في السماوات أيضا زلاتكم '),
(25020, 'Mark', 41, 11, 27, ' وجاءوا أيضا إلى أورشليم . وفيما هو يمشي في الهيكل ، أقبل إليه رؤساء الكهنة والكتبة والشيوخ '),
(25021, 'Mark', 41, 11, 28, ' وقالوا له : بأي سلطان تفعل هذا ؟ ومن أعطاك هذا السلطان حتى تفعل هذا '),
(25022, 'Mark', 41, 11, 29, ' فأجاب يسوع وقال لهم : وأنا أيضا أسألكم كلمة واحدة . أجيبوني ، فأقول لكم بأي سلطان أفعل هذا '),
(25023, 'Mark', 41, 11, 30, ' معمودية يوحنا : من السماء كانت أم من الناس ؟ أجيبوني '),
(25024, 'Mark', 41, 11, 31, ' ففكروا في أنفسهم قائلين : إن قلنا : من السماء ، يقول : فلماذا لم تؤمنوا به '),
(25025, 'Mark', 41, 11, 32, ' وإن قلنا : من الناس . فخافوا الشعب . لأن يوحنا كان عند الجميع أنه بالحقيقة نبي '),
(25026, 'Mark', 41, 11, 33, ' فأجابوا وقالوا ليسوع : لا نعلم . فأجاب يسوع وقال لهم : ولا أنا أقول لكم بأي سلطان أفعل هذا '),
(25027, 'Mark', 41, 12, 1, ' وابتدأ يقول لهم بأمثال : إنسان غرس كرما وأحاطه بسياج ، وحفر حوض معصرة ، وبنى برجا ، وسلمه إلى كرامين وسافر '),
(25028, 'Mark', 41, 12, 2, ' ثم أرسل إلى الكرامين في الوقت عبدا ليأخذ من الكرامين من ثمر الكرم '),
(25029, 'Mark', 41, 12, 3, ' فأخذوه وجلدوه وأرسلوه فارغا '),
(25030, 'Mark', 41, 12, 4, ' ثم أرسل إليهم أيضا عبدا آخر ، فرجموه وشجوه وأرسلوه مهانا '),
(25031, 'Mark', 41, 12, 5, ' ثم أرسل أيضا آخر ، فقتلوه . ثم آخرين كثيرين ، فجلدوا منهم بعضا وقتلوا بعضا '),
(25032, 'Mark', 41, 12, 6, ' فإذ كان له أيضا ابن واحد حبيب إليه ، أرسله أيضا إليهم أخيرا ، قائلا : إنهم يهابون ابني '),
(25033, 'Mark', 41, 12, 7, ' ولكن أولئك الكرامين قالوا فيما بينهم : هذا هو الوارث هلموا نقتله فيكون لنا الميراث '),
(25034, 'Mark', 41, 12, 8, ' فأخذوه وقتلوه وأخرجوه خارج الكرم '),
(25035, 'Mark', 41, 12, 9, ' فماذا يفعل صاحب الكرم ؟ يأتي ويهلك الكرامين ، ويعطي الكرم إلى آخرين '),
(25036, 'Mark', 41, 12, 10, ' أما قرأتم هذا المكتوب : الحجر الذي رفضه البناؤون ، هو قد صار رأس الزاوية '),
(25037, 'Mark', 41, 12, 11, ' من قبل الرب كان هذا ، وهو عجيب في أعيننا '),
(25038, 'Mark', 41, 12, 12, ' فطلبوا أن يمسكوه ، ولكنهم خافوا من الجمع ، لأنهم عرفوا أنه قال المثل عليهم . فتركوه ومضوا '),
(25039, 'Mark', 41, 12, 13, ' ثم أرسلوا إليه قوما من الفريسيين والهيرودسيين لكي يصطادوه بكلمة '),
(25040, 'Mark', 41, 12, 14, ' فلما جاءوا قالوا له : يا معلم ، نعلم أنك صادق ولا تبالي بأحد ، لأنك لا تنظر إلى وجوه الناس ، بل بالحق تعلم طريق الله . أيجوز أن تعطى جزية لقيصر أم لا ؟ نعطي أم لا نعطي '),
(25041, 'Mark', 41, 12, 15, ' فعلم رياءهم ، وقال لهم : لماذا تجربونني ؟ ايتوني بدينار لأنظره '),
(25042, 'Mark', 41, 12, 16, ' فأتوا به . فقال لهم : لمن هذه الصورة والكتابة ؟ فقالوا له : لقيصر '),
(25043, 'Mark', 41, 12, 17, ' فأجاب يسوع وقال لهم : أعطوا ما لقيصر لقيصر وما لله لله . فتعجبوا منه '),
(25044, 'Mark', 41, 12, 18, ' وجاء إليه قوم من الصدوقيين ، الذين يقولون ليس قيامة ، وسألوه قائلين '),
(25045, 'Mark', 41, 12, 19, ' يا معلم ، كتب لنا موسى : إن مات لأحد أخ ، وترك امرأة ولم يخلف أولادا ، أن يأخذ أخوه امرأته ، ويقيم نسلا لأخيه '),
(25046, 'Mark', 41, 12, 20, ' فكان سبعة إخوة . أخذ الأول امرأة ومات ، ولم يترك نسلا '),
(25047, 'Mark', 41, 12, 21, ' فأخذها الثاني ومات ، ولم يترك هو أيضا نسلا . وهكذا الثالث '),
(25048, 'Mark', 41, 12, 22, ' فأخذها السبعة ، ولم يتركوا نسلا . وآخر الكل ماتت المرأة أيضا '),
(25049, 'Mark', 41, 12, 23, ' ففي القيامة ، متى قاموا ، لمن منهم تكون زوجة ؟ لأنها كانت زوجة للسبعة '),
(25050, 'Mark', 41, 12, 24, ' فأجاب يسوع وقال لهم : أليس لهذا تضلون ، إذ لا تعرفون الكتب ولا قوة الله '),
(25051, 'Mark', 41, 12, 25, ' لأنهم متى قاموا من الأموات لا يزوجون ولا يزوجون ، بل يكونون كملائكة في السماوات '),
(25052, 'Mark', 41, 12, 26, ' وأما من جهة الأموات إنهم يقومون : أفما قرأتم في كتاب موسى ، في أمر العليقة ، كيف كلمه الله قائلا : أنا إله إبراهيم وإله إسحاق وإله يعقوب '),
(25053, 'Mark', 41, 12, 27, ' ليس هو إله أموات بل إله أحياء . فأنتم إذا تضلون كثيرا '),
(25054, 'Mark', 41, 12, 28, ' فجاء واحد من الكتبة وسمعهم يتحاورون ، فلما رأى أنه أجابهم حسنا ، سأله : أية وصية هي أول الكل '),
(25055, 'Mark', 41, 12, 29, ' فأجابه يسوع : إن أول كل الوصايا هي : اسمع يا إسرائيل . الرب إلهنا رب واحد '),
(25056, 'Mark', 41, 12, 30, ' وتحب الرب إلهك من كل قلبك ، ومن كل نفسك ، ومن كل فكرك ، ومن كل قدرتك . هذه هي الوصية الأولى '),
(25057, 'Mark', 41, 12, 31, ' وثانية مثلها هي : تحب قريبك كنفسك . ليس وصية أخرى أعظم من هاتين '),
(25058, 'Mark', 41, 12, 32, ' فقال له الكاتب : جيدا يا معلم . بالحق قلت ، لأنه الله واحد وليس آخر سواه '),
(25059, 'Mark', 41, 12, 33, ' ومحبته من كل القلب ، ومن كل الفهم ، ومن كل النفس ، ومن كل القدرة ، ومحبة القريب كالنفس ، هي أفضل من جميع المحرقات والذبائح '),
(25060, 'Mark', 41, 12, 34, ' فلما رآه يسوع أنه أجاب بعقل ، قال له : لست بعيدا عن ملكوت الله . ولم يجسر أحد بعد ذلك أن يسأله '),
(25061, 'Mark', 41, 12, 35, ' ثم أجاب يسوع وقال وهو يعلم في الهيكل : كيف يقول الكتبة إن المسيح ابن داود '),
(25062, 'Mark', 41, 12, 36, ' لأن داود نفسه قال بالروح القدس : قال الرب لربي : اجلس عن يميني ، حتى أضع أعداءك موطئا لقدميك '),
(25063, 'Mark', 41, 12, 37, ' فداود نفسه يدعوه ربا . فمن أين هو ابنه ؟  . وكان الجمع الكثير يسمعه بسرور '),
(25064, 'Mark', 41, 12, 38, ' وقال لهم في تعليمه : تحرزوا من الكتبة ، الذين يرغبون المشي بالطيالسة ، والتحيات في الأسواق '),
(25065, 'Mark', 41, 12, 39, ' والمجالس الأولى في المجامع ، والمتكآت الأولى في الولائم '),
(25066, 'Mark', 41, 12, 40, ' الذين يأكلون بيوت الأرامل ، ولعلة يطيلون الصلوات . هؤلاء يأخذون دينونة أعظم '),
(25067, 'Mark', 41, 12, 41, ' وجلس يسوع تجاه الخزانة ، ونظر كيف يلقي الجمع نحاسا في الخزانة . وكان أغنياء كثيرون يلقون كثيرا '),
(25068, 'Mark', 41, 12, 42, ' فجاءت أرملة فقيرة وألقت فلسين ، قيمتهما ربع '),
(25069, 'Mark', 41, 12, 43, ' فدعا تلاميذه وقال لهم : الحق أقول لكم : إن هذه الأرملة الفقيرة قد ألقت أكثر من جميع الذين ألقوا في الخزانة '),
(25070, 'Mark', 41, 12, 44, ' لأن الجميع من فضلتهم ألقوا . وأما هذه فمن إعوازها ألقت كل ما عندها ، كل معيشتها '),
(25071, 'Mark', 41, 13, 1, ' وفيما هو خارج من الهيكل ، قال له واحد من تلاميذه : يا معلم ، انظر ما هذه الحجارة وهذه الأبنية '),
(25072, 'Mark', 41, 13, 2, ' فأجاب يسوع وقال له : أتنظر هذه الأبنية العظيمة ؟ لا يترك حجر على حجر لا ينقض '),
(25073, 'Mark', 41, 13, 3, ' وفيما هو جالس على جبل الزيتون ، تجاه الهيكل ، سأله بطرس ويعقوب ويوحنا وأندراوس على انفراد '),
(25074, 'Mark', 41, 13, 4, ' قل لنا متى يكون هذا ؟ وما هي العلامة عندما يتم جميع هذا '),
(25075, 'Mark', 41, 13, 5, ' فأجابهم يسوع وابتدأ يقول : انظروا لا يضلكم أحد '),
(25076, 'Mark', 41, 13, 6, ' فإن كثيرين سيأتون باسمي قائلين : إني أنا هو ويضلون كثيرين '),
(25077, 'Mark', 41, 13, 7, ' فإذا سمعتم بحروب وبأخبار حروب فلا ترتاعوا ، لأنها لابد أن تكون ، ولكن ليس المنتهى بعد '),
(25078, 'Mark', 41, 13, 8, ' لأنه تقوم أمة على أمة ، ومملكة على مملكة ، وتكون زلازل في أماكن ، وتكون مجاعات واضطرابات . هذه مبتدأ الأوجاع '),
(25079, 'Mark', 41, 13, 9, ' فانظروا إلى نفوسكم . لأنهم سيسلمونكم إلى مجالس ، وتجلدون في مجامع ، وتوقفون أمام ولاة وملوك ، من أجلي ، شهادة لهم '),
(25080, 'Mark', 41, 13, 10, ' وينبغي أن يكرز أولا بالإنجيل في جميع الأمم '),
(25081, 'Mark', 41, 13, 11, ' فمتى ساقوكم ليسلموكم ، فلا تعتنوا من قبل بما تتكلمون ولا تهتموا ، بل مهما أعطيتم في تلك الساعة فبذلك تكلموا . لأن لستم أنتم المتكلمين بل الروح القدس '),
(25082, 'Mark', 41, 13, 12, ' وسيسلم الأخ أخاه إلى الموت ، والأب ولده ، ويقوم الأولاد على والديهم ويقتلونهم '),
(25083, 'Mark', 41, 13, 13, ' وتكونون مبغضين من الجميع من أجل اسمي . ولكن الذي يصبر إلى المنتهى فهذا يخلص '),
(25084, 'Mark', 41, 13, 14, ' فمتى نظرتم رجسة الخراب التي قال عنها دانيآل النبي ، قائمة حيث لا ينبغي - ليفهم القارئ - فحينئذ ليهرب الذين في اليهودية إلى الجبال '),
(25085, 'Mark', 41, 13, 15, ' والذي على السطح فلا ينزل إلى البيت ولا يدخل ليأخذ من بيته شيئا '),
(25086, 'Mark', 41, 13, 16, ' والذي في الحقل فلا يرجع إلى الوراء ليأخذ ثوبه '),
(25087, 'Mark', 41, 13, 17, ' وويل للحبالى والمرضعات في تلك الأيام '),
(25088, 'Mark', 41, 13, 18, ' وصلوا لكي لا يكون هربكم في شتاء '),
(25089, 'Mark', 41, 13, 19, ' لأنه يكون في تلك الأيام ضيق لم يكن مثله منذ ابتداء الخليقة التي خلقها الله إلى الآن ، ولن يكون '),
(25090, 'Mark', 41, 13, 20, ' ولو لم يقصر الرب تلك الأيام ، لم يخلص جسد . ولكن لأجل المختارين الذين اختارهم ، قصر الأيام '),
(25091, 'Mark', 41, 13, 21, ' حينئذ إن قال لكم أحد : هوذا المسيح هنا أو : هوذا هناك فلا تصدقوا '),
(25092, 'Mark', 41, 13, 22, ' لأنه سيقوم مسحاء كذبة وأنبياء كذبة ، ويعطون آيات وعجائب ، لكي يضلوا لو أمكن المختارين أيضا '),
(25093, 'Mark', 41, 13, 23, ' فانظروا أنتم . ها أنا قد سبقت وأخبرتكم بكل شيء '),
(25094, 'Mark', 41, 13, 24, ' وأما في تلك الأيام بعد ذلك الضيق : فالشمس تظلم ، والقمر لا يعطي ضوءه ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(25095, 'Mark', 41, 13, 25, ' ونجوم السماء تتساقط ، والقوات التي في السماوات تتزعزع '),
(25096, 'Mark', 41, 13, 26, ' وحينئذ يبصرون ابن الإنسان آتيا في سحاب بقوة كثيرة ومجد '),
(25097, 'Mark', 41, 13, 27, ' فيرسل حينئذ ملائكته ويجمع مختاريه من الأربع الرياح ، من أقصاء الأرض إلى أقصاء السماء '),
(25098, 'Mark', 41, 13, 28, ' فمن شجرة التين تعلموا المثل : متى صار غصنها رخصا وأخرجت أوراقا ، تعلمون أن الصيف قريب '),
(25099, 'Mark', 41, 13, 29, ' هكذا أنتم أيضا ، متى رأيتم هذه الأشياء صائرة ، فاعلموا أنه قريب على الأبواب '),
(25100, 'Mark', 41, 13, 30, ' الحق أقول لكم : لا يمضي هذا الجيل حتى يكون هذا كله '),
(25101, 'Mark', 41, 13, 31, ' السماء والأرض تزولان ، ولكن كلامي لا يزول '),
(25102, 'Mark', 41, 13, 32, ' وأما ذلك اليوم وتلك الساعة فلا يعلم بهما أحد ، ولا الملائكة الذين في السماء ، ولا الابن ، إلا الآب '),
(25103, 'Mark', 41, 13, 33, ' انظروا اسهروا وصلوا ، لأنكم لا تعلمون متى يكون الوقت '),
(25104, 'Mark', 41, 13, 34, ' كأنما إنسان مسافر ترك بيته ، وأعطى عبيده السلطان ، ولكل واحد عمله ، وأوصى البواب أن يسهر '),
(25105, 'Mark', 41, 13, 35, ' اسهروا إذا ، لأنكم لا تعلمون متى يأتي رب البيت ، أمساء ، أم نصف الليل ، أم صياح الديك ، أم صباحا '),
(25106, 'Mark', 41, 13, 36, ' لئلا يأتي بغتة فيجدكم نياما '),
(25107, 'Mark', 41, 13, 37, ' وما أقوله لكم أقوله للجميع : اسهروا '),
(25108, 'Mark', 41, 14, 1, ' وكان الفصح وأيام الفطير بعد يومين . وكان رؤساء الكهنة والكتبة يطلبون كيف يمسكونه بمكر ويقتلونه '),
(25109, 'Mark', 41, 14, 2, ' ولكنهم قالوا : ليس في العيد ، لئلا يكون شغب في الشعب '),
(25110, 'Mark', 41, 14, 3, ' وفيما هو في بيت عنيا في بيت سمعان الأبرص ، وهو متكئ ، جاءت امرأة معها قارورة طيب ناردين خالص كثير الثمن . فكسرت القارورة وسكبته على رأسه '),
(25111, 'Mark', 41, 14, 4, ' وكان قوم مغتاظين في أنفسهم ، فقالوا : لماذا كان تلف الطيب هذا '),
(25112, 'Mark', 41, 14, 5, ' لأنه كان يمكن أن يباع هذا بأكثر من ثلاثمئة دينار ويعطى للفقراء . وكانوا يؤنبونها '),
(25113, 'Mark', 41, 14, 6, ' أما يسوع فقال : اتركوها لماذا تزعجونها ؟ قد عملت بي عملا حسنا '),
(25114, 'Mark', 41, 14, 7, ' لأن الفقراء معكم في كل حين ، ومتى أردتم تقدرون أن تعملوا بهم خيرا . وأما أنا فلست معكم في كل حين '),
(25115, 'Mark', 41, 14, 8, ' عملت ما عندها . قد سبقت ودهنت بالطيب جسدي للتكفين '),
(25116, 'Mark', 41, 14, 9, ' الحق أقول لكم : حيثما يكرز بهذا الإنجيل في كل العالم ، يخبر أيضا بما فعلته هذه ، تذكارا لها '),
(25117, 'Mark', 41, 14, 10, ' ثم إن يهوذا الإسخريوطي ، واحدا من الاثني عشر ، مضى إلى رؤساء الكهنة ليسلمه إليهم '),
(25118, 'Mark', 41, 14, 11, ' ولما سمعوا فرحوا ، ووعدوه أن يعطوه فضة . وكان يطلب كيف يسلمه في فرصة موافقة '),
(25119, 'Mark', 41, 14, 12, ' وفي اليوم الأول من الفطير . حين كانوا يذبحون الفصح ، قال له تلاميذه : أين تريد أن نمضي ونعد لتأكل الفصح '),
(25120, 'Mark', 41, 14, 13, ' فأرسل اثنين من تلاميذه وقال لهما : اذهبا إلى المدينة ، فيلاقيكما إنسان حامل جرة ماء . اتبعاه '),
(25121, 'Mark', 41, 14, 14, ' وحيثما يدخل فقولا لرب البيت : إن المعلم يقول : أين المنزل حيث آكل الفصح مع تلاميذي '),
(25122, 'Mark', 41, 14, 15, ' فهو يريكما علية كبيرة مفروشة معدة . هناك أعدا لنا '),
(25123, 'Mark', 41, 14, 16, ' فخرج تلميذاه وأتيا إلى المدينة ، ووجدا كما قال لهما . فأعدا الفصح '),
(25124, 'Mark', 41, 14, 17, ' ولما كان المساء جاء مع الاثني عشر '),
(25125, 'Mark', 41, 14, 18, ' وفيما هم متكئون يأكلون ، قال يسوع : الحق أقول لكم : إن واحدا منكم يسلمني . الآكل معي '),
(25126, 'Mark', 41, 14, 19, ' فابتدأوا يحزنون ، ويقولون له واحدا فواحدا : هل أنا ؟ وآخر : هل أنا '),
(25127, 'Mark', 41, 14, 20, ' فأجاب وقال لهم : هو واحد من الاثني عشر ، الذي يغمس معي في الصحفة '),
(25128, 'Mark', 41, 14, 21, ' إن ابن الإنسان ماض كما هو مكتوب عنه ، ولكن ويل لذلك الرجل الذي به يسلم ابن الإنسان . كان خيرا لذلك الرجل لو لم يولد. '),
(25129, 'Mark', 41, 14, 22, ' وفيما هم يأكلون ، أخذ يسوع خبزا وبارك وكسر ، وأعطاهم وقال : خذوا كلوا ، هذا هو جسدي '),
(25130, 'Mark', 41, 14, 23, ' ثم أخذ الكأس وشكر وأعطاهم ، فشربوا منها كلهم '),
(25131, 'Mark', 41, 14, 24, ' وقال لهم : هذا هو دمي الذي للعهد الجديد ، الذي يسفك من أجل كثيرين '),
(25132, 'Mark', 41, 14, 25, ' الحق أقول لكم : إني لا أشرب بعد من نتاج الكرمة إلى ذلك اليوم حينما أشربه جديدا في ملكوت الله '),
(25133, 'Mark', 41, 14, 26, ' ثم سبحوا وخرجوا إلى جبل الزيتون '),
(25134, 'Mark', 41, 14, 27, ' وقال لهم يسوع : إن كلكم تشكون في في هذه الليلة ، لأنه مكتوب : أني أضرب الراعي فتتبدد الخراف '),
(25135, 'Mark', 41, 14, 28, ' ولكن بعد قيامي أسبقكم إلى الجليل '),
(25136, 'Mark', 41, 14, 29, ' فقال له بطرس : وإن شك الجميع فأنا لا أشك '),
(25137, 'Mark', 41, 14, 30, ' فقال له يسوع : الحق أقول لك : إنك اليوم في هذه الليلة ، قبل أن يصيح الديك مرتين ، تنكرني ثلاث مرات '),
(25138, 'Mark', 41, 14, 31, ' فقال بأكثر تشديد : ولو اضطررت أن أموت معك لا أنكرك . وهكذا قال أيضا الجميع '),
(25139, 'Mark', 41, 14, 32, ' وجاءوا إلى ضيعة اسمها جثسيماني ، فقال لتلاميذه : اجلسوا ههنا حتى أصلي '),
(25140, 'Mark', 41, 14, 33, ' ثم أخذ معه بطرس ويعقوب ويوحنا ، وابتدأ يدهش ويكتئب '),
(25141, 'Mark', 41, 14, 34, ' فقال لهم : نفسي حزينة جدا حتى الموت امكثوا هنا واسهروا '),
(25142, 'Mark', 41, 14, 35, ' ثم تقدم قليلا وخر على الأرض ، وكان يصلي لكي تعبر عنه الساعة إن أمكن '),
(25143, 'Mark', 41, 14, 36, ' وقال : يا أبا الآب ، كل شيء مستطاع لك ، فأجز عني هذه الكأس . ولكن ليكن لا ما أريد أنا ، بل ما تريد أنت '),
(25144, 'Mark', 41, 14, 37, ' ثم جاء ووجدهم نياما ، فقال لبطرس : يا سمعان ، أنت نائم أما قدرت أن تسهر ساعة واحدة '),
(25145, 'Mark', 41, 14, 38, ' اسهروا وصلوا لئلا تدخلوا في تجربة . أما الروح فنشيط ، وأما الجسد فضعيف '),
(25146, 'Mark', 41, 14, 39, ' ومضى أيضا وصلى قائلا ذلك الكلام بعينه '),
(25147, 'Mark', 41, 14, 40, ' ثم رجع ووجدهم أيضا نياما ، إذ كانت أعينهم ثقيلة ، فلم يعلموا بماذا يجيبونه '),
(25148, 'Mark', 41, 14, 41, ' ثم جاء ثالثة وقال لهم : ناموا الآن واستريحوا يكفي قد أتت الساعة هوذا ابن الإنسان يسلم إلى أيدي الخطاة '),
(25149, 'Mark', 41, 14, 42, ' قوموا لنذهب هوذا الذي يسلمني قد اقترب '),
(25150, 'Mark', 41, 14, 43, ' وللوقت فيما هو يتكلم أقبل يهوذا ، واحد من الاثني عشر ، ومعه جمع كثير بسيوف وعصي من عند رؤساء الكهنة والكتبة والشيوخ '),
(25151, 'Mark', 41, 14, 44, ' وكان مسلمه قد أعطاهم علامة قائلا : الذي أقبله هو هو . أمسكوه ، وامضوا به بحرص '),
(25152, 'Mark', 41, 14, 45, ' فجاء للوقت وتقدم إليه قائلا : يا سيدي ، يا سيدي وقبله '),
(25153, 'Mark', 41, 14, 46, ' فألقوا أيديهم عليه وأمسكوه '),
(25154, 'Mark', 41, 14, 47, ' فاستل واحد من الحاضرين السيف ، وضرب عبد رئيس الكهنة فقطع أذنه '),
(25155, 'Mark', 41, 14, 48, ' فأجاب يسوع وقال لهم : كأنه على لص خرجتم بسيوف وعصي لتأخذوني '),
(25156, 'Mark', 41, 14, 49, ' كل يوم كنت معكم في الهيكل أعلم ولم تمسكوني ولكن لكي تكمل الكتب '),
(25157, 'Mark', 41, 14, 50, ' فتركه الجميع وهربوا '),
(25158, 'Mark', 41, 14, 51, ' وتبعه شاب لابسا إزارا على عريه ، فأمسكه الشبان '),
(25159, 'Mark', 41, 14, 52, ' فترك الإزار وهرب منهم عريانا '),
(25160, 'Mark', 41, 14, 53, ' فمضوا بيسوع إلى رئيس الكهنة ، فاجتمع معه جميع رؤساء الكهنة والشيوخ والكتبة '),
(25161, 'Mark', 41, 14, 54, ' وكان بطرس قد تبعه من بعيد إلى داخل دار رئيس الكهنة ، وكان جالسا بين الخدام يستدفئ عند النار '),
(25162, 'Mark', 41, 14, 55, ' وكان رؤساء الكهنة والمجمع كله يطلبون شهادة على يسوع ليقتلوه ، فلم يجدوا '),
(25163, 'Mark', 41, 14, 56, ' لأن كثيرين شهدوا عليه زورا ، ولم تتفق شهاداتهم '),
(25164, 'Mark', 41, 14, 57, ' ثم قام قوم وشهدوا عليه زورا قائلين '),
(25165, 'Mark', 41, 14, 58, ' نحن سمعناه يقول : إني أنقض هذا الهيكل المصنوع بالأيادي ، وفي ثلاثة أيام أبني آخر غير مصنوع بأياد. '),
(25166, 'Mark', 41, 14, 59, ' ولا بهذا كانت شهادتهم تتفق '),
(25167, 'Mark', 41, 14, 60, ' فقام رئيس الكهنة في الوسط وسأل يسوع قائلا : أما تجيب بشيء ؟ ماذا يشهد به هؤلاء عليك '),
(25168, 'Mark', 41, 14, 61, ' أما هو فكان ساكتا ولم يجب بشيء . فسأله رئيس الكهنة أيضا وقال له : أأنت المسيح ابن المبارك '),
(25169, 'Mark', 41, 14, 62, ' فقال يسوع : أنا هو . وسوف تبصرون ابن الإنسان جالسا عن يمين القوة ، وآتيا في سحاب السماء '),
(25170, 'Mark', 41, 14, 63, ' فمزق رئيس الكهنة ثيابه وقال : ما حاجتنا بعد إلى شهود '),
(25171, 'Mark', 41, 14, 64, ' قد سمعتم التجاديف ما رأيكم ؟ فالجميع حكموا عليه أنه مستوجب الموت '),
(25172, 'Mark', 41, 14, 65, ' فابتدأ قوم يبصقون عليه ، ويغطون وجهه ويلكمونه ويقولون له : تنبأ . وكان الخدام يلطمونه '),
(25173, 'Mark', 41, 14, 66, ' وبينما كان بطرس في الدار أسفل جاءت إحدى جواري رئيس الكهنة '),
(25174, 'Mark', 41, 14, 67, ' فلما رأت بطرس يستدفئ ، نظرت إليه وقالت : وأنت كنت مع يسوع الناصري '),
(25175, 'Mark', 41, 14, 68, ' فأنكر قائلا : لست أدري ولا أفهم ما تقولين وخرج خارجا إلى الدهليز ، فصاح الديك '),
(25176, 'Mark', 41, 14, 69, ' فرأته الجارية أيضا وابتدأت تقول للحاضرين : إن هذا منهم '),
(25177, 'Mark', 41, 14, 70, ' فأنكر أيضا . وبعد قليل أيضا قال الحاضرون لبطرس : حقا أنت منهم ، لأنك جليلي أيضا ولغتك تشبه لغتهم '),
(25178, 'Mark', 41, 14, 71, ' فابتدأ يلعن ويحلف : إني لا أعرف هذا الرجل الذي تقولون عنه '),
(25179, 'Mark', 41, 14, 72, ' وصاح الديك ثانية ، فتذكر بطرس القول الذي قاله له يسوع : إنك قبل أن يصيح الديك مرتين ، تنكرني ثلاث مرات . فلما تفكر به بكى. '),
(25180, 'Mark', 41, 15, 1, ' وللوقت في الصباح تشاور رؤساء الكهنة والشيوخ والكتبة والمجمع كله ، فأوثقوا يسوع ومضوا به وأسلموه إلى بيلاطس '),
(25181, 'Mark', 41, 15, 2, ' فسأله بيلاطس : أنت ملك اليهود ؟ فأجاب وقال له : أنت تقول '),
(25182, 'Mark', 41, 15, 3, ' وكان رؤساء الكهنة يشتكون عليه كثيرا '),
(25183, 'Mark', 41, 15, 4, ' فسأله بيلاطس أيضا قائلا : أما تجيب بشيء ؟ انظر كم يشهدون عليك '),
(25184, 'Mark', 41, 15, 5, ' فلم يجب يسوع أيضا بشيء حتى تعجب بيلاطس '),
(25185, 'Mark', 41, 15, 6, ' وكان يطلق لهم في كل عيد أسيرا واحدا ، من طلبوه '),
(25186, 'Mark', 41, 15, 7, ' وكان المسمى باراباس موثقا مع رفقائه في الفتنة ، الذين في الفتنة فعلوا قتلا '),
(25187, 'Mark', 41, 15, 8, ' فصرخ الجمع وابتدأوا يطلبون أن يفعل كما كان دائما يفعل لهم '),
(25188, 'Mark', 41, 15, 9, ' فأجابهم بيلاطس قائلا : أتريدون أن أطلق لكم ملك اليهود '),
(25189, 'Mark', 41, 15, 10, ' لأنه عرف أن رؤساء الكهنة كانوا قد أسلموه حسدا '),
(25190, 'Mark', 41, 15, 11, ' فهيج رؤساء الكهنة الجمع لكي يطلق لهم بالحري باراباس '),
(25191, 'Mark', 41, 15, 12, ' فأجاب بيلاطس أيضا وقال لهم : فماذا تريدون أن أفعل بالذي تدعونه : ملك اليهود '),
(25192, 'Mark', 41, 15, 13, ' فصرخوا أيضا : اصلبه '),
(25193, 'Mark', 41, 15, 14, ' فقال لهم بيلاطس : وأي شر عمل ؟ فازدادوا جدا صراخا : اصلبه '),
(25194, 'Mark', 41, 15, 15, ' فبيلاطس إذ كان يريد أن يعمل للجمع ما يرضيهم ، أطلق لهم باراباس ، وأسلم يسوع ، بعدما جلده ، ليصلب '),
(25195, 'Mark', 41, 15, 16, ' فمضى به العسكر إلى داخل الدار ، التي هي دار الولاية ، وجمعوا كل الكتيبة '),
(25196, 'Mark', 41, 15, 17, ' وألبسوه أرجوانا ، وضفروا إكليلا من شوك ووضعوه عليه '),
(25197, 'Mark', 41, 15, 18, ' وابتدأوا يسلمون عليه قائلين : السلام يا ملك اليهود '),
(25198, 'Mark', 41, 15, 19, ' وكانوا يضربونه على رأسه بقصبة ، ويبصقون عليه ، ثم يسجدون له جاثين على ركبهم '),
(25199, 'Mark', 41, 15, 20, ' وبعدما استهزأوا به ، نزعوا عنه الأرجوان وألبسوه ثيابه ، ثم خرجوا به ليصلبوه '),
(25200, 'Mark', 41, 15, 21, ' فسخروا رجلا مجتازا كان آتيا من الحقل ، وهو سمعان القيرواني أبو ألكسندرس وروفس ، ليحمل صليبه '),
(25201, 'Mark', 41, 15, 22, ' وجاءوا به إلى موضع جلجثة الذي تفسيره موضع جمجمة '),
(25202, 'Mark', 41, 15, 23, ' وأعطوه خمرا ممزوجة بمر ليشرب ، فلم يقبل '),
(25203, 'Mark', 41, 15, 24, ' ولما صلبوه اقتسموا ثيابه مقترعين عليها : ماذا يأخذ كل واحد '),
(25204, 'Mark', 41, 15, 25, ' وكانت الساعة الثالثة فصلبوه '),
(25205, 'Mark', 41, 15, 26, ' وكان عنوان علته مكتوبا : ملك اليهود '),
(25206, 'Mark', 41, 15, 27, ' وصلبوا معه لصين ، واحدا عن يمينه وآخر عن يساره '),
(25207, 'Mark', 41, 15, 28, ' فتم الكتاب القائل : وأحصي مع أثمة '),
(25208, 'Mark', 41, 15, 29, ' وكان المجتازون يجدفون عليه ، وهم يهزون رؤوسهم قائلين : آه يا ناقض الهيكل وبانيه في ثلاثة أيام '),
(25209, 'Mark', 41, 15, 30, ' خلص نفسك وانزل عن الصليب '),
(25210, 'Mark', 41, 15, 31, ' وكذلك رؤساء الكهنة وهم مستهزئون فيما بينهم مع الكتبة ، قالوا : خلص آخرين وأما نفسه فما يقدر أن يخلصها '),
(25211, 'Mark', 41, 15, 32, ' لينزل الآن المسيح ملك إسرائيل عن الصليب ، لنرى ونؤمن . واللذان صلبا معه كانا يعيرانه '),
(25212, 'Mark', 41, 15, 33, ' ولما كانت الساعة السادسة ، كانت ظلمة على الأرض كلها إلى الساعة التاسعة '),
(25213, 'Mark', 41, 15, 34, ' وفي الساعة التاسعة صرخ يسوع بصوت عظيم قائلا : إلوي ، إلوي ، لما شبقتني ؟ الذي تفسيره : إلهي ، إلهي ، لماذا تركتني '),
(25214, 'Mark', 41, 15, 35, ' فقال قوم من الحاضرين لما سمعوا : هوذا ينادي إيليا '),
(25215, 'Mark', 41, 15, 36, ' فركض واحد وملأ إسفنجة خلا وجعلها على قصبة وسقاه قائلا : اتركوا . لنر هل يأتي إيليا لينزله '),
(25216, 'Mark', 41, 15, 37, ' فصرخ يسوع بصوت عظيم وأسلم الروح '),
(25217, 'Mark', 41, 15, 38, ' وانشق حجاب الهيكل إلى اثنين ، من فوق إلى أسفل '),
(25218, 'Mark', 41, 15, 39, ' ولما رأى قائد المئة الواقف مقابله أنه صرخ هكذا وأسلم الروح ، قال : حقا كان هذا الإنسان ابن الله '),
(25219, 'Mark', 41, 15, 40, ' وكانت أيضا نساء ينظرن من بعيد ، بينهن مريم المجدلية ، ومريم أم يعقوب الصغير ويوسي ، وسالومة، '),
(25220, 'Mark', 41, 15, 41, ' اللواتي أيضا تبعنه وخدمنه حين كان في الجليل . وأخر كثيرات اللواتي صعدن معه إلى أورشليم '),
(25221, 'Mark', 41, 15, 42, ' ولما كان المساء ، إذ كان الاستعداد ، أي ما قبل السبت '),
(25222, 'Mark', 41, 15, 43, ' جاء يوسف الذي من الرامة ، مشير شريف ، وكان هو أيضا منتظرا ملكوت الله ، فتجاسر ودخل إلى بيلاطس وطلب جسد يسوع '),
(25223, 'Mark', 41, 15, 44, ' فتعجب بيلاطس أنه مات كذا سريعا . فدعا قائد المئة وسأله : هل له زمان قد مات '),
(25224, 'Mark', 41, 15, 45, ' ولما عرف من قائد المئة ، وهب الجسد ليوسف '),
(25225, 'Mark', 41, 15, 46, ' فاشترى كتانا ، فأنزله وكفنه بالكتان ، ووضعه في قبر كان منحوتا في صخرة ، ودحرج حجرا على باب القبر '),
(25226, 'Mark', 41, 15, 47, ' وكانت مريم المجدلية ومريم أم يوسي تنظران أين وضع '),
(25227, 'Mark', 41, 16, 1, ' وبعدما مضى السبت ، اشترت مريم المجدلية ومريم أم يعقوب وسالومة ، حنوطا ليأتين ويدهنه '),
(25228, 'Mark', 41, 16, 2, ' وباكرا جدا في أول الأسبوع أتين إلى القبر إذ طلعت الشمس '),
(25229, 'Mark', 41, 16, 3, ' وكن يقلن فيما بينهن : من يدحرج لنا الحجر عن باب القبر '),
(25230, 'Mark', 41, 16, 4, ' فتطلعن ورأين أن الحجر قد دحرج لأنه كان عظيما جدا '),
(25231, 'Mark', 41, 16, 5, ' ولما دخلن القبر رأين شابا جالسا عن اليمين لابسا حلة بيضاء ، فاندهشن '),
(25232, 'Mark', 41, 16, 6, ' فقال لهن : لا تندهشن أنتن تطلبن يسوع الناصري المصلوب . قد قام ليس هو ههنا . هوذا الموضع الذي وضعوه فيه '),
(25233, 'Mark', 41, 16, 7, ' لكن اذهبن وقلن لتلاميذه ولبطرس : إنه يسبقكم إلى الجليل . هناك ترونه كما قال لكم '),
(25234, 'Mark', 41, 16, 8, ' فخرجن سريعا وهربن من القبر ، لأن الرعدة والحيرة أخذتاهن . ولم يقلن لأحد شيئا لأنهن كن خائفات '),
(25235, 'Mark', 41, 16, 9, ' وبعدما قام باكرا في أول الأسبوع ظهر أولا لمريم المجدلية ، التي كان قد أخرج منها سبعة شياطين '),
(25236, 'Mark', 41, 16, 10, ' فذهبت هذه وأخبرت الذين كانوا معه وهم ينوحون ويبكون '),
(25237, 'Mark', 41, 16, 11, ' فلما سمع أولئك أنه حي ، وقد نظرته ، لم يصدقوا '),
(25238, 'Mark', 41, 16, 12, ' وبعد ذلك ظهر بهيئة أخرى لاثنين منهم ، وهما يمشيان منطلقين إلى البرية '),
(25239, 'Mark', 41, 16, 13, ' وذهب هذان وأخبرا الباقين ، فلم يصدقوا ولا هذين '),
(25240, 'Mark', 41, 16, 14, ' أخيرا ظهر للأحد عشر وهم متكئون ، ووبخ عدم إيمانهم وقساوة قلوبهم ، لأنهم لم يصدقوا الذين نظروه قد قام '),
(25241, 'Mark', 41, 16, 15, ' وقال لهم : اذهبوا إلى العالم أجمع واكرزوا بالإنجيل للخليقة كلها '),
(25242, 'Mark', 41, 16, 16, ' من آمن واعتمد خلص ، ومن لم يؤمن يدن '),
(25243, 'Mark', 41, 16, 17, ' وهذه الآيات تتبع المؤمنين : يخرجون الشياطين باسمي ، ويتكلمون بألسنة جديدة '),
(25244, 'Mark', 41, 16, 18, ' يحملون حيات ، وإن شربوا شيئا مميتا لا يضرهم ، ويضعون أيديهم على المرضى فيبرأون '),
(25245, 'Mark', 41, 16, 19, ' ثم إن الرب بعدما كلمهم ارتفع إلى السماء ، وجلس عن يمين الله '),
(25246, 'Mark', 41, 16, 20, ' وأما هم فخرجوا وكرزوا في كل مكان ، والرب يعمل معهم ويثبت الكلام بالآيات التابعة . آمين '),
(25247, 'Matthew', 40, 1, 1, ' كتاب ميلاد يسوع المسيح ابن داود ابن إبراهيم '),
(25248, 'Matthew', 40, 1, 2, ' إبراهيم ولد إسحاق . وإسحاق ولد يعقوب . ويعقوب ولد يهوذا وإخوته '),
(25249, 'Matthew', 40, 1, 3, ' ويهوذا ولد فارص وزارح من ثامار . وفارص ولد حصرون . وحصرون ولد أرام '),
(25250, 'Matthew', 40, 1, 4, ' وأرام ولد عميناداب . وعميناداب ولد نحشون . ونحشون ولد سلمون '),
(25251, 'Matthew', 40, 1, 5, ' وسلمون ولد بوعز من راحاب . وبوعز ولد عوبيد من راعوث . وعوبيد ولد يسى '),
(25252, 'Matthew', 40, 1, 6, ' ويسى ولد داود الملك . وداود الملك ولد سليمان من التي لأوريا '),
(25253, 'Matthew', 40, 1, 7, ' وسليمان ولد رحبعام . ورحبعام ولد أبيا . وأبيا ولد آسا '),
(25254, 'Matthew', 40, 1, 8, ' وآسا ولد يهوشافاط . ويهوشافاط ولد يورام . ويورام ولد عزيا '),
(25255, 'Matthew', 40, 1, 9, ' وعزيا ولد يوثام . ويوثام ولد أحاز . وأحاز ولد حزقيا '),
(25256, 'Matthew', 40, 1, 10, ' وحزقيا ولد منسى . ومنسى ولد آمون . وآمون ولد يوشيا '),
(25257, 'Matthew', 40, 1, 11, ' ويوشيا ولد يكنيا وإخوته عند سبي بابل '),
(25258, 'Matthew', 40, 1, 12, ' وبعد سبي بابل يكنيا ولد شألتئيل . وشألتئيل ولد زربابل '),
(25259, 'Matthew', 40, 1, 13, ' وزربابل ولد أبيهود . وأبيهود ولد ألياقيم . وألياقيم ولد عازور '),
(25260, 'Matthew', 40, 1, 14, ' وعازور ولد صادوق . وصادوق ولد أخيم . وأخيم ولد أليود '),
(25261, 'Matthew', 40, 1, 15, ' وأليود ولد أليعازر . وأليعازر ولد متان . ومتان ولد يعقوب '),
(25262, 'Matthew', 40, 1, 16, ' ويعقوب ولد يوسف رجل مريم التي ولد منها يسوع الذي يدعى المسيح '),
(25263, 'Matthew', 40, 1, 17, ' فجميع الأجيال من إبراهيم إلى داود أربعة عشر جيلا ، ومن داود إلى سبي بابل أربعة عشر جيلا ، ومن سبي بابل إلى المسيح أربعة عشر جيلا '),
(25264, 'Matthew', 40, 1, 18, ' أما ولادة يسوع المسيح فكانت هكذا : لما كانت مريم أمه مخطوبة ليوسف ، قبل أن يجتمعا ، وجدت حبلى من الروح القدس '),
(25265, 'Matthew', 40, 1, 19, ' فيوسف رجلها إذ كان بارا ، ولم يشأ أن يشهرها ، أراد تخليتها سرا '),
(25266, 'Matthew', 40, 1, 20, ' ولكن فيما هو متفكر في هذه الأمور ، إذا ملاك الرب قد ظهر له في حلم قائلا : يا يوسف ابن داود ، لا تخف أن تأخذ مريم امرأتك . لأن الذي حبل به فيها هو من الروح القدس '),
(25267, 'Matthew', 40, 1, 21, ' فستلد ابنا وتدعو اسمه يسوع . لأنه يخلص شعبه من خطاياهم '),
(25268, 'Matthew', 40, 1, 22, ' وهذا كله كان لكي يتم ما قيل من الرب بالنبي القائل '),
(25269, 'Matthew', 40, 1, 23, ' هوذا العذراء تحبل وتلد ابنا ، ويدعون اسمه عمانوئيل الذي تفسيره : الله معنا '),
(25270, 'Matthew', 40, 1, 24, ' فلما استيقظ يوسف من النوم فعل كما أمره ملاك الرب ، وأخذ امرأته '),
(25271, 'Matthew', 40, 1, 25, ' ولم يعرفها حتى ولدت ابنها البكر . ودعا اسمه يسوع '),
(25272, 'Matthew', 40, 2, 1, ' ولما ولد يسوع في بيت لحم اليهودية ، في أيام هيرودس الملك ، إذا مجوس من المشرق قد جاءوا إلى أورشليم '),
(25273, 'Matthew', 40, 2, 2, ' قائلين : أين هو المولود ملك اليهود ؟ فإننا رأينا نجمه في المشرق وأتينا لنسجد له '),
(25274, 'Matthew', 40, 2, 3, ' فلما سمع هيرودس الملك اضطرب وجميع أورشليم معه '),
(25275, 'Matthew', 40, 2, 4, ' فجمع كل رؤساء الكهنة وكتبة الشعب ، وسألهم : أين يولد المسيح '),
(25276, 'Matthew', 40, 2, 5, ' فقالوا له : في بيت لحم اليهودية . لأنه هكذا مكتوب بالنبي '),
(25277, 'Matthew', 40, 2, 6, ' وأنت يا بيت لحم ، أرض يهوذا لست الصغرى بين رؤساء يهوذا ، لأن منك يخرج مدبر يرعى شعبي إسرائيل '),
(25278, 'Matthew', 40, 2, 7, ' حينئذ دعا هيرودس المجوس سرا ، وتحقق منهم زمان النجم الذي ظهر '),
(25279, 'Matthew', 40, 2, 8, ' ثم أرسلهم إلى بيت لحم ، وقال : اذهبوا وافحصوا بالتدقيق عن الصبي . ومتى وجدتموه فأخبروني ، لكي آتي أنا أيضا وأسجد له '),
(25280, 'Matthew', 40, 2, 9, ' فلما سمعوا من الملك ذهبوا . وإذا النجم الذي رأوه في المشرق يتقدمهم حتى جاء ووقف فوق ، حيث كان الصبي '),
(25281, 'Matthew', 40, 2, 10, ' فلما رأوا النجم فرحوا فرحا عظيما جدا '),
(25282, 'Matthew', 40, 2, 11, ' وأتوا إلى البيت ، ورأوا الصبي مع مريم أمه . فخروا وسجدوا له . ثم فتحوا كنوزهم وقدموا له هدايا : ذهبا ولبانا ومرا '),
(25283, 'Matthew', 40, 2, 12, ' ثم إذ أوحي إليهم في حلم أن لا يرجعوا إلى هيرودس ، انصرفوا في طريق أخرى إلى كورتهم '),
(25284, 'Matthew', 40, 2, 13, ' وبعدما انصرفوا ، إذا ملاك الرب قد ظهر ليوسف في حلم قائلا : قم وخذ الصبي وأمه واهرب إلى مصر ، وكن هناك حتى أقول لك . لأن هيرودس مزمع أن يطلب الصبي ليهلكه '),
(25285, 'Matthew', 40, 2, 14, ' فقام وأخذ الصبي وأمه ليلا وانصرف إلى مصر '),
(25286, 'Matthew', 40, 2, 15, ' وكان هناك إلى وفاة هيرودس . لكي يتم ما قيل من الرب بالنبي القائل : من مصر دعوت ابني '),
(25287, 'Matthew', 40, 2, 16, ' حينئذ لما رأى هيرودس أن المجوس سخروا به غضب جدا . فأرسل وقتل جميع الصبيان الذين في بيت لحم وفي كل تخومها ، من ابن سنتين فما دون ، بحسب الزمان الذي تحققه من المجوس '),
(25288, 'Matthew', 40, 2, 17, ' حينئذ تم ما قيل بإرميا النبي القائل '),
(25289, 'Matthew', 40, 2, 18, ' صوت سمع في الرامة ، نوح وبكاء وعويل كثير . راحيل تبكي على أولادها ولا تريد أن تتعزى ، لأنهم ليسوا بموجودين '),
(25290, 'Matthew', 40, 2, 19, ' فلما مات هيرودس ، إذا ملاك الرب قد ظهر في حلم ليوسف في مصر '),
(25291, 'Matthew', 40, 2, 20, ' قائلا : قم وخذ الصبي وأمه واذهب إلى أرض إسرائيل ، لأنه قد مات الذين كانوا يطلبون نفس الصبي '),
(25292, 'Matthew', 40, 2, 21, ' فقام وأخذ الصبي وأمه وجاء إلى أرض إسرائيل '),
(25293, 'Matthew', 40, 2, 22, ' ولكن لما سمع أن أرخيلاوس يملك على اليهودية عوضا عن هيرودس أبيه ، خاف أن يذهب إلى هناك . وإذ أوحي إليه في حلم ، انصرف إلى نواحي الجليل '),
(25294, 'Matthew', 40, 2, 23, ' وأتى وسكن في مدينة يقال لها ناصرة ، لكي يتم ما قيل بالأنبياء : إنه سيدعى ناصريا '),
(25295, 'Matthew', 40, 3, 1, ' وفي تلك الأيام جاء يوحنا المعمدان يكرز في برية اليهودية '),
(25296, 'Matthew', 40, 3, 2, ' قائلا : توبوا ، لأنه قد اقترب ملكوت السماوات '),
(25297, 'Matthew', 40, 3, 3, ' فإن هذا هو الذي قيل عنه بإشعياء النبي القائل : صوت صارخ في البرية : أعدوا طريق الرب . اصنعوا سبله مستقيمة '),
(25298, 'Matthew', 40, 3, 4, ' ويوحنا هذا كان لباسه من وبر الإبل ، وعلى حقويه منطقة من جلد . وكان طعامه جرادا وعسلا بريا '),
(25299, 'Matthew', 40, 3, 5, ' حينئذ خرج إليه أورشليم وكل اليهودية وجميع الكورة المحيطة بالأردن '),
(25300, 'Matthew', 40, 3, 6, ' واعتمدوا منه في الأردن ، معترفين بخطاياهم '),
(25301, 'Matthew', 40, 3, 7, ' فلما رأى كثيرين من الفريسيين والصدوقيين يأتون إلى معموديته ، قال لهم : يا أولاد الأفاعي ، من أراكم أن تهربوا من الغضب الآتي '),
(25302, 'Matthew', 40, 3, 8, ' فاصنعوا أثمارا تليق بالتوبة '),
(25303, 'Matthew', 40, 3, 9, ' ولا تفتكروا أن تقولوا في أنفسكم : لنا إبراهيم أبا . لأني أقول لكم : إن الله قادر أن يقيم من هذه الحجارة أولادا لإبراهيم '),
(25304, 'Matthew', 40, 3, 10, ' والآن قد وضعت الفأس على أصل الشجر ، فكل شجرة لا تصنع ثمرا جيدا تقطع وتلقى في النار '),
(25305, 'Matthew', 40, 3, 11, ' أنا أعمدكم بماء للتوبة ، ولكن الذي يأتي بعدي هو أقوى مني ، الذي لست أهلا أن أحمل حذاءه . هو سيعمدكم بالروح القدس ونار '),
(25306, 'Matthew', 40, 3, 12, ' الذي رفشه في يده ، وسينقي بيدره ، ويجمع قمحه إلى المخزن ، وأما التبن فيحرقه بنار لا تطفأ '),
(25307, 'Matthew', 40, 3, 13, ' حينئذ جاء يسوع من الجليل إلى الأردن إلى يوحنا ليعتمد منه '),
(25308, 'Matthew', 40, 3, 14, ' ولكن يوحنا منعه قائلا : أنا محتاج أن أعتمد منك ، وأنت تأتي إلي '),
(25309, 'Matthew', 40, 3, 15, ' فأجاب يسوع وقال له : اسمح الآن ، لأنه هكذا يليق بنا أن نكمل كل بر . حينئذ سمح له '),
(25310, 'Matthew', 40, 3, 16, ' فلما اعتمد يسوع صعد للوقت من الماء ، وإذا السماوات قد انفتحت له ، فرأى روح الله نازلا مثل حمامة وآتيا عليه '),
(25311, 'Matthew', 40, 3, 17, ' وصوت من السماوات قائلا : هذا هو ابني الحبيب الذي به سررت '),
(25312, 'Matthew', 40, 4, 1, ' ثم أصعد يسوع إلى البرية من الروح ليجرب من إبليس '),
(25313, 'Matthew', 40, 4, 2, ' فبعد ما صام أربعين نهارا وأربعين ليلة ، جاع أخيرا '),
(25314, 'Matthew', 40, 4, 3, ' فتقدم إليه المجرب وقال له : إن كنت ابن الله فقل أن تصير هذه الحجارة خبزا '),
(25315, 'Matthew', 40, 4, 4, ' فأجاب وقال : مكتوب : ليس بالخبز وحده يحيا الإنسان ، بل بكل كلمة تخرج من فم الله '),
(25316, 'Matthew', 40, 4, 5, ' ثم أخذه إبليس إلى المدينة المقدسة ، وأوقفه على جناح الهيكل '),
(25317, 'Matthew', 40, 4, 6, ' وقال له : إن كنت ابن الله فاطرح نفسك إلى أسفل ، لأنه مكتوب : أنه يوصي ملائكته بك ، فعلى أياديهم يحملونك لكي لا تصدم بحجر رجلك '),
(25318, 'Matthew', 40, 4, 7, ' قال له يسوع : مكتوب أيضا : لا تجرب الرب إلهك '),
(25319, 'Matthew', 40, 4, 8, ' ثم أخذه أيضا إبليس إلى جبل عال جدا ، وأراه جميع ممالك العالم ومجدها '),
(25320, 'Matthew', 40, 4, 9, ' وقال له : أعطيك هذه جميعها إن خررت وسجدت لي '),
(25321, 'Matthew', 40, 4, 10, ' حينئذ قال له يسوع : اذهب يا شيطان لأنه مكتوب : للرب إلهك تسجد وإياه وحده تعبد '),
(25322, 'Matthew', 40, 4, 11, ' ثم تركه إبليس ، وإذا ملائكة قد جاءت فصارت تخدمه '),
(25323, 'Matthew', 40, 4, 12, ' ولما سمع يسوع أن يوحنا أسلم ، انصرف إلى الجليل '),
(25324, 'Matthew', 40, 4, 13, ' وترك الناصرة وأتى فسكن في كفرناحوم التي عند البحر في تخوم زبولون ونفتاليم '),
(25325, 'Matthew', 40, 4, 14, ' لكي يتم ما قيل بإشعياء النبي القائل '),
(25326, 'Matthew', 40, 4, 15, ' أرض زبولون ، وأرض نفتاليم ، طريق البحر ، عبر الأردن ، جليل الأمم '),
(25327, 'Matthew', 40, 4, 16, ' الشعب الجالس في ظلمة أبصر نورا عظيما ، والجالسون في كورة الموت وظلاله أشرق عليهم نور '),
(25328, 'Matthew', 40, 4, 17, ' من ذلك الزمان ابتدأ يسوع يكرز ويقول : توبوا لأنه قد اقترب ملكوت السماوات '),
(25329, 'Matthew', 40, 4, 18, ' وإذ كان يسوع ماشيا عند بحر الجليل أبصر أخوين : سمعان الذي يقال له : بطرس ، وأندراوس أخاه يلقيان شبكة في البحر ، فإنهما كانا صيادين '),
(25330, 'Matthew', 40, 4, 19, ' فقال لهما : هلم ورائي فأجعلكما صيادي الناس '),
(25331, 'Matthew', 40, 4, 20, ' فللوقت تركا الشباك وتبعاه '),
(25332, 'Matthew', 40, 4, 21, ' ثم اجتاز من هناك فرأى أخوين آخرين : يعقوب بن زبدي ويوحنا أخاه ، في السفينة مع زبدي أبيهما يصلحان شباكهما ، فدعاهما '),
(25333, 'Matthew', 40, 4, 22, ' فللوقت تركا السفينة وأباهما وتبعاه '),
(25334, 'Matthew', 40, 4, 23, ' وكان يسوع يطوف كل الجليل يعلم في مجامعهم ، ويكرز ببشارة الملكوت ، ويشفي كل مرض وكل ضعف في الشعب '),
(25335, 'Matthew', 40, 4, 24, ' فذاع خبره في جميع سورية . فأحضروا إليه جميع السقماء المصابين بأمراض وأوجاع مختلفة ، والمجانين والمصروعين والمفلوجين ، فشفاهم '),
(25336, 'Matthew', 40, 4, 25, ' فتبعته جموع كثيرة من الجليل والعشر المدن وأورشليم واليهودية ومن عبر الأردن '),
(25337, 'Matthew', 40, 5, 1, ' ولما رأى الجموع صعد إلى الجبل ، فلما جلس تقدم إليه تلاميذه '),
(25338, 'Matthew', 40, 5, 2, ' ففتح فاه وعلمهم قائلا '),
(25339, 'Matthew', 40, 5, 3, ' طوبى للمساكين بالروح ، لأن لهم ملكوت السماوات '),
(25340, 'Matthew', 40, 5, 4, ' طوبى للحزانى ، لأنهم يتعزون '),
(25341, 'Matthew', 40, 5, 5, ' طوبى للودعاء ، لأنهم يرثون الأرض '),
(25342, 'Matthew', 40, 5, 6, ' طوبى للجياع والعطاش إلى البر ، لأنهم يشبعون '),
(25343, 'Matthew', 40, 5, 7, ' طوبى للرحماء ، لأنهم يرحمون '),
(25344, 'Matthew', 40, 5, 8, ' طوبى للأنقياء القلب ، لأنهم يعاينون الله '),
(25345, 'Matthew', 40, 5, 9, ' طوبى لصانعي السلام ، لأنهم أبناء الله يدعون '),
(25346, 'Matthew', 40, 5, 10, ' طوبى للمطرودين من أجل البر ، لأن لهم ملكوت السماوات '),
(25347, 'Matthew', 40, 5, 11, ' طوبى لكم إذا عيروكم وطردوكم وقالوا عليكم كل كلمة شريرة ، من أجلي ، كاذبين '),
(25348, 'Matthew', 40, 5, 12, ' افرحوا وتهللوا ، لأن أجركم عظيم في السماوات ، فإنهم هكذا طردوا الأنبياء الذين قبلكم '),
(25349, 'Matthew', 40, 5, 13, ' أنتم ملح الأرض ، ولكن إن فسد الملح فبماذا يملح ؟ لا يصلح بعد لشيء ، إلا لأن يطرح خارجا ويداس من الناس '),
(25350, 'Matthew', 40, 5, 14, ' أنتم نور العالم . لا يمكن أن تخفى مدينة موضوعة على جبل '),
(25351, 'Matthew', 40, 5, 15, ' ولا يوقدون سراجا ويضعونه تحت المكيال ، بل على المنارة فيضيء لجميع الذين في البيت '),
(25352, 'Matthew', 40, 5, 16, ' فليضئ نوركم هكذا قدام الناس ، لكي يروا أعمالكم الحسنة ، ويمجدوا أباكم الذي في السماوات '),
(25353, 'Matthew', 40, 5, 17, ' لا تظنوا أني جئت لأنقض الناموس أو الأنبياء . ما جئت لأنقض بل لأكمل '),
(25354, 'Matthew', 40, 5, 18, ' فإني الحق أقول لكم : إلى أن تزول السماء والأرض لا يزول حرف واحد أو نقطة واحدة من الناموس حتى يكون الكل '),
(25355, 'Matthew', 40, 5, 19, ' فمن نقض إحدى هذه الوصايا الصغرى وعلم الناس هكذا ، يدعى أصغر في ملكوت السماوات . وأما من عمل وعلم ، فهذا يدعى عظيما في ملكوت السماوات '),
(25356, 'Matthew', 40, 5, 20, ' فإني أقول لكم : إنكم إن لم يزد بركم على الكتبة والفريسيين لن تدخلوا ملكوت السماوات '),
(25357, 'Matthew', 40, 5, 21, ' قد سمعتم أنه قيل للقدماء : لا تقتل ، ومن قتل يكون مستوجب الحكم '),
(25358, 'Matthew', 40, 5, 22, ' وأما أنا فأقول لكم : إن كل من يغضب على أخيه باطلا يكون مستوجب الحكم ، ومن قال لأخيه : رقا ، يكون مستوجب المجمع ، ومن قال : يا أحمق ، يكون مستوجب نار جهنم '),
(25359, 'Matthew', 40, 5, 23, ' فإن قدمت قربانك إلى المذبح ، وهناك تذكرت أن لأخيك شيئا عليك '),
(25360, 'Matthew', 40, 5, 24, ' فاترك هناك قربانك قدام المذبح ، واذهب أولا اصطلح مع أخيك ، وحينئذ تعال وقدم قربانك '),
(25361, 'Matthew', 40, 5, 25, ' كن مراضيا لخصمك سريعا مادمت معه في الطريق ، لئلا يسلمك الخصم إلى القاضي ، ويسلمك القاضي إلى الشرطي ، فتلقى في السجن '),
(25362, 'Matthew', 40, 5, 26, ' الحق أقول لك : لا تخرج من هناك حتى توفي الفلس الأخير '),
(25363, 'Matthew', 40, 5, 27, ' قد سمعتم أنه قيل للقدماء : لا تزن '),
(25364, 'Matthew', 40, 5, 28, ' وأما أنا فأقول لكم : إن كل من ينظر إلى امرأة ليشتهيها ، فقد زنى بها في قلبه '),
(25365, 'Matthew', 40, 5, 29, ' فإن كانت عينك اليمنى تعثرك فاقلعها وألقها عنك ، لأنه خير لك أن يهلك أحد أعضائك ولا يلقى جسدك كله في جهنم '),
(25366, 'Matthew', 40, 5, 30, ' وإن كانت يدك اليمنى تعثرك فاقطعها وألقها عنك ، لأنه خير لك أن يهلك أحد أعضائك ولا يلقى جسدك كله في جهنم '),
(25367, 'Matthew', 40, 5, 31, ' وقيل : من طلق امرأته فليعطها كتاب طلاق '),
(25368, 'Matthew', 40, 5, 32, ' وأما أنا فأقول لكم : إن من طلق امرأته إلا لعلة الزنى يجعلها تزني ، ومن يتزوج مطلقة فإنه يزني '),
(25369, 'Matthew', 40, 5, 33, ' أيضا سمعتم أنه قيل للقدماء : لا تحنث ، بل أوف للرب أقسامك '),
(25370, 'Matthew', 40, 5, 34, ' وأما أنا فأقول لكم : لا تحلفوا البتة ، لا بالسماء لأنها كرسي الله '),
(25371, 'Matthew', 40, 5, 35, ' ولا بالأرض لأنها موطئ قدميه ، ولا بأورشليم لأنها مدينة الملك العظيم '),
(25372, 'Matthew', 40, 5, 36, ' ولا تحلف برأسك ، لأنك لا تقدر أن تجعل شعرة واحدة بيضاء أو سوداء '),
(25373, 'Matthew', 40, 5, 37, ' بل ليكن كلامكم : نعم نعم ، لا لا . وما زاد على ذلك فهو من الشرير '),
(25374, 'Matthew', 40, 5, 38, ' سمعتم أنه قيل : عين بعين وسن بسن '),
(25375, 'Matthew', 40, 5, 39, ' وأما أنا فأقول لكم : لا تقاوموا الشر ، بل من لطمك على خدك الأيمن فحول له الآخر أيضا '),
(25376, 'Matthew', 40, 5, 40, ' ومن أراد أن يخاصمك ويأخذ ثوبك فاترك له الرداء أيضا '),
(25377, 'Matthew', 40, 5, 41, ' ومن سخرك ميلا واحدا فاذهب معه اثنين '),
(25378, 'Matthew', 40, 5, 42, ' من سألك فأعطه ، ومن أراد أن يقترض منك فلا ترده '),
(25379, 'Matthew', 40, 5, 43, ' سمعتم أنه قيل : تحب قريبك وتبغض عدوك '),
(25380, 'Matthew', 40, 5, 44, ' وأما أنا فأقول لكم : أحبوا أعداءكم . باركوا لاعنيكم . أحسنوا إلى مبغضيكم ، وصلوا لأجل الذين يسيئون إليكم ويطردونكم '),
(25381, 'Matthew', 40, 5, 45, ' لكي تكونوا أبناء أبيكم الذي في السماوات ، فإنه يشرق شمسه على الأشرار والصالحين ، ويمطر على الأبرار والظالمين '),
(25382, 'Matthew', 40, 5, 46, ' لأنه إن أحببتم الذين يحبونكم ، فأي أجر لكم ؟ أليس العشارون أيضا يفعلون ذلك '),
(25383, 'Matthew', 40, 5, 47, ' وإن سلمتم على إخوتكم فقط ، فأي فضل تصنعون ؟ أليس العشارون أيضا يفعلون هكذا '),
(25384, 'Matthew', 40, 5, 48, ' فكونوا أنتم كاملين كما أن أباكم الذي في السماوات هو كامل '),
(25385, 'Matthew', 40, 6, 1, ' احترزوا من أن تصنعوا صدقتكم قدام الناس لكي ينظروكم ، وإلا فليس لكم أجر عند أبيكم الذي في السماوات '),
(25386, 'Matthew', 40, 6, 2, ' فمتى صنعت صدقة فلا تصوت قدامك بالبوق ، كما يفعل المراؤون في المجامع وفي الأزقة ، لكي يمجدوا من الناس . الحق أقول لكم : إنهم قد استوفوا أجرهم '),
(25387, 'Matthew', 40, 6, 3, ' وأما أنت فمتى صنعت صدقة فلا تعرف شمالك ما تفعل يمينك '),
(25388, 'Matthew', 40, 6, 4, ' لكي تكون صدقتك في الخفاء . فأبوك الذي يرى في الخفاء هو يجازيك علانية '),
(25389, 'Matthew', 40, 6, 5, ' ومتى صليت فلا تكن كالمرائين ، فإنهم يحبون أن يصلوا قائمين في المجامع وفي زوايا الشوارع ، لكي يظهروا للناس . الحق أقول لكم : إنهم قد استوفوا أجرهم '),
(25390, 'Matthew', 40, 6, 6, ' وأما أنت فمتى صليت فادخل إلى مخدعك وأغلق بابك ، وصل إلى أبيك الذي في الخفاء . فأبوك الذي يرى في الخفاء يجازيك علانية '),
(25391, 'Matthew', 40, 6, 7, ' وحينما تصلون لا تكرروا الكلام باطلا كالأمم ، فإنهم يظنون أنه بكثرة كلامهم يستجاب لهم '),
(25392, 'Matthew', 40, 6, 8, ' فلا تتشبهوا بهم . لأن أباكم يعلم ما تحتاجون إليه قبل أن تسألوه '),
(25393, 'Matthew', 40, 6, 9, ' فصلوا أنتم هكذا : أبانا الذي في السماوات ، ليتقدس اسمك '),
(25394, 'Matthew', 40, 6, 10, ' ليأت ملكوتك . لتكن مشيئتك كما في السماء كذلك على الأرض '),
(25395, 'Matthew', 40, 6, 11, ' خبزنا كفافنا أعطنا اليوم '),
(25396, 'Matthew', 40, 6, 12, ' واغفر لنا ذنوبنا كما نغفر نحن أيضا للمذنبين إلينا '),
(25397, 'Matthew', 40, 6, 13, ' ولا تدخلنا في تجربة ، لكن نجنا من الشرير . لأن لك الملك ، والقوة ، والمجد ، إلى الأبد . آمين '),
(25398, 'Matthew', 40, 6, 14, ' فإنه إن غفرتم للناس زلاتهم ، يغفر لكم أيضا أبوكم السماوي '),
(25399, 'Matthew', 40, 6, 15, ' وإن لم تغفروا للناس زلاتهم ، لا يغفر لكم أبوكم أيضا زلاتكم '),
(25400, 'Matthew', 40, 6, 16, ' ومتى صمتم فلا تكونوا عابسين كالمرائين ، فإنهم يغيرون وجوههم لكي يظهروا للناس صائمين . الحق أقول لكم : إنهم قد استوفوا أجرهم '),
(25401, 'Matthew', 40, 6, 17, ' وأما أنت فمتى صمت فادهن رأسك واغسل وجهك '),
(25402, 'Matthew', 40, 6, 18, ' لكي لا تظهر للناس صائما ، بل لأبيك الذي في الخفاء . فأبوك الذي يرى في الخفاء يجازيك علانية '),
(25403, 'Matthew', 40, 6, 19, ' لا تكنزوا لكم كنوزا على الأرض حيث يفسد السوس والصدأ ، وحيث ينقب السارقون ويسرقون '),
(25404, 'Matthew', 40, 6, 20, ' بل اكنزوا لكم كنوزا في السماء ، حيث لا يفسد سوس ولا صدأ ، وحيث لا ينقب سارقون ولا يسرقون '),
(25405, 'Matthew', 40, 6, 21, ' لأنه حيث يكون كنزك هناك يكون قلبك أيضا '),
(25406, 'Matthew', 40, 6, 22, ' سراج الجسد هو العين ، فإن كانت عينك بسيطة فجسدك كله يكون نيرا '),
(25407, 'Matthew', 40, 6, 23, ' وإن كانت عينك شريرة فجسدك كله يكون مظلما ، فإن كان النور الذي فيك ظلاما فالظلام كم يكون '),
(25408, 'Matthew', 40, 6, 24, ' لا يقدر أحد أن يخدم سيدين ، لأنه إما أن يبغض الواحد ويحب الآخر ، أو يلازم الواحد ويحتقر الآخر . لا تقدرون أن تخدموا الله والمال '),
(25409, 'Matthew', 40, 6, 25, ' لذلك أقول لكم : لا تهتموا لحياتكم بما تأكلون وبما تشربون ، ولا لأجسادكم بما تلبسون . أليست الحياة أفضل من الطعام ، والجسد أفضل من اللباس '),
(25410, 'Matthew', 40, 6, 26, ' انظروا إلى طيور السماء : إنها لا تزرع ولا تحصد ولا تجمع إلى مخازن ، وأبوكم السماوي يقوتها . ألستم أنتم بالحري أفضل منها '),
(25411, 'Matthew', 40, 6, 27, ' ومن منكم إذا اهتم يقدر أن يزيد على قامته ذراعا واحدة '),
(25412, 'Matthew', 40, 6, 28, ' ولماذا تهتمون باللباس ؟ تأملوا زنابق الحقل كيف تنمو لا تتعب ولا تغزل '),
(25413, 'Matthew', 40, 6, 29, ' ولكن أقول لكم : إنه ولا سليمان في كل مجده كان يلبس كواحدة منها '),
(25414, 'Matthew', 40, 6, 30, ' فإن كان عشب الحقل الذي يوجد اليوم ويطرح غدا في التنور ، يلبسه الله هكذا ، أفليس بالحري جدا يلبسكم أنتم يا قليلي الإيمان '),
(25415, 'Matthew', 40, 6, 31, ' فلا تهتموا قائلين : ماذا نأكل ؟ أو ماذا نشرب ؟ أو ماذا نلبس '),
(25416, 'Matthew', 40, 6, 32, ' فإن هذه كلها تطلبها الأمم . لأن أباكم السماوي يعلم أنكم تحتاجون إلى هذه كلها '),
(25417, 'Matthew', 40, 6, 33, ' لكن اطلبوا أولا ملكوت الله وبره ، وهذه كلها تزاد لكم '),
(25418, 'Matthew', 40, 6, 34, ' فلا تهتموا للغد ، لأن الغد يهتم بما لنفسه . يكفي اليوم شره '),
(25419, 'Matthew', 40, 7, 1, ' لا تدينوا لكي لا تدانوا '),
(25420, 'Matthew', 40, 7, 2, ' لأنكم بالدينونة التي بها تدينون تدانون ، وبالكيل الذي به تكيلون يكال لكم '),
(25421, 'Matthew', 40, 7, 3, ' ولماذا تنظر القذى الذي في عين أخيك ، وأما الخشبة التي في عينك فلا تفطن لها '),
(25422, 'Matthew', 40, 7, 4, ' أم كيف تقول لأخيك : دعني أخرج القذى من عينك ، وها الخشبة في عينك '),
(25423, 'Matthew', 40, 7, 5, ' يا مرائي ، أخرج أولا الخشبة من عينك ، وحينئذ تبصر جيدا أن تخرج القذى من عين أخيك '),
(25424, 'Matthew', 40, 7, 6, ' لا تعطوا القدس للكلاب ، ولا تطرحوا درركم قدام الخنازير ، لئلا تدوسها بأرجلها وتلتفت فتمزقكم '),
(25425, 'Matthew', 40, 7, 7, ' اسألوا تعطوا . اطلبوا تجدوا . اقرعوا يفتح لكم '),
(25426, 'Matthew', 40, 7, 8, ' لأن كل من يسأل يأخذ ، ومن يطلب يجد ، ومن يقرع يفتح له '),
(25427, 'Matthew', 40, 7, 9, ' أم أي إنسان منكم إذا سأله ابنه خبزا ، يعطيه حجرا '),
(25428, 'Matthew', 40, 7, 10, ' وإن سأله سمكة ، يعطيه حية '),
(25429, 'Matthew', 40, 7, 11, ' فإن كنتم وأنتم أشرار تعرفون أن تعطوا أولادكم عطايا جيدة ، فكم بالحري أبوكم الذي في السماوات ، يهب خيرات للذين يسألونه '),
(25430, 'Matthew', 40, 7, 12, ' فكل ما تريدون أن يفعل الناس بكم افعلوا هكذا أنتم أيضا بهم ، لأن هذا هو الناموس والأنبياء '),
(25431, 'Matthew', 40, 7, 13, ' ادخلوا من الباب الضيق ، لأنه واسع الباب ورحب الطريق الذي يؤدي إلى الهلاك ، وكثيرون هم الذين يدخلون منه '),
(25432, 'Matthew', 40, 7, 14, ' ما أضيق الباب وأكرب الطريق الذي يؤدي إلى الحياة ، وقليلون هم الذين يجدونه '),
(25433, 'Matthew', 40, 7, 15, ' احترزوا من الأنبياء الكذبة الذين يأتونكم بثياب الحملان ، ولكنهم من داخل ذئاب خاطفة '),
(25434, 'Matthew', 40, 7, 16, ' من ثمارهم تعرفونهم . هل يجتنون من الشوك عنبا ، أو من الحسك تينا '),
(25435, 'Matthew', 40, 7, 17, ' هكذا كل شجرة جيدة تصنع أثمارا جيدة ، وأما الشجرة الردية فتصنع أثمارا ردية '),
(25436, 'Matthew', 40, 7, 18, ' لا تقدر شجرة جيدة أن تصنع أثمارا ردية ، ولا شجرة ردية أن تصنع أثمارا جيدة '),
(25437, 'Matthew', 40, 7, 19, ' كل شجرة لا تصنع ثمرا جيدا تقطع وتلقى في النار '),
(25438, 'Matthew', 40, 7, 20, ' فإذا من ثمارهم تعرفونهم '),
(25439, 'Matthew', 40, 7, 21, ' ليس كل من يقول لي : يا رب ، يا رب يدخل ملكوت السماوات . بل الذي يفعل إرادة أبي الذي في السماوات '),
(25440, 'Matthew', 40, 7, 22, ' كثيرون سيقولون لي في ذلك اليوم : يا رب ، يا رب أليس باسمك تنبأنا ، وباسمك أخرجنا شياطين ، وباسمك صنعنا قوات كثيرة '),
(25441, 'Matthew', 40, 7, 23, ' فحينئذ أصرح لهم : إني لم أعرفكم قط اذهبوا عني يا فاعلي الإثم '),
(25442, 'Matthew', 40, 7, 24, ' فكل من يسمع أقوالي هذه ويعمل بها ، أشبهه برجل عاقل ، بنى بيته على الصخر '),
(25443, 'Matthew', 40, 7, 25, ' فنزل المطر ، وجاءت الأنهار ، وهبت الرياح ، ووقعت على ذلك البيت فلم يسقط ، لأنه كان مؤسسا على الصخر '),
(25444, 'Matthew', 40, 7, 26, ' وكل من يسمع أقوالي هذه ولا يعمل بها ، يشبه برجل جاهل ، بنى بيته على الرمل '),
(25445, 'Matthew', 40, 7, 27, ' فنزل المطر ، وجاءت الأنهار ، وهبت الرياح ، وصدمت ذلك البيت فسقط ، وكان سقوطه عظيما '),
(25446, 'Matthew', 40, 7, 28, ' فلما أكمل يسوع هذه الأقوال بهتت الجموع من تعليمه '),
(25447, 'Matthew', 40, 7, 29, ' لأنه كان يعلمهم كمن له سلطان وليس كالكتبة '),
(25448, 'Matthew', 40, 8, 1, ' ولما نزل من الجبل تبعته جموع كثيرة '),
(25449, 'Matthew', 40, 8, 2, ' وإذا أبرص قد جاء وسجد له قائلا : يا سيد ، إن أردت تقدر أن تطهرني '),
(25450, 'Matthew', 40, 8, 3, ' فمد يسوع يده ولمسه قائلا : أريد ، فاطهر . وللوقت طهر برصه '),
(25451, 'Matthew', 40, 8, 4, ' فقال له يسوع : انظر أن لا تقول لأحد . بل اذهب أر نفسك للكاهن ، وقدم القربان الذي أمر به موسى شهادة لهم '),
(25452, 'Matthew', 40, 8, 5, ' ولما دخل يسوع كفرناحوم ، جاء إليه قائد مئة يطلب إليه '),
(25453, 'Matthew', 40, 8, 6, ' ويقول : يا سيد ، غلامي مطروح في البيت مفلوجا متعذبا جدا '),
(25454, 'Matthew', 40, 8, 7, ' فقال له يسوع : أنا آتي وأشفيه '),
(25455, 'Matthew', 40, 8, 8, ' فأجاب قائد المئة وقال : يا سيد ، لست مستحقا أن تدخل تحت سقفي ، لكن قل كلمة فقط فيبرأ غلامي '),
(25456, 'Matthew', 40, 8, 9, ' لأني أنا أيضا إنسان تحت سلطان . لي جند تحت يدي . أقول لهذا : اذهب فيذهب ، ولآخر : ائت فيأتي ، ولعبدي : افعل هذا فيفعل '),
(25457, 'Matthew', 40, 8, 10, ' فلما سمع يسوع تعجب ، وقال للذين يتبعون : الحق أقول لكم : لم أجد ولا في إسرائيل إيمانا بمقدار هذا '),
(25458, 'Matthew', 40, 8, 11, ' وأقول لكم : إن كثيرين سيأتون من المشارق والمغارب ويتكئون مع إبراهيم وإسحاق ويعقوب في ملكوت السماوات '),
(25459, 'Matthew', 40, 8, 12, ' وأما بنو الملكوت فيطرحون إلى الظلمة الخارجية . هناك يكون البكاء وصرير الأسنان '),
(25460, 'Matthew', 40, 8, 13, ' ثم قال يسوع لقائد المئة : اذهب ، وكما آمنت ليكن لك . فبرأ غلامه في تلك الساعة '),
(25461, 'Matthew', 40, 8, 14, ' ولما جاء يسوع إلى بيت بطرس ، رأى حماته مطروحة ومحمومة '),
(25462, 'Matthew', 40, 8, 15, ' فلمس يدها فتركتها الحمى ، فقامت وخدمتهم '),
(25463, 'Matthew', 40, 8, 16, ' ولما صار المساء قدموا إليه مجانين كثيرين ، فأخرج الأرواح بكلمة ، وجميع المرضى شفاهم '),
(25464, 'Matthew', 40, 8, 17, ' لكي يتم ما قيل بإشعياء النبي القائل : هو أخذ أسقامنا وحمل أمراضنا '),
(25465, 'Matthew', 40, 8, 18, ' ولما رأى يسوع جموعا كثيرة حوله ، أمر بالذهاب إلى العبر '),
(25466, 'Matthew', 40, 8, 19, ' فتقدم كاتب وقال له : يا معلم ، أتبعك أينما تمضي '),
(25467, 'Matthew', 40, 8, 20, ' فقال له يسوع : للثعالب أوجرة ولطيور السماء أوكار ، وأما ابن الإنسان فليس له أين يسند رأسه '),
(25468, 'Matthew', 40, 8, 21, ' وقال له آخر من تلاميذه : يا سيد ، ائذن لي أن أمضي أولا وأدفن أبي '),
(25469, 'Matthew', 40, 8, 22, ' فقال له يسوع : اتبعني ، ودع الموتى يدفنون موتاهم '),
(25470, 'Matthew', 40, 8, 23, ' ولما دخل السفينة تبعه تلاميذه '),
(25471, 'Matthew', 40, 8, 24, ' وإذا اضطراب عظيم قد حدث في البحر حتى غطت الأمواج السفينة ، وكان هو نائما '),
(25472, 'Matthew', 40, 8, 25, ' فتقدم تلاميذه وأيقظوه قائلين : يا سيد ، نجنا فإننا نهلك '),
(25473, 'Matthew', 40, 8, 26, ' فقال لهم : ما بالكم خائفين يا قليلي الإيمان ؟ ثم قام وانتهر الرياح والبحر ، فصار هدو عظيم '),
(25474, 'Matthew', 40, 8, 27, ' فتعجب الناس قائلين : أي إنسان هذا ؟ فإن الرياح والبحر جميعا تطيعه '),
(25475, 'Matthew', 40, 8, 28, ' ولما جاء إلى العبر إلى كورة الجرجسيين ، استقبله مجنونان خارجان من القبور هائجان جدا ، حتى لم يكن أحد يقدر أن يجتاز من تلك الطريق '),
(25476, 'Matthew', 40, 8, 29, ' وإذا هما قد صرخا قائلين : ما لنا ولك يا يسوع ابن الله ؟ أجئت إلى هنا قبل الوقت لتعذبنا '),
(25477, 'Matthew', 40, 8, 30, ' وكان بعيدا منهم قطيع خنازير كثيرة ترعى '),
(25478, 'Matthew', 40, 8, 31, ' فالشياطين طلبوا إليه قائلين : إن كنت تخرجنا ، فأذن لنا أن نذهب إلى قطيع الخنازير '),
(25479, 'Matthew', 40, 8, 32, ' فقال لهم : امضوا . فخرجوا ومضوا إلى قطيع الخنازير ، وإذا قطيع الخنازير كله قد اندفع من على الجرف إلى البحر ، ومات في المياه '),
(25480, 'Matthew', 40, 8, 33, ' أما الرعاة فهربوا ومضوا إلى المدينة ، وأخبروا عن كل شيء ، وعن أمر المجنونين '),
(25481, 'Matthew', 40, 8, 34, ' فإذا كل المدينة قد خرجت لملاقاة يسوع . ولما أبصروه طلبوا أن ينصرف عن تخومهم '),
(25482, 'Matthew', 40, 9, 1, ' فدخل السفينة واجتاز وجاء إلى مدينته '),
(25483, 'Matthew', 40, 9, 2, ' وإذا مفلوج يقدمونه إليه مطروحا على فراش . فلما رأى يسوع إيمانهم قال للمفلوج : ثق يا بني . مغفورة لك خطاياك '),
(25484, 'Matthew', 40, 9, 3, ' وإذا قوم من الكتبة قد قالوا في أنفسهم : هذا يجدف '),
(25485, 'Matthew', 40, 9, 4, ' فعلم يسوع أفكارهم ، فقال : لماذا تفكرون بالشر في قلوبكم '),
(25486, 'Matthew', 40, 9, 5, ' أيما أيسر ، أن يقال : مغفورة لك خطاياك ، أم أن يقال : قم وامش '),
(25487, 'Matthew', 40, 9, 6, ' ولكن لكي تعلموا أن لابن الإنسان سلطانا على الأرض أن يغفر الخطايا . حينئذ قال للمفلوج : قم احمل فراشك واذهب إلى بيتك '),
(25488, 'Matthew', 40, 9, 7, ' فقام ومضى إلى بيته '),
(25489, 'Matthew', 40, 9, 8, ' فلما رأى الجموع تعجبوا ومجدوا الله الذي أعطى الناس سلطانا مثل هذا '),
(25490, 'Matthew', 40, 9, 9, ' وفيما يسوع مجتاز من هناك ، رأى إنسانا جالسا عند مكان الجباية ، اسمه متى . فقال له : اتبعني . فقام وتبعه '),
(25491, 'Matthew', 40, 9, 10, ' وبينما هو متكئ في البيت ، إذا عشارون وخطاة كثيرون قد جاءوا واتكأوا مع يسوع وتلاميذه '),
(25492, 'Matthew', 40, 9, 11, ' فلما نظر الفريسيون قالوا لتلاميذه : لماذا يأكل معلمكم مع العشارين والخطاة '),
(25493, 'Matthew', 40, 9, 12, ' فلما سمع يسوع قال لهم : لا يحتاج الأصحاء إلى طبيب بل المرضى '),
(25494, 'Matthew', 40, 9, 13, ' فاذهبوا وتعلموا ما هو : إني أريد رحمة لا ذبيحة ، لأني لم آت لأدعو أبرارا بل خطاة إلى التوبة '),
(25495, 'Matthew', 40, 9, 14, ' حينئذ أتى إليه تلاميذ يوحنا قائلين : لماذا نصوم نحن والفريسيون كثيرا ، وأما تلاميذك فلا يصومون '),
(25496, 'Matthew', 40, 9, 15, ' فقال لهم يسوع : هل يستطيع بنو العرس أن ينوحوا ما دام العريس معهم ؟ ولكن ستأتي أيام حين يرفع العريس عنهم ، فحينئذ يصومون '),
(25497, 'Matthew', 40, 9, 16, ' ليس أحد يجعل رقعة من قطعة جديدة على ثوب عتيق ، لأن الملء يأخذ من الثوب ، فيصير الخرق أردأ '),
(25498, 'Matthew', 40, 9, 17, ' ولا يجعلون خمرا جديدة في زقاق عتيقة ، لئلا تنشق الزقاق ، فالخمر تنصب والزقاق تتلف . بل يجعلون خمرا جديدة في زقاق جديدة فتحفظ جميعا '),
(25499, 'Matthew', 40, 9, 18, ' وفيما هو يكلمهم بهذا ، إذا رئيس قد جاء فسجد له قائلا : إن ابنتي الآن ماتت ، لكن تعال وضع يدك عليها فتحيا '),
(25500, 'Matthew', 40, 9, 19, ' فقام يسوع وتبعه هو وتلاميذه '),
(25501, 'Matthew', 40, 9, 20, ' وإذا امرأة نازفة دم منذ اثنتي عشرة سنة قد جاءت من ورائه ومست هدب ثوبه '),
(25502, 'Matthew', 40, 9, 21, ' لأنها قالت في نفسها : إن مسست ثوبه فقط شفيت '),
(25503, 'Matthew', 40, 9, 22, ' فالتفت يسوع وأبصرها ، فقال : ثقي يا ابنة ، إيمانك قد شفاك . فشفيت المرأة من تلك الساعة '),
(25504, 'Matthew', 40, 9, 23, ' ولما جاء يسوع إلى بيت الرئيس ، ونظر المزمرين والجمع يضجون '),
(25505, 'Matthew', 40, 9, 24, ' قال لهم : تنحوا ، فإن الصبية لم تمت لكنها نائمة . فضحكوا عليه '),
(25506, 'Matthew', 40, 9, 25, ' فلما أخرج الجمع دخل وأمسك بيدها ، فقامت الصبية '),
(25507, 'Matthew', 40, 9, 26, ' فخرج ذلك الخبر إلى تلك الأرض كلها '),
(25508, 'Matthew', 40, 9, 27, ' وفيما يسوع مجتاز من هناك ، تبعه أعميان يصرخان ويقولان : ارحمنا يا ابن داود '),
(25509, 'Matthew', 40, 9, 28, ' ولما جاء إلى البيت تقدم إليه الأعميان ، فقال لهما يسوع : أتؤمنان أني أقدر أن أفعل هذا ؟ قالا له : نعم ، يا سيد '),
(25510, 'Matthew', 40, 9, 29, ' حينئذ لمس أعينهما قائلا : بحسب إيمانكما ليكن لكما '),
(25511, 'Matthew', 40, 9, 30, ' فانفتحت أعينهما . فانتهرهما يسوع قائلا : انظرا ، لا يعلم أحد '),
(25512, 'Matthew', 40, 9, 31, ' ولكنهما خرجا وأشاعاه في تلك الأرض كلها '),
(25513, 'Matthew', 40, 9, 32, ' وفيما هما خارجان ، إذا إنسان أخرس مجنون قدموه إليه '),
(25514, 'Matthew', 40, 9, 33, ' فلما أخرج الشيطان تكلم الأخرس ، فتعجب الجموع قائلين : لم يظهر قط مثل هذا في إسرائيل '),
(25515, 'Matthew', 40, 9, 34, ' أما الفريسيون فقالوا : برئيس الشياطين يخرج الشياطين '),
(25516, 'Matthew', 40, 9, 35, ' وكان يسوع يطوف المدن كلها والقرى يعلم في مجامعها ، ويكرز ببشارة الملكوت ، ويشفي كل مرض وكل ضعف في الشعب '),
(25517, 'Matthew', 40, 9, 36, ' ولما رأى الجموع تحنن عليهم ، إذ كانوا منزعجين ومنطرحين كغنم لا راعي لها '),
(25518, 'Matthew', 40, 9, 37, ' حينئذ قال لتلاميذه : الحصاد كثير ولكن الفعلة قليلون '),
(25519, 'Matthew', 40, 9, 38, ' فاطلبوا من رب الحصاد أن يرسل فعلة إلى حصاده '),
(25520, 'Matthew', 40, 10, 1, ' ثم دعا تلاميذه الاثني عشر وأعطاهم سلطانا على أرواح نجسة حتى يخرجوها ، ويشفوا كل مرض وكل ضعف '),
(25521, 'Matthew', 40, 10, 2, ' وأما أسماء الاثني عشر رسولا فهي هذه : الأول سمعان الذي يقال له : بطرس ، وأندراوس أخوه . يعقوب بن زبدي ، ويوحنا أخوه '),
(25522, 'Matthew', 40, 10, 3, ' فيلبس ، وبرثولماوس . توما ، ومتى العشار . يعقوب بن حلفى ، ولباوس الملقب تداوس '),
(25523, 'Matthew', 40, 10, 4, ' سمعان القانوي ، ويهوذا الإسخريوطي الذي أسلمه '),
(25524, 'Matthew', 40, 10, 5, ' هؤلاء الاثنا عشر أرسلهم يسوع وأوصاهم قائلا : إلى طريق أمم لا تمضوا ، وإلى مدينة للسامريين لا تدخلوا '),
(25525, 'Matthew', 40, 10, 6, ' بل اذهبوا بالحري إلى خراف بيت إسرائيل الضالة '),
(25526, 'Matthew', 40, 10, 7, ' وفيما أنتم ذاهبون اكرزوا قائلين : إنه قد اقترب ملكوت السماوات '),
(25527, 'Matthew', 40, 10, 8, ' اشفوا مرضى . طهروا برصا . أقيموا موتى . أخرجوا شياطين . مجانا أخذتم ، مجانا أعطوا '),
(25528, 'Matthew', 40, 10, 9, ' لا تقتنوا ذهبا ولا فضة ولا نحاسا في مناطقكم '),
(25529, 'Matthew', 40, 10, 10, ' ولا مزودا للطريق ولا ثوبين ولا أحذية ولا عصا ، لأن الفاعل مستحق طعامه '),
(25530, 'Matthew', 40, 10, 11, ' وأية مدينة أو قرية دخلتموها فافحصوا من فيها مستحق ، وأقيموا هناك حتى تخرجوا '),
(25531, 'Matthew', 40, 10, 12, ' وحين تدخلون البيت سلموا عليه '),
(25532, 'Matthew', 40, 10, 13, ' فإن كان البيت مستحقا فليأت سلامكم عليه ، ولكن إن لم يكن مستحقا فليرجع سلامكم إليكم '),
(25533, 'Matthew', 40, 10, 14, ' ومن لا يقبلكم ولا يسمع كلامكم فاخرجوا خارجا من ذلك البيت أو من تلك المدينة ، وانفضوا غبار أرجلكم '),
(25534, 'Matthew', 40, 10, 15, ' الحق أقول لكم : ستكون لأرض سدوم وعمورة يوم الدين حالة أكثر احتمالا مما لتلك المدينة '),
(25535, 'Matthew', 40, 10, 16, ' ها أنا أرسلكم كغنم في وسط ذئاب ، فكونوا حكماء كالحيات وبسطاء كالحمام '),
(25536, 'Matthew', 40, 10, 17, ' ولكن احذروا من الناس ، لأنهم سيسلمونكم إلى مجالس ، وفي مجامعهم يجلدونكم '),
(25537, 'Matthew', 40, 10, 18, ' وتساقون أمام ولاة وملوك من أجلي شهادة لهم وللأمم '),
(25538, 'Matthew', 40, 10, 19, ' فمتى أسلموكم فلا تهتموا كيف أو بما تتكلمون ، لأنكم تعطون في تلك الساعة ما تتكلمون به '),
(25539, 'Matthew', 40, 10, 20, ' لأن لستم أنتم المتكلمين بل روح أبيكم الذي يتكلم فيكم '),
(25540, 'Matthew', 40, 10, 21, ' وسيسلم الأخ أخاه إلى الموت ، والأب ولده ، ويقوم الأولاد على والديهم ويقتلونهم '),
(25541, 'Matthew', 40, 10, 22, ' وتكونون مبغضين من الجميع من أجل اسمي . ولكن الذي يصبر إلى المنتهى فهذا يخلص '),
(25542, 'Matthew', 40, 10, 23, ' ومتى طردوكم في هذه المدينة فاهربوا إلى الأخرى . فإني الحق أقول لكم : لا تكملون مدن إسرائيل حتى يأتي ابن الإنسان '),
(25543, 'Matthew', 40, 10, 24, ' ليس التلميذ أفضل من المعلم ، ولا العبد أفضل من سيده '),
(25544, 'Matthew', 40, 10, 25, ' يكفي التلميذ أن يكون كمعلمه ، والعبد كسيده . إن كانوا قد لقبوا رب البيت بعلزبول ، فكم بالحري أهل بيته '),
(25545, 'Matthew', 40, 10, 26, ' فلا تخافوهم . لأن ليس مكتوم لن يستعلن ، ولا خفي لن يعرف '),
(25546, 'Matthew', 40, 10, 27, ' الذي أقوله لكم في الظلمة قولوه في النور ، والذي تسمعونه في الأذن نادوا به على السطوح '),
(25547, 'Matthew', 40, 10, 28, ' ولا تخافوا من الذين يقتلون الجسد ولكن النفس لا يقدرون أن يقتلوها ، بل خافوا بالحري من الذي يقدر أن يهلك النفس والجسد كليهما في جهنم '),
(25548, 'Matthew', 40, 10, 29, ' أليس عصفوران يباعان بفلس ؟ وواحد منهما لا يسقط على الأرض بدون أبيكم '),
(25549, 'Matthew', 40, 10, 30, ' وأما أنتم فحتى شعور رؤوسكم جميعها محصاة '),
(25550, 'Matthew', 40, 10, 31, ' فلا تخافوا أنتم أفضل من عصافير كثيرة '),
(25551, 'Matthew', 40, 10, 32, ' فكل من يعترف بي قدام الناس أعترف أنا أيضا به قدام أبي الذي في السماوات '),
(25552, 'Matthew', 40, 10, 33, ' ولكن من ينكرني قدام الناس أنكره أنا أيضا قدام أبي الذي في السماوات '),
(25553, 'Matthew', 40, 10, 34, ' لا تظنوا أني جئت لألقي سلاما على الأرض . ما جئت لألقي سلاما بل سيفا '),
(25554, 'Matthew', 40, 10, 35, ' فإني جئت لأفرق الإنسان ضد أبيه ، والابنة ضد أمها ، والكنة ضد حماتها '),
(25555, 'Matthew', 40, 10, 36, ' وأعداء الإنسان أهل بيته '),
(25556, 'Matthew', 40, 10, 37, ' من أحب أبا أو أما أكثر مني فلا يستحقني ، ومن أحب ابنا أو ابنة أكثر مني فلا يستحقني '),
(25557, 'Matthew', 40, 10, 38, ' ومن لا يأخذ صليبه ويتبعني فلا يستحقني '),
(25558, 'Matthew', 40, 10, 39, ' من وجد حياته يضيعها ، ومن أضاع حياته من أجلي يجدها '),
(25559, 'Matthew', 40, 10, 40, ' من يقبلكم يقبلني ، ومن يقبلني يقبل الذي أرسلني '),
(25560, 'Matthew', 40, 10, 41, ' من يقبل نبيا باسم نبي فأجر نبي يأخذ ، ومن يقبل بارا باسم بار فأجر بار يأخذ '),
(25561, 'Matthew', 40, 10, 42, ' ومن سقى أحد هؤلاء الصغار كأس ماء بارد فقط باسم تلميذ ، فالحق أقول لكم : إنه لا يضيع أجره '),
(25562, 'Matthew', 40, 11, 1, ' ولما أكمل يسوع أمره لتلاميذه الاثني عشر ، انصرف من هناك ليعلم ويكرز في مدنهم '),
(25563, 'Matthew', 40, 11, 2, ' أما يوحنا فلما سمع في السجن بأعمال المسيح ، أرسل اثنين من تلاميذه '),
(25564, 'Matthew', 40, 11, 3, ' وقال له : أنت هو الآتي أم ننتظر آخر '),
(25565, 'Matthew', 40, 11, 4, ' فأجاب يسوع وقال لهما : اذهبا وأخبرا يوحنا بما تسمعان وتنظران '),
(25566, 'Matthew', 40, 11, 5, ' العمي يبصرون ، والعرج يمشون ، والبرص يطهرون ، والصم يسمعون ، والموتى يقومون ، والمساكين يبشرون '),
(25567, 'Matthew', 40, 11, 6, ' وطوبى لمن لا يعثر في '),
(25568, 'Matthew', 40, 11, 7, ' وبينما ذهب هذان ابتدأ يسوع يقول للجموع عن يوحنا : ماذا خرجتم إلى البرية لتنظروا ؟ أقصبة تحركها الريح '),
(25569, 'Matthew', 40, 11, 8, ' لكن ماذا خرجتم لتنظروا ؟ أإنسانا لابسا ثيابا ناعمة ؟ هوذا الذين يلبسون الثياب الناعمة هم في بيوت الملوك '),
(25570, 'Matthew', 40, 11, 9, ' لكن ماذا خرجتم لتنظروا ؟ أنبيا ؟ نعم ، أقول لكم ، وأفضل من نبي '),
(25571, 'Matthew', 40, 11, 10, ' فإن هذا هو الذي كتب عنه : ها أنا أرسل أمام وجهك ملاكي الذي يهيئ طريقك قدامك '),
(25572, 'Matthew', 40, 11, 11, ' الحق أقول لكم : لم يقم بين المولودين من النساء أعظم من يوحنا المعمدان ، ولكن الأصغر في ملكوت السماوات أعظم منه '),
(25573, 'Matthew', 40, 11, 12, ' ومن أيام يوحنا المعمدان إلى الآن ملكوت السماوات يغصب ، والغاصبون يختطفونه ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(25574, 'Matthew', 40, 11, 13, ' لأن جميع الأنبياء والناموس إلى يوحنا تنبأوا '),
(25575, 'Matthew', 40, 11, 14, ' وإن أردتم أن تقبلوا ، فهذا هو إيليا المزمع أن يأتي '),
(25576, 'Matthew', 40, 11, 15, ' من له أذنان للسمع فليسمع '),
(25577, 'Matthew', 40, 11, 16, ' وبمن أشبه هذا الجيل ؟ يشبه أولادا جالسين في الأسواق ينادون إلى أصحابهم '),
(25578, 'Matthew', 40, 11, 17, ' ويقولون : زمرنا لكم فلم ترقصوا نحنا لكم فلم تلطموا '),
(25579, 'Matthew', 40, 11, 18, ' لأنه جاء يوحنا لا يأكل ولا يشرب ، فيقولون : فيه شيطان '),
(25580, 'Matthew', 40, 11, 19, ' جاء ابن الإنسان يأكل ويشرب ، فيقولون : هوذا إنسان أكول وشريب خمر ، محب للعشارين والخطاة . والحكمة تبررت من بنيها '),
(25581, 'Matthew', 40, 11, 20, ' حينئذ ابتدأ يوبخ المدن التي صنعت فيها أكثر قواته لأنها لم تتب '),
(25582, 'Matthew', 40, 11, 21, ' ويل لك يا كورزين ويل لك يا بيت صيدا لأنه لو صنعت في صور وصيداء القوات المصنوعة فيكما ، لتابتا قديما في المسوح والرماد '),
(25583, 'Matthew', 40, 11, 22, ' ولكن أقول لكم : إن صور وصيداء تكون لهما حالة أكثر احتمالا يوم الدين مما لكما '),
(25584, 'Matthew', 40, 11, 23, ' وأنت يا كفرناحوم المرتفعة إلى السماء ستهبطين إلى الهاوية . لأنه لو صنعت في سدوم القوات المصنوعة فيك لبقيت إلى اليوم '),
(25585, 'Matthew', 40, 11, 24, ' ولكن أقول لكم : إن أرض سدوم تكون لها حالة أكثر احتمالا يوم الدين مما لك '),
(25586, 'Matthew', 40, 11, 25, ' في ذلك الوقت أجاب يسوع وقال : أحمدك أيها الآب رب السماء والأرض ، لأنك أخفيت هذه عن الحكماء والفهماء وأعلنتها للأطفال '),
(25587, 'Matthew', 40, 11, 26, ' نعم أيها الآب ، لأن هكذا صارت المسرة أمامك '),
(25588, 'Matthew', 40, 11, 27, ' كل شيء قد دفع إلي من أبي ، وليس أحد يعرف الابن إلا الآب ، ولا أحد يعرف الآب إلا الابن ومن أراد الابن أن يعلن له '),
(25589, 'Matthew', 40, 11, 28, ' تعالوا إلي يا جميع المتعبين والثقيلي الأحمال ، وأنا أريحكم '),
(25590, 'Matthew', 40, 11, 29, ' احملوا نيري عليكم وتعلموا مني ، لأني وديع ومتواضع القلب ، فتجدوا راحة لنفوسكم '),
(25591, 'Matthew', 40, 11, 30, ' لأن نيري هين وحملي خفيف '),
(25592, 'Matthew', 40, 12, 1, ' في ذلك الوقت ذهب يسوع في السبت بين الزروع ، فجاع تلاميذه وابتدأوا يقطفون سنابل ويأكلون '),
(25593, 'Matthew', 40, 12, 2, ' فالفريسيون لما نظروا قالوا له : هوذا تلاميذك يفعلون ما لا يحل فعله في السبت '),
(25594, 'Matthew', 40, 12, 3, ' فقال لهم : أما قرأتم ما فعله داود حين جاع هو والذين معه '),
(25595, 'Matthew', 40, 12, 4, ' كيف دخل بيت الله وأكل خبز التقدمة ، الذي لم يحل أكله له ولا للذين معه ، بل للكهنة فقط '),
(25596, 'Matthew', 40, 12, 5, ' أو ما قرأتم في التوراة أن الكهنة في السبت في الهيكل يدنسون السبت وهم أبرياء '),
(25597, 'Matthew', 40, 12, 6, ' ولكن أقول لكم : إن ههنا أعظم من الهيكل '),
(25598, 'Matthew', 40, 12, 7, ' فلو علمتم ما هو : إني أريد رحمة لا ذبيحة ، لما حكمتم على الأبرياء '),
(25599, 'Matthew', 40, 12, 8, ' فإن ابن الإنسان هو رب السبت أيضا '),
(25600, 'Matthew', 40, 12, 9, ' ثم انصرف من هناك وجاء إلى مجمعهم '),
(25601, 'Matthew', 40, 12, 10, ' وإذا إنسان يده يابسة ، فسألوه قائلين : هل يحل الإبراء في السبوت ؟ لكي يشتكوا عليه '),
(25602, 'Matthew', 40, 12, 11, ' فقال لهم : أي إنسان منكم يكون له خروف واحد ، فإن سقط هذا في السبت في حفرة ، أفما يمسكه ويقيمه '),
(25603, 'Matthew', 40, 12, 12, ' فالإنسان كم هو أفضل من الخروف إذا يحل فعل الخير في السبوت '),
(25604, 'Matthew', 40, 12, 13, ' ثم قال للإنسان : مد يدك . فمدها . فعادت صحيحة كالأخرى '),
(25605, 'Matthew', 40, 12, 14, ' فلما خرج الفريسيون تشاوروا عليه لكي يهلكوه '),
(25606, 'Matthew', 40, 12, 15, ' فعلم يسوع وانصرف من هناك . وتبعته جموع كثيرة فشفاهم جميعا '),
(25607, 'Matthew', 40, 12, 16, ' وأوصاهم أن لا يظهروه '),
(25608, 'Matthew', 40, 12, 17, ' لكي يتم ما قيل بإشعياء النبي القائل '),
(25609, 'Matthew', 40, 12, 18, ' هوذا فتاي الذي اخترته ، حبيبي الذي سرت به نفسي . أضع روحي عليه فيخبر الأمم بالحق '),
(25610, 'Matthew', 40, 12, 19, ' لا يخاصم ولا يصيح ، ولا يسمع أحد في الشوارع صوته '),
(25611, 'Matthew', 40, 12, 20, ' قصبة مرضوضة لا يقصف ، وفتيلة مدخنة لا يطفئ ، حتى يخرج الحق إلى النصرة '),
(25612, 'Matthew', 40, 12, 21, ' وعلى اسمه يكون رجاء الأمم. '),
(25613, 'Matthew', 40, 12, 22, ' حينئذ أحضر إليه مجنون أعمى وأخرس فشفاه ، حتى إن الأعمى الأخرس تكلم وأبصر '),
(25614, 'Matthew', 40, 12, 23, ' فبهت كل الجموع وقالوا : ألعل هذا هو ابن داود '),
(25615, 'Matthew', 40, 12, 24, ' أما الفريسيون فلما سمعوا قالوا : هذا لا يخرج الشياطين إلا ببعلزبول رئيس الشياطين '),
(25616, 'Matthew', 40, 12, 25, ' فعلم يسوع أفكارهم ، وقال لهم : كل مملكة منقسمة على ذاتها تخرب ، وكل مدينة أو بيت منقسم على ذاته لا يثبت '),
(25617, 'Matthew', 40, 12, 26, ' فإن كان الشيطان يخرج الشيطان فقد انقسم على ذاته . فكيف تثبت مملكته '),
(25618, 'Matthew', 40, 12, 27, ' وإن كنت أنا ببعلزبول أخرج الشياطين ، فأبناؤكم بمن يخرجون ؟ لذلك هم يكونون قضاتكم '),
(25619, 'Matthew', 40, 12, 28, ' ولكن إن كنت أنا بروح الله أخرج الشياطين ، فقد أقبل عليكم ملكوت الله '),
(25620, 'Matthew', 40, 12, 29, ' أم كيف يستطيع أحد أن يدخل بيت القوي وينهب أمتعته ، إن لم يربط القوي أولا ، وحينئذ ينهب بيته '),
(25621, 'Matthew', 40, 12, 30, ' من ليس معي فهو علي ، ومن لا يجمع معي فهو يفرق '),
(25622, 'Matthew', 40, 12, 31, ' لذلك أقول لكم : كل خطية وتجديف يغفر للناس ، وأما التجديف على الروح فلن يغفر للناس '),
(25623, 'Matthew', 40, 12, 32, ' ومن قال كلمة على ابن الإنسان يغفر له ، وأما من قال على الروح القدس فلن يغفر له ، لا في هذا العالم ولا في الآتي '),
(25624, 'Matthew', 40, 12, 33, ' اجعلوا الشجرة جيدة وثمرها جيدا ، أو اجعلوا الشجرة ردية وثمرها رديا ، لأن من الثمر تعرف الشجرة '),
(25625, 'Matthew', 40, 12, 34, ' يا أولاد الأفاعي كيف تقدرون أن تتكلموا بالصالحات وأنتم أشرار ؟ فإنه من فضلة القلب يتكلم الفم '),
(25626, 'Matthew', 40, 12, 35, ' الإنسان الصالح من الكنز الصالح في القلب يخرج الصالحات ، والإنسان الشرير من الكنز الشرير يخرج الشرور '),
(25627, 'Matthew', 40, 12, 36, ' ولكن أقول لكم : إن كل كلمة بطالة يتكلم بها الناس سوف يعطون عنها حسابا يوم الدين '),
(25628, 'Matthew', 40, 12, 37, ' لأنك بكلامك تتبرر وبكلامك تدان '),
(25629, 'Matthew', 40, 12, 38, ' حينئذ أجاب قوم من الكتبة والفريسيين قائلين : يا معلم ، نريد أن نرى منك آية '),
(25630, 'Matthew', 40, 12, 39, ' فأجاب وقال لهم : جيل شرير وفاسق يطلب آية ، ولا تعطى له آية إلا آية يونان النبي '),
(25631, 'Matthew', 40, 12, 40, ' لأنه كما كان يونان في بطن الحوت ثلاثة أيام وثلاث ليال ، هكذا يكون ابن الإنسان في قلب الأرض ثلاثة أيام وثلاث ليال '),
(25632, 'Matthew', 40, 12, 41, ' رجال نينوى سيقومون في الدين مع هذا الجيل ويدينونه ، لأنهم تابوا بمناداة يونان ، وهوذا أعظم من يونان ههنا '),
(25633, 'Matthew', 40, 12, 42, ' ملكة التيمن ستقوم في الدين مع هذا الجيل وتدينه ، لأنها أتت من أقاصي الأرض لتسمع حكمة سليمان ، وهوذا أعظم من سليمان ههنا '),
(25634, 'Matthew', 40, 12, 43, ' إذا خرج الروح النجس من الإنسان يجتاز في أماكن ليس فيها ماء ، يطلب راحة ولا يجد '),
(25635, 'Matthew', 40, 12, 44, ' ثم يقول : أرجع إلى بيتي الذي خرجت منه . فيأتي ويجده فارغا مكنوسا مزينا '),
(25636, 'Matthew', 40, 12, 45, ' ثم يذهب ويأخذ معه سبعة أرواح أخر أشر منه ، فتدخل وتسكن هناك ، فتصير أواخر ذلك الإنسان أشر من أوائله هكذا يكون أيضا لهذا الجيل الشرير '),
(25637, 'Matthew', 40, 12, 46, ' وفيما هو يكلم الجموع إذا أمه وإخوته قد وقفوا خارجا طالبين أن يكلموه '),
(25638, 'Matthew', 40, 12, 47, ' فقال له واحد : هوذا أمك وإخوتك واقفون خارجا طالبين أن يكلموك '),
(25639, 'Matthew', 40, 12, 48, ' فأجاب وقال للقائل له : من هي أمي ومن هم إخوتي '),
(25640, 'Matthew', 40, 12, 49, ' ثم مد يده نحو تلاميذه وقال : ها أمي وإخوتي '),
(25641, 'Matthew', 40, 12, 50, ' لأن من يصنع مشيئة أبي الذي في السماوات هو أخي وأختي وأمي '),
(25642, 'Matthew', 40, 13, 1, ' في ذلك اليوم خرج يسوع من البيت وجلس عند البحر '),
(25643, 'Matthew', 40, 13, 2, ' فاجتمع إليه جموع كثيرة ، حتى إنه دخل السفينة وجلس . والجمع كله وقف على الشاطئ '),
(25644, 'Matthew', 40, 13, 3, ' فكلمهم كثيرا بأمثال قائلا : هوذا الزارع قد خرج ليزرع '),
(25645, 'Matthew', 40, 13, 4, ' وفيما هو يزرع سقط بعض على الطريق ، فجاءت الطيور وأكلته '),
(25646, 'Matthew', 40, 13, 5, ' وسقط آخر على الأماكن المحجرة ، حيث لم تكن له تربة كثيرة ، فنبت حالا إذ لم يكن له عمق أرض '),
(25647, 'Matthew', 40, 13, 6, ' ولكن لما أشرقت الشمس احترق ، وإذ لم يكن له أصل جف '),
(25648, 'Matthew', 40, 13, 7, ' وسقط آخر على الشوك ، فطلع الشوك وخنقه '),
(25649, 'Matthew', 40, 13, 8, ' وسقط آخر على الأرض الجيدة فأعطى ثمرا ، بعض مئة وآخر ستين وآخر ثلاثين '),
(25650, 'Matthew', 40, 13, 9, ' من له أذنان للسمع ، فليسمع '),
(25651, 'Matthew', 40, 13, 10, ' فتقدم التلاميذ وقالوا له : لماذا تكلمهم بأمثال '),
(25652, 'Matthew', 40, 13, 11, ' فأجاب وقال لهم : لأنه قد أعطي لكم أن تعرفوا أسرار ملكوت السماوات ، وأما لأولئك فلم يعط '),
(25653, 'Matthew', 40, 13, 12, ' فإن من له سيعطى ويزاد ، وأما من ليس له فالذي عنده سيؤخذ منه '),
(25654, 'Matthew', 40, 13, 13, ' من أجل هذا أكلمهم بأمثال ، لأنهم مبصرين لا يبصرون ، وسامعين لا يسمعون ولا يفهمون '),
(25655, 'Matthew', 40, 13, 14, ' فقد تمت فيهم نبوة إشعياء القائلة : تسمعون سمعا ولا تفهمون ، ومبصرين تبصرون ولا تنظرون '),
(25656, 'Matthew', 40, 13, 15, ' لأن قلب هذا الشعب قد غلظ ، وآذانهم قد ثقل سماعها . وغمضوا عيونهم ، لئلا يبصروا بعيونهم ، ويسمعوا بآذانهم ، ويفهموا بقلوبهم ، ويرجعوا فأشفيهم '),
(25657, 'Matthew', 40, 13, 16, ' ولكن طوبى لعيونكم لأنها تبصر ، ولآذانكم لأنها تسمع '),
(25658, 'Matthew', 40, 13, 17, ' فإني الحق أقول لكم : إن أنبياء وأبرارا كثيرين اشتهوا أن يروا ما أنتم ترون ولم يروا ، وأن يسمعوا ما أنتم تسمعون ولم يسمعوا '),
(25659, 'Matthew', 40, 13, 18, ' فاسمعوا أنتم مثل الزارع '),
(25660, 'Matthew', 40, 13, 19, ' كل من يسمع كلمة الملكوت ولا يفهم ، فيأتي الشرير ويخطف ما قد زرع في قلبه . هذا هو المزروع على الطريق '),
(25661, 'Matthew', 40, 13, 20, ' والمزروع على الأماكن المحجرة هو الذي يسمع الكلمة ، وحالا يقبلها بفرح '),
(25662, 'Matthew', 40, 13, 21, ' ولكن ليس له أصل في ذاته ، بل هو إلى حين . فإذا حدث ضيق أو اضطهاد من أجل الكلمة فحالا يعثر '),
(25663, 'Matthew', 40, 13, 22, ' والمزروع بين الشوك هو الذي يسمع الكلمة ، وهم هذا العالم وغرور الغنى يخنقان الكلمة فيصير بلا ثمر '),
(25664, 'Matthew', 40, 13, 23, ' وأما المزروع على الأرض الجيدة فهو الذي يسمع الكلمة ويفهم . وهو الذي يأتي بثمر ، فيصنع بعض مئة وآخر ستين وآخر ثلاثين '),
(25665, 'Matthew', 40, 13, 24, ' قدم لهم مثلا آخر قائلا : يشبه ملكوت السماوات إنسانا زرع زرعا جيدا في حقله '),
(25666, 'Matthew', 40, 13, 25, ' وفيما الناس نيام جاء عدوه وزرع زوانا في وسط الحنطة ومضى '),
(25667, 'Matthew', 40, 13, 26, ' فلما طلع النبات وصنع ثمرا ، حينئذ ظهر الزوان أيضا '),
(25668, 'Matthew', 40, 13, 27, ' فجاء عبيد رب البيت وقالوا له : يا سيد ، أليس زرعا جيدا زرعت في حقلك ؟ فمن أين له زوان '),
(25669, 'Matthew', 40, 13, 28, ' فقال لهم : إنسان عدو فعل هذا . فقال له العبيد : أتريد أن نذهب ونجمعه '),
(25670, 'Matthew', 40, 13, 29, ' فقال : لا لئلا تقلعوا الحنطة مع الزوان وأنتم تجمعونه '),
(25671, 'Matthew', 40, 13, 30, ' دعوهما ينميان كلاهما معا إلى الحصاد ، وفي وقت الحصاد أقول للحصادين : اجمعوا أولا الزوان واحزموه حزما ليحرق ، وأما الحنطة فاجمعوها إلى مخزني '),
(25672, 'Matthew', 40, 13, 31, ' قدم لهم مثلا آخر قائلا : يشبه ملكوت السماوات حبة خردل أخذها إنسان وزرعها في حقله '),
(25673, 'Matthew', 40, 13, 32, ' وهي أصغر جميع البزور . ولكن متى نمت فهي أكبر البقول ، وتصير شجرة ، حتى إن طيور السماء تأتي وتتآوى في أغصانها '),
(25674, 'Matthew', 40, 13, 33, ' قال لهم مثلا آخر : يشبه ملكوت السماوات خميرة أخذتها امرأة وخبأتها في ثلاثة أكيال دقيق حتى اختمر الجميع '),
(25675, 'Matthew', 40, 13, 34, ' هذا كله كلم به يسوع الجموع بأمثال ، وبدون مثل لم يكن يكلمهم '),
(25676, 'Matthew', 40, 13, 35, ' لكي يتم ما قيل بالنبي القائل : سأفتح بأمثال فمي ، وأنطق بمكتومات منذ تأسيس العالم '),
(25677, 'Matthew', 40, 13, 36, ' حينئذ صرف يسوع الجموع وجاء إلى البيت . فتقدم إليه تلاميذه قائلين : فسر لنا مثل زوان الحقل '),
(25678, 'Matthew', 40, 13, 37, ' فأجاب وقال لهم : الزارع الزرع الجيد هو ابن الإنسان '),
(25679, 'Matthew', 40, 13, 38, ' والحقل هو العالم . والزرع الجيد هو بنو الملكوت . والزوان هو بنو الشرير '),
(25680, 'Matthew', 40, 13, 39, ' والعدو الذي زرعه هو إبليس . والحصاد هو انقضاء العالم . والحصادون هم الملائكة '),
(25681, 'Matthew', 40, 13, 40, ' فكما يجمع الزوان ويحرق بالنار ، هكذا يكون في انقضاء هذا العالم '),
(25682, 'Matthew', 40, 13, 41, ' يرسل ابن الإنسان ملائكته فيجمعون من ملكوته جميع المعاثر وفاعلي الإثم '),
(25683, 'Matthew', 40, 13, 42, ' ويطرحونهم في أتون النار . هناك يكون البكاء وصرير الأسنان '),
(25684, 'Matthew', 40, 13, 43, ' حينئذ يضيء الأبرار كالشمس في ملكوت أبيهم . من له أذنان للسمع ، فليسمع '),
(25685, 'Matthew', 40, 13, 44, ' أيضا يشبه ملكوت السماوات كنزا مخفى في حقل ، وجده إنسان فأخفاه . ومن فرحه مضى وباع كل ما كان له واشترى ذلك الحقل '),
(25686, 'Matthew', 40, 13, 45, ' أيضا يشبه ملكوت السماوات إنسانا تاجرا يطلب لآلئ حسنة '),
(25687, 'Matthew', 40, 13, 46, ' فلما وجد لؤلؤة واحدة كثيرة الثمن ، مضى وباع كل ما كان له واشتراها '),
(25688, 'Matthew', 40, 13, 47, ' أيضا يشبه ملكوت السماوات شبكة مطروحة في البحر ، وجامعة من كل نوع '),
(25689, 'Matthew', 40, 13, 48, ' فلما امتلأت أصعدوها على الشاطئ ، وجلسوا وجمعوا الجياد إلى أوعية ، وأما الأردياء فطرحوها خارجا '),
(25690, 'Matthew', 40, 13, 49, ' هكذا يكون في انقضاء العالم : يخرج الملائكة ويفرزون الأشرار من بين الأبرار '),
(25691, 'Matthew', 40, 13, 50, ' ويطرحونهم في أتون النار . هناك يكون البكاء وصرير الأسنان '),
(25692, 'Matthew', 40, 13, 51, ' قال لهم يسوع : أفهمتم هذا كله ؟ فقالوا : نعم ، يا سيد '),
(25693, 'Matthew', 40, 13, 52, ' فقال لهم : من أجل ذلك كل كاتب متعلم في ملكوت السماوات يشبه رجلا رب بيت يخرج من كنزه جددا وعتقاء '),
(25694, 'Matthew', 40, 13, 53, ' ولما أكمل يسوع هذه الأمثال انتقل من هناك '),
(25695, 'Matthew', 40, 13, 54, ' ولما جاء إلى وطنه كان يعلمهم في مجمعهم حتى بهتوا وقالوا : من أين لهذا هذه الحكمة والقوات '),
(25696, 'Matthew', 40, 13, 55, ' أليس هذا ابن النجار ؟ أليست أمه تدعى مريم ، وإخوته يعقوب ويوسي وسمعان ويهوذا '),
(25697, 'Matthew', 40, 13, 56, ' أو ليست أخواته جميعهن عندنا ؟ فمن أين لهذا هذه كلها '),
(25698, 'Matthew', 40, 13, 57, ' فكانوا يعثرون به . وأما يسوع فقال لهم : ليس نبي بلا كرامة إلا في وطنه وفي بيته '),
(25699, 'Matthew', 40, 13, 58, ' ولم يصنع هناك قوات كثيرة لعدم إيمانهم '),
(25700, 'Matthew', 40, 14, 1, ' في ذلك الوقت سمع هيرودس رئيس الربع خبر يسوع '),
(25701, 'Matthew', 40, 14, 2, ' فقال لغلمانه : هذا هو يوحنا المعمدان قد قام من الأموات ولذلك تعمل به القوات '),
(25702, 'Matthew', 40, 14, 3, ' فإن هيرودس كان قد أمسك يوحنا وأوثقه وطرحه في سجن من أجل هيروديا امرأة فيلبس أخيه '),
(25703, 'Matthew', 40, 14, 4, ' لأن يوحنا كان يقول له : لا يحل أن تكون لك '),
(25704, 'Matthew', 40, 14, 5, ' ولما أراد أن يقتله خاف من الشعب ، لأنه كان عندهم مثل نبي '),
(25705, 'Matthew', 40, 14, 6, ' ثم لما صار مولد هيرودس ، رقصت ابنة هيروديا في الوسط فسرت هيرودس '),
(25706, 'Matthew', 40, 14, 7, ' من ثم وعد بقسم أنه مهما طلبت يعطيها '),
(25707, 'Matthew', 40, 14, 8, ' فهي إذ كانت قد تلقنت من أمها قالت : أعطني ههنا على طبق رأس يوحنا المعمدان '),
(25708, 'Matthew', 40, 14, 9, ' فاغتم الملك . ولكن من أجل الأقسام والمتكئين معه أمر أن يعطى '),
(25709, 'Matthew', 40, 14, 10, ' فأرسل وقطع رأس يوحنا في السجن '),
(25710, 'Matthew', 40, 14, 11, ' فأحضر رأسه على طبق ودفع إلى الصبية ، فجاءت به إلى أمها '),
(25711, 'Matthew', 40, 14, 12, ' فتقدم تلاميذه ورفعوا الجسد ودفنوه . ثم أتوا وأخبروا يسوع '),
(25712, 'Matthew', 40, 14, 13, ' فلما سمع يسوع انصرف من هناك في سفينة إلى موضع خلاء منفردا . فسمع الجموع وتبعوه مشاة من المدن '),
(25713, 'Matthew', 40, 14, 14, ' فلما خرج يسوع أبصر جمعا كثيرا فتحنن عليهم وشفى مرضاهم '),
(25714, 'Matthew', 40, 14, 15, ' ولما صار المساء تقدم إليه تلاميذه قائلين : الموضع خلاء والوقت قد مضى . اصرف الجموع لكي يمضوا إلى القرى ويبتاعوا لهم طعاما '),
(25715, 'Matthew', 40, 14, 16, ' فقال لهم يسوع : لا حاجة لهم أن يمضوا . أعطوهم أنتم ليأكلوا '),
(25716, 'Matthew', 40, 14, 17, ' فقالوا له : ليس عندنا ههنا إلا خمسة أرغفة وسمكتان '),
(25717, 'Matthew', 40, 14, 18, ' فقال : ائتوني بها إلى هنا '),
(25718, 'Matthew', 40, 14, 19, ' فأمر الجموع أن يتكئوا على العشب . ثم أخذ الأرغفة الخمسة والسمكتين ، ورفع نظره نحو السماء وبارك وكسر وأعطى الأرغفة للتلاميذ ، والتلاميذ للجموع '),
(25719, 'Matthew', 40, 14, 20, ' فأكل الجميع وشبعوا . ثم رفعوا ما فضل من الكسر اثنتي عشرة قفة مملوءة '),
(25720, 'Matthew', 40, 14, 21, ' والآكلون كانوا نحو خمسة آلاف رجل ، ما عدا النساء والأولاد '),
(25721, 'Matthew', 40, 14, 22, ' وللوقت ألزم يسوع تلاميذه أن يدخلوا السفينة ويسبقوه إلى العبر حتى يصرف الجموع '),
(25722, 'Matthew', 40, 14, 23, ' وبعدما صرف الجموع صعد إلى الجبل منفردا ليصلي . ولما صار المساء كان هناك وحده '),
(25723, 'Matthew', 40, 14, 24, ' وأما السفينة فكانت قد صارت في وسط البحر معذبة من الأمواج . لأن الريح كانت مضادة '),
(25724, 'Matthew', 40, 14, 25, ' وفي الهزيع الرابع من الليل مضى إليهم يسوع ماشيا على البحر '),
(25725, 'Matthew', 40, 14, 26, ' فلما أبصره التلاميذ ماشيا على البحر اضطربوا قائلين : إنه خيال . ومن الخوف صرخوا '),
(25726, 'Matthew', 40, 14, 27, ' فللوقت كلمهم يسوع قائلا : تشجعوا أنا هو . لا تخافوا '),
(25727, 'Matthew', 40, 14, 28, ' فأجابه بطرس وقال : يا سيد ، إن كنت أنت هو ، فمرني أن آتي إليك على الماء '),
(25728, 'Matthew', 40, 14, 29, ' فقال : تعال . فنزل بطرس من السفينة ومشى على الماء ليأتي إلى يسوع '),
(25729, 'Matthew', 40, 14, 30, ' ولكن لما رأى الريح شديدة خاف . وإذ ابتدأ يغرق ، صرخ قائلا : يا رب ، نجني '),
(25730, 'Matthew', 40, 14, 31, ' ففي الحال مد يسوع يده وأمسك به وقال له : يا قليل الإيمان ، لماذا شككت '),
(25731, 'Matthew', 40, 14, 32, ' ولما دخلا السفينة سكنت الريح '),
(25732, 'Matthew', 40, 14, 33, ' والذين في السفينة جاءوا وسجدوا له قائلين : بالحقيقة أنت ابن الله '),
(25733, 'Matthew', 40, 14, 34, ' فلما عبروا جاءوا إلى أرض جنيسارت '),
(25734, 'Matthew', 40, 14, 35, ' فعرفه رجال ذلك المكان . فأرسلوا إلى جميع تلك الكورة المحيطة وأحضروا إليه جميع المرضى '),
(25735, 'Matthew', 40, 14, 36, ' وطلبوا إليه أن يلمسوا هدب ثوبه فقط . فجميع الذين لمسوه نالوا الشفاء '),
(25736, 'Matthew', 40, 15, 1, ' حينئذ جاء إلى يسوع كتبة وفريسيون الذين من أورشليم قائلين '),
(25737, 'Matthew', 40, 15, 2, ' لماذا يتعدى تلاميذك تقليد الشيوخ ، فإنهم لا يغسلون أيديهم حينما يأكلون خبزا '),
(25738, 'Matthew', 40, 15, 3, ' فأجاب وقال لهم : وأنتم أيضا ، لماذا تتعدون وصية الله بسبب تقليدكم '),
(25739, 'Matthew', 40, 15, 4, ' فإن الله أوصى قائلا : أكرم أباك وأمك ، ومن يشتم أبا أو أما فليمت موتا '),
(25740, 'Matthew', 40, 15, 5, ' وأما أنتم فتقولون : من قال لأبيه أو أمه : قربان هو الذي تنتفع به مني . فلا يكرم أباه أو أمه '),
(25741, 'Matthew', 40, 15, 6, ' فقد أبطلتم وصية الله بسبب تقليدكم '),
(25742, 'Matthew', 40, 15, 7, ' يا مراؤون حسنا تنبأ عنكم إشعياء قائلا '),
(25743, 'Matthew', 40, 15, 8, ' يقترب إلي هذا الشعب بفمه ، ويكرمني بشفتيه ، وأما قلبه فمبتعد عني بعيدا '),
(25744, 'Matthew', 40, 15, 9, ' وباطلا يعبدونني وهم يعلمون تعاليم هي وصايا الناس '),
(25745, 'Matthew', 40, 15, 10, ' ثم دعا الجمع وقال لهم : اسمعوا وافهموا '),
(25746, 'Matthew', 40, 15, 11, ' ليس ما يدخل الفم ينجس الإنسان ، بل ما يخرج من الفم هذا ينجس الإنسان '),
(25747, 'Matthew', 40, 15, 12, ' حينئذ تقدم تلاميذه وقالوا له : أتعلم أن الفريسيين لما سمعوا القول نفروا '),
(25748, 'Matthew', 40, 15, 13, ' فأجاب وقال : كل غرس لم يغرسه أبي السماوي يقلع '),
(25749, 'Matthew', 40, 15, 14, ' اتركوهم . هم عميان قادة عميان . وإن كان أعمى يقود أعمى يسقطان كلاهما في حفرة '),
(25750, 'Matthew', 40, 15, 15, ' فأجاب بطرس وقال له : فسر لنا هذا المثل '),
(25751, 'Matthew', 40, 15, 16, ' فقال يسوع : هل أنتم أيضا حتى الآن غير فاهمين '),
(25752, 'Matthew', 40, 15, 17, ' ألا تفهمون بعد أن كل ما يدخل الفم يمضي إلى الجوف ويندفع إلى المخرج '),
(25753, 'Matthew', 40, 15, 18, ' وأما ما يخرج من الفم فمن القلب يصدر ، وذاك ينجس الإنسان '),
(25754, 'Matthew', 40, 15, 19, ' لأن من القلب تخرج أفكار شريرة : قتل ، زنى ، فسق ، سرقة ، شهادة زور ، تجديف '),
(25755, 'Matthew', 40, 15, 20, ' هذه هي التي تنجس الإنسان . وأما الأكل بأيد غير مغسولة فلا ينجس الإنسان '),
(25756, 'Matthew', 40, 15, 21, ' ثم خرج يسوع من هناك وانصرف إلى نواحي صور وصيداء '),
(25757, 'Matthew', 40, 15, 22, ' وإذا امرأة كنعانية خارجة من تلك التخوم صرخت إليه قائلة : ارحمني ، يا سيد ، يا ابن داود ابنتي مجنونة جدا '),
(25758, 'Matthew', 40, 15, 23, ' فلم يجبها بكلمة . فتقدم تلاميذه وطلبوا إليه قائلين : اصرفها ، لأنها تصيح وراءنا '),
(25759, 'Matthew', 40, 15, 24, ' فأجاب وقال : لم أرسل إلا إلى خراف بيت إسرائيل الضالة '),
(25760, 'Matthew', 40, 15, 25, ' فأتت وسجدت له قائلة : يا سيد ، أعني '),
(25761, 'Matthew', 40, 15, 26, ' فأجاب وقال : ليس حسنا أن يؤخذ خبز البنين ويطرح للكلاب '),
(25762, 'Matthew', 40, 15, 27, ' فقالت : نعم ، يا سيد والكلاب أيضا تأكل من الفتات الذي يسقط من مائدة أربابها '),
(25763, 'Matthew', 40, 15, 28, ' حينئذ أجاب يسوع وقال لها : يا امرأة ، عظيم إيمانك ليكن لك كما تريدين . فشفيت ابنتها من تلك الساعة '),
(25764, 'Matthew', 40, 15, 29, ' ثم انتقل يسوع من هناك وجاء إلى جانب بحر الجليل ، وصعد إلى الجبل وجلس هناك '),
(25765, 'Matthew', 40, 15, 30, ' فجاء إليه جموع كثيرة ، معهم عرج وعمي وخرس وشل وآخرون كثيرون ، وطرحوهم عند قدمي يسوع . فشفاهم '),
(25766, 'Matthew', 40, 15, 31, ' حتى تعجب الجموع إذ رأوا الخرس يتكلمون ، والشل يصحون ، والعرج يمشون ، والعمي يبصرون . ومجدوا إله إسرائيل '),
(25767, 'Matthew', 40, 15, 32, ' وأما يسوع فدعا تلاميذه وقال : إني أشفق على الجمع ، لأن الآن لهم ثلاثة أيام يمكثون معي وليس لهم ما يأكلون . ولست أريد أن أصرفهم صائمين لئلا يخوروا في الطريق '),
(25768, 'Matthew', 40, 15, 33, ' فقال له تلاميذه : من أين لنا في البرية خبز بهذا المقدار ، حتى يشبع جمعا هذا عدده '),
(25769, 'Matthew', 40, 15, 34, ' فقال لهم يسوع : كم عندكم من الخبز ؟ فقالوا : سبعة وقليل من صغار السمك '),
(25770, 'Matthew', 40, 15, 35, ' فأمر الجموع أن يتكئوا على الأرض '),
(25771, 'Matthew', 40, 15, 36, ' وأخذ السبع خبزات والسمك ، وشكر وكسر وأعطى تلاميذه ، والتلاميذ أعطوا الجمع '),
(25772, 'Matthew', 40, 15, 37, ' فأكل الجميع وشبعوا . ثم رفعوا ما فضل من الكسر سبعة سلال مملوءة '),
(25773, 'Matthew', 40, 15, 38, ' والآكلون كانوا أربعة آلاف رجل ما عدا النساء والأولاد '),
(25774, 'Matthew', 40, 15, 39, ' ثم صرف الجموع وصعد إلى السفينة وجاء إلى تخوم مجدل '),
(25775, 'Matthew', 40, 16, 1, ' وجاء إليه الفريسيون والصدوقيون ليجربوه ، فسألوه أن يريهم آية من السماء '),
(25776, 'Matthew', 40, 16, 2, ' فأجاب وقال لهم : إذا كان المساء قلتم : صحو لأن السماء محمرة '),
(25777, 'Matthew', 40, 16, 3, ' وفي الصباح : اليوم شتاء لأن السماء محمرة بعبوسة . يا مراؤون تعرفون أن تميزوا وجه السماء ، وأما علامات الأزمنة فلا تستطيعون '),
(25778, 'Matthew', 40, 16, 4, ' جيل شرير فاسق يلتمس آية ، ولا تعطى له آية إلا آية يونان النبي . ثم تركهم ومضى '),
(25779, 'Matthew', 40, 16, 5, ' ولما جاء تلاميذه إلى العبر نسوا أن يأخذوا خبزا '),
(25780, 'Matthew', 40, 16, 6, ' وقال لهم يسوع : انظروا ، وتحرزوا من خمير الفريسيين والصدوقيين '),
(25781, 'Matthew', 40, 16, 7, ' ففكروا في أنفسهم قائلين : إننا لم نأخذ خبزا '),
(25782, 'Matthew', 40, 16, 8, ' فعلم يسوع وقال لهم : لماذا تفكرون في أنفسكم يا قليلي الإيمان أنكم لم تأخذوا خبزا '),
(25783, 'Matthew', 40, 16, 9, ' أحتى الآن لا تفهمون ؟ ولا تذكرون خمس خبزات الخمسة الآلاف وكم قفة أخذتم '),
(25784, 'Matthew', 40, 16, 10, ' ولا سبع خبزات الأربعة الآلاف وكم سلا أخذتم '),
(25785, 'Matthew', 40, 16, 11, ' كيف لا تفهمون أني ليس عن الخبز قلت لكم أن تتحرزوا من خمير الفريسيين والصدوقيين '),
(25786, 'Matthew', 40, 16, 12, ' حينئذ فهموا أنه لم يقل أن يتحرزوا من خمير الخبز ، بل من تعليم الفريسيين والصدوقيين '),
(25787, 'Matthew', 40, 16, 13, ' ولما جاء يسوع إلى نواحي قيصرية فيلبس سأل تلاميذه قائلا : من يقول الناس إني أنا ابن الإنسان '),
(25788, 'Matthew', 40, 16, 14, ' فقالوا : قوم : يوحنا المعمدان ، وآخرون : إيليا ، وآخرون : إرميا أو واحد من الأنبياء '),
(25789, 'Matthew', 40, 16, 15, ' قال لهم : وأنتم ، من تقولون إني أنا '),
(25790, 'Matthew', 40, 16, 16, ' فأجاب سمعان بطرس وقال : أنت هو المسيح ابن الله الحي '),
(25791, 'Matthew', 40, 16, 17, ' فأجاب يسوع وقال له : طوبى لك يا سمعان بن يونا ، إن لحما ودما لم يعلن لك ، لكن أبي الذي في السماوات '),
(25792, 'Matthew', 40, 16, 18, ' وأنا أقول لك أيضا : أنت بطرس ، وعلى هذه الصخرة أبني كنيستي ، وأبواب الجحيم لن تقوى عليها '),
(25793, 'Matthew', 40, 16, 19, ' وأعطيك مفاتيح ملكوت السماوات ، فكل ما تربطه على الأرض يكون مربوطا في السماوات . وكل ما تحله على الأرض يكون محلولا في السماوات '),
(25794, 'Matthew', 40, 16, 20, ' حينئذ أوصى تلاميذه أن لا يقولوا لأحد إنه يسوع المسيح '),
(25795, 'Matthew', 40, 16, 21, ' من ذلك الوقت ابتدأ يسوع يظهر لتلاميذه أنه ينبغي أن يذهب إلى أورشليم ويتألم كثيرا من الشيوخ ورؤساء الكهنة والكتبة ، ويقتل ، وفي اليوم الثالث يقوم '),
(25796, 'Matthew', 40, 16, 22, ' فأخذه بطرس إليه وابتدأ ينتهره قائلا : حاشاك يا رب لا يكون لك هذا '),
(25797, 'Matthew', 40, 16, 23, ' فالتفت وقال لبطرس : اذهب عني يا شيطان أنت معثرة لي ، لأنك لا تهتم بما لله لكن بما للناس '),
(25798, 'Matthew', 40, 16, 24, ' حينئذ قال يسوع لتلاميذه : إن أراد أحد أن يأتي ورائي فلينكر نفسه ويحمل صليبه ويتبعني '),
(25799, 'Matthew', 40, 16, 25, ' فإن من أراد أن يخلص نفسه يهلكها ، ومن يهلك نفسه من أجلي يجدها '),
(25800, 'Matthew', 40, 16, 26, ' لأنه ماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه ؟ أو ماذا يعطي الإنسان فداء عن نفسه '),
(25801, 'Matthew', 40, 16, 27, ' فإن ابن الإنسان سوف يأتي في مجد أبيه مع ملائكته ، وحينئذ يجازي كل واحد حسب عمله '),
(25802, 'Matthew', 40, 16, 28, ' الحق أقول لكم : إن من القيام ههنا قوما لا يذوقون الموت حتى يروا ابن الإنسان آتيا في ملكوته '),
(25803, 'Matthew', 40, 17, 1, ' وبعد ستة أيام أخذ يسوع بطرس ويعقوب ويوحنا أخاه وصعد بهم إلى جبل عال منفردين '),
(25804, 'Matthew', 40, 17, 2, ' وتغيرت هيئته قدامهم ، وأضاء وجهه كالشمس ، وصارت ثيابه بيضاء كالنور '),
(25805, 'Matthew', 40, 17, 3, ' وإذا موسى وإيليا قد ظهرا لهم يتكلمان معه '),
(25806, 'Matthew', 40, 17, 4, ' فجعل بطرس يقول ليسوع : يا رب ، جيد أن نكون ههنا فإن شئت نصنع هنا ثلاث مظال : لك واحدة ، ولموسى واحدة ، ولإيليا واحدة '),
(25807, 'Matthew', 40, 17, 5, ' وفيما هو يتكلم إذا سحابة نيرة ظللتهم ، وصوت من السحابة قائلا : هذا هو ابني الحبيب الذي به سررت . له اسمعوا '),
(25808, 'Matthew', 40, 17, 6, ' ولما سمع التلاميذ سقطوا على وجوههم وخافوا جدا '),
(25809, 'Matthew', 40, 17, 7, ' فجاء يسوع ولمسهم وقال : قوموا ، ولا تخافوا '),
(25810, 'Matthew', 40, 17, 8, ' فرفعوا أعينهم ولم يروا أحدا إلا يسوع وحده '),
(25811, 'Matthew', 40, 17, 9, ' وفيما هم نازلون من الجبل أوصاهم يسوع قائلا : لا تعلموا أحدا بما رأيتم حتى يقوم ابن الإنسان من الأموات '),
(25812, 'Matthew', 40, 17, 10, ' وسأله تلاميذه قائلين : فلماذا يقول الكتبة : إن إيليا ينبغي أن يأتي أولا '),
(25813, 'Matthew', 40, 17, 11, ' فأجاب يسوع وقال لهم : إن إيليا يأتي أولا ويرد كل شيء '),
(25814, 'Matthew', 40, 17, 12, ' ولكني أقول لكم : إن إيليا قد جاء ولم يعرفوه ، بل عملوا به كل ما أرادوا . كذلك ابن الإنسان أيضا سوف يتألم منهم '),
(25815, 'Matthew', 40, 17, 13, ' حينئذ فهم التلاميذ أنه قال لهم عن يوحنا المعمدان '),
(25816, 'Matthew', 40, 17, 14, ' ولما جاءوا إلى الجمع تقدم إليه رجل جاثيا له '),
(25817, 'Matthew', 40, 17, 15, ' وقائلا : يا سيد ، ارحم ابني فإنه يصرع ويتألم شديدا ، ويقع كثيرا في النار وكثيرا في الماء '),
(25818, 'Matthew', 40, 17, 16, ' وأحضرته إلى تلاميذك فلم يقدروا أن يشفوه '),
(25819, 'Matthew', 40, 17, 17, ' فأجاب يسوع وقال : أيها الجيل غير المؤمن ، الملتوي ، إلى متى أكون معكم ؟ إلى متى أحتملكم ؟ قدموه إلي ههنا '),
(25820, 'Matthew', 40, 17, 18, ' فانتهره يسوع ، فخرج منه الشيطان . فشفي الغلام من تلك الساعة '),
(25821, 'Matthew', 40, 17, 19, ' ثم تقدم التلاميذ إلى يسوع على انفراد وقالوا : لماذا لم نقدر نحن أن نخرجه '),
(25822, 'Matthew', 40, 17, 20, ' فقال لهم يسوع : لعدم إيمانكم . فالحق أقول لكم : لو كان لكم إيمان مثل حبة خردل لكنتم تقولون لهذا الجبل : انتقل من هنا إلى هناك فينتقل ، ولا يكون شيء غير ممكن لديكم '),
(25823, 'Matthew', 40, 17, 21, ' وأما هذا الجنس فلا يخرج إلا بالصلاة والصوم '),
(25824, 'Matthew', 40, 17, 22, ' وفيما هم يترددون في الجليل قال لهم يسوع : ابن الإنسان سوف يسلم إلى أيدي الناس '),
(25825, 'Matthew', 40, 17, 23, ' فيقتلونه ، وفي اليوم الثالث يقوم . فحزنوا جدا '),
(25826, 'Matthew', 40, 17, 24, ' ولما جاءوا إلى كفرناحوم تقدم الذين يأخذون الدرهمين إلى بطرس وقالوا : أما يوفي معلمكم الدرهمين '),
(25827, 'Matthew', 40, 17, 25, ' قال : بلى . فلما دخل البيت سبقه يسوع قائلا : ماذا تظن يا سمعان ؟ ممن يأخذ ملوك الأرض الجباية أو الجزية ، أمن بنيهم أم من الأجانب '),
(25828, 'Matthew', 40, 17, 26, ' قال له بطرس : من الأجانب . قال له يسوع : فإذا البنون أحرار '),
(25829, 'Matthew', 40, 17, 27, ' ولكن لئلا نعثرهم ، اذهب إلى البحر وألق صنارة ، والسمكة التي تطلع أولا خذها ، ومتى فتحت فاها تجد إستارا ، فخذه وأعطهم عني وعنك '),
(25830, 'Matthew', 40, 18, 1, ' في تلك الساعة تقدم التلاميذ إلى يسوع قائلين : فمن هو أعظم في ملكوت السماوات '),
(25831, 'Matthew', 40, 18, 2, ' فدعا يسوع إليه ولدا وأقامه في وسطهم '),
(25832, 'Matthew', 40, 18, 3, ' وقال : الحق أقول لكم : إن لم ترجعوا وتصيروا مثل الأولاد فلن تدخلوا ملكوت السماوات '),
(25833, 'Matthew', 40, 18, 4, ' فمن وضع نفسه مثل هذا الولد فهو الأعظم في ملكوت السماوات '),
(25834, 'Matthew', 40, 18, 5, ' ومن قبل ولدا واحدا مثل هذا باسمي فقد قبلني '),
(25835, 'Matthew', 40, 18, 6, ' ومن أعثر أحد هؤلاء الصغار المؤمنين بي فخير له أن يعلق في عنقه حجر الرحى ويغرق في لجة البحر '),
(25836, 'Matthew', 40, 18, 7, ' ويل للعالم من العثرات فلا بد أن تأتي العثرات ، ولكن ويل لذلك الإنسان الذي به تأتي العثرة '),
(25837, 'Matthew', 40, 18, 8, ' فإن أعثرتك يدك أو رجلك فاقطعها وألقها عنك . خير لك أن تدخل الحياة أعرج أو أقطع من أن تلقى في النار الأبدية ولك يدان أو رجلان '),
(25838, 'Matthew', 40, 18, 9, ' وإن أعثرتك عينك فاقلعها وألقها عنك . خير لك أن تدخل الحياة أعور من أن تلقى في جهنم النار ولك عينان '),
(25839, 'Matthew', 40, 18, 10, ' انظروا ، لا تحتقروا أحد هؤلاء الصغار ، لأني أقول لكم : إن ملائكتهم في السماوات كل حين ينظرون وجه أبي الذي في السماوات '),
(25840, 'Matthew', 40, 18, 11, ' لأن ابن الإنسان قد جاء لكي يخلص ما قد هلك '),
(25841, 'Matthew', 40, 18, 12, ' ماذا تظنون ؟ إن كان لإنسان مئة خروف ، وضل واحد منها ، أفلا يترك التسعة والتسعين على الجبال ويذهب يطلب الضال '),
(25842, 'Matthew', 40, 18, 13, ' وإن اتفق أن يجده ، فالحق أقول لكم : إنه يفرح به أكثر من التسعة والتسعين التي لم تضل '),
(25843, 'Matthew', 40, 18, 14, ' هكذا ليست مشيئة أمام أبيكم الذي في السماوات أن يهلك أحد هؤلاء الصغار '),
(25844, 'Matthew', 40, 18, 15, ' وإن أخطأ إليك أخوك فاذهب وعاتبه بينك وبينه وحدكما . إن سمع منك فقد ربحت أخاك '),
(25845, 'Matthew', 40, 18, 16, ' وإن لم يسمع ، فخذ معك أيضا واحدا أو اثنين ، لكي تقوم كل كلمة على فم شاهدين أو ثلاثة '),
(25846, 'Matthew', 40, 18, 17, ' وإن لم يسمع منهم فقل للكنيسة . وإن لم يسمع من الكنيسة فليكن عندك كالوثني والعشار '),
(25847, 'Matthew', 40, 18, 18, ' الحق أقول لكم : كل ما تربطونه على الأرض يكون مربوطا في السماء ، وكل ما تحلونه على الأرض يكون محلولا في السماء '),
(25848, 'Matthew', 40, 18, 19, ' وأقول لكم أيضا : إن اتفق اثنان منكم على الأرض في أي شيء يطلبانه فإنه يكون لهما من قبل أبي الذي في السماوات '),
(25849, 'Matthew', 40, 18, 20, ' لأنه حيثما اجتمع اثنان أو ثلاثة باسمي فهناك أكون في وسطهم '),
(25850, 'Matthew', 40, 18, 21, ' حينئذ تقدم إليه بطرس وقال : يا رب ، كم مرة يخطئ إلي أخي وأنا أغفر له ؟ هل إلى سبع مرات '),
(25851, 'Matthew', 40, 18, 22, ' قال له يسوع : لا أقول لك إلى سبع مرات ، بل إلى سبعين مرة سبع مرات '),
(25852, 'Matthew', 40, 18, 23, ' لذلك يشبه ملكوت السماوات إنسانا ملكا أراد أن يحاسب عبيده '),
(25853, 'Matthew', 40, 18, 24, ' فلما ابتدأ في المحاسبة قدم إليه واحد مديون بعشرة آلاف وزنة '),
(25854, 'Matthew', 40, 18, 25, ' وإذ لم يكن له ما يوفي أمر سيده أن يباع هو وامرأته وأولاده وكل ما له ، ويوفي الدين '),
(25855, 'Matthew', 40, 18, 26, ' فخر العبد وسجد له قائلا : يا سيد ، تمهل علي فأوفيك الجميع '),
(25856, 'Matthew', 40, 18, 27, ' فتحنن سيد ذلك العبد وأطلقه ، وترك له الدين '),
(25857, 'Matthew', 40, 18, 28, ' ولما خرج ذلك العبد وجد واحدا من العبيد رفقائه ، كان مديونا له بمئة دينار ، فأمسكه وأخذ بعنقه قائلا : أوفني ما لي عليك '),
(25858, 'Matthew', 40, 18, 29, ' فخر العبد رفيقه على قدميه وطلب إليه قائلا : تمهل علي فأوفيك الجميع '),
(25859, 'Matthew', 40, 18, 30, ' فلم يرد بل مضى وألقاه في سجن حتى يوفي الدين '),
(25860, 'Matthew', 40, 18, 31, ' فلما رأى العبيد رفقاؤه ما كان ، حزنوا جدا . وأتوا وقصوا على سيدهم كل ما جرى '),
(25861, 'Matthew', 40, 18, 32, ' فدعاه حينئذ سيده وقال له : أيها العبد الشرير ، كل ذلك الدين تركته لك لأنك طلبت إلي '),
(25862, 'Matthew', 40, 18, 33, ' أفما كان ينبغي أنك أنت أيضا ترحم العبد رفيقك كما رحمتك أنا '),
(25863, 'Matthew', 40, 18, 34, ' وغضب سيده وسلمه إلى المعذبين حتى يوفي كل ما كان له عليه '),
(25864, 'Matthew', 40, 18, 35, ' فهكذا أبي السماوي يفعل بكم إن لم تتركوا من قلوبكم كل واحد لأخيه زلاته '),
(25865, 'Matthew', 40, 19, 1, ' ولما أكمل يسوع هذا الكلام انتقل من الجليل وجاء إلى تخوم اليهودية من عبر الأردن '),
(25866, 'Matthew', 40, 19, 2, ' وتبعته جموع كثيرة فشفاهم هناك '),
(25867, 'Matthew', 40, 19, 3, ' وجاء إليه الفريسيون ليجربوه قائلين له : هل يحل للرجل أن يطلق امرأته لكل سبب '),
(25868, 'Matthew', 40, 19, 4, ' فأجاب وقال لهم : أما قرأتم أن الذي خلق من البدء خلقهما ذكرا وأنثى '),
(25869, 'Matthew', 40, 19, 5, ' وقال : من أجل هذا يترك الرجل أباه وأمه ويلتصق بامرأته ، ويكون الاثنان جسدا واحدا '),
(25870, 'Matthew', 40, 19, 6, ' إذا ليسا بعد اثنين بل جسد واحد . فالذي جمعه الله لا يفرقه إنسان '),
(25871, 'Matthew', 40, 19, 7, ' قالوا له : فلماذا أوصى موسى أن يعطى كتاب طلاق فتطلق '),
(25872, 'Matthew', 40, 19, 8, ' قال لهم : إن موسى من أجل قساوة قلوبكم أذن لكم أن تطلقوا نساءكم . ولكن من البدء لم يكن هكذا '),
(25873, 'Matthew', 40, 19, 9, ' وأقول لكم : إن من طلق امرأته إلا بسبب الزنا وتزوج بأخرى يزني ، والذي يتزوج بمطلقة يزني '),
(25874, 'Matthew', 40, 19, 10, ' قال له تلاميذه : إن كان هكذا أمر الرجل مع المرأة ، فلا يوافق أن يتزوج '),
(25875, 'Matthew', 40, 19, 11, ' فقال لهم : ليس الجميع يقبلون هذا الكلام بل الذين أعطي لهم '),
(25876, 'Matthew', 40, 19, 12, ' لأنه يوجد خصيان ولدوا هكذا من بطون أمهاتهم ، ويوجد خصيان خصاهم الناس ، ويوجد خصيان خصوا أنفسهم لأجل ملكوت السماوات . من استطاع أن يقبل فليقبل '),
(25877, 'Matthew', 40, 19, 13, ' حينئذ قدم إليه أولاد لكي يضع يديه عليهم ويصلي ، فانتهرهم التلاميذ '),
(25878, 'Matthew', 40, 19, 14, ' أما يسوع فقال : دعوا الأولاد يأتون إلي ولا تمنعوهم لأن لمثل هؤلاء ملكوت السماوات '),
(25879, 'Matthew', 40, 19, 15, ' فوضع يديه عليهم ، ومضى من هناك '),
(25880, 'Matthew', 40, 19, 16, ' وإذا واحد تقدم وقال له : أيها المعلم الصالح ، أي صلاح أعمل لتكون لي الحياة الأبدية '),
(25881, 'Matthew', 40, 19, 17, ' فقال له : لماذا تدعوني صالحا ؟ ليس أحد صالحا إلا واحد وهو الله . ولكن إن أردت أن تدخل الحياة فاحفظ الوصايا '),
(25882, 'Matthew', 40, 19, 18, ' قال له : أية الوصايا ؟ فقال يسوع : لا تقتل . لا تزن . لا تسرق . لا تشهد بالزور '),
(25883, 'Matthew', 40, 19, 19, ' أكرم أباك وأمك ، وأحب قريبك كنفسك '),
(25884, 'Matthew', 40, 19, 20, ' قال له الشاب : هذه كلها حفظتها منذ حداثتي . فماذا يعوزني بعد '),
(25885, 'Matthew', 40, 19, 21, ' قال له يسوع : إن أردت أن تكون كاملا فاذهب وبع أملاكك وأعط الفقراء ، فيكون لك كنز في السماء ، وتعال اتبعني '),
(25886, 'Matthew', 40, 19, 22, ' فلما سمع الشاب الكلمة مضى حزينا ، لأنه كان ذا أموال كثيرة '),
(25887, 'Matthew', 40, 19, 23, ' فقال يسوع لتلاميذه : الحق أقول لكم : إنه يعسر أن يدخل غني إلى ملكوت السماوات '),
(25888, 'Matthew', 40, 19, 24, ' وأقول لكم أيضا : إن مرور جمل من ثقب إبرة أيسر من أن يدخل غني إلى ملكوت الله '),
(25889, 'Matthew', 40, 19, 25, ' فلما سمع تلاميذه بهتوا جدا قائلين : إذا من يستطيع أن يخلص '),
(25890, 'Matthew', 40, 19, 26, ' فنظر إليهم يسوع وقال لهم : هذا عند الناس غير مستطاع ، ولكن عند الله كل شيء مستطاع '),
(25891, 'Matthew', 40, 19, 27, ' فأجاب بطرس حينئذ وقال له : ها نحن قد تركنا كل شيء وتبعناك . فماذا يكون لنا '),
(25892, 'Matthew', 40, 19, 28, ' فقال لهم يسوع : الحق أقول لكم : إنكم أنتم الذين تبعتموني ، في التجديد ، متى جلس ابن الإنسان على كرسي مجده ، تجلسون أنتم أيضا على اثني عشر كرسيا تدينون أسباط إسرائيل الاثني عشر '),
(25893, 'Matthew', 40, 19, 29, ' وكل من ترك بيوتا أو إخوة أو أخوات أو أبا أو أما أو امرأة أو أولادا أو حقولا من أجل اسمي ، يأخذ مئة ضعف ويرث الحياة الأبدية '),
(25894, 'Matthew', 40, 19, 30, ' ولكن كثيرون أولون يكونون آخرين ، وآخرون أولين '),
(25895, 'Matthew', 40, 20, 1, ' فإن ملكوت السماوات يشبه رجلا رب بيت خرج مع الصبح ليستأجر فعلة لكرمه '),
(25896, 'Matthew', 40, 20, 2, ' فاتفق مع الفعلة على دينار في اليوم ، وأرسلهم إلى كرمه '),
(25897, 'Matthew', 40, 20, 3, ' ثم خرج نحو الساعة الثالثة ورأى آخرين قياما في السوق بطالين '),
(25898, 'Matthew', 40, 20, 4, ' فقال لهم : اذهبوا أنتم أيضا إلى الكرم فأعطيكم ما يحق لكم . فمضوا '),
(25899, 'Matthew', 40, 20, 5, ' وخرج أيضا نحو الساعة السادسة والتاسعة وفعل كذلك '),
(25900, 'Matthew', 40, 20, 6, ' ثم نحو الساعة الحادية عشرة خرج ووجد آخرين قياما بطالين ، فقال لهم : لماذا وقفتم ههنا كل النهار بطالين '),
(25901, 'Matthew', 40, 20, 7, ' قالوا له : لأنه لم يستأجرنا أحد . قال لهم : اذهبوا أنتم أيضا إلى الكرم فتأخذوا ما يحق لكم '),
(25902, 'Matthew', 40, 20, 8, ' فلما كان المساء قال صاحب الكرم لوكيله : ادع الفعلة وأعطهم الأجرة مبتدئا من الآخرين إلى الأولين '),
(25903, 'Matthew', 40, 20, 9, ' فجاء أصحاب الساعة الحادية عشرة وأخذوا دينارا دينارا '),
(25904, 'Matthew', 40, 20, 10, ' فلما جاء الأولون ظنوا أنهم يأخذون أكثر . فأخذوا هم أيضا دينارا دينارا '),
(25905, 'Matthew', 40, 20, 11, ' وفيما هم يأخذون تذمروا على رب البيت '),
(25906, 'Matthew', 40, 20, 12, ' قائلين : هؤلاء الآخرون عملوا ساعة واحدة ، وقد ساويتهم بنا نحن الذين احتملنا ثقل النهار والحر '),
(25907, 'Matthew', 40, 20, 13, ' فأجاب وقال لواحد منهم : يا صاحب ، ما ظلمتك أما اتفقت معي على دينار '),
(25908, 'Matthew', 40, 20, 14, ' فخذ الذي لك واذهب ، فإني أريد أن أعطي هذا الأخير مثلك '),
(25909, 'Matthew', 40, 20, 15, ' أو ما يحل لي أن أفعل ما أريد بما لي ؟ أم عينك شريرة لأني أنا صالح '),
(25910, 'Matthew', 40, 20, 16, ' هكذا يكون الآخرون أولين والأولون آخرين ، لأن كثيرين يدعون وقليلين ينتخبون '),
(25911, 'Matthew', 40, 20, 17, ' وفيما كان يسوع صاعدا إلى أورشليم أخذ الاثني عشر تلميذا على انفراد في الطريق وقال لهم '),
(25912, 'Matthew', 40, 20, 18, ' ها نحن صاعدون إلى أورشليم ، وابن الإنسان يسلم إلى رؤساء الكهنة والكتبة ، فيحكمون عليه بالموت '),
(25913, 'Matthew', 40, 20, 19, ' ويسلمونه إلى الأمم لكي يهزأوا به ويجلدوه ويصلبوه ، وفي اليوم الثالث يقوم '),
(25914, 'Matthew', 40, 20, 20, ' حينئذ تقدمت إليه أم ابني زبدي مع ابنيها ، وسجدت وطلبت منه شيئا '),
(25915, 'Matthew', 40, 20, 21, ' فقال لها : ماذا تريدين ؟ قالت له : قل أن يجلس ابناي هذان واحد عن يمينك والآخر عن اليسار في ملكوتك '),
(25916, 'Matthew', 40, 20, 22, ' فأجاب يسوع وقال : لستما تعلمان ما تطلبان . أتستطيعان أن تشربا الكأس التي سوف أشربها أنا ، وأن تصطبغا بالصبغة التي أصطبغ بها أنا ؟ قالا له : نستطيع '),
(25917, 'Matthew', 40, 20, 23, ' فقال لهما : أما كأسي فتشربانها ، وبالصبغة التي أصطبغ بها أنا تصطبغان . وأما الجلوس عن يميني وعن يساري فليس لي أن أعطيه إلا للذين أعد لهم من أبي '),
(25918, 'Matthew', 40, 20, 24, ' فلما سمع العشرة اغتاظوا من أجل الأخوين '),
(25919, 'Matthew', 40, 20, 25, ' فدعاهم يسوع وقال : أنتم تعلمون أن رؤساء الأمم يسودونهم ، والعظماء يتسلطون عليهم '),
(25920, 'Matthew', 40, 20, 26, ' فلا يكون هكذا فيكم . بل من أراد أن يكون فيكم عظيما فليكن لكم خادما '),
(25921, 'Matthew', 40, 20, 27, ' ومن أراد أن يكون فيكم أولا فليكن لكم عبدا '),
(25922, 'Matthew', 40, 20, 28, ' كما أن ابن الإنسان لم يأت ليخدم بل ليخدم ، وليبذل نفسه فدية عن كثيرين '),
(25923, 'Matthew', 40, 20, 29, ' وفيما هم خارجون من أريحا تبعه جمع كثير '),
(25924, 'Matthew', 40, 20, 30, ' وإذا أعميان جالسان على الطريق . فلما سمعا أن يسوع مجتاز صرخا قائلين : ارحمنا يا سيد ، يا ابن داود '),
(25925, 'Matthew', 40, 20, 31, ' فانتهرهما الجمع ليسكتا ، فكانا يصرخان أكثر قائلين : ارحمنا يا سيد ، يا ابن داود '),
(25926, 'Matthew', 40, 20, 32, ' فوقف يسوع وناداهما وقال : ماذا تريدان أن أفعل بكما '),
(25927, 'Matthew', 40, 20, 33, ' قالا له : يا سيد ، أن تنفتح أعيننا '),
(25928, 'Matthew', 40, 20, 34, ' فتحنن يسوع ولمس أعينهما ، فللوقت أبصرت أعينهما فتبعاه '),
(25929, 'Matthew', 40, 21, 1, ' ولما قربوا من أورشليم وجاءوا إلى بيت فاجي عند جبل الزيتون ، حينئذ أرسل يسوع تلميذين '),
(25930, 'Matthew', 40, 21, 2, ' قائلا لهما : اذهبا إلى القرية التي أمامكما ، فللوقت تجدان أتانا مربوطة وجحشا معها ، فحلاهما وأتياني بهما '),
(25931, 'Matthew', 40, 21, 3, ' وإن قال لكما أحد شيئا ، فقولا : الرب محتاج إليهما . فللوقت يرسلهما '),
(25932, 'Matthew', 40, 21, 4, ' فكان هذا كله لكي يتم ما قيل بالنبي القائل '),
(25933, 'Matthew', 40, 21, 5, ' قولوا لابنة صهيون : هوذا ملكك يأتيك وديعا ، راكبا على أتان وجحش ابن أتان '),
(25934, 'Matthew', 40, 21, 6, ' فذهب التلميذان وفعلا كما أمرهما يسوع '),
(25935, 'Matthew', 40, 21, 7, ' وأتيا بالأتان والجحش ، ووضعا عليهما ثيابهما فجلس عليهما '),
(25936, 'Matthew', 40, 21, 8, ' والجمع الأكثر فرشوا ثيابهم في الطريق . وآخرون قطعوا أغصانا من الشجر وفرشوها في الطريق '),
(25937, 'Matthew', 40, 21, 9, ' والجموع الذين تقدموا والذين تبعوا كانوا يصرخون قائلين : أوصنا لابن داود مبارك الآتي باسم الرب أوصنا في الأعالي '),
(25938, 'Matthew', 40, 21, 10, ' ولما دخل أورشليم ارتجت المدينة كلها قائلة : من هذا '),
(25939, 'Matthew', 40, 21, 11, ' فقالت الجموع : هذا يسوع النبي الذي من ناصرة الجليل '),
(25940, 'Matthew', 40, 21, 12, ' ودخل يسوع إلى هيكل الله وأخرج جميع الذين كانوا يبيعون ويشترون في الهيكل ، وقلب موائد الصيارفة وكراسي باعة الحمام '),
(25941, 'Matthew', 40, 21, 13, ' وقال لهم : مكتوب : بيتي بيت الصلاة يدعى . وأنتم جعلتموه مغارة لصوص '),
(25942, 'Matthew', 40, 21, 14, ' وتقدم إليه عمي وعرج في الهيكل فشفاهم '),
(25943, 'Matthew', 40, 21, 15, ' فلما رأى رؤساء الكهنة والكتبة العجائب التي صنع ، والأولاد يصرخون في الهيكل ويقولون : أوصنا لابن داود ، غضبوا '),
(25944, 'Matthew', 40, 21, 16, ' وقالوا له : أتسمع ما يقول هؤلاء ؟ فقال لهم يسوع : نعم أما قرأتم قط : من أفواه الأطفال والرضع هيأت تسبيحا '),
(25945, 'Matthew', 40, 21, 17, ' ثم تركهم وخرج خارج المدينة إلى بيت عنيا وبات هناك '),
(25946, 'Matthew', 40, 21, 18, ' وفي الصبح إذ كان راجعا إلى المدينة جاع '),
(25947, 'Matthew', 40, 21, 19, ' فنظر شجرة تين على الطريق ، وجاء إليها فلم يجد فيها شيئا إلا ورقا فقط . فقال لها : لا يكن منك ثمر بعد إلى الأبد . فيبست التينة في الحال '),
(25948, 'Matthew', 40, 21, 20, ' فلما رأى التلاميذ ذلك تعجبوا قائلين : كيف يبست التينة في الحال '),
(25949, 'Matthew', 40, 21, 21, ' فأجاب يسوع وقال لهم : الحق أقول لكم : إن كان لكم إيمان ولا تشكون ، فلا تفعلون أمر التينة فقط ، بل إن قلتم أيضا لهذا الجبل : انتقل وانطرح في البحر فيكون '),
(25950, 'Matthew', 40, 21, 22, ' وكل ما تطلبونه في الصلاة مؤمنين تنالونه '),
(25951, 'Matthew', 40, 21, 23, ' ولما جاء إلى الهيكل تقدم إليه رؤساء الكهنة وشيوخ الشعب وهو يعلم ، قائلين : بأي سلطان تفعل هذا ؟ ومن أعطاك هذا السلطان '),
(25952, 'Matthew', 40, 21, 24, ' فأجاب يسوع وقال لهم : وأنا أيضا أسألكم كلمة واحدة ، فإن قلتم لي عنها ، أقول لكم أنا أيضا بأي سلطان أفعل هذا '),
(25953, 'Matthew', 40, 21, 25, ' معمودية يوحنا : من أين كانت ؟ من السماء أم من الناس ؟ ففكروا في أنفسهم قائلين : إن قلنا : من السماء ، يقول لنا : فلماذا لم تؤمنوا به '),
(25954, 'Matthew', 40, 21, 26, ' وإن قلنا : من الناس ، نخاف من الشعب ، لأن يوحنا عند الجميع مثل نبي '),
(25955, 'Matthew', 40, 21, 27, ' فأجابوا يسوع وقالوا : لا نعلم . فقال لهم هو أيضا : ولا أنا أقول لكم بأي سلطان أفعل هذا '),
(25956, 'Matthew', 40, 21, 28, ' ماذا تظنون ؟ كان لإنسان ابنان ، فجاء إلى الأول وقال : يا ابني ، اذهب اليوم اعمل في كرمي '),
(25957, 'Matthew', 40, 21, 29, ' فأجاب وقال : ما أريد . ولكنه ندم أخيرا ومضى '),
(25958, 'Matthew', 40, 21, 30, ' وجاء إلى الثاني وقال كذلك . فأجاب وقال : ها أنا يا سيد . ولم يمض '),
(25959, 'Matthew', 40, 21, 31, ' فأي الاثنين عمل إرادة الأب ؟  . قالوا له : الأول . قال لهم يسوع : الحق أقول لكم : إن العشارين والزواني يسبقونكم إلى ملكوت الله '),
(25960, 'Matthew', 40, 21, 32, ' لأن يوحنا جاءكم في طريق الحق فلم تؤمنوا به ، وأما العشارون والزواني فآمنوا به . وأنتم إذ رأيتم لم تندموا أخيرا لتؤمنوا به '),
(25961, 'Matthew', 40, 21, 33, ' اسمعوا مثلا آخر : كان إنسان رب بيت غرس كرما ، وأحاطه بسياج ، وحفر فيه معصرة ، وبنى برجا ، وسلمه إلى كرامين وسافر '),
(25962, 'Matthew', 40, 21, 34, ' ولما قرب وقت الأثمار أرسل عبيده إلى الكرامين ليأخذ أثماره '),
(25963, 'Matthew', 40, 21, 35, ' فأخذ الكرامون عبيده وجلدوا بعضا وقتلوا بعضا ورجموا بعضا '),
(25964, 'Matthew', 40, 21, 36, ' ثم أرسل أيضا عبيدا آخرين أكثر من الأولين ، ففعلوا بهم كذلك '),
(25965, 'Matthew', 40, 21, 37, ' فأخيرا أرسل إليهم ابنه قائلا : يهابون ابني '),
(25966, 'Matthew', 40, 21, 38, ' وأما الكرامون فلما رأوا الابن قالوا فيما بينهم : هذا هو الوارث هلموا نقتله ونأخذ ميراثه '),
(25967, 'Matthew', 40, 21, 39, ' فأخذوه وأخرجوه خارج الكرم وقتلوه '),
(25968, 'Matthew', 40, 21, 40, ' فمتى جاء صاحب الكرم ، ماذا يفعل بأولئك الكرامين '),
(25969, 'Matthew', 40, 21, 41, ' قالوا له : أولئك الأردياء يهلكهم هلاكا رديا ، ويسلم الكرم إلى كرامين آخرين يعطونه الأثمار في أوقاتها '),
(25970, 'Matthew', 40, 21, 42, ' قال لهم يسوع : أما قرأتم قط في الكتب : الحجر الذي رفضه البناؤون هو قد صار رأس الزاوية ؟ من قبل الرب كان هذا وهو عجيب في أعيننا '),
(25971, 'Matthew', 40, 21, 43, ' لذلك أقول لكم : إن ملكوت الله ينزع منكم ويعطى لأمة تعمل أثماره '),
(25972, 'Matthew', 40, 21, 44, ' ومن سقط على هذا الحجر يترضض ، ومن سقط هو عليه يسحقه '),
(25973, 'Matthew', 40, 21, 45, ' ولما سمع رؤساء الكهنة والفريسيون أمثاله ، عرفوا أنه تكلم عليهم '),
(25974, 'Matthew', 40, 21, 46, ' وإذ كانوا يطلبون أن يمسكوه ، خافوا من الجموع ، لأنه كان عندهم مثل نبي '),
(25975, 'Matthew', 40, 22, 1, ' وجعل يسوع يكلمهم أيضا بأمثال قائلا '),
(25976, 'Matthew', 40, 22, 2, ' يشبه ملكوت السماوات إنسانا ملكا صنع عرسا لابنه '),
(25977, 'Matthew', 40, 22, 3, ' وأرسل عبيده ليدعوا المدعوين إلى العرس ، فلم يريدوا أن يأتوا '),
(25978, 'Matthew', 40, 22, 4, ' فأرسل أيضا عبيدا آخرين قائلا : قولوا للمدعوين : هوذا غدائي أعددته . ثيراني ومسمناتي قد ذبحت ، وكل شيء معد . تعالوا إلى العرس '),
(25979, 'Matthew', 40, 22, 5, ' ولكنهم تهاونوا ومضوا ، واحد إلى حقله ، وآخر إلى تجارته '),
(25980, 'Matthew', 40, 22, 6, ' والباقون أمسكوا عبيده وشتموهم وقتلوهم '),
(25981, 'Matthew', 40, 22, 7, ' فلما سمع الملك غضب ، وأرسل جنوده وأهلك أولئك القاتلين وأحرق مدينتهم '),
(25982, 'Matthew', 40, 22, 8, ' ثم قال لعبيده : أما العرس فمستعد ، وأما المدعوون فلم يكونوا مستحقين '),
(25983, 'Matthew', 40, 22, 9, ' فاذهبوا إلى مفارق الطرق ، وكل من وجدتموه فادعوه إلى العرس '),
(25984, 'Matthew', 40, 22, 10, ' فخرج أولئك العبيد إلى الطرق ، وجمعوا كل الذين وجدوهم أشرارا وصالحين . فامتلأ العرس من المتكئين '),
(25985, 'Matthew', 40, 22, 11, ' فلما دخل الملك لينظر المتكئين ، رأى هناك إنسانا لم يكن لابسا لباس العرس '),
(25986, 'Matthew', 40, 22, 12, ' فقال له : يا صاحب ، كيف دخلت إلى هنا وليس عليك لباس العرس ؟ فسكت '),
(25987, 'Matthew', 40, 22, 13, ' حينئذ قال الملك للخدام : اربطوا رجليه ويديه ، وخذوه واطرحوه في الظلمة الخارجية . هناك يكون البكاء وصرير الأسنان '),
(25988, 'Matthew', 40, 22, 14, ' لأن كثيرين يدعون وقليلين ينتخبون '),
(25989, 'Matthew', 40, 22, 15, ' حينئذ ذهب الفريسيون وتشاوروا لكي يصطادوه بكلمة '),
(25990, 'Matthew', 40, 22, 16, ' فأرسلوا إليه تلاميذهم مع الهيرودسيين قائلين : يا معلم ، نعلم أنك صادق وتعلم طريق الله بالحق ، ولا تبالي بأحد ، لأنك لا تنظر إلى وجوه الناس '),
(25991, 'Matthew', 40, 22, 17, ' فقل لنا : ماذا تظن ؟ أيجوز أن تعطى جزية لقيصر أم لا '),
(25992, 'Matthew', 40, 22, 18, ' فعلم يسوع خبثهم وقال : لماذا تجربونني يا مراؤون '),
(25993, 'Matthew', 40, 22, 19, ' أروني معاملة الجزية . فقدموا له دينارا '),
(25994, 'Matthew', 40, 22, 20, ' فقال لهم : لمن هذه الصورة والكتابة '),
(25995, 'Matthew', 40, 22, 21, ' قالوا له : لقيصر . فقال لهم : أعطوا إذا ما لقيصر لقيصر وما لله لله '),
(25996, 'Matthew', 40, 22, 22, ' فلما سمعوا تعجبوا وتركوه ومضوا '),
(25997, 'Matthew', 40, 22, 23, ' في ذلك اليوم جاء إليه صدوقيون ، الذين يقولون ليس قيامة ، فسألوه '),
(25998, 'Matthew', 40, 22, 24, ' قائلين : يا معلم ، قال موسى : إن مات أحد وليس له أولاد ، يتزوج أخوه بامرأته ويقم نسلا لأخيه '),
(25999, 'Matthew', 40, 22, 25, ' فكان عندنا سبعة إخوة ، وتزوج الأول ومات . وإذ لم يكن له نسل ترك امرأته لأخيه '),
(26000, 'Matthew', 40, 22, 26, ' وكذلك الثاني والثالث إلى السبعة '),
(26001, 'Matthew', 40, 22, 27, ' وآخر الكل ماتت المرأة أيضا '),
(26002, 'Matthew', 40, 22, 28, ' ففي القيامة لمن من السبعة تكون زوجة ؟ فإنها كانت للجميع '),
(26003, 'Matthew', 40, 22, 29, ' فأجاب يسوع وقال لهم : تضلون إذ لا تعرفون الكتب ولا قوة الله '),
(26004, 'Matthew', 40, 22, 30, ' لأنهم في القيامة لا يزوجون ولا يتزوجون ، بل يكونون كملائكة الله في السماء '),
(26005, 'Matthew', 40, 22, 31, ' وأما من جهة قيامة الأموات ، أفما قرأتم ما قيل لكم من قبل الله القائل '),
(26006, 'Matthew', 40, 22, 32, ' أنا إله إبراهيم وإله إسحاق وإله يعقوب ؟ ليس الله إله أموات بل إله أحياء '),
(26007, 'Matthew', 40, 22, 33, ' فلما سمع الجموع بهتوا من تعليمه '),
(26008, 'Matthew', 40, 22, 34, ' أما الفريسيون فلما سمعوا أنه أبكم الصدوقيين اجتمعوا معا '),
(26009, 'Matthew', 40, 22, 35, ' وسأله واحد منهم ، وهو ناموسي ، ليجربه قائلا '),
(26010, 'Matthew', 40, 22, 36, ' يا معلم ، أية وصية هي العظمى في الناموس '),
(26011, 'Matthew', 40, 22, 37, ' فقال له يسوع : تحب الرب إلهك من كل قلبك ، ومن كل نفسك ، ومن كل فكرك '),
(26012, 'Matthew', 40, 22, 38, ' هذه هي الوصية الأولى والعظمى '),
(26013, 'Matthew', 40, 22, 39, ' والثانية مثلها : تحب قريبك كنفسك '),
(26014, 'Matthew', 40, 22, 40, ' بهاتين الوصيتين يتعلق الناموس كله والأنبياء '),
(26015, 'Matthew', 40, 22, 41, ' وفيما كان الفريسيون مجتمعين سألهم يسوع '),
(26016, 'Matthew', 40, 22, 42, ' قائلا : ماذا تظنون في المسيح ؟ ابن من هو ؟ قالوا له : ابن داود '),
(26017, 'Matthew', 40, 22, 43, ' قال لهم : فكيف يدعوه داود بالروح ربا ؟ قائلا '),
(26018, 'Matthew', 40, 22, 44, ' قال الرب لربي : اجلس عن يميني حتى أضع أعداءك موطئا لقدميك '),
(26019, 'Matthew', 40, 22, 45, ' فإن كان داود يدعوه ربا ، فكيف يكون ابنه '),
(26020, 'Matthew', 40, 22, 46, ' فلم يستطع أحد أن يجيبه بكلمة . ومن ذلك اليوم لم يجسر أحد أن يسأله بتة '),
(26021, 'Matthew', 40, 23, 1, ' حينئذ خاطب يسوع الجموع وتلاميذه '),
(26022, 'Matthew', 40, 23, 2, ' قائلا : على كرسي موسى جلس الكتبة والفريسيون '),
(26023, 'Matthew', 40, 23, 3, ' فكل ما قالوا لكم أن تحفظوه فاحفظوه وافعلوه ، ولكن حسب أعمالهم لا تعملوا ، لأنهم يقولون ولا يفعلون '),
(26024, 'Matthew', 40, 23, 4, ' فإنهم يحزمون أحمالا ثقيلة عسرة الحمل ويضعونها على أكتاف الناس ، وهم لا يريدون أن يحركوها بإصبعهم '),
(26025, 'Matthew', 40, 23, 5, ' وكل أعمالهم يعملونها لكي تنظرهم الناس : فيعرضون عصائبهم ويعظمون أهداب ثيابهم '),
(26026, 'Matthew', 40, 23, 6, ' ويحبون المتكأ الأول في الولائم ، والمجالس الأولى في المجامع '),
(26027, 'Matthew', 40, 23, 7, ' والتحيات في الأسواق ، وأن يدعوهم الناس : سيدي ، سيدي '),
(26028, 'Matthew', 40, 23, 8, ' وأما أنتم فلا تدعوا سيدي ، لأن معلمكم واحد المسيح ، وأنتم جميعا إخوة '),
(26029, 'Matthew', 40, 23, 9, ' ولا تدعوا لكم أبا على الأرض ، لأن أباكم واحد الذي في السماوات '),
(26030, 'Matthew', 40, 23, 10, ' ولا تدعوا معلمين ، لأن معلمكم واحد المسيح '),
(26031, 'Matthew', 40, 23, 11, ' وأكبركم يكون خادما لكم '),
(26032, 'Matthew', 40, 23, 12, ' فمن يرفع نفسه يتضع ، ومن يضع نفسه يرتفع '),
(26033, 'Matthew', 40, 23, 13, ' لكن ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم تغلقون ملكوت السماوات قدام الناس ، فلا تدخلون أنتم ولا تدعون الداخلين يدخلون '),
(26034, 'Matthew', 40, 23, 14, ' ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم تأكلون بيوت الأرامل ، ولعلة تطيلون صلواتكم . لذلك تأخذون دينونة أعظم '),
(26035, 'Matthew', 40, 23, 15, ' ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم تطوفون البحر والبر لتكسبوا دخيلا واحدا ، ومتى حصل تصنعونه ابنا لجهنم أكثر منكم مضاعفا '),
(26036, 'Matthew', 40, 23, 16, ' ويل لكم أيها القادة العميان القائلون : من حلف بالهيكل فليس بشيء ، ولكن من حلف بذهب الهيكل يلتزم '),
(26037, 'Matthew', 40, 23, 17, ' أيها الجهال والعميان أيما أعظم : ألذهب أم الهيكل الذي يقدس الذهب '),
(26038, 'Matthew', 40, 23, 18, ' ومن حلف بالمذبح فليس بشيء ، ولكن من حلف بالقربان الذي عليه يلتزم '),
(26039, 'Matthew', 40, 23, 19, ' أيها الجهال والعميان أيما أعظم : ألقربان أم المذبح الذي يقدس القربان '),
(26040, 'Matthew', 40, 23, 20, ' فإن من حلف بالمذبح فقد حلف به وبكل ما عليه '),
(26041, 'Matthew', 40, 23, 21, ' ومن حلف بالهيكل فقد حلف به وبالساكن فيه '),
(26042, 'Matthew', 40, 23, 22, ' ومن حلف بالسماء فقد حلف بعرش الله وبالجالس عليه ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(26043, 'Matthew', 40, 23, 23, ' ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم تعشرون النعنع والشبث والكمون ، وتركتم أثقل الناموس : الحق والرحمة والإيمان . كان ينبغي أن تعملوا هذه ولا تتركوا تلك '),
(26044, 'Matthew', 40, 23, 24, ' أيها القادة العميان الذين يصفون عن البعوضة ويبلعون الجمل '),
(26045, 'Matthew', 40, 23, 25, ' ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم تنقون خارج الكأس والصحفة ، وهما من داخل مملوآن اختطافا ودعارة '),
(26046, 'Matthew', 40, 23, 26, ' أيها الفريسي الأعمى نق أولا داخل الكأس والصحفة لكي يكون خارجهما أيضا نقيا '),
(26047, 'Matthew', 40, 23, 27, ' ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم تشبهون قبورا مبيضة تظهر من خارج جميلة ، وهي من داخل مملوءة عظام أموات وكل نجاسة '),
(26048, 'Matthew', 40, 23, 28, ' هكذا أنتم أيضا : من خارج تظهرون للناس أبرارا ، ولكنكم من داخل مشحونون رياء وإثما '),
(26049, 'Matthew', 40, 23, 29, ' ويل لكم أيها الكتبة والفريسيون المراؤون لأنكم تبنون قبور الأنبياء وتزينون مدافن الصديقين '),
(26050, 'Matthew', 40, 23, 30, ' وتقولون : لو كنا في أيام آبائنا لما شاركناهم في دم الأنبياء '),
(26051, 'Matthew', 40, 23, 31, ' فأنتم تشهدون على أنفسكم أنكم أبناء قتلة الأنبياء '),
(26052, 'Matthew', 40, 23, 32, ' فاملأوا أنتم مكيال آبائكم '),
(26053, 'Matthew', 40, 23, 33, ' أيها الحيات أولاد الأفاعي كيف تهربون من دينونة جهنم '),
(26054, 'Matthew', 40, 23, 34, ' لذلك ها أنا أرسل إليكم أنبياء وحكماء وكتبة ، فمنهم تقتلون وتصلبون ، ومنهم تجلدون في مجامعكم ، وتطردون من مدينة إلى مدينة '),
(26055, 'Matthew', 40, 23, 35, ' لكي يأتي عليكم كل دم زكي سفك على الأرض ، من دم هابيل الصديق إلى دم زكريا بن برخيا الذي قتلتموه بين الهيكل والمذبح '),
(26056, 'Matthew', 40, 23, 36, ' الحق أقول لكم : إن هذا كله يأتي على هذا الجيل '),
(26057, 'Matthew', 40, 23, 37, ' يا أورشليم ، يا أورشليم يا قاتلة الأنبياء وراجمة المرسلين إليها ، كم مرة أردت أن أجمع أولادك كما تجمع الدجاجة فراخها تحت جناحيها ، ولم تريدوا '),
(26058, 'Matthew', 40, 23, 38, ' هوذا بيتكم يترك لكم خرابا '),
(26059, 'Matthew', 40, 23, 39, ' لأني أقول لكم : إنكم لا ترونني من الآن حتى تقولوا : مبارك الآتي باسم الرب '),
(26060, 'Matthew', 40, 24, 1, ' ثم خرج يسوع ومضى من الهيكل ، فتقدم تلاميذه لكي يروه أبنية الهيكل '),
(26061, 'Matthew', 40, 24, 2, ' فقال لهم يسوع : أما تنظرون جميع هذه ؟ الحق أقول لكم : إنه لا يترك ههنا حجر على حجر لا ينقض '),
(26062, 'Matthew', 40, 24, 3, ' وفيما هو جالس على جبل الزيتون ، تقدم إليه التلاميذ على انفراد قائلين : قل لنا متى يكون هذا ؟ وما هي علامة مجيئك وانقضاء الدهر '),
(26063, 'Matthew', 40, 24, 4, ' فأجاب يسوع وقال لهم : انظروا لا يضلكم أحد '),
(26064, 'Matthew', 40, 24, 5, ' فإن كثيرين سيأتون باسمي قائلين : أنا هو المسيح ويضلون كثيرين '),
(26065, 'Matthew', 40, 24, 6, ' وسوف تسمعون بحروب وأخبار حروب . انظروا ، لا ترتاعوا . لأنه لابد أن تكون هذه كلها ، ولكن ليس المنتهى بعد '),
(26066, 'Matthew', 40, 24, 7, ' لأنه تقوم أمة على أمة ومملكة على مملكة ، وتكون مجاعات وأوبئة وزلازل في أماكن '),
(26067, 'Matthew', 40, 24, 8, ' ولكن هذه كلها مبتدأ الأوجاع '),
(26068, 'Matthew', 40, 24, 9, ' حينئذ يسلمونكم إلى ضيق ويقتلونكم ، وتكونون مبغضين من جميع الأمم لأجل اسمي '),
(26069, 'Matthew', 40, 24, 10, ' وحينئذ يعثر كثيرون ويسلمون بعضهم بعضا ويبغضون بعضهم بعضا '),
(26070, 'Matthew', 40, 24, 11, ' ويقوم أنبياء كذبة كثيرون ويضلون كثيرين '),
(26071, 'Matthew', 40, 24, 12, ' ولكثرة الإثم تبرد محبة الكثيرين '),
(26072, 'Matthew', 40, 24, 13, ' ولكن الذي يصبر إلى المنتهى فهذا يخلص '),
(26073, 'Matthew', 40, 24, 14, ' ويكرز ببشارة الملكوت هذه في كل المسكونة شهادة لجميع الأمم . ثم يأتي المنتهى '),
(26074, 'Matthew', 40, 24, 15, ' فمتى نظرتم رجسة الخراب التي قال عنها دانيآل النبي قائمة في المكان المقدس ليفهم القارئ '),
(26075, 'Matthew', 40, 24, 16, ' فحينئذ ليهرب الذين في اليهودية إلى الجبال '),
(26076, 'Matthew', 40, 24, 17, ' والذي على السطح فلا ينزل ليأخذ من بيته شيئا '),
(26077, 'Matthew', 40, 24, 18, ' والذي في الحقل فلا يرجع إلى ورائه ليأخذ ثيابه '),
(26078, 'Matthew', 40, 24, 19, ' وويل للحبالى والمرضعات في تلك الأيام '),
(26079, 'Matthew', 40, 24, 20, ' وصلوا لكي لا يكون هربكم في شتاء ولا في سبت '),
(26080, 'Matthew', 40, 24, 21, ' لأنه يكون حينئذ ضيق عظيم لم يكن مثله منذ ابتداء العالم إلى الآن ولن يكون '),
(26081, 'Matthew', 40, 24, 22, ' ولو لم تقصر تلك الأيام لم يخلص جسد . ولكن لأجل المختارين تقصر تلك الأيام '),
(26082, 'Matthew', 40, 24, 23, ' حينئذ إن قال لكم أحد : هوذا المسيح هنا أو : هناك فلا تصدقوا '),
(26083, 'Matthew', 40, 24, 24, ' لأنه سيقوم مسحاء كذبة وأنبياء كذبة ويعطون آيات عظيمة وعجائب ، حتى يضلوا لو أمكن المختارين أيضا '),
(26084, 'Matthew', 40, 24, 25, ' ها أنا قد سبقت وأخبرتكم '),
(26085, 'Matthew', 40, 24, 26, ' فإن قالوا لكم : ها هو في البرية فلا تخرجوا . ها هو في المخادع فلا تصدقوا '),
(26086, 'Matthew', 40, 24, 27, ' لأنه كما أن البرق يخرج من المشارق ويظهر إلى المغارب ، هكذا يكون أيضا مجيء ابن الإنسان '),
(26087, 'Matthew', 40, 24, 28, ' لأنه حيثما تكن الجثة ، فهناك تجتمع النسور '),
(26088, 'Matthew', 40, 24, 29, ' وللوقت بعد ضيق تلك الأيام : تظلم الشمس ، والقمر لا يعطي ضوءه ، والنجوم تسقط من السماء ، وقوات السماوات تزعزع '),
(26089, 'Matthew', 40, 24, 30, ' وحينئذ تظهر علامة ابن الإنسان في السماء . وحينئذ تنوح جميع قبائل الأرض ، ويبصرون ابن الإنسان آتيا على سحاب السماء بقوة ومجد كثير '),
(26090, 'Matthew', 40, 24, 31, ' فيرسل ملائكته ببوق عظيم الصوت ، فيجمعون مختاريه من الأربع الرياح ، من أقصاء السماوات إلى أقصائها '),
(26091, 'Matthew', 40, 24, 32, ' فمن شجرة التين تعلموا المثل : متى صار غصنها رخصا وأخرجت أوراقها ، تعلمون أن الصيف قريب '),
(26092, 'Matthew', 40, 24, 33, ' هكذا أنتم أيضا ، متى رأيتم هذا كله فاعلموا أنه قريب على الأبواب '),
(26093, 'Matthew', 40, 24, 34, ' الحق أقول لكم : لا يمضي هذا الجيل حتى يكون هذا كله '),
(26094, 'Matthew', 40, 24, 35, ' السماء والأرض تزولان ولكن كلامي لا يزول '),
(26095, 'Matthew', 40, 24, 36, ' وأما ذلك اليوم وتلك الساعة فلا يعلم بهما أحد ، ولا ملائكة السماوات ، إلا أبي وحده '),
(26096, 'Matthew', 40, 24, 37, ' وكما كانت أيام نوح كذلك يكون أيضا مجيء ابن الإنسان '),
(26097, 'Matthew', 40, 24, 38, ' لأنه كما كانوا في الأيام التي قبل الطوفان يأكلون ويشربون ويتزوجون ويزوجون ، إلى اليوم الذي دخل فيه نوح الفلك '),
(26098, 'Matthew', 40, 24, 39, ' ولم يعلموا حتى جاء الطوفان وأخذ الجميع ، كذلك يكون أيضا مجيء ابن الإنسان '),
(26099, 'Matthew', 40, 24, 40, ' حينئذ يكون اثنان في الحقل ، يؤخذ الواحد ويترك الآخر '),
(26100, 'Matthew', 40, 24, 41, ' اثنتان تطحنان على الرحى ، تؤخذ الواحدة وتترك الأخرى '),
(26101, 'Matthew', 40, 24, 42, ' اسهروا إذا لأنكم لا تعلمون في أية ساعة يأتي ربكم '),
(26102, 'Matthew', 40, 24, 43, ' واعلموا هذا : أنه لو عرف رب البيت في أي هزيع يأتي السارق ، لسهر ولم يدع بيته ينقب '),
(26103, 'Matthew', 40, 24, 44, ' لذلك كونوا أنتم أيضا مستعدين ، لأنه في ساعة لا تظنون يأتي ابن الإنسان '),
(26104, 'Matthew', 40, 24, 45, ' فمن هو العبد الأمين الحكيم الذي أقامه سيده على خدمه ليعطيهم الطعام في حينه '),
(26105, 'Matthew', 40, 24, 46, ' طوبى لذلك العبد الذي إذا جاء سيده يجده يفعل هكذا '),
(26106, 'Matthew', 40, 24, 47, ' الحق أقول لكم : إنه يقيمه على جميع أمواله '),
(26107, 'Matthew', 40, 24, 48, ' ولكن إن قال ذلك العبد الردي في قلبه : سيدي يبطئ قدومه '),
(26108, 'Matthew', 40, 24, 49, ' فيبتدئ يضرب العبيد رفقاءه ويأكل ويشرب مع السكارى '),
(26109, 'Matthew', 40, 24, 50, ' يأتي سيد ذلك العبد في يوم لا ينتظره وفي ساعة لا يعرفها '),
(26110, 'Matthew', 40, 24, 51, ' فيقطعه ويجعل نصيبه مع المرائين . هناك يكون البكاء وصرير الأسنان '),
(26111, 'Matthew', 40, 25, 1, ' حينئذ يشبه ملكوت السماوات عشر عذارى ، أخذن مصابيحهن وخرجن للقاء العريس '),
(26112, 'Matthew', 40, 25, 2, ' وكان خمس منهن حكيمات ، وخمس جاهلات '),
(26113, 'Matthew', 40, 25, 3, ' أما الجاهلات فأخذن مصابيحهن ولم يأخذن معهن زيتا '),
(26114, 'Matthew', 40, 25, 4, ' وأما الحكيمات فأخذن زيتا في آنيتهن مع مصابيحهن '),
(26115, 'Matthew', 40, 25, 5, ' وفيما أبطأ العريس نعسن جميعهن ونمن '),
(26116, 'Matthew', 40, 25, 6, ' ففي نصف الليل صار صراخ : هوذا العريس مقبل ، فاخرجن للقائه '),
(26117, 'Matthew', 40, 25, 7, ' فقامت جميع أولئك العذارى وأصلحن مصابيحهن '),
(26118, 'Matthew', 40, 25, 8, ' فقالت الجاهلات للحكيمات : أعطيننا من زيتكن فإن مصابيحنا تنطفئ '),
(26119, 'Matthew', 40, 25, 9, ' فأجابت الحكيمات قائلات : لعله لا يكفي لنا ولكن ، بل اذهبن إلى الباعة وابتعن لكن '),
(26120, 'Matthew', 40, 25, 10, ' وفيما هن ذاهبات ليبتعن جاء العريس ، والمستعدات دخلن معه إلى العرس ، وأغلق الباب '),
(26121, 'Matthew', 40, 25, 11, ' أخيرا جاءت بقية العذارى أيضا قائلات : يا سيد ، يا سيد ، افتح لنا '),
(26122, 'Matthew', 40, 25, 12, ' فأجاب وقال : الحق أقول لكن : إني ما أعرفكن '),
(26123, 'Matthew', 40, 25, 13, ' فاسهروا إذا لأنكم لا تعرفون اليوم ولا الساعة التي يأتي فيها ابن الإنسان '),
(26124, 'Matthew', 40, 25, 14, ' وكأنما إنسان مسافر دعا عبيده وسلمهم أمواله '),
(26125, 'Matthew', 40, 25, 15, ' فأعطى واحدا خمس وزنات ، وآخر وزنتين ، وآخر وزنة . كل واحد على قدر طاقته . وسافر للوقت '),
(26126, 'Matthew', 40, 25, 16, ' فمضى الذي أخذ الخمس وزنات وتاجر بها ، فربح خمس وزنات أخر '),
(26127, 'Matthew', 40, 25, 17, ' وهكذا الذي أخذ الوزنتين ، ربح أيضا وزنتين أخريين '),
(26128, 'Matthew', 40, 25, 18, ' وأما الذي أخذ الوزنة فمضى وحفر في الأرض وأخفى فضة سيده '),
(26129, 'Matthew', 40, 25, 19, ' وبعد زمان طويل أتى سيد أولئك العبيد وحاسبهم '),
(26130, 'Matthew', 40, 25, 20, ' فجاء الذي أخذ الخمس وزنات وقدم خمس وزنات أخر قائلا : يا سيد ، خمس وزنات سلمتني . هوذا خمس وزنات أخر ربحتها فوقها '),
(26131, 'Matthew', 40, 25, 21, ' فقال له سيده : نعما أيها العبد الصالح والأمين كنت أمينا في القليل فأقيمك على الكثير . ادخل إلى فرح سيدك '),
(26132, 'Matthew', 40, 25, 22, ' ثم جاء الذي أخذ الوزنتين وقال : يا سيد ، وزنتين سلمتني . هوذا وزنتان أخريان ربحتهما فوقهما '),
(26133, 'Matthew', 40, 25, 23, ' قال له سيده : نعما أيها العبد الصالح الأمين كنت أمينا في القليل فأقيمك على الكثير . ادخل إلى فرح سيدك '),
(26134, 'Matthew', 40, 25, 24, ' ثم جاء أيضا الذي أخذ الوزنة الواحدة وقال : يا سيد ، عرفت أنك إنسان قاس ، تحصد حيث لم تزرع ، وتجمع من حيث لم تبذر '),
(26135, 'Matthew', 40, 25, 25, ' فخفت ومضيت وأخفيت وزنتك في الأرض . هوذا الذي لك '),
(26136, 'Matthew', 40, 25, 26, ' فأجاب سيده وقال له : أيها العبد الشرير والكسلان ، عرفت أني أحصد حيث لم أزرع ، وأجمع من حيث لم أبذر '),
(26137, 'Matthew', 40, 25, 27, ' فكان ينبغي أن تضع فضتي عند الصيارفة ، فعند مجيئي كنت آخذ الذي لي مع ربا '),
(26138, 'Matthew', 40, 25, 28, ' فخذوا منه الوزنة وأعطوها للذي له العشر وزنات '),
(26139, 'Matthew', 40, 25, 29, ' لأن كل من له يعطى فيزداد ، ومن ليس له فالذي عنده يؤخذ منه '),
(26140, 'Matthew', 40, 25, 30, ' والعبد البطال اطرحوه إلى الظلمة الخارجية ، هناك يكون البكاء وصرير الأسنان '),
(26141, 'Matthew', 40, 25, 31, ' ومتى جاء ابن الإنسان في مجده وجميع الملائكة القديسين معه ، فحينئذ يجلس على كرسي مجده '),
(26142, 'Matthew', 40, 25, 32, ' ويجتمع أمامه جميع الشعوب ، فيميز بعضهم من بعض كما يميز الراعي الخراف من الجداء '),
(26143, 'Matthew', 40, 25, 33, ' فيقيم الخراف عن يمينه والجداء عن اليسار '),
(26144, 'Matthew', 40, 25, 34, ' ثم يقول الملك للذين عن يمينه : تعالوا يا مباركي أبي ، رثوا الملكوت المعد لكم منذ تأسيس العالم '),
(26145, 'Matthew', 40, 25, 35, ' لأني جعت فأطعمتموني . عطشت فسقيتموني . كنت غريبا فآويتموني '),
(26146, 'Matthew', 40, 25, 36, ' عريانا فكسوتموني . مريضا فزرتموني . محبوسا فأتيتم إلي '),
(26147, 'Matthew', 40, 25, 37, ' فيجيبه الأبرار حينئذ قائلين : يا رب ، متى رأيناك جائعا فأطعمناك ، أو عطشانا فسقيناك '),
(26148, 'Matthew', 40, 25, 38, ' ومتى رأيناك غريبا فآويناك ، أو عريانا فكسوناك '),
(26149, 'Matthew', 40, 25, 39, ' ومتى رأيناك مريضا أو محبوسا فأتينا إليك '),
(26150, 'Matthew', 40, 25, 40, ' فيجيب الملك ويقول لهم : الحق أقول لكم : بما أنكم فعلتموه بأحد إخوتي هؤلاء الأصاغر ، فبي فعلتم '),
(26151, 'Matthew', 40, 25, 41, ' ثم يقول أيضا للذين عن اليسار : اذهبوا عني يا ملاعين إلى النار الأبدية المعدة لإبليس وملائكته '),
(26152, 'Matthew', 40, 25, 42, ' لأني جعت فلم تطعموني . عطشت فلم تسقوني '),
(26153, 'Matthew', 40, 25, 43, ' كنت غريبا فلم تأووني . عريانا فلم تكسوني . مريضا ومحبوسا فلم تزوروني '),
(26154, 'Matthew', 40, 25, 44, ' حينئذ يجيبونه هم أيضا قائلين : يا رب ، متى رأيناك جائعا أو عطشانا أو غريبا أو عريانا أو مريضا أو محبوسا ولم نخدمك '),
(26155, 'Matthew', 40, 25, 45, ' فيجيبهم قائلا : الحق أقول لكم : بما أنكم لم تفعلوه بأحد هؤلاء الأصاغر ، فبي لم تفعلوا '),
(26156, 'Matthew', 40, 25, 46, ' فيمضي هؤلاء إلى عذاب أبدي والأبرار إلى حياة أبدية '),
(26157, 'Matthew', 40, 26, 1, ' ولما أكمل يسوع هذه الأقوال كلها قال لتلاميذه '),
(26158, 'Matthew', 40, 26, 2, ' تعلمون أنه بعد يومين يكون الفصح ، وابن الإنسان يسلم ليصلب '),
(26159, 'Matthew', 40, 26, 3, ' حينئذ اجتمع رؤساء الكهنة والكتبة وشيوخ الشعب إلى دار رئيس الكهنة الذي يدعى قيافا '),
(26160, 'Matthew', 40, 26, 4, ' وتشاوروا لكي يمسكوا يسوع بمكر ويقتلوه '),
(26161, 'Matthew', 40, 26, 5, ' ولكنهم قالوا : ليس في العيد لئلا يكون شغب في الشعب '),
(26162, 'Matthew', 40, 26, 6, ' وفيما كان يسوع في بيت عنيا في بيت سمعان الأبرص '),
(26163, 'Matthew', 40, 26, 7, ' تقدمت إليه امرأة معها قارورة طيب كثير الثمن ، فسكبته على رأسه وهو متكئ '),
(26164, 'Matthew', 40, 26, 8, ' فلما رأى تلاميذه ذلك اغتاظوا قائلين : لماذا هذا الإتلاف '),
(26165, 'Matthew', 40, 26, 9, ' لأنه كان يمكن أن يباع هذا الطيب بكثير ويعطى للفقراء '),
(26166, 'Matthew', 40, 26, 10, ' فعلم يسوع وقال لهم : لماذا تزعجون المرأة ؟ فإنها قد عملت بي عملا حسنا '),
(26167, 'Matthew', 40, 26, 11, ' لأن الفقراء معكم في كل حين ، وأما أنا فلست معكم في كل حين '),
(26168, 'Matthew', 40, 26, 12, ' فإنها إذ سكبت هذا الطيب على جسدي إنما فعلت ذلك لأجل تكفيني '),
(26169, 'Matthew', 40, 26, 13, ' الحق أقول لكم : حيثما يكرز بهذا الإنجيل في كل العالم ، يخبر أيضا بما فعلته هذه تذكارا لها '),
(26170, 'Matthew', 40, 26, 14, ' حينئذ ذهب واحد من الاثني عشر ، الذي يدعى يهوذا الإسخريوطي ، إلى رؤساء الكهنة '),
(26171, 'Matthew', 40, 26, 15, ' وقال : ماذا تريدون أن تعطوني وأنا أسلمه إليكم ؟ فجعلوا له ثلاثين من الفضة '),
(26172, 'Matthew', 40, 26, 16, ' ومن ذلك الوقت كان يطلب فرصة ليسلمه '),
(26173, 'Matthew', 40, 26, 17, ' وفي أول أيام الفطير تقدم التلاميذ إلى يسوع قائلين له : أين تريد أن نعد لك لتأكل الفصح '),
(26174, 'Matthew', 40, 26, 18, ' فقال : اذهبوا إلى المدينة ، إلى فلان وقولوا له : المعلم يقول : إن وقتي قريب . عندك أصنع الفصح مع تلاميذي '),
(26175, 'Matthew', 40, 26, 19, ' ففعل التلاميذ كما أمرهم يسوع وأعدوا الفصح '),
(26176, 'Matthew', 40, 26, 20, ' ولما كان المساء اتكأ مع الاثني عشر '),
(26177, 'Matthew', 40, 26, 21, ' وفيما هم يأكلون قال : الحق أقول لكم : إن واحدا منكم يسلمني '),
(26178, 'Matthew', 40, 26, 22, ' فحزنوا جدا ، وابتدأ كل واحد منهم يقول له : هل أنا هو يا رب '),
(26179, 'Matthew', 40, 26, 23, ' فأجاب وقال : الذي يغمس يده معي في الصحفة هو يسلمني '),
(26180, 'Matthew', 40, 26, 24, ' إن ابن الإنسان ماض كما هو مكتوب عنه ، ولكن ويل لذلك الرجل الذي به يسلم ابن الإنسان . كان خيرا لذلك الرجل لو لم يولد '),
(26181, 'Matthew', 40, 26, 25, ' فأجاب يهوذا مسلمه وقال : هل أنا هو يا سيدي ؟ قال له : أنت قلت '),
(26182, 'Matthew', 40, 26, 26, ' وفيما هم يأكلون أخذ يسوع الخبز ، وبارك وكسر وأعطى التلاميذ وقال : خذوا كلوا . هذا هو جسدي '),
(26183, 'Matthew', 40, 26, 27, ' وأخذ الكأس وشكر وأعطاهم قائلا : اشربوا منها كلكم '),
(26184, 'Matthew', 40, 26, 28, ' لأن هذا هو دمي الذي للعهد الجديد الذي يسفك من أجل كثيرين لمغفرة الخطايا '),
(26185, 'Matthew', 40, 26, 29, ' وأقول لكم : إني من الآن لا أشرب من نتاج الكرمة هذا إلى ذلك اليوم حينما أشربه معكم جديدا في ملكوت أبي '),
(26186, 'Matthew', 40, 26, 30, ' ثم سبحوا وخرجوا إلى جبل الزيتون '),
(26187, 'Matthew', 40, 26, 31, ' حينئذ قال لهم يسوع : كلكم تشكون في في هذه الليلة ، لأنه مكتوب : أني أضرب الراعي فتتبدد خراف الرعية '),
(26188, 'Matthew', 40, 26, 32, ' ولكن بعد قيامي أسبقكم إلى الجليل '),
(26189, 'Matthew', 40, 26, 33, ' فأجاب بطرس وقال له : وإن شك فيك الجميع فأنا لا أشك أبدا '),
(26190, 'Matthew', 40, 26, 34, ' قال له يسوع : الحق أقول لك : إنك في هذه الليلة قبل أن يصيح ديك تنكرني ثلاث مرات '),
(26191, 'Matthew', 40, 26, 35, ' قال له بطرس : ولو اضطررت أن أموت معك لا أنكرك . هكذا قال أيضا جميع التلاميذ '),
(26192, 'Matthew', 40, 26, 36, ' حينئذ جاء معهم يسوع إلى ضيعة يقال لها جثسيماني ، فقال للتلاميذ : اجلسوا ههنا حتى أمضي وأصلي هناك '),
(26193, 'Matthew', 40, 26, 37, ' ثم أخذ معه بطرس وابني زبدي ، وابتدأ يحزن ويكتئب '),
(26194, 'Matthew', 40, 26, 38, ' فقال لهم : نفسي حزينة جدا حتى الموت . امكثوا ههنا واسهروا معي '),
(26195, 'Matthew', 40, 26, 39, ' ثم تقدم قليلا وخر على وجهه ، وكان يصلي قائلا : يا أبتاه ، إن أمكن فلتعبر عني هذه الكأس ، ولكن ليس كما أريد أنا بل كما تريد أنت '),
(26196, 'Matthew', 40, 26, 40, ' ثم جاء إلى التلاميذ فوجدهم نياما ، فقال لبطرس : أهكذا ما قدرتم أن تسهروا معي ساعة واحدة '),
(26197, 'Matthew', 40, 26, 41, ' اسهروا وصلوا لئلا تدخلوا في تجربة . أما الروح فنشيط وأما الجسد فضعيف '),
(26198, 'Matthew', 40, 26, 42, ' فمضى أيضا ثانية وصلى قائلا : يا أبتاه ، إن لم يمكن أن تعبر عني هذه الكأس إلا أن أشربها ، فلتكن مشيئتك '),
(26199, 'Matthew', 40, 26, 43, ' ثم جاء فوجدهم أيضا نياما ، إذ كانت أعينهم ثقيلة '),
(26200, 'Matthew', 40, 26, 44, ' فتركهم ومضى أيضا وصلى ثالثة قائلا ذلك الكلام بعينه '),
(26201, 'Matthew', 40, 26, 45, ' ثم جاء إلى تلاميذه وقال لهم : ناموا الآن واستريحوا هوذا الساعة قد اقتربت ، وابن الإنسان يسلم إلى أيدي الخطاة '),
(26202, 'Matthew', 40, 26, 46, ' قوموا ننطلق هوذا الذي يسلمني قد اقترب '),
(26203, 'Matthew', 40, 26, 47, ' وفيما هو يتكلم ، إذا يهوذا أحد الاثني عشر قد جاء ومعه جمع كثير بسيوف وعصي من عند رؤساء الكهنة وشيوخ الشعب '),
(26204, 'Matthew', 40, 26, 48, ' والذي أسلمه أعطاهم علامة قائلا : الذي أقبله هو هو . أمسكوه '),
(26205, 'Matthew', 40, 26, 49, ' فللوقت تقدم إلى يسوع وقال : السلام يا سيدي وقبله '),
(26206, 'Matthew', 40, 26, 50, ' فقال له يسوع : يا صاحب ، لماذا جئت ؟ حينئذ تقدموا وألقوا الأيادي على يسوع وأمسكوه '),
(26207, 'Matthew', 40, 26, 51, ' وإذا واحد من الذين مع يسوع مد يده واستل سيفه وضرب عبد رئيس الكهنة ، فقطع أذنه '),
(26208, 'Matthew', 40, 26, 52, ' فقال له يسوع : رد سيفك إلى مكانه . لأن كل الذين يأخذون السيف بالسيف يهلكون '),
(26209, 'Matthew', 40, 26, 53, ' أتظن أني لا أستطيع الآن أن أطلب إلى أبي فيقدم لي أكثر من اثني عشر جيشا من الملائكة '),
(26210, 'Matthew', 40, 26, 54, ' فكيف تكمل الكتب : أنه هكذا ينبغي أن يكون '),
(26211, 'Matthew', 40, 26, 55, ' في تلك الساعة قال يسوع للجموع : كأنه على لص خرجتم بسيوف وعصي لتأخذوني كل يوم كنت أجلس معكم أعلم في الهيكل ولم تمسكوني '),
(26212, 'Matthew', 40, 26, 56, ' وأما هذا كله فقد كان لكي تكمل كتب الأنبياء . حينئذ تركه التلاميذ كلهم وهربوا '),
(26213, 'Matthew', 40, 26, 57, ' والذين أمسكوا يسوع مضوا به إلى قيافا رئيس الكهنة ، حيث اجتمع الكتبة والشيوخ '),
(26214, 'Matthew', 40, 26, 58, ' وأما بطرس فتبعه من بعيد إلى دار رئيس الكهنة ، فدخل إلى داخل وجلس بين الخدام لينظر النهاية '),
(26215, 'Matthew', 40, 26, 59, ' وكان رؤساء الكهنة والشيوخ والمجمع كله يطلبون شهادة زور على يسوع لكي يقتلوه '),
(26216, 'Matthew', 40, 26, 60, ' فلم يجدوا . ومع أنه جاء شهود زور كثيرون ، لم يجدوا . ولكن أخيرا تقدم شاهدا زور '),
(26217, 'Matthew', 40, 26, 61, ' وقالا : هذا قال : إني أقدر أن أنقض هيكل الله ، وفي ثلاثة أيام أبنيه '),
(26218, 'Matthew', 40, 26, 62, ' فقام رئيس الكهنة وقال له : أما تجيب بشيء ؟ ماذا يشهد به هذان عليك '),
(26219, 'Matthew', 40, 26, 63, ' وأما يسوع فكان ساكتا . فأجاب رئيس الكهنة وقال له : أستحلفك بالله الحي أن تقول لنا : هل أنت المسيح ابن الله '),
(26220, 'Matthew', 40, 26, 64, ' قال له يسوع : أنت قلت وأيضا أقول لكم : من الآن تبصرون ابن الإنسان جالسا عن يمين القوة ، وآتيا على سحاب السماء '),
(26221, 'Matthew', 40, 26, 65, ' فمزق رئيس الكهنة حينئذ ثيابه قائلا : قد جدف ما حاجتنا بعد إلى شهود ؟ ها قد سمعتم تجديفه '),
(26222, 'Matthew', 40, 26, 66, ' ماذا ترون ؟ فأجابوا وقالوا : إنه مستوجب الموت '),
(26223, 'Matthew', 40, 26, 67, ' حينئذ بصقوا في وجهه ولكموه ، وآخرون لطموه '),
(26224, 'Matthew', 40, 26, 68, ' قائلين : تنبأ لنا أيها المسيح ، من ضربك '),
(26225, 'Matthew', 40, 26, 69, ' أما بطرس فكان جالسا خارجا في الدار ، فجاءت إليه جارية قائلة : وأنت كنت مع يسوع الجليلي '),
(26226, 'Matthew', 40, 26, 70, ' فأنكر قدام الجميع قائلا : لست أدري ما تقولين '),
(26227, 'Matthew', 40, 26, 71, ' ثم إذ خرج إلى الدهليز رأته أخرى ، فقالت للذين هناك : وهذا كان مع يسوع الناصري '),
(26228, 'Matthew', 40, 26, 72, ' فأنكر أيضا بقسم : إني لست أعرف الرجل '),
(26229, 'Matthew', 40, 26, 73, ' وبعد قليل جاء القيام وقالوا لبطرس : حقا أنت أيضا منهم ، فإن لغتك تظهرك '),
(26230, 'Matthew', 40, 26, 74, ' فابتدأ حينئذ يلعن ويحلف : إني لا أعرف الرجل وللوقت صاح الديك '),
(26231, 'Matthew', 40, 26, 75, ' فتذكر بطرس كلام يسوع الذي قال له : إنك قبل أن يصيح الديك تنكرني ثلاث مرات . فخرج إلى خارج وبكى بكاء مرا '),
(26232, 'Matthew', 40, 27, 1, ' ولما كان الصباح تشاور جميع رؤساء الكهنة وشيوخ الشعب على يسوع حتى يقتلوه '),
(26233, 'Matthew', 40, 27, 2, ' فأوثقوه ومضوا به ودفعوه إلى بيلاطس البنطي الوالي '),
(26234, 'Matthew', 40, 27, 3, ' حينئذ لما رأى يهوذا الذي أسلمه أنه قد دين ، ندم ورد الثلاثين من الفضة إلى رؤساء الكهنة والشيوخ '),
(26235, 'Matthew', 40, 27, 4, ' قائلا : قد أخطأت إذ سلمت دما بريئا . فقالوا : ماذا علينا ؟ أنت أبصر '),
(26236, 'Matthew', 40, 27, 5, ' فطرح الفضة في الهيكل وانصرف ، ثم مضى وخنق نفسه '),
(26237, 'Matthew', 40, 27, 6, ' فأخذ رؤساء الكهنة الفضة وقالوا : لا يحل أن نلقيها في الخزانة لأنها ثمن دم '),
(26238, 'Matthew', 40, 27, 7, ' فتشاوروا واشتروا بها حقل الفخاري مقبرة للغرباء '),
(26239, 'Matthew', 40, 27, 8, ' لهذا سمي ذلك الحقل حقل الدم إلى هذا اليوم '),
(26240, 'Matthew', 40, 27, 9, ' حينئذ تم ما قيل بإرميا النبي القائل : وأخذوا الثلاثين من الفضة ، ثمن المثمن الذي ثمنوه من بني إسرائيل '),
(26241, 'Matthew', 40, 27, 10, ' وأعطوها عن حقل الفخاري ، كما أمرني الرب '),
(26242, 'Matthew', 40, 27, 11, ' فوقف يسوع أمام الوالي . فسأله الوالي قائلا : أأنت ملك اليهود ؟ فقال له يسوع : أنت تقول '),
(26243, 'Matthew', 40, 27, 12, ' وبينما كان رؤساء الكهنة والشيوخ يشتكون عليه لم يجب بشيء '),
(26244, 'Matthew', 40, 27, 13, ' فقال له بيلاطس : أما تسمع كم يشهدون عليك '),
(26245, 'Matthew', 40, 27, 14, ' فلم يجبه ولا عن كلمة واحدة ، حتى تعجب الوالي جدا '),
(26246, 'Matthew', 40, 27, 15, ' وكان الوالي معتادا في العيد أن يطلق للجمع أسيرا واحدا ، من أرادوه '),
(26247, 'Matthew', 40, 27, 16, ' وكان لهم حينئذ أسير مشهور يسمى باراباس '),
(26248, 'Matthew', 40, 27, 17, ' ففيما هم مجتمعون قال لهم بيلاطس : من تريدون أن أطلق لكم ؟ باراباس أم يسوع الذي يدعى المسيح '),
(26249, 'Matthew', 40, 27, 18, ' لأنه علم أنهم أسلموه حسدا '),
(26250, 'Matthew', 40, 27, 19, ' وإذ كان جالسا على كرسي الولاية أرسلت إليه امرأته قائلة : إياك وذلك البار ، لأني تألمت اليوم كثيرا في حلم من أجله '),
(26251, 'Matthew', 40, 27, 20, ' ولكن رؤساء الكهنة والشيوخ حرضوا الجموع على أن يطلبوا باراباس ويهلكوا يسوع '),
(26252, 'Matthew', 40, 27, 21, ' فأجاب الوالي وقال لهم : من من الاثنين تريدون أن أطلق لكم ؟ فقالوا : باراباس '),
(26253, 'Matthew', 40, 27, 22, ' قال لهم بيلاطس : فماذا أفعل بيسوع الذي يدعى المسيح ؟ قال له الجميع : ليصلب '),
(26254, 'Matthew', 40, 27, 23, ' فقال الوالي : وأي شر عمل ؟ فكانوا يزدادون صراخا قائلين : ليصلب '),
(26255, 'Matthew', 40, 27, 24, ' فلما رأى بيلاطس أنه لا ينفع شيئا ، بل بالحري يحدث شغب ، أخذ ماء وغسل يديه قدام الجمع قائلا : إني بريء من دم هذا البار أبصروا أنتم '),
(26256, 'Matthew', 40, 27, 25, ' فأجاب جميع الشعب وقالوا : دمه علينا وعلى أولادنا '),
(26257, 'Matthew', 40, 27, 26, ' حينئذ أطلق لهم باراباس ، وأما يسوع فجلده وأسلمه ليصلب '),
(26258, 'Matthew', 40, 27, 27, ' فأخذ عسكر الوالي يسوع إلى دار الولاية وجمعوا عليه كل الكتيبة '),
(26259, 'Matthew', 40, 27, 28, ' فعروه وألبسوه رداء قرمزيا '),
(26260, 'Matthew', 40, 27, 29, ' وضفروا إكليلا من شوك ووضعوه على رأسه ، وقصبة في يمينه . وكانوا يجثون قدامه ويستهزئون به قائلين : السلام يا ملك اليهود '),
(26261, 'Matthew', 40, 27, 30, ' وبصقوا عليه ، وأخذوا القصبة وضربوه على رأسه '),
(26262, 'Matthew', 40, 27, 31, ' وبعد ما استهزأوا به ، نزعوا عنه الرداء وألبسوه ثيابه ، ومضوا به للصلب '),
(26263, 'Matthew', 40, 27, 32, ' وفيما هم خارجون وجدوا إنسانا قيروانيا اسمه سمعان ، فسخروه ليحمل صليبه '),
(26264, 'Matthew', 40, 27, 33, ' ولما أتوا إلى موضع يقال له جلجثة ، وهو المسمى موضع الجمجمة '),
(26265, 'Matthew', 40, 27, 34, ' أعطوه خلا ممزوجا بمرارة ليشرب . ولما ذاق لم يرد أن يشرب '),
(26266, 'Matthew', 40, 27, 35, ' ولما صلبوه اقتسموا ثيابه مقترعين عليها ، لكي يتم ما قيل بالنبي : اقتسموا ثيابي بينهم ، وعلى لباسي ألقوا قرعة '),
(26267, 'Matthew', 40, 27, 36, ' ثم جلسوا يحرسونه هناك '),
(26268, 'Matthew', 40, 27, 37, ' وجعلوا فوق رأسه علته مكتوبة : هذا هو يسوع ملك اليهود '),
(26269, 'Matthew', 40, 27, 38, ' حينئذ صلب معه لصان ، واحد عن اليمين وواحد عن اليسار '),
(26270, 'Matthew', 40, 27, 39, ' وكان المجتازون يجدفون عليه وهم يهزون رؤوسهم '),
(26271, 'Matthew', 40, 27, 40, ' قائلين : يا ناقض الهيكل وبانيه في ثلاثة أيام ، خلص نفسك إن كنت ابن الله فانزل عن الصليب '),
(26272, 'Matthew', 40, 27, 41, ' وكذلك رؤساء الكهنة أيضا وهم يستهزئون مع الكتبة والشيوخ قالوا '),
(26273, 'Matthew', 40, 27, 42, ' خلص آخرين وأما نفسه فما يقدر أن يخلصها إن كان هو ملك إسرائيل فلينزل الآن عن الصليب فنؤمن به '),
(26274, 'Matthew', 40, 27, 43, ' قد اتكل على الله ، فلينقذه الآن إن أراده لأنه قال : أنا ابن الله '),
(26275, 'Matthew', 40, 27, 44, ' وبذلك أيضا كان اللصان اللذان صلبا معه يعيرانه '),
(26276, 'Matthew', 40, 27, 45, ' ومن الساعة السادسة كانت ظلمة على كل الأرض إلى الساعة التاسعة '),
(26277, 'Matthew', 40, 27, 46, ' ونحو الساعة التاسعة صرخ يسوع بصوت عظيم قائلا : إيلي ، إيلي ، لما شبقتني ؟ أي : إلهي ، إلهي ، لماذا تركتني '),
(26278, 'Matthew', 40, 27, 47, ' فقوم من الواقفين هناك لما سمعوا قالوا : إنه ينادي إيليا '),
(26279, 'Matthew', 40, 27, 48, ' وللوقت ركض واحد منهم وأخذ إسفنجة وملأها خلا وجعلها على قصبة وسقاه '),
(26280, 'Matthew', 40, 27, 49, ' وأما الباقون فقالوا : اترك . لنرى هل يأتي إيليا يخلصه '),
(26281, 'Matthew', 40, 27, 50, ' فصرخ يسوع أيضا بصوت عظيم ، وأسلم الروح '),
(26282, 'Matthew', 40, 27, 51, ' وإذا حجاب الهيكل قد انشق إلى اثنين ، من فوق إلى أسفل . والأرض تزلزلت ، والصخور تشققت '),
(26283, 'Matthew', 40, 27, 52, ' والقبور تفتحت ، وقام كثير من أجساد القديسين الراقدين '),
(26284, 'Matthew', 40, 27, 53, ' وخرجوا من القبور بعد قيامته ، ودخلوا المدينة المقدسة ، وظهروا لكثيرين '),
(26285, 'Matthew', 40, 27, 54, ' وأما قائد المئة والذين معه يحرسون يسوع فلما رأوا الزلزلة وما كان ، خافوا جدا وقالوا : حقا كان هذا ابن الله '),
(26286, 'Matthew', 40, 27, 55, ' وكانت هناك نساء كثيرات ينظرن من بعيد ، وهن كن قد تبعن يسوع من الجليل يخدمنه '),
(26287, 'Matthew', 40, 27, 56, ' وبينهن مريم المجدلية ، ومريم أم يعقوب ويوسي ، وأم ابني زبدي '),
(26288, 'Matthew', 40, 27, 57, ' ولما كان المساء ، جاء رجل غني من الرامة اسمه يوسف ، وكان هو أيضا تلميذا ليسوع '),
(26289, 'Matthew', 40, 27, 58, ' فهذا تقدم إلى بيلاطس وطلب جسد يسوع . فأمر بيلاطس حينئذ أن يعطى الجسد '),
(26290, 'Matthew', 40, 27, 59, ' فأخذ يوسف الجسد ولفه بكتان نقي '),
(26291, 'Matthew', 40, 27, 60, ' ووضعه في قبره الجديد الذي كان قد نحته في الصخرة ، ثم دحرج حجرا كبيرا على باب القبر ومضى '),
(26292, 'Matthew', 40, 27, 61, ' وكانت هناك مريم المجدلية ومريم الأخرى جالستين تجاه القبر '),
(26293, 'Matthew', 40, 27, 62, ' وفي الغد الذي بعد الاستعداد اجتمع رؤساء الكهنة والفريسيون إلى بيلاطس '),
(26294, 'Matthew', 40, 27, 63, ' قائلين : يا سيد ، قد تذكرنا أن ذلك المضل قال وهو حي : إني بعد ثلاثة أيام أقوم '),
(26295, 'Matthew', 40, 27, 64, ' فمر بضبط القبر إلى اليوم الثالث ، لئلا يأتي تلاميذه ليلا ويسرقوه ، ويقولوا للشعب : إنه قام من الأموات ، فتكون الضلالة الأخيرة أشر من الأولى '),
(26296, 'Matthew', 40, 27, 65, ' فقال لهم بيلاطس : عندكم حراس . اذهبوا واضبطوه كما تعلمون '),
(26297, 'Matthew', 40, 27, 66, ' فمضوا وضبطوا القبر بالحراس وختموا الحجر '),
(26298, 'Matthew', 40, 28, 1, ' وبعد السبت ، عند فجر أول الأسبوع ، جاءت مريم المجدلية ومريم الأخرى لتنظرا القبر '),
(26299, 'Matthew', 40, 28, 2, ' وإذا زلزلة عظيمة حدثت ، لأن ملاك الرب نزل من السماء وجاء ودحرج الحجر عن الباب ، وجلس عليه '),
(26300, 'Matthew', 40, 28, 3, ' وكان منظره كالبرق ، ولباسه أبيض كالثلج '),
(26301, 'Matthew', 40, 28, 4, ' فمن خوفه ارتعد الحراس وصاروا كأموات '),
(26302, 'Matthew', 40, 28, 5, ' فأجاب الملاك وقال للمرأتين : لا تخافا أنتما ، فإني أعلم أنكما تطلبان يسوع المصلوب '),
(26303, 'Matthew', 40, 28, 6, ' ليس هو ههنا ، لأنه قام كما قال هلما انظرا الموضع الذي كان الرب مضطجعا فيه '),
(26304, 'Matthew', 40, 28, 7, ' واذهبا سريعا قولا لتلاميذه : إنه قد قام من الأموات . ها هو يسبقكم إلى الجليل . هناك ترونه . ها أنا قد قلت لكما '),
(26305, 'Matthew', 40, 28, 8, ' فخرجتا سريعا من القبر بخوف وفرح عظيم ، راكضتين لتخبرا تلاميذه '),
(26306, 'Matthew', 40, 28, 9, ' وفيما هما منطلقتان لتخبرا تلاميذه إذا يسوع لاقاهما وقال : سلام لكما . فتقدمتا وأمسكتا بقدميه وسجدتا له '),
(26307, 'Matthew', 40, 28, 10, ' فقال لهما يسوع : لا تخافا . اذهبا قولا لإخوتي أن يذهبوا إلى الجليل ، وهناك يرونني '),
(26308, 'Matthew', 40, 28, 11, ' وفيما هما ذاهبتان إذا قوم من الحراس جاءوا إلى المدينة وأخبروا رؤساء الكهنة بكل ما كان '),
(26309, 'Matthew', 40, 28, 12, ' فاجتمعوا مع الشيوخ ، وتشاوروا ، وأعطوا العسكر فضة كثيرة '),
(26310, 'Matthew', 40, 28, 13, ' قائلين : قولوا إن تلاميذه أتوا ليلا وسرقوه ونحن نيام '),
(26311, 'Matthew', 40, 28, 14, ' وإذا سمع ذلك عند الوالي فنحن نستعطفه ، ونجعلكم مطمئنين '),
(26312, 'Matthew', 40, 28, 15, ' فأخذوا الفضة وفعلوا كما علموهم ، فشاع هذا القول عند اليهود إلى هذا اليوم '),
(26313, 'Matthew', 40, 28, 16, ' وأما الأحد عشر تلميذا فانطلقوا إلى الجليل إلى الجبل ، حيث أمرهم يسوع '),
(26314, 'Matthew', 40, 28, 17, ' ولما رأوه سجدوا له ، ولكن بعضهم شكوا '),
(26315, 'Matthew', 40, 28, 18, ' فتقدم يسوع وكلمهم قائلا : دفع إلي كل سلطان في السماء وعلى الأرض '),
(26316, 'Matthew', 40, 28, 19, ' فاذهبوا وتلمذوا جميع الأمم وعمدوهم باسم الآب والابن والروح القدس '),
(26317, 'Matthew', 40, 28, 20, ' وعلموهم أن يحفظوا جميع ما أوصيتكم به . وها أنا معكم كل الأيام إلى انقضاء الدهر . آمين '),
(26318, 'Micah', 33, 2, 2, ' فإنهم يشتهون الحقول ويغتصبونها ، والبيوت ويأخذونها ، ويظلمون الرجل وبيته والإنسان وميراثه '),
(26319, 'Micah', 33, 2, 3, ' لذلك هكذا قال الرب : هأنذا أفتكر على هذه العشيرة بشر لا تزيلون منه أعناقكم ، ولا تسلكون بالتشامخ لأنه زمان رديء '),
(26320, 'Micah', 33, 2, 4, ' في ذلك اليوم ينطق عليكم بهجو ويرثى بمرثاة ، ويقال : خربنا خرابا . بدل نصيب شعبي . كيف ينزعه عني ؟ يقسم للمرتد حقولنا '),
(26321, 'Micah', 33, 2, 5, ' لذلك لا يكون لك من يلقي حبلا في نصيب بين جماعة الرب '),
(26322, 'Micah', 33, 2, 6, ' يتنبأون قائلين : لا تتنبأوا . لا يتنبأون عن هذه الأمور . لا يزول العار '),
(26323, 'Micah', 33, 2, 7, ' أيها المسمى بيت يعقوب ، هل قصرت روح الرب ؟ أهذه أفعاله ؟ أليست أقوالي صالحة نحو من يسلك بالاستقامة '),
(26324, 'Micah', 33, 2, 8, ' ولكن بالأمس قام شعبي كعدو . تنزعون الرداء عن الثوب من المجتازين بالطمأنينة ، ومن الراجعين من القتال '),
(26325, 'Micah', 33, 2, 9, ' تطردون نساء شعبي من بيت تنعمهن . تأخذون عن أطفالهن زينتي إلى الأبد '),
(26326, 'Micah', 33, 2, 10, ' قوموا واذهبوا ، لأنه ليست هذه هي الراحة . من أجل نجاسة تهلك والهلاك شديد '),
(26327, 'Micah', 33, 2, 11, ' لو كان أحد وهو سالك بالريح والكذب يكذب قائلا : أتنبأ لك عن الخمر والمسكر لكان هو نبي هذا الشعب '),
(26328, 'Micah', 33, 2, 12, ' إني أجمع جميعك يا يعقوب . أضم بقية إسرائيل . أضعهم معا كغنم الحظيرة ، كقطيع في وسط مرعاه يضج من الناس '),
(26329, 'Micah', 33, 2, 13, ' قد صعد الفاتك أمامهم . يقتحمون ويعبرون من الباب ، ويخرجون منه ، ويجتاز ملكهم أمامهم ، والرب في رأسهم '),
(26330, 'Micah', 33, 3, 1, ' وقلت : اسمعوا يا رؤساء يعقوب ، وقضاة بيت إسرائيل . أليس لكم أن تعرفوا الحق '),
(26331, 'Micah', 33, 3, 2, ' المبغضين الخير والمحبين الشر ، النازعين جلودهم عنهم ، ولحمهم عن عظامهم '),
(26332, 'Micah', 33, 3, 3, ' والذين يأكلون لحم شعبي ، ويكشطون جلدهم عنهم ، ويهشمون عظامهم ، ويشققون كما في القدر ، وكاللحم في وسط المقلى '),
(26333, 'Micah', 33, 3, 4, ' حينئذ يصرخون إلى الرب فلا يجيبهم ، بل يستر وجهه عنهم في ذلك الوقت كما أساءوا أعمالهم '),
(26334, 'Micah', 33, 3, 5, ' هكذا قال الرب على الأنبياء الذين يضلون شعبي ، الذين ينهشون بأسنانهم ، وينادون : سلام والذي لا يجعل في أفواههم شيئا ، يفتحون عليه حربا '),
(26335, 'Micah', 33, 3, 6, ' لذلك تكون لكم ليلة بلا رؤيا . ظلام لكم بدون عرافة . وتغيب الشمس عن الأنبياء ، ويظلم عليهم النهار '),
(26336, 'Micah', 33, 3, 7, ' فيخزى الراؤون ، ويخجل العرافون ، ويغطون كلهم شواربهم ، لأنه ليس جواب من الله '),
(26337, 'Micah', 33, 3, 8, ' لكنني أنا ملآن قوة روح الرب وحقا وبأسا ، لأخبر يعقوب بذنبه وإسرائيل بخطيته '),
(26338, 'Micah', 33, 3, 9, ' اسمعوا هذا يا رؤساء بيت يعقوب وقضاة بيت إسرائيل ، الذين يكرهون الحق ويعوجون كل مستقيم '),
(26339, 'Micah', 33, 3, 10, ' الذين يبنون صهيون بالدماء ، وأورشليم بالظلم '),
(26340, 'Micah', 33, 3, 11, ' رؤساؤها يقضون بالرشوة ، وكهنتها يعلمون بالأجرة ، وأنبياؤها يعرفون بالفضة ، وهم يتوكلون على الرب قائلين : أليس الرب في وسطنا ؟ لا يأتي علينا شر '),
(26341, 'Micah', 33, 3, 12, ' لذلك بسببكم تفلح صهيون كحقل ، وتصير أورشليم خربا ، وجبل البيت شوامخ وعر '),
(26342, 'Micah', 33, 4, 1, ' ويكون في آخر الأيام أن جبل بيت الرب يكون ثابتا في رأس الجبال ، ويرتفع فوق التلال ، وتجري إليه شعوب '),
(26343, 'Micah', 33, 4, 2, ' وتسير أمم كثيرة ويقولون : هلم نصعد إلى جبل الرب ، وإلى بيت إله يعقوب ، فيعلمنا من طرقه ، ونسلك في سبله . لأنه من صهيون تخرج الشريعة ، ومن أورشليم كلمة الرب '),
(26344, 'Micah', 33, 4, 3, ' فيقضي بين شعوب كثيرين . ينصف لأمم قوية بعيدة ، فيطبعون سيوفهم سككا ، ورماحهم مناجل . لا ترفع أمة على أمة سيفا ، ولا يتعلمون الحرب في ما بعد '),
(26345, 'Micah', 33, 4, 4, ' بل يجلسون كل واحد تحت كرمته وتحت تينته ، ولا يكون من يرعب ، لأن فم رب الجنود تكلم '),
(26346, 'Micah', 33, 4, 5, ' لأن جميع الشعوب يسلكون كل واحد باسم إلهه ، ونحن نسلك باسم الرب إلهنا إلى الدهر والأبد '),
(26347, 'Micah', 33, 4, 6, ' في ذلك اليوم ، يقول الرب ، أجمع الظالعة ، وأضم المطرودة ، والتي أضررت بها '),
(26348, 'Micah', 33, 4, 7, ' وأجعل الظالعة بقية ، والمقصاة أمة قوية ، ويملك الرب عليهم في جبل صهيون من الآن إلى الأبد '),
(26349, 'Micah', 33, 4, 8, ' وأنت يا برج القطيع ، أكمة بنت صهيون إليك يأتي . ويجيء الحكم الأول ملك بنت أورشليم '),
(26350, 'Micah', 33, 4, 9, ' الآن لماذا تصرخين صراخا ؟ أليس فيك ملك ، أم هلك مشيرك حتى أخذك وجع كالوالدة '),
(26351, 'Micah', 33, 4, 10, ' تلوي ، ادفعي يا بنت صهيون كالوالدة ، لأنك الآن تخرجين من المدينة ، وتسكنين في البرية ، وتأتين إلى بابل . هناك تنقذين . هناك يفديك الرب من يد أعدائك '),
(26352, 'Micah', 33, 4, 11, ' والآن قد اجتمعت عليك أمم كثيرة ، الذين يقولون : لتتدنس ولتتفرس عيوننا في صهيون '),
(26353, 'Micah', 33, 4, 12, ' وهم لا يعرفون أفكار الرب ولا يفهمون قصده ، إنه قد جمعهم كحزم إلى البيدر '),
(26354, 'Micah', 33, 4, 13, ' قومي ودوسي يا بنت صهيون ، لأني أجعل قرنك حديدا ، وأظلافك أجعلها نحاسا ، فتسحقين شعوبا كثيرين ، وأحرم غنيمتهم للرب ، وثروتهم لسيد كل الأرض '),
(26355, 'Micah', 33, 5, 1, ' الآن تتجيشين يا بنت الجيوش . قد أقام علينا مترسة . يضربون قاضي إسرائيل بقضيب على خده '),
(26356, 'Micah', 33, 5, 2, ' أما أنت يا بيت لحم أفراتة ، وأنت صغيرة أن تكوني بين ألوف يهوذا ، فمنك يخرج لي الذي يكون متسلطا على إسرائيل ، ومخارجه منذ القديم ، منذ أيام الأزل '),
(26357, 'Micah', 33, 5, 3, ' لذلك يسلمهم إلى حينما تكون قد ولدت والدة ، ثم ترجع بقية إخوته إلى بني إسرائيل '),
(26358, 'Micah', 33, 5, 4, ' ويقف ويرعى بقدرة الرب ، بعظمة اسم الرب إلهه ، ويثبتون . لأنه الآن يتعظم إلى أقاصي الأرض '),
(26359, 'Micah', 33, 5, 5, ' ويكون هذا سلاما . إذا دخل أشور في أرضنا ، وإذا داس في قصورنا ، نقيم عليه سبعة رعاة وثمانية من أمراء الناس '),
(26360, 'Micah', 33, 5, 6, ' فيرعون أرض أشور بالسيف ، وأرض نمرود في أبوابها ، فينفذ من أشور إذا دخل أرضنا وإذا داس تخومنا '),
(26361, 'Micah', 33, 5, 7, ' وتكون بقية يعقوب في وسط شعوب كثيرين كالندى من عند الرب ، كالوابل على العشب الذي لا ينتظر إنسانا ولا يصبر لبني البشر '),
(26362, 'Micah', 33, 5, 8, ' وتكون بقية يعقوب بين الأمم في وسط شعوب كثيرين كالأسد بين وحوش الوعر ، كشبل الأسد بين قطعان الغنم ، الذي إذا عبر يدوس ويفترس وليس من ينقذ '),
(26363, 'Micah', 33, 5, 9, ' لترتفع يدك على مبغضيك وينقرض كل أعدائك '),
(26364, 'Micah', 33, 5, 10, ' ويكون في ذلك اليوم ، يقول الرب ، أني أقطع خيلك من وسطك ، وأبيد مركباتك '),
(26365, 'Micah', 33, 5, 11, ' وأقطع مدن أرضك ، وأهدم كل حصونك '),
(26366, 'Micah', 33, 5, 12, ' وأقطع السحر من يدك ، ولا يكون لك عائفون '),
(26367, 'Micah', 33, 5, 13, ' وأقطع تماثيلك المنحوتة وأنصابك من وسطك ، فلا تسجد لعمل يديك في ما بعد '),
(26368, 'Micah', 33, 5, 14, ' وأقلع سواريك من وسطك وأبيد مدنك '),
(26369, 'Micah', 33, 5, 15, ' وبغضب وغيظ أنتقم من الأمم الذين لم يسمعوا '),
(26370, 'Micah', 33, 6, 1, ' اسمعوا ما قاله الرب : قم خاصم لدى الجبال ولتسمع التلال صوتك '),
(26371, 'Micah', 33, 6, 2, ' اسمعي خصومة الرب أيتها الجبال ، ويا أسس الأرض الدائمة : فإن للرب خصومة مع شعبه وهو يحاكم إسرائيل '),
(26372, 'Micah', 33, 6, 3, ' يا شعبي ، ماذا صنعت بك وبماذا أضجرتك ؟ اشهد علي '),
(26373, 'Micah', 33, 6, 4, ' إني أصعدتك من أرض مصر ، وفككتك من بيت العبودية ، وأرسلت أمامك موسى وهارون ومريم '),
(26374, 'Micah', 33, 6, 5, ' يا شعبي اذكر بماذا تآمر بالاق ملك موآب ، وبماذا أجابه بلعام بن بعور ، من شطيم إلى الجلجال ، لكي تعرف إجادة الرب '),
(26375, 'Micah', 33, 6, 6, ' بم أتقدم إلى الرب وأنحني للإله العلي ؟ هل أتقدم بمحرقات ، بعجول أبناء سنة '),
(26376, 'Micah', 33, 6, 7, ' هل يسر الرب بألوف الكباش ، بربوات أنهار زيت ؟ هل أعطي بكري عن معصيتي ، ثمرة جسدي عن خطية نفسي '),
(26377, 'Micah', 33, 6, 8, ' قد أخبرك أيها الإنسان ما هو صالح ، وماذا يطلبه منك الرب : إلا أن تصنع الحق وتحب الرحمة ، وتسلك متواضعا مع إلهك '),
(26378, 'Micah', 33, 6, 9, ' صوت الرب ينادي للمدينة ، والحكمة ترى اسمك : اسمعوا للقضيب ومن رسمه '),
(26379, 'Micah', 33, 6, 10, ' أفي بيت الشرير بعد كنوز شر وإيفة ناقصة ملعونة '),
(26380, 'Micah', 33, 6, 11, ' هل أتزكى مع موازين الشر ومع كيس معايير الغش '),
(26381, 'Micah', 33, 6, 12, ' فإن أغنياءها ملآنون ظلما ، وسكانها يتكلمون بالكذب ، ولسانهم في فمهم غاش '),
(26382, 'Micah', 33, 6, 13, ' فأنا قد جعلت جروحك عديمة الشفاء ، مخربا من أجل خطاياك '),
(26383, 'Micah', 33, 6, 14, ' أنت تأكل ولا تشبع ، وجوعك في جوفك . وتعزل ولا تنجي ، والذي تنجيه أدفعه إلى السيف '),
(26384, 'Micah', 33, 6, 15, ' أنت تزرع ولا تحصد . أنت تدوس زيتونا ولا تدهن بزيت ، وسلافة ولا تشرب خمرا '),
(26385, 'Micah', 33, 6, 16, ' وتحفظ فرائض : عمري ، وجميع أعمال بيت : أخآب ، وتسلكون بمشوراتهم ، لكي أسلمك للخراب ، وسكانها للصفير ، فتحملون عار شعبي '),
(26386, 'Micah', 33, 7, 1, ' ويل لي لأني صرت كجنى الصيف ، كخصاصة القطاف ، لا عنقود للأكل ولا باكورة تينة اشتهتها نفسي '),
(26387, 'Micah', 33, 7, 2, ' قد باد التقي من الأرض ، وليس مستقيم بين الناس . جميعهم يكمنون للدماء ، يصطادون بعضهم بعضا بشبكة '),
(26388, 'Micah', 33, 7, 3, ' اليدان إلى الشر مجتهدتان . الرئيس طالب والقاضي بالهدية ، والكبير متكلم بهوى نفسه فيعكشونها '),
(26389, 'Micah', 33, 7, 4, ' أحسنهم مثل العوسج ، وأعدلهم من سياج الشوك . يوم مراقبيك عقابك قد جاء . الآن يكون ارتباكهم '),
(26390, 'Micah', 33, 7, 5, ' لا تأتمنوا صاحبا . لا تثقوا بصديق . احفظ أبواب فمك عن المضطجعة في حضنك '),
(26391, 'Micah', 33, 7, 6, ' لأن الابن مستهين بالأب ، والبنت قائمة على أمها ، والكنة على حماتها ، وأعداء الإنسان أهل بيته '),
(26392, 'Micah', 33, 7, 7, ' ولكنني أراقب الرب ، أصبر لإله خلاصي . يسمعني إلهي '),
(26393, 'Micah', 33, 7, 8, ' لا تشمتي بي يا عدوتي ، إذا سقطت أقوم . إذا جلست في الظلمة فالرب نور لي '),
(26394, 'Micah', 33, 7, 9, ' أحتمل غضب الرب لأني أخطأت إليه ، حتى يقيم دعواي ويجري حقي . سيخرجني إلى النور ، سأنظر بره '),
(26395, 'Micah', 33, 7, 10, ' وترى عدوتي فيغطيها الخزي ، القائلة لي : أين هو الرب إلهك ؟  . عيناي ستنظران إليها . الآن تصير للدوس كطين الأزقة '),
(26396, 'Micah', 33, 7, 11, ' يوم بناء حيطانك ، ذلك اليوم يبعد الميعاد '),
(26397, 'Micah', 33, 7, 12, ' هو يوم يأتون إليك من أشور ومدن مصر ، ومن مصر إلى النهر . ومن البحر إلى البحر . ومن الجبل إلى الجبل '),
(26398, 'Micah', 33, 7, 13, ' ولكن تصير الأرض خربة بسبب سكانها ، من أجل ثمر أفعالهم '),
(26399, 'Micah', 33, 7, 14, ' ارع بعصاك شعبك غنم ميراثك ، ساكنة وحدها في وعر في وسط الكرمل . لترع في باشان وجلعاد كأيام القدم '),
(26400, 'Micah', 33, 7, 15, ' كأيام خروجك من أرض مصر أريه عجائب '),
(26401, 'Micah', 33, 7, 16, ' ينظر الأمم ويخجلون من كل بطشهم . يضعون أيديهم على أفواههم ، وتصم آذانهم '),
(26402, 'Micah', 33, 7, 17, ' يلحسون التراب كالحية ، كزواحف الأرض . يخرجون بالرعدة من حصونهم ، يأتون بالرعب إلى الرب إلهنا ويخافون منك '),
(26403, 'Micah', 33, 7, 18, ' من هو إله مثلك غافر الإثم وصافح عن الذنب لبقية ميراثه لا يحفظ إلى الأبد غضبه ، فإنه يسر بالرأفة '),
(26404, 'Micah', 33, 7, 19, ' يعود يرحمنا ، يدوس آثامنا ، وتطرح في أعماق البحر جميع خطاياهم '),
(26405, 'Micah', 33, 7, 20, ' تصنع الأمانة ليعقوب والرأفة لإبراهيم ، اللتين حلفت لآبائنا منذ أيام القدم '),
(26406, 'Micah', 33, 1, 1, ' قول الرب الذي صار إلى ميخا المورشتي في أيام يوثام وآحاز وحزقيا ملوك يهوذا ، الذي رآه على السامرة وأورشليم '),
(26407, 'Micah', 33, 1, 2, ' اسمعوا أيها الشعوب جميعكم . أصغي أيتها الأرض وملؤها . وليكن السيد الرب شاهدا عليكم ، السيد من هيكل قدسه '),
(26408, 'Micah', 33, 1, 3, ' فإنه هوذا الرب يخرج من مكانه وينزل ويمشي على شوامخ الأرض '),
(26409, 'Micah', 33, 1, 4, ' فتذوب الجبال تحته ، وتنشق الوديان كالشمع قدام النار . كالماء المنصب في منحدر '),
(26410, 'Micah', 33, 1, 5, ' كل هذا من أجل إثم يعقوب ، ومن أجل خطية بيت إسرائيل . ما هو ذنب يعقوب ؟ أليس هو السامرة ؟ وما هي مرتفعات يهوذا ؟ أليست هي أورشليم '),
(26411, 'Micah', 33, 1, 6, ' فأجعل السامرة خربة في البرية ، مغارس للكروم ، وألقي حجارتها إلى الوادي ، وأكشف أسسها '),
(26412, 'Micah', 33, 1, 7, ' وجميع تماثيلها المنحوتة تحطم ، وكل أعقارها تحرق بالنار ، وجميع أصنامها أجعلها خرابا ، لأنها من عقر الزانية جمعتها وإلى عقر الزانية تعود '),
(26413, 'Micah', 33, 1, 8, ' من أجل ذلك أنوح وأولول . أمشي حافيا وعريانا . أصنع نحيبا كبنات آوى ، ونوحا كرعال النعام '),
(26414, 'Micah', 33, 1, 9, ' لأن جراحاتها عديمة الشفاء ، لأنها قد أتت إلى يهوذا ، وصلت إلى باب شعبي إلى أورشليم '),
(26415, 'Micah', 33, 1, 10, ' لا تخبروا في جت ، لا تبكوا في عكاء . تمرغي في التراب في بيت عفرة '),
(26416, 'Micah', 33, 1, 11, ' اعبري يا ساكنة شافير عريانة وخجلة . الساكنة في صانان لا تخرج . نوح بيت هأيصل يأخذ عندكم مقامه '),
(26417, 'Micah', 33, 1, 12, ' لأن الساكنة في ماروث اغتمت لأجل خيراتها ، لأن شرا قد نزل من عند الرب إلى باب أورشليم '),
(26418, 'Micah', 33, 1, 13, ' شدي المركبة بالجواد يا ساكنة لاخيش ، هي أول خطية لابنة صهيون ، لأنه فيك وجدت ذنوب إسرائيل '),
(26419, 'Micah', 33, 1, 14, ' لذلك تعطين إطلاقا لمورشة جت . تصير بيوت أكزيب كاذبة لملوك إسرائيل '),
(26420, 'Micah', 33, 1, 15, ' آتي إليك أيضا بالوارث يا ساكنة مريشة . يأتي إلى عدلام مجد إسرائيل '),
(26421, 'Micah', 33, 1, 16, ' كوني قرعاء وجزي من أجل بني تنعمك . وسعي قرعتك كالنسر ، لأنهم قد انتفوا عنك '),
(26422, 'Micah', 33, 2, 1, ' ويل للمفتكرين بالبطل ، والصانعين الشر على مضاجعهم في نور الصباح يفعلونه لأنه في قدرة يدهم '),
(26423, 'Nahum', 34, 1, 1, ' وحي على نينوى . سفر رؤيا ناحوم الألقوشي '),
(26424, 'Nahum', 34, 1, 2, ' الرب إله غيور ومنتقم . الرب منتقم وذو سخط . الرب منتقم من مبغضيه وحافظ غضبه على أعدائه '),
(26425, 'Nahum', 34, 1, 3, ' الرب بطيء الغضب وعظيم القدرة ، ولكنه لا يبرئ البتة . الرب في الزوبعة ، وفي العاصف طريقه ، والسحاب غبار رجليه '),
(26426, 'Nahum', 34, 1, 4, ' ينتهر البحر فينشفه ويجفف جميع الأنهار . يذبل باشان والكرمل ، وزهر لبنان يذبل '),
(26427, 'Nahum', 34, 1, 5, ' الجبال ترجف منه ، والتلال تذوب ، والأرض ترفع من وجهه ، والعالم وكل الساكنين فيه '),
(26428, 'Nahum', 34, 1, 6, ' من يقف أمام سخطه ؟ ومن يقوم في حمو غضبه ؟ غيظه ينسكب كالنار ، والصخور تنهدم منه '),
(26429, 'Nahum', 34, 1, 7, ' صالح هو الرب . حصن في يوم الضيق ، وهو يعرف المتوكلين عليه '),
(26430, 'Nahum', 34, 1, 8, ' ولكن بطوفان عابر يصنع هلاكا تاما لموضعها ، وأعداؤه يتبعهم ظلام '),
(26431, 'Nahum', 34, 1, 9, ' ماذا تفتكرون على الرب ؟ هو صانع هلاكا تاما . لا يقوم الضيق مرتين '),
(26432, 'Nahum', 34, 1, 10, ' فإنهم وهم مشتبكون مثل الشوك ، وسكرانون كمن خمرهم ، يؤكلون كالقش اليابس بالكمال '),
(26433, 'Nahum', 34, 1, 11, ' منك خرج المفتكر على الرب شرا ، المشير بالهلاك '),
(26434, 'Nahum', 34, 1, 12, ' هكذا قال الرب : إن كانوا سالمين وكثيرين هكذا ، فهكذا يجزون فيعبر . أذللتك . لا أذلك ثانية '),
(26435, 'Nahum', 34, 1, 13, ' والآن أكسر نيره عنك وأقطع ربطك '),
(26436, 'Nahum', 34, 1, 14, ' ولكن قد أوصى عنك الرب : لا يزرع من اسمك في ما بعد . إني أقطع من بيت إلهك التماثيل المنحوتة والمسبوكة . أجعله قبرك ، لأنك صرت حقيرا '),
(26437, 'Nahum', 34, 1, 15, ' هوذا على الجبال قدما مبشر مناد بالسلام عيدي يا يهوذا أعيادك . أوفي نذورك ، فإنه لا يعود يعبر فيك أيضا المهلك . قد انقرض كله '),
(26438, 'Nahum', 34, 2, 1, ' قد ارتفعت المقمعة على وجهك . احرس الحصن . راقب الطريق . شدد الحقوين . مكن القوة جدا '),
(26439, 'Nahum', 34, 2, 2, ' فإن الرب يرد عظمة يعقوب كعظمة إسرائيل ، لأن السالبين قد سلبوهم وأتلفوا قضبان كرومهم '),
(26440, 'Nahum', 34, 2, 3, ' ترس أبطاله محمر . رجال الجيش قرمزيون . المركبات بنار الفولاذ في يوم إعداده . والسرو يهتز '),
(26441, 'Nahum', 34, 2, 4, ' تهيج المركبات في الأزقة . تتراكض في الساحات . منظرها كمصابيح . تجري كالبروق '),
(26442, 'Nahum', 34, 2, 5, ' يذكر عظماءه . يتعثرون في مشيهم . يسرعون إلى سورها ، وقد أقيمت المترسة '),
(26443, 'Nahum', 34, 2, 6, ' أبواب الأنهار انفتحت ، والقصر قد ذاب '),
(26444, 'Nahum', 34, 2, 7, ' وهصب قد انكشفت . أطلعت . وجواريها تئن كصوت الحمام ضاربات على صدورهن '),
(26445, 'Nahum', 34, 2, 8, ' ونينوى كبركة ماء منذ كانت ، ولكنهم الآن هاربون . قفوا ، قفوا ولا ملتفت '),
(26446, 'Nahum', 34, 2, 9, ' انهبوا فضة . انهبوا ذهبا ، فلا نهاية للتحف للكثرة من كل متاع شهي '),
(26447, 'Nahum', 34, 2, 10, ' فراغ وخلاء وخراب ، وقلب ذائب وارتخاء ركب ووجع في كل حقو . وأوجه جميعهم تجمع حمرة '),
(26448, 'Nahum', 34, 2, 11, ' أين مأوى الأسود ومرعى أشبال الأسود ؟ حيث يمشي الأسد واللبوة وشبل الأسد ، وليس من يخوف '),
(26449, 'Nahum', 34, 2, 12, ' الأسد المفترس لحاجة جرائه ، والخانق لأجل لبواته حتى ملأ مغاراته فرائس ومآويه مفترسات '),
(26450, 'Nahum', 34, 2, 13, ' ها أنا عليك ، يقول رب الجنود . فأحرق مركباتك دخانا ، وأشبالك يأكلها السيف ، وأقطع من الأرض فرائسك ، ولا يسمع أيضا صوت رسلك '),
(26451, 'Nahum', 34, 3, 1, ' ويل لمدينة الدماء . كلها ملآنة كذبا وخطفا . لا يزول الافتراس '),
(26452, 'Nahum', 34, 3, 2, ' صوت السوط وصوت رعشة البكر ، وخيل تخب ومركبات تقفز '),
(26453, 'Nahum', 34, 3, 3, ' وفرسان تنهض ، ولهيب السيف وبريق الرمح ، وكثرة جرحى ، ووفرة قتلى ، ولا نهاية للجثث . يعثرون بجثثهم '),
(26454, 'Nahum', 34, 3, 4, ' من أجل زنى الزانية الحسنة الجمال صاحبة السحر البائعة أمما بزناها ، وقبائل بسحرها '),
(26455, 'Nahum', 34, 3, 5, ' هأنذا عليك ، يقول رب الجنود ، فأكشف أذيالك إلى فوق وجهك ، وأري الأمم عورتك والممالك خزيك '),
(26456, 'Nahum', 34, 3, 6, ' وأطرح عليك أوساخا ، وأهينك وأجعلك عبرة '),
(26457, 'Nahum', 34, 3, 7, ' ويكون كل من يراك يهرب منك ويقول : خربت نينوى ، من يرثي لها ؟ من أين أطلب لك معزين '),
(26458, 'Nahum', 34, 3, 8, ' هل أنت أفضل من نو أمون الجالسة بين الأنهار ، حولها المياه التي هي حصن البحر ، ومن البحر سورها '),
(26459, 'Nahum', 34, 3, 9, ' كوش قوتها مع مصر وليست نهاية . فوط ولوبيم كانوا معونتك '),
(26460, 'Nahum', 34, 3, 10, ' هي أيضا قد مضت إلى المنفى بالسبي ، وأطفالها حطمت في رأس جميع الأزقة ، وعلى أشرافها ألقوا قرعة ، وجميع عظمائها تقيدوا بالقيود '),
(26461, 'Nahum', 34, 3, 11, ' أنت أيضا تسكرين . تكونين خافية . أنت أيضا تطلبين حصنا بسبب العدو '),
(26462, 'Nahum', 34, 3, 12, ' جميع قلاعك أشجار تين بالبواكير ، إذا انهزت تسقط في فم الآكل '),
(26463, 'Nahum', 34, 3, 13, ' هوذا شعبك نساء في وسطك تنفتح لأعدائك أبواب أرضك . تأكل النار مغاليقك '),
(26464, 'Nahum', 34, 3, 14, ' استقي لنفسك ماء للحصار . أصلحي قلاعك . ادخلي في الطين ودوسي في الملاط . أصلحي الملبن '),
(26465, 'Nahum', 34, 3, 15, ' هناك تأكلك نار ، يقطعك سيف ، يأكلك كالغوغاء ، تكاثري كالغوغاء . تعاظمي كالجراد '),
(26466, 'Nahum', 34, 3, 16, ' أكثرت تجارك أكثر من نجوم السماء . الغوغاء جنحت وطارت '),
(26467, 'Nahum', 34, 3, 17, ' رؤساؤك كالجراد ، وولاتك كحرجلة الجراد الحالة على الجدران في يوم البرد . تشرق الشمس فتطير ولا يعرف مكانها أين هو '),
(26468, 'Nahum', 34, 3, 18, ' نعست رعاتك يا ملك أشور . اضطجعت عظماؤك . تشتت شعبك على الجبال ولا من يجمع '),
(26469, 'Nahum', 34, 3, 19, ' ليس جبر لانكسارك . جرحك عديم الشفاء . كل الذين يسمعون خبرك يصفقون بأيديهم عليك ، لأنه على من لم يمر شرك على الدوام '),
(26470, 'Nehemiah', 16, 11, 27, ' وفي حصر شوعال وبئر سبع وقراها '),
(26471, 'Nehemiah', 16, 11, 28, ' وفي صقلغ ومكونة وقراها '),
(26472, 'Nehemiah', 16, 11, 29, ' وفي عين رمون وصرعة ويرموث '),
(26473, 'Nehemiah', 16, 11, 30, ' وزانوح وعدلام وضياعهما ، ولخيش وحقولها ، وعزيقة وقراها ، وحلوا من بئر سبع إلى وادي هنوم '),
(26474, 'Nehemiah', 16, 11, 31, ' وبنو بنيامين سكنوا من جبع إلى مخماس وعيا وبيت إيل وقراها '),
(26475, 'Nehemiah', 16, 11, 32, ' وعناثوث ونوب وعننية '),
(26476, 'Nehemiah', 16, 11, 33, ' وحاصور ورامة وجتايم '),
(26477, 'Nehemiah', 16, 11, 34, ' وحاديد وصبوعيم ونبلاط '),
(26478, 'Nehemiah', 16, 11, 35, ' ولود وأونو وادي الصناع '),
(26479, 'Nehemiah', 16, 11, 36, ' وكان من اللاويين فرق في يهوذا وفي بنيامين '),
(26480, 'Nehemiah', 16, 12, 1, ' وهؤلاء هم الكهنة واللاويون الذين صعدوا مع زربابل بن شألتئيل ويشوع : سرايا ويرميا وعزرا '),
(26481, 'Nehemiah', 16, 12, 2, ' وأمريا وملوخ وحطوش '),
(26482, 'Nehemiah', 16, 12, 3, ' وشكنيا ورحوم ومريموث '),
(26483, 'Nehemiah', 16, 12, 4, ' وعدو وجنتوي وأبيا '),
(26484, 'Nehemiah', 16, 12, 5, ' وميامين ومعديا وبلجة '),
(26485, 'Nehemiah', 16, 12, 6, ' وشمعيا ويوياريب ويدعيا '),
(26486, 'Nehemiah', 16, 12, 7, ' وسلو وعاموق وحلقيا ويدعيا . هؤلاء هم رؤوس الكهنة وإخوتهم في أيام يشوع '),
(26487, 'Nehemiah', 16, 12, 8, ' واللاويون : يشوع وبنوي وقدميئيل وشربيا ويهوذا ومتنيا الذي على التحميد هو وإخوته '),
(26488, 'Nehemiah', 16, 12, 9, ' وبقبقيا وعني أخواهم مقابلهم في الحراسات '),
(26489, 'Nehemiah', 16, 12, 10, ' ويشوع ولد يوياقيم ، ويوياقيم ولد ألياشيب ، وألياشيب ولد يوياداع '),
(26490, 'Nehemiah', 16, 12, 11, ' ويوياداع ولد يوناثان ، ويوناثان ولد يدوع '),
(26491, 'Nehemiah', 16, 12, 12, ' وفي أيام يوياقيم كان الكهنة رؤوس الآباء : لسرايا مرايا ، وليرميا حننيا '),
(26492, 'Nehemiah', 16, 12, 13, ' ولعزرا مشلام ، ولأمريا يهوحانان '),
(26493, 'Nehemiah', 16, 12, 14, ' ولمليكو يوناثان ، ولشبنيا يوسف '),
(26494, 'Nehemiah', 16, 12, 15, ' ولحريم عدنا ، ولمرايوث حلقاي '),
(26495, 'Nehemiah', 16, 12, 16, ' ولعدو زكريا ولجنثون مشلام '),
(26496, 'Nehemiah', 16, 12, 17, ' ولأبيا زكري ، ولمنيامين لموعديا ، فلطاي '),
(26497, 'Nehemiah', 16, 12, 18, ' ولبلجة شموع ، ولشمعيا يهوناثان '),
(26498, 'Nehemiah', 16, 12, 19, ' وليوياريب متناي ، وليدعيا عزي '),
(26499, 'Nehemiah', 16, 12, 20, ' ولسلاي قلاي ، ولعاموق عابر '),
(26500, 'Nehemiah', 16, 12, 21, ' ولحلقيا حشبيا ، وليدعيا نثنئيل '),
(26501, 'Nehemiah', 16, 12, 22, ' وكان اللاويون في أيام ألياشيب ويوياداع ويوحانان ويدوع مكتوبين رؤوس آباء ، والكهنة أيضا في ملك داريوس الفارسي '),
(26502, 'Nehemiah', 16, 12, 23, ' وكان بنو لاوي رؤوس الآباء مكتوبين في سفر أخبار الأيام إلى أيام يوحانان بن ألياشيب '),
(26503, 'Nehemiah', 16, 12, 24, ' ورؤوس اللاويين : حشبيا وشربيا ويشوع بن قدميئيل وإخوتهم مقابلهم للتسبيح والتحميد ، حسب وصية داود رجل الله ، نوبة مقابل نوبة '),
(26504, 'Nehemiah', 16, 12, 25, ' وكان متنيا وبقبقيا وعوبديا ومشلام وطلمون وعقوب بوابين حارسين الحراسة عند مخازن الأبواب '),
(26505, 'Nehemiah', 16, 12, 26, ' كان هؤلاء في أيام يوياقيم بن يشوع بن يوصاداق ، وفي أيام نحميا الوالي ، وعزرا الكاهن الكاتب '),
(26506, 'Nehemiah', 16, 12, 27, ' وعند تدشين سور أورشليم طلبوا اللاويين من جميع أماكنهم ليأتوا بهم إلى أورشليم ، لكي يدشنوا بفرح وبحمد وغناء بالصنوج والرباب والعيدان '),
(26507, 'Nehemiah', 16, 12, 28, ' فاجتمع بنو المغنين من الدائرة حول أورشليم ، ومن ضياع النطوفاتي '),
(26508, 'Nehemiah', 16, 12, 29, ' ومن بيت الجلجال ، ومن حقول جبع وعزموت ، لأن المغنين بنوا لأنفسهم ضياعا حول أورشليم '),
(26509, 'Nehemiah', 16, 12, 30, ' وتطهر الكهنة واللاويون ، وطهروا الشعب والأبواب والسور '),
(26510, 'Nehemiah', 16, 12, 31, ' وأصعدت رؤساء يهوذا على السور . وأقمت فرقتين عظيمتين من الحمادين ، ووكبت الواحدة يمينا على السور نحو باب الدمن '),
(26511, 'Nehemiah', 16, 12, 32, ' وسار وراءهم هوشعيا ونصف رؤساء يهوذا '),
(26512, 'Nehemiah', 16, 12, 33, ' وعزريا وعزرا ومشلام '),
(26513, 'Nehemiah', 16, 12, 34, ' ويهوذا وبنيامين وشمعيا ويرميا '),
(26514, 'Nehemiah', 16, 12, 35, ' ومن بني الكهنة بالأبواق : زكريا بن يوناثان بن شمعيا بن متنيا بن ميخايا بن زكور بن آساف '),
(26515, 'Nehemiah', 16, 12, 36, ' وإخوته شمعيا وعزرئيل ومللاي وجللاي وماعاي ونثنئيل ويهوذا وحناني بآلات غناء داود رجل الله ، وعزرا الكاتب أمامهم ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(26516, 'Nehemiah', 16, 12, 37, ' وعند باب العين الذي مقابلهم صعدوا على درج مدينة داود عند مصعد السور ، فوق بيت داود ، إلى باب الماء شرقا '),
(26517, 'Nehemiah', 16, 12, 38, ' والفرقة الثانية من الحمادين وكبت مقابلهم ، وأنا وراءها ، ونصف الشعب على السور من عند برج التنانير إلى السور العريض '),
(26518, 'Nehemiah', 16, 12, 39, ' ومن فوق باب أفرايم وفوق الباب العتيق وفوق باب السمك وبرج حننئيل وبرج المئة إلى باب الضأن ، ووقفوا في باب السجن '),
(26519, 'Nehemiah', 16, 12, 40, ' فوقف الفرقتان من الحمادين في بيت الله ، وأنا ونصف الولاة معي '),
(26520, 'Nehemiah', 16, 12, 41, ' والكهنة : ألياقيم ومعسيا ومنيامين وميخايا وأليوعيناي وزكريا وحننيا بالأبواق '),
(26521, 'Nehemiah', 16, 12, 42, ' ومعسيا وشمعيا وألعازار وعزي ويهوحانان وملكيا وعيلام وعازر ، وغنى المغنون ويزرحيا الوكيل '),
(26522, 'Nehemiah', 16, 12, 43, ' وذبحوا في ذلك اليوم ذبائح عظيمة وفرحوا ، لأن الله أفرحهم فرحا عظيما . وفرح الأولاد والنساء أيضا ، وسمع فرح أورشليم عن بعد '),
(26523, 'Nehemiah', 16, 12, 44, ' وتوكل في ذلك اليوم أناس على المخادع للخزائن والرفائع والأوائل والأعشار ، ليجمعوا فيها من حقول المدن أنصبة الشريعة للكهنة واللاويين ، لأن يهوذا فرح بالكهنة واللاويين الواقفين '),
(26524, 'Nehemiah', 16, 12, 45, ' حارسين حراسة إلههم وحراسة التطهير . وكان المغنون والبوابون حسب وصية داود وسليمان ابنه '),
(26525, 'Nehemiah', 16, 12, 46, ' لأنه في أيام داود وآساف منذ القديم كان رؤوس مغنين وغناء تسبيح وتحميد لله '),
(26526, 'Nehemiah', 16, 12, 47, ' وكان كل إسرائيل في أيام زربابل وأيام نحميا يؤدون أنصبة المغنين والبوابين أمر كل يوم في يومه ، وكانوا يقدسون للاويين ، وكان اللاويون يقدسون لبني هارون '),
(26527, 'Nehemiah', 16, 13, 1, ' في ذلك اليوم قرئ في سفر موسى في آذان الشعب ، ووجد مكتوبا فيه أن عمونيا وموآبيا لا يدخل في جماعة الله إلى الأبد '),
(26528, 'Nehemiah', 16, 1, 1, ' كلام نحميا بن حكليا : حدث في شهر كسلو في السنة العشرين ، بينما كنت في شوشن القصر '),
(26529, 'Nehemiah', 16, 1, 2, ' أنه جاء حناني ، واحد من إخوتي ، هو ورجال من يهوذا ، فسألتهم عن اليهود الذين نجوا ، الذين بقوا من السبي ، وعن أورشليم '),
(26530, 'Nehemiah', 16, 1, 3, ' فقالوا لي : إن الباقين الذين بقوا من السبي هناك في البلاد ، هم في شر عظيم وعار . وسور أورشليم منهدم ، وأبوابها محروقة بالنار '),
(26531, 'Nehemiah', 16, 1, 4, ' فلما سمعت هذا الكلام جلست وبكيت ونحت أياما ، وصمت وصليت أمام إله السماء '),
(26532, 'Nehemiah', 16, 1, 5, ' وقلت : أيها الرب إله السماء ، الإله العظيم المخوف ، الحافظ العهد والرحمة لمحبيه وحافظي وصاياه '),
(26533, 'Nehemiah', 16, 1, 6, ' لتكن أذنك مصغية وعيناك مفتوحتين لتسمع صلاة عبدك الذي يصلي إليك الآن نهارا وليلا لأجل بني إسرائيل عبيدك ، ويعترف بخطايا بني إسرائيل التي أخطأنا بها إليك . فإني أنا وبيت أبي قد أخطأنا '),
(26534, 'Nehemiah', 16, 1, 7, ' لقد أفسدنا أمامك ، ولم نحفظ الوصايا والفرائض والأحكام التي أمرت بها موسى عبدك '),
(26535, 'Nehemiah', 16, 1, 8, ' اذكر الكلام الذي أمرت به موسى عبدك قائلا : إن خنتم فإني أفرقكم في الشعوب '),
(26536, 'Nehemiah', 16, 1, 9, ' وإن رجعتم إلي وحفظتم وصاياي وعملتموها ، إن كان المنفيون منكم في أقصاء السماوات ، فمن هناك أجمعهم وآتي بهم إلى المكان الذي اخترت لإسكان اسمي فيه '),
(26537, 'Nehemiah', 16, 1, 10, ' فهم عبيدك وشعبك الذي افتديت بقوتك العظيمة ويدك الشديدة '),
(26538, 'Nehemiah', 16, 1, 11, ' يا سيد ، لتكن أذنك مصغية إلى صلاة عبدك وصلاة عبيدك الذين يريدون مخافة اسمك . وأعط النجاح اليوم لعبدك وامنحه رحمة أمام هذا الرجل . لأني كنت ساقيا للملك '),
(26539, 'Nehemiah', 16, 2, 1, ' وفي شهر نيسان ، في السنة العشرين لأرتحشستا الملك ، كانت خمر أمامه ، فحملت الخمر وأعطيت الملك . ولم أكن قبل مكمدا أمامه '),
(26540, 'Nehemiah', 16, 2, 2, ' فقال لي الملك : لماذا وجهك مكمد وأنت غير مريض ؟ ما هذا إلا كآبة قلب . فخفت كثيرا جدا '),
(26541, 'Nehemiah', 16, 2, 3, ' وقلت للملك : ليحي الملك إلى الأبد . كيف لا يكمد وجهي والمدينة بيت مقابر آبائي خراب ، وأبوابها قد أكلتها النار '),
(26542, 'Nehemiah', 16, 2, 4, ' فقال لي الملك : ماذا طالب أنت ؟  . فصليت إلى إله السماء '),
(26543, 'Nehemiah', 16, 2, 5, ' وقلت للملك : إذا سر الملك ، وإذا أحسن عبدك أمامك ، ترسلني إلى يهوذا ، إلى مدينة قبور آبائي فأبنيها '),
(26544, 'Nehemiah', 16, 2, 6, ' فقال لي الملك ، والملكة جالسة بجانبه : إلى متى يكون سفرك ، ومتى ترجع ؟  . فحسن لدى الملك وأرسلني ، فعينت له زمانا '),
(26545, 'Nehemiah', 16, 2, 7, ' وقلت للملك : إن حسن عند الملك فلتعط لي رسائل إلى ولاة عبر النهر لكي يجيزوني حتى أصل إلى يهوذا '),
(26546, 'Nehemiah', 16, 2, 8, ' ورسالة إلى آساف حارس فردوس الملك ، لكي يعطيني أخشابا لسقف أبواب القصر الذي للبيت ، ولسور المدينة ، وللبيت الذي أدخل إليه . فأعطاني الملك حسب يد إلهي الصالحة علي '),
(26547, 'Nehemiah', 16, 2, 9, ' فأتيت إلى ولاة عبر النهر وأعطيتهم رسائل الملك . وأرسل معي الملك رؤساء جيش وفرسانا '),
(26548, 'Nehemiah', 16, 2, 10, ' ولما سمع سنبلط الحوروني وطوبيا العبد العموني ساءهما مساءة عظيمة ، لأنه جاء رجل يطلب خيرا لبني إسرائيل '),
(26549, 'Nehemiah', 16, 2, 11, ' فجئت إلى أورشليم وكنت هناك ثلاثة أيام '),
(26550, 'Nehemiah', 16, 2, 12, ' ثم قمت ليلا أنا ورجال قليلون معي ، ولم أخبر أحدا بما جعله إلهي في قلبي لأعمله في أورشليم . ولم يكن معي بهيمة إلا البهيمة التي كنت راكبها '),
(26551, 'Nehemiah', 16, 2, 13, ' وخرجت من باب الوادي ليلا أمام عين التنين إلى باب الدمن ، وصرت أتفرس في أسوار أورشليم المنهدمة وأبوابها التي أكلتها النار '),
(26552, 'Nehemiah', 16, 2, 14, ' وعبرت إلى باب العين وإلى بركة الملك ، ولم يكن مكان لعبور البهيمة التي تحتي '),
(26553, 'Nehemiah', 16, 2, 15, ' فصعدت في الوادي ليلا وكنت أتفرس في السور ، ثم عدت فدخلت من باب الوادي راجعا '),
(26554, 'Nehemiah', 16, 2, 16, ' ولم يعرف الولاة إلى أين ذهبت ، ولا ما أنا عامل ، ولم أخبر إلى ذلك الوقت اليهود والكهنة والأشراف والولاة وباقي عاملي العمل '),
(26555, 'Nehemiah', 16, 2, 17, ' ثم قلت لهم : أنتم ترون الشر الذي نحن فيه ، كيف أن أورشليم خربة ، وأبوابها قد أحرقت بالنار . هلم فنبني سور أورشليم ولا نكون بعد عارا '),
(26556, 'Nehemiah', 16, 2, 18, ' وأخبرتهم عن يد إلهي الصالحة علي ، وأيضا عن كلام الملك الذي قاله لي ، فقالوا : لنقم ولنبن . وشددوا أياديهم للخير '),
(26557, 'Nehemiah', 16, 2, 19, ' ولما سمع سنبلط الحوروني وطوبيا العبد العموني وجشم العربي هزأوا بنا واحتقرونا ، وقالوا : ما هذا الأمر الذي أنتم عاملون ؟ أعلى الملك تتمردون '),
(26558, 'Nehemiah', 16, 2, 20, ' فأجبتهم وقلت لهم : إن إله السماء يعطينا النجاح ، ونحن عبيده نقوم ونبني . وأما أنتم فليس لكم نصيب ولا حق ولا ذكر في أورشليم '),
(26559, 'Nehemiah', 16, 3, 1, ' وقام ألياشيب الكاهن العظيم وإخوته الكهنة وبنوا باب الضأن . هم قدسوه وأقاموا مصاريعه ، وقدسوه إلى برج المئة إلى برج حننئيل '),
(26560, 'Nehemiah', 16, 3, 2, ' وبجانبه بنى رجال أريحا ، وبجانبهم بنى زكور بن إمري '),
(26561, 'Nehemiah', 16, 3, 3, ' وباب السمك بناه بنو هسناءة . هم سقفوه وأوقفوا مصاريعه وأقفاله وعوارضه '),
(26562, 'Nehemiah', 16, 3, 4, ' وبجانبهم رمم مريموث بن أوريا بن هقوص . وبجانبهم رمم مشلام بن برخيا بن مشيزبئيل . وبجانبهم رمم صادوق بن بعنا '),
(26563, 'Nehemiah', 16, 3, 5, ' وبجانبهم رمم التقوعيون ، وأما عظماؤهم فلم يدخلوا أعناقهم في عمل سيدهم '),
(26564, 'Nehemiah', 16, 3, 6, ' والباب العتيق رممه يوياداع بن فاسيح ومشلام بن بسوديا . هما سقفاه وأقاما مصاريعه وأقفاله وعوارضه '),
(26565, 'Nehemiah', 16, 3, 7, ' وبجانبهما رمم ملطيا الجبعوني ويادون الميرونوثي من أهل جبعون والمصفاة إلى كرسي والي عبر النهر '),
(26566, 'Nehemiah', 16, 3, 8, ' وبجانبهما رمم عزيئيل بن حرهايا من الصياغين . وبجانبه رمم حننيا من العطارين . وتركوا أورشليم إلى السور العريض '),
(26567, 'Nehemiah', 16, 3, 9, ' وبجانبهم رمم رفايا بن حور رئيس نصف دائرة أورشليم '),
(26568, 'Nehemiah', 16, 3, 10, ' وبجانبهم رمم يدايا بن حروماف ومقابل بيته . وبجانبه رمم حطوش بن حشبنيا '),
(26569, 'Nehemiah', 16, 3, 11, ' قسم ثان رممه ملكيا بن حاريم وحشوب بن فحث موآب وبرج التنانير '),
(26570, 'Nehemiah', 16, 3, 12, ' وبجانبه رمم شلوم بن هلوحيش رئيس نصف دائرة أورشليم هو وبناته '),
(26571, 'Nehemiah', 16, 3, 13, ' باب الوادي رممه حانون وسكان زانوح . هم بنوه وأقاموا مصاريعه وأقفاله وعوارضه ، وألف ذراع على السور إلى باب الدمن '),
(26572, 'Nehemiah', 16, 3, 14, ' وباب الدمن رممه ملكيا بن ركاب رئيس دائرة بيت هكاريم . هو بناه وأقام مصاريعه وأقفاله وعوارضه '),
(26573, 'Nehemiah', 16, 3, 15, ' وباب العين رممه شلون بن كلحوزة رئيس دائرة المصفاة . هو بناه وسقفه وأقام مصاريعه وأقفاله وعوارضه ، وسور بركة سلوام عند جنينة الملك إلى الدرج النازل من مدينة داود '),
(26574, 'Nehemiah', 16, 3, 16, ' وبعده رمم نحميا بن عزبوق رئيس نصف دائرة بيت صور إلى مقابل قبور داود ، وإلى البركة المصنوعة ، وإلى بيت الجبابرة '),
(26575, 'Nehemiah', 16, 3, 17, ' وبعده رمم اللاويون رحوم بن باني ، وبجانبه رمم حشبيا رئيس نصف دائرة قعيلة في قسمه '),
(26576, 'Nehemiah', 16, 3, 18, ' وبعده رمم إخوتهم بواي بن حيناداد رئيس نصف دائرة قعيلة '),
(26577, 'Nehemiah', 16, 3, 19, ' ورمم بجانبه عازر بن يشوع رئيس المصفاة قسما ثانيا ، من مقابل مصعد بيت السلاح عند الزاوية '),
(26578, 'Nehemiah', 16, 3, 20, ' وبعده رمم بعزم باروخ بن زباي قسما ثانيا ، من الزاوية إلى مدخل بيت ألياشيب الكاهن العظيم '),
(26579, 'Nehemiah', 16, 3, 21, ' وبعده رمم مريموث بن أوريا بن هقوص قسما ثانيا ، من مدخل بيت ألياشيب إلى نهاية بيت ألياشيب '),
(26580, 'Nehemiah', 16, 3, 22, ' وبعده رمم الكهنة أهل الغور '),
(26581, 'Nehemiah', 16, 3, 23, ' وبعدهم رمم بنيامين وحشوب مقابل بيتهما . وبعدهما رمم عزريا بن معسيا بن عننيا بجانب بيته '),
(26582, 'Nehemiah', 16, 3, 24, ' وبعده رمم بنوي بن حيناداد قسما ثانيا ، من بيت عزريا إلى الزاوية وإلى العطفة '),
(26583, 'Nehemiah', 16, 3, 25, ' وفالال بن أوزاي من مقابل الزاوية والبرج ، الذي هو خارج بيت الملك الأعلى الذي لدار السجن . وبعده فدايا بن فرعوش '),
(26584, 'Nehemiah', 16, 3, 26, ' وكان النثينيم ساكنين في الأكمة إلى مقابل باب الماء لجهة الشرق والبرج الخارجي '),
(26585, 'Nehemiah', 16, 3, 27, ' وبعدهم رمم التقوعيون قسما ثانيا ، من مقابل البرج الكبير الخارجي إلى سور الأكمة '),
(26586, 'Nehemiah', 16, 3, 28, ' وما فوق باب الخيل رممه الكهنة ، كل واحد مقابل بيته '),
(26587, 'Nehemiah', 16, 3, 29, ' وبعدهم رمم صادوق بن إمير مقابل بيته . وبعده رمم شمعيا بن شكنيا حارس باب الشرق '),
(26588, 'Nehemiah', 16, 3, 30, ' وبعده رمم حننيا بن شلميا وحانون بن صالاف السادس قسما ثانيا . وبعده رمم مشلام بن برخيا مقابل مخدعه '),
(26589, 'Nehemiah', 16, 3, 31, ' وبعده رمم ملكيا ابن الصائغ إلى بيت النثينيم والتجار ، مقابل باب العد إلى مصعد العطفة '),
(26590, 'Nehemiah', 16, 3, 32, ' وما بين مصعد العطفة إلى باب الضأن رممه الصياغون والتجار '),
(26591, 'Nehemiah', 16, 4, 1, ' ولما سمع سنبلط أننا آخذون في بناء السور غضب واغتاظ كثيرا ، وهزأ باليهود '),
(26592, 'Nehemiah', 16, 4, 2, ' وتكلم أمام إخوته وجيش السامرة وقال : ماذا يعمل اليهود الضعفاء ؟ هل يتركونهم ؟ هل يذبحون ؟ هل يكملون في يوم ؟ هل يحيون الحجارة من كوم التراب وهي محرقة '),
(26593, 'Nehemiah', 16, 4, 3, ' وكان طوبيا العموني بجانبه ، فقال : إن ما يبنونه إذا صعد ثعلب فإنه يهدم حجارة حائطهم '),
(26594, 'Nehemiah', 16, 4, 4, ' اسمع يا إلهنا ، لأننا قد صرنا احتقارا ، ورد تعييرهم على رؤوسهم ، واجعلهم نهبا في أرض السبي '),
(26595, 'Nehemiah', 16, 4, 5, ' ولا تستر ذنوبهم ولا تمح خطيتهم من أمامك لأنهم أغضبوك أمام البانين '),
(26596, 'Nehemiah', 16, 4, 6, ' فبنينا السور ، واتصل كل السور إلى نصفه وكان للشعب قلب في العمل '),
(26597, 'Nehemiah', 16, 4, 7, ' ولما سمع سنبلط وطوبيا والعرب والعمونيون والأشدوديون أن أسوار أورشليم قد رممت والثغر ابتدأت تسد ، غضبوا جدا '),
(26598, 'Nehemiah', 16, 4, 8, ' وتآمروا جميعهم معا أن يأتوا ويحاربوا أورشليم ويعملوا بها ضررا '),
(26599, 'Nehemiah', 16, 4, 9, ' فصلينا إلى إلهنا وأقمنا حراسا ضدهم نهارا وليلا بسببهم '),
(26600, 'Nehemiah', 16, 4, 10, ' وقال يهوذا : قد ضعفت قوة الحمالين ، والتراب كثير ، ونحن لا نقدر أن نبني السور '),
(26601, 'Nehemiah', 16, 4, 11, ' وقال أعداؤنا : لا يعلمون ولا يرون حتى ندخل إلى وسطهم ونقتلهم ونوقف العمل '),
(26602, 'Nehemiah', 16, 4, 12, ' ولما جاء اليهود الساكنون بجانبهم قالوا لنا عشر مرات : من جميع الأماكن التي منها رجعوا إلينا '),
(26603, 'Nehemiah', 16, 4, 13, ' فأوقفت الشعب من أسفل الموضع وراء السور وعلى القمم ، أوقفتهم حسب عشائرهم ، بسيوفهم ورماحهم وقسيهم '),
(26604, 'Nehemiah', 16, 4, 14, ' ونظرت وقمت وقلت للعظماء والولاة ولبقية الشعب : لا تخافوهم بل اذكروا السيد العظيم المرهوب ، وحاربوا من أجل إخوتكم وبنيكم وبناتكم ونسائكم وبيوتكم '),
(26605, 'Nehemiah', 16, 4, 15, ' ولما سمع أعداؤنا أننا قد عرفنا ، وأبطل الله مشورتهم ، رجعنا كلنا إلى السور كل واحد إلى شغله '),
(26606, 'Nehemiah', 16, 4, 16, ' ومن ذلك اليوم كان نصف غلماني يشتغلون في العمل ، ونصفهم يمسكون الرماح والأتراس والقسي والدروع . والرؤساء وراء كل بيت يهوذا '),
(26607, 'Nehemiah', 16, 4, 17, ' البانون على السور بنوا وحاملو الأحمال حملوا . باليد الواحدة يعملون العمل ، وبالأخرى يمسكون السلاح '),
(26608, 'Nehemiah', 16, 4, 18, ' وكان البانون يبنون ، وسيف كل واحد مربوط على جنبه ، وكان النافخ بالبوق بجانبي '),
(26609, 'Nehemiah', 16, 4, 19, ' فقلت للعظماء والولاة ولبقية الشعب : العمل كثير ومتسع ونحن متفرقون على السور وبعيدون بعضنا عن بعض '),
(26610, 'Nehemiah', 16, 4, 20, ' فالمكان الذي تسمعون منه صوت البوق هناك تجتمعون إلينا . إلهنا يحارب عنا '),
(26611, 'Nehemiah', 16, 4, 21, ' فكنا نحن نعمل العمل ، وكان نصفهم يمسكون الرماح من طلوع الفجر إلى ظهور النجوم '),
(26612, 'Nehemiah', 16, 4, 22, ' وقلت في ذلك الوقت أيضا للشعب : ليبت كل واحد مع غلامه في وسط أورشليم ليكونوا لنا حراسا في الليل وللعمل في النهار '),
(26613, 'Nehemiah', 16, 4, 23, ' ولم أكن أنا ولا إخوتي ولا غلماني ولا الحراس الذين ورائي نخلع ثيابنا . كان كل واحد يذهب بسلاحه إلى الماء '),
(26614, 'Nehemiah', 16, 5, 1, ' وكان صراخ الشعب ونسائهم عظيما على إخوتهم اليهود '),
(26615, 'Nehemiah', 16, 5, 2, ' وكان من يقول : بنونا وبناتنا نحن كثيرون . دعنا نأخذ قمحا فنأكل ونحيا '),
(26616, 'Nehemiah', 16, 5, 3, ' وكان من يقول : حقولنا وكرومنا وبيوتنا نحن راهنوها حتى نأخذ قمحا في الجوع '),
(26617, 'Nehemiah', 16, 5, 4, ' وكان من يقول : قد استقرضنا فضة لخراج الملك على حقولنا وكرومنا '),
(26618, 'Nehemiah', 16, 5, 5, ' والآن لحمنا كلحم إخوتنا وبنونا كبنيهم ، وها نحن نخضع بنينا وبناتنا عبيدا ، ويوجد من بناتنا مستعبدات ، وليس شيء في طاقة يدنا ، وحقولنا وكرومنا للآخرين '),
(26619, 'Nehemiah', 16, 5, 6, ' فغضبت جدا حين سمعت صراخهم وهذا الكلام '),
(26620, 'Nehemiah', 16, 5, 7, ' فشاورت قلبي في ، وبكت العظماء والولاة ، وقلت لهم : إنكم تأخذون الربا كل واحد من أخيه . وأقمت عليهم جماعة عظيمة '),
(26621, 'Nehemiah', 16, 5, 8, ' وقلت لهم : نحن اشترينا إخوتنا اليهود الذين بيعوا للأمم حسب طاقتنا . وأنتم أيضا تبيعون إخوتكم فيباعون لنا . فسكتوا ولم يجدوا جوابا '),
(26622, 'Nehemiah', 16, 5, 9, ' وقلت : ليس حسنا الأمر الذي تعملونه . أما تسيرون بخوف إلهنا بسبب تعيير الأمم أعدائنا '),
(26623, 'Nehemiah', 16, 5, 10, ' وأنا أيضا وإخوتي وغلماني أقرضناهم فضة وقمحا . فلنترك هذا الربا '),
(26624, 'Nehemiah', 16, 5, 11, ' ردوا لهم هذا اليوم حقولهم وكرومهم وزيتونهم وبيوتهم ، والجزء من مئة الفضة والقمح والخمر والزيت الذي تأخذونه منهم ربا '),
(26625, 'Nehemiah', 16, 5, 12, ' فقالوا : نرد ولا نطلب منهم . هكذا نفعل كما تقول . فدعوت الكهنة واستحلفتهم أن يعملوا حسب هذا الكلام '),
(26626, 'Nehemiah', 16, 5, 13, ' ثم نفضت حجري وقلت : هكذا ينفض الله كل إنسان لا يقيم هذا الكلام من بيته ومن تعبه ، وهكذا يكون منفوضا وفارغا . فقال كل الجماعة : آمين . وسبحوا الرب . وعمل الشعب حسب هذا الكلام '),
(26627, 'Nehemiah', 16, 5, 14, ' وأيضا من اليوم الذي أوصيت فيه أن أكون واليهم في أرض يهوذا ، من السنة العشرين إلى السنة الثانية والثلاثين لأرتحشستا الملك ، اثنتي عشرة سنة ، لم آكل أنا ولا إخوتي خبز الوالي '),
(26628, 'Nehemiah', 16, 5, 15, ' ولكن الولاة الأولون الذين قبلي ثقلوا على الشعب ، وأخذوا منهم خبزا وخمرا ، فضلا عن أربعين شاقلا من الفضة ، حتى إن غلمانهم تسلطوا على الشعب . وأما أنا فلم أفعل هكذا من أجل خوف الله '),
(26629, 'Nehemiah', 16, 5, 16, ' وتمسكت أيضا بشغل هذا السور ، ولم أشتر حقلا . وكان جميع غلماني مجتمعين هناك على العمل '),
(26630, 'Nehemiah', 16, 5, 17, ' وكان على مائدتي من اليهود والولاة مئة وخمسون رجلا ، فضلا عن الآتين إلينا من الأمم الذين حولنا '),
(26631, 'Nehemiah', 16, 5, 18, ' وكان ما يعمل ليوم واحد ثورا وستة خراف مختارة . وكان يعمل لي طيور ، وفي كل عشرة أيام كل نوع من الخمر بكثرة . ومع هذا لم أطلب خبز الوالي ، لأن العبودية كانت ثقيلة على هذا الشعب '),
(26632, 'Nehemiah', 16, 5, 19, ' اذكر لي يا إلهي للخير كل ما عملت لهذا الشعب '),
(26633, 'Nehemiah', 16, 6, 1, ' ولما سمع سنبلط وطوبيا وجشم العربي وبقية أعدائنا أني قد بنيت السور ولم تبق فيه ثغرة ، على أني لم أكن إلى ذلك الوقت قد أقمت مصاريع للأبواب '),
(26634, 'Nehemiah', 16, 6, 2, ' أرسل سنبلط وجشم إلي قائلين : هلم نجتمع معا في القرى في بقعة أونو . وكانا يفكران أن يعملا بي شرا '),
(26635, 'Nehemiah', 16, 6, 3, ' فأرسلت إليهما رسلا قائلا : إني أنا عامل عملا عظيما فلا أقدر أن أنزل . لماذا يبطل العمل بينما أتركه وأنزل إليكما '),
(26636, 'Nehemiah', 16, 6, 4, ' وأرسلا إلي بمثل هذا الكلام أربع مرات ، وجاوبتهما بمثل هذا الجواب '),
(26637, 'Nehemiah', 16, 6, 5, ' فأرسل إلي سنبلط بمثل هذا الكلام مرة خامسة مع غلامه برسالة منشورة بيده مكتوب فيها '),
(26638, 'Nehemiah', 16, 6, 6, ' قد سمع بين الأمم ، وجشم يقول : إنك أنت واليهود تفكرون أن تتمردوا ، لذلك أنت تبني السور لتكون لهم ملكا حسب هذه الأمور '),
(26639, 'Nehemiah', 16, 6, 7, ' وقد أقمت أيضا أنبياء لينادوا بك في أورشليم قائلين : في يهوذا ملك . والآن يخبر الملك بهذا الكلام . فهلم الآن نتشاور معا '),
(26640, 'Nehemiah', 16, 6, 8, ' فأرسلت إليه قائلا : لا يكون مثل هذا الكلام الذي تقوله ، بل إنما أنت مختلقه من قلبك '),
(26641, 'Nehemiah', 16, 6, 9, ' لأنهم كانوا جميعا يخيفوننا قائلين : قد ارتخت أيديهم عن العمل فلا يعمل . فالآن يا إلهي شدد يدي '),
(26642, 'Nehemiah', 16, 6, 10, ' ودخلت بيت شمعيا بن دلايا بن مهيطبئيل وهو مغلق ، فقال : لنجتمع إلى بيت الله إلى وسط الهيكل ونقفل أبواب الهيكل ، لأنهم يأتون ليقتلوك . في الليل يأتون ليقتلوك '),
(26643, 'Nehemiah', 16, 6, 11, ' فقلت : أرجل مثلي يهرب ؟ ومن مثلي يدخل الهيكل فيحيا ؟ لا أدخل '),
(26644, 'Nehemiah', 16, 6, 12, ' فتحققت وهوذا لم يرسله الله لأنه تكلم بالنبوة علي ، وطوبيا وسنبلط قد استأجراه '),
(26645, 'Nehemiah', 16, 6, 13, ' لأجل هذا قد استؤجر لكي أخاف وأفعل هكذا وأخطئ ، فيكون لهما خبر رديء لكي يعيراني '),
(26646, 'Nehemiah', 16, 6, 14, ' اذكر يا إلهي طوبيا وسنبلط حسب أعمالهما هذه ، ونوعدية النبية وباقي الأنبياء الذين يخيفونني '),
(26647, 'Nehemiah', 16, 6, 15, ' وكمل السور في الخامس والعشرين من أيلول ، في اثنين وخمسين يوما '),
(26648, 'Nehemiah', 16, 6, 16, ' ولما سمع كل أعدائنا ورأى جميع الأمم الذين حوالينا ، سقطوا كثيرا في أعين أنفسهم ، وعلموا أنه من قبل إلهنا عمل هذا العمل '),
(26649, 'Nehemiah', 16, 6, 17, ' وأيضا في تلك الأيام أكثر عظماء يهوذا توارد رسائلهم على طوبيا ، ومن عند طوبيا أتت الرسائل إليهم '),
(26650, 'Nehemiah', 16, 6, 18, ' لأن كثيرين في يهوذا كانوا أصحاب حلف له ، لأنه صهر شكنيا بن آرح ، ويهوحانان ابنه أخذ بنت مشلام بن برخيا '),
(26651, 'Nehemiah', 16, 6, 19, ' وكانوا أيضا يخبرون أمامي بحسناته '),
(26652, 'Nehemiah', 16, 7, 1, ' ولما بني السور ، وأقمت المصاريع ، وترتب البوابون والمغنون واللاويون '),
(26653, 'Nehemiah', 16, 7, 2, ' أقمت حناني أخي وحننيا رئيس القصر على أورشليم ، لأنه كان رجلا أمينا يخاف الله أكثر من كثيرين '),
(26654, 'Nehemiah', 16, 7, 3, ' وقلت لهما : لا تفتح أبواب أورشليم حتى تحمى الشمس . وما داموا وقوفا فليغلقوا المصاريع ويقفلوها . وأقيم حراسات من سكان أورشليم ، كل واحد على حراسته ، وكل واحد مقابل بيته '),
(26655, 'Nehemiah', 16, 7, 4, ' وكانت المدينة واسعة الجناب وعظيمة ، والشعب قليلا في وسطها ، ولم تكن البيوت قد بنيت '),
(26656, 'Nehemiah', 16, 10, 7, ' ومشلام وأبيا وميامين '),
(26657, 'Nehemiah', 16, 10, 8, ' ومعزيا وبلجاي وشمعيا ، هؤلاء هم الكهنة '),
(26658, 'Nehemiah', 16, 10, 9, ' واللاويون : يشوع بن أزنيا وبنوي من بني حيناداد وقدميئيل '),
(26659, 'Nehemiah', 16, 10, 10, ' وإخوتهم : شبنيا وهوديا وقليطا وفلايا وحانان '),
(26660, 'Nehemiah', 16, 10, 11, ' وميخا ورحوب وحشبيا '),
(26661, 'Nehemiah', 16, 10, 12, ' وزكور وشربيا وشبنيا '),
(26662, 'Nehemiah', 16, 10, 13, ' وهوديا وباني وبنينو '),
(26663, 'Nehemiah', 16, 10, 14, ' رؤوس الشعب : فرعوش وفحث موآب وعيلام وزتو وباني '),
(26664, 'Nehemiah', 16, 10, 15, ' وبني وعزجد وبيباي '),
(26665, 'Nehemiah', 16, 10, 16, ' وأدونيا وبغواي وعادين '),
(26666, 'Nehemiah', 16, 10, 17, ' وآطير وحزقيا وعزور '),
(26667, 'Nehemiah', 16, 10, 18, ' وهوديا وحشوم وبيصاي '),
(26668, 'Nehemiah', 16, 10, 19, ' وحاريف وعناثوث ونيباي '),
(26669, 'Nehemiah', 16, 10, 20, ' ومجفيعاش ومشلام وحزير '),
(26670, 'Nehemiah', 16, 10, 21, ' ومشيزبئيل وصادوق ويدوع '),
(26671, 'Nehemiah', 16, 10, 22, ' وفلطيا وحانان وعنايا '),
(26672, 'Nehemiah', 16, 10, 23, ' وهوشع وحننيا وحشوب '),
(26673, 'Nehemiah', 16, 10, 24, ' وهلوحيش وفلحا وشوبيق '),
(26674, 'Nehemiah', 16, 10, 25, ' ورحوم وحشبنا ومعسيا '),
(26675, 'Nehemiah', 16, 10, 26, ' وأخيا وحانان وعانان '),
(26676, 'Nehemiah', 16, 10, 27, ' وملوخ وحريم وبعنة '),
(26677, 'Nehemiah', 16, 10, 28, ' وباقي الشعب والكهنة واللاويين والبوابين والمغنين والنثينيم ، وكل الذين انفصلوا من شعوب الأراضي إلى شريعة الله ، ونسائهم وبنيهم وبناتهم ، كل أصحاب المعرفة والفهم '),
(26678, 'Nehemiah', 16, 10, 29, ' لصقوا بإخوتهم وعظمائهم ودخلوا في قسم وحلف أن يسيروا في شريعة الله التي أعطيت عن يد موسى عبد الله ، وأن يحفظوا ويعملوا جميع وصايا الرب سيدنا ، وأحكامه وفرائضه '),
(26679, 'Nehemiah', 16, 10, 30, ' وأن لا نعطي بناتنا لشعوب الأرض ، ولا نأخذ بناتهم لبنينا '),
(26680, 'Nehemiah', 16, 10, 31, ' وشعوب الأرض الذين يأتون بالبضائع وكل طعام يوم السبت للبيع ، لا نأخذ منهم في سبت ولا في يوم مقدس ، وأن نترك السنة السابعة ، والمطالبة بكل دين '),
(26681, 'Nehemiah', 16, 10, 32, ' وأقمنا على أنفسنا فرائض : أن نجعل على أنفسنا ثلث شاقل كل سنة لخدمة بيت إلهنا '),
(26682, 'Nehemiah', 16, 10, 33, ' لخبز الوجوه والتقدمة الدائمة والمحرقة الدائمة والسبوت والأهلة والمواسم والأقداس وذبائح الخطية ، للتكفير عن إسرائيل ، ولكل عمل بيت إلهنا '),
(26683, 'Nehemiah', 16, 10, 34, ' وألقينا قرعا على قربان الحطب بين الكهنة واللاويين والشعب ، لإدخاله إلى بيت إلهنا حسب بيوت آبائنا ، في أوقات معينة سنة فسنة ، لأجل إحراقه على مذبح الرب إلهنا كما هو مكتوب في الشريعة '),
(26684, 'Nehemiah', 16, 10, 35, ' ولإدخال باكورات أرضنا ، وباكورات ثمر كل شجرة سنة فسنة إلى بيت الرب '),
(26685, 'Nehemiah', 16, 10, 36, ' وأبكار بنينا وبهائمنا ، كما هو مكتوب في الشريعة ، وأبكار بقرنا وغنمنا لإحضارها إلى بيت إلهنا ، إلى الكهنة الخادمين في بيت إلهنا '),
(26686, 'Nehemiah', 16, 10, 37, ' وأن نأتي بأوائل عجيننا ورفائعنا وأثمار كل شجرة من الخمر والزيت إلى الكهنة ، إلى مخادع بيت إلهنا ، وبعشر أرضنا إلى اللاويين ، واللاويون هم الذين يعشرون في جميع مدن فلاحتنا '),
(26687, 'Nehemiah', 16, 10, 38, ' ويكون الكاهن ابن هارون مع اللاويين حين يعشر اللاويون ، ويصعد اللاويون عشر الأعشار إلى بيت إلهنا ، إلى المخادع ، إلى بيت الخزينة '),
(26688, 'Nehemiah', 16, 10, 39, ' لأن بني إسرائيل وبني لاوي يأتون برفيعة القمح والخمر والزيت إلى المخادع ، وهناك آنية القدس والكهنة الخادمون والبوابون والمغنون ، ولا نترك بيت إلهنا '),
(26689, 'Nehemiah', 16, 11, 1, ' وسكن رؤساء الشعب في أورشليم ، وألقى سائر الشعب قرعا ليأتوا بواحد من عشرة للسكنى في أورشليم ، مدينة القدس ، والتسعة الأقسام في المدن '),
(26690, 'Nehemiah', 16, 11, 2, ' وبارك الشعب جميع القوم الذين انتدبوا للسكنى في أورشليم '),
(26691, 'Nehemiah', 16, 11, 3, ' وهؤلاء هم رؤوس البلاد الذين سكنوا في أورشليم وفي مدن يهوذا . سكن كل واحد في ملكه ، في مدنهم من إسرائيل ، الكهنة واللاويون والنثينيم وبنو عبيد سليمان '),
(26692, 'Nehemiah', 16, 11, 4, ' وسكن في أورشليم من بني يهوذا ومن بني بنيامين . فمن بني يهوذا : عثايا بن عزيا بن زكريا بن أمريا بن شفطيا بن مهللئيل من بني فارص '),
(26693, 'Nehemiah', 16, 11, 5, ' ومعسيا بن باروخ بن كلحوزة بن حزايا بن عدايا بن يوياريب بن زكريا بن الشيلوني '),
(26694, 'Nehemiah', 16, 11, 6, ' جميع بني فارص الساكنين في أورشليم أربع مئة وثمانية وستون من رجال البأس '),
(26695, 'Nehemiah', 16, 11, 7, ' وهؤلاء بنو بنيامين : سلو بن مشلام بن يوعيد بن فدايا بن قولايا بن معسيا بن إيثيئيل بن يشعيا '),
(26696, 'Nehemiah', 16, 11, 8, ' وبعده جباي سلاي . تسع مئة وثمانية وعشرون '),
(26697, 'Nehemiah', 16, 11, 9, ' وكان يوئيل بن زكري وكيلا عليهم ، ويهوذا بن هسنوآة ثانيا على المدينة '),
(26698, 'Nehemiah', 16, 11, 10, ' من الكهنة : يدعيا بن يوياريب وياكين '),
(26699, 'Nehemiah', 16, 11, 11, ' وسرايا بن حلقيا بن مشلام بن صادوق بن مرايوث بن أخيطوب رئيس بيت الله '),
(26700, 'Nehemiah', 16, 11, 12, ' وإخوتهم عاملو العمل للبيت ثمان مئة واثنان وعشرون . وعدايا بن يروحام بن فلليا بن أمصي بن زكريا بن فشحور بن ملكيا '),
(26701, 'Nehemiah', 16, 11, 13, ' وإخوته رؤوس الآباء مئتان واثنان وأربعون . وعمشساي بن عزرئيل بن أخزاي بن مشليموث بن إمير '),
(26702, 'Nehemiah', 16, 11, 14, ' وإخوتهم جبابرة بأس مئة وثمانية وعشرون . والوكيل عليهم زبديئيل بن هجدوليم '),
(26703, 'Nehemiah', 16, 11, 15, ' ومن اللاويين : شمعيا بن حشوب بن عزريقام بن حشبيا بن بوني '),
(26704, 'Nehemiah', 16, 11, 16, ' وشبتاي ويوزاباد على العمل الخارجي لبيت الله من رؤوس اللاويين '),
(26705, 'Nehemiah', 16, 11, 17, ' ومتنيا بن ميخا بن زبدي بن آساف ، رئيس التسبيح يحمد في الصلاة وبقبقيا الثاني بين إخوته ، وعبدا بن شموع بن جلال بن يدوثون '),
(26706, 'Nehemiah', 16, 11, 18, ' جميع اللاويين في المدينة المقدسة مئتان وثمانية وأربعون '),
(26707, 'Nehemiah', 16, 11, 19, ' والبوابون : عقوب وطلمون وإخوتهما حارسو الأبواب مئة واثنان وسبعون '),
(26708, 'Nehemiah', 16, 11, 20, ' وكان سائر إسرائيل من الكهنة واللاويين في جميع مدن يهوذا ، كل واحد في ميراثه '),
(26709, 'Nehemiah', 16, 11, 21, ' وأما النثينيم فسكنوا في الأكمة . وكان صيحا وجشفا على النثينيم '),
(26710, 'Nehemiah', 16, 11, 22, ' وكان وكيل اللاويين في أورشليم على عمل بيت الله عزي بن باني بن حشبيا بن متنيا بن ميخا من بني آساف المغنين '),
(26711, 'Nehemiah', 16, 11, 23, ' لأن وصية الملك من جهتهم كانت أن للمرنمين فريضة أمر كل يوم فيوم '),
(26712, 'Nehemiah', 16, 11, 24, ' وفتحيا بن مشيزبئيل من بني زارح بن يهوذا ، كان تحت يد الملك في كل أمور الشعب '),
(26713, 'Nehemiah', 16, 11, 25, ' وفي الضياع مع حقولها سكن من بني يهوذا في قرية أربع وقراها ، وديبون وقراها ، وفي يقبصئيل وضياعها '),
(26714, 'Nehemiah', 16, 11, 26, ' وفي يشوع ومولادة وبيت فالط '),
(26715, 'Nehemiah', 16, 7, 5, ' فألهمني إلهي أن أجمع العظماء والولاة والشعب لأجل الانتساب . فوجدت سفر انتساب الذين صعدوا أولا ، ووجدت مكتوبا فيه '),
(26716, 'Nehemiah', 16, 7, 6, ' هؤلاء هم بنو الكورة الصاعدون من سبي المسبيين الذين سباهم نبوخذنصر ملك بابل ورجعوا إلى أورشليم ويهوذا ، كل واحد إلى مدينته '),
(26717, 'Nehemiah', 16, 7, 7, ' الذين جاءوا مع زربابل ، يشوع ، نحميا ، عزريا ، رعميا ، نحماني ، مردخاي ، بلشان ، مسفارث بغواي ، نحوم ، وبعنة . عدد رجال شعب إسرائيل '),
(26718, 'Nehemiah', 16, 7, 8, ' بنو فرعوش ألفان ومئة واثنان وسبعون '),
(26719, 'Nehemiah', 16, 7, 9, ' بنو شفطيا ثلاث مئة واثنان وسبعون '),
(26720, 'Nehemiah', 16, 7, 10, ' بنو آرح ست مئة واثنان وخمسون '),
(26721, 'Nehemiah', 16, 7, 11, ' بنو فحث موآب من بني يشوع ويوآب ألفان وثمان مئة وثمانية عشر '),
(26722, 'Nehemiah', 16, 7, 12, ' بنو عيلام ألف ومئتان وأربعة وخمسون '),
(26723, 'Nehemiah', 16, 7, 13, ' بنو زتو ثمان مئة وخمسة وأربعون '),
(26724, 'Nehemiah', 16, 7, 14, ' بنو زكاي سبع مئة وستون '),
(26725, 'Nehemiah', 16, 7, 15, ' بنو بنوي ست مئة وثمانية وأربعون '),
(26726, 'Nehemiah', 16, 7, 16, ' بنو باباي ست مئة وثمانية وعشرون '),
(26727, 'Nehemiah', 16, 7, 17, ' بنو عزجد ألفان وثلاث مئة واثنان وعشرون '),
(26728, 'Nehemiah', 16, 7, 18, ' بنو أدونيقام ست مئة وسبعة وستون '),
(26729, 'Nehemiah', 16, 7, 19, ' بنو بغواي ألفان وسبعة وستون '),
(26730, 'Nehemiah', 16, 7, 20, ' بنو عادين ست مئة وخمسة وخمسون '),
(26731, 'Nehemiah', 16, 7, 21, ' بنو أطير لحزقيا ثمانية وتسعون '),
(26732, 'Nehemiah', 16, 7, 22, ' بنو حشوم ثلاث مئة وثمانية وعشرون '),
(26733, 'Nehemiah', 16, 7, 23, ' بنو بيصاي ثلاث مئة وأربعة وعشرون '),
(26734, 'Nehemiah', 16, 7, 24, ' بنو حاريف مئة واثنا عشر '),
(26735, 'Nehemiah', 16, 7, 25, ' بنو جبعون خمسة وتسعون '),
(26736, 'Nehemiah', 16, 7, 26, ' رجال بيت لحم ونطوفة مئة وثمانية وثمانون '),
(26737, 'Nehemiah', 16, 7, 27, ' رجال عناثوث مئة وثمانية وعشرون '),
(26738, 'Nehemiah', 16, 7, 28, ' رجال بيت عزموت اثنان وأربعون '),
(26739, 'Nehemiah', 16, 7, 29, ' رجال قرية يعاريم كفيرة وبئيروت سبع مئة وثلاثة وأربعون '),
(26740, 'Nehemiah', 16, 7, 30, ' رجال الرامة وجبع ست مئة وواحد وعشرون '),
(26741, 'Nehemiah', 16, 7, 31, ' رجال مخماس مئة واثنان وعشرون '),
(26742, 'Nehemiah', 16, 7, 32, ' رجال بيت إيل وعاي مئة وثلاثة وعشرون '),
(26743, 'Nehemiah', 16, 7, 33, ' رجال نبو الأخرى اثنان وخمسون '),
(26744, 'Nehemiah', 16, 7, 34, ' بنو عيلام الآخر ألف ومئتان وأربعة وخمسون '),
(26745, 'Nehemiah', 16, 7, 35, ' بنو حاريم ثلاث مئة وعشرون '),
(26746, 'Nehemiah', 16, 7, 36, ' بنو أريحا ثلاث مئة وخمسة وأربعون '),
(26747, 'Nehemiah', 16, 7, 37, ' بنو لود بنو حاديد وأونو سبع مئة وواحد وعشرون '),
(26748, 'Nehemiah', 16, 7, 38, ' بنو سناءة ثلاثة آلاف وتسع مئة وثلاثون '),
(26749, 'Nehemiah', 16, 7, 39, ' أما الكهنة : فبنو يدعيا من بيت يشوع تسع مئة وثلاثة وسبعون '),
(26750, 'Nehemiah', 16, 7, 40, ' بنو إمير ألف واثنان وخمسون '),
(26751, 'Nehemiah', 16, 7, 41, ' بنو فشحور ألف ومئتان وسبعة وأربعون '),
(26752, 'Nehemiah', 16, 7, 42, ' بنو حاريم ألف وسبعة عشر '),
(26753, 'Nehemiah', 16, 7, 43, ' أما اللاويون : فبنو يشوع ، لقدميئيل من بني هودويا أربعة وسبعون '),
(26754, 'Nehemiah', 16, 7, 44, ' المغنون : بنو آساف مئة وثمانية وأربعون '),
(26755, 'Nehemiah', 16, 7, 45, ' البوابون : بنو شلوم ، بنو أطير ، بنو طلمون ، بنو عقوب ، بنو حطيطا ، بنو شوباي مئة وثمانية وثلاثون '),
(26756, 'Nehemiah', 16, 7, 46, ' النثينيم : بنو صيحا ، بنو حسوفا ، بنو طباعوت '),
(26757, 'Nehemiah', 16, 7, 47, ' بنو قيروس ، بنو سيعا ، بنو فادون '),
(26758, 'Nehemiah', 16, 7, 48, ' وبنو لبانة وبنو حجابا ، بنو سلماي '),
(26759, 'Nehemiah', 16, 7, 49, ' بنو حانان ، بنو جديل ، بنو جاحر '),
(26760, 'Nehemiah', 16, 7, 50, ' بنو رآيا ، بنو رصين وبنو نقودا '),
(26761, 'Nehemiah', 16, 7, 51, ' بنو جزام ، بنو عزا ، بنو فاسيح '),
(26762, 'Nehemiah', 16, 7, 52, ' بنو بيساي ، بنو معونيم ، بنو نفيشسيم '),
(26763, 'Nehemiah', 16, 7, 53, ' بنو بقبوق ، بنو حقوفا ، بنو حرحور '),
(26764, 'Nehemiah', 16, 7, 54, ' بنو بصليت ، بنو محيدا ، بنو حرشا '),
(26765, 'Nehemiah', 16, 7, 55, ' بنو برقوس ، بنو سيسرا ، بنو تامح '),
(26766, 'Nehemiah', 16, 7, 56, ' بنو نصيح ، بنو حطيفا '),
(26767, 'Nehemiah', 16, 7, 57, ' بنو عبيد سليمان : بنو سوطاي ، بنو سوفرث ، بنو فريدا '),
(26768, 'Nehemiah', 16, 7, 58, ' بنو يعلا ، بنو درقون ، بنو جديل '),
(26769, 'Nehemiah', 16, 7, 59, ' بنو شفطيا ، بنو حطيل ، بنو فوخرة الظباء ، بنو آمون '),
(26770, 'Nehemiah', 16, 7, 60, ' كل النثينيم وبني عبيد سليمان ثلاث مئة واثنان وتسعون '),
(26771, 'Nehemiah', 16, 7, 61, ' وهؤلاء هم الذين صعدوا من تل ملح وتل حرشا ، كروب وأدون وإمير ، ولم يستطيعوا أن يبينوا بيوت آبائهم ونسلهم هل هم من إسرائيل '),
(26772, 'Nehemiah', 16, 7, 62, ' بنو دلايا ، بنو طوبيا ، بنو نقودا ست مئة واثنان وأربعون '),
(26773, 'Nehemiah', 16, 7, 63, ' ومن الكهنة : بنو حبابا ، بنو هقوص ، بنو برزلاي ، الذي أخذ امرأة من بنات برزلاي الجلعادي وتسمى باسمهم '),
(26774, 'Nehemiah', 16, 7, 64, ' هؤلاء فحصوا عن كتابة أنسابهم فلم توجد ، فرذلوا من الكهنوت '),
(26775, 'Nehemiah', 16, 7, 65, ' وقال لهم الترشاثا أن لا يأكلوا من قدس الأقداس حتى يقوم كاهن للأوريم والتميم '),
(26776, 'Nehemiah', 16, 7, 66, ' كل الجمهور معا أربع ربوات وألفان وثلاث مئة وستون '),
(26777, 'Nehemiah', 16, 7, 67, ' فضلا عن عبيدهم وإمائهم الذين كانوا سبعة آلاف وثلاث مئة وسبعة وثلاثين . ولهم من المغنين والمغنيات مئتان وخمسة وأربعون '),
(26778, 'Nehemiah', 16, 7, 68, ' وخيلهم سبع مئة وستة وثلاثون ، وبغالهم مئتان وخمسة وأربعون '),
(26779, 'Nehemiah', 16, 7, 69, ' والجمال أربع مئة وخمسة وثلاثون ، والحمير ستة آلاف وسبع مئة وعشرون '),
(26780, 'Nehemiah', 16, 7, 70, ' والبعض من رؤوس الآباء أعطوا للعمل . الترشاثا أعطى للخزينة ألف درهم من الذهب ، وخمسين منضحة ، وخمس مئة وثلاثين قميصا للكهنة '),
(26781, 'Nehemiah', 16, 7, 71, ' والبعض من رؤوس الآباء أعطوا لخزينة العمل ربوتين من الذهب ، وألفين ومئتي منا من الفضة '),
(26782, 'Nehemiah', 16, 7, 72, ' وما أعطاه بقية الشعب ست ربوات من الذهب ، وألفي منا من الفضة ، وسبعة وستين قميصا للكهنة '),
(26783, 'Nehemiah', 16, 7, 73, ' وأقام الكهنة واللاويون والبوابون والمغنون وبعض الشعب والنثينيم وكل إسرائيل في مدنهم . ولما استهل الشهر السابع وبنو إسرائيل في مدنهم '),
(26784, 'Nehemiah', 16, 8, 1, ' اجتمع كل الشعب كرجل واحد إلى الساحة التي أمام باب الماء ، وقالوا لعزرا الكاتب أن يأتي بسفر شريعة موسى التي أمر بها الرب إسرائيل '),
(26785, 'Nehemiah', 16, 8, 2, ' فأتى عزرا الكاتب بالشريعة أمام الجماعة من الرجال والنساء وكل فاهم ما يسمع ، في اليوم الأول من الشهر السابع '),
(26786, 'Nehemiah', 16, 8, 3, ' وقرأ فيها أمام الساحة التي أمام باب الماء ، من الصباح إلى نصف النهار ، أمام الرجال والنساء والفاهمين . وكانت آذان كل الشعب نحو سفر الشريعة '),
(26787, 'Nehemiah', 16, 8, 4, ' ووقف عزرا الكاتب على منبر الخشب الذي عملوه لهذا الأمر ، ووقف بجانبه متثيا وشمع وعنايا وأوريا وحلقيا ومعسيا عن يمينه ، وعن يساره فدايا وميشائيل وملكيا وحشوم وحشبدانة وزكريا ومشلام '),
(26788, 'Nehemiah', 16, 8, 5, ' وفتح عزرا السفر أمام كل الشعب ، لأنه كان فوق كل الشعب . وعندما فتحه وقف كل الشعب '),
(26789, 'Nehemiah', 16, 8, 6, ' وبارك عزرا الرب الإله العظيم . وأجاب جميع الشعب : آمين ، آمين . رافعين أيديهم ، وخروا وسجدوا للرب على وجوههم إلى الأرض '),
(26790, 'Nehemiah', 16, 8, 7, ' ويشوع وباني وشربيا ويامين وعقوب وشبتاي وهوديا ومعسيا وقليطا وعزريا ويوزاباد وحنان وفلايا واللاويون أفهموا الشعب الشريعة ، والشعب في أماكنهم '),
(26791, 'Nehemiah', 16, 8, 8, ' وقرأوا في السفر ، في شريعة الله ، ببيان ، وفسروا المعنى ، وأفهموهم القراءة '),
(26792, 'Nehemiah', 16, 8, 9, ' ونحميا أي الترشاثا ، وعزرا الكاهن الكاتب ، واللاويون المفهمون الشعب قالوا لجميع الشعب : هذا اليوم مقدس للرب إلهكم ، لا تنوحوا ولا تبكوا . لأن جميع الشعب بكوا حين سمعوا كلام الشريعة '),
(26793, 'Nehemiah', 16, 8, 10, ' فقال لهم : اذهبوا كلوا السمين ، واشربوا الحلو ، وابعثوا أنصبة لمن لم يعد له ، لأن اليوم إنما هو مقدس لسيدنا . ولا تحزنوا ، لأن فرح الرب هو قوتكم '),
(26794, 'Nehemiah', 16, 8, 11, ' وكان اللاويون يسكتون كل الشعب قائلين : اسكتوا ، لأن اليوم مقدس فلا تحزنوا '),
(26795, 'Nehemiah', 16, 8, 12, ' فذهب كل الشعب ليأكلوا ويشربوا ويبعثوا أنصبة ويعملوا فرحا عظيما ، لأنهم فهموا الكلام الذي علموهم إياه '),
(26796, 'Nehemiah', 16, 8, 13, ' وفي اليوم الثاني اجتمع رؤوس آباء جميع الشعب ، والكهنة واللاويون ، إلى عزرا الكاتب ليفهمهم كلام الشريعة '),
(26797, 'Nehemiah', 16, 8, 14, ' فوجدوا مكتوبا في الشريعة التي أمر بها الرب عن يد موسى أن بني إسرائيل يسكنون في مظال في العيد في الشهر السابع '),
(26798, 'Nehemiah', 16, 8, 15, ' وأن يسمعوا وينادوا في كل مدنهم وفي أورشليم قائلين : اخرجوا إلى الجبل وأتوا بأغصان زيتون وأغصان زيتون بري وأغصان آس وأغصان نخل وأغصان أشجار غبياء لعمل مظال ، كما هو مكتوب '),
(26799, 'Nehemiah', 16, 8, 16, ' فخرج الشعب وجلبوا وعملوا لأنفسهم مظال ، كل واحد على سطحه ، وفي دورهم ، ودور بيت الله ، وفي ساحة باب الماء ، وفي ساحة باب أفرايم '),
(26800, 'Nehemiah', 16, 8, 17, ' وعمل كل الجماعة الراجعين من السبي مظال ، وسكنوا في المظال ، لأنه لم يعمل بنو إسرائيل هكذا من أيام يشوع بن نون إلى ذلك اليوم ، وكان فرح عظيم جدا '),
(26801, 'Nehemiah', 16, 8, 18, ' وكان يقرأ في سفر شريعة الله يوما فيوما من اليوم الأول إلى اليوم الأخير . وعملوا عيدا سبعة أيام ، وفي اليوم الثامن اعتكاف حسب المرسوم '),
(26802, 'Nehemiah', 16, 9, 1, ' وفي اليوم الرابع والعشرين من هذا الشهر اجتمع بنو إسرائيل بالصوم ، وعليهم مسوح وتراب '),
(26803, 'Nehemiah', 16, 9, 2, ' وانفصل نسل إسرائيل من جميع بني الغرباء ، ووقفوا واعترفوا بخطاياهم وذنوب آبائهم '),
(26804, 'Nehemiah', 16, 9, 3, ' وأقاموا في مكانهم وقرأوا في سفر شريعة الرب إلههم ربع النهار ، وفي الربع الآخر كانوا يحمدون ويسجدون للرب إلههم '),
(26805, 'Nehemiah', 16, 9, 4, ' ووقف على درج اللاويين : يشوع وباني وقدميئيل وشبنيا وبني وشربيا وباني وكناني ، وصرخوا بصوت عظيم إلى الرب إلههم '),
(26806, 'Nehemiah', 16, 9, 5, ' وقال اللاويون : يشوع وقدميئيل وباني وحشبنيا وشربيا وهوديا وشبنيا وفتحيا : قوموا باركوا الرب إلهكم من الأزل إلى الأبد ، وليتبارك اسم جلالك المتعالي على كل بركة وتسبيح '),
(26807, 'Nehemiah', 16, 9, 6, ' أنت هو الرب وحدك . أنت صنعت السماوات وسماء السماوات وكل جندها ، والأرض وكل ما عليها ، والبحار وكل ما فيها ، وأنت تحييها كلها . وجند السماء لك يسجد '),
(26808, 'Nehemiah', 16, 9, 7, ' أنت هو الرب الإله الذي اخترت أبرام وأخرجته من أور الكلدانيين وجعلت اسمه إبراهيم '),
(26809, 'Nehemiah', 16, 9, 8, ' ووجدت قلبه أمينا أمامك ، وقطعت معه العهد أن تعطيه أرض الكنعانيين والحثيين والأموريين والفرزيين واليبوسيين والجرجاشيين وتعطيها لنسله . وقد أنجزت وعدك لأنك صادق '),
(26810, 'Nehemiah', 16, 9, 9, ' ورأيت ذل آبائنا في مصر ، وسمعت صراخهم عند بحر سوف '),
(26811, 'Nehemiah', 16, 9, 10, ' وأظهرت آيات وعجائب على فرعون وعلى جميع عبيده وعلى كل شعب أرضه ، لأنك علمت أنهم بغوا عليهم ، وعملت لنفسك اسما كهذا اليوم '),
(26812, 'Nehemiah', 16, 9, 11, ' وفلقت اليم أمامهم ، وعبروا في وسط البحر على اليابسة ، وطرحت مطارديهم في الأعماق كحجر في مياه قوية '),
(26813, 'Nehemiah', 16, 9, 12, ' وهديتهم بعمود سحاب نهارا ، وبعمود نار ليلا لتضيء لهم في الطريق التي يسيرون فيها '),
(26814, 'Nehemiah', 16, 9, 13, ' ونزلت على جبل سيناء ، وكلمتهم من السماء ، وأعطيتهم أحكاما مستقيمة وشرائع صادقة ، فرائض ووصايا صالحة '),
(26815, 'Nehemiah', 16, 9, 14, ' وعرفتهم سبتك المقدس ، وأمرتهم بوصايا وفرائض وشرائع عن يد موسى عبدك '),
(26816, 'Nehemiah', 16, 9, 15, ' وأعطيتهم خبزا من السماء لجوعهم ، وأخرجت لهم ماء من الصخرة لعطشهم ، وقلت لهم أن يدخلوا ويرثوا الأرض التي رفعت يدك أن تعطيهم إياها '),
(26817, 'Nehemiah', 16, 9, 16, ' ولكنهم بغوا هم وآباؤنا ، وصلبوا رقابهم ولم يسمعوا لوصاياك '),
(26818, 'Nehemiah', 16, 9, 17, ' وأبوا الاستماع ، ولم يذكروا عجائبك التي صنعت معهم ، وصلبوا رقابهم . وعند تمردهم أقاموا رئيسا ليرجعوا إلى عبوديتهم . وأنت إله غفور وحنان ورحيم ، طويل الروح وكثير الرحمة ، فلم تتركهم '),
(26819, 'Nehemiah', 16, 9, 18, ' مع أنهم عملوا لأنفسهم عجلا مسبوكا وقالوا : هذا إلهك الذي أخرجك من مصر ، وعملوا إهانة عظيمة '),
(26820, 'Nehemiah', 16, 9, 19, ' أنت برحمتك الكثيرة لم تتركهم في البرية ، ولم يزل عنهم عمود السحاب نهارا لهدايتهم في الطريق ، ولا عمود النار ليلا ليضيء لهم في الطريق التي يسيرون فيها '),
(26821, 'Nehemiah', 16, 9, 20, ' وأعطيتهم روحك الصالح لتعليمهم ، ولم تمنع منك عن أفواههم ، وأعطيتهم ماء لعطشهم '),
(26822, 'Nehemiah', 16, 9, 21, ' وعلتهم أربعين سنة في البرية فلم يحتاجوا . لم تبل ثيابهم ، ولم تتورم أرجلهم '),
(26823, 'Nehemiah', 16, 9, 22, ' وأعطيتهم ممالك وشعوبا ، وفرقتهم إلى جهات ، فامتلكوا أرض سيحون ، وأرض ملك حشبون ، وأرض عوج ملك باشان '),
(26824, 'Nehemiah', 16, 9, 23, ' وأكثرت بنيهم كنجوم السماء ، وأتيت بهم إلى الأرض التي قلت لآبائهم أن يدخلوا ويرثوها '),
(26825, 'Nehemiah', 16, 9, 24, ' فدخل البنون وورثوا الأرض ، وأخضعت لهم سكان أرض الكنعانيين ، ودفعتهم ليدهم مع ملوكهم وشعوب الأرض ليعملوا بهم حسب إرادتهم '),
(26826, 'Nehemiah', 16, 9, 25, ' وأخذوا مدنا حصينة وأرضا سمينة ، وورثوا بيوتا ملآنة كل خير ، وآبارا محفورة وكروما وزيتونا وأشجارا مثمرة بكثرة ، فأكلوا وشبعوا وسمنوا وتلذذوا بخيرك العظيم '),
(26827, 'Nehemiah', 16, 9, 26, ' وعصوا وتمردوا عليك ، وطرحوا شريعتك وراء ظهورهم ، وقتلوا أنبياءك الذين أشهدوا عليهم ليردوهم إليك ، وعملوا إهانة عظيمة '),
(26828, 'Nehemiah', 16, 9, 27, ' فدفعتهم ليد مضايقيهم فضايقوهم . وفي وقت ضيقهم صرخوا إليك ، وأنت من السماء سمعت ، وحسب مراحمك الكثيرة أعطيتهم مخلصين خلصوهم من يد مضايقيهم '),
(26829, 'Nehemiah', 16, 9, 28, ' ولكن لما استراحوا رجعوا إلى عمل الشر قدامك ، فتركتهم بيد أعدائهم ، فتسلطوا عليهم ثم رجعوا وصرخوا إليك ، وأنت من السماء سمعت وأنقذتهم حسب مراحمك الكثيرة أحيانا كثيرة '),
(26830, 'Nehemiah', 16, 9, 29, ' وأشهدت عليهم لتردهم إلى شريعتك ، وأما هم فبغوا ولم يسمعوا لوصاياك وأخطأوا ضد أحكامك ، التي إذا عملها إنسان يحيا بها . وأعطوا كتفا معاندة ، وصلبوا رقابهم ولم يسمعوا '),
(26831, 'Nehemiah', 16, 9, 30, ' فاحتملتهم سنين كثيرة ، وأشهدت عليهم بروحك عن يد أنبيائك فلم يصغوا ، فدفعتهم ليد شعوب الأراضي '),
(26832, 'Nehemiah', 16, 9, 31, ' ولكن لأجل مراحمك الكثيرة لم تفنهم ولم تتركهم ، لأنك إله حنان ورحيم '),
(26833, 'Nehemiah', 16, 9, 32, ' والآن يا إلهنا ، الإله العظيم الجبار المخوف ، حافظ العهد والرحمة ، لا تصغر لديك كل المشقات التي أصابتنا نحن وملوكنا ورؤساءنا وكهنتنا وأنبياءنا وآباءنا وكل شعبك ، من أيام ملوك أشور إلى هذا اليوم '),
(26834, 'Nehemiah', 16, 9, 33, ' وأنت بار في كل ما أتى علينا لأنك عملت بالحق ، ونحن أذنبنا '),
(26835, 'Nehemiah', 16, 9, 34, ' وملوكنا ورؤساؤنا وكهنتنا وآباؤنا لم يعملوا شريعتك ، ولا أصغوا إلى وصاياك وشهاداتك التي أشهدتها عليهم '),
(26836, 'Nehemiah', 16, 9, 35, ' وهم لم يعبدوك في مملكتهم وفي خيرك الكثير الذي أعطيتهم ، وفي الأرض الواسعة السمينة التي جعلتها أمامهم ، ولم يرجعوا عن أعمالهم الردية '),
(26837, 'Nehemiah', 16, 9, 36, ' ها نحن اليوم عبيد ، والأرض التي أعطيت لآبائنا ليأكلوا أثمارها وخيرها ، ها نحن عبيد فيها '),
(26838, 'Nehemiah', 16, 9, 37, ' وغلاتها كثيرة للملوك الذين جعلتهم علينا لأجل خطايانا ، وهم يتسلطون على أجسادنا وعلى بهائمنا حسب إرادتهم ، ونحن في كرب عظيم '),
(26839, 'Nehemiah', 16, 9, 38, ' ومن أجل كل ذلك نحن نقطع ميثاقا ونكتبه . ورؤساؤنا ولاويونا وكهنتنا يختمون '),
(26840, 'Nehemiah', 16, 10, 1, ' والذين ختموا هم : نحميا الترشاثا ابن حكليا . وصدقيا '),
(26841, 'Nehemiah', 16, 10, 2, ' وسرايا وعزريا ويرميا '),
(26842, 'Nehemiah', 16, 10, 3, ' وفشحور وأمريا وملكيا '),
(26843, 'Nehemiah', 16, 10, 4, ' وحطوش وشبنيا وملوخ '),
(26844, 'Nehemiah', 16, 10, 5, ' وحاريم ومريموث وعوبديا '),
(26845, 'Nehemiah', 16, 10, 6, ' ودانيآل وجنثون وباروخ '),
(26846, 'Nehemiah', 16, 13, 2, ' لأنهم لم يلاقوا بني إسرائيل بالخبز والماء ، بل استأجروا عليهم بلعام لكي يلعنهم ، وحول إلهنا اللعنة إلى بركة '),
(26847, 'Nehemiah', 16, 13, 3, ' ولما سمعوا الشريعة فرزوا كل اللفيف من إسرائيل '),
(26848, 'Nehemiah', 16, 13, 4, ' وقبل هذا كان ألياشيب الكاهن المقام على مخدع بيت إلهنا قرابة طوبيا '),
(26849, 'Nehemiah', 16, 13, 5, ' قد هيأ له مخدعا عظيما حيث كانوا سابقا يضعون التقدمات والبخور والآنية ، وعشر القمح والخمر والزيت ، فريضة اللاويين والمغنين والبوابين ، ورفيعة الكهنة '),
(26850, 'Nehemiah', 16, 13, 6, ' وفي كل هذا لم أكن في أورشليم ، لأني في السنة الاثنتين والثلاثين لأرتحشستا ملك بابل دخلت إلى الملك ، وبعد أيام استأذنت من الملك '),
(26851, 'Nehemiah', 16, 13, 7, ' وأتيت إلى أورشليم . وفهمت الشر الذي عمله ألياشيب لأجل طوبيا ، بعمله له مخدعا في ديار بيت الله '),
(26852, 'Nehemiah', 16, 13, 8, ' وساءني الأمر جدا ، وطرحت جميع آنية بيت طوبيا خارج المخدع '),
(26853, 'Nehemiah', 16, 13, 9, ' وأمرت فطهروا المخادع ، ورددت إليها آنية بيت الله مع التقدمة والبخور '),
(26854, 'Nehemiah', 16, 13, 10, ' وعلمت أن أنصبة اللاويين لم تعط ، بل هرب اللاويون والمغنون عاملو العمل ، كل واحد إلى حقله '),
(26855, 'Nehemiah', 16, 13, 11, ' فخاصمت الولاة وقلت : لماذا ترك بيت الله ؟  . فجمعتهم وأوقفتهم في أماكنهم '),
(26856, 'Nehemiah', 16, 13, 12, ' وأتى كل يهوذا بعشر القمح والخمر والزيت إلى المخازن '),
(26857, 'Nehemiah', 16, 13, 13, ' وأقمت خزنة على الخزائن : شلميا الكاهن وصادوق الكاتب وفدايا من اللاويين ، وبجانبهم حانان بن زكور بن متنيا لأنهم حسبوا أمناء ، وكان عليهم أن يقسموا على إخوتهم '),
(26858, 'Nehemiah', 16, 13, 14, ' اذكرني يا إلهي من أجل هذا ، ولا تمح حسناتي التي عملتها نحو بيت إلهي ونحو شعائره '),
(26859, 'Nehemiah', 16, 13, 15, ' في تلك الأيام رأيت في يهوذا قوما يدوسون معاصر في السبت ، ويأتون بحزم ويحملون حميرا ، وأيضا يدخلون أورشليم في يوم السبت بخمر وعنب وتين وكل ما يحمل ، فأشهدت عليهم يوم بيعهم الطعام '),
(26860, 'Nehemiah', 16, 13, 16, ' والصوريون الساكنون بها كانوا يأتون بسمك وكل بضاعة ، ويبيعون في السبت لبني يهوذا وفي أورشليم '),
(26861, 'Nehemiah', 16, 13, 17, ' فخاصمت عظماء يهوذا وقلت لهم : ما هذا الأمر القبيح الذي تعملونه وتدنسون يوم السبت '),
(26862, 'Nehemiah', 16, 13, 18, ' ألم يفعل آباؤكم هكذا فجلب إلهنا علينا كل هذا الشر ، وعلى هذه المدينة ؟ وأنتم تزيدون غضبا على إسرائيل إذ تدنسون السبت '),
(26863, 'Nehemiah', 16, 13, 19, ' وكان لما أظلمت أبواب أورشليم قبل السبت ، أني أمرت بأن تغلق الأبواب ، وقلت أن لا يفتحوها إلى ما بعد السبت . وأقمت من غلماني على الأبواب حتى لا يدخل حمل في يوم السبت '),
(26864, 'Nehemiah', 16, 13, 20, ' فبات التجار وبائعو كل بضاعة خارج أورشليم مرة واثنتين '),
(26865, 'Nehemiah', 16, 13, 21, ' فأشهدت عليهم وقلت لهم : لماذا أنتم بائتون بجانب السور ؟ إن عدتم فإني ألقي يدا عليكم . ومن ذلك الوقت لم يأتوا في السبت '),
(26866, 'Nehemiah', 16, 13, 22, ' وقلت للاويين أن يتطهروا ويأتوا ويحرسوا الأبواب لأجل تقديس يوم السبت . بهذا أيضا اذكرني يا إلهي ، وترأف علي حسب كثرة رحمتك '),
(26867, 'Nehemiah', 16, 13, 23, ' في تلك الأيام أيضا رأيت اليهود الذين ساكنوا نساء أشدوديات وعمونيات وموآبيات '),
(26868, 'Nehemiah', 16, 13, 24, ' ونصف كلام بنيهم باللسان الأشدودي ، ولم يكونوا يحسنون التكلم باللسان اليهودي ، بل بلسان شعب وشعب '),
(26869, 'Nehemiah', 16, 13, 25, ' فخاصمتهم ولعنتهم وضربت منهم أناسا ونتفت شعورهم ، واستحلفتهم بالله قائلا : لا تعطوا بناتكم لبنيهم ، ولا تأخذوا من بناتهم لبنيكم ، ولا لأنفسكم '),
(26870, 'Nehemiah', 16, 13, 26, ' أليس من أجل هؤلاء أخطأ سليمان ملك إسرائيل ولم يكن في الأمم الكثيرة ملك مثله ؟ وكان محبوبا إلى إلهه ، فجعله الله ملكا على كل إسرائيل . هو أيضا جعلته النساء الأجنبيات يخطئ '),
(26871, 'Nehemiah', 16, 13, 27, ' فهل نسكت لكم أن تعملوا كل هذا الشر العظيم بالخيانة ضد إلهنا بمساكنة نساء أجنبيات '),
(26872, 'Nehemiah', 16, 13, 28, ' وكان واحد من بني يوياداع بن ألياشيب الكاهن العظيم صهرا لسنبلط الحوروني ، فطردته من عندي '),
(26873, 'Nehemiah', 16, 13, 29, ' اذكرهم يا إلهي ، لأنهم نجسوا الكهنوت وعهد الكهنوت واللاويين '),
(26874, 'Nehemiah', 16, 13, 30, ' فطهرتهم من كل غريب ، وأقمت حراسات الكهنة واللاويين ، كل واحد على عمله '),
(26875, 'Nehemiah', 16, 13, 31, ' ولأجل قربان الحطب في أزمنة معينة وللباكورات . فاذكرني يا إلهي بالخير '),
(26876, 'Numbers', 4, 6, 5, ' كل أيام نذر افترازه لا يمر موسى على رأسه . إلى كمال الأيام التي انتذر فيها للرب يكون مقدسا ، ويربي خصل شعر رأسه '),
(26877, 'Numbers', 4, 6, 6, ' كل أيام انتذاره للرب لا يأتي إلى جسد ميت '),
(26878, 'Numbers', 4, 6, 7, ' أبوه وأمه وأخوه وأخته لا يتنجس من أجلهم عند موتهم ، لأن انتذار إلهه على رأسه '),
(26879, 'Numbers', 4, 6, 8, ' إنه كل أيام انتذاره مقدس للرب '),
(26880, 'Numbers', 4, 6, 9, ' وإذا مات ميت عنده بغتة على فجأة فنجس رأس انتذاره ، يحلق رأسه يوم طهره . في اليوم السابع يحلقه '),
(26881, 'Numbers', 4, 6, 10, ' وفي اليوم الثامن يأتي بيمامتين أو بفرخي حمام إلى الكاهن إلى باب خيمة الاجتماع '),
(26882, 'Numbers', 4, 6, 11, ' فيعمل الكاهن واحدا ذبيحة خطية ، والآخر محرقة ويكفر عنه ما أخطأ بسبب الميت ، ويقدس رأسه في ذلك اليوم '),
(26883, 'Numbers', 4, 6, 12, ' فمتى نذر للرب أيام انتذاره يأتي بخروف حولي ذبيحة إثم ، وأما الأيام الأولى فتسقط لأنه نجس انتذاره '),
(26884, 'Numbers', 4, 6, 13, ' وهذه شريعة النذير : يوم تكمل أيام انتذاره يؤتى به إلى باب خيمة الاجتماع '),
(26885, 'Numbers', 4, 6, 14, ' فيقرب قربانه للرب خروفا واحدا حوليا صحيحا محرقة ، ونعجة واحدة حولية صحيحة ذبيحة خطية ، وكبشا واحدا صحيحا ذبيحة سلامة '),
(26886, 'Numbers', 4, 6, 15, ' وسل فطير من دقيق أقراصا ملتوتة بزيت ، ورقاق فطير مدهونة بزيت مع تقدمتها وسكائبها '),
(26887, 'Numbers', 4, 6, 16, ' فيقدمها الكاهن أمام الرب ويعمل ذبيحة خطيته ومحرقته '),
(26888, 'Numbers', 4, 6, 17, ' والكبش يعمله ذبيحة سلامة للرب مع سل الفطير ، ويعمل الكاهن تقدمته وسكيبه '),
(26889, 'Numbers', 4, 6, 18, ' ويحلق النذير لدى باب خيمة الاجتماع رأس انتذاره ، ويأخذ شعر رأس انتذاره ويجعله على النار التي تحت ذبيحة السلامة '),
(26890, 'Numbers', 4, 6, 19, ' ويأخذ الكاهن الساعد مسلوقا من الكبش ، وقرص فطير واحدا من السل ، ورقاقة فطير واحدة ، ويجعلها في يدي النذير بعد حلقه شعر انتذاره '),
(26891, 'Numbers', 4, 6, 20, ' ويرددها الكاهن ترديدا أمام الرب . إنه قدس للكاهن مع صدر الترديد وساق الرفيعة . وبعد ذلك يشرب النذير خمرا '),
(26892, 'Numbers', 4, 6, 21, ' هذه شريعة النذير الذي ينذر ، قربانه للرب عن انتذاره فضلا عما تنال يده . حسب نذره الذي نذر كذلك يعمل حسب شريعة انتذاره '),
(26893, 'Numbers', 4, 6, 22, ' وكلم الرب موسى قائلا '),
(26894, 'Numbers', 4, 6, 23, ' كلم هارون وبنيه قائلا : هكذا تباركون بني إسرائيل قائلين لهم '),
(26895, 'Numbers', 4, 6, 24, ' يباركك الرب ويحرسك '),
(26896, 'Numbers', 4, 6, 25, ' يضيء الرب بوجهه عليك ويرحمك '),
(26897, 'Numbers', 4, 6, 26, ' يرفع الرب وجهه عليك ويمنحك سلاما . 27فيجعلون اسمي على بني إسرائيل ، وأنا أباركهم '),
(26898, 'Numbers', 4, 7, 1, ' ويوم فرغ موسى من إقامة المسكن ، ومسحه وقدسه وجميع أمتعته ، والمذبح وجميع أمتعته ومسحها وقدسها '),
(26899, 'Numbers', 4, 7, 2, ' قرب رؤساء إسرائيل ، رؤوس بيوت آبائهم ، هم رؤساء الأسباط الذين وقفوا على المعدودين '),
(26900, 'Numbers', 4, 7, 3, ' أتوا بقرابينهم أمام الرب : ست عجلات مغطاة ، واثني عشر ثورا . لكل رئيسين عجلة ، ولكل واحد ثور ، وقدموها أمام المسكن '),
(26901, 'Numbers', 4, 7, 4, ' فكلم الرب موسى قائلا '),
(26902, 'Numbers', 4, 7, 5, ' خذها منهم فتكون لعمل خدمة خيمة الاجتماع ، وأعطها للاويين ، لكل واحد حسب خدمته '),
(26903, 'Numbers', 4, 7, 6, ' فأخذ موسى العجلات والثيران وأعطاها للاويين '),
(26904, 'Numbers', 4, 7, 7, ' اثنتان من العجلات وأربعة من الثيران أعطاها لبني جرشون حسب خدمتهم '),
(26905, 'Numbers', 4, 7, 8, ' وأربع من العجلات وثمانية من الثيران أعطاها لبني مراري حسب خدمتهم بيد إيثامار بن هارون الكاهن '),
(26906, 'Numbers', 4, 7, 9, ' وأما بنو قهات فلم يعطهم ، لأن خدمة القدس كانت عليهم ، على الأكتاف كانوا يحملون '),
(26907, 'Numbers', 4, 7, 10, ' وقرب الرؤساء لتدشين المذبح يوم مسحه . وقدم الرؤساء قرابينهم أمام المذبح '),
(26908, 'Numbers', 4, 7, 11, ' فقال الرب لموسى : رئيسا رئيسا في كل يوم يقربون قرابينهم لتدشين المذبح '),
(26909, 'Numbers', 4, 7, 12, ' والذي قرب قربانه في اليوم الأول نحشون بن عميناداب ، من سبط يهوذا '),
(26910, 'Numbers', 4, 7, 13, ' وقربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26911, 'Numbers', 4, 7, 14, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26912, 'Numbers', 4, 7, 15, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26913, 'Numbers', 4, 7, 16, ' وتيس واحد من المعز لذبيحة خطية '),
(26914, 'Numbers', 4, 7, 17, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان نحشون بن عميناداب '),
(26915, 'Numbers', 4, 7, 18, ' وفي اليوم الثاني قرب نثنائيل بن صوغر رئيس يساكر '),
(26916, 'Numbers', 4, 7, 19, ' قرب قربانه طبقا واحدا من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعين شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26917, 'Numbers', 4, 7, 20, ' وصحنا واحدا عشرة شواقل من ذهب مملوا بخورا '),
(26918, 'Numbers', 4, 7, 21, ' وثورا واحدا ابن بقر وكبشا واحدا وخروفا واحدا حوليا لمحرقة '),
(26919, 'Numbers', 4, 7, 22, ' وتيسا واحدا من المعز لذبيحة خطية '),
(26920, 'Numbers', 4, 7, 23, ' ولذبيحة السلامة ثورين وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان نثنائيل بن صوغر '),
(26921, 'Numbers', 4, 7, 24, ' وفي اليوم الثالث رئيس بني زبولون أليآب بن حيلون '),
(26922, 'Numbers', 4, 7, 25, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26923, 'Numbers', 4, 7, 26, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26924, 'Numbers', 4, 7, 27, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26925, 'Numbers', 4, 7, 28, ' وتيس واحد من المعز لذبيحة خطية '),
(26926, 'Numbers', 4, 7, 29, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان أليآب بن حيلون '),
(26927, 'Numbers', 4, 7, 30, ' وفي اليوم الرابع رئيس بني رأوبين أليصور بن شديئور '),
(26928, 'Numbers', 4, 7, 31, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26929, 'Numbers', 4, 7, 32, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26930, 'Numbers', 4, 7, 33, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26931, 'Numbers', 4, 7, 34, ' وتيس واحد من المعز لذبيحة خطية '),
(26932, 'Numbers', 4, 7, 35, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان أليصور بن شديئور '),
(26933, 'Numbers', 4, 7, 36, ' وفي اليوم الخامس رئيس بني شمعون شلوميئيل بن صوريشداي '),
(26934, 'Numbers', 4, 7, 37, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26935, 'Numbers', 4, 7, 38, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26936, 'Numbers', 4, 7, 39, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26937, 'Numbers', 4, 7, 40, ' وتيس واحد من المعز لذبيحة خطية '),
(26938, 'Numbers', 4, 7, 41, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان شلوميئيل بن صوريشداي '),
(26939, 'Numbers', 4, 7, 42, ' وفي اليوم السادس رئيس بني جاد ألياساف بن دعوئيل ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(26940, 'Numbers', 4, 7, 43, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26941, 'Numbers', 4, 7, 44, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26942, 'Numbers', 4, 7, 45, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26943, 'Numbers', 4, 7, 46, ' وتيس واحد من المعز لذبيحة خطية '),
(26944, 'Numbers', 4, 7, 47, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان ألياساف بن دعوئيل '),
(26945, 'Numbers', 4, 7, 48, ' وفي اليوم السابع رئيس بني أفرايم أليشمع بن عميهود '),
(26946, 'Numbers', 4, 7, 49, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26947, 'Numbers', 4, 7, 50, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26948, 'Numbers', 4, 7, 51, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26949, 'Numbers', 4, 7, 52, ' وتيس واحد من المعز لذبيحة خطية '),
(26950, 'Numbers', 4, 7, 53, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان أليشمع بن عميهود '),
(26951, 'Numbers', 4, 7, 54, ' وفي اليوم الثامن رئيس بني منسى جمليئيل بن فدهصور '),
(26952, 'Numbers', 4, 7, 55, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26953, 'Numbers', 4, 7, 56, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26954, 'Numbers', 4, 7, 57, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26955, 'Numbers', 4, 7, 58, ' وتيس واحد من المعز لذبيحة خطية '),
(26956, 'Numbers', 4, 7, 59, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان جمليئيل بن فدهصور '),
(26957, 'Numbers', 4, 7, 60, ' وفي اليوم التاسع رئيس بني بنيامين أبيدن بن جدعوني '),
(26958, 'Numbers', 4, 7, 61, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26959, 'Numbers', 4, 7, 62, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26960, 'Numbers', 4, 7, 63, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26961, 'Numbers', 4, 7, 64, ' وتيس واحد من المعز لذبيحة خطية '),
(26962, 'Numbers', 4, 7, 65, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان أبيدن بن جدعوني '),
(26963, 'Numbers', 4, 7, 66, ' وفي اليوم العاشر رئيس بني دان أخيعزر بن عميشداي '),
(26964, 'Numbers', 4, 7, 67, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26965, 'Numbers', 4, 7, 68, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26966, 'Numbers', 4, 7, 69, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26967, 'Numbers', 4, 7, 70, ' وتيس واحد من المعز لذبيحة خطية '),
(26968, 'Numbers', 4, 7, 71, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان أخيعزر بن عميشداي '),
(26969, 'Numbers', 4, 7, 72, ' وفي اليوم الحادي عشر رئيس بني أشير فجعيئيل بن عكرن '),
(26970, 'Numbers', 4, 7, 73, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26971, 'Numbers', 4, 7, 74, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26972, 'Numbers', 4, 7, 75, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26973, 'Numbers', 4, 7, 76, ' وتيس واحد من المعز لذبيحة خطية '),
(26974, 'Numbers', 4, 7, 77, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان فجعيئيل بن عكرن '),
(26975, 'Numbers', 4, 7, 78, ' وفي اليوم الثاني عشر رئيس بني نفتالي أخيرع بن عينن '),
(26976, 'Numbers', 4, 7, 79, ' قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ، ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس ، كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة '),
(26977, 'Numbers', 4, 7, 80, ' وصحن واحد عشرة شواقل من ذهب مملوء بخورا '),
(26978, 'Numbers', 4, 7, 81, ' وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة '),
(26979, 'Numbers', 4, 7, 82, ' وتيس واحد من المعز لذبيحة خطية '),
(26980, 'Numbers', 4, 7, 83, ' ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية . هذا قربان أخيرع بن عينن '),
(26981, 'Numbers', 4, 7, 84, ' هذا تدشين المذبح يوم مسحه من رؤساء إسرائيل . أطباق فضة اثنا عشر ، ومناضح فضة اثنتا عشرة ، وصحون ذهب اثنا عشر '),
(26982, 'Numbers', 4, 7, 85, ' كل طبق مئة وثلاثون شاقل فضة ، وكل منضحة سبعون . جميع فضة الآنية ألفان وأربع مئة على شاقل القدس '),
(26983, 'Numbers', 4, 7, 86, ' وصحون الذهب اثنا عشر مملوءة بخورا ، كل صحن عشرة على شاقل القدس . جميع ذهب الصحون مئة وعشرون شاقلا '),
(26984, 'Numbers', 4, 7, 87, ' كل الثيران للمحرقة اثنا عشر ثورا ، والكباش اثنا عشر ، والخراف الحولية اثنا عشر مع تقدمتها ، وتيوس المعز اثنا عشر لذبيحة الخطية '),
(26985, 'Numbers', 4, 7, 88, ' وكل الثيران لذبيحة السلامة أربعة وعشرون ثورا ، والكباش ستون ، والتيوس ستون ، والخراف الحولية ستون . هذا تدشين المذبح بعد مسحه '),
(26986, 'Numbers', 4, 7, 89, ' فلما دخل موسى إلى خيمة الاجتماع ليتكلم معه ، كان يسمع الصوت يكلمه من على الغطاء الذي على تابوت الشهادة من بين الكروبين ، فكلمه '),
(26987, 'Numbers', 4, 8, 1, ' وكلم الرب موسى قائلا '),
(26988, 'Numbers', 4, 8, 2, ' كلم هارون وقل له : متى رفعت السرج فإلى قدام المنارة تضيء السرج السبعة '),
(26989, 'Numbers', 4, 8, 3, ' ففعل هارون هكذا . إلى قدام المنارة رفع سرجها كما أمر الرب موسى '),
(26990, 'Numbers', 4, 8, 4, ' وهذه هي صنعة المنارة : مسحولة من ذهب . حتى ساقها وزهرها هي مسحولة . حسب المنظر الذي أراه الرب موسى هكذا عمل المنارة '),
(26991, 'Numbers', 4, 8, 5, ' وكلم الرب موسى قائلا '),
(26992, 'Numbers', 4, 8, 6, ' خذ اللاويين من بين بني إسرائيل وطهرهم '),
(26993, 'Numbers', 4, 8, 7, ' وهكذا تفعل لهم لتطهيرهم : انضح عليهم ماء الخطية ، وليمروا موسى على كل بشرهم ، ويغسلوا ثيابهم فيتطهروا '),
(26994, 'Numbers', 4, 8, 8, ' ثم يأخذوا ثورا ابن بقر وتقدمته دقيقا ملتوتا بزيت . وثورا آخر ابن بقر تأخذ لذبيحة خطية '),
(26995, 'Numbers', 4, 8, 9, ' فتقدم اللاويين أمام خيمة الاجتماع ، وتجمع كل جماعة بني إسرائيل '),
(26996, 'Numbers', 4, 8, 10, ' وتقدم اللاويين أمام الرب ، فيضع بنو إسرائيل أيديهم على اللاويين '),
(26997, 'Numbers', 4, 8, 11, ' ويردد هارون اللاويين ترديدا أمام الرب من عند بني إسرائيل فيكونون ليخدموا خدمة الرب '),
(26998, 'Numbers', 4, 8, 12, ' ثم يضع اللاويون أيديهم على رأسي الثورين ، فتقرب الواحد ذبيحة خطية ، والآخر محرقة للرب ، للتكفير عن اللاويين '),
(26999, 'Numbers', 4, 8, 13, ' فتوقف اللاويين أمام هارون وبنيه وترددهم ترديدا للرب '),
(27000, 'Numbers', 4, 8, 14, ' وتفرز اللاويين من بين بني إسرائيل فيكون اللاويون لي '),
(27001, 'Numbers', 4, 8, 15, ' وبعد ذلك يأتي اللاويون ليخدموا خيمة الاجتماع فتطهرهم وترددهم ترديدا '),
(27002, 'Numbers', 4, 8, 16, ' لأنهم موهوبون لي هبة من بين بني إسرائيل . بدل كل فاتح رحم ، بكر كل من بني إسرائيل قد اتخذتهم لي '),
(27003, 'Numbers', 4, 8, 17, ' لأن لي كل بكر في بني إسرائيل من الناس ومن البهائم . يوم ضربت كل بكر في أرض مصر قدستهم لي '),
(27004, 'Numbers', 4, 8, 18, ' فاتخذت اللاويين بدل كل بكر في بني إسرائيل '),
(27005, 'Numbers', 4, 8, 19, ' ووهبت اللاويين هبة لهارون وبنيه من بين بني إسرائيل ، ليخدموا خدمة بني إسرائيل في خيمة الاجتماع ، وللتكفير عن بني إسرائيل ، لكي لا يكون في بني إسرائيل وبأ عند اقتراب بني إسرائيل إلى القدس '),
(27006, 'Numbers', 4, 8, 20, ' ففعل موسى وهارون وكل جماعة بني إسرائيل للاويين حسب كل ما أمر الرب موسى عن اللاويين . هكذا فعل لهم بنو إسرائيل '),
(27007, 'Numbers', 4, 8, 21, ' فتطهر اللاويون وغسلوا ثيابهم ، ورددهم هارون ترديدا أمام الرب ، وكفر عنهم هارون لتطهيرهم '),
(27008, 'Numbers', 4, 8, 22, ' وبعد ذلك أتى اللاويون ليخدموا خدمتهم في خيمة الاجتماع أمام هارون وأمام بنيه ، كما أمر الرب موسى عن اللاويين هكذا فعلوا لهم '),
(27009, 'Numbers', 4, 8, 23, ' وكلم الرب موسى قائلا '),
(27010, 'Numbers', 4, 8, 24, ' هذا ما للاويين : من ابن خمس وعشرين سنة فصاعدا يأتون ليتجندوا أجنادا في خدمة خيمة الاجتماع '),
(27011, 'Numbers', 4, 8, 25, ' ومن ابن خمسين سنة يرجعون من جند الخدمة ولا يخدمون بعد '),
(27012, 'Numbers', 4, 8, 26, ' يوازرون إخوتهم في خيمة الاجتماع لحرس حراسة ، لكن خدمة لا يخدمون . هكذا تعمل للاويين في حراساتهم '),
(27013, 'Numbers', 4, 9, 1, ' وكلم الرب موسى في برية سيناء ، في السنة الثانية لخروجهم من أرض مصر في الشهر الأول قائلا '),
(27014, 'Numbers', 4, 9, 2, ' وليعمل بنو إسرائيل الفصح في وقته '),
(27015, 'Numbers', 4, 9, 3, ' في اليوم الرابع عشر من هذا الشهر بين العشاءين تعملونه في وقته . حسب كل فرائضه وكل أحكامه تعملونه '),
(27016, 'Numbers', 4, 9, 4, ' فكلم موسى بني إسرائيل أن يعملوا الفصح '),
(27017, 'Numbers', 4, 9, 5, ' فعملوا الفصح في الشهر الأول في اليوم الرابع عشر من الشهر بين العشاءين في برية سيناء ، حسب كل ما أمر الرب موسى هكذا فعل بنو إسرائيل '),
(27018, 'Numbers', 4, 15, 23, ' جميع ما أمركم به الرب عن يد موسى ، من اليوم الذي أمر فيه الرب فصاعدا في أجيالكم '),
(27019, 'Numbers', 4, 15, 24, ' فإن عمل خفية عن أعين الجماعة سهوا ، يعمل كل الجماعة ثورا واحدا ابن بقر محرقة لرائحة سرور للرب ، مع تقدمته وسكيبه كالعادة ، وتيسا واحدا من المعز ذبيحة خطية '),
(27020, 'Numbers', 4, 15, 25, ' فيكفر الكاهن عن كل جماعة بني إسرائيل ، فيصفح عنهم لأنه كان سهوا . فإذا أتوا بقربانهم وقودا للرب ، وبذبيحة خطيتهم أمام الرب لأجل سهوهم '),
(27021, 'Numbers', 4, 15, 26, ' يصفح عن كل جماعة بني إسرائيل والغريب النازل بينهم ، لأنه حدث لجميع الشعب بسهو '),
(27022, 'Numbers', 4, 15, 27, ' وإن أخطأت نفس واحدة سهوا ، تقرب عنزا حولية ذبيحة خطية '),
(27023, 'Numbers', 4, 15, 28, ' فيكفر الكاهن عن النفس التي سهت عندما أخطأت بسهو أمام الرب للتكفير عنها ، فيصفح عنها '),
(27024, 'Numbers', 4, 15, 29, ' للوطني في بني إسرائيل وللغريب النازل بينهم تكون شريعة واحدة للعامل بسهو '),
(27025, 'Numbers', 4, 15, 30, ' وأما النفس التي تعمل بيد رفيعة من الوطنيين أو من الغرباء فهي تزدري بالرب . فتقطع تلك النفس من بين شعبها '),
(27026, 'Numbers', 4, 15, 31, ' لأنها احتقرت كلام الرب ونقضت وصيته . قطعا تقطع تلك النفس . ذنبها عليها '),
(27027, 'Numbers', 4, 15, 32, ' ولما كان بنو إسرائيل في البرية وجدوا رجلا يحتطب حطبا في يوم السبت '),
(27028, 'Numbers', 4, 15, 33, ' فقدمه الذين وجدوه يحتطب حطبا إلى موسى وهارون وكل الجماعة '),
(27029, 'Numbers', 4, 15, 34, ' فوضعوه في المحرس لأنه لم يعلن ماذا يفعل به '),
(27030, 'Numbers', 4, 15, 35, ' فقال الرب لموسى : قتلا يقتل الرجل . يرجمه بحجارة كل الجماعة خارج المحلة '),
(27031, 'Numbers', 4, 15, 36, ' فأخرجه كل الجماعة إلى خارج المحلة ورجموه بحجارة ، فمات كما أمر الرب موسى '),
(27032, 'Numbers', 4, 15, 37, ' وكلم الرب موسى قائلا '),
(27033, 'Numbers', 4, 15, 38, ' كلم بني إسرائيل وقل لهم : أن يصنعوا لهم أهدابا في أذيال ثيابهم في أجيالهم ، ويجعلوا على هدب الذيل عصابة من أسمانجوني '),
(27034, 'Numbers', 4, 15, 39, ' فتكون لكم هدبا ، فترونها وتذكرون كل وصايا الرب وتعملونها ، ولا تطوفون وراء قلوبكم وأعينكم التي أنتم فاسقون وراءها '),
(27035, 'Numbers', 4, 15, 40, ' لكي تذكروا وتعملوا كل وصاياي ، وتكونوا مقدسين لإلهكم '),
(27036, 'Numbers', 4, 15, 41, ' أنا الرب إلهكم الذي أخرجكم من أرض مصر ليكون لكم إلها . أنا الرب إلهكم '),
(27037, 'Numbers', 4, 16, 1, ' وأخذ قورح بن يصهار بن قهات بن لاوي ، وداثان وأبيرام ابنا أليآب ، وأون بن فالت ، بنو رأوبين '),
(27038, 'Numbers', 4, 16, 2, ' يقاومون موسى مع أناس من بني إسرائيل ، مئتين وخمسين رؤساء الجماعة مدعوين للاجتماع ذوي اسم '),
(27039, 'Numbers', 4, 16, 3, ' فاجتمعوا على موسى وهارون وقالوا لهما : كفاكما إن كل الجماعة بأسرها مقدسة وفي وسطها الرب . فما بالكما ترتفعان على جماعة الرب '),
(27040, 'Numbers', 4, 16, 4, ' فلما سمع موسى سقط على وجهه '),
(27041, 'Numbers', 4, 16, 5, ' ثم كلم قورح وجميع قومه قائلا : غدا يعلن الرب من هو له ، ومن المقدس حتى يقربه إليه . فالذي يختاره يقربه إليه '),
(27042, 'Numbers', 4, 16, 6, ' افعلوا هذا : خذوا لكم مجامر . قورح وكل جماعته '),
(27043, 'Numbers', 4, 16, 7, ' واجعلوا فيها نارا ، وضعوا عليها بخورا أمام الرب غدا . فالرجل الذي يختاره الرب هو المقدس . كفاكم يا بني لاوي '),
(27044, 'Numbers', 4, 16, 8, ' وقال موسى لقورح : اسمعوا يا بني لاوي '),
(27045, 'Numbers', 4, 16, 9, ' أقليل عليكم أن إله إسرائيل أفرزكم من جماعة إسرائيل ليقربكم إليه لكي تعملوا خدمة مسكن الرب ، وتقفوا قدام الجماعة لخدمتها '),
(27046, 'Numbers', 4, 16, 10, ' فقربك وجميع إخوتك بني لاوي معك ، وتطلبون أيضا كهنوتا '),
(27047, 'Numbers', 4, 16, 11, ' إذن أنت وكل جماعتك متفقون على الرب . وأما هارون فما هو حتى تتذمروا عليه '),
(27048, 'Numbers', 4, 16, 12, ' فأرسل موسى ليدعو داثان وأبيرام ابني أليآب . فقالا : لا نصعد '),
(27049, 'Numbers', 4, 16, 13, ' أقليل أنك أصعدتنا من أرض تفيض لبنا وعسلا لتميتنا في البرية حتى تترأس علينا ترؤسا '),
(27050, 'Numbers', 4, 16, 14, ' كذلك لم تأت بنا إلى أرض تفيض لبنا وعسلا ، ولا أعطيتنا نصيب حقول وكروم . هل تقلع أعين هؤلاء القوم ؟ لا نصعد '),
(27051, 'Numbers', 4, 16, 15, ' فاغتاظ موسى جدا وقال للرب : لا تلتفت إلى تقدمتهما . حمارا واحدا لم آخذ منهم ، ولا أسأت إلى أحد منهم '),
(27052, 'Numbers', 4, 16, 16, ' وقال موسى لقورح : كن أنت وكل جماعتك أمام الرب ، أنت وهم وهارون غدا '),
(27053, 'Numbers', 4, 16, 17, ' وخذوا كل واحد مجمرته ، واجعلوا فيها بخورا ، وقدموا أمام الرب كل واحد مجمرته . مئتين وخمسين مجمرة . وأنت وهارون كل واحد مجمرته '),
(27054, 'Numbers', 4, 16, 18, ' فأخذوا كل واحد مجمرته وجعلوا فيها نارا ووضعوا عليها بخورا ، ووقفوا لدى باب خيمة الاجتماع مع موسى وهارون '),
(27055, 'Numbers', 4, 16, 19, ' وجمع عليهما قورح كل الجماعة إلى باب خيمة الاجتماع ، فتراءى مجد الرب لكل الجماعة '),
(27056, 'Numbers', 4, 16, 20, ' وكلم الرب موسى وهارون قائلا '),
(27057, 'Numbers', 4, 16, 21, ' افترزا من بين هذه الجماعة فإني أفنيهم في لحظة '),
(27058, 'Numbers', 4, 16, 22, ' فخرا على وجهيهما وقالا : اللهم ، إله أرواح جميع البشر ، هل يخطئ رجل واحد فتسخط على كل الجماعة '),
(27059, 'Numbers', 4, 16, 23, ' فكلم الرب موسى قائلا '),
(27060, 'Numbers', 4, 16, 24, ' كلم الجماعة قائلا : اطلعوا من حوالي مسكن قورح وداثان وأبيرام '),
(27061, 'Numbers', 4, 16, 25, ' فقام موسى وذهب إلى داثان وأبيرام ، وذهب وراءه شيوخ إسرائيل '),
(27062, 'Numbers', 4, 16, 26, ' فكلم الجماعة قائلا : اعتزلوا عن خيام هؤلاء القوم البغاة ، ولا تمسوا شيئا مما لهم لئلا تهلكوا بجميع خطاياهم '),
(27063, 'Numbers', 4, 16, 27, ' فطلعوا من حوالي مسكن قورح وداثان وأبيرام ، وخرج داثان وأبيرام ووقفا في باب خيمتيهما مع نسائهما وبنيهما وأطفالهما '),
(27064, 'Numbers', 4, 16, 28, ' فقال موسى : بهذا تعلمون أن الرب قد أرسلني لأعمل كل هذه الأعمال ، وأنها ليست من نفسي '),
(27065, 'Numbers', 4, 16, 29, ' إن مات هؤلاء كموت كل إنسان ، وأصابتهم مصيبة كل إنسان ، فليس الرب قد أرسلني '),
(27066, 'Numbers', 4, 16, 30, ' ولكن إن ابتدع الرب بدعة وفتحت الأرض فاها وابتلعتهم وكل ما لهم ، فهبطوا أحياء إلى الهاوية ، تعلمون أن هؤلاء القوم قد ازدروا بالرب '),
(27067, 'Numbers', 4, 16, 31, ' فلما فرغ من التكلم بكل هذا الكلام ، انشقت الأرض التي تحتهم '),
(27068, 'Numbers', 4, 16, 32, ' وفتحت الأرض فاها وابتلعتهم وبيوتهم وكل من كان لقورح مع كل الأموال '),
(27069, 'Numbers', 4, 16, 33, ' فنزلوا هم وكل ما كان لهم أحياء إلى الهاوية ، وانطبقت عليهم الأرض ، فبادوا من بين الجماعة '),
(27070, 'Numbers', 4, 16, 34, ' وكل إسرائيل الذين حولهم هربوا من صوتهم ، لأنهم قالوا : لعل الأرض تبتلعنا '),
(27071, 'Numbers', 4, 16, 35, ' وخرجت نار من عند الرب وأكلت المئتين والخمسين رجلا الذين قربوا البخور '),
(27072, 'Numbers', 4, 16, 36, ' ثم كلم الرب موسى قائلا '),
(27073, 'Numbers', 4, 16, 37, ' قل لألعازار بن هارون الكاهن أن يرفع المجامر من الحريق ، واذر النار هناك فإنهن قد تقدسن '),
(27074, 'Numbers', 4, 16, 38, ' مجامر هؤلاء المخطئين ضد نفوسهم ، فليعملوها صفائح مطروقة غشاء للمذبح ، لأنهم قد قدموها أمام الرب فتقدست . فتكون علامة لبني إسرائيل '),
(27075, 'Numbers', 4, 16, 39, ' فأخذ ألعازار الكاهن مجامر النحاس التي قدمها المحترقون ، وطرقوها غشاء للمذبح '),
(27076, 'Numbers', 4, 16, 40, ' تذكارا لبني إسرائيل ، لكي لا يقترب رجل أجنبي ليس من نسل هارون ليبخر بخورا أمام الرب ، فيكون مثل قورح وجماعته ، كما كلمه الرب عن يد موسى '),
(27077, 'Numbers', 4, 16, 41, ' فتذمر كل جماعة بني إسرائيل في الغد على موسى وهارون قائلين : أنتما قد قتلتما شعب الرب '),
(27078, 'Numbers', 4, 16, 42, ' ولما اجتمعت الجماعة على موسى وهارون انصرفا إلى خيمة الاجتماع وإذا هي قد غطتها السحابة وتراءى مجد الرب '),
(27079, 'Numbers', 4, 16, 43, ' فجاء موسى وهارون إلى قدام خيمة الاجتماع '),
(27080, 'Numbers', 4, 16, 44, ' فكلم الرب موسى قائلا '),
(27081, 'Numbers', 4, 16, 45, ' اطلعا من وسط هذه الجماعة ، فإني أفنيهم بلحظة . فخرا على وجهيهما '),
(27082, 'Numbers', 4, 16, 46, ' ثم قال موسى لهارون : خذ المجمرة واجعل فيها نارا من على المذبح ، وضع بخورا ، واذهب بها مسرعا إلى الجماعة وكفر عنهم ، لأن السخط قد خرج من قبل الرب . قد ابتدأ الوبأ '),
(27083, 'Numbers', 4, 16, 47, ' فأخذ هارون كما قال موسى ، وركض إلى وسط الجماعة ، وإذا الوبأ قد ابتدأ في الشعب . فوضع البخور وكفر عن الشعب '),
(27084, 'Numbers', 4, 16, 48, ' ووقف بين الموتى والأحياء فامتنع الوبأ '),
(27085, 'Numbers', 4, 16, 49, ' فكان الذين ماتوا بالوبإ أربعة عشر ألفا وسبع مئة ، عدا الذين ماتوا بسبب قورح '),
(27086, 'Numbers', 4, 16, 50, ' ثم رجع هارون إلى موسى إلى باب خيمة الاجتماع والوبأ قد امتنع '),
(27087, 'Numbers', 4, 17, 1, ' وكلم الرب موسى قائلا '),
(27088, 'Numbers', 4, 17, 2, ' كلم بني إسرائيل وخذ منهم عصا عصا لكل بيت أب من جميع رؤسائهم حسب بيوت آبائهم . اثنتي عشرة عصا . واسم كل واحد تكتبه على عصاه '),
(27089, 'Numbers', 4, 17, 3, ' واسم هارون تكتبه على عصا لاوي ، لأن لرأس بيت آبائهم عصا واحدة '),
(27090, 'Numbers', 4, 17, 4, ' وضعها في خيمة الاجتماع أمام الشهادة حيث أجتمع بكم '),
(27091, 'Numbers', 4, 17, 5, ' فالرجل الذي أختاره تفرخ عصاه ، فأسكن عني تذمرات بني إسرائيل التي يتذمرونها عليكما '),
(27092, 'Numbers', 4, 17, 6, ' فكلم موسى بني إسرائيل ، فأعطاه جميع رؤسائهم عصا عصا لكل رئيس حسب بيوت آبائهم . اثنتي عشرة عصا . وعصا هارون بين عصيهم '),
(27093, 'Numbers', 4, 17, 7, ' فوضع موسى العصي أمام الرب في خيمة الشهادة '),
(27094, 'Numbers', 4, 17, 8, ' وفي الغد دخل موسى إلى خيمة الشهادة ، وإذا عصا هارون لبيت لاوي قد أفرخت . أخرجت فروخا وأزهرت زهرا وأنضجت لوزا '),
(27095, 'Numbers', 4, 17, 9, ' فأخرج موسى جميع العصي من أمام الرب إلى جميع بني إسرائيل ، فنظروا وأخذ كل واحد عصاه '),
(27096, 'Numbers', 4, 17, 10, ' وقال الرب لموسى : رد عصا هارون إلى أمام الشهادة لأجل الحفظ ، علامة لبني التمرد ، فتكف تذمراتهم عني لكي لا يموتوا '),
(27097, 'Numbers', 4, 17, 11, ' ففعل موسى كما أمره الرب . كذلك فعل '),
(27098, 'Numbers', 4, 17, 12, ' فكلم بنو إسرائيل موسى قائلين : إننا فنينا وهلكنا . قد هلكنا جميعا '),
(27099, 'Numbers', 4, 17, 13, ' كل من اقترب إلى مسكن الرب يموت . أما فنينا تماما '),
(27100, 'Numbers', 4, 18, 1, ' وقال الرب لهارون : أنت وبنوك وبيت أبيك معك تحملون ذنب المقدس ، وأنت وبنوك معك تحملون ذنب كهنوتكم '),
(27101, 'Numbers', 4, 18, 2, ' وأيضا إخوتك سبط لاوي ، سبط أبيك ، قربهم معك فيقترنوا بك ويوازروك ، وأنت وبنوك قدام خيمة الشهادة '),
(27102, 'Numbers', 4, 18, 3, ' فيحفظون حراستك وحراسة الخيمة كلها . ولكن إلى أمتعة القدس وإلى المذبح لا يقتربون ، لئلا يموتوا هم وأنتم جميعا '),
(27103, 'Numbers', 4, 18, 4, ' يقترنون بك ويحفظون حراسة خيمة الاجتماع مع كل خدمة الخيمة . والأجنبي لا يقترب إليكم '),
(27104, 'Numbers', 4, 18, 5, ' بل تحفظون أنتم حراسة القدس وحراسة المذبح ، لكي لا يكون أيضا سخط على بني إسرائيل '),
(27105, 'Numbers', 4, 18, 6, ' هأنذا قد أخذت إخوتكم اللاويين من بين بني إسرائيل عطية لكم معطين للرب ، ليخدموا خدمة خيمة الاجتماع '),
(27106, 'Numbers', 4, 18, 7, ' وأما أنت وبنوك معك فتحفظون كهنوتكم مع ما للمذبح وما هو داخل الحجاب ، وتخدمون خدمة . عطية أعطيت كهنوتكم . والأجنبي الذي يقترب يقتل '),
(27107, 'Numbers', 4, 18, 8, ' وقال الرب لهارون : وهأنذا قد أعطيتك حراسة رفائعي ، مع جميع أقداس بني إسرائيل لك أعطيتها ، حق المسحة ولبنيك فريضة دهرية '),
(27108, 'Numbers', 4, 18, 9, ' هذا يكون لك من قدس الأقداس من النار ، كل قرابينهم مع كل تقدماتهم وكل ذبائح خطاياهم وكل ذبائح آثامهم التي يردونها لي . قدس أقداس هي لك ولبنيك '),
(27109, 'Numbers', 4, 18, 10, ' في قدس الأقداس تأكلها . كل ذكر يأكلها . قدسا تكون لك '),
(27110, 'Numbers', 4, 18, 11, ' وهذه لك : الرفيعة من عطاياهم مع كل ترديدات بني إسرائيل . لك أعطيتها ولبنيك وبناتك معك فريضة دهرية . كل طاهر في بيتك يأكل منها '),
(27111, 'Numbers', 4, 18, 12, ' كل دسم الزيت وكل دسم المسطار والحنطة ، أبكارهن التي يعطونها للرب ، لك أعطيتها '),
(27112, 'Numbers', 4, 18, 13, ' أبكار كل ما في أرضهم التي يقدمونها للرب لك تكون . كل طاهر في بيتك يأكلها '),
(27113, 'Numbers', 4, 18, 14, ' كل محرم في إسرائيل يكون لك '),
(27114, 'Numbers', 4, 18, 15, ' كل فاتح رحم من كل جسد يقدمونه للرب ، من الناس ومن البهائم ، يكون لك . غير أنك تقبل فداء بكر الإنسان . وبكر البهيمة النجسة تقبل فداءه '),
(27115, 'Numbers', 4, 18, 16, ' وفداؤه من ابن شهر تقبله حسب تقويمك فضة ، خمسة شواقل على شاقل القدس . هو عشرون جيرة '),
(27116, 'Numbers', 4, 18, 17, ' لكن بكر البقر أو بكر الضأن أو بكر المعز لا تقبل فداءه . إنه قدس . بل ترش دمه على المذبح ، وتوقد شحمه وقودا رائحة سرور للرب '),
(27117, 'Numbers', 4, 18, 18, ' ولحمه يكون لك ، كصدر الترديد والساق اليمنى يكون لك '),
(27118, 'Numbers', 4, 18, 19, ' جميع رفائع الأقداس التي يرفعها بنو إسرائيل للرب أعطيتها لك ولبنيك وبناتك معك حقا دهريا . ميثاق ملح دهريا أمام الرب لك ولزرعك معك '),
(27119, 'Numbers', 4, 18, 20, ' وقال الرب لهارون : لا تنال نصيبا في أرضهم ، ولا يكون لك قسم في وسطهم . أنا قسمك ونصيبك في وسط بني إسرائيل '),
(27120, 'Numbers', 4, 18, 21, ' وأما بنو لاوي ، فإني قد أعطيتهم كل عشر في إسرائيل ميراثا عوض خدمتهم التي يخدمونها ، خدمة خيمة الاجتماع '),
(27121, 'Numbers', 4, 18, 22, ' فلا يقترب أيضا بنو إسرائيل إلى خيمة الاجتماع ليحملوا خطية للموت '),
(27122, 'Numbers', 4, 18, 23, ' بل اللاويون يخدمون خدمة خيمة الاجتماع ، وهم يحملون ذنبهم فريضة دهرية في أجيالكم . وفي وسط إسرائيل لا ينالون نصيبا '),
(27123, 'Numbers', 4, 18, 24, ' إن عشور بني إسرائيل التي يرفعونها للرب رفيعة قد أعطيتها للاويين نصيبا . لذلك قلت لهم : في وسط بني إسرائيل لا ينالون نصيبا '),
(27124, 'Numbers', 4, 18, 25, ' وكلم الرب موسى قائلا '),
(27125, 'Numbers', 4, 18, 26, ' واللاويون تكلمهم وتقول لهم : متى أخذتم من بني إسرائيل العشر الذي أعطيتكم إياه من عندهم نصيبا لكم ، ترفعون منه رفيعة الرب : عشرا من العشر '),
(27126, 'Numbers', 4, 18, 27, ' فيحسب لكم . إنه رفيعتكم كالحنطة من البيدر ، وكالملء من المعصرة '),
(27127, 'Numbers', 4, 18, 28, ' فهكذا ترفعون أنتم أيضا رفيعة الرب من جميع عشوركم التي تأخذون من بني إسرائيل . تعطون منها رفيعة الرب لهارون الكاهن '),
(27128, 'Numbers', 4, 18, 29, ' من جميع عطاياكم ترفعون كل رفيعة الرب من الكل ، دسمه المقدس منه '),
(27129, 'Numbers', 4, 18, 30, ' وتقول لهم : حين ترفعون دسمه منه يحسب للاويين كمحصول البيدر وكمحصول المعصرة '),
(27130, 'Numbers', 4, 18, 31, ' وتأكلونه في كل مكان أنتم وبيوتكم ، لأنه أجرة لكم عوض خدمتكم في خيمة الاجتماع '),
(27131, 'Numbers', 4, 18, 32, ' ولا تتحملون بسببه خطية إذا رفعتم دسمه منه . وأما أقداس بني إسرائيل فلا تدنسوها لئلا تموتوا '),
(27132, 'Numbers', 4, 19, 1, ' وكلم الرب موسى وهارون قائلا '),
(27133, 'Numbers', 4, 19, 2, ' هذه فريضة الشريعة التي أمر بها الرب قائلا : كلم بني إسرائيل أن يأخذوا إليك بقرة حمراء صحيحة لا عيب فيها ، ولم يعل عليها نير '),
(27134, 'Numbers', 4, 19, 3, ' فتعطونها لألعازار الكاهن ، فتخرج إلى خارج المحلة وتذبح قدامه '),
(27135, 'Numbers', 4, 19, 4, ' ويأخذ ألعازار الكاهن من دمها بإصبعه وينضح من دمها إلى جهة وجه خيمة الاجتماع سبع مرات '),
(27136, 'Numbers', 4, 19, 5, ' وتحرق البقرة أمام عينيه . يحرق جلدها ولحمها ودمها مع فرثها '),
(27137, 'Numbers', 4, 19, 6, ' ويأخذ الكاهن خشب أرز وزوفا وقرمزا ويطرحهن في وسط حريق البقرة '),
(27138, 'Numbers', 4, 19, 7, ' ثم يغسل الكاهن ثيابه ويرحض جسده بماء ، وبعد ذلك يدخل المحلة . ويكون الكاهن نجسا إلى المساء '),
(27139, 'Numbers', 4, 19, 8, ' والذي أحرقها يغسل ثيابه بماء ويرحض جسده بماء ويكون نجسا إلى المساء '),
(27140, 'Numbers', 4, 19, 9, ' ويجمع رجل طاهر رماد البقرة ويضعه خارج المحلة في مكان طاهر ، فتكون لجماعة بني إسرائيل في حفظ ، ماء نجاسة . إنها ذبيحة خطية '),
(27141, 'Numbers', 4, 19, 10, ' والذي جمع رماد البقرة يغسل ثيابه ويكون نجسا إلى المساء . فتكون لبني إسرائيل وللغريب النازل في وسطهم فريضة دهرية '),
(27142, 'Numbers', 4, 19, 11, ' من مس ميتا ميتة إنسان ما ، يكون نجسا سبعة أيام '),
(27143, 'Numbers', 4, 19, 12, ' يتطهر به في اليوم الثالث ، وفي اليوم السابع يكون طاهرا . وإن لم يتطهر في اليوم الثالث ففي اليوم السابع لا يكون طاهرا '),
(27144, 'Numbers', 4, 19, 13, ' كل من مس ميتا ميتة إنسان قد مات ولم يتطهر ، ينجس مسكن الرب . فتقطع تلك النفس من إسرائيل . لأن ماء النجاسة لم يرش عليها تكون نجسة . نجاستها لم تزل فيها '),
(27145, 'Numbers', 4, 19, 14, ' هذه هي الشريعة : إذا مات إنسان في خيمة ، فكل من دخل الخيمة ، وكل من كان في الخيمة يكون نجسا سبعة أيام '),
(27146, 'Numbers', 4, 19, 15, ' وكل إناء مفتوح ليس عليه سداد بعصابة فإنه نجس '),
(27147, 'Numbers', 4, 19, 16, ' وكل من مس على وجه الصحراء قتيلا بالسيف أو ميتا أو عظم إنسان أو قبرا ، يكون نجسا سبعة أيام '),
(27148, 'Numbers', 4, 19, 17, ' فيأخذون للنجس من غبار حريق ذبيحة الخطية ويجعل عليه ماء حيا في إناء '),
(27149, 'Numbers', 4, 19, 18, ' ويأخذ رجل طاهر زوفا ويغمسها في الماء وينضحه على الخيمة ، وعلى جميع الأمتعة وعلى الأنفس الذين كانوا هناك ، وعلى الذي مس العظم أو القتيل أو الميت أو القبر '),
(27150, 'Numbers', 4, 19, 19, ' ينضح الطاهر على النجس في اليوم الثالث واليوم السابع . ويطهره في اليوم السابع ، فيغسل ثيابه ويرحض بماء ، فيكون طاهرا في المساء '),
(27151, 'Numbers', 4, 19, 20, ' وأما الإنسان الذي يتنجس ولا يتطهر ، فتباد تلك النفس من بين الجماعة لأنه نجس مقدس الرب . ماء النجاسة لم يرش عليه . إنه نجس '),
(27152, 'Numbers', 4, 19, 21, ' فتكون لهم فريضة دهرية . والذي رش ماء النجاسة يغسل ثيابه ، والذي مس ماء النجاسة يكون نجسا إلى المساء '),
(27153, 'Numbers', 4, 19, 22, ' وكل ما مسه النجس يتنجس ، والنفس التي تمس تكون نجسة إلى المساء '),
(27154, 'Numbers', 4, 20, 1, ' وأتى بنو إسرائيل ، الجماعة كلها ، إلى برية صين في الشهر الأول . وأقام الشعب في قادش . وماتت هناك مريم ودفنت هناك '),
(27155, 'Numbers', 4, 20, 2, ' ولم يكن ماء للجماعة فاجتمعوا على موسى وهارون '),
(27156, 'Numbers', 4, 20, 3, ' وخاصم الشعب موسى وكلموه قائلين : ليتنا فنينا فناء إخوتنا أمام الرب '),
(27157, 'Numbers', 4, 20, 4, ' لماذا أتيتما بجماعة الرب إلى هذه البرية لكي نموت فيها نحن ومواشينا '),
(27158, 'Numbers', 4, 20, 5, ' ولماذا أصعدتمانا من مصر لتأتيا بنا إلى هذا المكان الرديء ؟ ليس هو مكان زرع وتين وكرم ورمان ، ولا فيه ماء للشرب '),
(27159, 'Numbers', 4, 20, 6, ' فأتى موسى وهارون من أمام الجماعة إلى باب خيمة الاجتماع وسقطا على وجهيهما ، فتراءى لهما مجد الرب '),
(27160, 'Numbers', 4, 20, 7, ' وكلم الرب موسى قائلا '),
(27161, 'Numbers', 4, 20, 8, ' خذ العصا واجمع الجماعة أنت وهارون أخوك ، وكلما الصخرة أمام أعينهم أن تعطي ماءها ، فتخرج لهم ماء من الصخرة وتسقي الجماعة ومواشيهم '),
(27162, 'Numbers', 4, 20, 9, ' فأخذ موسى العصا من أمام الرب كما أمره '),
(27163, 'Numbers', 4, 20, 10, ' وجمع موسى وهارون الجمهور أمام الصخرة ، فقال لهم : اسمعوا أيها المردة ، أمن هذه الصخرة نخرج لكم ماء '),
(27164, 'Numbers', 4, 20, 11, ' ورفع موسى يده وضرب الصخرة بعصاه مرتين ، فخرج ماء غزير ، فشربت الجماعة ومواشيها '),
(27165, 'Numbers', 4, 20, 12, ' فقال الرب لموسى وهارون : من أجل أنكما لم تؤمنا بي حتى تقدساني أمام أعين بني إسرائيل ، لذلك لا تدخلان هذه الجماعة إلى الأرض التي أعطيتهم إياها '),
(27166, 'Numbers', 4, 20, 13, ' هذا ماء مريبة ، حيث خاصم بنو إسرائيل الرب ، فتقدس فيهم '),
(27167, 'Numbers', 4, 20, 14, ' وأرسل موسى رسلا من قادش إلى ملك أدوم : هكذا يقول أخوك إسرائيل : قد عرفت كل المشقة التي أصابتنا '),
(27168, 'Numbers', 4, 20, 15, ' إن آباءنا انحدروا إلى مصر ، وأقمنا في مصر أياما كثيرة وأساء المصريون إلينا وإلى آبائنا '),
(27169, 'Numbers', 4, 20, 16, ' فصرخنا إلى الرب فسمع صوتنا ، وأرسل ملاكا وأخرجنا من مصر . وها نحن في قادش ، مدينة في طرف تخومك '),
(27170, 'Numbers', 4, 20, 17, ' دعنا نمر في أرضك . لا نمر في حقل ولا في كرم ، ولا نشرب ماء بئر . في طريق الملك نمشي ، لا نميل يمينا ولا يسارا حتى نتجاوز تخومك '),
(27171, 'Numbers', 4, 20, 18, ' فقال له أدوم : لا تمر بي لئلا أخرج للقائك بالسيف '),
(27172, 'Numbers', 4, 20, 19, ' فقال له بنو إسرائيل : في السكة نصعد ، وإذا شربنا أنا ومواشي من مائك أدفع ثمنه . لا شيء . أمر برجلي فقط '),
(27173, 'Numbers', 4, 20, 20, ' فقال : لا تمر . وخرج أدوم للقائه بشعب غفير وبيد شديدة '),
(27174, 'Numbers', 4, 20, 21, ' وأبى أدوم أن يسمح لإسرائيل بالمرور في تخومه ، فتحول إسرائيل عنه '),
(27175, 'Numbers', 4, 20, 22, ' فارتحل بنو إسرائيل ، الجماعة كلها ، من قادش وأتوا إلى جبل هور '),
(27176, 'Numbers', 4, 20, 23, ' وكلم الرب موسى وهارون في جبل هور على تخم أرض أدوم قائلا '),
(27177, 'Numbers', 4, 20, 24, ' يضم هارون إلى قومه لأنه لا يدخل الأرض التي أعطيت لبني إسرائيل ، لأنكم عصيتم قولي عند ماء مريبة '),
(27178, 'Numbers', 4, 20, 25, ' خذ هارون وألعازار ابنه واصعد بهما إلى جبل هور '),
(27179, 'Numbers', 4, 20, 26, ' واخلع عن هارون ثيابه ، وألبس ألعازار ابنه إياها . فيضم هارون ويموت هناك '),
(27180, 'Numbers', 4, 20, 27, ' ففعل موسى كما أمر الرب ، وصعدوا إلى جبل هور أمام أعين كل الجماعة '),
(27181, 'Numbers', 4, 20, 28, ' فخلع موسى عن هارون ثيابه وألبس ألعازار ابنه إياها . فمات هارون هناك على رأس الجبل ، ثم انحدر موسى وألعازار عن الجبل '),
(27182, 'Numbers', 4, 20, 29, ' فلما رأى كل الجماعة أن هارون قد مات ، بكى جميع بيت إسرائيل على هارون ثلاثين يوما '),
(27183, 'Numbers', 4, 21, 1, ' ولما سمع الكنعاني ملك عراد الساكن في الجنوب أن إسرائيل جاء في طريق أتاريم ، حارب إسرائيل وسبى منهم سبيا '),
(27184, 'Numbers', 4, 21, 2, ' فنذر إسرائيل نذرا للرب وقال : إن دفعت هؤلاء القوم إلى يدي أحرم مدنهم '),
(27185, 'Numbers', 4, 21, 3, ' فسمع الرب لقول إسرائيل ، ودفع الكنعانيين ، فحرموهم ومدنهم . فدعي اسم المكان حرمة '),
(27186, 'Numbers', 4, 21, 4, ' وارتحلوا من جبل هور في طريق بحر سوف ليدوروا بأرض أدوم ، فضاقت نفس الشعب في الطريق '),
(27187, 'Numbers', 4, 21, 5, ' وتكلم الشعب على الله وعلى موسى قائلين : لماذا أصعدتمانا من مصر لنموت في البرية ؟ لأنه لا خبز ولا ماء ، وقد كرهت أنفسنا الطعام السخيف '),
(27188, 'Numbers', 4, 21, 6, ' فأرسل الرب على الشعب الحيات المحرقة ، فلدغت الشعب ، فمات قوم كثيرون من إسرائيل '),
(27189, 'Numbers', 4, 21, 7, ' فأتى الشعب إلى موسى وقالوا : قد أخطأنا إذ تكلمنا على الرب وعليك ، فصل إلى الرب ليرفع عنا الحيات . فصلى موسى لأجل الشعب '),
(27190, 'Numbers', 4, 21, 8, ' فقال الرب لموسى : اصنع لك حية محرقة وضعها على راية ، فكل من لدغ ونظر إليها يحيا '),
(27191, 'Numbers', 4, 21, 9, ' فصنع موسى حية من نحاس ووضعها على الراية ، فكان متى لدغت حية إنسانا ونظر إلى حية النحاس يحيا '),
(27192, 'Numbers', 4, 21, 10, ' وارتحل بنو إسرائيل ونزلوا في أوبوت '),
(27193, 'Numbers', 4, 21, 11, ' وارتحلوا من أوبوت ونزلوا في عيي عباريم في البرية ، التي قبالة موآب إلى شروق الشمس '),
(27194, 'Numbers', 4, 21, 12, ' من هناك ارتحلوا ونزلوا في وادي زارد '),
(27195, 'Numbers', 4, 21, 13, ' من هناك ارتحلوا ونزلوا في عبر أرنون الذي في البرية ، خارجا عن تخم الأموريين . لأن أرنون هو تخم موآب ، بين موآب والأموريين '),
(27196, 'Numbers', 4, 21, 14, ' لذلك يقال في كتاب حروب الرب : واهب في سوفة وأودية أرنون '),
(27197, 'Numbers', 4, 21, 15, ' ومصب الأودية الذي مال إلى مسكن عار ، واستند إلى تخم موآب '),
(27198, 'Numbers', 4, 21, 16, ' ومن هناك إلى بئر . وهي البئر حيث قال الرب لموسى : اجمع الشعب فأعطيهم ماء '),
(27199, 'Numbers', 4, 21, 17, ' حينئذ ترنم إسرائيل بهذا النشيد : اصعدي أيتها البئر أجيبوا لها '),
(27200, 'Numbers', 4, 21, 18, ' بئر حفرها رؤساء ، حفرها شرفاء الشعب ، بصولجان ، بعصيهم . ومن البرية إلى متانة '),
(27201, 'Numbers', 4, 21, 19, ' ومن متانة إلى نحليئيل ، ومن نحليئيل إلى باموت '),
(27202, 'Numbers', 4, 21, 20, ' ومن باموت إلى الجواء التي في صحراء موآب عند رأس الفسجة التي تشرف على وجه البرية '),
(27203, 'Numbers', 4, 21, 21, ' وأرسل إسرائيل رسلا إلى سيحون ملك الأموريين قائلا '),
(27204, 'Numbers', 4, 21, 22, ' دعني أمر في أرضك . لا نميل إلى حقل ولا إلى كرم ولا نشرب ماء بئر . في طريق الملك نمشي حتى نتجاوز تخومك '),
(27205, 'Numbers', 4, 21, 23, ' فلم يسمح سيحون لإسرائيل بالمرور في تخومه ، بل جمع سيحون جميع قومه وخرج للقاء إسرائيل إلى البرية ، فأتى إلى ياهص وحارب إسرائيل '),
(27206, 'Numbers', 4, 21, 24, ' فضربه إسرائيل بحد السيف وملك أرضه من أرنون إلى يبوق إلى بني عمون . لأن تخم بني عمون كان قويا '),
(27207, 'Numbers', 4, 21, 25, ' فأخذ إسرائيل كل هذه المدن ، وأقام إسرائيل في جميع مدن الأموريين في حشبون وفي كل قراها '),
(27208, 'Numbers', 4, 21, 26, ' لأن حشبون كانت مدينة سيحون ملك الأموريين ، وكان قد حارب ملك موآب الأول وأخذ كل أرضه من يده حتى أرنون '),
(27209, 'Numbers', 4, 21, 27, ' لذلك يقول أصحاب الأمثال : ايتوا إلى حشبون فتبنى ، وتصلح مدينة سيحون '),
(27210, 'Numbers', 4, 21, 28, ' لأن نارا خرجت من حشبون ، لهيبا من قرية سيحون . أكلت عار موآب . أهل مرتفعات أرنون '),
(27211, 'Numbers', 4, 21, 29, ' ويل لك يا موآب . هلكت يا أمة كموش . قد صير بنيه هاربين وبناته في السبي لملك الأموريين سيحون '),
(27212, 'Numbers', 4, 21, 30, ' لكن قد رميناهم . هلكت حشبون إلى ديبون . وأخربنا إلى نوفح التي إلى ميدبا '),
(27213, 'Numbers', 4, 21, 31, ' فأقام إسرائيل في أرض الأموريين '),
(27214, 'Numbers', 4, 21, 32, ' وأرسل موسى ليتجسس يعزير ، فأخذوا قراها وطردوا الأموريين الذين هناك '),
(27215, 'Numbers', 4, 21, 33, ' ثم تحولوا وصعدوا في طريق باشان . فخرج عوج ملك باشان للقائهم هو وجميع قومه إلى الحرب في إذرعي '),
(27216, 'Numbers', 4, 21, 34, ' فقال الرب لموسى : لا تخف منه لأني قد دفعته إلى يدك مع جميع قومه وأرضه ، فتفعل به كما فعلت بسيحون ملك الأموريين الساكن في حشبون '),
(27217, 'Numbers', 4, 21, 35, ' فضربوه وبنيه وجميع قومه حتى لم يبق له شارد ، وملكوا أرضه '),
(27218, 'Numbers', 4, 22, 1, ' وارتحل بنو إسرائيل ونزلوا في عربات موآب من عبر أردن أريحا '),
(27219, 'Numbers', 4, 22, 2, ' ولما رأى بالاق بن صفور جميع ما فعل إسرائيل بالأموريين '),
(27220, 'Numbers', 4, 22, 3, ' فزع موآب من الشعب جدا لأنه كثير ، وضجر موآب من قبل بني إسرائيل '),
(27221, 'Numbers', 4, 22, 4, ' فقال موآب لشيوخ مديان : الآن يلحس الجمهور كل ما حولنا كما يلحس الثور خضرة الحقل . وكان بالاق بن صفور ملكا لموآب في ذلك الزمان '),
(27222, 'Numbers', 4, 22, 5, ' فأرسل رسلا إلى بلعام بن بعور ، إلى فتور التي على النهر في أرض بني شعبه ليدعوه قائلا : هوذا شعب قد خرج من مصر . هوذا قد غشى وجه الأرض ، وهو مقيم مقابلي '),
(27223, 'Numbers', 4, 22, 6, ' فالآن تعال والعن لي هذا الشعب ، لأنه أعظم مني ، لعله يمكننا أن نكسره فأطرده من الأرض ، لأني عرفت أن الذي تباركه مبارك والذي تلعنه ملعون '),
(27224, 'Numbers', 4, 22, 7, ' فانطلق شيوخ موآب وشيوخ مديان ، وحلوان العرافة في أيديهم ، وأتوا إلى بلعام وكلموه بكلام بالاق '),
(27225, 'Numbers', 4, 22, 8, ' فقال لهم : بيتوا هنا الليلة فأرد عليكم جوابا كما يكلمني الرب . فمكث رؤساء موآب عند بلعام '),
(27226, 'Numbers', 4, 22, 9, ' فأتى الله إلى بلعام وقال : من هم هؤلاء الرجال الذين عندك '),
(27227, 'Numbers', 4, 22, 10, ' فقال بلعام لله : بالاق بن صفور ملك موآب قد أرسل إلي يقول '),
(27228, 'Numbers', 4, 22, 11, ' هوذا الشعب الخارج من مصر قد غشى وجه الأرض . تعال الآن العن لي إياه ، لعلي أقدر أن أحاربه وأطرده '),
(27229, 'Numbers', 4, 22, 12, ' فقال الله لبلعام : لا تذهب معهم ولا تلعن الشعب ، لأنه مبارك '),
(27230, 'Numbers', 4, 22, 13, ' فقام بلعام صباحا وقال لرؤساء بالاق : انطلقوا إلى أرضكم لأن الرب أبى أن يسمح لي بالذهاب معكم '),
(27231, 'Numbers', 4, 22, 14, ' فقام رؤساء موآب وأتوا إلى بالاق وقالوا : أبى بلعام أن يأتي معنا '),
(27232, 'Numbers', 4, 22, 15, ' فعاد بالاق وأرسل أيضا رؤساء أكثر وأعظم من أولئك '),
(27233, 'Numbers', 4, 22, 16, ' فأتوا إلى بلعام وقالوا له : هكذا قال بالاق بن صفور : لا تمتنع من الإتيان إلي '),
(27234, 'Numbers', 4, 22, 17, ' لأني أكرمك إكراما عظيما ، وكل ما تقول لي أفعله . فتعال الآن العن لي هذا الشعب '),
(27235, 'Numbers', 4, 22, 18, ' فأجاب بلعام وقال لعبيد بالاق : ولو أعطاني بالاق ملء بيته فضة وذهبا لا أقدر أن أتجاوز قول الرب إلهي لأعمل صغيرا أو كبيرا '),
(27236, 'Numbers', 4, 22, 19, ' فالآن امكثوا هنا أنتم أيضا هذه الليلة لأعلم ماذا يعود الرب يكلمني به '),
(27237, 'Numbers', 4, 22, 20, ' فأتى الله إلى بلعام ليلا وقال له : إن أتى الرجال ليدعوك فقم اذهب معهم ، إنما تعمل الأمر الذي أكلمك به فقط '),
(27238, 'Numbers', 4, 22, 21, ' فقام بلعام صباحا وشد على أتانه وانطلق مع رؤساء موآب '),
(27239, 'Numbers', 4, 22, 22, ' فحمي غضب الله لأنه منطلق ، ووقف ملاك الرب في الطريق ليقاومه وهو راكب على أتانه وغلاماه معه '),
(27240, 'Numbers', 4, 22, 23, ' فأبصرت الأتان ملاك الرب واقفا في الطريق وسيفه مسلول في يده ، فمالت الأتان عن الطريق ومشت في الحقل . فضرب بلعام الأتان ليردها إلى الطريق '),
(27241, 'Numbers', 4, 22, 24, ' ثم وقف ملاك الرب في خندق للكروم ، له حائط من هنا وحائط من هناك '),
(27242, 'Numbers', 4, 22, 25, ' فلما أبصرت الأتان ملاك الرب زحمت الحائط ، وضغطت رجل بلعام بالحائط ، فضربها أيضا '),
(27243, 'Numbers', 4, 22, 26, ' ثم اجتاز ملاك الرب أيضا ووقف في مكان ضيق حيث ليس سبيل للنكوب يمينا أو شمالا '),
(27244, 'Numbers', 4, 22, 27, ' فلما أبصرت الأتان ملاك الرب ، ربضت تحت بلعام . فحمي غضب بلعام وضرب الأتان بالقضيب '),
(27245, 'Numbers', 4, 22, 28, ' ففتح الرب فم الأتان ، فقالت لبلعام : ماذا صنعت بك حتى ضربتني الآن ثلاث دفعات '),
(27246, 'Numbers', 4, 22, 29, ' فقال بلعام للأتان : لأنك ازدريت بي . لو كان في يدي سيف لكنت الآن قد قتلتك '),
(27247, 'Numbers', 4, 22, 30, ' فقالت الأتان لبلعام : ألست أنا أتانك التي ركبت عليها منذ وجودك إلى هذا اليوم ؟ هل تعودت أن أفعل بك هكذا ؟ فقال : لا '),
(27248, 'Numbers', 4, 22, 31, ' ثم كشف الرب عن عيني بلعام ، فأبصر ملاك الرب واقفا في الطريق وسيفه مسلول في يده ، فخر ساجدا على وجهه '),
(27249, 'Numbers', 4, 22, 32, ' فقال له ملاك الرب : لماذا ضربت أتانك الآن ثلاث دفعات ؟ هأنذا قد خرجت للمقاومة لأن الطريق ورطة أمامي '),
(27250, 'Numbers', 4, 22, 33, ' فأبصرتني الأتان ومالت من قدامي الآن ثلاث دفعات . ولو لم تمل من قدامي لكنت الآن قد قتلتك واستبقيتها '),
(27251, 'Numbers', 4, 22, 34, ' فقال بلعام لملاك الرب : أخطأت . إني لم أعلم أنك واقف تلقائي في الطريق . والآن إن قبح في عينيك فإني أرجع '),
(27252, 'Numbers', 4, 22, 35, ' فقال ملاك الرب لبلعام : اذهب مع الرجال ، وإنما تتكلم بالكلام الذي أكلمك به فقط . فانطلق '),
(27253, 'Numbers', 4, 22, 36, ' فلما سمع بالاق أن بلعام جاء ، خرج لاستقباله إلى مدينة موآب التي على تخم أرنون الذي في أقصى التخوم '),
(27254, 'Numbers', 4, 22, 37, ' فقال بالاق لبلعام : ألم أرسل إليك لأدعوك ؟ لماذا لم تأت إلي ؟ أحقا لا أقدر أن أكرمك '),
(27255, 'Numbers', 4, 22, 38, ' فقال بلعام لبالاق : هأنذا قد جئت إليك . ألعلي الآن أستطيع أن أتكلم بشيء ؟ الكلام الذي يضعه الله في فمي به أتكلم '),
(27256, 'Numbers', 4, 22, 39, ' فانطلق بلعام مع بالاق وأتيا إلى قرية حصوت '),
(27257, 'Numbers', 4, 22, 40, ' فذبح بالاق بقرا وغنما ، وأرسل إلى بلعام وإلى الرؤساء الذين معه '),
(27258, 'Numbers', 4, 22, 41, ' وفي الصباح أخذ بالاق بلعام وأصعده إلى مرتفعات بعل ، فرأى من هناك أقصى الشعب '),
(27259, 'Numbers', 4, 23, 1, ' فقال بلعام لبالاق : ابن لي ههنا سبعة مذابح وهيئ لي ههنا سبعة ثيران وسبعة كباش '),
(27260, 'Numbers', 4, 23, 2, ' ففعل بالاق كما تكلم بلعام . وأصعد بالاق وبلعام ثورا وكبشا على كل مذبح '),
(27261, 'Numbers', 4, 23, 3, ' فقال بلعام لبالاق : قف عند محرقتك ، فأنطلق أنا لعل الرب يوافي للقائي ، فمهما أراني أخبرك به . ثم انطلق إلى رابية '),
(27262, 'Numbers', 4, 23, 4, ' فوافى الله بلعام ، فقال له : قد رتبت سبعة مذابح وأصعدت ثورا وكبشا على كل مذبح '),
(27263, 'Numbers', 4, 23, 5, ' فوضع الرب كلاما في فم بلعام وقال : ارجع إلى بالاق وتكلم هكذا '),
(27264, 'Numbers', 4, 23, 6, ' فرجع إليه وإذا هو واقف عند محرقته هو ، وجميع رؤساء موآب '),
(27265, 'Numbers', 4, 23, 7, ' فنطق بمثله وقال : من أرام أتى بي بالاق ملك موآب ، من جبال المشرق : تعال العن لي يعقوب ، وهلم اشتم إسرائيل '),
(27266, 'Numbers', 4, 23, 8, ' كيف ألعن من لم يلعنه الله ؟ وكيف أشتم من لم يشتمه الرب '),
(27267, 'Numbers', 4, 23, 9, ' إني من رأس الصخور أراه ، ومن الآكام أبصره . هوذا شعب يسكن وحده ، وبين الشعوب لا يحسب '),
(27268, 'Numbers', 4, 23, 10, ' من أحصى تراب يعقوب وربع إسرائيل بعدد ؟ لتمت نفسي موت الأبرار ، ولتكن آخرتي كآخرتهم '),
(27269, 'Numbers', 4, 23, 11, ' فقال بالاق لبلعام : ماذا فعلت بي ؟ لتشتم أعدائي أخذتك ، وهوذا أنت قد باركتهم '),
(27270, 'Numbers', 4, 23, 12, ' فأجاب وقال : أما الذي يضعه الرب في فمي أحترص أن أتكلم به '),
(27271, 'Numbers', 4, 23, 13, ' فقال له بالاق : هلم معي إلى مكان آخر تراه منه . إنما ترى أقصاءه فقط ، وكله لا ترى . فالعنه لي من هناك '),
(27272, 'Numbers', 4, 23, 14, ' فأخذه إلى حقل صوفيم إلى رأس الفسجة ، وبنى سبعة مذابح ، وأصعد ثورا وكبشا على كل مذبح '),
(27273, 'Numbers', 4, 23, 15, ' فقال لبالاق : قف هنا عند محرقتك وأنا أوافي هناك '),
(27274, 'Numbers', 4, 23, 16, ' فوافى الرب بلعام ووضع كلاما في فمه وقال : ارجع إلى بالاق وتكلم هكذا '),
(27275, 'Numbers', 4, 23, 17, ' فأتى إليه وإذا هو واقف عند محرقته ، ورؤساء موآب معه . فقال له بالاق : ماذا تكلم به الرب '),
(27276, 'Numbers', 4, 23, 18, ' فنطق بمثله وقال : قم يا بالاق واسمع . اصغ إلي يا ابن صفور '),
(27277, 'Numbers', 4, 23, 19, ' ليس الله إنسانا فيكذب ، ولا ابن إنسان فيندم . هل يقول ولا يفعل ؟ أو يتكلم ولا يفي '),
(27278, 'Numbers', 4, 23, 20, ' إني قد أمرت أن أبارك . فإنه قد بارك فلا أرده '),
(27279, 'Numbers', 4, 23, 21, ' لم يبصر إثما في يعقوب ، ولا رأى تعبا في إسرائيل . الرب إلهه معه ، وهتاف ملك فيه '),
(27280, 'Numbers', 4, 23, 22, ' الله أخرجه من مصر . له مثل سرعة الرئم '),
(27281, 'Numbers', 4, 23, 23, ' إنه ليس عيافة على يعقوب ، ولا عرافة على إسرائيل . في الوقت يقال عن يعقوب وعن إسرائيل ما فعل الله '),
(27282, 'Numbers', 4, 23, 24, ' هوذا شعب يقوم كلبوة ، ويرتفع كأسد . لا ينام حتى يأكل فريسة ويشرب دم قتلى '),
(27283, 'Numbers', 4, 23, 25, ' فقال بالاق لبلعام : لا تلعنه لعنة ولا تباركه بركة '),
(27284, 'Numbers', 4, 23, 26, ' فأجاب بلعام وقال لبالاق : ألم أكلمك قائلا : كل ما يتكلم به الرب فإياه أفعل '),
(27285, 'Numbers', 4, 23, 27, ' فقال بالاق لبلعام : هلم آخذك إلى مكان آخر ، عسى أن يصلح في عيني الله أن تلعنه لي من هناك '),
(27286, 'Numbers', 4, 23, 28, ' فأخذ بالاق بلعام إلى رأس فغور المشرف على وجه البرية '),
(27287, 'Numbers', 4, 23, 29, ' فقال بلعام لبالاق : ابن لي ههنا سبعة مذابح ، وهيئ لي ههنا سبعة ثيران وسبعة كباش '),
(27288, 'Numbers', 4, 23, 30, ' ففعل بالاق كما قال بلعام ، وأصعد ثورا وكبشا على كل مذبح '),
(27289, 'Numbers', 4, 24, 1, ' فلما رأى بلعام أنه يحسن في عيني الرب أن يبارك إسرائيل ، لم ينطلق كالمرة الأولى والثانية ليوافي فألا ، بل جعل نحو البرية وجهه '),
(27290, 'Numbers', 4, 24, 2, ' ورفع بلعام عينيه ورأى إسرائيل حالا حسب أسباطه ، فكان عليه روح الله '),
(27291, 'Numbers', 4, 24, 3, ' فنطق بمثله وقال : وحي بلعام بن بعور . وحي الرجل المفتوح العينين '),
(27292, 'Numbers', 4, 24, 4, ' وحي الذي يسمع أقوال الله . الذي يرى رؤيا القدير ، مطروحا وهو مكشوف العينين '),
(27293, 'Numbers', 4, 24, 5, ' ما أحسن خيامك يا يعقوب ، مساكنك يا إسرائيل '),
(27294, 'Numbers', 4, 24, 6, ' كأودية ممتدة . كجنات على نهر ، كشجرات عود غرسها الرب . كأرزات على مياه '),
(27295, 'Numbers', 4, 24, 7, ' يجري ماء من دلائه ، ويكون زرعه على مياه غزيرة ، ويتسامى ملكه على أجاج وترتفع مملكته '),
(27296, 'Numbers', 4, 24, 8, ' الله أخرجه من مصر . له مثل سرعة الرئم . يأكل أمما ، مضايقيه ، ويقضم عظامهم ويحطم سهامه '),
(27297, 'Numbers', 4, 24, 9, ' جثم كأسد . ربض كلبوة . من يقيمه ؟ مباركك مبارك ، ولاعنك ملعون '),
(27298, 'Numbers', 4, 24, 10, ' فاشتعل غضب بالاق على بلعام ، وصفق بيديه وقال بالاق لبلعام : لتشتم أعدائي دعوتك ، وهوذا أنت قد باركتهم الآن ثلاث دفعات '),
(27299, 'Numbers', 4, 24, 11, ' فالآن اهرب إلى مكانك . قلت أكرمك إكراما ، وهوذا الرب قد منعك عن الكرامة '),
(27300, 'Numbers', 4, 24, 12, ' فقال بلعام لبالاق : ألم أكلم أيضا رسلك الذين أرسلت إلي قائلا '),
(27301, 'Numbers', 4, 24, 13, ' ولو أعطاني بالاق ملء بيته فضة وذهبا لا أقدر أن أتجاوز قول الرب لأعمل خيرا أو شرا من نفسي . الذي يتكلمه الرب إياه أتكلم '),
(27302, 'Numbers', 4, 24, 14, ' والآن هوذا أنا منطلق إلى شعبي . هلم أنبئك بما يفعله هذا الشعب بشعبك في آخر الأيام '),
(27303, 'Numbers', 4, 24, 15, ' ثم نطق بمثله وقال : وحي بلعام بن بعور . وحي الرجل المفتوح العينين '),
(27304, 'Numbers', 4, 24, 16, ' وحي الذي يسمع أقوال الله ويعرف معرفة العلي . الذي يرى رؤيا القدير ساقطا وهو مكشوف العينين '),
(27305, 'Numbers', 4, 24, 17, ' أراه ولكن ليس الآن . أبصره ولكن ليس قريبا . يبرز كوكب من يعقوب ، ويقوم قضيب من إسرائيل ، فيحطم طرفي موآب ، ويهلك كل بني الوغى '),
(27306, 'Numbers', 4, 24, 18, ' ويكون أدوم ميراثا ، ويكون سعير أعداؤه ميراثا . ويصنع إسرائيل ببأس '),
(27307, 'Numbers', 4, 9, 6, ' لكن كان قوم قد تنجسوا لإنسان ميت ، فلم يحل لهم أن يعملوا الفصح في ذلك اليوم . فتقدموا أمام موسى وهارون في ذلك اليوم '),
(27308, 'Numbers', 4, 9, 7, ' وقال له أولئك الناس : إننا متنجسون لإنسان ميت . لماذا نترك حتى لا نقرب قربان الرب في وقته بين بني إسرائيل '),
(27309, 'Numbers', 4, 9, 8, ' فقال لهم موسى : قفوا لأسمع ما يأمر به الرب من جهتكم '),
(27310, 'Numbers', 4, 9, 9, ' فكلم الرب موسى قائلا '),
(27311, 'Numbers', 4, 9, 10, ' كلم بني إسرائيل قائلا : كل إنسان منكم أو من أجيالكم كان نجسا لميت ، أو في سفر بعيد ، فليعمل الفصح للرب '),
(27312, 'Numbers', 4, 9, 11, ' في الشهر الثاني ، في اليوم الرابع عشر بين العشاءين يعملونه . على فطير ومرار يأكلونه '),
(27313, 'Numbers', 4, 9, 12, ' لا يبقوا منه إلى الصباح ولا يكسروا عظما منه . حسب كل فرائض الفصح يعملونه '),
(27314, 'Numbers', 4, 9, 13, ' لكن من كان طاهرا وليس في سفر ، وترك عمل الفصح ، تقطع تلك النفس من شعبها ، لأنها لم تقرب قربان الرب في وقته . ذلك الإنسان يحمل خطيته '),
(27315, 'Numbers', 4, 9, 14, ' وإذا نزل عندكم غريب فليعمل فصحا للرب . حسب فريضة الفصح وحكمه كذلك يعمل . فريضة واحدة تكون لكم للغريب ولوطني الأرض '),
(27316, 'Numbers', 4, 9, 15, ' وفي يوم إقامة المسكن ، غطت السحابة المسكن ، خيمة الشهادة . وفي المساء كان على المسكن كمنظر نار إلى الصباح '),
(27317, 'Numbers', 4, 9, 16, ' هكذا كان دائما . السحابة تغطيه ومنظر النار ليلا '),
(27318, 'Numbers', 4, 9, 17, ' ومتى ارتفعت السحابة عن الخيمة كان بعد ذلك بنو إسرائيل يرتحلون ، وفي المكان حيث حلت السحابة هناك كان بنو إسرائيل ينزلون '),
(27319, 'Numbers', 4, 9, 18, ' حسب قول الرب كان بنو إسرائيل يرتحلون ، وحسب قول الرب كانوا ينزلون . جميع أيام حلول السحابة على المسكن كانوا ينزلون '),
(27320, 'Numbers', 4, 9, 19, ' وإذا تمادت السحابة على المسكن أياما كثيرة كان بنو إسرائيل يحرسون حراسة الرب ولا يرتحلون '),
(27321, 'Numbers', 4, 9, 20, ' وإذا كانت السحابة أياما قليلة على المسكن ، فحسب قول الرب كانوا ينزلون ، وحسب قول الرب كانوا يرتحلون '),
(27322, 'Numbers', 4, 9, 21, ' وإذا كانت السحابة من المساء إلى الصباح ، ثم ارتفعت السحابة في الصباح ، كانوا يرتحلون . أو يوما وليلة ثم ارتفعت السحابة كانوا يرتحلون '),
(27323, 'Numbers', 4, 9, 22, ' أو يومين أو شهرا أو سنة ، متى تمادت السحابة على المسكن حالة عليه ، كان بنو إسرائيل ينزلون ولا يرتحلون . ومتى ارتفعت كانوا يرتحلون '),
(27324, 'Numbers', 4, 9, 23, ' حسب قول الرب كانوا ينزلون ، وحسب قول الرب كانوا يرتحلون . وكانوا يحرسون حراسة الرب حسب قول الرب بيد موسى '),
(27325, 'Numbers', 4, 10, 1, ' وكلم الرب موسى قائلا '),
(27326, 'Numbers', 4, 10, 2, ' اصنع لك بوقين من فضة . مسحولين تعملهما ، فيكونان لك لمناداة الجماعة ولارتحال المحلات '),
(27327, 'Numbers', 4, 10, 3, ' فإذا ضربوا بهما يجتمع إليك كل الجماعة إلى باب خيمة الاجتماع '),
(27328, 'Numbers', 4, 10, 4, ' وإذا ضربوا بواحد يجتمع إليك الرؤساء ، رؤوس ألوف إسرائيل '),
(27329, 'Numbers', 4, 10, 5, ' وإذا ضربتم هتافا ترتحل المحلات النازلة إلى الشرق '),
(27330, 'Numbers', 4, 10, 6, ' وإذا ضربتم هتافا ثانية ترتحل المحلات النازلة إلى الجنوب . هتافا يضربون لرحلاتهم '),
(27331, 'Numbers', 4, 10, 7, ' وأما عندما تجمعون الجماعة فتضربون ولا تهتفون '),
(27332, 'Numbers', 4, 10, 8, ' وبنو هارون الكهنة يضربون بالأبواق . فتكون لكم فريضة أبدية في أجيالكم '),
(27333, 'Numbers', 4, 10, 9, ' وإذا ذهبتم إلى حرب في أرضكم على عدو يضر بكم ، تهتفون بالأبواق ، فتذكرون أمام الرب إلهكم ، وتخلصون من أعدائكم '),
(27334, 'Numbers', 4, 10, 10, ' وفي يوم فرحكم ، وفي أعيادكم ورؤوس شهوركم ، تضربون بالأبواق على محرقاتكم وذبائح سلامتكم ، فتكون لكم تذكارا أمام إلهكم . أنا الرب إلهكم '),
(27335, 'Numbers', 4, 10, 11, ' وفي السنة الثانية في الشهر الثاني ، في العشرين من الشهر ، ارتفعت السحابة عن مسكن الشهادة '),
(27336, 'Numbers', 4, 10, 12, ' فارتحل بنو إسرائيل في رحلاتهم من برية سيناء ، فحلت السحابة في برية فاران '),
(27337, 'Numbers', 4, 10, 13, ' ارتحلوا أولا حسب قول الرب عن يد موسى '),
(27338, 'Numbers', 4, 10, 14, ' فارتحلت راية محلة بني يهوذا أولا حسب أجنادهم ، وعلى جنده نحشون بن عميناداب '),
(27339, 'Numbers', 4, 10, 15, ' وعلى جند سبط بني يساكر نثنائيل بن صوغر '),
(27340, 'Numbers', 4, 10, 16, ' وعلى جند سبط بني زبولون أليآب بن حيلون '),
(27341, 'Numbers', 4, 10, 17, ' ثم أنزل المسكن فارتحل بنو جرشون وبنو مراري حاملين المسكن '),
(27342, 'Numbers', 4, 10, 18, ' ثم ارتحلت راية محلة رأوبين حسب أجنادهم ، وعلى جنده أليصور بن شديئور '),
(27343, 'Numbers', 4, 10, 19, ' وعلى جند سبط بني شمعون شلوميئيل بن صوريشداي '),
(27344, 'Numbers', 4, 10, 20, ' وعلى جند سبط بني جاد ألياساف بن دعوئيل '),
(27345, 'Numbers', 4, 10, 21, ' ثم ارتحل القهاتيون حاملين المقدس . وأقيم المسكن إلى أن جاءوا '),
(27346, 'Numbers', 4, 10, 22, ' ثم ارتحلت راية محلة بني أفرايم حسب أجنادهم ، وعلى جنده أليشمع بن عميهود '),
(27347, 'Numbers', 4, 10, 23, ' وعلى جند سبط بني منسى جمليئيل بن فدهصور '),
(27348, 'Numbers', 4, 10, 24, ' وعلى جند سبط بني بنيامين أبيدن بن جدعوني '),
(27349, 'Numbers', 4, 10, 25, ' ثم ارتحلت راية محلة بني دان ساقة جميع المحلات حسب أجنادهم ، وعلى جنده أخيعزر بن عميشداي '),
(27350, 'Numbers', 4, 10, 26, ' وعلى جند سبط بني أشير فجعيئيل بن عكرن '),
(27351, 'Numbers', 4, 10, 27, ' وعلى جند سبط بني نفتالي أخيرع بن عينن '),
(27352, 'Numbers', 4, 10, 28, ' هذه رحلات بني إسرائيل بأجنادهم حين ارتحلوا '),
(27353, 'Numbers', 4, 10, 29, ' وقال موسى لحوباب بن رعوئيل المدياني حمي موسى : إننا راحلون إلى المكان الذي قال الرب أعطيكم إياه . اذهب معنا فنحسن إليك ، لأن الرب قد تكلم عن إسرائيل بالإحسان '),
(27354, 'Numbers', 4, 10, 30, ' فقال له : لا أذهب ، بل إلى أرضي وإلى عشيرتي أمضي '),
(27355, 'Numbers', 4, 10, 31, ' فقال : لا تتركنا ، لأنه بما أنك تعرف منازلنا في البرية تكون لنا كعيون '),
(27356, 'Numbers', 4, 10, 32, ' وإن ذهبت معنا فبنفس الإحسان الذي يحسن الرب إلينا نحسن نحن إليك '),
(27357, 'Numbers', 4, 10, 33, ' فارتحلوا من جبل الرب مسيرة ثلاثة أيام ، وتابوت عهد الرب راحل أمامهم مسيرة ثلاثة أيام ليلتمس لهم منزلا '),
(27358, 'Numbers', 4, 10, 34, ' وكانت سحابة الرب عليهم نهارا في ارتحالهم من المحلة '),
(27359, 'Numbers', 4, 10, 35, ' وعند ارتحال التابوت كان موسى يقول : قم يارب ، فلتتبدد أعداؤك ويهرب مبغضوك من أمامك '),
(27360, 'Numbers', 4, 10, 36, ' وعند حلوله كان يقول : ارجع يارب إلى ربوات ألوف إسرائيل '),
(27361, 'Numbers', 4, 11, 1, ' وكان الشعب كأنهم يشتكون شرا في أذني الرب . وسمع الرب فحمي غضبه ، فاشتعلت فيهم نار الرب وأحرقت في طرف المحلة '),
(27362, 'Numbers', 4, 11, 2, ' فصرخ الشعب إلى موسى ، فصلى موسى إلى الرب فخمدت النار '),
(27363, 'Numbers', 4, 11, 3, ' فدعي اسم ذلك الموضع تبعيرة لأن نار الرب اشتعلت فيهم '),
(27364, 'Numbers', 4, 11, 4, ' واللفيف الذي في وسطهم اشتهى شهوة . فعاد بنو إسرائيل أيضا وبكوا وقالوا : من يطعمنا لحما '),
(27365, 'Numbers', 4, 11, 5, ' قد تذكرنا السمك الذي كنا نأكله في مصر مجانا ، والقثاء والبطيخ والكراث والبصل والثوم '),
(27366, 'Numbers', 4, 11, 6, ' والآن قد يبست أنفسنا . ليس شيء غير أن أعيننا إلى هذا المن '),
(27367, 'Numbers', 4, 11, 7, ' وأما المن فكان كبزر الكزبرة ، ومنظره كمنظر المقل '),
(27368, 'Numbers', 4, 11, 8, ' كان الشعب يطوفون ليلتقطوه ، ثم يطحنونه بالرحى أو يدقونه في الهاون ويطبخونه في القدور ويعملونه ملات . وكان طعمه كطعم قطائف بزيت '),
(27369, 'Numbers', 4, 11, 9, ' ومتى نزل الندى على المحلة ليلا كان ينزل المن معه '),
(27370, 'Numbers', 4, 11, 10, ' فلما سمع موسى الشعب يبكون بعشائرهم ، كل واحد في باب خيمته ، وحمي غضب الرب جدا ، ساء ذلك في عيني موسى '),
(27371, 'Numbers', 4, 11, 11, ' فقال موسى للرب : لماذا أسأت إلى عبدك ؟ ولماذا لم أجد نعمة في عينيك حتى أنك وضعت ثقل جميع هذا الشعب علي '),
(27372, 'Numbers', 4, 11, 12, ' ألعلي حبلت بجميع هذا الشعب ؟ أو لعلي ولدته ، حتى تقول لي احمله في حضنك كما يحمل المربي الرضيع ، إلى الأرض التي حلفت لآبائه '),
(27373, 'Numbers', 4, 11, 13, ' من أين لي لحم حتى أعطي جميع هذا الشعب ؟ لأنهم يبكون علي قائلين : أعطنا لحما لنأكل '),
(27374, 'Numbers', 4, 11, 14, ' لا أقدر أنا وحدي أن أحمل جميع هذا الشعب لأنه ثقيل علي '),
(27375, 'Numbers', 4, 11, 15, ' فإن كنت تفعل بي هكذا ، فاقتلني قتلا إن وجدت نعمة في عينيك ، فلا أرى بليتي '),
(27376, 'Numbers', 4, 11, 16, ' فقال الرب لموسى : اجمع إلي سبعين رجلا من شيوخ إسرائيل الذين تعلم أنهم شيوخ الشعب وعرفاؤه ، وأقبل بهم إلى خيمة الاجتماع فيقفوا هناك معك '),
(27377, 'Numbers', 4, 11, 17, ' فأنزل أنا وأتكلم معك هناك ، وآخذ من الروح الذي عليك وأضع عليهم ، فيحملون معك ثقل الشعب ، فلا تحمل أنت وحدك ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(27378, 'Numbers', 4, 11, 18, ' وللشعب تقول : تقدسوا للغد فتأكلوا لحما ، لأنكم قد بكيتم في أذني الرب قائلين : من يطعمنا لحما ؟ إنه كان لنا خير في مصر . فيعطيكم الرب لحما فتأكلون '),
(27379, 'Numbers', 4, 11, 19, ' تأكلون لا يوما واحدا ، ولا يومين ، ولا خمسة أيام ، ولا عشرة أيام ، ولا عشرين يوما '),
(27380, 'Numbers', 4, 11, 20, ' بل شهرا من الزمان ، حتى يخرج من مناخركم ، ويصير لكم كراهة ، لأنكم رفضتم الرب الذي في وسطكم وبكيتم أمامه قائلين : لماذا خرجنا من مصر '),
(27381, 'Numbers', 4, 11, 21, ' فقال موسى : ست مئة ألف ماش هو الشعب الذي أنا في وسطه ، وأنت قد قلت : أعطيهم لحما ليأكلوا شهرا من الزمان '),
(27382, 'Numbers', 4, 11, 22, ' أيذبح لهم غنم وبقر ليكفيهم ؟ أم يجمع لهم كل سمك البحر ليكفيهم '),
(27383, 'Numbers', 4, 11, 23, ' فقال الرب لموسى : هل تقصر يد الرب ؟ الآن ترى أيوافيك كلامي أم لا '),
(27384, 'Numbers', 4, 11, 24, ' فخرج موسى وكلم الشعب بكلام الرب ، وجمع سبعين رجلا من شيوخ الشعب وأوقفهم حوالي الخيمة '),
(27385, 'Numbers', 4, 11, 25, ' فنزل الرب في سحابة وتكلم معه ، وأخذ من الروح الذي عليه وجعل على السبعين رجلا الشيوخ . فلما حلت عليهم الروح تنبأوا ، ولكنهم لم يزيدوا '),
(27386, 'Numbers', 4, 11, 26, ' وبقي رجلان في المحلة ، اسم الواحد ألداد ، واسم الآخر ميداد ، فحل عليهما الروح . وكانا من المكتوبين ، لكنهما لم يخرجا إلى الخيمة ، فتنبآ في المحلة '),
(27387, 'Numbers', 4, 11, 27, ' فركض غلام وأخبر موسى وقال : ألداد وميداد يتنبآن في المحلة '),
(27388, 'Numbers', 4, 11, 28, ' فأجاب يشوع بن نون خادم موسى من حداثته وقال : يا سيدي موسى ، اردعهما '),
(27389, 'Numbers', 4, 11, 29, ' فقال له موسى : هل تغار أنت لي ؟ يا ليت كل شعب الرب كانوا أنبياء إذا جعل الرب روحه عليهم '),
(27390, 'Numbers', 4, 11, 30, ' ثم انحاز موسى إلى المحلة هو وشيوخ إسرائيل '),
(27391, 'Numbers', 4, 11, 31, ' فخرجت ريح من قبل الرب وساقت سلوى من البحر وألقتها على المحلة ، نحو مسيرة يوم من هنا ومسيرة يوم من هناك ، حوالي المحلة ، ونحو ذراعين فوق وجه الأرض '),
(27392, 'Numbers', 4, 11, 32, ' فقام الشعب كل ذلك النهار ، وكل الليل وكل يوم الغد وجمعوا السلوى . الذي قلل جمع عشرة حوامر . وسطحوها لهم مساطح حوالي المحلة '),
(27393, 'Numbers', 4, 11, 33, ' وإذ كان اللحم بعد بين أسنانهم قبل أن ينقطع ، حمي غضب الرب على الشعب ، وضرب الرب الشعب ضربة عظيمة جدا '),
(27394, 'Numbers', 4, 11, 34, ' فدعي اسم ذلك الموضع قبروت هتأوة لأنهم هناك دفنوا القوم الذين اشتهوا '),
(27395, 'Numbers', 4, 11, 35, ' ومن قبروت هتأوة ارتحل الشعب إلى حضيروت ، فكانوا في حضيروت '),
(27396, 'Numbers', 4, 12, 1, ' وتكلمت مريم وهارون على موسى بسبب المرأة الكوشية التي اتخذها ، لأنه كان قد اتخذ امرأة كوشية '),
(27397, 'Numbers', 4, 12, 2, ' فقالا : هل كلم الرب موسى وحده ؟ ألم يكلمنا نحن أيضا ؟ فسمع الرب '),
(27398, 'Numbers', 4, 12, 3, ' وأما الرجل موسى فكان حليما جدا أكثر من جميع الناس الذين على وجه الأرض '),
(27399, 'Numbers', 4, 12, 4, ' فقال الرب حالا لموسى وهارون ومريم : اخرجوا أنتم الثلاثة إلى خيمة الاجتماع . فخرجوا هم الثلاثة '),
(27400, 'Numbers', 4, 12, 5, ' فنزل الرب في عمود سحاب ووقف في باب الخيمة ، ودعا هارون ومريم فخرجا كلاهما '),
(27401, 'Numbers', 4, 12, 6, ' فقال : اسمعا كلامي . إن كان منكم نبي للرب ، فبالرؤيا أستعلن له . في الحلم أكلمه '),
(27402, 'Numbers', 4, 12, 7, ' وأما عبدي موسى فليس هكذا ، بل هو أمين في كل بيتي '),
(27403, 'Numbers', 4, 12, 8, ' فما إلى فم وعيانا أتكلم معه ، لا بالألغاز . وشبه الرب يعاين . فلماذا لا تخشيان أن تتكلما على عبدي موسى '),
(27404, 'Numbers', 4, 12, 9, ' فحمي غضب الرب عليهما ومضى '),
(27405, 'Numbers', 4, 12, 10, ' فلما ارتفعت السحابة عن الخيمة إذا مريم برصاء كالثلج . فالتفت هارون إلى مريم وإذا هي برصاء '),
(27406, 'Numbers', 4, 12, 11, ' فقال هارون لموسى : أسألك يا سيدي ، لا تجعل علينا الخطية التي حمقنا وأخطأنا بها '),
(27407, 'Numbers', 4, 12, 12, ' فلا تكن كالميت الذي يكون عند خروجه من رحم أمه قد أكل نصف لحمه '),
(27408, 'Numbers', 4, 12, 13, ' فصرخ موسى إلى الرب قائلا : اللهم اشفها '),
(27409, 'Numbers', 4, 12, 14, ' فقال الرب لموسى : ولو بصق أبوها بصقا في وجهها ، أما كانت تخجل سبعة أيام ؟ تحجز سبعة أيام خارج المحلة ، وبعد ذلك ترجع '),
(27410, 'Numbers', 4, 12, 15, ' فحجزت مريم خارج المحلة سبعة أيام ، ولم يرتحل الشعب حتى أرجعت مريم '),
(27411, 'Numbers', 4, 12, 16, ' وبعد ذلك ارتحل الشعب من حضيروت ونزلوا في برية فاران '),
(27412, 'Numbers', 4, 13, 1, ' ثم كلم الرب موسى قائلا '),
(27413, 'Numbers', 4, 13, 2, ' أرسل رجالا ليتجسسوا أرض كنعان التي أنا معطيها لبني إسرائيل . رجلا واحدا لكل سبط من آبائه ترسلون . كل واحد رئيس فيهم '),
(27414, 'Numbers', 4, 13, 3, ' فأرسلهم موسى من برية فاران حسب قول الرب . كلهم رجال هم رؤساء بني إسرائيل '),
(27415, 'Numbers', 4, 13, 4, ' وهذه أسماؤهم : من سبط رأوبين شموع بن زكور '),
(27416, 'Numbers', 4, 13, 5, ' من سبط شمعون شافاط ابن حوري '),
(27417, 'Numbers', 4, 13, 6, ' من سبط يهوذا كالب بن يفنة '),
(27418, 'Numbers', 4, 13, 7, ' من سبط يساكر يجآل بن يوسف '),
(27419, 'Numbers', 4, 13, 8, ' من سبط أفرايم هوشع بن نون '),
(27420, 'Numbers', 4, 13, 9, ' من سبط بنيامين فلطي بن رافو '),
(27421, 'Numbers', 4, 13, 10, ' من سبط زبولون جديئيل بن سودي '),
(27422, 'Numbers', 4, 13, 11, ' من سبط يوسف من سبط منسى جدي بن سوسي '),
(27423, 'Numbers', 4, 13, 12, ' من سبط دان عميئيل بن جملي '),
(27424, 'Numbers', 4, 13, 13, ' من سبط أشير ستور بن ميخائيل '),
(27425, 'Numbers', 4, 13, 14, ' من سبط نفتالي نحبي بن وفسي '),
(27426, 'Numbers', 4, 13, 15, ' من سبط جاد جأوئيل بن ماكي '),
(27427, 'Numbers', 4, 13, 16, ' هذه أسماء الرجال الذين أرسلهم موسى ليتجسسوا الأرض . ودعا موسى هوشع بن نون يشوع '),
(27428, 'Numbers', 4, 13, 17, ' فأرسلهم موسى ليتجسسوا أرض كنعان ، وقال لهم : اصعدوا من هنا إلى الجنوب واطلعوا إلى الجبل '),
(27429, 'Numbers', 4, 13, 18, ' وانظروا الأرض ، ما هي : والشعب الساكن فيها ، أقوي هو أم ضعيف ؟ قليل أم كثير '),
(27430, 'Numbers', 4, 13, 19, ' وكيف هي الأرض التي هو ساكن فيها ، أجيدة أم ردية ؟ وما هي المدن التي هو ساكن فيها ، أمخيمات أم حصون '),
(27431, 'Numbers', 4, 13, 20, ' وكيف هي الأرض ، أسمينة أم هزيلة ؟ أفيها شجر أم لا ؟ وتشددوا فخذوا من ثمر الأرض . وأما الأيام فكانت أيام باكورات العنب '),
(27432, 'Numbers', 4, 13, 21, ' فصعدوا وتجسسوا الأرض من برية صين إلى رحوب في مدخل حماة '),
(27433, 'Numbers', 4, 13, 22, ' صعدوا إلى الجنوب وأتوا إلى حبرون . وكان هناك أخيمان وشيشاي وتلماي بنو عناق . وأما حبرون فبنيت قبل صوعن مصر بسبع سنين '),
(27434, 'Numbers', 4, 13, 23, ' وأتوا إلى وادي أشكول ، وقطفوا من هناك زرجونة بعنقود واحد من العنب ، وحملوه بالدقرانة بين اثنين ، مع شيء من الرمان والتين '),
(27435, 'Numbers', 4, 13, 24, ' فدعي ذلك الموضع وادي أشكول بسبب العنقود الذي قطعه بنو إسرائيل من هناك '),
(27436, 'Numbers', 4, 13, 25, ' ثم رجعوا من تجسس الأرض بعد أربعين يوما '),
(27437, 'Numbers', 4, 13, 26, ' فساروا حتى أتوا إلى موسى وهارون وكل جماعة بني إسرائيل ، إلى برية فاران ، إلى قادش ، وردوا إليهما خبرا وإلى كل الجماعة وأروهم ثمر الأرض '),
(27438, 'Numbers', 4, 13, 27, ' وأخبروه وقالوا : قد ذهبنا إلى الأرض التي أرسلتنا إليها ، وحقا إنها تفيض لبنا وعسلا ، وهذا ثمرها '),
(27439, 'Numbers', 4, 13, 28, ' غير أن الشعب الساكن في الأرض معتز ، والمدن حصينة عظيمة جدا . وأيضا قد رأينا بني عناق هناك '),
(27440, 'Numbers', 4, 13, 29, ' العمالقة ساكنون في أرض الجنوب ، والحثيون واليبوسيون والأموريون ساكنون في الجبل ، والكنعانيون ساكنون عند البحر وعلى جانب الأردن '),
(27441, 'Numbers', 4, 13, 30, ' لكن كالب أنصت الشعب إلى موسى وقال : إننا نصعد ونمتلكها لأننا قادرون عليها '),
(27442, 'Numbers', 4, 13, 31, ' وأما الرجال الذين صعدوا معه فقالوا : لا نقدر أن نصعد إلى الشعب ، لأنهم أشد منا '),
(27443, 'Numbers', 4, 13, 32, ' فأشاعوا مذمة الأرض التي تجسسوها ، في بني إسرائيل قائلين : الأرض التي مررنا فيها لنتجسسها هي أرض تأكل سكانها ، وجميع الشعب الذي رأينا فيها أناس طوال القامة '),
(27444, 'Numbers', 4, 13, 33, ' وقد رأينا هناك الجبابرة ، بني عناق من الجبابرة . فكنا في أعيننا كالجراد ، وهكذا كنا في أعينهم '),
(27445, 'Numbers', 4, 14, 1, ' فرفعت كل الجماعة صوتها وصرخت ، وبكى الشعب تلك الليلة '),
(27446, 'Numbers', 4, 14, 2, ' وتذمر على موسى وعلى هارون جميع بني إسرائيل ، وقال لهما كل الجماعة : ليتنا متنا في أرض مصر ، أو ليتنا متنا في هذا القفر '),
(27447, 'Numbers', 4, 14, 3, ' ولماذا أتى بنا الرب إلى هذه الأرض لنسقط بالسيف ؟ تصير نساؤنا وأطفالنا غنيمة . أليس خيرا لنا أن نرجع إلى مصر '),
(27448, 'Numbers', 4, 14, 4, ' فقال بعضهم لبعض : نقيم رئيسا ونرجع إلى مصر '),
(27449, 'Numbers', 4, 14, 5, ' فسقط موسى وهارون على وجهيهما أمام كل معشر جماعة بني إسرائيل '),
(27450, 'Numbers', 4, 14, 6, ' ويشوع بن نون وكالب بن يفنة ، من الذين تجسسوا الأرض ، مزقا ثيابهما '),
(27451, 'Numbers', 4, 14, 7, ' وكلما كل جماعة بني إسرائيل قائلين : الأرض التي مررنا فيها لنتجسسها الأرض جيدة جدا جدا '),
(27452, 'Numbers', 4, 14, 8, ' إن سر بنا الرب يدخلنا إلى هذه الأرض ويعطينا إياها ، أرضا تفيض لبنا وعسلا '),
(27453, 'Numbers', 4, 14, 9, ' إنما لا تتمردوا على الرب ، ولا تخافوا من شعب الأرض لأنهم خبزنا . قد زال عنهم ظلهم ، والرب معنا . لا تخافوهم '),
(27454, 'Numbers', 4, 14, 10, ' ولكن قال كل الجماعة أن يرجما بالحجارة . ثم ظهر مجد الرب في خيمة الاجتماع لكل بني إسرائيل '),
(27455, 'Numbers', 4, 14, 11, ' وقال الرب لموسى : حتى متى يهينني هذا الشعب ؟ وحتى متى لا يصدقونني بجميع الآيات التي عملت في وسطهم '),
(27456, 'Numbers', 4, 14, 12, ' إني أضربهم بالوبإ وأبيدهم ، وأصيرك شعبا أكبر وأعظم منهم '),
(27457, 'Numbers', 4, 14, 13, ' فقال موسى للرب : فيسمع المصريون الذين أصعدت بقوتك هذا الشعب من وسطهم '),
(27458, 'Numbers', 4, 14, 14, ' ويقولون لسكان هذه الأرض الذين قد سمعوا أنك يارب في وسط هذا الشعب ، الذين أنت يارب قد ظهرت لهم عينا لعين ، وسحابتك واقفة عليهم ، وأنت سائر أمامهم بعمود سحاب نهارا وبعمود نار ليلا '),
(27459, 'Numbers', 4, 14, 15, ' فإن قتلت هذا الشعب كرجل واحد ، يتكلم الشعوب الذين سمعوا بخبرك قائلين '),
(27460, 'Numbers', 4, 14, 16, ' لأن الرب لم يقدر أن يدخل هذا الشعب إلى الأرض التي حلف لهم ، قتلهم في القفر '),
(27461, 'Numbers', 4, 14, 17, ' فالآن لتعظم قدرة سيدي كما تكلمت قائلا '),
(27462, 'Numbers', 4, 14, 18, ' الرب طويل الروح كثير الإحسان ، يغفر الذنب والسيئة ، لكنه لا يبرئ . بل يجعل ذنب الآباء على الأبناء إلى الجيل الثالث والرابع '),
(27463, 'Numbers', 4, 14, 19, ' اصفح عن ذنب هذا الشعب كعظمة نعمتك ، وكما غفرت لهذا الشعب من مصر إلى ههنا '),
(27464, 'Numbers', 4, 14, 20, ' فقال الرب : قد صفحت حسب قولك '),
(27465, 'Numbers', 4, 14, 21, ' ولكن حي أنا فتملأ كل الأرض من مجد الرب '),
(27466, 'Numbers', 4, 14, 22, ' إن جميع الرجال الذين رأوا مجدي وآياتي التي عملتها في مصر وفي البرية ، وجربوني الآن عشر مرات ، ولم يسمعوا لقولي '),
(27467, 'Numbers', 4, 14, 23, ' لن يروا الأرض التي حلفت لآبائهم . وجميع الذين أهانوني لا يرونها '),
(27468, 'Numbers', 4, 14, 24, ' وأما عبدي كالب فمن أجل أنه كانت معه روح أخرى ، وقد اتبعني تماما ، أدخله إلى الأرض التي ذهب إليها ، وزرعه يرثها '),
(27469, 'Numbers', 4, 14, 25, ' وإذ العمالقة والكنعانيون ساكنون في الوادي ، فانصرفوا غدا وارتحلوا إلى القفر في طريق بحر سوف '),
(27470, 'Numbers', 4, 14, 26, ' وكلم الرب موسى وهارون قائلا '),
(27471, 'Numbers', 4, 14, 27, ' حتى متى أغفر لهذه الجماعة الشريرة المتذمرة علي ؟ قد سمعت تذمر بني إسرائيل الذي يتذمرونه علي '),
(27472, 'Numbers', 4, 14, 28, ' قل لهم : حي أنا يقول الرب ، لأفعلن بكم كما تكلمتم في أذني '),
(27473, 'Numbers', 4, 14, 29, ' في هذا القفر تسقط جثثكم ، جميع المعدودين منكم حسب عددكم من ابن عشرين سنة فصاعدا الذين تذمروا علي '),
(27474, 'Numbers', 4, 14, 30, ' لن تدخلوا الأرض التي رفعت يدي لأسكننكم فيها ، ما عدا كالب بن يفنة ويشوع بن نون '),
(27475, 'Numbers', 4, 14, 31, ' وأما أطفالكم الذين قلتم يكونون غنيمة فإني سأدخلهم ، فيعرفون الأرض التي احتقرتموها '),
(27476, 'Numbers', 4, 14, 32, ' فجثثكم أنتم تسقط في هذا القفر '),
(27477, 'Numbers', 4, 14, 33, ' وبنوكم يكونون رعاة في القفر أربعين سنة ، ويحملون فجوركم حتى تفنى جثثكم في القفر '),
(27478, 'Numbers', 4, 14, 34, ' كعدد الأيام التي تجسستم فيها الأرض أربعين يوما ، للسنة يوم . تحملون ذنوبكم أربعين سنة فتعرفون ابتعادي '),
(27479, 'Numbers', 4, 14, 35, ' أنا الرب قد تكلمت . لأفعلن هذا بكل هذه الجماعة الشريرة المتفقة علي . في هذا القفر يفنون ، وفيه يموتون '),
(27480, 'Numbers', 4, 14, 36, ' أما الرجال الذين أرسلهم موسى ليتجسسوا الأرض ، ورجعوا وسجسوا عليه كل الجماعة بإشاعة المذمة على الأرض '),
(27481, 'Numbers', 4, 14, 37, ' فمات الرجال الذين أشاعوا المذمة الرديئة على الأرض بالوبإ أمام الرب '),
(27482, 'Numbers', 4, 14, 38, ' وأما يشوع بن نون وكالب بن يفنة ، من أولئك الرجال الذين ذهبوا ليتجسسوا الأرض ، فعاشا '),
(27483, 'Numbers', 4, 14, 39, ' ولما تكلم موسى بهذا الكلام إلى جميع بني إسرائيل بكى الشعب جدا '),
(27484, 'Numbers', 4, 14, 40, ' ثم بكروا صباحا وصعدوا إلى رأس الجبل قائلين : هوذا نحن نصعد إلى الموضع الذي قال الرب عنه ، فإننا قد أخطأنا '),
(27485, 'Numbers', 4, 14, 41, ' فقال موسى : لماذا تتجاوزون قول الرب ؟ فهذا لا ينجح '),
(27486, 'Numbers', 4, 14, 42, ' لا تصعدوا ، لأن الرب ليس في وسطكم لئلا تنهزموا أمام أعدائكم '),
(27487, 'Numbers', 4, 14, 43, ' لأن العمالقة والكنعانيين هناك قدامكم تسقطون بالسيف . إنكم قد ارتددتم عن الرب ، فالرب لا يكون معكم '),
(27488, 'Numbers', 4, 14, 44, ' لكنهم تجبروا وصعدوا إلى رأس الجبل . وأما تابوت عهد الرب وموسى فلم يبرحا من وسط المحلة '),
(27489, 'Numbers', 4, 14, 45, ' فنزل العمالقة والكنعانيون الساكنون في ذلك الجبل وضربوهم وكسروهم إلى حرمة '),
(27490, 'Numbers', 4, 15, 1, ' وكلم الرب موسى قائلا '),
(27491, 'Numbers', 4, 15, 2, ' كلم بني إسرائيل وقل لهم : متى جئتم إلى أرض مسكنكم التي أنا أعطيكم '),
(27492, 'Numbers', 4, 15, 3, ' وعملتم وقودا للرب ، محرقة أو ذبيحة ، وفاء لنذر أو نافلة أو في أعيادكم ، لعمل رائحة سرور للرب من البقر أو من الغنم '),
(27493, 'Numbers', 4, 15, 4, ' يقرب الذي قرب قربانه للرب تقدمة من دقيق ، عشرا ملتوتا بربع الهين من الزيت '),
(27494, 'Numbers', 4, 15, 5, ' وخمرا للسكيب ربع الهين . تعمل على المحرقة أو الذبيحة للخروف الواحد '),
(27495, 'Numbers', 4, 15, 6, ' لكن للكبش تعمل تقدمة من دقيق عشرين ملتوتين بثلث الهين من الزيت '),
(27496, 'Numbers', 4, 15, 7, ' وخمرا للسكيب ثلث الهين تقرب لرائحة سرور للرب '),
(27497, 'Numbers', 4, 15, 8, ' وإذا عملت ابن بقر محرقة أو ذبيحة وفاء لنذر أو ذبيحة سلامة للرب '),
(27498, 'Numbers', 4, 15, 9, ' تقرب على ابن البقر تقدمة من دقيق ثلاثة أعشار ملتوتة بنصف الهين من الزيت '),
(27499, 'Numbers', 4, 15, 10, ' وخمرا تقرب للسكيب نصف الهين وقود رائحة سرور للرب '),
(27500, 'Numbers', 4, 15, 11, ' هكذا يعمل للثور الواحد أو للكبش الواحد أو للشاة من الضأن أو من المعز '),
(27501, 'Numbers', 4, 15, 12, ' كالعدد الذي تعملون هكذا تعملون لكل واحد حسب عددهن '),
(27502, 'Numbers', 4, 15, 13, ' كل وطني يعمل هذه هكذا ، لتقريب وقود رائحة سرور للرب '),
(27503, 'Numbers', 4, 15, 14, ' وإذا نزل عندكم غريب ، أو كان أحد في وسطكم في أجيالكم وعمل وقود رائحة سرور للرب ، فكما تفعلون كذلك يفعل '),
(27504, 'Numbers', 4, 15, 15, ' أيتها الجماعة ، لكم وللغريب النازل عندكم فريضة واحدة دهرية في أجيالكم . مثلكم يكون مثل الغريب أمام الرب '),
(27505, 'Numbers', 4, 15, 16, ' شريعة واحدة وحكم واحد يكون لكم وللغريب النازل عندكم '),
(27506, 'Numbers', 4, 15, 17, ' وكلم الرب موسى قائلا '),
(27507, 'Numbers', 4, 15, 18, ' كلم بني إسرائيل وقل لهم : متى دخلتم الأرض التي أنا آت بكم إليها '),
(27508, 'Numbers', 4, 15, 19, ' فعندما تأكلون من خبز الأرض ترفعون رفيعة للرب '),
(27509, 'Numbers', 4, 15, 20, ' أول عجينكم ترفعون قرصا رفيعة ، كرفيعة البيدر هكذا ترفعونه '),
(27510, 'Numbers', 4, 15, 21, ' من أول عجينكم تعطون للرب رفيعة في أجيالكم '),
(27511, 'Numbers', 4, 15, 22, ' وإذا سهوتم ولم تعملوا جميع هذه الوصايا التي كلم بها الرب موسى '),
(27512, 'Numbers', 4, 24, 19, ' ويتسلط الذي من يعقوب ، ويهلك الشارد من مدينة '),
(27513, 'Numbers', 4, 24, 20, ' ثم رأى عماليق فنطق بمثله وقال : عماليق أول الشعوب ، وأما آخرته فإلى الهلاك '),
(27514, 'Numbers', 4, 24, 21, ' ثم رأى القيني فنطق بمثله وقال : ليكن مسكنك متينا ، وعشك موضوعا في صخرة '),
(27515, 'Numbers', 4, 24, 22, ' لكن يكون قاين للدمار . حتى متى يستأسرك أشور '),
(27516, 'Numbers', 4, 24, 23, ' ثم نطق بمثله وقال : آه من يعيش حين يفعل ذلك '),
(27517, 'Numbers', 4, 24, 24, ' وتأتي سفن من ناحية كتيم وتخضع أشور ، وتخضع عابر ، فهو أيضا إلى الهلاك '),
(27518, 'Numbers', 4, 24, 25, ' ثم قام بلعام وانطلق ورجع إلى مكانه . وبالاق أيضا ذهب في طريقه '),
(27519, 'Numbers', 4, 25, 1, ' وأقام إسرائيل في شطيم ، وابتدأ الشعب يزنون مع بنات موآب '),
(27520, 'Numbers', 4, 25, 2, ' فدعون الشعب إلى ذبائح آلهتهن ، فأكل الشعب وسجدوا لآلهتهن '),
(27521, 'Numbers', 4, 25, 3, ' وتعلق إسرائيل ببعل فغور . فحمي غضب الرب على إسرائيل '),
(27522, 'Numbers', 4, 25, 4, ' فقال الرب لموسى : خذ جميع رؤوس الشعب وعلقهم للرب مقابل الشمس ، فيرتد حمو غضب الرب عن إسرائيل '),
(27523, 'Numbers', 4, 25, 5, ' فقال موسى لقضاة إسرائيل : اقتلوا كل واحد قومه المتعلقين ببعل فغور '),
(27524, 'Numbers', 4, 25, 6, ' وإذا رجل من بني إسرائيل جاء وقدم إلى إخوته المديانية ، أمام عيني موسى وأعين كل جماعة بني إسرائيل ، وهم باكون لدى باب خيمة الاجتماع '),
(27525, 'Numbers', 4, 25, 7, ' فلما رأى ذلك فينحاس بن ألعازار بن هارون الكاهن ، قام من وسط الجماعة وأخذ رمحا بيده '),
(27526, 'Numbers', 4, 25, 8, ' ودخل وراء الرجل الإسرائيلي إلى القبة وطعن كليهما ، الرجل الإسرائيلي والمرأة في بطنها . فامتنع الوبأ عن بني إسرائيل '),
(27527, 'Numbers', 4, 25, 9, ' وكان الذين ماتوا بالوبإ أربعة وعشرين ألفا '),
(27528, 'Numbers', 4, 25, 10, ' فكلم الرب موسى قائلا '),
(27529, 'Numbers', 4, 25, 11, ' فينحاس بن ألعازار بن هارون الكاهن قد رد سخطي عن بني إسرائيل بكونه غار غيرتي في وسطهم حتى لم أفن بني إسرائيل بغيرتي '),
(27530, 'Numbers', 4, 25, 12, ' لذلك قل : هأنذا أعطيه ميثاقي ميثاق السلام '),
(27531, 'Numbers', 4, 25, 13, ' فيكون له ولنسله من بعده ميثاق كهنوت أبدي ، لأجل أنه غار لله وكفر عن بني إسرائيل '),
(27532, 'Numbers', 4, 25, 14, ' وكان اسم الرجل الإسرائيلي المقتول الذي قتل مع المديانية ، زمري بن سالو ، رئيس بيت أب من الشمعونيين '),
(27533, 'Numbers', 4, 25, 15, ' واسم المرأة المديانية المقتولة كزبي بنت صور ، هو رئيس قبائل بيت أب في مديان '),
(27534, 'Numbers', 4, 25, 16, ' ثم كلم الرب موسى قائلا '),
(27535, 'Numbers', 4, 25, 17, ' ضايقوا المديانيين واضربوهم '),
(27536, 'Numbers', 4, 25, 18, ' لأنهم ضايقوكم بمكايدهم التي كادوكم بها في أمر فغور وأمر كزبي أختهم بنت رئيس لمديان ، التي قتلت يوم الوبإ بسبب فغور '),
(27537, 'Numbers', 4, 26, 1, ' ثم بعد الوبإ كلم الرب موسى وألعازار بن هارون الكاهن قائلا '),
(27538, 'Numbers', 4, 26, 2, ' خذا عدد كل جماعة بني إسرائيل ، من ابن عشرين سنة فصاعدا حسب بيوت آبائهم ، كل خارج للجند في إسرائيل '),
(27539, 'Numbers', 4, 26, 3, ' فكلمهم موسى وألعازار الكاهن في عربات موآب على أردن أريحا قائلين '),
(27540, 'Numbers', 4, 26, 4, ' من ابن عشرين سنة فصاعدا . كما أمر الرب موسى . وبني إسرائيل الخارجين من أرض مصر '),
(27541, 'Numbers', 4, 26, 5, ' رأوبين بكر إسرائيل ، بنو رأوبين : لحنوك عشيرة الحنوكيين . لفلو عشيرة الفلويين '),
(27542, 'Numbers', 4, 26, 6, ' لحصرون عشيرة الحصرونيين . لكرمي عشيرة الكرميين '),
(27543, 'Numbers', 4, 26, 7, ' هذه عشائر الرأوبينيين ، وكان المعدودون منهم ثلاثة وأربعين ألفا وسبع مئة وثلاثين '),
(27544, 'Numbers', 4, 26, 8, ' وابن فلو أليآب '),
(27545, 'Numbers', 4, 26, 9, ' وبنو أليآب : نموئيل وداثان وأبيرام ، وهما داثان وأبيرام المدعوان من الجماعة اللذان خاصما موسى وهارون في جماعة قورح حين خاصموا الرب '),
(27546, 'Numbers', 4, 26, 10, ' ففتحت الأرض فاها وابتلعتهما مع قورح حين مات القوم بإحراق النار ، مئتين وخمسين رجلا . فصاروا عبرة '),
(27547, 'Numbers', 4, 26, 11, ' وأما بنو قورح فلم يموتوا '),
(27548, 'Numbers', 4, 26, 12, ' بنو شمعون حسب عشائرهم : لنموئيل عشيرة النموئيليين . ليامين عشيرة اليامينيين . لياكين عشيرة الياكينيين '),
(27549, 'Numbers', 4, 26, 13, ' لزارح عشيرة الزارحيين . لشأول عشيرة الشأوليين '),
(27550, 'Numbers', 4, 26, 14, ' هذه عشائر الشمعونيين ، اثنان وعشرون ألفا ومئتان '),
(27551, 'Numbers', 4, 26, 15, ' بنو جاد حسب عشائرهم : لصفون عشيرة الصفونيين . لحجي عشيرة الحجيين . لشوني عشيرة الشونيين '),
(27552, 'Numbers', 4, 26, 16, ' لأزني عشيرة الأزنيين . لعيري عشيرة العيريين '),
(27553, 'Numbers', 4, 26, 17, ' لأرود عشيرة الأروديين . لأرئيلي عشيرة الأرئيليين '),
(27554, 'Numbers', 4, 26, 18, ' هذه عشائر بني جاد حسب عددهم ، أربعون ألفا وخمس مئة '),
(27555, 'Numbers', 4, 26, 19, ' ابنا يهوذا : عير وأونان ، ومات عير وأونان في أرض كنعان '),
(27556, 'Numbers', 4, 26, 20, ' فكان بنو يهوذا حسب عشائرهم : لشيلة عشيرة الشيليين . ولفارص عشيرة الفارصيين . ولزارح عشيرة الزارحيين '),
(27557, 'Numbers', 4, 26, 21, ' وكان بنو فارص : لحصرون عشيرة الحصرونيين . ولحامول عشيرة الحاموليين '),
(27558, 'Numbers', 4, 26, 22, ' هذه عشائر يهوذا حسب عددهم ، ستة وسبعون ألفا وخمس مئة '),
(27559, 'Numbers', 4, 26, 23, ' بنو يساكر حسب عشائرهم : لتولاع عشيرة التولاعيين . ولفوة عشيرة الفويين '),
(27560, 'Numbers', 4, 26, 24, ' ولياشوب عشيرة الياشوبيين . ولشمرون عشيرة الشمرونيين '),
(27561, 'Numbers', 4, 26, 25, ' هذه عشائر يساكر حسب عددهم ، أربعة وستون ألفا وثلاث مئة '),
(27562, 'Numbers', 4, 26, 26, ' بنو زبولون حسب عشائرهم : لسارد عشيرة السارديين . ولإيلون عشيرة الإيلونيين . ولياحلئيل عشيرة الياحلئيليين '),
(27563, 'Numbers', 4, 26, 27, ' هذه عشائر الزبولونيين حسب عددهم ، ستون ألفا وخمس مئة '),
(27564, 'Numbers', 4, 26, 28, ' ابنا يوسف حسب عشائرهما منسى وأفرايم '),
(27565, 'Numbers', 4, 26, 29, ' بنو منسى : لماكير عشيرة الماكيريين . وماكير ولد جلعاد . ولجلعاد عشيرة الجلعاديين '),
(27566, 'Numbers', 4, 26, 30, ' هؤلاء بنو جلعاد : لإيعزر عشيرة الإيعزريين . لحالق عشيرة الحالقيين '),
(27567, 'Numbers', 4, 26, 31, ' لأسريئيل عشيرة الأسريئيليين . لشكم عشيرة الشكميين '),
(27568, 'Numbers', 4, 26, 32, ' لشميداع عشيرة الشميداعيين . لحافر عشيرة الحافريين '),
(27569, 'Numbers', 4, 26, 33, ' وأما صلفحاد بن حافر فلم يكن له بنون بل بنات . وأسماء بنات صلفحاد : محلة ونوعة وحجلة وملكة وترصة '),
(27570, 'Numbers', 4, 26, 34, ' هذه عشائر منسى ، والمعدودون منهم اثنان وخمسون ألفا وسبع مئة '),
(27571, 'Numbers', 4, 26, 35, ' وهؤلاء بنو أفرايم حسب عشائرهم : لشوتالح عشيرة الشوتالحيين . لباكر عشيرة الباكريين . لتاحن عشيرة التاحنيين '),
(27572, 'Numbers', 4, 26, 36, ' وهؤلاء بنو شوتالح : لعيران عشيرة العيرانيين '),
(27573, 'Numbers', 4, 26, 37, ' هذه عشائر بني أفرايم حسب عددهم ، اثنان وثلاثون ألفا وخمس مئة . هؤلاء بنو يوسف حسب عشائرهم '),
(27574, 'Numbers', 4, 26, 38, ' بنو بنيامين حسب عشائرهم : لبالع عشيرة البالعيين . لأشبيل عشيرة الأشبيليين . لأحيرام عشيرة الأحيراميين '),
(27575, 'Numbers', 4, 26, 39, ' لشفوفام عشيرة الشفوفاميين . لحوفام عشيرة الحوفاميين '),
(27576, 'Numbers', 4, 26, 40, ' وكان ابنا بالع : أرد ونعمان . لأرد عشيرة الأرديين ، ولنعمان عشيرة النعمانيين '),
(27577, 'Numbers', 4, 26, 41, ' هؤلاء بنو بنيامين حسب عشائرهم ، والمعدودون منهم خمسة وأربعون ألفا وست مئة '),
(27578, 'Numbers', 4, 26, 42, ' هؤلاء بنو دان حسب عشائرهم : لشوحام عشيرة الشوحاميين . هذه قبائل دان حسب عشائرهم '),
(27579, 'Numbers', 4, 26, 43, ' جميع عشائر الشوحاميين حسب عددهم ، أربعة وستون ألفا وأربع مئة '),
(27580, 'Numbers', 4, 26, 44, ' بنو أشير حسب عشائرهم : ليمنة عشيرة اليمنيين . ليشوي عشيرة اليشويين . لبريعة عشيرة البريعيين '),
(27581, 'Numbers', 4, 26, 45, ' لبني بريعة : لحابر عشيرة الحابريين . لملكيئيل عشيرة الملكيئيليين '),
(27582, 'Numbers', 4, 34, 6, ' وأما تخم الغرب فيكون البحر الكبير لكم تخما . هذا يكون لكم تخم الغرب '),
(27583, 'Numbers', 4, 34, 7, ' وهذا يكون لكم تخم الشمال . من البحر الكبير ترسمون لكم إلى جبل هور '),
(27584, 'Numbers', 4, 34, 8, ' ومن جبل هور ترسمون إلى مدخل حماة ، وتكون مخارج التخم إلى صدد '),
(27585, 'Numbers', 4, 34, 9, ' ثم يخرج التخم إلى زفرون ، وتكون مخارجه عند حصر عينان . هذا يكون لكم تخم الشمال '),
(27586, 'Numbers', 4, 34, 10, ' وترسمون لكم تخما إلى الشرق من حصر عينان إلى شفام '),
(27587, 'Numbers', 4, 34, 11, ' وينحدر التخم من شفام إلى ربلة شرقي عين . ثم ينحدر التخم ويمس جانب بحر كنارة إلى الشرق '),
(27588, 'Numbers', 4, 34, 12, ' ثم ينحدر التخم إلى الأردن ، وتكون مخارجه عند بحر الملح . هذه تكون لكم الأرض بتخومها حواليها '),
(27589, 'Numbers', 4, 34, 13, ' فأمر موسى بني إسرائيل قائلا : هذه هي الأرض التي تقتسمونها بالقرعة ، التي أمر الرب أن تعطى للتسعة الأسباط ونصف السبط '),
(27590, 'Numbers', 4, 34, 14, ' لأنه قد أخذ سبط بني رأوبين حسب بيوت آبائهم ، وسبط بني جاد حسب بيوت آبائهم ، ونصف سبط منسى . قد أخذوا نصيبهم '),
(27591, 'Numbers', 4, 34, 15, ' السبطان ونصف السبط قد أخذوا نصيبهم في عبر أردن أريحا شرقا ، نحو الشروق '),
(27592, 'Numbers', 4, 34, 16, ' وكلم الرب موسى قائلا '),
(27593, 'Numbers', 4, 34, 17, ' هذان اسما الرجلين اللذين يقسمان لكم الأرض : ألعازار الكاهن ويشوع بن نون '),
(27594, 'Numbers', 4, 34, 18, ' ورئيسا واحدا من كل سبط تأخذون لقسمة الأرض '),
(27595, 'Numbers', 4, 34, 19, ' وهذه أسماء الرجال : من سبط يهوذا كالب بن يفنة '),
(27596, 'Numbers', 4, 34, 20, ' ومن سبط بني شمعون شموئيل بن عميهود '),
(27597, 'Numbers', 4, 34, 21, ' ومن سبط بنيامين أليداد بن كسلون '),
(27598, 'Numbers', 4, 34, 22, ' ومن سبط بني دان الرئيس بقي بن يجلي '),
(27599, 'Numbers', 4, 34, 23, ' ومن بني يوسف : من سبط بني منسى الرئيس حنيئيل بن إيفود '),
(27600, 'Numbers', 4, 34, 24, ' ومن سبط بني أفرايم الرئيس قموئيل بن شفطان '),
(27601, 'Numbers', 4, 34, 25, ' ومن سبط بني زبولون الرئيس أليصافان بن فرناخ '),
(27602, 'Numbers', 4, 34, 26, ' ومن سبط بني يساكر الرئيس فلطيئيل بن عزان '),
(27603, 'Numbers', 4, 34, 27, ' ومن سبط بني أشير الرئيس أخيهود بن شلومي '),
(27604, 'Numbers', 4, 34, 28, ' ومن سبط بني نفتالي الرئيس فدهئيل بن عميهود '),
(27605, 'Numbers', 4, 34, 29, ' هؤلاء هم الذين أمرهم الرب أن يقسموا لبني إسرائيل في أرض كنعان '),
(27606, 'Numbers', 4, 35, 1, ' ثم كلم الرب موسى في عربات موآب على أردن أريحا قائلا '),
(27607, 'Numbers', 4, 35, 2, ' أوص بني إسرائيل أن يعطوا اللاويين من نصيب ملكهم مدنا للسكن ، ومسارح للمدن حواليها تعطون اللاويين '),
(27608, 'Numbers', 4, 35, 3, ' فتكون المدن لهم للسكن ومسارحها تكون لبهائمهم وأموالهم ولسائر حيواناتهم '),
(27609, 'Numbers', 4, 35, 4, ' ومسارح المدن التي تعطون اللاويين تكون من سور المدينة إلى جهة الخارج ألف ذراع حواليها '),
(27610, 'Numbers', 4, 35, 5, ' فتقيسون من خارج المدينة جانب الشرق ألفي ذراع ، وجانب الجنوب ألفي ذراع ، وجانب الغرب ألفي ذراع ، وجانب الشمال ألفي ذراع ، وتكون المدينة في الوسط . هذه تكون لهم مسارح المدن '),
(27611, 'Numbers', 4, 35, 6, ' والمدن التي تعطون اللاويين تكون ست منها مدنا للملجإ . تعطونها لكي يهرب إليها القاتل . وفوقها تعطون اثنتين وأربعين مدينة '),
(27612, 'Numbers', 4, 35, 7, ' جميع المدن التي تعطون اللاويين ثماني وأربعون مدينة مع مسارحها '),
(27613, 'Numbers', 4, 35, 8, ' والمدن التي تعطون من ملك بني إسرائيل ، من الكثير تكثرون ، ومن القليل تقللون . كل واحد حسب نصيبه الذي ملكه يعطي من مدنه للاويين '),
(27614, 'Numbers', 4, 35, 9, ' وكلم الرب موسى قائلا '),
(27615, 'Numbers', 4, 35, 10, ' كلم بني إسرائيل وقل لهم : إنكم عابرون الأردن إلى أرض كنعان '),
(27616, 'Numbers', 4, 35, 11, ' فتعينون لأنفسكم مدنا تكون مدن ملجإ لكم ، ليهرب إليها القاتل الذي قتل نفسا سهوا '),
(27617, 'Numbers', 4, 35, 12, ' فتكون لكم المدن ملجإ من الولي ، لكيلا يموت القاتل حتى يقف أمام الجماعة للقضاء '),
(27618, 'Numbers', 4, 35, 13, ' والمدن التي تعطون تكون ست مدن ملجإ لكم '),
(27619, 'Numbers', 4, 35, 14, ' ثلاثا من المدن تعطون في عبر الأردن ، وثلاثا من المدن تعطون في أرض كنعان . مدن ملجإ تكون '),
(27620, 'Numbers', 4, 35, 15, ' لبني إسرائيل وللغريب وللمستوطن في وسطهم تكون هذه الست المدن للملجإ ، لكي يهرب إليها كل من قتل نفسا سهوا '),
(27621, 'Numbers', 4, 35, 16, ' إن ضربه بأداة حديد فمات ، فهو قاتل . إن القاتل يقتل '),
(27622, 'Numbers', 4, 35, 17, ' وإن ضربه بحجر يد مما يقتل به فمات ، فهو قاتل . إن القاتل يقتل '),
(27623, 'Numbers', 4, 35, 18, ' أو ضربه بأداة يد من خشب مما يقتل به ، فهو قاتل . إن القاتل يقتل '),
(27624, 'Numbers', 4, 35, 19, ' ولي الدم يقتل القاتل . حين يصادفه يقتله '),
(27625, 'Numbers', 4, 35, 20, ' وإن دفعه ببغضة أو ألقى عليه شيئا بتعمد فمات '),
(27626, 'Numbers', 4, 35, 21, ' أو ضربه بيده بعداوة فمات ، فإنه يقتل الضارب لأنه قاتل . ولي الدم يقتل القاتل حين يصادفه '),
(27627, 'Numbers', 4, 35, 22, ' ولكن إن دفعه بغتة بلا عداوة ، أو ألقى عليه أداة ما بلا تعمد '),
(27628, 'Numbers', 4, 35, 23, ' أو حجرا ما مما يقتل به بلا رؤية . أسقطه عليه فمات ، وهو ليس عدوا له ولا طالبا أذيته '),
(27629, 'Numbers', 4, 35, 24, ' تقضي الجماعة بين القاتل وبين ولي الدم ، حسب هذه الأحكام '),
(27630, 'Numbers', 4, 35, 25, ' وتنقذ الجماعة القاتل من يد ولي الدم ، وترده الجماعة إلى مدينة ملجئه التي هرب إليها ، فيقيم هناك إلى موت الكاهن العظيم الذي مسح بالدهن المقدس '),
(27631, 'Numbers', 4, 35, 26, ' ولكن إن خرج القاتل من حدود مدينة ملجئه التي هرب إليها '),
(27632, 'Numbers', 4, 35, 27, ' ووجده ولي الدم خارج حدود مدينة ملجئه ، وقتل ولي الدم القاتل ، فليس له دم '),
(27633, 'Numbers', 4, 35, 28, ' لأنه في مدينة ملجئه يقيم إلى موت الكاهن العظيم . وأما بعد موت الكاهن العظيم فيرجع القاتل إلى أرض ملكه '),
(27634, 'Numbers', 4, 35, 29, ' فتكون هذه لكم فريضة حكم إلى أجيالكم في جميع مساكنكم '),
(27635, 'Numbers', 4, 35, 30, ' كل من قتل نفسا فعلى فم شهود يقتل القاتل . وشاهد واحد لا يشهد على نفس للموت '),
(27636, 'Numbers', 4, 35, 31, ' ولا تأخذوا فدية عن نفس القاتل المذنب للموت ، بل إنه يقتل '),
(27637, 'Numbers', 4, 35, 32, ' ولا تأخذوا فدية ليهرب إلى مدينة ملجئه ، فيرجع ويسكن في الأرض بعد موت الكاهن '),
(27638, 'Numbers', 4, 35, 33, ' لا تدنسوا الأرض التي أنتم فيها ، لأن الدم يدنس الأرض . وعن الأرض لا يكفر لأجل الدم الذي سفك فيها ، إلا بدم سافكه '),
(27639, 'Numbers', 4, 35, 34, ' ولا تنجسوا الأرض التي أنتم مقيمون فيها التي أنا ساكن في وسطها . إني أنا الرب ساكن في وسط بني إسرائيل '),
(27640, 'Numbers', 4, 36, 1, ' وتقدم رؤوس الآباء من عشيرة بني جلعاد بن ماكير بن منسى من عشائر بني يوسف ، وتكلموا قدام موسى وقدام الرؤساء رؤوس الآباء من بني إسرائيل '),
(27641, 'Numbers', 4, 36, 2, ' وقالوا : قد أمر الرب سيدي أن يعطي الأرض بقسمة بالقرعة لبني إسرائيل . وقد أمر سيدي من الرب أن يعطي نصيب صلفحاد أخينا لبناته '),
(27642, 'Numbers', 4, 36, 3, ' فإن صرن نساء لأحد من بني أسباط بني إسرائيل ، يؤخذ نصيبهن من نصيب آبائنا ويضاف إلى نصيب السبط الذي صرن له . فمن قرعة نصيبنا يؤخذ '),
(27643, 'Numbers', 4, 36, 4, ' ومتى كان اليوبيل لبني إسرائيل يضاف نصيبهن إلى نصيب السبط الذي صرن له ، ومن نصيب سبط آبائنا يؤخذ نصيبهن '),
(27644, 'Numbers', 4, 36, 5, ' فأمر موسى بني إسرائيل حسب قول الرب قائلا : بحق تكلم سبط بني يوسف '),
(27645, 'Numbers', 4, 36, 6, ' هذا ما أمر به الرب عن بنات صلفحاد قائلا : من حسن في أعينهن يكن له نساء ، ولكن لعشيرة سبط آبائهن يكن نساء '),
(27646, 'Numbers', 4, 36, 7, ' فلا يتحول نصيب لبني إسرائيل من سبط إلى سبط ، بل يلازم بنو إسرائيل كل واحد نصيب سبط آبائه '),
(27647, 'Numbers', 4, 36, 8, ' وكل بنت ورثت نصيبا من أسباط بني إسرائيل تكون امرأة لواحد من عشيرة سبط أبيها ، لكي يرث بنو إسرائيل كل واحد نصيب آبائه '),
(27648, 'Numbers', 4, 36, 9, ' فلا يتحول نصيب من سبط إلى سبط آخر ، بل يلازم أسباط بني إسرائيل كل واحد نصيبه '),
(27649, 'Numbers', 4, 36, 10, ' كما أمر الرب موسى كذلك فعلت بنات صلفحاد '),
(27650, 'Numbers', 4, 36, 11, ' فصارت محلة وترصة وحجلة وملكة ونوعة بنات صلفحاد نساء لبني أعمامهن '),
(27651, 'Numbers', 4, 36, 12, ' صرن نساء من عشائر بني منسى بن يوسف ، فبقي نصيبهن في سبط عشيرة أبيهن '),
(27652, 'Numbers', 4, 36, 13, ' هذه هي الوصايا والأحكام التي أوصى بها الرب إلى بني إسرائيل عن يد موسى ، في عربات موآب على أردن أريحا '),
(27653, 'Numbers', 4, 26, 46, ' واسم ابنة أشير سارح '),
(27654, 'Numbers', 4, 26, 47, ' هذه عشائر بني أشير حسب عددهم ، ثلاثة وخمسون ألفا وأربع مئة '),
(27655, 'Numbers', 4, 26, 48, ' بنو نفتالي حسب عشائرهم : لياحصئيل عشيرة الياحصئيليين . لجوني عشيرة الجونيين '),
(27656, 'Numbers', 4, 26, 49, ' ليصر عشيرة اليصريين . لشليم عشيرة الشليميين '),
(27657, 'Numbers', 4, 26, 50, ' هذه قبائل نفتالي حسب عشائرهم ، والمعدودون منهم خمسة وأربعون ألفا وأربع مئة '),
(27658, 'Numbers', 4, 26, 51, ' هؤلاء المعدودون من بني إسرائيل ست مئة ألف وألف وسبع مئة وثلاثون '),
(27659, 'Numbers', 4, 26, 52, ' ثم كلم الرب موسى قائلا '),
(27660, 'Numbers', 4, 26, 53, ' لهؤلاء تقسم الأرض نصيبا على عدد الأسماء '),
(27661, 'Numbers', 4, 26, 54, ' الكثير تكثر له نصيبه ، والقليل تقلل له نصيبه . كل واحد حسب المعدودين منه يعطى نصيبه '),
(27662, 'Numbers', 4, 26, 55, ' إنما بالقرعة تقسم الأرض . حسب أسماء أسباط آبائهم يملكون '),
(27663, 'Numbers', 4, 26, 56, ' حسب القرعة يقسم نصيبهم بين كثير وقليل '),
(27664, 'Numbers', 4, 26, 57, ' وهؤلاء المعدودون من اللاويين حسب عشائرهم : لجرشون عشيرة الجرشونيين . لقهات عشيرة القهاتيين . لمراري عشيرة المراريين '),
(27665, 'Numbers', 4, 26, 58, ' هذه عشائر لاوي : عشيرة اللبنيين وعشيرة الحبرونيين وعشيرة المحليين وعشيرة الموشيين وعشيرة القورحيين . وأما قهات فولد عمرام '),
(27666, 'Numbers', 4, 26, 59, ' واسم امرأة عمرام يوكابد بنت لاوي التي ولدت للاوي في مصر ، فولدت لعمرام هارون وموسى ومريم أختهما '),
(27667, 'Numbers', 4, 26, 60, ' ولهارون ولد ناداب وأبيهو وألعازار وإيثامار '),
(27668, 'Numbers', 4, 26, 61, ' وأما ناداب وأبيهو فماتا عندما قربا نارا غريبة أمام الرب '),
(27669, 'Numbers', 4, 26, 62, ' وكان المعدودون منهم ثلاثة وعشرين ألفا ، كل ذكر من ابن شهر فصاعدا . لأنهم لم يعدوا بين بني إسرائيل ، إذ لم يعط لهم نصيب بين بني إسرائيل '),
(27670, 'Numbers', 4, 26, 63, ' هؤلاء هم الذين عدهم موسى وألعازار الكاهن حين عدا بني إسرائيل في عربات موآب على أردن أريحا '),
(27671, 'Numbers', 4, 26, 64, ' وفي هؤلاء لم يكن إنسان من الذين عدهم موسى وهارون الكاهن حين عدا بني إسرائيل في برية سيناء '),
(27672, 'Numbers', 4, 26, 65, ' لأن الرب قال لهم إنهم يموتون في البرية ، فلم يبق منهم إنسان إلا كالب بن يفنة ويشوع بن نون '),
(27673, 'Numbers', 4, 27, 1, ' فتقدمت بنات صلفحاد بن حافر بن جلعاد بن ماكير بن منسى ، من عشائر منسى بن يوسف . وهذه أسماء بناته : محلة ونوعة وحجلة وملكة وترصة '),
(27674, 'Numbers', 4, 27, 2, ' ووقفن أمام موسى وألعازار الكاهن وأمام الرؤساء وكل الجماعة لدى باب خيمة الاجتماع قائلات '),
(27675, 'Numbers', 4, 27, 3, ' أبونا مات في البرية ، ولم يكن في القوم الذين اجتمعوا على الرب في جماعة قورح ، بل بخطيته مات ولم يكن له بنون '),
(27676, 'Numbers', 4, 27, 4, ' لماذا يحذف اسم أبينا من بين عشيرته لأنه ليس له ابن ؟ أعطنا ملكا بين إخوة أبينا '),
(27677, 'Numbers', 4, 27, 5, ' فقدم موسى دعواهن أمام الرب '),
(27678, 'Numbers', 4, 27, 6, ' فكلم الرب موسى قائلا '),
(27679, 'Numbers', 4, 27, 7, ' بحق تكلمت بنات صلفحاد ، فتعطيهن ملك نصيب بين إخوة أبيهن ، وتنقل نصيب أبيهن إليهن '),
(27680, 'Numbers', 4, 27, 8, ' وتكلم بني إسرائيل قائلا : أيما رجل مات وليس له ابن ، تنقلون ملكه إلى ابنته '),
(27681, 'Numbers', 4, 27, 9, ' وإن لم تكن له ابنة ، تعطوا ملكه لإخوته '),
(27682, 'Numbers', 4, 27, 10, ' وإن لم يكن له إخوة ، تعطوا ملكه لإخوة أبيه '),
(27683, 'Numbers', 4, 27, 11, ' وإن لم يكن لأبيه إخوة ، تعطوا ملكه لنسيبه الأقرب إليه من عشيرته فيرثه . فصارت لبني إسرائيل فريضة قضاء ، كما أمر الرب موسى '),
(27684, 'Numbers', 4, 27, 12, ' وقال الرب لموسى : اصعد إلى جبل عباريم هذا وانظر الأرض التي أعطيت بني إسرائيل '),
(27685, 'Numbers', 4, 27, 13, ' ومتى نظرتها ، تضم إلى قومك أنت أيضا كما ضم هارون أخوك '),
(27686, 'Numbers', 4, 27, 14, ' لأنكما في برية صين ، عند مخاصمة الجماعة ، عصيتما قولي أن تقدساني بالماء أمام أعينهم . ذلك ماء مريبة قادش في برية صين '),
(27687, 'Numbers', 4, 27, 15, ' فكلم موسى الرب قائلا '),
(27688, 'Numbers', 4, 27, 16, ' ليوكل الرب إله أرواح جميع البشر رجلا على الجماعة '),
(27689, 'Numbers', 4, 27, 17, ' يخرج أمامهم ويدخل أمامهم ويخرجهم ويدخلهم ، لكيلا تكون جماعة الرب كالغنم التي لا راعي لها '),
(27690, 'Numbers', 4, 27, 18, ' فقال الرب لموسى : خذ يشوع بن نون ، رجلا فيه روح ، وضع يدك عليه '),
(27691, 'Numbers', 4, 27, 19, ' وأوقفه قدام ألعازار الكاهن وقدام كل الجماعة ، وأوصه أمام أعينهم '),
(27692, 'Numbers', 4, 27, 20, ' واجعل من هيبتك عليه لكي يسمع له كل جماعة بني إسرائيل '),
(27693, 'Numbers', 4, 27, 21, ' فيقف أمام ألعازار الكاهن فيسأل له بقضاء الأوريم أمام الرب . حسب قوله يخرجون ، وحسب قوله يدخلون ، هو وكل بني إسرائيل معه ، كل الجماعة '),
(27694, 'Numbers', 4, 27, 22, ' ففعل موسى كما أمره الرب . أخذ يشوع وأوقفه قدام ألعازار الكاهن وقدام كل الجماعة '),
(27695, 'Numbers', 4, 27, 23, ' ووضع يديه عليه وأوصاه كما تكلم الرب عن يد موسى '),
(27696, 'Numbers', 4, 28, 1, ' وكلم الرب موسى قائلا '),
(27697, 'Numbers', 4, 28, 2, ' أوص بني إسرائيل وقل لهم : قرباني ، طعامي مع وقائدي رائحة سروري ، تحرصون أن تقربوه لي في وقته '),
(27698, 'Numbers', 4, 28, 3, ' وقل لهم : هذا هو الوقود الذي تقربون للرب : خروفان حوليان صحيحان لكل يوم محرقة دائمة '),
(27699, 'Numbers', 4, 28, 4, ' الخروف الواحد تعمله صباحا ، والخروف الثاني تعمله بين العشاءين '),
(27700, 'Numbers', 4, 28, 5, ' وعشر الإيفة من دقيق ملتوت بربع الهين من زيت الرض تقدمة '),
(27701, 'Numbers', 4, 28, 6, ' محرقة دائمة . هي المعمولة في جبل سيناء . لرائحة سرور ، وقودا للرب '),
(27702, 'Numbers', 4, 28, 7, ' وسكيبها ربع الهين للخروف الواحد . في القدس اسكب سكيب مسكر للرب '),
(27703, 'Numbers', 4, 28, 8, ' والخروف الثاني تعمله بين العشاءين كتقدمة الصباح ، وكسكيبه تعمله وقود رائحة سرور للرب '),
(27704, 'Numbers', 4, 28, 9, ' وفي يوم السبت خروفان حوليان صحيحان ، وعشران من دقيق ملتوت بزيت تقدمة مع سكيبه '),
(27705, 'Numbers', 4, 28, 10, ' محرقة كل سبت ، فضلا عن المحرقة الدائمة وسكيبها '),
(27706, 'Numbers', 4, 28, 11, ' وفي رؤوس شهوركم تقربون محرقة للرب : ثورين ابني بقر ، وكبشا واحدا ، وسبعة خراف حولية صحيحة '),
(27707, 'Numbers', 4, 28, 12, ' وثلاثة أعشار من دقيق ملتوت بزيت تقدمة لكل ثور . وعشرين من دقيق ملتوت بزيت تقدمة للكبش الواحد '),
(27708, 'Numbers', 4, 28, 13, ' وعشرا واحدا من دقيق ملتوت بزيت تقدمة لكل خروف . محرقة رائحة سرور وقودا للرب '),
(27709, 'Numbers', 4, 28, 14, ' وسكائبهن تكون نصف الهين للثور ، وثلث الهين للكبش ، وربع الهين للخروف من خمر . هذه محرقة كل شهر من أشهر السنة '),
(27710, 'Numbers', 4, 28, 15, ' وتيسا واحدا من المعز ذبيحة خطية للرب . فضلا عن المحرقة الدائمة يقرب مع سكيبه '),
(27711, 'Numbers', 4, 28, 16, ' وفي الشهر الأول ، في اليوم الرابع عشر من الشهر فصح للرب '),
(27712, 'Numbers', 4, 28, 17, ' وفي اليوم الخامس عشر من هذا الشهر عيد . سبعة أيام يؤكل فطير '),
(27713, 'Numbers', 4, 28, 18, ' في اليوم الأول محفل مقدس . عملا ما من الشغل لا تعملوا '),
(27714, 'Numbers', 4, 28, 19, ' وتقربون وقودا محرقة للرب : ثورين ابني بقر ، وكبشا واحدا ، وسبعة خراف حولية . صحيحة تكون لكم '),
(27715, 'Numbers', 4, 28, 20, ' وتقدمتهن من دقيق ملتوت بزيت : ثلاثة أعشار تعملون للثور ، وعشرين للكبش '),
(27716, 'Numbers', 4, 28, 21, ' وعشرا واحدا تعمل لكل خروف من السبعة الخراف '),
(27717, 'Numbers', 4, 28, 22, ' وتيسا واحدا ذبيحة خطية للتكفير عنكم '),
(27718, 'Numbers', 4, 28, 23, ' فضلا عن محرقة الصباح التي لمحرقة دائمة تعملون هذه '),
(27719, 'Numbers', 4, 28, 24, ' هكذا تعملون كل يوم ، سبعة أيام طعام وقود رائحة سرور للرب ، فضلا عن المحرقة الدائمة يعمل مع سكيبه '),
(27720, 'Numbers', 4, 28, 25, ' وفي اليوم السابع يكون لكم محفل مقدس . عملا ما من الشغل لا تعملوا '),
(27721, 'Numbers', 4, 28, 26, ' وفي يوم الباكورة ، حين تقربون تقدمة جديدة للرب في أسابيعكم ، يكون لكم محفل مقدس . عملا ما من الشغل لا تعملوا '),
(27722, 'Numbers', 4, 28, 27, ' وتقربون محرقة لرائحة سرور للرب : ثورين ابني بقر ، وكبشا واحدا ، وسبعة خراف حولية '),
(27723, 'Numbers', 4, 28, 28, ' وتقدمتهن من دقيق ملتوت بزيت : ثلاثة أعشار لكل ثور ، وعشرين للكبش الواحد '),
(27724, 'Numbers', 4, 28, 29, ' وعشرا واحدا لكل خروف من السبعة الخراف '),
(27725, 'Numbers', 4, 28, 30, ' وتيسا واحدا من المعز للتكفير عنكم '),
(27726, 'Numbers', 4, 28, 31, ' فضلا عن المحرقة الدائمة وتقدمتها تعملون . مع سكائبهن صحيحات تكون لكم '),
(27727, 'Numbers', 4, 29, 1, ' وفي الشهر السابع ، في الأول من الشهر ، يكون لكم محفل مقدس . عملا ما من الشغل لا تعملوا . يوم هتاف بوق يكون لكم '),
(27728, 'Numbers', 4, 29, 2, ' وتعملون محرقة لرائحة سرور للرب : ثورا واحدا ابن بقر ، وكبشا واحدا ، وسبعة خراف حولية صحيحة '),
(27729, 'Numbers', 4, 29, 3, ' وتقدمتهن من دقيق ملتوت بزيت : ثلاثة أعشار للثور ، وعشرين للكبش '),
(27730, 'Numbers', 4, 29, 4, ' وعشرا واحدا لكل خروف من السبعة الخراف '),
(27731, 'Numbers', 4, 29, 5, ' وتيسا واحدا من المعز ذبيحة خطية للتكفير عنكم '),
(27732, 'Numbers', 4, 29, 6, ' فضلا عن محرقة الشهر وتقدمتها والمحرقة الدائمة وتقدمتها مع سكائبهن كعادتهن رائحة سرور وقودا للرب '),
(27733, 'Numbers', 4, 29, 7, ' وفي عاشر هذا الشهر السابع ، يكون لكم محفل مقدس ، وتذللون أنفسكم . عملا ما لا تعملوا '),
(27734, 'Numbers', 4, 29, 8, ' وتقربون محرقة للرب رائحة سرور : ثورا واحدا ابن بقر ، وكبشا واحدا ، وسبعة خراف حولية . صحيحة تكون لكم '),
(27735, 'Numbers', 4, 29, 9, ' وتقدمتهن من دقيق ملتوت بزيت : ثلاثة أعشار للثور ، وعشران للكبش الواحد '),
(27736, 'Numbers', 4, 29, 10, ' وعشر واحد لكل خروف من السبعة الخراف '),
(27737, 'Numbers', 4, 29, 11, ' وتيسا واحدا من المعز ذبيحة خطية ، فضلا عن ذبيحة الخطية للكفارة والمحرقة الدائمة وتقدمتها مع سكائبهن '),
(27738, 'Numbers', 4, 29, 12, ' وفي اليوم الخامس عشر من الشهر السابع ، يكون لكم محفل مقدس . عملا ما من الشغل لا تعملوا . وتعيدون عيدا للرب سبعة أيام '),
(27739, 'Numbers', 4, 29, 13, ' وتقربون محرقة ، وقود رائحة سرور للرب : ثلاثة عشر ثورا أبناء بقر ، وكبشين ، وأربعة عشر خروفا حوليا . صحيحة تكون لكم '),
(27740, 'Numbers', 4, 29, 14, ' وتقدمتهن من دقيق ملتوت بزيت : ثلاثة أعشار لكل ثور من الثلاثة عشر ثورا ، وعشران لكل كبش من الكبشين '),
(27741, 'Numbers', 4, 29, 15, ' وعشر واحد لكل خروف من الأربعة عشر خروفا '),
(27742, 'Numbers', 4, 29, 16, ' وتيسا واحدا من المعز ذبيحة خطية ، فضلا عن المحرقة الدائمة وتقدمتها وسكيبها '),
(27743, 'Numbers', 4, 29, 17, ' وفي اليوم الثاني : اثني عشر ثورا أبناء بقر ، وكبشين ، وأربعة عشر خروفا حوليا صحيحا '),
(27744, 'Numbers', 4, 29, 18, ' وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة '),
(27745, 'Numbers', 4, 29, 19, ' وتيسا واحدا من المعز ذبيحة خطية ، فضلا عن المحرقة الدائمة وتقدمتها مع سكائبهن '),
(27746, 'Numbers', 4, 29, 20, ' وفي اليوم الثالث : أحد عشر ثورا ، وكبشين ، وأربعة عشر خروفا حوليا صحيحا '),
(27747, 'Numbers', 4, 29, 21, ' وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة '),
(27748, 'Numbers', 4, 29, 22, ' وتيسا واحدا لذبيحة خطية ، فضلا عن المحرقة الدائمة وتقدمتها وسكيبها '),
(27749, 'Numbers', 4, 29, 23, ' وفي اليوم الرابع : عشرة ثيران ، وكبشين ، وأربعة عشر خروفا حوليا صحيحا '),
(27750, 'Numbers', 4, 29, 24, ' وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة '),
(27751, 'Numbers', 4, 29, 25, ' وتيسا واحدا من المعز لذبيحة خطية ، فضلا عن المحرقة الدائمة وتقدمتها وسكيبها '),
(27752, 'Numbers', 4, 29, 26, ' وفي اليوم الخامس : تسعة ثيران ، وكبشين ، وأربعة عشر خروفا حوليا صحيحا '),
(27753, 'Numbers', 4, 29, 27, ' وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة '),
(27754, 'Numbers', 4, 29, 28, ' وتيسا واحدا لذبيحة خطية ، فضلا عن المحرقة الدائمة وتقدمتها وسكيبها '),
(27755, 'Numbers', 4, 29, 29, ' وفي اليوم السادس : ثمانية ثيران ، وكبشين ، وأربعة عشر خروفا حوليا صحيحا '),
(27756, 'Numbers', 4, 29, 30, ' وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة '),
(27757, 'Numbers', 4, 29, 31, ' وتيسا واحدا لذبيحة خطية ، فضلا عن المحرقة الدائمة وتقدمتها وسكيبها '),
(27758, 'Numbers', 4, 29, 32, ' وفي اليوم السابع : سبعة ثيران ، وكبشين ، وأربعة عشر خروفا حوليا صحيحا '),
(27759, 'Numbers', 4, 29, 33, ' وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كعادتهن '),
(27760, 'Numbers', 4, 29, 34, ' وتيسا واحدا لذبيحة خطية ، فضلا عن المحرقة الدائمة وتقدمتها وسكيبها '),
(27761, 'Numbers', 4, 29, 35, ' في اليوم الثامن : يكون لكم اعتكاف . عملا ما من الشغل لا تعملوا '),
(27762, 'Numbers', 4, 29, 36, ' وتقربون محرقة وقودا رائحة سرور للرب : ثورا واحدا ، وكبشا واحدا ، وسبعة خراف حولية صحيحة '),
(27763, 'Numbers', 4, 29, 37, ' وتقدمتهن وسكائبهن للثور والكبش والخراف حسب عددهن كالعادة '),
(27764, 'Numbers', 4, 29, 38, ' وتيسا واحدا لذبيحة خطية ، فضلا عن المحرقة الدائمة وتقدمتها وسكيبها '),
(27765, 'Numbers', 4, 29, 39, ' هذه تقربونها للرب في مواسمكم ، فضلا عن نذوركم ونوافلكم من محرقاتكم وتقدماتكم وسكائبكم وذبائح سلامتكم '),
(27766, 'Numbers', 4, 29, 40, ' فكلم موسى بني إسرائيل حسب كل ما أمر به الرب موسى '),
(27767, 'Numbers', 4, 30, 1, ' وكلم موسى رؤوس أسباط بني إسرائيل قائلا : هذا ما أمر به الرب '),
(27768, 'Numbers', 4, 30, 2, ' إذا نذر رجل نذرا للرب ، أو أقسم قسما أن يلزم نفسه بلازم ، فلا ينقض كلامه . حسب كل ما خرج من فمه يفعل '),
(27769, 'Numbers', 4, 30, 3, ' وأما المرأة فإذا نذرت نذرا للرب والتزمت بلازم في بيت أبيها في صباها '),
(27770, 'Numbers', 4, 30, 4, ' وسمع أبوها نذرها واللازم الذي ألزمت نفسها به ، فإن سكت أبوها لها ، ثبتت كل نذورها . وكل لوازمها التي ألزمت نفسها بها تثبت '),
(27771, 'Numbers', 4, 30, 5, ' وإن نهاها أبوها يوم سمعه ، فكل نذورها ولوازمها التي ألزمت نفسها بها لا تثبت ، والرب يصفح عنها لأن أباها قد نهاها '),
(27772, 'Numbers', 4, 30, 6, ' وإن كانت لزوج ونذورها عليها أو نطق شفتيها الذي ألزمت نفسها به '),
(27773, 'Numbers', 4, 30, 7, ' وسمع زوجها ، فإن سكت في يوم سمعه ثبتت نذورها . ولوازمها التي ألزمت نفسها بها تثبت '),
(27774, 'Numbers', 4, 30, 8, ' وإن نهاها رجلها في يوم سمعه ، فسخ نذرها الذي عليها ونطق شفتيها الذي ألزمت نفسها به ، والرب يصفح عنها '),
(27775, 'Numbers', 4, 30, 9, ' وأما نذر أرملة أو مطلقة ، فكل ما ألزمت نفسها به يثبت عليها '),
(27776, 'Numbers', 4, 30, 10, ' ولكن إن نذرت في بيت زوجها أو ألزمت نفسها بلازم بقسم '),
(27777, 'Numbers', 4, 30, 11, ' وسمع زوجها ، فإن سكت لها ولم ينهها ثبتت كل نذورها . وكل لازم ألزمت نفسها به يثبت '),
(27778, 'Numbers', 4, 30, 12, ' وإن فسخها زوجها في يوم سمعه ، فكل ما خرج من شفتيها من نذورها أو لوازم نفسها لا يثبت . قد فسخها زوجها . والرب يصفح عنها '),
(27779, 'Numbers', 4, 30, 13, ' كل نذر وكل قسم التزام لإذلال النفس ، زوجها يثبته وزوجها يفسخه '),
(27780, 'Numbers', 4, 30, 14, ' وإن سكت لها زوجها من يوم إلى يوم فقد أثبت كل نذورها أو كل لوازمها التي عليها . أثبتها لأنه سكت لها في يوم سمعه '),
(27781, 'Numbers', 4, 30, 15, ' فإن فسخها بعد سمعه فقد حمل ذنبها '),
(27782, 'Numbers', 4, 30, 16, ' هذه هي الفرائض التي أمر بها الرب موسى ، بين الزوج وزوجته ، وبين الأب وابنته في صباها في بيت أبيها '),
(27783, 'Numbers', 4, 31, 1, ' وكلم الرب موسى قائلا '),
(27784, 'Numbers', 4, 31, 2, ' انتقم نقمة لبني إسرائيل من المديانيين ، ثم تضم إلى قومك '),
(27785, 'Numbers', 4, 31, 3, ' فكلم موسى الشعب قائلا : جردوا منكم رجالا للجند ، فيكونوا على مديان ليجعلوا نقمة الرب على مديان '),
(27786, 'Numbers', 4, 31, 4, ' ألفا واحدا من كل سبط من جميع أسباط إسرائيل ترسلون للحرب '),
(27787, 'Numbers', 4, 31, 5, ' فاختير من ألوف إسرائيل ألف من كل سبط . اثنا عشر ألفا مجردون للحرب '),
(27788, 'Numbers', 4, 31, 6, ' فأرسلهم موسى ألفا من كل سبط إلى الحرب ، هم وفينحاس بن ألعازار الكاهن إلى الحرب ، وأمتعة القدس وأبواق الهتاف في يده '),
(27789, 'Numbers', 4, 31, 7, ' فتجندوا على مديان كما أمر الرب وقتلوا كل ذكر '),
(27790, 'Numbers', 4, 31, 8, ' وملوك مديان قتلوهم فوق قتلاهم : أوي وراقم وصور وحور ورابع . خمسة ملوك مديان . وبلعام بن بعور قتلوه بالسيف '),
(27791, 'Numbers', 4, 31, 9, ' وسبى بنو إسرائيل نساء مديان وأطفالهم ، ونهبوا جميع بهائمهم ، وجميع مواشيهم وكل أملاكهم '),
(27792, 'Numbers', 4, 31, 10, ' وأحرقوا جميع مدنهم بمساكنهم ، وجميع حصونهم بالنار '),
(27793, 'Numbers', 4, 31, 11, ' وأخذوا كل الغنيمة وكل النهب من الناس والبهائم '),
(27794, 'Numbers', 4, 31, 12, ' وأتوا إلى موسى وألعازار الكاهن وإلى جماعة بني إسرائيل بالسبي والنهب والغنيمة إلى المحلة إلى عربات موآب التي على أردن أريحا '),
(27795, 'Numbers', 4, 31, 13, ' فخرج موسى وألعازار الكاهن وكل رؤساء الجماعة لاستقبالهم إلى خارج المحلة '),
(27796, 'Numbers', 4, 31, 14, ' فسخط موسى على وكلاء الجيش ، رؤساء الألوف ورؤساء المئات القادمين من جند الحرب '),
(27797, 'Numbers', 4, 31, 15, ' وقال لهم موسى : هل أبقيتم كل أنثى حية '),
(27798, 'Numbers', 4, 31, 16, ' إن هؤلاء كن لبني إسرائيل ، حسب كلام بلعام ، سبب خيانة للرب في أمر فغور ، فكان الوبأ في جماعة الرب '),
(27799, 'Numbers', 4, 31, 17, ' فالآن اقتلوا كل ذكر من الأطفال . وكل امرأة عرفت رجلا بمضاجعة ذكر اقتلوها '),
(27800, 'Numbers', 4, 31, 18, ' لكن جميع الأطفال من النساء اللواتي لم يعرفن مضاجعة ذكر أبقوهن لكم حيات '),
(27801, 'Numbers', 4, 31, 19, ' وأما أنتم فانزلوا خارج المحلة سبعة أيام ، وتطهروا كل من قتل نفسا ، وكل من مس قتيلا ، في اليوم الثالث وفي السابع ، أنتم وسبيكم '),
(27802, 'Numbers', 4, 31, 20, ' وكل ثوب ، وكل متاع من جلد ، وكل مصنوع من شعر معز ، وكل متاع من خشب ، تطهرونه '),
(27803, 'Numbers', 4, 31, 21, ' وقال ألعازار الكاهن لرجال الجند الذين ذهبوا للحرب : هذه فريضة الشريعة التي أمر بها الرب موسى '),
(27804, 'Numbers', 4, 31, 22, ' الذهب والفضة والنحاس والحديد والقصدير والرصاص '),
(27805, 'Numbers', 4, 31, 23, ' كل ما يدخل النار ، تجيزونه في النار فيكون طاهرا ، غير أنه يتطهر بماء النجاسة . وأما كل ما لا يدخل النار فتجيزونه في الماء '),
(27806, 'Numbers', 4, 31, 24, ' وتغسلون ثيابكم في اليوم السابع فتكونون طاهرين ، وبعد ذلك تدخلون المحلة '),
(27807, 'Numbers', 4, 31, 25, ' وكلم الرب موسى قائلا '),
(27808, 'Numbers', 4, 31, 26, ' أحص النهب المسبي من الناس والبهائم ، أنت وألعازار الكاهن ورؤوس آباء الجماعة '),
(27809, 'Numbers', 4, 31, 27, ' ونصف النهب بين الذين باشروا القتال الخارجين إلى الحرب ، وبين كل الجماعة '),
(27810, 'Numbers', 4, 31, 28, ' وارفع زكاة للرب . من رجال الحرب الخارجين إلى القتال واحدة . نفسا من كل خمس مئة من الناس والبقر والحمير والغنم '),
(27811, 'Numbers', 4, 31, 29, ' من نصفهم تأخذونها وتعطونها لألعازار الكاهن رفيعة للرب '),
(27812, 'Numbers', 4, 31, 30, ' ومن نصف بني إسرائيل تأخذ واحدة مأخوذة من كل خمسين من الناس والبقر والحمير والغنم من جميع البهائم ، وتعطيها للاويين الحافظين شعائر مسكن الرب '),
(27813, 'Numbers', 4, 31, 31, ' ففعل موسى وألعازار الكاهن كما أمر الرب موسى '),
(27814, 'Numbers', 4, 31, 32, ' وكان النهب فضلة الغنيمة التي اغتنمها رجال الجند : من الغنم ست مئة وخمسة وسبعين ألفا '),
(27815, 'Numbers', 4, 31, 33, ' ومن البقر اثنين وسبعين ألفا '),
(27816, 'Numbers', 4, 31, 34, ' ومن الحمير واحدا وستين ألفا '),
(27817, 'Numbers', 4, 31, 35, ' ومن نفوس الناس من النساء اللواتي لم يعرفن مضاجعة ذكر ، جميع النفوس اثنين وثلاثين ألفا '),
(27818, 'Numbers', 4, 31, 36, ' وكان النصف نصيب الخارجين إلى الحرب : عدد الغنم ثلاث مئة وسبعة وثلاثين ألفا وخمس مئة '),
(27819, 'Numbers', 4, 31, 37, ' وكانت الزكاة للرب من الغنم ست مئة وخمسة وسبعين '),
(27820, 'Numbers', 4, 31, 38, ' والبقر ستة وثلاثين ألفا ، وزكاتها للرب اثنين وسبعين '),
(27821, 'Numbers', 4, 31, 39, ' والحمير ثلاثين ألفا وخمس مئة ، وزكاتها للرب واحدا وستين '),
(27822, 'Numbers', 4, 31, 40, ' ونفوس الناس ستة عشر ألفا ، وزكاتها للرب اثنين وثلاثين نفسا '),
(27823, 'Numbers', 4, 31, 41, ' فأعطى موسى الزكاة رفيعة الرب لألعازار الكاهن كما أمر الرب موسى '),
(27824, 'Numbers', 4, 31, 42, ' وأما نصف إسرائيل الذي قسمه موسى من الرجال المتجندين '),
(27825, 'Numbers', 4, 31, 43, ' فكان نصف الجماعة من الغنم ثلاث مئة وسبعة وثلاثين ألفا وخمس مئة '),
(27826, 'Numbers', 4, 31, 44, ' ومن البقر ستة وثلاثين ألفا '),
(27827, 'Numbers', 4, 31, 45, ' ومن الحمير ثلاثين ألفا وخمس مئة '),
(27828, 'Numbers', 4, 31, 46, ' ومن نفوس الناس ستة عشر ألفا '),
(27829, 'Numbers', 4, 31, 47, ' فأخذ موسى من نصف بني إسرائيل المأخوذ واحدا من كل خمسين من الناس ومن البهائم ، وأعطاها للاويين الحافظين شعائر مسكن الرب ، كما أمر الرب موسى '),
(27830, 'Numbers', 4, 31, 48, ' ثم تقدم إلى موسى الوكلاء الذين على ألوف الجند ، رؤساء الألوف ورؤساء المئات '),
(27831, 'Numbers', 4, 31, 49, ' وقالوا لموسى : عبيدك قد أخذوا عدد رجال الحرب الذين في أيدينا فلم يفقد منا إنسان '),
(27832, 'Numbers', 4, 31, 50, ' فقد قدمنا قربان الرب ، كل واحد ما وجده ، أمتعة ذهب : حجولا وأساور وخواتم وأقراطا وقلائد ، للتكفير عن أنفسنا أمام الرب '),
(27833, 'Numbers', 4, 31, 51, ' فأخذ موسى وألعازار الكاهن الذهب منهم ، كل أمتعة مصنوعة '),
(27834, 'Numbers', 4, 31, 52, ' وكان كل ذهب الرفيعة التي رفعوها للرب ستة عشر ألفا وسبع مئة وخمسين شاقلا من عند رؤساء الألوف ورؤساء المئات '),
(27835, 'Numbers', 4, 31, 53, ' أما رجال الجند فاغتنموا كل واحد لنفسه '),
(27836, 'Numbers', 4, 31, 54, ' فأخذ موسى وألعازار الكاهن الذهب من رؤساء الألوف والمئات وأتيا به إلى خيمة الاجتماع تذكارا لبني إسرائيل أمام الرب '),
(27837, 'Numbers', 4, 32, 1, ' وأما بنو رأوبين وبنو جاد فكان لهم مواش كثيرة وافرة جدا . فلما رأوا أرض يعزير وأرض جلعاد ، وإذا المكان مكان مواش '),
(27838, 'Numbers', 4, 32, 2, ' أتى بنو جاد وبنو رأوبين وكلموا موسى وألعازار الكاهن ورؤساء الجماعة قائلين '),
(27839, 'Numbers', 4, 32, 3, ' عطاروت وديبون ويعزير ونمرة وحشبون وألعالة وشبام ونبو وبعون '),
(27840, 'Numbers', 4, 32, 4, ' الأرض التي ضربها الرب قدام بني إسرائيل ، هي أرض مواش ، ولعبيدك مواش '),
(27841, 'Numbers', 4, 32, 5, ' ثم قالوا : إن وجدنا نعمة في عينيك فلتعط هذه الأرض لعبيدك ملكا ، ولا تعبرنا الأردن '),
(27842, 'Numbers', 4, 32, 6, ' فقال موسى لبني جاد وبني رأوبين : هل ينطلق إخوتكم إلى الحرب ، وأنتم تقعدون ههنا '),
(27843, 'Numbers', 4, 32, 7, ' فلماذا تصدون قلوب بني إسرائيل عن العبور إلى الأرض التي أعطاهم الرب '),
(27844, 'Numbers', 4, 32, 8, ' هكذا فعل آباؤكم حين أرسلتهم من قادش برنيع لينظروا الأرض '),
(27845, 'Numbers', 4, 32, 9, ' صعدوا إلى وادي أشكول ونظروا الأرض وصدوا قلوب بني إسرائيل عن دخول الأرض التي أعطاهم الرب ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(27846, 'Numbers', 4, 32, 10, ' فحمي غضب الرب في ذلك اليوم وأقسم قائلا '),
(27847, 'Numbers', 4, 32, 11, ' لن يرى الناس الذين صعدوا من مصر ، من ابن عشرين سنة فصاعدا ، الأرض التي أقسمت لإبراهيم وإسحاق ويعقوب ، لأنهم لم يتبعوني تماما '),
(27848, 'Numbers', 4, 32, 12, ' ما عدا كالب بن يفنة القنزي ويشوع بن نون ، لأنهما اتبعا الرب تماما '),
(27849, 'Numbers', 4, 32, 13, ' فحمي غضب الرب على إسرائيل وأتاههم في البرية أربعين سنة ، حتى فني كل الجيل الذي فعل الشر في عيني الرب '),
(27850, 'Numbers', 4, 32, 14, ' فهوذا أنتم قد قمتم عوضا عن آبائكم ، تربية أناس خطاة ، لكي تزيدوا أيضا حمو غضب الرب على إسرائيل '),
(27851, 'Numbers', 4, 32, 15, ' إذا ارتددتم من ورائه ، يعود يتركه أيضا في البرية ، فتهلكون كل هذا الشعب '),
(27852, 'Numbers', 4, 32, 16, ' فاقتربوا إليه وقالوا : نبني صير غنم لمواشينا ههنا ومدنا لأطفالنا '),
(27853, 'Numbers', 4, 32, 17, ' وأما نحن فنتجرد مسرعين قدام بني إسرائيل حتى نأتي بهم إلى مكانهم ، ويلبث أطفالنا في مدن محصنة من وجه سكان الأرض '),
(27854, 'Numbers', 4, 32, 18, ' لا نرجع إلى بيوتنا حتى يقتسم بنو إسرائيل كل واحد نصيبه '),
(27855, 'Numbers', 4, 32, 19, ' إننا لا نملك معهم في عبر الأردن وما وراءه ، لأن نصيبنا قد حصل لنا في عبر الأردن إلى الشرق '),
(27856, 'Numbers', 4, 32, 20, ' فقال لهم موسى : إن فعلتم هذا الأمر ، إن تجردتم أمام الرب للحرب '),
(27857, 'Numbers', 4, 32, 21, ' وعبر الأردن كل متجرد منكم أمام الرب حتى طرد أعداءه من أمامه '),
(27858, 'Numbers', 4, 32, 22, ' وأخضعت الأرض أمام الرب ، وبعد ذلك رجعتم ، فتكونون أبرياء من نحو الرب ومن نحو إسرائيل ، وتكون هذه الأرض ملكا لكم أمام الرب '),
(27859, 'Numbers', 4, 32, 23, ' ولكن إن لم تفعلوا هكذا ، فإنكم تخطئون إلى الرب ، وتعلمون خطيتكم التي تصيبكم '),
(27860, 'Numbers', 4, 32, 24, ' ابنوا لأنفسكم مدنا لأطفالكم وصيرا لغنمكم . وما خرج من أفواهكم افعلوا '),
(27861, 'Numbers', 4, 32, 25, ' فكلم بنو جاد وبنو رأوبين موسى قائلين : عبيدك يفعلون كما أمر سيدي '),
(27862, 'Numbers', 4, 32, 26, ' أطفالنا ونساؤنا ومواشينا وكل بهائمنا تكون هناك في مدن جلعاد '),
(27863, 'Numbers', 4, 32, 27, ' وعبيدك يعبرون ، كل متجرد للجند أمام الرب للحرب كما تكلم سيدي '),
(27864, 'Numbers', 4, 32, 28, ' فأوصى بهم موسى ألعازار الكاهن ويشوع بن نون ورؤوس آباء الأسباط من بني إسرائيل '),
(27865, 'Numbers', 4, 32, 29, ' وقال لهم موسى : إن عبر الأردن معكم بنو جاد وبنو رأوبين ، كل متجرد للحرب أمام الرب ، فمتى أخضعت الأرض أمامكم ، تعطونهم أرض جلعاد ملكا '),
(27866, 'Numbers', 4, 32, 30, ' ولكن إن لم يعبروا متجردين معكم ، يتملكوا في وسطكم في أرض كنعان '),
(27867, 'Numbers', 4, 32, 31, ' فأجاب بنو جاد وبنو رأوبين قائلين : الذي تكلم به الرب عن عبيدك كذلك نفعل '),
(27868, 'Numbers', 4, 32, 32, ' نحن نعبر متجردين أمام الرب إلى أرض كنعان ، ولكن نعطى ملك نصيبنا في عبر الأردن '),
(27869, 'Numbers', 4, 32, 33, ' فأعطى موسى لهم ، لبني جاد وبني رأوبين ونصف سبط منسى بن يوسف ، مملكة سيحون ملك الأموريين ومملكة عوج ملك باشان ، الأرض مع مدنها بتخوم مدن الأرض حواليها '),
(27870, 'Numbers', 4, 32, 34, ' فبنى بنو جاد : ديبون وعطاروت وعروعير '),
(27871, 'Numbers', 4, 32, 35, ' وعطروت شوفان ويعزير ويجبهة '),
(27872, 'Numbers', 4, 32, 36, ' وبيت نمرة وبيت هاران مدنا محصنة مع صير غنم '),
(27873, 'Numbers', 4, 32, 37, ' وبنى بنو رأوبين : حشبون وألعالة وقريتايم '),
(27874, 'Numbers', 4, 32, 38, ' ونبو وبعل معون ، مغيرتي الاسم ، وسبمة ، ودعوا بأسماء أسماء المدن التي بنوا '),
(27875, 'Numbers', 4, 32, 39, ' وذهب بنو ماكير بن منسى إلى جلعاد وأخذوها وطردوا الأموريين الذين فيها '),
(27876, 'Numbers', 4, 32, 40, ' فأعطى موسى جلعاد لماكير بن منسى فسكن فيها '),
(27877, 'Numbers', 4, 32, 41, ' وذهب يائير ابن منسى وأخذ مزارعها ودعاهن : حووث يائير '),
(27878, 'Numbers', 4, 32, 42, ' وذهب نوبح وأخذ قناة وقراها ودعاها نوبح باسمه '),
(27879, 'Numbers', 4, 33, 1, ' هذه رحلات بني إسرائيل الذين خرجوا من أرض مصر بجنودهم عن يد موسى وهارون '),
(27880, 'Numbers', 4, 33, 2, ' وكتب موسى مخارجهم برحلاتهم حسب قول الرب . وهذه رحلاتهم بمخارجهم '),
(27881, 'Numbers', 4, 33, 3, ' ارتحلوا من رعمسيس في الشهر الأول ، في اليوم الخامس عشر من الشهر الأول ، في غد الفصح . خرج بنو إسرائيل بيد رفيعة أمام أعين جميع المصريين '),
(27882, 'Numbers', 4, 33, 4, ' إذ كان المصريون يدفنون الذين ضرب منهم الرب من كل بكر ، والرب قد صنع بآلهتهم أحكاما '),
(27883, 'Numbers', 4, 33, 5, ' فارتحل بنو إسرائيل من رعمسيس ونزلوا في سكوت '),
(27884, 'Numbers', 4, 33, 6, ' ثم ارتحلوا من سكوت ونزلوا في إيثام التي في طرف البرية '),
(27885, 'Numbers', 4, 33, 7, ' ثم ارتحلوا من إيثام ورجعوا على فم الحيروث التي قبالة بعل صفون ونزلوا أمام مجدل '),
(27886, 'Numbers', 4, 33, 8, ' ثم ارتحلوا من أمام الحيروث وعبروا في وسط البحر إلى البرية ، وساروا مسيرة ثلاثة أيام في برية إيثام ونزلوا في مارة '),
(27887, 'Numbers', 4, 33, 9, ' ثم ارتحلوا من مارة وأتوا إلى إيليم . وكان في إيليم اثنتا عشرة عين ماء ، وسبعون نخلة . فنزلوا هناك '),
(27888, 'Numbers', 4, 33, 10, ' ثم ارتحلوا من إيليم ونزلوا على بحر سوف '),
(27889, 'Numbers', 4, 33, 11, ' ثم ارتحلوا من بحر سوف ونزلوا في برية سين '),
(27890, 'Numbers', 4, 33, 12, ' ثم ارتحلوا من برية سين ونزلوا في دفقة '),
(27891, 'Numbers', 4, 33, 13, ' ثم ارتحلوا من دفقة ونزلوا في ألوش '),
(27892, 'Numbers', 4, 33, 14, ' ثم ارتحلوا من ألوش ونزلوا في رفيديم ، ولم يكن هناك ماء للشعب ليشرب '),
(27893, 'Numbers', 4, 33, 15, ' ثم ارتحلوا من رفيديم ونزلوا في برية سيناء '),
(27894, 'Numbers', 4, 33, 16, ' ثم ارتحلوا من برية سيناء ونزلوا في قبروت هتأوة '),
(27895, 'Numbers', 4, 33, 17, ' ثم ارتحلوا من قبروت هتأوة ونزلوا في حضيروت '),
(27896, 'Numbers', 4, 33, 18, ' ثم ارتحلوا من حضيروت ونزلوا في رثمة '),
(27897, 'Numbers', 4, 33, 19, ' ثم ارتحلوا من رثمة ونزلوا في رمون فارص '),
(27898, 'Numbers', 4, 33, 20, ' ثم ارتحلوا من رمون فارص ونزلوا في لبنة '),
(27899, 'Numbers', 4, 33, 21, ' ثم ارتحلوا من لبنة ونزلوا في رسة '),
(27900, 'Numbers', 4, 33, 22, ' ثم ارتحلوا من رسة ونزلوا في قهيلاتة '),
(27901, 'Numbers', 4, 33, 23, ' ثم ارتحلوا من قهيلاتة ونزلوا في جبل شافر '),
(27902, 'Numbers', 4, 33, 24, ' ثم ارتحلوا من جبل شافر ونزلوا في حرادة '),
(27903, 'Numbers', 4, 33, 25, ' ثم ارتحلوا من حرادة ونزلوا في مقهيلوت '),
(27904, 'Numbers', 4, 33, 26, ' ثم ارتحلوا من مقهيلوت ونزلوا في تاحت '),
(27905, 'Numbers', 4, 33, 27, ' ثم ارتحلوا من تاحت ونزلوا في تارح '),
(27906, 'Numbers', 4, 33, 28, ' ثم ارتحلوا من تارح ونزلوا في مثقة '),
(27907, 'Numbers', 4, 33, 29, ' ثم ارتحلوا من مثقة ونزلوا في حشمونة '),
(27908, 'Numbers', 4, 33, 30, ' ثم ارتحلوا من حشمونة ونزلوا في مسيروت '),
(27909, 'Numbers', 4, 33, 31, ' ثم ارتحلوا من مسيروت ونزلوا في بني يعقان '),
(27910, 'Numbers', 4, 33, 32, ' ثم ارتحلوا من بني يعقان ونزلوا في حور الجدجاد '),
(27911, 'Numbers', 4, 33, 33, ' ثم ارتحلوا من حور الجدجاد ونزلوا في يطبات '),
(27912, 'Numbers', 4, 33, 34, ' ثم ارتحلوا من يطبات ونزلوا في عبرونة '),
(27913, 'Numbers', 4, 33, 35, ' ثم ارتحلوا من عبرونة ونزلوا في عصيون جابر '),
(27914, 'Numbers', 4, 33, 36, ' ثم ارتحلوا من عصيون جابر ونزلوا في برية صين وهي قادش '),
(27915, 'Numbers', 4, 33, 37, ' ثم ارتحلوا من قادش ونزلوا في جبل هور في طرف أرض أدوم '),
(27916, 'Numbers', 4, 33, 38, ' فصعد هارون الكاهن إلى جبل هور حسب قول الرب ، ومات هناك في السنة الأربعين لخروج بني إسرائيل من أرض مصر ، في الشهر الخامس في الأول من الشهر '),
(27917, 'Numbers', 4, 33, 39, ' وكان هارون ابن مئة وثلاث وعشرين سنة حين مات في جبل هور '),
(27918, 'Numbers', 4, 33, 40, ' وسمع الكنعاني ملك عراد وهو ساكن في الجنوب في أرض كنعان بمجيء بني إسرائيل '),
(27919, 'Numbers', 4, 33, 41, ' ثم ارتحلوا من جبل هور ونزلوا في صلمونة '),
(27920, 'Numbers', 4, 33, 42, ' ثم ارتحلوا من صلمونة ونزلوا في فونون '),
(27921, 'Numbers', 4, 33, 43, ' ثم ارتحلوا من فونون ونزلوا في أوبوت '),
(27922, 'Numbers', 4, 33, 44, ' ثم ارتحلوا من أوبوت ونزلوا في عيي عباريم في تخم موآب '),
(27923, 'Numbers', 4, 33, 45, ' ثم ارتحلوا من عييم ونزلوا في ديبون جاد '),
(27924, 'Numbers', 4, 33, 46, ' ثم ارتحلوا من ديبون جاد ونزلوا في علمون دبلاتايم '),
(27925, 'Numbers', 4, 33, 47, ' ثم ارتحلوا من علمون دبلاتايم ونزلوا في جبال عباريم أمام نبو '),
(27926, 'Numbers', 4, 33, 48, ' ثم ارتحلوا من جبال عباريم ونزلوا في عربات موآب على أردن أريحا '),
(27927, 'Numbers', 4, 33, 49, ' نزلوا على الأردن من بيت يشيموت إلى آبل شطيم في عربات موآب '),
(27928, 'Numbers', 4, 33, 50, ' وكلم الرب موسى في عربات موآب على أردن أريحا قائلا '),
(27929, 'Numbers', 4, 33, 51, ' كلم بني إسرائيل وقل لهم : إنكم عابرون الأردن إلى أرض كنعان '),
(27930, 'Numbers', 4, 33, 52, ' فتطردون كل سكان الأرض من أمامكم ، وتمحون جميع تصاويرهم ، وتبيدون كل أصنامهم المسبوكة وتخربون جميع مرتفعاتهم '),
(27931, 'Numbers', 4, 33, 53, ' تملكون الأرض وتسكنون فيها لأني قد أعطيتكم الأرض لكي تملكوها '),
(27932, 'Numbers', 4, 33, 54, ' وتقتسمون الأرض بالقرعة حسب عشائركم . الكثير تكثرون له نصيبه والقليل تقللون له نصيبه . حيث خرجت له القرعة فهناك يكون له . حسب أسباط آبائكم تقتسمون '),
(27933, 'Numbers', 4, 33, 55, ' وإن لم تطردوا سكان الأرض من أمامكم يكون الذين تستبقون منهم أشواكا في أعينكم ، ومناخس في جوانبكم ، ويضايقونكم على الأرض التي أنتم ساكنون فيها '),
(27934, 'Numbers', 4, 33, 56, ' فيكون أني أفعل بكم كما هممت أن أفعل بهم '),
(27935, 'Numbers', 4, 34, 1, ' وكلم الرب موسى قائلا '),
(27936, 'Numbers', 4, 34, 2, ' أوص بني إسرائيل وقل لهم : إنكم داخلون إلى أرض كنعان . هذه هي الأرض التي تقع لكم نصيبا . أرض كنعان بتخومها '),
(27937, 'Numbers', 4, 34, 3, ' تكون لكم ناحية الجنوب من برية صين على جانب أدوم ، ويكون لكم تخم الجنوب من طرف بحر الملح إلى الشرق '),
(27938, 'Numbers', 4, 34, 4, ' ويدور لكم التخم من جنوب عقبة عقربيم ، ويعبر إلى صين ، وتكون مخارجه من جنوب قادش برنيع ، ويخرج إلى حصر أدار ، ويعبر إلى عصمون '),
(27939, 'Numbers', 4, 34, 5, ' ثم يدور التخم من عصمون إلى وادي مصر ، وتكون مخارجه عند البحر '),
(27940, 'Numbers', 4, 1, 1, ' وكلم الرب موسى في برية سيناء ، في خيمة الاجتماع ، في أول الشهر الثاني في السنة الثانية لخروجهم من أرض مصر قائلا '),
(27941, 'Numbers', 4, 1, 2, ' أحصوا كل جماعة بني إسرائيل بعشائرهم وبيوت آبائهم ، بعدد الأسماء ، كل ذكر برأسه '),
(27942, 'Numbers', 4, 1, 3, ' من ابن عشرين سنة فصاعدا ، كل خارج للحرب في إسرائيل . تحسبهم أنت وهارون حسب أجنادهم '),
(27943, 'Numbers', 4, 1, 4, ' ويكون معكما رجل لكل سبط ، رجل هو رأس لبيت آبائه '),
(27944, 'Numbers', 4, 1, 5, ' وهذه أسماء الرجال الذين يقفون معكما : لرأوبين أليصور بن شديئور '),
(27945, 'Numbers', 4, 1, 6, ' لشمعون شلوميئيل بن صوريشداي '),
(27946, 'Numbers', 4, 1, 7, ' ليهوذا نحشون بن عميناداب '),
(27947, 'Numbers', 4, 1, 8, ' ليساكر نثنائيل بن صوغر '),
(27948, 'Numbers', 4, 1, 9, ' لزبولون أليآب بن حيلون '),
(27949, 'Numbers', 4, 1, 10, ' لابني يوسف : لأفرايم أليشمع بن عميهود ، ولمنسى جمليئيل بن فدهصور '),
(27950, 'Numbers', 4, 1, 11, ' لبنيامين أبيدن بن جدعوني '),
(27951, 'Numbers', 4, 1, 12, ' لدان أخيعزر بن عميشداي '),
(27952, 'Numbers', 4, 1, 13, ' لأشير فجعيئيل بن عكرن '),
(27953, 'Numbers', 4, 1, 14, ' لجاد ألياساف بن دعوئيل '),
(27954, 'Numbers', 4, 1, 15, ' لنفتالي أخيرع بن عينن '),
(27955, 'Numbers', 4, 1, 16, ' هؤلاء هم مشاهير الجماعة ، رؤساء أسباط آبائهم . رؤوس ألوف إسرائيل '),
(27956, 'Numbers', 4, 1, 17, ' فأخذ موسى وهارون هؤلاء الرجال الذين تعينوا بأسمائهم '),
(27957, 'Numbers', 4, 1, 18, ' وجمعا كل الجماعة في أول الشهر الثاني ، فانتسبوا إلى عشائرهم وبيوت آبائهم بعدد الأسماء ، من ابن عشرين سنة فصاعدا برؤوسهم '),
(27958, 'Numbers', 4, 1, 19, ' كما أمر الرب موسى . فعدهم في برية سيناء '),
(27959, 'Numbers', 4, 1, 20, ' فكان بنو رأوبين بكر إسرائيل ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء برؤوسهم ، كل ذكر من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27960, 'Numbers', 4, 1, 21, ' كان المعدودون منهم لسبط رأوبين ستة وأربعين ألفا وخمس مئة '),
(27961, 'Numbers', 4, 1, 22, ' بنو شمعون ، تواليدهم حسب عشائرهم وبيوت آبائهم ، المعدودون منهم بعدد الأسماء برؤوسهم ، كل ذكر من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27962, 'Numbers', 4, 1, 23, ' المعدودون منهم لسبط شمعون تسعة وخمسون ألفا وثلاث مئة '),
(27963, 'Numbers', 4, 1, 24, ' بنو جاد ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27964, 'Numbers', 4, 1, 25, ' المعدودون منهم لسبط جاد خمسة وأربعون ألفا وست مئة وخمسون '),
(27965, 'Numbers', 4, 1, 26, ' بنو يهوذا ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27966, 'Numbers', 4, 1, 27, ' المعدودون منهم لسبط يهوذا أربعة وسبعون ألفا وست مئة '),
(27967, 'Numbers', 4, 1, 28, ' بنو يساكر ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27968, 'Numbers', 4, 1, 29, ' المعدودون منهم لسبط يساكر أربعة وخمسون ألفا وأربع مئة '),
(27969, 'Numbers', 4, 1, 30, ' بنو زبولون ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27970, 'Numbers', 4, 1, 31, ' المعدودون منهم لسبط زبولون سبعة وخمسون ألفا وأربع مئة '),
(27971, 'Numbers', 4, 1, 32, ' بنو يوسف : بنو أفرايم ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27972, 'Numbers', 4, 1, 33, ' المعدودون منهم لسبط أفرايم أربعون ألفا وخمس مئة '),
(27973, 'Numbers', 4, 1, 34, ' بنو منسى ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27974, 'Numbers', 4, 1, 35, ' المعدودون منهم لسبط منسى اثنان وثلاثون ألفا ومئتان '),
(27975, 'Numbers', 4, 1, 36, ' بنو بنيامين ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27976, 'Numbers', 4, 1, 37, ' المعدودون منهم لسبط بنيامين خمسة وثلاثون ألفا وأربع مئة '),
(27977, 'Numbers', 4, 1, 38, ' بنو دان ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27978, 'Numbers', 4, 1, 39, ' المعدودون منهم لسبط دان اثنان وستون ألفا وسبع مئة '),
(27979, 'Numbers', 4, 1, 40, ' بنو أشير ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27980, 'Numbers', 4, 1, 41, ' المعدودون منهم لسبط أشير واحد وأربعون ألفا وخمس مئة '),
(27981, 'Numbers', 4, 1, 42, ' بنو نفتالي ، تواليدهم حسب عشائرهم وبيوت آبائهم ، بعدد الأسماء من ابن عشرين سنة فصاعدا ، كل خارج للحرب '),
(27982, 'Numbers', 4, 1, 43, ' المعدودون منهم لسبط نفتالي ثلاثة وخمسون ألفا وأربع مئة '),
(27983, 'Numbers', 4, 1, 44, ' هؤلاء هم المعدودون الذين عدهم موسى وهارون ورؤساء إسرائيل ، اثنا عشر رجلا ، رجل واحد لبيت آبائه '),
(27984, 'Numbers', 4, 1, 45, ' فكان جميع المعدودين من بني إسرائيل حسب بيوت آبائهم من ابن عشرين سنة فصاعدا ، كل خارج للحرب في إسرائيل '),
(27985, 'Numbers', 4, 1, 46, ' كان جميع المعدودين ست مئة ألف وثلاثة آلاف وخمس مئة وخمسين '),
(27986, 'Numbers', 4, 1, 47, ' وأما اللاويون حسب سبط آبائهم فلم يعدوا بينهم '),
(27987, 'Numbers', 4, 1, 48, ' إذ كلم الرب موسى قائلا '),
(27988, 'Numbers', 4, 1, 49, ' أما سبط لاوي فلا تحسبه ولا تعده بين بني إسرائيل '),
(27989, 'Numbers', 4, 1, 50, ' بل وكل اللاويين على مسكن الشهادة وعلى جميع أمتعته وعلى كل ما له . هم يحملون المسكن وكل أمتعته ، وهم يخدمونه ، وحول المسكن ينزلون '),
(27990, 'Numbers', 4, 1, 51, ' فعند ارتحال المسكن ينزله اللاويون وعند نزول المسكن يقيمه اللاويون . والأجنبي الذي يقترب يقتل '),
(27991, 'Numbers', 4, 1, 52, ' وينزل بنو إسرائيل كل في محلته وكل عند رايته بأجنادهم '),
(27992, 'Numbers', 4, 1, 53, ' وأما اللاويون فينزلون حول مسكن الشهادة لكي لا يكون سخط على جماعة بني إسرائيل ، فيحفظ اللاويون شعائر مسكن الشهادة '),
(27993, 'Numbers', 4, 1, 54, ' ففعل بنو إسرائيل حسب كل ما أمر الرب موسى كذلك فعلوا '),
(27994, 'Numbers', 4, 2, 1, ' وكلم الرب موسى وهارون قائلا '),
(27995, 'Numbers', 4, 2, 2, ' ينزل بنو إسرائيل كل عند رايته بأعلام لبيوت آبائهم . قبالة خيمة الاجتماع حولها ينزلون '),
(27996, 'Numbers', 4, 2, 3, ' فالنازلون إلى الشرق ، نحو الشروق ، راية محلة يهوذا حسب أجنادهم ، والرئيس لبني يهوذا نحشون بن عميناداب '),
(27997, 'Numbers', 4, 2, 4, ' وجنده المعدودون منهم أربعة وسبعون ألفا وست مئة '),
(27998, 'Numbers', 4, 2, 5, ' والنازلون معه سبط يساكر ، والرئيس لبني يساكر نثنائيل بن صوغر '),
(27999, 'Numbers', 4, 2, 6, ' وجنده المعدودون منه أربعة وخمسون ألفا وأربع مئة '),
(28000, 'Numbers', 4, 2, 7, ' وسبط زبولون ، والرئيس لبني زبولون أليآب بن حيلون '),
(28001, 'Numbers', 4, 2, 8, ' وجنده المعدودون منه سبعة وخمسون ألفا وأربع مئة '),
(28002, 'Numbers', 4, 2, 9, ' جميع المعدودين لمحلة يهوذا مئة ألف وستة وثمانون ألفا وأربع مئة بأجنادهم . يرتحلون أولا '),
(28003, 'Numbers', 4, 2, 10, ' راية محلة رأوبين إلى التيمن حسب أجنادهم ، والرئيس لبني رأوبين أليصور بن شديئور '),
(28004, 'Numbers', 4, 2, 11, ' وجنده المعدودون منه ستة وأربعون ألفا وخمس مئة '),
(28005, 'Numbers', 4, 2, 12, ' والنازلون معه سبط شمعون ، والرئيس لبني شمعون شلوميئيل بن صوريشداي '),
(28006, 'Numbers', 4, 2, 13, ' وجنده المعدودون منهم تسعة وخمسون ألفا وثلاث مئة '),
(28007, 'Numbers', 4, 2, 14, ' وسبط جاد ، والرئيس لبني جاد ألياساف بن رعوئيل '),
(28008, 'Numbers', 4, 2, 15, ' وجنده المعدودون منهم خمسة وأربعون ألفا وست مئة وخمسون '),
(28009, 'Numbers', 4, 2, 16, ' جميع المعدودين لمحلة رأوبين مئة ألف وواحد وخمسون ألفا وأربع مئة وخمسون بأجنادهم ، ويرتحلون ثانية '),
(28010, 'Numbers', 4, 2, 17, ' ثم ترتحل خيمة الاجتماع . محلة اللاويين في وسط المحلات . كما ينزلون كذلك يرتحلون . كل في موضعه براياتهم '),
(28011, 'Numbers', 4, 2, 18, ' راية محلة أفرايم حسب أجنادهم إلى الغرب ، والرئيس لبني أفرايم أليشمع بن عميهود '),
(28012, 'Numbers', 4, 2, 19, ' وجنده المعدودون منهم أربعون ألفا وخمس مئة '),
(28013, 'Numbers', 4, 2, 20, ' ومعه سبط منسى ، والرئيس لبني منسى جمليئيل بن فدهصور '),
(28014, 'Numbers', 4, 2, 21, ' وجنده المعدودون منهم اثنان وثلاثون ألفا ومئتان '),
(28015, 'Numbers', 4, 2, 22, ' وسبط بنيامين ، والرئيس لبني بنيامين أبيدن بن جدعوني '),
(28016, 'Numbers', 4, 2, 23, ' وجنده المعدودون منهم خمسة وثلاثون ألفا وأربع مئة '),
(28017, 'Numbers', 4, 2, 24, ' جميع المعدودين لمحلة أفرايم مئة ألف وثمانية آلاف ومئة بأجنادهم ، ويرتحلون ثالثة '),
(28018, 'Numbers', 4, 2, 25, ' راية محلة دان إلى الشمال حسب أجنادهم ، والرئيس لبني دان أخيعزر بن عميشداي '),
(28019, 'Numbers', 4, 2, 26, ' وجنده المعدودون منهم اثنان وستون ألفا وسبع مئة '),
(28020, 'Numbers', 4, 2, 27, ' والنازلون معه سبط أشير ، والرئيس لبني أشير فجعيئيل بن عكرن '),
(28021, 'Numbers', 4, 2, 28, ' وجنده المعدودون منهم واحد وأربعون ألفا وخمس مئة '),
(28022, 'Numbers', 4, 2, 29, ' وسبط نفتالي ، والرئيس لبني نفتالي أخيرع بن عينن '),
(28023, 'Numbers', 4, 2, 30, ' وجنده المعدودون منهم ثلاثة وخمسون ألفا وأربع مئة '),
(28024, 'Numbers', 4, 2, 31, ' جميع المعدودين لمحلة دان مئة ألف وسبعة وخمسون ألفا وست مئة . يرتحلون أخيرا براياتهم '),
(28025, 'Numbers', 4, 2, 32, ' هؤلاء هم المعدودون من بني إسرائيل حسب بيوت آبائهم . جميع المعدودين من المحلات بأجنادهم ست مئة ألف وثلاثة آلاف وخمس مئة وخمسون '),
(28026, 'Numbers', 4, 2, 33, ' وأما اللاويون فلم يعدوا بين بني إسرائيل ، كما أمر الرب موسى '),
(28027, 'Numbers', 4, 2, 34, ' ففعل بنو إسرائيل حسب كل ما أمر به الرب موسى . هكذا نزلوا براياتهم ، وهكذا ارتحلوا . كل حسب عشائره مع بيت آبائه '),
(28028, 'Numbers', 4, 3, 1, ' وهذه تواليد هارون وموسى يوم كلم الرب موسى في جبل سيناء '),
(28029, 'Numbers', 4, 3, 2, ' وهذه أسماء بني هارون : ناداب البكر ، وأبيهو وألعازار وإيثامار '),
(28030, 'Numbers', 4, 3, 3, ' هذه أسماء بني هارون الكهنة الممسوحين الذين ملأ أيديهم للكهانة '),
(28031, 'Numbers', 4, 3, 4, ' ولكن مات ناداب وأبيهو أمام الرب عندما قربا نارا غريبة أمام الرب في برية سيناء ، ولم يكن لهما بنون . وأما ألعازار وإيثامار فكهنا أمام هارون أبيهما '),
(28032, 'Numbers', 4, 3, 5, ' وكلم الرب موسى قائلا '),
(28033, 'Numbers', 4, 3, 6, ' قدم سبط لاوي وأوقفهم قدام هارون الكاهن وليخدموه '),
(28034, 'Numbers', 4, 3, 7, ' فيحفظون شعائره وشعائر كل الجماعة قدام خيمة الاجتماع ، ويخدمون خدمة المسكن '),
(28035, 'Numbers', 4, 3, 8, ' فيحرسون كل أمتعة خيمة الاجتماع ، وحراسة بني إسرائيل ويخدمون خدمة المسكن '),
(28036, 'Numbers', 4, 3, 9, ' فتعطي اللاويين لهارون ولبنيه . إنهم موهوبون له هبة من عند بني إسرائيل '),
(28037, 'Numbers', 4, 3, 10, ' وتوكل هارون وبنيه فيحرسون كهنوتهم ، والأجنبي الذي يقترب يقتل '),
(28038, 'Numbers', 4, 3, 11, ' وكلم الرب موسى قائلا '),
(28039, 'Numbers', 4, 3, 12, ' وها إني قد أخذت اللاويين من بين بني إسرائيل ، بدل كل بكر فاتح رحم من بني إسرائيل فيكون اللاويون لي '),
(28040, 'Numbers', 4, 3, 13, ' لأن لي كل بكر . يوم ضربت كل بكر في أرض مصر قدست لي كل بكر في إسرائيل من الناس والبهائم . لي يكونون . أنا الرب '),
(28041, 'Numbers', 4, 3, 14, ' وكلم الرب موسى في برية سيناء قائلا '),
(28042, 'Numbers', 4, 3, 15, ' عد بني لاوي حسب بيوت آبائهم وعشائرهم . كل ذكر من ابن شهر فصاعدا تعدهم '),
(28043, 'Numbers', 4, 3, 16, ' فعدهم موسى حسب قول الرب كما أمر '),
(28044, 'Numbers', 4, 3, 17, ' وكان هؤلاء بني لاوي بأسمائهم : جرشون وقهات ومراري '),
(28045, 'Numbers', 4, 3, 18, ' وهذان اسما ابني جرشون حسب عشائرهما : لبني وشمعي '),
(28046, 'Numbers', 4, 3, 19, ' وبنو قهات حسب عشائرهم : عمرام ويصهار وحبرون وعزيئيل '),
(28047, 'Numbers', 4, 3, 20, ' وابنا مراري حسب عشائرهما : محلي وموشي . هذه هي عشائر اللاويين حسب بيوت آبائهم '),
(28048, 'Numbers', 4, 3, 21, ' لجرشون عشيرة اللبنيين وعشيرة الشمعيين . هذه هي عشائر الجرشونيين '),
(28049, 'Numbers', 4, 3, 22, ' المعدودون منهم بعدد كل ذكر من ابن شهر فصاعدا ، المعدودون منهم سبعة آلاف وخمس مئة '),
(28050, 'Numbers', 4, 3, 23, ' عشائر الجرشونيين ينزلون وراء المسكن إلى الغرب '),
(28051, 'Numbers', 4, 3, 24, ' والرئيس لبيت أبي الجرشونيين ألياساف بن لايل '),
(28052, 'Numbers', 4, 3, 25, ' وحراسة بني جرشون في خيمة الاجتماع : المسكن ، والخيمة وغطاؤها ، وسجف باب خيمة الاجتماع '),
(28053, 'Numbers', 4, 3, 26, ' وأستار الدار وسجف باب الدار اللواتي حول المسكن وحول المذبح محيطا وأطنابه مع كل خدمته '),
(28054, 'Numbers', 4, 3, 27, ' ولقهات عشيرة العمراميين وعشيرة اليصهاريين وعشيرة الحبرونيين وعشيرة العزيئيليين . هذه عشائر القهاتيين '),
(28055, 'Numbers', 4, 3, 28, ' بعدد كل ذكر من ابن شهر فصاعدا ثمانية آلاف وست مئة حارسين حراسة القدس '),
(28056, 'Numbers', 4, 3, 29, ' وعشائر بني قهات ينزلون على جانب المسكن إلى التيمن '),
(28057, 'Numbers', 4, 3, 30, ' والرئيس لبيت أبي عشيرة القهاتيين أليصافان بن عزيئيل '),
(28058, 'Numbers', 4, 3, 31, ' وحراستهم التابوت والمائدة والمنارة والمذبحان وأمتعة القدس التي يخدمون بها ، والحجاب وكل خدمته '),
(28059, 'Numbers', 4, 3, 32, ' ولرئيس رؤساء اللاويين ألعازار بن هارون الكاهن وكالة حراس حراسة القدس '),
(28060, 'Numbers', 4, 3, 33, ' ولمراري عشيرة المحليين وعشيرة الموشيين . هذه هي عشائر مراري '),
(28061, 'Numbers', 4, 3, 34, ' والمعدودون منهم بعدد كل ذكر من ابن شهر فصاعدا ستة آلاف ومئتان '),
(28062, 'Numbers', 4, 3, 35, ' والرئيس لبيت أبي عشائر مراري صوريئيل بن أبيحايل . ينزلون على جانب المسكن إلى الشمال '),
(28063, 'Numbers', 4, 3, 36, ' ووكالة حراسة بني مراري : ألواح المسكن وعوارضه وأعمدته وفرضه وكل أمتعته وكل خدمته '),
(28064, 'Numbers', 4, 3, 37, ' وأعمدة الدار حواليها وفرضها وأوتادها وأطنابها '),
(28065, 'Numbers', 4, 3, 38, ' والنازلون قدام المسكن إلى الشرق قدام خيمة الاجتماع ، نحو الشروق ، هم موسى وهارون وبنوه ، حارسين حراسة المقدس لحراسة بني إسرائيل ، والأجنبي الذي يقترب يقتل '),
(28066, 'Numbers', 4, 3, 39, ' جميع المعدودين من اللاويين الذين عدهم موسى وهارون حسب قول الرب بعشائرهم ، كل ذكر من ابن شهر فصاعدا ، اثنان وعشرون ألفا '),
(28067, 'Numbers', 4, 3, 40, ' وقال الرب لموسى : عد كل بكر ذكر من بني إسرائيل من ابن شهر فصاعدا ، وخذ عدد أسمائهم '),
(28068, 'Numbers', 4, 3, 41, ' فتأخذ اللاويين لي . أنا الرب . بدل كل بكر في بني إسرائيل . وبهائم اللاويين بدل كل بكر في بهائم بني إسرائيل '),
(28069, 'Numbers', 4, 3, 42, ' فعد موسى كما أمره الرب كل بكر في بني إسرائيل '),
(28070, 'Numbers', 4, 3, 43, ' فكان جميع الأبكار الذكور بعدد الأسماء من ابن شهر فصاعدا ، المعدودين منهم اثنين وعشرين ألفا ومئتين وثلاثة وسبعين '),
(28071, 'Numbers', 4, 3, 44, ' وكلم الرب موسى قائلا '),
(28072, 'Numbers', 4, 3, 45, ' خذ اللاويين بدل كل بكر في بني إسرائيل ، وبهائم اللاويين بدل بهائمهم ، فيكون لي اللاويون . أنا الرب '),
(28073, 'Numbers', 4, 3, 46, ' وأما فداء المئتين والثلاثة والسبعين الزائدين على اللاويين من أبكار بني إسرائيل '),
(28074, 'Numbers', 4, 3, 47, ' فتأخذ خمسة شواقل لكل رأس . على شاقل القدس تأخذها . عشرون جيرة الشاقل '),
(28075, 'Numbers', 4, 3, 48, ' وتعطي الفضة لهارون وبنيه فداء الزائدين عليهم '),
(28076, 'Numbers', 4, 3, 49, ' فأخذ موسى فضة فدائهم من الزائدين على فداء اللاويين '),
(28077, 'Numbers', 4, 3, 50, ' من أبكار بني إسرائيل أخذ الفضة ألفا وثلاث مئة وخمسة وستين على شاقل القدس '),
(28078, 'Numbers', 4, 3, 51, ' وأعطى موسى فضة الفداء لهارون وبنيه حسب قول الرب ، كما أمر الرب موسى '),
(28079, 'Numbers', 4, 4, 1, ' وكلم الرب موسى وهارون قائلا '),
(28080, 'Numbers', 4, 4, 2, ' خذ عدد بني قهات من بين بني لاوي حسب عشائرهم وبيوت آبائهم '),
(28081, 'Numbers', 4, 4, 3, ' من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة ، كل داخل في الجند ليعمل عملا في خيمة الاجتماع '),
(28082, 'Numbers', 4, 4, 4, ' هذه خدمة بني قهات في خيمة الاجتماع : قدس الأقداس '),
(28083, 'Numbers', 4, 4, 5, ' يأتي هارون وبنوه عند ارتحال المحلة وينزلون حجاب السجف ويغطون به تابوت الشهادة '),
(28084, 'Numbers', 4, 4, 6, ' ويجعلون عليه غطاء من جلد تخس ، ويبسطون من فوق ثوبا كله أسمانجوني ، ويضعون عصيه '),
(28085, 'Numbers', 4, 4, 7, ' وعلى مائدة الوجوه يبسطون ثوب أسمانجون ، ويضعون عليه الصحاف والصحون والأقداح وكاسات السكيب ، ويكون الخبز الدائم عليه '),
(28086, 'Numbers', 4, 4, 8, ' ويبسطون عليها ثوب قرمز ويغطونه بغطاء من جلد تخس ويضعون عصيه '),
(28087, 'Numbers', 4, 4, 9, ' ويأخذون ثوب أسمانجون ويغطون منارة الضوء وسرجها وملاقطها ومنافضها وجميع آنية زيتها التي يخدمونها بها '),
(28088, 'Numbers', 4, 4, 10, ' ويجعلونها وجميع آنيتها في غطاء من جلد تخس ، ويجعلونه على العتلة '),
(28089, 'Numbers', 4, 4, 11, ' وعلى مذبح الذهب يبسطون ثوب أسمانجون ، ويغطونه بغطاء من جلد تخس ويضعون عصيه '),
(28090, 'Numbers', 4, 4, 12, ' ويأخذون جميع أمتعة الخدمة التي يخدمون بها في القدس ، ويجعلونها في ثوب أسمانجون ويغطونها بغطاء من جلد تخس ، ويجعلونها على العتلة '),
(28091, 'Numbers', 4, 4, 13, ' ويرفعون رماد المذبح ، ويبسطون عليه ثوب أرجوان '),
(28092, 'Numbers', 4, 4, 14, ' ويجعلون عليه جميع أمتعته التي يخدمون عليه بها : المجامر والمناشل والرفوش والمناضح ، كل أمتعة المذبح ، ويبسطون عليه غطاء من جلد تخس ، ويضعون عصيه '),
(28093, 'Numbers', 4, 4, 15, ' ومتى فرغ هارون وبنوه من تغطية القدس وجميع أمتعة القدس عند ارتحال المحلة ، يأتي بعد ذلك بنو قهات للحمل ولكن لا يمسوا القدس لئلا يموتوا . ذلك حمل بني قهات في خيمة الاجتماع '),
(28094, 'Numbers', 4, 4, 16, ' ووكالة ألعازار بن هارون الكاهن هي زيت الضوء والبخور العطر والتقدمة الدائمة ودهن المسحة ، ووكالة كل المسكن وكل ما فيه بالقدس وأمتعته '),
(28095, 'Numbers', 4, 4, 17, ' وكلم الرب موسى وهارون قائلا '),
(28096, 'Numbers', 4, 4, 18, ' لا تقرضا سبط عشائر القهاتيين من بين اللاويين '),
(28097, 'Numbers', 4, 4, 19, ' بل افعلا لهم هذا فيعيشوا ولا يموتوا عند اقترابهم إلى قدس الأقداس : يدخل هارون وبنوه ويقيمونهم كل إنسان على خدمته وحمله '),
(28098, 'Numbers', 4, 4, 20, ' ولا يدخلوا ليروا القدس لحظة لئلا يموتوا '),
(28099, 'Numbers', 4, 4, 21, ' وكلم الرب موسى قائلا '),
(28100, 'Numbers', 4, 4, 22, ' خذ عدد بني جرشون أيضا حسب بيوت آبائهم وعشائرهم '),
(28101, 'Numbers', 4, 4, 23, ' من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة تعدهم ، كل الداخلين ليتجندوا أجنادا ، ليخدموا خدمة في خيمة الاجتماع '),
(28102, 'Numbers', 4, 4, 24, ' هذه خدمة عشائر الجرشونيين من الخدمة والحمل '),
(28103, 'Numbers', 4, 4, 25, ' يحملون شقق المسكن ، وخيمة الاجتماع وغطاءها ، وغطاء التخس الذي عليها من فوق ، وسجف باب خيمة الاجتماع '),
(28104, 'Numbers', 4, 4, 26, ' وأستار الدار وسجف مدخل باب الدار اللواتي حول المسكن وحول المذبح محيطة ، وأطنابهن وكل أمتعة خدمتهن . وكل ما يعمل لهن فهم يصنعونه '),
(28105, 'Numbers', 4, 4, 27, ' حسب قول هارون وبنيه تكون جميع خدمة بني الجرشونيين من كل حملهم ومن كل خدمتهم . وتوكلهم بحراسة كل أحمالهم '),
(28106, 'Numbers', 4, 4, 28, ' هذه خدمة عشائر بني الجرشونيين في خيمة الاجتماع ، وحراستهم بيد إيثامار بن هارون الكاهن '),
(28107, 'Numbers', 4, 4, 29, ' بنو مراري حسب عشائرهم وبيوت آبائهم تعدهم '),
(28108, 'Numbers', 4, 4, 30, ' من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة تعدهم ، كل الداخلين في الجند ليخدموا خدمة خيمة الاجتماع '),
(28109, 'Numbers', 4, 4, 31, ' وهذه حراسة حملهم وكل خدمتهم في خيمة الاجتماع : ألواح المسكن وعوارضه وأعمدته وفرضه '),
(28110, 'Numbers', 4, 4, 32, ' وأعمدة الدار حواليها وفرضها وأوتادها وأطنابها مع كل أمتعتها وكل خدمتها . وبالأسماء تعدون أمتعة حراسة حملهم '),
(28111, 'Numbers', 4, 4, 33, ' هذه خدمة عشائر بني مراري . كل خدمتهم في خيمة الاجتماع بيد إيثامار بن هارون الكاهن '),
(28112, 'Numbers', 4, 4, 34, ' فعد موسى وهارون ورؤساء الجماعة بني القهاتيين حسب عشائرهم وبيوت آبائهم '),
(28113, 'Numbers', 4, 4, 35, ' من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة ، كل الداخلين في الجند للخدمة في خيمة الاجتماع '),
(28114, 'Numbers', 4, 4, 36, ' فكان المعدودون منهم حسب عشائرهم ألفين وسبع مئة وخمسين '),
(28115, 'Numbers', 4, 4, 37, ' هؤلاء هم المعدودون من عشائر القهاتيين ، كل الخادمين في خيمة الاجتماع الذين عدهم موسى وهارون حسب قول الرب عن يد موسى '),
(28116, 'Numbers', 4, 4, 38, ' والمعدودون من بني جرشون حسب عشائرهم وبيوت آبائهم '),
(28117, 'Numbers', 4, 4, 39, ' من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة ، كل الداخلين في الجند للخدمة في خيمة الاجتماع '),
(28118, 'Numbers', 4, 4, 40, ' كان المعدودون منهم حسب عشائرهم وبيوت آبائهم ألفين وست مئة وثلاثين '),
(28119, 'Numbers', 4, 4, 41, ' هؤلاء هم المعدودون من عشائر بني جرشون ، كل الخادمين في خيمة الاجتماع الذين عدهم موسى وهارون حسب قول الرب '),
(28120, 'Numbers', 4, 4, 42, ' والمعدودون من عشائر بني مراري حسب عشائرهم وبيوت آبائهم '),
(28121, 'Numbers', 4, 4, 43, ' من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة ، كل الداخلين في الجند للخدمة في خيمة الاجتماع '),
(28122, 'Numbers', 4, 4, 44, ' كان المعدودون منهم حسب عشائرهم ثلاثة آلاف ومئتين '),
(28123, 'Numbers', 4, 4, 45, ' هؤلاء هم المعدودون من عشائر بني مراري الذين عدهم موسى وهارون حسب قول الرب عن يد موسى '),
(28124, 'Numbers', 4, 4, 46, ' جميع المعدودين اللاويين الذين عدهم موسى وهارون ورؤساء إسرائيل ، حسب عشائرهم وبيوت آبائهم '),
(28125, 'Numbers', 4, 4, 47, ' من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة ، كل الداخلين ليعملوا عمل الخدمة وعمل الحمل في خيمة الاجتماع '),
(28126, 'Numbers', 4, 4, 48, ' كان المعدودون منهم ثمانية آلاف وخمس مئة وثمانين '),
(28127, 'Numbers', 4, 4, 49, ' حسب قول الرب عن يد موسى عد كل إنسان على خدمته وعلى حمله ، الذين عدهم موسى كما أمره الرب '),
(28128, 'Numbers', 4, 5, 1, ' وكلم الرب موسى قائلا '),
(28129, 'Numbers', 4, 5, 2, ' أوص بني إسرائيل أن ينفوا من المحلة كل أبرص ، وكل ذي سيل ، وكل متنجس لميت '),
(28130, 'Numbers', 4, 5, 3, ' الذكر والأنثى تنفون . إلى خارج المحلة تنفونهم لكيلا ينجسوا محلاتهم حيث أنا ساكن في وسطهم '),
(28131, 'Numbers', 4, 5, 4, ' ففعل هكذا بنو إسرائيل ونفوهم إلى خارج المحلة . كما كلم الرب موسى هكذا فعل بنو إسرائيل '),
(28132, 'Numbers', 4, 5, 5, ' وكلم الرب موسى قائلا '),
(28133, 'Numbers', 4, 5, 6, ' قل لبني إسرائيل : إذا عمل رجل أو امرأة شيئا من جميع خطايا الإنسان ، وخان خيانة بالرب ، فقد أذنبت تلك النفس '),
(28134, 'Numbers', 4, 5, 7, ' فلتقر بخطيتها التي عملت ، وترد ما أذنبت به بعينه ، وتزد عليه خمسه ، وتدفعه للذي أذنبت إليه '),
(28135, 'Numbers', 4, 5, 8, ' وإن كان ليس للرجل ولي ليرد إليه المذنب به ، فالمذنب به المردود يكون للرب لأجل الكاهن ، فضلا عن كبش الكفارة الذي يكفر به عنه '),
(28136, 'Numbers', 4, 5, 9, ' وكل رفيعة مع كل أقداس بني إسرائيل التي يقدمونها للكاهن تكون له '),
(28137, 'Numbers', 4, 5, 10, ' والإنسان أقداسه تكون له . إذا أعطى إنسان شيئا للكاهن فله يكون '),
(28138, 'Numbers', 4, 5, 11, ' وكلم الرب موسى قائلا '),
(28139, 'Numbers', 4, 5, 12, ' كلم بني إسرائيل وقل لهم : إذا زاغت امرأة رجل وخانته خيانة '),
(28140, 'Numbers', 4, 5, 13, ' واضطجع معها رجل اضطجاع زرع ، وأخفي ذلك عن عيني رجلها ، واستترت وهي نجسة وليس شاهد عليها ، وهي لم تؤخذ '),
(28141, 'Numbers', 4, 5, 14, ' فاعتراه روح الغيرة وغار على امرأته وهي نجسة ، أو اعتراه روح الغيرة وغار على امرأته وهي ليست نجسة '),
(28142, 'Numbers', 4, 5, 15, ' يأتي الرجل بامرأته إلى الكاهن ، ويأتي بقربانها معها : عشر الإيفة من طحين شعير ، لا يصب عليه زيتا ولا يجعل عليه لبانا ، لأنه تقدمة غيرة ، تقدمة تذكار تذكر ذنبا '),
(28143, 'Numbers', 4, 5, 16, ' فيقدمها الكاهن ويوقفها أمام الرب '),
(28144, 'Numbers', 4, 5, 17, ' ويأخذ الكاهن ماء مقدسا في إناء خزف ، ويأخذ الكاهن من الغبار الذي في أرض المسكن ويجعل في الماء '),
(28145, 'Numbers', 4, 5, 18, ' ويوقف الكاهن المرأة أمام الرب ، ويكشف رأس المرأة ، ويجعل في يديها تقدمة التذكار التي هي تقدمة الغيرة ، وفي يد الكاهن يكون ماء اللعنة المر '),
(28146, 'Numbers', 4, 5, 19, ' ويستحلف الكاهن المرأة ويقول لها : إن كان لم يضطجع معك رجل ، وإن كنت لم تزيغي إلى نجاسة من تحت رجلك ، فكوني بريئة من ماء اللعنة هذا المر '),
(28147, 'Numbers', 4, 5, 20, ' ولكن إن كنت قد زغت من تحت رجلك وتنجست ، وجعل معك رجل غير رجلك مضجعه '),
(28148, 'Numbers', 4, 5, 21, ' يستحلف الكاهن المرأة بحلف اللعنة ، ويقول الكاهن للمرأة : يجعلك الرب لعنة وحلفا بين شعبك ، بأن يجعل الرب فخذك ساقطة وبطنك وارما '),
(28149, 'Numbers', 4, 5, 22, ' ويدخل ماء اللعنة هذا في أحشائك لورم البطن ، ولإسقاط الفخذ . فتقول المرأة : آمين ، آمين '),
(28150, 'Numbers', 4, 5, 23, ' ويكتب الكاهن هذه اللعنات في الكتاب ثم يمحوها في الماء المر '),
(28151, 'Numbers', 4, 5, 24, ' ويسقي المرأة ماء اللعنة المر ، فيدخل فيها ماء اللعنة للمرارة '),
(28152, 'Numbers', 4, 5, 25, ' ويأخذ الكاهن من يد المرأة تقدمة الغيرة ، ويردد التقدمة أمام الرب ويقدمها إلى المذبح '),
(28153, 'Numbers', 4, 5, 26, ' ويقبض الكاهن من التقدمة تذكارها ويوقده على المذبح ، وبعد ذلك يسقي المرأة الماء '),
(28154, 'Numbers', 4, 5, 27, ' ومتى سقاها الماء ، فإن كانت قد تنجست وخانت رجلها ، يدخل فيها ماء اللعنة للمرارة ، فيرم بطنها وتسقط فخذها ، فتصير المرأة لعنة في وسط شعبها '),
(28155, 'Numbers', 4, 5, 28, ' وإن لم تكن المرأة قد تنجست بل كانت طاهرة ، تتبرأ وتحبل بزرع '),
(28156, 'Numbers', 4, 5, 29, ' هذه شريعة الغيرة ، إذا زاغت امرأة من تحت رجلها وتنجست '),
(28157, 'Numbers', 4, 5, 30, ' أو إذا اعترى رجلا روح غيرة فغار على امرأته ، يوقف المرأة أمام الرب ، ويعمل لها الكاهن كل هذه الشريعة '),
(28158, 'Numbers', 4, 5, 31, ' فيتبرأ الرجل من الذنب ، وتلك المرأة تحمل ذنبها '),
(28159, 'Numbers', 4, 6, 1, ' وكلم الرب موسى قائلا '),
(28160, 'Numbers', 4, 6, 2, ' كلم بني إسرائيل وقل لهم : إذا انفرز رجل أو امرأة لينذر نذر النذير ، لينتذر للرب '),
(28161, 'Numbers', 4, 6, 3, ' فعن الخمر والمسكر يفترز ، ولا يشرب خل الخمر ولا خل المسكر ، ولا يشرب من نقيع العنب ، ولا يأكل عنبا رطبا ولا يابسا '),
(28162, 'Numbers', 4, 6, 4, ' كل أيام نذره لا يأكل من كل ما يعمل من جفنة الخمر من العجم حتى القشر '),
(28163, 'Obadiah', 31, 1, 1, ' رؤيا عوبديا : هكذا قال السيد الرب عن أدوم : سمعنا خبرا من قبل الرب وأرسل رسول بين الأمم : قوموا ، ولنقم عليها للحرب '),
(28164, 'Obadiah', 31, 1, 2, ' إني قد جعلتك صغيرا بين الأمم . أنت محتقر جدا '),
(28165, 'Obadiah', 31, 1, 3, ' تكبر قلبك قد خدعك أيها الساكن في محاجئ الصخر ، رفعة مقعده ، القائل في قلبه : من يحدرني إلى الأرض '),
(28166, 'Obadiah', 31, 1, 4, ' إن كنت ترتفع كالنسر ، وإن كان عشك موضوعا بين النجوم ، فمن هناك أحدرك ، يقول الرب '),
(28167, 'Obadiah', 31, 1, 5, ' إن أتاك سارقون أو لصوص ليل . كيف هلكت أفلا يسرقون حاجتهم ؟ إن أتاك قاطفون أفلا يبقون خصاصة '),
(28168, 'Obadiah', 31, 1, 6, ' كيف فتش عيسو وفحصت مخابئه '),
(28169, 'Obadiah', 31, 1, 7, ' طردك إلى التخم كل معاهديك . خدعك وغلب عليك مسالموك . أهل خبزك وضعوا شركا تحتك . لا فهم فيه '),
(28170, 'Obadiah', 31, 1, 8, ' ألا أبيد في ذلك اليوم ، يقول الرب ، الحكماء من أدوم ، والفهم من جبل عيسو '),
(28171, 'Obadiah', 31, 1, 9, ' فيرتاع أبطالك يا تيمان ، لكي ينقرض كل واحد من جبل عيسو بالقتل '),
(28172, 'Obadiah', 31, 1, 10, ' من أجل ظلمك لأخيك يعقوب ، يغشاك الخزي وتنقرض إلى الأبد '),
(28173, 'Obadiah', 31, 1, 11, ' يوم وقفت مقابله يوم سبت الأعاجم قدرته ، ودخلت الغرباء أبوابه ، وألقوا قرعة على أورشليم ، كنت أنت أيضا كواحد منهم '),
(28174, 'Obadiah', 31, 1, 12, ' ويجب أن لا تنظر إلى يوم أخيك يوم مصيبته ، ولا تشمت ببني يهوذا يوم هلاكهم ، ولا تفغر فمك يوم الضيق '),
(28175, 'Obadiah', 31, 1, 13, ' ولا تدخل باب شعبي يوم بليتهم ، ولا تنظر أنت أيضا إلى مصيبته يوم بليته ، ولا تمد يدا إلى قدرته يوم بليته '),
(28176, 'Obadiah', 31, 1, 14, ' ولا تقف على المفرق لتقطع منفلتيه ، ولا تسلم بقاياه يوم الضيق '),
(28177, 'Obadiah', 31, 1, 15, ' فإنه قريب يوم الرب على كل الأمم . كما فعلت يفعل بك . عملك يرتد على رأسك '),
(28178, 'Obadiah', 31, 1, 16, ' لأنه كما شربتم على جبل قدسي ، يشرب جميع الأمم دائما ، يشربون ويجرعون ويكونون كأنهم لم يكونوا '),
(28179, 'Obadiah', 31, 1, 17, ' وأما جبل صهيون فتكون عليه نجاة ، ويكون مقدسا ، ويرث بيت يعقوب مواريثهم '),
(28180, 'Obadiah', 31, 1, 18, ' ويكون بيت يعقوب نارا ، وبيت يوسف لهيبا ، وبيت عيسو قشا ، فيشعلونهم ويأكلونهم ولا يكون باق من بيت عيسو ، لأن الرب تكلم '),
(28181, 'Obadiah', 31, 1, 19, ' ويرث أهل الجنوب جبل عيسو ، وأهل السهل الفلسطينيين ، ويرثون بلاد أفرايم وبلاد السامرة ، ويرث بنيامين جلعاد '),
(28182, 'Obadiah', 31, 1, 20, ' وسبي هذا الجيش من بني إسرائيل يرثون الذين هم من الكنعانيين إلى صرفة . وسبي أورشليم الذين في صفارد يرثون مدن الجنوب '),
(28183, 'Obadiah', 31, 1, 21, ' ويصعد مخلصون على جبل صهيون ليدينوا جبل عيسو ، ويكون الملك للرب '),
(28184, 'Philemon', 57, 1, 1, ' بولس ، أسير يسوع المسيح ، وتيموثاوس الأخ ، إلى فليمون المحبوب والعامل معنا '),
(28185, 'Philemon', 57, 1, 2, ' وإلى أبفية المحبوبة ، وأرخبس المتجند معنا ، وإلى الكنيسة التي في بيتك '),
(28186, 'Philemon', 57, 1, 3, ' نعمة لكم وسلام من الله أبينا والرب يسوع المسيح '),
(28187, 'Philemon', 57, 1, 4, ' أشكر إلهي كل حين ذاكرا إياك في صلواتي '),
(28188, 'Philemon', 57, 1, 5, ' سامعا بمحبتك ، والإيمان الذي لك نحو الرب يسوع ، ولجميع القديسين '),
(28189, 'Philemon', 57, 1, 6, ' لكي تكون شركة إيمانك فعالة في معرفة كل الصلاح الذي فيكم لأجل المسيح يسوع '),
(28190, 'Philemon', 57, 1, 7, ' لأن لنا فرحا كثيرا وتعزية بسبب محبتك ، لأن أحشاء القديسين قد استراحت بك أيها الأخ '),
(28191, 'Philemon', 57, 1, 8, ' لذلك ، وإن كان لي بالمسيح ثقة كثيرة أن آمرك بما يليق '),
(28192, 'Philemon', 57, 1, 9, ' من أجل المحبة ، أطلب بالحري - إذ أنا إنسان هكذا نظير بولس الشيخ ، والآن أسير يسوع المسيح أيضا '),
(28193, 'Philemon', 57, 1, 10, ' أطلب إليك لأجل ابني أنسيمس ، الذي ولدته في قيودي '),
(28194, 'Philemon', 57, 1, 11, ' الذي كان قبلا غير نافع لك ، ولكنه الآن نافع لك ولي '),
(28195, 'Philemon', 57, 1, 12, ' الذي رددته . فاقبله ، الذي هو أحشائي '),
(28196, 'Philemon', 57, 1, 13, ' الذي كنت أشاء أن أمسكه عندي لكي يخدمني عوضا عنك في قيود الإنجيل '),
(28197, 'Philemon', 57, 1, 14, ' ولكن بدون رأيك لم أرد أن أفعل شيئا ، لكي لا يكون خيرك كأنه على سبيل الاضطرار بل على سبيل الاختيار '),
(28198, 'Philemon', 57, 1, 15, ' لأنه ربما لأجل هذا افترق عنك إلى ساعة ، لكي يكون لك إلى الأبد '),
(28199, 'Philemon', 57, 1, 16, ' لا كعبد في ما بعد ، بل أفضل من عبد : أخا محبوبا ، ولاسيما إلي ، فكم بالحري إليك في الجسد والرب جميعا '),
(28200, 'Philemon', 57, 1, 17, ' فإن كنت تحسبني شريكا ، فاقبله نظيري '),
(28201, 'Philemon', 57, 1, 18, ' ثم إن كان قد ظلمك بشيء ، أو لك عليه دين ، فاحسب ذلك علي '),
(28202, 'Philemon', 57, 1, 19, ' أنا بولس كتبت بيدي : أنا أوفي . حتى لا أقول لك إنك مديون لي بنفسك أيضا '),
(28203, 'Philemon', 57, 1, 20, ' نعم أيها الأخ ، ليكن لي فرح بك في الرب . أرح أحشائي في الرب '),
(28204, 'Philemon', 57, 1, 21, ' إذ أنا واثق بإطاعتك ، كتبت إليك ، عالما أنك تفعل أيضا أكثر مما أقول '),
(28205, 'Philemon', 57, 1, 22, ' ومع هذا ، أعدد لي أيضا منزلا ، لأني أرجو أنني بصلواتكم سأوهب لكم '),
(28206, 'Philemon', 57, 1, 23, ' يسلم عليك أبفراس المأسور معي في المسيح يسوع '),
(28207, 'Philemon', 57, 1, 24, ' ومرقس ، وأرسترخس ، وديماس ، ولوقا العاملون معي '),
(28208, 'Philemon', 57, 1, 25, ' نعمة ربنا يسوع المسيح مع روحكم . آمين '),
(28209, 'Philippians', 50, 1, 1, ' بولس وتيموثاوس عبدا يسوع المسيح ، إلى جميع القديسين في المسيح يسوع ، الذين في فيلبي ، مع أساقفة وشمامسة '),
(28210, 'Philippians', 50, 1, 2, ' نعمة لكم وسلام من الله أبينا والرب يسوع المسيح '),
(28211, 'Philippians', 50, 1, 3, ' أشكر إلهي عند كل ذكري إياكم '),
(28212, 'Philippians', 50, 1, 4, ' دائما في كل أدعيتي ، مقدما الطلبة لأجل جميعكم بفرح '),
(28213, 'Philippians', 50, 1, 5, ' لسبب مشاركتكم في الإنجيل من أول يوم إلى الآن '),
(28214, 'Philippians', 50, 1, 6, ' واثقا بهذا عينه أن الذي ابتدأ فيكم عملا صالحا يكمل إلى يوم يسوع المسيح '),
(28215, 'Philippians', 50, 1, 7, ' كما يحق لي أن أفتكر هذا من جهة جميعكم ، لأني حافظكم في قلبي ، في وثقي ، وفي المحاماة عن الإنجيل وتثبيته ، أنتم الذين جميعكم شركائي في النعمة '),
(28216, 'Philippians', 50, 1, 8, ' فإن الله شاهد لي كيف أشتاق إلى جميعكم في أحشاء يسوع المسيح '),
(28217, 'Philippians', 50, 1, 9, ' وهذا أصليه : أن تزداد محبتكم أيضا أكثر فأكثر في المعرفة وفي كل فهم '),
(28218, 'Philippians', 50, 1, 10, ' حتى تميزوا الأمور المتخالفة ، لكي تكونوا مخلصين وبلا عثرة إلى يوم المسيح '),
(28219, 'Philippians', 50, 1, 11, ' مملوئين من ثمر البر الذي بيسوع المسيح لمجد الله وحمده '),
(28220, 'Philippians', 50, 1, 12, ' ثم أريد أن تعلموا أيها الإخوة أن أموري قد آلت أكثر إلى تقدم الإنجيل '),
(28221, 'Philippians', 50, 1, 13, ' حتى إن وثقي صارت ظاهرة في المسيح في كل دار الولاية وفي باقي الأماكن أجمع '),
(28222, 'Philippians', 50, 1, 14, ' وأكثر الإخوة ، وهم واثقون في الرب بوثقي ، يجترئون أكثر على التكلم بالكلمة بلا خوف '),
(28223, 'Philippians', 50, 1, 15, ' أما قوم فعن حسد وخصام يكرزون بالمسيح ، وأما قوم فعن مسرة '),
(28224, 'Philippians', 50, 1, 16, ' فهؤلاء عن تحزب ينادون بالمسيح لا عن إخلاص ، ظانين أنهم يضيفون إلى وثقي ضيقا '),
(28225, 'Philippians', 50, 1, 17, ' وأولئك عن محبة ، عالمين أني موضوع لحماية الإنجيل '),
(28226, 'Philippians', 50, 1, 18, ' فماذا ؟ غير أنه على كل وجه سواء كان بعلة أم بحق ينادى بالمسيح ، وبهذا أنا أفرح . بل سأفرح أيضا '),
(28227, 'Philippians', 50, 1, 19, ' لأني أعلم أن هذا يؤول لي إلى خلاص بطلبتكم ومؤازرة روح يسوع المسيح '),
(28228, 'Philippians', 50, 1, 20, ' حسب انتظاري ورجائي أني لا أخزى في شيء ، بل بكل مجاهرة كما في كل حين ، كذلك الآن ، يتعظم المسيح في جسدي ، سواء كان بحياة أم بموت '),
(28229, 'Philippians', 50, 1, 21, ' لأن لي الحياة هي المسيح والموت هو ربح '),
(28230, 'Philippians', 50, 1, 22, ' ولكن إن كانت الحياة في الجسد هي لي ثمر عملي ، فماذا أختار ؟ لست أدري '),
(28231, 'Philippians', 50, 1, 23, ' فإني محصور من الاثنين : لي اشتهاء أن أنطلق وأكون مع المسيح ، ذاك أفضل جدا '),
(28232, 'Philippians', 50, 1, 24, ' ولكن أن أبقى في الجسد ألزم من أجلكم '),
(28233, 'Philippians', 50, 1, 25, ' فإذ أنا واثق بهذا أعلم أني أمكث وأبقى مع جميعكم لأجل تقدمكم وفرحكم في الإيمان '),
(28234, 'Philippians', 50, 1, 26, ' لكي يزداد افتخاركم في المسيح يسوع في ، بواسطة حضوري أيضا عندكم '),
(28235, 'Philippians', 50, 1, 27, ' فقط عيشوا كما يحق لإنجيل المسيح ، حتى إذا جئت ورأيتكم ، أو كنت غائبا أسمع أموركم أنكم تثبتون في روح واحد ، مجاهدين معا بنفس واحدة لإيمان الإنجيل '),
(28236, 'Philippians', 50, 1, 28, ' غير مخوفين بشيء من المقاومين ، الأمر الذي هو لهم بينة للهلاك ، وأما لكم فللخلاص ، وذلك من الله '),
(28237, 'Philippians', 50, 1, 29, ' لأنه قد وهب لكم لأجل المسيح لا أن تؤمنوا به فقط ، بل أيضا أن تتألموا لأجله '),
(28238, 'Philippians', 50, 1, 30, ' إذ لكم الجهاد عينه الذي رأيتموه في ، والآن تسمعون في '),
(28239, 'Philippians', 50, 2, 1, ' فإن كان وعظ ما في المسيح . إن كانت تسلية ما للمحبة . إن كانت شركة ما في الروح . إن كانت أحشاء ورأفة '),
(28240, 'Philippians', 50, 2, 2, ' فتمموا فرحي حتى تفتكروا فكرا واحدا ولكم محبة واحدة بنفس واحدة ، مفتكرين شيئا واحدا '),
(28241, 'Philippians', 50, 2, 3, ' لا شيئا بتحزب أو بعجب ، بل بتواضع ، حاسبين بعضكم البعض أفضل من أنفسهم '),
(28242, 'Philippians', 50, 2, 4, ' لا تنظروا كل واحد إلى ما هو لنفسه ، بل كل واحد إلى ما هو لآخرين أيضا '),
(28243, 'Philippians', 50, 2, 5, ' فليكن فيكم هذا الفكر الذي في المسيح يسوع أيضا '),
(28244, 'Philippians', 50, 2, 6, ' الذي إذ كان في صورة الله ، لم يحسب خلسة أن يكون معادلا لله '),
(28245, 'Philippians', 50, 2, 7, ' لكنه أخلى نفسه ، آخذا صورة عبد ، صائرا في شبه الناس '),
(28246, 'Philippians', 50, 2, 8, ' وإذ وجد في الهيئة كإنسان ، وضع نفسه وأطاع حتى الموت موت الصليب '),
(28247, 'Philippians', 50, 2, 9, ' لذلك رفعه الله أيضا ، وأعطاه اسما فوق كل اسم '),
(28248, 'Philippians', 50, 2, 10, ' لكي تجثو باسم يسوع كل ركبة ممن في السماء ومن على الأرض ومن تحت الأرض '),
(28249, 'Philippians', 50, 2, 11, ' ويعترف كل لسان أن يسوع المسيح هو رب لمجد الله الآب '),
(28250, 'Philippians', 50, 2, 12, ' إذا يا أحبائي ، كما أطعتم كل حين ، ليس كما في حضوري فقط ، بل الآن بالأولى جدا في غيابي ، تمموا خلاصكم بخوف ورعدة '),
(28251, 'Philippians', 50, 2, 13, ' لأن الله هو العامل فيكم أن تريدوا وأن تعملوا من أجل المسرة '),
(28252, 'Philippians', 50, 2, 14, ' افعلوا كل شيء بلا دمدمة ولا مجادلة '),
(28253, 'Philippians', 50, 2, 15, ' لكي تكونوا بلا لوم ، وبسطاء ، أولادا لله بلا عيب في وسط جيل معوج وملتو ، تضيئون بينهم كأنوار في العالم '),
(28254, 'Philippians', 50, 2, 16, ' متمسكين بكلمة الحياة لافتخاري في يوم المسيح ، بأني لم أسع باطلا ولا تعبت باطلا '),
(28255, 'Philippians', 50, 2, 17, ' لكنني وإن كنت أنسكب أيضا على ذبيحة إيمانكم وخدمته ، أسر وأفرح معكم أجمعين '),
(28256, 'Philippians', 50, 2, 18, ' وبهذا عينه كونوا أنتم مسرورين أيضا وافرحوا معي '),
(28257, 'Philippians', 50, 2, 19, ' على أني أرجو في الرب يسوع أن أرسل إليكم سريعا تيموثاوس لكي تطيب نفسي إذا عرفت أحوالكم '),
(28258, 'Philippians', 50, 2, 20, ' لأن ليس لي أحد آخر نظير نفسي يهتم بأحوالكم بإخلاص '),
(28259, 'Philippians', 50, 2, 21, ' إذ الجميع يطلبون ما هو لأنفسهم لا ما هو ليسوع المسيح '),
(28260, 'Philippians', 50, 2, 22, ' وأما اختباره فأنتم تعرفون أنه كولد مع أب خدم معي لأجل الإنجيل '),
(28261, 'Philippians', 50, 2, 23, ' هذا أرجو أن أرسله أول ما أرى أحوالي حالا '),
(28262, 'Philippians', 50, 2, 24, ' وأثق بالرب أني أنا أيضا سآتي إليكم سريعا '),
(28263, 'Philippians', 50, 2, 25, ' ولكني حسبت من اللازم أن أرسل إليكم أبفرودتس أخي ، والعامل معي ، والمتجند معي ، ورسولكم ، والخادم لحاجتي '),
(28264, 'Philippians', 50, 2, 26, ' إذ كان مشتاقا إلى جميعكم ومغموما ، لأنكم سمعتم أنه كان مريضا '),
(28265, 'Philippians', 50, 2, 27, ' فإنه مرض قريبا من الموت ، لكن الله رحمه . وليس إياه وحده بل إياي أيضا لئلا يكون لي حزن على حزن '),
(28266, 'Philippians', 50, 2, 28, ' فأرسلته إليكم بأوفر سرعة ، حتى إذا رأيتموه تفرحون أيضا وأكون أنا أقل حزنا '),
(28267, 'Philippians', 50, 2, 29, ' فاقبلوه في الرب بكل فرح ، وليكن مثله مكرما عندكم '),
(28268, 'Philippians', 50, 2, 30, ' لأنه من أجل عمل المسيح قارب الموت ، مخاطرا بنفسه ، لكي يجبر نقصان خدمتكم لي '),
(28269, 'Philippians', 50, 3, 1, ' أخيرا يا إخوتي افرحوا في الرب . كتابة هذه الأمور إليكم ليست علي ثقيلة ، وأما لكم فهي مؤمنة '),
(28270, 'Philippians', 50, 3, 2, ' انظروا الكلاب . انظروا فعلة الشر . انظروا القطع '),
(28271, 'Philippians', 50, 3, 3, ' لأننا نحن الختان ، الذين نعبد الله بالروح ، ونفتخر في المسيح يسوع ، ولا نتكل على الجسد '),
(28272, 'Philippians', 50, 3, 4, ' مع أن لي أن أتكل على الجسد أيضا . إن ظن واحد آخر أن يتكل على الجسد فأنا بالأولى '),
(28273, 'Philippians', 50, 3, 5, ' من جهة الختان مختون في اليوم الثامن ، من جنس إسرائيل ، من سبط بنيامين ، عبراني من العبرانيين . من جهة الناموس فريسي '),
(28274, 'Philippians', 50, 3, 6, ' من جهة الغيرة مضطهد الكنيسة . من جهة البر الذي في الناموس بلا لوم '),
(28275, 'Philippians', 50, 3, 7, ' لكن ما كان لي ربحا ، فهذا قد حسبته من أجل المسيح خسارة '),
(28276, 'Philippians', 50, 3, 8, ' بل إني أحسب كل شيء أيضا خسارة من أجل فضل معرفة المسيح يسوع ربي ، الذي من أجله خسرت كل الأشياء ، وأنا أحسبها نفاية لكي أربح المسيح '),
(28277, 'Philippians', 50, 3, 9, ' وأوجد فيه ، وليس لي بري الذي من الناموس ، بل الذي بإيمان المسيح ، البر الذي من الله بالإيمان '),
(28278, 'Philippians', 50, 3, 10, ' لأعرفه ، وقوة قيامته ، وشركة آلامه ، متشبها بموته '),
(28279, 'Philippians', 50, 3, 11, ' لعلي أبلغ إلى قيامة الأموات '),
(28280, 'Philippians', 50, 3, 12, ' ليس أني قد نلت أو صرت كاملا ، ولكني أسعى لعلي أدرك الذي لأجله أدركني أيضا المسيح يسوع '),
(28281, 'Philippians', 50, 3, 13, ' أيها الإخوة ، أنا لست أحسب نفسي أني قد أدركت . ولكني أفعل شيئا واحدا : إذ أنا أنسى ما هو وراء وأمتد إلى ما هو قدام '),
(28282, 'Philippians', 50, 3, 14, ' أسعى نحو الغرض لأجل جعالة دعوة الله العليا في المسيح يسوع '),
(28283, 'Philippians', 50, 3, 15, ' فليفتكر هذا جميع الكاملين منا ، وإن افتكرتم شيئا بخلافه فالله سيعلن لكم هذا أيضا '),
(28284, 'Philippians', 50, 3, 16, ' وأما ما قد أدركناه ، فلنسلك بحسب ذلك القانون عينه ، ونفتكر ذلك عينه '),
(28285, 'Philippians', 50, 3, 17, ' كونوا متمثلين بي معا أيها الإخوة ، ولاحظوا الذين يسيرون هكذا كما نحن عندكم قدوة '),
(28286, 'Philippians', 50, 3, 18, ' لأن كثيرين يسيرون ممن كنت أذكرهم لكم مرارا ، والآن أذكرهم أيضا باكيا ، وهم أعداء صليب المسيح '),
(28287, 'Philippians', 50, 3, 19, ' الذين نهايتهم الهلاك ، الذين إلههم بطنهم ومجدهم في خزيهم ، الذين يفتكرون في الأرضيات '),
(28288, 'Philippians', 50, 3, 20, ' فإن سيرتنا نحن هي في السماوات ، التي منها أيضا ننتظر مخلصا هو الرب يسوع المسيح '),
(28289, 'Philippians', 50, 3, 21, ' الذي سيغير شكل جسد تواضعنا ليكون على صورة جسد مجده ، بحسب عمل استطاعته أن يخضع لنفسه كل شيء '),
(28290, 'Philippians', 50, 4, 1, ' إذا يا إخوتي الأحباء والمشتاق إليهم ، يا سروري وإكليلي ، اثبتوا هكذا في الرب أيها الأحباء '),
(28291, 'Philippians', 50, 4, 2, ' أطلب إلى أفودية وأطلب إلى سنتيخي أن تفتكرا فكرا واحدا في الرب '),
(28292, 'Philippians', 50, 4, 3, ' نعم أسألك أنت أيضا ، يا شريكي المخلص ، ساعد هاتين اللتين جاهدتا معي في الإنجيل ، مع أكليمندس أيضا وباقي العاملين معي ، الذين أسماؤهم في سفر الحياة '),
(28293, 'Philippians', 50, 4, 4, ' افرحوا في الرب كل حين ، وأقول أيضا : افرحوا '),
(28294, 'Philippians', 50, 4, 5, ' ليكن حلمكم معروفا عند جميع الناس . الرب قريب '),
(28295, 'Philippians', 50, 4, 6, ' لا تهتموا بشيء ، بل في كل شيء بالصلاة والدعاء مع الشكر ، لتعلم طلباتكم لدى الله '),
(28296, 'Philippians', 50, 4, 7, ' وسلام الله الذي يفوق كل عقل ، يحفظ قلوبكم وأفكاركم في المسيح يسوع '),
(28297, 'Philippians', 50, 4, 8, ' أخيرا أيها الإخوة كل ما هو حق ، كل ما هو جليل ، كل ما هو عادل ، كل ما هو طاهر ، كل ما هو مسر ، كل ما صيته حسن ، إن كانت فضيلة وإن كان مدح ، ففي هذه افتكروا '),
(28298, 'Philippians', 50, 4, 9, ' وما تعلمتموه ، وتسلمتموه ، وسمعتموه ، ورأيتموه في ، فهذا افعلوا ، وإله السلام يكون معكم '),
(28299, 'Philippians', 50, 4, 10, ' ثم إني فرحت بالرب جدا لأنكم الآن قد أزهر أيضا مرة اعتناؤكم بي الذي كنتم تعتنونه ، ولكن لم تكن لكم فرصة '),
(28300, 'Philippians', 50, 4, 11, ' ليس أني أقول من جهة احتياج ، فإني قد تعلمت أن أكون مكتفيا بما أنا فيه '),
(28301, 'Philippians', 50, 4, 12, ' أعرف أن أتضع وأعرف أيضا أن أستفضل . في كل شيء وفي جميع الأشياء قد تدربت أن أشبع وأن أجوع ، وأن أستفضل وأن أنقص '),
(28302, 'Philippians', 50, 4, 13, ' أستطيع كل شيء في المسيح الذي يقويني '),
(28303, 'Philippians', 50, 4, 14, ' غير أنكم فعلتم حسنا إذ اشتركتم في ضيقتي '),
(28304, 'Philippians', 50, 4, 15, ' وأنتم أيضا تعلمون أيها الفيلبيون أنه في بداءة الإنجيل ، لما خرجت من مكدونية ، لم تشاركني كنيسة واحدة في حساب العطاء والأخذ إلا أنتم وحدكم '),
(28305, 'Philippians', 50, 4, 16, ' فإنكم في تسالونيكي أيضا أرسلتم إلي مرة ومرتين لحاجتي '),
(28306, 'Philippians', 50, 4, 17, ' ليس أني أطلب العطية ، بل أطلب الثمر المتكاثر لحسابكم '),
(28307, 'Philippians', 50, 4, 18, ' ولكني قد استوفيت كل شيء واستفضلت . قد امتلأت إذ قبلت من أبفرودتس الأشياء التي من عندكم ، نسيم رائحة طيبة ، ذبيحة مقبولة مرضية عند الله '),
(28308, 'Philippians', 50, 4, 19, ' فيملأ إلهي كل احتياجكم بحسب غناه في المجد في المسيح يسوع '),
(28309, 'Philippians', 50, 4, 20, ' ولله وأبينا المجد إلى دهر الداهرين . آمين '),
(28310, 'Philippians', 50, 4, 21, ' سلموا على كل قديس في المسيح يسوع . يسلم عليكم الإخوة الذين معي '),
(28311, 'Philippians', 50, 4, 22, ' يسلم عليكم جميع القديسين ولاسيما الذين من بيت قيصر '),
(28312, 'Philippians', 50, 4, 23, ' نعمة ربنا يسوع المسيح مع جميعكم . آمين '),
(28313, 'Proverbs', 20, 1, 1, ' أمثال سليمان بن داود ملك إسرائيل '),
(28314, 'Proverbs', 20, 1, 2, ' لمعرفة حكمة وأدب . لإدراك أقوال الفهم '),
(28315, 'Proverbs', 20, 1, 3, ' لقبول تأديب المعرفة والعدل والحق والاستقامة '),
(28316, 'Proverbs', 20, 1, 4, ' لتعطي الجهال ذكاء ، والشاب معرفة وتدبرا '),
(28317, 'Proverbs', 20, 1, 5, ' يسمعها الحكيم فيزداد علما ، والفهيم يكتسب تدبيرا '),
(28318, 'Proverbs', 20, 1, 6, ' لفهم المثل واللغز ، أقوال الحكماء وغوامضهم '),
(28319, 'Proverbs', 20, 1, 7, ' مخافة الرب رأس المعرفة ، أما الجاهلون فيحتقرون الحكمة والأدب '),
(28320, 'Proverbs', 20, 1, 8, ' اسمع يا ابني تأديب أبيك ، ولا ترفض شريعة أمك '),
(28321, 'Proverbs', 20, 1, 9, ' لأنهما إكليل نعمة لرأسك ، وقلائد لعنقك '),
(28322, 'Proverbs', 20, 1, 10, ' يا ابني ، إن تملقك الخطاة فلا ترض ');
INSERT INTO `bible_ar` (`ID`, `Book_Name`, `book`, `Chapter`, `Verse`, `Text`) VALUES
(28323, 'Proverbs', 20, 1, 11, ' إن قالوا : هلم معنا لنكمن للدم . لنختف للبريء باطلا '),
(28324, 'Proverbs', 20, 1, 12, ' لنبتلعهم أحياء كالهاوية ، وصحاحا كالهابطين في الجب '),
(28325, 'Proverbs', 20, 1, 13, ' فنجد كل قنية فاخرة ، نملأ بيوتنا غنيمة '),
(28326, 'Proverbs', 20, 1, 14, ' تلقي قرعتك وسطنا . يكون لنا جميعا كيس واحد '),
(28327, 'Proverbs', 20, 1, 15, ' يا ابني ، لا تسلك في الطريق معهم . امنع رجلك عن مسالكهم '),
(28328, 'Proverbs', 20, 1, 16, ' لأن أرجلهم تجري إلى الشر وتسرع إلى سفك الدم '),
(28329, 'Proverbs', 20, 1, 17, ' لأنه باطلا تنصب الشبكة في عيني كل ذي جناح '),
(28330, 'Proverbs', 20, 1, 18, ' أما هم فيكمنون لدم أنفسهم . يختفون لأنفسهم '),
(28331, 'Proverbs', 20, 1, 19, ' هكذا طرق كل مولع بكسب . يأخذ نفس مقتنيه '),
(28332, 'Proverbs', 20, 1, 20, ' الحكمة تنادي في الخارج . في الشوارع تعطي صوتها '),
(28333, 'Proverbs', 20, 1, 21, ' تدعو في رؤوس الأسواق ، في مداخل الأبواب . في المدينة تبدي كلامها '),
(28334, 'Proverbs', 20, 1, 22, ' قائلة : إلى متى أيها الجهال تحبون الجهل ، والمستهزئون يسرون بالاستهزاء ، والحمقى يبغضون العلم '),
(28335, 'Proverbs', 20, 1, 23, ' ارجعوا عند توبيخي . هأنذا أفيض لكم روحي . أعلمكم كلماتي '),
(28336, 'Proverbs', 20, 1, 24, ' لأني دعوت فأبيتم ، ومددت يدي وليس من يبالي '),
(28337, 'Proverbs', 20, 1, 25, ' بل رفضتم كل مشورتي ، ولم ترضوا توبيخي '),
(28338, 'Proverbs', 20, 1, 26, ' فأنا أيضا أضحك عند بليتكم . أشمت عند مجيء خوفكم '),
(28339, 'Proverbs', 20, 1, 27, ' إذا جاء خوفكم كعاصفة ، وأتت بليتكم كالزوبعة ، إذا جاءت عليكم شدة وضيق '),
(28340, 'Proverbs', 20, 1, 28, ' حينئذ يدعونني فلا أستجيب . يبكرون إلي فلا يجدونني '),
(28341, 'Proverbs', 20, 1, 29, ' لأنهم أبغضوا العلم ولم يختاروا مخافة الرب '),
(28342, 'Proverbs', 20, 1, 30, ' لم يرضوا مشورتي . رذلوا كل توبيخي '),
(28343, 'Proverbs', 20, 1, 31, ' فلذلك يأكلون من ثمر طريقهم ، ويشبعون من مؤامراتهم '),
(28344, 'Proverbs', 20, 1, 32, ' لأن ارتداد الحمقى يقتلهم ، وراحة الجهال تبيدهم '),
(28345, 'Proverbs', 20, 1, 33, ' أما المستمع لي فيسكن آمنا ، ويستريح من خوف الشر '),
(28346, 'Proverbs', 20, 2, 1, ' يا ابني ، إن قبلت كلامي وخبأت وصاياي عندك '),
(28347, 'Proverbs', 20, 2, 2, ' حتى تميل أذنك إلى الحكمة ، وتعطف قلبك على الفهم '),
(28348, 'Proverbs', 20, 2, 3, ' إن دعوت المعرفة ، ورفعت صوتك إلى الفهم '),
(28349, 'Proverbs', 20, 2, 4, ' إن طلبتها كالفضة ، وبحثت عنها كالكنوز '),
(28350, 'Proverbs', 20, 2, 5, ' فحينئذ تفهم مخافة الرب ، وتجد معرفة الله '),
(28351, 'Proverbs', 20, 2, 6, ' لأن الرب يعطي حكمة . من فمه المعرفة والفهم '),
(28352, 'Proverbs', 20, 2, 7, ' يذخر معونة للمستقيمين . هو مجن للسالكين بالكمال '),
(28353, 'Proverbs', 20, 2, 8, ' لنصر مسالك الحق وحفظ طريق أتقيائه '),
(28354, 'Proverbs', 20, 2, 9, ' حينئذ تفهم العدل والحق والاستقامة ، كل سبيل صالح '),
(28355, 'Proverbs', 20, 2, 10, ' إذا دخلت الحكمة قلبك ، ولذت المعرفة لنفسك '),
(28356, 'Proverbs', 20, 2, 11, ' فالعقل يحفظك ، والفهم ينصرك '),
(28357, 'Proverbs', 20, 2, 12, ' لإنقاذك من طريق الشرير ، ومن الإنسان المتكلم بالأكاذيب '),
(28358, 'Proverbs', 20, 2, 13, ' التاركين سبل الاستقامة للسلوك في مسالك الظلمة '),
(28359, 'Proverbs', 20, 2, 14, ' الفرحين بفعل السوء ، المبتهجين بأكاذيب الشر '),
(28360, 'Proverbs', 20, 2, 15, ' الذين طرقهم معوجة ، وهم ملتوون في سبلهم '),
(28361, 'Proverbs', 20, 2, 16, ' لإنقاذك من المرأة الأجنبية ، من الغريبة المتملقة بكلامها '),
(28362, 'Proverbs', 20, 2, 17, ' التاركة أليف صباها ، والناسية عهد إلهها '),
(28363, 'Proverbs', 20, 2, 18, ' لأن بيتها يسوخ إلى الموت ، وسبلها إلى الأخيلة '),
(28364, 'Proverbs', 20, 2, 19, ' كل من دخل إليها لا يؤوب ، ولا يبلغون سبل الحياة '),
(28365, 'Proverbs', 20, 2, 20, ' حتى تسلك في طريق الصالحين وتحفظ سبل الصديقين '),
(28366, 'Proverbs', 20, 2, 21, ' لأن المستقيمين يسكنون الأرض ، والكاملين يبقون فيها '),
(28367, 'Proverbs', 20, 2, 22, ' أما الأشرار فينقرضون من الأرض ، والغادرون يستأصلون منها '),
(28368, 'Proverbs', 20, 3, 1, ' يا ابني ، لا تنس شريعتي ، بل ليحفظ قلبك وصاياي '),
(28369, 'Proverbs', 20, 3, 2, ' فإنها تزيدك طول أيام ، وسني حياة وسلامة '),
(28370, 'Proverbs', 20, 3, 3, ' لا تدع الرحمة والحق يتركانك . تقلدهما على عنقك . اكتبهما على لوح قلبك '),
(28371, 'Proverbs', 20, 3, 4, ' فتجد نعمة وفطنة صالحة في أعين الله والناس '),
(28372, 'Proverbs', 20, 3, 5, ' توكل على الرب بكل قلبك ، وعلى فهمك لا تعتمد '),
(28373, 'Proverbs', 20, 3, 6, ' في كل طرقك اعرفه ، وهو يقوم سبلك '),
(28374, 'Proverbs', 20, 3, 7, ' لا تكن حكيما في عيني نفسك . اتق الرب وابعد عن الشر '),
(28375, 'Proverbs', 20, 3, 8, ' فيكون شفاء لسرتك ، وسقاء لعظامك '),
(28376, 'Proverbs', 20, 3, 9, ' أكرم الرب من مالك ومن كل باكورات غلتك '),
(28377, 'Proverbs', 20, 3, 10, ' فتمتلئ خزائنك شبعا ، وتفيض معاصرك مسطارا '),
(28378, 'Proverbs', 20, 3, 11, ' يا ابني ، لا تحتقر تأديب الرب ولا تكره توبيخه '),
(28379, 'Proverbs', 20, 3, 12, ' لأن الذي يحبه الرب يؤدبه ، وكأب بابن يسر به '),
(28380, 'Proverbs', 20, 3, 13, ' طوبى للإنسان الذي يجد الحكمة ، وللرجل الذي ينال الفهم '),
(28381, 'Proverbs', 20, 3, 14, ' لأن تجارتها خير من تجارة الفضة ، وربحها خير من الذهب الخالص '),
(28382, 'Proverbs', 20, 3, 15, ' هي أثمن من اللآلئ ، وكل جواهرك لا تساويها '),
(28383, 'Proverbs', 20, 3, 16, ' في يمينها طول أيام ، وفي يسارها الغنى والمجد '),
(28384, 'Proverbs', 20, 3, 17, ' طرقها طرق نعم ، وكل مسالكها سلام '),
(28385, 'Proverbs', 20, 3, 18, ' هي شجرة حياة لممسكيها ، والمتمسك بها مغبوط '),
(28386, 'Proverbs', 20, 6, 8, ' وتعد في الصيف طعامها ، وتجمع في الحصاد أكلها '),
(28387, 'Proverbs', 20, 6, 9, ' إلى متى تنام أيها الكسلان ؟ متى تنهض من نومك '),
(28388, 'Proverbs', 20, 6, 10, ' قليل نوم بعد قليل نعاس ، وطي اليدين قليلا للرقود '),
(28389, 'Proverbs', 20, 6, 11, ' فيأتي فقرك كساع وعوزك كغاز '),
(28390, 'Proverbs', 20, 6, 12, ' الرجل اللئيم ، الرجل الأثيم يسعى باعوجاج الفم '),
(28391, 'Proverbs', 20, 6, 13, ' يغمز بعينيه . يقول برجله . يشير بأصابعه '),
(28392, 'Proverbs', 20, 6, 14, ' في قلبه أكاذيب . يخترع الشر في كل حين . يزرع خصومات '),
(28393, 'Proverbs', 20, 6, 15, ' لأجل ذلك بغتة تفاجئه بليته . في لحظة ينكسر ولا شفاء '),
(28394, 'Proverbs', 20, 6, 16, ' هذه الستة يبغضها الرب ، وسبعة هي مكرهة نفسه '),
(28395, 'Proverbs', 20, 6, 17, ' عيون متعالية ، لسان كاذب ، أيد سافكة دما بريئا '),
(28396, 'Proverbs', 20, 6, 18, ' قلب ينشئ أفكارا رديئة ، أرجل سريعة الجريان إلى السوء '),
(28397, 'Proverbs', 20, 6, 19, ' شاهد زور يفوه بالأكاذيب ، وزارع خصومات بين إخوة '),
(28398, 'Proverbs', 20, 6, 20, ' يا ابني ، احفظ وصايا أبيك ولا تترك شريعة أمك '),
(28399, 'Proverbs', 20, 6, 21, ' اربطها على قلبك دائما . قلد بها عنقك '),
(28400, 'Proverbs', 20, 6, 22, ' إذا ذهبت تهديك . إذا نمت تحرسك ، وإذا استيقظت فهي تحدثك '),
(28401, 'Proverbs', 20, 6, 23, ' لأن الوصية مصباح ، والشريعة نور ، وتوبيخات الأدب طريق الحياة '),
(28402, 'Proverbs', 20, 6, 24, ' لحفظك من المرأة الشريرة ، من ملق لسان الأجنبية '),
(28403, 'Proverbs', 20, 6, 25, ' لا تشتهين جمالها بقلبك ، ولا تأخذك بهدبها '),
(28404, 'Proverbs', 20, 6, 26, ' لأنه بسبب امرأة زانية يفتقر المرء إلى رغيف خبز ، وامرأة رجل آخر تقتنص النفس الكريمة '),
(28405, 'Proverbs', 20, 6, 27, ' أيأخذ إنسان نارا في حضنه ولا تحترق ثيابه '),
(28406, 'Proverbs', 20, 6, 28, ' أو يمشي إنسان على الجمر ولا تكتوي رجلاه '),
(28407, 'Proverbs', 20, 6, 29, ' هكذا من يدخل على امرأة صاحبه . كل من يمسها لا يكون بريئا '),
(28408, 'Proverbs', 20, 6, 30, ' لا يستخفون بالسارق ولو سرق ليشبع نفسه وهو جوعان '),
(28409, 'Proverbs', 20, 6, 31, ' إن وجد يرد سبعة أضعاف ، ويعطي كل قنية بيته '),
(28410, 'Proverbs', 20, 6, 32, ' أما الزاني بامرأة فعديم العقل . المهلك نفسه هو يفعله '),
(28411, 'Proverbs', 20, 11, 7, ' عند موت إنسان شرير يهلك رجاؤه ، ومنتظر الأثمة يبيد '),
(28412, 'Proverbs', 20, 11, 8, ' الصديق ينجو من الضيق ، ويأتي الشرير مكانه '),
(28413, 'Proverbs', 20, 11, 9, ' بالفم يخرب المنافق صاحبه ، وبالمعرفة ينجو الصديقون '),
(28414, 'Proverbs', 20, 11, 10, ' بخير الصديقين تفرح المدينة ، وعند هلاك الأشرار هتاف '),
(28415, 'Proverbs', 20, 11, 11, ' ببركة المستقيمين تعلو المدينة ، وبفم الأشرار تهدم '),
(28416, 'Proverbs', 20, 11, 12, ' المحتقر صاحبه هو ناقص الفهم ، أما ذو الفهم فيسكت '),
(28417, 'Proverbs', 20, 11, 13, ' الساعي بالوشاية يفشي السر ، والأمين الروح يكتم الأمر '),
(28418, 'Proverbs', 20, 11, 14, ' حيث لا تدبير يسقط الشعب ، أما الخلاص فبكثرة المشيرين '),
(28419, 'Proverbs', 20, 11, 15, ' ضررا يضر من يضمن غريبا ، ومن يبغض صفق الأيدي مطمئن '),
(28420, 'Proverbs', 20, 11, 16, ' المرأة ذات النعمة تحصل كرامة ، والأشداء يحصلون غنى '),
(28421, 'Proverbs', 20, 11, 17, ' الرجل الرحيم يحسن إلى نفسه ، والقاسي يكدر لحمه '),
(28422, 'Proverbs', 20, 11, 18, ' الشرير يكسب أجرة غش ، والزارع البر أجرة أمانة '),
(28423, 'Proverbs', 20, 11, 19, ' كما أن البر يؤول إلى الحياة كذلك من يتبع الشر فإلى موته '),
(28424, 'Proverbs', 20, 11, 20, ' كراهة الرب ملتوو القلب ، ورضاه مستقيمو الطريق '),
(28425, 'Proverbs', 20, 11, 21, ' يد ليد لا يتبرر الشرير ، أما نسل الصديقين فينجو '),
